INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Iesākumā Dievs radīja debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Un zeme bija tumša un tukša, un tumsa bija pār dziļumiem, un Dieva Gars lidinājās pa ūdeņu virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Un Dievs sacīja: Lai top gaisma. Tad tapa gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Un Dievs redzēja gaismu labu esam. Un Dievs šķīra gaismu no tumsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Un Dievs nosauca gaismu par dienu, un tumsu Viņš nosauca par nakti. Un tapa vakars un tapa rīts, pirmā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Tad Dievs sacīja: Lai top izplatījums ūdeņu starpā un lai tas šķir ūdeni no ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Un Dievs darīja izplatījumu, un darīja starpu to ūdeni, kas izplatījuma apakšā, un to ūdeni, kas izplatījuma virsū; un tā notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Un Dievs nosauca izplatījumu par debesi. Un tapa vakars un tapa rīts, otra diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Tad Dievs sacīja: Lai ūdens debess apakšā krājās vienā vietā, ka sausums top redzams; un tā notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Un Dievs nosauca sausumu par zemi, un to ūdeņu krājumu Viņš nosauca par jūru. Un Dievs redzēja to labu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Un Dievs sacīja: Lai zeme izdod zaļumu un zāli, kas savu sēklu nes, auglīgus kokus, kas augļus nes pēc savas kārtas, kam sava sēkla iekš sevis ir virs zemes; un tā notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Un zeme izdeva zaļumu un zāli, kas savu sēklu nes pēc savas kārtas, un kokus, kas augļus nes, kam sava sēkla iekš sevis pēc savas kārtas. Un Dievs redzēja to labu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Un tapa vakars un tapa rīts, trešā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Tad Dievs sacīja: Lai top spīdekļi debess izplatījumā, kas šķir dienu no nakts un kas dod zīmes un laikus un dienas un gadus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Un lai tie ir par spīdekļiem debess izplatījumā un spīd virs zemes; un tā notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Un Dievs darīja divus lielus spīdekļus, lielāko spīdekli, dienu valdīt un mazāko spīdekli, naktī valdīt, - un zvaigznes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Un Dievs tos lika debess izplatījumā, lai tie spīd uz zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Un valda dienu un nakti un šķir gaismu no tumsas. Un Dievs redzēja to labu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Un tapa vakars un tapa rīts, ceturtā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Tad Dievs sacīja: Lai pa pulkiem rodas ūdenī kustošas dzīvas dvašas un putni, kas virs zemes skrien apakš debess izplatījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Un Dievs radīja lielus jūras zvērus un visādas dzīvas dvašas, kas lien, ko ūdens pa pulkiem izdod pēc viņu kārtām, un visādus spārnainus putnus pēc viņu kārtas. Un Dievs redzēja to labu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Un Dievs tos svētīja sacīdams: Vaislojaties un vairojaties un piepildiet ūdeni jūrā, un putni lai vairojās virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Un tapa vakars un tapa rīts, piektā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Tad Dievs sacīja: Lai zeme izdod dzīvas dvašas pēc viņu kārtas, lopus, tārpus un zemes zvērus pēc viņu kārtas; un tā notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Un Dievs darīja zemes zvērus pēc viņu kārtas un lopus pēc viņu kārtas un visādus zemes tārpus pēc viņu kārtas. Un Dievs redzēja to labu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Un Dievs sacīja: Darīsim cilvēkus pēc mūsu ģīmja, pēc mūsu līdzības, lai tie valda pār zivīm jūrā un pār putniem apakš debess un pār lopiem un pār visu zemi un pār visiem tārpiem, kas lien virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Un Dievs radīja cilvēku pēc Sava ģīmja, pēc Dieva ģīmja Viņš to radīja, un radīja tos, vīrieti un sievieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Un Dievs tos svētīja, un Dievs uz tiem sacīja: Augļojaties un vairojaties un piepildiet zemi un pārvaldiet to un valdat pār zivīm jūrā un pār putniem apakš debess un pār visām dvašām, kas lien virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Un Dievs sacīja: Redzi, Es jums esmu devis visādu zāli, kas nes sēklu, kas ir pa visu zemes virsu, un visus kokus, kam savi augļi iekš sevis un kas nes sēklu, jums par ēdamo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Un visiem zvēriem virs zemes un visiem putniem apakš debess un visiem tārpiem virs zemes, kam dzīva dvaša, esmu devis visādu zaļu zāli par barību. Un tā notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Un Dievs uzlūkoja visu, ko Viņš bija darījis, un redzi, tas bija ļoti labs. Un tapa vakars un tapa rīts, sestā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Tā ir pabeigtas debesis un zeme un viss viņu spēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Un Dievs pabeidza septītā dienā Savu darbu, ko bija darījis, un dusēja septītā dienā no visa Sava darba, ko bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Un Dievs svētīja to septīto dienu un to iesvētīja, tāpēc ka Viņš bija dusējis no visa Sava darba, ko Dievs bija radījis un taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Tā debesis un zeme cēlušās, kad tās tapa radītas tai laikā, kad Dievs Tas Kungs zemi un debesis darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Un vēl nekādu krūmu nebija laukā virs zemes, un vēl nekāda zāle nezēla, jo Dievs Tas Kungs vēl nebija licis lietum līt virs zemes, un cilvēka nebija, kas zemi būtu kopis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Bet migla cēlās no zemes un slapināja visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Un Dievs Tas Kungs taisīja cilvēku no zemes pīšļiem un iepūta viņa nāsīs dzīvības dvašu; tad cilvēks tapa par dzīvu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Un Dievs Tas Kungs stādīja dārzu Ēdenē pret rītiem un iecēla tur to cilvēku, ko Viņš bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Un Dievs Tas Kungs izaudzināja no zemes visādus kokus, kas jauki bija uzlūkot un labi ēst, un dzīvības koku dārza vidū, arī laba un ļauna atzīšanas koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Un tekošs ūdens iztecēja no Ēdenes, to dārzu slapināt, un no turienes tas dalījās un palika par četrām upēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Pirmai ir vārds Pīšone: tā iet ap visu Havilas zemi, kur zelts ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Un tās zemes zelts ir labs; tur ir arī bedellions un sardonika(oniksa) akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Un otrai upei ir vārds Ģihone; tā tek ap visu Kuša(Moru) zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Un trešai upei ir vārds Hideķele; tā tek Assura zemei pret rītiem, un ceturtā upe ir Eifrate.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Un Dievs Tas Kungs ņēma cilvēku un to ielika Ēdenes dārzā, lai tas to koptu un sargātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Un Dievs Tas Kungs pavēlēja cilvēkam sacīdams: no visiem dārza augļiem tu vari ēst, kā tīk,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Bet no tā laba un ļauna atzīšanas koka, no tā tev nebūs ēst, jo kurā dienā tu no tā ēdīsi, tu mirdams mirsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Un Dievs Tas Kungs sacīja: nav labi, cilvēkam būt vienam; Es tam darīšu palīgu, kas ap to būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Un Dievs Tas Kungs no zemes bija taisījis visus zvērus laukā un visus putnus apakš debess; un Viņš tos veda pie cilvēka, lai redzētu, kā tas tos nosauks, un kā cilvēks nosauktu ikvienu dzīvu dvašu, tā lai būtu viņas vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Tad cilvēks nosauca vārdus visiem lopiem un putniem apakš debess un visiem zvēriem laukā, bet priekš cilvēka neatradās palīgs, kas ap to būtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Tad Dievs Tas Kungs cilvēkam sūtīja cietu miegu, un tas aizmiga. Un Viņš ņēma vienu no viņa sānkauliem un aizpildīja to vietu ar miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Un Dievs Tas Kungs iztaisīja to sānkaulu, ko no cilvēka bija ņēmis, par sievu un pieveda to pie cilvēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Un cilvēks sacīja: šī nu ir kauls no maniem kauliem un miesa no manas miesas, tā taps saukta sieva(vīrene), tāpēc ka tā no vīra ir ņemta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Tādēļ vīrs atstās savu tēvu un savu māti un pieķersies pie savas sievas, un tie būs viena miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Un tie abi bija pliki, cilvēks un viņa sieva, un nekaunējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Un čūska bija gudrāka uz viltu nekā visi zvēri laukā, ko Dievs Tas Kungs bija radījis, un tā sacīja uz sievu: vai tad Dievs ir sacījis: jums nebūs ēst no neviena koka dārzā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Tad sieva sacīja uz čūsku: mēs ēdam no koku augļiem dārzā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Bet par tā koka augļiem, kas dārza vidū, Dievs ir sacījis: neēdiet no tā un neaizskariet to, ka jūs nemirstat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Un čūska sacīja uz sievu: mirt nemirsiet vis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Bet Dievs zin, ka, kurā dienā jūs no tā ēdīsiet, tad jūsu acis taps atvērtas, un jūs būsiet itin kā Dievs, zinādami labu un ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Un sieva redzēja, ka labi būtu ēst no tā koka, un ka tas acīm jauks un patīkams koks esam, gudru darīt, un tā ņēma no viņa augļiem un ēda un deva arī savam vīram, un viņš ēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Tad viņu abēju acis tapa atvērtas, un tie atzina, ka bija pliki, un sapina vīģes koka lapas un darīja sev priekšautus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Un tie dzirdēja Dieva Tā Kunga balsi, kas dārzā staigāja dienas dzestrumā. Tad Ādams un viņa sieva paslēpās priekš Dieva Tā Kunga apakš kokiem dārzā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Un Dievs Tas Kungs sauca Ādamu un sacīja uz to: Kur tu esi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Un tas sacīja: es dzirdēju Tavu balsi dārzā un bijājos, jo es esmu pliks, un paslēpos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Un Viņš sacīja: kas tev ir teicis, ka tu esi pliks? Vai tu neesi ēdis no tā koka, par ko Es tev pavēlēju, ka tev no tā nebija ēst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Un Ādams sacīja: tā sieva, ko Tu man devis, tā man deva no tā koka, un es esmu ēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Un Dievs Tas Kungs sacīja uz sievu: kam tu to esi darījusi? Un sieva sacīja: čūska mani pievīlusi, un es esmu ēdusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Tad Dievs Tas Kungs sacīja uz čūsku: Tādēļ ka tu to darījusi, esi nolādēta priekš visiem lopiem un priekš visiem zvēriem laukā; uz tava vēdera tev būs iet un pīšļus ēst visu savu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Un Es celšu ienaidu starp tevi un sievu un starp tavu sēklu un viņas sēklu: šis samīs tev galvu, un tu viņam iedursi papēdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Un uz sievu Viņš sacīja: Es vairodams vairošu tavas sāpes un tavas grūtības mokas; ar sāpēm tev būs bērnus dzemdēt, un tavai iegribēšanai būs būt pēc tava vīra, un viņam būs pār tevi valdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Un uz Ādamu Viņš sacīja: tāpēc ka tu esi klausījis savas sievas balsij un ēdis no tā koka, par ko Es tev pavēlēju sacīdams, tev nebūs no tā ēst, - nolādēta lai ir zeme tevis dēļ, ar mokām tev no tās būs uzturēties visu savu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Un ērkšķus un dadžus tā tev izdos, un tev būs ēst lauka augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Ar sava vaiga sviedriem tev būs maizi ēst, tiekams tu atkal topi par zemi, no kā tu esi ņemts, jo tu esi no pīšļiem un tev būs atkal palikt par pīšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Un Ādams nosauca savas sievas vārdu Ieva, tāpēc ka tā ir visu dzīvo māte.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Un Dievs Tas Kungs taisīja Ādamam un viņa sievai uzvalkus no ādām un tiem tos apvilka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Un Dievs Tas Kungs sacīja: redzi, cilvēks ir tapis kā viens no mums, atzīdams labu un ļaunu, un nu, lai tas savu roku neizstiepj un neņem arī no tā dzīvības koka un neēd un nedzīvo mūžīgi, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Tad Dievs Tas Kungs to izdzina no Ēdenes dārza, lai tas to zemi strādātu, no kā bija ņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Un Viņš izmeta cilvēku un lika Ēdenes dārzam pret rītiem ķerubus un cērtama zobena liesmu, lai sargātu ceļu uz dzīvības koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Un Ādams atzina Ievu, savu sievu, un tā tapa grūta un dzemdēja Kainu un sacīja: es esmu dabūjusi vīru ar To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Un tā vēl dzemdēja viņa brāli, Ābelu; un Ābels palika par avju ganu, bet Kains palika par zemes kopēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Un notikās pēc kāda laika, ka Kains Tam Kungam upuri nesa no zemes augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Un Ābels arīdzan nesa no savu avju pirmdzimtiem un no viņu taukiem. Un Tas Kungs uzlūkoja Ābelu un viņa upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Bet Kainu un viņa upuri Viņš neuzlūkoja. Tad iedegās Kaina bardzība, un viņa vaigs raudzījās nikni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Un Tas Kungs sacīja uz Kainu: kam tu esi apskaities, un kādēļ tavs vaigs raugās nikni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Vai nav tā: ja tu darīsi pareizi, tad vari savu vaigu pacelt; bet ja tu darīsi nepareizi, tad grēks guļ priekš durvīm un tīko pēc tevis, - bet tu, valdi pār viņu. Un Kains runāja ar savu brāli Ābelu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Un notikās, kad tie bija laukā, tad Kains cēlās pret Ābelu, savu brāli, un to nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Un Tas Kungs sacīja uz Kainu: kur ir Ābels, tavs brālis? Un tas sacīja: es nezinu. Vai tad es sava brāļa sargs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Un Viņš sacīja: ko tu esi darījis? Tava brāļa asiņu balss brēc uz Mani no zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Un nu esi nolādēts, nost no zemes, kas savu muti atpletusi, tava brāļa asinis saņemt no tavām rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Kad tu zemi strādāsi, tad tā vairs tev nedos savu spēku; tekulis un bēglis tu būsi virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Un Kains sacīja uz To Kungu: mans noziegums ir lielāks, nekā to varētu panest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Redzi, Tu mani šodien izdzen no zemes, un man būs paslēpties no Tava vaiga un es būšu tekulis un bēglis virs zemes, un notiks, ka ikviens, kas mani atrod, tas mani nokaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Un Tas Kungs uz to sacīja: tādēļ, kas Kainu nokauj, tas taps septiņkārt atriebts. Un Tas Kungs pielika Kainam zīmi, lai to nenokautu, kas to atrastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Un Kains aizgāja no Tā Kunga vaiga un mita Nodzemē, Ēdenei pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Un Kains atzina savu sievu, un tā tapa grūta un dzemdēja Ēnohu; un viņš uztaisīja pilsētu un nosauca tās pilsētas vārdu pēc sava dēla vārda Ēnohu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Un Ēnoham dzima Īrads, un Īrads dzemdināja Meūjaēlu, un Meūjaēls dzemdināja Metusaēlu, un Metusaēls dzemdināja Lāmehu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Un Lāmehs apņēma divas sievas; pirmai bija vārds Ada, un otrai bija vārds Cilla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Un Ada dzemdēja Jabalu; tas ir tēvs bijis tiem, kas teltīs dzīvoja un lopus audzināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Un viņa brāļa vārds bija Jubals; tas ir tēvs bijis visiem koklētājiem un stabulniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Un Cilla arīdzan dzemdēja Tubalkaīnu, kas bija visādu vara un dzelzs rīku kalējs. Un Tubalkaīna māsa bija Naēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Un Lāmehs sacīja uz savām sievām: Ada un Cilla, klausiet manu balsi, jūs Lāmeha sievas, ņemiet vērā manus vārdus! Jo es vīru nokauju par savu vāti un jaunekli par savu brūci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Jo Kains taps septiņkārt atriebts, bet Lāmehs septiņdesmit septiņkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Un Ādams atzina atkal savu sievu, un tā dzemdēja dēlu un nosauca viņa vārdu Setu; jo (tā sacīja:) Dievs man ir licis citu dzimumu Ābela vietā, jo Kains to ir nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Un Setam arī dzima dēls, un tas nosauca viņa vārdu Enosu. Tai laikā iesāka piesaukt Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Šie ir Ādama raduraksti. Tai dienā, kad Dievs cilvēku radīja, Viņš to darīja pēc Dieva līdzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Vīrieti un sievieti, Viņš tos radīja un tos svētīja un nosauca tos par cilvēkiem, tai dienā, kad tie tapa radīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Un Ādams dzīvoja simts un trīsdesmit gadus un dzemdināja dēlu pēc savas līdzības, pēc sava ģīmja, un nosauca viņa vārdu Setu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Un Ādama dienas pēc tam, kad Setu bija dzemdinājis, ir astoņsimt gadi, un viņš dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Un visas Ādama dienas, ko viņš dzīvojis, bija deviņsimt un trīsdesmit gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Un Sets bija simts un pieci gadus vecs un dzemdināja Enosu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Un Sets pēc tam, kad Enosu bija dzemdinājis, dzīvoja astoņsimt un septiņus gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Un visas Seta dienas bija deviņsimt un divdesmit gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Un Enos bija deviņdesmit gadus vecs un dzemdināja Kainanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Un Enos dzīvoja pēc tam, kad Kainanu bija dzemdinājis, astoņsimt un piecpadsmit gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Un visas Enosa dienas bija deviņsimt un pieci gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Un Kainans bija septiņdesmit gadus vecs un dzemdināja Mahalaleēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Un Kainans dzīvoja pēc tam, kad Mahalaleēli bija dzemdinājis, astoņsimt un četrdesmit gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Un visas Kainana dienas bija deviņsimt un desmit gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleēls bija sešdesmit un pieci gadus vecs un dzemdināja Jaredu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Un Mahalaleēls dzīvoja pēc tam, kad Jaredu bija dzemdinājis, astoņsimt un trīsdesmit gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Un visas Mahalaleēla dienas bija astoņsimt deviņdesmit un pieci gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Un Jareds bija simts sešdesmit un divus gadus vecs un dzemdināja Enohu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Un Jareds dzīvoja pēc tam, kad Enohu bija dzemdinājis, astoņsimt gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Un visas Jareda dienas bija deviņsimt sešdesmit un divi gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Un Enohs bija sešdesmit un pieci gadus vecs un dzemdināja Metuzalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Un Enohs pēc tam, kad Metuzalu bija dzemdinājis, staigāja ar Dievu trīssimt gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Un visas Enoha dienas bija trīssimt sešdesmit un pieci gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Un Enohs staigāja ar Dievu un viņa vairs nebija, jo Dievs viņu paņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Un Metuzala bija simts astoņdesmit un septiņus gadus vecs un dzemdināja Lāmehu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Un Metuzala dzīvoja pēc tam, kad Lāmehu bija dzemdinājis, septiņsimt astoņdesmit un divus gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Un visas Metuzalas dienas bija deviņsimt sešdesmit un deviņi gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Un Lāmehs bija simts astoņdesmit un divus gadus vecs un dzemdināja dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Un nosauca viņa vārdu Noa, sacīdams: šis mūs iepriecinās mūsu darbos un mūsu mokās, kas nāk no šīs zemes, ko Tas Kungs nolādējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Un Lāmehs dzīvoja pēc tam, kad Nou bija dzemdinājis, piecsimt deviņdesmit un pieci gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Un visas Lāmeha dienas bija septiņsimt septiņdesmit septiņi gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Un Noa bija piecsimt gadus vecs, un dzemdināja Šemu, Hamu un Jafetu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Un notikās, kad cilvēki sāka vairoties virs zemes un tiem meitas piedzima,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Tad Dieva bērni redzēja cilvēku meitas, ka tās bija skaistas, un ņēma sev sievas, kādas tiem patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Un Tas Kungs sacīja: Manam Garam nebūs valdīt iekš cilvēkiem mūžīgi; maldīdamies tie ir miesa; un viņu dienas vēl būs simts un divdesmit gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Tanīs dienās tie milžu vīri bija virs zemes, un arī pēc, kad Dieva bērni bija iegājuši pie cilvēku meitām un sev bērnus bija dzemdinājuši; šie tie varenie, kas bija no iesākuma, slaveni vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Un Tas Kungs redzēja, ka cilvēku ļaunums augtin auga virs zemes, un viss viņu sirdsprāts un padoms tikai ļauns bija vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Tad Tam Kungam palika žēl, ka Viņš cilvēkus virs zemes bija radījis, un tas Viņam rūpēja sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Un Tas Kungs sacīja: Es izdeldēšu no zemes visus tos cilvēkus, ko esmu radījis, cilvēkus līdz ar lopiem, tārpiem un putniem apakš debess, jo Man ir žēl, ka Es tos esmu radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Bet Noa atrada žēlastību priekš Tā Kunga acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Šie ir tie stāsti par Noas cilti: Noa bija taisns, nenoziedzīgs vīrs savā ciltī, un Noa staigāja ar Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Un Noa dzemdināja trīs dēlus: Šemu, Hamu un Jafetu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Un zeme bija samaitāta Dieva priekšā, un zeme bija pilna varasdarbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Un Dievs redzēja zemi, un redzi, tā bija samaitāta; visa miesa bija savu ceļu samaitājusi virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Un Dievs sacīja uz Nou: visas miesas gals ir nācis Manā priekšā; jo zeme ir pilna no viņu varas darbiem, un redzi, Es nomaitāšu tos līdz ar zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Taisi sev šķirstu no priežu koka; ar mājokļiem tev to šķirstu būs taisīt un to apsveķot ar darvu no iekš un āra puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Un tev būs viņu tā taisīt: trīssimt olekšu lai ir tā šķirsta garums, piecdesmit olekšu platums un trīsdesmit olekšu viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Vienu logu tev būs tam šķirstam taisīt; olekts lielumā tev būs to taisīt virsgalā, un durvis tev būs likt viņa sānos; tev būs viņu taisīt ar trim bēniņiem, apakšēju, vidēju un virsēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Jo, redzi, Es vedīšu ūdensplūdus virs zemes, lai nomaitā apakš debess ikvienu miesu, iekš kā ir dzīva dvaša; visiem, kas virs zemes, būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Un Es celšu derību ar tevi, un tev būs iet šķirstā līdz ar saviem dēliem un ar savu sievu un ar savu dēlu sievām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Un no visa, kas dzīvo, no ikvienas miesas, pa diviem no ikvienas kārtas, tev būs ievest šķirstā, lai tie līdz ar tevi paliek dzīvi; tēviņam un mātītei tiem būs būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'No putniem pēc savas kārtas un no lopiem pēc savas kārtas un no visiem zemes tārpiem pēc savas kārtas; pa divi no ikvienas kārtas nāks pie tevis, lai paliktu dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Un ņem pie sevis no visādas barības, ko var ēst, un sakrāj to pie sevis, ka tā tev un viņiem būtu par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Un Noa darīja itin tā, kā Dievs tam bija pavēlējis, - tā viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Un Tas Kungs sacīja uz Nou: ej šķirstā, tu un viss tavs nams, jo tevi Es esmu redzējis Manā priekšā taisnu šinī ciltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'No visādiem šķīstiem lopiem ņem pie sevis pa septiņiem, tēviņu un mātīti, bet no tiem lopiem, kas nešķīsti, pa diviem, tēviņu un mātīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Arī no putniem apakš debess pa septiņiem, tēviņu un mātīti, ka vaisla paliek dzīva pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Jo vēl būs septiņas dienas, tad Es likšu lietum līt virs zemes četrdesmit naktis, un Es izdeldēšu no zemes virsas ikvienu dzīvu radījumu, ko esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Un Noa darīja itin tā, kā Tas Kungs bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Un Noa bija sešsimt gadus vecs, kad ūdensplūdi zemi pārplūda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Tad Noa iegāja šķirstā un līdz ar viņu viņa dēli un viņa sieva un viņa dēlu sievas priekš tiem ūdensplūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'No šķīstiem lopiem un no tiem lopiem, kas nav šķīsti, un no putniem un no visa, kas lien virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Iegāja pa pāriem pie Noas šķirstā, tēviņš un mātīte, (it) kā Dievs Noam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Un notikās pēc septiņām dienām, tad ūdensplūdi nāca virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Sešsimtā Noas dzīvības gadā, otrā mēnesī, septiņpadsmitā mēneša dienā, tai pašā dienā visi lielie bezdibeņa avoti ir pārtrūkuši, un debess logi atvērušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Un lietus nāca virs zemes četrdesmit dienas un četrdesmit naktis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Tai dienā iegāja šķirstā Noa un Šems un Hams un Jafets, Noas dēli, un Noas sieva un viņa trīs vedeklas līdz ar tiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Un arī visādi zvēri pēc savas kārtas un visādi lopi pēc savas kārtas un visādi tārpi, kas lien virs zemes, pēc savas kārtas, un visādi putni pēc savas kārtas, visādi putniņi un visādi spārnaiņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Un tie nāca šķirstā pie Noas pa pāriem no ikvienas miesas, iekš kā bija dzīva dvaša,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Un tie, kas nāca, bija tēviņš un mātīte no visādas miesas un iegāja (it) kā Dievs tam bija pavēlējis, un Tas Kungs aizslēdza aiz viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Tad nāca plūdi virs zemes četrdesmit dienas, un ūdeņi vairojās un pacēla šķirstu un pacēla to no zemes virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Un ūdeņi augtin auga un vairojās ļoti virs zemes, un šķirsts gāja peldu pa ūdens virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Un ūdeņi vairojās pārlieku ļoti virs zemes, un visi augstie kalni visur apakš debesīm tapa pārņemti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Piecpadsmit olekšu augstumā ūdeņi cēlās, un kalni tapa pārņemti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Tad visa miesa apmira, kas virs zemes kustās, no putniem un no visādiem tārpiem, kas lien virs zemes, un visi cilvēki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Viss, kam dzīva gara dvaša bija nāsīs, viss, kas mita sausumā, tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Tad visi dzīvie radījumi tapa izdeldēti virs zemes no cilvēkiem līdz lopiem, līdz tārpiem un līdz putniem apakš debess; bet Noa vien atlikās un kas līdz ar viņu bija šķirstā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Un ūdeņi vairojās virs zemes simts un piecdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Un Dievs pieminēja Nou un visus zvērus un visus lopus, kas līdz ar to bija šķirstā, un Dievs deva vēju virs zemes, un ūdeņi nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Un bezdibeņa avoti un debess logi tapa aizdarīti, un lietus no debess tapa aizturēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Un ūdeņi atgriezās no zemes virsas, šurp un turp tecēdami, un ūdeņi krita pēc simts un piecdesmit dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Un šķirsts nolaidās septītā mēnesī septiņpadsmitā mēneša dienā uz Ararata kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Un ūdeņi notecēja šurp un turp līdz desmitam mēnesim; desmitā mēnesī un pirmā mēneša dienā rādījās kalnu gali.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Un notikās pēc četrdesmit dienām, tad Noa atvēra šķirsta logu, ko viņš bija taisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Un izlaida kraukli, un tas skraidīja šurp un turp, kamēr ūdeņi nosīka no zemes virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Pēc tam viņš izlaida balodi, lai redzētu, vai ūdeņi jau noskrējuši no zemes virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Bet balodis neatrada, kur kāja varētu dusēt, un atgriezās pie viņa šķirstā, jo ūdeņi vēl bija pa visu zemes virsu; un viņš izstiepa savu roku un to satvēra un ņēma pie sevis šķirstā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Un pagaidīja vēl citas septiņas dienas un izlaida atkal balodi no šķirsta ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Un balodis nāca pie viņa ap vakara laiku, un redzi, norauta eļļas koka lapa bija viņa mutē. Tad Noa noprata, ka ūdeņi bija noskrējuši no zemes virsas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Un pagaidīja vēl citas septiņas dienas un izlaida balodi, un tas negriezās vairs atpakaļ pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Un notikās sešsimt pirmajā gadā, pirmā mēnesī, pirmā mēneša (dienā), tad ūdeņi izsīka no zemes virsas, un Noa noņēma šķirsta jumtu un skatījās, un redzi, zemes virsa bija apžuvusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Un otrā mēnesī, divdesmit septītā mēneša dienā, zeme bija nožuvusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Tad Dievs runāja uz Nou sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Izej no šķirsta, tu un tava sieva un tavi dēli un tavas vedeklas līdz ar tevi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Visas dzīvības, kas pie tevis, no ikkatras miesas, no putniem un no lopiem un no visiem līdējiem tārpiem virs zemes, tie lai iziet līdz ar tevi, un lai tie pulkiem rodas un augļojās virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Tad Noa izgāja un līdz ar viņu viņa dēli un viņa sieva un viņa vedeklas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Visi zvēri, visi tārpi un visi putni, viss, kas virs zemes kust, izgāja no šķirsta pēc savām sugām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Un Noa uztaisīja Tam Kungam altāri un ņēma no visiem šķīstiem lopiem un no visiem šķīstiem putniem un upurēja Tam Kungam dedzināmos upurus uz tā altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Un Tas Kungs oda to saldo smaržu un sacīja Savā sirdī: “Es joprojām vairs nenolādēšu zemi cilvēka dēļ, jo cilvēka sirdsprāts ir ļauns no mazām dienām, un Es joprojām vairs negribu samaitāt visu, kas dzīvo, kā esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Kamēr būs dienas virs zemes, nemitēsies sēšana un pļaušana, aukstums un karstums, vasara un ziema, diena un nakts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Un Dievs svētīja Nou un viņa dēlus un sacīja uz tiem: augļojaties un vairojaties un piepildiet zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Lai no jums bīstas un baidās visi zemes zvēri un visi putni apakš debess, un viss, kas kust virs zemes, un visas zivis jūrā; - jūsu rokās tie ir doti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Viss, kas kust un ir dzīvs, lai jums ir par barību, (it) kā to zaļo zāli, visu to Es jums esmu nodevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Tik vien miesu viņas dzīvībā, viņas asinīs, jums nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Un par jūsu dzīvības asinīm (Es) prasīšu, no visiem zvēriem tās gribu prasīt, un no cilvēku rokām, no ikviena rokas, kas ir viņa brālis, (Es) prasīšu cilvēka dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kas cilvēka asinis izlej, tā asinīm caur cilvēkiem būs tapt izlietām, jo Dievs cilvēku radījis pēc Sava ģīmja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Bet jūs augļojaties un vairojaties un rodaties pulkiem virs zemes un vairojaties virs tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Un Dievs runāja uz Nou un uz viņa dēliem pie viņa, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Redzi, Es ceļu Savu derību ar jums un ar jūsu dzimumu pēc jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Un ar ikvienu dzīvu dvašu, kas pie jums, ar putniem, lopiem un visām zemes dzīvībām pie jums; - proti ar visiem, kas no šķirsta izgājuši, ar visām zemes dzīvībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Un Es ceļu Savu derību ar jums: un neviena miesa vairs netaps izdeldēta ūdensplūdos, un plūdi vairs nemaitās zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Un Dievs sacīja: šī ir tā derības zīme, ko Es dodu starp Mani un jums un visām dzīvām dvašām, kas pie jums, uz mūžīgiem laikiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Savu varavīksni padebešos Es esmu licis, un tā būs derības zīme starp Mani un starp zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Un kad Es padebešus vadīšu pār zemi un varavīksne padebešos rādīsies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Tad Es pieminēšu Savu derību, kas ir starp Mani un jums un visām dzīvām dvašām ikvienā miesā. Un ūdensplūdi vairs nenāks, samaitāt nevienu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Tad nu varavīksne būs padebešos, un to uzskatīdams Es pieminēšu to mūžīgo derību starp Dievu un visām dzīvām dvašām ikvienā miesā, kas ir virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Un Dievs sacīja uz Nou: šī ir tā derības zīme, ko esmu iecēlis starp mani un ikvienu miesu, kas virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Un Noas dēli, kas no šķirsta izgāja, bija Šems un Hams un Jafets, un Hams ir Kanaāna tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Šie trīs ir Noas dēli, un no šiem ir visi zemes iedzīvotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Un Noa sāka zemi kopt un stādīt vīna dārzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Un viņš dzēra no vīna un piedzērās un gulēja atsedzies sava dzīvokļa vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Un Hams, Kanaāna tēvs, redzēja sava tēva plikās miesas un pasacīja to saviem diviem brāļiem ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Tad Šems un Jafets ņēma drēbes un lika tās abi uz saviem pleciem, un ačgārni ejot tie apsedza sava tēva plikās miesas, un bija savu vaigu nogriezuši, ka sava tēva plikās miesas neredzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Un Noa uzmodās no sava vīna un dabūja zināt, ko viņa jaunākais dēls viņam bija darījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Un sacīja: nolādēts lai ir Kanaāns: tam būs būt savu brāļu kalpu kalpam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Un viņš sacīja: svētīts lai ir Tas Kungs, Šema Dievs, un Kanaāns lai ir viņa kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Lai Dievs vairo Jafetu, un lai tas mājo Šema dzīvokļos, un Kanaāns lai ir viņa kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Un Noa dzīvoja pēc ūdensplūdiem trīssimt un piecdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Tad visas Noas dienas bija deviņsimt un piecdesmit gadi; un viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Un šie ir Noas dēlu: Zema, Hama un Jafeta dzimumi, un tiem dzima dēli pēc ūdensplūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Jafeta bērni Gomers un Magogs un Madajus un Javans un Tūbals un Mešehs un Tīras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Un Gomera bērni: Aškenas un Rifats un Togarmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Un Javana bērni: Elišus un Taršišs un Ķītim un Dodanim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'No šiem ir atšķīrušās tās pagānu salas savās zemēs, ikviens pēc savas valodas, pēc savām ciltīm, savās tautās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Un Hama bērni ir: Kušs un Micraīm un Puts un Kanaāns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Un Kuša bērni ir: Seba un Havila un Sabta un Raēma un Zabteka. Un Raēmas bērni ir: Šeba un Dedans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Un Kušs dzemdināja Nimrodu; šis sāka varens būt virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Viņš bija varens mednieks Tā Kunga priekšā, tādēļ top sacīts: tā kā Nimrods, varens mednieks Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Un viņa valsts iesākums bija Bābele un Erek un Akad un Kalne Sineārzemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'No šās zemes Assurs ir izgājis un ir uztaisījis Ninivi ar Rehobotu un Kalu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Un Reseni starp Ninivi un Kalu; šī ir tā lielā pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Un Micraīm dzemdināja Ludim un Ānamim un Leabim un Naftuīm');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Un Patrusim un Kasluīm, no kurienes ir izgājuši tie Fīlisti un Kaftori.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Un Kanaānam piedzima Sidons, viņa pirmdzimtais, un Hets');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Un Jebuzi un Amori un Ģirgozi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Un Hivi un Arki un Sini');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Un Arvadi un Cemari un Hamati; un no turienes ir izpletušās Kanaāniešu ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Un Kanaāniešu robežas bija no Sidonas uz Ģerara pusi līdz Gazai, uz Sodomas un Gomoras un Adamas un Ceboīma pusi līdz Lazai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Šie ir Hama bērni pēc savām ciltīm, pēc savām valodām, savās zemēs, savās tautās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Un Šemam arīdzan bērni dzimuši; šis ir visu Ēbera bērnu tēvs, Jafeta vecākais brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Šema bērni bija: Elams un Assurs un Arvaksads un Luds un Arams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Un Arama bērni bija: Ucs un Huls un Ģeters un Mazs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Un Arvaksads dzemdināja Šalu, un Šalus dzemdināja Ēberu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Un Ēberam dzima divi dēli; tā pirmā vārds ir Pelegs, jo viņa laikā zeme dalījās, un viņa brāļa vārds ir Joktans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Un Joktans dzemdināja Almodadu un Šelefu un Hacarmavetu un Jarahu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Un Hadoramu un Uzalu un Diķelu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Un Obalu un Abimaēli un Zebu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Un Ofiru un Havilu un Jobabu: šie visi ir Joktana bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Un viņi mita no Mešas līdz Sefarai uz tiem kalniem pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Šie ir Šema bērni pēc savām ciltīm, pēc savām valodām, savās zemēs, savās tautās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Šīs ir Noas bērnu ciltis pēc saviem radiem savās tautās, un no šiem ir izpletušās tās tautas virs zemes pēc ūdensplūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Un visai pasaulei bija vienāda mēle un vienāda valoda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Un kad tie aizgāja pret rītiem, tad tie atrada klajumu Sineārzemē un tur apmetās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Un sacīja cits uz citu: Iesim, taisīsim ķieģeļus un dedzināt dedzināsim; un tie ķieģeļi tiem bija akmeņu vietā, un zemes piķis tiem bija kaļķu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Un tie sacīja: Iesim, taisīsim sev pilsētu un torni, kura gals debesīs, un celsim sev vārdu, lai neizklīstam pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Tad Tas Kungs nonāca zemē, apraudzīt to pilsētu un to torni, ko tie cilvēku bērni cēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Un Tas Kungs sacīja: redzi, tie ir viena tauta un tiem visiem ir viena valoda, un to viņi iesākuši darīt; un nu tie no nekā nenostāsies, ko tie apņēmušies darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Nolaidīsimies zemē un sajauksim tiem tur viņu valodu, ka lai neviens nesaprot sava tuvākā valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Tad Tas Kungs tos izklīdināja no turienes pa visu zemes virsu, un tie atstājās no pilsētas celšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Tādēļ viņas vārds tapa nosaukts Bābele, jo Tas Kungs tur sajauca visas zemes valodu, un no turienes Tas Kungs tos izklīdināja pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Šie ir Šema dzimumi: Šems bija simts gadus vecs un dzemdināja Arvaksadu, divus gadus pēc ūdensplūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Un Šems dzīvoja pēc tam, kad Arvaksadu bija dzemdinājis, piecsimt gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Un Arvaksads dzīvoja trīsdesmit un piecus gadus un dzemdināja Šalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Un Arvaksads dzīvoja pēc tam, kad Šalu bija dzemdinājis, četrsimt un trīs gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Un Šalus dzīvoja trīsdesmit gadus un dzemdināja Ēberu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Un Šalus dzīvoja pēc tam, kad Ēberu bija dzemdinājis, četrsimt un trīs gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Un Ēbers dzīvoja trīsdesmit un četrus gadus un dzemdināja Pelegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Un Ēbers dzīvoja pēc tam, kad Pelegu bija dzemdinājis, četrsimt un trīsdesmit gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Un Pelegs dzīvoja trīsdesmit gadus un dzemdināja Regu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Un Pelegs dzīvoja pēc tam, kad Regu bija dzemdinājis, divsimt un deviņus gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Un Regus dzīvoja trīsdesmit un divus gadus un dzemdināja Serugu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Un Regus dzīvoja pēc tam, kad Serugu bija dzemdinājis, divsimt un septiņus gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Un Serugs dzīvoja trīsdesmit gadus un dzemdināja Nahoru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Un Serugs dzīvoja pēc tam, kad Nahoru bija dzemdinājis, divsimt gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Un Nahors dzīvoja divdesmit un deviņus gadus un dzemdināja Tāru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Un Nahors dzīvoja pēc tam, kad Tāru bija dzemdinājis, simts deviņpadsmit gadus un dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Un Tārus dzīvoja septiņdesmit gadus un dzemdināja Ābramu, Nahoru un Hāranu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Un šie ir Tārus dzimumi: Tārum dzima Ābrams, Nahors un Hārans, un Hāranam dzima Lats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Bet Hārans nomira priekš sava tēva Tārus savā dzimtenē, iekš Ur Kaldejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Un Ābrams un Nahors apņēma sievas. Ābrama sievas vārds bija Sāraī, un Nahora sievas vārds bija Milka, Hārana meita; Hārans bija Milkas un Jiskas tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Un Sāraī bija neauglīga, un viņai nebija bērna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Un Tārus ņēma Ābramu, savu dēlu, un Latu, Hārana dēlu, sava dēla dēlu, un Sāraī, savu vedeklu, Ābrama, sava dēla, sievu, un ar tiem cēlās un gāja no Ur iekš Kaldejas, ka ietu uz Kanaāna zemi; un tie nāca līdz Hāranai un tur mājoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Un Tārus dienas bija divsimt un pieci gadi, un Tārus nomira Hāranā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Un Tas Kungs sacīja uz Ābramu: izej no savas zemes un no savas dzimtenes un no sava tēva nama uz to zemi, ko Es tev rādīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Un Es tevi darīšu par lielu tautu un tevi svētīšu un darīšu tavu vārdu lielu, un tu būsi par svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Un Es svētīšu tos, kas tevi svētī, un nolādēšu tos, kas tevi lād, un iekš tevis visas ciltis virs zemes taps svētītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Un Ābrams aizgāja, kā Tas Kungs tam bija sacījis, un Lats gāja tam līdz. Un Ābrams bija septiņdesmit un pieci gadus vecs, kad viņš no Hāranas izgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Un Ābrams ņēma Sāraī, savu sievu, un Latu, savu brālēnu, un visu savu mantu, ko tie bija mantojuši, un tās dvēseles, ko tie Hāranā bija dabūjuši, un tie izgāja, ka ietu uz Kanaāna zemi, un tie nonāca Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Un Ābrams pārstaigāja to zemi līdz Šehemes vietai, līdz Mores ozolam; un Kanaānieši bija to laiku tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Tad Tas Kungs parādījās Ābramam un sacīja: tavam dzimumam Es došu šo zemi; un viņš tur uztaisīja altāri Tam Kungam, kas viņam bija parādījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Un no turienes viņš cēlās uz tiem kalniem Bētelei pret rītiem, un uzcēla savu telti, ka Bētele bija pret vakariem un Aja pret austruma pusi, un uztaisīja tur Tam Kungam altāri un piesauca Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Un Ābrams cēlās un gāja iedams uz dienvidu(Negebu) pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Un tanī zemē bija bads, un Ābrams nogāja uz Ēģipti, tur mist, jo tas bads bija grūts tanī zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Un notikās, kad bija nonācis tuvu pie Ēģiptes, tad viņš sacīja uz Sāraī, savu sievu: redzi, es zinu, ka tu no vaiga esi skaista sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Un kad ēģiptieši tevi redzēs, tad tie sacīs: šī ir viņa sieva, - un mani nokaus, un tevi atstās dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Saki jel, ka tu mana māsa, lai man labi klājās tevis dēļ, un mana dvēsele tevis dēļ paliek dzīva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Kad nu Ābrams nāca Ēģiptes zemē, tad ēģiptieši redzēja to sievu, ka tā bija ļoti skaista.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Un Faraona lielkungi viņu redzēja, un to slavēja Faraona priekšā, un tā sieva tapa ņemta Faraona namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Un šis Ābramam darīja labu viņas dēļ; un tam bija avis un vērši un ēzeļi un kalpi un kalpones un ēzeļa mātes un kamieļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Bet Tas Kungs mocīja Faraonu un viņa namu ar lielām mocībām, Sāraī, Ābrama sievas, dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Tad Faraons aicināja Ābramu un sacīja: kam tu man to esi darījis? Kāpēc tu man neesi sacījis, ka šī tava sieva?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Kāpēc tu sacīji, ka šī tava māsa? Jo es viņu sev ņēmu par sievu. Un nu redzi, še tava sieva, ņem viņu un ej.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Un Faraons pavēlēja par viņu saviem vīriem, un tie to izvadīja un viņa sievu un visu, kas tam bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Tad Ābrams aizgāja no Ēģiptes uz (Kanaāna) dienvidus zemi, viņš ar savu sievu un ar visu, kas viņam bija, un Lats līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Un Ābrams bija ļoti bagāts ar lopiem, ar sudrabu un ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Un viņš gāja savu ceļu no dienvidus zemes uz Bēteli līdz tai vietai, kur iesākumā viņa telts bija starp Bēteli un starp Aju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Līdz tā altāra vietai, ko viņš iesākumā bija cēlis; un Ābrams tur piesauca Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Un Latam, kas Ābramam gāja līdz, bija arīdzan avis un vērši un teltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Un tā zeme tos nepanesa, ka varētu kopā dzīvot, jo viņu manta bija liela, un tie nevarēja kopā dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Un strīdus cēlās starp Ābrama lopu ganiem un Lata lopu ganiem; un Kanaānieši un Ferezieši dzīvoja tolaik tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Tad Ābrams sacīja uz Latu: lūdzams, lai jel strīdus nav starp mani un tevi, un starp maniem ganiem un taviem ganiem, jo mēs esam brāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Vai visa zeme nav tavā priekšā? Atšķiries jel no manis; ja tu gribi pa kreiso roku, tad es gribu pa labo, bet ja tu gribi pa labo roku, tad es iešu pa kreiso.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Un Lats pacēla savas acis un redzēja visu Jardānes apgabalu, ka tas bija bagāts ar ūdeni, (pirms nekā Tas Kungs Sodomu un Gomoru izpostīja), tā kā Tā Kunga dārzs, itin kā Ēģiptes zeme, kamēr nāk līdz Coārai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Tad Lats izredzējās visu Jardānes apgabalu, un Lats aizgāja pret rītiem, un tie šķīrās viens no otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Ābrams dzīvoja Kanaāna zemē, un Lats dzīvoja Jardānes apgabala pilsētās un cēla savas teltis līdz Sodomai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Bet Sodomieši bija ļauni un ļoti grēcīgi pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Un Tas Kungs sacīja uz Ābramu, kad Lats no viņa bija šķīries: pacel jel savas acis un lūko no tās vietas, kur tu esi, uz ziemeļa pusi un uz dienvidiem un uz rītiem un uz jūru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Jo visu to zemi, ko tu redzi, Es došu tev un tavam dzimumam mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Un Es darīšu tavu dzimumu tā kā zemes pīšļus, ja kas varēs izskaitīt zemes pīšļus, tas varēs izskaitīt arī tavu dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Celies, pārstaigā to zemi krustām šķērsām, jo tev Es to gribu dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Un Ābrams cēla teltis un nāca un dzīvoja starp Mamres ozoliem pie Hebrones, un uztaisīja tur Tam Kungam altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Un notikās Amrafela, Sineāras ķēniņa, Arioka, Elasaras ķēniņa, Ķedorlaomera, Elama ķēniņa, un Tideāla, Gojimu ķēniņa, laikā -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Tie karoja pret Beru, Sodomas ķēniņu, un pret Biršu, Gomoras ķēniņu, Sineabu, Adamas ķēniņu, un Semeberu, Ceboīma ķēniņu, un Belas, tas ir Coāras ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Šie visi sapulcējās Sidim ielejā, tā ir tā Sāls jūra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Divpadsmit gadus tie bija kalpojuši Ķedorlaomeram, un trīspadsmitā gadā tie atkrita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Un četrpadsmitā gadā Ķedorlaomers nāca un tie ķēniņi, kas līdz ar viņu bija, un sakāva tos Refaīm iekš Astarot-Karnaīm un tos Hauzim Amā, un tos Emim Kiriataīm ielejā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Un tos Horiešus uz viņu Seīra kalniem līdz Ēl-Param, kas pie tuksneša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Un tie griezās atpakaļ un nāca pie Mišpata avota, tas ir Kādeša, un sakāva visu Amalekiešu apgabalu un arī Amoriešus, kas dzīvoja Acecon-Tamarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Tad izgāja Sodomas ķēniņš un Gomoras ķēniņš un Adamas ķēniņš un Ceboīma ķēniņš un Belas, tas ir Coāras, ķēniņš, un taisījās pret tiem kauties Sidim ielejā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Pret Ķedorlaomeru, Elama ķēniņu, un Tideālu, Gojimu ķēniņu, un Amrafeli, Sineāras ķēniņu, un Arioku, Elasaras ķēniņu: - četri ķēniņi pret pieciem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Un Sidim ielejā bija daudz zemes piķa bedres; tad Sodomas un Gomoras ķēniņi bēga un tur iekrita, un tie atlikušie aizbēga kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Un tie paņēma visu Sodomas un Gomoras mantu un visu viņu barību un aizgāja projām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Un paņēma arī Latu, Ābrama brālēnu, un viņa mantu, jo tas dzīvoja Sodomā, - un aizgāja projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Tad nāca viens, kas bija izmucis, un pasacīja to Ābramam, tam Ebrejam; tas dzīvoja starp tiem ozoliem, kas piederēja tam Amorietim Mamre, Eškola un Anera brālim; šie bija Ābrama derības biedri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Un Ābrams dzirdējis, savu brāli esam aizvestu cietumā, apbruņojās ar saviem kalpiem, kas viņa namā bija dzimuši, trīssimt un astoņpadsmit, un dzinās tiem pakaļ līdz Danam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Un viņš dalījās un uzbruka tiem naktī, viņš un viņa kalpi, un tos sakāva un dzinās tiem pakaļ līdz Hobai, kas Damaskum pa kreiso roku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Un atveda atpakaļ visu mantu, un arī Latu, savu brāli, un viņa mantu viņš atveda atpakaļ, ir tās sievas un tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Un kad viņš atpakaļ nāca no kaušanās ar Kedorlaomeru un ar tiem ķēniņiem, kas pie tā bija, tad Sodomas ķēniņš izgāja viņam pretī līdz Šaves ielejai, - tā ir tā ķēniņa ieleja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Un Melhizedeks, Salemes ķēniņš, iznesa maizi un vīnu, un tas bija priesteris Dievam tam visu augstajam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Un tas viņu svētīja un sacīja: svētīts lai ir Ābrams no tā visu augstā Dieva, kam pieder zeme un debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Un svētīts lai ir tas visu augstais Dievs, kas tavus ienaidniekus nodevis tavā rokā. Un Ābrams tam deva desmito tiesu no visām lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Un Sodomas ķēniņš sacīja uz Ābramu: dod man tos ļaudis, un to mantu ņem sev.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Un Ābrams sacīja uz Sodomas ķēniņu: es savu roku paceļu uz To Kungu, to visaugsto Dievu, kam debess un zeme pieder, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Nevienu pavedienu, nedz kurpes siksnu, nedz citu ko es neņemšu no visa tā, kas tev pieder, lai tu nesaki: es Ābramu esmu darījis bagātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Tik vien to, ko tie jaunekļi apēduši, un to vīru daļu, kas man gājuši līdz, Aners, Eškols un Mamre, tie lai ņem savu daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Pēc šīm lietām Tā Kunga vārds notika uz Ābramu iekš parādīšanās sacīdams: Nebīsties, Ābram; Es tev esmu par priekšturamām bruņām, un tava alga ir ļoti liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Tad Ābrams sacīja: Kungs, Dievs, ko Tu man dosi? Es aizeju bez bērniem un mana nama mantinieks ir šis Eliēzers no Damaskus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Un Ābrams sacīja: redzi, man Tu neesi dzimumu devis, un redzi, manas saimes bērns būs mans mantinieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Un redzi, Tā Kunga vārds notika uz viņu sacīdams: šis nebūs tavs mantinieks, bet kas no tavām miesām nāks, tas būs tavs mantas ņēmējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Un Viņš to izveda ārā un sacīja: skaties uz debesīm un skaiti zvaigznes; vai tu tās vari izskaitīt? Un Viņš tam sacīja: tāpat būs tavs dzimums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Un Ābrams ticēja uz To Kungu, un Viņš tam to pielīdzināja par taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Un Viņš tam sacīja: Es esmu Tas Kungs, kas tevi izvedis no Ur iekš Kaldejas, ka tev dotu šo zemi iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Un tas sacīja: Kungs, Dievs, pie kam nopratīšu, ka es to iemantošu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Un Viņš tam sacīja: dabū Man treju gadu gotiņu un treju gadu kazu un treju gadu aunu un vienu ūbeli un vienu jaunu balodi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Un tas Viņam dabūja visus tos un dalīja tos vidū uz pusēm un lika ikkatra daļu vienu pret otru, bet tos putnus viņš nedalīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Un vanagi krita uz tām, un Ābrams tos nodzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Un kad saule nogāja, tad Ābramam ciets miegs uznāca, un redzi, izbailes un liela tumsība tam uzkrita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Un Viņš sacīja uz Ābramu: zini zinādams, ka tavs dzimums piemitīs kādā zemē, kas tam nepieder, un tur viņus kalpinās un tiem grūti darīs četrsimt gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Bet to tautu, kam tie kalpos, Es arī sodīšu, un pēc tam tie izies ar lielu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Un tu aiziesi pie saviem tēviem mierā un tapsi aprakts labā vecumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Un ceturtā mūža augums nāks atkal šai vietā, jo Amoriešu netaisnība līdz šim vēl nav pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Un notikās, kad saule nogāja un tumsa metās, tad redzi, dūmains ceplis un uguns liesma, kas cauri šāvās tiem upura gabaliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Tanī dienā Tas Kungs cēla derību ar Ābramu, sacīdams: tavam dzimumam Es esmu devis šo zemi, no Ēģiptes upes līdz lielai Eifrat upei;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Keniešus un Ķenaziešus un Kadmoniešus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Hetiešus un Fereziešus un Refaīmiešus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Un Amoriešus un Kanaāniešus, Ģirgoziešus un Jebusiešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Un Sāraī, Ābrama sieva, tam nedzemdēja, un tai bija kalpone no Ēģiptes, Hāgare vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Un Sāraī sacīja uz Ābramu: redzi, Tas Kungs man ir liedzis dzemdēt, ej jel pie manas kalpones, vai es caur viņu nemantotu dzimumu. Un Ābrams klausīja Sāraī balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Tad Sāraī, Ābrama sieva, ņēma Hāgari, to Ēģiptieti, savu kalponi, kad Ābrams desmit gadus bija dzīvojis Kanaāna zemē, un deva to par sievu Ābramam, savam vīram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Un viņš gāja pie Hāgares, un tā tapa grūta. Kad nu tā redzēja, ka bija grūta, tad viņas valdniece bija nicināta viņas acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Tad Sāraī sacīja uz Ābramu: tu dari nepareizi; savu kalponi es esmu devusi tavā klēpī, un nu viņa redz sevi grūtu esam, un es esmu nicināta viņas acīs; Tas Kungs lai tiesā starp mani un tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Un Ābrams sacīja uz Sāraī: redzi, tava kalpone ir tavā rokā, dari tai, kā tev patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Un Sāraī to pārmācīja, un tā aizbēga no viņas; un Tā Kunga eņģelis to atrada pie ūdens akas tuksnesī, pie tās akas uz Šuras ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Un tas sacīja: Hāgare, Sāraī kalpone, no kurienes tu nāci un uz kurieni tu ej? Un tā sacīja: es bēgu no savas valdnieces Sāraī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Tad Tā Kunga eņģelis tai sacīja: griezies atpakaļ pie savas valdnieces un pazemojies apakš viņas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Un Tā Kunga eņģelis uz to sacīja: Es vairodams vairošu tavu dzimumu, un to neskaitīs liela pulka dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Un Tā Kunga eņģelis uz to sacīja: redzi, tu esi grūta un dzemdēsi dēlu; nosauc viņa vārdu Ismaēls, tāpēc ka Tas Kungs tavas bēdas paklausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Un tas būs cilvēks kā meža ēzelis; viņa roka būs pret ikkatru, un ikkatra roka pret viņu, un viņš dzīvos visu savu brāļu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Un tā nosauca Tā Kunga vārdu, kas ar viņu bija runājis: Tu esi tas stiprais Dievs, kas mani redz; jo tā sacīja: vai es šeit gan neesmu pakaļ skatījusies Tam, kas mani uzlūkojis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Tāpēc to aku sauc par Beer Lekai-Roī (tas ir: par dzīvā aku, kas mani uzlūko); redzi, tā ir starp Kādešu un Baredu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Un Hāgare dzemdēja Ābramam dēlu, un Ābrams nosauca savu dēlu, ko Hāgare tam bija dzemdējusi, par Ismaēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Un Ābrams bija astoņdesmit un sešus gadus vecs, kad Hāgare viņam Ismaēli dzemdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Un Ābrams bija deviņdesmit un deviņus gadus vecs, tad Tas Kungs Ābramam parādījās un uz to sacīja: Es esmu tas visuvarenais Dievs, staigā Manā priekšā un esi taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Un Es celšu derību starp Mani un tevi, un Es tevi vairodams vairošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Tad Ābrams nometās uz savu vaigu, un Dievs runāja ar to sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Redzi, Es esmu cēlis Savu derību ar tevi, un tu būsi par tēvu daudz ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Un tavam vārdam nebūs vairs sauktam tapt Ābramam, bet Ābrahāms lai ir tavs vārds; jo Es tevi esmu licis par tēvu daudz ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Un Es tevi darīšu varen ļoti auglīgu un celšu no tevis tautas, un ķēniņiem būs nākt no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Un Es uzcelšu Savu derību starp Mani un tevi un tavu dzimumu pēc tevis viņu bērnu bērniem par mūžīgu derību, tā ka Es būšu par Dievu tev un tavam dzimumam pēc tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Un tev un tavam dzimumam pēc tevis Es došu tavas svešniecības zemi, visu Kanaāna zemi mūžam paturēt, un Es tiem būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Un Dievs sacīja uz Ābrahāmu: tev būs Manu derību turēt, tev un tavam dzimumam pēc tevis uz bērnu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Šī ir mana derība, ko jums būs turēt starp mani un tevi un starp tavu dzimumu pēc tevis: ikkatram vīrietim jūsu starpā būs tapt apgraizītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Un jums būs apgraizīt priekšādu pie savām miesām un lai tas ir par derības zīmi starp Mani un jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Un astoņas dienas vecu jums būs apgraizīt ikvienu no vīriešu kārtas jūsu pēcnākamos, to, kas namā dzimis, un to, kas par naudu pirkts, no jebkura svešinieka, kas nav no jūsu dzimuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Tiešām to būs apgraizīt, kas tavā namā dzimis un kas par naudu ir pirkts, un Mana derība pie jūsu miesām lai ir par mūžīgu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Un neapgraizīts vīrietis, kas netiks apgraizīts savas miesas priekšādā: tā dvēsele taps izdeldēta no saviem ļaudīm; jo tā ir pārkāpusi Manu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Un Dievs sacīja uz Ābrahāmu: tev nebūs savas sievas Sāraī vārdu saukt Sāraī, bet viņas vārds lai ir Sāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Jo Es viņu svētīšu un arī no viņas tev došu dēlu, un Es viņu svētīšu, ka tai būs palikt par daudz ļaudīm un tautu ķēniņi no viņas celsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Un Ābrahāms nometās uz savu vaigu un pasmējās un sacīja savā sirdī: vai vienam, kas ir simts gadus vecs, bērns piedzims, un vai Sāra, deviņdesmit gadus veca, dzemdēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Un Ābrahāms sacīja uz Dievu: kaut jel Ismaēls tavā priekšā dzīvotu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Un Dievs sacīja: patiesi, Sāra, tava sieva, tev dzemdēs dēlu, un tev būs viņa vārdu nosaukt Īzaku, un Es uzcelšu Savu derību ar to, par mūžīgu derību viņa dzimumam pēc viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Arī Ismaēla labad Es tevi esmu paklausījis un darīšu viņu auglīgu un vairošu viņu varen ļoti: divpadsmit lielkungi viņam piedzims, un Es viņu celšu par lielu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Bet Savu derību Es uzcelšu ar Īzaku, ko tev Sāra dzemdēs ap šo laiku nākamā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Un Dievs beidza ar to runāt un uzbrauca no Ābrahāma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Tad Ābrahāms ņēma Ismaēli, savu dēlu, un visus savā namā dzimušos un visus par naudu pirktos, visus, kas bija no vīriešu kārtas Ābrahāma saimē, un apgraizīja priekšādas pie viņu miesām tanī pašā dienā, kā Dievs uz viņu bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Un Ābrahāms bija deviņdesmit deviņus gadus vecs, kad priekšāda pie viņa miesas tapa apgraizīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Un Ismaēls, viņa dēls, bija trīspadsmit gadus vecs, kad priekšāda pie viņa miesas tapa apgraizīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Tanī pašā dienā tapa apgraizīti Ābrahāms un viņa dēls Ismaēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Un visi vīri viņa saimē, kas viņa namā bija dzimuši un kas par naudu bija pirkti no svešiniekiem, tie līdz ar viņu tapa apgraizīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Un Tas Kungs viņam parādījās pie Mamres ozoliem, kad viņš sēdēja sava nama durvīs, ap dienas karstumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Un viņš pacēla savas acis un skatījās, un redzi, trīs vīri stāvēja viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Un tos ieraudzījis viņš tiem tecēja pretī no dzīvokļa durvīm un nometās pie zemes un sacīja: Kungs, ja es esmu žēlastību atradis Tavās acīs, tad lūdzams neej garām Savam kalpam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Lai atnes drusciņ ūdens, un mazgājiet savas kājas un apmetaties apakš šī koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Un es dabūšu kādu kumosu maizes, ka jūs atspirdzināt savu sirdi; pēc varat iet; jo tāpēc jūs esat pie sava kalpa nākuši. Un tie sacīja: dari, kā tu esi sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Un Ābrahāms traucās dzīvoklī pie Sāras un sacīja: steidzies, ņem sijātu miltu trīs mērus, samīci un cep karašas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Un Ābrāams notecēja pie lopiem un ņēma vienu mīkstu un labu teļu un deva to puisim, un tas steidzās to sataisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Un viņš ņēma sviestu un pienu un to teļu, ko bija sataisījis, un cēla tiem priekšā un stāvēja pats pie tiem apakš tā koka, un tie ēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Tad tie uz viņu sacīja: kur ir Sāra, tava sieva? Un viņš sacīja: redzi, iekšā dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Un tas sacīja: nāktin Es atnākšu pie tevis ap šo laiku nākamā gadā; un redzi, Sārai, tavai sievai, būs dēls. Un Sāra to dzirdēja dzīvokļa durvīs; jo tās bija aiz viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Bet Ābrahāms un Sāra bija veci un daudz dienas piedzīvojuši, un pie Sāras vairs nebija, kā sievām mēdz būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Tad Sāra pati pie sevis smējās sacīdama: vai tad man izdēdējušai būs kārība, un mans kungs ir vecīgs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Un Tas Kungs sacīja uz Ābrahāmu: kam Sāra smējusies par to sacīdama: vai es tiešām dzemdēšu, veca būdama?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Vai tad kāda lieta Tam Kungam neiespējama? Noliktā laikā Es atnākšu pie tevis nākamā gadā, tad Sārai būs dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Un Sāra liedzās sacīdama: es neesmu smējusies. Jo tai bija bail. Bet Viņš sacīja: nē, tu esi gan smējusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Tad tie vīri no turienes cēlās un griezās uz Sodomu. Un Ābrahāms gāja tiem līdz, tos pavadīdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Un Tas Kungs sacīja: vai man būs slēpt Ābrahāmam, ko gribu darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Jo Ābrahāms būs par lielu un varenu tautu, un iekš viņa visi ļaudis virs zemes taps svētīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Jo Es to esmu atzinis, lai viņš saviem bērniem un savam namam pēc sevis pavēl sargāt Tā Kunga ceļu, darot, kas taisnība un kas tiesa, ka Tas Kungs liktu nākt uz Ābrahāmu, ko Viņš tam runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Un Tas Kungs sacīja: liela brēkšana ir par Sodomu un Gomoru, un viņu grēki ļoti grūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Tad nu Es noiešu un lūkošu, vai tie visnotaļ ir darījuši pēc tās brēkšanas, kas Manā priekšā nākusi, vai ne; to Es gribu zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Un tie vīri griezās no turienes un gāja uz Sodomu; bet Ābrahāms stāvēja vēl Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Un Ābrahāms piegāja un sacīja: vai Tu samaitāsi taisno ar bezdievīgo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Varbūt, ka piecdesmit taisni tai pilsētā, vai Tu tos samaitāsi un to vietu nežēlosi to piecdesmit taisno dēļ, kas viņu starpā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Ne mūžam Tu tā nedarīsi, nonāvēdams taisno līdz ar bezdievīgo, ka taisnais būtu tā kā bezdievīgais; ne mūžam! - vai visas pasaules soģis nedarīs taisni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Tad Tas Kungs sacīja: ja Es Sodomas pilsētā atradīšu piecdesmit taisnus, tad Es žēlošu visu to vietu viņu labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Un Ābrahāms atbildēja un sacīja: redzi jel, es esmu iedrošinājies ar To Kungu runāt, jebšu es esmu pīšļi un pelni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Ja tur piecu trūktu no tiem piecdesmit taisniem, vai šo piecu dēļ Tu samaitātu visu to pilsētu? Un Viņš sacīja: Es to nesamaitāšu, ja tur atradīšu četrdesmit un piecus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Tad tas joprojām runāja uz Viņu un sacīja: ja tur atrastos četrdesmit? Un Viņš sacīja: Es nekā nedarīšu to četrdesmit labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Un tas sacīja: neapskaities, Kungs, lūdzams, ka es vēl runāju: ja tur atrastos trīsdesmit? Un Viņš sacīja: Es to nedarīšu, ja atradīšu trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Un tas sacīja: redzi jel, es esmu iedrošinājies uz To Kungu runāt: ja tur atrastos divdesmit? Un Viņš sacīja: Es nesamaitāšu to divdesmit labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Un tas sacīja: neapskaities, Kungs, lūdzams, ka es vēl vienreiz runāju, - ja tur atrastos desmit? Un Viņš sacīja: Es nesamaitāšu to desmit labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Tad Tas Kungs aizgāja, kad bija beidzis uz Ābrahāmu runāt, un Ābrahāms griezās atpakaļ uz savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Un tie divi eņģeļi vakarā nonāca Sodomā, un Lats sēdēja Sodomas vārtos. Un tos ieraudzījis Lats cēlās un gāja tiem pretī un nometās uz savu vaigu pie zemes');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Un sacīja: redzi, mani kungi, ņemiet lūdzami mājas vietu pie sava kalpa un palieciet šo nakti un mazgājiet savas kājas; tad rītā cēlušies varat iet savu ceļu. Un tie sacīja: nē, bet mēs gribam palikt pa nakti uz ielas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Bet viņš tos lūgdams lūdza, lai tie pie viņa mājotu; un tie iegāja viņa namā, un viņš tiem taisīja mielastu, cepdams neraudzētas karašas, un tie ēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Pirms ne kā tie apgūlās, Sodomas pilsētas ļaudis apstāja to namu, jauni un veci, viss tas pulks no visām malām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Un aicināja Latu un sacīja uz to: kur tie vīri, kas šo nakti pie tevis nākuši? Izved tos pie mums ārā, ka tos atzīstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Tad Lats izgāja pie tiem ārā priekš durvīm, un aizslēdza durvis aiz sevis un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Brāļi, nedariet jel tādu grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Redziet, man ir divas meitas, kas nav atzinušas vīra, tās izvedīšu pie jums, un dariet ar tām, kā patīk, - tikai šiem vīriem nedariet nekā, jo tāpēc tie nākuši mana jumta pavēnī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Tad tie sacīja: atkāpies nost! Un tie sacīja: šis viens ir atnācis kā svešinieks un grib valdīt? Nu tev vairāk ļauna darīsim nekā viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Un mākdamies tie mācās virsū tam vīram, Latam, un nāca durvis uzlauzt. Bet tie vīri izstiepa ārā savu roku un ierāva Latu pie sevis namā un aizslēdza durvis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Un apstulboja tos ļaudis priekš nama durvīm, mazos un lielos, tā ka tie piekusa pēc durvīm grābstīdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Tad tie vīri sacīja uz Latu: vai tev še vēl kāds znots vai dēli vai meitas vai cits kāds, kas tev pieder šai pilsētā, - izved tos no šās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Jo mēs samaitāsim šo vietu, tāpēc ka tā brēkšana par viņu ir liela Tā Kunga priekšā, un Tas Kungs mūs ir sūtījis to samaitāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Un Lats izgāja un runāja uz saviem znotiem, kas viņa meitas gribēja apņemt, un sacīja: ceļaties un ejat ārā no šās vietas, jo Tas Kungs samaitās šo pilsētu. Bet tiem znotiem viņš izlikās tā kā smieklus runājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Un kad gaisma ausa, tad tie eņģeļi Latu skubināja sacīdami: celies, ņem savu sievu un savas divas meitas, kas tev ir, ka tu neietu bojā šīs pilsētas noziegumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Bet viņš kavējās; un tie vīri satvēra viņa roku un viņa sievas roku un viņa divēju meitu roku, tāpēc ka Tas Kungs viņu žēloja, un tie to izveda un to palaida ārpus pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Un kad tie tos bija izveduši ārā, tad viņš sacīja: Izglāb jel savu dzīvību, neskaties atpakaļ un nestāvi nekur šinī klajumā; glābies kalnā, ka neej bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Un Lats sacīja uz tiem: ak nē, Kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Redzi jel, tavs kalps ir atradis žēlastību tavās acīs, un varen liela ir tava žēlošana, ko tu man esi darījis, izglābdams manu dzīvību; bet es nespēju glābties kalna galā, lai man ļaunums neuznāk un es nemirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Redzi jel, šī pilsēta ir tuvu klāt, uz turieni bēgt, un tā ir maza; tur es gribu glābties, - vai tā nav maza? - Ka es palieku dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Un viņš uz to sacīja: redzi, arī šinī lietā es tevi esmu uzlūkojis, ka es nesamaitāšu to pilsētu, par ko tu esi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Steidzies, glābies turp, jo es nekā nevaru darīt, tiekams tu uz turieni neesi nonācis. Tādēļ tās pilsētas vārdu sauc Coāru (t.i. maza).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Saule uzlēca pār zemi, kad Lats nonāca Coārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Un Tas Kungs lika līt sēram un ugunij uz Sodomu un Gomoru no Tā Kunga, no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Un viņš izpostīja tās pilsētas un visu to apgabalu un visus to pilsētu iedzīvotājus, ir zemes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Un viņa sieva skatījās atpakaļ un palika par sālsstabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Un Ābraams cēlās it agri uz to vietu, kur viņš bija stāvējis priekš Tā Kunga vaiga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Un skatījās uz Sodomas un Gomoras pusi un uz visu to apgabalu, un redzi, dūmi cēlās no zemes, tā kā kāda cepļa dūmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Un notikās, kad Dievs šī apgabala pilsētas samaitāja, tad viņš pieminēja Ābrahāmu un izveda Latu no tā posta, kad viņš tās pilsētas izpostīja, kur Lats mita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Un Lats gāja no Coāras uz augšu un mita kalnos, un viņa divas meitas līdz ar viņu; jo viņam bija bail Coārā mist; un viņš dzīvoja kādā alā līdz ar savām abām meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Un tā pirmdzimušā sacīja uz to jaunāko: mūsu tēvs ir vecs, un vīra nav virs zemes, kas pie mums nāktu pēc visas pasaules ieraduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Nāc, dosim savam tēvam vīnu dzert un gulēsim pie tā un paturēsim dzīvu dzimumu no sava tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Un tās deva savam tēvam vīnu dzert tanī naktī, un tā pirmdzimušā nāca un gulēja pie sava tēva, un viņš to nenomanīja, kad tā apgūlās, nedz kad tā cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Un no rīta tā pirmdzimušā sacīja uz to jaunāko: redzi, izgājušo nakti es esmu gulējusi pie sava tēva; dosim viņam arī šo nakti vīnu dzert, tad ieej tu un guli pie tā, ka dzimumu gādājam no sava tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Un tās arī tanī naktī deva savam tēvam vīnu dzert, un tā jaunākā cēlās un gulēja pie tā, un tas nenomanīja, kad tā apgūlās, nedz kad tā cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Un Lata abas meitas tapa grūtas no sava tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Un tā pirmdzimušā dzemdēja dēlu un nosauca viņa vārdu Moabs, šis ir Moabiešu tēvs līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Un tā jaunākā dzemdēja arī dēlu un nosauca viņa vārdu Ben-Ammi: šis ir Amona bērnu tēvs līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Un Ābrahāms no turienes aizgāja uz to zemi pret dienasvidus pusi un dzīvoja starp Kādeš un Šur un piemita Ģerarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Un Ābrahāms sacīja no Sāras, savas sievas: tā ir mana māsa; tad Abimelehs, Ģeraras ķēniņš, sūtīja un paņēma Sāru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Bet Dievs nāca pie Abimeleha sapnī nakts laikā un uz to sacīja: redzi, tev jāmirst tās sievas dēļ, ko tu esi ņēmis, jo tā ir laulāta sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Bet Abimelehs viņu vēl nebija aizskāris; tad tas sacīja: Kungs, vai Tu arī taisnus ļaudis nonāvēsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Vai viņš man nav sacījis: tā ir mana māsa? Un viņa pati arīdzan sacījusi: tas ir mans brālis. Es to esmu darījis vientiesīgu sirdi un šķīstām rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Tad Dievs sapnī uz to sacīja: Es arīdzan zinu, ka to esi darījis savā sirds vientiesībā, un Es tevi arī esmu atturējis, ka tu pret Mani negrēko; tādēļ Es tev neesmu ļāvis viņu aizskart.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Un nu, atdodi tam vīram to sievu, jo tas ir pravietis, un lai viņš priekš tevis lūdz, tad tu dzīvosi; bet ja tu to neatdosi, tad zini, ka tu mirdams mirsi, un viss, kas tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Un no rīta agri Abimelehs cēlās un aicināja visus savus kalpus un runāja visus šos vārdus priekš viņu ausīm, un tie vīri bijājās ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Un Abimelehs aicināja Ābrahāmu un uz to sacīja: kam tu mums to esi darījis, un ko es pret tevi esmu grēkojis, ka tu par mani un par manu valsti vedis tik lielus grēkus? Tu man tā esi darījis, kā nepieklājās darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Un Abimelehs sacīja uz Ābrahāmu: ko tu esi nodomājis to darīdams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Tad Ābrahāms sacīja: es domāju, tiešām Dieva bijāšanas nav šinī vietā, un tie mani nokaus manas sievas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Un tā arī tiešām ir mana māsa, mana tēva meita, bet tik ne manas mātes meita; un tā ir tapusi mana sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Un pēc tam, kad Dievs man licis iziet no mana tēva nama, tad es uz to sacīju: lai šī ir tā žēlastība, ko tu pie manis darīsi: visur, kurp nāksim saki no manis: tas ir mans brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Tad Abimelehs ņēma avis un vēršus un kalpus un kalpones un deva tos Ābrahāmam un atdeva tam arī Sāru, viņa sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Un Abimelehs sacīja: redzi, mana zeme ir tavā priekšā; dzīvo, kur tavām acīm patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Un uz Sāru viņš sacīja: redzi, es tavam brālim esmu devis tūkstoš sudraba gabalus, un, redzi, lai tas tev ir par acu apsegu priekš visiem, kas pie tevis un visur, un tu esi taisnota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Un Ābrahāms pielūdza Dievu, tad Dievs dziedināja Abimeleku un viņa sievu un viņa kalpones, ka tās dzemdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Jo Tas Kungs Abimeleha namā bija cieti aizslēdzis visas mātes, Sāras, Ābrahāma sievas, dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Un Tas Kungs piemeklēja Sāru, (it) kā viņš bija sacījis, un Tas Kungs darīja Sārai, kā bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Un Sāra tapa grūta un dzemdēja Ābrahāmam dēlu viņa vecumā tai noliktā laikā, ko Dievs viņam bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Un Ābrahāms nosauca sava dēla vārdu, kas viņam piedzima, ko Sāra viņam dzemdēja, Īzaku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Un Ābrahāms apgraizīja savu dēlu Īzaku, astoņas dienas vecu, (it) kā Dievs tam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Un Ābrahāms bija simts gadus vecs, kad tam Īzaks, viņa dēls, piedzima.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Un Sāra sacīja: smiešanos Dievs man ir sataisījis; ikkatrs, kas to dzirdēs, par mani smiesies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Un tā sacīja: kas gan Ābrahāmam būtu sacījis, ka Sāra bērnus zīdīs? Jo es esmu dzemdējusi dēlu viņa vecumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Un tas bērns auga un tapa no krūtīm atšķirts, un Ābrahāms darīja lielas dzīres tai dienā, kad Īzaks tapa atšķirts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Un Sāra redzēja Hāgares, tās Ēģiptietes, dēlu, ko tā Ābrahāmam bija dzemdējusi, smējēju esam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Un tā sacīja uz Ābrahāmu: izdzen šo kalponi un viņas dēlu, jo šīs kalpones dēlam nebūs mantot līdz ar manu dēlu, ar Īzaku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Un tas vārds Ābrahāmam ļoti rieba sava dēla dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Bet Dievs sacīja uz Ābrahāmu: lai tas tev neriebj tā puiša un tās kalpones dēļ. Visu, ko Sāra tev ir sacījusi, - klausi viņas balsij, jo iekš Īzaka tev dzimums taps nosaukts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Tomēr arī tās kalpones dēlu Es celšu par tautu, tāpēc ka tas tavs dzimums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Un no rīta agri Ābrahāms cēlās un ņēma maizi un ūdens trauku, un deva to Hāgarei, likdams uz viņas pleciem, un to bērnu; un viņš to aizraidīja; un tā gāja un maldījās Bēršebas tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Kad nu ūdens traukā pietrūka, tad tā nometa to bērnu apakš krūma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Un nogāja un apsēdās tur pretī bultas šāviena tālumā, jo tā sacīja: es nevaru redzēt to bērnu mirstam; un apsēdās tur pretī un pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Un Dievs dzirdēja tā puiša balsi, un Dieva eņģelis no debesīm sauca Hāgarei un uz to sacīja: kas tev kait, Hāgare? Nebīsties, jo Dievs tā puiša balsi dzirdējis tai vietā, kur viņš ir. Celies, ņem to puisi un turi to pie savas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Jo Es viņu celšu par lielu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Un Dievs viņai atvēra acis, un tā ieraudzīja ūdens aku un gāja un pildīja to trauku ar ūdeni, un dzirdināja to puisi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Un Dievs bija ar to puisi, un tas auga un dzīvoja tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Un tapa strēlnieks ar stopu un dzīvoja Varanas tuksnesī; un viņa māte tam veda sievu no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Un tanī laikā Abimelehs un Pīkols, viņa karaspēka virsnieks, runāja ar Ābrahāmu sacīdami: Dievs ir ar tevi visās lietās, ko tu dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Un nu zvērē man šeitan pie Dieva, ka tu negribi viltīgs būt pret mani, nedz pret maniem bērniem, nedz pret maniem bērnu bērniem; pēc tās žēlastības, ko es tev darījis, tev būs man darīt un tai zemei, kur tu kā svešinieks piemīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Un Ābrahāms sacīja: es zvērēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Un Ābrahāms norāja Abimelehu ūdens akas dēļ, ko Abimeleha kalpi ar varu bija paņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Tad Abimeleks sacīja: es nezinu, kas to darījis, ne tu man to esi sacījis, nedz es to arī esmu dzirdējis līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Un Ābrahāms ņēma avis un vēršus un deva tos Abimeleham, un tie abi cēla derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Bet Ābrahāms nolika savrup septiņus jērus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Tad Abimelehs sacīja uz Ābrahāmu: par ko šie septiņi jēri, ko tu savrup esi nolicis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Un viņš sacīja: par to, ka tev būs ņemt tos septiņus jērus no manas rokas, lai man būtu par liecību, ka es šo aku racis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Tāpēc tā vieta nosaukta Bēršeba, ka tie abi tur bija zvērējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Un tie derēja derību Bēršebā. Tad cēlās Abimelehs un Pīkols, viņa karaspēka virsnieks, un griezās atpakaļ uz Fīlistu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Bet viņš dēstīja tamariskas koku Bēršebā, un piesauca tur Tā Kunga, tā mūžīgā Dieva, vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Un Ābrahāms piemita kā svešinieks Fīlistu zemē ilgu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Un notikās pēc šīm lietām, tad Dievs Ābrahāmu pārbaudīja un uz to sacīja: Ābrahām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Un tas atbildēja: Redzi, še es esmu. Un Viņš sacīja: ņem jel savu dēlu, savu vienīgo, ko tu mīļo, to Īzaku, un ej uz Morijas zemi, un upurē to tur par dedzināmo upuri uz viena no tiem kalniem, ko Es tev sacīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Un rītā agri Ābrahāms cēlās un apjoza savu ēzeli un ņēma līdz divus no saviem puišiem un Īzaku savu dēlu, un skaldīja malku priekš tā dedzināmā upura un cēlās un gāja uz to vietu, ko Dievs tam bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Un trešā dienā Ābrahāms pacēla savas acis un redzēja to vietu no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Un Ābrahāms sacīja uz saviem puišiem: palieciet jūs teju ar to ēzeli, un es un tas puisēns iesim uz turieni un pielūgsim; tad atkal atnāksim pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Un Ābrahāms ņēma tā dedzināmā upura malku un to uzlika Īzakam, savam dēlam, un ņēma savā rokā uguni un nazi, un tie gāja abi kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Tad Īzaks runāja ar Ābrahāmu, savu tēvu, un sacīja: mans tēvs! Un viņš sacīja: redz, še es esmu, mans dēls. Un tas sacīja: redz, še uguns un malka, bet kur ir tas jērs par dedzināmo upuri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Tad Ābrahāms sacīja: Dievs Sev izredzēs jēru par dedzināmo upuri, mans dēls. Un tie gāja abi kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Un tie nāca tai vietā, ko Dievs viņam bija sacījis, un Ābrahāms tur uztaisīja altāri un salika to malku un saistīja Īzaku, savu dēlu, un lika to uz to altāri malkai virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Un Ābrahāms izstiepa savu roku un ņēma nazi, savu dēlu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Bet Tā Kunga eņģelis sauca no debesīm uz to un sacīja: Ābrahām! Ābrahām! Un tas sacīja: redzi, še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Tad viņš sacīja: neizstiep savu roku pret to puisi un nedari tam nekā, jo nu Es zinu, ka tu Dievu bīsties un savu dēlu, savu vienīgo, neesi taupījis Manis labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Un Ābrahāms pacēla savas acis un skatījās, un redzi, aiz viņa bija auns, biezos krūmos ar saviem ragiem aizķēries; un Ābrahāms gāja un ņēma to aunu, un to upurēja par dedzināmo upuri sava dēla vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Un Ābrahāms nosauca tās vietas vārdu: Tas Kungs redz. Tad vēl šodien saka: uz tā kalna, kur Tas Kungs parādās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Tad Tā Kunga eņģelis otru reizi uz Ābrahāmu sauca no debesīm');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Un sacīja: Es esmu pie Sevis zvērējis, saka Tas Kungs, - tāpēc ka tu tā esi darījis un savu dēlu, savu vienīgo, neesi taupījis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Ka Es svētīdams tevi svētīšu un vairodams vairošu tavu dzimumu, tā kā debess zvaigznes un kā smiltis, kas ir jūrmalā, un tavs dzimums iemantos tavu ienaidnieku vārtus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Un iekš tavas sēklas visas tautas virs zemes taps svētītas, tāpēc ka tu Manai balsij esi paklausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Un Ābrahāms griezās atpakaļ pie saviem puišiem, un tie cēlās un gāja kopā uz Bēršebu, un Ābrahāms mita Bēršebā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Un pēc šīm lietām Ābrahāmam tapa sludināts un sacīts: redzi, Milka Nahoram, tavam brālim, arī bērnus ir dzemdējusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Ucu, viņa pirmdzimto, un Buzu, viņa brāli, un Ķemuēli, Arama tēvu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Un Ķesedu un Hazu un Pildašu un Jitlapu un Betuēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Un Betuēls dzemdināja Rebeku. Šos astoņus dzemdēja Milka Nahoram, Ābrahāma brālim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Un viņa lieka sieva, Reūma vārdā, dzemdēja arīdzan: Tebu un Gaāmu un Taāsu un Maāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Un Sāra bija simts divdesmit un septiņus gadus veca, - šis bija Sāras mūžs, - un Sāra nomira Kiriat-Arbā, - tā ir Hebrone Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Un Ābrahāms nāca Sāru nožēlot un viņu apraudāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Tad Ābrahāms cēlās no sava miroņa un runāja ar Heta bērniem sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Es esmu svešinieks un piedzīvotājs pie jums, dodiet man dzimts kapa vietu, - tad es savu mironi aprakšu no manām acīm nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Un Heta bērni Ābrahāmam atbildēja un uz to sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Klausi mūs, kungs; tu esi viens Dieva celts virsnieks mūsu vidū, - aproc savu mironi mūsu visgodīgākos kapos; nevienam no mums tev nebūs liegt savu kapu, ka tu nevarētu aprakt savu mironi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Tad Ābrahāms cēlās un klanījās priekš tiem zemes ļaudīm, priekš Heta bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Un ar tiem runāja sacīdams: ja tas jums pa prātam, ka es savu mironi aproku no savām acīm nost, tad klausiet man un lūdziet par mani Efronu, Coāra dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Lai tas man dod Makpelas alu, kas tam ir sava tīruma galā; lai man to dod par pilnu naudu, par dzimts kapa vietu jūsu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Un Efrons sēdēja starp Heta bērniem. Tad Efrons, tas Etietis, Ābrahāmam atbildēja priekš Heta bērnu ausīm un priekš visiem, kas pa viņa pilsētas vārtiem staigāja, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nē, mans kungs, klausi man, - to tīrumu es tev dodu, un to alu, kas tanī ir, to es tev dodu, priekš savu ļaužu bērnu acīm es tev to dodu, aproc savu mironi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Tad Ābrahāms klanījās priekš tiem zemes ļaudīm');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Un runāja uz Efronu, tiem zemes ļaudīm dzirdot, sacīdams: kaut tu jel mani klausītu! Es tev došu to naudu par to tīrumu, ņem to no manis, tad es tur aprakšu savu mironi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Un Efrons atbildēja Ābrahāmam sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mans kungs, klausi mani, tā zeme maksā četrsimt sudraba sēķeļus, - kas tas ir starp mani un tevi? Aproc tikai savu mironi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Un Ābrahāms paklausīja Efronam un nosvēra tam to naudu, kā tas bija runājis, Heta bērniem dzirdot, četrsimt sudraba sēķeļus, kas ģeld tirgotāju starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Tad kļuva apstiprināts Efrona tīrums, iekš kā tā Makpelas ala, pret Mamri, tas tīrums un tā ala, kas tanī bija, un visi koki, kas uz tā tīruma stāvēja, kas visapkārt bija viņa ežās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Ābrahāmam par īpašumu priekš Heta bērnu acīm, priekš visiem, kas pa viņa pilsētas vārtiem staigāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Un pēc tam Ābrahāms apraka savu sievu Sāru Makpelas alā tai tīrumā pret Mamri, - tā ir Hebrone Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Tā kļuva apstiprināts tas tīrums un tā ala, kas tanī bija, Ābrahāmam par dzimts kapa vietu no Heta bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Un Ābrahāms bija vecs un labi piedzīvojis, un Tas Kungs Ābrahāmu bija svētījis ar visām lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Tad Ābrahāms sacīja uz savu kalpu, to vecāko savā namā, kas valdīja pār visu, kas viņam bija:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Liec jel savu roku apakš manas ciskas, tad es tev likšu zvērēt pie Tā Kunga, tā debes\' Dieva un tā zemes Dieva, ka tev manam dēlam nebūs sievu ņemt no Kanaāniešu meitām, kuru vidū es dzīvoju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Bet ka tev būs iet uz manu zemi un pie maniem radiem un manam dēlam Īzakam sievu ņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Tad tas kalps uz viņu sacīja: ja tā sieva negribēs man nākt līdzi uz šo zemi, vai man tad tavu dēlu atkal būs aizvest uz to zemi, no kurienes tu izgājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Un Ābrahāms uz to sacīja: sargies, ka tu manu dēlu uz turieni nevedi atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Tas Kungs, tas debes\' Dievs, kas mani ņēmis no mana tēva nama un no manas dzimtenes un kas ar mani runājis un kas man zvērējis sacīdams: tavam dzimumam Es došu šo zemi, - Tas sūtīs Savu eņģeli tavā priekšā, ka tu manam dēlam vari ņemt sievu no turienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Bet ja tā sieva tev negribēs iet līdz, tad tu būsi vaļā no šī mana zvēresta; tikai neved manu dēlu atpakaļ uz turieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Un tas kalps lika savu roku apakš Ābrahāma, sava kunga, ciskas, un tam zvērēja par šo lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Tad tas kalps ņēma desmit kamieļus no sava kunga kamieļiem un aizgāja, un visāda viņa kunga manta bija viņa rokā; un viņš cēlās un gāja uz Mezopotamiju, uz Nahora pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Un viņš tiem kamieļiem lika apmesties ārā priekš pilsētas pie vienas ūdens akas ap vakara laiku, tai laikā, kad tās smēlējas ārā nāca, un viņš sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Kungs, Tu mana kunga Ābrahāma Dievs, lai man šodien izdodas un dari žēlastību pie mana kunga Ābrahāma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Redzi, es stāvu pie ūdens akas, un šīs pilsētas ļaužu meitas nāks ārā ūdeni smelt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Tad lai notiek, ka tā jauna meita, uz ko es sacīšu, pasniedz jel savu trauku, ka es varu dzert, - un tā sacīs, dzer, es tavus kamieļus arīdzan dzirdināšu, - ka tā ir tā, ko Tu Savam kalpam Īzakam novēlējis, un ka es pie tā varu atzīt, ka Tu žēlastību esi parādījis manam kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Un notikās, pirms nekā tas bija pabeidzis runāt, redzi, tad nāca Rebeka ārā, kas bija dzimusi Betuēlim, Milkas, Ābrahāma brāļa, Nahora, sievas dēlam; un tai bija viņas trauks uz pleca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Un tai meitiņai bija ļoti skaists vaigs; tā bija jumprava un neviens vīrs to nebija atzinis; tā nokāpa akā un piepildīja savu trauku un atkal uzkāpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Tad tas kalps steidzās viņai pretī un sacīja: ļauj man jel kādu ūdens malciņu no tava trauka nodzerties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Un tā sacīja: dzer, mans kungs! Un tā steidzās un nolaida to trauku uz savu roku un deva tam dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Un kad tā viņam bija devusi dzert, tad tā sacīja: es smelšu arī priekš taviem kamieļiem, kamēr tie būs padzirdīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Un tā steidzās un izlēja savu trauku dzirdināmā silē, un tecēja atkal uz aku smelt un smēla visiem viņa kamieļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Un tas vīrs izbrīnījās par to, klusu ciezdams, ka viņš samanītu, vai Tas Kungs viņa ceļam licis labi izdoties, vai ne.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Un kad tie kamieļi bija padzērušies, tad tas vīrs ņēma vienu zelta pieres sprādzi, - tā svēra pussēķeli - un divus apliekamus roku gredzenus priekš viņas rokām, - tie svēra desmit sēķeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Un viņš sacīja: meitiņa, kam meita tu esi? Pasaki man jel to: vai priekš mums tava tēva namā vietas, tur naktsmāju dabūt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Un tā uz viņu sacīja: es esmu Betuēļa, Milkas dēla, meita, ko tā Nahoram dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Un tā vēl uz viņu sacīja: tur ir arī diezgan salmu un barības pie mums, ir mājošanas vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Tad tas vīrs Tā Kunga priekšā nomezdamies to pielūdza');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Un sacīja: slavēts lai ir Tas Kungs, mana kunga Ābrahāma Dievs, kas nav atrāvis Savu žēlastību un patiesību no mana kunga! Jo Tas Kungs mani ir vadījis to ceļu uz mana kunga brāļa namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Un tā meitiņa tecēja un to pasacīja savas mātes namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Un Rebekai bija brālis, Lābans vārdā, un Lābans steidzās pie tā vīra ārā uz aku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Un kad viņš to pieres sprādzi un tos roku gredzenus pie savas māsas rokām redzēja un savas māsas Rebekas vārdus dzirdēja, kas sacīja: tā tas vīrs uz mani runājis, - tad tas nāca pie tā vīra, un redzi, tas stāvēja pie tiem kamieļiem pie akas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Un viņš sacīja: nāc iekšā, Tā Kunga svētītais, kam tu stāvi ārā? Jo es esmu namu sataisījis un vieta ir priekš taviem kamieļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Tad tas vīrs nāca namā, un tie nosegloja tos kamieļus, un deva tiem kamieļiem salmus un barību un ūdeni, mazgāt viņa kājas un to vīru kājas, kas viņam bija līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Un tie viņam cēla priekšā barību; bet viņš sacīja: es neēdīšu, pirms nebūšu runājis savus vārdus. Un tas sacīja: runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Tad viņš sacīja: es esmu Ābrahāma kalps,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Un Tas Kungs bagāti ir svētījis manu kungu, un tas ir augumā audzis, un viņš tam ir devis avis un vēršus un sudrabu un zeltu un kalpus un kalpones un kamieļus un ēzeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Un Sāra, mana kunga sieva, manam kungam ir dzemdējusi dēlu savā vecumā, un tam viņš ir devis visu, kas viņam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Un mans kungs man ir licis zvērēt sacīdams: tev manam dēlam nebūs ņemt no tām Kanaāniešu meitām, kuru zemē es dzīvoju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Bet tev būs iet uz mana tēva namu un pie maniem radiem un manam dēlam sievu ņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Tad es sacīju uz savu kungu: ja tā sieva man neies līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Un viņš uz mani sacīja: Tas Kungs, kura priekšā es esmu staigājis, sūtīs Savu eņģeli ar tevi, un liks labi izdoties tavam ceļam, ka tu manam dēlam ņemi sievu no manas cilts un no mana tēva nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Tad tu būsi vaļā no mana zvēresta, kad tu iesi pie maniem radiem, un ja viņi tev nedos, tad tu būsi vaļā no mana zvēresta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Un es nācu šodien pie tās akas un sacīju: Kungs, Tu mana kunga Ābrahāma Dievs, ja Tu, lūdzams, manam ceļam esi licis labi izdoties, kur es eju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Redzi, es stāvu pie tās ūdens akas: kad nu viena jauna meita nāks smelt, un es viņai sacīšu: dod man jel maķenīt ūdens dzert no tava trauka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Un tā uz mani sacīs: dzer ir tu un ir taviem kamieļiem es smelšu, - ka šī ir tā sieva, ko Tas Kungs mana kunga dēlam novēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Pirms es savā sirdī pabeidzu runāt, redzi, tad Rebeka nāca ārā ar ūdens trauku uz pleca, un tā nokāpa akā un smēla, un es uz to sacīju: dod man lūdzama padzerties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Tad viņa traucās un nocēla savu trauku no sava pleca zemē un sacīja: dzer, un es tavus kamieļus arīdzan dzirdināšu; tad es dzēru, un tie kamieļi arīdzan tapa dzirdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Un es viņu vaicāju un sacīju: kam meita tu esi? Un tā sacīja: Betuēla, Nahora dēla, meita, ko Milka tam dzemdējusi. Tad es liku to pieres sprādzi uz viņas vaigu un tos roku gredzenus ap viņas rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Un es nometos un pielūdzu To Kungu un slavēju To Kungu, mana kunga Ābrahāma Dievu, kas mani to īsteno ceļu bija vadījis, mana kunga brāļa meitu viņa dēlam ņemt par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Un nu, ja jūs esat tie, kas žēlastību un uzticību pie mana kunga grib parādīt, tad sakāt man to; un ja ne, tad sakāt man ir to; tad es griezīšos, vai pa labo roku vai pa kreiso.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Tad Lābans un Betuēls atbildēja un sacīja: šī lieta ir no Tā Kunga nākusi, mēs nedz ļauna nedz laba nevaram uz tevi runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Redzi, Rebeka ir tavā priekšā, ņem to un ej; lai tā ir tava kunga dēla sieva, kā Tas Kungs ir sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Un kad Ābrahāma kalps viņu vārdus dzirdēja, tad viņš Tā Kunga priekšā pie zemes mezdamies To pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Un tas kalps izņēma sudraba un zelta lietas un drēbes, un deva Rebekai un viņas brālim, un viņas mātei tas arī deva dārgas dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Tad tie ēda un dzēra, viņš un tie vīri, kas viņam bija līdz, un palika tur pa nakti. Un tie cēlās rītā, un viņš sacīja: atlaidiet mani pie mana kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Tad viņas brālis un viņas māte sacīja: lai tā meitiņa kādas desmit dienas paliek pie mums; pēc tu vari iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Bet viņš uz tiem sacīja: neaizkavējiet mani, Tas Kungs manam ceļam licis labi izdoties; atlaidiet mani, ka es eju pie sava kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Tad tie sacīja: sauksim to meitiņu un jautāsim viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Tad tie sauca Rebeku un uz to sacīja: vai tu gribi iet ar šo vīru? Un tā sacīja: es iešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Tad tie atlaida Rebeku, savu māsu, un viņas emmu, un Ābrahāma kalpu un viņa vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Un tie svētīja Rebeku un uz to sacīja: tu, mūsu māsa, audzi par tūkstošu tūkstošiem, un tavs dzimums lai pārvalda savu ienaidnieku vārtus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Un Rebeka cēlās ar savām meitām un sēdās uz kamieļiem un gāja tam vīram līdz, un tas kalps ņēma Rebeku un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Un Īzaks nāca to ceļu no Lekaj-Roī akas, jo tas mita dienvidu(Negebas) zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Bet Īzaks bija izgājis uz lauku Dievu pielūgt ap vakara laiku. Un tas pacēla savas acis un skatījās, un redzi, kamieļi nāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Un Rebeka pacēla savas acis un redzēja Īzaku un nolaidās no kamieļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Un tā sacīja uz to kalpu: kas tas par vīru, kas tur pa lauku mums nāk pretī? Un tas kalps sacīja: tas ir mans kungs. Tad tā ņēma vaiga apsegu un apsedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Un tas kalps Īzakam visu izteica, ko tas bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Un Īzaks veda Rebeku savas mātes Sāras dzīvoklī, un viņš to ņēma un tā viņam palika par sievu, un viņš to mīlēja. Tā Īzaks tapa iepriecināts pēc savas mātes nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Un Ābrahāms ņēma atkal vienu sievu, Ķeturu vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Un tā viņam dzemdēja Zimranu un Jokšanu un Medanu un Midijanu un Jisbaku un Šuahu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Un Jokšans dzemdēja Šebu un Dedanu, un Dedana bērni bija Asurim un Latuzim un Leūmim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Un Midijana bērni bija Ēfa un Efers un Hanoks un Abidus un Eldaūs; šie visi bija Ķeturas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Bet Ābrahāms deva Īzakam visu, kas tam piederēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Bet to lieko sievu bērniem, kas Ābrahāmam bija, Ābrahāms deva dāvanas, un vēl dzīvs būdams tos atstādināja no sava dēla Īzaka, pret rītiem uz austruma zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Un šie ir Ābrahāma mūža gadi, cik ilgi tas dzīvojis: simts septiņdesmit un pieci gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Un viņš aizmiga un nomira labā vecumā, vecs un diezgan dzīvojis, un viņš tapa piepulcināts pie saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Un Īzaks un Ismaēls, viņa dēli, viņu apraka Makpelas alā, tā Hetieša Efrona, Coāra dēla, tīrumā, kas ir pret Mamri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Tai tīrumā, ko Ābrahāms bija pircis no Heta bērniem; tur Ābrahāms ir aprakts un viņa sieva Sāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Un pēc tam, kad Ābrahāms bija nomiris, tad Dievs svētīja Īzaku, viņa dēlu, un Īzaks mita pie Lekaj-Roī akas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Šie nu ir Ismaēla, Ābrahāma dēla, radu raksti. To Hāgare, tā Ēģiptiete, Sāras kalpone, Ābrahāmam ir dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Un šie ir Ismaēla bērnu vārdi ar saviem cilts vārdiem: Ismaēla pirmdzimtais Nebajots, tad Ķedars un Adbeēls un Mibzams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Un Mizmus un Dumus un Mazus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Adars un Temus, Jeturs, Navis un Ķedmus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Šie ir Ismaēla bērni, un šie ir viņu vārdi pēc viņu sētām un ciemiem, divpadsmit virsnieki par saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Un šie ir Ismaēla dzīvības gadi: simts trīsdesmit un septiņi gadi. Un viņš aizmiga un nomira un tapa piepulcināts pie saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Un tie dzīvoja no Havilas līdz Šurai, kas pretim Ēģiptes zemei, kur iet uz Asuru, visiem saviem brāļiem pretim viņš apmetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Un šie ir Īzaka, Ābrahāma dēla, radu raksti. Ābrahāms dzemdināja Īzaku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Un Īzaks bija četrdesmit gadus vecs, kad viņš par sievu dabūja Rebeku, tā Sīrieša Betuēļa meitu no Mezopotamias, Lābana, tā Sīrieša, māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Un Īzaks no sirds pielūdza To Kungu par savu sievu, jo tā bija neauglīga; un Tas Kungs likās pielūgties, un Rebeka, viņa sieva, tapa grūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Un tie bērni stumdījās viņas miesās, - tad tā sacīja: ja tas tā, kam tad es tāda esmu? Un tā nogāja To Kungu jautāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Un Tas Kungs tai sacīja: divas tautas ir tavās miesās un divējādi ļaudis šķirsies no tava klēpja, un viena tauta būs jo spēcīgāka nekā otra, un tas lielākais kalpos tam mazākajam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Kad nu tas laiks nāca, ka tai bija dzemdēt, redzi, tad dvīņi bija viņas miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Un tas pirmais nāca ārā, pasarkans viscaur, kā spalvaina drēbe, un tie nosauca viņa vārdu Ēsavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Un pēc tam viņa brālis nāca ārā; tas ar savu roku Ēsava papēdi bija satvēris, tāpēc viņa vārds tapa nosaukts Jēkabs. Un Īzaks bija sešdesmit gadus vecs, kad viņš tos dzemdināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Un tie puisēni auga, un Ēsavs bija gudrs uz medīšanu un dzīvoja pa lauku, un Jēkabs tapa rāms vīrs un mājoja teltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Un Īzaks mīlēja Ēsavu, tāpēc ka viņa medījums viņa mutei bija gards, un Rebeka mīlēja Jēkabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Un Jēkabs bija vārījis kādu virumu; tad Ēsavs nāca no lauka un bija piekusis; un Ēsavs sacīja uz Jēkabu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Dod man jel ēst no tā sarkanā, no tā sarkanā (viruma), jo es esmu piekusis; tādēļ viņa vārds ir nosaukts Edoms (Sarkanais).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Tad Jēkabs sacīja: pārdod man šodien savu pirmdzimtību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Un Ēsavs sacīja: redzi, man taču jāmirst, ko tad man palīdz tā pirmdzimtība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Tad Jēkabs sacīja: zvērē man šodien. Tad viņš tam zvērēja un pārdeva Jēkabam savu pirmdzimtību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Un Jēkabs deva Ēsavam maizi un to lēču virumu, un tas ēda un dzēra un cēlās un aizgāja. Tā Ēsavs nicināja savu pirmdzimtību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Un bads bija tai zemē pēc tā pirmā bada, kas bija Ābrahāma laikā. Un Īzaks nogāja uz Ģeraru pie Abimeleha, Fīlistu ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Un Tas Kungs viņam parādījās un sacīja: nenoej uz Ēģipti, mīti tai zemē, ko Es tev saku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Piemājo šinī zemē, un Es būšu ar tevi, un Es tevi svētīšu; jo tev un tavam dzimumam Es došu visas šās zemes un piepildīšu to zvērestu, ko Es tavam tēvam Ābrahāmam esmu zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Un Es vairošu tavu dzimumu kā debess zvaigznes un došu tavam dzimumam visas šās zemes, un iekš tavas sēklas visas zemes tautas svētīsies, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Tāpēc ka Ābrahāms Manai balsij ir klausījis un turējis Manas pavēles, Manus iestādījumus, likumus un baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Tā Īzaks mita Ģerarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Un tās vietas ļaudis vaicāja par viņa sievu, - un viņš sacīja: tā ir mana māsa, jo viņam bija bail sacīt: tā ir mana sieva, - lai tās vietas ļaudis mani nenokauj Rebekas dēļ, jo tā bija skaista vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Un kad viņš labu laiku tur bija dzīvojis, tad Abimelehs, Fīlistu ķēniņš, skatījās pa logu, un redz, Īzaks smējās ar savu sievu Rebeku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Tad Abimelehs aicināja Īzaku un sacīja: redzi, tiešām tā ir tava sieva, kā tad tu esi sacījis, tā ir mana māsa? Un Īzaks uz to sacīja: tāpēc ka es domāju, lai man viņas dēļ nebūtu jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Tad Abimelehs sacīja: kāpēc tu mums to esi darījis? Gandrīz viens no šiem ļaudīm būtu varējis gulēt pie tavas sievas, tad tu mums būtu uzvedis noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Un Abimelehs pavēlēja visiem ļaudīm sacīdams: kas šo vīru vai viņa sievu aizskar, tam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Un Īzaks sēja tanī zemē un dabūja tai gadā simtkārtīgus augļus, jo Tas Kungs to svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Un tas vīrs tapa liels un auga augumā, kamēr viņš palika ļoti liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Un tam bija manta no sīkiem un manta no lieliem lopiem un daudz saimes, un Fīlisti viņu apskauda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Un visas akas, ko viņa tēva kalpi bija rakuši viņa tēva Ābrahāma laikā, tās Fīlisti aizbēra un pildīja ar smiltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Un Abimelehs sacīja uz Īzaku: ej projām no mums, jo tu esi palicis jo varenāks nekā mēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Tad Īzaks no turienes aizgāja un nometās Ģeraras ielejā, un dzīvoja tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Un Īzaks atkal atraka tās ūdens akas, kas bija raktas viņa tēva Ābrahāma laikā, un ko Fīlisti pēc tam bija aizbēruši, kad Ābrahāms bija miris, un viņš viņu vārdus nosauca pēc tiem vārdiem, ar ko viņa tēvs tās bija nosaucis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Un Īzaka kalpi raka tanī ielejā un tur atrada aku ar dzīvu ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Bet Ģeraras gani bārās ar Īzaka ganiem sacīdami: šis ūdens mums pieder. Tad viņš tās akas vārdu nosauca Eseku (strīdus), tāpēc ka tie ar viņu bija strīdējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Tad tie raka citu aku, un par to arīdzan bārās; tāpēc viņš viņas vārdu nosauca Sitna (sūdzība).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Un viņš cēlās no turienes un raka citu aku, un tie par to nebārās; tad viņš viņas vārdu nosauca Rehobot (platums) un sacīja: jo nu Tas Kungs mūs ir izplatījis, un mēs esam augļojušies šinī zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Tad viņš no turienes gāja augšup uz Bēršebu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Un Tas Kungs viņam parādījās tanī naktī un sacīja: Es esmu Ābrahāma, tava tēva Dievs; nebīsties, jo Es esmu ar tevi un tevi svētīšu un vairošu tavu dzimumu Ābrahāma, Sava kalpa, dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Un viņš tur uztaisīja altāri un piesauca Tā Kunga vārdu un tur uzcēla savu telti, un Īzaka kalpi tur raka vienu aku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Un Abimelehs nāca pie tā no Ģeraras, un viens no viņa draugiem Aūzats un Pīkols, viņa karaspēka virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Tad Īzaks uz tiem sacīja: kāpēc jūs nākat pie manis, jūs, kas mani ienīstat un mani no sevis esat izdzinuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Un tie sacīja: mēs redzēt redzam, ka Tas Kungs ir ar tevi; tad esam sacījuši: sazvērēsimies kopā, mēs un tu, un darīsim derību ar tevi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Ka tu mums ļauna nedari, (it) kā mēs tevi neesam aizskāruši, un (it) kā mēs tev labu vien esam darījuši un tevi ar mieru atlaiduši; tu nu esi Tā Kunga svētīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Un viņš tiem darīja dzīres, un tie ēda un dzēra,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Un cēlās rītā agri un zvērēja viens otram, un Īzaks tos atlaida; tad tie no viņa aizgāja ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Un tanī dienā Īzaka kalpi nāca un viņam sacīja, kas bija noticis ar to aku, ko tie bija rakuši, un viņam sacīja: mēs esam ūdeni atraduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Un viņš to nosauca Šebu (zvērests), tādēļ tās pilsētas vārds ir Bēršeba līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Un Ēsavs bija četrdesmit gadus vecs un ņēma par sievu Juditu, Berus, tā Hetieša, meitu, un Basmatu, Elona, tā Hetieša, meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Un tās darīja sirdēstus Īzakam un Rebekai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Un notikās, kad Īzaks bija vecs palicis, un viņa acis tumšas metušās, ka vairs neredzēja, tad viņš aicināja savu vecāko dēlu Ēsavu un uz to sacīja: mans dēls! Un tas viņam atbildēja: redzi, še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Un viņš sacīja: redzi jel, es esmu palicis vecs, - es nezinu savas miršanas dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Ņem tad nu lūdzams savus rīkus, savu bultu maku un savu stopu, un ej uz lauku un medī man kādu medījumu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Un sataisi man gardumu, (it) kā man tīk, un cel man to priekšā ēst, ka mana dvēsele tevi svētī, pirms es mirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Un Rebeka dzirdēja, ko Īzaks runāja uz savu dēlu Ēsavu; un Ēsavs gāja uz lauku, gribēdams kādu medījumu medīt un atnest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Un Rebeka runāja ar savu dēlu Jēkabu un sacīja: redz, es dzirdēju tavu tēvu uz tavu brāli Ēsavu tā runājam un sakām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Atnes man kādu medījumu un sataisi man gardumu, ko ēst, tad es tevi svētīšu Tā Kunga priekšā, pirms es mirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Un nu, mans dēls, klausi manu balsi, kā es tev pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Ej jel pie avīm un dabū man no turienes divus diženus āzīšus, tad es tos tavam tēvam sataisīšu par gardumu, kā tam tīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Un tev to būs priekšā celt savam tēvam, ka viņš ēd un tevi svētī, pirms viņš mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Tad Jēkabs sacīja uz Rebeku, savu māti: redzi, Ēsavs, mans brālis, ir spalvains vīrs, un es esmu gludens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Ja mans tēvs mani aptaustīs, tad es būšu viņa acīs tā kā krāpnieks, un dabūšu lāstu un ne svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Tad viņa māte uz viņu sacīja: tavi lāsti lai nāk uz mani, mans dēls! Klausi tikai manu balsi, un ej, dabū man tos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Tad viņš nogāja un ņēma un atnesa savai mātei, un viņa māte sataisīja gardumu, tā kā viņa tēvam patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Un Rebeka ņēma Ēsava, sava vecāka dēla, krašņākās drēbes, kas tai bija namā, un tās apvilka Jēkabam, savam jaunākam dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Un tās kazlēnu ādas tā aplika ap viņa rokām un ap viņa kakla plikumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Un viņa deva to gardumu un to maizi, ko bija sataisījusi, Jēkaba, sava dēla, rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Un tas nāca pie sava tēva un sacīja: mans tēvs! Un viņš sacīja: še es esmu; kurš tu esi, mans dēls?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Tad Jēkabs sacīja uz savu tēvu: es esmu Ēsavs, tavs pirmdzimtais; es esmu darījis, kā tu uz mani sacījis; celies, lūdzams, sēdies un ēd no mana medījuma, lai tava dvēsele mani svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Tad Īzaks sacīja uz savu dēlu: kā tu to drīz esi atradis, mans dēls? Un tas sacīja: Tas Kungs, tavs Dievs, man to lika sastapt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Tad Īzaks sacīja uz Jēkabu: nāc jel šurp, ka es tevi aptaustu, mans dēls, vai tu te esi mans dēls Ēsavs, vai ne.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Un Jēkabs piegāja pie sava tēva Īzaka, un viņš to aptaustīja un sacīja: balss ir Jēkaba balss, bet rokas ir Ēsava rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Un viņš to nepazina, jo viņa rokas bija spalvainas tā kā viņa brāļa Ēsava rokas, un viņš to svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Un viņš sacīja: vai tu te esi Ēsavs, mans dēls? Un tas sacīja: es tas esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Tad viņš sacīja: cel man to priekšā, ka es ēdu no tava medījuma, mans dēls, lai mana dvēsele tevi svētī. Un tas cēla viņam priekšā un viņš ēda; un tas viņam atnesa vīnu, un viņš dzēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Un viņa tēvs Īzaks uz to sacīja: nāc jel šurp un skūpsti mani, mans dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Un Jēkabs piegāja un viņu skūpstīja, un viņš saoda viņa drēbju smaržu un to svētīja un sacīja: redzi, mana dēla smarža ir tā kā lauka smarža, ko Tas Kungs svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Lai tad Dievs tev dod no debess rasas un no zemes treknuma un daudz labības un vīna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Ļaužu pulki lai tev kalpo, un ļaudis lai klanās tavā priekšā; esi kungs pār saviem brāļiem, un tavas mātes bērni lai klanās tavā priekšā; nolādēts, kas tevi lād, un svētīts, kas tevi svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Un notikās, kad Īzaks bija pabeidzis Jēkabu svētīt, un Jēkabs tikko bija izgājis no sava tēva Īzaka, tad Ēsavs, viņa brālis, nāca no savas medīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Un tas arīdzan sataisīja gardumu un to nesa savam tēvam priekšā un sacīja uz savu tēvu: celies, mans tēvs, un ēd no sava dēla medījuma, lai tava dvēsele mani svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Tad Īzaks, viņa tēvs, uz to sacīja: kas tu esi? Un tas sacīja: es esmu tavs dēls, tavs pirmdzimtais, Ēsavs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Tad Īzaks iztrūcinājās pārbīdamies varen ļoti un sacīja: kas tad tas mednieks, kas man jau atnesa? Un es esmu ēdis no visa, pirms tu nāci, un es viņu esmu svētījis; tas arī svētīts paliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Kad Ēsavs sava tēva vārdus dzirdēja, tad tas brēca lielā brēkšanā un noskuma pārlieku un sacīja uz savu tēvu: svētī mani arīdzan, mans tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Un viņš sacīja: tavs brālis ir nācis ar viltu un tavu svētību paņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Un tas sacīja: tiešām viņa vārdu sauc Jēkabu, un šis nu mani otru reiz\' pievīlis; manu pirmdzimtību viņš ir ņēmis, un redzi, nu viņš ņem manu svētību. Un tas sacīja; vai tu nekādas svētības priekš manis vairs neesi atlicinājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Un Īzaks atbildēja un sacīja uz Ēsavu: redz, es viņu par kungu esmu cēlis pār tevi un visus viņa brāļus esmu licis viņam par kalpiem, arī labību un vīnu es viņam esmu piešķīris, - ko man tad tev būs darīt, mans dēls?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Un Ēsavs sacīja uz savu tēvu: vai tad tev tikai viena pati svētība, mans tēvs? Svēti mani arīdzan, mans tēvs. Un Ēsavs pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Tad Īzaks, viņa tēvs, atbildēja un uz to sacīja: redzi, bez zemes treknuma būs tava mājas vieta, un bez debess rasas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Un no sava zobena tu dzīvosi un kalposi savam brālim, un notiksies, kad tu vaļā rausies, tad tu nokratīsi viņa jūgu no sava kakla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Un Ēsavs nīdēja Jēkabu tās svētības dēļ, ar ko tēvs viņu bija svētījis, un Ēsavs sacīja savā sirdī: gan nāks manam tēvam drīz bēdu dienas, jo es nokaušu savu brāli Jēkabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Un Rebekai šie Ēsava, viņas vecāka dēla, vārdi tapa pasacīti, un tā sūtīja un aicināja Jēkabu, savu jaunāko dēlu, un uz to sacīja: redzi, tavs brālis Ēsavs grib atriebties un tevi nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Un nu, mans dēls, klausi manu balsi, celies, bēdz pie Lābana, mana brāļa, Hāranā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Un palieci pie viņa kādu laiku, kamēr tava brāļa karstums pāriet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Kamēr tava brāļa dusmas no tevis novēršās, un viņš to aizmirst, ko tu viņam esi darījis. Tad es sūtīšu un tevi vedīšu no turienes atpakaļ. Kādēļ lai jūs abus zaudēju vienā dienā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Un Rebeka sacīja uz Īzaku: es esmu apnikusi dzīvot Heta meitu priekšā; ja Jēkabs sievu ņem no Heta meitām, (it) kā šīs ir no šās zemes meitām, - kam tad man vairs dzīvot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Tad Īzaks aicināja Jēkabu un to svētīja un tam pavēlēja un uz to sacīja: tev nebūs sievu ņemt no Kanaāniešu meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Celies, ej uz Mezopotamiju, Betuēļa, savas mātes tēva, namā, un ņem sev sievu no turienes, no Lābana, savas mātes brāļa, meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Un tas visuvarenais Dievs lai tevi svētī un lai tevi dara auglīgu un lai tevi vairo, ka topi par lielu ļaužu pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Un lai viņš tev dod Ābrahāma svētību, tev un tavam dzimumam ar tevi, ka tu vari iemantot to zemi, kur tu esi piemitis, ko Dievs Ābrahāmam ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Tā Īzaks atlaida Jēkabu, un tas gāja uz Mezopotamiu pie Lābana, Betuēļa, tā Sīrieša, dēla, Rebekas, Jēkaba un Ēsava mātes, brāļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Kad nu Ēsavs redzēja, ka Īzaks Jēkabu bija svētījis un uz Mezopotamiu sūtījis, no turienes sievu ņemt, un ka viņš to svētījot tam bija pavēlējis sacīdams: tev nebūs sievu ņemt no Kanaāniešu meitām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Un ka Jēkabs savam tēvam un savai mātei bija paklausījis un uz Mezopotamiu aizgājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Un kad Ēsavs arī redzēja, ka Īzaks, viņa tēvs, tās Kanaāniešu meitas neieredzēja, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Tad Ēsavs gāja pie Ismaēla un ņēma klāt pie savām sievām sev par sievu Maālatu, Ismaēla, Ābrahāma dēla, meitu, Nebajota māsu. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Un Jēkabs aizgāja no Bēršebas un gāja uz Hāranu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Un tam gadījās nonākt kādā vietā, tur viņš palika par nakti, jo saule bija nogājusi; un tas ņēma vienu no tās vietas akmeņiem un lika to sev pagalvē un apgūlās tanī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Un tas sapņoja, un redzi, trepes bija celtas virs zemes, un viņu virsgals aiztika debesis, un redzi, Dieva eņģeļi pa tām uzkāpa un nokāpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Un redzi, Tas Kungs stāvēja virsgalā un sacīja: Es esmu Tas Kungs, tava tēva Ābrahāma Dievs un Īzaka Dievs; to zemi, kur tu guli, Es došu tev un tavam dzimumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Un tavs dzimums būs kā zemes pīšļi, un tu izplētīsies pret vakariem un pret rītiem, uz ziemeļa pusi un uz dienasvidus pusi, un caur tevi un tavu sēklu visas zemes ciltis taps svētītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Un redzi, Es esmu ar tevi un pasargāšu tevi visur, kur tu noiesi, un pārvedīšu tevi atkal uz šo zemi; jo Es tevi negribu atstāt, tiekams Es izdarīšu, ko Es uz tevi esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Kad nu Jēkabs no sava miega atmodās, tad tas sacīja: tiešām, Tas Kungs ir šinī vietā, un es to neesmu zinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Un viņš bijās un sacīja: cik bijājama ir šī vieta! Še ir tiešām Dieva nams un še ir debesu vārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Un Jēkabs cēlās rītā agri un ņēma to akmeni, kas tam bija pagalvē bijis, un to uzcēla par zīmi un tam uzlēja eļļu virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Un viņš nosauca tās vietas vārdu Bēteli (Dieva nams); bet papriekš tai pilsētai bija Lūza vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Un Jēkabs solīdamies solījās un sacīja: ja Dievs Tas Kungs būs ar mani un mani pasargās uz šā ceļa, ko es staigāju, un man dos maizi ēst un drēbes ģērbties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Un man liks ar mieru pāriet sava tēva namā, tad Tas Kungs lai man ir par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Un šim akmenim, ko esmu uzcēlis par zīmi, būs tapt par Dieva namu, un no visa, ko Tu man dosi, es Tev došu desmito tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Un Jēkabs cēlās kājās un gāja uz to ļaužu zemi, kas pret rītiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Un skatījās, un redzi, tur bija aka uz lauka. Un redzi, tur bija trīs avju pulki pie tās nometušies, jo no tās akas tās avis tapa dzirdinātas, un liels akmens bija uz akas cauruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Un turpat visi avju pulki tapa sadzīti, un tie novēla to akmeni no akas cauruma un dzirdīja tās avis un uzlika atkal to akmeni uz akas caurumu savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Tad Jēkabs uz tiem sacīja: brāļi, no kurienes jūs esat? Un tie sacīja: mēs esam no Hāranas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Un viņš uz tiem sacīja: vai jūs pazīstat Lābanu, Nahora dēlu? Un tie sacīja: pazīstam gan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Tad viņš uz tiem sacīja: vai tam labi klājās? Un tie atbildēja: labi gan; un redzi, Rahēle, viņa meita, te nāk ar avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Un viņš sacīja: redzi, saule vēl ir gabalā, vēl nav laiks lopus pārdzīt, dzirdinājiet tās avis un ejat un paganiet tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Tad tie sacīja: mēs nevaram, pirms visi avju pulki nav sadzīti; tad to akmeni noveļ no akas cauruma, un mēs dzirdinām tās avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Kad viņš vēl ar tiem runāja, tad nāca Rahēle ar avīm, kas viņas tēvam piederēja, jo viņa tās ganīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Un kad Jēkabs ieraudzīja Rahēli, savas mātes brāļa Lābana meitu, un savas mātes brāļa Lābana avis, tad tas piegāja un novēla to akmeni no akas cauruma un dzirdīja savas mātes brāļa Lābana avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Un Jēkabs skūpstīja Rahēli un pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Un Jēkabs sacīja Rahēlei, ka esot viņas tēva radinieks un Rebekas dēls, tad tā tecēja un to pasacīja savam tēvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Un kad Lābans dzirdēja to vēsti par Jēkabu, savas māsas dēlu, tad tas viņam tecēja pretī un viņu apkampa un skūpstīja un ieveda savā namā. Tad tas Lābanam teica visas šās lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Un Lābans uz viņu sacīja: tiešām, tu esi no maniem kauliem un no manas miesas; un viņš pie tā palika veselu mēnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Un Lābans sacīja uz Jēkabu: jebšu tu esi mans radinieks, vai tādēļ: tu man velti kalpotu? Saki man, kādu algu tu prasi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Un Lābanam bija divas meitas; tās vecākās vārds bija Lea un tās jaunākās vārds bija Rahēle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Leas acis bija pavājas, bet Rahēle bija skaista no auguma un ģīmja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Un Jēkabs mīlēja Rahēli un sacīja: es tev gribu kalpot septiņus gadus par Rahēli, tavu jaunāko meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Tad Lābans sacīja: Labāki es to dodu tev, nekā citam vīram; paliec pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Un Jēkabs kalpoja par Rahēli septiņus gadus; tās likās kādas dienas vien esam, tik mīļa tā viņam bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Un Jēkabs sacīja uz Lābanu: dod man manu sievu, jo manas dienas ir pilnas, ka es pie tās eju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Tad Lābans sapulcēja visus tās vietas ļaudis un taisīja dzīres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Un vakarā viņš ņēma savu meitu Leū un to ieveda pie viņa, un Jēkabs gāja pie tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Un Lābans deva savu kalponi Zilfu Leai, savai meitai, par kalponi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Un notikās rītā, un redzi, tā bija Lea. Tad viņš sacīja uz Lābanu: kam tu man to esi darījis? Vai es neesmu tev kalpojis par Rahēli; kam tu mani esi pievīlis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Tad Lābans sacīja: mūsu zemē nemēdz izdot jaunāko priekš pirmdzimtās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Beidz to nedēļu ar šo, tad es arī viņu tev došu par to kalpošanu, ko tu vēl citus septiņus gadus pie manis kalposi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Un Jēkabs tā darīja un beidza to nedēļu ar šo; tad Lābans tam deva Rahēli, savu meitu, par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Un Lābans deva savu kalponi Bilu Rahēlei par kalponi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Un Jēkabs gāja arī pie Rahēles, un mīlēja Rahēli vairāk nekā Leū, un kalpoja pie Lābana vēl septiņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Un Tas Kungs redzēja, ka Lea netapa cienīta; tad viņš to darīja auglīgu, bet Rahēle bija neauglīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Un Lea tapa grūta un dzemdēja dēlu un nosauca viņa vārdu Rūbenu; jo tā sacīja: Tas Kungs manas bēdas ir redzējis, jo nu mans vīrs mani mīļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Un tā tapa atkal grūta un dzemdēja dēlu un sacīja: Tas Kungs dzirdējis, mani esam necienītu, viņš man arī šo ir devis; un tā nosauca viņa vārdu Sīmeanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Un tā tapa atkal grūta un dzemdēja dēlu un sacīja: nu jel mans vīrs mani mīlēs; jo es viņam esmu dzemdējusi trīs dēlus. Tādēļ tā nosauca viņa vārdu Levi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Un viņa tapa atkal grūta un dzemdēja dēlu un sacīja: šo brīdi es slavēšu To Kungu. Tādēļ tā viņa vārdu nosauca Jūdu. Un tā mitējās dzemdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Kad nu Rahēle redzēja, ka tā Jēkabam nedzemdēja, tad tā apskauda savu māsu un sacīja uz Jēkabu: dabū man bērnus, bet ja ne, tad man jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Tad Jēkabs apskaitās uz Rahēli un sacīja: vai es esmu Dieva vietā, kas tev miesas augļus liedzis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Un tā sacīja: redzi, še ir mana kalpone Bilha, ej pie tās, ka tā uz manu klēpi dzemdē, un es arīdzan caur viņu augļojos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Un viņa tam deva Bilu, savu kalponi par sievu, un Jēkabs gāja pie tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Un Bilha tapa grūta un dzemdēja Jēkabam dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Tad Rahēle sacīja: Dievs man tiesu ir iznesis un arī manu balsi paklausījis un man dēlu devis. Tādēļ tā viņa vārdu nosauca Danu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Un Bilha, Rahēles kalpone, tapa atkal grūta un dzemdēja Jēkabam otru dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Tad Rahēle sacīja: Dieva cīnīšanos esmu cīnījusies ar savu māsu un arī uzvarējusi, - un nosauca viņa vārdu Naftali.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Kad nu Lea redzēja, ka bija mitējusies dzemdēt, tad tā arīdzan ņēma savu kalponi Zilfu un to Jēkabam deva par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Un Zilfa, Leas kalpone, dzemdēja Jēkabam dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Tad Lea sacīja: laime, - un nosauca viņa vārdu Gadu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Un Zilfa, Leas kalpone, dzemdēja Jēkabam otru dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Tad Lea sacīja: labi man, jo meitas mani teiks svētīgu, - un tā nosauca viņa vārdu Ašeru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Un Rūbens gāja kviešu pļaujamā laikā un atrada dudaīm (mīlestības ābols) laukā un atnesa tos Leai, savai mātei, un Rahēle sacīja uz Leū: dod man jel no tava dēla dudaīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Un viņa uz to sacīja: vai tā ir maza lieta, ka tu manu vīru esi atņēmusi, un tu arī mana dēla dudaīm gribi ņemt? Tad Rahēle sacīja: tam būs šo nakti pie tevis gulēt par tava dēla dudaīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Kad nu Jēkabs vakarā no lauka nāca, tad Lea tam izgāja pretī un sacīja: tev būs nākt pie manis, jo es tevi ar maksu esmu saderējusi par sava dēla dudaīm. Un viņš pie tās gulēja tanī naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Un Dievs paklausīja Leū, un tā tapa grūta un dzemdēja Jēkabam piekto dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Tad Lea sacīja: Dievs man to atmaksājis, ka es savam vīram esmu devusi savu kalponi, - un tā nosauca viņa vārdu Īsašaru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Un Lea tapa atkal grūta un dzemdēja Jēkabam sesto dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Tad Lea sacīja: Dievs mani apdāvinājis ar labu dāvanu, nu mans vīrs pie manis dzīvos, tāpēc, ka es viņam esmu dzemdējusi sešus dēlus - un tā nosauca viņa vārdu Zebulonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Un pēc tam viņa dzemdēja meitu un nosauca viņas vārdu Dinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Un Dievs pieminēja Rahēli un paklausīja viņu un darīja viņu auglīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Un viņa tapa grūta un dzemdēja dēlu un sacīja: Dievs manu apsmieklu no manis atņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Un tā nosauca viņa vārdu Jāzepu, sacīdama: lai Tas Kungs mani apdāvina vēl ar citu dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Un notikās, kad Rahēle Jāzepu bija dzemdējusi, tad Jēkabs sacīja uz Lābanu: atlaid mani, ka es noeju uz savu vietu savā zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dod man manas sievas un manus bērnus, kuru dēļ tev esmu kalpojis, tad es iešu, jo tu gan zini to kalpošanu, ko tev esmu kalpojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Un Lābans uz to sacīja: kaut es būtu atradis žēlastību tavās acīs! - es esmu nopratis, ka Tas Kungs mani tevis dēļ ir svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Un viņš sacīja: prasi savu algu no manis, tad es to došu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Un tas uz viņu sacīja: tu zini, kā es tev esmu kalpojis, un kā tavi lopi pie manis ir izdevušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Jo priekš manas atnākšanas tev bija mazums, un tas ir lielā pulkā vairojies, un Tas Kungs tevi svētījis caur maniem soļiem; un nu, kad tad man būs apgādāt savu namu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Un viņš sacīja: ko lai tev dodu? Tad Jēkabs sacīja: tev man nekā nav jādod; ja tu man šo darīsi, tad es atkal ganīšu un sargāšu tavas avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Es izstaigāšu šodien pa visu tavu ganāmo pulku un atšķiršu no turienes visus raibos un lāsainos un visus melnos starp jēriem un visus lāsainos un raibos starp kazām, - un tās būs man par algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Tad mana taisnība liecinās par mani nākamās dienās, kad tu nāksi, manu algu raudzīt: viss, kas nav raibs un lāsains starp kazām un melns starp jēriem, to es būšu zadzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Tad Lābans sacīja: redzi, lai jel notiek pēc tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Un viņš atšķīra tanī dienā tos lāsainos un raibos āžus, un visas lāsainās un raibās kazas, visu, pie kā bija baltums, un visu, kas bija melns starp jēriem, un viņš tos iedeva savu bērnu rokā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Un lika starpu treju dienu gājumā starp sevi un Jēkabu. Un Jēkabs ganīja Lābana citas avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Tad Jēkabs ņēma rīkstes no zaļām apsēm un mandeļu kokiem un kļavām, un nodrāza tām baltas strīpas, atklādams to baltumu pie tām rīkstēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Un tos kociņus, ko bija nomizojis, viņš ielika ūdens silēs un dzeramos traukos avīm priekšā, ka tās nākdamas dzert apietos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Un tās avis apgājās pār tām rīkstēm, un vedās strīpainas, lāsainas un raibas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Un Jēkabs šķīra tos jērus, un lika tām mātēm skatīties uz tām strīpainām un melnām starp Lābana avīm, un lika savus ganāmos pulkus atsevišķi, un nelika tos pie Lābana avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Un notikās allažiņ, kad tās agrās avis apgājās, tad Jēkabs to avju priekšā tos kociņus ielika ūdens silēs, ka tās pār tiem kokiem apietos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Bet kad tās vēlās avis apgājās, tad Jēkabs tos kociņus nelika iekšā, tad tie atpīļi(vājie) kļuva Lābanam un tie agrējie(spēcīgie) Jēkabam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Un tas vīrs auga ļoti varens, un tam bija daudz avju, kalpoņu un kalpu, kamieļu un ēzeļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Un viņš dzirdēja, ka Lābana bērni sacīja: Jēkabs visu paņēmis, kas mūsu tēvam pieder, un no tā, kas mūsu tēvam piederēja, viņš visu šo mantu ir krājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Un Jēkabs redzēja Lābana vaigu, un redzi, tas nebija vairs, kā vakar un aizvakar.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Un Tas Kungs sacīja uz Jēkabu: griezies atpakaļ uz savu tēva zemi un pie saviem radiem, un Es būšu ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Tad Jēkabs sūtīja un aicināja Rahēli un Leū uz lauku pie savām avīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Un sacīja uz tām: es redzu jūsu tēva vaigu, ka tas nav pret mani kā vakar un aizvakar, bet mana tēva Dievs ir bijis ar mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Un jūs zināt, ka ar visu savu spēku jūsu tēvam esmu kalpojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Bet jūsu tēvs mani pievīlis un manu algu desmitkārt pārgrozījis; tomēr Dievs tam nav vaļas devis, man ļaunu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Kad viņš tā sacīja: tām lāsainām būs tev būt par algu, tad visas avis vedās lāsainas; un kad viņš tā sacīja: tām strīpainām būs tev būt par algu, tad visas avis vedās strīpainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Tā Dievs jūsu tēvam tos lopus ir atņēmis un man devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Un notikās tanī laikā, kad avis apgājās, ka es savas acis pacēlu un redzēju sapnī, un redzi, tie āži, kas apgājās, bija strīpaini, raibi un lāsaini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Tad tas Dieva eņģelis uz mani sacīja sapnī: Jēkab; un es sacīju: še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Un tas sacīja: pacel jel savas acis un skaties, - visi tekuļi, kas apietās ar tām avīm, ir strīpaini, lāsaini un raibi; jo Es visu to esmu redzējis, ko tev Lābans dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Es esmu Bēteles Dievs, kur tu esi svaidījis piemiņas akmeni, kur tu man solīdamies esi solījies; celies nu un izej no šās zemes un griezies atpakaļ uz savu dzimteni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Tad Rahēle un Lea atbildēja un uz to sacīja: vai mums vēl ir kāda daļa un mantība mūsu tēva namā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Vai mēs no viņa neesam turētas kā svešas? Jo viņš mūs ir pārdevis un arī mūsu maksu rīdams aprijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Jo visa bagātība, ko Dievs mūsu tēvam ir atņēmis, pieder mums un mūsu bērniem; un nu dari visu to, ko Dievs tev ir sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Un Jēkabs cēlās un lika savus bērnus un savas sievas uz kamieļiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Un aizveda visus savus lopus un visu savu mantu, ko Mezopotamijā bija pelnījis, ka ietu pie Īzaka, sava tēva, uz Kanaāna zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Un Lābans bija aizgājis savas avis cirpt, un Rahēle nozaga tos elka dievus, kas bija viņas tēvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Un Jēkabs pievīla Lābanu, to Sīrieti, nesacīdams, ka bēgšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Un viņš bēga ar visu, kas tam bija, un cēlās un pārcēlās pār to lielo upi un grieza savu vaigu uz Gileād kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Un trešā dienā Lābanam tapa sacīts, Jēkabu esam aizbēgušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Tad tas ņēma savus brāļus un dzinās tam pakaļ septiņu dienu gājumu un to panāca uz Gileād kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Bet Dievs nāca pie Lābana, tā Sīrieša, sapnī un tam sacīja: sargies, ka tu ar Jēkabu nerunā no laba uz ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Un Lābans panāca Jēkabu; un Jēkabs savu telti bija uzcēlis kalnā, un Lābans ar saviem brāļiem to uzcēla Gileād kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Tad Lābans sacīja uz Jēkabu: ko tu esi darījis, ka tu mani esi pievīlis un manas meitas aizvedis, tā kā ar zobenu saņemtas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Kam tu paslepen esi aizbēdzis un no manis nozadzies, un man to neesi sacījis, ka es tev būtu pavadījis ar līksmību un dziesmām, ar bungām un koklēm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Un tu man neesi ļāvis skūpstīt savus dēlus un savas meitas. Tu neprātīgi esi darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Spēka gan būtu manā rokā jums ļaunu darīt, bet jūsu tēva Dievs vakar uz mani runājis sacīdams: sargies, ka tu ar Jēkabu nerunā no laba uz ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Un nu, tu esi ātri aizgājis, jo tu esi ilgodamies ilgojies pēc sava tēva nama; - kāpēc tu esi nozadzis manus dievus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Tad Jēkabs atbildēja un sacīja uz Lābanu: man bija bail un es domāju, ka tu man savas meitas ar varu atņemsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Bet pie kura tu savus dievus atradīsi, tas lai nepaliek dzīvs mūsu brāļu priekšā. Izmeklē, kas man ir, un ņem tos. Bet Jēkabs nezināja, ka Rahēle tos bija nozagusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Un Lābans gāja Jēkaba teltī un Leas teltī un to abu kalpoņu teltī un neatrada nenieka; un izgāja no Leas telts un iegāja Rahēles teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Bet Rahēle tos elka dievus bija ņēmusi un nolikusi apakš kamieļa sedliem un uzsēdusies tiem virsū. Un Lābans apgrābstīja visu to telti un tos neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Un tā sacīja uz savu tēvu: neapskaisties, mans kungs, ka es priekš tevis nevaru celties, jo man klājās, kā sievām mēdz būt. Un viņš pārmeklēdams neatrada tos elka dievus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Tad Jēkabs apskaitās un bārās un sacīja uz Lābanu: kas ir mans noziegums, kas ir mani grēki, ka tu tik karsti man esi dzinies pakaļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Ka tu visus manus rīkus esi aptaustījis; ko tu esi atradis no visiem tava nama rīkiem? Liec to priekšā maniem un taviem brāļiem, ka tie starp mums abiem tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Šos divdesmit gadus es pie tevis esmu bijis, tavas avis un tavas kazas nav izmetušās, un tos aunus no tavām avīm es neesmu ēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'To saplosīto es tev neesmu pārnesis, tas man bija jāmaksā; no manas rokas tu to esi prasījis, vai tas bija zagts dienā, vai tas bija zagts naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Es esmu tāds bijis, ka mani dienā karstums nomāca un naktī aukstums, un miegs nenāca manās acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Divdesmit gadus esmu bijis tavā namā, četrpadsmit gadus tev esmu kalpojis par tavām divām meitām un sešus gadus par tavām avīm, un tu manu algu desmitkārt esi pārgrozījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Ja mana tēva Dievs, tas Ābrahāma Dievs un Tas, ko Īzaks bijās, pie manis nebūtu bijis, tu nu mani tukšu būtu aizsūtījis. Dievs manas bēdas un manu roku darbu ir uzlūkojis un tevi izgājušā naktī apsaucis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Tad Lābans atbildēja un sacīja uz Jēkabu: tās meitas ir manas meitas, un tie bērni ir mani bērni, un tās avis ir manas avis, un viss, ko tu redzi, tas ir mans; un ko es šodien darīšu šīm manām meitām vai viņu bērniem, ko tās ir dzemdējušas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Un nu nāc, darīsim derību, es un tu, ka tā ir par liecību starp mani un tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Un Jēkabs ņēma akmeni un to uzcēla par zīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Un Jēkabs sacīja uz saviem brāļiem: salasiet akmeņus; un tie ņēma akmeņus un salika tos vienā kopā, un ēda tur virs tās kopas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Un Lābans to nosauca Jegar-Sahāduta (āramiski: liecības kopa), bet Jēkabs to nosauca Galed (ebrejiski: liecības kopa).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Un Lābans sacīja: šī kopa lai šodien liecību dod starp mani un tevi; tāpēc viņas vārdu nosauca Galedu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Un Micpu, tāpēc ka viņš sacīja: Tas Kungs lai skatās uz mani un uz tevi, kad mēs viens otru neredzēsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Ja tu apbēdināsi manas meitas un ņemsi citas sievas pie manām meitām klāt, - neviens nav pie mums, redzi, Dievs būs liecinieks starp mani un tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Tad Lābans sacīja uz Jēkabu: redz, šī kopa, un redz, šī piemiņas zīme, ko es esmu uzcēlis starp mani un tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Šī kopa lai dod liecību un šī zīme lai dod liecību, ka es gar šo kopu nenoiešu pie tevis, ļauna darīt, un ka tev gar šo kopu un šo zīmi nebūs pie manis nākt, ļauna darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Ābrahāma Dievs un Nahora Dievs un viņu tēvu Dievs lai tiesā starp mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Un Jēkabs zvērēja pie tā, ko viņa tēvs Īzaks bijās, un upurēja upuri kalnā un aicināja savus brāļus maizi ēst. Un tie ēda maizi un palika par nakti uz tā kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Un Lābans cēlās rītā agri un skūpstīja savus bērnus un savas meitas un tos svētīja. Un Lābans aizgāja un griezās atpakaļ uz savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Un Jēkabs gāja savu ceļu, un Dieva eņģeļi to sastapa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Un šos redzēdams Jēkabs sacīja: tas ir Dieva karaspēks, - un nosauca tās vietas vārdu Mahānaīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Un Jēkabs sūtīja vēstnešus savā priekšā pie Ēsava, sava brāļa, uz Seīra zemi, uz Edoma tiesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Un tiem pavēlēja un sacīja: tā jums būs sacīt manam kungam Ēsavam: tā saka tavs kalps Jēkabs: es esmu svešumā mitis pie Lābana un līdz šim tur palicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Un man ir vērši un ēzeļi, avis un kalpi un kalpones, un es esmu sūtījis savam kungam vēstīt, lai es žēlastību tavās acīs atrodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Un tie vēstneši griezās atpakaļ pie Jēkaba un sacīja: mēs nācām pie tava brāļa Ēsava, un viņš tev arīdzan iet pretī, un četrsimt vīri līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Tad Jēkabs bijās ļoti un viņam bija bail, un viņš šķīra divējos pulkos tos ļaudis, kas tam bija, un tās avis un tos vēršus un tos kamieļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Un sacīja: ja Ēsavs uzbruks vienam pulkam un to apkaus, tad tas otrs pulks izmuks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Un Jēkabs sacīja: tu mana tēva Ābrahāma Dievs, un mana tēva Īzaka Dievs, ak Kungs! Kas uz mani sacījis: griezies atpakaļ uz savu zemi un pie saviem radiem, un es tev gribu labu darīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Es esmu mazs pret visām apžēlošanām un pret visu uzticību, ko tu savam kalpam esi darījis. Jo ar savu spieķi es pār šo Jardāni esmu pārgājis un nu es esmu palicis par diviem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Izpestī mani lūdzams no mana brāļa rokas, no Ēsava rokas, jo es bīstos, ka tas nenāk un mani neapkauj, māti ar bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Tu esi sacījis: Es nemitēšos tev labu darīt un vairošu tavu dzimumu kā jūras smiltis, ko nevar izskaitīt aiz liela pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Un viņš palika tur to nakti un ņēma no tā, kas tam pie rokas bija, dāvanu priekš Ēsava, sava brāļa:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Divsimt kazas un divdesmit āžus, divsimt avis un divdesmit aunus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Trīsdesmit zīdošas kamieļu mātes ar viņu kumeļiem, četrdesmit govis un desmit vēršus, divdesmit ēzeļu mātes un desmit kumeļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Un deva tos savu kalpu rokā, ikkatru pulku atsevišķi, un sacīja uz saviem kalpiem: ejat man papriekš un pametiet starpu starp pulku un pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Un viņš pavēlēja tam pirmajam sacīdams: kad Ēsavs, mans brālis, tevi sastaps un tev vaicās un sacīs: kam tu piederi un uz kurieni tu ej, un kam pieder še, kas tavā priekša?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Tad tev būs sacīt: tie pieder tavam kalpam Jēkabam; tas sūta savam kungam Ēsavam dāvanu, un redzi, viņš pats ir arīdzan mums pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Un viņš pavēlēja arī tam otram un tam trešajam un visiem, kas tos lopus dzina sacīdams: pēc šiem vārdiem jums būs sacīt uz Ēsavu, kad to sastapsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Un jums būs arī sacīt: redzi, tavs kalps Jēkabs mums nāk pakaļ! Jo viņš domāja: es apmierināšu viņa vaigu ar šo dāvanu, kas man iet pa priekšu, un pēc es redzēšu viņa vaigu, kas zina, viņš mani pieņems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Tad nu tā dāvana aizgāja viņam pa priekšu, bet viņš pats palika to nakti pie sava pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Un viņš cēlās tanī naktī un ņēma savas divas sievas un savas divas kalpones un savus vienpadsmit bērnus, un gāja pie Jabokas brasla;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Un viņš tos ņēma un pārveda pār upi, un pārveda, kas tam bija; bet Jēkabs palika viens pats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Tad viens vīrs ar to cīnījās, līdz kamēr diena ausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Un kad Tas redzēja, ka viņu nepārspēja, tad Tas aizskāra viņa ciskas locekli, tā ka Jēkaba ciskas loceklis cīkstoties izgriezās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Un Tas sacīja: palaid Mani, jo gaisma jau aust; bet viņš atbildēja: es Tevi nepalaidīšu, ja Tu mani nesvēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Un Tas uz viņu sacīja: kas tev vārdā? Un viņš sacīja: Jēkabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Tad Tas sacīja: tavu vārdu nebūs vairs saukt Jēkabu, bet Israēli; jo tu esi cīnījies ar Dievu un ar cilvēkiem un esi pārspējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Un Jēkabs vaicāja un sacīja: saki man jel Savu vārdu. Un Tas sacīja: kam tu jautā pēc Mana vārda? Un Tas viņu turpat svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Un Jēkabs nosauca tās vietas vārdu Pniēli: jo es esmu Dievu redzējis vaigu vaigā, un mana dvēsele ir izglābta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Un saule tam uzlēca gar Pniēli aizejot. Un viņš bija klibs ar savu cisku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Tāpēc Israēla bērni līdz šai dienai neēd no dzīslas pie ciskas locekļa, tāpēc ka Jēkabam tā dzīsla pie ciskas locekļa tapa maitāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Un Jēkabs pacēla savas acis un skatījās, un redzi, Ēsavs nāca un četrsimt vīri līdz ar to; tad viņš piedalīja tos bērnus pie Leas un pie Rahēles un pie tām divām kalponēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Un lika tās kalpones un viņu bērnus priekšā, un Leū un viņas bērnus tiem pakaļ, un Rahēli un Jāzepu visu pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Un viņš pats gāja tiem priekšā un klanījās septiņreiz pie zemes, tiekams viņš tapa klāt pie sava brāļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Un Ēsavs tecēja tam pretī un to apkampa un metās viņam ap kaklu un to skūpstīja, un tie raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Un viņš pacēla savas acis un redzēja tās sievas un tos bērnus un sacīja: kas šie tev ir? Un tas sacīja: šie ir tie bērni, ar ko Dievs tavu kalpu svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Tad tās kalpones piegāja, viņas un viņu bērni, un klanījās');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Un Lea piegāja arīdzan un viņas bērni, un klanījās, un pēc nāca Jāzeps un Rahēle un klanījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Un viņš sacīja: kas viss tas tev par pulku, ko es esmu sastapis? Un tas sacīja: lai es žēlastību atrastu tavās acīs, mans kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Un Ēsavs sacīja: man pašam diezgan, brāli; paturi, kas tev ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Bet Jēkabs sacīja: ak ne! Lūdzams, ja es žēlastību esmu atradis tavās acīs, tad ņem manu dāvanu no manas rokas; jo tāpēc es tavu vaigu esmu redzējis, tā kā redz Dieva vaigu, un tu mani mīļi esi saņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Pieņem lūdzams manu svētību, kas tev ir pievesta, jo Dievs mani ar to svētījis, un man ir viss papilnam. Un tas viņu spieda, ka viņš to ņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Un viņš sacīja: nāc, ejam projām, es iešu tev līdzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Bet tas uz viņu sacīja: mans kungs zin, ka man sīki bērni un avis un teļu mātes; kad tos tikai vienu dienu pārdzītu, tad man visi lopiņi apmirtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Ej, kungs, lūdzams savam kalpam papriekš, un es iešu ceļā lēniņām, tā kā mani lopiņi spēj, kas manā priekšā, un tā kā tie bērni spēj, tiekams es nāku pie sava kunga Seīrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Un Ēsavs sacīja: tad nu es atstāšu pie tevis kādus no tiem ļaudīm, kas pie manis. Un tas sacīja: kam tā vajag? Lai žēlastību atrodu sava kunga acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Un Ēsavs tanī dienā griezās atpakaļ pa savu ceļu uz Seīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Bet Jēkabs nogāja uz Sukotu un uzcēla sev namu, un taisīja laidarus saviem lopiem; tādēļ viņš tās vietas vārdu nosauca Sukotu (laidari).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Un Jēkabs nonāca sveiks vesels Šehemas pilsētā, kas ir Kanaāna zemē, no Mezopotamijas nākdams, un apmetās tās pilsētas priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Un viņš pirka vienu zemes gabalu no Hamora, Šehema tēva, bērniem, par simts sudraba gabaliem, un uzcēla tur savu dzīvokli');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Un uztaisīja tur altāri un to nosauca: tas Stiprais Dievs ir Israēla Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Un Dina, Leas meita, ko šī Jēkabam bija dzemdējusi, izgāja apraudzīt tās zemes meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Un Šehems, Hivieša Hamora, tā zemes valdnieka, dēls to ieraudzīja un to ņēma un pie tās gulēja un to piegulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Un viņa sirds pieķērās Dinai, Jēkaba meitai, un viņš mīļoja to jauno meitu un runāja mīlīgi ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Un Šehems runāja ar Hamoru, savu tēvu, un sacīja: ņem man šo meitu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Un Jēkabs dzirdēja, ka tas Dinu, viņa meitu, bija apsmējis; un viņa dēli bija ar ganāmo pulku laukā, un Jēkabs cieta klusu, tiekams tie pārnāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Tad Hamors, Šehema tēvs, izgāja pie Jēkaba, ar to runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Un Jēkaba dēli nāca no lauka, un kad tie to dzirdēja, tad tas tiem vīriem sāpēja un tie apskaitās ļoti, tāpēc ka tas ģeķību bija darījis iekš Israēla, gulēdams pie Jēkaba meitas, un tā nebija darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Un Hamors ar tiem runāja sacīdams: Šehema, mana dēla, sirds pieķērusies jūsu meitai; dodiet to lūdzami viņam par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Un apdraudzinājaties ar mums, - dodiet mums savas meitas un ņemat mūsu meitas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Un dzīvojiet pie mums, un visa tā zeme būs atvērta jūsu priekšā: mītiet, pelnaties un paliekat uz dzīvi iekš tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Un Šehems sacīja uz viņas tēvu un uz viņas brāļiem: lai žēlastību atrodu jūsu acīs, un ko jūs man sacīsiet, to es došu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Prasiet papilnam kroņa maksu un dāvanu, es došu, kā jūs man sacīsiet, dodiet man tikai to jaunavu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Tad Jēkaba dēli atbildēja Šehemam un Hamoram, viņa tēvam, ar viltu un runāja aplinkus, tāpēc ka tas Dinu, viņu māsu, bija apsmējis, un sacīja tiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Mēs to nevaram darīt, ka savu māsu dodam vīram, kam priekšāda, jo tā mums būtu negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Tomēr mēs tad jums būsim pa prātam, ja jūs topat tā kā mēs, apgraizīdami savā starpā visus vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Tad mēs jums dosim savas meitas un sev ņemsim jūsu meitas un dzīvosim ar jums kopā un būsim viena tauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Bet ja jūs mums neklausīsiet un neapgraizīsities, tad mēs ņemsim savu meitu un aiziesim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Un tie vārdi patika Hamoram un Šehemam, Hamora dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Un tas jauneklis nekavējās to darīt, jo viņš mīlēja Jēkaba meitu, un tas bija godāts pār visu sava tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Tad Hamors un Šehems, viņa dēls, nāca tās pilsētas vārtos un runāja ar savas pilsētas vīriem un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Šie vīri ir saticīgi ar mums, lai tie mīt šinī zemē un pelnās, jo redzi, tā zeme ir diezgan plaša priekš viņiem; mēs ņemsim viņu meitas sev par sievām un dosim viņiem savas meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Tomēr tie vīri tik tad grib būt mums pa prātam, ja visi vīri, kas mūsu starpā, top apgraizīti, kā viņi ir apgraizīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Viņu ganāmpulki un viņu sagāds nu visi viņu lopi, vai tie mums nepiederēs? Lai tikai tiem esam pa prātam, tad tie pie mums dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Un Hamoram un Šehemam, viņa dēlam, visi klausīja, kas staigāja pa viņa pilsētas vārtiem, un visi vīri tapa apgraizīti, kas staigāja pa viņa pilsētas vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Un trešā dienā, kad tiem sāpes bija, tad tie divi Jēkaba dēli, Sīmeans un Levis, Dinas brāļi, ņēma ikkatrs savu zobenu un nāca droši tai pilsētā un nokāva visus vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Un nokāva arī Hamoru un Šehemu, viņa dēlu, ar zobena asmeni, un ņēma Dinu no Šehema nama un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Tad Jēkaba dēli uzbruka tiem nokautiem un aplaupīja to pilsētu, tāpēc ka tie viņu māsu bija apsmējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Viņu avis un viņu vēršus un viņu ēzeļus un to, kas bija pilsētā un kas laukā, tie paņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Un visu viņu padomu un visus viņu bērniņus un visas viņu sievas tie gūstīja, un tos aizveda, un visu, kas bija viņu mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Un Jēkabs sacīja uz Sīmeanu un Levi: jūs mani esat apbēdinājuši, smirdošu mani darīdami starp šīs zemes iedzīvotājiem, starp Kanaāniešiem un Fereziešiem, un es esmu mazā skaitā, - ja tie pret mani sapulcināsies, tad tie mani apkaus, un es tapšu izdeldēts, es un mans nams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Un tie sacīja: vai tad viņam bija mūsu māsai darīt tā kā maukai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Un Dievs sacīja uz Jēkabu: celies un ej uz Bēteli un mīti tur, un taisi tur altāri tam Dievam, kas tev parādījās, kad tu bēgi no sava brāļa Ēsava.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Tad Jēkabs sacīja uz savu saimi un uz visiem, kas pie tā bija: metiet nost tos svešos dievus, kas pie jums, un šķīstaties un pārģērbjaties citās drēbēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Ceļamies un ejam uz Bēteli, un tur es taisīšu altāri tam stipram Dievam, kas mani paklausījis bēdu dienā un pie manis bijis tai ceļā, ko esmu staigājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Tad tie Jēkabam deva visus svešos dievus, kas bija viņu rokās, un tās ausu sprādzes, kas bija viņu ausīs, un Jēkabs tos apraka apakš tā ozola, kas ir pie Šehemes. Un tie gāja projām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Un Dievs uzsūtīja bailību tām pilsētām, kas viņiem bija visapkārt, tā ka tie Jēkaba bērniem nedzinās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Un Jēkabs un visi ļaudis, kas bija ar viņu, nonāca Lūzā, kas ir Kanaāna zeme - tā ir Bētele.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Un viņš tur uztaisīja altāri, un nosauca to vietu El-Bēteli, tāpēc, ka Dievs tam bija parādījies, kad tas no sava brāļa bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Un Debora, Rebekas emma(zīdītāja), nomira un tapa aprakta pie Bēteles apakš tā ozola, kam vārdu viņš nosauca raudu ozols.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Un Dievs atkal parādījās Jēkabam, kad tas no Mezopotamijas nāca, un Viņš to svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Un Dievs uz to sacīja: “tavs vārds ir Jēkabs, - tavu vārdu nebūs vairs saukt Jēkabs, bet - Israēls, būs tavam vārdam būt”, un Tas nosauca viņa vārdu Israēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Un Dievs sacīja uz viņu: Es esmu tas visuspēcīgais Dievs, - augļojies un vairojies, no tevis ļaudis un ļaužu pulki celsies, un ķēniņi nāks no taviem gurniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Un šo zemi, ko Es Ābrahāmam un Īzakam esmu devis, Es tev došu, un tavam dzimumam pēc tevis Es došu šo zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Tad Dievs no tā uzbrauca uz augšu tanī vietā, kur Viņš ar to bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Un Jēkabs uzcēla piemiņas zīmi tanī vietā, kur viņš ar To bija runājis, vienu piemiņas akmeni, un viņš to apsvaidīja ar dzeramu upuri un lēja tur eļļu virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Un Jēkabs nosauca tās vietas vārdu, kur Dievs ar to bija runājis, Bēteli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Un tie izgāja no Bēteles, un tur vēl mazs ceļa gabals bija jāiet līdz Efratai, un Rahēle dzemdēja, un viņai nācās grūti dzemdēt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Un kad viņai dzemdēšana tik grūti nācās, tad tā bērnu saņēmēja sacīja: nebīsties, jo šis tev arī būs dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Un kad viņai dvēsele izgāja, ka tā nomira, tad tā nosauca viņa vārdu Ben-Oni, bet viņa tēvs to nosauca Benjaminu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Un Rahēle nomira un tapa aprakta Efratas ceļmalā, - tā ir Bētleme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Un Jēkabs uzcēla piemiņas zīmi uz viņas kapa; šī ir Rahēles kapa zīme līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Tad Israēls aizgāja un uzcēla savu telti viņpus Eder torņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Un notikās, kad Israēls tai zemē dzīvoja, tad Rūbens piegāja un gulēja pie Bilhas, sava tēva liekās sievas, un Israēls to dzirdēja. Un Jēkaba dēlu bija divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Leas dēli bija Rūbens, Jēkaba pirmdzimtais, un Sīmeans un Levis un Jūda un Īsašars un Zebulons,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rahēles dēli bija Jāzeps un Benjamins.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Bilhas, Rahēles kalpones, dēli bija Dans un Naftalus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Un Zilfas, Leas kalpones, dēli bija Gads un Ašers. Šie ir Jēkaba dēli, kas tam dzima Mezopotamijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Un Jēkabs nāca pie Īzaka, sava tēva, uz Mamri pie Kiriat-Arbas, tā ir Hebrone, kur Ābrahāms un Īzaks kā svešinieki bija mituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Un Īzaka dzīvība bija simts un astoņdesmit gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Un Īzaks izlaida garu un nomira un tapa piepulcināts saviem ļaudīm, vecs un diezgan dzīvojis, un viņa dēli Ēsavs un Jēkabs viņu apraka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Šie nu ir Ēsava, tas ir Edoma, radu raksti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ēsavs ņēma sievas no Kanaāna meitām, Adu, Elona, tā Hetieša, meitu, un Aholibamu, Anus meitu, Cibeona, tā Hivieša, dēla meitu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Un Basmatu, Ismaēla meitu, Nebajota māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Un Ada dzemdēja Ēsavam Elifasu, un Basmate dzemdēja Reguēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Un Aholibama dzemdēja Jeūsu un Jaēlamu un Korahu, tie ir Ēsava dēli, kas tam dzima Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Un Ēsavs ņēma savas sievas un savus bērnus un savas meitas un visas sava nama dvēseles un savu ganāmo pulku un visus savus lopus un visu savu mantu, ko tas Kanaāna zemē bija sakrājis, un aizgāja no Jēkaba sava brāļa uz citu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Jo viņu mantas bija padaudz, ka tie nevarēja kopā dzīvot, un tā zeme, kur tie piemita, tiem nepietika viņu lopu pulku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Un Ēsavs mita Seīras kalnos - Ēsavs, tas ir Edoms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Un šie ir Ēsava, Edomiešu tēva, radu raksti, uz Seīras kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Šie ir Ēsava dēlu vārdi: Elifas, Adas, Ēsava sievas, dēls, Reguēls, Basmates, Ēsava sievas, dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Un Elifasa dēli bija Temans, Omars, Zefus un Gaētams un Ķenas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Un Timna bija Elifasa, Ēsava dēla, lieka sieva, un tā dzemdēja Elifasam Amaleku; šie ir Adas, Ēsava sievas, dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Un šie ir Reguēļa dēli: Nahats un Zerus, Šammus un Mizus, šie ir Basmates, Ēsava sievas, dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Un šie Aholibamas, Anus meitas, Cibeona dēla meitas, Ēsava sievas, dēli, un tā dzemdēja Ēsavam Jeūsu un Jaēlamu un Korahu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Šie ir Ēsava dēlu valdnieki: Elifasa, Ēsava pirmdzimtā, dēli: valdnieks Temans, valdnieks Omars, valdnieks Zefus, valdnieks Ķenas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Valdnieks Korahs, valdnieks Gaētams, valdnieks Amaleks: šie ir Elifasa valdnieki Edoma zemē, šie ir Adas dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Un šie ir Reguēļa, Ēsava dēla, dēli: valdnieks Nahats, valdnieks Zerus, valdnieks Šammus, valdnieks Mizus; šie ir Reguēļa valdnieki Edoma zemē: šie ir Basmates, Ēsava sievas, dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Un šie ir Aholibamas, Ēsava sievas, dēli: valdnieks Jeūs, valdnieks Jaēlams, valdnieks Korahs; šie ir Aholibamas, Anus meitas, Ēsava sievas, valdnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Šie ir Ēsava dēli un šie ir viņu valdnieki. Viņš ir Edoms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Šie ir Seīra, Horieša, dēli, kas tai zemē dzīvoja: Lotams un Šobals un Cibeons un Anus un Dišons un Ecers un Dišans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Šie ir Horiešu valdnieki, Seīra dēli, Edoma zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Un Lotama dēli bija Orus un Emams, un Lotama māsa Timna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Un šie ir Šobala dēli: Alvans un Manahats un Ebals, Zevus un Onams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Un šie ir Cibeona dēli: Ajus un Anus; šis ir tas Anus, kas tos siltos avotus tuksnesī ir atradis, kad viņš ganīja sava tēva Cibeona ēzeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Un šie ir Anus bērni: Dišons un Aholibama, Anus meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Un šie ir Dišona dēli: Hemdans un Ešbans un Jetrans un Karans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Šie ir Ecera dēli: Bilhans un Safans un Akans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Šie ir Dišana dēli: Uc un Arans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Šie ir tie Horiešu valdnieki: valdnieks Lotans, valdnieks Šobals, valdnieks Cibeons, valdnieks Anus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Valdnieks Dišons, valdnieks Ecers, valdnieks Dišans; šie ir tie Horiešu valdnieki pēc savām valstīm Seīras zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Un šie ir tie ķēniņi, kas valdījuši Edoma zemē, pirms nekā ķēniņi valdīja pār Israēla bērniem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Belus, Beora dēls, valdīja Edomā, un viņa pilsētas vārds bija Dinaba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Un Belus nomira un viņa vietā valdīja Jobabs, Zerus dēls, no Bacras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Un Jobabs nomira un viņa vietā valdīja Uzams no Temaniešu zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Un Uzams nomira un viņa vietā valdīja Hadads, Bedada dēls, kas Midijanu apkāva Moaba laukā, un viņa pilsētas vārds bija Avite.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Un Hadads nomira un viņa vietā valdīja Zamlus no Mazrekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Un Zamlus nomira un viņa vietā valdīja Sauls no Rehobotes pie tās upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Un Sauls nomira un viņa vietā valdīja Baāl-Anans, Akbora dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Un Baāl-Anans, Akbora dēls, nomira un viņa vietā valdīja Adars, un viņa pilsētas vārds bija Pagus un viņa sievas vārds bija Mehetabeēle, Matredas meita, Mezaābas meitas meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Un šie ir Ēsava valdnieku vārdi pēc viņu radiem, pēc viņu vietām ar saviem vārdiem: Timnas valdnieks, Alvas valdnieks, Jeteta valdnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Aholibamas valdnieks, Elas valdnieks, Pinona valdnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Ķenasa valdnieks, Temana valdnieks, Mibcara valdnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Magdiēla valdnieks, Īrama valdnieks. Šie ir Edoma valdnieki pēc saviem radiem tai zemē, ko bija iemantojuši. Un Ēsavs ir Edomiešu tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Un Jēkabs dzīvoja tai zemē, kur viņa tēvs kā svešinieks bija mitis, Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Šie ir Jēkaba radu raksti: Jāzeps, septiņpadsmit gadus vecs būdams, ganīja avis ar saviem brāļiem, un tas zēns bija pie Bilhas un Zilfas, sava tēva sievu, dēliem, un Jāzeps nesa viņu ļauno slavu tēvam priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Un Israēls mīlēja Jāzepu pār visiem saviem bērniem, jo tas viņam bija dzimis vecumā, un viņš tam taisīja raibus svārkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Un viņa brāļi redzēja, ka tēvs to mīlēja pār visiem viņa brāļiem, un tie to ienīdēja un nevarēja laipni ar to runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Un Jāzeps sapņoja sapni un to stāstīja saviem brāļiem, - tad šie to vēl vairāk ienīdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Un viņš uz tiem sacīja: klausāties jel šo sapni, ko esmu redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Un redzi, mēs sējām kūlīšus laukā, un redzi, mans kūlītis cēlās un stāvēja, un redzi, jūsu kūlīši apstājušies klanījās pret manu kūlīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Tad viņa brāļi uz to sacīja: vai tu mums paliksi par ķēniņu? Vai tu valdīdams pār mums valdīsi? Un tie vēl vairāk to ienīdēja viņa sapņu un viņa stāstu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Un tas sapņoja vēl citu sapni un to teica saviem brāļiem un sacīja: redzi, es vēl citu sapni esmu redzējis, un redzi, saule un mēnesis un vienpadsmit zvaigznes klanījās priekš manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Un kad viņš to stāstīja savam tēvam un saviem brāļiem, tad viņa tēvs to aprāja un uz to sacīja: kas tas par sapni, ko tu esi sapņojis? Vai es un tava māte un tavi brāļi patiesi nāksim pie zemes klanīties tavā priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Un viņa brāļi to skauda, bet viņa tēvs šo vārdu paturēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Un viņa brāļi gāja ganīt sava tēva lopus Šehemē. Tad Israēls sacīja uz Jāzepu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Vai tavi brāļi negana Šehemē? Nāc, es tevi sūtīšu pie tiem; un tas sacīja: redzi, še es esmu. Un viņš uz to sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Ej jel, lūko, kā taviem brāļiem klājās un kā lopiņiem klājās, un nes man vēsti atpakaļ. Un viņš to izsūtīja no Hebrones ielejas, un tas nāca uz Šehemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Un viens vīrs viņu atrada un redzi, viņš maldījās pa lauku; tad tas vīrs to vaicāja sacīdams, ko tu meklē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Un tas sacīja: es meklēju savus brāļus, saki man lūdzams, kur tie gana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Tad tas vīrs sacīja: tie no šejienes aizgājuši, jo es dzirdēju tos sakām: iesim uz Dotanu; un Jāzeps gāja saviem brāļiem pakaļ un atrada tos Dotanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Un tie to ieraudzīja no tālienes, un pirms tas tuvu pie viņiem atnāca, tie sarunājās viņu nokaut,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Un sacīja viens uz otru: redzi, še nāk tas sapņotājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Un nu nāciet, nokausim to un iemetīsim to kādā bedrē un sacīsim: negants zvērs to aprijis; tad redzēsim, kas būs no viņa sapņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Un Rūbens to dzirdēja un to izpestīja no viņu rokām un sacīja: nenokausim viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Un Rūbens uz tiem sacīja: neizlejat asinis, metiet viņu tai bedrē, kas te tuksnesī, un nepieliekat rokas pie viņa, - lai viņš to izpestītu no viņu rokām un pārvestu savam tēvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Un notikās, kad Jāzeps atnāca pie saviem brāļiem, tad tie Jāzepam novilka svārkus, tos raibos, kas tam bija mugurā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Un tie to ņēma un iemeta bedrē, bet tā bedre bija tukša, un tur ūdens nebija iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Pēc tie apsēdās maizi ēst un pacēla savas acis un skatījās, un redzi, Ismaēliešu pulks nāca no Gileādas, un viņu kamieļi nesa dārgas zāles, balzamu un mirres; tie gāja, to nonest uz Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Tad Jūda sacīja uz saviem brāļiem: ko tas mums līdz, ja savu brāli nokaujam un viņa asinis slēpjam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Nāciet, pārdosim viņu tiem Ismaēliešiem un nepieliksim savas rokas pie viņa, jo viņš ir mūsu brālis, mūsu miesa. Un viņa brāļi tam klausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Tiem Midianiešu vīriem, tiem tirgotājiem, garām ejot, tie izvilka un izcēla Jāzepu no bedres un pārdeva Jāzepu tiem Ismaēliešiem par divdesmit sudraba gabaliem, un tie aizveda Jāzepu uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Un Rūbens gāja atpakaļ pie tās bedres un redzi, Jāzeps nebija bedrē; tad tas saplēsa savas drēbes');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Un griezās atpakaļ pie saviem brāļiem un sacīja: tā puisēna tur nav un es, - kur man būs palikt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Un tie ņēma Jāzepa svārkus un nokāva āzi un iemērca tos svārkus asinīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Un nosūtīja tos raibos svārkus un lika tos nonest savam tēvam un sacīja: šos esam atraduši; apraugi jel, vai tie ir tava dēla svārki, vai nē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Un tas tos pazina un sacīja: tie ir mana dēla svārki; nikns zvērs viņu ir aprijis, plosīt tas Jāzepu saplosījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Un Jēkabs pārplēsa savas drēbes un apvilka maisu ap saviem gurniem un bēdājās pēc sava dēla ilgu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Tad visi viņa dēli un visas viņa meitas cēlās, viņu iepriecināt, bet viņš negribējās iepriecinājams būt un sacīja: ar bēdām es noiešu kapā pie sava dēla. Un viņa tēvs to apraudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Un tie Midianieši to pārdeva Ēģiptes zemē Potifaram, ķēniņa Faraona kambarjunkuram un sargu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Un notikās tanī laikā, ka Jūda no saviem brāļiem nogāja un apmetās pie kāda Adulamnieku vīra, Hīras vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Un Jūda redzēja tur kāda Kanaāniešu vīra meitu, un viņa vārds bija Šua, un viņš to ņēma un gāja pie tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Un tā tapa grūta un dzemdēja dēlu un nosauca viņa vārdu Ģeru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Un tā tapa atkal grūta un dzemdēja dēlu un nosauca viņa vārdu Onanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Un tā dzemdēja vēl vienu dēlu un nosauca viņa vārdu Šelu, un viņš bija Ķezibā, kad tā to dzemdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Un Jūda ņēma sievu priekš Ģera, sava pirmdzimtā, un viņas vārds bija Tamāre.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Bet Ģers, Jūdas pirmdzimtais, bija ļauns Tā Kunga priekšā, tāpēc Tas Kungs to nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Tad Jūda sacīja Onanam: ej pie sava brāļa sievas un ņem to sava brāļa vietā un cel dzimumu savam brālim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Bet Onans zinādams, ka tas dzimums viņam nepiederēs, pie sava brāļa sievas iedams, tam lika izgaist zemē, lai savam brālim nedotu dzimuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Un Tam Kungam nepatika, ko viņš darīja, un viņš to arīdzan nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Tad Jūda sacīja uz savu vedeklu Tamāri: paliec atraitne sava tēva namā, tiekams Šelus, mans dēls, pieaug; jo viņš domāja: vai viņam arī nebūs jāmirst, kā viņa brāļiem. Un Tamāre nogāja un dzīvoja sava tēva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Kad nu labs laiks bija pagājis, tad Šuas meita, Jūda sieva, nomira; pēc tam Jūda iepriecinājās un gāja pie saviem avju cirpējiem uz Timnu, viņš un Hīra, viņa draugs, tas Adulamnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Un Tamārei tapa vēstīts un sacīts: redzi, tavs tēvocis iet uz Timnu, savas avis cirpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Tad viņa novilka savas atraitņu drēbes un apsedzās ar vaiga apsegu un aptinās un apsēdās priekš Enaima vārtiem, kas ir uz Timnas ceļa; jo tā bija redzējusi, ka Šelus bija pieaudzis un ka viņa tam nebija dota par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Un Jūda to redzēja un šķita, to esam mauku, tāpēc ka tā savu vaigu bija apsegusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Un noklīda pie tās ceļmalā un sacīja: nāc jel, laid man pie tevis ieiet; jo viņš nezināja, to savu vedeklu esam. Un tā sacīja: ko tu man dosi, ja tu pie manis ieiesi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Un tas sacīja: es tev sūtīšu vienu āzi no ganāmpulka. Un tā sacīja: tad dod man ķīlas, tiekams tu to sūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Tad tas sacīja: kas tās tādas ķīlas, ko man tev būs dot? Un tā atbildēja: tavs aizspiežamais gredzens un tava virkne un tava niedre, kas tavā rokā. Un tas viņai to deva un iegāja pie tās; un tā tapa grūta no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Un tā cēlās un aizgāja un nolika to apsegu un apvilka savas atraitņu drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Un Jūda sūtīja to āzi caur savu draugu, to Adulamnieku, atņemt tās ķīlas no tās sievas rokas; bet tas to neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Tad tas vaicāja tās vietas ļaudis sacīdams: kur ir tā mauka, kas Enaimā uz ceļa sēdējusi? Un tie sacīja: še maukas nav bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Un tas atgriezās pie Jūdas un sacīja: es to neesmu atradis, un tās vietas ļaudis arīdzan saka: še maukas nav bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Tad Jūda sacīja: lai tā to sev patur, ka netopam kaunā; redzi, es šo āzi esmu sūtījis, un tu viņas neesi atradis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Un notikās pēc kādiem trim mēnešiem, tad Jūdam tapa vēstīts un sacīts: Tamāre, tava vedekla, maucību dzinusi, un redzi, tā ir arī grūta no maukošanas. Tad Jūda sacīja: izvediet to ārā, ka tā top sadedzināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Kad nu tā tapa izvesta, tad tā sūtīja pie sava tēvoča un sacīja: no tā vīra, kam šās lietas pieder, es esmu grūta; un tā sacīja: vai pazīsti jel, - kam tas aizspiežamais gredzens un šī virkne un šī niedre pieder?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Un Jūda tās pazina un sacīja: tā sieva ir taisnāka nekā es, tāpēc ka es viņu savam dēlam Šelum neesmu devis. Un viņš to vairs neatzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Un tai dzemdējot, redzi, tai bija dvīņi viņas miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Un kad tā dzemdēja, tad viens roku izbāza, un bērnu saņēmēja to ņēma un apsēja sarkanu pavedienu ap to roku un sacīja: šis nāks pirmais ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Un kad tas to roku ievilka, redzi, tad nāca viņa brālis ārā; un tā sacīja: kāpēc tu sev plēsumu esi plēsis? Un tā viņa vārdu nosauca Perec (plēsis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Un pēc tam viņa brālis nāca ārā, ap kā roku tas sarkanais pavediens bija, un tā viņa vārdu nosauca Zerus (atspīdums).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Un Jāzeps tapa novests uz Ēģipti, un Potifars, Faraona kambarjunkurs un sargu virsnieks, viens ēģiptiešu vīrs, to nopirka no to Ismaēliešu rokas, kas to uz turieni bija noveduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Un Tas Kungs bija ar Jāzepu, tā ka tam viss laimīgi izdevās, un tas bija sava kunga, tā ēģiptieša, namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Un viņa kungs redzēja, ka Tas Kungs bija ar viņu, un ka Tas Kungs visiem darbiem labi lika izdoties caur viņa roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Tad Jāzeps atrada žēlastību viņa priekšā un viņam kalpoja, un viņš to iecēla pār savu namu, un deva viņa rokā visu, kas tam piederēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Un no tā laika, kad viņš to bija cēlis pār savu namu un pār visu, kas viņam piederēja, Tas Kungs svētīja tā ēģiptieša namu Jāzepa labad, un Tā Kunga svētība bija visās lietās, kas viņam piederēja, sētā un laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Un visu, kas tam piederēja, viņš nodeva Jāzepa rokās, un negādāja pats par neko, kā vien par to maizi, ko ēda. Un Jāzeps bija skaists no auguma un skaists no ģīmja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Un notikās pēc šīm lietām, ka viņa kunga sieva savas acis uzmeta uz Jāzepu un sacīja: guli pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Bet viņš liedzās un sacīja uz sava kunga sievu: redzi, mans kungs negādā par neko, kas ir namā, un visu, kas viņam pieder, viņš ir devis manā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Neviens šinī namā nav lielāks pār mani, un viņš man neko nav aizliedzis, bez vien tevi, tāpēc ka tu esi viņa sieva; kā tad lai es tādu lielu ļaunumu daru un pret Dievu grēkoju?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Un kad viņa ikdienas to uz Jāzepu runāja, un tas viņai nepaklausīja, ka pie viņas būtu gulējis un ap viņu bijis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Tad notikās kādā dienā Jāzepam namā nākot savu darbu padarīt, un no nama ļaudīm nevienam mājās neesot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Ka tā viņu sagrāba pie drēbēm un sacīja: guli pie manis. Bet tas pameta savas drēbes viņas rokā un izbēga un izgāja ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Kad nu tā redzēja, ka tas savas drēbes viņas rokā bija pametis un izbēdzis ārā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Tad tā sasauca savu saimi un runāja uz tiem un sacīja: raugāt, viņš to Ebreju vīru pie mums ir atvedis mūs apsmiet; tas nāca pie manis gulēt un es brēcu visā galvā(skaļā balsī).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Un kad tas dzirdēja, ka es savu balsi pacēlu un brēcu, tad tas pameta savas drēbes pie manis un aizbēga un izmuka ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Un tā lika viņa drēbes sev līdzās, kamēr viņas kungs pārnāca mājā; tad tā uz viņu runāja pēc šiem vārdiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Un sacīja: tas Ebreju kalps, ko tu mums esi atvedis, nāca pie manis, mani apsmiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Un kad es savu balsi pacēlu un brēcu, tad tas pameta savas drēbes pie manis un izbēga ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Un kad viņa kungs dzirdēja savas sievas vārdus, kā tā uz viņu bija runājusi sacīdama: tā un tā man tavs kalps darījis, tad viņa kungs apskaitās ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Un Jāzepa kungs to ņēma un to ielika cietuma namā, tanī vietā, kur ķēniņa cietuma ļaudis tapa apsargāti; un viņš bija tur cietuma namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Bet Tas Kungs bija ar Jāzepu, un tam parādīja apžēlošanu un tam lika atrast žēlastību cietuma sarga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Un cietuma sargs deva Jāzepa rokā visus cietuma ļaudis, kas cietuma namā bija, un viss, kas tur bija jādara, to viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Cietuma sargs neraudzīja ne uz vienu lietu, kas bija viņa rokā, jo Tas Kungs bija ar viņu, un ko vien viņš darīja, tam Tas Kungs lika labi izdoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Un pēc šīm lietām Ēģiptes ķēniņa dzēriena devējs un maizes cepējs apgrēkojās pret savu kungu, Ēģiptes ķēniņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Tā ka Faraons apskaitās par saviem diviem virsniekiem, par dzēriena devēju virsnieku un par maizes cepēju virsnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Un viņš tos lika iemest cietumā, sargu virsnieka namā, turpat, kur Jāzeps bija saistīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Un sargu virsnieks tiem iedeva Jāzepu, ka tas tiem kalpotu, un tie bija kādu laiku cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Un tie abi vienā naktī sapņoja sapņus, katrs savu sapni, Ēģiptes ķēniņa dzēriena devējs un maizes cepējs, kas cietuma namā bija saistīti, - katrs sapnis bija savādi izstāstāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Un Jāzeps no rīta pie tiem nāca un tos apraudzīja, un redzi, tie bija noskumuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Tad tas vaicāja Faraona virsniekus, kas pie tā bija cietumā, sava kunga namā, un sacīja: kāpēc jūsu vaigi šodien tik skumīgi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Un šie tam sacīja: mēs sapni esam sapņojuši un še nav neviena, kas mums to izstāsta. Un Jāzeps tiem atbildēja: vai izstāstīšanas nepieder Dievam? Teiciet jel man to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Tad dzēriena devēju virsnieks Jāzepam izteica savu sapni un uz to sacīja: redzi jel, savā sapnī es redzēju vīnakoku savā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Un tam vīnakokam bija trīs zari, un tas izplauka, viņa zaļums auga, ziedēja, un viņa ogas ienācās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Un Faraona biķeris bija manā rokā, un es ņēmu tās ogas un tās izspiedu Faraona biķerī un devu biķeri Faraona rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Tad Jāzeps uz to sacīja: šī ir viņa izstāstīšana, - tie trīs zari ir trīs dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Pēc trim dienām Faraons tavu galvu paaugstinās un tevi iecels atkal tavā amatā, un tu dosi Faraonam biķeri viņa rokā pēc pirmaja ieraduma, kad tu biji viņa dzēriena devējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Bet piemini mani, kad tev labi klāsies, un dari lūdzams žēlastību pie manis un piemini mani pie Faraona un dari, ka es topu izlaists no šā nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Jo es zagšus esmu nozagts no Ebreju zemes, un arī nekā ļauna neesmu darījis, ka tie mani bedrē iemetuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Un kad maizes cepēju virsnieks redzēja, ka tas labi bija izstāstījis, tad tas Jāzepam sacīja: man arī bija sapnis, un redzi, trīs maizes kurvji bija uz manas galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Un virsējā kurvī bija no visāda Faraona ēdiena, kas ir beķera cepums, un putni ēda no tā kurvja uz manas galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Tad Jāzeps atbildēja un sacīja. Šī ir viņa izstāstīšana, - tie trīs kurvji ir trīs dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Un pēc trim dienām Faraons tavu galvu pacels un tevi pakārs karātavās un putni ēdīs tavu miesu no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Un notikās trešā dienā, Faraona dzimšanas dienā, ka viņš visiem saviem kalpiem dzīres darīja, un viņš paaugstināja dzēriena devēju virsnieka galvu un maizes cepēju virsnieka galvu starp saviem kalpiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Un iecēla dzēriena devēju virsnieku atkal viņa vietā, un tas biķeri deva Faraonam rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Un maizes cepēju virsnieku viņš lika pakārt, - tā kā Jāzeps tiem bija izstāstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Bet dzēriena devēju virsnieks nepieminēja Jāzepu, bet viņu aizmirsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Un pēc diviem gadiem Faraons redzēja sapni un redzi, viņš stāvēja upes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Un redzi, no upes izkāpa septiņas govis krāšņu augumu un treknām miesām, un tās ganījās niedrēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Un redzi, septiņas citas govis izkāpa pēc šīm no upes, nejauku augumu un liesām miesām, un piestājās pie tām citām govīm upes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Un tās govis nejauku izskatu un liesām miesām ierija tās septiņas treknās govis krāšņu izskatu; - tad Faraons atmodās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Pēc viņš atkal aizmiga un sapņoja otrkārt. Un redzi, septiņas vārpas auga uz viena stiebra, briedušas un brangas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Un redzi, septiņas tievas un austriņa kaltētas vārpas radās pēc tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Un tās tievās vārpas ierija tās septiņas briedušās un pilnās vārpas. Tad Faraons atmodās, un redzi, tas bija sapnis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Un notikās no rīta, tad viņš bija bēdīgs savā garā, un sūtīja un aicināja visus ēģiptiešu zīlniekus un visus gudros, kas tur bija, un Faraons tiem teica savus sapņus, bet neviena nebija, kas tos Faraonam izstāstītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Tad dzēriena devēju virsnieks runāja uz Faraonu un sacīja: es pieminu šodien savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Kad Faraons bija apskaities par saviem kalpiem un mani ielika cietumā, sargu virsnieka namā, mani un maizes cepēju virsnieku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Tad mums bija vienā naktī sapnis, ikvienam savs sapnis, savādi izstāstāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Un tur bija pie mums viens Ebreju jauneklis, sargu virsnieka kalps, un mēs tam tos pasacījām, un viņš mums mūsu sapņus izstāstīja, ikvienam tas to izstāstīja pēc viņa sapņošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Un kā tas mums ir izstāstījis, tāpat tas noticis; mani Faraons atkal iecēlis manā vietā un viņu pakāris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Tad Faraons sūtīja un aicināja Jāzepu, un tie tam ātri lika iziet no bedres, un viņš apcirpās un apvilka citas drēbes un nāca pie Faraona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Tad Faraons sacīja uz Jāzepu: es esmu sapņojis sapni, un neviena nav, kas to izstāsta; bet es esmu dzirdējis par tevi sakām, kad tu sapni dzirdot, tad tu to varot izstāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Un Jāzeps atbildēja Faraonam un sacīja: tas nestāv pie manis; Dievs Faraonam sludinās labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Un Faraons sacīja uz Jāzepu: redzi, es sapnī stāvēju upes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Un redzi, tur izkāpa no upes septiņas govis treknām miesām un krāšņu izskatu un ganījās niedrēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Un redzi, septiņas citas govis izkāpa pēc tām, liesu un ļoti nejauku augumu un izdēdējušām miesām, es tik nejaukas, kā šās, visā Ēģiptes zemē neesmu redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Un tās izdēdējušās un nejaukās govis ierija tās septiņas pirmās treknās govis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Un kad tās no viņām bija ierītas, nevarēja manīt, ka tās bija viņu iekšās, un tās izskatījās nejaukas tāpat kā papriekš. Tad es atmodos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Pēc tam es redzēju savā sapnī, un redzi, septiņas vārpas izauga no viena stiebra, pilnas un brangas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Un redzi, septiņas sakaltušas, tievas un austriņa kaltētas vārpas izplauka pēc tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Un tās septiņas tievās vārpas ierija tās septiņas brangās vārpas. Un es to tiem zīlniekiem esmu teicis, bet neviena nav, kas to var izstāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Tad Jāzeps sacīja uz Faraonu. Faraona sapņi ir vienādi. Dievs Faraonam ir darījis zināmu, ko Viņš apņēmies darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Tās septiņas krāšņās govis ir septiņi gadi, un tās septiņas brangās vārpas ir septiņi gadi, - tie sapņi ir vienādi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Un tās septiņas izdēdējušās un nejaukās govis, kas pēc tām izkāpa, ir septiņi gadi, un tās septiņas tievās un austriņa kaltētās vārpas būs septiņi bada gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Šis ir tas vārds, ko es uz Faraonu esmu runājis: Dievs Faraonam ir parādījis, ko Viņš apņēmies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Redzi, septiņi it auglīgi gadi nāks pār visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Bet pēc tiem nāks septiņi bada gadi; tad tas pilnums Ēģiptes zemē taps aizmirsts, un bads klaji apēdīs zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Un to pilnumu vairs nemanīs tai zemē aiz tā bada pēc tam, jo tas būs pārlieku grūts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Un, ka tas sapnis Faraonam divreiz ir rādījies, tas ir tāpēc, ka Dievs to stipri apņēmies un Dievs steigšus to darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Un nu lai Faraons lūko pēc viena prātīga un gudra vīra un to lai ieceļ pār Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Lai Faraons tā dara un lai ieceļ uzraugus pār zemi un lai ņem piekto tiesu no Ēģiptes zemes pa tiem septiņiem bagātiem gadiem, un lai tie sakrāj visādu barību pa šiem nākamiem auglīgiem gadiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Un lai tie saber labību apakš Faraona rokas par barību pilsētā, un lai to paglabā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Tad būs barība zemei par padomu, kamēr tie septiņi bada gadi būs Ēģiptes zemē, ka zeme no bada netop izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Un šie vārdi patika Faraonam un visiem viņa kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Un Faraons sacīja uz saviem kalpiem: kur mēs atrastu tādu vīru, iekš kā ir Dieva Gars?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Tad Faraons sacīja uz Jāzepu: tāpēc ka Dievs tev visas šīs lietas ir darījis zināmas, nav neviena tik prātīga un gudra, kā tu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tev būs būt pār manu namu, un visiem maniem ļaudīm būs klausīt tavam vārdam; pēc tā goda krēsla vien es būšu lielāks nekā tu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Un Faraons sacīja uz Jāzepu: redzi, es tevi esmu iecēlis pār visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Un Faraons novilka savu gredzenu no savas rokas un deva to Jāzepam rokā, un to apģērba ar dārga audekla drēbēm un apkāra zelta ķēdes ap viņa kaklu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Un tam lika braukt uz saviem otrajiem ratiem, kas viņam bija, un viņa priekšā sauca: klanāties! Un viņš to iecēla pār visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Un Faraons sacīja uz Jāzepu: es esmu Faraons, tomēr bez tavas ziņas nevienam ne roku, ne kāju nebūs pacelt visā Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Un Faraons Jāzepu nosauca Capnat-Paneak (pasaules glābējs) un tam deva par sievu Asnatu, Potifera, Onna priestera, meitu. Un Jāzeps devās ceļā pa visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Un Jāzeps bija trīsdesmit gadus vecs, kad viņš priekš Ēģiptes ķēniņa Faraona stāvēja. Un Jāzeps aizgāja no Faraona un pārstaigāja visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Un zeme tanīs septiņos bagātos gados izdeva bagātus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Un viņš sakrāja to septiņu gadu labību, kas bija Ēģiptes zemē, visu un lika to labību pilsētās; to labību no ikvienas pilsētas tīruma, kas ap to bija, viņš tanī nolika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Tā Jāzeps sabēra pārlieku daudz labības, kā smiltis jūrmalā, ka beidzot mitējās skaitīt, jo tā bija neskaitāma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Un Jāzepam piedzima divi dēli, pirms nekā tie bada gadi nāca; tos Asnata, Potifera, Onna priestera, meita, viņam dzemdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Un Jāzeps tā pirmdzimtā vārdu nosauca Manasu, jo Dievs man ir licis aizmirst visu manu grūtumu un visu mana tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Un tā otrā vārdu viņš nosauca Efraīm, jo Dievs man licis augt manā bēdu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Un tie septiņi bagātie gadi beidzās, kas bija Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Un tie septiņi bada gadi sāka nākt, tā kā Jāzeps bija sacījis, un tur bija bads visapkārt, bet pa visu Ēģiptes zemi bija maize.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Kad nu visa Ēģiptes zeme arī badu cieta, tad tie ļaudis brēca uz Faraonu pēc maizes. Un Faraons sacīja visiem ēģiptiešiem: ejat pie Jāzepa, - ko tas jums sacīs, to dariet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Un bads bija pa visu zemi, un Jāzeps atvēra visas klētis un pārdeva ēģiptiešiem, jo bads palika jo dienas jo lielāks Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Un visas citas zemes nāca uz Ēģiptes zemi pie Jāzepa pirkt, jo bads bija liels pa visām zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Kad nu Jēkabs redzēja, ka labība bija Ēģiptes zemē, tad viņš saviem dēliem sacīja: ko jūs skatāties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Un viņš sacīja: redzi, es esmu dzirdējis, labību esam Ēģiptes zemē, noejat turp un pērciet mums no turienes, lai dzīvojam un nemirstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Tad desmit Jāzepa brāļi nogāja, labības pirkt no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Bet Benjaminu, Jāzepa brāli, Jēkabs nesūtīja ar viņa brāļiem, jo tas sacīja: ka to kāda nelaime neaizņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Tā Israēla dēli nāca, labības pirkt līdz ar citiem, kas turp gāja, jo bads bija arī Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Un Jāzeps bija tas valdītājs pār zemi un pārdeva visiem tās zemes ļaudīm, un Jāzepa brāļi nāca un klanījās viņa priekšā ar vaigu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Tad Jāzeps redzēja savus brāļus un tos pazina, bet viņš likās pret tiem svešs, un runāja ar tiem bargi un sacīja uz tiem: no kurienes jūs nākat? Un tie sacīja: no Kanaāna zemes, maizes pirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Un Jāzeps pazina savus brāļus, bet tie viņu nepazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Un Jāzeps pieminēja savus sapņus, ko viņš par tiem bija sapņojis, un viņš uz tiem sacīja: jūs esat izlūki, jūs esat nākuši raudzīt, kur zemei var piekļūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Un tie uz viņu sacīja: nē, mans kungs, tavi kalpi ir nākuši, maizes pirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Mēs visi esam viena vīra dēli, mēs esam taisni ļaudis, tavi kalpi nav izlūki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Un viņš uz tiem sacīja: nē, bet jūs esat nākuši izlūkot, kur zemei var piekļūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Un tie sacīja: mēs tavi kalpi bijām divpadsmit brāļi, viena paša vīra dēli Kanaāna zemē, un redzi, tas jaunākais vēl šodien ir pie mūsu tēva, bet tā viena vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Tad Jāzeps uz tiem sacīja: tā tas ir, kā es uz jums esmu runājis un sacījis: jūs esat izlūki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Pie tam jūs tapsiet pārbaudīti; tik tiešām kā Faraons dzīvo, jūs no šejienes netiksiet projām, ja jūsu jaunākais brālis nenāk šurpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sūtiet vienu no jums, kas atved jūsu brāli, bet jūs paliekat cietumā, tad jūsu vārdi taps pārbaudīti, vai pie jums ir patiesība, un ja ne, tik tiešām kā Faraons dzīvo, tad jūs esat izlūki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Un viņš tos kopā lika trīs dienas cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Un trešā dienā Jāzeps uz tiem sacīja: dariet tā, tad jūs dzīvosiet; es bīstos Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Ja jūs esat taisni ļaudis, tad lai viens no jūsu brāļiem paliek saistīts cietumā, un jūs ejat, pārvediet to labību, tādēļ ka bads jūsu mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Un atvediet savu jaunāko brāli pie manis, tad jūsu vārdi taps atrasti taisni, un jūs nemirsiet; un tie tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Tad tie sacīja viens uz otru: patiesi, mēs esam noziegušies pret savu brāli, ka mēs viņa dvēseles bēdas redzējām, kad viņš no mums žēlastības lūdzās, un neklausījām; tādēļ šās bēdas nāk pār mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Un Rūbens tiem atbildēja un sacīja: vai es jums to neteicu sacīdams: neapgrēkojaties pret to bērnu, bet jūs neklausījāt? Un nu redzi, viņa asinis top meklētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Un tie nezināja, ka Jāzeps to saprata, jo tur bija tulks viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Un viņš no tiem novērsās un raudāja, un atkal pie tiem atgriezās un ar tiem runāja, un ņēma no viņu vidus Sīmeanu un to saistīja priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Un Jāzeps pavēlēja viņu maisus pildīt ar labību un viņu naudu atlikt ikkatram savā maisā, un tiem dot ceļa barību uz ceļu; un tiem tā tapa darīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Un tie uzkrāva savu labību uz saviem ēzeļiem un aizgāja no turienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Kad nu viens no tiem savu maisu atraisīja, savu ēzeli barot mājas vietā, tad tas ieraudzīja savu naudu, un redzi, tā bija viņa maisa virsgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Un tas sacīja uz saviem brāļiem: mana nauda man ir atlikta, un redzi, tā ir manā maisā. Tad tiem sirds iztrūkās un tie pārbijās viens uz otru sacīdami: kas tas ir, ko Dievs mums ir darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Un tie nāca pie Jēkaba, sava tēva, uz Kanaāna zemi un teica tam visu, kas tiem bija noticis, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Tas vīrs, tas zemes kungs, runāja bargi ar mums un mūs turēja par zemes izlūkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Tad mēs tam sacījām: mēs esam taisni ļaudis, mēs neesam izlūki bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Mēs bijām divpadsmit brāļi, sava tēva dēli, viena vairs nav, un tas jaunākais vēl šodien ir pie mūsu tēva Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Un tas vīrs, tas zemes kungs, mums sacīja: pie tam es nomanīšu, jūs esam taisnus: pametiet vienu no saviem brāļiem pie manis un ņemiet, ko jums vajag, un noejat,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Un atvediet savu jaunāko brāli pie manis, tad es manīšu, jūs neesam izlūkus, bet taisnus ļaudis. Jūsu brāli es jums atdošu un jums ļaušu šinī zemē pirkt un pārdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Un kad tie savus maisus izbēra, redzi, tad ikviens atrada savu naudas mučkuli(maisiņu) savā maisā, un tie ieraudzīja savus naudas mučkuļus, viņi un viņu tēvs, un tie izbijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Tad Jēkabs, viņu tēvs, uz tiem sacīja: jūs man paņemat manus bērnus: Jāzepa vairs nav un Sīmeana vairs nav, un Benjaminu jūs ņemsiet; viss tas nāk man virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Tad Rūbens runāja ar savu tēvu un sacīja: ja es to pie tevis neatvedīšu atpakaļ, tad nokauj manus divus dēlus; dod viņu manā rokā, tad es viņu pie tevis atvedīšu atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Bet viņš sacīja: manam dēlam nebūs noiet ar jums, jo viņa brālis ir miris, un tas ir viens pats atlicis. Ja tam kāda nelaime notiks uz ceļa, kur jūs iesiet, tad jūs manus sirmos matus ar sirdēstiem novedīsiet bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Un bads bija grūts tanī zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Un kad tā labība, ko tie no Ēģiptes bija atveduši, jau bija izlietojuši, tad viņu tēvs uz tiem sacīja: noejat atkal un pērciet mums maizes kādu mazumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Un Jūda uz to runāja un sacīja: tas vīrs mums stipri piekodinājis un sacījis: jūs manu vaigu neredzēsiet, ja jūsu brālis nav jums līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Ja tad tu mūsu brāli mums sūtīsi līdz, tad mēs gribam noiet un pirkt maizes priekš tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Bet ja tu to nesūtīsi, tad mēs nenoiesim, jo tas vīrs mums ir sacījis: jums nebūs manu vaigu redzēt, ja jūsu jaunākais brālis jums nav līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Tad Israēls sacīja: kāpēc jūs man tik ļauni esat darījuši, tam vīram sacīdami, ka jums vēl viens brālis esot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Un tie sacīja: tas vīrs jautāja jautādams pēc mums un pēc mūsu radiem un sacīja: vai jūsu tēvs vēl dzīvs? Vai jums vēl viens brālis? Tad mēs viņam atbildējām, kā viņš mums jautāja; kā tad mēs to varējām zināt, ka tas sacīs: vediet savu brāli šurp?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Tad Jūda sacīja uz Israēli, savu tēvu: sūti to zēnu man līdz, tad mēs celsimies un noiesim, lai dzīvojam un nemirstam, ne mēs, ne tu pats, ne mūsu bērniņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Es galvoju par viņu, no manas rokas tev būs viņu prasīt; ja es to pie tevis nevedīšu atpakaļ un to nestādīšu priekš tavām acīm, tad es visu savu mūžu gribu noziedzīgs būt tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Jo ja mēs nebūtu kavējušies, mēs tagad jau otru reizi būtu pārnākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Tad viņu tēvs Israēls uz tiem sacīja: ja tam nu tā būs būt, tad dariet tā: ņemiet no šās zemes visteicamiem augļiem savos traukos un nonesiet tam vīram dāvanu, balzama kādu mazumu un kādu mazumu medus, dārgas zāles un mirres, riekstus un mandeles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Ņemiet arīdzan otrtik naudas savā rokā, un to naudu, kas jūsu maisu virsgalā atlikta, nesiet atpakaļ savā rokā, tiem jau tur būs misējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Ņemiet arī savu brāli un ceļaties un ejat atkal pie tā vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Bet tas visuvarenais Dievs lai jums dod žēlastību tā vīra priekšā, ka tas atlaiž jūsu otru brāli un Benjaminu. Bet es esmu tā kā kam bērni rautin atrauti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Tad tie vīri ņēma to dāvanu, un ņēma otrtik naudas savā rokā un Benjaminu, un cēlās un nogāja uz Ēģiptes zemi un stājās Jāzepa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Kad nu Jāzeps Benjaminu pie tiem ieraudzīja, tad viņš sacīja tam, kas bija pār viņa namu: ieved tos vīrus namā un nokauj kādu kaujamu lopu un taisi ēdienu, jo tie vīri pie manis ēdīs pusdienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Un tas vīrs darīja, kā Jāzeps bija sacījis, un tas vīrs ieveda tos vīrus Jāzepa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Tad tie vīri bijās, kad tos veda Jāzepa namā, un sacīja: tās naudas dēļ, ko viņu reiz\' atdabūjām savos maisos, mēs esam ievesti, lai viņš mums var uzbrukt un mums uzmākties un mūs par vergiem ņemt un mūsu ēzeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Tad tie piegāja pie tā vīra, kas bija pār Jāzepa namu, un runāja ar to priekš nama durvīm');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Un sacīja: ak mans kungs, mums viņu reiz\' bija jānāk, labības pirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Un kad bijām nākuši mājas vietā un atraisījām savus maisus, redzi, tad ikvienam tā nauda bija viņa maisa virsgalā ar pilnu svaru, un mēs to esam atkal atnesuši savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Mēs arī esam atnesuši citu naudu savā rokā, maizes pirkt, mēs nezinām, kas mūsu naudu mūsu maisos ielicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Un tas sacīja: esiet ar mieru, nebīstaties! Jūsu Dievs un jūsu tēva Dievs jums devis jūsu maisos apslēptu mantu; jūsu nauda man rokā tikusi. Un viņš izveda Sīmeanu pie tiem ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Pēc viņš tos vīrus ieveda Jāzepa namā un tiem deva ūdeni, un tie mazgāja savas kājas; un viņš deva viņu ēzeļiem ēdamo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Un tie sataisīja to dāvanu, tiekams Jāzeps nāca uz pusdienu; jo tie bija dzirdējuši, ka tiem tur bija maizi ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Kad nu Jāzeps nāca namā, tad tie viņam namā atnesa to dāvanu, kas bija viņu rokās, un metās viņa priekšā pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Un viņš jautāja, kā tiem klājās, un sacīja: kā klājās jūsu vecajam tēvam, par ko jūs stāstījāt? Vai viņš vēl dzīvs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Un tie sacīja: tavam kalpam, mūsu tēvam, labi klājās, viņš vēl dzīvs; un tie noliecās un klanījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Un viņš pacēla savas acis un ieraudzīja savu brāli Benjaminu, savas mātes dēlu, un sacīja: vai šis ir jūsu jaunākais brālis, par ko man stāstījāt? Un viņš sacīja: Dievs lai tev žēlīgs, mans dēls!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Un Jāzeps steidzās, jo viņa sirds iesila uz savu brāli, un viņš meklēja, kur raudāt, un iegāja kambarī un tur raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Un viņš mazgāja savu vaigu un nāca ārā un savaldījās un sacīja: celiet maizi priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Un tie cēla priekšā viņam (at)sevišķi un viņiem (at)sevišķi, un tiem ēģiptiešiem (at)sevišķi, kas pie viņa ēda, jo ēģiptieši ar Ebrejiem nevar maizi ēst, jo ēģiptiešiem tā ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Un tie sēdēja viņam pretī, tas pirmdzimtais pēc savas pirmdzimtības, un tas jaunākais pēc savas jaunības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Par to tie vīri brīnījās savā starpā, un viņš cēla tiem priekšā goda daļas no sava galda, bet Benjamina daļu viņš pieckārtīgi vairoja pār visu citu daļām; un tie dzēra un padzērās ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Un viņš pavēlēja tam, kas bija pār viņa namu, un sacīja: pildi to vīru maisus ar labību, cik tie var nest, un liec ikviena naudu viņa maisa virsgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Un manu biķeri, to sudraba biķeri, liec tam jaunākam maisa virsgalā, arī viņa labības naudu. Un tas darīja pēc Jāzepa vārda, ko viņš bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Rītā, gaismai austot, tie vīri tapa atlaisti līdz ar saviem ēzeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Bet tiem no pilsētas izejot un tāli vēl neesot, Jāzeps sacīja savam nama uzraugam: celies, dzenies tiem vīriem pakaļ, un tos panācis saki tiem: kādēļ esat atmaksājuši labu ar ļaunu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Vai šis nav tas, no kā mans kungs dzer? Un no tā viņš mēdz padzert. Jūs esat ļaunu darījuši, to darīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Un tas viņus panāca un viņiem sacīja šos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Tad viņi uz to sacīja: kāpēc mans kungs runā tādus vārdus? Ne mūžam tavi kalpi tādu darbu nedarīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Redzi, to naudu, ko esam atraduši savu maisu virsgalā, mēs tev atkal esam atnesuši no Kanaāna zemes, - kā tad mēs zagsim no tava kunga nama sudrabu vai zeltu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Pie kura no taviem kalpiem to atradīs, tas lai mirst, un mēs arī gribam būt par vergiem savam kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Un viņš sacīja: lai nu arī notiek pēc jūsu vārdiem: pie kura to atradīs, tas būs mans vergs, bet jūs būsiet svabadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Un tie steidzās un nocēla ikviens savu maisu zemē, un ikviens atraisīja savu maisu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Un viņš pārmeklēja no tā vecākā iesākdams un pie tā jaunākā beigdams, un tas biķeris tapa atrasts Benjamina maisā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Tad tie saplēsa savas drēbes un apkrāva ikviens savu ēzeli un griezās atpakaļ uz pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Un Jūda ar saviem brāļiem nāca Jāzepa namā, jo šis tur vēl bija, un tie nometās priekš viņa vaiga pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Un Jāzeps uz tiem sacīja: kas tas par darbu, ko jūs esat darījuši? Vai nezinājāt, ka tāds vīrs, kā es, tiešām to paredzēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Tad Jūda sacīja: ko lai sakām savam kungam, ko lai runājam un kā lai taisnojamies? Dievs tavu kalpu noziegumu ir atradis, redzi, mēs esam sava kunga vergi, - tā mēs, kā arī tas, pie kā tas biķeris atrasts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Tad viņš sacīja: nemūžam es to nedarīšu; tas vīrs, pie kā tas biķeris atrasts, tam būs man būt par vergu. Bet jūs ejat ar mieru pie sava tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Tad Jūda pie tā piegāja un sacīja: ak mans kungs! Lūdzams, lai tavs kalps runā kādu vārdu priekš sava kunga ausīm, un neapskaities par savu kalpu, jo tu esi tik augsts kā Faraons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mans kungs vaicāja savus kalpus un sacīja: vai jums ir tēvs vai brālis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Tad mēs sacījām savam kungam: mums ir vecs tēvs un viens zēns, kas tam vecumā dzimis, tas jaunākais, un viņa brālis ir miris, un tas ir viens pats no savas mātes atlicis, un viņa tēvs viņu mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Tad tu sacīji saviem kalpiem: atvediet to pie manis, lai manas acis viņu redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Tad mēs sacījām uz savu kungu: tas zēns savu tēvu nevar atstāt; ja tas atstās savu tēvu, tad šis mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Tad tu saviem kalpiem sacīji: ja jūsu jaunākais brālis ar jums neatnāk, tad jūs manu vaigu vairs neredzēsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Un kad mēs nācām pie tava kalpa, sava tēva, un viņam sacījām sava kunga vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Tad mūsu tēvs sacīja: noejat atkal, pērciet mums ēdama kādu mazumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Tad sacījām: mēs nevaram noiet: ja mūsu jaunākais brālis mums ir līdz, tad mēs noiesim. Jo mēs nevaram tā vīra vaigu redzēt, ja šis mūsu jaunākais brālis nav mums līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Tad tavs kalps, mans tēvs, mums sacīja: jūs zināt, ka mana sieva man divus dēlus dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Un tas viens ir no manis aizgājis, un es sacīju, tiešām tas ir saplosīts, un es to vairs neesmu redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Ja tad jūs arī šo paņemsiet no manām acīm un tam kāda nelaime uzies, tad jūs manus sirmos matus ar sirdēstiem novedīsiet kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Tad nu, kad es nākšu pie tava kalpa, sava tēva, un tas zēns mums nebūs līdz, jo tā tēva dvēsele viņa dvēselei sietin piesieta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Tad notiks, kad tas redzēs, ka tā zēna nav, tad tas mirs, un tavi kalpi novedīs tava kalpa, mana tēva, sirmos matus ar sirdēstiem kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Jo tavs kalps ir galvojis par to zēnu pie sava tēva, un sacījis: ja es viņu tev atpakaļ neatvedīšu, tad visu savu mūžu es gribu būt noziedzīgs sava tēva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Un nu lai jel tavs kalps tā zēna vietā paliek par sava kunga vergu, un lai tas zēns aiziet ar saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Jo kā es varētu iet pie sava tēva, ja tas zēns man nebūtu līdz? - Man būtu jāredz tie sirdēsti, kas manam tēvam uzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Tad Jāzeps nevarēja valdīties priekš visiem, kas pie viņa stāvēja, un sauca: vediet visus no manis ārā; un neviens pie tā nestāvēja, kad Jāzeps devās pazīties saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Un viņš pacēla savu balsi raudādams, tā ka tie ēģiptieši to dzirdēja, un Faraona saime to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Un Jāzeps sacīja uz saviem brāļiem: es esmu Jāzeps, vai mans tēvs vēl dzīvs? Un viņa brāļi tam nevarēja atbildēt, jo tie priekš viņa vaiga pārbijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Un Jāzeps sacīja uz saviem brāļiem: nāciet jel klāt pie manis. Un tie piegāja; tad viņš sacīja: es esmu Jāzeps, jūsu brālis, ko jūs esat pārdevuši uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Un nu, nebēdājaties un neiztrūcinājāties, ka jūs mani šurp esat pārdevuši, jo Dievs mani šurp ir sūtījis jūsu priekšā jūsu dzīvības uzturēšanas pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Jo šis ir tas otrais bada gads pār visu zemi, un vēl būs pieci gadi, kur nebūs nedz aršanas, nedz pļaušanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Un Dievs mani sūtījis jūsu priekšā, lai viņš jūs liktu par atlikumu virs zemes, un jūs uzturētu dzīvus par lielu pulku, kas izglābti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Un nu, jūs mani neesat šurp sūtījuši, bet Dievs, kas mani licis Faraonam par tēvu un par kungu visā viņa namā un par valdītāju visā Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Steidzaties un ejat pie mana tēva un sakāt tam: tā saka tavs dēls Jāzeps: Dievs mani iecēlis par kungu visai Ēģiptes zemei, - nāc šurp pie manis, nekavējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Tev būs dzīvot Gošenes zemē, un tu būsi tuvu pie manis, tu un tavi dēli un tavu dēlu dēli un tavi sīkie lopi un tavi vērši un viss, kas tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Un es tevi tur uzturēšu, jo vēl ir pieci bada gadi, - ka tu trūkumā neiznīksti, tu un tavs nams un viss, kas tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Un raugi, jūsu acis redz un mana brāļa Benjamina acis, ka mana mute uz jums runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Un stāstiet manam tēvam visu manu godību Ēģiptes zemē, un visu, ko jūs redzējuši, un steidzaties un atvediet manu tēvu šurp.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Un viņš Benjaminam, savam brālim, apkampās ap kaklu un raudāja, un Benjamins raudāja pie viņa kakla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Un viņš skūpstīja visus savus brāļus un raudāja pār tiem, un pēc viņa brāļi runāja ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Un tā slava tapa daudzināta Faraona namā: Jāzepa brāļi ir atnākuši. Un tas patika Faraonam un viņa kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Un Faraons sacīja uz Jāzepu: saki saviem brāļiem: dariet tā: apkraujiet savus lopus un ietin noejat uz Kanaāna zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Un ņemiet savu tēvu un savu saimi, un nāciet pie manis, tad es jums došu Ēģiptes zemes labumu, un jūs ēdīsiet tās zemes treknumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Un tev ir pavēlēts: dariet tā: ņemiet no Ēģiptes zemes ratus priekš saviem bērniņiem un priekš savām sievām, un atvediet savu tēvu un nāciet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Un lai jūsu acīm nav žēl savu namarīku - jo visas Ēģiptes zemes labums jums piederēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Un Israēla dēli tā darīja, un Jāzeps tiem deva ratus pēc Faraona vārdiem un tiem deva ceļamaizi uz ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Un visiem viņš deva ikvienam svētku drēbes, bet Benjaminam viņš deva trīssimt sudraba gabalus un piecas svētku drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Un savam tēvam viņš sūtīja tāpat desmit ēzeļus, kas no Ēģiptes labumu nesa, un desmit ēzeļu mātes, kas nesa labību un maizi un barību priekš tēva uz ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Un viņš savus brāļus nosūtīja, un tie aizgāja, un viņš sacīja: nebaraties pa ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Un tie aizgāja no Ēģiptes un nāca Kanaāna zemē pie Jēkaba, sava tēva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Un viņam stāstīja sacīdami: Jāzeps vēl dzīvs, un ir valdītājs pār visu Ēģiptes zemi. Bet Jēkaba sirds palika auksta, jo viņš tiem neticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Bet kad tie uz viņu runāja visus Jāzepa vārdus, ko tas tiem bija sacījis, un kad viņš ieraudzīja tos ratus, ko Jāzeps bija sūtījis, viņu novest, tad Jēkaba, viņu tēva, gars atdzīvojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Un Israēls sacīja: diezgan! Mans dēls Jāzeps vēl dzīvs! Es gribu iet un viņu redzēt, pirms nekā mirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Un Israēls aizgāja ar visu, kas tam piederēja, un nāca uz Bēršebu un upurēja upurus sava tēva Īzaka Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Un Dievs runāja ar Israēli nakts parādīšanā un sacīja: Jēkab, Jēkab! Un tas sacīja: redzi, še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Tad viņš sacīja: Es esmu tas stiprais Dievs, tava tēva Dievs; nebīsties noiet uz Ēģipti, jo Es tevi tur celšu par lielu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Es noiešu tev līdz uz Ēģiptes zemi un Es tevi vedin atkal atvedīšu, un Jāzepam būs ar savu roku tavas acis aizspiest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Tad Jēkabs cēlās no Bēršebas, un Israēla bērni veda Jēkabu, savu tēvu, un savus bērniņus un savas sievas uz ratiem, ko Faraons bija sūtījis, viņu vest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Un tie ņēma savus lopus un savu mantu, ko tie bija sakrājuši Kanaāna zemē, un nāca uz Ēģipti, Jēkabs un viss viņa dzimums līdz ar viņu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Viņa dēli un viņa dēlu dēli ar viņu, viņa meitas un viņa dēlu meitas un viss viņa dzimums, to viņš veda līdz uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Un šie ir Israēla dēlu vārdi, kas nāca uz Ēģipti, Jēkabs un viņa dēli: Rūbens, Jēkaba pirmdzimtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Un Rūbena dēli: Hanoks un Pallus un Hecrons un Karmus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Un Sīmeana dēli: Jemuels un Jamins un Oāds un Jaķins un Coārs un Sauls, vienas Kanaāniešu sievas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Un Levja dēli: Geršons, Kehāts un Merarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Un Jūda dēli: Ģers un Onans un Šelus, Perec un Zerus; un Ģers un Onans bija miruši Kanaāna zemē, - un Pereca dēli bija Hecrons un Hamuls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Un Īsašara dēli: Tolus un Puūs un Jobs un Šimrons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Un Zebulona dēli: Sereds un Elons un Jahleēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Šie ir Leas dēli, ko tā Jēkabam ir dzemdējusi Mezopotamijā, ar Dinu, viņa meitu; visas viņa dēlu un viņa meitu dvēseles bija trīsdesmit un trīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Un Gada dēli: Zifions un Hagaja, Šunus, Ecbons, Erus un Arodus un Arelus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Un Ašera dēli: Jemnus un Ješvus, Jisvi un Berius un Zera, viņu māsa. Un Berius dēli: Hebers un Malķiēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Šie ir Zilfas bērni, ko Lābans Leai, savai meitai, bija devis; un tā dzemdēja Jēkabam šās sešpadsmit dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Rahēles, Jēkaba sievas, dēli bija Jāzeps un Benjamins.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Un Jāzepam dzima Ēģiptē Manasus un Efraīms, ko viņam dzemdēja Asnata, Potifera, Onna priestera, meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Un Benjamina dēli: Belus un Beķers un Ašbels, Ģerus un Naāmans, Eķius un Ros, Mupims un Hupims un Ards.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Šie ir Rahēles dēli, kas Jēkabam ir piedzimuši, - visi kopā četrpadsmit dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Dana dēli: Hušims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Un Naftalus dēli: Jahceēls un Gunus un Jecers un Šillems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Šie ir Bilhas dēli, ko Lābans savai meitai Rahēlei deva, un tā dzemdēja šos Jēkabam, - visi kopā bija septiņas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Visas dvēseles, kas ar Jēkabu uz Ēģipti nāca, kas no viņa gurniem cēlušās, bez Jēkaba dēlu sievām, visas dvēseles sešdesmit un sešas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Un Jāzepa dēli, kas viņam Ēģiptes zemē dzimuši, bija divas dvēseles; visas dvēseles Jēkaba namā, kas uz Ēģipti nāca, bija septiņdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Un viņš sūtīja Jūdu savā priekšā pie Jāzepa, ka šis priekš viņa tam ierādītu Gošenes zemi; un tie nāca Gošenes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Tad Jāzeps iejūdza savus ratus un gāja savam tēvam Israēlim pretī uz Gošeni, un viņu ieraudzījis tas metās ap viņa kaklu un raudāja ilgi pie viņa kakla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Un Israēls sacīja uz Jāzepu: nu es labprāt gribu mirt, kad tavu vaigu esmu redzējis, ka tu vēl esi dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Un Jāzeps sacīja uz saviem brāļiem un uz sava tēva namu: es noiešu un to pasacīšu Faraonam un tam teikšu: mani brāļi un mana tēva nams, kas bija Kanaāna zemē, pie manis atnākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Un tie vīri ir avju gani, jo tie ir lopu kopēji, un savus sīkos lopus un savus vēršus, un visu, kas tiem pieder, to tie atveduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Kad nu Faraons jūs aicinās un jautās, kas ir jūsu amats?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Tad sakāt: tavi kalpi ir lopu kopēji no mazām dienām līdz šim, tā pat mēs kā mūsu tēvi, lai jūs varat mist Gošenes zemē; jo ēģiptiešiem visi lopu gani bija negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Tad Jāzeps nāca un pasludināja Faraonam un sacīja: mans tēvs un mani brāļi un viņu sīkie lopi un viņu vērši un viss, kas tiem pieder, ir atnākuši no Kanaāna zemes, un redzi, tie ir Gošenes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Un viņš ņēma piecus no visiem saviem brāļiem, un tos veda Faraona priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Un Faraons sacīja uz viņa brāļiem: kas ir jūsu darbs? Un tie sacīja uz Faraonu: tavi kalpi ir lopu gani, tā pat mēs kā mūsu tēvi. Un tie sacīja uz Faraonu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Mēs esam nākuši šinī zemē piemist, jo ganības trūkst tiem sīkiem lopiem, kas taviem kalpiem pieder, jo bads ir grūts Kanaāna zemē, un nu vēli, lūdzams, lai tavi kalpi apmetās Gošenes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Tad Faraons runāja uz Jāzepu un sacīja: tavs tēvs un tavi brāļi pie tevis atnākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Ēģiptes zeme stāv tev atvērā; lai tavs tēvs un tavi brāļi dzīvo tai vislabākā zemes vietā, - lai tie mīt Gošenes zemē, un ja tu zini, ka starp tiem ir krietni vīri, tad iecel tos par manu lopu uzraugiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Un Jāzeps atveda savu tēvu Jēkabu, un to stādīja Faraona priekšā, un Jēkabs svētīja Faraonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Un Faraons sacīja uz Jēkabu: Cik gadu tavām dzīvības dienām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Tad Jēkabs sacīja uz Faraonu: manas svešniecības gadu dienas ir simts un trīsdesmit gadi; īsas un grūtas ir bijušas manas dzīvības gadu dienas un nepanāk manu tēvu gadus viņu svešniecības dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Un Jēkabs svētīja Faraonu un izgāja no Faraona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Un Jāzeps savam tēvam un saviem brāļiem iedeva mājas vietas, un tiem deva Ēģiptes zemē to labāko zemes vietu turēt, Raēmzes tiesā, tā kā Faraons bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Un Jāzeps uzturēja savu tēvu un savus brāļus un visu sava tēva namu ar maizi, kā kuram bija bērnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Un pa visām zemēm nebija maizes; jo bads bija ļoti grūts, tā ka Ēģiptes zemē un Kanaāna zemē aiz bada nevarēja glābties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Un Jāzeps sakrāja visu naudu, kas atradās Ēģiptes zemē un Kanaāna zemē par to labību, ko tie pirka, un Jāzeps to naudu nesa Faraona namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Kad nu tā nauda Ēģiptes zemē un Kanaāna zemē bija pagalam, tad visi ēģiptieši nāca pie Jāzepa un sacīja: dod mums maizes, kādēļ mums tavā priekšā būs mirt, kad naudas vairs nav?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Tad Jāzeps sacīja: dodiet savus lopus; tad es jums došu par jūsu lopiem, kad naudas nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Tad tie veda savus lopus pie Jāzepa, un Jāzeps tiem deva maizes par zirgiem un par sīkiem lopiem un par vēršiem un par ēzeļiem, un viņš tos to gadu izmitināja ar maizi par visiem viņu lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Kad tas gads bija galā, tad tie otrā gadā pie viņa nāca un uz viņu sacīja: mēs neapslēpsim priekš sava kunga, ka nevien tā nauda ir beigta, bet arī tie lopi mūsu kungam ir kļuvuši un nekas nav atlicis priekš mūsu kunga, kā vien mūsu miesas un mūsu tīrumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Kādēļ mums būs bojā iet priekš tavām acīm, mums un mūsu tīrumiem? Pērc mūs un mūsu tīrumus par maizi, tad mēs ar savu tīrumu Faraonam būsim par kalpiem, un dodi sēklu, ka mēs dzīvojam un nemirstam, un mūsu zeme nepaliek tukša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Tad Jāzeps visus ēģiptiešu tīrumus pirka priekš Faraona, jo ēģiptieši pārdeva ikviens savu tīrumu, tāpēc ka bads tiem bija grūts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Tad tā zeme kļuva Faraona rokā, un viņš tos ļaudis pārcēla pilsētās, no viena Ēģiptes robežu gala līdz otram galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Tikai priesteru tīrumus viņš nepirka, jo priesteriem bija sava daļa no Faraona, un tie ēda no savas daļas, ko Faraons tiem deva, tādēļ tie savu tīrumu nepārdeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Tad Jāzeps sacīja uz tiem ļaudīm: redzi, es šodien jūs un jūsu tīrumus esmu pircis Faraonam, redzi, še jums sēkla, ka jūs tīrumus apsējat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Bet ar augļiem tas tā būs, ka jūs piekto tiesu dodat Faraonam, un četras daļas jums piederēs, tīrumus apsēt un par pārtiku jums un tiem, kas jūsu namā, un par pārtiku jūsu bērniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Un tie sacīja: tu mūs esi uzturējis dzīvus; lai žēlastību atrodam sava kunga acīs, tad mēs būsim Faraona kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Tad Jāzeps to iecēla par likumu pār ēģiptiešu tīrumiem līdz šai dienai, ka Faraonam tā piektā tiesa nāktos, - tikai priesteru zeme vien nekļuva Faraonam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Un Israēls mita Ēģiptē Gošenes zemē, un tur uzturējās un auga un vairojās ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Un Jēkabs dzīvoja Ēģiptes zemē septiņpadsmit gadus, un Jēkaba dienas bija simts četrdesmit un septiņi gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Kad nu Israēla laiks pienāca, ka tam bija mirt, tad viņš sauca savu dēlu Jāzepu un uz to sacīja: ja es tavās acīs esmu atradis žēlastību, tad liec jel lūdzams savu roku apakš manas ciskas un dari pie manis žēlastību un patiesību: neaproc jel mani Ēģiptes zemē;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Bet es gribu gulēt pie saviem tēviem; un tev būs mani izvest no Ēģiptes un mani aprakt viņu kapos, - un tas sacīja: es darīšu pēc tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Tad viņš sacīja: zvērē man. Un tas viņam zvērēja. Un Israēls pielūdza Dievu savas gultas galvgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Un notikās pēc tam, ka Jāzepam sacīja: redzi, tavs tēvs ir nevesels. Tad tas ņēma līdz savus divus dēlus, Manasu un Efraīmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Un Jēkabam tapa teikts un sacīts: redzi, tavs dēls Jāzeps nāk pie tevis. Tad Israēls saņēmās spēkā un apsēdās uz gultas. Un Jēkabs sacīja uz Jāzepu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Tas visuvarenais Dievs man ir parādījies Lūzā, Kanaāna zemē, un mani svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Un viņš uz mani sacījis: redzi, Es tev likšu augļoties un tevi vairošu un tevi celšu par tautu pulku, un došu šo zemi tavam dzimumam pēc tevis par mūžīgu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Un nu taviem diviem dēliem, kas Ēģiptē dzimuši, pirms nekā es pie tevis esmu atnācis uz Ēģipti, tiem būs būt maniem; Efraīms un Manasus būs man tāpat, kā Rūbens un Sīmeans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Bet tavi bērni, kas tev dzims pēc viņiem, tev piederēs, tiem būs tapt nosauktiem pēc savu brāļu vārda viņu iemantojamā tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Kad es nu nācu no Mezopotamijas, tad Rahēle pie manis ir nomirusi Kanaāna zemē uz ceļa, mazu gabalu no Efratas, un es viņu apraku tur Efratas ceļmalā, - un šī ir Bētleme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Un Israēls ieraudzīja Jāzepa dēlus un sacīja: kam šie ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Un Jāzeps sacīja uz savu tēvu: tie ir mani dēli, ko Dievs man še devis. Un viņš sacīja: pieved jel tos pie manis, ka es tos svētīju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Bet Israēla acis bija tumšas no vecuma, un viņš nevarēja redzēt, un tas tos pie viņa pieveda, un viņš tos skūpstīja un tos apkampa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Un Israēls sacīja uz Jāzepu: es nedomāju redzēt tavu vaigu, un raugi, Dievs man licis redzēt arī tavu dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Un Jāzeps tos ņēma no viņa klēpja un ar savu vaigu nometās pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Un Jāzeps tos abus ņēma, Efraīmu ar savu labo roku Israēlim pa kreiso roku, un Manasu ar savu kreiso roku Israēlim pa labo roku, un tos viņam pieveda klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Un Israēls izstiepa savu labo roku un to lika uz Efraīma galvu, jebšu tas bija tas jaunākais, un savu kreiso roku uz Manasus galvu; viņš ar ziņu tā savas rokas lika, jebšu Manasus bija tas pirmdzimtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Un viņš svētīja Jāzepu un sacīja: tas Dievs, priekš kura vaiga mani tēvi, Ābrahāms un Īzaks, staigājuši, - tas Dievs, kas mani visu mūžu līdz šai dienai ir ganījis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Tas eņģelis, kas mani pestījis no visa ļauna, - tas lai svētī šos bērnus, ka iekš tiem mans vārds top nosaukts un manu tēvu, Ābrahāma un Īzaka, vārds, un ka tie pa pulkiem vairojās virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Un Jāzeps redzēja, ka viņa tēvs savu labo roku lika uz Efraīma galvu, un tas viņam nepatika, un viņš satvēra sava tēva roku, to nolikdams no Efraīma galvas uz Manasus galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Un Jāzeps sacīja uz savu tēvu: ne tā, mans tēvs, jo šis ir tas pirmdzimtais, liec savu labo roku uz viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Bet viņa tēvs liedzās un sacīja: es to gan zinu, mans dēls, gan zinu. Arī šis būs par ļaužu pulku, un tas arī būs liels, bet tomēr viņa jaunākais brālis būs lielāks nekā viņš, un viņa dzimums būs par lielu ļaužu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Un viņš tos svētīja tanī dienā un sacīja: iekš tevis Israēls svētīs un sacīs: lai Dievs tevi dara tā kā Efraīmu un kā Manasu, un viņš cēla Efraīmu pāri par Manasu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Pēc Israēls sacīja uz Jāzepu: redzi, es mirstu, bet Dievs būs ar jums un jūs vedīs atpakaļ uz jūsu tēvu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Un es tev dodu vienu daļu pāri par taviem brāļiem, ko es no Amoriešu rokas esmu ņēmis ar savu zobenu un ar savu stopu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Un Jēkabs sasauca savus dēlus un sacīja: sapulcējaties, un es jums sludināšu, kas jums notiks nākamās dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Sapulcējaties un klausāties, jūs Jēkaba dēli, klausāties uz Israēli, savu tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rūben, tu mans pirmdzimtais, mans spēks un mana stipruma iesākums, pirmais augstībā un pirmais stiprumā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Verdošs kā ūdens, - tev nebūs būt tam augstākajam, jo sava tēva gultā tu esi kāpis, tur tu to esi sagānījis; manās cisās viņš kāpis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Sīmeans un Levis ir brāļi, viņu zobeni ir varas ieroči.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Lai mana dvēsele nenāk viņu runās, mans gods lai nav viņu draudzē, jo savā bardzībā tie vīrus nokāvuši, un savā tīšā prātā tie vēršus maitājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Nolādēta lai ir viņu dusmība, jo tā ir briesmīga, un viņu bardzība, jo tā ir cieta; es tos izdalīšu pa Jēkabu, es tos izkaisīšu pa Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Jūda, tu tas esi, tevi teiks tavi brāļi, tava roka būs uz kakla taviem ienaidniekiem, tavā priekšā klanīsies tava tēva bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Jūda ir jauns lauva, no laupījuma tu esi pacēlies, mans dēls, viņš nometies, nogūlies tā kā lauva un tā kā lauvas māte; kas viņu traucēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Scepteris nezudīs no Jūda, nedz valdības zizlis no viņa kājām, tiekams tas ŠĪLO (miers) nāks, un viņam tās tautas paklausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Viņš sien savu jauno ēzeli pie vīna koka un savas ēzeļa mātes kumeļu pie vīna koka stīgām. Savas drēbes viņš mazgā vīnā, un savu mēteli vīna ķekaru asinīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Viņa acis ir sarkanas no vīna, un viņa zobi balti no piena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulons dzīvos pie jūras krastiem un būs pie kuģu ostām un sniedzās līdz Sidonai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Īsašars ir stiprs kaulains ēzelis un guļ starp laidariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Un viņš redzēja dusu, ka tā laba, un to zemi, ka tā jauka, un locīja savu muguru pie nešanas un kalpoja klausīdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dans, tā kā citas Israēla ciltis, tiesās savu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dans būs čūska ceļmalā, odze tekas malā, kozdama zirgam papēžos, ka viņa jājējs krīt atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Kungs, es gaidu uz Tavu pestīšanu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gads, dzinēji viņu dzenās, bet viņš tos atgainīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'No Ašera būs trekna maize, un viņš dos ķēniņu gardumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftalus ir stirna savā vaļā, viņš dod mīlīgus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Jāzeps ir jauns augļu koks, jauns augļu koks avota malā, tie zari stiepjas pār mūri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Strēlnieki viņu kaitinājuši, viņu apšaudījuši un ienīdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Bet viņa stops ir palicis stiprs, un viņa roku elkoņi spēcīgi, no tā rokām, kas varens iekš Jēkaba; no turienes, kur tas gans, Israēla klints,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'No tava tēva Dieva, un Tas tev palīdzēs, - un no tā Visuvarenā, Tas tevi svētīs ar debess svētījumiem no augšienes, ar dziļumu svētījumiem apakšā, ar svētījumiem no krūtīm un miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Tava tēva svētījumi ir stiprāki nekā manu vecaju svētījumi līdz mūžīgo kalnu galiem, tie nāks pār Jāzepa galvu, un pār tā galvu, kas tas izredzētais savu brāļu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamins ir plēsīgs vilks, no rīta viņš laupījumu ēdīs un ap vakaru viņš laupījumu dalīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Šās visas ir Israēla divpadsmit ciltis, un šie ir tie vārdi, ko viņu tēvs uz tiem runāja, tos svētīdams; ikvienu viņš svētīja ar īpašu svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Un viņš tiem pavēlēja un sacīja: es tapšu piepulcināts pie saviem ļaudīm, aprociet mani pie maniem tēviem tai alā, kas ir Hetieša Efrona tīrumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Makpelas alas tīrumā, kas ir pret Mamri, Kanaāna zemē, ko Ābrahāms ir pircis no Efrona, tā Hetieša, sev par dzimts kapa vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tur tie ir aprakuši Ābrahāmu un Sāru, viņa sievu, tur tie ir aprakuši Īzaku un Rebeku, viņa sievu, tur es esmu apracis Leū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Tas tīrums un tā ala, kas tur, ir pirkti no Heta bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Kad Jēkabs bija beidzis pavēles dot saviem dēliem, tad viņš salika savas kājas uz gultas un izlaida garu un tapa piepulcināts pie saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Tad Jāzeps krita uz sava tēva vaigu un raudāja pār viņu un to skūpstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Un Jāzeps pavēlēja saviem kalpiem, tiem dziedniekiem, ka tie svaidītu viņa tēvu ar balzamu, un tie dziednieki svaidīja Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Un tā pagāja četrdesmit dienas, jo tik daudz dienas pie svaidīšanas aiziet, un ēģiptieši viņu apraudāja septiņdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Kad nu viņa raudu dienas bija pagājušas, tad Jāzeps runāja uz Faraona namu un sacīja: ja es esmu atradis žēlastību jūsu acīs, tad runājiet jel priekš Faraona ausīm un sakāt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mans tēvs man ir licis zvērēt sacīdams: redzi, es mirstu; manā kapā, ko es sev esmu racis Kanaāna zemē, tur tev būs mani aprakt. Un nu vēli man jel noiet, ka es savu tēvu aproku, tad es atkal nākšu atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Un Faraons sacīja: ej un aproc savu tēvu, tā kā viņš tev ir licis zvērēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Tad Jāzeps aizgāja savu tēvu aprakt, un viņam gāja līdz visi Faraona kalpi, viņa nama vecaji un visi Ēģiptes zemes vecaji,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Un viss Jāzepa nams un viņa brāļi un viņa tēva nams, tikai savus bērniņus un savus sīkos lopus un savus lielos lopus tie atstāja Gošenes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Un viņam gāja līdz rati un jātnieki, un bija varen liels pulks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Kad tie nu nāca pie Atad klona, kas ir viņpus Jardānes, tad tie tur žēlojās lielās grūtās žēlabās, un viņš savam tēvam darīja septiņas raudu dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Kad tās zemes ļaudis, tie Kanaānieši, redzēja tās žēlabas pie Atad klona, tad tie sacīja: ēģiptiešiem tur ir grūtas žēlabas, tāpēc tās vietas vārdu nosauca ēģiptiešu žēlabas, kas viņpus Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Un viņa dēli viņam darīja, kā viņš tiem bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Jo viņa dēli to veda uz Kanaāna zemi un to apraka Makpelas tīruma alā, ko Ābrahāms ar to tīrumu bija pircis sev par dzimts kapa vietu no Efrona, tā Hetieša, pret Mamri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Un Jāzeps griezās atpakaļ uz Ēģipti, viņš un viņa brāļi un visi, kas ar viņu bija gājuši, viņa tēvu aprakt, pēc tam kad viņš savu tēvu bija paglabājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Bet Jāzepa brāļi bijās, kad viņu tēvs bija miris un sacīja: kad tik Jāzeps mūs neienīdēs un mums neatmaksās visu to ļaunumu, ko mēs viņam esam darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Tad tie lika Jāzepam sacīt: tavs tēvs pavēlēja, pirms tas mira, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Tā jums būs sacīt Jāzepam: piedod lūdzams savu brāļu noziegumu un viņu grēku, jo tie tev ļaunu darījuši, bet nu piedod lūdzams to noziegumu sava tēva Dieva kalpotājiem. Un Jāzeps raudāja, kad tie tā uz viņu runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Tad viņa brāļi paši nāca un metās priekš viņa zemē un sacīja: redzi, mēs esam tavi kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Un Jāzeps uz tiem sacīja: nebīstaties! Vai tad es esmu Dieva vietā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Jūs gan esat ļaunu pret mani domājuši, bet Dievs to par labu ir nodomājis, gribēdams, tā kā šodien redzams, uzturēt daudz ļaudis pie dzīvības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Un nu nebīstaties, - es uzturēšu jūs un jūsu bērniņus. Un viņš tos iepriecināja un ar tiem laipnīgi runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Un Jāzeps dzīvoja Ēģiptē, viņš un viņa tēva nams; un Jāzeps dzīvoja simts un desmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Un Jāzeps redzēja no Efraīma bērnus līdz trešam augumam, un Mahira, Manasus dēla, bērni piedzima Jāzepa klēpī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Un Jāzeps sacīja uz saviem brāļiem: es mirstu, bet Dievs jūs meklēt piemeklēs un jūs izvedīs no šīs zemes uz to zemi, ko viņš Ābrahāmam, Īzakam un Jēkabam zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Un Jāzeps Israēla dēliem lika zvērēt sacīdams: Dievs jūs meklēt piemeklēs, tad jums manus kaulus būs aizvest no šejienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Un Jāzeps nomira simts un desmit gadus vecs, un tie viņu svaidīja ar balzamu un ielika šķirstā Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Šie nu ir Israēla bērnu vārdi, kas ar Jēkabu ir nākuši uz Ēģiptes zemi; ikviens nāca ar savu saimi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rūbens, Sīmeans, Levis un Jūda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Īsašars, Zebulons un Benjamins,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dans, Naftalus, Gads un Ašers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Un visas dvēseles, kas nākušas no Jēkaba gurniem bija septiņdesmit; bet Jāzeps jau bija Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Kad nu Jāzeps bija nomiris un visi viņa brāļi un viss tas dzimums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Tad Israēla bērni augļojās un radās pa pulkiem un vairojās un tapa ļoti vareni, tā ka tā zeme ar tiem tapa piepildīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Un jauns ķēniņš cēlās pār Ēģiptes zemi, kas Jāzepu nepazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Tas sacīja uz saviem ļaudīm: Redzi, Israēla bērnu tauta ir liela, un tie ir jo varenāki nekā mēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Tad nu turēsimies gudri pret tiem, ka tie nevairojās, lai, kad karš ceļas, tie nedodās pie mūsu ienaidniekiem un nekaro pret mums un neaiziet no šīs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Tad tie pār viņiem iecēla darba uzraugus, ka viņus spiestu ar grūtiem darbiem, un tie Faraonam uztaisīja mantu pilis Pitom un Raēmzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Bet jo vairāk viņus spieda, jo vairāk tie vairojās un izplētās; un tiem palika bail no Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Un ēģiptieši kalpināja Israēla bērnus nežēlīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Un darīja dzīvību tiem rūgtu ar grūtiem darbiem pie māliem un ķieģeļiem un ar visādiem darbiem laukā, un ar visādiem darbiem, ar ko tie viņus nežēlīgi kalpināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Un Ēģiptes ķēniņš runāja uz Ebreju bērnu saņēmējām, (tās vienas vārds bija Šifra un tās otras Pua),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Un sacīja: kad jūs Ebreju sievām palīdzat pie dzemdēšanas, un tām uz krēsla sēžot redzat to esam dēlu, tad to nonāvējiet, bet ja ir meita, tad to atstājiet dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Bet tās bērnu saņēmējas bijās Dievu un nedarīja, kā Ēģiptes ķēniņš tām bija sacījis, bet atstāja tos puisēnus dzīvus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Tad Ēģiptes ķēniņš tās bērnu saņēmējas aicināja un uz tām sacīja: kādēļ jūs to esat darījušas un tos puisēnus atstājušas dzīvus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Un tās bērnu saņēmējas sacīja uz Faraonu: tādēļ ka Ebreju sievas nav kā ēģiptiešu sievas; jo tās ir stipras; pirms bērnu saņēmēja pie tām atnāk, tās jau ir dzemdējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Tāpēc Dievs tām bērnu saņēmējām darīja labu, un tie ļaudis vairojās un tapa vareni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Un tāpēc ka tās bērnu saņēmējas Dievu bijās, viņš tām darīja namus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Tad Faraons pavēlēja visiem saviem ļaudīm un sacīja: jums visus dēlus, kas piedzimst, būs iemest upē, bet visas meitas atstāt dzīvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Un viens vīrs no Levja nama nogāja un apņēma Levja meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Un tā sieva tapa grūta un dzemdēja dēlu. Kad nu tā redzēja viņu esam skaistu, tad tā viņu paslēpa trīs mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Bet kad viņu vairs nevarēja paslēpt, tad tā ņēma priekš viņa niedru šķirstiņu un to aptraipīja ar piķi un sveķiem, ielika to bērnu tur iekšā, un to nolika niedrēs upmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Un viņa māsa stāvēja no tālienes, nolūkot, kas tam notiktu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Tad Faraona meita nonāca upē mazgāties, un viņas jumpravas staigāja upes malā. Un viņa redzēja to šķirstu niedru vidū un sūtīja savu kalponi un lika to atnest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Kad nu viņa to atvēra, tad tā redzēja to bērniņu, un raugi, tas puisēns raudāja, un viņa par to apžēlojās un sacīja: šis ir viens no tiem Ebreju bērniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Tad viņa māsa sacīja uz Faraona meitu: vai man būs iet un tev aicināt zīdītāju no Ebreju sievām, kas tev to bērnu var zīdināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Un Faraona meita uz to sacīja: ej! Un tā meitene nogāja un aicināja tā bērniņa māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Un Faraona meita uz viņu sacīja: ņem šo bērniņu un zīdi man to, es tev došu tavu algu. Un tā sieva ņēma to bērniņu un to zīdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Un kad tas bērniņš bija paaudzis, tad viņa to noveda pie Faraona meitas, un tas viņai tapa par dēlu, un tā viņa vārdu nosauca Mozu (izvilktais), sacīdama: tāpēc, ka es to no ūdens esmu izvilkusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Un notika tanīs dienās, kad Mozus bija uzaudzis, tad viņš izgāja pie saviem brāļiem un apraudzīja viņu grūtumu un redzēja ēģiptiešu vīru sitam vienu Ebreju vīru, vienu no viņa brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Un viņš skatījās šurp un turp un redzēdams, ka tur neviena nebija, viņš to Ēģiptieti nosita un to apslēpa smiltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Un viņš izgāja otrā dienā un redzi, divi Ebreju vīri bārās; un viņš sacīja uz to vainīgo: kāpēc tu siti savu tuvāko?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Tad tas sacīja: kas tevi mums licis par virsnieku jeb soģi? Vai tu tā saki, mani arīdzan gribēdams nokaut, kā tu to Ēģiptieti esi nokāvis? Tad Mozus bijās un sacīja: patiesi šī lieta ir tapusi zināma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Kad nu Faraons šo lietu dzirdēja, tad viņš meklēja Mozu nokaut, un Mozus bēga no Faraona un mita Midijanas zemē un apmetās pie vienas akas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Un Midijanas priesterim bija septiņas meitas; tās nāca smelt un pildīja ūdens siles, dzirdināt sava tēva avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Bet tie gani nāca un tās nodzina, un Mozus cēlās tām palīgā un dzirdināja viņu avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Un kad tās nāca pie sava tēva Reguēļa, tad viņš sacīja: kā tad jūs šodien tik drīz esat pārnākušas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Tad tās sacīja: viens ēģiptiešu vīrs mūs izglābis no to ganu rokas, un viņš mums arī smēlis un dzirdinājis mūsu avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Un tas sacīja uz savām meitām: kur tad viņš ir? Kāpēc jūs šo vīru tur esat atstājušas. Aicinājiet to, maizi ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Un Mozum bija pa prātam, palikt pie tā vīra, un tas deva Mozum savu meitu Ciporu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Tā viņam dzemdēja dēlu, un tas viņa vārdu nosauca Geršomu (piemitējs), sacīdams: es esmu piemitējs svešā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Un ilgu laiku pēc tam Ēģiptes ķēniņš nomira un Israēla bērni nopūtās un brēca par to kalpošanu, un viņu brēkšana par to kalpošanu uzkāpa pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Un Dievs dzirdēja viņu nopūtas, un pieminēja Savu derību ar Ābrahāmu, Īzaku un Jēkabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Un Dievs uzlūkoja Israēla bērnus un Dievs ņēma to vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Un Mozus ganīja Jetrus, sava tēvoča, Midijanas priestera, avis un dzina tās avis aiz tuksneša un nāca pie Dieva kalna Horebā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Un Tā Kunga eņģelis viņam parādījās uguns liesmā no ērkšķu krūma, un viņš skatījās un redzi, tas ērkšķu krūms dega ar uguni, bet tas ērkšķu krūms nesadega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Tad Mozus sacīja: es jel noiešu un apraudzīšu šo lielo parādīšanu, kādēļ tas ērkšķu krūms nesadeg.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Un Tas Kungs redzēja, ka tas gāja lūkot, un Dievs sauca uz to no tā ērkšķu krūma un sacīja: Mozu! Mozu! Un tas sacīja: redzi, še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Un Viņš sacīja: nenāc klāt, novelc savas kurpes no kājām, jo tā vieta, kur tu stāvi, ir svēta zeme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Un Viņš sacīja: Es esmu tava tēva Dievs, Ābrahāma Dievs, Īzaka Dievs un Jēkaba Dievs. Un Mozus aizklāja savu vaigu, jo tas bijās Dievu uzlūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Un Tas Kungs sacīja: Es tiešām esmu redzējis Savu ļaužu bēdas, kas ir Ēģiptes zemē un esmu dzirdējis viņu brēkšanu par saviem dzinējiem, jo viņu sāpes Es esmu ņēmis vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Tādēļ Es esmu nolaidies, tos izpestīt no ēģiptiešu rokas un tos izvest no šās zemes uz labu un plašu zemi, uz zemi, kur piens un medus tek, uz Kanaāniešu, Hetiešu, Amoriešu, Fereziešu, Hiviešu un Jebusiešu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Un nu redzi, Israēla bērnu brēkšana ir nākusi Manā priekšā, un Es arī esmu redzējis to spaidīšanu, ar ko ēģiptieši tos spaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Tad nu ej, Es tevi sūtīšu pie Faraona, un izvedi Manus ļaudis, Israēla bērnus, no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Tad Mozus sacīja uz Dievu: kas es esmu, ka man būs iet pie Faraona un izvest Israēla bērnus no Ēģiptes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Un Viņš sacīja: Es būšu ar tevi: un šī būs tev tā zīme, ka Es tevi esmu sūtījis: kad tu tos ļaudis no Ēģiptes zemes būsi izvedis, tad jūs Dievam kalposiet uz šī kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Un Mozus sacīja uz Dievu: redzi, kad es nākšu pie Israēla bērniem un uz tiem sacīšu: jūsu tēvu Dievs mani pie jums ir sūtījis, un tie uz mani saka, kāds ir Viņa vārds? Ko man tiem būs sacīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Tad Dievs sacīja uz Mozu: Es Esmu, Kas Es Esmu. Un Viņš sacīja: tā tev būs sacīt Israēla bērniem: Es Esmu, Tas mani pie jums ir sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Un Dievs vēl sacīja Mozum: tā tev būs sacīt Israēla bērniem: Tas Kungs, jūsu tēvu Dievs, Ābrahāma Dievs, Īzaka Dievs un Jēkaba Dievs, mani pie jums ir sūtījis; šis ir Mans vārds mūžīgi, un šī ir Mana piemiņa uz bērnu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Ej un sapulcini Israēla vecajus un saki tiem: Tas Kungs, jūsu tēvu Dievs, man ir parādījies, Ābrahāma, Īzaka un Jēkaba Dievs, un sacījis: Es esmu nācis jūs raudzīt un to, kas jums darīts Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Un Es esmu sacījis: Es jūs izvedīšu no ēģiptiešu spaidīšanas uz Kanaāniešu, Hetiešu, Amoriešu, Fereziešu, Hiviešu un Jebusiešu zemi, uz zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Un kad tie klausīs tavai balsij, tad tev ar Israēla vecajiem būs iet pie Ēģiptes ķēniņa un uz to sacīt: Tas Kungs, tas Ebreju Dievs, mūs ir sastapis. Un nu lai ejam treju dienu gājumu tuksnesī, upurēt Tam Kungam, savam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Bet Es zinu, ka Ēģiptes ķēniņš jums neļaus iet, pat ne caur stipru roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Tad Es izstiepšu Savu roku un sitīšu Ēģiptes zemi ar visiem Saviem brīnumiem, ko Es viņas vidū darīšu; tad viņš jūs atlaidīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Un Es tiem ļaudīm došu žēlastību ēģiptiešu priekšā, un kad jūs iziesiet, tad jūs neiziesiet tukši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Bet ikvienai sievai no savas kaimiņienes un no tās, kas dzīvo viņas namā, būs prasīt zelta un sudraba traukus un drēbes, tos jums būs likt uz saviem dēliem un savām meitām un ēģiptiešiem atņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Tad Mozus atbildēja un sacīja: bet redzi, viņi man neticēs nedz klausīs manai balsij, jo tie sacīs: Tas Kungs tev nav parādījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Un Tas Kungs uz to sacīja: kas tev tavā rokā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Un tas sacīja: zizlis. Tad Viņš sacīja: met to zemē! Un tas to meta zemē; tad tas kļuva par čūsku, un Mozus bēga no viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Tad Tas Kungs sacīja uz Mozu: izstiep savu roku un satver to pie astes! Un tas izstiepa savu roku un to satvēra; tad tā atkal kļuva par zizli viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Tāpēc viņi ticēs, ka tev Tas Kungs ir parādījies, viņu tēvu Dievs, Ābrahāma Dievs, Īzaka Dievs un Jēkaba Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Un Tas Kungs vēl tam sacīja: bāz jel savu roku azotē! Un tas iebāza savu roku azotē un to izvilka, un redzi, tā roka bija spitālīga kā sniegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Un Viņš sacīja: bāz atkal savu roku azotē! Un tas iebāza savu roku azotē un to izvilka no azotes, un redzi, tā bija atkal kā viņa cita miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Un ja viņi tev neticēs un neklausīs pie tās pirmās zīmes, tad viņi tev ticēs pie tās otrās zīmes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Un ja viņi arī neticēs šīm divām zīmēm un neklausīs tavai balsij, tad ņem ūdeni no upes un izlej to uz sausumu, tad tas ūdens, ko tu no upes ņemsi, paliks par asinīm uz sausuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Tad Mozus sacīja uz To Kungu: Ak Kungs! es neesmu runātājs, nedz vakar, nedz aizvakar, nedz no tā laika, kad tu uz Savu kalpu esi runājis, jo man ir grūta valoda un grūta mēle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Tad Tas Kungs uz to sacīja: kas cilvēkam muti devis? Jeb kas dara mēmu vai kurlu vai redzīgu vai aklu? Vai ne Es, Tas Kungs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Un nu ej, Es būšu ar tavu muti un tev mācīšu, kas tev jārunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Tad viņš sacīja: ak Kungs, sūti jel kādu sūtīdams!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Tad Tā Kunga dusmība iedegās par Mozu un viņš sacīja: vai Ārons, tas Levits, nav tavs brālis? Es zinu, ka tas skaidri runā. Un redzi, tas izies tev pretī un priecāsies savā sirdī, tevi redzēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tad tev būs runāt uz viņu un tos vārdus likt viņa mutē, un Es būšu ar tavu muti un ar viņa muti, un Es jūs mācīšu, kas jums jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Un viņam priekš tevis būs runāt uz tiem ļaudīm, viņam būs tev būt par muti, un tev būs viņam būt par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Un ņem šo zizli savā rokā, ar to tev būs tās zīmes darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Tad Mozus nogāja un atgriezās pie sava tēvoča Jetrus un uz to sacīja: laidi mani iet atpakaļ pie saviem brāļiem, kas Ēģiptes zemē, un raudzīt, vai tie vēl dzīvi. Tad Jetrus sacīja uz Mozu: ej ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Tas Kungs vēl sacīja uz Mozu Midijanā: ej atpakaļ uz Ēģiptes zemi, jo visi tie vīri ir miruši, kas tavu dzīvību meklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Tad Mozus ņēma savu sievu un savus dēlus un tiem lika jāt uz ēzeļiem un griezās atpakaļ uz Ēģiptes zemi; un Mozus ņēma to Dieva zizli savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Un Tas Kungs sacīja uz Mozu: kad tu nu ej atpakaļ uz Ēģiptes zemi, tad pielūko, ka tu dari visus tos brīnumus, ko Es tev esmu devis Faraona priekšā; tomēr Es viņa sirdi apcietināšu, ka viņš tos ļaudis neatlaidīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Tad tev būs sacīt uz Faraonu: tā saka Tas Kungs: Israēls ir Mans dēls, Mans pirmdzimtais;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Un Es tev esmu sacījis: atlaid Manu dēlu, ka tas Man kalpo, bet tu esi liedzies viņu atlaist; redzi, Es nokaušu tavu dēlu, tavu pirmdzimto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Un kad viņš uz ceļa bija naktsmājās, tad Tas Kungs viņam nāca pretī un meklēja viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Un Cipora ņēma asu akmeni un apgraizīja sava dēla priekšādu un aizskāra viņa kājas un sacīja: Tu man esi asins brūtgāns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Tad Viņš no tā atstājās; bet tā sacīja: asins brūtgāns, tās apgraizīšanas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Tad Tas Kungs sacīja uz Āronu: ej Mozum pretī uz tuksnesi. Un viņš gāja un to sastapa pie Tā Dieva kalna, un viņš to skūpstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Un Mozus teica Āronam visus tos vārdus, ar ko Tas Kungs viņu bija sūtījis, un par visām zīmēm, ko Tas viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Tad Mozus un Ārons gāja un sapulcēja visus Israēla bērnu vecajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Un Ārons runāja visus tos vārdus, ko Tas Kungs bija sacījis uz Mozu, un viņš darīja tās zīmes to ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Un tie ļaudis ticēja. Un tie dzirdēja, ka Tas Kungs piemeklējis Israēla bērnus un ka tas redzējis viņu spaidīšanu, un tie klanījās un pielūdza Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Un pēc tam Mozus un Ārons gāja un sacīja uz Faraonu: tā saka Tas Kungs, Israēla Dievs: atlaid manus ļaudis, ka tie man svētkus tur tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Bet Faraons sacīja: kas tas tāds Kungs, kā balsij man būs klausīt un Israēli atlaist? Es To Kungu nepazīstu, un Israēli arī neatlaidīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Tad tie sacīja: tas Ebreju Dievs mūs ir sastapis, lai mēs ejam treju dienu gājumu tuksnesī, upurēt Tam Kungam, savam Dievam, lai Viņš pār mums nenāk ar mēri vai ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Tad Ēģiptes ķēniņš uz tiem sacīja: jūs, Mozus un Ārons, - kam jūs tos ļaudis atturat no viņu darbiem? Ejat pie savas kalpošanas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Vēl Faraons sacīja: redzi, ļaužu tai zemē tā jau daudz, un jūs tos vēl gribat atturēt no viņu kalpošanas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Un Faraons tai dienā ļaužu uzraugiem un virsniekiem pavēlēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Jums turpmāk nebūs tiem ļaudīm dot salmus pie ķieģeļu taisīšanas, kā vakar un aizvakar; tiem pašiem būs iet un sev salmus meklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Un to ķieģeļu pulku, ko tie citkārt taisījuši, jums tiem tā pat būs uzlikt, jums no tiem neko nebūs atraut; jo tie ir bez darba, tādēļ tie brēc un saka: iesim, upurēsim savam Dievam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Lai tiem vīriem tā kalpošana top grūtāka, ka tiem ir darbs, un tie negriežās pie blēņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Tad tie ļaužu uzraugi un virsnieki izgāja un runāja uz tiem ļaudīm sacīdami: Tā saka Faraons: es jums vairs nedošu salmus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Ejat paši, dabūjiet sev salmus kur dabūdami, bet no jūsu darba nekas netaps atlaists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Tad tie ļaudis izklīda pa visu Ēģiptes zemi, ka tie rugājus sakrātu salmu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Un tie uzraugi tos spieda, sacīdami: Pabeidziet savu dienas darbu it tāpat, kā kad jums salmi bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Un Israēla bērnu uzraugi, ko Faraona virsnieki pār tiem bija iecēluši, tapa sisti, un uz tiem sacīja: kāpēc jūs neesat pabeiguši savu nospriesto darbu pie ķieģeļu dedzināšanas kā papriekš, ne vakar, ne šodien?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Tad Israēla bērnu uzraugi gāja un brēca uz Faraonu un sacīja: kāpēc tu saviem kalpiem tā dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Taviem kalpiem salmus nedod, un mums saka: taisāt ķieģeļus; un redzi, tavi kalpi top sisti, un tā ir tavas tautas vaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Tad Faraons sacīja: jūs esat sliņķi, sliņķi jūs esat, tāpēc jūs sakāt, iesim, upurēsim Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Tad nu ejat pie darba, salmus jums nedos, bet ķieģeļu skaits jums jātaisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Tad Israēla bērnu uzraugi redzēja, ka viņi postā, tāpēc ka sacīja: jums nebūs atraut no nospriestā dienas darba ķieģeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Un tie sastapa Mozu un Āronu, kas tur stāvēja tos sagaidīt, kad tie no Faraona izgāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Un sacīja uz tiem: lai Tas Kungs jūs redz un soda, tāpēc ka jūs mūsu smaržu esat smirdošu darījuši pie Faraona un pie viņa kalpiem, viņiem rokā dodami zobenu, mūs nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Tad Mozus atgriezās pie Tā Kunga un sacīja: Kungs, kāpēc Tu šiem ļaudīm esi darījis ļaunu? Kāpēc tad Tu mani esi sūtījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Jo kamēr es esmu gājis pie Faraona, runāt Tavā vārdā, viņš tiem ļaudīm dara ļaunu, un Tu Savus ļaudis glābt neesi glābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Tad Tas Kungs sacīja uz Mozu: nu tev būs redzēt, ko Es Faraonam darīšu, jo caur stipru roku viņam tos būs atlaist, un caur stipru roku viņam tos būs izdzīt no savas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Un Dievs runāja ar Mozu un uz to sacīja: Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Un Es esmu parādījies Ābrahāmam, Īzakam un Jēkabam, kā tas visuvarenais Dievs, bet Mans vārds “Kungs” viņiem nav bijis zināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Es arī esmu uzcēlis Savu derību ar tiem, tiem dot Kanaāna zemi, to zemi, kur viņi piemituši, kur tie bijuši svešinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Es arī esmu dzirdējis Israēla bērnu nopūtas, ko ēģiptieši kalpina, un esmu pieminējis Savu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Tāpēc saki Israēla bērniem: Es esmu Tas Kungs un jūs izvedīšu no Ēģiptes nastām un jūs izraušu no viņu kalpošanas un jūs atpestīšu ar izstieptu roku un ar lielām sodībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Un Es jūs pieņemšu par Saviem ļaudīm un jums būšu par Dievu, un jūs atzīsiet, ka Es esmu Tas Kungs, jūsu Dievs, kas jūs izvedis no Ēģiptes nastām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Un Es jūs ievedīšu tai zemē, par ko Es Savu roku esmu uzcēlis, to dot Ābrahāmam, Īzakam un Jēkabam, un došu jums to par īpašumu, Es, Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Un Mozus runāja tā uz Israēla bērniem; bet tie Mozum neklausīja aiz sirdēstiem un grūtiem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Un Tas Kungs runāja uz Mozu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Ej, runā uz Faraonu, Ēģiptes ķēniņu, ka tam Israēla bērnus būs izlaist no savas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Un Mozus runāja Tā Kunga priekšā un sacīja: redzi, Israēla bērni man neklausa, kā tad Faraons man klausītu? Un man ir arī neapgraizītas lūpas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Un Tas Kungs runāja uz Mozu un Āronu, un tos sūtīja ar pavēli pie Israēla bērniem un pie Faraona, Ēģiptes ķēniņa, Israēla bērnus izvest no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Šie ir viņu tēvu namu galvinieki: Rūbena, Israēla pirmdzimtā, bērni: Hanoks un Pallus, Hecrons un Karmus; šie ir Rūbena dzimumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Un Sīmeana bērni: Jemuels un Jamins un Oāds un Jakins un Coārs un Sauls, vienas Kanaānietes dēls, šie ir Sīmeana dzimumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Un šie ir Levja bērnu vārdi pēc viņu radiem: Geršons un Kehāts un Merarus. Un Levja dzīvības laiks bija simts trīsdesmit un septiņi gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Geršona bērni: Libnus un Šimejus pēc viņu dzimumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Un Kehāta bērni: Amrams un Jecears un Hebrons un Uzijels. Un Kehāta dzīvības laiks bija simts trīsdesmit un trīs gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merarus bērni: Maēlus un Muzus; šie ir Levja dzimumi pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Un Amrams ņēma par sievu Joķebedu, sava tēva māsu, un tā viņam dzemdēja Āronu un Mozu. Un Amrama dzīvības laiks bija simts trīsdesmit un septiņi gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Un Jeceara bērni: Korahs un Nevegs un Sihrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Un Uzijeļa bērni: Mišaēls un Elcavans un Zitrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Un Ārons ņēma sev par sievu Elizebu, Aminadaba meitu, Naāsana māsu, un tā viņam dzemdēja Nadabu un Abiju un Eleazaru un Ītamaru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Un Koraha bērni: Asirs un Elkanus un AbiAsafs; šie ir Koriešu dzimumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Un Eleazars, Ārona dēls, ņēma sev sievu no Putijeļa meitām; un tā viņam dzemdēja Pinehasu. Šie ir Levitu tēvu namu galvinieki pēc viņu dzimumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Šis ir tas Ārons un Mozus, kam Tas Kungs sacīja: izvediet Israēla bērnus no Ēģiptes zemes ar viņu pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Šie ir, kas uz Faraonu, Ēģiptes ķēniņu, runāja, izvest Israēla bērnus no Ēģiptes zemes, proti Mozus un Ārons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Un tai dienā, kad Tas Kungs runāja uz Mozu Ēģiptes zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Tad Viņš runāja uz Mozu un sacīja: Es esmu Tas Kungs, - runā uz Faraonu, Ēģiptes ķēniņu, visu, ko Es uz tevi runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Tad Mozus sacīja Tā Kunga priekšā: redzi, man ir neapgraizītas lūpas, kā tad Faraons mani klausīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Tad Tas Kungs sacīja uz Mozu: redzi, Es tevi Faraonam esmu licis par Dievu, un Āronam, tavam brālim, būs būt tavam pravietim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tev būs runāt visu, ko es tev pavēlēšu, un Āronam tavam brālim, būs runāt uz Faraonu, ka tam būs atlaist Israēla bērnus no savas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Un es apcietināšu Faraona sirdi un vairošu savas zīmes un savus brīnumus Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Un Faraons jums neklausīs, un Es likšu Savu roku uz Ēģiptes zemi un izvedīšu Savu pulku, Savus ļaudis, Israēla bērnus, no Ēģiptes zemes caur lielām sodībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Un ēģiptiešiem būs atzīt, ka Es esmu Tas Kungs, kad Es Savu roku izstiepju pār Ēģiptes zemi un Israēla bērnus izvedu no viņu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Tad Mozus un Ārons darīja, kā Tas Kungs tiem bija pavēlējis, - tā tie darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Un Mozus bija astoņdesmit gadus vecs un Ārons astoņdesmit un trīs gadus vecs, kad tie runāja uz Faraonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Un Tas Kungs runāja uz Mozu un Āronu un sacīja: kad Faraons ar jums runās un sacīs, rādiet savus brīnumus, tad tev būs Āronam sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Ņem savu zizli un nomet to Faraona priekšā, ka tas top par čūsku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Tad Mozus un Ārons gāja pie Faraona un darīja tā, kā Tas Kungs bija pavēlējis; un Ārons nometa savu zizli Faraona priekšā un viņa kalpu priekšā, un tas tapa par čūsku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Tad Faraons sauca tos gudros un tos burvjus, un Ēģiptes burvji darīja arīdzan tā ar savām buršanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Un ikviens nometa savu zizli, un tie tapa par čūskām, bet Ārona zizlis aprija viņu zižļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Tomēr Faraona sirds apcietinājās, tā ka viņš tiem neklausīja, kā Tas Kungs bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Tad Tas Kungs sacīja uz Mozu: Faraona sirds ir cieta, viņš liedzās, tos ļaudis atlaist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Ej rītu pie Faraona; redzi, viņš ies ārā pie ūdens; ej viņam pretim upes malā, un ņem savā rokā to zizli, kas par čūsku bijis pārvērsts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Un saki uz viņu: Tas Kungs, tas Ebreju Dievs, mani sūtījis pie tevis sacīdams: atlaid Manus ļaudis, ka tie Man kalpo tuksnesī! - Bet redzi, tu līdz šim neesi klausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Tā saka Tas Kungs: pie tā tev būs atzīt, ka Es esmu Tas Kungs: redzi, es sitīšu ar to zizli, kas manā rokā, pār upes ūdeņiem, tad tie pārvērtīsies par asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Un tās zivis, kas upē, nomirs, tā ka upe smirdēs un ēģiptiešiem riebsies ūdeni dzert no upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Un Tas Kungs sacīja uz Mozu: Saki Āronam: ņem savu zizli un izstiep savu roku pār Ēģiptes ūdeņiem un pār viņu strautiem un pār viņu ezeriem un pār visiem viņu ūdens krājumiem, ka tie pārvēršās par asinīm; un asinis būs visā Ēģiptes zemē, koku un akmeņu traukos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Tad Mozus un Ārons darīja tā, kā Tas Kungs bija pavēlējis, un viņš pacēla to zizli un sita to upes ūdeni, Faraonam redzot un viņa kalpiem redzot tad viss ūdens upē pārvērtās par asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Un zivis upē apmira, un upe smirdēja, un ēģiptieši nevarēja dzert to ūdeni no upes, un visā Ēģiptes zemē bija asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Un Ēģiptes burvji darīja tāpat ar savu buršanu, tā ka Faraona sirds apcietinājās, un viņš tiem neklausīja, kā Tas Kungs bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Un Faraons griezās atpakaļ un nāca savā namā un arī to neņēma pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Bet visi ēģiptieši raka ap upi pēc ūdens, ko dzert, jo no ūdens upē nevarēja dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Un tā pagāja pilnas septiņas dienas, kamēr Tas Kungs upi bija sitis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Tad Tas Kungs sacīja uz Mozu: ej pie Faraona un saki tam: tā saka Tas Kungs: atlaid Manus ļaudis, ka tie Man kalpo;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Un ja tu liegsies, tos atlaist, redzi, tad Es visas tavas robežas sitīšu ar vardēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Ka upe kustin kustēs ar vardēm, un tās celsies un nāks tavā namā un tavā guļamā kambarī un uz tavu gultu un tavu kalpu namos un pār taviem ļaudīm un tavos cepļos un tavās abrās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Un vardes nāks uz tevi un uz taviem ļaudīm un uz taviem kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Tad Tas Kungs sacīja uz Mozu: saki Āronam: izstiep savu roku ar savu zizli pār strautiem, pār upēm un pār ezeriem, un liec vardēm nākt pār Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Un Ārons izstiepa savu roku pār Ēģiptes ūdeņiem, tad nāca vardes un apklāja Ēģiptes zemi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Un tie burvji darīja arīdzan tā ar savu buršanu un lika vardēm nākt pār Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Tad Faraons aicināja Mozu un Āronu un sacīja: lūdziet To Kungu, ka Viņš tās vardes atņemtu no manis un no maniem ļaudīm; tad es tos ļaudis atlaidīšu, upurēt Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Bet Mozus sacīja uz Faraonu: saki man jel, kad man būs lūgt tevis dēļ un tavu kalpu un tavu ļaužu labad, lai tās vardes tiek izdeldētas, ka vairs nav pie tevis nedz tavā namā, bet paliek upē vien?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Un viņš sacīja: rītu. Un tas sacīja: lai ir pēc tava vārda; lai tu atzīsti, ka neviens nav kā Tas Kungs, mūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Tām vardēm būs atstāties no tevis un no tava nama un no taviem kalpiem un no taviem ļaudīm; upē vien tām būs palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Tad Mozus un Ārons aizgāja no Faraona, un Mozus sauca uz To Kungu to varžu dēļ, kā viņš Faraonam bija apsolījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Un Tas Kungs darīja pēc Mozus vārda, un tās vardes nomira namos, sētās un uz laukiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Un tie tās meta kopās, un zeme smirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Kad nu Faraons redzēja, ka bija dabūjis atvieglināšanu, tad viņš apcietināja savu sirdi un tiem neklausīja, kā Tas Kungs bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Tad Tas Kungs sacīja uz Mozu: saki Āronam: izstiep savu zizli un sit zemes pīšļus, lai top par utīm pa visu Ēģiptes zemi, un tie tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Jo Ārons izstiepa savu roku ar savu zizli un sita zemes pīšļus, un utis radās pie cilvēkiem un pie lopiem; - visi zemes pīšļi palika par utīm pa visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Tad tie burvji darbojās arī tā ar savu buršanu, likt utīm nākt; bet tie nevarēja. Tā bija utis pie cilvēkiem un pie lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Tad tie burvji sacīja uz Faraonu: šis ir Dieva pirksts. Tomēr Faraona sirds apcietinājās, un viņš tiem neklausīja, tā kā Tas Kungs bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Tad Tas Kungs sacīja uz Mozu: celies rīt agri un stājies Faraona priekšā: redzi, viņš izies pie ūdens, - un runā uz to: tā saka Tas Kungs: atlaid Manus ļaudis, lai tie Man kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Bet ja tu Manus ļaudis neatlaidīsi, tad Es sūtīšu visādus kukaiņus pār tevi un pār taviem kalpiem un pār taviem ļaudīm un tavos namos, un visādiem kukaiņiem būs piepildīt ēģiptiešu namus un to zemi, kur tie ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Un tanī dienā Es izšķiršu Gošenes zemi, kur Mani ļaudis dzīvo, ka tur nebūs kukaiņiem būt, lai tu atzīsti, ka Es Tas Kungs esmu pa visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Un Es darīšu starpību starp Maniem ļaudīm un taviem ļaudīm; rīt šai zīmei būs notikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Un Tas Kungs darīja tā, un kukaiņi nāca bariem Faraona namā un viņa kalpu namos un pa visu Ēģiptes zemi, un zeme tapa maitāta no kukaiņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Tad Faraons aicināja Mozu un Āronu un sacīja: ejat un upurējat savam Dievam šinī zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Bet Mozus sacīja: tā nevar darīt; jo, kas ēģiptiešiem negantība, to mēs upurētu Tam Kungam, savam Dievam. Redzi, ja tad mēs, kas ēģiptiešiem negantība, upurētu viņu priekšā, vai tie mūs ar akmeņiem nenomētātu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Mēs iesim kādu treju dienu gājumu tuksnesī un upurēsim Tam Kungam, savam Dievam, kā Viņš mums ir sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Tad Faraons sacīja: es jūs atlaidīšu, upurēt Tam Kungam, savam Dievam; tikai neaizejiet visai tālu,- lūdziet par mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Tad Mozus sacīja: redzi, es aizeju no tevis un lūgšu To Kungu, ka šiem kukaiņiem rītu būs atstāties no Faraona un no viņa kalpiem un no viņa ļaudīm; tikai Faraonam nebūs vairs mani pievilt, neatlaižot tos ļaudis, upurēt Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Tad Mozus aizgāja no Faraona un lūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Un Tas Kungs darīja pēc Mozus vārda, un tie kukaiņi atstājās no Faraona, no viņa kalpiem un no viņa tautas, ka tur neviens nepalika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Tomēr Faraons arī šo reiz apcietināja savu sirdi un neatlaida tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Tad Tas Kungs sacīja uz Mozu: ej pie Faraona un runā uz to: tā saka Tas Kungs, tas Ebreju Dievs: atlaid Manus ļaudis, ka tie Man kalpo;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Jo ja tu liegsies, tos atlaist un tos vēl ilgāki aizturēsi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Redzi, tad Tā Kunga roka būs pār tavu ganāmupulku, kas ir laukā, pār zirgiem, pār ēzeļiem, pār kamieļiem, pār vēršiem un pār sīkiem lopiem ar varen grūtu mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Un Tas Kungs darīs brīnišķu starpību starp Israēla lopiem un ēģiptiešu lopiem, ka tur no visa, kas Israēla bērniem pieder, nevienam nebūs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Un Tas Kungs nolika īpašu laiku un sacīja: rītu Tas Kungs to darīs šinī zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Un Tas Kungs to darīja tai nākošā dienā, un visi ēģiptiešu lopi nomira, bet no Israēla bērnu lopiem nemira neviens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Un Faraons nosūtīja, un redzi (patiesi), no Israēla lopiem nebija neviens nomiris. Bet Faraona sirds apcietinājās un viņš neatlaida tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Tad Tas Kungs sacīja uz Mozu un Āronu: ņemat pilnas saujas pelnu no krāsns, un lai Mozus tos kaisa pret debesīm Faraonam redzot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Ka tie izput pār visu Ēģiptes zemi un paliek par trumiem, kas izsitās ar pūtēm pie cilvēkiem un pie lopiem pa visu Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Un tie ņēma pelnus no krāsns un stājās Faraona priekšā, un Mozus tos kaisīja pret debesīm, - tad izsitās trumi ar pūtēm pie cilvēkiem un pie lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Tā ka tie burvji priekš Mozus nevarēja stāvēt to trumu dēļ, jo trumi bija pie tiem burvjiem un pie visiem ēģiptiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Bet Tas Kungs apcietināja Faraona sirdi, ka tas tiem neklausīja, kā Tas Kungs uz Mozu bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Tad Tas Kungs sacīja uz Mozu: celies rīt agri un stājies Faraona priekšā un runā uz to: tā saka Tas Kungs, tas Ebreju Dievs, atlaid Manus ļaudis, ka tie Man kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Jo šo brīdi Es sūtīšu visas Savas mocības tavā sirdī un pār taviem kalpiem un pār taviem ļaudīm, ka tev būs atzīt, ka neviens nav tāds kā Es pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Jo Es Savu roku jau būtu izstiepis un tevi un tavus ļaudis sitis ar mēri, ka tu no zemes būtu izdeldēts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Bet patiesi, tāpēc Es tevi esmu taupījis, ka Es Savu spēku pie tevis parādītu, un ka Mans vārds taptu teikts pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Vai tu vēl celies pret Maniem ļaudīm, negribēdams tos atlaist?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Redzi, rīt ap šo laiku Es likšu krist varen lielai krusai, kāda vēl nav bijusi Ēģiptes zemē no tās dienas, kamēr tā ir celta, līdz šim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Un nu sūti un sadzen savus lopus, un visu, kas tev ir uz lauka; visi cilvēki un lopi, kas laukā atradīsies un pajumtā nebūs sadzīti, tie nomirs, kad šī krusa uz viņiem kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kurš nu no Faraona kalpiem Tā Kunga vārdu bijās, tas saviem kalpiem un saviem lopiem lika bēgt pajumtā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Bet kurš savā sirdi Tā Kunga vārdu nelika vērā, tas savus kalpus un savus lopus pameta laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Tad Tas Kungs sacīja uz Mozu: izstiep savu roku pret debesīm, un lai krusa nāk visā Ēģiptes zemē pār cilvēkiem un pār lopiem un pār visiem lauka augļiem Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Un Mozus izstiepa savu zizli pret debesīm. Un Tas Kungs izlaida pērkonus un krusu, un uguns nošāvās uz zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Un Tas Kungs lika krusai līt pār Ēģiptes zemi, un tur bija krusa un uguns laistījās krusā, ļoti briesmīgs, kāds nav bijis Ēģiptes zemē, kamēr ļaudis tur bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Un krusa apsita visā Ēģiptes zemē visu, kas bija laukā, cilvēkus līdz ar lopiem, un visus lauka augļus krusa apsita un salauzīja visus kokus laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Tik Gošenes zemē vien, kur Israēla bērni dzīvoja, krusas nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Tad Faraons sūtīja un aicināja Mozu un Āronu un tiem sacīja: es šo brīdi esmu grēkojis; Tas Kungs ir taisns, bet es un mani ļaudis esam bezdievīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Lūdziet To Kungu, lai ir gan (pietiek), ka Dieva pērkoni un krusa apstātos, tad es jūs atlaidīšu un jums vairs nebūs palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Tad Mozus uz viņu sacīja: kad no pilsētas iziešu, es savas rokas izstiepšu uz To Kungu, tad pērkoni mitēsies, un krusas vairs nebūs, lai tu atzīsti, ka tā zeme pieder Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Tomēr tevi un tavus kalpus es zinu, ka jūs vēl nebīsities Dievu, To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Tā tapa apsisti lini un mieži, jo mieži bija izplaukuši, un liniem jau bija galviņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Bet kvieši un rudzi netapa apsisti, jo tie bija vēlu sēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Tad Mozus aizgāja no Faraona, no pilsētas ārā, un izstiepa savas rokas uz To Kungu, un pērkoni un krusa mitējās, un lietus vairs negāzās zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Kad nu Faraons redzēja, ka lietus un krusa un pērkoni mitējās, tad viņš vēl vairāk apgrēkojās un apcietināja savu sirdi, viņš un viņa kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Tā Faraona sirds apcietinājās, ka viņš Israēla bērnus neatlaida, kā Tas Kungs caur Mozu bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Un Tas Kungs sacīja uz Mozu: ej pie Faraona, jo Es esmu apcietinājis viņa sirdi un viņa kalpu sirdi, lai Es šās Savas zīmes daru viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Un lai tu stāsti priekš savu bērnu un bērnu bērnu ausīm, ko Es Ēģiptes zemē esmu darījis, un Manas zīmes, ko Es tur esmu cēlis, un lai jūs atzīstat, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Tad Mozus un Ārons gāja pie Faraona un uz to sacīja: tā saka Tas Kungs, tas Ebreju Dievs: cik ilgi tu liedzies pazemoties priekš Mana vaiga? Atlaid Manus ļaudis, ka tie Man var kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Jo ja tu liegsies, atlaist Manus ļaudis, redzi, tad Es rītu vedīšu siseņus tavās robežās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Un tie apklās visu zemes virsu, tā ka zemi neredzēs, un tie ēdīs to pēdējo, kas jums atlicis un palicis no krusas, un noēdīs visus jūsu kokus, kas jums zaļo laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Un tie piepildīs tavus namus un visu tavu kalpu namus un visu ēģiptiešu namus; tādus ne tavi tēvi, ne tavu tēvu tēvi nav redzējuši no tās dienas, kamēr tie virs zemes bijuši, līdz šim; un viņš griezās un aizgāja no Faraona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Un Faraona kalpi sacīja uz viņu: cik ilgi tas mums būs par slazda valgu? Atlaid tos ļaudis, lai tie kalpo Tam Kungam, savam Dievam; vai tu vēl neredzi, ka Ēģiptes zeme iet bojā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Tad Mozus un Ārons atkal pie Faraona tapa atvesti, un viņš uz tiem sacīja: ejat un kalpojiet Tam Kungam, savam Dievam! Kas tie visi ir, kas grib noiet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Un Mozus sacīja: mēs iesim ar saviem jauniem un veciem, ar saviem dēliem un ar savām meitām; mēs iesim ar saviem maziem un lieliem lopiem, jo mums ir Tā Kunga svētki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Tad viņš uz tiem sacīja: lai Tas Kungs jums tā palīdz, kā es jūs un jūsu bērnus atlaidīšu! Redziet, kāds ļaunums jums prātā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nē, nē, ejat jūs vīri un kalpojiet Tam Kungam, jo to jūs arī esat meklējuši. Un tos izstūma no Faraona vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Tad Tas Kungs sacīja uz Mozu: izstiep savu roku pār Ēģiptes zemi siseņu dēļ, ka tie nāk pār Ēģiptes zemi un noēd visu zemes zāli, visu, ko krusa ir atlicinājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Tad Mozus izstiepa savu zizli pār Ēģiptes zemi, un Tas Kungs deva austriņu(austruma vējš) tai zemē cauru dienu un cauru nakti; un kad rīts ausa, tad tas austriņš uzveda siseņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Un siseņi uznāca pār visu Ēģiptes zemi un nolaidās visās Ēģiptes robežās lielā pulkā; priekš tiem tādu siseņu nav bijis, un pēc tiem vairs tādu nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Jo tie apklāja visu zemes virsu, un zeme tapa aptumšota, un tie noēda visu zemes zāli un visus koku augļus, ko krusa bija atlicinājusi, un tur nepalika vairs zaļuma ne pie kokiem, ne pie lauka zāles visā Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Tad Faraons traucās aicināt Mozu un Āronu un sacīja: es esmu grēkojis pret To Kungu, jūsu Dievu, un pret jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Un nu piedod lūdzams manus grēkus tikai šo reiz, un lūdziet To Kungu, savu Dievu, ka Viņš šo nāvi gribētu atņemt no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Un viņš aizgāja no Faraona un lūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Tad Tas Kungs deva ļoti stipru vakara vēju; tas pacēla tos siseņus un tos iemeta niedru jūrā, ka neviens sisenis neatlika visās Ēģiptes robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Tomēr Tas Kungs apcietināja Faraona sirdi, un tas Israēla bērnus neatlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Tad Tas Kungs sacīja uz Mozu: izstiep savu roku pret debesīm, ka tumsa nāk pār Ēģiptes zemi, ka tumsu var sataustīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Un Mozus izstiepa savu roku pret debesīm, tad cēlās bieza tumsa visā Ēģiptes zemē trīs dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Neviens otru neredzēja, un neviens trejās dienās necēlās no savas vietas; bet visiem Israēla bērniem bija gaisma viņu mājokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Tad Faraons aicināja Mozu un sacīja: ejat, kalpojiet Tam Kungam, bet jūsu sīkiem lopiem un vēršiem būs palikt tepat; lai arī jūsu bērni iet jums līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Bet Mozus sacīja: tev būs arī mūsu rokā dot kaujamus upurus un dedzināmos upurus, ko pienest Tam Kungam, savam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Mūsu lopiem arīdzan būs mums iet līdz; nevienam nadziņam nebūs palikt atpakaļ; jo no tiem mēs ņemsim, Tam Kungam, savam Dievam kalpot; jo mēs nezinām, kā mums Tam Kungam jākalpo, tiekams mēs turp nāksim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Bet Tas Kungs apcietināja Faraona sirdi, un tas negribēja tos atlaist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Un Faraons uz viņu sacīja: ej nost no manis; sargies, ka tu vairs nenāci man priekš acīm; jo kurā dienā tu nāksi man priekš acīm, tev būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Tad Mozus sacīja: lai tā ir, kā tu esi sacījis; es tavu vaigu vairs neredzēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Un Tas Kungs sacīja uz Mozu: Vēl vienu mocību Es vedīšu pār Faraonu un pār Ēģiptes zemi; pēc tam viņš jūs atlaidīs no šejienes; kad viņš jūs pilnīgi atlaidīs, tad viņš dzītin jūs izdzīs no šejienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Runā jel priekš to ļaužu ausīm, lai ikviens vīrs no sava tuvākā un ikviena sieva no savas tuvākās prasa sudraba traukus un zelta traukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Un Tas Kungs tiem ļaudīm deva žēlastību ēģiptiešu acis; un tas vīrs Mozus bija ļoti augsti turēts Ēģiptes zemē Faraona kalpu acis un to ļaužu acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Un Mozus sacīja: tā Tas Kungs saka: ap pusnakti Es iziešu pa Ēģiptes vidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Un visiem pirmdzimušiem Ēģiptes zemē būs mirt, no Faraona pirmdzimušā, kas sēž uz goda krēsla, līdz kalpones pirmdzimušam, kas ir aiz dzirnavām, un visiem lopu pirmdzimušiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Un liela brēkšana būs Ēģiptes zemē, kāda nav bijusi un kāda vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Bet pie visiem Israēla bērniem ne suns savu mēli nekustinās, no cilvēkiem līdz lopiem, lai jūs ziniet, ka Tas Kungs dara starpību starp ēģiptiešiem un Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Tad visi šie tavi kalpi nonāks pie manis un klanīsies priekš manis un sacīs: izej, tu un visi ļaudis, kas tev ir padoti, un pēc tam es iziešu. Un viņš aizgāja no Faraona bargās dusmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Bet Tas Kungs sacīja uz Mozu: Faraons jums neklausīs, lai daudz Manu brīnumu notiek Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Un Mozus un Ārons darīja visus šos brīnumus Faraona priekšā; bet Tas Kungs lika Faraona sirdij apcietināties, ka tas Israēla bērnus neatlaida no savas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Un Tas Kungs runāja uz Mozu un Āronu Ēģiptes zemē un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Šis mēnesis lai pie jums ir tas pirmais un no šī mēneša jums būs iesākt gadu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Runājiet uz visu Israēla draudzi un sakāt: šī mēneša desmitā dienā lai tie ņem, ikviens nama tēvs, vienu jēru, uz ikvienu namu vienu jēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Bet ja kāds nams ir par mazu priekš viena jēra, tad lai viņš un šī nama tuvākais kaimiņš ņem vienu pēc dvēseļu skaita; pēc tā mēra, cik ikviens var apēst, būs skaitīt uz to jēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Jēru bez vainas jums būs ņemt, auniņu, vienu gadu vecu. No avīm un kazām jums to būs ņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Un jums to būs glabāt līdz šī mēneša četrpadsmitai dienai, un visai Israēla draudzes sapulcei to būs nokaut ap vakaru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Un būs ņemt no tām asinīm un aptraipīt abējus durvju stenderus un to palodu pie tiem namiem, kur to ēdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Un būs ēst to gaļu tanī naktī, pie uguns ceptu, ar neraudzētu maizi, ar rūgtām zālēm tiem to būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Jums to nebūs ēst jēlu, nedz ūdenī vārītu, bet pie uguns ceptu, viņa galvu ar viņa lieliem un ar viņa iekšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Jums arī no tā nebūs neko atlicināt līdz rītam, bet kas no tā līdz rītam atliek, to jums ar uguni būs sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Tā jums to nu būs ēst: jūsu gurni lai ir apjozti, jūsu kurpes kājās un jūsu spieķi rokās, un jums to būs steigšus ēst; tas ir Tā Kunga Pasa (saudzēšana).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Jo šinī naktī Es pārstaigāšu Ēģiptes zemi un sitīšu visus pirmdzimtos Ēģiptes zemē, no cilvēkiem līdz lopiem. Es parādīšu sodību pie visiem ēģiptiešu dieviem, Es, Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Un tām asinīm jums būs par zīmi būt pie tiem namiem, kur jūs esat. Kad Es tās asinis redzēšu, tad Es jums iešu garām, un pie jums nebūs tā mocība, kas samaitā, kad Es Ēģiptes zemi sitīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Un šī diena jums būs par piemiņu, un jums to būs svētīt Tam Kungam par svētkiem, uz bērnu bērniem par mūžīgu likumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Septiņas dienas jums būs ēst neraudzētu maizi; bet pirmā dienā raugu būs izmest no jūsu namiem; jo ikkatrs, kas ēd raudzētu maizi, no pirmās dienas līdz septītai, tā dvēsele lai top izdeldēta no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Un pirmā dienā būs būt svētai sapulcei, un arī septītā dienā būs būt svētai sapulcei; iekš tām jums nekāda darba nebūs darīt, tik vien, ko kurš ēd, to jūs varat sataisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Tad nu turiet to neraudzēto maizi; tāpēc ka Es tai dienā jūsu spēku esmu izvedis no Ēģiptes zemes, un turiet šo dienu pie saviem pēcnākamiem kā mūžīgu likumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Pirmā mēnesī, četrpadsmitā mēneša dienā, vakarā jums būs ēst neraudzētu maizi līdz divdesmit pirmās dienas vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Septiņas dienas raugs lai netop atrasts jūsu namos, jo kas raudzētu maizi ēdīs, tā dvēsele lai top izdeldēta no Israēla draudzes, vai būtu svešinieks, vai iedzīvotājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Jums nekā raudzēta nebūs ēst; visās jūsu mājvietās jums būs ēst neraudzētu maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Tad Mozus aicināja visus Israēla vecajus un uz tiem sacīja: ķerat un ņemat sev jērus priekš savām saimēm un nokaujiet to Pasa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Un ņemiet īzapu pušķi un mērciet to tanīs asinīs, kas bļodā, un aptraipiet palodu un abas stenderes ar tām asinīm, kas bļodā; bet nevienam nebūs iziet pa savām nama durvīm līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Jo Tas Kungs ies garām, sist ēģiptiešus; bet kad viņš redzēs tās asinis pie palodas un pie abām stenderēm, tad Tas Kungs tām durvīm ies garām un samaitātājam neļaus ieiet jūsu namos uz mocību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Tāpēc turat šo lietu par iestādījumu pie sevis un saviem bērniem mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Un kad jūs nāksiet tai zemē, ko Tas Kungs jums dos, kā Viņš ir runājis, tad jums šo Dieva kalpošanu būs turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Un kad jūsu bērni uz jums sacīs: kas jums tā tāda Dieva kalpošana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Tad jums būs sacīt: tas ir tas Pasa upuris Tam Kungam, kas Israēla bērnu namiem aizgāja garām Ēģiptes zemē, kad viņš sita ēģiptiešus un mūsu namus izglāba. Tad tie ļaudis liecās pie zemes un pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Un Israēla bērni gāja un darīja, kā Tas Kungs Mozum un Āronam bija pavēlējis; tā tie darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Un nakts vidū Tas Kungs sita visus pirmdzimušos Ēģiptes zemē, no Faraona pirmdzimušā, kam uz viņa krēsla bija jāsēž, līdz cietumnieka pirmdzimušam, kas cietumā bija, un visus lopu pirmdzimtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Tad Faraons cēlās naktī un visi viņa kalpi un visi ēģiptieši, un liela brēkšana bija Ēģiptes zemē, jo neviens nams nebija, kur nebija miroņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Un viņš aicināja Mozu un Āronu naktī un sacīja: ceļaties, izejat no manu ļaužu vidus, gan jūs, gan Israēla bērni, un noejat, kalpojiet Tam Kungam pēc jūsu vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ņemiet arīdzan līdz savus sīkos un lielos lopus, itin kā jūs esat runājuši, un noejat un svētījiet mani arīdzan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Un ēģiptieši spieda tos ļaudis, lai tos steigšus izdzītu no zemes; jo tie sacīja: mums visiem jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Un tie ļaudis nesa savu mīklu, pirms tā bija saraudzēta, tās abras, savās drēbēs iesietas, uz saviem pleciem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Un Israēla bērni bija darījuši pēc Mozus vārda un prasījuši no ēģiptiešiem sudraba traukus un zelta traukus un drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Tas Kungs tiem ļaudīm arī bija žēlastību devis ēģiptiešu priekšā, ka tie viņiem deva; un viņi aplaupīja ēģiptiešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Tā Israēla bērni izgāja no Raēmzes uz Sukotu, kādi sešsimt tūkstoš vīri kājām bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Un līdz ar tiem izgāja vēl visādi piedzīvotāji un sīki lopi un lieli lopi, varen daudz lopu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Un no tās mīklas, ko tie bija nesuši no Ēģiptes zemes, tie cepa neraudzētas karašas; jo tā nebija raudzēta; jo tie tapa izdzīti no Ēģiptes zemes, un tie nevarēja kavēties, nedz sev sataisīt ceļamaizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Un Israēla bērnu laiks, ko tie mituši Ēģiptes zemē, ir četrsimt un trīsdesmit gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Un kad tie četrsimt un trīsdesmit gadi bija pagājuši, tad tas notika; tai dienā viss Tā Kunga pulks izgāja no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Šo nakti Tam Kungam būs svētu turēt, tāpēc ka viņš tos izvedis no Ēģiptes zemes; šī ir tā nakts, ko Tam Kungam lai svētī visi Israēla bērni uz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Un Tas Kungs sacīja uz Mozu un Āronu: šis ir tas Pasa iestādījums. Nevienam svešiniekam no tā nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Bet ikvienam par naudu pirktam kalpam, kad tas apgraizīts, būs no tā ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Nevienam piedzīvotājam nedz algādzim no tā nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Vienā namā to būs ēst. Jums no tās gaļas nekā nebūs iznest no nama, un neviena kaula jums pie tā nebūs salauzt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Visai Israēla draudzei to būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Bet ja kāds svešinieks pie tevis mājo un Tam Kungam grib svētīt Pasa svētkus, tad lai viņam apgraiza visus vīriešus, un tad tas var nākt to svētīt; tad viņš būs tā kā viens, kas tai zemē dzimis, bet nevienam neapgraizītam nebūs no tā ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Vienādai bauslībai būs būt Israēla bērnam un svešiniekam, kas jūsu vidū piemīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Un visi Israēla bērni darīja, tā kā Tas Kungs Mozum un Āronam bija pavēlējis; tā tie darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Un tas notika, tanī pašā dienā Tas Kungs Israēla bērnus izveda no Ēģiptes zemes ar viņu pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Svēti Man visus pirmdzimušos, visus kas māti atplēš, starp Israēla bērniem, no cilvēkiem un no lopiem; tie Man pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Tad Mozus sacīja uz tiem ļaudīm: pieminiet šo dienu, kur jūs esat izgājuši no Ēģiptes zemes, no tā vergu nama, jo Tas Kungs ar stipru roku jūs ir izvedis no šejienes; tāpēc nekā raudzēta nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Šodien jūs izejat Abiba mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Un kad Tas Kungs jūs būs ievedis Kanaāniešu un Hetiešu un Amoriešu un Hiviešu un Jebusiešu zemē, ko Viņš jūsu tēviem zvērējis, tev dot, - zemi, kur piens un medus tek: tad tev ar tādu kalpošanu būs kalpot šai mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Septiņas dienas tev būs ēst neraudzētu maizi, un septītā dienā lai ir Tā Kunga svētki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Septiņas dienas būs ēst neraudzētu maizi, un raudzētu maizi lai neredz pie jums, un raugu lai neredz pie jums visās jūsu robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Un tev būs ziņu dot savam dēlam tai dienā un sacīt: tas ir tādēļ, ko Tas Kungs man darījis, kad es izgāju no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Un tam būs tev būt par zīmi tavā rokā un par piemiņas rakstu priekš tavām acīm, tāpēc lai Tā Kunga bauslība ir tavā mutē; jo ar stipru roku Tas Kungs tevi izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Tad nu turi šo iestādījumu īstenā laikā ik gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Un kad Tas Kungs tevi būs ievedis Kanaāniešu zemē, itin kā Viņš tev un taviem tēviem zvērējis, un tev to būs devis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Tad tev būs nodot Tam Kungam visu, kas māti atplēš, arī no taviem lopiem visu pirmdzimto; kas ir vīrietis, tam būs piederēt Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Bet visus pirmdzimtos no ēzeļa tev būs izpirkt ar vienu jēru, un ja tu to neizpirksi, tad nolauz viņam kaklu; bet ikvienu pirmdzimto no cilvēkiem starp jūsu bērniem jums būs izpirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Un kad tavs dēls šodien vai rītu tev vaicās un sacīs: kas tas ir? Tad tev būs tam sacīt: Tas Kungs mūs ar stipru roku ir izvedis no Ēģiptes, no tā vergu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Jo kad Faraons apcietinājās, mūs atlaist, tad Tas Kungs nokāva visus pirmdzimtos Ēģiptes zemē, no cilvēku pirmdzimtiem līdz lopu pirmdzimtiem; tādēļ es Tam Kungam upurēju visu, kas no vīriešu kārtas māti atplēš, bet visus savus pirmdzimtos dēlus es izpērku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Un tas būs par zīmi tavā rokā un par piemiņas rakstu priekš tavām acīm; jo Tas Kungs mūs ar stipru roku ir izvedis no Ēģiptes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Un kad Faraons tos ļaudis bija atlaidis, tad Dievs tos nevadīja pa Fīlistu zemes ceļu, jebšu tas bija īsāks, jo Dievs sacīja: lai tiem ļaudīm nepaliek žēl, kad tie redz karu, un lai tie atkal negriežās atpakaļ uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Bet Dievs tiem ļaudīm lika griezties pa tuksneša ceļu uz niedru jūru, un Israēla bērni izgāja apbruņoti no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Un Mozus ņēma Jāzepa kaulus līdz ar sevi; jo tas Israēla bērniem bija licis zvērēt it stipru zvērestu, sacīdams: Dievs jūs tiešām piemeklēs; tad vediet manus kaulus līdz ar sevi no šejienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Tā tie izgāja no Sukota un apmetās Etamā, tuksneša galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Un Tas Kungs gāja viņiem priekšā, dienu padebeša stabā, ka Viņš tos pa ceļu vadītu, un nakti uguns stabā, ka Viņš tiem spīdētu, iet dienu un nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Un tas padebeša stabs nenozuda dienā nedz tas uguns stabs naktī no ļaužu priekšas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Runā uz Israēla bērniem, lai tie griežas un apmet lēģeri pret Pi Hahirotleiju, starp Migdolu un jūru, šaipus Baāl Cevonas; tai pretī jums būs lēģeri apmest pie jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Tad Faraons sacīs no Israēla bērniem, tie ir apmaldījušies tai zemē, tuksnesis tiem ir visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Un Es apcietināšu Faraona sirdi, ka tas viņiem dzīsies pakaļ, un Es pagodināšos pie Faraona un pie visa viņa spēka, tā ka ēģiptiešiem būs atzīt, ka Es esmu Tas Kungs. Un tie tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Kad nu Ēģiptes ķēniņam tapa sacīts, tos ļaudis bēgam, tad Faraona un viņa kalpu sirdis pārvērtās pret tiem ļaudīm un tie sacīja: ko mēs esam darījuši, Israēli atlaizdami, ka tie mums vairs nekalpo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Un viņš iejūdza savus ratus un ņēma līdz savus ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Un viņš ņēma sešsimt izlasītus ratus un visus Ēģiptes zemes ratus un virsniekus pār tiem visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Un Tas Kungs apcietināja Faraona, Ēģiptes ķēniņa, sirdi, ka tas Israēla bērniem dzinās pakaļ; bet Israēla bērni izgāja caur augstu(stipru) roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Un ēģiptieši tiem dzinās pakaļ un tos panāca, kur tie lēģeri bija apmetuši pie jūras, visi Faraona zirgi, rati un viņa jātnieki un viņa spēks pie Pi Hahirotleijas pret Baāl Cefonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Kad nu Faraons bija tuvu pie tiem, tad Israēla bērni pacēla savas acis, un redzi, ēģiptieši dzinās viņiem pakaļ; un Israēla bērni ļoti bijās un brēca uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Un tie sacīja uz Mozu: vai nebija kapenes Ēģiptes zemē, ka tu mūs esi aizvedis, lai mirstam tuksnesī? Kāpēc tu mums to esi darījis, ka tu mūs esi izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Vai tā nav tā valoda, ko mēs Ēģiptes zemē uz tevi runājām sacīdami: atstājies no mums, un lai kalpojam ēģiptiešiem; jo tas mums būtu labāki bijis, kalpot ēģiptiešiem, nekā mirt tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Tad Mozus sacīja uz tiem ļaudīm: nebīstaties, pastāviet un lūkojiet Tā Kunga pestīšanu, ko Viņš šodien jums darīs. Jo tos ēģiptiešus, ko jūs šodien redzat, jūs mūžam vairs neredzēsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Tas Kungs karos par jums, un jūs būsiet mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Tad Tas Kungs sacīja uz Mozu: ko tu brēc uz Mani? Saki Israēla bērniem, lai dodās ceļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Un tu pacel savu zizli un izstiep savu roku pār jūru un pāršķir to, ka Israēla bērni var iziet cauri caur jūras vidu pa sausumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Un redzi, Es apcietināšu ēģiptiešu sirdi, ka tie ies viņiem pakaļ, un Es pagodināšos pie Faraona un pie visa viņa spēka, pie viņa ratiem un pie viņa jātniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Un ēģiptiešiem būs atzīt, ka Es esmu Tas Kungs, kad Es pagodināšos pie Faraona, pie viņa ratiem un pie viņa jātniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Un tas Dieva eņģelis, kas Israēla lēģerim gāja papriekš, cēlās un apstājās aiz viņiem, un tas padebeša stabs cēlās arīdzan no viņu priekšas un apstājās aiz viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Un tas nāca starp ēģiptiešu lēģeri un Israēla lēģeri, un tas padebesis bija (ēģiptiešiem) tumšs un darīja (Israēla bērniem) nakti gaišu, tā ka cauru nakti tie nevarēja tikt pie šiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Kad nu Mozus savu roku izstiepa pār jūru, tad Tas Kungs tai jūrai lika notecēt caur stipru austriņu visu nakti, un darīja to jūru sausu, un tas ūdens pāršķīrās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Un Israēla bērni iegāja jūras vidū sausām kājām, un tas ūdens tiem bija par mūri pa labo un kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Un ēģiptieši tiem dzinās pakaļ un iegāja tiem pakaļ, visi Faraona zirgi, viņa rati un viņa jātnieki jūras vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Un notikās rīta krēslā, tad Tas Kungs skatījās tai uguns un padebeša stabā uz ēģiptiešu karaspēku un iztrūcināja ēģiptiešu karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Un nogrūda tos riteņus no viņu ratiem, ka tiem grūti nācās tikt projām; tad ēģiptieši sacīja: lai bēgam no Israēla, jo Tas Kungs karo priekš viņiem pret ēģiptiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Un Tas Kungs sacīja uz Mozu: izstiep savu roku pār jūru, ka tas ūdens sagāžas pār ēģiptiešiem, pār viņu ratiem un pār viņu jātniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Tad Mozus savu roku izstiepa pār jūru, un tā jūra atgriezās pašā rīta krēslā savā straumē, un ēģiptieši bēga viņai pretī, un Tas Kungs iegāza ēģiptiešus jūras vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Un tas ūdens griezās atpakaļ un apklāja ratus un jātniekus, visu Faraona spēku, kas viņiem jūrā bija gājis pakaļ, ka neviens no tiem neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Bet Israēla bērni gāja sausām kājām caur jūras vidu, un ūdens tiem bija par mūri pa labo un kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Tā Tas Kungs tanī dienā izglāba Israēli no ēģiptiešu rokas, un Israēls redzēja ēģiptiešus nomirušus jūras malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Israēls redzēja arīdzan to stipro roku, ko Tas Kungs pie ēģiptiešiem bija parādījis. Un tie ļaudis bijās To Kungu un ticēja Tam Kungam un Viņa kalpam Mozum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tad Mozus un Israēla bērni dziedāja Tam Kungam šo dziesmu un sacīja: es dziedāšu Tam Kungam, jo Viņš ir ļoti paaugstinājies: zirgus un viņu jātniekus Viņš iegāzis jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Tas Kungs ir mans spēks un mana dziesma, un Viņš man bijis par pestīšanu: Viņš ir mans stiprais Dievs, es Viņu pagodināšu; Viņš ir mana tēva Dievs, es Viņu paaugstināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Tas Kungs ir karavīrs, Kungs ir Viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraona ratus un viņa spēku Viņš iemetis jūrā, un viņa izlasītie virsnieki apslīkuši niedru jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Dziļumi tos apklājuši, tie dibenā nogrimuši kā akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Ak Kungs! Tava labā roka ir pagodināta caur spēku, Tava labā roka, ak Kungs, ienaidniekus salauzījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Un Savā lielā augstumā Tu esi nogāzis Savus pretiniekus, Tu esi izlaidis Savu bardzību, kas tos aprijusi kā rugājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Un caur Tavu nāšu pūšanu sacēlās ūdeņi, strauti sastājās kā kopā, ūdeņi sastinga jūras vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Ienaidnieks sacīja: es dzīšos pakaļ, es panākšu, es dalīšu laupījumu, mana dvēsele pie tiem atriebsies. Es izvilkšu savu zobenu, un mana roka tos izdeldēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Tu Savu dvašu esi pūtis, jūra tos apklājusi, tie nogrimuši kā svins varenos ūdeņos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Ak Kungs! Kas ir tāds kā Tu? Kas ir tāds kā Tu starp tiem dieviem, pagodināts svētībā, cienījams ar teikšanām, brīnumu darītājs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Tu esi izstiepis Savu labo roku, zeme tos aprijusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Tu caur Savu žēlastību esi vadījis šos ļaudis, ko Tu atpestījis, Tu tos esi vadījis caur Savu spēku uz Tavas svētības mājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Tautas to dzird un trīc, bailība tos aizņēmusi, kas Fīlistejā mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tad Edoma virsnieki iztrūcinājās, trīcēšana aizņem Moaba varenos, sirds izkūst visiem, kas Kanaānā dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Iztrūcināšana un bailība krīt uz tiem, caur Tava elkoņa lielumu tie paliek klusu kā akmens, tiekams Tavi ļaudis pārstaigās cauri, ak Kungs, tiekams tie ļaudis pārstaigās, ko Tu Sev esi mantojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu tos vedi un stādi Savas mantības kalnā, tai vietā, ko Tu, Kungs, esi darījis par Savu mājas vietu, tai svētā vietā, ko Tavas rokas, ak Kungs, ir cēlušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Tas Kungs ir ķēniņš mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Jo Faraona zirgi ar viņa ratiem un ar viņa jātniekiem ir nākuši jūrā, un Tas Kungs jūras ūdenim ir licis pār tiem atpakaļ griezties, bet Israēla bērni caur jūras vidu izgājuši sausām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Un Mirjame, tā praviete, Ārona māsa, ņēma bungas savā rokā, un visas sievas izgāja viņai pakaļ ar bungām un diešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Tad Mirjame tiem atbildēja: dziedāt Tam Kungam, jo Viņš ir ļoti paaugstinājies: zirgus un viņu jātniekus Viņš ir iegāzis jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Pēc tam Mozus Israēlim lika aiziet no niedru jūras, un tie izgāja līdz Šur tuksnesim un gāja trīs dienas tuksnesī un neatrada ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Tad tie nāca uz Māru, bet Māras ūdeni nevarēja dzert, jo tas bija rūgts, tāpēc viņas vārdu nosauc Māra (rūgtums).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Tad tie ļaudis kurnēja pret Mozu un sacīja: ko mēs dzersim?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Un viņš brēca uz To Kungu un Tas Kungs viņam rādīja koku, to viņš ielika tai ūdenī, tad tas ūdens tapa salds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Tur viņš tiem iecēla likumu un tiesu, un tur viņš tos pārbaudīja un sacīja: ja jūs tikuši(uzmanīgi) klausīsiet Tā Kunga, sava Dieva, balsi, un darīsiet, kas tiesa ir Viņa acīs, un liksiet vērā Viņa baušļus un sargāsiet visus Viņa likumus, tad Es uz jums nelikšu nekādu vājību, ko Es esmu licis uz Ēģipti; jo Es esmu Tas Kungs tavs ārsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Tad tie nāca uz Elim, un tur bija divpadsmit avoti un septiņdesmit palmas, un tie tur apmeta lēģeri pie ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Un no Elim atkal aizgājuši, visa Israēla bērnu draudze nāca uz Sina tuksnesi, kas ir starp Elim un Sinaī, otra mēneša piecpadsmitā dienā pēc viņu iziešanas no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Un visa Israēla bērnu draudze kurnēja pret Mozu un Āronu tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Un Israēla bērni uz tiem sacīja: kaut mēs caur Tā Kunga roku būtu nomiruši Ēģiptes zemē, kad sēdējām pie gaļas podiem, un mums maizes bija papilnam ko ēst; jo jūs mūs esat izveduši šai tuksnesī, visai šai draudzei likt badu mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Tad Tas Kungs sacīja uz Mozu: redzi, Es jums likšu maizei līt no debesīm un tiem ļaudīm būs iziet un ikdienas salasīt savu dienas mēru, lai Es tos pārbaudu, vai tie Manā bauslībā staigā vai ne?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Un notiks sestā dienā, kad sataisīs, ko sanesuši, tad būs otrutik, cik ikdienas sakrāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Tad Mozus un Ārons sacīja uz visiem Israēla bērniem: šovakar jums būs atzīt, ka Tas Kungs jūs ir izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Un rīt jūs redzēsiet Tā Kunga godību, tāpēc ka Viņš dzirdējis jūsu kurnēšanu pret To Kungu: jo kas mēs esam, ka jūs pret mums kurnat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Un Mozus sacīja: kad Tas Kungs jums šovakar dos gaļu ēst un rīt maizes papilnam, tad tas ir tāpēc, ka Tas Kungs ir dzirdējis jūsu kurnēšanu, ar ko jūs pret Viņu esat kurnējuši, - jo kas mēs esam? Jūsu kurnēšana nav pret mums, bet pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Un Mozus sacīja uz Āronu: saki visai Israēla bērnu draudzei: nāciet tuvu Tā Kunga priekšā; jo Viņš ir dzirdējis jūsu kurnēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Un kad Ārons tā runāja uz Israēla bērnu draudzi, tad tie griezās uz tuksnesi un redzi, Tā Kunga godība rādījās padebesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Es esmu dzirdējis Israēla bērnu kurnēšanu. Runā uz tiem un saki: ap vakara laiku jūs ēdīsiet gaļu un rītu jūs ar maizi tapsiet paēdināti un jums būs atzīt, ka Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Un vakarā paipalas uznāca un apklāja lēģeri, un no rīta rasa bija nokritusi ap lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Kad nu rasa bija nozudusi, redzi, tad bija pa tuksnesi tāds apaļš un plāns, plāns kā sarma pa zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Kad Israēla bērni to redzēja, tad tie sacīja cits uz citu: kas tas ir? Jo tie nezināja, kas tas bija. Tad Mozus uz tiem sacīja: šī ir tā maize, ko Tas Kungs jums devis ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Tas ir, ko Tas Kungs pavēlējis: salasiet no tās ikviens, cik tas var apēst, vienu gomeru priekš ikvienas galvas, pēc jūsu skaita; ikvienam būs ņemt priekš tiem, kas ir viņa dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Un Israēla bērni darīja tā un salasīja cits daudz, cits maz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Bet kad tie ar gomeru mēroja, tad nebija pāri tam, kas daudz bija lasījis, un netrūka nekā tam, kas maz bija lasījis; ikviens bija lasījis, cik tas varēja apēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Un Mozus uz tiem sacīja: lai neviens no tā neko neatlicina līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Bet tie Mozum neklausīja un kādi vīri atlicināja no tā līdz rītam; tad tur ieradās tārpi, un tas smirdēja. Tad Mozus par tiem apskaitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Tie nu to salasīja ik rītu, ikviens, cik tas varēja apēst; jo kad saule iekarsa, tad tas izkusa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Un sestā dienā tie salasīja otrutik maizes, divus gomerus priekš ikkatra, un visi draudzes virsnieki nāca un to pasacīja Mozum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Un viņš tiem sacīja: Tas ir, ko Tas Kungs ir runājis; rīt ir Tā Kunga dusēšana, Tā Kunga svēta dusēšanas diena; ko jūs gribat cept, to cepiet, un ko gribat vārīt, to vāriet, un visu, kas atliek, to glabājiet un taupat līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Un tie to glabāja līdz rītam, kā Mozus bija pavēlējis, un tas nesmirdēja, un tārpi tur nemetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Tad Mozus sacīja: ēdiet to šodien, jo šodien ir Tā Kunga dusēšanas diena, šodien jūs laukā nekā neatradīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sešas dienas jums to būs lasīt, bet tā septītā diena ir tā dusēšanas diena, tanī tas nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Taču tai septītā dienā kādi no tiem ļaudīm izgāja lasīt, un neatrada nekā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Tad Tas Kungs sacīja uz Mozu: cik ilgi jūs liedzaties turēt Manus baušļus un Manus likumus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Redziet, tādēļ ka Tas Kungs jums to dusēšanas dienu devis, tāpēc Viņš jums sestā dienā dod divēju dienu maizi; lai ikviens savā vietā paliek un lai septītā dienā neviens neiziet no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Tā tie ļaudis dusēja septītā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Un Israēla nams viņa vārdu sauca mannu, un tas bija tā kā koriandra sēkla balts, un viņa garša bija tā kā karašas ar medu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Un Mozus sacīja: Tas ir, ko Tas Kungs ir pavēlējis: piepildiet vienu gomeru ar to, saglabājiet saviem bērnu bērniem, ka tie var redzēt to maizi, ko Es jums esmu devis ēst tuksnesī, kad Es jūs izvedu no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Un Mozus sacīja uz Āronu: ņem vienu kausu un ieliec tajā vienu pilnu gomeru mannas, un noliec to priekš Tā Kunga vaiga, glabāt priekš bērnu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Itin kā Tas Kungs Mozum bija pavēlējis, tā Ārons to nolika glabāt klāt pie tās liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Un Israēla bērni ēda to mannu četrdesmit gadus, kamēr tie nāca apdzīvotā zemē; tie ēda to mannu, tiekams tie nāca līdz Kanaāna zemes robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Bet gomers ir desmitā tiesa no ēfas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Tad visa Israēla bērnu draudze aizgāja pa saviem gājumiem no Sina tuksneša uz Tā Kunga pavēli un apmeta lēģeri iekš Refidim, un tur nebija ūdens, tiem ļaudīm ko dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Tad tie ļaudis bārās ar Mozu un sacīja: dod mums ūdeni, ka dzeram. Tad Mozus uz tiem sacīja: ko jūs ar mani baraties? Kāpēc jūs To Kungu kārdinājat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Kad nu tiem ļaudīm tur pēc ūdens slāpa, tad viņi kurnēja pret Mozu un sacīja: kāpēc tu mūs esi izvedis no Ēģiptes, lai mirstam aiz slāpēm, mēs un mūsu bērni un mūsu lopi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Un Mozus brēca uz To Kungu un sacīja: ko lai es daru ar šiem ļaudīm? Daudz netrūkst, tad tie mani ar akmeņiem nomētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Tad Tas Kungs sacīja uz Mozu: ej tiem ļaudīm priekšā un ņem līdz Israēla vecajus un ņem savā rokā to zizli, ar ko tu to upi esi sitis un noej.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Redzi, Es tur stāvēšu tavā priekšā uz klints pie Horeba, un tev būs uz to klinti sist, tad ūdens no tā iztecēs, tiem ļaudīm ko dzert. Un Mozus tā darīja priekš Israēla vecaju acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Un tās vietas vārdu nosauca Masu un Meribu (kārdināšana un strīdus), Israēla bērnu strīdus dēļ, un tāpēc ka tie To Kungu bija kārdinājuši sacīdami: vai Tas Kungs ir mūsu vidū vai nav?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Un Amaleks nāca un kāvās ar Israēli iekš Refidim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Tad Mozus sacīja uz Jozua: izlasi mums vīrus un izej un kaujies pret Amaleku; rīt es stāvēšu pakalna galā, un Dieva zizlis būs manā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Tad Jozuas darīja kā Mozus tam bija sacījis, un kāvās pret Amaleku; un Mozus un Ārons un Hurs kāpa tai pakalna galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Un kamēr Mozus turēja savas rokas pacēlis, Israēls uzvarēja, un kad viņš savu roku nolaida, tad Amaleks uzvarēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Bet Mozus rokas palika smagas; tad tie ņēma akmeni un lika to viņam apakšā, ka viņš uz tā sēdēja, un Ārons un Hurs turēja viņa rokas, viens vienā, otrs otrā pusē; tā viņa rokas palika stingras, kamēr saule nogāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Un Jozuas Amaleku un viņa ļaudis izdeldēja caur zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Tad Tas Kungs sacīja uz Mozu: raksti to par piemiņu grāmatā, un pavēli to Jozuam ausīs; jo Es izdeldēšu Amaleka piemiņu apakš debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Un Mozus uztaisīja altāri un nosauca viņa vārdu: Tas Kungs mans karogs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Un sacīja: roka pacelta pret Tā Kunga goda krēslu! Tam Kungam būs karš pret Amaleku uz bērnu bērniem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Kad nu Jetrus, tas Midijanas priesteris, Mozus tēvocis, dzirdēja visu, ko Dievs bija darījis Mozum un Israēlim, Saviem ļaudīm, ka Tas Kungs Israēli bija izvedis no Ēģiptes zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Tad Jetrus, Mozus tēvocis, ņēma Ciporu, Mozus sievu, ko šis bija atpakaļ sūtījis, un viņa divus dēlus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Tam vienam vārds bija Geršons, jo viņš sacīja: es esmu svešinieks bijis svešā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Un tam otram vārds Eliēzers, jo (viņš sacīja) mana tēva Dievs man bijis par palīgu un mani ir izrāvis no Faraona zobena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Kad nu Jetrus, Mozus tēvocis, un viņa dēli un viņa sieva nāca pie Mozus tuksnesī, kur viņš lēģeri bija apmetis, pie Tā Dieva kalna, tad viņš lika Mozum sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Es, Jetrus, tavs tēvocis, nāku pie tevis un tava sieva un viņas divi dēli līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Tad Mozus izgāja ārā savam tēvocim pretī un klanījās un viņu skūpstīja, un tie apsveicinājās viens otru un gāja teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Un Mozus stāstīja savam tēvocim visu, ko Tas Kungs Israēla dēļ bija darījis Faraonam un ēģiptiešiem, visu grūtumu, kas tiem ceļā bija noticis, un kā Tas Kungs tos bija izglābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Un Jetrus priecājās par visu to labumu, ko Tas Kungs Israēlim bija darījis, ka viņš tos izglābis no ēģiptiešu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Un Jetrus sacīja: slavēts lai ir Tas Kungs, kas jūs izglābis no ēģiptiešu rokas un no Faraona rokas, kas tos ļaudis izpestījis no ēģiptiešu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nu es atzīstu, ka Tas Kungs lielāks nekā visi dievi, jo tāds Viņš parādījies, kad ēģiptieši pret viņiem bija lieli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Tad Jetrus, Mozus tēvocis, ņēma dedzināmos upurus un kaujamus upurus priekš Dieva, un Ārons un visi Israēla vecaji nāca ēst maizi ar Mozus tēvoci Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Un otrā dienā Mozus apsēdās, tos ļaudis tiesāt, un tie ļaudis stāvēja Mozus priekšā no rīta līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Kad nu Mozus tēvocis visu redzēja, ko viņš tiem ļaudīm darīja, tad tas sacīja: kas tas ir, ko tu ar tiem ļaudīm dari? Kāpēc tu viens pats sēdi, un visi ļaudis stāv tavā priekšā no rīta līdz vakaram?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Tad Mozus sacīja uz savu tēvoci: tāpēc ka tie ļaudis pie manis nāk Dievu vaicāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Kad tiem ir kāda lieta, tad tie nāk pie manis, un es tiesāju starp vienu un otru un daru tiem zināmus Dieva likumus un viņa bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Tad Mozus tēvocis uz viņu sacīja: tā nav labi, kā tu dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Tu gurtin pagursi, gan tu, gan šie ļaudis, kas pie tevis; jo tas tev ir par grūtu, tu viens pats to nespēji izdarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Nu klausi manu balsi, - es tev došu padomu, tad Dievs būs ar tevi. Stāvi tu par tiem ļaudīm Dieva priekšā un nes tās lietas Dieva priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Un māci tiem likumus un baušļus, un dari tiem zināmu to ceļu, kur tiem jāiet, un to darbu, kas tiem jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Bet lūko starp visiem tiem ļaudīm pēc krietniem un dievbijīgiem vīriem, pēc taisniem vīriem, kas negausību ienīst, un iecel no šiem pār viņiem virsniekus pār tūkstošiem, virsniekus pār simtiem, virsniekus pār piecdesmitiem un virsniekus pār desmitiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Un lai tie tos ļaudis tiesā jebkurā laikā; bet tā, ka tie tev nes priekšā visas lielās lietas un visas mazās lietas paši tiesā; atvieglini tā savu nastu, un lai tie tev palīdz nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Ja tu tā darīsi, un Dievs tev to pavēlēs, tad tu varēsi pastāvēt, un arī visi šie ļaudis nāks savā vietā ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Un Mozus klausīja sava tēvoča balsij un darīja visu, ko tas bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Un Mozus izraudzīja krietnus vīrus no visa Israēla un tos iecēla par virsniekiem pār tiem ļaudīm, virsniekus pār tūkstošiem, virsniekus pār simtiem, virsniekus pār piecdesmitiem un virsniekus pār desmitiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Ka tie tos ļaudis jebkurā laikā tiesātu un grūtās lietas nestu Mozus priekšā, bet visas mazās lietas paši tiesātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Tad Mozus atlaida savu tēvoci, un tas gāja atkal uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Trešā mēnesī pēc Israēla bērnu iziešanas no Ēģiptes zemes, tanī laikā tie nonāca Sinaī tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Jo tie izgāja no Refidim un nonāca Sinaī tuksnesī un apmeta lēģeri tuksnesī; tur Israēls apmeta lēģeri pret to kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Un Mozus uzkāpa pie Dieva, un Tas Kungs sauca uz viņu no tā kalna un sacīja: tā tev būs sacīt uz Jēkaba namu un pasludināt Israēla bērniem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Jūs esat redzējuši, ko Es ēģiptiešiem esmu darījis, ka Es jūs nesu uz ērgļu spārniem un jūs pie Sevis vedu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Un nu, ja jūs klausīsiet Manu balsi un turēsiet Manu derību, tad jūs no visām tautām būsiet Mans īpašums, jo Man pieder visa pasaule.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Un jūs Man būsiet priesteru ķēniņa valstība un svēta tauta. Šie ir tie vārdi, ko tev būs runāt uz Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Un Mozus nāca un sasauca ļaužu vecajus un lika viņiem priekšā visus šos vārdus, ko Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Tad visi ļaudis kopā atbildēja un sacīja: visu, ko Tas Kungs ir runājis, to mēs darīsim. Un Mozus nesa to ļaužu vārdus atkal pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Tad Tas Kungs sacīja uz Mozu: redzi, Es nākšu pie tevis biezā padebesī, ka tie ļaudis dzird, Mani ar tevi runājam, un ka tie arī tev tic mūžam. Un Mozus teica Tam Kungam to ļaužu vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Un Tas Kungs sacīja uz Mozu: ej pie tiem ļaudīm un svētī tos šodien un rītu, un lai tie mazgā savas drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Un lai tie ir gatavi uz trešo dienu; jo trešā dienā Tas Kungs nolaidīsies priekš visu ļaužu acīm uz Sinaī kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Un tev būs taisīt sētu ap tiem ļaudīm un sacīt: sargājaties, ka nekāpjat uz to kalnu un neaizskarat viņa galu; ikviens, kas to kalnu aizskars, tas mirdams mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nevienai rokai to nebūs aizskart, bet tam tik tiešām ar akmeņiem būs tapt nomētātam vai nošautam; vai tas ir lops, vai cilvēks, tam nebūs dzīvot. Kad taure atskanēs, tad tiem būs kāpt uz to kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Tad Mozus nonāca no tā kalna pie tiem ļaudīm. Un viņš svētīja tos ļaudis, un tie mazgāja savas drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Un viņš sacīja uz tiem ļaudīm: esiet gatavi uz trešo dienu, neaiztiekat sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Un notika trešā dienā, kad gaisma ausa, tad bija pērkoni un zibeņi un biezs padebesis virs tā kalna un varen stipras bazūnes skaņa, tā ka visi ļaudis iztrūcinājās, kas bija lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Un Mozus tos ļaudis izveda no lēģera Dievam pretī, un tie nostājās apakšā pie tā kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Un Sinaī kalns kūpeja, tāpēc ka Tas Kungs nonāca ar uguni, un viņa dūmi cēlās tā kā krāsns dūmi, un viss kalns trīcēja ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Un bazūnes skaņa palika jo stipra, un Mozus runāja, un Dievs tam atbildēja caur vienu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Kad nu Tas Kungs bija nonācis uz Sinaī kalnu, uz kalna galu, tad Tas Kungs sauca Mozu uz kalna galu, un Mozus kāpa augšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Un Tas Kungs sacīja uz Mozu: nokāp un piekodini tiem ļaudīm, lai tie cauri nelaužas redzēt To Kungu, ka daudzi no tiem nekrīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Un tiem priesteriem, kas nāk pie Tā Kunga, būs svētīties, ka Tas Kungs tos nesatriec.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Tad Mozus sacīja uz To Kungu: tie ļaudis nevar kāpt uz Sinaī kalnu, jo Tu mums esi piekodinājis sacīdams: dari sētu ap to kalnu un svētī to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Tad Tas Kungs uz to sacīja: ej, kāp zemē. Tad tev un Āronam līdz ar tevi būs kāpt augšām, bet tiem priesteriem un tiem ļaudīm nebūs cauri lauzties uzkāpt pie Tā Kunga, ka Viņš tos nesatriec.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Tad Mozus nokāpa pie tiem ļaudīm un tiem to sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Tad Dievs runāja visus šos vārdus un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Es esmu Tas Kungs, tavs Dievs, kas tevi izvedis no Ēģiptes zemes, no tā vergu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Tev nebūs citus Dievus turēt priekš Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Tev nebūs sev darīt nekādu tēlu nedz līdzību, ne no tā, kas augšā debesīs, ne no tā, kas apakšā virs zemes, nedz no tā, kas ūdenī apakš zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Tev nebūs priekš tiem zemē mesties nedz tiem kalpot; jo Es Tas Kungs, tavs Dievs, esmu stiprs un dusmīgs Dievs, kas piemeklē tēvu grēkus pie bērniem līdz trešam un ceturtam augumam pie tiem, kas Mani ienīst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Un dara žēlastību tūkstošiem, kas Mani mīļo un Manus baušļus tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Tev nebūs Tā Kunga, sava Dieva, vārdu nelietīgi velti valkāt, jo Tas Kungs to nepametīs nesodītu, kas Viņa vārdu nelietīgi velti valkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Piemini to svēto dienu, ka tu to svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sešas dienas tev būs strādāt un visu savu darbu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Bet tā septītā diena ir Tā Kunga, tava Dieva, dusēšanas diena; tad tev nebūs nekādu darbu darīt, ne tev pašam, ne tavam dēlam, ne tavai meitai, ne tavam kalpam, ne tavai kalponei, ne tavam lopam, ne tavam svešiniekam, kas tavos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Jo sešās dienās Tas Kungs ir darījis debesis un zemi, jūru un visu, kas tur iekšā, un septītā dienā dusējis, tādēļ Tas Kungs to dusēšanas dienu ir svētījis un to iesvētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Godā savu tēvu un savu māti, lai tu ilgi dzīvo tai zemē, ko Tas Kungs, tavs Dievs, tev dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Tev nebūs nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Tev nebūs laulību pārkāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Tev nebūs zagt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Tev nebūs nepatiesu liecību dot pret savu tuvāko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Tev nebūs iekārot sava tuvākā namu. Tev nebūs iekārot sava tuvākā sievu, nedz viņa kalpu, nedz viņa kalponi, nedz viņa vērsi, nedz viņa ēzeli, nedz kaut ko, kas tavam tuvākam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Un visi ļaudis redzēja tos pērkonus un zibeņus un to bazūnes skaņu un to kalnu kūpam. Kad tie ļaudis to redzēja, tad tie bēga un stāvēja no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Un sacīja uz Mozu: runā tu ar mums, un mēs klausīsimies, bet lai Dievs ar mums nerunā, ka nemirstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Tad Mozus sacīja uz tiem ļaudīm: nebīstaties, jo Dievs ir nācis jūs pārbaudīt, un lai Viņa bijāšana ir priekš jūsu acīm, ka jūs negrēkojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Un tie ļaudis stāvēja no tālienes, bet Mozus gāja tai tumšumā, kur Dievs bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Un Tas Kungs sacīja uz Mozu: tā tev būs sacīt Israēla bērniem: jūs esat redzējuši, ka Es ar jums esmu runājis no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Jums nebūs neko celt Man līdzās; jums nebūs sev taisīt sudraba nedz zelta dievus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Cel Man altāri no zemes un upurē uz tā savus dedzināmos upurus un savus pateicības upurus, savas avis un savus vēršus. Ikkurā vietā, kur Es likšu pieminēt Savu vārdu, tur Es pie tevis nākšu un tevi svētīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Bet ja tu Man gribi celt akmeņu altāri, tad tev to nebūs taisīt no cirstiem akmeņiem; ja tu ar dzelzi pie tā strādāsi, tad tu to apgānīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Tev arī nebūs kāpt pa trepēm uz Manu altāri, ka pie viņa tavs plikums netop atsegts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Šīs nu ir tās tiesas, ko tev viņiem būs likt priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Ja tu pirksi Ebreju kalpu, tad tam būs sešus gadus kalpot, bet septītā tam par velti būs iziet svabadam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ja tas viens pats ir nācis, tad tam būs vienam pašam iziet, ja viņš bijis laulāts vīrs, tad viņa sievai būs iziet līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Ja viņa kungs viņam sievu devis, un tā viņam dzemdējusi dēlus vai meitas, tad tai sievai un viņas bērniem būs palikt kungam, un viņam būs iziet vienam pašam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Bet ja tas kalps pats sacīs: es mīlēju savu kungu, savu sievu un savus bērnus, es negribu svabads iziet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Tad lai viņa kungs to ved Dieva priekšā, un tad lai to ved pie durvīm vai pie stenderes, un lai viņa kungs tam ausi izdur ar īlenu, un lai tas viņam kalpo mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Un kad kas savu meitu pārdevis par kalponi, tad tai nebūs iziet, kā tie kalpi iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Ja viņa savam kungam nepatīk, ka viņš to neņem par sievu, tad viņam būs ļaut, lai to izpērk; viņš viltīgi ar to darīdams to nevar pārdot svešai tautai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Bet ja viņš to savam dēlam dod par sievu, tad lai viņai ir meitas tiesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Ja viņš tam citu ved, tad lai viņai nekā neatrauj no viņas barības, no viņas apsega un piedzīvošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Un ja viņš šās trīs lietas nedarīs, tad viņai būs velti(brīvai) iziet bez naudas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kas cilvēku sit, ka tas mirst, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Bet kad viņš ar viltu uz to nav glūnējis, bet Dievs ļāvis caur viņa roku tā notikt, tad es tev nosacīšu kādu vietu, kurp tam būs bēgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Bet ja kas blēdīgi darījis pret savu tuvāko, viņu viltīgi nokaudams, tad arī no mana altāra tev to būs ņemt, ka tas tiek nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Ja kas savu tēvu vai savu māti sit, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Ja kas cilvēku zog un viņu pārdod, un tas pie viņa top atrasts, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Arī kas savu tēvu vai savu māti lād, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Un ja vīri baras, un viens otru sit ar akmeni vai ar dūri, ka tas nemirst, bet tam uz gultas jāguļ;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Ja tas atkal uzceļas un iet ārā ar savu spieķi, tad tam, kas viņu sita, būs būt nenoziedzīgam; viņam tikai būs maksāt, ko tas ir aizkavējis un būs to it labi likt dziedināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Un ja kas savu kalpu vai kalponi ar koku sit, ka tas apakš viņa rokas mirst, pie tā to it tiešām būs atriebt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Bet ja viņš vienu vai divas dienas paliek pie dzīvības, tad to nebūs atriebt, jo tas ir ar viņa naudu pirkts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Un kad vīri baras un sit grūtu sievu, ka viņas auglis noiet, bet tomēr viņai pašai nekāda vaina nenotiek, tad to ar naudu būs sodīt, cik tās sievas vīrs viņam noprasa un tam to būs dot pēc soģu sprieduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Bet ja tai kāda nelaime būs, tad tam būs dot dvēseli pret dvēseli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Aci pret aci, zobu pret zobu, roku pret roku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Kāju pret kāju, degunu pret degunu, vāti pret vāti, trumu(rētu) pret trumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Un ja kas savu kalpu vai savu kalponi acī sit un to samaitā, tam būs viņu svabadu atlaist tās acs labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Un ja viņš sava kalpa vai savas kalpones zobu izsit, tad tam viņu būs atlaist tā zoba labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Un ja kāds vērsis vai vīru vai sievu sabada, ka mirst, tad to vērsi akmeņiem būs nomētāt un viņa gaļu nebūs ēst, bet tā vērša kungam būs būt nenoziedzīgam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Bet ja tas vērsis jau papriekš bijis badīgs, un tas viņa kungam ir teikts, un viņš to nav sargājis, un tas nobada vai vīru vai sievu, tad tam vērsim akmeņiem būs tapt nomētātam un viņa kungam arīdzan būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Ja viņam top nospriesta izpirkšana, tad tam par savas dvēseles izglābšanu būs dot visu, kas viņam top nospriests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Ja tas (vērsis) dēlu vai meitu ir badījis, tad tam būs darīt pēc šīs tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Ja tas vērsis kalpu vai kalponi bada, tad lai viņa kungs dod trīsdesmit sudraba sēķeļus, un to vērsi akmeņiem lai nomētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Un ja kas aku attaisa, vai ja kas aku rok un neapsedz, un tur kāds vērsis vai ēzelis krīt iekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Tad lai tās akas kungs to maksā, lai atdod (tā lopa) kungam to naudu, bet to maitu lai patur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Un ja kaut kāda vērsis bada sava tuvākā vērsi, ka tas mirst, tad to dzīvo vērsi būs pārdot un to naudu dalīt, un to maitu būs arī dalīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Bet ja tas bijis zināms, ka tas vērsis papriekš bijis badīgs, un viņa kungs to nav sargājis, tad lai vērsi pret vērsi atdod, bet to maitu lai patur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Ja kas vērsi vai avi zog un to nokauj vai pārdod, tam būs atdot piecus vēršus par vienu vērsi un četras avis par vienu avi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Ja zaglis kur top atrasts ielauzies, un top sists, ka mirst, tad viņa asinis nebūs atriebt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Ja saule pār to zagli ir uzlēkusi, tad viņa asinis būs atriebt. Zaglis lai atdod. Ja tam nav, tad tam būs tapt pārdotam savas zādzības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Ja zagtais lops viņa rokā top atrasts dzīvs, lai tas ir vērsis vai ēzelis vai avs, tad tam to būs atdot divkārtīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Ja kas kādu tīrumu vai vīna dārzu nogana un tur palaiž savu lopu, ka ēd cita tīrumā, tam par to būs atdot to labāko no sava tīruma un to labāko no sava vīna dārza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Kad uguns izceļas un aizņem ērkšķus, ka labības guba vai druva vai tīrums sadeg, tad tam, kas to uguni iededzinājis, būs pilnīgi atdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Ja kas savam tuvākam dod glabāt naudu vai lietas, un tās top izzagtas no tā vīra nama, - ja tas zaglis top atrasts, tam divkārtīgi to būs atdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Ja tas zaglis netop atrasts, tad to nama kungu būs vest Dieva priekšā, vai tas pats nav licis savu roku pie sava tuvākā mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Ikviena sūdzības lieta par vērsi, par ēzeli, par avi, par drēbēm, par ikvienu pazudušu lietu, ko kurš saka savu esam, lai nāk Dieva priekšā; kuru nu Dievs notiesā, tam divkārtīgi būs atdot savam tuvākam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Ja kas savam tuvākam dod glabāt ēzeli vai vērsi vai avi vai citu kādu lopu, un tas nosprāgst vai top ievainots vai nodzīts, ka neviens to neredz,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Tad pie Tā Kunga jānozvēras abu starpā, vai tas savu roku pats nav licis pie sava tuvākā mantas, un (tā lopa) kungam būs to pieņemt un tam (glabātajam) to nebūs atmaksāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Bet ja tas (lops) tam (glabātajam) zagšus top nozagts, tad lai tā (lopa) kungam to atmaksā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Ja ir saplosīts, tad būs dot liecību par to, un tad to saplosīto nebūs maksāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Un ja kas no sava tuvākā (lopu) aizņēmās un šis top ievainots vai nosprāgst viņa kungam klātu neesot, tad to būs atmaksāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Ja viņa kungs bijis klātu, tad nebūs atmaksāt; ja tas (lops) par naudu ņemts, tad tas caur to maksu ir aizmaksāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Ja kas meitu pieviļ, kas vēl nav saderēta, un pie tās guļ, tad lai viņai to kroņa naudu dod un lai viņu ņem par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Bet ja viņas tēvs liedzās viņam to dot, tad lai to naudu dod, cik tai meitai kroņa naudas pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Burvi tev nebūs pamest dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Visiem, kas ar kādu lopu jaucās, būs tapt nokautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kas upurē svešiem dieviem, un ne Tam Kungam vien, tam būs būt nolādētam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Tev arī nevienu svešinieku nebūs ne dragāt, ne spaidīt, jo jūs esat bijuši svešinieki Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Tev nevienu atraitni un nevienu bāriņu nebūs apbēdināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Ja tu kaut kā to apbēdināsi, un tā brēkdama uz Mani brēks, tad Es klausīt paklausīšu viņas brēkšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Un Mana bardzība iedegsies, un Es jūs nokaušu ar zobenu, un jūsu sievām būs tapt par atraitnēm un jūsu bērniem par bāriņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Ja tu Maniem ļaudīm, kas ir pie tevis par nabagiem, naudu aizdod, tad neesi pret tiem, kā kāds pagaidu plēsējs; tev par to nebūs augļus dzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Ja tu sava tuvākā drēbes ķīlā ņem, tad tev tās viņam būs atdot, pirms saule noiet;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Jo tās ir viņa vienīgais apsegs, tās ir tās drēbes pār viņa miesām, iekš kā viņš būtu gulējis; bet kad tas uz Mani brēks, tad Es to klausīšu, jo Es esmu žēlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Dievu tev nebūs zaimot, un savu ļaužu virsnieku tev nebūs lādēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Savus pirmajus augļus no labības un vīna tev nebūs aizturēt, to pirmdzimušo no saviem dēliem tev Man būs dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Tāpat tev būs darīt ar savu vērsi un ar savām avīm; septiņas dienas tiem būs būt pie savas mātes un astotā dienā tev tos Man būs atdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Jums būs svētiem ļaudīm būt Manā priekšā; tāpēc jums nebūs ēst tādas miesas gaļu, kas laukā ir saplosīta; jums to būs mest suņiem priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Tev nebūs nepatiesu slavu izpaust; un nebiedrojies ar bezdievīgo, palikdams par viltīgu liecinieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Tev nebūs turēties pie lielā pulka, ļaunu darīt, un ķildās neliecini lielajam pulkam pa prātam, tiesu pārgrozot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Arī nabagu tev nebūs aizstāvēt, kad tam netaisnas ķildas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Kad tu sava ienaidnieka vērsi vai ēzeli sastopi maldamies, tad tev tūdaļ viņam to būs vest atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Ja tu sava naidnieka ēzeli redzi apakš nastas guļam, tad nepamet viņu tādu, bet palīdzi atraisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Tev nebūs pārgrozīt sava nabaga tiesu, kad tam jātiesājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Atraujies no nepatiesas liecības; nenoziedzīgo un taisno tev nebūs nokaut, jo es netaisnošu bezdievīgo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Tev nebūs dāvanas ņemt, jo dāvanas apstulbo acis un pārgroza taisnu ļaužu lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Tev arī nebūs svešinieku nospaidīt, jo jūs zināt, kā svešiniekam ap sirdi, tāpēc ka jūs arī esat bijuši svešinieki Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sešus gadus tev būs apsēt savu zemi un sakrāt viņas augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Bet septītā tev to būs pamest un atstāt, ka tavu ļaužu nabagi var ēst, un zvēri atlikumu var ēst; tāpat tev būs darīt ar savu vīna dārzu un ar savu eļļas koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sešas dienas tev būs darīt savu darbu, bet septītā dienā tev būs dusēt, lai tavs vērsis un tavs ēzelis dus un tavas kalpones dēls un tavs svešinieks atspirgst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Visu, ko Es jums esmu sacījis, jums būs turēt, un citu dievu vārdu nepieminēt; to no jūsu mutes nebūs dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trīs reiz\' gadskārtā tev Man būs svētkus turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Neraudzētās maizes svētkus tev būs turēt un septiņas dienas ēst neraudzētu maizi, tā kā Es tev esmu pavēlējis, noliktā laikā, Abiba mēnesī, jo tanī tu esi izgājis no Ēģiptes zemes; bet nenāciet tukši Mana vaiga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Un pļaušanas svētkus, par sava darba pirmajiem augļiem, ko tu uz tīrumu esi sējis, un savākšanas svētkus ap gada galu, kad tu esi savācis sava darba augļus no tīruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trīs reiz\' gadskārtā visiem vīriešiem būs rādīties Tā Kunga vaiga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Tev nebūs Mana upura asinis upurēt kopā ar raudzētu maizi, un tie tauki no Maniem svētkiem lai nepaliek pa nakti līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Pirmajus no tavas zemes pirmiem augļiem tev būs nest Tā Kunga, sava Dieva, namā. Tev āzīti nebūs vārīt viņa mātes pienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Redzi, Es sūtu eņģeli tavā priekšā, tevi sargāt uz šī ceļa un tevi novest tai vietā, ko Es esmu sataisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Sargies priekš viņa un klausi viņa balsij un neapkaitini viņu, jo viņš jūsu pārkāpšanas nepiedos, jo Mans Vārds ir iekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Bet ja tu viņa balsij klausīdams klausīsi un darīsi visu, ko Es runāšu, tad Es būšu tavu ienaidnieku ienaidnieks un tavu pretinieku pretinieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Jo mans eņģelis ies tavā priekšā un tevi ievedīs pie Amoriešiem un Hetiešiem un Fereziešiem un Kanaāniešiem, Hiviešiem un Jebusiešiem, un Es viņus izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Tev nebūs mesties zemē priekš viņu elku dieviem, nedz viņiem kalpot, tev arī nebūs darīt pēc viņu darbiem, bet postīt un sadauzīt viņu uzceltos dievekļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Un jums būs kalpot Tam Kungam, savam Dievam, tad viņš svētīs tavu maizi un tavu ūdeni, un Es noņemšu visu vājību no tava vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nevienas(sievas) nebūs, kas nelaikā izmet dzimumu, nedz kādas neauglīgas tavā zemē; Es piepildīšu tava mūža dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Es sūtīšu Savas briesmas tavā priekšā, Es izbiedēšu visus tos ļaudis, pie kuriem tu nāksi, un darīšu, ka visiem taviem ienaidniekiem būs bēgt tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Un Es sūtīšu dundurus tavā priekšā, tie izdzīs tavā priekšā Hiviešus, Kanaāniešus un Hetiešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Es tos neizdzīšu vienā gadā no tavas priekšas, ka zeme netop postā, un zemes zvēri pār tevi nevairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, '30, Es pamazām tos izdzīšu tavā priekšā, tiekams tu pieaugsi un to zemi varēsi turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Un Es likšu tavas robežas no niedru jūras līdz Fīlistu jūrai, un no tuksneša līdz tai upei(Eifratas), jo Es tās zemes iedzīvotājus došu jūsu rokās, ka jūs tos izdzenat savā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Jums nebūs ne kādu derību derēt nedz ar viņiem, nedz ar viņu dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Tiem nebūs dzīvot tavā zemē, lai tie tevi neapgrēcina pret Mani, jo tas tev paliks par slazda valgu, ja tu kalposi viņu dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Un tad Viņš sacīja uz Mozu: uzkāp pie Tā Kunga, tu un Ārons, Nadabs un Abijus un tie septiņdesmit Israēla vecaji, un pielūdziet no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Un lai Mozus viens pats nāk pie Tā Kunga, bet viņi lai nenāk, un tie ļaudis lai neuzkāpj līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Un kad nu Mozus nāca un tiem ļaudīm teica visus Tā Kunga vārdus un visas tiesas, tad visi ļaudis atbildēja vienā balsī un sacīja: visus šos vārdus, ko Tas Kungs runājis, mēs darīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Un Mozus uzrakstīja visas Tā Kunga runas un cēlās agri no rīta un uztaisīja altāri lejā pie paša kalna un divpadsmit stabus pēc tām divpadsmit Israēla ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Un viņš sūtīja Israēla bērnu jaunekļus, ka tie upurētu dedzināmos upurus, un upurētu pateicības upurus Tam Kungam no vēršiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Un Mozus ņēma pusi no tām asinīm un lika to bļodās, un pusi no tām asinīm viņš slacīja pār altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Un viņš ņēma to derības grāmatu un to lasīja priekš ļaužu ausīm, un tie sacīja: visu, ko Tas Kungs ir runājis, to mēs darīsim un klausīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Tad Mozus ņēma tās asinis un slacīja pār tiem ļaudīm un sacīja: redzi, šīs ir tās derības asinis, ko Tas Kungs ar jums ir derējis uz visiem šiem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Tad Mozus un Ārons kāpa augšām, arī Nadabs un Abijus un septiņdesmit no Israēla vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Un tie redzēja Israēla Dievu un apakš Viņa kājām tā kā darījumu no safīra akmeņiem, skaidru kā pašas debesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Bet Viņš neizstiepa Savu roku pret Israēla bērnu priekšniekiem, un tie redzēja Dievu un ēda un dzēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Tad Tas Kungs sacīja uz Mozu. Nāc augšām pie Manis kalnā un esi tur, un Es tev došu akmens galdiņus un to bauslību un likumu, ko Es esmu rakstījis, viņus mācīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Tad Mozus pacēlās ar savu kalpu Jozua, un kāpa uz to Dieva kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Bet uz tiem vecajiem viņš sacīja: gaidiet mūs šeitan, kamēr mēs pie jums atpakaļ nāksim; un redzi, Ārons un Hurs ir pie jums - kam kāda lieta, lai nāk pie tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Kad nu Mozus bija uzkāpis kalnā, tad padebesis apsedza kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Un Tā Kunga godība mita uz Sinaī kalna, un padebesis viņu apsedza sešas dienas, un septītā dienā viņš sauca Mozu tai padebesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Un Tā Kunga godība parādījās tā kā rijoša uguns kalna galā priekš Israēla bērnu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Un Mozus iegāja padebeša vidū, kad bija uzkāpis kalnā, un palika kalnā četrdesmit dienas un četrdesmit naktis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Tad Tas Kungs runāja ar Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Runā ar Israēla bērniem, ka tiem priekš Manis būs ņemt cilājamu upuri no ikviena, kam sirds to labprāt darīs; no tāda jums būs ņemt Manu cilājamo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Šis nu ir tas cilājamais upuris, ko jums no viņiem būs ņemt: zelts un sudrabs un varš,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Un zilums, purpurs, karmezīns un šķetinātas smalkas dzijas un kazu spalvas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Sarkanas aunu ādas un roņu ādas un akācijas koki,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Eļļu lukturim, zāles svaidāmai eļļai un saldi smaržīgas zāles kvēpināšanai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Oniksa akmeņi un ieliekami akmeņi priekš efoda un krūšu glītuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Un tiem būs Man taisīt svētu vietu, ka Es mājoju viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Pēc visa tā, kā Es tev rādīšu šā dzīvokļa priekšzīmi un visu viņa rīku priekšzīmi, tā jums to būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Un tiem būs taisīt šķirstu no akācijas koka; pustrešas olekts lai ir viņa garums un pusotras olekts viņa platums un pusotras olekts viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Un to tev būs apvilkt ar tīru zeltu, no iekš un no āra puses, un visapkārt uz tā tev būs taisīt zelta kroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Un lej priekš tā četrus zelta gredzenus un liec tos viņa četros stūros, tā ka divi gredzeni ir vienā pusē un divi gredzeni otrā pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Un taisi divas nesamās kārtis no akācijas koka un apvelc tās ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Un bāz tās nesamās kārtis tais gredzenos, kas ir šķirsta sānos, ka šķirstu ar tām var nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Tām nesamām kārtīm būs stāvēt šķirsta gredzenos, tām nebūs tapt izvilktām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Pēc tam tev būs ielikt šķirstā to liecību, ko Es tev došu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Tev arī būs taisīt salīdzināšanas vāku no tīra zelta; pustrešas olekts lai ir viņa garums un pusotras viņa platums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Tev arī būs taisīt divus ķerubus no zelta, tev tos būs taisīt no tīra (zelta), salīdzināšanas vāka abējos galos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Un taisi vienu ķerubu vienā galā un otru ķerubu otrā galā, uz paša salīdzināšanas vāka jums tos ķerubus būs taisīt viņa abējos galos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Un tiem ķerubiem būs izstiept savus spārnus pa virsu, ka tie apklāj ar saviem spārniem salīdzināšanas vāku, un viņu vaigiem būs būt vienam pret otru. Ķerubu vaigiem būs lūkoties uz salīdzināšanas vāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Un salīdzināšanas vāku tev būs likt virsū uz to šķirstu, kad tu to liecību, ko Es tev došu, būsi ielicis šķirstā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Tur būs mūsu saiešanas vieta, tur no salīdzināšanas vāka virsas, no abu ķerubu vidus, (kam uz liecības šķirsta būs būt), tur Es ar tevi runāšu visu, ko Es tev pavēlēšu priekš Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Tev arī galdu būs taisīt no akācijas koka; divas olektis lai ir viņa garums un viena olekts viņa platums un pusotras olekts viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Un tev to būs apvilkt ar tīru zeltu; arī zelta kroni tev būs taisīt pie tā visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Tev arī būs taisīt līsti visapkārt, vienas plaukstas augstumā, un tev būs taisīt zelta kroni ap to līsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Tev arī pie tā būs taisīt četrus zelta gredzenus, un tos gredzenus likt tais četros stūros, kas būs pie viņa četrām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Tiem gredzeniem būs būt pie līstes klāt, ka var ielikt tās ceļamās kārtis, ka to galdu var nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Tās ceļamās kārtis tev būs taisīt no akācijas koka un tās apvilkt ar zeltu, un to galdu ar tām būs nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Tev būs priekš viņa arī taisīt bļodas un karotes, kannas un kausus, ar ko lai laista; - no tīra zelta tev tos būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Un uz to galdu tev allažiņ būs likt tās maizes, kas liekamas Mana vaiga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Tev arī būs taisīt lukturi no tīra zelta, no kalta zelta būs to lukturi taisīt; viņa kātam un zariem, viņa kausiem, viņa pogām un puķēm būs no tā izstiepties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Tā ka seši zari izstiepjas sānis no viņa, trīs zari no luktura vienas puses un trīs zari no luktura otras puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Vienā zarā lai ir trīs kausiņi, tā kā mandeļu ziedi, ar pogu un puķi, un otrā zarā lai ir atkal trīs kausiņi, tā kā mandeļu ziedi, ar pogu un puķi; tādiem būs būt tiem sešiem zariem, kas no tā luktura izstiepjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Bet pie paša luktura būs būt četriem kausiem ar savām pogām un ar savām puķēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Un tur būs iznākt vienai pogai apakš diviem zariem, un (atkal) būs iznākt vienai pogai apakš diviem zariem, un vēl vienai pogai būs iznākt apakš diviem zariem; tā tam būs būt ar tiem sešiem zariem, kas no tā luktura izstiepjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Viņu pogām un zariem būs no tā (luktura) izstiepties. Tam visam būs kaltam būt no tīra zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Tev arī būs taisīt septiņus eļļas lukturīšus priekš viņa un likt virsū, ka spīd viņam iepretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Viņa lukt(dakts) šķērēm un dzēšamiem kausiem būs būt no tīra zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'No viena talenta tīra zelta to būs taisīt ar visiem šiem rīkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Tad lūko, ka tu to taisi pēc viņu priekšzīmes, kas tev kalnā ir rādīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Un to dzīvokli tev būs taisīt no desmit deķiem, no šķetinātām dzijām un ziluma un purpura un karmezīna(spilgti sarkana), ar ķerubiem; no izrotāta audekla tev to būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Viena deķa garums lai ir divdesmit un astoņas olektis, un viena deķa platums lai ir četras olektis, visiem deķiem būs būt vienā mērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pieciem deķiem būs būt sašūtiem vienam pie otra, atkal pieciem deķiem būs būt sašūtiem vienam pie otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Un tev būs pazilas cilpas taisīt pie tā viena deķa vīles, tai malā, kur tas top pielaists; tāpat tev būs arī darīt pie tā otra deķa vīles, kur atkal šis top pielaists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Piecdesmit cilpas tev būs taisīt pie tā viena deķa, un piecdesmit cilpas tev būs taisīt pie tā otra deķa pielaižamās malas. Šās cilpas lai stāv viena otrai iepretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Tev arī būs taisīt piecdesmit zelta kāsīšus, un tos deķus vienu pie otra salaist ar šiem kāsīšiem, ka tas top par vienu dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Tev arī deķus no kazu spalvas būs taisīt par telti pār to dzīvokli; vienpadsmit deķus tev būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Deķa garums lai ir trīsdesmit olektis, un deķa platums četras olektis; šiem vienpadsmit deķiem būs būt vienā mērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Un piecus no šiem deķiem tev būs sevišķi sašūt vienu pie otra, un sešus no tiem deķiem (atkal) sevišķi, un to sesto deķi tev būs divkārtīgu taisīt pie telts priekšas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Un tev piecdesmit cilpas būs taisīt pie viena deķa vīles, tai malā, kur tā top pielaista, un piecdesmit cilpas atkal pie tā otra deķa vīles, kur šī top pielaista.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Tev arī būs taisīt piecdesmit vara kāsīšus un tos kāsīšus ielikt tais cilpās, un tev to telti būs salaist, ka tā saiet kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Un kas vēl atliek no tiem telts deķiem, tas atliekamais pusdeķis lai karājās pāri telts pakaļgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Un tā viena olekts no šīs puses un tā viena olekts no viņas puses, kas pāri ir pie telts deķa garuma, lai karājās pāri pār tā dzīvokļa sāniem šai un viņā pusē, to apklāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Tev tai teltij arī būs taisīt apsegu no sarkanām aunu ādām, un tur virsū apsegu no roņu ādām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Tev arī dēļus pie tā dzīvokļa būs taisīt no akācijas koka, stāvošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Vienam dēlim būs būt desmit olektis garam, un pusotras olekts platam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Divas tapas lai ir ikkatrā dēlī, salaistas viena ar otru; tā tev ar visiem telts dēļiem būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Un tos dēļus priekš tā dzīvokļa tev tā būs taisīt: divdesmit dēļi lai stāv pret tārpiņa vēju dienvidu pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Tev arī četrdesmit sudraba kājas būs taisīt apakš tiem divdesmit dēļiem, divas kājas apakš ikviena dēļa pie viņa divām tapām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Tāpat arīdzan divdesmit dēļiem būs būt pie otras telts puses pret ziemeļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Ar savām četrdesmit sudraba kājām, pa divām kājām apakš ikviena dēļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Bet uz to telts pusi pret vakariem tev būs taisīt sešus dēļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Tev arī divus dēļus būs likt stūros, telts galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Un tiem pa diviem apakšgalā būs būt salaistiem, un virsgalā arīdzan pa diviem ar vienu riņķi. Tā to būs darīt ar tiem diviem dēļiem, kas būs stūros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Tā tiem astoņiem dēļiem būs būt ar savām sudraba kājām; tās ir sešpadsmit kājas; divas kājas apakš ikviena dēļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Tev arī būs cauršaujamas (kārtis) taisīt no akācijas koka, piecas pie tiem dēļiem vienā telts pusē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Un piecas pie tiem dēļiem otrā telts pusē, ir piecas cauršaujamas kārtis pie telts gala dēļiem pret vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Tai vidējai cauršaujamai kārtij būs būt tai dēļu vidū un cauri iet no viena gala līdz otram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Un tos dēļus tev būs ar zeltu apvilkt, un viņu riņķus (priekš tām cauršaujamām kārtīm) no zelta taisīt; tās kārtis tev arīdzan ar zeltu būs apvilkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Un tev to telti būs uzcelt itin tā, kā tev kalnā ir rādīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Pēc tam tev būs taisīt priekškaramo no ziluma un purpura un karmezīna un šķetinātām dzijām; to būs taisīt no izrotāta audekla, kur ķerubi ieausti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Un tev to būs pakārt pie četriem ar zeltu apvilktiem stabiem no akācijas koka; viņu kāsīšiem būs būt no zelta, (un tiem būs stāvēt) uz četrām sudraba kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Un tev būs pakārt to priekškaramo pie tām sprādzēm, un liecības šķirstu turp nonest aiz tā priekškaramā, un šim priekškaramam jums būs būt par starpību starp to svēto un to vissvētāko vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Un salīdzināšanas vāku tev būs likt uz liecības šķirstu tai vissvētākā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Un to galdu tev būs likt šaipus tā priekškaramā, un to lukturi tam galdam pretī pret telts dienasvidus pusi, bet to galdu tev būs likt pret ziemeļa pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Tev arī apsegu būs taisīt telts durvīs no ziluma un purpura un karmezīna un šķetinātām dārgām dzijām raibi austu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Un priekš šā apsega tev būs taisīt piecus stabus no akācijas koka un tos apvilkt ar zeltu un viņu kāsīšiem būs būt no zelta, un tev tiem būs liet piecas vara kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Tev arī būs taisīt altāri no akācijas koka; piecas olektis lai ir garums un piecas olektis platums; tam altārim būs būt četrkantīgam, un trīs olektis lai ir viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Un tev būs viņam ragus taisīt uz viņa četriem stūriem; tiem ragiem būs no viņa iziet, un tev viņu būs apvilkt ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tev arī viņam būs taisīt pelnu podus un lāpstas un slakāmus traukus un dakšas un ogļu traukus; visus viņa rīkus tev būs taisīt no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Tev tam arī būs taisīt vara traliņus kā tīklu, un tev pie tiem būs taisīt četrus vara rinķus viņa četros stūros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Un tev tos būs likt apakš altāra beņķa, tā ka tie traliņi sniedz līdz altāra vidum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Tev arī būs taisīt nesamas kārtis tam altārim, nesamas kārtis no akācijas koka, un tās apvilkt ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Un tās nesamās kārtis būs ielikt riņķos, tā ka tās nesamās kārtis ir abējos altāra sānos, kad to nes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tev viņu būs taisīt no dēļiem ar tukšu vidu; itin kā tas tev kalnā rādīts, tā tiem to būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tev arī būs taisīt telts pagalmu: uz dienvidu pusi, pagalma gardīnes(aizkars) no šķetinātām dzijām simts olektis garumā tai vienā pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Un viņa divdesmit stabus un šo divdesmit kājas no vara. Šo stabu kāsīšiem un viņu stīpām būs būt no sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Tāpat pret ziemeļa pusi gardīnes, simts olektis garumā, un divdesmit stabus un viņu divdesmit kājas no vara. To stabu kāsīšiem un viņu stīpām būs būt no sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Un pagalma platumā pret vakariem būs būt gardīnēm no piecdesmit olektīm, un turklāt būs būt desmit stabiem ar viņu desmit kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Tāpat pagalma garums pret rītiem lai ir piecdesmit olektis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Tā ka tām gardīnēm vienā pusē ir piecpadsmit olektis ar saviem trim stabiem un ar viņu trim kājām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Un piecpadsmit olektis tām gardīnēm otrā pusē ar saviem trim stabiem un ar viņu trim kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Bet pagalma vārtos būs būt segām no divdesmit olektīm, šim būs būt raibi austam no ziluma un purpura un karmezīna(spilgti sarkana) un šķetinātām dzijām, ar saviem četriem un ar šo četrām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Visiem pagalma stabiem visapkārt būs aptaisītiem būt ar sudraba stīpām, un viņu kāsīšiem būs būt no sudraba, bet viņu kājām no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Pagalma garums lai ir simts olektis un platums viscaur piecdesmit olektis un augstums piecas olektis, no šķetinātām dzijām; bet viņu kājām būs būt no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Visiem dzīvokļa rīkiem pie visas viņa kalpošanas un visām viņu naglām un visām pagalma naglām būs būt no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Tad nu tev būs pavēlēt Israēla bērniem, ka tie pie tevis atnes tīru eļļu no eļļas kokiem sagrūstu priekš tā luktura, ka allažiņ tie eļļas lukturīši top uzlikti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Saiešanas teltī, šaipus tā priekškaramā, kas ir priekš tās liecības, Āronam un viņa dēliem to būs sataisīt no vakara līdz rītam Tā Kunga priekšā; tam būs būt par likumu pie viņu pēcnākamiem starp Israēla bērniem mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Un tev būs atvest pie sevis savu brāli Āronu un viņa dēlus līdz ar viņu no Israēla bērniem, lai viņš ir Mans priesteris, (proti) Ārons, Nadabs un Abijus, Eleazars un Ītamars, Ārona dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Un tev būs taisīt savam brālim Āronam svētas drēbes par godu un rotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Tev būs arī runāt ar visiem, kam ir gudra sirds, ko Es ar gudrības garu esmu piepildījis, ka tiem Ārona drēbes būs taisīt priekš viņa iesvētīšanas, lai viņš ir Mans priesteris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Šīs nu ir tās drēbes, kas tiem jātaisa: krūšu glītums un efods un uzvalks un tie šaurie izrotātie svārki, cepure un josta; lai tad tie Āronam, tavam brālim, un viņa dēliem taisa svētas drēbes, ka tie ir Mani priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Tiem arī būs ņemt zeltu, zilumu un purpuru un karmezīnu un smalkas dzijas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Un tiem būs taisīt to efodu no zelta un ziluma un purpura un karmezīna un šķetinātām dārgām dzijām, izrotātu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Divi sasprādzēti plecu gabali lai viņam ir abējos viņa galos, kur tiem būs būt sasietiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Un efoda josta, kas pār to ir, lai ir tāpat taisīta no zelta, ziluma un purpura un karmezīna un šķetinātām dārgām dzijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Un tev būs ņemt divus oniksa akmeņus un uz tiem iegriezt Israēla bērnu vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Sešus no viņu vārdiem vienā akmenī un tos otrus sešus vārdus otrā akmenī, pēc viņu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Tas lai ir akmeņu griezēja darbs; kā gredzeni top griezti, tā tev šiem diviem dārgiem akmeņiem būs uzgriezt Israēla bērnu vārdus; zelta kalumos tev tos būs ielikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Un tev būs likt tos divus dārgos akmeņus uz to efodu pašos plecos par piemiņas akmeņiem priekš Israēla bērniem, un Āronam viņu vārdus būs nest uz saviem abiem pleciem par piemiņu Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Tev arī būs taisīt zelta kalumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Un divas ķēdītes tev būs taisīt no šķīsta zelta; vienā garumā tev tās būs taisīt uz vijamu vīzi un tās savītās ķēdītes iekabināt pie tiem kalumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Arī krūšu glītumu, tiesu nest, tev būs taisīt, izrotātu darbu; tā kā tā efoda darbu tev to būs taisīt no zelta, ziluma un purpura un karmezīna un no šķetinātām dzijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Tam būs būt četrkantīgam un divkārtīgam; viens sprīdis lai ir viņa garums un viens sprīdis viņa platums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Un tev to būs aplikt ar četrām dārgu akmeņu rindām. Vienā rindā lai ir sardis, topāzs un smaragds; šī ir tā pirmā rinda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Un otrā rindā lai ir rubīns, safīrs un dimants.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Un trešā rindā lai ir hiacints, akats un ametists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Un ceturtā rindā lai ir krizolits, berils un jaspis. Tiem būs būt ieliktiem zelta kalumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Un šiem akmeņiem būs būt divpadsmit pēc Israēla bērnu vārdiem; tiem būs būt grieztiem tā kā gredzeniem, ikvienam ar savu vārdu būs būt priekš tām divpadsmit ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Tev arī ķēdītes būs taisīt pie krūšu glītuma, vienā garumā, no tīra zelta uz vijamu vīzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Tev pie krūšu glītuma arī būs taisīt divus zelta gredzenus, un tos divus gredzenus tev būs likt pie krūšu glītuma abiem augšgaliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Tad tās divas savītās zelta ķēdītes tev būs ielikt tais divējos gredzenos pie krūšu glītuma galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Bet to abēju savīto ķēdīšu abus galus tev būs likt pie tiem abiem kalumiem, un tev to būs likt uz efodu pašos plecos priekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Un tev būs taisīt divus zelta gredzenus un tos likt pie krūšu glītuma abiem (apakš) galiem, pie viņa vīles, iekšpusē, efodam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Un tev būs taisīt divus zelta gredzenus un tos likt efodam uz abiem pleciem, apakšā priekšpusē priekšgalu, kur tas top sasprādzēts pār efoda jostu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Un krūšu glītumu ar viņa gredzeniem būs piesiet ar pazilu auklu pie efoda gredzeniem, ka tas ir pār efoda jostu virsū, un ka netop vaļā no efoda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Tā Āronam uz savas sirds būs nest Israēla bērnu vārdus tai krūšu glītumā, ar ko tiesa tiek spriesta, kad viņam jāiet tai svētā vietā, par piemiņu Tā Kunga vaiga priekšā allažiņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Tai tiesas krūšu glītumā tev arī būs ielikt tos urim un tumim (gaismu un taisnību), ka tie ir uz Ārona sirds, kad viņam jāiet Tā Kunga priekšā; tā Āronam Israēla bērnu tiesu būs allažiņ nest uz savas sirds Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Tev arī efoda uzvalku būs taisīt visu no ziluma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Un augšā pašā viņa vidū būs būt caurumam, šim caurumam lai ir visapkārt vīle, vēvera(audēja) darbs, tā kā krūšu bruņu caurumam tam būs būt, lai neplīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Un pie viņa apakšējām vīlēm tev būs taisīt granātābolus no ziluma un purpura un karmezīna, pie viņa vīlēm visapkārt, un zelta zvārgulīšus viņu starpās visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Tā ka stāv zelta zvārgulītis un tad granātābols, un atkal zelta zvārgulītis un granātābols pie uzvalka apakšējām vīlēm visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Un Āronam to būs apvilkt, kad viņš kalpo, ka viņa skaņu dzird, kad viņš ieiet tai svētā vietā priekš Tā Kunga vaiga, un kad viņš iziet, ka tas nemirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Tev arī būs taisīt platīti no šķīsta zelta un tur iegriezt, kā gredzenos iegriež: svēts Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Un tev to būs piesiet ar pazilu auklu, un tai būs būt pie cepures, cepures priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Un tai būs būt uz Ārona pieres, tā ka Ārons nes tos noziegumus, kas ir pie tā svētuma, ko Israēla bērni svētī visās savās svētās dāvanās; un tai būs allaž būt priekš viņa pieres, lai tās Tam Kungam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Tev arī būs izaust šaurus svārkus no šķetinātām dzijām; tev arī būs taisīt cepuri no šķetinātām dzijām, un jostu būs taisīt, izrakstītu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Un arī Ārona dēliem tev būs taisīt svārkus, un viņiem taisīt jostas, un viņiem taisīt paaugstas cepures par godu un rotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Un Āronu, savu brāli, un viņa dēlus līdz ar viņu tev tā būs apģērbt, un tev tos būs svaidīt un tev tos būs amatā iecelt un iesvētīt, ka tie ir Mani priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Darini tiem arī linu ūzas(bikses), apklāt viņu miesas plikumu; - no gurniem līdz ciskām tām būs būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Un Āronam un viņa dēliem tās būs apvilkt, kad tie ieiet saiešanas teltī, vai kad tiem jāiet pie altāra un jākalpo tai svētā vietā, ka tie nenoziedzās un nemirst; tas lai ir par likumu viņam un viņa dzimumam pēc viņa mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Tā nu dari viņiem, tos Man iesvētīdams par priesteriem: ņem vienu jaunu vērsi un divus aunus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Un neraudzētu maizi un neraudzētas karašas ar eļļu sajauktas un neraudzētus raušus ar eļļu svaidītus; no kviešu miltiem tev visu to būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Un tev to būs likt kurvī un tai kurvī to atnest līdz ar to vērsi un tiem abiem auniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Tad tev būs pievest Āronu un viņa dēlus pie saiešanas telts durvīm un mazgāt ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Pēc tam tev būs ņemt tās drēbes un Āronam apvilkt tos šauros svārkus un to efoda uzvalku un to efodu un to krūšu glītumu un apjozt viņam to jostu ap to efodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Un tev to cepuri būs likt viņam galvā un to svētības kroni tev būs likt pie tās cepures.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Un tev būs ņemt to svaidāmo eļļu un uzliet uz viņa galvu. Tā tev viņu būs svaidīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Pēc tam tev būs atvest arī viņa dēlus un tiem tos svārkus apvilkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Un tev tos būs apjozt ar to jostu, proti Āronu un viņa dēlus, un tev tiem būs uzsiet tās cepures, ka tiem ir tas priesteru amats par likumu mūžīgi. Tā tev būs amatā iecelt Āronu un viņa dēlus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Un to vērsi būs atvest priekš saiešanas telts, un Āronam un viņa dēliem būs savas rokas likt uz tā vērša galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Un tev to vērsi būs nokaut Tā Kunga priekšā, priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Pēc tam tev būs ņemt no tā vērša asinīm un ar savu pirkstu likt uz altāra ragiem, un visas citas asinis tev būs izliet uz altāra grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Un tev būs ņemt visus taukus, kas iekšas apklāj, un tos taukus, kas pār aknām, un tās abas īkstis ar tiem taukiem, kas tur klāt, un tev tos būs iededzināt uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Bet tā vērša gaļu un viņa ādu un viņa sūdus tev būs ar uguni sadedzināt ārā aiz lēģera; tas ir grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Pēc tam tev būs ņemt to vienu aunu un Āronam un viņa dēliem būs savas rokas likt uz tā auna galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Un tev būs to aunu nokaut un ņemt viņa asinis un slacīt visapkārt ap altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Un to aunu tev būs dalīt gabalos un mazgāt viņa iekšas un viņa kājas un tās uzlikt uz viņa gabaliem un uz viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Tā tev visu to aunu būs iededzināt uz altāra; tas ir dedzināms upuris Tam Kungam par saldu smaržu, tas ir uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Pēc tam tev būs ņemt to otru aunu, un Āronam un viņa dēliem būs savas rokas likt uz tā auna galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Un tev to aunu būs nokaut un ņemt no viņa asinīm un likt uz Ārona labās auss skripstiņu un uz viņa dēlu labās auss skripstiņu, tāpat uz viņa dēlu labās rokas īkšķi un uz viņu labās kājas īkšķi, un tās asinis tev būs slacīt uz altāri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Tad tev būs ņemt no tām asinīm, kas ir uz altāra, un no tās svaidāmās eļļas un slacīt uz Āronu un viņa drēbēm un uz viņa dēliem un uz viņa dēlu drēbēm, lai viņš ir svētīts un viņa drēbes un viņa dēli un viņa dēlu drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Un tev no tā auna būs ņemt taukus un asti un tos taukus, kas iekšas apklāj, un aknu taukus un abējas īkstis ar tiem taukiem, kas pie tām, un to labo pleci, jo tas ir tas iesvētīšanas auns,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Un vienu kukuli maizes un vienu eļļas karašu un vienu rausi no tā neraudzētās maizes kurvja, kam būs būt priekš Tā Kunga vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Un tev visu to būs likt uz Ārona un uz viņa dēlu plaukstām, un to līgot par līgojamu upuri Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Pēc tam ņem to no viņu rokām un iededzini to uz altāra pār to dedzināmo upuri, par saldu smaržu Tā Kunga priekšā; - tas ir uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Tad ņem tās krūtis no Ārona iesvētīšanas auna, un līgo tās Tā Kunga priekšā; - tā būs tava daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Un tev būs svētīt tās līgojama upura krūtis un tā cilājama upura pleci, kas ir cilāts un līgots no Ārona un viņa dēlu iesvētīšanas auna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Un tam būs būt Āronam un viņa dēliem par mūžīgu iestādījumu no Israēla bērniem; jo tas ir cilājams upuris, un Israēla bērnu cilājamam upurim būs būt pie viņu pateicības upuriem, viņu cilājamam upurim priekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Ārona svētās drēbes piederēs viņa dēliem pēc viņa, ka tie iekš tām top svaidīti un amatā iecelti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Septiņas dienas tās būs valkāt tam no viņa dēliem, kas viņa vietā būs par priesteri, kam jāiet saiešanas teltī un jākalpo tai svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Tev būs ņemt iesvētīšanas upura aunu un viņa gaļu vārīt svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Tad Āronam un viņa dēliem būs ēst tā auna gaļu ar to maizi, kas kurvī, priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Un tiem to būs ēst, ar ko tā salīdzināšana ir notikusi, lai viņi top amatā iecelti un iesvētīti, bet svešiniekiem to nebūs ēst, jo tā ir svēta barība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Un ja kas atliek no tās iesvētīšanas upura gaļas vai no šīs maizes līdz rītam, tad tev to atlikumu būs sadedzināt ar uguni, to nebūs ēst, jo tas ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tā tev būs darīt Āronam un viņa dēliem, kā es tev esmu pavēlējis; septiņas dienas tev būs viņus iesvētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Tev ikdienas arī vienu vērsi būs nokaut par grēku upuri, par salīdzināšanu, un to altāri tev būs šķīstīt, salīdzināšanu darot par viņu, un tev viņu būs svaidīt, ka viņš top svētīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Septiņas dienas tev būs salīdzināšanu darīt par to altāri un viņu iesvētīt, un tad tas altāris būs augsti svēts; ikviens, kas to altāri aizskar, lai ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Šis nu ir, ko tev būs upurēt uz altāra: divus jērus, gadu vecus, ikdienas allažiņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'To vienu jēru tev būs upurēt no rīta un to otru tev būs upurēt ap vakara laiku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Ar desmito tiesu kviešu miltu, ko būs sajaukt ar vienu ceturtdaļu inna sagrūstas eļļas, un par dzeramo upuri vienu ceturtdaļu inna vīna, priekš tā viena jēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Un to otru jēru tev būs upurēt ap vakara laiku; tev ar to būs darīt, tā kā ar ēdamo upuri rītā un kā ar viņa dzeramo upuri; par saldu smaržu tas ir uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Šis ir tas dienišķais dedzināmais upuris pie jūsu pēcnākamiem, pie saiešanas telts durvīm Tā Kunga priekšā; tur būs mūsu saiešanas vieta, tur Es ar tevi runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Un tur būs Mana saiešanas vieta ar Israēla bērniem, ka tie top svētīti iekš Manas godības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Un Es svētīšu to saiešanas telti līdz ar to altāri un svētīšu arī Āronu un viņa dēlus, ka tie ir Mani priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Un Es mitīšu Israēla bērnu vidū un Es tiem būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Un tiem būs atzīt, ka Es esmu Tas Kungs, viņu Dievs, kas tos izvedis no Ēģiptes zemes, lai Es viņu vidū dzīvoju, Es Tas Kungs, viņu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Tev būs taisīt arī kvēpināmu altāri kvēpināšanai; no akācijas koka tev to būs taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Viena olekts lai ir viņa garums un viena olekts viņa platums, četrkantīgam tam būs būt, bet divas olektis lai ir viņa augstums; - viņa ragiem būs iziet no tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Un tev viņu būs apvilkt ar tīru zeltu, viņa virsu un viņa sienas visapkārt, arī viņa ragus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Un tev būs viņam taisīt zelta kroni visapkārt, tev būs taisīt arī divus zelta riņķus apakš viņa kroņa; tev tos būs taisīt, ka abiem viņa sāniem tur var ielikt nesamās kārtis, ka viņu ar tām var nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Un tās nesamās kārtis tev būs taisīt no akācijas koka un tās apvilkt ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Un tev viņu būs nolikt priekš tā priekškaramā, kas būs liecības šķirsta priekšā, priekš salīdzināšanas vāka, kas virsū uz tās liecības; tur būs mūsu saiešanas vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Un Āronam uz tā būs iededzināt saldas kvēpināmās zāles, ik rītu, kad viņš tos eļļas lukturīšus šķīstījis, tad viņam tās būs iededzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Un kad Ārons tos eļļas lukturīšus uzliek ap vakara laiku, tad viņam atkal būs iededzināt kvēpināmās zāles, vienmēr priekš Tā Kunga uz jūsu pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Tev uz tā nebūs iededzināt svešas kvēpināmās zāles, nedz dedzināmu upuri, nedz ēdamu upuri; tev arī nebūs liet uz to dzeramu upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Un Āronam vienreiz gadskārtā viņa ragus būs salīdzināt ar grēku upura asinīm par salīdzināšanu; vienreiz gadskārtā to būs salīdzināt uz jūsu pēcnākamiem, tas altāris ir Tam Kungam augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Vēl Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Ja tu Israēla bērnus skaitīsi pēc viņu pulkiem, tad ikvienam par savas dvēseles atpestīšanu būs upurēt Tam Kungam, kad tu tos skaitīsi, lai nekāda mocība uz viņiem nenāk, kad tu tos skaiti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Tas tiem jādod: ikvienam, kas top skaitīts, būs dot pussēķeli pēc svētās vietas sēķeļa, (šis sēķelis ir divdesmit ģeras); tas pussēķelis ir cilājams upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Ikvienam, kas pie skaitīšanas divdesmit gadus vecs un pāri, būs dot Tā Kunga cilājamo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bagātam nebūs vairāk un nabagam nebūs mazāk dot nekā to pussēķeli, ko būs dot Tam Kungam par cilājamu upuri, par dvēseles salīdzināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Tev tad to salīdzināšanas naudu būs ņemt no Israēla bērniem, un nolikt kalpošanai pie saiešanas telts; un tas Israēla bērniem būs par piemiņu Tā Kunga priekšā, ka jūsu dvēseles top salīdzinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Tev būs taisīt arī mazgājamu trauku no vara, un viņa kāju arīdzan no vara, priekš mazgāšanas, un tev to būs nolikt starp saiešanas telti un altāri un tur ieliet ūdeni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Ka Ārons un viņa dēli tur var mazgāt savas rokas un savas kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Kad tiem jāiet saiešanas teltī, tad tiem ar ūdeni būs mazgāties, ka tie nemirst, vai kad tie nāk kalpot pie altāra un iededzināt uguni Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Tad tiem būs mazgāt savas rokas un savas kājas, ka tie nemirst, un tas tiem būs par likumu, viņam un viņa dzimumam mūžīgi, uz viņu pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Un tu ņem dārgas zāles, it šķīstas mirres, piecsimt sēķeļus, un pusi kanēli, proti divsimt un piecdesmit sēķeļus, un kalmes divsimt un piecdesmit sēķeļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Un laurus piecsimt sēķeļus, pēc svētās vietas sēķeļa, un vienu innu eļļas no eļļas kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Un taisi no tā to svēto svaidāmo eļļu, svaidāmu zalvi, kā aptieķeri mēdz taisīt; tā būs tā svētā svaidāmā eļļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Un svaidi ar to saiešanas telti un liecības šķirstu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'To galdu ar visiem viņa rīkiem un to lukturi ar viņa rīkiem un to kvēpināmo altāri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Un to dedzināmo upuru altāri ar visiem viņa rīkiem un to mazgājamo trauku ar viņa kāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Tev tos būs svētīt, ka tie ir augsti svēti; ikviens, kas tos aizskar, lai ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Tev arī būs svaidīt Āronu un viņa dēlus, un tev tos būs iesvētīt, ka tie ir Mani priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Un tev būs runāt uz Israēla bērniem un sacīt: šī būs tā svētā svaidāmā eļļa priekš Manis uz jūsu pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'To nebūs liet uz nekāda cilvēka miesu, jums arī nebūs tādu taisīt, kas tai līdzīga; tā ir svēta, lai tā jums ir svēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Kas tādu taisīs, kas tai ir līdzīga, un kas no tās lies uz kādu svešinieku, tam būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Vēl Tas Kungs sacīja uz Mozu: ņem zāles, kas dod labu smaržu, mirres un oniksu un galbanu, šīs saldās smaržas zāles ar šķīstu vīraku vienādā svarā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Un taisi no tā kvēpināmās zāles, kā aptieķeri mēdz taisīt, sālītas, šķīstas, svētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Un tev tās būs sagrūst it smalki, un no tām nolikt tās liecības priekšā saiešanas teltī, kur būs mūsu saiešanas vieta; tās lai jums ir augsti svētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Bet tādas kvēpināmās zāles, kā šīs ir taisītas, jums priekš sevis nebūs taisīt, tām būs būt svētām Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Kas tādas taisīs, kas tām līdzīgas un ar tām kvēpinās, tam būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Pēc tam Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Redzi, Es esmu saucis pie vārda Becaleēli, Ūrus, Hūra dēla, dēlu no Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Un Es to esmu pildījis ar Dieva garu, ar gudrību un prātu un samanību pie visāda darba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Izdomāt gudrus darbus un strādāt iekš zelta un iekš sudraba un iekš vara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Un iekš smalkas akmeņu griešanas, ka tos var ielikt, un iekš smalkas koku griešanas, darīt visādus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Un redzi, Es viņam esmu pielicis Aholiabu, Ahisamaka dēlu, no Dana cilts, un ikkatram, kam gudrs prāts, Es esmu devis gudrību sirdī, un tiem būs taisīt visu, ko Es tev esmu pavēlējis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Proti to saiešanas telti un to liecības šķirstu un to salīdzināšanas vāku, kas uz tā, un visus tos telts rīkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Un to galdu ar viņa rīkiem un to zelta lukturi ar visiem viņa rīkiem un to kvēpināmo altāri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Un to dedzināmo upuru altāri ar visiem viņa rīkiem un to mazgājamo trauku ar viņa kāju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Un tās amata drēbes un priestera Ārona svētās drēbes un viņa dēlu drēbes uz priesteru amatu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Un to svaidāmo eļļu un to kvēpināmo zalvi no saldas smaržas zālēm priekš tās svētās vietas; kā Es tev esmu pavēlējis, tiem būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Vēl Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Un tu runā uz Israēla bērniem un saki: jums būs sargāt manu svēto dienu, jo tā ir zīme starp mani un jums uz jūsu pēcnākamiem, lai top zināms, ka Es esmu Tas Kungs, kas jūs svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Tad nu turat to dusēšanas dienu, tāpēc ka tā jums ir svēta; kas to nesvētī, tam būs tapt nokautam, jo ikviens, kas tanī kādu darbu darīs, tam dvēsele taps izdeldēta no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sešas dienas būs darbu darīt, bet tā septītā diena ir liela dusēšanas diena, Tam Kungam svēta; kas dusēšanas dienā darbu dara, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Tad nu Israēla bērniem būs svētīt to dusēšanas dienu un turēt to dusēšanas dienu uz saviem pēcnākamiem par derību mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Starp Mani un Israēla bērniem tā lai ir zīme mūžīgi. Jo sešās dienās Tas Kungs radījis debesis un zemi, un septītā dienā Viņš ir dusējis un atspirdzinājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Un Viņš deva Mozum, kad ar to beidza runāt uz Sinaī kalna, divus liecības galdiņus, akmens galdiņus, aprakstītus ar Dieva pirkstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Kad nu tie ļaudis redzēja, ka Mozus kavējās nokāpt no kalna, tad tie sapulcējās pie Ārona un uz to sacīja: celies, taisi mums dievu, kas iet mūsu priekšā; jo šim Mozum, šim vīram, kas mūs izvedis no Ēģiptes zemes, mēs nezinām, kas viņam noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Tad Ārons uz tiem sacīja: noplēšat tās zelta ausu sprādzes, kas ir jūsu sievu, jūsu dēlu un jūsu meitu ausīs, un atnesiet tās pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Tad visi ļaudis noplēsa tās zelta ausu sprādzes, kas bija viņu ausīs, un tās atnesa pie Ārona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Un viņš tās ņēma no viņu rokām un zīmēja ar rakstāmo un no tām lēja teļu; tad tie sacīja: šis ir tavs dievs, Israēl, kas tevi izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Kad Ārons to redzēja, tad viņš priekš tā uztaisīja altāri, un Ārons izsauca un sacīja: rītā ir Tā Kunga svētki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Un tie cēlās otrā rītā agri un upurēja dedzināmos upurus un atnesa pateicības upurus, un tie ļaudis apsēdās ēst un dzert un cēlās līksmoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Tad Tas Kungs sacīja uz Mozu: ej, kāp zemē! Jo tavi ļaudis, ko tu esi izvedis no Ēģiptes zemes, ir apgrēkojušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Tie drīz atkāpušies no tā ceļa, ko Es tiem biju pavēlējis; tie sev lējuši teļu un to pielūguši un tam ir upurējuši un sacījuši: šis ir tavs dievs, Israēl, kas tevi izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Vēl Tas Kungs sacīja uz Mozu: Es šos ļaudis esmu raudzījis, un redzi, tie ir pārgalvīgi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Un nu laid Mani, ka Mana dusmība pret tiem iedegās un tos aprij, tad Es tevi darīšu par lielu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Bet Mozus lūdza To Kungu, savu Dievu, un sacīja: ak Kungs! Kāpēc Tava dusmība iedegusies par Taviem ļaudīm, ko Tu no Ēģiptes zemes esi izvedis ar lielu spēku un ar stipru roku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Kāpēc ēģiptiešiem būs runāt un sacīt: uz nelaimi Viņš tos ir izvedis, ka Viņš tos nokautu kalnos un izdeldētu no zemes virsas? Atgriezies no Savas dusmības karstuma un lai Tev ir žēl ļauna darīt Saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Piemini Ābrahāmu, Īzaku un Israēli, Savus kalpus, kam Tu pie Sevis paša esi zvērējis un uz tiem runājis: Es vairošu jūsu dzimumu kā debess zvaigznes, un visu šo zemi, par ko esmu runājis, Es došu jūsu dzimumam par īpašumu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Tad Tam Kungam bija žēl tā ļaunuma, par ko Viņš bija runājis, to darīt Saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Un Mozus griezās atpakaļ un nokāpa no kalna ar tiem diviem liecības galdiņiem savā rokā; tie galdiņi bija abējās pusēs aprakstīti; vienā un otrā pusē tie bija aprakstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Un tie galdiņi bija Dieva darbs, un tas raksts bija Dieva raksts, iegriezts tanīs galdiņos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Kad nu Jozuas to ļaužu balsi dzirdēja un to troksni, tad viņš sacīja uz Mozu: tur ir kara troksnis lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Bet tas sacīja: tā nav brēkšanas balss ne no uzvarētāja, ne no uzvarētā, es dzirdu gavilēšanas balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Un kad viņš tuvu nāca pie lēģera un redzēja to teļu un to diešanu, tad Mozus iedegās dusmās un viņš meta tos galdiņus no savām rokām un tos sasita apakšā pie kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Un viņš ņēma to teļu, ko tie bija taisījuši, un to sadedzināja ar uguni un to sagrūda, kamēr tas tapa smalks, un to izkaisīja pa ūdens virsu un ar to dzirdināja Israēla bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Un Mozus sacīja uz Āronu: ko šie ļaudis tev darījuši, ka tu tādu lielu grēku pār tiem esi vedis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Tad Ārons sacīja: lai mana Kunga dusmas neiedegās; tu pazīsti tos ļaudis, ka tie ir ļauni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Tie uz mani sacīja: taisi mums dievu, kas mums iet priekšā; jo šim Mozum, šim vīram, kas mūs izvedis no Ēģiptes zemes, mēs nezinām, kas tam ir noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Un es uz tiem sacīju: kam ir zelts, tas lai to noplēš. Un tie man to deva un es to iemetu ugunī; no tā kļuva tas teļš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Kad nu Mozus redzēja, ka tie ļaudis bija palaidušies, jo Ārons tos bija palaidis, par kaunu viņu pretinieku priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Tad Mozus nostājās lēģera vārtos un sacīja: kas Tam Kungam pieder, tas lai nāk pie manis! Tad pie viņa sapulcējās visi Levja dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Un viņš uz tiem sacīja: tā saka Tas Kungs, Israēla Dievs: joziet ikviens savu zobenu ap saviem gurniem un ejat šurp un turp no vieniem lēģera vārtiem līdz otriem, un nokaujat ikviens savu brāli un ikviens savu draugu un ikviens savu tuvāko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Un Levja dēli darīja pēc Mozus vārda, un tai dienā krita no tiem ļaudīm kādi trīs tūkstoši vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Tad Mozus sacīja: pildāt šodien savas rokas Tam Kungam, jo ikviens ir bijis pret savu dēlu un pret savu brāli, ka šodien uz jums top likta svētība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Otru rītu Mozus sacīja uz tiem ļaudīm: jūs esat apgrēkojušies ar lieliem grēkiem, un nu es kāpšu augšām pie Tā Kunga, vai es varēšu jūsu grēkus salīdzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Tad Mozus griezās atpakaļ pie Tā Kunga un sacīja: ak, šie ļaudis ir darījuši lielus grēkus un sev taisījuši zelta dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nu tad, piedod tiem viņu grēkus; bet ja ne, tad izdeldē labāk mani no Tavas grāmatas, ko Tu esi rakstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Tad Tas Kungs sacīja uz Mozu: kas pret Mani apgrēkojies, to Es izdeldēšu no Savas grāmatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Tad nu ej, vadi tos ļaudis, kurp Es tev esmu sacījis. Redzi, Mans eņģelis ies tavā priekšā, - tomēr Savā piemeklēšanas dienā Es pie tiem piemeklēšu viņu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Tā Tas Kungs sita tos ļaudis, tāpēc ka tie bija taisījuši to teļu, ko Ārons bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Un Tas Kungs sacīja uz Mozu: ej un celies no šejienes, tu un tie ļaudis, ko tu esi izvedis no Ēģiptes zemes, uz to zemi, ko Es esmu zvērējis Ābrahāmam, Īzakam un Jēkabam, sacīdams: tavam dzimumam Es to došu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Un Es sūtīšu eņģeli tavā priekšā un izdzīšu Kanaāniešus, Amoriešus un Hetiešus un Fereziešus, Hiviešus un Jebusiešus: uz to zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Jo Es tavā vidū neiešu līdz, jo jūs esat pārgalvīgi ļaudis, ka Es ceļā jūs neapriju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Kad tie ļaudis dzirdēja šo briesmīgo vārdu, tad tie žēlojās, un neviens neapvilka savas greznās drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Un Tas Kungs bija sacījis uz Mozu: saki Israēla bērniem: jūs esat pārgalvīgi ļaudis; kad Es tev iešu līdz vienu acumirkli, tad Es tevi izdeldēšu. Bet nu noliec savu greznumu, tad Es zināšu, ko tev darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Tad Israēla bērni nometa savu greznumu pie Horeb kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Un Mozus ņēma to telti un to uzcēla ārpusē, tālu no lēģera, un to nosauca par saiešanas telti. Un kas To Kungu meklēja, tam bija jāiziet uz to saiešanas telti, kas bija ārā no lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Un kad Mozus izgāja uz to telti, tad visi ļaudis cēlās, un ikviens stāvēja sava dzīvokļa durvīs un skatījās Mozum pakaļ, tiekams tas bija iegājis teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Un kad Mozus teltī iegāja, tad tas padebeša stabs nonāca un stāvēja telts durvīs, un Viņš runāja ar Mozu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Un visi ļaudis redzēja to padebeša stabu telts durvīs stāvam, un visi ļaudis cēlās un ikviens metās pie zemes sava dzīvokļa durvīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Un Tas Kungs runāja ar Mozu vaigu vaigā, itin kā kas runā ar savu draugu. Pēc tam viņš griezās atpakaļ uz lēģeri, bet Jozuas, viņa sulainis, Nuna dēls, jauneklis, neatstājās no telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Un Mozus sacīja uz To Kungu: redzi, Tu man saki: vadi šos ļaudis! Bet Tu man nesaki, ko Tu man sūtīsi līdzi, jebšu Tu esi sacījis: Es pazīstu tevi pie vārda, - un atkal: tu esi žēlastību atradis Manās acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Un nu, ja es žēlastību esmu atradis Tavās acīs, tad lūdzams, dari man jel zināmu Tavu ceļu, lai es Tevi pazīstu, un lai es atrodu žēlastību Tavās acīs, un uzlūko, ka šie ļaudis ir Tavi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Bet Viņš sacīja: Mans vaigs ies līdz, un Es tevi vedīšu pie dusas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Tad tas uz Viņu sacīja: ja Tavs vaigs neies līdzi, tad neved mūs no šejienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Jo pie kam varētu manīt, ka es un Tavi ļaudis žēlastību esam atraduši Tavās acīs, kā vien pie tam, ka Tu mums ej līdzi? Tā mēs tapsim brīnišķa tauta, es un Tavi ļaudis, priekš visām tautām, kas virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Tad Tas Kungs sacīja uz Mozu: arī šo lietu, ko tu esi runājis, Es darīšu; jo tu esi atradis žēlastību Manās acīs, un Es tevi pazīstu pie vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Tad tas sacīja: rādi man, lūdzams, Savu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Un Viņš sacīja: Es visai Savai laipnībai likšu garām iet tavā priekšā un saukšu Tā Kunga vārdu tavā priekšā. Jo Es esmu žēlīgs, kam esmu žēlīgs, un apžēlojos, par ko apžēlojos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Vēl Viņš sacīja: tu Manu vaigu nevari redzēt, jo neviens cilvēks Mani nevar redzēt un dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Un Tas Kungs sacīja: redzi, še pie Manis ir vieta, tur tev būs stāvēt uz klints.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Un kad Mana godība ies garām, tad Es tev likšu stāvēt klints alā, un tevi apklāšu ar Savu roku, tiekams būšu garām gājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Un kad Es Savu roku būšu atņēmis, tad tu Mani redzēsi no aizmugures, bet Manu vaigu nevar redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Tad Tas Kungs sacīja uz Mozu: izcērt divus akmens galdiņus tā kā tos pirmajus, tad Es uz tiem galdiņiem rakstīšu tos vārdus, kas ir bijuši uz tiem pirmajiem galdiņiem, ko tu esi salauzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Un rītu esi gatavs, ka tu rītu vari kāpt uz Sinaī kalnu, un stājies Manā priekšā tur kalna galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Un nevienam nebūs kāpt līdz ar tevi augšā, nevienam arī nebūs tapt redzētam pa visu to kalnu, arī nedz sīkus, nedz lielus lopus nebūs ganīt tam kalnam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Tad Mozus izcirta divus akmens galdiņus tā kā tos pirmajus un cēlās no rīta agri un kāpa augšam uz Sinaī kalnu, kā Tas Kungs viņam bija pavēlējis; un viņš ņēma savā rokā tos divus akmens galdiņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Tad Tas Kungs nonāca padebesī, un tur piestājās pie viņa un izsauca Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Un Tas Kungs gāja viņam garām un izsauca: Tas Kungs, Dievs ir žēlīgs un sirdsmīlīgs Dievs, lēnprātīgs un liels no žēlastības un uzticības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Kas parāda žēlastību daudz tūkstošiem, piedod noziegumus, pārkāpumus un grēkus, bet arī nepamet nesodītus, piemeklēdams tēvu grēkus pie bērniem un bērnu bērniem līdz trešam un ceturtam augumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Un Mozus traucās un metās zemē un pielūdza,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Un sacīja: Kungs, ja esmu atradis žēlastību Tavās acīs, tad lūdzams, ej jel, Kungs, līdz ar mums, jebšu šie ir pārgalvīgi ļaudis, - ka Tu piedod mūsu noziegumus un mūsu grēkus, un pieņem mūs par Savu īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Tad Viņš sacīja: redzi, Es daru derību: priekš visiem taviem ļaudīm Es darīšu brīnumus, kas nav darīti nekur pa zemes virsu, nedz pie kādām tautām, tā ka visiem ļaudīm, starp kuriem tu esi, būs redzēt Tā Kunga darbu, jo tās būs ļoti bijājamas lietas, ko Es pie tevis darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Ņem vērā, ko Es tev šodien pavēlu: redzi, Es izdzīšu tavā priekšā Amoriešus un Kanaāniešus un Hetiešus un Fereziešus un Hiviešus un Jebusiešus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Sargies, ka tu nedari derību ar tās zemes iedzīvotājiem, pie kuriem tu nāksi, ka tie nekļūst tavā starpā par slazda valgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Bet jums būs izpostīt viņu altārus un jums būs salauzīt viņu uzceltos stabus un nocirst viņu elku kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Jo tev nebūs pielūgt nekādu citu dievu, - jo Tas Kungs: dusmotājs ir Viņa vārds, Viņš ir dusmīgs Dievs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ka tu nedari nekādu derību ar tās zemes iedzīvotājiem, un kad tie saviem dieviem mauko pakaļ un nes upurus saviem dieviem, ka tie tevi neaicina, un tu neēdi no viņu upuriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Un ka tu saviem dēliem neņem no viņu meitām, un viņu meitas saviem dieviem nemauko pakaļ un nedara arī tavus dēlus pakaļ maukojam viņu dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Tev nebūs sev taisīt lietus dievus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Tev būs turēt neraudzētās maizes svētkus; septiņas dienas tev būs ēst neraudzētu maizi, kā Es tev esmu pavēlējis, noliktā laikā Abiba mēnesī; jo Abiba mēnesī tu esi izgājis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Viss, kas māti atplēš, Man pieder, un visi tavi lopi, kas no tēviņu kārtas piedzimst, māti atplēsdami, lai lieli, lai sīki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Bet ēzeli, kas ēzeļa māti atplēš, tev būs izpirkt ar avi; bet ja tu to neizpirksi, tad lauz viņam kaklu. Visus pirmdzimušos no taviem dēliem tev būs izpirkt, un priekš Mana vaiga jums nebūs rādīties tukšiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sešas dienas tev būs strādāt, bet septītā dienā dusēt, arī aramā un pļaujamā laikā tev būs dusēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Nedēļu svētkus arīdzan tev būs turēt ar kviešu pļaujas pirmajiem augļiem un pļaušanas svētkus, kad gads pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trīs reiz gadskārtā visiem, kas jūsu starpā ir vīrieši, būs rādīties Tā Kunga Dieva, Israēla Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Kad Es tos pagānus izdzīšu tavā priekšā, un izpletīšu tavas robežas, tad neviens tavu zemi neiekāros, kamēr tu iesi rādīties Tā Kunga, sava Dieva priekšā, trīs reiz gadskārtā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Tev nebūs upurēt Mana upura asinis ar raudzētu maizi, un Pasa svētku upurim nebūs palikt cauru nakti līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tos pirmajus no tavas zemes pirmajiem augļiem tev būs nest Tā Kunga tava Dieva, namā; āzīti tev nebūs vārīt viņa mātes pienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Un Tas Kungs sacīja uz Mozu: “Raksti šos vārdus, jo pēc šiem vārdiem Es esmu darījis derību ar tevi un ar Israēli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Un viņš tur bija pie Tā Kunga četrdesmit dienas un četrdesmit naktis; viņš neēda maizes un nedzēra ūdens, un rakstīja uz tiem galdiņiem tos derības vārdus, tos desmit vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Un notikās, kad Mozus nokāpa no Sinaī kalna un tie divi liecības galdiņi bija Mozus rokā, tad no tā kalna nokāpjot Mozus nezināja, ka viņa vaiga āda spīdēja, tādēļ ka tas ar Viņu bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Kad nu Ārons un visi Israēla bērni Mozu uzlūkoja, redzi, tad viņa vaiga āda spīdēja, tāpēc tie bijās nākt tuvu pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Tad Mozus tos sauca un Ārons un visi draudzes virsnieki griezās pie viņa un Mozus uz tiem runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Pēc tam visi Israēla bērni piegāja, un viņš tiem visu pavēlēja, ko Tas Kungs ar viņu bija runājis Sinaī kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Un kad Mozus beidza ar tiem runāt, tad viņš lika apsegu uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Bet kad Mozus priekš Tā Kunga nāca ar Viņu runāt, tad tas noņēma to apsegu, tiekams tas izgāja, un kad tas bija izgājis, tad tas runāja uz Israēla bērniem, kas tam bija pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Un Israēla bērni redzēja Mozus vaigu, ka Mozus vaiga āda spīdēja, un tad Mozus to apsegu atkal uzlika uz savu vaigu, tiekams tas iegāja ar Viņu runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Un Mozus sapulcēja visu Israēla bērnu draudzi un uz tiem sacīja: šie ir tie vārdi, ko Tas Kungs ir pavēlējis, ka tos būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sešas dienas būs darbu darīt, bet septīta diena lai jums ir svēta, liela dusēšanas diena Tam Kungam; ikviens kas tanī dara kādu darbu, tam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Jums nebūs uguni kurt savās māju vietās dusēšanas dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Un Mozus runāja uz visu Israēla bērnu draudzi sacīdams: šis ir tas vārds, ko Tas Kungs ir pavēlējis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Ņemiet no tā, kas jums pieder, cilājamu upuri Tam Kungam; ikviens, kam labprātīga sirds, lai to atnes par cilājamu upuri Tam Kungam, zeltu un sudrabu un varu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Un arī zilumu un purpuru un karmezīnu un smalkas dzijas un kazu spalvas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Un pasarkanas aunu ādas un roņu ādas un akācijas koku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Un eļļu lukturim un dārgas zāles svaidāmai eļļai un kvēpināšanai saldi smaržīgas zāles,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Un oniksa akmeņus un dārgus ieliekamus akmeņus efodam un krūšu glītumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Un visiem, kam samanīga sirds jūsu starpā, būs nākt un darīt visu, ko Tas Kungs pavēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'To dzīvokli, viņa telti un viņa segu, viņa kāsīšus un viņa dēļus viņa kārtis un viņa stabus un viņa kājas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'To šķirstu un viņa nesamās kārtis, to salīdzināšanas vāku un to priekškaramo segu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'To galdu un viņa nesamās kārtis un visus viņa rīkus un tās priekšliekamās maizes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Un to lukturi priekš spīdēšanas un viņa rīkus un tos eļļas lukturīšus un to eļļu priekš spīdēšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Un to kvēpināšanas altāri un viņa nesamās kārtis un to svaidāmo eļļu un tās kvēpināmās smaržīgās zāles un to durvju segu pie dzīvokļa durvīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'To dedzināmo upuru altāri līdz ar viņa vara traliņiem, viņa kārtis un visus viņa rīkus, to mazgājamo trauku un viņa kāju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Tās pagalma gardīnes un viņu stabus un viņu kājas un to segu pagalma vārtos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Tās dzīvokļa naglas un tos pagalma vadžus ar viņu saitēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Tās amata drēbes priekš kalpošanas svētā vietā, priestera Ārona svētās drēbes un viņa dēlu drēbes, ka tie ir par priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Tad visa Israēla bērnu draudze aizgāja no Mozus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Un tie nāca ikviens, kam bija labprātīga sirds, un ikviens, kam gars bija labprātīgs; tie atnesa Tā Kunga cilājamo upuri priekš saiešanas telts taisīšanas un priekš visas viņas kalpošanas un priekš tām svētām drēbēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Tad nu nāca vīri ar sievām, visi kam bija labprātīga sirds, tie atnesa saktas un ausu sprādzes un gredzenus un apkaltas jostas, visādus zelta rīkus, un ja kāds gribēja atnest zeltu par līgojamu upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Un ikviens, pie kā atradās zilums un purpurs un karmezīns un smalkas dzijas un kazu spalvas un pasarkanas aunu ādas un roņu ādas, to tie atnesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Visi, kas gribēja atnest cilājamu upuri no zelta un vara, tie to atnesa par cilājamu upuri Tam Kungam, un visi, pie kuriem akācijas koks atradās, to atnesa priekš ikviena Dieva kalpošanas darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Un ikviena sieva, kam bija samanīga sirds, vērpa ar savām rokām un atnesa to vērpumu, zilumu un purpuru un karmezīnu un smalkas dzijas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Un visas sievas, kam sirds prata gudru darbu, tās vērpa kazu spalvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Un tie lielie kungi atnesa oniksa akmeņus un ieliekamus akmeņus priekš efoda un krūšu glītuma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Un dārgas zāles un eļļu lukturim un svaidāmai eļļai un saldi smaržīgas zāles priekš kvēpināšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Ikviens vīrs un ikviena sieva, kam sirds bija labprātīga, ko pienest pie visa tā darba, ko Tas Kungs caur Mozu bija pavēlējis darīt tā Israēla bērni atnesa upuri Tam Kungam no laba prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Tad Mozus sacīja uz Israēla bērniem: redziet, Tas Kungs pie vārda saucis Becaleēli, Ūrus dēla, Hūra dēla dēlu, no Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Un Dieva Gars to ir pildījis ar gudrību, prātu un samanību pie visāda darba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Izdomāt gudrus darbus un strādāt iekš zelta un iekš sudraba un iekš vara');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Un iekš dārgu akmeņu griešanas, ka tos var ielikt, un iekš koku izgriešanas, uz visāda izrotāta roku darba strādāšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Viņš tam arī sirdī devis mācīt, tam un Aholiabam, Ahisamaka dēlam, no Dana cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Viņš tos ar sirds gudrību ir pildījis, ka tie var darīt visādu amatnieka un audēja un rakstītāja darbu iekš ziluma un iekš purpura un karmezīna un iekš smalkām dzijām, arī vēvera (audēja) darbu, ka tie var darīt visādu darbu un izdomāt gudras lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Un Becaleēls un Aholiabs lai strādā un ikviens, kam samanīga sirds, kam Tas Kungs devis gudrību un saprašanu, zināt visādu darbu pie svētās vietas kalpošanas, tā kā Tas Kungs bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Un Mozus aicināja Becaleēli un Aholiabu, un ikvienu, kam bija gudra sirds, kam Tas Kungs bija devis gudrību sirdī, visus, kam sirds nesās, pie tā darba iet un to darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Un tie ņēma no Mozus visu to cilājamo upuri, ko Israēla bērni bija atnesuši priekš tā darba pie svētās vietas taisīšanas, ka tie to darītu, un tie atnesa vēl ik rītu pie viņa upurus no laba prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Tāpēc visi tie gudrie nāca, kas svētās vietas darbu darīja, ikviens savu darbu, kas tam bija jādara, un runāja uz Mozu sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Tie ļaudis pienes daudz vairāk, nekā vajag pie tā darba darīšanas, ko Tas Kungs ir pavēlējis darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Tad Mozus pavēlēja pa lēģeri izsaukt un sacīt: vīri un sievas, nenesat vairs cilājamu upuri priekš tā darba svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Tad tie ļaudis mitējās nest, jo bija diezgan priekš visa tā darba vajadzības, kas bija jādara, un vēl atlikās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Tā visi tie gudrie starp tiem darba strādniekiem taisīja to dzīvokli no desmit deķiem, no šķetinātām smalkām dzijām un ziluma un purpura un karmezīna ar ķerubiem, - izrotātu darbu viņi to taisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Viena deķa garums bija divdesmit astoņas olektis un platums bija četras olektis; visiem tiem deķiem bija vienāds mērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Un viņš salika piecus deķus vienu pie otra, un atkal piecus deķus viņš salika vienu pie otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Pēc tam viņš taisīja cilpas no ziluma pie viena deķa vīles tai malā, kur tas tapa pielaists; tā viņš darīja arī pie otra deķa vīles, kur atkal tas tapa pielaists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Piecdesmit cilpas viņš taisīja pie viena deķa, un piecdesmit cilpas viņš taisīja pie otra deķa pielaižamās malas, šās cilpas vienu otrai pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Un viņš taisīja arī piecdesmit zelta kāsīšus un salika tos deķus vienu pie otra ar tiem kāsīšiem, ka tas tapa par vienu dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Un viņš taisīja deķus no kazu spalvas telts pārklāju, pāri pār to dzīvokli; no vienpadsmit deķiem viņš to taisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Viena deķa garums bija trīsdesmit olektis un viena deķa platums četras olektis; šiem vienpadsmit deķiem bija vienāds mērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Un viņš salika piecus deķus sevišķi un atkal sešus deķus sevišķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Un viņš taisīja piecdesmit cilpas pie tā pēdīgā(malējā) deķa vīles, kur tas tapa pielaists, un viņš taisīja piecdesmit cilpas pie tā deķa otras pielaižamās malas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Un viņš taisīja arī piecdesmit vara kāsīšus priekš telts salikšanas, ka tā vienā kopā saietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Viņš taisīja arī telts segu no pasarkanām aunu ādām, un tur virsū segu no roņu ādām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Viņš taisīja arī stāvošus dēļus pie tā dzīvokļa no akācijas koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Ikkatra dēļa garums bija desmit olektis, un ikkatra dēļa platums pusotras olekts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Divas tapas bija vienam dēlim, ar ko viens ar otru tapa salaists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Tā viņš darīja ar visiem dzīvokļa dēļiem; viņš taisīja arī tā dzīvokļa dēļus dienvidu pusē, divdesmit dēļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Un taisīja četrdesmit sudraba kājas apakš tiem divdesmit dēļiem, divas kājas apakš viena dēļa pie viņa divām tapām, un divas kājas apakš otra dēļa pie viņa divām tapām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Viņš taisīja divdesmit dēļus arī otrā dzīvokļa pusē pret ziemeli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Ar viņu četrdesmit sudraba kājām, divas kājas apakš viena dēļa, un divas kājas apakš otra dēļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Bet dzīvokļa galā pret vakariem viņš taisīja sešus dēļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Viņš taisīja arī divus dēļus par stūru dēļiem dzīvokļa galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Un tie bija apakšgalā pa diviem salikti, un bija arī virsgalā kā dvīņi salikti ar vienu riņķi; tā viņš darīja ar tiem abiem abējos stūros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Tā bija astoņi dēļi ar savām sudraba kājām, sešpadsmit kājas, divas kājas apakš ikviena dēļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Viņš taisīja arī kārtis no akācijas koka, piecas pie tiem dēļiem vienā dzīvokļa pusē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Un piecas kārtis pie tiem dēļiem otrā dzīvokļa pusē, un piecas kārtis pie tiem gala dēļiem pret vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Un viņš taisīja to vidēju kārti cauršaujamu gar dēļu vidu no viena gala līdz otram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Un viņš tos dēļus apvilka ar zeltu, un viņu riņķus (priekš tām kārtīm) viņš taisīja no zelta, tās kārtis viņš arī apvilka ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Pēc tam viņš taisīja priekškaramo no ziluma un purpura un karmezīna un smalkām šķetinātām dzijām, viņš to izauda izrotātu darbu ar ķerubiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Un viņš tam taisīja četrus stabus no akācijas koka un tos apvilka ar zeltu; viņu kāsīši bija no zelta, un viņš tiem lēja četras sudraba kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Viņš taisīja arī priekš telts durvīm segu no ziluma un purpura un karmezīna un smalkām šķetinātām dzijām raibi austu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Un viņa piecus stabus un viņa kāsīšus, un viņš apvilka viņu virsgalus un viņu stīpas ar zeltu, un viņu piecas kājas bija no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Un Becaleēls taisīja to šķirstu no akācijas koka; pustrešas olekts bija viņa garums un pusotras olekts viņa platums un pusotras olekts viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Un viņš to apvilka ar šķīstu zeltu no iekšas un no ārpuses, un tam aptaisīja kroni no zelta visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Un lēja priekš tā četrus zelta riņķus pie viņa četriem stūriem, tā ka divi riņķi bija viņa vienā pusē un divi riņķi viņa otrā pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Un viņš taisīja nesamas kārtis no akācijas koka un tās apvilka ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Un viņš ielika tās nesamās kārtis tais riņķos pie šķirsta sāniem, ka šķirstu varētu nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Un viņš taisīja salīdzināšanas vāku no šķīsta zelta, pustrešas olekts bija viņa garums un pusotras olekts viņa platums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Viņš taisīja arī divus ķerubus no zelta, viņš tos izkala, salīdzināšanas vāka abējos galos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Vienu ķerubu vienā galā un otru ķerubu otrā galā, no salīdzināšanas vāka izejot viņš taisīja tos ķerubus viņa abējos galos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Un tie ķerubi izstiepa spārnus pa virsu, apklādami ar saviem spārniem salīdzināšanas vāku, un viņu vaigi bija viens otram pretī, ķerubu vaigi skatījās uz salīdzināšanas vāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Viņš taisīja arī galdu no akācijas koka; divas olektis bija viņa garums un viena olekts viņa platums un pusotras olekts viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Un viņš to apvilka ar šķīstu zeltu un tam aptaisīja zelta kroni visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Viņš tam arī aptaisīja līsti plaukstas platumā visapkārt, un viņš aptaisīja zelta kroni ap viņa līsti visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Viņš lēja arī četrus zelta riņķus pie tā, un lika tos riņķus pie tiem četriem stūriem, kas bija pie viņa četrām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Tie riņķi bija pie tās līstes priekš nesamām kārtīm, ka to galdu varētu nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Viņš taisīja arī tās nesamās kārtis no akācijas koka, un tās apvilka ar zeltu, ka to galdu varēja nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Un viņš taisīja tos rīkus, kam uz galda vajadzēja būt, viņa bļodas un viņa karotes un kannas un kausus, ar ko laistīt, no šķīsta zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Viņš taisīja arī lukturi no tīra zelta, viņš to lukturi izkala, viņa kātu un viņa zarus; viņa kausi, viņa pogas un viņa puķes no tā izstiepās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Seši zari izstiepās no viņa sāniem, trīs luktura zari no vienas puses un trīs luktura zari no otras puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Vienā zarā bija trīs kausiņi, tā kā mandeļu ziedi, ar pogu un puķi, un otrā zarā atkal trīs kausiņi, tā kā mandeļu ziedi, ar pogu un puķi. Tādi bija tie seši zari, kas no luktura izstiepās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Bet pašā lukturī bija četri kausiņi tā kā mandeļu ziedi, ar savām pogām un ar savām puķēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Un tur bija viena poga apakš diviem zariem, kas no tā izstiepās, un (atkal) viena poga apakš diviem zariem, kas no tā izstiepās, un vēl viena poga apakš diviem zariem, kas no tā izstiepās. Tā tas bija ar tiem sešiem zariem, kas no tā izstietpās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Viņa pogas un viņa zari izgāja no tā; tas bija visnotaļ vienādi izkalts no tīra zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Un viņš tam taisīja septiņus eļļas lukturīšus, viņa lukt(dakts) šķēres un viņa dzēšamos kausus no tīra zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'No viena talenta tīra zelta viņš to taisīja un visus viņa rīkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Un viņš taisīja kvēpināmo altāri no akācijas koka, - viena olekts bija viņa garums un viena olekts viņa platums, - tas bija četrkantīgs, bet divas olektis bija viņa augstums, un viņa ragi izgāja no tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Un viņš to apvilka ar tīru zeltu, viņa virsu un viņa sienas visapkārt un viņa ragus, un viņš tam aptaisīja zelta kroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Un viņš taisīja divus zelta riņķus pie tā, apakš viņa kroņa viņa divējos stūros, uz viņa abējiem sāniem priekš tām nesamām kārtīm, ar ko to varētu nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Un viņš taisīja tās nesamās kārtis no akācijas koka un tās apvilka ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Viņš taisīja arī to svēto svaidāmo eļļu un tās kvēpināmās zāles no šķīstām jaukas smaržas zālēm, kā aptieķeri mēdz taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Viņš taisīja arī dedzināmo upuru altāri no akācijas koka; piecas olektis bija viņa garums un piecas olektis viņa platums, tas bija četrkantīgs, un trīs olektis viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Un viņš taisīja viņa ragus viņa četros stūros; viņa ragi izgāja no tā, un viņš to apvilka ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Un viņš taisīja visus altāra rīkus, podus un lāpstas un slakāmus traukus, dakšas un ogļu traukus, visus viņa rīkus viņš taisīja no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Viņš taisīja tam altārim arī vara traliņus kā tīklu, apakš altāra beņķa, no apakšas līdz viņa vidum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Un viņš lēja četrus riņķus uz tiem vara traliņu četriem stūriem priekš nesamām kārtīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Un viņš taisīja tās nesamās kārtis no akācijas koka un tās apvilka ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Un viņš ielika tās nesamās kārtis tais riņķos uz altāra sāniem, ka to ar tiem varētu nest; viņš taisīja (to altāri) ar tukšu vidu no dēļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Viņš taisīja arī mazgājamo trauku no vara, ar viņa vara kāju, no to sievu spieģeļiem, kas pulkiem sanāca (kalpot) priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Viņš taisīja arī pagalmu; tai pusē pret dienvidiem, pagalma gardīnes bija no smalkām šķetinātām dzijām, simts olektis garumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Viņa divdesmit stabi un viņu divdesmit kājas bija no vara, stabu kāsīši un viņu stīpas bija no sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Arī pret ziemeli bija simts olektis. Viņu divdesmit stabi un viņu divdesmit kājas bija no vara, bet stabu kāsīši un viņu stīpas bija no sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Un tai pusē pret vakariem bija gardīnes no piecdesmit olektīm, stabu bija desmit, un kāju desmit; stabu kāsīši un viņu stīpas bija no sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Un pret rītiem bija piecdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Tās gardīnes vienā pusē bija piecpadsmit olektis garumā; viņām bija trīs stabi ar savām trim kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Un arī otrā pusē pie pagalma vārtiem (cik vienā tik otrā pusē) bija gardīnes piecpadsmit olektis garumā, ar viņu trim stabiem un viņu trim kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Visas pagalma gardīnes bija visapkārt no smalkām šķetinātām dzijām, un stabu kājas bija no vara, un stabu kāsīši ar viņu stīpām no sudraba, tā ka viņu virsgali ar sudrabu bija apvilkti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Un visi pagalma stabi bija ar sudrabu apstīpoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Un pagalma vārtu segs bija raibi austs no ziluma un purpura un karmezīna un smalkām šķetinātām dzijām, un divdesmit olektis bija tas garums un viņa augstums (vienas gardīnes) platumā piecas olektis, pēc tām pagalma gardīnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Un viņu četri stabi ar savām četrām kājām bija no vara un viņu kāsīši no sudraba, un viņu virsgals un viņu stīpas bija ar sudrabu apvilktas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Un visas dzīvokļa un pagalma naglas visapkārt bija no vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Tās ir visas tā dzīvokļa, tā liecības dzīvokļa, lietas, kas pavēlētas caur Mozu, priekš Levitu kalpošanas, caur Ītamara, Ārona dēla, tā priestera, roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Tad nu Becaleēls, Ūrus dēls, Hūra dēla dēls, no Jūdu cilts, taisīja visu, ko Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Un līdz ar viņu Aholiabs, Ahisamaka dēls, no Dana cilts, meistars un gudrs audējs un rakstītājs iekš ziluma un purpura un karmezīna un smalkām dzijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Visa zelta, kas pie tās svētās vietas izstrādāts, (proti) tā zelta, kas tapa dots par līgojamu upuri, bija divdesmit deviņi talenti un septiņsimt un trīsdesmit sēķeļi, pēc svētās vietas sēķeļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Bet tā sudraba, kas no draudzes tapa dots, bija simts talenti un tūkstoš septiņsimt pieci sēķeļi, pēc svētās vietas sēķeļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'No ikvienas galvas viena beka, tas ir pussēķelis, pēc svētās vietas sēķeļa no visiem, kas tapa skaitīti, no divdesmit gadiem un pāri, proti sešsimt trīs tūkstoši piecsimt un piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'No simts sudraba talentiem lēja tās kājas svētai vietai un tam priekškaram; priekš simts kājām bija simts talenti, viens talents priekš vienas kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Bet no tiem tūkstoš septiņsimt un septiņdesmit pieciem sēķeļiem viņš taisīja tos kāsīšus pie tiem stabiem, un apvilka viņu galvas un tos apstīpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Un tā vara, kas par līgojamu upuri tapa dots, bija septiņdesmit talenti un divtūkstoš un četrsimt sēķeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Un viņš no tā taisīja tās durvju kājas pie saiešanas telts un to vara altāri un tos vara traliņus, kas tam bija, un visus altāra rīkus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Un tās pagalma kājas visapkārt un tās pagalma vārtu kājas, arī visas dzīvokļa naglas un visas pagalma naglas visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Tie taisīja arī amata drēbes priekš Dieva kalpošanas svētā vietā no ziluma un purpura un karmezīna; un taisīja tās svētās drēbes Āronam, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Un viņš taisīja to efodu no zelta, ziluma un purpura un karmezīna un smalkām šķetinātām dzijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Un tie zeltu sakala plakanu un izgrieza drāti no tā, ieaust starp to zilumu un purpuru un karmezīnu un tām smalkām šķetinātām dzijām, izrotātu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Tie taisīja divus saliekamus plecu gabalus pie tā, abējos viņa galos tie tapa sasieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Un efoda josta, kas pār to bija, tā bija tāds pat darbs, no zelta, ziluma un purpura un karmezīna un smalkām šķetinātām dzijām, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Tie sataisīja arī tos oniksa akmeņus, zelta iekalumos ieliktus, grieztus, tā kā gredzenus, kur Israēla bērnu vārdi bija uzgriezti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Un viņš tos lika efodam uz pašiem pleciem par piemiņas akmeņiem priekš Israēla bērniem, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Un viņš taisīja krūšu glītumu, izrotātu darbu, kā efoda darbu no zelta, ziluma un purpura un karmezīna un smalkām šķetinātām dzijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Tas bija četrkantīgs; tie taisīja to krūšu glītumu divkārtīgu, viens sprīdis bija viņa garums un viens sprīdis viņa platums, divkārtīgs tas bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Un tie to aplika ar četrām akmeņu rindām; vienā kārtā bija sardis, topāzs un smaragds - šī ir tā pirmā kārta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Un otrā kārtā bija rubīns, safīrs un dimants.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Un trešā kārtā bija hiacints, akats un ametists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Un ceturtā kārtā bija krizolits, berils un jaspis zelta iekalumos savās rindās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Un to akmeņu pēc Israēla bērnu vārdiem bija divpadsmit, pēc viņu vārdiem, griezti kā gredzeni, ikviens ar savu vārdu pēc tām divpadsmit ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Tie taisīja pie krūšu glītuma arī ķēdītes, vienā garumā savītas, no tīra zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Un tie taisīja divus zelta iekalumus ar diviem zelta gredzeniem, un lika tos divus gredzenus pie krūšu glītuma diviem galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Un pielika tās savītās ķēdītes tiem diviem gredzeniem pie krūšu glītuma galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Bet abu savīto ķēdīšu otrus galus pielika pie tiem diviem iekalumiem un pie efoda saliekamiem gabaliem priekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Tie taisīja divus zelta gredzenus un tos lika uz tiem diviem otriem krūšu glītuma galiem, pie viņa vīles iekšpusē, efodam pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Vēl tie taisīja divus zelta gredzenus, un tos lika uz efoda abiem plecu gabaliem, apakšā uz to priekšgalu, kur tas top sasprādzēts pār efoda jostu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Un tie piesēja krūšu glītumu ar viņa gredzeniem pie efoda gredzeniem ar vienu pazilu auklu, ka tas būtu pār efoda jostu, ka no efoda nešķirtos, - itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Un viņš darīja efoda uzvalku, austu darbu, visu no ziluma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Un paša uzvalka vidū bija caurums, tā kā krūšu bruņu caurums; šim caurumam bija vīle visapkārt, ka tas neplīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Un pie uzvalka apakšvīlēm tie taisīja granātābolus no ziluma un purpura un karmezīna un šķetinātām smalkām dzijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Tie taisīja arī zvārgulīšus no šķīsta zelta un lika tos zvārgulīšus starp tiem granātāboliem pie uzvalka apakšvīlēm visapkārt starp tiem granātāboliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Ka bija viens zvārgulīts un tad viens granātābols un atkal viens zvārgulīts un viens granātābols pie uzvalka apakšvīlēm visapkārt priekš kalpošanas, - itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Tie taisīja arī svārkus no šķetinātām smalkām dzijām, austu darbu, priekš Ārona un priekš viņa dēliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Un cepuri no dārgām dzijām un paaugstas cepures no smalkām dzijām un linu ūzas no šķetinātām smalkām dzijām');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Un jostu no šķetinātām smalkām dzijām un no ziluma un purpura un karmezīna, izrotātu darbu, itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Tie taisīja arī to zelta platīti, to svēto kroni, no tīra zelta, un uzrakstīja rakstu, itin kā gredzeni top griezti: svēts Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Un piesēja pazilu auklu pie tās, ka tā uz cepures virsas taptu piesieta, itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Tā viss tas darbs tapa pabeigts pie saiešanas telts dzīvokļa. Un Israēla bērni bija darījuši, itin kā Tas Kungs Mozum bija pavēlējis, tā tie bija darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Pēc tam tie atnesa to dzīvokli pie Mozus, to telti un visus viņas rīkus, viņas kāsīšus, viņas galdus, viņas nesamās kārtis, viņas stabus un viņas kājas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Un to segu no pasarkanām aunu ādām un to segu no roņu ādām un to priekškaramo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'To liecības šķirstu un viņa nesamās kārtis un to salīdzināšanas vāku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'To galdu, visus viņa rīkus un tās priekšliekamās maizes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'To zelta lukturi ar viņa eļļas lukturīšiem, kas jāuzliek, un visus viņa rīkus un to eļļu spīdēšanai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Un to zelta altāri un to svaidāmo eļļu un to kvēpināmo no smaržīgām zālēm un to segu priekš telts durvīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'To vara altāri un tos vara traliņus, kas tam bija, viņa nesamās kārtis un visus viņa rīkus, to mazgājamo trauku un viņa kāju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Tās pagalma gardīnes, viņa stabus un viņa kājas un to pagalma vārtu segu, viņa virves un viņa naglas un visus rīkus, ko vajadzēja, pie saiešanas telts dzīvokļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Tās amata drēbes kalpošanai svētā vietā, priestera Ārona svētās drēbes, un viņa dēlu drēbes, ka tie būtu priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Itin kā Tas Kungs Mozum pavēlējis, tā Israēla bērni visu to darbu bija darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Tad Mozus apraudzīja visu to darbu, un redzi, tie to bija darījuši, tā kā Tas Kungs bija pavēlējis, tā tie bija darījuši. Tad Mozus tos svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Un Tas Kungs runāja uz Mozu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Pirmā mēnesī, pirmā mēneša dienā, tev būs uzcelt to dzīvokli, to saiešanas telti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Un tev tur būs nolikt to liecības šķirstu un to priekškaramo uzkārt priekš tā šķirsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Pēc tam tev būs ienest to galdu un sataisīt, kas ir sataisāms, tev arī būs iecelt to lukturi un uzlikt viņa eļļas lukturīšus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Un to zelta kvēpināšanas altāri tev būs likt priekš liecības šķirsta, tad tev būs pakārt dzīvokļa durvju segu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Tev arī būs uzcelt to dedzināmo upuru altāri priekš saiešanas telts dzīvokļa durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Un tev būs likt to mazgājamo trauku starp saiešanas telti un altāri, un tanī turēt ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Pēc tam tev būs uzcelt to pagalmu visapkārt, un to segu pakārt pie pagalma vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Tad tev būs ņemt svaidāmo eļļu un apsvaidīt to dzīvokli un visu, kas tanī ir, un to būs svētīt ar visiem viņa rīkiem, lai tas ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Tev arī būs svaidīt dedzināmo upuru altāri un visus viņa rīkus, un svaidīt to altāri, lai tas altāris ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Tad tev būs svaidīt to mazgājamo trauku un viņa kāju, un to būs svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Tev arī būs pievest Āronu un viņa dēlus priekš saiešanas telts durvīm un tos mazgāt ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Tev būs apvilkt Āronam tās svētās drēbes un viņu svaidīt un viņu svētīt, lai tas ir mans priesteris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Tev arī būs pievest viņa dēlus un tiem apvilkt tos svārkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Un tev tos būs svaidīt, itin kā tu viņu tēvu esi svaidījis, lai tie ir mani priesteri, un tas notiks, ka tiem tā svaidīšana būs par priestera amatu mūžīgi pie viņu pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Un Mozus darīja, itin kā Tas Kungs viņam bija pavēlējis, tā viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Un notikās otrā gadā, pirmā mēnesī, pirmā mēneša (dienā), tad tas dzīvoklis tapa uzcelts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Jo Mozus uzcēla to dzīvokli, un nolika viņa kājas un uzcēla viņa dēļus un ielika viņa aizšaujamos un uzcēla viņa stabus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Un viņš izstiepa to telti pār to dzīvokli un uzlika telts segu tur virsū, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Un viņš ņēma to liecību un ielika šķirstā un nolika tās nesamās kārtis pie tā šķirsta un uzcēla salīdzināšanas vāku uz to šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Un ienesa to šķirstu tai dzīvoklī un uzkāra priekškaramo segu un aizsedza liecības šķirstu, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Un viņš ienesa to galdu saiešanas teltī un nolika to dzīvokļa sānos pret ziemeli, šaipus priekškaramā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Un viņš tās maizes salika kopā priekš Tā Kunga vaiga, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Viņš nolika arī to lukturi saiešanas teltī tam galdam pretī, dzīvokļa sānos pret dienasvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Viņš uzlika tos eļļas lukturīšus priekš Tā Kunga vaiga, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Un viņš nolika to zelta altāri saiešanas teltī priekškaramā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Un viņš uz tā iededzināja kvēpināmo no smaržīgām zālēm, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Un viņš uzkāra arī to segu dzīvokļa durvīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Un viņš lika dedzināmo upuru altāri pie saiešanas telts dzīvokļa durvīm un upurēja uz tā dedzināmu upuri un ēdamu upuri, itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Un mazgājamo trauku viņš nolika starp saiešanas telti un altāri, un ielēja tanī ūdeni priekš mazgāšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Un Mozus, Ārons un viņa dēli tur mazgāja savas rokas un savas kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Kad tie iegāja saiešanas teltī un piegāja pie altāra, tad tie mazgājās, tā kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Un viņš uzcēla arī to pagalmu ap dzīvokli un ap altāri un uzkāra to segu pagalma durvīs. Un Mozus pabeidza visu to darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Tad tās padebesis apklāja saiešanas telti, un Tā Kunga godība piepildīja to dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Un Mozus nevarēja ieiet saiešanas teltī, kamēr tās padebesis uz tās(telts) palika, un Tā Kunga godība piepildīja to dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Un kad tās padebesis no tā dzīvokļa pacēlās, tad Israēla bērni devās ceļā visos savos gājumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Bet kad tās padebesis neuzcēlās, tad tie nedevās ceļā līdz tai dienai, kad tās cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Jo Tā Kunga padebesis bija dienā uz tā dzīvokļa, un naktī tas bija ugunīgs pār viņu priekš visa Israēla nama acīm visos viņu gājumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Un Tas Kungs aicināja Mozu un runāja uz to no saiešanas telts sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Runā uz Israēla bērniem un saki tiem: ja kāds no jums Tam Kungam grib upurēt upuri, tad jums savus upurus būs nest no lopiem, no lieliem un no sīkiem lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ja viņa upuris ir dedzināms upuris no lieliem lopiem, tad būs upurēt vērsi, kas bez vainas; priekš saiešanas telts durvīm viņam to būs upurēt, ka tas Tam Kungam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Un tam savu roku būs likt uz tā dedzināmā upura galvu, ka tas Viņam labi patīk, to salīdzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Tad tam būs nokaut to jauno vērsi Tā Kunga priekšā, un Ārona dēliem, tiem priesteriem, būs tās asinis pienest un tās asinis slacīt visapkārt uz to altāri, kas ir priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Tad tam dedzināmam upurim būs novilkt ādu un viņu sacirst gabalos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Un priestera Ārona dēliem būs uguni iededzināt uz altāra un malku likt uz uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Un Ārona dēliem, tiem priesteriem, tos gabalus, galvu un taukus būs likt virsū uz to malku, kas ir uz tā uguns altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Bet viņa iekšas un viņa kājas tam būs mazgāt ar ūdeni, un priesterim to visu būs iededzināt uz altāra; tas ir dedzināms upuris, uguns upuris Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Un ja viņa upuris ir no sīkiem lopiem, no avīm vai no kazām par dedzināmo upuri, tad tam būs upurēt tēviņu, kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Un viņam to būs nokaut pie altāra sāniem pret ziemeli Tā Kunga priekšā, un Ārona dēliem, tiem priesteriem, būs slacīt viņa asinis visapkārt uz altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Tad viņam to būs sacirst gabalos līdz ar viņa galvu un viņa taukiem, un priesterim to būs likt uz to malku, kas virsū uz uguns altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Bet iekšas un kājas viņam ūdenī būs mazgāt, un priesterim visu to būs pienest un iededzināt uz altāra; šis ir dedzināms upuris, uguns upuris par saldu smaržu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Un ja viņa upuris Tā Kunga priekšā ir dedzināms upuris no putniem, tad viņam savu upuri Tam Kungam būs pienest no ūbelēm vai no jauniem baložiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Un priesterim to būs nest pie altāra un galvu nokniebt un uz altāra iededzināt, un viņa asinis būs izspaidīt pie altāra sienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Un viņa guzu ar viņa spalvām būs atņemt un pie altāra nomest pret rītiem uz pelnu kopu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Un tam to būs ieplēst pie spārniem, ne dalīt, un priesterim to uz altāra būs iededzināt ugunī uz malkas; tas ir dedzināms upuris, uguns upuris Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Ja nu kas laban Tam Kungam grib pienest ēdamu upuri, tad viņa upurim būs būt no kviešu miltiem, un tam būs uzliet eļļu un uzlikt vīraku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Un viņam to būs nest pie Ārona dēliem, tiem priesteriem, tad priesterim būs ņemt pilnu sauju no tiem kviešu miltiem un no viņa eļļas ar visu viņa vīraku un viņa piemiņas tiesu uz altāra iededzināt; tas ir uguns upuris Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Un kas atliek no tā ēdamā upura, pieder Āronam un viņa dēliem; tas ir augsti svēts no Tā Kunga uguns upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Un ja gribi pienest ēdamu upuri no tā, kas ceplī cepts, tad lai tās ir neraudzētas karašas no kviešu miltiem, ar eļļu sajauktas, un neraudzēti rauši ar eļļu aptraipīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Un ja tavs upuris ir ēdams upuris, kas pannā cepts, tad tam būs būt no neraudzētiem, ar eļļu sajauktiem kviešu miltiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Griez to gabalos un lej tur eļļu virsū, tas ir ēdams upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Un ja tavs upuris ir ēdams upuris katlā vārāms, tad to būs sataisīt no kviešu miltiem ar eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Tad tev to ēdamo upurī, kas no tā ir sataisīts, būs nest Tā Kunga priekšā un to būs nest pie priestera, un tam to būs likt uz altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Un priesterim no tā ēdamā upura būs ņemt piemiņas tiesu un uz altāra iededzināt; tas ir uguns upuris Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Bet kas no tā ēdamā upura atliek, pieder Āronam un viņa dēliem; tas ir augsti svēts no Tā Kunga uguns upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nevienam ēdamam upurim, ko jūs Tam Kungam pienesat, nebūs būt raudzētam; jo ne no rauga, ne no medus jums nebūs iededzināt uguns upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Par pirmaju upuri, to Tam Kungam pienesat, bet uz altāri tam nebūs nākt par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Un visus savus ēdamos upurus tev būs sālīt ar sāli, un tava Dieva derības sāls lai nepaliek nost no tava ēdamā upura. Visus savus upurus tev būs upurēt ar sāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Un ja tu Tam Kungam gribi upurēt pirmaju augļu ēdamo upuri, tad tev būs upurēt to pirmaju augļu ēdamo upuri no vārpām, kas pie uguns grauzdētas un smalki sagrūstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Un tev būs uzliet eļļu un tur virsū likt vīraku; tas ir ēdams upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Tad priesterim būs sadedzināt to piemiņas tiesu no viņa sagrūstām vārpām un no viņa eļļas ar visu vīraku; tas ir uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Un ja viņa upuris ir pateicības upuris, ja tas to upurē no lieliem lopiem, lai vērsis, lai govs, tad tam būs upurēt Tā Kunga priekšā tādus, kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Un tam būs likt savu roku uz sava upura galvu un to nokaut priekš saiešanas telts durvīm, un Ārona dēliem, tiem priesteriem, būs slacīt tās asinis visapkārt uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Un no tā pateicības upura lai viņš upurē par Tā Kunga uguns upuri tos taukus, kas iekšas apklāj, un visus taukus, kas ir pie iekšām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Un tās divas īkstis un tos taukus, kas pie tām klātu ir pie gurniem, un aknu taukus; pie īkstīm lai viņš tos noplēš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Un Ārona dēliem uz altāra to būs iededzināt uz tā dedzināmā upura, kas uz malkas uguns virsū, - tas ir uguns upuris Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Un ja viņa sīko lopu upuris ir pateicības upuris Tam Kungam, vai auns, vai avs, tad viņam tādus būs upurēt kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Ja viņš avi pienes par upuri, tad viņam to būs nest Tā Kunga priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Un savu roku būs likt uz sava upura galvu un to nokaut priekš saiešanas telts, un Ārona dēliem būs slacīt viņa asinis uz altāri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Un no pateicības upura tam būs upurēt par uguns upuri Tam Kungam viņa taukus, visu asti, - to viņam pie paša muguras kaula būs nogriezt, - un tos taukus, kas iekšas apklāj, un visus taukus, kas ir pie iekšām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Un abējas īkstis(nieres) un tos taukus, kas tām klātu ir pie gurniem, un aknu taukus; pie īkstīm viņam tos būs noplēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Un priesterim to būs iededzināt uz altāra; tā ir uguns barība Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Un ja viņa upuris ir kaza, tad tam to būs atvest Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Un tam būs likt savu roku uz viņas galvu un viņu nokaut priekš saiešanas telts, un Ārona dēliem būs slacīt viņas asinis uz altāri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Tad viņam no tā savu upuri būs pienest, par uguns upuri Tam Kungam, tos taukus, kas iekšas apklāj, un visus taukus, kas ir pie iekšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Un abējas īkstis un tos taukus, kas tām ir klātu pie gurniem, un aknu taukus; pie īkstīm viņam tos būs noplēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Un priesterim to būs iededzināt uz altāra par uguns barību. Par saldu smaržu ir visi tauki Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Tas lai ir likums mūžam jūsu pēcnākamiem visās jūsu māju vietās, ka jūs neēdat nekādus taukus, nedz asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Runā uz Israēla bērniem un saki: ja kas laban netīši apgrēkojies pret kādu no Tā Kunga baušļiem, ko nebūs darīt, un pret vienu no tiem darījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Ja priesteris, kas ir svaidīts, apgrēkojies, ka viņš tos ļaudis apgrēcina, tad viņam savu grēku dēļ, ko viņš grēkojis, Tam Kungam būs pienest vienu vērsi, jaunu vērsi, kas bez vainas, par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Un tam to vērsi būs vest priekš saiešanas telts durvīm Tā Kunga priekšā, un būs likt savu roku uz tā vērša galvu un to vērsi nokaut Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Un tam svaidītam priesterim būs ņemt no tā vērša asinīm un to nest saiešanas teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Un priesterim būs iemērkt savu pirkstu asinīs, un ar tām asinīm septiņkārt slacināt Tā Kunga priekšā pret svētās vietas priekškaramo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Un priesterim būs likt no tām asinīm arī uz altāra ragiem, kur smaržīgas zāles top kvēpinātas, kas saiešanas teltī ir Tā Kunga priekšā, un tā vērša citas asinis tam būs izliet uz dedzināmo upuru altāra grīdu priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Un grēku upura vērša taukus visus viņam no tā būs atņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Tos taukus, kas iekšas apklāj, un visus taukus, kas ir pie iekšām, un abējas īkstis un tos taukus, kas tām klātu ir pie gurniem, un aknu taukus, to būs noņemt pie īkstīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Itin kā tas top atņemts no pateicības upura vērša; un tam priesterim to būs iededzināt uz dedzināmo upuru altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Bet tā vērša ādu un visu viņa gaļu ar viņa galvu un ar viņa kājām un viņa iekšas un viņa sūdus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Un visu to vērsi būs iznest ārā lēģera priekšā uz šķīstu vietu, kur pelni top izgāzti, un to ar uguni būs sadedzināt uz malkas; pie tiem izgāztiem pelniem to būs sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Un ja visa Israēla draudze netīši apgrēkotos, un tā lieta būtu apslēpta priekš draudzes acīm, un ja tie ko būtu darījuši pret kādu no Tā Kunga baušļiem, ko tiem nebija darīt, un būtu noziegušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Un ja tie grēki, ko tie darījuši, top zināmi, tad draudzei būs atvest vienu vērsi, jaunu vērsi, par grēku upuri un to vest saiešanas telts priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Un draudzes vecajiem būs likt savas rokas uz tā vērša galvu Tā Kunga priekšā un to vērsi nokaut Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Un tam svaidītam priesterim no tā vērša asinīm būs nest saiešanas teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Un priesterim būs iemērkt savu pirkstu, un no asinīm ņemt un septiņkārt slacīt Tā Kunga priekšā pret priekškaramo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Un viņam no tām asinīm būs likt uz altāra ragiem, kas ir priekš Tā Kunga saiešanas telts; tad viņam visas asinis būs izliet uz tā dedzināmo upura altāra grīdu priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Viņam arī būs atņemt visus viņa taukus no tā un tos iededzināt uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Un ar šo vērsi būs darīt, itin kā dara ar grēku upura vērsi; tā ar to būs darīt. Un priesterim tos būs salīdzināt, tad tiem taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Un to vērsi būs ārā vest no lēģera un sadedzināt, itin kā viņš to pirmo vērsi sadedzinājis; tas ir draudzes grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Ja kāds virsnieks netīši apgrēkojās un dara pret kādu no Tā Kunga, sava Dieva, baušļiem, ko nebūs darīt un paliek noziedzīgs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Vai kad viņam tie grēki, ar ko viņš apgrēkojies, top zināmi, tad viņam par upuri būs atvest āzi, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Un būs likt savu roku uz tā āža galvu un to nokaut tai vietā, kur dedzināmo upuri nokauj Tā Kunga priekšā; tas ir grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Un priesterim būs ņemt ar savu pirkstu no tā grēku upura asinīm un likt uz dedzināmo upuru altāra ragiem, tad izgāzt viņa asinis uz dedzināmo upuru altāra grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Bet visus viņa taukus tam būs iededzināt uz altāra, tā kā pateicības upura taukus; tā priesterim būs salīdzināt viņa grēkus, tad tie viņam taps piedoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Un ja kas laban no zemiem ļaudīm netīši apgrēkojās, darīdams pret vienu no Tā Kunga baušļiem, ko tam nebija darīt, un paliek noziedzīgs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Vai kad viņa grēki, ar ko tas apgrēkojies, viņam top zināmi, tad tam būs atvest par upuri jaunu kazu, kas bez vainas, par saviem grēkiem, ko tas darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Un tam savu roku būs likt uz tā grēku upura galvu un to grēku upuri nokaut, kur dedzināma upura vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Tad priesterim būs ņemt ar savu pirkstu no viņa asinīm un likt uz dedzināmo upuru altāra ragiem, un visas viņa asinis izgāzt uz altāra grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Bet visus viņa taukus viņam būs noņemt, itin kā noņem pateicības upura taukus, un priesterim to būs iededzināt uz altāra Tam Kungam par saldu smaržu; tā priesterim viņu būs salīdzināt, tad viņam taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Bet ja viņš avi upurē par grēku upuri, tad tam būs atnest aitiņu, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Un būs likt savu roku uz tā grēku upura galvu un to nokaut par grēku upuri tai vietā, kur nokauj dedzināmos upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Un priesterim no tā grēku upura asinīm būs ņemt ar savu pirkstu un likt uz dedzināmo upuru altāra ragiem un visas viņa asinis izliet uz altāra grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Un visus taukus no tā būs noņemt, tā kā noņem pateicības upura jēra taukus, un priesterim tos būs iededzināt uz altāra, par uguns upuri Tam Kungam; tā priesterim viņu būs salīdzināt par viņa grēku, ko tas darījis, - tad viņam taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Un ja kas laban apgrēkotos, dzirdēdams kādu sazvērestību, par ko viņš ir liecinieks, ja viņš to dzirdējis, vai zina, un to nedara zināmu, tad tam būs nest savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Vai ja kas laban aizskartu kādu nešķīstu lietu, vai tā ir nešķīstu zvēru maita, vai nešķīstu lopu maita, vai nešķīstu tārpu maita, un viņš to nav zinājis, - tomēr viņš ir nešķīsts un noziedzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Vai ja viņš kāda cilvēka nešķīstumu aizskartu, kaut kādu nešķīstumu, ar ko viņš apgānījies, un viņš to nav zinājis, un viņam top zināms, - tad viņš ir noziedzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Vai ja kas laban neapdomīgām lūpām zvērē, ļaunu vai labu darīt, ko vien cilvēks neapdomīgi var zvērēt, un ja to nav zinājis un to atzīst, tad viņš vai nu tā vai tā ir noziedzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Kad nu notiek ka viņš vai šā vai tā noziedzies, tad tam būs izteikt, ar ko tas apgrēkojies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Un atnest par noziedzības upuri Tam Kungam par tiem grēkiem, ko viņš darījis, mātīti no sīkiem lopiem, aitiņu, vai kaziņu, par grēku upuri; tad priesterim viņu būs salīdzināt par to grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Bet ja viņam nav pie rokas, cik par avi vajag, tad par to noziegumu, ko viņš darījis, būs atnest Tam Kungam divas ūbeles vai divus jaunus baložus, vienu par grēku upuri un otru par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Un tos būs nest pie priestera; tam papriekš to būs upurēt, kas ir dots par grēku upuri, un viņa galvu pie pakauša būs nokniebt, bet nenolauzt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Un no tā grēku upura asinīm būs slacīt uz altāra sienu, bet kas atliek no tām asinīm, to būs iztecināt uz altāra grīdu; tas ir grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Un to otru tam būs sataisīt par dedzināmo upuri, kā pienākas; tā priesterim to būs salīdzināt par viņa grēku, ko viņš darījis, - tad viņam taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Bet ja viņam tik daudz nav pie rokas, cik vajag par divām ūbelēm vai diviem jauniem baložiem, tad tam, kas grēkojis, par upuri būs atnest desmito daļu no vienas ēfas kviešu miltu par grēku upuri; tam nebūs eļļas uzliet, nedz vīraka uzlikt, jo tas ir grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'To būs nest pie priestera, un priesterim no tā būs ņemt pilnu sauju par piemiņas tiesu, un to iededzināt uz altāra, par uguns upuri Tam Kungam; - tas ir grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Un priesterim būs viņu salīdzināt par viņa grēku, ko viņš šā vai tā darījis, - tad viņam taps piedots; un tas pieder priesterim, tā kā ēdamais upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Ja kas laban noziedzās un netīši apgrēkojās pie tā, kas Tam Kungam ir svētīts, tad tam par nozieguma upuri būs atnest Tam Kungam aunu, kas bez vainas, no ganāmā pulka, divu sudraba sēķeļu vērtībā pēc svētās vietas sēķeļa, par nozieguma upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Un būs atdot, ko tas pret tām svētām lietām grēkojis, un piekto daļu būs pielikt pārāki un dot priesterim; tā priesterim viņu būs salīdzināt ar to nozieguma upura aunu, - tad viņam taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Un ja kas laban apgrēkotos, darīdams pret kaut kādu no Tā Kunga baušļiem, ko nebūs darīt, un to nav zinājis, tomēr viņš ir noziedzies un viņam būs nest savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Un tam būs nest no ganāmā pulka aunu, kas bez vainas, pie priestera par nozieguma upuri pēc tava sprieduma; un priesterim viņu būs salīdzināt par viņa netīšo apgrēkošanos, ko viņš darījis un pats nebija zinājis, - tad viņam taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Tas ir nozieguma upuris, - viņš noziegdamies bija noziedzies pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Ja kas laban apgrēkotos un pret To Kungu noziegtos un noliegtu savam tuvākam to, kas pie viņa nolikts, vai viņa rokā iedots, vai laupīts, vai ar ko viņš savu tuvāko piekrāpis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Vai kad viņš ko pazudušu atradis un to noliedzis, vai nepatiesi zvērējis kādas lietas dēļ, ko cilvēks dara apgrēkodamies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Kad tas tā apgrēkojies un noziedzies, tad tam būs atdot to laupījumu, ko viņš laupījis vai to, ar ko viņš piekrāpis, vai to nolikto, kas pie viņa nolikts, vai to pazudušo, ko viņš atradis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Vai visu to, par ko viņš nepatiesi zvērējis, to visu viņam būs atdot un piekto daļu pielikt klāt; tam, kam tas pieder, to būs viņam dot sava nozieguma upura dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Un par savu noziegumu tam būs nest Tam Kungam pie priestera no sava ganāmā pulka aunu, kas bez vainas pēc tava sprieduma par nozieguma upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Un priesterim to būs salīdzināt Tā Kunga priekšā, tad viņam taps piedots viss, ko viņš darījis noziegdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Pavēli Āronam un viņa dēliem un saki: šis ir tas dedzināmā upura likums. Šim dedzināmam upurim uz altāra būs degt visu nakti līdz rītam, un ar to altāra uguns paliks degošs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Un priesterim būs apvilkt savas nātnu(linu) drēbes un tās linu ūzas uz savu miesu un saņemt tos pelnus, kad uguns uz altāra sadedzinājis dedzināmo upuri un nobērt tos altārim sānis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Tad viņam būs novilkt savas drēbes un citas drēbes apvilkt, un tos pelnus iznest ārā no lēģera kādā šķīstā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Un ugunij uz altāra tā būs palikt degošam un nebūs izdzist. Tur virsū priesterim ik rītu malku būs iededzināt, un uz to būs likt dedzināmo upuri un uz tā iededzināt pateicības upura taukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Ugunij uz altāra vienmēr būs degt un nebūs izdzist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Šis nu ir tas ēdamā upura likums: Ārona dēliem to būs upurēt priekš Tā Kunga, altāra priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Un būs ņemt pilnu sauju no tā, no ēdamā upura kviešu miltiem un no viņa eļļas, un visu to vīraku, kas uz tā ēdamā upura, un to iededzināt uz altāra, par saldu smaržu, par piemiņu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Un kas no tā atlicies, to būs ēst Āronam un viņa dēliem; neraudzētu to būs ēst svētā vietā, saiešanas telts pagalmā tiem to būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'To nebūs cept ar raugu. Šī ir viņu daļa, ko Es tiem esmu devis no Saviem uguns upuriem; tas ir augsti svēts, itin kā grēku upuris un kā nozieguma upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Visiem vīriešiem starp Ārona dēliem to būs ēst; tas lai ir par likumu uz jūsu pēcnākamiem mūžam, no Tā Kunga uguns upuriem: ikviens, kas tos aizskars, lai ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Šis ir Ārona un viņa dēlu upuris, ko tiem būs upurēt Tam Kungam savā svaidāmā dienā: vienas ēfas desmitā tiesa kviešu miltu dienišķam ēdamam upurim, viena puse rītā un otra puse vakarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'To būs sataisīt pannā ar eļļu, iejauktu tev to būs nest, un tā ēdamā upura ceptos gabalus tev būs upurēt Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Un tam priesterim, kas no viņa dēliem viņa vietā top svaidīts, to būs darīt; tas lai ir likums mūžam; - to būs veselu sadedzināt Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Jo ikkatra priestera ēdamo upuri būs veselu sadedzināt, to nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Runā uz Āronu un uz viņa dēliem un saki: šis ir tas grēku upura likums. Tai vietā, kur dedzināmais upuris top nokauts, būs arī nokaut grēku upuri Tā Kunga priekšā; tas ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Tam priesterim, kas grēku upuri upurē, to būs ēst, svētā vietā to būs ēst, saiešanas telts pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Ikviens kas viņa gaļu aizskar, būs svēts un ja kas no viņa asinīm slacīs uz kādām drēbēm, tad to, ko viņš ir apslacījis, būs mazgāt svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Un to podu, kur tas vārīts, būs sasist; bet ja tas ir vara traukā vārīts, tad to būs berzt un ar ūdeni skalot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Visiem, kas no vīriešu kārtas starp priesteriem, to būs ēst; tas ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Bet visus tos grēku upurus, no kuru asinīm ienes saiešanas teltī par salīdzināšanu svētā vietā, tos nebūs ēst, bet sadedzināt ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Šis nu ir tas nozieguma upura likums; tas ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Tai vietā, kur nokauj dedzināmo upuri, būs arī nokaut nozieguma upuri, un viņa asinis būs slacīt uz altāri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Un visus viņa taukus būs upurēt, asti un taukus, kas iekšas apklāj,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Un abas īkstis un tos taukus pie tām, pie gurniem, un aknu taukus būs noņemt pie īkstīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Un priesterim tos būs iededzināt uz altāra par uguns upuri Tam Kungam; tas ir nozieguma upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Visiem, kas no vīriešu kārtas starp priesteriem, no tā būs ēst; to būs ēst svētā vietā, - tas ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Tā kā grēku upuris, tā būs būt nozieguma upurim, - tiem ir viens likums, tas pieder tam priesterim, kas ar to salīdzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Un tam priesterim, kas upurē kāda dedzināmo upuri, pieder no tā dedzināmā upura, ko viņš upurē, tā āda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Un visi ēdamie upuri, kas ceplī top cepti, ar visu, kas katlā un pannā sataisīts, pieder tam priesterim, kas to upurē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Arī visi ēdamie upuri vai ar eļļu sajauktie, vai sausie, piederēs visiem Ārona dēliem, vienam kā otram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Un šis ir tas likums par to pateicības upuri, ko Tam Kungam upurē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Ja to par pateicību pienes, tad līdz ar to pateicības upuri būs upurēt neraudzētas karašas, kas ar eļļu sajauktas, un neraudzētus raušus, kas ar eļļu aptraipīti, un karašas, kas ar eļļu ir sajauktas no iejautiem kviešu miltiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Līdz ar tām karašām būs pienest saraudzētu maizi par upuri, par pateicības upuri un slavas upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Un vienu karašu no visa tā upura Tam Kungam būs pienest par cilājamu upuri; tas piederēs tam priesterim, kas slaka pateicības upura asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Bet slavas un pateicības upura gaļu būs tai dienā ēst, kad to upurē; no tā nekā nebūs atlicināt līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Un ja viņa upuris ir solījums vai upuris no laba prāta, tad to būs ēst tai dienā, kad to nes, un kas no tā atliek, to būs ēst otrā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Un kas vēl atliek no tā upura gaļas, to būs trešā dienā sadedzināt ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Bet ja kas no sava pateicības upura gaļas ēdīs trešā dienā, tad tas, kas to upurējis, nebūs patīkams, - tas upuris viņam netaps pielīdzināts, tā būs viena negantība, un tam, kas no tā ēdīs, tas būs par noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Un to gaļu nebūs ēst, kas no kāda nešķīstuma aizskarta, to būs sadedzināt ar uguni. To gaļu ikviens var ēst, kas ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Un ja kas laban ēdīs no Tā Kunga pateicības upura gaļas, kamēr nešķīstums pie viņa, tad tam būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Un ja kas laban ko aizskar, kas ir nešķīsts, vai cilvēka nešķīstumu vai kādu nešķīstu lopu vai kādu citu nešķīstu negantību, un ēd no pateicības upura gaļas, kas Tam Kungam pieder, tam būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Runā uz Israēla bērniem un saki: Jums nebūs ēst taukus no vēršiem un jēriem un kazām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Taukus no kādas maitas un taukus no tā, kas saplēsts, jūs varat likt pie visādām lietām, bet jums tos nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Jo ikviens, kas taukus ēdīs no kāda lopa, no kā Tam Kungam upurē uguns upuri, tam, kas to ēdis, būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Jums arī nepavisam nebūs asinis ēst savās mājās, ne no putniem, ne no lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Ikvienam, kas asinis ēd, tam būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Runā uz Israēla bērniem un saki: kas savu pateicības upuri Tam Kungam nes, tam būs atnest, kas Tam Kungam par upuri pienākas no viņa pateicības upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Viņa rokas lai to uguns upuri Tam Kungam nes, tos krūšu taukus lai nes līdz ar tām krūtīm, un to lai līgo par līgojamu upuri Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Un priesterim tos taukus būs iededzināt uz altāra, bet tās krūtis piederēs Āronam un viņa dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Un to labo pleci jums būs dot par cilājamu upuri priesterim no saviem pateicības upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Kurš no Ārona dēliem upurē pateicības upura asinis un taukus, tam tas labais plecs piederēs par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Jo tās krūtis un to cilājamo pleci es esmu ņēmis no Israēla bērniem, no viņu pateicības upura, un tos devis Āronam, tam priesterim, un viņa dēliem par tiesu no Israēla bērniem mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Šī ir Ārona svaidīšanas daļa un viņa dēlu svaidīšanas daļa no Tā Kunga uguns upuriem, tai dienā, kad viņš tos pieveda, palikt par Tā Kunga priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'To Tas Kungs pavēlējis, viņiem dot no Israēla bērniem, tai dienā, kad Viņš tos svaidīja, par tiesu pie viņu pēcnākamiem mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Šis ir dedzināmā upura, ēdamā upura un grēku upura un nozieguma upura un iesvētīšanas upura un pateicības upura likums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Ko Tas Kungs Mozum ir pavēlējis uz Sinaī kalna, kad viņš Israēla bērniem pavēlēja, Tam Kungam upurēt savus upurus Sinaī tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Ņem Āronu un viņa dēlus līdz ar viņu un tās drēbes un to svaidāmo eļļu un to grēku upura vērsi un tos divus aunus un to kurvi ar neraudzētām maizēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Un sapulcē visu draudzi priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Tad Mozus darīja, itin kā Tas Kungs viņam bija pavēlējis, un tā draudze tapa sapulcēta priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Un Mozus sacīja uz to draudzi: šis ir tas vārds, ko Tas Kungs pavēlējis darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Un Mozus pieveda Āronu un viņa dēlus un mazgāja tos ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Tad viņš tam apvilka tos svārkus un viņu apjoza ar to jostu un viņam apvilka to uzvalku un viņam uzlika to plecusegu un viņu apjoza ar tās plecusegas jostu un to ar šo piesēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Un viņam aplika to krūšu glītumu, un tam krūšu glītumam uzlika tos urim un tumim (gaismu un taisnību).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Un viņš uzlika to cepuri viņa galvā un pielika pie tās cepures viņa pieres priekšā to zelta platīti, to svētības kroni, itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Un Mozus ņēma to svaidāmo eļļu un svaidīja to dzīvokli un visu, kas iekš tā bija, un viņš to svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Un viņš no tās slacīja uz altāri septiņreiz un svaidīja altāri un visus viņa rīkus līdz ar to mazgāšanas trauku un viņa kāju, lai (visu) to iesvētītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Un viņš lēja no tās svaidāmās eļļas uz Ārona galvu un to svaidīja, lai to iesvētītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Un Mozus pieveda Ārona dēlus un tiem uzvilka tos svārkus un tos apjoza ar jostām un viņiem uzsēja paaugstas cepures, itin kā Tas Kungs bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Un viņš lika pievest to grēku upura vērsi, un Ārons un viņa dēli uzlika savas rokas uz tā grēku upura vērša galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Un tas tapa nokauts, un Mozus ņēma tās asinis un tās uzlika ar savu pirkstu altāra ragiem visapkārt un šķīstīja altāri, pēc tam viņš izlēja tās asinis uz altāra grīdu un to iesvētīja un salīdzināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Un viņš ņēma visus tos taukus, kas pie iekšām un tos taukus pie aknām un abējas īkstis un viņu taukus, un to iededzināja uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Bet to vērsi ar viņa ādu un viņa gaļu un viņa sūdus viņš sadedzināja ar uguni ārpus lēģera, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Un viņš lika atvest tā dedzināmā upura aunu, un Ārons un viņa dēli uzlika savas rokas uz tā auna galvu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Un tas tapa nokauts, un Mozus slacīja tās asinis ap altāri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Un viņš pārdalīja to aunu viņa gabalos un iededzināja to galvu un tos gabalus un taukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Bet iekšas un kājas viņš mazgāja ar ūdeni, un Mozus iededzināja visu to aunu uz altāra. Tas bija dedzināms upuris par saldu smaržu, uguns upuris Tam Kungam, itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Pēc tam viņš lika atvest to otru aunu, to iesvētīšanas upura aunu, un Ārons ar saviem dēliem uzlika savas rokas uz tā auna galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Un tas tapa nokauts, un Mozus ņēma no viņa asinīm un tās lika uz Ārona labās auss skripstiņu un uz viņa labās rokas īkšķi un uz viņa labās kājas lielo pirkstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Viņš pieveda arī Ārona dēlus un lika no tām asinīm uz viņu labās auss skripstiņu un uz viņu labās rokas īkšķi un uz viņu labās kājas lielo pirkstu un slacīja tās asinis ap altāri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Un viņš ņēma tos taukus un to asti un visus taukus, kas ir pie iekšām, un tos taukus pie aknām un abējas īkstis un viņu taukumu un to labo pleci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Un viņš ņēma arī neraudzētas maizes no tā kurvja, kas bija Tā Kunga priekšā, vienu neraudzētu karašu un vienu ar eļļu ceptu karašu un vienu rausi un lika tos uz tiem taukiem un uz to labo pleci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Un viņš lika visu to uz Ārona rokām un uz viņa dēlu rokām un līgoja to par līgojamu upuri Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Pēc tam Mozus to ņēma no viņu rokām un to iededzināja uz dedzināmo upuru altāra; tas bija iesvētīšanas upuris par saldu smaržu, tas bija uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Un Mozus ņēma tās krūtis un tās līgoja par līgojamu upuri Tā Kunga priekšā no tā iesvētīšanas upura auna; tās bija Mozum par daļu, itin kā Tas Kungs viņam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Un Mozus ņēma arī no tās svaidāmās eļļas un no tām asinīm, kas bija uz altāra, un to slacīja uz Āronu un viņa drēbēm un uz viņa dēliem un uz viņa dēlu drēbēm arīdzan, un iesvētīja Āronu un viņa drēbes un viņa dēlus un viņa dēlu drēbes arīdzan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Un Mozus sacīja uz Āronu un uz viņa dēliem: vāriet to gaļu priekš saiešanas telts durvīm un ēdiet to turpat līdz ar to maizi, kas ir iesvētīšanas upura kurvī, itin kā man pavēlēts un sacīts. Āronam un viņa dēliem to būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Bet kas atliek no tās gaļas un no tās maizes, to jums būs ar uguni sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Jums arī nebūs iziet no saiešanas telts durvīm septiņas dienas, līdz tai dienai, kad jūsu iesvētīšanas upura dienas beidzās, jo septiņas dienas jūsu rokas taps pildītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Itin kā tas šinī dienā ir darīts, tā Tas Kungs pavēlējis to darīt, lai jūs topat salīdzināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Jums tad priekš saiešanas telts durvīm būs palikt dienu un nakti septiņas dienas un turēt Tā Kunga likumu, ka jūs nemirstat; jo tā tas man ir pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Un Ārons un viņa dēli darīja visu to, ko Tas Kungs caur Mozu bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Un astotā dienā Mozus sauca Āronu un viņa dēlus un Israēla vecajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Un viņš sacīja uz Āronu: ņem jaunu teļu par grēku upuri un aunu par dedzināmo upuri, kas ir bez vainas, un atved tos Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Pēc tam runā uz Israēla bērniem un saki: ņemiet āzi par grēku upuri un teļu un jēru, kas gadu veci un bez vainas, par dedzināmo upuri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Un vērsi un aunu par pateicības upuri, Tā Kunga priekšā upurēt, un ēdamu upuri ar eļļu sajauktu, jo šodien jums Tas Kungs parādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Tad tie ņēma, ko Mozus bija pavēlējis, un to noveda pie saiešanas telts, un visa draudze piegāja un stāvēja Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Un Mozus sacīja: šo lietu, ko Tas Kungs pavēlējis, jums būs darīt, tad Tā Kunga godība jums parādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Un Mozus sacīja uz Āronu: pieej pie altāra un sataisi savu grēku upuri un savu dedzināmo upuri un dari salīdzināšanu priekš sevis un priekš tiem ļaudīm, pēc upurē to ļaužu upuri un salīdzini tos, itin kā Tas Kungs pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Tad Ārons piegāja pie altāra un nokāva grēku upura teļu priekš sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Un Ārona dēli pienesa tās asinis pie viņa, un viņš savu pirkstu iemērca tanīs asinīs un lika tās uz altāra ragiem, pēc tam viņš izlēja tās asinis uz altāra grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Bet taukus un īkstis un taukus no aknām pie tā grēku upura viņš iededzināja uz altāra, itin kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Un gaļu un ādu viņš sadedzināja ar uguni ārpus lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Pēc tam viņš nokāva to dedzināmo upuri, un Ārona dēli nesa tās asinis pie viņa un to slacīja ap altāri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Un tie pienesa pie viņa to dedzināmo upuri savos gabalos ar to galvu, un viņš to iededzināja uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Un viņš mazgāja tās iekšas un tās kājas un tās iededzināja virs tā dedzināmā upura uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Pēc tam viņš pienesa to ļaužu upuri un ņēma to grēku upura āzi, kas bija priekš tiem ļaudīm, un to nokāva un to sataisīja par grēku upuri, tā kā to pirmo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Un viņš pieveda to dedzināmo upuri un to sataisīja pēc tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Un viņš pienesa to ēdamo upuri un ņēma no tā pilnu sauju un to iededzināja uz altāra, vēl klāt pie tā rīta dedzināmā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Pēc tam viņš nokāva to vērsi un to aunu par pateicības upuri priekš tiem ļaudīm. Un Ārona dēli pienesa tās asinis pie viņa, un viņš tās slacīja ap altāri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Un tos taukus no tā vērša un no tā auna to asti, un kas iekšas apklāj, un tās īkstis un tos aknu taukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Un tie lika tos taukus uz tām krūtīm, un viņš iededzināja tos taukus uz altāra,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Bet tās krūtis un to labo pleci Ārons līgoja par līgojamu upuri Tā Kunga priekšā, tā kā Mozus bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Pēc tam Ārons pacēla savu roku uz tiem ļaudīm un tos svētīja, un nokāpa, kad bija beidzis grēku upuri un dedzināmo upuri un pateicības upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Un Mozus un Ārons gāja saiešanas teltī; pēc tie nāca ārā un svētīja tos ļaudis. Un Tā Kunga godība parādījās visiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Jo uguns izgāja no Tā Kunga un aprija uz altāra to dedzināmo upuri un tos taukus; un visi ļaudis to redzēja un gavilēja un krita uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Un Ārona dēli Nadabs un Abijus ņēma ikviens savu kvēpināmo trauku un ielika uguni un kvēpināmās zāles tur virsū un nesa svešu uguni Tā Kunga priekšā, ko viņš tiem nebija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Tad uguns izgāja no Tā Kunga un tos aprija, un tie nomira Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Un Mozus sacīja uz Āronu: tas ir, ko Tas Kungs ir runājis sacīdams: “Iekš tiem, kas Man tuvu, Es tapšu svētīts un visu ļaužu priekšā Es tapšu godināts.” Bet Ārons cieta klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Un Mozus aicināja Mišaēli un Elcafanu, Ūziēļa, Ārona tēva brāļa, dēlus, un tiem sacīja: pieejat un nesiet savus brāļus projām no svētās vietas ārā aiz lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Tad tie piegāja un iznesa tos ar viņu šauriem svārkiem ārā aiz lēģera, kā Mozus bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Un Mozus sacīja uz Āronu un Eleazaru un Ītamaru, viņa dēliem: jums nebūs savas galvas atsegt nedz savas drēbes saplēst, lai jūs nemirstat, un lai dusmība nenāk pār visu draudzi; bet jūsu brāļiem, visam Israēla namam, būs apraudāt šo uguns sodību, ko Tas Kungs iededzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Jums no saiešanas telts durvīm arī nebūs iziet, ka jūs nemirstat; jo Tā Kunga svaidāmā eļļa ir uz jums. Un tie darīja pēc Mozus vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Un Tas Kungs runāja uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vīnu un stipru dzērienu tev nebūs dzert, ne tev, ne taviem dēliem, kad ejat saiešanas teltī, lai jūs nemirstat; tas lai ir par likumu uz jūsu pēcnākamiem mūžīgi; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Lai jūs varat izšķirt svētu no nesvēta un nešķīstu no šķīsta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Un lai jūs Israēla bērniem varat mācīt visus likumus, ko Tas Kungs uz tiem ir runājis caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Un Mozus runāja uz Āronu un uz Eleazaru un uz Ītamaru, viņa atlikušiem dēliem: ņemiet to ēdamo upuri, kas no Tā Kunga uguns upuriem atlicis un ēdiet to neraudzētu pie altāra, jo tas ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Tāpēc jums to būs ēst svētā vietā, jo tā ir tava nospriestā daļa un tavu dēlu nospriestā daļa no Tā Kunga uguns upuriem, jo tā man ir pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Un tās līgotās krūtis un to cilāto pleci jums būs ēst šķīstā vietā, tev un taviem dēliem un tavām meitām līdz ar tevi, jo tā ir tava nospriestā daļa, un tavu dēlu nospriestā daļa un dota no Israēla bērnu pateicības upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'To cilājamo pleci un tās līgojamās krūtis tiem būs pienest pie tauku uguns upura, ka tie top līgoti par līgojamu upuri Tā Kunga priekšā; tas lai ir tev un taviem dēliem arīdzan par tiesu mūžīgi, tā kā Tas Kungs pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Un Mozus meklēt meklēja to grēku upura āzi, un redzi, tas bija sadedzināts; un viņš apskaitās par Eleazaru un par Ītamaru, Ārona atlikušiem dēliem, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Kāpēc jūs to grēku upuri neesat ēduši svētā vietā? Jo tas ir augsti svēts, un viņš jums to ir devis, lai jūs nesat draudzes noziedzību, to salīdzinādami Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Redzi, viņa asinis nav iekšā ienestas tai svētā vietā; jums tas bija jāēd svētā vietā, kā tas man pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Tad Ārons runāja uz Mozu: redzi šodien tie savu grēku upuri un savu dedzināmo upuri ir atnesuši Tā Kunga priekšā, un tādas lietas man ir notikušas; ja tad es šodien to grēku upuri būtu ēdis, - vai tas Tam Kungam būtu paticis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Kad Mozus to dzirdēja, tad tas viņam patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Un Tas Kungs runāja uz Mozu un uz Āronu un uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Runājiet uz Israēla bērniem un sakāt: šie ir tie lopi, ko jūs varat ēst no visiem lopiem, kas virs zemes:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Visus lopus, kam šķelti nagi, kam nagi šķelti divējos gabalos, un kas gremo, tos ēdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Bet šos jums nebūs ēst no tiem, kas gremo un kam šķelti nagi: kamieļi, jo tas gan gremo, bet tam nav šķelti nagi; to jums būs turēt par nešķīstu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Un trusi, jo tas gan gremo, bet tam nav šķelti nagi, to jums būs turēt par nešķīstu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Un zaķi, jo tas gan gremo, bet tam nav šķelti nagi, to jums būs turēt par nešķīstu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Un cūku, jo tai gan šķelti nagi un šķelti divējos gabalos, bet tā negremo, to jums būs turēt par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'No viņu gaļas jums nebūs ēst nedz viņu maitas aizskart, tos jums būs turēt par nešķīstiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Šos ēdat no visa, kas ūdenī: visu, kam ir spuras un zvīņas ūdenī, jūrā un upēs, to varat ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Bet visu, kam nav spuru un zvīņu ūdenī un upē, no visa, kas ūdenī kust, un no visa, kas dzīvo ūdenī, to jums būs turēt par negantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'To jums būs turēt par negantu, jums no viņu gaļas nebūs ēst, un viņu maitas jums būs turēt par negantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Visu, kam nav spuru un zvīņu ūdenī, jums būs turēt par negantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Un no putniem šos jums būs turēt par negantiem, ka jūs tos neēdat: šie lai jums ir neganti: ērglis un sarkandzeltenais ērglis un melnais ērglis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Un lija un vanags pēc savas kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Un visi kraukļi pēc savas kārtas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Un strauss un bezdelīga un ķīris un vēja vanags pēc savas kārtas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Un apogs un maitas lija un ūpis');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Un pūce un dumpis un gulbis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Stārķis, kalnu vanags pēc savas kārtas, badadzeguze un sikspārnis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Visi spārnainie līdēji, kas iet uz četrām kājām, lai jums ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Bet tos ēdat no visiem spārnainiem līdējiem, kas uz četrām kājām iet; kam augšām pie savām kājām ir lieli, ar ko tie pa zemi lēkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Šos no tiem ēdat: siseni pēc viņa kārtas un zolamu pēc viņa kārtas un argolu pēc viņa kārtas un agabu pēc viņa kārtas (zolams, argols un agabs ir siseņu kārtas).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Visus citus spārnaiņos līdējus, jums būs turēt par negantiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Un caur šiem jūs tapsiet apgānīti; ikviens, kas viņu maitas aizskar, būs nešķīsts līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Un kas no viņu maitām ko nesīs, tam būs mazgāt savas drēbes un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Visus lopus, kam nagi šķelti, bet nav šķelti divējos gabalos un kas negremo, tos jums būs turēt par nešķīstiem; kas tos aizskar, tam būs būt nešķīstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Un visiem četrkājīgiem zvēriem, kam kājas ar asiem nagiem, tie lai jums ir nešķīsti; kas viņu maitas aizskar, tas būs nešķīsts līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Un kas viņu maitas ir nesis, tam savas drēbes būs mazgāt un nešķīstam būt līdz vakaram; tie lai jums ir nešķīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Un starp tiem līdējiem, kas virs zemes lien, šie lai jums ir nešķīsti: sērmulis, pele, bruņurupucis pēc savas kārtas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Sesks, hameleons, ķirzaka, gliemezis un kurmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Tos no visiem līdējiem jums būs turēt par nešķīstiem; kas tos aizskar, kad tie miruši, tam būs nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Un uz ko kas no tiem kritīs, kad tie ir miruši, tam būs nešķīstam būt, lai tas ir kāds koku trauks, vai drēbes, vai āda, vai maiss, vai kāds rīks, ar ko kāds darbs top darīts, - to būs ūdenī iebāzt un tam būs nešķīstam būt līdz vakaram, pēc tas būs šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Un ikvienu mālu trauku, kur kas no tiem ir iekritis, - visam, kas tur iekšā, būs nešķīstam būt, un jums to būs sadauzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Ikvienam ēdienam, kas top ēsts, uz ko šis ūdens ir nācis, būs nešķīstam būt, un ikvienu dzērienu, kas top dzerts no visiem tādiem traukiem, būs turēt par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Un visu, uz ko viņu maitas kritīs, to būs turēt par nešķīstu, cepli un traukus būs sadauzīt, tie ir nešķīsti; tāpēc jums tos būs turēt par nešķīstiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Tikai avoti un akas un dīķi būs šķīsti; bet kas viņu maitas aizskar, to būs turēt par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Un ja kas no viņu maitām kritīs uz sēklu, kas ir sējama, tā ir šķīsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Bet ja ūdens top liets pār sēklu, un tad kas no tādām maitām uzkrīt, tad jums to būs turēt par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Ja kāds lops mirst, kas jums ir par barību, - kas viņa maitu aizskar, tam būs nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Un kas no viņa maitas ir ēdis, tam būs savas drēbes mazgāt un nešķīstam būt līdz vakaram; un kas viņu maitu nes, tam būs savas drēbes mazgāt un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Un visu, kas lien virs zemes, jums būs turēt par negantu, to nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Visu, kas uz sava vēdera lien, un visu, kas virs zemes lien uz četrām kājām, līdz ar visu, kam daudz kājas, to jums nebūs ēst; lai tas jums ir negants.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Neapgānāt savas dvēseles ar nekādiem līdējiem, kas lien, un nedariet sevi nešķīstus pie tiem, ka jūs caur tiem netopat apgānīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Jo Es esmu Tas Kungs, jūsu Dievs, tāpēc jums būs svētīties un svētiem būt, jo Es esmu svēts; un jums nebūs savas dvēseles apgānīt ar neko, kas lien virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Jo Es esmu Tas Kungs, kas jūs izvedis no Ēģiptes zemes, lai Es jums esmu par Dievu; tad esat svēti, jo Es esmu svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Šis ir tas likums par lopiem un putniem un par visām dzīvām dvašām, kas kust ūdenī, un par visām dvašām, kas lien virs zemes, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Ka jūs varat izšķirt nešķīstu no šķīsta, un putnus, kas ēdami, no putniem, kas nav ēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Runā uz Israēla bērniem un saki: kad kāda sieva top grūta un dzemdē dēliņu, tad tai septiņas dienas būs nešķīstai būt; cik ilgi tā savu sārņu dēļ ir atšķirta, tik ilgi tai būs nešķīstai būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Un astotā dienā viņa priekšādas miesu būs apgraizīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Un trīsdesmit un trīs dienas tai būs palikt iekš savas asins šķīstīšanās; tai nebūs aizskart nekādu svētu lietu, nedz nākt tai svētā vietā, tiekams viņas šķīstīšanās dienas pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Bet ja viņa meitiņu dzemdēs, tad tai divas nedēļas būs nešķīstai būt, cik ilgi viņas atšķiršana ir, pēc tam viņai sešdesmit sešas dienas būs palikt iekš savas šķīstīšanās asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Un kad viņas šķīstīšanās dienas priekš dēla vai priekš meitas ir pagalam, tad viņai gada vecu jēru par dedzināmo upuri un jaunu balodi jeb ūbeli par grēku upuri būs atnest priekš saiešanas telts durvīm pie priestera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Tam to būs upurēt Tā Kunga priekšā un viņu salīdzināt; tad tā taps šķīsta no saviem asins sārņiem. Šis ir tas likums priekš tās, kas dēliņu vai meitiņu dzemdē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Bet ja viņai nav pie rokas, cik par jēru nākas, tad lai viņa ņem divas ūbeles jeb divus jaunus baložus, vienu par dedzināmo upuri un vienu par grēku upuri, un priesterim būs viņu salīdzināt, tad viņa taps šķīsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Kad kāda cilvēka miesas ādā metās tūkums vai augonis vai balta pūte, tā kā viņa miesas ādā būtu spitālības vaina, tad to būs vest pie priestera Ārona vai pie viena no viņa dēliem, tiem priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Un priesterim būs apraudzīt viņa miesas ādas vainu; ja tie mati tai vainā palikuši balti, un tā vaina dziļāka izraugās nekā viņa miesas āda, tad tā ir spitālības vaina; kad priesteris to apraudzījis, tad viņam to būs spriest par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Bet ja tā pūte viņa miesas ādā ir balta, bet dziļaka neizraugās nekā tā āda, un tie mati tai vainā nav tapuši balti, tad priesterim to, kam tā vaina, būs ieslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Un priesterim septītā dienā to atkal būs apraudzīt, un redzi, ja tā vaina pēc viņa aplūkošanas tāda pat ir palikusi un viņa ādas vaina nav izpletusies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Tad priesterim viņu vēl būs ieslēgt septiņas dienas. Un priesterim atkal viņu būs apraudzīt septītā dienā, un redzi, ja tā vaina ādā nav izpletusies, tad priesterim to būs atzīt par šķīstu; tas bija kašķis; un tam būs mazgāt savas drēbes, - tad viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Bet ja tas kašķis pār ādu ir izpleties, pēc tam, ka tas no priestera ir apraudzīts un par šķīstu nosaukts, tad priesterim otrreiz to būs apraudzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Ja nu priesteris redz, un raugi, tas kašķis ādā ir izpleties, tad priesterim viņu būs atzīt par nešķīstu, - tie ir spitāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Ja spitāļi būs pie kāda cilvēka, tad to būs vest pie priestera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Tad priesteris redzēs, un raugi, ja balts tūkums ir ādā, kas matus pārvērtis par baltiem, un jēla gaļa ir tai tūkumā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Tie ir veci spitāļi viņa miesas ādā, tāpēc priesterim viņu būs spriest par nešķīstu; tam to nebūs ieslēgt, jo tas ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Un ja spitāļi ādā izsitās, un spitāļi tam, kam tā vaina, visu ādu ir apklājuši no galvas līdz kājām, cik priestera acis redz,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Un priesteris redz, un raugi, spitāļi visu viņa miesu apklājuši, tad viņam to, kam tā vaina, būs atzīt par šķīstu; tā ir visa balta tapusi, - viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Bet kad jēla gaļa iekš tās top redzēta, tad tam būs nešķīstam būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Un kad priesteris to jēlo gaļu redz, tad viņam to būs spriest par nešķīstu; tā jēlā gaļa ir nešķīsta, tie ir spitāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Bet ja tā jēlā gaļa pārvērtīsies un paliks balta, tad lai viņš nāk pie priestera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Un priesteris viņu aplūkos, un redzi, ja tā vaina ir tapusi balta, tad priesterim to, kam tā vaina, būs atzīt par šķīstu, jo viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Un ja miesas ādā kāds augonis ir bijis, kas ir sadzijis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Un tai augoņa vietā ceļas balta pūte vai balta pasarkana rēta, tad viņam būs rādīties priesterim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Un priesteris redzēs, un raugi, ja viņa rādās dziļāka nekā tā āda, un kad viņas mati tapuši balti, tad priesterim viņu būs atzīt par nešķīstu; tie ir spitāļi, caur to augoni tie ir izsitušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Bet ja priesteris to apraudzīs, un redzi, tur nav balti mati un tā nav dziļāka nekā tā āda, bet ir palikusi bāla, tad priesterim viņu būs ieslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Ja tad viņa ir izpletusies pār ādu, tad priesterim viņu būs atzīt par nešķīstu; tā ir (spitālības) vaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Bet ja tā baltā pūte paliks savā vietā un neizpletīsies, tad tā ir plēve no tā augoņa, un priesterim viņu būs atzīt par šķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Vai ja miesas ādā ir bijis kāds uguns degums, un tai sadzijušā degumā ir balti pasarkana vai balta pūte,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Un priesteris to redz, un raugi, tie mati uz tā deguma tapuši balti, un viņš dziļāks izraugās nekā tā āda, tad tie ir spitāļi; tie caur to degumu ir izsitušies, un priesterim viņu būs atzīt par nešķīstu, jo tā ir spitālības vaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Bet ja priesteris to aplūkos, un redzi, uz rētas nav baltu matu, un tā nav dziļāka nekā tā āda un ir palikusi bāla, tad priesterim viņu būs ieslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Un septītā dienā priesterim viņu būs apraudzīt: ja tā ir ādā izpletusies, tad priesterim viņu būs turēt par nešķīstu; tā ir spitālības vaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Bet ja tā plēve savā vietā paliks un ādā neizpletīsies, bet palikusi bāla, tad tas ir tā deguma tūkums; tāpēc priesterim viņu būs atzīt par šķīstu, jo tā ir tā deguma plēve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Un ja kādam vīram vai kādai sievai vaina metās galvā vai bārdā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Tad priesterim to vainu būs aplūkot, un redzi, ja viņa dziļāka izraugās nekā tā āda, un mati iekš tās iedzelteni plāni, tad priesterim to būs atzīt par nešķīstu, - tas ir kašķis, tie ir galvas jeb bārdas spitāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Bet ja priesteris to kašķa vainu aplūkos, un redzi, tā dziļāka neizraugās nekā tā āda, un nekādu melnu matu uz tās nav, tad priesterim to, kam tā kašķa vaina, būs ieslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Un septītā dienā priesterim to vainu būs aplūkot, un redzi, ja tas kašķis nav izpleties un uz tā nav nekādu iedzeltenu matu un tas kašķis arī neizraugās dziļāks nekā tā āda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Tad tam matus būs nodzīt, bet ne pa to kašķi, un priesterim to, kam tā vaina, būs ieslēgt vēl septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Un septītā dienā priesterim to kašķi būs aplūkot, un redzi, ja tas kašķis nav izpleties pār ādu, nedz izraugās dziļāks nekā tā āda, tad priesterim to būs turēt par šķīstu; tam savas drēbes būs mazgāt un šķīstam būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Bet ja tas kašķis ir izpleties pār ādu pēc viņa šķīstīšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Tad priesterim viņu būs aplūkot un redzi, ja tas kašķis ir izpleties pār ādu, tad priesterim vairs nebūs meklēt tos iedzeltenos matus; viņš ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Bet ja tas kašķis pēc viņa apraudzīšanas tāds pat ir palicis un melni mati uz tā ir auguši, tad tas kašķis ir sadzijis; viņš ir šķīsts, un priesterim viņu būs atzīt par šķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Un ja kādam vīram vai kādai sievai pie viņu miesas ādas metās baltas pūtes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Un priesteris to aplūko, un redzi, viņu miesas ādā ir bālas baltas pūtes, tad tas ir kraupis; tas iekš ādas ir izsities, - viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Un ja kādam vīram galvas mati izkrīt, ka tā paliek plika, - viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Un ja uz viņa galvas priekšas mati ir izkrituši, tad viņš ir plikgalvis, viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Bet ja tai plikumā jeb pleiķī metās balta pasarkana vaina, tad tie ir spitāļi, kas izsitās pie viņa plikuma jeb pleiķa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Un kad priesteris viņu ir aplūkojis, un viņa vainas tūkums viņa plikumā jeb pleiķī ir balti pasarkans, un izraugās tā kā spitāļi miesas ādā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Tad tas vīrs ir spitālīgs, viņš ir nešķīsts, priesterim viņu būs atzīt par nešķīstu, uz viņa galvas ir (spitāļu) vaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Un kas ir spitālīgs, kam šī vaina, tam būs saplēst drēbes un atsegt galvu, un aizsegt savas lūpas un saukt: nešķīsts! nešķīsts!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Visu to laiku, kamēr viņam tā vaina, tam būs būt nešķīstam; tam būs atšķirtam dzīvot, ārā aiz lēģera lai ir viņa māju vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Un ja tie spitāļi būs pie drēbēm, pie vilnainām drēbēm vai pie nātnu drēbēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Lai tie ir pie adītām vai austām, lai pie nātnu vai vilnainām (drēbēm), lai pie kādas ādas vai pie kā, kas no ādām taisīts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Un ja tā vaina pie drēbēm vai pie ādas vai pie adītām vai austām vai pie kā, kas no ādām taisīts, ir zaļgana vai pasarkana: tad tie ir spitāļi, un tos būs priesterim rādīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Un priesterim to vainu būs apraudzīt, un to, kam tā vaina, būs ieslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Un septītā dienā to vainu būs apraudzīt, ja tā vaina ir izpletusies pie drēbēm, vai pie adītām vai pie austām vai pie ādas vai pie kā, kas no ādas taisīts, tad tā ir ēdoti(ļaundabīga) spitālības vaina, - tas ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Un tās drēbes, vai tos apmeslus vai tos audus, tik labi no vilnainām kā no nātnu drēbēm un visu to, kas no ādām taisīts, kur tā vaina radās, to būs sadedzināt, jo tā ir ēdoti spitālības vaina, - to būs ar uguni sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Un ja priesteris lūkos un redzēs, ka tā vaina pie drēbēm vai adītām vai austām vai pie kā, kas no ādām taisīts, nav izpletusies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Tad priesterim būs pavēlēt, ka tas, pie kā tā vaina, top mazgāts, un otrā kārtā to būs ieslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Un kad tas ir mazgāts, tad priesterim to vainu būs aplūkot, un redzi, ja tā vaina pēc izskata nav pārvērtusies un tā vaina nav izpletusies, tad tas ir nešķīsts; jums to ar uguni būs sadedzināt, jo tā ir ēdoti vaina, - lai būtu no iekš vai ārpuses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Bet ja priesteris lūkos un redzi, tā vaina pēc viņas mazgāšanas ir nobālējusi, tad tam to būs noplēst no drēbēm vai no ādas vai no adītām vai no austām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Bet ja tas vēl top ieraudzīts pie drēbēm vai adītām vai austām vai pie kā, kas no ādām taisīts, tad tie ir spitāļi, kas izsitās; to, pie kā tā vaina, jums būs sadedzināt ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Bet drēbes vai apmeslus vai audus vai to, kas no ādām taisīts, ko jūs esat mazgājuši, kad tā vaina no tā atstājās, tad jums to otrā kārtā būs mazgāt, un tas ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Šis ir tas likums par spitālības vainu pie vilnainām vai nātnu drēbēm vai adītām vai austām vai pie kaut kā, kas no ādām taisīts, to turēt vai par šķīstu vai par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Šis būs tas likums par spitālīgo viņa šķīstīšanas laikā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'To būs vest pie priestera, un priesterim būs iziet ārā aiz lēģera, un ja priesteris redz, un raugi, spitālības vaina no spitālīgā ir sadzijusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Tad priesterim būs pavēlēt, ka priekš tā, kas jāšķīstī, būs ņemt divus dzīvus šķīstus putnus un ciedra koku un sarkanus dzīparus un īzapu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Un priesterim būs pavēlēt, ka tas viens putns top nokauts iekš kāda māla trauka pār tekošu ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'To dzīvo putnu viņam tad būs ņemt un to ciedra koku un tos sarkanos dzīparus un to īzapu, un tos līdz ar to dzīvo putnu būs iemērcēt tā otra putna asinīs, kas ir nokauts pār to tekošo ūdeni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Un to, kas no spitāļiem šķīstās, būs septiņreiz apslacīt un šķīstīt, un to dzīvo putnu palaist laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Un tam, kas šķīstās, būs mazgāt savas drēbes un nocirpt visus savus matus un ūdenī mazgāties, tad tas būs šķīsts; pēc tam lai viņš nāk lēģerī, bet lai paliek sava dzīvokļa ārpusē septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Septītā dienā tam būs nodzīt savus matus, savu galvu un savu bārdu, to spalvu savās uzacīs; visus savus matus tam būs nodzīt un savas drēbes mazgāt un savu miesu ar ūdeni mazgāt, tad tas būs šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Un astotā dienā tam būs ņemt divus jērus, kas bez vainas, un gada vecu aitiņu, kas bez vainas, līdz ar trim desmitiem kviešu miltu par ēdamo upuri, ar eļļu sajauktu, un vienu logu(glāze) eļļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Tad tam priesterim, kas šķīsti, to vīru, kas šķīstās, līdz ar tām lietām būs stādīt Tā Kunga priekšā, priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Un priesterim būs ņemt to vienu jēru un to upurēt par nozieguma upuri ar to logu (glāze) eļļas, un par līgojamu upuri to upurēt Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Tad viņam to jēru būs nokaut tai vietā, kur top nokauts tas grēku upuris un dedzināmais upuris, svētā vietā, jo tas nozieguma upuris pieder tāpat kā tas grēku upuris priesterim; tas ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Un priesterim būs ņemt no tā nozieguma upura asinīm, un to būs likt uz labās auss skripstiņu tam, kas jāšķīstī, un uz viņa labās rokas īkšķi un uz viņa labās kājas lielo pirkstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Un priesterim arī būs ņemt eļļu no tā loga un liet savā kreisā saujā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Un būs iemērcēt savu labo pirkstu tai eļļā, kas kreisajā saujā, un ar savu pirkstu no tās eļļas septiņreiz slacīt Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Un no tās atlikušās eļļas, kas viņa saujā, priesterim būs likt uz labās auss skripstiņu tam, kas jāšķīstī, un uz viņa labās rokas īkšķi un uz viņa labās kājas lielo pirkstu virsū uz tām nozieguma upura asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Un kas vēl atlicis no tās eļļas, kas bija priestera saujā, to viņam būs likt uz galvu tam, tas jāšķīstī; tā priesterim viņu būs salīdzināt Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Un priesterim arī būs sataisīt grēku upuri un to šķīstīto salīdzināt viņa nešķīstības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Tad viņam būs nokaut to dedzināmo upuri un to dedzināmo upuri un to ēdamo upuri būs celt uz altāri; tā priesterim viņu būs salīdzināt, tad tas ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Bet ja viņš ir nabags un viņam maz pie rokas, tad lai ņem vienu jēru nozieguma upurim par līgojamu upuri, sevi salīdzināt, un desmito tiesu kviešu miltu ar eļļu sajauktu par ēdamu upuri un vienu logu (glāze) eļļas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Un divas ūbeles jeb divus jaunus baložus, cik viņa roka paspēj; no tiem lai ir viens par grēku upuri un otrs par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Un astotā šķīstīšanas dienā tos būs nest pie priestera, pie saiešanas telts durvīm Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Un priesterim būs ņemt to nozieguma upura jēru un to logu (glāze) eļļas, un tos būs līgot par līgojamu upuri Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Tad nozieguma upura jēru būs nokaut un ņemt no nozieguma upura asinīm, un to likt uz labās auss skripstiņu tam, kas šķīstās un uz viņa labās rokas īkšķi un uz viņa labās kājas lielo pirkstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Un priesterim no tās eļļas būs liet savā kreisajā saujā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Un no tās eļļas, kas kreisajā saujā, priesterim septiņreiz būs slacīt Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Un no tās eļļas, kas viņa saujā, priesterim būs likt uz labās auss skripstiņu tam, kas šķīstās, un uz viņa labās kājas lielo pirkstu, virsū uz tām nozieguma upura asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Un to atlikumu no tās eļļas, kas priestera saujā, būs likt uz galvu tam, kas šķīstās, par salīdzināšanu Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Tad viņam būs sataisīt vienu no tām ūbelēm jeb no tiem jauniem baložiem, cik viņa roka paspēj,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Cik viņa roka paspēj, vienu par grēku upuri un otru par dedzināmo upuri līdz ar ēdamo upuri; tā priesterim to, kas šķīstās, būs salīdzināt Tā Kunga priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Šis ir tas likums par to, kam ir spitāļi, kam roka nepaspēj, cik viņa šķīstīšanas pēc vajag.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Kad jūs nāksiet Kanaāna zemē, ko Es jums došu par īpašumu, un kad Es spitālības vainu piesūtīšu kādam jūsu zemes namam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Tad tam, kam tas nams pieder, būs nākt un priesterim dot ziņu un sacīt: man šķiet, kādu vainu esam manā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Un priesterim būs pavēlēt, ka to namu izkravā, pirms priesteris nāk, to vainu apraudzīt, lai netop nešķīsti visi, kas tai namā, un tad priesterim būs nākt un to namu apraudzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Kad viņš nu to vainu aplūkojis un redz, ka tai vainai pie nama sienām ir pazaļas vai pasarkanas dobītes, un tās dziļāki izraugās nekā tā siena,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Tad priesterim no nama būs iziet pie nama durvīm un to namu aizslēgt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Un septītā dienā priesterim atkal būs nākt un lūkot, un raugi, ja tā vaina pie nama sienām ir izpletusies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Tad priesterim būs pavēlēt, ka tos akmeņus izlauž, kur tā vaina, un tos ārā izmet aiz pilsētas kādā nešķīstā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Un to namu no iekšienes visapkārt būs nokasīt, un to nokasījumu, ko tie nokasījuši, būs izmest ārā aiz pilsētas uz kādu nešķīstu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Tad tiem būs ņemt citus akmeņus un likt viņu akmeņu vietā, un citus mālus ņemt un to namu apmest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Bet ja tā vaina tajā namā izplešas, pēc tam kad tie akmeņi ir izlauzti, tas nams nokasīts un atkal apmests,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Tad priesterim būs nākt un raudzīt, un redzi, ja tā vaina pie tā nama ir izpletusies, tad ēdoti spitālības vaina ir tanī namā; - tas ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Un to namu, viņa akmeņus un viņa kokus un visus nama mālus būs nolauzīt un ārā izmest aiz pilsētas uz kādu nešķīstu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Un kas šai namā iet jebkurā dienā, kad tas tapis aizslēgts, tam būs nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Un kas tajā namā guļ, tam būs mazgāt savas drēbes, un kas tai namā ēd, tam būs mazgāt savas drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Bet kad priesteris atkal nāks un lūkos un redzi, tā vaina tai namā pēc tam, kad tas apmests, nav izpletusies, tad priesterim to namu būs atzīt par šķīstu, jo tā vaina ir sadzijusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Tad viņam priekš tā nama šķīstīšanas būs ņemt divus putnus un ciedra koku un sarkanus dzīparus un īzapu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Un viņam to vienu putnu būs nokaut kādā mālu traukā pār tekošu ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Un viņam būs ņemt to ciedra koku un to īzapu un tos sarkanos dzīparus un to dzīvo putnu un tos iemērcēt tā nokauta putna asinīs un tai tekošā ūdenī un to namu septiņreiz apslacīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Tā viņam to namu būs šķīstīt ar tā putna asinīm un ar to tekošo ūdeni un ar to dzīvo putnu un ar to ciedra koku un ar to īzapu un ar tiem sarkaniem dzīpariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Tad viņam to dzīvo putnu būs palaist ārā aiz pilsētas laukā; tā viņam to namu būs salīdzināt, tad tas taps šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Šis ir tas likums par ikvienu spitālības vainu un par kraupi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Un par drēbju un namu spitāļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Un par tūkumiem un kašķi un baltām pūtēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Par mācību, kad kas ir nešķīsts un kad kas šķīsts; - šis ir tas likums par spitāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Runājiet uz Israēla bērniem un sakāt uz tiem: ikvienam vīram, kam sava miesa pil, būs savas pilēšanas dēļ nešķīstam būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Šī nu ir viņa nešķīstība viņa pilēšanas dēļ: kad no viņa miesas iztek viņa pilēšana, vai kad viņa miesa aiztur viņa pilēšanu; šī ir viņa nešķīstība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Visām gultām, uz kā tas gulēs, kam tā pilēšana, būs nešķīstām būt, un visiem rīkiem, uz kā viņš sēdēs, būs nešķīstiem būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Un kas viņa gultu aizskar, tam savas drēbes būs mazgāt un ar ūdeni pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Un kas uz to uzsēžas, kur viņš ir sēdējis, tam savas drēbes būs mazgāt un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Un kas aizskar miesu tam, kam tā pilēšana, tam savas drēbes būs mazgāt un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Un, ja tas, kam tā pilēšana, uz vienu šķīstu uzspļaus, tad šim savas drēbes būs mazgāt un ar ūdeni pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Un visiem sedliem, uz kā tas jāj, kam tā pilēšana, būs nešķīstiem būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Un kas kādu lietu aizskar, kas viņa apakšā bijusi, būs nešķīsts līdz vakaram, un kas to nes, tam savas drēbes būs mazgāt un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Un ikkatram, ko tas aizskar, kam tā pilēšana, pirms savas rokas nav mazgājis, būs mazgāt savas drēbes un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Un to mālu trauku, ko tas aizskar, kam tā pilēšana, būs sadauzīt, bet koku trauku ar ūdeni būs skalot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Kad nu tas, kam tā pilēšana, no savas pilēšanas ir šķīstīts, tad tam no savas šķīstīšanas būs septiņas dienas skaitīt un savas drēbes mazgāt un savu miesu tekošā ūdenī pērt, tad tas būs šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Un astotā dienā tam būs ņemt divas ūbeles jeb divus jaunus baložus un nākt Tā Kunga priekšā pie saiešanas telts durvīm un tos priesterim dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Un priesterim tos būs sataisīt, vienu par grēku upuri un otru par dedzināmo upuri; tā priesterim viņu būs salīdzināt viņa pilēšanas dēļ Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Un, ja no kāda vīra guļot sēkla iztek, tad tam visu savu miesu būs ūdenī pērt un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Un visām drēbēm un visai ādai, uz kā tā sēkla būs, tām ar ūdeni būs mazgātām tapt un būt nešķīstām līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Un tai sievai, pie kā tāds vīrs gulējis, kam sēkla guļot (izpil), ūdenī būs pērties un nešķīstai būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Bet, ja vienai sievai asins sārņi no miesas pil, tad viņa septiņas dienas taps atšķirta, un, kas viņu aizskar, būs nešķīsts līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Un viss, uz kā viņa guļ, kamēr viņa ir atšķirta, būs nešķīsts, ir viss, uz kā viņa sēd, būs nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Un kas viņas gultu aizskar, tam būs savas drēbes mazgāt un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Un ikvienam, kas to aizskar, uz kā viņa sēdējusi, savas drēbes būs mazgāt un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Un, ja kāds trauks uz tā sēdekļa jeb uz tās gultas ir bijis, - ja kas to aizskar, tam būs nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Un, ja kāds vīrs pie viņas gulēt gulēs un viņas nešķīstība tam uziet, tad tam septiņas dienas būs nešķīstam būt, un ikvienai gultai, kur viņš virsū gulējis, būs nešķīstai būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Un, ja kāda sieva daudz dienas, kad tai tas sārņu laiks nav, uz drānām dabū, jeb kad viņas sārņi ilgāki stāv, tad viņai tik ilgi, kamēr viņai tie sārņi, būs nešķīstai būt tā kā pašā sārņu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Ikvienai gultai, uz kā tā ir gulējusi visās savu lieku sārņu dienās, viņai tāpat būs būt kā tā gulta viņas īsto sārņu laikā, un viss, uz kā viņa ir sēdējusi, būs nešķīsts tā kā viņas sārņu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Un kas no tām lietām ko aizskar, tam būs nešķīstam būt un savas drēbes mazgāt un ūdenī pērties un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Bet, ja viņa no saviem sārņiem top šķīsta, tad viņai priekš sevis būs septiņas dienas skaitīt, pēc tam viņai būs šķīstai būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Un astotā dienā viņai priekš sevis būs ņemt divas ūbeles jeb divus jaunus baložus, un tos nest pie priestera priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Un priesterim būs sataisīt vienu par grēku upuri un otru par dedzināmo upuri; tā priesterim viņu būs salīdzināt Tā Kunga priekšā, viņas nešķīstības sārņu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Tā jums Israēla bērnus būs atšķirt no viņu nešķīstības, ka tie savā nešķīstībā nenomirst, apgānīdami manu dzīvokli, kas ir jūsu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Šis ir tas likums par to, kam miesa pil, un par to, no kā guļot sēkla tek, tā ka viņš caur to top nešķīsts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Un par vāju sievu sārņu laikā, un par to, kam sava miesa pil, lai būtu vīrietis, vai sieviete, un par vīru, kas pie kādas nešķīstas sievas ir gulējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Un Tas Kungs runāja uz Mozu, pēc tam kad Ārona divi dēli bija nomiruši, kad tie bija nākuši Tā Kunga priekšā un miruši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Tad Tas Kungs sacīja uz Mozu: runā uz Āronu, savu brāli, ka tam nebūs iet kaut kurā laikā svētā vietā aiz tā priekškaramā, priekš salīdzināšanas vāka, kas uz tā šķirsta, ka tas nemirst; jo Es parādīšos padebesī uz salīdzināšanas vāka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Ar to Āronam būs ieiet svētā vietā: ar jaunu vērsi par grēku upuri un aunu par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Viņam būs uzvilkt svētos nātnu svārkus, un nātnu ūzām būs būt uz viņa miesām, un ar nātnu jostu viņam būs apjozties un ar nātnu cepuri apsegties: šās ir tās svētās drēbes; un savu miesu viņam būs pērt ūdenī un tad apģērbties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Un no Israēla bērnu draudzes viņam būs ņemt divus āžus par grēku upuri un vienu aunu par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Un Āronam grēku upura vērsi priekš sevis būs upurēt un sevi un savu namu salīdzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Viņam arī būs ņemt tos divus āžus un tos novest Tā Kunga priekšā, priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Un Āronam par tiem diviem āžiem būs mest meslus, vienu meslu priekš Tā Kunga, un otru meslu priekš tā palaižamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Un to āzi, uz ko tie mesli priekš Tā Kunga krituši, Āronam būs pievest un to sataisīt par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Bet to āzi, uz ko tie mesli krituši, ka tas palaižams, būs vest dzīvu Tā Kunga priekšā un salīdzināt, ka to var palaist par palaižamo tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'To grēku upura vērsi, kas priekš viņa paša, Āronam būs pievest un sevi un savu namu salīdzināt, un to grēku upura vērsi nokaut, kas ir priekš viņa paša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Viņam arī būs ņemt vīraka trauku, pilnu ar degošām oglēm no altāra Tā Kunga priekšā, un abas rokas pilnas ar kvēpināmo no sagrūstām jaukas smaržas zālēm, un tās viņam būs nest aiz tā priekškaramā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Un tās kvēpināmās zāles viņam būs likt uz uguni Tā Kunga priekšā, ka tie kvēpināšanas dūmi apklāj salīdzināšanas vāku uz tās liecības, lai viņš nemirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Un no tā vērša asinīm viņam būs ņemt un ar savu pirkstu slacīt uz salīdzināšanas vāka priekšu, un pret salīdzināšanas vāku viņam septiņkārt no tām asinīm būs slacīt ar savu pirkstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Un to grēku upura āzi, kas priekš tiem ļaudīm, viņam būs nokaut un viņa asinis ienest aiz tā priekškaramā, un ar viņa asinīm tāpat darīt, kā viņš darījis ar tā vērša asinīm, un tās slacīt uz salīdzināšanas vāku un pret salīdzināšanas vāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Tā viņam būs salīdzināt to svēto vietu Israēla bērnu nešķīstības dēļ un viņu pārkāpumu dēļ visos viņu grēkos, un tā viņam būs darīt saiešanas teltī, kas pie viņiem ir viņu nešķīstību vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Un nevienam cilvēkam nebūs būt saiešanas teltī, kad viņš ieies, salīdzināšanu darīt svētā vietā, tiekams viņš iziet; tā viņam būs salīdzināt sevi un savu namu un visu Israēla draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Tad viņam būs iziet pie altāra, kas ir Tā Kunga priekšā, un viņu salīdzināt, un būs ņemt no tā vērša asinīm un no tā auna asinīm un likt uz altāra ragiem visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Un viņam ar savu pirkstu no tām asinīm septiņkārt uz to būs slacīt un to šķīstīt un svētīt no Israēla bērnu nešķīstībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Kad nu viņš pabeidzis salīdzināt to svēto vietu un saiešanas telti un altāri, tad viņam būs pievest to dzīvo āzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Un Āronam būs likt savas abējas rokas uz tā dzīva āža galvu, un uz tā izsūdzēt visus Israēla bērnu noziegumus un visus viņu pārkāpumus pēc visiem viņu grēkiem un tos likt uz tā āža galvu un to tuksnesī palaist caur zināma vīra roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Tā tam āzim uz sevis būs nest visus viņu noziegumus tuksnesī, un tam vīram to āzi būs palaist tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Tad Āronam būs nākt saiešanas teltī un novilkt tās nātnu drēbes, ko viņš bija apvilcis, svētā vietā iedams, un tās tur nolikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Un savu miesu viņam būs pērt ūdenī svētā vietā un apvilkt savas drēbes; tad viņam būs iziet un sataisīt savu dedzināmo upuri un to ļaužu dedzināmo upuri, un salīdzināt sevi un tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Un viņam arī būs iededzināt tos grēku upura taukus uz altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Un kas to palaižamo āzi palaidis, tam būs mazgāt savas drēbes un pērt ūdenī savu miesu, un pēc lai tas nāk lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Bet to grēku upura vērsi un to grēku upura āzi, kuru asinis ir ienestas, salīdzināt to svēto vietu, tos viņam būs izvest ārā aiz lēģera un ar uguni sadedzināt viņu ādas un viņu gaļu un viņu sūdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Kas tos sadedzina, tam būs mazgāt savas drēbes un pērt savu miesu ūdenī, un pēc lai tas nāk lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Un tas lai jums ir par likumu mūžam: septītā mēnesī, desmitā mēneša dienā, jums būs savu dvēseli mērdēt (gavēt), un nekādu darbu lai nedara nedz iedzīvotājs nedz svešinieks, kas mīt jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Jo šai dienā jūs topat salīdzināti uz šķīstīšanu, no visiem saviem grēkiem jūs topat šķīstīti Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Šī lai jums ir it augsta dusēšanas diena, un mērdējat savu dvēseli; tas ir likums mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Un to salīdzināšanu lai izdara tas priesteris, kas svaidīts un kam roka ir pildīta, ka viņš sava tēva vietā par priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Un viņam būs apvilkt tās nātnu drēbes, tās svētās drēbes; tā viņam būs salīdzināt svētās vietas svētumu; un viņam būs salīdzināt saiešanas telti un altāri, un viņam būs salīdzināt priesterus un draudzes ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Un tas lai jums ir par likumu mūžam, ka jūs Israēla bērnus salīdzināt par visiem viņu grēkiem vienreiz gadskārtā. Un viņš darīja, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Runā uz Āronu un uz viņa dēliem un uz visiem Israēla bērniem, un saki tiem: šis ir tas vārds, ko Tas Kungs pavēlējis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Ikviens no Israēla nama, kas lēģerī nokaus kādu vērsi vai teļu vai kazu, vai ārā aiz lēģera ko nokaus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Un to nenesīs priekš saiešanas telts durvīm, upuri upurēt Tam Kungam Tā Kunga dzīvokļa priekšā, tam vīram asinis taps pielīdzinātas, tā kā viņš būtu izlējis asinis; tāpēc tam vīram būs tapt izdeldētam no viņa ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Lai Israēla bērni pienes savus upurus, ko tie uz lauka grib upurēt, lai tos pienes priekš saiešanas telts durvīm pie priestera, un lai tos upurē Tam Kungam par pateikšanas upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Un priesterim būs slacīt tās asinis uz Tā Kunga altāri priekš saiešanas telts durvīm, un būs iededzināt tos taukus par saldu smaržu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Un savus upurus tiem arī vairs nebūs upurēt tiem jodiem(ļauniem gariem), kam pakaļ tie mauko; lai tas viņiem ir par likumu uz viņu pēcnākamiem mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Saki tad viņiem: ikviens no Israēla nama un no svešiniekiem, kas mīt jūsu starpā, kad tas grib upurēt dedzināmu vai kaujamu upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Un to nenesīs priekš saiešanas telts durvīm, to sataisīdams Tam Kungam, šim vīram būs tapt izdeldētam no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Un ikviens no Israēla nama un no svešiniekiem, kas mīt jūsu starpā, kas kaut kādas asinis ēd, pret to, kas ēd asinis, Es celšu Savu vaigu un to izdeldēšu no viņa ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Jo miesas dvēsele ir asinīs, tādēļ Es jums tās esmu devis uz altāri, lai jūsu dvēseles ar tām top salīdzinātas, jo asinis salīdzina caur dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Tādēļ Es Israēla bērniem esmu sacījis: nevienam no jums nebūs ēst asinis, arī tam svešiniekam, kas mīt jūsu starpā, nebūs ēst asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Ikkatram no Israēla bērniem un no svešiniekiem, kas jūsu starpā, kas medī kādu meža zvēru vai putnu, kas ēdams, tam būs izliet viņa asinis un tās apraust ar zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Jo ar ikvienas miesas dvēseli ir tā: viņas asinis ir viņas dvēsele, tāpēc es esmu sacījis Israēla bērniem: jums nebūs ēst nekādas miesas asinis, jo ikvienas miesas dvēsele ir viņas asinis; ikkatram, kas to ēd, būs tapt izdeldētam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Un kurš no iedzīvotājiem vai svešiniekiem ēd maitu vai saplosītu, tam būs mazgāt savas drēbes un pērties ūdenī un nešķīstam būt līdz vakaram, tad viņš taps šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Bet ja viņš nemazgās un nepērs savu miesu, tad viņam būs nest savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Runā uz Israēla bērniem un saki tiem: Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Pēc Ēģiptes zemes darbiem, kur jūs esat mājojuši jums nebūs darīt un pēc Kanaāna zemes darbiem, kurp Es jūs vedu, jums nebūs darīt, nedz staigāt viņu likumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Jums būs darīt Manu tiesu un Manu iestādījumu un iekš tiem staigāt; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Manus likumus jums būs turēt un Manu tiesu jums būs darīt; kurš cilvēks tos darīs, tas caur tiem dzīvos; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nevienam nebūs pieiet pie sava asinsrada, kaunumu atsegt; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Sava tēva kaunumu un savas mātes kaunumu tev nebūs atsegt; tā ir tava māte, viņas kaunumu tev nebūs atsegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Sava tēva sievas kaunumu tev nebūs atsegt; - tas ir tava tēva kaunums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Savas māsas, sava tēva meitas vai savas mātes meitas kaunumu, vai tā mājā vai ārā dzimusi, tev nebūs atsegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Sava dēla meitas vai savas meitas meitas kaunumu tev nebūs atsegt; - jo tas ir tavs kaunums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Sava tēva sievas meitas kaunumu, kas tavam tēvam dzimusi, (tā ir tava māsa) tev nebūs atsegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Sava tēva māsas kaunumu tev nebūs atsegt, tā ir: tava tēva asins radiniece.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Savas mātes māsas kaunumu tev nebūs atsegt, jo tā ir tavas mātes asins radiniece.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Sava tēva-brāļa kaunumu tev nebūs atsegt, viņas sievu tev nebūs aizskart, - tā ir tava tēva brāļa sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Savas vedeklas kaunumu tev nebūs atsegt, tā ir tava dēla sieva, - tev nebūs atsegt viņas kaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Sava brāļa sievas kaunumu tev nebūs atsegt, - tas ir tava brāļa kaunums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Kādas sievas un viņas meitas kaunumu tev nebūs atsegt, nedz viņas dēla meitu nedz viņas meitas meitu tev nebūs ņemt, viņas kaunumu atsegt: tās ir asins radinieces, tā ir negantība,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Tev arī nebūs ņemt sievu pie viņas māsas, kas tev jau ir, viņas kaunumu atsegt šai par riebšanu, kamēr šī dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Tev arī nebūs sievu aizskart, kamēr viņas sārņu laiks ir, viņas kaunumu atsegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Tev arī nebūs piegulēt sava tuvākā sievu, ar viņu apgānīdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Un no sava dzimuma tev nebūs dot, ka tas Molokam top sadedzināts, ka tu sava Dieva vārdu nepulgo; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Pie vīrieša tev nebūs gulēt, tā kā pie sievas, - tā ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Tev arī nebūs jaukties ar nekādu lopu, ar viņu apgānīdamies; ir nekādai sievai ar nekādu lopu nebūs apieties, ar to sagānīdamās; tā ir neganta sajaukšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Un jums nebūs apgānīties ar šādiem (grēkiem), jo ar šiem visiem tie pagāni ir apgānījušies, ko Es jūsu priekšā izdzīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Un tā zeme ir apgānīta, un Es par to viņas noziegumu piemeklēšu, tā ka tā zeme savus iedzīvotājus izspļauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Bet jums būs turēt Manus likumus un Manu tiesu un nekā nedarīt no visām šīm negantībām, ne iedzīvotājam, ne svešiniekam, kas mīt jūsu starpā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Jo šīs zemes ļaudis, kas priekš jums bija, visas šās negantības darījuši, un tā zeme ir apgānīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Lai tā zeme jūs arīdzan neizspļauj, kad jūs to apgānīsiet, itin kā tā izspļāvusi tos pagānus, kas priekš jums bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Jo ikviens, kas no šīm negantībām ko darīs: tām dvēselēm, kas to dara, būs tikt izdeldētām no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Tāpēc jums būs turēt Manu likumu, ka jūs nedarāt pēc nevienas no tām negantām ierašām, ko tie priekš jums darījuši, nedz ar tām apgānāties: - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Runā uz visu Israēla bērnu draudzi un saki tiem: jums būs svētiem būt, jo Es, Tas Kungs, jūsu Dievs, esmu svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ikvienam būs bīties savu māti un savu tēvu un turēt Manu dusēšanas dienu; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Jums nebūs griezties pie elkiem un nebūs sev darīt lietus dievus; Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Un kad jūs Tam Kungam gribat upurēt pateicības upuri, tad jums to būs upurēt no laba prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Tai dienā, kad jūs to upurējat, un otrā dienā jums to būs ēst, bet kas atliek līdz trešai dienai, to būs sadedzināt ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Un ja kas trešā dienā ēdin no tā ēdīs, tad tā ir negantība; tas nebūs patīkami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Un kas no tā ēd, tam būs nest savu noziegumu, tāpēc ka tas sagānījis Tā Kunga svētumu, un šī dvēsele taps izdeldēta no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Un kad jūs pļaujat savas zemes augļus, tad tev nebūs visai(pilnīgi) nopļaut sava tīruma stūri, nedz to visai(pilnīgi) sakrāt, kas no tavas pļaušanas ir sakrājams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Arī sava vīna dārza augļus tev nebūs it gluži nolasīt nedz uzlasīt sava vīna dārza nokritušās ogas; nabagam un svešiniekam tev to būs pamest; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Jums nebūs zagt nedz melot, nedz viltību dzīt nevienam pret savu tuvāko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Jums nebūs nepatiesi zvērēt pie Mana Vārda, ka tu neapgāni sava Dieva vārdu; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Tev savu tuvāko nebūs pievilt nedz aplaupīt, algādža algai pie tevis nebūs palikt līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Tev nebūs kurlu lādēt nedz aklam ko ceļā mest, bet tev būs bīties no sava Dieva; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Jums tiesā nebūs netaisnības darīt; tev nebūs zemākā vaigu uzlūkot nedz augstākā vaigu godāt; ar taisnību tev būs tiesāt savu tuvāko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Tev nebūs mēlnesim būt starp saviem ļaudīm, tev nebūs celties pret sava tuvākā asinīm: - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Tev nebūs savu brāli ienīdēt savā sirdī, bet savu tuvāko tikuši(atklāti) pārmācīt, ka tev viņa dēļ nav grēks jānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Tev nebūs atriebties nedz dusmību turēt pret savu ļaužu bērniem, bet tev būs savu tuvāko mīlēt kā sevi pašu; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Manus likumus jums būs turēt; saviem lopiem tev nebūs likt sajaukties ar lopiem no citas kārtas; savu tīrumu tev nebūs apsēt ar dažādu mistru, un drēbēm no divējāda auduma, nātnu un vilnainu, nebūs nākt uz tavu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Kad vīrs guļ pie kādas sievas un to pieguļ, un tā ir kalpone, kas vīram saderēta, bet nav ne atpirkta, ne atlaista svabada, - tos būs sodīt, bet mirt tiem nebūs, jo tā nav bijusi svabada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Un viņam būs pienest Tam Kungam savu nozieguma upuri priekš saiešanas telts durvīm, aunu par nozieguma upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Un ar to nozieguma upura aunu priesterim viņu būs salīdzināt Tā Kunga priekšā viņa grēka dēļ, ko viņš darījis; lai viņam tiek piedots viņa grēks, ko viņš darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Un kad jūs tai zemē nāksiet un dēstīsiet visādus kokus par barību, tad jums viņu augļus būs turēt par neapgraizītiem; trīs gadus lai tie jums paliek par neapgraizītiem, tos nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Bet ceturtā gadā visiem viņu augļiem būs svētiem būt, par slavas upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Un piektā gadā jums būs ēst viņu augļus, lai viņu augļi priekš jums vairojās; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Jums nekā nebūs ēst ar asinīm. Jums nebūs zīlēt nedz burt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Jums nebūs apgriezt savus galvas matus nedz apcirpt bārdas malas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Jums miroņa dēļ nebūs iegriezt zīmes savā miesā, nedz sev iededzināt rakstus; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Tev nebūs sagānīt savu meitu, viņu pie maucības turot, lai zeme nedzen maucību, un lai zeme nepildās ar negantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Jums būs turēt Manas dusēšanas dienas un bīties Manu svēto vietu; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Jums nebūs griezties pie zīlniekiem vai pareģiem; nemeklējiet tos, lai pie tiem nesagānāties; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Priekš sirmas galvas tev būs uzcelties un veca vaigu godāt un savu Dievu bīties; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Un kad viens svešinieks pie tevis mitīs jūsu zemē, tad jums nebūs viņu apspiest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Tas svešinieks, kas pie jums piemīt, lai jūsu starpā ir tā kā jūsu iedzīvotājs; tev viņu būs mīļot kā sevi pašu; - jo jūs esat svešinieki bijuši Ēģiptes zemē; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Jums nebūs nekādu netaisnību darīt tiesā, ar olekti, svaru, mēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Jums būs turēt taisnu svaru, taisnus podus un taisnu pūru un stopu; - Es esmu Tas Kungs, jūsu Dievs, kas jūs izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Un visus Manus likumus un visas Manas tiesas jums būs turēt un pildīt; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Tev būs sacīt Israēla bērniem: ikvienu no Israēla bērniem un no tiem svešiniekiem, kas mīt Israēla starpā, kas no sava dzimuma Molokam dod, to būs nokaut; tiem zemes ļaudīm viņu būs nomētāt ar akmeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Un Es celšu Savu vaigu pret šo vīru un to izdeldēšu no viņa ļaužu vidus, tāpēc ka tas no sava dzimuma ir devis Molokam, nešķīstu darīdams Manu svēto vietu un sagānīdams Manu svēto Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Un ja tās zemes ļaudis savas acis aizslēdz priekš šī cilvēka, kad tas no sava dzimuma dod Molokam, to nenokaudami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Tad Es celšu Savu vaigu pret to vīru un pret viņa cilti, un izdeldēšu no viņa ļaužu vidus viņu un visus, kas tam mauko pakaļ, un mauko pakaļ Molokam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Kad kas laban griezīsies pie zīlniekiem un pareģiem, viņiem maukodams pakaļ, pret to Es celšu Savu vaigu un to izdeldēšu no viņa ļaužu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Tāpēc svētījaties un esiet svēti, jo Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Un turat Manus likumus un dariet tos; - Es esmu Tas Kungs, kas jūs svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Ja kas savu tēvu vai savu māti lād, to būs nokaut; viņš savu tēvu vai savu māti lādējis, viņa asinis lai uz tā paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Un kad kāds vīrs laulību pārkāpj ar cita sievu, kad viņš laulību pārkāpj ar sava tuvākā sievu, tam būs tikt nokautam, ir tam pārkāpējam, ir tai pārkāpējai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Un tas vīrs, kas guļ pie sava tēva sievas, tas atsedz sava tēva kaunumu, - tos abus būs nokaut; lai viņu asinis uz tiem paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Un ja kāds vīrs guļ pie savas vedeklas, tos abus būs nokaut; tie darījuši negantu nešķīstību; lai viņu asinis uz tiem paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Un ja vīrs guļ pie vīra kā pie sievas, tie abi ir darījuši negantību; tos būs nokaut; lai viņu asinis uz tiem paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Un ja kāds vīrs ņem sievu un viņas māti, tā ir negantība; viņu līdz ar tām būs ar uguni sadedzināt, lai nav negantība jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Un ja kāds vīrs guļ pie lopa, to būs nokaut, un jums arī to lopu būs nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Tāpat arīdzan, ja sieva nāk pie lopa, ar viņu sajaukdamās, tad jums būs nokaut to sievu un to lopu, tiem jāmirst; lai viņu asinis uz tiem paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Un ja kāds vīrs ņem savu māsu, sava tēva meitu vai savas mātes meitu, un tas lūko viņas kaunumu, un tā lūko viņa kaunumu, tā ir bezkaunība, - tāpēc tiem būs tikt izdeldētiem no savu ļaužu bērnu acīm; viņš ir atsedzis savas māsas kaunumu, tam būs nest savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Un ja vīrs guļ pie kādas sievas, kurai ir uz drānām, un atsedz viņas kaunumu un atdara viņas avotu, un šī atsedz savu asins avotu, tad tiem abiem būs tapt izdeldētiem no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Savas mātes māsas un sava tēva māsas kaunumu tev nebūs atsegt, jo tāds ir atsedzis savu asinsradinieci, - tiem būs nest savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Un ja vīrs guļ pie sava tēva brāļa sievas, tas ir atsedzis sava tēva brāļa kaunumu, tiem būs nest savus grēkus, bez bērniem tiem būs nomirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Un ja vīrs ņem sava brāļa sievu, tā ir bezkaunība, tas ir atsedzis sava brāļa kaunumu, tiem būs palikt bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Turat tad visus Manus likumus un visas Manas tiesas un dariet pēc tiem, ka tā zeme jūs neizspļauj, kurp Es jūs vedu, tur dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Un nestaigājiet to pagānu likumos, ko Es jūsu priekšā izdzīšu, jo visas šās lietas tie ir darījuši, tāpēc Es viņus esmu apnicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Un Es jums esmu sacījis, jums būs iemantot viņu zemi, un Es jums došu to iemantot, zemi, kur piens un medus tek; Es esmu Tas Kungs, jūsu Dievs, kas jūs atšķīris no pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Tāpēc jums būs izšķirt šķīstus lopus no nešķīstiem un nešķīstus putnus no šķīstiem; un jums nebūs sagānīt savas dvēseles pie lopiem nedz pie putniem nedz pie kaut kā, kas lien virs zemes, no kā Es jūs esmu nošķīris, un jums to būs turēt par nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Un jums būs Man būt svētiem, jo Es, Tas Kungs, esmu svēts un esmu jūs nošķīris no pagāniem, Man piederēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Kad nu vīrs vai sieva ir zīlnieki vai pareģi, tos būs nokaut, tie ar akmeņiem jānomētā; - lai viņu asinis uz tiem paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Un Tas Kungs sacīja uz Mozu: runā uz tiem priesteriem, Ārona dēliem, un saki tiem: pie miroņa lai (priesteris) nepaliek nešķīsts starp saviem ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Kā tik vien pie sava asinsrada, kas viņam tuvu rada, pie savas mātes un pie sava tēva un pie sava dēla un pie savas meitas un pie sava brāļa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Un pie savas māsas, kas vēl jumprava un viņam klāt, kas vēl nav pie vīra, pie tiem tas var palikt nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Nešķīstam nebūs palikt kungam pār saviem ļaudīm, sevi apgānot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Uz savas galvas tiem nebūs izcirpt plikumu, nedz nogriezt savas bārdas malas, nedz iegriezt zīmes savā miesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Tiem būs svētiem būt savam Dievam un sava Dieva vārdu tiem nebūs sagānīt, jo tie upurē Tā Kunga uguns upurus, sava Dieva maizi, tāpēc tiem būs svētiem būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Mauku vai apsmietu tiem nebūs ņemt, un sievu, kas atstādināta no sava vīra, tiem nebūs ņemt, jo viņš ir savam Dievam svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Tāpēc to turi par svētu, jo viņš upurē tava Dieva maizi; tam būs tev svētam būt, jo Es esmu svēts, Es Tas Kungs, kas jūs svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Ja nu kāda priestera meita sāk maucību dzīt, tā sagāna savu tēvu; ar uguni to būs sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Un tam augstam priesterim starp saviem brāļiem, uz kura galvu svaidāmā eļļa ir izlieta un kas iesvētīts, ka tas apģērbts ar (svētām) drēbēm, tam nebūs savu galvu atsegt nedz savas drēbes saplosīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Tam arī nebūs iet pie neviena miroņa, ne pie sava tēva ne pie savas mātes, tam nebūs palikt nešķīstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Un no tās svētās vietas tam nebūs iziet, ka tas nesagāna sava Dieva svēto vietu, jo tas kronis, viņa Dieva svaidāmā eļļa, ir uz viņa; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Un tam būs ņemt jumpravu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Atraitni, vai atstādinātu, vai apsmietu mauku, tādu tam nebūs ņemt, bet jumpravu no saviem ļaudīm viņam būs ņemt par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Tam nebūs sagānīt savu dzimumu starp saviem ļaudīm; jo Es esmu Tas Kungs, kas viņu svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Runā uz Āronu un saki: nevienam no tava dzimuma jūsu rados, kam kāda vaina, nebūs pieiet, sava Dieva maizi upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Jo nevienam vīram, kam kāda vaina, nebūs pieiet, ne aklam, ne tizlam, nedz kam vaina ģīmī, nedz kroplim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Nedz kam kāja vai roka lauzta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Nedz kam kupris, nedz kas izdilis, nedz kam plēve pār aci, nedz kam kraupis, nedz kam ēde, nedz kas kaunumā maitāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nevienam vīram no priestera Ārona dzimuma, kam ir kāda vaina, nebūs pieiet, uguns upurus nest Tā Kunga priekšā. Viņam ir vaina, viņam nebūs pieiet, sava Dieva maizi upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Sava Dieva maizi tas var ēst, gan no tām vissvētākajām, gan no tām svētām dāvanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Bet pie tā priekškaramā tam nebūs nākt un nepieiet pie altāra, tāpēc ka viņam ir vaina, lai tas nesagāna Manu svēto vietu; jo Es esmu Tas Kungs, kas tos svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Un Mozus to runāja uz Āronu un uz viņa dēliem un uz visiem Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Runā uz Āronu un viņa dēliem, ka tiem būs sargāties no Israēla bērnu svētām dāvanām, (ko tie Man svētī), ka tie nesagāna Manu svēto vārdu; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Saki tiem: kas starp jūsu pēcnākamiem no visa jūsu dzimuma pieies pie tām svētām dāvanām, ko Israēla bērni Tam Kungam svētī, kad tam kāds nešķīstums, tas taps izdeldēts no Mana vaiga; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Nevienam no Ārona dzimuma, kad tas ir spitālīgs, vai kam miesa pil, nebūs ēst no tām svētām dāvanām, tiekams tas top šķīsts. Kas ko aizskar, kas caur mironi palicis nešķīsts, vai kam guļot sēkla izpil,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Vai ja kas kādu līdēju tārpu aizskar, caur ko tas palicis nešķīsts, vai kādu cilvēku, caur ko tas palicis nešķīsts ar kaut kādu nešķīstību, kas viņam ir,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Tas, kas to aizskāris, būs nešķīsts līdz vakaram un lai neēd no tām svētām dāvanām, bet lai per savu miesu ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Un kad saule nogājusi, tad tas ir šķīsts, un pēc tam tas var ēst no tām svētām dāvanām, jo tā ir viņa barība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Maitu un saplosītu tam nebūs ēst, lai ar to nesagānās; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Tā tiem būs turēt Manu pavēli, ka tiem tādēļ grēks nav jānes un caur to nav jāmirst, ka tie to sagānījuši; - Es esmu Tas Kungs, kas tos svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Nevienam svešiniekam nebūs ēst no tā svētītā; nedz piedzīvotājam pie priestera nedz algādzim no tā svētīta nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Bet ja priesteris kādu cilvēku pircis par savu naudu, tam būs no tā ēst, un kas viņa namā ir dzimis, tiem būs ēst no viņa maizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Bet ja priestera meita ies pie kāda sveša vīra, tad viņai nebūs ēst no tā svētā cilājamā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Bet ja priestera meita būs atraitne vai atstādināta un viņai dzimuma nav, un tā nākusi atpakaļ sava tēva namā, kā kad vēl bija meita, tad viņai būs ēst sava tēva maizi; bet nevienam svešiniekam to nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Un ja kas nezinādams no tā svētītā ēdīs, tad viņam pie tā būs pielikt piekto daļu, un atdot priesterim līdz ar to svētīto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Un tiem nebūs sagānīt Israēla bērnu svētās dāvanas, ko tie Tam Kungam devuši par cilājamu upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Ka tie sev neuzkrauj noziegumu un apgrēcību, kad tie ēd savas svētās dāvanas; jo Es esmu Tas Kungs, kas tos svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Runā uz Āronu un uz viņa dēliem un uz visiem Israēla bērniem un saki tiem: ja kas no Israēla nama un no svešiniekiem iekš Israēla grib savu upuri pienest, lai būtu kāds solījums, vai kāds labprātības upuris, ko tie Tam Kungam grib upurēt par dedzināmo upuri, lai tas no jums Viņam būtu patīkams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Tad nesiet vienu tēviņu no vēršiem, jēriem un kazlēniem, kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Kam kāda vaina, to jums nebūs upurēt, jo tas nebūs patīkams no jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Un ja kas Tam Kungam pienes pateicības upuri, vai īpašu solījumu, vai no laba prāta, no lieliem vai no sīkiem lopiem, tam būs būt bez vainas, ka tas ir patīkams, pie tā lai nav nekādas vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ja tas ir akls, vai ar lūzumu, vai ievainots, vai kraupains, vai kašķains ar ēdi, tādus jums nebūs Tam Kungam upurēt, un no tiem jums nebūs Tam Kungam uz altāri likt uguns upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Bet vērsi vai avi, kam visai gari, vai visai īsi locekļi, to jūs varat sataisīt par labprātības upuri, bet par solījuma upuri tas nebūs patīkams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'To saspaidīto, to sadauzīto, vai saplosīto, vai izrāmīto jums nebūs upurēt Tam Kungam, to jums nebūs darīt savā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Arī no svešinieka rokas jums nekā no tādiem nebūs upurēt savam Dievam par barību; jo tiem ir trūkums, tiem ir vaina, tie no jums nebūs patīkami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Kad vērsis, vai jērs, vai kazlēns piedzims, tad tam būs palikt septiņas dienas pie savas mātes, bet astotā dienā un pēc tas būs patīkams Tam Kungam par uguns upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Liellopu vai avi, pašu līdz ar viņa augli, jums nebūs nokaut vienā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Un kad jūs Tam Kungam upurēsiet slavas upuri, tad jums to būs upurēt, kā tas no jums lai būtu patīkams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Tai pašā dienā to būs ēst, jums no tā neko nebūs atlicināt līdz rītam; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Tad nu jums Manus baušļus būs turēt un tos darīt; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Un jums nebūs pulgot Manu svēto vārdu, ka Es Israēla bērnu starpā topu svētīts; - Es esmu Tas Kungs, kas jūs svētī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Kas jūs izvedis no Ēģiptes zemes, lai Es jums būtu par Dievu, Es, Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Runā uz Israēla bērniem un saki tiem: Tā Kunga svētkiem, ko jums būs izsaukt, būs būt svētām sapulcēm; šie ir Mani svētki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sešas dienas būs darbu darīt, bet septītā diena ir tā lielā dusēšanas diena, svēta sapulce; nekādu darbu jums nebūs darīt, tā ir Tā Kunga dusēšanas diena visos jūsu dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Šie ir Tā Kunga noliktie svētki, tās svētas sapulces, ko jums būs izsaukt savā noliktā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Pirmā mēnesī, četrpadsmitā mēneša dienā ap vakara laiku, ir Tā Kunga Pasa svētki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Un piecpadsmitā dienā tai pašā mēnesī ir Tā Kunga neraudzētās maizes svētki; septiņas dienas jums būs ēst neraudzētu maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Pirmā dienā lai jums ir svēta sapulce; nekādu kalpošanas darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Un jums būs septiņas dienas Tam Kungam uguns upuri upurēt; septītā dienā būs svēta sapulce, nekādu kalpošanas darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Runā uz Israēla bērniem un saki tiem: kad jūs tai zemē nāksiet, ko Es jums došu, un jūs viņas augļus pļausiet, tad vienu kūli no savu augļu pirmajiem jums būs nest pie priestera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Un tam to kūli būs līgot Tā Kunga priekšā, ka tas no jums būtu patīkams, tai dienā pēc dusēšanas dienas priesterim to būs līgot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Tai dienā, kad jūs to kūli līgojiet, jums arī būs sataisīt gada vecu jēru, kas bez vainas, Tam Kungam par dedzināmo upuri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Un viņa ēdamo upuri, divus mēriņus kviešu miltu ar eļļu sajauktus, uguns upuri Tam Kungam par saldu smaržu, un viņa dzeramo upuri no vīna, ceturtni no inna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Un jums nebūs ēst maizi, nedz grauzdētas nedz zaļas vārpas līdz tai dienai, kad jūs savam Dievam upuri nesīsiet; tas lai ir par likumu jūsu pēcnākamiem visos jūsu dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Tad jums būs skaitīt no tās dienas pēc dusēšanas dienas, kad jūs nesāt to līgojamā upura kūli, - septiņas pilnas nedēļas lai tās ir;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Līdz tai dienai pēc septītās dusēšanas dienas jums būs skaitīt piecdesmit dienas, tad jums Tam Kungam būs upurēt jaunu ēdamu upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Jums no saviem dzīvokļiem būs pienest divas maizes par līgojamu upuri, no diviem mēriņiem kviešu miltu tām būs būt, ar raugu tās būs cept; tie ir tie pirmaji Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Līdz ar to maizi jums arī būs upurēt septiņus, gada vecus jērus, kas bez vainas, un vienu jaunu vērsi un divus aunus; tie Tam Kungam būs dedzināms upuris līdz ar savu ēdamo upuri un saviem dzeramiem upuriem, uguns upuris Tam Kungam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Jums būs sataisīt arī vienu āzi par grēku upuri un divus gada vecus jērus par pateicības upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Un priesterim tos būs līgot līdz ar tām pirmaju maizēm par līgojamu upuri Tā Kunga priekšā; līdz ar tiem diviem jēriem tās Tam Kungam būs svētas un pieder priesterim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Un tanī pašā dienā jums būs izsaukt un turēt svētu sapulci, nekādu kalpošanas darbu jums nebūs darīt; tas lai ir par likumu visos jūsu dzīvokļos jūsu pēcnākamiem mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Kad jūs nu pļausiet savas zemes augļus, tad jums savā pļaušanā nebūs visai(pilnīgi) nopļaut sava tīruma stūri, nedz sīki salasīt savus augļus; priekš nabaga un priekš svešinieka jums tos būs pamest; - Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Runā uz Israēla bērniem un saki: septītā mēnesī, pirmā mēneša dienā, lai jums ir dusēšana, taurēšanas piemiņa, svēta sapulce.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nekādu kalpošanas darbu jums nebūs darīt, bet jums Tam Kungam būs upurēt uguns upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Bet desmitā dienā, šinī septītā mēnesī, ir salīdzināšanas diena; tad lai jums ir svēta sapulce, un jums būs savas dvēseles mērdēt(gavēt) un Tam Kungam upurēt uguns upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Un tanī dienā jums nekādu darbu nebūs darīt jo tā ir salīdzināšanas diena, ka jūs topat salīdzināti Tā Kunga, sava Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Jo ikviens, kas tai dienā savu dvēseli nemērdē, tas taps izdeldēts no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Un ikviens, kas tai dienā kādu darbu darīs, to Es izdeldēšu no viņa ļaužu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nekādu darbu jums nebūs darīt; lai tas ir par likumu jūsu pēcnākamiem mūžam visos jūsu dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Lai šī jums ir tā lielā dusēšanas diena, tur jums savas dvēseles būs mērdēt, mēneša devītās dienas vakarā, no vakara līdz vakaram jums būs turēt savu dusēšanas dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Runā uz Israēla bērniem un saki: piecpadsmitā dienā šinī septītā mēnesī būs lieveņu svētki septiņas dienas Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Pirmā dienā lai ir svēta sapulce, nekādu kalpošanas darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Septiņas dienas jums būs upurēt uguns upuri Tam Kungam; astotā dienā lai jums ir svēta sapulce, tad jums Tam Kungam būs upurēt uguns upuri, jo šī ir sapulces diena; nekādu kalpošanas darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Šie ir Tā Kunga noliktie svētki, ko jums būs izsaukt par svētām sapulcēm un kur jums būs upurēt Tam Kungam uguns upuri, dedzināmu upuri un ēdamu upuri, kaujamu upuri un dzeramus upurus, kas krīt ikvienai dienai;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Klāt pie Tā Kunga dusēšanas dienām un klāt pie jūsu dāvanām un klāt pie visiem jūsu solījumiem un klāt pie visiem jūsu labprātības upuriem, ko jums būs dot Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Bet septītā mēneša piecpadsmitā dienā, kad jūs zemes augļus esat sakrājuši, jums būs svētīt Tā Kunga svētkus septiņas dienas; pirmā diena lai ir dusēšanas diena, un astotā diena lai arī ir dusēšanas diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Un pirmā dienā jums būs ņemt augļus no skaistiem kokiem, palmu zarus un zarus no kupliem kokiem un vītoliem, un jums Tā Kunga, sava Dieva, priekšā būs līksmoties septiņas dienas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Un tos svētkus jums būs svētīt Tam Kungam septiņas dienas gadskārtā; tas lai ir par likumu jūsu pēcnākamiem mūžam; septītā mēnesī jums tos būs svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Septiņas dienas jums būs dzīvot lieveņos; visiem, kas iekš Israēla dzimuši, būs lieveņos dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Lai jūsu radi var zināt, ka Es Israēla bērniem esmu licis lieveņos dzīvot, tos izvezdams no Ēģiptes zemes, Es Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Un Mozus nosacīja Israēla bērniem Tā Kunga svētkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Pavēli Israēla bērniem, tev nest šķīstu, sagrūstu eļļu no eļļas kokiem priekš luktura, ka eļļas lukturīšus allažiņ var iededzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Ārpus liecības priekškara, saiešanas teltī Āronam no vakara līdz rītam allažiņ to būs sataisīt Tā Kunga priekšā; tas lai ir par likumu jūsu pēcnākamiem mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Uz tā luktura no šķīsta zelta viņam būs iededzināt tos eļļas lukturīšus vienmēr Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Un tev būs ņemt kviešu miltus un no tiem cept divpadsmit raušus, divas desmitdaļas ēfas būs būt vienam rausim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Un tev tos būs uzlikt divās rindās, pa sešiem vienā rindā uz tā šķīstā galda Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Un uz ikvienu rindu tev būs likt šķīstu vīraku, piemiņas tiesu pie tās maizes, par uguns upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Ik svētdienas bez mitēšanās tam tos būs sataisīt Tā Kunga priekšā, no Israēla bērniem par mūžīgu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Un tas lai pieder Āronam un viņa dēliem un tiem to būs ēst svētā vietā, jo tas priekš tiem ir augsti svēts no Tā Kunga uguns upuriem, likums mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Un vienas Israēliešu sievas dēls, kam Ēģiptietis bija par tēvu, izgāja pie Israēla bērniem, un tas Israēliešu sievas dēls bārās lēģerī ar vienu Israēliešu vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Un tas Israēliešu sievas dēls zaimoja (Tā Kunga) vārdu un lādēja. Tad viņu veda pie Mozus, un viņa mātes vārds bija Šelomite, tā bija Dibra meita no Dana cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Un viņu ielika cietumā, kamēr tiem tiktu spriedums no Tā Kunga mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Izved to lādētāju ārā no lēģera, un visiem, kas to dzirdējuši, būs savas rokas uzlikt uz viņa galvu, un visai draudzei to ar akmeņiem būs nomētāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Un uz Israēla bērniem tev būs runāt un sacīt: ikvienam, kas savu Dievu lād, būs nest savu grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Un kas Tā Kunga vārdu zaimo, to būs nokaut, visai draudzei to ar akmeņiem būs nomētāt; vai svešinieks, vai iedzīvotājs, kas to vārdu zaimos, tam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Un ja kas kādu cilvēku nosit, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Bet kas kādu lopu nosit, tam to būs maksāt, dzīvību pret dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Un ja kas savu tuvāko ievaino, tam lai top atdarīts, kā viņš darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Lūzumu pret lūzumu, aci pret aci, zobu pret zobu, itin kā viņš cilvēku ir ievainojis, tāpat viņam taps atdarīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kas lopu nosit, tam to būs maksāt, bet kas cilvēku nosit, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Lai jums ir vienāda tiesa, tā svešiniekam, kā iedzīvotājam; jo Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Un Mozus runāja uz Israēla bērniem, un tie izveda to lādētāju ārā no lēģera un to nomētāja ar akmeņiem un Israēla bērni darīja, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Un Tas Kungs runāja uz Mozu Sinaī kalnā un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Runā uz Israēla bērniem un saki tiem: Kad jūs nāksiet tai zemē, ko Es jums dodu, tad tai zemei būs turēt dusēšanu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sešus gadus tev savu tīrumu būs apsēt un sešus gadus savu vīna dārzu apgriezt un viņa augļus krāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Bet tas septītais gads lai ir tas lielais dusēšanas laiks tai zemei, dusēšana Tam Kungam; savu tīrumu tev nebūs apsēt un savu vīnadārzu tev nebūs apgraizīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Kas pēc tavas pļaušanas pats aug, to tev nebūs nopļaut, un tās ogas, kas bez tavas kopšanas aug, tev nebūs nogriezt; lai tas ir dusēšanas gads zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Bet ko zeme tai dusēšanā nes, lai ir jums par barību, tev un tavam kalpam un tavai kalponei un tavam algādzim un tavam piedzīvotājam, kas mīt pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Un tavam lopam un tam zvēram, kas tavā zemē, lai visi viņas augļi ir par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Un tev septiņus tādus dusēšanas gadus būs skaitīt, septiņus gadus septiņreiz, tā ka to septiņu dusēšanas gadu laiks tev ir četrdesmit deviņi gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Un gavilēšanas bazūne lai skan septītā mēnesī, desmitā mēneša dienā; salīdzināšanas dienā lai bazūne skan visā jūsu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Un jums būs svētīt piecdesmito gadu un izsaukt svabadību tai zemē priekš visiem, kas tur dzīvo; tas lai jums ir gaviles gads, un jums būs ikvienam atkal nākt pie sava īpašuma un ikvienam būs atkal nākt pie savas cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Gaviles gads lai jums ir tas piecdesmitais gads; jums nebūs sēt, nedz to pļaut, kas no sevis paša aug, nedz nogriezt, kas aug bez jūsu kopšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Jo šis ir gaviles gads, tas lai jums ir svēts; jums no tīruma būs ēst, kas tur aug.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Šinī gaviles gadā jums ikvienam atkal būs nākt pie sava īpašuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Tad nu, ja tu ko pārdosi savam tuvākam, vai no sava tuvākā rokas ko pirksi, tad viens otram pāri nedariet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Pēc gadu skaita no tā gaviles gada tev būs pirkt no sava tuvākā, un pēc augļu gadu skaita tev būs viņam pārdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Jo vairāk gadu jo vairāk maksās, un jo mazāk gadu jo mazāk maksās, jo viņš tev pārdod tos augļus pēc tiem gadiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Tad nu nedariet pāri viens otram, bet bīstaties savu Dievu; jo Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Un dariet Manus likumus un turat Manas tiesas un dariet tās, tad jūs tai zemē varēsiet dzīvot mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Un zeme dos savus augļus, un jūs ēdīsiet un būsiet paēduši, un tur dzīvosiet mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Un ja jūs sacīsiet: ko ēdīsim septītā gadā? Redzi, mēs nesējam, nedz krājam savus augļus; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Tad Es pavēlēšu Savai svētībai par jums sestā gadā, ka tam būs izdot treju gadu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Un kad jūs sēsiet astotā gadā, tad jūs ēdīsiet no veciem augļiem līdz devītajam gadam; tiekams jaunie augļi nāk, jūs ēdīsiet vecos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Un zemi nebūs pārdot uz mūžu; jo Man pieder tā zeme, un jūs esat svešinieki un piedzīvotāji pie Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Tāpēc jums visā savā zemē, kas jums pieder, būs atļaut zemi izpirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Kad tavs brālis panīkst un ko pārdod no savas zemes, tad lai nāk viņa tuvākais radinieks viņam par izpircēju un lai izpērk, ko viņa brālis pārdevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Bet ja kam izpircēja nav un viņa roka tik daudz iespēj, ka viņam tik daudz ir, ko izpirkt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Tad viņam būs skaitīt tos gadus, kad viņš pārdevis, un to, kas pāri, atdot tam vīram, kam viņš to bija pārdevis, un tā nākt atpakaļ savā īpašumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Bet ja viņam nav tik daudz pie rokas, cik vajadzīgs atdot, tad tas, ko viņš pārdevis, lai paliek pircēja rokā līdz gaviles gadam, bet gaviles gadā tas nāk vaļā un viņš atkal tiek pie sava īpašuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Un ja kas pārdod dzīvojamu ēku pilsētas mūros, tam būs to atpirkt gada laikā, kamēr to pārdevis; tas ir viņa atpirkšanas laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Bet ja tas netop atpirkts, kamēr gads apkārt, tad tas nams pilsētas mūros lai paliek tam pircējam mūžam uz viņa pēcnākamiem; tas nenāk vaļā gaviles gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Bet namus ciemos, bez mūriem visapkārt, būs pieskaitīt pie zemes laukiem, tie ir atpērkami un nāk vaļā gaviles gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Bet Levitu pilsētās viņu pilsētu nami paliek Levitiem mūžīgi atpērkami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Un ja kas ko pērk no Levitiem, tad tas pārdotais nams viņu pilsētā nāk vaļā gaviles gadā, jo nami Levitu pilsētās ir viņu daļa Israēla bērnu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Arī lauki viņu pilsētu apgabalā nav pārdodami, jo tie ir viņu mūžīgs īpašums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Un ja tavs brālis panīkst un viņa roka gurst tev līdzās, tad palīdzi tam, lai būtu svešinieks, vai piedzīvotājs, ka viņš var dzīvot pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Tev no viņa nebūs ņemt pagaidas nedz augļus, bet tev būs bīties savu Dievu, lai tavs brālis pie tevis dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Savu naudu tev nebūs viņam izdot uz pagaidām, nedz savu barību viņam aizdot uz augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Es esmu Tas Kungs, jūsu Dievs, kas jūs izvedis no Ēģiptes zemes, jums dot Kanaāna zemi un jums būt par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Un kad tavs brālis pie tevis panīkst un tev top pārdots, tad tev nebūs viņam likt kalpot kā vergam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Kā algādzis un piedzīvotājs lai pie tevis dzīvo; līdz gaviles gadam lai viņš tev kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Tad lai viņš no tevis tiek vaļā, viņš un viņa bērni līdz ar to, un lai viņš iet atpakaļ pie savas cilts un nāk atkal pie savu tēvu mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Jo viņi ir Mani kalpi, ko Es esmu izvedis no Ēģiptes zemes; tiem nebūs tapt pārdotiem, kā vergus pārdod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Tev nebūs bargi par viņu valdīt, bet tev būs bīties savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Taviem kalpiem un tavām kalponēm, kas tev ir, būs būt no apkārtējiem pagāniem; no tiem jums būs pirkt kalpus un kalpones.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Arī no piedzīvotāju bērniem, kas pie jums mīt, no tiem jūs varat tos pirkt un no viņu dzimuma pie jums, ko tie jūsu zemē dzemdinājuši, un tie lai jums ir par īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Un tos jūs varat atstāt par mantību saviem bērniem pēc jums, ka tie ir viņu īpašums; lai tie jums kalpo mūžam; bet par saviem brāļiem, Israēla bērniem, lai neviens par otru bargi nevalda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Un ja kāds svešinieks vai piedzīvotājs pie tevis nāk pie rocības, un tavs brālis pie viņa panīkst un top pārdots tam svešiniekam, kas pie tevis mīt, vai kādam no svešinieka rada un cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Tad viņu var atpirkt, kad ir pārdots; viens no viņa brāļiem lai viņu atpērk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Vai viņa tēva brālis, vai viņa tēva brāļa dēls lai viņu atpērk, vai kāds no viņa cilts asins radiem lai viņu atpērk, vai kad viņa paša roka spēj, tad lai pats atpērkas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Un viņam ar savu pircēju būs skaitīt no tā gada, kad viņš pārdevies, līdz gaviles gadam, un viņa atpirkšanas maksā lai ir pēc tā gadu skaita, uz laiku kā algādzis lai viņš pie tā ir bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Ja vēl ir daudz gadu, tad pēc viņu skaita lai tas atdod par savu atpirkšanu to naudu, ar ko viņš ir pirkts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Un ja vēl maz gadu pāri līdz gaviles gadam, tad lai tos saskaita; pēc savu gadu skaita tam būs atmaksāt savu atpirkšanu; kā algādzis gadu pēc gada lai viņš pie tā ir bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Tam nebūs bargi pār viņu valdīt tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Un ja viņš tā netop izpirkts, tad viņam gaviles gadā būs tikt vaļā, viņam un viņa dēliem līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Jo Israēla bērni Man ir par kalpiem, viņi ir Mani kalpi, ko Es esmu izvedis no Ēģiptes zemes. Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Jums nebūs sev darīt elkus, nedz izgriezt bildes, nedz uzcelt kādus stabus, nedz likt iezīmētus akmeņus savā zemē, tos pielūgt; jo Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Manas dusēšanas dienas jums būs turēt un Manu svēto vietu bīties; - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Ja jūs Manos likumos staigāsiet un Manas pavēles turēsiet un tās darīsiet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Tad Es jums došu lietu savā laikā, un zeme dos savu labību, un koki laukā dos savus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Un kulšanas laiks sniegsies līdz vīna lasīšanai, un vīna lasīšana līdz sējamam laikam, un jūs ēdīsiet savu maizi un būsiet paēduši un dzīvosiet mierīgi savā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Un Es došu mieru zemei, ka jūs gulēsiet, un nebūs, kas biedina; un Es atņemšu visus niknos zvērus no zemes, un zobenam nebūs iet pa jūsu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Un jūs saviem ienaidniekiem dzīsities pakaļ, un tie kritīs caur zobenu priekš jūsu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Pieci no jums dzenās simtus, un simts no jums dzenās desmit tūkstošus, un jūsu ienaidniekiem priekš jūsu acīm būs krist caur zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Un Es griezīšos pie jums un darīšu jūs auglīgus un jūs vairošu un uzcelšu ar jums Savu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Un jūs ēdīsiet no veca padoma, un to veco jūs nesīsiet ārā jaunajam nākot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Un Es celšu Savu dzīvokli jūsu vidū, un Mana dvēsele jūs neapniks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Un Es staigāšu jūsu vidū un būšu jums par Dievu, un jūs Man būsiet par ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Es esmu Tas Kungs, jūsu Dievs, kas jūs izvedis no Ēģiptes zemes, ka jūs nebūtu viņas vergi, un esmu saraustījis jūsu jūga saites un esmu licis jums stāvu staigāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Bet ja jūs Man neklausīsiet un visus šos baušļus nedarīsiet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Un ja jūs Manus likumus nicināsiet, un ja jūsu dvēsele Manu tiesu apniks, ka jūs nedarāt visus Manus baušļus, nicinādami Manu derību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Tad Es jums tā darīšu: Es likšu pār jums nākt izbailēm, dilonim un karstuma sērgai, kas acis aptumšo un dvēseli nomoka; un jums savu sēklu būs velti sēt, un jūsu ienaidniekiem to būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Un Es celšu Savu vaigu pret jums, ka jūs tapsiet kauti savu ienaidnieku priekšā, un jūsu nicinātājiem būs par jums valdīt, un jūs bēgsiet, kad neviens jūs nedzenā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Un ja jūs arī tad Man vēl neklausīsiet, tad Es tam vēl pielikšu septiņkārt, jūsu grēkus sodīdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Jo Es salauzīšu jūsu stipruma lepnību un jums darīšu debesi kā dzelzi un zemi kā varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Un jūs savu spēku velti tērēsiet un jūsu zeme nedos savu ražu, nedz jūsu zemes koki savus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Un ja jūs Man pretī turēsities un negribēsiet Man klausīt, tad Es uzlikšu jums vēl septiņkārtīgas mokas jūsu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Un Es jums sūtīšu meža zvērus, kas jūsu bērnus aprīs un jūsu lopus saplosīs un jūs dzīs mazumā, un jūsu ceļiem būs palikt tukšiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Un ja jūs vēl nepieņemsiet šo Manu pārmācību, bet Man pretī turēsities,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Tad Es jums arīdzan pretī turēšos un jūs sitīšu vēl septiņkārt vairāk jūsu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Jo Es vedīšu pār jums atriebšanas zobenu, kas atriebs Manu derību, un kad jūs glābsities savās pilsētās, tad Es sūtīšu mēri jūsu vidu, un jūs tapsiet nodoti ienaidnieka rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Kad Es jums atņemšu maizes padomu, tad desmit sievām jūsu maizi būs cept vienā ceplī, un jūsu maizi atdos ar svaru, un jūs ēdīsiet un nebūsiet paēduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Un ja jūs pat caur to Man neklausīsiet, bet Man turēsities pretī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Tad arī Es jums bardzībā turēšos pretī un jūs pārmācīšu vēl septiņkārt vairāk jūsu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Jo jūs ēdīsiet savu dēlu miesas un savu meitu miesas jūs ēdīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Un Es izpostīšu jūsu kalnu vietas un izdeldēšu jūsu elku stabus un metīšu jūsu maitas uz jūsu nogāztiem elkiem un jūs būsiet riebīgi Manai dvēselei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Un Es darīšu jūsu pilsētas par postažām un izpostīšu jūsu svētumus, un Es negribu ost jūsu saldo smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Es to zemi tā gribu izpostīt, ka būs iztrūcināties jūsu ienaidniekiem, kas tur dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Un Es jūs izkaisīšu starp pagāniem un izvilkšu zobenu jums pakaļ, un jūsu zeme paliks postā un jūsu pilsētas taps izpostītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tad zeme baudīs savu dusēšanu visā tai posta laikā un kamēr jūs esat ienaidnieku zemē, tad zeme dusēs un baudīs savu dusēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Visā tai posta laikā viņa dusēs, tāpēc ka tā nedusēja jūsu dusēšanas dienās, kad jūs tur dzīvojāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Un tiem atlikušiem jūsu starpā Es došu bailīgu sirdi viņu ienaidnieku zemē, ka kustošas lapas čaukstēšana tos dzīs, un tie bēgs kā no zobena un kritīs, kur dzinēja nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Un tie klups viens uz otru, kā no zobena, kur dzinēja nav, un jūs nepastāvēsiet priekš savu ienaidnieku acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Bet jūs iesiet bojā starp pagāniem, un jūsu ienaidnieku zeme jūs norīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Un tie atlikušie jūsu starpā panīks savu grēku dēļ savu ienaidnieku zemē; tur tiem savu tēvu noziegumu dēļ būs panīkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Tad tie izsūdzēs savus noziegumus un savu tēvu noziegumus un savus pārkāpumus, ar ko tie pret Mani noziegušies, un ka tie Man turējušies pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Un arī Es tiem turēšos pretī un tos likšu aizvest viņu ienaidnieku zemē; lai jel viņu neapgraizītā sirds top pazemota, un viņu noziegumi top atlīdzināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Tad Es pieminēšu Savu derību ar Jēkabu un arī Savu derību ar Īzaku un arī Savu derību ar Ābrahāmu Es pieminēšu un pieminēšu to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Un tā zeme no viņiem būs atstāta, un tā baudīs savu dusēšanu, kad no viņiem palikusi tukša, un tiem taps atlīdzināti viņu noziegumi, tādēļ un par to, ka tie Manas tiesas ir atmetuši un ka viņu dvēsele Manus likumus ir apnikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Bet arī tad vēl, kad tie būs savu ienaidnieku zemē, Es tos neesmu atmetis, nedz viņus esmu apnicis, ka tos izdeldētu, iznīcinādams Savu derību ar viņiem; jo Es esmu Tas Kungs, viņu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Bet Es pieminēšu viņiem to derību ar tiem vecajiem, ko Es esmu izvedis no Ēģiptes zemes priekš pagānu acīm, ka Es tiem būtu par Dievu, Es Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Tie ir tie likumi un tās tiesas un tie baušļi, ko Tas Kungs ir devis starp Sevi un Israēla bērniem uz Sinaī kalna caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Runā uz Israēla bērniem un saki tiem: ja kas laban Tam Kungam sola īpašu solījumu, tad lai tā dvēsele Tam Kungam ir pēc tava sprieduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Un tavs spriedums par vīrieti no divdesmit gadiem līdz sešdesmit gadiem lai ir tas spriedums: piecdesmit sudraba sēķeļi pēc svētās vietas sēķeļiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Bet ja tā ir sieviete, tad lai ir tavs spriedums trīsdesmit sēķeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Bet ja tas no pieci līdz divdesmit gadiem vecs, tad tavs spriedums par vīrieti lai ir divdesmit sēķeļi, bet par sievieti desmit sēķeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Bet ja tas vienu mēnesi līdz pieci gadiem vecs, tad tavs spriedums par vīrieti lai ir pieci sudraba sēķeļi, un par sievieti trīs sudraba sēķeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Bet ja tas sešdesmit gadus vecs un pāri, ja tas ir vīrs, tad lai ir tavs spriedums piecpadsmit sēķeļi, un ja ir sieva, desmit sēķeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Bet ja tam nav tik daudz pie rokas, kā tu viņam esi nospriedis, tad to būs vest pie priestera, un priesteris lai viņu apspriež; pēc tam, cik tā solītāja roka var pelnīt, lai priesteris viņam spriež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Un ja tas ir lops, ko Tam Kungam var upurēt, tad viss lai ir svēts, ko no tā Tam Kungam dod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'To nebūs ne mīt, ne mainīt labu ar nelabu, vai nelabu ar labu, bet ja tomēr lopu pret lopu pārmīs, tad šis un arī tas, kas pārmīts, lai ir svēts Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Un ja tas ir kāds nešķīsts lops, ko Tam Kungam nedrīkst upurēt, tad to lopu būs vest pie priestera,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Un priesterim to būs apspriest, cik labs vai nelabs tas ir, un kā priesteris ir spriedis, tā tam būs būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Un ja kas to pērkot izpirks, tad piekto tiesu lai pieliek pie tā, kā tu esi apspriedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Un ja kas savu namu svētī, ka tas Tam Kungam lai ir svēts, tad priesterim to būs apspriest, cik labs vai nelabs tas ir: kā priesteris spriedis, tā tam būs būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Un ja tas, kas savu namu ir svētījis, to grib izpirkt, tad viņam būs pielikt piekto naudas tiesu pie tā, ko tu esi spriedis; tad tas viņam piederēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Un ja kas no sava paša tīruma Tam Kungam ko laba svētīs, tad tavs spriedums lai ir pēc viņa sējuma; kur viens omers miežu top sēts, tā būs spriest uz piecdesmit sudraba sēķeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Ja viņš savu tīrumu svētīs no gaviles gada, tad viņa maksā būs pēc tava sprieduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Bet ja viņš savu tīrumu svētīs pēc gaviles gada, tad priesterim to naudu būs apspriest pēc atliekamo gadu skaita līdz gaviles gadam, un jāatņem no tava sprieduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Un ja viņš to tīrumu, ko viņš ir svētījis, pērkot izpirks, tad viņam būs pielikt piekto naudas tiesu pie tā, ko tu esi spriedis, - tad tas viņam piederēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Bet ja viņš to tīrumu neizpirks un ja to tīrumu citam pārdos, tad tam vairs nebūs tapt izpirktam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Bet tas tīrums, kad viņš nāk vaļā gaviles gadā, lai ir svēts Tam Kungam, tā kā pavisam nodots tīrums; tas priesterim būs par īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Un ja viņš Tam Kungam tīrumu ir svētījis, ko viņš pircis, kas nav no viņa paša tīruma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Tad priesterim būs spriest, kāda vērtība viņam līdz gaviles gadam, un viņam tai dienā būs dot, cik tu esi nospriedis, lai tas Tam Kungam ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Gaviles gadā tam tīrumam atkal būs tam krist, no kā viņš bija pirkts, tam, kam tā zeme īpaši piederēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Visa tava spriešana lai notiek pēc svētās vietas sēķeļa, vienam sēķeļim ir divdesmit ģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Bet pirmdzimto no lopiem, kas Tam Kungam pieder, nevienam nebūs svētīt, vai tas ir vērsis, vai avs; - tas pieder Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Bet ja tas ir no nešķīsta lopa, tad viņam to pēc tava sprieduma būs izpirkt, un piekto tiesu pielikt klāt, un ja tas netop izpirkts, tad lai to pārdod pēc tava sprieduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Bet visu, kas (pagalam) novēlēts, ko tas Tam Kungam (pagalam) novēlēs no visa, kas tam pieder, no cilvēkiem, vai no lopiem, vai no sava paša tīruma, no tā neko nebūs pārdot nedz izpirkt; viss, kas (pagalam) novēlēts, Tam Kungam ir augsti svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Visam, kas Tam Kungam (pagalam) novēlēts no cilvēkiem, nebūs tapt izpirktam, bet nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Un visi zemes desmitie no zemes labības, no koku augļiem, pieder Tam Kungam, tie Tam Kungam ir svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Bet ja kas no saviem desmitiem ko laba pircin izpirks, tam piekto tiesu būs pielikt klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Un visi desmitie no lieliem un sīkiem lopiem, kas ar rīksti top noskaitīti, tie desmitie no visa būs Tam Kungam svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Starp nelaba un laba nekādu izmeklēšanu nebūs turēt, nedz to pārmainīt; bet ja to pārmīs, tad šis un arī tas, kas ir izmīts, būs svēts; to nebūs izpirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Tie ir tie baušļi, ko Tas Kungs Mozum pavēlējis priekš Israēla bērniem uz Sinaī kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Un Tas Kungs runāja uz Mozu Sinaī tuksnesī, saiešanas teltī, pirmā dienā, otrā mēnesī, otrā gadā pēc viņu iziešanas no Ēģiptes zemes, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Uzņemiet visas Israēla bērnu draudzes pulku pēc viņu ciltīm, viņu tēvu namiem, skaitīdami visu to ļaužu vārdus, kas ir no vīriešu kārtas, pēc viņu galvām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Kas divdesmit gadus un pāri ir, visus, kas Israēla starpā iet karā, tos tev būs skaitīt pēc viņu pulkiem, tev un Āronam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Lai arī līdz ar jums ir no ikkatras cilts viens vīrs, kas ir virsnieks pār savu tēvu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Šie nu ir to vīru vārdi, kam pie jums būs stāvēt. No Rūbena: Elicurs, Šedeūra dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'No Sīmeana: Šelumiēls, Curi-Šadaja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'No Jūda: Nahšons, Aminadaba dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'No Īsašara: Nataneēls, Cuāra dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'No Zebulona: Eliabs, Ķelona dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'No Jāzepa bērniem, no Efraīma: Elišams, Amiuda dēls, no Manasus: Eamliēls, Pedacura dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'No Benjamina: Abidans, Sideona dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'No Dana: Ahiēzars, Ami-Šadaja dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'No Ašera: Paģiēls, Okrana dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'No Gada: Eliazavs, Deguēļa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'No Naftalus: Ahirus, Enana dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Šie ir tie draudzes runas vīri, virsnieki pār savu tēvu ciltīm, virsnieki pār Israēla tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Tad Mozus un Ārons ņēma šos vīrus, kā tie ar vārdiem ir nosaukti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Un sapulcēja visu draudzi pirmā dienā, otrā mēnesī, un tie pierakstījās cilts rakstos pēc savām ciltīm, pēc saviem tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, pēc savām galvām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Kā Tas Kungs Mozum bija pavēlējis, un tā viņš tos skaitīja Sinaī tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Tad Rūbena, Israēla pirmdzimušā, bērni, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, kam vārdi tapa skaitīti pēc savām galvām, visi no vīriešu kārtas no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Tie tika skaitīti Rūbena ciltī četrdesmit un seši tūkstoši un pieci simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'No Sīmeana bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, kas no tiem tapa skaitīti, pēc vārdu skaita, pēc savām galvām, visi no vīriešu kārtas no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Tie tika skaitīti Sīmeana ciltī piecdesmit deviņi tūkstoši un trīssimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'No Gada bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Tie tika skaitīti Gada ciltī četrdesmit pieci tūkstoši sešsimt un piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'No Jūda bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Tie tika skaitīti Jūda ciltī septiņdesmit četri tūkstoši un seši simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'No Īsašara bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Tie tika skaitīti Īsašara ciltī piecdesmit četri tūkstoši un četri simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'No Zebulona bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Tie tika skaitīti Zebulona ciltī piecdesmit septiņi tūkstoši un četri simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'No Jāzepa bērniem, no Efraīma bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Tie tika skaitīti Efraīma ciltī četrdesmit tūkstoši un piecsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'No Manasus bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Tie tika skaitīti Manasus ciltī trīsdesmit divi tūkstoši un divi simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'No Benjamina bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Tie tika skaitīti Benjamina ciltī trīsdesmit pieci tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'No Dana bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Tie tika skaitīti Dana ciltī sešdesmit divi tūkstoši un septiņsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'No Ašera bērniem, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Tie tika skaitīti Ašera ciltī četrdesmit un viens tūkstotis un pieci simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Naftalus bērni, viņu dzimumi pēc savām ciltīm, pēc savu tēvu namiem, pēc vārdu skaita, no divdesmit gadiem un pāri, visi, kas gāja karā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Tie tika skaitīti Naftalus ciltī piecdesmit trīs tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Šie ir tie skaitītie, ko skaitījuši Mozus un Ārons un Israēla virsnieki, divpadsmit vīri, - ikviens bija pār savu tēvu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Un viss viņu skaits no Israēla bērniem pēc tēvu namiem, no divdesmit gadiem un pāri, visi, kas no Israēla gāja karā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Visi tie skaitītie bija sešsimt trīs tūkstoši un piecsimt piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Bet Leviti pēc savu tēvu cilts netapa pie tiem pieskaitīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Jo Tas Kungs bija uz Mozu runājis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Levja cilti vien tev nebūs skaitīt, nedz viņu pulku pieņemt pie Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Bet tu iecel Levitus pār liecības telti un pār visiem viņas rīkiem un pār visu, kas tai pieder; tiem būs to telti nest un visus viņas rīkus, un viņiem būs pie tās kalpot un ap to telti apmesties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Un kad telts pacelsies, tad Levitiem to būs noārdīt, un kad telts apmetīsies, tad Levitiem to būs uzcelt; bet ja kāds svešinieks pieiet, tam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Un Israēla bērniem būs apmesties ikvienam pie sava lēģera un ikvienam pie sava karoga pēc saviem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Bet Levitiem būs apmesties ap liecības dzīvokli, ka nekāda dusmība nenāk pār Israēla bērnu draudzi; tāpēc Levitiem būs sargāt liecības dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Un Israēla bērni darīja pēc visa, tā kā Tas Kungs Mozum bija pavēlējis; tā tie darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Israēla bērniem lēģeri būs apmest, ikvienam apakš sava karoga, pēc savu tēvu nama zīmēm, visapkārt saiešanas teltij pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Pret rīta pusi būs apmesties Jūda lēģera karogam pēc saviem pulkiem, un Nahšonam, Aminadaba dēlam, Jūda bērnu virsniekam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Tā pulks un viņa skaitītie bija septiņdesmit četri tūkstoši un sešsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Un pie viņa klāt būs apmesties Īsašara ciltij, un Nataneēlim, Cuāra dēlam, Īsašara bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Tā pulks un viņa skaitītie bija piecdesmit četri tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Un Zebulona ciltij un Eliabam, Helona dēlam, Zebulona bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Tā pulks un viņa skaitītie bija piecdesmit septiņi tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Visi Jūda lēģera skaitītie bija simts astoņdesmit seši tūkstoši un četrsimt pēc saviem pulkiem; tiem būs pirmiem celties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Rūbena lēģera karogam būs turēties pret dienasvidu pēc saviem pulkiem, un Elicuram, Šedeūra dēlam, Rūbena bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Tā pulks un viņa skaitītie bija četrdesmit seši tūkstoši un piecsimti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Un pie viņa klāt būs apmesties Sīmeana ciltij, un Šelumiēlim, Curi-Šadaja dēlam, Sīmeana bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Tā pulks un viņa skaitītie bija piecdesmit deviņi tūkstoši un trīs simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Un blakām Gada ciltij un Eliazavam, Regueļa dēlam, Gada bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Tā pulks un viņa skaitītie bija četrdesmit pieci tūkstoši sešsimt un piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Visi Rūbena lēģera skaitītie bija simts piecdesmit viens tūkstotis četrsimt piecdesmit pēc saviem pulkiem, un tiem būs otriem celties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Pēc tam saiešanas telts lai ceļas ar Levitu lēģeri lēģeru starpā; kā tie apmetās, tā tiem būs celties, ikvienam savā vietā, pēc saviem karogiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Efraīma lēģera karogam būs būt pret vakariem pēc saviem pulkiem, un Elišamam, Amiuda dēlam, Efraīma bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Tā pulks un viņa skaitītie bija četrdesmit tūkstoši un piecsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Un pie viņa klāt Manasus cilts un Gamaliēls, Pedacura dēls, Manasus bērnu virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Tā pulks un viņa skaitītie bija trīsdesmit divi tūkstoši un divi simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Un tad Benjamina cilts un Abidans, Gideona dēls, Benjamina bērnu virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Tā pulks un viņa skaitītie bija trīsdesmit pieci tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Visi Efraīma lēģera skaitītie bija simts astoņi tūkstoši un simts pēc saviem pulkiem, un tiem būs celties trešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Dana lēģera karogam būs būt pret ziemeļiem pēc saviem pulkiem, un Ahiēzaram, Ami-Šadaja dēlam, Dana bērnu virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Tā pulks bija sešdesmit divi tūkstoši un septiņsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Un pie viņa klāt lai apmetās Ašera cilts, un Paģiēls, Okrana dēls, Ašera bērnu virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Tā pulks un viņa skaitītie bija četrdesmit viens tūkstotis un piecsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Un tad Naftalus cilts un Ahira, Enana dēls, Naftalus bērnu virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Tā pulks un viņa skaitītie bija piecdesmit trīs tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Visi Dana lēģera skaitītie bija simts piecdesmit septiņi tūkstoši sešsimt; tiem būs pēdīgiem celties pēc saviem karogiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Šie ir Israēla bērnu skaitītie pēc savu tēvu namiem; visi bija sešsimt trīs tūkstoši piecsimt un piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Bet Leviti netapa skaitīti Israēla bērnu starpā, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Un Israēla bērni darīja visu, ko Tas Kungs Mozum bija pavēlējis; tā tie apmetās pēc saviem karogiem, un tā tie cēlās, ikviens pēc savas cilts, pēc savu tēvu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Šie nu ir Ārona un Mozus dzimumi, tai dienā, kad Tas Kungs runāja uz Mozu Sinaī kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Un šie ir Ārona dēlu vārdi: tas pirmdzimtais Nadabs un Abijus, Eleazars un Ītamars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Šie ir Ārona dēlu vārdi, kas bija svaidīti priesteri, kas bija iesvētīti, kalpot priestera amatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Bet Nadabs un Abijus nomira Tā Kunga priekšā, kad tie svešu uguni bija nesuši Tā Kunga priekšā Sinaī tuksnesī; un tiem nebija dēlu; bet Eleazars un Ītamars bija priesteri, Ārona, sava tēva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Un Tas Kungs runāja uz Mozu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Pieved Levja cilti un stādi to priestera Ārona priekšā, lai tie viņam kalpo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Lai tie kopj viņa kopšanu un visas draudzes kopšanu priekš saiešanas telts, stāvēdami telts kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Un lai tie glabā visus saiešanas telts rīkus un kopj visu Israēla bērnu kopšanu, stāvēdami telts kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Un dod tos Levitus Āronam un viņa dēliem; tie viņam pavisam ir atdoti no Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Bet Āronu un viņa dēlus tev būs iecelt, lai tie kopj savu priestera amatu, bet svešiniekam, kas pieies, būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Un Tas Kungs runāja uz Mozu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Redzi, tos Levitus Es esmu ņēmis no Israēla bērnu vidus visu pirmdzimušo vietā, kas māti atplēš, no Israēla bērniem, un tie Leviti lai Man pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Jo visi pirmdzimtie Man pieder no tās dienas, kad Es visus pirmdzimušos kāvu Ēģiptes zemē; Es Sev esmu svētījis visus pirmdzimušos Israēla starpā no cilvēkiem līdz lopiem; tie Man lai pieder, - Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Un Tas Kungs runāja uz Mozu Sinaī tuksnesī un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Skaiti Levja dēlus pēc viņu tēvu namiem, pēc viņu ciltīm; visus no vīriešu kārtas, kam viens mēnesis un pāri, tos tev būs skaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Un Mozus tos skaitīja pēc Tā Kunga vārda, kā viņam bija pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Šie nu ir Levja bērni ar saviem vārdiem: Geršons un Kehāts un Merarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Un šie ir Geršona dēlu vārdi pēc viņu ciltīm: Libnus un Zimeūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Un Kehāta bērni pēc savām ciltīm: Amrams un Jecears, Hebrons un Uzijels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Un Merarus dēli pēc savām ciltīm: Maēlus un Muzus. Šās ir Levitu ciltis pēc savu tēvu namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'No Geršona bija Libniešu cilts un Zimiešu cilts; šīs ir Geršoniešu ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Viņu skaitītie, visi no vīriešu kārtas, vienu mēnesi un vecāki, to skaits bija septiņi tūkstoši un pieci simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Geršoniešu cilts apmetās aiz tā dzīvokļa pret vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Un Geršoniešu tēva nama virsnieks bija Eliazavs, Laēļa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Un Geršona dēli apkopa pie saiešanas telts to telti, viņas apsegu un saiešanas telts durvju priekškaramo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Un pagalma gardīnes un durvju priekškaramo pagalmā, kas tam dzīvoklim un altārim visapkārt līdz ar viņu virvēm, un visu, kas tur darāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Un no Kehāta ir Amramiešu cilts un Jeceariešu cilts un Hebroniešu cilts un Uziēliešu cilts; šīs ir Kehātiešu ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Skaits visiem, kas no vīriešu kārtas, vienu mēnesi un vecāki, bija astoņi tūkstoši un seši simti, kas kopa svētuma kopšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Kehāta dēlu cilts apmetās klāt pie tā dzīvokļa pret dienasvidus pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Un Kehātiešu ciltīm tēvu nama virsnieks bija Elicafans, Uzijeļa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Un tie apkopa to šķirstu un to galdu un to lukturi un tos altārus un svētās vietas rīkus, ar ko to darbu dara, un to priekškaramo un visu, kas tur darāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Un Levitu virsnieku virsnieks bija Eleazars, Ārona dēls, tas priesteris, uzraugs tiem, kas kopj svētās vietas kopšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'No Merarus ir Maēliešu cilts un Muziešu cilts. Šīs ir Merariešu ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Un viņu skaitītie, visi no vīriešu kārtas, vienu mēnesi un vecāki, bija seši tūkstoši un divi simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Un Merariešu ciltīm tēvu nama virsnieks bija Curiēls, Abikaīļa dēls, tie apmetās klāt pie tā dzīvokļa pret ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Un Merarus dēli uzraudzīja un kopa tā dzīvokļa galdus un viņa kārtis un viņa stabus un viņa kājas un visus viņa rīkus un visu, kas tur darāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Un arī pagalma stabus visapkārt un viņu kājas un viņa naglas un viņa virves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Un tie, kas apmetās dzīvokļa priekšā pret rītiem, priekš saiešanas telts pret austrumu, bija Mozus un Ārons ar saviem dēliem, kopdami svētuma kopšanu priekš Israēla bērniem. Bet svešiniekam, kas tur pieiet, būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Viss Levitu skaits, ko Mozus un Ārons pēc viņu ciltīm skaitīja uz Tā Kunga pavēli, visi, kas no vīriešu kārtas vienu mēnesi un pāri, bija divdesmit divi tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Un Tas Kungs runāja uz Mozu: skaiti visus Israēla bērnu pirmdzimušos no vīriešu kārtas, kam viens mēnesis un pāri, un izdabū viņu vārdu skaitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Un Levitus tev būs ņemt priekš manis (Es esmu Tas Kungs) visu pirmdzimušo Israēla bērnu vietā, un Levitu lopus visu pirmdzimušo Israēla bērnu lopu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Un Mozus skaitīja, kā Tas Kungs tam bija pavēlējis, visus Israēla bērnu pirmdzimušos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Un visi pirmdzimušie no vīriešu kārtas pēc vārdu skaita, kas vienu mēnesi un vecāki, kā tie tapa skaitīti, bija divdesmit divi tūkstoši divi simti septiņdesmit un trīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Un Tas Kungs runāja uz Mozu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Ņem Levitus visu Israēla bērnu pirmdzimto vietā un Levitu lopus viņu lopu vietā; jo tiem Man būs piederēt. Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Bet par tiem divsimt septiņdesmit trim, kam būs tapt izpirktiem, kas pie Israēla bērnu pirmdzimtiem pāri ir par tiem Levitiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Par ikvienu galvu tev būs ņemt piecus sudraba sēķeļus, pēc svētās vietas sēķeļa; - viens sēķeļis ir divdesmit ģeras,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Un to naudu tev būs dot Āronam un viņa dēliem, to naudu, ar ko tie pārējie izpirkti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Tad Mozus ņēma to izpirkšanas naudu no tiem, kas bija pāri par tiem Levitu izpirktiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'No Israēla bērnu pirmdzimtiem viņš ņēma to naudu, tūkstoš trīssimt sešdesmit un piecus sēķeļus, pēc svētās vietas sēķeļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Un Mozus deva to izpirkšanas naudu Āronam un viņa dēliem pēc Tā Kunga vārda, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Un Tas Kungs runāja uz Mozu un uz Āronu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Uzņem no Levja dēlu vidus Kehāta dēlu skaitu, pēc viņu ciltīm, pēc viņu tēvu namiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Tos, kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, visus, kas iestājās kalpošanā, savu darbu darīt pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Šis lai ir Kehāta dēlu darbs saiešanas teltī: tas visusvētākais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Kad lēģeris ceļas, tad Āronam un viņa dēliem būs nākt un noņemt to priekškaramo, kas priekš visusvētākās vietas karājās, un ar to apsegt liecības šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Un tiem uz to būs uzlikt apsegu no roņu ādām, un uz to uzklāt pazilu deķi, un tiem būs pielikt viņa nesamās kārtis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Un pāri pār Dieva maizes galdu tiem arī būs izklāt pazilu deķi, un tur uzlikt tās bļodas un karotes un kannas un lejamos kausus, un tai maizei, kas vienmēr tur jāliek, būs uz tā palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Un pāri tiem būs izklāt deķi no karmezīna un to apsegt ar apsegu no roņu ādām un pielikt tās nesamās kārtis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Tad tiem būs ņemt pazilu deķi un apsegt to spīdošo lukturi un viņa eļļas lukturīšus un viņa dzēšamos rīkus un visus viņa eļļas traukus, ar ko pie tā jākalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Un tiem to ar visiem viņa rīkiem būs ielikt apsegā no roņu ādām un to likt uz tām nesamām kārtīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Un pāri pār zelta altāri tiem būs izklāt pazilu deķi, un to apsegt ar apsegu no roņu ādām un pielikt viņa nesamās kārtis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Un tiem būs ņemt visus amata rīkus, ar ko tiem svētā vietā jākalpo, un tos ielikt pazilā deķī un tos apsegt ar apsegu no roņu ādām un likt uz tām nesamām kārtīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Un tiem tos pelnus no altāra būs noslaucīt un purpura deķi pāri izklāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Un tur būs uzlikt visus viņa rīkus, ar ko tiem pie viņa jākalpo, kvēpināmos traukus, dakšas, lāpstas un slacināmos traukus, visus altāra rīkus, un tiem pāri būs izklāt apsegu no roņu ādām un pielikt viņa nesamās kārtis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Kad nu Ārons un viņa dēli lēģerim ceļoties būs pabeiguši apsegt to svēto vietu un visus svētuma rīkus, tad pēc tam Kehāta dēliem būs nākt un to nest, bet tiem nebūs to svētumu aizskart, ka nemirst; tas ir Kehāta dēliem jānes pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Un Eleazars, priestera Ārona dēls, lai ir uzraugs par luktura eļļu un par to smaržīgo kvēpināmo un par dienišķo ēdamo upuri un svaidāmo eļļu; lai ir uzraugs par visu dzīvokli un visu, kas tur ir, par to svētumu un viņa rīkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Sargājaties, ka Kehāta radu cilts netop izdeldēta no Levitu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Bet tā jums būs viņiem darīt, ka tie dzīvo un nemirst, kad tiem jāpieiet pie tā visusvētākā. Āronam un viņa dēliem būs nākt, tos nolikt ikvienu pie sava darba un pie sava nesamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Bet viņi paši lai neieiet pat ne acumirkli skatīties to svētumu, ka nemirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Uzņem arī Geršona dēlu skaitu pēc viņu tēvu namiem, pēc viņu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, tos tev būs skaitīt, visus, kas iestājās kalpošanā, savu darbu darīt pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Šis ir Geršoniešu radu darbs, kalpot un nest:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Tiem būs nest tā dzīvokļa deķus un saiešanas teltī, viņas apsegu un to roņu ādas apsegu, kas virsū uz tās un saiešanas telts durvju apsegu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Un pagalma gardīnes un vārtu apsegu tai pagalmā, kas ap dzīvokli un ap altāri, un viņu virves un visus viņu darba rīkus, visu, kas darāms, to tiem būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Pēc Ārona un viņa dēlu pavēles lai notiek visa Geršoniešu dēlu kalpošana pie visa, kas tiem jānes, un pie visiem viņu darbiem, un jums uz tiem būs raudzīt, ka tie visu, kas tiem jānes, ņem vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tas ir Geršoniešu dēlu radu darbs saiešanas teltī, un viņu kalpošana lai stāv apakš Ītamara, priestera Ārona dēla, rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Merarus dēlus tev būs skaitīt pēc viņu ciltīm, pēc viņu tēvu namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, tos tev būs skaitīt, visus, kas iestājās kalpošanā, savu darbu darīt pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Un to viņiem būs kopt un nest pēc visa sava amata pie saiešanas telts: dzīvokļa galdus un viņa aizšaujamās kārtis un viņa stabus un viņa kājas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Līdz ar apkārtējiem pagalma stabiem un viņu kājām un naglām un virvēm, ar visiem viņu rīkiem, ar visu, kas tiem darāms. Un visus rīkus, kas tiem jākopj un jānes, tos tiem iedodiet ar vārdu un skaitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tā lai ir Merariešu radu kalpošana, viss viņu darbs pie saiešanas telts, apakš Ītamara, priestera Ārona dēla, rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Tad Mozus un Ārons un draudzes virsnieki skaitīja Kehātiešu dēlus pēc viņu ciltīm un viņu tēvu namiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, visus, kas iestājās kalpošanā, savu darbu darīt pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Tad viņu skaits bija pēc viņu ciltīm divi tūkstoši septiņsimti un piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Šie ir Kehāta cilšu skaitītie, visi, kas kalpo pie saiešanas telts, ko Mozus un Ārons bija skaitījuši pēc Tā Kunga vārda caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Un Geršona dēlu skaitītie pēc viņu ciltīm un pēc viņu tēvu namiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, visi, kas iestājās kalpošanā, savu darbu darīt pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Un viņu skaitītie pēc viņu ciltīm, pēc viņu tēvu namiem bija divi tūkstoši sešsimt trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Šie ir Geršona cilšu skaitītie, visi, kas kalpoja saiešanas teltī, ko Mozus un Ārons skaitīja pēc Tā Kunga pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Un Merarus dēlu skaitītie pēc viņu ciltīm, pēc viņu tēvu namiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, visi, kas iestājās kalpošanā, savu darbu darīt pie saiešanas telts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Viņu skaitītie pēc viņu ciltīm bija trīs tūkstoši divi simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Šie ir Merarus cilšu skaitītie, ko Mozus un Ārons skaitījuši pēc Tā Kunga pavēles caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Visi tie Leviti, ko Mozus un Ārons un Israēla virsnieki ir skaitījuši pēc viņu ciltīm un pēc viņu tēvu namiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Kam trīsdesmit gadi un pāri līdz piecdesmitam gadam, visi kas iestājās kalpošanā, kalpot un nest pie saiešanas telts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Viņu skaitītie bija astoņi tūkstoši piecsimt un astoņdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Pēc Tā Kunga pavēles tie tapa nolikti caur Mozu, ikviens pie sava darba, pie sava nesamā, un tapa skaitīti, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Pavēli Israēla bērniem, ka tiem no lēģera būs izraidīt visus spitālīgos, un visus, kam miesa pil, un visus, kas palikuši nešķīsti pie miroņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Tāpat vīrus kā sievas tev būs izraidīt; ārā no lēģera tev tos būs izraidīt, ka tie neapgāna savus lēģerus, kur Es dzīvoju viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Un Israēla bērni tā darīja un tos izraidīja no lēģera ārā; kā Tas Kungs uz Mozu bija runājis, tā Israēla bērni darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Runā uz Israēla bērniem: ja vīrs vai sieva padara kaut kādu cilvēku grēku, noziegdamies pret To Kungu, un šī dvēsele paliek vainīga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Tad tiem būs izsūdzēt savu grēku, ko tie darījuši, un savu noziegumu atlīdzināt ar pilnu maksu, un piekto daļu pielikt klāt un tam dot, pret ko tie noziegušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Bet ja tam vīram nav izpircēja, kam to noziegumu varētu maksāt, tad lai tas maksājamais parāds pieder Tam Kungam priekš priestera, bez tā salīdzināšanas auna, kas tam par salīdzināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Tāpat visi cilājamie upuri no visādām lietām, ko Israēla bērni svētī un pie priestera nes, lai viņam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Un ikkatra svētīta lieta lai viņam krīt; ja kas priesterim ko laba dod, tas lai viņam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Runā uz Israēla bērniem un saki tiem: ja sieva no sava vīra novēršas un noziegdamies pret to noziedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Un ja viens vīrs pie viņas guļ un to pieguļ, un viņas vīram tas būtu nezināms, un tā to būtu slēpusi, ka apgānījusies, un liecinieka pret viņu nebūtu, un viņa nebūtu pieķerta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Un neuzticības kaislība viņu pārņemtu un viņš neuzticētu savai sievai, un tā ir apgānījusies, vai ja tā neuzticības kaislība viņu pārņemtu un viņš neuzticētu savai sievai, un tā nav apgānījusies, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Tad tam vīram savu sievu būs vest pie priestera un atnest upuri priekš viņas, desmito tiesu no ēfas miežu miltu; tam nebūs eļļu uzliet, nedz vīraka uzlikt, jo tas ir viens kaislības upuris, piemiņas ēdamais upuris, atgādināt noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Un priesterim viņu būs pievest un nostādīt Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Un priesterim būs ņemt svētu ūdeni mālu traukā, un pīšļus no tā dzīvokļa grīdas priesterim būs ņemt un ielikt tai ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Tad priesterim to sievu būs nostādīt Tā Kunga priekšā un atsegt tās sievas galvu un to piemiņas upuri likt viņas rokās, tas ir viens kaislības upuris; un tas rūgtais lāsta ūdens lai ir priestera rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Un priesterim būs to sievu zvērināt un uz to sacīt: ja neviens vīrs pie tevis nav gulējis, un ja tu neesi novērsusies no sava vīra uz nešķīstību, tad tu paliksi vesela no šī rūgtā lāsta ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Bet ja tu no sava vīra esi novērsusies un apgānījusies, un cits vīrs pie tevis gulējis, un ne tavs vīrs vien,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Un priesterim būs to sievu zvērināt ar to lāsta zvērestu un sacīt uz to sievu: lai Tas Kungs tevi dara par lāstu un zvērestu starp taviem ļaudīm, ka Tas Kungs tavai ciskai liek izdilt un tavam vēderam uztūkt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Un šis lāsta ūdens tavās iekšās lai ieiet un dara, ka vēders uztūkst un ciska izdilst. Tad tai sievai būs sacīt: Āmen, Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Un priesterim šos lāstus būs rakstīt grāmatā un noskalot ar to rūgto ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Un to rūgto lāsta ūdeni viņam tai sievai būs dot dzert, ka tas lāsta ūdens viņai ieiet ar rūgtumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Un priesterim no tās sievas rokas būs ņemt to kaislības upuri un to līgot priekš Tā Kunga un likt uz altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Un priesterim no tā ēdamā upura būs ņemt pilnu sauju par piemiņas upuri, un to iededzināt uz altāra, un tad viņam to ūdeni tai sievai būs dot dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Kad nu viņš tai to ūdeni būs devis dzert, tad notiks: ja tā ir sagānījusies un pret savu vīru noziegdamies ir noziegusies, ka tas lāsta ūdens viņai paliks par rūgtumu un viņas vēders uztūks un viņas ciska izdils, un tā sieva būs par lāstu starp saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Bet ja tā sieva nav sagānījusies, bet šķīsta, tad viņa paliks vesela un auglīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Šis ir tas bauslis par neuzticības kaislību, kad laulāta sieva ir novērsusies no sava vīra un sagānījusies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Vai kad vīru pārņem neuzticības kaislība un viņš neuztic savai sievai, tad tam tā sieva jāved Tā Kunga priekšā, un priesterim jādara pēc visa šī baušļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Un tas vīrs būs nenoziedzīgs pie tā nozieguma, bet tā sieva nesīs savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Runā uz Israēla bērniem un saki tiem: kad vīrs vai sieva apsolīsies palikt par nazīru svētīdamies Tam Kungam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Tad tam būs sargāties no vīna un stipra dzēriena, vīna etiķi un stipra dzēriena etiķi tam nebūs dzert, nedz ko citu, kas taisīts no vīna ogām, nedz baudīt ne zaļas, nedz žāvētas vīna-ogas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Visu sava solījuma laiku tam nekā nebūs baudīt ko taisa no vīna koka, no kodola līdz mizai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Visu sava nazīra solījuma laiku dzenamam nazim nebūs iet pār viņa galvu; kamēr tās dienas top piepildītas, cik viņš Tam Kungam solījies, tikmēr viņam būs būt svētam un savas galvas matus audzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Visu to laiku, ko viņš Tam Kungam solījies, viņam nebūs iet pie miroņa;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Ne pie sava tēva, ne pie savas mātes, ne pie sava brāļa, ne pie savas māsas; tam nebūs pie tiem sagānīties, kad tie miruši, jo nazīra solījums Dievam ir uz viņa galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Visā sava nazīra solījuma laikā viņam būs būt svētam priekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Un ja pie viņa viens nejauši, piepeši nomirtu, ka viņš savu svētīto galvu sagānītu, tad viņam savas šķīstīšanas dienā būs nocirpt savu galvu, septītā dienā viņam to būs nocirpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Un astotā dienā viņam būs nest divas ūbeles vai divus jaunus baložus pie priestera priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Un priesterim vienu būs sataisīt par grēka upuri un otru par dedzināmo upuri, un viņu salīdzināt tādēļ, ka viņš ir apgrēkojies pie miroņa; tā viņam savu galvu būs svētīt tai dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Pēc tam lai viņš atkal uzņem sava solījuma dienas Tam Kungam un pienes gada vecu jēru par nozieguma upuri; bet tām pirmajām dienām būs būt par velti, tāpēc ka viņa nazīra svētums ir sagānīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Un šis ir tas nazīra bauslis: tai dienā, kad viņa solījuma laiks ir piepildīts, tad to būs vest pie saiešanas telts durvīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Un lai viņš savu upuri upurē Tam Kungam, vienu gada vecu jēru bez vainas par dedzināmo upuri un vienu gada vecu aitiņu bez vainas par grēku upuri un vienu aunu bez vainas par pateicības upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Un kurvi ar neraudzētu maizi, raušus no smalkiem miltiem, kas aplaistīti ar eļļu, un neraudzētas, ar eļļu aptraipītas karašas, līdz ar tiem ēdamiem upuriem un dzeramiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Un priesteris lai to nes Tā Kunga priekšā un sataisa viņa grēku upuri un viņa dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Un lai viņš sataisa to aunu Tam Kungam par pateicības upuri ar to kurvi neraudzētu raušu, un priesteris lai sataisa viņa ēdamo upuri un viņa dzeramo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Un nazīram priekš saiešanas telts durvīm būs nodzīt savu svētīto galvu, un ņemt savus svētītos galvas matus un likt tai ugunī, kas ir apakš tā pateicības upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Un priesterim būs ņemt tā auna vārīto priekšpleci un vienu neraudzētu rausi no tā kurvja un vienu neraudzētu karašu un būs to likt uz tā nazīra rokām, pēc tam, kad viņš savus matus visapkārt ir nodzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Un priesterim tos būs līgot par līgojamu upuri priekš Tā Kunga; tā ir svēta dāvana priesterim, līdz ar tām līgojama upura krūtīm un ar to cilājama upura priekšpleci; un pēc tas nazīrs var dzert vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Šis ir tas bauslis par nazīru, kas Tam Kungam savu upuri solījis savas svētīšanās dēļ, bez tam, ko viņa roka vēl iespēj; pēc sava solījuma, ko viņš solījis, tam būs darīt pēc tā svētīšanās baušļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Runā uz Āronu un viņa dēliem un saki: tā jums būs svētīt Israēla bērnus un uz tiem sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Tas Kungs lai tevi svētī un lai tevi pasargā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Tas Kungs lai apgaismo Savu vaigu pār tevi un lai tev ir žēlīgs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Tas Kungs lai paceļ Savu vaigu uz tevi un lai tev dod mieru!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Tā tiem būs likt Manu vārdu uz Israēla bērniem, un Es tos svētīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Un notika tai dienā, kad Mozus bija pabeidzis to dzīvokli uzcelt un to bija svaidījis un iesvētījis ar visiem viņa rīkiem, un to altāri un visus viņa rīkus, - kad viņš to bija svaidījis un iesvētījis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Tad Israēla virsnieki, savu tēvu namu galvinieki, upurēja; šie bija cilšu virsnieki, kas bija pār tiem skaitītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Un tie nesa savu upuri Tā Kunga priekšā: sešus apklātus ratus un divpadsmit vēršus, vienus ratus uz diviem virsniekiem un vienu vērsi uz ikvienu; tos tie atveda pie tā dzīvokļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Ņem tos no viņiem un lai tie ir par kalpošanu saiešanas teltij, un dod tos Levitiem, ikvienam pēc viņa kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Tā Mozus ņēma tos ratus un vēršus un tos deva Levitiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Divus ratus un četrus vēršus viņš deva Geršona dēliem pēc viņu kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Un četrus ratus un astoņus vēršus viņš deva Merarus dēliem pēc viņu kalpošanas, apakš Ītamara, priestera Ārona dēla, rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Bet Kehāta dēliem viņš nedeva nekā, jo tiem pienācās kalpot svētumā, uz pleciem tiem bija jānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Un tie virsnieki upurēja uz altāra iesvētīšanu; tai dienā, kad tas tapa svaidīts, tie virsnieki pienesa savus upurus altāra priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Un Tas Kungs sacīja uz Mozu: ikvienam virsniekam savā dienā būs pienest savus upurus uz altāra iesvētīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Kas pirmā dienā pienesa savu upuri, tas bija Nahšons, Aminadaba dēls, no Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Un viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamo upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri; šis bija Nahšona, Aminadaba dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Otrā dienā upurēja Netaneēls, Cuara dēls, Īsašara virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Viņš pienesa par upuri vienu sudraba bļodu, kas svēra simts un trīsdesmit sēķeļus, vienu sudraba kausu no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abus pilnus kviešu miltu, aplietu ar eļļu, par ēdamu upuri,-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Vienu zelta kausu no desmit sēķeļiem, pilnu ar kvēpināmām zālēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Vienu vērsēnu no lieliem lopiem, vienu aunu, vienu gada vecu jēru par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Vienu āzi par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Un par pateicības upuri divus vēršus, piecus aunus, piecus āžus, piecus gada vecus jērus: tas bija Netaneēļa, Cuara dēla upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Trešā dienā upurēja Zebulona bērnu virsnieks, Eliabs, Helona dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs, par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Eliaba, Helona dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Ceturtā dienā upurēja Rūbena bērnu virsnieks, Elicurs, Šedeūra dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs, par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Elicura, Šedeūra dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Piektā dienā upurēja Sīmeana bērnu virsnieks, Šelumiēls, Curi-Šadaja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Šelumiēļa, Curi-Šadaja dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Sestā dienā upurēja Gada bērnu virsnieks, Eliāsavs, Deguēļa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Eliāzava, Deguēļa dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Septītā dienā upurēja Efraīma bērnu virsnieks, Elišamus, Amiuda dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs, par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Elišama, Amiuda dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Astotā dienā upurēja Manasus bērnu virsnieks Gamaliēls, Pedacura dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Gamaliēla, Pedacura dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'devītā dienā upurēja Benjamina bērnu virsnieks, Ābidans, Gideona dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Ābidana, Gideona dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Desmitā dienā upurēja Dana bērnu virsnieks, Ahiēzars, Ami-Šadaja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Ahiēzara, Ami-Šadaja dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Vienpadsmitā dienā upurēja Ašera bērnu virsnieks, Paģiēls, Okrana dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Paģiēļa, Okrana dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Divpadsmitā dienā upurēja Naftalus bērnu virsnieks, Ahirus, Enana dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Viņa upuris bija viena sudraba bļoda, kas svēra simts un trīsdesmit sēķeļus, viens sudraba kauss no septiņdesmit sēķeļiem, pēc svētās vietas sēķeļa, - abi pilni kviešu miltu, aplietu ar eļļu, par ēdamu upuri, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Viens zelta kauss no desmit sēķeļiem, pilns kvēpināmu zāļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Viens vērsēns no lieliem lopiem, viens auns, viens gada vecs jērs par dedzināmo upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Viens āzis par grēku upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Un par pateicības upuri divi vērši, pieci auni, pieci āži, pieci gada veci jēri: šis bija Ahirus, Enana dēla, upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Šīs bija altāra iesvētīšanas dāvanas tai dienā, kad tas tapa svaidīts no Israēla virsniekiem: divpadsmit sudraba bļodas, divpadsmit sudraba kausi, divpadsmit zelta kausi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Ikviena sudraba bļoda svēra simts un trīsdesmit sēķeļus, ikviens sudraba kauss svēra septiņdesmit sēķeļus, viss tas trauku sudrabs bija divi tūkstoši un četrsimt sēķeļi, pēc svētās vietas sēķeļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Divpadsmit zelta kausi, pilni kvēpināmu zāļu, ikviens kauss svēra desmit sēķeļus, pēc svētās vietas sēķeļa, viss tas kausu zelts bija simts un divdesmit sēķeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Visi liellopi par dedzināmo upuri bija divpadsmit vērsēni, divpadsmit auni, divpadsmit gadu veci jēri ar savu ēdamo upuri un divpadsmit āži par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Un visi liellopi par pateicības upuri bija divdesmit četri vērši, sešdesmit auni, sešdesmit āži, sešdesmit gada veci jēri. Šīs bija altāra iesvētīšanas dāvanas pēc tam, kad tas bija svaidīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Un kad Mozus iegāja saiešanas teltī ar Viņu runāt, tad tas dzirdēja balsi uz sevi runājam no tā salīdzināšanas vāka, kas bija uz liecības šķirsta starp tiem diviem ķerubiem, un Viņš uz to runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Runā uz Āronu un saki tam: kad tu tos eļļas lukturīšus iededzināsi, tad lai tie septiņi eļļas lukturīši spīd uz luktura priekšpusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Un Ārons tā darīja; luktura priekšpusē viņš iededzināja viņa eļļas lukturīšus, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Un tas lukturis bija taisīts no tīra zelta, un viņa kāts, un viņa puķes bija izkaltas; pēc tās priekšzīmes, ko Tas Kungs Mozum bija rādījis, - tā viņš to lukturi bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Ņem Levitus no Israēla bērnu vidus un šķīsti tos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Un tā tev būs darīt viņus šķīstot: uzslaki tiem grēku ūdeni, un lai tiem dzenamais nazis iet pār visu viņu miesu, un lai tie mazgā savas drēbes un šķīstās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Un viņiem būs ņemt vienu vērsīti no liellopiem ar viņa ēdamo upuri, kviešu miltus, aplietus ar eļļu, un otru vērsēnu no liellopiem tev būs ņemt par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Un Levitus tev būs vest saiešanas telts priekšā un visu Israēla bērnu draudzi sapulcināt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Un Levitus tev būs vest Tā Kunga priekšā, un Israēla bērniem būs likt savas rokas uz Levitiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Un Āronam Levitus būs līgot par līgojamu upuri priekš Tā Kunga no Israēla bērniem, ka tiem būs stāvēt Tā Kunga kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Un Levitiem būs likt savas rokas uz to vēršu galvām; pēc upurē tu vienu par grēku upuri un vienu par dedzināmo upuri Tam Kungam, Levitus salīdzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Un Levitus tev būs vest priekš Ārona un priekš viņa dēliem un tos līgot par līgojamu upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Un Levitus no Israēla bērnu vidus tev būs atšķirt, ka Leviti ir Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Un pēc tam lai Leviti nāk kalpot saiešanas teltī. Tā tev tos būs šķīstīt un tos līgot par līgojamu upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Jo tie Man pavisam ir nodoti no Israēla bērnu vidus, Es tos sev esmu ņēmis no Israēla bērniem visu pirmdzimušo vietā, kas māti atplēš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Jo Man pieder visi Israēla bērnu pirmdzimušie, gan starp cilvēkiem gan starp lopiem, tai dienā, kad Es visus pirmdzimušos Ēģiptes zemē situ, Es tos Sev esmu svētījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Un Es Levitus esmu ņēmis visu pirmdzimušo vietā no Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Un Es Levitus esmu devis Āronam un viņa dēliem par dāvanu no Israēla bērniem, lai tie stāv Israēla bērnu kalpošanā pie saiešanas telts un salīdzina Israēla bērnus, ka nekāda mocība neuznāk Israēla bērniem, ja Israēla bērni paši aiztiktu to svētumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Tad Mozus un Ārons un visa Israēla bērnu draudze tā darīja ar Levitiem; kā Tas Kungs Mozum bija pavēlējis par Levitiem, tā Israēla bērni ar viņiem darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Un Leviti šķīstījās un mazgāja savas drēbes, un Ārons tos līgoja par līgojamu upuri priekš Tā Kunga, un Ārons tos salīdzināja, lai paliek šķīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Un pēc tam Leviti nāca, darīt savus darbus saiešanas teltī priekš Ārona un priekš viņa dēliem; kā Tas Kungs Mozum bija pavēlējis par Levitiem, tā tie ar viņiem darīja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Tas ir tas, kas Levitiem pienākas; kam divdesmit un pieci gadi un pāri, tiem būs iestāties kalpošanā, savu darbu darīt pie saiešanas telts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Bet kam piecdesmit gadi un pāri, tam no šīs kalpošanas būs izstāties un vairs nebūs kalpot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Bet būs pie rokas būt saviem brāļiem saiešanas teltī pie apkopšanas, bet pašā kalpošanā tam nebūs kalpot. Tā tev būs darīt ar Levitiem viņu amatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Un Tas Kungs runāja uz Mozu Sinaī tuksnesī otrā gadā pēc viņu iziešanas no Ēģiptes zemes, pirmā mēnesī, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Lai nu Israēla bērni tur Pasa svētkus savā noliktā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Četrpadsmitā dienā šinī mēnesī ap vakara laiku jums tos būs turēt savā noliktā laikā, - pēc visiem viņu likumiem un pēc visām viņu tiesām jums tos būs turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Tad Mozus runāja uz Israēla bērniem, lai tie turētu Pasa svētkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Un tie turēja Pasa svētkus, pirmā mēneša četrpadsmitā dienā ap vakara laiku, Sinaī tuksnesī; kā Tas Kungs Mozum bija pavēlējis, tā Israēla bērni darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Un bija vīri, kas pie miroņa bija palikuši nešķīsti, tā ka tie tai dienā Pasa svētkus nevarēja turēt, tādēļ tie piegāja pie Mozus un pie Ārona tai pašā dienā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Un tie vīri uz viņu sacīja: mēs pie miroņa esam palikuši nešķīsti, kāpēc mums to būs pieciest, ka mēs Tā Kunga upuri savā noliktā laikā nevaram upurēt kopā ar Israēla bērniem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Un Mozus uz tiem sacīja: pagaidiet, lai es dzirdu, ko Tas Kungs jums pavēlēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Runā uz Israēla bērniem un saki: kad kāds no jums vai no jūsu pēcnākamiem pie miroņa ir palicis nešķīsts, vai kāds ir tālā ceļā, tad viņam tomēr Tam Kungam būs turēt Pasa svētkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Otrā mēnesī, četrpadsmitā dienā ap vakara laiku viņiem tos būs turēt, ar neraudzētu maizi un ar rūgtām zālēm tiem to būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Tiem no tā nekā nebūs atlicināt līdz rītam, nedz tam kādu kaulu salauzt; pēc visiem Pasa svētku likumiem viņiem tos būs turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Bet kas ir šķīsts un nav uz ceļa un atraujas no Pasa svētku turēšanas, tā dvēsele lai top izdeldēta no saviem ļaudīm, tāpēc ka viņš Tā Kunga upuri savā noliktā laikā nav upurējis; tāds cilvēks lai nes savu grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Un ja pie jums kāds svešinieks piemājo un Tam Kungam Pasa svētkus tur, tad lai tos tur pēc Pasa svētku likumiem un pēc viņu tiesām; vienāds likums lai jums ir, tāds svešiniekam kā zemes iedzīvotājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Un tai dienā, kad tas dzīvoklis tapa uzcelts, tas padebesis apklāja liecības telts dzīvokli, un vakarā pār to dzīvokli bija uguns spožums līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tā notikās bez mitēšanās; padebesis to apklāja un nakts laikā bija uguns spožums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Un kad tas padebesis pacēlās no telts, tad arī Israēla bērni pēc tam cēlās, un tai vietā, kur tas padebesis palika, tur Israēla bērni apmetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Pēc Tā Kunga vārda Israēla bērni cēlās, un pēc Tā Kunga vārda Israēla bērni apmetās; visu to laiku, kamēr tas padebesis uz tā dzīvokļa palika, tie palika uz vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Un kad tas padebesis daudz dienas uz tā dzīvokļa palika, tad Israēla bērni ņēma vērā Tā Kunga pavēli un necēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Un kad tas padebesis maz dienu palika uz tā dzīvokļa, - tad pēc Tā Kunga vārda tie palika uz vietas un pēc Tā Kunga vārda tie cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Bet kad tas padebesis no vakara līdz rītam stāvēja un rītā pacēlās, tad viņi cēlās; vai bija diena, vai nakts, kad tas padebesis pacēlās, tad arī viņi cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Bet ja tas padebesis divas dienas, vai vienu mēnesi vai ilgāki uz tā dzīvokļa stāvēja un uz tā palika, tad Israēla bērni palika uz vietas un necēlās, un kad tas cēlās, tad arī viņi cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Pēc Tā Kunga vārda tie apmetās un pēc Tā Kunga vārda tie cēlās; tie ņēma vērā Tā Kunga pavēles, kā Tas Kungs caur Mozu bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Taisi sev divas trumetes(taures), no sudraba tev tās būs izkalt, un tās lai ir priekš draudzes sasaukšanas un priekš lēģera pacelšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Kad ar viņām abām pūtīs, tad visai draudzei pie tevis būs sapulcēties priekš saiešanas telts durvīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Bet ja ar vienu vien pūtīs, tad tiem lieliem kungiem, tiem virsniekiem pār Israēla tūkstošiem pie tevis būs sapulcēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Kad jūs ar varenu skaņu pūšat, tad tiem lēģeriem būs celties, kas pret rītiem apmetušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Bet kad jūs ar varenu skaņu otrā kārtā pūšat, tad tiem lēģeriem būs celties, kas pret dienas vidiem apmetušies; ar varenu skaņu būs pūst, kad viņiem jāceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Bet to draudzi sapulcinājot jums būs pūst, tomēr ne ar varenu skaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Un Ārona dēliem, tiem priesteriem, būs tās trumetes pūst, un tas lai jums ir par likumu mūžīgi pie jūsu pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Un kad jūs savā zemē iesiet karā pret saviem ienaidniekiem, kas jūs spiež, tad jums būs pūst ar varenu skaņu; tad Tas Kungs, jūsu Dievs, jūs pieminēs, un jūs tapsiet izglābti no saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Un savā līksmības laikā un savos svētkos un savos jaunos mēnešos jums arīdzan trumetes būs pūst, pie saviem dedzināmiem upuriem un pie saviem pateicības upuriem, lai jūsu Dievs jūs piemin. Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Un notikās otrā gadā, otrā mēnesī, divdesmitā mēneša dienā, ka tās padebesis pacēlās no tā liecības dzīvokļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Un Israēla bērni cēlās pēc saviem pulkiem no Sinaī tuksneša, un tas padebesis nolaidās Pārana tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Tā tie pirmoreiz cēlās pēc Tā Kunga vārda caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Pa priekšu cēlās Jūda bērnu lēģera karogs, pēc saviem pulkiem, un pār viņa pulku bija Nahšons, Aminadaba dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Un pār Īsašara bērnu cilts pulku bija Netaneēls, Cuara dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Un pār Zebulona bērnu cilts pulku bija Eliabs, Helona dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Un tas dzīvoklis tapa nocelts, un Geršona bērni un Merarus bērni cēlās un nesa to dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Pēc tam cēlās Rūbena lēģera karogs pēc saviem pulkiem, un pār viņa pulku bija Elicurs, Šedeūra dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Un pār Sīmeana bērnu cilts pulku bija Šelumiēls, Curi-Šadaja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Un pār Gada bērnu cilts pulku bija Eliazavs, Deguēļa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Tad Kehāta bērni cēlās un nesa tās svētuma lietas, un tas dzīvoklis tika uzcelts, kamēr šie atnāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Un pēc tam cēlās Efraīma bērnu lēģera karogs pēc saviem pulkiem, un pār viņa pulku bija Elišamus, Amiuda dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Un pār Manasus bērnu cilts pulku bija Gamaliēls, Pedacura dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Un pār Benjamina bērnu cilts pulku bija Abidans, Gideona dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Tad cēlās Dana bērnu lēģera karogs visu lēģeru beidzamā galā pēc saviem pulkiem, un pār viņa pulku bija Ahiēzars, Ami-Šadaja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Un pār Ašera bērnu cilts pulku bija Paģiēls, Okrana dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Un pār Naftalus bērnu cilts pulku bija Ahirus, Enana dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tā Israēla bērni cēlās pēc saviem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Un Mozus sacīja uz Hobabu, Reguēļa, tā Midijanieša, dēlu, Mozus sievas brāli: mēs ejam uz to vietu, par ko Tas Kungs ir sacījis: “To Es jums došu.” Nāc līdz ar mums, mēs tev gribam labu darīt, jo Tas Kungs Israēlim labumu apsolījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Bet viņš sacīja: es neiešu, bet es gribu iet uz savu zemi un pie saviem radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Bet tas viņam sacīja: neatstājies no mums, jo tāpēc ka tu zini, kur mums tuksnesī jāapmetas, tad tev būs mums būt par aci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Un notiks, ja tu mums iesi līdz un mums nāks tas labums, ko Tas Kungs mums darīs, tad mēs tev arīdzan gribam labu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Un tie cēlās no Tā Kunga kalna treju dienu gājumu, un Tā Kunga derības šķirsts viņiem gāja priekšā treju dienu gājumu, viņiem rādīt dusamu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Un Tā Kunga padebesis bija pār viņiem dienas laikā, kad tie no lēģera cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Un notikās, kad tas šķirsts cēlās, tad Mozus sacīja: celies, Kungs, lai Tavi ienaidnieki top izkaisīti un Tavi nīdētāji lai bēg priekš Tava vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Un kad tas dusēja, tad viņš sacīja: atgriezies, Kungs, pie Israēla pulku tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Un notikās, kad tie ļaudis Tā Kunga ausīs kurnēja, tad Tas Kungs to dzirdēja, un Viņa bardzība iekarsa, un Tā Kunga uguns iedegās pret viņiem un rija lēģera galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Tad tie ļaudis brēca uz Mozu. Un Mozus lūdza To Kungu, un tas uguns noslāpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Un tās vietas vārdu nosauca Tabeēra (degums), tāpēc ka Tā Kunga uguns starp tiem bija iededzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Un pulks visādu pienācēju, kas bija viņu starpā, palika kārīgi, un arī Israēla bērni raudāja atkal sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Kas mums dos gaļu ēst? Mēs pieminam tās zivis, ko Ēģiptes zemē velti ēdām, gurķus, melones, lokus, sīpolus un ķiplokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Bet nu mūsu dvēsele ir iztvīkusi, jo nav nekā kā vien tas manna priekš mūsu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Un manna bija tā kā koriandra sēklas un izskatījās kā bdelliums(sveķi).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Un tie ļaudis skrēja šurp un turp un to sakrāja un mala dzirnavās, vai sagrūda piestās, un to vārīja podos un taisīja no tā raušus, un viņa smaka bija tā kā eļļas raušu smaka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Un kad rasa pa naktīm nokrita lēģerī, tad tas manna nokrita līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Tad Mozus dzirdēja tos ļaudis raudam ar viņu saimēm, ikvienu priekš sava dzīvokļa durvīm, un Tā Kunga bardzība iedegās ļoti, un arī Mozum tas nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Un Mozus sacīja uz To Kungu: kāpēc Tu Savam kalpam esi darījis tik grūti? Un kāpēc es neesmu atradis Tavās acīs žēlastību, ka Tu man esi uzlicis visu šo ļaužu nastu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Vai es visus šos ļaudis esmu nesis savās miesās? Vai es tos esmu dzemdējis, ka Tu man gribi sacīt: nes tos savā klēpī, tā kā auklētājs nes zīdāmu bērnu, uz to zemi, ko Tu viņu tēviem esi zvērējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Kur es gaļas varētu dabūt, ko dot visiem šiem ļaudīm? Jo tie raud pret mani sacīdami: dod mums gaļas ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Es viens pats visus šos ļaudis nevaru nest, jo tas man ir visai grūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Un ja Tu man tā gribi darīt, tad nokauj labāk mani, ja es žēlastību esmu atradis Tavās acīs, tad neliec man tā redzēt savu nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Un Tas Kungs sacīja uz Mozu: sapulcini Man septiņdesmit vīrus no Israēla vecajiem, kurus tu zini, ka tie ir ļaužu vecaji un viņu virsnieki, un ved Man tos priekš saiešanas telts, un lai tie tur stāv pie tevis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Tad Es nonākšu un ar tevi tur runāšu, un no Tā Gara, kas uz tevis, Es gribu ņemt un likt uz viņiem, un viņiem būs līdz ar tevi nest to ļaužu nastu, ka tā tev vienam nav jānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Un uz tiem ļaudīm tev būs sacīt: svētījaties uz rīta dienu, tad jūs ēdīsiet gaļu, jo jūs priekš Tā Kunga ausīm esat raudājuši sacīdami: kas mums dos gaļu ēst? Jo mums ir labi klājies Ēģiptes zemē. Tāpēc Tas Kungs jums dos gaļu ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Jūs neēdīsiet vienu nedz divas dienas nedz piecas dienas nedz desmit dienas nedz divdesmit dienas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Bet veselu mēnesi, tiekams tā jums caur nāsīm izies un jūs to apniksiet, tāpēc ka jūs To Kungu esat atmetuši, kas ir jūsu vidū, un priekš Viņa esat raudājuši sacīdami: kāpēc mēs esam izgājuši no Ēģiptes zemes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Un Mozus sacīja: sešsimt tūkstoši ir šo ļaužu kājnieki, kā vidū es esmu, un Tu saki, es tiem došu gaļu, un tiem būs ēst veselu mēnesi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Vai tad mazus un lielus lopus priekš tiem būs nokaut, ka tiem būtu diezgan? Jeb vai visas jūras zivis būs sapulcināt, ka tiem būtu diezgan?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Bet Tas Kungs runāja uz Mozu: vai tad Tā Kunga roka ir paīsināta? Tagad tev būs redzēt, vai Mans Vārds tev notiks, vai ne.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Un Mozus izgāja un runāja Tā Kunga vārdus uz tiem ļaudīm un sapulcināja septiņdesmit vīrus no to ļaužu vecajiem un nostādīja tos ap saiešanas telti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Tad Tas Kungs nonāca padebesī un runāja uz to un ņēma no Tā Gara, kas uz viņa bija, un lika to uz tiem septiņdesmit vecajiem, un notikās, kad Tas Gars uz tiem dusēja, tad tie runāja kā pravieši, bet pēc vairs ne.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Un divi vīri bija palikuši lēģerī, tā viena vārds bija Eldads un tā otra vārds bija Medads, un Tas Gars uz tiem dusēja, jo tie bija starp tiem uzrakstītiem, jebšu nebija nogājuši uz to telti, un tie runāja kā pravieši lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Tad viens puisis tecēja un teica Mozum un sacīja: Eldads un Medads runā lēģerī kā pravieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Un Jozuas, Nuna dēls, Mozus sulainis, viens no viņa izlasītiem jaunekļiem, atbildēja un sacīja: mans kungs, Mozu, aizliedz tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Tad Mozus uz to sacīja: vai tev deg mani aizstāvēt? Ak kaut Tā Kunga ļaudis visi būtu pravieši un kaut Tas Kungs Savu Garu pār tiem (visiem) dotu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Pēc tam Mozus aizgāja atpakaļ lēģerī ar Israēla vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Tad vējš cēlās no Tā Kunga un atveda paipalas no jūras un izkaisīja tās pa lēģeri, šeit vienas dienas gājumu un tur vienas dienas gājumu visapkārt ap lēģeri, un tās bija līdz divām olektīm augstumā pa zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Tad tie ļaudis cēlās cauru dienu un cauru nakti un cauru otru dienu un lasīja paipalas, un kam maz bija, tas bija salasījis desmit gomorus, un tie tās klādami izklāja priekš sevis ap lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Tā gaļa viņiem vēl bija zobos, pirms tā bija apēsta, tad Tā Kunga bardzība iedegās pret tiem ļaudīm un Tas Kungs sita tos ļaudis ar ļoti grūtu mocību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Tāpēc tās vietas vārdu sauca kārības kapenes, jo tur tie apraka tos kārīgos starp tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'No tām kārības kapenēm tie ļaudis aizgāja uz Hacerotu un apmetās Hacerotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Tad Mirjame un Ārons runāja pret Mozu tās etiopiešu sievas dēļ ko viņš bija ņēmis, jo viņš vienu etiopieti bija ņēmis par sievu, un tie sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Vai Tas Kungs tikai caur Mozu vien runājis? Vai tas nav arī caur mums runājis? Un Tas Kungs to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Bet tas vīrs Mozus bija ļoti lēnprātīgs, vairāk nekā visi cilvēki virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Tad Tas Kungs piepeši runāja uz Mozu un uz Āronu un uz Mirjami: nāciet ārā jūs trīs pie saiešanas telts; un tie trīs nāca ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Tad Tas Kungs nonāca padebeša stabā un stāvēja saiešanas telts durvīs; un viņš sauca Āronu un Mirjami, un tie abi nāca ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Un Viņš sacīja: klausiet jel Manu vārdu! Ja jūsu starpā viens pravietis, tad Es, Tas Kungs, viņam parādos parādīšanā, caur sapni Es ar viņu runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Tāds nav Mans kalps Mozus, kas visā Manā namā ir uzticīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Muti pret muti Es ar viņu runāju un ne caur tumšiem vārdiem, bet redzēdams viņš redz Tā Kunga vaigu; kādēļ tad jūs neesat bijušies runāt pret Manu kalpu, pret Mozu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Un Tā Kunga bardzība iedegās pret tiem, un Viņš aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Un tas padebesis atstājās no telts virsas, un redzi, Mirjame bija spitālīga kā sniegs, un Ārons uzlūkoja Mirjami, un redzi, tā bija spitālīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Tad Ārons sacīja uz Mozu: lūdzams, mans kungs, nepielīdzini mums tos grēkus, ar ko mēs ģeķīgi esam darījuši un ar ko esam apgrēkojušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Lai viņa nav kā tas, kas nedzīvs iziet no mātes miesām, kam puse no miesas jau saēsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Tad Mozus brēca uz To Kungu un sacīja: Ak Dievs, lūdzams, dziedini jel viņu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Un Tas Kungs sacīja uz Mozu: kad viņas tēvs spļaudams viņas vaigā būtu spļāvis, vai tā septiņas dienas nekaunētos? Lai tā septiņas dienas ārā aiz lēģera top ieslēgta un pēc tam lai tā atkal top pieņemta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Tad Mirjame tapa ieslēgta ārā aiz lēģera septiņas dienas, un tie ļaudis negāja tālāki, kamēr Mirjame atkal tapa pieņemta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Bet pēc tam tie ļaudis cēlās no Hacerotas un apmetās Pārana tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Un Tas Kungs runāja uz Mozu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Izsūti vīrus, kas izlūko Kanaāna zemi, ko Es Israēla bērniem dodu; no ikvienas cilts tev būs sūtīt vienu vīru, kas visi ir virsnieki viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Tad Mozus tos izsūtīja no Pārana tuksneša pēc Tā Kunga vārda; visi tie vīri bija Israēla bērnu virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Un šie ir viņu vārdi: no Rūbena cilts Šamuūs, Zakura dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'No Sīmeana cilts Sāfats, Horija dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'No Jūda cilts Kālebs, Jefunna dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'No Īsašara cilts Jiģeāls, Jāzepa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'No Efraīma cilts Hošejs, Nuna dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'No Benjamina cilts Paltus, Rapus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'No Zebulona cilts Gadiēls, Sodija dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'No Jāzepa cilts, (tas ir) no Manasus cilts Gadus, Susus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'No Dana cilts Amiēls, Ģemalus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'No Ašera cilts Seturs, Mihaēla dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'No Naftalus cilts Nakbus, Vafsus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'No Gada cilts Geuēls, Māhus dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Šie ir to vīru vārdi, ko Mozus sūtīja, to zemi izlūkot. Un Mozus nosauca Hošeju, Nuna dēlu, (par) Jozua.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Un Mozus tos sūtīja, Kanaāna zemi izlūkot, un tiem sacīja: ceļaties šeit no dienvidu(Negeba) puses un ejat augšām uz tiem kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Un apraugāt to zemi, kāda tā ir, un tos ļaudis, kas tur dzīvo, vai tie ir stipri, vai vāji, vai maz, vai daudz;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Un kāda tā zeme, kur tie dzīvo, vai tā laba vai nelaba, un kādas pilsētas tur ir, kur tie dzīvo, vai tie dzīvo lēģeros vai stiprās pilīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Un kāda tā zeme, vai tauka, vai liesa, vai koki tur ir, vai ne. Esiet droši un ņemat līdz no zemes augļiem; jo tas notika pašā pirmo vīna ogu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Un tie aizgāja un izlūkoja to zemi no Cin tuksneša līdz Rehobai, kur iet uz Amatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Un tie aizgāja no dienvidu(Negeba) puses un nāca Hebronē, un tur bija Aķimans, Zezaūs un Talmaūs, Enaka bērni. Bet Hebrones pilsēta bija celta septiņus gadus priekš Coana Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Un tie nāca pie Eškoles upes un nogrieza tur vienu zaru ar vīna ķekaru, to divi nesa uz nesamās kārts, - arī granātābolus un vīģes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Šī vieta tapa nosaukta Eškoles upe, pēc tā vīna ķekara, ko Israēla bērni tur bija nogriezuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Un tie griezās atpakaļ no tās zemes izlūkošanas pēc četrdesmit dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Un tie gāja un nāca pie Mozus un pie Ārona un pie visas Israēla bērnu draudzes, Pārana tuksnesī uz Kādešu, un atnesa vēsti viņam un visai draudzei un rādīja tās zemes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Un tie viņam teica un sacīja: mēs tai zemē esam nākuši, kurp tu mūs esi sūtījis, un patiesi, tur tek piens un medus, un šis ir viņas auglis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Bet tik stipri ļaudis tai zemē dzīvo un tās pilsētas ir stipras un ļoti lielas; mēs tur arī Enaka bērnus esam redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalekieši dzīvo tai zemē pret dienvidiem, bet Hetieši un Jebusieši un Amorieši dzīvo kalnos, un Kanaānieši dzīvo pie jūras un Jardānes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Tad Kālebs apklusināja tos ļaudis Mozus priekšā un sacīja: iedami iesim augšup un mēs to ieņemsim, jo mēs to tiešām uzvarēsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Bet tie vīri, kas viņam bija līdz gājuši, sacīja: mēs nevaram iet pret šiem ļaudīm, jo tie ir stiprāki nekā mēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Tā tie izpauda nelabu slavu no tās zemes, ko tie bija izlūkojuši, pie Israēla bērniem, sacīdami: tā zeme, ko esam pārstaigājuši izlūkot, ir tāda zeme, kas savus iedzīvotājus aprij, un visi ļaudis, ko mēs tur esam redzējuši, ir vīri no liela garuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Mēs tur arī milžu ļaudis esam redzējuši, tos Enaka dēlus no milžu cilts; mēs bijām savās acīs tā kā siseņi, un tādi paši mēs bijām viņu acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Tad visa draudze cēlās un pacēla savu balsi, un tie ļaudis raudāja to nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Un visi Israēla bērni kurnēja pret Mozu un pret Āronu, un visa draudze uz tiem sacīja: kaut Ēģiptes zemē būtu nomiruši, jeb kaut šinī tuksnesī būtu nomiruši!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Un kāpēc Tas Kungs mūs ved uz šo zemi, ka mums būs krist caur zobenu, mūsu sievām un mūsu bērniņiem būs palikt par laupījumu? Vai mums nebūtu labāki, griezties atpakaļ uz Ēģiptes zemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Un tie sacīja viens uz otru: celsim sev virsnieku un griezīsimies atpakaļ uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Tad Mozus un Ārons nokrita uz savu vaigu priekš visa Israēla bērnu draudzes pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Un Jozuas, Nuna dēls, un Kālebs, Jefunna dēls, no tiem zemes izlūkiem, saplēsa savas drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Un tie runāja uz visu Israēla bērnu draudzi un sacīja: tā zeme, ko esam pārstaigājuši izlūkot, ir ļoti varen laba zeme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Ja Tam Kungam ir labs prāts pie mums, tad Viņš mūs novedīs uz šo zemi un mums to dos, zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Tikai nesaceļaties pret To Kungu un nebīstaties no tās zemes ļaudīm; tie mums būs kā maizes kumoss. Viņu patvērums no tiem ir atstājies, un Tas Kungs ir ar mums; nebīstaties no tiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Tad visa draudze sacīja, ka tie akmeņiem jānomētā. Bet Tā Kunga godība parādījās saiešanas teltī priekš visiem Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Un Tas Kungs runāja uz Mozu: cik ilgi šie ļaudis Mani kaitina? Un cik ilgi tie negrib Man ticēt, pie visām tām zīmēm, ko Es viņu vidū esmu darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Es tos sitīšu ar mēri un tos izdeldēšu, un tevi darīšu par lielāku un stiprāku tautu, nekā viņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Bet Mozus sacīja uz To Kungu: taču ēģiptieši dzirdējuši, ka Tu caur Savu spēku šos ļaudis no viņiem esi izvedis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Un sacījuši šās zemes iedzīvotājiem; tie dzirdējuši, ka Tu, ak Kungs, esi starp šiem ļaudīm, ka Tu, Kungs, acīm esi redzams, ka Tavs padebesis pār tiem stāv, un Tu viņu priekšā ej padebeša stabā dienu un uguns stabā nakti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Ja Tu nu šos ļaudis nokautu tā kā vienu vienīgu vīru, - tad tie pagāni, kas Tavu slavu dzirdējuši, tiešām runātu un sacītu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Tāpēc ka Tas Kungs šos ļaudis nevarēja ievest tai zemē, ko Viņš tiem bija zvērējis, Viņš tos ir nokāvis tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Nu tad, lai Tā Kunga spēks paaugstinājās, kā Tu esi runājis un sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Tas Kungs ir pacietīgs un no lielas žēlastības, piedodams noziegumus un pārkāpumus, bet Viņš arī nepamet nesodītus, piemeklēdams tēvu grēkus pie bērniem līdz trešam un ceturtam augumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Piedod jel šo ļaužu noziegumu pēc Savas lielās žēlastības un tā kā Tu šiem ļaudīm esi piedevis no Ēģiptes zemes līdz šim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Un Tas Kungs sacīja: esmu piedevis pēc tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Un nu, tik tiešām kā Es dzīvoju un visa pasaule taps pilna Tā Kunga godības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Visi tie vīri, kas ir redzējuši Manu godību un Manas zīmes, ko Es esmu darījis Ēģiptes zemē un tuksnesī, un Mani nu ir kārdinājuši desmitkārt un Manai balsij nav paklausījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Tiem nebūs redzēt to zemi, ko Es viņu tēviem esmu zvērējis: nevienam no tiem, kas Mani apkaitinājuši, to nebūs redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Bet Savu kalpu Kālebu, tāpēc ka cits gars ar to ir bijis, un ka tas pareizi Mani klausījis, to Es gribu ievest tai zemē, kur viņš ir bijis, un viņa dzimumam to būs iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Amalekieši un Kanaānieši dzīvo lejā. Griežaties rītā atpakaļ un ejat uz tuksnesi pa niedru jūras ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Cik ilgi tā būs ar šo ļauno draudzi, kas pret Mani kurn? Es esmu dzirdējis Israēla bērnu kurnēšanu, ar ko tie pret Mani kurn.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Saki tiem: tik tiešām kā Es dzīvoju, saka Tas Kungs, Es jums tā darīšu, kā jūs Manās ausīs esat runājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Šinī tuksnesī būs krist jūsu miesām, un visiem jūsu skaitītiem, pēc visiem jūsu pulkiem, tiem, kas divdesmit gadus veci un pārāki, kas pret Mani esat kurnējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Jums nebūs ieiet tai zemē, par ko Es Savu roku esmu pacēlis, lai tur mājojiet, bet tik vien Kālebam, Jefunna dēlam, un Jozuam, Nuna dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Un jūsu bērnus, par ko jūs sacījāt, tie būšot par laupījumu, tos Es ievedīšu, un tie dabūs pazīt to zemi, ko jūs nicinādami esat atmetuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Bet jums un jūsu miesām būs krist šinī tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Un jūsu bērni būs gani tuksnesī četrdesmit gadus, un tiem būs jūsu maucību nest, tiekams jūsu miesas bojā iet tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Pēc to četrdesmit dienu skaita, cik ilgi jūs to zemi esat izlūkojuši, ikvienu dienu skaitot par gadu, jums būs nest savus noziegumus četrdesmit gadus; ka jūs atzīstat, kas tas ir, kad Es no jums nogriežos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Es Tas Kungs esmu runājis, Es to tiešām darīšu visai šai ļaunai draudzei, kas pret Mani sametusies; šinī tuksnesī tiem būs iet bojā, un tur tiem būs nomirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Tad nu tie vīri, ko Mozus bija sūtījis, to zemi izlūkot, kas bija atgriezušies atpakaļ un visu draudzi pret viņu rīdinājuši uz kurnēšanu un izpauduši nelabu slavu par to zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Tie vīri, kas tai zemei darījuši nelabu slavu, nomira caur vienu mocību Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Bet Jozuas, Nuna dēls, un Kālebs, Jefunna dēls, palika dzīvi no tiem vīriem, kas bija nogājuši, to zemi izlūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Un Mozus runāja šos vārdus uz visiem Israēla bērniem; tad tie ļaudis ļoti bēdājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Un tie cēlās agri un devās augšā uz kalnu galu sacīdami: redzi, šeit esam un iesim uz to vietu, par ko Tas Kungs sacījis; jo mēs esam grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Bet Mozus sacīja: kāpēc jūs pārkāpjat Tā Kunga vārdu? Jo tas jums neizdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Neejat uz augšu, Tas Kungs nav jūsu vidū, ka jūs netopat sakauti no saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Jo Amalekieši un Kanaānieši tur ir jūsu priekšā, un jūs kritīsiet caur zobenu; jo tāpēc ka jūs no Tā Kunga esat atkāpušies, Tas Kungs nebūs ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Tomēr tie ar pārgalvību devās uz augšu, uz kalnu galu, bet Tā Kunga derības šķirsts un Mozus neatstājās no lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Tad Amalekieši un Kanaānieši, kas uz tiem kalniem dzīvoja, nāca un tos sita un sakāva līdz Hormai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Runā uz Israēla bērniem un saki tiem: kad jūs savā zemē nāksiet, ko Es jums došu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Un jūs Tam Kungam gribat nest uguns upuri, dedzināmo upuri vai kaujamu upuri, vai pēc īpaša solījuma vai no laba prāta, vai savos noliktos svētkos, lai būtu Tam Kungam par saldu smaržu, no lieliem vai sīkiem lopiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Tad tam, kas savu upuri Tam Kungam pienes, būs upurēt ēdamu upuri no desmitās tiesas kviešu miltu, kas ir sajaukti ar ceturksni inna eļļas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Un vīnu par dzeramu upuri vienu ceturksni inna tev būs sataisīt pie tā dedzināmā upura, vai pie tā kaujamā upura, pie ikviena upurējama jēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Vai kad auns top upurēts, tev ēdamu upuri būs sataisīt no divām desmitām kviešu miltu, kas sajaukti ar trešo tiesu inna eļļas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Un vīnu par dzeramu upuri tev būs upurēt trešu tiesu inna par saldu smaržu Tam Kungam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Bet ja tu jaunu vērsi gribi sataisīt par dedzināmo upuri, vai kaujamu upuri, kāda īpaša solījuma dēļ, vai par pateicības upuri Tam Kungam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Tad pie tā jauna vērša būs pielikt ēdamu upuri, proti trīs desmitās kviešu miltu, kas sajaukti ar pusinnu eļļas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Un vīnu tev būs upurēt par dzeramu upuri, pusinnu, par uguns upuri, par saldu smaržu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Tā lai top darīts ar ikvienu vērsi vai ar ikvienu aunu vai ar jēru vai kazlēnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Pēc tā skaita, ko jūs sataisīsiet, jums tā būs darīt ar ikvienu pēc viņu skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Ikvienam iedzīvotājam šās lietas tā būs darīt, kad upurē uguns upuri par saldu smaržu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Un ja kāds svešinieks pie jums piemīt, vai ja kas jūsu starpā ir pie jūsu pēcnākamiem, un Tam Kungam par saldu smaržu grib nest uguns upuri, tam būs tā darīt, kā jūs darāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Visai draudzei lai ir vienāds likums, jums un tam svešiniekam, kas pie jums piemīt, likums mūžīgi jūsu pēcnākamiem: tā kā jūs, tāpat lai ir tas svešinieks Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Vienāda bauslība un vienāda tiesa lai ir jums un tam svešiniekam, kas pie jums piemājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Runā uz Israēla bērniem un saki tiem: kad jūs nonāksiet tai zemē, uz kurieni Es jūs vedīšu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Kad jūs ēdīsiet tās zemes maizi, tad jums Tam Kungam būs upurēt cilājamu upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Savas mīklas pirmajus, vienu karašu jums būs upurēt par cilājamu upuri, itin kā to cilājamo upuri no klona, tā jums to būs upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'No savas mīklas pirmajiem jums Tam Kungam būs dot cilājamu upuri līdz jūsu pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Un kad jūs netīši apgrēkosities un nedarīsiet visus šos baušļus, ko Tas Kungs uz Mozu ir runājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Visu, ko Tas Kungs jums caur Mozu pavēlējis, no tās dienas, kad Tas Kungs to pavēlējis, un tā projām līdz jūsu pēcnākamiem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Tad, ja draudzei nezinot un netīši tas noticis, lai visa draudze upurē vienu vērsēnu no lieliem lopiem par dedzināmo upuri, par saldu smaržu Tam Kungam, līdz ar viņa ēdamo upuri un viņa dzeramo upuri, kā pienākas, un vienu āzi par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Un priesterim būs salīdzināt visu Israēla bērnu draudzi, tad viņiem taps piedots, jo tas bija netīši grēkots; tā lai tie savu upuri nes, uguns upuri Tam Kungam, un savu grēku upuri Tā Kunga priekšā savas apgrēkošanās dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Tad visai Israēla bērnu draudzei taps piedots, un arī tam svešiniekam, kas jūsu starpā piemīt, tāpēc ka visiem ļaudīm tas grēks noticis netīši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Un ja kaut kāds netīši apgrēkotos, tam gada vecu kazu būs upurēt par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Un priesterim būs salīdzināt to, kas ar netīšu grēku apgrēkojies Tā Kunga priekšā; to lai salīdzina, tad viņam taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Tam, kas Israēla bērnu vidū ir dzimis, un tam svešiniekam, kas jūsu starpā piemīt, vienāda bauslība lai jums ir priekš tā, kas netīši apgrēkojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Bet tā dvēsele, kas kaut ko darīs pārgalvībā, vai tas jūsu starpā dzimis, vai tas svešinieks, - tas To Kungu zaimo, un tā dvēsele lai top izdeldēta no saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Jo tā ir nicinājusi Tā Kunga vārdu un pulgojusi Viņa bauslību, ar izdeldēšanu tā dvēsele pavisam lai top izdeldēta; viņas noziegums lai paliek uz viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Kad nu Israēla bērni bija tuksnesī, tad tie atrada vienu vīru malku lasām dusēšanas dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Un tie, kas viņu atrada malku lasām, to atveda pie Mozus un Ārona un pie visas draudzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Un tie to lika cietumā, jo nebija skaidri izteikts, kas ar to jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Tad Tas Kungs sacīja uz Mozu: to vīru būs nokaut, visa draudze lai viņu akmeņiem nomētā ārā aiz lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Tad visa draudze viņu izveda ārā aiz lēģera, un viņu akmeņiem nomētāja, ka tas nomira, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Runā uz Israēla bērniem un saki tiem, ka tiem sev būs taisīt pušķus drēbju stūros, līdz saviem pēcnākamiem, un pazilu auklu likt pie tiem stūru pušķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Un tos pušķus jums tāpēc būs nest, ka jūs tos uzskatot pieminat visus Tā Kunga baušļus un pēc tiem dariet, un nestaigājiet pēc sava sirds prāta un sava acu kāruma, tam pakaļ maukodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Lai jūs pieminat un darāt visus Manus baušļus un savam Dievam esiet svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Es esmu Tas Kungs, jūsu Dievs, kas jūs izvedis no Ēģiptes zemes, lai Es jums esmu par Dievu, Es Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Bet Korahs, Jeceara dēls, (šis bija Kehāta, Levja dēla, dēls), ņēma pie sevis Datanu un Abiramu, Eliaba dēlus, un Onnu, Peleta dēlu, Rūbena dēlus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Un sacēlās pret Mozu līdz ar divsimt un piecdesmit Israēla bērnu vīriem, kas bija draudzes virsnieki un sapulces runas vīri un no lielas slavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Un tie sapulcējās pret Mozu un pret Āronu un sacīja uz tiem: jums nu diezgan! Jo visa draudze ir svēta, un Tas Kungs ir viņu vidū; kāpēc jūs paaugstinājaties pār Tā Kunga draudzi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Kad Mozus to dzirdēja, tad viņš krita uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Un viņš runāja uz Korahu un uz visu viņa pulku un sacīja: rītā agri, tad Tas Kungs darīs zināmu, kas Viņam pieder, un kas ir svēts, un kas var iet pie Viņa, un kuru Viņš izvēlēs, tas varēs iet pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Dariet tā, ņemat sev kvēpināmus traukus, Korahs un viss viņa pulks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Un rītā ieliekat tanīs uguni un liekat kvēpināmās zāles tur virsū priekš Tā Kunga, un kuru Tas Kungs izvēlēs, tas lai ir svēts; nu jums diezgan! Jūs Levja bērni!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Un Mozus sacīja uz Korahu: klausāties jel, jūs Levja bērni!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Vai jums par maz, ka Israēla Dievs jūs izraudzījis no Israēla draudzes, Viņam nākt tuvu, kalpot pie Tā Kunga dzīvokļa kalpošanas un stāvēt draudzes priekšā un tai kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Viņš tev līdz ar visiem taviem brāļiem, tiem Levja bērniem, licis tuvu nākt; un nu jūs meklējat arī priestera amatu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Tādēļ tu un viss tavs pulks esiet sametušies kopā pret To Kungu; jo kas ir Ārons, ka jūs pret viņu kurnat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Un Mozus nosūtīja, aicināt Datanu un Abiramu, Eliaba dēlus, bet tie sacīja: mēs nenāksim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Vai vēl nav gan, ka tu mūs izvedis no tās zemes, kur piens un medus tek, mūs nokaut tuksnesī, ka tu arī vēl pats uzmeties mums par virsnieku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Tu mūs tiešām neesi vedis zemē, kur piens un medus tek, nedz mums devis iemantot tīrumus vai vīna dārzus, - vai tu tiem vīriem acis gribi izraut? Mēs nenāksim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Tad Mozus ļoti apskaitās un sacīja uz To Kungu: neuzlūko viņu upuri. Pat ne ēzeli es no tiem neesmu ņēmis un nevienam ļauna neesmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Un Mozus sacīja uz Korahu: tu un viss tavs pulks, nāciet rītu priekš Tā Kunga vaiga, tu un viņi un Ārons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Un ņemiet ikviens savu kvēpināmo trauku un liekat iekšā kvēpināmās zāles, un nesiet Tā Kunga priekšā ikviens savu trauku, divsimt un piecdesmit traukus, un arī tu un Ārons, ikviens savu trauku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Tad tie ņēma ikviens savu trauku un ielika uguni un uzlika virsū kvēpināmās zāles, un stāvēja priekš saiešanas telts durvīm, un tāpat Mozus un Ārons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Un Korahs sapulcēja visu draudzi pret viņiem priekš saiešanas telts durvīm. Tad Tā Kunga godība parādījās visai draudzei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Un Tas Kungs runāja uz Mozu un uz Āronu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Atšķiraties no šīs draudzes, ka Es tos acumirklī apriju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Bet tie krita uz savu vaigu un sacīja: Ak Dievs! Tu Dievs pār visas miesas gariem, - ja viens cilvēks apgrēkojies, vai Tu tāpēc dusmosies par visu draudzi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Runā uz draudzi un saki: atkāpjaties visapkārt no Koraha, Datana un Abirama dzīvokļa nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Tad Mozus cēlās un gāja pie Datana un Abirama, un viņam gāja pakaļ Israēla vecaji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Un viņš runāja uz draudzi un sacīja: atkāpjaties nost no šo bezdievīgo cilvēku dzīvokļiem un neaizskarat nekā no tā, kas viņiem pieder, ka jūs neejat bojā visu viņu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Tad tie visapkārt gāja nost no Koraha, Datana un Abirama dzīvokļa, bet Datans un Abirams iznāca ārā un stāvēja savas telts durvīs līdz ar savām sievām un dēliem un bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Un Mozus sacīja: pie tam jūs atzīsiet, ka Tas Kungs mani sūtījis, visus šos darbus darīt, ne no mana paša prāta:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Ja šie nomirs, itin kā visi citi cilvēki mirst, un taps piemeklēti, itin kā visi cilvēki top piemeklēti, tad Tas Kungs mani nav sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Bet ja Tas Kungs ko jauna darīs un zeme atvērs savu muti un tos norīs līdz ar visu, kas tiem pieder, ka tie dzīvi nogrimst ellē, tad jūs atzīsiet, ka šie cilvēki To Kungu ir nicinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Un notikās, kad viņš visus šos vārdus bija pabeidzis runāt, tad zeme apakš viņiem pāršķēlās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Un atdarīja savu muti un tos norija līdz ar viņu namiem un ar visiem cilvēkiem, kas bija pie Koraha, un ar visu viņu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Un tie dzīvi nogrima ellē ar visu, kas tiem piederēja, un zeme tos apklāja, un tie gāja bojā no draudzes vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Un viss Israēls, kas viņiem bija visapkārt, bēga viņiem brēcot, jo tie sacīja: ka mūs zeme neaprij!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Un no Tā Kunga izgāja uguns un aprija tos divsimt un piecdesmit vīrus, kas tās kvēpināmās zāles upurēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Saki priesterim Eleazaram, Ārona dēlam, lai tos kvēpināmos traukus paņem no tā deguma un to uguni izkaisa, jo tie trauki ir svēti, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Šo traukus, kas pret savām dvēselēm bija grēkojuši, lai kaļ plakanos gabalos un ar tiem lai apvelk altāri; jo tie ir upurēti priekš Tā Kunga un svētīti, un būs Israēla bērniem par zīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Tad priesteris Eleazars, ņēma tos kvēpināmos vara traukus, ko tie sadegušie bija pienesuši, un tos izkala plātīs, altārim par pārvelkamo;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Par piemiņu Israēla bērniem, lai neviens svešs, un kas nav no Ārona dzimuma, nepieietu, kvēpināt ar kvēpināmām zālēm Tā Kunga priekšā, ka tam nenotiktu, kā Koraham un kā viņa pulkam, itin kā Tas Kungs tam bija runājis caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Bet otrā dienā visa Israēla bērnu draudze kurnēja pret Mozu un pret Āronu un sacīja: jūs Tā Kunga ļaudis esat nokāvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Un kad draudze sapulcējās pret Mozu un pret Āronu, tad tie griezās uz saiešanas telti, un redzi, tas padebesis to apklāja, un Tā Kunga godība parādījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Tad Mozus un Ārons gāja uz saiešanas telti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Atkāpjaties no šās draudzes, tad Es to aprīšu acumirklī. Tad tie krita uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Un Mozus sacīja uz Āronu: ņem kvēpināmo trauku un ieliec uguni no altāra un uzliec kvēpināmās zāles virsū un ej steigšus draudzes vidū un salīdzini tos, jo bardzība no Tā Kunga ir izgājusi, un mocība ir iesākusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Un Ārons to ņēma, kā Mozus bija runājis, un skrēja draudzes vidū, un redzi, mocība bija iesākusies pie tiem ļaudīm, un viņš uzlika virsū kvēpināmās zāles un salīdzināja tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Un viņš stāvēja starp mirušiem un dzīviem; tad tā mocība tapa novērsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Un to, kas no tās mocības bija nomiruši, bija četrpadsmit tūkstoši un septiņsimt, bez tiem, kas Koraha dēļ bija miruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Un Ārons griezās atpakaļ pie Mozus priekš saiešanas telts durvīm, un tā mocība mitējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Runā uz Israēla bērniem un ņem no tiem priekš ikviena tēva nama vienu zizli, no visiem viņu virsniekiem pēc viņu tēvu namiem divpadsmit zižļus; tev ikviena vārdu būs rakstīt uz viņa zizli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Bet Ārona vārdu tev būs rakstīt uz Levja cilts zizli, jo ikvienam zizlim būs būt priekš sava tēva nama galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Un tev tos būs nolikt saiešanas teltī liecības priekšā, kur Es ar jums sanāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Un tad tā vīra zizlis, ko Es izvēlēšu, zaļos, un Es klusināšu Israēla bērnu kurnēšanu pret Mani, ar ko tie pret jums kurn.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Un Mozus runāja uz Israēla bērniem. Tad visi viņu virsnieki viņam deva ikviens virsnieks vienu zizli, pēc saviem tēvu namiem divpadsmit zižļus; tur arī Ārona zizlis bija starp viņu zižļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Un Mozus nolika tos zižļus Tā Kunga priekšā liecības teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Un otrā ritā, kad Mozus iegāja liecības teltī, tad redzi, Ārona zizlis priekš Levja nama zaļoja, un ziedi bija izplaukuši un bija nesuši mandeles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Un Mozus iznesa visus šos zižļus no Tā Kunga priekšas pie visiem Israēla bērniem, un tie to redzēja, un ikviens ņēma savu zizli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Tad Tas Kungs sacīja uz Mozu: nes Ārona zizli atpakaļ liecības priekšā, to paglabāt par zīmi pārgalvjiem; tā tev to kurnēšanu pret Mani būs apklusināt, ka tiem nav jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Un Mozus tā darīja; itin kā Tas Kungs tam bija pavēlējis, tā viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Tad Israēla bērni runāja uz Mozu: redzi, mēs mirstam, mēs ejam bojā, mēs visi ejam bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Ikviens, kas pie Tā Kunga dzīvokļa pieiet, tam jāmirst; vai tad mums patiesi būs iet bojā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Tad Tas Kungs runāja uz Āronu: tev un taviem dēliem un tava tēva namam līdz ar tevi būs nest svētās vietas noziegumu, un tev un taviem dēliem būs nest priestera amata noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Un arī savus brāļus, Levja cilti, sava tēva cilti, tev līdz ar sevi būs pievest, ka tie tev palīdz un tev kalpo; bet tev un taviem dēliem līdz ar tevi būs būt liecības telts priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Un tiem būs kopt tavu kopšanu, un visas telts kopšanu; bet pie svētās vietas rīkiem un pie altāra tiem nebūs pieiet, lai nemirst, ne viņi, ne jūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Bet tiem būs tev palīdzēt un kopt to kopšanu saiešanas teltī visā telts kalpošanā, un nevienam svešiniekam pie jums nebūs pieiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Tad nu kopjat svētās vietas kopšanu un altāra kopšanu, lai vairs nenāk bardzība pār Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Jo redzi, Es jūsu brāļus, tos Levitus, esmu ņēmis no Israēla bērniem; tie jums ir doti par dāvanu Tam Kungam, ka tiem jākalpo pie saiešanas telts kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Bet tev un taviem dēliem līdz ar tevi būs savu priestera amatu kopt visās altāra lietās un iekšpusē aiz tā priekškaramā un kalpot, jūsu priestera amatu Es jums dodu kā dāvanu. Un tam svešiniekam, kas pieiet, būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Un Tas Kungs runāja uz Āronu: un Es, redzi, Es tev esmu devis glabāt Savus cilājamos upurus; no visām Israēla bērnu svētām dāvanām Es tev tos esmu devis par daļu un taviem dēliem par tiesu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Tas lai tev pieder no tām augsti svētām dāvanām no ugunīm: visas viņu dāvanas pie visiem viņu ēdamiem upuriem un pie visiem viņu grēku upuriem un pie visiem viņu nozieguma upuriem, ko tie Man dod; augsti svētas dāvanas lai tās ir tev un taviem dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Augsti svētā vietā tev to būs ēst; visi, kas no vīriešu kārtas, lai to ēd, - tas lai tev ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Un tas lai tev pieder kā cilājams upuris no viņu dāvanām: no visiem Israēla bērnu līgojamiem upuriem Es to esmu devis tev un taviem dēliem un tavām meitām līdz ar tevi par tiesu mūžīgi; ikkatrs, kas tavā namā šķīsts, lai to ēd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'To visu labāko no eļļas un to visu labāko no vīna un no labības, viņu pirmajus, ko tiem būs Tam Kungam dot, to Es tev esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Tiem pirmiem augļiem no visa, kas ir viņu zemē, ko tiem Tam Kungam būs nest, tev būs piederēt; ikkatrs, kas tavā namā šķīsts, lai to ēd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Viss, kas iekš Israēla Dievam nolikts, lai tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Viss, kas māti atplēš, no ikvienas miesas, ko Tam Kungam atnesīs, no cilvēkiem un no lopiem, lai tev pieder; bet cilvēku pirmdzimtos pērkot lai izpērk, un nešķīsto lopu pirmdzimtos arī lai izpērk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Kas nu tos izpērk, lai tos izpērk vienu mēnesi vecus, pēc tava sprieduma, par pieciem sēķeļiem pēc svētās vietas sēķeļa (viens ir divdesmit ģeras).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Bet govs pirmdzimto vai avs pirmdzimto vai kazas pirmdzimto tev nebūs likt izpirkt, tie ir svēti, - viņu asinis tev būs slacīt uz altāri, un viņu taukus tev būs iededzināt par uguns upuri, par saldu smaržu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Un viņu gaļa lai tev pieder, itin kā tās līgojamās krūtis, un tas labais plecs, tā lai viņa tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Visus svētos cilājamos upurus ko Israēla bērni Tam Kungam pienes, Es esmu devis tev un arī taviem dēliem un tavām meitām līdz ar tevi par tiesu mūžam. Šī lai ir mūžīga sāls derība Tā Kunga priekšā tev un arī tavam dzimumam mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Un Tas Kungs sacīja uz Āronu: viņu zemē tev nebūs mantības un viņu starpā tev nebūs daļas; Es esmu tava daļa un tava manta starp Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Un redzi, Levja bērniem Es esmu devis visus desmitos iekš Israēla par daļu par viņu kalpošanu, ar ko tie kalpo saiešanas telts kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Un Israēla bērniem vairs nebūs pieiet pie saiešanas telts, ka tie neapgrēkojās un nemirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Bet Levitiem saiešanas telts kalpošanā būs kalpot, un tiem būs nest viņu noziegumus; tas lai ir likums mūžīgi pie jūsu pēcnākamiem; un starp Israēla bērniem tiem zemes daļas nebūs mantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Jo Israēla bērnu desmitos, ko tie upurē Tam Kungam par cilājamu upuri, Es esmu devis Levitiem par daļu; tādēļ Es uz tiem esmu sacījis: tiem Israēla bērnu vidū zemes daļas nebūs mantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Tev uz Levitiem vēl būs runāt un tiem sacīt: kad jūs no Israēla bērniem dabūsiet tos desmitos, ko Es jums esmu devis par daļu no viņiem, tad jums no tiem būs nest cilājamu upuri Tam Kungam, to desmito no tiem desmitiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Un tas jums taps pielīdzināts par jūsu cilājamo upuri, kā labība no klona un kā pilnība no vīna spaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tā jums arī cilājamu upuri būs upurēt Tam Kungam no visiem saviem desmitiem, ko jūs dabūsiet no Israēla bērniem, un no tiem dot Tā Kunga cilājamo upuri Āronam, tam priesterim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'No visām savām dāvanām jums būs upurēt visu to cilājamo upuri Tam Kungam, no tā vislabākā to svēto daļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Tev tad uz viņiem būs sacīt: kad jūs to vislabāko no tā upurējat, tad tas Levitiem taps pielīdzināts, tā kā labība no klona vai kā auglis no vīna spaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Un ēdat to visās vietās, jūs un jūsu nams, jo tā ir jūsu alga par jūsu kalpošanu saiešanas teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Un jūs par to nenesīsiet nekādu grēku, kad jūs to visu labāko no tā upurēsiet, un Israēla bērnu svētās dāvanas nesagānīsiet un nemirsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Un Tas Kungs runāja uz Mozu un uz Āronu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Šis ir tas bauslības likums, ko Tas Kungs ir pavēlējis un sacījis: runā uz Israēla bērniem, ka tiem pie tevis būs vest sarkanu govi, kas bez vainas un kam nav nekādas kaites un uz kā nekāds jūgs vēl nav bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Un jums to būs dot priesterim Eleazaram, un to būs izvest no lēģera un viņa priekšā nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Un priesterim Eleazaram no viņas asinīm būs ņemt ar savu pirkstu un no viņas asinīm slacīt pret siešanas telts priekšu septiņreiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Un tad viņam to govi savā priekšā būs likt sadedzināt; viņas ādu un viņas gaļu un viņas asinis līdz ar viņas sūdiem viņam būs likt sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Un priesterim būs ņemt ciedra koku un īzapu un karmezīnu un to uzmest uz to degošo govi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Tad priesterim savas drēbes būs mazgāt un savas miesas pērt ūdenī un pēc būs iet lēģerī; un priesterim būs nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Un kas to sadedzinājis, tam savas drēbes būs mazgāt ūdenī, savas miesas ūdenī pērt un nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Un šķīstam vīram būs saņemt tās govs pelnus un tos likt ārā aiz lēģera kādā šķīstā vietā, ka tie tur top glabāti priekš Israēla bērnu draudzes šķīstīšanas ūdeni; tas ir grēku upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Un kas tās govs pelnus ir saņēmis, tam būs mazgāt savas drēbes un nešķīstam būt līdz vakaram. Un tas lai ir likums mūžīgi Israēla bērniem un tiem svešiniekiem, kas mīt jūsu starpā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kas aizskar mironi, kāda miruša cilvēka miesas, tam būs nešķīstam būt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Trešā un septītā dienā viņam ar to būs šķīstīties, tad viņš būs šķīsts; bet ja viņš trešā un septītā dienā nešķīstīsies, tad viņš nebūs šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Ikviens, kas aizskar mironi, kādu mirušu cilvēku, un nešķīstīsies, tas sagāna Tā Kunga dzīvokli, un tādu dvēseli lai izdeldē no Israēla, tāpēc ka šķīstīšanas ūdens uz to nav slacināts: viņš ir nešķīsts, viņa nešķīstība ir vēl pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Šis ir tas bauslis, kad viens cilvēks kādā dzīvoklī mirst: ikvienam, kas nāk tai dzīvoklī, un ikvienam, kas ir tai dzīvoklī, būs nešķīstam būt septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Un visi trauki, kas vaļā un kam vāka nav virsū, tie ir nešķīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Un ikvienam, kas laukā kādu aizskar, kas ar zobenu nokauts vai miris, vai cilvēka kaulus, vai kapu, tam būs būt nešķīstam septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Tad nu priekš tā nešķīstā būs ņemt no tā sadedzinātā grēku upura pelniem un uz tiem uzliet avota ūdeni traukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Un šķīstam vīram būs ņemt īzapu un to iemērkt ūdenī un apslacīt telti un visus traukus un visas dvēseles, kas tur bijušas, un to, kas aizskāris kādus kaulus vai kādu nokautu vai mirušu vai kapu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Un tam šķīstajam būs apslacīt to nešķīsto trešā dienā un septītā dienā, un septītā dienā viņam to būs šķīstīt, un tam būs savas drēbes mazgāt un ūdenī pērties, tad viņš vakarā būs šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Bet kas būs nešķīsts un nešķīstīsies, šo dvēseli būs izdeldēt no draudzes vidus, jo viņš Tā Kunga svēto vietu apgānījis; tas šķīstīšanas ūdens nav uz to slacīts, - tas ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Tas nu lai viņiem ir likums mūžīgi, un kas to šķīstīšanas ūdeni slaka, tam būs savas drēbes mazgāt, un kas to šķīstīšanas ūdeni aizskar, tam būs nešķīstam būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Un viss, ko tas nešķīstais aizskar, tas būs nešķīsts, un kura dvēsele to aizskars, tai būs nešķīstai būt līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Un pirmā mēnesī visa Israēla bērnu draudze nāca Cin tuksnesī, un tie ļaudis apmetās Kādešā, un Mirjame tur nomira un tapa tur aprakta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Un tai draudzei nebija ūdens; tad tie sapulcējās pret Mozu un pret Āronu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Un tie ļaudis strīdējās ar Mozu un runāja sacīdami: kaut būtu bojā gājuši, kad mūsu brāļi bojā gāja priekš Tā Kunga!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Kāpēc jūs esat veduši Tā Kunga draudzi uz šo tuksnesi, ka še mums un mūsu lopiem jāmirst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Un kāpēc jūs mūs esat izveduši no Ēģiptes zemes un mūs atveduši šai posta vietā? tā nav sējama vieta, nedz vīģu nedz vīnu dārzu nedz granātābolu vieta, te arī ūdens nav, ko dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Tad Mozus un Ārons gāja no tās draudzes pie saiešanas telts durvīm un metās uz savu vaigu; un Tā Kunga godība viņiem parādījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Ņem to zizli un salpulcini to draudzi, tu un Ārons, tavs brālis, un runājiet uz to klinti priekš viņu acīm, tad tā dos ūdeni; tā tu viņiem izdabūsi ūdeni no klints un dzirdināsi to draudzi un viņas lopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Tad Mozus ņēma to zizli no Tā Kunga priekšas, kā Viņš tam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Un Mozus un Ārons sapulcēja to draudzi pie tās klints, un viņš uz tiem sacīja: klausāties jel, jūs pārgalvji, vai mēs jums izdabūsim ūdeni no šīs klints?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Tad Mozus pacēla savu roku un sita to klinti ar savu zizli divreiz, tad iznāca daudz ūdens ārā, tā ka tā draudze un viņas lopi dzēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Tad Tas Kungs sacīja uz Mozu un Āronu, tādēļ ka jūs Man neesat ticējuši un Mani neesat svētījuši priekš Israēla bērnu acīm, tādēļ jūs šo draudzi neievedīsiet tai zemē, ko Es tiem esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Šis ir tas Meribas (strīdus) ūdens, kur Israēla bērni ar To Kungu strīdējās, un Viņš pie tiem svēts parādījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Tad Mozus sūtīja vēstnešus no Kādešas pie Edoma ķēniņa: tā saka tavs brālis Israēls: tu zini visas tās bēdas, kas mums uzgājušas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Ka mūsu tēvi ir nogājuši uz Ēģiptes zemi, un ka mēs ilgu laiku esam dzīvojuši Ēģiptes zemē, un ka ēģiptieši mums un mūsu tēviem ir ļaunu darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Tad mēs brēcām uz To Kungu, un Viņš klausīja mūsu balsi un sūtīja eņģeli un mūs izveda no Ēģiptes zemes, un redzi, mēs esam Kādešas pilsētā tavu robežu malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Ļauj mums iet caur tavu zemi; mēs neiesim pār druvām, ne caur vīna dārziem, nedz dzersim ūdeni no akām, pa lielceļu mēs iesim un negriezīsimies ne pa labo ne pa kreiso roku, tiekams būsim izgājuši caur tavām robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Bet Edoms uz to sacīja: tev nebūs iet caur mums, citādi es tev iziešu pretī ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Tad Israēla bērni sacīja uz viņu: pa lielceļu mēs iesim, un ja dzersim no tava ūdens, mēs ar saviem lopiem, tad par to dosim maksu; cita nekā negribam kā kājām iet cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Un viņš sacīja: tev nebūs iet cauri! Un Edoms viņam izgāja pretī ar varenu pulku un stipru roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Tā Edoms Israēlim aizliedza un viņam neļāva iet caur savām robežām; un Israēls griezās nost no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Un tie aizgāja no Kādešas, un visa Israēla bērnu draudze nāca pie Hora kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Tad Tas Kungs runāja uz Mozu un Āronu pie Hora kalna, pie Edoma zemes robežām, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Āronam būs tapt piepulcinātam pie saviem ļaudīm, jo viņš nenāks tai zemē, ko Es dodu Israēla bērniem, tāpēc ka jūs Manam vārdam esat pretī turējušies pie strīdus ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Ņem Āronu un viņa dēlu Eleazaru, un ved tos augšā uz Hora kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Un novelc Āronam viņa drēbes un apvelc tās Eleazaram, viņa dēlam, jo Ārons tur taps piepulcināts un nomirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Tad Mozus darīja, itin kā Tas Kungs bija pavēlējis. Un tie uzkāpa uz Hora kalnu priekš visas draudzes acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Un Mozus Āronam novilka viņa drēbes un tās apvilka Eleazaram, viņa dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Un Ārons tur nomira, tā kalna galā; tad Mozus un Eleazars nāca no kalna zemē. Kad nu visa draudze redzēja Āronu esam nomirušu, tad viss Israēla nams Āronu apraudāja trīsdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Un tas Kanaānietis, Arada ķēniņš, kas dzīvoja pret dienvidiem, dzirdēja Israēli nākam pa izlūku ceļu, un kāvās pret Israēli un aizveda kādus no viņiem sagūstītus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tad Israēls Tam Kungam apsolīja solījumu sacīdams: ja Tu šos ļaudis dosi manā rokā, tad es viņu pilsētas izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Un Tas Kungs klausīja Israēla bērnu balsij un nodeva tos Kanaāniešus, un tie šos izdeldēja ar viņu pilsētām un nosauca tās vietas vārdu Horma (izdeldēšana).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Tad tie aizgāja no Hora kalna pa niedru jūras ceļu, ka ietu apkārt Edomiešu zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Un tiem ļaudīm apnika ceļā, un tie ļaudis runāja pret Dievu un pret Mozu: kāpēc jūs mūs esat izveduši no Ēģiptes zemes, ka tuksnesī mirstam? - Jo šeit nav ne maizes, ne ūdens, un mūsu dvēselei šī blēņu maize riebj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Tad Tas Kungs sūtīja dedzīgas čūskas ļaužu starpā; tās tos koda un tur nomira daudz ļaužu no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Tad tie ļaudis nāca pie Mozus un sacīja: mēs esam grēkojuši, runādami pret To Kungu un pret tevi; lūdz To Kungu, lai Viņš atņem tās čūskas no mums. Tad Mozus lūdza par tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Un Tas Kungs sacīja uz Mozu: taisi sev vienu čūsku un uzcel to par zīmi, un notiks, ikviens, kas ir kosts un to uzlūkos, tas dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Un Mozus taisīja vara čūsku un to uzcēla par zīmi, un notikās, ja čūska kādu bija kodusi, tad tas uzlūkoja to vara čūsku un palika dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Tad Israēla bērni aizgāja un apmetās Obotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Pēc tie aizgāja no Obota un apmetās pie Abaru kalniem tuksnesī, kas ir pret Moabu, pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'No turienes tie aizgāja un apmetās pie Zaredas upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'No turienes tie aizgāja un apmetās šaipus Arnonas, kas ir tuksnesī un iztek no Amoriešu robežām; jo Arnona ir Moaba robeža, starp Moabu un Amoriešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Tāpēc top sacīts Tā Kunga karu grāmatā: (tas Kungs karoja) pret Vahēbu viesulī un pret Arnonas upēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Un to strautu ieleju, kas griežas uz Ar pilsētu un iet gar Moaba robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Un no turienes tie aizgāja uz Beēru. Šī ir tā aka, par ko Tas Kungs Mozum sacīja: sapulcini tos ļaudis, tad Es tiem došu ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tad Israēls dziedāja šo dziesmu: Verdi, aka, uzdziediet viņai!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Tu aka, ko virsnieki rakuši, ko ļaužu cienīgie izrakuši ar scepteri, ar saviem zižļiem. Pēc tie aizgāja no tuksneša uz Matanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Un no Matanas uz Naāliēli, un no Naāliēles uz Bamotu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Un no Bamotas uz to ieleju, kas ir Moaba laukā, pie tā augstā Pizgas kalna, kas stiepjas pret tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Tad Israēls sūtīja vēstnešus pie Sihona, Amoriešu ķēniņa, un sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Ļauj man iet caur tavu zemi; mēs negriezīsimies druvās nedz vīna dārzos, mēs nedzersim ūdeni no akām; pa lielceļu iesim, tiekams būsim cauri izgājuši caur tavām robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Bet Sihons Israēlim neļāva iet caur savām robežām, un Sihons sapulcēja visus savus ļaudis un izgāja Israēlim pretī uz tuksnesi, un nāca uz Jācu un karoja pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Bet Israēls viņu apkāva ar zobena asmeni un uzņēma viņa zemi no Arnonas līdz Jabokai, līdz Amona bērniem; (jo Amona bērnu robežas bija stipras).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Tā Israēls uzņēma visas šīs pilsētas, un Israēls dzīvoja visās Amoriešu pilsētās, Hešbonā un visos viņu ciemos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Jo Hešbona bija Sihona, Amoriešu ķēniņa, pilsēta, un šis bija karojis pret Moabiešu iepriekšējo ķēniņu un bija paņēmis visu viņa zemi no viņa rokām līdz Arnonai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Tāpēc dziesminieki saka: nāciet Hešbonā, uztaisīt un apstiprināt Sihona pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Jo uguns ir izgājis no Hešbonas un liesma no Sihona pilsētas; tā ir aprijusi Aru Moabā un Arnonas kalnu kungus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Vai tev, Moab! Kamosa ļaudis, jūs ejat bojā! Viņa dēli spiesti bēgt un viņa meitas cietumā vestas no Sihona, Amoriešu ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Un viņa spožums ir iznīcis no Hešbonas līdz Dibonai, mēs to esam izdeldējuši līdz Nofai, kas stiepjas līdz Medbai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Tā Israēls dzīvoja Amoriešu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Un Mozus sūtīja izlūkot Jaēzeru, un tie uzvarēja viņas valstis un izdzina tos Amoriešus, kas tur bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Un tie griezās un gāja uz augšu pa Basanas ceļu, un Ogs, Basanas ķēniņš, viņiem izgāja pretī, viņš un visi viņa ļaudis, kauties pie Edrejas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Tad Tas Kungs sacīja uz Mozu: nebīsties no viņa, jo viņu un visus viņa ļaudis un visu viņa zemi Es esmu devis tavā rokā, un tev būs tam darīt, itin kā tu esi darījis Sihonam, Amoriešu ķēniņam, kas dzīvoja Hešbonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Un tie viņu apkāva un viņa dēlus un visus viņa ļaudis, tā ka neviens neatlikās, un uzņēma viņa zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Tad Israēla bērni cēlās un apmetās Moaba klajumos, viņpus Jardānes, Jērikum pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Kad nu Balaks, Cipora dēls, visu redzēja, ko Israēls bija darījis Amoriešiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Tad Moabs ļoti bijās no tiem ļaudīm, jo to bija daudz, un Moabam bija bail no Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Tāpēc Moabs sacīja uz Midijaniešu vecajiem: nu šī draudze visu apēdīs, kas mums visapkārt, itin kā vērsis apēd zāli virs zemes. Bet Balaks, Cipora dēls, bija tanī laikā Moabiešu ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Un tas sūtīja vēstnešus pie Bileāma, Beora dēla, uz Petoru, kas pie tās lielupes, viņa ļaužu bērnu zemē, viņu aicināt, un sacīja: redzi, tur ir ļaudis izgājuši no Ēģiptes zemes, redzi, tie apklāj zemes virsu un ir apmetušies man pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Un nu nāc jel un nolādi man šos ļaudis, - jo tie ir stiprāki nekā es, - ka es tos varētu apkaut un izdzīt no zemes; jo es zinu, ka ko tu svētī, tas ir svētīts, un ko tu nolādi, tas ir nolādēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Tad Moabiešu vecaji un Midijaniešu vecaji gāja, un zīlēšanas alga bija viņu rokā, un tie nāca pie Bileāma un runāja uz viņu Balaka vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Tad tas uz viņiem sacīja: paliekat šeit par nakti, tad es jums atsacīšu, kā Tas Kungs uz mani runās; un Moaba virsnieki palika pie Bileāma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Un Dievs nāca pie Bileāma un sacīja: kas tie tādi ļaudis, kas pie tevis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Tad Bileāms sacīja uz Dievu: Balaks, Cipora dēls, Moabiešu ķēniņš, pie manis sūtījis');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '(Sacīdams): Redzi, ļaudis no Ēģiptes zemes ir izgājuši un apklāj zemes virsu, nāc nu, nolādi man tos, ka es pret tiem varētu karot un tos izdzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Tad Dievs sacīja uz Bileāmu: tev nebūs iet ar viņiem, tev nebūs šos ļaudis nolādēt, jo tie ir svētīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Tad Bileāms cēlās rītā agri un sacīja uz Balaka lielkungiem: ejat uz savu zemi, jo Tas Kungs aizliedz un neļauj Man iet ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Tad Moaba virsnieki cēlās un nāca pie Balaka un sacīja: Bileāms ir liedzies, mums iet līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Un Balaks atkal sūtīja vēl vairāk un jo cienīgus lielkungus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Tie nāca pie Bileāma un uz to sacīja: tā saka Balaks, Cipora dēls: lūdzams, neliedzies nākt pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Jo es tevi augsti godināšu un visu, ko tu man sacīsi, to es darīšu: tad nāc jel, nolād man šos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Tad Bileāms atbildēja un sacīja uz Balaka kalpiem: kaut man Balaks savu namu dotu pilnu zelta un sudraba, tomēr es nevarētu pārkāpt Tā Kunga, sava Dieva, vārdu, darīt vai mazu vai lielu lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Un nu paliekat jel arī šo nakti pie manis, tad es redzēšu, ko Tas Kungs atkal ar mani runās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Tad Dievs nāca pie Bileāma naktī un uz to sacīja: ja tie vīri nākuši tevi aicināt, tad celies, ej viņiem līdz, bet tikai to tev būs darīt, ko Es uz tevi runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Tad Bileāms cēlās rītā agri un apsedloja savu ēzelieni un gāja tiem Moaba virsniekiem līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Bet Dieva bardzība iedegās, tāpēc ka viņš gāja, un Tā Kunga eņģelis nostājās uz ceļa viņam par pretinieku; un viņš jāja uz savas ēzelienes, un viņa divi puiši viņam līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Un tā ēzeliene ieraudzīja Tā Kunga eņģeli uz ceļa stāvam, pliku zobenu rokā, un tā ēzeliene atkāpās no ceļa un gāja uz tīrumu; tad Bileāms sita to ēzelieni, viņu griezdams uz ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Bet Tā Kunga eņģelis nostājās ceļa šaurumā vīna dārzu starpā, kur abējās pusēs bija mūris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Kad nu tā ēzeliene Tā Kunga eņģeli ieraudzīja, tad tā spiedās pie mūra un piespieda Bileāma kāju pie mūra; tāpēc viņš to atkal sita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Un Tā Kunga eņģelis gāja tālāki un nostājās kādā šaurā vietā, kur nebija kur atkāpties, ne pa labo, ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Kad nu tā ēzeliene Tā Kunga eņģeli ieraudzīja, tad tā pakrita uz ceļiem apakš Bileāma, un Bileāma dusmas iedegās un viņš to ēzelieni sita ar koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Un Tas Kungs atvēra muti tai ēzelienei un tā sacīja uz Bileāmu: ko es tev esmu darījusi, ka tu man nu trīs reizes esi sitis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Un Bileāms sacīja uz to ēzelieni: tāpēc ka tu mani esi kaitinājusi! Kaut zobens būtu manā rokā, es tevi tagad nokautu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Tad tā ēzeliene sacīja uz Bileāmu: vai neesmu tava ēzeliene, uz kā tu esi jājis līdz šai dienai? Vai tas bijis man ieradums tev tā darīt? Viņš sacīja: nē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Tad Tas Kungs Bileāmam atvēra acis, ka viņš Tā Kunga eņģeļi ieraudzīja uz ceļa stāvam, pliku zobenu rokā; tāpēc viņš klanījās un nometās uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Tad Tā Kunga eņģelis uz viņu sacīja: kāpēc tu savu ēzelieni nu trīs reiz sitis? Raugi, es esmu izgājis tev par pretinieku, jo tavs ceļš manā priekšā ir ļauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Bet tā ēzeliene mani redzējusi un nu trīs reiz no manis atkāpusies, un ja viņa nebūtu atkāpusies, tiešām es tevi būtu nokāvis un viņu pametis dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Tad Bileāms sacīja uz Tā Kunga eņģeli: es esmu grēkojis, jo es nezināju, tevi uz ceļa man pretī stāvam, un nu, ja tev nepatīk, tad es iešu atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Tad Tā Kunga eņģelis sacīja uz Bileāmu: ej tiem vīriem līdz; tomēr to vien, ko es uz tevi runāšu, to tev būs runāt. Tā Bileāms gāja Balaka lielkungiem līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Kad nu Balaks dzirdēja Bileāmu nākam, tad viņš tam izgāja pretī līdz tai Moabiešu pilsētai, kas ir Arnonas robežās, - pašā robežu malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Un Balaks sacīja uz Bileāmu: vai es neesmu sūtīdams pie tevis sūtījis, tevi aicināt? Kāpēc tu neesi pie manis nācis? vai tad es nespēju tevi godināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Tad Bileāms sacīja uz Balaku: redzi, es pie tevis esmu atnācis, bet vai es kautko varu runāt kā vien to vārdu, ko Dievs liks manā mutē? - To es runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Un Bileāms gāja Balakam līdz un tie nonāca Kiriat Hucotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Un Balaks upurēja lielus un sīkus lopus un sūtīja Bileāmam un tiem lielkungiem, kas pie viņa bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Un no rīta Balaks ņēma Bileāmu un to veda uz Baāla kalniem, un no turienes šis redzēja vienu galu no tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Tad Bileāms sacīja uz Balaku: uztaisi man šeitan septiņus altārus un sataisi man še septiņus vēršus un septiņus aunus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Tad Balaks tā darīja, kā Bileāms bija sacījis, un Balaks un Bileāms upurēja vērsi un aunu uz ikviena altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Un Bileāms sacīja uz Balaku: paliec pie sava dedzināmā upura stāvot; es iešu, vai Tas Kungs man nenāks pretī; un ko Viņš man rādīs, to es tev atsacīšu. Tad viņš gāja uz vienu kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Un Dievs sastapa Bileāmu, un tas uz Viņu sacīja: septiņus altārus es esmu uztaisījis un vērsi un aunu upurējis uz ikviena altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Tad Tas Kungs lika Bileāma mutē to vārdu un sacīja: griezies atpakaļ pie Balaka un runā tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Un kad viņš pie šī atgriezās, redzi, tad šis stāvēja pie sava dedzināmā upura ar visiem Moaba lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Tad viņš sāka teikt savu sakāmo un sacīja: no Aramas Balaks, Moabiešu ķēniņš, mani atvedis, - no tiem kalniem pret rītiem: nāc, nolādi man Jēkabu, un nāc, nosodi Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kā lai es nolādu, ko Dievs nelād, un kā lai es nosodu, ko Tas Kungs nesoda?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Jo no augstas klints es viņu redzu, un no tiem kalniem es to ieraugu; redzi, tauta, kas savrup dzīvo un nepieskaitās pagāniem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kas izskaitīs Jēkaba pīšļus vai Israēla skaita ceturto daļu? Lai mana dvēsele mirst šo taisno nāvē, un lai mans pastara gals ir tāds kā viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Tad Balaks sacīja uz Bileāmu: ko tu man esi darījis? Es tevi esmu aicinājis, manus ienaidniekus nolādēt, un redzi, tu tos svētīdams esi svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Tad viņš atbildēja un sacīja: vai man nav jādara, ko Tas Kungs mana mutē licis runāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Tad Balaks viņam sacīja: nāc jel man līdz uz citu vietu, no kurienes tu viņus vari redzēt; tu tikai vienu galu no viņiem esi redzējis un visus tu neesi redzējis; - un nolādi man tos no turienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Tā viņš to ņēma līdz uz Cofim tīrumu, uz Pizgas kalngalu, un uztaisīja septiņus altārus un upurēja vērsi un aunu uz ikviena altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Un viņš sacīja uz Balaku: paliec šeitan pie sava dedzināmā upura, es tur iešu pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Tad Tas Kungs sastapa Bileāmu un lika viņa mutē to vārdu un sacīja: griezies atpakaļ pie Balaka un runā tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Kad nu viņš pie šī nāca, tad šis stāvēja pie sava dedzināmā upura un Moaba lielkungi pie viņa. Tad Balaks viņam sacīja: ko Tas Kungs ir runājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Tad viņš sāka savu teikumu teikt un sacīja: celies, Balak un klausies! Griez savas ausis uz mani, tu Cipora dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Dievs nav cilvēks, ka melotu, nedz cilvēka bērns, ka Viņam kas būtu žēl. Vai Viņš ko sacītu un nedarītu, vai Viņš ko runātu un neturētu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Redzi, man ir pavēlēts svētīt; Viņš ir svētījis, un es nedarīšu citādi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Noziegumu Viņš neredz iekš Jēkaba un ļaunumu neatrod iekš Israēla; Tas Kungs, viņa Dievs, ir ar viņu, un ķēniņa prieki pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Dievs tos ir izvedis no Ēģiptes zemes; spēki viņam ir kā sūbram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Jo zīlēšana neder pret Jēkabu un buršana neder pret Israēli. Savā laikā Jēkabam top sacīts un Israēlim, ko Dievs dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Redzi, tauta, kas ceļas kā lauvas māte un kas šaujās augšā kā lauva; neapgulstās, kamēr laupījums aprīts un dzer nokauto asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Tad Balaks sacīja uz Bileāmu: tev nemaz nebūs viņu ne lādēt, ne svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bet Bileāms atbildēja un sacīja uz Balaku: vai es uz tevi neesmu runājis sacīdams: visu, ko Tas Kungs runās, to es darīšu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Tad Balaks sacīja uz Bileāmu: nāc jel, es tev ņemšu līdz uz kādu citu vietu; varbūt Dievam patiks, ka tu man viņu no turienes nolādi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Tad Balaks Bileāmu veda uz Peora kalngalu, kas pret tuksnesi stiepjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Un Bileāms sacīja uz Balaku: uztaisi man šeit septiņus altārus un sataisi man septiņus vēršus un septiņus aunus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Tad Balaks darīja, kā Bileāms bija sacījis, un upurēja vērsi un aunu uz ikviena altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Kad nu Bileāms redzēja, ka Tam Kungam patika, Israēli svētīt, tad viņš vairs negāja pēc zīmēm, kā pirmo un otru reiz, bet grieza savu vaigu uz tuksnesi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Un pacēla savas acis un redzēja Israēli, kas bija apmeties pēc savām ciltīm; un tas Dieva Gars nāca uz viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Un viņš sāka savu teikumu teikt un sacīja: Bileāms, Beora dēls runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Tas vīrs, kam acis atvērtas, runā, tas Dieva vārdu klausītājs runā, kas redz Tā Visuvarenā parādīšanas, pie zemes meties atvērtām acīm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Cik jaukas ir tavas teltis, Jēkab, tavi dzīvokļi, Israēl!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Kā upes ielejas, tā viņi izplešas, kā dārzi pie upēm, kā alvejas koki, ko Tas Kungs stādījis, kā ciedru koki pie ūdens!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Ūdens tek no viņa traukiem un viņa dzimumam ir ūdens papilnam, un viņa ķēniņš būs augstāks par Agagu, un viņa valsts augsti celta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Dievs viņu izvedis no Ēģiptes, viņam ir spēki kā sūbram, viņš norij pagānus, savus ienaidniekus, un satriec viņu kaulus, ar savām bultām viņš tos sašauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Viņš ir apgulies kā lauva, kā lauvas māte - kas to traucēs? Kas tevi svētī, tas lai ir svētīts, un kas tevi nolād, tas lai ir nolādēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Tad Balaka bardzība iedegās pret Bileāmu un viņš sasita savas rokas kopā, un Balaks sacīja uz Bileāmu: es tevi esmu aicinājis, nolādēt manus ienaidniekus, bet redzi, tu tos nu trīs reiz svētīdams esi svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Un nu steidzies uz mājām, es domāju godādams tevi godāt, bet redzi, Tas Kungs tev to godu ir liedzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Tad Bileāms sacīja uz Balaku: vai es jau neteicu uz taviem vēstnešiem, ko tu pie manis esi sūtījis, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Jebšu Balaks man dotu savu namu pilnu sudraba un zelta, tomēr es nevaru pārkāpt Tā Kunga vārdu, un darīt vai labu vai ļaunu pēc sava prāta. Ko Tas Kungs uz mani runās, to es runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Un nu redzi, es eju pie saviem ļaudīm; nāc, es tev stāstīšu, ko šie ļaudis darīs taviem ļaudīm nākamās dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Un viņš sāka teikt savu teikumu un sacīja: Bileāms, Beora dēls, runā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Tas vīrs, kam acis atvērtas, runā, tas Dieva vārdu klausītājs runā, kas atzīst Tā Visuaugstākā atzīšanu, kas redz Tā Visuvarenā parādīšanas, pie zemes meties atvērtām acīm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Es viņu redzu, bet ne tagad, es viņu ieraugu, bet ne tuvu klāt. Zvaigzne uzlēks no Jēkaba, un scepteris celsies no Israēla, tas satrieks Moaba robežas un izpostīs visus dumpja ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Un Edoms paliek par īpašumu un Seīrs paliek par īpašumu, viņa ienaidnieki, bet Israēls pieņemas spēkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Un no Jēkaba nāks tas valdītājs, un tas izpostīs, kas atlicies no tām pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Un viņš redzēja Amaleku un sāka savu teikumu teikt un sacīja: Amaleks ir pagānu pirmais, bet viņa gals ir posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Un viņš redzēja Keniešus un sāka savu teikumu teikt un sacīja: tavs dzīvoklis ir stiprs, un tu savu ligzdu esi taisījis uz klints.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Tomēr Kains taps sadedzināts. Cik ilgi būs, tad Asurs tevi vedīs cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Un viņš sāka savu teikumu teikt un sacīja: Ak vai! Kas dzīvos, kad tas stiprais Dievs to darīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Un lielas laivas no Ķitim spaidīs Asuru un spaidīs arī Ēberu, bet arī viņš pats tas spaidītājs ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Tad Bileāms cēlās un aizgāja un griezās atpakaļ uz mājām uz savu vietu, un Balaks gāja arīdzan savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Un Israēls mita iekš Sitimas, un tie ļaudis sāka maucību dzīt ar Moabiešu meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Un tās aicināja tos ļaudis pie savu dievu upuriem, un tie ļaudis ēda un metās zemē priekš viņu dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Kad nu Israēls sapinās ar Baāl Peoru, tad Tā Kunga bardzība iedegās pret Israēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Un Tas Kungs sacīja uz Mozu: ņem visus ļaužu virsniekus un pakar tos Tam Kungam pret sauli, lai Tā Kunga bargā dusmība no Israēla nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Tad Mozus sacīja uz Israēla soģiem: nokaujiet ikviens savus ļaudis, kas ar Baāl Peoru sapinušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Un redzi, viens vīrs no Israēla bērniem nāca un atveda pie saviem brāļiem Midijaniešu sievu priekš Mozus acīm un priekš visas Israēla bērnu draudzes acīm; un šie raudāja priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Kad Pinehas, Eleazara dēls, priestera Ārona dēla dēls, to ieraudzīja, tad viņš cēlās no draudzes vidus un ņēma šķēpu savā rokā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Un gāja tam Israēla vīram pakaļ mauku kaktā un pārdūra abus caur vēderu, to Israēla vīru un to sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Tad tā mocība mitējās no Israēla bērniem; un to, kas tai mocībā nomira, bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas, Eleazara dēls, priestera Ārona dēla dēls, Manu bardzību novērsis no Israēla bērniem, dusmodamies ar Manām dusmām viņu vidū, tā ka Es Israēla bērnus neesmu izdeldējis Savā dusmībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Tādēļ saki: redzi, Es viņam došu Savu miera derību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Un viņam un viņa dzimumam pēc viņa būs mūžīgas priesterības derība, tāpēc ka viņš par savu Dievu iededzies un Israēla bērnus salīdzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Un tā nokautā Israēliešu vīra vārds, kas līdz ar to Midijaniešu sievu bija nokauts, bija Zimrus, Šalus dēls, virsnieks Sīmeana ciltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Un tās nokautās Midijaniešu sievas vārds bija Kazbi, Curus meita, kas bija ļaužu virsnieks kādā Midijaniešu ciltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Uzbrūkat tiem Midijaniešiem un kaujat tos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Jo tie jums ir uzbrukuši ar savām viltībām, ar ko tie jūs pievīluši caur Peoru un caur savu māsu Kazbi, Midijana virsnieka meitu, kas ir nokauta tai mocības dienā Peora dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Un notikās pēc tās mocības, tad Tas Kungs runāja uz Mozu un uz Eleazaru, priestera Ārona dēlu, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Skaiti visas Israēla bērnu draudzes pulku, kas ir divdesmit gadu un pāri, pēc viņu tēvu namiem, visus, kas iekš Israēla var iet karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Tad Mozus un Eleazars, tas priesteris, ar tiem runāja Moaba klajumos, pie Jardānes pret Jēriku un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '(Lai top skaitīti) kas ir divdesmit gadu un pāri, itin kā Tas Kungs Mozum pavēlējis. Bet Israēla bērni, kas no Ēģiptes zemes izgājuši, bija:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Rūbens Israēla pirmdzimtais. Rūbena dēli bija Hanoks, no tā ir Hanoka cilts; no Pallus ir Pallus cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'No Hecrona ir Hecrona cilts, no Karmus ir Karmus cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Šās ir Rūbena ciltis, un viņu skaits bija četrdesmit trīs tūkstoši septiņsimt un trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Un Pallus dēls bija Eliabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Un Eliaba dēli bija Nemuēls un Datans un Abirams. Šis Datans un Abirams bija tās draudzes virsnieki, kas pret Mozu un Āronu sacēlās Koraha pulkā, kad tas sacēlās pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Un zeme atdarīja savu muti un tos aprija līdz ar Korahu, ka tas pulks nomira; tur uguns divsimt un piecdesmit vīrus aprija, un tie tapa par biedēkli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Bet Koraha dēli nenomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Sīmeana dēli pēc savām ciltīm: no Nemuēļa ir Nemuēļa cilts, no Jāmina ir Jāmina cilts, no Jākina ir Jākina cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'No Zerus ir Zerus cilts, no Saulus ir Saulus cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Šās ir Sīmeana ciltis, divdesmit un divi tūkstoši un divi simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gada dēli pēc savām ciltīm: no Cevona ir Cevona cilts, no Hagus ir Hagus cilts, no Zūnus ir Zūnus cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'No Oznus ir Oznus cilts, no Erus ir Erus cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'No Aroda ir Aroda cilts, no Ariēļa ir Ariēļa cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Šās ir Gada dēlu ciltis, pēc sava skaita četrdesmit tūkstoši un piecsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Jūda dēli bija Ģers un Onans, bet Ģers un Onans nomira Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Tad Jūda bērni bija pēc savām ciltīm: no Šelus Šelus cilts, no Pereca Pereca cilts, no Zerus Zerus cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Un Pereca dēli bija Hecrons, no tā ir Hecrona cilts, no Hamula ir Hamula cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Šās ir Jūda ciltis, pēc sava skaita septiņdesmit un seši tūkstoši un piecsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Īsašara dēli pēc savām ciltīm bija: Tolus, no tā ir Tolus cilts, no Pūvus ir Pūvus cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'No Jašuba ir Jašuba cilts, no Šimrona ir Šimrona cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Šās ir Īsašara ciltis, pēc sava skaita sešdesmit un četri tūkstoši un trīssimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Zebulona dēli pēc savām ciltīm bija: Sereds, no tā ir Sereda cilts, no Elona ir Elona cilts, no Jaleēļa ir Jaleēļa cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Šās ir Zebulona ciltis, pēc sava skaita sešdesmit tūkstoši un piecsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Jāzepa dēli pēc savām ciltīm bija Manasus un Efraīms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manasus dēli bija: Mahirs, no tā ir Mahira cilts, un Mahirs dzemdināja Gileādu, no Gileāda ir Gileāda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Šie ir Gileāda dēli: Jēzers no tā ir Jēzera cilts, Heleks, no tā ir Heleka cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Un no Asriēla ir Asriēla cilts, no Šehema ir Šehema cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Un no Šemida ir Šemida cilts, un no Hefera ir Hefera cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Bet Celofehadam, Hefera dēlam, nebija dēlu, bet meitas, un Celofehada meitu vārdi bija Maēla un Noa, Hagla, Milka un Tirca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Šās ir Manasus ciltis, un viņu skaits piecdesmit un divi tūkstoši un septiņsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Šie ir Efraīma bērni pēc savām ciltīm: no Šūtelus ir Šūtelus cilts, no Bekera Bekera cilts, no Taāna Taāna cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Un šie ir Šūtelus dēli: no Erana ir Erana cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Šās ir Efraīma dēlu ciltis, pēc sava skaita trīsdesmit divi tūkstoši un piecsimt. Šie ir Jāzepa dēli pēc savām ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjamina dēli pēc savām ciltīm: no Belus ir Belus cilts, no Ašbela Ašbela cilts, no Ahirus Ahirus cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'No Šūpus Šūpus cilts, no Hūpus Hūpus cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Un Belus dēli bija: Ards un Naēmans: no viņa ir Arda cilts, no Naēmana ir Naēmana cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Šie ir Benjamina dēli pēc savām ciltīm, un viņu skaits bija četrdesmit pieci tūkstoši un sešsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Šie ir Dana dēli pēc savām ciltīm: no Šuhāma ir Šuhāma cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Šās ir Dana ciltis pēc savām ciltīm, visi Šuhāma radi pēc sava skaita sešdesmit četri tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Ašera dēli pēc savām ciltīm: no Jemna ir Jemna cilts, no Jisvus ir Jisvus cilts, no Berius ir Berius cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'No Berius bērniem, no Hebera ir Hebera cilts, no Melķiēļa ir Melķiēļa cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Un Ašera meitas vārds bija Sāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Šās ir Ašera bērnu ciltis, pēc sava skaita piecdesmit trīs tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naftalus dēli pēc savām ciltīm: no Jaēciēļa ir Jaēciēļa cilts, no Gunus ir Gunus cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'No Jecera ir Jecera cilts, no Šilema ir Šilema cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Šie ir Naftalus dēli pēc savām ciltīm, un viņu skaits bija četrdesmit pieci tūkstoši un četrsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Šie ir Israēla bērnu skaitītie, sešsimt tūkstoši viens tūkstotis septiņsimt un trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Šiem lai tā zeme top izdalīta par mantu pēc tā vārdu skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Kuru ir daudz, tiem tev to daļu būs vairot, un, kuru ir mazāk, tiem būs mazāk dot par daļu, ikvienam tā daļa lai top dota pēc tā skaitīta pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Bet tā zeme caur īpašu meslošanu lai top izdalīta, pēc viņu tēvu cilts vārdiem tiem būs mantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Kā tā meslošana rādīs, tā lai ikviena daļa top dota pēc tā lielā vai tā mazā skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Šie nu ir tie skaitītie Leviti pēc savām ciltīm: no Geršona ir Geršona cilts, no Kehāta ir Kehāta cilts, no Merarus ir Merarus cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Šās ir Levja ciltis: Libnus cilts, Hebrona cilts, Maēlus cilts, Muzus cilts, Koraha cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Un Kehāts dzemdināja Amramu, un Amrama sievas vārds bija Joķebete, Levja meita, kas Levjam Ēģiptes zemē dzimusi, un šī dzemdēja Amramam Āronu un Mozu un Mirjami, viņa māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Un Āronam piedzima Nadabs un Abijus, Eleazars un Ītamars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Bet Nadabs un Abijus bija nomiruši, kad tie svešu uguni Tam Kungam pienesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Un viņu skaits bija divdesmit trīs tūkstoši, visi vīrieši, kas vienu mēnesi veci un pāri; jo tie netapa skaitīti pie Israēla bērniem, tāpēc ka tiem nekāda daļa nebija dota starp Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Šie ir skaitīti no Mozus un priestera Eleazara, kas Israēla bērnus skaitīja Moaba klajumos, pie Jardānes pret Jēriku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Un starp tiem nebija neviena no tā Israēla bērnu skaita, ko Mozus un Ārons, tas priesteris, bija skaitījuši Sinaī tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Jo Tas Kungs uz tiem bija sacījis: tie mirtin mirs tuksnesī, un no tiem neviens nebija atlicies kā vien Kālebs, Jefunna dēls, un Jozuas, Nuna dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Tad piegāja Celofehada meitas; tas bija Hefera dēls, šis Gileāda dēls, šis Mahira dēls, šis Manasus dēls, no Manasus, Jāzepa dēla, ciltīm; un šie ir viņa meitu vārdi: Maēla un Noa un Hagla un Milka un Tirca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Un tās nāca pie Mozus un priestera Eleazara, un pie tiem virsniekiem un pie visas draudzes priekš saiešanas telts durvīm un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Mūsu tēvs tuksnesī ir nomiris, un tas nebija tai pulkā, kas bija sacēlies pret To Kungu, Koraha pulkā, bet viņš sava paša grēka dēļ ir miris un viņam nebija dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Kāpēc tad lai top izdeldēts mūsu tēva vārds savā ciltī, ka tam dēla nav? Dodiet mums daļu starp mūsu tēva brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Un Mozus viņu tiesas lietu nesa Tam Kungam priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Tad Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Celofehada meitas runā pareizi; dod viņām īpašumu starp viņu tēva brāļiem un piešķir tām viņu tēva īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Un uz Israēla bērniem tev būs runāt un sacīt: kad kāds mirst, kam dēlu nav, tad viņa mantību būs piešķirt viņa meitai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Un kad tam meitas nav, tad jums viņa mantību būs dot viņa brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Un ja tam brāļa nav, tad jums viņa mantību būs dot viņa tēva brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Ja tam arī tēva brāļu nav, tad jums viņa mantību būs dot viņa tuvākajam radam, kas ir no viņa cilts, un tam to būs iemantot; tas lai Israēla bērniem ir par tiesas likumu, itin kā Tas Kungs Mozum pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Tad Tas Kungs sacīja uz Mozu: kāp uz šo Abarim kalnu un skati to zemi, ko Es Israēla bērniem esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Un kad tu to būsi redzējis, tad arī tu tapsi piepulcināts pie saviem ļaudīm, kā Ārons, tavs brālis, ir piepulcināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Tāpēc ka jūs Manam vārdam esat pretī turējušies Cina tuksnesī, kad draudze strīdējās, kur jums vajadzēja Mani svētīt pie tā ūdens priekš viņu acīm. Tas ir tas strīdus ūdens Kādešā, Cina tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Tad Mozus runāja uz To Kungu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Lai Tas Kungs, tas Dievs pār visas miesas gariem, ieceļ vienu vīru pār šo draudzi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Kas viņu priekšā var iziet un ieiet, kas tos izvada un ievada, ka Tā Kunga draudze nav kā avis, kam gana nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Tad Tas Kungs sacīja uz Mozu: ņem sev Jozua, Nuna dēlu, vīru, kam ir gars, un liec savu roku uz viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Un ved to priestera Eleazara priekšā un visas draudzes priekšā, un dod tam pavēles priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Un liec uz to no sava goda, lai visa Israēla bērnu draudze tam klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Un viņam būs stāvēt priestera Eleazara priekšā, tam par viņu būs vaicāt Tā Kunga priekšā pēc Urim tiesas; pēc viņa vārda tiem būs iziet un pēc viņa vārda ieiet, viņam un visiem Israēla bērniem līdz ar viņu un visai draudzei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Un Mozus darīja, kā Tas Kungs viņam bija pavēlējis; un viņš ņēma Jozua un to noveda priestera Eleazara un visas draudzes priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Un uzlika savu roku uz viņu un deva viņam pavēles, kā Tas Kungs caur Mozu bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Pavēli Israēla bērniem un saki tiem: gādājiet Manu upuri, Manu maizi, priekš Maniem uguns upuriem, Man par saldu smaržu, ka jūs Man upurējat savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Un tev viņiem būs sacīt: šie ir tie uguns upuri, ko jums būs upurēt Tam Kungam: divus gada vecus jērus, kas bez vainas, arvien ik dienas par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Vienu jēru tev būs no rīta sataisīt un otru jēru ap vakaru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Un desmito tiesu ēfas kviešu miltu par ēdamu upuri, sajauktu ar vienu ceturtdaļu inna sagrūstas eļļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Šis ir tas ikdienas dedzināmais upuris, kas iestādīts Sinaī kalnā par saldu smaržu, uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Un viņa dzeramais upuris lai ir viena inna ceturtdaļa uz vienu jēru; svētā vietā būs upurēt vīna dzeramo upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Un to otru jēru tev būs sataisīt ap vakaru, itin kā to ēdamo upuri no rīta un kā viņa dzeramo upuri tev to būs sataisīt, uguns upuri par saldu smaržu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Bet uz dusēšanas dienu: divus gada vecus jērus, kas bez vainas, un par ēdamu upuri divas desmitās tiesas kviešu miltu, kas ar eļļu sajaukti, līdz ar to piederīgo dzeramo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Šis ir dusēšanas dienas dedzināmais upuris, ikvienā dusēšanas dienā, klāt pie tā ikdienas dedzināmā upura un tā piederīgā dzeramā upura,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Un savu mēnešu iesākumos jums būs upurēt Tam Kungam dedzināmo upuri, divus vērsēnus no lieliem lopiem un vienu aunu un septiņus gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Un par ēdamu upuri trīs desmitās tiesas kviešu miltu, kas ar eļļu sajaukti, uz ikvienu vērsi un divas desmitās tiesas kviešu miltu, kas ar eļļu sajaukti, pie ikviena auna par ēdamu upuri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Un par ēdamu upuri vienu desmito tiesu kviešu miltu, kas ar eļļu sajaukti, uz ikvienu jēru, tas ir dedzināms upuris par saldu smaržu, uguns upuris Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Un viņa dzeramais upuris lai ir pusinna uz ikvienu vērsi un inna trešā tiesa vīna uz aunu un inna ceturtdaļa uz jēru, šis ir tas dedzināmais upuris ikkatrā jaunā mēnesī pēc gada mēnešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Un viens āzis lai top sataisīts par grēku upuri Tam Kungam, klāt pie tā ikdienas dedzināmā upura līdz ar viņa dzeramo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Un pirmā mēnesī četrpadsmitajā dienā ir Pasa svētki Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Un šī mēneša piecpadsmitajā dienā ir tie svētki. Septiņas dienas būs ēst neraudzētas maizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Pirmā dienā lai ir svēta sapulce; nekādu darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Bet uguns upuri jums būs upurēt par dedzināmo upuri Tam Kungam, divus vērsēnus no lieliem lopiem un vienu aunu, un septiņus gadu vecus jērus, kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Un viņa ēdamais upuris lai ir kviešu milti, kas ar eļļu sajaukti, trīs desmitās tiesas uz ikkatru vērsēnu, un uz aunu jums būs sataisīt divas desmitās tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Vienu desmit tiesu tev būs sataisīt uz ikvienu no tiem septiņiem jēriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Pēc tam āzi par grēku upuri, jums par salīdzināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Klāt pie tā rīta upura, kas ir tas ikdienas dedzināmais upuris, to jums būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Un tā jums ikdienas, visas septiņas dienas, būs sataisīt tā uguns upura maizi par saldu smaržu Tam Kungam; klāt pie tā ikdienas dedzināmā upura to būs sataisīt līdz ar viņa dzeramo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Un septītā dienā lai jums ir svēta sapulce, nekādu darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Un tai pirmaju dienā, kad jūs Tam Kungam upurējat ēdamu upuri pēc savām nedēļām, lai jums ir svēta sapulce, nekādu darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Tad jums Tam Kungam būs upurēt dedzināmo upuri par saldu smaržu, divus vērsēnus no lieliem lopiem, vienu aunu, septiņus gada vecus jērus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Un viņu ēdamo upuri no kviešu miltiem, kas ar eļļu sajaukti, trīs desmitās tiesas uz ikkatru vērsi, divas desmitās tiesas uz aunu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Vienu desmito tiesu uz ikvienu no tiem septiņiem jēriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Vienu āzi jums par salīdzināšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Klāt pie tā ikdienas dedzināmā upura ar viņa ēdamo upuri jums šās lietas būs sataisīt; tās jums lai ir bez vainas līdz ar viņu dzeramiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Un arī septītā mēnesī, pirmā mēneša dienā, lai jums ir svēta sapulce, - nekādu darbu jums nebūs darīt, - tā lai jums ir trumetēšanas(gaviļu) diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Tad jums būs sataisīt dedzināmo upuri Tam Kungam par saldu smaržu, vienu vērsēnu no lieliem lopiem, vienu aunu, septiņus gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Un viņu ēdamo upuri no kviešu miltiem, kas ar eļļu sajaukti, trīs desmitās tiesas uz vērsēnu un divas desmitās tiesas uz aunu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'Un vienu desmito tiesu uz ikvienu no tiem septiņiem jēriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Un vienu āzi par grēku upuri, jums par salīdzināšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Klāt pie tā mēneša dedzināmā upura un viņa ēdamā upura un pie tā ikdienas dedzināmā upura un viņa ēdamā upura un viņu dzeramiem upuriem, pēc viņu tiesas, par saldu smaržu, par uguns upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Un desmitā dienā šinī septītā mēnesī lai jums ir svēta sapulce; jums būs savas dvēseles mērdēt(gavēt), nekādu darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Bet jums būs upurēt dedzināmo upuri Tam Kungam par saldu smaržu, vienu vērsēnu no lieliem lopiem, vienu aunu, septiņus gada vecus jērus; tie lai jums ir bez vainas; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Un viņu ēdamo upuri no kviešu miltiem, kas ar eļļu sajaukti, trīs desmitās tiesas uz vērsēnu, divas desmitās tiesas uz aunu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Un vienu desmito tiesu uz ikvienu no tiem septiņiem jēriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Vienu āzi par grēku upuri, klāt pie tā grēku salīdzināšanas upura un pie ikdienas dedzināmā upura un viņa ēdamā upura un viņu dzeramiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Un arī piecpadsmitā dienā šinī septītā mēnesī lai jums ir svēta sapulce; nekādu darbu jums nebūs darīt, bet septiņas dienas Tam Kungam svētkus svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Un jums būs pienest dedzināmo upuri, uguns upuri, par saldu smaržu Tam Kungam, trīspadsmit vērsēnus no liellopiem, divus aunus, četrpadsmit gada vecus jērus, - bez vainas lai tie ir, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Un viņu ēdamo upuri no kviešu miltiem, kas ar eļļu sajaukti, trīs desmitās tiesas uz ikvienu no tiem trīspadsmit vēršiem, divas desmitās tiesas uz ikvienu no tiem diviem auniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Un vienu desmito tiesu uz ikvienu no tiem četrpadsmit jēriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura, viņa ēdamā upura un viņa dzeramā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Un otrā dienā divpadsmit vērsēnus no liellopiem, divus aunus, četrpadsmit gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Un viņu ēdamo upuri un viņu dzeramo upuri pie vēršiem, pie auniem un pie jēriem, pēc viņu skaita, - kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura un viņu dzeramiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Un trešā dienā vienpadsmit vēršus, divus aunus, četrpadsmit gada vecus jērus, kas bez vainas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Un viņu ēdamos upurus un viņu dzeramos upurus pie vēršiem, pie auniem un pie jēriem pēc viņu skaita, kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura un viņa ēdamā upura un dzeramā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Un ceturtā dienā desmit vēršus, divus aunus, četrpadsmit gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Viņu ēdamos upurus un viņu dzeramos upurus pie vēršiem, pie auniem un pie jēriem pēc viņu skaita, kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura, viņa ēdamā upura un viņa dzeramā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Un piektā dienā deviņus vēršus, divus aunus, četrpadsmit gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Līdz ar viņu ēdamiem upuriem un ar viņu dzeramiem upuriem pie vēršiem, pie auniem un pie jēriem pēc viņu skaita, kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura, un viņa dzeramā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Un sestā dienā astoņus vēršus, divus aunus, četrpadsmit gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Līdz ar viņu ēdamiem upuriem un ar viņu dzeramiem upuriem pie vēršiem, pie auniem un pie jēriem pēc viņu skaita, kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura, viņa ēdamā upura un viņa dzeramiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Un septītā dienā septiņus vēršus, divus aunus, četrpadsmit gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Līdz ar viņu ēdamiem upuriem un ar viņu dzeramiem upuriem pie vēršiem, pie auniem un pie jēriem pēc viņu skaita, kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Un vienu āzi par grēku upuri, klāt pie tā ikdienas dedzināmā upura, viņa ēdamā upura un viņa dzeramā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Astotā dienā lai jums ir svēta sapulce; nekādu darbu jums nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Un jums būs pienest dedzināmo upuri, uguns upuri, par saldu smaržu Tam Kungam, vienu vērsi, vienu aunu, septiņus gada vecus jērus, kas bez vainas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Viņu ēdamos upurus, viņu dzeramos upurus pie tā vērša, pie tā auna un pie tiem jēriem pēc viņu skaita, kā pienākas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Un vienu āzi par grēku upuri klāt pie tā ikdienas dedzināmā upura un viņa ēdamā upura un viņa dzeramā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'To jums Tam Kungam būs darīt savos noliktos laikos, līdz ar saviem solījumiem un savām labprātības dāvanām, saviem dedzināmiem upuriem un saviem ēdamiem upuriem un dzeramiem upuriem un saviem pateicības upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Un Mozus sacīja Israēla bērniem visu, ko Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Un Mozus runāja uz Israēla bērnu cilšu virsniekiem: šis ir tas vārds, ko Tas Kungs pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Ja kāds vīrs Tam Kungam sola solījumu vai zvērē zvērestu, savai dvēselei ko aizliegdams, - lai tas savu vārdu nelauž; visu, kas no viņa mutes ir izgājis, tam būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Un kad kāda sieviete Tam Kungam sola solījumu un tēva namā meita būdama apņēmās, sev ko aizliegt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Un kad viņas tēvs dzird par šo solījumu un aizliegumu, un par to klusu cieš, tad būs pastāvēt visiem viņas solījumiem un aizliegumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Bet ja viņas tēvs to neatļauj tai dienā, kad viņš to dzird, tad nebūs pastāvēt nevienam no viņas solījumiem un aizliegumiem, ko viņa savai dvēselei aizliegusi, bet Tas Kungs viņai piedos, jo viņas tēvs viņai to nav atļāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Bet ja viņa ir pie vīra un solījumu uzņēmusies, vai no viņas lūpām izšāvies savai dvēselei ko aizliegt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Un viņas vīrs to dzird un tai dienā, kad to dzird, par to klusu cieš, tad būs pastāvēt viņas solījumiem un aizliegumiem, ko viņa savai dvēselei aizliegusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Bet kad viņas vīrs tai dienā, kad to dzird, to neatļauj un atceļ viņas solījumu, ko tā uzņēmusies un kas no viņas lūpām izšāvies un ko viņa savai dvēselei aizliegusi, tad Tas Kungs viņai piedos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Atraitnei vai atstādinātai sievai solījums un viss, ko tā savai dvēselei aizliegusi, stipri jātur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Bet ja viņa sava vīra namā ir apsolījusies vai zvērēdama savai dvēselei ko aizliegusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Un viņas vīrs to dzirdējis, un par to klusu cietis, to atļaudams, tad būs pastāvēt visiem viņas solījumiem un visiem viņas aizliegumiem, ko tā savai dvēselei aizliegusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Bet ja viņas vīrs to atcēlis tai dienā, kad viņš to dzirdējis, tad nekas lai nepastāv no visa, kas no viņas mutes izgājis, ko viņa apsolījusi un savai dvēselei aizliegusi; viņas vīrs to atcēlis, un Tas Kungs viņai piedos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Visu, ko ir solījusi, un visu, ko zvērēdama aizliegusies, par dvēseles mērdēšanu, to viņas vīrs vai apstiprinās vai atcels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Bet ja viņas vīrs klusu ciezdams par to dienu no dienas klusu cieš, tad viņš apstiprina visus viņas solījumus vai visus viņas aizliegumus, ko tā uzņēmusies; viņš apstiprina caur to, ka viņš par to ir klusu cietis tai dienā, kad to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Bet kad viņš to atceļ pēc tam, kad to bija dzirdējis, tad tam būs nest viņas noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Šie ir tie likumi, ko Tas Kungs Mozum ir pavēlējis, starp vīra un viņa sievas, starp tēva un viņa jaunās meitas, kamēr viņa vēl ir bez vīra sava tēva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Atrieb Israēla bērnus pie Midijaniešiem; tad tu tapsi piepulcināts pie saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Tad Mozus runāja uz tiem ļaudīm un sacīja: lai no jums vīri apbruņojās uz karu un lai tie ceļas pret Midijaniešiem, To Kungu atriebt pie Midijaniešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'No visām Israēla ciltīm no cilts pa tūkstoti jums būs sūtīt karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Tā no Israēla tūkstošiem tapa nodoti pa tūkstoti no ikvienas cilts, divpadsmit tūkstoši apbruņoti uz karu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Un Mozus tos sūtīja karā, tūkstoti no ikvienas cilts, un Pinehasu, priestera Eleazara dēlu, ar tiem svētiem rīkiem un skanīgām trumetēm viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Un tie kāvās pret Midijanu, kā Tas Kungs Mozum bija pavēlējis, un nokāva visu, kas bija no vīriešu kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Un tie nokāva ar tiem citiem nokautiem Midijana ķēniņus Evu un Reķemu un Curu un Huru un Rebu, piecus Midijana ķēniņus; tā tie arī nokāva Bileāmu, Beora dēlu, ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Un Israēla bērni aizveda gūstītās Midijaniešu sievas līdz ar viņu bērniem un laupīja visus viņu lopus un visus viņu ganāmos pulkus un visu viņu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Un visas viņu pilsētas ar viņu māju vietām un ar visām viņu pilīm tie sadedzināja ar uguni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Un ņēma visu laupījumu un visu, ko tie bija sagūstījuši, cilvēkus un lopus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Un noveda pie Mozus un priestera Eleazara un pie visas Israēla bērnu draudzes, ko bija gūstījuši, saņēmuši un laupījuši, uz lēģeri Moaba klajumos, kas ir pie Jardānes pret Jēriku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Bet Mozus un priesteris Eleazars, un visi draudzes virsnieki viņiem gāja pretī ārā priekš lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Un Mozus apskaitās pret tiem kara virsniekiem, tiem virsniekiem pār tūkstošiem un tiem virsniekiem pār simtiem, kas no tās kara kaušanās nāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Un Mozus uz tiem sacīja: kam tad jūs visas sievas esat pametuši dzīvas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Redzi, šās bija caur Bileāma padomu vainīgas, ka Israēla bērni apgrēkojās pret To Kungu, Peora dēļ, kādēļ mocība nāca pār Tā Kunga draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Nu tad nokaujiet visus, kas ir no vīriešu kārtas starp tiem bērniem, un nokaujiet visas sievas, kas vīru ir atzinušas un pie vīra gulējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Bet visus bērnus no sieviešu kārtas, un kas nav gulējušas pie vīra, pametat dzīvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Un jūs paliekat ārā lēģera priekšā septiņas dienas, ikviens, kas cilvēku nokāvis, un ikviens, kas nokautu aizskāris. Trešā dienā un septītā dienā jums būs šķīstīties, jums un jūsu gūstītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Un visas drēbes un visas ādu lietas un visu, kas darīts no kazu spalvas un visus koka rīkus jums būs šķīstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Un priesteris Eleazars sacīja uz visiem karavīriem, kas karā bija gājuši: šis ir tas bauslības likums, ko Tas Kungs Mozum pavēlējis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Zeltu un sudrabu un varu un dzelzi un alvu un svinu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Visu, kas panes uguni, to jums būs laist caur uguni, ka top šķīsts, bet turklāt ar slacinājamu ūdeni tam būs tapt šķīstītam; bet viss, kas uguni nepanes, to jums būs laist caur ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Jums arī būs mazgāt savas drēbes septītā dienā, ka topat šķīsti, un tad jums būs nākt lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Skaiti, cik tā laupījuma, tos sagūstītos cilvēkus un lopus, tu un priesteris Eleazars un tie draudzes cilšu priekšnieki,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Un dali to laupījumu uz pusi starp tiem, kas karā gājuši un ir kāvušies, un starp visu draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Un ņem vienu daļu priekš Tā Kunga no tiem karavīriem, kas karā izgājuši, no piecsimtiem vienu dvēseli, no cilvēkiem un no vēršiem un no ēzeļiem un no sīkiem lopiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'No tās puses, kas ir viņu daļa, tev to būs ņemt un dot priesterim Eleazaram par cilājamu upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Bet no tās Israēla bērnu puses tev būs ņemt vienu sagūstītu no piecdesmit, no cilvēkiem, no vēršiem, no ēzeļiem un no sīkiem lopiem un no visiem lopiem, un tos tev būs dot tiem Levitiem, kas Tā Kunga dzīvokli kopj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Tad Mozus un priesteris Eleazars darīja, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Un tas atlikušais laupījums no tā, ko tie kara ļaudis bija laupījuši, bija sešsimt un septiņdesmit pieci tūkstoši sīku lopu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Un septiņdesmit divi tūkstoši liellopu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Un sešdesmit un viens tūkstotis ēzeļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Un cilvēku dvēseles, tās sievietes kas vīru nebija atzinušas, visas tās dvēseles trīsdesmit divi tūkstoši dvēseļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Un tā viena puse, to daļa, kas bija karā gājuši, bija savā pulkā trīssimt trīsdesmit septiņi tūkstoši un piecsimt sīku lopu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Un tā daļa priekš Tā Kunga no tiem sīkiem lopiem bija sešsimt septiņdesmit un pieci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Un liellopu bija trīsdesmit seši tūkstoši, un viņu daļa priekš Tā Kunga bija septiņdesmit divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Un ēzeļu bija trīsdesmit tūkstoši un piecsimt, un viņu noliktā daļa priekš Tā Kunga bija sešdesmit un viens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Un cilvēku dvēseļu bija sešpadsmit tūkstoši, un viņu noliktā daļa priekš Tā Kunga bija trīsdesmit divas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Un Mozus deva priesterim Eleazaram to daļu par cilājamu upuri Tam Kungam, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Un no Israēla bērnu pustiesas, ko Mozus biju ņēmis no tiem karavīriem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Šī draudzes pustiesa bija sīku lopu trīs simt un trīsdesmit septiņi tūkstoši un piecsimt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Un liellopu bija trīsdesmit seši tūkstoši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Un ēzeļu bija trīsdesmit tūkstoši un piecsimt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Un cilvēku dvēseļu bija sešpadsmit tūkstoši. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Un Mozus ņēma no Israēla bērnu pustiesas vienu gūstītu no piecdesmit, no cilvēkiem un lopiem, un deva tos tiem Levitiem, kas Tā Kunga dzīvokli kopa, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Tad piegāja pie Mozus tie kara pulka virsnieki, tie virsnieki pār tūkstošiem un tie virsnieki pār simtiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Un sacīja uz Mozu: tavi kalpi skaitījuši to karavīru pulku, kas mums bija padoti, un tur neviena no mums netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Tāpēc mēs Tam Kungam esam atnesuši upuri, ikviens, ko viņš ir atradis no zelta rīkiem, no ķēdēm, no roku gredzeniem, no ausu sprādzēm un no dārgām rotām, - savas dvēseles salīdzināt Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Tad Mozus un priesteris Eleazars no tiem saņēma to zeltu, visādus smalkus izstrādājumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Un viss zelts, ko tie Tam Kungam atnesa par cilājamu upuri, bija sešpadsmit tūkstoši septiņsimt un piecdesmit sēķeļi, no tiem virsniekiem pār tūkstošiem un no tiem virsniekiem pār simtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Jo tie karavīri bija laupījuši ikviens priekš sevis paša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Tad Mozus un priesteris Eleazars saņēma to zeltu no tiem virsniekiem pār tūkstošiem un pār simtiem un to atnesa saiešanas teltī, par piemiņu Israēla bērniem Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Un Rūbena un Gada bērniem bija ļoti daudz lopu, un tie aplūkoja Jaēzeras un Gileādas zemi, un raugi, šī vieta bija vieta priekš ganāmiem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Tad Gada bērni un Rūbena bērni nāca un runāja uz Mozu un uz priesteri Eleazaru un uz tiem draudzes virsniekiem un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarota un Dibona un Jaēzera un Nimra un Hešbona un Eleale un Sebana un Neba un Beona,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Tā zeme, ko Tas Kungs ir sitis Israēla draudzes priekšā, tā ir zeme priekš ganāmiem pulkiem, un mums, taviem kalpiem, ir ganāmi pulki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Un tie sacīja: ja mēs žēlastību esam atraduši tavās acīs, tad lai šī zeme top dota taviem kalpiem par īpašumu un neliec mums iet pāri pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Bet Mozus sacīja uz Gada bērniem un uz Rūbena bērniem: vai tad jūsu brāļi ies karā un jūs paliksiet še?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Kāpēc jūs Israēla bērniem sirdi novēršat, nenoiet uz to zemi, ko Tas Kungs viņiem devis? -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tā jūsu tēvi darīja, kad es tos no Kādeš Barneas sūtīju, to zemi aplūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Kad tie bija nākuši pie Eškoles upes un to zemi bija izlūkojuši, tad tie novērsa Israēla bērnu sirdi, ka tie negribēja iet uz to zemi, ko Tas Kungs viņiem gribēja dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Tad Tā Kunga bardzība iedegās tai dienā un Viņš zvērēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Tiem vīriem, kas no Ēģiptes zemes ir nākuši, kam divdesmit gadi un pāri, tiem nebūs redzēt to zemi, ko Es viņu tēviem Ābrahāmam, Īzakam un Jēkabam esmu zvērējis, jo tie Man nav paklausījuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Tik vien Kālebs, Jefunna dēls, tas ķenaisietis, un Jozuas, Nuna dēls, jo tie Tam Kungam ir paklausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Tā Tā Kunga bardzība iedegās pret Israēli un lika tiem maldīties tuksnesī četrdesmit gadus, tiekams viss tas augums izmira, kas bija ļaunu darījis priekš Tā Kunga acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Un nu redzi, jūs savu tēvu vietā esat nākuši, grēcīgu ļaužu dzimums, vairodami Tā Kunga bargo dusmību pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Jo ja jūs nogriezīsities no Viņa, tad Viņš šiem vēl liks palikt tuksnesī, un jūs nomaitāsiet visus šos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Tad tie pie viņa piegāja un sacīja: mēs šeit gribam laidarus taisīt priekš saviem ganāmiem pulkiem un pilsētas priekš saviem bērniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Bet mēs paši steigšus apbruņosimies Israēla bērnu priekšā, tiekams tos būsim aizveduši viņu vietā; bet mūsu bērni lai paliek stiprās pilsētās to zemes iedzīvotāju dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Mēs negriezīsimies atpakaļ uz savām mājām, tiekams Israēla bērni nebūs dabūjuši ikviens savu daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Jo mēs neņemsim līdz ar viņiem savu daļu viņā Jardānes pusē, vai tālāki, bet mūsu daļa mums nāksies šai Jardānes pusē pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Tad Mozus uz tiem sacīja: ja jūs šo lietu tā gribat darīt, ka jūs apbruņojaties Tā Kunga priekšā uz karu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Un ikviens no jums, kam bruņas, iesiet pār Jardāni Tā Kunga priekšā, kamēr Viņš Savus ienaidniekus Savā priekšā izdzīs, un tā zeme priekš Tā Kunga būs uzvarēta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Tad jūs pēc tam varat iet atpakaļ un būsiet nenoziedzīgi Tā Kunga un Israēla priekšā, un šī zeme jums būs par daļu Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Bet ja jūs tā nedarīsiet, redzi, tad jūs pret To Kungu grēkosiet un jūs samanīsiet savus grēkus, kad tie jūs atradīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Uztaisat sev pilsētas priekš saviem bērniem un laidarus priekš saviem sīkiem lopiem un dariet pēc tā vārda, kas no jūsu mutes izgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Tad Gada bērni un Rūbena bērni runāja uz Mozu un sacīja: tavi kalpi darīs, kā mans kungs pavēl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Mūsu bērni, mūsu sievas, mūsu ganāmie pulki un visi mūsu lopi paliks tur Gileādas pilsētās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Bet tavi kalpi, visi apbruņoti, noies karā Tā Kunga priekšā, kā mans kungs ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Tad Mozus viņu dēļ pavēlēja priesterim Eleazaram un Jozuam, Nuna dēlam, un Israēla cilšu tēvu virsniekiem, un Mozus uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Ja Gada bērni un Rūbena bērni, ikviens kam bruņas, līdz ar jums ies karā pār Jardāni Tā Kunga priekšā, un tā zeme jūsu priekšā būs uzvarēta, tad dodat tiem Gileādas zemi par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Bet ja tie ar jums nenoies apbruņoti, tad tiem savu daļu būs dabūt jūsu starpā Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Tad Gada bērni un Rūbena bērni atbildēja un sacīja: ko Tas Kungs uz taviem kalpiem runājis, tā mēs darīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Mēs aiziesim apbruņoti Tā Kunga priekšā uz Kanaāna zemi un savu iemantojamo īpašumu turēsim šai Jardānes pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Tad Mozus viņiem deva, Gada bērniem un Rūbena bērniem un Manasus, Jāzepa dēla, pusciltij Sihona, Āmoriešu ķēniņa, valsti un Oga, Basanas ķēniņa, valsti, to zemi ar tām pilsētām viņu robežās, tās zemes pilsētas visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Un Gada bērni uztaisīja Dibonu un Atarotu un Arveru');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Un Atarot-Zovanu un Jaēzeru, Jogabeū');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Un Bet-Nimru un Betaranu, stipras pilsētas un sīku lopu laidarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Un Rūbena bērni uztaisīja Hešbonu un Eleali un Ķīriataīmu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Un Nebu un Baāl-Meonu ar citiem vārdiem un Sibmahu, un tie nosauca tās pilsētas, ko tie uztaisīja, ar citiem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Un Mahira, Manasus dēla bērni, gāja uz Gileādu un to uzņēma un izdzina tos Amoriešus, kas tur bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Tā Mozus Gileādu deva Mahiram, Manasus dēlam, un viņš tur dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Un Jaīrs, Manasus dēls, gāja un uzņēma viņu ciemus un tos nosauca Avot-Jaīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Un Nobus gāja un uzņēma Kenatu ar viņas piederīgām vietām un to nosauca Nobu pēc sava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Šie ir Israēla bērnu ceļa gājumi, kā viņi no Ēģiptes zemes ir izgājuši pēc saviem pulkiem caur Mozu un Āronu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Un Mozus uz Tā Kunga vārdu aprakstīja viņu iziešanu pēc viņu ceļa gājumiem, un šie ir viņu ceļa gājumi, viņiem izejot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Tie izgāja no Raēmzes pirmā mēnesī piecpadsmitā dienā; pirmā mēnesī, otrā Pasa svētku dienā Israēla bērni izgāja caur augstu roku priekš visu ēģiptiešu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Un ēģiptieši apraka visus pirmdzimtos, ko Tas Kungs viņu starpā bija sitis; Tas Kungs arī viņu dievus bija sodījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Un Israēla bērni izgāja no Raēmzes un apmetās Sukotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Un izgāja no Sukota un apmetās Etamā, kas ir tuksneša galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Un tie izgāja no Etama un griezās uz Pi Hahirota ieleju, kas ir pret Baāl Cefonu un apmetās pret Migdolu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Un izgāja no Ķirota un gāja vidū caur jūru uz tuksnesi un staigāja treju dienu gājumus Etama tuksnesī un apmetās Mārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Un izgāja no Māras un nāca uz Elimu, un Elimā bija divpadsmit avoti un septiņdesmit palma koki, un tie tur apmetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Un izgāja no Elima un apmetās pie niedru jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Un izgāja no niedru jūras un apmetās Sina tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Un izgāja no Sina tuksneša un apmetās Dofkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Un izgāja no Dofkas un apmetās Āluzā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Un izgāja no Āluzas un apmetās Refidos, bet tur nebija ūdens tiem ļaudīm ko dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Un tie izgāja no Refidiem un apmetās Sinaī tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Un izgāja no Sinaī tuksneša un apmetās pie tiem kārības kapiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Un izgāja no tiem kārības kapiem un apmetās Hacerotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Un izgāja no Hacerotas un apmetās Ritmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Un izgāja no Ritmas un apmetās RimonParecā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Un izgāja no RimonParecas un apmetās Libnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Un izgāja no Libnas un apmetās Rissā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Un izgāja no Rissas un apmetās Ķelatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Un izgāja no Ķelatas un apmetās pie Zāvera kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Un izgāja no Zāvera kalna un apmetās Aradā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Un izgāja no Aradas un apmetās Maķelotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Un izgāja no Maķelotas un apmetās Taātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Un izgāja no Taātas un apmetās Tārākā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Un izgāja no Tārākas un apmetās Mitkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Un izgāja no Mitkas un apmetās Asmonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Un izgāja no Asmonas un apmetās Mozerotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Un izgāja no Mozerotas un apmetās BneJaēkanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Un izgāza no BneJaēkanas un apmetās Orģidgadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Un izgāja no Orģidgadas un apmetās Jotbatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Un izgāja no Jotbatas un apmetās Abronā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Un izgāja no Abronas un apmetās Eceon-Ģēberā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Un izgāja no Eceon-Ģēberas un apmetās Cin tuksnesī, tas ir Kādeš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Un izgāja no Kādešas un apmetās pie Hora kalna, Edoma zemes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Tad Ārons, tas priesteris, gāja uz Hora kalnu pēc Tā Kunga vārda un tur nomira četrdesmitā gadā pēc tam, kad Israēla bērni bija izgājuši no Ēģiptes zemes, piektā mēnesī, pirmā mēneša dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Bet Ārons bija simts divdesmit un trīs gadus vecs, kad viņš nomira uz Hora kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Tad tas Kanaānietis, ķēniņš Arads, kas dienvidu(Negebas) pusē dzīvoja Kanaāna zemē, dzirdēja Israēla bērnus nākam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Un tie izgāja no Hora kalna un apmetās Calmonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Un izgāja no Calmonas un apmetās Pūnonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Un izgāja no Pūnonas un apmetās Obotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Un izgāja no Obotas un apmetās pie Ijim Abarima uz Moaba robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Un izgāja no Ijim un apmetās Dibon-Gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Un izgāja no Dibon-Gadas un apmetās Almon-Diblataīmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Un izgāja no Almon-Diblataīmas un apmetās Abarim kalnos pret Nebu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Un izgāja no Abarim-kalniem un apmetās Moaba klajumos pie Jardānes pret Jēriku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Un apmetās pie Jardānes no Bet-Jezimotam līdz Abel-Šitimai Moaba klajumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Un Tas Kungs runāja uz Mozu Moaba klajumos pie Jardānes pret Jēriku, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Runā uz Israēla bērniem un saki tiem: kad jūs iesiet pāri pār Jardāni uz Kanaāna zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Tad jums būs izdzīt savā priekšā visus zemes iedzīvotājus un izdeldēt visus viņu elku tēlus un izdeldēt visas viņu lietās bildes un nopostīt visus viņu elku kalnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Un jums to zemi būs ieņemt un tanī dzīvot, jo Es jums to zemi esmu devis iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Un jums to zemi būs dalīt caur meslošanu pēc savām ciltīm; tai, kam daudz ļaužu, lai dod lielāku daļu, un tai, kam maz ļaužu, mazāku daļu, - kā ikvienai meslošana izkrīt, to lai tā dabū, - jums to zemi būs dalīt pēc savām tēvu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Bet ja jūs tos zemes iedzīvotājus neizdzīsiet savā priekšā, tad notiks, kurus jūs no tiem atlicināsiet, tie jums taps par ērkšķiem jūsu acīs un par dzeloni jūsu sānos, un jūs spaidīs tai zemē, kur jūs dzīvojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Un notiks, kā Es viņiem domāju darīt, tā Es jums darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Pavēli Israēla bērniem un saki tiem: kad jūs uz Kanaāna zemi nākat, tad šī būs tā zeme, kas jums kritīs par īpašumu: Kanaāna zeme pēc savām robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Tad nu dienvidu mala lai jums ir no Cin tuksneša pie Edoma sāniem, un dienvidu robeža lai jums ir no sāls jūras gala pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Un lai tā robeža iet apkārt no dienvidiem(Negebas) uz Akrabu kalniem un lai iet pāri uz Cin, un lai iziet uz Kādeš Barneas dienvidu pusi, un lai iet uz Acar Adaru un iet cauri līdz Acmonam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Un tad šai robežai būs iet apkārt no Acmona uz Ēģiptes upi, un viņas gals lai ir pie jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Vakara pusē lai tā lielā jūra jums ir par robežu,- šī lai jums ir tā vakaru robeža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Un šī lai jums ir tā ziemeļu robeža: no tās lielās jūras jums būs mērot līdz Hora kalnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'No Hora kalna jums būs mērot, kamēr nāk uz Amatu, un tā robeža lai noiet uz Cedadu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Un tā robeža lai stiepjas uz Zifronu, un viņas gals lai ir Enana ciems; šī lai jums ir tā ziemeļu robeža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Un par robežu pret rītiem jums būs mērot no Enana ciema līdz Šefamam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Un šī robeža lai nostiepjas no Šefama uz Riblu, Aīnam pret rītiem; pēc lai tā robeža nostiepjas un iet gar Ķinneretes jūras malu pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Un šī robeža lai nostiepjas gar Jardāni, un viņas gals lai ir sāls jūra. Šī nu lai jums ir tā zeme pēc savām robežām visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Un Mozus pavēlēja Israēla bērniem un sacīja: šī ir tā zeme, ko jums caur meslošanu būs par īpašumu dabūt, ko Tas Kungs ir pavēlējis dot tām deviņām ciltīm un tai pusciltij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Jo Rūbena bērnu cilts pēc saviem tēvu namiem un Gada bērnu cilts pēc saviem tēvu namiem un Manasus puscilts savu daļu ir dabūjušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Divas ciltis un viena puscilts savu īpašumu ir dabūjušas šaipus Jardānes, no Jērikus pret rītiem, pret austrumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Šie ir to vīru vārdi, kas to zemi jums lai izdala: Eleazars, tas priesteris, un Jozuas, Nuna dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Un no ikvienas cilts jums būs ņemt vienu virsnieku pie zemes izdalīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Un šie ir to vīru vārdi: no Jūda cilts Kālebs, Jefunna dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Un no Sīmeana bērnu cilts Šemuēls, Amiuda dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Un no Benjamina cilts Elidus, Ķislona dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Un no Dana bērnu cilts virsnieks Būkus, Jagla dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'No Jāzepa bērniem, no Manasus cilts virsnieks Hanniēls, Efoda dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Un no Efraīma bērnu cilts virsnieks Ķemuēls, Šiftana dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Un no Zebulona bērnu cilts virsnieks Elicafans, Parnaka dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Un no Īsašara bērnu cilts virsnieks Paltiēls, Asana dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Un no Ašera bērnu cilts virsnieks Aķiuds, Zelona dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Un no Naftalus bērnu cilts virsnieks Pedaēls, Amiuda dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Šie ir tie, kam Tas Kungs pavēlējis Israēla bērniem izdalīt to īpašumu Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Un Tas Kungs runāja uz Mozu Moaba klajumos pie Jardānes pret Jēriku un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Pavēli Israēla bērniem, lai tie no savas iemantojamās daļas dod pilsētas Levitiem, kur dzīvot, un lai tie dod Levitiem arī apgabalus ārā ap viņu pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Un tās pilsētas tiem būs, lai tie tur dzīvo, bet tie apgabali lai ir priekš viņu lieliem un sīkiem lopiem un priekš visiem viņu ganāmiem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Un tie pilsētu apgabali, ko jūs Levitiem dosiet, lai ir no pilsētas mūriem uz āru tūkstošas olektis uz visām pusēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Un jums būs mērot pilsētas āra pusē pret rītiem divtūkstoš olektis un pret dienas vidiem divtūkstoš olektis un pret vakariem divtūkstoš olektis un pret ziemeļiem divtūkstoš olektis, ka pilsēta ir vidū; šie būs viņiem tie pilsētu apgabali.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Un to pilsētu starpā, ko jūs dosiet Levitiem, lai ir sešas glābšanas pilsētas, kas jums jādod, ka tas nokāvējs uz turieni bēg, un pie tām klāt viņiem būs dot vēl četrdesmit divas pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Visas pilsētas, ko jūs dosiet Levitiem, lai ir četrdesmit astoņas pilsētas līdz ar viņu apgabaliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Un no tām pilsētām, ko jūs dosiet no Israēla bērnu daļas, jums būs ņemt daudz no tiem, kam ir daudz, un maz no tiem, kam ir maz; ikvienam no savām pilsētām būs dot Levitiem pēc savas daļas, ko tas mantojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Un Tas Kungs runāja uz Mozu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Runā uz Israēla bērniem un saki tiem: kad jūs iesiet pāri pār Jardāni uz Kanaāna zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Tad jums būs iecelt pilsētas, kas jums lai ir par glābšanas pilsētām, ka uz turieni tas nokāvējs var bēgt, kas kādu cilvēku netīši nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Un šīs pilsētas lai jums ir par glābšanu no atriebēja, ka tam nokāvējam nav jāmirst, tiekams viņš nav stāvējis draudzes priekšā iztiesāšanas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Un tās pilsētas, ko jūs dosiet, lai jums ir sešas glābšanas pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Trīs no šīm pilsētām noliekat viņpus Jardānes un trīs no tām pilsētām noliekat Kanaāna zemē, - glābšanas pilsētas lai tās ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Šīs pilsētas lai Israēla bērniem ir par glābšanu, arī svešiniekam un piedzīvotājam jūsu starpā, ka uz turieni var bēgt ikviens, kas kādu cilvēku netīši nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Bet ja viņš to ar dzelzs ieroci sitis, ka mirst, tas ir slepkava, šim slepkavam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Vai ja viņš to sit ar akmeni rokā, ar ko var nokaut, tā ka mirst, tas ir slepkava, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Vai ja viņš to sit ar koka gabalu, ar ko var nokaut, tā ka mirst, tas ir slepkava, tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Asiņu atriebējs lai nonāvē to slepkavu; kad tas viņu sastop, lai viņu nokauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Un ja viņš nīdēdams to grūdis, vai tīši uz to ko sviedis, ka tas mirst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Vai ja viņš nīdēdams to sitis ar savu roku, ka tas mirst, tad tam būs tapt nokautam; jo viņš ir slepkava; asiņu atriebējs lai to nokauj, kad viņu sastop.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Bet ja viņš netīši bez ienaida grūdis, vai no nejauši kādu rīku uz to sviedis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Vai akmenim, caur ko tas var mirt, netīši tam licis uzkrist, tā ka tas mirst, un nav bijis viņa ienaidnieks, nedz meklējis viņa nelaimi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Tad lai draudze tiesā starp nokāvēju un asiņu atriebēju pēc šiem likumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Un draudzei nokāvēju būs izglābt no asiņu atriebēja rokas, un draudzei būs to novest viņa glābšanas pilsētā, kurp viņš bija bēdzis, un tur tam būs palikt, kamēr augstais priesteris miris, kas ir svaidīts ar svēto eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Bet ja nokāvējs iziedams izies no savas glābšanas pilsētas robežām, kurp bija nobēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Un asiņu atriebējs ārpus viņa glābšanas pilsētas robežām to atradīs un nokaus, tad tas nav noziedzīgs pie viņa asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Jo tam bija jāpaliek savā glābšanas pilsētā, kamēr augstais priesteris nomirs; bet pēc tā augstā priestera miršanas nokāvējs lai griežas atpakaļ uz savu zemes daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Un tas lai jums ir par tiesas likumu pie jūsu pēcnākamiem visās jūsu māju vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Ja kas kādu cilvēku nosit, tad uz liecinieku vārdu slepkavam būs tapt nokautam, bet vienam lieciniekam vien nebūs liecību dot pret kādu cilvēku, ka tam būtu jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Tev arī nebūs ņemt atpirkšanas maksu par slepkavu, kas nāvi pelnījis, jo tam būs tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Jums arī nebūs ņemt atpirkšanas maksu par to, kas savā glābšanas pilsētā ir nobēdzis, ka tas atkal nāktu dzīvot savā zemes daļā, pirms augstais priesteris miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Un jums nebūs sagānīt to zemi, kur jūs esat; jo tās tādas asinis sagāna to zemi, un to zemi nevar salīdzināt to asiņu dēļ, kas tur izlietas, kā vien caur tā asinīm, kas tās izlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Tad nu nesagāniet to zemi, kur jūs dzīvojat, un kur Mans dzīvoklis, jo Es esmu Tas Kungs, kas dzīvo Israēla bērnu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Un tie tēvu namu virsnieki no Gileāda bērnu cilts, - tas bija Mahira dēls, šis Manasus dēls, no Jāzepa dēlu ciltīm, - tie piegāja un runāja priekš Mozus un priekš tiem lielkungiem, Israēla bērnu tēvu namu virsniekiem, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Tas Kungs ir pavēlējis manam kungam caur meslošanu izdot to zemi Israēla bērniem par īpašumu, un manam kungam caur To Kungu ir pavēlēts, mūsu brāļa Celofehada īpašumu dot viņa meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Kad nu tās paliktu vienam no Israēla bērnu ciltīm par sievām, tad viņu īpašums taptu atrauts no mūsu tēvu īpašuma un pielikts tās cilts īpašumam, kurp tās noietu, un mūsu īpašuma daļa būtu mazināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Un ja Israēla bērniem nāk gaviles gads, tad viņu īpašums taptu pielikts tās cilts īpašumam, kurp tās noietu, un no mūsu tēvu cilts īpašuma viņu īpašums ietu nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Tad Mozus pavēlēja Israēla bērniem pēc Tā Kunga vārda un sacīja: Jāzepa bērnu cilts runā pareizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Šis ir tas vārds, ko Tas Kungs pavēlējis Celofehada meitām un sacījis: lai tās iet pie vīra, kā viņām patīk; bet lai kļūst par sievām sava tēva cilts radiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Ka Israēla bērnu īpašums no cilts uz cilti netop pārcelts, jo Israēla bērniem būs turēties ikvienam pie savu tēvu cilts īpašuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Un ikviena meita, kam ir zemes daļa kādā Israēla bērnu ciltī, lai iet pie vīra pie kāda no savas tēva cilts radiem, ka Israēla bērni patur savu tēvu mantas daļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Un īpašums netop pārcelts no vienas cilts uz otru; jo Israēla bērnu ciltis lai turas ikviena pie sava īpašuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Kā Tas Kungs Mozum bija pavēlējis, tā Celofehada meitas darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Jo Maēla, Tirca un Hagla un Milka un Noa, Celofehada meitas, kļuva par sievām sava tēva brāļa dēliem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Jāzepa dēla Manasus bērnu radiem tās kļuva par sievām; tā viņu īpašums palika pie viņu tēva radu cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Šie ir tie likumi un tās tiesas, ko Tas Kungs caur Mozu Israēla bērniem ir pavēlējis Moaba klajumos pie Jardānes pret Jēriku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Šie ir tie vārdi, ko Mozus runāja uz visu Israēli viņpus Jardānes tuksnesī, tai klajumā pret Sūfu, starp Pāranu un Tovelu un Labanu un Hacerotu un Dizaābu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Vienpadsmit dienu gājumus no Horeba, pa Seīra kalna ceļu līdz Kādeš-Barneai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Un notikās četrdesmitā gadā, vienpadsmitā mēnesī, pirmā mēneša dienā, tad Mozus runāja uz Israēla bērniem, kā Tas Kungs viņam priekš tiem bija pavēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Pēc tam, kad viņš bija sakāvis Sihonu, Amoriešu ķēniņu, kas dzīvoja Hešbonā, un Ogu, Basanas ķēniņu, kas dzīvoja Astarotā un Edrejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Viņpus Jardānes, Moaba zemē, Mozus sāka šo bauslību izskaidrot sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Tas Kungs mūsu Dievs runāja uz mums Horeba kalnā un sacīja: jūs gan ilgi esat palikuši pie šā kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Griežaties un ceļaties un ejat uz Amoriešu kalniem un pie visiem viņu kaimiņiem klajumā, kalnos un lejā un pret dienvidiem un jūras malā, uz Kanaāna zemi un uz Lībanu, līdz tai lielai upei, tai Eifrat upei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Redzi, Es jums nododu šo zemi, ejat, uzņemat to zemi, ko Tas Kungs jūsu tēviem Ābrahāmam, Īzakam un Jēkabam ir zvērējis, dot viņiem un viņu dzimumam pēc viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Un tanī laikā es uz jums runāju un sacīju: es viens pats jūs nevaru panest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Tas Kungs, jūsu Dievs, jūs ir vairojis, un redzi, jūs šodien esat savā pulkā tā kā debess zvaigznes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Tas Kungs, jūsu tēvu Dievs, lai vēl pie jums pieliek, ka esat tūkstoškārt vairāk, un lai jūs svētī, itin kā Viņš uz jums ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Kā man vienam būs panest jūsu grūtumu un nastu un strīdu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Dabūjat sev gudrus, prātīgus un zināmus vīrus pēc savām ciltīm, lai tos jums ieceļu par virsniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Un jūs man atbildējāt sacīdami: tas ir labs vārds, ko tu runā, ka to gribi darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Tad es ņēmu jūsu cilšu virsniekus, gudrus un zināmus vīrus, un tos iecēlu par virsniekiem pār jums, virsniekus pār tūkstošiem un virsniekus pār simtiem un virsniekus pār piecdesmitiem un virsniekus pār desmitiem un uzraugus pēc jūsu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Un es jūsu soģiem tanī laikā pavēlēju un sacīju: pārklausinājiet tās lietas starp jūsu brāļiem un tiesājiet taisni starp ikvienu un viņa brāli un viņa piedzīvotāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Tiesā jums nebūs uzlūkot vaigu, tāpat mazo kā lielo jums būs klausīt, no neviena jums nebūs bīties, jo tas sods pieder Dievam; bet to lietu, kas priekš jums par grūtu, to jums būs nest pie manis, un es to klausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Tā es jums tanī laikā pavēlēju visas lietas, kas jums bija jādara. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Tad mēs cēlāmies no Horeba un gājām caur visu to lielo un briesmīgo tuksnesi, ko jūs esat redzējuši, pa to ceļu uz Amoriešu kalniem, itin kā Tas Kungs, mūsu Dievs, mums bija pavēlējis, un mēs nācām uz Kādeš-Barneū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Tad es jums sacīju: jūs esat nākuši pie Amoriešu kalniem, ko Tas Kungs, mūsu Dievs, mums dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Redzi, Tas Kungs, tavs Dievs, tev ir devis to zemi, celies, uzņem to, kā Tas Kungs, tavu tēvu Dievs, uz tevi runājis; nebīsties un neiztrūcinājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Tad jūs visi nācāt pie manis un sacījāt: sūtīsim vīrus savā priekšā, mums to zemi izlūkot un mums ziņu atnest, pa kuru ceļu lai ejam uz turieni, un par tām pilsētām, kurp nāksim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Tad man šī lieta patika un es ņēmu no jums divpadsmit vīrus, no ikvienas cilts vienu vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Un tie griezās un gāja uz tiem kalniem un nāca pie Eškoles upes un to izlūkoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Un tie ņēma no tiem zemes augļiem savā rokā un atnesa tos pie mums un stāstīja mums un sacīja: tā zeme, ko Tas Kungs, mūsu Dievs, mums dos, ir laba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Bet jūs negribējāt iet un bijāt nepaklausīgi Tā Kunga, sava Dieva, vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Un jūs kurnējāt savos dzīvokļos un sacījāt: tāpēc ka Tas Kungs mūs ienīst, Viņš mūs izvedis no Ēģiptes zemes, mūs nodot Amoriešu rokā un mūs izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kurp mums iet? Mūsu brāļi mūsu sirdi darījuši bailīgu sacīdami: tur ir ļaudis lielāki un garāki nekā mēs, tās pilsētas ir lielas un stipras līdz pat debesīm, un mēs tur arī esam redzējuši Enaka bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Tad es uz jums sacīju: neiztrūcināties un nebīstaties no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Tas Kungs, jūsu Dievs, kas iet jūsu priekšā, karos par jums, itin kā Viņš pie jums ir darījis Ēģiptes zemē priekš jūsu acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Un tuksnesī, kur tu esi redzējis, kā Tas Kungs, tavs Dievs, tevi nesis, itin kā vīrs savu dēlu nes, uz visiem ceļiem, kur tu esi gājis, tiekams jūs esat nākuši līdz šai vietai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Bet arī pie šī vārda jūs neticējāt uz To Kungu, savu Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Kas jūsu priekšā gāja ceļā, jums izlūkodams to vietu, kur jums apmesties pa nakti, ugunī jums rādīdams to ceļu, kas jums bija jāstaigā, un pa dienu padebesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Kad nu Tas Kungs jūsu vārdu balsi dzirdēja, tad Viņš apskaitās un zvērēja sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Nevienam no šiem vīriem, no šā niknā auguma, nebūs redzēt to labo zemi, ko Es esmu zvērējis dot jūsu tēviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Kā vien Kālebam, Jefunna dēlam, tam to būs redzēt, un tam Es došu to zemi, kur viņš staigājis, un viņa bērniem, tāpēc ka viņš pareizi klausījis Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Tas Kungs arī par mani apskaitās jūsu dēļ un sacīja: arī tu tur nenonāksi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jozuas, Nuna dēls, kas stāv tavā priekšā, tas tur nonāks; stiprini viņu, jo tas Israēlim to zemi izdalīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Un jūsu bērniņi, par kuriem jūs sacījāt, ka būšot par laupījumu, un jūsu bērni, kas šodien nezin nedz laba nedz ļauna, tie tur nonāks, un tiem Es to došu, un tiem to būs iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Bet jūs griežaties un ejat uz tuksnesi pa niedru jūras ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Tad jūs man atbildējāt un sacījāt: mēs pret To Kungu esam grēkojuši, mēs celsimies un karosim, kā Tas Kungs, mūsu Dievs, mums ir pavēlējis. Kad nu jūs ikviens ar saviem rīkiem apbruņojaties un bijāt gatavi iet uz tiem kalniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Tad Tas Kungs uz mani sacīja: saki viņiem, neceļaties un nekarojiet, jo Es neesmu jūsu vidū, ka netopat sakauti savu ienaidnieku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Bet kad es uz jums runāju, tad jūs neklausījāt un turējaties Tā Kunga vārdam pretī un palikāt pārgalvīgi un gājāt uz tiem kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Tad tie Amorieši, kas tanīs kalnos dzīvoja, jums izgāja pretī un dzinās jums pakaļ, kā bites dara, un jūs sakāva Seīrā līdz Hormai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Kad jūs nu atgriezušies Tā Kunga priekšā raudājāt, tad Tas Kungs neklausīja jūsu balsi un negrieza Savas ausis uz jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Un jūs palikāt Kādešā ilgu laiku, tās dienas, ko tur esat dzīvojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Tad mēs griezāmies un gājām uz tuksnesi pa niedru jūras ceļu, kā Tas Kungs uz mani bija runājis, un gājām ap Seīra kalniem daudz dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Un Tas Kungs uz mani runāja sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Jūs diezgan esat gājuši ap tiem kalniem, griežaties pret ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Un pavēli tiem ļaudīm sacīdams: jums jāstaigā caur savu brāļu, Ēsava bērnu, robežām, kas Seīrā dzīvo, tie no jums bīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Bet tikai sargājaties, nekarojiet ar tiem, jo Es jums no viņu zemes nedošu ne pēdas platuma, jo Es Ēsavam esmu devis Seīra kalnus par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Barību pērkat no viņiem par naudu, ka ēdat, un arī ūdeni pērkat no viņiem par naudu, ka dzerat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Jo Tas Kungs, tavs Dievs, tevi ir svētījis visos tavos rokas darbos, Viņš zina tavu staigāšanu caur šo lielo tuksnesi; šos četrdesmit gadus Tas Kungs, tavs Dievs, ir bijis ar tevi; nekā tev nav trūcis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Un mēs gājām garām saviem brāļiem, Ēsava bērniem, kas Seīrā dzīvo, pa klajuma ceļu, no Elata un Eceonģebera, un griezušies gājām pa Moaba tuksneša ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Tad Tas Kungs uz mani sacīja: neapbēdini Moabu un nekaro ar viņu, jo Es tev nedošu mantību no viņa zemes, tāpēc ka Es Aru esmu devis Lata bērniem par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Senāk tur dzīvoja Emieši, lieli un stipri un gari ļaudis, tā kā tie Enaķieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Tie arīdzan tapa turēti par milžiem, tā kā tie Enaķieši, un Moabieši tos sauca par Emiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Un Seīrā senāk dzīvoja Horieši, bet Ēsava bērni tos izdzina un tos izdeldēja savā priekšā un dzīvoja viņu vietā, itin kā Israēls ir darījis savā iemantotā zemē, ko Tas Kungs viņiem ir devis.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Nu ceļaties un ejat pār Zaredes upi. Tad mēs cēlāmies pār Zaredes upi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Tad nu tās dienas, cik ilgi no Kādeš Barneas esam gājuši, līdz kamēr esam gājuši pār Zaredes upi, ir trīsdesmit astoņi gadi, tiekams viss tas karavīru dzimums lēģerī bija nobeidzies, itin kā Tas Kungs viņiem bija zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Un Tā Kunga roka bija pret viņiem, viņus izdeldēt no lēģera, tiekams tie bija nobeigti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Un kad visi tie karavīri bija nobeigti un izmiruši no ļaužu vidus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Tad Tas Kungs uz mani runāja sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tev šodien būs iziet caur Moaba robežām pie Ara');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Un nākt Ammona bērnu tuvumā, bet neuzkrīti tiem un nekaro ar tiem, jo no Ammona bērnu zemes Es tev nedošu mantību, tāpēc ka Es to esmu devis par mantību Lata bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Šī arīdzan top turēta par milžu ļaužu zemi; milži senāk tur dzīvoja, un Ammonieši tos sauca par Zamzumiešiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Lieli un stipri un gari ļaudis, kā tie Enaķieši, un Tas Kungs tos izdeldēja viņu priekšā, tā ka šie viņus izdzina un tur dzīvoja viņu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Itin kā Viņš darījis Ēsava bērniem, kas Seīrā dzīvo, kuru priekšā Viņš Horiešus izdeldēja, un tie tos izdzina un dzīvoja viņu vietā līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Un Aviešus, kas ciemos dzīvoja līdz Gacai, Kaftorieši, kas no Kaftora nāca, ir izdeldējuši un dzīvojuši viņu vietā.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Ceļaties, izejat un ejat pāri pār Arnonas upi; redziet, Es esmu devis jūsu rokā Sihonu, Hešbonas ķēniņu, to Amorieti, un viņa zemi; sāc ieņemt un ej karā ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Šodien Es sākšu darīt, ka no tevis iztrūcināsies un bīsies tās tautas, kas apakš visas debess; kas tavu slavu dzirdēs, tiem būs trīcēt un drebēt tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Tad Es sūtīju vēstnešus no Ķedemot tuksneša pie Sihona, Hešbonas ķēniņa, ar miera vārdiem sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Ļauj man iet caur tavu zemi, es pa ceļu vien iešu, es neatkāpšos ne pa labo, ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Pārdod man par naudu barību, ko ēst, un dod man par naudu ūdeni, ko dzert; tikai kājām es iešu cauri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Kā man ir darījuši Ēsava bērni, kas Seīrā dzīvo, un Moabieši, kas Arā dzīvo, tiekams es nāku pāri pār Jardāni tai zemē, ko Tas Kungs, mūsu Dievs, mums dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Bet Sihons, Hešbonas ķēniņš, mums negribēja ļaut iet cauri, jo Tas Kungs, tavs Dievs, viņa prātu apcietināja un viņa sirdi drošināja, lai Viņš to nodotu tavā rokā, itin kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Un Tas Kungs sacīja uz mani: redzi, Es esmu iesācis tev nodot Sihonu un viņa zemi; sāc ieņemt viņa zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Un Sihons izgāja mums pretī, pats ar visiem saviem ļaudīm, karot pie Jācas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Bet Tas Kungs, mūsu Dievs, to mums nodeva, un mēs to sakāvām un viņa dēlus un visus viņa ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Un tanī laikā uzņēmām visas viņa pilsētas un izdeldējām visas pilsētas, vīrus un sievas un bērniņus, mēs neatlicinājām neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Tikai tos lopus mēs sev esam paņēmuši un to laupījumu tais pilsētās, ko uzņēmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'No Aroēra pie Arnonas upes krasta, un no tās pilsētas, kas pie upes, līdz Gileādai, nevienas pilsētas nebija, kas pret mums varēja turēties; visu to Tas Kungs, mūsu Dievs, mums nodeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Tikai uz Ammona bērnu zemi tu neesi gājis, uz visu to pusi gar Jabokas upi, nedz uz tām pilsētām kalnos, nedz kaut kur, kurp (iet) Tas Kungs, mūsu Dievs, bija aizliedzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Tad mēs griezāmies un gājām uz augšu pa Basanas ceļu, un Ogs, Basanas ķēniņš, mums gāja pretī, pats ar visiem saviem ļaudīm, karot pie Edrejas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Un Tas Kungs sacīja uz mani: nebīsties no viņa, jo Es viņu un visus viņa ļaudis un viņa zemi esmu devis tavā rokā, un tev būs viņam darīt, tā tu esi darījis Sihonam, Amoriešu ķēniņam, kas dzīvoja Hešbonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Un Tas Kungs, mūsu Dievs, deva mūsu rokā arī Ogu, Basanas ķēniņu, līdz ar visiem viņa ļaudīm, un mēs to sakāvām, kamēr viņam nekas neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Un mēs uzņēmām tanī laikā visas viņa pilsētas; nevienas pilsētas nebija, ko mēs viņam nebūtu atņēmuši; sešdesmit pilsētas, visu Argoba daļu, Oga valsti Basanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Visas tās pilsētas bija apstiprinātas ar augstiem mūriem, vārtiem un bultām; - bez tam vēl daudz miestus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Un mēs tos izdeldējām, itin kā bijām darījuši Sihonam, Hešbonas ķēniņam, izdeldēdami visas pilsētas, vīrus, sievas un bērniņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Bet visus lopus un to laupījumu tais pilsētās paņēmām sev.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Tā mēs tanī laikā paņēmām to zemi no to divu Amoriešu ķēniņu rokas, viņpus Jardānes, no Arnonas upes līdz Hermona kalnam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Sidonieši Hermonu sauc par Zirionu, bet Amorieši viņu sauc par Seniru) -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Visas pilsētas klajumā un visu Gileādu un visu Basanu līdz Zalkai un Edrejai, Oga valsts pilsētām Basanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '(Jo Ogs, Basanas ķēniņš, vien bija atlicies no tiem atlikušiem milžiem; redzi, viņa gulta, dzelzs gulta, vai tā nav Ammona bērnu Rabatā? Deviņu olekšu viņas garums un četru olekšu viņas platums, pēc vīra elkoņa.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Tad nu šo zemi tanī laikā ieņēmām no Aroēra, kas ir pie Arnonas upes. Un Gileādas kalnu un viņas pilsētu vienu pusi es atdevu Rūbena un Gada bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Un kas atlikās no Gileādas un visu Basanu, Oga valsti, es atdevu Manasus pusciltij, visu Argoba apgabalu; visu šo Basanu sauc par milžu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaīrs, Manasus dēls, dabūja visu Argoba apgabalu, līdz gešuriešu un Maāhatiešu robežām, un viņš Basanu nosauca pēc sava vārda Avot Jaīru līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Un Mahiram es devu Gileādu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Bet Rūbena un Gada bērniem es no Gileādas devu līdz Arnonas upei to upes ieleju un malu, un līdz Jabokas upei, Ammona bērnu robežai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Un to klajumu un to Jardāni, kas ir par robežu no Ķineretes līdz klajuma ezeram, tai sāls jūrai, apakš Pizgas pakalniem pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Un tanī laikā es jums pavēlēju un sacīju: Tas Kungs, jūsu Dievs, jums šo zemi ir devis iemantot, - bet visi, kas ir stipri vīri, ejat apbruņoti savu brāļu, Israēla bērnu, priekšā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Tikai jūsu sievas un jūsu bērniņi un jūsu ganāmais pulks (jo es zinu, ka jums tas ganāmais pulks ir liels), lai paliek jūsu pilsētās, ko es jums esmu devis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Tiekams Tas Kungs dos dusu jūsu brāļiem, itin kā jums, un tie arīdzan iemantos to zemi, ko Tas Kungs, jūsu Dievs, viņiem dos viņpus Jardānes; tad jums ikvienam būs griezties uz savu daļu, ko es jums esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Es Jozuam pavēlēju tanī laikā un sacīju: tavas acis ir redzējušas visu, ko Tas Kungs, jūsu Dievs, šiem diviem ķēniņiem ir darījis; tā Tas Kungs darīs visām valstīm, uz kurieni tu iesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Nebīstaties no viņiem, jo Tas Kungs jūsu Dievs, priekš jums karos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Un es lūdzu To Kungu tanī laikā un sacīju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Kungs, Dievs, Tu esi iesācis Savam kalpam parādīt Savu augstību un Savu stipro roku, jo kur ir tāds stiprs Dievs debesīs un virs zemes, kas varētu darīt pēc Taviem darbiem un pēc Tava spēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Ļauj lūdzams man iet pāri un redzēt to labo zemi, kas ir viņpus Jardānes, tos jaukos kalnus un to Lībanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Bet Tas Kungs jūsu dēļ iekarsa par mani un mani nepaklausīja, un Tas Kungs uz mani sacīja: lai tev ir gan, nerunā vairs uz Mani par šo lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Kāp Pizgas kalna galā un pacel savas acis pret vakariem un pret ziemeļiem un pret dienvidiem un pret rītiem, un pārlūko to ar savām acīm, jo tev nebūs iet pār šo Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Pavēli tad Jozuam un stiprini viņu un iedrošini viņu, jo viņš ies pāri šo ļaužu priekšā un izdalīs viņiem to zemi, ko tu redzēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Un mēs palikām tanī lejā pret Bet-Peoru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Nu tad, Israēl, klausi tos likumus un tās tiesas, ko es jums mācu darīt, lai jūs dzīvojat un ienākat un iemantojat to zemi, ko Tas Kungs, jūsu tēvu Dievs, jums dod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Pie tā vārda, ko es jums pavēlu, jums neko nebūs pielikt, nedz no tā ko atraut, ka jūs turat Tā Kunga, sava Dieva, baušļus, ko es jums pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Jūsu acis ir redzējušas, ko Tas Kungs Baāl-Peora dēļ darījis; jo ikvienu, kas Baāl-Peoram dzinās pakaļ, to Tas Kungs, jūsu Dievs, ir izdeldējis no jūsu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Bet jūs, kas esat pieķērušies Tam Kungam, savam Dievam, jūs šodien visi esat dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Redzi, es jums esmu mācījis tos likumus un tās tiesas, itin kā Tas Kungs, mans Dievs, man pavēlējis, lai jūs tā darāt tanī zemē, ko jūs ejat iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Turat nu tos un darāt tos, jo šī būs jūsu gudrība un jūsu saprašana to ļaužu acīs, kas visus šos likumus dzirdēs un sacīs: tiešām gudri un prātīgi ļaudis ir šī lielā tauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Jo kur ir cita tāda liela tauta, kam dievi tik tuvu, kā Tas Kungs, mūsu Dievs, mums, cikkārt viņu piesaucam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Un kur ir cita tāda liela tauta, kam tādi taisni likumi un tiesas, kā visa šī bauslība, ko es šodien lieku jūsu priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Bet sargies un sargi ļoti savu dvēseli, ka tu neaizmirsti to, ko tavas acis redzējušas, ka tas neizzūd no tavas sirds visās tava mūža dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Un dari to zināmu saviem bērniem un saviem bērnu bērniem. Tai dienā, kad tu stāvēji priekš Tā Kunga, sava Dieva, Horebā, kad Tas Kungs uz mani sacīja: sapulcini Man tos ļaudis, un Es tiem došu dzirdēt Savus vārdus, lai tie mācās Mani bīties visas dienas, cik ilgi tie virs zemes dzīvo, un lai tie tos māca saviem bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Tad jūs piegājāt un stāvējāt apakšā pie tā kalna, un tas kalns dega ugunī līdz debess vidum; tur bija tumsa, mākonis un krēsla;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Un Tas Kungs runāja uz jums no uguns vidus; jūs dzirdējāt to vārdu balsi, bet jūs neredzējāt nekādu ģīmi, balss vien bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Tad Viņš jums pasludināja Savu derību, ko Viņš jums pavēlēja darīt, (proti) tos desmit vārdus, un tos rakstīja uz diviem akmens galdiņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Un Tas Kungs tanī laikā man pavēlēja, lai es jums mācu likumus un tiesas, ko lai jūs dariet tai zemē, ko jūs ejat iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Tad nu sargājaties ļoti savu dvēseļu labad; jo jūs nekādu ģīmi neesat redzējuši tai dienā, kad Tas Kungs Horebā uz jums runāja no uguns vidus, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Ka jūs neapgrēkojaties un sev nedarāt nekādu elka bildi, nekāda tēla līdzību, nedz vīra nedz sievas ģīmi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Nekāda lopa ģīmi, kas virs zemes, nekāda spārnaina putna ģīmi, kas apakš debess skraida,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Nekāda tārpa ģīmi, kas virs zemes lien, nekādas zivs ģīmi, kas ūdenī apakš zemes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Un ka tu savas acis nepacel uz debesīm, uzlūkodams sauli un mēnesi un zvaigznes, visu debespulku, un neliecies kārdināties, viņu priekšā zemē mesties un tiem kalpot; tos Tas Kungs, tavs Dievs, ir piešķīris visiem ļaudīm apakš visas debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Bet jūs Tas Kungs ir pieņēmis un jūs izvedis no tā dzelzs cepļa, no Ēģiptes, lai jūs esat Viņa īpaša tauta, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Un Tas Kungs par mani dusmojās jūsu dēļ un zvērēja, ka man nebūs iet pār Jārdani un ka man nebūs nākt uz to labo zemi, ko Tas Kungs, tavs Dievs, tev dod par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Jo man jāmirst šinī zemē un es neiešu pār Jardāni, bet jūs iesiet un iemantosiet šo labo zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Tad sargājaties nu, ka jūs neaizmirstat Tā Kunga, sava Dieva, derību, ko Viņš ar jums derējis, ka jūs sev nedarāt nekādu elka bildi, nekādu tēlu, ko Tas Kungs, tavs Dievs, ir aizliedzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Jo Tas Kungs, tavs Dievs, ir rijoša uguns, stiprs Dievs, dusmotājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Kad nu jūs dzemdināsiet bērnus un bērnu bērnus un tapsiet veci tai zemē un apgrēkosities, darīdami kādu elka bildi, jeb kādas lietas tēlu, un grēkosiet priekš Tā Kunga, sava Dieva vaiga, Viņu apkaitinādami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Tad pār jums šodien piesaucu debesis un zemi par lieciniekiem, ka jūs bojā iesiet piepeši no tās zemes virsas, uz kurieni jūs ejat pār Jardāni to iemantot; jūs tur ilgi nepaliksiet, bet ar izdeldēšanu tapsiet izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Un Tas Kungs jūs izkaisīs starp tautām un no jums atliksies mazs pulciņš starp pagāniem, kurp Tas Kungs jūs aizdzīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Un tur jūs kalposiet dieviem, kas ir cilvēku rokas darbs, koks un akmens, kas ne redz, ne dzird, ne ēd, ne ož.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Tad tur jūs meklēsiet To Kungu, savu Dievu, un Viņu atradīsiet, kad meklēsi no visas savas sirds un no visas savas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Kad būsi bēdās un visas šīs lietas tev notiks nākamās dienās, tad tu atgriezīsies pie Tā Kunga, sava Dieva, un klausīsi Viņa balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Jo sirds žēlīgs Dievs ir Tas Kungs, tavs Dievs; Viņš tevi neatstās, nedz tevi izdeldēs, nedz aizmirsīs tavu tēvu derību, ko Viņš tiem ir zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Jo vaicā jel pēc tiem pagājušiem laikiem, kas priekš tevis bijuši no tās dienas, kad Dievs cilvēku virs zemes radījis, no viena debess gala līdz otram, vai tāda lieta ir notikusi, kā šī, vai dzirdēta, kā šī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Vai kādi ļaudis dzirdējuši Dieva balsi runājam no uguns vidus, kā tu esi dzirdējis, un palikuši dzīvi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Jeb vai Dievs ir apņēmies iet un Sev vienu tautu ņemt no tautu vidus caur pārbaudīšanām, caur zīmēm un caur brīnumiem un caur karu un caur stipru roku un caur izstieptu elkoni un caur lielām iztrūcināšanām, kā visu to Tas Kungs, jūsu Dievs, jums darījis priekš jūsu acīm Ēģiptes zemē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tev tas ir rādīts, lai tu zini, ka Tas Kungs ir Dievs, cits neviens, kā tik Viņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'No debesīm Viņš tev licis dzirdēt Savu balsi, tevi pamācīdams, un virs zemes Viņš tev rādījis Savu lielo uguni, un tu Viņa vārdus esi dzirdējis no uguns vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Un tāpēc, ka Viņš tavus tēvus bija mīlējis un izredzējis viņu dzimumu pēc viņiem, tad Viņš tevi izvedis ar Savu vaigu no Ēģiptes zemes caur Savu lielo spēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Gribēdams izdzīt tavā priekšā lielas tautas, kas jo stiprākas nekā tu, un tevi ievest viņu zemē, un tev to dot par daļu, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Tā tev šodien būs zināt, un savā sirdī pieminēt, ka Tas Kungs ir Dievs augšā debesīs un apakšā virs zemes, un cits neviens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Un tev būs turēt Viņa likumus un Viņa baušļus, ko es tev šodien pavēlu, lai labi klājās tev un taviem bērniem pēc tevis, un lai tavas dienas top pagarinātas tai zemē, ko Tas Kungs, tavs Dievs, tev dod mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tad Mozus atšķīra trīs pilsētas viņpus Jardānes pret saules uzlēkšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Ka uz turieni bēgtu tas nokāvējs, kas savu tuvāko netīši nositis, ar ko viņš agrāk nebija ienaidā, ka tas nobēgtu uz vienu no šīm pilsētām un paliktu dzīvs, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Beceru tuksnesī, klajā zemē, priekš Rūbeniešiem, un Rāmotu Gileādā priekš Gadiešiem, un Golanu Basanā priekš Manasiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Šī nu ir tā bauslība, ko Mozus lika priekšā Israēla bērniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Šīs tās liecības un tie likumi un tās tiesas, ko Mozus uz Israēla bērniem runāja, kad tie bija izgājuši no Ēģiptes zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Viņpus Jardānes, tai ielejā Bet-Peoram pretī, Sihona, Amoriešu ķēniņa zemē, kas Hešbonā dzīvoja, ko Mozus un Israēla bērni sakāva, kad tie bija izgājuši no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Un tie viņa zemi bija iemantojuši, arī Oga, Basanas ķēniņa, zemi, to divu Amoriešu ķēniņu zemi, kas viņpus Jardānes pret saules lēkšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'No Aroēra, kas pie Arnonas upes krasta, līdz Sihona kalnam, tas ir Hermons,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'Un visu klajumu viņpus Jardānes pret rītiem līdz klajuma ezeram apakš Pizgas pakalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Un Mozus saaicināja visu Israēli un sacīja uz tiem: klausies, Israēl, tos likumus un tās tiesas, ko es šodien priekš jūsu ausīm runāju, ka jūs tos mācaties un vērā ņemat, tos darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Tas Kungs, mūsu Dievs, ar mums derību derējis Horebā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ar mūsu tēviem Tas Kungs šo derību nav derējis, bet ar mums, ar mums, kas šeit visi šodien esam dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Vaigu vaigā Tas Kungs ar jums ir runājis tai kalnā no uguns vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Es tanī laikā stāvēju starp To Kungu un jums, jums darīt zināmu Tā Kunga vārdu; jo jūs bijāties no tā uguns un nekāpāt uz to kalnu. Un Viņš sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Es esmu Tas Kungs, tavs Dievs, kas tevi izvedis no Ēģiptes zemes, no tā vergu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Tev nebūs citus dievus turēt priekš Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Tev nebūs sev darīt nekādu tēlu nedz līdzību ne no tā, kas augšā debesīs, ne no tā, kas apakšā virs zemes, ne no tā, kas ūdenī apakš zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Tev nebūs priekš tiem zemē mesties nedz tiem kalpot; jo Es Tas Kungs, tavs Dievs, esmu stiprs un dusmīgs Dievs, kas piemeklē tēvu grēkus pie bērniem trešā un ceturtā augumā pie tiem, kas Mani ienīst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Un dara žēlastību pie tūkstošiem, kas Mani mīļo un Manus baušļus tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Tev nebūs Tā Kunga, sava Dieva, vārdu nelietīgi velti valkāt, jo Dievs to nepametīs nesodītu, kas Viņa vārdu nelietīgi velti valkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Turi to dusēšanas dienu, ka tu to svētī, itin kā tev Tas Kungs, tavs Dievs ir pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sešas dienas tev būs strādāt un visu savu darbu darīt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Bet tā septītā diena ir Tā Kunga, tava Dieva, dusēšanas diena; tad tev nebūs nekādu darbu darīt, ne tev, ne tavam dēlam, ne tavai meitai, ne tavam kalpam, ne tavai kalponei, ne tavam vērsim, ne tavam ēzelim, nedz kādam no taviem lopiem, nedz tavam svešiniekam, kas ir tavos vārtos, lai tavs kalps un tava kalpone var dusēt tā kā tu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Jo tev būs pieminēt, ka tu esi bijis kalps Ēģiptes zemē, un ka Tas Kungs, tavs Dievs, tevi no turienes ir izvedis caur stipru roku un izstieptu elkoni, tāpēc Tas Kungs, tavs Dievs, tev ir pavēlējis, turēt to dusēšanas dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Tev būs savu tēvu un savu māti godāt, itin kā Tas Kungs, tavs Dievs tev ir pavēlējis, lai tu ilgi dzīvo un tev labi klājās tai zemē, ko Tas Kungs, tavs Dievs, tev dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Tev nebūs nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Un tev nebūs laulību pārkāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Un tev nebūs zagt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Un tev nebūs nepatiesu liecību dot pret savu tuvāko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Un tev nebūs iekārot sava tuvākā sievu. Un tev nebūs iekārot sava tuvākā namu, nedz viņa tīrumu, nedz viņa kalpu, nedz viņa kalponi, nedz viņa vērsi, nedz viņa ēzeli, nedz kaut ko, kas tavam tuvākam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Šos vārdus Tas Kungs runāja uz visu jūsu draudzi kalnā no uguns, mākoņa un tumsas ar lielu balsi, un nekā nepielika klāt, un Viņš tos rakstīja uz diviem akmens galdiņiem un tos man iedeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Un kad jūs dzirdējāt to balsi no tās tumsas, un tas kalns ar uguni dega, tad jūs pie manis nācāt, visi jūsu cilšu virsnieki un jūsu vecaji, un sacījāt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Redzi, Tas Kungs, mūsu Dievs, mums ir rādījis Savu godību un Savu augstību, un mēs esam dzirdējuši Viņa balsi no uguns. Šodien mēs esam redzējuši Dievu ar cilvēkiem runājam, un ka tie paliek dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Bet nu, kāpēc mums būs mirt? Jo šis lielais uguns mūs norīs; ja mēs Tā Kunga, sava Dieva, balsi vēl joprojām dzirdēsim, tad mums jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Jo kas ir visa miesa, ka varētu dzirdēt tā dzīvā Dieva balsi no uguns runājam, tā kā mēs, un paliktu dzīva?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Pieej tu un klausies visu, ko Tas Kungs, mūsu Dievs, runās, un runā tu uz mums visu, ko Tas Kungs, mūsu Dievs, uz tevi runās; tad mēs klausīsim un to darīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Kad nu Tas Kungs dzirdēja jūsu vārdu balsi, ko jūs uz mani runājāt, tad Tas Kungs sacīja uz mani: Es esmu dzirdējis šo ļaužu vārdu balsi, ko tie uz tevi runājuši; tie ir labi darījuši ar visu, ko tie runājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ak kaut viņiem būtu tāda sirds, Mani bīties un visus Manus baušļus turēt mūžīgi, ka viņiem labi klātos un viņu bērniem mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Ej, saki tiem: griežaties atpakaļ uz savām teltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Bet tu stāvi šeit pie Manis, lai Es uz tevi runāju visus tos baušļus un likumus un visas tās tiesas, ko tev viņiem būs mācīt, ka tie tā dara tai zemē, ko Es tiem dodu iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Ņemiet tad vērā, ka jūs darāt, itin kā Tas Kungs, jūsu Dievs, jums ir pavēlējis, un neatkāpjaties ne pa labo, ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Bet pa ikkatru ceļu, ko Tas Kungs, jūsu Dievs, jums pavēl, jums būs staigāt, lai jūs dzīvojat un jums labi klājās un ilgi dzīvojat tai zemē, ko jūs iemantosiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Un šie ir tie baušļi, tie likumi un tās tiesas, ko Tas Kungs, jūsu Dievs, ir pavēlējis jums mācīt, ka jūs pēc tiem darāt tai zemē, ko jūs ejat iemantot:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Ka tu To Kungu, savu Dievu, bīsties un turi visus Viņa likumus un Viņa baušļus, ko es tev pavēlu, tu un tavi bērni un tavi bērnu bērni, visas tava mūža dienas, un ka tu ilgi dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Klausies tad, Israēl, un ņem vērā, ka tu tos dari, lai tev labi klājās, un lai jūs ļoti vairojaties, kā Tas Kungs, tavu tēvu Dievs, tev ir runājis, tai zemē, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Klausies, Israēl, Tas Kungs, mūsu Dievs, ir viens vienīgs Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Un tev To Kungu, savu Dievu, būs mīlēt no visas savas sirds, no visas savas dvēseles un no visa sava spēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Un šie vārdi, ko es tev šodien pavēlu, lai tev iet pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Un tev tos būs piekodināt saviem bērniem un no tiem runāt savā namā sēžot un pa ceļu ejot, guļoties un ceļoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Un tev tos būs siet par zīmi uz savu roku, un tiem būs būt par piemiņas zīmi starp tavām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Un tev tos būs rakstīt uz sava nama stenderes un uz saviem vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Kad nu Tas Kungs, tavs Dievs, tevi ievedīs tai zemē, ko Viņš zvērējis taviem tēviem Ābrahāmam, Īzakam un Jēkabam, tev dot, lielas un labas pilsētas, ko tu neesi uzcēlis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Un namus visa labuma pilnus, ko tu neesi pildījis, un izcirstas akas, ko tu neesi izcirtis, vīna dārzus un eļļas koku dārzus, ko tu neesi dēstījis, ka tu ēdīsi un būsi paēdis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Tad sargies, ka tu neaizmirsti To Kungu, kas tevi izvedis no Ēģiptes zemes, no tā vergu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Tev būs bīties To Kungu, savu Dievu, un Viņam kalpot un pie Viņa vārda zvērēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Jums nebūs dzīties pakaļ citiem dieviem, kas ir no apkārtēju tautu dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Jo Tas Kungs, tavs Dievs, tavā vidū ir stiprs un dusmīgs Dievs; ka Tā Kunga, tava Dieva, bardzība pret tevi neiedegās un tevi neizdeldē no zemes virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Jums To Kungu, savu Dievu, nebūs kārdināt, kā jūs Viņu kārdinājāt Masā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Turēdami turat Tā Kunga, sava Dieva, baušļus līdz ar Viņa liecībām un ar Viņa likumiem, ko Viņš tev pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Un dari, kas tiesa un labi priekš Tā Kunga acīm, lai tev labi klājās un tu ej un iemanto to labo zemi, ko Tas Kungs taviem tēviem zvērējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Kad Viņš izdzīs visus tavus ienaidniekus tavā priekšā, itin kā Tas Kungs ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Kad nākamās dienās tavs dēls jautās un sacīs: kuras ir tās liecības un tie likumi un tās tiesas, ko Tas Kungs, mūsu Dievs, jums ir pavēlējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Tad tev būs atbildēt savam dēlam: mēs bijām Faraona kalpi Ēģiptes zemē, bet Tas Kungs mūs caur stipru roku no Ēģiptes zemes izvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Un Tas Kungs deva zīmes un lielus un briesmīgus brīnumus Ēģiptes zemē pie Faraona un pie visa viņa nama priekš mūsu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Un Viņš mūs izveda no turienes, ka Viņš mūs atvestu un mums dotu to zemi, ko Viņš mūsu tēviem bija zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Un Tas Kungs mums pavēlēja visus šos likumus darīt, To Kungu, savu Dievu, bīties, mums par labu mūžam, ka mēs dzīvi taptu paturēti, it tā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Un tā būs mūsu taisnība, kad mēs sargāsim un darīsim visus šos baušļus Tā Kunga, sava Dieva, priekšā, kā Viņš mums ir pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Kad Tas Kungs, tavs Dievs, tevi ievedīs tai zemē, ko tu ej iemantot, un izmetīs daudz tautas tavā priekšā, Hetiešus un Ģirgaziešus un Amoriešus un Kanaāniešus un Fereziešus un Hiviešus un Jebusiešus, septiņas tautas, kas lielākas un stiprākas nekā tu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Un kad Tas Kungs, tavs Dievs, tos nodos tavā priekšā, ka tu tos sakauj, tad tev tos pavisam būs izdeldēt; tev nebūs ar tiem nekādu derību derēt, nedz viņus žēlot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Un tev nebūs ar viņiem apdraudzēties; savas meitas tev nebūs dot viņu dēliem, un viņu meitas tev nebūs ņemt saviem dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Jo tās novērsīs tavus dēlus, ka tie nestaigā Man pakaļ, bet ka tie citiem dieviem kalpo, un Tā Kunga bardzība pret jums iedegsies, un jūs izdeldēs piepeši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Bet tā jums būs viņiem darīt: viņu altārus jums būs izpostīt un viņu stabus salauzīt, un viņu Ašeras jums būs nocirst un viņu elku tēlus ar uguni sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Jo tu esi svēta tauta Tam Kungam, savam Dievam; tevi Tas Kungs, tavs Dievs, ir izredzējis, ka tu Viņam piederi no visām tautām, kas virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Tam Kungam nav tāpēc labs prāts pie jums bijis, Viņš arī jūs nav tāpēc izredzējis, ka jūsu pulks būtu bijis jo liels pār visām tautām, jo jūs bijāt tā vismazākā no visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Bet tāpēc, ka Tas Kungs jūs mīlējis un jums tur to zvērējumu, ko Viņš jūsu tēviem zvērējis, tāpēc Tas Kungs jūs ir izvedis ar stipru roku un tevi izglābis no tā vergu nama, no Faraona, Ēģiptes ķēniņa, rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Tad nu tev būs zināt, ka Tas Kungs, tavs Dievs, ir Dievs, tas uzticīgais Dievs, kas derību un žēlastību tur līdz tūkstošam augumam tiem, kas Viņu mīl un Viņa baušļus tur,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Un atmaksā tiem, kas Viņu ienīst, taisni acīs, viņus izdeldēdams; Viņš nekavēsies tam, kas Viņu ienīst, atmaksāt viņam taisni acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Turi tad tos baušļus un tos likumus un tās tiesas, ko es tev šodien pavēlu, ka tu tos dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Un kad jūs šīs tiesas klausīsiet un turēsiet un darīsiet, tad Tas Kungs, tavs Dievs, tev turēs to derību un to žēlastību, ko Viņš taviem tēviem zvērējis, un Viņš tevi mīļos un tevi svētīs un tevi vairos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Un Viņš svētīs tavas miesas augli un tavas zemes augli, tavu labību un tavu vīnu un tavu eļļu, tavu lielo lopu augumu un tavu sīko lopu vaislu tai zemē, ko Viņš taviem tēviem zvērējis, tev dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Svētīts tu būsi pār visām tautām; neauglīgu nebūs ne tavā starpā, ne tavu lopu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Un Tas Kungs no tevis atņems visu neveselību un jums neuzliks nevienu no tām niknām Ēģiptes sērgām, ko tu pazīsti, bet Viņš tās uzliks visiem, kas tevi ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Un tu aprīsi visas tās tautas, ko Tas Kungs, tavs Dievs, tev nodos; tava acs lai viņas nežēlo; tev arī viņu dieviem nebūs kalpot, jo tas tev būtu par slazda valgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Ja tu savā sirdī sacītu: šās tautas ir lielākas nekā es esmu, kā es tās varētu izdzīt? -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Nebīsties no tiem, piemini, ko Tas Kungs, tavs Dievs ir darījis pie Faraona un pie visiem ēģiptiešiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Tās lielās pārbaudīšanas, ko tavas acis redzējušas, un tās zīmes un tos brīnumus un to stipro roku un izstiepto elkoni, caur ko Tas Kungs, tavs Dievs, tevi izvedis; tā Tas Kungs, tavs Dievs, darīs visām tautām, no kurām tu bīsties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Tas Kungs, tavs Dievs, sūtīs viņu starpā arī dundurus, tiekams tie būs izdeldēti, kas atlikuši un tavā priekšā paslēpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Nebaiļojaties priekš viņiem, jo Tas Kungs, tavs Dievs, ir tavā vidū, tas stiprais Dievs, liels un bijājams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Un Tas Kungs, tavs Dievs, pamazām izmetīs šīs tautas tavā priekšā, piepeši tu tās nevari apkaut, ka zvēri laukā pret tevi nevairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Un Tas Kungs tos nodos tavā priekšā un tos satrieks ar lielu satriekšanu, tiekams tie top izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Un Viņš viņu ķēniņus arī nodos tavā rokā, lai tu viņu vārdus iznīcini apakš debess; nevienam tavā priekšā nebūs pastāvēt, tiekams tu tos nebūsi izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Viņu elku tēlus tev būs sadedzināt ar uguni, to sudrabu un zeltu, kas viņiem klāt tev nebūs iekārot nedz sev paņemt, ka tu caur to netopi savaldzināts; jo tā ir negantība Tam Kungam, tavam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Tev nebūs negantību ienest savā namā, ka tu netopi izdeldēts tā kā viņi, lai tie tev riebj un turi tos visai par negantiem, jo tie ir izdeldējami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Visus tos baušļus, ko es tev šodien pavēlu, tev būs turēt un tos darīt, lai jūs dzīvojat un topat vairoti un nākat un iemantojat to zemi, ko Tas Kungs jūsu tēviem zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Un tev būs pieminēt visu to ceļu, pa kuru Tas Kungs, tavs Dievs, tevi tuksnesī vadījis šos četrdesmit gadus, ka Viņš tevi pazemotu un pārbaudītu, ka Viņš zinātu, kas ir tavā sirdī, vai tu Viņa baušļus turēsi, vai ne.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Un Viņš tevi pazemoja un tev lika izsalkt un tevi ēdināja ar mannu, ko ne tu pazini, ne tavi tēvi nebija pazinuši, lai Viņš tev dotu atzīt, ka cilvēks nedzīvo no maizes vien, bet ka cilvēks dzīvo no visa, kas iziet no Tā Kunga mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Tavas drēbes tavā mugurā nav nodilušas, un tava kāja nav uztūkusi šinīs četrdesmit gados.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Tad nu atzīsti savā sirdī, ka Tas Kungs, tavs Dievs, tevi pārmāca, itin kā kāds savu dēlu pārmāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Un turi Tā Kunga, sava Dieva, baušļus, staigādams pa Viņa ceļiem un bīsties Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Jo Tas Kungs, tavs Dievs, tevi, ved uz labu zemi, uz zemi, kur ir upes, avoti un ūdeņi, kas rodas ielejās un kalnos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Uz zemi, kur ir kvieši un mieži un vīna koki un vīģes koki un granātu koki, uz zemi, kur ir eļļas koki un medus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Uz zemi, kur maizi ēdīsi bez trūkuma, kur tev nekā netrūks, uz zemi, kur akmeņi ir dzelzs, no kuras kalniem tu izcirtīsi varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Kad tu nu ēdīsi un būsi paēdis, tad tev būs teikt To Kungu, savu Dievu, par to labo zemi, ko Viņš tev devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Sargies, ka tu neaizmirsti To Kungu, savu Dievu, bet turi Viņa baušļus un Viņa tiesas un Viņa likumus, ko es tev šodien pavēlu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Ka tu, kad būsi ēdis un paēdis un labus namus uztaisījis un iekš tiem dzīvosi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Kad tavi vērši un sīkie lopi būs vairojušies un tavs sudrabs un zelts vairojies un viss, kas tev pieder, būs vairojies -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Ka tava sirds tad nelepojās, un tu neaizmirsti To Kungu, savu Dievu, kas tevi izvedis no Ēģiptes zemes, no tā vergu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Kas tevi vadījis tai lielā un briesmīgā tuksnesī, kur bija dedzīgas čūskas un skorpioni un izkaltušas vietas bez ūdens, kas tev lika izvirst ūdenim no cietas klints,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Kas tuksnesī tevi ēdināja ar mannu, ko tavi tēvi nebija pazinuši, ka Viņš tevi pazemotu un pārbaudītu, un pēcgalā tev darītu labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Tad nesaki savā sirdī: mans spēks un manas rokas stiprums man ir devis šo mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Bet piemini To Kungu savu Dievu, ka Viņš ir Tas, kas tev dod spēku, mantu dabūt, gribēdams Savu derību apstiprināt, ko Viņš zvērējis taviem tēviem, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Bet ja tu aizmirsīsi To Kungu, savu Dievu, un dzīsies pakaļ citiem dieviem, un tiem kalposi un priekš tiem metīsies zemē, tad es šodien pret jums apliecināju, ka jūs nīcin iznīksiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Kā tās tautas, ko Tas Kungs jūsu priekšā iznīcina, tāpat jūs iznīksiet, tāpēc ka jūs neesat klausījuši Tā Kunga, sava Dieva, balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Klausies, Israēl, tu šodien iesi pār Jardāni, uzvarēt tautas, lielākas un stiprākas, nekā tu esi, lielas un līdz debesīm apstiprinātas pilsētas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Lielus un garus ļaudis, Enaka bērnus, par kuriem tu zini un esi dzirdējis: kas var pastāvēt Enaka bērnu priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Tad tev šodien būs atzīt, ka Tas Kungs, tavs Dievs, pats iet tavā priekšā, rijoša uguns, - Viņš pats tos izdeldēs un tos nometīs tavā priekšā, un tu tos izdzīsi un tos steigšus iznīcināsi, itin kā Tas Kungs uz tevi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Kad nu Tas Kungs, tavs Dievs, tos tavā priekšā izdzīs, tad nerunā savā sirdī un nesaki: Tas Kungs manas taisnības dēļ mani ievedis, šo zemi iemantot; jo šo tautu bezdievības dēļ Tas Kungs tos izdzen tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ne tavas taisnības dēļ, nedz tavas sirds skaidrības dēļ tu nenāc iemantot viņu zemi, bet šo tautu bezdievības dēļ Tas Kungs, tavs Dievs, tos izdzen tavā priekšā un gribēdams apstiprināt to vārdu, ko Tas Kungs zvērējis taviem tēviem Ābrahāmam, Īzakam un Jēkabam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Tad nu zini, ka Tas Kungs, tavs Dievs, tev nedod iemantot šo labo zemi tavas taisnības dēļ, jo tu esi stūrgalvīga tauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Piemini un neaizmirsti, ka tu To Kungu, savu Dievu, ļoti esi apkaitinājis tuksnesī; no tās dienas, kad tu izgāji no Ēģiptes zemes. kamēr jūs esat nonākuši šai vietā, jūs esat pretī turējušies Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Jo Horebā jūs To Kungu ļoti apkaitinājāt un Tas Kungs par jums apskaitās un gribēja jūs izdeldēt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Kad es uzkāpu kalnā, saņemt tos akmens galdiņus, tās derības galdiņus, ko Tas Kungs ar jums bija derējis. Un es paliku četrdesmit dienas un četrdesmit naktis uz tā kalna un neēdu maizi un nedzēru ūdeni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Un Tas Kungs man deva tos abus akmens galdiņus, Dieva pirksta aprakstītus, un uz tiem bija visi vārdi, ko Tas Kungs kalnā ar jums bija runājis no uguns vidus sapulces dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Un pēc tām četrdesmit dienām un četrdesmit naktīm Tas Kungs man deva tos abus akmens galdiņus, tos derības galdiņus, un Tas Kungs sacīja uz mani:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Celies, ej steigšus lejā, jo tavi ļaudis, ko tu izvedis no Ēģiptes zemes, ir apgrēkojušies, tie ir steigšus atkāpušies no tā ceļa, ko Es tiem pavēlējis, - tie sev lējuši tēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Un Tas Kungs runāja uz mani sacīdams: Es redzu šos ļaudis, un raugi, tie ir stūrgalvīgi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laid mani, Es tos iznīcināšu un izdeldēšu viņu vārdu no pasaules un tevi darīšu par stiprāku un lielāku tautu, nekā tie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Tad es atgriezies nogāju no tā kalna, un tas kalns dega ar uguni, un tie divi derības galdiņi bija manās abās rokās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Un es skatījos, un redzi, jūs bijāt apgrēkojušies pret To Kungu, savu Dievu, jūs bijāt sev lējuši teļu, jūs bijāt steigšus atkāpušies no tā ceļa, ko Tas Kungs jums bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Tad es sagrābu tos abus galdiņus un tos izmetu no savām abām rokām un tos sasitu priekš jūsu acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Un nometos priekš Tā Kunga tā kā papriekš, četrdesmit dienas un četrdesmit naktis, es maizi neēdu un ūdeni nedzēru, visu jūsu grēku dēļ, ar ko jūs bijāt apgrēkojušies, ļaunu darīdami Tā Kunga acīs, viņu apkaitinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Jo es bijājos par to bardzību un dusmību, ar ko Tas Kungs par jums bija apskaities, jūs izdeldēt; bet Tas Kungs arī to brīdi mani paklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Un Tas Kungs ļoti dusmojās arī par Āronu un gribēja viņu izdeldēt, bet es to brīdi lūdzu arī par Āronu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Bet jūsu grēku, to teļu, ko jūs bijāt taisījuši, to es ņēmu un sadedzināju ar uguni un sagrūdu un samalu, kamēr tas smalks palika par pīšļiem, un viņa pīšļus es iemetu tai upē, kas tek no tā kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Jūs To Kungu apkaitinājāt arī Tabeērā un Masā un pie tiem kārības kapiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Un kad Tas Kungs jūs izsūtīja no Kādeš Barneas sacīdams: ejat uz augšu un uzņemiet to zemi, ko Es jums esmu devis, tad jūs Tā Kunga, sava Dieva, vārdam turējaties pretī un neticējāt, nedz klausījāt Viņa balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Pārgalvīgi jūs esat bijuši pret To Kungu, kamēr es jūs pazīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Un es nometos Tā Kunga priekšā četrdesmit dienas un četrdesmit naktis, kur biju nometies, tāpēc ka Tas Kungs bija sacījis, ka gribot jūs izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Bet es pielūdzu To Kungu un sacīju: Kungs, Dievs, neizdeldē Savus ļaudis un Savu īpašumu, ko Tu esi atpestījis caur Savu lielo spēku, ko Tu ar stipru roku esi izvedis no Ēģiptes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Piemini Savus kalpus, Ābrahāmu, Īzaku un Jēkabu, neuzlūko šo ļaužu pārgalvību, nedz viņu bezdievību, nedz viņu grēkus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Lai tā zeme, no kurienes tu mūs esi izvedis, nesaka: Tas Kungs tos nevarēja ievest tai zemē, par ko Viņš tiem bija runājis, un tādēļ ka Viņš tos ienīdēja, Viņš tos izvedis, lai tos nonāvētu tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Tie jau ir Tavi ļaudis un Tavs īpašums, ko Tu esi izvedis caur Savu lielo spēku un caur Savu izstiepto elkoni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Tanī laikā Tas Kungs sacīja uz mani: izcērt sev divus akmens galdiņus, kā tos pirmos, un uzkāp pie Manis kalnā; pēc tam taisi koka šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Un Es uzrakstīšu uz tiem galdiņiem tos vārdus, kas bija uz tiem pirmiem galdiņiem, ko tu esi sasitis; tad liec tos tai šķirstā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Tad es taisīju šķirstu no akācijas koka un izcirtu divus akmens galdiņus tā kā tos pirmos, un uzkāpu uz to kalnu, un tie divi galdiņi bija manā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Tad Viņš uz tiem galdiņiem uzrakstīja to pirmo rakstu, tos desmit vārdus, ko Tas Kungs kalnā uz jums bija runājis no uguns vidus sapulces dienā, un Tas Kungs man tos iedeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Un es atgriezdamies nokāpu no tā kalna un liku tos galdiņus tai šķirstā, ko es biju taisījis, un tie tur ir, kā Tas Kungs man bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Un Israēla bērni aizgāja no Berot Bnejakana līdz Mozeram; tur Ārons nomira un tapa tur aprakts, un viņa dēls Eleazars palika par priesteri viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Un no turienes tie aizgāja līdz Gudgodam un no Gudgoda līdz Jatbatai; tā ir upēm bagāta zeme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Tanī laikā Tas Kungs atšķīra Levja cilti, nest Tā Kunga derības šķirstu un stāvēt Tā Kunga priekšā, Viņam kalpot un svētīt Viņa vārdā līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Tādēļ Levja ciltij nav nekādas daļas nedz mantības ar saviem brāļiem; Tas Kungs ir viņa mantība, kā Tas Kungs tavs Dievs, uz viņu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Un es stāvēju kalnā tā kā papriekš četrdesmit dienas un četrdesmit naktis, un Tas Kungs mani paklausīja arī to brīdi; Tas Kungs negribēja tevi izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Bet Tas Kungs uz mani sacīja: celies, ej, dodies ceļā ļaužu priekšā, ka tie nāk un uzņem to zemi, ko Es viņu tēviem esmu zvērējis, viņiem dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nu tad, Israēl, ko Tas Kungs tavs Dievs, no tevis prasa, kā vien bīties To Kungu, savu Dievu, staigāt visos Viņa ceļos un Viņu mīlēt un Tam Kungam, savam Dievam, kalpot no visas savas sirds un no visas savas dvēseles,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Turēt Tā Kunga baušļus un likumus, ko es tev šodien pavēlu, tev par labu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Redzi, Tam Kungam, tavam Dievam, pieder debesis un debesu debesis, zeme un viss, kas iekš tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Tomēr pie taviem tēviem vien Tam Kungam bijis labs prāts, viņus mīlēt, un Viņš ir izredzējis viņu dzimumu pēc viņiem, jūs pašus, no visiem ļaudīm, tā kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Apgraiziet tad savas sirds priekšādu un neesat vairs pārgalvīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Jo Tas Kungs, jūsu Dievs, ir tas dievu Dievs un tas kungu Kungs, stiprs Dievs, liels, varens un bīstams, kas vaigu neuzlūko un dāvanas neņem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Un tiesu nes bāriņiem un atraitnēm, un mīļo svešinieku un dod viņam maizi un drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Tāpēc mīļojiet to svešinieku, jo jūs esat bijuši svešinieki Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'To Kungu, savu Dievu, tev būs bīties, Viņam kalpot un Viņam pieķerties un pie Viņa vārda zvērēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Viņš ir tava slava un Viņš ir tavs Dievs, kas pie tevis darījis šīs lielās un briesmīgās lietas, ko tavas acis redzējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Tavi tēvi nogāja uz Ēģiptes zemi, septiņdesmit dvēseles, un nu Tas Kungs, tavs Dievs, vairojis tavu pulku, kā debess zvaigznes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Tad nu tev būs mīlēt To Kungu, savu Dievu, un turēt Viņa baušļus un Viņa likumus un Viņa tiesas un Viņa pavēles visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Un jums būs šodien zināt, ka es nerunāju ar jūsu bērniem, kas to nezin un kas nav redzējuši Tā Kunga, jūsu Dieva, pārmācīšanu, Viņa lielo spēku, Viņa stipro roku un Viņa izstiepto elkoni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Un Viņa zīmes un Viņa darbus, ko Viņš darījis Ēģiptē pie Faraona, Ēģiptes ķēniņa, un pie visas viņa zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Un ko Viņš darījis pie Ēģiptes kara spēka, pie viņa zirgiem un pie viņa ratiem, ka Viņš ūdenim Niedras jūrā lika pār tiem gāzties, kad tie jums dzinās pakaļ, un Tas Kungs tos izdeldēja līdz šai dienai;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Un ko Viņš jums darījis tuksnesī, tiekams jūs esat nākuši šai vietā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Un ko Viņš darījis Datanam un Abiramam, Eliaba, Rūbena dēla, dēliem, ka zeme atdarīja savu muti un tos aprija ar viņu padomu, kas tiem piederēja visa Israēla vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Jo jūsu acis ir redzējušas visu šo lielo darbu, ko Tas Kungs darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Tad nu turiet visus tos baušļus, ko es tev šodien pavēlu, ka jūs topat stipri un nākat un uzņemat to zemi, ko jūs ejat iemantot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Ka jūs ilgi dzīvojat tai zemē, ko Tas Kungs jūsu tēviem zvērējis, dot viņiem un viņu dzimumam, zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Jo tā zeme, uz kurieni tu ej to iemantot, nav kā Ēģiptes zeme, no kurienes jūs esat izgājuši, ko tu apsēji ar savu sēklu un pats aplaistīji, tā kā kāpostu dārzu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Bet tā zeme, ko jūs ejat iemantot, ir zeme ar kalniem un ielejām, tā top slacīta ar ūdeni no debess lietus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Zeme, ko Tas Kungs, tavs Dievs, apgādā, uz ko Tā Kunga, tava Dieva, acis skatās bez mitēšanās no gada iesākuma līdz gada galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Un ja jūs labi klausīsiet Maniem baušļiem, ko Es jums šodien pavēlu un mīlēsiet To Kungu, savu Dievu, un Viņam kalposiet no visas savas sirds un no visas savas dvēseles,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Tad Es došu lietu jūsu zemē savā laikā, agri un vēlu, ka tu vari sakrāt savu labību un savu vīnu un savu eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Un Es došu zāli tavā laukā taviem lopiem, un tu ēdīsi un būsi paēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Sargājaties, ka jūsu sirds netop pārrunāta, atkāpties un kalpot citiem dieviem un tos pielūgt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Tā ka Tā Kunga bardzība neiedegās pret jums un neaizslēdz debesi, ka lietus nenāk un zeme nedod savus augļus, un ka jūs ātri neejat bojā no tās labās zemes, ko Tas Kungs jums dod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Ieliekat tad šos Manus vārdus savā sirdī un savā dvēselē un sienat tos par zīmi uz savām rokām, un ka tie ir par piemiņas zīmēm starp jūsu acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Un mācat tos saviem bērniem, ka tu no tiem runā savā namā sēžot un savu ceļu staigājot, ir apguļoties, ir ceļoties;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Un raksti tos uz sava nama stenderes un pie saviem vārtiem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Lai jūsu dienas un jūsu bērnu dienas top vairotas tai zemē, ko Tas Kungs jūsu tēviem zvērējis, tiem to dot, kamēr būs debess un zeme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Jo ja jūs turēsiet visus šos baušļus, ko Es jums pavēlu turēt, mīļodami To Kungu, savu Dievu, un staigādami visos Viņa ceļos un Viņam pieķerdamies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Tad Tas Kungs izdzīs visas šīs tautas jūsu priekšā, un jūs uzņemsiet lielākas un stiprākas tautas, nekā jūs esat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Visas vietas, kurp jūsu kāja staigās, jums piederēs, no tuksneša un Lībanus, no Eifrat upes līdz vakara jūrai būs jūsu robeža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Neviens priekš jums nepastāvēs; Tas Kungs, jūsu Dievs, darīs, ka no jums iztrūcināsies un bīsies visa tā zeme, kur jūs staigāsiet, kā Viņš uz jums runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Redzi, es jums šodien ceļu priekšā svētību un lāstu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Svētību, ja jūs klausīsiet Tā Kunga, sava Dieva, baušļiem, ko es šodien jums pavēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Bet lāstu, ja jūs neklausīsiet Tā Kunga, sava Dieva, baušļiem un atkāpsities no tā ceļa, ko es jums šodien pavēlu, staigājot citiem dieviem pakaļ, ko jūs nepazīstat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Un kad Tas Kungs, tavs Dievs, tevi ievedīs tai zemē, ko tu ej iemantot, tad tev būs izsaukt to svētību uz Gerizim kalna un to lāstu uz Ebal kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Vai tie nav viņpus Jardānes, aiz tā ceļa pret saules noiešanu, Kanaāniešu zemē, kas klajumā dzīvo pret Gilgalu, sānis Mores ozoliem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Jo jūs iesiet pāri pār Jardāni, to zemi iemantot, ko Tas Kungs, jūsu Dievs, jums dod, un jūs to iemantosiet un tur dzīvosiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Tad nu turat un darāt visus likumus un visas tiesas, ko es jums šodien lieku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Šie ir tie likumi un tās tiesas, ko jums būs turēt un darīt tai zemē, ko Tas Kungs, tavu tēvu Dievs, tev devis iemantot, kamēr jūs dzīvojat tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Izpostiet pilnīgi visas tās vietas, kur tie pagāni, ko jūs uzvarēsiet, kalpojuši saviem dieviem, uz augstiem kalniem un uz pakalniem un apakš zaļiem kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Un viņu altārus jums būs apgāzt un viņu stabus salauzt un viņu elka kokus ar uguni sadedzināt un viņu dievu tēlus nocirst, un viņu vārdus izdeldēt no tās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Tā jūs nedariet Tam Kungam, savam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Bet to vietu, ko Tas Kungs, jūsu Dievs, izredzēs no visām jūsu ciltīm, tur iecelt Savu vārdu, Viņa mājas vietu, to jums būs meklēt, un uz turieni tev būs iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Un tur jums būs novest savus dedzināmos upurus un savus kaujamos upurus un savus desmitos un savas rokas cilājamos upurus un savus solījumus un savas labprātības dāvanas un savu lielo un sīko lopu pirmdzimtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Un tur jums un jūsu namiem Tā Kunga, sava Dieva, priekšā būs ēst un priecāties par visu, ko jūsu rokas atnes, ar ko Tas Kungs tavs Dievs, tevi svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Nedariet, kā mēs šeit šodien darām, ikviens, kā tam šķiet pareizi esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Jo jūs līdz šim neesat nākuši pie dusas, nedz pie tās mantības, ko Tas Kungs, tavs Dievs, tev dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Bet jūs iesiet pāri pār Jardāni un dzīvosiet tai zemē, ko Tas Kungs, jūsu Dievs, jums liks iemantot, un Viņš jums dos dusu no visiem jūsu ienaidniekiem visapkārt, un jūs dzīvosiet mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Kad nu Tas Kungs, jūsu Dievs, izredzēs vietu, tur iecelt Savu vārdu, uz turieni jums būs nest visu, ko es jums pavēlu, savus dedzināmos upurus un savus kaujamos upurus, savus desmitos un savas rokas cilājamos upurus, un visus savus izredzētos solījumus, ko jūs Tam Kungam esat solījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Un jums būs priecāties Tā Kunga, sava Dieva, priekšā, jums un jūsu dēliem un jūsu meitām un jūsu kalpiem un jūsu kalponēm un tam Levitam, kas ir jūsu vārtos, jo tam nav daļas nedz mantības līdz ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Sargies, ka tu savus dedzināmos upurus neupurē jebkurā vietā, ko tu ieraugi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Bet tai vietā, ko Tas Kungs izredzēs vienā no tavām ciltīm, tur tev būs upurēt savus dedzināmos upurus, un tur tev visu būs darīt, ko es tev pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Bet kā vien tavai dvēselei tīk, tu vari kaut un gaļu ēst visos savos vārtos, pēc Tā Kunga, sava Dieva, svētības, ko Viņš tev ir devis, šķīstais un nešķīstais to lai ēd, kā stirnu un briedi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Tikai asinis jums nebūs ēst; jums tās būs izliet zemē kā ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Bet savos vārtos tu nevari ēst to desmito no savas labības un sava vīna un savas eļļas, nedz tos pirmdzimtos no saviem lieliem un sīkiem lopiem, nedz savus solījumus, ko tu esi solījis, nedz savas labprātības dāvanas, nedz savas rokas cilājamo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Bet to tu ēd Tā Kunga, sava Dieva, priekšā, tai vietā, ko Tas Kungs, tavs Dievs, izredzēs, tu un tavs dēls un tava meita un tavs kalps un tava kalpone un tas Levits, kas ir tavos vārtos, un priecājies Tā Kunga, sava Dieva, priekšā par visu, ko tava roka dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Sargies, ka tu to Levitu neatstāji, kamēr tu dzīvo savā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Kad Tas Kungs, tavs Dievs, izpletīs tavas robežas, kā Viņš tev ir runājis, un tu sacīsi: es ēdīšu gaļu,- tāpēc ka tavai dvēselei gribās gaļu ēst, - tad tu vari gaļu ēst, kā vien tavai dvēselei tīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Ja tā vieta būs tālu no tevis, ko Tas Kungs, tavs Dievs, izredzēs Savu vārdu tur iecelt, tad tu vari kaut no saviem lieliem un sīkiem lopiem, ko Tas Kungs tev ir devis, kā es tev esmu pavēlējis, un vari ēst savos vārtos, kā vien tavai dvēselei tīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Bet tikai kā stirnu un briedi ēd, tā tu to vari ēst; nešķīstais līdz ar šķīsto lai to ēd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Noturies tikai, ka tu asinis neēd, jo asinīs ir dvēsele; un dvēseli ar miesu tev nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Tās tev nebūs ēst, bet izliet zemē kā ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Tās tev nebūs ēst, lai labi klājās tev un taviem bērniem pēc tevis, ja tu darīsi, kas ir pareizi priekš Tā Kunga acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Bet savas svētās dāvanas, kas tev būs, un savus solījumus tev būs ņemt un tai vietā noiet, ko Tas Kungs izredzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Un savus dedzināmos upurus, gaļu un asinis tev būs sataisīt uz Tā Kunga, sava Dieva, altāra, un izliet savu upuru asinis uz Tā Kunga, sava Dieva, altāri, bet to gaļu tev būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Ņem vērā un klausi visus šos vārdus, ko es tev pavēlu, lai labi klājās tev un taviem bērniem pēc tevis mūžīgi, ja tu darīsi, kas ir labi un pareizi priekš Tā Kunga, sava Dieva, acīm. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Kad Tas Kungs, tavs Dievs, tavā priekšā izdeldēs tos pagānus, ko tu ej iemantot, un tu tos būsi iemantojis un dzīvosi viņu zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Sargies, ka tu netopi savaldzināts, viņiem dzīties pakaļ, kad tie tavā priekšā ir izdeldēti, un ka tu nevaicā pēc viņu dieviem sacīdams: tā kā šie ļaudis kalpojuši saviem dieviem, tāpat es arīdzan darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Tev tā nebūs darīt Tam Kungam, savam Dievam, jo viss, kas Tam Kungam ir negantība, ko Viņš ienīst, to tie saviem dieviem ir darījuši, jo tie arī savus dēlus un savas meitas ar uguni ir sadedzinājuši saviem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Visus tos vārdus, ko es jums pavēlu, jums būs turēt, ka jūs tā dariet; tev pie tiem nebūs neko pielikt, neko atraut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Kad pravietis vai sapņotājs pie tevis ceļas un tev dod kādu zīmi vai brīnumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Un tā zīme jeb tas brīnums nāk, ko viņš uz tevi bija runājis, sacīdams: dzīsimies pakaļ citiem dieviem, ko tu nepazīsti, un kalposim tiem. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Tad tev nebūs klausīt šī pravieša vārdiem nedz šī sapņotāja sapnim, jo Tas Kungs, jūsu Dievs, jūs pārbauda, lai var atzīt, vai jūs To Kungu, savu Dievu, mīlat no visas savas sirds un no visas savas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Tam Kungam, savam Dievam, jums būs dzīties pakaļ un Viņu bīties, un Viņa baušļus jums būs turēt un Viņa balsi klausīt un Viņam kalpot un Viņam pieķerties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Un šim pravietim un šim sapņotājam būs tapt nokautam, tāpēc ka viņš ir mācījis atkāpties no Tā Kunga, jūsu Dieva, kas jūs izvedis no Ēģiptes zemes un atpestījis no tā vergu nama, un ka viņš tevi noved no tā ceļa, ko Tas Kungs, tavs Dievs, tev ir pavēlējis staigāt; tā tev to ļaunumu būs izdeldēt no sava vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Kad tavs brālis, tavas mātes dēls, vai tavs dēls, vai tava meita, vai tā sieva pie tavām krūtīm, vai tavs draugs, ko tu turi tā kā savu dvēseli, tevi paslepeni kārdinās un sacīs: ejam kalposim citiem dieviem! Ko ne tu nepazīsti, ne tavi tēvi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'No to ļaužu dieviem, kas dzīvo jums apkārt, vai tuvu vai tālu no tevis, no viena zemes gala līdz otram,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Tad nedod viņam vaļas un neklausi viņam, un tava acs lai viņu netaupa, un tu nežēlo viņu un neapslēpi viņu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Bet kautin viņu būs nokaut, - tava roka lai ir tā pirmā pret viņu to nonāvēt, un pēc tam visu ļaužu roka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Ar akmeņiem to būs nomētāt, ka mirst, jo viņš meklēja tevi novērst no Tā Kunga, tava Dieva, kas tevi izvedis no Ēģiptes zemes, no tā vergu nama;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Lai viss Israēls to dzird un bīstas un nedara vairs tādu ļaunu darbu tavā vidū. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Kad tu dzirdēsi par kādu no tavām pilsētām, ko Tas Kungs, tavs Dievs, tev dod tur dzīvot, ka saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Vīri, Beliala bērni (ļauni un nelietīgi), no tava vidus ir izgājuši un pārrunājuši savas pilsētas iedzīvotājus sacīdami: ejam kalposim citiem dieviem! Ko jūs nepazīstat, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Tad tev būs izvaicāt, izklausīt un izjautāt labi, un redzi, ja tas tiešām tiesa un šī negantība tavā vidū ir darīta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Tad tās pilsētas iedzīvotājus tev būs kautin nokaut ar zobena asmeni, un izdeldēt to pilsētu un visu, kas tur ir, un viņas lopus ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Un visu viņas laupījumu tev būs sakrāt viņas ielas vidū, un to pilsētu un viņas laupījumu pavisam sadedzināt ar uguni Tam Kungam savam Dievam, lai tā ir gruvešu kopa mūžam; to vairs nebūs uztaisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Un lai nekas no tā nolādētā nepaliek tavā rokā, lai Tas Kungs atgriežas no Savas bardzības karstuma un tev dod žēlastību un par tevi apžēlojās un tevi vairo, kā Viņš taviem tēviem ir zvērējis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Tāpēc ka tu Tā Kunga, sava Dieva, balsi esi klausījis, turēt visus Viņa baušļus, ko es tev šodien pavēlu, un dari, kas ir pareizi Tā Kunga, tava Dieva, acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Jūs esat Tā Kunga, sava Dieva, bērni; jums sev pašiem nebūs zīmes iegriezt nedz pleiķi darīt pār savām acīm kāda miroņa dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Jo tu esi svēta tauta Tam Kungam, savam Dievam, un Tas Kungs tevi ir izredzējis, ka tu Viņam esi īpaša tauta no visām tautām, kas virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Tev nebūs ēst nekādu negantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Šie ir tie lopi, ko jūs varat ēst: vērši, avis un kazas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Briedis, stirna un meža vērsis un kalna āzis un mazais briedis un sumbrs un meža kaza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Visus lopus, kam šķelti nagi un šķelti divējos gabalos, un kurš lops gremo, to ēdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Bet šos jums nebūs ēst no tiem, kas gremo, un no tiem, kam šķelti nagi: kamieļi un zaķi un trusi, jo tie gan gremo, bet tiem nav šķelti nagi; tie lai jums ir nešķīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Arī cūka, - jo tai gan šķelti nagi, bet tā negremo; lai tā jums ir nešķīsta; no viņas gaļas jums nebūs ēst un viņas maitu jums nebūs aizskart.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Šos ēdat no visa, kas ir ūdenī: visu, kam ir spuras un zvīņas, to ēdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Bet visu to, kam spuru un zvīņu nav, tos neēdat; lai tas jums ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Visus šķīstos putnus ēdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Bet šie ir, no kuriem jums nebūs ēst:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Ērglis, sarkandzeltenais ērglis un melnais ērglis, vārna, lija un vanags pēc savas kārtas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Un visi kraukļi pēc savas kārtas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Un strauss un bezdelīga un ķīris un vēja vanags pēc savas kārtas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Apogs un ūpis un pūce,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Un pelikāns un gulbis un maitas lija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Un stārķis, kalnu vanags pēc savas kārtas, bada dzeguze un sikspārnis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Un visi spārnoti līdēji lai jums ir nešķīsti, tos jums nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Visus šķīstos putnus ēdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Nekā sprāguša jums nebūs ēst; svešiniekam, kas ir tavos vārtos, to dod, lai viņš to ēd, vai pārdod to svešam; jo tu esi svēta tauta Tam Kungam, savam Dievam. Tev āzīti nebūs vārīt mātes pienā. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Tev būs taisni dot desmito tiesu no visiem savas sējas augļiem, ko tavs tīrums ik gadus nes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Un tev to būs ēst Tā Kunga, sava Dieva, priekšā, tai vietā, ko Viņš izredzēs, Savu vārdu tur iecelt, savas labības, sava vīna un savas eļļas desmito tiesu, un savu lielo un sīko lopu pirmdzimtos, lai tu mācies To Kungu, savu Dievu, bīties visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Bet ja tas ceļš priekš tevis visai tālu, ka tu to nevari nonest, tāpēc ka tā vieta no tevis ir tālu, ko Tas Kungs, tavs Dievs, izredzēs, Savu vārdu tur iecelt, kad Tas Kungs, tavs Dievs, tevi svētījis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Tad pārdod to par naudu un iesien to naudu savā rokā un ej uz to vietu, ko Tas Kungs, tavs Dievs, izredzēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Un dod to naudu par visu, kas tavai dvēselei tīk, par vēršiem un par avīm un par vīnu un par stipru dzērienu un par visu, ko tava dvēsele kāro un ēd tur Tā Kunga, sava Dieva, priekšā, un priecājies, tu un tavs nams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Bet to Levitu, kas ir tavos vārtos, tev nebūs atstāt, jo viņam nav daļas nedz mantības līdz ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Trešā gada galā tev būs izdot visu savu augļu desmito tiesu no šī gada, un tev to būs nolikt savos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Tad nāks tas Levits, tāpēc ka tam nav nekādas daļas nedz mantības līdz ar jums, un tas piedzīvotājs un tas bārenis un tā atraitne, kas ir tavos vārtos, un ēdīs un paēdīs, lai Tas Kungs, tavs Dievs, tevi svētī visā tavu roku darbā, ko tu dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Septītā gada galā tev būs turēt atlaišanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Šāda nu ir tā atlaišana, ka ikvienam aizdevējam būs atlaist, ko tas savam tuvākam aizdevis; tam nebūs spiest savu tuvāko nedz savu brāli, jo Tam Kungam atlaišana ir izsaukta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'No svešinieka atprasi, bet kas tev pie tava brāļa, to lai tava roka atlaiž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Lai jel nav nabagu tavā starpā; jo Tas Kungs svētīdams tevi svētīs tai zemē, ko Viņš, Tas Kungs, tavs Dievs, tev dos iemantot par īpašumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Ja tu tikai Tā Kunga, sava Dieva, balsi klausīsi, turēdams visus šos baušļus, ko es tev šodien pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Jo Tas Kungs, tavs Dievs, tevi svētīs, tā kā Viņš tev runājis; tad tu aizdosi daudz tautām, bet tu neaizņemsies, un tu valdīsi pār daudz tautām, bet viņām pār tevi nebūs valdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Kad tavā starpā būs nabags, kāds no taviem brāļiem kādos vārtos tavā zemē, ko Tas Kungs, tavs Dievs, tev dos, tad tev nebūs apcietināt savu sirdi, nedz aizslēgt savu roku priekš sava nabaga brāļa;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Bet atvērdams atver viņam savu roku un aizdodams aizdod viņam, cik viņam vajag savā trūkumā, kas trūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Sargies, ka tavā sirdī nav blēdības, ka tu nesaki: septītais gads, tas atlaišanas gads, ir tuvu, un tava acs būtu ļauna pret savu brāli, kas nabags, un tu viņam nedod; tad viņš par tevi brēks uz To Kungu, un tas tev būs par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Dod viņam labprāt, lai tava sirds nav ļauna, kad tu viņam dod, jo tādēļ Tas Kungs, tavs Dievs, tevi svētīs visā tavā darbā un pie visa, kur tu savu roku pieliksi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Jo tur nabagu netrūks tai zemē, tādēļ es tev pavēlu un saku: atvērdams atver savu roku savam brālim, kas top spaidīts un ir nabags tavā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Kad tavs brālis tev būs pārdots, Ebrejs vai Ebrejiete, tad lai viņš tev kalpo sešus gadus, bet septītā gadā tev būs viņu svabadu atlaist no sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Un kad tu viņu svabadu atlaidi, tad neatlaid viņu tukšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Apdāvinādams apdāvini to no sava ganāmā pulka, no savas klēts un no sava vīna spaida; ar ko Tas Kungs, tavs Dievs, tevi svētījis, no tā tev būs viņam dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Un piemini, ka tu esi bijis kalps Ēģiptes zemē, un ka Tas Kungs, tavs Dievs, tevi atpestījis, tāpēc es tev šodien pavēlu šās lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Bet ja viņš uz tevi sacīs: es no tevis negribu aiziet, tāpēc ka viņš tevi un tavu namu mīl, ka tam labi klājās pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Tad ņem īlenu un piedur viņa ausi pie durvīm, tad tas tev būs par kalpu mūžīgi; tāpat dari savai kalponei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Lai tev grūti nenākas viņu atlaist svabadu no sevis, jo sešus gadus viņš tev nokalpojis divkārtīgu algādža algu; tad tevi Tas Kungs, tavs Dievs, svētīs pie visa, ko tu darīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Ikvienu pirmdzimto, kas dzimst no tavām govīm un avīm, to tēviņu tev būs svētīt Tam Kungam, savam Dievam; ar savas govs pirmdzimto tev nebūs strādāt, un savu avju pirmdzimto tev nebūs cirpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Tā Kunga, sava Dieva, priekšā tev un tavam namam to būs ēst ikgadus tai vietā, ko Tas Kungs izredzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Bet ja tam kāda vaina, ka ir vai klibs vai akls, jeb ja ir cita kāda ļauna vaina, tad tev to nebūs upurēt Tam Kungam, savam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Savos vārtos to ēdat, nešķīstais un šķīstais kopā, itin kā stirnu un kā briedi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Tikai viņa asinis tev nebūs ēst, tās tev būs izliet zemē kā ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Ņem vērā Abiba mēnesi, ka tu tos Pasa svētkus turi Tam Kungam, savam Dievam, jo Abiba mēnesī Tas Kungs, tavs Dievs, tevi naktī izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Tad tev būs kaut to Pasa Tam Kungam, savam Dievam, avis un vēršus, tai vietā, ko Tas Kungs izredzēs, tur iecelt Savu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Tad tev nebūs ēst, kas raudzēts; septiņas dienas tev būs ēst neraudzētas bēdu maizes, jo steigdamies tu esi izgājis no Ēģiptes, lai tu piemini to dienu, kur izgāji no Ēģiptes zemes, kamēr tu dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Tāpēc septiņas dienas lai neredz rauga pie tevis pa visām tavām robežām, un par nakti līdz rītam lai nekas neatliek no tās gaļas, ko tu esi nokāvis pirmās dienas vakarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'To Pasa tu nevari kaut jebkuros no taviem vārtiem, ko Tas Kungs, tavs Dievs, tev dod;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Bet tai vietā, ko Tas Kungs, tavs Dievs, izredzēs, ka Viņa vārds tur dzīvo, (tur) tev būs kaut to Pasa, vakarā saulei noejot, ap to laiku, kur tu izgāji no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Tev to būs vārīt un ēst tai vietā, ko Tas Kungs, tavs Dievs, tev izredzēs; pēc tam tev rītā būs atpakaļ griezties un iet uz savu mājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Sešas dienas tev būs ēst neraudzētas maizes, bet septītā dienā lai ir svēta sapulce Tam Kungam, tavam Dievam; nekādu darbu tev nebūs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Septiņas nedēļas skaiti sev; kad ar cirpi nāk druvā, tad tev būs sākt skaitīt tās septiņas nedēļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Tad tev būs turēt nedēļu svētkus Tam Kungam, savam Dievam, ar savas rokas labprātīgo dāvanu, ko tu dosi, tā kā Tas Kungs, tavs Dievs, tevi svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Un tev būs priecāties Tā Kunga, sava Dieva, priekšā, tev un tavam dēlam un tavai meitai un tavam kalpam un tavai kalponei un tam Levitam, kas ir tavos vārtos, un tam piedzīvotājam, tam bāriņam un tai atraitnei, kas ir tavā vidū, tai vietā, ko Tas Kungs, tavs Dievs, izredzēs, ka Viņa vārds tur mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Un tev būs pieminēt, ka esi bijis kalps Ēģiptes zemē, un tev šos likumus būs turēt un darīt. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Lieveņu svētkus tev būs turēt septiņas dienas, kad tu esi sakrājis no sava klona un no sava vīna spaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Un tev būs priecāties savos svētkos, tev un tavam dēlam un tavai meitai un tavam kalpam un tavai kalponei un tam Levitam un tam piedzīvotājam un tam bāriņam un tai atraitnei, kas ir tavos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Septiņas dienas tev būs svētkus turēt Tam Kungam, savam Dievam, tai vietā, ko Tas Kungs izredzēs; jo Tas Kungs, tavs Dievs, tevi svētīs pie visiem taviem augļiem un pie visa tava roku darba, tāpēc tev tikai būs priecāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trīs reizes gadskārtā visiem taviem vīriešiem būs rādīties Tā Kunga, tava Dieva, priekšā tai vietā, ko Viņš izredzēs, neraudzētās maizes svētkos un nedēļu svētkos un lieveņu svētkos; bet tiem nebūs tukšā rādīties Tā Kunga priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Ikvienam ar savas rokas dāvanu, pēc tās svētības, ko Tas Kungs, tavs Dievs, tev devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Soģus un priekšniekus tev būs sev iecelt visos savos vārtos, ko Tas Kungs, tavs Dievs tev dos tavās ciltīs, lai tie tos ļaudis tiesā ar taisnu tiesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Tev nebūs tiesu grozīt, tev nebūs vaigu uzlūkot, tev arī nebūs dāvanas ņemt; jo dāvanas apstulbo acis gudriem un pārgroza lietas taisniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Pēc taisnības, taisnības tev būs dzīties, lai tu vari dzīvot un iemantot to zemi, ko Tas Kungs, tavs Dievs, tev dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Neviena koka tev nebūs stādīt sev par elka koku pie Tā Kunga, sava Dieva, altāra, ko tu sev taisīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Tev arī nebūs sev uzcelt nekādu elka stabu, ko Tas Kungs, tavs Dievs, ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Tam Kungam, savam Dievam, tev nebūs upurēt nedz vērsi nedz avi, kam kāda vaina jeb kaite, jo Tam Kungam, tavam Dievam, tā ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Kad tavā vidū, kādos vārtos, ko Tas Kungs, tavs Dievs, tev dos, atrastos vīrs vai sieva, kas ļaunu dara Tā Kunga, tava Dieva, priekšā, un pārkāpj Viņa derību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Un iet un kalpo citiem dieviem un tos pielūdz, vai sauli, vai mēnesi, vai visu debess pulku, ko es neesmu pavēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Un tas tev top sacīts, un tu to dzirdi, tad tev to būs labi izvaicāt, un redzi, ja tas ir tiesa, un tiešām šī negantība iekš Israēla ir darīta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Tad tev būs izvest šo vīru, vai šo sievu, kas šo grēku darījuši, pie saviem vārtiem, to vīru, vai to sievu, un tos akmeņiem nomētāt, lai mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Uz divu vai treju liecinieku vārda tam būs tapt nokautam, kam jāmirst; uz viena liecinieka vārda tam nebūs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Liecinieku roka lai ir tā pirmā pret viņu, to nonāvēt un pēc tam visu ļaužu roka; tā tev būs izdeldēt to ļaunumu no sava vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Kad kāda lieta tev pavisam grūti izspriest starp asinīm un asinīm, starp sūdzību un sūdzību, starp vainu un vainu, tiesas lietas tavos vārtos, tad celies un ej uz to vietu, ko Tas Kungs, tavs Dievs, izredzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Un tev būs nākt pie tiem priesteriem, tiem Levitiem, un pie tā soģa, kas to brīdi tur būs, un tev būs vaicāt, - tad viņi tev sludinās tiesas spriedumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Un tev būs darīt pēc tā vārda, ko viņi tev sacīs tai vietā, ko Tas Kungs izredzēs, un tev būs vērā ņemt un darīt visu, ko tie tev mācīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Pēc tās bauslības, ko tie tev mācīs un pēc tās tiesas, ko tie tev sacīs, tev būs darīt; tev nebūs atkāpties no tā vārda, ko tie tev sacīs, ne pa labo ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Ja kas laban turēsies pārgalvīgi, neklausīdams tam priesterim, kas tur stāv Tam Kungam, savam Dievam, kalpodams, vai tam soģim, tam būs mirt, un tev būs izdeldēt to ļaunumu no Israēla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Lai visi ļaudis to dzird un bīstas, un vairs neturās pārgalvīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Kad tu nāksi tai zemē, ko Tas Kungs, tavs Dievs, tev dos, un to iemantosi un tur dzīvosi un sacīsi: es pār sevi iecelšu ķēniņu, kā visas apkārtējās tautas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Tad iecel sev par ķēniņu to, ko Tas Kungs, tavs Dievs, izredzēs; no savu brāļu vidus tev būs sev iecelt ķēniņu, tu nevari pār sevi celt svešu vīru, kas nav tavs brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Bet viņam nebūs turēt pulka zirgu, nedz tos ļaudis atpakaļ vest uz Ēģiptes zemi, lai dabūtu pulka zirgu, jo Tas Kungs jums ir sacījis: tev nebūs atpakaļ griezties pa šo ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Tam arī nebūs apņemt daudz sievu, ka viņa sirds neatkāpjas; tam arī nebūs sev sakrāt ļoti daudz sudraba un zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Un kad viņš nu sēdēs uz sava valstības krēsla, tad lai viņš no tiem priesteriem un Levitiem sev grāmatā raksta šīs bauslības norakstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Un tas lai pie viņa stāv, un lai viņš tanī lasa visu savu mūžu, ka viņš mācās bīties To Kungu, savu Dievu, un turēt visus šās bauslības vārdus un visus šos likumus, ka viņš tos dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Ka viņa sirds nepaceļas pār saviem brāļiem, un ka viņš neatkāpjas no likuma ne pa labo, ne pa kreiso roku, lai viņš ilgi paliek savā valstībā, viņš un viņa dēli Israēla vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Priesteriem, Levitiem, visai Levja ciltij lai nav nedz daļas nedz mantības līdz ar Israēli; lai tie ēd no Tā Kunga uguns upuriem un no Viņa mantas daļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Un mantības lai tiem nav savu brāļu vidū, Tas Kungs ir viņu mantība, itin kā Viņš uz tiem runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Šī nu lai ir tā priesteru tiesa no tiem ļaudīm, no tiem, kas kādu upuri upurē, lai tas ir vērsis vai avs; priesterim lai dod pleci, abus žokļus un kuņģi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Savas labības, sava vīna un savas eļļas pirmajus, un pirmajus no savu avju cirpšanas tev būs viņam dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Jo Tas Kungs, tavs Dievs, viņu ir izredzējis no visām tavām ciltīm, lai tas stāv un kalpo Tā Kunga vārdam, viņš un viņa dēli visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Un ja kāds Levits nāk no kādiem Israēla vārtiem, kur viņš piemīt, un nāk, tā kā viņa dvēselei tīk, uz to vietu, ko Tas Kungs izredzēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Un kalpo Tā Kunga, sava Dieva, vārdā, kā visi viņa brāļi, tie Leviti, kas tur Tā Kunga priekšā stāv,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Tad lai tie ēd līdzīgu daļu, pāri par viņu ienākumu no tēvu puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Kad tu nāc tai zemē, ko Tas Kungs, tavs Dievs, tev dos, tad tev nebūs mācīties darīt pēc šo pagānu negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Lai tavā starpā netop atrasts, kas savam dēlam vai savai meitai liek iet caur uguni, neviens zīlnieks, ne burvis, ne pūšļotājs, ne riebējs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Ne vārdotājs, ne pareģis, ne pesteļu cienītājs, nedz miroņu vaicātājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Jo visi, kas to dara, Tam Kungam ir negantība, un šīs negantības dēļ Tas Kungs, tavs Dievs, tos izdzen tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Bezvainīgam tev būs būt Tā Kunga, sava Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Jo šās tautas, ko tu izdzīsi, cienī burvjus un zīlniekus, bet tev tā neklājās; tev Tas Kungs, tavs Dievs, tā nav devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Pravieti, kāds es esmu, Tas Kungs, tavs Dievs, tev cels no tava vidus, no taviem brāļiem, - tam jums būs klausīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Pēc visa tā, ko tu esi lūdzies no Tā Kunga, sava Dieva, Horebā, sapulces dienā, sacīdams: es vairs negribu dzirdēt Tā Kunga, sava Dieva, balsi, un negribu vairs redzēt šo lielo uguni, ka nemirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Tad Tas Kungs uz mani sacīja: tas ir labi, ko tie runājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Es tiem celšu pravieti, kāds tu esi, no viņu brāļu vidus, un Es likšu Savu vārdu viņa mutē, un viņš runās uz tiem visu, ko Es tam pavēlēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Un ja kāds neklausīs Maniem vārdiem, ko viņš runās Manā Vārdā, no tā Es to prasīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Bet tas pravietis, kas iedrošinājās runāt Manā Vārdā, ko Es tam neesmu pavēlējis runāt, vai ja tas citu dievu vārdā runās, šim pravietim būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Ja tu tad savā sirdī sacīsi: kā lai pazīstam to vārdu, ko Tas Kungs nav runājis? -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Kad tas pravietis Tā Kunga Vārdā runās, un tas vārds nenotiek un nenāk, - tad šis ir tas vārds, ko Tas Kungs nav runājis, tas pravietis to ir aplam runājis, tāpēc nebīsties no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Kad Tas Kungs, tavs Dievs, izdeldēs tās tautas, kuru zemi Tas Kungs, tavs Dievs, tev dos, un tu tās iemantosi un dzīvosi viņu pilsētās un viņu namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Tad trīs pilsētas tev būs atšķirt savā zemē, ko Tas Kungs, tavs Dievs, tev dos iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Sataisi ceļu uz turieni, un iedali trīs daļās savas zemes robežas, ko Tas Kungs, tavs Dievs, tev liks iemantot, ka uz turieni var bēgt ikviens, kas kādu nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Un tā lai notiek ar to, kas kādu nokāvis: kas uz turieni bēgs, tas dzīvos, ja savu tuvāko netīši nositis un ar to iepriekš nav bijis ienaidā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Ja kas ar savu tuvāko mežā ietu, malku cirst, un viņš paceltu savu roku ar cirvi, malku cirst, un cirvis nomuktu no kāta un aizķertu viņa tuvāko, ka tas mirtu, tas lai bēg uz vienu no šīm pilsētām, ka paliek dzīvs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Lai asiņu atriebējs nedzenās pakaļ nokāvējam, kad viņa sirds iekarsusi, un to nepanāk, kad tas ceļš būtu tālu, un viņam neņem dzīvību, jebšu viņš nāvi nav pelnījis, jo viņš ar to iepriekš nebija ienaidā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Tāpēc es tev pavēlu un saku: tev būs sev atšķirt trīs pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Un kad Tas Kungs, tavs Dievs, izplatīs tavas robežas, kā Viņš taviem tēviem ir zvērējis, un tev dos visu zemi, ko Viņš solījis dot taviem tēviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(Kad tu visu šo likumu turēsi, un darīsi, ko es tev šodien pavēlu, ka tu mīļo To Kungu, savu Dievu, un visu mūžu staigā Viņa ceļos): tad tev vēl sev būs pielikt trīs pilsētas pie šīm trim;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Lai nenoziedzīgas asinis netop izlietas tavā zemē, ko Tas Kungs, tavs Dievs, tev dos par īpašumu, un lai nepaliek asins vainas uz tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Bet ja kāds būs, kas savu tuvāko ienīst un uz viņu glūn un pret viņu ceļas un viņu sit, ka mirst, un bēg uz vienu no šīm pilsētām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Tad viņa pilsētas vecajiem būs sūtīt un viņu no turienes paņemt, un nodot asiņu atriebējam rokā, lai mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Lai tava acs viņu nežēlo, bet tev būs atņemt tā nenoziedzīgā asinis no Israēla, lai tev labi klājās. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Tev nebūs pārcelt sava tuvākā ežas (robežas), ko tie tēvi likuši tavā daļā, ko tu iemantosi tai zemē, ko tev Tas Kungs, tavs Dievs, dos iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Vienam vienīgam lieciniekam nebūs celties pret nevienu par kādu noziegumu jeb par kādu grēku, ko tas būtu darījis; uz divu vai treju liecinieku vārda lai tā lieta pastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Kad blēdīgs liecinieks ceļas pret kādu, pret viņu apliecināt pārkāpumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Tad tiem diviem vīriem, kam tā ķilda, būs stāties Tā Kunga priekšā, priekš tiem priesteriem un tiem soģiem, kas to brīdi būs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Un tiem soģiem būs labi izvaicāt, un redzi, ja tas liecinieks ir viltīgs liecinieks un devis nepatiesu liecību pret savu brāli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Tad jums būs viņam darīt, itin kā viņš nodomāja darīt savam brālim, un tev to ļaunumu no sevis būs izdeldēt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Lai tie citi to dzird un bīstas, un vairs nedara tādu ļaunu darbu tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Tad nu lai tava acs nežēlo: dzīvība pret dzīvību, acs pret aci, zobs pret zobu, roka pret roku, kāja pret kāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Kad tu iesi karā pret saviem ienaidniekiem un redzēsi zirgus un ratus un ļaužu vairāk nekā tu, tad nebīsties no viņiem, jo ar tevi ir Tas Kungs, tavs Dievs, kas tevi izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Un kad jūs esat tuvu pie kaujas, tad priesterim būs pieiet un uz tiem ļaudīm runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Un uz tiem sacīt: klausies, Israēl, jūs šodien ejat karā pret saviem ienaidniekiem, - lai jūsu sirds nepaliek bailīga, nebīstaties un nebaiļojaties un neiztrūcināties priekš tiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Jo Tas Kungs, jūsu Dievs, Tas iet jums līdz, par jums karot ar jūsu ienaidniekiem, jūs atpestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Tad tiem priekšniekiem būs runāt uz tiem ļaudīm un sacīt: ja kas laban jaunu namu uztaisījis, un to vēl nav iesvētījis, tas lai iet un griežas uz savu namu, ka tas karā nemirst un cits to neiesvēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Un ja kas laban dēstījis vīna dārzu un augļus no tā nav baudījis, tas lai iet un griežas atpakaļ uz savu namu, ka tas karā nemirst un cits nebauda viņa augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Un ja kas laban sievu precējis un to vēl nav pārvedis, tas lai iet un griežas uz savu namu, ka tas karā nemirst un cits to neapņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Pēc tam tiem priekšniekiem vēl būs runāt uz tiem ļaudīm un sacīt: ja kas laban bīstas un kam ir bailīga sirds, tas lai iet un griežas uz savu namu, ka tas savu brāļu sirdi neiebaida tā kā savu paša sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Un kad tie priekšnieki ir pabeiguši uz tiem ļaudīm runāt, tad tiem būs iecelt karaspēka virsniekus ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Kad tu nāc pie kādas pilsētas pret viņu karot, tad tev būs viņai piedāvāt mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Un ja tā ar tevi līgs mieru un tev atvērs, tad lai visi ļaudis, kas tur atrodas, tev paliek par klausītājiem un tev kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Bet ja tie mieru ar tevi nelīgs, bet pret tevi karos, tad spiedi tos ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Un kad Tas Kungs, tavs Dievs, to pilsētu nodos tavā rokā, tad visus vīriešus, kas tur ir, tev būs apkaut ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Bet tās sievas un tos bērniņus un tos lopus un visu, kas tai pilsētā, visu viņu laupījumu, ņem sev un ēd savu ienaidnieku laupījumu, ko Tas Kungs, tavs Dievs, tev ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tā tev būs darīt visām pilsētām, kas tālu no tevis, kas nav no šo tautu pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Bet no šo ļaužu pilsētām, ko Tas Kungs, tavs Dievs, tev dos par īpašumu, tev neko nebūs atstāt dzīvu, kam ir dzīva dvaša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Bet izdeldi tos pavisam: Hetiešus, Amoriešus, Kanaāniešus, Fereziešus, Hiviešus un Jebusiešus, itin kā tev Tas Kungs, tavs Dievs, ir pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Lai tie jūs nemāca darīt pēc visām savām negantībām, ko tie darījuši saviem dieviem, un lai jūs pret To Kungu, savu Dievu, negrēkojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Kad tu kādu pilsētu ilgu laiku apstāsi, pret viņu karodams, lai viņu uzvarētu, tad tev nebūs postīt viņas kokus, cirvi tiem pielikdams; jo tu no tiem vari ēst, bet tev tos nebūs nocirst; jo vai tas koks laukā ir cilvēks, ka tu pret viņu karotu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Bet tos kokus, ko jūs pazīsiet, ka tie nav ēdami koki, tos tu vari postīt un nocirst, un no tiem uzcelt apcietinājumu pret to pilsētu, kas ar tevi karo, kamēr tu to uzvari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Kad atrod kādu nokautu tai zemē, ko Tas Kungs, tavs Dievs, tev dos iemantot, un tas guļ uz lauka, un neviens nezin, kas to nokāvis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Tad taviem vecajiem un taviem soģiem būs iziet ārā un mērot līdz tām pilsētām, kas ir ap to nokauto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Kura pilsēta nu tam nokautam tā tuvākā, tās pilsētas vecaji lai ņem no liellopiem teli, ar ko vēl nav strādāts, kas nekādu jūgu vēl nav vilkusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Un tās pilsētas vecajiem būs novest to teli tekošas upes ielejā, kur netop ne strādāts, ne sēts, un tiem tur upes ielejā tai telei būs lauzt kaklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Tad priesteriem, Levja bērniem, būs pieiet, jo Tas Kungs, tavs Dievs, tos ir izredzējis, Viņam kalpot un svētīt Tā Kunga Vārdā, un lai pēc viņu vārdiem ikviena ķilda un ikviena vaina top izlīdzināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Un visiem šīs pilsētas vecajiem, kas tam nokautam ir tie tuvākie, būs mazgāt savas rokas pār to teli, kam kakls lauzts upes ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Un tiem būs dot liecību un sacīt: mūsu rokas nav izlējušas šās asinis un mūsu acis nav redzējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Piedod Saviem Israēla ļaudīm, ko Tu, Kungs, esi atpestījis, un nepielīdzini nenoziedzīgas asinis Saviem Israēla ļaudīm - tad tie būs salīdzināti par šīm asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Tā Tu izdeldēsi tās nenoziedzīgās asinis no Sava vidus, darīdams, kas ir tiesa Tā Kunga acīs. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Kad tu iesi karā pret saviem ienaidniekiem, un Tas Kungs viņus nodos tavā rokā, ka tu gūstītus no viņiem pārvedi cietumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Un tu redzēsi starp tiem gūstītiem skaistu sievu, un tu viņas iegribies un to ņem sev par sievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Tad tev to būs vest savā namā un lai viņa savu galvu apcērp un savus nagus apgraiza,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Un noliek savas cietuma drēbes un sēž tavā namā un apraud savu tēvu un savu māti vienu mēnesi un pēc tam ej pie viņas un esi viņai par vīru, un viņa lai ir tev par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Un ja viņa tev nepatīk, tad atlaid viņu, kur viņa grib, bet par naudu tev to nebūs pārdot, nedz turēt verdzībā, tāpēc ka tu to esi pazemojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Kad kādam vīram ir divas sievas, viena mīlēta un otra neieredzēta, un tā mīlētā kā tā neieredzētā dzemdē viņam dēlus, un tas pirmdzimtais ir no tās neieredzētās, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Un kad viņš saviem dēliem savu mantu dalīs, tad tās mīlētās dēlu viņš nevar uzņemt par pirmdzimto, tās neieredzētās dēla vietā, kas tas pirmdzimtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Bet viņam būs atzīt tās neieredzētās dēlu par pirmdzimto, un tam dot divkārtīgu tiesu no visa, kas tam ir; jo tas ir viņa spēka pirmdzimtais, - tam pieder pirmdzimtības tiesa. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Kad kādam vīram ir stūrgalvīgs un neklausīgs dēls, kas neklausa sava tēva un savas mātes balsij, un tie viņu ir pārmācījuši, un viņš tomēr tiem neklausa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Tad viņa tēvam un mātei to būs sagrābt un izvest pie savas pilsētas vecajiem un pie savas pilsētas vārtiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Un tiem būs sacīt uz savas pilsētas vecajiem: šis mūsu dēls ir stūrgalvīgs un neklausīgs, viņš neklausa mūsu balsij, viņš ir rijējs un dzērājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Tad visiem viņa pilsētas ļaudīm to būs akmeņiem nomētāt, ka mirst. Tā tev būs izdeldēt to ļaunumu no tava vidus, ka viss Israēls to dzird un bīstas. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Un ja kas darījis kādu grēku, ar ko tas nāvi pelnījis, un top nonāvēts un tu to pakar pie koka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Tad lai viņa miesas nepaliek par nakti pie koka, bet aproc tās tai pašā dienā; jo tas pakārtais ir Dieva lāsts; tā tev šo zemi nebūs apgānīt, ko Tas Kungs, tavs Dievs, tev dod par īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Sava brāļa vērsi vai avi tev nebūs redzēt maldamies un no viņa atrauties; tev tos būs atpakaļ vest savam brālim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Un ja tavs brālis tev nav tuvu, un tu to nepazīsti, tad tev tos būs pārdzīt savās mājās, lai tie paliek pie tevis, kamēr tavs brālis tos meklē; tad tev tos būs viņam atdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tāpat tev arī būs darīt pie viņa ēzeļa, un tā tev būs darīt pie viņa drēbēm, un tā tev būs darīt pie visa pazuduša, kas tavam brālim zūd un ko tu atrodi, - tu no tā nevari atrauties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Tev sava brāļa ēzeli vai viņa vērsi nebūs redzēt uz ceļa pakritušus un no tiem atrauties; palīdzi viņam tos uzcelt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Vīra drēbes sievai nebūs valkāt, un vīram nebūs apvilkt sievas drēbes; jo visi, kas to dara, Tam Kungam, savam Dievam, ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Kad tu putna ligzdu uzej ceļā, kādā kokā vai zemē, ar bērniem vai ar olām, un mātīte sēž uz tiem bērniem vai uz tām olām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Tad tev nebūs ņemt to mātīti līdz ar tiem bērniem; to mātīti palaid un tos bērnus ņem priekš sevis, lai tev labi klājās un tu ilgi dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Kad tu uzcērt jaunu namu, tad taisi margas uz sava jumta, ka tu nekrauj kādu asins vainu uz savu namu, ja kāds no tā nokristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Tev savu vīna dārzu nebūs apsēt ar mistru, ka nekrīt svētumam viss tavas sējas ienākums un vīna dārza augļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Tev nebūs art ar vērsi un ēzeli kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Tev nebūs valkāt pusnātnas drēbes, vilnainu un nātnu kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tev būs sev taisīt pušķus pie sava apsega četriem stūriem, ar ko tu apsedzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Kad vīrs ņem sievu un pie tās ieiet un tad to ienīst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Un tai ceļ neslavu un no tās izpauž ļaunu valodu, sacīdams: šo sievu es esmu ņēmis un pie tās iegājis, bet to neesmu atradis šķīstu meitu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Tad šīs meitas tēvam un mātei to būs ņemt, un to zīmi, ka tā bijusi šķīsta meita, rādīt pilsētas vecajiem vārtos:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Un tās meitas tēvam būs sacīt uz tiem vecajiem: es šim vīram savu meitu esmu devis par sievu, bet viņš to ir ienīdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Un redzi, viņš tai cēlis neslavu sacīdams: es tavu meitu neesmu atradis šķīstu; še nu tā zīme, ka mana meita bijusi šķīsta, un tiem būs izklāt tās drēbes priekš pilsētas vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Tad pilsētas vecajiem to vīru būs ņemt un pārmācīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Un tie lai viņam nospriež simts sudraba sēķeļus un to naudu lai dod tās meitas tēvam, tāpēc ka tas šķīstai Israēla meitai cēlis kauna valodu, un viņa lai tam paliek par sievu; tas to nevar atlaist visu savu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Bet ja tā valoda ir tiesa, ka tā nav atrasta šķīsta meita,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Tad tiem to meitu būs izvest pie viņas tēva nama durvīm, un viņas pilsētas ļaudis lai viņu akmeņiem nomētā, ka mirst, tāpēc ka viņa kauna lietu ir darījusi iekš Israēla, maucību dzīdama sava tēva namā. Tā tev būs izdeldēt to ļaunumu no sava vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Ja kāds vīrs top atrasts, kas guļ pie cita vīra sievas, tad tiem abiem būs mirt, tam vīram, kas pie tās sievas gulējis, un tai sievai. Tā tev būs izdeldēt to ļaunumu no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Kad kāda meita ir saderēta kādam vīram, un cits vīrs to sastaps pilsētā un pie tās gulēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Tad jums būs abus izvest aiz pilsētas vārtiem un tos akmeņiem nomētāt, ka mirst, to meitu tādēļ, ka tā nav brēkusi pilsētā, un to vīru tādēļ, ka tas piesmējis sava tuvākā sievu. Tā tev būs izdeldēt to ļaunumu no sava vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Bet ja kāds sastop saderētu meitu laukā un to pārvar un pie tās guļ, tad lai tas vīrs, kas pie tās gulējis, viens pats mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Bet tai meitai tev neko nebūs darīt; tai meitai nav nekādas nāves vainas; jo itin kā kad vīrs celtos pret savu tuvāko un viņu nokautu, - tāda pat ir šī lieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Jo viņš to laukā ir sastapis, tā saderētā meita brēca, bet tur nebija glābēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Kad kāds sastop jaunu meitu, kas nav saderēta, un to sagrābj un pie tās guļ, un tie top atrasti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Tad tas, kas pie viņas gulējis, lai dod tam meitas tēvam piecdesmit sudraba sēķeļus, un tā lai viņam ir par sievu, tāpēc ka viņš to piesmējis; tas viņu savu mūžu nevar atlaist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nevienam nebūs ņemt sava tēva sievu, nedz atsegt sava tēva apsegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Neviens, kam kaunums ir sagrūsts, vai kas ir rāmits(kastrēts), lai nenāk Tā Kunga draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Nevienam maukas bērnam nebūs nākt Tā Kunga draudzē, un arī viņa desmitam augumam nebūs nākt Tā Kunga draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Nevienam Amonietim un nevienam Moabietim nebūs nākt Tā Kunga draudzē, līdz pat viņu desmitam augumam; ne mūžam tiem nebūs nākt Tā Kunga draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Tādēļ ka tie jums nav pretī nākuši ar maizi un ar ūdeni tai ceļā, kad jūs izgājāt no Ēģiptes zemes, un ka viņš pret tevi ir derējis Bileāmu, Beora dēlu, no Petoras, no Mezopotamijas, tevi nolādēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Bet Tas Kungs, tavs Dievs, negribēja Bileāmu paklausīt, bet Tas Kungs, tavs Dievs, lāstu tev pārvērta par svētību, tādēļ ka Tas Kungs, tavs Dievs, tevi mīlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Tādēļ tev nebūs meklēt viņu mieru nedz viņu labumu visās tavās dienās ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Edomieti tev nebūs turēt par negantu, jo tas ir tavs brālis; Ēģiptieti tev nebūs turēt par negantu, jo tu esi bijis piemitējs viņa zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Tie bērni, kas viņam piedzims trešā augumā, tie lai nāk Tā Kunga draudzē. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Kad tu no lēģera izej pret saviem ienaidniekiem, tad tev būs sargāties no ikvienas ļaunas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Kad tavā starpā kāds vīrs, kas ir nešķīsts, kad tam naktī kas ir noticis, tas lai iziet ārā no lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Tam nebūs nākt lēģerī, bet pret vakaru lai viņš mazgājās ar ūdeni, un kad saule nogājusi, tad lai viņš nāk lēģerī. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Lai tev arī ir vieta ārpus lēģera, kur tu vari noiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Un lai tev ir lāpstiņa pie tavām citām lietām, un kad tu ārā sēdēsi, tad tev ar to būs rakt un atkal apraust, ko tu izmetis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Jo Tas Kungs, tavs Dievs, staigā tavā lēģerī, tevi pestīdams un tavus ienaidniekus tavā priekšā nododams, tāpēc tavam lēģerim būs būt svētam, lai Viņš neredz nekādu kauna lietu tavā starpā un nenogriežas no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Kalpu, kas no sava kunga pie tevis izglābies, tev nebūs nodot viņa kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Lai tas paliek pie tevis tavā vidū, tai vietā, ko viņš izredzēsies kaut kur tavos vārtos, kur viņam patīk; tev nebūs viņam pāri darīt. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Lai nav maukas starp Israēla meitām, nedz maucinieka starp Israēla dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Ne maukas algu nedz suņa naudu tev nebūs nest Tā Kunga, sava Dieva, namā par kādu solījumu: jo tie abi Tam Kungam, tavam Dievam, ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'No sava brāļa tev nebūs augļus dzīt, nedz naudas augļus nedz barības augļus nedz citas kādas lietas augļus, ar ko var augļus dzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'No svešiem tu vari augļus dzīt, bet no sava brāļa tev nebūs augļus dzīt, lai Tas Kungs, tavs Dievs, tevi svētī pie visa, kur tu savu roku pieliec, tai zemē, ko tu ej iemantot. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Kad tu Tam Kungam, savam Dievam, esi apsolījis kādu solījumu, tad tev nebūs kavēt to maksāt, jo Tas Kungs, tavs Dievs, to tiešām no tevis prasīs un tas tev būs par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Kad tu nesoli, tad tas tev nebūs par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Kas no tavām lūpām iziet, to tev būs turēt un darīt, itin kā tu Tam Kungam, savam Dievam, esi solījis no laba prāta to, ko tu ar savu muti esi runājis. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Kad tu ej sava tuvākā vīna dārzā, tad tu vari ogas ēst, kā tev tīk, kamēr tu paēdis, bet savā traukā tev neko nebūs ielikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Kad tu ej sava tuvākā druvā, tad tu ar roku vari noplūkt vārpas, bet cirpi tev nebūs likt pie sava tuvākā druvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Kad kāds apņem sievu un ar to iedodas laulībā, un kad tā neatrod žēlastību viņa acīs, tādēļ ka tas to pienācis kādā kauna lietā un viņš raksta šķiršanās grāmatu un to viņai dod rokā un viņu izraida no sava nama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Un tā iziet no viņa nama, un paliek citam vīram par sievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Un kad šis otrs vīrs arīdzan to ienīst un tai raksta šķiršanās grāmatu, un to tai dod rokā un to izraida no sava nama, vai ja tas otrs vīrs mirst, kas to sev par sievu ņēmis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Tad viņas pirmais vīrs, kas to izraidījis, to nevar atkal par sievu ņemt pēc tam, kad tā palikusi netīra; jo tā ir negantība priekš Tā Kunga; tā tev nebūs ar grēkiem apgānīt to zemi, ko Tas Kungs, tavs Dievs, tev dod iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Kad kāds apņem jaunu sievu, tam nebūs iet karā un to ne pie kā nebūs piespiest; veselu gadu lai tas ir svabads savā namā un iepriecina savu sievu, ko viņš ir ņēmis. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Tev nebūs ķīlā ņemt ne dzirnavas ne dzirnu akmeni, jo tāds apķīlā dzīvību. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Ja kādu atrod, kas cilvēku zog no saviem brāļiem, no Israēla bērniem un to tur kā vergu un to pārdod, šis zaglis lai mirst, un tev to ļaunumu būs izdeldēt no sava vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Sargies no spitālības, ka tu turi un tikuši(uzmanīgi ikkatru pamācību) dari, kā tie priesteri, tie Leviti, tev mācīs; kā es tiem esmu pavēlējis, tā jums to būs turēt un darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Piemini, ko Tas Kungs, tavs Dievs, pie Mirjames ir darījis ceļā, kad jūs izgājāt no Ēģiptes zemes. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Kad tu savam tuvākam ko aizdod uz parādu, tad tev nebūs viņa namā iet ķīlas ņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Paliec ārā un lai tas vīrs, kam tu uz parādu esi aizdevis, iznes tās ķīlas pie tevis ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Bet ja tas ir nabags, tad tev ar viņa ķīlām nebūs iet gulēt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Bet atdod viņam tās ķīlas, kad saule noiet, ka tas ar savu apsegu guļ un tevi svētī. Un tas tev būs par taisnību Tā Kunga, tava Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Neapspiedi bēdīgu nabaga algādzi, lai viņš ir no taviem brāļiem, vai no taviem piedzīvotājiem, kas ir tavā zemē un tavos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Bet to pašu dienu dod tam algu, lai saule pār to nenoiet; jo viņš ir nabags un viņa dvēsele uz to gaida, ka tas par tevi nesauc uz To Kungu un tas tev nav par grēku. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Tēviem nebūs tapt nokautiem dēlu dēļ, un dēliem nebūs tapt nokautiem tēvu dēļ, bet ikvienam būs tapt nokautam savu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Nepārgrozi piedzīvotāja un bāriņa tiesu, un neņem ķīlām atraitnes drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Piemini, ka tu esi bijis kalps Ēģiptes zemē, un ka Tas Kungs, tavs Dievs, tevi no turienes atpestījis; tādēļ es tev pavēlu to darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Kad tu savu labību pļausi savā tīrumā, un aizmirsīsi vienu kūlīti tīrumā, tad tev nebūs atgriezties to paņemt, bet lai tas paliek piedzīvotājam, bāriņam un atraitnei, lai Tas Kungs, tavs Dievs, tevi svētī visā tavā rokas darbā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kad tu savu eļļas koku nokratīsi, tad tev tos zarus nebūs otrreiz pārmeklēt; lai tas paliek piedzīvotājam, bāriņam un atraitnei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kad tu savā vīna dārzā ogas lasīsi, tad tev tās otrreiz nebūs lasīt, bet lai tas paliek piedzīvotājam un bāriņam un atraitnei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Un piemini, ka tu Ēģiptes zemē esi bijis par kalpu; tāpēc es tev pavēlu to darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Kad starp vīriem ir kāda ķilda un tie ies priekš tiesas, tad soģiem tos būs tiesāt un taisno taisnot un netaisno notiesāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Un ja tas vainīgais sitienus pelnījis, tad lai soģis tam liek mesties zemē, un klāt būdams tam liek sitienus dot ar skaitu pēc viņa vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Četrdesmit sitienus lai tam liek dot; Ne vairāk, lai, ja to vēl vairāk sistu pāri par to, tavs brālis nekļūst nicināts tavās acīs. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Vērsim, kas labību min, tev nebūs purnu apsiet.-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Kad brāļi kopā dzīvo un viens no tiem mirst un tam dēla nav, tad tā mirušā sievai nebūs (par sievu) tapt citam kādam svešam vīram, bet tā vīra brālis lai pie viņas ieiet un to ņem par sievu, un tai dara, kas vīra brālim pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Un to pirmdzimušo, ko viņa dzemdēs, viņam būs likt sava nomirušā brāļa vārdā, lai viņa vārds no Israēla netop izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Bet ja šim vīram nepatīk ņemt sava brāļa sievu, tad lai tā brāļa sieva iet pie tiem vecajiem vārtos un lai saka: mans vīra brālis liedzās savam brālim celt vārdu iekš Israēla; viņš man negrib darīt, kas vīra brālim pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Tad lai pilsētas vecaji viņu aicina un uz viņu runā; ja tad viņš pastāv un saka: man nepatīk viņu ņemt; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Tad lai viņa brāļa sieva iet pie viņa priekš vecaju acīm, un lai viņam novelk kurpi no kājas un lai viņam spļauj vaigā; un lai viņa atbild un saka: tā lai notiek tam vīram, kas negrib uzcelt sava brāļa namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Un viņa vārds iekš Israēla taps nosaukts baskājas nams. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Kad vīri viens ar otru kaujās, un tā viena sieva pieiet izglābt savu vīru no viņa sitēja rokas un izstiepj savu roku un sagrābj viņa kaunumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Tad tev to roku viņai būs nocirst, - lai tava acs nežēlo. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Tev nebūs divējādu svaru turēt savā kulē, lielu un mazu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Tev nebūs divējādu pūru turēt savā namā, lielu un mazu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Lai tev ir pilnīgs un taisns svars lai tev ir pilnīgs un taisns mērs, ka tu ilgi dzīvo tai zemē, ko Tas Kungs, tavs Dievs, tev dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Jo ikviens, kas to dara, ikviens, kas netaisni dara, tas Tam Kungam, tavam Dievam, ir negantība. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Piemini, ko Amalekieši tev darīja ceļā, kad izgājāt no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Kā viņi tev pretī cēlās ceļā, un tev kāva tos pakaļējus, visus nespēcīgos aiz tevis, kad tu biji piekusis un noguris, un tie nebijās Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Kad nu Tas Kungs, tavs Dievs, tev būs devis dusu no visiem taviem ienaidniekiem visapkārt tai zemē, ko Tas Kungs, tavs Dievs, tev dos par īpašumu iemantot, tad Amalekiešu piemiņu tev būs izdeldēt no pasaules. Neaizmirsti to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Un kad tu nāksi tai zemē, ko Tas Kungs, tavs Dievs, tev dos iemantot, un tu to dabūsi un tur dzīvosi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Tad tev būs ņemt no visiem zemes augļu pirmajiem, ko tu ievāksi no savas zemes, ko Tas Kungs, tavs Dievs, tev dos, un tev tos būs likt kurvī un iet uz to vietu, ko Tas Kungs, tavs, Dievs izredzēs, ka Viņa vārds tur mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Un tev būs iet pie tā priestera, kas tai laikā būs, un uz viņu sacīt: es šodien apliecināju priekš Tā Kunga, tava Dieva, ka es esmu ienācis tai zemē, ko Tas Kungs mūsu tēviem ir zvērējis, mums dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Tad tam priesterim no tavas rokas būs ņemt to kurvi un to likt priekš Tā Kunga, tava Dieva, altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Un tev priekš Tā Kunga, sava Dieva, būs atbildēt un sacīt: mans tēvs bija izģindis Sīrietis un nogāja uz Ēģiptes zemi un piemita tur ar mazu ļaužu pulciņu, un tur palika par lielu, stipru un varenu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Bet ēģiptieši mums darīja ļaunu un mūs spieda un mums uzlika grūtu kalpošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Tad mēs brēcām uz To Kungu, savu tēvu Dievu, un Tas Kungs paklausīja mūsu balsi un ieraudzīja mūsu bēdas un mūsu grūtumu un mūsu spaidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Un Tas Kungs mūs izveda no Ēģiptes zemes caur stipru roku un izstieptu elkoni un caur lielu iztrūcināšanu un caur zīmēm un brīnumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Un Viņš mūs ir vedis uz šo vietu, un mums devis šo zemi, zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Un nu redzi, es esmu atnesis augļu pirmajus no tās zemes, ko Tas Kungs man ir devis. - Tad tev tos būs atstāt Tā Kunga, sava Dieva, priekšā un pielūgt To Kungu, savu Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Un tev būs priecāties par visu to labumu, ko Tas Kungs devis tev un tavam namam, tev un tavam Levitam un tavam piedzīvotājam, kas ir tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Kad tu būsi atdevis to desmito tiesu no visiem saviem augļiem trešā gadā, šis ir tās desmitās tiesas gads, un būsi devis Levitam, piedzīvotājam, bāriņam un atraitnei, ka tie tavos vārtos ēd un ir paēduši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Tad tev priekš Tā Kunga, sava Dieva, vaiga būs sacīt: es to, kas svētīts, no nama esmu iznesis un esmu to arī devis Levitam un piedzīvotājam, bāriņam un atraitnei pēc visām Tavām pavēlēm, ko Tu man esi pavēlējis; Tavas pavēles es neesmu ne pārkāpis, ne aizmirsis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Es no tā neesmu ēdis savā skumībā un no tā neesmu neko atrāvis, kad biju nešķīsts, es no tā arī neesmu devis priekš miruša; es Tā Kunga, sava Dieva, balsij esmu klausījis, es esmu darījis, tā kā Tu man esi pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Skaties zemē no Savas svētās vietas, no debesīm, un svētī Savus Israēla ļaudis un to zemi, ko Tu mums esi devis, kā Tu mūsu tēviem esi zvērējis, zemi, kur piens un medus tek. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Šinī dienā Tas Kungs, tavs Dievs, tev pavēl šos likumus un šās tiesas darīt; tad nu turi un dari tos no visas savas sirds un no visas savas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Šodien tu Tam Kungam esi sacījis, lai Viņš tev ir par Dievu un ka tu gribi staigāt visos Viņa ceļos un turēt Viņa likumus un Viņa baušļus un Viņa tiesas, un klausīt Viņa balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Un Tas Kungs tev šodien ir sacījis, lai tu Viņam esi par īpašu tautu, kā Viņš tev runājis, un lai tu turi visus Viņa baušļus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Un ka Viņš tevi augsti cels pār visām tautām, ko Viņš ir darījis, par teikšanu un par slavu un par godu, un ka tu būsi svēta tauta Tam Kungam, savam Dievam, kā Viņš runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Un Mozus līdz ar Israēla vecajiem pavēlēja tiem ļaudīm un sacīja: turiet visu to pavēli, ko es jums šodien pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Un kad jūs iesiet pāri pār Jardāni uz to zemi, ko Tas Kungs, tavs Dievs, tev dos, tad tev būs uzcelt lielus akmeņus un tos apmest ar kaļķiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Un tev uz tiem būs rakstīt visus šīs bauslības vārdus, kad tu esi gājis pāri un iegājis tai zemē, ko Tas Kungs, tavs Dievs, tev dos, zemi, kur piens un medus tek, kā Tas Kungs, tavu tēvu Dievs, tev runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Kad jūs nu iesiet pāri pār Jardāni, tad jums šos akmeņus, par ko jums šodien pavēlu, būs uzcelt Ebala kalnā un tos apmest ar kaļķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Un tur tev būs altāri uztaisīt Tam Kungam, savam Dievam, altāri no akmeņiem, tev tos nebūs apstrādāt ar dzelzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'No veseliem akmeņiem tev būs uztaisīt Tā Kunga, sava Dieva, altāri un uz tā upurēt dedzināmos upurus Tam Kungam, savam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Tev arī būs upurēt pateicības upurus, un tur ēst un priecāties Tā Kunga, sava Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Un uz šiem akmeņiem tev būs rakstīt visus šīs bauslības vārdus skaidriem rakstiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Un Mozus un tie priesteri, tie Leviti, runāja uz visu Israēli un sacīja: ņem vērā un klausies, Israēl! šai dienā tu esi palicis par Tā Kunga, sava Dieva, tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Tāpēc tev būs klausīt Tā Kunga, sava Dieva, balsij, un darīt Viņa baušļus un likumus, ko es tev šodien pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Un Mozus pavēlēja tiem ļaudīm tai dienā un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Šie lai stāv uz Gerizim kalna, un lai tos ļaudis svētī, kad jūs būsiet gājuši pāri pār Jardāni: Sīmeans un Levis un Jūda un Īsašars un Jāzeps un Benjamins.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Un šie lai stāv uz Ebala kalna un lād: Rūbens, Gads un Ašers un Zebulons un Dans un Naftalis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Tad Levitiem būs sākt un sacīt ar skaņu balsi uz visiem Israēla ļaudīm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Nolādēts, kas taisa kādu izgrieztu vai izlietu tēlu, negantību priekš Tā Kunga, gudru rokas darbu, un kas to slepeni uzceļ! - un visiem ļaudīm būs atbildēt un sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Nolādēts, kas nicina savu tēvu vai savu māti! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Nolādēts, kas pārceļ sava tuvākā ežas(robežas)! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Nolādēts, kas aklu ceļā apmaldina! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Nolādēts, kas tiesu groza piedzīvotājam, bāriņam un atraitnei! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Nolādēts, kas guļ pie sava tēva sievas, jo viņš atsedzis sava tēva apsegu! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Nolādēts, kas guļ pie kāda lopa! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Nolādēts, kas guļ pie savas māsas, sava tēva meitas vai savas mātes meitas! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Nolādēts, kas guļ pie savas sievas mātes! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Nolādēts, kas savu tuvāko slepeni nosit! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Nolādēts, kas ņem dāvanas, izliet nenoziedzīgas asinis! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Nolādēts, kas netur šīs bauslības vārdus, pēc tiem nedarīdams! - un visiem ļaudīm būs sacīt: Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Un kad tu klausīsi Tā Kunga, sava Dieva, balsij un turēsi visus Viņa baušļus, un darīsi, ko es tev šodien pavēlu, tad Tas Kungs, tavs Dievs, tevi augsti cels pār visām zemes tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Un visas šās svētības nāks pār tevi un tev notiks, kad tu Tā Kunga, sava Dieva, balsij klausīsi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Svētīts tu būsi pilsētā un svētīts tu būsi laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Svētīts būs tavas miesas auglis un tavas zemes auglis un tavu lopu auglis un tavu lielo lopu augums un tavu sīko lopu vaisla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Svētīts būs tavs kurvis, un svētīta tava abra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Svētīts tu būsi ieiedams un svētīts tu būsi iziedams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Tas Kungs dos visus tavus ienaidniekus, kas pret tevi ceļas, ka tie top nokauti tavā priekšā; pa vienu ceļu tie pret tevi izies, un pa septiņiem ceļiem tie no tevis bēgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Tas Kungs pavēlēs svētībai, ka tā būs ar tevi tavās klētīs un pie visa, pie kā tu liksi savu roku, un tevi svētīs tai zemē, ko Tas Kungs, tavs Dievs, tev dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Tas Kungs tevi cels Sev par svētu tautu, kā Viņš tev zvērējis, ja tu turēsi Tā Kunga, sava Dieva, baušļus un staigāsi Viņa ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Tad visi ļaudis virs zemes redzēs, ka tu esi nosaukts pēc Tā Kunga vārda, un bīsies no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Un Tas Kungs tevi ļoti vairos ar labumu pie tavas miesas augļiem un pie tavu lopu augļiem un pie tavas zemes augļiem tai zemē, ko Tas Kungs, tavs Dievs, taviem tēviem ir zvērējis, tev dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Tas Kungs tev atvērs Savu labo mantu, debesīs, un dos lietu savā laikā tavai zemei, un svētīs visu tavu rokas darbu, un tu aizdosi daudz tautām, bet tu neaizņemsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Un Tas Kungs tevi darīs par galvu un ne par asti, un tu būsi virsū vien un ne apakšā, ja tu klausīsi Tā Kunga, sava Dieva, baušļiem, ko es tev šodien pavēlu, viņus turēt un darīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Un neatkāpsies no visiem tiem vārdiem, ko es jums šodien pavēlu, ne pa labo, ne pa kreiso roku, nedzīdamies pakaļ citiem dieviem, tiem kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Bet ja tu neklausīsi Tā Kunga, sava Dieva, balsij, un neturēsi un nedarīsi visus Viņa baušļus un Viņa likumus, ko es tev šodien pavēlu, tad visi šie lāsti nāks pār tevi un tev notiks:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Nolādēts tu būsi pilsētā un nolādēts tu būsi laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Nolādēts būs tavs kurvis, un nolādēta tava abra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Nolādēts būs tavas miesas auglis un tavas zemes auglis, tavu lielo lopu augums un tavu sīko lopu vaisla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Nolādēts tu būsi ieiedams un nolādēts tu būsi iziedams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Tas Kungs sūtīs pār tevi lāstu, bailes un briesmas pie ikviena darba, pie kā tu savu roku pieliksi un ko tu darīsi, kamēr tu tapsi izdeldēts, un kamēr tu ātri iesi bojā, tavu ļaunu darbu dēļ, ka tu Mani esi atstājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Tas Kungs tev uzsūtīs mēri, kamēr Viņš tevi izdeldēs no tās zemes, ko tu ej iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Tas Kungs tevi sitīs ar diloni un ar drudzi un ar karstumu un ar karsoni un ar zobenu un ar bula laiku un ar rūsu, kas tev ies pakaļ, kamēr iesi bojā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Un tavas debesis, kas pār tavu galvu, būs kā varš, un tā zeme, kas apakš tevis, būs kā dzelzs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Tas Kungs tavai zemei dos pīšļus un pelnus lietus vietā, no debesīm tie nonāks pār tevi, kamēr būsi izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Tas Kungs tevi nodos, ka tu topi sakauts tavu ienaidnieku priekšā; pa vienu ceļu tu pret viņiem iziesi un pa septiņiem ceļiem tu no viņiem bēgsi, un tapsi izkaisīts pa visām zemes valstīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Un tavas miesas būs par ēdamo visiem debess putniem un zemes zvēriem, un nebūs, kas tos nodzīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Tas Kungs tevi sitīs ar Ēģiptes trumiem un ar tūkumiem un kraupi un ar niezi, no kā tu nevari izdziedēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Tas Kungs tevi sitīs ar trakumu un ar aklību un ar sirds stulbību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Ka tu dienas vidū grābstīsies tā kā akls grābstās tumsā, un tavi ceļi labi neizdosies; bet tu būsi tikai nospaidīts un aplaupīts visu mūžu, un glābēja nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu saderināsies ar sievu, bet cits pie tās gulēs; tu uztaisīsi namu, bet tanī nedzīvosi; tu dēstīsi vīna dārzu, bet viņa augļus nebaudīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Tavs vērsis priekš tavām acīm taps nokauts, un tu no tā neēdīsi; tavs ēzelis taps laupīts priekš tavām acīm un tev netaps atdots; tavi sīkie lopi taps nodoti taviem ienaidniekiem, un glābēja nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tavi dēli un tavas meitas taps nodoti citai tautai, ka tavas acis to redzēs un pēc viņiem ikdienas īgs, bet tavā rokā spēka nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Tavas zemes augļus un visu tavu padomu ēdīs tauta, ko tu nepazīsti, un tu būsi tikai spaidīts un dauzīts visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Un tu paliksi bez prāta, redzēdams, ko tavas acis redzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Tas Kungs tevi sitīs ar nelabiem trumiem pie ceļiem un lieliem, ko nevar dziedināt, no tavas pēdas līdz tavas galvas virsai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Tas Kungs novedīs tevi ar tavu ķēniņu, ko tu pār sevi iecelsi, uz tādu tautu, ko ne tu neesi pazinis, nedz tavi tēvi, un tur tu kalposi citiem dieviem, kokam un akmenim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Un tu būsi par briesmām un par sakāmu vārdu un par apsmieklu starp visām tautām, uz kurieni Tas Kungs tevi aizdzīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Tu iznesīsi daudz sēklas uz tīrumu, bet maz sakrāsi, jo siseņi to apēdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Tu dēstīsi vīna dārzus un tos apstrādāsi, bet vīnu tu nedzersi, nedz salasīsi, jo tārpi to noēdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Tev būs eļļas koki visās tavās robežās, bet ar eļļu tu nesvaidīsies, jo tavs eļļas koks augļus nometīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Tu dzemdināsi dēlus un meitas, bet tie tev nebūs, jo tie aizies cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Visi tavi koki un visi tavi zemes augļi paliks tārpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Tas svešinieks, kas pie tevis mīt, taps paaugstināts pār tevi augsti jo augsti, bet tu tapsi pazemots zemi jo zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Viņš tev aizdos, bet tu viņam neaizdosi, viņš būs par galvu, bet tu būsi par asti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Un visi šie lāsti nāks pār tevi un tevi vajās un tev uzies, kamēr tu tapsi izdeldēts, tāpēc ka tu neesi klausījis Tā Kunga, sava Dieva, balsij, nedz turējis Viņa baušļus un Viņa likumus, ko Viņš tev pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Un tie būs pie tevis par zīmi un par brīnumu, gan pie tava dzimuma mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Tāpēc ka tu Tam Kungam, savam Dievam, neesi kalpojis ar prieku un ar labu sirdi, kad tev bija visas lietas pār pārim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Tu kalposi saviem ienaidniekiem, ko Tas Kungs pret tevi sūtīs, badā un slāpēs un plikumā un visu lietu trūkumā, un Viņš liks dzelzs jūgu uz tavu kaklu, kamēr Viņš tevi izdeldēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Tas Kungs pār tevi atvedīs tautu no tālienes, no pasaules gala, itin kā ērglis skrien, tautu, kuras valodu tu neproti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Briesmīgu tautu, kas vecos necienīs un jaunos nežēlos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Un tā ēdīs tavu lopu augļus un tavas zemes augļus, kamēr tu tapsi izdeldēts; tā tev neatlicinās ne labību, ne vīnu, ne eļļu, ne tavu lielo lopu augumu, ne tavu sīko lopu vaislu, kamēr tā tevi nomaitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Un viņa tevi spaidīs visos tavos vārtos, kamēr sagrūs tavi augstie un stiprie mūri, uz ko tu paļāvies visā savā zemē, un viņa tevi spaidīs visos tavos vārtos un visā tavā zemē, ko Tas Kungs, tavs Dievs, tev ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Un tu ēdīsi savas miesas augļus, savu dēlu un savu meitu miesu, ko Tas Kungs, tavs Dievs, tev devis, to tu ēdīsi tai apstāšanā un tai spaidīšanā, ar ko tavi ienaidnieki tevi spaidīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Un tam vīram, kas starp jums bijis izlutināts un ļoti grezns, tam acs būs skaudīga uz savu brāli un uz to sievu pie savām krūtīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Un uz saviem atlikušiem dēliem, ka viņš nevienam no tiem nedod savu dēlu gaļu, ko viņš ēd, tāpēc ka tam nekas nav atlicis tai apstāšanā un spaidīšanā, ar ko tavs ienaidnieks tevi spaidīs visos tavos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Tai sievai, kas starp jums bija izlutināta un grezna, kas aiz mīkstuma un kāruma nav vīžojusi savu kāju pie zemes spert, tai acs būs skaudīga uz to vīru pie savām krūtīm un uz savu dēlu un uz savu meitu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Par to bērnu, kas tikko izgājis no viņas miesas, un par savu dēlu, ko tā dzemdējusi, jo viņa tos ēdīs slepeni tai briesmīgā trūcībā, tai apstāšanā un spaidīšanā, ar ko tavs ienaidnieks tevi spaidīs tavos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Ja tu neturēsi visus šīs bauslības vārdus un nedarīsi, kas šinī grāmatā rakstīts, nebīdamies Tā Kunga, sava Dieva, godājamo un bīstamo vārdu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Tad Tas Kungs darīs briesmīgas mokas tev un tavam dzimumam, lielas un pastāvīgas mokas un niknas un pastāvīgas sērgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Un Viņš uz tevi griezīs visas Ēģiptes sērgas, no kā tu bīsties, un tās tev pielips.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Un visādas sērgas un visādas mokas, kas šinī bauslības grāmatā nav rakstītas, Tas Kungs tev uzsūtīs, kamēr tu būsi izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Un mazs pulciņš atliks no jums, kas papriekš bijāt savā skaitā kā debess zvaigznes, tāpēc ka tu neesi klausījis Tā Kunga, sava Dieva, balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Un notiksies, itin kā Tas Kungs par jums ir priecājies, jums labu darīt un jūs vairot, tā Tas Kungs par jums priecāsies, jūs nomaitāt un jūs izdeldēt, un jūs tapsiet izpostīti no tās zemes virsas, ko ejat iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Un Tas Kungs tevi izkaisīs starp visām pasaules tautām, no viena pasaules gala līdz otram pasaules galam, un tur tu kalposi citiem dieviem, ko ne tu neesi pazinis, ne tavi tēvi, kokam un akmenim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Un starp šīm tautām tev nebūs miera un tavai kājai nebūs dusas, jo Tas Kungs tev tur dos drebošu sirdi un noīgušas acis un noskumušu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Un tava dzīvība tev karāsies (kā pie pavediena) un tu baiļosies naktīm dienām un necerēsi dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Rītos tu sacīsi: kaut jau būtu vakars! Un vakaros tu sacīsi: kaut jau būtu rīts! No sirds izbailēm, ar ko tu baiļosies, un no tām lietām, ko tavas acis redzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Un Tas Kungs ar laivām tevi vedīs atpakaļ uz Ēģiptes zemi, to ceļu, par ko es tev esmu sacījis: tu viņu vairs neredzēsi; un tur jūs gribēsiet pārdoties saviem ienaidniekiem par kalpiem un par kalponēm, bet tur pircēja nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Šie ir tās derības vārdi, ko Tas Kungs Mozum pavēlējis ar Israēla bērniem derēt Moaba zemē, pāri par to derību, ko Viņš ar tiem bija derējis Horebā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Un Mozus saaicināja visu Israēli un uz tiem sacīja: jūs visu esat redzējuši, ko Tas Kungs Ēģiptes zemē jūsu priekšā darījis pie Faraona un pie viņa kalpiem un pie visas viņa zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Visas tās lielās kārdināšanas, ko tavas acis redzējušas, tās lielās zīmes un tos brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Bet Tas Kungs jums nav sirdi devis, kas saprot, nedz acis, kas redz, nedz ausis, kas dzird, līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Un četrdesmit gadus Es jums esmu licis pa tuksnesi staigāt; jūsu drēbes mugurā jums nav nodilušas, un tavas kurpes kājās tev nav noplīsušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Maizi jūs neesat ēduši, nedz vīnu nedz stipru dzērienu dzēruši, lai jūs atzītu, ka Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Kad nu jūs atnācāt uz šo vietu, tad Sihons, Hešbonas ķēniņš, un Ogs, Basanas ķēniņš, izgāja mums pretī karā un mēs tos esam sakāvuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Un viņu zemi uzņēmuši un to devuši par daļu Rūbeniešiem un Gadiešiem un Manasus pusciltij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Tad nu turiet šās derības vārdus un dariet tos, ka jums izdodas pie visa, ko jūs darīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Jūs visi šodien stāvat Tā Kunga, sava Dieva, priekšā, jūsu cilts virsnieki un jūsu vecaji un jūsu priekšnieki, visi Israēla vīri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Jūsu bērniņi, jūsu sievas un tavs piedzīvotājs, kas ir tavā lēģerī, no tava malkas cirtēja līdz tavam ūdens smēlējam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Ka tu iedotos Tā Kunga, sava Dieva, derībā un tai zvērestā, ko Tas Kungs, tavs Dievs, šodien ar tevi dara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Ka Viņš tevi šodien ieceltu sev par tautu un tev būtu par Dievu, kā Viņš tev runājis un kā Viņš zvērējis taviem tēviem, Ābrahāmam, Īzakam un Jēkabam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Un šo derību un šo zvērestu es daru nevien ar jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Bet kā ar jums, kas šodien ar mums še stāvat Tā Kunga, mūsu Dieva, priekšā, tāpat ar tiem, kas šodien še pie mums nestāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Jo jūs zināt, ka mēs esam dzīvojuši Ēģiptes zemē un ka esam gājuši vidū caur tām tautām, kur jūs esat gājuši cauri.-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Un jūs esat redzējuši viņu negantības un elkus no koka un akmens, sudraba un zelta, kas tiem bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Lai nav jūsu starpā ne vīrs ne sieva, ne saime ne cilts, kas šodien savu sirdi būtu nogriezis no Tā Kunga, mūsu Dieva, un ietu kalpot šo tautu dieviem; lai nav jūsu starpā nevienas saknes, kas nes nāvīgas zāles un vērmeles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Un lai nenotiek, ka šos lāstu vārdus dzirdot kāds savā sirdī svētījās un saka: man labi klāsies, jebšu es staigāšu pēc sava cieta sirds prāta. Tā iet bojā gan tas, kas dzirdīts, gan tas, kas iztvīcis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Tas Kungs negribēs par tādu apžēloties, bet tad kūpēs Tā Kunga bardzība un karstums par tādu vīru, un visi lāsti, kas šinī grāmatā rakstīti, gulēs uz tā, un Tas Kungs izdeldēs viņa vārdu no pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Un Tas Kungs to izraudzīs postam no visām Israēla ciltīm pēc visiem derības lāstiem, kas rakstīti šinī bauslības grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Tad tie pēcnākamie dzimumi sacīs, jūsu bērni, kas pēc jums celsies, un tas svešais, kas atnāks no tālas zemes, redzēdami tās zemes mocības un viņas sērgas, ar ko Tas Kungs tai liks sirgt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Ka visa viņu zeme ir sērs un degoša sāls; tur nesēj, tur neaug, tur zāle nezeļ, tā kā Sodoma ir izdeldēta un Gomora, Ādama un Ceboīma, ko Tas Kungs izdeldējis Savā dusmībā un bardzībā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Tad visas tautas sacīs: kāpēc Tas Kungs šai zemei tā ir darījis? Kas tās par lielām bargām dusmām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Tad sacīs: tāpēc ka tie ir atstājuši Tā Kunga, savu tēvu Dieva, derību, ko Viņš ar tiem bija derējis, kad tos izveda no Ēģiptes zemes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Un ir nogājuši un citiem dieviem kalpojuši un viņus pielūguši, tādus dievus, ko tie nepazina un ko Viņš tiem nebija devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Tāpēc Tā Kunga bardzība ir iedegusies pret šo zemi, vest pār viņu visus šos lāstus, kas šinī grāmatā rakstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Un Tas Kungs tos no viņu zemes ir izstūmis ar dusmību, ar bardzību un ar lielu īgnumu, un tos ir izmetis uz citu zemi, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Tā Kunga, mūsu Dieva, noslēpumi ir darīti zināmi mums un mūsu bērniem mūžam, ka mums būs darīt visus šīs bauslības vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Kad nu viss tas nāks pār tevi, vai šī svētība, vai šie lāsti, ko es tev esmu licis priekšā, un kad tu to ņemsi pie sirds starp tām tautām, uz kurieni Tas Kungs, tavs Dievs, tevi izdzinis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Un tu atgriezīsies pie Tā Kunga, sava Dieva, un klausīsi Viņa balsij, kā es tev šodien pavēlu, tu un tavi bērni, no visas savas sirds un no visas savas dvēseles:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Tad Tas Kungs, tavs Dievs, nogriezīs tavu cietumu un apžēlosies par tevi, un tevi atkal salasīs no visām tautām, uz kurieni Tas Kungs, tavs Dievs, tevi izkaisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Jebšu tavi izdzītie arī būtu pašā pasaules galā, tad tomēr Tas Kungs, tavs Dievs, no turienes tevi sapulcēs un tevi ņems no turienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Un Tas Kungs, tavs Dievs, tevi vedīs uz to zemi, ko tavi tēvi turējuši, un tu to iemantosi, un Viņš tev darīs labu, un tevi vairos vairāk nekā tavus tēvus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Un Tas Kungs, tavs Dievs, apgraizīs tavu sirdi un tava dzimuma sirdi, ka tu To Kungu, savu Dievu, mīlēsi no visas savas sirds un no visas savas dvēseles, lai tu dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Un Tas Kungs, tavs Dievs, liks visus šos lāstus uz taviem ienaidniekiem un uz taviem skauģiem, kas tevi vajā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Bet tu atkal klausīsi Tā Kunga balsij un darīsi visus Viņa baušļus, ko es tev šodien pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Un Tas Kungs, tavs Dievs, tevi bagāti svētīs visā tavā roku darbā, pie tavas miesas augļiem un pie tavu lopu augļiem un pie tavas zemes augļiem, ka tev labi klājās; jo Tas Kungs atkal par tevi priecāsies, tev par labu, itin kā Viņš priecājies par taviem tēviem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Kad tu klausīsi Tā Kunga, sava Dieva, balsij, un turēsi Viņa baušļus un Viņa likumus, kas rakstīti šai bauslības grāmatā, kad tu atgriezīsies pie Tā Kunga, sava Dieva, ar visu savu sirdi un ar visu savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Jo šis bauslis, ko es tev šodien pavēlu, tev nav ne par augstu nedz par tālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Tas nav debesīs, ka būtu jāsaka: kas mums kāps debesīs, to mums dabūt un to dot mums dzirdēt, ka to darām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Tas arī nav viņpus jūras, ka būtu jāsaka: kas mums pārcelsies viņpus jūras, to mums dabūt un to mums dot dzirdēt, ka to darām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Jo tas vārds ir ļoti tuvu pie tevis, tavā mutē un tavā sirdī, ka tu to dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Redzi, šodien es tev esmu licis priekšā dzīvību un labumu, nāvi un ļaunumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Es tev šodien pavēlu To Kungu, savu Dievu, mīļot, Viņa ceļos staigāt un turēt Viņa baušļus, likumus un tiesas, ka tu dzīvo un vairojies, un Tas Kungs, tavs Dievs, tevi svētī tai zemē, ko tu ej iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Bet ja tava sirds griezīsies un neklausīs un tu liksies pavesties, pielūgt citus dievus un tiem kalpot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Tad es jums šodien pasludināju, ka jūs pavisam iesiet bojā; jūs ilgi nedzīvosiet tai zemē, ko iemantot tu tagad ej pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Es šodien piesaucu debesis un zemi par lieciniekiem pār jums; es jums esmu licis priekšā dzīvību un nāvi, svētību un lāstu; tad nu izvēlies dzīvību, ka tu dzīvo, tu un tavs dzimums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Mīļodams To Kungu, savu Dievu, klausīdams Viņa balsij un Viņam pieķerdamies, jo Viņš ir tava dzīvība un tavu dienu pagarinātājs, ka tu palieci tai zemē, ko Tas Kungs zvērējis taviem tēviem Ābrahāmam, Īzakam un Jēkabam, viņiem dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Tad Mozus nogāja un runāja šos vārdus uz visu Israēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Un uz tiem sacīja: šodien es esmu simts un divdesmit gadus vecs; es nevarēšu vairs ne iziet ne ieiet, un Tas Kungs uz mani sacījis: tev nebūs iet pāri pār šo Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Tas Kungs, tavs Dievs, Tas ies pats tavā priekšā pāri, Tas izdeldēs šīs tautas tavā priekšā, ka tu tās iemanto; Jozuas, tas ies pāri tavā priekšā, kā Tas Kungs runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Un Tas Kungs viņiem darīs, kā Viņš darījis Sihonam un Ogam, Amoriešu ķēniņiem, un viņu zemei, ko Viņš izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Kad nu Tas Kungs tos nodos jūsu priekšā, tad jums tiem būs darīt pēc visām pavēlēm, ko es jums esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Esat stipri un turat drošu prātu, nebīstaties un nebaiļojaties priekš viņiem, jo Tas Kungs, tavs Dievs, Tas tev iet līdz; Viņš tevi neatstās, nedz tevi pametīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Un Mozus aicināja Jozua un sacīja uz viņu visa Israēla priekšā: esi stiprs un turi drošu prātu, jo tu ieiesi ar šiem ļaudīm tai zemē, ko Tas Kungs viņu tēviem ir zvērējis, viņiem dot, un tev to būs viņiem izdalīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Tas Kungs, Tas iet tavā priekšā, Viņš būs ar tevi, Viņš tevi neatstās, nedz tevi pametīs, nebīsties un nebaiļojies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Un Mozus uzrakstīja to bauslību un to deva tiem priesteriem, Levja dēliem, kas nesa Tā Kunga derības šķirstu, un visiem Israēla vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Un Mozus tiem pavēlēja un sacīja: ik septītā gadā, atlaišanas gada laikā, lieveņu svētkos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Kad viss Israēls nāks rādīties Tā Kunga, tava Dieva, priekšā, tai vietā, ko Viņš izredzēs, tad tev šo bauslību būs priekšā lasīt visam Israēlim viņu ausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Sapulcini tos ļaudis, vīrus un sievas un bērniņus un savus piedzīvotājus, kas tavos vārtos, lai tie dzird un mācās un bīstas To Kungu, jūsu Dievu, un tur un dara visus šīs bauslības vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Un lai viņu bērni, kas to nezina, dzird un mācās bīties To Kungu, jūsu Dievu, visu to laiku, kamēr jūs dzīvosiet tai zemē, ko iemantot jūs ejat pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Un Tas Kungs sacīja uz Mozu: redzi, tavs laiks ir klāt, ka jāmirst; aicini Jozua, un ejat saiešanas teltī, lai Es viņam pavēlu. Tad Mozus un Jozuas gāja un nostājās saiešanas teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Tad Tas Kungs tai teltī parādījās padebeša stabā, un tas padebeša stabs stāvēja saiešanas telts durvīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Un Tas Kungs sacīja uz Mozu: redzi, tu dusēsi pie saviem tēviem, un šie ļaudis celsies un maukos pakaļ tās zemes svešiem dieviem, kur tie nāks dzīvot, un atstās Mani un atmetīs Manu derību, ko Es ar tiem esmu derējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Tai dienā Mana bardzība pret tiem iedegsies, un Es tos atstāšu un paslēpšu Savu vaigu no viņiem, ka tie top aprīti, un daudz ļaunuma un daudz bēdu viņiem uzies, ka tie tai dienā sacīs: vai šis ļaunums man nav uzgājis tāpēc, ka mans Dievs nav mūsu vidū?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Bet Es paslēpšu Savu vaigu tai dienā visa ļaunuma dēļ, ko tie ir darījuši, nogriezdamies pie citiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Un nu uzrakstiet sev šo dziesmu un māci to Israēla bērniem un ieliec to viņu mutē, ka šī dziesma Man ir par liecību pret Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Jo Es tos ievedīšu tai zemē, ko esmu zvērējis viņu tēviem, kur piens un medus tek, un kad tie ēdīs un būs paēduši un paliks trekni, tad tie nogriezīsies pie citiem dieviem un tiem kalpos un Mani apkaitinās un atmetīs Manu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Un kad daudz ļaunuma un daudz bēdu tiem uzies, tad šī dziesma tiem atbildēs un būs par liecību, jo tā netaps aizmirsta viņu dzimuma mutē. Jo Es zinu viņu domas, kas tiem jau šodien ir, pirms Es tos esmu ievedis tai zemē, ko tiem esmu zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Tad Mozus uzrakstīja šo dziesmu tai dienā un to mācīja Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Un Viņš pavēlēja Jozuam, Nuna dēlam, un sacīja: esi stiprs un turi drošu prātu, jo tu ievedīsi Israēla bērnus tai zemē, ko Es viņiem esmu zvērējis, un Es būšu ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Un kad Mozus bija pabeidzis līdz pat galam sarakstīt šās bauslības vārdus grāmatā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Tad Mozus pavēlēja tiem Levitiem, kas Tā Kunga derības šķirstu nesa, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Ņemiet šo bauslības grāmatu un noliekat to blakām Tā Kunga, sava Dieva, derības šķirstam, lai viņa tur ir par liecību pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Jo es pazīstu tavu nepaklausību un tavu stūrgalvību. Redzi, šodien kamēr es vēl esmu dzīvs jūsu vidū, jūs esat neklausīgi pret To Kungu, - cik vairāk, kad es būšu nomiris!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Sapulcējiet pie manis visus savus cilšu vecajus un savus priekšniekus, lai es runāju šos vārdus priekš viņu ausīm un pret tiem piesaucu par lieciniekiem debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Jo es zinu, ka pēc manas nāves jūs visai(pilnīgi) apgrēkosities un atkāpsities no tā ceļa, ko es jums esmu pavēlējis; tad jums tas ļaunums uzies nākamā laikā, kad jūs darīsiet, kas ļauns Tā Kunga acīs, viņu apkaitinādami ar savu rokas darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Tad Mozus runāja priekš visas Israēla draudzes ausīm šīs dziesmas vārdus līdz pat galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Ņemiet vērā, debesis, jo es runāšu, un zeme lai dzird manas mutes vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Mana mācība lai līst kā lietus, un mana valoda lai pil kā rasa, kā lietutiņš uz zaļumu, un kā lāses uz zāli');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Jo es slavēšu Tā Kunga vārdu; dodiet godu mūsu Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Viņš ir tas akmens kalns, Viņa darbs ir pilnīgs, jo visi Viņa ceļi ir tiesa; Dievs ir patiesība un bez viltus, Viņš ir taisns un patiesīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Pret Viņu tie apgrēkojušies; tie nav Viņa bērni, bet sev par kaunu, nikna un netikla cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Vai jūs Tam Kungam tā atmaksājiet, tu ģeķīga un negudra tauta? Vai Viņš nav tavs tēvs, kam tu piederi, kas tevi radījis un sataisījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Piemini tās senās dienas, ņemiet vērā tos gadus no radu radiem, vaicā savam tēvam, tas tev to stāstīs, saviem vecajiem, tie tev to sacīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Kad tas visuaugstais tautām deva viņu daļas un šķīra cilvēku bērnus, tad Viņš tautām cēla robežas pēc Israēla bērnu skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Jo Tā Kunga daļa ir Viņa ļaudis, Jēkabs ir Viņa īpaša mantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Viņš to atrada tuksneša zemē, briesmīgā kaukšanas postažā, Viņš to pasargāja, kā Savu acs raugu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Kā ērglis savu perēkli vedina un lidinājās pār saviem bērniem, izplāta savus spārnus un tos uzņem un tos nes uz saviem spārniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Tā Tas Kungs vien tos vadīja, un sveša dieva nebija ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Viņš to spēcīgi vadīja pār zemes augstumiem, to ēdināja ar tīruma augļiem un to zīdināja ar medu no klints un ar eļļu no cieta akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Sviestu no govīm, un pienu no avīm, līdz ar jēru taukiem, un Basanas aunus un āžus ar taukām īkstīm, tīrus treknus kviešus un vīnogu sulu, - vīna ogu asinis tu dzēri, vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Kad nu Ješuruns (t.i. Israēls) palika trekns, tad viņš spēra, - tu paliki trekns un tukls un resns, - tad viņš atstāja Dievu, savu Radītāju, un nicināja savas pestīšanas akmens kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Tie Viņu tirināja caur svešiem (dieviem), caur negantībām tie Viņu apkaitināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Tie upurēja jodiem, nedievam, dieviem, ko tie nepazina, jauniem, kas nesen cēlušies, ko jūsu tēvi nav bijušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'To akmens kalnu, kas tevi dzemdinājis, tu atstāji, un aizmirsi Dievu, kas tevi radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Kad Tas Kungs to redzēja, tad Viņš atmeta īgnumā Savus dēlus un Savas meitas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Un sacīja: Es paslēpšu Savu vaigu no viņiem, Es redzēšu, kā tiem pēc klāsies, jo tie ir netikla tauta, bērni bez ticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Tie Mani tirinājuši caur nedievu, tie Mani kaitinājuši caur savām nelietībām; tad arī Es viņus tirināšu caur netautu, caur ģeķīgu tautu Es tos kaitināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Jo uguns ir iededzies no Manām dusmām un degs līdz visdziļākai ellei un aprīs zemi ar viņas augļiem un iededzinās kalnu pamatus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Es sakrāšu pār tiem ļaunumus, Savas bultas Es uz tiem izšaušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Badā tiem būs izģinst, mēris un rūgtas sērgas tos aprīs, Es sūtīšu zvēru zobus pret tiem un pīšļos līdēju čūsku dzeloņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Ārā tos postīs zobens un iekšā briesmas, kā jaunekļus, tā jaunavas, zīdāmos līdz ar sirmgalvjiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Es sacītu: Es tos izputināšu, Es izdeldēšu viņu piemiņu starp cilvēkiem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Ja Es nebītos, ka viņu ienaidnieki Mani nesadusmo, ka viņu spaidītāji nesaprazdami nesaka: mūsu roka bija augsta, un ne Tas Kungs visu to darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Jo tie ir ļaudis bez padoma, un saprašanas tiem nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Ak kaut viņi būtu gudri to saprast, un ņemtu vērā, kā tiem pēcgalā klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kā viens var tūkstošus vajāt un kā divi var dzenāt desmit tūkstošus? Vai ne tāpēc, ka viņu akmens kalns tos ir pārdevis, un Tas Kungs tos ir nodevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Jo viņu akmens kalns nav kā mūsu akmens kalns, par to mūsu ienaidnieki paši ir spriedēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Jo viņu vīna koks ir no Sodomas vīna koka un no Gomoras laukiem; viņu vīna ķekari ir žults ķekari, tiem ir rūgtas ogas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Viņu vīns ir pūķu siekalas un briesmīga odžu žults.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Vai tas nav pie Manis paslēpts, aizzieģelēts Manā padomā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Man pieder atriebšana un atmaksāšana, uz to laiku, kad viņu kāja slīdēs; jo viņu posta diena ir tuvu, un viņu liktenis nāk steigšus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Jo Tas Kungs tiesās Savus ļaudis un par Saviem kalpiem Viņš apžēlosies, kad Viņš redzēs, ka spēks ir izzudis, ka beigti mazs un liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Tad Viņš sacīs: Kur ir viņu dievi, tas akmens kalns, uz ko tie cerēja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Viņu upura taukus tie ēda, viņu dzeramā upura vīnu tie dzēra, - lai viņi ceļas un jums palīdz, ka jums ir patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Raugāt nu, ka Es, Es tas esmu, un neviena nav, kā vien Es! Es nonāvēju un daru dzīvu, Es ievainoju un dziedināju, un glābēja nav no Manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Jo Es paceļu pret debesīm Savu roku un saku: tik tiešām, kā Es dzīvoju mūžīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Kad Es trīšu Sava zobena zibeni un Mana roka izstiepsies uz sodību, tad Es atkal atriebšos pie Saviem pretiniekiem un atmaksāšu Saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Es dzirdināšu Savas bultas ar asinīm, - un Mans zobens ēdīs miesas, - ar nokauto un gūstīto asinīm, no ienaidnieku varenām galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Gavilējiet, tautas, par Viņa ļaudīm, - jo Viņš atriebj Savu kalpu asinis un atriebjas pie Saviem pretiniekiem un apžēlojās par Savu zemi un par Saviem ļaudīm. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Un Mozus nāca un runāja visus šīs dziesmas vārdus to ļaužu ausīs, viņš un Jozuas, Nuna dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Kad nu Mozus bija beidzis runāt visus šos vārdus uz visu Israēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Tad viņš uz tiem sacīja: ņemiet pie sirds visus šos vārdus, ko es šodien jums apliecināju; tos jums būs pavēlēt saviem bērniem, ka tie tur un dara visus šīs bauslības vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Jo tas jums nav tukšs vārds, bet ir jūsu dzīvība, un caur šo vārdu jūs ilgi dzīvosiet tai zemē, ko iemantot jūs ejat pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Un Tas Kungs runāja uz Mozu tai pašā dienā sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '“Kāp uz šo Abarim kalnu, tas ir Nebus kalns, Moaba zemē pret Jēriku, un skaties Kanaāna zemi, ko Es Israēla bērniem došu iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Un tev būs mirt uz tā kalna, kur tu uzkāpsi, un tapt piepulcinātam pie saviem ļaudīm, kā Ārons, tavs brālis, nomira uz Hora kalna un tapa piepulcināts pie saviem ļaudīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Tādēļ ka jūs Israēla bērnu vidū esat noziegušies pret Mani pie strīdus ūdens Kādešā, Cin tuksnesī, tāpēc ka jūs Mani neesat svētījuši Israēla bērnu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Jo tu redzēsi to zemi savā priekšā, bet tur tu nenonāksi, tai zemē, ko Es došu Israēla bērniem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Šī ir tā svētība, ar ko Mozus, tas Dieva vīrs, priekš savas miršanas Israēla bērnus svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Un viņš sacīja: “Tas Kungs ir nācis no Sinaī un tiem uzlēcis no Seīra, Viņš atspīdējis no Pārana kalniem un nācis no daudz tūkstošiem svētiem; no Viņa labās rokas tiem bauslības uguns (izgājis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Kā Viņš tos ļaudis mīļo! Visi Tavi svētie ir Tavā rokā, tie nosēžas pie Tavām kājām un ņem no Taviem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mozus mums ir pavēlējis to bauslību, Jēkaba draudzes mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Viņš palika par ķēniņu Ješurunam (Israēlim), kad ļaužu virsnieki sapulcējās līdz ar Israēla ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Rūbens lai dzīvo un lai nemirst, un viņa pulks lai ir skaitāms.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Un šo viņš sacīja par Jūdu: “Klausi, Kungs, Jūda balsi, un vedi to pie viņa ļaudīm. Ar savām rokām viņš par tiem karo, un Tu esi viņam palīgs pret viņa ienaidniekiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Un par Levi viņš sacīja: “Tavs tumim un urim (tiesa un gaisma) lai paliek pie Tava svētā vīra, ko Tu esi kārdinājis Masā, ar ko Tu strīdējies pie strīdus ūdeni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Kas par savu tēvu un par savu māti sacīja: es viņu neredzu, un kas savus brāļus neatzina un savus dēlus nepazina, jo tie sargāja Tavu vārdu un turēja Tavu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Tie Jēkabam mācīs Tavas tiesas un Israēlim Tavu bauslību; tie liks kvēpināmās zāles priekš Tavām nāsīm un dedzināmos upurus uz Tavu altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Svētī, Kungs, viņa spēku, un lai viņa roku darbs Tev patīk; sasit gurnus tiem, kas pret to ceļas, un kas viņu ienīst, ka tie nevar celties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Un par Benjaminu viņš sacīja: “Tā Kunga mīļais dzīvos droši pie Viņa, Viņš to apsegs ikdienas, un tas mitīs starp Viņa kamiešiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Un par Jāzepu viņš sacīja: “Viņa zeme lai ir Tā Kunga svētīta ar debess labumu, ar rasu un ar ūdeņiem, kas apakšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Ar vislabākiem saules augļiem, ar vislabākiem mēnešu augļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Un ar to visdārgāko no vecu veciem kalniem, un ar to vislabāko no mūžīgiem pakalniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Un ar vislabākiem zemes un viņas pilnuma augļiem; un laipnība no tā, kas ērkšķu krūmā mita, lai nāk uz Jāzepa galvu un uz galvu savu brāļu izredzētam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Viņa gods ir kā vēršu pirmdzimtam, un viņa ragi kā sūbra ragi; ar tiem viņš sabadīs visas tautas līdz zemes galiem; šie ir Efraīma lielie pulki un šie ir Manasus tūkstoši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Un par Zebulonu viņš sacīja: “Priecājies, Zebulon, par savu gājumu, un Īsašar, par saviem dzīvokļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Tie aicinās tos ļaudis kalnā, tur tie upurēs taisnības upurus, jo tie zīdīs jūras bagātību un smiltīs paslēptas mantas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Un par Gadu viņš sacīja: “Svētīts lai ir, kas Gadu izplata, viņš guļ kā lauva un saplosa gan elkoni, gan galvas virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Viņš izredzējās pirmaju tiesu, jo tur vadoņa daļa bija glabāta; viņš piestājās ļaužu virsniekiem un darīja Tā Kunga taisnību un Viņa tiesas līdz ar Israēli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Un par Danu viņš sacīja: “Dans ir jauns lauva, viņš izlēks no Basanas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Un par Naftali viņš sacīja: “Naftalim ir žēlastības diezgan, un Tā Kunga svētības papilnam; pret vakariem un pret dienvidiem būs viņa daļa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Un par Ašeru viņš sacīja: “Ašers lai ir svētīts pār tiem dēliem, lai tas ir apžēlots savu brāļu vidū un kas savām kājām min eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Dzelzs un varš būs tavs stiprums, un visu mūžu lai tev ir miers.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, '“Neviens nav kā Ješuruna (Israēla) Dievs, Viņš brauc pa debesīm tev palīgā un Savā godībā pa padebešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Tas mūžīgais Dievs ir patvērums, un virs zemes valda mūžīgas rokas, un Viņš aizdzen ienaidnieku tavā priekšā, un saka: izdeldi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Israēls tad dzīvos droši par sevi; Jēkaba acs skatās uz labības un vīna zemi, un viņa debess pilina rasu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Svētīgs tu esi, Israēl, - kas ir tāds kā tu, Tā Kunga atpestītā tauta? Viņš ir tava palīga bruņas un tavas godības zobens; un tavi ienaidnieki tev pielabināsies un tu staigāsi pa viņu augstumiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Tad Mozus uzkāpa no Moaba klajumiem uz Nebus kalnu, Pizgas virsgalu, kas ir pret Jēriku, un Tas Kungs viņam rādīja visu Gileādas zemi līdz Danam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Un visu Naftalus un Efraīma un Manasus zemi un visu Jūda zemi līdz pat jūrai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Un to dienvidu(Negebas) pusi un to klajumu, to palmu pilsētu, Jērikus leju, līdz Coārai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Un Tas Kungs sacīja uz viņu: “Šī ir tā zeme, ko Es Ābrahāmam, Īzakam un Jēkabam esmu zvērējis sacīdams: tavam dzimumam Es to došu; Es tev to esmu licis redzēt ar tavām acīm, bet tev nebūs uz turieni iet pāri.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Tā Mozus, Tā Kunga kalps, nomira Moaba zemē pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Un Viņš to apraka ielejā, Moaba zemē, Bet Peoram pretī, un neviens viņa kapu nezin līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Un Mozus bija simts un divdesmit gadus vecs, kad viņš nomira. Viņa acis nebija palikušas tumšas un viņa spēks nebija zudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Un Israēla bērni apraudāja Mozu Moaba klajumos trīsdesmit dienas, tad tās gaudu un raudu dienas par Mozu beidzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Un Jozuas, Nuna dēls, bija gudrības gara pilns, jo Mozus uz viņu bija uzlicis savas rokas, un Israēla bērni viņam klausīja un darīja, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Un tāds pravietis iekš Israēla vairs necēlās, kā Mozus, ko Tas Kungs būtu atzinis vaigu vaigā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Pēc visām tām zīmēm un tiem brīnumiem, ko darīt Tas Kungs viņu bija sūtījis uz Ēģiptes zemi pie Faraona un pie visiem viņa kalpiem un pie visas viņa zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Un pēc tās stiprās rokas un pēc visiem tiem lieliem un bijājamiem darbiem, ko Mozus darīja priekš visa Israēla acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Un notikās pēc Mozus, Tā Kunga kalpa, miršanas, tad Tas Kungs runāja uz Jozua, Nuna dēlu, Mozus sulaini, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mans kalps Mozus ir nomiris; tad nu celies, ej pāri pār šo Jardāni, tu un visi šie ļaudis, uz to zemi, ko Es Israēla bērniem dodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Visas vietas, kur jūs savu kāju spersiet, Es jums esmu devis, tā kā Es uz Mozu esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'No tuksneša un no šīs Lībanus līdz tai lielai upei, Eifrat upei, visa Hetiešu zeme līdz tai lielai jūrai pret saules noiešanu lai ir jūsu robežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Neviens tavā priekšā nepastāvēs visu tavu mūžu; tā kā Es esmu bijis ar Mozu, tāpat Es būšu ar tevi; Es tevi neatstāšu, nedz pametīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Esi stiprs un turi drošu prātu, jo tev šiem ļaudīm būs izdalīt to zemi par iemantojamu tiesu, ko Es viņu tēviem esmu zvērējis dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Esi tikai stiprs un turi drošu prātu, ka tu turies un dari pēc visas bauslības, ko Mozus, Mans kalps, tev ir pavēlējis; neatkāpies no tās ne pa labo ne pa kreiso roku, ka tev labi izdodas visur, kur tu iesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Lai šī bauslības grāmata neatstājās no tavas mutes, bet apdomā to dienām naktīm, ka tu vari turēt un darīt visu, kas tanī stāv rakstīts: tad tavi ceļi labi izdosies un tad tev laimēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Vai Es tev neesmu pavēlējis: esi stiprs un turi drošu prātu? Nebēdājies un nebaiļojies, jo Tas Kungs, tavs Dievs, ir ar tevi visur, kurp tu iesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Tad Jozuas pavēlēja tiem ļaužu virsniekiem un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Ejat pa lēģeri un pavēliet tiem ļaudīm sacīdami: sataisiet sev ceļamaizi, jo pēc trim dienām jūs iesiet pār šo Jardāni, ka jūs ieejat, iemantot to zemi, ko Tas Kungs, jūsu Dievs, jums dod par īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Un Jozuas runāja uz Rūbeniešiem un Gadiešiem un uz Manasus puscilti un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Pieminiet to vārdu, ko Mozus, Tā Kunga kalps, jums ir pavēlējis sacīdams: Tas Kungs, jūsu Dievs, jums dod dusēšanu un jums dod šo zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Jūsu sievas, jūsu bērniņi, jūsu ganāmie pulki lai paliek tai zemē, ko Mozus šaipus Jardānes jums devis, bet jūs ejat apbruņoti savu brāļu priekšā, visi spēcīgie un stiprie vīri, un palīdziet viņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Tiekams Tas Kungs jūsu brāļiem dod dusēšanu tā kā jums, un arī viņi to zemi iemanto, ko Tas Kungs, jūsu Dievs, viņiem dod. Tad jūs griezīsities atpakaļ uz savu pašu zemi un dabūsiet to, ko Mozus, Tā Kunga kalps, jums ir devis šaipus Jardānes pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Tad tie Jozuam atbildēja sacīdami: visu, ko tu mums esi pavēlējis, to mēs darīsim, un visur, kurp tu mūs sūtīsi, mēs iesim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Tā kā mēs visās lietās esam klausījuši Mozum, tā tev klausīsim, lai tikai Tas Kungs, tavs Dievs, ir ar tevi tā kā Viņš bijis ar Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Ikvienam, kas tavai mutei turēsies pretī un taviem vārdiem neklausīs iekš visa, ko tu viņam pavēlēsi, tam būs mirt. Esi tikai stiprs un turi drošu prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Un Jozuas, Nuna dēls, sūtīja slepeni divus izlūkus no Sitimas sacīdams: ejat, izlūkojiet to zemi un Jēriku. Un tie gāja un nāca kādas sievas namā, tā bija mauka, tai vārds bija Rahaba, un tie tur gulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Un Jērikus ķēniņam tapa sacīts: redzi, šinī naktī vīri nākuši no Israēla bērniem, to zemi izlūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Tad Jērikus ķēniņš sūtīja pie Rahabas un sacīja: dod šurp tos vīrus, kas pie tevis nākuši tavā namā, jo tie ir nākuši, visu šo zemi izlūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Bet tā sieva ņēma tos divus vīrus un tos paslēpa un sacīja tā: tie vīri gan pie manis bija nākuši, bet es nezināju, no kurienes tie bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Un kad vārti bija jāaizslēdz, kad metās tumšs, tad tie vīri izgāja. Es nezinu, kurp tie vīri gājuši; dzenaties tiem steigšus pakaļ, tad jūs tos panāksiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Bet viņa tiem bija likusi uz jumtu uzkāpt un tos bija paslēpusi apakš linājiem, ko uz jumta bija izklājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Un tie vīri tiem dzinās pakaļ pa Jardānes ceļu līdz tai pārceļamai vietai, un vārti tapa aizslēgti pēc tam, kad bija izgājuši, kas tiem dzinās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Un pirms tie apgūlās, viņa pie tiem uzkāpa uz jumtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Un sacīja uz tiem vīriem: es zinu, ka Tas Kungs jums šo zemi devis un ka bailes no jums mums uzkritušas, un ka visi zemes iedzīvotāji jūsu priekšā izbijušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Jo mēs esam dzirdējuši, kā Tas Kungs licis izsīkt niedru jūras ūdeņiem jūsu priekšā, jums no Ēģiptes zemes izejot, un ko jūs esat darījuši viņpus Jardānes tiem diviem Amoriešu ķēniņiem, Sihonam un Ogam, ko jūs esat izdeldējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Un to dzirdot mūsu sirds palikusi bailīga, un nav vairs drošības nevienam pret jums; jo Tas Kungs, jūsu Dievs, Viņš ir Dievs augšā debesīs un apakšā virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Nu tad zvērējiet man jel pie Tā Kunga, tāpēc ka es žēlastību pie jums esmu darījusi, ka arī jūs darīsiet žēlastību pie mana tēva nama, un dodat man kādu ticamu zīmi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Ka jūs atstāsiet dzīvus manu tēvu, manu māti un manus brāļus un manas māsas ar visu, kas tiem pieder, un ka jūs mūsu dvēseles izglābsiet no nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Tad tie vīri uz to sacīja: ja mēs nedarīsim žēlastību un uzticību pie tevis, kad Tas Kungs mums šo zemi dos, tad lai mirst mūsu dvēsele jūsu vietā, ja tik jūs šo mūsu lietu nedarīsiet zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Tad viņa tos ar virvi nolaida pa logu, jo viņas nams bija pie pilsētas mūra un viņa dzīvoja pie tā mūra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Un viņa uz tiem sacīja: ejat kalnos, ka tie jūs nesastop, kas jums dzenās pakaļ, un paslēpjaties tur trīs dienas, tiekams tie vajātāji atgriezīsies, tad pēc ejat savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Tad tie vīri uz viņu sacīja: mēs būsim vaļā no šī tava zvēresta, ko tu mums lieci zvērēt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Redzi, kad mēs nākam tai zemē, tad piesien pie sava loga šo sarkano virvi, ar ko tu mūs nolaidi, un sapulcini pie sevis šai namā savu tēvu un savu māti un savus brāļus un visu tava tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Un ikviens, kas pa tava nama durvīm izies ārā, tā asinis lai paliek uz viņa galvas, un mēs būsim nevainīgi. Bet ikviens, kas pie tevis būs namā, tā asinis lai paliek uz mūsu galvas, ja kas savu roku pie viņa pieliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Bet ja tu šo mūsu lietu darīsi zināmu, tad mēs būsim vaļā no šī zvēresta, ko tu mums likusi zvērēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Tad viņa sacīja: lai tā ir, kā jūs sakāt. Un viņa tos atlaida, un tie aizgāja; un viņa to sarkano virvi piesēja pie loga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Tā tie aizgāja un nāca kalnos un palika tur trīs dienas, tiekams tie vajātāji bija atpakaļ griezušies; jo tie vajātāji tos bija meklējuši pa visiem ceļiem, bet nebija atraduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Tad tie divi vīri griezās atpakaļ un nonāca no tiem kalniem un cēlās pāri un nāca pie Jozuas, Nuna dēla, un teica tam visu, kas tiem bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Un tie sacīja uz Jozua: tiešām Tas Kungs visu to zemi ir devis mūsu rokās, un visi zemes iedzīvotāji no mums bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Tad Jozuas cēlās no rīta agri, un tie aizgāja no Sitimas un nāca līdz Jardānei, viņš un visi Israēla bērni. Un tie tur palika par nakti, pirms pārcēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Un pēc trim dienām tie virsnieki gāja pa lēģeri');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Un pavēlēja tiem ļaudīm sacīdami: kad jūs redzēsiet Tā Kunga, sava Dieva, derības šķirstu un tos priesterus, Levja bērnus, to nesam, tad ceļaties no savas vietas un ejat viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Tomēr lai starpa paliek starp jums un viņu līdz divi tūkstošu olekšu plata, un neejat tam tuvu, lai jūs to ceļu varat zināt, kas jums jāiet, jo jūs šo ceļu vēl nekad neesat gājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Un Jozuas sacīja uz tiem ļaudīm: svētījaties, jo rītā Tas Kungs jūsu starpā darīs brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Un Jozuas runāja uz tiem priesteriem sacīdams: ņemat derības šķirstu un ejat pāri ļaužu priekšā. Tad tie ņēma derības šķirstu un gāja tiem ļaudīm priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Un Tas Kungs sacīja uz Jozua: šodien Es sākšu tevi paaugstināt visa Israēla acīs; lai tie zin, ka Es būšu ar tevi, kā esmu bijis ar Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Un tiem priesteriem, kas to derības šķirstu nes, tev būs pavēlēt un sacīt: kad jūs nākat Jardānes malā pie ūdens, tad apstājaties pie Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Un Jozuas sacīja uz Israēla bērniem: nāciet šurp un klausāties Tā Kunga, sava Dieva, vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Un Jozuas sacīja: pie tam jums būs zināt, ka Tas dzīvais Dievs ir jūsu vidū, un ka Viņš izdzīdams izdzīs jūsu priekšā Kanaāniešus un Hetiešus un Hiviešus un Fereziešus un Ģirgaziešus un Amoriešus un Jebusiešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Redzi, visas pasaules valdītāja derības šķirsts ies jūsu priekšā pāri pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Tad nu ņemat sev divpadsmit vīrus no Israēla ciltīm, no ikvienas cilts vienu vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Un kad to priesteru kājas, kas Tā Kunga, visas pasaules valdītāja, šķirstu nes, nolaidīsies Jardānes ūdenī, tad Jardānes ūdens apstāsies, tas ūdens, kas no augšienes tek, un stāvēs vienā kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Un kad tie ļaudis no saviem dzīvokļiem cēlās, iet pār Jardāni, un tie priesteri nesa derības šķirstu ļaužu priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Un kad tie šķirsta nesēji nāca līdz Jardānei, un kad to priesteru kājas, kas to šķirstu nesa, upmalā iebrida ūdenī, (bet Jardāne līdz pašām malām ir uzplūdusi cauru pļaujamo laiku),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Tad tas ūdens, kas no augšienes nāca, nostājās stāvu vienā kopā, labi tālu no Adamas pilsētas, kas sānis Cartanai; bet tas, kas tecēja uz leju, klajuma jūrā, (proti) sāls jūrā, tas pavisam izsīka. Tad tie ļaudis gāja pāri, Jērikum pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Bet tie priesteri, kas Tā Kunga derības šķirstu nesa, stāvēja sausumā Jardānes vidū, un viss Israēls gāja pāri pa sausumu, tiekams visi ļaudis bija pārgājuši pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Un kad visi ļaudis bija pārgājuši pār Jardāni, tad Tas Kungs runāja uz Jozua un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Ņemat sev divpadsmit vīrus no tiem ļaudīm, no ikvienas cilts vienu vīru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Un pavēliet tiem sacīdami: paņemiet no šejienes, no Jardānes vidus, kur priesteru kājās stāvējušas, divpadsmit akmeņus un nesiet tos līdz pāri un noliekat tos tai vietā, kur paliksiet par nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Tad Jozuas aicināja tos divpadsmit vīrus, ko viņš no Israēla bērniem bija iecēlis, no ikvienas cilts vienu vīru, un Jozuas uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Noejat Tā Kunga, sava Dieva, šķirsta priekšā Jardānes vidū un paņemat ikkatrs vienu akmeni uz saviem pleciem pēc Israēla bērnu cilšu skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Lai šī ir zīme jūsu starpā, kad jūsu bērni pēclaikā vaicās, sacīdami: kas tie jums par akmeņiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Tad jums būs uz tiem sacīt: tādēļ, ka Jardānes ūdens ir izsīcis priekš Tā Kunga derības šķirsta; kad tas gāja caur Jardāni, tad Jardānes ūdens izsīka. Tā lai šie akmeņi Israēla bērniem ir par piemiņu mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Un Israēla bērni darīja, kā Jozuas tiem bija pavēlējis, un ņēma no Jardānes vidus divpadsmit akmeņus pēc Israēla bērnu cilšu skaita, kā Tas Kungs uz Jozua bija runājis, un tos pārnesa līdz mājas vietā, un tos tur nolika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Jozuas uzcēla arī divpadsmit akmeņus pašā Jardānes vidū, kur priesteru, derības šķirsta nesēju, kājas bija stāvējušas, un tie tur ir līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Un tie priesteri, kas to šķirstu nesa, stāvēja Jardānes vidū, kamēr viss bija izdarīts, ko Tas Kungs Jozuam bija pavēlējis, uz tiem ļaudīm runāt, pēc visa, ko Mozus Jozuam bija pavēlējis; un tie ļaudis steidzās un gāja pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Un kad tie ļaudis bija pārgājuši, tad Tā Kunga šķirsts gāja pāri un tie priesteri ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Rūbena bērni un Gada bērni un Manasus puscilts apbruņoti gāja Israēla bērnu priekšā, kā Mozus uz tiem bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Pie četrdesmit tūkstošu apbruņotu karavīru gāja karā Tā Kunga priekšā Jērikus klajumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Tai dienā Tas Kungs Jozua paaugstināja visa Israēla acīs, un tie viņu bijās, tā kā tie bija Mozu bijušies visas viņa mūža dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Un Tas Kungs runāja uz Jozua un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Pavēli tiem priesteriem, kas derības šķirstu nes, lai tie izkāpj no Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Tad Jozuas tiem priesteriem pavēlēja un sacīja: izkāpiet no Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Un kad tie priesteri, kas Tā Kunga derības šķirstu nesa, izkāpa no Jardānes vidus, un kad priesteru kājas nāca sausumā, tad Jardānes ūdens griezās atpakaļ savā vietā un pārplūda kā papriekš visur savos krastos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Bet pirmā mēneša desmitā dienā tie ļaudis no Jardānes izkāpa un apmetās Gilgalā, Jērikum pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Un Jozuas uzcēla Gilgalā tos divpadsmit akmeņus, ko tie no Jardānes bija paņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Un viņš runāja uz Israēla bērniem sacīdams: kad jūsu bērni turpmāk saviem tēviem vaicās un sacīs: kas tie par akmeņiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Tad jums būs stāstīt saviem bērniem un sacīt: Israēls ir gājis pa sausumu caur šo Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Jo Tas Kungs, jūsu Dievs, Jardānes ūdenim jūsu priekšā ir licis izsīkt, tiekams jūs bijāt pārgājuši, kā Tas Kungs, jūsu Dievs, bija darījis niedru jūrā; tai Viņš arī lika izsīkt mūsu priekšā, tiekams bijām gājuši cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Lai visas zemes tautas atzīst Tā Kunga roku, ka tā ir stipra, lai jūs bīstaties To Kungu, savu Dievu, visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Un notikās, kad visi Amoriešu ķēniņi, kas viņpus Jardānes pret jūru un visi Kanaāniešu ķēniņi, kas jūrmalā, dzirdēja, ka Tas Kungs bija licis izsīkt Jardānes ūdenim Israēla bērnu priekšā, tiekams tie bija gājuši cauri, tad viņu sirds tapa bailīga, un tiem izzuda drošība Israēlu bērnu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Tanī laikā Tas Kungs sacīja uz Jozua: taisi sev akmens nažus un apgraizī atkal Israēla bērnus otru reiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Tad Jozuas taisīja sev akmens nažus un apgraizīja Israēla bērnus uz Aralot pakalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Un tādēļ Jozuas tos apgraizīja: visi ļaudis no vīriešu kārtas, kas no Ēģiptes zemes bija izgājuši, visi kara vīri bija nomiruši tuksnesī uz ceļa, no Ēģiptes zemes nākot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Jo visi ļaudis, kas izgāja, bija apgraizīti. Bet visi ļaudis, kas bija dzimuši tuksnesī, ceļā no Ēģiptes zemes nākot, tie nebija apgraizīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Jo Israēla bērni staigāja četrdesmit gadus tuksnesī, tiekams bija izmiruši visi karavīri, kas no Ēģiptes zemes bija izgājuši, tādēļ ka Tā Kunga balsij nebija klausījuši; tiem Tas Kungs bija zvērējis, ka Viņš tiem to zemi negribot ļaut redzēt, ko Viņš viņu tēviem bija zvērējis, mums dot, zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Bet viņu dēlus Viņš cēla viņu vietā; tos Jozuas apgraizīja, tāpēc ka tiem bija priekšāda, jo tie nebija apgraizīti ceļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Un kad visi ļaudis bija apgraizīti, tad tie palika savā vietā lēģerī, tiekams bija dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Un Tas Kungs sacīja uz Jozua: šodien Es no jums esmu novērsis visu Ēģiptes kaunu. Tāpēc tās vietas vārds tapa nosaukts Gilgala (novēršana) līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Un Israēla bērni apmetās Gilgalā, un turēja Pasa svētkus mēneša četrpadsmitā dienā ap vakaru, Jērikus klajumos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Un ēda Pasa svētku otrā dienā no tās zemes labības neraudzētu maizi un ceptas vārpas šinī dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Un tas manna beidzās otrā dienā pēc tam, kad tie bija ēduši no tās zemes labības, un tur nebija vairs manna Israēla bērniem, bet tie ēda to gadu no Kanaāna zemes augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Un kad Jozuas bija pie Jērikus, tad viņš pacēla savas acis, un redzēja, un raugi, tur viens vīrs viņam stāvēja pretī, tam bija izvilkts zobens rokā, un Jozuas pie viņa gāja un sacīja: vai tu esi no mūsējiem vai no mūsu pretiniekiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Un tas sacīja: nē, bet es esmu Tā Kunga karaspēka virsnieks, tagad es esmu nācis. Tad Jozuas metās zemē uz savu vaigu un to pielūdza un uz to sacīja: ko mans Kungs runā uz savu kalpu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Tad Tā Kunga karaspēka virsnieks sacīja uz Jozua: novelc savas kurpes no savām kājām, jo tā vieta, kur tu stāvi, ir svēta. Un Jozuas tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Un Jērikus aizslēdza vārtus un bija aizslēgts priekš Israēla bērniem; tur neviens ne izgāja, ne iegāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Tad Tas Kungs sacīja uz Jozua: redzi, Jēriku ar viņa ķēniņu un stipriem karavīriem Es dodu tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Un ejat ap pilsētu, visi kara vīri visapkārt ap pilsētu vienreiz; tā dari sešas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Un septiņi priesteri lai nes septiņas gaviles bazūnes tā šķirsta priekšā, un septītā dienā ejat septiņas reizes ap pilsētu un tie priesteri lai pūš bazūnes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Un kad tie pūtīs gaviles bazūni un jūs dzirdēsiet bazūnes skaņu, tad lai visi ļaudis kliedz lielā kliegšanā, un pilsētas mūri sagrūs, un tie ļaudis lai kāpj iekšā, kur katrs stāvēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Tad Jozuas, Nuna dēls, aicināja tos priesterus un uz tiem sacīja: nesiet derības šķirstu, un lai septiņi priesteri nes septiņas gaviles bazūnes Tā Kunga šķirsta priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Un uz tiem ļaudīm viņš sacīja: ejat apkārt ap pilsētu, un tie apbruņotie lai iet Tā Kunga šķirsta priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Un kā Jozuas uz tiem ļaudīm bija sacījis, tā tie septiņi priesteri gāja nesdami septiņas gaviles bazūnes Tā Kunga priekšā, tie gāja un pūta bazūnes, un Tā Kunga derības šķirsts tiem gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Un tie apbruņotie gāja to priesteru priekšā, kas bazūnes pūta, un tas pulks gāja tam šķirstam pakaļ, ejot bazūnes pūzdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Un Jozuas tiem ļaudīm bija pavēlējis sacīdams: jums nebūs kliegt, un lai jūsu balss netop dzirdēta, un lai ne vārds neiziet no jūsu mutes līdz tai dienai, kad es jums sacīšu: kliedzat! Tad jums būs kliegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Un Tā Kunga šķirsts gāja ap pilsētu apkārt vienreiz; tad tie nāca atkal lēģerī un palika par nakti lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Un Jozuas cēlās no rīta agri, un tie priesteri nesa Tā Kunga šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Un tie septiņi priesteri, kas tās septiņas gaviles bazūnes nesa Tā Kunga šķirsta priekšā, gāja un ejot pūta bazūnes un tie apbruņotie gāja viņiem pa priekšu, un tas pulks gāja Tā Kunga šķirstam pakaļ, un ejot pūta bazūnes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Un otrā dienā tie gāja ap pilsētu vienreiz un griezās atkal lēģerī; tā tie darīja sešas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Un septītā dienā tie cēlās agri, gaismai austot, un gāja ap pilsētu tādā pašā kārtā septiņas reizes; tik vien šai dienā tie gāja ap pilsētu septiņas reizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Un septītā reizē, kad tie priesteri bazūnes pūta, Jozuas sacīja uz tiem ļaudīm: kliedzat, jo Tas Kungs jums to pilsētu ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Un tā pilsēta un viss, kas tur ir, Tam Kungam lai top izdeldēts; Rahaba tikai, tā mauka, lai paliek dzīva, un visi, kas pie viņas ir namā, jo viņa ir paslēpusi tos vīrus, ko bijām izsūtījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Tikai sargājaties no tā izdeldējamā, ka jūs paši netopat izdeldēti, un neņemat no tā izdeldējamā, un nedarāt, ka Israēla lēģeris netop izdeldēts, un nevedat to postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Bet viss sudrabs un zelts un vara un dzelzs rīki, - tas lai Tam Kungam ir svēts, tam būs nākt pie Tā Kunga mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tad nu tie ļaudis kliedza, un bazūnes tapa pūstas. Un notikās, kad tie ļaudis dzirdēja bazūnes skaņu, tad tie ļaudis kliedza lielā kliegšanā, un tas mūris sagruva, un tie ļaudis kāpa pilsētā, kur katrs stāvēdams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Un tie uzņēma to pilsētu un izdeldēja ar zobena asmeni visu, kas pilsētā bija, vīrus un sievas, bērnus un vecos līdz ar vēršiem un sīkiem lopiem un ēzeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Tad Jozuas sacīja tiem diviem vīriem, tās zemes izlūkiem: ejat tās sievas, tās maukas, namā, un izvediet no turienes to sievu un visu, kas tai pieder, kā jūs tai esat zvērējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Tad tie jaunekļi, tie izlūki, gāja un izveda Rahabu un viņas tēvu un viņas māti un viņas brāļus un visu, kas tai piederēja; tie izveda arī visus viņas radus un lika tiem palikt ārā priekš Israēla lēģera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Un to pilsētu tie sadedzināja ar uguni, un visu, kas tur bija; bet to sudrabu un zeltu līdz ar tiem vara un dzelzs rīkiem, to tie lika pie Tā Kunga nama mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Bet to mauku Rahabu un viņas tēva namu, un visu, kas tai piederēja, Jozuas pameta dzīvu, un tā dzīvo Israēla vidū līdz šai dienai, tāpēc ka viņa bija paslēpusi tos vīrus, ko Jozuas bija izsūtījis, Jēriku izlūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Un tanī laikā Jozuas zvērēja un sacīja: nolādēts lai ir tas vīrs Tā Kunga priekšā, kas celsies un uztaisīs šo pilsētu Jēriku! Pamatu tas lai liek par savu pirmdzimto un vārtus lai ceļ par savu jaunāko!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Tā Tas Kungs bija ar Jozua, un viņa slava izpaudās pa visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Bet Israēla bērni noziedzās pie tā izdeldējamā, jo Akans, Karmus dēls, tas bija Zabdus, tas Zerus dēls no Jūda cilts, ņēma no tā izdeldējamā. Tad Tā Kunga bardzība iedegās pret Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Kad nu Jozuas izsūtīja vīrus no Jērikus uz Aju pie Bet-Avenas, no Bēteles pret rītiem, un uz tiem runāja sacīdams: noejat un izlūkojiet to zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Tad tie vīri nogāja un izlūkoja Aju, un griezās atpakaļ pie Jozuas un uz to sacīja: lai visi ļaudis nenoiet, bet lai kādi divtūkstoš vai trīstūkstoš vīri noiet un Aju kauj, neapgrūtini visus ļaudis, jo viņu tur ir maz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Tad no tiem ļaudīm cēlās uz turieni trīstūkstoš vīri, bet tiem bija jābēg priekš Ajas vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Un Ajas vīri apkāva no tiem trīsdesmit un sešus vīrus un dzinās tiem pakaļ no vārtiem līdz Zabarim, un tos sakāva pakalnē. Tad to ļaužu sirds izkusa un palika kā ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Un Jozuas saplēsa savas drēbes un metās zemē uz savu vaigu priekš Tā Kunga šķirsta līdz pat vakaram, viņš un Israēla vecaji, un tie kaisīja pīšļus uz savām galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Un Jozuas sacīja: ak Kungs, Dievs! Kāpēc tu šiem ļaudīm esi licis iet caur Jardāni, mūs dodams Amoriešu rokās, ka tie mūs izdeldē? Ak, kaut mēs mierā būtu palikuši viņpus Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ak Kungs, ko lai saku, kad nu Israēls muguru griež saviem ienaidniekiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Kad Kanaānieši un visi zemes iedzīvotāji to dzirdēs, tad tie mūs apstās visapkārt un izdeldēs mūsu vārdu no zemes. Ko tad Tu darīsi Sava lielā Vārda dēļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Tad Tas Kungs sacīja uz Jozua: celies, kāpēc tu tā guli uz sava vaiga?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israēls ir apgrēkojies un arī pārkāpis Manu derību, ko Es tiem esmu pavēlējis; tie ir arī ņēmuši no tā izdeldējamā un ir zaguši un slēpuši un to ir likuši pie savas mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Tāpēc Israēla bērni nevar pastāvēt priekš saviem ienaidniekiem, tiem bēdzin jābēg no saviem ienaidniekiem, jo tie ir izdeldējami. Es nebūšu vairs ar jums, ja jūs to, kas izdeldējams, no sava vidus neizdeldēsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Celies, svētī tos ļaudis un saki: svētījaties uz rītdienu, jo tā saka Tas Kungs, Israēla Dievs: izdeldējama lieta ir tavā vidū, Israēl; tu nevari pastāvēt priekš saviem ienaidniekiem, tiekams tu nebūsi izdeldējis no sava vidus to izdeldējamo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Rītā agri nākat priekšā pēc savām ciltīm, un tā cilts, ko Tas Kungs uzrādīs, lai nāk priekšā pēc saviem radiem, un tas rads, ko Tas Kungs uzrādīs, lai nāk priekšā pēc savām saimēm, un tā saime, ko Tas Kungs uzrādīs, lai nāk priekšā pēc saviem vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Un kas taps atrasts ar to izdeldējamo, to būs sadedzināt ar uguni, līdz ar visu, kas tam pieder, tāpēc ka viņš pārkāpis Tā Kunga derību, un tāpēc ka viņš kauna lietu darījis iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Tad Jozuas cēlās no rīta agri un veda priekšā Israēli pēc viņu ciltīm, - tad Jūda cilts tapa uzrādīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Un kad viņš Jūda cilti veda priekšā, tad tapa uzrādīts Zeraiešu rads, un kad Zeraiešu radu veda priekšā pēc tiem saimniekiem, tad Zabdus tapa uzrādīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Kad šo saimi veda priekšā pēc tiem vīriem, tad Akans tapa uzrādīts, Karmus dēls, tas bija Zabdus, tas Zerus dēls no Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Tad Jozuas sacīja uz Akanu: mans dēls, dod jel Tam Kungam, Israēla Dievam, godu un dod Viņam slavu un stāsti man jel, ko tu esi darījis, un neslēpi to man.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Tad Akans atbildēja Jozuam un sacīja: tiešām, es esmu apgrēkojies pret To Kungu, Israēla Dievu, un esmu tā un tā darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Jo es ieraudzīju pie laupījuma vienu skaistu Babiloniešu mēteli un divsimt sudraba sēķeļus un vienu zelta sprādzi, tā svēra piecdesmit sēķeļus, un es tās lietas iekāroju un tās ņēmu, un redzi, tās manā teltī ir paslēptas zemē un tas sudrabs tur apakšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Tad Jozuas sūtīja vīrus un tie skrēja uz to telti, un redzi, tas bija apslēpts viņa teltī, un tas sudrabs tur apakšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Un tie to izņēma no tās telts un atnesa pie Jozuas un pie visiem Israēla bērniem un to izbēra Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Tad Jozuas un viss Israēls līdz ar viņu ņēma Akanu, Zerus dēlu, un to sudrabu un to mēteli un to zelta sprādzi un viņa dēlus un viņa meitas un viņa vēršus un viņa ēzeļus un viņa sīkos lopus un viņa telti un visu, kas tam bija, un tos veda uz Ahora ieleju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Un Jozuas sacīja: kā tu mūs esi apbēdinājis, tā tev Tas Kungs šodien apbēdinās; un viss Israēls to akmeņiem nomētāja un tos sadedzināja ar uguni un uzkrāva pār tiem akmeņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Un tie uzcēla pār tiem lielu akmeņu kopu, kas stāv līdz šai dienai. Tā Tas Kungs atgriezās no Savas bardzības karstuma; tādēļ tās vietas vārds top nosaukts Ahora ieleja līdz šai pašai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Tad Tas Kungs sacīja uz Jozua: nebīsties un nebaiļojies! Ņem līdz visus karavīrus un celies pret Aju; redzi, Es esmu devis tavā rokā Ajas ķēniņu un viņa ļaudis, viņa pilsētu un viņa zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Un dari Ajai un viņas ķēniņam, kā tu esi darījis Jērikum un viņa ķēniņam, tikai lai jūs viņas laupījumu un viņas lopus priekš sev ņemat. Liec citiem paslēpties aiz pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Tad Jozuas un visi karavīri cēlās, iet uz Aju, un Jozuas izlasīja trīsdesmit tūkstošus spēcīgu un stipru vīru, un tos izsūtīja naktī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Un tiem pavēlēja sacīdams: raugāt, jums pret to pilsētu būs paslēpties aiz pilsētas; neturaties visai tālu no pilsētas un esiet visi gatavi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Es tad un visi tie ļaudis, kas pie manis, pieiesim pie pilsētas, un kad tie izies mums pretī tā kā pirmo reiz, tad mēs no viņiem bēgsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Lai tie tad nāk ārā mums pakaļ, kamēr mēs tos no pilsētas atšķiram, jo tie sacīs: viņi bēg mūsu priekšā, tā kā pirmo reiz, - un mēs bēgsim no viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Bet jūs ceļaties no tās vietas, kur bijāt slēpušies, un uzņemat to pilsētu, jo Tas Kungs, jūsu Dievs, to devis jūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Un kad jūs to pilsētu esat uzņēmuši tad jums to pilsētu būs sadedzināt ar uguni, pēc Tā Kunga vārda jums būs darīt; redziet, es jums to esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Tā Jozuas tos izsūtīja. Un tie gāja paslēpties un turējās starp Bēteli un Aju, Ajai pret vakariem, bet Jozuas palika to nakti pie tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Un Jozuas cēlās no rīta agri un pārlūkoja tos ļaudis, un viņš un Israēla vecaji cēlās tiem ļaudīm priekšā pret Aju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Tā līdz arīdzan visi karavīri, kas pie tā bija, cēlās un piegāja un nāca pret to pilsētu un apmetās pret ziemeļa pusi no Ajas, un tur bija ieleja starp tiem un Aju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Un viņš ņēma kādus piectūkstoš vīrus un tiem lika paslēpties starp Bēteli un Aju, pilsētai pret vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Un tie nostādīja tos ļaudis, visu to lēģeri, kas bija pret pilsētas ziemeļa pusi, un viņa pakaļējo pulku pret pilsētas vakara pusi, un Jozuas tanī naktī nogāja pašā ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Un kad Ajas ķēniņš to redzēja, tad tie pilsētas vīri steidzās un cēlās no rīta agri un izgāja Israēlim pretī uz kaušanos, viņš un visi viņa ļaudis, norunātā vietā klajuma priekšā, bet viņš nezināja, ka citi bija paslēpušies aiz pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Un Jozuas un viss Israēls izlikās kauti esoši viņu priekšā un bēga pa tuksneša ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Tāpēc visi ļaudis, kas bija pilsētā, tapa sasaukti, ka tiem dzītos pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Un tie dzinās Jozuam pakaļ un šķīrās nost no pilsētas, un tur neatlika neviena vīra Ajā un Bētelē, kas nebūtu izgājis Israēlim pakaļ, un tie pameta pilsētu atvērtu un dzinās Israēlim pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Tad Tas Kungs sacīja uz Jozua: izstiep to šķēpu, kas tavā rokā, pret Aju, jo Es to došu tavā rokā. Tad Jozuas izstiepa to šķēpu, kas bija viņa rokā, pret to pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Tad tie, kas bija paslēpušies, tūdaļ cēlās no savas vietas un skrēja, kad viņš savu roku izstiepa, un nāca pilsētā un to uzņēma un steidzās un iededzināja to pilsētu ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Kad nu Ajas ļaudis atpakaļ griezās, tad tie skatījās, un redzi, pilsētas dūmi cēlās pret debesi, un tie nespēja nekur bēgt, ne šurp, ne turp, jo tie ļaudis, kas uz tuksnesi bēga, griezās atpakaļ pret tiem, kas dzinās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Jo kad Jozuas un viss Israēls redzēja, ka tie, kas bija paslēpušies, pilsētu bija uzņēmuši un ka pilsētas dūmi cēlās, tad viņi arīdzan griezās atpakaļ un kāva Ajas vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Un tad arī tie no pilsētas nāca ārā viņiem pretī, tā ka tie bija vidū starp Israēli, šie no tejienes un viņi no turienes, un tie tos kāva, kamēr neviens no tiem neatlika nedz izbēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Bet Ajas ķēniņu tie sagūstīja dzīvu un veda pie Jozuas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Un kad Israēls bija nokāvis visus Ajas iedzīvotājus, laukā un tuksnesī, uz kurieni tie viņiem bija dzinušies pakaļ, un kad tie visi caur zobena asmeni bija krituši līdz pēdīgam, tad viss Israēls griezās atpakaļ uz Aju, un to sita ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Un visi, kas tai dienā krita, vīri un sievas, bija divpadsmit tūkstoši; tie bija visi Ajas ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Un Jozuas neatvilka savu roku, ko viņš ar šķēpu bija izstiepis, tiekams viņš nebija izdeldējis visus Ajas iedzīvotājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Tikai lopus un pilsētas laupījumu Israēls laupīja priekš sevis pēc Tā Kunga vārda, ko viņš Jozuam bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Un Jozuas sadedzināja Aju un to padarīja par mūžīgu postažas vietu līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Un Ajas ķēniņu viņš pakāra pie koka līdz vakaram, un kad saule nogāja, Jozuas pavēlēja, viņa miesas noņemt no koka, un tie viņu nometa pie pilsētas vārtiem un uzkrāva pār viņu lielu akmeņu kopu līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tad Jozuas uztaisīja altāri Tam Kungam, Israēla Dievam, Ebala kalnā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Tā kā Mozus, Tā Kunga kalps, Israēla bērniem bija pavēlējis, kā Mozus bauslības grāmatā stāv rakstīts, altāri no veseliem akmeņiem, kur dzelzs ierocis nebija pielikts, un uz tā tie upurēja Tam Kungam dedzināmos upurus un upurēja arī pateicības upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Un viņš rakstīja uz tiem akmeņiem norakstu no Mozus bauslības, ko šis bija rakstījis priekš Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Un viss Israēls ar saviem vecajiem un virsniekiem un soģiem stāvēja abējos šķirsta sānos pretim tiem priesteriem un Levitiem, kas Tā Kunga derības šķirstu nesa, gan svešinieki, gan pašu ļaudis, viena puse pret Gerizim kalnu un otra puse pret Ebalkalnu, tā kā Mozus, Tā Kunga kalps, iepriekš bija pavēlējis, tos ļaudis svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Un pēc tam viņš izlasīja visus bauslības vārdus, svētību un lāstu, kā bauslības grāmatā stāv rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Tur nebija neviena vārda no visiem, cik Mozus bija pavēlējis, ko Jozuas nebūtu izlasījis priekš visas Israēla draudzes un tām sievām un tiem bērniņiem un tiem svešiniekiem, kas staigāja viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Un kad to dzirdēja visi ķēniņi, kas viņpus Jardānes bija, kalnos un ielejās un gar visu lielās jūras malu, Lībanum pretī, Hetieši un Amorieši, Ferezieši, Hivieši un Jebusieši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Tad tie sapulcējās visi kopā, kauties ar Jozua un ar Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Kad nu Gibeonas iedzīvotāji dzirdēja, ko Jozuas bija darījis ar Jēriku un ar Aju, tad tie arīdzan darīja viltu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Un nogāja un likās vēstneši ejoši un ņēma vecus maisus uz saviem ēzeļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Un vecus saplīsušus un lāpītus ādas vīna traukus, arī vecas un lāpītas kurpes savās kājās, un tiem bija arī vecas drēbes mugurā, un visa viņu ceļamaize bija sakaltusi un sapelējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Un tie gāja pie Jozuas Gilgalas lēģerī un sacīja uz to un uz Israēla vīriem: mēs no tālas zemes esam nākuši; tad dariet nu ar mums derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Tad Israēla vīri sacīja uz to Hivieti: varbūt, ka tu dzīvo mūsu vidū, kā tad mēs ar tevi varam darīt derību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Tad tie sacīja uz Jozua: mēs esam tavi kalpi. Tad Jozuas uz tiem sacīja: kas jūs esat un no kurienes jūs nākat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Tie uz viņu sacīja: tavi kalpi nākuši no varen tālas zemes, Tā Kunga, tava Dieva, vārda dēļ; jo mēs esam dzirdējuši Viņa slavu un visu, ko Viņš darījis Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Un visu, ko Viņš darījis tiem diviem Amoriešu ķēniņiem, kas viņpus Jardānes bija, Sihonam, Hešbonas ķēniņam, un Ogam, Basanas ķēniņam, kas Astarotā dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Tāpēc mūsu vecaji un visi, kas mūsu zemē dzīvo, uz mums runāja un sacīja: ņemiet savās rokās ceļamaizi un ejat viņiem pretī un sakāt uz tiem: mēs esam jūsu kalpi; un nu dariet ar mums derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Šo savu maizi mēs jaunu no savām mājām uz ceļu esam paņēmuši līdz, tai dienā, kad mēs izgājām pie jums nākt, bet redzi, nu tā sakaltusi un sapelējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Un šie ādas vīna trauki, ko mēs pildījām, bija jauni, bet redzi, tie ir saplīsuši un šīs mūsu drēbes un mūsu kurpes ir vecas palikušas no tā varen tālā ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Tad tie vīri ņēma no viņu ceļamaizes un nevaicāja Tā Kunga muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Un Jozuas derēja mieru ar tiem un darīja derību ar tiem, tos atstāt dzīvus, un tie draudzes virsnieki tiem zvērēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Un pēc trim dienām, kad tie derību ar tiem bija darījuši, tad tie dzirdēja, viņus no tuvienes esam un dzīvojam viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Jo kad Israēla bērni cēlās, tad tie nāca trešā dienā pie viņu pilsētām. Bet viņu pilsētas bija Gibeona, Kavira un Beērote un Kiriat-Jearima.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Un Israēla bērni tos nekāva, tāpēc ka draudzes virsnieki tiem bija zvērējuši pie Tā Kunga, Israēla Dieva; tāpēc visa draudze kurnēja pret tiem virsniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Tad visi tie virsnieki uz visu draudzi sacīja: mēs pie Tā Kunga, Israēla Dieva, tiem esam zvērējuši, tāpēc mēs tos nu nevaram aizskart.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Bet mēs tiem darīsim tā: pametīsim tos dzīvus, ka nekāda dusmība pār mums nenāk tā zvēresta dēļ, ko mēs tiem esam zvērējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Tad tie virsnieki uz tiem sacīja: lai paliek dzīvi; un tie bija malkas cirtēji un ūdens smēlēji visai draudzei, kā tie virsnieki tiem bija runājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Un Jozuas tos aicināja un uz tiem runāja sacīdams: kāpēc jūs mūs esat pievīluši sacīdami, mēs esam ļoti tālu no jums, - un jūs tomēr mūsu vidū dzīvojat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Nu tad esat nolādēti, ka no jums netrūkst kalpu un malkas cirtēju un ūdens smēlēju priekš mūsu Dieva nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Tie atbildēja Jozuam un sacīja: taviem kalpiem tapa stāstīts, ko Tas Kungs, tavs Dievs, Mozum Savam kalpam, ir pavēlējis, ka Viņš jums visu to zemi grib dot, un visus tos, kas tai zemē dzīvo, no jūsu priekšas izdeldēt, tad mēs savas dzīvības dēļ ļoti bijāmies no jums un tā darījām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Un nu redzi, mēs esam tavā rokā, dari mums, tā kā darīt tavās acīs rādās labi un taisni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Tad viņš tiem tā darīja un tos izglāba no Israēla bērnu rokas, ka tie tos nenokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Un Jozuas tai dienā tos nodeva draudzei par malkas cirtējiem un ūdens smēlējiem un priekš Tā Kunga altāra līdz šai dienai tai vietā, ko Viņš izredzētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Un kad Adonicedeķs, Jeruzālemes ķēniņš, dzirdēja, ka Jozuas Aju bija uzņēmis un izdeldējis, un Ajai un viņas ķēniņam tā darījis, kā viņš Jērikum un viņa ķēniņam bija darījis, un ka tie, kas Gibeonā dzīvoja, ar Israēli bija derējuši mieru un starp tiem dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Tad tie ļoti bijās, jo Gibeona bija liela pilsēta, tā kā viena ķēniņa pilsēta, lielāka nekā Aja, un visi viņas vīri bija stipri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Tāpēc Adonicedeķs, Jeruzālemes ķēniņš, sūtīja pie Oāma, Hebronas ķēniņa, un pie Pireama, Jarmutes ķēniņa, un pie Javiūs, Lāķisas ķēniņa, un pie Debira, Eglonas ķēniņa, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Nāciet pie manis un palīdziet man, lai Gibeonu kaujam, jo tā mieru derējusi ar Jozua un ar Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Tad sapulcējās un cēlās pieci Amoriešu ķēniņi: Jeruzālemes ķēniņš, Hebronas ķēniņš, Jarmutes ķēniņš, Lāķisas ķēniņš, Eglonas ķēniņš, līdz ar visiem saviem karapulkiem un apmetās pret Gibeonu un karoja pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Un Gibeonas vīri sūtīja pie Jozuas lēģerī uz Gilgalu sacīdami: neatrauj savu roku no saviem kalpiem; nāc steigšus un izglāb mūs un palīdzi mums, jo visi Amoriešu ķēniņi, kas kalnos dzīvo, pret mums sapulcējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Tad Jozuas cēlās no Gilgalas, pats un visi kara ļaudis līdz ar viņu, un visi spēka vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Un Tas Kungs sacīja uz Jozua: nebīsties no viņiem, jo Es tos esmu nodevis tavā rokā, neviens nepastāvēs tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Un Jozuas piepeši viņiem uzbruka, cauru nakti no Gilgalas uz augšu iedams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Un Tas Kungs tos izbiedēja Israēla priekšā, un viņš tos kāva ar lielu kaušanu Gibeonā un tiem dzinās pakaļ pa to ceļu augšup uz Bet-Oronu un tos kāva līdz Āzekai un Maķedai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Un kad tie no Israēla bēga lejā no Bet-Orona, tad Tas Kungs lielus krusas gabalus no debess uz tiem nometa līdz Āzekai, ka tie nomira; tur bija vairāk, kas no krusas nomira, nekā ko Israēla bērni ar zobenu nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Tad Jozuas runāja uz To Kungu tai dienā, kad Tas Kungs Amoriešus nodeva Israēla priekšā, un sacīja Israēla priekšā: Saule, apstājies Gibeonā, un mēnesi, Ajalones ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Tad saule apstājās un mēnesis stāvēja, tiekams tie ļaudis pie saviem ienaidniekiem bija atriebušies. Vai tas nav rakstīts tā taisnā grāmatā: Tā saule stāvēja debess vidū un nesteidzās noiet veselu dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Un tādas dienas kā šī nebija, ne priekš viņas, ne pēc viņas, ka Tas Kungs cilvēka balsi paklausīja; jo Tas Kungs karoja par Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Tad Jozuas griezās atpakaļ un viss Israēls līdz ar viņu uz Gilgalas lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Bet tie pieci ķēniņi bija bēguši un apslēpušies tai alā pie Maķedas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Un Jozuam tapa teikts un sacīts: tie pieci ķēniņi ir atrasti, apslēpušies tai alā pie Maķedas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Tad Jozuas sacīja: pieveļat lielus akmeņus priekš alas cauruma un liekat vīrus priekšā, viņus sargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Bet jūs nestāviet mierā, dzenaties saviem ienaidniekiem pakaļ un kaujiet viņu pakaļējos, neļaujat tiem savās pilsētās nākt, jo Tas Kungs, jūsu Dievs, tos ir nodevis jūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Un kad Jozuas un Israēla bērni bija beiguši tos kaut ar ļoti lielu kaušanu, kamēr tie bija izdeldēti, un kad tie atlikušie no tiem bija glābušies un nākuši stiprās pilsētās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Tad visi ļaudis ar mieru griezās atpakaļ pie Jozuas uz lēģeri pie Maķedas; neviens pret Israēla bērniem pat ne mēli nekustināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Un Jozuas sacīja: atdariet tās alas caurumu un izvediet tos piecus ķēniņus no alas pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Un tie tā darīja un izveda no tās alas pie viņa tos piecus ķēniņus, Jeruzālemes ķēniņu, Hebronas ķēniņu, Jarmutes ķēniņu, Lāķisas ķēniņu, Eglonas ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Un kad tie šos ķēniņus pie Jozuas bija izveduši, tad Jozuas sauca visus Israēla vīrus un sacīja uz tiem karavīru virsniekiem, kas viņam bija gājuši līdz: nākat klāt, liekat savas kājas uz šo ķēniņu kakliem, un tie piegāja un lika savas kājas uz viņu kakliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Un Jozuas uz tiem sacīja: nebīstaties un nebaiļojaties, esiet stipri un turat drošu prātu, jo tāpat Tas Kungs darīs visiem jūsu ienaidniekiem, ar ko jūs karojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Un pēc tam Jozuas viņus sita un nokāva, un pakāra pie pieciem kokiem, un tie palika pie kokiem pakārti līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Un ap to laiku, kad saule noiet, Jozuas pavēlēja tos noņemt no tiem kokiem, un tie tos nometa tai alā, kur tie bija apslēpušies, un lika lielus akmeņus priekš tās alas cauruma, kas tur ir līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Tai dienā Jozuas arī uzņēma Maķedu, un to kāva ar zobena asmeni, un viņš izdeldēja viņas ķēniņu, viņu pašu un visas dvēseles, kas tur bija; viņš neatlicināja neviena, un darīja Maķedas ķēniņam tā kā viņš bija darījis Jērikus ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Tad Jozuas aizgāja un viss Israēls ar viņu no Maķedas uz Libnu un karoja pret Libnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Un Tas Kungs to arīdzan nodeva Israēla rokā ar viņas ķēniņu, un viņš to kāva ar zobena asmeni un visas dvēseles, kas tur bija, viņš neatlicināja iekš tās neviena, un darīja viņas ķēniņam, kā viņš bija darījis Jērikus ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Tad Jozuas aizgāja un viss Israēls ar viņu no Libnas līdz Lāķisai, un apmetās pret viņu un karoja pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Un Tas Kungs nodeva Lāķisu Israēla rokā, un viņš to uzņēma otrā dienā un to kāva ar zobena asmeni, un visas dvēseles, kas tur bija; tā kā viņš Libnai bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tad Orams, Ģezeras ķēniņš, cēlās Lāķisai par palīgu, bet Jozuas to kāva un viņa ļaudis, kamēr viņš neviena no tiem neatlicināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Un Jozuas aizgāja un viss Israēls līdz ar viņu no Lāķisas uz Eglonu, un apmetās pret viņu un karoja pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Un uzņēma viņu tai pašā dienā, un to kāva ar zobena asmeni, un visas dvēseles, kas tur bija, viņš tai dienā izdeldēja, kā viņš bija darījis Lāķisai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Tad Jozuas cēlās un viss Israēls līdz ar viņu no Eglonas līdz Hebronei un karoja pret viņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Un uzņēma viņu un kāva viņu ar zobena asmeni un viņas ķēniņu ar visām pilsētām un ar visām dvēselēm, kas tur bija; viņš neatlicināja neviena, kā viņš Eglonai bija darījis, un to izdeldēja ar visām dvēselēm, kas tur bija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Tad Jozuas griezās atpakaļ un viss Israēls līdz ar viņu uz Debiru un karoja pret viņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Un uzņēma viņu un viņas ķēniņu un visas viņa pilsētas, un tos kāva ar zobena asmeni un izdeldēja visas dvēseles, kas tur bija; viņš neatlicināja neviena; itin kā viņš Hebronai bija darījis, tā viņš darīja Debirai un viņas ķēniņam, un itin kā viņš Libnai un viņas ķēniņam bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Tā Jozuas apkāva visu to zemi, kalnus un dienasvidus zemi un ieleju un pakalnus ar visiem viņu ķēniņiem: viņš neatlicināja neviena un izdeldēja visu, kam bija dvaša, tā kā Tas Kungs, Israēla Dievs, bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Un Jozuas tos kāva no Kādeš Barneas līdz Gazai, arī visu Gošena zemi līdz Gibeonai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Un Jozuas uzņēma visus šos ķēniņus un visu viņu zemi uz vienu reizi, jo Tas Kungs, Israēla Dievs, karoja par Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Tad Jozuas griezās atpakaļ un viss Israēls līdz ar viņu uz Gilgalas lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Un notika, kad Jabins, Hacoras ķēniņš, to dzirdēja, tad viņš sūtīja pie Jobaba, Madonas ķēniņa, un pie Šimronas ķēniņa un pie Akšafas ķēniņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Un pie tiem ķēniņiem, kas pret ziemeļiem kalnos un tai klajumā pret dienvidiem no Ķinerot un ielejā un kas Navot Dora jūrmalā dzīvoja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Pie Kanaāniešiem pret rītiem un vakariem un pie Amoriešiem un Hetiešiem un Fereziešiem un Jebusiešiem kalnos un pie Hiviešiem apakš Hermona, Micpas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Šie izgāja un visi karapulki līdz ar tiem un daudz ļaužu, tik daudz kā smiltis jūrmalā, un varen daudz zirgu un ratu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Visi šie ķēniņi sapulcējās un nāca un kopā apmetās lēģerī pie Meroma ūdens, karot pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Un Tas Kungs sacīja uz Jozua: nebīsties no viņiem, jo rītu ap šo laiku Es tos visus nodošu apkautus Israēla priekšā; viņu zirgus tev būs darīt tizlus un viņu ratus ar uguni sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Tad Jozuas un visi karaļaudis līdz ar viņu piepeši tiem uznāca pie Meroma ūdens un tiem uzbruka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Un Tas Kungs tos nodeva Israēla rokā, un tie tos kāva un tiem dzinās pakaļ līdz tai lielai Sidonai un līdz tiem siltiem ūdeņiem un līdz Micpas klajumam pret rītiem un tos kāva, kamēr neviens no tiem neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Un Jozuas tiem darīja, kā Tas Kungs viņam bija sacījis; viņu zirgus viņš darīja tizlus un viņu ratus viņš sadedzināja ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Un Jozuas griezās atpakaļ tanī laikā un uzņēma Hacoru, un viņas ķēniņu viņš sita ar zobenu, jo Hacora priekš tam bija galvas pilsēta visām šo ķēniņu valstīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Un tie kāva visus, kas tur bija, ar zobena asmeni, viņus izdeldēdami; tur neviens neatlika, kam bija dvaša, un Hacoru viņš sadedzināja ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Un Jozuas uzņēma visas šo ķēniņu pilsētas un visus viņu ķēniņus un tos kāva ar zobena asmeni, tos izdeldēdams, kā Mozus, Tā Kunga kalps, bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Bet visas pilsētas, kas stāv savos kalnos, Israēls nesadedzināja, tikai Hacoru Jozuas sadedzināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Un visu šo pilsētu laupījumu un visus lopus Israēla bērni laupīja priekš sevis, bet visus cilvēkus tie kāva ar zobena asmeni, tiekams tie tos izdeldēja; tie neatlicināja neviena, kam bija dvaša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Tā kā Tas Kungs Mozum, savam kalpam, bija pavēlējis, tā Mozus pavēlēja Jozuam, un tā Jozuas darīja; viņš neatrāva ne vārda no visa, ko Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tā Jozuas uzņēma visu šo zemi, kalnus un visu dienasvidus zemi un visu Gošenes zemi un ieleju un klajumu un Israēla kalnus ar viņu ieleju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'No Ālaka kalna, kas uz augšu stiepjas uz Seīru līdz Baāl-Gadam Lībanus klajumā, apakš Hermona kalna; viņš gūstīja arī visus viņu ķēniņus, tos sita un nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Ilgu laiku Jozuas pret visiem šiem ķēniņiem karoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Nevienas pilsētas nebija, kas ar labu Israēlim būtu padevusies, kā vien tie Hivieši, kas Gibeonā dzīvoja. Viņi visas uzņēma ar karošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Jo tas bija no Tā Kunga, ka tie savu sirdi apcietināja, karā iet pret Israēli, lai Viņš tos izdeldētu, lai tiem nekāda žēlastība nenotiktu, bet lai Viņš tos nomaitātu, kā Tas Kungs Mozum bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Tanī laikā Jozuas nāca un izsakņoja Enaķiešus no tiem kalniem, no Hebronas, no Debiras, no Ānabas, no visiem Jūda kalniem un no visiem Israēla kalniem, un Jozuas tos izdeldēja ar viņu pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Neviens no Enaķiešiem neatlika Israēla bērnu zemē, tik vien Gazā, Gatā un Ašdodā tie atlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Tā Jozuas uzņēma visu to zemi, tā kā Tas Kungs uz Mozu bija runājis, un Jozuas to Israēlim nodeva par iemantojamu tiesu, to dalīdams pēc viņu ciltīm, un zemei tika miers no karošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Šie nu ir tās zemes ķēniņi, ko Israēla bērni ir kāvuši un viņu zemi ieņēmuši, viņpus Jardānes pret saules uzlēkšanu no Arnonas upes līdz Hermona kalnam un visu klajumu pret rītiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihons, Amoriešu ķēniņš, kas Hešbonā dzīvoja, valdīdams no Aroēra, kas Arnonas upes malā, un no tās upes vidus, un par vienu Gileādas pusi un līdz Jabokas upei, kas ir Amona bērnu robeža,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Un par to klajumu līdz Ķinerotes jūrai pret rītiem, un līdz tai klajuma jūrai, tai sāls jūrai pret rītiem, uz to ceļu līdz BetJezimotam, un dienvidu pusē apakš Pizgas kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Un Oga, Basanas ķēniņa, robežas; tas bija atlicis no tiem milžu ļaudīm, un dzīvoja Astarotā un Edrejā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Un valdīja par Hermona kalnu un par Zalku un par visu Basanu līdz Gešuriešu un Maāhatiešu robežām un tai vienā Gileādas pusē līdz Sihona, Hešbonas ķēniņa, robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mozus, Tā Kunga kalps, un Israēla bērni tos kāva, un Mozus, Tā Kunga kalps, to deva Rūbeniešiem un Gadiešiem un Manasus pusciltij par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Šie nu ir tās zemes ķēniņi, ko Jozuas un Israēla bērni kāva šaipus Jardānes pret vakariem, no Baāl-Gada Lībanus lejā līdz Ālaka kalnam, kas uz Seīru stiepjas, (un Jozuas to deva Israēla ciltīm par īpašumu pēc viņu daļām,)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Kalnos un ielejās un klajumos un pakalnos un tuksnesī un pret dienasvidu: Hetieši, Amorieši, Kanaānieši, Ferezieši, Hivieši un Jebusieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Jērikus ķēniņš viens; Ajas ķēniņš, kas sānis Bētelei, viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Jeruzālemes ķēniņš viens; Hebrones ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Jarmutes ķēniņš viens; Lākisas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Eglonas ķēniņš viens; Ģezeras ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Debiras ķēniņš viens; Ģederas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Hormas ķēniņš viens; Aradas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Libnas ķēniņš viens; Adulamas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Maķedas ķēniņš viens; Bēteles ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Tapuas ķēniņš viens; Heferas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Afekas ķēniņš viens; LāŠaronas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Madonas ķēniņš viens; Hacoras ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Šimron-Meronas ķēniņš viens; Akšafas ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Taēnakas ķēniņš viens; Meģidus ķēniņš viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Kēdesas ķēniņš viens; Jokneamas ķēniņš pie Karmeļa viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Doras ķēniņš Navat-Dorā viens; Gojimu ķēniņš Gilgalā viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Tircas ķēniņš viens; visi šie ķēniņi ir trīsdesmit un viens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Un Jozuas bija vecs un stipri gados un Tas Kungs sacīja uz viņu: tu esi palicis vecs un stipri gados, un vēl ļoti daudz zemes atliek kas jāuzņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Šī ir tā zeme, kas vēl atliek: visas Fīlistu robežas un visas Gešuriešu robežas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'No Šihora, kas ir Ēģiptes priekšā, līdz Ekronas robežai pret ziemeļiem Kanaāniešiem top pieskaitīti pieci Fīlistu lielkungi: Gaziešu, Ašdodešu, Askaloniešu, Gatiešu un Ekroniešu lielskungs, un arī Avieši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'No dienasvidus puses visa Kanaāniešu zeme un Meara, kas Sidoniešiem pieder, līdz Afekai, līdz Amoriešu robežām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Tā arī Ģibliešu zeme un viss Lībanus no rīta puses, no Baāl-Gada apakš Hermona kalna, kamēr nāk uz Hamatu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Visi, kas tais kalnos dzīvo, no Lībanus līdz tiem siltiem ūdeņiem, visi Sidonieši, Es tos izdzīšu Israēla bērnu priekšā; izdali to tikai Israēlim par īpašumu, kā Es tev esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Un nu dali šo zemi par iemantojamu tiesu tām deviņām ciltīm un Manasus pusciltij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Līdz ar to (otru puscilti) Rūbenieši un Gadieši ir dabūjuši savu iemantojamo tiesu, ko tiem Mozus deva viņpus Jardānes pret rītiem, tā kā Mozus, Tā Kunga kalps, tiem devis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'No Aroēra, kas ir Arnonas upes malā, un tās pilsētas kas ir upes ielejas vidū, un visu klajumu no Medbas līdz Dibonai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Un līdz Amona bērnu robežām visas pilsētas, kas piederēja Sihonam, Amoriešu ķēniņam, Hešbonas valdniekam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Un Gileādu un Gešuriešu un Maāhatiešu robežas, un visu Hermona kalnu un visu Basanu līdz Zalkai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Visu Oga, Basanas ķēniņa, valsti, kas valdīja Astarotā un Edrejā, un bija atlicis no tiem atlikušiem milžiem, ko Mozus ir apkāvis un izdzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Bet Israēla bērni neizdzina Gešuriešus un Maāhatiešus, bet Gešurs un Maāhats dzīvoja Israēla vidū līdz šai dienai. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Tikai Levja ciltij viņš nedeva zemes daļu; Tā Kunga, Israēla Dieva, uguns upuri ir viņas daļa, tā kā viņš tai ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Un Mozus deva Rūbena bērnu ciltij pēc viņas radiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Ka viņu robežas bija no Aroēra, kas Arnonas upes malā, un tā pilsēta, kas ir ielejas vidū, un viss klajums līdz Medbai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hešbona un visas viņas pilsētas kas tai klajumā, Dibona un Bamot-Baāla un Bet-Baāl-Meona,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Un Jāca un Ķedemote un Mevaāte');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Un Kiriataīma un Sibma un Ceret-Zaūra uz tā kalna tai ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Un Bet-Peore un Ašdod-Pizga un Bet-Jezimote');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Un visas klajuma pilsētas un visa Sihona valsts, Sihona, Amoriešu ķēniņa, kas Hešbonā valdīja, ko Mozus apkāva līdz ar Midijanas lieliem kungiem, Evu un Reķimu un Curu un Huru un Rebu, Sihona valdniekiem, kas tai zemē dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Tāpat Israēla bērni ar zobenu nokāva Bileāmu, Beora dēlu, to pareģi, līdz ar tiem (citiem), ko viņi nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Un Rūbena bērnu robeža bija Jardāne un viņas apgabals. Šī ir Rūbena bērnu daļa pēc viņu radiem, pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Un Gada ciltij, Gada bērniem pēc viņu radiem Mozus deva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Ka viņu robežas bija Jaēzere un visas Gileādas pilsētas un Amona bērnu zemes viena puse līdz Aroēram, kas ir šaipus Rabas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Un no Hešbonas līdz Rāmat-Micpai un Betanim un no Mahānaīm līdz Debiras robežai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Un ielejā: BetHarama un Bet-Nimra un Sukota un Cavana, kas atlika no Sihona, Hešbonas ķēniņa, valsts, Jardāne un viņas robeža, līdz Ķinerotes jūras galam viņpus Jardānes pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Šī ir Gada bērnu daļa pēc viņu radiem, pilsētas un ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Un ko Mozus Manasus pusciltij par daļu bija devis, tas palika pie Manasus bērnu puscilts pēc viņas radiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Tā ka viņu robežas bija no Mahānaīm visa Basana, visa Oga, Basanas ķēniņa, valsts un visi Jaīra miesti, kas ir Basanā, sešdesmit pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Un Gileādas viena puse un Astarote un Edreja, Oga, Basanas ķēniņa, valsts pilsētas, piederēja Mahira, Manasus dēla, bērniem, (proti) Mahira bērnu pusei pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'To nu Mozus bija izdalījis Moaba klajumos viņpus Jardānes no Jērikus pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Bet Levja ciltij Mozus nedeva nekādu zemes daļu; Tas Kungs, Israēla Dievs, ir viņu daļa, tā kā Viņš tiem ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'To nu Israēla bērni iemantojuši Kanaāna zemē, ko viņiem ir izdalījuši Eleazars, tas priesteris, un Jozuas, Nuna dēls, un tie augstie Israēla bērnu cilts tēvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Caur meslošanu tiem dalīja, kā Tas Kungs caur Mozu bija pavēlējis, dot tām deviņām ciltīm un tai pusciltij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Jo tām divām ciltīm un tai pusciltij Mozus bija devis daļu viņpus Jardānes, bet Levitiem viņš nekādu zemes daļu nebija devis viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Jo Jāzepa bērnu bija divas ciltis, Manasus un Efraīms; un Levitiem nedeva nekādu īpašu daļu tai zemē, bet pilsētas vien, kur dzīvot, un ganības priekš viņu lopiem un priekš viņu īpašuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Kā Tas Kungs Mozum bija pavēlējis, tā Israēla bērni darīja un izdalīja to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Tad Jūda bērni piegāja pie Jozuas Gilgalā, un Kālebs, Jefunna dēls, no Ķenasa bērniem, sacīja uz viņu: tu zini to vārdu, ko Tas Kungs uz Mozu, to Dieva vīru, ir runājis Kādeš Barneā manis pēc un tevis pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Es biju četrdesmit gadus vecs, kad Mozus, Tā Kunga kalps, mani sūtīja no Kādeš Barneas, to zemi izlūkot, un es viņam atsacīju, tā kā tas bija manā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Bet mani brāļi, kas man bija gājuši līdz, tie darīja to ļaužu sirdi bailīgu, bet es Tam Kungam, savam Dievam, pareizi klausīju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Tad Mozus tai dienā zvērēja un sacīja: tā zeme, kur tu ar savu kāju esi minis, tev un taviem bērniem būs par daļu mūžam; jo tu Tam Kungam, manam Dievam, esi pareizi klausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Un nu redzi, Tas Kungs manu dzīvību ir uzturējis, tā kā Viņš ir runājis, un ir četrdesmit un pieci gadi no tā laika, kad Tas Kungs šo vārdu uz Mozu runāja, Israēlim tuksnesī staigājot, un nu redzi, es šodien esmu astoņdesmit piecus gadus vecs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Es vēl šodien esmu tik stiprs, kā tai dienā kad Mozus mani izsūtīja; kāds mans spēks bija to brīdi, tāds ir mans spēks šo brīdi uz karu, uz iziešanu un ieiešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Un nu, dod man šo kalnu zemi, par ko Tas Kungs tai dienā runājis, jo tu tai dienā esi dzirdējis, ka tur dzīvo Enaķieši, un tur ir lielas stipras pilsētas; varbūt Tas Kungs būs ar mani, ka es tos varu izdzīt, tā kā Tas Kungs runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Tad Jozuas viņu svētīja un deva Kālebam, Jefunna dēlam, Hebroni par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Tā tad Hebrone Kālebam, Jefunna dēlam, no Ķenasa bērniem, tika par daļu līdz šai dienai, tāpēc ka tas Tam Kungam, Israēla Dievam, pareizi bija klausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Bet Hebrones vārds bija vecos laikos Kiriat Arba (Arbas pilsēta), tas ir bijis viens liels cilvēks starp Enaķiešiem. Un zemei bija miers no karošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Un tā nomeslota tiesa priekš Jūda bērniem, pēc viņu radiem, bija pie Edoma robežām, pie Cin tuksneša, pašā dienvidus galā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Tā ka viņu robeža pret dienvidiem bija Sāls jūras gals no tās mēles, kas pret dienvidiem stiepjas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Un iziet pret dienvidu pusi uz Akrabu kalniem un iet cauri līdz Cinam un iet uz augšu no dienvidu puses līdz Kādeš-Barneai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Un iet caur Acronu un stiepjas uz augšu līdz Ādarai un iet ap Karku un iet cauri līdz Acmonai un iznāk pie Ēģiptes upes, un tas robežas gals stiepjas pret jūru; šī lai ir jūsu robeža dienas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Un robeža pret rītiem ir sāls jūra līdz Jardānes galam, un robeža ziemeļa pusē ir no jūras mēles, no Jardānes gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Un šī robeža iet uz augšu līdz Bet-Aglai un iet cauri no ziemeļa puses līdz Bet-Arabai, un tā robeža iet uz augšu līdz Boēna, Rūbena dēla, akmenim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Un (tālāk) šī robeža iet uz augšu līdz Debirai no Ahora ielejas un pret ziemeļiem stiepjas līdz Gilgalai, kas stāv pret Adumu kalniem, kas no upes uz dienvidiem; pēc šī robeža iet cauri uz En-Zemes ūdeni, un viņas gals stiepjas līdz Roģeles akai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Un šī robeža iet uz augšu pa Ben-Inoma ieleju, no dienvidu puses gar Jebuzu, - šī ir Jeruzāleme, - un šī robeža iet uz augšu līdz tā kalna virsgalam, kas no Inoma ielejas ir pret vakara pusi, kas stiepjas līdz Refaīm ielejas galam pret ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Pēc šī robeža stiepjas no tā kalna gala līdz Nevtoas avotam un iznāk uz Efrona kalna pilsētām; šī robeža stiepjas līdz Baālai, - tā ir Kiriat-Jearima.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Pēc šī robeža griežas no Baālas uz vakara pusi līdz Seīra kalniem un iet cauri gar ArJearim uz ziemeļa pusi, - tas ir Ķesalons, - un nāk lejā uz Bet-Šemesu un iet caur Timnatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Un tā robeža iznāk gar Ekronu pret ziemeļa pusi un stiepjas līdz Zikronam un iet pār Baālas kalnu un iznāk uz Jabneēlu, un viņas gals stiepjas līdz jūrai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Un robeža pret vakara pusi ir tā lielā jūra un viņas mala. Šī ir Jūda bērnu robeža visapkārt pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Bet Kālebam, Jefunna dēlam, viņš deva tiesu starp Jūda bērniem, pēc Tā Kunga vārda uz Jozua, proti Kiriat-Arbu, Eneka tēva pilsētu, tā ir Hebrone.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Un Kālebs izdzina no turienes tos trīs Enaka dēlus, Zezaju un Aķimanu un Talmaju, kas no Enaka dzimuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Un no turienes viņš cēlās pret Debiras iedzīvotājiem, bet Debiras vārds senāk bija Kiriat-Zevere.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Un Kālebs sacīja: kas Kiriat-Zeveri kaus un uzņems, tam es savu meitu Aksu došu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Tad to uzņēma Otniēls, Ķenasa dēls, Kāleba brālēns, un viņš tam deva savu meitu Aksu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Un notikās, kad viņa pie tā nāca, tad viņa to skubināja, tīrumu lūgties no viņas tēva, un viņa nolēca no ēzeļa; tad Kālebs uz viņu sacīja: kas tev ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Un viņa sacīja: dod man kādu svētību, jo tu man esi devis dienvidu zemi, tad dod man arī ūdens avotus. Tad tas viņai deva avotus augšā un avotus ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Šī ir Jūda bērnu cilts daļa pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Tad nu tās pilsētas no Jūda bērnu cilts gala līdz Edoma robežai pret dienvidu pusi ir: Kabceēle un Edere un Jagura');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Un Ķina un Dimona un Ādada');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Un Ķedesa un Ācora un Itnana');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Un Zīva un Telema un Bealota');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Un Ācor-ādāta un Kiriat-Hecrona, - tā ir Ācora, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Āmama un Šema un Molada');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Un Ācar Gada un Ezmona un Betpaleta');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Un Ācar-Zuala un Bēršeba un Bisjot-Ja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Bala un Ijim un Ācēma');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Un Eldolada un Ķezila un Horma');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Un Ciklaga un Madmana un Zan-Zana');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Un Lebaota, Zilim un Aīna un Rimona, - visu šo pilsētu ir divdesmit deviņas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Lejā ir Estaole un Carea un Asna');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Un Zanoa un En-Ganim, Tapua un Enama');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Un Jarmute un Adulama un Zukus un Āzeka');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Un Zaēraīm un Aditaīm un Gedera un Ģederotaīm, četrpadsmit pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Cenana un Adaza un Migdal Gada');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Un Dileana un Micpa un Jaktiēle,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lāķis un Bockata un Eglone');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Un Kābona un Lāmasa un Ķitlisa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Un Ģederota, BetDagona un Naēma un Maķeda, sešpadsmit pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna un Etere un Āzana');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Un Jevta un Azna un Necibe');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Un Ķeīla un Aksiba un Mareza, deviņas pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekrona un viņas miesti un viņas ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'No Ekronas un līdz jūrai viss, kas blakām Ašdodai un blakām viņu ciemiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Ašdoda un viņas miesti, un viņas ciemi, Gaza un viņas miesti, un viņas ciemi līdz Ēģiptes upei un tai lielai jūrai un viņas malai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Un kalnos bija Zamira un Jatira un Zokus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Un Dana, un Kiriat-Zana, - tā ir Debira -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Un Ānaba un Estemus un Ānim');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Un Gošene un Holone un Šīlo, vienpadsmit pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arāba un Duma un Ezeaņa un Januma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Un Bet-Tapua un Āveka');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Un Umta un Kiriat-Arba, - tā ir Hebrone, - un Ciora, deviņas pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maona, Karmelis un Zīva un Jūta');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Un Jezreēle un Jokdeama un Zanoa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kaina, Ģibea un Timna, desmit pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Alula, Bet-Cura, Gedora');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Un Maārata un Bet-Anota un Eltekone, sešas pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kiriat-Baāla, - tā ir Kiriat-Jearima, - un Arāba, divas pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Tuksnesī bija Bet-Araba, Midina un Zekaka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Un Nibzana un tā sāls pilsēta un Enģedi, sešas pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Bet tos Jebusiešus, kas Jeruzālemē dzīvoja, Jūda bērni nevarēja izdzīt un Jebusieši dzīvoja pie Jūda bērniem Jeruzālemē līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Un tā tiesa Jāzepa bērniem tapa nomeslota no Jardānes pret Jēriku, pie Jērikus ūdeņiem pret rītiem, tas tuksnesis, kas no Jērikus stiepjas caur Bēteles kalniem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Un iznāk no Bēteles uz Lūzu un tek caur Arķiešu robežām līdz Atarotai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Un noiet pret vakara pusi uz Javletes robežām līdz Lejas-Bet-Oronas robežām un līdz Gazerai, un viņas gals stiepjas līdz jūrai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Tā Jāzepa bērni, Manasus un Efraīms, savu daļu dabūjuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Un Efraīma bērnu robeža pēc viņu radiem ir šī: viņu daļas robeža bija pret rītiem Atarot Ādara līdz Kalna-Bet-Oronai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Un tā robeža iznāk no vakara puses gar Miķmetu pa ziemeļa pusi, un šī robeža griežas pret rītiem uz Taēnat Šīlo un iet caur viņu uz rīta pusi līdz Janoai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Un notek no Janoas uz Atarotu un Naāratu, un stiepjas uz Jēriku un iznāk pie Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'No Tapuas tā robeža stiepjas pret vakara pusi uz Kānas upi, un viņas gals ir pie jūras. Šī ir Efraīma bērnu cilts daļa pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Un tās pilsētas, kas bija atšķirtas priekš Efraīma bērniem, bija Manasus bērnu daļas vidū, visas tās pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Un tie neizdzina tos Kanaāniešus, kas Gazerā dzīvoja, tā Kanaānieši dzīvoja Efraīma vidū līdz šai dienai un palika par klausītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Un Manasus ciltij tiesa tika nomeslota, - jo viņš bija Jāzepa pirmdzimtais, - Mahiram, Manasus pirmdzimtam, Gileāda tēvam, kas bija karavīrs, krita Gileāda un Basana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Un tiem citiem Manasus bērniem tika sava tiesa pēc viņu radiem, (proti) Abiēzera bērniem un Eleka bērniem un Asriēļa bērniem un Zeķema bērniem un Hefera bērniem un Zemida bērniem. Šie ir Manasus, Jāzepa dēla, bērni no vīriešu kārtas pēc saviem radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Bet Celofehadam, Hefera dēlam, (tas bija dēls Gileādam, tas Mahiram, tas Manasum) tam nebija dēlu, bet meitas vien, un šie ir viņa meitu vārdi: Maāla, Noa, Hagla, Milka un Tirca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Tās nāca pie priestera Eleazara un pie Jozuas, Nuna dēla, un pie tiem virsniekiem un sacīja: Tas Kungs Mozum pavēlējis, mums daļu dot mūsu brāļu vidū; tāpēc viņš pēc Tā Kunga vārda tām deva daļu viņu tēva brāļu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Un Manasum desmit zemes gabali tapa piedalīti, bez Gileādas zemes un Basanas, kas viņpus Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Jo Manasus meitas iemantoja īpašu daļu viņa dēlu vidū, un Gileādas zeme piederēja tiem citiem Manasus bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Un Manasus robeža bija no Ašeras līdz Mikmetai, kas Šehemes priekša, un šī robeža iet pa labo roku uz tiem, kas En-Tapuā dzīvoja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Un Manasum gan piederēja Tapuas zeme, bet pati Tapua pie Manasus robežas piederēja Efraīma bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Un tā robeža nonāk uz Kānas upi pret dienasvidu no upes. Šīs pilsētas pieder Efraīmam, Manasus pilsētu vidū, un Manasus robeža ir no tās upes uz ziemeļa pusi, un viņas gals stiepjas pret jūru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Kas pret dienvidiem, pieder Efraīmam, un kas pret ziemeļiem, Manasum, un jūra ir viņu robeža. Un uz ziemeļa pusi viņi stiepjas līdz Ašeram, un uz rīta pusi līdz Īsašaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Un Manasum iekš Īsašara un Ašera piederēja Bet-Zeana un viņas miesti un Jibleana un viņas miesti un Doras iedzīvotāji un miesti un Endoras iedzīvotāji un miesti un Taēnakas iedzīvotāji un miesti un, kas iekš Meģidus dzīvoja, un viņa miesti, - trīs zemes gabali');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Un Manasus bērni nevarēja izdzīt šo pilsētu iedzīvotājus, bet Kanaānieši iesāka palikt tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Un kad Israēla bērni palika stipri, tad tie tos Kanaāniešus spieda pie klausības, bet izdzīt tos neizdzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Un Jāzepa bērni runāja uz Jozua sacīdami: kāpēc tu mums par daļu esi nomeslojis tikai vienu tiesu un vienu zemes gabalu? Un mēs tomēr esam liels ļaužu pulks, tādēļ ka Tas Kungs mūs tā ir svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Tad Jozuas uz tiem sacīja: ja jūs esiet tāds liels ļaužu pulks, tad ejat mežos un nolīdiet tos priekš sevis Veresiešu un Revaiešu zemē, kad jums nepietiek ar Efraīma kalniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Tad Jāzepa bērni sacīja: ar tiem kalniem mums nepietiks, un dzelzs rati ir visiem Kanaāniešiem, kas tai ielejas zemē dzīvo, Bet-Zeanā un viņas miestos, un tiem, kas Israēla klajumā dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Bet Jozuas runāja uz Jāzepa namu, uz Efraīmu un Manasu, sacīdams: tu esi liels ļaužu pulks un tev ir liels spēks, tev nebūs viena daļa vien,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Bet tie kalni tev piederēs; tur ir mežs un to tu nolīdisi un viņa malas tev piederēs. Jo tu izdzīsi tos Kanaāniešus, jebšu tiem ir dzelzs rati un jebšu tie ir stipri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Un visa Israēla bērnu draudze sapulcējās Šīlo un tur uzcēla saiešanas telti, kad nu zeme viņu priekšā bija uzvarēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Un no Israēla bērniem, kam savas daļas nebija nodalītas, atlika septiņas ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Un Jozuas sacīja uz Israēla bērniem: cik ilgi jūs esat tik kūtri, ka nenoejat uzņemt to zemi, ko Tas Kungs, jūsu tēvu Dievs jums devis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Dabūjiet sev trīs vīrus no ikvienas cilts, tad es tos sūtīšu, lai tie ceļas un zemi pārstaigā un to uzraksta pēc savām daļām, un griežas atpakaļ pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Tiem nu to būs dalīt septiņās daļās; Jūda lai paliek savās robežās no dienasvidus puses, un Jāzepa nams lai paliek savās robežās no ziemeļa puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Un jums to zemi būs uzrakstīt septiņās daļās un atnest man, ka es priekš jums šeit mesloju Tā Kunga, mūsu Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Jo Levitiem nav nekādas zemes daļas jūsu starpā, bet Tā Kunga priestera amats ir viņu daļa. Bet Gads un Rūbens un Manasus puscilts savu tiesu ir ņēmuši viņpus Jardānes pret rītiem, ko Mozus, Tā Kunga kalps, tiem devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Tad tie vīri cēlās un nogāja, un Jozuas tiem, kas nogāja, pavēlēja zemi uzrakstīt, un sacīja: ejat, un pārstaigājat to zemi un uzrakstiet to un griežaties atpakaļ pie manis, tad es priekš jums metīšu meslus Tā Kunga priekšā šeitan Šīlo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Tad tie vīri nogāja un pārstaigāja to zemi un to pēc viņas pilsētām grāmatā uzrakstīja septiņās daļās, un nāca atpakaļ pie Jozuas uz lēģeri Šīlo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Un Jozuas meta meslus priekš viņiem Šīlo Tā Kunga priekšā, un Jozuas tur Israēla bērniem dalīja to zemi pēc viņu daļām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Un mesli krita Benjamina bērnu ciltij pēc viņu radiem, un viņu nomeslotās tiesas robeža stiepjas starp Jūda bērniem un Jāzepa bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Un viņu ziemeļa robeža nāca no Jardānes, un šī robeža iet augšā gar Jērikus ziemeļa pusi un stiepjas caur tiem kalniem pret vakara pusi un viņas gals ir pie Bet-Avenas tuksneša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Un no turienes robeža aiziet uz Lūzu, gar Lūzu, - šī ir Bētele, - pret dienasvidu, un robeža noiet uz Atarot-Ādaru pie tā kalna, kas ir dienasvidus pusē no Lejas-Bet-Oronas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Un šī robeža stiepjas un griežas vakara malā uz dienasvidu, no tā kalna, kas ir Bet-Oronai pretī uz dienasvidu, un viņas gals ir pie Kiriat-Baālas, - šī ir Kiriat-Jearima, Jūda bērnu pilsēta, - šī ir vakara puses mala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Un dienasvidus mala stiepjas no Kiriat-Jearimas gala, un šī robeža iznāk no vakara puses un iziet uz Nevtoas avotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Un šī robeža noiet līdz tā kalna galam, kas ir Inoma dēla ielejai pretī, Revaiešu ielejā pret ziemeļiem un noiet caur Inoma ieleju gar Jebusiešiem pret dienasvidu un noiet līdz Roģeles avotam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Un stiepjas uz ziemeļa pusi un iznāk uz En-Zemesu un iziet uz Ģililotu, kas stiepjas pret Adumim, un noiet uz Boēna, Rūbena dēla, akmeni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Un iet pāri gar to klajumu uz ziemeļa pusi un noiet uz to klajumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Un šī robeža iet pāri gar Bet-Aglu pret ziemeļiem, un šās robežas gals ir pie sāls jūras mēles pret ziemeļiem, pie Jardānes gala dienas vidū; šī ir dienvidu robeža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Un Jardāne ir viņa robeža rīta pusē; šī ir Benjamina bērnu daļa pēc viņu robežām visapkārt, pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Bet Benjamina bērnu cilts pilsētas pēc viņu radiem ir: Jērikus un Bet-Agla un Emek-Ķecica');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Un Bet-Araba un Cemaraīm un Bētele.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Un Avim un Para un Ovra');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Un Kavar-Amonaja un Ovni un Gaba, divpadsmit pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeona un Rāma un Beērote');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Un Micpa un Ķevira un Moca');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Un Reķeme un Jerpeēle un Tareala');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Un Cela, Eleve un Jebuzi, - šī ir Jeruzāleme, - Ģibeata, Kiriata, četrpadsmit pilsētas un viņu ciemi. Šī ir Benjamina bērnu daļa pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Un otri mesli krita Sīmeanam, Sīmeana bērnu ciltij pēc viņu radiem, un viņu nomeslota tiesa bija Jūda bērnu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Un tiem bija par daļu: Bēršeba un Zeba un Moloda');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Un Hacar-Šuale un Bala un Aceme');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Un Eltolade un Betule un Horma');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Un Ciklaga un Bet-Markabote un Acar-Zusa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Un Betlebaote un Zaruēne, trīspadsmit pilsētas un viņu ciemi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Aīna, Rimona un Etere un Azane, četras pilsētas un viņu ciemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Un visi ciemi šo pilsētu apgabalā līdz Baālat-Beērei, dienasvidus Rāmatai; šī ir Sīmeana bērnu cilts daļa pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Sīmeana bērnu daļa ir Jūda bērnu zemē, jo Jūda bērnu tiesa tiem bija par lielu, tāpēc Sīmeana bērni mantoja viņu daļas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Un trešie mesli krita Zebulona bērniem pēc viņu radiem, un viņu daļas robeža stiepjas līdz Zaridei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Un viņu robeža iet uz augšu pret vakara pusi uz Marealu, un tek līdz Dabazetei un stiepjas līdz tai upei, kas šaipus Jokneama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Un viņa griežas no Zarides pret rītiem pret saules lēkšanu, uz Ķislot-Tābora robežām, un iznāk pie Dobrates un stiepjas līdz Javiai;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Un no turienes viņa iet pret rītiem, pret saules lēkšanu, uz GatEveru, Iti, Kacini un iznāk pie Rimona, sniegdamās līdz Neai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Un šī robeža griežas apkārt pret ziemeļa pusi uz Kanatonu, un viņas gals ir Jevtaēles ieleja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Un Katāte un Nahāle un Šimrona un Jedeala un Bētleme, divpadsmit pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Šī ir Zebulona bērnu daļa pēc viņu radiem, šīs pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Ceturtie mesli krita Īsašaram, Īsašara bērniem pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Un viņu robežas bija Jezreēls, Ķezulote un Šuneme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Un Avaraīm un Sihons un Anaārot');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Un Rabita un Ķiseons un Abeca');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Un Remeta un Enganim un Enada un Bet-Paceca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Un šī robeža stiepjas un Tāboru un Zaācimu un Bet-Šemesu un viņu robežas gals ir pie Jardānes: sešpadsmit pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Šī ir Īsašara bērnu cilts daļa, pēc viņu radiem, pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Un piektie mesli krita Ašera bērniem pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Un viņu robežas bija Elkate un Alus un Betene un Aksave');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Un Alameleķs un Ameada un Mizeala, un stiepjas uz Karmeli pie jūras un uz Šihor-Libnatu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Un griežas pret saules lēkšanu uz Bet-Dagonu un stiepjas uz Zebulonu un uz JevtaEles ieleju pret ziemeļiem no Bet-Emeka un Neģiēla un iznāk uz Kabalu pa kreiso roku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Un uz Hebronu un Reobu un Amonu un Kānu līdz lielai Sidonai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Un šī robeža griežas uz Ramu un uz stipro Tirus pilsētu, tad šī robeža griežas uz Osu, un viņas gals ir pie jūras, blakām Aksibes robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Un Umma un Afeks un Reobe: divdesmit divas pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Šī ir Ašera bērnu cilts daļa pēc viņu radiem, šīs pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Sestie mesli krita Naftalus bērniem pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Un viņu robeža ir no Eleves, no tā ozola pie Caēnanim, un Adami-Neķebes un Jabneēļa līdz Lakum, un viņas gals ir pie Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Un šī robeža griežas pret vakara pusi uz Asnot-Tāboru, un no turienes viņa noiet uz Ukoku, un stiepjas uz Zebulonu pret dienasvidu, un pie Ašera viņa stiepjas pret vakara pusi, un pie Jūda līdz Jardānei pret saules lēkšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Un stipras pilsētas ir: Cidim, Cera un Amata, Rākata un Ķinerete');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Un Ādama un Rāma un Hacore');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Un Ķedesa un Edreji un EnAcore');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Un Jereons un MigdalEle, Oreme un Bet-Anata un BetŠemes, deviņpadsmit pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Šī ir Naftalus bērnu cilts daļa pēc viņu radiem, pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Septītie mesli krita Dana bērnu ciltij pēc viņu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Un viņu daļas robežas bija Carea un Estaole un Irzameze');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Un Zaēlabina un Ajalone un Jetla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Un Elona un Timnata un Ekrona');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Un Elteķe un Ģibetonā un Baālate,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jeūde un Bne-Barata un Gat-Rimona,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Un Mejarkona un Rakona, ar to robežu pret Joppi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Bet Dana bērnu robežas kļuva lielākas, jo Dana bērni cēlās un karoja pret Lezemu un to uzņēma un to sita ar zobena asmeni un to iemantoja un tur dzīvoja, un nosauca Lezemu par Danu pēc sava tēva Dana vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Šī ir Dana bērnu cilts daļa pēc viņu radiem, pilsētas un viņu ciemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Un kad tie nu bija beiguši zemi izdalīt pēc viņas robežām, tad Israēla bērni Jozuam, Nuna dēlam, deva daļu savā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Pēc Tā Kunga vārda tie viņam deva to pilsētu, ko viņš prasīja, Timnat-Zeru Efraīma kalnos, un viņš uztaisīja to pilsētu un tur dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Tās ir tās daļas, ko priesteris Eleazars, un Jozuas, Nuna dēls, un tie cilts tēvi Israēla bērnu ciltīm caur mesliem izdalīja Šīlo Tā Kunga priekšā pie saiešanas telts durvīm un tā tie pabeidza zemes izdalīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Un Tas Kungs runāja uz Jozua un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Runā uz Israēla bērniem un saki: noliekat sev glābšanās pilsētas, par kurām Es uz jums esmu runājis caur Mozu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Ka uz turieni var bēgt tas nokāvējs, kas kādu dvēseli no nejauši nezinādams nokauj, ka tās jums var būt par patvēruma no asins atriebēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Un kurš uz kādu no šīm pilsētām bēg, tam pie pilsētas vārtiem būs stāvēt, un savus vārdus runāt priekš pilsētas vecaju ausīm; tad tie viņu lai uzņem pie sevis pilsētā un viņam dod vietu, ka viņš pie tiem var dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Un kad tas asins atriebējs viņam dzenās pakaļ, tad lai tie to nokāvēju viņam nedod rokā, tāpēc ka viņš nezinādams savu tuvāko nokāvis, un viņu iepriekš nav ienīdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Tad tam tai pilsētā būs dzīvot, tiekams viņš draudzes priekšā būs stāvējis uz tiesu, līdz kamēr tas augstais priesteris būs miris, kas tanīs dienās būs, tad lai tas nokāvējs griežas atpakaļ un iet savā pilsētā un savā namā, tai pilsētā, no kurienes viņš izbēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Tad tie iesvētīja Ķedesu Galilejā Naftalus kalnos, un Šehemi Efraīma kalnos, un ĶniatArpu, - tā ir Hebrone, - Jūda kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Un viņpus Jardānes, no Jērikus pret rītiem, tie deva Beceru tuksnesi Rūbena cilts klajumā, un Golanu Basanā no Manasus cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Šīs tās noliktās pilsētas priekš visiem Israēla bērniem un priekš svešiniekiem viņu starpā, ka uz turieni bēgtu ikkatrs, kas cilvēku nejauši nokauj, ka tam nebūtu jāmirst caur asins atriebēja roku, pirms nebūtu stāvējis draudzes priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Tad Levitu cilts tēvi piegāja pie priestera Eleazara un pie Jozuas, Nuna dēla, un pie Israēla bērnu cilts tēviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Un runāja uz tiem Šīlo Kanaāna zemē, sacīdami: Tas Kungs caur Mozu pavēlējis, mums dot pilsētas, kur varam dzīvot, ar ganībām priekš mūsu lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Tad Israēla bērni Levitiem deva no savām daļām pēc Tā Kunga vārda šīs pilsētas un viņu ganības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Un mesli krita Kehāta radiem. Un priestera Ārona bērniem no Levitiem caur mesliem krita trīspadsmit pilsētas no Jūda cilts un no Sīmeana cilts un no Benjamina cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Un tiem citiem Kehāta bērniem caur mesliem krita desmit pilsētas no Efraīma cilts radiem un no Dana cilts un no Manasus puscilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Un Geršona bērniem caur mesliem krita trīspadsmit pilsētas no Īsašara cilts radiem un no Ašera cilts un no Naftalus cilts un no Manasus puscilts Basanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merarus bērniem pēc viņu radiem krita divpadsmit pilsētas no Rūbena cilts un no Gada cilts un no Zebulona cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Tā Israēla bērni Levitiem deva caur meslošanu šīs pilsētas un viņu ganības, kā Tas Kungs caur Mozu bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Un no Jūda bērnu cilts un no Sīmeana bērnu cilts tie deva šīs pilsētas, ko pie vārda nosauca,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Ka tie piederētu Ārona bērnu bērniem, no Kehāta radiem, no Levja bērniem; jo tie pirmie mesli viņiem krita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Un tie tiem deva Kiriat-Arbu, Enaka tēva pilsētu, tā ir Hebrone Jūda kalnos un viņas apkārtējās ganības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Bet tās pilsētas tīrumu un līdz ar viņas ciemiem tie deva Kālebam, Jefunna dēlam, par dzimtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Un tie deva priestera Ārona bērniem to glābšanas pilsētu priekš nokāvējiem, Hebroni un viņas ganības, un Libnu un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Un Jatiru un viņas ganības, un Estemou un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Un Holonu un viņas ganības, un Debiru un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Un Aīnu un viņas ganības, un Jūtu un viņas ganības, un BetŠemesu un viņas ganības, - deviņas pilsētas no šīm divām ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Un no Benjamina cilts: Gibeonu un viņas ganības, Ģebu un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Un Anatotu un viņas ganības, un Almonu un viņas ganības, - četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Pavisam priestera Ārona dēliem bija trīspadsmit pilsētas ar savām ganībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Bet Kehāta bērnu radiem, tiem Levitiem, tiem citiem Kehāta bērniem krita caur mesliem tās pilsētas no Efraīma cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Un tiem deva Šehemi, to glābšanās pilsētu priekš nokāvējiem, un viņas ganības Efraīma kalnos, un Ģezeru un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Un Ķibcaīm un viņas ganības, un Bet-Oronu un viņas ganības, četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Un no Dana cilts: Elteku un viņas ganības, un Ģibetonu un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Un Ajaloni un viņas ganības, Gat-Rimonu un viņas ganības, - četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Un no Manasus puscilts: Taēnaku un viņas ganības, un Gat-Rimonu un viņas ganības, divas pilsētas:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Pavisam kopā priekš tiem citiem Kehāta bērnu radiem desmit pilsētas ar savām ganībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Un Geršona bērniem no Levitu radiem (krita) no Manasus puscilts tā glābšanās pilsēta priekš nokāvējiem, Golana Basanā un viņas ganības un Beēstra un viņas ganības, - divas pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Un no Īsašara cilts Ķisjone un viņas ganības, un Dobrate un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmute un viņas ganības, Enganim un viņas ganības, - četras pilsētas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Un no Ašera cilts Mizeale un viņas ganības, Abdone un viņas ganības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Elkata un viņas ganības, un Reoba un viņas ganības, - četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Un no Naftalus cilts tā glābšanās pilsēta priekš nokāvējiem Ķedesā Galilejā un viņas ganības, Amot-Dore un viņas ganības, un Kartane un viņas ganības, - trīs pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Pavisam Geršona bērniem pēc viņu radiem ir trīspadsmit pilsētas ar savām ganībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Un Merarus bērnu radiem, tiem citiem Levitiem, (krita) no Zebulona cilts Jokneane un viņas ganības, un Karta un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna un viņas ganības, Naālale un viņas ganības, - četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Un no Rūbena cilts Becere un viņas ganības, Jāca un viņas ganības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Ķedemota un viņas ganības, un Mepaāta un viņas ganības, - četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Un no Gada cilts krita tā glābšanās pilsēta priekš nokāvējiem, Rāmote Gileādā un viņas ganības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Un Mahānaīm un viņas ganības, Hešbona un viņas ganības, Jaēzere un viņas ganības, pavisam četras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Visas šīs pilsētas piederēja Merarus bērniem pēc viņu radiem, kas arī vēl bija no Levitu radiem, un caur mesliem tiem krita divpadsmit pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Pavisam Levitu pilsētu Israēla bērnu zemē bija četrdesmit un astoņas ar savām ganībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Visas šīs pilsētas bija savrup ar savām apkārtējām ganībām; tā bija ar visām šīm pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Tā Tas Kungs Israēlim deva visu to zemi, ko Viņš bija zvērējis dot viņu tēviem, un tie to uzņēma un tur dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Un Tas Kungs tiem deva mieru visapkārt, tā kā Tas Kungs viņu tēviem bija zvērējis, un no visiem viņu ienaidniekiem neviens nepastāvēja viņu priekšā, visus viņu ienaidniekus Tas Kungs deva viņu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Un neviena vārda netrūka no visiem tiem labiem vārdiem, ko Tas Kungs uz Israēla namu bija runājis, - viss tas notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Tad Jozuas aicināja Rūbeniešus un Gadiešus un Manasus puscilti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Un uz tiem sacīja: jūs visu esat turējuši, ko jums Mozus, Tā Kunga kalps, pavēlējis, un esat klausījuši manai balsij visās lietās, ko es jums esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Jūs savus brāļus neesat atstājuši tādu ilgu laiku līdz šai dienai, bet esat turējuši, kas bija jātur, Tā Kunga, sava Dieva pavēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Un nu Tas Kungs, jūsu Dievs, mieru ir devis jūsu brāļiem, tā kā Viņš tiem bija runājis. Tad nu griežaties atpakaļ un ejat uz saviem dzīvokļiem, uz savu īpašu zemi, ko jums Tā Kunga kalps Mozus devis viņpus Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Bet no Dieva puses dariet to likumu un to bauslību, ko jums Mozus, Tā Kunga kalps, ir pavēlējis, ka jūs mīļojat To Kungu, savu Dievu, un staigājat visos Viņa ceļos un turat Viņa baušļus un Viņam pieķeraties un Viņam kalpojat no visas savas sirds un no visas savas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Tā Jozuas tos svētīja un atlaida, un tie aizgāja uz saviem dzīvokļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Jo vienai Manasus cilts pusei Mozus to (daļu) bija devis Basanā, bet viņas otrai pusei Jozuas to daļu deva pie viņu brāļiem šaipus Jardānes pret vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Kad Jozuas tos atlaida uz viņu dzīvokļiem, tad viņš tos svētīja un uz tiem runāja sacīdams: ar lielu bagātību jūs griežaties atpakaļ uz saviem dzīvokļiem, ar varen daudz lopiem, ar sudrabu un zeltu un ar varu un ar dzelzi un ar ļoti daudz drēbēm. Daliet savu ienaidnieku laupījumu ar saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Tā Rūbena bērni un Gada bērni un Manasus puscilts griezās atpakaļ un aizgāja no Israēla bērniem no Šīlo Kanaāna zemē, un gāja uz Gileādas zemi, uz savu īpašu zemi, kur tie par mantiniekiem bija iecelti pēc Tā Kunga pavēles caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Kad tie nu nāca uz Jardānes apgabalu, kas Kanaāna zemē, tad Rūbena bērni un Gada bērni un Manasus puscilts tur uzcēla altāri pie Jardānes, lielu altāri, kur bija ko redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Un Israēla bērni dzirdēja sakām: Redzi, Rūbena bērni un Gada bērni un Manasus puscilts ir uzcēluši altāri Kanaāna zemei pretī, Jardānes apgabalā, Israēla bērniem pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Kad Israēla bērni to dzirdēja, tad visa Israēla bērnu draudze sapulcējās Šīlo, ka tie pret viņiem celtos ar karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Un Israēla bērni sūtīja pie Rūbena bērniem un pie Gada bērniem un pie Manasus puscilts uz Gileādas zemi Pinehasu, Eleazara, tā priestera, dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Un desmit virsniekus līdz ar viņu, no ikviena tēva nama vienu virsnieku no visām Israēla ciltīm, un ikviens no tiem bija tā galva savu tēvu namā pār Israēla tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Un tie nāca pie Rūbena bērniem un pie Gada bērniem un pie Manasus puscilts Gileādas zemē, un runāja ar tiem un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Tā saka visa Tā Kunga draudze: kas tas par noziegumu, ko jūs pret Israēla Dievu esat noziegušies, nogriezdamies šodien no Tā Kunga, ka jūs sev esat uztaisījuši altāri, Tam Kungam šodien pretī turēdamies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Vai tas Peora noziegums mums vēl ir mazs, no kā mēs (vēl) neesam šķīstījušies līdz šai dienai, jebšu mocība Tā Kunga draudzē ir bijusi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Un jūs šodien nogriežaties no Tā Kunga; bet notiks, kad jūs Tam Kungam šodien turēsities pretī, tad Viņš rīt dusmosies par visu Israēla draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Bet ja jums šķiet, savu iemantoto zemi nešķīstu esam, tad nāciet pāri uz Tā Kunga īpašu zemi, kur Tā Kunga dzīvoklis stāv, un ņemiet savu daļu mūsu vidū, bet neturaties pretī Tam Kungam, nedz turaties pretī mums, uzceldami sev altāri klāt pie Tā Kunga, mūsu Dieva, altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Vai Akans, Zerus dēls, nebija ļoti noziedzies pie tā, kas bija izdeldējams? Un bardzība nāca pār visu Israēla draudzi, un tas vīrs nenomira viens vien sava nozieguma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Tad Rūbena bērni un Gada bērni un Manasus puscilts atbildēja un runāja uz Israēla tūkstošu virsniekiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Tas stiprais Dievs, Dievs, Tas Kungs, tas stiprais Dievs, Dievs, Tas Kungs, tas zin, un arī Israēlim būs zināt, ja tas ir no pretestības vai caur noziegumu pret To Kungu, tad lai Viņš mums šodien nepalīdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Ja mēs tāpēc sev altāri esam uzcēluši, ka gribam nogriezties no Tā Kunga, vai uz tā upurēt dedzināmos upurus vai ēdamus upurus vai pateicības upurus, tad lai Tas Kungs to piemeklē;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Un ja mēs to neesam darījuši šo lietu bīdamies un sacīdami: rītu jūsu bērni uz mūsu bērniem runās un sacīs: kas jums par daļu ar To Kungu, Israēla Dievu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Tas Kungs par robežu ir licis to Jardāni starp mums un jums, jūs Rūbena bērni un jūs Gada bērni, jums nav daļas pie Tā Kunga; tad jūsu bērni mūsu bērniem liktu atstāties no Tā Kunga bijāšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Tāpēc mēs sacījām: taisīsim jel sev un uzcelsim altāri, ne dedzināmiem upuriem, nedz kaujamiem upuriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Bet ka tas būtu par liecinieku starp mums un jums, un starp mūsu radiem pēc mums, ka mēs Tam Kungam ar kalpošanu varam kalpot Viņa priekšā, ar saviem dedzināmiem upuriem un ar saviem kaujamiem upuriem un ar saviem pateicības upuriem, un lai jūsu bērni turpmāk uz mūsu bērniem nevar sacīt: jums nav daļas pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Tāpēc mēs sacījām: kad notiek, ka tie uz mums vai uz mūsu pēcnākamiem turpmāk tā sacīs; tad mēs sacīsim: redziet Tā Kunga altāra taisījumu, ko mūsu tēvi ir taisījuši, ne dedzināmiem upuriem, nedz kaujamiem upuriem, bet par liecību starp jums un mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Lai tas ir tālu no mums, ka mēs būtu pretī turējušies Tam Kungam, vai šodien no Tā Kunga nogriezušies, uzceldami vēl vienu altāri dedzināmiem upuriem, ēdamiem upuriem un kaujamiem upuriem klāt pie Tā Kunga, mūsu Dieva, altāra, kas ir Viņa dzīvokļa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Kad priesteris Pinehas un tie draudzes virsnieki un tās galvas pār Israēla tūkstošiem, kas pie tā bija, dzirdēja tos vārdus, ko Rūbena bērni un Gada bērni un Manasus bērni runāja, tad tas viņiem patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Un Pinehas, priestera Eleazara dēls, sacīja uz Rūbena bērniem un uz Gada bērniem un uz Manasus bērniem: šodien mēs atzīstam, ka Tas Kungs ir mūsu vidū, ka jūs ar šo noziegumu neesat noziegušies pret To Kungu; nu jūs Israēla bērnus esat izglābuši no Tā Kunga rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Tad Pinehas, priestera Eleazara dēls, un tie virsnieki griezās atpakaļ no Rūbena bērniem un no Gada bērniem no Gileāda zemes uz Kanaāna zemi pie Israēla bērniem un viņiem atsacīja šo vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Un tas vārds patika Israēla bērniem, un Israēla bērni teica Dievu un vairs nedomāja pret viņiem celties ar karaspēku nedz to zemi postīt, kur Rūbena bērni un Gada bērni dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Un Rūbena bērni un Gada bērni nosauca to altāri: lai tas ir par liecinieku starp mums, ka Tas Kungs ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Un pēc ilga laika, kad Tas Kungs Israēlim mieru bija devis no visiem viņu ienaidniekiem visapkārt, un kad Jozuas bija vecs palicis un stipri gados,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Tad Jozuas sasauca visus Israēla vecajus un viņu virsniekus un viņu soģus un viņu priekšniekus un uz tiem sacīja: es esmu vecs palicis un stipri gados, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Un jūs visu esat redzējuši, ko Tas Kungs, jūsu Dievs, darījis visām šīm tautām jūsu priekšā, jo Tas Kungs, jūsu Dievs, tas priekš jums ir karojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Redziet, šās atlikušās tautas es caur mesliem jums esmu devis par daļu jūsu ciltīm, no Jardānes (sākot), un visas tautas, ko es esmu izdeldējis, un līdz tai lielai jūrai pret saules noiešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Un Tas Kungs, jūsu Dievs, pats tos izdzīs jūsu priekšā un tos no jums aizdzīs, un jūs iemantosiet viņu zemi, tā kā Tas Kungs, jūsu Dievs, uz jums runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Tad nu esat ļoti stipri, turēt un darīt visu, kas rakstīts Mozus bauslības grāmatā, ka jūs no tās neatkāpjaties ne uz labo, ne uz kreiso pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Ka jūs nenoejat pie šīm tautām, kas pie jums atlikušas, un nepieminiet viņu dievu vārdu, un nezvērējiet pie viņiem un nekalpojiet viņiem un nemetaties zemē priekš viņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Bet pieķeraties Tam Kungam, savam Dievam, kā jūs esat darījuši līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Tā Tas Kungs jūsu priekšā ir izdzinis lielas un varenas tautas, un neviens priekš jums nav pastāvējis līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Viens vīrs no jums dzen tūkstošus, jo Tas Kungs, jūsu Dievs, Tas priekš jums karo, tā kā Viņš jums runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Tāpēc sargājat savas dvēseles ļoti, ka jūs mīļojat To Kungu, savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Jo kad jūs nogriezīsities un pieķersities šīm tautām, kas pie jums atlikušas un apsvainosities(saradosities) ar viņām un iesiet pie viņām un tās pie jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Tad ziniet tiešām, ka Tas Kungs, jūsu Dievs, joprojām visas šās tautas jūsu priekšā neizdzīs, bet tās jums tiks par slazda valgu un par tīklu un par pātagu jūsu sānos un par ērkšķiem jūsu acīs, tiekams jūs iesiet bojā no šīs labās zemes, ko Tas Kungs, jūsu Dievs, jums devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Un redzi, es aizeju šodien visas pasaules ceļu; tad nu atzīstat no visas sirds un no visas dvēseles, ka neviena vārda netrūkst no visiem labiem vārdiem, ko Tas Kungs, jūsu Dievs, uz jums runājis; visi jums ir nākuši, no tiem netrūkst neviena vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Un kā viss tas labums pār jums nācis, ko Tas Kungs, jūsu Dievs, uz jums runājis: tā Tas Kungs, jūsu Dievs, uz jums liks nākt visam tam ļaunumam, ko Viņš runājis, tiekams Viņš jūs būs izdeldējis no šīs labās zemes virsas, ko Tas Kungs, jūsu Dievs, jums devis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Kad jūs Tā Kunga, sava Dieva, derību pārkāpjat, ko Viņš jums ir devis, un ejat un kalpojat citiem dieviem un metaties zemē priekš viņiem, tad Tā Kunga bardzība pret jums iedegsies un jūs piepeši izdeldēs no tās labās zemes virsas, ko Viņš jums devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Un Jozuas sapulcināja visas Israēla ciltis Šehemē un sasauca Israēla vecajus un viņu virsniekus un viņu soģus un viņu priekšniekus, un tie atnāca Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Tad Jozuas sacīja uz visiem tiem ļaudīm: tā saka Tas Kungs, Israēla Dievs: viņpus upes jūsu tēvi vecos laikos ir dzīvojuši, Tārus, Ābrahāma un Nahora tēvs, un ir kalpojuši citiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Tad Es ņēmu jūsu tēvu Ābrahāmu no viņas upes puses un tam liku staigāt caur visu Kanaāna zemi, un Es vairoju arī viņa dzimumu un devu viņam Īzaku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Un Īzakam Es devu Jēkabu un Ēsavu, un Ēsavam Es devu Seīra kalnus par daļu, bet Jēkabs un viņa bērni nogāja uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Tad Es sūtīju Mozu un Āronu, un mocīju Ēģiptes zemi, tā kā Es viņas vidū esmu darījis, un pēc tam Es jūs izvedu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Kad Es jūsu tēvus no Ēģiptes zemes biju izvedis, tad jūs nācāt pie jūras, un ēģiptieši jūsu tēviem dzinās pakaļ ar ratiem un ar jātniekiem līdz niedru jūrai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Tad tie brēca uz To Kungu, un Viņš lika tumsību starp jums un ēģiptiešiem, un Viņš lika jūrai pār tiem nākt un tos apklāja, un jūsu acis redzējušas, ko Es Ēģiptes zemē esmu darījis. Pēc tam jūs ilgu laiku esat dzīvojuši tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Un Es jūs vedu Amoriešu zemē, kas viņpus Jardānes dzīvoja: tie pret jums karoja, bet Es tos nodevu jūsu rokā, un jūs iemantojāt viņu zemi, un Es tos izdeldēju jūsu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Tad Balaks, Cipora dēls, Moabiešu ķēniņš, cēlās un karoja pret Israēli; un viņš nosūtīja un lika aicināt Bileāmu, Beora dēlu, jūs nolādēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Bet Es Bileāmu negribēju klausīt, un viņš svētīdams jūs svētīja, un Es jūs izglābu no viņa rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Un jūs cēlāties pār Jardāni un nācāt uz Jēriku; tad Jērikus iedzīvotāji pret jums karoja, Amorieši, Ferezieši un Kanaānieši un Hetieši un Ģirgozieši un Hivieši un Jebusieši, bet Es tos nodevu jūsu rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Un Es sūtīju jūsu priekšā dundurus, tie tos priekš jums izdzina, kā arī tos divus Amoriešu ķēniņus, ne caur tavu zobenu, ne caur tavu stopu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Un Es jums devu zemi, ko tu neesi apkopis, un pilsētas, ko jūs neesat uzcēluši, ka tur dzīvojat, vīna dārzus un eļļas kokus, ko jūs neesat dēstījuši, ka no tiem ēdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Un nu bīstaties To Kungu un kalpojiet Viņam skaidri un taisni, un atmetiet tos dievus, kam jūsu tēvi viņpus upes un Ēģiptes zemē ir kalpojuši, un kalpojiet Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Bet ja tas jums nepatiks, Tam Kungam kalpot, tad izvēlaties sev šodien, kam jūs gribat kalpot, vai tiem dieviem, kam jūsu tēvi kalpojuši viņpus upes, vai tiem Amoriešu dieviem, kuru zemē jūs dzīvojat. Bet es un mans nams, mēs kalposim Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Tad tie ļaudis atbildēja un sacīja: lai tas ir tālu no mums, To Kungu atstāt un kalpot citiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Jo Tas Kungs ir mūsu Dievs; Tas mūs un mūsu tēvus izvedis no Ēģiptes zemes, no tā vergu nama, Tas priekš mums šās lielās zīmes darījis un mūs pasargājis uz visiem ceļiem, kur esam gājuši, un starp visiem ļaudīm, caur kuru vidu esam staigājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Un Tas Kungs mūsu priekšā izdzinis visus tos ļaudis un tos Amoriešus, šās zemes iedzīvotājus, tāpēc mēs kalposim Tam Kungam, jo Tas ir mūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Tad Jozuas sacīja uz tiem ļaudīm: jūs nevarēsiet Tam Kungam kalpot, jo Tas Kungs ir svēts Dievs, Viņš ir stiprs Dievs, dusmotājs, Viņš nepiedos jūsu pārkāpumus, nedz jūsu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Kad jūs no Tā Kunga atstāsities un kalposiet svešiem dieviem, tad Viņš atstāsies un jums darīs ļaunu, un jums liks bojā iet, pēc tam, kad Viņš jums labu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Tad tie ļaudis sacīja uz Jozua: nē, bet mēs kalposim Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Tad Jozuas sacīja uz tiem ļaudīm: jūs esat liecinieki sev pašiem, ka jūs To Kungu esat izvēlējušies, Viņam kalpot. Un tie sacīja: mēs esam liecinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Un nu atmetiet tos svešos dievus, kas jūsu starpā, un griežat savas sirdis uz To Kungu, Israēla Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Un tie ļaudis sacīja uz Jozua: mēs kalposim Tam Kungam, mūsu Dievam, un klausīsim Viņa balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Tā Jozuas tai dienā darīja derību ar tiem ļaudīm, un tiem iecēla likumus un tiesas Šehemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Un Jozuas rakstīja šos vārdus Dieva bauslības grāmatā un ņēma lielu akmeni un to tur uzcēla apakš ozola pie Tā Kunga svētās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Un Jozuas sacīja uz visiem ļaudīm: redzi, šis akmens mums būs par liecību; jo tas ir dzirdējis visus Tā Kunga vārdus, ko Viņš ar mums runājis, - tas būs jums par liecību, ka jūs savam Dievam nemelojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Tā Jozuas tos ļaudis atlaida, ikvienu savā īpašumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Un notikās pēc šīm lietām, tad Jozuas, Nuna dēls, Tā Kunga kalps, nomira, simts un desmit gadus vecs būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Un tie viņu apraka viņa īpašuma robežās, Timnat-Zerā, kas ir Efraīma kalnos, no Gaāša kalna pret ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Un Israēls kalpoja Tam Kungam, kamēr Jozuas dzīvoja un kamēr tie vecaji dzīvoja, kas ilgi pēc Jozuas dzīvoja un kas visus Tā Kunga darbus zināja, ko Viņš Israēlim bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Un tie apraka arīdzan Jāzepa kaulus, ko Israēla bērni no Ēģiptes zemes bija izveduši, Šehemē, tai tīruma gabalā, ko Jēkabs no Hamora, Šehema tēva, bērniem bija pircis par simts sudraba gabaliem; jo tas Jāzepa bērniem bija ticis par daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Un Eleazars, Ārona dēls, nomira, un viņu apraka Ģibejā, viņa dēla Pinehasa pilsētā, kas viņam bija dota Efraīma kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Un notika pēc Jozuas nāves, ka Israēla bērni To Kungu vaicāja un sacīja: kas mums ies priekšā, karot pret Kanaāniešiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Un Tas Kungs sacīja: Jūdam būs iet: redzi, Es to zemi esmu devis viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Tad Jūda sacīja uz Sīmeanu, savu brāli: nāc man līdz uz manu daļu, un karosim pret Kanaāniešiem, tad es arīdzan tev iešu līdz uz tavu daļu. Un Sīmeans viņam gāja līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Un Jūda cēlās, un Tas Kungs nodeva viņu rokā Kanaāniešus un Fereziešus, un tas kāva Bezekā desmit tūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Un tie atrada Adoni-Bezeku Bezekā un karoja pret viņu un sakāva Kanaāniešus un Fereziešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Un Adoni-Bezeks bēga, bet tie viņam dzinās pakaļ un to sagūstīja un nocirta īkšķus pie viņa rokām un kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Tad Adoni-Bezeks sacīja: septiņdesmit ķēniņi ar nocirstiem roku un kāju īkšķiem salasīja apakš mana galda druskas; kā es esmu darījis, tā man Dievs ir atmaksājis. Un tie to veda uz Jeruzālemi, un viņš tur nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Jo Jūda bērni bija karojuši pret Jeruzālemi un to uzņēmuši un ar zobena asmeni situši un to pilsētu iededzinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Un pēc tam Jūda bērni nogāja karot pret tiem Kanaāniešiem, kas dzīvoja kalnos un pret dienas vidu un ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Un Jūda cēlās pret tiem Kanaāniešiem, kas Hebronē dzīvoja, (bet Hebrones vārds bija senāk KiriatArba,) un tie kāva Zezaju un Aķimanu un Talmaju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Un no turienes tie cēlās pret tiem, kas Debirā dzīvoja, bet Debiras vārds bija senāk KiriatZevere.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Un Kālebs sacīja: kas KiriatZeveri kaus un viņu uzņems, tam es savu meitu Aksu došu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Tad to uzņēma Otniēls, Ķenasa, Kāleba jaunākā brāļa, dēls, un viņš tam Aksu, savu meitu, deva par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Un notikās, kad viņa pie tā nāca, tad viņa to paskubināja, no viņas tēva tīrumu lūgt, un viņa nolēca no ēzeļa; tad Kālebs uz to sacīja: kas tev ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Un tā uz viņu sacīja: dod man svētību, jo tu man esi devis diena vidus zemi, tad dod man arī ūdens avotus. Tad Kālebs viņai deva avotus augšā un avotus ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Un tā Kenieša, Mozus tēvoča, bērni, gāja Jūda bērniem līdz no tās palmu pilsētas uz Jūda tuksnesi, kas no Arada uz dienas vidu, un nogāja un dzīvoja starp tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Un Jūda cēlās ar savu brāli Sīmeanu, un tie kāva tos Kanaāniešus, kas Cevatā dzīvoja, un tos izdeldēja; un nosauca tās pilsētas vārdu Horma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Un Jūda uzņēma arī Gacu ar viņas apgabalu, un Askalonu ar viņas apgabalu un Ekronu ar viņas apgabalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Un Tas Kungs bija ar Jūdu, ka viņš tos kalnus ieņēma. Jo tos, kas ielejā dzīvoja, viņš nevarēja izdzīt, tāpēc ka tiem bija dzelzs rati.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Un Kālebam tie deva Hebroni, kā Mozus bija runājis, un tas no turienes izdzina Enaka trīs dēlus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Bet Benjamina bērni neizdzina tos Jebusiešus, kas Jeruzālemē dzīvoja; un Jebusieši dzīvo Jeruzālemē ar Benjamina bērniem kopā līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Un Jāzepa nams arī cēlās uz Bēteli, un Tas Kungs bija ar viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Un Jāzepa nams lika Bēteli izlūkot, bet šīs pilsētas vārds senāk bija Lūza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Un tie izlūki redzēja vīru no pilsētas ārā nākam un sacīja uz viņu: rādi mums jel, kur pilsētā var iekļūt, tad mēs darīsim žēlastību pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Un kad viņš tiem rādīja, kur tie varēja iekļūt pilsētā, tad tie to pilsētu sita ar zobena asmeni, bet to vīru un visus viņa radus tie lika mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Tad tas vīrs nogāja uz Hetiešu zemi un uztaisīja pilsētu un nosauca viņas vārdu Lūza; tas ir viņas vārds līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Un Manasus neizdzina tos, kas bija Betzeanā, un viņas ciemos, nedz Taēnakā un viņas ciemos, nedz Dorā un viņas ciemos, nedz Jebleamā un viņas ciemos, nedz Meģidū un viņas ciemos, un tie Kanaānieši iesāka palikt šai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Bet kad Israēls palika stiprs, tad viņš Kanaāniešus piespieda pie klausības, bet izdzīt tos neizdzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Efraīms arīdzan neizdzina tos Kanaāniešus, kas Gazerā dzīvoja, bet Kanaānieši dzīvoja starp viņiem Gazerā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulons neizdzina Kitronas iedzīvotājus, nedz Naālalas iedzīvotājus, bet Kanaānieši dzīvoja starp viņiem un klausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Ašers neizdzina Akas iedzīvotājus, nedz tos iedzīvotājus, kas Sidonā. Aķelabā, Akzibā, Elbā, Afekā, Rekobā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Bet Ašerieši dzīvoja starp Kanaāniešiem, tās zemes iedzīvotājiem, jo viņi tos neizdzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naftalus neizdzina tos iedzīvotājus no BetŠemesas, nedz tos iedzīvotājus no ZetAnatas, bet dzīvoja starp Kanaāniešiem, tās zemes iedzīvotājiem, bet BetŠemesas un BetAnatas iedzīvotāji tiem palika par klausītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Un Amorieši iedzina Dana bērnus kalnos, jo tie tiem neļāva nākt ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Amorieši arī iesāka palikt Eres kalnos Ajalonā un Zaālbima, bet Jāzepa nama roka tos spieda, ka tie palika par klausītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Un Amoriešu robeža bija no Akrabu kalniem un no Zelas uz augšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Un Tā Kunga eņģelis nāca no Gilgalas uz Boķimu un sacīja: Es jūs esmu izvedis no Ēģiptes un jūs ievedis tai zemē, ko jūsu tēviem esmu zvērējis, un sacījis: Es Savu derību ar jums negribu lauzt ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Bet jums nebūs derību darīt ar šīs zemes iedzīvotājiem, viņu altārus jums būs salauzt. Bet jūs neesat klausījuši Manai balsij; kam jūs tā esat darījuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Tāpēc Es arī esmu sacījis: Es tos neizdzīšu jūsu priekšā, bet tie jums būs par tīkliem, un viņu dievi par slazda valgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Un kad Tā Kunga eņģelis šos vārdus bija runājis uz visiem Israēla bērniem, tad tie ļaudis pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Un tie nosauca tās vietas vārdu Boķim (raudātāji), un upurēja tur Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Jo kad Jozuas tos ļaudis bija atlaidis, tad Israēla bērni bija nogājuši ikviens uz savu īpašumu, ieņemt to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Un tie ļaudis kalpoja Tam Kungam, kamēr Jozuas dzīvoja un kamēr tie vecaji dzīvoja, kas vēl ilgu laiku pēc Jozuas dzīvoja, kas bija redzējuši visus Tā Kunga lielos darbus, ko Viņš bija darījis pie Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Bet kad Jozuas, Nuna dēls, Tā Kunga kalps, bija nomiris simts un desmit gadus vecs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Tad tie viņu apraka viņa robežās TimnatEresā uz Efraīma kalniem, no Gaāša kalna pret ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Kad nu arī viss tas dzimums bija aizgājis pie saviem tēviem, tad cēlās cits dzimums pēc viņiem, kas To Kungu nepazina, nedz tos darbus, ko Viņš bija darījis pie Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Tad Israēla bērni darīja, kas Tam Kungam nepatika, un kalpoja Baāliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Un atstāja To Kungu, savu tēvu Dievu, kas tos bija izvedis no Ēģiptes, un dzinās pakaļ citiem dieviem no to ļaužu dieviem, kas tiem bija visapkārt, un pielūdza tos un apkaitināja To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Jo tie atstāja To Kungu un kalpoja Baālam un Astartēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Tad Tā Kunga bardzība iedegās pret Israēli, un Viņš tos nodeva laupītājiem rokā, kas tos aplaupīja, un Viņš tos pārdeva viņu ienaidnieku rokā visapkārt, un tie vairs nevarēja pastāvēt savu ienaidnieku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Visur, kur tie izgāja, Tā Kunga roka bija pret tiem par sodu, kā Tas Kungs bija runājis un kā Tas Kungs tiem bija zvērējis, un tie tapa gauži spaidīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Tad Tas Kungs iecēla soģus, kas tos izglāba no viņu laupītāju rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Bet tie arī neklausīja saviem soģiem, bet maukoja pakaļ citiem dieviem un tos pielūdza; ātri tie atstājās no tā ceļa, ko viņu tēvi bija gājuši, klausīt Tā Kunga baušļus; tā tie nedarīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Un kad Tas Kungs tiem iecēla soģus, tad Tas Kungs bija ar to soģi, un tos izglāba no viņu ienaidnieku rokas, kamēr tas soģis dzīvoja; to Tam Kungam bija žēl, ka viņi nopūtās par tiem, kas viņus spieda un spaidīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Bet kad tas soģis nomira, tad tie atkāpās un palika ļaunāki nekā viņu tēvi, dzīdamies pakaļ citiem dieviem, tiem kalpodami un tos pielūgdami; tie neatstājās no saviem darbiem, nedz no savas pārgalvības ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Tad Tā Kunga bardzība iedegās pret Israēli, ka Viņš sacīja: tāpēc ka šī tauta Manu derību pārkāpusi, ko Es viņu tēviem pavēlēju, un nav klausījusi Manai balsij,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Tad Es arī viņu priekšā neizdzīšu neviena no tiem pagāniem, ko Jozuas atstājis, kad viņš nomira,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Lai Es Israēli caur tiem kārdināju, vai viņi Tā Kunga ceļu sargās, staigādami pa to, tā kā viņu tēvi ir sargājušies, vai ne?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Tā Tas Kungs atstāja šos pagānus, tos tik drīz neizdzīdams, un tos nenodeva Jozuas rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Šie nu ir tie pagāni, ko Tas Kungs atstāja, ka Viņš caur tiem Israēli kārdinātu, kas nekā nezināja no Kanaāna kariem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Lai Israēla bērnu pēcnākamie zinātu un mācītos karu, tie, kas no tā vēl nekā nezināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Pieci Fīlistu valdnieki un visi Kanaānieši un Sidonieši un Hivieši, kas dzīvoja Lībanus kalnos, un no BaālErmona kalna līdz Hamatai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Šie tad bija, lai Israēls caur tiem tiktu kārdināts, ka taptu zināms, vai tie klausīs Tā Kunga baušļiem, ko Viņš viņu tēviem bija pavēlējis caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Un Israēla bērni dzīvoja vidū starp Kanaāniešiem, Hetiešiem un Amoriešiem un Fereziešiem un Hiviešiem un Jebusiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Un tie sev ņēma viņu meitas par sievām un deva savas meitas viņu dēliem un kalpoja viņu dieviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Un Israēla bērni darīja, kas Tam Kungam nepatika, un aizmirsa To Kungu, savu Dievu, un kalpoja Baāliem un Astartēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Tad Tā Kunga bardzība iedegās pret Israēli un Viņš tos pārdeva Kuzan Rizataīma, Mezopotamijas ķēniņa, rokā, un Israēla bērni kalpoja Kuzan Rizataīmam astoņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Tad Israēla bērni brēca uz To Kungu, un Tas Kungs Israēla bērniem cēla pestītāju, kas tos izpestīja, Otniēli, Ķenasa, Kāleba jaunākā brāļa, dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Un Tā Kunga Gars bija uz viņu, un viņš bija par soģi Israēlim un izgāja karā, un Tas Kungs deva viņa rokā Kuzan Rizataīmu, Mezopotamijas ķēniņu, un viņa roka bija stipra pār Kuzan Rizataīmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Tad zemei bija miers četrdesmit gadus, un Otniēls, Ķenasa dēls, nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Bet Israēla bērni joprojām darīja, kas Tam Kungam nepatika. Tad Tas Kungs stiprināja Eglonu, Moaba ķēniņu, pret Israēli, tāpēc, ka tie darīja, kas Tam Kungam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Un viņš sapulcēja pie sevis Amona bērnus un Amaleku, un cēlās un kāva Israēli, un tie ieņēma to palmu pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Un Israēla bērni kalpoja Eglonam, Moaba ķēniņam, astoņpadsmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Tad Israēla bērni brēca uz To Kungu, un Tas Kungs tiem cēla par pestītāju Eūdu, Ģerus dēlu, no Benjamina cilts; tas bija kreilis, un Israēla bērni caur viņu sūtīja dāvanu Eglonam, Moaba ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Un Eūds taisīja sev abējās pusēs griezīgu zobenu, olekts garumā, un to apjoza apakš savām drēbēm pie savas labās ciskas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Un viņš Eglonam, Moaba ķēniņam, nonesa dāvanas, un Eglons bija ļoti resns vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Un kad viņš to dāvanu bija nodevis, tad viņš tos ļaudis atlaida, kas to dāvanu bija nesuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Bet viņš griezās atpakaļ no tiem elku stabiem, kas bija Gilgalā un sacīja: man viens noslēpums tev jāsaka, ķēniņ. Un tas sacīja: klusu! Tad visi izgāja ārā, kas ap viņu stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Un Eūds pie viņa pienāca; bet viņš sēdēja kādā dzestrā kambarī, kas bija viņam vienam. Tad Eūds sacīja: man ir Dieva vārds uz tevi. Tad viņš cēlās no tā krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Un Eūds izstiepa savu kreiso roku un ņēma to zobenu no savas labās ciskas un to viņam iedūra vēderā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Ka gan asmens, gan spals iegāja, un tie tauki to asmeni apklāja, jo viņš to zobenu no viņa vēdera neizvilka, un tas izgāja pakaļā cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Tad Eūds izgāja ārā un aizslēdza tā kambara durvis aiz sevis un tās aizšāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Kad tas nu bija izgājis, tad viņa kalpi nāca, un redzēja, un lūk, kambara durvis bija aizslēgtas. Un tie sacīja: viņš gan savas kājas apklāj tai dzestrā kambarī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Kad tie nu gaidīja tik ilgi, ka paši kaunējās, un redzi, viņš tā kambara durvis neatdarīja, tad viņi ņēma atslēgu un atslēdza, un redzi, viņu kungs gulēja pie zemes nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Un Eūds izmuka, kamēr tie gaidīja, jo viņš gāja gar tiem elku stabiem un aizmuka uz Seīratu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Un kad viņš tur nonāca, tad viņš pūta trumetē uz Efraīma kalniem, un Israēla bērni nogāja ar viņu no tiem kalniem un viņš pats viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Un viņš uz tiem sacīja: steidzaties man pakaļ, jo Tas Kungs devis jūsu rokā jūsu ienaidniekus, tos Moabiešus. Un tie nogāja viņam pakaļ un uzņēma Jardānes pārejamo vietu, kas pret Moabu, un nevienu nelaida pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Un tie kāva no Moabiešiem tanī laikā kādus desmit tūkstoš vīrus, visus brangus un visus stiprus, ka neviens neizspruka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Tad Moabs tai dienā tapa pazemots apakš Israēla bērnu rokas, un zemei bija miers astoņdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Un pēc viņa bija Zamgars, Anata dēls, tas kāva no Fīlistiem sešsimt vīrus ar vēršu dzenamo. Tā viņš arīdzan Israēli izpestīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Un Israēla bērni joprojām darīja, kas Tam Kungam nepatika, kad Eūds bija nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Tad Tas Kungs tos nodeva Jabina, Kanaāniešu ķēniņa, rokā, kas Hacorā valdīja, un viņa karaspēka virsnieks bija Siserus, un tas dzīvoja pagānu Arozetā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Tad Israēla bērni brēca uz To Kungu, jo tam bija deviņsimt dzelzs rati, un tas Israēla bērnus ar varu bija spaidījis divdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Un Debora, praviete, Lapidota sieva, tanī laikā Israēli tiesāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Un viņa dzīvoja apakš Deboras palmas koka starp Ramu un Bēteli Efraīma kalnos, un Israēla bērni gāja pie viņas uz tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Un viņa nosūtīja un aicināja Baraku, Abinoama dēlu, no Naftalus Ķedesas, un uz to sacīja: tiešām, Tas Kungs, Israēla Dievs, tev ir pavēlējis: ej un dodies uz Tābora kalnu, un ņem līdz desmit tūkstoš vīrus no Naftalus bērniem un no Zebulona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Tad Es tev pievedīšu pie Kisonas upes Siseru, Jabina karaspēka virsnieku, un viņa ratus un viņa pulku un viņu nodošu tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Tad Baraks uz viņu sacīja: ja tu man gribi iet līdz, tad es iešu, bet ja tu negribi iet līdz, tad es neiešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Un viņa sacīja: iet es iešu tev līdz, tomēr tas gods uz šī ceļa, ko tu tagad staigā, nepiederēs tev, bet Tas Kungs Siseru nodos kādas sievas rokā. Un Debora cēlās un gāja ar Baraku uz Ķedesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Tad Baraks sasauca Ķedesā Zebulonu un Naftalu, un tur desmit tūkstoš vīri gāja viņam pakaļ, un Debora gāja līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, '(Bet Hebers, tas kenietis, bija atšķīries no Keniešiem, no Hobaba, Mozus tēvoča, bērniem, un bija uzcēlis savu dzīvokli pie tā ozola iekš Caānaīm, kas ir pie Ķedesas.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Un Siserum tapa teikts, ka Baraks, Abinoama dēls, bija gājis uz Tābora kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Tad Siserus sasauca pie Ķizonas upes visus savus ratus, deviņsimt dzelzs ratus, un visus ļaudis, kas pie viņa bija no pagānu Arozetas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Un Debora sacīja uz Baraku: celies, jo šī ir tā diena, kur Tas Kungs Siseru devis tavā rokā: vai Tas Kungs nav izgājis tavā priekšā? Tad Baraks cēlās no Tābora kalna, un desmit tūkstoš vīri viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Un Tas Kungs izbiedēja Siseru ar visiem ratiem un visu karaspēku priekš Baraka zobena asmens, un Siserus nolēca no saviem ratiem un bēga kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Un Baraks dzinās pakaļ tiem ratiem un tam karaspēkam līdz pagānu Arozetai, un viss Siserus karapulks krita caur zobena asmeni, ka neviens neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Un Siserus bēga kājām uz Jaēles, Hebera, tā Kenieša, sievas, dzīvokli, jo starp Jabinu, Hacoras ķēniņu, un Hebera, tā Kenieša, namu bija miers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Tad Jaēle Siserum izgāja pretī un sacīja: nāc iekšā, kungs, nāc iekšā pie manis, nebīsties; un viņš iegāja pie viņas dzīvoklī, un viņa to apsedza ar apsegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Un viņš uz to sacīja: dod man jel maķenīt ūdens, jo man slāpst; tad viņa attaisīja piena trauku un to dzirdīja un to apsedza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Un viņš uz to sacīja: stāvi dzīvokļa durvīs; ja kāds nāk un tev vaicā un saka: vai še nav kāds; tad saki: nav neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Tad Jaēle, Hebera sieva, ņēma telts naglu un ņēma veseri savā rokā, un lēnam pie tā piegājusi, tā iedzina to naglu caur viņa deniņiem, tā ka tā iegāja zemē; bet viņš bija aizmidzis un noguris, un tā viņš nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Un redzi Baraks Siserum dzinās pakaļ Tad Jaēle izgāja viņam pretī un sacīja uz viņu: nāc, tad es tev rādīšu to vīru, ko tu meklē. Tad viņš pie tās iegāja, un redzi, Siserus gulēja nomiris, un tā nagla bija viņa deniņos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Tā Dievs tai dienā pazemoja Jabinu, Kanaāniešu ķēniņu, priekš Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Un Israēla bērnu roka palika jo dienas grūtāka pār Jabinu, Kanaāniešu ķēniņu, kamēr tie izdeldēja Jabinu, Kanaāniešu ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Tad Debora un Baraks, Abinoama, dēls, tai dienā dziedāja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Ka Israēla varenie spēcīgi rādījušies, ka ļaudis labprātīgi cēlušies, teiciet To Kungu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Klausāties, ķēniņi, ņemiet vērā, lielie kungi! Tam Kungam es dziedāšu, Tam Kungam, Israēla Dievam, es dziedāšu dziesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Kungs, kad Tu izgāji no Seīra un atnāci no Edoma lauka, tad zeme drebēja, un debesis pilēja, un padebeši pilēja ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Kalni izkusa Tā Kunga priekšā, pats Sinaī Tā Kunga, Israēla Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Zamgara, Anata dēla, dienās, Jaēles dienās, ceļi bija klusi, un ceļa ļaudis gāja aplinkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Klusi bija ciemi iekš Israēla, tie bija klusi, kamēr es, Debora, cēlos, kamēr es cēlos, māte iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Jaunus dievus izredzējās, tad radās karš vārtos. Vai gan redzēja bruņas, vai šķēpus pie četrdesmit tūkstošiem iekš Israēla?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mana sirds pieder Israēla valdniekiem, tiem ļaudīm, kas labprātīgi cēlušies. Teiciet To Kungu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Kas jājat uz baltām ēzelienēm, kas sēžat uz audumiem, kas staigājat pa ceļu, dziedājiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Kur strēlnieku balss skanēja pie ūdens akām, tur slavē Tā Kunga taisnos darbus, tos taisnos darbus pie Viņa ciemiem iekš Israēla. Tad Tā Kunga ļaudis pārgāja savos vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Modies, modies, Debora! modies, modies, dziedi dziesmu! Celies, Barak, un ved savus gūstītos, Abinoama dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Tad nonāca atlikums no tiem tautas vareniem; Tas Kungs nonāca man līdz starp tiem spēcīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'No Efraīma tie, kam sakne ir iekš Amaleka, aiz tevis Benjamins starp taviem ļaudīm; no Mahira valdnieki nāca un no Zebulona, kas tur (nes) vadoņa zizli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Un Īsašara virsnieki bija ar Deboru, un Īsašars tā kā Baraks, lejā nesti savām kājām. Pie Rūbena upēm bija lieli sirds padomi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Kāpēc tu paliki pie laidariem, klausīties stabules pie ganāmiem pulkiem? Pie Rūbena upēm bija lieli sirds spriedumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gileāds palika viņpus Jardānes, un kāpēc Dans mīt pie laivām? Ašers sēž jūrmalā un paliek savos līčos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zebulons, tā ir tauta, kas savu dvēseli nodod nāvē, un Naftalus arīdzan augstos klajumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Ķēniņi nāca, tie karoja, tad Kanaāna ķēniņi karoja pie Taānakas, pie Meģidus ūdeņiem; naudas peļņu tie nedabūja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'No debesīm karoja, zvaigznes no saviem ceļiem karoja pret Siseru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Ķizonas upe viņus aizrāva, tā veclaiku upe, Ķizonas upe. Celies, mana dvēsele, ar spēku!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Rībēt rībēja apakš zirgu kājām, jājot, viņu vareniem jājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Lādiet Merosu, saka Tā Kunga eņģelis, lādiet lādēdami viņa iedzīvotājus, tāpēc ka tie nav nākuši palīgā Tam Kungam, palīgā Tam Kungam ar stiprajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Svētīta pār sievām lai ir Jaēle, Hebera, tā Kenieša, sieva, svētīta pār sievām teltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Ūdeni tas prasīja, tā deva pienu; dārgā kausā tā atnesa kreimu(krējumu).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Savu roku tā izstiepa pēc naglas, un savu labo roku pēc strādnieku vesera, un sita Siseram, sašķēla viņa galvu, satrieca un izurba viņa deniņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Apakš viņas kājām tas locījās, krita zemē, gulēja; apakš viņas kājām tas locījās, krita; tur, kur locījās, tas gāzās un bija pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Pa logu skatījās Siserus māte un kliedza caur skadriņiem: kāpēc viņa rati kavējās, ka tie nenāk? Kāpēc viņa zirgu soļi tik lēni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Tās gudrās no viņas cienīgām tai atbild, un arī (viņa) pati tā atbild uz saviem vārdiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '“Vai tad tie neatradīs un neizdalīs laupījumu, vienu, divas sievietes uz vīra galvu, raibas drēbes Siserum par laupījumu, raibas rakstītas drēbes par laupījumu, raibu drēbi, divas rakstītas raibas drēbes ap kaklu laupītajām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tā lai, Kungs, iet bojā visi Tavi ienaidnieki! Bet kas Viņu mīļo, lai ir, tā kā saule uzlec savā spēkā.” - Un tai zemei bija miers četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Un Israēla bērni darīja, kas Tam Kungam nepatika. Tad Tas Kungs tos nodeva Midijaniešu rokā septiņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Kad nu Midijaniešu roka palika stipra pret Israēli, tad Israēla bērni sev taisīja alas kalnos un bedres un stipras pilis Midijaniešu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Jo kad Israēls bija sējis, tad nāca Midijanieši un Amalekieši un austruma ļaudis un cēlās pret tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Un apmetās pret tiem un postīja zemes druvas līdz Gacai; tie neatlicināja pārtikas iekš Israēla, nedz sīku lopu nedz vēršu nedz ēzeļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Jo tie atnāca ar saviem ganāmiem pulkiem un ar savām teltīm, tie nāca tā kā siseņu pulks, ka tos ar viņu kamieļiem nevarēja skaitīt, un tie nāca, zemi postīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Un Israēls ļoti panīka caur Midijaniešiem. Tad Israēla bērni brēca uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Un notikās, kad Israēla bērni Midijana dēļ uz To Kungu brēca,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Tad Tas Kungs sūtīja pravieti pie Israēla bērniem; tas uz viņiem sacīja: tā saka Tas Kungs, Israēla Dievs: Es jūs esmu izvedis no Ēģiptes un jūs izvedis no vergu nama');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Un jūs izglābis no ēģiptiešu rokas un no visu rokas, kas jūs spieda, un Es tos jūsu priekšā izdzinis un jums devis viņu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Un Es uz jums sacīju: Es esmu Tas Kungs, jūsu Dievs, nebīstaties Amoriešu dievus, kuru zemē jūs dzīvojat. Bet jūs neesat klausījuši Manai balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Un Tā Kunga eņģelis nāca un apsēdās apakš tā ozola Ovrā, kas piederēja Joasam, no Abiēzera nama, un viņu dēls Gideons kūla kviešus vīna spaidā, lai tos paslēptu no Midijaniešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Un Tā Kunga eņģelis tam parādījās un uz to sacīja: Tas Kungs ar tevi, tu stiprais varenais vīrs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Bet Gideons uz viņu sacīja: mans Kungs, kad Tas Kungs ir ar mums, kāpēc tad visas šīs bēdas mums uznākušas? Un kur ir visi viņa brīnumi, ko mums mūsu tēvi teikuši, sacīdami: vai Tas Kungs mūs nav izvedis no Ēģiptes? Bet nu Tas Kungs mūs atstājis un nodevis Midijaniešu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Tad Tas Kungs uz viņu atgriezās un sacīja: noej šinī savā spēkā, un atpestī Israēli no Midijaniešu rokas; redzi, Es tevi esmu sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Un viņš uz to sacīja: mans Kungs, ar ko es Israēli atpestīšu? Redzi, mans radu pulks ir tas mazākais Manasū, un es esmu tas mazākais sava tēva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Un Tas Kungs sacīja uz viņu: tāpēc ka Es būšu ar tevi, tu sitīsi Midijaniešus kā vienu vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Tad tas uz Viņu sacīja: ja es esmu atradis žēlastību Tavās acīs, tad dod man jel zīmi, ka Tu tas esi, kas ar mani runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Neaizej jel no šejienes, kamēr es pie Tevis nākšu un savu ēdamo upuri atnesīšu un Tev celšu priekšā. Un Viņš sacīja: Es palikšu, kamēr tu atkal nāksi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Un Gideons iegāja un sataisīja kazlēnu un neraudzētas karašas no vienas ēfas miltu; to gaļu viņš lika kurvī un to sulu viņš lēja podā, un to iznesa pie Viņa ārā apakš tā ozola un to nolika zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Un tas Dieva eņģelis sacīja uz viņu: ņem to gaļu un tās neraudzētās karašas un liec to šeitan uz to akmeni un izlej to sulu; un viņš tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Tad Tā Kunga eņģelis izstiepa tā zižļa galu, kas viņam bija rokā, un aizskāra to gaļu un tās neraudzētās maizes. Tad uguns izšāvās no tā akmens un aprija to gaļu un tās neraudzētās karašas; un Tā Kunga eņģelis nozuda no viņa acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Kad nu Gideons redzēja, to Tā Kunga eņģeli esam, tad Gideons sacīja: Ak vai! Kungs, Dievs! Jo es Tā Kunga eņģeli vaigu vaigā esmu redzējis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Tad Tas Kungs uz viņu sacīja: miers ar tevi! nebīsties, tu nemirsi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Tad Gideons tur Tam Kungam uzcēla altāri un to nosauca: Tas Kungs ir miers. Tas vēl līdz šodienai ir Abiēzeriešu Ovrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Un tai naktī Tas Kungs uz viņu sacīja: ņem vērsīti no sava tēva lopiem un vēl otru vērsi septiņus gadus vecu, un salauzi Baāla altāri, kas tavam tēvam, un nocērt to elka stabu, kas tur ir klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Un uztaisi Tam Kungam, savam Dievam, altāri šīs stiprās vietas kalna galā tā kārtīgi, un ņem to otru vērsi un upurē dedzināmo upuri ar to malku no tā elka staba, ko tu nocirtīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Tad Gideons ņēma desmit vīrus no saviem kalpiem un darīja, kā Tas Kungs uz viņu bija runājis; bet viņš bijās no sava tēva nama un tās pilsētas vīriem dienā to darīt, un to darīja naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Kad nu tās pilsētas vīri rītā uzcēlās, redzi, tad Baāla altāris bija salauzīts un tas elka stabs nocirsts, kas tur klātu, un tas otrs vērsis uz tā uztaisīta altāra bija upurēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Tad tie sacīja cits uz citu: kas to darījis? Un kad tie meklēja un izvaicāja, tad tapa sacīts: Gideons, Joasa dēls, to darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tad tās pilsētas vīri sacīja uz Joasu: izved savu dēlu, jo tam jāmirst, tāpēc ka viņš nolauzis Baāla altāri un to elka stabu nocirtis, kas tur bija klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Un Joas sacīja uz visiem, kas pie viņa stāvēja: vai jūs tiesāsities par Baālu? Vai jūs viņu izpestīsiet? Kas par viņu tiesāsies, tam vēl šodien būs tapt nokautam. Ja viņš ir dievs, tad lai viņš pats par sevi tiesājās, tāpēc ka viņa altāris nolauzīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Un tai dienā viņu nosauca JerubBaālu un sacīja: lai Baāls ar viņu tiesājās, ka tas viņa altāri nolauzījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Bet visi Midijanieši un Amalekieši un tie austruma ļaudis sapulcējās kopā un pārcēlās un apmetās Jezreēles ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Tad Tā Kunga Gars nāca uz Gideonu, un viņš pūta trumetē un sasauca Abiēzeriešus sev pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Un viņš sūtīja vēstnešus pa visu Manasu; ir tie tapa sasaukti, viņam pakaļ. Un viņš sūtīja vēstnešus pa Ašeru un pa Zebulonu un pa Naftalu un tie nāca viņiem pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Un Gideons sacīja uz Dievu: ja Tu Israēli gribi izpestīt caur manu roku, kā Tu esi runājis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Redzi, es nolikšu aitas cirpumu uz klonu; kad rasa būs uz cirpuma vien un pa visu zemi sausums, tad es zināšu, ka Tu Israēli izpestīsi caur manu roku, kā Tu esi sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Un tā notika. Jo viņš agri no rīta uzcēlās un izspieda to cirpumu un izgrieza rasu no tā cirpuma, vienu kausu pilnu ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Un Gideons sacīja uz Dievu: lai Tava bardzība pret mani neiedegās, ka vēl reiz\' runāju, - es vēl reiz\' raudzīšu ar to cirpumu. Lai jel ir sausums uz tā cirpuma vien, un pa visu zemi lai ir rasa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Un Dievs tā darīja tanī naktī; un sausums bija uz tā cirpuma vien, un pa visu zemi bija rasa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Tad JerubBaāls, tas ir Gideons, un visi ļaudis, kas pie viņa, agri cēlās un apmetās pie Aroda avota, tā ka Midijaniešu karaspēks viņam bija pret ziemeļa pusi, aiz Mores pakalna, ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Un Tas Kungs sacīja uz Gideonu: Pārāk daudz ļaužu ir pie tevis, nekā Es dotu Midijaniešus viņu rokā; lai Israēls pret Mani nelielās un nesaka: mana roka mani izpestījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Tad izsauc jel to ļaužu ausīs un saki: kas šaubīgs un bailīgs, lai griežas atpakaļ un steidzās projām no Gileāda kalna. Tad no tiem ļaudīm griezās atpakaļ divdesmit divi tūkstoši, un tik desmit tūkstoši atlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Un Tas Kungs sacīja uz Gideonu: ļaužu vēl ir par daudz; noved tos pie ūdens, tur Es tos tev pārbaudīšu, un par kuru Es uz tevi sacīšu: šim būs iet ar tevi, tas lai iet ar tevi, bet par kuru Es tev sacīšu, tam nebūs iet ar tevi, tas lai neiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Un viņš tos ļaudis noveda pie ūdens. Tad Tas Kungs sacīja uz Gideonu: ikkatru, kas ar savu mēli ūdeni laks, kā suns lok, to nostādi par sevi, un tāpat ikkatru, kas nometīsies ceļos dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Un to pulks, kas no savas rokas pie mutes bija lakuši, bija trīssimt vīri, bet visi citi ļaudis bija ūdeni dzēruši ceļos nometušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Un Tas Kungs sacīja uz Gideonu: caur šiem trīs simti vīriem, kas lakuši, Es jūs izpestīšu un nodošu Midijaniešus tavā rokā; tāpēc atlaid visus citus ļaudis, ikvienu uz savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Un tie ļaudis ņēma savu maizi savā rokā un savas trumetes, bet visus citus Israēla vīrus viņš atlaida, ikvienu uz savu dzīvokli, un tos trīs simti vīrus viņš paturēja, un Midijaniešu karaspēks viņam bija ielejas pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Un notika tanī naktī, ka Tas Kungs uz viņu sacīja: celies, noej uz lēģeri, jo Es to esmu devis tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Bet ja tev ir bail noiet, tad noej uz to lēģeri tu un Purus, tavs puisis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Tad tu dzirdēsi, ko tie runā, un pēc tam tavas rokas stiprināsies, un tu celsies pret to lēģeri. Tad viņš nogāja ar Puru, savu puisi, pie tiem pirmiem apbruņotiem, kas bija lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Un Midijanieši un Amalekieši un visi tie austruma bērni gulēja ielejā kā siseņu pulks, un viņu kamieļu pulku nevarēja skaitīt, kā smiltis jūrmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Kad nu Gideons nonāca, redzi, tur viens savam biedram stāstīja sapni un sacīja: redzi, es esmu sapni redzējis, un redzi, cepta miežu maize vēlās Midijaniešu lēģerī un atnāca līdz pat teltij un to sita, ka tā krita, un to pavisam apgāza, un telts gulēja (pie zemes).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Tad viņa biedrs atbildēja un sacīja: tas nav nekas cits, kā Gideona, Joasa dēla, tā Israēlieša, zobens; Dievs Midijaniešus un visu šo lēģeri devis viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Un kad Gideons dzirdēja šā sapņa stāstīšanu un izskaidrošanu, tad viņš pielūdza Dievu, griezās atpakaļ uz Israēla lēģeri un sacīja: ceļaties, jo Tas Kungs Midijaniešu karaspēku devis jūsu rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Un viņš dalīja tos trīs simtI vīrus trijos pulkos, un deva visiem trumetes un tukšas krūzes rokā un lāpas krūzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Un viņš uz tiem sacīja: skatāties uz mani un tā dariet; un redzi, kad es nākšu pie lēģera malas, tad dariet jūs tā, kā es daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Kad es trumetēšu, es un visi, kas pie manis, tad jums arīdzan būs trumetēt ap visu lēģeri un saukt: Tā Kunga un Gideona (zobens)!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Tad Gideons un tie simts vīri ar viņu nāca pie lēģera malas ap nakts vidu, kad nule sargi bija mainīti, un tie pūta trumetēs un sadauzīja tās krūzes savās rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Tā tie trīs pulki pūta trumetēs un sadauzīja tās krūzes un turēja ar kreiso roku tās lāpas un savā labajā rokā tās trumetes un pūta un kliedza: Tā Kunga un Gideona zobens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Un tie stāvēja ikviens savā vietā ap to lēģeri. Tad viss karaspēks sāka skriet un tie brēca un bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Jo kad tie trīs simti vīri trumetēs pūta, tad Tas Kungs grieza viena zobenu pret otru visā lēģerī, un tas karaspēks bēga līdz BetZitai uz Careratas pusi, līdz AbelMeolas robežai pie Tābatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Tad Israēla vīri tapa sasaukti no Naftalus un no Ašera un no visa Manasus, un tie dzinās pakaļ Midijanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Un Gideons sūtīja vēstnešus uz visiem Efraīma kalniem un sacīja: nonāciet pretī Midijaniešiem un aizstājiet tiem to ūdeni līdz Betbarai un Jardāni. Tā visi Efraīma vīri tika sasaukti un aizstāja to ūdeni līdz Betbarai un Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Un tie gūstīja divus Midijaniešu valdniekus, Orebu un Zeēbu, un nokāva Orebu pie Oreb akmens, un Zeēbu tie nokāva pie Zeēba spaida un dzinās pakaļ Midijanam un nonesa Oreba un Zeēba galvas pie Gideona viņpus Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Un Efraīma vīri sacīja uz viņu: kas tas ir, ko tu mums esi darījis, ka tu mūs neesi aicinājis pret Midijaniešiem karot? Un tie ar viņu stipri bārās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Tad viņš uz tiem sacīja: vai tad es ko esmu darījis, kā jūs? Vai Efraīma salasas nav labākas nekā Abiēzera savākums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Dievs Midijana valdniekus Orebu un Zeēbu nodevis jūsu rokās, - vai tad es ko varēju darīt kā jūs? Tad viņu dusmas pret to aprima, tam šo vārdu runājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Un Gideons nāca pie Jardānes, un gāja pāri ar tiem trīssimt vīriem, kas pie viņa bija, piekusuši no pakaļ dzīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Un viņš sacīja uz Sukotas vīriem: dodiet jel kādus maizes klaipus tiem ļaudīm, kas man līdz, jo tie piekusuši; un es dzenos pakaļ Zebum un Calmunum, Midijana ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Tad Sukotas virsnieki sacīja: vai tad Zebus un Calmunus dūre jau ir tavā rokā, ka mums tavam karaspēkam būs maizes dot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Tad Gideons sacīja: nu tad, ja Tas Kungs Zebu un Calmunu dos manā rokā, tad es jūsu miesas kapāšu ar tuksneša ērkšķiem un ar dadžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Un viņš gāja no turienes uz Pnuēli un runāja uz tiem tāpat; tad Pnuēles vīri viņam atbildēja, kā Sukotas vīri bija atbildējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Un viņš arī ar Pnuēles vīriem runāja sacīdams: kad es ar mieru griezīšos atpakaļ, tad es šo torni noārdīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Bet Zebus un Calmunus bija Karkorā, un viņu karaspēki pie viņiem, kādi piecpadsmit tūkstoši, kas vien bija atlikuši no visa austruma bērnu spēka, jo simts un divdesmit tūkstoš vīri, zobena nesēji, bija gājuši bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Un Gideons gāja pa telts ļaužu ceļu pret rītiem no Nobas un Jagbeas, un sakāva to karaspēku, jo tas karaspēks tur gulēja it droši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Un Zebus un Calmunus bēga, bet viņš tiem dzinās pakaļ un sagūstīja tos divus Midijaniešu ķēniņus, Zebu un Calmunu, un izbiedēja visu to karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Tad Gideons, Joasa dēls, griezās atpakaļ no kaušanās, pirms saule uzlēca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Un viņš sagūstīja vienu puisi no Sukotas vīriem un to vaicāja; un tas viņam uzrakstīja Sukotas virsniekus un viņas vecajus, septiņdesmit un septiņus vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Tad viņš nāca pie tiem Sukotas vīriem un sacīja: redz še ir Zebus un Calmunus, kādēļ jūs mani esat apsmējuši sacīdami: vai tad Zebus un Calmunus dūre jau ir tavā rokā, ka mums taviem piekusušiem vīriem būs maizes dot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Un viņš ņēma tās pilsētas vecajus un tuksneša ērkšķus un dadžus un pārmācīja Sukotas vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Un Pnuēles torni viņš noārdīja un nokāva tās pilsētas ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Un viņš sacīja uz Zebu un Calmunu: kas tie bija par vīriem, ko jūs Tāborā nokāvāt? Un tie sacīja: tie bija tādi kā tu, visi tādā vaigā, kā ķēniņa bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Un viņš sacīja: tie bija mani brāļi, manas mātes dēli; tik tiešām kā Tas Kungs dzīvo, ja jūs tos būtu atstājuši dzīvus, es jūs nenokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Un viņš sacīja uz Jeteru, savu pirmdzimto: celies, nokauj tos. Bet tas zēns neizvilka savu zobenu, jo viņš bijās, tāpēc ka vēl bija jauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Tad Zebus un Calmunus sacīja: celies pats un sit mūs, jo kāds vīrs, tāds spēks. Tad Gideons cēlās un nokāva Zebu un Calmunu un paņēma tās sprādzes, kas bija ap viņu kamieļu kakliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Un Israēla vīri sacīja uz Gideonu: valdi pār mums, tu un tavs dēls un tava dēla dēls, tāpēc ka tu mūs esi atpestījis no Midijana rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Bet Gideons uz tiem sacīja: es negribu pār jums valdīt, nedz mans dēls pār jums valdīs; Tas Kungs pār jums valdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Un Gideons uz tiem sacīja: es no jums ko prasīšu: dodiet man ikviens vienu ausu sprādzi no sava laupījuma. Jo tiem bija zelta ausu sprādzes, tāpēc ka tie bija Ismaēlieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Un tie sacīja: mēs dosim. Un tie izklāja drēbi un meta uz to ikkatrs vienu ausu sprādzi no sava laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Un to zelta ausu sprādžu svars, ko viņš bija prasījis, bija tūkstoš un septiņi simti zelta sēķeļi, bez tām sprādzēm un ķēdēm un tām purpura drēbēm, kas Midijaniešu ķēniņiem bija mugurā, un bez tām kakla saitēm, kas bija pie viņu kamieļu kakliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Un Gideons no tā taisīja efodu, un to nolika Ovrā, savā pilsētā, un viss Israēls tur tam maukoja pakaļ, un tas Gideonam un viņa namam palika par slazda valgu. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Tā Midijanieši tapa pazemoti priekš Israēla bērniem un nepacēla vairs savu galvu. Un zemei bija miers četrdesmit gadus, kamēr Gideons dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Un JerubBaāls, Joasa dēls, nogāja un dzīvoja savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Un Gideonam bija septiņdesmit dēli, kas no viņa gurniem nākuši, jo viņam bija daudz sievas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Un viņa liekā sieva, kas bija Šehemē, arīdzan viņam dzemdēja dēlu, un viņš tam vārdu nosauca Abimeleks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Un Gideons, Joasa dēls, nomira labā vecumā un tapa aprakts sava tēva Joasa kapā, Abiēzeriešu Ovrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Un kad Gideons bija nomiris, tad Israēla bērni nogriezās un maukoja Baāliem pakaļ un iecēla to BaālBeritu sev par dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Un Israēla bērni nepieminēja To Kungu, savu Dievu, kas tos bija izglābis no visu ienaidnieku rokas visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Un tie nedarīja žēlastību pie JerubBaāla, tas ir Gideona, nama, pēc visa tā labuma, ko viņš bija darījis pie Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Un Abimeleks, JerubBaāla dēls, gāja uz Šehemi pie savas mātes brāļiem un runāja uz tiem un uz visiem savas mātes tēva nama radiem un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Runājiet lūdzami priekš visu namnieku ausīm Šehemē: kas jums ir labāki, vai ka septiņdesmit vīri, visi JerubBaāla dēli, pār jums valda, vai ka viens vīrs pār jums valda? Pieminiet, mani arīdzan esam jūsu kaulu un jūsu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Tad viņa mātes brāļi viņa dēļ runāja priekš visu namnieku ausīm Šehemē visus šos vārdus un viņu sirds nesās uz Abimeleku, jo tie sacīja: viņš ir mūsu brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Un tie viņam deva septiņdesmit sudraba sēķeļus no BaālBerita nama, un Abimeleks ar tiem saderēja neliešus un nebēdniekus, kas viņam staigāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Un viņš nāca sava tēva namā uz Ovru un nokāva savus brāļus, JerubBaāla bērnus, septiņdesmit vīrus uz viena akmens; bet Jotams, JerubBaāla jaunākais dēls, atlika, jo viņš bija paslēpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Tad visi Šehemes namnieki sapulcējās un viss Millus nams, un tie nogāja un iecēla Abimeleku par ķēniņu pie tā piemiņas ozola, kas ir Šehemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Kad to Jotamam teica, tad viņš nogāja un nostājās Gerizima kalna paša galā un pacēla savu balsi un sauca un sacīja: klausāties mani, jūs Šehemes namnieki, tad Dievs arī jūs klausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Koki gāja, ķēniņu pār sevi svaidīt, un sacīja uz eļļas koku: esi ķēniņš pār mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Bet eļļas koks uz tiem sacīja: vai man būs atstāt savu taukumu, ko Dievs un cilvēki pie manis slavē, un noiet un līgoties pa koku virsu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Tad tie koki sacīja uz vīģes koku: nāc tu, esi ķēniņš pār mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Bet vīģes koks uz tiem sacīja: vai man būs atstāt savu saldumu un savus labos augļus un noiet un līgoties pa koku virsu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Tad tie koki sacīja uz vīnakoku: nāc tu un esi ķēniņš pār mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Bet vīnakoks uz tiem sacīja: vai man būs atstāt savu vīnu, kas dievus un cilvēkus iepriecina, un noiet un līgoties pa koku virsu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Tad visi koki sacīja uz ērkšķu krūmu: nāc tu un esi ķēniņš pār mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Tad ērkšķu krūms uz tiem kokiem sacīja: kad jūs tiešām mani svaidiet sev par ķēniņu, tad nāciet un uzticaties manai paēnai, bet ja ne, tad lai uguns iziet no ērkšķu krūma un norij Lībanus ciedru kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Un nu, vai jūs esat taisni un pareizi darījuši, Abimeleku celdami par ķēniņu, un vai jūs esat labi darījuši pie JerubBaāla un viņa nama un viņam darījuši pēc viņa roku nopelna?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Jo mans tēvs jūsu dēļ karojis un savu dzīvību nometis un jūs izglābis no Midijaniešu rokas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Bet jūs šodien esat cēlušies pret mana tēva namu un nokāvuši viņa dēlus, septiņdesmit vīrus uz viena akmens, un esat iecēluši Abimeleku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Ja nu jūs šodien taisni un pareizi esat darījuši pie JerubBaāla un pie viņa nama, tad priecājaties par Abimeleku, un lai viņš arīdzan priecājās par jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Bet ja ne, tad lai uguns iziet no Abimeleka un norij Šehemes namniekus un Millus namu, un lai uguns iziet no Šehemes namniekiem un no Millus nama un norij Abimeleku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Tad Jotams bēga un aizbēga uz Beru un dzīvoja tur, no sava brāļa Abimeleka bīdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Kad nu Abimeleks trīs gadus bija valdījis pār Israēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Tad Dievs sūtīja ļaunu garu starp Abimeleku un Šehemes namniekiem, un Šehemes namnieki turējās viltīgi pret Abimeleku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Ka tas varas darbs pie tiem septiņdesmit JerubBaāla dēliem nāktu un viņa asinis grieztos uz Abimeleku, viņu brāli, kas tos bija nokāvis, un tos, kas bija stiprinājuši, savus brāļus nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Un Šehemes namnieki sūtīja kādus, kas ar viltu uz viņu glūnēja kalna galos, un tie visus aplaupīja, kas pa to ceļu gāja, un tas Abimelekam tapa sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Un Gaāls, Ebeda dēls, nāca ar saviem brāļiem un gāja uz Šehemi, un Šehemes namnieki viņam uzticējās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Un izgāja uz lauku un nolasīja savus vīna kalnus un spaidīja ogas un svinēja prieka svētkus, un gāja sava dieva namā un ēda un dzēra un lādēja Abimeleku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Un Gaāls, Ebeda dēls, sacīja: kas ir Abimeleks, un kas ir Šehems, ka mums viņam būs kalpot? Vai tas nav JerubBaāla dēls un Zebuls viņa uzraugs? Kalpojiet labāki, Hamora, Šehema tēva, vīriem, jo kāpēc lai mēs viņam kalpojam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Ak kaut šie ļaudis būtu manā rokā, gan es Abimeleku izdzītu. Un uz Abimeleku viņš sacīja: vairo savu karaspēku un nāc ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Kad Zebuls, tās pilsētas virsnieks, Gaāla, Ebeda dēla, vārdus dzirdēja, tad viņš apskaitās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Un sūtīja slepeni vēstnešus pie Abimeleka un sacīja: redzi, Gaāls, Ebeda dēls, un viņa brāļi ir nākuši uz Šehemi, un redzi, tie ceļ dumpi pret tevi pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Un nu celies naktī, tu un tie ļaudis, kas pie tevis, un paslēpies laukā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Un rītā agri, kad saule lec, tad celies un uzbrūc tai pilsētai, un redzi, kad viņš un tie ļaudis, kas pie viņa, ies ārā tev pretī, tad dari viņam, kā tava roka māk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Tad Abimeleks un visi ļaudis, kas pie viņa bija, cēlās naktī un paslēpās pret Šehemi četros pulkos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Un Gaāls, Ebeda dēls, izgāja ārā un stāvēja priekš pilsētas vārtiem. Tad Abimeleks un tie ļaudis, kas pie viņa bija, cēlās, kur bija apslēpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Kad nu Gaāls tos ļaudis ieraudzīja, tad viņš sacīja uz Zebulu: redzi, no kalnu galiem nāk ļaudis. Bet Zebuls uz to sacīja: tev šķiet kalna ēnu cilvēkus esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Tad Gaāls vēl runāja un sacīja: redzi, ļaudis nāk no augšgala un viens pulks nāk pa ceļu no burvju ozola.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Tad Zebuls uz viņu sacīja: kur nu ir tava mute, ar ko tu sacīji: kas ir Abimeleks, ka lai tam kalpojam? Vai šie nav tie ļaudis, ko tu esi apsmējis? Izej jel nu ārā un karo pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Un Gaāls izgāja Šehemes namnieku priekšā un karoja pret Abimeleku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Un Abimeleks tam dzinās pakaļ, un tas bēga no viņa, un daudz krita nokauti līdz vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Un Abimeleks palika Arumā, bet Zebuls izdzina Gaālu un viņa brāļus, ka tie Šehemē nepalika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Un notika otrā dienā, ka tie ļaudis gāja uz lauku, un tas Abimelekam tapa sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Tad viņš ņēma tos (kara) ļaudis un tos dalīja trijos pulkos un paslēpās laukā. Un viņš skatījās, un redzi, tie ļaudis izgāja no pilsētas; tad viņš cēlās pret tiem un tos nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Un Abimeleks un tie pulki, kas pie viņa bija, uzbruka un nostājās priekš pilsētas vārtiem, bet tie divi pulki uzbruka visiem, kas bija laukā, un tos nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Un Abimeleks karoja pret to pilsētu visu to dienu un uzņēma to pilsētu un nokāva tos ļaudis, kas tanī bija, un nopostīja to pilsētu un apsēja to ar sāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Kad nu visi Šehemes pils namnieki to dzirdēja, tad tie gāja tai stiprā Berita dieva nama tornī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Un Abimelekam tas tapa sacīts, ka visi Šehemes pils namnieki bija sapulcējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Tad Abimeleks gāja uz Calmon kalnu, viņš un visi ļaudis, kas pie viņa bija, un Abimeleks ņēma cirvi savā rokā un nocirta koka zaru un to uzcēla un lika uz savu kamiesi un sacīja uz tiem ļaudīm, kas pie tā bija: ko esat redzējuši mani darām, to dariet steigšus tāpat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Tad arī visi ļaudis nocirta ikkatrs zaru un gāja Abimelekam pakaļ, un tos pielika pie tā stiprā torņa un iededzināja pār tiem to torni ar uguni, ka visi Šehemes pils ļaudis nomira līdz tūkstoš vīru un sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Un Abimeleks gāja uz Tebecu un apmetās pret Tebecu un to uzņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Bet pilsētas vidū bija stipra pils, uz turieni visi vīri un sievas un visi pilsētas namnieki bēga un ieslēdzās un uzkāpa uz pils jumtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Tad Abimeleks nāca pie tās pils un karoja pret to un piegāja pie pils durvīm, viņu ar uguni sadedzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Tad viena sieva nometa dzirnu akmens gabalu uz Abimeleka galvu un satrieca viņa galvas kausu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Tad viņš steigšus piesauca to puisi, savu bruņu nesēju, un uz to sacīja: izvelc savu zobenu un nokauj mani, lai no manis nesaka: viena sieva viņu nokāvusi. Un viņa puisis to nodūra, ka nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Kad nu Israēla vīri redzēja, ka Abimeleks bija nomiris, tad tie gāja ikkatrs uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tā Dievs Abimelekam maksāja to ļaunumu, ko viņš bija darījis savam tēvam, nokaudams savus septiņdesmit brāļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Un Dievs Šehemes vīriem atmaksāja visu ļaunumu uz viņu galvām, un Jotama, JerubBaāla dēla, lāsti nāca pār tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Un pēc Abimeleka, Tolus, Dodus dēla Puūs dēls, vīrs no Īsašara cilts, cēlās, Israēli pestīt, un dzīvoja Zamirā Efraīma kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Un viņš tiesāja Israēli divdesmit un trīs gadus un nomira un Zamirā tapa aprakts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Un pēc viņa cēlās Jaīrs, Gileādietis, un tiesāja Israēli divdesmit un divus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Un tam bija trīsdesmit dēli, tie jāja uz trīsdesmit ēzeļiem, un tiem bija trīsdesmit pilsētas, kuras nosauc (par) Jaīra ciemiem līdz šai dienai; tie ir Gileādas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Un Jaīrs nomira un tapa aprakts Kamonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Tad Israēla bērni joprojām darīja, kas Tam Kungam nepatika, un kalpoja Baāliem un Astartēm un Sīriešu dieviem un Sidonas dieviem un Moaba dieviem un Amona bērnu dieviem un Fīlistu dieviem un atstāja To Kungu un nekalpoja Viņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Tad Tā Kunga dusmība iedegās pret Israēli un Viņš tos pārdeva Fīlistu rokā un Amona bērnu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Un tie satrieca un samina Israēla bērnus no tā gada iesākot astoņpadsmit gadus, visus Israēla bērnus, kas viņpus Jardānes bija, Amoriešu zemē, tas ir Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Un Amona bērni gāja pār Jardāni un karoja pret Jūdu un pret Benjaminu un pret Efraīma namu, tā ka Israēlim bija ļoti bail.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Tad Israēla bērni brēca uz To Kungu un sacīja: mēs pret Tevi esam grēkojuši, jo mēs savu Dievu esam atstājuši un kalpojuši Baāliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Bet Tas Kungs sacīja uz Israēla bērniem: vai Es jūs neesmu izpestījis no ēģiptiešiem un Amoriešiem un Amona bērniem un Fīlistiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Un Sidoniešiem un Amalekiešiem un Maoniešiem, kad tie jūs spaidīja, un jūs uz Mani brēcāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Tomēr jūs Mani esat atstājuši un kalpojuši citiem dieviem, tādēļ Es jūs vairs negribu izpestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Ejat un brēciet uz saviem dieviem, ko jūs esat izmeklējušies, lai tie jūs izpestī jūsu bēdu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Bet Israēla bērni sacīja uz To Kungu: mēs esam grēkojuši; dari Tu mums, itin kā Tev patīk, izglāb mūs tikai šo reiz\'.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Un tie meta nost no sevis tos svešos dievus un kalpoja Tam Kungam. Tad Viņam palika žēl par Israēla bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Un Amona bērni tapa sasaukti un apmetās Gileādā un Israēla bērni sapulcējās un apmetās Micpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Tad tie ļaudis, Gileādas virsnieki, cits uz citu sacīja: kas būs tas vīrs, kas sāks karot pret Amona bērniem. Tam būs galvai būt pār visiem Gileādas iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jeftus, tas Gileādietis, bija stiprs karavīrs, bet viņš bija maukas bērns, ko Gileāds bija dzemdinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Kad nu Gileāda sieva viņam bērnus dzemdēja, un šās sievas bērni pieauga, tad tie Jeftu izdzina un uz to sacīja: tev nebūs mantot mūsu tēva namā, jo tu esi citas sievas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Tad Jeftus bēga no saviem brāļiem un dzīvoja Tobas zemē, un pie Jeftus sapulcējās nelieši un izgāja līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Un pēc kāda laika Amona bērni karoja pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Un kad Amona bērni pret Israēli karoja, tad Gileādas vecaji nogāja, Jeftu atvest no Toba zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Un tie sacīja uz Jeftu: nāc un esi mums par vadoni un karosim pret Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Bet Jeftus sacīja uz Gileādas vecajiem: vai jūs mani neesat ienīdējuši un mani izdzinuši no mana tēva nama? Kāpēc tad jūs nu nākat pie manis, kad jums ir bēdas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Un Gileādas vecaji sacīja uz Jeftu: tāpēc mēs nu pie tevis esam griezušies, ka tev būs iet ar mums un karot pret Amona bērniem; un tev būs būt par galvu mums, visiem Gileāda iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Un Jeftus sacīja uz Gileādas vecajiem: kad jūs mani atpakaļ vedat, karot pret Amona bērniem, un kad Tas Kungs tos nodos manā priekšā, tad es jums būšu par galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Un Gileādas vecaji sacīja uz Jeftu: lai Tas Kungs dzird mūsu sarunu, ja mēs tā nedarīsim, kā tu esi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Tad Jeftus gāja līdz Gileādas vecajiem, un tie ļaudis viņu iecēla sev par galvu un par vadoni, un Jeftus runāja visus savus vārdus Tā Kunga priekšā Micpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Un Jeftus sūtīja vēstnešus pie Amona bērnu ķēniņa un sacīja: kas tev ar mani, ka tu pie manis esi nācis, karot pret manu zemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Un Amona bērnu ķēniņš sacīja uz Jeftus vēstnešiem: tāpēc ka Israēls paņēmis manu zemi, kad viņš no Ēģiptes atnāca, no Arnonas līdz Jabokai un līdz Jardānei; tad nu atdod man to ar labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Bet Jeftus sūtīja atkal vēstnešus pie Amona bērnu ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Un uz to sacīja: tā saka Jeftus: Israēls nav ņēmis ne Moaba zemi, ne Amona bērnu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Jo kad viņš no Ēģiptes izgāja, tad Israēls gāja pa tuksnesi līdz niedru jūrai un nāca uz Kādešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Un Israēls sūtīja vēstnešus pie Edoma ķēniņa un sacīja: ļauj man jel iet caur tavu zemi, bet Edoma ķēniņš neklausīja. Un viņš sūtīja arī pie Moaba ķēniņa; tas arī negribēja. Tā Israēls palika Kādešā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Pēc tam viņš staigaja pa tuksnesi un apgāja ap Edoma zemi un Moaba zemi un nāca no rīta puses uz Moaba zemi; un tie apmetās viņpus Arnonas, bet tie nenāca Moabiešu robežās, jo Arnona ir Moabiešu robeža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Bet Israēls sūtīja vēstnešus pie Sihona, Amoriešu ķēniņa, kas bija Hešbonas ķēniņš, un Israēls uz viņu sacīja: ļauj mums jel iet caur tavu zemi līdz savai vietai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Bet Sihons Israēlim neuzticējās, ka tas tam būtu ļāvis iet caur savām robežām, bet Sihons sapulcēja visus savus ļaudis, un tie apmetās Jācā un karoja pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Un Tas Kungs, Israēla Dievs, nodeva Sihonu un visus viņa ļaudis Israēla rokā, ka tie tos sakāva, un Israēls iemantoja visu to zemi no Amoriešiem, kas tai zemē dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Un tie uzņēma visas Amoriešu robežas no Arnonas līdz Jabokai un no tuksneša līdz Jardānei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Tā nu Tas Kungs, Israēla Dievs, izdzinis Amoriešus Savu Israēla ļaužu priekšā, un tu gribi uzņemt to zemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Vai tev to nebūs paturēt, ko tavs dievs Kamos tev ir devis? Un mēs gribam paturēt visu to, ko Tas Kungs, mūsu Dievs, mums ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Un nu, vai tu esi labāks nekā Balaks, Cipora dēls, Moaba ķēniņš? Vai tas ar Israēli tiesājies, vai tas pret viņiem karojis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Kamēr Israēls dzīvojis Hešbonā un viņas ciemos un Aroērā un viņas ciemos un visās pilsētās, kas pie Arnonas, trīssimt gadus, - kāpēc tu tanī laikā tos neesi atņēmis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Un es pret tevi neesmu grēkojis, bet tu dari pret mani ļaunu, pret mani karodams. Tas Kungs, kas ir soģis, lai šodien tiesā starp Israēla bērniem un Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Bet Amona bērnu ķēniņš neklausīja Jeftus vārdiem, ko viņš pie tā bija sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Tad Tā Kunga Gars nāca uz Jeftu, un viņš gāja caur Gileādu un Manasu, un viņš gāja uz Micpu Gileādā un no Micpas Gileādā viņš gāja pret Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Un Jeftus solīja solījumu Tam Kungam un sacīja: ja tu Amona bērnus dosi manā rokā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Tad tam, kas no mana nama durvīm man nāks pretī, kad es ar mieru no Amona bērniem griezīšos atpakaļ, būs piederēt Tam Kungam, un es to upurēšu par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Tad Jeftus gāja pret Amona bērniem ar tiem kauties, un Tas Kungs tos nodeva viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Un viņš tos kāva varen lielā kaušanā no Aroēra, kamēr nāk uz Minitu, divdesmit pilsētas, un līdz tiem vīna kalnu klajumiem; tā Amona bērni tapa pazemoti Israēla bērnu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Kad nu Jeftus nāca uz Micpu pie sava nama, redzi, tad viņa meita viņam izgāja pretī ar bungām un stabulēm, un viņa bija tikai viņa vienīgā, un viņam nebija bez tās ne dēla ne meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Un kad viņš to redzēja, tad viņš saplosīja savas drēbes un sacīja: ak mana meita! Tu mani lauztin esi salauzusi un tu mani apbēdini, jo es savu muti esmu atdarījis Tā Kunga priekšā un nevaru atrauties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Un viņa uz to sacīja: mans tēvs, ja tu savu muti Tā Kunga priekšā esi atdarījis, tad dari man, kā tas no tavas mutes gājis, kad Tas Kungs tevi atriebis pie taviem ienaidniekiem, Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Un viņa sacīja uz savu tēvu: lai man tā notiek; dod man vaļu divus mēnešus, ka es eju un noeju kalnos un apraudu savu jumpravību, es ar savām biedrenēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Un viņš sacīja: ej! Un viņš to atlaida divus mēnešus. Tad viņa nogāja ar savām biedrenēm un apraudāja kalnos savu jumpravību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Un pēc diviem mēnešiem tā griezās atpakaļ pie sava tēva, un viņš tai darīja pēc sava solījuma, ko viņš bija solījis, un viņa vīra neatzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Un iekš Israēla palika par likumu, ka Israēla meitas ik gadus nogāja, Jeftus, tā Gileādieša, meitu, nožēlot četras dienas gadskārtā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Tad Efraīma vīri tapa sasaukti un gāja pret ziemeļa pusi un sacīja uz Jeftu: kāpēc tu esi gājis karot pret Amona bērniem un mūs neesi aicinājis, tev iet līdzi? Mēs tavu namu pār tevi sadedzināsim ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Un Jeftus uz tiem sacīja: man un maniem ļaudīm bija liels strīds ar Amona bērniem, un es jūs lūdzu, bet jūs man nepalīdzējāt (atbrīvoties) no viņu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Kad es nu redzēju, ka jūs negribējāt palīdzēt, tad es savu dvēseli liku savā rokā un gāju pret Amona bērniem, un Tas Kungs tos nodeva manā rokā. Kāpēc tad jūs šodien pret mani esat nākuši, karot ar mani?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Un Jeftus sapulcēja visus Gileādas vīrus un karoja ar Efraīmu, un Gileādas vīrī sakāva Efraīmu, tāpēc ka tie sacīja: jūs Gileādieši starp Efraīma un Manasus, jūs esat Efraīma bēgļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Un Gileādieši aizņēma Efraīmiešiem Jardānes pārejamo vietu. Un kad Efraīmieši bēgot sacīja: ļauj man pāriet! Tad Gileādas vīri uz to sacīja: vai tu esi no Efraīma? Kad viņš tad sacīja: ne!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Tad tie uz viņu sacīja: saki jel: Šibolet! Un kad tas sacīja: Sibolet! Un to nevarēja pareizi izrunāt; tad tie viņu sagrāba un to nokāva pie Jardānes pārejamās vietas, ka tanī laikā no Efraīma četrdesmit divi tūkstoši krita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Bet Jeftus tiesāja Israēli sešus gadus. Un Jeftus, tas Gileādietis, nomira un tapa aprakts kādā Gileādas pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Un pēc viņa Ebcans no Bētlemes tiesāja Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Un tam bija trīsdesmit dēli, un trīsdesmit meitas viņš izdeva, un trīsdesmit meitas viņš ieveda no ārienes priekš saviem dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Un tas Israēli tiesāja septiņus gadus; tad Ebcans nomira un tapa aprakts Bētlemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Un pēc viņa Elons, tas Zebulonietis, tiesāja Israēli, un tas Israēli tiesāja desmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Un Elons, tas Zebulonietis, nomira un tapa aprakts Ajalonā, Zebulona zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Un pēc viņa Abdons, Ilela, tā Piratonieša, dēls, tiesāja Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Un tam bija četrdesmit dēli un trīsdesmit dēlu dēli, kas uz septiņdesmit ēzeļiem jāja, un tas tiesāja Israēli astoņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Un Abdons, Ilela, tā Piratonieša, dēls, nomira un tapa aprakts Piratonā, Efraīma zemē, uz Amaleka kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Un Israēla bērni darīja joprojām, kas Tam Kungam nepatika; tad Tas Kungs tos nodeva Fīlistu rokā četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Un tur bija viens vīrs no Careas, no Dana cilts, un viņa vārds bija Manoūs, un viņa sieva bija neauglīga un nedzemdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Un Tā Kunga eņģelis parādījās tai sievai un uz to sacīja: redzi, tu esi neauglīga un neesi dzemdējusi, bet tu tapsi grūta un dzemdēsi dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Tad nu sargies un nedzer vīna nedz stipra dzēriena un neēd nekā, kas nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Jo redzi, tu tapsi grūta un dzemdēsi dēlu, kam uz galvu nebūs nākt nekādam dzenamam nazim, jo tas puisis būs Dievam svētīts (nazīrs) no mātes miesām, un viņš sāks Israēli izpestīt no Fīlistu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Tad tā sieva nāca un runāja uz savu vīru un sacīja: viens Dieva vīrs pie manis atnāca; viņa ģīmis bija kā Dieva eņģeļa ģīmis, ļoti bijājams, un es viņu nevaicāju, no kurienes tas esot, un viņš man arī savu vārdu neteica.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Bet viņš uz mani sacīja: redzi, tu tapsi grūta un dzemdēsi dēlu, un nu nedzer vīna nedz stipra dzēriena, nedz ēd ko, kas nešķīsts, jo tas puisis būs Dievam svētīts no mātes miesām līdz pat savai nāves dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Tad Manoūs pielūdza To Kungu un sacīja: Ak Kungs, lai jel tas Dieva vīrs, ko Tu esi sūtījis, atkal pie mums atnāk un mums māca, ko lai ar to bērnu darām, kas piedzims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Un Dievs paklausīja Manoūs balsi, un tas Dieva eņģelis nāca atkal pie tās sievas; un viņa sēdēja tīrumā, bet Manoūs, viņas vīrs, nebija pie viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Tad tā sieva steidzās un skrēja un to pasacīja savam vīram, un uz to sacīja: redzi, tas vīrs man parādījies, kas tai dienā pie manis nāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Tad Manoūs cēlās un gāja savai sievai pakaļ un nāca pie tā vīra un uz to sacīja: vai tu esi tas vīrs, kas uz to sievu runājis? Un tas sacīja: es tas esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Tad Manoūs sacīja: kad nu tas notiks, ko tu sacījis, kāds tikums tad būs tam zēnam un kāds būs viņa darbs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Un Tā Kunga eņģelis sacīja uz Manoū: no visa, ko es uz to sievu esmu runājis, viņai būs sargāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Viņai nebūs ēst nekā, kas no vīna koka izaug, un viņai nebūs dzert ne vīna, ne stipra dzēriena, nedz ēst, kas nešķīsts, visu, ko es viņai esmu pavēlējis, viņai būs turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Tad Manoūs sacīja uz Tā Kunga eņģeli: lūdzams, pakavējies un mēs sataisīsim priekš tevis kazlēnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Tad Tā Kunga eņģelis sacīja uz Manoū; jebšu tu mani uzkavētu, tomēr es no tavas maizes neēdīšu, bet ja tu gribi dedzināmo upuri pienest, to tu Tam Kungam vari upurēt. Jo Manoūs nezināja, viņu esam Tā Kunga eņģeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Un Manoūs sacīja uz Tā Kunga eņģeli: kā tavs vārds? Ka tevi varam godāt, kad notiks pēc tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Tad Tā Kunga eņģelis uz viņu sacīja: kāpēc tu tā vaicā pēc Mana Vārda, kas taču ir brīnišķīgs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Tad Manoūs ņēma kazlēnu un to ēdamo upuri, un to upurēja Tam Kungam uz tās klints; un viņš darīja brīnumu un Manoūs un viņa sieva skatījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Jo kad liesma no altāra virsas šāvās pret debesi, tad Tā Kunga eņģelis uzkāpa altāra liesmā. Un Manoūs un viņa sieva to redzēja un metās pie zemes uz saviem vaigiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Un Tā Kunga eņģelis neparādījās vairs ne Manoūm, nedz viņa sievai. Tad Manoūs atzina, ka tas bija Tā Kunga eņģelis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Un Manoūs sacīja uz savu sievu: mēs tiešām mirsim, jo mēs esam Dievu redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Bet viņa sieva uz viņu sacīja: kad Tas Kungs mūs gribētu nokaut, tad Viņš to dedzināmo upuri un ēdamo upuri nebūtu pieņēmis no mūsu rokām; Viņš arī visas šīs lietas mums nebūtu parādījis, nedz mums to licis dzirdēt šai laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Un tā sieva dzemdēja dēlu un nosauca viņa vārdu Simsons, un tas zēns uzauga, un Tas Kungs to svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Un Tā Kunga Gars viņu sāka skubināt Dana lēģerī starp Careu un Estaoli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Un Simsons nogāja uz Timnatu un redzēja vienu sievieti Timnatā no Fīlistu meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Un viņš aizgāja un to stāstīja savam tēvam un savai mātei un sacīja: Timnatā es esmu redzējis sievieti no Fīlistu meitām, - un nu ņemiet man to par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Tad viņa tēvs un viņa māte uz viņu sacīja: vai nav starp tavu brāļu meitām kāda sieva un starp visiem maniem ļaudīm, ka tu noej sievu ņemt no Fīlistiem, tiem neapgraizītiem? Un Simsons sacīja uz savu tēvu: ņem man viņu, jo tā manām acīm patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Bet viņa tēvs un viņa māte nezināja, ka tas bija no Tā Kunga, ka viņš iemeslus meklētu pie Fīlistiem; bet Fīlisti valdīja tanī laikā pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Tad Simsons ar savu tēvu un ar savu māti nogāja uz Timnatu. Kad tie nu pie Timnatas vīna kalniem nāca, redzi, tad jauns lauva viņam rūca pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Un Tā Kunga Gars nāca pār viņu, un viņš to saplēsa, tā kā kazlēnu saplēš, un viņa rokā nebija nekā; bet viņš ne savam tēvam, ne savai mātei nesacīja, ko viņš bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Un viņš nonāca un runāja ar to sievu, un tā patika Simsona acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Un kad viņš pēc kādām dienām griezās atpakaļ, viņu ņemt, tad viņš no ceļa nogāja, raudzīt tā lauvas maitu, un redzi lauvas maitā bija bišu pulks ar medu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Un viņš to ņēma savās rokās un gāja projām un ēda un gāja pie sava tēva un pie savas mātes un tiem deva, un tie ēda, bet viņš tiem nesacīja, ka viņš to medu bija ņēmis no lauvas maitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Kad nu viņa tēvs pie tās sievas bija nonācis, tad Simsons tur turēja kāzas, jo tā tie jaunekļi mēdza darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Un kad tie viņu redzēja, tad tie ņēma trīsdesmit biedrus, un tie bija pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Un Simsons uz tiem sacīja: es jums došu mīklu minēt; kad jūs to man šinīs septiņās kāzu dienās sacīsiet un uzminēsiet, tad es jums došu trīsdesmit kreklus no smalka audekla un trīsdesmit svētku drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Un ja jūs man to nevarēsiet uzminēt, tad jums man būs dot trīsdesmit kreklus no smalka audekla un trīsdesmit svētku drēbes. Un tie uz viņu sacīja: pasaki savu mīklu, lai mēs to dzirdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Un viņš uz tiem sacīja: barība izgāja no rijēja un saldums izgāja no stiprā. Un tanīs trijās dienās tie to mīklu nevarēja uzminēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Un septītā dienā tie sacīja uz Simsona sievu: pārrunā savu vīru, lai viņš mums to mīklu saka, ka mēs tevi un tava tēva namu nesadedzinām ar uguni; vai jūs mūs esat aicinājuši, mūsu mantu mums atņemt, vai ne?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Un Simsona sieva raudāja pie viņa un sacīja: tu mani tikai ienīsti, un mani nemīli; tu manu ļaužu bērniem esi devis mīklu un man to nesaki. Un viņš uz to sacīja: redzi, es ne savam tēvam, ne savai mātei to neesmu sacījis, un tev lai es to saku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Bet tā raudāja pie viņa septiņas dienas, kamēr tās kāzas bija, bet septītā dienā tas viņai to sacīja, jo viņa to spieda. Un viņa sacīja to mīklu savu ļaužu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Tad tās pilsētas vīri uz viņu sacīja septītā dienā, pirms saule nogāja: kas ir saldāks nekā medus? Kas ir stiprāks nekā lauva? Un viņš uz tiem sacīja: ja jūs ar manu teļu nebūtu aruši, tad jūs manu mīklu nebūtu uzminējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Tad Tā Kunga Gars nāca pār viņu un viņš nogāja uz Askalonu un nokāva no tiem trīsdesmit vīrus, un ņēma viņu novilktās drēbes un deva svētku drēbes tiem, kas to mīklu bija uzminējuši. Bet viņa dusmas iedegās un viņš aizgāja sava tēva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Un Simsona sieva tika dota viņa biedram, kas tam bija bijis par biedru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Un notikās pēc kādam dienām ap kviešu pļaujamo laiku, tad Simsons savu sievu apmeklēja ar kazlēnu un sacīja: es gribu iet pie savas sievas kambarī; bet viņas tēvs viņam neļāva iet kambarī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Jo viņas tēvs sacīja: es domāju, ka tu nīdēdams viņu ienīsti, tāpēc es to tavam biedram esmu devis. Vai viņas jaunākā māsa nav skaistāka nekā viņa? Lai jel šī ir tava viņas vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Tad Simsons uz tiem sacīja: šim brīdim es esmu nenoziedzīgs pie Fīlistiem, ja es tiem ļaunu darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Un Simsons aizgāja un gūstīja trīs simt lapsas un ņēma pagales un grieza asti pret asti un lika vienu pagali vidu starp divām astēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Un viņš tās pagales iededzināja ar uguni un tās palaida Fīlistu druvās, un iededzināja gan gubas, gan druvas, gan vīna dārzus, gan eļļas kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Tad tie Fīlisti sacīja: kas to ir darījis? Tad tapa sacīts: Simsons, tā Timnieša znots, tāpēc ka tas viņa sievu ņēmis un viņa biedrim devis. Tad Fīlisti nāca un sadedzināja viņu un viņas tēvu ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Un Simsons uz tiem sacīja: ja jūs tā dariet, tad es pret jums atriebšos un tad tikai mitēšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Un viņš sita tos par pleciem un gurniem ar lielu sišanu; un viņš nogāja un dzīvoja Etama klints alā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Tad Fīlisti aizgāja un apmeta lēģeri pret Jūdu un apmetās Liejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Un tie vīri no Jūda sacīja: kāpēc jūs pret mums esat cēlušies? Un tie sacīja: mēs esam nākuši, Simsonu saistīt, lai mēs viņam darām, kā viņš mums darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Tad nonāca trīstūkstoš vīri no Jūda uz Etama klints alu un sacīja uz Simsonu: vai tu nezini, ka Fīlisti pār mums valda? Kāpēc tad tu mums to esi darījis? Un viņš uz tiem sacīja: kā tie man ir darījuši, tā es atkal tiem esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Un tie uz viņu sacīja: mēs esam nonākuši tevi saistīt un tevi nodot Fīlistu rokā. Un Simsons uz tiem sacīja: zvērējiet man, ka jūs mani negribat nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Un tie runāja uz viņu sacīdami: nē, bet mēs esam nākuši tevi saistīt un tevi viņu rokā nodot, bet mēs tevi nenokausim. Un tie viņu saistīja ar divām jaunām virvēm un to veda augšām no tās klints.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Kad nu viņš līdz Liejai nāca, tad Fīlisti viņam gavilēja pretī, bet Tā Kunga Gars nāca pār viņu, un tās virves, kas bija ap viņa rokām, kļuva tā kā linu pavedieni, ko uguns ir apsvilinājis, un viņa saites trūka no viņa rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Un viņš atrada jaunu ēzeļa žokļa kaulu, un izstiepa savu roku un to ņēma un ar to nosita tūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Un Simsons sacīja: ar ēzeļa žokļa kaulu vienu pulku, divus pulkus, ar ēzeļa žokļa kaulu nokāvu tūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Un kad viņš bija izrunājis, tad viņš nometa to žokļa kaulu no savas rokas un nosauca to vietu RamatLieja (žokļa kaula kalns).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Un viņš bija ļoti izslāpis un piesauca To Kungu un sacīja: Tu caur Sava kalpa roku šo lielo pestīšanu esi devis, un nu man aiz slāpēm jāmirst un jākrīt šo neapgraizīto rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Tad Dievs pāršķēla kādu dobumu, kas bija Liejā; tad ūdens no tā izgāja, un viņš dzēra. Un viņa gars griezās atpakaļ, un viņš atspirga; tāpēc viņš to vietu nosauca Piesaucēja avotu, kas ir Liejā līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Un viņš tiesāja Israēli Fīlistu laikā divdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Un Simsons gāja uz Gazu un tur ieraudzīja vienu sievieti, kas bija mauka, un iegāja pie tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Un Gaziešiem tapa sacīts: Simsons ir šurp atnācis. Un tie gāja apkārt un glūnēja uz viņu cauru nakti pilsētas vārtos un turējās klusu cauru nakti un sacīja: kad rīta gaisma aust, tad to nokausim. Bet Simsons gulēja līdz pusnaktij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Un nakts vidū viņš cēlās un sagrāba pilsētas vārtus ar tiem diviem stabiem un tos izcēla līdz ar aizšaujamo un tos lika uz saviem pleciem un tos uznesa uz tā kalna galu, kas ir pret Hebronu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Un notikās pēc tam, ka viņš iemīļoja vienu sievieti pie Zoreka upes ar vārdu Delila.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Tad Fīlistu lielkungi pie tās atnāca un uz to sacīja: pārrunā viņu un lūko, iekš kā viņa lielais spēks stāv, un ar ko viņu spējam pārvarēt, ka viņu saistām un savaldām, tad mēs tev dosim ikkatrs tūkstoš un simts sudraba (gabalus).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Tad Delila sacīja uz Simsonu: saki man jel lūdzams, iekš kam stāv tavs lielais spēks, un ar ko tevi var saistīt un savaldīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Un Simsons uz to sacīja: ja mani saistītu ar septiņām zaļām lūku virvēm, kas vēl nav sakaltušas, tad es taptu nespēcīgs un būtu tā kā cits cilvēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Tad Fīlistu lielkungi pie tās atnesa septiņas zaļas lūku virves, kas nebija sakaltušas, un tā viņu ar tām saistīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Bet tie glūnētāji pie tās sēdēja kambarī. Un tā sacīja uz viņu: Fīlisti pār tevi, Simson! Tad viņš saraustīja tās virves tā kā pakulu pavedienu sarauta, kas pie uguns apsvilināts. Un viņa spēks netapa zināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Tad Delila sacīja uz Simsonu: redzi, tu mani esi mānījis un man melus stāstījis. Nu tad saki man lūdzams, ar ko tevi var saistīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Un viņš uz to sacīja: ja mani saistītu ar jaunām virvēm, ar ko nekāds darbs nav darīts, tad es taptu bezspēcīgs un būtu kā cits cilvēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Tad Delila ņēma jaunas virves un viņu ar tām saistīja un uz to sacīja: Fīlisti pār tevi, Simson! Un tie glūnētāji sēdēja kambarī. Bet viņš tās saraustīja no savām rokām tā kā pavedienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Tad Delila sacīja uz Simsonu: līdz šim tu mani esi mānījis un man melus stāstījis; saki man jel, ar ko tevi var saistīt? Un viņš uz to sacīja: ja tu manas septiņas matu bizes aptītu ap riestavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Un viņa tās piesita ar tapu un uz to sacīja: Fīlisti pār tevi, Simson! Un viņš uzmodās no sava miega un izrāva to aptīto tapu un to riestavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Tad viņa uz to sacīja: kā tu vari sacīt: es tevi mīlēju, kad tomēr tava sirds nav ar mani? Tu nu trīs reiz mani esi mānījis un man neesi sacījis, iekš kam tavs lielais spēks stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Un kad viņa to ikdienas ar savām runām māca un mocīja, tad viņa dvēsele apnika līdz pat nāvei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Un tas viņai darīja zināmu visu savu sirdi un uz viņu sacīja: uz manu galvu dzenamais nazis nav nācis, jo es esmu Dievam svētīts no mātes miesām; kad (mani mati) taptu nodzīti, tad mans spēks no manis atstātos, un es taptu bezspēcīgs un būtu tā kā visi citi cilvēki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Kad nu Delila redzēja, ka tas viņai visu savu sirdi bija izsacījis, tad viņa nosūtīja un sasauca Fīlistu lielkungus sacīdama: atnāciet vēl šo reiz\', jo viņš man izsacījis visu savu sirdi. Tad Fīlistu lielkungi pie viņas atnāca un atnesa to sudrabu savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Bet viņa tam lika aizmigt savā klēpī un aicināja vīru un lika nodzīt viņa galvas septiņas matu bizes un sāka viņu pārvarēt, un viņa spēks no viņa atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Un viņa sacīja: Fīlisti pār tevi, Simson! Un viņš uzmodās no sava miega un domāja: es iziešu šo reizi kā citām reizēm un izraušos; jo viņš nezināja, ka Tas Kungs no viņa bija atstājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Tad Fīlisti viņu sagrāba un izdūra viņam acis un to noveda uz Gazu un to sēja ar divām vara ķēdēm, un viņam tur cietumā bija jāmaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Bet viņa galvas mati sāka atkal ataugt, kad tie bija nodzīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Tad Fīlistu lielkungi sapulcējās, savam dievam Dagonam lielu upuri upurēt un līksmoties, un tie sacīja: mūsu dievs mūsu ienaidnieku Simsonu nodevis mūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Un kad tie ļaudis viņu redzēja, tad tie teica savu dievu, jo tie sacīja: mūsu dievs mūsu ienaidnieku mums ir rokā devis, kas mūsu zemi ir postījis un lielu pulku no mums nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Un kad viņu sirds līksmojās, tad tie sacīja: sauciet Simsonu, lai tas mūs pajautrina. Tad tie sauca Simsonu no cietuma nama, un viņš tiem bija par pajautrināšanu, un tie viņam lika stāvēt starp diviem stabiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Tad Simsons sacīja uz to puisi, kas viņu pie rokas vadīja: laid mani vaļā un ļauj man tos stabus taustīt, uz kā tas nams stiprināts, un pie tiem atslieties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Bet tas nams bija pilns ar vīriem un sievām. Un tur bija visi Fīlistu lielkungi, un uz tā jumta bija kādi trīs tūkstoši vīri un sievas, kas lūkojās uz Simsona jautrināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Tad Simsons piesauca To Kungu un sacīja: Kungs, Dievs, piemini mani un stiprini lūdzams mani tikai šo reiz\', ak Dievs, ka es par savām abējām acīm vienreiz varu atriebties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Un Simsons apkampa tos divus vidējos stabus, uz kā tas nams bija stiprināts un uz kā tas turējās, vienu ar savu labo roku un vienu ar savu kreiso roku, un Simsons sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Lai mana dvēsele mirst ar tiem Fīlistiem! Un viņš locījās ar varu, - tad tas nams krita uz tiem lielkungiem un uz visiem ļaudīm, kas iekšā bija un vairāk bija miroņu, ko viņš mirdams nokāva, nekā ko viņš bija nokāvis, dzīvs būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Tad viņa brāļi un viss viņa tēva nams nonāca un to ņēma un to aiznesa un apraka starp Careū un Estaoli, Manoūs, viņa tēva, kapā. Un viņš Israēli bija tiesājis divdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Un viens vīrs bija no Efraīma kalniem, tam vārds bija Miha.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Tas sacīja uz savu māti: tie tūkstoš un simts sudraba gabali, kas tev ir atņemti, un kādēļ tu esi apzvērējusies un arī priekš manām ausīm to sacījusi; redzi, tā nauda ir pie manis, es to esmu ņēmis. Tad viņa māte sacīja: esi svētīts, mans dēls, no Tā Kunga!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Tad viņš savai mātei atdeva tos tūkstoš un simts sudraba gabalus, bet viņa māte sacīja: es svētīdama šo naudu Tam Kungam esmu svētījusi no savas rokas priekš sava dēla, lai taisa izgrieztu tēlu un lietu bildi; tad nu es tev to atdodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Bet viņš savai mātei to naudu atdeva, un viņa māte ņēma divsimt sudraba gabalus un tos deva sudraba kalējam; tas no tā iztaisīja izgrieztu tēlu un lietu bildi. Un tie bija Mihas namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Un tam vīram Miham bija dievanams, un viņš taisīja efodu un elku dievus un iesvētīja vienu no saviem dēliem, lai tas viņam būtu par priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Tanīs dienās ķēniņa nebija iekš Israēla; ikviens darīja, ko viņš domāja esam labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Bet viens jauneklis bija no Jūda Bētlemes, no Jūda radiem; tas bija Levits un tur piemājoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Un tas vīrs bija nogājis no pilsētas, no Jūda Bētlemes, piemist, kur vieta gadītos. Kad nu viņš nāca uz Efraīma kalniem uz Mihas namu, pa savu ceļu staigādams, tad Miha uz viņu sacīja: no kurienes tu nāci?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Un viņš uz to sacīja: es esmu Levits no Jūdu Bētlemes un eju piemist, kur gadīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Tad Miha uz viņu sacīja: paliec pie manis un esi man par tēvu un priesteri, tad es tev par gadu došu desmit sudraba gabalus un tās vajadzīgās drēbes un uzturu. Un tas Levits (pie viņa) nogāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Un tas Levits bija ar mieru pie tā vīra palikt, un tas jauneklis viņam bija kā viens no viņa dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Un Miha to Levitu iesvētīja, lai tas jauneklis viņam būtu par priesteri, un tas bija Mihas namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Tad Miha sacīja: nu es zinu, ka Tas Kungs man labu darīs, tāpēc, ka man šis Levits par priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Tanīs dienās ķēniņa nebija iekš Israēla, un tanīs dienās Daniešu cilts meklēja īpašu vietu priekš sevis, kur varētu dzīvot, jo viņai nekāda īpaša vieta starp Israēla ciltīm nebija piešķirta līdz tai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Tad Dana bērni no saviem radiem sūtīja kādus piecus vīrus, no savējiem, kas bija stipri, no Careās un Estaoles, zemi izlūkot un pārmeklēt, un tie uz viņiem sacīja: ejat, pārmeklējiet zemi. Un tie nāca pie Efraīma kalniem līdz Mihas namam un palika turpat par nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Un tur pie Mihas nama būdami viņi pazina tā jaunekļa, tā Levita, balsi un nogriezās uz turieni un sacīja uz to: kas tevi še atvedis? Un ko tu še dari? Un kas tev šeitan ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Un tas uz viņiem sacīja: tā un tā man Miha darījis un mani saderējis, un es viņam esmu par priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Tad tie uz viņu sacīja: vaicā jel Dievam, ka mēs atzīstam, vai mūsu ceļš labi izdosies, ko ejam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Un tas priesteris uz tiem sacīja: ejat ar mieru! Jūsu ceļš, ko ejat, ir taisns priekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Tad tie pieci vīri nogāja un nāca uz Laīsu un ieraudzīja tos ļaudis tai vidū droši dzīvojam, pēc Sidoniešu ieraduma mierīgi un droši, un tai zemē nebija neviena valdītāja, kas kādas lietas dēļ kādu apbēdinātu; un tie bija arī tālu no Sidoniešiem un tiem nebija nekādas darīšanas ar nekādu cilvēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Un tie nāca pie saviem brāļiem uz Careū un Estaoli, un viņu brāļi uz tiem sacīja: ko jūs sakāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Tad tie sacīja: celsimies un iesim pret tiem, jo mēs to zemi esam izlūkojuši, un redzi, tā ir ļoti laba; un jūs turaties klusu? Neesiet kūtri iet, ka nākat to zemi uzņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kad jūs nākat, tad jūs nākat pie drošiem ļaudīm, un tai zemei ir plašas robežas; jo Dievs to devis jūsu rokās, vietu, kur nekāda trūkuma nav nekādā lietā, kas ir virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Tad no turienes, no Daniešu radiem, no Careās un Estaoles, aizgāja sešsimt apbruņoti karavīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Un tie cēlās un apmetas KiriatJearimā iekš Jūda; tādēļ to vietu nosauc par Dana lēģeri līdz šai dienai; redzi tas ir aiz KiriatJearimas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Un no turienes tie gāja uz Efraīma kalniem un nāca pie Mihas nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Tad tie pieci vīri, kas bija gājuši Laisas zemi izlūkot, sacīja uz saviem brāļiem: vai jūs zināt, ka šinī namā ir efods un elka dievi un izgriezts tēls un lieta bilde? Tad nu jūs paši varat zināt, kas jums jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Un tie nogriezās uz turieni un nāca pie tā jaunekļa, tā Levita, namu, pie Mihas nama, un to apsveicināja mīlīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Bet tie sešsimt vīri, kas bija no Dana bērniem, ar kara rīkiem apbruņoti, stāvēja pie vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Bet tie pieci vīri, kas bija gājuši zemi izlūkot, nāca uz turieni un paņēma to izgriezto tēlu un to efodu un tos elka dievus un to lieto bildi, un tas priesteris stāvēja pie vārtiem ar tiem sešsimt apbruņotiem vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Kad nu šie Mihas namā nāca un paņēma to izgriezto tēlu un to efodu un tos elka dievus un to lieto bildi, tad tas priesteris uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Ko jūs darāt? Un tie uz viņu sacīja: klusu, turi muti, un ej mums līdz un esi mums par tēvu un par priesteri. Vai tas tev labāki, viena vienīga vīra namā būt par priesteri nekā pie vienas cilts un viena rada iekš Israēla?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Tad tas tam priesterim bija pa prātam, un viņš ņēma to efodu un tos elka dievus un to izgriezto tēlu un gāja līdz to ļaužu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Un viņi griezās atpakaļ un nogāja un laida papriekš bērniņus un ganāmo pulku un savas dārgās lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Kad tie nu tālu no Mihas nama bija nākuši, tad tie vīri tapa sasaukti, kas bija tais namos pie Mihas nama, un tie panāca Dana bērnus un uzsauca tiem Dana bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Bet šie atgriezās un sacīja uz Miha: kas tev ir, ka tu savus ļaudis esi sasaucis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Tad viņš sacīja: jūs manus dievus, ko es esmu taisījis, esat atņēmuši līdz ar to priesteri un esat aizgājuši; kas tad nu man vēl ir? Un jūs sakāt uz mani: kas tev kait?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Bet Dana bērni uz viņu sacīja: lai tava balss pie mums netop dzirdēta, ka ļauni vīri pār tēvi nenāk un tu nepazaudē savu dzīvību līdz ar sava nama dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Tā Dana bērni aizgāja pa savu ceļu. Un kad Miha redzēja, ka tie jo stiprāki bija nekā viņš, tad viņš griezās atpakaļ uz savu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Bet tie to ņēma, ko Miha bija taisījis, un to priesteri, kas viņam bija bijis, un gāja uz Laīsu pie tiem ļaudīm, kas mierīgi un droši dzīvoja, un tos apkāva ar zobena asmeni, un to pilsētu sadedzināja ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Un nebija neviena, kas tos būtu izglābis, jo tā bija tālu no Sidonas, un tiem nebija nekādas darīšanas ar ļaudīm, un tā pilsēta stāvēja tai ielejā, kas ir pie BetRehobas. Un tie uztaisīja to pilsētu no jauna un dzīvoja tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Un tie nosauca tās pilsētas vārdu Dan, pēc sava tēva Dana vārda, kas Israēlim bija dzimis, jebšu tās pilsētas vārds papriekš bija Laīsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Un Dana bērni tur uzcēla to izgriezto tēlu priekš sevis, un Jonatāns, Manasus dēla, Geršona, dēls un viņa dēli bija priesteri Daniešu ciltī līdz tai dienai, kad tās zemes ļaudis tapa aizvesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Tā tie priekš sevis uzcēla Mihas izgriezto tēlu, ko tas bija taisījis, kamēr Dieva nams bija Šīlo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Un tanīs dienās ķēniņa nebija iekš Israēla. Un viens vīrs, Levits, piemita aiz Efraīma kalniem, tas sev ņēma lieku sievu no Jūda Bētlemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Bet viņa liekā sieva pie viņa būdama dzina maucību un nogāja no viņa sava tēva namā uz Bētlemi Judā, un tur sabija kādu laiku, četrus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Tad viņas vīrs cēlās un gāja viņai pakaļ, ka tas mīlīgi ar viņu runātu un viņu vestu atpakaļ, un viņa puisis bija viņam līdz un pāris ēzeļu; un viņa to ieveda sava tēva namā, un kad tās sievietes tēvs viņu redzēja, tad viņš līksmojās viņam pretī (iedams).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Un viņa tēvocis, tās sievietes tēvs, viņu paturēja, ka tas trīs dienas pie viņa palika, un tie ēda un dzēra un palika tur par nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Un ceturtā dienā tie steidzās agri un cēlās iet projām. Tad tās sievietes tēvs sacīja uz savu znotu: stiprini savu sirdi ar kādu maizes kumosu, un tad jūs varat iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Tad tie apsēdās un ēda abi kopā un dzēra, un tās sievietes tēvs sacīja uz to vīru: dari lūdzams tā un paliec par nakti, un lai tava sirds līksmojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Bet tas vīrs cēlās iet projām, un viņa tēvocis to ļoti turēja, ka tam bija jāgriežas atpakaļ un tur jāpaliek par nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Kad nu viņš piektā dienā no rīta taisījās aiziet, tad tās sievietes tēvs sacīja: stiprini jel savu sirdi; un tie kavējās, līdz kamēr vakars metās, un tie abi ēda kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Tad tas vīrs cēlās aiziet, viņš un viņa liekā sieva un viņa puisis. Bet viņa tēvocis, tās sievietes tēvs, uz viņu sacīja: redzi jel, šī diena jau līdz vakaram ir pavadīta, paliec jel par nakti; redzi, šī diena beidzās, paliec par nakti šeitan un lai tava sirds līksmojās, dodaties rīt agri uz savu ceļu un ej uz savu dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Bet tas vīrs negribēja par nakti palikt, un cēlās un aizgāja un nāca pret Jebuzu, tā ir Jeruzāleme, viņš un tas pāris apkrautu ēzeļu un viņa liekā sieva ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Kad nu tie pie Jebuzas bija, tad jau bija pavakars, un tas puisis sacīja uz savu kungu: nāc lūdzams un ieiesim šinī Jebusiešu pilsētā un paliksim tur par nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Bet viņa kungs uz viņu sacīja: mēs negribam griezties uz svešu pilsētu, kas nav no Israēla bērniem, bet gribam noiet līdz Ģibejai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Tad viņš sacīja uz savu puisi: nāc, ka mēs uz vienu no šīm vietām tiekam, un Ģibejā vai Ramā par nakti paliekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Tā tie gāja tālāk un staigāja, un saule tiem nogāja it klātu pie Ģibejas, kas pieder Benjaminam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Un tie griezās uz turieni, ka nāktu un Ģibejā paliktu par nakti. Kad viņš nu iegāja, tad viņš apsēdās kādā pilsētas ielā, jo tur nebija neviena, kas tiem savā namā gribēja dot naktsmājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Un redzi, viens vecs vīrs nāca vakarā no sava darba no tīruma, un tas vīrs arīdzan bija no Efraīma kalniem, bet piemita Ģibejā; bet tās vietas ļaudis bija Benjaminieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Kad tas vecais vīrs nu savas acis pacēla, tad viņš to ceļa vīru ieraudzīja pilsētas ielā un sacīja: uz kurieni tu ej? Un no kurienes tu nāc?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Un tas uz viņu sacīja: mēs no Jūda Bētlemes ejam aiz Efraīma kalniem, no kurienes es arī esmu, un es biju nogājis uz Jūda Bētlemi un es eju uz Tā Kunga namu, un neviena nav, kas man mājas vietu dod savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Un tomēr salmi un ēdamais mums priekš mūsu ēzeļiem ir, arī maize un vīns priekš manis un priekš tavas kalpones un priekš tā puiša, kas ir pie taviem kalpiem; mums nekādas lietas netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Tad tas vecais vīrs sacīja: esi ar mieru, viss, kas tev trūkst, ir pie manis, tikai nepaliec par nakti uz ielas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Un viņš to veda savā namā un deva priekš tiem ēzeļiem ēdamo. Kad tie nu savas kājas bija mazgājuši, tad tie ēda un dzēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Kad tie nu savu sirdi atspirdzināja, redzi, tad tās pilsētas vīri, bezdievīgi ļaudis, apstāja to namu un klaudzināja pie durvīm. Un tie sacīja uz to veco vīru, tā nama saimnieku: izved to vīru, kas nācis tavā namā, ka mēs to atzīstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Un tas vīrs, tā nama saimnieks, pie tiem izgāja un uz tiem sacīja: ne tā, mani brāļi, nedariet lūdzami tādu grēku; kad nu šis vīrs manā namā nācis, nedariet šo trakumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Redzi, man ir viena meita, jaunava, un viņam lieka sieva, tās es jums gribu izvest, ka jūs tās piesmejat un tām darāt, kas jums patīk, bet pie šā vīra nedarāt tādu trakumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Bet tie vīri to negribēja klausīt; tad tas vīrs sagrāba savu lieko sievu un to izveda pie viņiem ārā, un viņi to atzina un piesmēja cauru nakti līdz rītam un atlaida, kad gaisma metās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Un šī sieva nāca ap rīta laiku un krita pie zemes priekš tā vīra nama durvīm, kur viņas kungs iekšā bija, (un tur gulēja) līdz pat gaismai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Kad nu viņas kungs rītā cēlās un nama durvis atdarīja un izgāja, savu ceļu staigāt, redzi, tad viņa liekā sieva gulēja priekš nama durvīm un viņas rokas uz sliekšņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Un viņš uz to sacīja: celies, ejam projām, bet tā neatbildēja. Tad tas vīrs to ņēma uz savu ēzeli un cēlās un gāja uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Kad nu viņš savā namā nāca, tad viņš ņēma nazi un sagrāba savu lieko sievu un to sakapāja ar viņas kauliem divpadsmit daļās un to sūtīja uz visām Israēla robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Un ikviens, kas to redzēja, tas sacīja: tāda lieta, kā šī, nav notikusi nedz redzēta, kamēr Israēla bērni no Ēģiptes zemes izgājuši līdz šai dienai. Tad nu jūs ņemiet to vērā, dodiet padomu un runājiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Tad visi Israēla bērni izgāja un tā draudze sapulcējās kā viens vienīgs vīrs, no Dana līdz Bēršebai, arī Gileādas zeme, pie Tā Kunga Micpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Un visu ļaužu virsnieki, visas Israēla ciltis, rādījās(sanāca kopā) Dieva ļaužu draudzē, četrsimt tūkstoš kājnieki, zobenu vilcēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Un Benjamina bērni dzirdēja, ka Israēla bērni bija gājuši uz Micpu. Un Israēla bērni sacīja: sakāt, kā šis grēks noticis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Tad tas vīrs, tas Levits, tās nokautās sievas vīrs, atbildēja un sacīja: es ar savu sievu nācu uz Ģibeju, kas Benjaminam pieder, par nakti tur palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Tad Ģibejas namnieki pret mani cēlās un naktī mani apstāja namā; tie nodomāja mani nokaut, un manu lieko sievu tie pārvarējuši, tā ka tā mirusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Tad es ņēmu savu lieko sievu un to dalīju un to sūtīju visās Israēla zemes tiesās, jo tie nešķīstību un negantību ir darījuši iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Redzi, jūs visi esat Israēla bērni, sarunājaties un dodiet padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Tad visi ļaudis cēlās kā viens vienīgs vīrs un sacīja: mēs neiesim neviens uz savu dzīvokli un negriezīsimies neviens uz savu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Bet šī nu ir tā lieta, ko mēs darīsim pie Ģibejas: pret viņu kā mesli krīt!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Mēs ņemsim desmit vīrus no simta no visām Israēla ciltīm un simtu no tūkstošiem un tūkstoti no desmit tūkstošiem, ceļamaizi dabūt priekš tiem ļaudīm; tad iesim uz Benjamina Ģibeju, darīt (viņai) pēc visas negantības, ko tā iekš Israēla padarījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Tad visi Israēla vīri sapulcējās pret to pilsētu un sabiedrojās kā viens vienīgs vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Un Israēla ciltis sūtīja vīrus pie visiem Benjamina radiem sacīdami: kas tas par grēku, kas jūsu starpā noticis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Tad nu izdodiet tos vīrus, tos bezdievīgos, kas Ģibejā, ka mēs tos nokaujam un to ļaunumu no Israēla nogriežam. Bet Benjamina (bērni) negribēja klausīt savu brāļu, Israēla bērnu, balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Un Benjamina bērni sapulcējās no tām pilsētām uz Ģibeju, karā iziet pret Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Un Benjamina bērni tapa skaitīti tai dienā no tām pilsētām divdesmit seši tūkstoš vīri, zobenu vilcēji, bez tiem, kas Ģibejā dzīvoja, to bija pēc skaita septiņsimt izlasīti vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Starp visiem šiem ļaudīm bija septiņsimt izlasīti vīri, tie bija kreiļi; šie visi meta akmeni ar lingu uz mata, ka tas garām neaizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Un Israēla vīri tapa skaitīti bez Benjamina četrsimt tūkstoš vīri, zobenu vilcēji; visi šie bija kara vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Un Israēla bērni cēlās un nogāja uz Bēteli, un vaicāja Dievu un sacīja: kuram no mums būs priekšā iet, karot pret Benjamina bērniem? Un Tas Kungs sacīja: Jūda lai iet priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Tad Israēla bērni cēlās no rīta un apmeta lēģeri pret Ģibeju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Un Israēla vīri izgāja karā pret Benjaminu, un taisījās pret Ģibeju karot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Tad Benjamina bērni izgāja no Ģibejas, un viņi tai dienā no Israēla apkāva divdesmit un divus tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Bet tie ļaudis, Israēla vīri, stiprinājās un taisījās atkal karot tai vietā, kur tie pirmā dienā bija taisījušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Un Israēla bērni nogāja un raudāja priekš Tā Kunga līdz vakaram un vaicāja To Kungu un sacīja: vai man atkal būs iet karā pret Benjamina, sava brāļa, bērniem? Tad Tas Kungs sacīja: ejat pret tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Tā Israēla bērni gāja pret Benjamina bērniem otrā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Bet Benjamins tiem gāja pretī no Ģibejas otrā dienā un apkāva no Israēla bērniem vēl astoņpadsmit tūkstošus, kas visi bija zobenu vilcēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Tad visi Israēla bērni un visi ļaudis nogāja un nāca uz Bēteli un raudāja, un palika tur priekš Tā Kunga un gavēja tai dienā līdz vakaram, un upurēja dedzināmos upurus un pateicības upurus Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Un Israēla bērni vaicāja To Kungu, (jo tur tanīs dienās bija Dieva derības šķirsts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Un Pinehas, Ārona dēla, Eleazara, dēls stāvēja tanīs dienās priekš viņa) un sacīja: vai man vēl būs iet karā pret Benjamina, sava brāļa, bērniem, jeb vai man būs atstāties? Un Tas Kungs sacīja: ceļaties, jo rīt Es tos došu tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Tad Israēls lika kādiem apslēpties visapkārt pret Ģibeju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Un Israēla bērni nogāja trešā dienā pret Benjamina bērniem un taisījās pret Ģibeju, kā citām reizēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Tad Benjamina bērni tiem ļaudīm izgāja pretī un nogāja no tās pilsētas nost un sāka kaut un durt tos ļaudis tā kā jau divreiz\' uz tiem ceļiem, kur viens tek uz Bēteli un otrs uz Ģibeju laukā, kādus trīsdesmit vīrus no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Tad Benjamina bērni sacīja: tie mūsu priekšā ir sakauti tā kā papriekš, bet Israēla bērni sacīja: bēgsim un nošķirsim tos no pilsētas uz tiem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Tad visi Israēla vīri cēlās no savas vietas un nostājās BaālTamārā, tā līdz arī tie Israēlieši, kas bija paslēpušies, cēlās no savas vietas, no Ģibejas klajuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Un desmit tūkstoš vīri, izlasīti no visa Israēla, nāca no Ģibejas puses, un kaušanās bija briesmīga. Bet tie nezināja, ka nelaime tiem jau bija tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Tā Tas Kungs Benjaminu kāva Israēla priekšā, jo Israēla bērni tai dienā no Benjamina apkāva divdesmit piecus tūkstošus un simts vīrus, kas visi bija zobenu vilcēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Proti Benjamina bērni redzēja, ka viņi tapa kauti; un Israēla bērni Benjaminiešiem atstāja to vietu, jo viņi paļāvās uz tiem, kam bija likuši paslēpties pret Ģibeju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Un tie, kas bija paslēpušies, steidzās un izskrēja pret Ģibeju; tie, kas bija paslēpušies nāca un apkāva visu pilsētu ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Un Israēla vīriem bija noruna ar tiem, kas bija paslēpušies, ka tiem bija uzkurt lielus dūmus un tos laist gaisā no pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Un Israēla vīri kaujā griezās atpakaļ, un Benjamins bija iesācis nokaut no Israēliešiem kādus trīsdesmit vīrus, tā ka viņi sacīja: tie ir pavisam kauti mūsu priekšā tā kā pirmā kaušanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Tad dūmi no pilsētas sāka celties, kā dūmu stabs, un kad Benjamins skatījās atpakaļ, redzi, tad visa pilsēta liesmās cēlās pret debesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Un Israēla vīri griezās atpakaļ, bet Benjamina vīri iztrūcinājās, jo tie redzēja, ka nelaime tiem bija uzkritusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Un tie atgriezās Israēla vīru priekšā uz tuksneša ceļu, bet tā kaušanās tiem bija uz pēdām pakaļ, un tie no tām pilsētām tos apkāva savā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Un tie apstāja Benjaminu, dzinās tam pakaļ līdz Menukai, un tos samina līdz Ģibejai pret saules uzlēkšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Un no Benjamina krita astoņpadsmit tūkstoš vīri, šie visi bija stipri vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Un viņi griezās un bēga uz tuksnesi, uz Rimona klinti; un tie viņiem pa tiem ceļiem pakaļ dzīdamies apkāva vēl piectūkstoš vīrus un tiem dzinās pakaļ līdz Ģidomam un no tiem nokāva vēl divtūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Un visi, kas no Benjamina tai dienā krita, bija divdesmit un piectūkstoš vīri, kas bija zobenu vilcēji un visi stipri vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Bet sešsimt vīri griezās un bēga tuksnesī uz Rimona klinti, un palika pie Rimona klints četrus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Un Israēla bērni griezās atpakaļ pie Benjamina bērniem, un kāva tos ar zobena asmeni pilsētā, gan vīrus gan lopus un visu, kas tapa atrasts; tie arī visas pilsētas, ko atrada, sadedzināja ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Bet Israēla vīri Micpā bija zvērējuši sacīdami: neviens no mums lai nedod Benjaminiešiem savu meitu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Tad tie ļaudis nāca uz Bēteli un tur palika līdz vakaram Dieva priekšā un pacēla savas balsis un raudāja gauži raudādami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Un tie sacīja: ak Kungs, Tu Israēla Dievs! Kāpēc tas ir noticis iekš Israēla, ka šodien Israēls par vienu cilti ir mazāks kļuvis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Otrā dienā tie ļaudis cēlās agri un tur uztaisīja altāri, un upurēja dedzināmos upurus un pateicības upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Un Israēla bērni sacīja: kurš tas ir, kas no visām Israēla ciltīm nav atnācis tai draudzes sapulcē pie Tā Kunga? Jo par to, kas nebūtu atnācis pie Tā Kunga uz Micpu, bija ar lielu zvērestu noteikts, ka tam bija tapt nokautam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Un Israēla bērniem bija žēl par Benjaminu, savu brāli, un tie sacīja: šodien viena cilts no Israēla ir izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Ko mēs tiem darīsim, ka tie atlikušie dabū sievas? Jo mēs pie Tā Kunga esam zvērējuši, ka tiem no savām meitām nevienu negribam dot par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Un tie sacīja: vai kāds nav no Israēla ciltīm, kas nav atnācis pie Tā Kunga uz Micpu? Un redzi, no Jabesas Gileādā neviens nebija lēģerī nācis draudzes sapulcē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Jo tie ļaudis tapa skaitīti un redzi, tur nebija neviena no tiem, kas Jabesā Gileādā dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Tad tā draudze uz turieni sūtīja divpadsmit tūkstoš vīrus no tiem stiprākiem un tiem pavēlēja un sacīja: ejat un kaujiet tos, kas Jabesā Gileādā dzīvo ar zobena asmeni līdz ar sievām un bērniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Bet šī ir tā lieta, ko jums būs darīt: visus no vīriešu kārtas un visas sievas, kas pie vīra gulējušas, jums būs izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Un tie atrada starp tiem iedzīvotājiem Jabesā Gileādā četrsimt meitas, jaunavas, kas vīru nebija atzinušas, nedz pie vīriem gulējušas, un tās veda uz lēģeri Šīlo, kas ir Kanaāna zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Tad visa draudze nosūtīja un runāja uz Benjamina bērniem, kas bija pie Rimona klints, un tiem lika mieru pasludināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Tā tanī laikā Benjaminieši griezās atpakaļ; un tie viņiem deva tās sievas, ko tie bija dzīvas pametuši no Jabesas sievām Gileādā, bet tur viņiem nepietika,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Tad tiem ļaudīm bija žēl par Benjaminu, ka Tas Kungs plaisu bija darījis Israēla ciltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Un tie draudzes vecaji sacīja: ko mēs darīsim, ka tie atlikušie sievas dabū? Jo tās sievas no Benjamina ir izdeldētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Tad tie sacīja: Benjaminiešu zemes daļu pienākas iemantot tiem, kas izglābušies, lai neviena Israēla cilts netop izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Bet mēs tiem no savām meitām sievas nevaram dot, jo Israēla bērni ir apzvērējušies sacīdami: nolādēts lai ir, kas Benjaminiešiem dod sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Un tie sacīja: redzi, Šīlo ir Tā Kunga svētki ik gadus, Bētelei pret ziemeļa pusi, pret rītiem tam ceļam, kur iet no Bēteles uz Šehemi un pret dienas vidu Libonai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Un tie pavēlēja Benjamina bērniem un sacīja: ejat un paslēpjaties vīna kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Un skatāties, un redzi, kad Šīlo meitas diedamas ar stabulēm iznāks, tad izejiet jūs no tiem vīna kalniem un sagrābiet ikviens sev sievu no Šīlo meitām un noejat uz Benjamina zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Un kad viņu tēvi vai viņu brāļi nāks mūsu priekšā tiesāties, tad mēs uz tiem sacīsim: atvēliet mums tās, jo mēs ikvienam sievu ar karošanu neesam dabūjuši; jo jūs viņiem tās neesat devuši; tad jums tagad būtu vaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Un Benjamina bērni darīja tā un ņēma sievas pēc sava skaita no tām, kas tur dejoja; tās tie laupīja. Un nogāja un griezās atpakaļ uz savām mājām, un uztaisīja pilsētas un dzīvoja iekš tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Un Israēla bērni tanī laikā no turienes cēlās ikviens pie savas cilts un pie saviem radiem, un izgāja no turienes ikviens uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Tanīs dienās ķēniņa nebija iekš Israēla; ikviens darīja, kā tam patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Tanīs dienās, kad soģi valdīja, bija bads zemē. Un viens vīrs no Jūda Bētlemes nogāja piemist Moaba klajumos ar savu sievu un saviem diviem dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Un tā vīra vārds bija Elimeleks un viņa sievas vārds Naēmja un viņa abu dēlu vārdi Mālons un Ķiljons, Efratieši no Jūda Bētlemes, un tie nāca Moaba klajumos un tur palika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Un Elimeleks, Naēmjas vīrs, nomira, un viņa palika viena ar saviem diviem dēliem; tie sev ņēma Moabiešu sievas, - tās pirmās vārds bija Arpa un tās otras vārds Rute.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Un tie tur palika kādus desmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Tad arī šie abi, Mālons un Ķiljons, nomira, un tā sieva palika viena pēc saviem diviem dēliem un pēc sava vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Un viņa cēlās ar savām vedeklām un griezās atpakaļ no Moaba klajumiem; jo tā bija dzirdējusi Moaba zemē, ka Tas Kungs savus ļaudis piemeklējis un viņiem maizi devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Tāpēc viņa aizgāja no tās vietas, kur tā bija bijusi, un viņas abas vedeklas ar viņu. Un kad viņa pa ceļu gāja, pāriet uz Jūda zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Tad Naēmja sacīja uz savām abām vedeklām: ejat, griežaties atpakaļ ikviena uz savas mātes namu; lai Tas Kungs žēlastību pie jums dara, itin kā jūs esat darījuši pie tiem aizgājušiem un pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Lai Tas Kungs jums dod, ka jūs dusu atrodat, ikviena sava vīra namā. Un viņa tās skūpstīja. Tad tās pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Un tās sacīja uz viņu: mēs gribam tev līdz iet pie taviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Bet Naēmja sacīja: griežaties atpakaļ manas meitas, kāpēc jums man iet līdz? Vai tad man vēl dēli varētu būt manā klēpī, kas jums varētu būt par vīriem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Griežaties atpakaļ, manas meitas, ejat, jo es esmu par vecu, iet pie vīra. Kad es tā sacītu, man vēl ir cerība, un ja man šinī naktī vīrs gadītos, un es dēlus dzemdētu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Vai tad jūs gaidītu, kamēr tie uzaugtu? Vai tad jūs ieslēgtos un pie vīra neietu? - Ne tā, manas meitas, man iet daudz grūtāki nekā jums, jo Tā Kunga roka pret mani izstiepusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Tad tās pacēla savu balsi un raudāja atkal, un Arpa skūpstīja savu vīramāti, bet Rute palika pie viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Tad tā sacīja: redzi, tava vīra brāļa sieva griezusies atpakaļ pie saviem ļaudīm un pie sava dieva; griezies arī tu sava vīra brāļa sievai pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Bet Rute sacīja: nespied mani, tevi atstāt un no tevis aiziet; jo kurp tu iesi, arī es iešu, un kur tu mitīsi, tur arī es mitīšu; tavi ļaudis ir mani ļaudis, un tavs Dievs ir mans Dievs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Kur tu mirsi, tur es miršu, un tur gribu tapt aprakta; lai Tas Kungs man šā un tā dara, nāve vien mani un tevi šķirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Kad nu viņa redzēja, ka šī bija stipri apņēmusies, viņai iet līdzi, tad viņa mitējās to pārrunāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Un abas gāja, kamēr nāca uz Bētlemi. Un notikās, kad viņas Bētlemē nonāca, tad visa pilsēta par tām sacēlās, un tās (sievas) sacīja: vai šī nav Naēmja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Bet viņa uz tām sacīja: nesauciet mani par Naēmju (jauka), sauciet mani par Māru (rūgta), jo tas Visuvarenais man piesūtījis lielu sirds rūgtumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Pilna es aizgāju, bet tukšai Tas Kungs man licis atpakaļ griezties; kāpēc jūs mani sauksiet Naēmju, kad tomēr Tas Kungs pret mani liecību devis, un tas Visuvarenais mani apbēdinājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Tā Naēmja griezās atpakaļ, un Rute, tā Moabiešu sieva, viņas vedekla, līdz ar viņu griezās atpakaļ no Moaba, un tās nāca uz Bētlemi ap miežu pļaujamo laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Un Naēmjai bija radinieks no viņas vīra, varen turīgs vīrs no Elimeleka rada, un viņa vārds bija Boas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Tad Rute, tā Moabiešu sieva, sacīja uz Naēmju: ļauj man jel tīrumā iet, tad es vārpas aiz tā lasīšu, kura acīs es žēlastību atradīšu. Un tā uz viņu sacīja: ej, mana meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Tad viņa gāja un nāca un lasīja tīrumā aiz pļāvējiem. Un notikās, ka tas tīrums piederēja Boasam, kas bija no Elimeleka rada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Un redzi, Boas nāca no Bētlemes un sacīja uz tiem pļāvējiem: Tas Kungs lai jums palīdz; un tie sacīja uz viņu: Tas Kungs lai tevi svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Tad Boas sacīja uz savu puisi, kas bija celts pār pļāvējiem: kas tā tāda jauna sieviete?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Un tas puisis, kas bija celts pār pļāvējiem, atbildēja un sacīja: šī ir tā jaunā Moabiešu sieva, kas ar Naēmju ir atpakaļ griezusies no Moaba zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Un tā sacīja: ļauj man jel (vārpas) lasīt un krāt kūlīšu starpā pļāvējiem pakaļ; tā viņa nākusi un palikusi agri no rīta līdz šim laikam, un viņa daudz nepaliek mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Tad Boas sacīja uz Ruti: klausies mana meita, neej tu citā tīrumā lasīt, tev arī nebūs no šejienes aiziet, bet šeitan tev būs turēties pie manām kalponēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Tavas acis lai skatās uz to tīrumu, ko tie pļaus, un tu staigā tiem pakaļ; es arī puišiem esmu pavēlējis, ka neviens lai tevi neaiztiek, un kad tev slāpst, tad ej pie traukiem un dzer no tā, ko puiši būs smēluši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Tad viņa metās uz savu vaigu un klanījās pie zemes un uz viņu sacīja: kāpēc es žēlastību esmu atradusi tavās acīs, ka tu mani uzlūko, un es tomēr esmu sveša?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Un Boas atbildēja un uz viņu sacīja: man ir stāstīts viss, ko tu esi darījusi pie savas vīramātes pēc sava vīra miršanas, un ka tu esi atstājusi savu tēvu un savu māti un savu dzimtas zemi un gājusi pie ļaudīm, ko tu papriekš nepazini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Lai Tas Kungs tev atmaksā, ko tu darījusi, un tava alga lai ir pilnīga no Tā Kunga, Israēla Dieva, apakš kura spārniem tu esi nākusi, patvērumu dabūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Un viņa sacīja: lai es žēlastību atrodu tavās acīs, mans kungs, jo tu mani esi iepriecinājis un savu kalponi mīlīgi uzrunājis, jebšu es neesmu kā viena no tavām kalponēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Un Boas uz viņu sacīja: ap ēdamo laiku nāc šurp un ēd no maizes un iemērc savu kumosu skābumā. Tad viņa apsēdās pie tiem pļāvējiem, un viņai pasniedza ceptas vārpas, un tā ēda un paēda un viņai atlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Kad nu viņa cēlās atkal lasīt, tad Boas pavēlēja saviem puišiem un sacīja: lai viņa arī starp kūlīšiem lasa, un nedariet viņai kauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Izvelciet arīdzan priekš viņas no kūlīšiem un lai tur paliek, ka viņa to salasa, un nerājiet viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Tā viņa lasīja pa tīrumu līdz vakaram un izkūla, ko viņa bija salasījusi, un tas bija kāda ēfa miežu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Un viņa to ņēma un nāca pilsētā, un viņas vīramāte redzēja, ko tā bija salasījusi. Tad viņa izvilka un viņai deva, kas viņai ēdot bija atlicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Tad viņas vīramāte uz viņu sacīja: kur tu šodien esi lasījusi un kur tu esi strādājusi? Svētīts lai ir, kas tevi uzlūkojis. Un viņa stāstīja savai vīramātei, pie kā tā bija strādājusi, un sacīja: tā vīra vārds, pie ka es šodien esmu strādājusi, ir Boas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Tad Naēmja sacīja uz savu vedeklu: svētīts lai tas ir no Tā Kunga, kas savu žēlastību nav atrāvis ne no dzīviem, ne no mirušiem. Un Naēmja uz viņu sacīja: tas vīrs mums ir rada, no mūsu tuviniekiem viņš ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Tad Rute, tā Moabiešu sieva, sacīja: viņš arī uz mani sacīja: turies pie maniem ļaudīm, kamēr tie visu manu pļaušanu būs pabeiguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Tad Naēmja sacīja uz savu vedeklu Ruti: tas ir labi, mana meita, ka tu ar viņa kalponēm izej, lai citā tīrumā tev nedara pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Tā viņa turējās pie Boasa kalponēm, lasīdama, kamēr miežu pļaušana un kviešu pļaušana bija pabeigta, un dzīvoja pie savas vīramātes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Un Naēmja, viņas vīramāte, uz viņu sacīja: mana meita, vai es tev lai nemeklēju dusas vietu, kur tev labi klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Nu tad, vai Boas, pie kura kalponēm tu esi turējusies, nav no mūsu tuviem radiem? Redzi, šo nakti viņš vētīs miežus klonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Tad nu mazgājies un svaidies un apvelc savas drēbes un noej uz to klonu, un neparādies tam vīram, kamēr viņš beidzis ēst un dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Un kad viņš apguļas, tad ņem to vietu vērā, kur viņš apgulsies, un pieej un atsedz viņa kājgalu, un apgulies, tad viņš tev sacīs, kas tev būs jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Un viņa uz to sacīja: visu, ko tu man esi sacījusi, to es darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Tā viņa nogāja uz to klonu un darīja, tā kā viņas vīramāte viņai bija pavēlējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Kad nu Boas bija ēdis un dzēris, un viņa sirds bija līksma, tad viņš gāja apgulties aiz gubas. Tad viņa nāca klusiņām un atsedza viņa kājgalu un apgūlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Un nakts vidū tas vīrs izbijās, un palocījās, un redzi, viena sieviete gulēja viņam kājgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Un viņš sacīja: kas tu esi? Un tā sacīja: es esmu Rute, tava kalpone, izplēt savus spārnus pār savu kalponi, jo tu esi tas tuvinieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Un viņš sacīja: esi svētīta no Tā Kunga, mana meita! Šī tava pēdējā mīlība ir labāka, nekā tā pirmā, tāpēc ka tu neesi dzinusies pakaļ jaunekļiem, nedz bagātam, nedz nabagam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Un nu, mana meita, nebīsties! Visu, ko tu esi sacījusi, es tev darīšu; jo visos manu ļaužu vārtos ir zināms, ka tu esi godīga sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Nu tas gan ir tiesa, ka esmu tuvinieks, bet tur ir vēl viens jo tuvāks nekā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Paliec šo nakti, un rītu, ja viņš tevi ņems, labi, lai viņš tevi ņem; bet ja viņam negribās tevi ņemt, tad es tevi apņemšu, tik tiešām kā Tas Kungs dzīvo. Guli līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Tad tā apgūlās viņam kājgalā līdz rītam un uzcēlās, pirms viens otru varēja pazīt, jo viņš sacīja: lai netop zināms, ka sieviete ir klonā nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Un viņš sacīja: dod šurp savu apsegu, kas tev ir klātu, un turi to; un viņa to turēja. Un viņš mēroja sešus mērus miežu un uzlika tos viņai, un gāja pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Tad viņa nāca pie savas vīramātes, un tā sacīja: kā klājās, mana meita? Un tā viņai teica visu, ko tas vīrs viņai bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Viņa arī sacīja: šos sešus (mērus) miežu viņš man devis, jo viņš uz mani sacīja: tev tukšai nebūs nākt pie savas vīramātes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Tad viņa sacīja, paliec klusu, mana meita, kamēr tu zini, kā šī lieta izdosies, jo tas vīrs nedosies mierā, bet šo lietu šodien izvedīs galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Un Boas gāja vārtos un tur apsēdās, un redzi, tas tuvinieks gāja garām, no kā Boas bija runājis. Tad viņš sacīja: nāc, brāl, apsēdies še. Un tas nāca un apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Un viņš ņēma desmit vīrus no pilsētas vecajiem un sacīja: apsēžaties šeitan, un tie apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Tad viņš uz to tuvinieku sacīja: to tīruma gabalu, kas mūsu brālim Elimelekam piederēja, Naēmja, kas no Moaba zemes atnākusi, grib pārdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Un es apņēmos to tev sacīt, proti: pērc viņu to iedzīvotāju un manu ļaužu vecaju priekšā. Ja tu to gribi pirkt, tad pērc, bet ja tu nepirksi, tad saki man, ka es to zinu, jo cita nav, kam nākas to pirkt, bez manis un tevis. Tad tas sacīja: es pirkšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Un Boas sacīja: tai dienā kad tu to tīrumu no Naēmjas pērc, tad tev arī Ruti, to Moabieti, tā nomirušā sievu, būs precēt, un celt tā nomirušā vārdu par viņa zemes daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Tad tas tuvinieks sacīja: es nevaru to priekš sevis pirkt, lai savu paša mantību nemaitāju; pērc tu, kas man nākas pirkt, jo es to nevaru atpirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Nu tas vecos laikos bija tiesa iekš Israēla pie pirkšanas un pie mīšanas, apstiprināt ikkatru līgumu: vīrs novilka savu kurpi un to deva savam tuvākam, un tas bija par liecību iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Tad šis tuvinieks sacīja uz Boasu: pērc tu priekš sevis! Un novilka savu kurpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Un Boas sacīja uz tiem vecajiem un uz visiem ļaudīm: jūs šodien esat liecinieki, ka no Naēmjas rokas visu esmu pircis, kas Elimelekam, un visu, kas Ķiljonam un Mālonam piederēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Un arī Ruti, to Moabieti, Mālona sievu, es sev precēšu par sievu, un celšu tā nomirušā vārdu par viņa zemes daļu, ka tā nomirušā vārds netop izdeldēts no viņa brāļiem un no viņa pilsētas vārtiem, - jūs esat šodien liecinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Tad visi ļaudis, kas bija vārtos, līdz ar tiem vecajiem sacīja: mēs esam liecinieki. Lai Tas Kungs šo sievu, kas nāk tavā namā, dara kā Rahēli un Leū, kas abas Israēla namu vairojušas, un lai tevi stiprina Efratā un tev dara slavu Bētlemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Un tavs nams lai ir, kā Pereca nams, ko Tamāre Jūdam dzemdējusi, no tā dzimuma, ko Tas Kungs tev dos no šīs jaunās sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Tad Boas ņēma Ruti, un tā viņam bija par sievu, un viņš pie tās gāja, un Tas Kungs viņai deva, ka tā tapa grūta un dzemdēja dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Tad tās sievas sacīja uz Naēmju: svētīts lai ir Tas Kungs, kas tev neliek trūkt tuvinieka šodien; un Viņa Vārds lai top slavēts iekš Israēla!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Un tas tev būs par dvēseles atspirdzinātāju un par kopēju vecumā, jo tava vedekla, ko tu mīļo, viņu dzemdējusi, kas tev ir labāka, nekā septiņi dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Un Naēmja ņēma to bērniņu un lika to savā klēpī un bija viņa aukle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Un kaimiņienes viņam deva vārdu sacīdamas: Naēmjai dēls dzimis, un tie nosauca viņa vārdu Obedu, šis ir Isajus Dāvida tēva, tēvs:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Šie nu ir Pereca dzimumi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Perecs dzemdināja Hecronu, un Hecrons dzemdināja Ramu, un Rams dzemdināja Aminadabu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Un Aminadabs dzemdināja Nahšonu, un Nahšons dzemdināja Zalmu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Un Zalmus dzemdināja Boasu, un Boas dzemdināja Obedu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Un Obeds dzemdināja Isaju, un Isajus dzemdināja Dāvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Un viens vīrs bija no Ramatajim-Cofim, no Efraīma kalniem, Elkanus vārdā, Jeroama dēls, tas bija Elihus dēls, tas Tous dēls, tas Cuva dēls, no Efraīma cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Šim bija divas sievas, vienai bija vārds Anna, un otras vārds bija Pennina, un Peninnai bija bērni, bet Annai bērnu nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Un šis vīrs nogāja ik gadus no savas pilsētas, Dievu pielūgt un upurēt Tam Kungam Cebaot Šīlo. Un tur bija tie divi Elus dēli, Hofnus un Pinehas, Tam Kungam par priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Un tai dienā, kad Elkanus upurēja, viņš savai sievai Peninnai un visiem viņas dēliem un meitām deva daļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Bet Annai viņš deva divkārtīgu daļu, jo viņš to Annu mīlēja, bet Tas Kungs viņas miesas bija aizslēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Un viņas pretiniece viņu daudz apbēdināja un skumdināja kaitinādama, tādēļ ka Tas Kungs viņas miesas bija aizslēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Un tā viņš darīja ik gadus, kad viņa nogāja Tā Kunga namā. Un šī viņu skumdināja, ka viņa raudāja un neēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Tad Elkanus, viņas vīrs, uz viņu sacīja: Anna, kāpēc tu raudi? Un kāpēc tu neēdi? Un kāpēc tava sirds noskumusi? Vai es tev neesmu labāks nekā desmit dēli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Tad Anna cēlās, kad bija ēdusi un dzērusi Šīlo. Un Elus, tas priesteris, sēdēja uz krēsla pie stenderes Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Un viņas sirds dziļumā bija noskumusi un pielūdza To Kungu un raudāja gauži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Un viņa solīja solījumu un sacīja: Kungs Cebaot, ja Tu Savas kalpones bēdas uzlūkosi un mani pieminēsi un Savu kalponi neaizmirsīsi un dosi Savai kalponei dēlu, tad es to Tam Kungam došu visu viņa mūžu, un dzenamam nazim nebūs nākt uz viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Un kad viņa ilgi lūdza Tā Kunga priekšā, tad Elus viņas mutes (kustēšanu) lika vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Jo Anna runāja savā sirdī un viņas lūpas tikai kustējās, bet viņas balss netapa dzirdēta, tāpēc Elum šķita, viņu esam piedzērušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Un Elus uz to sacīja: cik ilgi tu būsi piedzērusi? Lai tavs vīns no tevis atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Bet Anna atbildēja un sacīja: nē, mans kungs, es esmu sieva ar bēdīgu sirdi, es neesmu ne vīna nedz stipra dzēriena dzērusi, bet savu sirdi esmu izgāzusi priekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Neturi savu kalponi par tādu negodīgu sievu, jo es līdz šim esmu runājusi aiz lielām sirds nopūtām un bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Tad Elus atbildēja un sacīja: ej ar mieru, lai Israēla Dievs tev dod tavu lūgumu, ko tu no Viņa lūgusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Un viņa sacīja: lai tava kalpone žēlastību atrod tavās acīs. Tad tā sieva nogāja savu ceļu un ēda un viņas vaigs vairs neraudzījās tik noskumis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Un tie cēlās rītā agri un pielūdza Tā Kunga priekšā un griezās atpakaļ un nāca savā namā Rāmatā. Un Elkanus atzina Annu, savu sievu, un Tas Kungs viņu pieminēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Un pēc kāda laika Anna tapa grūta un dzemdēja dēlu un nosauca viņa vārdu Samuēli, jo (viņa sacīja) es no Tā Kunga to esmu izlūgusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Kad nu tas vīrs, Elkanus, ar visu savu namu aizgāja, Tam Kungam upurēt to gadskārtējo upuri un savu solījumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Tad Anna negāja līdz, bet sacīja uz savu vīru: kad tas puisītis būs atšķirts, tad es viņu vedīšu, lai viņš rādās Tā Kunga priekšā un tur paliek mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Un Elkanus, viņas vīrs, uz to sacīja: dari, kā tev patīk, paliec šeitan, tiekams tu viņu būsi atšķīrusi; bet Tas Kungs lai piepilda Savu vārdu. Tā tā sieva palika un zīdīja savu dēlu, tiekams viņa to atšķīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Un kad viņa to bija atšķīrusi, tad viņa to veda sev līdz ar trim vēršiem un vienu ēfu miltu un vienu trauciņu ar vīnu, un noveda Tā Kunga namā uz Šīlo; un tas zēns bija vēl jauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Un tie nokāva vērsi un pieveda to zēnu pie Elus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Un tā sacīja: mans kungs, tik tiešām kā tava dvēsele dzīvo, mans kungs, es esmu tā sieva, kas šeitan pie tevis stāvēja, To Kungu lūgdama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Es par šo bērnu esmu lūgusi, un Tas Kungs man devis manu lūgumu, ko es no Viņa esmu lūgusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Tādēļ es to arī Tam Kungam kā izlūgtu esmu nodevusi visu mūžu, kamēr tas dzīvos, - viņš ir no Tā Kunga izlūgts. Un tie tur pielūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Tad Anna pielūdza un sacīja: “Mana sirds lec no prieka iekš Tā Kunga, mans rags ir paaugstināts iekš Tā Kunga; mana mute ir atvērta pret maniem ienaidniekiem, jo es priecājos par Tavu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Neviens nav svēts, kā Tas Kungs, neviens, kā Tu vien, un nekāds patvērums nav, kā mūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Nedaudzinājiet runu augsti jo augsti, blēņas lai paliek nost no jūsu mutes; jo Tas Kungs ir Dievs, tas visu zinātājs, Viņš sver tos darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Vareniem stops ir salauzts, un vājie ir apjozti ar stiprumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Paēdušie sader par maizi, un izsalkušie vairs nav izsalkuši. Pati neauglīgā dzemdē septiņus, kam bija daudz bērnu, tā savīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Tas Kungs nokauj un dara dzīvu, Viņš noved ellē un atkal uzved augšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Tas Kungs dara nabagu un dara bagātu, Viņš pazemo un paaugstina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Viņš uzceļ nabagu no pīšļiem, un bēdīgo Viņš paaugstina no dubļiem, ka Viņš tos sēdina starp lieliem kungiem un tiem liek iemantot goda krēslu; jo zemes pamati pieder Tam Kungam, un Viņš uz tiem pasauli licis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Savu svēto kājas Viņš pasargā; bet tie bezdievīgie tumsībā iet bojā: jo neviens nav varens caur (savu) spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Tas Kungs - Viņa pretinieki top iztrūcināti, debesīs pār tiem Viņš liek pērkoniem rūkt. Tas Kungs tiesās zemes galus un dos Savam ķēniņam spēku un paaugstinās Sava svaidītā ragu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Un Elkanus nogāja uz Rāmatu savā namā, bet tas zēns kalpoja Tam Kungam priestera Elus priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Bet Elus dēli bija netikli, tie neatzina To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Un priesteru ieradums ar ļaudīm bija: kad kāds upuri upurēja, tad priestera puisis nāca, kamēr tā gaļa vārījās, - un tam dakšas ar trim zariem bija rokā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Un bakstīja grāpī vai katlā vai pannā vai podā. Ko nu tās dakšas uzvilka, to priesteris ņēma priekš sevis. Tā tie darīja visiem Israēla ļaudīm, kas tur nāca uz Šīlo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Un pirms tie tos taukus iededzināja, priestera puisis nāca un sacīja uz to vīru, kas upurēja: dod gaļas priesterim priekš cepeša, jo viņš no tevis negrib vārītu gaļu, bet jēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Ja kas uz to sacīja: pašu laiku(vispirms) tos taukus iededzinās, tad ņem priekš sevis, kā tava sirds kāro, - tad šis uz to sacīja: nupat tev būs dot, un ja ne, tad es ņemšu ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Tā šo puišu grēki bija ļoti lieli Tā Kunga priekšā, jo šie vīri nicināja Tā Kunga ēdamo upuri. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Bet Samuēls kalpoja Tā Kunga priekšā, puisis būdams, apjozts ar nātnu efodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Un māte viņam taisīja mazus svārciņus un tos viņam nesa ik gadus, kad ar savu vīru nāca, gadskārtējo upuri upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Un Elus svētīja Elkanu un viņa sievu un sacīja: lai Tas Kungs tev dod dzimumu no šās sievas, par to izlūgto, ko viņa no Tā Kunga ir izlūgusi. Un tie gāja uz savu māju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Un Tas Kungs piemeklēja Annu un tā tapa grūta un dzemdēja trīs dēlus un divas meitas. Bet tas puisītis Samuēls uzauga pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Un Elus bija ļoti vecs un dzirdēja visu, ko viņa dēli visam Israēlim darīja, un ka tie gulēja pie tām sievām, kas sapulcējās priekš saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Un viņš uz tiem sacīja: kāpēc jūs darāt tādas lietas? Kā es par jums tādu neslavu dzirdu no visiem šiem ļaudīm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nē, mani bērni, tā nav laba slava, ko es dzirdu, jo jūs darāt Tā Kunga ļaudis pārkāpjam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Kad cilvēks pret cilvēku grēko, tad tiesas kungi to izlīdzina, bet kad cilvēks pret To Kungu grēko, kas priekš tāda var aizlūgt? Bet tie neklausīja sava tēva balsi, jo Tas Kungs tos gribēja nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Un tas puisis Samuēls augdams auga un patika gan Tam Kungam, gan tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Un viens Dieva vīrs nāca pie Elus un uz to sacīja: tā saka Tas Kungs: vai Es neesmu skaidri parādījies tava tēva namam, kad tie bija Ēģiptes zemē Faraona namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Un to no visām Israēla ciltīm Sev esmu licis par priesteri, upurēt uz Mana altāra, kvēpināmās zāles iededzināt un to plecu apsegu nest Manā priekšā, un Es tava tēva namam esmu devis visus Israēla bērnu uguns upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Kāpēc tad jūs kājām minat Manu upuri un Manu ēdamo upuri, ko Es esmu pavēlējis (nest Manā) dzīvoklī? Un tu godā savus dēlus vairāk nekā Mani, ka jūs barojaties no visu Manu Israēla ļaužu upuru pirmajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Tādēļ Tas Kungs, Israēla Dievs, saka: gan Es biju skaidri sacījis: tavam namam un tava tēva namam bija Manā priekšā staigāt mūžīgi. Bet nu Tas Kungs saka: nemūžam nē, bet kas Mani godā, tos Es godāju, un kas Mani nicina, tie paliek kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Redzi, nāk dienas, tad Es nocirtīšu tavu elkoni un tava tēva nama elkoni, tā ka neviena veca vairs nebūs tavā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Un tu redzēsi (Dieva) dzīvokļa bēdas pie visa, ko Viņš Israēlim labu darīs, un veca nebūs tavā namā nemūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Tomēr visus Es tev neizdeldēšu no Mana altāra, ka tavām acīm būs īgt un tavai dvēselei iztvīkt, bet viss tava nama dzimums mirs vīra gados.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Šī nu būs tā zīme, kas nāks pār taviem abiem dēliem, par Hofnu un Pinehasu: vienā dienā abi mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Un Es Sev celšu uzticīgu priesteri; tas darīs pēc Manas sirds un dvēseles, tam Es uztaisīšu pastāvīgu namu, un tas staigās priekš Mana svaidītā vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Un kas vēl atliks no tava nama, nāks un klanīsies priekš viņa par naudas artavu un par maizes riecienu un sacīs: pieņem mani lūdzams kādā priestera amatā, ka dabūju maizes kumosu, ko ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Un tas jauneklis Samuēls kalpoja Tam Kungam Elus priekšā, un Tā Kunga vārds bija dārgs tanī laikā, un parādīšanas notika reti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Un notikās tai laikā, kad Elus savā vietā gulēja, (un viņa acis jau sāka tumšas mesties, ka tas nevarēja redzēt),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Un tas Dieva lukturis vēl nebija izdzisis, un Samuēls gulēja Tā Kunga namā, kur Dieva šķirsts bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Tad Tas Kungs Samuēli sauca, un šis sacīja: redzi, še es esmu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Un skrēja pie Elus un sacīja: redzi, še es esmu, jo tu mani esi saucis. Un viņš sacīja: es tevi neesmu saucis, ej atkal gulēt. Un tas gāja un apgūlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Tad Tas Kungs Samuēli atkal sauca. Un Samuēls cēlās un gāja pie Elus un sacīja: redzi, še es esmu, jo tu mani esi saucis. Viņš sacīja: es tevi neesmu saucis, mans dēls, ej atkal gulēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Bet Samuēls vēl nepazina To Kungu un Tā Kunga vārds tam vēl nebija parādīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Tad Tas Kungs Samuēli atkal sauca trešu lāgu. Un tas cēlās un gāja pie Elus un sacīja: redzi, še es esmu, tu mani esi saucis. Tad Elus noprata, ka Tas Kungs to jaunekli sauca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Un Elus sacīja uz Samuēli: ej gulēt, un kad tevi sauks, tad saki: runā Kungs, jo Tavs kalps klausās. Un Samuēls gāja un apgūlās savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Tad Tas Kungs nāca un nostājās un sauca kā papriekš: Samuēl, Samuēl! Un Samuēls sacīja: runā, jo Tavs kalps klausās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Un Tas Kungs sacīja uz Samuēli: redzi, Es ko darīšu iekš Israēla, ka visiem, kas to dzirdēs, abās ausīs skanēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Tanī dienā Es pret Elu visu izdarīšu, ko pret viņa namu esmu runājis: Es to sākšu un arī pabeigšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Jo Es tam esmu ziņu devis, ka Es soģis būšu pār viņa namu mūžīgi tā nozieguma dēļ, ka viņš zinājis, kā viņa bērni sev lāstus krājās, un tiem to nav liedzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Un tādēļ Es Elus namam esmu zvērējis, ka Elus nama noziegums nemūžam netaps salīdzināts ne caur kaujamiem, ne caur ēdamiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Un Samuēls gulēja līdz rītam, un tad viņš atvēra Tā Kunga nama durvis, bet Samuēls bijās šo parādīšanu Elum stāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Tad Elus Samuēli aicināja un sacīja: Samuēl, mans dēls. Un tas atbildēja: redzi, še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Un viņš sacīja: kas tas par vārdu, ko Viņš uz tevi runājis? Neslēp jel to man; lai Dievs tev šā un tā dara, ja tu man vienu vārdu apslēpsi no visiem, ko Viņš uz tevi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Tad Samuēls tam stāstīja visus tos vārdus un tam nekā neapslēpa. Un tas sacīja: Viņš ir Tas Kungs, lai Viņš dara, ko Viņš pats redz labu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Un Samuēls uzauga, un Tas Kungs bija ar viņu, un Viņš nevienam no Saviem vārdiem nelika zemē krist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Un viss Israēls no Dana līdz Bēršebai atzina, ka Samuēls bija Tā Kunga uzticīgais pravietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Un Tas Kungs vēl parādījās Šīlo, jo Tas Kungs parādījās Samuēlim Šīlo caur Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Un Samuēls sludināja visam Israēlim Dieva vārdu. Un Israēls izgāja uz karu pret Fīlistiem un apmetās pie EbenEcera. Un Fīlisti apmetās pie Afekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Un Fīlisti taisījās Israēlim pretī, un tā kaušanās vairojās un izplētās, un Israēls no Fīlistiem tapa sakauts, un tie tai kaušanā uz lauka nokāva līdz četrtūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Un tie ļaudis nāca lēģerī, un Israēla vecaji sacīja: kāpēc Tas Kungs mūs šodien kāvis Fīlistu priekšā? Ņemsim pie sevis Tā Kunga derības šķirstu no Šīlo, ka Viņš nāk mūsu vidū un mūs izglābj no mūsu ienaidnieku rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Tad tie ļaudis sūtīja uz Šīlo un atveda no turienes Tā Kunga Cebaot derības šķirstu, (Tā Kunga), kas sēž pār ķerubiem, un abi Elus dēli, Hofnus un Pinehas, bija līdz, klāt pie Dieva derības šķirsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Kad nu Tā Kunga derības šķirsts nāca lēģerī, tad viss Israēls gavilēja ar lielu gavilēšanu, tā ka zeme drebēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Un kad Fīlisti to gavilēšanu dzirdēja, tad tie sacīja: kas tā par lielu gavilēšanas skaņu Ebreju lēģeri? Tad tie manīja, Tā Kunga šķirstu esam nākušu lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Un Fīlisti bijās un sacīja: Dievs nācis lēģerī. Un tie sacīja: Ak vai, mums! Jo līdz šim tā nav noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Ak vai, mums! Kas mūs izpestīs no šo vareno dievu rokas? Šie ir tie dievi, kas ēģiptiešus situši ar visādām mocībām tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Esiet stipri un turaties kā vīri, jūs Fīlisti, ka jums Ebrejiem nav jākalpo, tā kā tie jums kalpojuši, Turaties kā vīri un kaujaties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Tad Fīlisti kāvās un Israēls tapa sakauts un bēga ikviens uz savu dzīvokli. Un tur notika varen liela kaušana, jo no Israēla krita trīsdesmit tūkstoš kājnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Un Dieva šķirsts tika paņemts un Elus abi dēli, Hofnus un Pinehas, nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Tad viens Benjaminietis skrēja no tā karapulka un nāca tai dienā uz Šīlo ar saplēstām drēbēm un ar zemi uz galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Un tam nākot, redzi, Elus sēdēja uz krēsla ceļmalā skatīdamies, jo viņa sirds trīcēja Dieva šķirsta dēļ. Kad nu tas vīrs nonāca un pilsētā to stāstīja, tad visa pilsēta brēca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Un kad Elus to brēkšanu dzirdēja, tad viņš sacīja: kas tas par troksni? Tad tas vīrs steidzās un nāca un to izteica Elum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, '(Elus nu bija deviņdesmit un astoņus gadus vecs, un viņa acis jau bija tumšas metušās un nevarēja vairs redzēt.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Un tas vīrs sacīja uz Elu: es esmu nācis no karapulka un šodien bēdzis no karapulka. Tad viņš sacīja: kā tur iet, mans dēls?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Un tas vēstnesis atbildēja un sacīja: Israēls ir bēdzis Fīlistu priekšā un liela kaušana tiem ļaudīm notikusi, arī tavi abi dēli, Hofnus un Pinehas, miruši. Un Dieva šķirsts ir paņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Un notikās, kad šis Dieva šķirstu pieminēja, tad viņš krita no krēsla atpakaļ pie vārtiem un lauza savu kaklu un nomira, jo tas vīrs bija vecs un smags; un viņš Israēli bija tiesājis četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Un viņa vedekla, Pinehasa sieva, bija grūta un gaidās. Kad nu šī to vēsti dzirdēja, ka Dieva šķirsts bija paņemts un viņas tēvocis nomiris līdz ar viņas vīru, tad viņa locījās un dzemdēja, jo sāpes viņai uzbruka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Un viņai mirstot tās (sievas), kas viņai klāt stāvēja, sacīja: nebīsties, jo tu dēlu esi dzemdējusi. Bet viņa neatbildēja un to neņēma pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Un tā to puisēnu nosauca Ihabodu, sacīdama: godība ir nost no Israēla, - tādēļ ka Dieva šķirsts bija atņemts, un sava tēvoča un vīra dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Un tā sacīja: godība ir nost no Israēla, jo Dieva šķirsts ir atņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Un Fīlisti paņēma Dieva šķirstu un to noveda no Eben-Ecera uz Ašdodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Un Fīlisti paņēma Dieva šķirstu un to noveda Dagona namā un nolika Dagonam blakām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Bet kad Ašdodas ļaudis otrā rītā agri cēlās, redzi, tad Dagons uz savu vaigu bija zemē nokritis Tā Kunga šķirsta priekšā, un tie ņēma Dagonu un to atkal uzcēla savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Kad tie nu otrā rītā atkal agri cēlās, redzi, tad Dagons uz savu vaigu bija zemē nokritis Tā Kunga šķirsta priekšā, un Dagona galva un viņa abas rokas bija nolūzušas un gulēja uz sliekšņa, ka tas zivju tēls vien pie tā atlikās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Tādēļ Dagona priesteri un visi, kas iet Dagona namā, nemin uz Dagona slieksni Ašdodā līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Un Tā Kunga roka bija grūta pār Ašdodas ļaudīm un Viņš tos postīja un sita ar augoņiem, Ašdodu un viņas robežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Kad nu Ašdodas vīri redzēja, ka tas tā notika, tad tie sacīja: lai Israēla Dieva šķirsts pie mums nepaliek; jo Viņa roka ir grūta pār mums un pār mūsu dievu Dagonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Tāpēc tie sūtīja un sapulcināja visus Fīlistu lielkungus un sacīja: ko darīsim ar Israēla Dieva šķirstu? Tad tie sacīja: lai Israēla Dieva šķirsts top nests uz Gatu. Tā tie aiznesa Israēla Dieva šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Kad tie nu viņu bija aiznesuši, tad Tā Kunga roka pār to pilsētu nāca ar varen lielu iztrūcināšanu, jo Viņš sita tās pilsētas ļaudis, gan mazus gan lielus, un pie tiem izcēlās augoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Tad tie Dieva šķirstu sūtīja uz Ekronu, un notikās, kad Dieva šķirsts uz Ekronu nāca, tad Ekrona brēca un sacīja: tie Israēla Dieva šķirstu pie manis atveduši, mani un manus ļaudis nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Un tie sūtīja un sapulcināja visus Fīlistu lielkungus un sacīja: sūtat Israēla Dieva šķirstu projām, lai tas tiek atpakaļ savā vietā un nenokauj mani un manus ļaudis. Jo nāves bailes bija ikkatrā pilsētā, un Dieva roka tur bija ļoti grūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Un tie ļaudis, kas nenomira, tapa sisti ar augoņiem, tā ka tās pilsētas kliegšana cēlās pret debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Un Tā Kunga šķirsts sabija septiņus mēnešus Fīlistu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Un Fīlisti sasauca priesterus un zīlniekus sacīdami: ko lai darām ar Tā Kunga šķirstu? Sakāt mums, kā lai to sūtam atpakaļ savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Un tie sacīja: ja jūs Israēla Dieva šķirstu gribat sūtīt, tad nesūtat viņu tukšā, bet atmaksājiet Viņam noziegumu upuri; tad jūs tapsiet dziedināti, un jums taps zināms, kādēļ Viņa roka no jums nav atstājusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Tad tie sacīja: kāds ir tas nozieguma upuris, ko mums Viņam būs maksāt? Un tie sacīja: pieci zelta augoņi un piecas zelta peles pēc piecu Fīlistu lielkungu skaita; jo vienāda mocība ir pār jums visiem un pār jūsu lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Tad taisiet nu tādas zīmes tā kā jūsu augoņi ir, un tādu peļu zīmes, kas jūsu zemi samaitā, un dodiet Israēla Dievam godu, varbūt ka Viņš Savu roku atvieglinās pār jums un pār jūsu dievu un pār jūsu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Kāpēc tad jūs savu sirdi gribat apcietināt, kā ēģiptieši un Faraons savu sirdi apcietinājuši? Vai tas tā nav, kad Viņš brīnišķi tiem bija parādījies, tad tie atlaiduši (Israēla ļaudis), ka tie aizgāja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Nu tad ņemiet un taisiet jaunus ratus un ņemiet divas zīžamas govis, uz kurām vēl nekāds jūgs nav bijis, un iejūdziet tās govis ratos un vediet viņu teļus no tām atpakaļ uz mājām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Tad ņemiet Tā Kunga šķirstu un uzlieciet to uz tiem ratiem, un tās zelta lietas, ko jūs Viņam par nozieguma upuri maksāsiet, nolieciet trauciņā viņam blakām un sūtat viņu projām, lai iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Tad lūkojiet, ja tas uz savas robežas ceļu iet, uz Bet-Šemesu, tad Tas mums visu šo lielo ļaunumu darījis, bet ja ne, tad mēs nopratīsim, ka Viņa roka mūs nav aizskārusi, bet tas mums no nejauši noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Un tie ļaudis tā darīja un ņēma divas zīžamas govis un tās iejūdza ratos, un viņu teļus tie paturēja mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Un tie uzlika Tā Kunga šķirstu uz ratiem līdz ar trauciņu ar tām zelta pelēm un ar tām augoņu zīmēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Tad tās govis gāja taisni pa ceļu uz Bet-Šemesu, vienu pašu ceļu tās gāja tikuši(nepārtraukti) bļaudamas, un neatkāpās ne pa labo, ne pa kreiso roku, un Fīlistu lielkungi tām gāja pakaļ līdz Bet-Šemesas robežai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Un Bet-Šemesas ļaudis pļāva kviešus ielejā, un kad tie savas acis pacēla un to šķirstu redzēja, tad tie priecājās, to redzēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Un tie rati nāca uz Jozuas, tā Bet-Šemieša, tīrumu un tur apstājās. Un tur bija liels akmens, un tie skaldīja to ratu malku un upurēja tās govis Tam Kungam par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Un tie Leviti nocēla Tā Kunga šķirstu līdz ar to trauciņu, kas bija klāt, kur tās zelta lietas bija iekšā, un to uzlika uz to lielo akmeni, un Bet-Šemesas ļaudis upurēja tai dienā dedzināmos upurus un kāva Tam Kungam kaujamus upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Un kad tie pieci Fīlistu lielkungi to bija redzējuši, tad tie tai pašā dienā griezās atpakaļ uz Ekronu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Šie nu ir tie zelta augoņi, ko Fīlisti Tam Kungam deva par nozieguma upuri, vienu priekš Ašdodas, vienu priekš Gazas, vienu priekš Asklonas, vienu priekš Gatas, vienu priekš Ekronas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Un tās zelta peles bija pēc visu Fīlistu pilsētu skaita, kas apakš tiem pieciem lielkungiem, gan no stiprajām pilsētām, gan no laucinieku ciemiem. Un par liecinieku ir tas lielais akmens, kur tie Tā Kunga šķirstu bija nocēluši, kas līdz šai dienai ir uz Jozuas, tā Bet-Šemieša, tīruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Un Tas Kungs sita Bet-Šemesas ļaudis, tāpēc ka tie Tā Kunga šķirstu bija aplūkojuši, un Viņš sita no tiem ļaudīm septiņdesmit vīrus (piecdesmit no tūkstoša). Tad tie ļaudis bēdājās, ka Tas Kungs ar tādu lielu sišanu tos ļaudis bija sitis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Un tie ļaudis no Bet-Šemesas sacīja: kas var pastāvēt priekš Tā Kunga, šī svēta Dieva, vaiga? Un pie kā lai Viņš no mums aiziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Tad tie sūtīja vēstnešus pie Kiriat-Jearimas iedzīvotājiem sacīdami: Fīlisti Tā Kunga šķirstu atkal ir atveduši; nāciet un novediet to pie sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Tad tie ļaudis no Kiriat-Jearimas nāca un aizveda Tā Kunga šķirstu un to nesa Abinadaba namā uz kalna, un svētīja viņa dēlu Eleazaru, sargāt Tā Kunga šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Un notikās, ka no tās dienas, kad tas šķirsts Kiriat-Jearimā palika, labs laiks pagāja, pilni divdesmit gadi, un viss Israēla nams žēlojās pēc Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Tad Samuēls runāja uz visu Israēla namu un sacīja: ja jūs no visas savas sirds pie Tā Kunga gribat atgriezties, tad metiet nost tos svešos dievus un tās Astartes, un griežat savu sirdi pie Tā Kunga un kalpojiet Viņam vien, tad Viņš jūs izglābs no Fīlistu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Tad Israēla bērni meta nost tos Baālus un tās Astartes un kalpoja Tam Kungam vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Un Samuēls sacīja: sapulcinājiet man visu Israēli uz Micpu, tad es To Kungu jūsu labad piesaukšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Un tie tapa sapulcināti Micpā un smēla ūdeni un to izlēja Tā Kunga priekšā un gavēja to dienu un tur sacīja: mēs pret To Kungu esam grēkojuši. Tā Samuēls tiesāja Israēla bērnus Micpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Kad nu Fīlisti dzirdēja Israēla bērnus Micpā esam sapulcinātus, tad Fīlistu lielkungi nāca augšām pret Israēli. Un Israēla bērni to dzirdēja un bijās priekš Fīlistiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Un Israēla bērni sacīja uz Samuēli: nemities mūsu dēļ brēkt uz To Kungu, mūsu Dievu, ka Viņš mūs izglābj no Fīlistu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Tad Samuēls ņēma vienu zīdāmu jēru un upurēja to visu Tam Kungam par dedzināmo upuri, un Samuēls brēca uz To Kungu Israēla labad, un Tas Kungs viņu paklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Kad nu Samuēls patlaban to dedzināmo upuri upurēja, tad Fīlisti nāca pret Israēli kauties. Tad Tas Kungs tai dienā lieliem pērkoniem lika rūkt pār Fīlistiem un tos iztrūcināja, ka no Israēla tapa sakauti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Un Israēla vīri izgāja no Micpas un dzinās Fīlistiem pakaļ un tos sakāva līdz pat Betkarai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Tad Samuēls ņēma vienu akmeni un to uzcēla starp Micpu un Zenu, un nosauca viņa vārdu EbenEcer, (palīdzības akmens), un sacīja: līdz šejienei Tas Kungs mums palīdzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Tā Fīlisti tapa pazemoti un nenāca vairs Israēla robežās, un Tā Kunga roka bija pret Fīlistiem, kamēr Samuēls dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Un tās pilsētas, ko Fīlisti Israēlim bija noņēmuši, nāca atkal Israēla rokā, no Ekronas līdz Gatai, un arī viņu robežas Israēls izrāva no Fīlistu rokus, jo Israēlim bija miers ar Amoriešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Un Samuēls tiesāja Israēli, kamēr viņš dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Un viņš gāja visapkārt ik gadus uz Bēteli un Gilgalu un Micpu, un tiesāja Israēli visās tanīs vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Un tad viņš griezās atpakaļ uz Rāmatu, jo tur bija viņa nams, un tur viņš tiesāja Israēli un tur uztaisīja altāri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Kad nu Samuēls bija vecs palicis, tad viņš iecēla savus dēlus Israēlim par soģiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Viņa pirmdzimušā dēla vārds bija Joēls, un tā otrā vārds bija Abijus, tie bija soģi Bēršebā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Bet viņa dēli nestaigāja viņa ceļos, bet dzinās pēc mantas un ņēma dāvanas un grozīja tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Tad visi Israēla vecaji sapulcinājās un nāca pie Samuēla uz Rāmatu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Un uz to sacīja: redzi, tu esi palicis vecs un tavi dēli nestaigā tavos ceļos; tad nu cel mums ķēniņu, kas mūs tiesā, kā tas ir visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Un šī valoda Samuēlim nepatika, kad tie sacīja: dod mums ķēniņu, kas mūs tiesā. Un Samuēls pielūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Tad Tas Kungs sacīja uz Samuēli: paklausi to ļaužu balsij iekš visa, ko tie uz tevi runā, jo tie nav tevi atmetuši, bet Mani tie ir atmetuši, ka Man vairs nebūs ķēniņam būt pār tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Tā tie arvien ir darījuši no tās dienas, kad Es tos esmu izvedis no Ēģiptes, līdz šai dienai, un Mani atstājuši un kalpojuši citiem dieviem; tā tie tev arīdzan dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Un nu klausi viņu balsij, bet apliecini tiem skaidri un dari tiem zināmu, kāda tiesa ķēniņam, kas pār tiem valdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Tad Samuēls visus Tā Kunga vārdus sacīja tiem ļaudīm, kas ķēniņu no viņa prasīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Un viņš sacīja: šī būs tā tiesa ķēniņam, kas pār jums valdīs: jūsu dēlus viņš ņems un tos cels uz saviem ratiem un par saviem jātniekiem, un ka tie skrien viņa ratu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Un viņš tos cels par virsniekiem pār piecdesmitiem, un ka tie viņa tīrumu ar un viņa labību pļauj, un ka tie viņam taisa kara rīkus un ratu rīkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Un jūsu meitas viņš ņems par zalvju(ziežu) taisītājām un par pavārēm un par cepējām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Un jūsu labākos tīrumus un vīna un eļļas dārzus viņš ņems un dos saviem kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Un no jūsu druvām un vīna dārziem viņš ņems to desmito un to dos saviem sulaiņiem un kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Un viņš ņems jūsu kalpus un jūsu kalpones un jūsu labākos jaunekļus un jūsu ēzeļus, un ar tiem darīs savu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'No jūsu ganāmiem pulkiem viņš ņems to desmito, un jūs būsiet viņam par kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Tad jūs gan tai laikā brēksiet sava ķēniņa dēļ, ko jūs sev izvēlējušies, bet Tas Kungs jūs tai dienā neklausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Bet tie ļaudis negribēja klausīt Samuēla balsij un sacīja: ne tā, bet ķēniņš lai ir pār mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Un mēs gribam būt, kā visas citas tautas, un mūsu ķēniņam būs mūs tiesāt un mūsu priekšā iziet un vest mūsu karus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Un Samuēls dzirdēja visus tos ļaužu vārdus, un tos atsacīja Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Tad Tas Kungs sacīja uz Samuēli: paklausi viņu balsij un cel tiem ķēniņu. Tad Samuēls sacīja uz Israēla ļaudīm: ejat ikkatrs savā pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Un vīrs bija no Benjamina, Ķis vārdā, tas bija Abiēļa dēls, tas Cerora, tas Bekora, tas Apija, tas viena Benjaminieša dēls. Šis bija krietns, turīgs vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Un viņam bija dēls, Sauls vārdā, jauns un skaists, un tāda skaista vīra nebija starp Israēla bērniem kā viņš, veselu galvu lielāks nekā visi citi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Un Saula tēvam Ķisam ēzeļu mātes bija zudušas, un Ķis sacīja uz savu dēlu Saulu: ņem jel vienu no puišiem līdzi, un celies, ej meklēt tās ēzeļu mātes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Tad viņš pārstaigāja Efraīma kalnus un gāja caur Zalisa zemi, un tās neatrada; un tie gāja caur Zaālim zemi, un arī tur tās nebija; un tie gāja caur Jemiņa zemi un tās neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Tad tie nāca uz Cuv zemi, un Sauls sacīja uz savu puisi, kas pie viņa bija: nāc, iesim atpakaļ, ka mans tēvs no tām ēzeļu mātēm mitēdamies nesāk mūsu pēc bēdāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Bet šis uz to sacīja: redzi jel, šinī pilsētā ir viens Dieva vīrs, un tas vīrs stāv godā; viss ko viņš runā, tas tiešām notiek; ejam nu uz turieni, varbūt viņš mums teiks mūsu ceļu, kur mums jāiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Tad Sauls sacīja uz savu puisi: bet redzi, kad iesim, ko mēs tam vīram nesīsim? Jo maizes vairs nav mūsu kulītēs, un dāvanu mums nav, tam Dieva vīram ko nest, - kas tad mums ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Un tas puisis Saulam atkal atbildēja un sacīja: redzi, manā rokā ir sudraba sēķeļa ceturtdaļa, to es došu tam Dieva vīram, lai viņš mums teic mūsu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Citkārt tā sacīja iekš Israēla, kad kas gāja Dievu vaicāt: nāciet, iesim pie tā redzētāja; jo ko šodien sauc par pravieti, to citkārt sauca par redzētāju.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Tad Sauls sacīja uz savu puisi: tavs vārds ir labs, nāc, iesim! Un tie gāja uz to pilsētu, kur tas Dieva vīrs bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Šiem nu augšām ejot pa pilsētas pakalnu sastapa meitas, kas iznāca ūdeni smelt, un šie uz tām sacīja: vai tas redzētājs šeitan?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Tās viņiem atbildēja un sacīja: redzi, še pat viņš ir, steidzies tad, jo viņš šodien ir nācis pilsētā, tāpēc ka šodien tiem ļaudīm upuris uz kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Kā nāksiet pilsētā, tad jūs viņu atradīsiet, pirms ne kā viņš iet uz kalnu ēst. Jo tie ļaudis neēdīs, kamēr viņš nāks, jo viņš svētī to upuri, pēc tam ēd tie aicinātie; tāpēc ejat nu, jo šodien jūs tiksiet pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Un tā tie gāja pilsētā; un pilsētā ienākot, redzi, Samuēls tiem izgāja pretī, gribēdams iet uz kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Bet Tas Kungs vienu dienu papriekš, pirms ne kā Sauls nāca, Samuēla ausi bija atvēris sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Rīt ap šo laiku Es pie tevis sūtīšu vienu vīru no Benjamina zemes; to tev būs svaidīt par valdītāju Maniem Israēla ļaudīm, jo viņš Manus ļaudis izpestīs no Fīlistu rokas. Jo Es esmu uzlūkojis Savus ļaudis, tāpēc ka viņu brēkšana pie Manis nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Kad nu Samuēls Saulu redzēja, tad Tas Kungs tam atbildēja: redzi, tas ir tas vīrs, par ko Es tev sacīju: šim būs valdīt pār Maniem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Un Sauls piegāja pie Samuēla pašos vārtos un sacīja: saki man, lūdzams, kur še ir tā redzētāja nams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Tad Samuēls Saulam atbildēja un sacīja: es esmu tas redzētājs, ej manā priekšā uz kalnu, un ēdat šodien ar mani, tad es tevi rīt agri atlaidīšu, un visu, kas tavā sirdī, to es tev sacīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Un par tām ēzeļu mātēm, kas tev aizvakar zudušas, par tām nebēdājies vairs, jo tās ir atrastas. Un kam tad būs nu viss Israēla labums? Vai tas nebūs tev un visam tava tēva namam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Tad Sauls atbildēja un sacīja: vai es neesmu viens Benjaminietis, no tās vismazākās Israēla cilts, un mans nams ir tas mazākais no visiem Benjamina cilts namiem? Kāpēc tad tu uz mani saki tādu vārdu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Tad Samuēls ņēma Saulu un viņa puisi un tos ieveda ēdamā istabā un tos sēdināja visaugstākā vietā pie tiem aicinātiem, - to bija pie trīsdesmit vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Tad Samuēls sacīja uz to pavāru: dod šurp to gabalu, ko es tev devu, sacīdams: paglabā to pie sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Tad tas pavārs atnesa vienu pleci ar visu to, kas klāt bija, un to cēla Saulam priekšā. Un viņš sacīja: redzi, tev ir priekšā celts, kas bija atlicināts, ēd, jo tas uz šo nolikto laiku priekš tevis ir paglabāts, kad es sacīju: es tos ļaudis esmu aicinājis. Tā Sauls ēda ar Samuēli tai dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Un tie nogāja no tā kalna uz pilsētu; un viņš runāja ar Saulu uz jumta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Un tie cēlās agri, un kad gaisma metās, tad Samuēls sauca Saulam uz jumta sacīdams: celies, ka es tevi pavadu. Tad Sauls cēlās, un tie abi, viņš un Samuēls, izgāja ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Un kad tie līdz pilsētas galam bija nogājuši, tad Samuēls sacīja uz Saulu: saki tam puisim, lai viņš mums iet papriekš, (tad tas nogāja), bet tu palieci nu stāvot, jo es tev likšu Dieva vārdu dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tad Samuēls ņēma eļļas trauciņu un to izlēja uz viņa galvu un to skūpstīja un sacīja: vai Tas Kungs tevi nav svaidījis par valdnieku pār Savu mantību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Kad tu šodien no manis aiziesi, tad tu atradīsi divus vīrus pie Rahēles kapa, pie Benjamina robežām Celcā, tie uz tevi sacīs: tās ēzeļu mātes ir atrastas, ko tu esi izgājis meklēt, un redzi, tavs tēvs no tām ēzeļu mātēm ir mitējies un bēdājās jūsu pēc, sacīdams: ko lai es daru sava dēla pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Un no turienes vēl tālāki gājis, tu nāksi pie Tābor ozola, tur tevi sastaps trīs vīri, kas uz Bēteli iet pie Dieva; viens nesīs trīs kazlēnus un otrs nesīs trīs maizes klaipus un trešais nesīs trauku ar vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Un tie tevi apsveicinās laipnīgi un tev dos divas maizes; tās ņem no viņu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Pēc tam tu nāksi uz to Dieva pakalnu, kur Fīlistu lēģeri stāv, un kad tu pilsētā nāksi, tad tu sastapsi vienu praviešu pulku no kalna nākam, un viņu priekšā stīgas un bungas un stabules un kokles, un tie runās praviešu vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Un Tā Kunga Gars uz tevi nāks, ka tu līdz ar tiem praviešu vārdus runāsi, un tad tu tapsi pārvērsts par citu vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Kad nu šās zīmes tev notiks, tad dari, kā tava roka māk, jo Dievs ir ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Bet tev būs noiet manā priekšā uz Gilgalu, un redzi, es nonākšu pie tevis, dedzināmos upurus upurēt un pateicības upurus upurēt. Septiņas dienas tev tur būs gaidīt, tiekams es pie tevis nāku un tev saku, kas tev jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Un notikās, kad viņš savu muguru grieza, no Samuēla aiziet, tad Dievs viņam deva citu sirdi, un visas tās zīmes notika tai pašā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Tiem nu tur pie tā pakalna nākot, redzi, tad praviešu pulks viņu sastapa, un Tā Kunga Gars nāca pār viņu, un viņš runāja praviešu vārdus viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Un visi, kas viņu citkārt bija pazinuši, kad tie to redzēja ar tiem praviešiem praviešu vārdus runājam, tad tie ļaudis cits uz citu sacīja: kas tam Ķisa dēlam noticis? Vai Sauls arīdzan starp praviešiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Tad viens vīrs no turienes atbildēja un sacīja: kas tad ir šo tēvs? Tādēļ tas sakāms vārds ir cēlies: Vai Sauls arīdzan starp praviešiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Un viņš beidza praviešu vārdus runāt, un nāca uz to kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Tad Saula tēva brālis sacīja uz viņu un uz viņa puisi: kur bijāt gājuši? Viņš sacīja: tās ēzeļu mātes meklēt, un kad mēs redzējām, ka nav, tad mēs nācām pie Samuēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Tad Saula tēva brālis sacīja: saki man jel, ko jums Samuēls ir teicis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Un Sauls sacīja uz savu tēva brāli: viņš mums patiesi ir sacījis, tās ēzeļu mātes esam atrastas; bet par to ķēniņa godu, par ko Samuēls bija runājis, viņš tam nekā nesacīja. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Tad Samuēls tos ļaudis sasauca Tā Kunga priekšā uz Micpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Un viņš sacīja uz Israēla bērniem: tā saka Tas Kungs, Israēla Dievs: Es Israēli esmu izvedis no ēģiptiešu rokas un no visu ķēniņu rokas, kas jūs spaidīja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Bet jūs šodien savu Dievu esat atmetuši, kas jūs no visām jūsu bēdām un izbailēm ir atpestījis, un uz Viņu esat sacījuši: “Cel pār mums ķēniņu.” Nu tad, stājaties Tā Kunga priekšā pēc savām ciltīm un pēc saviem tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Kad nu Samuēls visām Israēla ciltīm bija licis klātu nākt, tad Benjamina cilts tapa iezīmēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Un kad viņš Benjamina ciltij pēc viņas radiem lika klātu nākt, tad Matra radi tapa iezīmēti, un Sauls, Ķisa dēls, tapa iezīmēts. Un tie to meklēja, bet neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Tad tie To Kungu vaicāja: vai vēl kāds še atnācis? Tad Tas Kungs sacīja: redzi, viņš starp tiem traukiem ir paslēpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Tad tie steidzās un viņu no turienes atveda, un viņš stājās ļaužu vidū, un viņš bija veselu galvu lielāks nekā visi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Tad Samuēls sacīja uz visiem ļaudīm: vai jūs redzat, kādu Tas Kungs ir izredzējis? Jo neviens nav tāds, kā viņš, starp visiem ļaudīm. Tad visi ļaudis gavilēja un sacīja: lai dzīvo ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Tad Samuēls uz tiem ļaudīm teica to ķēniņa tiesu un to sarakstīja grāmatā un nolika Tā Kunga priekšā. Un Samuēls atlaida visus ļaudis, ikvienu uz viņa mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Un Sauls gāja arīdzan mājās uz Ģibeju, un viņam gāja līdz pulks vīru, kam Dievs sirdi bija kustinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Bet kādi nelieši sacīja: ko šis mums palīdzēs? Un tie viņu nicināja un viņam nenesa dāvanas. Bet viņš nelikās to dzirdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Tad Naās, tas Amonietis, cēlās un apmeta lēģeri pret Jabesu Gileādā, un visi Jabesas vīri sacīja uz Naāsu: deri derību ar mums, tad mēs tev gribam kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Tad Naās, tas Amonietis, uz tiem sacīja: tā es ar jums gribu derēt derību, ka es jums visiem labo aci izduru un ka es visu Israēli tā lieku kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Tad Jabesas vecaji uz viņu sacīja: dod mums septiņas dienas vaļu, ka mēs vēstnešus sūtam pa visām Israēla robežām; ja tad nav, kas mūs izpestī, tad mēs pie tevis gribam iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Kad nu tie vēstneši nāca uz Ģibeju, Saula pilsētu, un šos vārdus runāja priekš ļaužu ausīm, tad visi ļaudis pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Un redzi, Sauls ar vēršiem nāca no lauka. Un Sauls sacīja: kas tiem ļaudīm kait, ka tie raud? Tad tie viņam stāstīja Jabesas vīru vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Un Dieva Gars nāca pār Saulu, kad tas šos vārdus dzirdēja, un viņa dusmas ļoti iedegās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Un viņš ņēma jūgu vēršu un tos sakapāja gabalos un tos sūtīja pa visām Israēla robežām caur vēstnešu rokām, sacīdams: kas neizies Saulam pakaļ un Samuēlim pakaļ, tā vēršiem tāpat darīs. Tad Tā Kunga bijāšana krita uz tiem ļaudīm, un tie izgāja kā viens vienīgs vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Un viņš tos skaitīja Bazekā, un Israēla bērnu bija trīssimt tūkstoši un Jūda vīru bija trīsdesmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Tad tie sacīja uz tiem vēstnešiem, kas bija nākuši: tā sakāt Jabesas vīriem Gileādā: rītu jums būs glābšana, kad saule spiež. Kad nu tie vēstneši nāca un Jabesas vīriem to stāstīja, tad tie priecājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Un Jabesas vīri sacīja: rīt mēs pie jums iesim ārā, lai jūs mums dariet, tā kā jums patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Un otrā rītā Sauls tos ļaudis dalīja trijos pulkos, un tie uzbruka lēģerim gaismai austot un kāva Amoniešus, kamēr diena iekarsa; bet tie, kas atlika, tā tapa izklīdināti, ka viņu starpā ne divi nepalika kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Tad tie ļaudis sacīja uz Samuēli: kas tie tādi, kas sacīja: vai lai Sauls pār mums valda? Dodiet šurp tos vīrus, lai tos nokaujam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Bet Sauls sacīja: šai dienā nevienam nebūs tapt nokautam, jo Tas Kungs šodien pestīšanu ir devis iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Un Samuēls sacīja uz tiem ļaudīm: nāciet, iesim uz Gilgalu un atjaunosim tur ķēniņa valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Un visi ļaudis gāja uz Gilgalu un cēla tur Saulu par ķēniņu Tā Kunga priekšā Gilgalā, un upurēja tur pateicības upurus Tā Kunga priekšā. Un Sauls tur ļoti priecājās ar visiem Israēla vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Tad Samuēls sacīja uz visu Israēli: redzi, es jūsu balsij esmu paklausījis iekš visa, ko jūs man esat sacījuši, un esmu jums cēlis ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Un nu redzi, te jūsu ķēniņš jūsu priekšā staigā, un es esmu vecs un sirms palicis, un mani dēli ir pie jums, un es esmu jūsu priekšā staigājis no savas jaunības līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Redzi, še es esmu, atbildiet pret mani Tā Kunga priekšā un viņa svaidītā priekšā: kura vērsi es esmu ņēmis un kuram es ēzeli ņēmis? Kuram es varas darbu darījis, kuru es spaidījis un no kura rokas es dāvanas ņēmis, ka es savas acis tādēļ būtu aizdarījis? Tad es jums to atdošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Un tie sacīja: tu mums netaisnību neesi darījis nedz mūs spaidījis, un nekā neesi ņēmis no neviena rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Tad viņš uz tiem sacīja: lai Tas Kungs ir liecinieks pret jums, un Viņa svaidītais lai ir šodien liecinieks, ka jūs manā rokā nekā neesat atraduši. Un tie sacīja: lai ir liecinieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Un Samuēls sacīja uz tiem ļaudīm: (lai ir liecinieks) Tas Kungs, kas Mozu un Āronu ir cēlis un kas jūsu tēvus no Ēģiptes zemes izvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Un nu stājaties šeitan, ka es ar jums tiesājos Tā Kunga priekšā par visām Tā Kunga labdarīšanām, ko Viņš jums un jūsu tēviem darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Kad Jēkabs Ēģiptes zemē bija nācis, un jūsu tēvi uz To Kungu brēca, tad Tas Kungs sūtīja Mozu un Āronu, un tie vadīja jūsu tēvus no Ēģiptes un lika tiem šai vietā dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Bet tie aizmirsa To Kungu, savu Dievu; tāpēc Viņš tos pārdeva Siserus, Hacoras kara kunga, rokā un Fīlistu rokā un Moaba ķēniņa rokā, un šie karoja pret viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Tad tie brēca uz To Kungu un sacīja: mēs esam grēkojuši, jo mēs To Kungu esam atstājuši un kalpojuši Baālam un Astartēm. Un nu izpestī mūs no mūsu ienaidnieku rokas, tad mēs Tev gribam kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Tad Tas Kungs sūtīja Jerub-Baālu un Bedanu un Jeftu un Samuēli, un jūs izglāba no jūsu ienaidnieku rokas visapkārt, tā ka jūs mierā dzīvojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Kad nu jūs redzējāt, ka Naās, Amona bērnu ķēniņš, pret jums nāca, tad jūs uz mani sacījāt: nē, bet ķēniņam būs pār mums valdīt! Un tomēr Tas Kungs, jūsu Dievs, bija jūsu ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Un nu redzi, te ir tas ķēniņš, ko jūs esat izvēlējušies, ko jūs esat prasījuši, un redzi, Tas Kungs ir cēlis ķēniņu pār jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Ja tik jūs To Kungu bīsities un Viņam kalposiet un Viņa balsij klausīsiet un Tā Kunga mutei pretī neturēsities un pakaļ staigāsiet Tam Kungam, savam Dievam, gan jūs, gan tas ķēniņš, kas pār jums valda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Bet ja jūs Tā Kunga balsij neklausīsiet un Tā Kunga mutei pretī turēsities, tad Tā Kunga roka būs pret jums, kā pret jūsu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Nostājaties tagad šeitan un redziet šo lielo lietu, ko Tas Kungs priekš jūsu acīm darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Vai tagad nav kviešu pļaujamais laiks? Es piesaukšu To Kungu, un tas dos pērkonus un lietu, lai jūs atzīstat un redzat, ka tas ļaunums liels, ko jūs esat darījuši priekš Tā Kunga acīm, ķēniņu sev lūgdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Kad nu Samuēls To Kungu piesauca, tad Tas Kungs deva pērkonus un lietu tai pašā dienā; un visi ļaudis To Kungu un Samuēli ļoti bijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Un visi ļaudis sacīja uz Samuēli: lūdz par saviem kalpiem To Kungu, savu Dievu, ka mēs nemirstam. Pie visiem saviem grēkiem mēs arī to grēku esam darījuši, ka sev ķēniņu esam lūguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Tad Samuēls sacīja uz tiem ļaudīm: nebīstaties! Jūs gan visu šo grēku esat darījuši, tomēr neatkāpjaties no Tā Kunga, bet kalpojiet Tam Kungam ar visu savu sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Un neatkāpjaties, ka nedzenaties nelietībai pakaļ, tiem, kas nedz palīdz nedz izglābj jo tie ir nelietība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Jo Tas Kungs neatstums Savus ļaudis Sava lielā Vārda dēļ; jo Tam Kungam ir paticis jūs darīt Sev par ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Arī es ne mūžam tā pret To Kungu neapgrēkošos, ka es mitētos par jums lūgt un jums mācīt to labo un taisno ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Bīstaties tikai To Kungu un kalpojiet Viņam uzticīgi no visas savas sirds, jo jūs esat redzējuši, kādas lielas lietas Viņš pie jums ir darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Bet ja jūs ļaunumu darīsiet, tad gan jūs, gan jūsu ķēniņš iesiet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Sauls bija četrdesmit* gadus vecs, kad palika par ķēniņu un valdīja divdesmit** divus gadus pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Un Sauls sev izlasīja trīs tūkstošus (vīru) no Israēla un divi tūkstoši bija pie Saula Mikmasā un uz Bēteles kalniem, un tūkstoš (vīru) pie Jonatāna Benjamina Ģibejā; un tos citus ļaudis viņš atlaida, ikvienu uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Bet Jonatāns sita Fīlistus lēģerī Ģebā, un Fīlisti to dzirdēja. Tādēļ Sauls pūta ar bazūnēm pa visu zemi sacīdams: lai Ebreji to dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Tad viss Israēls dzirdēja sakām: Sauls Fīlistus lēģerī ir sitis, un Israēls ir tapis smirdots pie Fīlistiem. Tad tie ļaudis tapa sasaukti uz Gilgalu Saulam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Un Fīlisti sapulcējās pret Israēli karot, trīsdesmit tūkstoš rati un seštūkstoš jātnieki un tik daudz ļaužu kā smiltis jūrmalā. Un tie cēlās un apmeta lēģeri pie Mikmasas, no Bet-Avenas pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Kad nu Israēla vīri redzēja savas bēdas (jo tie ļaudis bija spaidos), tad tie ļaudis paslēpās alās un ērkšķu krūmos un klintīs un pilīs un bedrēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Un Ebreji cēlās pār Jardāni pāri uz Gada zemi un Gileādu. Bet Sauls bija vēl Gilgalā un visi ļaudis drebēja viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Tad viņš gaidīja septiņas dienas, līdz tam laikam, ko Samuēls bija nolicis. Bet kad Samuēls uz Gilgalu nenāca, tad tie ļaudis no viņa izklīda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Tad Sauls sacīja: nesiet man šurp to dedzināmo upuri un tos pateicības upurus. Un viņš upurēja to dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Kad nu viņš bija beidzis upurēt to dedzināmo upuri, redzi, tad Samuēls atnāca, un Sauls izgāja tam pretī, viņu sveicināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Tad Samuēls sacīja: ko tu esi darījis? Un Sauls sacīja: kad es redzēju, ka tie ļaudis no manis izklīda un tu noliktā laikā nenāci, un tie Fīlisti bija sapulcējušies Mikmasā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Tad es sacīju: nu Fīlisti pie manis nāks uz Gilgalu, un es Tā Kunga vaigu neesmu pielūdzis, tā es iedrošinājos un upurēju to dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Tad Samuēls sacīja uz Saulu: tu esi aplam darījis; tu neesi turējis Tā Kunga, sava Dieva, bausli, ko Viņš tev ir pavēlējis; jo nu Tas Kungs tavu valstību pār Israēli būtu apstiprinājis mūžīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Bet nu tava valstība nepastāvēs: Tas Kungs Sev vīru ir izmeklējis pēc Savas sirds, un Tas Kungs to ir nolicis Saviem ļaudīm par valdnieku, tāpēc ka tu neesi turējis, ko Tas Kungs tev bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Tad Samuēls cēlās un gāja no Gilgalas uz Benjamina Ģibeju, un Sauls skaitīja tos ļaudis, kas pie viņa atradās, pie sešsimt vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Un Sauls un Jonatāns, viņa dēls, un tie ļaudis, kas pie viņiem atradās, palika Benjamina Ģibejā. Bet Fīlisti bija apmetušies Mikmasā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Un no Fīlistu lēģera izgāja trīs pulki sirotāju, viens pulks griezās uz to ceļu pret Ovru, uz Saula zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Un viens pulks griezās uz to ceļu pret Bet-Oronu, un viens pulks griezās uz to robežas ceļu, kas uz Ceboīm ieleju pret tuksnesi stiepjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Un neviena kalēja nebija pa visu Israēla zemi. Jo Fīlisti sacīja: lai Ebreji ne zobenu, ne šķēpu netaisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Tādēļ visam Israēlim bija jānoiet pie Fīlistiem, savu lemesi vai lāpstu vai cirvi vai izkapti asināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Un asmeņi pie izkaptīm un lāpstām un dakšām un cirvjiem bija atcirsti, un tie dzenuļi atkal bija jāmetina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Un notikās kaujas dienā, ka ne pie viena no tiem ļaudīm, kas bija pie Saula un pie Jonatāna, neatrada rokā ne zobena, ne šķēpa, tikvien pie Saula un pie Jonatāna, viņa dēla, tie atradās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Un viens pulks Fīlistu devās uz to ceļa šaurumu kalnos pie Mikmasas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Un kādā dienā Jonatāns, Saula dēls, sacīja uz savu puisi, kas viņa bruņas nesa: nāc, iesim pāri uz Fīlistu vakti, kas viņā pusē. Un viņš to savam tēvam nesacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Bet Sauls palika Ģibejas galā apakš tā granāta koka Migronā, un to ļaužu, kas pie viņa, bija pie sešsimt vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Un Ahijus, Aķitaba dēls, (tas bija Ihaboda brālis, tas Pinehas dēls, tas Elus dēls, kas bija Tā Kunga priesteris iekš Šīlo), nesa to efodu; bet tie ļaudis nezināja, ka Jonatāns bija aizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Bet tur tai ceļa šaurumā, kur Jonatānam bija cauri jāiet uz Fīlistu vakti, bija divas asas klintis, viena šai pusē, otra viņā pusē, un vienai bija vārds Bocec un otrai bija vārds Zene.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Vienai gals cēlās uz ziemeļa pusi pret Mikmasu un otrai uz dienasvidu pret Ģebu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Un Jonatāns sacīja uz to puisi, kas viņa bruņas nesa: ejam pāri uz šo neapgraizīto ļaužu vakti, vai Tas Kungs priekš mums ko nedarīs, jo Tam Kungam nav grūti atpestīt, vai caur daudz, vai caur maz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Tad viņa bruņu nesējs uz to sacīja: dari visu, kas tavā sirdī; ej tik, redzi, es iešu tev līdz pēc tava prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Tad Jonatāns sacīja: redzi, iesim pāri pie tiem vīriem un parādīsimies viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Ja tie tā uz mums sacīs: stāviet, tiekams mēs pie jums tiksim, tad paliksim stāvot savā vietā un nekāpsim augšā pie viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Bet ja tie tā sacīs: nāciet augšā pie mums, - tad kāpsim augšā, jo Tas Kungs tos ir devis mūsu rokā, un tas mums būs par zīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Kad nu tie abi Fīlistu vakts vīriem parādījās, tad tie Fīlisti sacīja: redzi, Ebreji nāk ārā no tām alām, kur tie bija paslēpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Un tie vakts vīri sauca Jonatānam un viņa bruņu nesējam un sacīja: nāciet pie mums augšā, mēs jums ko teiksim. Tad Jonatāns uz savu bruņu nesēju sacīja: kāp man pakaļ, jo Tas Kungs tos ir devis Israēla rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Tad Jonatāns ar rokām un kājām uzrāpās, un viņa bruņu nesējs viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Un tie krita Jonatāna priekšā, un viņa bruņu nesējs tos kāva viņam pakaļ, tā ka šinī pirmā kaušanā Jonatāns un viņa bruņu nesējs nokāva pie divdesmit vīru, tik ne pusbirzuma* vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Un tur izbailes cēlās lēģerī, uz lauka un starp tiem ļaudīm, un tā vakts un tie sirotāji paši, pat tie drebēja, un zeme trīcēja, un tās bija izbailes no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Kad nu Saula sargi Benjamina Ģibejā redzēja, ka tas pulks izšķīda un izklīda šurp un turp,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Tad Sauls sacīja uz tiem ļaudīm, kas pie viņa bija: skaitāt jel un redziet, kas no mums ir nogājis. Tad tie skaitīja, un redzi, Jonatāna un viņa bruņu nesēja nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Tad Sauls sacīja uz Ahiju: atnes Dieva šķirstu šurp! (jo Dieva šķirsts to laiku bija pie Israēla bērniem).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Un kamēr Sauls vēl uz to priesteri runāja, tad troksnis Fīlistu lēģerī auga un vairojās. Un Sauls sacīja uz to priesteri: apturi savu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Tad Sauls un visi ļaudis, kas pie viņa bija, sasaucās un gāja kauties un redzi, tur bija zobens pret zobenu, un bija liels troksnis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Un tie Ebreji, kas līdz šim bija pie Fīlistiem lēģerī bijuši un tiem bija līdz nākuši, tie arīdzan pārgāja pie Israēla, kas bija pie Saula un pie Jonatāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Un visi Israēla vīri, kas bija apslēpušies uz Efraīma kalniem, kad tie dzirdēja Fīlistus bēgam, arī dzinās tiem pakaļ kaudamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Tā Tas Kungs tai dienā Israēli atpestīja, un tā kaušanās stiepās līdz Bet-Avenai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Un Israēla vīri nogura tai dienā, un Sauls tiem ļaudīm piekodināja sacīdams: nolādēts tas vīrs, kas maizi ēdīs, pirms vakars nāks un es būšu atriebies pie saviem ienaidniekiem. Un neviens no tiem ļaudīm maizes neēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Un visi ļaudis nāca mežā, un tur bija medus pa zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Kad nu tie ļaudis nāca mežā, redzi, tur tecēja medus. Bet neviens nelika savu roku pie mutes, jo tie ļaudis bijās no tā zvēresta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Bet Jonatāns to nebija dzirdējis, ka viņa tēvs tos ļaudis ar zvērestu bija apdraudējis, un viņš izstiepa sava zižļa galu, kas bija viņa rokā, un iemērca to tai medū, un grieza savu roku atkal pie mutes, tad viņa acis tapa skaidras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Un viens no tiem ļaudīm bildināja(ieminējās) un sacīja: tavs tēvs tos ļaudis ar zvērestu gauži apdraudējis sacīdams: nolādēts lai ir tas vīrs, kas šodien ko ēd! Un tā tie ļaudis nogurst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Tad Jonatāns sacīja: mans tēvs to zemi ir sajaucis; redziet jel, kā manas acis palikušas skaidras, kad es maķenīt no šī medus esmu baudījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Cik vairāk, kad tie ļaudis būtu ēdin ēduši no savu ienaidnieku laupījuma, ko tie atraduši; bet nu Fīlistu sakaušana nav bijusi tik liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Taču tai dienā tie Fīlistus kāva no Mikmasas līdz Ajalonai, un tie ļaudis bija ļoti noguruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Tad tie ļaudis taisījās uz laupīšanu, un ņēma avis un vēršus un teļus, un tos kāva zemē, un tie ļaudis tos ēda ar asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Tad Saulam to teica un sacīja: redzi, tie ļaudis apgrēkojās pret To Kungu, asinis ēzdami. Un tas sacīja: jūs noziedzāties; atveļat man tagad šurp vienu lielu akmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Un Sauls sacīja: ejat šurp un turp pa tiem ļaudīm un sakāt tiem: atvediet pie manis ikviens savu vērsi un ikviens savu avi, un nokaujiet tos šeit un ēdiet un neapgrēkojaties pret To Kungu, ar asinīm ēzdami. Tad visi ļaudis naktī atveda ikviens savu vērsi ar savu roku un tos tur nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Tad Sauls Tam Kungam uztaisīja vienu altāri. Šis bija tas pirmais altāris, ko viņš Tam Kungam cēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Un Sauls sacīja: dzīsimies Fīlistiem pakaļ pa nakti un aplaupīsim tos, līdz kamēr gaisma metās, un neatlicināsim no tiem neviena. Tie sacīja: dari visu, kas tavām acīm patīk. Bet tas priesteris sacīja: iesim še pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Tad Sauls vaicāja Dievu: vai man Fīlistiem būs dzīties pakaļ? Vai tu tos dosi Israēla rokā? Bet Viņš tam tai dienā neatbildēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Tad Sauls sacīja: nāciet šurp visi ļaužu virsnieki, un izmeklējiet un raugiet, pie kā tas grēks ir šim brīžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Jo tik tiešām kā Tas Kungs dzīvo, kas Israēli atpestījis, jebšu tas būtu pie mana dēla Jonatāna, tad tam tiešām būs mirt. Un neviens no visiem ļaudīm tam neatbildēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Atkal tas sacīja uz visu Israēli: jums būs vienā pusē stāvēt, un es un mans dēls Jonatāns stāvēsim otrā pusē. Tad tie ļaudis sacīja uz Saulu: dari, kā tev patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Tad Sauls sacīja uz To Kungu, Israēla Dievu: parādi taisnību. Tad Jonatāns un Sauls tapa iezīmēti, bet tie ļaudis izgāja bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Tad Sauls sacīja: metiet par mani un par manu dēlu Jonatānu. Tad Jonatāns tapa iezīmēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Un Sauls sacīja uz Jonatānu: saki man, ko tu esi darījis? Tad Jonatāns viņam teica un sacīja: es tikai maķenīt medus esmu baudījis ar sava zižļa galu, kas bija manā rokā; redzi, man nu jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Tad Sauls sacīja: lai Dievs man šā un tā dara, Jonatān, - tev tiešām jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Tad tie ļaudis sacīja uz Saulu: vai Jonatānam būs mirt, kas šo lielo pestīšanu iekš Israēla padarījis. Nebūt ne! Tik tiešām kā Tas Kungs dzīvo, ne matam no viņa galvas nebūs zemē krist, jo viņš to šodien ir izdarījis ar Dievu. Tā tie ļaudis Jonatānu izpestīja, ka tam nebija jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Un Sauls no Fīlistiem atstājās un griezās atpakaļ, un Fīlisti gāja atkal uz savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Bet Sauls valdību bija uzņēmis pār Israēli un karoja visapkārt ar visiem saviem ienaidniekiem, arī pret Moabu un pret Amona bērniem un pret Edomu un pret Cobas ķēniņiem un pret Fīlistiem, un visiem, kurp viņš griezās viņš lika just savu bardzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Un viņš parādīja spēku un sakāva Amalekiešus un izpestīja Israēli no viņu laupītāju rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Un Saula dēli bija Jonatāns, Izvus un Malķizuūs, un viņa abu meitu vārdi - tās pirmdzimtās vārds bija Merabe un tās jaunākās vārds bija Mikale.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Un Saula sievas vārds bija Akinoame, Aķimaāca meita; un viņa kara virsnieka vārds bija Abners, Nera, Saula tēva brāļa, dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Un Ķis, Saula tēvs, un Ners, Abnera tēvs, bija Abiēļa dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Un karš bija briesmīgs pret Fīlistiem, kamēr Sauls dzīvoja. Un kad Sauls redzēja kādu stipru un varenu vīru, tad viņš to ņēma pie sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Tad Samuēls sacīja uz Saulu: Tas Kungs mani sūtījis, tevi par ķēniņu svaidīt pār Viņa ļaudīm, pār Israēli. Un nu klausi Tā Kunga vārdu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Tā saka Tas Kungs Cebaot: Es to gribu piemeklēt, ko Amaleks Israēlim darījis, ka viņš pret to ir cēlies uz ceļa, kad (Israēls) nāca no Ēģiptes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Ej nu un kauj Amaleku, izdeldiet visu, kas tam pieder, un netaupi viņu, bet nokauj gan vīrus un sievas, gan bērnus un zīdāmos, gan vēršus un avis, gan kamieļus un ēzeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'To Sauls tiem ļaudīm darīja zināmu un tos izskaitīja Telaīmā, divsimt tūkstoš kājnieku un desmit tūkstoš vīrus no Jūda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Un Sauls nāca pie Amalekiešu pilsētas, un lika kādiem pie upes slēpties. Un Sauls Keniešiem lika sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Ejat, šķiraties un izejat no Amalekiešu vidus, lai es jūs līdz ar tiem neizdeldu, jo jūs esat žēlastību darījuši pie visiem Israēla bērniem, kad tie no Ēģiptes izgāja. Tā Kenieši atšķīrās no Amalekiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Un Sauls kāva Amalekiešus no Ķeviļas līdz Šurai, kas ir šaipus Ēģiptes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Un viņš sagūstīja Agagu, Amalekiešu ķēniņu, dzīvu, un visus ļaudis viņš izdeldēja ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Bet Sauls un tie ļaudis saudzēja Agagu un tās labākās avis un vēršus un barotus lopus un jērus un visu, kas bija labs, un tos negribēja izdeldēt, bet visu, kas bija nederīgs un panīcis, to viņi izdeldēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Tad Tā Kunga vārds notika uz Samuēli un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '“Man ir žēl, ka Es Saulu esmu cēlis par ķēniņu, tāpēc ka viņš no Manis ir nogriezies un Manus vārdus nav izdarījis.” Tad Samuēls apskaitās un piesauca To Kungu cauru nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Un Samuēls cēlās agri Saulam pretī pašā rītā. Un Samuēlim teica un sacīja: Sauls ir uz Karmeli nācis, un redzi, viņš sev cēlis goda stabu, un viņš ir griezies un tālāk gājis ceļā uz Gilgalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Tad Samuēls nāca pie Saula, un Sauls uz to sacīja: esi svētīts no Tā Kunga! Es Tā Kunga vārdu esmu izdarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Tad Samuēls sacīja: bet kas tā ir par avju brēkšanu manās ausīs un kas tā ir par vēršu bļaušanu, ko es dzirdu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Tad Sauls sacīja: tos tie no Amalekiešiem atveduši; jo tie ļaudis labākās avis un labākos vēršus ir taupījuši par upuri Tam Kungam, tavam Dievam; bet to citu mēs esam izdeldējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Tad Samuēls sacīja uz Saulu: gan nu, es tev sacīšu, ko Tas Kungs uz mani ir runājis šo nakti. Tad tas uz viņu sacīja: runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Un Samuēls sacīja: vai tas tā nav? Kad tu biji mazs savās acīs, tad tu Israēla ciltīm esi palicis par galvu, un Tas Kungs tevi ir svaidījis Israēlim par ķēniņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Un Tas Kungs tevi ir sūtījis uz ceļu un sacījis: ej un izdeldi tos grēciniekus, tos Amalekiešus, un karo pret tiem, līdz kamēr tu tos visai(pilnīgi) izdeldi; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Kāpēc tad tu Tā Kunga balsij neesi klausījis, bet uz laupīšanu devies un darījis, kas Tam Kungam nepatīk?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Tad Sauls sacīja uz Samuēli: es jau Tā Kunga balsij esmu klausījis un gājis to ceļu, kur Tas Kungs mani sūtījis, un Agagu, Amalekiešu ķēniņu, esmu atvedis un Amalekiešus izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Bet tie ļaudis no tā laupījuma ir ņēmuši avis un vēršus, kas tie labākie bija no tā izdeldējamā, Tam Kungam, tavam Dievam, upurēt Gilgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Bet Samuēls sacīja: vai tad Tam Kungam tīk dedzināmi vai kaujami upuri vairāk nekā paklausīšana Tā Kunga balsij? Redzi, paklausība ir labāka nekā upuris, un uzmanība ir labāka nekā aunu tauki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Jo nepaklausība ir kā zīlēšanas grēks, un patgalvība ir elkadievība un dievekļu kalpošana. Tādēļ kā tu Tā Kunga vārdu esi atmetis, tā Viņš atkal tevi ir atmetis, vairs nebūt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Tad Sauls sacīja uz Samuēli: es esmu grēkojis, ka esmu pārkāpis Tā Kunga pavēli un tavus vārdus, jo es bijājos tos ļaudis un paklausīju viņu balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Un nu lūdzams piedod man manus grēkus un griezies ar mani atpakaļ, ka es To Kungu piesaucu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Bet Samuēls sacīja uz Saulu: es ar tevi negriezīšos atpakaļ; tāpēc ka tu Tā Kunga vārdu esi atmetis, Tas Kungs arī tevi atmetis, ka tev nebūs ķēniņam būt pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Kad nu Samuēls griezās aiziet, tad Sauls satvēra viņa svārku stūri, un tas plīsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Tad Samuēls uz to sacīja: Tas Kungs šodien Israēla valstību no tevis ir noplēsis un tavam tuvākam devis, kas ir labāks nekā tu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Un arī Israēla Patvērums nemelo nedz nožēlo, jo Viņš nav cilvēks, ka Viņam kas būtu žēl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Tad viņš sacīja: es esmu grēkojis; nu tad godā mani jel priekš manu ļaužu vecajiem un Israēla priekšā, un griezies ar mani atpakaļ, ka es To Kungu, tavu Dievu, pielūdzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Tad Samuēls griezās atpakaļ Saulam līdz, un Sauls pielūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Un Samuēls sacīja: atvediet man Agagu, Amalekiešu ķēniņu. Un Agags gāja pie viņa jautri un Agags sacīja: tiešām, nāves rūgtums atstājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Tad Samuēls sacīja: tā kā tavs zobens sievām bērnus laupījis, tā lai tava māte pār visām sievām paliek bez bērniem. Un Samuēls sacirta Agagu gabalos Tā Kunga priekšā Gilgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Un Samuēls gāja uz Rāmatu, un Sauls gāja savā namā uz Saula Ģibeju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Un Samuēls Saulu vairs neredzēja līdz savas miršanas dienai. Taču Samuēls bija noskumis par Saulu, un ka Tam Kungam bija žēl, ka Viņš Saulu Israēlim bija cēlis par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Un Tas Kungs sacīja uz Samuēli: cik ilgi tu žēlojies par Saulu, kad Es to esmu atmetis, ka tam nebūs Israēlim būt par ķēniņu? Pildi savu ragu ar eļļu un noej; Es tevi sūtīšu pie Isajus, tā Bētlemieša, jo Es no viņa dēliem Sev esmu izredzējis ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Bet Samuēls sacīja: kā lai es eju? Jo Sauls to dzirdēs un mani nokaus. Tad Tas Kungs sacīja: ņem vienu teļu līdz un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Es esmu nācis Tam Kungam upurēt. Un aicini Isaju pie tā upura, tad Es tev darīšu zināmu, ko tev būs darīt, un tev būs Man to svaidīt, ko Es tev noteikšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Un Samuēls darīja, ko Tas Kungs bija runājis, un nāca uz Bētlemi. Tad tās pilsētas vecaji drebēdami viņam gāja pretī un sacīja: vai tu nāci ar mieru?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Un viņš sacīja: ar mieru; es esmu nācis Tam Kungam upurēt. Svētījaties un nāciet ar mani pie tā upura. Un viņš svētīja Isaju un viņa dēlus un tos aicināja pie tā upura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Un notikās, kad tie nāca, tad viņš uzlūkoja Elijabu un domāja: tiešām, šis ir Tā Kunga priekšā Viņa svaidītais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Bet Tas Kungs sacīja uz Samuēli: “Neuzlūko viņa ģīmi nedz viņa lielo garumu, jo Es viņu esmu atmetis. Jo tas nav tā, kā cilvēki redz. Jo cilvēks redz, kas priekš acīm, bet Tas Kungs uzlūko sirdi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Tad Isajus aicināja Abinadabu, un tam lika iet Samuēla priekšā; bet viņš sacīja: arī šo Tas Kungs nav izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Tad Isajus Šamum lika nākt priekšā. Bet viņš sacīja: arī šo Tas Kungs nav izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Tā Isajus saviem septiņiem dēliem lika nākt Samuēla priekšā, bet Samuēls sacīja uz Isaju: Tas Kungs nevienu no šiem nav izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Un Samuēls sacīja uz Isaju: vai šie tie jaunekļi visi? Un viņš sacīja: Tas jaunākais vēl atliek, un redzi, viņš gana avis. Tad Samuēls sacīja uz Isaju: nosūti un atvedi viņu šurp; jo mēs neapsēdīsimies, kamēr viņš nebūs atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Tad viņš nosūtīja un to atveda. Un tas bija sarkaniem vaigiem, skaistām acīm un jauku ģīmi. Tad Tas Kungs sacīja: celies un svaidi to, jo tas ir tas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Tad Samuēls ņēma savu eļļas ragu un to svaidīja viņa brāļu vidū. Un Tā Kunga Gars nāca pār Dāvidu no šīs dienas un joprojām. Un Samuēls cēlās un nogāja uz Rāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Un Tā Kunga Gars atkāpās no Saula, un viņu biedināja ļauns gars no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Tad Saula kalpi uz to sacīja: redzi jel, ļauns gars no Dieva tevi biedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Lai saka mūsu kungs uz saviem kalpiem, kas tavā priekšā stāv, lai tie meklē kādu vīru, kas māk spēlēt uz koklēm, un kad tas ļaunais gars no Dieva pār tevi nāk, tad lai viņš ar savu roku spēlē, tad tev paliks labāki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Tad Sauls sacīja uz saviem kalpiem: lūkojiet man jel pēc tāda vīra, kas labi māk spēlēt, un atvediet to pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Tad viens no viņa sulaiņiem atbildēja un sacīja: raugi, es esmu redzējis vienu Isajus dēlu Bētlemē, tas māk labi spēlēt un ir spēcīgs varonis un karavīrs un gudrs vārdos un skaists no auguma, un Tas Kungs ir ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Tad Sauls sūtīja vēstnešus pie Isajus un tam sacīja: sūti pie manis savu dēlu Dāvidu, kas ir pie avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Tad Isajus ņēma ēzeli ar maizi un trauku vīna un vienu kazlēnu, un to sūtīja Saulam caur sava dēla Dāvida roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Tā Dāvids nāca pie Saula un stāvēja viņa priekšā, un tas viņu ļoti iemīlēja, un viņš tam bija par bruņu nesēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Un Sauls sūtīja pie Isajus un lika sacīt: lai jel Dāvids paliek pie manis, jo viņš ir žēlastību atradis manās acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Un notikās, kad gars no Dieva nāca pār Saulu, tad Dāvids ņēma kokles un spēlēja ar savu roku: tad Sauls atspirga un tam palika labāki, un tas ļaunais gars no viņa atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Un Fīlisti sapulcināja savu spēku uz karu un sapulcējās iekš Sohus, vienā Jūda cilts pilsētā un apmeta savu lēģeri starp Sohu un Azeku Eses-Damimā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Bet Sauls un Israēla vīri sapulcējās un apmetās ozolu ielejā un taisījās karot pret Fīlistiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Un Fīlisti stāvēja uz kalna viņā pusē, un Israēla ļaudis stāvēja uz kalna šai pusē, un ieleja bija viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Tad viens stiprinieks izgāja no Fīlistu lēģera, ar vārdu Goliats no Gatas; viņa garums bija sešas olektis un viens sprīdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Un tam bija vara cepure uz galvas un tam bija zvīņainas krūšu-bruņas un, tas krūšu bruņu svars bija pieci tūkstoši sēķeļu vara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Un lielu bruņas no vara ap lieliem, un vara šķēps uz pleciem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Un viņa šķēpa kāts bija kā riestava un viņa šķēpa asmens bija no sešsimt sēķeliem dzelzs, un tas bruņu nesējs gāja viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Šis nu stāvēja un sauca uz Israēla pulkiem un uz tiem sacīja: kāpēc jūs gribat iziet un stāties uz karu? Vai es neesmu Fīlists un jūs Saula kalpi? Izmeklējiet no sevis vienu, kas pie manis nāk lejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Ja tas ar mani varēs kauties un mani nokaus, tad mēs jums gribam būt par kalpiem, bet ja es viņu pārvaru un viņu kauju, tad jūs būsiet mums par kalpiem un mums kalposiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Un tas Fīlists sacīja: es šodien Israēla pulkus esmu lamājis; dodiet man vienu vīru, ka mēs viens ar otru cīkstamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Kad nu Sauls un viss Israēls šos Fīlista vārdus dzirdēja, tad tie iztrūcinājās un bijās ļoti. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Dāvids nu bija dēls tam Efratiešam no Jūda Bētlemes, ar vārdu Isajus; tam bija astoņi dēli, un Saula laikā tas jau bija vecs vīrs, jau labi gados.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Un Isajus trīs vecākie dēli bija karā gājuši Saulam līdz, un viņa triju dēlu vārdi, kas karā gāja, bija: Elijabs, tas pirmdzimtais, un viņa otrais, Abinadabs, un tas trešais Šamus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Un Dāvids bija tas jaunākais; un tie trīs vecākie Saulam bija gājuši līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Bet Dāvids gāja un nāca no Saula, sava tēva avis ganīt Bētlemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Bet tas Fīlists izgāja rītos un vakaros un rādījās tur četrdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Tad Isajus sacīja uz savu dēlu Dāvidu: ņem jel priekš saviem brāļiem vienu ēfu no šīm ceptām vārpām un šās desmit maizes un steidzies lēģerī pie saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Bet šos desmit sierus nones tam virsniekam par tūkstoš, un apmeklē savus brāļus, kā tiem klājās, un ņem vienu zīmi no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Bet Sauls un šie un visi Israēla vīri bija ozolu ielejā, ar Fīlistiem karodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Tad Dāvids cēlās agri un atstāja avis pie gana un ņēma (tās lietas) un nogāja, kā Isajus viņam bija pavēlējis, un nāca pie tiem savestiem lēģera ratiem, un tas karaspēks izgāja uz kaušanos un sacēla kara troksni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Un Israēlieši un Fīlisti nostājās uz kaušanos, pulks pret pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Tad Dāvids nolika tos traukus pie tā rīku sarga un skrēja pie tiem karapulkiem un nāca un apsveicināja savus brāļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Kad nu viņš vēl ar tiem runāja, redzi, tad nāca tas stiprinieks, vārdā Goliats, tas Fīlists no Gatas, no Fīlistu karapulkiem un runāja tos pašus vārdus, un Dāvids to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Bet visi Israēla vīri, kad tie šo vīru redzēja, tad tie priekš viņa bēga un bijās ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Un Israēla vīri sacīja: vai jūs to vīru esat redzējuši, kas te nāk? Viņš nāk Israēli lamāt. Un notiks, to vīru, kas šo kaus, ķēniņš darīs ļoti bagātu un tam dos savu meitu par sievu un atlaidīs viņa tēva namam nodošanas iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Tad Dāvids runāja uz tiem vīriem, kas pie viņa stāvēja, un sacīja: kas tam vīram būs, kas šo Fīlistu kaus un novērsīs kaunu no Israēla? Jo kas viņš tāds, tas Fīlists, tas neapgraizītais, ka tas tā dzīvā Dieva karapulkus lamā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Tad tie ļaudis viņam teica tos pašus vārdus un sacīja: tā un tā tam vīram darīs, kas viņu nokaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Bet Elijabs, viņa vecākais brālis, viņu dzirdēja ar tiem vīriem runājam, un Elijabs apskaitās par Dāvidu un sacīja: kāpēc tad tu esi atnācis? Un pie kā tu to mazo avju pulciņu tuksnesī esi pametis? Es gan zinu tavu lielību un tavu sirds blēdību, jo tu esi nācis kaušanos redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Tad Dāvids sacīja: ko tad nu es esmu darījis? Vai man nav brīvi runāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Un viņš griezās no tā pie cita un sacīja tos pašus vārdus. Un tie ļaudis tam atbildēja tā kā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Kad nu šie vārdi tapa dzirdēti, ko Dāvids runāja, un Saulam tapa sacīti, tad viņš to lika atvest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Un Dāvids sacīja uz Saulu: lai nevienam sirds nezūd viņa pēc. Tavs kalps noies un kausies ar šo Fīlistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Bet Sauls sacīja uz Dāvidu: tu nevari noiet pret šo Fīlistu, ar viņu kauties. Jo tu esi zēns un viņš ir karavīrs no savas jaunības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Tad Dāvids sacīja uz Saulu: tavs kalps ganīja sava tēva avis, tad nāca lauva un lācis un nonesa avi no ganāmā pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Un es tam dzinos pakaļ un to kāvu un izpestīju (to avi) no viņa rīkles. Kad viņš nu pret mani cēlās, tad es viņu grābu pie bārdas un to situ un nokāvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Tavs kalps ir gan lauvu, gan lāci nokāvis; tāpat būs šis neapgraizītais Fīlists, tā kā viens no tiem; jo viņš tā dzīvā Dieva karapulkus ir lamājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Un Dāvids sacīja: Tas Kungs, kas mani pestījis no lauvas un no lāča, mani arī atpestīs no šā Fīlista rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Tad Sauls sacīja uz Dāvidu: ej tad, lai Tas Kungs tev palīdz. Un Sauls apģērba Dāvidu ar savām paša drēbēm un lika vara cepuri uz viņa galvu un to apģērba ar krūšu bruņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Un Dāvids apjoza viņa zobenu pār savām drēbēm un sāka staigāt, jo viņš vēl to nebija ieradis. Un Dāvids sacīja uz Saulu: tā es nevaru iet, jo es to vēl neesmu ieradis. Un Dāvids to nolika no sevis nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Un viņš ņēma savu zizli rokā un izlasījās piecus gludus oļus no upes un tās lika tai gana tarbā, kas viņam bija, proti tai kulē, un viņa linga bija viņa rokā. Tā tas gāja tam Fīlistam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Un tas Fīlists nāca Dāvidam arvien tuvāk, un viņa bruņu nesējs viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Kad nu tas Fīlists skatījās un Dāvidu redzēja, tad viņš to izsmēja, jo tas bija jauneklis sarkaniem vaigiem un skaistu ģīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Un tas Fīlists sacīja uz Dāvidu: vai es esmu suns, ka tu ar koku pie manis nāci? Un tas Fīlists lādēja Dāvidu pie saviem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Un tas Fīlists sacīja uz Dāvidu: nāc šurp pie manis, es tavu miesu došu putniem apakš debess un zvēriem laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Bet Dāvids sacīja uz to Fīlistu: tu nāci pie manis ar zobenu un šķēpu un priekšturamām bruņām, bet es nāku pie tevis Tā Kunga Cebaot vārdā, kas ir Israēla karapulku Dievs, ko tu esi zaimojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Šodien Tas Kungs tevi dos manā rokā, ka es tevi nokauju un tavu galvu no tevis atņemu un Fīlistu lēģera maitas dodu putniem apakš debess un zvēriem virs zemes, un visa pasaule atzīs, ka Israēlim ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Un visi šie pulki atzīs, ka Tas Kungs neizglābj ar zobenu un šķēpu: jo tas karš pieder Tam Kungam, Tas jūs dos mūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Un notikās, kad nu tas Fīlists cēlās un nāca un Dāvidam tuvojās, tad Dāvids steidzās un skrēja uz tiem karapulkiem, tam Fīlistam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Un Dāvids bāza roku tarbā un izņēma vienu oli un meta ar lingu un iesvieda tam Fīlistam pašā pierē, tā ka tas akmens viņa pierē ieskrēja, un tas krita uz savu vaigu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tā Dāvids pārvarēja to Fīlistu ar lingu un ar oli, un kāva to Fīlistu un to nokāva, bet Dāvidam zobena nebija rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Tad Dāvids pieskrēja un piestājās pie tā Fīlista un ņēma viņa zobenu un to izvilka no makstīm un to nokāva un tam ar to nocirta galvu. Kad nu Fīlisti redzēja, ka viņu varenais bija miris, tad tie bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Un Israēla un Jūda vīri cēlās un gavilēja un dzinās Fīlistiem pakaļ, kamēr nāk tai ielejā un līdz pašiem Ekronas vārtiem; un Fīlistu nokautie krita uz Zaārim ceļa un līdz Gatai un līdz Ekronai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Un Israēla bērni griezās atpakaļ no Fīlistu dzīšanas un aplaupīja viņu lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Un Dāvids ņēma tā Fīlista galvu un to nonesa uz Jeruzālemi, bet viņa bruņas viņš nolika savā teltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Bet kad Sauls redzēja Dāvidu izejam pret to Fīlistu, tad tas uz Abneru, to kara lielkungu, sacīja: kam dēls ir šis jauneklis, Abner? Tad Abners sacīja: tik tiešām kā tava dvēsele dzīvo, ķēniņ, to es nezinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Tad ķēniņš sacīja: vaicā jel, kam dēls šis jauneklis ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Kad nu Dāvids atpakaļ griezās no tā Fīlista kaušanas, tad Abners viņu ņēma un veda Saula priekšā, un tā Fīlista galva bija viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Un Sauls uz to sacīja: kam dēls tu esi, puisi? Dāvids sacīja: tava kalpa Isajus, tā Bētlemieša, dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kad nu viņš bija beidzis ar Saulu runāt, tad Jonatāna sirds ar Dāvida sirdi sadraudzējās, un Jonatāns viņu iemīlēja kā savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Un Sauls viņu ņēma tai pašā dienā un tam neļāva tēva namā pāriet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Un Jonatāns derēja derību ar Dāvidu, tāpēc ka viņš to mīlēja kā savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Un Jonatāns noņēma savu mēteli, kas viņam bija, un to deva Dāvidam, arī savas drēbes, kā arī savu zobenu un savu stopu un savu jostu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Un Dāvids izgāja visur, kurp Sauls viņu sūtīja, un turējās gudri, un Sauls to iecēla pār tiem karavīriem, un tas patika labi visiem ļaudīm, arī Saula kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Un notikās, kad tie nu pārnāca, un Dāvids atpakaļ griezās no tā Fīlista kaušanas, tad tās sievas no visām Israēla pilsētām dziedot un dejot izgāja ķēniņam Saulam pretī ar bungām, ar prieku un ar spēlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Un tās sievas diedamas dziedāja un sacīja: Sauls tūkstošus nokāvis, bet Dāvids desmit tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Tad Sauls ļoti apskaitās un šī valoda viņam nepatika un viņš sacīja: tie Dāvidam devuši desmit tūkstošus un man tie devuši tūkstošus; tiešām valstība vēl viņam tiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Un Sauls skaudīgi skatījās uz Dāvidu no tās dienas un joprojām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Un notikās otrā dienā, kad ļauns gars no Dieva Saulam uznāca, un tas muldēja savā pašā namā, tad Dāvids spēlēja ar savu roku, kā ikdienas, un Saulam bija šķēps rokā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Un Sauls meta to šķēpu un domāja: es Dāvidu pie sienas noduršu. Bet Dāvids novērsās divreiz no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Un Sauls bijās no Dāvida, jo Tas Kungs bija ar viņu un bija no Saula atstājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Un Sauls viņu atstādināja no sevis un to darīja par virsnieku pār tūkstoti; un tas izgāja un iegāja ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Un Dāvids turējās gudri uz visiem saviem ceļiem, un Tas Kungs bija ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Kad nu Sauls redzēja, ka tas ļoti gudri turējās, tad tas no viņa bijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Bet viss Israēls un Jūda mīlēja Dāvidu, jo tas izgāja un iegāja viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Un Sauls sacīja uz Dāvidu: redzi, es tev došu savu vecāko meitu Merabu par sievu; esi man tikai sirdīgs vīrs un vedi Tā Kunga karus. Jo Sauls domāja: mana roka nebūs pret viņu, bet lai Fīlistu roka ir pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Bet Dāvids sacīja uz Saulu: kas es esmu, un kas ir mana dzīves kārta un mana tēva radi iekš Israēla, ka man būs palikt ķēniņam par znotu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Bet kad tas laiks nāca, ka Meraba, Saula meita, Dāvidam bija jādod, tad tā Adriēlim no Meolas tapa dota par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Bet Mikale, Saula meita, mīlēja Dāvidu. Kad tas Saulam tapa teikts, tad tas viņam bija pa prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Un Sauls sacīja: to es viņam došu, lai tā viņam ir par valgu, un Fīlistu roka nāk pār viņu. Tāpēc Sauls sacīja uz Dāvidu: ar to otru tu man šodien būsi par znotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Un Sauls pavēlēja saviem kalpiem: runājiet ar Dāvidu klusiņām un sakāt: redzi, ķēniņam ir labs prāts uz tevi, un visi viņa kalpi tevi mīļo, tad palieci ķēniņam par znotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Un Saula kalpi runāja šos vārdus priekš Dāvida ausīm. Bet Dāvids sacīja: vai tā ir maza lieta priekš jūsu acīm, ķēniņam palikt par znotu? Un es taču esmu nabags un zems vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Un Saula kalpi viņam to stāstīja sacīdami: tā un tā Dāvids ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Tad Sauls sacīja: sakāt Dāvidam tā: ķēniņam negribās kroņa naudas, bet simts Fīlistu priekšādas, lai atriebjamies pie ķēniņa ienaidniekiem. Jo Sauls domāja Dāvidu izdeldēt caur Fīlistu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Tad viņa kalpi Dāvidam šos vārdus sacīja, un Dāvidam labi patika, ķēniņam palikt par znotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Bet tās dienas vēl nebija pagalam, tad Dāvids cēlās un nogāja ar saviem vīriem un nokāva no Fīlistiem divsimt vīrus. Dāvids atnesa viņu priekšādas, un tās ķēniņam tapa nodotas pilnā skaitā, ka viņš taptu ķēniņa znots. Tad Sauls viņam deva savu meitu Mikali par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Un Sauls redzēja un nomanīja, ka Tas Kungs bija ar Dāvidu, un Mikale, Saula meita, viņu mīlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Tad Sauls no Dāvida vēl vairāk bijās un Sauls ienīdēja Dāvidu, kamēr viņš dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Kad nu Fīlistu lielkungi izgāja (karot), tad notikās viņiem izejot, ka Dāvids bija gudrāks nekā visi Saula kalpi, tā ka viņa vārds kļuva ļoti cienīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Tad Sauls runāja ar savu dēlu Jonatānu un ar visiem saviem kalpiem, ka tie Dāvidu nokautu. Bet Jonatānam, Saula dēlam, bija labs prāts uz Dāvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Un Jonatāns Dāvidam to teica sacīdams: mans tēvs Sauls tevi meklē nokaut; nu tad, sargies jel rītu un paslēpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Bet es iziešu un stāvēšu savam tēvam sānis laukā, kur tu būsi, un runāšu ar savu tēvu tevis pēc un redzēšu, kas tur būs, un tev to sacīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Tad Jonatāns runāja labu no Dāvida uz savu tēvu Saulu un uz to sacīja: lai ķēniņš neapgrēkojās pret savu kalpu Dāvidu, jo viņš pret tevi nav grēkojis, un viņa darbi tev nāk varen ļoti par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Jo viņš savu dzīvību ir licis savā rokā un to Fīlistu kāvis, un Tas Kungs ir devis lielu pestīšanu visam Israēlim. To tu esi redzējis un priecājies, kāpēc tad tu gribētu apgrēkoties pret nenoziedzīgām asinīm, Dāvidu bez vainas nokaudams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Un Sauls paklausīja Jonatāna balsij, un Sauls nozvērējās: tik tiešām ka Tas Kungs dzīvo, tam nebūs nokautam tapt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Un Jonatāns aicināja Dāvidu, un Jonatāns sacīja Dāvidam visus šos vārdus. Un Jonatāns veda Dāvidu Saula priekšā, un viņš bija šī priekšā kā citkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Tad atkal karš cēlās, un Dāvids izgāja un karoja ar Fīlistiem un tos kāva ar lielu kaušanu, un tie bēga viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Bet ļauns gars no Tā Kunga nāca pār Saulu, un tas sēdēja savā namā, un viņa šķēps bija viņa rokā, un Dāvids spēlēja uz stīgām ar roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Tad Sauls gribēja Dāvidu nodurt ar to šķēpu pie sienas, bet šis novērsās no Saula, un tas šķēps ieskrēja sienā; un Dāvids bēga un izbēga tai pašā naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Tad Sauls sūtīja vīrus Dāvida namā viņu sargāt un rītu nokaut. Bet Mikale, viņa sieva, to viņam teica un sacīja: ja tu šo nakti savu dzīvību neglābsi, tad tu rītu tapsi nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Un Mikale nolaida Dāvidu pa logu zemē, un tas nogāja un bēga un izglābās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Un Mikale ņēma vienu tēlu un to lika uz gultu, un vienu kazu spalvas audumu tam lika galvgalā un to apsedza ar deķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Un Sauls sūtīja vīrus, Dāvidu atvest, bet tā sacīja: viņš ir slims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Tad Sauls sūtīja vīrus, Dāvidu aplūkot un sacīja: atnesiet to ar gultu pie manis, ka tas top nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Kad nu tie vīri ienāca, redzi, tad tēls bija gultā, un kazu spalvas audums viņa galvgalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Tad Sauls sacīja uz Mikali: kāpēc tu mani tā esi pievīlusi un manu ienaidnieku atlaidusi, ka tas ir aizbēdzis? Bet Mikale sacīja uz Saulu: viņš uz mani sacīja: atlaid mani, kāpēc man tevi būs nokaut?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Tā Dāvids bēga un izglābās un nāca pie Samuēla uz Rāmatu, un stāstīja tam visu, ko Sauls tam bija darījis, un gāja līdz ar Samuēli un palika Najotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Un Saulam teica un sacīja: redzi, Dāvids ir Najotā pie Rāmatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Tad Sauls sūtīja vīrus, Dāvidu atvest. Kad tie nu redzēja vienu praviešu pulku runājam praviešu vārdus un Samuēli pie viņiem stāvam par uzraugu, tad Dieva Gars nāca par Saula vīriem, ka tie arī praviešu vārdus runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Un kad tas Saulam tapa sacīts, tad viņš sūtīja citus vīrus, - un arī tie runāja praviešu vārdus. Tad Sauls sūtīja vēl trešos vīrus, - tie arīdzan runāja praviešu vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Tad viņš arī pats gāja uz Rāmatu un nāca pie tās lielās akas, kas bija pie Sehus, un vaicāja sacīdams: kur ir Samuēls un Dāvids? Un viņam sacīja: redzi, Najotā pie Rāmatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Tad viņš gāja uz turieni, uz Najotu pie Rāmatas. Un Dieva Gars nāca arī uz viņu un tas gāja praviešu vārdus runādams, kamēr viņš nāca uz Najotu pie Rāmatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Un arī viņš tur novilka savas drēbes un runāja praviešu vārdus Samuēla priekšā, un viņš krita kails pie zemes cauru dienu un cauru nakti. Tāpēc saka: vai Sauls arī starp praviešiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Tad Dāvids bēga no Najotas pie Rāmatas, un nāca un sacīja Jonatāna priekšā: ko es esmu darījis, kas ir mans noziegums un kas ir mani grēki tava tēva priekšā, ka viņš manu dzīvību meklē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Tad tas uz viņu sacīja: lai Dievs pasargā, tu nemirsi! Redzi, mans tēvs nedara ne lielu ne mazu lietu, ko viņš man papriekš nesacītu, kādēļ tad mans tēvs šo lietu priekš manis būtu apslēpis? Tas tā nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Tad Dāvids turklāt vēl zvērēja un sacīja: tavs tēvs labi zina, ka es žēlastību esmu atradis priekš tavām acīm, tāpēc viņš domā, lai Jonatāns no tā nekā nezina, ka tas par to nenoskumstas. Bet patiesi, tik tiešām kā Tas Kungs dzīvo un tava dvēsele dzīvo, viens solis vien ir starp mani un nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Un Jonatāns sacīja uz Dāvidu: ko tava dvēsele vēlās, to es tev darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Un Dāvids sacīja uz Jonatānu: redzi, rītu ir jauns mēnesis, un man būtu ar ķēniņu pie galda jāsēž un jāēd, tad nu palaid mani, ka es laukā apslēpjos līdz trešās dienas vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Ja tavs tēvs pēc manis vaicās, tad saki: Dāvids mani lūgdams lūdzis, ka varētu steigšus noiet uz savu pilsētu Bētlemi, jo tur ir tas gadskārtīgais upuris visiem tiem radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ja nu viņš tā sacīs: tas ir labi, - tad tavam kalpam būs miers. Bet ja viņš par to apskaistās, tad tu vari zināt, ka viņš ļaunu apņēmies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Dari tad žēlastību pie sava kalpa, jo tu ar savu kalpu Tā Kunga derību esi derējis. Bet ja kāds noziegums ir pie manis, tad nokauj tu mani, kāpēc tu mani vēl gribētu vest pie sava tēva?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Tad Jonatāns sacīja: lai tas ne mūžam tev nenotiek, ja es tiešām atzītu, ka mans tēvs būtu apņēmies tev ļaunu darīt, ka es tev to nesacītu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Tad Dāvids sacīja uz Jonatānu: kas man to sacīs, kad tavs tēvs tev bargi atbildēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Tad Jonatāns sacīja uz Dāvidu: nāc, ejam laukā. Un tie izgāja abi divi uz lauku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Tad Jonatāns sacīja uz Dāvidu: Kungs, Israēla Dievs, ja es no sava tēva būšu izklausījis ap šo laiku rītu vai parītu, un redzi, kad tas ir labi priekš Dāvida, un es tad pie tevis nesūtu un tev no tā ziņas nedodu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Tad lai Tas Kungs Jonatānam šā un tā dara. Bet ja mans tēvs ko ļaunu pret tevi ir apņēmies, tad es tev par to arī ziņu došu, un tevi palaidīšu, ka tu ar mieru vari aiziet. Un lai tad Tas Kungs ir ar tevi, kā Viņš ir bijis ar manu tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Un kaut tu, kamēr es vēl dzīvoju, kaut tu pie manis parādītu Tā Kunga žēlastību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Un kad es mirstu, ne mūžam neatrautu savu žēlastību no mana nama, arī tad ne, kad Tas Kungs Dāvida ienaidniekus visus no zemes izdeldēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Tā Jonatāns derēja derību ar Dāvida namu. Un Tas Kungs ir piemeklējis Dāvida ienaidniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Un Jonatāns Dāvidu vēl reiz apzvērināja viņu mīlēdams, jo tas viņu mīlēja, itin kā savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Un Jonatāns uz viņu sacīja: rītu ir jauns mēnesis, tad pēc tevis vaicās, jo tava vieta, kur tu sēdi, būs tukša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Bet trešā dienā nonāc drīz un ej uz to vietu, kur tu biji paslēpies darba dienā, un apsēdies pie Azel akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Tad es trīs bultas šaušu tam sānis, tā kā mērķī šaudams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Un redzi, es sūtīšu puisi (sacīdams): ej, meklē tās bultas. Ja es uz to puisi sacīšu: redzi, tās bultas ir šaipus tevis, dabū tās, - tad nāc, jo tev ir miers un nav nekas, tik tiešām kā Tas Kungs dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Bet ja es tā uz to puisi sacīšu: redzi, tās bultas ir tavā priekšā viņā pusē, - tad ej, jo Tas Kungs tev ir licis iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Bet par to lietu, par ko es un tu esam runājuši, redzi, lai Tas Kungs ir starp mani un tevi mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Tad Dāvids paslēpās laukā, un kad jauns mēnesis bija, tad ķēniņš apsēdās pie galda ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kad nu ķēniņš apsēdās savā vietā, to brīdi kā ar vienu pie sienas, tad Jonatāns nāca, un Abners apsēdās Saulam sānis, bet Dāvida vieta palika tukša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Bet Sauls nesacīja tai dienā nekā, jo viņš domāja: tam kas ir noticis, ka tas nav šķīsts, - viņš nebūs šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Bet otrā jauna mēneša dienā Dāvida vieta palika atkal tukša. Tad Sauls sacīja uz savu dēlu Jonatānu: kāpēc Isajus dēls pie galda nav nācis nedz vakar, nedz šodien?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Tad Jonatāns Saulam atbildēja: Dāvids mani lūgdams lūdzis, ka varētu iet uz Bētlemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Un sacīja: atlaid mani lūdzams, jo mūsu radiem ir upuris tai pilsētā, un mans brālis man pats to ir pavēlējis; nu tad, ja es žēlastību esmu atradis tavās acīs, tad dod man lūdzams vaļu, savus brāļus apmeklēt. Tādēļ viņš nav nācis pie ķēniņa galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Tad Sauls apskaitās pret Jonatānu un uz to sacīja: tu netiklais stūrgalvi, vai es nezinu, ka tu to Isajus dēlu esi izredzējis sev par kaunu un tavai netiklai mātei par kaunu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Jo cik ilgi Isajus dēls virs zemes dzīvos, ne tu, nedz tava valstība nepastāvēs. Tad nu nosūti un dabū man viņu šurp, jo viņam jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Tad Jonatāns savam tēvam Saulam atbildēja un uz to sacīja: kāpēc tam būs mirt? Ko viņš ir darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Tad Sauls meta ar šķēpu pēc viņa, ka to nodurtu. Un Jonatāns nomanīja, ka viņa tēvs pilnīgi bija apņēmies, Dāvidu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Tad Jonatāns cēlās no galda ar dusmām un neēda tai otrā jauna mēneša dienā nekā, jo viņam sirds ēdās par Dāvidu, tāpēc ka viņa tēvs to bija negodā licis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Un rītā Jonatāns izgāja laukā, kur ar Dāvidu bija norunāts, un mazs zēns bija viņam līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Un viņš sacīja uz savu puisi: teci, meklē jel tās bultas, ko es šaušu. Tad tas puisis tecēja, un viņš šāva vienu bultu pāri pār to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Kad nu tas puisis uz to vietu nāca, kur Jonatāns to bultu bija aizšāvis, tad Jonatāns tam puisim sauca pakaļ un sacīja: vai tā bulta nav tavā priekšā viņā pusē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Atkal Jonatāns tam puisim sauca pakaļ: steidzies čakli, nestāvi! Tad tas puisis Jonatānam lasīja tās bultas un nāca atkal pie sava kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Bet tas puisis nezināja nekā; Jonatāns tikai un Dāvids zināja to lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Un Jonatāns deva tos rīkus savam puisim, un uz to sacīja: ej, nes tos pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Tā tas puisis nogāja, un Dāvids cēlās no dienasvidus puses un metās uz savu vaigu pie zemes un klanījās trīs reiz\', un tie skūpstījās un raudāja abi divi, bet Dāvids jo stipri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Tad Jonatāns sacīja uz Dāvidu: ej ar mieru! Ko mēs abi iekš Tā Kunga vārda esam zvērējuši sacīdami: Tas Kungs lai ir starp mani un tevi, un starp manu dzimumu un tavu dzimumu, - tas lai tā paliek mūžīgi. Un viņš cēlās un aizgāja, un Jonatāns nāca pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Tad Dāvids nāca uz Nobu pie priestera Aķimeleka, un Aķimeleks gāja Dāvidam drebēdams pretī un uz to sacīja: kāpēc tu nāci viens pats, un neviena tev nav līdz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Tad Dāvids sacīja uz priesteri Aķimeleku: ķēniņš man kādu lietu ir pavēlējis un uz mani sacījis: lai neviens nekā nezin no tās lietas, par ko es tevi esmu sūtījis, un ko es tev esmu pavēlējis; un saviem puišiem es esmu pavēlējis, tai un tai vietā uz mani gaidīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Nu tad, kas tev ir pie rokas? Dod man kādas piecas maizes, vai, kas atrodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Tad tas priesteris Dāvidam atbildēja un sacīja: še man nav ikdienišķas maizes pie rokas, bet vien tās svētās maizes; ja tikai tie puiši no sievām būs noturējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Tad Dāvids tam priesterim atbildēja un uz to sacīja: tiešām, sievas no mums ir nost bijušas vakar un aizvakar, kamēr es izgāju, un to puišu lietas bija svētas. Lai nu tas ceļš gan nav svēts, tomēr tas šodien taps svētīts caur to ieroci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Tad tas priesteris tam deva svētu maizi, tāpēc ka citas maizes tur nebija, kā vien tās priekšliekamās maizes, kas no Tā Kunga vaiga bija atņemtas, ka atkal jaunas taptu uzliktas tai dienā, kad viņas tiek atņemtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Un tur bija viens vīrs no Saula kalpiem tai dienā ieslēgts Tā Kunga priekšā, un viņa vārds bija Doēgs, viens Edomietis, virsnieks pār Saula ganiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Un Dāvids sacīja uz Aķimeleku: vai tavā rokā nav kāds šķēps vai zobens? Jo es nedz savu zobenu nedz savas bruņas neesmu līdzi ņēmis, tāpēc ka ķēniņa lieta bija steidzama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Tad tas priesteris sacīja: Fīlista Goliata zobens, ko tu ozolu ielejā nokāvi, redzi, tas ir še vienā drēbē ietīts aiz efoda; ja tu to gribi, tad ņem, jo te cita nav kā tas vien. Tad Dāvids sacīja: cita tāda nav, dod man to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Un Dāvids cēlās un bēga tai dienā no Saula un nāca pie Aķisa, Gatas ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Tad Aķisa kalpi uz to sacīja: vai šis nav Dāvids, tās zemes ķēniņš? Vai no tā netapa dziedāts ar stabulēm un sacīts: Sauls tūkstošus kāvis, bet Dāvids desmit tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Un Dāvids šos vārdus ņēma pie sirds un bijās ļoti no Aķisa, Gatas ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Tāpēc viņš izlikās ārprātīgs priekš viņu acīm un kā traks apakš viņu rokām kasīja vārtu durvis, un siekalas tam notecēja bārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Tad Aķis sacīja uz saviem kalpiem: raugi, jūs redzat, ka tas vīrs ir traks, kāpēc jūs to pie manis esat atveduši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Vai man traku nav diezgan, ka jūs šo pie manis esat atveduši, manā priekšā trakot, - vai tad tam būs nākt manā namā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Tad Dāvids aizgāja no turienes un bēga uz Adulama alu. Un viņa brāļi to dzirdēja ar visu viņa tēva namu un nonāca pie viņa uz turieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Un pie viņa sapulcinājās visi vīri, kas bija spaidos, un visi, kam bija daudz parādu, un visi, kam bija rūgtums sirdī, un viņš tiem palika par virsnieku, un pie viņa bija pie četrsimt vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Un Dāvids gāja no turienes uz Micpu Moaba zemē, un sacīja uz Moaba ķēniņu: lai jel mans tēvs un mana māte pie jums dzīvo, tiekams es atzīšu, ko Dievs ar mani darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Un viņš tos noveda pie Moaba ķēniņa un tie palika pie tā, kamēr Dāvids mita kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Tad pravietis Gads sacīja uz Dāvidu: nepaliec uz šiem kalniem, ej un paliec Jūda zemē. Tad Dāvids gāja un nāca Areta mežā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Un Sauls dzirdēja, ka Dāvids bija pamanīts ar tiem vīriem, kas pie viņa bija. Un Sauls sēdēja pie Ģibejas apakš kupla koka uz kalna, un viņa šķēps bija viņa rokā, un visi viņa kalpi stāvēja ap viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Tad Sauls sacīja uz saviem kalpiem, kas ap viņu stāvēja: klausiet jel, jūs Benjaminieši, vai Isajus dēls jums visiem dos tīrumus un vīna dārzus, vai viņš jūs visus cels par tūkstošniekiem un par simtniekiem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Ka jūs visi pret mani esat sazvērējušies, un neviena nav, kas priekš manām ausīm būtu sacījis, ka mans dēls derību ir derējis ar Isajus dēlu? Un neviena nav jūsu starpā, kam manis būtu žēl, un kas to priekš manām ausīm būtu teicis, ka mans dēls manu kalpu pret mani pamodinājis, ka tas uz mani glūn, kā tas šodien redzams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Tad Doēgs, tas Edomietis, kas pie Saula kalpiem stāvēja, atbildēja un sacīja: es redzēju Isajus dēlu uz Nobu nākam pie Aķimeleka, Aķitaba dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Tas To Kungu viņa labad vaicāja un tam deva ceļamaizi un tam deva arī Fīlista Goliata zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Tad ķēniņš nosūtīja un lika aicināt Aķimeleku, priestera Aķitaba dēlu, un visu viņa tēva namu, kas priesteri bija Nobā. Un tie nāca visi ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Tad Sauls sacīja: klausi jel, tu Aķitaba dēls! Un tas sacīja: redzi, še es esmu, kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Tad Sauls uz to sacīja: kāpēc jūs pret mani esat sazvērējušies, tu un Isajus dēls, ka tu viņam esi maizes devis un zobenu, un Dievu viņa labad vaicājis, ka viņš pret mani celtos un uz mani glūnētu, kā tas šodien redzams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Tad Aķimeleks ķēniņam atbildēja un sacīja: kurš tad starp visiem taviem kalpiem ir tik uzticīgs, kā Dāvids, paša ķēniņa znots, kas pie tevis var pieiet un tevi klausīt un top godā turēts tavā namā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Vai tad es šodien esmu iesācis Dievu viņa pēc vaicāt? Lai Dievs pasargā! Lai ķēniņš tādu lietu uz savu kalpu negriež nedz uz visu mana tēva namu, jo tavs kalps no visām šīm lietām nekā nezin, ne mazu ne lielu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Bet ķēniņš sacīja: mirt tev jāmirst, Aķimelek, tev un visam tava tēva namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Un ķēniņš sacīja uz tiem sargiem, kas pie viņa stāvēja: griežaties un nokaujiet Tā Kunga priesterus, tāpēc ka viņu roka arīdzan ir ar Dāvidu, un ka tie zinājuši viņu bēgam un man to nav sacījuši. Bet ķēniņa kalpi negribēja savu roku izstiept, Tā Kunga priesterus nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Tad ķēniņš sacīja uz Doēgu: griezies tu un kauj tos priesterus. Tad Doēgs, tas Edomietis, griezās un kāva tos priesterus un nokāva tai diena astoņdesmit un piecus vīrus, kas to nātnu efodu nesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Viņš sita arī Nobu, to priesteru pilsētu, ar zobena asmeni, gan vīrus, gan sievas, gan bērnus, gan zīdāmos, gan vēršus, gan ēzeļus, gan sīkus lopus viņš nokāva ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Tomēr viens no Aķimeleka, Aķitaba dēla, dēliem izbēga, ar vārdu Abjatars, un bēga pie Dāvida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Un Abjatars stāstīja Dāvidam, ka Sauls Tā Kunga priesterus bija nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Tad Dāvids sacīja uz Abjataru: es jau to zināju tai dienā, kad Doēgs, tas Edomietis, tur bija, ka tas Saulam to tiešām atsacīs. Es esmu noziedzīgs pie visām tava tēva nama dvēselēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Paliec pie manis, nebīsties, kas manu dzīvību meklē, tam būs arī tavu dzīvību meklēt, jo pie manis tev būs patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Un Dāvidam teica un sacīja: redzi, Fīlisti karo pret Ķeģilu un aplaupa klonus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Tad Dāvids vaicāja To Kungu un sacīja: vai man būs iet un Fīlistus kaut? Un Tas Kungs sacīja uz Dāvidu: ej, jo tu Fīlistus kausi un izglābsi Ķeģilu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Bet Dāvida vīri uz to sacīja: redzi, mēs bīstamies šeit iekš Jūda: kā mēs varētu iet uz Ķeģilu pret Fīlistu karapulkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Tad Dāvids vaicāja atkal To Kungu, un Tas Kungs tam atbildēja un sacīja: “Celies, noej uz Ķeģilu, jo Es Fīlistus dodu tavā rokā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Tad Dāvids nogāja ar saviem vīriem uz Ķeģilu un karoja pret Fīlistiem un aizdzina viņu lopus un sakāva tos lielā kaušanā. Tā Dāvids atpestīja Ķeģilas iedzīvotājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Bet kad Abjatars, Aķimeleka dēls, uz Ķeģilu bēga pie Dāvida, tad viņš nonāca ar to efodu savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Kad nu Saulam sacīja, ka Dāvids bija nācis uz Ķeģilu, tad Sauls sacīja: Dievs to nodevis manā rokā, jo viņš ir ieslēgts, ka tas nācis pilsētā, kur aizšaujami vārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Tad Sauls sasauca tos ļaudis uz karu, ka tie noietu uz Ķeģilu, Dāvidu ar viņa vīriem aplenkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Kad nu Dāvids nomanīja, ka Sauls šo ļaunumu pret viņu slepeni bija apņēmies, tad viņš sacīja uz priesteri Abjataru: nes to efodu šurp.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Un Dāvids sacīja: Kungs, Israēla Dievs, Tavs kalps to dzirdējis, ka Sauls domā uz Ķeģilu nākt, to pilsētu samaitāt manis dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Vai Ķeģilas namnieki mani nodos viņa rokā? Vai Sauls arī nāks lejā, kā Tavs kalps dzirdējis? Kungs, Israēla Dievs, saki to jel Savam kalpam. Tad Tas Kungs sacīja: viņš nonāks lejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Un Dāvids sacīja: vai tad Ķeģilas namnieki mani un manus vīrus nodos Saula rokā? Tad Tas Kungs sacīja: nodos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Tad Dāvids cēlās ar saviem vīriem, to bija pie sešsimt, un tie izgāja no Ķeģilas un gāja, kur varēdami. Un kad Saulam sacīja, ka Dāvids no Ķeģilas aizbēdzis, tad viņš palika neizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Un Dāvids mita tuksnesī nepieejamās vietās un palika uz kalniem Zifas tuksnesī. Un Sauls to meklēja vienmēr, bet Dievs to nedeva viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Un Dāvids redzēja, ka Sauls bija izgājis, viņa dzīvību meklēt; un Dāvids bija Zifas tuksneša silā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Tad Jonatāns, Saula dēls, cēlās un gāja pie Dāvida silā un stiprināja viņa roku iekš Dieva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Un sacīja uz to: nebīsties, jo mana tēva Saula roka tevi neatradīs, un tu tapsi Israēlim par ķēniņu, un es būšu tas tuvākais pie tevis, un to mans tēvs Sauls arī gan zina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Un tie abi derēja derību Tā Kunga priekšā, un Dāvids palika tai silā, bet Jonatāns gāja uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Tad Zifas ļaudis nogāja pie Saula uz Ģibeju un sacīja: vai Dāvids neslēpjas pie mums silā nepieejamās vietās, uz Aķilas pakalna, kas tuksnesim pa labo roku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Nu tad, ķēniņ, nāc tūdaļ it pēc tava sirds prāta, jo mums pienākas, viņu nodot ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Tad Sauls sacīja: svētīti jūs esat Tam Kungam, ka jūs par mani esat apžēlojušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Ejat jel, ņemiet vēl vērā, skatāties un izlūkojiet viņa vietu, kur viņa pēdas būs, un kas viņu tur ir redzējis; jo man ir sacīts, ka viņš ļoti gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Tāpēc izraugāt un izlūkojiet visas malas, kur viņš slēpjās; tad nāciet atkal pie manis ar īstu vēsti, tad es jums iešu līdz. Un ja viņš šai zemē būs, tad es viņam dzīšos pakaļ starp visiem tūkstošiem iekš Jūda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Tad tie cēlās un nogāja uz Zifu Saulam pa priekšu. Bet Dāvids un viņa vīri turējās Maona tuksneša klajumā, pa labo roku tuksnesim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Un Sauls ar saviem vīriem gāja, viņu meklēt. Bet Dāvidam tapa ziņa dota, un viņš nogāja uz to lielo akmeni un palika Maona tuksnesī. Kad nu Sauls to dzirdēja, tad viņš Dāvidam dzinās pakaļ pa Maona tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Un Sauls gāja šai kalna pusē, un Dāvids ar saviem vīriem viņā kalna pusē. Tad Dāvids steidzās no Saula bēgt, bet Sauls ar saviem vīriem Dāvidu un viņa vīrus aplenca, gribēdams tos sagūstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Bet viens vēstnesis nāca pie Saula sacīdams: steidzies un ej, jo Fīlisti zemē ielauzušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Un Sauls griezās atpakaļ no Dāvida pakaļdzīšanās un gāja pret Fīlistiem; tāpēc šī vieta top nosaukta Zela-Maklekot (šķiršanās akmens).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Un Dāvids aizgāja no turienes un palika Enģedos nepieejamās vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Un notikās, kad nu Sauls no Fīlistiem bija griezies atpakaļ, tad viņam teica un sacīja: redzi, Dāvids ir Enģedu tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Tad Sauls ņēma trīstūkstoš izlasītus vīrus no visa Israēla un gāja meklēt Dāvidu ar viņa vīriem uz tiem mežu kazu kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Un viņš nāca pie tiem avju laidariem ceļmalā; tur bija viena ala, un Sauls tanī iegāja savas kājas apsegt, bet Dāvids un viņa vīri sēdēja alas dibenā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Tad Dāvida vīri uz to sacīja: redzi, šī ir tā diena, par ko Tas Kungs tev ir sacījis: “Redzi, Es tavu ienaidnieku dodu tavā rokā, un tev būs viņam darīt, kā tev tīk.” Un Dāvids cēlās un nogrieza klusiņām vienu stūri no Saula svārkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Bet pēc tam Dāvidam sirds par to lēca, ka viņš to stūri no Saula svārkiem bija nogriezis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Un viņš sacīja uz saviem vīriem: lai Tas Kungs mani no tā pasargā, ka es ko darītu savam kungam, Tā Kunga svaidītam, un savu roku pie viņa pieliktu, - jo viņš ir Tā Kunga svaidītais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Un Dāvids apsauca savus vīrus ar vārdiem un viņiem neļāva pret Saulu celties; un Sauls cēlās no tās alas un gāja pa ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Tad arī Dāvids cēlās un izgāja no alas un sauca Saulam pakaļ un sacīja: mans kungs un ķēniņ! Tad Sauls skatījās atpakaļ. Un Dāvids locīdadamies ar savu vaigu nometās zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Un Dāvids sacīja uz Saulu: kāpēc tu klausi cilvēku vārdiem, kas saka: redzi, Dāvids meklē tavu nelaimi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Redzi, šodien tavas acis redz, ka Tas Kungs tevi šodien tai alā bija devis manā rokā. Un gan sacīja, lai es tevi nokauju, bet (mana roka) tevi žēloja, jo es sacīju: es nepielikšu savu roku pie sava kunga, jo viņš ir Tā Kunga svaidītais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Redzi jel, mans tēvs, redzi savu svārku stūri manā rokā; jo kad es to stūri no taviem svārkiem nogriezu, tad es tevi neesmu nokāvis. Atzīsti tad un redzi, ka manā rokā nav nedz ļaunuma nedz blēdības, un ka pret tevi neesmu grēkojis; taču tu meklē manu dvēseli paņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Tas Kungs tiesās starp mani un tevi, tiešām Tas Kungs mani pie tevis atriebs, bet mana roka nebūs pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Tā kā top teikts pēc veca sakāma vārda: no bezdievīgiem nāk bezdievība; bet mana roka nebūs pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Pret ko tu, Israēla ķēniņ, esi izgājis? Kam tu dzenies pakaļ? Vienam nedzīvam sunim, vienai blusai!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Bet Tas Kungs būs par tiesnesi un tiesās starp mani un tevi, un redzēs un pārstāvēs manu tiesu un mani izglābs no tavas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Kad nu Dāvids bija beidzis šos vārdus uz Saulu runāt, tad Sauls sacīja: vai šī nav tava balss, mans dēls Dāvid? Un Sauls pacēla savu balsi un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Un viņš sacīja uz Dāvidu: tu esi taisnāks nekā es. Jo tu man esi labu darījis, bet es tev ļaunu esmu atmaksājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Un nu tu man šodien esi parādījis, ka tu pie manis esi labu darījis, kad Tas Kungs mani tavā rokā bija iedevis, bet tu mani neesi nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Kad, kas savu ienaidnieku atrod, vai viņš tam liks staigāt pa labu ceļu? Lai Tas Kungs tev labu atmaksā par to, ko tu šodien pie manis esi darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Un nu, redzi, es zinu, ka tu tiešām būsi par ķēniņu, un ka Israēla valstība stāvēs tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Tad zvērē nu man pie Tā Kunga, ka tu manu dzimumu pēc manis negribi izdeldēt, nedz iznīcināt manu vārdu no mana tēva nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Tad Dāvids zvērēja Saulam. Un Sauls gāja savās mājās, bet Dāvids un viņa vīri gāja uz augšu tai nepieejamā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Un Samuēls nomira un viss Israēls sapulcējās un žēlojās par to un to apraka viņa namā Rāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Tad Dāvids nogāja uz Pārana tuksnesi. Un viens vīrs bija Maonā, kam saimniecība bija Karmelī; un tas vīrs bija ļoti bagāts, un tam bija trīstūkstoš avis un tūkstoš kazas. Un tas bija Karmelī, savas avis cirpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Un tam vīram bija vārds Nābals, un viņa sievai bija vārds Abigaīle, un tā sieva bija ļoti gudra padomā un skaista augumā. Bet tas vīrs bija pikts un ļauns savos darbos un no Kāleba bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Kad nu Dāvids tuksnesī dzirdēja, ka Nābals savas avis cirpa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Tad viņš sūtīja desmit puišus un sacīja tiem puišiem: ejat uz Karmeli un ejat pie Nābala un sveicinājiet viņu no manas puses,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Un sakāt: Dievs palīdz, miers lai ir ar tevi un miers ar tavu namu un miers ar visu, kas tev pieder!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Un nu es esmu dzirdējis, ka tev ir avju cirpēji. Tad nu tavi gani pie mums ir bijuši, mēs tiem nekā ļauna neesam darījuši, tiem arī nekas nav zudis visu to laiku, kamēr tie Karmelī bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Vaicā savus puišus, tad tie tev to sacīs. Lai tad tie jaunekļi žēlastību atrod priekš tavām acīm, jo mēs labā dienā esam atnākuši. Dod jel saviem kalpiem un savam dēlam Dāvidam, kas tev pie rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Kad nu Dāvida puiši bija nākuši un šos vārdus uz Nābalu no Dāvida puses runājuši, tad tie palika klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Bet Nābals atbildēja Dāvida kalpiem un sacīja: kas tas tāds Dāvids un kas tas tāds Isajus dēls? Šinī laikā ir daudz kalpu, kas no saviem kungiem aizbēg.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Vai tad es savu maizi un ūdeni un savus lopus ņemšu, ko es priekš saviem cirpējiem esmu kāvis, un došu vīriem, ko es nepazīstu, no kurienes tie ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Tad Dāvida puiši griezās atpakaļ uz savu ceļu un gāja atpakaļ un nāca un atsacīja viņam visus šos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Tad Dāvids sacīja uz saviem vīriem: apjoziet ikviens savu zobenu. Tad ikviens apjoza savu zobenu. Un Dāvids apjoza arīdzan savu zobenu, un tie devās uz augšu Dāvidam pakaļ pie četrsimt vīru, un divsimt palika pie rīkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Bet Abigaīlei, Nābala sievai, viens no tiem puišiem to stāstīja un sacīja: redzi, Dāvids ir vēstnešus sūtījis no tuksneša un mūsu kungu licis sveicināt, bet viņš tos izbāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Bet tie vīri mums ir bijuši ļoti labi, un mums nekā ļauna nav darījuši un mums nekas nav zudis visu to laiku, kad mēs pie tiem mituši, kad bijām laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Tie mums bijuši par mūri gan naktīm, gan dienām, visu to laiku, kad mēs pie tiem bijuši, avis ganīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Un nu ņem vērā un raugi, ko tu dari, jo nelaime būs gatava pret mūsu kungu un pret visu viņa namu, un tas ir netikls vīrs, ka viņam nekā nevar sacīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Tad Abigaīle steidzās un ņēma divsimt maizes un divus ādas traukus ar vīnu un piecas kautas avis un piecus pūrus miltu un simts rozīņu raušu un divsimt vīģu raušu, un to krāva uz ēzeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Un tā sacīja uz saviem puišiem: noejat manā priekšā, redzi, es būšu aiz jums. Bet savam vīram Nābalam, viņa par to tam nedeva ziņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Kad nu viņa uz ēzeļa jādama nonāca pakalnā, meža ēnā, redzi, tad Dāvids ar saviem vīriem nonāca viņai pretī, un viņa tos sastapa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Bet Dāvids bija sacījis: tiešām, es esmu velti sargājis visu, kas šim pieder tuksnesī, un tam nekas nav zudis no tā, kas viņam bija, bet viņš man maksā ļaunu par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Lai Dievs Dāvida ienaidniekiem šā un tā dara, ja es no visa, kas viņam pieder, līdz rītam vienu atlicināju, kas mīž pie sienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Kad nu Abigaīle Dāvidu redzēja, tad viņa steidzās un nokāpa no ēzeļa un Dāvida priekšā krita uz savu vaigu un metās pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Un tā krita viņam pie kājām un sacīja: ak mans kungs, pielīdzini man, man to noziegumu, un lai jel tava kalpone priekš tavām ausīm runā, un klausi tavas kalpones vārdus!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Mans kungs, nedusmojies, lūdzams, par šo netiklo vīru, par Nābalu, jo viņš ir tāds, kā viņa vārds skan; Nābals (ģeķis) viņa vārds un ģeķība ir pie viņa, un es, tava kalpone, sava kunga puišus neesmu redzējusi, ko tu esi sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Nu tad, mans kungs, tik tiešām kā Tas Kungs dzīvs un tava dvēsele dzīva, Tas Kungs tevi ir noturējis, ka tu neesi nācis asinsgrēkā un neesi atriebies ar savu roku, un nu, kā Nābals, tā lai top tavi ienaidnieki un tie, kas pret manu kungu ļaunu domā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Un šī nu ir tā svētība, ko tava kalpone savam kungam ir atnesusi; lai to dod tiem puišiem, kas manam kungam staigā pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Piedod, lūdzams, tavai kalponei to pārkāpumu; jo Tas Kungs tiešām manam kungam dos pastāvīgu namu, tāpēc ka mans kungs karo Tā Kunga karu, un nekāds ļaunums tevi neaizņems ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Un kad kāds cilvēks pret tevi celsies, tevi vajāt un tavu dvēseli meklēt, tad mana kunga dvēsele būs iesieta tai dzīvo (dvēseļu) kūlītī pie Tā Kunga, tava Dieva, bet tavu ienaidnieku dvēsele taps kā no lingas izlingota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Kad nu Tas Kungs manam kungam visu to labu darīs, ko Viņš par tevi runājis, un tevi cels par valdnieku pār Israēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Tad manam kungam nebūs šis grēks un šis sirds grūtums, ka tu velti būtu asinis izlējis, un ka mans kungs pats sev būtu palīdzējies; un kad Tas Kungs manam kungam labu darīs, tad tu pieminēsi savu kalponi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Tad Dāvids sacīja uz Abigaīli: slavēts lai ir Tas Kungs, Israēla Dievs, kas tevi šodien man pretī sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Un slavēts lai ir tavs padoms, un svētīta esi tu pati, ka tu man šodien noturējusi, ka neesmu nācis asinsgrēkā, un ka ar savu roku neesmu atriebies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Jo patiesi, tik tiešām kā Tas Kungs, Israēla Dievs, dzīvs, kas mani noturējis tev ļaunu darīt; ja tu nebūtu steigusies un man pretī nākusi, tad Nābalam nebūtu atlicis līdz rīta gaismai neviens, kas mīž pie sienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Tad Dāvids ņēma no viņas rokas, ko viņa tam bija atvedusi, un uz to sacīja: ej ar mieru atkal savās mājās! Redz, es tavu balsi esmu klausījis un tavu lūgšanu pieņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Kad nu Abigaīle pie Nābala nāca, redzi, tad tam bija dzīres savā namā, tāpat kā ķēniņa dzīres, un Nābala sirds priecājās pie sevis, un viņš bija ļoti piedzēries. Bet viņa tam ne vārda nesacīja, ne maza, ne liela, līdz rīta gaismai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Un notikās rītā, kad vīns no Nābala bija izgājis, tad viņa sieva tam visu to stāstīja. Tad viņa sirds iekš viņa pamira, un viņš kļuva kā akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Un pēc kādām desmit dienām Tas Kungs sita Nābalu, ka tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Kad Dāvids dzirdēja, Nābalu esam mirušu, tad viņš sacīja: slavēts ir Tas Kungs, kas manu apsmieklu pie Nābala atriebis un Savu kalpu noturējis no ļauna, un ka Tas Kungs Nābalam to ļaunu uz viņa galvu maksājis. Un Dāvids nosūtīja un runāja uz Abigaīli, ka viņš to ņemtu par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Tad Dāvida kalpi nāca pie Abigaīles uz Karmeli un runāja uz to un sacīja: Dāvids mūs pie tevis ir sūtījis, ka viņš tevi ņemtu sev par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Tad viņa cēlās un metās uz savu vaigu pie zemes un sacīja: redzi, še ir tava kalpone, ka tā kalpo un mazgā sava kunga kalpu kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Un Abigaīle steidzās un cēlās un jāja uz ēzeļa ar savām piecām jaunām meitām, kas viņai staigāja pakaļ, un tā gāja Dāvida vēstnešiem pakaļ un viņam palika par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Un Dāvids ņēma arī Aķinoamu no Jezreēles, un tā šās abas viņam bija par sievām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Jo Sauls savu meitu Mikali, Dāvida sievu, bija devis Paltam, Laīsa dēlam, kas bija no Gallim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Tad Zifieši nāca pie Saula uz Ģibeju un sacīja: vai Dāvids nav paslēpies uz Aķilas pakalna šaipus tuksneša?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Tad Sauls cēlās un nogāja uz Zifas tuksnesi, un viņam līdz trīstūkstoš izlasīti Israēla vīri, Dāvidu meklēt Zifas tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Un Sauls apmeta lēģeri uz Aķilas pakalna, kas šaipus tuksneša ceļmalā. Bet Dāvids palika tuksnesī. Un kad viņš redzēja, ka Sauls viņam pakaļ nāca tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Tad Dāvids izsūtīja izlūkus un nomanīja Saulu tiešām nākam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Un Dāvids cēlās un nāca uz to vietu, kur Sauls bija apmeties, un Dāvids redzēja to vietu, kur Sauls gulēja ar Abneru, Nera dēlu, savu karalielkungu, un Sauls gulēja starp tiem savestiem lēģera ratiem, un tie ļaudis ap viņu bija apmetušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Tad Dāvids bilda un sacīja uz Aķimeleku, to Etieti, un uz Abizaju, Cerujas dēlu, Joaba brāi, sacīdams: Kas man ies līdz pie Saula lēģerī? Tad Abizajus sacīja: es iešu tev līdzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Tad Dāvids un Abizajus nāca pie (Saula) ļaudīm naktī, un redzi, Sauls gulēja aizmidzis starp tiem savestiem lēģera ratiem, un viņa šķēps bija viņa galvas galā zemē iedurts, bet Abners un tie ļaudis gulēja ap viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Tad Abizajus sacīja uz Dāvidu: Dievs šodien tavu ienaidnieku ir devis tavā rokā; lai es nu viņu jel ar vienu reizi noduru ar šķēpu pie zemes, tad viņam otru reizi vairs nevajadzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Bet Dāvids sacīja uz Abizaju: nenonāve viņu, jo kas savu roku varētu pielikt pie Tā Kunga svaidītā un palikt nenoziedzīgs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Un Dāvids sacīja: tik tiešām kā Tas Kungs dzīvo, - ja Tas Kungs viņu nesitīs, vai nu viņa diena nāks, ka tas mirs, vai tas karā ies un ies bojā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Lai Tas Kungs mani pasargā, ka es savu roku liktu pie Tā Kunga svaidītā! Tāpēc ņem jel nu to šķēpu, kas ir viņa galvas galā, un to ūdens biķeri un ejam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Tā Dāvids ņēma to šķēpu un to ūdens biķeri no Saula galvas gala, un tie gāja projām, un neviens to neredzēja, un neviens to nemanīja, un neviens neuzmodās, bet tie gulēja visi, jo ciets miegs no Tā Kunga tiem bija uzkritis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Kad nu Dāvids uz otru pusi bija pārgājis, tad viņš stāvēja kalna galā no tālienes, ka vēl plata vieta bija viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Un Dāvids uzkliedza tiem ļaudīm un Abneram, Nera dēlam, un sacīja: vai tu neatbildi Abner? Tad Abners atbildēja un sacīja: kas tu tāds esi, ka tu tā pret ķēniņu kliedzi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Tad Dāvids sacīja uz Abneru: vai tu neesi vīrs? Un kas tev ir līdzīgs iekš Israēla? Kāpēc tad tu savu kungu, to ķēniņu, neesi sargājis? Jo viens no tiem ļaudīm ir nācis, ķēniņu, tavu kungu, nonāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Tas nav labi, ko tu esi darījis; tik tiešām kā Tas Kungs dzīvo, jo jūs nāvi esat pelnījuši, tāpēc ka jūs savu kungu, Tā Kunga svaidīto, neesat labāki sargājuši. Un nu redzi, kur ķēniņa šķēps ir un tas ūdens biķeris, kas bija viņa galvas galā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Un Sauls pazina Dāvida balsi un sacīja: vai šī nav tava balss, mans dēls Dāvid? Un Dāvids sacīja: mana balss, mans kungs un ķēniņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Un viņš sacīja: kāpēc mans kungs savu kalpu tā vajā? Jo ko es esmu darījis un kāds ļaunums ir manā rokā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Un nu klausi jel, mans kungs un ķēniņ, sava kalpa vārdus. Ja Tas Kungs tevi pret mani skubina, tad lai viņš ož upura dāvanu, bet ja cilvēku bērni to dara, tad tie lai ir nolādēti priekš Tā Kunga, tāpēc ka tie mani šodien izdzen, ka es nevaru palikt iekš Tā Kunga mantības, sacīdami: ej, kalpo svešiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Bet lai nu manas asinis pie zemes nekrīt tālu no Tā Kunga vaiga, jo Israēla ķēniņš ir izgājis vienu blusu meklēt, tā kā irbi medī uz kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Tad Sauls sacīja: es esmu grēkojis, griezies atpakaļ, mans dēls Dāvid, jo es tev vairs ļauna nedarīšu, tāpēc ka mana dvēsele šodien ir dārga bijusi tavās acīs; redzi, es esmu aplam darījis un ļoti noziedzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Tad Dāvids atbildēja un sacīja: redz, še ir ķēniņa šķēps, lai tad viens no tiem puišiem nāk un to paņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Bet Tas Kungs lai ikvienam maksā pēc viņa taisnības un pēc viņa uzticības; gan Tas Kungs tevi šodien manā rokā bija devis, bet es savu roku negribēju likt pie Tā Kunga svaidītā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Un redzi, kā tava dvēsele šodien ir augsti turēta manās acīs, tā lai mana dvēsele augsti top turēta Tā Kunga acīs, un lai viņš mani izpestī no visām bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Tad Sauls sacīja uz Dāvidu: svētīts tu esi, mans dēls Dāvid, tiešām ko tu uzņemsies, to tu tiešām arī izvedīsi galā. Tad Dāvids gāja savu ceļu, un Sauls griezās atpakaļ uz savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Un Dāvids domāja savā sirdī: taču man kādā dienā nāks gals caur Saula roku; man labuma nav, ja es glābtin neglābjos uz Fīlistu zemi, lai Sauls mitās mani joprojām meklēt visās Israēla robežās; tā es no viņa rokas izglābšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Tad Dāvids cēlās un gāja ar tiem sešsimt vīriem, kas pie viņa bija, pie Aķisa, Maoka dēla, Gatas ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Un Dāvids palika pie Aķisa Gatā, pats un viņa vīri, ikkatrs ar savu namu, Dāvids ar savām abām sievām, Aķinoamu, to Jezreēlieti, un Abigaīli, Nābala sievu, to Karmelieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Kad nu Saulam sacīja, ka Dāvids aizbēdzis uz Gatu, tad viņš to vairs nemeklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Un Dāvids sacīja uz Aķisu: ja es žēlastību esmu atradis priekš tavām acīm, tad lai man dod vietu vienā zemes pilsētā, ka es tur dzīvoju; jo kāpēc tavam kalpam ķēniņa pilsētā pie tevis būs dzīvot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Tad Aķis viņam tai dienā deva Ciklagu. Tāpēc Ciklaga Jūda ķēniņiem pieder līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Un tas laiks, ko Dāvids Fīlistu zemē mita, bija viens gads un četri mēneši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Un Dāvids cēlās ar saviem vīriem un uzbruka Gešuriešiem un Ģirziešiem un Amalekiešiem, jo tie citkārt bija tie zemes iedzīvotāji līdz Šurai un Ēģiptes zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Un Dāvids kāva to zemi un nepameta dzīvus ne vīrus, ne sievas un ņēma avis un vēršus un ēzeļus un kamieļus un drēbes, un griezās atpakaļ un nāca pie Aķisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Kad nu Aķis sacīja: kur jūs šodien esat ielauzušies? Tad Dāvids sacīja: pret dienasvidu iekš Jūda, un pret dienasvidu pie Jerameliešiem, un pret dienasvidu pie Keniešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Un Dāvids ne vīrus, ne sievas nepameta dzīvus, ka tie netiktu uz Gatu; jo viņš sacīja: lai nenes vēsti pret mums, sacīdami: tā Dāvids mums ir darījis. Un tāds bija viņa darbs, cik ilgi tas Fīlistu zemē dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Un Aķis ticēja Dāvidam un domāja, viņš sev smirdošu darījies priekš saviem Israēla ļaudīm, tāpēc viņš man mūžam būs par kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Tanīs dienās notika, ka Fīlisti savus pulkus uz karu sapulcināja, ar Israēli karot. Tad Aķis sacīja uz Dāvidu: tev būs zināt, ka tev līdz ar mani jāiet karā, gan tev, gan taviem vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Tad Dāvids sacīja uz Aķisu: tad tu gan manīsi, ko tavs kalps darīs. Un Aķis sacīja uz Dāvidu: tāpēc es tevi iecelšu par savas galvas sargu mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Un Samuēls jau bija nomiris, un viss Israēls par viņu bija žēlojies, un viņu bija aprakuši Rāmatā, viņa pilsētā. Un Sauls zīlniekus un burvjus bija izdzinis no zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Tā nu Fīlisti sapulcējās un nāca un apmetās Šunemē, un Sauls sapulcēja visu Israēli un tie apmetās Ģilboā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Kad nu Sauls Fīlistu lēģeri redzēja, tad viņš bijās, un viņa sirds drebēja ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Un Sauls vaicāja To Kungu, bet Tas Kungs tam neatbildēja ne caur sapņiem, ne caur urim(lozēm), ne caur praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Tad Sauls sacīja uz saviem kalpiem: meklējiet man vienu sievu, kam zīlnieka gars, ka es pie tās eju un to vaicāju. Un viņa kalpi uz to sacīja: redz, Endorā ir viena sieva, tai ir zīlnieka gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Un Sauls pārmija savas drēbes un apvilka citas un gāja pats ar diviem vīriem un nāca pie tās sievas naktī un sacīja: zīlē man, lūdzama, caur zīlnieka garu un uzved man to, ko es tev sacīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Tad tā sieva uz to sacīja: redzi, tu zini, ko Sauls ir darījis, ka tas zīlniekus un burvjus no zemes ir izdeldējis. Kāpēc tu tad manai dvēselei valgus lieci, mani nomaitāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Bet Sauls viņai zvērēja pie Tā Kunga un sacīja: tik tiešām kā Tas Kungs dzīvo, tev par to lietu nekāds sods neuzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Tad tā sieva sacīja: ko man tev būs uzvest? Un tas sacīja: uzved man Samuēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Kad nu tā sieva Samuēli redzēja, tad tā iebrēcās ar stipru balsi un teica uz Saulu un sacīja: kāpēc tu man esi pievīlis? Tu esi Sauls!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Un ķēniņš uz to sacīja: nebīsties! Bet ko tu redzi? Tā sieva sacīja uz Saulu: es redzu garu no zemes uzkāpjam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Un viņš uz to sacīja: kāds ir viņa ģīmis? Un viņa sacīja: tur uzkāpj vecs vīrs, apņēmies mētelī. Tad Sauls manīja, ka tas bija Samuēls, un viņš locīdamies nometās uz savu vaigu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Un Samuēls sacīja uz Saulu: kāpēc tu mani nelieci mierā, un man esi licis nākt augšām? Tad Sauls sacīja: man ir ļoti bail, jo Fīlisti karo pret mani, un Dievs no manis ir atstājies un man vairs neatbild, nedz caur praviešiem, nedz caur sapņiem; tad es tevi esmu aicinājis, man padomu dot, ko man būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Tad Samuēls sacīja: kāpēc tad tu mani vaicā, kad Tas Kungs no tevis atstājies un tev palicis par ienaidnieku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Jo Tas Kungs tev ir darījis, ko Viņš caur mani runājis, un Tas Kungs to valstību no tavas rokas ir izrāvis un devis Dāvidam, tavam tuvākam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Tā kā tu uz Tā Kunga balsi neesi klausījis un neesi darījis pēc Viņa bargām dusmām pret Amaleku, tā Tas Kungs tev šodien to dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Un Tas Kungs Israēli līdz ar tevi nodos Fīlistu rokā, jo rītu tu ar saviem dēliem būsi pie manis. Un Tas Kungs Israēla kara spēku dos Fīlistu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Tad Sauls piepeši krita garšļauku pie zemes, un izbijās ļoti par Samuēla vārdiem; jo viņam nebija spēka, tādēļ ka visu to dienu un nakti nebija ēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Tad tā sieva nāca pie Saula un redzēja, ka viņš ļoti bija izbijies, un uz viņu sacīja: redzi, tava kalpone tavai balsij ir klausījusi, un es savu dzīvību savā rokā esmu likusi un tavam vārdam paklausījusi, ko tu uz mani esi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Tad klausi nu arī tu, lūdzams, uz savas kalpones balsi, un es tev celšu priekšā kādu kumosu maizes, un ēd, tad tev atkal būs spēks, ka tu vari iet savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Bet viņš liedzās un sacīja: es negribu ēst, bet viņa kalpi un tā sieva to piespieda, ka tas viņu balsij paklausīja. Un viņš cēlās augšā no zemes un apsēdās uz gultu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Un tai sievai bija barots teļš sētā, un viņa steidzās un to nokāva un ņēma miltus un tos mīcīja un cepa neraudzētas karašas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Un to cēla priekšā Saulam un viņa kalpiem, un tie ēda un cēlās un aizgāja tai pašā naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Un Fīlisti visus savus pulkus bija sapulcinājuši Afekā, un Israēls apmetās pie Jezreēles akas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Un Fīlistu lielkungi tur gāja ar simtiem un ar tūkstošiem. Bet Dāvids un viņa vīri gāja ar Aķisu no aizmugures.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Tad Fīlistu lielkungi sacīja: ko šie Ebreji (te dara)? Un Aķis sacīja uz Fīlistu lielkungiem: vai šis nav Dāvids, Saula, Israēla ķēniņa, kalps, kas šīs dienas un šos gadus pie manis bijis, un es pie tā nekā neesmu atradis no tās dienas, kad viņš tur ir atkritis, līdz šai dienai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Bet Fīlistu lielkungi apskaitās par viņu un uz viņu sacīja: lai tas vīrs griežas atpakaļ un lai iet atpakaļ uz savu vietu, ko tu viņam esi devis; lai viņš neiet karā mums līdz, ka viņš mums nepaliek par pretinieku pašā kaušanā. Jo kā šis savam kungam labāki varētu patikt, nekā caur šo vīru galvām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Vai šis nav tas Dāvids, par ko tie dejojot un dziedot sacīja: Sauls ir tūkstošus kāvis, bet Dāvids desmit tūkstošus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Tad Aķis aicināja Dāvidu un uz to sacīja: tik tiešām kā Tas Kungs dzīvo, tu esi taisns vīrs un tava iziešana un ieiešana pie manis lēģerī man labi patīk, jo es pie tevis neesmu ļauna atradis no tās dienas, kad tu pie manis nācis, līdz šai dienai, bet tiem lielkungiem tu neesi patīkams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Tad nu griezies atpakaļ un ej ar mieru, ka tu ļauna nedari priekš Fīlistu lielkungu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Tad Dāvids sacīja uz Aķisu: ko es esmu darījis un ko tu pie sava kalpa esi atradis no tās dienas, kad es tavā priekšā bijis, līdz šai dienai, ka man nu nebūs iet un kauties pret sava kunga, tā ķēniņa, ienaidniekiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Tad Aķis atbildēja un sacīja uz Dāvidu: es gan zinu, tiešām tu manām acīm esi patīkams, tāpat kā viens Dieva eņģelis. Bet Fīlistu lielkungi saka, lai viņš neiet karā mums līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Nu tad celies rītā agri ar sava kunga kalpiem, kas tev līdz nākuši, un ceļaties rītā agri, kad gaisma būs metusies, un ejat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Tad Dāvids cēlās ar saviem vīriem, iet agri atpakaļ uz Fīlistu zemi. Bet Fīlisti cēlās uz Jezreēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Un notikās, kad Dāvids ar saviem vīriem trešā dienā nāca uz Ciklagu, tad Amalekieši pret dienvidiem un Ciklagā bija ielauzušies un Ciklagu kāvuši un ar uguni sadedzinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Un tās sievas no turienes bija aizveduši, un mazus un lielus, bet nevienu nebija nokāvuši, bet aizveduši un gājuši savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Un Dāvids ar saviem vīriem nāca pie tās pilsētas, un redzi, tā bija sadedzināta ar uguni, un viņu sievas un viņu dēli un viņu meitas bija aizvesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Tad Dāvids ar tiem vīriem, kas pie viņa bija, pacēla savu balsi un raudāja, kamēr tiem vairs spēka nebija raudāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Arī Dāvida abas sievas, Aķinoama, tā Jezreēliete, un Abigaīle, Nābala sieva, tā Karmeliete, bija aizvestas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Un Dāvidam bija ļoti bail, jo tie ļaudis to gribēja akmeņiem nomētāt, jo visiem ļaudīm sirds ēdās, ikvienam par saviem dēliem un par savām meitām. Bet Dāvids stiprinājās iekš Tā Kunga, sava Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Un Dāvids sacīja uz priesteri Abjataru, Aķimeleka dēlu: dod jel to efodu šurp! Un Abjatars nesa to efodu pie Dāvida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Tad Dāvids vaicāja To Kungu sacīdams: vai man būs tam pulkam pakaļ dzīties, vai es tos panākšu? Un Viņš tam sacīja: dzenies, tu tos panāksi un patiesi atpestīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Tad Dāvids nogāja ar tiem sešsimt vīriem, kas pie viņa bija, un kad tie nāca pie Bezoras upes, tad tur citi apstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Un Dāvids tiem dzinās pakaļ ar četrsimt vīriem, bet divsimt vīri tur palika stāvot, kas bija piekusuši, ka nevarēja iet pār Bezoras upi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Un tie atrada vienu Ēģiptieti laukā, to tie atveda pie Dāvida, un deva tam maizes, un viņš ēda, un deva tam ūdeni dzert,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Un deva tam vienu šķēli vīģu raušu un divus rozīņu raušus. Un viņš ēda, un viņa gars atkal atgriezās pie viņa, jo viņš nebija maizes ēdis, nedz ūdens dzēris trīs dienas un trīs naktis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Tad Dāvids uz to sacīja: kas tu esi un no kurienes tu esi? Tad tas sacīja: esmu ēģiptiešu puisis, viena Amalekieša kalps, un mans kungs mani atstājis, tāpēc ka es priekš trim dienām esmu slims palicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Mēs bijām ielauzušies pret dienasvidu pie Krietiem un uz Jūdu un pret dienasvidu pie Kāleba, un Ciklagu ar uguni esam sadedzinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Tad Dāvids uz to sacīja: vai tu gribi mani novest pie šā pulka? Un tas sacīja: zvērē man pie Dieva, ka tu mani negribi nokaut nedz nodot mana kunga rokā, tad es tevi pie šā pulka novedīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Un viņš to noveda. Un redzi, tie gulēja izklīduši pa visu klajumu, ēda un dzēra un dejoja par visu to lielo laupījumu, ko tie bija paņēmuši no Fīlistu un Jūdu zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Un Dāvids tos kāva no rīta gaismas līdz vakaram otrai dienai sākot, un neviens no tiem neizspruka, kā vien četrsimt jauni vīri, kas uz kamieļiem jāšus aizbēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Tā Dāvids izglāba visu, ko Amalekieši bija paņēmuši, un Dāvids arī izglāba savas abas sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Un no tiem netrūka neviena, ne maza ne liela, ne dēla ne meitas, ne no tā laupījuma, ne no visa, ko tie tiem bija paņēmuši, - visu Dāvids veda atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Un Dāvids ņēma visas avis un vēršus, un tie šos lopus dzina Dāvida priekšā un sacīja: šis ir Dāvida laupījums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Kad nu Dāvids pie tiem divsimt vīriem nāca, kas bija piekusuši, ka Dāvidam nevarēja iet pakaļ, un tāpēc pie Bezoras upes bija pamesti, tad tie Dāvidam un tiem ļaudīm, kas pie viņa bija, izgāja pretī. Un Dāvids piestājās pie tiem ļaudīm un vaicāja pēc viņu labklāšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Tad visi netiklie un negantie ļaudis to vīru starpā, kas ar Dāvidu bija gājuši, atbildēja un sacīja: tāpēc ka tie mums nav nākuši līdz, tad mēs tiem arī nekā nedosim no tā laupījuma, ko esam glābuši, kā vien ikkatram savu sievu un savas bērnus; tos lai tie ņem un iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Bet Dāvids sacīja: tā jums, mani brāļi, nebūs darīt ar to, ko Tas Kungs mums ir devis, jo Viņš mūs ir pasargājis, un to pulku, kas pret mums nācis, ir devis mūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kas jūs šinī lietā varētu klausīt? Jo kāda daļa ir tiem, kas gājuši kauties, tāda pat daļa būs arī šiem, kas pie rīkiem palikuši, tiem kopā būs dalīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Un tas no tās dienas nu joprojām tā ir palicis, jo viņš to par likumu un tiesu ir iecēlis iekš Israēla līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Kad nu Dāvids uz Ciklagu nāca, tad viņš no tā laupījuma Jūda vecajiem, saviem draugiem, sūtīja un sacīja: redz, še jums ir dāvanas no Tā Kunga ienaidnieku laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, '(Proti) tiem Bētelē un tiem Rāmatā pret dienasvidu un tiem Jatirā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Un tiem Aroērā un tiem Sipmotā un Estemoā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Un tiem Rakalā un tiem, kas bija Jerameēliešu pilsētās, un tiem, kas Keniešu pilsētās dzīvoja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Un tiem Ormā un tiem KorAzanā un tiem Atakā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'Tiem Hebronē, un visām vietām, kur Dāvids bija apkārt gājis, viņš un viņa vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Un Fīlisti karoja pret Israēli un Israēla vīri bēga no Fīlistiem un krita nokauti uz Ģilboas kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Un Fīlisti lauzās uz Saulu un uz viņa dēliem, un nokāva Jonatānu un Abinadabu un Malķizuū, Saula dēlus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Un tā kaušanās bija briesmīga pret Saulu, un strēlnieki to aizņēma ar saviem stopiem, un viņš tapa ļoti ievainots no tiem strēlniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Tad Sauls sacīja uz savu bruņu nesēju: izvelc savu zobenu un nodur mani ar to, ka šie neapgraizītie nenāk un mani nenodur un mani neliek smieklā. Bet viņa bruņu nesējs negribēja, jo viņš bijās ļoti. Tad Sauls ņēma zobenu un metās uz to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Kad nu viņa bruņu nesējs redzēja, ka Sauls bija miris, tad tas arīdzan metās savā zobenā un mira līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tā Sauls nomira un viņa trīs dēli un viņa bruņu nesējs un visi viņa vīri tai dienā kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Kad nu Israēla vīri, kas bija viņpus tās ielejas un viņpus Jardānes, redzēja, ka Israēla vīri bija bēguši un ka Sauls ar saviem dēliem bija nomiris, tad tie atstāja tās pilsētas un bēga, un Fīlisti nāca un dzīvoja iekš tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Un otrā dienā Fīlisti nāca, tos nokautos aplaupīt, un atrada Saulu un viņa trīs dēlus uz Ģilboas kalniem guļam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Un tie viņam nocirta galvu un novilka bruņas, un sūtīja pa Fīlistu zemi apkārt, ziņu dot savu elka dievu namos un pa tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Un tie nolika viņa bruņas Astartes namā un viņa miesas tie pakāra BetŠanā pie mūra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Kad nu Jabesas iedzīvotāji Gileādā dzirdēja, ko Fīlisti Saulam bija darījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Tad visi spēcīgie vīri cēlās un gāja cauru nakti un ņēma Saula miesas un viņa dēlu miesas no BetŠanas mūra, un tās veda uz Jabesu un tās tur sadedzināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Un ņēma viņu kaulus un tos apraka apakš Jabesas kokiem un gavēja septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Un notikās pēc Saula miršanas, kad Dāvids no Amalekiešu kaušanas bija atpakaļ griezies, tad Dāvids palika divas dienas Ciklagā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Un redzi, trešā dienā viens vīrs nāca no lēģera, no Saula, un viņa drēbes bija saplosītas, un zeme bija uz viņa galvas. Un kad viņš pie Dāvida nāca, viņš klanījās pie zemes mezdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Un Dāvids uz to sacīja: no kurienes tu nāci? Un tas uz viņu sacīja: no Israēla lēģera esmu izbēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Tad Dāvids uz to sacīja: kā tur iet? Teic man jel! Un tas sacīja: tie ļaudis no kaušanās ir bēguši un daudz no tiem ļaudīm krituši un miruši, arī Sauls un Jonatāns, viņa dēls, ir miruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Tad Dāvids sacīja uz to puisi, kas viņam to teica: kā tu zini, ka Sauls un Jonatāns, viņa dēls, miruši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Tad tas puisis, kas viņam to teica, sacīja: nejauši es nācu uz Ģilboas kalniem un redzi, Sauls bija atspiedies uz savu šķēpu, un redzi, rati un jātnieki tam lauzās virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Tad viņš griezās atpakaļ un mani ieraudzīja un mani sauca. Un es sacīju: še es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Un viņš uz mani sacīja: kas tu esi? Un es uz to sacīju: esmu Amalekietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Un viņš uz mani sacīja: nāc šurp pie manis un nokauj mani, jo izbailes mani pārņēmušas, un mana dzīvība vēl ir vesela iekš manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Tad es pie tā piegāju un to nokāvu, jo es gan zināju, ka viņš pēc savas krišanas nevarēja dzīvot, un es paņēmu to kroni, kas bija uz viņa galvas, un viņa rokas greznumu un to nesu šurp pie sava kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Tad Dāvids sakampa savas drēbes un tās saplēsa, tāpat arī visi tie vīri, kas pie viņa bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Un tie žēlojās un raudāja un gavēja līdz vakaram par Saulu un par viņa dēlu Jonatānu un par Tā Kunga ļaudīm un par Israēla namu, tāpēc ka tie caur zobenu bija krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Un Dāvids sacīja uz to puisi, kas viņam to bija teicis: no kurienes tu esi? Un viņš sacīja: es esmu sveša vīra, viena Amalekieša, dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Un Dāvids uz to sacīja: kā tu neesi bijies izstiept savu roku, nomaitāt Tā Kunga svaidīto?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Un Dāvids sauca vienu no tiem puišiem un sacīja: nāc, nokauj viņu. Un tas to kāva, ka tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Un Dāvids uz to sacīja, tavas asinis lai paliek uz tavas galvas, jo tava paša mute pret tevi ir liecinājusi sacīdama: es Tā Kunga svaidīto esmu nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Tad Dāvids dziedāja šo vaidu dziesmu par Saulu un par viņa dēlu Jonatānu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Un pavēlēja lai Jūda bērniem to stopa dziesmu mācītu (redzi, tā ir rakstīta tā taisnā grāmatā):');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Israēla glītums uz taviem kalniem nokauts! Kā tie varenie krituši!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Nestāstat to Gatā, neteiciet to Askalonas ielās, ka Fīlistu meitas nepriecājās, ka neapgraizīto meitas nelīksmojās!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Ģilboas kalni, lai rasa un lietus vairs nav uz jums, nedz tīrumi upuru dāvanām, jo tur to vareno priekšturamās bruņas ir nomestas, Saula priekšturamās bruņas ar eļļu nesvaidītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Jonatāna stops nekad nav dzīts atpakaļ un Saula zobens nekad nav pārnācis bez nokauto asinīm un vareno taukiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Sauls un Jonatāns, mīlīgi un laipni, dzīvībā un nāvē tie nav šķirti; tie bija vieglāki nekā ērgļi un stiprāki nekā lauvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Israēla meitas, raudiet par Saulu, kas jūs krāšņi tērpa ar purpuru, kas jūsu drēbes pušķoja ar zelta glītumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kā tie varenie ir krituši kara vidū! Jonatāns ir nokauts uz taviem kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Man ir žēl pēc tevis, mans brāli Jonatān! Tu man biji ļoti mīļš, tava mīlestība man bija saldāka, nekā sievas mīlestība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kā tie varenie krituši un kara ieroči gājuši bojā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Pēc tam Dāvids To Kungu vaicāja un sacīja: vai man būs iet uz vienu no Jūda pilsētām? Un Tas Kungs uz to sacīja: ej. Tad Dāvids sacīja: uz kurieni man būs iet? Un Viņš sacīja: uz Hebroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Tad Dāvids cēlās uz turieni līdz ar savām divām sievām, Aķinoamu, to Jezreēlieti, un Abigaīli, Nābala, tā Karmelieša, sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Un Dāvids arī saviem vīriem, kas pie viņa bija, ikkatram ar savu namu lika iet uz turieni; un tie dzīvoja Hebrones pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Un tie Jūda vīri nāca un Dāvidu tur svaidīja Jūda namam par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Un Dāvidam stāstīja un sacīja: Jabesas vīri Gileādā Saulu ir aprakuši. Tad Dāvids sūtīja vēstnešus pie tiem Jabesas vīriem Gileādā un tiem lika sacīt: svētīti jūs esat Tam Kungam, ka jūs šo mīlestību esat parādījuši savam kungam Saulam un viņu esat aprakuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Tad lai nu Dievs jums atkal parāda mīlestību un uzticību, un es arīdzan jums gribu labu darīt par to, ka jūs tā esat darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Un nu stiprinājiet savas rokas un esiet droši; jo, kad jūsu kungs Sauls nu ir miris, tad Jūda nams mani svaidījis sev par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Bet Abners, Nera dēls, Saula kara lielskungs, ņēma Išbošetu, Saula dēlu, un to pārveda uz Mahānaīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Un to iecēla par ķēniņu pār Gileādu un pār tiem Asuriešiem un pār Jezreēli un pār Efraīmu un pār Benjaminu un pār visu Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Četrdesmit gadus Išbošets, Saula dēls, bija vecs, kad viņš palika Israēlim par ķēniņu, un viņš valdīja divus gadus; bet tie no Jūda nama turējās pie Dāvida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Un viss tas laiks, kamēr Dāvids Hebronē bijis ķēniņš pār Jūda namu, ir septiņi gadi un seši mēneši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Un Abners, Nera dēls, izgāja ar Išbošeta, Saula dēla, kalpiem no Mahānaīm uz Gibeonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Un Joabs, Cerujas dēls, izgāja arīdzan ar Dāvida kalpiem, un tie sastapās pie Gibeonas dīķa, un palika viens šaipus dīķa un otrs viņpus dīķa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Un Abners sacīja uz Joabu: lai jel tie puiši ceļas un cīkstas mūsu priekšā. Tad Joabs sacīja: lai ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Tad cēlās un nogāja pēc skaita divpadsmit par Benjaminu un Išbošetu, Saula dēlu, un divpadsmit no Dāvida kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Un tie sagrāba viens otru pie galvas un iedūra savu zobenu otram sānos, un tie krita visi reizē, un šī vieta tapa nosaukta Elkat-Acurim (asmeņu tīrums), kas ir pie Gibeonas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Un tai dienā cēlās grūta kaušanās, un Abners un Israēla vīri tapa sakauti no Dāvida kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Un tur bija trīs Cerujas dēli, Joabs un Abizajus un Azaēls. Un Azaēls bija viegls uz kājām, kā stirna laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Un Azaēls dzinās Abneram pakaļ un neatstājās no Abnera ne pa labo ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Un Abners skatījās atpakaļ un sacīja: vai tu neesi Azaēls? Un viņš sacīja: es tas esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Tad Abners uz to sacīja: atkāpies vai pa labo, vai pa kreiso roku, un satver vienu no tiem puišiem un paņem viņa ieročus. Bet Azaēls no viņa negribēja atstāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Tad Abners runāja vēl uz Azaēli un sacīja: atstājies no manis, - kāpēc man tevi būs kaut zemē? Kā tad es varēšu savu vaigu pacelt tava brāļa Joaba priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Bet viņš negribēja atstāties. Tad Abners viņam ar šķēpa otru galu iedūra vēderā, ka šķēps pakaļā iznāca ārā, un Azaēls turpat krita un nomira. Un visi, kas uz to vietu nāca, kur Azaēls bija kritis un nomiris, tie tur apstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Bet Joabs un Abizajus dzinās Abneram pakaļ, un saule jau nogāja, kad tie nāca pie Amas pakalna, kas šaipus Ģias uz Gibeonas tuksneša ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Un Benjamina bērni sapulcējās Abneram pakaļ vienā pulkā un stāvēja kāda kalna galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Tad Abners sauca uz Joabu un sacīja: vai tad zobens lai rij mūžam? Vai tu nezini, ka beidzot ceļas rūgtums? Un cik ilgi tu tiem ļaudīm nesacīsi, lai saviem brāļiem vairs nedzenās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Tad Joabs sacīja: tik tiešām kā Dievs dzīvo, kad tu nebūtu runājis, tie ļaudis jau no paša rīta būtu novērsti, ikviens no sava brāļa nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Tad Joabs pūta ar bazūni, un visi ļaudis apstājās un nedzinās vairs Israēlim pakaļ un mitējās kauties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Un Abners un viņa vīri gāja cauru nakti pa to klajumu un cēlās pār Jardāni un gāja caur visu Bitronu un nāca uz Mahānaīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Un Joabs griezās atpakaļ no Abnera un sapulcināja visus ļaudis. Tad no Dāvida kalpiem trūka deviņpadsmit vīri un Azaēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Bet Dāvida kalpi bija kāvuši no Benjamina un Abnera vīriem trīssimt un sešdesmit vīrus; tie bija nomiruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Un tie pacēla Azaēli un to apraka viņa tēva kapā Bētlemē. Un Joabs gāja ar saviem vīriem cauru nakti, ka gaisma tiem ausa Hebronē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Un karš starp Saula namu un Dāvida namu vilcinājās. Bet Dāvids palika jo dienas jo spēcīgāks, un Saula nams jo dienas jo vājāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Un Dāvidam Hebronē piedzima dēli: viņa pirmdzimtais bija Ammons, no Aķinoamas, tās Jezreēlietes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Un viņa otrs bija Ķileabs no Abigaīles, Nābala sievas, no Karmeļa. Un trešais Absaloms, no Maākas, Talmaja, Gešuras ķēniņa, meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Un ceturtais Adonijus, Aģitas dēls. Un piektais Šefatijus, Abitalas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Un sestais Jetreams no Eglas, Dāvida sievas. Šie dzima Dāvidam Hebronē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Kamēr nu karš bija starp Saula namu un Dāvida namu, tad Abners stipri turējās pie Saula nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Un Saulam bija lieka sieva bijusi, Ricpa vārdā, Ajas meita. Un (Išbošets) sacīja uz Abneru: kāpēc tu guli pie mana tēva liekas sievas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Tad Abners ļoti apskaitās par Išbošeta vārdiem un sacīja: vai tad es esmu suņa galva, kas pie Jūda turas? Tava tēva Saula namam, viņa brāļiem un viņa draugiem es šodien parādu žēlastību un tevi neesmu nodevis Dāvida rokā, un tu man šodien noziegumu pārmeti tās sievas dēļ!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Lai Dievs Abneram šā un tā dara, ja es tā nedarīšu Dāvidam, kā Tas Kungs viņam ir zvērējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Noceldams valstību no Saula nama un uzceldams Dāvida goda krēslu pār Israēli un pār Jūdu no Dana līdz Bēršebai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Un tas Abneram ne vārda vairs nevarēja atbildēt, tā tas viņu bijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Un Abners sūtīja savā vietā vēstnešus pie Dāvida un sacīja: kam tā zeme pieder? Un sacīja: deri derību ar mani, redzi, tad mana roka būs ar tevi, atgriezt visu Israēli pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Un viņš sacīja: labi, es ar tevi derēšu derību, bet vienu lietu es prasu no tevis, proti, tev manu vaigu nebūs redzēt, pirms tu man nebūsi atvedis Mikali, Saula meitu, kad tu nāksi redzēt manu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Un Dāvids sūtīja vēstnešus pie Išbošeta, Saula dēla, sacīdams: dod man Mikali, manu sievu, ko esmu precējies ar simts Fīlistu priekšādām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Un Išbošets nosūtīja un to ņēma no vīra, no Paltiēļa, Laīsa dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Un viņas vīrs gāja viņai līdz, un iedams raudāja viņai pakaļ līdz Bakurim. Tad Abners uz to sacīja: ej, griezies atpakaļ. Tad viņš griezās atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Un Abners bija runājis ar Israēla vecajiem un sacījis: jūs citkārt Dāvidu esat meklējuši sev par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Tad dariet nu to, jo Tas Kungs uz Dāvidu ir runājis un sacījis: caur Sava kalpa Dāvida roku Es izpestīšu Savus Israēla ļaudis no Fīlistu rokas un no visu viņu ienaidnieku rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Tāpat Abners bija runājis priekš Benjamina ausīm, un Abners nogāja arī priekš Dāvida ausīm Hebronē runāt visu, kas Israēlim un visam Benjamina namam labi patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Un Abners nāca pie Dāvida uz Hebroni un divdesmit vīri viņam līdz, un Dāvids Abneram un tiem vīriem, kas viņam bija līdz, taisīja dzīres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Tad Abners sacīja uz Dāvidu: es celšos un iešu un sapulcināšu visu Israēli pie sava kunga, tā ķēniņa, ka tie ar tevi der derību; tad tu varēsi valdīt pār visu, kas tavai dvēselei patīk. Tā Dāvids atlaida Abneru, un tas aizgāja ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Un redzi, Dāvida kalpi un Joabs griezās atpakaļ no sirošanas un pārnesa lielu laupījumu. Un Abners nebija vairs pie Dāvida Hebronē, bet šis to bija atlaidis, ka tas ar mieru bija aizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kad nu Joabs un viss tas spēks ar viņu pārnāca, tad Joabam teica un sacīja: Abners, Nera dēls, ir nācis pie ķēniņa un tas viņu ir atlaidis, ka viņš ar mieru aizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Tad Joabs gāja pie ķēniņa un sacīja: ko tu esi darījis? Redzi, Abners pie tevis ir nācis, - kāpēc tu viņu esi atlaidis, ka tas aizgājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Tu gan Abneru, Nera dēlu, pazīsti, ka tas ir nācis tevi pierunāt, ka viņš vērā liktu tavu iziešanu un ieiešanu un izprastu visu, ko tu dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Un Joabs izgāja no Dāvida un sūtīja vēstnešus Abneram pakaļ, kas viņu atkal atveda no Ziras akas; bet Dāvids par to nezināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Kad nu Abners uz Hebroni nāca atpakaļ, tad Joabs viņu veda vārtos, klusu ar viņu parunāt, un tur tas viņam dūra vēderā, ka tas nomira, par viņa brāļa Azaēļa asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kad nu Dāvids to pēcak dzirdēja, tad viņš sacīja: es esmu nenoziedzīgs un mana valstība Tā Kunga priekšā mūžīgi pie Abnera, Nera dēla, asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Lai tās nāk uz Joaba galvu un uz visu viņa tēva namu, un lai Joaba namā netrūkst, kam izpil un kas ir spitālīgs un kas pie spieķa staigā un kas caur zobenu krīt un kam maizes trūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Tā Joabs un Abizajus, viņa brālis, nokāva Abneru par to, ka tas Azaēli, viņu brāli, bija nokāvis kaujā pie Gibeonas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Tad Dāvids sacīja uz Joabu un uz visiem ļaudīm, kas pie viņa bija: saplēšat savas drēbes un apvelciet maisus un žēlojaties Abnera pēc. Un ķēniņš Dāvids gāja bērēm pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Kad nu Abneru apraka Hebronē, tad ķēniņš pacēla savu balsi un raudāja pie Abnera kapa, un visi ļaudis raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Un ķēniņš žēlojās par Abneru un sacīja: vai Abneram bija jāmirst, kā mirst nelietis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tavas rokas nebija saistītas nedz tavas kājas liktas vara pinekļos; tu esi kritis, kā krīt caur netikliem. Tad visi ļaudis vēl vairāk par to raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Un visi ļaudis nāca aicināt, lai Dāvids maizes ēstu, kamēr vēl bija dienas gaisma; tad Dāvids zvērēja un sacīja: lai Dievs man šā un tā dara, ja es baudīšu maizes vai cita kā, pirms saule noiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Un visi ļaudis to dzirdēja, un tas tiem labi patika; viss ko ķēniņš darīja, tas visiem ļaudīm labi patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Un visi ļaudis un viss Israēls noprata tai dienā, ka tas nebija nācis no ķēniņa, ka Abners, Nera dēls, bija nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Un ķēniņš sacīja uz saviem kalpiem: vai nezināt, ka šodien lielskungs un augsts vīrs ir kritis iekš Israēla?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Bet es vēl šodien esmu par jaunu, nule par ķēniņu svaidīts. Un šie vīri, Cerujas dēli, man ir par stipriem; Tas Kungs lai atmaksā tiem ļauna darītājiem pēc viņu ļaundarīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Kad nu Saula dēls dzirdēja, ka Abners Hebronē bija miris, tad viņa rokas nogura un viss Israēls iztrūkās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Un Saula dēlam bija divi vīri, sirotāju virsnieki, un vienam bija vārds Baēna un otram Rekabs, Rimona dēli, no Beērotas, no Benjamina bērniem, (jo Beērota arīdzan Benjamina bērniem top pieskaitīta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Un tie Beērotieši bija bēguši uz Ģetaīm un bija tur piemitēji līdz šai dienai.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Un Jonatānam, Saula dēlam, bija dēls, tas bija tizls uz abējām kājām; pieci gadus viņš bija vecs, kad tā vēsts no Jezreēles nāca par Saulu un Jonatānu, un viņa emma viņu bija uzņēmusi un bēgusi, un tai steigšus bēgot viņš bija kritis un par kropli palicis, un viņa vārds bija Mefibošets.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Un Rimona, tā Beērotieša, dēli, Rekabs un Baēna, nogāja un nāca uz Išbošeta namu pašā dienas karstumā un viņš gulēja uz gultas dienasvidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Un tie gāja namā iekšā, tā kā kviešus ņemt, un iedūra viņam vēderā, un Rekabs un Baēna, viņa brālis, aizbēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Tie nāca namā, viņam uz gultas guļot savā guļamā istabā, un to sita un nokāva, un viņam nocirta galvu, un tie ņēma viņa galvu un gāja pa klajuma ceļu visu nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Un tie nesa Išbošeta galvu pie Dāvida uz Hebroni un sacīja uz ķēniņu: redzi, še ir Išbošeta, Saula dēla, tava ienaidnieka, galva, kas tavu dzīvību meklēja. Tā Tas Kungs manu kungu, to ķēniņu, šodien ir atriebis pie Saula un viņa dzimuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Bet Dāvids atbildēja Rekabam un viņa brālim Baēnam, Rimona, tā Beērotieša, dēliem, un uz tiem sacīja: tik tiešām, kā Tas Kungs dzīvs, kas manu dvēseli ir atpestījis no visām bēdām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Kas man to vēsti nesa, sacīdams: redzi, Sauls ir nomiris! Un šķitās labu vēsti nesot, to es sagrābu un nokāvu Ciklagā, dot tam vēstneša algu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Jo vairāk, kad bezdievīgi vīri taisnu vīru viņa namā uz viņa gultas nokāvuši, - un nu, vai man nebūs meklēt viņa asinis no jūsu rokām un jūs izdeldēt no zemes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Un Dāvids pavēlēja saviem puišiem, un tie tos nokāva un nocirta viņiem rokas un kājās un tos uzkāra pie Hebrones dīķa. Bet Išbošeta galvu tie ņēma un apraka Abnera kapā Hebronē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Tad visas Israēla ciltis nāca pie Dāvida uz Hebroni un runāja sacīdami: redzi, mēs esam no taviem kauliem un no tavām miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Arī senāk, kad Sauls mums bija par ķēniņu, tad tu Israēli izvadīji un ievadīji. Un Tas Kungs uz tevi ir sacījis: tev būs Manus Israēla ļaudis ganīt, un tev būs būt Israēlim par valdītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tā visi Israēla vecaji nāca pie ķēniņa uz Hebroni, un ķēniņš Dāvids derēja derību ar tiem Hebronē priekš Tā Kunga vaiga, un tie svaidīja Dāvidu Israēlim par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Trīsdesmit gadus Dāvids bija vecs, kad tas palika par ķēniņu, un viņš valdīja četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Hebronē viņš valdīja pār Jūdu septiņus gadus un sešus mēnešus, un Jeruzālemē viņš valdīja trīsdesmit un trīs gadus pār visu Israēli un Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Un ķēniņš gāja ar saviem vīriem uz Jeruzālemi pret Jebusiešiem, kas tai zemē dzīvoja, bet tie teica uz Dāvidu un sacīja: tu šurp nenāksi, bet aklie un tizlie tevi atsitīs, ar to teikdami, ka Dāvids tur iekšā netikšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Bet Dāvids uzņēma Ciānas pili, - šī ir Dāvida pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Jo Dāvids sacīja tai dienā: kas Jebusiešus kauj, lai grūž bezdibenī aklos un tizlos, ko Dāvida dvēsele ienīst. Tāpēc top sacīts: akls un tizls namā nenāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Tā Dāvids dzīvoja tai pilī un to nosauca par Dāvida pilsētu, un Dāvids to uztaisīja visapkārt no Millus sākot un uz iekšpusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Un Dāvids auga augumā vienmēr, un Tas Kungs, tas Dievs Cebaot, bija ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Un Hirams, Tirus ķēniņš, sūtīja vēstnešus pie Dāvida un ciedru kokus un remešus(namdarus) un akmeņu cirtējus, un tie uztaisīja Dāvidam namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Un Dāvids manīja, ka Tas Kungs viņu Israēlim bija apstiprinājis par ķēniņu, un ka Tas viņa valstību bija paaugstinājis Savu Israēla ļaužu labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Un Dāvids ņēma vēl vairāk lieku sievu un sievu no Jeruzālemes, kad viņš no Hebrones bija atnācis, un Dāvidam piedzima vēl vairāk dēlu un meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Un šie ir to vārdi, kas viņam Jeruzālemē dzimuši: Šamuūs un Zobabs, Nātans un Salamans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Un Jebears un Elizuūs un Nevegs un Japius');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Un Elišamus un Eliads un Elivalets.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Kad nu Fīlisti dzirdēja, ka Dāvids bija svaidīts Israēlim par ķēniņu, tad visi Fīlisti cēlās, Dāvidu meklēt. Un Dāvids to dzirdēdams nogāja uz to stipro pili.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Un Fīlisti nāca un apmetās Refaīm ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Tad Dāvids vaicāja To Kungu un sacīja: vai man būs celties pret Fīlistiem? Vai Tu tos dosi manā rokā? Un Tas Kungs sacīja uz Dāvidu: celies, jo Es Fīlistus tiešām došu tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Tad Dāvids nāca uz BaālPracim, un Dāvids tos tur kāva un sacīja: Tas Kungs manus ienaidniekus ir saplosījis manā priekšā, tā kā ūdens izplosa. Tādēļ šo vietu nosauca BaālPracim (plosījums).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Un tie tur pameta savus elkadievus, un Dāvids ar saviem vīriem tos paņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Un Fīlisti atkal cēlās un apmetās Refaīm ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Un Dāvids vaicāja To Kungu, un Tas sacīja: necelies viņiem pretī, bet met līkumu viņiem mugurā un uzbrūc tiem pret tiem raudu kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Un kad tu dzirdēsi soļu troksni raudu koku galos, tad traucies, jo Tas Kungs tad ir izgājis tavā priekšā, kaut Fīlistu lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Un Dāvids darīja, kā Tas Kungs tam bija pavēlējis, un kāva Fīlistus no Ģibejas līdz Gazerai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Pēc tam Dāvids atkal sapulcināja visus jaunos vīrus iekš Israēla, trīsdesmit tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Un Dāvids cēlās un nogāja ar visiem ļaudīm, kas pie viņa bija, uz Baālu Jūdā (Kiriatjearimu), ka no turienes atvestu Dieva šķirstu, pie kā top piesaukts tas vārds, Tā Kunga Cebaot vārds, kas sēž pār ķerubiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Un tie veda Dieva šķirstu ar jauniem ratiem un ņēma to no Abinadaba nama, kas tai pakalnā; un Uza un Ahijus, Abinadaba dēli, vadīja tos jaunos ratus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Kad tie nu Dieva šķirstu ņēma no Abinadaba nama, kas tai pakalnā, tad Ahijus gāja šķirsta priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Un Dāvids un viss Israēla nams līksmojās Tā Kunga priekšā ar visādiem priežu koka mūzikas rīkiem, ar koklēm un ar stabulēm un ar bungām un ar zvārguļiem un ar pulkstenīšiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Kad tie nu nāca pie Nahona klona, tad Uza izstiepa roku pie Dieva šķirsta un to turēja, jo vēršiem kājas slīdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Tad Tā Kunga dusmas iedegās pret Uzu, un Dievs viņu tur kāva tās drošības dēļ un viņš tur nomira pie Dieva šķirsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Un Dāvidam gāja pie sirds, ka Tas Kungs tādu robu cirtis, Uzu sizdams, un to vietu nosauca PerecUza (Uzas robs) līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Un Dāvids bijās To Kungu tai dienā un sacīja: kā lai pārnāk Tā Kunga šķirsts pie manis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Un Dāvids Tā Kunga šķirstu negribēja vest pie sevis uz Dāvida pilsētu, bet Dāvids to lika vest ObedEdoma, tā Gatieša, namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Un Tā Kunga šķirsts palika ObedEdoma, tā Gatieša, namā trīs mēnešus, un Tas Kungs svētīja ObedEdomu un visu viņa namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Tad ķēniņam Dāvidam teica un sacīja: Tas Kungs ObedEdoma namu ir svētījis ar visu, kas tam pieder, Dieva šķirsta labad. Tad Dāvids gāja un pārveda Dieva šķirstu no ObedEdoma nama uz Dāvida pilsētu ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Un kad Tā Kunga šķirsta nesēji sešus soļus bija pagājuši, tad viņš upurēja vērsi un barotu teļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Un Dāvids dejoja ar visu spēku Tā Kunga priekšā, un Dāvids bija apjozies ar nātnu efodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Tā Dāvids un viss Israēla nams pārveda Tā Kunga šķirstu ar gavilēšanu un bazūņu skaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Kad nu Tā Kunga šķirsts nāca Dāvida pilsētā, tad Mikale, Saula meita, skatījās pa logu un redzēja ķēniņu Dāvidu Tā Kunga priekšā dejojam un lecam un to nicināja savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Un tie ieveda Tā Kunga šķirstu un to nolika savā vietā tās telts vidū, ko Dāvids priekš tā bija uzcēlis. Un Dāvids upurēja dedzināmos upurus un pateicības upurus Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Kad nu Dāvids bija pabeidzis upurēt dedzināmos upurus un pateicības upurus, tad viņš tos ļaudis svētīja Tā Kunga Cebaot vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Un visiem ļaudīm, visai Israēla draudzei, gan vīriem, gan sievām, viņš izdalīja ikkatram pa karašai un pa gaļas gabalam un pa vīnogu rausim. Un visi ļaudis nogāja ikviens savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Kad nu Dāvids atpakaļ griezās, sveicināt savu namu, tad Mikale, Saula meita, Dāvidam izgāja pretī un sacīja: cik ļoti Israēla ķēniņš šodien pagodinājies, kas šodien priekš savu kalpu kalponēm ir atsedzies, tā kā atsedzās neliešu ļaudis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Bet Dāvids sacīja uz Mikali: Tā Kunga priekšā es esmu līksmojies, kas mani izredzējis tava tēva vietā un visa viņa nama vietā, mani ieceldams par valdītāju Tā Kunga ļaudīm, Israēlim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Un es vēl vairāk pazemošos nekā tā, un būšu zems savās acīs, un ar tām kalponēm, par ko tu runājusi, ar tām es gribu tikt godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Un Mikale, Saula meita, palika bez bērna līdz savai miršanas dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Un notikās, kad ķēniņš savā namā sēdēja un Tas Kungs viņam bija mieru devis no visiem viņa ienaidniekiem visapkārt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Tad ķēniņš sacīja uz pravieti Nātanu: redzi, es dzīvoju ciedru namā, un Tā Kunga šķirsts mīt starp telts deķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Tad Nātans sacīja uz ķēniņu: ej un dari visu, kas tavā sirdī, jo Tas Kungs ir ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Bet tai pašā naktī Tā Kunga vārds notika uz Nātanu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Ej un saki Dāvidam, Manam kalpam: tā saka Tas Kungs: Vai tev būs Man namu celt, Man par mājas vietu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Jo Es namā neesmu mitis no tās dienas, kad Israēla bērnus esmu izvedis no Ēģiptes, līdz šai dienai, bet esmu staigājis teltī un dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Visu to laiku, kad Es ar visiem Israēla bērniem esmu staigājis, vai esmu vienu vārdu runājis uz kādu no Israēla ciltīm, kam Es pavēlējis, Manus Israēla ļaudis ganīt, sacīdams: kāpēc jūs Man neuztaisiet ciedru namu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Tad nu tev tā būs sacīt uz Manu kalpu Dāvidu: tā saka Tas Kungs Cebaot: Es tevi no ganības, no sīkiem lopiem esmu ņēmis, būt valdītājam pār Maniem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Un Es ar tevi esmu bijis visur, kur esi staigājis, un esmu izdeldējis visus tavus ienaidniekus tavā priekšā un tev darījis augstu vārdu, kā lieliem kungiem vārds ir virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Un Saviem Israēla ļaudīm Es esmu vietu gādājis un tos dēstījis, ka tie savā vietā dzīvo un vairs netop šaubīti, un ļauni ļaudis tos vairs nespaida, kā senāk');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Un no tās dienas, kad Es soģus iecēlu pār Saviem Israēla ļaudīm. Un Es tev dodu mieru no visiem taviem ienaidniekiem. Un Tas Kungs tev sludina, ka Tas Kungs tev grib namu celt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Kad tavs laiks būs pagājis un tu dusēsi līdz ar saviem tēviem, tad Es uzcelšu tavu dzimumu pēc tevis, kas no tavām miesām nāks, tam Es apstiprināšu viņa valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Tas uztaisīs namu Manam vārdam, un Es apstiprināšu viņa valstības krēslu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Es viņam būšu par tēvu, un viņš Man būs par dēlu. Kad tas būs noziedzies, tad Es viņu pārmācīšu ar cilvēku rīkstēm un ar cilvēka bērnu sitieniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Bet Savu žēlastību Es no viņa neatraušu, kā Es to esmu atrāvis no Saula, ko Es esmu atmetis tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Un tavs nams un tava valstība pastāvēs tavā priekšā mūžīgi: tavs goda krēsls būs stiprs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Un pēc visiem šiem vārdiem un pēc visas šīs parādīšanas Nātans tā runāja uz Dāvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Tad ķēniņš Dāvids nāca un palika Tā Kunga priekšā un sacīja: kas es esmu Kungs, Dievs? Un kas ir mans nams, ka Tu mani līdz šejienei esi vadījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Un taču tas vēl ir maz Tavās acīs, Kungs, Dievs, bet Tu Sava kalpa namam esi runājis arī par nākošiem ilgiem laikiem, un tā pēc cilvēka vīzes, Kungs, Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Un ko lai nu Dāvids vēl uz Tevi runā? Jo Tu pazīsti Savu kalpu, Kungs, Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Sava vārda dēļ un pēc Savas sirds Tu visas šās lielās lietas esi darījis un tās Savam kalpam sludinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Tāpēc Tu esi augsts, Kungs Dievs. Jo neviena nav kā Tu, un Dieva nav kā Tu vien pēc visa, ko esam dzirdējuši savām ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Un kur gan kāda tauta virs zemes kā Tavi ļaudis, kā Israēls? Ko Dievs būtu gājis atpestīt Sev par ļaudīm un celt Sev vārdu un priekš viņiem darīt tādas lielas briesmīgas lietas Savai zemei, Savu ļaužu priekšā, ko Tu no Ēģiptes atpestījis, no pagāniem un viņu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Un Tu Savus Israēla ļaudis Sev esi apstiprinājis par Saviem ļaudīm mūžīgi, un Tu, Kungs, tiem esi palicis par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Un nu, Kungs Dievs, to vārdu, ko Tu esi runājis par Savu kalpu un par viņa namu, piepildi to mūžīgi, un izdari, ko Tu esi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Tad Tavs vārds taps paaugstināts mūžīgi, un sacīs: Tas Kungs Cebaot ir Dievs pār Israēli, un Tava kalpa Dāvida nams pastāvēs Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Jo Tu, Kungs Cebaot, Israēla Dievs, Sava kalpa ausi esi atdarījis un sacījis: Es tev celšu namu. Tāpēc Tavs kalps iedrošinājies ar šo lūgšanu Tevi pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Tad nu, Kungs, Dievs, Tu esi Dievs un Tavi vārdi ir patiesība, un Tu šo labumu uz Savu kalpu esi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Un tas lai nu ir Tavs prāts, svētīt Sava kalpa namu, ka tas ir mūžīgi Tavā priekšā. Jo Tu, Kungs, Dievs, to esi runājis, un ar Tavu svētību Tava kalpa nams būs svētīts mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Un notikās, ka pēc tam Dāvids sita Fīlistus un tos pārvarēja, un Dāvids atņēma valdīšanas iemauktus Fīlistu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Viņš sita arī Moabiešus un pie zemes nometis viņš tos mēroja ar auklu, un mēroja divas daļas nokaujamos un vienu pilnu daļu, ko pameta dzīvus. Tā Moabieši Dāvidam palika par kalpiem un nesa dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Un Dāvids sita arī HadadEzeru, Rekaba dēlu, Cobas ķēniņu, kad šis nogāja, savu varu atkal uzcelt pie Eifrat upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Un Dāvids tam paņēma tūkstoš un septiņsimt jātniekus un divdesmit tūkstoš kājniekus, un darīja visus zirgus tizlus, un no tiem atlicināja simts zirgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Un Sīrieši no Damaskus nāca palīgā HadadEzeram, Cobas ķēniņam, bet Dāvids kāva no Sīriešiem divdesmit un divtūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Un Dāvids ielika karavīrus Damaskū Sīrijā. Un Sīrieši Dāvidam palika par kalpiem un nesa dāvanas; un Tas Kungs Dāvidam visur palīdzēja, kurp viņš gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Un Dāvids ņēma tās priekšturamās zelta bruņas, kas HadadEzera kalpiem bija, un tās pārnesa uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Un no Betas un Berotajas, HadadEzera pilsētām, ķēniņš Dāvids paņēma arī daudz vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Kad nu Tojus, Hamatas ķēniņš, dzirdēja, ka Dāvids bija kāvis visu HadadEzera karaspēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Tad Tojus sūtīja savu dēlu Joramu pie ķēniņa Dāvida, vaicāt pēc viņa labklāšanās un viņam pateikties par to, ka viņš pret HadadEzeru bija karojis un to bija kāvis, (jo Tojum bija karš ar HadadEzeru) un viņa rokā bija sudraba un zelta un vara trauki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Arī tos ķēniņš Dāvids svētīja Tam Kungam, līdz ar to sudrabu un zeltu, ko viņš bija svētījis no visām tautām, ko bija pārvarējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'No Sīrijas un no Moaba un no Amona bērniem un no Fīlistiem un no Amalekiešiem un no HadadEzera, Rekaba dēla, Cobas ķēniņa, laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Un Dāvids pelnījās augstu slavu, pārnākdams no Sīriešu kaušanas, kad sāls ielejā bija kāvis astoņpadsmit tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Un viņš nolika karavīrus Edomā, visā Edomā viņš nolika karavīrus, un visi Edomieši palika Dāvidam par kalpiem, un Tas Kungs palīdzēja Dāvidam visur, kurp tas gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Tā Dāvids valdīja pār visu Israēli, un Dāvids nesa tiesu un taisnību visiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Un Joabs, Cerujas dēls, bija karaspēka virsnieks un Jehošafats, Aķiluda dēls, bija kanclers,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Un Cadoks, Aķitaba dēls, un Aķimeleks, Abjatara dēls, bija priesteris, un Serajus bija rakstu vedējs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Un Benajus, Jojadas dēls, bija virsnieks pār tiem Krietiem un Plietiem, bet Dāvida dēli bija lielkungi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Un Dāvids sacīja: vai vēl ir kāds, kas atlicies no Saula nama, ka es tam žēlastību parādu Jonatāna dēļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Un Saula namam bija kalps, Cībus vārdā, un tas tapa aicināts Dāvida priekšā. Un ķēniņš uz to sacīja: vai tu esi Cībus? Un viņš sacīja: esmu, tavs kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Un ķēniņš sacīja: vai vēl kāds nav no Saula nama, ka es Dieva žēlastību tam parādu? Un Cībus sacīja uz ķēniņu: Vēl ir viens Jonatāna dēls, tizls uz abām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Un ķēniņš uz to sacīja: kur tas ir? Un Cībus sacīja uz ķēniņu: redzi, viņš ir Mahira, Amiēļa dēla, namā, Lodabarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Tad ķēniņš Dāvids nosūtīja un to ņēma no Mahira, Amiēļa dēla, nama, no Lodabaras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Kad nu Mefibošets, Jonatāna dēls, Saula dēla dēls, pie Dāvida nāca tad viņš metās uz savu vaigu un klanījās. Un Dāvids sacīja: Mefibošet! Un viņš sacīja: redzi, še tavs kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Un Dāvids uz to sacīja: nebīsties, es tiešām tev parādīšu žēlastību tava tēva Jonatāna dēļ, un tev atdošu visus tava tēva Saula tīrumus, un tev būs vienmēr maizi ēst pie mana galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Un tas paklanījās un sacīja: kas tavs kalps tāds ir, ka tu uzlūko nomirušu suni, kāds es esmu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Tad ķēniņš aicināja Cību, Saula kalpu, un uz to sacīja: visu, kas Saulam un viņa namam piederēja, to es esmu devis tava kunga dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Tāpēc strādā tu viņam to zemi, tu ar saviem dēliem un ar saviem kalpiem, un savāc, ka tava kunga dēlam ir maizes ko ēst, un Mefibošets, tava kunga dēls, lai vienmēr ēd maizi pie mana galda. Bet Cībum bija piecpadsmit dēli un divdesmit kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Un Cībus sacīja uz ķēniņu: visu, ko mans kungs, tas ķēniņš, savam kalpam pavēl, to tavs kalps darīs. Un Mefibošets lai ēd pie mana galda tāpat, kā viens no ķēniņa bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Un Mefibošetam bija mazs dēls, vārdā Miha, un visi, kas Cībus namā dzīvoja, tie Mefibošetam bija par kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Un Mefibošets dzīvoja Jeruzālemē, tāpēc ka viņš vienmēr ēda pie ķēniņa galda. Un viņš bija tizls uz abām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Un pēc tam Amona bērnu ķēniņš nomira, un viņa dēls Anons palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Tad Dāvids sacīja: es darīšu žēlastību pie Anona, Nahasa dēla, tā kā viņa tēvs žēlastību darījis pie manis. Un Dāvids nosūtīja un lika viņu iepriecināt caur saviem kalpiem par viņa tēvu; un Dāvida kalpi nāca uz Amona bērnu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Tad Amona bērnu lielkungi sacīja uz savu kungu Anonu: vai Dāvids tavu tēvu godina tavās acīs, ka viņš ir sūtījis iepriecinātājus pie tevis? Vai Dāvids savus kalpus nav tāpēc sūtījis pie tevis, ka viņš šo pilsētu izklausa un izlūko un izposta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Tad Anons ņēma Dāvida kalpus un tiem nodzina pusbārdu un tiem nogrieza vienu drēbju pusi līdz pašiem gurniem un tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Kad tas nu Dāvidam tapa zināms, tad viņš tiem sūtīja pretī, jo šie vīri bija ļoti apsmieti. Un ķēniņš tiem lika sacīt: palieciet Jērikū, tiekams jūsu bārda būs ataugusi, un tad nāciet atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Kad nu Amona bērni redzēja, ka tie bija palikuši smirdoši pie Dāvida, tad Amona bērni nosūtīja un saderēja no BetRekabas Sīriešiem un no Cobas Sīriešiem divdesmit tūkstoš kājniekus un no Maākas ķēniņa tūkstoš vīrus un no Tobas vīriem divpadsmit tūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kad Dāvids to dzirdēja, tad viņš sūtīja Joabu un visu to vareno karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Un Amona bērni izgāja un taisījās uz kaušanos vārtu priekšā, bet tie Sīrieši no Cobas un Rekabas un tie vīri no Tobas un Maākas bija vieni paši savrup laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Kad nu Joabs redzēja, ka karš pret viņu taisījās no priekšas un no aizmugures, tad viņš izlasīja no visiem jauniem Israēla vīriem un nostājās Sīriešiem pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Un tos citus ļaudis viņš deva savam brālim Abizajum rokā, un tas nostājās pret Amona bērniem. Un viņš sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Ja Sīrieši būs stiprāki nekā es, tad nāc tu man palīgā, bet ja Amona bērni būs stiprāki nekā tu, tad es tev iešu palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Turies stipri un lai stipri stāvam priekš mūsu ļaudīm un priekš mūsu Dieva pilsētām, bet Tas Kungs lai dara, kā Viņam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Un Joabs ar tiem ļaudīm, kas pie viņa bija, gāja kauties Sīriešiem virsū, bet šie bēga viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Un kad Amona bērni to redzēja, ka Sīrieši bēga, tad tie arīdzan bēga Abizajus priekšā un nāca pilsētā, un Joabs griezās atpakaļ no Amona bērniem un nāca uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Kad nu Sīrieši redzēja, ka Israēla priekšā bija sakauti, tad tie atkal sapulcējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Un HadadEzers nosūtīja un lika tiem Sīriešiem nākt, kas bija viņpus upes, un tie nāca uz Elamu, un Zobaks, HadadEzera kara lielskungs, gāja viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Kad tas Dāvidam tapa sacīts, tad viņš sapulcināja visu Israēli un pārgāja pār Jardāni un nāca uz Elamu, un Sīrieši nostājās Dāvidam pretī un ar to kāvās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Bet Sīrieši bēga Israēla priekšā, un Dāvids nokāva no Sīriešiem septiņsimt ratus un četrdesmit tūkstoš jātniekus; viņš sita arī Zobaku, viņu kara lielkungu, ka tas tur nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Kad nu visi ķēniņi, kas bija HadadEzera kalpi, redzēja, ka bija sakauti Israēla priekšā, tad tie derēja mieru ar Israēli un viņam kalpoja, un Sīrieši bijās, uz priekšu nākt palīgā Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Un kad gads bija pagājis, ap to laiku, kad ķēniņi mēdz iziet, tad Dāvids sūtīja Joabu un savus kalpus viņam līdz un visu Israēli, un tie postīja Amona bērnus un apmetās pret Rabu; bet Dāvids palika Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Un notikās ap vakara laiku, ka Dāvids cēlās no savas gultas un staigāja pa ķēniņa nama jumtu un redzēja no jumta sievu mazgājamies, un šī sieva bija ļoti skaista no skata.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Un Dāvids nosūtīja un lika vaicāt pēc tās sievas; tad sacīja: tā ir Batseba, Elijama meita, Hetieša Ūrijas sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Tad Dāvids sūtīja vēstnešus un to lika atvest, un tā nāca pie viņa un viņš pie tās gulēja, un kad viņa no savas nešķīstības bija šķīstījusies, tad viņa atkal gāja mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Un tā sieva tapa grūta. Tad viņa nosūtīja un deva Dāvidam ziņu un sacīja: es esmu grūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Tad Dāvids sūtīja pie Joaba sacīdams: sūti to Etieti Ūriju pie manis. Un Joabs sūtīja Ūriju pie Dāvida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Kad nu Ūrija pie viņa atnāca, tad Dāvids vaicāja: kā iet Joabam, kā iet ļaudīm un kā iet karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Un Dāvids sacīja uz Ūriju: noej savā namā un mazgā savas kājas. Un kad Ūrija no ķēniņa nama izgāja, tad viņam ķēniņa dāvanas tapa nestas pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Bet Ūrija apgūlās priekš ķēniņa nama durvīm ar visiem sava kunga kalpiem un negāja mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Un Dāvidam deva ziņu un sacīja: Ūrija nav gājis uz mājām. Tad Dāvids sacīja uz Ūriju: Vai tu nenāci no ceļa? Kāpēc tu nenoej savā namā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Un Ūrija sacīja uz Dāvidu: Dieva šķirsts un Israēls un Jūda paliek teltīs, un mans kungs Joabs un mana kunga kalpi mīt laukā; vai tad es ietu mājās ēst un dzert un pie savas sievas gulēt? Tik tiešām kā tu dzīvs un tava dvēsele dzīva, es to nedarīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Tad Dāvids sacīja uz Ūriju: paliec arī šodien šeitan, tad es tev rītu atlaidīšu. Tā Ūrija palika Jeruzālemē šo un otru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Un Dāvids to aicināja, ka tas viņa priekšā ēda un dzēra, un viņš to piedzirdināja. Un vakarā viņš izgāja apgulties savās cisās ar sava kunga kalpiem, un viņš nenogāja mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Un otrā rītā Dāvids rakstīja grāmatu Joabam un to sūtīja caur Ūriju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Un tai grāmatā viņš tā bija rakstījis: nostādiet Ūriju tai vietā, kur tā visgrūtākā kaušanās, un novēršaties aiz viņa, ka viņš top kauts un mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Un notikās, kad Joabs to pilsētu aplenca, tad viņš nostādīja Ūriju tādā vietā, kur viņš zināja, ka tur bija stipri vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Kad nu pilsētas vīri izgāja un ar Joabu kāvās, tad krita kādi no tiem ļaudīm, no Dāvida kalpiem, un Etietis Ūrija arī nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Tad Joabs sūtīja un deva Dāvidam ziņu par visām karalietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Un viņš pavēlēja tam vēstnesim un sacīja: kad tu būsi ķēniņam izstāstījis visas karalietas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Un ķēniņam dusmas celsies un viņš uz tevi sacīs: kāpēc jūs tik tuvu pie pilsētas esat gājuši kauties? Vai jūs nezinājāt, ka no mūra šaus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kas Abimeleku, JerubBezeta dēlu, ir nokāvis? Vai sieva uz viņu nemeta dzirnu akmeni no mūra, ka tas Tebecā nomira? Kāpēc esat gājuši tik tuvu pie mūra? Tad saki: tavs kalps Ūrija, tas Etietis, arīdzan nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Un tas vēstnesis nogāja un nāca un stāstīja Dāvidam visu, par ko Joabs viņu bija sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Un tas vēstnesis sacīja uz Dāvidu: tie vīri bija stiprāki nekā mēs, un iznāca pret mums laukā, bet mēs viņiem pretī turējāmies līdz pat vārtu durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Tad strēlnieki no mūra šāva uz taviem kalpiem, ka kādi no ķēniņa kalpiem nomira,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Un tavs kalps Ūrija, tas Etietis, arīdzan nomiris. Tad Dāvids sacīja uz to vēstnesi: Tā saki uz Joabu: lai tev sirds neēdās šīs lietas dēļ, jo zobens rij te šo, te citu, stāvi jo stipri karā pret to pilsētu un izposti to, - un tā iedrošini viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Kad nu Ūrijas sieva dzirdēja, ka viņas vīrs Ūrija bija miris, tad viņa gaudās par savu kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Un kad gaudu laiks bija pagājis, tad Dāvids nosūtīja un to ņēma savā namā, un tā viņam palika par sievu un viņam dzemdēja dēlu. Bet šī lieta, ko Dāvids darīja, Tam Kungam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Un Tas Kungs sūtīja Nātanu pie Dāvida. Un tas gāja pie viņa un uz to sacīja: divi vīri bija vienā pilsētā, viens bagāts un otrs nabags.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Un tam bagātam bija ļoti daudz avju un vēršu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Bet tam nabagam nebija it nekā kā viens vienīgs jēriņš, ko viņš bija pircis un uzaudzinājis, un tas pie viņa bija uzaudzis kopā ar viņa bērniem; tas ēda no viņa kumosa un dzēra no viņa biķera un gulēja viņa klēpī un bija viņam tā kā bērns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Kad nu pie tā bagātā vīra atnāca ceļinieks, tad tam bija žēl ņemt no savām avīm un no saviem vēršiem, ko laba sataisīt tam ceļiniekam, kas pie viņa bija atnācis, un viņš ņēma tā nabaga vīra jēriņu un to sataisīja tam vīram, kas pie viņa bija atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Tad Dāvids dusmās iedegās pret to vīru varen ļoti un viņš sacīja uz Nātanu: tik tiešām kā Tas Kungs dzīvs, tas vīrs, kas to darījis, pelnījis nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Un to jēru tam būs četrkārtīgi atdot, tāpēc ka viņš tā darījis un ka nav žēlojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Tad Nātans sacīja uz Dāvidu: tu esi tas vīrs. Tā saka Tas Kungs, Israēla Dievs: Es tevi par ķēniņu esmu svaidījis Israēlim, un tevi esmu izpestījis no Saula rokas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Un tev esmu devis tava kunga namu, un tava kunga sievas tavā klēpī, un Es tev esmu devis arī Israēla un Jūda namu. Un ja tas vēl nepietiek, tad Es šo un to vēl gribēju pielikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Kāpēc tu tad Tā Kunga vārdu esi laidis pār galvu, darīdams, kas ļauns priekš Viņa acīm? To Etieti Ūriju tu esi nokāvis ar zobenu un viņa sievu sev ņēmis par sievu, bet viņu tu esi nokāvis ar Amona bērnu zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nu tad zobens neatstāsies no tava nama ne mūžam, tāpēc ka tu Mani esi nicinājis un tā Hetieša Ūrijas sievu ņēmis sev par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Tā saka Tas Kungs: redzi, Es vedīšu nelaimi pār tevi no tava paša nama un ņemšu tavas sievas priekš tavām acīm un tās došu tavam tuvākam; tas pie tavām sievām gulēs pašā saulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Jo tu to esi darījis slepeni, bet Es to darīšu visa Israēla priekšā un pašā saulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Tad Dāvids sacīja uz Nātanu: es esmu grēkojis pret To Kungu. Un Nātans sacīja uz Dāvidu: tad nu Tas Kungs arī tavus grēkus ir atņēmis; tev nebūs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Tomēr tāpēc ka tu caur šo lietu Tā Kunga ienaidniekiem esi devis tiešām iemeslu zaimot, tad arī tam dēlam, kas tev dzimis, būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Un Nātans gāja savā namā. Un Tas Kungs sita to bērnu, ko Ūrijas sieva Dāvidam bija dzemdējusi, ka tas palika ļoti slims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Un Dāvids meklēja Dievu par to bērnu, un Dāvids gavēja un iegāja un gulēja par nakti pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Tad visi viņa nama vecaji gāja pie viņa un viņu gribēja uzcelt no zemes, bet viņš negribēja un neēda maizes ar tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Un septītā dienā tas bērns nomira. Un Dāvida kalpi bijās viņam sacīt, ka tas bērns miris. Jo tie sacīja: redzi, kamēr tas bērns vēl bija dzīvs, tad mēs ar viņu runājām, un viņš negribēja mūsu balsi klausīt, kā tad lai viņam sakām, ka tas bērns miris, lai viņš nepadara ko ļauna?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Bet Dāvids redzēja, ka viņa kalpi klusiņām savā starpā runāja, un Dāvids manīja, ka tas bērns miris. Un Dāvids sacīja uz saviem kalpiem: vai tas bērns miris? Un tie sacīja: miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Tad Dāvids cēlās no zemes un mazgājās un svaidījās un pārmija savas drēbes un gāja Tā Kunga namā un pielūdza. Pēc viņš nāca savā namā un pavēlēja, lai viņam maizi ceļ priekšā, un ēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Tad viņa kalpi uz viņu sacīja: kas tas ir, ko tu dari? Kad tas bērns bija dzīvs, tad tu gavēji un raudāji, un kad nu tas bērns miris, tad tu celies un ēdi maizi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Un viņš sacīja: kamēr tas bērns vēl bija dzīvs, es gavēju un raudāju, jo es domāju, kas zin, vai Tas Kungs par mani neapžēlosies, ka tas bērns paliek dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Bet kad tas nu miris, kāpēc man būs gavēt? Vai es to vēl varēšu vest atpakaļ? Es gan iešu pie viņa, bet viņš pie manis atpakaļ negriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Un Dāvids iepriecināja Batsebu, savu sievu, un iegāja pie tās un gulēja pie tās. Un tā dzemdēja dēlu un tas nosauca viņa vārdu Salamanu. Un Tas Kungs to mīlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Un viņš deva pavēli caur pravieti Nātanu, un šis nosauca viņa vārdu JedidJa (t.i. Dieva mīlēts) Tā Kunga dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Un Joabs karoja pret Rabu, Amona bērnu pilsētu, un ieņēma to ķēniņa pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Tad Joabs sūtīja vēstnešus pie Dāvida un sacīja: es pret Rabu esmu karojis un pilsētas lejas daļu jau ieņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Tad nu sapulcini tos atlikušos ļaudis un apmeties pret to pilsētu un ieņem to, lai es neieņemu to pilsētu, un slava par to lai nepaliek man.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Tad Dāvids sapulcināja visus ļaudis un nogāja uz Rabu un karoja pret to un to ieņēma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Un ņēma viņu ķēniņa kroni no viņa galvas, tam svars bija viens talents zelta un dārgu akmeņu, un tas Dāvidam tapa likts uz galvu; viņš arī ļoti lielu laupījumu izveda no tās pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Un tos ļaudis, kas tur bija, viņš izveda un tos lika apakš zāģiem un apakš kuļamiem dzelzs ruļļiem un apakš dzelzs cirvjiem, un tos lika ķieģeļu cepļos. Tā viņš darīja visām Amona bērnu pilsētām. Un Dāvids un visi ļaudis griezās atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Un notikās pēc tam, Absalomam, Dāvida dēlam, bija skaista māsa, Tamāra vārdā, un Amnons, Dāvida dēls, to iemīlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Un Amnons gauži nobēdājās savas māsas Tamāras dēļ, un viņa bija jumprava, tā ka Amnonam rādījās grūta lieta, viņai ko darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Bet Amnonam bija draugs, ar vārdu Jonadabs, Šimejus, Dāvida brāļa, dēls, un Jonadabs bija ļoti gudrs vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Tas uz viņu sacīja: kāpēc tu tāds izdilis, tu ķēniņa dēls, un jo dienas jo vairāk? Vai to man negribi sacīt? Tad Amnons uz viņu sacīja: es mīlu Tamāru, sava brāļa Absaloma māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Un Jonadabs uz to sacīja: gulies savā gultā un izliecies slims. Kad nu tavs tēvs nāk, tevi apraudzīt, tad saki uz to, lai jel mana māsa, Tamāra, nāk un man dod maizes ēst un taisa priekš manām acīm ēdienu, ka es to redzu un ēdu no viņas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Tad Amnons gūlās un izlikās slims. Kad nu ķēniņš nāca, viņu apraudzīt, tad Amnons sacīja uz ķēniņu: lai jel mana māsa Tamāra nāk, un sataisa kādus divus raušus priekš manām acīm, ka es ēdu no viņas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Tad Dāvids sūtīja namā pie Tamāras un sacīja: ej jel Amnona, sava brāļa, namā un taisi viņam ēdienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Un Tamāra nogāja Amnona, sava brāļa namā, un viņš gulēja gultā. Un tā ņēma mīklu un mīcīja un taisīja raušus priekš viņa acīm un cepa tos raušus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Un viņa ņēma pannu un no tās izlika viņa priekšā, bet viņš liedzās ēst. Tad Amnons sacīja: lai visi no manis iziet ārā. Tad visi izgāja ārā no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Tad Amnons sacīja uz Tamāru: nes man to ēdienu istabā, ka es ēdu no tavas rokas. Tad Tamāra ņēma tos raušus, ko bija taisījusi, un nesa tos savam brālim Amnonam istabā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Kad tā tos nu viņam pienesa, ka ēstu, tad viņš to sagrāba un uz to sacīja: nāc šurp, guli pie manis, mana māsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Bet viņa uz to sacīja: nē, mans brāli, nepiesmej mani, jo tā tas nepieklājās iekš Israēla, - nedari tādu trakumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Jo kur es paliktu ar savu kaunu? Un tu būtu kā ģeķis iekš Israēla. Bet runā jel ar ķēniņu, jo viņš mani tev neliegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Bet tas viņas balsij negribēja klausīt, bet stiprāks būdams nekā viņa to piesmēja un piegulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Pēc Amnons viņu nīdēdams ienīdēja; un tas naids, ar ko viņš to ienīdēja, bija lielāks nekā tā mīlestība, ar ko viņš to bija mīlējis. Un Amnons uz to sacīja: celies un ej projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Tad viņa uz to sacīja: ne tā! Šis ļaunums būtu lielāks nekā tas pirmais, ko tu man darījis, ka tu mani izdzen. Bet viņš tai negribēja klausīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Un viņš sauca savu puisi, kas viņam kalpoja, un sacīja: izraidi jel šo no manis ārā un aizslēdz durvis aiz viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Un viņai bija svārki ar piedurknēm, jo ar tādiem uzvalkiem ķēniņa meitas ģērbās, kas bija jumpravas. Un kad viņa sulainis to bija izraidījis un durvis aiz viņas aizslēdzis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Tad Tamāra meta pelnus uz savu galvu un saplēsa tos svārkus ar piedurknēm, kas tai bija mugurā, un lika savu roku uz savu galvu un gāja apkārt brēkdama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Un viņas brālis Absaloms uz to sacīja: vai tavs brālis Amnons pie tevis bija? Nu tad, mana māsa, cieti klusu, viņš ir tavs brālis, neņem šo lietu tā pie sirds. Tā Tamāra palika atstāta sava brāļa Absaloma namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Un kad ķēniņš Dāvids visu šo dzirdēja, tad viņš ļoti apskaitās. Bet Absaloms nerunāja ar Amnonu nedz ļaunu nedz labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Jo Absaloms ienīdēja Amnonu par to, ka šis bija piesmējis Tamāru, viņa māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Un pēc kādiem diviem gadiem Absalomam bija avju cirpšana BaālAcorā pie Efraīma. Un Absaloms aicināja visus ķēniņa bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Un Absaloms nāca pie ķēniņa un sacīja: redzi jel, nu tavam kalpam ir avju cirpšana, kaut ķēniņš ar saviem kalpiem nāktu pie sava kalpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Bet ķēniņš sacīja uz Absalomu: nē, mans dēls, visi mēs neiesim, ka tevi neapgrūtinājam. Un viņš gan to lūdza, bet tas negribēja iet, bet viņu svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Tad Absaloms sacīja: ja tu negribi, tad lai jel mans brālis Amnons mums nāk līdz. Bet ķēniņš uz to sacīja: kāpēc lai tas iet līdz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Un kad Absaloms viņu vēl vairāk lūdza, tad viņš Amnonu tam laida līdz ar visiem ķēniņa bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Un Absaloms pavēlēja saviem puišiem un sacīja: raugāt jel, kad Amnona sirds būs priecīga no vīna, un es uz jums sacīšu: kaujiet Amnonu, - tad nokaujiet viņu, nebīstaties, jo es jums to esmu pavēlējis; turaties stipri un esat droši vīri!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Un Absaloma puiši darīja Amnonam, kā Absaloms bija pavēlējis. Tad visi ķēniņa bērni cēlās un metās ikkatrs uz savu zirgēzeli un bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Un tiem vēl ceļā esot, vēsts nāca pie Dāvida, un tur sacīja: Absaloms nokāvis visus ķēniņa bērnus, ka neviens no tiem nav atlicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Tad ķēniņš cēlās un saplēsa savas drēbes un metās pie zemes, un visi viņa kalpi stāvēja ar saplēstām drēbēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Un Jonadabs, Šimejus, Dāvida brāļa, dēls atbildēja un sacīja: nedomā, mans kungs, ka visi jaunekļi, ķēniņa dēli, ir nokauti, bet Amnons vien ir miris. Jo Absaloms to ir apņēmies no tās dienas, kad tas bija piesmējis viņa māsu Tamāru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Un lai nu mans kungs, tas ķēniņš, šo lietu tā neņem pie sirds, domādams, visus ķēniņa bērnus esam mirušus, jo Amnons vien ir miris. Un Absaloms bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Un vaktnieks pacēla savas acis un skatījās, un redzi, daudz ļaudis nāca pa ceļu aiz viņa gar kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Un Jonadabs sacīja uz ķēniņu: redzi, ķēniņa bērni nāk, tā kā tavs kalps sacījis, tā ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Un kad viņš bija beidzis runāt, redzi, tad tie ķēniņa dēli nāca un pacēla savu balsi un raudāja. Ir ķēniņš un visi viņa kalpi raudāja varen lielas raudas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Un Absaloms bēga un gāja pie Talmaja, Amijuda dēla, Gešuras ķēniņa. Bet (Dāvids) žēlojās pēc sava dēla mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Un Absaloms bēga un gāja uz Gešuru, tur viņš sabija trīs gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Un tas ķēniņu Dāvidu noturēja iziet pret Absalomu, jo viņš jau bija iepriecināts par Amnonu, ka tas miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Kad nu Joabs, Cerujas dēls, manīja, ka ķēniņa sirds pēc Absaloma ilgojās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Tad Joabs sūtīja uz Tekou un dabūja no turienes gudru sievu un uz to sacīja: liecies jel žēlojoties un apvelc sēru drēbes un nesvaidies ar eļļu un turies kā sieva, kas sen dienas sērojās par mironi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Un ej pie ķēniņa un runā uz to tā un tā. Un Joabs lika tos vārdus viņas mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Un tā Tekoiešu sieva sacīja uz ķēniņu, uz savu vaigu pie zemes mezdamās un klanīdamās: palīdzi, ķēniņ!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Un ķēniņš uz to sacīja: kas tev kait? Un viņa sacīja: kait gan, esmu atraitne un mans vīrs miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Un tad vēl tavai kalponei bija divi dēli, tie abi bārās laukā un tiem nebija starpnieka, tad viens sita otru un to nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Un redzi, visi radi cēlās pret tavu kalponi un saka: dod šurp to, kas savu brāli nokāvis, lai mēs viņu nokaujam par tā brāļa dzīvību, ko viņš nokāvis, un izdeldam arī šo mantinieku. Tā tie grib izdzēst manu dzirkstelīti, kas atlikusi, un neatstāt manam vīram ne vārda, ne pēcnākamais virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Tad ķēniņš uz to sievu sacīja: ej mājās, gan es tevis pēc pavēlēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Un tā Tekoiešu sieva sacīja uz ķēniņu: mans kungs un ķēniņ, lai tas noziegums paliek uz manis un uz mana tēva nama, bet ķēniņš un viņa goda krēsls lai paliek nenoziedzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Un ķēniņš sacīja: ja kas pret tevi runā, tad atved to pie manis, tad tam tevi vairs nebūs aizskart.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Un viņa sacīja: lai jel ķēniņš piemin To Kungu, savu Dievu, ka asins atriebēji nevairo to postu, ka tie manu dēlu nenomaitā. Tad viņš sacīja: tik tiešām kā Tas Kungs dzīvs, neviens no tava dēla matiem nekritīs pie zemes!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Tad tā sieva sacīja: lai jel tava kalpone vienu vārdu uz savu kungu, to ķēniņu, runā. Un viņš sacīja: runā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Un tā sieva sacīja: kāpēc tad tu tādu lietu esi nodomājis pret Dieva ļaudīm? Kad ķēniņš šo vārdu runājis, caur to viņš ir tā kā noziedzīgs, tāpēc ka ķēniņš savu atmesto neatved atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Jo mirt mums jāmirst un mēs esam kā ūdens, kas zemē izliets netop atkal sasmelts, un Dievs negrib dzīvību atņemt, bet domā uz to, ka neatmet arīdzan tādu, kas atmests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Nu tad es esmu nākusi ar savu kungu, to ķēniņu, šo vārdu runāt, jo tie ļaudis mani ir izbiedējuši. Tad tava kalpone sacīja: es runāšu jel ar ķēniņu, vai ķēniņš nedarīs, ko viņa kalpone saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Jo ķēniņš klausīs un izpestīs savu kalponi no tā vīra rokas, kas apņēmies mani un manu dēlu kopā izdeldēt no Dieva tautas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Un tava kalpone domāja, lai mana kunga, tā ķēniņa, vārds man ir par iepriecināšanu, jo mans kungs, tas ķēniņš, ir kā Dieva eņģelis, klausīdamies labu un ļaunu; bet Tas Kungs, tavs Dievs, lai ir ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Tad ķēniņš atbildēja un sacīja uz to sievu: neslēp man nekā, ko es tev vaicāšu. Un tā sieva sacīja: runā jel, mans kungs un ķēniņ!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Un ķēniņš sacīja: vai Joaba roka ar tevi nav visās šinīs lietās? Tad tā sieva atbildēja un sacīja: tik tiešām kā tava dvēsele dzīva, mans kungs un ķēniņ, citādi nav ne pa labo ne pa kreiso roku ar visu to, kā mans kungs, tas ķēniņš, ir runājis; jo tavs kalps Joabs vien, tas man to ir pavēlējis un visus šos vārdus licis tavas kalpones mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Šīs lietas nodomu gribēdams apslēpt, tavs kalps Joabs to ir darījis. Bet mans kungs ir gudrs pēc Dieva eņģeļa gudrības, zināt visu, kas virs zemes notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Un ķēniņš sacīja uz Joabu: redzi, es šo lietu esmu darījis. Ej tad un atved to puisi Absalomu atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Un Joabs klanījās uz savu vaigu pie zemes mezdamies un pateicās ķēniņam, un Joabs sacīja: šodien tavs kalps ir manījis, ka es žēlastību esmu atradis tavās acīs, mans kungs un ķēniņ, tāpēc ka ķēniņš sava kalpa vārdu paklausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Tā Joabs cēlās un gāja uz Gešuru un atveda Absalomu uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Un ķēniņš sacīja: lai viņš iet savā namā un nenāk priekš manām acīm. Tad Absaloms gāja savā namā un neredzēja ķēniņa vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Bet tāda vīra, tik skaista un ļoti slavējama kā Absaloms, nebija pa visu Israēli; no pēdām līdz galvas galam nekādas vainas pie viņa nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Un kad viņš savu galvu apcirpa, (tas notika gadu no gada, ka viņš to apcirpa, jo mati viņam bija visai smagi, tāpēc viņš tos nocirpa), tad viņa galvas mati svēra divsimt sēķeļus pēc ķēniņa svara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Un Absalomam piedzima trīs dēli un viena meita, Tamāra vārdā, tā bija ļoti skaista sieviete.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Tā Absaloms palika Jeruzālemē divus gadus un neredzēja ķēniņa vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Tāpēc Absaloms sūtīja pie Joaba, ka viņš to pie ķēniņa sūtītu, bet tas negribēja nākt pie viņa. Tad viņš sūtīja vēl otrreiz, un tas vēl negribēja nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Tad viņš sacīja uz saviem kalpiem: redzi, Joaba tīrums ir pie mana klātu, un viņam tur ir mieži; ejat un iededzinājiet to ar uguni. Tad Absaloma kalpi iededzināja to tīrumu ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Un Joabs cēlās un nāca Absaloma namā un uz to sacīja: kāpēc tavi kalpi manu tīrumu ar uguni ir iededzinājuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Un Absaloms sacīja uz Joabu: redzi, es pie tevis esmu sūtījis sacīdams: nāc šurp, ka es tevi pie ķēniņa sūtu un lieku sacīt, kāpēc es esmu nācis no Gešuras? Man būtu labāki, ka es vēl tur būtu. Bet nu es gribu ķēniņa vaigu redzēt, un ja vēl kāds noziegums ir pie manis, tad lai viņš mani nokauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Tad Joabs gāja pie ķēniņa un viņam to teica. Tad viņš aicināja Absalomu, un tas nāca pie ķēniņa un nometās uz savu vaigu pie zemes ķēniņa priekšā, un ķēniņš skūpstīja Absalomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Un pēc tam Absaloms sev sagādāja ratus un zirgus un piecdesmit vīrus, kas viņa priekšā skrēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Un Absaloms cēlās no rīta agri un nostājās ceļā pie vārtiem, un ja kam bija kāda tiesas lieta, par ko viņš pie ķēniņa nāca tiesāties, tad Absaloms to aicināja pie sevis un sacīja: no kuras pilsētas tu esi? Un kad tas sacīja: tavs kalps ir no šīs jeb tās Israēla cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Tad Absaloms uz to sacīja: redzi, tava lieta ir laba un taisna, bet tev nav izklausinātāja pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Un Absaloms uz to sacīja: ak! Kas mani celtu par zemes soģi, lai, ja kam kāds strīdus vai tiesas lieta būtu, nāktu pie manis un es tam gādātu taisnību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Un kad kāds pie viņa nāca un metās zemē, tad viņš izstiepa savu roku un to satvēra un to skūpstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Tā Absaloms darīja visam Israēlim, kas pie ķēniņa nāca tiesāties. Tā Absaloms zaga sirdi Israēla vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Un pēc četriem gadiem Absaloms sacīja uz ķēniņu: es gribu noiet un savu apsolījumu Hebronē izpildīt, ko es Tam Kungam solījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Jo tavs kalps ir solījumu solījis, kad es Gešurā Sīrijā dzīvoju, sacīdams: ja Tas Kungs mani tiešām vedīs atpakaļ uz Jeruzālemi, tad es kalpošu Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Tad ķēniņš uz to sacīja: ej ar mieru. Un viņš cēlās un gāja uz Hebroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Un Absaloms sūtīja izlūkus pie visām Israēla ciltīm un sacīja: kad jūs dzirdēsiet trumetes skaņu, tad jums būs sacīt: Absaloms ir ķēniņš Hebronē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Un ar Absalomu gāja divsimt vīri no Jeruzālemes, kas bija aicināti, bet tie gāja savā vientiesībā un nezināja it nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Absaloms sauca arī Ahitofelu no Ģilus, Dāvida padoma devēju, no viņa pilsētas Ģilus, kad viņš upurus upurēja. Un dumpinieku derība palika stipra un ļaudis pulcējās un vairojās pie Absaloma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Tad nāca vēstnesis pie Dāvida un sacīja: visu Israēla vīru sirds pieķērusies Absalomam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Tad Dāvids sacīja uz visiem saviem kalpiem, kas pie viņa bija Jeruzālemē: ceļaties un bēgsim, citādi mums glābšanās nav priekš Absaloma; ejat steigšus, ka viņš steigdamies mūs nepanāk un nepadara mums nelaimi un nekauj to pilsētu ar zobena asmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Tad ķēniņa kalpi uz ķēniņu sacīja: tā kā mans kungs, tas ķēniņš, nodomā, redzi, mēs esam tavi kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Un ķēniņš izgāja ar visu savu namu kājām. Un ķēniņš atstāja desmit liekas sievas, to namu sargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Tā nu ķēniņš ar visiem ļaudīm kājām izgāja un apstājās pie pēdējā nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Un visi viņa kalpi gāja viņam līdzās, ir visi Krieti un visi Plieti ir visi Gatieši, sešsimt vīri, kas viņam no Gatas bija līdz nākuši, tie gāja ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Tad ķēniņš sacīja uz Itaju no Gatas. Kam tu arīdzan mums gribi iet līdz? Ej atpakaļ un paliec pie ķēniņa, jo tu esi svešinieks un tik ienācējs savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Vakar tu esi atnācis, vai man šodien tevi būs maldināt, mums iet līdz? Jo es eju, kur varēdams; ej atpakaļ un ved savus brāļus līdz atpakaļ; žēlastība un uzticība lai ir ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Bet Itajus atbildēja ķēniņam un sacīja: tik tiešām kā Tas Kungs dzīvs, un kā mans kungs, tas ķēniņš, dzīvs, - tai vietā, kur mans kungs, tas ķēniņš, būs, lai būtu vai uz nāvi vai uz dzīvību, tur būs tavs kalps arīdzan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Un Dāvids sacīja uz Itaju: nāc tad, iesim! Tā Itajus no Gatas gāja līdz ar visiem saviem vīriem un ar visiem bērniem, kas pie viņa bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Un visa zeme raudāja lielas raudas, un visi ļaudis gāja garām. Un ķēniņš gāja pāri pār Kidronas upi, un visi ļaudis gāja pāri pa to ceļu uz tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Un redzi, arī Cadoks tur bija ar visiem Levitiem, kas Dieva derības šķirstu nesa; un tie nolika Dieva šķirstu un Abjatars tur pienāca - kamēr visi ļaudis no pilsētas bija izgājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Tad ķēniņš sacīja uz Cadoku: nes Dieva šķirstu atpakaļ pilsētā. Ja es žēlastību atradīšu Tā Kunga priekšā, tad Viņš mani vedīs atpakaļ un man liks redzēt Viņu pašu ar Viņa dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Bet ja Viņš tā sacīs: Man nav labs prāts pie tevis, - redzi, še es esmu, lai Viņš man dara, kā Viņam patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Un ķēniņš sacīja uz priesteri Cadoku: tu redzētāj, ej atpakaļ uz pilsētu ar mieru, un Aķimaācs, tavs dēls, un Jonatāns, Abjatara dēls, jūsu abi dēli ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Redziet, es gaidīšu tuksnesī pie braslām, tiekams kāda vēsts no jums atnāks un man dos ziņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Tā Cadoks un Abjatars Dieva šķirstu nesa atpakaļ uz Jeruzālemi un tur palika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Un Dāvids kāpa uz Eļļas kalnu un iedams raudāja un savu galvu bija aptinis un gāja pats basām kājām, arī tie ļaudis, kas pie viņa bija, ikkatrs savu galvu bija aptinis un gāja uz augšu un iedami raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Un Dāvidam teica un sacīja: Ahitofels ir starp dumpiniekiem pie Absaloma. Tad Dāvids sacīja: Kungs, dari jel Ahitofela padomu par ģeķību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Kad nu Dāvids nāca kalna galā, kur mēdza Dievu pielūgt, redzi, tad Uzajus, tas Arķiets, viņam nāca pretī ar saplēstiem svārkiem un zemi uz galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Un Dāvids uz to sacīja: ja tu man nāksi līdz, tad tu man būsi par nastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Bet ja tu iesi atpakaļ pilsētā un sacīsi uz Absalomu: es būšu tavs kalps, ķēniņ, kā citkārt esmu bijis tava tēva kalps, tā nu es būšu tavs kalps, - tad tu man iznīcināsi Ahitofela padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Un vai tur pie tevis nebūs tie priesteri Cadoks un Abjatars? Tāpēc visu, ko tu ķēniņa namā dzirdēsi, to saki tiem priesteriem, Cadokam un Abjataram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Redzi, tur ir viņu abi dēli, Aķimaācs Cadoka, un Jonatāns, Abjatara dēls, caur tiem jūs visu, ko dzirdat, sūtat pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Tā Uzajus, Dāvida draugs, gāja pilsētā, kad Absaloms nāca uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Kad nu Dāvids maķenīt no kalna gala bija nogājis, redzi, tad Cībus, Mefibošeta puisis, viņu sastapa ar pāri apkrautu ēzeļu, un uz tiem bija divsimt maizes un simts rozīņu raušu un simts vīģu raušu un ādas trauks ar vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Un ķēniņš sacīja uz Cību: kas tas tev tur ir? Tad Cībus sacīja: Tie ēzeļi ir priekš ķēniņa nama, ko jāt, un tā maize ar tām vīģēm priekš tiem puišiem, ko ēst, un tas vīns tiem piekusušiem tuksnesī, ko dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Tad ķēniņš sacīja: Kur tad ir tava kunga dēls? Un Cībus sacīja uz ķēniņu: redzi, viņš paliek Jeruzālemē, jo viņš sacīja: šodien Israēla nams man atdos mana tēva valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Tad ķēniņš sacīja uz Cību: redzi, tavs lai ir viss, kas Mefibošetam pieder. Un Cībus sacīja: es metos pie zemes, lai es žēlastību atrodu priekš tavām acīm, mans kungs un ķēniņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kad nu ķēniņš Dāvids nāca līdz Bakurim, redzi, tad no turienes izgāja vīrs no Saula nama radiem, Šimejus vārdā, Ģerus dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Viņš izgāja un iedams lādēja un mētāja akmeņiem Dāvidu un visus ķēniņa Dāvida kalpus, lai gan visi ļaudis un visi varenie gāja pa viņa labo un kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Un Šimejus sacīja tā lādēdams: ej ārā, ej ārā, tu asinsvīrs, tu negantais!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Tas Kungs liek pār tevi nākt visām Saula nama asinīm, kura vietā tu palicis par ķēniņu. Nu Tas Kungs to valstību dod tavam dēlam Absalomam rokā. Un redzi, nu tu esi nelaimē, jo tu esi asinsvīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Tad Abizajus, Cerujas dēls, sacīja uz ķēniņu: kāpēc šim nosprāgušam sunim būs lādēt manu kungu, to ķēniņu? Es noiešu un viņam noraušu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Bet ķēniņš sacīja: kas man ar jums, jūs Cerujas dēli. Lai viņš lād, jo Tas Kungs viņam ir sacījis: lādi Dāvidu. Kas tad sacīs: kāpēc tu tā dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Un Dāvids sacīja uz Abizaju un visiem saviem kalpiem: redzi, mans dēls, kas no manām miesām nācis, meklē manu dzīvību, vai ne nu jo vairāk šis Benjaminietis? Laid viņu mierā; lai lād, jo Tas Kungs viņam to ir licis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Varbūt Tas Kungs uzlūko manu noziegumu un Tas Kungs man šodien atkal atdos labumu viņa lāstu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Tā Dāvids gāja ar saviem vīriem pa ceļu, un Šimejus gāja gar kalnu, viņam iepretim, viņu lādēdams, un mētāja akmeņiem un putināja pīšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Un ķēniņš ar visiem ļaudīm, kas pie viņa bija, nonāca uz Ajevīm un tur atspirdzinājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Bet Absaloms un visi Israēla vīri nāca uz Jeruzālemi, ir Ahitofels ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Un notikās, kad Uzajus, tas Arķiets, Dāvida draugs, nāca pie Absaloma, tad Uzajus sacīja uz Absalomu: lai dzīvo ķēniņš, lai dzīvo ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Bet Absaloms sacīja uz Uzaju: vai tā ir tava mīlestība uz tavu draugu? Kāpēc tu neesi gājis ar savu draugu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Un Uzajus sacīja uz Absalomu: nē, bet ko Tas Kungs izredzējis un šie ļaudis un visi Israēla vīri, tam es arī piederēšu un pie tā es palikšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Un otram kārtam, kam man kalpot? Vai ne viņa dēlam? tā kā es tavam tēvam esmu kalpojis, tāpat es būšu tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Un Absaloms sacīja uz Ahitofelu: dodiet padomu, ko lai darām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Un Ahitofels sacīja uz Absalomu: ieej pie sava tēva liekām sievām, ko viņš atstājis, to namu sargāt, tad viss Israēls dzirdēs, ka tu smirdots tapis savam tēvam, un visu to rokas, kas pie tevis ir, taps stiprinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Un tie taisīja Absalomam telti uz jumta, un Absaloms iegāja pie sava tēva liekām sievām, visam Israēlim redzot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Un Ahitofela padoms, ko viņš tanīs dienās deva, tā tapa turēts, itin kā Dieva vārds būtu vaicāts, tā bija viss Ahitofela padoms, tik labi pie Dāvida kā pie Absaloma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Un Ahitofels sacīja uz Absalomu: es izlasīšu divpadsmit tūkstoš vīrus un celšos un dzīšos Dāvidam šonakt pakaļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Un es viņam uzbrukšu, kad viņš piekusis un viņa rokas nogurušas, un viņu izbiedēšu, ka visi ļaudis, kas pie tā ir, bēg, tad es nokaušu ķēniņu vienu pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Un es vedīšu visus ļaudis atpakaļ pie tevis. Kad visi būs griezušies atpakaļ, (jo viņš vien ir tas vīrs, ko tu meklē), tad visi ļaudis būs mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Šī valoda labi patika Absalomam un visiem Israēla vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Tad Absaloms sacīja: aicinājiet jel Uzaju, to Arķieti, arīdzan, un dzirdēsim, ko viņš saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Un kad Uzajus pie Absaloma nāca, tad Absaloms uz to runāja un sacīja: tā un tā Ahitofels ir runājis, - vai mums būs pēc viņa vārda darīt, vai ne? Runā tu arīdzan!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Tad Uzajus sacīja uz Absalomu: tas padoms, ko Ahitofels šim brīžam devis, nav labs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Un Uzajus sacīja: tu pazīsti savu tēvu un viņa vīrus, ka tie ir vareni un dusmīgu prātu, it tā lācis laukā, kam bērni paņemti, un tavs tēvs ir karavīrs un nepaliks naktī pie tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Redzi, nu viņš ir paslēpies kādā alā vai citā kādā vietā; kad nu notiktu, ka tas iesākumā viņiem uzkrīt, tad ikkatrs, kas to dzirdēs, sacīs: tie ļaudis ir sakauti, kas Absalomam iet pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Tad ir paši varenie, kam sirds kā lauvām, baiļot baiļosies. Jo viss Israēls zina, ka tavs tēvs ir varonis, un ka tie ir stipri ļaudis, kas pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Bet mans padoms ir šis: lai pie tevis top sapulcināts viss Israēls no Dana līdz Bēršebai tādā pulkā kā smiltis jūrmalā, un tev pašam jāiet viņiem līdz karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Un kad mēs viņu sastapsim kaut kurā vietā, kur viņu atradīsim, tad uzkritīsim viņam kā rasa krīt uz zemi, un neatliks neviens no viņa un visiem vīriem, kas pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Un ja viņš metīsies kādā pilsētā, tad viss Israēls tai pilsētai apmetīs virves, un mēs to novilksim upē, ka ne zvirgzdiņš tur vairs neatradīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Tad Absaloms un visi Israēla vīri sacīja: Uzajus, tā Arķieša, padoms ir labāks nekā Ahitofela padoms. Bet Tas Kungs tā bija nolicis, iznīcināt Ahitofela labo padomu, lai Tas Kungs nelaimi vestu pār Absalomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Un Uzajus sacīja uz tiem priesteriem, Cadoku un Abjataru: tā un tā Ahitofels padomu devis Absalomam un Israēla vecajiem, un tā un tā es esmu padomu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Un nu sūtait drīz un dodiet Dāvidam ziņu sacīdami: nepaliec pa nakti tuksnesī pie braslām, bet ej drīz pāri, ka ķēniņš netop aprīts ar visiem ļaudīm, kas pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Un Jonatāns un Aķimaācs stāvēja pie Roģela akas. Un viena meita gāja un tiem to sacīja. Tad tie nogāja un to sacīja ķēniņam Dāvidam, jo tie nedrīkstēja nākt un rādīties pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Un viens puisis tos redzēja un to sacīja Absalomam, bet tie gāja abi divi steigšus un nāca kāda vīra namā iekš Bakurim, tam bija aka savā pagalmā, un tie tur nokāpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Un tā sieva ņēma un izklāja apsegu pār akas caurumu, un uzkaisīja putraimus virsū, ka neko nemanīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Kad nu Absaloma kalpi pie tās sievas nāca namā, tad tie sacīja: kur ir Aķimaācs un Jonatāns? Un tā sieva uz tiem sacīja: tie ir gājuši pār šo upīti. Un tie tos meklēja un neatrada, un griezās atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Un kad šie bija aizgājuši, tad tie izkāpa no akas un gāja un to pasacīja ķēniņam Dāvidam; un tie sacīja uz Dāvidu: ceļaties un ejat drīz pār ūdeni pāri, jo tā un tā Ahitofels pret jums ir padomu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Tad Dāvids un visi ļaudis, kas pie viņa bija, cēlās un gāja pār Jardāni līdz pat gaismai, un neviena netrūka, kas nebūtu pār Jardāni gājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Kad nu Ahitofels redzēja, ka nedarīja pēc viņa padoma, tad viņš apsegloja savu ēzeli un cēlās un gāja uz savu namu savā pilsētā un apkopa savu namu un pakārās. Tā viņš nomira un tapa aprakts sava tēva kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Un Dāvids nāca uz Mahānaīm, bet Absaloms gāja pāri pār Jardāni, un visi Israēla vīri viņam līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Un Absaloms cēla Amasu Joaba vietā par karaspēka virsnieku, un Amasus bija dēls vienam Israēlietim, Jetrus vārdā, kas bija gulējis pie Abigaīles, Nahasa meitas, Cerujas, Joaba mātes māsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Un Israēls un Absaloms apmetās Gileādas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Un kad Dāvids uz Mahānaīm bija nācis, tad Zobi, Nahasa dēls, no Rabas, Amona bērnu pilsētas, un Mahirs, Amiēļa dēls, no Lodabaras, un Barzilajus, tas Gileādietis, no Roglim, nesa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Guļamas drēbes un kausus un mālu traukus un kviešus un miežus un miltus un taukšētu(grauzdētu) labību un pupas un lēcas, arī taukšētas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Un medu un sviestu un avis un govju sierus, ko ēst, pie Dāvida un pie tiem ļaudīm, kas pie viņa bija, jo tie sacīja: tie ļaudis būs izsalkuši un piekusuši un izslāpuši tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Un Dāvids pārlūkoja tos ļaudis, kas pie viņa bija, un iecēla tiem virsniekus pār tūkstošiem un virsniekus pār simtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Un Dāvids lika tos ļaudis, vienu daļu apakš Joaba rokas, un otru daļu apakš Abizajus, Cerujas dēla, Joaba brāļa, un to trešo apakš Itajus no Gatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Un ķēniņš sacīja uz tiem ļaudīm: es pats arīdzan iziešu līdz ar jums. Bet tie ļaudis sacīja: tev nebūs iziet, jo kad mēs bēgsim, tad tie to neliks vērā; un arī kad puse no mums mirst, tad tie to arī neliks vērā, bet tu esi kā desmit tūkstoši no mums. Tāpēc nu būs labāk, kad tu mums no pilsētas nāksi palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Un ķēniņš uz tiem sacīja: es darīšu, kā jums šķiet par labu. Un ķēniņš nostājās pie vārtiem, un visi ļaudis izgāja pa simtiem un pa tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Un ķēniņš pavēlēja Joabam un Abizajum un Itajum un sacīja: taupiet to puisi, to Absalomu, un visi ļaudis to dzirdēja, ka ķēniņš visiem virsniekiem par Absalomu pavēlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Tā tie ļaudis izgāja uz lauku Israēlim pretī, un tā kaušanās notika Efraīma mežā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Un Israēla ļaudis tur tapa kauti no Dāvida kalpiem, un tai dienā notika liela kaušana, līdz divdesmit tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Jo tā kauja izpletās tur pa visu to apgabalu, un mežs aprija vairāk ļaužu, nekā zobens aprija tai dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Un Absaloms sastapa Dāvida kalpus un Absaloms jāja uz zirgēzeļa. Un kad tas zirgēzelis nāca apakš kāda liela ozola kupliem zariem, tad viņa galva ieķērās cieti pie tā ozola, ka viņš karājās starp debesi un zemi, un viņa zirgēzelis apakš viņa aizskrēja projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Tad viens vīrs to redzēja un to teica Joabam un sacīja: redzi, es redzēju Absalomu karājamies pie kāda ozola.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Tad Joabs sacīja uz to vīru, kas viņam to teica: redzi, tu esi redzējis, kāpēc tad tu viņu tur neesi kāvis zemē? Tad es tev no savas puses būtu devis desmit sudraba gabalus un vienu jostu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Bet tas vīrs sacīja uz Joabu: un ne par tūkstoš sudraba gabaliem, kad tie taptu iesvērti manā rokā, es savu roku neliktu pie ķēniņa dēla. Jo ķēniņš, mums dzirdot, tev un Abizajum un Itajum ir pavēlējis un sacījis: sargājat ikviens to puisi, to Absalomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Bet ja es būtu viltu darījis pret viņa dvēseli, un ķēniņam jau nekas nepaliek apslēpts, tad tu pats man būtu stāvējis pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Un Joabs sacīja: es tā pie tevis nevaru kavēties. Un viņš ņēma trīs šķēpus savā rokā un tos iedūra Absaloma sirdī. Un kad tas vēl bija dzīvs pie ozola,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Tad desmit puiši, Joaba bruņunesēji, to apstāja un kāva Absalomu un to nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Tad Joabs lika pūst trumetes, un tie ļaudis griezās atpakaļ un Israēlim vairs nedzinās pakaļ; jo Joabs taupīja tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Un tie ņēma Absalomu, un to iemeta mežā lielā bedrē, un uzkrāva tam virsū ļoti lielu akmeņu kopu. Un viss Israēls bēga, ikkatrs savā dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Bet Absaloms, kamēr vēl bija dzīvs, bija ņēmis un uzcēlis sev stabu ķēniņa ielejā. Jo viņš sacīja: man dēla nav, lai mans vārds pie tā top pieminēts. Un viņš to stabu bija nosaucis pēc sava vārda, un tas vēl šodien top saukts Absaloma stabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Tad Aķimaācs, Cadoka dēls, sacīja: es skriešu un nesīšu ķēniņam vēsti, ka Tas Kungs viņam tiesu iznesis no viņa ienaidnieku rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Bet Joabs uz to sacīja: šodien tu neesi prieka vēstnesis, citu dienu tu vari vēstis nest, bet šodien tev labas vēsts nav, ko nest, jo ķēniņa dēls ir miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Un Joabs sacīja uz Kuzu: ej tu un teici ķēniņam, ko tu esi redzējis. Tad Kuzus paklanījās Joaba priekšā un aizskrēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Bet Aķimaācs, Cadoka dēls, runāja vēl uz Joabu: lai būtu kā būdams, liec man jel arī Kuzum skriet pakaļ. Un Joabs sacīja: kāpēc tad tu gribi skriet, mans dēls? Ej tad, - laba vēsts tā nav, kas ko ienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '(Viņš sacīja:) lai būtu kā būdams, es skriešu! Un viņš uz to sacīja: tad skrej! Tad Aķimaācs skrēja pa klajuma ceļu un Kuzum aiztika priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Un Dāvids sēdēja starp abiem vārtiem. Tad tas sargs kāpa uz vārtu jumtu un mūri un pacēla savas acis un skatījās, un redzi, tur vīrs skrēja viens pats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Un tas sargs sauca un to sacīja ķēniņam. Un ķēniņš sacīja: ja viņš viens pats, tad būs laba vēsts viņa mutē; un tas nāca arvien tuvāki klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Tad tas sargs redzēja otru vīru skrienam, un tas sargs sauca uz vārtiem un sacīja: raugi, vēl otrs vīrs skrien viens pats. Un ķēniņš sacīja: tas arī ir labs vēstnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Un tas sargs sacīja: es redzu, ka tā pirmā gaita ir kā Aķimaāca, Cadoka dēla, gaita, un ķēniņš sacīja: tas ir labs vīrs un nāks ar labu vēsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Tad Aķimaācs sauca un sacīja uz ķēniņu: miers! Un viņš nometās ķēniņa priekšā ar savu vaigu pie zemes un sacīja: slavēts ir Tas Kungs, tavs Dievs, kas tos vīrus nodevis, kas savu roku pret manu kungu, to ķēniņu, bija pacēluši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Tad ķēniņš sacīja: vai tas puisis Absaloms sveiks vesels? Un Aķimaācs sacīja: es redzēju lielu troksni, kad Joabs tā ķēniņa kalpu un mani, tavu kalpu, nosūtīja, bet es nezinu, kas tur bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Un ķēniņš sacīja: ej un nostājies te. Tad viņš gāja un nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Un redzi, Kuzus nāca, un Kuzus sacīja: manam kungam, tam ķēniņam, tā labā vēsts, ka Tas Kungs tev šodien ir tiesu iznesis no visu to rokas, kas pret tevi cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Tad ķēniņš sacīja uz Kuzu: vai tas puisis Absaloms sveiks un vesels? Un Kuzus sacīja: lai tā kā šim jauneklim, iet mana kunga, tā ķēniņa, ienaidniekiem un visiem, kas pret tevi ar ļaunumu ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Tad ķēniņš noskuma un gāja vārtu augšistabā un raudāja, un sacīja iedams: mans dēls Absalom! Mans dēls, mans dēls Absalom! Kaut es tavā vietā būtu miris! Ak Absalom! Mans dēls, mans dēls!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Un Joabam tapa sacīts: redzi, ķēniņš raud un žēlojās par Absalomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Un tā uzvara tai dienā palika par žēlabām visiem ļaudīm, jo tie ļaudis tai dienā dzirdēja sakām: ķēniņam sirds sāp par savu dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Un tie ļaudis tai dienā nāca zagšus pilsētā, tā kā ļaudis zagšus nāk, kas kaunā krituši, kaujā bēgdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Un ķēniņš savu galvu bija aptinis un sauca ar stipru balsi: ak mans dēls Absalom! Ak Absalom, mans dēls, mans dēls!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Tad Joabs nāca pie ķēniņa namā un sacīja: tu šodien esi apkaunojis visu savu kalpu vaigus, kas šodien glābuši tavu dzīvību un tavu dēlu un tavu meitu dzīvību un tavu sievu dzīvību un tavu lieko sievu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Bet tu mīļo, kas tevi ienīst, un ienīsti, kas tevi mīļo. Jo tu parādi šodien, ka virsnieki un kalpi priekš tevis nav nekas. Jo es nomanu šodien, kad tikai Absaloms būtu dzīvs un mēs visi šodien būtu miruši, tad tas tev būtu pa prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Tad celies nu un izej un runā sirsnīgi ar saviem kalpiem, jo es zvērēju pie Tā Kunga, ja tu neizej, tad neviens vīrs pie tevis nepaliks šo nakti. Un tā tev būs lielāka nelaime, nekā visa nelaime, kas tev notikusi no tavas jaunības līdz šim laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Tad ķēniņš cēlās un apsēdās vārtos. Un visiem ļaudīm tika teikts un sacīts: redzi, ķēniņš sēž vārtos. Tad visi ļaudis nāca ķēniņa priekšā. Bet Israēls bēga ikviens savā dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Un visi ļaudis visās Israēla ciltīs strīdējās un sacīja: ķēniņš mūs ir izglābis no mūsu ienaidnieku rokas un mūs ir atsvabinājis no Fīlistu rokas, un nu viņam no zemes bija jābēg Absaloma priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Un Absaloms, ko mēs sev bijām svaidījuši par ķēniņu, ir nomiris karā; nu tad, kāpēc jūs kavējaties, ķēniņu atkal pārvest?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Tad ķēniņš Dāvids sūtīja pie tiem priesteriem, Cadoka un Abjatara, sacīdams: runājiet uz Jūda vecajiem un sakāt: kāpēc jūs gribat tie pēdīgie būt, ķēniņu vest atpakaļ uz viņa namu? (Jo visa Israēla valoda jau bija nākusi pie ķēniņa viņa namā.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Jūs esat mani brāļi, jūs esat mani kauli un manas miesas - kāpēc tad jūs gribat tie pēdīgie būt, ķēniņu atkal atvest?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Un uz Amasu sakāt: vai tu neesi no maniem kauliem un no manas miesas? Lai Dievs man šā un tā dara, ja tu visu mūžu nebūsi par karalielkungu manā priekšā Joaba vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Tā viņš locīja visu Jūda vīru sirdi kā viena vienīga vīra, un tie sūtīja pie ķēniņa (sacīdami): griezies atpakaļ, tu un visi tavi kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Tā ķēniņš griezās atpakaļ un nāca pie Jardānes, un Jūda nāca uz Gilgalu, ķēniņam pretī iedams, ka ķēniņu vadītu pār Jardāni pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Un Šimejus, Benjaminieša Ģerus dēls, kas no Bakurim bija, steidzās un nonāca ar Jūda vīriem ķēniņam Dāvidam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Un tūkstoš vīri no Benjamina līdz ar viņu, ir Cībus, Saula nama sulainis, ar saviem piecpadsmit dēliem un saviem divdesmit kalpiem; un tie cēlās pāri pār Jardāni ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Un plosts pārcēlās, pārvest ķēniņa namu, un darīt, kas viņam pa prātam, un Šimejus, Ģerus dēls, nometās priekš ķēniņa zemē, kad šis pār Jardāni cēlās pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Un viņš sacīja uz ķēniņu: nepielīdzini man, mans kungs, to noziegumu, un nepiemini, ka tavs kalps ir noziedzies tai dienā, kad mans kungs, tas ķēniņš, no Jeruzālemes izgāja, un lai ķēniņš to neņem pie sirds!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Jo tavs kalps to atzīst, ka esmu grēkojis; bet redzi, šodien esmu nācis tas pirmais no visa Jāzepa nama, pretī iet savam kungam, tam ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Tad Abizajus, Cerujas dēls, atbildēja un sacīja: vai tad Šimeju par to nebija nokaut, ka viņš Tā Kunga svaidīto lādējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Tad Dāvids sacīja: kas man daļas ar jums, Cerujas dēli, ka jūs man šodien paliekat par pretiniekiem? Vai šodien kādu nokaut iekš Israēla? Vai tad es nezinu, ka es šodien esmu tapis par ķēniņu pār Israēli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Un ķēniņš sacīja uz Šimeju: tev nebūs mirt. Un ķēniņš tam zvērēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Arī Mefibošets, Saula dēls, nonāca ķēniņam pretī. Un viņš ne savas kājas ne savu bārdu nebija tīrījis, nedz savas drēbes mazgājis no tās dienas, kad ķēniņš bija nogājis, līdz tai dienai, kad ķēniņš atkal ar mieru pārnāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Un kad viņš Jeruzālemē ķēniņam pretī nāca, tad ķēniņš uz to sacīja: kāpēc tu neesi man līdz nācis, Mefibošet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Un viņš sacīja: mans kungs un ķēniņ, mans kalps mani pievīlis, jo tavs kalps sacīja: es sev likšu ēzeli seglot un jāšu uz tā, un iešu pie ķēniņa, jo tavs kalps ir tizls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Un viņš tavu kalpu pie mana kunga, tā ķēniņa, arī apmelojis. Bet mans kungs, tas ķēniņš, ir kā viens Dieva eņģelis, dari, kā tev patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Jo viss mana tēva nams tik nāves ļaudis vien bijuši priekš mana kunga, tā ķēniņa. Taču tu savu kalpu esi licis starp tiem, kas ēd pie tava galda; kādas tiesības man tad vēl ir, jeb par ko man vēl būs brēkt uz ķēniņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Tad ķēniņš uz to sacīja: kāpēc tu vēl runā par savām lietām? Es esmu sacījis: tu un Cībus daliet to tīrumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Un Mefibošets sacīja uz ķēniņu: lai viņš arī visu paņem, ka nu mans kungs, tas ķēniņš, atkal ar mieru savā namā pārnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Un Barzilajus tas Gileādietis, nāca arīdzan no Roglim un gāja ar ķēniņu pār Jardāni, viņu pārvadīt pār Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Un Barzilajus bija ļoti vecs, pie astoņdesmit gadiem, un ķēniņu bija apgādājis, kad tas mita iekš Mahānaīm, jo viņš bija ļoti bagāts vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Un ķēniņš sacīja uz Barzilaju: tev būs man iet līdz, es tevi apgādāšu pie sevis Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Bet Barzilajus sacīja uz ķēniņu: cik man vēl būs mūža gadu un dienu, ka man ar ķēniņu iet uz Jeruzālemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Es šodien esmu astoņdesmit gadus vecs, vai es vēl varu izšķirt, kas labs, kas nelabs? Un vai tavam kalpam vēl kāda garša, ko viņš ēd un dzer? Vai es vēl varētu sadzirdēt dziedātājus un dziedātājas? Un kāpēc tavs kalps lai ir par nastu manam kungam, tam ķēniņam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Tavs kalps ies maķenīt ar ķēniņu pār Jardāni; kāpēc ķēniņš man grib darīt tādu lielu žēlastību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Ļauj savam kalpam griezties atpakaļ un mirt savā pilsētā pie sava tēva un pie savas mātes kapa. Un redzi, še ir tavs kalps Ķimeams, lai šis iet pāri līdz ar manu kungu, to ķēniņu, un dari tam, kā tev patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Tad ķēniņš sacīja: Ķimeamam būs iet man līdz, un es viņam darīšu, kā tev patīk, un visu, ko tu no manis prasīsi, es tev gribu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Un kad visi ļaudis pār Jardāni bija pārgājuši, tad arī ķēniņš gāja pāri, un ķēniņš skūpstīja Barzilaju un to svētīja, un tas griezās atpakaļ uz savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Un ķēniņš gāja tālāk uz Gilgalu, un Ķimeams tam gāja līdz, un visi Jūda ļaudis ķēniņu bija pārveduši, un arī puse no Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Un redzi, visi Israēla vīri nāca pie ķēniņa un sacīja uz ķēniņu: kāpēc mūsu brāļi, Jūda vīri, tevi ir zaguši un ķēniņu ar viņa namu pār Jardāni pārveduši līdz ar visiem Dāvida vīriem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Tad visi Jūda vīri atbildēja Israēla vīriem: tāpēc ka ķēniņš mums ir tuvs radinieks, un kāpēc jums par to dusmas? Vai tad mēs esam dabūjuši ēst no ķēniņa, jeb vai viņš mums ir devis dāvanas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Un Israēla vīri atbildēja Jūda vīriem un sacīja: mums ir desmit daļas pie ķēniņa un arī pie Dāvida, mums ir vairāk nekā jums. Kāpēc tad jūs mūs esat turējuši tādā negodā? Vai mūsu vārds nav tas pirmais bijis, mūsu ķēniņu vest atpakaļ? Bet Jūda vīru valoda bija bargāka nekā Israēla vīru valoda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Un tur gadījās netikls vīrs, Šebus vārdā, Bikra dēls, Benjaminietis; tas pūta trumetes un sacīja: mums daļas nav pie Dāvida, nedz mantības pie Isajus dēla, - ikviens no Israēla ejat savā dzīvoklī!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Tad visi Israēla vīri gāja nost no Dāvida, Šebum, Bikra dēlam, pakaļ. Bet Jūda vīri turējās pie sava ķēniņa, no Jardānes līdz Jeruzālemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Kad nu Dāvids uz Jeruzālemi pārnāca savā namā, tad ķēniņš ņēma tās desmit sievas, savas liekas sievas ko viņš bija atstājis, to namu sargāt, un tās ielika kādā sargu namā un tās apgādāja, bet vairs pie tām negāja. Un tās bija ieslēgtas līdz savai miršanas dienai un dzīvoja par atraitnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Un ķēniņš sacīja uz Amasu: sasauc man Jūda vīrus uz trešo dienu, un stāvi tu arīdzan te.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Tad Amasus gāja, Jūdu sasaukt, bet viņš kavējās pāri par nolikto laiku, ko tas viņam bija nolicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Tad Dāvids sacīja uz Abizaju: nu mums Šebus, Bikra dēls, darīs vairāk ļaunuma nekā Absaloms. Ņem sava kunga kalpus un dzenies viņam pakaļ, ka viņš netiek stiprās pilsētās un neizzūd no mūsu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Tad Joaba vīri viņam izgāja pakaļ, ir tie Krieti un Plieti un visi varenie. Un tie izgāja no Jeruzālemes, Šebum, Bikra dēlam, dzīties pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Kad tie nu pie tā lielā akmens nāca, kas ir Gibeonā, tad Amasus tos sastapa, bet Joabs bija apjozies pār savām drēbēm, kas viņam bija mugurā, un pār tām bija josta, kur zobens bija piesiets uz viņa gurniem savās makstīs, šis izslīdēja un tas (zobens) nokrita zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Un Joabs sacīja uz Amasu: vai tev labi klājās, mans brāli? Un Joabs satvēra ar labo roku Amasus bārdu, viņu skūpstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Un Amasus nesargājās no tā zobena, kas bija Joaba rokā, un tas viņam to iedūra vēderā, ka viņa iekšas izgāzās zemē un viņam otras reizes vairs nevajadzēja, un viņš nomira. Bet Joabs un viņa brālis Abizajus dzinās pakaļ Šebum, Bikra dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Un viens vīrs no Joaba puišiem palika pie viņa stāvot un sacīja: kam labs prāts ir pie Joaba, un kas Dāvidam (pieķeras), tas lai iet Joabam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Bet Amasus vārtījās asinīs ceļa vidū. Kad nu tas vīrs redzēja, ka visi ļaudis tur apstājās, tad viņš Amasu no ceļa novēla uz tīrumu un uzmeta viņam drēbes, tāpēc ka redzēja, ka ikviens, kas pie viņa pienāca, apstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Kad viņš nu no ceļa bija novelts, tad visi ļaudis gāja garām, Joabam pakaļ, Šebum, Bikra dēlam pakaļ dzīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Un viņš gāja pa visām Israēla ciltīm uz Abelu un BetMaāku, un pa visu Berim-tiesu, un tie sapulcējās un gāja viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Un tie nāca un apmetās pret viņu Abel BetMaākā un uzmeta valni pret to pilsētu un tas stāvēja pie mūra, un visi ļaudis, kas pie Joaba bija, meklēja to mūri postīt un apgāzt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Tad viena gudra sieva no pilsētas sauca: klausiet, klausiet, sakāt jel Joabam: nāc šurp, es ar tevi gribu runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Kad viņš nu pie tās atnāca, tad tā sieva sacīja: vai tu esi Joabs? Un viņš sacīja: es tas esmu. Un tā uz viņu sacīja: klausies savas kalpones vārdus. Un viņš sacīja: es klausos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Tad viņa teica un sacīja: vecos laikos tā mēdza runāt: kas vaicā, lai vaicā Abelā, un tā tika galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Es esmu no tiem mierīgiem un uzticīgiem iekš Israēla, un tu meklē tādu pilsētu izdeldēt, kas ir māte iekš Israēla. Kāpēc tu gribi aprīt Tā Kunga mantību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Tad Joabs atbildēja un sacīja: lai Dievs pasargā, lai Dievs pasargā, ka es aprītu un ka es izdeldētu; tas tā nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Bet viens vīrs no Efraīma kalniem, Šebus vārdā, Bikra dēls, tas savu roku pacēlis pret ķēniņu, pret Dāvidu; dodiet man to vien, tad es aiziešu projām no pilsētas. Tad tā sieva sacīja uz Joabu: redzi, viņa galva pie tevis taps nomesta pāri pār mūri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Un tā sieva nāca pie visiem ļaudīm ar savu gudrību, un tie Šebum, Bikra dēlam, nocirta galvu un to izmeta Joabam ārā. Tad viņš pūta trumetes, un tie izklīda no tās pilsētas projām, ikviens savā dzīvoklī, un Joabs griezās atpakaļ uz Jeruzālemi pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Un Joabs bija pār visu Israēla karaspēku, un Benajus, Jojada dēls, pār tiem Krietiem un Plietiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Un Adorams bija pār tiem darbiniekiem un Jehošafats, Aķiluda dēls, bija kanclers,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Un Zejus bija rakstu vedējs, un Cadoks un Abjatars bija priesteri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Un arī Irus, Jaīra dēls, bija pie Dāvida lielskungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Un Dāvida laikā bija bads trīs gadus no vietas, un Dāvids meklēja Tā Kunga vaigu. Un Tas Kungs sacīja: tas ir Saula pēc un tā asins nama pēc, tāpēc ka viņš tos Gibeoniešus nokāvis');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Tad ķēniņš aicināja Gibeoniešus un uz tiem sacīja: (bet Gibeonieši nebija no Israēla bērniem, bet no Amoriešu atlikušiem, un Israēla bērni tiem bija zvērējuši, bet Sauls tos bija meklējis nokaut savā karstumā par Israēla un Jūda bērniem,)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Un Dāvids sacīja uz Gibeoniešiem: ko man jums būs darīt un ar ko man jūs būs salīdzināt, ka jūs Tā Kunga mantību svētījat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Un Gibeonieši tam atbildēja: mēs neprasām ne sudraba ne zelta Saula un viņa nama pēc; mēs arī negribam, lai kas iekš Israēla top nokauts. Tad viņš sacīja: ko tad jūs sakāt, ko man jums būs darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Tad tie sacīja uz ķēniņu: to vīru, kas mūs postījis un pret mums ļaunu izdomājis, mūs izdeldēt, lai mūsu nemaz vairs nav Israēla robežās; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Dodiet mums septiņus vīrus no viņa dēliem, ka tos Tam Kungam pakaram Ģibejā, Saula, Tā Kunga izredzētā pilsētā. Un ķēniņš sacīja: es došu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Bet ķēniņš saudzēja Mefibošetu, Jonatāna dēlu, Saula dēla dēlu, tā zvēresta pēc, ko Dāvids un Jonatāns, Saula dēls pie Tā Kunga bija zvērējuši savā starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Un ķēniņš ņēma Ricpas, Ajas meitas, divus dēlus, ko tā Saulam bija dzemdējusi, Armonu un Mefibošetu, un Mikales (māsas), Saula meitas, piecus dēlus, ko tā bija dzemdējusi, Adriēlim, Barzilajus, tā Maālotieša dēlam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Un tos deva Gibeoniešiem rokā, un tie tos pakāra uz tā kalna Tā Kunga priekšā. Un tie septiņi kopā gāja bojā un nomira pļaujamā laika iesākumā, kad miežu pļaušana sākās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Tad Ricpa, Ajas meita, ņēma maisu un to sev izklāja uz to akmeni pļaušanas iesākumā, tiekams ūdens no debesīm uz tiem pilēja, un viņa ne putniem apakš debess nelika uz tiem nākt dienā, ne lauka zvēriem naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Un Dāvidam sacīja, ko Ricpa, Ajas meita, Saula lieka sieva, bija darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Un Dāvids nogāja un ņēma Saula un viņa dēla Jonatāna kaulus no tiem namniekiem Jabesā Gileādā, kas tos bija zaguši no BetŠanas ielas, kur Fīlisti tos bija pakāruši tai dienā, kad Fīlisti Saulu Ģilboā kāva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Un viņš aizveda no tejienes Saula kaulus un Jonatāna, viņa dēla, kaulus, un tos sakrāja ar to pakārto kauliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Un apraka Saula un viņa dēla Jonatāna kaulus Benjamina zemē, Celā, Ķisa, viņa tēva, kapā, un tie darīja visu, ko ķēniņš bija pavēlējis. Tā Dievs pēc šim zemei atkal palika žēlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Pēc tam bija atkal karš starp Fīlistiem un Israēli. Un Dāvids nogāja un viņa kalpi līdz ar viņu un karoja pret Fīlistiem. Un Dāvids nogura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Un Jezbus no Nobas, viens no Revaiešiem, tam šķēps bija trīs simt vara sēķeļus smagumā, un tas bija apjozies ar jaunu (zobenu), šis domāja Dāvidu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Bet Abizajus, Cerujas dēls, viņam palīdzēja un sita to Fīlistu un nokāva. Tad Dāvida vīri tam zvērēja un sacīja: tev nebūs vairs ar mums iet karā, ka tu to gaišumu iekš Israēla neizdzēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Pēc tam bija atkal karš Gobā pret Fīlistiem. Tad Zibekajus, Uzata dēls, kāva Zavu, kas bija no Revaiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Un atkal bija karš Gobā pret Fīlistiem; tad Elanans, JaēraOrģima dēls, no Bētlemes, kāva Goliata, tā Gatieša, (brāli), kam šķēpa kāts bija kā vēvera (audēja) riestava.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Atkal bija karš Gatā, un tur bija ļoti garš vīrs, tam bija ik seši pirksti pie rokām un seši pie kājām, divdesmit četri pa visam, ir tas bija no Revaiešu cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Un tas mēdīja Israēli; bet Jonatāns, Šimejus, Dāvida brāļa, dēls to nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Šie četri bija Ravum Gatā dzimuši un krita caur Dāvida roku un caur viņa kalpu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Un Dāvids runāja Tā Kunga priekšā šīs dziesmas vārdus tai dienā, kad Tas Kungs viņu bija atpestījis no visu viņa ienaidnieku rokas un no Saula rokas; un viņš sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Tas Kungs ir mans akmens kalns un mana pils un mans glābējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Dievs ir mans patvērums, uz ko es paļaujos, manas priekšturamās bruņas un manas pestīšanas rags, mans augstais palīgs, un mana glābšana, mans Pestītājs, kas mani no varas darba atpestī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Es piesaukšu To Kungu, kas teicams, tad es tapšu atpestīts no saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Jo nāves viļņi mani apņēma un posta upes mani izbiedēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Elles saites mani apņēma, un nāves valgi mani pārvarēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Savās bēdās es piesaucu To Kungu, es piesaucu savu Dievu; tad Viņš klausīja manu balsi no Sava nama, un mana brēkšana nāca Viņa ausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Zeme tapa kustināta un drebēja, un debesu stiprumi kustējās un trīcēja, kad Viņš apskaitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Dūmi uzkāpa no Viņa nāsīm un rijoša uguns no Viņa mutes, zibeņi no Viņa iedegās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Viņš nolaida debesis un nokāpa, un tumsa bija apakš Viņa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Un Viņš brauca uz ķeruba un skrēja, un parādījās uz vēja spārniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Viņš lika tumsu ap Sevi par telti, un melnus ūdeņus un biezus mākoņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'No spožuma Viņa priekšā iedegās ugunīgi zibeņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Tas Kungs lika pērkoniem rībēt no debesīm, un tas Visuaugstais pacēla Savu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Un Viņš meta bultas un tos izklīdināja, Viņš meta zibeņus un tos iztrūcināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Jūras dibeni rādījās, zemes pamati tapa atklāti no Tā Kunga bāršanas, no Viņa nāšu dvašas pūšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Viņš izstiepa (roku) no augstības un satvēra mani, Viņš mani izvilka no lieliem ūdeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Viņš mani atpestīja no mana stiprā ienaidnieka un no maniem nīdētājiem, jo tie bija jo varenāki nekā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Tie cēlās pret mani manā bēdu laikā; bet Tas Kungs bija mans patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Un Viņš mani izveda klajumā, Viņš mani izrāva, jo Viņam bija labs prāts uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Tas Kungs man atmaksā pēc manas taisnības, Viņš man atlīdzina pēc manu roku šķīstības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Jo es sargāju Tā Kunga ceļus, un neesmu atkāpies no sava Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Jo visas Viņa tiesas ir manā priekšā, un Viņa likumus es nelieku nost no sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Bet es biju bezvainīgs Viņa priekšā un sargājos noziegties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Un Tas Kungs man atlīdzina pēc manas taisnības, pēc manas šķīstības priekš Viņa acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Pie tiem svētiem Tu rādies svēts, un pie tiem sirdsskaidriem vīriem Tu rādies skaidrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Pie tiem šķīstiem Tu rādies šķīsts, un pie tiem pārvērstiem (un pretdabiskiem) Tu pārvērties (un maldini).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Jo bēdīgus ļaudis Tu atpestī, un Tavas acis ir pret tiem lepniem, tos pazemot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Jo Tu Kungs esi mans spīdeklis. Tas Kungs dara manu tumsību gaišu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Jo ar Tevi es varu sadauzīt karaspēku, ar savu Dievu es varu lēkt pār mūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Tā stiprā Dieva ceļš ir bezvainīgs, Tā Kunga valoda ir šķīsta, Viņš ir par priekšturamām bruņām visiem, kas uz Viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Jo kur ir kāds Dievs, kā vien Tas Kungs? Un kur ir kāds patvērums, kā vien mūsu Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Tas stiprais Dievs ir mans varenais patvērums, un Viņš vada to taisno pa Savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Viņš man kājas dara kā stirnām, un mani uzceļ manā augstā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Viņš manas rokas māca karot, ka mans elkonis uzvelk vara stopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Un Tu man dod Savas pestīšanas priekšturamās bruņas, un Tava laipnība mani paaugstina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Maniem soļiem Tu esi darījis platu ceļu apakš manis, ka mani krimšļi nav slīdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Es dzīšos pakaļ saviem ienaidniekiem, un tos iznīcināšu un negriezīšos atpakaļ, kamēr tos nebūšu izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Es tos izdeldēšu un tos satriekšu, ka tie nevarēs celties, tiem jākrīt apakš manām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Jo Tu mani apjozīsi ar spēku uz karu, Tu nospiedīsi apakš manis, kas pret mani ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Tu maniem ienaidniekiem liksi bēgt manā priekšā un savus nīdētājus es iznīcināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Tie skatās visapkārt, bet glābēja nav, - uz To Kungu, bet Viņš tiem neatbild.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Es tos sagrūdīšu kā zemes pīšļus, es tos samīšu un izkaisīšu kā dubļus uz ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Tu mani izglābi no manu ļaužu ķildām, Tu mani lieci par galvu tautām: ļaudis, ko es nepazinu, man kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Svešinieku bērni mīlīgi izrādās manā priekšā; kad viņu auss dzird, tad tie man paklausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Svešinieku bērni nonīkst un drebēdami iziet no savām pilīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Tas Kungs ir dzīvs, un slavēts lai ir mans Patvērums, un augsti slavēts lai ir Dievs, manas pestīšanas Klints,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Tas stiprais Dievs, kas man dod atriebšanu, un tautas nomet apakš manis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Un kas mani izvada no maniem ienaidniekiem. Un Tu mani paaugstini pār tiem, kas pret mani cēlās, no tiem varas darītājiem Tu mani izglābi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Tāpēc es Tevi, Kungs, slavēšu starp tautām un dziedāšu Tavam vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Viņš Savam ķēniņam parāda lielu pestīšanu un dara labu Savam svaidītam Dāvidam un viņa dzimumam mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Un šie ir Dāvida pēdīgie vārdi. Dāvida, Isajus dēla, vārdi: tā saka tas vīrs, kas apstiprināts par Jēkaba Dieva svaidīto, un kas mīlīgs Israēla dziesmās:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Tā Kunga Gars caur mani runā, un Viņa vārds ir uz manas mēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israēla Dievs saka, Israēla patvērums uz mani runā: valdītājs pār cilvēkiem, kas taisns, valdītājs dievbijāšanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Tas ir kā rīta gaisma, kad saule uzlec, kā rīts bez mākoņiem, kā kad no spožuma un lietus zaļums zeļ no zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Vai tāds nav mans nams ar to stipro Dievu? Jo Viņš man uzcēlis mūžīgu derību, kas visādi labi nolikta un pasargāta. Jo visai manai pestīšanai un visam labam prātam, vai Viņš tam neliks plaukt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Bet tie netiklie, tie visi ir kā nomesti ērkšķi, ko rokā neņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Bet ikviens, kas tos grib aizskart, ņem dzelzs ieroci jeb šķēpa kātu rokā; un tos sadedzina ar uguni tai vietā, kur tie auguši. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Šie ir to varoņu vārdi, kas Dāvidam bijuši: Jazabeams, Akmona dēls, tas augstākais starp tiem virsniekiem. Viņš cilāja savu šķēpu un pārvarēja astoņsimt un tos nokāva vienā reizē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Un pēc tā bija Eleazars, Dodus dēls, Aoka dēla dēls, šis bija starp tiem trim varoņiem ar Dāvidu, kad tie Fīlistus kaunā lika, kas tur bija sapulcējušies uz karu, un Israēla vīri (pret tiem) cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Šis cēlās un kāva Fīlistus, tiekams viņa roka piekusa un viņa roka pie zobena pielipa, un Tas Kungs deva tai dienā lielu pestīšanu, ka tie ļaudis atgriezās viņam pakaļ, tikai laupīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Pēc viņa bija Šammus, Agas dēls, tas Arariets. Kad Fīlisti bija sapulcējušies vienā ciemā, un tur bija tīrums ar lēcām, un tie ļaudis bēga priekš Fīlistiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Tad viņš apstājās paša tīruma vidū un to aizstāvēja, un kāva Fīlistus, un Tas Kungs deva lielu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Un šie trīs virsnieki starp trīsdesmit vareniem vīriem nogāja un nāca pļaujamā laikā pie Dāvida, Adulama alā, un Fīlistu pulki bija apmetušies Refaīm ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Bet Dāvids to brīdi bija pilskalnā, un Fīlisti bija ielikuši Bētlemē karavīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Un Dāvidam iegribējās un viņš sacīja: kas man dos ūdeni dzert no tās akas pie Bētlemes vārtiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Tad šie trīs varoņi izlauzās caur Fīlistu lēģeri un smēla ūdeni no Bētlemes akas, kas bija pie vārtiem, un ņēma un atnesa to pie Dāvida. Bet viņš to negribēja dzert, bet to izlēja Tam Kungam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Un sacīja: lai Tas Kungs mani pasargā, ka es to nedaru. Vai tās nav to vīru asinis, kas nogājuši, savu dzīvību netaupīdami? Un viņš to negribēja dzert. To šie trīs varoņi darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Un Abizajus, Joaba brālis, Cerujas dēls, bija arīdzan par virsnieku starp trim. Tas pacēla savu šķēpu pret trīs simtiem un tos nokāva, un viņš bija arīdzan slavēts starp trim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'No šiem trim viņš bija tas augstākais, tāpēc viņš tiem bija par virsnieku, bet viņš tos trīs (pirmos) nepanāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Vēl bija Benajus, Jojadas dēls, stipra vīra dēls, kas lielus darbus darījis, no Kabceēles; šis kāva divus stiprus Moabiešu lauvas, viņš arī nogāja un alā kāva vienu lauvu sniega laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Viņš arī kāva vienu briesmīgu Ēģiptieti, un tā ēģiptieša rokā bija šķēps, bet viņš nogāja pie tā ar zizli un izrāva to šķēpu no tā ēģiptieša rokas un to nokāva ar viņa paša šķēpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'To Benajus, Jojadas dēls, darīja un viņš bija slavēts starp tiem trim varoņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Viņš bija tas augstākais starp tiem trīsdesmit, bet tos trīs pirmos viņš nepanāca. Un Dāvids viņu iecēla pār saviem pils karavīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Azaēls, Joaba brālis, bija starp tiem trīsdesmit; Elanans, Dodus dēls, no Bētlemes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Šammus no Arodas; Elikus no Arodas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Elecs, Palta dēls, Irus, Ikeša dēls, no Tekoas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiēsers no Anatotas; Mebunājus, Uzata dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Calmons, Aoka dēls, Maārajus no Netofas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Elebs, Baēnus dēls, no Netofas; Itajus, Ribaja dēls, no Benjaminiešu Ģibejas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benajus no Pirgatonas; Idajus no Gaāša upēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbons no Arbas; Asmavets no Barumas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Elaēba no Zaālbonas; Jazena un Jonatāna bērni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Šammus no Araras; Ajams, Zarara dēls, no Araras;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elivelets, Aāsbaja dēls, Maāhataja dēla dēls. Elijams, Ahitofela dēls, no Ģilonas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Ecrajus no Karmeļa; Paērajus no Arbas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jeģeals, Nātana dēls, no Cobas; Banus no Gada;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Celegs no Amona; Naārajus no Beērotes, Joaba, Cerujas dēla, bruņu nesējs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Īrus, Jetrus dēls, Gārebs, Jetrus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Ūrija, tas Etietis. Tie ir pavisam trīsdesmit un septiņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Un Tā Kunga dusmas atkal iedegās pret Israēli, un viņš Dāvidu skubināja pret tiem sacīdams: ej, skaiti Israēli un Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Un ķēniņš sacīja uz Joabu, karapulku virsnieku, kas pie viņa bija: ej jel apkārt pa visām Israēla ciltīm, no Dana līdz Bēršebai, un skaitāt tos ļaudis, lai es zinu to ļaužu skaitu. Tad Joabs sacīja uz ķēniņu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Lai Tas Kungs, tavs Dievs, pie šiem ļaudīm simtkārt vairāk pieliek, nekā viņu ir, ka mana kunga, tā ķēniņa, acis to redz; kāpēc tad manam kungam, tam ķēniņam, šīs lietas gribās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Bet ķēniņa vārds palika spēkā pret Joabu un tiem karavirsniekiem. Tā Joabs ar tiem karavirsniekiem izgāja no ķēniņa, Israēla ļaudis skaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Un tie gāja pār Jardāni un apmetās pie Aroēra, pa labo roku tai pilsētai, kas Gada ielejas vidū, un pie Jaēzeres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Pēc tie nāca uz Gileādu un uz to ielejas zemi Tahtim Hodši, tie nāca arī uz DanJaānu un apkārt uz Sidonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Un tie nāca uz to stipro Tirus pilsētu un uz visām Hiviešu un Kanaāniešu pilsētām, un tie iznāca ārā Jūdam pret dienasvidu uz Bēršebu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Tā tie gāja apkārt pa visu zemi un pārnāca pēc deviņiem mēnešiem un divdesmit dienām uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Un Joabs deva ķēniņam to uzrakstīto ļaužu skaitu, un iekš Israēla bija astoņsimt tūkstoš karavīru, kas bija zobena vilcēji, un Jūda vīru bija piecsimt tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Tad Dāvidam sirds trīcēja, kad tos ļaudis bija skaitījis. Un Dāvids sacīja uz To Kungu: es esmu ļoti grēkojis ar to, ko esmu darījis, un nu Kungs, atņem lūdzams sava kalpa noziegumu, jo es esmu ļoti aplam darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Kad nu Dāvids rītā cēlās, tad Tā Kunga vārds notika uz pravieti Gadu, Dāvida redzētāju, tā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Ej un runā uz Dāvidu: tā saka Tas Kungs: trīs lietas es tev lieku priekšā, izvēlies vienu no tām, ko lai es tev daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Un Gads nāca pie Dāvida un teica viņam un uz to sacīja: vai tu gribi septiņus gadus bada laiku savā zemē, jeb vai tu gribi trīs mēnešus bēgt no saviem ienaidniekiem, kas tevi vajās, jeb vai tu gribi, ka trīs dienas tavā zemē nāk mēris? Ņem nu vērā un redzi, ko lai es tam atsaku, kas mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Tad Dāvids sacīja uz Gadu: man ir ļoti bail. Es kritīšu labāk Tā Kunga rokā, jo Viņa žēlastība ir liela, bet cilvēku rokā es negribu krist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Tad Tas Kungs lika mērim nākt iekš Israēla, no rīta līdz tam nospriestam laikam, un ļaužu nomira no Dana līdz Bēršebai septiņdesmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Un kad tas eņģelis savu roku pār Jeruzālemi izstiepa, lai to nomaitātu, tad Tam Kungam tā ļaunuma bija žēl, un Viņš sacīja uz to eņģeli, kas tos ļaudis nonāvēja: ir gan, atrauj savu roku. Un Tā Kunga eņģelis stāvēja pie Aravnus, tā Jebusieša, klona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Un Dāvids sacīja uz To Kungu, to eņģeli redzēdams, kas tos ļaudis sita: redzi, es esmu grēkojis un noziedzies, bet ko šīs avis darījušas? Lai Tava roka ir pret mani un pret mana tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Tad Gads nāca tai dienā pie Dāvida un uz to sacīja: ej uz augšu un uztaisi Tam Kungam altāri uz Aravnus, tā Jebusieša, klona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Tad Dāvids gāja pēc Gada vārda, kā Tas Kungs bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Un Aravnus skatījās un redzēja pie sevis nākam ķēniņu un viņa kalpus, un Aravnus izgāja un nometās ķēniņa priekšā uz savu vaigu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Un Aravnus sacīja: kāpēc mans kungs, tas ķēniņš, nāk pie sava kalpa? Un Dāvids sacīja: šo klonu no tevis pirkt, ka es Tam Kungam taisu altāri, lai šī mocība no ļaudīm atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Tad Aravnus sacīja uz Dāvidu: lai mans kungs, tas ķēniņš, ņem un upurē, kā viņam patīk. Redzi, še ir vērši par dedzināmo upuri un kuļami rati un vēršu jūgi malkai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Šo visu, ķēniņ, Aravnus dod ķēniņam. Un Aravnus sacīja uz ķēniņu: lai Tam Kungam, tavam Dievam, ir labs prāts uz tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Bet ķēniņš sacīja uz Aravnu: nē, bet es pirkdams to tev nopirkšu, jo es negribu Tam Kungam, savam Dievam, dedzināmos upurus velti upurēt. Tā Dāvids to klonu un tos vēršus nopirka par piecdesmit sudraba sēķeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Un Dāvids uztaisīja tur Tam Kungam altāri un upurēja dedzināmos upurus un pateicības upurus. Tā Tas Kungs tai zemei tapa salīdzināts, un tā mocība atstājās no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Un kad ķēniņš Dāvids bija vecs un labi gados, tad viņu gan ar drēbēm apsedza, bet tomēr viņš nesasila.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Un viņa kalpi uz to sacīja: meklēsim ķēniņam, savam kungam, vienu meitu, vienu jumpravu, kas priekš ķēniņa lai stāv un viņu apkopj un tavā klēpī guļ, ka ķēniņš, mans kungs, sasilst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Tā tie meklēja vienu jaunu skaistu meitu pa visām Israēla robežām un atrada Abizagu no Šunemes un to veda pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Un tā meita bija ļoti skaista un palika ķēniņam par kopēju un tam kalpoja. Bet ķēniņš viņu neatzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Bet Adonija, Aģitas dēls, lielījās un sacīja: es būšu par ķēniņu. Un viņš sev sagādāja ratus un jātniekus un piecdesmit vīrus, kas viņa priekšā skrēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Un viņa tēvs to savu mūžu nebija aprājis, sacīdams: Kāpēc tu tā dari? Un viņš arī bija ļoti skaists, un (Aģita) viņu bija dzemdējusi pēc Absaloma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Un viņš ar Joabu, Cerujas dēlu, bija sarunājies un ar priesteri Abjataru; tie Adonijam gāja palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Bet priesteris Cadoks un Benaja, Jojadas dēls, un pravietis Nātans un Šimejus un Rejus un Dāvida varenie nebija ar Adoniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Un Adonija upurēja avis un vēršus un barotus lopus pie Zoēlet akmens, kas pie Roģela avota, un aicināja visus savus brāļus, ķēniņa dēlus, un visus vīrus no Jūda, ķēniņa kalpus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Bet pravieti Nātanu un Benaju un tos varenos un savu brāli Salamanu viņš nelūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Tad Nātans runāja ar Batsebu, Salamana māti, un sacīja: vai tu neesi dzirdējusi, ka Adonija, Aģitas dēls, ir palicis par ķēniņu un mūsu kungs Dāvids to nezin?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Un nu nāc, es tev došu padomu, ka tu savu dvēseli un sava dēla Salamana dvēseli izglābi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Noej pie ķēniņa Dāvida un saki uz to: vai tu, mans kungs un ķēniņ, savai kalponei neesi zvērējis sacīdams: Salamanam, tavam dēlam, būs par ķēniņu būt pēc manis, un viņš sēdēs uz mana goda krēsla? Kāpēc tad Adonija palicis par ķēniņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Redzi, kamēr tu vēl ar ķēniņu tur runāsi, tad es tev nākšu pakaļ un apstiprināšu tavus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Tad Batseba gāja pie ķēniņa istabā un ķēniņš bija ļoti vecs un Abizaga no Šunemes ķēniņam kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Un Batseba locījās un nometās zemē priekš ķēniņa. Un ķēniņš sacīja: kas tev kait?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Un viņa uz to sacīja: mans kungs, tu savai kalponei pie Tā Kunga, sava Dieva, esi zvērējis: tiešām, tavs dēls Salamans būs par ķēniņu pēc manis un tam būs sēdēt uz mana goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Bet nu redzi, Adonija ir palicis par ķēniņu, un tu, mans kungs un ķēniņ, to nezini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Un viņš ir upurējis vēršus un barotus lopus un daudz avis un aicinājis visus ķēniņa dēlus, ir priesteri Abjataru un kara virsnieku Joabu, bet tavu kalpu Salamanu viņš nav aicinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Bet tu, mans kungs un ķēniņ, - visa Israēla acis uz tevi skatās, ka tev tiem būs darīt zināmu, kas sēdēs uz ķēniņa, mana kunga, goda krēsla pēc viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Un notiks, kad mans kungs, tas ķēniņš, būs gājis dusēt pie saviem tēviem, tad es un mans dēls Salamans būsim par grēciniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Un redzi, viņai vēl ar ķēniņu runājot, pravietis Nātans atnāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Un ķēniņam tika teikts un sacīts: redzi, pravietis Nātans ir še. Un viņš nāca ķēniņa priekšā un metās ar savu vaigu zemē ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Un Nātans sacīja: mans kungs un ķēniņ, vai tu esi sacījis: Adonijam būs par ķēniņu būt pēc manis un tam būs sēdēt uz mana goda krēsla?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Jo viņš šodien ir nogājis un upurējis vēršus un barotus lopus un daudz avis un aicinājis visus ķēniņa dēlus, ir tos kara virsniekus un priesteri Abjataru. Un redzi, tie ēd un dzer viņa priekšā un saka: lai dzīvo ķēniņš Adonija!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Bet mani, kas esmu tavs kalps, un priesteri Cadoku un Benaju, Jojadas dēlu, un tavu kalpu Salamanu viņš nav aicinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Vai šī lieta no ķēniņa, mana kunga, pavēlēta, un vai tu savam kalpam neesi darījis zināmu, kas pēc viņa sēdēs uz ķēniņa, mana kunga, goda krēsla?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Tad ķēniņš Dāvids atbildēja un sacīja: aicinājiet man Batsebu; un tā nāca pie ķēniņa un stāvēja ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Un ķēniņš zvērēja un sacīja: tik tiešam kā Tas Kungs dzīvo, kas manu dvēseli no visām bēdām atpestījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Tiešām, kā es tev pie Tā Kunga, Israēla Dieva, esmu zvērējis sacīdams: Salamans, tavs dēls, būs par ķēniņu pēc manis, un tam būs sēdēt uz mana goda krēsla manā vietā, - tāpat es arī šodien darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Tad Batseba klanījās ar savu vaigu pie zemes un metās zemē priekš ķēniņa un sacīja: lai dzīvo mans kungs, ķēniņš Dāvids, mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Un ķēniņš Dāvids sacīja: aicinājiet man priesteri Cadoku un pravieti Nātanu un Benaju, Jojadas dēlu. Un tie nāca ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Un ķēniņš uz tiem sacīja: ņemiet sava kunga kalpus līdz un sēdinājiet manu dēlu Salamanu uz manu jājamo zirgēzelieni un novediet viņu uz Ģionu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Un lai priesteris Cadoks un pravietis Nātans viņu tur svaida par ķēniņu Israēlim. Pēc tam pūšat ar bazūnēm un sakāt: lai dzīvo ķēniņš Salamans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Un ejat viņam pakaļ un lai tas nāk un sēž uz mana goda krēsla, un lai ir par ķēniņu manā vietā. Un es pavēlu viņam būt par valdītāju pār Israēli un pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Tad Benaja, Jojadas dēls, ķēniņam atbildēja un sacīja: Āmen! Tas Kungs, mana kunga, tā ķēniņa, Dievs lai tāpat saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Itin kā Tas Kungs bijis ar manu kungu, to ķēniņu, tāpat lai viņš ir ar Salamanu, ka viņa goda krēsls top lielāks nekā mana kunga, ķēniņa Dāvida, goda krēsls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Tad priesteris Cadoks un pravietis Nātans un Benaja, Jojadas dēls, un tie Krieti un Plieti nogāja un sēdināja Salamanu uz ķēniņa Dāvida jājamo zirgēzelieni un to pavadīja uz Ģionu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Un priesteris Cadoks ņēma eļļasragu no telts un svaidīja Salamanu. Un tie pūta bazūnes un visi ļaudis sacīja: lai dzīvo ķēniņš Salamans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Un visi ļaudis viņam gāja pakaļ, un tie ļaudis stabulēja ar stabulēm un priecājās ar lielu prieku, tā ka zeme no viņu skaņas rībēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Un Adonija to dzirdēja ar visiem aicinātiem, kas pie viņa bija, un tie jau bija beiguši ēst. Un Joabs dzirdēja arīdzan to bazūnes skaņu un sacīja: kas tā tāda skaņa un troksnis pilsētā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Un kad tas vēl runāja, redzi, tad nāca Jonatāns, priestera Abjatara dēls. Un Adonija sacīja: nāc iekšā, jo tu esi godīgs vīrs un nesīsi labu vēsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Un Jonatāns atbildēja un sacīja uz Adoniju: bet tiešām, mūsu kungs, ķēniņš Dāvids, Salamanu cēlis par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Un ķēniņš ir sūtījis priesteri Cadoku un pravieti Nātanu un Benaju, Jojadas dēlu, un tos Krietus un Plietus viņam līdz, un tie viņu sēdinājuši uz ķēniņa jājamo zirgēzelieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Un priesteris Cadoks un pravietis Nātans to Ģionā svaidījuši par ķēniņu un no turienes priecīgi atnākuši, ka pilsēta rībēt rīb; šī ir tā skaņa, ko jūs esat dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Un Salamans ir nosēdies uz valdības krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Un ķēniņa kalpi ir nākuši mūsu kungam, ķēniņam Dāvidam, labu laimi vēlēt, sacīdami: lai tavs Dievs Salamana vārdu ceļ augstāki nekā tavu vārdu, un viņa goda krēsls lai top augstāks nekā tavs goda krēsls. Un ķēniņš Dievu pielūdzis savā gultā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Un ķēniņš tā sacījis: slavēts lai ir Tas Kungs, Israēla Dievs, kas šodien vienam devis sēdēt uz mana goda krēsla, ka manas acis to redzējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Tad iztrūcinājās un cēlās visi tie aicinātie, kas bija pie Adonijas, un gāja ikviens savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Bet Adonija bijās no Salamana un cēlās un nogāja un satvēra altāra ragus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Un Salamanam teica un sacīja: redzi, Adonija bīstas no ķēniņa Salamana un redzi, viņš altāra ragus ir satvēris un saka: lai ķēniņš Salamans man šodien zvērē, ka viņš savu kalpu ar zobenu nenokaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Tad Salamans sacīja: ja viņš būs krietns vīrs, tad neviens no viņa matiem nekritīs zemē, bet ja ļaunums pie viņa atrodas, tad tam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Un ķēniņš Salamans turp nosūtīja un lika to atvest no altāra. Un tas nāca un metās zemē priekš ķēniņa Salamana. Bet Salamans uz viņu sacīja: ej savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Kad nu Dāvidam laiks atnāca mirt, tad viņš pavēlēja savam dēlam Salamanam un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Es eju visas pasaules ceļu. Tāpēc ņemies drošu prātu un turies kā vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Un sargi, kas jāsargā Tam Kungam, tavam Dievam, staigādams Viņa ceļos, turēdams Viņa likumus, Viņa baušļus un Viņa tiesas un Viņa liecības, tā kā Mozus bauslībā ir rakstīts, ka tu prātīgi turies iekš visa, ko tu dari, un visur, kurp tu griezies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Lai Tas Kungs Savu vārdu apstiprina, ko Tas uz mani runājis, sacīdams: ja tavi dēli savu ceļu sargās, staigādami priekš Mana vaiga uzticīgi ar visu savu sirdi un ar visu savu dvēseli, tad, Viņš sacīja, tev netrūks vīra, kas sēdēs uz Israēla goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Tu arī gan zini, ko Joabs, Cerujas dēls, man ir darījis, un ko viņš darījis Israēla kara virsniekiem, Abneram, Nera dēlam, un Amasum, Jetera dēlam, ka viņš tos nokāvis, un kara asinis izlējis miera laikā un kara asinis licis pie savas jostas, kas ap viņa gurniem, un pie savām kurpēm, kas pie viņa kājām');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tāpēc dari pēc savas gudrības, ka tu viņa sirmiem matiem nelieci ar mieru nākt kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Bet Barzilajus, tā Gileādieša, dēliem, tev būs labu darīt, ka tie ir starp tiem, kas ēd pie tava galda, jo tā tie turējās pie manis, kad es bēgu priekš tava brāļa Absaloma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Un redzi, pie tevis ir Šimejus, Ģera dēls, tas Benjaminiets no Bakurim, kas mani lādēja ar briesmīgu lādēšanu tai dienā, kad es uz Mahānaīm gāju. Bet viņš man nonāca pretī pie Jardānes, un es viņam pie Tā Kunga esmu zvērējis, sacīdams; es tevi ar zobenu nekaušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Bet tu neturi viņu par nenoziedzīgu, jo tu esi gudrs vīrs un gan zināsi, ko tev viņam būs darīt, ka tu viņa sirmiem matiem ar asinīm lieci nākt bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Tā Dāvids gāja dusēt pie saviem tēviem un tapa aprakts Dāvida pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Un tas laiks, kamēr Dāvids ķēniņš bijis pār Israēli, ir četrdesmit gadi; septiņus gadus viņš bija valdījis Hebronē un trīsdesmit un trīs gadus Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Un Salamans sēdēja uz sava tēva Dāvida goda krēsla, un viņa valstība tapa varen stiprināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Un Adonija, Aģitas dēls, nāca pie Batsebas, Salamana mātes; un tā sacīja: vai tu nāc ar mieru? Un viņš sacīja: ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Un viņš sacīja: man ar tevi kas jārunā. Un viņa sacīja: runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Tad viņš sacīja: tu zini, ka man tā valstība piederēja, un visas Israēla acis uz mani skatījās, ka man bija ķēniņam būt; bet nu tā valstība ir novērsta un manam brālim tikusi, jo no Tā Kunga tā viņam ir tikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Bet nu es no tevis lūdzu vienu vienīgu lūgšanu, - neapkauno manu vaigu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Un viņa uz to sacīja: runā. Tad viņš sacīja: runā jel ar ķēniņu Salamanu, jo viņš tavu vaigu neliks kaunā, ka viņš man Abizagu no Šunemes dod par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Un Batseba sacīja: labi, es tevis pēc ar ķēniņu runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Tā Batseba nāca pie ķēniņa Salamana, Adonijas labad ar viņu runāt. Un ķēniņš cēlās viņai pretī un paklanījās priekš tās; un viņš apsēdās uz sava goda krēsla un deva ķēniņa mātei arī krēslu, un tā sēdēja pa viņa labo roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Un viņa sacīja: es lūdzos no tevis vienu mazu lūgšanu, - neapkauno manu vaigu. Un ķēniņš uz to sacīja: lūdz, mana māte, es tavu vaigu neapkaunošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Un viņa sacīja: dod Abizagu no Šunemes savam brālim Adonijam par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Tad ķēniņš Salamans atbildēja un sacīja uz savu māti: kāpēc tad tu prasi Abizagu no Šunemes priekš Adonijas? Prasi priekš viņa arī to valstību, jo viņš ir mans brālis, vecāks nekā es, priekš viņa un Abjatara, tā priestera, un Joaba, Cerujas dēla!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Un ķēniņš Salamans zvērēja pie Tā Kunga un sacīja: lai man Dievs šā un tā dara, tiešām, Adonija šo vārdu būs runājis pret savu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Un nu, tik tiešām kā Tas Kungs dzīvo, kas mani apstiprinājis un mani sēdinājis uz mana tēva Dāvida goda krēslu, un kas man ir namu cēlis, itin kā viņš runājis, tiešām, Adonija šodien taps nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Un ķēniņš Salamans nosūtīja pavēli Benajam, Jojadas dēlam; šis to nokāva, un tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Un uz priesteri Abjataru ķēniņš sacīja: ej uz Anatotu, uz savu tīrumu, jo tu esi nāvi pelnījis. Bet es tevi šodien nenokaušu, tāpēc ka tu Tā Kunga Dieva šķirstu nesis mana tēva Dāvida priekšā, un ka tu līdz panesis visu, ko mans tēvs panesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Tā Salamans izdzina Abjataru, ka tas Tam Kungam vairs nebija par priesteri, lai piepildītos Tā Kunga vārds, ko viņš par Elus namu Šīlo bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Kad nu šī vēsts pie Joaba nāca (jo Joabs bija turējies pie Adonijas, jebšu nebija turējies pie Absaloma), tad Joabs bēga Tā Kunga teltī un satvēra altāra ragus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Un ķēniņam Salamanam tapa sacīts, ka Joabs bēdzis Tā Kunga teltī, un redzi, viņš ir pie altāra. Tad Salamans sūtīja Benaju, Jojadas dēlu, un sacīja: ej, kauj viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Un kad Benaja uz Tā Kunga telti nāca, tad viņš uz to sacīja: tā saka ķēniņš: ej ārā. Bet viņš sacīja: nē, bet še es gribu mirt. Tad Benaja nesa ķēniņam atbildi un sacīja: tā Joabs ir runājis un tā viņš man ir atbildējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Un ķēniņš uz viņu sacīja: dari tā, kā viņš ir runājis, kauj viņu un aproc viņu, ka tu no manis un no mana tēva nama atņem tās asinis, ko Joabs velti izlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Un Tas Kungs lai liek viņa asinīm atkal nākt uz viņa galvu, tāpēc ka viņš ir sitis divus vīrus, kas labāki un taisnāki bija nekā viņš, un tos ir nokāvis ar zobenu, bez mana tēva Dāvida ziņas, proti Abneru, Nera dēlu, Israēla kara virsnieku, un Amasu, Jetera dēlu, Jūda kara virsnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Viņu asinis lai atkal nāk uz Joaba galvu un uz viņa dzimuma galvu mūžīgi. Bet Dāvidam un viņa dzimumam un viņa namam un viņa goda krēslam lai ir miers no Tā Kunga mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Un Benaja, Jojadas dēls, nogāja un sita viņu un to nokāva. Un viņš tapa aprakts savā namā tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Un ķēniņš iecēla Benaju, Jojadas dēlu, viņa vietā pār karaspēku, un priesteri Cadoku ķēniņš iecēla Abjatara vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Un ķēniņš nosūtīja un lika Šimeju aicināt, un uz to sacīja: uztaisi sev namu Jeruzālemē un dzīvo tur un neizej no turienes it nekur;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Un notiks, kurā dienā tu iziesi un iesi pār Kidronas upi, tad zini tiešām, ka tu mirdams mirsi, - tavas asinis lai paliek uz tavas galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Tad Šimejus sacīja uz ķēniņu: tas ir labs vārds; kā mans kungs, tas ķēniņš, ir runājis, tā tavs kalps darīs. Tā Šimejus dzīvoja Jeruzālemē labu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Un notikās pēc trim gadiem, ka Šimejum divi kalpi aizbēga pie Aķisa, Maēkas dēla, Gatas ķēniņa. Un Šimejum teica un sacīja: redzi, tavi kalpi ir Gatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Tad Šimejus cēlās un apsegloja savu ēzeli un nogāja uz Gatu pie Aķisa, savus kalpus meklēt. Un tā Šimejus nogāja un atveda savus kalpus no Gatas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Un Salamanam tapa sacīts, ka Šimejus no Jeruzālemes bija nogājis uz Gatu un atkal pārnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Tad ķēniņš sūtīja un sauca Šimeju un uz to sacīja: vai es tevi pie Tā Kunga neesmu apzvērinājis un tev piekodinājis sacīdams: kurā dienā tu iziesi un iesi šur vai tur, tad zini tiešām, ka tev jāmirst? Un tu sacīji uz mani: es esmu labu vārdu dzirdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Kāpēc tad tu neesi turējis Tā Kunga zvērestu un to pavēli, ko es tev esmu pavēlējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Un ķēniņš sacīja uz Šimeju: tu zini visu to ļaunu, ko tava sirds apzinās, ko tu manam tēvam Dāvidam darījis, tāpēc Tas Kungs tavam ļaunumam atkal licis nākt uz tavu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Bet ķēniņš Salamans būs svētīts, un Dāvida goda krēsls būs pastāvīgs priekš Tā Kunga mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Un ķēniņš pavēlēja Benajam, Jojadas dēlam; tas izgāja un viņu sita, un tas nomira. Tā valstība kļuva apstiprināta caur Salamana roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Un Salamans apdraudzējās ar Faraonu, Ēģiptes ķēniņu, un apņēma Faraona meitu un to ieveda Dāvida pilsētā, tiekams viņš pavisam uztaisīja savu namu un Tā Kunga namu un Jeruzālemes mūrus visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Bet tie ļaudis upurēja uz kalniem, jo līdz tam laikam vēl nams nebija uztaisīts Tā Kunga vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Un Salamans mīlēja To Kungu, staigādams sava tēva Dāvida likumos, tomēr viņš upurēja un kvēpināja uz kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Un ķēniņš nogāja uz Gibeonu, tur upurēt, jo tur bija tas lielais kalns; tūkstoš dedzināmos upurus Salamans upurēja uz šī altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Gibeonā Tas Kungs parādījās Salamanam nakts sapnī; un Dievs sacīja: lūdz, ko Man tev būs dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Tad Salamans sacīja: Tu Savam kalpam, manam tēvam Dāvidam, esi parādījis lielu žēlastību, tā kā viņš Tavā priekšā ir staigājis patiesībā un taisnībā un sirds skaidrībā ar Tevi, un Tu viņam šo lielo žēlastību esi turējis un viņam dēlu devis, kas sēž uz viņa goda krēsla, tā kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Un nu Kungs, mans Dievs, Tu Savu kalpu esi cēlis par ķēniņu mana tēva Dāvida vietā. Un es vēl esmu jauns un nezinu ne iziešanu, ne ieiešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Un Tavs kalps ir likts Tavas tautas vidū, ko Tu esi izredzējis, kas ir liela tauta, ko nevar ne skaitīt ne pārskatīt aiz lielā pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Tad dodi nu Savam kalpam paklausīgu sirdi, Tavus ļaudis tiesāt un gudri izšķirt, kas labs un kas ļauns; jo kas prastu tiesāt šo Tavu tik lielu ļaužu pulku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Un šis vārds Tam Kungam labi patika, ka Salamans bija lūdzis šo lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Un Dievs uz to sacīja: tāpēc ka tu šo lietu esi lūdzis un sev neesi lūdzis garu mūžu, nedz sev esi lūdzis bagātību, nedz lūdzis savu ienaidnieku dvēseles, bet ka tu sev esi lūdzis saprašanu, tiesas lietas izklausīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Redzi, tad Es daru pēc tava vārda. Redzi, Es tev dodu gudru un prātīgu sirdi, ka tāds kā tu priekš tevis nav bijis un pēc tevis vairs necelsies tāds kā tu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Un arī ko tu neesi lūdzis, Es tev dodu, arī bagātību un godu, ka tāds kā tu neviens nebūs starp ķēniņiem visā tavā mūžā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Un ja tu staigāsi Manos ceļos, turēdams Manus likumus un Manus baušļus, itin kā tavs tēvs Dāvids ir staigājis, tad Es tev došu arī garu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Un kad Salamans uzmodās, redzi, tad tas bija sapnis. Un viņš nāca uz Jeruzālemi un nostājās priekš Tā Kunga derības šķirsta un upurēja dedzināmos upurus un nesa pateicības upurus un taisīja visiem saviem kalpiem dzīres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'To brīdi nāca divas maukas pie ķēniņa un nostājās viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Un tā viena sieva sacīja: mans kungs, es un šī sieva dzīvojām vienā namā, un es pie viņas tai namā esmu dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Un notikās trešā dienā, kad es biju dzemdējusi, tad šī sieva arīdzan dzemdēja. Un mēs bijām kopā, un neviena sveša cilvēka pie mums nebija namā, bet mēs divas vien bijām namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Un šīs sievas dēls naktī nomiris, tāpēc ka viņa to nogulējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Un nakts vidū tā ir cēlusies un paņēmusi manu dēlu no maniem sāniem, kamēr tava kalpone gulēja, un to likusi savā klēpī, un savu mirušo dēlu tā atkal ir likusi manā klēpī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Kad es nu no rīta cēlos savu dēlu zīdīt, redzi, tad tas bija nomiris? Bet rītā es viņu labi aplūkoju, un redzi, tas nebija mans dēls, ko es biju dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Tad tā otra sieva sacīja: nē, bet tas dzīvais, tas ir mans dēls, un tas mirušais, tas ir tavs dēls. Un šī atkal sacīja: nē, bet tas mirušais ir tavs dēls, un tas dzīvais ir mans dēls. Tā tās runāja ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Tad ķēniņš sacīja: šī saka: tas dzīvais ir mans dēls un tas mirušais ir tavs dēls. Un tā otra atkal saka: tas mirušais ir tavs dēls un tas dzīvais ir mans dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Un ķēniņš sacīja: atnesiet man zobenu. Un tie atnesa zobenu pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Tad ķēniņš sacīja: pārcērtiet to dzīvo bērnu divējos gabalos un dodiet vienai vienu gabalu un otrai otru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Bet tā sieva, kam tas dzīvais bērns piederēja, sacīja uz ķēniņu (jo viņas sirds iekarsa par savu bērnu un tā sacīja): mans kungs! Dodat viņai to dzīvo bērnu, tikai kaut to nenokaujat! Bet tā otra sacīja: lai tas nav ne mans, ne tavs, cērtat viņu uz pusēm!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Tad ķēniņš atbildēja un sacīja: dodiet viņai to dzīvo bērnu un nenokaujiet to! Tā ir viņa māte.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Un viss Israēls dzirdēja šo spriedumu, ko ķēniņš bija spriedis, un tie bijās ķēniņu; jo tie redzēja, ka Dieva gudrība bija iekš viņa, tiesu spriest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Tā ķēniņš Salamans bija par ķēniņu pār visu Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Un šie ir tie lielkungi, kas viņam bija: Azarija, Cadoka dēls, bija tas (pirmais) lielskungs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elioreps un Ahija, Zizus dēli, bija rakstu vedēji; Jehošafats, Aķiluda dēls, bija kanclers;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Un Benaja, Jojadas dēls, bija karaspēka virsnieks; un Cadoks un Abjatars bija priesteri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Un Azarija, Nātana dēls, bija celts pār uzraugiem; un Zabuds, Nātana dēls, bija lielskungs, ķēniņa draugs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Un Aīzars bija nama uzraugs, un Adonirams, Abdus dēls, bija pār darbiniekiem celts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Un Salamanam bija divpadsmit uzraugi pār visu Israēli, kas ķēniņu un viņa namu apkopa. Ikvienam bija mēnesi par gadu tā apkopšana,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Un šie ir viņu vārdi: Ura dēls bija uz Efraīma kalniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Deķera dēls bija Makacā un Zaālbimā un BetŠemē un Elonā un BetAnanā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ezeda dēls Arubotā, un tam bija vēl Zokus un visa Hefera zeme;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinadaba dēls bija pār NavatDoru, un Tavata, Salamana meita, tam bija par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baēnam, Aķiluda dēlam, bija Taēnaka un Meģidus un visa BetZeana, kas ir sānis Cartanai apakš Jezreēla, no BetZeanas līdz Meola klajumam, līdz viņpus Jokmeamai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ģebera dēls bija Rāmotā Gileādā, un tam bija, Jaīra, Manasus dēla, ciemi Gileādā, viņam bija arī Argoba viducis Bazanā, sešdesmit lielas pilsētas ar mūriem un vara aizšaujamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Aķinadabs, Idus dēls, bija Mahānaīmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Aķimaācs bija iekš Naftalus. Šim arīdzan bija Salamana meita, Basmata, par sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baēna, Uzajus dēls, bija Ašerā un Alotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jehošafats, Paruūs dēls, bija iekš Īsašara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Šimejus, Elas dēls, bija iekš Benjamina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Ģebers, Urus dēls, bija Gileādā, Sihona, Amoriešu ķēniņa zemē, un Oga, Basanas ķēniņa, zemē, un bija tas vienīgais uzraugs tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Jūda un Israēla ļaužu bija daudz, tik daudz, kā smiltis jūrmalā, tie ēda un dzēra un bija priecīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Un Salamans valdīja pār visām valstīm no lielās upes un pār Fīlistu zemi un līdz Ēģiptes robežai; tie nesa dāvanas un kalpoja Salamanam visu viņa mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Un Salamana barība uz vienu dienu bija trīsdesmit kori kviešu miltu, sešdesmit kori citu miltu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Desmit baroti vērši un divdesmit vērši no ganībām un simts avis, bez briežiem un stirnām un meža kazām un barotiem putniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Jo viņš valdīja pār visu to zemi šaipus lielās upes, no Tivzas līdz Gazai, pār visiem ķēniņiem šaipus lielās upes. Un viņam bija miers no visām pusēm visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Un Jūda un Israēls dzīvoja mierā, ikviens apakš sava vīna koka un apakš sava vīģes koka, no Dana līdz Bēršebai visu Salamana mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Un Salamanam bija četrdesmit tūkstoš steliņģu priekš braucamiem zirgiem un divpadsmit tūkstoš jātnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Un tie uzraugi apkopa ikviens savā mēnesī ķēniņu Salamanu un visus, kas pie ķēniņa Salamana galda ēda, - tiem netrūka nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Un miežus un salmus priekš zirgiem un čakliem kamieļiem tie nesa tai vietā, kur viņš bija, ikviens pēc savas kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Un Dievs deva Salamanam gudrību un ļoti dziļu saprašanu un bagātu zināšanu kā smiltis jūrmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Un Salamana gudrība bija lielāka nekā visu austruma zemes bērnu gudrība un nekā visu ēģiptiešu gudrība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Un viņš bija gudrāks pār visiem cilvēkiem, pār Etanu, Ezraka dēlu, un Hemanu un Kalkalu un Dardu, Maālus dēliem, un viņa slava izpaudās pie visām tautām visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Un viņš runāja trīs tūkstoš sakāmus vārdus un viņa dziesmu bija tūkstoš un piecas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Un viņš runāja par kokiem, no ciedru koka uz Lībanus sākot līdz īzapam, kas pie sienas izaug, un viņš runāja arī par lopiem un par putniem un par tārpiem un par zivīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Un no visām tautām nāca klausīties Salamana gudrību, no visiem zemes ķēniņiem, kas bija dzirdējuši par viņa gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Un Hirams, Tirus ķēniņš, sūtīja savus kalpus pie Salamana. (Jo viņš bija dzirdējis, ka šo bija par ķēniņu svaidījuši viņa tēva vietā.) Jo Hirams Dāvidam bija draugs bijis visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Un Salamans sūtīja pie Hirama un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Tu zini, ka mans tēvs Dāvids nevarēja namu uztaisīt Tā Kunga, sava Dieva, vārdam, to karu dēļ, kas viņam bija visapkārt, tiekams Tas Kungs tos lika apakš viņa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Un nu Tas Kungs, mans Dievs, man devis mieru visapkārt, ka nav neviena pretinieka nedz cita ļauna kavēkļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Un redzi, es domāju uztaisīt namu Tā Kunga, sava Dieva, vārdam, itin kā Tas Kungs uz manu tēvu Dāvidu runājis un sacījis: tavs dēls, ko Es tavā vietā sēdināšu uz tavu goda krēslu, tas uztaisīs namu Manam vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Tad nu pavēli, ka man cērt ciedru kokus no Lībanus, un mani kalpi būs ar taviem kalpiem, un to algu priekš taviem kalpiem es tev došu, tā kā tu saki; jo tu zini, ka pie mums neviena nav, kas kokus tā māk cirst kā Sidonieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Un notikās, kad Hirams Salamana vārdus dzirdēja, tad viņš ļoti priecājās un sacīja: slavēts lai ir Tas Kungs šodien, kas Dāvidam gudru dēlu devis pār šo lielo tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Un Hirams sūtīja pie Salamana un sacīja: es esmu dzirdējis, par ko tu pie manis sūtījis. Es darīšu visu tavu prātu ar tiem ciedru kokiem un tām priedēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Maniem kalpiem tos no Lībanus būs novest jūrmalā, un es tos vedīšu ar plostiem pa jūru uz to vietu, ko tu man noteiksi, un es tos tur atraisīšu, ka tu tos vari aizvest. Tu arī darīsi manu prātu un dosi maizi priekš mana nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Tā Hirams Salamanam deva ciedru kokus un priedes, kā viņš pats gribēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Un Salamans Hiramam deva divdesmit tūkstoš koru kviešu maizei priekš viņa nama un divdesmit koru sagrūstas eļļas. To Salamans Hiramam deva ik gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Un Tas Kungs Salamanam deva gudrību, itin kā tam bija runājis. Un starp Hiramu un Salamanu bija miers, un tie abi derēja derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Un ķēniņš Salamans uzlika darba klausību visam Israēlim, un to darbinieku bija trīsdesmit tūkstoš vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Un viņš tos sūtīja uz Lībanu, pa desmit tūkstošiem ik mēnešus pēc kārtas; vienu mēnesi tie bija uz Lībanus un divus mēnešus tie bija mājās, un Adonirams bija uzraugs pār šiem darbiniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Un Salamanam bija septiņdesmit tūkstoš nastu nesēji un astoņdesmit tūkstoš akmens cirtēji uz tā kalna,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Bez tiem Salamana virsuzraugiem, kas pār šo darbu bija iecelti; to bija trīs tūkstoš un trīssimt, kas uzraudzīja tos ļaudis, kas to darbu darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Un ķēniņš pavēlēja, lauzt lielus akmeņus, dārgus akmeņus, apcirstus akmeņus, tam namam likt pamatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Un Salamana amatnieki un Hirama amatnieki un Ģiblieši tos apcirta un apstrādāja tos kokus un tos akmeņus, to namu uztaisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Un notikās četrsimt un astoņdesmitā gadā pēc Israēla bērnu iziešanas no Ēģiptes zemes, ceturtā gadā, kad Salamans valdīja pār Israēli, Ziv mēnesī, (šis ir tas otrs mēnesis), tad viņš taisīja Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Un tas nams, ko ķēniņš Salamans Tam Kungam taisīja, bija sešdesmit olektis garumā un divdesmit platumā un trīsdesmit olektis augstumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Un tas pagalms tā nama priekšā bija divdesmit olektis garumā pēc tā nama platuma, un desmit olektis platumā nama priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Un viņš tam namam taisīja logus, kas bija vienā pusē plati un otrā šauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Un visapkārt pie nama sienas viņš taisīja piebūvi, ap nama sienām visapkārt, ir ap to namu ir ap to visusvētāko vietu, un viņš taisīja sānu kambarus visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Apakšējās istabu rindas platums bija piecas olektis un vidējās platums sešas olektis un trešās platums septiņas olektis, jo viņš lika pakāpes uz ārpusi namam visapkārt, ka nevajadzēja piestiprināšanas nama sienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Un kad tas nams tapa taisīts, tad to taisīja no pilnīgi gataviem kaltiem akmeņiem, tā ka ne veseris, nedz cirvis, nedz cits kāds dzelzs ierocis netika dzirdēts pie tā nama, kad to taisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Un durvis uz apakšējo istabu rindu bija nama labajā pusē, un pa grieztām trepēm bija jāuzkāpj uz vidējo un no vidējās uz trešo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Tā viņš to namu uztaisīja un to pabeidza; un viņš noklāja to namu ar ciedru baļķiem un galdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Un viņš taisīja to piebūvi ap visu to namu, piecas olektis bija viņas augstums, un to piestiprināja pie nama ar ciedru kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Tad Tā Kunga vārds notika uz Salamanu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Šis nams, ko tu uztaisi - ja tu staigāsi Manos likumos un darīsi Manas tiesas un turēsi visus Manus baušļus, pēc tiem staigādams, tad Es Savu vārdu pie tevis apstiprināšu, ko Es esmu runājis uz tavu tēvu Dāvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Un Es dzīvošu Israēla bērnu vidū un neatstāšu Savus Israēla ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Tā Salamans to namu uztaisīja un to pabeidza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Viņš arī apsita nama sienas no iekšpuses ar ciedru dēļiem; no nama grīdas līdz griestiem viņš tās noklāja ar (ciedru) koku iekšpusē, un apsita nama grīdu ar priežu dēļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Un viņš taisīja vēl divdesmit olektis ar ciedru dēļiem nama galā, no grīdas līdz griestiem, to viņš tur taisīja nama iekšpusē dziļumā par visusvētāko vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Un tas nams bija garš četrdesmit olektis, proti tas Dieva nams, kas priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Iekšpusē bija ciedru koki vien pie tā nama, ar izgrieztām pogām un izplaukušām puķēm; viss bija no ciedra koka, tā ka neviens akmens nebija redzams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Un to visusvētāko vietu dziļumā nama iekšpusē viņš taisīja, kur nolikt Tā Kunga derības šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Un visusvētās vietas iekšpuses dziļumā bija divdesmit olektis garumā un divdesmit olektis platumā un divdesmit olektis augstumā, un viņš to pārvilka ar tīru zeltu, un altāri viņš apsita ar ciedru dēļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Un Salamans pārvilka nama iekšpusi ar tīru zeltu, un aiztaisīja ar zelta ķēdēm to visusvētāko vietu dziļumā un to pārvilka ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Tā viņš visu namu pārvilka ar zeltu, visu namu līdz galam, un visu altāri visusvētākās vietas priekšā dziļumā viņš pārvilka ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Un viņš taisīja tai visusvētās vietās dziļumā divus ķerubus no eļļas koka, desmit olektis augstumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Piecas olektis bija katrs ķeruba spārns, no viņa viena spārna gala līdz viņa otra spārna galam bija desmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Tāpat arī otram ķerubam bija desmit olektis; abiem ķerubiem bija vienāds mērs un vienāds izskats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Tas viens ķerubs bija desmit olektis augsts un tāpat arī tas otrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Un viņš tos ķerubus lika nama iekštelpas vidū. Un tie ķerubi izplēta spārnus, tā ka tā viena spārns sniedzās līdz vienai sienai, un tā otra ķeruba spārns līdz otrai sienai, bet viņu spārni nama vidū sniedzās spārns līdz spārnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Un viņš pārvilka tos ķerubus ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Un viņš izrakstīja visas nama sienas visapkārt ar izgrieztiem ķerubiem un palmu kokiem un izplaukušām puķēm iekšpusē un ārpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Viņš pārvilka arī nama grīdu ar zeltu no iekšpuses un no ārpuses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Un dziļumā visu svētākās vietas priekšā viņš taisīja durvis no eļļas koka; durvis ar stenderēm bija (sienas) piektā daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Un tās durvis bija divēju gabalu no eļļas koka, un viņš uz tām rakstīja izgrieztus ķerubus un palmu kokus un izplaukušas puķes, un tās pārvilka ar zeltu; viņš pārvilka ir tos ķerubus un tos palmu kokus ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Un Dieva nama priekšā viņš taisīja stenderes no eļļas koka, (sienas) ceturto daļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Un tās durvis bija divēju gabalu no priežu koka, tā ka ikkatrai durvju pusei bija divi galdi, kas savās eņģēs vērās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Un viņš tās izrakstīja ar izgrieztiem ķerubiem un palmu kokiem un izplaukušām puķēm un pārvilka tos rakstus ar zelta plāksnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Un viņš taisīja iekšējo pagalmu no trim rindām kaltu akmeņu un no vienas rindas ciedru baļķu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Ceturtā gadā, Ziv mēnesī, lika pamatu Tā Kunga namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Un vienpadsmitā gadā, Bul mēnesī, (tas ir astotais mēnesis) pabeidza namu ar visām viņa daļām un ar visu viņa vajadzību; un pie tā strādāja septiņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Bet pie sava nama Salamans strādāja trīspadsmit gadus, kamēr visu namu pabeidza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Un viņš taisīja namu no Lībanus kokiem, simts olektis garumā un piecdesmit olektis platumā un trīsdesmit olektis augstumā, uz četrām ciedru stabu rindām, un uz tiem stabiem bija ciedru sijas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Un ciedru griesti bija virsū uz tām istabām, kas uz tiem stabiem; šo bija četrdesmit pieci pa piecpadsmit ikkatrā rindā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Un treji griesti bija, tā ka logs logam stāvēja pretī trejās kārtās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Un visas durvis un logi bija četrkantīgi no baļķiem, un logs logam bija pretī trijās kārtās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Viņš arī taisīja namu uz stabiem, piecdesmit olektis garumā un trīsdesmit olektis platumā, un vēl vienu namu šim priekšā, un tiem priekšā stabus un slieksni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Viņš arī taisīja namu goda krēslam, kur tiesu turēja, soģa namu, un to apsita ar ciedru galdiem no grīdas līdz griestiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Un viņa paša nams, kur viņš dzīvoja, otrā pagalmā aiz šī nama, tāpat bija taisīts. Un Faraona meitai, ko Salamans bija apņēmis, viņš taisīja namu, kā šo namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Viss tas bija no dārgiem, pēc mēra cirstiem un ar zāģiem zāģētiem akmeņiem iekšpusē un ārpusē no pamata līdz jumtam un ārpusē līdz tam lielam pagalmam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Un tie pamata akmeņi bija arī lieli dārgi akmeņi no desmit olektīm un akmeņi no astoņām olektīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Un uz tiem bija dārgi, pēc mēra izcirsti akmeņi un ciedru koki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Bet tam lielam pagalmam bija visapkārt trīs rindas cirstu akmeņu un viena rinda ciedru baļķu; tāpat bija arī Tā Kunga nama iekšējais pagalms un tā nama priekšnams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Un ķēniņš Salamans sūtīja un lika atvest Hiramu no Tirus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Tas bija atraitnes dēls no Naftalus cilts, un viņa tēvs bija bijis vīrs no Tirus, vara kalējs. Tas bija pilns gudrības un saprašanas un zināšanas, visādu vara darbu darīt. Šis nāca pie ķēniņa Salamana un strādāja visus viņa darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Un viņš taisīja divus vara stabus; katrs stabs bija astoņpadsmit olektis augsts un divpadsmit olektis bija mērs ap katru stabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Viņš taisīja arī divus kroņus no vara izlietus, liekamus uz stabu virsgaliem, piecas olektis bija katra kroņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Un tie kroņi uz tiem stabiem bija aptīti kā ar tīkliem un apvīti kā ar ķēdēm, septiņas bija vienam kronim un septiņas otram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Tā viņš taisīja tos stabus un divās rindas granātābolu ap to tīkla darbu, apsegt tos kroņus, kas bija augšām; tā viņš taisīja arī tam otram kronim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Un tie kroņi uz tiem diviem stabiem bija kā lilijas taisīti tai namā, četras olektis (augstumā).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Un tie kroņi bija uz tiem diviem stabiem un augšām pār to apaļumu bija divsimt granātābolu visapkārt rindās aiz tā tīkla darba; tāpat arī pie tā otra kroņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Un viņš uzcēla tos stabus Dieva nama pagalmā, un to stabu, ko viņš pa labo roku bija uzcēlis, viņš nosauca: Jaķin, un to stabu, ko viņš pa kreiso roku bija uzcēlis, viņš nosauca: Boas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Un augšām uz tiem stabiem bija tas liliju darbs. Tā tas stabu darbs tapa pabeigts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Un viņš taisīja arī vara lietu ūdens trauku, desmit olektis bija no viņa vienas malas līdz otrai malai, visapkārt apaļu, un piecas olektis bija viņa augstums, un tas mērs visapkārt bija trīsdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Un apakšā pie viņa malas bija pogas visapkārt, desmit uz ikvienu olekti, un ap to trauku bija divas rindas no tādām pogām, vienā lējienā lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Un tas stāvēja uz divpadsmit vēršiem; no tiem trīs griezās pret ziemeļa pusi un trīs griezās pret vakara pusi un trīs pret dienvidu pusi un trīs pret rīta pusi un tas vara trauks bija virsū uz tiem, un visas viņu pakaļpuses bija iekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Un viņa biezums bija plaukstas platumā, un viņa mala bija kā kāda biķera mala, kā lilijas zieds; divi tūkstoši batu mēri tanī sagāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Viņš taisīja arī desmit vara krēslus, četras olektis bija krēsla garums un četras olektis viņa platums un trīs olektis viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Un tie krēsli tā bija taisīti: tiem bija sāngaldi starp līstēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Un uz tiem sāngaldiem starp līstēm bija lauvas, vērši un ķerubi, un uz tām līstēm virs un apakš lauvām un vēršiem bija vēl kroņi, kas karājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Un ikkatram krēslam bija četri vara riteņi ar vara asīm. Un viņu četriem stūriem bija turamie, apakš tā katla bija šie vara turamie kroņiem pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Un augšā kroņa iekšpusē tam bija olekts liels caurums un tam apkārt bija taisīta apaļa mala no pusotrām olektīm, un tai caurumā bija izrakstītas bildes, un krēslu sānu galdi bija četrkantīgi un ne apaļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Un tie četri riteņi bija tiem sānu galdiem apakšā, un riteņu asis bija pie tiem krēsliem, un ikkatrs ritenis bija pusotras olekts augsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Un tie riteņi bija taisīti tāpat kā ratu riteņi; viņu asis un viņu rumbas un viņu spieķi un viņu loki bija visi lieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Un tie četri turamie bija uz ikviena krēsla četriem stūriem uz augšu no tā krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Un augšā uz tā krēsla bija apaļa mala visapkārt pusolekts augstumā, un augšā uz tā krēsla bija viņa turamie un viņa sāngaldi pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Un uz viņa turamo sāniem un uz viņa sāngaldiem viņš izgrieza ķerubus, lauvas un palmu kokus, kā ikkatram vietas bija, un kroņi bija visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Tā viņš taisīja tos desmit krēslus, visi bija vienādi lieti, pēc viena mēra, pēc viena izskata.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Viņš taisīja arī desmit vara katlus, ikkatrā katlā sagāja četrdesmit bati, ikkatrs katls bija četras olektis plats, uz ikviena krēsla no tiem desmit krēsliem bija viens katls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Un viņš lika piecus no tiem krēsliem nama labajā pusē, un piecus viņš lika kreisajā nama pusē, bet to vara trauku viņš lika labajā nama pusē, uz to pusi starp rītiem un dienasvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hirams taisīja arī podus, lāpstas un bļodas, un Hirams pabeidza visu to darbu, ko viņš ķēniņam Salamanam darīja priekš Tā Kunga nama:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, '(Proti) tos divus stabus un apaļus kroņus uz tiem diviem stabiem, un tos divus pinumus, kas apsedza tos divus apaļos kroņus stabu virsgalos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Un tos četrsimt granātābolus pie tiem diviem pinumiem, divas rindas granātābolu pie ikkatra pinuma, kas apsedza tos divus apaļos kroņus uz tiem stabiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Un tos desmit krēslus un tos desmit katlus krēslu virsu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Un to vienu vara trauku un tos divpadsmit vēršus apakš tā vara trauka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Un tos podus un tās lāpstas un bļodas. Un visi tie rīki, ko Hirams ķēniņam Salamanam taisīja priekš Dieva nama, bija no spoža vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Jardānes klajumā ķēniņš tos lika liet cietā zemē starp Sukotu un Cartanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Un Salamans pameta nesvērtus visus šos rīkus tā gauži lielā svara dēļ; vara svars palika nezināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salamans taisīja arī visus rīkus priekš Tā Kunga nama, zelta altāri un zelta galdu tām priekšā liekamām maizēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Un lukturus, piecus pa labo roku un piecus pa kreiso roku, visusvētākās vietas priekšā, no tīra zelta ar zelta puķēm un eļļas lukturīšiem un zelta lukts(dakts) šķērēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Un kausus, nažus un bļodas un karotes un kvēpināšanas traukus no tīra zelta; ir tās durvju eņģes nama iekšpusē visusvētākā vietā un pie Dieva nama durvīm bija no zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Tā viss darbs tapa pabeigts, ko ķēniņš Salamans pie Tā Kunga nama darīja. Un Salamans tur ienesa sava tēva Dāvida Dievam svētītās dāvanas, sudrabu un zeltu un tos rīkus, un tos nolika pie Tā Kunga nama mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tad ķēniņš Salamans sapulcināja pie sevis Israēla vecajus un visus cilšu priekšniekus un Israēla bērnu tēvu namu virsniekus Jeruzālemē pie ķēniņa Salamana, pārvest Tā Kunga derības šķirstu no Dāvida pilsētas, - šī ir Ciāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Un visi Israēla vīri sapulcējās pie ķēniņa Salamana uz svētkiem Etanim mēnesī, šis ir tas septītais mēnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Un kad visi Israēla vecaji sanāca, tad priesteri ņēma to šķirstu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Un nesa Tā Kunga šķirstu un saiešanas telti ar visiem svētiem rīkiem, kas bija teltī, tos priesteri un Leviti nesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Un ķēniņš Salamans un visa Israēla draudze, kas pie viņa bija sapulcējusies, gāja viņam līdz šķirsta priekšā, un upurēja avis un vēršus, neizskaitāmu pulku un neizzināmu skaitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Tā priesteri nesa Tā Kunga derības šķirstu savā vietā, Dieva nama dziļumā, visusvētajā vietā, apakš ķerubu spārniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Jo tie ķerubi izplēta savus spārnus pār šķirsta vietu, un tie ķerubi apklāja šķirstu un viņa nesamās kārtis no augšienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Un tās nesamās kārtis bija tik garas, ka kāršu gali bija redzami no tās svētās vietas tās visusvētās vietas priekšā, bet ārpusē tās nebija redzamas, un tās tur ir līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Tai šķirstā nebija nekā, kā vien tie abi akmens galdiņi, ko Mozus Horebā bija ielicis, kad Tas Kungs derību derēja ar Israēla bērniem, kad tie izgāja no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Kad nu tie priesteri izgāja no tās svētās vietas, tad mākonis piepildīja Tā Kunga namu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Un tie priesteri nevarēja stāvēt un kalpot tā mākoņa dēļ. Jo Tā Kunga godība bija piepildījusi Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tad Salamans sacīja: Tas Kungs ir sacījis, ka viņš tumsā gribot dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Celt esmu cēlis namu tev par dzīvokli, mājokli, tev mājot mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Tad ķēniņš atgrieza savu vaigu un svētīja visu Israēla draudzi, un visa Israēla draudze stāvēja, un viņš sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Slavēts lai ir Tas Kungs, Israēla Dievs, kas ar Savu muti runājis uz manu tēvu Dāvidu un ar Savu roku to piepildījis, ko Viņš sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'No tās dienas, kad Es savus Israēla ļaudis esmu izvedis no Ēģiptes, Es nevienu pilsētu neesmu izredzējis starp visām Israēla ciltīm, taisīt namu, lai Mans vārds tur būtu. Bet Dāvidu Es esmu izredzējis, ka tas būtu pār Maniem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Un manam tēvam Dāvidam gan bija prātā, taisīt namu Tā Kunga, Israēla Dieva, vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Bet Tas Kungs sacīja uz manu tēvu Dāvidu: ka tu savā sirdī esi apņēmies, taisīt namu Manam vārdam, to tu gan esi labi darījis, ka tas tavā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Bet tev to namu nebūs taisīt, bet tavam dēlam, kas nāks no taviem gurniem, tas uztaisīs namu Manam vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Un Tas Kungs savu vārdu ir apstiprinājis, ko Viņš runājis. Jo es esmu stājies sava tēva Dāvida vietā, un sēžu uz Israēla goda krēsla, itin kā Tas Kungs runājis, un es esmu uztaisījis namu Tā Kunga, Israēla Dieva, vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Un tur esmu taisījis vietu tam šķirstam, kur Tā Kunga derība, ko Viņš derējis ar mūsu tēviem, kad Viņš tos izveda no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Un Salamans stājās Tā Kunga altāra priekšā, visai Israēla draudzei pretī, un izplēta savas rokas pret debesīm un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Kungs, Israēla Dievs, neviena tāda Dieva nav kā Tu, ne augšā debesīs, nedz apakšā virs zemes; derību un žēlastību Tu turi Saviem kalpiem, kas Tavā priekšā staigā no visas savas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Tu Savam kalpam, manam tēvam Dāvidam, esi turējis, ko tam esi runājis. Ar Savu muti Tu esi runājis un ar Savu roku to piepildījis, tā kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Un nu Kungs, Israēla Dievs, turi Savam kalpam, manam tēvam Dāvidam, arī to, ko Tu tam vēl esi runājis sacīdams: tev netrūks vīra Manā priekšā, kas sēdēs uz Israēla goda krēsla, ja tikai tavi dēli sargās savu ceļu, staigādami Manā priekša, itin kā tu esi staigājis Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nu tad, Israēla Dievs, lai jel Tavs vārds tiešām notiek, ko Tu esi runājis Savam kalpam, manam tēvam Dāvidam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Vai tad patiesi Tas Kungs dzīvotu virs zemes? Redzi, debesis un visu debesu debesis Tevi nevar saņemt, kā tad nu vēl šis nams, ko es esmu taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Bet griezies pie Sava kalpa lūgšanām un pie viņa piesaukšanām, Kungs, mans Dievs, un klausi to saukšanu un lūgšanu, ko Tavs kalps šodien lūdz priekš Tava vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Lai Tavas acis stāv atvērtas dienām naktīm pār šo namu, pār šo vietu, par ko Tu esi sacījis: Mans vārds lai tur ir; ka Tu klausi to lūgšanu, ko Tavs kalps lūgs šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Klausi tad Sava kalpa un Savu Israēla ļaužu sirds lūgšanu, ko tie lūgs šinī vietā, un klausi, kur Tu mīti debesīs, ak klausi un piedod!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Ja kāds būs apgrēkojies pret savu tuvāko un viņam liks zvērēt un nodievoties, un šis nāks un zvērēs priekš Tava altāra šinī namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Tad klausi Tu debesīs un dari un tiesā Savus kalpus, netaisno notiesādams un atmaksādams viņa ceļu uz viņa galvu, un taisno taisnodams, dodams viņam pēc viņa taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Kad Tavi Israēla ļaudis taps kauti savu ienaidnieku priekšā, tāpēc ka tie pret Tevi būs grēkojuši, un kad tie pie Tevis atgriezīsies un dos godu Tavam vārdam un Tevi pielūgs un no sirds piesauks šinī namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Tad klausi Tu debesīs un piedod Savu Israēla ļaužu grēkus un ved tos atkal tai zemē, ko Tu esi devis viņu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Kad debess būs aizslēgta, ka lietus nelīst, tāpēc ka tie pret Tevi grēkojuši, un kad tie šinī vietā lūgs un dos godu Tavam vārdam un atgriezīsies no saviem grēkiem, kad Tu tos pazemojis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Tad klausi Tu debesīs un piedod Savu kalpu un Savu Israēla ļaužu grēkus, ka Tu tiem parādi to labo ceļu, kur tiem jāstaigā, un dod lietu tai zemē, ko Tu devis Saviem ļaudīm par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Kad zemei būs bads, kad būs mēris, bula laiks, rūsa, siseņi, kukaiņi, kad viņu ienaidnieks zemē ielauzīsies pret viņu vārtiem, vai būs kāda cita mocība vai sērga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Visas lūgšanas, visas piesaukšanas, lai lūgtu kas lūgdams no visiem Taviem Israēla ļaudīm, kad tie atzīs savas sirds bēdas un izplētīs savas rokas šinī namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Tad klausi Tu debesīs, Savā mājoklī, kur Tu mīti, un piedod un dari un dod ikvienam pēc visiem viņa ceļiem, itin kā Tu pazīsti viņa sirdi, jo Tu vien pazīsti visu cilvēka bērnu sirdis; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Lai tie Tevi bīstas visu savu mūžu, kamēr tie dzīvos tai zemē, ko Tu esi devis mūsu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Kad arī kāds svešinieks būs, kas nav no taviem Israēla ļaudīm, bet atnācis no tālas zemes Tava vārda dēļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Jo tie dzirdēs par Tavu lielo vārdu un par Tavu stipro roku un par Tavu izstiepto elkoni,) un kad tas nāks un pielūgs šinī namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Tad klausi Tu debesīs, Savā mājoklī, kur Tu mīti, un dari visu, par ko tas svešais Tevi piesauks, lai visas tautas virs zemes atzīst Tavu vārdu un Tevi bīstas, kā Tavi Israēla ļaudis, un lai tie atzīst, ka Tavs vārds ir saukts pār šo namu, ko es esmu uztaisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Kad Tavi ļaudis ies karā pret saviem ienaidniekiem tai ceļā, kur Tu tos sūtīsi, un pielūgs To Kungu, griezušies uz šo pilsētu, ko Tu esi izredzējis, un uz šo namu, ko es tavam vārdam esmu uztaisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Tad klausi Tu debesīs viņu lūgšanas un viņu sirds saukšanas un nes viņiem tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Kad tie pret Tevi apgrēkosies, (jo neviena cilvēka nav, kas negrēkotu) un Tu par tiem dusmosies, un tos nodosi ienaidniekiem, ka viņu uzvarētāji tos cietumā noved ienaidnieku zemē, vai tālu, vai tuvu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Un kad tie to atkal ņems pie sirds tai zemē, kur tie cietumā aizvesti, un atgriezīsies un Tevi piesauks sava cietuma zemē sacīdami: mēs esam grēkojuši un ļaunu darījuši, mēs esam bezdievīgi bijuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'Un kad tie pie Tevis atgriezīsies no visas savas sirds un no visas savas dvēseles savu ienaidnieku zemē, kas tos aizveduši cietumā, un kad tie Tevi pielūgs, griezušies uz savu zemi, ko Tu devis viņu tēviem, uz to pilsētu, ko Tu izredzējis, un uz to namu, ko es tavam vārdam uztaisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Tad klausi Tu debesīs, Savā mājoklī, kur Tu mīti, viņu lūgšanu un viņu sirds saukšanu un nes viņiem tiesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Un piedod Saviem ļaudīm, ko tie pret Tevi grēkojuši, un visus viņu pārkāpumus, ar ko tie pret Tevi noziegušies, un dod tiem žēlastību atrast pie tiem, kas tos cietumā tur, ka tie par viņiem apžēlojās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Jo tie ir Tavi ļaudis un Tavs īpašums, ko Tu esi izvedis no Ēģiptes no tā dzelzs cepļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Lai Tavas acis atvērtas stāv uz Tava kalpa lūgšanu un uz Tavu Israēla ļaužu lūgšanu, ka Tu tos klausi visās lietās, par ko tie Tevi piesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Jo Tu tos Sev esi izredzējis par īpašumu no visām pasaules tautām, itin kā Tu esi runājis caur Savu kalpu Mozu, kad Tu mūsu tēvus izvedi no Ēģiptes zemes, Kungs, Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Un notikās, kad Salamans bija pabeidzis lūgt šo lūgšanu un sirds saukšanu uz To Kungu, tad viņš pacēlās priekš Tā Kunga altāra, kur viņš bija ceļos nometies un savas rokas izpletis pret debesīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Un viņš nostājās un svētīja visu Israēla draudzi ar stipru balsi un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Slavēts lai ir Tas Kungs, kas dusu devis Saviem Israēla ļaudīm, itin kā Viņš runājis; neviens vārds nav zemē kritis no visiem Viņa labiem vārdiem, ko Viņš runājis caur Savu kalpu Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Lai Tas Kungs, mūsu Dievs, ir ar mums, itin kā Viņš bijis ar mūsu tēviem. Viņš lai mūs neatstāj un lai mūs neatmet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Lai Viņš mūsu sirdis griež pie Sevis, ka mēs staigājam visos Viņa ceļos, turēdami Viņa baušļus un Viņa likumus un Viņa tiesas, ko Viņš pavēlējis mūsu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Un lai šie vārdi, ar ko es lūdzis Tā Kunga priekšā, tuvu ir pie Tā Kunga, mūsu Dieva, dienām naktīm, lai Viņš tiesu nes Savam kalpam un Saviem Israēla ļaudīm dienu no dienas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Lai visas pasaules tautas atzīst, ka Tas Kungs ir Dievs un cits neviens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Un lai jūsu sirds paliek pilnīgi pie Tā Kunga, mūsu Dieva, ka jūs staigājat Viņa likumos un turat Viņa baušļus, tāpat kā šodien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Un ķēniņš un viss Israēls līdz ar viņu upurēja upurus Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Un Salamans upurēja pateicības upurus, ko viņš Tam Kungam atnesa, divdesmit un divtūkstoš vēršus un simts un divdesmit tūkstoš avis. Tā ķēniņš ar visiem Israēla bērniem iesvētīja Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Tai dienā ķēniņš svētīja to iekšējo pagalmu, kas Tā Kunga nama priekšā, jo viņš tur upurēja dedzināmu upuri un ēdamu upuri un pateicības upuru taukus. Jo tas vara altāris Tā Kunga priekšā bija pa mazu priekš tā dedzināma upura un tā ēdama upura un tiem pateicības upuru taukiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Un tanī laikā Salamans noturēja svētkus ar visu Israēli, lielu draudzi no Hamata robežas līdz Ēģiptes upei Tā Kunga, mūsu Dieva, priekšā, septiņas dienas un atkal septiņas dienas, pavisam četrpadsmit dienas; astotā dienā viņš tos ļaudis atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Un tie svētīja ķēniņu un gāja uz saviem dzīvokļiem priecīgi un ar līksmu sirdi par visu to labumu, ko Tas Kungs bija darījis Savam kalpam Dāvidam un Saviem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Kad nu Salamans bija pabeidzis taisīt Tā Kunga namu un to ķēniņa namu un visu, uz ko Salamanam bija prieks un ko viņš bija apņēmies taisīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Tad Tas Kungs Salamanam parādījās otru reiz, kā tas viņam Gibeonā bija parādījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Un Tas Kungs uz to sacīja: Es esmu dzirdējis tavu lūgšanu un tavu sirds saukšanu, ko tu Manā priekšā esi lūdzis; Es šo namu esmu svētījis, ko tu esi uztaisījis, lai Mans vārds tur ir mūžīgi, un lai manas acis un mana sirds tur paliek vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Un tu, ja tu staigāsi Manā priekšā, kā tavs tēvs Dāvids staigājis, ar bezvainīgu un skaidru sirdi, darīdams visu, ko Es tev esmu pavēlējis, un turēdams Manus likumus un Manas tiesas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Tad Es tavu valstības krēslu pār Israēli stiprināšu mūžīgi, kā Es esmu runājis tavam tēvam Dāvidam sacīdams: tev netrūks vīra uz Israēla goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Bet ja jūs ar saviem bērniem nogriezīsities nost no Manis, un neturēsiet Manus baušļus un Manus likumus, ko Es licis priekš jūsu acīm, un iesiet un kalposiet citiem dieviem un metīsities zemē priekš tiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Tad Es Israēli izdeldēšu no tās zemes, ko Es tiem esmu devis. Un šo namu, ko Es Savam vārdam esmu svētījis, to Es atmetīšu no Sava vaiga, un Israēls būs par sakāmu vārdu un par apsmieklu visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Un šis nams, kas bijis augsts, tam garām iedams ikviens iztrūcināsies un svilpos un sacīs: kāpēc Tas Kungs tā darījis šai zemei un šim namam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Un tad sacīs: tāpēc ka tie ir atstājuši To Kungu, savu Dievu, kas viņu tēvus izvedis no Ēģiptes zemes, un ir pieķērušies citiem dieviem un priekš tiem metušies zemē un tiem kalpojuši, tāpēc Tas Kungs visam šim ļaunumam licis pār viņiem nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Un notikās pēc divdesmit gadiem, kad Salamans bija uztaisījis tos divus namus, Tā Kunga namu un to ķēniņa namu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Priekš kā Hirams, Tirus ķēniņš, Salamanam bija devis ciedru kokus un priežu kokus un zeltu pēc visas viņa vēlēšanās, tad ķēniņš Salamans Hiramam deva divdesmit pilsētas Galilejas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Un Hirams no Tirus izgāja tās pilsētas aplūkot, ko Salamans tam bija devis, bet tās viņam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Un viņš sacīja: kas tās par pilsētām, brāli, ko tu man esi devis? Un tās nosauca par Kabul (nieku) zemi, līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Jo Hirams bija sūtījis tam ķēniņam simts un divdesmit talentus zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Un tā tas bija ar to darba klausību, ko Salamans uzlika, lai uztaisītu Tā Kunga namu un savu namu un Millu un Jeruzālemes mūrus un Hacoru un Meģidu un Gazeru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Faraons, Ēģiptes ķēniņš, bija nācis un Gazeru uzņēmis un ar uguni sadedzinājis, un nokāvis tos Kanaāniešus, kas tai pilsētā dzīvoja, un to devis līdz par dāvanu savai meitai, Salamana sievai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Un Salamans uztaisīja Gazeru un lejas BetOronu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Un Baēlatu un Tadmoru tās zemes tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Un visas labības pilsētas, kas Salamanam bija, un ratu pilsētas un jātnieku pilsētas un uz ko Salamanam bija prieks un kas viņam patikās taisīt Jeruzālemē un uz Lībanus un visā savas valsts zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Un visiem ļaudīm, kas bija atlikuši no Amoriešiem, Hetiešiem, Fereziešiem, Hiviešiem un Jebusiešiem, kas nebija no Israēla bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Viņu bērniem, kas bija atlikuši pēc viņiem tai zemē, ko Israēla bērni nevarēja izdeldēt, tiem Salamans uzlika klausības darbus līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Bet no Israēla bērniem Salamans nevienu nedarīja par vergu, bet tie bija karavīri un viņa kalpi un viņa lielkungi un viņa karavirsnieki un virsnieki pār viņa ratiem un pār viņa jātniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Un to virsuzraugu pie Salamana darbiem bija piecsimt un piecdesmit, kas uzraudzīja tos ļaudis, kas pie tā darba strādāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Kad Faraona meita pārgāja no Dāvida pils savā namā, ko viņš tai bija taisījis, tad viņš uztaisīja Millu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Un Salamans upurēja gadskārtā trīsreiz dedzināmos upurus un pateicības upurus uz tā altāra, ko viņš Tam Kungam bija taisījis, un kvēpināja uz tā, Tā Kunga priekšā; un tā viņš to namu pabeidza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Un ķēniņš Salamans taisīja arī kuģus EceonĢeberā, pie Elotas, niedru jūras malā, Edoma zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Un Hirams sūtīja uz tiem kuģiem savus kalpus, kas bija kuģinieki un jūras pazinēji, līdzi Salamana kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Un tie nāca uz Ofiru un pārveda no turienes četrsimt un divdesmit talentus zelta, un to noveda ķēniņam Salamanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Un kad Sabas ķēniņiene dzirdēja Salamana slavu, kas tam bija Tā Kunga vārda dēļ, tad viņa nāca, to pārbaudīt ar mīklām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Un tā nāca uz Jeruzālemi ar ļoti lielu pulku, ar kamieļiem, kas nesa dārgas zāles un ļoti daudz zelta un dārgu akmeņu. Un tā nāca pie Salamana un runāja ar viņu visu, kas bija viņas sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Un Salamans viņai izstāstīja visus viņas vārdus; nekas ķēniņam nebija paslēpts, ko viņš tai nebūtu izstāstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Kad nu Sabas ķēniņiene redzēja visu Salamana gudrību un to namu, ko viņš bija uztaisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Un viņa galda ēdienus un viņa kalpu dzīvokļus un viņa sulaiņu vietas un viņu drēbes un viņa dzēriena devējus un to ejamo ceļu, kur viņš gāja Tā Kunga namā, tad viņai tikko neaizrāvās(elpa),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Un tā sacīja uz ķēniņu: tā slava ir patiesīga, ko es savā zemē esmu dzirdējusi par tavu dzīvi un par tavu gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Un es tai valodai neesmu ticējusi, tiekams esmu atnākusi un savām acīm to redzējusi. Un redzi, man nav ne puse stāstīta; tev ir vairāk gudrības un labuma, nekā tā slava, ko esmu dzirdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Svētīgi tavi ļaudis, svētīgi šie tavi kalpi, kas vienmēr stāv tavā priekšā, un dzird tavu gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Slavēts lai ir Tas Kungs, tavs Dievs, kam ir labs prāts uz tevi, ka tevi cēlis uz Israēla goda krēslu; tāpēc ka Tas Kungs Israēli mīļo mūžīgi, Viņš tevi iecēlis par ķēniņu, darīt tiesu un taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Un viņa deva ķēniņam simts un divdesmit talentus zelta un ļoti daudz dārgu zāļu un dārgu akmeņu; tik daudz dārgu zāļu vairs tur nenonāca, kā Sabas ķēniņiene bija devusi ķēniņam Salamanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Un arī Hirama kuģi, kas no Ofira zeltu atveda, nesa no Ofira ļoti daudz Almuģim koku un dārgu akmeņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Un ķēniņš Salamans taisīja no Almuģim koka stabus priekš Tā Kunga nama un priekš ķēniņa nama un kokles un stabules dziedātājiem. Tāds Almuģim koks nebija vēl nācis nedz redzēts līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Un ķēniņš Salamans deva Sabas ķēniņienei visu, ko tā gribēja un prasīja, bez tā, ko ķēniņš Salamans viņai deva pats no sevis. Un tā griezās atpakaļ un aizgāja ar saviem kalpiem atkal uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Un tā zelta svars, kas Salamanam ienāca vienā gadā, bija sešsimt sešdesmit un seši talenti zelta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Bez tiem ienākumiem no veikalniekiem un no tirgotājiem un no visiem Arābijas ķēniņiem un no visiem zemes pārvaldniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Un ķēniņš Salamans taisīja divsimt priekšturamās bruņas no kalta zelta, sešsimt zelta gabalus viņš deva priekš vienām priekšturamām bruņām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Un trīssimt sedzamās bruņas no kalta zelta, trīs mārciņas zelta viņš deva priekš vienām sedzamām bruņām. Un ķēniņš tās ielika Lībanus koku namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Un ķēniņš taisīja arī lielu goda krēslu no ziloņkaula un to pārvilka ar tīru zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Šim krēslam bija seši pakāpieni, un tā krēsla mugura augšpusē bija apaļa, un abējos sānos bija lēnes(roku balsti) ap sēdekli, un divas lauvas stāvēja pie tām lēnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Un divpadsmit lauvas tur stāvēja uz tiem sešiem pakāpieniem abējās pusēs; tāds nevienā valstī nav taisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Un visi ķēniņa Salamana dzeramie trauki bija no zelta, un visi trauki Lībanus koku namā bija no tīra zelta. Sudraba tur nebija, jo Salamana laikā to neturēja par neko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Bet ķēniņam bija lieli kuģi jūrā (kopā) ar Hirama kuģiem; šie kuģi nāca pa trim gadiem vienreiz atpakaļ un pārveda zeltu un sudrabu, ziloņkaulu un mērkaķus un pāvus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Tā ķēniņš Salamans kļuva lielāks nekā visi ķēniņi virs zemes bagātībā un gudrībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Un visa pasaule meklēja Salamanu redzēt, ka tie viņa gudrību dzirdētu, ko Dievs viņam bija devis sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Un ikkatrs no tiem atnesa dāvanas, sudraba un zelta traukus un drēbes un ieročus un dārgas zāles un zirgus un zirgēzeļus, tā bija gadu no gada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Un Salamans sakrāja ratus un jātniekus, un viņam bija tūkstoš un četrsimt rati un divpadsmit tūkstoš jātnieki, un viņš tos lika tais ratu pilsētās un Jeruzālemē pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Un ķēniņš darīja, ka Jeruzālemē bija tik daudz sudraba kā akmeņu, un tik daudz ciedru koku kā meža vīģes koku ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Un Salamanam atveda no Ēģiptes zirgus, un pulks ķēniņa tirgotāju pirka šos pulkiem par naudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Un rati no Ēģiptes tapa atvesti par sešsimt sudraba gabaliem, un viens zirgs par simt piecdesmit. Un tā caur viņu roku tie tapa atvesti visiem Hetiešu ķēniņiem un Sīrijas ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Un ķēniņš Salamans iemīlēja daudz svešas sievas, bez Faraona meitas vēl Moaba, Ammona, Edoma, Sidona un Hetiešu meitas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'No tām tautām, par ko Tas Kungs uz Israēla bērniem bija sacījis: jums nebūs pie tiem ieiet, un lai tie tāpat neieiet pie jums; tie patiesi jūsu sirdis locīs saviem dieviem pakaļ - šīm Salamans pieķērās ar mīlestību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Un viņam bija septiņsimt sievas no augstas kārtas un trīssimt liekas sievas, un viņa sievas novērsa viņa sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Kad nu Salamans bija vecs palicis, tad viņa sievas viņa sirdi novērsa svešiem dieviem pakaļ, un viņa sirds nepalika pilnīgi pie Tā Kunga, sava Dieva, kā viņa tēva Dāvida sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Tā Salamans staigāja pakaļ Astartei, Sidonas dieveklei, un Milkomam, Amoniešu negantam elkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Un Salamans darīja, kas bija ļauns Tā Kunga acīs, un nedzinās taisni pēc Tā Kunga, kā viņa tēvs Dāvids.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tolaik Salamans uztaisīja kalna altāri Kamosam, Moabiešu negantam elkam, tai kalnā Jeruzālemei pretī, un Molekam, Amoniešu negantam elkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Un tā Salamans darīja visām savām svešām sievām, kas saviem elkudieviem kvēpināja un upurēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Un Tas Kungs iedusmojās par Salamanu, ka tas savu sirdi bija novērsis no Tā Kunga, Israēla Dieva, kas viņam divkārt bija parādījies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Un to viņam bija pavēlējis, svešiem dieviem nestaigāt pakaļ, - un viņš taču nebija turējis, ko Tas Kungs bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Tad Tas Kungs sacīja uz Salamanu: tāpēc ka tas tev prātā nācis, un tu neesi sargājis Manu derību un Manus likumus, ko Es tev esmu pavēlējis, tad Es rautin atraušu to valstību no tevis un to došu tavam kalpam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Tikai tavā laikā Es to nedarīšu tava tēva Dāvida dēļ; no tava dēla rokas Es to atraušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Tikai visu valstību Es neatraušu; vienu cilti Es došu tavam dēlam, Sava kalpa Dāvida dēļ un Jeruzālemes labad, ko Es esmu izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Un Tas Kungs cēla Salamanam pretinieku Hadadu no Edoma; tas bija no ķēniņa dzimuma Edomā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Jo kad Dāvids bija Edomā bijis, un Joabs, tas kara virsnieks, gājis aprakt tos nokautos, un kāvis visus no vīriešu kārtas Edomā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Jo Joabs tur palika sešus mēnešus ar visu Israēli, kamēr visus vīriešus Edomā bija izdeldējis),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Tad Hadads bija izbēdzis un ar viņu citi Edomiešu vīri no viņa tēva kalpiem, un gājis uz Ēģipti, bet Hadads bija vēl mazs puisēns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Un tie cēlās no Midijanas un nonāca Pāranā un ņēma vīrus no Pārana sev līdz un nāca uz Ēģipti pie Faraona, Ēģiptes ķēniņa, un tas viņam deva namu un nosacīja maizi un viņam deva zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Un Hadads atrada lielu žēlastību Faraona acīs, un šis viņam deva par sievu savas sievas, ķēniņienes Tapenes, māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Un Tapenes māsa viņam dzemdēja dēlu, Ģenubatu; šo Tapene uzaudzināja Faraona namā, un Ģenubats bija Faraona namā starp Faraona dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Kad nu Hadads Ēģiptē dzirdēja, ka Dāvids bija aizgājis dusēt pie saviem tēviem, un ka Joabs, tas kara virsnieks, bija nomiris, tad Hadads sacīja uz Faraonu: atlaidi mani, ka es eju uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Bet Faraons uz to sacīja: kā tev pie manis vēl trūkst? Un redzi, tu gribi iet uz savu zemi? Viņš sacīja: nekā, taču atlaidi mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Dievs cēla viņam arī par pretinieku Rezonu, Elijada dēlu; tas bija bēdzis no sava kunga HadadEzera, Cobas ķēniņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Un sapulcinājis pret viņu vīrus un bija sirotāju virsnieks, kad Dāvids tos apkāva, un tie gāja uz Damasku un tur dzīvoja un valdīja Damaskā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Un viņš bija Israēla pretinieks, kamēr Salamans dzīvoja, un tas pienāca klāt pie tā ļaunuma, ko Hadads darīja; un viņam rieba Israēls un viņš valdīja pār Sīriju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Vēl bija Jerobeams, Nebata dēls, Efratietis no Caredas, Salamana kalps, un viņa māte bija Cerua vārdā, atraitne, - tas arī pacēla savu roku pret ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Un šī ir tā lieta, kāpēc viņš roku pacēla pret ķēniņu: kad Salamans Millu taisīja, tad viņš aiztaisīja to gravu sava tēva Dāvida pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Un Jerobeams bija varens vīrs. Kad Salamans to jaunekli bija redzējis, ka tas bija krietns strādnieks, tad viņš to iecēla pār visām Jāzepa nama klausībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Un notikās tanī laikā, kad Jerobeams izgāja no Jeruzālemes, tad pravietis Ahija no Šīlo to sastapa ceļā, un viņš bija jaunu mēteli aplicis, un tie abi divi vien bija uz lauka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Un Ahija ņēma to jauno mēteli, kas viņam bija mugurā, un to saplēsa divpadsmit gabalos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Un viņš sacīja uz Jerobeamu: ņem sev desmit gabalus. Jo tā saka Tas Kungs, Israēla Dievs: redzi, Es atraušu to valstību no Salamana rokas un tev došu desmit ciltis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Bet viena cilts viņam paliks mana kalpa Dāvida dēļ un Jeruzālemes pilsētas labad, ko esmu izredzējis no visām Israēla ciltīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Tāpēc ka tie Mani atstājuši un metušies zemē priekš Astartes, Sidoniešu dievekles, ir priekš Kamosa, Moabiešu dieva, un priekš Milkoma, Amona bērnu dieva, un nav staigājuši Manos ceļos, nedz darījuši, kas ir pareizi Manās acīs, Manus likumus un Manas tiesas, kā viņa tēvs Dāvids.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Tomēr Es no viņa rokas neņemšu visu valstību, bet Es viņu atstāju par valdītāju, kamēr viņš dzīvo, Mana kalpa Dāvida dēļ, ko esmu izredzējis, kas turējis Manus baušļus un Manus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Bet no viņa dēla rokas Es atņemšu to valstību un tev došu desmit ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Un viņa dēlam Es došu vienu cilti, lai Manam kalpam Dāvidam vienmēr paliek gaišums Jeruzālemes pilsētā, ko Sev esmu izredzējis, tur likt Savu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Es tevi ņemšu, un tev būs valdīt, kā tavai dvēselei patīk, un tu būsi Israēlim par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Un ja tu klausīsi visu, ko Es tev pavēlēšu, un staigāsi Manos ceļos un darīsi, kas ir pareizi Manās acīs, turēdams Manus likumus un Manus baušļus, kā Mans kalps Dāvids darījis, tad Es būšu ar tevi un tev celšu pastāvīgu namu, kā Dāvidam esmu cēlis, un tev došu Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Un tāpēc Es pazemošu Dāvida dzimumu, bet ne mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Un Salamans meklēja Jerobeamu nokaut, bet Jerobeams cēlās un aizbēga uz Ēģipti pie ķēniņa Zizaka un bija Ēģiptes zemē, kamēr Salamans mira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Un kas vēl par Salamanu stāstāms, un viss, ko viņš darījis, un viņa gudrība, tas ir uzrakstīts tai grāmatā par Salamana darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Un tas laiks, kamēr Salamans par ķēniņu bijis Jeruzālemē pār visu Israēli, ir četrdesmit gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Un Salamans gāja dusēt pie saviem tēviem un tapa aprakts Dāvida, sava tēva, pilī, un Rekabeams, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Un Rekabeams nogāja uz Šehemi, jo viss Israēls bija nācis uz Šehemi, viņu celt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Un Jerobeams, Nebata dēls, (to) dzirdēja vēl būdams Ēģiptes zemē, (jo viņš no ķēniņa Salamana bija bēdzis un dzīvoja Ēģiptes zemē).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Tad tie nosūtīja un viņu aicināja. Un Jerobeams un visa Israēla draudze nāca un runāja ar Rekabeamu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Tavs tēvs mums ir uzspiedis visai grūtu jūgu; atvieglini nu to grūto kalpošanu un to smago jūgu, ko tavs tēvs mums uzlicis, tad mēs tev gribam kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Bet viņš uz tiem sacīja: noejat līdz parītam, tad atnākat atkal pie manis. Un tie ļaudis aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Un ķēniņš Rekabeams prasīja padomu no tiem vecajiem, kas viņa tēva Salamana priekšā bija stāvējuši, kad tas vēl dzīvoja, un viņš sacīja: Kādu padomu jūs dodat, kā šiem ļaudīm būs atbildēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Un tie uz viņu runāja un sacīja: ja tu šodien šiem ļaudīm iztiksi un tiem darīsi pa prātam un tos paklausīsi un labus vārdus uz tiem runāsi, tad tie tev būs par kalpiem visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Bet viņš atmeta to vecaju padomu, ko tie viņam bija devuši, un prasīja padomu no tiem jauniem, kas ar viņu bija uzauguši un viņa priekšā stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Un viņš uz tiem sacīja: kādu padomu jūs dodat, kā lai atbildam šiem ļaudīm, kas uz mani runājuši un sacījuši: atvieglini to jūgu, ko tavs tēvs mums uzlicis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Un tie jaunie, kas ar viņu bija uzauguši, uz to runāja un sacīja: tā tev būs sacīt uz tiem ļaudīm, kas uz tevi runājuši un sacījuši: tavs tēvs mūsu jūgu grūtu darījis, tad atvieglini tu to mums, - tā tev uz tiem būs sacīt: mans mazais pirksts resnāks nekā mana tēva gurni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Ja nu mans tēvs jums uzlicis grūtu jūgu, tad es to jūgu jums padarīšu vēl grūtāku. Mans tēvs jūs pārmācījis ar pātagām, bet es jūs pārmācīšu ar skorpioniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Un trešā dienā Jerobeams un visi ļaudis nāca pie Rekabeama, kā ķēniņš bija runājis un sacījis: atnākat atkal pie manis trešā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Un ķēniņš tiem ļaudīm atbildēja bargi, jo viņš atmeta to vecaju padomu, ko tie viņam bija devuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Un viņš uz tiem runāja pēc to jauno padoma sacīdams: mans tēvs jūsu jūgu ir darījis grūtu, bet es jums to darīšu vēl grūtāku. Mans tēvs jūs pārmācījis ar pātagām, bet es jūs pārmācīšu ar skorpioniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Un ķēniņš neklausīja tos ļaudis, jo tā tas bija no Tā Kunga nolikts, ka notiktu pēc tā vārda, ko Tas Kungs bija runājis caur Ahiju no Šīlo uz Jerobeamu, Nebata dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Kad nu viss Israēls redzēja, ka ķēniņš viņiem neklausīja, tad tie ļaudis ķēniņam atkal atbildēja un sacīja: kāda daļa mums ir ar Dāvidu? Mums nav īpašuma pie Isajus dēla. Israēl, ej savos dzīvokļos; zinies nu par savu namu, Dāvid! Tā Israēls gāja uz saviem dzīvokļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Bet tik pār tiem Israēla bērniem, kas dzīvoja Jūda pilsētās, Rekabeams bija ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Tad ķēniņš Rekabeams sūtīja Adoramu, kas bija strādnieku uzraugs; bet viss Israēls to nomētāja akmeņiem, ka tas nomira. Bet ķēniņš Rekabeams kāpa steigšus ratos, bēgt uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Tā Israēls atkrita no Dāvida nama līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Un kad viss Israēls dzirdēja, ka Jerobeams bija pārnācis, tad tie sūtīja un viņu aicināja uz sapulci un cēla par ķēniņu pār visu Israēli. Neviens neturējās pie Dāvida nama, kā Jūda cilts vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Kad nu Rekabeams nonāca Jeruzālemē, tad viņš sapulcēja visu Jūda namu un Benjamina cilti, simts un astoņdesmit tūkstoš izlasītus kara vīrus, karot ar Israēla namu, valstību atkal vest pie Rekabeama, Salamana dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Bet Dieva vārds notika uz Šemaju, Dieva vīru, tā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Runā uz Rekabeamu, Salamana dēlu, Jūda ķēniņu, un uz visiem Jūda un Benjamina bērniem un uz tiem citiem ļaudīm un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Tā saka Tas Kungs: jums nebūs celties un karā iet pret saviem brāļiem, Israēla bērniem; griežaties atpakaļ, ikkatrs savā namā, jo šī lieta caur mani notikusi. Un tie klausīja Tā Kunga vārdam un griezās atpakaļ un aizgāja pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Un Jerobeams uztaisīja Šehemi Efraīma kalnos un tur dzīvoja, un izgāja no turienes un uztaisīja Pnuēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Un Jerobeams domāja savā sirdī: nu tā valstība atkal nāks pie Dāvida nama;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Ja šie ļaudis ies uz Jeruzālemi upurēt Tā Kunga namā, tad šo ļaužu sirds atkal griezīsies pie sava kunga, pie Rekabeama, Jūda ķēniņa, un tie mani nokaus un griezīsies atkal pie Rekabeama, Jūda ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Tāpēc ķēniņš aprunājās un taisīja divus zelta tēlus, un sacīja uz tiem (ļaudīm): jums pa daudz, iet uz Jeruzālemi, redzi, še tavs dievs, Israēl, kas tevi no Ēģiptes zemes izvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Un viņš lika vienu Bētelē un otru Danā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Un tas bija par apgrēcību; jo tie ļaudis gāja gan pie tā viena, gan pie tā otra līdz Danam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Viņš taisīja arī kalna altāra namu un iecēla priesterus no visādiem ļaudīm, kas nebija no Levja bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Un Jerobeams turēja svētkus astotā mēnesī piecpadsmitā mēneša dienā, tāpat kā tos svētkus, kas iekš Jūda bija, un upurēja uz tā altāra. Tā viņš Bētelē darīja, tiem teļiem upurēdams, ko viņš bija taisījis; viņš iecēla arīdzan Bētelē priesterus pie tiem kalna altāriem, ko viņš bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Un viņš upurēja uz tā altāra, ko viņš Bētelē bija taisījis, piecpadsmitā mēneša dienā, astotā mēnesī, ko viņš pats bija izdomājis; tā viņš Israēla bērniem iecēla svētkus un upurēja uz tā altāra kvēpinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Un redzi, viens Dieva vīrs nāca no Jūda caur Tā Kunga vārdu uz Bēteli, un Jerobeams stāvēja pie tā altāra kvēpinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Un viņš sauca pret to altāri caur Tā Kunga vārdu un sacīja: altāri! altāri! Tā saka Tas Kungs: Redzi, viens dēls dzims no Dāvida nama, Josija vārdā, un tas upurēs uz tevi tos kalna altāru priesterus, kas uz tevis kvēpina, un cilvēku kauli uz tevis taps sadedzināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Un viņš tai pašā dienā deva brīnuma zīmi un sacīja: šī ir tā brīnuma zīme, ko Tas Kungs runājis: Redzi, tas altāris plīsīs, un tie pelni, kas uz tā, taps nogāzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Kad nu ķēniņš no Tā Dieva vīra šo vārdu dzirdēja, ko tas sauca pret Bēteles altāri, tad Jerobeams savu roku izstiepa no tā altāra un sacīja: grābiet viņu! Bet viņa roka, ko viņš pret to bija izstiepis, sakalta, un viņš to vairs nevarēja savilkt pie sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Un tas altāris plīsa pušu un tie pelni nogāzās no tā altāra, pēc tās brīnuma zīmes, ko tas Dieva vīrs bija devis caur Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Tad ķēniņš atbildēja un sacīja uz to Dieva vīru: pielūdz jel To Kungu, savu Dievu, un aizlūdz par mani, ka mana roka atkal paliek vesela. Tad tas Dieva vīrs pielūdza To Kungu, un tā ķēniņa roka palika atkal vesela un kļuva tā kā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Un ķēniņš sacīja uz to Dieva vīru: nāc man līdz mājās un atspirdzinājies, un es tev došu dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Bet tas Dieva vīrs sacīja uz ķēniņu: jebšu tu man dotu savu pusnamu, tad es tev negribu līdz iet. Es arī neēdīšu maizes un nedzeršu ūdens šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Jo tā Tas Kungs man ir pavēlējis caur Savu vārdu sacīdams: tev nebūs nedz maizes ēst nedz ūdens dzert, tev arī nebūs atpakaļ nākt pa to ceļu, pa ko tu esi nogājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Un viņš gāja pa citu ceļu un negriezās atpakaļ pa to ceļu, pa ko tas bija nācis uz Bēteli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Un viens vecs pravietis dzīvoja Bētelē, tā dēls nāca un viņam teica visu to darbu, ko tas Dieva vīrs tai dienā Bētelē bija darījis, un tos vārdus, ko viņš uz ķēniņu bija runājis; un kad tie to savam tēvam bija stāstījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Tad viņu tēvs uz tiem sacīja: pa kuru ceļu tas ir aizgājis? Un viņa dēli to ceļu bija redzējuši, pa kuru tas Dieva vīrs bija aizgājis, kas no Jūda bija atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Tad viņš sacīja uz saviem dēliem: apseglojiet man ēzeli. Un tie tam apsegloja ēzeli, un viņš uz tā jāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Un viņš tam Dieva vīram devās pakaļ un to atrada apakš ozola sēžam un uz to sacīja: vai tu esi tas Dieva vīrs, kas no Jūda nācis? Un viņš sacīja: es tas esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Tad viņš uz to sacīja: nāc ar mani namā un ēd maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Bet tas sacīja: es nevaru ar tevi atpakaļ griezties nedz ar tevi iet, es arī neēdīšu maizes un nedzeršu ar tevi ūdens šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Jo uz mani sacīts caur Tā Kunga vārdu: tev tur nebūs maizes ēst nedz ūdens dzert, tev nebūs atpakaļ griezties un nebūs aiziet pa to ceļu, pa ko tu esi nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Un viņš uz to sacīja: es arīdzan esmu pravietis, tāpat kā tu, un eņģelis ar mani runājis caur Tā Kunga vārdu sacīdams: ved viņu sev līdz savā namā, ka tas maizi ēd un ūdeni dzer. Bet viņš tam meloja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Tā tas ar viņu griezās atpakaļ un ēda ar viņu maizi viņa namā un dzēra ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Un tiem pie galda sēžot Tā Kunga vārds notika uz to pravieti, kas viņu bija atpakaļ vedis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Un sauca uz to Dieva vīru, kas no Jūda bija nācis, un sacīja: tā saka Tas Kungs: tāpēc ka tu Tā Kunga mutei esi pretī turējies un Viņa pavēli neesi darījis, ko Tas Kungs, tavs Dievs, tev pavēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Bet esi atpakaļ griezies un maizi ēdis un ūdeni dzēris šai vietā, par ko viņš uz tevi bija runājis: tev nebūs maizes ēst nedz ūdens dzert; tad tavs līķis nenāks tavu tēvu kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Kad nu tas bija maizi ēdis un dzēris, tad viņš tam segloja ēzeli, tam pravietim, ko viņš bija atpakaļ vedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Un tas nogāja un lauva to atrada uz ceļa un to nonāvēja, un viņa līķis gulēja ceļā nomests, un tas ēzelis pie tā stāvēja, un tas lauva stāvēja pie tā līķa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Un redzi, kad ļaudis gāja garām un redzēja to līķi ceļā nomestu, un to lauvu pie tā līķa stāvam, tad tie nāca un to pasludināja tai pilsētā, kur tas vecais pravietis dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kad tas pravietis, kas viņu no ceļa bija atpakaļ vedis, to dzirdēja, tad viņš sacīja: tas ir tas Dieva vīrs, kas Tā Kunga mutei pretī turējies, tāpēc Tas Kungs viņu nodevis lauvām, kas viņu saplēsis un nonāvējis, pēc Tā Kunga vārda, ko viņš uz to runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Un viņš runāja uz saviem dēliem sacīdams: apseglojiet man ēzeli. Un tie to apsegloja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Tad viņš gāja un atrada viņa līķi ceļā nomestu, un tas ēzelis un tas lauva stāvēja pie tā līķa. Tas lauva to līķi nebija ēdis un to ēzeli nebija saplēsis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Tad tas pravietis pacēla Tā Dieva vīra līķi un to lika uz to ēzeli un to veda atpakaļ; tā tas vecais pravietis nāca pilsētā, viņu apgaust un aprakt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Un viņš viņa līķi lika savā kapā un tie to apgauda: vai manu brāli!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Un kad viņš to bija apracis, viņš runāja uz saviem dēliem sacīdams: kad es nomirstu, tad aprociet mani tai kapā, kur tas Dieva vīrs aprakts, lieciet manus kaulus pie viņa kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Jo tas vārds notiks, ko viņš caur Tā Kunga vārdu izsaucis pret Bēteles altāri un pret visiem kalnu altāru namiem, kas ir Samarijas pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Pēc šīm lietām Jerobeams neatgriezās no sava ļaunā ceļa, bet iecēla atkal kalnu altāru priesterus no visādiem ļaudīm. Kam gribējās, to viņš iecēla, un tie palika par kalnu altāru priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Un tas palika par grēku Jerobeama namam, par samaitāšanu un par izdeldēšanu no zemes virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Tanī laikā Abija, Jerobeama dēls, saslima.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Un Jerobeams sacīja uz savu sievu: celies un pārģērbies, ka neviens tevi nepazīst, ka tu esi Jerobeama sieva, un ej uz Šīlo; redzi, tur ir pravietis Ahija, kas par mani runājis, ka es būšot ķēniņš pār šiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Un ņem savā rokā desmit maizes un raušus un krūzi ar medu, un ej pie viņa; viņš tev dos ziņu, kas tam bērnam notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Un Jerobeama sieva tā darīja un cēlās un gāja uz Šīlo un nāca Ahijas namā. Bet Ahija nevarēja redzēt, jo viņa acis bija tumšas metušās no vecuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Bet Tas Kungs sacīja uz Ahiju: redzi, Jerobeama sieva nāk, tev ko vaicāt sava dēla pēc, jo tas ir slims. Tā un tā tev uz viņu būs runāt; kad viņa nāks, tad izliksies sveša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Kad nu Ahija dzirdēja viņas kāju troksni, viņai pa durvīm ienākot, tad viņš sacīja: nāc iekšā, Jerobeama sieva, kāpēc tu liecies sveša? Es tev esmu bargs vēstnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Ej, saki Jerobeamam: tā saka Tas Kungs, Israēla Dievs: tāpēc ka Es tevi paaugstinājis no tiem ļaudīm un tevi par valdītāju cēlis pār Maniem Israēla ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Un atrāvis valstību no Dāvida nama un tev to devis, un tu neesi bijis kā Mans kalps Dāvids, kas Manus baušļus sargājis un pie Manis turējies ar visu savu sirdi, darīdams vien, kas pareizi Manās acīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Bet tu esi ļaunu darījis vairāk nekā visi, kas priekš tevis bijuši, un nogājis un sev citus dievus taisījis un lietas bildes taisījis, Mani kaitināt, un tu Mani esi atmetis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Tāpēc redzi, Es vedīšu ļaunumu pār Jerobeama namu un izdeldēšu no Jerobeama visu, kas mīž pie sienas, tos lielos un tos mazos iekš Israēla, un izmēzīšu Jerobeama nama pēcnākamus, itin kā sūdi top izmēzti, tiekams tas visai būs pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Kas no Jerobeama mirst pilsētā, to suņi ēdīs, un kas mirst laukā, to putni apakš debess ēdīs, jo Tas Kungs to runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Bet tu, celies, ej uz mājām, un kad tavas kājas ieies pilsēta, tad tas bērns mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Un viss Israēls viņu nožēlos un viņu apraks, jo šis vien no Jerobeama nāks kapā, tāpēc ka Tas Kungs, Israēla Dievs, iekš tā ko laba atradis Jerobeama namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Bet Tas Kungs sev iecels ķēniņu pār Israēli, kas Jerobeama namu tai dienā izdeldēs. Un ko? Tas jau ir klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Tas Kungs sitīs Israēli, itin kā niedre ūdenī top šaubīta, un izstums Israēli no šās labās zemes, ko Viņš devis viņu tēviem, un tos izkaisīs viņpus upes, tāpēc ka tie sev elkastabus taisījuši, To Kungu kaitinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Un Viņš Israēli nodos Jerobeama grēku dēļ, ar ko pats grēkojis un Israēli apgrēcinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Tad Jerobeama sieva cēlās un gāja un nonāca Tircā. Kad nu viņa pie nama sliekšņa nāca, tad tas bērns nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Un to apraka, un viss Israēls viņu apgauda pēc Tā Kunga vārda, ko Viņš bija runājis caur Savu kalpu, pravieti Ahiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Un kas vēl par Jerobeamu stāstāms, kā tas karojis un kā tas valdījis, redzi, tas rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Un tas laiks, kamēr Jerobeams ķēniņš bijis, ir divdesmit un divi gadi; un tas aizmiga saviem tēviem pakaļ; un viņa dēls Nadabs palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Un Rekabeams, Salamana dēls, bija ķēniņš pār Jūdu. Četrdesmit un vienu gadu Rekabeams bija vecs, kad palika par ķēniņu, un valdīja septiņpadsmit gadus Jeruzālemes pilsētā, ko Tas Kungs no visām Israēla ciltīm bija izredzējis, tur likt savu vārdu. Un viņa mātes vārds bija Naēma, Amoniete.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Un Jūda darīja, kas Tam Kungam nepatika, un tie viņu vairāk apkaitināja, nekā visi viņu tēvi bija darījuši ar saviem grēkiem, ar ko tie bija grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Un tie arīdzan taisīja sev kalnu altārus un elku bildes un elku stabus uz ikkatra augsta kalna un apakš visiem zaļiem kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Un maucinieki bija tai zemē un darīja pēc visām pagānu negantībām, ko Tas Kungs bija izdzinis Israēla bērnu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Un ķēniņa Rekabeama piektā gadā Zizaks, Ēģiptes ķēniņš, cēlās pret Jeruzālemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Un paņēma Tā Kunga nama mantas un ķēniņa nama mantas: viņš paņēma visu, ir visas priekšturamās zelta bruņas viņš paņēma, ko Salamans bija licis taisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Ķēniņš Rekabeams viņu vietā taisīja priekšturamās bruņas no vara, un tās deva pils karavīru virsnieku rokā, kas apsargāja ķēniņa nama durvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Kad nu ķēniņš uz Tā Kunga namu gāja, tad pils karavīri tās nesa un pēc tie tās atkal nonesa pils karavīru istabā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Kas vēl stāstāms par Rekabeamu un par visu, ko viņš darījis, redzi, tas rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Un starp Rekabeamu un Jerobeamu bija karš visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Un Rekabeams gāja dusēt pie saviem tēviem un tapa aprakts pie saviem tēviem Dāvida pilsētā. Un viņa mātes vārds bija Naēma, Amoniete, un viņa dēls Abijams palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Un ķēniņa Jerobeama, Nebata dēla, astoņpadsmitā gadā Abijams palika par ķēniņu pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Trīs gadus viņš valdīja Jeruzālemē, un viņa mātei vārds bija Maēka Absaloma mazmeita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Un viņš staigāja visos sava tēva grēkos, ko tas priekš viņa bija darījis, un viņa sirds nebija pilnīgi pie Tā Kunga, sava Dieva, kā viņa tēva Dāvida sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Bet Dāvida dēļ Tas Kungs, viņa Dievs, deva gaišumu Jeruzālemē, viņa dēlu pēc viņa ieceldams un Jeruzālemi stiprinādams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Tāpēc ka Dāvids bija darījis, kas pareizi Tā Kunga acīs, un nebija atkāpies no neviena Dieva baušļa visu savu mūžu, bez tā viena notikuma ar Ūriju, to Etieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Bet starp Rekabeama un Jerobeama namu bija karš visu viņa mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Un kas vēl stāstāms par Abijamu, un viss, ko viņš darījis, tas rakstīts Jūda ķēniņu laiku grāmatā. Un karš bija starp Abijamu un Jerobeamu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Un Abijams gāja dusēt pie saviem tēviem, un viņu apraka Dāvida pilsētā, un viņa dēls Asa palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Un Jerobeama, Israēla ķēniņa, divdesmitā gadā Asa palika par ķēniņu pār Jūdu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Un valdīja četrdesmit un vienu gadu Jeruzālemē. Un viņa vecmātei vārds bija Maēka, Absaloma mazmeita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Un Asa darīja, kas bija pareizi Tā Kunga acīs, itin kā viņa tēvs Dāvids.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Jo viņš izdzina tos mauciniekus no zemes un atmeta visus elkudievus, ko viņa tēvi bija taisījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Un savu pašu vecmāti Maēku viņš nocēla no ķēniņienes goda, tāpēc ka tā bija cēlusi negantu elka bildi (Ašerai), un Asa izpostīja arī viņas neganto elka bildi un to sadedzināja pie Kidronas upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Bet kalnu altāri nezuda; tomēr Asas sirds turējās pilnīgi pie Tā Kunga visu cauru mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Un viņš nonesa Tā Kunga namā sava tēva svētītās dāvanas un savas paša svētītās dāvanas, sudrabu un zeltu un traukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Un starp Asu un Baešu, Israēla ķēniņu, bija karš visu viņu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Un Baeša, Israēla ķēniņš, cēlās pret Jūdu un uztaisīja Rāmu, ka viņš nevienam nevēlētu ne iziet ne ieiet pie Asas, Jūda ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Un Asa ņēma visu sudrabu un zeltu, kas vēl atlika no Tā Kunga nama mantām un no ķēniņa nama mantām un to deva saviem kalpiem rokā, un ķēniņš Asa tos sūtīja pie BenHadada, Tabrimona dēla, Eziana dēla dēla, Sīrijas ķēniņa, kas Damaskū dzīvoja, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Derība ir starp mani un tevi, starp manu tēvu un tavu tēvu, redzi, es tev sūtu dāvanu, sudrabu un zeltu; ej un lauz savu derību ar Baešu, Israēla ķēniņu, ka tas no manis atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Un BenHadads klausīja ķēniņu Asu un sūtīja sava karaspēka virsniekus pret Israēla pilsētām, un kāva Ijonu un Danu un AbelBetMaēku un visu Ķinerotu visā Naftalus zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Kad nu Baeša to dzirdēja, tad viņš atstāja Rāmas taisīšanu un palika Tircā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Bet ķēniņš Asa lika izsaukt pa visu Jūdu, (neviens netapa atlaists), ka vestu projām akmeņus no Rāmas un kokus, ko Baeša tur bija uztaisījis, un ķēniņš Asa ar tiem uztaisīja Benjamina Ģebu un Micpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Un kas vēl par Asu stāstāms, un viss viņa spēks un viss, ko viņš darījis, un visas viņa pilsētas, ko viņš uztaisījis, redzi, tas rakstīts Jūda ķēniņu laiku grāmatā; bet savā vecumā viņš palika slims ar kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Un Asa gāja dusēt pie saviem tēviem un tapa aprakts pie saviem tēviem sava tēva Dāvida pilsētā. Un Jehošafats, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Un Nadabs, Jerobeama dēls, palika par ķēniņu pār Israēli Asas, Jūda ķēniņa, otrā gadā un valdīja divus gadus pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Un viņš darīja, kas Tam Kungam nepatika, un staigāja sava tēva ceļos un viņa grēkos, ar ko viņš Israēli bija apgrēcinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Un Baeša, Ahijas dēls, no Īsašara nama, derēja derību pret viņu, un Baeša to kāva pie Ģibetonas, kas Fīlistiem piederēja. Jo Nadabs un viss Israēls bija apmetušies pret Ģibetonu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Un Baeša to nokāva Asas, Jūda ķēniņa, trešā gadā un palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Un kad tas nu bija palicis par ķēniņu, tad tas apkāva visu Jerobeama namu; viņš neviena neatlicināja no Jerobeama, kam bija dvaša, tiekams viņš to bija izdeldējis pēc Tā Kunga vārda, ko Viņš bija runājis caur Savu kalpu Ahiju no Šīlo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Jerobeama grēku dēļ, ar ko viņš apgrēkojās un ar ko viņš Israēli bija apgrēcinājis, un viņa kaitināšanas dēļ, ar ko viņš To Kungu, Israēla Dievu, bija apkaitinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Un kas vēl stāstāms par Nadabu, un viss, ko viņš darījis, tas rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Un starp Asu un Baešu, Israēla ķēniņu, bija karš visu viņu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Asas, Jūda ķēniņa, trešā gadā Baeša, Ahijas dēls, palika par ķēniņu pār visu Israēli Tircā un (valdīja) divdesmit un četrus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Un viņš darīja, kas Tam Kungam nepatika, un staigāja Jerobeama ceļā un viņa grēkos, uz ko viņš Israēli bija pavedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Un Tā Kunga vārds notika uz Jeū, Hananus dēlu, pret Baešu tā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Tāpēc ka Es tevi esmu paaugstinājis no pīšļiem un tevi cēlis par valdītāju pār Saviem Israēla ļaudīm, un tu esi staigājis Jerobeama ceļā un Manus Israēla ļaudis pavedis uz grēkiem, ka tie Mani ar saviem grēkiem kaitina,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Redzi, tad Es atmetīšu Baešas pēcnākamos un viņa nama pēcnākamos, un darīšu ar tavu namu kā ar Jerobeama, Nebata dēla, namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Kas no Baešas mirst pilsētā, to suņi ēdīs, un kas no viņa mirst laukā, to ēdīs putni apakš debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Un kas vēl stāstāms par Baešu, un ko viņš ir darījis, un viņa spēks, tas rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Un Baeša gāja dusēt pie saviem tēviem un tapa aprakts Tircā, un viņa dēls Ēla palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Bet Tā Kunga vārds notika caur pravieti Jeū, Hananus dēlu, pret Baešu un viņa namu, visa ļauna dēļ, ko viņš bija darījis priekš Tā Kunga acīm, ka tas viņu bija apkaitinājis ar savu roku darbu un tāds pat bijis kā Jerobeama nams, un ka viņš šo bija apkāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Asas, Jūda ķēniņa, divdesmit sestā gadā, Ēla, Baešas dēls, palika par ķēniņu pār Israēli Tircā, (un valdīja) divus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Un viņa kalps Zimrus, virsnieks pār ratu pulku vienu pusi, sacēlās pret viņu. Kad viņš Tircā dzēra un bija piedzēries Tircas nama uzrauga Arcas namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Tad Zimrus nāca iekšā un to sita un nokāva Asas, Jūda ķēniņa, divdesmit septītā gadā, un palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Kad viņš nu bija palicis par ķēniņu un sēdēja uz sava goda krēsla, tad viņš apkāva visu Baešas namu; viņš neatlicināja neviena, kas pie sienas mīž, nedz viņa radus, nedz viņa draugus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Tā Zimrus izdeldēja visu Baešas namu pēc Tā Kunga vārda, ko viņš pret Baešu bija runājis caur pravieti Jeū,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Visu Baešas grēku dēļ un Ēlas, viņa dēla, grēku dēļ, ar ko tie bija grēkojuši un Israēli paveduši uz grēkiem, apkaitinādami To Kungu, Israēla Dievu, ar neliešu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Un kas vēl stāstāms par Ēlu un viss, ko viņš darījis, tas rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Asas, Jūda ķēniņa, divdesmit septītā gadā Zimrus palika par ķēniņu (un valdīja) septiņas dienas Tircā, un tie ļaudis bija apmetušies pret Ģibetonu, kas Fīlistiem pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Un tie ļaudis, kas tur bija apmetušies, dzirdēja sakām: Zimrus dumpi cēlis un arī ķēniņu nokāvis. Tad viss Israēls lēģerī tai dienā cēla karavirsnieku Amru par ķēniņu pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Un Omrus cēlās un viss Israēls līdz ar viņu no Ģibetonas un apmetās pret Tircri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Kad nu Zimrus redzēja, ka pilsēta bija uzņemta, tad viņš gāja ķēniņa nama pilī un sadedzināja ķēniņa namu un sevi pašu ar uguni un nomira,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Savu grēku dēļ, ar ko viņš bija apgrēkojies, ļaunu darīdams priekš Tā Kunga acīm, staigādams Jerobeama ceļā un viņa grēkos, ko tas darīja, Israēli pavezdams uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Un kas vēl stāstāms par Zimru un viņa dumpi, ko viņš cēlis, tas rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tad Israēla ļaudis dalījās divējos pulkos, viena ļaužu puse pieķērās Tibnum, Ģinata dēlam, šo celt par ķēniņu, un otra puse pieķērās Amrum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Bet tie ļaudis, kas Amrum pieķērās, bija stiprāki, nekā tie ļaudis, kas Tibnum, Ģinata dēlam, pieķērās, un Tibnus nomira un Omrus palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Asas, Jūda ķēniņa, trīsdesmit pirmā gadā Omrus palika par ķēniņu pār Israēli, un valdīja divpadsmit gadus; Tircā viņš valdīja sešus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Un viņš pirka Samarijas kalnu no Zemera par diviem talentiem sudraba, un taisīja (pilsētu) tai kalnā un nosauca tās pilsētas vārdu, ko viņš bija uztaisījis, pēc Zemera, tā kalna kunga, vārda Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Un Omrus darīja, kas Tam Kungam nepatika, un bija ļaunāks nekā visi, kas priekš viņa bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Un viņš staigāja visos Jerobeama, Nebata dēla, ceļos un viņa grēkos, ar ko tas Israēli bija apgrēcinājis, apkaitinādams To Kungu, Israēla Dievu, ar saviem neliešu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Un kas vēl stāstāms par Amru, ko viņš darījis, un viņa vara, ko viņš parādījis, tas rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Un Omrus gāja dusēt pie saviem tēviem un tapa aprakts Samarijā, un viņa dēls Ahabs palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Un Ahabs, Omrus dēls, palika par ķēniņu pār Israēli Asas, Jūda ķēniņa, trīsdesmit astotā gadā, un Ahabs, Omrus dēls, valdīja pār Israēli divdesmit un divus gadus Samarijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Un Ahabs, Omrus dēls, darīja, kas Tam Kungam nepatika, vairāk nekā visi, kas priekš viņa bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Un viņam šķita mazu lietu esam, staigāt Jerobeama, Nebata dēla, grēkos. Un viņš ņēma Izebeli, Etbaāla, Sidoniešu ķēniņa, meitu par sievu, un nogāja un kalpoja Baālam un metās priekš tā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Un viņš uzcēla Baālam altāri Baāla namā, ko viņš Samarijā bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ahabs arī taisīja Ašeru, tā ka Ahabs vairāk darīja, kaitinādams To Kungu, Israēla Dievu, nekā visi Israēla ķēniņi, kas priekš viņa bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Viņa laikā Ķiēls no Bēteles uztaisīja Jēriku; viņa pamatus tas lika par savu pirmdzimto dēlu Abiramu, un viņa vārtus tas iecēla par savu jaunāko dēlu Zegubu, pēc Tā Kunga vārda, ko Viņš runājis caur Jozua, Nuna dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Un Elija no Tizbes, no Gileādas iedzīvotājiem, sacīja uz Ahabu: tik tiešām kā Tas Kungs, Israēla Dievs, dzīvo, kā priekšā es stāvu, šinīs gados nebūs nedz rasas nedz lietus, kā vien, kad es to sacīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Un Tā Kunga vārds uz to notika tā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Ej no šejienes un griezies pret rītiem un paslēpies pie Krites upes, kas tek pret Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Un tur tu vari dzert no tās upes, un Es kraukļiem esmu pavēlējis, ka tiem tevi tur būs uzturēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Un viņš nogāja un darīja pēc Tā Kunga vārda, un nogāja un palika pie Krites upes, kas tek pret Jardāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Un kraukļi viņam atnesa maizi un gaļu rītos un maizi un gaļu vakaros, un viņš dzēra no tās upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Bet pēc kāda laika tā upe izsīka, jo lietus tai zemē nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Tad Tā Kunga vārds uz viņu notika tā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Celies un ej uz Sareptu, kas pie Sidones pieder, un paliec turpat; redzi, Es tur esmu pavēlējis vienai atraitnei, tevi uzturēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Tad viņš cēlās un gāja uz Sareptu Un kad viņš nonāca pie pilsētas vārtiem, redzi, tad tur viena atraitne lasīja malku. Un viņš tai sauca un sacīja: atnes man traukā kādu ūdens malciņu, ko dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Un tā gāja to atnest. Un viņš tai sauca un sacīja: atnes man arī kumosu maizes savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Bet tā sacīja: tik tiešām kā Tas Kungs, tavs Dievs, dzīvo, man nekā cepta nav, un tik vien ir sauja miltu tīnē un maķenīt eļļas krūzē, un redzi, es esmu salasījusi kādu pāri malkas gabaliņu, un nu es iešu un sev un savam dēlam ko pataisīšu, ka ēdam un mirstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Un Elija uz to sacīja: nebīsties, ej, pataisi to, kā tu sacījusi, bet man taisi no tiem papriekš mazu rausi un iznes man to ārā, un pēc tu arī varēsi taisīt sev un savam dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Jo tā saka Tas Kungs, Israēla Dievs: milti tīnē neies galā un krūzē eļļas netrūks līdz tai dienai, kad Tas Kungs dos lietu virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Un tā nogāja un darīja pēc Elijas vārda; tā viņa ēda un viņš un viņas nams labu laiku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Milti tīnē negāja galā un krūzē eļļas netrūka pēc Tā Kunga vārda, ko viņš caur Eliju bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Un pēc tam notikās, ka šīs sievas, tās nama mātes, dēls palika slims un viņa slimība palika ļoti grūta, kamēr viņam dvašas vairs nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Un tā sacīja uz Eliju: kas man ar tevi, tu Dieva vīrs? Tu pie manis esi atnācis, lai mani grēki top pieminēti un mans dēls mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Un viņš uz to sacīja: dod man šurp savu dēlu. Un viņš to ņēma no viņas klēpja un to uznesa augšistabā, kur viņš mita, un to lika uz savu gultu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Un viņš piesauca To Kungu un sacīja: Kungs, mans Dievs! Vai tad Tu šai atraitnei, pie kuras es piemājoju, tik ļaunu esi darījis un nonāvējis viņas bērnu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Un viņš stiepās pār to bērnu trīs reizes un piesauca To Kungu un sacīja: Kungs, mans Dievs! Lai jel šā bērna dvēsele atkal nāk iekš viņa!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Un Tas Kungs klausīja Elijas balsi, un tā bērna dvēsele atkal nāca iekš viņa, un tas atdzīvojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Un Elija ņēma to bērnu un to nonesa no augšistabas namā un to deva viņa mātei; un Elija uz to sacīja: redzi še, tavs dēls dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Tad tā sieva sacīja uz Eliju: nu es zinu, ka tu esi Dieva vīrs, un Tā Kunga vārds tavā mutē ir patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Un pēc ilga laika Tā Kunga vārds notika uz Eliju trešā gadā tā: ej, rādies Ahabam, un Es došu lietu zemes virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Un Elija nogāja, Ahabam rādīties, bet bads Samarijā bija grūts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Un Ahabs bija aicinājis nama uzraugu Obadiju, un Obadija bijās To Kungu ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Jo kad Izebele bija izdeldējusi Tā Kunga praviešus, tad Obadija ņēma simts praviešus un tos apslēpa pa piecdesmit vienā alā un tos uzturēja ar maizi un ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Un Ahabs bija sacījis uz Obadiju: ej pa to zemi pie visiem ūdens avotiem un pie visām upēm, vai mēs neatradīsim zāli, ka dzīvus uzturam zirgus un zirgēzeļus, ka tie lopi visai neiet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Un tie to zemi dalīja savā starpā, to parstaigāt; Ahabs gaja viens pa vienu ceļu, un Obadija gāja arīdzan viens pa otru ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Kad nu Obadija bija ceļā, redzi, tad Elija tam nāca pretī, un viņš to pazīdams metās uz savu vaigu un sacīja: vai tu neesi mans kungs Elija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Un viņš sacīja: es tas esmu, ej, saki savam kungam: redzi, Elija ir še.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Bet viņš sacīja: ko es esmu grēkojis, ka tu savu kalpu dod Ahabam rokā, ka es topu nokauts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Tik tiešām kā Tas Kungs, tavs Dievs, dzīvo, nav nevienas tautas, nedz valsts, kurp mans kungs nebūtu sūtījis, tevi meklēt. Un kad tie sacīja: še viņa nav, tad viņš tai valstij un tai tautai lika zvērēt, ka tie tevi nebija atraduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Un nu tu saki: ej, saki savam kungam, redzi, Elija ir še.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Un notiks, kad es no tevis aiziešu, un Tā Kunga gars tevi aizņems, kas zin kur, un ja es būtu gājis Ahabam to sacīt, un viņš tevi pēc neatrastu, tad viņš mani nokautu. Bet es tavs kalps bīstos To Kungu no savām jaunām dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Vai manam kungam nav sacīts, ko es esmu darījis, kad Izebele nokāva Tā Kunga praviešus, ka es simtu no Tā Kunga praviešiem apslēpu pa piecdesmit vienā alā un tos uzturēju ar maizi un ūdeni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Un nu tu saki: ej, saki savam kungam, redzi, Elija ir še; tad jau viņš mani nokaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Tad Elija uz to sacīja: tik tiešām kā Tas Kungs Cebaot dzīvo, ka priekšā es stāvu, es šodien viņam rādīšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Tad Obadija nogāja Ahabam pretī un viņam to sacīja. Un Ahabs gāja Elijam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Un kad Ahabs Eliju ieraudzīja, tad Ahabs uz to sacīja: vai tu tas esi, kas Israēli sajauc?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Un viņš sacīja: es Israēli neesmu sajaucis, bet tu un tava tēva nams, caur to, ka jūs esat atstājuši Tā Kunga baušļus un Baāliem pakaļ staigājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Un nu sūti, sapulcini pie manis visu Israēli Karmeļa kalnā un tos četrsimt un piecdesmit Baāla praviešus un tos četrsimt Ašeras praviešus, kas ēd pie Izebeles galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Tad Ahabs izsūtīja pie visiem Israēla bērniem un sapulcināja tos praviešus Karmeļa kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Tad Elija piegāja pie visiem ļaudīm un sacīja: cik ilgi jūs klibosiet uz abējām pusēm? Ja Tas Kungs ir Dievs, tad ejat viņam pakaļ, bet ja Baāls tas ir, tad ejat tam pakaļ. Un tie ļaudis tam neatbildēja ne vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Tad Elija sacīja uz tiem ļaudīm: es viens vienīgs esmu atlicis, Tā Kunga pravietis, bet Baāla praviešu ir četrsimt un piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Un dodiet nu mums divus vēršus, un lai tie to vienu vērsi izvēlās un sacērt gabalos un liek uz malku, bet uguni tiem nebūs pielikt; tad es sataisīšu arī to otru vērsi un to likšu uz malku un nelikšu uguni klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Tad piesauciet jūs sava dieva vārdu, bet es piesaukšu Tā Kunga vārdu: kurš Dievs nu ar uguni atbildēs, tas lai ir Dievs. Tad visi ļaudis atbildēja un sacīja: šis vārds ir labs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Un Elija sacīja uz tiem Baāla praviešiem: izvēlaties to vienu vērsi un sataisiet to papriekš, jo jūs esat daudzi un piesauciet sava dieva vārdu, bet uguni neliekat klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Tad tie ņēma to vērsi, ko viņš tiem deva un to sataisīja un piesauca Baāla vārdu no rīta līdz dienasvidum sacīdami: Baāl, paklausi mūs! Bet tur nebija ne balss, ne atbildes! Un tie lēkāja ap to altāri, kas bija taisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Un ap dienasvidu Elija tos apsmēja un sacīja: sauciet stiprā balsī, jo viņš taču ir dievs; viņš laikam ir domās vai darīšanās vai ceļā, varbūt ka viņš guļ, lai uzmostas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Un tie sauca ar stipru balsi un iegriezās pēc sava ieraduma ar nažiem un īleniem, kamēr tiem asinis tecēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Kad nu pusdiena jau bija pāri, tad tie vēl muldēja līdz ēdamā upura laikam; bet tur nebija ne balss, ne atbildes, ne uzklausīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Tad Elija sacīja uz visiem ļaudīm: nāciet šurp pie manis. Tad visi ļaudis pie tā piegāja, un viņš uztaisīja atkal Tā Kunga altāri, kas bija salauzts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Un Elija ņēma divpadsmit akmeņus pēc Jēkaba bērnu skaita, uz ko Tā Kunga vārds bija noticis, sacīdams: tavu vārdu būs saukt Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Un viņš uztaisīja no tiem akmeņiem altāri Tā Kunga Vārdā, un taisīja bedri ap to altāri, tik platu, ka tur divi mēri labības varēja saiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Un viņš salika malku un dalīja to vērsi gabalos un to nolika uz to malku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Un viņš sacīja: pildiet četrus traukus ar ūdeni un lejiet to uz to dedzināmo upuri un uz to malku. Un viņš sacīja: dariet to vēl otru reizi. Un tie to darīja otru reizi. Un viņš sacīja: dariet to trešo reizi, un tie to darīja trešo reizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Un ūdens tecēja ap altāri, un bedre tapa pilna ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Un ap ēdamā upura laiku pravietis Elija piegāja un sacīja: Kungs, Ābrahāma, Īzaka un Israēla Dievs, šodien lai top zināms, ka Tu esi Dievs iekš Israēla un es Tavs kalps, un ka visu šo esmu darījis uz Tavu vārdu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Paklausi mani, Kungs, paklausi mani, lai šie ļaudis atzīst, ka Tu Kungs esi Dievs, un ka Tu viņu sirdi atgriezi atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Tad Tā Kunga uguns krita zemē un aprija to dedzināmo upuri un to malku un tos akmeņus un to zemi un uzlaizīja arī to ūdeni bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Kad nu visi ļaudis to redzēja, tad tie metās uz savu vaigu un sacīja: Tas Kungs ir Dievs, Tas Kungs ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Un Elija uz tiem sacīja: grābiet Baāla praviešus, ka neviens no tiem neizsprūk! Tad tie tos sagrāba. Un Elija tos noveda pie Ķizones upes un tos tur nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Tad Elija sacīja uz Ahabu: celies, ēd un dzer, jo šņāc kā uz lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Un Ahabs gāja ēst un dzert, bet Elija gāja Karmeļa kalna galā un metās zemē un lika savu vaigu starp saviem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Un viņš sacīja uz savu puisi: ej jel un skaties uz jūru. Tad tas gāja un skatījās un sacīja: tur nav nekā. Tad viņš sacīja: ej atkal! Septiņām lāgām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Un septītā reizē viņš sacīja: redzi, mazs mākonīts, kā vīra plauksta, ceļas no jūras. Tad viņš sacīja: noej, saki Ahabam jūdz un brauc, ka lietus tevi neaizņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Un pēc tam debess apmācās ar melniem mākoņiem un vētru un stiprs lietus gāzās. Un Ahabs sēdās ratos un brauca uz Jezreēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Un Tā Kunga roka nāca pār Eliju, un tas apjoza savus gurnus un skrēja Ahabam pa priekšu līdz Jezreēlei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Un Ahabs teica Izebelei visu, ko Elija bija darījis, un visu, kā viņš tos praviešus ar zobenu bija nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Tad Izebele sūtīja vēstnesi pie Elijas un lika sacīt: lai dievi man šā un tā dara, ja es rīt ap šo laiku tā nedaru tavai dvēselei, kā visām viņu dvēselēm (noticis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Kad viņš to redzēja, tad viņš cēlās un aizgāja savas dzīvības pēc, un nonāca Bēršebā, kas ir iekš Jūda, un atstāja tur savu puisi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Bet pats gāja tuksnesī dienas gājumu un nāca un apsēdās apakš paegles krūma un vēlējās, ka viņa dvēsele mirtu, un sacīja: nu ir gan! Ņem nu, Kungs, manu dvēseli, jo es neesmu labāks nekā mani tēvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Un viņš apgūlās un aizmiga apakš tā paegles krūma. Un redzi, eņģelis viņu aizskāra un uz viņu sacīja: celies un ēd!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Un viņš skatījās atpakaļ, un redzi, viņa galvas galā bija karaša uz oglēm cepta un krūze ar ūdeni. Un viņš ēda un dzēra un atkal apgūlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Un Tā Kunga eņģelis nāca atkal otrā reizē un to aizskāra un sacīja: celies, ēd, jo tev ir garš ceļš priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Tā viņš cēlās un ēda un dzēra un gāja ar šās barības spēku četrdesmit dienas un četrdesmit naktis līdz Dieva kalnam Horebam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Un viņš tur iegāja vienā alā un palika tur pa nakti. Un redzi, Tā Kunga vārds uz to notika un viņš uz to sacīja: ko tu še dari, Elija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Un tas sacīja: degt esmu dedzis Tā Kunga, Tā Dieva Cebaot, labad; jo Israēla bērni Tavu derību atstājuši un Tavus altārus nolauzījuši un Tavus praviešus ar zobenu nokāvuši, un es viens esmu atlicis, un tie meklē, man paņemt dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Un viņš sacīja: izej un nostājies kalnā Tā Kunga priekšā. Un redzi, Tas Kungs gāja garām, un liela briesmīga vētra, kas kalnus saplosīja un klintis sašķēla, Tā Kunga priekšā, - bet Tas Kungs nebija tai vētrā. Un pēc tās vētras bija zemes trīcēšana, bet Tas Kungs nebija tai zemes trīcēšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Un pēc tās zemes trīcēšanas nāca uguns, bet Tas Kungs nebija tai ugunī. Un pēc tā uguns nāca klusa un lēna vēsma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Un kad Elija to dzirdēja, tad viņš apklāja savu vaigu ar savu mēteli un izgāja un stāvēja alas priekšā, un redzi, balss uz to nāca un sacīja: ko tu še dari, Elija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Un viņš sacīja: degt esmu dedzis Tā Kunga, Tā Dieva Cebaot, labad; jo Israēla bērni Tavu derību atstājuši, Tavus altārus nolauzījuši un Tavus praviešus ar zobenu nokāvuši, un es viens esmu atlicis, un tie meklē, man paņemt dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Un Tas Kungs uz to sacīja: ej un griezies atpakaļ pa savu ceļu, pa tuksnesi uz Damasku, un ieej un svaidi Azaēli par ķēniņu pār Sīriju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Un Jeū, Nimšus dēlu, svaidi par ķēniņu pār Israēli, un Elišu, Šafata dēlu no AbelMeolas, svaidi par pravieti savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Un notiks, kas no Azaēļa zobena izglābsies, to nokaus Jeūs, un kas no Jeūs zobena izglābsies, to nokaus Eliša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Un es atlicināšu iekš Israēla septiņus tūkstošus, visus, kas savus ceļus nav locījuši Baāla priekšā, un visus, kas ar savu muti viņu nav skūpstījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Tad viņš no turienes aizgāja un atrada Elišu, Šafata dēlu, un tas ara; divpadsmit jūgi vēršu bija viņa priekšā, un viņš pats bija pie tā divpadsmitā, un Elija piegāja pie viņa un uzmeta viņam savu mēteli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Tad viņš atstāja tos vēršus un skrēja Elijam pakaļ un sacīja: ļauj man jel skūpstīt savu tēvu un savu māti, tad es iešu tev pakaļ. Un viņš uz to sacīja: ej un griezies atpakaļ, jo(piemini) ko es tev esmu darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Un viņš griezās atpakaļ un ņēma vienu jūgu vēršu un tos nokāva un vārīja viņu gaļu ar viņu rīku kokiem un deva to tiem ļaudīm ēst. Pēc viņš cēlās un gāja Elijam pakaļ un tam kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Un BenHadads, Sīrijas ķēniņš, sapulcināja visu savu spēku, un trīsdesmit un divi ķēniņi bija viņam līdz un zirgi un rati, un viņš nogāja un apmetās pret Samariju, un karoja pret to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Un viņš sūtīja vēstnešus pilsētā pie Ahaba, Israēla ķēniņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Un lika tam sacīt: tā saka BenHadads: tavs sudrabs un tavs zelts būs mans, arī tavas sievas un tavi labākie bērni būs mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Un Israēla ķēniņš atbildēja un sacīja: pēc tava vārda, mans kungs un ķēniņ, es esmu tavs, un viss, kas man ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Un tie vēstneši nāca atkal atpakaļ un sacīja: tā runā BenHadads un saka: es gan pie tevis esmu sūtījis un licis sacīt: tavu sudrabu un tavu zeltu un tavas sievas un tavus bērnus tev man būs dot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Bet rītu ap šo laiku es savus kalpus pie tevis sūtīšu, izmeklēt tavu namu un tavu kalpu namu, un viss, kas tur skaists priekš tavām acīm, to tiem būs ņemt un aiznest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Tad Israēla ķēniņš saaicināja visas zemes vecajus un sacīja: ņemiet jel vērā un redziet, kā šis ļaunu meklē. Jo tas pie manis ir sūtījis pēc manām sievām un pēc maniem bērniem un pēc mana sudraba un zelta, un es tam to neesmu liedzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Bet visi vecaji un visi ļaudis uz viņu sacīja: nepaklausi un neļauj to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Tad viņš sacīja uz BenHadada vēstnešiem: sakāt ķēniņam, manam kungam: visu, par ko tu pirmo reizi pie sava kalpa sūtījis, to es darīšu, bet šo lietu es nevaru darīt. Tad tie vēstneši nogāja un viņam atsacīja to vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Un BenHadads sūtīja pie viņa un lika sacīt: lai man dievi šā vai tā dara, ja Samarijas pīšļi pietiks visu ļaužu saujām, kas man ir līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Bet Israēla ķēniņš atbildēja un sacīja: atsakiet tā: kas apjozies, tas lai nelielās kā tas, kas atjozies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Kad nu tas šo vārdu dzirdēja, ar tiem ķēniņiem teltīs dzerot, tad viņš sacīja uz saviem kalpiem taisāties. Un tie taisījās pret to pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Un redzi, viens pravietis nāca pie Ahaba, Israēla ķēniņa, un sacīja: “Tā saka Tas Kungs: vai tu esi redzējis visu šo lielo pulku? Redzi, Es to šodien došu tavā rokā, lai tu atzīsti, ka Es esmu Tas Kungs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Un Ahabs sacīja: “Caur ko?” Tad viņš sacīja: “Tā saka Tas Kungs: caur zemes valdnieku puišiem.” Un viņš sacīja: “Kas lai uzsāk kauju?” Tad viņš sacīja: “Tu pats.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Tad viņš skaitīja tos zemes valdnieku puišus, to bija divsimt trīsdesmit un divi. Un pēc tiem viņš skaitīja visus ļaudis, visus Israēla bērnus, to bija septiņi tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Un tie izgāja dienasvidū. Bet BenHadads dzēra un piedzērās teltīs ar tiem trīsdesmit un diviem ķēniņiem, kas tam bija palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Un tie zemes valdnieku puiši izgāja papriekš. Tad BenHadads izsūtīja, un tie tam teica un sacīja: vīri nāk no Samarijas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Tad viņš sacīja: vai tie nākuši uz mieru, sagrābiet tos dzīvus, vai tie nākuši uz kauju, dzīvus tos sagrābiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Kad nu šie zemes valdnieku puiši no pilsētas bija izgājuši un arī tas karaspēks, kas tiem gāja pakaļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Tad tie kāva vīrs vīru. Un Sīrieši bēga un Israēls tiem dzinās pakaļ. Bet BenHadads, Sīrijas ķēniņš, izglābās uz zirga un ar jātniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Un Israēla ķēniņš izgāja un kāva zirgus un ratus un kāva Sīriešus lielā kaušanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Tad tas pravietis nāca pie Israēla ķēniņa un uz to sacīja; ej, stiprinājies: ņem vērā un lūko, ko tu dari, jo nākošā gadā Sīrijas ķēniņš atkal nāks pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Jo Sīrijas ķēniņa kalpi uz to sacīja: viņu dievi ir kalna dievi, tāpēc tie bijuši stiprāki nekā mēs. Kaut mums ar tiem būtu jākaro klajumā! Varbūt ka mēs būtu stiprāki nekā tie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tāpēc dari tā: atcel tos ķēniņus, ikvienu no viņa vietas, un iecel viņu vietā virsniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Un taisi sev karaspēku, kāds tas bija, kas tev zudis, un zirgus, kā bija zirgi, un ratus, kā bija rati, un iesim ar tiem kauties klajumā; vai nebūsim stiprāki par tiem? Un tas klausīja viņu balsi un tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Un otrā gadā BenHadads skaitīja Sīriešus un cēlās uz Afeku, karot pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Un Israēla bērni arī tapa skaitīti un izrīkoti, un gāja tiem pretī, un Israēla bērni apmetās tiem pretī, kā divi kazu pulciņi, bet zeme bija Sīriešu pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Un tas Dieva vīrs nāca un runāja uz Israēla ķēniņu un sacīja: “Tā saka Tas Kungs: tāpēc ka Sīrieši sacījuši: Tas Kungs ir kalnu Dievs un ne arī ieleju Dievs, tad visu šo lielo pulku Es dodu tavā rokā, lai jūs atzīstat, ka Es esmu Tas Kungs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Un tie palika apmetušies viens otram pretim septiņas dienas. Un septītā dienā kaušanās sākās, un Israēla bērni nokāva no Sīriešiem simts tūkstoš kājniekus vienā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Un tie atlikušie bēga uz Afekas pilsētu, un mūris sagruva pār divdesmit un septiņtūkstošiem no šiem atlikušiem. Un BenHadads bēga un nāca pilsētā no vienas istabas otrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Tad viņa kalpi uz to sacīja: redzi, mēs esam dzirdējuši, ka Israēla nama ķēniņi ir žēlīgi ķēniņi. Apvilksim maisus ap saviem gurniem un virves ap savām galvām, un iesim ārā pie Israēla ķēniņa; vai viņš tavai dvēselei neļaus dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Un tie apvilka maisus ap saviem gurniem un virves ap savām galvām, un nāca pie Israēla ķēniņa un sacīja: tavs kalps BenHadads saka: ļauj jel manai dvēselei dzīvot. Tad tas sacīja: vai viņš vēl dzīvs? Viņš ir mans brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Un tie vīri saprata šo vārdu sev par labu un steigšus to lika sev apstiprināt no viņa un sacīja: tad BenHadads tavs brālis? Un viņš sacīja: ejat un atvediet to šurp. Tad BenHadads iznāca pie viņa, un viņš tam lika kāpt ratos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Un BenHadads uz to sacīja: tās pilsētas, ko mans tēvs tavam tēvam paņēmis, es gribu atdot, un dari sev ielas Damaskā, itin kā mans tēvs darījis Samarijā. (Un Ahabs sacīja:) ar šo derību es tevi atlaidīšu. Tā viņš ar to derēja derību un to atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Un viens vīrs no praviešu bērniem sacīja uz otru caur Tā Kunga vārdu: sit jel mani. Bet tas vīrs liedzās to sist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Un viņš uz šo sacīja: tāpēc ka tu Tā Kunga balsi neesi klausījis, redzi, tad tevi lauva sitīs, kad tu no manis aiziesi. Kad nu tas no viņa aizgāja, lauva to sastapa un saplēsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Un viņš atrada citu vīru un sacīja: sit jel mani. Un tas vīrs to sita, un to sizdams ievainoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Tad tas pravietis gāja un nostājās ķēniņam ceļā un aptina savu vaigu ar drānu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Kad nu ķēniņš gāja garām, tad viņš sauca uz ķēniņu un sacīja: tavs kalps bija izgājis kaujā, un redzi, viens vīrs nāca malā un atveda pie manis vienu vīru un sacīja: apsargi šo vīru; ja tas kaut kā nozustu, tad tava dvēsele būs viņa dvēseles vietā, vai tev būs jāmaksā viens talents sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Kad nu tavam kalpam šur tur kas bija jādara, tad viņš nozuda. Un Israēla ķēniņš sacīja: tāds tavs spriedums, kā pats spriedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Tad viņš steigšus noņēma to drānu no sava vaiga, un Israēla ķēniņš to pazina, ka tas bija viens no tiem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Un viņš uz to sacīja: “Tā saka Tas Kungs: “Tāpēc ka tu šo vīru, ko es liku izdeldēt, esi izlaidis no rokas, tad tava dvēsele būs viņa dvēseles vietā, un tavi ļaudis viņa ļaužu vietā.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Un Israēla ķēniņš nogāja saīdzis un dusmīgs savā namā un aizgāja uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Un pēc tam notikās, ka Nābatam, tam Jezreēlietim, bija vīna dārzs Jezreēlē, sānis Ahaba, Samarijas ķēniņa, pilij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Un Ahabs runāja ar Nābatu sacīdams: dod man savu vīna dārzu, man par sakņu dārzu, jo tas ir tuvu pie mana nama, un es tev viņa vietā došu labāku vīna dārzu, nekā tas ir; vai ja tev patīk, es tev to aizmaksāšu ar naudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Bet Nābats sacīja uz Ahabu: lai Tas Kungs mani pasargā, ka es tev atdotu savu tēvu mantojumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Tad Ahabs saīdzis un dusmīgs nāca mājās tā vārda dēļ, ko Nābats, tas Jezreēlietis, uz viņu bija runājis sacīdams: es tev nedošu savu tēvu mantojumu. Un viņš metās gultā, apgriezās uz otru pusi un neēda maizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Tad Izebele, viņa sieva, pie tā nāca un ar to runāja: par ko tavs prāts tāds saīdzis un tu maizes neēdi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Un viņš uz to sacīja: es runāju ar Nābatu, to Jezreēlieti, un uz to sacīju: dod man savu vīna dārzu par naudu, vai ja tu gribi, es tev došu citu vīna dārzu tai vietā. Bet tas sacīja: es tev nedošu savu vīna dārzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Tad Izebele, viņa sieva, uz to sacīja: “Tu, vai tāda tava valdīšana pār Israēli? Celies, ēd maizi, un lai tava sirds ir mierā! Es tev dabūšu Nābata, tā Jezreēlieša, vīna dārzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Un tā rakstīja grāmatas Ahaba vārdā un tās aizzieģelēja ar viņa gredzenu, un sūtīja tās grāmatas pie tiem vecajiem un pie tiem cienīgiem viņa pilsētā, kas pie Nābata dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Un tā rakstīja tais grāmatās šos vārdus: izsauciet gavēni un sēdinājiet Nābatu augstā vietā ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Un stādiet tam pretim divus netiklus vīrus, kas pret viņu dod liecību un saka: tu Dievu un ķēniņu esi zaimojis, un izvediet to un nomētājiet to akmeņiem, ka tas mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Un viņa pilsētas vīri, tie vecaji un cienīgie, kas viņa pilsētā dzīvoja, darīja, kā Izebele tiem bija sacījusi, kā tanīs grāmatās bija rakstīts, ko viņa tiem bija sūtījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Un tie izsauca gavēni un sēdināja Nābatu ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Tad divi netikli vīri nāca un stājās viņa priekšā, un tie netiklie vīri deva liecību pret Nābatu ļaužu priekšā un sacīja: “Nābats Dievu un ķēniņu zaimojis.” Un tie to izveda no pilsētas ārā un to nomētāja akmeņiem, ka tas mira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Tad tie sūtīja pie Izebeles un lika sacīt: Nābats akmeņiem nomētāts un miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Kad nu Izebele dzirdēja, ka Nābats akmeņiem bija nomētāts un miris, tad Izebele sacīja uz Ahabu: “Celies, ņem Nābata, tā Jezreēlieša, vīna dārzu, ko viņš tev liedzies dot par naudu, jo Nābats nav vairs dzīvs, bet miris.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kad nu Ahabs dzirdēja, ka Nābats bija miris, tad Ahabs cēlās, noiet uz Nābata, tā Jezreēlieša, vīna dārzu, to paņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Tad Tā Kunga vārds notika uz Eliju no Tizbes tā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '“Celies, ej Ahabam, Israēla ķēniņam, pretī, kas ir Samarijā, redzi, viņš ir Nābata vīna dārzā, turp viņš ir nogājis, to paņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Un runā uz viņu un saki: tā saka Tas Kungs: vai tu neesi nokāvis un arī paņēmis? Tad tev uz viņu tā būs runāt un sacīt: tā saka Tas Kungs: tai vietā, kur suņi laizījuši Nābata asinis, tur suņi arī laizīs tavas asinis, tiešām tavas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Tad Ahabs sacīja uz Eliju: “Vai tu, mans ienaidnieks, mani esi atradis? Un tas sacīja: “Es tevi esmu atradis, tāpēc ka tu sevi esi pārdevies, ļaunu darīt priekš Tā Kunga acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Redzi, Es vedīšu nelaimi pār tevi un atmetīšu tavus pēcnākamos un izdeldēšu no Ahaba ikvienu, kas pie sienas mīž, to mazo un to lielo iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Un Es darīšu tavu namu tāpat kā Jerobeama, Nebata dēla, namu, un kā Baešas, Ahijas dēla, namu, tās kaitināšanas dēļ, ar ko tu Mani esi kaitinājis un ka tu Israēli esi pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Un par Izebeli Tas Kungs arī runāja un sacīja: “Suņiem Izebeli būs ēst pie Jezreēles mūriem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Kas no Ahaba mirst pilsētā, to ēdīs suņi, un kas mirst laukā, to ēdīs putni apakš debess.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(Tāds kā Ahabs neviens nav bijis, kas sevi bija pārdevies, ļaunu darīt Tā Kunga acīs, jo viņa sieva viņu tā paveda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Un viņš darīja daudz negantības, staigādams pakaļ elkadieviem, tā kā bija darījuši Amorieši, ko Tas Kungs bija izdzinis Israēla bērnu priekšā.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Kad nu Ahabs šos vārdus dzirdēja, tad viņš saplēsa savas drēbes un uzvilka maisus uz savu miesu un gavēja un gulēja maisā un staigāja apkārt klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Un Tā Kunga vārds notika uz Eliju no Tizbes un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '“Vai tu neesi redzējis, kā Ahabs Manā priekšā pazemojies? Tāpēc nu, ka tas Manā priekšā pazemojies, tad Es to nelaimi nevedīšu pār to viņa dienās; viņa dēla dienās Es vedīšu to nelaimi pār viņa namu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Un trīs gadus tiem bija miers un kara nebija starp Sīriešiem un Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Bet trešā gadā Jehošafats, Jūda ķēniņš, nogāja pie Israēla ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Un Israēla ķēniņš sacīja uz saviem kalpiem: vai jūs nezināt, ka Rāmota Gileādā pieder mums, un mēs esam klusu un viņu neņemam no Sīriešu ķēniņa rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Un viņš sacīja uz Jehošafatu: vai tu ar mani gribi iet karā pret Rāmotu Gileādā? Un Jehošafats sacīja uz Israēla ķēniņu: es būšu kā tu, un mani ļaudis kā tavi ļaudis, un mani zirgi kā tavi zirgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Un Jehošafats sacīja uz Israēla ķēniņu: vaicā jel šodien Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Un Israēla ķēniņš sapulcināja tos praviešus, četrsimt vīrus, un sacīja uz tiem: vai man būs iet karā uz Rāmotu Gileādā, jeb vai man no tam būs atstāties? Un tie sacīja: celies, jo Tas Kungs viņu dos ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Bet Jehošafats sacīja: vai še nav vēl kāds no Tā Kunga praviešiem, ka mēs to varētu vaicāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Un Israēla ķēniņš sacīja uz Jehošafatu: vēl ir gan viens vīrs, caur ko To Kungu var vaicāt, bet es viņu ienīstu, jo tas man nesludina labu, bet ļaunu vien, Miha, Jemlas dēls. Un Jehošafats sacīja: lai ķēniņš tā nerunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Tad Israēla ķēniņš aicināja vienu sulaini un sacīja: atved drīz Mihu, Jemlas dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Un Israēla ķēniņš un Jehošafats, Jūda ķēniņš, sēdēja ikkatrs savā krēslā savās drēbēs ģērbušies tai pagalmā, kur ieiet pa Samarijas vārtiem, un visi pravieši sludināja viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Un Cedeķija, Kenaānas dēls, taisīja sev dzelzs ragus un sacīja: tā saka Tas Kungs: ar šiem tu badīsi Sīriešus, kamēr tos izdeldēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Un visi pravieši sludināja tā sacīdami: celies pret Rāmotu Gileādā, jums būs laba laime, jo Tas Kungs viņu dos ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Un tas vēstnesis, kas bija gājis pēc Miha, uz to runāja un sacīja: redzi jel, tie pravieši runā vienā mutē labu ķēniņam, lai jel tavs vārds tāpat ir kā viņu vārds, un runā labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Bet Miha sacīja: tik tiešām kā Tas Kungs dzīvs, ko Tas Kungs uz mani sacīs, to es runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Un kad viņš nāca ķēniņa priekšā, tad ķēniņš uz viņu sacīja: Miha, vai mums būs iet karā pret Rāmotu Gileādā, jeb vai mums no tam būs atstāties? Un tas uz viņu sacīja: celies, tev izdosies, jo Tas Kungs viņu dos ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Tad ķēniņš uz viņu sacīja: cik reiz man tev būs piekodināt, cita nekā man nesacīt kā taisnību Tā Kunga Vārdā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Un viņš sacīja: es redzēju visu Israēli izklīdinātu pa kalniem, itin kā avis, kam gana nav. Un Tas Kungs sacīja: šiem kunga nav, lai ikviens ar mieru iet savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Tad Israēla ķēniņš sacīja uz Jehošafatu: vai es tev neesmu sacījis, ka viņš par mani labu nesludina, bet ļaunu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Un (Miha) sacīja: “Tādēļ klausi Tā Kunga vārdu: es redzēju To Kungu sēžam uz Sava goda krēsla un visu debess spēku ap Viņu stāvam pa labai un pa kreisai rokai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Un Tas Kungs sacīja: “Kurš pierunās Ahabu, lai tas ceļas un krīt Rāmotā Gileādā?” Un viens runāja šā, otrs tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tad viens gars izgāja un nostājās Tā Kunga priekšā un sacīja: “Es viņu pierunāšu.” Tad Tas Kungs uz to sacīja: “Caur ko?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Un viņš sacīja: “Es iziešu un būšu melu gars visu viņa praviešu mutē.” Un Viņš sacīja: “Tu viņu pierunāsi un arī pārspēsi; ej un dari tā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Un nu redzi, Tas Kungs melu garu devis visu šo tavu praviešu mutē, un Tas Kungs par tevi ļaunu runājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tad Cedeķija, Kenaānas dēls, piegāja un deva Miham pliķi un sacīja: kā tad Tā Kunga Gars būtu no manis atstājies, ar tevi runāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Un Miha sacīja: redzi, to tu redzēsi tai dienā, kad tu no vienas istabas otrā iesi paslēpties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Un Israēla ķēniņš sacīja: ņem Mihu un ved to atpakaļ pie Amona, pilsētas virsnieka, un pie Joasa, ķēniņa dēla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Un saki: tā saka ķēniņš: liekat to cietumā un ēdinājiet to ar bēdu maizi un ar bēdu ūdeni, kamēr es atkal laimīgs pārnākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Un Miha sacīja: ja tu atkal laimīgs pārnāksi, tad Tas Kungs caur mani nav runājis. Un viņš sacīja: klausāties, visi ļaudis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Tā Israēla ķēniņš un Jehošafats, Jūda ķēniņš, cēlās pret Rāmotu Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Un Israēla ķēniņš sacīja uz Jehošafatu: es pārģērbies iešu kaujā, bet tu ģērbies savās drēbēs. Un Israēla ķēniņš pārģērbās un gāja kaujā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Un Sīriešu ķēniņš saviem ratu virsniekiem (to bija trīsdesmit un divi) bija pavēlējis un sacījis: nelaužaties ne uz mazu ne uz lielu, bet uz Israēla ķēniņu vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Kad nu tie ratu virsnieki Jehošafatu redzēja, tad tie sacīja: tiešām tas ir Israēla ķēniņš, un tie griezās un lauzās uz viņu, bet Jehošafats brēca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Kad nu tie ratu virsnieki redzēja, ka šis nebija Israēla ķēniņš, tad tie no viņa griezās nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Un viens vīrs uzvilka savu stopu no nejauši un iešāva Israēla ķēniņam starp sprādzēm un krūšu bruņām. Tad viņš sacīja uz savu ratu vadītāju: griez savu roku un izved mani no kaujas, jo es esmu ievainots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Un kaušanās palika karsta tai dienā, un ķēniņš stāvēja savos ratos Sīriešiem pretī un nomira vakarā; un asinis tecēja no vainas uz ratu grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Tad pa visu karapulku saulei noejot sauca un sacīja: ikviens uz savu pilsētu, ikviens uz savu zemi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Tā ķēniņš nomira un tapa novests uz Samariju, un ķēniņu apraka Samarijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Kad nu tos ratus mazgāja Samarijas dīķī, tad maukām mazgājoties suņi laizīja viņa asinis pēc Tā Kunga vārda, ko viņš bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Kas nu vēl par Ahabu stāstāms, un viss, ko viņš darījis, un tas ziloņkaulu nams, ko viņš taisījis, un visas pilsētas, ko viņš cēlis, tas viss rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Tā Ahabs aizmiga saviem tēviem pakaļ, un Ahazija, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Un Jehošafats, Asas dēls, palika par ķēniņu pār Jūdu Ahaba, Israēla ķēniņa, ceturtā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Un Jehošafats bija trīsdesmit un piecus gadus vecs, kad viņš palika par ķēniņu un valdīja divdesmit un piecus gadus Jeruzālemē. Un viņa mātei bija vārds Azuba, Šilkus meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Un viņš staigāja visos sava tēva Asas ceļos, viņš no tiem neatstājās un darīja, kas Tam Kungam patika. Tik tie kalnu altāri netapa nopostīti, un tie ļaudis upurēja un kvēpināja vēl pa tiem kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Un Jehošafatam bija miers ar Israēla ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Un kas vēl stāstāms par Jehošafatu un viņa spēks, ko viņš parādījis, un kā viņš karojis, tas viss ir rakstīts Jūda ķēniņu laiku grāmatā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Viņš arī izdzina no zemes tos atlikušos mauciniekus, kas Asas, viņa tēva, laikā bija atlikuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'To brīdi neviena ķēniņa nebija Edomā, bet ķēniņa vietnieks valdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Un Jehošafats lika taisīt lielus kuģus, braukt uz Ofiru pēc zelta. Bet tie nenogāja, jo EceonĢeberā tie kuģi tapa sadragāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Tad Ahazija, Ahaba dēls, sacīja uz Jehošafatu: lai mani kalpi iet ar taviem kalpiem līdzi uz laivām. Bet Jehošafats negribēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Un Jehošafats aizmiga saviem tēviem pakaļ un tapa aprakts pie saviem tēviem Dāvida pilsētā. Un viņa dēls Jehorams palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Un Ahazija, Ahaba dēls, palika par ķēniņu pār Israēli Samarijā Jehošafata, Jūda ķēniņa, septiņpadsmitā gadā, un valdīja divus gadus pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Un viņš darīja, kas Tam Kungam nepatika, un staigāja sava tēva ceļā un savas mātes ceļā un Jerobeama, Nebata dēla, ceļā, kas Israēli paveda uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Un viņš kalpoja Baālam un metās zemē priekš tā un apkaitināja To Kungu, Israēla Dievu, tā kā viņa tēvs bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Un Moabs atkāpās no Israēla, kad Ahabs bija nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Un Ahazija nokrita caur savas augšistabas treliņiem Samarijā, un sasitās un sūtīja vēstnešus un tiem sacīja: ejat un vaicājiet BaālZebubu, Ekronas dievu, vai es palikšu vesels?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Bet Tā Kunga eņģelis runāja uz Eliju no Tizbes: celies, ej pretī Samarijas ķēniņa vēstnešiem un runā uz tiem: vai tad Dieva nav iekš Israēla, ka jūs ejat, vaicāt BaālZebubu, Ekronas dievu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Tāpēc Tas Kungs tā saka: tu necelsies no tās gultas, kur tu guli, bet tev jāmirst. Un Elija aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Tā tie vēstneši nāca atpakaļ pie viņa, un viņš uz tiem sacīja: kāpēc jūs nākat atpakaļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Un tie uz viņu sacīja: viens vīrs mums nāca pretī un uz mums sacīja: ejat, griežaties atpakaļ pie ķēniņa, kas jūs sūtījis, un sakāt tam: tā saka Tas Kungs: vai tad nav Dieva iekš Israēla, ka tu sūti, vaicāt BaālZebubu, Ekronas dievu? Tāpēc tu necelsies no tās gultas, kur tu guli, bet tev jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Un viņš uz tiem sacīja: kādu izskatu tas vīrs bija, kas jums pretī nāca un šos vārdus uz jums runāja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Un tie uz viņu sacīja: tas bija vīrs spalvas drēbēs un ar ādas jostu apjozies ap saviem gurniem. Tad viņš sacīja: tas ir Elija no Tizbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Un viņš pie tā sūtīja virsnieku pār piecdesmit un tos piecdesmit, kas tam bija. Un kad tas pie viņa nonāca, redzi, tad viņš sēdēja kalna galā, un tas uz viņu sacīja: tu Dieva vīrs, ķēniņš tev liek sacīt: nāc lejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Bet Elija atbildēja un sacīja uz to virsnieku pār tiem piecdesmit: ja es esmu Dieva vīrs, tad lai uguns krīt no debesīm un aprij tevi ar taviem piecdesmit. Tad uguns krita no debesīm un aprija to un viņa piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Bet viņš pie tā sūtīja vēl otru virsnieku pār piecdesmit un tos piecdesmit, kas tam bija, un tas bildināja un uz to sacīja: tu Dieva vīrs, tā ķēniņš saka: nāc tūdaļ lejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Bet Elija atbildēja un uz tiem sacīja: ja es esmu Dieva vīrs, tad lai uguns krīt no debesīm, un aprij tevi ar taviem piecdesmit. Tad Dieva uguns nokrita no debesīm un aprija to un viņa piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Bet viņš sūtīja atkal trešo reiz virsnieku pār piecdesmit un tos piecdesmit, kas tam bija. Un tas trešais virsnieks pār piecdesmit nāca augšām un piegāja un metās ceļos priekš Elijas, to lūdza un uz to sacīja: tu Dieva vīrs, lai jel mana dvēsele un šo tavu piecdesmit kalpu dvēseles atrod žēlastību tavās acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Redzi, uguns ir kritis no debesīm un aprijis tos divus pirmos virsniekus pār piecdesmit līdz ar viņu piecdesmitiem, bet nu lai jel mana dvēsele ir dārga tavās acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Un Tā Kunga eņģelis sacīja uz Eliju: noej ar viņu un nebīsties no viņa. Tad viņš cēlās un ar to nogāja pie ķēniņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Un sacīja uz to: tā saka Tas Kungs: tāpēc ka tu vēstnešus esi sūtījis, vaicāt BaālZebubu, Ekronas dievu, kā kad nebūtu Dieva iekš Israēla, kura vārdu varētu vaicāt tāpēc tu necelsies no tās gultas, kur tu guli, bet tev jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Tā viņš nomira pēc Tā Kunga vārda, ko Elija bija runājis, un Jorams palika par ķēniņu viņa vietā, Jehorama, Jehošafata dēla, Juda ķēniņa, otrā gadā, jo viņam nebija dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Un kas vēl stāstāms par Ahaziju, ko viņš darījis, tas viss rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Kad nu Tas Kungs Eliju vētrā gribēja uzņemt debesīs, tad Elija ar Elišu gāja no Gilgalas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Un Elija sacīja uz Elišu: paliec jel šeitan, jo Tas Kungs mani sūtījis uz Bēteli. Bet Eliša sacīja: tik tiešām kā Tas Kungs dzīvs un tava dvēsele dzīva, es tevi neatstāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Un kad tie gāja uz Bēteli, tad tie praviešu bērni, kas bija Bētelē, izgāja pie Elišas un uz to sacīja: vai tu zini, ka Tas Kungs šodien tavu kungu paņems no tavas galvas? Un viņš sacīja: zinu gan, esiet tikai klusu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Un Elija uz to sacīja: Eliša, paliec jel šeitan, jo Tas Kungs mani sūtījis uz Jēriku. Bet tas sacīja: tik tiešām kā Tas Kungs dzīvs un tava dvēsele dzīva, es tevi neatstāšu. Tā tie gāja uz Jēriku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Tad tie praviešu bērni, kas bija Jērikū, piegāja pie Elišas un uz to sacīja: vai tu zini, ka Tas Kungs tavu kungu šodien paņems no tavas galvas? Un tas sacīja: zinu gan, esiet tikai klusu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Tad Elija uz to sacīja: paliec jel šeitan, jo Tas Kungs mani sūtījis pie Jardānes. Bet tas sacīja: tik tiešām kā Tas Kungs dzīvs un tava dvēsele dzīva, es tevi neatstāšu. Tā tie gāja abi divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Un piecdesmit vīri no praviešu bērniem gāja un nostājās iepretim no tālienes; un tie abi stāvēja pie Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Tad Elija ņēma savu mēteli un to satina un sita ūdenī, un tas dalījās uz abējām pusēm, ka tie abi gāja cauri sausām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Kad tie nu bija cauri izgājuši, tad Elija sacīja uz Elišu: lūdz, ko man tev būs darīt, pirms es topu atņemts no tevis. Un Eliša sacīja: lai jel tavs gars divkārtīgā mērā ir uz manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Un viņš sacīja: grūtu lietu tu esi lūdzis; ja tu mani redzēsi, kad es no tevis tapšu atņemts, tad tas tev tā notiks, bet ja ne, tad tas nenotiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Un šiem tā ejot un runājot, redzi, ugunīgi rati un ugunīgi zirgi nāca, kas tos abus šķīra. Tā Elija aizbrauca vētrā uz debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Un Eliša to redzēja un brēca: mans tēvs, mans tēvs! Israēla rati un viņa jātnieki! Un viņš to vairs neredzēja. Un viņš sagrāba savas drēbes un tās saplēsa divos gabalos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Un viņš pacēla Elijas mēteli, kas tam bija nokritis, un griezās atpakaļ un stāvēja Jardānes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Un viņš ņēma Elijas mēteli, kas tam bija nokritis, un sita to ūdeni un sacīja: kur nu Viņš, Tas Kungs, Elijas Dievs? Un viņš sita to ūdeni, un tas dalījās uz abējām pusēm, un Eliša gāja cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Kad nu tie praviešu bērni iepretim Jērikum viņu redzēja, tad tie sacīja: Elijas gars dus uz Elišas, un tie viņam gāja pretī un metās pie zemes viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Un tie uz viņu sacīja: redzi, starp taviem kalpiem ir piecdesmit spēcīgi vīri, lai tie iet un meklē tavu kungu: kad tik Tā Kunga Gars viņu nav paņēmis un nometis uz kādu kalnu vai kādā ielejā. Bet viņš sacīja: nesūtiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Bet tie vēl vairāk lūdza, kamēr palika vai kauns, un viņš sacīja: sūtiet. Un tie sūtīja piecdesmit vīrus un to meklēja trīs dienas un neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Tad tie nāca atpakaļ pie viņa uz Jēriku, kur viņš bija palicis, un viņš uz tiem sacīja: vai es jums nesacīju: neejat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Un tās pilsētas vīri sacīja uz Elišu: redzi jel, šās pilsētas vieta ir gan laba, kā mans kungs redz, bet ūdens ir nelāga un zeme neauglīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Un viņš sacīja: atnesiet man jaunu kausu un liekat sāli iekšā; un tie viņam to atnesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Un viņš izgāja pie tā ūdens avota un iemeta tur to sāli iekšā un sacīja: tā saka Tas Kungs: es šo ūdeni esmu veselīgu darījis, no tejienes vairs nenāks ne nāve nedz neauglība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Tā tas ūdens palika veselīgs līdz šai dienai pēc Elišas vārda, ko viņš bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Un viņš no turienes gāja uz Bēteli, un kad viņš pa ceļu uz augšu gāja, tad mazi puikas no pilsētas nāca ārā un to mēdīja un uz to sacīja: plikgalvi, nāc augšā, plikgalvi, nāc augšā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Un viņš apgriezās, un tos ieraudzījis viņš tos nolādēja Tā Kunga Vārdā. Tad divi lāči iznāca no meža un no tiem saplosīja četrdesmit un divus bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Un viņš no turienes gāja uz Karmeļa kalnu, un no turienes viņš griezās atpakaļ uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Un Jorams, Ahaba dēls, palika par ķēniņu pār Israēli Samarijā, Jehošafata, Jūda ķēniņa, astoņpadsmitā gadā un valdīja divpadsmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Un viņš darīja, kas Tam Kungam nepatika, bet ne tā, kā viņa tēvs un kā viņa māte, jo viņš lika noņemt to uzcelto Baāla stabu, ko viņa tēvs bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Tikai viņš pieķērās Jerobeama, Nebata dēla, grēkiem, uz ko tas Israēli bija pavedis, - no tiem viņš neatstājās. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Un Mešum, Moaba ķēniņam, bija daudz lopu, un viņš deva Israēla ķēniņam par mesliem simts tūkstoš jērus un simts tūkstoš aunus ar visu vilnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Bet kad Ahabs bija nomiris, tad Moaba ķēniņš atkrita no Israēla ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Tad ķēniņš Jorams tai laikā cēlās no Samarijas un sarīkoja visu Israēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Un nogāja un sūtīja pie Jehošafata, Jūda ķēniņa, sacīdams: Moaba ķēniņš no manis atkritis, vai tu līdz ar mani gribi karā iet pret Moabu? Un tas sacīja: es iešu līdz, es būšu kā tu, mani ļaudis kā tavi ļaudis, un mani zirgi kā tavi zirgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Un viņš sacīja: pa kuru ceļu iesim? Un tas sacīja pa Edoma tuksneša ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Tā tie gāja, Israēla ķēniņš un Jūda ķēniņš un Edoma ķēniņš. Un kad tie bija gājuši septiņu dienu gājumu, tad tiem nebija ūdens, ne karaspēkam, ne lopiem, kas tiem bija līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Tad Israēla ķēniņš sacīja: Ak vai! Tas Kungs šos trīs ķēniņus aicinājis, ka Viņš tos dotu Moaba rokā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Un Jehošafats sacīja: vai še nav kāds no Tā Kunga praviešiem, ka To Kungu caur viņu vaicātu? Tad viens no Israēla ķēniņa kalpiem tam atbildēja un sacīja: še ir Eliša, Šafata dēls, kas ūdeni lēja uz Elijas rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Un Jehošafats sacīja: Tā Kunga vārds ir pie viņa. Tad pie tā nogāja Israēla ķēniņš un Jehošafats un Edoma ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Bet Eliša sacīja uz Israēla ķēniņu: kas man ar tevi? Ej pie sava tēva praviešiem un pie savas mātes praviešiem. Bet Israēla ķēniņš uz to sacīja: nē, jo Tas Kungs šos trīs ķēniņus ir aicinājis, ka viņš tos dotu Moaba rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Un Eliša sacīja: tik tiešām kā Tas Kungs Cebaot dzīvs, priekš kā es stāvu, ja es to nedarītu Jehošafata, Jūda ķēniņa, labad, tad es tev ne virsū neskatītos nedz tevi ievērotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Nu tad, dabūjat man vienu koklētāju. Un tam koklētājam koklējot Tā Kunga roka nāca pār viņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Un viņš sacīja: tā saka Tas Kungs: rokat grāvi pie grāvja šinī ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Jo tā saka Tas Kungs: jūs neredzēsiet ne vēju ne lietu, tomēr šī ieleja būs pilna ūdens, jums dzert pašiem un jūsu sīkiem un lieliem lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Un tas ir vēl maz priekš Tā Kunga, viņš arī Moabu dos jūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Un jums būs kaut visas stiprās pilsētas un visas izredzētās pilsētas, un nocirst visus labos kokus un aizbāzt visus ūdens avotus un samaitāt visus labos tīrumus ar akmeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Un notikās no rīta ap ēdamā upura laiku, redzi, tad ūdens nāca no Edoma puses, un zeme tapa ūdens pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Kad nu visi Moabieši dzirdēja, ka tie ķēniņi nāca, pret tiem karot, tad tie sasauca visus, kas spēja bruņas nest, un vēl pārāki(vecākie) un tie stājās uz robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Un kad tie no rīta agri cēlās un saule bija uzlēkusi pār to ūdeni, tad Moabieši no tālienes to ūdeni redzēja sarkanu kā asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Un tie sacīja: tās ir asinis; tiešām tie ķēniņi pacēluši zobenu, zobenus viens pret otru un cits citu nokāvuši. Un nu, Moab, celies uz laupīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Bet kad tie nāca pie Israēla lēģera, tad Israēlieši cēlās un kāva Moabiešus un šie no viņiem bēga. Un tie tur ielauzās un apkāva Moabiešus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Un nopostīja tās pilsētas, un ikkatrs meta savu akmeni uz visiem labiem tīrumiem un tos sameta pilnus, un aizbāza visus avotus un nocirta visus labos kokus, līdz kamēr Ķirarezetē akmeņus vien atlicināja. Un lingotāji ap to apmetās un tai svieda virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kad nu Moaba ķēniņš redzēja, ka kaušanās tam metās par stipru, tad viņš pie sevis ņēma septiņsimt vīrus, kas zobenu izvilka, lauzties cauri pret Edoma ķēniņu, bet tie nespēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Tad viņš ņēma savu pirmdzimušo dēlu, kam viņa vietā bija palikt par ķēniņu, un to upurēja par dedzināmo upuri uz mūra. Un Israēli pārņēma lielas dusmas un tie no tā atstājās un griezās atpakaļ uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Un viena sieva no praviešu bērnu sievām piesauca Elišu un sacīja: mans vīrs, tavs kalps, ir nomiris, un tu zini, ka tavs kalps To Kungu bijās. Un nu nāk tas parādu dzinējs, gribēdams manus divus bērnus sev ņemt par kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Un Eliša uz to sacīja: ko man tev būs darīt? Stāsti man, kas ir tavā namā? Un viņa sacīja: tavai kalponei nav it nekā namā, kā tikai krūze eļļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Tad viņš sacīja: ej, aizņemies traukus no citiem, no visiem saviem kaimiņiem lūdz tukšus traukus labu pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Tad ej iekšā un aizslēdz durvis aiz sevis un aiz saviem dēliem un lej visos tanīs traukos un, kas pilni, tos liec pie malas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Tad tā no viņa aizgāja un aizslēdza durvis aiz sevis un aiz saviem dēliem, tie viņai atnesa tos traukus, un viņa ielēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Un kad tie trauki bija pilni, tad tā sacīja uz savu dēlu: nes man vēl vienu trauku Bet tas uz viņu sacīja: nav vairs trauka Tad tā eļļa nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Un tā gāja un to teica tam Dieva vīram. Un viņš sacīja: ej, pārdod to eļļu un maksā savu parādu, un no atlikuma uzturies pati ar saviem dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Un notikās kādu dienu, kad Eliša gāja uz Šunemi, tad tur bija viena bagāta sieva, tā viņu uzlūdza, pie viņas ēst. Un notikās, kad viņš tur cauri staigāja, tad viņš tur iegāja, ēst maizi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Un tā sacīja uz savu vīru: redzi, es atzīstu, ka tas ir svēts Dieva vīrs, kas še vienmēr cauri staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Taisīsim viņam mazu augšistabiņu ar sienām un liksim viņam tur gultu un galdu un krēslu un lukturi, ka tam pie mums nākot ir, kur ieiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Un gadījās kādu dienu, kad viņš tur nonāca, tad tas gāja tai augšistabiņā, tur gulēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Un viņš sacīja uz Gehazi, savu puisi, pasauc šo Šunemieti. Un viņš to sauca un tā ienāca pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Un viņš uz to sacīja: saki jel viņai: redzi, mūsu dēļ tev ir bijušas visas šās rūpes, ko man tev būs darīt? Vai tev kas jārunā pie ķēniņa vai pie karu lielkunga? Bet viņa sacīja: es dzīvoju starp saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Tad viņš sacīja ko tad lai es viņai daru? Un Gehazis sacīja taču gan, viņai nav dēla un viņas vīrs ir vecs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Tad viņš sacīja pasauc viņu. Un tas viņu sauca, un tā ienāca durvīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Un viņš sacīja: nākošā gadā ap šo laiku tu skūpstīsi dēlu. Bet tā sacīja: ne tā, mans kungs tu Dieva vīrs! Nemelo tu savai kalponei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Un tā sieva tapa grūta un dzemdēja dēlu otrā gadā ap to pašu laiku, kā Eliša uz viņu bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Kad nu tas bērns paauga, tad tas kādu dienu gāja ārā pie sava tēva pie pļāvējiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Un tas sacīja uz savu tēvu: vai mana galva, mana galva! Un viņš sacīja puisim: nes to pie viņa mātes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Un tas to ņēma un nesa pie viņa mātes, un tā to ņēma savā klēpī līdz pusdienai, tad tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Un tā gāja augšām un to nolika Tā Dieva vīra gultā un to ieslēdza un izgāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Un sauca savu vīru un sacīja: sūti man jel vienu no puišiem un vienu ēzeļa māti, es jāšu pie Tā Dieva vīra un atkal pārnākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Un viņš sacīja: kāpēc tu šodien iesi pie viņa? Jo nav nedz jauns mēnesis nedz svēta diena. Bet tā sacīja: paliec mierā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Un viņa apsedloja ēzeļa māti un sacīja uz savu puisi: dzen steigšus, nekavē mani jājot, kā vien, kad es tev saku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Tā viņa jāja un nāca pie Tā Dieva vīra uz Karmeļa kalnu. Un kad tas Dieva vīrs no tālienes to redzēja, tad viņš sacīja uz savu puisi Gehazi: redzi, tur ir tā Šunemiete.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Steidzies jel viņai pretī un saki uz to: vai tev labi klājās, un tavam vīram, un tavam dēlam? Un viņa sacīja: labi gan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Un tā nāca kalnā pie Tā Dieva vīra un apkampa viņa kājas. Bet Gehazis piegāja to atstumt. Bet tas Dieva vīrs sacīja: liec to mierā, jo viņas dvēsele ir noskumusi, un Tas Kungs man to apslēpis un man nav darījis zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Un viņa sacīja: vai es esmu lūgusi dēlu no sava kunga? Vai es nesacīju: nevil mani?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Tad viņš sacīja uz Gehazi: apjoz savus gurnus un ņem manu zizli savā rokā un ej. Ja tevi kas sastop, tad nesveicini to, un ja kas tevi sveicina, tad neatbildi tam, un liec manu zizli uz tā bērna vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Bet tā bērna māte sacīja: tik tiešām kā Tas Kungs dzīvs un tava dvēsele dzīva, es tevi neatstāšu. Tad viņš cēlās un tai gāja līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehazis viņu priekšā bija nogājis un licis to zizli uz tā bērna vaigu, bet tur nebija ne balss nedz samaņas. Tad viņš griezās atpakaļ tam pretī un teica un sacīja: tas bērns nav uzmodies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Kad nu Eliša ienāca namā, redzi, tad tas bērns gulēja nomiris viņa gultā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Un viņš gāja iekšā un aizslēdza durvis aiz abiem un pielūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Un viņš uzkāpa un nolikās uz to bērnu un lika savu muti un savas acis uz viņa acīm un savas rokas uz viņa rokām, un nogūlās tā pār tā bērna miesām, kamēr tās sasila.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Un viņš atkal cēlās un gāja istabā reiz šurp un reiz turp un uzkāpa atkal un nogūlās pār to. Tad tas bērns šķaudīja septiņas reizes, pēc tas atdarīja savas acis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Un viņš sauca Gehazi un sacīja: pasauc to Šunemieti. Un viņš to sauca un tā nāca; tad viņš sacīja: ņem savu bērnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Tad tā nāca un metās viņam pie kājām un nometās zemē un ņēma savu dēlu un izgāja ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Un Eliša gāja atkal uz Gilgalu; un zemē bija bads, un praviešu bērni sēdēja viņa priekšā, un viņš sacīja uz savu puisi: liec to lielo podu pie uguns un vāri ēdienu praviešu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Tad viens izgāja laukā, zāles lasīt un atrada meža gurķu stīgas un no tām salasīja pilnu klēpi meža gurķu un nāca un tos iegrieza tai ēdiena podā, jo tie tos nepazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Un tie ielēja tiem vīriem ēst, un kad tie no tā ēdiena ēda, tad tie brēca un sacīja: nāve podā, tu Dieva vīrs! Un nevarēja to ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Bet viņš sacīja: atnesiet miltus. Un viņš tos iemeta tai podā un sacīja: lej tiem ļaudīm, lai tie ēd. Tad tur vairs nekā nelaba nebija podā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Un viens vīrs nāca no BaālBalizas un atnesa tam Dieva vīram jaunu maizi, divdesmit miežu maizes un taukšētas vārpas savā kulē. Un viņš sacīja: dodi tiem ļaudīm, lai ēd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Bet viņa sulainis sacīja: ko es došu simts vīriem? Un viņš sacīja: dod tiem ļaudīm, lai ēd; jo tā saka Tas Kungs: tie ēdīs un vēl atliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Tad viņš tiem lika priekšā, ka tie ēda, un tur vēl atlika pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Un Naēmans, Sīrijas ķēniņa kara lielskungs, bija augsts vīrs priekš sava kunga un no lielas slavas; jo caur viņu Tas Kungs Sīriešiem bija devis laimi, un viņš bija varens vīrs, bet spitālīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Un no Sīrijas sirotāji bija izgājuši un aizveduši no Israēla zemes mazu meiteni, kas bija Naēmana sievas kalpone.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Un tā sacīja uz savu valdnieci: kaut mans kungs būtu pie tā pravieša, kas Samarijā, tas viņu gan atsvabinātu no spitālības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Un (Naēmans) gāja un to teica savam kungam sacīdams: tā un tā, tā meitene runājusi, kas ir no Israēla zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Tad Sīrijas ķēniņš sacīja: ej, es sūtīšu grāmatu Israēla ķēniņam. Un tas gāja un ņēma līdz desmit talentus sudraba un seštūkstoš sēķeļus zelta un desmit svētku drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Un viņš nesa to grāmatu Israēla ķēniņam, kur bija rakstīts: kad šī grāmata pie tevis nāk, redzi, tad es savu kalpu Naēmanu pie tevis esmu sūtījis, lai tu viņu atsvabini no viņa spitālības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Kad nu Israēla ķēniņš šo grāmatu bija lasījis, tad viņš saplēsa savas drēbes un sacīja: vai tad es esmu Dievs, ka varu nokaut un atkal dzīvu darīt, ka šis pie manis sūta vīru, lai to atsvabinu no viņa spitālības? Ņemiet vērā un redziet, ka tas iemeslus pie manis meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Bet kad Eliša, tas Dieva vīrs, to dzirdēja, ka Israēla ķēniņš savas drēbes bija saplēsis, tad viņš sūtīja pie ķēniņa un lika sacīt: kāpēc tu savas drēbes esi saplēsis? Lai jel viņš nāk pie manis un atzīst, pravieti esam iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Un Naēmans ar saviem zirgiem un ar saviem ratiem nāca un apstājās priekš Elišas nama durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Un Eliša sūtīja vēstnesi pie tā un lika sacīt: ej un mazgājies septiņas reizes Jardānē, tad tava miesa atkal būs vesela, un tu tapsi šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Bet Naēmans apskaitās un aizgāja un sacīja: redzi, es domāju, viņš taču nāks pie manis ārā un stāvēs un piesauks Tā Kunga, sava Dieva, vārdu un ar savu roku braucīs pār to vietu un atņems to spitālību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Vai Amana un Farfara, tās upes pie Damaskus, nav labākas nekā visi Israēla ūdeņi, vai es tur nevaru mazgāties, lai topu šķīsts? Un viņš griezās atpakaļ un aizgāja dusmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Tad viņa kalpi piegāja un ar to runāja un sacīja: mans tēvs, kad tas pravietis tev būtu teicis kādu lielu lietu, vai tu to nedarītu? Kā nu ne, kad viņš tev sacījis: mazgājies, tad tu tapsi šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Tad viņš nokāpa un mazgājās Jardānē septiņas reizes pēc Tā Dieva vīra vārda, un viņa miesa palika atkal vesela, kā maza bērna miesa, un viņš tapa šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Tad viņš griezās atpakaļ pie Tā Dieva vīra ar visu savu pulku un nāca un apstājās priekš tā un sacīja: redzi, nu es zinu, ka cita Dieva nav pa visu pasauli kā vien iekš Israēla. Un nu ņem lūdzams kādu svētību no sava kalpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Bet tas sacīja: tik tiešām kā Tas Kungs dzīvs, priekš ka es stāvu, es to neņemšu. Un viņš tam uzstājās, lai ņemot, bet tas liedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Tad Naēmans sacīja: Ja ne, tad ļauj jel dot savam kalpam divu zirgēzeļu nastas zemes. Jo tavs kalps svešiem dieviem vairs nenesīs ne dedzināmus upurus ne kaujamus upurus, kā vien Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Šinī lietā lai Tas Kungs tavam kalpam piedod, kad mans kungs ies Rimona namā tur pielūgt un viņš atspiedīsies uz manu roku, un es nometīšos Rimona namā, tad lai Tas Kungs tavam kalpam piedod šo lietu, kad es tā nometos Rimona namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Un viņš uz to sacīja: ej ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Kad nu viņš kādu ceļa gabalu no tā bija aizgājis, tad Gehazis, Elišas, Tā Dieva vīra, puisis, domāja: redzi, mans kungs šo Sīrieti Naēmanu ir saudzējis un no viņa rokas neko nav ņēmis no tā, ko viņš atnesis; tik tiešām kā Tas Kungs dzīvs, es tam skriešu pakaļ un ņemšu ko no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Tā Gehazis skrēja Naēmanam pakaļ, un kad Naēmans redzēja, sev pakaļ skrienam, tad viņš nokāpa no saviem ratiem viņam pretī un sacīja: vai viss labi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Un tas sacīja: labi. Mans kungs mani sūtījis un liek sacīt: redzi, tagad divi puiši no praviešu bērniem pie manis atnākuši no Efraīma kalniem, dod jel viņiem talentu sudraba un divas svētku drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Un Naēmans sacīja: ņem lūdzams divus talentus. Un tas tam uzstājās un iesēja divus talentus sudraba divos makos un divas svētku drēbes, un tos deva diviem no saviem puišiem, kas tos viņa priekšā nonesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Kad nu viņš nāca pie pakalnes, tad viņš to paņēma no viņu rokām un to nolika namā un tos vīrus atlaida, ka tie aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Bet viņš nāca un tur stāvēja sava kunga priekšā. Un Eliša uz to sacīja: kur tu biji, Gehazi? Un tas sacīja: tavs kalps ne šur ne tur nav bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Bet viņš uz to sacīja: vai mana sirds tur līdzi nestaigāja, kad tas vīrs griezās atpakaļ no saviem ratiem tev pretī? Vai tas bija laiks, ņemt sudrabu un drēbes un eļļas kokus un vīna dārzus un avis un vēršus un kalpus un kalpones?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Tāpēc Naēmana spitālība tev pielips un tavam dzimumam mūžam. Tad tas no viņa aizgāja spitālīgs kā sniegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Un praviešu bērni sacīja uz Elišu: redzi jel, tā vieta, kur mēs tavā priekšā dzīvojam, mums ir par šauru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Ejam jel pie Jardānes un ņemsim tur ikkatrs vienu baļķi, un taisīsim sev tur vietu, kur dzīvot. Un tas sacīja: ejat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Un viens sacīja: nāc lūdzams un ej līdz saviem kalpiem. Un viņš sacīja: es iešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Tā viņš ar tiem gāja. Un tie nonāca pie Jardānes un nocirta kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Un notikās, ka vienam baļķi cērtot cirvis iekrita ūdenī; tad tas sāka brēkt un sacīja: vai, mans kungs! Un tas bija palienēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Un tas Dieva vīrs sacīja: kur tas iekrita? Tad tas viņam rādīja to vietu, un viņš nogrieza koku un iegrūda tur, tad tā dzelzs peldēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Un viņš sacīja: ņem to. Tad tas izstiepa savu roku un to paņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Un Sīriešu ķēniņš karoja pret Israēli un aprunājās ar saviem kalpiem un sacīja: apmetīsimies tai un tai vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Bet tas Dieva vīrs sūtīja pie Israēla ķēniņa un sacīja: sargies, neej šai vietai garām, jo Sīrieši tur grib apmesties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Tad Israēla ķēniņš sūtīja uz to vietu, par ko tas Dieva vīrs tam bija sacījis un piekodinājis, un tur apsargājās ne vienu ne otru lāgu vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Tad Sīriešu ķēniņa sirds sašuta par šo lietu, un viņš aicināja savus kalpus un uz tiem sacīja: vai jūs man nevarat sacīt, kurš no mūsējiem tinās ar Israēla ķēniņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Tad viens no viņa kalpiem sacīja: tā nav, mans kungs un ķēniņ, bet Israēla pravietis, Eliša, saka Israēla ķēniņam tos vārdus; ko tu savā guļamā istabā runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Un viņš sacīja: ejat un raugāt, kur tas ir, ka es sūtu, viņu atvest. Tad viņam teica un sacīja: redzi, viņš ir Dotanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Tad viņš uz turieni sūtīja zirgus un ratus un lielu pulku, un tie nāca naktī un apmetās ap to pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Un Tā Dieva vīra sulainis cēlās agri un izgāja, un redzi, kara pulks ar zirgiem un ratiem bija apmeties ap pilsētu. Tad viņa puisis uz to sacīja: mans kungs, ko darīsim?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Un viņš sacīja: nebīsties, jo to ir vairāk, kas pie mums, nekā to, kas pie viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Un Eliša pielūdza un sacīja: Kungs, atdari jel viņam acis, ka tas redz! Tad Tas Kungs atdarīja tā puiša acis, ka tas redzēja, un redzi, kalns bija pilns ugunīgu zirgu un ratu Elišam apkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Un tie nonāca pie viņa, un Eliša lūdza To Kungu un sacīja: sit jel šos ļaudis ar aklību, un Viņš tos sita ar aklību pēc Elišas vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Tad Eliša uz tiem sacīja: šis nav tas ceļš un šī nav tā pilsēta. Nāciet man pakaļ, es jūs vedīšu pie tā vīra, ko jūs meklējat. Un viņš tos veda uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Kad tie nu nonāca Samarijā, tad Eliša sacīja: Kungs, atdari tiem acis, ka tie redz. Un Tas Kungs atdarīja tiem acis, ka tie redzēja, un redzi, tie bija pašā Samarijas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Un Israēla ķēniņš sacīja uz Elišu, kad viņš tos redzēja: vai man tos būs kaut, vai kaut, mans tēvs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Bet viņš sacīja: tev tos nebūs kaut; ko tu ar savu zobenu un ar savu stopu aizņem, tos kauj. Cel viņiem priekšā maizi un ūdeni, lai tie ēd un dzer un iet atkal pie sava kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Un viņš tiem taisīja lielu mielastu, ka tie ēda un dzēra; un viņš tos atlaida, un tie atkal gāja pie sava kunga. Pēc tam Sīriešu sirotāji vairs nenāca Israēla zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Un pēc tam notikās, ka BenHadads, Sīriešu ķēniņš, sapulcināja visu savu karaspēku un cēlās un apmeta lēģeri ap Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Un liels bads bija Samarijā, jo redzi, tie šo spieda tik ilgi, tiekams ēzeļa galva maksāja astoņdesmit sudraba gabalus, un ceturtdaļa kaba(apmēram litrs) baložu mēslu pieci sudraba gabalus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Un notikās, kad Israēla ķēniņš staigāja pa mūri, tad viena sieva uz to brēca un sacīja: palīdzi man, mans kungs un ķēniņ!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Un tas sacīja: Tas Kungs tev nepalīdz, kā tad lai es tev palīdzu? Vai no klona, vai no vīna spaida?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Un ķēniņš uz to sacīja: kas tev kait? Un tā sacīja: šī sieva uz mani sacīja, dod savu dēlu, ka to šodien ēdam, tad rītu ēdīsim manu dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Tad mēs manu dēlu esam vārījušas un ēdušas. Bet kad otru dienu es uz to sacīju: dod nu savu dēlu, ka to ēdam, tad viņa savu dēlu ir apslēpusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Un kad ķēniņš dzirdēja šās sievas vārdus, tad tas saplēsa savas drēbes, pa mūri iedams, un tie ļaudis redzēja, un redzi, tam bija maiss apakšā uz pašām miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Un viņš sacīja: lai Dievs man šā vai tā dara, ja Elišas, Šafata dēla, galva šodien uz viņa paliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Un Eliša sēdēja namā, un tie vecaji sēdēja pie tā. Un (ķēniņš) sūtīja vīru savā priekšā. Bet pirms tas vēstnesis pie tā nonāca, Eliša sacīja uz tiem vecajiem: vai esat redzējuši, ka šis slepkavas bērns sūtījis, man galvu noraut? Redziet, kad tas vēstnesis nāk, tad aizslēdziet durvis, ar tām durvīm to grūzdami ārā. Klau, aiz viņa jau viņa kunga kāju troksnis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Un kamēr viņš vēl ar tiem runāja, redzi, tad tas vēstnesis ienāca pie tā un (ķēniņš) sacīja: redzi, tas ļaunums nāk no Tā Kunga, ko tad man vēl cerēt uz To Kungu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Tad Eliša sacīja: klausāties Tā Kunga vārdu: tā saka Tas Kungs: rītu ap šo laiku pūrs kviešu miltu maksās vienu sēķeli un divi pūri miežu vienu sēķeli Samarijas vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Tad tas virsnieks, uz kura roku ķēniņš atspiedās, atbildēja tam Dieva vīram un sacīja: redzi, jebšu Tas Kungs logus taisītu debesīs, vai šī lieta varētu notikt? Bet tas sacīja: redzi, ar savām acīm tu to redzēsi, bet no tā neēdīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Un četri spitālīgi vīri bija vārtu durvīs un tie sacīja cits uz citu: ko še paliekam, kamēr mirstam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Ja arī domātu pilsētā tikt, tad pilsētā ir bads, un mēs taču tur mirsim, - un ja te paliksim, tad arī mirsim. Tad nu nāciet, iesim Sīriešu lēģeri, - ja tie mūs pamet dzīvus, tad dzīvosim, un ja tie mūs nokauj, tad mirsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Un tie cēlās paša novakarē, iet uz Sīriešu lēģeri, un kad tie nonāca pie Sīriešu lēģera malas, redzi, tad tur nebija neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Jo Tas Kungs Sīriešu spēkam bija licis dzirdēt troksni no ratiem un zirgiem un liela karaspēka troksni, tā ka cits uz citu sacīja: redzi, Israēla ķēniņš pret mums saderējis Hetiešu ķēniņus un ēģiptiešu ķēniņus, ka tie mums uzbrūk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Tā tie bija cēlušies un bēguši pa krēslu un pametuši savas teltis un savus zirgus un savus ēzeļus, lēģeri, kā tas bija, un bija bēguši, glābt tik dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Kad nu šie spitālīgie nonāca pie lēģera malas, tad tie iegāja vienā teltī, ēda un dzēra, un ņēma no turienes sudrabu un zeltu un drēbes, un nogāja un apslēpa un nāca atkal un gāja citā teltī, un ņēma no turienes arīdzan un nogāja un apslēpa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Tad cits uz citu sacīja: mēs nedarām labi; šī diena ir priecīgas vēsts diena; ja mēs cietīsim klusu un gaidīsim līdz rīta gaismai, tad kritīsim vainā. Nu tad nāciet, iesim un nesīsim ziņu ķēniņa namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Un tie gāja un sauca pilsētas vārtu sargus un tiem teica sacīdami: mēs gājām Sīriešu lēģerī, un redzi, tur nebija neviena un neviena cilvēka balss, kā vien piesieti zirgi un ēzeļi un teltis kā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Tad sasauca vārtu sargus, un tie nesa to vēsti iekšā ķēniņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Un ķēniņš cēlās naktī un sacīja uz saviem kalpiem: es jums teikšu, ko Sīrieši mums darījuši. Tie zina, ka mēs esam badā, tāpēc tie no lēģera ir izgājuši apslēpties laukā, domādami: ja tie no pilsētas nāks ārā, tad mēs tos grābsim dzīvus un ielauzīsimies pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Tad viens no viņa kalpiem atbildēja un sacīja: lai jel ņem tos pieci atlikušos zirgus, kas pilsētā atlikuši, (redzi, tie ir kā viss Israēla pulks, kas atlicies, vai kā viss Israēla pulks, kas aizgājis bojā); tos sūtīsim izlūkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Tad tie ņēma divus ratus ar zirgiem, un ķēniņš tos sūtīja Sīriešu karaspēkam pakaļ un sacīja: ejat un izlūkojiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Un tie laida tiem pakaļ līdz Jardānei, un redzi, viss ceļš bija pilns drēbju un rīku, ko Sīrieši bēgdami bija nometuši. Un tie vēstneši griezās atpakaļ un to teica ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Tad tie ļaudis izgāja un aplaupīja Sīriešu lēģeri, un pūrs kviešu miltu maksāja vienu sēķeli, un divi pūri miežu maksāja arī vienu sēķeli, pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Un ķēniņš to virsnieku, uz kura roku viņš atspiedās, bija iecēlis pār vārtiem, un tie ļaudis viņu samina vārtos, ka tas nomira, pēc tiem vārdiem, ko tas Dieva vīrs bija runājis, kad ķēniņš pie viņa nonāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Jo tas notika tā, kā tas Dieva vīrs uz ķēniņu bija runājis un sacījis: rītu ap šo laiku pūrs kviešu miltu maksās vienu sēķeli un divi pūri miežu vienu sēķeli Samarijas vārtos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Tad tas virsnieks tam Dieva vīram bija atbildējis un sacījis: redzi, jebšu Tas Kungs taisītu logus debesīs, vai šī lieta varētu notikt? Un tas bija sacījis: redzi, tu to redzēsi ar savām acīm, bet no tā neēdīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Un tā viņam notika, jo tie ļaudis viņu samina vārtos, ka tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Un Eliša runāja ar to sievu, kuras dēlu viņš bija darījis dzīvu, un sacīja: celies un ej ar savu saimi un piemīti, kur varēdama, jo Tas Kungs badu aicinājis, tas nāks tai zemē septiņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Tad tā sieva cēlās un darīja pēc Tā Dieva vīra vārda un nogāja ar savu saimi un piemita Fīlistu zemē septiņus gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Un kad tie septiņi gadi bija pagājuši, tad tā sieva nāca atpakaļ no Fīlistu zemes un izgāja, ķēniņu piesaukt par savu namu un par savu tīrumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Un ķēniņš runāja ar Gehazi, Tā Dieva vīra puisi, un sacīja: stāsti man jel visas lielās lietas, ko Eliša darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Kad nu tas patlaban ķēniņam stāstīja, ka tas nomirušu bija darījis dzīvu, redzi, tad tā sieva, kuras dēlu viņš bija dzīvu darījis, piesauca ķēniņu sava nama un sava tīruma pēc. Un Gehazis sacīja: mans kungs un ķēniņ, šī ir tā sieva, un šis ir viņas dēls, ko Eliša dzīvu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Tad ķēniņš vaicāja to sievu, un tā viņam to stāstīja, un ķēniņš tai deva līdz vienu kambarjunkuri, sacīdams, lai tai atdod visu, kas tai pieder, arī visus tīruma augļus no tās dienas, kad tā to zemi atstājusi, līdz šim laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Un Eliša gāja uz Damasku, kad BenHadads, Sīriešu ķēniņš, bija slims; un viņam teica un sacīja: tas Dieva vīrs ir atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Tad ķēniņš sacīja uz Azaēli: ņem dāvanas savā rokā un ej pretī tam Dieva vīram un vaicā caur viņu To Kungu un prasi: vai es palikšu vesels no šās slimības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Un Azaēls viņam gāja pretī un ņēma dāvanas savā rokā, visādas Damaskus mantas, nastu četrdesmit kamieļiem, un tas gāja un stājās viņa priekšā un sacīja: tavs dēls BenHadads, Sīrijas ķēniņš, mani pie tevis sūtījis sacīdams: vai es atkal palikšu vesels no šīs sērgas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Un Eliša uz to sacīja: ej un saki viņam: tu paliksi vesels! Bet Tas Kungs man ir rādījis, ka viņš mirdams mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Un tas Dieva vīrs skatījās stipri to uzlūkodams, kamēr šis sarāvās, un viņš raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Tad Azaēls sacīja: kāpēc mans kungs raud? Un tas sacīja: tāpēc, ka es zinu, ko ļauna tu darīsi Israēla bērniem; tu sadedzināsi viņu stiprās pilis ar uguni un nokausi viņu jaunekļus ar zobenu un satrieksi viņu bērnus un uzšķērdīsi viņu grūtās sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Tad Azaēls sacīja: kas ir tavs kalps, tas suns, kam tādas lielas lietas būs darīt? Un Eliša sacīja: Tas Kungs man rādījis tevi kā Sīriešu ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Un viņš aizgāja no Elišas un nāca pie sava kunga, un tas uz viņu sacīja: ko Eliša tev sacījis? Un tas atbildēja: viņš man sacīja, tu palikšot vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Un otrā dienā Azaēls ņēma apsegu un to iemērca ūdenī un pārklāja pār viņa vaigu, ka tas nomira. Un Azaēls palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Jorama, Ahaba dēla, Israēla ķēniņa, piektā gadā, kad Jehošafats par ķēniņu bija pār Jūdu, Jehorams, Jehošafata dēls, sāka valdīt iekš Jūda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Viņš bija trīsdesmit un divus gadus vecs, kad viņš palika par ķēniņu un valdīja astoņus gadus Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Un staigāja pa Israēla ķēniņu ceļiem, kā Ahaba nams darīja; jo Ahaba meita bija viņam par sievu, un viņš darīja, kas Tam Kungam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Bet Tas Kungs negribēja Jūdu samaitāt sava kalpa Dāvida dēļ, kā viņš tam bija sacījis, ka tam došot gaišumu pie viņa bērniem mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Viņa laikā Edomieši atkrita no Jūda pārvaldības un cēla sev ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Jo Jehorams bija gājis uz Caīru ar visiem saviem ratiem un naktī cēlies un kāvis tos Edomiešus, kas viņu bija apstājuši, līdz ar visiem ratu virsniekiem, bet tie ļaudis bēga savos dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Tāpēc Edomieši atkrita no Jūda virsvaldības līdz šai dienai. Tai laikā arī Libna atkrita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Un kas vēl stāstāms par Jehoramu, un viss, ko viņš darījis, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Un Jehorams aizmiga saviem tēviem pakaļ un tapa aprakts pie saviem tēviem Dāvida pilī, un Ahazija, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Jorama, Ahaba dēla, Israēla ķēniņa, divpadsmitā gadā Ahazija, Jehorama dēls, sāka valdīt pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Divdesmit un divus gadus Ahazija bija vecs, kad viņš palika par ķēniņu, un valdīja vienu gadu Jeruzālemē, un viņa mātei bija vārds Atalija, un bija Omrus, Israēla ķēniņa, meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Un viņš staigāja Ahaba nama ceļā, un darīja, kas Tam Kungam nepatika, kā Ahaba nams, jo viņš Ahaba namam bija par znotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Un viņš gāja karā ar Joramu, Ahaba dēlu, uz Rāmotu Gileādā, pret Azaēli, Sīriešu ķēniņu, un Sīrieši ievainoja Joramu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Tad ķēniņš Jorams griezās atpakaļ, likties Jezreēlē dziedināties no tām vainām, ko Sīrieši tam bija situši Rāmotā, kad tas karoja ar Azaēli, Sīriešu ķēniņu. Un Ahazija, Jehorama dēls, Jūda ķēniņš, nonāca apraudzīt Joramu, Ahaba dēlu, Jezreēlē, jo viņš bija slims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Tad pravietis Eliša sauca vienu no praviešu bērniem un uz to sacīja: apjozi savus gurnus un ņem savā rokā šo eļļas krūzi un ej uz Rāmotu Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Un turp nonācis lūko, kur Jeūs, Jehošafata dēls, Nimšus dēla dēls, un ej iekšā un liec viņam celties no saviem brāļiem un ved viņu dibina(tālākā) istabā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Un ņem to eļļas krūzi un izlej to pār viņa galvu un saki: tā saka Tas Kungs: Es tevi svaidu par ķēniņu pār Israēli. Pēc atdari durvis un bēdz un nekavējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Un šis jauneklis, tas pravieša puisis, nogāja uz Rāmotu Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Un viņam ieejot, redzi, kara virsnieki tur sēdēja, un tas sacīja: man ar tevi kas jārunā, kara virsniek. Tad Jeūs sacīja: ar kuru no mums visiem? Un viņš sacīja: ar tevi, kara virsniek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Tad viņš cēlās un gāja namā. Un tas izlēja to eļļu uz viņa galvu un uz to sacīja: tā saka Tas Kungs, Israēla Dievs: “Es tevi svaidu par ķēniņu pār Tā Kunga ļaudīm, pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Un tev būs sava kunga Ahaba namu kaut, lai Es atriebju pie Izebeles savu kalpu, to praviešu, asinis un visu Tā Kunga kalpu asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Un viss Ahaba nams ies bojā; un Es izdeldēšu no Ahaba nama visu, kas pie sienas mīž, mazu un lielu iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Jo Es darīšu Ahaba namu kā Jerobeama, Nebata dēla, namu un kā Baešus, Ahijas dēla namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Un suņi ēdīs Izebeli Jezreēles tīrumā, un neviena nebūs, kas to apraks.” Tad viņš atdarīja durvis un bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Kad nu Jeūs izgāja pie sava kunga kalpiem, tad tie uz viņu sacīja: vai miers? Kāpēc šis trakais pie tevis nācis? Un viņš uz tiem sacīja: jūs jau pazīstat to vīru un viņa valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Bet tie sacīja: tie ir meli, stāsti mums jel! Un tas sacīja: tā un tā tas uz mani runāja un sacīja: tā saka Tas Kungs: “Es tevi svaidu par ķēniņu pār Israēli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Tad tie steidzās un ņēma ikkatrs savu drēbi un to lika viņam apakšā uz pakāpēm un pūta bazūnes un sacīja: Jeūs ir ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Tā Jeūs, Jehošafata dēls, Nimšus dēla dēls, cēla dumpi pret Joramu. Bet Jorams ar visu Israēli bija apmeties ap Rāmotu Gileādā, pret Azaēli, Sīriešu ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Un ķēniņš Jorams bija pārnācis, likties dziedināties Jezreēlē no tām vainām, ko Sīrieši viņam bija situši, kad tas karoja pret Azaēli, Sīriešu ķēniņu. Un Jeūs sacīja: ja tas jūsu prāts, tad lai neviens no pilsētas neizmūk un nenoiet, to stāstīt Jezreēlē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Tad Jeūs sēdās ratos un brauca uz Jezreēli, jo Jorams tur gulēja. Un Ahazija, Jūda ķēniņš, bija nācis, Joramu apraudzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Un tas vaktnieks, kas stāvēja Jezreēles tornī, ieraudzīja Jeūs pulku nākam un sacīja: es redzu vienu pulku. Tad Jorams sacīja: ņem vienu jātnieku un sūti to viņiem pretī, un lai tas prasa: vai miers?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Un tas jātnieks tam jāja pretī un sacīja: tā saka ķēniņš: vai miers? Bet Jeūs sacīja: kas tev par mieru? Stājies man iepakaļ! Tad tas vaktnieks teica un sacīja: tas vēstnesis pie tiem nonācis, bet nenāk atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Tad viņš izsūtīja citu jātnieku, un tas pie tiem nonāca un sacīja: tā saka ķēniņš: vai miers? Bet Jeūs sacīja: kas tev par mieru? Stājies man iepakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Tad tas vaktnieks teica un sacīja: viņš pie tiem nonācis, bet negriežas atpakaļ, un skriešana ir kā Jeūs, Nimšus dēla, skriešana, jo viņš skrien kā traks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Tad Jorams sacīja: iejūdziet! Tad viņa rati tapa iejūgti, un Jorams, Israēla ķēniņš, izgāja, arī Ahazija, Jūda ķēniņš, ikkatrs savos ratos, un tie izgāja Jeūm pretī un to sastapa Nābata, tā Jezreēlieša, tīrumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Kad nu Jorams Jeū redzēja, tad viņš sacīja: vai miers, Jeū? Bet tas sacīja: kāds miers, kamēr tavas mātes Izebeles maucība un māņi augumā aug?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Tad Jorams grieza apkārt un bēga un sacīja uz Ahaziju: viltus, Ahazija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Bet Jeūs kampa stopu rokā un šāva Joramam starp viņa pleciem, ka bulta izskrēja caur viņa sirdi, un viņš nokrita savos ratos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Un (Jeūs) sacīja uz savu virsnieku Bidekaru: ņem un met viņu uz Nabata, tā Jezreēlieša, tīrumu, Jo atminies, ka es un tu mēs abi jājām pakaļ viņa tēvam Ahabam, un Tas Kungs lika šo spriedumu uz viņu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Tiešām, Es vakar esmu redzējis Nābata asinis un viņa bērnu asinis, saka Tas Kungs. Un Es tev to atmaksāšu tai pašā tīrumā, saka Tas Kungs. Un nu ņem un met viņu uz to tīrumu pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Kad Ahazija, Jūda ķēniņš, to redzēja, tad viņš bēga pa dārza nama ceļu. Bet Jeūs tam dzinās pakaļ un sacīja: kaujiet šo arīdzan ratos! - Augšām ejot uz Guru, kas ir pie Jeblaāmas; un viņš bēga uz Meģidu un tur nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Un viņa kalpi to noveda uz Jeruzālemi un to apraka viņa kapā pie viņa tēviem Dāvida pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Jorama, Ahaba dēla, vienpadsmitā gadā Ahazija bija par ķēniņu palicis pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Un kad Jeūs nonāca Jezreēlē un Izebele to dzirdēja, tad viņa svaidīja savas acis un izgreznoja savu galvu un skatījās pa logu ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Kad nu Jeūs pa vārtiem ienāca, tad tā sacīja: vai miers Zimrum, sava kunga slepkavam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Un viņš pacēla savas acis uz to logu un sacīja: kas manā pusē, kas? Tad uz to skatījās kādi divi, trīs kambarjunkuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Un viņš sacīja: gāziet to zemē, un tie to nogāza, tā ka no viņas asinīm siena un zirgi tapa aptraipīti, un viņš to samina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Kad nu viņš bija ienācis un ēdis un dzēris, tad viņš sacīja: lūkojiet pēc tās nolādētās un aprociet to, jo tā ir ķēniņa meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Bet kad tie nogāja viņu aprakt, tad tie no tās nekā neatrada, kā vien galvaskausu, kājas un roku plaukstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Tad tie nāca atpakaļ un viņam to stāstīja, un viņš sacīja: tas ir Tā Kunga vārds, ko viņš runājis caur savu kalpu Eliju no Tizbes, sacīdams: Jezreēles tīrumā suņiem būs ēst Izebeles miesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Un Izebeles maita paliks kā sūdi laukā Jezreēles tīrumā, ka nevarēs sacīt: tā ir Izebele.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Un Ahabam bija septiņdesmit dēli Samarijā, un Jeūs rakstīja grāmatas un tās sūtīja uz Samariju pie Jezreēles virsniekiem, pie tiem vecajiem un Ahaba bērnu uzraugiem ar šiem vārdiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Kad šī grāmata pie jums nonāk, un jūsu kunga dēli ir pie jums, un rati un zirgi, stipra pilsēta un bruņas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Tad izredziet to labāko un taisnāko no sava kunga dēliem, un ieceļat to viņa tēva goda krēslā, un karojiet par sava kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Bet tie bijās varen ļoti un sacīja: redzi, divi ķēniņi viņa priekšā nav pastāvējuši, kā tad mēs pastāvēsim?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Un kas par to namu un pilsētu bija iecelts, un tie vecaji un uzraugi sūtīja pie Jeūs un sacīja: mēs esam tavi kalpi un darīsim visu, ko tu mums sacīsi, mēs nevienu necelsim par ķēniņu; dari tu, kas tev patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Tad viņš tiem rakstīja citu grāmatu ar šiem vārdiem: ja jūs esat manā pusē un gribat klausīt manai balsij, tad ņemiet sava kunga dēlu galvas un nāciet pie manis rīt ap šo laiku uz Jezreēli. (Un to ķēniņa dēlu bija septiņdesmit vīri pie pilsētas lielkungiem, kas tos audzināja.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Kad nu šī grāmata pie tiem atnāca, tad tie ņēma tos ķēniņa dēlus un nokāva visus septiņdesmit un lika viņu galvas kurvjos un tās sūtīja uz Jezreēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Un kad tas vēstnesis atnāca un viņam to stāstīja sacīdams: tie ir atnesuši ķēniņa dēlu galvas, tad viņš sacīja: lieciet tās divējās kopās pie vārtu durvīm līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Un no rīta, kad viņš izgāja, tad viņš tur nostājās un sacīja uz visiem ļaudīm: jūs esat taisni, redzi, es esmu cēlis dumpi pret savu kungu un viņu nokāvis; kas tad šos visus ir kāvis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Tāpēc atzīstiet, ka no Tā Kunga vārda nekas nav kritis zemē, ko Tas Kungs runājis pret Ahaba namu; jo Tas Kungs ir darījis, ko Viņš runājis caur savu kalpu Eliju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Tad Jeūs arī visus apkāva, kas no Ahaba nama bija atlikušies Jezreēlē, arī visus viņa augstniekus un viņa pazīstamos un viņa svētītājus, kamēr tam neviena vairs neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Un viņš cēlās un gāja un nonāca Samarijā un bija ceļā vienā namā, kur gani dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Tad Jeūs atrada Ahazijas, Jūda ķēniņa, brāļus un uz tiem sacīja: kas jūs esat? Un tie sacīja: mēs esam Ahazijas brāļi un esam nākuši apmeklēt ķēniņa un ķēniņienes bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Tad viņš sacīja: grābiet tos dzīvus. Un tie tos sagrāba dzīvus un tos apkāva pie ganu nama akas, četrdesmit un divus vīrus, un neatlicināja no tiem neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Un no turienes aizgājis viņš atrada Jonadabu, Rekaba dēlu, pretī nākam, un to apsveicināja un uz to sacīja: vai tava sirds taisna, kā mana sirds ar tavu sirdi? Un Jonadabs sacīja: ir gan. (Jeūs sacīja:) Ja tā ir, tad dod man savu roku. Un viņš tam deva roku. Un viņš tam lika pie sevis kāpt ratos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Un viņš sacīja: nāc man līdz un skaties manu karstumu priekš Tā Kunga. Un viņš tam lika braukt savos ratos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Tad viņš nonāca Samarijā un apkāva visus, kas Ahabam bija atlikuši Samarijā, tiekams viņš tos izdeldēja, pēc Tā Kunga vārda, ko tas caur Eliju bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Un Jeūs sapulcināja visus ļaudis un uz tiem sacīja: Ahabs Baālam maz ir kalpojis, Jeūs viņam daudz vairāk kalpos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Tāpēc aicinājiet visus Baāla praviešus, visus viņa kalpus un visus viņa svētītājus pie manis, ka neviens neatraujās, jo man Baālam jaupurē liels upuris. Nevienam, kas atraujās, nebūs palikt dzīvam. Bet Jeūs to darīja ar viltību, ka viņš nomaitātu visus Baāla kalpus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Un Jeūs sacīja: svētījiet Baālam svētkus, un tie tos izsauca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Tad Jeūs sūtīja arī pa visu Israēli, un visi Baāla kalpi atnāca, un neviens neatrāvās, kas nebūtu nācis, un tie nāca Baāla namā, ka Baāla nams līdz galu galam bija pilns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Tad viņš sacīja uz tiem, kas bija iecelti pār to drēbju namu: atnesiet visiem Baāla kalpiem drēbes, un tie viņiem atnesa drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Tad Jeūs ar Jonadabu, Rekaba dēlu, gāja Baāla namā, un viņš sacīja uz Baāla kalpiem: meklējiet un pieraugāt, ka jūsu starpā nav neviena no Tā Kunga kalpiem, bet Baāla kalpi vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Kad tie nu nāca upurēt kaujamos un dedzināmos upurus, tad Jeūs ārā nolika astoņdesmit vīrus un sacīja: ja kāds no tiem vīriem, ko es jums dodu rokā, izbēgs, tad jūsu dvēsele būs viņa dvēseles vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Kad nu dedzināmais upuris bija pabeigts, tad Jeūs sacīja uz pils karavīriem un uz virsniekiem: ejat un kaujiet tos, ka neviens neizbēg. Un tie tos apkāva ar zobena asmeni, un tie pils karavīri un virsnieki tos nometa pie malas un gāja Baāla nama pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Un tie iznesa Baāla nama uzceltos stabus un tos sadedzināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Un sadragāja Baāla uzcelto tēlu un salauzīja Baāla namu un to darīja par gānekļu vietu līdz šodienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Tā Jeūs Baālu izdeldēja no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Bet no Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem, Jeūs neatstājās, proti no tiem zelta teļiem Bētelē un Danā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Un Tas Kungs sacīja uz Jeū: “Tāpēc ka tev labs prāts bijis darīt, kas Man patīk un Ahaba namam visu esi darījis, kas bija Manā sirdī, tad tavi dēli tev sēdēs Israēla krēslā līdz ceturtam augumam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Bet Jeūs nedzinās staigāt Tā Kunga, Israēla Dieva, bauslībā ar visu savu sirdi; viņš neatstājās no Jerobeama grēkiem, kas Israēli bija pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Tanī laikā Tas Kungs Israēli iesāka mazināt, jo Azaēls tos kāva visās Israēla robežās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'No Jardānes puses pret rītiem visu Gileādas zemi, Gadiešus un Rūbeniešus un Manasiešus, no Aroēra pie Arnonas upes un Gileādu un Basanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Un kas vēl par Jeū stāstāms, un viss, ko viņš darījis, un viss viņa spēks, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Un Jeūs aizmiga saviem tēviem pakaļ un viņu apraka Samarijā, un viņa dēls Joakas palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Un tas laiks, kamēr Jeūs pār Israēli valdījis Samarijā, ir divdesmit un astoņi gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Kad nu Atalija, Ahazijas māte, redzēja, ka viņas dēls bija miris, tad viņa cēlās un izdeldēja visu ķēniņa dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Bet Jošeba, ķēniņa Jehorama meita, Ahazijas māsa, ņēma Joasu, Ahazijas dēlu, un to nozaga no tiem ķēniņa bērniem, kas kļuva nokauti, līdz ar viņa zīdītāju guļamā kambarī, un tie viņu apslēpa no Atalijas, ka tas netapa nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Un viņš ar to bija apslēpts Tā Kunga namā sešus gadus, un Atalija valdīja pār zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Un septītā gadā Jojada sūtīja un sauca tos virsniekus pār simtiem un sargus un pils karavīrus, lai nāk pie viņa Tā Kunga namā, un derēja derību ar tiem, lika tiem zvērēt Tā Kunga namā un parādīja tiem to ķēniņa dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Un viņš tiem pavēlēja sacīdams: šī tā lieta, ko jums būs darīt. Trešā daļa no jums, kam svētdienā jāstāv kārtā, lai tur vakti pie ķēniņa nama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Un otra trešā daļa lai stāv pie Sur vārtiem un trešā daļa pie tiem vārtiem aiz pils karavīriem; tā jums būs turēt vakti un to namu nosargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Un divi pulki no jums, visi kas svētdienā tiek vaļā, lai vakti tur Tā Kunga namā pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Un jums būs stāties ap ķēniņu, ikkatram ar savu ieroci rokā. Un kas tais rindās ielauzīsies, tam būs mirt, un esiet pie ķēniņa, kad viņš iziet un ieiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Un tie virsnieki pār simtiem darīja kā priesteris Jojada tiem bija pavēlējis, un ikkatrs ņēma savus vīrus, kam svētdienā bija kārta un kas svētdienā tika vaļā, un gāja pie priestera Jojadas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Un priesteris tiem virsniekiem pār simtiem deva šķēpus un priekšturamās bruņas, kas ķēniņam Dāvidam bija Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Un tie pils karavīri stāvēja ikkatrs ar savu ieroci rokā no nama labās puses līdz nama kreisai pusei, pie altāra un pie nama ap ķēniņu visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Un viņš izveda ķēniņa dēlu un uzlika viņam kroni un deva viņam liecības (grāmatu), un tie viņu cēla par ķēniņu un to svaidīja un plaukšķināja ar rokām un sacīja: lai dzīvo ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Un kad Atalija dzirdēja to pils karavīru (un) ļaužu kliegšanu, tad tā nāca pie tiem ļaudīm Tā Kunga namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Un tā skatījās, un redzi, ķēniņš stāvēja augstajā vietā, kā bija ieradums, un virsnieki un trumešu pūtēji pie ķēniņa, un visi zemes ļaudis priecājās un pūta trumetes. Tad Atalija saplēsa savas drēbes un sauca: dumpis, dumpis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Bet priesteris Jojada pavēlēja tiem virsniekiem pār simtiem, tiem kara spēka vadoņiem, un uz tiem sacīja: izvediet to no nama ārā rindām cauri un kas viņai ies pakaļ, to nokaujiet ar zobenu; jo priesteris sacīja: Tā Kunga namā to nebūs nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Un tie pielika rokas pie tās, un tā gāja pa zirgu braucamo ceļu uz ķēniņa namu un tur tapa nokauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Un Jojada derēja derību starp To Kungu un ķēniņu un ļaudīm, ka tie būtu Tā Kunga ļaudis, ir starp ķēniņu un ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Tad visi zemes ļaudis gāja Baāla namā un to nolauzīja ar viņa altāriem un sadauzīja viņa tēlus pavisam un nokāva Matanu, Baāla svētītāju, altāru priekšā, un priesteris iecēla atkal priekšniekus pie Tā Kunga nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Un viņš ņēma tos virsniekus pār simtiem un tos sargus un pils karavīrus un visus zemes ļaudis, un tie veda ķēniņu no Tā Kunga nama un gāja to ceļu pa pils karavīru vārtiem uz ķēniņa namu, un viņš apsēdās ķēniņu goda krēslā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Un visi zemes ļaudis priecājās, un pilsēta norima, kad tie Ataliju ar zobenu bija nokāvuši pie ķēniņa nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Un Joas bija septiņus gadus vecs, kad tas palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Jeūs septītā gadā Joas palika par ķēniņu un valdīja četrdesmit gadus Jeruzālemē. Un viņa mātei bija vārds Cibea no Bēršebas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Un Joas darīja, kas Tam Kungam labi patika, visu savu mūžu, kamēr priesteris Jojada viņu mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Tikai kalnu altāri netapa nopostīti; jo tie ļaudis upurēja un kvēpināja vēl uz tiem kalnu altāriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Un Joas sacīja uz tiem priesteriem: visu naudu, kas top dota Dievam par godu un nāk Tā Kunga namā, naudu, kas iet uz galvām, visu naudu, ko spriež par dvēseli, un visu naudu, ko dod no labprātības Tā Kunga namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'To priesteriem būs ņemt, ikkatram no sava pazīstama, un tiem būs izlabot tā nama plīsumus visur, kur tie plīsumus atrod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Un notikās ķēniņa Joasa divdesmit un trešā gadā, ka tie priesteri nebija labojuši tā nama plīsumus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Tad ķēniņš Joas aicināja priesteri Jojadu un tos citus priesterus un uz tiem sacīja: kāpēc jūs nelabojiet tā nama plīsumus. Un nu jums vairs nebūs ņemt naudu no saviem pazīstamiem, bet to dot priekš tā nama plīsumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Tad tie priesteri bija mierā, naudas no ļaudīm vairs neņemt, nedz nama plīsumus izlabot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Un priesteris Jojada ņēma šķirstu un ieurba tā vākā caurumu, un to lika sānis altārim pa labo roku; kad kāds nāca Tā Kunga namā, tad tie priesteri, kas slieksni sargāja, tur ielika to naudu, ko ienesa Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Kad nu redzēja daudz naudas šķirstā esam, tad ķēniņa skrīveris un augstais priesteris nāca un sasēja un skaitīja to naudu, ko atrada Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Un tie to naudu ieskaitīja rokā darba uzraugiem, kas bija iecelti pār Tā Kunga namu. Un tie to izdeva amatniekiem un nama būvētājiem, kas pie Tā Kunga nama strādāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Un mūrniekiem un akmeņu cirtējiem, pirkt kokus un cirstus akmeņus, izlabot Tā Kunga nama plīsumus un izdot par visu, kas bija vajadzīgs, izlabot Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Bet sudraba kausus, nažus, bļodas, trumetes un visādas zelta un sudraba lietas priekš Tā Kunga nama netaisīja no tās naudas, ko sanesa Tā Kunga namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Bet tie to deva strādniekiem, izlabot ar to Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Un atbildēšanu neprasīja no tiem vīriem, kam tā nauda bija dota, to dot strādniekiem, bet tie to darīja uz ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Nauda no noziegumu upuriem un nauda no grēku upuriem netapa nesta Tā Kunga namā, tā nācās priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'To brīdi Azaēls, Sīriešu ķēniņš, cēlās un karoja pret Gatu un to uzņēma. Un Azaēls griezās iet pret Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Tad Joas, Jūda ķēniņš, ņēma visas svētās dāvanas, ko viņa tēvi Jehošafats un Jehorams un Ahazija, Jūda ķēniņi, Dievam bija dāvinājuši, ir tās dāvanas, ko viņš pats bija devis, un visu zeltu, kas atradās Tā Kunga namā un pie ķēniņa nama mantām, un to sūtīja Azaēlim, Sīriešu ķēniņam. Tad šis aizgāja no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Un kas vēl par Joasu stāstāms, un viss, ko viņš darījis, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Un viņa kalpi cēlās un derēja derību un nokāva Joasu Millus namā, kur iet uz Sillu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jo Jozakars, Šimeata dēls, un Jozabats, Šomera dēls, viņa kalpi, to nokāva, ka tas nomira; un viņu apraka pie viņa tēviem Dāvida pilī. Un viņa dēls Amacīja palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Joasa, Ahazijas dēla, Jūda ķēniņa, divdesmit trešā gadā Joakas, Jeūs dēls, palika par ķēniņu pār Israēli un valdīja Samarijā septiņpadsmit gadus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Un viņš darīja, kas Tam Kungam nepatika, jo viņš staigāja pakaļ Jerobeama, Nebata dēla, grēkiem, kas Israēli paveda uz grēkiem; no tiem viņš neatstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Tad Tā Kunga bardzība iedegās pār Israēli, un Viņš tos nodeva rokā Azaēlim, Sīriešu ķēniņam, un BenHadadam, Azaēļa dēlam visu to laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Bet Joakas pielūdza Tā Kunga vaigu, un Tas Kungs to paklausīja; jo Viņš uzlūkoja to spaidīšanu, ar ko Sīriešu ķēniņš Israēli spaidīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Un Tas Kungs Israēlim deva glābēju, ka tie izglābās no Sīriešu rokas, un Israēla bērni dzīvoja savās teltīs kā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Taču tie neatstājās no Jerobeama nama grēkiem, kas Israēli bija pavedis uz grēkiem, bet staigāja iekš tiem; pat Astarte palika Samarijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Jo no Joakasa ļaudīm vairāk nebija atlikuši nekā piecdesmit jātnieki un desmit rati un desmit tūkstoš kājnieki. Jo Sīrijas ķēniņš tos bija nokāvis un tos darījis kā saminamus pīšļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Un kas vēl par Joakasu stāstāms, un viss, ko viņš darījis, un viss viņa spēks, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Un Joakas aizmiga saviem tēviem pakaļ un tapa aprakts Samarijā. Un viņa dēls Jehoas palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Joasa, Jūda ķēniņa, trīsdesmit septītā gadā Jehoas, Joakasa dēls, palika par ķēniņu pār Israēli Samarijā, un valdīja sešpadsmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Un viņš darīja, kas Tam Kungam nepatika; viņš neatstājās no visiem Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem, - tanīs viņš staigāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Un kas vēl par Jehoasu stāstāms, un viss, ko viņš darījis, un viss viņa spēks, kā viņš karojis pret Amacīju, Jūda ķēniņu, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Un Jehoas aizmiga saviem tēviem pakaļ, un Jerobeams sēdās viņa goda krēslā. Bet Jehoas Samarijā tapa aprakts pie Israēla ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Un Eliša sasirga ar slimību, ar ko tas arī nomira. Un Jehoas, Israēla ķēniņš, nogāja pie tā un raudāja viņa priekšā un sacīja: mans tēvs! Mans tēvs! Israēla rati un viņa jātnieki!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Un Eliša uz to sacīja: dabū stopu un bultas. Un viņš tam dabūja stopu un bultas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Tad viņš sacīja uz Israēla ķēniņu: uzvelc to stopu ar savu roku! Un tas uzvilka ar savu roku, un Eliša lika savu roku uz ķēniņa roku');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Un sacīja: atveri logu pret rītiem. Un viņš to atvēra. Un Eliša sacīja: šauj! Un viņš šāva. Tad viņš sacīja: tā ir Tā Kunga glābēja bulta, glābēja bulta pret Sīriešiem, jo tu kausi Sīriešus Afekā, tiekams tu tos izdeldēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Pēc viņš sacīja: ņem tās bultas. Un kad tas tās ņēma, tad viņš sacīja uz Israēla ķēniņu: sit to zemi! Un viņš sita trīs reizes un apstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Tad tas Dieva vīrs par to apskaitās un sacīja: ja tu būtu piecas vai sešas reizes sitis, tad tu Sīriešus būtu kāvis līdz izdeldēšanai, bet nu tu Sīriešus kausi trīs reiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Un Eliša nomira un to apraka, kad Moabiešu sirotāji gada sākumā ielauzās zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Un notikās, kad tie nupat vienu vīru gribēja aprakt, redzi, tad tie ieraudzīja to pulku un iemeta to vīru Elišas kapā. Un kad tas vīrs dabūja aiztikt Elišas kaulus, tad tas palika dzīvs un cēlās uz savām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Un Azaēls, Sīriešu ķēniņš, spaidīja Israēli visu Joakasa mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Bet Tas Kungs tiem bija žēlīgs un apžēlojās par tiem un atgriezās pie tiem Savas derības dēļ ar Ābrahāmu, Īzaku un Jēkabu un negribēja tos nomaitāt un tos arīdzan neatmeta no Sava vaiga līdz šim laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Un Azaēls, Sīriešu ķēniņš, nomira, un BenHadads, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Tad Jehoas, Joakasa dēls, atņēma atkal tās pilsētas no BenHadada, Azaēļa dēla rokas, ko šis karā bija ņēmis no Joakasa, viņa tēva, rokas. Jehoas viņu kāva trīs reizes un atdabūja Israēla pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Jehoasa, Joakasa dēla, Israēla ķēniņa, otrā gadā Amacīja, Joasa, Jūda ķēniņa, dēls palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Divdesmit pieci gadus viņš bija vecs, kad palika par ķēniņu, un valdīja divdesmit deviņus gadus Jeruzālemē, un viņa mātei bija vārds Joadane no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Un viņš darīja, kas Tam Kungam labi patika, tomēr ne tā kā viņa tēvs Dāvids, bet kā viņa tēvs Joas, tā viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Tikai kalnu altāri netapa nopostīti; tie ļaudis upurēja un kvēpināja vēl uz kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Un kad viņš bija stiprinājies savā valstībā, tad tas nokāva savus kalpus, kas viņa tēvu, to ķēniņu, bija nokāvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Bet to slepkavu bērnus viņš nenokāva, kā rakstīts ir Mozus bauslības grāmatā, kur Tas Kungs pavēlējis sacīdams: tēviem nebūs tapt nokautiem par bērniem, un bērniem nebūs tapt nokautiem par tēviem, bet ikkatram būs tapt nokautam par saviem paša grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Viņš kāva Edomiešus sāls ielejā desmit tūkstošus un uzņēma Selu kaujā, un nosauca viņas vārdu Jokteēli līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Tad Amacīja sūtīja vēstnešus pie Jehoasa, Joakasa dēla, Jeūs dēla dēla, Israēla ķēniņa, un lika sacīt: nāc, skatīsimies acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Bet Jehoas, Israēla ķēniņš, sūtīja pie Amacījas, Jūda ķēniņa, un lika sacīt: Lībanus ērkšķu krūms sūtīja pie Lībanus ciedru koka, sacīdams: dod savu meitu manam dēlam par sievu. Bet Lībanus lauka zvēri gāja pāri un samina to ērkšķu krūmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Tu gan Edomu esi kāvis, - tāpēc tava sirds lepojās. Paturi to godu un paliec mājās, kāpēc tu gribi dzīties pēc nelaimes, ka tu krīti un Jūda līdz ar tevi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Bet Amacīja neklausīja. Tad Jehoas, Israēla ķēniņš, nāca un Amacīja, Jūda ķēniņš, saskatījās acīs pie BetŠemesas Jūda zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Un Jūda tapa sakauts no Israēla un tie bēga ikkatrs savā dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Un Jehoas, Israēla ķēniņš, sagūstīja Amacīju, Joasa dēlu, Ahazijas dēla dēlu, Jūda ķēniņu pie BetŠemesas, un nonāca Jeruzālemē un nolauzīja Jeruzālemes mūrus četrsimt olektis no Efraīma vārtiem līdz Stūra vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Un viņš ņēma visu zeltu un sudrabu un visus rīkus, kas atradās Tā Kunga namā un tā ķēniņa nama mantās, un bērnus ķīlām, un griezās atpakaļ uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Un kas vēl par Jehoasu stāstāms, ko viņš darījis, un viņa spēks, un kā viņš karojis ar Amacīju, Jūda ķēniņu, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Un Jehoas aizmiga saviem tēviem pakaļ un tapa aprakts Samarijā pie Israēla ķēniņiem, un Jerobeams, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Bet Amacīja, Joasa, Jūda ķēniņa, dēls, dzīvoja piecpadsmit gadus, kad Jehoas, Joakasa, Israēla ķēniņa, dēls, bija nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Un kas vēl par Amacīju stāstāms, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Un dumpis cēlās pret viņu Jeruzālemē. Bet viņš bēga uz Laķisu, un viņam sūtīja pakaļ uz Laķisu un viņu tur nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Un viņu atveda uz zirgiem un apraka Jeruzālemē pie viņa tēviem Dāvida pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Un visi Jūda ļaudis ņēma Azariju, kas bija sešpadsmit gadus vecs, un to cēla par ķēniņu viņa tēva Amacījas vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Tas uztaisīja Elatu un atdabūja to atkal pie Jūda pēc tam, kad ķēniņš bija aizmidzis pakaļ saviem tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Amacījas, Joasa dēla, Jūda ķēniņa, piecpadsmitā gadā Jerobeams, Jehoasa dēls, palika par ķēniņu pār Israēli Samarijā un valdīja četrdesmit un vienu gadu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Un viņš darīja, kas Tam Kungam nepatika; viņš neatstājās no visiem Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Viņš atdabūja Israēla robežu no tās vietas, kur iet uz Hamatu, līdz klajuma jūrai, pēc Tā Kunga, Israēla Dieva, vārda, ko Viņš bija runājis caur Savu kalpu, pravieti Jonu, Amitajus dēlu, kas bija no GatEveras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Jo Tas Kungs uzlūkoja, ka Israēla bēdas bija ļoti rūgtas, un arī neviena vairs nebija ne maza ne liela, un ka Israēlim palīga nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Un Tas Kungs nebija runājis, ka Israēla vārdu gribot izdeldēt apakš debesīm, bet Viņš tos atpestīja caur Jerobeama, Jehoasa dēla, roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Un kas vēl par Jerobeamu stāstāms un viss, ko viņš darījis, un viņa spēks, kā viņš karojis un kā viņš Damasku un Hamatu atkal atdabūjis no Jūda pie Israēla, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Un Jerobeams aizmiga pakaļ saviem tēviem Israēla ķēniņiem. Un viņa dēls Zaharija palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Jerobeama, Israēla ķēniņa, divdesmit septītā gadā Azarija, Amacījas, Jūda ķēniņa, dēls, palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Viņš bija sešpadsmit gadus vecs, kad viņš palika par ķēniņu, un valdīja piecdesmit un divus gadus Jeruzālemē. Un viņa mātei bija vārds Jekalija no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Un viņš darīja, kas Tam Kungam labi patika, kā viņa tēvs Amacīja bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Tikai kalnu altāri vien netapa nopostīti, bet ļaudis upurēja un kvēpināja vēl pa kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Un Tas Kungs sita ķēniņu, ka tas palika spitālīgs līdz savas miršanas dienai, un viņš dzīvoja slimnieku namā. Bet Jotams, ķēniņa dēls, bija pār to namu un tiesāja tās zemes ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Kas vēl par Azariju stāstāms, un viss, ko viņš darījis, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Un Azarija aizmiga saviem tēviem pakaļ, un to apraka pie viņa tēviem Dāvida pilī, un Jotams, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Azarijas, Jūda ķēniņa, trīsdesmit astotā gadā Zaharija, Jerobeama dēls, palika par ķēniņu pār Israēli Samarijā, un valdīja sešus mēnešus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Un darīja, kas Tam Kungam nepatika, kā viņa tēvi bija darījuši; viņš neatstājās no Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Un Šalums, Jabesa dēls, cēla dumpi pret viņu un to kāva ļaužu priekšā un to nokāva un palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Un kas vēl par Zahariju stāstāms, redzi, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Šis bija Tā Kunga vārds, ko viņš bija runājis uz Jeū sacīdams: līdz ceturtam augumam tavi bērni sēdēs uz Israēla goda krēsla; un tā tas noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Šalums, Jabesa dēls, palika par ķēniņu Uzijas, Jūda ķēniņa, trīsdesmit devītā gadā un valdīja vienu mēnesi Samarijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Jo Menaēms, Gadus dēls, cēlās no Tircas un nāca uz Samariju, un kāva Šalumu, Jabesa dēlu, Samarijā un to nokāva un palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Un kas vēl par Šalumu stāstāms, un tas dumpis, ko viņš cēlis, redzi, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tad Menaēms kāva Tivzu un visu, kas tur bija, un viņas robežas no Tircas nākdams, tāpēc ka tie viņam nebija (vārtus) atdarījuši, un viņš to kāva un pāršķēla visas grūtās sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Azarijas, Jūda ķēniņa, trīsdesmit devītā gadā Menaēms, Gadus dēls, palika par ķēniņu pār Israēli un valdīja desmit gadus Samarijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Un viņš darīja, kas Tam Kungam nepatika, un kamēr dzīvoja, viņš neatstājās no Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Tad Pūls, Asīrijas ķēniņš, nāca pret to zemi, un Menaēms deva Pūlam tūkstoš talentus sudraba, lai viņa roka ar to būtu, ka varētu stiprināties savā valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Un Menaēms to naudu izspieda no Israēla, un ikkatram bagātam bija jādod Asīrijas ķēniņam par ikkatru vīru piecdesmit sudraba sēķeli. Tad Asīrijas ķēniņš griezās atpakaļ un nepalika vairs tai zemē');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Un kas vēl stāstāms par Menaēmu, un viss, ko viņš darījis, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Un Menaēms aizmiga saviem tēviem pakaļ, un Pekaja, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Azarijas, Jūda ķēniņa, piecdesmitā gadā Pekaja, Menaēma dēls, palika par ķēniņu pār Israēli Samarijā, un valdīja divus gadus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Un darīja, kas Tam Kungam nepatika; viņš neatstājās no Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Un Peka, Remalijas dēls, viņa virsnieks, cēla dumpi pret viņu un to kāva Samarijā, ķēniņa nama pagalmā, ar Argobu un ar Arju; un pie viņa bija piecdesmit vīri no Gileādas bērniem, un viņš to nokāva, un palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Un kas vēl stāstāms par Pekaju, un viss, ko viņš darījis, redzi, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Azarijas, Jūda ķēniņa, piecdesmit otrā gadā Peka, Remalijas dēls, palika par ķēniņu pār Israēli Samarijā un valdīja divdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Un viņš darīja, kas Tam Kungam nepatika; viņš neatstājās no Jerobeama, Nebata dēla, grēkiem, kas Israēli bija pavedis uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Pekas, Israēla ķēniņa, laikā Tiglat Pilezers, Asīrijas ķēniņš, atnāca un uzņēma Jonu un AbelBetMaāku un Janoū un Ķedesu un Hacoru un Gileādu un Galileju un visu Naftalus zemi, un tos noveda uz Asīriju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Un Hoseja, Elas dēls, cēla dumpi pret Peku, Remalijas dēlu, un to sita un nokāva un palika par ķēniņu viņa vietā Jotama, Uzijas dēla, divdesmitā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Un kas vēl par Peku stāstāms, un viss, ko viņš darījis, redzi, tas ir rakstīts Israēla ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Pekas, Remalijas dēla, Israēla ķēniņa, otrā gadā Jotams, Uzijas dēls, palika par ķēniņu pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Divdesmit pieci gadus viņš bija vecs, kad palika par ķēniņu, un valdīja sešpadsmit gadus Jeruzālemē, un viņa mātei bija vārds Jeruza, Cadaka meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Un viņš darīja, kas Tam Kungam labi patika, kā viņa tēvs Uzija bija darījis, tā viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Tikai kalnu altāri vien netapa nopostīti, ļaudis upurēja un kvēpināja vēl pa kalniem. Šis uztaisīja tos augšvārtus pie Tā Kunga nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Un kas vēl par Jotamu stāstāms, un viss, ko viņš darījis, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Tanī laikā Tas Kungs sāka uz Jūdu sūtīt Recinu, Sīriešu ķēniņu un Peku, Remalijas dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Un Jotams aizmiga saviem tēviem pakaļ, un tapa aprakts pie saviem tēviem Dāvida, sava tēva, pilī. Un Ahazs, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Pekas, Remalijas dēla, septiņpadsmitā gadā Ahazs, Jotama, Jūda ķēniņa, dēls, palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Ahazs bija divdesmit gadus vecs, kad palika par ķēniņu, un valdīja sešpadsmit gadus Jeruzālemē, un nedarīja, kas Tam Kungam, viņa Dievam, patika, kā viņa tēvs Dāvids.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Jo viņš staigāja pa Israēla ķēniņu ceļiem. Viņš arī savam dēlam lika caur uguni iet pēc pagānu negantības, ko Tas Kungs Israēla bērnu priekšā bija izdzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Viņš upurēja un kvēpināja arī pa kalniem un pakalniem un apakš visiem zaļiem kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tad Recins, Sīriešu ķēniņš, ar Peku, Remalijas dēlu, Israēla ķēniņu, cēlās karā pret Jeruzālemi, un apmeta lēģeri ap Ahazu, bet to nevarēja pārvarēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Tanī laikā Recins, Sīriešu ķēniņš, atdabūja Elatu uz Sīriešu pusi, un izdzina Jūdus no Elatas, un Sīrieši nāca uz Elatu un tur dzīvoja līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Bet Ahazs sūtīja vēstnešus pie Tiglat Pilezera, Asiriešu ķēniņa, un lika sacīt: es esmu tavs kalps un tavs dēls, nāc šurp un atpestī mani no Sīriešu ķēniņa rokas un no Israēla ķēniņa rokas, kas pret mani cēlušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Un Ahazs ņēma to sudrabu un zeltu, kas atradās Tā Kunga namā un ķēniņa nama mantās, un sūtīja dāvanas Asiriešu ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Un Asiriešu ķēniņš tam paklausīja, un Asiriešu ķēniņš cēlās pret Damasku un to uzņēma un aizveda tos (iedzīvotājus) uz Kiru un nokāva Recinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Tad ķēniņš Ahazs nāca Tiglat Pilezeram, Asiriešu ķēniņam, pretī uz Damasku un tur redzēja to altāri, kas bija Damaskū, un ķēniņš Ahazs sūtīja priesterim Ūrijam tā altāra līdzību un tēlu, visu tā, kā tas bija taisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Un priesteris Ūrija uztaisīja tādu altāri; itin tādu, kādu ķēniņš Ahazs no Damaskus bija sūtījis, tādu priesteris Ūrija taisīja, kamēr ķēniņš Ahazs no Damaskus pārnāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Kad nu ķēniņš Ahazs no Damaskus pārnāca, tad ķēniņš redzēja to altāri, un ķēniņš gāja pie tā altāra un uz tā upurēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Un iededzināja savu dedzināmo upuri un savu ēdamo upuri un izlēja savu dzeramo upuri un slacīja sava pateicības upura asinis uz to altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Bet to vara altāri, kas bija Tā Kunga priekšā, to viņš nocēla no tās vietas nama priekšā, starp (savu) altāri un Tā Kunga namu, un to cēla sānis(savam) altārim pret ziemeļa pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Un ķēniņš Ahazs pavēlēja priesterim Ūrijam sacīdams: uz tā lielā altāra tev būs iededzināt rīta dedzināmo upuri un vakara ēdamo upuri, ir ķēniņa dedzināmo upuri un viņa ēdamo upuri, ir visu zemes ļaužu dedzināmo upuri un viņu ēdamo upuri un viņu dzeramo upuri, un tev uz to būs slacināt visas asinis no dedzināmiem upuriem un no kaujamiem upuriem, bet par to vara altāri es apdomāšu, ko es darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Un priesteris Ūrija darīja, kā ķēniņš Ahazs bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Un ķēniņš Ahazs nolauzīja tos sānu galdus no tiem krēsliem un noņēma no viņu virsas tos katlus un nocēla to jūru no tiem vara vēršiem, kas apakš tās bija, un to lika uz akmeņu grīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Viņš arī pārgrozīja pie Tā Kunga nama tās svētās dienas lieveni, ko tie pie tā nama bija taisījuši, un ķēniņa vārtus no āra puses, Asīrijas ķēniņa labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Un kas vēl par Ahazu stāstāms, ko viņš darījis, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Un Ahazs aizmiga saviem tēviem pakaļ, un tapa aprakts pie saviem tēviem Dāvida pili, un Hizkija, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Ahaza, Jūda ķēniņa, divpadsmitā gadā Hoseja, Elas dēls, palika par ķēniņu pār Israēli Samarijā un valdīja deviņus gadus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Un darīja, kas Tam Kungam nepatika, taču ne tā, kā tie Israēla ķēniņi, kas bijuši priekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Pret to cēlās Salmanasers, Asīrijas ķēniņš, un Hoseja tam palika par kalpu, un tam deva dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Bet Asīrijas ķēniņš manīja, ka Hoseja bija derējis derību un sūtījis vēstnešus pie Ēģiptes ķēniņa Zoūs, un vairs nenonesa dāvanas Asīrijas ķēniņam kā gadu no gada, un Asīrijas ķēniņš to saņēma ciet un saistītu iemeta cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Jo Asīrijas ķēniņš apņēma visu zemi un nāca uz Samariju un apmeta lēģeri pret to trīs gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Un Hosejas devītā gadā Asīrijas ķēniņš uzņēma Samariju un aizveda Israēli uz Asīriju un tiem lika dzīvot Helahā un pie Haboras, Gozanas upes, un Medijas pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Un notikās, kad Israēla bērni apgrēkojās pret To Kungu, savu Dievu, kas tos no Ēģiptes bija izvedis, no Ēģiptes ķēniņa Faraona rokas, un kalpoja citiem dieviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Un staigāja pēc pagānu likumiem, ko Tas Kungs Israēla bērnu priekšā bija izdzinis, un pēc Israēla ķēniņu (likumiem), ko tie bija cēluši, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Un Israēla bērni slepenībā domāja un darīja, kas nebija labi, pret To Kungu, savu Dievu, un taisīja sev kalnu altārus visās savās pilsētās, gan pilīs, gan stiprās pilsētās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Un uztaisīja sev elku bildes un Astartes uz visiem augstiem pakalniem un apakš visiem zaļiem kokiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Un kvēpināja tur uz visiem kalniem, tāpat kā pagāni, ko Tas Kungs viņu priekšā bija aizvedis, un darīja ļaunas lietas, To Kungu kaitinādami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Un kalpoja elku dieviem, par ko Tas Kungs uz tiem bija sacījis: “Jums to nebūs darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Un kad Tas Kungs pret Israēli un pret Jūdu liecību deva caur visiem praviešiem un visiem redzētājiem un lika sacīt: “Atgriežaties no saviem nikniem ceļiem un turat Manus baušļus un Manus likumus, pēc visas bauslības, ko Es jūsu tēviem pavēlējis, un ko Es pie jums esmu sūtījis caur Saviem kalpiem, tiem praviešiem!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Tad tie neklausīja, bet apcietinājās stūrgalvīgi pēc savu tēvu stūrgalvības, kas nebija ticējuši uz To Kungu, savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Un tie nicināja Viņa baušļus un Viņa derību, ko Tas ar viņu tēviem bija darījis, un Viņa liecības, ko Tas viņu starpā bija apliecinājis, un dzinās uz nelietību un kļuva nelieši un (gāja) pakaļ apkārtējiem pagāniem, par ko Tas Kungs tiem bija pavēlējis, lai tā nedara kā viņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Un tie atstājās no visiem Tā Kunga, sava Dieva, baušļiem un taisīja sev izlietas bildes, divus teļus, un taisīja arī Astartes un metās zemē priekš visa debess spēka un kalpoja Baālam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Un tie lika saviem dēliem un savām meitām iet caur uguni un devās uz zīlēšanu un vārdošanu, un pārdevās ļaunu darīt priekš Tā Kunga acīm, Viņu apkaitinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Tad Tas Kungs ļoti apskaitās par Israēli un tos atmeta nost no Sava vaiga, ka nekā neatlika, kā vien Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Un arī Jūda neturēja Tā Kunga, sava Dieva, baušļus, bet tie staigāja Israēla likumos, ko tie bija cēluši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Tad Tas Kungs atmeta visu Israēla dzimumu un tos iegāza bēdās un tos deva laupītājiem rokā, kamēr tos pavisam atmeta no Sava vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Un Viņš norāva Israēli no Dāvida nama, un tie cēla Jerobeamu, Nebata dēlu, par ķēniņu, un Jerobeams novērsa Israēli no Tā Kunga un paveda tos uz lieliem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Un Israēla bērni staigāja visos Jerobeama grēkos, ko tas bija darījis; tie no tiem neatstājās, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Tiekams Tas Kungs Israēli atmeta no Sava vaiga, kā Tas bija runājis caur visiem Saviem kalpiem, tiem praviešiem. Un Israēls no savas zemes tapa aizvests uz Asīriju līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Un Asīrijas ķēniņš atveda (ļaudis) no Bābeles un no Kutas un no Avas un no Hamatas un no Sefarvaimas un tiem lika dzīvot Samarijas pilsētās Israēla bērnu vietā, un tie iemantoja Samariju un dzīvoja tās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Kad tie nu tur sāka dzīvot un To Kungu nebijās, tad Tas Kungs sūtīja lauvas viņu starpā, kas citus no tiem saplēsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Tādēļ tie runāja uz Asīrijas ķēniņu un sacīja: tās tautas, ko tu esi aizvedis un kam tu licis dzīvot Samarijas pilsētās, nezina tās zemes Dieva tiesu, tādēļ Viņš starp tiem ir lauvas sūtījis, un redzi, tie tos saplēš, tāpēc ka tie nezina tās zemes Dieva tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Tad Asīrijas ķēniņš pavēlēja sacīdams: novediet uz turieni vienu no tiem priesteriem, ko jūs no turienes esat aizveduši; lai tie iet un tur dzīvo un lai viņš māca tās zemes Dieva tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Un viens no tiem priesteriem, kas no Samarijas bija aizvesti, nāca un dzīvoja Bētelē un tos mācīja, kā To Kungu bīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Bet ikkatra tauta pati sev taisīja dievus un tos uzcēla elku kalnu namos, ko Samarijas ļaudis bija cēluši, - ikkatra tauta savās pilsētās, kur tie dzīvoja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Un Bābeles ļaudis taisīja SukotBenotu, un Kutas ļaudis taisīja Nerģelu, un Hamatas ļaudis taisīja Azimu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Un Avieši taisīja Nibeasu un Tartaku, un Sefarvaimieši sadedzināja ar uguni savus dēlus Adramelekam un Anamelekam, Sefarvaimiešu dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Un tie bijās arī To Kungu un cēla sev kalnu priesterus no ļaužu vidus, un tie viņiem upurēja tais kalnu namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Tie bijās To Kungu un kalpoja arī saviem dieviem, pēc ikkatras tautas ieraduma, no kurienes tie bija atvesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Un līdz šai dienai tie dara pēc tā pirmā ieraduma; tie nebīstas To Kungu, nedz dara pēc saviem likumiem un pēc savām tiesām, nedz pēc tās bauslības, nedz pēc tā likuma, ko Tas Kungs Jēkaba bērniem pavēlējis, kam Viņš deva Israēla vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Tas Kungs ar tiem bija derējis derību un tiem pavēlējis sacīdams: “Jums nebūs bīties citus dievus, nedz priekš tiem mesties zemē, nedz tiem kalpot, nedz tiem upurēt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Bet Tam Kungam, kas jūs izvedis no Ēģiptes zemes ar lielu spēku un izstieptu elkoni: To jums būs bīties un priekš Tā jums būs mesties zemē un Tam jums būs upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Un jums būs turēt tos likumus un tās tiesas un to bauslību un to pavēli, ko Viņš jums rakstījis, to darīt visu mūžu, bet citus dievus jums nebūs bīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Un to derību, ko Es ar jums esmu derējis, jums nebūs aizmirst un nebūs bīties citus dievus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Bet jums To Kungu, savu Dievu, būs bīties, tad Tas jūs izglābs no visu jūsu ienaidnieku rokas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Bet tie neklausīja, bet darīja pēc sava pirmā ieraduma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Tā šās tautas bijās To Kungu un kalpoja arī saviem elka dieviem, arī viņu bērni un bērnu bērni dara tā pat, kā viņu tēvi darījuši, līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Un Hosejas, Elas dēla, Israēla ķēniņa, trešā gadā Hizkija, Ahaza, Jūda ķēniņa, dēls, palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Un viņš bija divdesmit pieci gadus vecs, kad palika par ķēniņu, un valdīja divdesmit deviņus gadus Jeruzālemē, un viņa mātei bija vārds Abi, Zaharijas meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Un tas darīja, kas Tam Kungam labi patika, tāpat kā viņa tēvs Dāvids bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Tas nopostīja tos kalnu altārus un nolauzīja tos stabus un izdeldēja Astartes un sadragāja to vara čūsku, ko Mozus bija taisījis; jo līdz tam laikam Israēla bērni tai bija kvēpinājuši un to nosauca Neūstan (vara taisīta).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Viņš uzticējās Tam Kungam, Israēla Dievam, un pēc viņa nebija otrs tāds kā viņš no visiem Jūda ķēniņiem, arī priekš viņa tāds nebija bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Jo viņš pieķērās Tam Kungam un viņš no Tā neatkāpās un viņš turēja tos baušļus, ko Tas Kungs caur Mozu bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Un Tas Kungs bija ar viņu, ka viss, kur viņš izgāja, labi izdevās. Viņš atkāpās arīdzan no Asīrijas ķēniņa un tam vairs nekalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Viņš kāva arīdzan Fīlistus līdz Gazai un viņas robežām, gan pilīs, gan stiprās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Un ķēniņa Hizkijas ceturtā gadā, tas ir Hosejas, Elas dēla, Israēla ķēniņa, septītais gads, Salmanasers, Asīrijas ķēniņš, cēlās pret Samariju un apmeta lēģeri pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Un to uzņēma pēc trim gadiem, Hizkijas sestā gada, tas ir Hosejas, Israēla ķēniņa, devītais gads, - tad Samarija tapa uzņemta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Un Asīrijas ķēniņš aizveda Israēli uz Asīriju un tiem lika dzīvot Halahā un pie Haboras, Gozanas upes, un Medijas pilsētās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Tāpēc ka tie Tā Kunga, sava Dieva, balsij nebija klausījuši, bet viņa derību pārkāpuši, un visu, ko Mozus, Tā Kunga kalps, bija pavēlējis, un to nebija nedz klausījuši nedz darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Bet ķēniņa Hizkijas četrpadsmitā gadā Sanheribs, Asīrijas ķēniņš, cēlās pret visām stiprām Jūda pilsētām un tās uzņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Tad Hizkija, Jūda ķēniņš, sūtīja pie Asīrijas ķēniņa uz Laķisu un lika sacīt: es esmu apgrēkojies, griezies atpakaļ no manis, es nesīšu, ko tu man uzliksi. Tad Asīrijas ķēniņš Hizkijam, Jūda ķēniņam, uzlika trīssimt talentus sudraba un trīsdesmit talentus zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Un Hizkija deva visu sudrabu, kas atradās Tā Kunga namā un tā ķēniņa nama mantās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Tanī laikā Hizkija noplēsa (to zeltu) no Tā Kunga nama durvīm un no tiem stabiem, ko Hizkija, Jūda ķēniņš, bija apkalis ar zeltu, un to deva Asīrijas ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Bet Asīrijas ķēniņš sūtīja Tartanu (augsto sargu), Rabsarisu (augsto valdoni) un Rabzaku (augsto dzērienu devēju) no Laķisas pie ķēniņa Hizkijas ar lielu karaspēku uz Jeruzālemi, un tie cēlās un gāja uz Jeruzālemi. Un kad tie bija cēlušies un nonākuši, tad tie nostājās pie augšēja dīķa ūdens grāvja, ceļa malā pie vadmalnieku tīruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Un tie sauca ķēniņu. Tad pie tiem izgāja nama uzraugs Elijaķims, Hilķijas dēls, un skrīveris Šebna un kanclers Joaks, Asafa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Un Rabzakus uz tiem sacīja: sakāt jel Hizkijam: tā saka tas lielais ķēniņš, Asīrijas ķēniņš: kas tas tāds patvērums, uz ko tu paļaujies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu saki tukšu vārdu, diezgan esot padoma un spēka uz karu. Uz ko tad tu paļaujies, ka tu no manis esi atkritis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Nu redzi, tu paļaujies uz to salūzušo niedri, uz Ēģipti. Kas uz to atspiežas, tam tā ies rokā un to pārdurs. Tāds ir Faraons, Ēģiptes ķēniņš, visiem, kas uz viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Bet ja jūs uz mani sakāt: mēs paļaujamies uz To Kungu, savu Dievu: vai tas nav, kam kalnus un altārus Hizkija ir nopostījis un sacījis uz Jūdu un Jeruzālemi: priekš šī altāra, kas ir Jeruzālemē, jums būs pielūgt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nu tad, noderi ar manu kungu, Asīrijas ķēniņu, un es tev došu divtūkstoš zirgus, ja tev ir jātnieki, ko tiem likt virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kā tad tu varēsi atsist atpakaļ vienu pašu virsnieku no mana kunga vismazākiem kalpiem? Bet tu paļaujies uz Ēģipti, ratu un jātnieku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Vai tad nu es bez Tā Kunga esmu cēlies pret šo vietu, to izpostīt? Tas Kungs uz mani sacījis: celies pret šo zemi un izposti to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Tad Elijaķims, Hilķijas dēls, un Šebna un Joaks sacīja uz Rabzaku: runā jel ar saviem kalpiem sīriski, - mēs to gan protam - un nerunā ar mums jūdiski priekš šo ļaužu ausīm, kas ir uz mūra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Bet Rabzakus uz tiem sacīja: vai mans Kungs mani sūtījis pie tava kunga un pie tevis, šos vārdus runāt? Vai ne pie tiem vīriem, kas sēž uz mūra, kam līdz ar jums būs jāēd savi sūdi un jādzer savi mīzali.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Un Rabzakus nostājās un sauca ar stipru balsi jūdiski un runāja un sacīja: klausāties tā lielā ķēniņa, Asīrijas ķēniņa, vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Tā saka ķēniņš: lai Hizkija jūs neapmāna, jo viņš jūs nevarēs izglābt no manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Lai arī Hizkija jums nedara cerību uz To Kungu sacīdams: tiešām, Tas Kungs mūs izglābs un šī pilsēta netaps dota Asīrijas ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Neklausāties uz Hizkiju. Jo tā saka Asīrijas ķēniņš: deriet ar mani mieru un nāciet pie manis ārā, tad ikviens ēdīs no sava vīna koka un ikviens no sava vīģes koka un ikviens dzers ūdeni no savas akas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Kamēr es nākšu un jūs aizvedīšu tādā zemē, kāda ir jūsu zeme, labības un vīna zeme, maizes un vīna dārzu zeme, eļļas koku, eļļas un medus zeme, - tad jūs paliksiet dzīvi un nemirsiet. Bet Hizkijam neklausiet, jo viņš jūs pieviļ sacīdams: Tas Kungs mūs izpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Vai gan pagānu dievi ikviens savu zemi izglābuši no Asiriešu ķēniņa rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kur ir Hamatas un Arpadas dievi? Kur ir Sefarvaimas, Enas un Ivas dievi? Vai tie gan izglābuši Samariju no manas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kurš no visas pasaules dieviem izglābis savu zemi no manas rokas? Kā tad Tas Kungs Jeruzālemi izglābs no manas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Bet tie ļaudis cieta klusu un viņam neatbildēja neviena vārda, jo ķēniņš bija pavēlējis un sacījis: jums nebūs viņam atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Tad nama uzraugs Elijaķims, Hilķijas dēls, un skrīveris Šebna un kanclers Joaks, Asapa dēls, nāca pie Hizkijas ar saplēstām drēbēm un viņam stāstīja Rabzakus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Kad nu ķēniņš Hizkija to dzirdēja, tad viņš saplēsa savas drēbes un apvilka maisu un gāja Tā Kunga namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Un sūtīja nama uzraugu Elijaķimu un skrīveri Šebnu un tos vecākos priesterus, maisos ģērbušos, pie pravieša Jesajas, Amoca dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Un tie uz viņu sacīja: tā saka Hizkija: šī diena ir bēdu un soda un kauna diena. Jo bērni nākuši uz dzimšanu un spēka nav dzemdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Vai Tas Kungs, tavs Dievs, nedzirdēs visus Rabzakus vārdus, ko viņa kungs, Asīrijas ķēniņš, ir sūtījis, zaimot to dzīvo Dievu, un nepārmācīs par tiem vārdiem, ko Viņš dzirdējis, Tas Kungs, tavs Dievs? Tāpēc celies un lūdz par tiem atlikušiem, kas vēl atrodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Un ķēniņa Hizkijas kalpi nāca pie Jesajas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Un Jesaja uz tiem sacīja: tā jums savam kungam būs sacīt: tā saka Tas Kungs: “Nebīsties par tiem vārdiem, ko tu esi dzirdējis, ar ko Asīrijas ķēniņa sulaiņi Mani zaimojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Redzi, Es tam došu tādu garu, ka tas dzirdēs baumu un ies atpakaļ uz savu zemi, un Es viņam paša zemē likšu krist caur zobenu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Kad nu Rabzakus gāja atpakaļ, tad viņš atrada Asīrijas ķēniņu pret Libnu karojam, jo viņš bija dzirdējis, ka tas no Laķisa jau bija aizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Un kad viņš par Tiraku, Moru ķēniņu, dzirdēja sakām: redzi, viņš ir izgājis ar tevi karot, tad viņš atkal sūtīja vēstnešus pie Hizkijas un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Tā runājiet uz Hizkiju, Jūda ķēniņu, un sakāt: lai tevi nepieviļ tavs Dievs, uz ko tu paļaujies, sacīdams: Jeruzāleme netaps rokā dota Asīrijas ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Redzi, tu esi dzirdējis, ko Asīrijas ķēniņi darījuši visām zemēm, tās izdeldēdami; un tu domā izglābties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Vai pagānu dievi tos glābuši, ko mani tēvi izpostījuši, Gozanu un Haranu un Recevu un Edeņa bērnus, kas bija Telasarā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kur ir Hamatas ķēniņš un Arpadas ķēniņš un Sefarvaimas pilsētas, Enas un Ivas ķēniņš?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Kad nu Hizkija bija dabūjis tās grāmatas no vēstnešu rokas un tās izlasījis, tad viņš gāja Tā Kunga namā, un Hizkija tās atpleta Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Un Hizkija pielūdza Tā Kunga priekšā un sacīja: Kungs, Israēla Dievs, kas sēdi pār ķerubiem, Tu viens pats esi Dievs pār visām zemes valstīm, Tu esi radījis debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Atgriez, ak Kungs, Savas ausis un klausies, atveri, ak Kungs, Savas acis un redzi un dzirdi Sanheriba vārdus, ko viņš sūtījis, zaimot To dzīvo Dievu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Patiesi, ak Kungs, Asīrijas ķēniņi ir postījuši pagānus un viņu zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Un viņu dievus metuši ugunī, jo tie nav dievi, bet cilvēku roku darbs, koks un akmens, tāpēc tie tos ir izpostījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Nu tad, Kungs, mūsu Dievs, izpestī mūs jel no viņa rokas, lai visas valstis virs zemes atzīst, ka Tu, ak Kungs, vien esi Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Tad Jesaja, Amoca dēls, sūtīja pie Hizkijas un lika sacīt: tā saka Tas Kungs, Israēla Dievs: par ko tu Mani pielūdzis pret Sanheribu, Asīrijas ķēniņu, to Es esmu klausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Šis ir tas vārds, ko Tas Kungs pret viņu runājis: tevi nievā, tevi apsmej jumprava, Ciānas meita, aiz tevis krata galvu Jeruzālemes meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Ko tu esi apsmējis un zaimojis un pret ko tu esi pacēlis savu balsi un augsti uzcēlis savas acis? Pret to Svēto iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Caur saviem vēstnešiem tu To Kungu esi apmēdījis un sacījis: ar saviem ratu pulkiem es uzkāpu kalnu galos, Lībanus virsgalā, un izcērtu viņa augstos ciedru kokus un izlasītās priedes, un tieku līdz paša gala mājoklim, līdz viņa meža lepnumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Es roku un dzeru svešus ūdeņus, un no manu kāju pēdām paliek sausas visas Ēģiptes upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Vai tu neesi dzirdējis, ka Es jau sen iepriekš to esmu sataisījis, jau vecos laikos to esmu apņēmies? Tagad Es tam esmu licis notikt, ka tu izposti stipras pilsētas un dari par akmeņu kopām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Tāpēc viņu iedzīvotājiem nogura rokas, un tie iztrūcinājās un tapa kaunā, tie bija kā zāle laukā un kā uzzēlis zaļums un kā zāle uz jumtiem un kā rūsaina labība, pirms nāk stiebros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Un Es zinu tavu sēdēšanu un tavu iziešanu un tavu ieiešanu un tavu trakošanu pret Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Tavas trakošanas dēļ pret Mani un tavas pārgalvības pēc, kas nākusi Manās ausīs, Es Savu kāsi likšu tavās nāsīs un Savus laužņus tavā mutē, un tev likšu griezties atpakaļ pa to ceļu, kur tu esi nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Un tas tev būs par zīmi: šai gadā ēdīs papuvē augušu, un otrā gadā ataugu, un trešajā gadā sējiet un pļaujiet un stādiet vīna dārzus un ēdiet viņu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Un kas no Jūda nama ir izglābts un atlicis, sakņos atkal lejup un nesīs augļus augšup;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Jo no Jeruzālemes izies atlikuši, un atpestīti no Ciānas kalna. To darīs Tā Kunga Cebaot karstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Tāpēc tā saka Tas Kungs par Asīrijas ķēniņu: viņš nenāks šai pilsētā un neiešaus tanī nevienu bultu un nepacels pret to priekšturamās bruņas un neuzmetīs pret to valni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Pa to pašu ceļu, kur viņš nācis, viņam būs griezties atpakaļ, bet šai pilsētā viņš nenāks, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Jo Es šo pilsētu paglabāšu un izpestīšu Sevis labad un Sava kalpa Dāvida labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Un tai pašā naktī notikās, ka Tā Kunga eņģelis izgāja un nokāva Asiriešu lēģerī simts astoņdesmit un pieci tūkstošus. Un kad no rīta agri cēlās, redzi, tad tur viss bija miroņu pilns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Tā Sanheribs, Asīrijas ķēniņš, aizgāja un gāja projām un griezās atpakaļ un palika Ninivē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Un notikās, kad viņš pielūdza Nizroka, sava dieva, namā, tad Adrameleķs un Sarecers, viņa dēli, to nokāva ar zobenu un aizbēga uz Ararata zemi. Un viņa dēls Asaradons palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Tanī laikā Hizkija palika slims uz miršanu, un pravietis Jesaja, Amoca dēls, nāca pie viņa un uz to sacīja: tā saka Tas Kungs: apkopi savu namu, jo tu mirsi un nepaliksi vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Tad Hizkija savu vaigu pagrieza pret sienu un pielūdza To Kungu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ak Kungs, piemini lūdzams, ka es Tavā priekšā esmu staigājis patiesībā no visas sirds un darījis, kas tev patīk. Un Hizkija gauži raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Un kad Jesaja vēl nebija izgājis ne pusceļa caur pilsētu, tad Tā Kunga vārds uz viņu notika un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Ej atpakaļ un saki uz Hizkiju, Manas tautas valdnieku: tā saka Tas Kungs, tava tēva Dāvida Dievs: Es tavu lūgšanu esmu klausījis, Es tavas asaras esmu redzējis, redzi, Es tevi darīšu veselu, trešā dienā tu iesi Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Un pie tavām dienām Es vēl pielikšu piecpadsmit gadus, un tevi un šo pilsētu Es izpestīšu no Asīrijas ķēniņa rokas un pasargāšu šo pilsētu Sevis labad un Sava kalpa Dāvida labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Un Jesaja sacīja: ņemiet vīģu rausi. Un tie to ņēma un uzlika uz to trumu, tad viņš palika vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Un Hizkija sacīja uz Jesaju: kāda ir tā zīme, ka Tas Kungs mani darīs veselu, un ka es trešā dienā iešu Tā Kunga namā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Un Jesaja sacīja: šī būs tā zīme no Tā Kunga, ka Tas Kungs šo lietu darīs, ko viņš runājis. Vai ēnai būs iet desmit kāpienus uz priekšu, vai desmit kāpienus atpakaļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Tad Hizkija sacīja: tas ir viegli, ēnai iet desmit kāpienus uz priekšu, - to ne, bet lai ēna iet desmit kāpienus atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Un pravietis Jesaja piesauca To Kungu, un Tas tai ēnai lika iet desmit kāpienus atpakaļ pa tiem pašiem kāpieniem, ko tā bija gājusi uz priekšu pie Ahaza saules stundeņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Tanī laikā Berodaks Baladans, Baladana dēls, Bābeles ķēniņš, sūtīja grāmatas un dāvanas pie Hizkijas, jo tas bija dzirdējis, ka Hizkija bijis slims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Un Hizkija par tiem priecājās un tiem radīja visu savu mantas namu, sudrabu un zeltu un dārgās zāles un to smalko eļļu un visu savu bruņu namu un visu, kas viņa mantās bija; nekas nebija viņa namā un visā viņa valstī ko Hizkija tiem nebūtu rādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Tad pravietis Jesaja nāca pie ķēniņa Hizkijas un uz to sacīja: ko šie vīri sacījuši un no kurienes tie pie tevis nākuši? Un Hizkija sacīja: tie no tālas zemes atnākuši, no Bābeles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Un tas sacīja: ko tie laba redzējuši tavā namā? Un Hizkija sacīja: tie visu redzējuši, kas manā namā; nekā nav no manām mantām, ko es tiem nebūtu rādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Tad Jesaja sacīja uz Hizkiju: klausies Tā Kunga vārdu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Redzi, dienas nāks, ka viss, kas ir tavā namā un ko tavi tēvi līdz šai dienai sakrājuši, taps novests uz Bābeli, nekas netaps atlicināts, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Un no taviem bērniem, kas no tevis nāks, ko tu dzemdināsi, taps ņemti, ka tie būs par kambarjunkuriem Bābeles ķēniņa pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Un Hizkija sacīja uz Jesaju: Tā Kunga vārds ir labs, ko tu runājis. Un viņš sacīja: lai notiek, kad tikai miers un drošība pastāv manā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Un kas vēl par Hizkiju stāstāms, un viss viņa spēks, un ko viņš darījis, un par to dīķi un ūdens grāvi, un ka viņš ūdeni vadījis pilsētā, tas viss ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Un Hizkija aizmiga saviem tēviem pakaļ, un Manasus, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasus bija divpadsmit gadus vecs, kad palika par ķēniņu, un valdīja piecdesmit un pieci gadus Jeruzālemē. Un viņa mātei bija vārds Evciba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Un viņš darīja, kas Tam Kungam nepatika, pēc to pagānu negantības, ko Tas Kungs bija izdzinis Israēla bērnu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Jo tas uztaisīja atkal kalnu altārus, ko viņa tēvs Hizkija bija iznīcinājis, un cēla Baālam altārus un taisīja Ašeru, kā Ahabs, Israēla ķēniņš, bija darījis, un metās zemē priekš visa debesspulka un tiem kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Viņš taisīja arī altārus Tā Kunga namā, par ko Tas Kungs sacījis: “Jeruzālemē Es gribu likt Savu Vārdu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Viņš uztaisīja altārus arī visam debess pulkam abos Tā Kunga nama pagalmos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Un viņš lika savam dēlam iet caur uguni un cienīja zīlēšanu un vārdošanu un pieturēja pūtējus un burvjus, un darīja daudz ļauna priekš Tā Kunga acīm, Viņu kaitinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Viņš arī lika Ašeras bildi, ko bija taisījis, tai namā, par ko Tas Kungs bija sacījis uz Dāvidu un viņa dēlu Salamanu: šai namā un Jeruzālemē, ko Es no visām Israēla ciltīm izredzējis, Es Savu vārdu likšu mūžīgu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Un Israēla kājai Es vairs nelikšu kustēt no tās zemes, ko Es esmu devis viņu tēviem, kad tie tura un dara visu, ko Es tiem esmu pavēlējis, un visu bauslību, ko Mans kalps Mozus tiem pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Bet tie neklausīja, jo Manasus tos apmaldināja, ka tie ļaunāki darīja nekā tie pagāni, ko Tas Kungs Israēla bērnu priekšā bija izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Tad Tas Kungs runāja caur Saviem kalpiem, tiem praviešiem, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Tāpēc ka Manasus, Jūda ķēniņš, darījis šādu negantību, ļaunāki pār visu, ko Amorieši darījuši priekš viņa, un Jūdu arīdzan pavedis uz grēkiem caur saviem elkudieviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Tāpēc Tas Kungs, Israēla Dievs tā saka: redzi, Es vedīšu nelaimi pār Jeruzālemi un pār Jūdu, ka ikkatram, kas to dzird, abas ausis skanēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Jo Es Jeruzālemi izdalīšu kā Samariju un izsvēršu kā Ahaba namu, un izslaucīšu Jeruzālemi, kā bļodu izslauka, kas top izslaucīta un uz muti apgāzta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Un Es atmetīšu Savas tautas atlikušos un tos nodošu viņu ienaidnieku rokā, un tie būs par laupījumu un izpostījumu visiem saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Tāpēc ka tie darījuši, kas Man nepatīk, un Mani apkaitinājuši no tās dienas, kad viņu tēvi izgāja no Ēģiptes, līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Un Manasus arī izlēja daudz nenoziedzīgas asinis, tiekams Jeruzāleme tapa pilna no viena gala līdz otram, pāri par to grēku, uz ko viņš Jūdu paveda, darīt, kas Tam Kungam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Un kas vēl par Manasu stāstāms un viss, ko viņš darījis un viņa grēki, ko viņš grēkojis, tas viss ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Un Manasus aizmiga saviem tēviem pakaļ un tapa aprakts sava nama dārzā, Uzas dārzā, un viņa dēls Amons palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amons bija divdesmit un divus gadus vecs, kad palika par ķēniņu, un valdīja divus gadus Jeruzālemē. Un viņa mātei bija vārds Mezulemeta, Aruca meita, no Jotbas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Un viņš darīja, kas Tam Kungam nepatika, kā viņa tēvs Manasus bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Un viņš staigāja visos tanīs ceļos, kur viņa tēvs bija staigājis, un kalpoja tiem elkadieviem, kam viņa tēvs bija kalpojis, un metās zemē priekš tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Un viņš atstāja To Kungu, savu tēvu Dievu, un nestaigāja Tā Kunga ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Un Amona kalpi cēla dumpi pret viņu un nokāva ķēniņu viņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Bet tās zemes ļaudis kāva visus, kas dumpi bija cēluši pret ķēniņu Amonu. Un tie zemes ļaudis darīja viņa dēlu Josiju par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Un kas vēl par Amonu stāstāms, ko viņš darījis, tas viss ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Un viņš savā kapā tapa aprakts Uzas dārzā, un viņa dēls Josija palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josija bija astoņus gadus vecs, kad palika par ķēniņu, un valdīja trīsdesmit un vienu gadu Jeruzālemē. Un viņa mātei bija vārds Jedida, Adajas meita no Backates.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Un tas darīja, kas Tam Kungam labi patika un staigāja visos sava tēva Dāvida ceļos un neatkāpās ne pa labo ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Un ķēniņa Josijas astoņpadsmitā gadā ķēniņš sūtīja skrīveri Safanu, Acalijas dēlu, Mešulama dēla dēlu, Tā Kunga namā un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Ej pie augstā priestera Hilķijas, saņemt to naudu, kas Tā Kunga namā nesta, un ko sliekšņu sargi no tiem ļaudīm sakrājuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Un to dot tiem darba uzraugiem rokā, kas ir iecelti pār Tā Kunga namu, lai tie to dod tiem strādniekiem pie Tā Kunga nama, izlabot tā nama plīsumus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Tiem amatniekiem un nama taisītājiem un mūrniekiem, pirkt kokus un cirstus akmeņus, izlabot to namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Bet lai neprasa atbildēšanu par to naudu, kas viņu rokā dota, jo tie to dara uz ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Tad augstais priesteris Hilķija sacīja uz skrīveri Safanu: es bauslības grāmatu esmu atradis Tā Kunga namā. Un Hilķija deva Safanam to grāmatu; un tas to lasīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Un skrīveris Safans nāca pie ķēniņa un viņam nesa vēsti atpakaļ un sacīja: tavi kalpi ir izbēruši to naudu, kas Tā Kunga namā atrasta, un to devuši rokā tiem darba uzraugiem, kas iecelti pār Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Un skrīveris Safans stāstīja ķēniņam un sacīja: priesteris Hilķija man devis vienu grāmatu. Un Safans to lasīja ķēniņam priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Kad nu ķēniņš dzirdēja tās bauslības grāmatas vārdus, tad viņš saplēsa savas drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Un ķēniņš pavēlēja priesterim Hilķijam un Aikamam, Safana dēlam, un Akboram, Mikajas dēlam, un skrīverim Safanam un ķēniņa kalpam Azajam, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Ejat, vaicājiet To Kungu priekš manis un priekš tiem ļaudīm un priekš visa Jūda par šās grāmatas vārdiem, kas ir atrasta. Jo Tā Kunga bardzība ir liela, kas pret mums iedegusies par to, ka mūsu tēvi šās grāmatas vārdus nav klausījuši, nedz to darījuši, kas viss mums tur uzrakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Tad priesteris Hilķija un Aikams un Akbors un Safans un Azaja nogāja pie pravietes Uldas, drēbju sarga, Šaluma, Tikvas dēla, Aras dēla dēla, sievas, kas dzīvoja Jeruzālemes otrā daļā, un tie ar to runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Un tā uz tiem sacīja: tā saka Tas Kungs, Israēla Dievs: sakāt tam vīram, kas jūs pie Manis sūtījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Tā saka Tas Kungs: redzi, Es vedīšu nelaimi pār šo vietu un pār viņas iedzīvotājiem, visus tās grāmatas vārdus, ko Jūda ķēniņš lasījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Tāpēc ka tie Mani atstājuši un kvēpinājuši citiem dieviem un Mani kaitinājuši ar visiem saviem roku darbiem, tāpēc Mana bardzība pret šo vietu iedegsies un nedzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Bet uz Jūda ķēniņu, kas jūs sūtījis, To Kungu vaicāt, jums tā būs sacīt: tā saka Tas Kungs, Israēla Dievs, par tiem vārdiem, ko tu esi dzirdējis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Tāpēc ka tava sirds mīksta tapusi, un tu priekš Tā Kunga esi zemojies, dzirdēdams, ko Es esmu runājis pret šo vietu un pret viņas iedzīvotājiem, ka tiem būs iet postā un palikt par lāstu, un esi saplēsis savas drēbes un raudājis manā priekšā, tad es tevi arī esmu paklausījis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Tāpēc, redzi, Es tevi piepulcināšu taviem tēviem, un tu ar mieru tapsi guldīts savā kapā, un tavas acis neredzēs to nelaimi, ko Es vedīšu pār šo vietu. Un tie ķēniņam atsacīja šo vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Tad ķēniņš sūtīja, un pie viņa sapulcinājās visi vecaji no Jūda un Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Un ķēniņš gāja Tā Kunga namā un līdz ar viņu visi Jūda vīri un visi Jeruzālemes iedzīvotāji un visi priesteri un pravieši un visi ļaudis, gan mazi, gan lieli. Un viņš lasīja priekš viņu ausīm visus vārdus no tās derības grāmatas, kas bija atrasta Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Un ķēniņš stāvēja tai augstajā vietā un derēja derību priekš Tā Kunga vaiga, Tam Kungam pakaļ staigāt un turēt Viņa baušļus un Viņa liecības un Viņa likumus no visas sirds un no visas dvēseles, stipri turēt šās derības vārdus, kas bija rakstīti šai grāmatā. Un visi ļaudis uzņēma šo derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Un ķēniņš pavēlēja augstajam priesterim Hilķijam, un otras kārtas priesteriem un sliekšņa sargiem, iznest no Tā Kunga nama visus rīkus, kas bija taisīti Baālam un Ašerai un visam debess pulkam, un viņš tos sadedzināja ārā aiz Jeruzālemes Kidronas ielejā un viņu pīšļus lika nest uz Bēteli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Viņš arī nocēla tos kalnu priesterus, ko Jūda ķēniņi bija iecēluši, kvēpināt uz kalniem Jūda pilsētas un ap Jeruzālemi, arī tos, kas kvēpināja Baālam, saulei un mēnesim un zvaigznēm un visam debess pulkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Viņš arī izmeta to Ašeru no Tā Kunga nama ārā aiz Jeruzālemes pie Kidronas upes un to sadedzināja pie Kidronas upes un to sagrūda pīšļos un nometa viņas pīšļus uz ļaužu bērnu kapiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Viņš noplēsa arī maucinieku namus, kas pie Tā Kunga nama bija, kur sievas auda teltis priekš Ašeras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Un viņš saaicināja visus priesterus no Jūda pilsētām un sagānīja tos kalnu altārus, kur tie svētītāji bija kvēpinājuši, no Ģebas līdz Bēršebai, un noplēsa elku altārus pie vārtiem, to, kas bija Jozuas, pilsētas virsnieka, vārtu priekšā, (un to, kas) bija pa kreiso roku, kad ieiet pilsētas vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Bet kalnu priesteri neupurēja uz Tā Kunga altāra Jeruzālemē, bet tie ēda neraudzētu maizi starp saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Viņš sagānīja arī Tovetu, Inoma bērnu ielejā, ka neviens savam dēlam vai meitai neliktu caur uguni iet Molokam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Viņš arī atmeta tos zirgus, ko Jūda ķēniņi saulei bija cēluši, kur Tā Kunga namā iet, pie kambarjunkura NetanMeleka kambara, kas iekš Parvarim, un sadedzināja arī saules ratus ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Viņš noplēsa arī tos altārus, kas bija uz Ahaza augšistabas jumta, ko Jūda ķēniņi bija taisījuši līdz ar tiem altāriem, ko Manasus bija taisījis Tā Kunga nama abos pagalmos, un tos sagrūda un meta viņu pīšļus Kidronas upē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Un ķēniņš sagānīja tos kalnu altārus Jeruzālemes priekšā, pa labo roku samaitāšanas kalnam, ko Salamans, Israēla ķēniņš, bija uztaisījis Astartei, Sidona negantībai, un Kamosam, Moaba negantībai, un Milkonam, Amona bērnu negantībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Un viņš sadragāja tos stabus un nopostīja tās Ašeras un pildīja viņu vietas ar cilvēku kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Viņš noplēsa arī to altāri, kas bija Bētelē, to kalna namu, ko Jerobeams, Nebata dēls, bija taisījis, kas Israēli paveda uz grēkiem: to altāri un kalna namu viņš noplēsa un sadedzināja to kalna namu un to sagrūda pīšļos un sadedzināja to Ašeru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Un Josija apgriezās un redzēja tos kapus, kas tur tanī kalnā bija; un viņš sūtīja un ņēma tos kaulus no tiem kapiem un tos sadedzināja uz tā altāra un to sagānīja pēc Tā Kunga vārda, ko tas Dieva vīrs bija sludinājis, kas šīs lietas sludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Un viņš sacīja: kas tā par kapa zīmi, ko es redzu? Un tās pilsētas ļaudis uz to sacīja: Tas ir Tā Dieva vīra kaps, kas no Jūda atnāca un šās lietas pasludināja, ko tu pie Bēteles altāra darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Un viņš sacīja: Lai tas dus mierā, neviens lai neaiztiek viņa kaulus. Tā tie izglāba viņa kaulus ar tā pravieša kauliem, kas no Samarijas bija nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Josija arī noplēsa visus kalnu namus Samarijas pilsētās, ko Israēla ķēniņi bija cēluši, to (Kungu) kaitinādami, un viņš tiem darīja, kā viņš Bētelē bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Un visus kalnu priesterus, kas tur bija, viņš nokāva uz tiem altāriem un sadedzināja cilvēku kaulus uz tiem; tad viņš griezās atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Un ķēniņš pavēlēja visiem ļaudīm sacīdams: turat Tam Kungam, savam Dievam, Pasa svētkus, kā šīs derības grāmatā rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Jo tādi Pasa svētki kā šie nebija turēti nedz soģu laikā, kas Israēli tiesāja, nedz visu Israēla ķēniņu, nedz Jūda ķēniņu laikā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Bet ķēniņa Josijas astoņpadsmitā gadā šie Pasa svētki Tam Kungam tapa turēti Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Un Josija arī izdeldēja pūtējus un burvjus, tēlus un elkus un visu negantību, ko vien redzēja Jūda zemē un Jeruzālemē, ka viņš stipri turētu bauslības vārdus, kas bija rakstīti tai grāmatā, ko priesteris Hilķija bija atradis Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Un priekš viņa nebija tāds ķēniņš, kā viņš, kas pie Tā Kunga būtu atgriezies no visas savas sirds un no visas savas dvēseles un ar visu savu spēku, pēc visas Mozus bauslības, un arī pēc viņa tāds necēlās, kā viņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Tomēr Tas Kungs negriezās no Savas lielās dusmības karstuma, ar ko Viņa bardzība pret Jūdu bija iedegusies, par visu kaitināšanu, ar ko Manasus Viņu bija kaitinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Un Tas Kungs sacīja: Es atmetīšu arī Jūdu nost no Sava vaiga, kā Es Israēli esmu atmetis, un atmetīšu šo pilsētu, ko Es biju izredzējis, proti Jeruzālemi, un to namu, par ko biju sacījis: Mans vārds tur būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Un kas vēl par Josiju stāstāms un viss, ko viņš darījis, tas rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Viņa laikā Faraons Nekus, Ēģiptes ķēniņš, cēlās pret Asīrijas ķēniņu pie Eifrat upes. Un ķēniņš Josija tam gāja pretī, un Ēģiptes ķēniņš to nokāva pie Meģidus, kad tie sastapās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Un viņa kalpi to aizveda nomirušu no Meģidus un to noveda uz Jeruzālemi un to apraka viņa kapā. Un tās zemes ļaudis ņēma Joakasu, Josijas dēlu, un to svaidīja un cēla par ķēniņu viņa tēva vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joakas bija divdesmit un trīs gadus vecs, kad viņš palika par ķēniņu, un valdīja trīs mēnešus Jeruzālemē. Un viņa mātei bija vārds Amutala, Jeremijas meita no Libnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Un viņš darīja, kas Tam Kungam nepatika, kā viņa tēvi bija darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Bet Faraons Nekus to saistīja Riblatā, Hamatas zemē, lai nebūtu vairs par ķēniņu Jeruzālemē, un viņš uzlika zemei meslus dot, simts talentus sudraba un vienu talentu zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Un Faraons Nekus iecēla par ķēniņu Elijaķimu, Josijas dēlu, viņa tēva Josijas vietā, un viņam deva citu vārdu, Jojaķimu. Bet Joakasu viņš ņēma līdz, un tas nāca uz Ēģipti un tur nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Un Jojaķims Faraonam deva sudrabu un zeltu. Bet viņš lika zemi uzrakstīt, lai varētu to sudrabu dot pēc Faraona pavēles, no ikkatra pēc tā raksta viņš to zeltu un sudrabu piedzina no zemes ļaudīm, ko dot Faraonam Nekum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jojaķims bija divdesmit pieci gadus vecs, kad palika par ķēniņu, un valdīja vienpadsmit gadus Jeruzālemē. Un viņa mātei bija vārds Zebuda, Pedajus meita, no Rumas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Un viņš darīja, kas Tam Kungam nepatika, kā viņa tēvi bija darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Viņa laikā Nebukadnecars, Bābeles ķēniņš, cēlās, un Jojaķims viņam bija par kalpu trīs gadus, tad viņš no tā atkal atkrita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Un Tas Kungs sūtīja pret viņu Kaldeju pulkus un Sīriešu pulkus un Moaba pulkus un Amona bērnu pulkus un tos sūtīja pret Jūdu, to izdeldēt, pēc Tā Kunga vārda, ko Viņš bija runājis caur Saviem kalpiem, tiem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Tiešām, pēc Tā Kunga vārda Jūdam tā notika, ka Viņš to atmeta nost no Sava vaiga Manasus grēku dēļ ko šis bija darījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Un to nenoziedzīgo asiņu dēļ, ko tas bija izlējis un Jeruzālemi piepildījis ar nenoziedzīgām asinīm; tāpēc Tas Kungs negribēja piedot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Un kas vēl par Jojaķimu stāstāms, un viss, ko viņš darījis, tas ir rakstīts Jūda ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Un Jojaķims aizmiga saviem tēviem pakaļ, un viņa dēls Jojaķins palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Un Ēģiptes ķēniņš neizgāja vairs no savas zemes, jo Bābeles ķēniņš bija visu uzņēmis, kas Ēģiptes ķēniņam piederēja no Ēģiptes upes līdz Eifrat upei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jojaķins bija astoņpadsmit gadus vecs, kad palika par ķēniņu, un valdīja trīs mēnešus Jeruzālemē. Un viņa mātei bija vārds Neūsta, Elnatana meita, no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Un viņš darīja, kas Tam Kungam nepatika, tā kā viņa tēvs bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Tanī laikā Nebukadnecara, Bābeles ķēniņa, kalpi cēlās pret Jeruzālemi un apsēda to pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Un Nebukadnecars, Bābeles ķēniņš, pats nāca pret to pilsētu, kad viņa kalpi to spaidīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Tad Jojaķins, Jūda ķēniņš, izgāja pie Bābeles ķēniņa ar savu māti un saviem kalpiem un saviem virsniekiem un kambarjunkuriem, un Bābeles ķēniņš to saņēma gūstā savas valdības astotā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Un viņš no turienes paņēma visas Tā Kunga nama mantas un visas ķēniņa nama mantas, un nolauzīja zeltu no visiem rīkiem, ko Salamans, Israēla ķēniņš, bija taisījis Tā Kunga namā, kā Tas Kungs bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Un viņš aizveda cietumā visu Jeruzālemi, visus virsniekus un visus varenos, desmit tūkstošus, un visus būvmeistarus un kalējus, nekas neatlika, kā tikai zemes nabaga ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Un viņš aizveda Jojaķinu uz Bābeli līdz ar ķēniņa māti un ķēniņa sievām un viņa kambarjunkuriem un zemes vareniem, tos viņš no Jeruzālemes noveda cietumā uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Un visus stipros vīrus, septiņus tūkstošus, un amatniekus un kalējus, kādu tūkstoti, kas visi bija stipri vīri karā, tos Bābeles ķēniņš noveda uz Bābeli cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Un Bābeles ķēniņš cēla par ķēniņu viņa vietā Mataniju, viņa tēva brāli, un viņam deva vārdu Cedeķija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Cedeķija bija divdesmit vienu gadu vecs, kad palika par ķēniņu, un valdīja vienpadsmit gadus Jeruzālemē, un viņa mātei bija vārds Amitala, Jeremijas meita, no Libnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Un viņš darīja, kas Tam Kungam nepatika, tāpat, kā Jojaķims bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Bet tā notika caur Tā Kunga dusmību pret Jeruzālemi un Jūdu, tiekams Viņš tos bija atmetis nost no Sava vaiga. Un Cedeķija atkrita no Bābeles ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Un notikās viņa valdības devītajā gadā desmitā mēnesi, desmitā mēneša dienā, tad Nebukadnecars, Bābeles ķēniņš, nāca ar visu savu karaspēku pret Jeruzālemi un apmeta lēģeri pret to un uztaisīja valni ap to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Un tā pilsēta palika apstāta līdz ķēniņa Cedeķijas vienpadsmitam gadam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Un (ceturtā) mēneša devītā (dienā), kad bads pilsētu pārvarēja un iedzīvotājiem vairs nebija maizes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Tad ielauzās pilsētā, un visi karavīri bēga naktī pa vārtu ceļu starp abiem mūriem pie ķēniņa dārza, (bet Kaldeji bija pilsētai visapkārt) un ķēniņš bēga pa klajuma ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Un Kaldeju spēks ķēniņam dzinās pakaļ un to panāca Jērikus klajumā, un viss viņa spēks no viņa izklīda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Un tie sagrāba ķēniņu un to noveda pie Bābeles ķēniņa uz Riblatu, un turēja tiesu pār viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Un tie nokāva Cedeķijas dēlus priekš viņa acīm un izdūra Cedeķijam acis un to saistīja ar divām vara ķēdēm un to noveda uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Un piektā mēneša septītā dienā (tas bija ķēniņa Nebukadnecara, Bābeles ķēniņa, deviņpadsmitais gads,) NebuzarAdans, pils karavīru virsnieks, Bābeles ķēniņa kalps, nāca uz Jeruzālemi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Un sadedzināja Tā Kunga namu un ķēniņa namu un visus Jeruzālemes namus, visus lielos namus viņš sadedzināja ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Un viss Kaldeju spēks, kas bija pie pils karavīru virsnieka, noplēsa Jeruzālemes mūrus visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Un tos atlikušos ļaudis, kas bija atlikuši pilsētā, un tos bēgļus, kas bija aizbēguši pie Bābeles ķēniņa, un tautas atlikumu NebuzarAdans, pils karavīru virsnieks, aizveda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Bet no zemniekiem pils karavīru virsnieks citus atlicināja par vīna dārzniekiem un arājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Un Kaldeji salauzīja tos vara stabus Tā Kunga namā un tos krēslus un to vara jūru Tā Kunga nama, un noveda to varu uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Tie paņēma arī tos podus un tās lāpstas un dakšas un kausus un visus vara rīkus pie Dieva nama kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Un pils karavīru virsnieks paņēma tos ogļu traukus un tās bļodas, kas bija tīra zelta un tīra sudraba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Tos divus stabus, to vienu jūru un tos krēslus, ko Salamans bija taisījis Tā Kunga namam. Visu šo trauku varš bija nesverams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Astoņpadsmit olektis augsts bija viens stabs un uz tā vara kronis un tas kronis bija trīs olektis augsts, un tīkli un granātāboli apkārt kronim bija visi no vara. Un tāpat bija arī tas otrs stabs ar tiem tīkliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Un pils karavīru virsnieks paņēma augsto priesteri Seraju un otru priesteri Cefaniju un trīs sliekšņa sargus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Un no pilsētas viņš paņēma vienu kambarjunkuri, kas bija pār karavīriem, un piecus vīrus no tiem, kas vienmēr bija ķēniņa priekšā un kas pilsētā atradās, un karavirsnieka skrīveri, kas zemes ļaudis rīkoja uz karu, un sešdesmit vīrus no zemes ļaudīm, kas pilsētā atradās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Un NebuzarAdans, pils karavīru virsnieks, tos ņēmis noveda pie Bābeles ķēniņa uz Riblatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Un Bābeles ķēniņš tos kāva un nokāva Riblatā Hamatas zemē. Tā Jūda tapa aizvests no savas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Bet pār tiem ļaudīm, kas bija atlikuši Jūda zemē, ko Nebukadnecars, Bābeles ķēniņš, bija atlicinājis, viņš iecēla Ģedaliju, Aikama dēlu, Safana dēla dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Kad nu visi kara virsnieki ar saviem vīriem dzirdēja, ka Bābeles ķēniņš Ģedaliju bija iecēlis par valdnieku, tad tie nāca pie Ģedalijas uz Micpu, ar vārdu: Ismaēls, Netanijas dēls, un Johanans, Kareūs dēls, un Seraja, Tanumeta dēls, no Netofas, un Jaēzanija, Maēkata dēls, ar saviem vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Un Ģedalija tiem un viņu vīriem zvērēja un uz tiem sacīja: nebīstaties no Kaldeju kalpiem, paliekat zemē un kalpojiet Bābeles ķēniņam, tad jums labi klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Bet septītā mēnesī nāca Ismaēls, Netanijas dēls, Elišama dēla dēls, no ķēniņa dzimuma, un desmit vīri ar viņu, un tie kāva Ģedaliju, ka tas nomira, līdz ar tiem Jūdiem un Kaldejiem, kas pie viņa bija Micpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Tad visi ļaudis cēlās, ir mazi, ir lieli līdz ar kara virsniekiem, un gāja uz Ēģipti; jo tie bijās no Kaldejiem. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Un trīsdesmit septītā gadā pēc tam, kad Jojaķins, Jūda ķēniņš, bija aizvests, divpadsmitā mēnesī, divdesmit septītā mēneša dienā, Evil-Merodaks, Bābeles ķēniņš, tai gadā, kad palika par ķēniņu, paaugstināja Jojaķina, Jūda ķēniņa, galvu no cietuma nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Un viņš runāja laipnīgi ar to un lika viņa krēslu pār visiem ķēniņu krēsliem, kas pie viņa bija Bābelē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Un viņš pārmija viņa cietuma drēbes, un tas ēda vienmēr viņa priekšā, kamēr dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Un viņš tam nosprieda uzturam dienišķu daļu, ko tas ikdienas dabūja no ķēniņa, kamēr dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Ādams, Sets, Enos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kainans, Mahalaleēls, Jareds,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enohs, Metuzala, Lāmehs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noa, Šems, Hams un Jafets.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Jafeta bērni bija: Gomers un Magogs un Madajus un Javans un Tūbals un Mešehs un Tīras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Un Gomera bērni bija: Aškenas un Rifats un Togarmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Un Javana bērni bija: Elišus un Taršiš, Ķītim un Dodanim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Hama bērni bija: Kušs un Micraīm, Puts un Kanaāns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Un Kuša bērni bija: Seba un Havila un Sabta un Raēma un Zabteka. Un Raēmas bērni bija: Šeba un Dedans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Un Kušs dzemdināja Nimrodu, tas sāka varens būt virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Un Micraīm dzemdināja Ludim, Ānamim un Leabim un Naftuīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Un Patrusim un Kasluīm, no kurienes Fīlisti un Kaftori cēlušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Un Kanaāns dzemdināja Sidonu, savu pirmdzimušo, un Hetu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Un Jebusi un Amori un Ģirgozi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Un Hivi un Arki un Sini');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Un Arvadi un Cemari un Hamati.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Šema bērni bija: Elams un Asurs un Arvaksads un Luds un Ārams un Uc un Huls un Ģeters un Mazeķs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Un Arvaksads dzemdināja Šalu, un Šalus dzemdināja Ēberu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Un Ēberam dzima divi dēli, tā pirmaja vārds bija Pelegs, tāpēc ka viņa laikā zeme tapa dalīta, un viņa brāļa vārds bija Joktans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Un Joktans dzemdināja Almodadu un Šelefu, Hacarmavetu un Jarahu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Un Hadoramu un Uzalu un Diķelu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Un Obalu un Abimaēlu un Zebu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Un Ofiru un Havilu un Jobabu. Šie visi ir Joktana bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Šems, Arvaksads, Šalus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Ēbers, Pelegs, Regus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serugs, Nahors, Tārus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Ābrams, tas ir Ābrahāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Ābrahāma bērni bija: Īzaks un Ismaēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Šīs ir viņu ciltis: Ismaēla pirmdzimtais bija Nebajots, tad Ķedars un Adbeēls');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Un Mibzams, Mizmus un Dumus, Mazus, Hadads un Temus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jeturs, Ravis un Ķedmus. Šie bija Ismaēla bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Un Ķeturas, Ābrahāma liekas sievas, bērni: tā dzemdēja Zimranu un Jokšanu un Medanu un Midijanu un Jisbaku un Šuahu. Un Jokšana bērni bija: Šebus un Dedans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Un Midijana bērni bija: Ēfa un Efers un Hanoks un Abidus un Eldaūs. Šie visi bija Ķeturas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Un Ābrahāms dzemdināja Īzaku; Īzaka bērni bija Ēsavs un Israēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Ēsava bērni bija: Elifas, Reguēls, Jeūs un Jaēlams un Korahs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Elifasa bērni bija: Temans un Omars, Zefus un Gaētams, Ķenas un Timnus un Amaleks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguēļu bērni bija: Nahats, Zerus, Šammus un Mizus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Un Seīra bērni bija: Lotans un Šobals un Cibeons un Anus un Dišons un Ecers un Dišans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Un Lotana bērni bija: Orus un Omams, un Lotana māsa bija Timna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Šobala bērni bija: Alvans un Manahats un Ebals, Zevus un Onams. Un Cibeona bērni bija Ajus un Anus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Anus bērni bija: Dišons. Un Dišona bērni bija: Amrans un Ešbans un Jetrans un Karans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Ecera bērni bija: Bilhans un Safans, Akans. Dišana bērni bija: Uc un Arans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Un šie ir tie ķēniņi, kas Edoma zemē valdījuši, pirms ķēniņi valdīja pār Israēla bērniem: Belus, Beora dēls, un viņa pilsētas vārds bija Dinaba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Un Belus nomira, un viņa vietā palika par ķēniņu Jobabs, Zeras dēls, no Bacras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Un Jobabs nomira, un Uzams no Temana zemes palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Un Uzams nomira, un Hadads, Bedada dēls, palika par ķēniņu viņa vietā; tas sakāva Midijaniešus Moaba laukā, un viņa pilsētas vārds bija Avite.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Un Hadads nomira, un Zamlus no Mazrekas palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Un kad Zamlus nomira, tad Sauls no Rehobotes pie tās upes palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Un kad Sauls nomira, tad BaālAnans, Akbora dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Un kad BaālAnans nomira, tad Hadads palika par ķēniņu viņa vietā, un viņa pilsētas vārds bija Pagus un viņa sievai bija vārds Mehetabeēle, Madredas meita, kas bija Mazaāba meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Un Hadads nomira. Edoma valdnieki bija: Timnas valdnieks, Alvas valdnieks, Jeteta valdnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Aholibamas valdnieks, Elas valdnieks, Pinona valdnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Ķenasa valdnieks, Temana valdnieks, Mīcara valdnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Magdiēļa valdnieks, Īrama valdnieks. Šie bija Edoma valdnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Šie bija Israēla bērni: Rūbens, Sīmeans, Levis un Jūda, Īsašars un Zebulons,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dans, Jāzeps un Benjamins, Naftalus, Gads un Ašers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Jūda bērni bija: Ģers un Onans un Šelus. Tie trīs viņam dzima no Zuas meitas, tās Kanaānietes. Bet Ģers, Jūda pirmdzimušais, bija ļauns priekš Tā Kunga acīm, tāpēc šis viņu nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Un Tamāre, viņa vedekla, tam dzemdēja Perecu un Zeru; Jūda bērnu pavisam bija pieci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Pereca bērni bija: Hecrons un Hamuls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Un Zerus bērni bija: Zimrus un Etans un Hemans un Kalkols un Darus, - to ir pavisam pieci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Un Karmus bērni bija: Akors(Akans), kas Israēli apbēdināja, kad viņš pie tā noziedzās, kas bija izdeldams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Un Etana bērni bija: Azarijus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Un Hecrona bērni, kas viņam dzima, bija Jerameēls un Rams un Kalubajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Un Rams dzemdināja Aminadabu, un Aminadabs dzemdināja Nahšonu, to Jūda bērnu valdnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Un Nahšons dzemdināja Zalmu, un Zalmus dzemdināja Boasu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Un Boas dzemdināja Obedu. Un Obeds dzemdināja Isaju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Un Isajus dzemdināja savu pirmdzimušo Elijabu un Abinadabu, otru, un Šimeju, trešo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Netaneēlu, ceturto, Radaju, piekto,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ocemu, sesto, Dāvidu, septīto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Un viņu māsas bija Ceruja un Abigaīle. Un Cerujas bērni bija trīs: Abizajus, Joabs un Azaēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Un Abigaīle dzemdēja Amasu. Un Amasas tēvs bija Jeters, Ismaēlietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Un Kālebs, Hecrona dēls, dzemdināja bērnus no savas sievas Azubas un no Jerigotas, un šās bērni ir: Jezers un Zobabs un Ardons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Kad nu Azuba bija nomirusi, tad Kālebs apņēma Efratu; tā tam dzemdēja Uru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Un Hurs dzemdināja Ūri. Un Ūris dzemdināja Becaleēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Un pēc Hecrons iegāja pie Gileāda tēva Mahira meitas, un to apņēma, sešdesmit gadus vecs būdams, un tā tam dzemdēja Zegubu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Un Zegubs dzemdināja Jaīru, un tam bija divdesmit trīs pilsētas Gileāda zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Un Gešurs un Arams tiem atņēma Jaīra miestus, Ķenatu ar visām piederīgām vietām, sešdesmit pilsētas. Un šie visi ir Mahira, Gileāda tēva, bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Kad Hecrons KālebEfratā bija nomiris, tad Abija, Hecrona sieva, tam dzemdēja Azuru, Tekoūs tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Un Jerameēļa, Hecrona pirmdzimušā, bērni bija: Rams, tas pirmdzimušais, un Bunus un Orens un Ocems un Ahijus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Un Jerameēlim bija vēl viena sieva, ar vārdu Atara, tā bija Onama māte.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Un Rāma, Jerameēla pirmdzimušā, bērni bija: Maācs un Jamins un Eķers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Un Onama bērni bija Zamajus un Jadus. Un Zamajus bērni bija Nadabs un Abizurs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Un Abizura sievai bija vārds Abikaīle, un tā tam dzemdēja Ekbonu un Molidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Un Nadaba bērni bija: Zeleds un Apaīms, un Zeleds nomira bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Apaīma bērni bija: Jezejus. Un Jezejus bērni bija: Zezans. Un Zezana bērni bija: Aklajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Un Jadus, Zamajus brāļa, bērni bija: Jeters un Jonatāns. Un Jeters nomira bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Un Jonatāna bērni bija. Pelets un Zaza. Šie bija Jerameēļa bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Un Zezanam dēlu nebija, bet meitas vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Un Zezanam bija ēģiptiešu kalps, Jarkus vārdā. Un Zezans deva savu meitu Jarkum, savam kalpam, par sievu, un tā tam dzemdēja Ataju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Un Atajus dzemdināja Nātanu. Un Nātans dzemdināja Zabadu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Un Zabads dzemdināja Evlalu. Un Evlals dzemdināja Obedu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Un Obeds dzemdināja Jeū. Un Jeūs dzemdināja Azariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Un Azarijus dzemdināja Kalecu. Un Kalec dzemdināja Eleazu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Un Eleazus dzemdināja Zisemaju. Un Zisemajus dzemdināja Šalumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Un Šalums dzemdināja Jekamju. Un Jekamjus dzemdināja Elišamu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Un Kāleba, Jerameēļa brāļa, bērni bija: Mezus, viņa pirmdzimušais, šis ir Ziva tēvs, un Marezas, Hebrona tēva, bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Un Hebrona bērni bija: Korahs un Tabuūs un Reķems un Šamus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Un Šamus dzemdināja Rakamu, Jarkaāma tēvu. Un Reķems dzemdināja Zamaju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Un Zamajum bija dēls, Maons vārdā, un Maons bija Betcura tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Un Eva, Kāleba lieka sieva, dzemdēja Haranu un Mocu un Gazezu. Un Harans dzemdināja Gazezu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Un Jadajus bērni bija: Reģems un Jotams un Ģezans un Pelets un Epus un Zaāps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maēka, Kāleba lieka sieva, dzemdēja Zebru un Tirkanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Un dzemdēja Zaāpu, Madmana tēvu un Zevu, Makbena tēvu un Ģibeja tēvu. Un Kāleba meita bija Akza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Šie bija Kāleba bērni: BenUrs, tas pirmdzimušais no Efratas, Šobals, KiriatJearima tēvs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Zalmus, Bētlema tēvs, Aravs, Betgaderas tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Un Šobalam, KirijatJearima tēvam, bija dēli: Aroa, puse no Manuota');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Un ĶirijatJearima ciltis, Jetrieši un Putieši un Zumatieši un Mizraieši. No šiem ir nākuši Caregatieši un Estaolieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Zalmus bērni bija: Bētlems un Netofatieši, Joaba nama kronis, un puse no Manaķiešiem, Carieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Un rakstītāju radi, kas Jaēbecā dzīvoja: Tireatieši un Zimeatieši un Zukatieši. Šie ir Kinieši, kas nākuši no Amata, BetRekaba tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Šie bija Dāvida bērni, kas tam Hebronē dzimuši: tas pirmdzimušais Amnons, no Jezreēlietes Aķinomas. Otrais Daniēls no Karmelietes Abigaīles;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Trešais Absaloms, Maēkas, Gešura ķēniņa Talmajus meitas, dēls, ceturtais Adonijus, Aģitas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Piektais Zevatjus no Abitalas; sestais Jetreams no viņa sievas Eglas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Šie seši viņam dzimuši Hebronē; jo viņš tur valdīja septiņus gadus un sešus mēnešus, un trīsdesmit trīs gadus viņš valdīja Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Un šie viņam dzimuši Jeruzālemē: Zimeūs un Zobabs un Nātans un Salamans, četri no Batsebas, Amiēļa meitas, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Jebears un Elišamus un Elivalets');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Un Nogus un Nevegs un Japius');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Un Elišamus un Elijadus un Elivalets, deviņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Šie visi ir Dāvida bērni, bez lieku sievu bērniem. Un Tamāra bija viņu māsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Un Salamana dēls bija Rekabeams, tā dēls Abija, tā dēls Aza, tā dēls Jehošafats,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Tā dēls Jehorams, tā dēls Ahazija, tā dēls Joas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Tā dēls Amacīja, tā dēls Azarija, tā dēls Jotams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Tā dēls Ahazs, tā dēls Hizkija, tā dēls Manasus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Tā dēls Amons, tā dēls Josija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Un Josijas bērni bija Joanams, tas pirmdzimušais, Joaķims otrais, Cedeķija trešais, Šalums ceturtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Jojaķima bērni bija Jekanija, tā dēls bija Cedeķija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Un Jekanijas, tā cietumā aizvestā, bērni bija Šealtiēls, viņa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Un Malķīrams un Vadajus un Zemneacars un Jekamajus, Ozamus un Nedabijus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Un Vadajus bērni bija Cerubabels un Šimejus. Un Cerubabeļa bērni bija Mešulams un Ananija un Šelomite viņu māsa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Un Hašubus un Oēls un Bereķija un Azadija, Juzab Ezeds, pieci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Un Ananijas bērni bija Platija un Ješaja; Revajas bērni, Arnana bērni. Obadijas bērni, Šehanijas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Un Šehanijas bērni bija: Šemajus. Un Šemajus bērni bija: Hatus un Jiģeals un Bariaks un Nearija un Šafats, Zezus, seši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Un Nearijas bērni bija: Elioēnajus un Hizkija un Asrikams, trīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Un Eljoēnajus bērni bija: Obajus, Elijašibs un Pelaja un Akubs un Johanans no Delajus un Hananus, septiņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Jūda bērni bija: Perecs, Hecrons un Karmus un Hurs un Šobals.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Un Reajus, Šobala dēls, dzemdināja Jakatu. Un Jakats dzemdināja Ahumaju un Lahadu, šie ir Caregatiešu radi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Šie ir no Etama tēva: Jezreēls, Jezmus un Jedbas, un viņu māsai bija vārds Aclelpone.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Un Pnuēls bija Ģedora tēvs, un Ezers bija Uzas tēvs. Šie ir Ura, Efratas pirmdzimušā dēla, Bētlema tēva, bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Un Azuram, Tekoūs tēvam, bija divas sievas: Ellea un Naēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Un Naēra tam dzemdēja Akuzamu un Heferu un Temnu un Akastaru. Šie ir Naēras bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Un Elleas bērni bija: Cerets, Jecoars un Etnans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Un Koc dzemdināja Anubu un Acobebu un Aharhēla, Aruma dēla, radus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Un Jaēbecam bija lielāks gods pār saviem brāļiem, un viņa māte viņa vārdu bija saukusi Jaēbecs, sacīdama: es to ar sāpēm esmu dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Jo Jaēbecs piesauca Israēla Dievu un sacīja: kaut tu mani svētīt svētītu un manas robežas vairotu, un tava roka būtu ar mani un darītu, ka ļaunums un sāpes mani neaiztiek Un Dievs tam lika nākt, ko viņš lūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Un Kalubs, Zukas brālis, dzemdināja Meķeru, šis ir Estona tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Un Estons dzemdināja Betravu un Paseju un Teīnnu, Naāsa pilsētas tēvu. Šie ir Rekas vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Un Ķenasa bērni bija: Otniēls un Seraja. Un Otniēļa bērni bija: Atats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Un Meonotajus dzemdināja Ovru. Un Seraja dzemdināja Joabu, amatnieku ielejas tēvu, jo tie bija amatnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Un Kāleba, Jefunna dēla, bērni bija: Irus, Elus un Naāms. Un Elus bērni bija: Kenas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Un Jealeēļa bērni bija: Zivs un Ziva, Tirja un Azareēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Un Ezras bērni bija: Jeters un Mereds un Hefers un Jalons un Taārs ar Mirjamu un Zamaju un Jezbu, Estemoas tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Un viņa sieva Judija dzemdēja Jeredu, Ģedora tēvu, un Heberu, Zokus tēvu, un Jekutiēli, Zanoas tēvu. Šie ir Bitjas, Faraona meitas, bērni, ko Mereds bija apņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Un sievas Hodijas, Nakama māsas bērni bija: Ķegilas tēvs garmietis, un Maēkiets Estemoa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Un Sīmeana bērni bija: Amnons un Rinnus, Benanans un Tilons. Un Jezeūs bērni bija: Zoēts un BenZoēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Un Šelus, Jūda dēla, bērni bija: Ģers, Lekas tēvs, un Laēdus, Marezas tēvs, un Azbeas nama vēveru(audēju) radi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Ir Joķims un KoŠebas vīri un Joas un Zaravs, kas pār Moabiešiem valdījuši, un Jazubi Laēmā; bet tās jau ir vecas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Tie bija podnieki un dzīvoja Netaīmā un Ģederā; pie ķēniņa darba tie tur dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Sīmeana bērni bija: Nemuels un Jamins un Jaribs, Zerus, Sauls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Tā dēls bija Šalums, tā dēls Mibzams, tā dēls Mizmus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Un Mizmus bērni bija: Amuels, tā dēls Zakurs, tā dēls Šimejus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Un Šimejum bija sešpadsmit dēli un sešas meitas, bet viņa brāļiem nebija daudz bērnu. Un visi viņu radi nevairojās tik daudz, kā Jūda bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Un tie dzīvoja Bēršebā un Moladā un AcarZualā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Un Bilā un Ecemā un Toladā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Un Betuēlā un Ormā un Ciklagā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Un Bet Markabotā un Acurzuzimā un Betbiērā un Sāraīma. Šās bija viņu pilsētas, tiekams Dāvids palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Un viņu ciemi bija Etans un Aīns, Rimons un Tokens un Azans, piecas pilsētas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Un visi viņu ciemi apkārt šīm pilsētām līdz Baālam; šie ir viņu dzīvokļi un viņu radu raksti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Un Mezobabs un Jamleķs un Jošus, Amacījas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Un Joēls un Jeūs, Jozivja dēls, tas bija Serajas, tas Aziēļa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Un Eljoēnajus un Jaēkobus un Jezoaja un Azaja un Adiēls un Jezimeēls un Benaja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Un Zizas, Zivejus dēls, tas bija Alona, tas Jedajas, tas Zimrus, tas Šemajas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Šie vārdiem minetie bija lielkungi saviem radiem, un viņu tēva nama radi izplētās daudzumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Un tie gāja līdz Ģedoras ceļam, ielejas rīta pusē, ganības meklēdami savām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Un tie atrada taukas un labas ganības un plašu zemi, klusu un mierīgu, jo Hama bērni tur senāk dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Un tie, vārdiem uzrakstītie, nāca Hizkijas, Jūda ķēniņa, laikā, un apkāva viņu teltis un dzīvotājus, kas tur bija, un tos izdeldēja līdz šai dienai, un dzīvoja viņu vietā, jo tur bija ganības viņu avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Un no viņiem, no Sīmeana bērniem, izgāja piecsimt vīri uz Seīra kalniem, un Pēlatja un Nearja un Revaja un Uziēls, Jezejus dēli, tiem bija par virsniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Un tie apkāva Amaleka atlikumu, kas bija izglābies, un tur dzīvoja līdz pat šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Un Rūbena, Israēla pirmdzimušā dēla, bērni, (jo viņš bija tas pirmdzimušais, bet tāpēc, ka tas bija sagānījis sava tēva gultu, viņa pirmdzimtība tapa dota Jāzepa, Israēla dēla, bērniem, bet to tik neskaitīja (cilts rakstos) par pirmdzimto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Jo Jūda palika varens starp saviem brāļiem, un no viņa bija tas valdnieks, bet Jāzepam palika tā pirmdzimtība).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Rūbena, Israēla pirmdzimušā dēla, bērni bija: Hanoks un Palus, Hecrons un Karmus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Joēļa bērni bija: Šemajus, tā dēls Gogs, tā dēls Šimejus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Tā dēls Miha, tā dēls Reaja, tā dēls Baāls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Tā dēls Beēra, ko TiglatPilnesers, Asīrijas ķēniņš, aizveda cietumā, - tas bija Rūbena bērnu lielskungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Un viņa brāļi pēc saviem radiem, kā tie savos radu rakstos tapa skaitīti: virsnieks Jejels un Zaharija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Un Belus, Asasa dēls, tas bija Zemas, tas Joēļa dēls, tas dzīvoja Aroērā un līdz Nebum un BaālMeonam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Un pret rītiem viņš dzīvoja, līdz kamēr nāk tuksnesī pie Eifrat upes, jo viņu ganāmie pulki bija vairojušies Gileādas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Un Saula laikā tie karoja pret Agariem; un šie krita caur viņu rokām, un tie dzīvoja viņu teltīs visā Gileādas rīta pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Un Gada bērni dzīvoja tiem pretī Basanas zemē līdz Zalkai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joēls tas pirmais un Safans tas otrais un Jaēnajus un Šafats Basanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Un viņu brāļi pēc viņu tēvu namiem bija: Mikaēls un Mešulams un Zebus un Jorajus un Jaēkans un Zija un Hebers, septiņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Šie bija Abikaīļa bērni, tas bija Ura, tas Jarvas, tas Gileāda, tas Mikaēļa, tas Jezizajus, tas Jādas, tas Busa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Akus, Abdiēļa dēls, Gunas dēla dēls, bija virsnieks pār viņu tēvu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Un tie dzīvoja Gileādā un Basanā un viņu piederīgās vietās un visā Šarona apgabalā līdz viņu galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Visi šie tapa sazīmēti radu rakstos Jotama, Jūda ķēniņa, laikā, un Jerobeama, Israēla ķēniņa, laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Rūbena bērnu un Gada bērnu un Manasus puscilts, kas bija sirdīgi vīri un bruņas un zobenu nesa un stopu uzvilka un uz karu mācīti, to bija četrdesmit četri tūkstoši septiņsimt sešdesmit, kas gāja karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Un tie karoja pret Agariem un Jeturu un Navesu un Nodabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Bet tiem nāca palīgs pret šiem, un Agari tapa doti viņu rokā un visi, kas ar tiem bija. Jo tie piesauca Dievu kaujā, un viņš no tiem likās pielūgties, tāpēc ka tie uz viņu cerēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Un tie noveda lopus, piecdesmit tūkstoš kamieļus, divsimt piecdesmit tūkstoš avis un divtūkstoš ēzeļus un simt tūkstoš cilvēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Jo daudz krita ievainoti, tāpēc ka tā kauja bija no Dieva. Un tie dzīvoja viņu vietā līdz cietuma laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Un Manasus puscilts bērni dzīvoja tai zemē un vairojās no Basanas līdz Baāl Hermonam un Senirai un Hermona kalnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Un šie bija viņu tēva namu virsnieki: Hefers un Jezejus un Eliēls un Asriēls un Jeremija un Odavija un Jakdiēls, stipri varoņi, slaveni vīri, savu tēvu nama virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Bet kad tie apgrēkojās pret savu tēvu Dievu un maukoja pakaļ to zemes ļaužu dieviem, ko Dievs viņu priekšā bija izdeldējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Tad Israēla Dievs pamodināja Pūla, Asīrijas ķēniņa, garu un Tiglat-Pilnesera, Asīrijas ķēniņa, garu un aizveda cietumā Rūbena bērnus un Gada bērnus un Manasus puscilti un tos noveda uz Alu un Aboru un Aru un pie Gozanas upes līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Levja bērni bija: Geršons, Kehāts un Merarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Un Kehāta bērni bija: Amrams, Jecears un Hebrons un Uziēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Un Amrama bērni bija: Ārons un Mozus un Mirjame. Un Ārona bērni bija: Nadabs un Abijus, Eleazars un Ītamars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazars dzemdināja Pinehasu. Pinehas dzemdināja Abizuū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Un Abizuūs dzemdināja Buku, un Bukus dzemdināja Uzu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Un Uzus dzemdināja Seraju, un Serajus dzemdināja Merajotu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajots dzemdināja Amariju, un Amarija dzemdināja Aķitubu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Un Aķitubs dzemdināja Cadoku, un Cadoks dzemdināja Aķimaācu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Un Aķimaācs dzemdināja Azariju, un Azarija dzemdināja Johananu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Un Johanans dzemdināja Azariju, to, kas bija par priesteri tai namā, ko Salamans Jeruzālemē uztaisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Un Azarija dzemdināja Amariju, un Amarija dzemdināja Aķitubu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Un Aķitubs dzemdināja Cadoku, un Cadoks dzemdināja Šalumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Un Šalums dzemdināja Hilķiju, un Hilķija dzemdināja Azariju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Un Azarija dzemdināja Seraju un Seraja dzemdināja Jocadaku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Bet Jocadaks gāja līdz, kad Tas Kungs Jūdu un Jeruzālemi aizveda caur Nebukadnecara roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Tad nu Levja bērni ir: Geršons, Kehāts un Merarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Un šie ir Geršona bērnu vārdi: Libnus un Šimejus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Un Kehāta bērni bija: Amrams un Jecears un Hebrons un Uziēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Un Merarus bērni bija: Maēlus un Muzus. Un šie ir Levitu radi pēc viņu tēviem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Geršona dēls bija Libnus, tā Jakats, tā Zimus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Tā Joaks, tā Idus, tā Zerus, tā Jeatrajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Kehāta bērni bija: Aminadabs, tā dēls bija Korahs, tā Asirs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Tā Elkanus, tā AbiAsafs, tā Asirs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Tā Taāts, tā Uriēls, tā Uzija, tā Sauls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Un Elkanus bērni bija: Amasaja un Aķimots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Tā dēls bija Elkanus, tā Elkanus no Covas, tā Nahats,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Tā Elijabs, tā Jeroams, tā Elkanus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Un Samuēla bērni bija: tas pirmdzimtais Vaznus un Abija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Merarus bērni bija: Maēlus, tā dēls bija Libnus, tā Šimejus, tā Uzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Tā Zimeūs, tā Aģija, tā Azaja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Un šie ir tie, ko Dāvids iecēla par dziedātājiem Tā Kunga namā, kur tas šķirsts stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Un tie kalpoja priekš saiešanas telts dzīvokļa ar dziedāšanu, tiekams Salamans uztaisīja Tā Kunga namu Jeruzālemē. Un tie stāvēja pēc kārtām savā kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Un šie ir, kas stāvēja ar saviem bērniem: no Kehāta bērniem Hemans, tas dziedātājs, Joēļa dēls, tas bija Samuēla dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Tas bija Elkanus, tas Jeroama, tas Eliēļa, tas Toūs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Tas Cuva, tas Elkanus, tas Maāta, tas Amasajus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Tas Elkanus, tas Joēla, tas Azarijas, tas Cefanijas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Tas Takala, tas Asira, tas AbiAsafa, tas Korahs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Tas Jeceara, tas Kehāta, tas Levja, tas Israēla dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Un viņa brālis Asafs stāvēja viņam pa labo roku. Asafs bija Bereķijas dēls, tas Zimeūs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Tas Mikaēļa, tas Baāsejas, tas Malhijas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Tas Atnus, tas Zerus, tas Adajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Tas Etana, tas Zimus, tas Šimejus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Tas Jahata, tas Geršona, tas Levja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Un viņu brāļi, Merarus bērni, stāvēja pa kreiso roku, ar vārdu Etans, Kuzus dēls, tas bija Abdus, tas Maluka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Tas Hašabijas, tas Amacījas, tas Hilķijas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Tas Amcus, tas Banus, tas Zamerus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Tas Maēlus, tas Muzus, tas Merarus, tas Levja dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Un viņa brāļi, Levja bērni, bija iecelti visādai kalpošanai Dieva nama dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Un Ārons un viņa dēli upurēja uz dedzināmo upuru altāra un uz kvēpināma altāra, un bija iecelti, visādi kalpot visusvētākajā vietā un Israēli salīdzināt, kā Dieva kalps Mozus bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Un šie bija Ārona bērni: Eleazars, viņa dēls, tā dēls bija Pinehas, tā Abizuūs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Tā Bukus, tā Uzus, tā Seraja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Tā Merajots, tā Amarija, tā Aķitubs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Tā Cadoks, tā Aķimaācs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Un šie ir Ārona bērnu, Kehātu radu, dzīvokļi pēc viņu miestiem viņu robežās, jo tur viņiem mesli bija krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Un tiem deva Hebroni Jūdu zemē un viņas apgabalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Bet pilsētas tīrumus un viņas ciemus deva Kālebam, Jefunna dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Un Ārona bērniem deva tās glābšanas pilsētas, Hebroni un Libnu un viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Un Jatiru un Estemoū un viņas apgabalu, un Hilenu un viņas apgabalu, un Debiru un viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Un Azanu un viņas apgabalu, un BetŠemesu un viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Un no Benjamina cilts Ģebu un viņas apgabalu, un Alemeti un viņas apgabalu, un Anatotu un viņas apgabalu, - visas viņu pilsētas bija trīspadsmit viņu rados.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Bet tiem citiem Kehāta bērniem pēc viņu radiem no Manasus puscilts nodeva caur mesliem desmit pilsētas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Un Geršona bērniem pēc viņu radiem no Īsašara cilts un no Ašera cilts un no Naftalus cilts un no Manasus cilts Basanā kļuva dotas trīspadsmit pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Merarus bērniem pēc viņu radiem no Rūbena cilts un no Gada cilts un no Zebulona cilts iedeva caur mesliem divpadsmit pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Tā Israēla bērni Levitiem deva pilsētas ar viņu apgabaliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Un no Jūda bērnu cilts un no Sīmeana bērnu cilts un no Benjamina bērnu cilts, nodeva caur mesliem šās ar vārdu sauktās pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Bet (tiem citiem) Kehāta bērnu radiem bija savas pilsētas Efraīma ciltī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Jo tiem deva tās glābšanas pilsētas: Šehemi ar viņas apgabalu uz Efraīma kalniem, un Ģezeru ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Un Jakmeamu ar viņas apgabalu, un BetOronu ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Un Ajaloni ar viņas apgabalu, un GatRimonu ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Un no Manasus puscilts Aneru ar viņas apgabalu, un Bileāmu ar viņas apgabalu, - tiem citiem Kehāta bērnu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Geršona bērniem deva no Manasus puscilts radiem: Golanu Basanā ar viņas apgabalu un Astarotu ar viņas apgabalu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Un no Īsašara cilts: Ķedesu ar viņas apgabalu un Dabratu ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Un Rāmotu ar viņas apgabalu un Anemu ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Un no Ašera cilts (deva) Mazalu ar viņas apgabalu un Abdonu ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Un Ukoku ar viņas apgabalu un Rekobu ar viņas apgabalu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Un no Naftalus cilts deva Ķedesu Galilejā ar viņas apgabalu un Amonu ar viņas apgabalu un Kiriataīmu ar viņas apgabalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Tie citi Merarus bērni no Zebulona cilts dabūja Rimonu ar viņas apgabalu un Tāboru ar viņas apgabalu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'Un viņpus Jardānes pie Jērikus, pret Jardānes rīta pusi, no Rūbena cilts: Beceru tuksnesī ar viņas apgabalu un Jacu ar viņas apgabalu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Un Ķedemotu ar viņas apgabalu un Mevaātu ar viņas apgabalu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Un no Gada cilts: Rāmotu Gileādā ar viņas apgabalu un Mahānaīmu ar viņas apgabalu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Un Hešbonu ar viņas apgabalu un Jaēzeru ar viņas apgabalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Un Īsašara bērni bija: Tolus un Puūs, Jazubs un Šimrons, četri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Un Tolus bērni bija: Uzus un Revaja un Jeriēls un Jakmajus un Jebzams un Samuēls, savu tēvu namu virsnieki no Tolus, stipri varoņi savos rados; viņu skaits Dāvida laikā bija divdesmit divi tūkstoši un seši simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Un Uzus bērni bija: Jezraja. Un Jezrajas bērni bija: Mikaēls un Obadija un Joēls, Jezija, - pavisam pieci virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Un tiem pēc saviem radiem, pēc saviem tēvu namiem bija karaspēka pulki trīsdesmit seši tūkstoši, jo tiem bija daudz sievu un bērnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Un viņu brāļi visos Īsašara rados bija stipri varoņi pēc uzzīmēšanas pavisam astoņdesmit septiņi tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjamina (bērni) bija: Belus un Beķers un Jediaēls, trīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Un Belus bērni bija: Ecbons un Uzus un Uziēls un Jerimots un Īrus, pieci virsnieki savu tēvu namos, stipri varoņi, un pēc uzzīmēšanas divdesmit divtūkstoš trīsdesmit un četri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Un Beķera bērni bija: Zemirus un Joas un Eliēzers un Elioēnajus un Omrus un Jerimots un Abija un Anatots un Alemets, šie visi bija Beķera bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Un pēc uzzīmēšanas savos rados tie bija savu tēvu namu virsnieki, stipri vareni ļaudis, divdesmit tūkstoši divi simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Un Jediaēļa bērni bija: Bilhans. Un Bilhana bērni bija: Jeūs un Benjamins un Eūds un Knaēna un Zetans un Taršišs un Aķizaārs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Visi šie ir Jediaēļa bērni, tēvu namu virsnieki, stipri varoņi, septiņpadsmit tūkstoši divsimt, kas karā gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Un Zupims un Hupims bija Īra bērni, un Hušims - Aķera bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naftalus bērni bija: Jakciēls un Gunus un Jecers un Šalums, Bilhas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manasus bērni bija: Ezriēls, kas viņam piedzima. Un viņa lieka sieva no Arama tam dzemdēja Mahiru, Gileāda tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Un Mahirs ņēma par sievu Hupima un Zupima māsu, un viņas vārds bija Maēka. Un tā otra vārds bija Celofehads, un Celofehadam bija meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Un Mahira sieva Maēka dzemdēja dēlu un sauca viņa vārdu Peres, un viņa brāļa vārds bija Zares, un šā dēli bija Ulams un Raķems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Un Ulama bērni bija: Bedans. Šie bija Gileāda bērni, tas bija Mahira, tas Manasus dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Un viņa māsa Moleķete dzemdēja Izudu un Abiēzeru un Maēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Un Zemidas bērni bija: Aķejans un Šehems un Likus un Aniams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Un Efraīma bērni bija: Zutelaks, tā dēls Bereds, tā Takats, tā Elada, tā Takats,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Tā Zabads, tā Zutelaks un Ezers un Eleads. Un Gatas vīri, tās zemes iedzīvotāji, šos nokāva, tāpēc ka tie bija nākuši lejā, viņu lopus atņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Un Efraīms, viņu tēvs, žēlojās ilgu laiku, un viņa brāļi nāca to iepriecināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Un viņš gāja pie savas sievas, un tā tapa grūta un dzemdēja dēlu un viņš nosauca viņa vārdu Briju, tāpēc ka bēdas aizņēmušas viņa namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Un viņa meita bija Zeēra; tā uztaisīja Lejas un Kalna BetOronu un UzenZeēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Un Repus bija viņa dēls, tā dēls Rezeps un Telus, tā dēls Taāns,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Tā Laēdans, tā Amjuds, tā Elišama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Tā Nuns, tā Jozuas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Un viņu īpašums un mājvieta bija Bētele ar saviem ciemiem un pret rītiem Naērana un pret vakara pusi Ģezera ar saviem ciemiem, un Šeheme ar saviem ciemiem, līdz Gazai un viņas ciemiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Un sānis Manasus bērniem bija Betzeana ar saviem ciemiem, Taēnaka ar saviem ciemiem, Meģidus ar saviem ciemiem, Dora ar saviem ciemiem. Tanīs dzīvoja Jāzepa, Israēla dēla, bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Ašera bērni bija: Jemnus un Ješvus un Jisvi un Berius un Zera, viņu māsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Un Berius bērni bija: Hebers un Malķiēls, šis ir Birzavita tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Un Hebers dzemdināja Javletu un Zomeru un Otamu un Zuū, viņu māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Un Javleta bērni bija: Pazaks un Bimeals un Azvats; šie bija Javleta bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Un Zomera bērni bija: Akus un Ragus un Jeūbus un Arams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Un viņa brāļa Elema bērni bija: Zefus un Jemnus un Zeles un Amals.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Covas bērni bija: Zuūs un Arnevers un Zuals un Berus un Jemrus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Becers un Ods un Šamus un Zilza un Jetrans un Beēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Un Jetera bērni bija: Jefunnus, Vizvus un Ara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Un Ulas bērni bija: Araks un Aniēls un Ricja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Visi šie bija Ašera bērni, tēvu nama virsnieki, izlasīti stipri varoņi, lielkungu virsnieki. Un pēc uzzīmēšanas kara spēkā tie bija skaitā divdesmit seštūkstoš vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Un Benjamins dzemdināja Belu, savu pirmdzimušo, Abzalu otru, Aru trešo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nohu ceturto un Rafu piekto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Un Belam bija bērni: Adars un Ģerus un Abiūds');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Un Abizuūs un Naēmans un Akoa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Un Ģerus un Zepupans un Hūrams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Šie ir Eūda bērni, tie bija Ģebas iedzīvotāju tēvu namu virsnieki, un tos aizveda uz Manatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Proti Naēmans, Ahija un Ģerus; tas tos aizveda un dzemdināja Uzu un Ahijudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Un Zakaraīms dzemdināja Moaba zemē, kad tas Hušimu un Baeru, savas sievas, bija atlaidis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'No Odezas, savas sievas, viņš dzemdināja Jobabu un Cibju un Mezu un Malkamu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Un Jeūcu un Zaķiju un Mirmu. Šie ir viņa dēli, tēvu namu virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Un no Hušimas viņš dzemdināja Abitobu un Elpaālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Un Elpaāla bērni ir: Ēbers un Mizeams un Zamers. Šis uztaisīja Onu un Ladu un viņu ciemus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Un Brija un Šemus, tie bija Ajalones iedzīvotāju tēvu namu virsnieki; šie izdzina Gatas iedzīvotājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Un Ahijus, Zazaks un Jeremots');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Un Zebadija un Arads un Aders');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Un Mikaēlis un Jespus un Jokus, tie bija Brijas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Un Zebadija un Mešulams un Iskus un Hebers,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Un Jezmerajus un Jezlija un Jobabs, tie bija Elpaāla bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Un Jaķims un Sihrus un Zabdus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Un Elioēnajus un Ciltajus un Eliēls');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Un Adaja un Braja un Zimrats, tie bija Šimeja bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Un Jezpans un Ēbers un Eliēls');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Un Abdons un Sihrus un Hanans');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Un Ananaja un Elams un Antotija');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Un Jepdeja un Pnuēls, tie bija Zazaka bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Un ZamSerajus un Zekarija un Atalija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Un Jaērezija un Elija un Sihrus, tie bija Jerokama bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Tie bija tēvu namu virsnieki savos rados un valdnieki un dzīvoja Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Un Gibeonā dzīvoja Gibeona tēvs, un viņa sievai bija vārds Maēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Un viņa pirmdzimušais dēls bija Abdons, tad Curs un Ķis un Baāls un Nadabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Un Ģedors un Ahijus un Zeķers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Un Miklots dzemdināja Zimeū, un tie dzīvoja arīdzan blakām saviem brāļiem Jeruzālemē pie saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Un Ners dzemdināja Ķisu, un Ķis dzemdināja Saulu, un Sauls dzemdināja Jonatānu un Malķizuū un Abinadabu un Ezbaālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Un Jonatāna dēls bija Meribaāls, un Meribaāls dzemdināja Mihu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Un Mihas bērni bija: Pitons un Meleķs un Taērus un Ahazs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Un Ahazs dzemdināja Joadu, un Joadus dzemdināja Alemetu un Asmavetu un Zimru, un Zimrus dzemdināja Mocu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Un Mocus dzemdināja Bineū, tā dēls bija Ravus, tā Eliazus, tā Acels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Un Acelim bija seši dēli, un šie ir viņu vārdi: Asrikams, Bokrus un Ismaēls un Zearija un Obadija un Hanans. Visi šie ir Aceļa bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Un viņa brāļa Ešeka bērni bija: Ulams, viņa pirmdzimušais, Jeūs, otrais, un Elivelets, trešais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Un Ulama bērni bija stipri varoņi, kas stopu vilka, un tiem bija daudz bērnu un bērnu bērni, simts piecdesmit; tie visi bija Benjamina bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Un viss Israēls tapa uzrakstīts, un redzi, tie ir rakstīti Israēla ķēniņu grāmatā. Un Jūda tapa aizvests uz Bābeli savu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Proti tie pirmie iedzīvotāji, kas savā īpašumā, savās pilsētās dzīvoja: Israēls, priesteri un Leviti un (dieva nama) apkalpotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Un Jeruzālemē dzīvoja no Jūda bērniem un no Benjamina bērniem un no Efraīma un Manasus bērniem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utajus, Amjuda dēls, - tas bija Omra dēls, tas Imra, tas Banus dēls, - no Pereca, Jūda dēla, bērniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Un no Šiloniešiem: Azajus, tas pirmdzimušais, un viņa bērni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Un no Zerus bērniem: Jeguēls un viņa brāļi, sešsimt un deviņdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Un no Benjamina bērniem: Šalus, Mešulama dēls, tas bija Odavijas, tas Aznuas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Un Jēneja, Jeroama dēls, un Elus, Uzus dēls, Mikrus dēla dēls, un Mešulams, Šefatijas dēls, tas bija Reguēļa, tas Jebneja dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Un viņa brāļi pēc viņu radiem, deviņsimt piecdesmit un seši. Visi tie vīri bija virsnieki pār saviem tēvu namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Un no priesteriem: Jedaja un Jojaribs un Jaķins,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Un Azarija, Hilķijas dēls, tas bija Mešulama, tas Cadoka, tas Merajota, tas Aķitoba dēls, Dieva nama priekšnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Un Adaja, Jeroama dēls, tas bija Pašhura, tas Malhijas dēls, un Maēzajus, Adiēļa dēls, tas bija Jakzera, tas Mešulama, tas Mezilemita, tas Immera dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Un viņu brāļi, savu tēvu namu virsnieki, tūkstoš septiņsimt un sešdesmit, stipri varoņi pie Dieva nama kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Un no Levitiem, no Merarus bērniem: Šemaja, Hašuba dēls, tas bija Azrikama, tas Hašabijas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Un Bakbakars, Ķeres un Galals un Matanija, Mihas dēls, tas bija Sihrus, tas Asafa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Un Obadija, Šemajas dēls, tas bija Ģelala, tas Jedutuna dēls un Bereķija, Asafa dēls, Elkanas dēla dēls, kas dzīvoja Netofatiešu ciemos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Un vārtu sargi bija: Šalums un Akubs un Talmons un Aķimans ar saviem brāļiem, un Šalums bija par virsnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Un līdz šim šie ir pie ķēniņa vārtiem pret rītiem vārtu sargi Levja bērnu lēģeriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Un Šalums, Kores dēls, tas bija AbiAsafa, tas Koraha dēls, un viņa brāļi no viņa tēva nama, tie Koraha dēli, bija pēc savas klausības sliekšņu sargi dzīvoklī, kā viņu tēvi bija bijuši durvju sargi Tā Kunga lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Un Pinehas, Eleazara dēls, bija citkārt tiem par virsnieku; Tas Kungs bija ar to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zaharija, Me Šelemijas dēls, bija par vārtu sargu pie saiešanas telts durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Par sliekšņu sargiem iecelti bija pavisam divsimt divpadsmit; tie bija pierakstīti savos ciemos. Dāvids un Samuēls, tas redzētājs, tos tai amatā bija iecēluši uz ticību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Ka tie ar saviem bērniem sargātu Tā Kunga namu, telts nama vārtus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Un tie sargi stāvēja pret tiem četriem vējiem, pret rītiem, pret vakariem pret ziemeli un pret dienasvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Un viņu brāļiem ciemos katru septīto dienu bija jānāk kalpot ar tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Jo šie četri sargu virsnieki, tie Leviti, bija iecelti uz ticību pār Dieva nama kambariem un mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Un tie palika caurām naktīm ap Dieva namu, jo tiem tas bija jāapsargā un ik rītu vārti jāatdara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Un citi no tiem bija iecelti pār dievkalpošanas rīkiem, ko tie pēc skaita ienesa un pēc skaita iznesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Un citi no tiem bija iecelti pār traukiem un pār visiem svētiem traukiem, un pār tiem kviešu miltiem un vīnu un eļļu un vīraku un dārgām zālēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Un no priesteru bērniem citi sataisīja smaržīgu svaidāmu eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Un Matatijam no Levitiem, kas bija Šaluma, Koraha dēla, pirmdzimušais, pannu darbs bija uzticēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Un no Kehāta bērniem, viņu brāļiem, citiem bija uzticēta maizes uzlikšana, ka tā ik svētdienas taptu uzlikta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Un šie, kas bija dziedātāji, Levitu tēvu namu virsnieki, bija atsvabināti no mantu kambariem, jo tie bija kalpošanā dienām naktīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Šie ir Levitu tēvu namu virsnieki pēc saviem radiem, virsnieki. Šie dzīvoja Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Bet Gibeonā dzīvoja Jejels, Gibeona tēvs, un viņa sievai bija vārds Maēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Un viņa pirmdzimušais dēls bija Abdons, tad Curs un Ķis un Baāls un Ners un Nadabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Un Ģedors un Aājus un Zaharija un Miklots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Un Miklots dzemdināja Zimeamu; šie arīdzan dzīvoja blakām saviem brāļiem Jeruzālemē pie saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ners dzemdināja Ķisu, un Ķis dzemdināja Saulu, un Sauls dzemdināja Jonatānu un Malķizuū un Abinadabu un Ezbaālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Un Jonatāna dēls bija Meribaāls, un Meribaāls dzemdināja Mihu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Un Mihas bērni bija Pitons un Meleks un Taērijus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Un Ahazs dzemdināja Jaēru, un Jaērus dzemdināja Alemetu un Asmavetu un Zimru, un Zimrus dzemdināja Mocu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Un Mocus dzemdināja Bineū, tam dēls bija Revaja, tam Eleazus, tam Acels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Un Acelim bija seši dēli un šie ir viņu vārdi: Asrikams, Bokrus un Jezmaēls un Zearija un Obadija un Hanans, - šie ir Aceļa bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Un Fīlisti karoja pret Israēli, un Israēla vīri bēga no Fīlistiem un krita nokauti uz Ģilboas kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Bet Fīlisti lauzās uz Saulu un uz viņa dēliem, un Fīlisti nokāva Jonatānu un Abinadabu un Malķizuū, Saula dēlus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Un kaušana bija briesmīga pret Saulu, un strēlnieki viņu aizņēma ar saviem stopiem, ka tam bailes uznāca no tiem strēlniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Tad Sauls sacīja uz savu bruņu nesēju: izvelc savu zobenu un nodur mani ar to, ka šie neapgraizītie nenāk un mani neliek smieklā. Bet viņa bruņu nesējs negribēja, jo viņš bijās ļoti. Tad Sauls ņēma zobenu un metās uz to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Kad nu viņa bruņu nesējs redzēja, ka Sauls bija nomiris, tad viņš arī metās uz zobenu un nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tā Sauls nomira un viņa trīs dēli un viss viņa nams nomira kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Kad nu visi Israēla ļaudis ielejā redzēja, ka tie bēga un ka Sauls un viņa dēli bija nomiruši, tad tie atstāja savas pilsētas un bēga, un Fīlisti nāca un tanīs dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Un otrā dienā Fīlisti nāca, tos nokautos aplaupīt, un atrada Saulu un viņa dēlus guļam uz Ģilboas kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Un tie tam novilka drēbes un paņēma viņa galvu un viņa bruņas, un tos sūtīja pa Fīlistu zemi apkārt par priecīgu ziņu saviem elkiem un ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Un tie nolika viņa bruņas sava dieva namā un viņa galvu tie piekala Dagona namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kad nu visi ļaudis Jabesā Gileādā dzirdēja visu, ko Fīlisti Saulam bija darījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Tad visi spēcīgie vīri cēlās un paņēma Saula miesas un viņa dēlu miesas un tās pārnesa uz Jabesu un apraka viņu kaulus Jabesā apakš ozola, un gavēja septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Tā Sauls nomira savos grēkos, ko bija darījis pret To Kungu, Tā Kunga vārda dēļ, ko viņš neturēja, arī ka viņš to zīlnieci bija vaicājis un meklējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Un nebija vaicājis To Kungu; tāpēc viņš tam lika mirt un piešķīra valstību Dāvidam, Isajus dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Un viss Israēls sapulcinājās pie Dāvida Hebronē un sacīja: redzi, mēs esam tavi kauli un tava miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Jau sen, kamēr Sauls bija par ķēniņu, tu Israēli esi izvadījis un ievadījis, un Tas Kungs, tavs Dievs, uz tevi sacījis: tev būs manus Israēla ļaudis ganīt un tapt par valdnieku pār maniem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Un visi Israēla vecaji nāca pie ķēniņa Hebronē, un Dāvids ar tiem derēja derību Hebronē Tā Kunga priekšā. Un tie svaidīja Dāvidu par ķēniņu pār Israēli, pēc Tā Kunga vārda caur Samuēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Tad Dāvids un viss Israēls nogāja uz Jeruzālemi (šī ir Jebuza), un tur Jebusieši bija tās zemes iedzīvotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Un Jebuzas iedzīvotāji sacīja uz Dāvidu: te tu netiksi iekšā. Bet Dāvids uzņēma Ciānas pili, - šī ir Dāvida pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Tad Dāvids sacīja: kas pirmais Jebusiešus kaus, tas būs par virsnieku un lielkungu. Tad Joabs, Cerujas dēls, visupirmais tika augšā un palika par virsnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Un Dāvids dzīvoja tai pilī, tāpēc to sauca par Dāvida pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Un viņš uztaisīja to pilsētu visapkārt, no Millus iesākot visapkārt; bet Joabs pameta dzīvus, kas pilsētā atlikās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Un Dāvids auga augumā un Tas Kungs Cebaot bija ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Un šie ir Dāvida varoņu virsnieki, kas viņa valstībā stipri pie viņa turējās ar visu Israēli, viņu celt par ķēniņu pēc Tā Kunga vārda uz Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Un šis ir Dāvida varoņu skaits: Jazabeams, Akmona dēls, tas augstākais no tiem trīsdesmit; viņš pacēla savu šķēpu pret trīs simtiem, kamēr tos nokāva vienā reizē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Un pēc viņa bija Eleazars, Dodus dēls, Aoka dēla dēls, tas bija viens no tiem trim varoņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Viņš bija pie Dāvida PasDamimā, kad Fīlisti tur bija sapulcējušies karā; un tur bija druvas gabals ar miežiem, un tie ļaudis bēga no Fīlistiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Tad tie nostājās pašā tīruma vidū un to aizstāvēja un kāva Fīlistus, un Tas Kungs deva lielu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Un trīs no tiem trīsdesmit virsniekiem nogāja pie Dāvida uz to akmens kalnu Adulama alā. Un Fīlistu karaspēks bija apmeties Refaīm ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Un Dāvids bija to brīdi pils kalnā, un Fīlisti bija karavīrus ielikuši Bētlemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Un Dāvidam iekārojās un viņš sacīja: kas man dos ūdeni dzert no akas pie Bētlemes vārtiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Tad tie trīs izlauzās caur Fīlistu lēģeri un smēla ūdeni no akas pie Bētlemes vārtiem, un ņēma un atnesa to pie Dāvida. Bet Dāvids to negribēja dzert, bet to izlēja Tam Kungam');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Un sacīja: lai Dievs mani pasargā, ka es to būtu darījis un šo vīru asinis dzēris par viņu dzīvību, jo tie savu dzīvību netaupīdami to atnesuši; un viņš to negribēja dzert. To darīja šie trīs varoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Un Abizajus, Joaba brālis, bija arī par virsnieku pār trim; un tas pacēla savu šķēpu un nokāva trīs simtus. Un tam bija slava starp tiem trim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Starp šiem otriem trim viņš bija jo lielā godā, un viņš tiem bija par virsnieku, bet tos pirmajus trīs viņš nepanāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, Jojadas dēls, stipra vīra dēls, kas lielus darbus darījis, no Kabceēles, tas kāva divus stiprus Moabiešu lauvas, un nogāja un kāva vienu lauvu pašā alā sniega laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Viņš nokāva arī vienu Ēģiptes vīru, vīru pieci olektis garu, un tam Ēģiptietim bija šķēps rokā kā riestava; bet šis tam piegāja ar zizli un izrāva to šķēpu no tā ēģiptieša rokas un to nokāva ar viņa paša šķēpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'To darīja Benaja, Jojadas dēls, un šis bija slavens starp tiem trim varoņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Un viņš bija tas augstākais starp trīsdesmit, bet tos trīs (pirmajus) viņš nepanāca. Un Dāvids to iecēla par savu padomnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Un karaspēka varoņi bija: Azaēls, Joaba brālis; Elanans, Dodus dēls, no Bētlemes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Zamots no Aroras, Elecs no Pelonas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Īrus, Ikeša dēls, no Tekoas; Abiēzers no Antotas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Zibekajus, Uzata dēls, Ilajus, Aoka dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Makarajus no Retovas; Eleds, Baēnas dēls, no Netofas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itajus, Ribaja dēls, no Ģibejas Benjamina bērnos; Benaja no Pirgatoas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Urajus no Gaāša upēm; Abiēls no Arbatas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmavets no Baērumas; Elijabus, no Zaālbonas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'No Azema bērniem no Ģizonas bija: Jonatāns, Zages dēls no Araras;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahijams, Zakara dēls, no Araras; Elivals, Ura dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefers no Maķeras; Ahijus no Pelonas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Ecrus no Karmela; Naērajus, Azbajus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joēls Nātana brālis; Mibears, Agra dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Celeķs no Amona; Naķerajus no Berotas, bruņu nesējs Joabam, Cerujas dēlam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Īrus, Jetrus dēls, Gārebs, Jetrus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Ūrija, tas Etietis; Zabads, Aķelaja dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adinus, Zizus dēls, tas Rūbenietis, Rūbeniešu virsnieks, un pie viņa bija vēl trīsdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanans, Maēkas dēls, un Jehošafats no Matonas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzija no Astras; Šamus un Jajels, Otama dēli, no Aroēras;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediaēls, Zimrus dēls, un Joūs, viņa brālis, no Ticas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliēls no Maēvas, un Jeribajus un Jozavijas, Elnaāma dēli; un Jetmus no Moaba;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliēls un Abeds un Jaēziēls no Mecobajas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Un šie ir, kas pie Dāvida nāca uz Ciklagu, kad tas vēl mita svešumā Saula, Ķisa dēla, pēc. Un tie bija arīdzan no tiem varoņiem, kara palīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Stopu nesēji, akmeņu metēji ar labo un ar kreiso roku un bultu šāvēji no stopa. Tie bija no Saula brāļiem, no Benjamina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Tie pirmie bija Aķiēzers un Joas, Zaāmas bērni no Ģibeas, tad Jeziēls un Pelecs, Asmaveta bērni, un Barakus un Jeūs no Antotas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Un Jezmaja no Gibeonas bija jo varens starp tiem trīsdesmit un pār tiem trīsdesmit. Un Jeremija un Jaēziēls un Jehohanans un Jozabats no Ģederas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eleūzajus un Jerimots un Bealija un Samarija un Zevataja no Aravas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkanus un Jezija un Azareēls un Joēzers un Jazabeams, Koraha dēli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Un Joēlus un Zabadija, Jeroama dēli, no Ģedoras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'No Gada bērniem arīdzan Dāvidam tai pilskalnā tuksnesī piekrita vareni karavīri, priekšturamu bruņu un šķēpu nesēji, no izskata kā lauvas un čakli kā stirnas pa kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Tas pārākais bija Ezers, otrais Obadija, trešais Elijabs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Ceturtais Mazmanus, piektais Jeremija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Sestais Atajus, septītais Eliēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Astotais Jehohanans, devītais Ebsabads,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Desmitais Jeremija, vienpadsmitais Makbanajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Šie bija no Gada bērniem, kara virsnieki, tie mazākie viens par simtu, tie lielākie par tūkstoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Šie ir tie, kas pār Jardāni pārgāja pirmā mēnesī, kad tā bija pilna līdz pašiem krastiem, un tie izdzina visus ielejas ļaudis pret rītiem un pret vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'No Benjamina un Jūda bērniem nāca arīdzan pie Dāvida uz pilskalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Un Dāvids tiem izgāja pretī un bildināja un uz tiem sacīja: ja jūs ar miera prātu pie manis esat nākuši, man palīdzēt, tad man būs viena sirds ar jums; bet ja jūs mani ar viltu gribat nodot maniem ienaidniekiem, un tomēr netaisnības pie manis nav, tad lai mūsu Dievs to redz un soda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Bet Tas Gars nāca uz Amaaju, to virsnieku pār trīsdesmit (un tas sacīja): tev mēs piederam, Dāvid un ar tevi mēs būsim, tu Isajus dēls: miers, miers lai ir ar tevi un miers ar taviem palīgiem, jo tavs Dievs ir tavs palīgs. Tad Dāvids tos pieņēma un tos iecēla par karapulku virsniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Arī no Manasus Dāvidam piekrita, kad tas ar Fīlistiem nāca pret Saulu karot, bet šiem nepalīdzēja; jo Fīlistu lielkungi pēc sava padoma to atlaida sacīdami: viņš pāries pie sava kunga Saula un mūsu galvas kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Kad viņš gāja uz Ciklagu, tad tam no Manasus piekrita Adnaks un Jozabats un Jediaēls un Mikaēls un Jozabads un Elijus un Ciltajus, virsnieki pār Manasus tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Un tie Dāvidam palīdzēja pret (Amalekiešu) sirotājiem, jo tie visi bija stipri varoņi un palika par kara virsniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Un ikdienas Dāvidam piekrita palīgi, tiekams tas karaspēks palika tik liels kā Dieva karaspēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Un šis ir to galvu skaits, kas bija apbruņojušies uz karu un nākuši pie Dāvida uz Hebroni, ka viņam piešķirtu Saula valstību pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Jūda bērnu, kas priekšturamās bruņas un šķēpus nesa, bija seši tūkstoši un astoņsimt uz karu gatavi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'No Sīmeana bērniem bija septiņi tūkstoši un simts stipri kara varoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'No Levja bērniem četrtūkstoš un sešsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Un Jojadus, Ārona bērnu valdnieks, un ar to trīs tūkstoši un septiņsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Un Cadoks, jauns stiprs varonis, un no viņa tēva nama bija divdesmit divi virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Un no Benjamina bērniem bija Saula brāļu trīs tūkstoši; jo līdz tam laikam vēl viss vairums turējās pie Saula nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Un no Efraīma bērniem divdesmit tūkstoši un astoņsimt stipri varoņi, vīri, kam bija liela slava savu tēvu namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Un no Manasus puscilts astoņpadsmit tūkstoši, kas ar vārdu tika noteikti, ka nāktu, Dāvidu celt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Un no Izašara bērniem, kas bija gudri noprast, kas Israēlim katrā laikā bija darāms; šo virsnieku bija divsimt, un visi viņu brāļi darīja pēc viņu vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'No Zebulona, kas izgāja karā apbruņoti ar visādām karabruņām, bija piecdesmit tūkstoši, savā kārtā stāvēdami ar drošu sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Un no Naftalus bija tūkstotis virsnieki un ar tiem trīsdesmit septiņi tūkstoši ar priekšturamām bruņām un šķēpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Un no Dana bērniem uz karu gatavi divdesmit un astoņi tūkstoši un sešsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Un no Ašera, kas izgāja karā, uz kaušanos gatavi, četrdesmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Un no PārJardānes, no Rūbena un Gada bērniem un no Manasus puscilts ar visādām kara bruņām, simts un divdesmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Visi šie karavīri, ar drošu sirdi pēc kārtas pulkos stāvēdami, nāca uz Hebroni, Dāvidu celt par ķēniņu pār visu Israēli. Un arī visiem citiem no Israēla bija vienāda sirds, Dāvidu celt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Un tie tur bija pie Dāvida trīs dienas, ēda un dzēra, jo viņu brāļi priekš tiem bija sataisījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Un kas tuvu pie tiem dzīvoja līdz Īsašaram un Zebulonam un Naftalum, tie nesa maizi uz ēzeļiem un kamieļiem un zirgēzeļiem un uz vēršiem, miltu ēdienus, vīģu un rozīņu raušus un vīnu un eļļu un vēršus un avis lielā pulkā; jo līksmība bija iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Un Dāvids aprunājās ar tiem virsniekiem pār tūkstošiem un pār simtiem un ar visiem lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Un Dāvids sacīja uz visu Israēla draudzi: ja jums šķiet labi esam un ja tas ir no Tā Kunga mūsu Dieva, tad sūtīsim visur apkārt pie saviem citiem brāļiem visās Israēla valstīs un pie tiem priesteriem un Levitiem savās pilsētās un viņu apgabalos, ka tie pie mums sapulcējās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Un atvedīsim sava Dieva šķirstu atkal pie sevis; jo Saula laikā mēs to neesam meklējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Tad visa draudze sacīja, lai tā darot, jo šī valoda patika visiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Tad Dāvids sapulcināja visu Israēli no Ēģiptes Šihoras, līdz kur nāk uz Hamatu, atvest Dieva šķirstu no KiriatJearimas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Tad Dāvids cēlās ar visu Israēli uz Baālu, tā ir KiriatJearima iekš Jūda, no turienes atvest Dieva Tā Kunga šķirstu, Tā Kunga, kas mīt pār ķerubiem, kur viņa vārds top piesaukts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Un tie veda Dieva šķirstu uz jauniem ratiem no Abinadaba nama, un Uza un Ahijus vadīja tos ratus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Un Dāvids un viss Israēls līksmojās Dieva priekšā ar visu spēku, ar dziesmām un ar koklēm un somastabulēm un bungām un pulkstenīšiem un bazūnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Bet kad tie nāca līdz Ķidona klonam, tad Uza izstiepa savu roku, to šķirstu turēt, jo tie vērši (to) gāza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Tad Tā Kunga dusmas iedegās pret Uzaju, un viņš to sita par to, ka tas savu roku bija izstiepis pēc tā šķirsta, un tas tur nomira Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Un Dāvids noskuma, ka Tas Kungs tādu robu robojis, Uzu sizdams, un to vietu nosauca PerecUza (Uzas robs) līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Un Dāvids bijās Dievu tai dienā un sacīja: kā lai es Dieva šķirstu atvedu pie sevis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Un Dāvids neveda to šķirstu pie sevis Dāvida pilī, bet to nolika Gatieša ObedEdoma namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Tā Dieva šķirsts palika pie ObedEdoma viņa namā trīs mēnešus, un Tas Kungs svētīja ObedEdoma namu un visu, kas tam bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Un Īrams, Tirus ķēniņš, sūtīja vēstnešus pie Dāvida un ciedru kokus un mūrniekus un būvmeistarus, viņam uztaisīt namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Un Dāvids manīja, ka Tas Kungs viņu bija apstiprinājis par ķēniņu pār Israēli; jo viņa valstība tapa varen paaugstināta viņa Israēla ļaužu labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Un Dāvids ņēma vēl vairāk sievu Jeruzālemē un Dāvidam dzima vēl vairāk dēlu un meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Un šie ir to bērnu vārdi, kas viņam piedzima Jeruzālemē: Šamuūs un Zobabs, Nātans un Salamans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Un Jebears un Elizuūs un Elvalets');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Un Nogus un Nevegs un Japius');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Un Elišamus un BaelJadus un Elivalets.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Kad nu Fīlisti dzirdēja, ka Dāvids bija svaidīts par ķēniņu pār visu Israēli, tad visi Fīlisti nāca, Dāvidu meklēt. Un kad Dāvids to dzirdēja, tad viņš tiem izgāja pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Un Fīlisti nāca un izplētās Refaīm ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Tad Dāvids vaicāja Dievam un sacīja: vai man būs iet pret Fīlistiem, un vai tu tos dosi manā rokā? Un Tas Kungs tam sacīja: celies, jo es tos došu tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Un tie gāja uz BaālPracim, un Dāvids tos tur sakāva, un Dāvids sacīja: Dievs aizrāvis manus ienaidniekus caur manu roku, tā kā ūdens rauj. Tādēļ tie nosauca to vietu BaālPracim (rāveju vieta).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Un tie tur pameta savus dievus; un Dāvids pavēlēja, tos sadedzināt ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Bet Fīlisti atkal nāca un apmetās ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Tad Dāvids atkal vaicāja Dievam, un Dievs uz to sacīja: neej aiz viņiem bet ej apkārt ap viņiem, un ej tiem virsū pret tiem raudu kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Un kad tu dzirdēsi soļus rībam raudu koku galotnēs, tad izej uz kaušanos, jo Dievs iziet tavā priekšā, kaut Fīlistu karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Un Dāvids darīja, kā Dievs tam bija pavēlējis; un tie kāva Fīlistu karaspēku no Gibeonas līdz Gazerai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Tā Dāvida slava izpaudās pa visām zemēm, un Tas Kungs lika bailēm no viņa uziet visiem pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Un Dāvids uztaisīja sev namus Dāvida pilsētā un sataisīja vietu Dieva šķirstam un tam uzcēla telti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tad Dāvids sacīja: neviens lai nenes Dieva šķirstu kā vien Leviti, jo tos Tas Kungs ir izredzējis, nest Dieva šķirstu un viņam kalpot mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Un Dāvids sapulcēja visu Israēli uz Jeruzālemi, novest Dieva šķirstu savā vietā, ko viņš tam bija sataisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Un Dāvids sasauca Ārona bērnus un Levitus:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'No Kehāta bērniem virsnieku Uriēli ar saviem brāļiem, simt un divdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'No Merarus bērniem virsnieku Asaju ar saviem brāļiem, divsimt un divdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'No Ģerzoma bērniem virsnieku Joēli ar saviem brāļiem, simt un trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'No Elicafana bērniem virsnieku Šemaju ar saviem brāļiem, divsimt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'No Hebrona bērniem virsnieku Eliēli ar saviem brāļiem, astoņdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'No Uziēļa bērniem virsnieku Aminadabu ar saviem brāļiem, simt un divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Un Dāvids aicināja priesterus Cadoku un Abjataru, un Levitus Uriēli, Azaju un Joēli, Šemaju un Eliēli un Aminadabu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Un uz tiem sacīja: jūs Levitu tēvu namu virsnieki, svētījaties paši ar saviem brāļiem un atvedat Tā Kunga, Israēla Dieva, šķirstu, kur es tam vietu sataisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Jo viņu reiz, kad jūs klāt nebijāt, Tas Kungs, mūsu Dievs, izlauza robu mūsu starpā, tāpēc ka to nemeklējām, kā pienācās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Tad tie priesteri un Leviti svētījās, atvest Tā Kunga, Israēla Dieva, šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Un Levitu bērni nesa Dieva šķirstu, itin kā Mozus bija pavēlējis pēc Tā Kunga vārda, ar kārtīm uz saviem kamiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Un Dāvids pavēlēja Levitu virsniekiem sarīkot savus brāļus, tos dziedātājus, ar spēlēm, ar soma stabulēm, ar koklēm un pulkstenīšiem, skaņi dziedāt un balsi pacelt ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Tad Leviti iecēla Hemanu, Joēļa dēlu, un no viņa brāļiem Asafu, Bereķijas dēlu, un no Merarus bērniem, saviem brāļiem, Etanu, Kuzajas dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Un ar šiem savus brāļus no otras kārtas, Zahariju, Benu un Jaēziēli un Zemiramotu un Jejeēli un Unnu, Elijabu un Benaju un Maāseju un Matitiju un Eliveleju un Mikneju un ObedEdomu un Jeīeli, tos vārtu sargus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Un dziedātāji bija Hemans, Asafs un Etans, skandinādami ar vara pulkstenīšiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Un Zaharija un Aziēls un Zemiramots un Jeīels un Unnus un Elijabs un Maāseja un Benaja ar smalki skanīgām soma stabulēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Un Matitija un Elivelejus un Mikneja un ObedEdoms un Jeīels un Azazija, priekšā dziedādami ar astoņu stīgu koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Un Kananaja bija Levitu vadonis, (dziesmas) uzņemt, viņš tos mācīja uzņemt, jo viņš bija saprātīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Un Bereķija un Elkanus bija šķirsta vārtu sargi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Un Zabanija un Jehošafats un Netaneēls un Amasajus un Zaharija un Benaja un Eliēzers, tie priesteri, pūta trumetes Dieva šķirsta priekšā, un ObedEdoms un Jeķija bija šķirsta vārtu sargi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Tā Dāvids un Israēla vecaji un virsnieki pār tūkstošiem nogāja, atvest Tā Kunga derības šķirstu no ObedEdoma nama ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Un kad Dievs tiem Levitiem palīdzēja, kas Tā Kunga derības šķirstu nesa, tad tie upurēja septiņus vēršus un septiņus aunus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Un Dāvids bija ģērbies nātnu svārkos un tāpat visi Leviti, kas to šķirstu nesa, un tie dziedātāji un Kananija, tas dziedātāju vadonis; Dāvidam bija arī linu plecusega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Tā viss Israēls nesa augšām Tā Kunga derības šķirstu ar gavilēšanu un bazūņu skaņu un ar trumetēm un ar pulkstenīšiem, un spēlēja ar soma stabulēm un koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Un kad Tā Kunga derības šķirsts nonāca Dāvida pilī, tad Mikale, Saula meita, skatījās pa logu ārā un redzēja ķēniņu Dāvidu dejojam un spēlējam, un tā to nicināja savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Un tie atveda Dieva šķirstu un to nolika tai teltī, ko Dāvids tam bija uzcēlis, un upurēja dedzināmos upurus un pateicības upurus Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Un kad Dāvids tos dedzināmos upurus un pateicības upurus bija pabeidzis, tad viņš tos ļaudis svētīja Tā Kunga Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Un viņš izdalīja ikkatram no Israēla, tā vīram kā sievai, pa klaipam maizes un pa gabalam gaļas un pa mēram vīna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Un kādus no Levitiem viņš nolika par kalpotājiem priekš Tā Kunga šķirsta, godāt, teikt un slavēt To Kungu, Israēla Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asafs bija par virsnieku un otrs pēc viņa Zaharija; Jeīls, Zemiramots, Jeķiēls un Matitija un Elijabs un Benaja un ObedEdoms un Jeīels ar spēlēm, somastabulēm un koklēm, un Asafs skandināja ar pulkstenīšiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Un Benaja un Jeaziēls, tie priesteri, pūta vienmēr trumetes Dieva derības šķirsta priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Tai dienā Dāvids pirmo reiz deva šo dziesmu, To Kungu slavēt, caur Asafu un viņa brāļiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Teiciet To Kungu, piesauciet Viņa vārdu, dariet zināmus starp tautām Viņa darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Dziedājiet Viņam, slavējiet To ar dziesmām, pārdomājiet visus Viņa brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Slavējiet viņa svēto vārdu, lai sirds priecājās tiem, kas To Kungu meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Vaicājiet pēc Tā Kunga un pēc Viņa stipruma, meklējiet Viņa vaigu bez mitēšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Pieminiet Viņa brīnumus, ko Viņš darījis, Viņa brīnuma zīmes un Viņa mutes tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Tu, Israēl, Viņa kalpa dzimums, jūs Jēkaba bērni, Dieva izredzētie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Viņš ir Tas Kungs, mūsu Dievs, Viņa tiesas iet pār visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Pieminiet mūžīgi Viņa derību, to vārdu, ko Viņš iecēlis tūkstošiem dzimumiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Ko Viņš derējis ar Ābrahāmu un ko zvērējis Īzakam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'To Viņš arī Jēkabam iecēlis par likumu un Israēlim par mūžīgu derību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Sacīdams: tev Es došu Kanaāna zemi, jūsu mantības daļu; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Kad jūs bijāt mazs pulciņš, ne daudz, un svešinieki iekš tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Un tie staigāja no vienas tautas pie otras, un no vienas valsts pie citiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Viņš nekam neļāva tos spaidīt, Viņš arī ķēniņus pārmācīja viņu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Neaizskariet Manus svaidītos, un nedariet ļauna Maniem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Dziedājiet Tam Kungam, visa zeme, sludinājiet ikdienas Viņa pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Teiciet pagānu starpā Viņa godu, visu tautu starpā Viņa brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Jo Tas Kungs ir liels un ļoti slavējams un bijājams pār visiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Jo visi pagānu dievi ir elki, bet Tas Kungs debesis radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Augstība un gods ir Viņa priekšā, spēks un līksmība ir Viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Dodiet Tam Kungam, jūs ļaužu tautas, dodiet Tam Kungam godu un spēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Dodiet Tam Kungam Viņa vārda godu, atnesiet dāvanas un nāciet priekš Viņa vaiga, pielūdziet To Kungu svētā glītumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Bīstaties priekš Viņa, visa pasaule; tiešām zeme stāv un nekustās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Lai debess priecājās un lai zeme līksmojās, un lai saka tautu starpā: Tas Kungs ir ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Lai jūra kauc un viss, kas iekš tās ir, lai lauki līksmojās ar visu, kas tur virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Lai gavilē meža koki Tā Kunga priekšā, jo Tas nāk, zemi tiesāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Teiciet To Kungu, jo Viņš ir labs, un Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Un sakāt: atpestī mūs, Dievs, mūsu Pestītājs, un sapulcini mūs un izglāb mūs no pagāniem, ka teicam Tavu svēto vārdu un Tevi augsti slavējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Slavēts lai ir Tas Kungs, Israēla Dievs, mūžīgi mūžam, un visi ļaudis lai saka: Āmen, un lai slavē To Kungu. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Tā viņš tur Tā Kunga derības šķirsta priekšā lika palikt Asafam un viņa brāļiem, vienmēr kalpot tā šķirsta priekšā, ikdienas savā kārtā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Un ObedEdomam ar saviem brāļiem, - to bija sešdesmit un astoņi, ObedEdomam, Jedituna dēlam, un Osam par vārtu sargiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Un priesterim Cadokam un viņa brāļiem, tiem priesteriem, priekš Tā Kunga dzīvokļa uz tā kalna Gibeonā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Tam Kungam upurēt dedzināmos upurus uz dedzināmo upuru altāra vienmēr, rītos un vakaros, tā kā rakstīts Tā Kunga bauslībā, ko viņš Israēlim bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Un ar viņiem bija Hemans un Jedituns un tie citi izredzētie, kas ar vārdiem bija noteikti, To Kungu slavēt, ka Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Un ar šiem Hemans un Jedituns, skandināt ar trumetēm un pulkstenīšiem un ar svētu dziesmu spēlēm, bet Jedituna bērni bija par vārtu sargiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Tā visi ļaudis nogāja ikkatrs savā namā, un Dāvids atgriezās, savu namu sveicināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Un notikās, kad Dāvids savā namā dzīvoja, tad Dāvids sacīja uz pravieti Nātanu: redzi, es dzīvoju ciedru namā, bet Tā Kunga derības šķirsts mīt starp telts deķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Tad Nātans sacīja uz Dāvidu: dari visu, kas ir tavā sirdī, jo Dievs ir ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Bet tai pašā naktī Dieva vārds notika uz Nātanu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Ej un saki manam kalpam Dāvidam: tā saka Tas Kungs: tev nebūs Man namu celt par mājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Jo Es namā neesmu mitis no tās dienas, kad Israēli esmu izvedis, līdz šai dienai, bet Es esmu gājis no telts uz telti un no dzīvokļa uz dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Visu to laiku, kad Es ar visu Israēli esmu staigājis, vai esmu vārdu runājis uz kādu no Israēla soģiem, kam Es pavēlējis Savus ļaudis ganīt, sacīdams: kāpēc jūs Man neuztaisiet ciedru namu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Tad nu saki tā uz Manu kalpu Dāvidu: tā saka Tas Kungs Cebaot: Es tevi esmu ņēmis no ganības, no sīkiem lopiem, lai tu Maniem Israēla ļaudīm būtu par valdnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Un Es ar tevi esmu bijis visur, kur tu esi gājis, un esmu izdeldējis visus tavus ienaidniekus tavā priekšā un tev cēlis augstu vārdu, kā tiem lieliem kungiem vārds ir virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Un Saviem Israēla ļaudīm Es esmu gādājis vietu un tos dēstījis, ka tie savā vietā dzīvo un vairs netop šaubīti, un netikli ļaudis tos vairs nespaida, kā senāk,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Un no tās dienas, kad Es soģus iecēlu pār Saviem Israēla ļaudīm. Un visus tavus ienaidniekus Es esmu pazemojis un tev daru zināmu, ka Tas Kungs tev cels namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Un notiks, kad tavs laiks būs pagājis, kad tu pie saviem tēviem iesi, tad Es pamodināšu tavu dzimumu pēc tevis, kas būs no taviem bērniem, un apstiprināšu viņa valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Tas Man uztaisīs namu un Es apstiprināšu viņa goda krēslu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Es tam būšu par tēvu un tas Man būs par dēlu, un Savu žēlastību Es no viņa neatraušu, kā Es to esmu atrāvis no tā, kas bija tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Bet Es to Manā namā un Manā valstībā iecelšu mūžīgi, ka viņa goda krēsls pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Un kad Nātans pēc visiem šiem vārdiem un pēc šīs parādīšanas ar Dāvidu bija runājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Tad ķēniņš Dāvids nāca un palika Tā Kunga priekšā un sacīja: kas es esmu, Kungs Dievs, un kas ir mans nams, ka Tu mani līdz šejienei esi vadījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Un tas Tev vēl bijis maz, ak Dievs! Bet Tu vēl uz Sava kalpa namu esi runājis par nākošiem ilgiem laikiem un mani esi uzlūkojis pēc cilvēka vīzes, Tu Dievs Kungs augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Un ko lai Dāvids vēl uz Tevi saka par Tava kalpa godību? Bet Tu gan pazīsti Savu kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Kungs, Tava kalpa labad un pēc Tavas sirds Tu visas šās lielās lietas esi darījis, un visas šās augstās lietas darījis zināmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Kungs, neviens nav kā Tu, un neviena dieva nav, kā Tu vien, pēc visa, ko mēs savām ausīm esam dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Un kur gan ir kāda tauta virs zemes kā Tavi Israēla ļaudis, ko Dievs gājis atpestīt Sev par ļaudīm, un Sev celt lielu un bijājamu vārdu, pagānus izdzīdams Savu ļaužu priekšā, ko Tu no Ēģiptes izglābis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Un Tu Savus Israēla ļaudis Sev esi cēlis par tautu mūžīgi, un Tu Kungs tiem esi palicis par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Tad nu, Kungs, lai tas vārds, ko Tu esi runājis par Savu kalpu un par viņa namu, tiešām tā notiek mūžīgi, un dari, kā Tu esi runājis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Tiešām, lai tā notiek, ka Tavs vārds top paaugstināts mūžīgi, lai saka: Tas Kungs Cebaot, Israēla Dievs, ir Dievs pār Israēli, un Tava kalpa Dāvida nams lai pastāv Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Jo tu, mans Dievs, sava kalpa ausi esi atvēris, ka tu tam gribi namu uztaisīt, tādēļ tavs kalps ir iedrošinājies pielūgt tava vaiga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Tad nu, Kungs, Tu esi Dievs, un esi runājis uz Savu kalpu šo labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Un nu tas ir Tavs prāts, svētīt Sava kalpa namu, ka tas mūžīgi paliek Tavā priekšā; jo ko Tu, Kungs, svētī, tas paliek svētīts mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Un notikās pēc tam, ka Dāvids kāva Fīlistus un tos pārvarēja un uzņēma Gatu un viņas ciemus no Fīlistu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Un viņš kāva arī Moabiešus, tā ka Moabieši Dāvidam palika par kalpiem un nesa dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Dāvids kāva arī HadadEzeru, Cobas ķēniņu, Hamatā, kad šis nogāja savu varu atkal uzcelt pie Eifrat upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Un Dāvids tiem atņēma tūkstoš ratus un septiņtūkstoš jātniekus un divdesmit tūkstoš kājniekus, un Dāvids darīja visus zirgus tizlus un atlicināja no tiem simts zirgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Un Sīrieši no Damaskus nāca HadadEzeram, Cobas ķēniņam, palīgā, bet Dāvids kāva no Sīriešiem divdesmit divi tūkstoš vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Un Dāvids lika (karavīrus) Damaskū Sīrijā, un Sīrieši Dāvidam palika par kalpiem un nesa dāvanas; jo Tas Kungs palīdzēja Dāvidam visur, kur viņš gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Un Dāvids ņēma tās zelta priekšturamās bruņas, kas HadadEzera kalpiem bija, un tās pārveda uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Dāvids paņēma arī ļoti daudz vara no Tibeatas un no Kunas, HadadEzera pilsētām; no tā Salamans taisīja to vara jūru un tos stabus un tos vara traukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Kad nu Tojus, Hamatas ķēniņš, dzirdēja, ka Dāvids bija kāvis visu HadadEzera, Cobas ķēniņa, karaspēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Tad viņš savu dēlu Adoramu sūtīja pie ķēniņa Dāvida, vaicāt pēc viņa labklāšanās un viņam pateikt, kā tas pret HadadEzeru bija karojis un viņu kāvis, jo HadadEzeram bija karš pret Toju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Un visus zelta un sudraba un vara traukus, tos ķēniņš Dāvids svētīja Tam Kungam līdz ar to sudrabu un zeltu, ko viņš no visām tautām bija paņēmis, no Edoma un Moaba un no Amona bērniem, no Fīlistiem un no Amalekiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abizajus, Cerujas dēls, kāva arīdzan Edomiešus sāls ielejā, astoņpadsmit tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Un viņš lika karavīrus Edomā, un visi Edomieši palika Dāvidam par kalpiem, jo Tas Kungs palīdzēja Dāvidam visur, kurp tas gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Tā Dāvids valdīja pār visu Israēli un nesa tiesu un taisnību visiem saviem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Un Joabs, Cerujas, dēls, bija pār karaspēku, un Jehošafats, Aķiluda dēls, bija kanclers,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Un Cadoks, Aķitoba dēls, un Abimeleks, Abjatara dēls, bija priesteri, un Zauzus bija skrīveris,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Un Benaja, Jojadas dēls bija pār tiem Krietiem un Plietiem, un Dāvida bērni bija tie pirmie pie ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Un notikās pēc tam, ka Nahas, Amona bērnu ķēniņš, nomira, un viņa dēls palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Tad Dāvids sacīja: es darīšu žēlastību pie Anona, Nahasa dēla, jo viņa tēvs žēlastību darījis pie manis. Un Dāvids sūtīja vēstnešus, viņu iepriecināt par viņa tēvu. Tad Dāvida kalpi nāca uz Amona bērnu zemi pie Anona, viņu iepriecināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Bet Amona bērnu lielkungi sacīja uz Anonu: vai Dāvids godina tavu tēvu tavās acīs, ka tas sūtījis pie tevis iepriecētājus? Vai viņa kalpi nav tāpēc pie tevis nākuši, ka zemi izklausa un izposta un izlūko?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Tad Anons ņēma Dāvida kalpus un tiem nodzina bārdu un viņiem nogrieza vienu drēbju pusi līdz gurniem un tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Un tie aizgāja. Un kad nu Dāvidam ziņu deva par tiem vīriem, tad viņš tiem sūtīja pretī, (jo tie vīri bija ļoti apsmieti,) un ķēniņš tiem lika sacīt: paliekat Jērikū, tiekams jūsu bārda atkal būs ataugusi, tad nāciet atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Kad nu Amona bērni redzēja, ka bija palikuši smirdoši Dāvida priekšā, tad Anons un Amona bērni sūtīja tūkstoš sudraba talentus, saderēt ratus un jātniekus no Mezopotamijas, no Maēkas un no Cobas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Un tie sev saderēja trīsdesmit un divi tūkstoš ratus un to ķēniņu no Maēkas un viņa ļaudis, un tie nāca un apmeta lēģeri pret Medbu. Un Amona bērni arīdzan sapulcējās no savām pilsētām un nāca karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Kad nu Dāvids to dzirdēja, tad viņš sūtīja Joabu un visu spēku ar tiem vareniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Un Amona bērni izgāja un nostājās uz kauju priekš pilsētas vārtiem. Bet tie ķēniņi, kas bija nākuši, turējās savrup laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Kad nu Joabs redzēja, ka karš pret viņu taisījās no priekšas un no aizmugures, tad viņš izlasīja kādus no Israēla jauniem vīriem un nostājās Sīriešiem pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Bet tos citus ļaudis viņš deva Abizajam, savam brālim, rokā, un tie nostājās pret Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Un viņš sacīja: ja Sīrieši būs stiprāki nekā es, tad nāc tu man palīgā, bet ja Amona bērni būs stiprāki nekā tu, tad es nākušu tev palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Turies droši un lai stipri cīnāmies priekš saviem ļaudīm un priekš sava Dieva pilsētām, un Tas Kungs lai dara, kā tam patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Un Joabs nāca tuvāki ar saviem ļaudīm, kas pie viņa bija, kauties ar Sīriešiem, bet tie bēga viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Un kad Amona bērni redzēja, kā Sīrieši bēga, tad tie arīdzan bēga priekš Abizajus, viņa brāļa, un tie nāca pilsētā, un Joabs nāca uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Kad nu Sīrieši redzēja, ka Israēla priekšā bija sakauti, tad tie sūtīja vēstnešus un lika nākt tiem Sīriešiem, kas viņpus upes dzīvoja, un Šofahs, HadadEzera kara lielskungs, gāja viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Kad to Dāvidam teica, tad viņš sapulcēja visu Israēli un pārgāja pār Jardāni, un nāca pie tiem un nostājās tiem pretī. Un Dāvids nostājās Sīriešiem pretī uz kauju, un tie ar viņu kāvās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Bet Sīrieši bēga Israēla priekšā, un Dāvids nokāva no Sīriešiem septiņ tūkstoš ratus un četrdesmit tūkstoš kājniekus; viņš nokāva arī Šofahu, to kara lielkungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Kad nu HadadEzera kalpi redzēja, ka Israēla priekšā bija sakauti, tad tie derēja mieru ar Dāvidu un viņam kalpoja. Un Sīrieši negribēja vairs Amona bērniem palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Un kad gads bija pagājis, ap to laiku, kad ķēniņi iziet, tad Joabs izvadīja karaspēku un izpostīja Amona bērnu zemi, un nāca un apmeta lēģeri pret Rabu. Bet Dāvids palika Jeruzālemē. Un Joabs kāva Rabu un to izpostīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Un Dāvids ņēma viņas ķēniņa kroni no viņa galvas un atrada, ka tas svēra vienu talentu zelta, un dārgi akmeņi bija iekš tā, un tas Dāvidam tapa likts galvā; viņš arī izveda ļoti daudz laupījuma no tās pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Un viņš izveda tos ļaudis, kas tur bija, un tos lika apakš zāģiem un apakš dzelzs kuļamiem ruļļiem un apakš dzelzs cirvjiem. Un tā Dāvids darīja visām Amona bērnu pilsētām. Tad Dāvids ar visiem ļaudīm griezās atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Un pēc tam karš cēlās ar Fīlistiem Gazerā; tad Zibekajus, Uzata dēls, kāva Zibaju, kas bija no milžu ļaužu bērniem, un tos pazemoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Un atkal karš cēlās ar Fīlistiem, un Elkanus, Jaīra dēls, kāva Laēmu, Goliata, tā Gatieša, brāli, kam šķēpa kāts bija kā riestava.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Un atkal bija karš Gatā, un tur bija viens liels vīrs, tam bija pa sešiem pirkstiem pie rokām un kājām, divdesmit un četri pavisam, un tas bija arīdzan dzimis no milžu ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Un tas apmēdīja Israēli, bet Jonatāns, Šimejus, Dāvida brāļa, dēls, to nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Tie no milžu ļaudīm bija dzimuši Gatā, un krita caur Dāvida roku un caur viņa kalpu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Un sātans stāvēja pret Israēli un skubināja Dāvidu, skaitīt Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Un Dāvids sacīja uz Joabu un uz tiem ļaužu virsniekiem: ejat, skaitait Israēli no Bēršebas līdz Danai un atnesiet man to skaitu, ka es to zinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Tad Joabs sacīja: lai Tas Kungs pie šiem ļaudīm, kā tie nu ir, simtreiz vairāk pieliek, - vai tie visi, mans kungs un ķēniņ, nav mana kunga kalpi? Kāpēc mans kungs to meklē? Kāpēc tam būs notikt Israēlim par noziegumu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Bet ķēniņa vārds bija stiprāks nekā Joaba. Tāpēc Joabs izgāja un pārstaigāja visu Israēli un nāca atkal uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Un Joabs Dāvidam deva to skaitīto ļaužu skaitu, un viss Israēls bija vienpadsmit reiz simts tūkstoš vīri, kas zobena vilcēji, un no Jūda bija četrsimt un septiņdesmit tūkstoš vīri, kas zobena vilcēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Bet Levi un Benjaminu, tos viņu starpā neskaitīja, jo ķēniņa vārds Joabam bija negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Un šī lieta Dievam nepatika, un viņš sita Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Tad Dāvids sacīja uz Dievu: es esmu ļoti grēkojis, ka to esmu darījis, bet lūdzams, atņem Sava kalpa noziegumu, jo es esmu ļoti aplam darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Un Tas Kungs runāja uz Gadu, Dāvida redzētāju, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Ej un runā uz Dāvidu un saki: tā saka Tas Kungs: trīs lietas Es tev lieku priekšā, izvēlies vienu no tām, ko lai Es tev daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Un Gads nāca pie Dāvida un uz to sacīja: tā saka Tas Kungs: izvēlies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Vai trīs gadus bada laiku, vai trīs mēnešus bēgt no saviem pretiniekiem un no savu ienaidnieku zobena, kas tevi aizņem? - jeb vai trīs dienas Tā Kunga zobenu, tas ir mēri iekš zemes un Tā Kunga maitātāju eņģeli visās Israēla robežās? Tad lūko nu, ko lai es Tam atsaku, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Tad Dāvids sacīja uz Gadu: man ir ļoti bail; lai es jel krītu Tā Kunga rokā, jo Viņa žēlastība ir ļoti liela, bet lai nekrītu cilvēku rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Tad Dievs sūtīja mēri pār Israēli, un no Israēla krita septiņdesmit tūkstoš vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Un Dievs sūtīja eņģeli uz Jeruzālemi, to samaitāt; un kad viņš to samaitāja, tad Tas Kungs uzlūkoja un Viņam bija žēl par to ļaunumu. Un Viņš sacīja uz to eņģeli, to samaitātāju: ir gan, atrauj savu roku. Un Tā Kunga eņģelis stāvēja pie Jebusieša Arnana klona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Kad nu Dāvids savas acis pacēla, tad viņš redzēja Tā Kunga eņģeli starp debess un zemes stāvam, un tam bija izvilkts zobens rokā, kas bija izstiepts pār Jeruzālemi. Tad Dāvids un tie vecaji, ar maisiem apģērbušies, metās uz savu vaigu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Un Dāvids sacīja uz Dievu: vai es tas neesmu, kas pavēlējis, tos ļaudis skaitīt? Es, es esmu grēkojis un ļaunu darījis, - bet šās avis, ko tās darījušas? Ak Kungs, mans Dievs! Lai jel Tava roka ir pret mani un pret mana tēva namu, bet ne pret Taviem ļaudīm par mocību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Un Tā Kunga eņģelis sacīja uz Gadu, lai saka Dāvidam, ka Dāvids lai ietu, Tam Kungam uztaisīt altāri Jebusieša Arnana klonā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Tā Dāvids nogāja pēc Gada vārda, ko tas Tā Kunga Vārdā bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Kad nu Arnans pagriezās, tad viņš redzēja to eņģeli, un viņa četri dēli, kas pie viņa bija, paslēpās, bet Arnans kūla kviešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Un Dāvids nāca pie Arnana, un Arnans skatījās un redzēja Dāvidu un nāca no tā klona un metās Dāvida priekšā uz savu vaigu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Un Dāvids sacīja uz Arnanu: dod man tā klona vietu, ka es tur Tam Kungam taisu altāri; dod man to par pilnu naudu, lai šī mocība mitās no tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Tad Arnans sacīja uz Dāvidu: Ņem to, un dari, mans kungs un ķēniņ, kā tev patīk, redzi, es tos vēršus dodu par dedzināmiem upuriem un šos kuļamos ratus malkai un šos kviešus par ēdamu upuri, - visu to es dodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Bet ķēniņš Dāvids sacīja uz Arnanu: nē, bet es to gribu pirkt par pilnu naudu; jo es negribu ņemt priekš Tā Kunga, kas tev pieder, un upurēt dedzināmo upuri par velti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Tā Dāvids Arnanam par to vietu deva sešsimt sēķeļus zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Un tur Dāvids Tam Kungam uztaisīja altāri un upurēja dedzināmos upurus un pateicības upurus. Un kad tas To Kungu piesauca, tad viņš tam atbildēja caur uguni no debesīm uz dedzināmo upuru altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Un Tas Kungs sacīja uz to eņģeli, lai tas savu zobenu bāž savā makstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Tanī laikā, kad Dāvids redzēja, ka Tas Kungs viņam bija atbildējis uz Arnana, tā Jebusieša, klona, tad viņš tur upurēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Jo Tā Kunga dzīvoklis, ko Mozus tuksnesī bija taisījis, un tas dedzināmo upuru altāris to laiku bija Gibeonas kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Bet Dāvids tur pie tā nevarēja noiet, Dievu meklēt, tā viņš bija iztrūcinājies no Tā Kunga eņģeļa zobena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Un Dāvids sacīja: šeitan būs būt Dieva Tā Kunga namam, un še būs būt dedzināmo upuru altārim priekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Un Dāvids pavēlēja sapulcināt svešiniekus, kas bija Israēla zemē, un viņš saderēja akmeņu cirtējus, apcirst akmeņus Dieva nama būvei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Un Dāvids sakrāja daudz dzelzs priekš naglām pie vārtu durvīm un klamburiem un tik daudz vara, ka nebija sverams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Un ciedru koku, ka nebija skaitāmi, jo Sidonieši un Tirieši veda ciedru kokus Dāvidam lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Un Dāvids sacīja: mans dēls Salamans ir jauns un mazs, un tam namam, kas Tam Kungam jātaisa būs jo lielam būt par slavu un godu visās zemēs, tāpēc es viņam sagādāšu krājumu. Tā Dāvids sakrāja lielu krājumu, pirms nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Tad viņš aicināja savu dēlu Salamanu un tam pavēlēja namu celt Tam Kungam, Israēla Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Un Dāvids sacīja uz Salamanu: mans dēls, man gan bija prātā, celt namu Tā Kunga, sava Dieva, vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Bet Tā Kunga vārds uz mani notika tā: tu esi izlējis daudz asinis, jo tu esi vedis lielus karus; tev nebūs manam vārdam celt namu, jo tu esi izlējis daudz asinis virs zemes manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Redzi, tas dēls, kas tev dzims, būs miera vīrs, jo es viņam došu mieru no visiem viņa ienaidniekiem visapkārt, jo Salamans (miera vīrs) būs viņa vārds, un viņa laikā Israēlim es došu mieru un dusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Tas manam vārdam cels namu un tas man būs par dēlu, un es tam būšu par tēvu, un es apstiprināšu viņa valstības krēslu pār Israēli mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nu tad, mans dēls, Tas Kungs būs ar tevi un tev labi izdosies, ka tu uzcel Tam Kungam, savam Dievam, namu, kā viņš par tevi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Un Tas Kungs tev dos gudrību un saprašanu un tevi cels pār Israēli, turēt Tā Kunga, sava Dieva, bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Tad tev labi izdosies, kad tu turēsi un darīsi tos likumus un tās tiesas, ko Tas Kungs Mozum pavēlējis priekš Israēla. Ņemies drošu sirdi, nebīsties un nebaiļojies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Un redzi, es esmu rūpējies un sakrājis priekš Tā Kunga nama simt tūkstoš talentus zelta un tūkstoš reiz tūkstoš talentus sudraba, un varu un dzelzi bez svara, jo tā ir ļoti daudz; ir kokus un akmeņus es esmu sakrājis; tu vari vēl gādāt klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Tev arī ir pulks strādnieku, akmeņu cirtēju un amatnieku pie akmeņiem un kokiem un ļaudis, mācīti uz visādu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Zelta, sudraba un vara un dzelzs ir neizskaitāms pulks. Celies un taisi, un lai Tas Kungs ir ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Un Dāvids pavēlēja visiem Israēla virsniekiem, palīdzēt viņa dēlam Salamanam:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Vai Tas Kungs, jūsu Dievs, nav ar jums, un jums nav devis mieru visapkārt? Jo viņš tās zemes iedzīvotājus ir devis manā rokā, un šī zeme ir pārvarēta Tā Kunga un viņa ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Tad nu dzenaties ar savu sirdi un ar savu dvēseli meklēt To Kungu, savu Dievu, un ceļaties un uztaisiet Dieva, Tā Kunga, svēto vietu, ka Tā Kunga derības šķirstu un svētos Dieva traukus var ienest šai namā, kas taps uztaisīts Tā Kunga vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Un kad Dāvids bija vecs un savu laiku nodzīvojis, tad tas savu dēlu Salamanu cēla par ķēniņu pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Un (Dāvids) sapulcēja visus Israēla virsniekus un priesterus un Levitus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Un Leviti tapa skaitīti no trīsdesmit gadiem un pārāk, un viņu skaits pēc viņu vīru galvām bija trīsdesmit astoņi tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'No tiem bija divdesmit četri tūkstoši nolikti pie Tā Kunga nama darba, un seši tūkstoš uzraugi un tiesneši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Un četri tūkstoš vārtu sargi un četri tūkstoš Tā Kunga dziedātāji ar spēlēm, ko es esmu iecēlis, Dievu teikt (sacīja Dāvids).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Un Dāvids tos dalīja kārtās, pēc Levja bērniem, Geršona, Kehāta un Merarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'No Geršona bērniem bija Laēdans un Šimejus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Laēdana bērni bija: Jeīels, virsnieks, un Zetams un Joēls, tie trīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Šimejus bērni bija: Zalomits un Aziēls un Hārans, tie trīs; šie bija Laēdana tēvu nama virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Un Šimejus bērni bija: Jakats, Zinus un Jeūs un Brija; šie četri bija Šimejus bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Un Jakats bija pirmais un Zinus otrais. Bet Jeūm un Brijam nebija daudz bērnu, tāpēc tie tapa skaitīti par vienu tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Un Kehāta bērni bija: Amrams, Jecears, Hebrons un Uziēls, tie četri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amrama bērni bija Ārons un Mozus. Un Āronu atšķīra, ka tas taptu svētīts visusvētākajā amatā līdz ar saviem dēliem mūžīgi, kvēpināt priekš Tā Kunga vaiga un viņam kalpot un svētīt viņa vārdā mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Un Mozus, Tā Dieva vīra, bērni bija skaitīti pie Levitu cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mozus bērni bija: Ģerzoms un Eliēzers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Ģerzoma bērni bija Zebuēls, virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Un Eliēzeram bērni bija: Rekabeja, virsnieks. Un Eliēzeram nebija citu bērnu. Bet Rekabejas bērni vairojās daudz vairāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jeceara bērni bija: virsnieks Zalomits.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebrona bērni bija: Jerija tas pirmais, Amarija otrais, Jeaziēls trešais, un Jakmeams ceturtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Uziēļa bērni bija: Miha tas pirmais un Jezija otrais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merarus bērni bija: Maēlus un Muzus. Maēlus bērni bija: Eleazars un Ķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Un Eleazars nomira, un tam dēlu nebija, bet meitas vien, un Ķisa bērni, viņu brāļi, tās apņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Muzus bērni bija Maēlns, Eders un Jeremots, tie trīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Šie bija Levja bērni pēc savu tēvu namiem, savu tēvu namu virsnieki, kas pēc vārdiem tapa skaitīti pēc viņu galvām; tie stāvēja kalpošanas darbā Tā Kunga namā, divdesmit gadus veci un vairāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Jo Dāvids bija sacījis: Tas Kungs, Israēla Dievs, Saviem ļaudīm dusu devis, un Viņš Jeruzālemē mājos mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Tad arī Levitiem vairs nebija jānes tas dzīvoklis, nedz kādas citas lietas, kas pie tā amata piederēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Bet pēc Dāvida pēdējiem vārdiem Levja bērni tapa skaitīti, divdesmit gadus veci un vairāk,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Ka tiem bija jāstāv apakš Ārona bērnu rokas, kalpot Tā Kunga nama pagalmā un mantas kambaros un tīrīt visas svētās lietas un stāvēt Dieva nama kalpošanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Un pie Dieva priekšā noliekamām maizēm un ēdamo upuru kviešu miltiem un neraudzētām karašām un pannām un ceptiem raušiem un pie visiem svariem un mēriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Un ik rītu stāvēt, To Kungu teikt un slavēt, tāpat arī ik vakaru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Un upurēt visus dedzināmos upurus svētdienās, jaunos mēnešos un svētkos pēc sava skaita un tiesas Tā Kunga priekšā vienmēr,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Un sargāt saiešanas telti un svēto vietu un kalpot saviem brāļiem, Ārona bērniem, Tā Kunga nama kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Un šī bija Ārona bērnu kārta. Ārona bērni bija: Nadabs un Abijus, Eleazars un Ītamars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Bet Nadabs un Abijus nomira priekš sava tēva, un tiem bērnu nebija, un Eleazars un Ītamars palika par priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Un Dāvids tos nodalīja, Cadoku no Eleazara bērniem un Aķimeleku no Ītamara bērniem, pēc viņu kalpošanas kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Un Eleazara bērnos tapa atrastas vairāk vīriešu galvas, nekā Ītamara bērnos, un tie tos nodalīja; no Eleazara bērniem bija sešpadsmit tēvu namu virsnieki, bet no Ītamara bērniem bija astoņi virsnieki pēc saviem tēvu namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Un tos nodalīja caur meslošanu, tā šos kā viņus, jo virsnieki svētā vietā un virsnieki Dieva priekšā bija no Eleazara un Ītamara bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Un Šemaja, Netaneēļa dēls, skrīveris no Levitiem, tos uzrakstīja ķēniņa priekšā un lielkungu un priestera Cadoka un Aķimeleka, Abjatara dēla, un priesteru un Levitu tēvu namu virsnieku priekšā; viens tēva nams tapa ņemts no Eleazara, un viens tāpat tapa ņemts no Ītamara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Un tā pirmā meslu zīme krita Jojaribam, otrā Jedajam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Trešā Harimam, ceturtā Zeorimam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Piektā Malhijam, sestā Mejaminam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Septītā Akocam, astotā Abijam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Devītā Jezuam, desmitā Šekanijam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Vienpadsmitā Eliazibam, divpadsmitā Jaķimam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Trīspadsmitā Upam, četrpadsmitā Jezebeabam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Piecpadsmitā Bilgam, sešpadsmitā Imeram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Septiņpadsmitā Heziram, astoņpadsmitā Apicecam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Deviņpadsmitā Petahjam, divdesmitā Jezķelim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Divdesmit pirmā Jaķinam, divdesmit otrā Gamulam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Divdesmit trešā Delajam, divdesmit ceturtā Maāzijam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Šī ir viņu kalpošanas kārta, iet Tā Kunga namā pēc sava likuma caur Āronu, savu tēvu, kā tam Tas Kungs, Israēla Dievs, bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Un no tiem citiem Levja bērniem: no Amrama bērniem bija Zubaēls, no Zubaēla bērniem Jekdeja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'No Rekabejas: Rekabejas bērniem virsnieks bija Jezija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'No Jeceara bērniem bija Zalomots, no Zalamota bērniem Jakats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Un no (Hebrona) bērniem bija: Jerijus (pirmais), Amarija otrais, Jaēziēls trešais, Jakmeams ceturtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Uziēļa bērni Miha: no Mihas bērniem: Zamirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Mihas brālis bija Jezija: no Jezijas bērniem: Zaharija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merarus bērni bija: Maēlus un Muzus; tā dēls Jaēzija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merarus bērni no Jaēzijas, viņa dēla, bija: Zoams un Zakurs un Jbrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'No Maēlus bija Eleazars; tam nebija bērnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'No Ķisa: Ķisa bērni: Jerameēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Un Muzus bērni bija: Maēlus un Eders un Jeremots. Šie ir Levitu bērni pēc saviem tēvu namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Un priekš tiem tapa arī meslots, tāpat tā priekš viņu brāļiem, Ārona dēliem, ķēniņa Dāvida priekšā un Cadoka un Aķimeleka un priesteru un Levitu tēvu namu virsnieku priekšā, tā tēvu nama virsniekam, kā mazākam brālim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Un Dāvids ar tiem kara lielkungiem nodalīja pie kalpošanas no Asafa un Hemana un Jedituna bērniem, kas garīgas dziesmas dziedāja ar koklēm un soma stabulēm un pulkstenīšiem, un to vīru skaits, kas savā kalpošanā stāvēja, bija:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'No Asafa bērniem: Zakurs un Jāzeps un Netanija un Azarelus; tie bija Asafa bērni apakš Asafa, kas pie ķēniņa garīgas dziesmas dziedāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'No Jedituna: Jedituna bērni bija: Ģedalija un Corus un Ješaja, Hašabija un Matatija (un Zimei), tie seši, apakš sava tēva Jedituna ar koklēm garīgas dziesmas dziedādami, To Kungu teikt un slavēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'No Hemana: Hemana bērni bija: Buķija, Matanija, Uziēls, Zebuēls un Jerimots, Ananija, Hananus, Eliatus, Ģidaltus, RomamtiEzers, Jazbekazus, Malotus, Otirs, Maēziots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Šie visi bija Hemana bērni, kas bija ķēniņa redzētājs Dieva vārdos, pacelt ragu; un Dievs Hemanam deva četrpadsmit dēlus un trīs meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Šie visi bija apakš saviem tēviem pie dziedāšanas Tā Kunga namā ar pulkstenīšiem, soma stabulēm un koklēm pie Dieva nama kalpošanas, apakš ķēniņa, Asafa, Jedituna un Hemana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Un viņu skaits ar viņu brāļiem, kas Tā Kunga dziesmās bija mācīti, visi dziesmu pratēji bija divsimt astoņdesmit un astoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Un tie meta meslus par savu kalpošanas kārtu visi kopā, tā priekš maza, kā priekš liela, tā priekš mācītāja, kā priekš mācekļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Pirmā meslu zīme krita Asafam un Jāzepam; otrā Ģedalijam ar viņa brāļiem un viņa dēliem, to bija divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Trešā Zakuram ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Ceturtā Jecrum ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Piektā Netanijam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Sestā Buķijam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Septītā Jezreēlim ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Astotā Ješajam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Devītā Metanijam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Desmitā Šimejum ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Vienpadsmitā Azareēlim ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Divpadsmitā Hašabijam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Trīspadsmitā Zubuēlim ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Četrpadsmitā Matitijam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Piecpadsmitā Jeremotam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Sešpadsmitā Ananijam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Septiņpadsmitā Jazbekazum ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Astoņpadsmitā Hananum ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Deviņpadsmitā Malotum ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Divdesmitā Elijatam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Divdesmit pirmā Otiram ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Divdesmit otrā Ģidaltum ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Divdesmit trešā Maēsiotam ar viņa dēliem un viņa brāļiem, to bija divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Divdesmit ceturtā RomamtiEzeram ar viņa dēliem un ar viņa brāļiem, to bija divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Un vārtu sargu kārta bija šī: no Koraha bērniem bija: MeŠelemija, Koraha dēls, no Asafa bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Un Me Šelemijas bērni bija: Zaharija, tas pirmdzimušais, Jediaēls otrais, Zebadija trešais, Jatniēls ceturtais,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elams piektais, Jehohanans sestais, Elioēnajus septītais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Un ObedEdoma bērni bija: Šemaja tas pirmdzimušais, Jozabads otrais, Joaks trešais, Zakars ceturtais, un Netaneēls piektais,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiēls sestais, Īsašars septītais, Pegultajus astotais, - jo Dievs viņu bija svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Un viņa dēlam Šemajam arīdzan piedzima dēli, valdnieki sava tēva namā; jo tie bija krietni vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Šemajas bērni bija: Atnus un Revaēls un Obeds un Elzabads, viņa brāļi, krietni vīri, Elijus un Zemaķija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Šie visi bija no ObedEdoma bērniem, gan paši, gan viņu bērni un viņu brāļi, krietni vīri, tikuši(spējīgi ar spēku) pie kalpošanas, sešdesmit divi no ObedEdoma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Un Me Šelemijam bija bērni un brāļi, krietni vīri, astoņpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Un Osam no Merarus bērniem bija dēli: Zimrus tas virsnieks; jebšu viņš nebija tas pirmdzimušais, taču viņa tēvs to iecēla par virsnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilķija otrais, Tebalija trešais, Zaharija ceturtais: visu Osas bērnu un brāļu bija trīspadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Šīm vārtu sargu nodaļām pēc vīriešu galvu skaita piekrita tā sargāšana līdz ar saviem brāļiem, kalpot Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Un tie meta meslus, tā mazais, kā lielais, pēc saviem tēvu namiem, par katriem vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Un tā meslu zīme pret rītiem krita Me Šelemijam; arī viņa dēlam Zaharijam, kas bija gudrs padoma devējs, meta meslus, un viņa meslu zīme krita pret ziemeļiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'ObedEdomam pret dienasvidu un viņa dēliem pie mantu klēts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Zupimam un Osam pret vakariem pie Šalleket vārtiem, kur iela iet uz augšu, vakts pie vakts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Pret rītiem bija seši Leviti, pret ziemeļa pusi ikdienas četri, pret dienasvidu ikdienas četri, bet pie klēts pa diviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Pie Parvara pret vakara pusi četri pie ielas un divi pie Parvara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Šīs ir tās vārtu sargu kārtas no Koraha bērniem un no Merarus bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Bet tie Leviti, viņu brāļi, bija pār Dieva nama mantām un pār tām svētām mantām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'No Laēdana bērniem, Laēdana, Geršona dēla, bērniem, Laēdana, Geršona dēla, tēvu namu virsnieki bija Jeķiēla bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Jeķiēla bērni, Zetams un viņa brālis Joēls, bija pār Tā Kunga nama mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'No Imrama, Jeceara, Hebrona, un Uziēļa bērniem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Zebuēls, Ģerzoma, Mozus dēla, dēls bija par virsnieku pār tām mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Un viņa brāļi no Eliēzera: tā dēls bija Rekabeja, tā Ješaja, tā Jorams, tā Sihrus, tā Šelomits.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Šis Šelomits un viņa brāļi bija pār visām tām svētām mantām, ko ķēniņš Dāvids bija svētījis, līdz ar tiem tēvu namu virsniekiem un tiem tūkstošniekiem un simtniekiem un citiem kara virsniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'No karu laupījuma tie to bija svētījuši, Tā Kunga namu uzkopt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Un visu, ko Samuēls, tas redzētājs, bija svētījis un Sauls, Ķisa dēls, un Abners, Nera dēls, un Joabs, Cerujas dēls, viss, kas bija svētīts, tas bija rokā Šelomitam un viņa brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'No Jeceara bērniem Ķenanija un viņa dēli bija celti tai darbā ārā pie Israēla, par priekšniekiem un tiesnešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'No Hebrona bērniem Hašabija un viņa brāļi, vareni ļaudis, tūkstoš un septiņsimt, bija uzraugi pār Israēli šai Jardānes malā pret vakara pusi pār visu Tā Kunga darbu un ķēniņa kalpošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'No Hebrona bērniem bija Jerija virsnieks pār Hebrona bērniem, viņu radiem un tēvu namiem. Četrdesmitā Dāvida valdīšanas gadā viņu starpā meklēja un atrada krietnus vīrus Jaēzerā Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Un viņu brāļi bija krietni vīri, divtūkstoš un septiņsimt tēvu namu virsnieki. Un ķēniņš Dāvids tos iecēla pār Rūbena un Gada bērniem un Manasus puscilti, pār visām Dieva lietām un ķēniņa lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Šie nu ir Israēla bērni pēc sava skaita, tēvu namu virsnieki un tūkstošnieki un simtnieki un viņu uzraugi, kas ķēniņam kalpoja itin pēc noliktas kārtas nākdami un iedami ik mēnešus cauru gadu; un ikkatrā kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Pār pirmo kārtu pirmā mēnesī bija Jazabeams, Zabdiēļa dēls, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Viņš bija no Pereca bērniem, virsnieks pār visiem kara kungiem pirmā mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Un pār otra mēneša kārtu bija Dodajus, Akoka dēls, un Miklots bija vadonis viņa kārtai, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Trešais kara virsnieks trešā mēnesī bija virsnieks Benaja, priestera Jojadas dēls, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Šis Benaja bija tas varenais starp trīsdesmitiem un pār tiem trīsdesmitiem, un viņa kārtai bija (vadonis) Amizadabs, viņa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Ceturtais ceturtā mēnesī bija Azaēls, Joaba brālis, un pēc viņa Zabadija, viņa dēls, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Piektais virsnieks piektā mēnesi bija Zameūts, Jezraka dēls, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Sestais sestā mēnesī bija Īrus, Ikeša, dēls, no Tekoas, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Septītais septītā mēnesī bija Elecs no Pelonas, no Efraīma bērniem, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Astotais astotā mēnesī bija Zibekajus, Uzata dēls, no Zeraka bērniem, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Devītais devītā mēnesī bija Abiēzers no Antotas, no Benjamina bērniem, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Desmitais desmitā mēnesī bija Maērajus no Netofas, no Zeraka bērniem, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Vienpadsmitais vienpadsmitā mēnesī bija Benaja no Pirgatonas, no Efraīma bērniem, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Divpadsmitais divpadsmitā mēnesī bija Eldajus no Netofas, no Atniēļa nama, un viņa kārtā bija divdesmit četri tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Un pār Israēla ciltīm bija: pār Rūbena bērniem bija valdītājs Eliēzers, Sihrus dēls, pār Sīmeana bērniem Šefatija, Maēkas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Pār Levitiem Hašabija, Ķemuēļa dēls, pār Ārona bērniem Cadoks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Pār Jūdu Elijus, no Dāvida brāļiem; pār Īsašaru Omrus, Mikaēļa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Pār Zebulonu Jezmaja, Obadijas dēls, pār Naftalu Jeremots, Asriēļa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Pār Efraīma bērniem Hošeja, Azazias dēls, pār Manasus puscilti Joēls, Pedajas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Pār Manasus puscilti Gileādā Idus Zaharijas dēls, pār Benjaminu Jaēziēls, Abnera dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Pār Danu Azareēls, Jeroama dēls, šie ir Israēla cilšu virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Bet Dāvids tos neskaitīja, kas divdesmit gadus veci un vēl jaunāki, tāpēc ka Tas Kungs bija sacījis, ka Israēli gribot vairot kā debess zvaigznes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joabs, Cerujas dēls, bija sācis skaitīt, bet nepabeidza, tāpēc ka nāca liela dusmība pār Israēli, un tas skaits netika uzņemts ķēniņa Dāvida laiku grāmatu skaitļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Un pār ķēniņa mantām bija Asmavets, Adiēļa dēls, un pār labības krājumiem uz laukiem, pilsētās un ciemos un pilīs Jonatāns, Uzijas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Un pār zemes strādniekiem un lauku kopējiem bija Ezrus, Ķeluba dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Un pār vīna dārziem bija Šimejus no Rāmatas; un pār vīna krājumiem vīna dārzos Zabdus no Zevamas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Un pār eļļas dārziem un meža vīģes kokiem ielejās bija BaālAnans no Ģederas; un pār eļļas krājumiem Joas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Un pār vēršiem, kas Šaronā ganījās, bija Zitrajus no Šaronas, bet pār tiem vēršiem ielejās, Šafats, Adlaja dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Un pār kamieļiem bija Obils, tas Ismaēlietis; un pār ēzeļu mātēm Jeēdija no Meronotas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Un pār sīkiem lopiem bija Jazus, tas Agarietis. Šie visi bija uzraugi pār ķēniņa Dāvida mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Un Jonatāns, Dāvida brālēns, bija padoma devējs, prātīgs vīrs un rakstu pratējs, un Jeīels, Akmona dēls, bija pie ķēniņa bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Un Ahitofels bija ķēniņa padoma devējs, un Uzajus no Arkas, bija ķēniņa draugs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Un pēc Ahitofela bija Jojada, Benajas dēls, un Abjatars. Bet Joabs bija ķēniņa kara vadonis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Tad Dāvids sapulcēja uz Jeruzālemi visus Israēla lielkungus, cilšu virsniekus un kārtu virsniekus, kas ķēniņam kalpoja, tūkstošniekus un simtniekus, un virsniekus pār visām ķēniņa un viņa dēlu mantām un ganāmiem pulkiem un kambarjunkurus un varenos un visus stipros vīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Un ķēniņš Dāvids cēlās kājās un sacīja: klausāties mani, mani brāļi un mani ļaudis. Es savā prātā biju apņēmies, dusas namu uztaisīt Tā Kunga derības šķirstam un par kāju pameslu mūsu Dievam, un jau biju taisījies to celt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Bet Dievs uz mani sacīja: tev nebūs namu taisīt Manam vārdam, jo tu esi karavīrs un esi asinis izlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Nu Tas Kungs, Israēla Dievs, mani izredzējis no visa mana tēva nama būt par ķēniņu pār Israēli mūžīgi. Jo viņš Jūdu izredzējis par valdītāju un Jūda ciltī mana tēva namu, un starp mana tēva bērniem viņam labs prāts bijis pie manis, celt mani par ķēniņu pār visu Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Un no visiem maniem dēliem, (jo Tas Kungs man devis daudz dēlu,) viņš izredzējis manu dēlu Salamanu, sēdēt Tā Kunga valstības krēslā pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Un Viņš uz mani sacījis: tavs dēls Salamans, tas uztaisīs Manu namu un Manus pagalmus, jo to Es esmu izredzējis Sev par dēlu, un Es tam būšu par tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Un Es apstiprināšu viņa valstību mūžīgi, ja viņš pastāvīgi turēs un darīs Manus baušļus un Manas tiesas itin kā šodien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Un nu, visam Israēlim, Tā Kunga draudzei, redzot un mūsu Dievam dzirdot: turat un meklējiet Tā Kunga, sava Dieva, baušļus visus, ka jūs paturat to labo zemi un to atstājat saviem bērniem par mantojumu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Un tu, mans dēls Salaman, atzīsti sava tēva Dievu un kalpo Tam ar visu sirdi un ar labu prātu, jo Tas Kungs izmeklē visas sirdis un saprot visas prāta domas. Ja tu Viņu meklēsi, tad tu Viņu atradīsi, bet ja tu Viņu atstāsi, tad Viņš tevi atmetīs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Redzi nu, kad Tas Kungs tevi izredzējis, uztaisīt namu par svētu vietu, tad esi stiprs un dari to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Un Dāvids deva savam dēlam Salamanam priekšzīmi no priekšnama un viņa ēkām un mantas kambariem un viņa augšistabām un iekšistabām un no salīdzināšanas vāka(grēka apklāšanas) nama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Un priekšzīmi no visa, kas viņam bija prātā, proti no Tā Kunga nama pagalmiem un no visiem apkārtējiem kambariem priekš Dieva nama mantām un svētajām mantām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Un priekš priesteru un Levitu kārtām un visa kalpošanas darba Tā Kunga namā un priekš visiem rīkiem pie Tā Kunga nama kalpošanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Un no zelta, cik zelta ņemams katram dievkalpošanas traukam un no visiem sudraba traukiem, cik svara katram kalpošanas traukam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Un noteica svaru zelta lukturiem un viņu zelta eļļas lukturīšiem, cik svara katram lukturim un viņa eļļas lukturīšiem; ir sudraba lukturiem, cik svara ikkatram lukturim, un viņa eļļas lukturīšiem, kā ikkatram lukturim vajadzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Viņš arī nosacīja zeltu pēc svara priekšliekamās maizes galdiem, cik ikkatram galdam vajadzēja, un sudrabu sudraba galdiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Un dakšām un bļodām un kannām no tīra zelta un zelta un sudraba biķeriem pēc ikkatra biķera svara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Un kvēpināšanas altārim no šķīstīta zelta pēc svara; arī priekšzīmi no ratiem ar zelta ķerubiem, kas spārnus izplētuši apsedz Tā Kunga derības šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Tas viss stāv rakstos no Tā Kunga rokas, kas mani pamācījis par visiem darbiem pēc šīs priekšzīmes (tā Dāvids sacīja).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Un Dāvids sacīja uz savu dēlu Salamanu: ņemies drošu prātu un dari to un nebīsties un nebaiļojies, jo Dievs Tas Kungs, mans Dievs, būs ar tevi, Viņš tevi nepametīs un neatstās, tiekams tu visu darbu būsi pabeidzis Tā Kunga nama kalpošanai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Un redzi, še ir tās priesteru un Levitu kārtas pie visas Dieva nama kalpošanas; un tev ir uz visādu darbu visādi labprātīgi vīri, gudri pie visādas kalpošanas, un lielkungi un visi ļaudis gatavi, darīt pēc tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Un ķēniņš Dāvids sacīja uz visu draudzi: Salamans, mans dēls, tas vienīgais, ko Dievs izredzējis, vēl ir jauns un mazs, un taču šis darbs ir liels, jo tā nav pils kādam cilvēkam, bet Dievam, Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Tad ar visu savu spēku esmu sagādājis priekš sava Dieva nama zeltu zelta rīkiem un sudrabu sudraba rīkiem un varu vara rīkiem un dzelzi dzelzs rīkiem un kokus koka rīkiem, Onika akmeņus un ieliekamus akmeņus un rubīnus un raibus akmeņus, visādus dārgus akmeņus un marmora akmeņus lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Un turklāt, kad man pie sava Dieva nama ir labs prāts, man ir vēl zelts un sudrabs, un to es dodu klāt savam Dieva namam bez visa tā, ko esmu sakrājis priekš tā svētā nama:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Trīstūkstoš talentus zelta no Ofira zelta un septiņtūkstoš talentus šķīsta sudraba, ēku sienas pārvilkt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Zeltu zelta- un sudrabu sudraba-(traukiem) un ikvienam darbam, ko amatnieku roka taisa. Un kam nu ir labs prāts šodien ar pilnu roku upurēt Tam Kungam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Tad deva ar labu prātu tēvu namu virsnieki un Israēla cilšu virsnieki un tūkstošnieki un simtnieki un ķēniņa darba virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Tie deva Dieva nama vajadzībai piectūkstoš talentus zelta un desmit tūkstoš zelta gabalus un desmit tūkstoš talentus sudraba, astoņpadsmit tūkstoš talentus vara un simts tūkstoš talentus dzelzs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Un pie kā akmeņi atradās, tie tos deva Tā Kunga nama mantā Jeķiēļa, Geršona dēla, rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Un tie ļaudis priecājās labprātīgi dodami, jo tie deva no visas sirds Tam Kungam ar labu prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Un ķēniņš Dāvids priecājās arī ar lielu prieku, un Dāvids teica To Kungu visas draudzes priekšā. Un Dāvids sacīja: slavēts esi Kungs, mūsu tēva Israēla Dievs, mūžīgi mūžam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tev, Kungs, pieder augstība un spēks un godība un slava un gods, jo viss, kas debesīs un zemes virsū, tas Tev pieder. Tava ir tā valstība, un Tu esi paaugstinājies kā galva pār visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Un bagātība un gods nāk no Tevis, un Tu esi valdītājs pār visu, un Tavā rokā ir spēks un vara, un Tavā rokā stāv, visu paaugstināt un stiprināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Tad nu, mūsu Dievs, mēs Tev pateicamies un slavējam Tavas godības vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Jo kas es esmu, un kas ir mani ļaudis, ka mēs spētu labprātīgi dot tādas dāvanas? Jo viss ir no Tevis, un no Tavas rokas mēs Tev dodam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Jo mēs esam svešinieki un piemitēji Tavā priekšā, kā visi mūsu tēvi; mūsu dienas virs zemes ir kā ēna un bez pastāvības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Kungs, mūsu Dievs, visa šī bagātība, ko esam sakrājuši, Tev namu taisīt Tavam svētam vārdam, tā ir no Tavas rokas, un viss Tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Un es zinu, mans Dievs, ka Tu sirdi pārbaudi, un skaidrība Tev labi patīk; no savas sirds skaidrības visu šo esmu devis ar labu prātu, un esmu redzējis ar līksmību Tavus ļaudis, kas še sanākuši, Tev dodam labprātīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Kungs, mūsu tēvu, Ābrahāma, Īzaka un Israēla, Dievs, uzturi to mūžīgi, tādu prātu un sirdi Saviem ļaudīm, un atgriez viņu sirdis pie Sevis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Un manam dēlam Salamanam dod padevīgu sirdi, turēt Tavus baušļus un Tavas liecības un Tavus likumus un visu darīt un uztaisīt šo augsto namu, ko es esmu nolicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Un Dāvids sacīja uz visu draudzi: teiciet jel To Kungu, savu Dievu! Tad visa draudze teica To Kungu, savu tēvu Dievu, un palocījās un nometās zemē Tā Kunga un ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Un tie upurēja Tam Kungam upurus, un upurēja Tam Kungam dedzināmos upurus otras dienas rītā tūkstoš vēršus, tūkstoš aunus, tūkstoš jērus ar saviem dzeramiem upuriem un kaujamiem upuriem lielā pulkā priekš visa Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Un tie ēda un dzēra tai dienā Tā Kunga priekšā ar lielu līksmību. Un tie cēla Salamanu, Dāvida dēlu, otrā reizē par ķēniņu un to svaidīja par valdītāju Tā Kunga priekšā un Cadoku par priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Tā Salamans sēdās Tā Kunga krēslā par ķēniņu sava tēva Dāvida vietā, un tam labi izdevās, un viss Israēls tam klausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Un visi lielkungi un varenie, arī visi ķēniņa Dāvida bērni padevās ķēniņam Salamanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Un Tas Kungs darīja Salamanu jo lielu visa Israēla priekšā un deva tam valstības godību, kāda vēl nebija bijusi nevienam Israēla ķēniņam priekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Tā Dāvids, Isajus dēls, bija valdījis pār visu Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Un tas laiks, kamēr viņš valdīja pār Israēli, bija četrdesmit gadi; Hebronē viņš valdīja septiņus gadus un Jeruzālemē viņš valdīja trīsdesmit trīs gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Un viņš nomira labā vecumā, diezgan piedzīvojis mūža dienu, bagātības un goda, un viņa dēls Salamans palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Un ķēniņa Dāvida lietas, pirmās un pēdējās, redzi, tās ir rakstītas redzētāja Samuēla stāstos un pravieša Nātana stāstos un redzētāja Gada stāstos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Ar visu viņa valdību un varu un tiem laikiem, kas aizgājuši pār viņu un pār Israēli un pār visām valstīm un zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Un Salamans, Dāvida dēls, palika spēcīgs savā ķēniņa valdībā, jo Tas Kungs, viņa Dievs, bija ar to un darīja to ļoti lielu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Un Salamans sacīja uz visu Israēli, uz tūkstošniekiem un simtniekiem un tiesnešiem un visiem Israēla lielkungiem, tēvu namu virsniekiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Ka tie noietu, Salamans un visa draudze līdz ar viņu, uz to kalnu Gibeonā, jo tur bija Dieva saiešanas telts, ko Mozus, Tā Kunga kalps, tuksnesī bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Bet Dieva šķirstu Dāvids bija atvedis no Kiriat Jearimas uz to vietu, ko Dāvids tam bija sataisījis, jo viņš tam bija uzcēlis telti Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Tur bija arī vara altāris, ko Becaleēls, Urus dēls, Ura dēla dēls, bija taisījis priekš Tā Kunga dzīvokļa, un Salamans un tā draudze to apmeklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Un Salamans tur upurēja priekš Tā Kunga vaiga uz vara altāra saiešanas telts priekšā, un viņš upurēja uz tā tūkstoš dedzināmos upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Tanī naktī Dievs parādījās Salamanam un uz to sacīja: lūdz, ko Man tev būs dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Un Salamans sacīja uz Dievu: manam tēvam Dāvidam Tu esi parādījis lielu žēlastību un mani Tu esi cēlis par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Tad nu, Kungs Dievs, lai Tavs vārds tiešām tā notiek, kā Tu esi runājis uz manu tēvu Dāvidu, jo Tu mani esi cēlis par ķēniņu pār ļaudīm, kuru tik daudz, kā zemes pīšļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Tad dod man nu gudrību un saprašanu, ka es šo ļaužu priekšā izeju un ieeju, jo kas varētu tiesāt šo Tavu lielo tautu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Tad Dievs sacīja uz Salamanu: tāpēc ka tas ir tavā sirdī, un tu neesi lūdzies nedz bagātību, nedz mantas, nedz godu, nedz savu ienaidnieku dvēseles, nedz ilgu mūžu, bet esi izlūdzies gudrību un saprašanu, Manus ļaudis tiesāt, pār ko Es tevi esmu iecēlis par ķēniņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Tad tev taps dota gudrība un saprašana, un bagātību un mantas un godu arīdzan Es tev došu, kā nevienam ķēniņam nav bijis priekš tevis un pēc tevis arī nevienam nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Tā Salamans nonāca Jeruzālemē no tā kalna Gibeonā, no saiešanas telts, un viņš valdīja pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Un Salamans sakrāja ratus un jātniekus, un viņam bija tūkstoš četrsimt rati un divpadsmit tūkstoš jātnieki, un viņš tos lika ratu pilsētās un pie ķēniņa Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Un ķēniņš darīja, ka sudraba un zelta bija Jeruzālemē tik daudz, kā akmeņu, un ciedru koku tik daudz, kā meža vīģes koku ielejās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Un Salamanam veda zirgus no Ēģiptes un visādas preces, un ķēniņa tirgotāji pirka tās preces.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Un tie gāja un atveda no Ēģiptes ratus par sešsimt sudraba gabaliem, un vienu zirgu par simt piecdesmit. Un viņi tos izveda arī visiem Hetiešu ķēniņiem un Sīriešu ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Un Salamans nodomāja celt namu Tā Kunga vārdam un namu savai ķēniņa valdībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Un Salamans noskaitīja septiņdesmit tūkstoš vīrus pie nastu nešanas un astoņdesmit tūkstoš cirtējus uz kalniem un trīs tūkstoš sešsimt uzraugus pār viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Un Salamans sūtīja pie Hirama, Tirus ķēniņa, un lika sacīt: kā tu esi darījis manam tēvam Dāvidam un tam sūtījis ciedru kokus, sev namu celt, kur dzīvot, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Redzi, es gribu namu celt Tā Kunga, sava Dieva, vārdam un Viņam to svētīt, Viņa priekšā kvēpināt ar saldām kvēpināmām zālēm un nolikt vienmēr priekšliekamas maizes un upurēt dedzināmos upurus ik rītu un ik vakaru, svētdienās un jaunos mēnešos un Tā Kunga, mūsu Dieva, augstos svētkos, kā Israēlim mūžīgi pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Un tas nams, ko es celšu, būs liels, jo mūsu Dievs ir lielāks nekā visi dievi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Bet kam tad tik daudz spēka, Viņam namu celt? Jo debesis un visu debesu debesis nespēs Viņu saņemt; kas tad es esmu, ka varētu Viņam celt namu? Bet ka tik vien Viņa priekšā varētu kvēpināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Un nu sūti man gudru vīru, kas māk izstrādāt zeltu un sudrabu un varu un dzelzi, purpuru, karmezīnu un zilumu, un kas prot strādāt izrakstītu darbu kopā ar tiem gudriem, kas pie manis iekš Jūda un Jeruzālemē, ko mans tēvs Dāvids gādājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Sūti man arī ciedru kokus, priedes un algumim kokus no Lībanus; jo es zinu, ka tavi kalpi prot cirst Lībanus kokus. Un redzi, mani kalpi būs pie taviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Man sacirst kokus lielā vairumā; jo tas nams, ko es celšu, būs liels un apbrīnojams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Un redzi, taviem kalpiem, kas tos kokus cērt, es došu divdesmit tūkstoš koru samaltu kviešu un divdesmit tūkstoš koru miežu, un divdesmit tūkstoš batus vīna un divdesmit tūkstoš batus eļļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Tad Hirams, Tirus ķēniņš, atbildēja caur grāmatām un sūtīja pie Salamana: tāpēc ka Tas Kungs Savus ļaudis mīļo, Viņš tevi licis pār tiem par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Un Hirams sacīja: slavēts lai ir Tas Kungs, Israēla Dievs, kas radījis debesi un zemi, kas ķēniņam Dāvidam devis gudru, prātīgu un apdomīgu dēlu, kas namu uztaisīs Tam Kungam un namu savai ķēniņa valdībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Tad es nu sūtu gudru pratēju vīru, Huramu Abivu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Viņa māte ir no Dana meitām, un viņa tēvs Tiriešu vīrs. Tas māk izstrādāt zeltu un sudrabu, varu, dzelzi, akmeņus, kokus, purpuru un zilumu un smalkas dzijas, audeklu un karmezīnu, un darīt visādu izrakstītu darbu, izdomāt visādas gudras lietas, ko tam liek, ar taviem gudriem un ar tava tēva, mana kunga, Dāvida, gudriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Tad nu lai sūta taviem kalpiem tos kviešus un miežus un eļļu un vīnu, ko mans kungs minējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Tad mēs cirtīsim Lībanus kokus, cik tev vajag un pie tevis novedīsim ar plostiem pār jūru uz Joppi, tad tu tos varēsi likt vest uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Un Salamans skaitīja visus svešiniekus Israēla zemē, pēc tās skaitīšanas, kā viņa tēvs Dāvids tos bija skaitījis, un tur atradās simt piecdesmit trīs tūkstoši seši simti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Un viņš no tiem ņēma septiņdesmit tūkstoš nastu nesējus un astoņdesmit tūkstoš cirtējus uz kalniem un trīs tūkstoš sešsimt uzraugus, ļaudis dzīt pie darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Un Salamans sāka celt Tā Kunga namu Jeruzālemē Morijas kalnā, kas viņa tēvam Dāvidam bija rādīts, tai vietā, ko Dāvids bija sataisījis, uz Jebusieša Arnana klona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Un viņš sāka celt otrā mēnesī otrā dienā, savas valdīšanas ceturtā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Un Salamans lika pamatu ceļamam Dieva namam; pēc tā pirmā mēra tas bija sešdesmit olekšu garumā un divdesmit olekšu platumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Un priekšnams priekšgalā bija tik garš, cik tas nams plats, divdesmit olektis, un simts divdesmit olekšu tas bija augstumā, un viņš to iekšpusē pārvilka ar tīru zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Un tam lielam namam viņš grīdu lika no priedes kokiem, pārvilka to ar labu zeltu un uztaisīja palmu kokus un ķēdītes klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Viņš arī tam namam aplika dārgus akmeņus par glītumu, un tas zelts bija no Parvaīma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Un viņš to namu, baļķus, stabus un viņa sienas un viņa durvis apzeltīja un izgrieza ķerubus pie sienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Un viņš taisīja tās visu svētākās vietas namu; tas bija divdesmit olektis garš un divdesmit olektis plats, un viņš to pārvilka ar labu zeltu pie sešsimt talentiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Un tas naglu svars bija pie piecdesmit sēķeļiem zelta, un viņš pārvilka arī tās augšistabas ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Un viņš taisīja tai visu svētākās vietas namā divus ķerubus, tēlotāja darbu, un tos pārvilka ar zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Un tie ķerubu spārni bija divdesmit olekšu garumā, viens spārns bija piecu olekšu un sniedzās līdz nama sienai, un otrs spārns bija arī piecu olekšu un sniedzās līdz otra ķeruba spārnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Tāpat bija arī tā otra ķeruba spārns piecu olekšu un sniedzās līdz nama sienai, un otrs spārns bija arī piecu olekšu un sniedzās līdz tā otra ķeruba spārnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Šo ķerubu spārni izplētās divdesmit olektis, un tie stāvēja uz savām kājām, un viņu vaigi bija griezti uz iekšpusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Un viņš taisīja priekšvelkamo no ziluma, no purpura un dārga sarkanuma un smalkām dzijām un ieauda tam ķerubus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Bet tā nama priekšā viņš lika divus stabus trīsdesmit un piecu olekšu augstumā, un tas kronis ikkatram virsū bija piecu olekšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Un viņš taisīja ķēdītes pie stīpas un lika tās uz tiem stabu kroņiem un taisīja simts granātābolus un lika tos starp tām ķēdītēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Un viņš uzcēla tos stabus Dieva nama priekšā, vienu pa labo roku un otru pa kreiso, un viņš to pa labo roku nosauca Jaķinu un to pa kreiso Boasu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Un viņš taisīja vara altāri; divdesmit olektis tas bija garš un divdesmit olektis bija viņa platums un desmit olektis bija viņa augstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Un viņš lēja jūru; tā bija desmit olektis no vienas malas līdz otrai, visapkārt apaļa, un piecas olektis bija viņas augstums, un tas mērs visapkārt bija trīsdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Un vēršu tēli bija apakšā ap viņu visapkārt, desmit uz ikvienu olekti, un tika visapkārt ap to jūru; tādu vēršu bija divas rindas, vienā lējienā līdz ar to jūru lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Tā (jūra) stāvēja uz divpadsmit vēršiem; trīs no tiem griezās pret ziemeļa pusi un trīs griezās pret vakara pusi un trīs griezās pret dienasvidu un trīs griezās pret rītiem, un tā jūra bija virsū uz tiem, un visi viņu aizmugures gali bija iekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Un viņas biezums bija plaukstas platumā, un viņas mala bija tā darīta kā biķera mala, pēc lilijas zieda iztaisīta; un trīs tūstoš bati tanī sagāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Un viņš taisīja desmit katlus un lika piecus pa labo un piecus pa kreiso roku priekš mazgāšanas, - kas pie tā dedzināma upura piederēja, to tie tur izskaloja; bet tā jūra bija priekš tam, ka tie priesteri tur mazgātos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Un viņš taisīja desmit zelta lukturus, kā tiem vajadzēja būt, un tos nolika Dieva namā, piecus pa labo un piecus pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Un viņš taisīja desmit galdus un tos nolika Dieva namā, piecus pa labo un piecus pa kreiso roku, un taisīja arī simts zelta bļodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Un viņš taisīja to priesteru pagalmu un to lielo pagalmu ar tiem pagalma vārtiem, un vārtu durvis viņš pārvilka ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Un to jūru viņš nolika pa labo roku rīta pusē dienasvidum pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Vēl Hurams taisīja podus un lāpstas un bļodas. Tā Hurams pabeidza to darbu, ko viņš ķēniņam Salamanam Dieva namā darīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Tos divus stabus ar tiem apaļiem kroņiem abēju stabu virsū un tās divas pītās stīpas, tos apaļos kroņus apsegt, kas bija stabu virsū,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Un tos četrsimt granātābolus pie tām divām pītām stīpām, divas granātābolu rindas pie katras stīpas, tos apaļos kroņus apsegt, kas bija stabu virsū,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Un viņš taisīja tos krēslus, un uz tiem krēsliem viņš taisīja katlus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'To vienu jūru, un apakš tās tos divpadsmit vēršus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Tāpat podus un lāpstas un bļodas un visus viņu rīkus Hurams Abivus taisīja ķēniņam Salamanam priekš Tā Kunga nama no šķīsta vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Jardānes klajumā viņš tos ķēniņam lēja cietā zemē starp Sukotu un Caredatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Un Salamans taisīja visas šās lietas varen lielā pulkā, un vara svars netapa likts vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Un Salamans taisīja visas lietas priekš Dieva nama un to zelta altāri un tos galdus, uz ko tās svētās maizes tapa liktas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Un tos lukturus ar viņu eļļas lukturīšiem no tīra zelta, ka tie taptu iededzināti visusvētākās vietas priekšā, tā kā piederējās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Un tās puķes un eļļas lukturus un lukt(dakts)šķēres no zelta: viss bija no visšķīstākā zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Un naži un bļodas un karotes un kvēpināmie trauki bija no tīra zelta. Un tā nama vārtu durvis iekšpusē uz to vissvētāko vietu un Dieva nama durvis bija no zelta. Tā viss darbs tapa pabeigts, ko Salamans pie Tā Kunga nama darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Un Salamans nonesa visas sava tēva Dāvida svētītās lietas un sudrabu un zeltu un visus traukus un nolika pie tām Dieva nama mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Tad Salamans sapulcināja Israēla vecajus un visu cilšu priekšniekus, tos tēvu namu virsniekus starp Israēla bērniem, uz Jeruzālemi, Tā Kunga derības šķirstu uz augšu nest no Dāvida pilsētas, tā ir Ciāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Un visi Israēla vīri sapulcējās pie ķēniņa svētkos. Tas bija tas septītais mēnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Un visi Israēla vecaji atnāca, un Leviti pacēla to šķirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Un to šķirstu un saiešanas telti tie uznesa augšām līdz ar visām svētām lietām, kas bija teltī, tās priesteri un Leviti uznesa augšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Bet ķēniņš Salamans un visa Israēla draudze, kas pie viņa bija sapulcējusies tā šķirsta priekšā, upurēja avis un vēršus, ko liela pulka dēļ nevarēja ne skaitīt, ne rēķināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Un priesteri nesa Tā Kunga derības šķirstu savā vietā, nama iekšnamā, tai visusvētākā vietā apakš tiem ķerubru spārniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Un tie ķerubi izplēta savus spārnus pār tā šķirsta vietu, un tie ķerubi apklāja to šķirstu un viņa kārtis no virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Un nesamās kārtis bija tik garas, ka kāršu gali no šķirsta bija redzami visusvētās vietas priekšā, bet ārpusē tie nebija redzami; un tas tur bija līdz šo dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Tai šķirstā nekā nebija iekšā kā vien tie divi galdi, ko Mozus Horebā bija ielicis, kad Tas Kungs derību derēja ar Israēla bērniem, kad tie bija izgājuši no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Un notikās, kad tie priesteri no tās svētās vietas izgāja, jo visi priesteri, kas atradās, bija svētījušies, tā ka tās kārtas netapa turētas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Un Leviti ar visiem tiem, kas bija apakš Asafa un Hemana un Jedituna un viņu bērniem un brāļiem, ar nātnu drēbēm apģērbti, ar pulkstenīšiem un somastabulēm un koklēm, stāvēja pret altāra rīta pusi, un ar tiem kādi simts un divdesmit priesteri, kas pūta ar trumetēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Un tie vienā skaņā pūta un dziedāja, tā ka bija viena vienīga balss, kas To Kungu teica un slavēja; - kad tie nu balsi pacēla ar trumetēm un pulkstenīšiem un citiem spēlējamiem rīkiem, To Kungu slavēt, ka Viņš labs un Viņa žēlastība paliek mūžīgi, - tad tas nams, Tā Kunga nams, piepildījās ar mākoni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Ka tie priesteri nevarēja stāvēt tā mākoņa dēļ nedz kalpot, jo Tā Kunga godība bija piepildījusi Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tad Salamans sacīja: Tas Kungs ir sacījis, Viņš gribot tumsā mājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Un es Tev esmu uztaisījis mājas vietu un vietu Tev par mūžīgu dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Un ķēniņš atgrieza savu vaigu un svētīja visu Israēla draudzi un visa Israēla draudze stāvēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Un viņš sacīja: slavēts lai ir Tas Kungs, Israēla Dievs, kas ar Savu muti runājis uz manu tēvu Dāvidu un ar Savu roku to piepildījis, ko sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'No tās dienas, kamēr esmu izvedis Savus ļaudis no Ēģiptes zemes, Es nevienu pilsētu neesmu izredzējis no visām Israēla ciltīm, namu taisīt, ka Mans vārds tur būtu; arī nevienu vīru neesmu izredzējis par valdītāju pār Maniem Israēla ļaudīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Bet Jeruzālemi Es esmu izredzējis, ka Mans vārds tur būtu, un Dāvidu Es esmu izredzējis, ka tas būtu pār Maniem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Un tas manam tēvam Dāvidam bija sirdī, namu celt Tā Kunga, Israēla Dieva, vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Bet Tas Kungs sacīja uz manu tēvu Dāvidu: tāpēc ka tu savā sirdī esi apņēmies, celt Manam vārdam namu, tu gan labi esi darījis, ka tas bijis tavā sirdī;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Tomēr tev nebūs celt to namu, bet tavam dēlam, kas nāks no taviem gurniem, tam būs namu celt Manam vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Un Tas Kungs ir piepildījis Savu vārdu, ko Viņš runājis, jo es esmu cēlies sava tēva Dāvida vietā un sēžu Israēla goda krēslā, kā Tas Kungs runājis, un esmu namu cēlis Tā Kunga, Israēla Dieva, vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Un tur es esmu nolicis to šķirstu, kur Tā Kunga derība, ko Viņš derējis ar Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Un viņš stājās Tā Kunga altāra priekšā visai Israēla draudzei pretī un izplēta savas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Un Salamans bija taisījis vara pakāpienus un tās licis pagalma vidū, piecas olektis garas un piecas olektis platas un trīs olektis augstas, un tur viņš uzkāpa un nometās ceļos visas Israēla draudzes priekšā un izplēta savas rokas pret debesīm un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Kungs, Israēla Dievs, neviens nav tāds Dievs, kā Tu, ne debesīs, ne virs zemes; Tu turi derību un žēlastību Saviem kalpiem, kas ar visu sirdi staigā Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Savam kalpam, manam tēvam Dāvidam, Tu esi turējis, ko Tu viņam runājis, jo ar Savu muti Tu esi runājis un ar Savu roku Tu to esi piepildījis, tā kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Un nu Kungs, Israēla Dievs, turi Savam kalpam, manam tēvam Dāvidam, ko Tu tam esi runājis, sacīdams: tev netrūks vīra Manā priekšā, kas sēdēs Israēla goda krēsla, ja tikai tavi dēli sargās savu ceļu, staigādami Manā bauslībā, kā tu esi staigājis Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Tad nu, Kungs, Israēla Dievs, lai jel Tavs vārds tiešām notiek, ko Tu esi runājis Savam kalpam Dāvidam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Jo vai Dievs tiešām dzīvo pie cilvēkiem virs zemes? Redzi, debesis un visu debesu debesis tevi nevar saņemt, ne vēl šis nams, ko es esmu cēlis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Tomēr, griezies pie Sava kalpa lūgšanām un pie viņa piesaukšanām, Kungs, mans Dievs, un klausi to saukšanu un lūgšanu, ko tavs kalps lūdz priekš Tava vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Lai Tavas acis ir atvērtas dienām naktīm pār šo namu, pār šo vietu, kur Tu esi solījis iecelt Savu vārdu, klausīt to lūgšanu, ko Tavs kalps lūgs šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Klausi tad Sava kalpa un Savu Israēla ļaužu sirds lūgšanu, ko tie lūgs šinī vietā, klausi no tās vietas, kur Tu mīti debesīs, ak klausi un piedod!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Ja kāds būs apgrēkojies pret savu tuvāko un viņam liks zvērēt un nodievoties, un kad šī zvērēšana nāks priekš Tava altāra šinī namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Tad klausi Tu no debesīm un dari un tiesā Savus kalpus un atmaksā tam bezdievīgam, dodams viņa ceļu uz viņa galvu, un taisno to taisno, dodams tam pēc viņa taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Un kad Tavi Israēla ļaudis būs kauti ienaidnieku priekšā, kad tie pret Tevi būs grēkojuši, un atgriezīsies un apliecinās Tavu vārdu un Tavā priekšā pielūgs un no sirds piesauks šai namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Tad klausi Tu no debesīm un piedod Savu Israēla ļaužu grēkus un ved tos atpakaļ uz to zemi, ko Tu tiem un viņu tēviem esi devis. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Kad debess būs aizslēgta, ka lietus nelīs, tāpēc ka tie pret Tevi būs apgrēkojušies, un tie šinī vietā lūgs un Tavam vārdam dos godu un atgriezīsies no Saviem grēkiem, kad Tu tos apbēdini,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Tad klausi Tu debesīs un piedod Savu kalpu un Savu Israēla ļaužu grēkus, ka Tu tiem rādi to labo ceļu, kur tiem būs staigāt, un lietu dodi tai zemē, ko Tu saviem ļaudīm devis par mantību. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Kad zemē būs bada laiks, mēris, bula laiks, rūsa, siseņi un kukaiņi, kad viņu ienaidnieks zemē lauzīsies pret viņu vārtiem, vai būs kāda cita mocība vai sērga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Kas tad lūgs, kas no sirds piesauks, lai būtu kas būdams no visiem Taviem Israēla ļaudīm, kad tie atzīs savas mokas un bēdas un izpletīs savas rokas šinī namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Tad klausi Tu no debesīm, no tās vietas, kur Tu mīti, un piedod un dari un dod ikkatram pēc visiem viņa ceļiem, itin kā Tu viņa sirdi pazīsti, jo Tu vien pazīsti cilvēku bērnu sirdis; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Lai tie tēvi bīstas un arvienu staigā Tavos ceļos, kamēr tie dzīvo tai zemē, ko Tu mūsu tēviem esi devis. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Kad arī kāds svešinieks būs, kas nav no Taviem Israēla ļaudīm, bet nāk no tālas zemes Tava lielā vārda pēc un Tavas stiprās rokas un Tava izstiepta elkoņa dēļ, un kad tas nāks un šinī namā pielūgs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Tad klausi Tu no debesīm, no tās vietas, kur Tu mīti, un dari visu, par ko tas svešais Tevi piesauks, lai visas pasaules ļaudis atzīst Tavu vārdu un Tevi bīstas, tāpat kā Tavi Israēla ļaudis, un lai tie zina, ka Tavs vārds ir saukts pār šo namu, ko es esmu cēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Kad Tavi ļaudis ies karā pret saviem ienaidniekiem, pa to ceļu, kur Tu tos sūtīsi, un Tevi pielūgs, vaigu griezuši uz šo pilsētu, ko Tu esi izredzējies, un pret šo namu, ko es esmu cēlis Tavam vārdam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Tad klausi Tu no debesīm viņu lūgšanas un viņu sirds saukšanas un nes viņiem tiesu. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Kad tie pret Tevi būs apgrēkojušies (jo nav neviena cilvēka, kas nebūtu grēkojis), un Tu pār tiem būsi apskaities un tos nodosi ienaidniekiem, ka viņu uzvarētāji tos noved cietumā ienaidnieku zemē, vai tālu vai tuvu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Un tie tai zemē, kur ir aizvesti cietumā to atkal ņems pie sirds un atgriezīsies un Tevi piesauks sava cietuma zemē, sacīdami: mēs esam grēkojuši un noziegušies, mēs esam bijuši bezdievīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Un kad tie pie Tevis atgriežas no visas savas sirds un no visas savas dvēseles sava cietuma zemē, kur tie cietumā top turēti, un tie Tevi pielūgs, vaigu griezuši uz savu zemi, ko Tu devis viņu tēviem, uz to pilsētu, ko Tu esi izredzējies, un pret to namu, ko esmu cēlis Tavam vārdam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Tad klausi Tu no debesīm, no tās vietas, kur Tu mīti, viņu lūgšanu un viņu sirds saukšanu un nes tiem tiesu un piedod Saviem ļaudīm, ko tie pret Tevi grēkojuši. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nu, mans Dievs, lai jel Tavas acis ir atvērtas, un Tavas ausis klausās uz to lūgšanu šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Un nu celies šurp, Kungs Dievs, Savā dusas vietā, Tu un Tava spēka šķirsts; lai Tavi priesteri, Kungs Dievs, top apģērbti ar svētību, un Tavi svētie lai priecājās par labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Kungs Dievs, neatmet Sava svaidītā vaigu, piemini to žēlastību, kas solīta Dāvidam, Tavam kalpam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Kad nu Salamans bija beidzis to lūgšanu, tad uguns krita no debesīm un norija tos dedzināmos upurus un kaujamos upurus, un Tā Kunga godība piepildīja to namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Un priesteri nevarēja ieiet Tā Kunga namā, jo Tā Kunga godība bija piepildījusi Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Un kad visi Israēla bērni redzēja to uguni nokrītam un Tā Kunga godību nonākam pār to namu, tad tie nometās uz savu vaigu pie zemes uz grīdu un pielūdza un teica To Kungu, ka Viņš labs, ka Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Un ķēniņš un visi ļaudis upurēja upurus Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Un ķēniņš Salamans upurēja divdesmit divi tūkstošus vēršus un simts divdesmit tūkstoš avis. Tā ķēniņš un visi ļaudis iesvētīja Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Un priesteri stāvēja savā kalpošanā un Leviti ar Tā Kunga spēlējamiem rīkiem, ko ķēniņš Dāvids bija taisījis, To Kungu slavēt, ka Viņa žēlastība paliek mūžīgi, ar Dāvida dziesmām, ko tie dziedāja, un priesteri pūta ar trumetēm viņiem pretī, un viss Israēls stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Un Salamans svētīja to iekšpagalmu Tā Kunga nama priekšā, jo viņš tur upurēja dedzināmos upurus un pateicības upuru taukus. Jo tas vara altāris, ko Salamans bija taisījis, nevarēja saņemt tos dedzināmos upurus un ēdamos upurus un taukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Un Salamans tanī laikā svinēja svētkus septiņas dienas, un viss Israēls līdz ar viņu, varen liela draudze, no Hamatas līdz Ēģiptes upei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Un astotā dienā tie turēja svētku sapulci, jo to altāri tie iesvētīja septiņas dienas, ir svētkus tie turēja septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Bet divdesmit trešā dienā, septītā mēnesī viņš tos ļaudis atlaida uz viņu mājām, priecīgus un ar labu prātu par to labumu, ko Tas Kungs bija darījis Dāvidam un Salamanam un Saviem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Tā Salamans pabeidza Tā Kunga namu un ķēniņa namu; un viss ko Salamans bija iedomājies taisīt Tā Kunga namā un savā paša namā, tas viņam izdevās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Un Tas Kungs parādījās Salamanam naktī un uz to sacīja: Es esmu paklausījis tavu lūgšanu un šo vietu izredzējis Sev par upuru namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Redzi, kad Es debesis aizslēgšu, ka lietus nebūs, vai kad Es pavēlēšu siseņiem zemi noēst, vai kad Es sūtīšu mēri Saviem ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Un Mani ļaudis, pār kuriem Mans vārds ir saukts, pazemosies un pielūgs un meklēs Manu vaigu un atgriezīsies no saviem ļauniem ceļiem, tad Es no debesīm gribu klausīt un piedot viņu grēkus un dziedināt viņu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Tad nu Manas acis būs atvērtas, un Manas ausis klausīsies uz to lūgšanu šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Jo Es nu esmu izredzējis šo namu un to svētījis, ka Manam vārdam tur būs būt mūžīgi, un Manas acis un Mana sirds tur būs vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Un nu, ja tu staigāsi Manā priekšā, kā tavs tēvs Dāvids staigājis, un darīsi, kā Es tev esmu pavēlējis, un turēsi Manus likumus un Manas tiesas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Tad Es apstiprināšu tavu valstības krēslu, itin kā Es derību esmu derējis ar tavu tēvu Dāvidu, sacīdams: tev nekad netrūks vīra, kas valdīs pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Bet ja jūs atkāpsities un atstāsiet Manus likumus un Manus baušļus, ko Es jums esmu devis, un iesiet un kalposiet svešiem dieviem un metīsities zemē priekš tiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Tad Es tos izsakņošu no Savas zemes, ko Es tiem esmu devis, un atmetīšu no Sava vaiga šo namu, ko Es esmu svētījis Savam vārdam, un to darīšu par sakāmu vārdu un apsmieklu starp visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Un par šo namu, kas tik augsts bijis, visiem, kas iet garām, būs iztrūcināties un sacīt: kāpēc Tas Kungs tā ir darījis šai zemei un šim namam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Tad sacīs: tāpēc ka tie atstājuši To Kungu, savu tēvu Dievu, kas tos izvedis no Ēģiptes zemes, un ir turējušies pie citiem dieviem un priekš tiem metušies zemē un tiem kalpojuši, - tādēļ Viņš pār tiem vedis visu šo ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Un pēc divdesmit gadiem, kad Salamans bija uztaisījis Tā Kunga namu un savu namu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Tad Salamans izbūvēja tās pilsētas, ko Hirams Salamanam bija devis, un lika Israēla bērniem tur dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Pēc tam Salamans cēlās uz HamatCovu un to pārvarēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Viņš arī uztaisīja Tadmoru tuksnesī un visas labības pilsētas, ko viņš Hamatā būvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Viņš arī uztaisīja kalna- un Lejas-BetOronu, stipras pilsētas ar mūriem, vārtiem un aizšaujamiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Un Baēlatu un visas labības pilsētas, kas Salamanam piederēja, un visas ratu un jātnieku pilsētas un visas Salamana prieka pilis, ko tam bija prieks taisīt Jeruzālemē un uz Lībanus un visās zemēs viņa valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Visus atlikušos ļaudis no Hetiešiem un Amoriešiem un Fereziešiem un Hiviešiem un Jebusiešiem, kas nebija no Israēla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Šo bērnus, kas pēc tiem tai zemē bija atlikuši, ko Israēla bērni nebija izdeldējuši, tos Salamans spieda pie klausības līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Bet no Israēla bērniem Salamans neņēma kalpus pie sava darba, bet tie bija karavīri un virsnieki pār viņa bruņiniekiem un viņa ratu un jātnieku virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Un virsuzraugu ķēniņam Salamanam bija divsimt un piecdesmit, kas pār tiem ļaudīm valdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Un Salamans veda Faraona meitu no Dāvida pils tai namā, ko viņš tai bija taisījis. Jo viņš sacīja: manai sievai nebūs Israēla ķēniņa Dāvida namā dzīvot, tāpēc ka tā vieta ir svēta, kur Tā Kunga šķirsts nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tad Salamans upurēja Tam Kungam dedzināmos upurus uz Tā Kunga altāra, ko viņš priekšnama priekšā bija uztaisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Ikkatrā dienā savu tiesu upurēdams, itin kā Mozus bija pavēlējis, svētdienās un jaunos mēnešos un svētkos, trīs reiz gadskārtā, neraudzētās maizes svētkos un nedēļu svētkos un lieveņu svētkos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Un viņš iestādīja pēc sava tēva Dāvida likuma priesteru kārtas, kā tiem bija kalpot, un Levitus, kopt savu kopjamo, slavēt un kalpot priesteru priekšā, kas katrai dienai piekrita, arī vārtu sargus pēc savas kārtas pie ikkatriem vārtiem, jo tā bija Dāvida, Tā Dieva vīra, pavēle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Un no ķēniņa pavēles par priesteriem un Levitiem viņi neatkāpās ne kādā lietā, arī ne pie tām mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Tā Salamans pabeidza visu savu darbu, no tās dienas, kad Tā Kunga namam lika pamatu, līdz kamēr to pabeidza un Tā Kunga nams pavisam bija gatavs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tad Salamans gāja uz EceonĢeberu un uz Elotu jūrmalā, Edoma zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Un Hirams tam sūtīja caur saviem kalpiem lielas laivas, un kalpus, kas jūru pārzināja, un tie gāja ar Salamana kalpiem uz Ofiru un atveda no turienes četrsimt un piecdesmit talentus zelta un to nesa ķēniņam Salamanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Un kad Sabas ķēniņiene dzirdēja Salamana slavu, tad tā nāca, pārbaudīt Salamanu ar mīklām, uz Jeruzālemi ar varen lielu pulku, ir ar kamieļiem, kas nesa kvēpināmās zāles un daudz zelta un dārgus akmeņus. Un viņa nāca pie Salamana un runāja ar to visu, ko bija apņēmusies savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Un Salamans viņai atbildēja uz visiem viņas vārdiem, un nekas Salamanam nebija paslēpts, ko viņš tai nebūtu teicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Kad nu Sabas ķēniņiene redzēja Salamana gudrību un to namu, ko viņš bija uzcēlis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Un viņa galda ēdienus un viņa kalpu dzīvokļus un viņa sulaiņu amatu un viņu drēbes un viņa dzēriena devējus un viņu drēbes un viņa uzejamo vietu, kur viņš gāja Tā Kunga namā, tad viņa tikko nepalika bez dvašas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Un sacīja uz ķēniņu: tas ir tiesa, ko es savā zemē esmu dzirdējusi no tavām lietām un no tavas gudrības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Bet es viņu vārdiem neticēju, kamēr es pati nācu un manas acis redzēja; un redzi, man nav ne puse teikta no visas tavas lielās gudrības; tev ir vairāk, nekā tā slava, ko es dzirdēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Svētīgi tavi ļaudis un svētīgi šie tavi kalpi, kas vienmēr stāv tavā priekšā un dzird tavu gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Slavēts lai ir Tas Kungs, tavs Dievs, kam labs prāts bijis pie tevis, sēdināt tevi uz savu goda krēslu par ķēniņu Tam Kungam, tavam Dievam. Tāpēc ka tavs Dievs Israēli mīļo, gribēdams to uzturēt mūžīgi, viņš tevi iecēlis pār tiem, darīt tiesu un taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Un viņa deva ķēniņam simts un divdesmit talentus zelta un kvēpināmās zāles un dārgus akmeņus lielā pulkā, un tādu zāļu nav bijis kā šīs, ko Sabas ķēniņiene deva ķēniņam Salamanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Tāpat arī Hirama kalpi un Salamana kalpi, kas zeltu nesa no Ofira, atnesa arī algumim kokus un dārgus akmeņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Un ķēniņš no tiem algumim kokiem taisīja trepes Tā Kunga namā un ķēniņa namā, ir kokles un somastabules koklētājiem. Tādi (koki) citkārt nebija redzēti Jūdu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Un ķēniņš Salamans deva Sabas ķēniņienei visu, ko tā gribēja un lūdza, bez tā, ko tā ķēniņam bija atnesusi, Un tā griezās atpakaļ un gāja ar saviem kalpiem uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Un tas zelta svars, kas Salamanam ikgadus ienāca, bija sešsimt sešdesmit seši talenti zelta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Bez tā, ko viņš dabūja no tirgotājiem un veikalniekiem; ir visi Arābijas ķēniņi un zemes lielkungi nesa Salamanam zeltu un sudrabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Un ķēniņš Salamans taisīja divsimt priekšturamās bruņas no kalta zelta, - sešsimt zelta gabalus viņš deva priekš ikvienām priekšturamām bruņām, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Un trīssimt sedzamas bruņas no kalta zelta, - tur viņš deva trīs simt gabalus zelta priekš ikvienām bruņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Un ķēniņš tās ielika Lībanus koku namā. Un ķēniņš taisīja lielu krēslu no ziloņkauliem un to pārvilka ar tīru zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Šim krēslam bija seši pakāpieni un viens kāju pamesls no zelta, kas pie tā krēsla bija piestiprināts, un abējās pusēs tam bija lēnes pie sēdekļa, un divas lauvas stāvēja pie tām lēnēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Un divpadsmit lauvas stāvēja tur uz tiem sešiem pakāpieniem abējās pusēs. Tāds nekādā valstībā nav taisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Un visi ķēniņa Salamana dzeramie trauki bija no zelta un visi trauki Lībanus koku namā bija no tīra zelta, - sudrabu Salamana laikā neko necienīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Jo ķēniņa kuģi gāja uz Taršišu ar Hirama kalpiem; tie Taršiša kuģi pa trim gadiem vienreiz pārnāca un pārveda zeltu un sudrabu un ziloņkaulus un pērtiķus un pāvus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Tā ķēniņš Salamans tapa lielāks, nekā visi ķēniņi virs zemes, bagātībā un gudrībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Un visi ķēniņi virs zemes meklēja Salamana vaigu, viņa gudrību dzirdēt, ko Dievs tam bija devis sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Un tie atnesa ikkatrs savas dāvanas, sudraba un zelta traukus un drēbes un bruņas un dārgas zāles, zirgus un zirgēzeļus ik gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Un Salamanam bija četrtūkstoš zirgu stelinģu un divpadsmit tūkstoš jātnieki, un viņš tos lika ratu pilsētās un pie ķēniņa Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Un viņš valdīja pār visiem ķēniņiem no lielupes līdz Fīlistu zemei un līdz Ēģiptes robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Un ķēniņš darīja, ka tik daudz sudraba bija Jeruzālemē kā akmeņu, un ciedru koku tik daudz, kā meža vīģes koku ielejās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Un Salamanam atveda zirgus no Ēģiptes un no citām zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Un kas vēl atliek par Salamana lietām, gan pirmās, gan pēdējās, tas viss rakstīts pravieša Nātana laiku grāmatā un Ahijas, tā Šilonieša, pravieša vārdos un Jedus, tā redzētāja, parādīšanās pret Jerobeamu, Nebata dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Un Salamans valdīja Jeruzālemē pār visu Israēli četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Un Salamans aizmiga pie saviem tēviem, un to apraka viņa tēva Dāvida pilī, un viņa dēls Rekabeams palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Un Rekabeams gāja uz Šehemi, jo viss Israēls Šehemē bija sanācis, viņu celt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Kad nu Jerobeams, Nebata dēls, to dzirdēja (jo viņš bija Ēģiptes zemē, kurp no ķēniņa Salamana bija bēdzis), tad Jerobeams griezās atpakaļ no Ēģiptes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Un tie nosūtīja un to ataicināja. Un Jerobeams nāca ar visu Israēli un runāja uz Rekabeamu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Tavs tēvs mums uzlicis par daudz grūtu jūgu; tad nu atvieglini tu sava tēva grūto kalpošanu un viņa smago jūgu, ko viņš mums uzlicis, tad mēs tev kalposim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Un viņš uz tiem sacīja: pēc trim dienām nāciet atkal pie manis. Un tie ļaudis aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Un ķēniņš Rekabeams meklēja padomu pie tiem vecajiem, kas bija stāvējuši viņa tēva Salamana priekšā, kamēr tas dzīvoja, un viņš sacīja: kādu padomu jūs dodat, kā šiem ļaudīm būs atbildēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Un tie uz viņu runāja un sacīja: ja tu būsi laipnīgs pret šiem ļaudīm un tiem rādīsi labu prātu un uz tiem runāsi labus vārdus, tad tie tev būs par kalpiem visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Bet viņš atmeta to vecaju padomu, ko tie viņam deva, un meklēja padomu pie tiem jauniem, kas ar viņu bija uzauguši un viņa priekšā stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Un viņš uz tiem sacīja: kādu padomu jūs dodat, kā šiem ļaudīm lai atbildam, kas uz mani runājuši un sacījuši: atvieglini to jūgu, ko tavs tēvs mums uzlicis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Bet tie jaunie, kas ar viņu bija uzauguši, uz to runāja un sacīja: tā tev būs sacīt uz tiem ļaudīm, kas uz tevi runājuši un sacījuši: tavs tēvs mums uzlicis visai grūtu nastu, atvieglini tu mums to, - tā tev uz tiem būs sacīt: mans mazais pirksts būs resnāks ne kā mana tēva gurni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Ja nu mans tēvs jums uzlicis grūtu jūgu, tad es to jūgu jums padarīšu vēl grūtāku; mans tēvs jūs pārmācījis ar pātagām, bet es jūs pārmācīšu ar skorpioniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Kad nu Jerobeams un visi ļaudis pie Rekabeama atnāca trešā dienā, kā ķēniņš bija runājis un sacījis: atnākat atkal pie manis trešā dienā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Tad ķēniņš tiem atbildēja bargi, un ķēniņš Rekabeams atmeta to vecaju padomu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Un runāja uz tiem pēc to jauno padoma un sacīja: mans tēvs jums uzlicis grūtu nastu, bet es jums uzlikšu vēl vairāk; mans tēvs jūs pārmācījis ar pātagām, bet es ar skorpioniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Tā ķēniņš neklausīja tos ļaudis, jo tā bija no Dieva nolikts, ka Tas Kungs savus vārdus apstiprinātu, ko bija runājis caur Ahiju, to Šīlonieti, uz Jerobeamu, Nebata dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Kad nu viss Israēls redzēja, ka ķēniņš tos neklausīja, tad tie ļaudis ķēniņam atbildēja un sacīja: kāda daļa mums ar Dāvidu? Mums nav mantības pie Isajus dēla. Israēl, ej savos dzīvokļos; tad redzi nu tu pēc sava nama, Dāvid! Tā viss Israēls nogāja savos dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Bet pār tiem Israēla bērniem, kas Jūda pilsētās dzīvoja, pār tiem Rekabeams palika ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Un ķēniņš Rekabeams sūtīja Adoramu, kas bija iecelts pār darbiniekiem, bet Israēla bērni to nomētāja akmeņiem, ka tas nomira. Un ķēniņš Rekabeams kāpa steigšus ratos, bēgt uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Tā Israēls atkāpās no Dāvida nama līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Un Jeruzālemē nonācis Rekabeams sapulcināja Jūda un Benjamina namu, simts un astoņdesmit tūkstoš jaunus, izlasītus karavīrus, karot pret Israēli, lai valstība atkal tiktu Rekabeamam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Bet Tā Kunga vārds notika uz Šemaju, Dieva vīru, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Runā uz Rekabeamu, Salamana dēlu, Jūda ķēniņu, un uz visu Israēli Jūdā un Benjaminā un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Tā saka Tas Kungs: jums nebūs iet pret saviem brāļiem karot; griežaties atpakaļ ikkatrs savās mājās, jo šī lieta no manis notikusi. Un tie klausīja Tā Kunga vārdus un griezās atpakaļ no tā ceļa pret Jerobeamu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Un Rekabeams dzīvoja Jeruzālemē un uztaisīja pilsētas par stipram pilīm Jūdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Un viņš uztaisīja Bētlemi un Etamu un Tekou');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Un Betcuru un Zoku un Adulamu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Un Gatu un Marezu un Zivu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Un Adoraīmu un Laķisu un Azeku');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Un Careju un Ajalonu un Hebroni, kas Jūdā un Benjaminā bija stipras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Un viņš darīja šās stiprās pilis vēl stiprākas un lika tanīs virsniekus, sakrāja tur barību, eļļu un vīnu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Un ikkatrā pilsētā viņš ielika priekšturamās bruņas un šķēpus un darīja tās ļoti stipras; tā Jūda un Benjamins viņam piederēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Un tie priesteri un Leviti, kas bija starp visu Israēli, atnāca pie viņa no visām savām robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Jo Leviti atstāja savus apgabalus un savu dzīvi un gāja uz Jūdu un Jeruzālemi; jo Jerobeams un viņa dēli tos izdzina, lai tie Tam Kungam vairs nebūtu par priesteriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Un viņš sev iecēla priesterus priekš tiem kalna altāriem un jodiem un teļiem, ko viņš bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Un viņiem gāja pakaļ uz Jeruzālemi arī no visām Israēla ciltīm, kas savu sirdi nodeva, meklēt To Kungu, Israēla Dievu, un upurēt Tam Kungam, savu tēvu Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Tā tie darīja spēcīgu Jūda valstību un stiprināja Rekabeamu, Salamana dēlu, trīs gadus; jo trīs gadus tie staigāja Dāvida un Salamana ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Un Rekabeams ņēma par sievu Maēlatu, Jerimota, Dāvida dēla, meitu, un Abikaīlu, Elijaba, Isajus dēla, meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Tā tam dzemdēja dēlus: Jeū, Zemariju un Zaāmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Un pēc tās viņš ņēma Maēku, Absaloma meitu; tā tam dzemdēja Abiju un Ataju un Zizu un Šelomitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Un Rekabeams mīlēja Maēku, Absaloma meitu, vairāk nekā visas savas sievas un liekās sievas; jo viņš bija ņēmis astoņpadsmit sievas un sešdesmit liekas sievas, un dzemdināja divdesmitastoņus dēlus un sešdesmit meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Un Rekabeams iecēla Abiju, Maēkas dēlu, par virsnieku un lielkungu starp viņa brāļiem; jo viņš domāja, to celt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Un viņš turējās gudri un izdalīja visus savus dēlus pa visām Jūda un Benjamina valstīm visās stiprās pilsētās, un deva tiem barības papilnam un ņēma tiem pulku sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Kad nu Rekabeams valstību bija stiprinājis un pats bija palicis stiprs, tad viņš atstāja Tā Kunga bauslību un viss Israēls līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Un ķēniņa Rekabeama piektā gadā Zizaks, Ēģiptes ķēniņš, cēlās pret Jeruzālemi (jo tie bija apgrēkojušies pret To Kungu)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Ar tūkstoš un divsimt ratiem un ar sešdesmit tūkstoš jātniekiem, un to ļaužu bija neizskaitāms pulks, kas ar viņu nāca no Ēģiptes: Lībieši, Zuķieši un Moru ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Un viņš uzņēma tās stiprās pilsētas, kas bija Jūdā, un nāca līdz Jeruzālemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Tad pravietis Šemaja nāca pie Rekabeama un pie Jūda lielkungiem, kas Zizaka dēļ Jeruzālemē bija sapulcējušies, un uz tiem sacīja: tā saka Tas Kungs: jūs Mani esat atstājuši, tāpēc Es jūs arīdzan esmu atstājis Zizaka rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Tad Israēla lielkungi un ķēniņš pazemojās un sacīja: Tas Kungs ir taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Kad nu Tas Kungs redzēja, ka tie pazemojās, tad Tā Kunga vārds notika uz Šemaju sacīdams: tie ir pazemojušies, Es tos negribu izdeldēt, bet Es tos gan drīz izglābšu un neizgāzīšu Savu bardzību pār Jeruzālemi caur Zizaka roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Bet tiem būs viņam par kalpiem būt, lai tie atzīst, kas tas ir Man kalpot, un kas tas ir pasaules ķēniņiem kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Tad Zizaks, Ēģiptes ķēniņš, nāca pret Jeruzālemi un paņēma Tā Kunga nama mantas un ķēniņa nama mantas, visu viņš paņēma; viņš paņēma arī tās zelta priekšturamās bruņas, ko Salamans bija taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Un ķēniņš Rekabeams taisīja viņu vietā priekšturamās vara bruņas un tās iedeva pils karavīru virsniekiem rokā, kas vakti turēja priekš ķēniņa nama durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Kad nu ķēniņš Tā Kunga namā gāja, tad tie pils karavīri nāca un tās nesa, un pēc tie tās atnesa atpakaļ pils karavīru kambarī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Un kad tas pazemojās, tad Tā Kunga bardzība no tā novērsās, ka Viņš to pavisam neizdeldēja; jo iekš Jūda vēl bija kāds labums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Un ķēniņš Rekabeams stiprinājās Jeruzālemē un valdīja. Jo Rekabeams bija četrdesmit vienu gadu vecs, kad tas palika par ķēniņu un valdīja septiņpadsmit gadus Jeruzālemē, tai pilsētā, ko Tas Kungs no visām bija izredzējis, tur likt Savu vārdu, un viņa mātei bija vārds Naēma, Amoniete.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Un viņš darīja ļaunu, jo viņa sirds nebija pastāvīga, To Kungu meklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Un tie stāsti par Rekabeamu, gan pirmie, gan pēdējie, tie rakstīti pravieša Šemajas un redzētāja Idus grāmatās, radu rakstos. Un Rekabeama un Jerobeama kari nemitējās visā viņu mūžā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Un Rekabeams aizmiga pie saviem tēviem un tapa aprakts Dāvida pilī; un Abija, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Ķēniņa Jerobeama astoņpadsmitā gadā Abija palika par ķēniņu pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Viņš valdīja trīs gadus Jeruzālemē, un viņa mātei bija vārds Mikaja, Uriēļa meita no Ģibejas. Un karš cēlās starp Abiju un Jerobeamu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Un Abija taisījās uz karu ar varenu kara spēku, ar četrsimt tūkstoš izlasītiem vīriem. Un Jerobeams taisījās pret viņu uz karu ar astoņsimt tūkstoš izlasītiem stipriem kara vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Un Abija uzkāpa uz Cemaraim kalnu Efraīma kalnos un sacīja: klausiet mani, Jerobeam un viss Israēl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Vai jums nav zināms, ka Tas Kungs, Israēla Dievs, valdību pār Israēli devis Dāvidam uz mūžīgiem laikiem, ir viņam, ir viņa dēliem caur sāls (neiznīkstamu) derību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Taču Jerobeams, Nebata dēls, Salamana Dāvida dēla, kalps, sacēlis dumpi pret savu kungu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Un pie viņa sapulcējušies nelieši, netikli ļaudis, un pret Rekabeamu, Salamana dēlu, palikuši stipri, kamēr Rekabeams vēl bija jauns un tam bija bailīga sirds, ka pret viņiem nevarēja turēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Un nu jūs domājat stipri būt pret Tā Kunga valstību Dāvida dēlu rokā; jūs gan esat liels pulks, bet pie jums ir zelta teļi, ko Jerobeams jums cēlis par dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Vai jūs Tā Kunga priesterus, Ārona dēlus, tos Levitus, neesat izdzinuši un neesat sev priesterus cēluši, kā pasaules tautas? Ikviens, kas nāk savu roku pildīdams ar jaunu vērsi un septiņiem auniem, tas top par priesteri tādiem, kas nav dievi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Bet ar mums ir Tas Kungs, mūsu Dievs, un mēs Viņu neesam atstājuši, un tie priesteri, kas Tam Kungam kalpo, ir Ārona dēli, un Leviti savā kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Un tie Tam Kungam iededzina dedzināmos upurus ik rītu un ik vakaru, arī saldas kvēpināmās zāles, un liek to (svēto) maizi uz to šķīsto galdu; un tur ir tas zelta lukturis ar saviem eļļas lukturīšiem, kas ik vakaru top iededzināti; jo mēs turam Tā Kunga, sava Dieva, likumus, bet jūs Viņu esat atstājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Un nu redzi, Dievs ir ar mums pašā priekšā un Viņa priesteri ar skanīgām bazūnēm, bazūnēt pret jums. Jūs, Israēla bērni nekarojat ar To Kungu, savu tēvu Dievu; jo tas jums neizdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Bet Jerobeams karavīriem lika slepeni apiet apkārt, tiem uzbrukt mugurā, un tā viņi stāvēja Jūda priekšā, un tie glūnētāji viņiem mugurā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Kad nu Jūda atpakaļ skatījās, redzi, tad karš tiem bija priekšā un mugurā. Un tie piesauca To Kungu, un priesteri bazūnēja ar bazūnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Un Jūda vīri kliedza. Un kad Jūda vīri tā kliedza, tad Dievs kāva Jerobeamu un visu Israēli Abijas un Jūda priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Un Israēla bērni bēga Jūda priekšā, un Dievs tos deva viņu rokā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Un Abija ar saviem ļaudīm tos sakāva lielā kaušanā, un no Israēla krita nokauti piecsimt tūkstoš izlasīti vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Tā Israēla bērni tanī laikā tapa pazemoti, bet Jūda bērni tapa vareni, tāpēc ka tie bija paļāvušies uz To Kungu, savu tēvu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Un Abija dzinās Jerobeamam pakaļ un ieņēma viņa pilsētas: Bēteli ar viņas miestiem un Jēzanu ar viņas miestiem, un Efronu ar viņas miestiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Un Jerobeams vairs netika pie spēka Abijas laikā, bet Tas Kungs to sita, un tas nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Un Abija palika spēcīgs un apņēma četrpadsmit sievas un dzemdināja divdesmit divus dēlus un sešpadsmit meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Un kas vēl par Abiju stāstāms, viņa ceļi un viņa vārdi, tie rakstīti pravieša Idus stāstos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Un Abija aizmiga pie saviem tēviem, un to apraka Dāvida pilī; un viņa dēls Asa palika par ķēniņu viņa vietā. Viņa laikā zemei bija miers desmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Un Asa darīja, kas bija pareizi un Tam Kungam, viņa Dievam, labi patika,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Un izdeldēja svešo dievu altārus un elku kalnus un nolauzīja tēlu stabus un nocirta Ašeras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Un pavēlēja, lai Jūda meklē To Kungu, savu tēvu Dievu, un dara bauslību un pavēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Un viņš izdeldēja no visām Jūda pilsētām elku kalnus un dievekļus, jo valsts apakš viņa bija mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Viņš arī uzcēla stipras pilsētas iekš Jūda, jo zeme bija mierā, un tanīs gados karš pret viņu nebija, jo Tas Kungs viņam deva mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Un viņš sacīja uz Jūdu: uzcelsim šīs pilsētas un mūrēsim mūrus apkārt un torņus, un taisīsim vārtus un aizšaujamos; vēl tā zeme mums pieder; jo mēs To Kungu, savu Dievu, esam meklējuši, mēs esam meklējuši, un viņš mums visapkārt devis mieru. Tā tie būvēja un tiem labi izdevās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Un Asam bija karaspēks, trīssimt tūkstoši no Jūda ar šķēpiem un priekšturamām bruņām, un no Benjamina divsimt astoņdesmit tūkstoši ar priekšturamām bruņām un stopiem, šie visi bija stipri varoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Un pret tiem cēlās Zerus, Moru ķēniņš, ar karaspēku, ar tūkstoš reiz tūkstošiem un ar trīs simt ratiem, un atnāca līdz Marezai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Bet Asa tiem izgāja pretī, un tie nostājās uz kauju Cevatas ielejā pie Marezas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Un Asa piesauca To Kungu, savu Dievu, un sacīja: Kungs, neviena nav kā Tu, kas var palīdzēt nespēcīgam pret stipro. Palīdzi mums, Kungs, mūsu Dievs, jo mēs paļaujamies uz Tevi un Tavā vārdā esam nākuši pret šo lielo pulku. Kungs! Tu esi mūsu Dievs, pret Tevi neviens cilvēks neko neiespēj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Un Tas Kungs sita tos Moru ļaudis priekš Asas un priekš Jūda, un tie Moru ļaudis bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Bet Asa un tie ļaudis, kas pie tā bija, tiem dzinās pakaļ līdz Ģerarai, un tie Moru ļaudis krita, ka neviens no tiem nepalika dzīvs; jo tie tapa satriekti priekš Tā Kunga un priekš viņa kara spēka, un viņi dabūja ļoti daudz laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Un viņi kāva visas pilsētas ap Ģeraru, jo bailes no Tā Kunga bija uz tiem nākušas; un tie aplaupīja visas pilsētas, tāpēc ka tur bija daudz laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Tie kāva arī lopu teltis un aizveda avis un kamieļus, lielu pulku, un pārnāca atkal Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Tad Dieva Gars nāca uz Azariju, Odeda dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Un tas izgāja Asam pretī un uz to sacīja: klausiet mani, Asa un viss Jūda un Benjamin. Tas Kungs ir ar jums, kamēr jūs esat ar Viņu, un ja jūs Viņu meklēsiet, Viņš no jums taps atrasts. Bet ja jūs Viņu atstāsiet, tad Viņš jūs arīdzan atstās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Un daudz dienas būs iekš Israēla bez īsta Dieva, bez priestera, kas māca, un bez bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Taču ja tie savās bēdās atgriezīsies pie Tā Kunga, Israēla Dieva, un Viņu meklēs, tad Viņš no tiem taps atrasts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Un tanīs laikos labi neklāsies ne tam, kas iziet, ne tam, kas ieiet, bet daudz briesmu būs pār zemes iedzīvotājiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Tā ka tauta celsies pret tautu, pilsēta sadauzīs pilsētu, jo Dievs tos iztrūcinās ar visādām bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Bet jūs esat droši, un jūsu rokas lai nenogurst, jo jūsu darbam būs sava alga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Kad nu Asa dzirdēja šos vārdus un pravieša Odeda(dēla) sludināšanu, tad viņš ņēmās drošu prātu un izdeldēja tās negantības no visas Jūda un Benjamina zemes un no tām pilsētām, ko bija uzņēmis Efraīma kalnos, un atjaunoja Tā Kunga altāri, kas priekš Tā Kunga priekšnama stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Un viņš sapulcināja visu Jūdu un Benjaminu un tos, kas pie viņiem piemita, no Efraīma un Manasus un no Sīmeana; jo no Israēla tam daudzi pieķērās, kad tie redzēja, ka Tas Kungs, viņa Dievs bija ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Un tie sapulcējās Jeruzālemē trešā mēnesī, Asas valdīšanas piecpadsmitā gadā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Un upurēja Tam Kungam tai dienā no tā laupījuma, ko tie bija atveduši, septiņsimt vēršus un septiņtūkstoš avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Un tie atjaunoja to derību, meklēt To Kungu, savu tēvu Dievu no visas savas sirds un no visas savas dvēseles;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Bet visus, kas nemeklē To Kungu, Israēla Dievu, nokaut, tā mazus kā lielus, tā vīrus kā sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Un tie Tam Kungam zvērēja ar stipru balsi un gavilēšanu, arī ar trumetēm un bazūnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Un viss Jūda priecājās par šo zvērestu, jo tie no visas sirds bija zvērējuši un meklēja Viņu ar visu prātu, un Viņš no tiem likās atrasties, un Tas Kungs tiem deva mieru visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Viņš arī nocēla Maēku, ķēniņa Asas vecmāti, no ķēniņienes goda, tāpēc ka tā bija taisījusi negantu elka bildi Ašerai, un Asa izdeldēja arī viņas elka bildi un to sadauzīja un sadedzināja pie Kidronas upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Bet kalnu altāri netapa izdeldēti iekš Israēla, tikai Asas sirds bija skaidra visu viņa mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Un viņš ienesa Dieva namā visas sava tēva svētītās dāvanas, un ko viņš pats bija svētījis, sudrabu un zeltu un traukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Un kara nebija līdz trīsdesmit piektam Asas valdīšanas gadam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Asas trīsdesmit sestā valdīšanas gadā Baeša, Israēla ķēniņš, cēlās pret Jūdu un uztaisīja Rāmu, ka viņš nevienam neļautu ne iziet nedz ieiet pie Asas, Jūda ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Tad Asa ņēma sudrabu un zeltu no Tā Kunga nama un no ķēniņa nama mantām, un to sūtīja BenHadadam, Sīrijas ķēniņam, kas Damaskū dzīvoja, un lika sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Derība ir starp mani un tevi un starp manu tēvu un tavu tēvu; redzi, es tev sūtu sudrabu un zeltu: ej un lauz savu derību ar Baešu, Israēla ķēniņu, ka tas no manis atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Un BenHadads paklausīja ķēniņam Asam un sūtīja savus kara virsniekus pret Israēla pilsētām, un tie sita Ejonu un Danu un AbelMaīmu un visas Navtaļa labības pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Kad nu Baeša to dzirdēja, tad viņš mitējās Rāmu uztaisīt un atstāja savu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Tad ķēniņš Asa ņēma visu Jūdu, un tie nonesa akmeņus un kokus no Rāmas, ko Baeša bija taisījis, un viņš no tiem uzcēla Ģebu un Micpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Un tanī laikā Hananus, tas redzētājs, nāca pie Asas, Jūda ķēniņa, un uz to sacīja: tāpēc ka tu esi paļāvies uz Sīrijas ķēniņu un neesi paļāvies uz To Kungu, savu Dievu, tādēļ Sīrijas ķēniņa karaspēks no tavas rokas izsprucis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Vai Moru ļaudis un Libeji nebija liels karaspēks ar ļoti daudz ratiem un jātniekiem? Taču, kad tu uz To Kungu paļāvies, tad Viņš tos devis tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Jo Tā Kunga acis skatās pa visām zemēm, ka Viņš tos stiprina, kas ar skaidru sirdi pie viņa turas. Tu še esi aplam darījis; jo no šī laika būs kari pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Bet Asa apskaitās pret to redzētāju un to ielika cietumā; jo viņš par to palika ļauns pret viņu. Un Asa spaidīja kādus no tiem ļaudīm tanī laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Un redzi, tie stāsti par Asu, ir tie pirmie, ir tie pēdējie, ir rakstīti Jūda un Israēla ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Un savā trīsdesmit devītā valdīšanas gadā Asa palika slims ar kājām, un viņa slimība auga lielā augumā; viņš arī savā slimībā nemeklēja To Kungu, bet dziedniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Tā Asa aizmiga pie saviem tēviem un nomira savā četrdesmit pirmā valdīšanas gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Un to apraka viņa kapā, ko viņš priekš sevis bija licis rakt Dāvida pilī, un to lika uz gultu, ko ar dārgām zālēm un visādām kvēpināmām zālēm bija pildījuši pēc zāļotāju ziņas, un par viņu dedzināja (dārgas zāles) ar lielu dedzināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Un viņa dēls Jehošafats palika par ķēniņu viņa vietā un tas palika spēcīgs pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Un viņš ielika karavīrus visās stiprās Jūda pilsētās un karavīrus Jūda zemē un Efraīma pilsētās, ko viņa tēvs Asa bija uzņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Un Tas Kungs bija ar Jehošafatu, jo viņš staigāja sava tēva Dāvida pirmajos ceļos un nemeklēja Baālus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Bet viņš meklēja sava tēva Dievu un staigāja Viņa baušļos un ne pēc Israēla darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Tāpēc Tas Kungs apstiprināja to valstību viņa rokā, un visa Jūda valsts deva Jehošafatam dāvanas, un tam bija bagātības un godības papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Un viņa sirds pieņēmās Tā Kunga ceļos, un viņš nopostīja vēl elku kalnus un Ašeras no Jūda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Un savas valdīšanas trešā gadā viņš sūtīja savus lielkungus, Benkaēlu un Obadiju un Zahariju un Nataneēli un Mikaju, mācīt Jūdu pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Un ar tiem bija tie Leviti Šemaja un Neanija un Zebadija un Azaēls un Zemiramots un Jonatāns un Adonija un Tobija un TobAdonija, Leviti, un ar tiem Elišamus un Jorams, priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Un tie mācīja Jūdā, un Tā Kunga bauslības grāmata tiem bija līdz, un tie gāja apkārt visās Jūda pilsētās un mācīja ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Un bailes priekš Tā Kunga bija pār visām zemes valstīm apkārt ap Jūdu, ka tie pret Jehošafatu nekaroja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Un no Fīlistiem Jehošafatam atnesa dāvanas, pulka sudraba. Un Arābi viņam deva sīkus lopus septiņtūkstoš un septiņsimt aunus un septiņtūkstoš un septiņsimt āžus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Un Jehošafats arvienu auga lielā augumā un uzcēla Jūdā pilis un labības pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Un viņam bija daudz mantas Jūda pilsētās un varen stipri karavīri Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Un tā tie tapa skaitīti pēc viņu tēvu namiem: Jūdā bija virsnieki pār tūkstošiem: virsnieks Adnus, un tam bija trīs simt tūkstoš kara vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Viņam blakām bija virsnieks Johanans, un tam bija divsimt astoņdesmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Un tam blakām bija Amasija, Sihrus dēls, kas ar labu prātu Tam Kungam bija nodevies, un tam bija divsimt tūkstoš kara vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Un no Benjamina bija Elijadus, kara varonis, un tam bija divsimt tūkstoši ar stopiem un priekšturamām bruņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Un tam blakām bija Jozabads, un tam bija simts astoņdesmit tūkstoši uz karu gatavi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Šie kalpoja ķēniņam, bez tiem, ko ķēniņš bija ielicis stiprās pilsētās pa visu Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Un Jehošafatam bija daudz bagātības un godības un viņš palika rada Ahabam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Un pēc kādiem gadiem viņš nogāja pie Ahaba uz Samariju. Un Ahabs viņam un tiem ļaudīm, kas viņam bija līdz, kāva avis un vēršus lielu pulku, un to paskubināja iet pret Rāmotu Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Un Ahabs, Israēla ķēniņš, sacīja uz Jehošafatu, Jūda ķēniņu: vai tu gribi ar mani iet pret Rāmotu Gileādā? Un tas uz viņu sacīja: es būšu kā tu, un mani ļaudis, kā tavi ļaudis, un mēs iesim tev līdz karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Un Jehošafats sacīja uz Israēla ķēniņu: vaicā jel šodien Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Tad Israēla ķēniņš sapulcināja praviešus, četrsimt vīrus, un uz tiem sacīja: vai mums būs iet karā pret Rāmotu Gileādā, jeb vai man nebūs iet? Un tie sacīja: ej, jo Dievs to nodos ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Bet Jehošafats sacīja: vai šeitan vēl nav kāds no Tā Kunga praviešiem, ka tam varētu vaicāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Un Israēla ķēniņš sacīja uz Jehošafatu: vēl ir viens vīrs, caur ko To Kungu var vaicāt, bet es viņu ienīstu, jo tas man nesludina labas lietas, bet ļaunas vien, Miha, Jemlas dēls. Un Jehošafats sacīja: lai ķēniņš tā nerunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Tad Israēla ķēniņš sauca vienu kambarjunkuri un sacīja: atved steigšus Mihu, Jemlas dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Un Israēla ķēniņš un Jehošafats, Jūda ķēniņš, sēdēja ikkatrs uz sava krēsla ar savām drēbēm apģērbti, un tie sēdēja pagalmā priekš Samarijas vārtiem, un visi tie pravieši sludināja viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Un Cedeķija, Knaēnas dēls, sev taisīja dzelzs ragus un sacīja: tā saka Tas Kungs: ar šiem tu badīsi Sīriešus, tiekams tos būsi izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Un visi pravieši sludināja sacīdami: celies pret Rāmotu Gileādā, tev būs laba laime, jo Tas Kungs to dos ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Un tas vēstnesis, kas bija gājis Mihu aicināt, uz to runāja un sacīja: redzi jel, tie pravieši runā vienā mutē labu ķēniņam, lai jel tavs vārds tāpat ir kā viņu vārds, un runā labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Bet Miha sacīja: tik tiešām kā Tas Kungs dzīvo: ko mans Dievs man sacīs, to es runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Un kad viņš ķēniņa priekšā nāca, tad ķēniņš uz viņu sacīja: Miha, vai mums būs iet karā pret Rāmotu Gileādā, jeb vai man nebūs iet? Un tas sacīja: ceļaties, jums būs laba laime, jo tie taps doti jūsu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Bet ķēniņš uz viņu sacīja: cik reiz lai es tev piekodināju, man cita nekā nesacīt, kā vien kas tiesa Tā Kunga Vārdā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Un viņš sacīja: es redzēju visu Israēli izklīdinātu pa kalniem, kā avis, kam nav gana, un Tas Kungs sacīja: šiem nav kunga, lai iet ikviens ar mieru savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Tad Israēla ķēniņš sacīja uz Jehošafatu: vai es tev neesmu sacījis, ka viņš par mani labu nesludina bet ļaunu vien?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Un (Miha) sacīja: tādēļ klausiet Tā Kunga vārdu: es redzēju To Kungu sēžam uz Sava godības krēsla un visu debess spēku ap Viņu stāvam pa labo un pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Un Tas Kungs sacīja: kas pierunās Ahabu, Israēla ķēniņu, ka tas ceļas un krīt Rāmotā Gileādā? Un viens runāja šā otrs tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Tad viens gars izgāja un nostājās Tā Kunga priekšā un sacīja: es viņu pārrunāšu. Bet Tas Kungs sacīja uz to: kā tad?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Un viņš sacīja: es iziešu un būšu melu gars visu viņa praviešu mutē. Un viņš sacīja: tev būs viņu pierunāt un tu to arī spēsi, ej un dari tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Un nu, redzi, Tas Kungs ir devis melu garu šo tavu praviešu mutē, un Tas Kungs ļaunu pret tevi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Tad Cedeķija, Knaēnas dēls, piegāja un sita Miham vaigā un sacīja: kā gan Tā Kunga Gars no manis būtu atstājies, runāt, ar tevi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Un Miha sacīja: tu to redzēsi tai dienā, kad no vienas istabas otrā iesi paslēpties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Un Israēla ķēniņš sacīja: ņemiet Mihu un vediet viņu atpakaļ pie Amona, pilsētas virsnieka, un pie Joasa, ķēniņa dēla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Un sakāt: tā saka ķēniņš: lieciet šo cietumā un ēdiniet to ar bēdu maizi un ar bēdu ūdeni, kamēr es vesels atkal pārnākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Un Miha sacīja: ja tu vesels atkal pārnāksi, tad Tas Kungs caur mani nav runājis. Un viņš sacīja: klausāties, visi ļaudis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Tā Israēla ķēniņš un Jehošafats, Jūda ķēniņš, cēlās pret Rāmotu Gileādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Un Israēla ķēniņš sacīja uz Jehošafatu: es pārģērbies iešu kaujā, bet tu apģērbies ar savām drēbēm. Un Israēla ķēniņš pārģērbās, un tie gāja kaujā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Un Sīriešu ķēniņš saviem ratu virsniekiem bija pavēlējis un sacījis: nelaužaties pret nevienu, ne mazu ne lielu, kā tik vien pret Israēla ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Kad nu tie ratu virsnieki redzēja Jehošafatu, tad tie sacīja: tas ir Israēla ķēniņš. Un tie to apstāja uz viņu lauzdamies. Bet Jehošafats brēca, un Tas Kungs tam palīdzēja un Dievs tos no viņa novērsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Jo kad tie ratu virsnieki redzēja, ka šis nebija Israēla ķēniņš, tad tie griezās no viņa atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Bet viens vīrs no nejauši uzvilka savu stopu un iešāva Israēla ķēniņam starp sprādzēm un krūšu bruņām. Tad ķēniņš sacīja uz savu ratu vadoni: griez un izved mani no kaujas, jo es esmu ievainots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Un kaušanās vairojās tai dienā, un Israēla ķēniņš stāvēja savos ratos Sīriešiem pretī līdz pat vakaram un nomira, kad saule nogāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Un Jehošafats, Jūda ķēniņš, griezās vesels atpakaļ uz savu namu Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Un Jeūs, Hananus dēls, tas redzētājs, tam izgāja pretī un sacīja uz ķēniņu Jehošafatu: vai tev tā tam bezdievīgam bija jāpalīdz un tie jāmīļo, kas To Kungu ienīst? Tādēļ Tā Kunga dusmība nāk pār tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Taču vēl kāds labums pie tevis ir atrasts, ka tu tās Ašeras no zemes esi izpostījis un savā sirdī apņēmies, Dievu meklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Tā Jehošafats dzīvoja Jeruzālemē, un izgāja atkal pa ļaudīm no Bēršebas līdz Efraīma kalniem, un atgrieza tos atkal pie Tā Kunga, viņu tēvu Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Viņš arī iecēla soģus zemē, visās stiprās Jūda pilsētās priekš ikkatras pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Un viņš sacīja uz tiem soģiem: pieraugāt, ko jūs darāt, jo jūs tiesu nenesat cilvēkiem, bet Tam Kungam, un viņš ir ar jums pie tiesas nešanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Tad nu lai Tā Kunga bijāšana ir pie jums, sargāties un dariet to. Jo pie Tā Kunga, mūsu Dieva, nav netaisnības nedz cilvēka vaiga uzlūkošanas nedz dāvanu ņemšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Arī Jeruzālemē Jehošafats iecēla kādus no Levitiem un priesteriem un no Israēla tēvu namu virsniekiem, Tā Kunga tiesu nest un tiesas lietas izšķirt. Un tie griezās atpakaļ uz Jeruzālemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Un viņš tiem pavēlēja un sacīja: dariet tā iekš Tā Kunga bijāšanas ar uzticību un ar skaidru sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Un visās tiesas lietās, kas pie jums nāk no jūsu brāļiem, kas savās pilsētās dzīvo, starp asinīm un asinīm, starp bauslību un bausli un likumiem un tiesām, tad pamāciet tos, lai tie pie Tā Kunga nenoziedzās, un lai nenāk dusmība pār jums un pār jūsu brāļiem; dariet tā, tad jūs nenoziegsities.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Un redzi, priesteris Amarija ir tas augstākais pār jums visās Tā Kunga lietās, un Zabadija, Ismaēla dēls, tas lielskungs no Jūda nama, visās ķēniņa lietās; bet par uzraugiem ir Leviti jūsu priekšā. Ņematies drošu prātu un dariet to, un Tas Kungs būs ar to, kas ir labs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Un pēc tam notika, ka Moaba bērni un Amona bērni, un līdz ar tiem kādi no tiem Meunim nāca, karot pret Jehošafatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Un vēstneši nāca un sacīja Jehošafatam: liels pulks nāk pret tevi no viņpus jūras, no Sīrijas, un redzi, tie ir AceconaTamarā, tas ir Enģedos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Tad Jehošafats izbijās un grieza savu vaigu, To Kungu meklēt, un izsauca gavēni pa visu Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Un Jūda ļaudis sapulcinājās, meklēt no Tā Kunga palīgu, un no visām Jūda pilsētām tie nāca, To Kungu meklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Un Jehošafats stāvēja Jūda un Jeruzālemes draudzes vidū Tā Kunga namā priekš tā jaunā pagalma');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Un sacīja: Kungs mūsu tēvu Dievs! Vai Tu neesi Dievs debesīs un valdītājs visu ļaužu valstīs? Un Tavā rokā ir spēks un vara, ka neviens pret Tevi nevar celties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Vai Tu, mūsu Dievs, šās zemes iedzīvotājus neesi izdzinis Savu Israēla ļaužu priekšā, un vai to neesi devis Ābrahāma, Sava mīļā, dzimumam uz mūžīgiem laikiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Un tie tur dzīvojuši un Tev tur taisījuši svētu vietu Tavam vārdam, sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Kad pār mums nāk nelaime, zobens, sodība, mēris un bads, tad mēs stāvēsim priekš šī nama un priekš Tava vaiga, tāpēc ka Tavs vārds ir šinī namā, un kad Tevi piesauksim savās bēdās, tad Tu paklausīsi un izpestīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Un nu, redzi, Amona bērni un Moabs un tie no Seīra kalniem, kur Tu Israēlim neļāvi iet cauri, kad tie nāca no Ēģiptes zemes, bet tie no tiem atstājās un tos neizdeldēja, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Redzi nu, tie mums to atmaksā, nākdami, mūs izdzīt no mūsu zemes, ko Tu mums licis iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Ak mūsu Dievs! Vai Tu nenesīsi tiesu pret viņiem? Jo mums nav spēka pret šo lielo pulku, kas pret mums nāk, un mēs nezinām, ko būs darīt, bet mūsu acis griežas uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Un visa Jūda valsts stāvēja Tā Kunga priekšā, arī viņu bērni, viņu sievas un viņu dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Tad Tā Kunga Gars nāca draudzes vidū pār Jeaziēli, Zakarijas dēlu, tas bija Benajas, tas Jeiēļa, tas Levita Matanijas dēls, no Asafa bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Un tas sacīja: klausāties, visa Jūda valsts un Jeruzālemes iedzīvotāji, un ķēniņ Jehošafat, - tā saka Tas Kungs uz jums: nebīstaties un neizbaiļojaties priekš šā lielā pulka, jo tas karš nepieder jums, bet Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Ejat rītu tiem pretī, redzi, tie nāks augšā pa Cic kalnu, un jūs tos sastapsiet ielejas galā šaipus Jeruēles tuksneša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Šinī kaujā jums nebūs jākaujas, ejat tikai klāt, stāviet un redziet Tā Kunga pestīšanu, kas ir ar jums. Jūda un Jeruzāleme, nebīstaties un neizbaiļojaties, izejat rītu viņiem pretī, jo Tas Kungs būs ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Tad Jehošafats locījās ar savu vaigu pie zemes, un visi Jūda un Jeruzālemes iedzīvotāji metās pie zemes priekš Tā Kunga un pielūdza To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Un tie Leviti no Kehāta bērniem un no Koraha bērniem cēlās, augsti slavēt To Kungu, Israēla Dievu ar skanīgu balsi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Un tie cēlās it agri un izgāja uz Tekoas tuksnesi, un tiem izejot Jehošafats stāvēja un sacīja: klausiet mani, Jūda un Jeruzālemes iedzīvotāji, ticiet uz To Kungu, savu Dievu, tad jūs pastāvēsiet; ticiet Viņa praviešiem, tad jums labi izdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Un viņš sarunājās ar tiem ļaudīm un iecēla dziedātājus priekš Tā Kunga, ka tie svētā glītumā slavētu, apbruņoto priekšā iedami un sacīdami: teiciet To Kungu, jo Viņa žēlastība paliek mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Un to brīdi, kad tie sāka dziedāt tās priecīgās un teicamās dziesmas, tad Tas Kungs sūtīja glūnētājus pret Amona bērniem, Moabu un tiem no Seīra kalniem, kas bija nākuši uz Jūdu, un tie tika sakauti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Jo Amona bērni un Moabs cēlās pret Seīra kalnu iedzīvotājiem un tos izdeldēja un nomaitāja, un kad tie visus Seīra iedzīvotājus bija nokāvuši, tad tie palīdzēja nomaitāt cits citu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Un Jūda nāca kalna galā pie tuksneša un griezās pret tiem pulkiem, un redzi, tur bija miroņi, kas zemē gulēja, un neviens nebija izbēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Tad Jehošafats un viņa ļaudis nāca un tos aplaupīja un atrada pie tiem ļoti daudz mantas un drēbes un dārgus rīkus, un paņēma tik daudz, ka nevarēja panest, un tie laupīja laupījumu trīs dienas, jo tur bija ļoti daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Un ceturtā dienā tie sapulcējās teikšanas ielejā, jo tur tie teica To Kungu, tāpēc tie tās vietas vārdu nosauca Teikšanas ieleja līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Pēc tam visi vīri no Jūda un Jeruzālemes griezās atpakaļ, un Jehošafats viņu priekšā, un gāja uz Jeruzālemi ar prieku; jo Tas Kungs viņus bija darījis priecīgus par viņu ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Un tie nonāca Jeruzālemē ar somastabulēm un koklēm un trumetēm uz Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Un bailes no Dieva nāca pār visām zemes valstīm, kad dzirdēja, ka Tas Kungs bija karojis pret Israēla ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Un Jehošafata valsts bija mierā, un viņa Dievs tam deva mieru visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Un Jehošafats valdīja pār Jūdu; viņš bija trīsdesmit piecus gadus vecs, kad tas palika par ķēniņu, un valdīja divdesmit piecus gadus Jeruzālemē, un viņa mātei bija vārds Azuba, Šilkus meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Un viņš staigāja sava tēva Asas ceļos un neatstājās no tiem, darīdams, kas Tam Kungam patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Taču kalnu altāri netapa nopostīti, un vēl tie ļaudis ar savu sirdi pilnīgi neturējās pie savu tēvu Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Un kas vēl par Jehošafatu stāstāms, par viņa pirmām un pēdējām dienām, redzi, tas rakstīts Jeūs, Anana dēla, stāstos, ko viņš sarakstījis Israēla ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Un pēc tam Jehošafats, Jūda ķēniņš, sabiedrojās ar Ahaziju, Israēla ķēniņu; tas bija bezdievīgs savos darbos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Un viņš ar to vienojās, kuģus taisīt, ar ko braukt uz Taršišu, un tie taisīja kuģus EceonĢeberā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Bet Eliēzers, Dodava dēls, no Marezas, sludināja pret Jehošafatu sacīdams: tādēļ ka tu ar Ahaziju esi sabiedrojies, Tas Kungs salauzīs tavu darbu. Un tie kuģi tika sadragāti un nevarēja tikt uz Taršišu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Un Jehošafats aizmiga pie saviem tēviem un tapa aprakts pie saviem tēviem Dāvida pilī, un viņa dēls Jehorams palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Un tam bija brāļi, Jehošafata dēli, Azarija un Jeīels un Zaharija un Acarija un Mikaēls un Šefatija, šie visi bija Jehošafata, Israēla ķēniņa, dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Un viņu tēvs tiem deva daudz dāvanas, sudrabu un zeltu un dārgas lietas, arī stipras pilsētas Jūdā, bet valstību viņš deva Jehoramam, tāpēc ka tas bija tas pirmdzimtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kad nu Jehorams bija nācis pie sava tēva valstības un bija palicis spēcīgs, tad viņš nokāva visus savus brāļus ar zobenu, arī kādus no Israēla lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Trīsdesmit divi gadus Jehorams bija vecs, kad palika par ķēniņu, un valdīja astoņus gadus Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Un viņš staigāja Israēla ķēniņu ceļos, tā kā Ahaba nams darīja; jo viņam Ahaba meita bija par sievu, un viņš darīja, kas Tam Kungam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Bet Tas Kungs Dāvida namu negribēja izdeldēt tās derības dēļ, ko viņš bija derējis ar Dāvidu, un ka bija sacījis, viņam un viņa dēliem dot gaišumu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Viņa laikā Edomieši atkrita no Jūda valdības un iecēla sev ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Tādēļ Jehorams cēlās ar saviem virsniekiem un ar visiem saviem ratiem, un nogāja naktī un kāva Edomiešus, kas viņu bija apstājuši, un tos ratu virsniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Tomēr Edomieši no Jūda valdības atkrita līdz šai dienai. Tai pašā laikā Libna atkrita no viņa valdības; jo viņš To Kungu, savu tēvu Dievu, bija atstājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Viņš arī cēla altārus Jūda kalnos un darīja, ka Jeruzālemes iedzīvotāji maukoja, un pievīla Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Tad grāmata pie tā nāca no pravieša Elijas ar šiem vārdiem: tā saka Tas Kungs, tava tēva Dāvida Dievs: tāpēc ka tu neesi staigājis sava tēva Jehošafata un Asas, Jūda ķēniņa, ceļos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Bet esi staigājis Israēla ķēniņu ceļos un esi darījis, ka Jūda un Jeruzālemes iedzīvotāji maukoja pēc Ahaba nama maukošanas, un arī esi nokāvis savus brāļus no sava tēva nama, kas bija labāki nekā tu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Redzi, tad Tas Kungs tevi mocīs ar lielu mocību pie taviem ļaudīm, pie taviem bērniem un pie tavām sievām un pie visas tavas mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Un tev uzies liela slimība, ka tavas iekšas sirgs, tiekams tavas iekšas caur šo sērgu ar laiku pavisam izbeigsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Un Tas Kungs pamodināja pret Jehoramu Fīlistu un Arābu prātu, kas dzīvo gar Moru zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Un tie cēlās pret Jūdu un ielauzās un aizveda visu mantu, kas atradās ķēniņa namā, arī viņa bērnus un viņa sievas, tā kā neviens dēls viņam neatlika, kā vien Joakas (Ahazija), viņa jaunākais dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Un pēc visa tā Tas Kungs viņu mocīja viņa iekšās ar tādu sērgu, ko nevarēja dziedināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Tas notika jo dienas jo vairāk, un kad divu gadu laiks bija pagājis, tad viņa iekšas ar to sērgu izbeidzās, ka tas lielās mokās nomira. Un viņa ļaudis par viņu nededzināja tādu dedzināšanu, kā tie bija darījuši viņa tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Viņš bija trīsdesmit divus gadus vecs, kad palika par ķēniņu, un valdīja astoņus gadus Jeruzālemē, un viņš aizgāja, un nevienam viņa nebija žēl, un to apraka Dāvida pilī, bet ne ķēniņu kapos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Un Jeruzālemes iedzīvotāji cēla par ķēniņu viņa vietā Ahaziju, viņa jaunāko dēlu. Jo visus tos vecākos bija nokāvuši sirotāji, kas ar Arābiešiem bija nākuši lēģerī; tā Jehorama, Jūda ķēniņa, dēls Ahazija palika par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Divdesmit divus gadus Ahazija bija vecs, kad palika par ķēniņu, un valdīja vienu gadu Jeruzālemē, un viņa mātei bija vārds Atalija, tā bija Omrus meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Un tas arīdzan staigāja Ahaba nama ceļos, jo viņa māte bija viņa padoma devēja uz bezdievību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Un viņš darīja, kas Tam Kungam nepatika, tā kā Ahaba nams, jo tie bija viņa padoma devēji, kad viņa tēvs bija nomiris, viņam par postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Un pēc viņu padoma viņš arī cēlās un ar Joramu, Ahaba dēlu, Israēla ķēniņu, nogāja karā pret Azaēli, Sīrijas ķēniņu, uz Rāmotu Gileādā. Un Sīrieši sita Joramu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Un viņš griezās atpakaļ, ka liktos dziedināties Jezreēlē, jo tam bija vātis, kas viņam Rāmā bija sistas, kad tas karoja pret Azaēli, Sīrijas ķēniņu. Un Azarija (Ahazija), Jehorama, Jūda ķēniņa, dēls, nogāja apraudzīt Joramu, Ahaba dēlu, Jezreēlē, jo tas bija slims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Jo Ahazijam no Dieva tas notikās par postu, ka nāca pie Jorama, jo kad viņš bija nonācis, tad viņš izgāja ar Joramu pret Jeū, Nimšus dēlu, ko Tas Kungs bija svaidījis, Ahaba namu izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Kad nu Jeūs par Ahaba namu to sodību izdarīja, tad viņš atrada Jūda lielkungus un Ahazijas brāļa dēlus, kas Ahazijam kalpoja, un viņš tos nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Un viņš meklēja Ahaziju, un to sagrāba, jo tas bija paslēpies Samarijā, un tie to atveda pie Jeūs un to nokāva un to apraka; jo tie sacīja: viņš ir Jehošafata dēls, kas no visas savas sirds To Kungu meklējis. Tā Ahazijas namam neviena nebija, kas būtu varējis palikt par ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Kad nu Atalija, Ahazijas māte, redzēja savu dēlu esam nomirušu, tad tā cēlās un nogalinaja visu Jūda nama ķēniņa dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Bet Jozabate, ķēniņa meita, ņēma Joasu, Ahazijas dēlu, un to nozaga no ķēniņa bērnu vidus, kas tapa nokauti, un to ar viņu emmu lika guļamā kambarī. Tā Jozabate, ķēniņa Jehorama meita, priestera Jojadas sieva, (jo tā bija Ahazijas māsa) viņu apslēpa priekš Atalijas, ka tā to nenokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Un viņš ar tiem bija apslēpts Dieva namā sešus gadus, un Atalija valdīja pār zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Bet septītā gadā Jojada iedrošinājās un cēla derību ar tiem virsniekiem pār simtiem, Azariju, Jeroama dēlu, un Ismaēli, Johanana dēlu, un Azariju, Obeda dēlu, un Maāseju, Adajas dēlu, un Elizavatu, Sihrus dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Un tie gāja pa Jūdu apkārt un sapulcināja Levitus no visām Jūda pilsētām un Israēla tēvu namu virsniekus, un tie sanāca Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Un visa draudze derēja derību Dieva namā ar ķēniņu, un viņš uz tiem sacīja: redzi, ķēniņa dēlam būs būt par ķēniņu, tā kā Tas Kungs runājis par Dāvida dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'To nu jums būs darīt: Trešdaļa no jums, kam svētdienā krīt kārta, no priesteriem un Levitiem, lai vakti tur pie durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Un trešdaļa lai stāv ķēniņa namā, un trešdaļa pie Pamatu vārtiem. Un visi ļaudis lai stāv Tā Kunga nama pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Bet nevienam nebūs Tā Kunga namā ieiet, kā vien priesteriem un Levitiem, kas kalpo; tie var ieiet, jo tie ir svēti, bet visi ļaudis lai tur Tā Kunga vakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Un Leviti lai stājās visapkārt ap ķēniņu, ikkatrs ar savu ieroci rokā, un kas namā ieiet, tam būs mirt, bet jums būs būt pie ķēniņa, kad tas ieiet un iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Un Leviti un visa Jūda valsts darīja pēc visa, ko priesteris Jojada bija pavēlējis, un ikviens ņēma savus vīrus, kam svētdienā krita kārta un kam svētdienā kārta beidzās. Jo priesteris Jojada tiem kārtniekiem neļāva aiziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Un priesteris Jojada deva tiem virsniekiem pār simtniekiem šķēpus un priekšturamās bruņas un tās bruņas, kas ķēniņam Dāvidam bijušas, kas bija Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Un viņš nostādīja visus ļaudis, ikvienu ar savu ieroci rokā, no nama labās puses līdz nama kreisai pusei, līdz altārim un namam visapkārt ap ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Un tie izveda to ķēniņa dēlu un viņam uzlika kroni un tam deva to liecības grāmatu un to cēla par ķēniņu. Un Jojada ar saviem dēliem to svaidīja un sacīja: lai dzīvo ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kad nu Atalija to ļaužu kliegšanu dzirdēja, kas bija saskrējuši un ķēniņu slavēja, tad viņa nāca pie tiem ļaudīm Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Un tā skatījās, un redzi, ķēniņš stāvēja savā vietā pie durvīm un lielkungi un taurētāji bija pie ķēniņa, un visi zemes ļaudis priecājās un pūta trumetes, un dziedātāji ar saviem rīkiem pavadīja tās slavas dziesmas. Tad Atalija saplēsa savas drēbes un sacīja: dumpis, dumpis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Bet priesteris Jojada lika iziet tiem virsniekiem pār simtiem, tiem kara vadoņiem, un uz tiem sacīja: izvediet to ārā no nama caur rindām, un kas viņai ies pakaļ, to būs ar zobenu nokaut. Jo tas priesteris bija sacījis: nenokaujiet to Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Un tie tai deva ceļu atkāpdamies uz abējām pusēm, un kad tā ieejot pa tiem zirgu vārtiem nāca ķēniņa namā, tad tie viņu tur nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Un Jojada derēja derību starp sevi un visiem ļaudīm un ķēniņu, ka tie būtu Tā Kunga ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Tad visi ļaudis gāja Baāla namā un to nolauzīja un viņa altārus, un sadauzīja viņa bildes un nokāva Matanu, Baāla priesteri, altāru priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Un Jojada iecēla atkal par uzraugiem pie Tā Kunga nama priesterus, tos Levitus, ko Dāvids bija atšķīris Tā Kunga namam, upurēt Tam Kungam dedzināmos upurus, kā Mozus bauslībā rakstīts, ar prieku un ar dziesmām pēc Dāvida likuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Un viņš iecēla vārtu sargus pie Tā Kunga nama vārtiem, ka neviens tur neieietu, kas kaut kādas lietas dēļ nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Un viņš ņēma tos virsniekus pār simtiem un varenos un ļaužu lielkungus, arī visus zemes ļaudis, un noveda ķēniņu no Tā Kunga nama un gāja caur augšējiem vārtiem ķēniņa namā, un sēdināja ķēniņu uz valstības krēslu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Un visi zemes ļaudis priecājās, un pilsēta norima pēc tam, kad Ataliju bija nokāvuši ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas bija septiņus gadus vecs, kad palika par ķēniņu, un valdīja četrdesmit gadus Jeruzālemē, un viņa mātei bija vārds Cibea, no Bēršebas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Un Joas darīja, kas Tam Kungam labi patika, kamēr priesteris Jojada dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Un Jojada tam ņēma divas sievas, un tās dzemdināja dēlus un meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Pēc tam Joas apņēmās savā sirdī, atjaunot Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Un viņš sapulcināja priesterus un Levitus un uz tiem sacīja: izejiet Jūda pilsētās un sakrājiet naudu no visa Israēla, atkal apkopt sava Dieva namu gadu no gada; un steidzaties ar šo lietu. Bet Leviti nesteidzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Un ķēniņš aicināja augsto priesteri Jojadu, un uz to sacīja: kāpēc tu neesi raudzījis uz Levitiem, ka tiem no Jūda un Jeruzālemes bija sakrāt to meslu naudu, ko Mozus, Tā Kunga kalps, nospriedis, ka Israēla draudzei jādod priekš saiešanas telts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Jo bezdievīgā Atalija un viņas dēli Dieva namu postījuši, un visas svētās dāvanas no Tā Kunga nama izlietojuši Baāliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Tad ķēniņš pavēlēja taisīt šķirstu, un to likt ārā pie Tā Kunga nama vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Un Jūdā un Jeruzālemē izsauca, lai Tam Kungam atnes meslu naudu, ko Mozus, tas Dieva kalps, Israēlim tuksnesi bija nospriedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Tad visi lielkungi un visi ļaudis priecājās un atnesa un iemeta tai šķirstā, kamēr tas tapa pilns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Kad nu bija laiks, Levitiem šķirstu atnest pie ķēniņa celtiem uzraugiem, un kad redzēja, ka daudz naudas bija iekšā, tad ķēniņa skrīveris, un augstā priestera uzraugs, nāca un iztukšoja to šķirstu, un to ņēma un atkal nonesa savā vietā; tā tie darīja ikdienas un sakrāja daudz naudas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Un ķēniņš un Jojada to deva tiem darba vedējiem pie Tā Kunga nama darba, un tie saderēja akmeņu cirtējus un amatniekus, Tā Kunga namu atjaunot, arī dzelzs un vara kalējus, atkal uzkopt Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Un tie strādnieki darīja savu darbu un darbs veicās caur viņu roku, un tie Dieva namu atkal iztaisīja pareizi un to uzkopa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Kad tie to nu bija pabeiguši, tad tie atnesa atlikušo naudu pie ķēniņa un Jojadas, un par to lika rīkus taisīt Tā Kunga namam, rīkus kalpošanai un upurēšanai un bļodas un zelta un sudraba traukus; un tie upurēja vienmēr dedzināmos upurus Tā Kunga namā, kamēr Jojada dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Un Jojada palika vecs un bija savu laiku nodzīvojis un nomira; simts un trīsdesmit gadus viņš bija vecs, kad nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Un to apraka Dāvida pilī pie ķēniņiem, jo viņš Israēlim bija labu darījis, ir Dievam, ir viņa namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Bet kad Jojada bija nomiris, tad Jūda lielkungi nāca un metās zemē ķēniņa priekšā; un ķēniņš uz tiem klausījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Un tie atstāja Tā Kunga, savu tēvu Dieva, namu, un kalpoja Ašerām un elkiem. Tad dusmība nāca pār Jūdu un Jeruzālemi šā viņu nozieguma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Un viņš tiem sūtīja praviešus, tos atkal atgriezt pie Tā Kunga, un tie gan deva liecību pret viņiem, bet šie savas ausis neatvēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Bet Tā Kunga Gars nāca uz Zahariju, priestera Jojadas dēlu. Tas uzkāpa kādā augstā vietā ļaužu priekšā un uz tiem sacīja: tā Dievs saka: kāpēc jūs pārkāpjat Tā Kunga baušļus? Tas jums nebūs par labu! Jūs To Kungu esat atstājuši, Viņš jūs arīdzan atstās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Un tie cēlās pret viņu un to nomētāja akmeņiem pēc ķēniņa pavēles Tā Kunga nama pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Tā ķēniņš Joas nepieminēja to žēlastību, ko viņa tēvs Jojada tam bija parādījis, bet nokāva viņa dēlu. Un mirdams tas sacīja: Tas Kungs to redzēs un piemeklēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Kad nu gads bija pagājis, tad Sīriešu kara spēks cēlās pret viņu; un tie nāca pret Jūdu un Jeruzālemi un nogalināja no tiem ļaudīm visus ļaužu virsniekus, un sūtīja visu savu laupījumu Damaskus ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Un jebšu Sīriešu spēks mazā pulkā atnāca, taču Tas Kungs tiem nodeva rokā ļoti lielu kara spēku, tāpēc ka šie bija atstājuši To Kungu, savu tēvu Dievu; un Joasu tie sodīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Un kad šie no viņa atkal aizgāja, (jo šie viņu pameta ļoti ievainotu,) tad viņa kalpi pret viņu sacēlās priestera Jojadas bērnu asiņu dēļ, un to nokāva viņa gultā, ka tas nomira. Un to apraka Dāvida pilī, bet ķēniņa kapos to neraka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Un šie ir, kas pret viņu bija sacēlušies: Zabads, Amonietes Zimeatas dēls, un Jozabads, Moabietes Zimrites dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Bet viņa dēli un viņa meslu-naudas krājums un Dieva nama uzkopšana, redzi, tas viss rakstīts ķēniņu grāmatas rakstos. Un viņa dēls Amacīja palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amacīja bija divdesmit piecus gadus vecs, kad palika par ķēniņu, un valdīja Jeruzālemē divdesmit deviņus gadus, un viņa mātei vārds bija Joadana, no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Un viņš darīja, kas Tam Kungam labi patika, tomēr ne no visas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Kad nu viņš bija stiprinājies savā valstībā, tad viņš nokāva savus kalpus, kas bija kāvuši viņa tēvu, to ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Bet viņu bērnus viņš nenokāva, kā ir rakstīts Mozus bauslības grāmatā, kur Tas Kungs pavēlējis sacīdams: tēviem nebūs mirt par bērniem, un bērniem nebūs mirt par tēviem, bet ikviens lai mirst savu paša grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Un Amacīja salpulcināja Jūdu un tos šķīra pēc tēvu namiem, pēc tūkstošniekiem un pēc simtniekiem pa visu Jūdu un Benjaminu, un skaitīja no tiem tos, kas divdesmit un vairāk gadus bija veci, un atrada no tiem trīs simt reizi tūkstoš izlasītus, kas varēja iet karā un nesa šķēpus un priekšturamās bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Un viņš saderēja no Israēla simt tūkstoš stiprus karavīrus par simts talentiem sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Bet viens Dieva vīrs nāca pie viņa un sacīja: ķēniņ! Israēla spēks lai tev neiet līdz, jo Tas Kungs nav ar Israēli, ar nevienu no Efraīma bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Bet ja tu iesi un (to) darīsi un būsi drošs uz karu, tad Dievs tev liks krist ienaidnieka priekšā; jo Dievam ir spēks palīdzēt un nogāzt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Un Amacīja sacīja uz to Dieva vīru: bet ko tad es darīšu ar tiem simts talentiem, ko esmu devis Israēla karavīriem? Bet tas Dieva vīrs sacīja: Tam Kungam ir vairāk tev ko dot nekā tik daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Tad Amacīja atšķīra tos karavīrus, kas no Efraīma bija nākuši pie viņa, lai tie ietu uz savām mājām. Bet tie ļoti apskaitās pret Jūdu un ar lielām dusmām griezās atkal atpakaļ uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Un Amacīja ņēmās drošu prātu un izveda savus ļaudis un nogāja sāls ielejā un kāva desmit tūkstošus no Seīra bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Un Jūda bērni sagūstīja no tiem desmit tūkstošus dzīvus un tos veda klints galā un tos nogāza no paša klints gala, ka tie visi tapa sašķelti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Bet tie karavīri, kam Amacīja bija licis iet atpakaļ, lai tie ar viņu karā neietu, tie ielauzās Jūda pilsētās no Samarijas līdz BetOronai un kāva no tiem trīs tūkstošus un aiznesa lielu laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Kad nu Amacīja pārnāca no Edomiešu kaujas un bija atvedis līdz Seīra bērnu dievus, tad viņš tos sev iecēla par dieviem un metās zemē viņu priekšā un tiem kvēpināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Tad Tā Kunga bardzība iedegās pret Amacīju, un Viņš sūtīja pie tā pravieti. Tas uz viņu sacīja: kāpēc tu esi meklējis to ļaužu dievus, kas savus ļaudis nevarēja atpestīt no tavas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Kad nu viņš uz to tā runāja, tad tas uz viņu sacīja: vai tu esi iecelts par ķēniņa padoma devēju? Esi klusu, kāpēc lai tevi nokauj? Tad tas pravietis apklusa un sacīja: es gan atzīstu, ka Dievs apņēmies tevi samaitāt, tāpēc ka tu to esi darījis un neesi klausījis manam padomam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Un Amacīja, Jūda ķēniņš, aprunājās un sūtīja pie Jehoasa, Joakasa dēla, Jeūs dēla dēla, Israēla ķēniņa, un sacīt: nāc, griezīsim vaigu pret vaigu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Bet Jehoas, Israēla ķēniņš, sūtīja pie Amacījas, Jūda ķēniņa, un lika sacīt: ērkšķu krūms uz Lībanus sūtīja pie ciedra koka uz Lībanus un sacīja: dod savu meitu manam dēlam par sievu; bet tie lauka zvēri, kas uz Lībanus, gāja pāri un samina to ērkšķu krūmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Redzi, tu domā, tu esi kāvis Edomiešus, un tava sirds lepojās un lielās. Nu tad, paliec mājās, kāpēc tu gribi skriet nelaimē, pats krist un Jūda līdz ar tevi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Bet Amacīja neklausīja, jo tas notika no Dieva, lai viņš tos viņiem dotu rokā, tāpēc ka tie bija meklējuši Edomiešu dievus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Un Jehoas, Israēla ķēniņš, cēlās, un tie grieza vaigu pret vaigu, viņš un Amacīja, Jūda ķēniņš, BetŠemē iekš Jūda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Un Jūda tapa kauts Israēla priekšā, un tie bēga ikviens uz savu dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Un Jehoas Israēla ķēniņš, sagūstīja Amacīju, Jūda ķēniņu, Joasa dēlu, Joakasa (Ahazijas) dēla dēlu, BetŠemesā un to noveda Jeruzālemē un noplēsa Jeruzālemes mūrus no Efraīma vārtiem līdz Stūra vārtiem četrsimt olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Un viņš ņēma visu zeltu un sudrabu un visus traukus, kas Dieva namā tapa atrasti pie ObedEdoma, un ķēniņa nama mantas līdz ar tiem galviniekiem un griezās atpakaļ uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Un Amacīja, Joasa dēls, Jūda ķēniņš dzīvoja pēc tam, kad Jehoas, Joakasa dēls, Israēla ķēniņš, bija nomiris, piecpadsmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Un kas vēl par Amacīju stāstāms, ir par viņa iesākumu, ir par viņa galu, redzi, tas rakstīts Jūda un Israēla ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Un no tā laika, kamēr Amacīja no Tā Kunga bija atkāpies, dumpis pret viņu cēlās Jeruzālemē, un viņš bēga uz Laķisu. Bet tie viņam sūtīja pakaļ uz Laķisu un to tur nokāva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Un to atveda uz zirgiem un apraka pie viņa tēviem Jūda pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Tad visi Jūda ļaudis ņēma Uziju - tas bija sešpadsmit gadus vecs, - un to cēla par ķēniņu viņa tēva Amacījas vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Tas uztaisīja Elatu un to atkal atdabūja pie Jūda, pēc tam, kad ķēniņš bija aizmidzis pie saviem tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sešpadsmit gadus Uzija bija vecs, kad palika par ķēniņu, un valdīja Jeruzālemē piecdesmit divus gadus, un viņa mātei bija vārds Jekalija no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Un viņš darīja, kas Tam Kungam labi patika, tā kā viņa tēvs Amacīja bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Jo viņš meklēja Dievu, kamēr Zaharija dzīvoja, kas bija Dieva parādīšanu tulkotājs; kamēr tas nu To Kungu meklēja, Dievs tam lika labi izdoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Un viņš izgāja un karoja pret Fīlistiem un nolauzīja Gatas mūri un Jabnes mūri un Ašdodas mūri un uztaisīja pilsētas Ašdodas valstī un Fīlistu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Un Dievs tam palīdzēja pret Fīlistiem un pret Arābiem, kas GurBaālā dzīvoja, un pret Meūniešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Un Amonieši Uzijam deva dāvanas, un viņa slava izpaudās līdz Ēģiptes robežām, jo viņš palika jo dienas jo varens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Un Uzija taisīja torņus Jeruzālemē pie stūra vārtiem un ielejas vārtiem un pie citiem stūriem, un tos apstiprināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Viņš uztaisīja arī torņus tuksnesī un izraka daudz akas, jo viņam bija daudz lopu un ielejā un klajumā arāji un pa kalniem un auglīgiem tīrumiem vīna dārznieki, jo viņš mīļoja zemes darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Un Uzijam bija mācīts karaspēks, kas karā gāja pa pulkiem, skaitīti caur rakstu vedēju Jeīelu un uzraugu Maāseju, apakš Ananijas, ķēniņa lielkunga, rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Visi kara spēka tēvu namu virsnieku skaits bija divi tūkstoši un sešsimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Un apakš viņu rokas bija tas karaspēks, trīssimt septiņtūkstoš piecsimt pilnā spēkā uz karu mācīti, ķēniņam palīdzēt pret ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Un Uzija visam kara spēkam lika taisīt priekšturamās bruņas un šķēpus un bruņu cepures un krūšu bruņas un stopus un lingu akmeņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Viņš taisīja arīdzan Jeruzālemē lielus kara rīkus, gudru strādnieku darbu, uz torņiem un stūriem, šaut ar bultām un lieliem akmeņiem. Tā viņa slava izpaudās it tālu, jo viņam tapa brīnišķi palīdzēts, kamēr viņš palika varens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Bet kad viņš bija palicis varens, tad viņa sirds pacēlās noziegties, un viņš apgrēkojās pret To Kungu, savu Dievu, jo viņš gāja Tā Kunga namā, kvēpināt uz kvēpināmā altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Bet priesteris Azarija tam gāja pakaļ, un līdz ar viņu Tā Kunga astoņdesmit priesteri, krietni vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Un tie turējās ķēniņam Uzijam pretī un uz to sacīja: tas tev nepiekrīt, Uzija, Tam Kungam kvēpināt, bet priesteriem, Ārona dēliem, kas ir svētīti kvēpināt. Izej no svētās vietas, jo tu esi apgrēkojies, un tas tev nav par godu pie Dieva, Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Tad Uzija apskaitās un tas kvēpināmais trauks bija viņa rokā, ko kvēpināt. Kad nu viņš par tiem priesteriem apskaitās, tad spitālība izsitās viņa pierē to priesteru priekšā Tā Kunga namā priekš tā kvēpināmā altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Un augstais priesteris Azarija to uzlūkoja ar visiem priesteriem un redzi, tas bija spitālīgs pierē, un tie viņu steigšus izraidija no turienes. Viņš pats arī steidzās iziet, jo Tas Kungs viņu bija sitis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Tā ķēniņš Uzija bija spitālīgs līdz savas miršanas dienai, un spitālīgs būdams viņš dzīvoja atšķirtā namā, jo viņš bija izslēgts no Tā Kunga nama. Un viņa dēls Jotams bija pār ķēniņa namu un tiesāja tās zemes ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Un kas vēl par Uziju stāstāms, ir tās pirmās, ir tās pēdējās dienas, to pravietis Jesaja, Amoca dēls, uzrakstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Un Uzija aizmiga pie saviem tēviem, un to apraka pie viņa tēviem tai tīrumā, kur bija ķēniņu kapenes; jo tie sacīja: viņš ir spitālīgs. Un viņa dēls Jotams palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotams bija divdesmit piecus gadus vecs, kad palika par ķēniņu, un valdīja Jeruzālemē sešpadsmit gadus, un viņa mātei bija vārds Jeruza, Cadaka meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Un viņš darīja, kas Tam Kungam labi patika, tā kā viņa tēvs Uzija bija darījis, bez vien ka tas Tā Kunga svētā namā neiegāja. Bet tie ļaudis vēl noziedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Šis uztaisīja Tā Kunga namā augšvārtus, arī pie Ofel mūra viņš daudz būvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Viņš uztaisīja arīdzan pilsētas Jūda kalnos, un mežos viņš taisīja pilis un torņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Viņš arī karoja ar Amona bērnu ķēniņu un tos pārvarēja, un Amona bērniem tai gadā tam bija jādod simts talentu sudraba un desmit tūkstoš koru kviešu un desmit tūkstoš koru miežu; to viņam Amona bērni atnesa arī otrā un trešā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Tā Jotams palika spēcīgs, jo viņš staigāja taisni Tā Kunga, sava Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Un kas vēl par Jotamu stāstāms, un viņa kari un viņa ceļi, redzi, tie rakstīti Israēla un Jūda ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Viņš bija divdesmit piecus gadus vecs, kad palika par ķēniņu, un valdīja Jeruzālemē sešpadsmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Un Jotams aizmiga pie saviem tēviem, un viņu apraka Dāvida pilī, un Ahazs, viņa dēls, palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahazs bija divdesmit gadus vecs, kad palika par ķēniņu, un valdīja Jeruzālemē sešpadsmit gadus, un nedarīja, kas Tam Kungam labi patika, kā viņa tēvs Dāvids.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Bet viņš staigāja Israēla ķēniņu ceļos un taisīja arī tēlus Baāliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Un kvēpināja BenHinnoma ielejā un sadedzināja savus dēlus ugunī, pēc to pagānu negantības, ko Tas Kungs bija izdzinis Israēla bērnu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Viņš upurēja un kvēpināja kalnos un pakalnos un apakš visiem zaļiem kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Tādēļ Tas Kungs, viņa Dievs, to nodeva rokā Sīrijas ķēniņam, un tie viņu sita un no tā aizveda lielu pulku cietumā, un tos noveda uz Damasku. Viņš tapa arī nodots Israēla ķēniņa rokā; tas viņu kāva lielā kaušanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Un Peka, Remalijas dēls, kāva iekš Jūda vienā dienā simts divdesmit tūkstošus, kas visi bija kara vīri, tāpēc ka tie bija atstājuši To Kungu, savu tēvu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Un Sihrus, varonis no Efraīma, nokāva Maāseju, ķēniņa dēlu, un Asrikamu, (ķēniņa) nama pārvaldnieku, un Elkanu, otro no ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Un Israēla bērni aizveda no saviem brāļiem divsimt tūkstošus, sievas, dēlus un meitas, un ņēma arī daudz laupījuma no tiem, un veda to laupījumu uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Un tur bija Tā Kunga pravietis Odeds vārdā, tas izgāja pretī tam kara spēkam, kas uz Samariju nāca, un uz tiem sacīja: redzi, bardzībā par Jūdu, Tas Kungs, jūsu tēvu Dievs, tos ir devis jūsu rokā, un jūs tos esat nokāvuši tādā bardzībā, kas sniedzās līdz debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Nu jūs arī domājat Jūda un Jeruzālemes bērnus sev padarīt par vergiem un kalponēm; vai tas jums nav par grēku pret To Kungu, savu Dievu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Nu tad, klausiet mani, vediet atpakaļ tos cietumniekus, ko jūs no saviem brāļiem esat aizveduši cietumā, jo Tā Kunga bardzība pret jums ir iekarsusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Tad no Efraīma bērnu virsniekiem šie vīri, Azarija, Jehohanana dēls, Bereķija, Mezilemota dēls, un Jeīsķija, Šaluma dēls, un Amasa, Adlaja dēls, cēlās pret tiem, kas no tā karaspēka nāca,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Un uz tiem sacīja: nevediet šurp tos cietumniekus, jo jūs tikai gribat, lai apgrēkojamies pret To Kungu, vairot mūsu grēkus un noziegumus, jebšu mūsu noziegums liels un bardzība pret Israēli ir iedegusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Tad tie apbruņotie atstāja tos cietumniekus un to laupījumu virsnieku un visas draudzes priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Un tie vīri, kas ar vārdu minēti, cēlās un ņēma tos cietumniekus un apģērba no tā laupījuma visus plikos viņu starpā un tiem deva drēbes un kurpes un ēst un dzert, un tos svaidīja un lika uz ēzeļiem visus, kas bija noguruši, un tos noveda uz Jēriku, to palmu pilsētu, pie viņu brāļiem, un griezās atpakaļ uz Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Tanī laikā ķēniņš Ahazs sūtīja pie Asīrijas ķēniņiem pēc palīdzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Tad vēl arī Edomieši nāca un kāva Jūdu un aizveda cietumniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Arī Fīlisti ielauzās ielejas pilsētās un Jūda dienvidu pusē un uzņēma BetŠemesu un Ajalonu un Ģederotu un Zoku un viņas miestus, un Timnu un viņas miestus, un Ģimzu un viņas miestus, un tie tur apmetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Jo Tas Kungs pazemoja Jūdu Ahaza, Israēla ķēniņa, dēļ, jo tas bija bezdievīgi dzīvojis iekš Jūda un ļoti noziedzies pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Un Tiglat Pilnezers, Asīrijas ķēniņš, nāca pret viņu, un viņu spieda un tam nepalīdzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Jebšu Ahazs iztukšoja Tā Kunga namu un ķēniņa namu un to lielkungu namu, un deva dāvanas Asīrijas ķēniņam, tomēr tas viņam nepalīdzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Un tai laikā, kad to spieda, viņš pret To Kungu vēl vairāk apgrēkojās; tāds bija ķēniņš Ahazs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Un viņš upurēja Damaskus dieviem, kas viņu bija situši, un sacīja: tāpēc ka Sīriešu ķēniņu dievi tiem palīdz, tad es tiem upurēšu, lai tie arī man palīdz; bet tie tam bija par krišanu, ir visam Israēlim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Un Ahazs ņēma Dieva nama traukus un sasita Dieva nama traukus un aizslēdza Tā Kunga nama durvis un taisīja sev altārus visos Jeruzālemes kaktos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Viņš taisīja arī ikkatrā Jūda pilsētā altārus, svešiem dieviem kvēpināt, - tā viņš apkaitināja To Kungu, savu tēvu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Un kas vēl par viņu stāstāms, un visi viņa ceļi, gan pirmie, gan pēdējie, redzi tie ir rakstīti Jūda un Israēla ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Un Ahazs aizmiga pie saviem tēviem, un viņu apraka Jeruzālemes pilsētā. Bet viņu neveda Israēla ķēniņu kapenēs. Un viņa dēls Hizkija palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Hizkija, divdesmit piecus gadus vecs, palika par ķēniņu un valdīja divdesmit deviņus gadus Jeruzālemē. Un viņa mātei bija vārds Abija, Zaharijas meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Un viņš darīja, kas Tam Kungam labi patika, tā kā viņa tēvs Dāvids bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Savas valdīšanas pirmā gadā, pirmā mēnesī, viņš atdarīja atkal Tā Kunga nama durvis un tās sataisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Un viņš lika nākt priesteriem un levitiem un tos sapulcināja tai pagalmā pret rītiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Un uz tiem sacīja: klausiet mani, jūs leviti, svētījaties nu paši un svētījat Tā Kunga, savu tēvu Dieva, namu un izmetat to nešķīstību no tās svētās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Jo mūsu tēvi grēkojuši un ļaunu darījuši Tā Kunga, mūsu Dieva, acīs, tie Viņu atstājuši un savu vaigu novērsuši no Tā Kunga dzīvokļa un tam griezuši muguru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Tie arī aizslēguši pagalma durvis un izdzēsuši tos eļļas lukturus un nav kvēpinājuši kvēpināmās zāles nedz upurējuši svētā vietā dedzināmos upurus Israēla Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Tādēļ Tā Kunga lielā bardzība nākusi pār Jūdu un Jeruzālemi, un Viņš tos darījis par riebumu un biedēkli un izsmieklu, tā kā paši redzat savām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Jo redzi, mūsu tēvi krituši caur zobenu, un mūsu dēli un mūsu meitas un mūsu sievas tādēļ ir cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Tad nu tas ir manā sirdī, derību derēt ar To Kungu, Israēla Dievu, lai Viņa bargā dusmība no mums novēršas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Nu tad, mani dēli, neesat kūtri, jo Tas Kungs jūs ir izredzējis, ka jums Viņa priekšā būs stāvēt, Viņam kalpot un būt Viņa kalpiem un kvēpinātājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Tad cēlās tie leviti: Makats, Amasajus dēls, un Joēls, Azarijas dēls, no Kehāta bērniem. Un no Merarus bērniem: Ķis, Abdus dēls, un Azarija, Jealeleēļa dēls, un no Geršona bērniem: Joūs, Zimas dēls, un Edens, Joūs dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Un no Elicafana bērniem: Zimrus un Jeīels; un no Asafa bērniem: Zaharija un Matanija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Un no Hemana bērniem: Jeiēls un Zemeja; un no Jedutuna bērniem: Šemaja un Uziēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Un tie sapulcināja savus brāļus un svētījās un nāca pēc ķēniņa pavēles, pēc Tā Kunga vārdiem šķīstīt Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Un tie priesteri iegāja Tā Kunga namā, to šķīstīt, un izmeta Tā Kunga nama pagalmā visu nešķīstību, ko tie atrada Tā Kunga namā; un tie leviti to ņēma un izmeta ārā, Kidronas upē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Un pirmā mēneša pirmā dienā tie sāka svētīt, un astotā mēneša dienā tie nāca Tā Kunga pagalmā un svētīja Tā Kunga namu astoņas dienas un pabeidza pirmā mēneša sešpadsmitā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Pēc tam tie nāca pie ķēniņa Hizkijas iekšā un sacīja: mēs visu Tā Kunga namu esam šķīstījuši, arī dedzināmo upuru altāri un visus viņa rīkus un to svētās maizes galdu ar visiem viņa rīkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Un visus rīkus, ko ķēniņš Ahazs, kamēr valdīja, bija apgānījis caur saviem grēkiem, tos mēs esam atkal sataisījuši un svētījuši, un redzi, tie ir Tā Kunga altāra priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Tad ķēniņš Hizkija agri cēlās un sapulcināja pilsētas virsniekus un gāja Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Un tie atveda septiņus vēršus un septiņus aunus un septiņus jērus un septiņus āžus par grēku upuri priekš valstības un priekš tās svētās vietas un priekš Jūda. Un viņš pavēlēja Ārona bērniem, tiem priesteriem, upurēt uz Tā Kunga altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Tad tie priesteri nokāva tos vēršus, saņēma tās asinis un tās slacināja uz altāri; tie nokāva arī tos aunus un slacināja tās asinis uz altāri, ir tos jērus tie nokāva un slacināja tās asinis uz altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Tad tie atveda tos āžus par grēku upuri ķēniņa un visas draudzes priekšā, un šie savas rokas tiem uzlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Un tie priesteri tos nokāva un slacināja viņu asinis pret altāri par grēku upuri, visu Israēli salīdzināt; jo ķēniņš to dedzināmo upuri un grēku upuri bija pavēlējis nest priekš visa Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Un viņš iecēla levitus Tā Kunga namā ar pulkstenīšiem, somastabulēm un koklēm pēc Dāvida un Gada, ķēniņa redzētāja, un pravieša Nātana pavēles; jo šī bija Tā Kunga pavēle caur viņa praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Tad nu tie leviti stāvēja ar Dāvida mūzikas rīkiem un tie priesteri ar bazūnēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Un Hizkija pavēlēja dedzināmo upuri upurēt uz altāra; un līdz kā dedzināmais upuris iesākās, sākās arī Tā Kunga dziesmas ar bazūnēm, vadītas no Dāvida, Israēla ķēniņa, mūzikas rīkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Un visa draudze metās zemē un dziesmas atskanēja un bazūnes bazūnēja no vienas vietas kamēr dedzināmais upuris bija pabeigts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Kad nu tas upuris bija pabeigts, tad ķēniņš nomētās ceļos un visi, kas pie viņa bija, un pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Un ķēniņš Hizkija un tie lielkungi pavēlēja levitiem, To Kungu slavēt ar Dāvida un ar redzētāja Asafa vārdiem, un tie slavēja priecādamies un metās zemē un pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Un Hizkija atbildēja un sacīja: nu jūs savas rokas esat pildījuši Tam Kungam, ejat klāt un nonesiet kaujamus upurus un pateicības upurus Tā Kunga namā. Un draudze atveda kaujamus upurus un pateicības upurus, un visi, kam bija labs prāts, dedzināmos upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Un to dedzināmo upuru skaits, ko draudze atnesa bija septiņdesmit vērši, simts auni, divsimt jēri; tie visi Tam Kungam bija par dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Un to svēto pateicības upuru bija sešsimt vērši un trīs tūkstoš avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Bet priesteru bija par maz un tie nevarēja visus dedzināmos upurus nodīrāt; tāpēc viņu brāļi, tie leviti, tiem palīdzēja, tiekams darbs tapa pabeigts un tiekams tie priesteri bija svētījušies; jo tie leviti bija dedzīgāki bijuši savā sirdī svētīties nekā tie priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Arī dedzināmo upuru bija liels skaits, līdz ar pateicības upuru taukiem un līdz ar dzeramiem upuriem pie tiem dedzināmiem upuriem. Tā tie pabeidza to kalpošanu pie Tā Kunga nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Un Hizkija un visi ļaudis priecājās par to, ka Dievs tiem ļaudīm to bija novēlējis; jo šī lieta bija ātri notikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Un Hizkija sūtīja pie visa Israēla un Jūda un rakstīja grāmatas arī uz Efraīmu un Manasu, lai nāk Tā Kunga namā uz Jeruzālemi, svētīt Pasa svētkus Tam Kungam, Israēla Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Jo ķēniņš ar tiem lielkungiem un ar visu draudzi Jeruzālemē bija nospriedis, svētīt Pasa svētkus otrā mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Jo īstenā laikā tie tos nepaspēja svētīt, tāpēc ka priesteru nebija diezgan svētījušies, un ļaudis Jeruzālemē nebija sapulcējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Un šī lieta patika ķēniņam un visai draudzei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Un tie pavēlēja, izsaukt pa visu Israēli, no Bēršebas līdz Danai, lai nāk Tam Kungam, Israēla Dievam, svētīt Pasa svētkus Jeruzālemē, - jo lielā sapulcē tie tos nebija turējuši, kā ir rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Tad skrējēji izgāja ar grāmatām no ķēniņa un lielkungu rokas pa visu Israēli un Jūdu, pēc ķēniņa pavēles sacīdami: jūs Israēla bērni, atgriežaties pie Tā Kunga, Ābrahāma, Īzaka un Israēla Dieva, tad arī viņš atgriezīsies pie tiem izglābtiem, kas jums atlikuši no Asiriešu ķēniņu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Un neesat tādi, kā jūsu tēvi un jūsu brāļi, kas noziegušies pret To Kungu, savu tēvu Dievu, kādēļ Viņš tos nodevis postam, kā paši redzat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nu tad neesat stūrgalvīgi kā jūsu tēvi, dodiet Tam Kungam savu roku un nāciet Viņa svētā vietā, ko Viņš ir svētījis mūžīgi un kalpojiet Tam Kungam, savam Dievam, tad Viņa bargā dusmība no jums novērsīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Jo kad jūs atgriezīsities pie Tā Kunga, tad jūsu brāļi un jūsu bērni dabūs žēlastību pie tiem, kas tos veduši cietumā, tā ka atkal atnāks šaizemē. Jo Tas Kungs, jūsu Dievs, ir žēlīgs un žēlsirdīgs un nenovērsīs Savu vaigu no jums, ja jūs atgriezīsities pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Tā tie skrējēji gāja no pilsētas uz pilsētu pa Efraīma un Manasus zemi līdz Zebulonam; bet šie tos apsmēja un apmēdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Bet taču kādi no Ašera un Manasus un Zebulona pazemojās un nāca uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Arī pār Jūdu bija Dieva roka, un Viņš tiem deva vienādu sirdi, darīt ķēniņa un lielkungu pavēli pēc Tā Kunga vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Un daudz ļaužu sapulcinājās Jeruzālemē, svētīt neraudzētās maizes svētkus otrā mēnesī, varen liela draudze.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Un tie cēlās un noārdīja tos altārus, kas bija Jeruzālemē, un ņēma visus kvēpināmos traukus un tos iemeta Kidronas upē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Tad tie nokāva Pasa jērus otrā mēnesī četrpadsmitā dienā. Un priesteri un leviti prata savu kaunu un svētījās un nesa dedzināmos upurus Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Un tie stāvēja savā kārtā, pēc savas tiesas, pēc Dieva vīra Mozus bauslības. Priesteri slacināja asinis no levitu rokas (ņemdami).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Jo daudz bija draudzē, kas nebija svētījušies; tādēļ leviti nokāva Pasa jērus priekš visiem, kas nebija šķīsti, ka tos Tam Kungam svētītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Jo liels ļaužu pulks no Efraīma un no Manasus, Īsašara un Zebulona nebija šķīstījušies, un taču tie ēda to Pasa jēru, bet ne tā kā ir rakstīts. Bet Hizkija lūdza par tiem un sacīja: Tas Kungs, tas žēlīgais, lai to piedod');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Visiem, kas savā sirdī taisījušies, meklēt Dievu To Kungu, savu tēvu Dievu, jebšu ne pēc svētās šķīstības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Un Tas Kungs paklausīja Hizkiju un dziedināja tos ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Tā Israēla bērni, kas Jeruzālemē bija sanākuši, turēja neraudzētās maizes svētkus septiņas dienas ar lielu prieku. Un leviti un priesteri slavēja To Kungu ikdienas ar mūzikas rīkiem Tam Kungam par godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Un Hizkija runāja laipnīgi ar visiem levitiem, kas Tā Kunga kalpošanu labi zināja; un tie ēda svētku upurus septiņas dienas un upurēja pateicības upurus un teica To Kungu, savu tēvu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Un visa draudze nosprieda, vēl otras septiņas dienas svētīt, un tie svētīja vēl otras septiņas dienas ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Jo Hizkija, Jūda ķēniņš, deva draudzei tūkstoš vēršus un septiņtūkstoš avis. Un tie lielkungi deva draudzei tūkstoš vēršus un desmit tūkstoš avis. Un tie priesteri svētījās lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Un visa Jūda draudze priecājās līdz ar priesteriem un levitiem, arī visa draudze, kas bija nākusi no Israēla, un tie svešinieki, kas bija atnākuši no Israēla zemes, un kas iekš Jūda piemita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Tā bija liels prieks Jeruzālemē, jo no Salamana, Dāvida dēla, Israēla ķēniņa, laika Jeruzālemē tā nebija bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Un priesteri un leviti cēlās un svētīja tos ļaudis, un viņu balss tapa paklausīta, un viņu lūgšana nāca viņa svētā dzīvoklī debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Kad nu viss tas bija pabeigts, tad viss Israēls, kas bija sanācis, izgāja Jūda pilsētās un nolauzīja tos uzceltos tēlus un nocirta tās Ašeras un izpostīja tos elku kalnus un altārus pa visu Jūdu un Benjaminu un Efraīmu un Manasu, līdz visu nopostīja. Un tad visi Israēla bērni griezās atpakaļ, ikkatrs uz savām mājām savās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Un Hizkija nolika priesteru un levitu kārtas pēc viņu kārtām, ikkatru pēc savas kalpošanas, priesterus un levitus pie dedzināmiem upuriem un pateicības upuriem, kalpot un teikt un slavēt Tā Kunga lēģeru vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Un (viņš nosprieda arī) ķēniņa daļu no sava padoma pie dedzināmiem upuriem rītos un vakaros un pie dedzināmiem upuriem svētdienās un jaunos mēnešos un svētkos, tā kā Tā Kunga bauslībā rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Un viņš sacīja uz tiem ļaudīm, kas Jeruzālemē dzīvoja, lai priesteriem un levitiem dod savu daļu, ka tie turētos pie Tā Kunga bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Kad nu šī valoda izpaudās, tad Israēla bērni atnesa bagātīgi pirmajus no labības, vīna un eļļas un medus un no visiem tīruma augļiem, arī desmito(tiesu) no visādām lietām tie atnesa lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Un Israēla un Jūda bērni, kas Jūda pilsētās dzīvoja tie arīdzan atnesa desmito no vēršiem un avīm un desmito no tā, ko tie bija svētījuši Tam Kungam, savam Dievam, un to sakrāva kaudžu kaudzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Trešā mēnesī tie iesāka tās kaudzes kraut, un septītā mēnesī tie pabeidza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Kad nu Hizkija un tie lielkungi nāca un tās kaudzes redzēja, tad tie teica To Kungu un Viņa tautu Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Un Hizkija vaicāja tiem priesteriem un levitiem par tām kaudzēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Un augstais priesteris Azarija, no Cadoka nama, runāja uz to un sacīja: kamēr ir sākts nest šo cilājamo upuri Tā Kunga namā, esam ēduši un paēduši, un daudz vēl atlicis, jo Tas Kungs ir svētījis Savus ļaudis, tā ka tik pulka ir atlicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Tad Hizkija pavēlēja taisīt kambarus pie Tā Kunga nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Un tos taisīja un tur ienesa to cilājamo upuri un to desmito un tās svētītās dāvanas ar uzticību. Un levits Kananija pār to bija tas virsnieks, un Šimejus, viņa brālis, tas otrais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Bet Jeīels un Azazija un Nagats un Azaēls un Jerimots un Jozabats un Eliēls un Jezmaķija un Makats un Benaja bija par uzlūkiem apakš Kananijas un Šimejus, viņa brāļa, caur ķēniņa Hizkijas un Azarijas, Dieva nama virsnieka, pavēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Un levits Korus, Jemnas dēls, tas vārtu sargs pret rītiem, bija iecelts pār tām dāvanām, ko Dievam deva no laba prāta, ka tam bija dot Tā Kunga cilājamo upuri un tās vissvētās dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Un tam bija pie rokas Edens un Minjamins un Ješuūs un Šemaja un Amarija un Šehanija priesteru pilsētās, ar uzticību izdalīt saviem brāļiem pēc viņu kārtām, ir lielam, ir mazam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Arī tiem, kas vīriešu radu rakstos tapa skaitīti, trīs gadus un vairāk veci būdami, - no visiem, kas Tā Kunga namā gāja pie tās ikdienišķās kalpošanas, savā amata kalpošanā pēc savas kārtas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Un arī tiem, kas priesteru un levitu radu rakstos tapa skaitīti pēc savu tēvu nama, kas divdesmit un vairāk gadus bija veci, pie viņu kalpošanas pēc savas kārtas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Arī tiem, kas radu rakstos tapa skaitīti ar saviem bērniem, sievām un dēliem un meitām visā draudzē, jo tie svētījās ar uzticību svētai kalpošanai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Un Ārona bērniem, priesteriem, uz tīrumiem visu viņu pilsētu apgabalos bija vīri, ar vārdu noteikti, daļu dot visiem priesteriem un radurakstos ierakstītiem levitiem no vīriešu kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Un tā Hizkija darīja pa visu Jūdu, un darīja, kas bija labi un pareizi un tiesa Tā Kunga, viņa Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Un visu darbu, ko viņš iesāka pie Dieva nama kalpošanas un pēc bauslības un likuma, savu Dievu meklēdams, to viņš darīja no visas sirds, un viņam labi izdevās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Pēc šīm lietām un šī ticības darba Sanheribs, Asīrijas ķēniņš, nāca un cēlās pret Jūdu un apmetās pret tām stiprām pilsētām un domāja tās raut pie sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Kad nu Hizkija redzēja, ka Sanheribs atnāca un bija apņēmies pret Jeruzālemi karot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Tad viņš sprieda ar saviem lielkungiem un varoņiem, aiztaisīt avotu ūdeņus ārpus pilsētas, un tie tam palīdzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Un daudz ļaužu sapulcējās, kas visus avotus aiztaisīja, arī to upi, kas vidū caur zemi tecēja, jo tie sacīja: kāpēc lai Asiriešu ķēniņi nākdami atrod daudz ūdens?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Un viņš ņēmās drošu prātu un uztaisīja visu mūri, kur tas bija plīsis, un to uzvilka līdz torņiem, un ārā viņš taisīja vēl citu mūri un nostiprināja Millu Dāvida pilsētā, un taisīja daudz ieročus un bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Un viņš iecēla kara virsniekus pār tiem ļaudīm un tos sapulcināja pie sevis laukā pie pilsētas vārtiem un tiem piekodināja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Esiet stipri un ņematies drošu prātu, nebīstaties un neizbaiļojaties priekš Asiriešu ķēniņa, nedz priekš visiem tiem pulkiem, kas pie viņa, jo pie mums ir vairāk, nekā pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Ar viņu ir miesas elkonis, bet ar mums ir Tas Kungs, mūsu Dievs, mums palīdzēt un vest mūsu karus. Un tie ļaudis paļāvās uz Hizkijas, Jūda ķēniņa, vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Pēc tam Sanheribs, Asīrijas ķēniņš, sūtīja savus kalpus uz Jeruzālemi (bet viņš pats bija pie Laķisa un pie viņa bija viss viņa valsts spēks) pie Hizkijas, Jūda ķēniņa, un pie visas Jūdu cilts, kas bija Jeruzālemē, un lika sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Tā saka Sanheribs, Asīrijas ķēniņš: uz ko jūs paļaujaties, palikdami ieslēgti Jeruzālemē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Vai Hizkija jūs nepiekrāpj un jūs nenodod nāvei caur badu un slāpēm, sacīdams: Tas Kungs, mūsu Dievs, mūs atpestīs no Asiriešu ķēniņa rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Vai šis nav tas Hizkija, kas viņa kalnus un altārus nopostījis un uz Jūdu un Jeruzālemi runājis un sacījis: viena altāra priekšā jums būs pielūgt un uz tā kvēpināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Vai nezināt, ko es un mani tēvi esam darījuši visām pasaules tautām? Vai pasaules tautu dievi varēja izglābt savas zemes no manas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kurš ir no visiem šo tautu dieviem, ko mani tēvi izdeldējuši, kas savus ļaudis varējis izglābt no manas rokas, ka jūsu Dievs jūs izglābtu no manas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Nu tad, lai Hizkija jūs nepieviļ, un neliekaties tā pārrunāties un neticat viņam. Jo ja nevienas citas tautas un valsts dievs nav varējis izglābt savus ļaudis no manas rokas un no manu tēvu rokas, tad jūsu Dievs ne tik jūs neizglābs no manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Un viņa kalpi runāja vēl vairāk pret Dievu, To Kungu, un pret Hizkiju, viņa kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Viņš rakstīja arī grāmatas, To Kungu, Israēla Dievu, zaimodams un pret viņu tā runādams un sacīdams: tā kā pasaules tautu dievi nav izglābuši savus ļaudis no manas rokas, tāpat arī Hizkijas Dievs Savus ļaudis neizglābs no manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Un tie sauca ar stipru balsi Jūdiski pret Jeruzālemes ļaudīm, kas uz mūra bija, tos izbiedēt un iztrūcināt, ka pilsētu varētu ieņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Un tie runāja pret Jeruzālemes Dievu tāpat, kā pret pasaules tautu dieviem, kas ir cilvēku roku darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Bet ķēniņš Hizkija un pravietis Ezaīja, Amoca dēls, lūdza par to un sauca uz debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Un Tas Kungs sūtīja eņģeli, kas nomaitāja visus varenos karavīrus un lielkungus un virsniekus Asīrijas ķēniņa lēģerī, ka tas ar kaunu atkal griezās atpakaļ uz savu zemi. Un kad viņš sava dieva namā gāja, tad tie, kas no viņa miesām bija cēlušies, viņu nokāva ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Tā Tas Kungs atpestīja Hizkiju un Jeruzālemes iedzīvotājus no Sanheriba, Asiriešu ķēniņa, rokas un no visu citu rokas un tos pasargāja visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Un daudzi nesa dāvanas Tam Kungam uz Jeruzālemi un dārgas lietas Hizkijam, Jūda ķēniņam, tā ka viņš pēc tam bija paaugstināts visu tautu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Tanī laikā Hizkija palika slims uz miršanu un tas lūdza To Kungu, un Viņš uz to runāja un tam deva vienu brīnuma zīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Bet Hizkija neatmaksāja tā, kā viņam bija labi darīts, jo viņa sirds sāka lepoties, tāpēc nāca liela dusmība pār viņu un pār Jūdu un Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Tad Hizkija pazemojās savas sirds lepnības dēļ ar Jeruzālemes iedzīvotājiem, tāpēc Tā Kunga bardzība pār viņiem nenāca, kamēr, Hizkija dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Un Hizkijam bija ļoti daudz bagātības un goda un viņš sev taisīja mantu kambarus sudrabam un zeltam un dārgiem akmeņiem un dārgām zālēm un priekšturamām bruņām un visādiem dārgiem rīkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Un klētis lauku augļiem, labībai, vīnam un eļļai un kūtis visādiem lopiem un laidarus ganāmiem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Viņš sev arī uztaisīja pilsētas, un tam bija avis un vērši lielā pulkā; jo Dievs tam deva ļoti lielu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Un šis Hizkija aiztaisīja Ģiona ūdens augšizteku un to vadīja uz leju pret vakara pusi uz Dāvida pilsētu, un Hizkijam viss viņa darbs laimējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Bet kad Bābeles lielkungi, kas pie viņa bija sūtīti, nāca vaicāt pēc tās brīnuma zīmes, kas tai zemē bija notikusi, tad Dievs viņu tā atstāja, ka to kārdināja, lai taptu zināms, kas būtu viņa sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Un kas vēl stāstāms par Hizkiju un viņa dievbijību, redzi, tas rakstīts pravieša Jesajas, Amoca dēla, parādīšanā un Jūda un Israēla ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Un Hizkija aizmiga pie saviem tēviem, un to apraka Dāvida bērnu augstākā kapu vietā, un visa Jūda valsts un Jeruzālemes iedzīvotāji tam parādīja godu, kad tas bija nomiris, un viņa dēls Manasus palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasus bija divpadsmit gadus vecs, kad palika par ķēniņu, un valdīja piecdesmit pieci gadus Jeruzālemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Un darīja, kas Tam Kungam nepatika, pēc to tautu negantībām, ko Tas Kungs Israēla bērnu priekšā bija izdzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Jo tas uztaisīja atkal kalnu altārus, ko viņa tēvs Hizkija bija nolauzījis, un uztaisīja altārus Baāliem un taisīja Ašeras un metās zemē priekš visa debess spēka un tiem kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Viņš taisīja altārus arī Tā Kunga namā, par ko Tas Kungs bija sacījis: Jeruzālemē lai ir mans vārds mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Un visam debess spēkam viņš cēla altārus Tā Kunga nama abējos pagalmos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Un viņš lika saviem dēliem caur uguni iet Ben-Inoma ielejā un zīlēja un vārdoja un būra un turēja zīlniekus un pūšļotājus; viņš darīja ļoti daudz, kas Tam Kungam nepatika, viņu kaitinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Arī elka tēlu, ko bija taisījis, viņš uzcēla Dieva namā, par ko Dievs uz Dāvidu un viņa dēlu Salamanu bija sacījis: šinī namā un Jeruzālemē, ko Es esmu izredzējis no visām Israēla ciltīm, Es Savu vārdu iecelšu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Un Israēla kājai Es vairs nelikšu kustēt no tās zemes, ko Es jūsu tēviem esmu nolicis, ja tie visu turēs un darīs, ko Es tiem esmu pavēlējis, pēc visas bauslības un likumiem un tiesām caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Tā Manasus Jūdu un Jeruzālemes iedzīvotājus vedināja uz ļaunu, ka tie niknāki darīja, nekā tie pagāni, ko Tas Kungs Israēla bērnu priekšā bija izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Un Tas Kungs gan runāja uz Manasu un uz viņa ļaudīm, bet tie neņēma vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Tāpēc Tas Kungs tiem sūtīja Asīrijas ķēniņa kara virsniekus; tie gūstīja Manasu saitēm un to apcietināja ar divām vara ķēdēm un to noveda uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Kad tas nu tā bija spaidos, tad tas pielūdza To Kungu, savu Dievu, un pazemojās ļoti priekš savu tēvu Dieva');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Un lūdza Viņu. Un Viņš no tā ļāvās pielūgties un paklausīja viņa sirsnīgo lūgšanu un pārveda to atkal uz Jeruzālemi viņa valstībā. Tad Manasus atzina, ka Tas Kungs ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Un pēc tam viņš uztaisīja Dāvida pilsētas āra mūri uz Ģiona pusi pret vakariem ielejā līdz tai vietai, kur ieiet pa Zivju vārtiem, un apkārt Ofelam, un to taisīja ļoti augstu, un ielika arīdzan kara virsniekus visās stiprās Jūda pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Un viņš nopostīja tos svešos dievus un to elku no Tā Kunga nama, ar visiem altāriem, ko viņš bija uztaisījis Tā Kunga nama kalnā un Jeruzālemē un izmeta tos ārā no pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Un viņš uzkopa Tā Kunga altāri un upurēja uz tā pateicības upurus un slavas upurus, un pavēlēja Jūda ļaudīm, kalpot Tam Kungam, Israēla Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Taču tie ļaudis vēl upurēja kalnos, bet Tam Kungam savam Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Un kas vēl par Manasu stāstāms, un viņa lūgšana uz savu Dievu un to redzētāju vārdi, kas uz viņu runājuši Tā Kunga, Israēla Dieva, vārdā, redzi, tas ir Israēla ķēniņu stāstos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Un viņa lūgšana un kā Dievs viņu paklausījis, arī visi viņa grēki un viņa pārkāpumi, un tās vietas, kur viņš uztaisījis elku altārus un uzcēlis Ašeras un elku tēlus, pirms tapa pazemots, tas rakstīts Kazaja stāstos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Un Manasus aizmiga pie saviem tēviem, un to apraka viņa namā, un viņa dēls Amons palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amons bija divdesmit divus gadus vecs, kad palika par ķēniņu, un valdīja divus gadus Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Un viņš darīja, kas Tam Kungam nepatika, tā kā viņa tēvs Manasus bija darījis, un Amons upurēja visiem elku tēliem, ko viņa tēvs Manasus bija taisījis, un tiem kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Bet viņš nepazemojās Tā Kunga priekšā, tā kā viņa tēvs Manasus bija pazemojies; bet šis Amons vairoja noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Un viņa kalpi sacēlās pret viņu un to nokāva viņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Un tie zemes ļaudis nokāva visus, kas bija sacēlušies pret ķēniņu Amonu, un tie zemes ļaudis cēla Josiju, viņa dēlu, par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Astoņus gadus Josija bija vecs, kad palika par ķēniņu, un valdīja trīsdesmit vienu gadu Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Un viņš darīja, kas Tam Kungam labi patika, un staigāja sava tēva Dāvida ceļos un neatkāpās ne pa labo, ne pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Jo savas valdīšanas astotā gada, kad vēl bija jauns, viņš sāka meklēt sava tēva Dāvida Dievu, un divpadsmitā gadā viņš Jūdu un Jeruzālemi sāka šķīstīt no elku kalniem un Ašerām un elku tēliem un lietām bildēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Un priekš viņa acīm Baālu altāri tapa salauzīti, un tos saules stabus tur virsū viņš nocirta, un tās Ašeras un tos elku tēlus un tās lietās bildes viņš salauzīja un tās darīja par pīšļiem un tos kaisīja uz to kapiem, kas tām bija upurējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Un elku priesteru kaulus viņš sadedzināja uz viņu altāriem, un tā viņš šķīstīja Jūdu un Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Arī pa Manasus un Efraīma un Sīmeana pilsētām līdz Naftalum, pa viņu posta vietām visapkārt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Viņš nolauzīja tos altārus, un tās Ašeras, un tos elka tēlus viņš satrieca un sadragāja, un nocirta visus saules stabus pa visu Israēla zemi, un griezās atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Savas valdīšanas astoņpadsmitā gadā, kad to zemi un to namu bija šķīstījis, viņš sūtīja Safanu, Acalijas dēlu, un Maāseju, pilsētas virsnieku, un Joaku, Joakasa dēlu, to kancleri, ka tie atkal uzkoptu Tā Kunga, sava Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Un tie nāca pie tā augstā priestera Hilķijas, un tiem deva to naudu, kas bija sanesta Dieva namā, ko leviti, tie sliekšņa sargi, bija sakrājuši no Manasus, no Efraīma un no visiem Israēla atlikušiem un no visas Jūda un Benjamina cilts un no Jeruzālemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Un tie to deva tiem darba vedējiem rokā, kas pār Tā Kunga namu bija iecelti, un tie darba vedēji to deva tiem strādniekiem, kas pie Tā Kunga nama strādāja, to namu sataisīt un uzkopt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Un tie to deva tiem amatniekiem un nama taisītājiem, pirkt izcirstus akmeņus un kokus sijām un baļķus tiem namiem, ko Jūda ķēniņi bija postā pametuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Un tie vīri darīja savu darbu uzticīgi. Un viņu uzraugi bija Jakats un Obadija, leviti no Merarus bērniem, un Mešulams no Kehāta bērniem; tie to darbu uzraudzīja; un visi tie leviti mācēja spēlēt mūzikas rīkus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Un bija pār nastu nesējiem un uzraugi pār visiem darba strādniekiem. Un citi leviti bija skrīveri un darba vedēji un vārtu sargi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Un kad tie to naudu izņēma, kas bija sanesta Tā Kunga namā, tad priesteris Hilķija atrada Tā Kunga bauslības grāmatu, kas caur Mozu dota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Un Hilķija atbildēja un sacīja uz skrīveri Safanu: es esmu atradis to bauslības grāmatu Tā Kunga namā. Un Hilķija deva Safanam to grāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Un Safans nesa to grāmatu ķēniņam un teica ķēniņam un sacīja: visu, ko tu saviem kalpiem pavēlējis, to tie dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Un tie izbēruši to naudu, kas Tā Kunga namā atrasta, un to devuši tiem darba vedējiem un strādniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Un skrīveris Safans ķēniņam teica un sacīja: priesteris Hilķija man ir devis grāmatu; un Safans no tās lasīja ķēniņam priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Kad nu ķēniņš dzirdēja tos bauslības vārdus, tad viņš saplēsa savas drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Un ķēniņš pavēlēja Hilķijam un Aīkamam, Safana dēlam, un Abdonam, Mihas dēlam, un skrīverim Safanam, un Azajam, ķēniņa kalpam, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Ejat, vaicājiet To Kungu par mani un par visiem atlikušiem iekš Israēla un Jūda, par šās grāmatas vārdiem, kas atrasta. Jo Tā Kunga bardzība ir liela, kas pret mums iedegusies, tāpēc ka mūsu tēvi nav turējuši Tā Kunga vārdu, nedz to darījuši, kas viss šai grāmatā rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Tad Hilķija ar ķēniņa vīriem nogāja pie pravietes Uldas, Šaluma, Takeata dēla Azras dēla, tā drēbju sarga sievas, (tā dzīvoja Jeruzālemē otrā pusē,) un to uz viņu runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Un viņa uz tiem sacīja: tā saka Tas Kungs, Israēla Dievs: sakāt tam vīram, kas jūs pie Manis sūtījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Tā saka Tas Kungs: redzi, Es sūtīšu nelaimi šai vietai un viņas iedzīvotājiem, visus tos lāstus, kas tai grāmatā rakstīti, ko tie lasījuši Jūda ķēniņa priekšā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Tāpēc ka tie Mani atstājuši un kvēpinājuši citiem dieviem, Mani kaitinādami ar visiem saviem roku darbiem, tad Mana bardzība pret šo vietu iedegsies un neizdzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Bet uz Jūda ķēniņu, kas jūs sūtījis, To Kungu vaicāt, jums tā būs sacīt: tā saka Tas Kungs, Israēla Dievs, par tiem vārdiem, ko tu esi dzirdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Tādēļ ka tava sirds ir mīksta palikusi un tu esi pazemojies Dieva priekšā, dzirdēdams Viņa vārdus pret šo vietu un viņas iedzīvotājiem, un esi pazemojies Manā priekšā un saplēsis savas drēbes un raudājis Manā priekšā, tad Es tevi esmu paklausījis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Redzi, Es tevi likšu pie taviem tēviem, un tu ar mieru tapsi glabāts savā kapā pie viņiem, un tavas acis neredzēs visu to ļaunumu, ko Es sūtīšu šai vietai un viņas iedzīvotājiem. Un tie ķēniņam atsacīja šos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Tad ķēniņš sūtīja un sapulcināja visus Jūda un Jeruzālemes vecajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Un ķēniņš gāja Tā Kunga namā līdz ar visiem Jūda vīriem un Jeruzālemes iedzīvotājiem, un ar priesteriem un levitiem un visiem ļaudīm, lieliem un maziem, un priekš viņu ausīm tapa lasīti visi derības vārdi no tās grāmatas, kas bija atrasta Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Un ķēniņš stāvēja savā vietā un derēja derību Tā Kunga priekšā, Tam Kungam pakaļ staigāt un no visas savas sirds un no visas savas dvēseles turēt Viņa baušļus un Viņa liecības un Viņa likumus un darīt tos derības vārdus, kas rakstīti šinī grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Un viņš uzņēma tai derībā visus, kas Jeruzālemē un Benjaminā atradās, un Jeruzālemes iedzīvotāji darīja pēc Dieva, savu tēvu Dieva, derības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Un Josija izdeldēja visas negantības no visām zemēm, kas Israēla bērniem piederēja, un darīja, ka visi, kas iekš Israēla atradās, kalpoja Tam Kungam, savam Dievam. Kamēr viņš dzīvoja, tie neatkāpās no Tā Kunga, savu tēvu Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Un Josija Tam Kungam noturēja Pasa svētkus Jeruzālemē, un tie nokāva to Pasa pirmā mēneša četrpadsmitā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Un viņš iecēla priesterus, ikvienu savā vietā, un tos iedrošināja pie Tā Kunga nama kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Un viņš sacīja uz tiem levitiem, kas visu Israēli mācīja, kas bija svētīti Tam Kungam: noliekat to svēto šķirstu tai namā, ko Salamans, Dāvida dēls, Israēla ķēniņš, ir uzcēlis; tas jums vairs nav jānes uz kamiešiem. Tad nu kalpojiet Tam Kungam, savam Dievam, un Viņa Israēla ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Un esat gatavi pēc savu tēvu namiem, pēc savām kārtām, kā Dāvids, Israēla ķēniņš, to uzrakstījis, un kā Salamans, viņa dēls, arī uzrakstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Un stāviet svētā vietā pēc tēvu namu kārtām par saviem brāļiem, tiem ļaužu bērniem, un pēc levitu tēvu namu kārtām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Un kaujiet to Pasa un svētījaties un sataisiet to saviem brāļiem, darīdami pēc Tā Kunga vārda caur Mozu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Un Josija deva tiem ļaudīm no sīkiem lopiem jērus un kazlēnus, tos visus par Pasa upuriem, visiem, kas tur atradās, trīsdesmit tūkstošus, un trīs tūkstošus vēršus; tas bija no ķēniņa mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Arī viņa lielkungi deva labprātības upurus tiem ļaudīm, priesteriem un levitiem: Hilķija un Zaharija un Jeīels, Dieva nama virsnieki, deva priesteriem uz Pasa svētkiem divtūkstoš sešsimt jērus un trīssimt vēršus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Un Kananija un Šemaja un Netaneēls, viņa brāļi, Hašabija un Jeīels un Jozabads, levitu virsnieki, deva levitiem uz Pasa svētkiem piectūkstoš jērus un piecsimt vēršus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Tā Dieva kalpošana tapa ierīkota, un priesteri stāvēja savā vietā un leviti pēc savām kārtām, pēc ķēniņa pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Un tie kāva to Pasa, un priesteri slacināja asinis no savām rokām, un leviti noplēsa ādas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Un tie atšķīra dedzināmos upurus, ka tos izdalītu ļaužu tēvu namu kārtām, Tam Kungam upurēt, kā Mozus grāmatā rakstīts. Tāpat arī darīja ar vēršiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Un tie cepa to Pasa pie uguns pēc likuma, bet svētos gabalus tie vārīja podos un katlos un pannās un steigšus to nesa visiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Pēc tam tie arī sev sataisīja un priesteriem. Jo priesteri, Ārona dēli, upurēja līdz pašai naktij dedzināmos upurus un taukus, tādēļ leviti sataisīja priekš sevis un priekš priesteriem, Ārona dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Un tie dziedātāji, Asafa dēli, stāvēja savās vietās, tā kā Dāvids un Asafs un Hemans un Jedutuns, ķēniņa redzētājs, pavēlējuši, arī vārtu sargi pie ikkatriem vārtiem. Un tiem nevajadzēja atkāpties no sava darba, bet viņu brāļi, tie leviti, to sataisīja priekš viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Tā visa Tā Kunga kalpošana tai dienā tapa izdarīta, Pasa svētki tika noturēti un tie dedzināmie upuri upurēti uz Tā Kunga altāra, kā ķēniņš Josija to bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Un Israēla bērni, kas tur atradās, turēja tai laikā Pasa svētkus un neraudzētās maizes svētkus septiņas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Tādi Pasa svētki iekš Israēla vēl nebija turēti no pravieša Samuēla laika, un neviens no Israēla ķēniņiem nebija turējis tādus Pasa svētkus, kā Josija turēja ar priesteriem un levitiem un ar visu Jūdu un Israēli, cik tur atradās, un ar Jeruzālemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Josijas valdīšanas astoņpadsmitā gadā šie Pasa svētki tapa turēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Pēc visa tā, kad Josija to namu bija uzkopis, tad Nekus, Ēģiptes ķēniņš, nāca karot pret Karķemisu pie Eifrat upes. Un Josija tam izgāja pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Bet viņš sūtīja vēstnešus pie tā un sacīja: kas man ar tevi, Jūda ķēniņ? Es šodien pret tevi neesmu nācis, bet pret kādu namu, kas karo pret mani, un Dievs ir sacījis, ka man būs steigties; nepretojies tu Dievam, kas ir ar mani, lai tas tevi nesamaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Bet Josija nenovērsās no tā, bet sataisījās ar viņu karot, un viņš neklausīja Nekus vārdiem no Dieva mutes un nāca, ar viņu kauties Meģidus ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Bet strēlnieki šāva uz ķēniņu Josiju, un ķēniņš sacīja uz saviem kalpiem: vediet mani projām, jo es esmu ļoti ievainots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Tad viņa kalpi to nocēla no ratiem un noveda uz viņa otriem ratiem, un to noveda Jeruzālemē. Un tas nomira un tapa aprakts savu tēvu kapos, un visa Jūda valsts un Jeruzāleme žēlojās par Josiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Un Jeremija taisīja vienu raudu dziesmu par Josiju, un visi dziedātāji un dziedātājas runāja savās raudu dziesmās par Josiju līdz šai dienai, un to iestādīja par likumu iekš Israēla; un redzi, tās ir rakstītas raudu dziesmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Un kas vēl par Josiju stāstāms, un viņa dievbijība pēc Tā Kunga bauslības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Arī viņa pirmās un pēdējās lietas, redzi, tās rakstītas Israēla un Jūda ķēniņu grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Tad tās zemes ļaudis ņēma Joakasu, Josijas dēlu, un to cēla par ķēniņu viņa tēva vietā Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Divdesmit trīs gadus Joakas bija vecs, kad palika par ķēniņu, un valdīja trīs mēnešus Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Jo Ēģiptes ķēniņš to nocēla Jeruzālemē un uzlika tai zemei par mesliem simts talentus sudraba un vienu talentu zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Un Ēģiptes ķēniņš cēla Elijaķimu, viņa brāli, par Jūda un Jeruzālemes ķēniņu, un deva viņam citu vārdu, Jojaķimu; bet Joakasu, viņa brāli, Nekus paņēma un noveda uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Divdesmit piecus gadus Jojaķims bija vecs, kad palika par ķēniņu, un valdīja vienpadsmit gadus Jeruzālemē un darīja, kas Tam Kungam, viņa Dievam, nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Pret šo NebukadNecars, Bābeles ķēniņš, cēlās un to saistīja ar divām vara ķēdēm un to noveda uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Un NebukadNecars aizveda arī kādus no Tā Kunga nama traukiem uz Bābeli, un tos nolika Bābelē savā dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Un kas vēl stāstāms par Jojaķimu, un viņa negantību, ko viņš darījis, un kas pie viņa atrasts, redzi, viss tas rakstīts Israēla un Jūda ķēniņu grāmatā. Un viņa dēls Jojaķins palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Astoņ(padsmit) gadus Jojaķins bija vecs, kad palika par ķēniņu, un valdīja trīs mēnešus un desmit dienas Jeruzālemē un darīja, kas Tam Kungam nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Un kad jauns gads atnāca, tad ķēniņš NebukadNecars sūtīja un to lika novest uz Bābeli līdz ar Tā Kunga nama dārgākiem traukiem un cēla Cedeķiju, viņa brāli par Jūda un Jeruzālemes ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Divdesmit un vienu gadu Cedeķija bija vecs, kad palika par ķēniņu, un valdīja vienpadsmit gadus Jeruzālemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Un darīja, kas Tam Kungam, viņa Dievam nepatika. Viņš nepazemojās priekš pravieša Jeremijas, kas no Tā Kunga mutes runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Viņš atkāpās arī no ķēniņa NebukadNecara, kas viņu pie Dieva bija zvērinājis, un tapa stūrgalvīgs un apcietināja savu sirdi, ka neatgriezās pie Tā Kunga, Israēla Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Tāpat arī visi priesteru virsnieki un ļaudis vairoja savus grēkus pēc visām pagānu negantībām un sagānīja Tā Kunga namu, ko viņš Jeruzālemē bija svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Un Tas Kungs, viņu tēvu Dievs, tikuši(neatlaidīgi) pie tiem sūtīja savus vēstnešus vienā sūtīšanā. Jo viņš žēloja savus ļaudis un savu mājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Bet tie apmēdīja Dieva vēstnešus un nicināja viņu vārdus un apsmēja viņa praviešus, tiekams Tā Kunga bardzība pret viņa ļaudīm tik augsti cēlās, ka dziedināšanas vairs nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Tad viņš pamodināja pret tiem Kaldeju ķēniņu, un tas nokāva viņu jaunos vīrus ar zobenu viņu svētā namā, un netaupīja nedz jaunekļus nedz jaunavas, nedz vecus nedz sirmgalvjus; Dievs tos visus nodeva viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Un visus Dieva nama traukus, lielus un mazus, un Tā Kunga nama mantas, ir ķēniņa ir viņa lielkungu mantas, visu viņš nodeva uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Un tie sadedzināja Dieva namu un nolauzīja Jeruzālemes mūrus un sadedzināja visus viņas skaistos namus ar uguni, ka visi viņas dārgumi tapa nopostīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Un kas no zobena atlika, tos viņš aizveda cietumā uz Bābeli, un tie viņam un viņa dēliem palika par kalpiem, tiekams Persiešu valdība sākās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Lai piepildītos Tā Kunga vārds caur Jeremijas muti: “kamēr tā zeme būs bagāti baudījusi savu dusēšanu“; visā tai posta laikā tā dusēja, kamēr septiņdesmit gadi piepildījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Un Kirus, Persiešu ķēniņa, pirmā gadā, lai Tā Kunga vārds caur Jeremiju runāts piepildītos, Tas Kungs pamodināja Kirus, Persiešu ķēniņa garu, ka tas visā savā valstī lika izsaukt un arī izrakstīt un sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Tā saka Kirus, Persiešu ķēniņš: Tas Kungs, debesu Dievs, man devis visas zemes valstis, un tas man pavēlējis, viņam namu uzcelt Jeruzālemē, Jūdu zemē; kas nu jūsu starpā ir no viņa ļaudīm, ar to lai ir Tas Kungs, viņa Dievs, un tas lai noiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Persiešu ķēniņa Kirus pirmā gadā, lai piepildītos Tā Kunga vārds caur Jeremijas muti, Tas Kungs pamodināja Persiešu ķēniņa Kirus garu, ka viņš ar vārdiem un arī ar grāmatām pa visu savu valsti lika izsludināt un sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Tā saka Kirus, Persiešu ķēniņš: Tas Kungs, debesu Dievs, man devis visas pasaules valstis, un Tas man pavēlējis, Viņam namu uzcelt Jeruzālemē, Jūdu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kas nu jūsu starpā ir no Viņa ļaudīm, lai viņa Dievs ir ar to, un lai tas iet uz Jeruzālemi Jūdu zemē, un lai uzceļ Tā Kunga, Israēla Dieva, namu. Viņš ir tas Dievs, kas Jeruzālemē dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Un kas vēl atlikuši visās vietās, kur tie piemīt, lai tās vietas ļaudis tiem palīdz ar sudrabu un zeltu un ar mantu un ar lopiem un arī ar laba prāta dāvanu priekš Jeruzālemes Dieva nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Tad Jūda un Benjamina cilts tēvi un priesteri un leviti cēlās ar visiem, kam Dievs garu pamodināja uz ceļu doties, uzcelt Tā Kunga namu Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Un visi viņu apkārtējie stiprināja viņu rokas ar sudraba traukiem, ar zeltu, ar mantu un lopiem un dārgiem zemes augļiem, bez tām labprātīgām upuru dāvanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Un ķēniņš Kirus atdeva Tā Kunga nama traukus, ko NebukadNecars no Jeruzālemes bija aizvedis un nolicis sava dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Un Kirus, Persiešu ķēniņš, tos atdeva caur mantas sargu Mitredatu, un tas tos ieskaitīja Šešbacaram, Jūda virsniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Un šis ir viņu skaits: trīsdesmit zelta bļodas, tūkstoš sudraba bļodas, divdesmit deviņi naži,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Trīsdesmit zelta biķeri, četrsimt desmit citi sudraba biķeri un tūkstoš citi trauki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Visu zelta un sudraba trauku bija piectūkstoš četrsimt. Šos visus Šešbacars pārveda, kad tie aizvestie no Bābeles gāja atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Šie ir tie valsts bērni, kas no cietuma zemes atpakaļ griezās, ko NebukadNecars, Bābeles ķēniņš, bija aizvedis uz Bābeli, un tie griezās atpakaļ uz Jeruzālemi un Jūdu, ikkatrs uz savu pilsētu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Tie nāca ar Zerubabeli, Ješuū, Nehemiju, Seraju, Reēlaju, Mordohaju, Bilšanu, Mišparu, Biģevaju, Rehumu un Baēnu. Šis ir Israēla vīru skaits:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Pareūs bērni: divtūkstoš simts septiņdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Šefatijas bērni: trīssimt septiņdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Araka bērni: septiņsimt septiņdesmit un pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'PaātMoaba bērni, no Ješuūs Joaba bērniem: divtūkstoš astoņsimt un divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elama bērni: tūkstoš divsimt piecdesmit un četri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Zatus bērni: deviņsimt četrdesmit un pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Zakajus bērni: septiņsimt un sešdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Banus bērni: sešsimt četrdesmit un divi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebajus bērni: sešsimt divdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Azgada bērni: tūkstoš divsimt divdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikama bērni: sešsimt sešdesmit un seši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Biģevajus bērni: divtūkstoš piecdesmit un seši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adina bērni: četrsimt piecdesmit un četri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Atera bērni, no Hizkijas: deviņdesmit un astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Becajus bērni: trīssimt divdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Joras bērni: simts un divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hašuma bērni: divsimt divdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Ģiberas bērni: deviņdesmit un pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Bētlemes bērni: simts divdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netofas vīri: piecdesmit un seši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Anatotas vīri: simts divdesmit un astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Asmavetas bērni: četrdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'KiriatAārimas, Kaviras un Beērotas bērni: septiņsimt četrdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Rāmas un Gabas bērni: sešsimt divdesmit un viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mikmasas vīri: simts divdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Bēteles un Ajas vīri: divsimt divdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Nebus bērni: piecdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Makbisa bērni: simts piecdesmit un seši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Otra Elama bērni: tūkstoš divsimt piecdesmit un četri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Harima bērni: trīssimt un divdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Lodas, Adidas un Onus bērni: septiņsimt divdesmit un pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Jērikus bērni: trīssimt četrdesmit un pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Zenaūs bērni: trīs tūkstoš sešsimt un trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Priesteri: Jedajas bērni, no Ješuūs nama: deviņsimt septiņdesmit un trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Imera bērni: tūkstoš piecdesmit un divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pašhura bērni: tūkstoš divsimt četrdesmit un septiņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Harima bērni: tūkstoš un septiņpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leviti: Ješuūs un Kadmiēļa bērni, no Odavijas bērniem: septiņdesmit un četri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Dziedātāji: Asafa bērni: simts divdesmit un astoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Vārtu sargu bērni: Šaluma bērni, Atera bērni, Talmona bērni, Akuba bērni, Atita bērni, Zobaja bērni, pavisam: simts trīsdesmit un deviņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Dieva nama kalpotāji: Cikus bērni, Azuva bērni, Tabaota bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Ķerus bērni, Zius bērni, Padona bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebana bērni, Agaba bērni, Akuba bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Agaba bērni, Zamlajus bērni, Anana bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Ģidela bērni, Gaāra bērni, Reajas bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Recina bērni, Nekoda bērni, Gazama bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Uzus bērni, Paseūs bērni, Besajus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asnus bērni, Meūnima bērni, Nevusima bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbuka bērni, Akuva bērni, Arura bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Baceluta bērni, Meķida bērni, Arzas bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkus bērni, Sisera bērni, Tamus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Necius bērni, Ativus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salamana kalpu bērni, Sotajus bērni, Sofereta bērni, Prudus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaēlus bērni, Darkona bērni, Ģideļa bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Šefatijas bērni, Atila bērni, Poķereta bērni no Cebaīm, Amja bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Visu Dieva nama kalpotāju un Salamana kalpu bērnu bija trīssimt deviņdesmit un divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Šie ir, kas aizgāja no TelMelakas, TelArzus, Ķeruba, Adana, Imera; bet tie sava tēva namu nevarēja pierādīt nedz savu dzimumu, vai tie bija no Israēla:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delajas bērni, Tobijas bērni, Nekoda bērni: sešsimt piecdesmit un divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Un no priesteru bērniem: Abajus bērni, Akoca bērni, Barzilajus bērni, kas no Gileādieša Barzilajus meitām sievu bija ņēmis un pēc viņas vārda tapa nosaukts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Šie meklēja savus radu rakstus, bet neatrada, tāpēc tie no priestera amata tapa atmesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Un zemes valdnieks uz tiem sacīja: lai tie neēd no tā visusvētākā, kamēr priesteris celsies ar urim un tumim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Visa draudze kopā bija četrdesmit divtūkstoš trīssimt un sešdesmit,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Bez viņu kalpiem un kalponēm, - to bija septiņtūkstoš trīssimt trīsdesmit un septiņi; un tiem bija divsimt dziedātāji un dziedātājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Zirgu viņiem bija septiņsimt trīsdesmit un seši, divsimt četrdesmit un pieci zirgēzeļi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Četrsimt trīsdesmit un pieci kamieļi, seštūkstoš septiņsimt un divdesmit ēzeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Un kādi cilts virsnieki, kad tie nāca Tā Kunga namā Jeruzālemē, tad tie no laba prāta deva pie Dieva nama, lai tas taptu uzcelts savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Cik spēja, tik tie deva pie būves naudas: sešdesmit vienu tūkstoti zelta drakmu un piectūkstoš mārciņas sudraba un simts priesteru svārkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Un priesteri un leviti un tie ļaudis un dziedātāji un vārtu sargi un Dieva nama kalpotāji dzīvoja savās pilsētās un viss Israēls savās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Kad nu septītais mēnesis atnāca, un Israēla bērni bija savās pilsētās, tad tie ļaudis sapulcējās Jeruzāleme tā kā viens vienīgs vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Un Ješuūs, Jocadaka dēls, cēlās ar saviem brāļiem, tiem priesteriem un Zerubabels, Šealtiēļa dēls, ar saviem brāļiem, un uzcēla Israēla Dieva altāri, uz viņa upurēt dedzināmos upurus, kā stāv rakstīts Mozus, Tā Dieva vīra, bauslībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Un tie uzcēla to altāri savā vietā, gan bīdamies no tās zemes tautām, un uz tā upurēja dedzināmos upurus Tam Kungam, dedzināmos upurus rītos un vakaros,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Un turēja lieveņu svētkus, kā stāv rakstīts, un upurēja ikdienas dedzināmos upurus pēc tā skaita, kā pienācās, ikdienas savus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Un pēc tam arī tos nemitējamos dedzināmos upurus un kā nākas jaunos mēnešos un visos, Tam Kungam svētītos svētkos un priekš ikviena, kas Tam Kungam atnesa kādu labprātības dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'No septītā mēneša pirmās dienas tie iesāka Tam Kungam upurēt dedzināmos upurus; bet Tā Kunga nama pamats vēl nebija likts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Un tie deva naudu akmeņu cirtējiem un amatniekiem un ēst un dzert un eļļu Sidoniešiem un Tiriešiem, lai tie vestu ciedru kokus no Lībanus jūrmalā uz Jazu, kā Kirus, Persiešu ķēniņš, tiem bija vēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Tad nu otrā gadā pēc viņu atnākšanas pie Dieva nama Jeruzālemē, otrā mēnesī, Zerubabels, Šealtiēļa dēls, un Ješuūs, Jocadaka dēls, un tie atlikušie no viņu brāļiem, priesteri un leviti un visi, kas no cietuma zemes bija pārnākuši Jeruzālemē, iesāka un iecēla tos levitus, kas divdesmit gadus veci un pāri, par uzraugiem pie Tā Kunga nama darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Un Ješuūs, viņa dēli un viņa brāļi, Kadmiēls un viņa dēli, un Jūda dēli stāvēja kā viens vienīgs vīrs, uzraugi būdami pār tiem, kas to darbu pie Tā Kunga nama darīja, tāpat Henadada bērni, viņu dēli un viņu brāļi, tie leviti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Kad nu tie amatnieki Tā Kunga namam lika pamatu, tad nostādīja priesterus amata drēbēs ar bazūnēm un levitus, Asafa dēlus, ar pulkstenīšiem, To Kungu teikt ar Dāvida, Israēla ķēniņa dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Un tie dziedāja viens par otru, To Kungu teikdami un slavēdami, ka Tas ir labs, un Viņa žēlastība paliek mūžīgi pār Israēli. Un visi ļaudis gavilēja ar lielu gavilēšanu, To Kungu teikdami, ka pamats bija likts Tā Kunga namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Bet daudz priesteru un levitu un cilts tēvu, kas bija veci, kas bija redzējuši to pirmo namu, kad tie šim namam redzēja pamatu liekam, tad tie raudāja gauži. Bet daudz atkal pacēla savas balsis ar gavilēšanu un ar prieku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Tā ka tie ļaudis nevarēja izšķirt to gaviļu un prieka balsi no ļaužu raudāšanas, jo tie ļaudis gavilēja ar skaņu gavilēšanu, un tā skaņa bija tālu dzirdama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Kad nu Jūda un Benjamina pretinieki dzirdēja, ka tie no cietuma pārnākušie atkal ceļ namu Tam Kungam, Israēla Dievam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Tad tie nāca pie Zerubabela un pie tiem cilts tēviem un uz tiem sacīja: mēs celsim līdz ar jums. Jo mēs meklējam jūsu Dievu tāpat kā jūs, un tam esam upurējuši no tā laika, kad EsarHadons, Asīrijas ķēniņš, mūs atvedis uz šejieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Bet Zerubabels un Ješuūs un tie atlikušie Israēla cilts tēvi uz viņiem sacīja: jums nenākās ar mums celt namu mūsu Dievam, bet mēs gribam priekš sev uzcelt Tam Kungam, Israēla Dievam, kā mums Kirus, Persiešu ķēniņš, pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Tad tās zemes ļaudis nogurdināja Jūdu ļaužu rokas un atbiedēja tos no celšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Un pirka pret tiem padomniekus, iznīcināt viņu nodomu visā Kirus, Persiešu ķēniņa, laikā, līdz Darius, Persiešu ķēniņa, valdīšanai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Un kad Ahasverus valdīja, viņa valdīšanas iesākumā, tie rakstīja sūdzības grāmatu pret Jūda un Jeruzālemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Un Artakserksus dienās Bišlams, Mitredats, Tabeēls un citi viņu biedri rakstīja Artakserksum, Persiešu ķēniņam. Un tas grāmatas raksts bija sīriski rakstīts un sīriski tulkots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Kanclers Rehums un rakstu vedējs Zimzajus rakstīja grāmatu pret Jeruzālemi ķēniņam Artakserksum ar šiem vārdiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Toreiz (rakstīja): kanclers Rehums un rakstu vedējs Zimzajus un citi viņu biedri, no Dinas, no Arvaksadas, no Tarplas, no Avarzijas, no Arakas, no Bābeles, no Zuzanas, no Deas, no Elama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Un citas tautas, ko tas lielais un slavējamais Aznavars atvedis un tām licis dzīvot Samarijas pilsētās, un tie citi viņpus upes, un tā projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Un šis ir tas raksts, ko tie viņam, proti ķēniņam Artakserksum, sūtīja: tavi kalpi, tie vīri viņpus upes, un tā projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Lai ķēniņam ir zināms, ka tie Jūdi, kas no tevis aizgājuši, pie mums atnākuši uz Jeruzālemi, uzceļ to dumpīgo un nikno pilsētu, uztaisa mūrus un izlabo pamatus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Tad nu lai ķēniņam ir zināms: kad šī pilsēta taps uzcelta un tie mūri būs uztaisīti, tad tie nedos meslus, tiesu un muitu, un tā ķēniņiem nāks zudums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Kad nu mēs visi no ķēniņa pils sāli un maizi ēdam, un mums nepieklājās redzēt ķēniņa zudumu, tad esam sūtījuši un ķēniņam ziņu par to devuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Lai meklē tavu tēvu laiku grāmatā, tad tu atzīsi, šo pilsētu esam bijušu dumpīgu un ķēniņiem un valstīm pretīgu pilsētu, un ka tie jau no vecu veciem laikiem dumpojušies, - tāpēc šī pilsēta ir izpostīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Mēs ķēniņam darām zināmu, ka, ja šī pilsēta taps uzcelta un viņas mūri taps sataisīti, tev caur to nekas vairs neatliks viņpus upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Tad ķēniņš sūtīja atkal grāmatu kanclerim Rehumam un rakstu vedējam Zimzajum un tiem citiem viņu biedriem, kas Samarijā dzīvoja, un tiem citiem viņpus upes: mieru! Un tā projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Tā grāmata, ko jūs man esat sūtījuši, manā priekšā skaidri izlasīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Un es esmu pavēlējis, lai meklē. Un ir atrasts, ka šī pilsēta priekšlaikos pret ķēniņiem ir cēlusies, un ka tur ir celts dumpis un nemiers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Vareni ķēniņi bijuši Jeruzālemē un valdījuši pār visu zemi viņpus upes, un tiem doti mesli, tiesa un muita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Tāpēc pavēliet, ka šiem vīriem būs liegt, šo pilsētu uztaisīt, kamēr no manis nāks pavēle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Sargājaties tad, ka nepārskataties, lai ļaunums nevairojās un ķēniņam nenāk zudums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Kad nu ķēniņa Artakserksus grāmatas raksts bija izlasīts Rehuma un rakstu vedēja Zimzaja un viņu biedru priekšā, tad tie cēlās steigšus uz Jeruzālemi pret tiem Jūdiem un tos aizkavēja ar varu un spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Tad tas darbs pie Dieva nama Jeruzālemē mitējās un palika mierā līdz Persiešu ķēniņa Dārija valdīšanas otram gadam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Un pravieši Hagaja un Zaharija, Idus dēls, sludināja tiem Jūdiem, kas Jūdā un Jeruzālemē dzīvoja, - Israēla Dieva vārdā tie uz viņiem runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tad Zerubabels, Šealtiēļa dēls, un Ješuūs, Jocadaka dēls, cēlās un sāka uzcelt Dieva namu Jeruzālemē, un līdz ar tiem tie Dieva pravieši, kas tos iedrošināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Tanī laikā pie tiem atnāca Tatnajs, zemes valdītājs viņpus upes, un ŠetarBoznajs ar saviem biedriem, un uz tiem tā sacīja: kas jums atvēlējis, šo namu uztaisīt un šo mūri uzcelt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Tad mēs viņiem sacījām to vīru vārdus, kas šo darbu taisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Bet viņu Dieva acs bija pār Jūdu vecajiem, ka tie viņus neaizkavēja, kamēr šī lieta Dārijam nāca zināma un tie grāmatu par to dabūja atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Šis ir tās grāmatas raksts, ko Tatnajs, zemes valdītājs viņpus upes, ar ŠetarBoznaju un viņa biedriem, Avarzaķiešiem, kas viņpus upes dzīvoja, rakstīja ķēniņam Dārijam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Tie sūtīja viņam grāmatu un tanī tā bija rakstīts: viss miers lai ir ķēniņam Dārijam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Ķēniņam lai ir zināms, ka mēs esam nogājuši Jūda zemē tā lielā Dieva namā, kas top uzcelts no cirstiem akmeņiem, un baļķi top ielikti sienās, un darbs top tikuši(rūpīgi) darīts un izdodas labi caur viņu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Mēs tad esam vaicājuši tos vecajus un uz viņiem sacījuši: kas jums atvēlējis, šo namu uzcelt un šo mūri uztaisīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Mēs arī viņu vārdus esam izprasījuši no tiem, tev dot ziņu un rakstīt to vīru vārdus, kas viņu virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Bet tie mums atdeva tādu atbildi un sacīja: mēs esam debesu un zemes Dieva kalpi un uzceļam to namu, kas jau sen priekšgados bijis uzcelts, jo liels Israēla ķēniņš to uzcēlis un pabeidzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Tādēļ vien ka mūsu tēvi bija apkaitinājuši to debesu Dievu, viņš tos nodevis Kaldeja NebukadNecara, Bābeles ķēniņa, rokā, un tas šo namu nopostījis un tos ļaudis aizvedis cietumā uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Bet Bābeles ķēniņa Kirus pirmā gadā ķēniņš Kirus pavēlējis, šo Dieva namu uzcelt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Un arī Dieva nama zelta un sudraba traukus, ko NebukadNecars izvedis no Dieva nama Jeruzālemē un tos novedis sava dieva namā uz Bābeli, tos ķēniņš Kirus ir ņēmis no Bābeles dieva nama, un tie ir atdoti vienam ar vārdu Šešbacars, ko viņš bija iecēlis par zemes valdītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Un viņš uz to sacīja: ņem šos traukus, ej un noved tos uz to Dieva namu, kas Jeruzālemē, un lai tas Dieva nams top uzcelts savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tad šis Šešbacars nāca un lika pamatu Dieva namam Jeruzālemē, un tā no tā laika līdz šim ir strādāts, bet ne pabeigts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Ja nu ķēniņam patīk, tad lai meklē ķēniņa mantu namā, kas Bābelē, vai tā ir, ka no ķēniņa Kirus pavēlēts, uzcelt Dieva namu Jeruzālemē, un lai ķēniņa pavēle par to mums top sūtīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Tad ķēniņš Dārijs pavēlēja un sūtīja grāmatu namā, kur mantas tika noliktas Bābelē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Un Akmetas pilī, kas Medenes valstī, atrada satītu grāmatu, kur tā bija rakstīts par piemiņu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Ķēniņa Kirus pirmā gadā ķēniņš Kirus pavēlēja par Dieva namu Jeruzālemē: lai uztaisa to namu par vietu, kur upurus upurē, un viņa pamatam būs stipram būt; viņa augstums lai ir sešdesmit olektis un viņa platums sešsimt olektis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Trīs sienas lai ir no cirstiem akmeņiem un viena siena no jauniem baļķiem. Un to maksu būs dot no ķēniņa nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Un Dieva nama zelta un sudraba traukus būs atdot ko NebukadNecars no Dieva nama, kas Jeruzālemē, aizvedis un uz Bābeli novedis, ka tie nāk atkal uz Dieva namu Jeruzālemē, savā vietā, un tos būs nest Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Tad nu, Tatnaj, tu zemes valdītājs viņpus upes, tu ŠetarBoznaj ar saviem biedriem, tiem Avarzaķiešiem, kas viņpus upes, turaties tālu nost no viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Ļaujat tiem vaļu, pie šī Dieva nama strādāt, ka Jūdu zemes valdītājs un Jūdu vecaji uzceļ to Dieva namu savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Vēl no manis top pavēlēts, kas jums jādara Jūdu vecajiem pie šā Dieva nama uzcelšanas, proti, ka no ķēniņa mantas, no muitas viņpus upes būs tikuši(pilnu un bez kavēšanās) maksu dot šiem vīriem, ka tie netop aizkavēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Un visu, ko tiem vajag, jaunus vēršus, aunus un jērus par dedzināmiem upuriem tam debesu Dievam, kviešus, sāli, vīnu un eļļu, pēc Jeruzālemes priesteru vajadzības, - to viņiem būs ikdienas dot bez atraušanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Lai tie upurē upurus par saldu smaržu tam debesu Dievam, un lūdz par ķēniņa un viņa bērnu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Vēl no manis top pavēlēts, ja kas šo vārdu pārkāps, tad no viņa nama būs baļķi ņemt un uzcelt un viņu pie tā pakārt, un viņa namu būs sagāzt gruvešos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Bet tas Dievs, kam vārds tur mājo, lai gāž zemē visus ķēniņus un ļaudis, kas savas rokas izstiepj, pretī turēties un postīt to Dieva namu Jeruzālemē. Es Dārijs to esmu pavēlējis, to tikuši(rūpīgi) būs darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'To nu tikuši(rūpīgi) darīja Tatnajs, zemes valdītājs viņpus upes un ŠetarBoznajs ar saviem biedriem, - tā kā ķēniņš Dārijs bija sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Un Jūdu vecaji būvēja, un darbs labi izdevās pēc pravieša Hagaja un Zaharijas, Idus dēla, sludināšanas. Un tie to uztaisīja un pabeidza pēc Israēla Dieva pavēles un pēc Kirus, Dārija un Artakserksus, Persiešu ķēniņu, pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Un šo namu pabeidza Adara mēneša trešā dienā; tas bija ķēniņa Dārija valdīšanas sestais gads.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Un Israēla bērni, priesteri un leviti un tie citi no cietuma pārnākušie iesvētīja šo Dieva namu ar prieku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Un upurēja pie šā Dieva nama iesvētīšanas simts vēršus, divsimt aunus, četrsimt jērus un divpadsmit āžus par grēku upuri priekš visa Israēla, pēc Israēla cilšu skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Un iecēla priesterus viņu kārtās un levitus viņu kārtās Jeruzālemes Dieva kalpošanai, kā rakstīts Mozus grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Tie no cietuma pārnākušie turēja arī Pasa svētkus pirmā mēneša četrpadsmitā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Jo priesteri un leviti bija šķīstījušies, un visi bija šķīsti kā viens vienīgs vīrs, un tie nokāva tos Pasa jērus priekš visiem no cietuma pārnākušiem un priekš saviem brāļiem, tiem priesteriem, un priekš sev pašiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Tā Israēla bērni, kas no svešuma bija pārnākuši, to ēda līdz ar visiem, kas no tās zemes pagānu nešķīstības bija atšķīrušies un tiem piebiedrojušies, meklēdami To Kungu, Israēla Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Un tie turēja neraudzētās maizes svētkus septiņas dienas ar prieku. Jo Tas Kungs tos bija priecīgus darījis un uz tiem pagriezis Asīrijas ķēniņa sirdi, ka viņu rokas tapa stiprinātas pie Dieva, Israēla Dieva, nama darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Un pēc šiem notikumiem, kad Persiešu ķēniņš Artakserksus valdīja, cēlās Ezra, tas bija Seraja, tas Azarijas, tas Hilķijas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Tas Šaluma, tas Cadoka, tas Aķitoba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Tas Amarijas, tas Azarijas, tas Merajota,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Tas Zeraķijas, tas Uzus, tas Bukus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Tas Abizuūs, tas Pinehas, tas Eleazara, tas augstā priestera Ārona dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Šis Ezra cēlās no Bābeles, un viņš bija rakstu mācītājs, tikuši(prasmīgi) mācīts Mozus bauslībā, ko Tas Kungs, Israēla Dievs, bija devis. Un ķēniņš viņam deva visu, ko viņš lūdza, tāpēc ka Tā Kunga, viņa Dieva, roka bija pār viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Arī citi no Israēla bērniem un no priesteriem un levitiem un dziedātājiem un vārtu sargiem un Dieva nama kalpotājiem cēlās uz Jeruzālemi ķēniņa Artakserksus septītā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Un piektā mēnesī viņš nonāca Jeruzālemē; šis bija ķēniņa septītais gads.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Jo pirmā mēneša pirmā dienā viņš sāka iet no Bābeles, un piektā mēneša pirmā dienā viņš nonāca Jeruzālemē, tāpēc ka viņa Dieva labā roka bija pār viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Jo Ezra savā sirdī bija apņēmies, Tā Kunga bauslību meklēt un darīt un mācīt Israēlim likumus un tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Un šis ir tās grāmatas raksts, ko ķēniņš Artakserksus deva priesterim un rakstu mācītājam Ezram; tas bija mācītājs, mācīts Tā Kunga baušļu vārdos un viņa likumos priekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artakserksus, tas ķēniņu ķēniņš, priesterim un rakstu mācītājam Ezram, mācītam debesu Dieva bauslībā, un tā projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'No manas puses ir pavēlēts, ka ikkatrs no Israēla ļaudīm un priesteriem un levitiem manā valstī, kam prāts nesās, iet uz Jeruzālemi, tas lai iet ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Tāpēc ka tu no ķēniņa un viņa septiņiem padoma devējiem esi sūtīts, izvaicāt par Jūdu un Jeruzālemi pēc tava Dieva bauslības, kas ir tavā rokā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Un uz turieni novest to sudrabu un zeltu, ko ķēniņš un viņa padoma devēji ar labu prātu devuši Israēla Dievam, kam mājas vieta ir Jeruzālemē, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Līdz ar visu to sudrabu un zeltu, ko tu pa visu Bābeles valsti vari atrast, ar tām labprātīgām dāvanām, ko tie ļaudis un priesteri ar labu prātu dod priekš sava Dieva nama Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Un tev par to naudu būs tikuši(rūpīgi) pirkt vēršus, aunus, jērus un viņu ēdamos upurus un viņu dzeramos upurus un tos upurēt uz jūsu Dieva nama altāra, kas Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Un kā tev un taviem brāļiem prāts nesās darīt ar to citu sudrabu un zeltu, tā jūs varat darīt pēc sava Dieva prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Un tos traukus, kas jums atdoti jūsu Dieva namam priekš kalpošanas, tos nododiet Dieva priekšā Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Un ko tev vēl vajadzēs priekš tava Dieva nama, kas tev būs jāizdod, to lai dod no ķēniņa mantu nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Un no manis, ķēniņa Artakserksus, top pavēlēts visiem mantu sargiem, kas viņpus upes, ka jūs visu, ko Ezra, tas priesteris un rakstu mācītājs, mācīts tā debesu Dieva bauslībā, no jums prasīs, to darāt drīz,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Līdz simts talentiem sudraba un līdz simts koriem kviešu un līdz simts batiem vīna līdz simts batiem eļļas un sāls bez mēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Viss, kas no tā debesu Dieva ir pavēlēts, tas lai tikuši(rūpīgi) top darīts pie tā debesu Dieva nama, lai dusmība nenāk pār valsti, ķēniņu un viņa bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Un mēs jums dodam ziņu, ka visiem priesteriem un levitiem, dziedātājiem, vārtu sargiem, Dieva nama kalpotājiem un šī Dieva nama kalpiem nebūs uzlikt nekādus meslus, tiesu nedz muitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Bet tu, Ezra, pēc sava Dieva gudrības, kas tev dota, iecel valdniekus un tiesnešus, tiesāt visus ļaudis viņpus upes, visus, kas jūsu Dieva bauslību zin, un kas to nezin, tiem to mācat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Un par ikvienu, kas jūsu Dieva bauslību un ķēniņa bauslību nedarīs, par to lai tikuši(rūpīgi un stingri) spriež tiesu, vai uz nāvi, vai uz aizdzīšanu, vai uz sodu pie mantas, vai uz cietumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Slavēts lai ir Tas Kungs, mūsu tēvu Dievs, kas to tā ir devis ķēniņa sirdī, izgreznot Tā Kunga namu Jeruzālemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'Un man žēlastību devis pie ķēniņa un viņa padoma devējiem un visiem ķēniņa vareniem lielkungiem. Tā es stiprinājos, tāpēc ka Tā Kunga, mana Dieva, roka bija pār mani, un sapulcēju Israēla virsniekus, man iet līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Šie nu ir viņu cilts virsnieki ar savu radu rakstu, kas ar mani (no Bābeles) aizgāja, kad Bābeles ķēniņš Artakserksus valdīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'No Pinehas bērniem: Geršons; no Ītamara bērniem: Daniēls; no Dāvida bērniem: Hatus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'No Šekanijas bērniem, (no Pareus bērniem): Zaharija, un ar viņu simts un piecdesmit no vīriešu kārtas skaitīti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'No PaātMoaba bērniem: Elioēnajus, Serajas dēls, un ar viņu divsimt no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'No Šekanijas bērniem: Jeaziēļa dēls, un ar viņu trīssimt no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Un no Adina bērniem: Ebeds, Jonatāna dēls, un ar viņu piecdesmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Un no Elama bērniem: Ješaja, Atalijas dēls, un ar viņu septiņdesmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Un no Šefatijas bērniem: Zebadija, Mikaēļa dēls, un ar viņu astoņdesmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'No Joaba bērniem: Obadija, Jeīeļa dēls, un ar viņu divsimt un astoņpadsmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Un no Šelomita bērniem: Josivijas dēls, un ar viņu simts un sešdesmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Un no Bebajus bērniem: Zaharija, Bebajus dēls, un ar viņu divdesmit un astoņi no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Un no Azgada bērniem: Johanans, Katana dēls, un ar viņu simts un desmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Un no Adonikama pēdējiem bērniem, kam šie vārdi: Elivelets, Jeīels un Šemaja, un ar tiem sešdesmit no vīriešu kārtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Un no Biģevajus bērniem: Utajus un Zabuds, un ar tiem septiņdesmit no vīriešu kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Un es tos sapulcēju pie tās upes, kas tek uz Aķevu, un mēs tur apmetāmies trīs dienas. Tad es lūkoju uz tiem ļaudīm un priesteriem un neatradu neviena no Levja bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Tad es sūtīju tos virsniekus, Eliēzeru un Ariēlu un Šemaju un Elnatanu un Jaribu un Elnatanu un Nātanu un Zahariju un Mešulamu, un tos mācītājus Jojaribu un Elnatanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Un sūtīju tos ar pavēli pie virsnieka Idus uz Kasifju. Un es liku tos vārdus viņu mute, ko tiem bija runāt uz Idu un viņa brāļiem, Dieva nama kalpotājiem Kazpijā, mums atvest kalpus priekš mūsu Dieva nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Un tā, kā mūsu Dieva labā roka bija pār mums, tie mums atveda IžZekelu no Maēlas, Levja dēla, Israēla dēla, bērniem, un Šerebiju ar viņa dēliem un viņa brāļiem, astoņpadsmit,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Un Hašabiju un arī Jezaju no Merarus bērniem, ar viņa brāļiem un ar viņa dēliem, divdesmit,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Un no tiem Dieva nama kalpotājiem, ko Dāvids un tie lielkungi bija pielikuši kalpot levitiem, divsimt un divdesmit, kas visi ar vārdu tika nosaukti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Tad es tur izsaucu gavēni pie Aķevas upes, ka mums bija pazemoties priekš sava Dieva vaiga un no viņa meklēt labu ceļu sev un saviem bērniem un visām savām mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Jo man bija kauns, no ķēniņa lūgties karaspēku un jātniekus, kas mums palīdzētu ceļā pret ienaidniekiem. Jo mēs uz ķēniņu bijām runājuši sacīdami: mūsu Dieva roka ir pār visiem, kas viņu meklē, tiem par labu, bet viņa spēks un bardzība pret visiem, kas no viņa atkāpjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Tā mēs gavējām un lūdzām savu Dievu, un viņš mūs paklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Un es atšķīru divpadsmit no priestera virsniekiem, Šerebiju, Hašabiju, un desmit no viņu brāļiem līdz ar viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Un es tiem iesvēru to sudrabu un zeltu un tos traukus par cilājamo upuri mūsu Dieva namam, ko ķēniņš un viņa padoma devēji un viņa lielkungi un viss Israēls, cik atradās, bija dāvinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Es tad viņiem rokā iesvēru sešsimt piecdesmit talentus sudraba un simts talentus sudraba trauku un simts talentus zelta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Un divdesmit zelta biķerus, tūkstoš drakmu vērtībā, un divus vara traukus no spoža laba vara, skaistus kā no zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Un es uz tiem sacīju: jūs esat svēti Tam Kungam, un tie trauki ir svēti līdz ar to sudrabu un zeltu, kas ir labprātības dāvana Tam Kungam, jūsu tēvu Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Esiet modrīgi un glabājiet to, kamēr jūs to iesverat priesteru un levitu virsniekiem un Israēla cilts virsniekiem Jeruzālemē Dieva nama kambaros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Tad tie priesteri un leviti ņēma to iesvērto zeltu un sudrabu un tos traukus, tos nest uz Jeruzālemi uz mūsu Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Un mēs aizgājām no Aķevas upes pirmā mēneša divpadsmitā dienā, iedami uz Jeruzālemi, un mūsu Dieva roka bija pār mums un mūs izglāba no ienaidnieku rokas, un no tiem, kas ceļā uz mums glūnēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Un mēs nonācām Jeruzālemē un palikām tur trīs dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Un ceturtā dienā mēs iesvērām to sudrabu un zeltu un tos traukus mūsu Dieva namā Ūrijas dēlam, priesterim Meremotam rokā, un līdz ar viņu Eleazaram, Pinehas dēlam, un līdz ar viņiem Jozabadam, Ješuūs dēlam, un Noadijam, Benujus dēlam, levitiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Pēc skaita un svara no visa, un viss tas svars tai laikā tapa uzrakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Un to aizvesto bērni, kas no cietuma bija pārnākuši, upurēja dedzināmos upurus Israēla Dievam, divpadsmit vēršus priekš visa Israēla, deviņdesmit sešus aunus, septiņdesmit septiņas avis, divpadsmit āžus par grēku upuri, visu par dedzināmo upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Un tie atdeva ķēniņa pavēles ķēniņa zemes valdītājiem un zemes soģiem viņpus upes. Un šie aizstāvēja tos ļaudis un Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Kad tas nu bija pabeigts, tad tie virsnieki nāca pie manis un sacīja: Israēla ļaudis un priesteri un leviti nav atšķīrušies no tās zemes ļaudīm pēc viņu negantībām, no Kanaāniešiem, Hetiešiem, Fereziešiem, Jebusiešiem, Amoniešiem, Moabiešiem, ēģiptiešiem un Amoriešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Jo no viņu meitām tie ņēmuši priekš sevis un priekš saviem dēliem, un ir sajaukuši to svēto dzimumu ar tās zemes ļaudīm, un virsnieku un valdnieku roka ir tā pirmā bijusi šinī pārkāpšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Kad nu šo lietu dzirdēju, tad es saplēsu savas drēbes un savu mēteli un izplēsu matus no savas galvas un savas bārdas, un apsēdos skumīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Un pie manis sapulcējās visi, kas to aizvesto ļaužu pārkāpšanas dēļ priekš Israēla Dieva vārdiem drebēja, un es sēdēju skumīgs līdz vakara upurim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Un ap vakara upuri es cēlos no savas pašpazemošanās un saplēsu savas drēbes un savu mēteli, un metos ceļos un izplētu savas rokas Tā Kunga, sava Dieva, priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Un es sacīju: mans Dievs, es kaunos un bīstos, savu vaigu pacelt tavā priekšā, mans Dievs, jo mūsu noziegumi vairojušies pār mūsu galvu, un mūsu vaina ir liela līdz debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'No savu tēvu dienām mēs esam lielā noziegumā līdz šai dienai, un savu pārkāpumu dēļ mēs, mūsu ķēniņi, mūsu priesteri, esam nodoti pagānu ķēniņiem rokā, zobenam, cietumam un laupīšanai un vaiga apkaunošanai, tā kā tas vēl šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Un nu mums kādu mazu brīdi žēlastība ir notikusi no Tā Kunga, mūsu Dieva, mums atlicināt kādu atlikumu un mums dot vienu vadzi(telts mietu) viņa svētā vietā, ka mūsu Dievs mūsu acis apskaidrotu un mums dotu drusku atspirgties mūsu verdzībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Jo mēs esam vergi; tomēr mūsu Dievs mūs nav atstājis mūsu verdzībā, bet uz mums griezis Persiešu ķēniņu žēlastību, ka tie mums drusku dotu atspirgties, ka varam uzcelt mūsu Dieva namu un uztaisīt viņa postītas vietas, un ka mums dotu vienu mūri iekš Jūda un Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Un nu, ko lai mēs par to sakām, ak mūsu Dievs! - Jo mēs esam atkāpušies no taviem baušļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Ko tu esi pavēlējis caur saviem kalpiem, tiem praviešiem, sacīdams: tā zeme, kurp jūs ejat to iemantot, ir nešķīsta zeme caur zemes ļaužu nešķīstību, caur viņu negantību, ar ko tie to piepildījuši no viena gala līdz otram caur savu nešķīstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Tad nu jums nebūs dot savas meitas viņu dēliem, nedz ņemt viņu meitas saviem dēliem, nedz mūžam meklēt viņu mieru, vai labumu, lai jūs topat stipri un varat ēst tās zemes labumu un saviem bērniem atstāt par mantību mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Un pēc visa tā, kas mums uznācis mūsu ļauno darbu un mūsu lielās vainas dēļ, tu, mūsu Dievs, mūs esi vairāk saudzējis, nekā mūsu noziegumi (pelnījuši) un mums esi atlicinājis vienu atlikumu, kāds šis ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Vai tad mums nu atkal bija jānogriežas, lauzt tavus baušļus un iedoties rados ar šādas negantības ļaudīm? Vai tu pret mums neapskaitīsies līdz kamēr izdeldēsi, ka nebūs nedz atlikuma nedz izglābta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Ak Kungs, Israēla Dievs, tu esi taisns, jo mēs esam atlikuši viens izglābts pulciņš, tā kā tas šodien ir; redzi, mēs esam priekš tava vaiga savā noziegumā, jo tāpēc neviens nevar tavā priekšā pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Kad nu Ezra tā lūdza un tā sūdzēja raudādams un nomezdamies Dieva nama priekšā, tad no Israēla pie viņa sapulcējās ļoti liela draudze vīru un sievu un bērnu; jo tie ļaudis raudāja lielā raudāšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Tad Šehanija, Jeīeļa dēls no Elama bērniem, atbildēja un sacīja uz Ezru: mēs esam grēkojuši pret savu Dievu, ka esam apņēmuši svešas sievas no tās zemes ļaudīm, bet taču vēl būs cerības priekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Derēsim tad nu derību ar savu Dievu, ka izdzenam visas sievas, un kas no tām ir dzimuši, pēc Tā Kunga padoma un pēc to ļaužu padoma, kas mūsu Dieva baušļus bīstas, un lai tad darām pēc bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Celies, jo šī lieta tev piekrīt, un mēs būsim ar tevi; esi stiprs un izdari (to).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Tad Ezra cēlās un lika priesteru un levitu un visa Israēla virsniekiem zvērēt, darīt pēc šī vārda. Un tie zvērēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Un Ezra cēlās Dieva nama priekšā un iegāja Jehohanana, Elijadziba dēla, kambarī, un tur nācis viņš neēda maizes un nedzēra ūdens, jo viņš nobēdājās to aizvesto ļaužu pārkāpšanas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Un tie lika izsaukt pa Jūdu un Jeruzālemi pie visiem no cietuma pārnākušiem, sapulcēties Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Un kas triju dienu starpā nenāktu pēc virsnieku un vecaju nosacīšanas, tā manta tapšot izdeldēta un pats izstumts no pārnākušo draudzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Tad visi Jūda un Benjamina vīri triju dienu starpā sapulcējās Jeruzālemē, - tā bija tā divdesmitā diena devītā mēnesī, - un visi ļaudis sēdēja uz ielas priekš Dieva nama trīcēdami šās lietas dēļ un no stipra lietus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Tad priesteris Ezra cēlās un uz tiem sacīja: jūs esat apgrēkojušies, svešas sievas apņemdami, ka jūs vairotu Israēla noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Tad nu izsūdziet to Tam Kungam, savu tēvu Dievam, un dariet pēc viņa prāta, un šķiraties no tās zemes ļaudīm un no tām svešām sievām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Tad visa draudze atbildēja un sacīja ar stipru balsi: pēc taviem vārdiem mums tā jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Bet to ļaužu ir daudz un ir lietus laiks, ka nevar ārā stāvēt; tas arī nav vienas jeb divēju dienu darbs, jo mēs šinī lietā esam pārlieku grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Lai mēs savus virsniekus ieceļam pār visu draudzi, ka visi, kas ir mūsu pilsētās, kas svešas sievas apņēmuši, lai nāk nospriestos laikos un ar tiem ikkatras pilsētas vecaji un viņas soģi, kamēr mēs no sevis novēršam sava Dieva bardzību šīs lietas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Tad Jonatāns, Azaēļa dēls, un Jeazija, Tikvus dēls, tam cēlās pretī, un leviti, Mešulams un Šabetajus, tiem palīdzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Bet tie pārnākušie tā darīja: Tie izraudzīja priesteri Ezru un vīrus, proti savu tēvu namu virsniekus pēc saviem tēvu namiem, visus ar vārdu noteiktus. Un tie turēja sapulci desmitā mēneša pirmā dienā, šo lietu izmeklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Un tie to izdarīja pie visiem vīriem, kas svešas sievas bija apņēmuši, līdz pirmā mēneša pirmajai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Un no priesteru dēliem tapa atrasti, kas svešas sievas bija apņēmuši, no Ješuūs, Jocadaka dēla, dēliem un viņa brāļiem: Maāseja, Eliēcers, Jaribs un Ģedalija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Un tie deva savu roku, ka savas sievas izdzīšot, un noziedzīgi būdami tie deva aunu priekš sava nozieguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Un no Imera bērniem: Hananus un Zebadija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Un no Harima bērniem: Maāseja un Elija un Šemaja un Jeīels un Uzija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Un no Pazura bērniem: Elioēnajus, Maāseja, Ismaēls, Netaneēls, Jozabads un Eleaza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Un no levitiem: Jozabads un Šimejus un Ķelaja, (šis ir Kelita), Petahja, Jūda un Eliēcers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Un no dziedātājiem: Elijašibs. Un no vārtu sargiem: Šalums un Telems un Urus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Un no Israēla, no Pareus bērniem: Ramija un Jezija un Malhija un Mejamins un Eleazars un Malhija un Benaja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Un no Elama bērniem: Metanija, Zaharija, Jeīels un Abdus un Jerimots un Elija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Un no Zatus bērniem: Elioēnajus, Elijadzibs, Matanija un Jerimots un Zabats un Aziza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Un no Bebajus bērniem: Jehohanans, Ananija, Zebajus, Atlajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Un no Banus bērniem: Mešulams, Malaks un Adaja, Jazubs un Zeals, Jeramots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Un no PaātMoaba bērniem: Adna un Ķelals, Benaja, Maāseja, Matanija Becaleēls un Benujus un Manasus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Un no Harima bērniem: Eliēsers, Jezija, Malhija Šemaja, Sīmeans,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamins, Maluks un Zemarija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'No Azama bērniem: Matnajus, Matata, Zabads, Elivalets, Jeremajus, Manasus, Šimejus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'No Banus bērniem: Maēdajus, Amrams un Uēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedija, Ķelujus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Un Naja, Meremots, Elijašibs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mantanija, Matnaja un Jaēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Un Banus un Benujus un Šimejus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Un Šelemija un Nātans un Adaja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbajus, Zazajus, Zarajus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareēls un Šelemija, Samarija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Šalums, Amarija, Jāzeps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'No Nebus bērniem: Jeīels, Matitija, Zabads, Zebina, Jadajus un Joēls, Benaja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Visi šie bija svešas sievas apņēmuši, un no tām sievām kādas bija bērnus dzemdējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Šie ir Nehemijas, Hakalijas dēla, stāsti. Un notikās Kisleva mēnesī, divdesmitā gadā, kad es biju Sūsanas pilī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Tad nāca Hanans, viens no maniem brāļiem, līdz ar citiem Jūda vīriem. Un es tos vaicāju par tiem atlaistiem Jūdiem, kas bija atlikuši no cietuma, un par Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Un tie uz mani sacīja: tie atlikušie, kas no cietuma tur tai valstī ir atlikuši, tie ir lielā nelaimē un kaunā, un Jeruzālemes mūris ir nolauzīts un viņas vārti ar uguni sadedzināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Un kad es šos vārdus dzirdēju, tad es apsēdos un raudāju un biju noskumis kādas dienas un gavēju un lūdzu priekš debesu Dieva vaiga');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Un sacīju: Ak Kungs, Tu debesu Dievs, Tu lielais un bijājamais Dievs, kas derību un žēlastību turi tiem, kas Tevi mīļo un Tavus baušļus sargā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Lai Tavas ausis jel uzklausa un Tavas acis ir atvērtas, klausīt Tava kalpa lūgšanu, ko es tagad lūdzu Tavā priekšā dienās un naktīs, par Israēla bērniem, Taviem kalpiem, un izsūdzu Israēla bērnu grēkus, ko tie pret Tevi grēkojuši; arī es, un mana tēva nams esam grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Mēs Tavā priekšā ļoti esam samaitājušies un neesam turējuši tos baušļus nedz tos likumus nedz tās tiesas, ko Tu Savam kalpam Mozum esi pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Piemini jel to vārdu, ko Tu Savam kalpam Mozum esi pavēlējis sacīdams: ja jūs apgrēkosities, tad Es jūs izklīdināšu pa tām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Ja tad jūs atgriezīsieties pie Manis un turēsiet Manus baušļus un tos darīsiet, jebšu tad jūsu aizdzītie būtu debess galā, tomēr Es tos no turienes salasīšu un atvedīšu uz to vietu, ko esmu izredzējis, lai Mans vārds tur mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Tie jau ir Tavi kalpi un Tavi ļaudis, ko Tu esi izpestījis ar Savu lielo spēku un ar Savu stipro roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ak Kungs, lai jel Tavas ausis uzklausa uz Tava kalpa lūgšanu un uz Tavu kalpu lūgšanu, kam gribās Tavu vārdu bīties, un lai jel šodien Tavam kalpam labi izdodas, un dod viņam apžēlošanu šā vīra(ķēniņa) priekšā. Bet es biju ķēniņa dzēriena devējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Un notika Nīsana mēnesī, ķēniņa Artakserksus divdesmitā gadā, kad vīns bija viņa priekšā, tad es pacēlu to vīnu un devu ķēniņam; un es (citkārt) nebiju noskumis bijis viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Un ķēniņš uz mani sacīja: kādēļ tavs vaigs izskatās noskumis? Vai tu esi slims? Tā gan nav, bet tava sirds ir noskumusi. Tad es bijos ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Un es sacīju uz ķēniņu: lai ķēniņš dzīvo mūžīgi! Kā lai mans vaigs nav noskumis? Jo tā pilsēta, kur manu tēvu kapi, ir postā, un viņas vārti no uguns aprīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Un ķēniņš uz mani sacīja: ko tad tu nu gribi? Tad es pielūdzu to debesu Dievu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Un sacīju uz ķēniņu: ja tas ķēniņam patīk un ja tavs kalps ir patīkams tavā priekšā, tad sūti mani uz Jūdu, uz to pilsētu, kur manu tēvu kapi, ka es to uzceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Tad ķēniņš uz mani sacīja, ķēniņienei viņam blakām sēžot: cik ilgi tad tu paliksi ceļā un kad tu nāksi atpakaļ? Un ķēniņam patika, mani sūtīt, kad es viņam laiku biju nolicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Un es sacīju uz ķēniņu: Ja tas ķēniņam patīk, tad lai man grāmatas dod pie zemes valdītājiem viņpus upes, lai tie mani pārvada, tiekams nākšu uz Jūdu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Un arī grāmatu pie Asafa, ķēniņa mežu uzrauga, lai tas man dod baļķus priekš Dieva nama pils vārtu nostiprināšanas un priekš pilsētas mūra un priekš tā nama, kur es ieiešu. Un ķēniņš man deva, tāpēc ka Dieva labā roka bija pār mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Tad es nācu pie tiem zemes valdītājiem viņpus upes un tiem devu ķēniņa grāmatas. Un ķēniņš man bija sūtījis līdz virsniekus un jātniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Kad nu Sanebalats, tas Horonietis, un Tobija, tas kalps, tas Amonietis, to dzirdēja, tad tas viņiem nepavisam nepatika, ka viens cilvēks bija nācis, ko laba meklēt priekš Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Un es nācu uz Jeruzālemi un tur biju trīs dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Tad es cēlos naktī, es un kādi vīri līdz ar mani, un nestāstīju nevienam, ko Dievs manā sirdī bija devis pie Jeruzālemes darīt, un nekāda lopa man nebija līdz, bez tā, uz kā es jāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Un es izjāju naktī caur Ielejas vārtiem pret Pūķa aku līdz Mēslu vārtiem, un es aplūkoju Jeruzālemes mūrus, kas bija nolauzīti un viņas vārtus, kas no uguns bija aprīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Un es aizjāju uz Akas vārtiem un Ķēniņa dīķi, un tas lops, uz kā es jāju, tur nevarēja tikt cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Tad es devos naktī augšām gar upi un aplūkoju to mūri un griezos atpakaļ un iejāju caur Ielejas vārtiem; tā es griezos atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Bet tie valdnieki nezināja, kurp es biju gājis un ko es darīju; jo līdz šim es vēl neko nebiju zināmu darījis ne Jūdiem, ne priesteriem, ne tiem cienīgiem, ne tiem priekšniekiem, ne tiem citiem, kas to darbu darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Tad es uz tiem sacīju: jūs redzat to nelaimi, kurā mēs esam, ka Jeruzāleme ir postā un viņas vārti ar uguni sadedzināti, - nāciet, uzcelsim Jeruzālemes mūrus, ka vairs neesam par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Un es tiem stāstīju sava Dieva roku, kas bija laba bijusi pār mani, un arī ķēniņa vārdus, ko viņš uz mani bija sacījis. Tad tie sacīja: celsimies un būvēsim. Un tie stiprināja savas rokas uz labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Kad nu Sanebalats, tas Horonietis un Tobija, tas kalps, tas Amonietis, un Gešems, tas Arābs, to dzirdēja, tad tie mūs apsmēja un mūs nicināja un sacīja: kas tas tāds darbs, ko jūs darāt? Vai jūs gribat dumpi celt pret ķēniņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Tad es tiem atbildēju un uz tiem sacīju: Dievs debesīs mums dos, ka tas mums labi izdosies, un mēs, viņa kalpi, celsimies un (to) uztaisīsim; bet jums nav nekādas daļas, nedz tiesas, nedz piemiņas Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Un augstais priesteris Elijašibs cēlās ar saviem brāļiem, tiem priesteriem, un uztaisīja Avju vārtus; tie tos iesvētīja un iecēla viņu durvis; tos tie iesvētīja līdz Meas(Simtnieku) tornim, līdz Hananeēļa tornim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Un viņiem sānis strādāja Jērikus vīri, un viņiem sānis strādāja Zakurs, Imra dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Un Zivju vārtus taisīja Senaās bērni; tie tos salaida un iecēla viņu durvis, viņu atslēgas un aizšaujamos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Un viņiem sānis strādāja Meremots, Ūrijas dēls, Akoca dēla dēls. Un viņiem sānis strādāja Mešulams, Bereķijas dēls, Mešezabeēļa dēla dēls. Un viņiem sānis strādāja Cadoks, Baēnas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Un viņiem sānis strādāja Tekoieši, bet viņu cienīgie nepadeva savu kaklu, kalpot savam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Un Vecpilsētas vārtus taisīja Jojadus, Paseas dēls, un Mešulams, Besodijas dēls, tie tos salaida un iecēla viņu durvīs ar viņu atslēgām un viņu aizšaujamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Un viņiem sānis strādāja Gibeonietis Melatija un Meronietis Jadons, Gibeona un Micpas vīri (kas pieder) pie zemes valdnieka tiesas viņpus upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Viņiem sānis strādāja Uziēls, Harhajas dēls, no tiem sudraba kalējiem. Viņiem sānis strādāja Hananija, zāļu pārdevēja dēls, un Jeruzālemi atkal uztaisīja līdz tam Platajam mūrim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Viņiem sānis strādāja Revaja, Ura dēls, Jeruzālemes pusapriņķa virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Un viņiem sānis strādāja Jedaja, Arumava dēls, savam namam iepretim. Un viņam sānis strādāja Hatus, Azabenijas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Otru gabalu uztaisīja Malhija, Harima dēls, un Hašubs, PaātMoaba dēls, un arī to cepļa torni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Un viņiem sānis strādāja Šalums, Āloēs dēls, Jeruzālemes pusapriņķa virsnieks, viņš un viņa meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Ielejas vārtus taisīja Hanuns un Zanoas iedzīvotāji; tie tos taisīja un iecēla viņu durvis, viņu atslēgas un viņu aizšaujamos, arī tūkstoš olektis mūra līdz Mēslu vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Un Mēslu vārtus taisīja Malhija, Rekaba dēls, vīna dārzu apgabala virsnieks; viņš tos uztaisīja, un iecēla viņu durvis, viņu atslēgas un viņu aizšaujamos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Un Akas vārtus taisīja Šalums, KalKosus dēls, Micpas apriņķa virsnieks; viņš tos uztaisīja un tos apsedza un iecēla viņu durvis, viņu atslēgas un viņu aizšaujamos, tā arī to mūri pie Šelahas dīķa, pie ķēniņa dārza, līdz tām pakāpēm, kas nonāk no Dāvida pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Aiz viņa taisīja Nehemija, Azbuka dēls, Betzura pusapriņķa virsnieks, līdz pret Dāvida kapam un līdz Azujas dīķim un līdz varoņu namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Aiz viņa taisīja leviti, Rehums, Banus dēls. Viņam sānis strādāja Hašabija, Ķeģilas pusapriņķa virsnieks par savu apgabalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Aiz viņa strādāja viņu brāļi, Bavajus, EnHadada dēls, Ķeģilas pusapriņķa virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Viņam sānis strādāja Ezers, Ješuūs dēls, Micpas virsnieks, otru gabalu, turpat pretī, kur uzkāpj pie bruņu nama pašā stūrī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Aiz viņa strādāja uzcītīgi Bāruks, Zebajus dēls, otru gabalu, no tā stūra līdz Elijašiba, augstā priestera, nama durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Aiz viņa strādāja Merimots, Ūrijas dēls, Akoca dēla dēls, otru gabalu, no Elijašiba nama durvīm līdz Elijašiba nama galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Un aiz viņa strādāja priesteri, tie vīri no (Jardānes) ielejas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Aiz tiem strādāja Benjamins un Hašubs savam namam iepretim. Aiz tiem strādāja Azarija, Maāsejas dēls, Ananijas dēla dēls, pie sava nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Aiz viņa strādāja Binuūs, EnHadada dēls, otru gabalu, no Azarijas nama līdz kaktam un līdz stūrim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palals, Uzijus dēls, stūrim iepretim un tam augstam tornim iepretim, kas no augšēja ķēniņa nama izceļas un stāv pie cietuma pagalma. Aiz viņa Pedaja, Pareūs dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Bet Dieva nama kalpotāji dzīvoja Ofelā līdz Ūdens vārtiem pret rīta pusi un pret to torni, kas tur izceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Aiz tiem strādāja Tekoieši otru gabalu, tam lielam tornim iepretim, kas tur izceļas, un līdz Ofela mūrim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Augšpus Zirgu vārtiem strādāja priesteri, ikviens savam namam iepretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Aiz tiem strādāja Cadoks, Imera dēls, savam namam iepretim. Un aiz viņa Šemaja, Šehanijas dēls, Rīta vārtu sargs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Aiz viņa strādāja Hananija, Šelemijas dēls, un Hanuns, Calafa sestais dēls, otru gabalu. Aiz viņiem strādāja Mešulams, Bereķijas, dēls, savam kambarim iepretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Aiz viņa strādāja Malkija, sudraba kalēja dēls, līdz Dievu nama kalpotāju un zāļu pārdevēju namam, Tiesas vārtiem iepretim, līdz stūra uzkāpēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Un starp stūra uzkāpēm un Avju vārtiem strādāja sudraba kalēji un zāļu pārdevēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Kad nu Sanbalats dzirdēja, ka mēs to mūri uzceļam, tad viņš apskaitās un palika varen dusmīgs un apsmēja Jūdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Un tas sacīja savu brāļu un Samarijas karaspēka priekšā: ko tie nespēcīgie Jūdi dara? Vai tiem būs dot tādu vaļu? Vai tie upurēs? Vai viņi vienā dienā to pabeigs? Vai viņi tos sadedzinātos akmeņus no pelnu čupām darīs dzīvus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Un Tobija, tas Amonietis, stāvēja viņam blakām un sacīja: lai tik taisa! Kad tur lapsa uzlēks, tad tā viņu akmeņu mūri nogāzīs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Klausi, ak mūsu Dievs, kā mēs esam nievāti, un atgriez viņu nievāšanu uz viņu galvu un nodod tos par apsmieklu cietuma zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Un neapklāj viņu noziegumu, un viņu grēki lai netop izdzēsti Tavā priekšā, jo tie (Tevi) kaitinājuši to strādnieku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Bet mēs cēlām to mūri un tas mūris tapa uzcelts līdz pusei, tad tie ļaudis jo priecīgi sāka strādāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Kad nu Sanbalats un Tobija un tie Arābi un Amonieši un Ašdodieši dzirdēja, ka Jeruzālemes mūri gana augsti bija celti, ka tās starpas jau taisījās cieti, tad tie ļoti apskaitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Un tie sametās visi uz vienu roku, nākt un karot pret Jeruzālemi un viņu postīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Bet mēs pielūdzām savu Dievu un likām vakti viņu dēļ dienām naktīm viņiem pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Tad Jūda sacīja: nesēju spēks ir noguris un daudz ir gruvešu, tā ka mēs pie mūra nevaram strādāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Bet mūsu ienaidnieki sacīja: tiem nemanot un neredzot mēs nāksim viņu vidū un tos nokausim un tam darbam darīsim galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Un notikās, kad tie Jūdi, kas viņiem sānis dzīvoja, nāca un mums gan desmit reiz sacīja no visām vietām: griežaties atpakaļ pie mums!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Tad es tais lejas vietās aiz tā mūra un uz tiem kalniem nostādīju tos ļaudis pēc viņu radiem ar viņu zobeniem, viņu šķēpiem un viņu stopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Un es lūkoju un cēlos un sacīju uz tiem virsniekiem un priekšniekiem un tiem citiem ļaudīm: nebīstaties no viņiem; pieminiet to lielo bijājamo Kungu un karojiet par saviem brāļiem, saviem dēliem un savām meitām, savām sievām un saviem namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Un notikās, kad mūsu ienaidnieki bija dzirdējuši, ka tas mums tapis zināms, un ka Dievs viņu padomu bija iznīcinājis, tad mēs visi griezāmies atpakaļ pie mūra, ikkatrs pie sava darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Un no tās dienas manu jaunekļu viena daļa darīja to darbu, un otra daļa turēja šķēpus un priekšturamās bruņas un stopus un krūšu bruņas, un tie virsnieki stāvēja aiz visa Jūda nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Kas mūri cēla un kas nastu nesa un kas uzkrāva, tie visi ar vienu roku darīja darbu un ar otru tie turēja kara ieročus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Un tie strādnieki bija jozuši ikviens savu zobenu ap saviem gurniem un tā tie strādāja, bet kas bazūni pūta, tas bija man blakām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Un es sacīju uz tiem virsniekiem un uz tiem valdniekiem un uz tiem citiem ļaudīm: tas darbs ir liels un garš, un mēs esam atšķirti tālu cits no cita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Tai vietā, kur jūs dzirdēsiet bazūnes skaņu, tur jums pie mums būs sapulcēties; mūsu Dievs priekš mums karos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Tā mēs darījām to darbu. Un viena puse no tiem turēja šķēpus no rīta gaismas, līdz kamēr zvaigznes sāka spīdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Tanī laikā es arī sacīju uz tiem ļaudīm: lai ikviens ar savu puisi pa nakti paliek Jeruzālemē, ka tie mums naktī ir par sargiem un dienā palīdz pie darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Un ne es, ne mani brāļi, ne mani jaunekļi, ne tie sargi, kas aiz manis stāvēja, mēs nenovilkām savas drēbes un ikkatram bija savas bruņas pie rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Un tie ļaudis un viņu sievas daudz brēca pret saviem brāļiem, tiem Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Jo tur bija, kas sacīja: mēs ar saviem dēliem un ar savām meitām esam daudzi, mums vajag labības ko ēst, lai dzīvojam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Tur arī bija, kas sacīja: izdosim ķīlām savus tīrumus un savus vīna dārzus un savus namus, ka varam labības dabūt pret badu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Vēl bija, kas sacīja: mēs naudu esam aizņēmuši uz saviem tīrumiem un saviem vīna dārziem priekš ķēniņa mesliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Un tomēr mūsu miesa ir kā mūsu brāļu miesa, mūsu bērni kā viņu bērni, un redzi, mums jādod savi dēli un savas meitas jūgā par kalpiem. Un no mūsu meitām jau kādas ir jūgā padotas un padoma mūsu rokā nav, arī mūsu tīrumi un mūsu vīna dārzi pieder citiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Tad es ļoti apskaitos, kad dzirdēju viņu brēkšanu un šos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Un es to pārdomāju savā sirdī un bāros ar tiem virsniekiem un valdniekiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Un uz tiem sacīju: jūs plēšat augļus viens no otra? Un es pret tiem savedu lielu draudzi un uz tiem sacīju: mēs savus brāļus, tos Jūdus, kas pagāniem bija pārdoti, cik spēdami esam atpirkuši, un jūs savus brāļus gribat pārdot un lai mēs tos pērkam? Tad tie cieta klusu un nemācēja ne vārda atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Tad es sacīju: nav labi, ko jūs darāt! Vai jums nebija staigāt mūsu dievbijāšanā, to pagānu, mūsu ienaidnieku nievāšanas dēļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Arī es un mani brāļi un mani jaunekļi tiem esam devuši naudu un labību. Lai jel šo parādu tiem atlaižam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Atdodiet jel tiem šodien viņu tīrumus, viņu vīna dārzus, viņu eļļas dārzus un viņu namus un to simto tiesu naudas un labības un vīna un eļļu, ko jūs no tiem (augļos) esat ņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Tad tie sacīja: mēs atdosim un nemeklēsim no tiem nekā; mēs darīsim, kā tu saki. Un es aicināju priesterus un tiem liku zvērēt, ka tā darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Es arī izkratīju savu azoti un sacīju: lai Dievs ikkatru, kas šo vārdu neturēs, tā izkrata no viņa nama un no viņa mantas, un lai tas tā ir izkratīts un iztukšots. Un visa draudze sacīja: Āmen! Un slavēja To Kungu. Un tie ļaudis darīja pēc šī vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'No tām dienām, kad man tapa pavēlēts, būt par zemes valdītāju Jūdu zemē, no ķēniņa Artakserksus divdesmitā gada līdz trīsdesmit otram gadam, caurus divpadsmit gadus, arī neesmu ēdis zemes valdītāja maizi, ne es, ne mani brāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Jo tie pirmie zemes valdītāji, kas priekš manis bijuši, tie tiem ļaudīm bija grūti darījuši un no tiem ņēmuši maizi un vīnu un vēl četrdesmit sudraba sēķeļus; pat viņu jaunekļi valdīja pār tiem ļaudīm, bet es tā neesmu darījis, Dievu bīdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Es arī pats esmu strādājis pie tā mūra, un tīrumu mēs neesam pirkuši, un visi mani puiši tur kopā bija pie darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Un Jūdi un valdnieki, simts piecdesmit vīri, un kas no tiem apkārtējiem pagāniem pie mums nāca, ir bijuši pie mana galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Un ikkatrā dienā tapa sataisīts viens vērsis, sešas barotas avis un putni man kļuva sataisīti, arī daudz vīna priekš ik desmit dienām; tomēr es zemes valdītāja maizi nemeklēju, jo tā kalpošana šiem ļaudīm bija grūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Piemini, Dievs, man par labu visu, ko es šiem ļaudīm esmu darījis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Un notikās, kad Sanbalats un Tobija un Arābs Gešems un mūsu citi ienaidnieki dzirdēja, ka mēs to mūri bijām uzcēluši un iekš tā caurums neatlikās, (jebšu es līdz šim durvis vēl nebiju iecēlis vārtos),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Tad Sanbalats un Gešems pie manis sūtīja un lika sacīt: nāc, saiesim kopā Onus klajuma ciemos. Bet tie domāja, man ļaunu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Un es sūtīju vēstnešus pie tiem un liku sacīt: man liels darbs darāms, ka nevaru nonākt; kāpēc šim darbam būs kavēties, ka es to pamestu un pie jums nonāktu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Un tie gan četras reizes pie manis sūtīja ar šo pašu valodu, un es sūtīju pie tiem atpakaļ ar to pašu valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Tad Sanbalats piektā reizē pie manis sūtīja savu puisi tāpat ar neaiztaisītu grāmatu viņa rokā. Iekš tās bija rakstīts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Ļaudis dzird, un Gešems saka, ka tu ar tiem Jūdiem domā atkāpties un tāpēc to mūri uztaisi, un ka tu viņiem gribi būt par ķēniņu, - tā runā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Ka tu arī praviešus iecēlis, kas lai izsauc par tevi Jeruzālemē un saka: viņš ir ķēniņš iekš Jūda. Un nu ķēniņš tādu valodu dzirdēs; nāc tad jel un lai mēs kopā sarunājamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Bet es sūtīju pie viņa sacīdams: no tā, ko tu runā, nekas nav noticis; no savas sirds tu to esi izdomājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Jo visi tie mūs baidīja un sacīja: viņu rokām būs no tā darba atstāties, ka tas netop darīts. Un nu, stiprini Tu, (ak Dievs), manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Kad es nu nācu Šemajas namā, - tas bija Delajas, Mehetabeēļa dēla, dēls, (bet viņš bija ieslēdzies), tad viņš sacīja: sanāksim Dieva namā, pašā Dieva nama vidū, un lai mēs Dieva nama durvis aizslēdzam, jo tie nāks, tevi nokaut, pašā naktī tie nāks, tevi nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Bet es sacīju: vai tādam vīram, kā es, būs bēgt? Vai tādam, kā es, Dieva namā būs iet, lai paliktu dzīvs? Es neiešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Jo redzi, es manīju, ka Dievs viņu nebija sūtījis. Bet viņš runāja šo sludināšanu uz mani, tāpēc ka Tobija un Sanebalats viņu bija derējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Viņš bija derēts, lai es izbīstos un tā daru un apgrēkojos, ka tie kādu ļaunu slavu atrastu, ar ko mani varētu nievāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Piemini, mans Dievs, Tobiju un Sanbalatu pēc šiem darbiem un arī pravieti Noadiju un tos citus praviešus, kas ir meklējuši, mani darīt bailīgu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Tad nu tas mūris tapa pabeigts Elula mēneša divdesmit piektā dienā, piecdesmit divās dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Un kad visi mūsu ienaidnieki to dzirdēja, tad visi apkārtējie pagāni bijās un viņu drošība zuda, jo tie samanīja, ka šis darbs ar mūsu Dieva palīgu bija padarīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Tanīs dienās arī daudz virsnieki no Jūda rakstīja grāmatas; tās tapa sūtītas pie Tobijas, un Tobija sūtīja atkal pie tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Jo daudzi iekš Jūda viņam bija zvērējuši, tāpēc ka tas bija Šehanijas, Arahus dēla, znots, un viņa dēls Jehohanans bija apņēmis Mešulama, Bereķijas dēla, meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Tie runāja arīdzan labu par viņu manā priekšā, un manus vārdus tie nonesa pie viņa; tad Tobija sūtīja grāmatas, ka tas mani biedinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Kad nu mūris bija uztaisīts, tad es iecēlu durvis, un vārtu sargi un dziedātāji un leviti tapa iecelti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Un es pavēlēju savam brālim Hananum un Hananijam, Jeruzālemes pils virsniekam, (jo tas bija uzticams vīrs un dievbijīgs pār daudziem),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Un uz tiem sacīju: Lai Jeruzālemes vārti netop atdarīti, pirms saule nesilda, un tiem vēl klāt esot durvis lai atkal aizslēdz un aizšauj. Un Jeruzālemes iedzīvotājus ieceļat par sargiem, ikkatru uz savu vakti un ikkatru savam namam pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Bet pilsēta bija plata un liela un ļaužu tur bija maz un nami nebija uzcelti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Tad mans Dievs man iedeva sirdī, sapulcināt virsniekus un priekšniekus un tos ļaudis, lai sarakstītu radu rakstus. Un es atradu vienu radu rakstu grāmatu par tiem, kas pirmie bija pārnākuši, un es atradu, ka tur tā bija rakstīts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Šie ir tie valsts bērni, kas bija pārnākuši no tā cietuma, kur NebukadNecars, Bābeles ķēniņš, tos bija aizvedis, un kas ir griezušies atpakaļ uz Jeruzālemi un uz Jūdu, ikviens savā pilsētā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Kas nākuši ar Zerubabeli, ar Ješuū, Nehemiju, Azariju, Raāmiju, Naēmanu, Mordohaju, Bilšanu, Mizperetu, Biģevaju, Neūmu, Baēnu. Šis ir Israēla vīru skaits.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Pareūs bērni bija divtūkstoš simt septiņdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Zeroatijas bērni: trīssimt septiņdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Arus bērni: sešsimt piecdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'PaātMoaba bērni, no Ješuūs un Joaba bērniem: divtūkstoš astoņsimt astoņpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elama bērni: tūkstoš divsimt piecdesmit četri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Zatus bērni: astoņsimt četrdesmit pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Zakajus bērni: septiņsimt sešdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Banus bērni: sešsimt četrdesmit astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bebajus bērni: sešsimt divdesmit astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Azgada bērni: divtūkstoš trīssimt divdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikama bērni: sešsimt sešdesmit septiņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Biģevajus bērni: divtūkstoš sešdesmit septiņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adina bērni: sešsimt piecdesmit pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Atera bērni no Hizkijas (nama): deviņdesmit astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hašuma bērni: trīssimt divdesmit astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Becajus bērni: trīssimt divdesmit četri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Ariva bērni: simts divpadsmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeona bērni: deviņdesmit pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Bētlemes un Netofas vīri: simts astoņdesmit astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Anatotas vīri: simts divdesmit astoņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'BetAsmavetas vīri: četrdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'KiriatJearimas, Kaviras un Beērotas vīri: septiņsimt četrdesmit trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Rāmas un Gabas vīri: sešsimt divdesmit viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mikmasas vīri: simts divdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Bēteles un Ajas vīri: simts divdesmit trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Otra Nebus vīri: piecdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Otra Elama bērni: tūkstoš divsimt piecdesmit četri;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harima bērni: trīssimt divdesmit;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jērikus bērni: trīssimt četrdesmit pieci;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Lodas, Adidas un Onus bērni: septiņsimt divdesmit viens;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Zenaūs bērni: trīstūkstoš deviņsimt trīsdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Priesteri: Jedajas bērni, no Ješuūs nama: deviņsimt septiņdesmit trīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Imera bērni: tūkstoš piecdesmit divi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pašhura bērni: tūkstoš divsimt četrdesmit septiņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harima bērni: tūkstoš septiņpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Leviti: Ješuūs bērni no Kadmiēļa, no Odavijas bērniem: septiņdesmit četri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Dziedātāji, - Asafa bērni: simts četrdesmit astoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Vārtu sargi: Šaluma bērni, Atera bērni, Talmona bērni, Akuba bērni, Atita bērni, Zobaja bērni: simts trīsdesmit astoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Dieva nama kalpotāji: Cikus bērni, Azuva bērni, Tabaota bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Ķerus bērni, Ziūs bērni, Padona bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebana bērni, Agaba bērni, Zalmajus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Anana bērni, Ģideļa bērni, Gaāra bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reajus bērni, Recina bērni, Nekoda bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gazama bērni, Uzus bērni, Paseūs bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Besajus bērni, Meūnima bērni, Nevusima bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbuka bērni, Akuva bērni, Arura bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Baceluta bērni, Mekida bērni, Arsas bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkus bērni, Sisera bērni, Tamus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Necius bērni, Ativus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Salamana kalpu bērni, Sotajus bērni, Sofereta bērni, Pridus bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaēlus bērni, Darkona bērni, Ģideļa bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Šefatijas bērni, Atila bērni, Poķereta bērni no Cebaīm, Amona bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Dieva nama kalpotāju un Salamana kalpu bērnu bija pavisam trīssimt deviņdesmit divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Un šie pārnāca līdz no TelMelakas, TelArzus, Ķeruba, Adona, Imera. Bet tie sava tēva namu un savu dzimumu nevarēja pierādīt, vai tie bija no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delajas bērni, Tobijas bērni, Nekoda bērni: sešsimt četrdesmit divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Un no priesteriem: Abajus bērni, Akoca bērni, Barzilajus bērni, kas no Barzilajus, tā Gileādieša, meitām sievu bija ņēmis, un pēc viņa vārda bija nosaukts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Šie savus radu rakstus meklēja bet neatrada; tāpēc tie no priestera amata tapa atmesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Un zemes soģis uz tiem sacīja: lai neēd no tā vissvētākā, tiekams priesteris celtos ar urim un tumim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Visa šī draudze bija kopā: četrdesmit divi tūkstoši trīssimt sešdesmit,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Bez kalpiem un kalponēm, - šo bija septiņtūkstoš trīssimt trīsdesmit septiņi. Un tiem bija divsimt četrdesmit pieci dziedātāji un dziedātājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Viņu zirgu bija septiņsimt trīsdesmit seši, viņu zirgēzeļu divsimt četrdesmit pieci,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Kamieļu četrsimt trīsdesmit pieci, ēzeļu seštūkstoš septiņsimt divdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Un no cilts virsniekiem šie deva ko pie tā darba: zemes soģis piemeta pie tās mantas tūkstoš zelta gabalus, piecdesmit bļodas un piecsimt trīsdesmit priesteru svārkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Un no cilts virsniekiem piemeta pie tās mantas uz to darbu divdesmit tūkstoš zelta gabalus un divtūkstoš divsimt mārciņas sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Un ko tie citi ļaudis meta, tas bija divdesmit tūkstoš zelta gabali un divtūkstoš mārciņas sudraba un sešdesmit septiņi priesteru svārki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Un priesteri un leviti un vārtu sargi un dziedātāji un tie ļaudis un tie Dieva nama kalpotāji un viss Israēls dzīvoja savās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Kad nu septītais mēnesis atnāca, un Israēla bērni bija savās pilsētās, tad visi ļaudis sapulcinājās kā viens vienīgs vīrs laukā priekš Ūdens vārtiem un sacīja uz Ezru, to rakstu mācītāju, lai tas atnes Mozus bauslības grāmatu, ko Tas Kungs Israēlim bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Un priesteris Ezra atnesa bauslību draudzes priekšā, vīriem un sievām un visiem, kas to varēja saprast, pirmā dienā septītā mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Un lasīja no tās uz lauka Ūdens vārtu priekšā no pašas gaismas līdz pusdienai vīru un sievu priekšā, kas tik saprata, un visu ļaužu ausis (griezās) uz bauslības grāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Un Ezra, tas rakstu mācītājs, stāvēja uz augsta koka krēsla, ko tie priekš tam bija uztaisījuši, un viņam sānis stāvēja Matatija un Šemus un Anaja un Ūrija un Hilķija un Maāseja viņam pa labo roku, un viņam pa kreiso roku Pedaja un Mišaēls un Malhija un Hašums un Hašbadanus, Zaharija, Mešulams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Un Ezra atdarīja to grāmatu priekš visu ļaužu acīm, jo viņš stāvēja augstāki nekā visi ļaudis, un kad viņš to atdarīja, tad visi ļaudis uzcēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Un Ezra teica To Kungu, to lielo Dievu, un visi ļaudis atbildēja: Āmen, Āmen! Savas rokas paceldami, un locījās un metās uz savu vaigu zemē priekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Un Ješuūs un Banus un Šerebija, Jamins, Akubs, Šabetajus, Hodija, Maāseja, Kelitus, Azarija, Jozabads, Hanans, Pelaja un tie leviti izskaidroja tiem ļaudīm bauslību, un tie ļaudis stāvēja savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Un tie lasīja no Dieva bauslības grāmatas tulkodami un izskaidrodami, ka lasot to varēja saprast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Tad Nehemija, tas ir tas zemes soģis, un priesteris Ezra, tas rakstu mācītājs, un tie leviti, kas tos ļaudis mācīja, sacīja uz visiem tiem ļaudīm: šī diena Tam Kungam, jūsu Dievam, ir svēta, neesiet noskumuši un neraudat. Jo visi ļaudis raudāja, kad tie dzirdēja bauslības vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Tad viņš uz tiem sacīja: Ejat, ēdiet treknu un dzeriet saldu, un sūtiet daļas tam, kam nekā nav sataisīts. Jo šī diena mūsu Kungam ir svēta. Tad nu neesiet noskumuši, jo prieks pie Tā Kunga ir jūsu stiprums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Un tie leviti apklusināja visus ļaudis sacīdami: esiet klusu; jo šī diena ir svēta, tāpēc neesiet noskumuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Tad visi ļaudis gāja ēst un dzert un daļas sūtīt un lielu prieku darīt; jo tie tos vārdus bija sapratuši, kas tiem bija sacīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Un otrā dienā visas tautas cilts virsnieki, priesteri un leviti sapulcējās pie rakstu mācītāja Ezras, klausīties bauslības vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Un tie atrada bauslībā, ka bija rakstīts, ko Tas Kungs caur Mozu bija pavēlējis, lai Israēla bērni lieveņos dzīvo pa tiem svētkiem septītā mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Un lai tie to izsludina un izsauc pa visām pilsētām un Jeruzālemē sacīdami: ejat ārā kalnos un atnesiet zarus no eļļas kokiem un zarus no meža eļļas kokiem un zarus no mirtu kokiem un zarus no palma kokiem un zarus no (citiem) kupliem kokiem, un taisāt lieveņus, tā kā ir rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Tā tie ļaudis izgāja ārā un atnesa un taisīja sev lieveņus, ikkatrs uz sava jumta un savos pagalmos un Dieva nama pagalmos un uz Ūdens vārtu lauka un uz Efraīma vārtu lauka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Un visa draudze, tie, kas no cietuma bija pārnākuši, taisīja lieveņus un dzīvoja lieveņos. Jo Israēla bērni nebija tā darījuši no Jozuas, Nuna dēla, laika līdz šai dienai, un tur bija varen liela līksmība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Un Dieva bauslības grāmata tapa ikdienas lasīta, no pirmās dienas līdz beidzamai dienai, un tie turēja svētkus septiņas dienas un astotā dienā to atsvēti, tā kā bija nolikts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Un tā paša mēneša divdesmit ceturtā dienā Israēla bērni sapulcējās, gavēdami un maisos un ar zemi uz galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Un Israēla dzimums šķīrās no visiem svešiniekiem, un tie stāvēja un sūdzēja savus grēkus un savu tēvu noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Un tie cēlās no savas vietas un vienu cēlienu tie lasīja Tā Kunga, sava Dieva, bauslības grāmatā, un vienu cēlienu tie sūdzēja (savus grēkus) un pielūdza To Kungu, savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Un augstā levitu vietā stāvēja: Ješuūs un Banus, Kadmiēls, Šebanija, Bunus, Šerebija, Banus un Kenanus, un sauca ar stipru balsi uz To Kungu, savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Un tad sacīja tie leviti Ješuūs un Kadmiēls, Banus, Azabenija, Šerebija, Hodija, Šebanija, Petahja: ceļaties, teiciet To Kungu, savu Dievu, mūžīgi mūžam. Un lai slavēts top Tavas godības vārds, kas ir augstāks pār visu slavu un teikšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Tu esi tas vienīgais Kungs, Tu esi darījis debesis un debesu debesis un visu viņu spēku, zemi un visu, kas zemes virsū, jūru un visu, kas iekš tās, un Tu dari šo visu dzīvu un debesu spēks klanās Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tu esi Tas Kungs un Dievs, kas Ābramu izredzējis un viņu izvedis no Ura Kaldejā un viņam devis vārdu Ābrahāmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Un Tu viņa sirdi esi atradis uzticīgu Sava vaiga priekšā, un ar viņu esi cēlis derību, viņam dot Kanaāniešu, Hetiešu, Amoriešu un Fereziešu un Jebusiešu un Ģirgoziešu zemi, to dot viņa dzimumam; un Tu Savu vārdu stipri esi turējis, tāpēc ka Tu esi taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Un Tu esi redzējis mūsu tēvu bēdas Ēģiptes zemē un viņu brēkšanu klausījis pie Niedru jūras,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Un esi zīmes un brīnumus darījis pie Faraona un pie visiem viņa kalpiem un pie visiem viņa zemes ļaudīm. Jo Tu zināji, ka tie pret tiem bijuši pārgalvīgi, un Tu Sev esi darījis slavu, tā kā šodien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Un jūru Tu esi dalījis viņu priekšā, ka tie pa jūras vidu ir gājuši sausumā; un kas viņiem pakaļ dzinās, tos Tu esi iemetis dziļumos, tā kā akmeni stipros ūdeņos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Un dienā Tu tos esi vadījis ar padebeša stabu un naktī ar uguns stabu, viņiem gaišu darīdams ceļu, kur tiem bija jāiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Un Tu esi nolaidies uz Sinaī kalnu un no debesīm ar tiem runājis un tiem devis taisnas tiesas, īstenu bauslību, labus likumus un baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Un savu svēto dusas dienu Tu tiem esi darījis zināmu, un baušļus un iestādījumus un bauslību tiem esi pavēlējis caur Mozu, Savu kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Un maizi Tu tiem esi devis no debesīm, kad tie bija izsalkuši, un ūdeni tiem izvedis no klints, kad tie bija izslāpuši, un esi uz tiem sacījis, lai ieiet un iemanto to zemi, pār ko Tu Savu roku pacēli, viņiem to dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Bet šie, mūsu tēvi, turējušies pārgalvīgi un viņu kakls palika stīvs, un tie nav klausījuši Taviem baušļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Un ir liegušies klausīt un nav pieminējuši Tavus brīnumus, ko Tu tiem esi darījis, bet tie palikuši stūrgalvīgi un cēluši virsnieku, iet atpakaļ uz savu kalpošanu, dumpinieki būdami. Bet Tu Dievs žēlotājs, žēlīgs un sirdsžēlīgs, lēnprātīgs un no lielas žēlastības, Tu tos neesi atstājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Jebšu tie arī taisīja lietu teļu un sacīja: šis ir tavs dievs, kas tevi izvedis no Ēģiptes zemes, - un tevi gauži kaitināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Tomēr pēc Savas lielās sirdsžēlastības Tu tos neesi atstājis tuksnesī, tas padebeša stabs neatstājās no tiem dienā, tos vezdams pa ceļu, nedz tas uguns stabs naktī, tiem spīdēdams uz ceļa, kur tie gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Un Tu esi devis Savu labo Garu, tos pamācīt, un to mannu Tu neesi atrāvis no viņu mutes, un tiem ūdeni esi devis, kad tie bija izslāpuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Tā Tu tos tuksnesī esi uzturējis četrdesmit gadus, tiem nekāds trūkums nav bijis, viņu drēbes nav palikušas vecas un viņu kājas nav uztūkušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Un Tu tiem esi devis ķēniņu valstis un ļaudis, un tos esi nošķīris šurp un turp. Tā tie ir iemantojuši Sihona zemi un Hešbonas ķēniņa zemi un Basanas ķēniņa Oga zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Un viņu bērnus Tu esi vairojis kā debess zvaigznes un tos ievedis tai zemē, par ko Tu viņu tēviem esi sacījis, ka tie ieies, to iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Tā tie bērni tur ir iegājuši un to zemi iemantojuši, un Tu esi pazemojis tās zemes iedzīvotājus, tos Kanaāniešus, viņu priekšā un nodevis viņu rokās viņu ķēniņus un tās zemes ļaudis, lai ar tiem dara pēc sava prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Un tie ir uzņēmuši stipras pilsētas un treknu zemi un iemantojuši namus, visāda labuma pilnus, izcirstas akas, vīna dārzus un eļļas dārzus un daudz augļu kokus, un tie ir ēduši un paēduši un tauki palikuši, un ir priecājušies caur Tavu lielo labdarīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Bet tie ir palikuši pārgalvīgi un Tev turējušies pretī un atmetuši Tavu bauslību un nokāvuši Tavus praviešus, kas pret tiem liecināja, lai pie Tevis atgriežas, un tie ir padarījuši lielas apkaitināšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Tāpēc Tu tos esi devis viņu naidnieku rokā, kas tos spaidījuši. Bet tiem savu spaidu laikā uz Tevi brēcot, Tu esi dzirdējis no debesīm un pēc Savas lielās apžēlošanas Tu tiem esi devis pestītājus, kas tos izpestīja no viņu naidnieku rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Bet kad tiem bija miers, tad tie atkal darīja ļaunu Tava vaiga priekšā; tā Tu tos atstāji viņu ienaidnieku rokā, un tie pār viņiem valdīja. Kad tie nu atgriezās un uz Tevi brēca, tad Tu tos esi klausījis no debesīm un tos dažu reizi izpestījis pēc Savas lielās apžēlošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Un Tu tiem esi devis liecību, lai tie atgriežas pie Tavas bauslības. Bet tie bija pārgalvīgi un neklausīja Taviem baušļiem un grēkoja pret Tavām tiesām, ko cilvēkam būs darīt, lai caur to dzīvo, un tie Tev griezuši muguru un savu kaklu darījuši stīvu un nav klausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Un Tu uz tiem esi gaidījis daudz gadus un tiem liecinājis caur Savu Garu, caur Saviem praviešiem: bet tie neatgrieza savas ausis. Tāpēc Tu tos esi nodevis pasaules tautu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Tomēr pēc Savas lielās apžēlošanas Tu tos neesi pavisam iznīcinājis nedz tos atstājis; jo Tu esi žēlīgs un sirdsžēlīgs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Un nu mūsu Dievs, Tu stiprais, lielais, varenais un bijājamais Dievs, kas tur derību un sirds žēlastību, - lai Tev nešķiet maza visa šī grūtība, kas mums uzgājusi mūsu ķēniņiem, mūsu lielkungiem un mūsu priesteriem un mūsu praviešiem un mūsu tēviem un visiem Taviem ļaudīm, no Asīrijas ķēniņa laika līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Tomēr Tu esi taisns iekš visa, kas mums uznācis, jo Tu esi uzticīgi darījis; bet mēs esam darījuši bezdievīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Un mūsu ķēniņi, mūsu lielkungi, mūsu priesteri un mūsu tēvi nav turējuši Tavu bauslību un nav vērā ņēmuši Tavas pavēles un Tavas liecības, ko Tu tiem liecinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Jo tie Tev nav kalpojuši savā valstī un iekš Tava lielā labuma, ko Tu tiem biji devis, un tai plašā treknā zemē, ko Tu priekš viņiem biji nolicis, un nav atgriezušies no saviem ļauniem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Redzi, mēs šodien esam kalpi; arī tai zemē, ko Tu mūsu tēviem esi devis, viņas augļus un viņas labumu ēst, - redzi, iekš tās mēs esam kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Un viņas augļi vairojās priekš tiem ķēniņiem, ko Tu pār mums esi iecēlis mūsu grēku dēļ, un tie valda pār mūsu miesām un pār mūsu lopiem pēc savas patikšanas. Tā mēs esam lielās bēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Un pēc visa tā mēs cēlām taisnu derību un to uzrakstījām; un mūsu lielkungi, mūsu leviti un mūsu priesteri to apzieģelēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Un uz tā apzieģelētā stāvēja: Nehemija, tas zemes soģis, Hakalijas dēls, un Cedeķija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Azarija, Jeremija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pašhurs, Amarija, Malhija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hatus, Šebanija, Maluks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harims, Merimots, Obadija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniēls, Ģintuns, Bāruks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mešulams, Abija, Mejamins,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maāzgus, Bilgajus, Šemaja: šie bija priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Un leviti: Ješuūs, Azanijas dēls, Binujus no EnHadada bērniem, Kadmiēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Un viņu brāļi Šebanija, Hodija, Kelitus, Pelaja, Hanans,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Miha, Reūbs, Hašabija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakurs, Šerebija. Šebanija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Banus, Beninus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Tie ļaužu virsnieki: Pareūs, PaātMoabs, Elams, Zatus, Banus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunus, Azgads, Bebajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonija, Bigvājus, Adins,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Aters, Hizkija, Azurs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Hašums, Becajus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Harips, Anatots, Nebajus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpijas, Mešulams, Hezirs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mešezabeēls, Cadoks, Jaduūs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Platija, Hanans, Anaja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hošeja, Hananija, Hašubs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Haloūs, Pilka, Šobeks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehums, Hašabnus, Maāseja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Un Ahija, Hanans, Anans,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Maluks, Harims, Baēnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Un tie citi ļaudis, priesteri, leviti, vārtu sargi, dziedātāji, Dieva nama kalpotāji un visi, kas bija atšķīrušies no tiem pagāniem tanīs zemēs uz Dieva bauslības pusi, viņu dēli un viņu meitas, visi prātīgie un mācītie ļaudis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Šie turējās pie saviem brāļiem, tiem virsniekiem, un svēti apsolījās un zvērēja, staigāt Dieva bauslībā, kas caur Mozu, Dieva kalpu, dota, un turēt un darīt Tā Kunga, mūsu Dieva, baušļus un Viņa tiesas un Viņa likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Un ka mēs negribam dot savas meitas tiem zemes ļaudīm, nedz ņemt viņu meitas saviem dēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Un kad tie zemes ļaudis preces un visādu labību atvedīs svētā dienā pārdot, ka mēs no tiem negribam ņemt svētā dienā vai kādos citos svētkos, un ka mēs septīto gadu gribam turēt par vaļas gadu un atlaist visādu nastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Un tad mēs iecēlām sev bausli, ka ik gadus gribam dot viena sēķeļa trešo daļu sava Dieva nama kalpošanai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Tām priekšliekamām maizēm un tam nemitējamam ēdamam upurim un tam nemitējamam dedzināmam upurim svētdienās, jaunos mēnešos un svētkos, tām svētām dāvanām un tiem grēku upuriem, Israēli salīdzināt, un visiem darbiem mūsu Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Un mēs, priesteri, leviti un tie ļaudis metām meslus par malkas došanu, kas bija pievedama pie mūsu Dieva nama, pēc mūsu tēvu namiem ik gadus savā laikā, dedzināt uz Tā Kunga, mūsu Dieva, altāra, kā tas bauslībā rakstīts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Un ka arī savas zemes pirmajus un visu augļu pirmajus no visādiem kokiem gribam ik gadus nest uz Tā Kunga namu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Un savus pirmdzimušos dēlus un lopus, tā kā tas bauslībā rakstīts; un ka mēs savus pirmdzimušos vēršus un sīkos lopus gribam novest uz sava Dieva namu tiem priesteriem, kas mūsu Dieva namā kalpo;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Un ka tos pirmajus no savas mīklas un no saviem cilājamiem upuriem un visādu koku augļus, vīnu un eļļu gribam nest tiem priesteriem sava Dieva nama kambaros, un desmito tiesu no savas zemes tiem levitiem, un ka šie leviti to desmito tiesu dabū visās pilsētās, kur zemi kopjam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Un ka priesterim no Ārona bērniem būs būt pie tiem levitiem, kad leviti to desmito tiesu dabū, un levitiem būs to desmito tiesu no (saviem) desmitiem nest augšām mūsu Dieva nama mantu kambaros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Jo Israēla bērniem un Levja bērniem cilājamo upuri, labību, vīnu un eļļu būs nest tanīs kambaros, kur arī svētās vietas trauki ir un tie priesteri, kas tur kalpo, un vārtu sargi un dziedātāji, ka mēs sava Dieva nama neatstājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Un tie ļaužu virsnieki dzīvoja Jeruzālemē, bet tie citi ļaudis mesloja, ka pa vienam no desmit būs nākt un dzīvot Jeruzālemē, tai svētā pilsētā, un deviņiem tais citās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Un tie ļaudis svētīja visus, kas ar labu prātu apņēmās Jeruzālemē dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Un šie ir tie valsts virsnieki, kas Jeruzālemē dzīvoja. Bet pa Jūda pilsētām dzīvoja ikviens savā iemantotā tiesā, savās pilsētās, Israēlieši, priesteri un leviti un Dieva nama kalpotāji un Salamana kalpu bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Un Jeruzālemē dzīvoja no Jūda bērniem un no Benjamina bērniem. No Jūda bērniem: Ataja, Uzijas dēls, tas bija Zaharijas, tas Amarijas, tas Šefatijas, tas Mahalaleēļa dēls, no Pereca bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Un Maāseja, Bāruka dēls, tas bija Kol-Hozus, tas Hazajas, tas Adajas, tas Jojariba, tas Zaharijas, tas Šilonus dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Visu Pereca bērnu, kas Jeruzālemē dzīvoja, bija četrsimt sešdesmit astoņi stipri vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Un šie ir Benjamina bērni: Sallus, Mešulama dēls, tas bija Joēda, tas Pedajas, tas Kolajas, tas Maāsejas, tas Itiēļa, tas Ješajas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'Un pēc tā Gabajs un Sallajus, deviņsimt divdesmit astoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Un Joēls, Zihrus dēls, bija uzraugs pār tiem, un Jūda, Senuūs dēls, bija otrs pilsētas valdnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Un no priesteriem: Jedaja, Jojariba dēls, Jaķins.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, Hilķijas dēls, - tas bija Mešulama, tas Cadoka, tas Merajota, tas Ahitoba dēls, - tas bija Dieva nama virsnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Un viņu brāļi, kas to darbu namā darīja, to bija astoņsimt divdesmit divi. Un Adaja, Jeroama dēls, tas bija Pelalijas, tas Amaca, tas Zaharijas, tas Pašhura, tas Malhijas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Un viņa brāļi, cilts virsnieki, to bija divsimt četrdesmit divi. Un Amasajus, Azareēļa dēls, - tas bija Akuzajus, tas Mešilamota, tas Imera dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'Un viņa brāļi, stipri vīri, to bija simts divdesmit astoņi, Un tas uzraugs pār tiem bija Zabdiēls, Ģedolima dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Un no levitiem: Šemaja, Hašuba dēls, tas bija Azrikama, tas Hašabijas, tas Bunus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Un Šabetajus un Jozabads no levitu virsniekiem pār to darbu Dieva nama ārpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Un Matanija, Mihas dēls, tas bija Zabdus, tas Asafa dēls, tas bija tas pirmais, kas pie Dieva lūgšanas uzņēma to slavas dziesmu. Un Bakbuķijus bija tas otrais no saviem brāļiem, un Abdus, Šamuūs dēls, tas bija Galala, tas Jedutuna dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Visu levitu tai svētā pilsētā bija divsimt astoņdesmit četri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Un vārtu sargi: Akubs, Talmons un viņu brāļi, kas vārtus sargāja; to bija simts septiņdesmit divi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Bet tie citi no Israēla, no priesteriem un levitiem, bija pa visām Jūda pilsētām, ikviens savā īpašumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Un tie Dieva nama kalpotāji dzīvoja Ofelā, un Cikus un Ģišpus bija pār Dieva nama kalpotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Un levitu uzraugs Jeruzālemē bija Uzus, Banus dēls, tas bija Hašabijas, tas Matanijas, tas Mihas dēls, no Asafa bērniem, kas bija dziedātāji pie Dieva nama kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Jo ķēniņa pavēle tiem bija dota un skaidrs nolikums tiem dziedātājiem, kas ikkatrai dienai krīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Un Petahja, Mešezabeēla dēls, no Zerus, Jūda dēla, bērniem, bija pie ķēniņa rokas visās ļaužu lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Un pa ciemiem uz saviem tīrumiem dzīvoja no Jūda bērniem KiriatArbā un viņas apgabalā, un Dibonā un viņas apgabalā, un Jekabceēlā un viņas ciemos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Un Ješuā un Moladā un BePeletā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Un HacarŠualā un Bēršebā un viņas apgabalā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Un Ciklagā un Makonā un viņas apgabalā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'Un EnRimonā un Caregā un Jeremutā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Un Zanoā, Adulamā un viņas ciemos, Laķisā un viņas tīrumos, Azekā un viņas apgabalā. Un tie apmetās no Bēršebas līdz Inoma ielejai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Bet Benjamina bērni no Gabas dzīvoja Mihmasā un Ajā un Bētelē un viņas apgabalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anatotā, Nobā, Ananijā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hacorā, Rāmā, Ģitaīmā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadadā, Ceboīmā, Nebalatā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lodā un Onā, tai amatnieku ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Un no levitiem, kam daļa bija Jūdā, kādi dzīvoja iekš Benjamina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Šie ir tie priesteri un leviti, kas bija atnākuši ar Zerubabeli, Šealtiēļa dēlu, un Ješuū: Seraja, Jeremija, Ezra,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarija, Maluks, Hatus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Šekanijus, Rehums, Meremots,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Idus, Ģintous, Abija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mejamins, Maādija, Bilgus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Šemaja un Jojaribs, Jedaja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallus, Amoks, Hilķija un Jedaja. Šie ir priesteru un viņu brāļu virsnieki Ješuūs dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Un tie leviti bija: Ješuūs, Binujus, Kadmiēls, Šerebija, Jūda, Matanilus, - tas ar saviem brāļiem bija iecelts par dziesmu vadoni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Un Bakbuķija un Unnus, viņu brāļi, stāvēja kalpošanā viņiem pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Un Ješuūs dzemdināja Jojaķimu, un Jojaķims dzemdināja Elijašibu, un Elijašibs dzemdināja Jojadu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Un Jojadus dzemdināja Jonatānu, un Jonatāns dzemdināja Jaduū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Un Jojaķima dienās bija no priesteriem cilts virsnieki: Serajam Meraja, Jeremijam Hananija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Ezram Mešulams, Amarijam Johanans,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Malukam Jonatāns, Šebanijam Jāzeps,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Harimam Adnus, Merajotam Ebkajus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Idum Zaharija, Ģintonam Mešulams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abijam Sihrus, Minjaminam Moadijam Piltajus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgum Šamuūs, Šemajam Jonatāns,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Un Jojaribam Matnajus, Jedajam Uzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Sallajam Kallajus, Amokam Ēbers,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilķijam Hašabija, Jedajam Netaneēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Elijašiba, Jojada, Jehohanana un Jaduūs dienās levitu cilts virsnieki tapa uzrakstīti un priesteri apakš Dārija, tā Persieša, valdīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Levja bērnu cilts virsnieki laiku grāmatā ir sarakstīti līdz Jehohanana, Elijašiba dēla, dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Bet levitu virsnieki bija šie: Hašabija, Šerebija un Ješuūs, Kadmiēļa dēls, un viņu brāļi bija viņiem klāt, slavēt un teikt, pēc Dieva vīra Dāvida likuma, ikkatrs savu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanija un Bukbaķija, Obadijus, Mešulams, Talmons, Akubs, tie bija vārtu sargi, sargāt mantas namus pie vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Šie bija Jojaķima, Ješuūs dēla, Jocadaka dēla dēla, dienās, un Nehemijas, tā zemes soģa, un priestera Ezras, tā rakstu mācītāja, dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Un pie Jeruzālemes mūra iesvētīšanas meklēja levitus no visām viņu vietām, tos vest uz Jeruzālemi, ka tie noturētu iesvētīšanas prieka svētkus ar pateikšanas un teikšanas dziesmām un ar pulkstenīšiem un somastabulēm un koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Un tie dziedātāju bērni sapulcējās no Jeruzālemes apgabala un no Netofatas ciemiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Un no BetGilgalas un no Ģebas tīrumiem un no Asmavetas. Jo dziedātāji bija sev uzcēluši ciemus ap Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Tad priesteri un leviti šķīstījās un šķīstīja tos ļaudis un tos vārtus un to mūri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Tad es vedu Jūda virsniekus uz mūri un liku divus lielus dziedātāju pulkus uz svētku gājienu pa labo roku ārpus mūra līdz Mēslu vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Un tiem gāja pakaļ Ozaja un viena puse no Jūda virsniekiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Un Azarijus un Ezra un Mešulams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Jūda un Benjamins un Šemaja un Jeremija,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Un no priesteru bērniem ar bazūnēm: Zaharija, Jonatāna dēls, tas bija Šemajas, tas Matanijas, tas Mikajas, tas Zakura, tas Asafa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Un viņa brāļi Šemaja un Azareēls, Milalajus, Ģilalajus, Maājus, Netaneēls un Jūda, Hananus, ar Tā Dieva vīra Dāvida mūzikas rīkiem; un Ezra, tas rakstu mācītājs, gāja viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Un pie Akas vārtiem, kas bija pretim, tie gāja augšām pa tām pakāpēm uz Dāvida pilsētu, pa mūra uzkāpi uz Dāvida namu, un līdz Ūdens vārtiem pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Tas otrais dziedātāju pulks gāja it pretī, un es viņam pakaļ ar otru ļaužu pusi, pa mūri no Cepļa torņa līdz Platajam mūrim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'Un pa Efraīma vārtiem, pa Vecpilsētas vārtiem un pa Zivju vārtiem un Hananeēļa torni un Meas(Simtnieku) torni un līdz Avju vārtiem, un tie apstājās pie Cietuma vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Un tā abi dziedātāju pulki stāvēja pie Dieva nama, arī es un valdnieku viena puse līdz ar mani,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Un priesteri Elijaķims, Maāseja, Minjamins, Mikajus, Elioēnajus, Zaharija, Ananija ar bazūnēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Un Maāseja, Šemaja, Eleazars un Uzus un Jehohanans un Malhija un Elams un Azars. Un dziedātāji dziedāja un Jizraķija bija tas vadonis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Un tie upurēja tai dienā lielus upurus un priecājās; jo Dievs tos bija iepriecinājis ar lielu prieku; tur priecājās arī sievas un bērni, tā ka Jeruzālemes prieks tapa tālu dzirdēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Tai dienā tur vīri kļuva iecelti pār mantu kambariem, kur tie cilājamie upuri, tie pirmaji un tie desmitie, lai tur sakrāj no pilsētu tīrumiem tās pienākamās daļas priekš priesteriem un levitiem. Jo Jūda priecājās par tiem priesteriem un levitiem, kas tur stāvēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Un ņēma vērā sava Dieva nama kopšanu un to šķīstīšanu; tāpat arī dziedātāji un vārtu sargi pēc Dāvida un viņa dēla Salamana likuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Jo vecos laikos Dāvida un Asafa dienās bija priekšnieki dziedātājiem un Dieva slavas un pateicības dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Tāpēc viss Israēls Zerubabeļa dienās un Nehemijas dienās deva daļas dziedātājiem un vārtu sargiem, ikdienas savu dienas daļu. Un deva to svēto tiesu levitiem, un leviti deva to svēto tiesu Ārona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Tai dienā Mozus grāmatā lasīja priekš ļaužu ausīm un tur atrada rakstītu, ka Amoniešiem un Moabiešiem ne mūžam nebūs nākt Dieva draudzē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Tāpēc ka viņi nebija nākuši pretī Israēla bērniem ar maizi un ar ūdeni, bet pret tiem bija derējuši Bileāmu, viņus nolādēt, lai gan mūsu Dievs lāstu pārvērta par svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Tad notikās, ka šo bauslību dzirdot tie visus svešiniekus atšķīra no Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Un priesteris Elijašibs, kas bija iecelts pār mūsu Dieva nama kambari, papriekš bija sadraudzējies ar Tobiju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Un viņam bija taisījis lielu kambari, kur tie papriekš bija nolikuši ēdamo upuri, vīraku un rīkus un labības, vīna un eļļas desmitos, kas kļuva nodoti priekš levitiem un dziedātājiem un vārtu sargiem, līdz ar priesteru cilājamo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Bet viss tas notika, kamēr es Jeruzālemē nebiju; jo Artakserksus, Bābeles ķēniņa, trīsdesmit otrā gadā es nācu pie ķēniņa, un pēc kāda laika es to no ķēniņa izlūdzos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Kad es nu nācu uz Jeruzālemi un samanīju to ļaunumu, ko Elijašibs priekš Tobijas bija darījis, viņam kambari taisīdams Dieva nama pagalmos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Tad tas man ļoti rieba, un es izmetu visas Tobijas nama lietas no tā kambara ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Es arī pavēlēju, to kambari šķīstīt, un es atkal tur ienesu Dieva nama rīkus ar ēdamo upuri un vīraku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Es arī samanīju, ka levitiem viņu daļa nebija dota, tā ka leviti un dziedātāji, kas to darbu darījuši, bija aizmukuši ikkatrs uz savu tīrumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Tad es bāros ar tiem virsniekiem un sacīju: kāpēc Dieva nams ir atstāts? Un es tos sapulcināju un tos atkal iecēlu viņu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Tad visa Jūda valsts atnesa to desmito no labības un no vīna un no eļļas mantas namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Un es par mantu sargiem iecēlu priesteri Šelemiju un rakstu mācītāju Cadoku un Pedaju no levitiem, un viņiem pa roku Hananu, Zakura, Matanijas dēla, dēlu; jo šie tapa turēti par uzticamiem, un tiem tapa uzlikts, lai izdala saviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Piemini mani, mans Dievs, par to un neizdeldē manu labdarīšanu, ko esmu darījis pie sava Dieva nama un pie viņa kalpošanas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Tanīs dienās es Jūdā redzēju, ka vīna spaidus mina svētā dienā, un ka kūlīšus saņēma, ko uz ēzeļiem krāva, vīnu, vīna ķekarus un vīģes un visādu nastu, un svētā dienā ienesa Jeruzālemē, un es tai dienā (pret tiem) devu liecību, kad tie barību pārdeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Tur arī Tirieši dzīvoja, kas zivis atnesa un visādu preci, un to pārdeva svētā dienā Jūda bērniem un Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Tad es bāros ar Jūda virsniekiem un uz tiem sacīju: kas tas par ļaunu darbu, ko jūs darāt un pārkāpjat svēto dienu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Vai jūsu tēvi tā nav darījuši, un mūsu Dievs ir vedis visu šo nelaimi pār mums un pār šo pilsētu? Un jūs vairojiet tās dusmas pār Israēli, pārkāpdami svēto dienu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Un notikās svētai dienai nākot, kad tumšs metās Jeruzālemes vārtos, tad es pavēlēju durvis aizslēgt un neatdarīt, kamēr svētā diena pagājusi. Un no saviem puišiem es kādus liku pie vārtiem, ka nekādu nastu tur neienestu svētā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Tad tie zāļu un visādas preces pārdevēji palika pa nakti ārā Jeruzālemes priekšā vienreiz un otrreiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Un es pret tiem apliecināju un uz tiem sacīju: kāpēc jūs pa nakti paliekat pie mūra? Ja jūs to atkal darīsiet, tad es jūs grābšu rokā. No tā laika tie vairs nenāca svētā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Un levitiem es sacīju, lai šķīstās un nāk vārtus sargāt, ka svētā diena taptu svētīta. Arī par to piemini mani, mans Dievs, un žēlo mani pēc Tavas lielās žēlastības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Es tanīs dienās arī redzēju Jūdus, kas bija apņēmuši Ašdodiešu, Amoniešu un Moabiešu sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Un viņu bērni runāja pus Ašdodiski un nemācēja Jūdiski runāt, bet pēc abēju tautu valodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Tad es ar tiem bāros un tos lādēju un situ kādus no tiem un tiem plūcu matus un tiem liku pie Dieva zvērēt, jums nebūs savas meitas dot viņu dēliem, nedz ņemt viņu meitas saviem dēliem nedz sev.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Vai šo dēļ Salamans, Israēla ķēniņš, nav apgrēkojies? Jebšu nevienai tautai tāds ķēniņš nav bijis, kāds viņš bija, un viņš savam Dievam bija mīļš, un Dievs viņu bija iecēlis par ķēniņu pār visu Israēli, un tomēr ir tādu tās svešās sievas paveda uz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Vai tad mēs jums klausīsim un visu tādu lielu ļaunumu darīsim noziegdamies pret savu Dievu, ka apņemam svešas sievas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Un viens no Jojada, Elijašiba dēla, tā augstā priestera, bērniem bija par znotu palicis Sanebalatam, tam Horonietim, tāpēc es viņu aizdzinu no sevis projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Piemini viņus, mans Dievs, tāpēc ka tie sagānījuši priesteru amatu un priesteru un levitu derību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Tā es tos šķīstīju no visiem svešiem ieradumiem un noliku priesteriem un levitiem, ikkatram savu darīšanu savā kalpošanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Un to malkas došanu noliktos laikos un tos pirmajus. Piemini, mans Dievs, man to par labu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Un notikās Ahasverus laikā, šis ir tas Ahasverus, kas no Indijas līdz Moru zemei valdīja pār simts divdesmit septiņām valstīm, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Tanīs dienās, kad ķēniņš Ahasverus sēdēja uz sava goda krēsla Sūsanas pilī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Savas valdīšanas trešā gadā viņš darīja dzīres visiem saviem lielkungiem un saviem kalpiem, Persiešu un Mēdiešu karavadoņiem, virsniekiem un valsts valdniekiem, kas viņa priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Ka viņš parādītu savas valstības bagāto godību un savas augstības dārgo spožumu, daudz dienas, simts un astoņdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Kad nu šīs dienas bija pagājušas, tad ķēniņš visiem ļaudīm, kas atradās Sūsanas pilī, taisīja dzīres, gan maziem, gan lieliem, septiņas dienas tai dārzā ķēniņa nama pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Tur karājās baltas, sarkanas un pazilas gardīnes ar dārgām linu un purpura saitēm sudraba gredzenos pie marmora pīlāriem piesietas; sēdekļi bija no zelta un sudraba uz grīdas no sarkana un balta un dzeltena un melna marmora.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Un dzēriens tapa nests zelta traukos un ikkatrs trauks bija savādāks nekā tie citi, un ķēniņa vīna bija papilnam, pēc ķēniņa bagātības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Un pie dzeršanas bija nolikums, nevienu nespiest, jo tā ķēniņš bija stipri pavēlējis visiem sava nama lielkungiem, lai ikviens dara kā tīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Un ķēniņiene Vasti arī taisīja dzīres tām sievām ķēniņa Ahasverus pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Septītā dienā, kad ķēniņa sirds bija līksma no vīna, viņš sacīja uz Meūmanu, Bistu, Arbonu, Bigtu un Abagtu, Zetaru un Karku, tiem septiņiem kambarjunkuriem, kas ķēniņa Ahasverus priekšā kalpoja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Lai ķēniņieni Vasti atved ķēniņa priekšā ar ķēniņa kroni, ka viņš tiem ļaudīm un lielkungiem rādītu viņas skaistumu, jo tā bija skaista no vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Bet ķēniņiene Vasti liedzās nākt uz ķēniņa vārdu caur tiem kambarjunkuriem. Tad ķēniņš ļoti apskaitās, un viņa bardzība iekš viņa iedegās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Un ķēniņš sacīja uz tiem gudriem, kas tos laikus prata, - (jo tā ķēniņa lietas bija apspriežamas no visiem likumu un tiesu zinātājiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Bet šie bija tie tuvākie pie viņa: Karzenus, Zetars, Admatus, Taršiš, Meres, Marzenus, Memukans, septiņi Persiešu un Mēdiešu lielkungi, kas drīkstēja redzēt ķēniņa vaigu un sēdēja tai augstākā vietā valstī):');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Ko lai dara pēc tiesas ar ķēniņieni Vasti, tāpēc ka tā nav darījusi ķēniņa Ahasverus vārdu, kas caur tiem kambarjunkuriem viņai bija sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Tad Memukans ķēniņa un to lielkungu priekšā sacīja: ķēniņiene Vasti ir noziegusies nevien pret ķēniņu, bet arī pret visiem lielkungiem un pret visiem ļaudīm, kas dzīvo visās ķēniņa Ahasverus valstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Jo šī ķēniņienes liegšanās izpaudīsies pie visām sievām, ka tās nicinās savus vīrus pie sevis un tā sacīs: ķēniņš Ahasverus pavēlēja, lai ķēniņieni Vasti pie viņa atved, bet tā nenāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Tagad Persiešu un Mēdiešu lielmātes sacīs uz visiem ķēniņa lielkungiem, kad dzirdēs šo ķēniņienes darīšanu, un tad būs ķibeles un dusmu papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Ja ķēniņam patīk, tad lai no viņa iziet ķēniņa pavēle un lai top rakstīts Mēdiešu un Persiešu likumos, tā ka netop pārkāpts, ka Vastij nebūs vairs nākt ķēniņa Ahasverus priekšā, un lai ķēniņš viņas godu dod citai, kas labāka ir nekā viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Un kad ķēniņa pavēle taps dzirdēta, kas sūtama pa visu viņa valsti (jo tā ir liela), tad visas sievas savus kungus turēs godā, pie augstiem un zemiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Un tas vārds patika ķēniņam un tiem lielkungiem, un ķēniņš darīja pēc Memukana vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Tad grāmatas tapa sūtītas visās ķēniņa valstīs uz ikvienu valsti pēc viņas valodas un uz visām tautām pēc viņu mēles, ka ikkatrs vīrs lai ir kungs savā namā, un to sacīja ikkatrai tautai viņas valodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Pēc tam, kad ķēniņa Ahasverus bardzība bija nostājusies, tad viņš pieminēja Vasti, un ko tā bija darījusi, un kas par viņu bija nospriests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Tad ķēniņa jaunekļi, kas viņam kalpoja, sacīja: lai ķēniņam meklē jaunas jumpravas skaistu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Un lai ķēniņš ieceļ uzraugus visās savās valsts tiesās, ka tie sapulcē visas jaunās jumpravas skaistu vaigu uz Sūsanas pili, uz to sievu namu, apakš Egajus, ķēniņa kambarjunkura, tā sievu sarga, un lai pie tām notiek mazgāšana un svaidīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Un kura jauna meita ķēniņam labi patiks, tā lai top par ķēniņieni Vastis vietā. Un tas vārds patika ķēniņam un viņš tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Un viens Jūdu vīrs bija Sūsanas pilī, vārdā Mardakajs, tas bija Jaīra, tas Šimejus, tas Ķisa dēls, Benjaminietis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Tas bija aizvests no Jeruzālemes līdz ar tiem, kas tapa aizvesti ar Jekaniju, Jūda ķēniņu, ko NebukadNecars, Bābeles ķēniņš, bija aizvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Un viņš bija Adasas audžu tēvs, tā ir Estere, viņa brālēna meita, jo viņai nebija ne tēva ne mātes. Un viņa bija jauna meita daiļu augumu un skaistu vaigu. Un kad viņas tēvs un viņas māte nomira, tad Mardakajs viņu bija pieņēmis par meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Kad nu ķēniņa vārds un viņa pavēle izpaudās un daudz jaunas meitas tika savestas Sūsanas pilī apakš Egajus rokas, tad Estere arī tapa ņemta ķēniņa namā, apakš Egajus, tā sievu sarga, rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Un tā meita viņam patika un atrada žēlastību viņa priekšā, un viņš steidzās tai dot tās svaidāmās zāles priekš mazgāšanās un viņas daļu, un viņš tai deva septiņas daiļas jaunas meitas no ķēniņa nama, un viņš to noveda ar viņas meitām tai vislabākā vietā sievu namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Bet Estere nebija teikusi nedz savus ļaudis nedz savus radus, jo Mardakajs viņai bija piekodinājis, lai tā to neteicot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Un Mardakajs staigāja ikdienas gar sievu nama pagalmu, lai dabūtu zināt, kā Esterei klājās un kas ar to būšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kad nu ikvienas jaunietes reize atnāca iet pie ķēniņa Ahasverus, kad pēc sievu likuma ar to bija darīts divpadsmit mēnešus, (jo tik daudz laika pagāja viņu mazgāšanai un svaidīšanai, proti sešus mēnešus ar mirru eļļu un sešus mēnešus ar balzamu un citām sievu zālēm), -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Tad tā jauniete nāca pie ķēniņa, un ko viņa prasīja, to viņai deva, ka viņa ar to ietu no sievu nama uz ķēniņa namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Vakarā viņa iegāja un rītā viņa gāja atpakaļ uz otru sievu namu, apakš Zaāzgas, ķēniņa kambarjunkura, lieko sievu sarga; viņa negāja atkal pie ķēniņa, kā vien, kad ķēniņš viņu gribēja un viņu pie vārda sauca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Kad nu Esteres, Abikaīla, Mardakaja brālēna, meitas, Mardakaja audzēknes, reize atnāca, iet pie ķēniņa, tad viņa neprasīja ne ko, ka tik vien ko Egajus, ķēniņa kambarjunkurs, tas sievu sargs, sacīja. Un Estere atrada žēlastību pie visiem, kas viņu redzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Tā Estere tapa ņemta pie ķēniņa Ahasverus ķēniņa namā desmitā mēnesī, tas ir Tebetmēnesis, viņa valdīšanas septītā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Un ķēniņš iemīlēja Esteri pār visām sievām, un viņa atrada vairāk žēlastības un laipnības viņa priekšā nekā visas jaunietes, un viņš lika ķēniņa kroni uz viņas galvu un to cēla pār ķēniņieni Vastis vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Un ķēniņš taisīja lielas dzīres visiem saviem lielkungiem un kalpiem, - tās bija Esteres dzīres, - un deva valstīm atvieglināšanu un izdalīja dāvanas pēc ķēniņa bagātības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Kad nu otrā reizē tās jaunietes tapa sapulcētas, tad Mardakajs sēdēja ķēniņa vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Bet Estere nebija teikusi ne savus radus, ne savus ļaudis, tā kā Mardakajs tai bija pavēlējis; jo Estere darīja pēc Mardakaja vārda, kā to laiku, kad viņa pie tā uzauga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Tanīs dienās, kad Mardakajs sēdēja ķēniņa vārtos, Bigtans un Teres, divi ķēniņa kambarjunkuri no tiem sliekšņa sargiem, apskaitās un meklēja rokas pielikt pie ķēniņa Ahasverus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Un šī lieta Mardakajum tapa zināma, un viņš to izteica ķēniņienei Esterei, un Estere to sacīja ķēniņam Mardakaja vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Un tā lieta tapa izmeklēta un tā atrasta, un tie divi tapa pakārti pie koka, un tas tapa ierakstīts laiku grāmatā priekš ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Pēc tam ķēniņš Ahasverus paaugstināja Amanu, Medatus dēlu, to Agaģieti, un to cēla augsti, un lika viņa krēslu pār visiem lielkungiem, kas pie viņa bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Un visi ķēniņa kalpi, kas ķēniņa vārtos bija, locījās un klanījās Amana priekšā, jo ķēniņš tā viņa pēc bija pavēlējis; bet Mardakajs nelocījās un neklanījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Tad ķēniņa kalpi, kas bija ķēniņa vārtos, sacīja uz Mardakaju: kāpēc tu pārkāpi ķēniņa pavēli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Un tā tie ikdienas uz viņu runāja, bet viņš tiem neklausīja. Tad tie to stāstīja Amanam, ka redzētu, vai tāda Mardakaja pretestība pastāvētu, - jo tas viņiem bija stāstījis, ka viņš esot Jūds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Kad nu Amans redzēja, ka Mardakajs nelocījās un viņa priekšā neklanījās, tad Amans palika ļoti dusmīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Bet viņam šķita vēl maz esam, roku pielikt pie Mardakaju vien, (jo tie viņam bija izteikuši Mardakaja cilti,) bet Amans meklēja izdeldēt visus Jūdus pa visu Ahasverus valsti, Mardakaja tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Pirmā mēnesī, (tas ir Nīsana mēnesis,) ķēniņa Ahasverus divpadsmitā gadā, meta meslus, tas ir pur, priekš Amana ikdienas un ik mēnešus līdz tam divpadsmitam mēnesim, tas ir Adara mēnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Un Amans sacīja uz ķēniņu Ahasveru: viena tauta ir izkaisīta un izdalīta starp ļaudīm visās tavas valsts tiesās, un viņiem ir citāda bauslība, nekā visiem citiem ļaudīm, un ķēniņa pavēli tie nedara, tāpēc ķēniņam nepieklājās tos ieredzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Ja ķēniņam patīk, tad lai raksta, ka tie kļūst izdeldēti, tad es tiem mantas uzraugiem desmit tūkstoš talentus sudraba iesvēršu rokā, lai to nes ķēniņa mantas namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Tad ķēniņš novilka savu gredzenu no savas rokas un to deva Agaģietim Amanam, Medatus dēlam, Jūdu pretiniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Un ķēniņš sacīja uz Amanu: tas sudrabs lai tev paliek, arī tie ļaudis, ka tu ar tiem dari, kā tev patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Tad ķēniņa skrīveri tapa saaicināti, trīspadsmitā dienā pirmā mēnesī, un tapa rakstīts, tā kā Amans pavēlēja, uz ķēniņa valdītājiem un zemes valdniekiem, kas bija pār ikkatru valsti, un uz ikkatras tautas virsniekiem, ikvienai valstij pēc viņas valodas un ikvienai tautai pēc viņas mēles; ķēniņa Ahasverus vārdā tas tapa rakstīts un ar ķēniņa gredzenu aizzieģelēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Un tās grāmatas tapa sūtītas caur skrējējiem pa visām ķēniņa Ahasverus valstīm, ka visi Jūdi taptu izdeldēti, nokauti un nomaitāti, gan jauni, gan veci, bērniņi un sievas, vienā dienā, trīspadsmitā dienā divpadsmitā mēnesī, tas ir Adara mēnesis, un ka viņu manta taptu laupīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Tais grāmatās bija rakstīts: ka pavēle dota visās valstīs, ka visiem ļaudīm nāktu zināms, lai tie tai pašā dienā būtu gatavi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Un tie skrējēji izgāja steigšus pēc ķēniņa vārda; un tā pavēle bija dota Sūsanas pilī. Un ķēniņš un Amans sēdēja un dzēra, bet Sūsanas pilsēta iztrūcinājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Kad nu Mardakajs dabūja zināt visu, kas bija noticis, tad Mardakajs saplosīja savas drēbes un apvilka maisu ar pelniem, un gāja pilsētas vidū, un brēca ar lielu un rūgtu brēkšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Un viņš nāca priekš ķēniņa vārtiem; jo (pašos) ķēniņa vārtos neviens nevarēja ieiet ar maisu apģērbies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Un visās valstīs un vietās, kurp ķēniņa vārds un viņa pavēle nonāca, bija lielas bēdas Jūdiem ar gavēšanu un raudāšanu un bēdāšanos, un daudzi gulēja maisos un pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Tad Esteres meitas un viņas kambarjunkuri nāca un viņai to stāstīja, un ķēniņiene iztrūcinājās ļoti un viņa sūtīja drēbes, Mardakaju apģērbt un to maisu viņam atņemt, bet viņš tās nepieņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Tad Estere aicināja Ataku, vienu no ķēniņa kambarjunkuriem, kas viņai bija iedots, un viņa pavēlēja Mardakaju izvaicāt, kas un kāpēc tas esot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Un Ataks izgāja pie Mardakaju uz pilsētas ielu priekš ķēniņa vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Tad Mardakajs viņam stāstīja visu, kas tam bija noticis, un to nospriesto sudrabu, ko Amans bija solījis ķēniņa mantu namā iesvērt par Jūdiem, ka tie taptu izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Un viņš tam deva tās rakstītās pavēles norakstu, kas Sūsanā bija dota, ka tie taptu izdeldēti, lai viņš to Esterei rādītu un viņai stāstītu, un viņai pavēlētu, iet pie ķēniņa, viņu piesaukt un lūgt savas tautas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Tad Ataks nāca un sacīja Esterei Mardakaja vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Un Estere sacīja uz Ataku un lika Mardakajam teikt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Visi ķēniņa kalpi un visi ķēniņa valsts ļaudis zina, ka ikkatrs, vīrs vai sieva, kas pie ķēniņa nāk iekšējā pagalmā, kas nav aicināts, tam nospriests, to nokaut, (bez vien, kad ķēniņš to zelta scepteri viņam piesniedz, ka viņš paliek dzīvs). Bet es neesmu aicināta pie ķēniņa nākt nu jau trīsdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Un Esteres vārdus atsacīja Mardakajam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Tad Mardakajs Esterei atkal lika sacīt: nedomā savā prātā, ka tu savu dzīvību ķēniņa namā labāki izglābsi nekā tie citi Jūdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Jo ja tu šinī laikā klusu cietīsi, tad Jūdiem nāks palīdzība un izglābšana no citas vietas, bet tu un tava tēva nams iesiet bojā. Un kas zina, vai tu šī laika labad neesi iecelta par ķēniņieni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Tad Estere Mardakajam lika sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Ej un sapulcē visus Jūdus, kas Sūsanā atrodas, un gavējiet priekš manis un neēdiet, nedz dzeriet trīs dienas, ne dienu ne nakti; es ar savām meitām, mēs tāpat gavēsim, un tā es iešu pie ķēniņa, jebšu tas nav pēc likuma; ja tad jāiet bojā, tad jāiet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Tad Mardakajs nogāja un darīja visu, ko Estere viņam bija pavēlējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Tad Estere apģērbās trešā dienā kā ķēniņiene un gāja ķēniņa nama iekšējā pagalmā, ķēniņa namam pretī; un ķēniņš sēdēja uz sava goda krēsla ķēniņa namā, tām nama durvīm pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Un kad ķēniņš redzēja ķēniņieni Esteri pagalmā stāvam, tad tā atrada žēlastību priekš viņa acīm, tā ka ķēniņš to zelta scepteri, kas bija viņa rokā, Esterei piesniedza, un Estere piegāja un aizskāra sceptera galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Tad ķēniņš uz viņu sacīja: kas tev kait, ķēniņiene Estere, jeb ko tu prasi? Un pat valsts viena puse tev taps dota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Tad Estere sacīja: ja ķēniņam patīk, tad lai ķēniņš un Amans šodien nāk uz tām dzīrēm, ko es viņam esmu sataisījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Un ķēniņš sacīja: lai Amans steidzās un dara pēc Esteres vārda. Kad nu ķēniņš un Amans nāca uz tām dzīrēm, ko Estere bija sataisījusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Tad ķēniņš sacīja uz Esteri vīnu dzerot: ko tu lūdzi, tas tev taps dots, un ko tu prasi, tam būs notikt, arī līdz pusvalstij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Tad Estere atbildēja un sacīja: mana lūgšana un mana prasīšana ir šī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Ja esmu atradusi žēlastību priekš ķēniņa un ja ķēniņam ir pa prātam, manu lūgšanu man dot un darīt, ko es prasīšu, tad lai ķēniņš un Amans nāk uz tām dzīrēm, ko es tiem sataisīšu, tad es rītu darīšu pēc ķēniņa vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Tad Amans tai dienā izgāja līksms un ar labu prātu. Bet kad Amans Mardakaju redzēja ķēniņa vārtos, ka tas necēlās un priekš viņa nelocījās, tad Amans palika dusmu pilns pret Mardakaju, tomēr viņš savaldījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Un tas nāca savā namā, un sūtīja un lika nākt saviem draugiem līdz ar Zeresu, savu sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Un Amans tiem izteica savas bagātības godu un savu dēlu pulku, un visu, kā ķēniņš viņu bija paaugstinājis, un kā tas viņu bija pacēlis pār tiem lielkungiem un ķēniņa kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Un Amans sacīja: un ķēniņiene Estere nevienam nav likusi nākt līdz ar ķēniņu uz tām dzīrēm, ko tā ir sataisījusi, kā man vien, un arī uz rītu no viņas esmu aicināts līdz ar ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Bet viss tas man nav gana, kamēr es to Jūdu Mardakaju redzu sēžam ķēniņa vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Tad viņa sieva Zeresa un visi viņa draugi uz to sacīja: lai uzceļ koku piecdesmit olektis augstumā, un saki rītu ķēniņam, ka Mardakaju pie tā būs pakārt, un tad ej līksms ar ķēniņu uz dzīrēm. Un šis padoms patika Amanam, un viņš to koku lika uzcelt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Tanī naktī ķēniņam nenāca miegs un viņš pavēlēja, lai atnes laiku grāmatu, kur tās vērā liekamās lietas bija uzrakstītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Un to lasīja ķēniņa priekšā. Un tur atrada rakstītu, ka Mardakajs bija zināmu darījis, ka Bigtans un Teres, ķēniņa divi kambarjunkuri un sliekšņa sargi, bija meklējuši roku likt pie ķēniņa Ahasverus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Tad ķēniņš sacīja: kāds gods un kāda paaugstināšana Mardakajam par to notikusi? Un ķēniņa jaunekļi, viņa sulaiņi, sacīja: viņam nekas nav noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Tad ķēniņš sacīja: kas ir pagalmā? (Bet Amans bija nācis ķēniņa nama ārējā pagalmā, ķēniņam sacīt, lai Mardakaju pakar pie tā koka, ko viņš tam bija licis uzcelt.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Un ķēniņa jaunekļi uz viņu sacīja: redzi, Amans stāv pagalmā. Tad ķēniņš sacīja: lai viņš nāk iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Tad Amans nāca iekšā, un ķēniņš uz to sacīja: ko būs darīt tādam vīram, ko ķēniņš labprāt grib godāt? Tad Amans domāja savā sirdī: kurš būs, ko ķēniņš grib godāt, nekā es pats?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Tādēļ Amans sacīja uz ķēniņu: Tam vīram, ko ķēniņš grib godāt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Tam būs nest ķēniņa drēbes, ar ko ķēniņš pats mēdz apģērbties, un zirgu, uz kā ķēniņš mēdz jāt un kam valstības kronis likts uz galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Un to drēbi ar to zirgu būs rokā dot vienam no tiem lielkungiem un to vīru, ko ķēniņš grib godāt, ar to būs apģērbt, un viņam likt jāt uz tā zirga pa pilsētas ielām un viņa priekšā izsaukt: tā dara tam vīram, ko ķēniņš grib godāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Tad ķēniņš sacīja uz Amanu: steidzies, ņem to drēbi un to zirgu, tā kā tu esi runājis, un dari tā tam Jūdam Mardakajam, kas sēž ķēniņa vārtos, un lai netrūkst neviena vārda no visa, ko tu esi runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Tad Amans ņēma tās drēbes un to zirgu un apģērba Mardakaju, un lika viņam jāt pa pilsētas ielām un izsauca viņa priekšā: tā dara tam vīram, ko ķēniņš grib godāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Pēc tam Mardakajs griezās atpakaļ ķēniņa vārtos; bet Amans steidzās atkal mājās, bēdīgs un aizsegtu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Un Amans teica savai sievai Zeresai un visiem saviem draugiem visu, kas viņam bija noticis. Tad viņa gudrie un Zeresa, viņa sieva, uz to sacīja: ja Mardakajs, kā priekšā tu esi iesācis krist, ir no Jūdu dzimuma, tad tu pret viņu nekā neiespēsi, bet tu viņa priekšā krizdams kritīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Kad tie vēl ar viņu runāja, tad ķēniņa kambarjunkuri atnāca un steigšus Amanu noveda dzīrēs, ko Estere bija sataisījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Kad nu ķēniņš un Amans nāca pie ķēniņienes Esteres uz dzīrēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Tad ķēniņš sacīja uz Esteri atkal otrā dienā vīnu dzerot: ko tu lūdzi, ķēniņiene Estere, tas tev taps dots, un ko tu prasi, arī līdz pusvalstij, tam būs notikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Tad ķēniņiene Estere atbildēja: ja es, ķēniņ, žēlastību esmu atradusi tavās acīs, un ja ķēniņam patīk, tad dod man manu dzīvību uz manu lūgšanu un manus ļaudis uz manu prasīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Jo mēs esam pārdoti, es un mani ļaudis, ka topam izdeldēti, nokauti un nomaitāti. Ja mēs būtu pārdoti par kalpiem un kalponēm, tad es būtu klusu cietusi; jo nelaime neatsver ķēniņa traucējumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Tad ķēniņš Ahasverus atbildēja un sacīja uz ķēniņieni Esteri: kas tas tāds un kur ir tas, kas to savā prātā ir apņēmies, tā darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Tad Estere atbildēja: tas pretinieks un ienaidnieks ir šis niknais Amans. Tad Amans iztrūcinājās ķēniņa un ķēniņienes priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Un ķēniņš cēlās savā bardzībā no dzīrēm un gāja uz tā nama dārzu. Un Amans stāvēja un meklēja savu dzīvību no ķēniņienes Esteres, jo viņš redzēja, ka ķēniņš par viņu bija nodomājis nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Un ķēniņš griezās atpakaļ no nama dārza uz dzīru namu, un Amans bija nokritis pie tā sēdekļa, uz kā Estere sēdēja. Tad ķēniņš sacīja: vai viņš arī pie ķēniņienes varas darbu grib darīt pie manis namā? Kad šis vārds no ķēniņa mutes izgāja, tad Amanam aizsedza galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Un Arbonus, viens no ķēniņa kambarjunkuriem, sacīja: redzi, Amana namā stāv koks piecdesmit olektis augstumā, ko Amans cēlis priekš Mardakaju, kas runājis labu priekš ķēniņa. Tad ķēniņš sacīja: pakariet viņu pie tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Tad tie pakāra Amanu pie tā koka, ko tas Mardakajam bija licis uzcelt. Tad ķēniņa bardzība nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Tanī dienā ķēniņš Ahasverus deva ķēniņienei Esterei Amana, tā Jūdu ienaidnieka, namu, un Mardakajs nāca ķēniņa priekšā, jo Estere bija stāstījusi, kas viņš tai esot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Un ķēniņš novilka savu gredzenu, ko no Amana bija ņēmis, un to deva Mardakajam, un Estere iecēla Mardakaju pār Amana namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Un Estere runāja vēl ķēniņa priekšā un krita viņam pie kājām un raudāja un viņu lūdza, ka viņš atņemtu Amana, tā Agaģieša, ļaunumu un viņa nodomu, ko viņš izdomājis pret Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Tad ķēniņš Esterei piesniedza zelta scepteri, un Estere cēlās un stāvēja ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Un viņa sacīja: ja ķēniņam patīk, un ja es žēlastību esmu atradusi viņa priekšā, un ja tas pareizi ir ķēniņa priekšā, un es patīkama esmu viņa acīs, tad lai top rakstīts, ka Amana, Medatus, tā Agaģieša dēla, grāmatas un domas top iznīcinātas, ko viņš rakstījis, gribēdams Jūdus nomaitāt, kas ir visās ķēniņa valstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Jo kā es varētu redzēt to nelaimi, kas maniem ļaudīm uzies, un kā es varētu uzlūkot savu radu nomaitāšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Tad ķēniņš Ahasverus sacīja uz ķēniņieni Esteri un uz Jūdu Mardakaju: redzi, Amana namu es esmu devis Esterei, un viņš ir pakārts pie koka, tādēļ ka savu roku pielicis pie Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Tad nu jūs rakstiet par tiem Jūdiem, kā jums patīk ķēniņa vārdā un aizspiežat to ar ķēniņa gredzenu, jo to rakstu, kas ķēniņa vārdā rakstīts un ar ķēniņa zieģeli aizspiests, to nedrīkst pārgrozīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Tad ķēniņa rakstītāji tanī laikā tapa aicināti trešā mēnesī, tas ir Zivana mēnesis, divdesmit trešā dienā, un tapa rakstīts, tā kā Mardakajs pavēlēja, Jūdiem un valdniekiem un zemes valdītājiem un valsts lieliem kungiem, no Indijas līdz Moru zemei, simts divdesmit septiņās valstīs un uz ikvienu valsti viņas rakstā un uz ikvienu tautu viņas valodā, un Jūdiem pēc viņu rakstiem un pēc viņu valodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Un tas tapa rakstīts ķēniņa Ahasverus vārdā un aizspiests ar ķēniņa gredzenu. Un tās grāmatas tapa sūtītas caur skrējējiem, kas jāja uz čakliem zirgiem no ķēniņa staļļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Ķēniņš atļaujot Jūdiem visās pilsētās sapulcēties un savu dzīvību aizstāvēt, izdeldēt, nokaut un nomaitāt visu to ļaužu un valsts spēku, kas nāktu virsū, laupīt bērnus un sievas, un viņu mantu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Vienā dienā, pa visām ķēniņa Ahasverus valstīm, trīspadsmitā dienā divpadsmitā mēnesī, tas ir Adara mēnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Tais grāmatās bija rakstīts: ka pavēle dota pa visām valstīm, ka visiem ļaudīm nāk zināms, lai Jūdi ir gatavi uz to dienu atriebties pie saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Tad tie skrējēji izgāja jāšus ar ķēniņa čakliem zirgiem ātri steigdamies, pēc ķēniņa vārda, un tā pavēle tapa dota Sūsanas pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Un Mardakajs izgāja no ķēniņa ar pazilām un baltām ķēniņa drēbēm un ar lielu zelta kroni un ar uzvalku no dārga audekla un purpura, un Sūsanas pilsēta gavilēja un līksmojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Pie Jūdiem bija spožums un līksmība un prieks un gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Un visās valstīs un visās pilsētās, kur ķēniņa vārds un pavēle nāca zināmi, bija prieks un līksmība pie Jūdiem, dzīres un labas dienas, un daudz no pagāniem palika par Jūdiem, jo bailes no Jūdiem tiem bija uzkritušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Tad nu divpadsmitā mēnesī, tas ir Adara mēnesis, trīspadsmitā dienā, kad pēc ķēniņa vārda un pavēles notikās, tai dienā, kad Jūdu ienaidnieki cerēja tos pārvarēt, bet tas otrādi pārgriezās, ka Jūdi pārvarēja savus nīdētājus, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Tad Jūdi sapulcējās savās pilsētās pa visām ķēniņa Ahasverus valstīm, ka tie rokas pieliktu pie tiem, kas viņu nelaimi meklēja, un neviens nepastāvēja viņu priekšā, jo bailes no viņiem bija nākušas pār visiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Un visi lielkungi pa tām valstīm un valdnieki un zemes valdītāji un ķēniņa mantas uzraugi godāja Jūdus, jo bailes no Mardakaja pār tiem bija nākušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Jo Mardakajs bija liels ķēniņa namā, un viņa slava izgāja pa visām valstīm, jo tas vīrs Mardakajs tapa jo dienas jo augstāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Bet Jūdi kāvās pret visiem saviem ienaidniekiem, ar zobenu kaudami un nokaudami un nomaitādami, un darīja ar saviem nīdētājiem pēc sava prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Un Sūsanas pilī Jūdi ir nokāvuši un nomaitājuši piecsimt vīrus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Un Parzandatu un Dalvonu un Azvatu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Un Poratu un Adaliju un Aridatu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Un Parmastu un Arisaju un Aridaju un Vajezatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Amana, Medatus dēla, Jūdu ienaidnieka, desmit dēlus tie nokāva, bet tie savas rokas nepielika pie laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Tai dienā nokauto skaits tapa zināms ķēniņam Sūsanas pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Un ķēniņš sacīja uz ķēniņieni Esteri: Sūsanas pilī Jūdi ir nokāvuši un nomaitājuši piecsimt vīrus, un arī Amana desmit dēlus, ko tad tie nebūs darījuši citās ķēniņa valstīs? Un nu, kas ir tava lūgšana, tas tev taps dots; un kas vēl tava prasīšana, tai būs notikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Tad Estere sacīja: ja ķēniņam patīk, tad lai tie Jūdi, kas ir Sūsanā, arī rītu dara pēc šīs dienas atvēlēšanas, un lai Amana desmit dēli pie koka top pakārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Tad ķēniņš pavēlēja, lai to dara, un tā pavēle tapa dota Sūsanā, un tie pakāra Amana desmit dēlus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Un tie Jūdi, kas bija Sūsanā, sapulcējās četrpadsmitā dienā, Adara mēnesī, un nokāva Sūsanā trīssimt vīrus, bet tie savu roku nepielika pie laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Un tie citi Jūdi, kas bija ķēniņa valstīs, sapulcējās, ka tie savas dzīvības labad kautos un ka tiem miers būtu no saviem ienaidniekiem, un tie nokāva no saviem nīdētājiem septiņdesmit piecus tūkstošus, bet tie savas rokas nepielika pie laupījuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Tas notikās trīspadsmitā dienā, Adara mēnesī, un viņa četrpadsmitā dienā tie dusēja, un šo dienu iecēla par dzīru un līksmības dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Bet tie Jūdi, kas Sūsanā bija sapulcējušies trīspadsmitā un četrpadsmitā dienā, tie dusēja piecpadsmitā dienā un to iecēla par dzīru un līksmības dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Tāpēc tie Jūdi, kas ciemos un miestos dzīvoja, to četrpadsmito Adara mēneša dienu cēla par prieku un dzīru un svētku dienu, un kur cits citam sūtīja dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Un Mardakajs uzrakstīja šās lietas un sūtīja grāmatas pie visiem Jūdiem, kas bija visās ķēniņa Ahasverus valstīs tuvu un tālu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Tiem par stipru likumu iestādīdams, lai četrpadsmito un piecpadsmito Adara mēneša dienu ik gadus svētī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Tādēļ ka pa tām dienām Jūdi bija mieru dabūjuši no saviem ienaidniekiem, un tādēļ ka tai mēnesī viņu noskumšana bija pārvērtusies par prieku un viņu bēdas par labām dienām, lai tie tās dara par dzīru un līksmības dienām un sūta cits citam dāvinājumus un nabagiem dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Un Jūdi pieņēma, kā tie bija sākuši darīt, un ko Mardakajs tiem bija rakstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Proti ka Amans, Medatus dēls, tas Agaģietis, visu Jūdu ienaidnieks, pret Jūdiem bija nodomājis, tos izdeldēt, un ka viņš metis meslus, tas ir pur, tos biedināt un nomaitāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Bet kad (Estere) ķēniņa priekšā nākusi, tad šis caur grāmatām pavēlējis, ka viņa niknās domas, ko viņš par Jūdiem bija nodomājis, atgrieztos uz viņa galvu, un tie viņu ar viņa dēliem pakāruši pie koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Tādēļ tie šās dienas sauca purim, no tā meslu vārda „pur“. Tādēļ pēc visiem tiem vārdiem tai grāmatā, un ko tie paši bija redzējuši un kas tiem bija noticis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Jūdi to iecēla un nolika priekš sevis un saviem bērniem un visiem, kas viņiem pieķērās, ka to nepārkāptu, bet ka svētītu šās divas dienas pēc viņu rakstiem un pēc viņu nospriestā laika ikgadus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Ka šīs dienas taptu pieminētas un turētas pie visiem pēcnākamiem, ikvienā augumā, ikvienā radā, ikvienā valstī un ikvienā pilsētā, un ka tās purim dienas nepārkāptu Jūdu starpā un ka viņu piemiņa netaptu aizmirsta pie viņu bērnu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Un ķēniņiene Estere, Abikaīla meita, un Mardakajs, tas Jūds, rakstīja it tikuši(ar visu savu spēku un ietekmi) apstiprināt šo otru grāmatu par tiem purim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Un viņš sūtīja grāmatas visiem Jūdiem uz visām simts divdesmit septiņām ķēniņa Ahasverus valstīm ar miera un uzticības vārdiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Lai tie šīs purim dienas pastāvīgi svētī savā nospriestā laikā, tā kā Mardakajs, tas Jūds, un ķēniņiene Estere to bija iecēluši, un tā kā tie paši sev un savam dzimumam bija apstiprinājuši, līdz ar to gavēņu un gaudu iestādījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Un Estere apstiprināja ar savu pavēli šos purim likumus, un tie tapa ierakstīti grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Un ķēniņš Ahasverus uzlika klausību zemei un jūras salām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Bet visi viņa varas un viņa stipruma darbi un Mardakaja lielā paaugstināšana, ar ko ķēniņš viņu paaugstinājis, tas viss rakstīts Mēdiešu un Persiešu ķēniņu laiku grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Jo Jūds Mardakajs bija otrais pie ķēniņa Ahasverus un augsts pie Jūdiem un pieņēmīgs(patīkams) pie visiem saviem brāļiem; jo viņš meklēja labumu priekš savas tautas, un runāja par visa sava dzimuma labklāšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Viens vīrs bija Uca zemē, Ījabs vārdā, un tas bija sirdsskaidrs un taisns un dievbijīgs un sargājās no ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Un tam dzima septiņi dēli un trīs meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Un viņam lopu bija septiņtūkstoš avis un trīstūkstoš kamieļi un piecsimt jūgi vēršu un piecsimt ēzeļu mātes un ļoti liela saime; un viņš bija lielāks nekā visi austruma ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Un viņa dēli gāja un taisīja dzīres ikviena namā savā dienā, un sūtīja un aicināja savas trīs māsas, līdz ar tiem ēst un dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Kad nu tās dzīru dienas bija apkārt, tad Ījabs sūtīja (atgādinājumu šķīstīties) un tos svētīja un cēlās no rīta agri un upurēja dedzināmos upurus pēc visu viņu skaita, jo Ījabs sacīja: Varbūt, ka mani dēli apgrēkojušies un Dievam savā sirdī atsacījuši. Tā Ījabs darīja ikdienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Un notikās kādā dienā, kad Dieva bērni nāca stāties Tā Kunga priekšā, tad sātans arīdzan atnāca viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Un Tas Kungs sacīja uz sātanu: no kurienes tu nāci? Un sātans Tam Kungam atbildēja un sacīja: esmu gājis apkārt pa pasauli un to esmu izstaigājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Un Tas Kungs sacīja uz sātanu: vai tu neesi licis vērā Manu kalpu Ījabu? Jo neviena tāda nav pasaulē kā viņš, sirdsskaidrs, taisns un dievbijīgs vīrs, un kas tā sargās no ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Tad sātans atbildēja Tam Kungam un sacīja: vai tad Ījabs velti Dievu bīstas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Vai Tu viņu un viņa namu un visu, kas tam pieder, neesi visapkārt aptaisījis tā kā ar sētu? Viņa roku darbu Tu esi svētījis, un viņa lopi ir vairojušies zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Bet nu izstiep jel Savu roku un aizskar, kas tam pieder, tiešām viņš Tev vaigā atsacīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Un Tas Kungs sacīja uz sātanu: redzi, viss, kas tam pieder, lai ir tavā rokā, tikai pie viņa paša nepieliec savu roku. Un sātans aizgāja no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Kad nu kādā dienā viņa dēli un meitas ēda un vīnu dzēra sava pirmdzimušā brāļa namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Tad vēstnesis nāca pie Ījaba un sacīja: vērši ara un ēzeļu mātes pie tiem bija klāt ganos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Tad Arābi ielauzās un tos paņēma un kāva tos puišus ar zobena asmeni, un es viens pats tikai esmu izbēdzis, tev to stāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Kamēr tas vēl runāja, cits atnāca un sacīja: Dieva uguns krita no debess un iededzināja avis un puišus un tos sadedzināja pavisam, un es viens pats tikai esmu izbēdzis, tev to stāstīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Kamēr tas vēl runāja, cits atnāca un sacīja: Kaldeji taisījās trijos pulkos un uzbruka kamieļiem un tos paņēma un kāva tos puišus ar zobena asmeni, un es viens pats tikai esmu izbēdzis, tev to stāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Kamēr tas vēl runāja, cits atnāca un sacīja: tavi dēli un tavas meitas ēda un dzēra vīnu sava pirmdzimušā brāļa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Un redzi, briesmīga vētra nāca no tuksneša puses un aizņēma tos četrus nama stūrus, ka tas sagruva uz tiem jaunekļiem, un tie nomira, un es viens pats tikai esmu izbēdzis, tev to stāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Tad Ījabs cēlās un saplēsa savus svārkus un apcirpa savu galvu un metās pie zemes un pielūdza');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Un sacīja: kails esmu nācis no savas mātes miesām un kails atkal aiziešu. Tas Kungs ir devis, Tas Kungs ir ņēmis, Tā Kunga vārds lai ir slavēts!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Visās šinīs lietās Ījabs neapgrēkojās un neturējās aplam pret Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Un notikās atkal kādā dienā, kad Dieva bērni nāca, stāties Tā Kunga priekšā, tad arī sātans atnāca viņu starpā, stāties Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Un Tas Kungs sacīja uz sātanu: no kurienes tu nāci? Un sātans Tam Kungam atbildēja un sacīja: esmu gājis apkārt pa pasauli un to esmu izstaigājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Tad Tas Kungs sacīja uz sātanu: vai tu neesi licis vērā Manu kalpu Ījabu? Jo neviena tāda nav pasaulē kā viņš, sirdsskaidrs un taisns, dievbijīgs vīrs, un kas tā sargās no ļauna; un viņš vēl turas stipri pie savas sirdsskaidrības, bet tu Mani esi skubinājis pret viņu, viņu velti samaitāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Tad sātans Tam Kungam atbildēja un sacīja: ādu par ādu; un visu, kas cilvēkam pieder, to viņš dod par savu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Bet izstiep jel Savu roku un aizskar viņa kaulus un viņa miesas; tiešām viņš Tev vaigā atsacīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Un Tas Kungs sacīja uz sātanu: redzi, lai viņš ir tavā rokā, bet taupi viņa dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Tad sātans aizgāja no Tā Kunga un sita Ījabu ar nikniem augoņiem no pēdas līdz galvas virsai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Un viņš ņēma poda gabalu, ar to kasīties, un bija apsēdies pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Tad viņa sieva uz viņu sacīja: vai tu vēl stipri turies pie savas sirds skaidrības? Atsaki Dievam un mirsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Bet viņš uz to sacīja: tu runā kā daža neprātīga runā; vai labumu gan saņemsim no Dieva, bet ļaunumu vis nesaņemsim? Visās šinīs lietās Ījabs neapgrēkojās ar savām lūpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Kad nu Ījaba trīs draugi dzirdēja visu šo nelaimi, kas viņam bija uzgājusi, tad tie nāca ikkatrs no savas vietas, Elifas no Temanas un Bildads no Šuhas un Cofars no Naēmas; jo tie bija sarunājušies, nākt un viņu žēlot un viņu iepriecināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Un tie pacēla savas acis no tālienes un viņu nepazina; tad tie pacēla savu balsi un raudāja, un ikviens no tiem saplēsa savus svārkus un kaisīja pīšļus uz savām galvām pret debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Tā tie pie viņa sēdēja zemē septiņas dienas un septiņas naktis, un neviens uz to nerunāja ne vārda; jo tie redzēja, ka tās sāpes bija ļoti lielas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Pēc tam Ījabs atdarīja savu muti un nolādēja savu dienu. Un Ījabs iesāka un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Tā diena lai pazūd, kur esmu dzimis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Un tā nakts, kur sacīja: puisītis ieņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Šī diena lai paliek tumša, lai Dievs no augšienes pēc viņas nevaicā, un spožums pār viņu lai nespīd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Tumsa un nāves ēna lai viņu aizņem, padebeši lai viņu apklāj un kas vien dienu aptumšo, lai viņu biedē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Šo nakti lai tumsa apņem, ka tā starp gada dienām nepriecājās, lai viņa nenāk mēnešu skaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Redzi, šī nakts lai paliek neauglīga, ka tanī nenotiek gavilēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Lai dienu lādētāji to nolād, tie, kas māk Levijatanu uzrīdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Lai viņas rīta zvaigznes top aptumšotas, lai viņa gaida uz gaismu, bet nekā, un lai viņa neredz ausekļa spīdumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Tāpēc ka tā manām miesām durvis nav aizslēgusi, un bēdas nav noslēpusi priekš manām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Kāpēc es neesmu nomiris mātes miesās un bojā gājis, kad no miesām iznācu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Kāpēc esmu likts klēpī un kāpēc pie krūtīm, ka man bija zīst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Jo tad es gulētu un būtu klusu, tad es gulētu, un man būtu dusa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Līdz ar ķēniņiem un runas kungiem virs zemes, kas sev kapu vietas uztaisījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Vai ar lieliem kungiem, kam zelts bijis, kas savus namus ar sudrabu pildījuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Vai kā norakts nelaikā dzimis bērns es nebūtu nekas, tā kā bērniņi, kas nav redzējuši gaismas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tur bezdievīgie stājās no trakošanas, un tur dus, kam spēks noguris;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Tur cietumnieki visi līdzi ir mierā, tie nedzird dzinēja balsi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Tur ir mazs un liels, un kalps ir vaļā no sava kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Kāpēc (Dievs) dod bēdīgam gaismu un dzīvību tiem, kam noskumusi sirds,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Kas pēc nāves ilgojās, bet tā nenāk, un rok pēc tās vairāk nekā pēc mantām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Kas priecātos un gavilētu, kas līksmotos, kad kapu atrastu -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Vīram, kam ceļš ir apslēpts, un ko Dievs visapkārt apspiedis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Jo maizes vietā man ir nopūtas, un mana kaukšana izgāzās kā ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Jo briesmas, ko bijos, man uzgājušas, un no kā man bija bail, tas man uznācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Man nav miera, man nav dusas, es nedabūju atpūsties, un bēdas nāk uz bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Tad Elifas no Temanas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Vai ļaunā ņemsi, kad tev kādu vārdu teiksim? Bet, - kas varētu klusu ciest?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Redzi, dažu labu tu esi pamācījis un nogurušas rokas stiprinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tavi vārdi kritušu ir uzcēluši, un drebošus ceļus tu esi spēcinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Bet kad tas nu nāk uz tevi, tad tu nogursti, un kad tas tevi aizņem, tad tu iztrūcinājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Vai uz tavu Dieva bijāšanu nebija tava cerība, vai tu nepaļāvies uz saviem nenoziedzīgiem ceļiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Piemini jel, kurš nenoziedzīgs būdams ir bojā gājis, un kur taisni ir izdeldēti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Tā es gan esmu redzējis: kas netaisnību ar un varas darbu sēj, tie to pašu pļauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Caur Dieva dvašu tie iet bojā, un no viņa bardzības gara tie iznīkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Lauvas rūkšana un liela lauvas balss un jaunu lauvu zobi ir izlauzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Vecais lauva iet bojā, jo laupījuma nav, un vecās lauvas bērni izklīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Un slepeni pie manis nācis vārds, un mana auss kādu skaņu no tā ir saņēmusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Nakts parādīšanu domās, kad ciets miegs cilvēkiem uziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Tad bailes man uznāca un šaušalas un iztrūcināja visus manus kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Un viens gars man gāja garām, ka visi manas miesas mati cēlās stāvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Viņš stāvēja, bet es nepazinu viņa ģīmi, tēls bija priekš manām acīm un es dzirdēju palēnu balsi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Vai cilvēks taisns Dieva priekšā, vai vīrs šķīsts priekš sava Radītāja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Redzi, Saviem kalpiem Viņš neuztic, un Saviem eņģeļiem Viņš pierāda vainu,-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Cik vairāk tiem, kas mālu namos dzīvo, kas ceļas no pīšļiem, kas nīcīgi kā kodi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Starp rīta un vakara laiku tie top sašķelti, ka neviens to nenomana, viņi iet pavisam bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Vai viņu gods viņiem netop atņemts? Tie nomirst, bet ne gudrībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Sauc jel, vai būs kāds, kas tev atbild? Un pie kura no svētiem tu gribi griezties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Jo sirdēsti nokauj ģeķi, un pārsteigšanās nonāvē nejēgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Es redzēju ģeķi iesakņotu, bet piepeši nolādēju viņa namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Viņa bērni palika tālu no pestīšanas un tapa satriekti vārtos, un nebija glābēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Viņa pļāvumu ēda izsalkuši, un pat no ērkšķu vidus to lasīja, un laupītāji aprija viņa padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Jo no pīšļiem neizaug nelaime, un no zemes neizplaukst grūtums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Bet cilvēks uz grūtumu piedzimst, kā dzirksteles no oglēm paceļas skraidīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Bet es meklētu to stipro Dievu un Dievam pavēlētu savas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Viņš dara lielas lietas, kas nav izprotamas, un brīnumus, ko nevar skaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Viņš dod lietu virs zemes un ūdenim liek nākt pār druvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Zemos Viņš liek augstā vietā, un bēdīgie tiek celti laimē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Viņš iznīcina viltniekiem padomu, ka viņu rokas nekā derīga nevar padarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Viņš satver gudros viņu viltībā, un netikliem padoms ātri krīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Pa dienu tie skraida tumsā, un dienas vidū tie grābstās kā naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Bet Viņš izglābj no zobena, no viņu mutes, un to bēdīgo no varenā rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Tā nabagam nāk cerība, bet blēdībai būs turēt muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Redzi, svētīgs tas cilvēks, ko Dievs pārmāca, tāpēc neņem par ļaunu tā Visuvarenā pārmācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Jo Viņš ievaino un atkal sasien, Viņš sadauza, un Viņa roka dziedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Sešās bēdās Viņš tevi izglābs, un septītā tevi ļaunums neaizskars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Bada laikā Viņš tevi izpestīs no nāves, un kara laikā no zobena cirtieniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'No ļaunām mēlēm tu tapsi paglābts, un nebīsies no posta, kad tas nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Postīšanā un badā tu smiesies, un no zemes zvēriem tu nebīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Jo tev būs derība ar akmeņiem tīrumā, un zvēri laukā turēs ar tevi mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Un tu samanīsi, ka tavs dzīvoklis mierā, un apraudzīsi savu namu un trūkuma nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Un tu samanīsi, ka tava dzimuma būs daudz, un tavi pēcnākamie kā zāle virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Vecumā tu iesi kapā, tā kā kūlīšus ieved savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Redzi, to mēs esam izmeklējuši, tā tas ir; klausi tu un ņem to labi vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Kaut manas vaimanas ar svaru svērtu un turpretī manas bēdas svaru kausā liktu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Jo tās tagad ir grūtākas nekā jūras smiltis, tāpēc mana mute muld.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Jo tā Visuvarenā bultas ir iekš manis, mans gars dzer viņu ugunis, Dieva briesmas karo pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Vai gan meža ēzelis zviedz, kad tam ir zāle? Vai vērsis mauj, kad tam sava barība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Vai jēlu var ēst bez sāls? Vai ir gardums olas baltumā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Ko mana dvēsele negribēja aizskart, tā nu ir mana bēdu barība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Kaut mana lūgšana notiktu, un Dievs man dotu, ko es gaidu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Kaut Dievs mani sadauzītu, kaut tas Savu roku izstieptu un mani satriektu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Tas man vēl būtu par prieku, un es vēl savās nežēlīgās sāpēs būtu līksms, ka neesmu aizliedzis tā Svētā vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Kāds ir mans spēks, ka es vēl varētu cerēt, un kāds ir mans gals, ka manai dvēselei būtu jāpaciešās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Vai mans spēks ir akmeņu spēks, vai mana miesa ir varš?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Vai man palīga netrūkst pavisam, un vai man padoms nav visai pagalam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Izsamisušam žēlastības vajag no sava drauga, citādi tas arī tā Visuvarenā bijāšanu atmet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mani brāļi mani pieviļ kā strauts, kā strauta ūdeņi, kas notek;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Sajukuši tie bija ar ledu, un sasniguši ar sniegu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Tai laikā, kad karstums tos spiež, tad tie izsīkst, kad karsts metās, tad tie iznīkst no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Viņu ceļi griežas sānis, tie iet uz tuksnesi un izzūd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Uz tiem skatās ceļa ļaudis no Temas un cer Šebas ceļa gājēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Tie paliek kaunā ar tādu cerību un nosarkst, tur nonākdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Tiešām nu jūs neesat it nekas, redzat briesmas un iztrūcinājāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Vai es jeb kad sacīju: nesiet man un dodiet man dāvanas no sava padoma?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Jeb glābiet mani no ienaidnieka rokas un pestījiet mani no varas darītāju rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Mācat mani, es cietīšu klusu, un pierādiet man, kur es maldījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Cik spēcīgi ir taisni vārdi, bet ko norāj jūsu rāšana;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Vai jūs esat apņēmušies vārdus aprāt? Vējam pieder izsamisuša vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Vai arī bāriņam gribat valgus mest un bedri rakt savam tuvākam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Bet nu, lūdzami, uzlūkojiet mani, jums acīs tiešām es nemelošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Atbildiet jel, lai nenotiek netaisnība, atbildiet, jo mana taisnība vēl stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Vai tad uz manas mēles būs netaisnība, vai mana mute nemanīs, kas ir blēdība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Vai cilvēkam nav karš virs zemes, un vai viņa dienas nav kā algādža dienas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Tā kā kalps ilgojās pēc ēnas un kā algādzis gaida uz savu algu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Tāpat man nākuši daudz bēdīgi mēneši, un grūtas naktis man ir piešķirtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Kad apguļos, tad es saku: kad atkal celšos? un vakars vilcinājās, un es apnīkstu mētāties gultā līdz gaismai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mana miesa ir apsegta ar tārpiem un vātīm, mana āda sadzīst un čūlo atkal.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Manas dienas ir ātrākas nekā vēvera (audēja) spole un beidzās bez nekādas cerības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Piemini, ka mana dzīvība ir vējš un mana acs labuma vairs neredzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Acs, kas nu mani redz, manis vairs neredzēs. Tavas acis uz mani skatās, un es vairs neesmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Mākonis iznīkst un aiziet, - tāpat kas kapā nogrimst, nenāks atkal augšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Viņš neatgriezīsies atkal savā namā, un viņa vieta viņu vairs nepazīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Tā tad es savu muti neturēšu, es runāšu savās sirds bēdās, es žēlošos savā sirdsrūgtumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Vai tad es esmu kā jūra, vai kā liela jūras zivs, ka tu ap mani noliec vakti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kad es saku: mana gulta man iepriecinās, manas cisas atvieglinās manas vaimanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Tad Tu mani izbiedē ar sapņiem, un caur parādīšanām Tu mani iztrūcini,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Tā ka mana dvēsele vēlās būt nožņaugta, labāki mirt nekā tā izģinst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Es esmu apnicis, man netīk mūžam dzīvot; atstājies jel no manis, jo manas dienas ir kā nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Kas ir cilvēks, ka Tu viņu tik augsti turi un ka Tu viņu lieci vērā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Un viņu piemeklē ik rītu, viņu pārbaudi ik acumirkli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Ka Tu nemaz no manis neatstājies un mani nepameti, ne siekalas ierīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Ja esmu grēkojis, ko es Tev darīšu, Tu cilvēku sargs? Kāpēc Tu mani esi licis Sev par mērķi, ka es sev pašam palicis par nastu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Un kāpēc Tu manus pārkāpumus nepiedod un neatņem manu noziegumu? Jo nu es apgulšos pīšļos, un kad Tu mani meklēsi, tad manis vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Tad Bildads no Šuhas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Cik ilgi tu tā gribi runāt? tavas mutes vārdi ir kā stiprs vējš, kas greznojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Vai Dievs pārgrozītu tiesu, un tas Visuvarenais pārgrozītu taisnību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Kad tavi bērni pret Viņu grēkojuši, tad Viņš tos arī nodevis viņu grēku varā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Bet ja tu pie laika to stipro Dievu meklēsi un no tā Visuvarenā žēlastības lūgsies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Ja tu šķīsts būsi un taisns, tad Viņš tevi gan uzlūkos un atkal uztaisīs tavas taisnības dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Un ja tu iesākumā biji sīks, pēcgalā tu būsi ļoti liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Jo vaicā jel tiem senajiem, un liec vērā, ko viņu tēvi piedzīvojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Jo mēs esam vakarēji un nezinām nenieka; jo mūsu dienas ir kā ēna virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Viņi tevi gan mācīs un tev sacīs un no savas sirds runās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Vai ašķi aug bez dūņām, vai niedres izaug bez ūdens?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Vēl zaļo, netiek plūktas, bet nokalst ātrāki nekā visa cita zāle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Tā iet visiem, kas Dievu aizmirst, un blēža cerība iet bojā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Viņa drošums iznīkst, un viņa patvērums ir kā zirnekļa tīkls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Viņš atslienas pie sava nama, bet tas nestāv, viņš gan pie tā turas, bet tas nepastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Gan viņš ir zaļš, saulei spīdot, un viņa zari izplešas viņa dārzā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Viņa saknes vijās ap akmeņiem un ķērās pie mūra ēkas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Kad viņš to izdeldē no viņa vietas, tad šī viņu aizliedz: Es tevi neesmu redzējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Redzi, tāds ir viņa ceļa prieks, un no pīšļiem izaug atkal citi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Redzi, Dievs neatmet sirdsskaidro, un neņem bezdievīgo pie rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Kamēr Viņš tavu muti piepildīs ar smiešanos un tavas lūpas ar gavilēšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Tavi ienaidnieki taps apģērbti ar kaunu, un bezdievīgo dzīvokļa vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Patiesi, es zinu, ka tas tā ir: jo kā cilvēks varētu taisns būt tā stiprā Dieva priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Ja viņš grib ar To tiesāties, tad tas Viņam uz tūkstošiem ne vārda nevar atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Viņš ir gudrs no sirds un stiprs no spēka; kas pret Viņu var tiepties un pastāvēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Viņš pārceļ kalnus, un tie nemana, ka Viņš tos apgāž Savā dusmībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Viņš kustina zemi no viņas vietas, ka viņas pamati trīc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Viņš pavēl saulei, tad tā neuzlec, Viņš aizspiež zieģeli priekš zvaigznēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Viņš viens izplata debesis un staigā pa jūras augstumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Viņš radījis tos vāģus(Lāci), Orijonu un Sietiņu un tās zvaigznes pret dienasvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Viņš dara lielas lietas, ko nevar izprast, un brīnumus, ko nevar izskaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Redzi, Viņš man iet secen, ka To neredzu, Viņš staigā garām, ka To nesamanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Redzi, kad Viņš aizgrābj, kas Viņu kavēs, kas uz Viņu sacīs: ko Tu dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Dievs neaptur Savas dusmas, apakš Viņa tā varenā palīgi lokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Kā tad nu es Viņam varētu atbildēt un atrast vārdus pret Viņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Jo, kad es arī taisns būtu, taču es nevaru atbildēt, bet man būtu savs soģis jāpielūdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Jebšu es sauktu, un Viņš man atbildētu, taču es nevarētu ticēt, ka Viņš klausīšot manu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Jo Viņš sagrābtu mani tā kā ar vētru un vairotu manas nepelnītas vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Viņš manam garam neļautu atspirgties, bet mani pieēdinātu ar rūgtumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Ja spēka vajag, redzi, Viņš ir varens, un ja tiesā jānāk, kas Viņu sauks priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Ja es būtu taisns, tad mana mute mani pazudinātu, ja es būtu skaidrs, taču Viņš man pierādītu vainu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Es esmu nenoziedzīgs, es savu dvēseli nežēloju, man riebj dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Viena alga! tādēļ es saku: Viņš izdeldē nenoziedzīgu un bezdievīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Kad Viņa rīkste piepeši nonāvē, tad Viņš smejas par nenoziedzīgo izsamišanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Zeme top dota bezdievīgā rokā, Viņš apklāj viņas tiesnešu vaigus. Ja tas tā nav, kas tad to dara?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Manas dienas jo ātras bijušas nekā skrējējs, tās ir aiztecējušas un labuma nav redzējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Tās aizgājušas kā vieglas laivas, kā ērglis, kas šaujas uz barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Kad es domāju: es gribu aizmirst savas vaimanas un pamest savu skumību un atspirgties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Tad es iztrūkstos par visām savām sāpēm; es zinu, ka Tu mani neturi par nenoziedzīgu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Ja man būs vainīgam būt, - kāpēc tad man velti nodarboties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Jebšu es mazgātos sniegā un šķīstītu savas rokas sārmā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Taču Tu mani iemērktu bedrē, tā ka manas drēbes no manis kaunētos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Jo Viņš nav tāds vīrs kā es, kam es varētu atbildēt, ka mēs kopā varētu iet priekš tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Nav mūsu starpā izšķīrēja, kas savu roku varētu likt uz mums abiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Kad Viņš atņemtu Savu rīksti no manis un Viņa biedēklis mani neiztrūcinātu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Tad es runātu un no Viņa nebītos; jo tā tas ar mani vis nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Mana dvēsele apnikusi dzīvot; savas vaimanas es neaizturēšu, es runāšu savas dvēseles rūgtumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Es sacīšu uz Dievu: nepazudini mani, dod man zināt, kāpēc Tu ar mani tiesājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Vai Tev patīk varas darbu darīt, atmest Savas rokas darbu un bezdievīgo padomam dot spožumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Vai Tev ir miesīgas acis, vai Tu redzi, kā cilvēks redz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Vai Tavas dienas ir kā cilvēka dienas un Tavi gadi kā kāda vīra dienas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Ka Tu manu noziegumu meklē un vaicā pēc maniem grēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Lai gan Tu zini, ka es bezdievīgs neesmu, un ka neviena nav, kas no Tavas rokas izglābj,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tavas rokas mani sataisījušas un darījušas, kāds es viscaur esmu, un tomēr Tu mani aprij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Piemini jel, ka Tu mani kā mālu esi taisījis, vai Tu mani atkal darīsi par pīšļiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Vai Tu mani neesi izlējis kā pienu, un man licis sarikt kā sieram?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Ar ādu un miesu Tu mani esi apģērbis, ar kauliem un dzīslām mani salaidis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Dzīvību un žēlastību Tu man esi devis, un Tavas acis sargāja manu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Un to Tu Savā sirdī esi slēpis, es zinu, ka tas Tev prātā stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Kad es grēkoju, tad Tu to gribēji pieminēt un mani neatlaist no maniem noziegumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Ja es bezdievīgs biju, ak vai, man! Bet ja biju taisns, taču man nebija galvu pacelt, ar lielu kaunu ieraugot savas bēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Un ja es galvu paceļu, kā lauva Tu mani gribēji vajāt, un arvien atkal brīnišķi pret mani rādīties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Pret mani vest Savus lieciniekus citus par citiem un vairot Savu dusmību pret mani, celt pret mani vienu kara spēku pēc otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Kāpēc tad Tu mani esi izvedis no mātes miesām? Kaut es būtu nomiris un neviena acs mani nebūtu redzējusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Tad es būtu kā kas mūžam nav bijis, no mātes miesām es būtu kapā guldīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Vai nav īss mans mūžs? Mities jel, atstājies no manis, ka es maķenīt atspirgstos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Pirms es noeju, un vairs neatgriežos, uz tumsības un nāves ēnas zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Uz zemi, kur bieza tumsība kā pusnakts, kur nāves ēna un nekāda skaidrība, un kur gaisma ir kā tumsība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Tad Cofars no Naēmas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Vai uz tik daudz vārdiem nebūs atbildēt, vai mutīgam cilvēkam lai paliek taisnība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Vai tad citiem uz tavām blēņām būs klusu ciest, ka tu mēdi, un neviens tevi neapkauno,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Un saki: mana mācība ir skaidra, un es esmu šķīsts priekš Tavām acīm, (ak Dievs!)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Bet tiešām, kaut Dievs runātu un atdarītu Savas lūpas pret tevi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Un tev stāstītu to apslēpto gudrību, kas ir gudrība pār gudrību, tad tu zinātu, ka Dievs nemaz vēl visus tavus noziegumus nepiemin.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Vai tu Dieva apslēptos padomus vari atrast, vai attapt tā Visuvarenā pilnību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Viņa ir augstāka nekā debesis, - ko tu vari darīt? Dziļāka nekā elle, - ko tu vari zināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Garāka nekā zeme savā mērā, un platāka nekā jūra!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Kad Viņš uzbrūk un gūsta, priekš tiesas stāda, kas Viņam to liegs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Jo Viņš pazīst neliešus, Viņš redz negantību, vai vērā nelikdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Bet pirms ģeķis nāk pie gudrības, tad meža lops paliek par cilvēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Ja tu pacelsi savu sirdi un izplētīsi savas rokas uz Viņu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Ja tu to ļaunumu, kas tavā rokā, tālu atmetīsi, un netaisnībai neļausi mājot savā dzīvoklī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Tad tu savu vaigu varēsi pacelt bez vainas un varēsi pastāvēt un nebūs jābīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Tad tu bēdas varēsi aizmirst, un tās tā pieminēt, kā ūdeni, kas aizskrien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Un tavs mūžs stāvēs spožāks nekā dienas vidus, un pat tumsa būs kā rīta gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Un tu varēsi ticēt, ka vēl ir cerība, un redzēsi, ka vari mierā dusēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Un varēsi apgulties, un neviens tevi neizbiedēs, un daudzi vēl tevi godinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Bet bezdievīgo acis izīgst un viņu patvērums iet bojā, un viņu cerība iznīks kā pēdīgā dvaša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Bet Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Tas ir tiesa, jūs esat ļaudis un ar jums gudrība izmirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Man arīdzan ir sirds, tāpat kā jums, jūs man priekšā neesat, un kas tad to gudrību nezin?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Es pat savam tuvākam esmu par apsmieklu, es, kas Dievu piesaucis un no Viņa esmu paklausīts, par apsmieklu tas taisnais un sirdsskaidrais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Kauns nelaimei pēc laimīga domām; tas gaida to, kam kāja slīd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Postītāju dzīvokļiem labi klājās, un mierā paliek bezdievīgi un kam Dievs ir dūrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Un tiešām, vaicā jel lopiem, tie tev to mācīs, un putniem apakš debess, tie tev to stāstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Jeb runā ar zemi, tā tev mācīs, un jūras zivis tev to izteiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kas neatzīst pie visa tā, ka Tā Kunga roka to darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Viņa rokā ir visu dzīvo dvēsele un visu cilvēku miesu gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Vai auss nepārbauda vārdus, kā mute bauda barību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Pie veciem ir gudrība un ilgs mūžs dod saprašanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Pie Viņa ir gudrība un spēks, Viņam ir padoms un prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Redzi, Viņš nolauž, un neviens nevar uztaisīt. Viņš ko aizslēdz, un neviens nevar atvērt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Redzi, kad Viņš ūdeņus satur, tad tie izsīkst, un kad Viņš tos laiž vaļā, tad tie zemi griež apkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Pie Viņa ir spēks un pastāvība, Viņa priekšā ir, kas maldās un kas maldina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Viņš ved padomu devējus par laupījumu, un tiesnešus Viņš dara par ģeķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Ķēniņu saites Viņš sarauj un apjož pašiem gurnus ar saitēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Viņš ved cienīgus par laupījumu, un apgāž varenus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Viņš atņem runātājiem valodu un noņem vecajiem prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Viņš izlej negodu pār lieliem kungiem, un vareniem Viņš jostu raisa vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Viņš atklāj dziļumus tumsai, un nāves ēnu Viņš ved gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Viņš vairo ļaudis un tos izdeldē, Viņš ceļ spēkā tautas un tās izklīdina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Viņš ļaužu virsniekiem virs zemes atņem sirdi un tos maldina tuksnesī, kur ceļa nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Tie grābsta tā kā tumsā, kur gaismas nav, un Viņš tiem liek maldīties kā piedzērušiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Redzi, to visu mana acs redzējusi, mana auss dzirdējusi un to likusi vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Ko jūs protat, to es arīdzan protu, jūs man neesat priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Bet es gribu runāt uz to Visuvareno, un man gribās aizbildināties tā stiprā Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Jo tiešām, jūs esat melu runātāji, jūs visi esat nelietīgi dziednieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Kaut jūs pavisam klusu būtu, tas jums būtu par gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Klausiet jel manu aizbildināšanos, un ņemiet vērā manas mutes tiesāšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Vai gribat netaisnību runāt Dieva labad un Viņa labad izteikt viltību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Vai Viņu gribat aizbildināt un Dievam būt pārstāvētāji?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Vai būs labi, kad Viņš jūs meklēs, vai Viņu pievilsiet, kā cilvēku pieviļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Sodīt Viņš jūs sodīs, ja jūs slepeni vaigu uzlūkojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Vai Viņa augstība jūs neiztrūcinās un bailes no Viņa jums neuzkritīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Jūsu mācības būs kā pelni, un jūsu augstie vārdi kā mālu kopas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Palieciet man klusu, un es runāšu, lai man notiek, kas notikdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Kāpēc man savu miesu bija zobos ņemt, un savu dvēseli likt savā rokā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Redzi, jebšu Viņš mani nokaus, taču es uz Viņu gribu cerēt, es tikai savus ceļus gribu aizbildināt Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Jau tas man būs par pestīšanu, ka viltnieks Viņa priekšā nenāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Klausāties, klausāties manus vārdus, un mana valoda lai skan jūsu ausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Redzat jel, es esmu gatavs uz tiesu, es zinu, ka man paliks taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kas ar mani varētu tiesāties? Patiesi tad es ciestu klusu un mirtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Divas lietas tikai man nedari, tad es neapslēpšos Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Lai Tava roka paliek tālu no manis, un Tava briesmība lai mani neizbiedē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Tad sauc, un es atbildēšu, vai es runāšu, un Tu atbildi man.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Cik man ir noziegumu un grēku? Dari man zināmus manus grēkus un manus pārkāpumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Kāpēc Tu apslēpi Savu vaigu un mani turi par Savu ienaidnieku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Vai Tu biedināsi šaubīgu lapu un vajāsi izkaltušus rugājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Jo Tu man nospriedi rūgtumus un lieci manīt manas jaunības noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Tu lieci manas kājas siekstā un glūni uz visiem maniem ceļiem un ieslēdzi manas pēdas aplokā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Un tomēr šis iznīkst kā trūdi, tā kā drēbe, ko kodes saēd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Cilvēks, no sievas dzimis, dzīvo īsu laiku un ir pilns grūtuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Viņš izaug kā puķe un novīst, viņš bēg kā ēna un nepastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Un par tādu Tu atveri savas acis un vedi mani Tavas tiesas priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Kas dos šķīstu no nešķīstiem? Nav neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Viņa dienas jau ir nospriestas, viņa mēnešu pulks stāv pie Tevis, Tu tam esi licis robežu, to viņš nepārkāps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Griez nost Savas acis no tā, ka atpūšās, ka tas priecājās kā algādzis, savu dienu nobeidzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Jo kokam, kad top nocirsts, ir cerība, ka atkal atjaunosies, un viņa atvases nemitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Jebšu viņa sakne zemē kļūst paveca, un viņa celms pīšļos mirst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Taču no ūdens smaržas viņš atkal izplaukst un dabū zarus kā iedēstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Bet vīrs mirst, un ir pagalam, cilvēks izlaiž dvēseli, - un kur nu ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Ūdeņi iztek no ezera, un upe izsīkst un izžūst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Tāpat cilvēks apgūlās un necēlās vairs; kamēr debesis zūd, tie neuzmodīsies, un netaps traucēti no sava miega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ak, kaut Tu mani apslēptu kapā un mani apsegtu, kamēr Tava dusmība novērstos; kaut Tu man galu nolemtu un tad mani pieminētu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Kad vīrs mirst, vai tas atkal dzīvos? Es gaidītu visu savu kalpošanas laiku, kamēr nāktu mana atsvabināšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Tu sauktu un es Tev atbildētu; Tu ilgotos pēc Sava roku darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Bet nu Tu skaiti manus soļus un neapstājies manu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Mana pārkāpšana ir noglabāta un apzieģelēta, un Tu pielieci vēl klāt pie mana nozieguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Tiešām, kalns sagrūst, kad tas krīt, un klints aizceļas no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Ūdens izgrauž akmeņus, un viņa plūdi aizpludina zemes pīšļus, un cilvēka cerībai Tu lieci zust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Tu viņu pārvari pavisam un viņš aiziet; Tu pārvērti viņa ģīmi, un tā Tu viņu aizdzeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Vai viņa bērni tiek godā, viņš to nezin, vai tie ir trūkumā, ir to viņš no tiem nesamana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Viņa paša miesās ir sāpes, un viņa paša dvēselei jāžēlojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Tad Elifas no Temanas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Vai tad gudram vīram būs runāt tukšas domas un savu sirdi pildīt ar vēju?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Pārmācīt ar vārdiem, kas nepieklājās, un ar valodu, kur labums neatlec?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Tiešām, tu iznīcini Dieva bijāšanu un nicini pielūgšanu Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Jo tava mute parāda tavu noziegumu, un tu esi uzņēmies runāt, kā gudrinieki runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Tava mute tevi pazudina, un ne es; tavas lūpas pret tevi dod liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Vai tu esi tas pirmais cilvēks piedzimis, vai tu esi dzemdināts, pirms kalni bija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Vai tu esi dzirdējis Dieva apslēpto padomu, vai tu gudrību esi iezīdis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Ko tu zini, ko mēs nezinātu, ko tu proti, un mēs to neprastu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Arī mūsu starpā ir sirmi un veci, kas ilgāki dzīvojuši, nekā tavs tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Vai Dieva iepriecināšanas priekš tevis mazas, un vārds, laipnīgi uz tevi runāts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Kāpēc tava sirds tevi tā apmāna, kāpēc tavas acis tā spulgo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Ka tavas dusmas ceļas pret Dievu un izverd tādu valodu no tavas mutes?!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kas ir cilvēks, ka tas būtu šķīsts, un ka būtu taisns, kas no sievas dzimis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Redzi, Saviem svētiem Viņš neuztic un debesis nav šķīstas priekš Viņa acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Ne nu vēl tas negantais un samaitātais cilvēks, kas netaisnību dzer kā ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Es tev stāstīšu, klausies mani, un es tev teikšu, ko esmu redzējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Ko gudrie stāstījuši no saviem tēviem un nav slēpuši, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Tiem vien zeme bija dota, un svešinieks viņu starpā nebija nācis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Bezdievīgais mokās visu mūžu, un briesmīgais, cik tam gadi nolikti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Viņa ausīs skan briesmas, pašā mierā viņam uzbrūk postītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Viņš neuzticās iznākt no tumsības; jo zobens uz viņu gaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Viņš skraida šurp un turp pēc maizes, kur varētu dabūt; viņš zin tumsības dienu sev tuvu klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Bēdas un izbailes viņu biedē, viņu pārvar kā ķēniņš, uz kaušanos gatavs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Jo viņš izstiepa savu roku pret Dievu un cēlās pret to Visuvareno.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Viņš skrēja pret Viņu ar pašu galvu, ar savu priekšturamo bruņu biezām pumpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Viņš savu vaigu tauki izbaroja un kopa resnu vēderu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Viņš dzīvoja izpostītās pilsētās un namos, kur nebija jādzīvo, kuriem nolemts būt par akmeņu kopām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, '(Tāpēc) viņš nepaliks bagāts, un viņa manta nepastāvēs, un viņa laime neizplētīsies virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Viņš no tumsības ārā neiznāks, liesma izkaltēs viņa zarus, caur Dieva mutes dvašu viņš aizies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Lai viņš nepaļaujas uz nelietību, ar to viņš pieviļas; jo nelietība būs viņa alga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Tā alga nāks priekšlaiku, un viņa zars nezaļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Viņš zaudēs kā vīna koks savus ķekarus un nometīs kā eļļas koks savus ziedus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Jo bezdievīgo saime paliks neauglīga, un uguns norīs dāvanu ņēmēju dzīvokļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Tie ir grūti ar netaisnību un dzemdē postu, un savām sirds domām tie pieviļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Tad Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Tādas lietas nu papilnam esmu dzirdējis, jūs visi esat nelāga iepriecinātāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Vai tie uzpūstie vārdi nu būs galā, vai kas tevi dzen tā atbildēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Es gan tāpat runātu kā jūs, kad jūsu dvēsele būtu manā vietā, ar vārdiem es pret jums turētos un kratītu savu galvu pār jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Es jūs stiprinātu ar savu muti, jūs iepriecinātu ar savām lūpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Kad es runāju, tad manas sāpes nerimst, un kad es klusu ciešu, vai tad tās nostājās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Tiešām, nu Viņš mani nokausējis; Tu esi izklīdinājis visu manu saimi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Un mani darījis grumbainu, - tas ir par liecību, un mana liecība cēlās pret mani un mani apsūdzēja pašā vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Viņa bardzība mani saplosīja un vajāja, Viņš sakož Savus zobus par mani, mans pretinieks met briesmīgas acis uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Tie atplēš muti pret mani, un lādot tie mani sit vaigā, tie sapulcējās kopā pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Dievs mani nodevis neliešiem un man licis nākt bezdievīgu rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Es biju mierā, bet Viņš mani sadauzījis, Viņš mani grābis pie kakla un mani satriecis un mani licis Sev par mērķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Viņa bultas ap mani skraida, Viņš sašķēlis manas īkstis un nav taupījis, Viņš manu žulti izlējis zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Plosīdams Viņš mani plosot plosījis, Viņš kā pats varenais pret mani lauzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Es maisu esmu šuvis ap savu ādu un savu ragu licis pīšļos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mans vaigs ir nosarcis no raudām, un pār maniem acu vākiem ir nāves ēna,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Jebšu netaisnība nav manā rokā, un mana lūgšana ir šķīsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Zeme, neapklāj manas asinis, un mana saukšana lai nemitās!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Jau tagad, redzi, mans liecinieks ir debesīs, un mans liecības devējs debess augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Mani draugi ir mani mēdītāji, bet no manas acs asaras pil uz Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Kaut Viņš tiesu nestu starp vīru un Dievu un starp cilvēka bērnu un viņa draugu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Jo tie noliktie gadi ies galā, un es aiziešu ceļu, kur atpakaļ negriezīšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mans gars ir vājš, manas dienas pagalam, kaps man ir klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Tiešām, mēdītāji mani apstāj un uz viņu tiepšanos jāskatās manām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Galvo jel, pārstāvi Tu mani pie Sevis paša, kur tad cits man roku dos!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Jo viņu sirdīm Tu saprašanu esi apslēpis; tāpēc Tu viņiem virsroku nedosi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Kas savus draugus izdāvā par laupījumu, tā bērnu acis izīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Bet Viņš mani darījis ļaudīm par sakāmu vārdu, ka esmu tāds, kam spļauj vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Tādēļ mana acs ir tumša no skumības, un visi mani locekļi ir kā ēna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Taisnie par to iztrūcinājās, un nenoziedzīgais iekarst par neganto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Bet taisnais turas pastāvīgi uz sava ceļa, un kam šķīstas rokas, pieņemas stiprumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Tad nu jūs visi nāciet tik atkal vien, gudra es neatradīšu jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Manas dienas ir pagājušas, mani padomi iznīcināti, ko mana sirds bija kopusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Nakti tie sauc par dienu, un gaismu saka tuvu esam, kur tumsa klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Ko man vēl gaidīt, kaps būs mans nams; tumsā es uztaisīšu savu gultu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Trūdus es saucu par savu tēvu, tārpus par savu māti un māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kur tad būs mana cerība, manu cerību, kas to redzēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Kapā tā nogrims, kad it visiem pīšļos būs dusa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Tad Bildads no Šuhas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Cik ilgi vēl jūs grābstīsities pēc vārdiem? Pieņemiet padomu, un tad runāsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Kāpēc mēs topam turēti par lopiem, un par muļķiem jūsu acīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Tava dvēsele no dusmām plīst; vai tad tevis dēļ zeme paliks tukša un klintis celsies no savas vietas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Tomēr bezdievīgo gaisma izdzisīs, un viņa uguns liesma nespīdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Gaišums paliek tumšs viņa dzīvoklī, un viņa spīdeklis pār viņu izdziest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Viņa varas ceļi paliek šauri, un paša padoms viņu gāž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Jo viņa kājas to iedzen tīklā, un viņš staigā pār slazda valgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Valgs saista viņa pēdas, un saites viņu satver.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Viņa valgs ir apslēpts zemē, un viņa slazds uz ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Visapkārt bailība viņu iztrūcina un viņu dzen uz visiem soļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Nelaime taisās viņu rīt, un posts ir gatavs viņu gāzt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Tas ēd viņa miesas, un nāves pirmdzimušais rij viņa locekļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Viņa cerība tiek atņemta no viņa dzīvokļa, un viņam jānoiet pie briesmu ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Viņa dzīvoklī dzīvo visai sveši, uz viņa mājas vietu kaisa sēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'No apakšas sakalst viņa saknes, un no augšienes novīst viņa zari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Viņa piemiņa iznīkst no zemes, un slava viņam nepaliek pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'No gaismas to izstumj tumsā un aizdzen no zemes virsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Viņam nav nedz bērna, nedz bērnu bērna savos ļaudīs, un neviens neatliek viņa māju vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Kas rietumos, iztrūcinājās par viņa dienu, un kas austrumos, tos pārņem šaušalas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Tiešām, tā notiek netaisno dzīvokļiem un tādu ļaužu vietai, kas Dievu neatzīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Bet Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Cik ilgi jūs manu dvēseli bēdināsiet un mani mocīsiet ar vārdiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Jūs gan desmitkārt mani likuši kaunā un nekaunaties mani tā nomākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Un ja es tiešām esmu maldījies, tad tā maldīšanās ir mana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Vai tad jums tiešām tā bija lielīties pret mani un pierādīt manu kaunu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Ņemiet jel vērā, kā Dievs mani lauzis un mani apvaldzinājis ar Savu tīklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Redzi, es brēcu par varas darbu, bet man neatbild; es kliedzu pēc palīga, bet tiesas nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Manam ceļam Viņš licis šķēršļus, ka netieku uz priekšu, un uz manām tekām Viņš licis tumsību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Manu godu Viņš man novilcis un atņēmis manas galvas kroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Viņš mani nopostījis visapkārt, ka eju bojā, un manu cerību Viņš izsakņojis kā koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Viņš iededzinājis Savu bardzību pret mani un mani tur kā Savu ienaidnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Viņa kara spēki sanākuši kopā un pret mani taisījuši savu ceļu un apmetuši lēģeri ap manu dzīvokli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Manus brāļus viņš atšķīris tālu no manis, un mani draugi man palikuši visai sveši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Mani tuvinieki atstājās, un mani draugi mani aizmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Mana saime un manas kalpones tur mani par svešinieku, un es esmu kā svešs viņu acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Es saucu savu kalpu, bet tas neatbild, tas man mīļi jālūdzās ar savu muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mana dvaša riebj manai sievai, un mana smaka manas mātes bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Pat puikas mani nicina; kad es ceļos, tad tie man runā pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Visi mani uzticamie draugi mani tur par negantību, un ko es mīlējis, tie ir griezušies pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Mani kauli līp pie manas ādas un pie manas miesas, un maniem zobiem āda vien atliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Apžēlojaties par mani, apžēlojaties par mani, mani draugi! Jo Dieva roka mani aizskārusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Kāpēc jūs mani vajājat, kā tas stiprais Dievs, un no manas miesas nevarat pieēsties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ak kaut mani vārdi taptu sarakstīti, ak kaut tie taptu iezīmēti grāmatā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Kaut tie ar dzelzs kaltu un svinu par mūžīgu piemiņu taptu iecirsti akmenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Bet es zinu, ka mans Pestītājs dzīvs, un pēcgalā Viņš celsies pār pīšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Un kad mana āda, kas tā sasista, vairs nebūs, tad vaļā no savas miesas es skatīšu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Tiešām, es Viņu sev skatīšu, un manas acis Viņu redzēs, un nebūs svešs. - Mana sirds iekš manis ilgojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Kad jūs sakāt: Kā mēs to vajāsim? Un ka tā vaina pie manis atrasta:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Tad bīstaties no zobena; jo zobens ir tā bardzība par noziegumiem, lai jūs atzīstat, ka ir sodība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Tad Cofars no Naēmas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Uz to manas sirds domas mani spiež atbildēt, un es nevaru valdīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Es dzirdu pārmācīšanu sev par kaunu, bet mans gars savā gudrībā zinās atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Vai tu nezini, ka mūžam tā bijis, kamēr Dievs cilvēkus licis virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Ka bezdievīgo lielība ilgi nepastāv, un ka blēdnieka prieks paliek tik acumirkli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Jebšu viņa greznība uzkāptu līdz debesīm, un viņa galva sniegtu līdz padebešiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Taču kā viņa sūds viņš mūžam zudīs; kas viņu redzējuši, tie sacīs: kur viņš ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Viņš aizskries kā sapnis, ka to nevarēs atrast, un pazudīs kā parādīšana naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Acs, kas viņu redzējusi, to vairs neredzēs, un viņa vieta to vairs neieraudzīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Viņa bērni pielabināsies pie nabagiem, un viņa roka dos atpakaļ viņa mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Viņa kauli bija pilni jaunības spēka, bet apgulsies ar viņu pīšļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Jebšu blēdība bijusi salda viņa mutei, un viņš to slēpis apakš savas mēles,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Un viņš to mīlējis un nepametis, bet to paturējis savā mutē:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Taču viņa barība pārvērtīsies viņa iekšās, par odžu žultīm tā būs iekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Mantu, ko ierijis, viņš atkal izvems, un Dievs to izgrūdīs viņam no vēdera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Odžu žultis viņš zīdīs, glodeņu dzelonis viņu nokaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Viņš neredzēs upes, kas ielejās tek no medus un piena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Viņš gan strādās, bet to atdos un no tā nebaudīs; cik viņš arī neiemantos, prieka tam nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Jo viņš nospaidījis un atstājis nabagus, namus viņš laupījis, bet tos neuzcels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Jo viņa kuņģis nebija pildāms, viņš neizglābsies caur savu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Viņa rīklei nekas neizmuka, tādēļ viņa labums nepastāvēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Pašā bagātā pilnībā viņam būs bēdas, visu apbēdināto roka nāks viņam virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Un notiks, lai viņa kuņģis top pilns, tad (Dievs) uz viņu sūtīs savas bardzības karstumu un uz viņu liks lītin līt, lai to rij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Viņš bēgs no dzelzs bruņām, un vara stops viņam izšaus cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Viņš izvelk un no viņa miesām nāk ārā, no viņa žultīm spīdoša dzelzs, un nāves šausmas viņu pārņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Visāda tumsība apklās viņa krājumu, neuzpūsts uguns viņu aprīs, un nomaitās to atlikumu viņa dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Debess viņa noziegumu darīs zināmu, un zeme celsies pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Viņa nama krājums aizies, viņam izšķīdīs Dieva dusmības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Šī ir bezdievīga cilvēka daļa no Dieva, un viņa nospriesta mantība no tā stiprā Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Bet Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Klausāties, klausāties manu valodu, un tā mani iepriecinājāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Paciešaties man runājot, pēc apsmejiet manu valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Vai tad es vaidu par cilvēkiem, un kā lai mans prāts nav skumīgs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Skatāties uz mani, tad jūs iztrūcināsities un liksiet roku uz muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Kad es to pieminu, tad es iztrūkstos, un šaušalas pārņem manu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Kāpēc bezdievīgi paliek dzīvi, top veci, un vareni spēkā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Viņu sēkla pastāv viņu priekšā līdz ar viņiem, un viņu bērni priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Viņu namam ir miers bez bailēm, un Dieva rīkste nenāk pār tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Viņa vērsis aplec un nepaliek bez augļiem, viņa govs vedās un neizmetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Savus bērnus tie izlaiž kā avju pulku, un viņu puikas lēkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Tie ir līksmi ar bungām un koklēm un priecājās ar stabules skaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Tie pavada savas dienas labklājībā, un acumirklī tie iegrimst kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Taču tie sacījuši uz Dievu: Nost no mums, jo Tavus ceļus mēs negribam atzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kas ir tas Visuvarenais, ka mēs tam kalpotu, un kāds labums mums atlec, ka to piesauktu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, '(Bet) redzi, viņu labums nestāv viņu rokā; tādēļ bezdievīgo padoms lai ir tālu nost no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Cikkārt tad izdziest bezdievīgo gaišums, un posts tiem uznāk, ka Dievs (tiem) liek valgus Savā dusmībā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Ka tie ir kā rugāji priekš vēja un kā pelus, ko vētra aizrauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Dievs pataupot viņa nelaimi uz viņa bērniem. Lai Viņš to viņam pašam atmaksā, ka pats to mana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Viņa paša acis lai redz savu postu, un pats lai dzer no tā Visuvarenā bardzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Jo kādas tam bēdas par savu namu, kad paša vairs nav, kad viņa mēnešu skaits ir beigts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Kas mācītu saprašanu Dievam, kas arī tos augstos tiesā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Viens nomirst pilnā spēkā visā mierā un laimē;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Viņa trauki ir pilni piena, un viņa kauli ir tauki no smadzenēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Cits atkal mirst ar rūgtu dvēseli un nekad nav baudījis labuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Tie kopā guļ pīšļos, un abus tārpi apklāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Redzi, es zinu jūsu domas un jūsu gudrību, ar ko jūs mani gribat nomākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Jo jūs sakāt: kur ir tā varenā nams, un kur to bezdievīgo telts un dzīve?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Vai neesat vaicājuši, kas tālus ceļus gājuši; vai nezināt, ko tie stāsta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Ka ļaunais glābjās nelaimes dienā, un bardzības dienā tie top pasargāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kas viņam acīs pārmetīs viņa ceļu, kas viņu sodīs, kad tas ko dara?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Ar godu viņš top pavadīts kapā, un kaps tam stāv par dzīvu piemiņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Kapa smiltis ir viņam vieglas, un visi cilvēki iet viņam pakaļ, kā tie priekš viņa bijuši bez skaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Kā tad jūs mani tik velti iepriecinājat? Jūsu atbildes ir un paliek blēņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Tad Elifas no Temanas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Vai Dievam kāds labums no cilvēka? Nē, labums tam pašam, ka ir prātīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Vai tas tam Visuvarenam par labu, kad tu taisns, jeb par mantu, ka tu savus ceļus nenoziedzīgi staigā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Vai tad Viņš tavas Dieva bijāšanas dēļ tevi sodīs un ar tevi ies tiesā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Vai tava blēdība nav liela un tavi noziegumi bez gala?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Jo savus brāļus tu esi ķīlājis bez vainas un novilcis kailiem drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Piekusušo tu neesi dzirdinājis ar ūdeni un izsalkušam liedzis maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Kur kāds bija varens, tam piederēja zeme, un kas bija augstā godā, tas tur dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Atraitnes tu esi atlaidis tukšā, un bāriņu elkoņi ir salauzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Tādēļ ir virves ap tevi, un izbailes tev piepeši uzgājušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Jeb vai tu neredzi tumsu un ūdens plūdus, kas tevi apklāj?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Vai Dievs nav augšām debesīs? Redzi jel zvaigžņu augstumu, cik tās augstas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Un tu saki: ko Dievs zin? Vai Viņš aiz tumšiem mākoņiem māk tiesāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Padebeši ir Viņa aizsegs, ka neredz, un Viņš staigā debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Vai tu vecās pasaules ceļu gribi staigāt, ko netaisnie ļaudis gājuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Kas priekšlaiku bojā gājuši, - plūdi izgāzušies pār viņu pamatiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Kas uz to stipro Dievu sacīja: Nost no mums! un ko tas Visuvarenais tiem varētu darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Tomēr Tas viņu namus bija pildījis ar labumu. Šo bezdievīgo padoms lai ir tālu no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Taisnie to redz un priecājās, un nenoziedzīgais par tiem smiesies:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Tiešām, izdeldēti ir mūsu ienaidnieki, un uguns aprijis viņu pārējo mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Meklē Viņa draudzību, tad paliksi mierā, no tā tev nāks labums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Pieņem jel mācību no Viņa mutes un liec Viņa vārdus savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Ja tu atgriezīsies pie tā Visuvarenā un atmetīsi netaisnību tālu no sava dzīvokļa, tad tu tapsi uztaisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Liec pīšļos mantu un upes oļos zeltu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Tad tas Visuvarenais tev būs par zeltu un Viņš tev būs par spožu sudrabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Tad tu par to Visuvareno priecāsies un pacelsi uz Dievu savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Tu Viņu piesauksi, un Viņš tevi paklausīs, un tu maksāsi savus solījumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Ko tu apņemsies, tas tev notiks, un uz taviem ceļiem spīdēs gaišums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Kad iet uz leju, tad tu saki: uz augšu! Un Viņš izglābs to, kam noskumis vaigs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Viņš izpestīs to, kas nav nenoziedzīgs; tavu roku šķīstības dēļ tas taps izpestīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Bet Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Vēl šodien man jātiepjas manās vaimanās, tā roka uz manis ir smagāka, nekā manas nopūtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ak kaut es Viņu zinātu atrast un varētu aiztikt līdz Viņa krēslam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Es Viņam liktu priekšā savu lietu un raudzītu pierādīt savu taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Es gribētu dzirdēt tos vārdus, ko Viņš man atbildētu, un vērā ņemt, ko Viņš man sacītu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Vai Viņš pēc Sava lielā spēka ar mani tiesāsies? Nē, Viņš klausīsies uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tad taisns ar Viņu tiesātos, un es mūžam taptu izglābts no sava soģa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Bet, ja es eju pret rītiem, tad Viņa tur nav, ja eju pret vakariem, tad Viņu nemanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Ja Viņš ziemeļos dara Savu darbu, tad es Viņu neraugu, ja Viņš nogriežas uz dienasvidu, tad es Viņu neredzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Bet Viņš zina manu ceļu; ja Viņš mani pārbaudītu, tad es taptu atrasts kā zelts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Mana kāja turējās Viņa pēdās, es Viņa ceļu esmu sargājis un neesmu atkāpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'No Viņa lūpu pavēles es neesmu atkāpies, Viņa mutes vārdus es vairāk esmu glabājis nekā savu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Bet kad Viņš uz ko pastāv, kas Viņu novērsīs? Ko Viņš grib, to Viņš dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Jo Viņš izdara, ko Viņš par mani nodomājis, un vēl daudz tādu padomu ir pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Tādēļ es iztrūcinājos priekš Viņa vaiga; kad es to apdomāju, tad es bīstos Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Tas stiprais Dievs manu sirdi darījis bailīgu, un tas Visuvarenais mani iztrūcinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Jo tādā tumsībā es vēl neesmu izdeldēts, lai gan tumsa manu vaigu apklājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Kāpēc tas Visuvarenais nav nolicis tiesas laikus, un kāpēc tie, kas Viņu pazīst, neredz Viņa dienas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Robežas pārceļ, ganāmu pulku laupa un gana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Bāriņu ēzeli aizdzen un atraitnes govi ķīlā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Nabagus grūž no ceļa un bēdu ļaudīm zemē visiem jāapslēpjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Redzi, kā mežu ēzeļi tuksnesī tie iziet pie sava darba, agri celdamies pēc maizes, tuksnesis tiem ir barība priekš bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Tīrumā tie sev pļauj lopu ēdamo, un nolasa atlikas bezdievīgā vīna dārzā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Kaili tie guļ bez drēbēm, apsega tiem nav pret aukstumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Tie mirkst no lietus uz kalniem, un bez patvēruma būdami tie apkampj klintis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Bāriņu rauj no krūtīm un ņem no nabaga ķīlas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Kaili tie iet bez drēbēm, un izsalkuši tie nes kūlīšus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Šiem eļļa jāizspiež starp viņu mūriem, vīna spaids tiem jāmin un jāslāpst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Pilsētās ļaudis nopūšās un ievainoto dvēsele kliedz; un taču Dievs to grēku nesoda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Tie ir gaismas pretinieki, Viņa ceļus tie nepazīst un nepaliek uz Viņa tekām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Gaismai austot slepkava ceļas, nokauj nabagu un bēdīgu, un naktī tas top par zagli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Un laulības pārkāpēja acs gaida krēslību un saka: Neviena acs mani nepazīs; un apslēpj savu vaigu ar apsegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Tie tumsā ielaužās namos, dienas laikā slēpjās, no gaismas nekā negrib zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Jo visiem šiem tumša nakts ir par dienu, jo nakts briesmas tiem ir pazīstamas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Ātri tas nozūd pa ūdens virsu, viņa ežas ir nolādētas virs zemes, tas vairs nestaigās uz savu vīna dārzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Bula laiks un karstums aizņem sniega ūdeni, tāpat elle tos, kas grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Pats mātes klēpis viņu aizmirst, tas ir gardums tārpiem, tas netop vairs pieminēts, netaisnība top salauzta kā sapuvis koks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Jo viņš aplaupīja neauglīgo, kas nedzemdē, un nedarīja nekā laba atraitnei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Bet Dievs arī uztur varas darītājus ar savu spēku; vēl ceļas kas vairs neticēja, ka dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Viņš tiem dod drošību un stiprumu, un Viņa acis skatās uz viņu ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Tie ir augsti cēlušies, un mazs brīdis, tad to vairs nav; tie apgulstās, tiek savākti kā visi citi, un top nopļauti kā vārpas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Vai tas tā nav? Kas mani darīs par melkuli un manu valodu pierādīs par tukšu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Tad Bildads no Šuhas atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Valdība un briesmas ir pie Viņa, Viņš mieru gādā Savā debess augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Kas var izskaitīt Viņa karapulkus? Un pār ko Viņa gaisma neceļas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kā tad cilvēks varētu būt taisns Dieva priekšā, un šķīsts, kas no sievas dzimis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Skaties uz pašu mēnesi, tas nav skaidrs, un zvaigznes nav šķīstas priekš Viņa acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Ne vēl cilvēks, kas ir kode, un cilvēka bērns, kas ir tārps?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Un Ījabs atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Kā tu nu palīdzējis nestipram un stiprinājis nespēcīgo elkoni!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Kā tu nu padomu devis negudram un saprašanu izrādījis ļoti skaidri!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Kam tu teic šos vārdus, un kā dvaša no tevis iziet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Miroņi sāk trīcēt apakš ūdeņiem, un tie, kas tur mīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Elle Viņa priekšā ir atvērta, un nāves bezdibenim nav apsega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Viņš zvaigžņu debesi gaisā izpletis un zemi piekāris, kur nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Viņš saņem ūdeni Savos mākoņos, un padebeši apakš Viņa nesaplīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Viņš aizklāj Savu goda krēslu, Viņš izpleš tam priekšā Savu padebesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Viņš ap ūdeņiem licis ežu, līdz kur gaisma un tumsa šķirās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Debess pīlāri trīc un iztrūcinājās no Viņa draudiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Caur Viņa spēku jūra saceļas viļņos, un caur Viņa ziņu augstie viļņi tiek sašķelti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Caur Viņa vēju debess paliek skaidra, un Viņa roka nodur žiglo čūsku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Redzi, tā ir Viņa ceļu maliņa, un kāda lēna balss tikai, ko samanām; kas Viņa varas pērkoni varētu dzirdēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Un Ījabs teica vēl tālāk savus teikumus un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Tik tiešām kā Dievs dzīvs, kas man taisnību neizspriež, un tas Visuvarenais, kas manu dvēseli apbēdinājis -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Kamēr mana dvēsele vēl ir iekš manis un Tas Gars no Dieva manās nāsīs -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Manas lūpas nerunās netaisnību, un mana mēle neteiks melus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Es nebūt nevaru teikt, ka jums taisnība; kamēr man dvaša zūd, es aizstāvēšu savu nenoziedzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Es turēšos stipri pie savas taisnības un no tās neatlaidīšos; mana sirds mani nekož manu dienu pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Manam ienaidniekam būs palikt par blēdi, un manam pretiniekam par netaisnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Jo kāda ir blēdnieka cerība, kad Dievs atņem un aizrauj viņa dvēseli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Vai Dievs klausīs viņa saukšanu, kad viņam uznāk bēdas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Jeb vai viņš var prieku dabūt pie tā Visuvarenā, vai viņš Dievu var piesaukt ikkatrā laikā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Es jums mācīšu, kāda ir Dieva roka; kāds tā Visuvarenā padoms, to negribu slēpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Redzi, jūs visi to redzat, kāpēc tad jūs domājiet tukšas domas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Šī ir bezdievīga cilvēka alga pie Dieva un varas darītāju daļa, ko tie no tā Visuvarenā dabūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Ja tam daudz bērnu, tad zobens nāk pār tiem, un viņa pēcnākamie nepaēdīs maizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Viņa atlikušos mēris liek kapā, un viņa atraitnes nedabū raudāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Kad viņš naudu sakrāj kā pīšļus un drēbes sagādā kā mēslus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Tad viņš gan sagādā, bet taisnie tās apvilks, un nenoziedzīgie dalīs to naudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Viņš uztaisījis savu namu kā kode un kā gans uztaisa būdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bagāts tas apgūlās, un tad nekad vairs; viņš atdara savas acis, un nav vairs nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Bailība tam uzbrūk kā ūdens, naktī viņu aizrauj viesulis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Austriņa vējš viņu aizrauj, ka tas aiziet, un aizpūš viņu no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, '(Dievs) šauj uz viņu un netaupa, no Viņa rokas tas bēg šurpu turpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Par to sasit plaukstas un to aizsvilpo no viņa vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Tiešām, sudrabam ir savi ceļi, kur tas rodas, un kausējamam zeltam sava vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Dzelzs no zemes top ņemta, un no akmeņiem varš top kausēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Tumsai gals likts, un caur caurim cilvēks izmeklē arī pašā galējā tumsā apslēptos akmeņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Viņš izrok ceļu turp, kur neviens nedzīvo, un kur neviena kāja neved; tur viņš karājās un nolaižās tālu no cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'No zemes virsas izaug maize, viņas apakša top apgriezta kā no uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Viņas akmeņos ir safīri, un tur rodas zelta graudi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Ne ērglis šo ceļu nav ieraudzījis, ne vanaga acs to nav redzējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Briesmīgi zvēri pa to nav gājuši, un lauva pa to nav staigājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Cilvēks pieliek savu roku pie akmeņiem, un izrok kalnu pamatus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Viņš izcērt ceļus akmeņu kalnos, un viņa acs ierauga visādus dārgumus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Viņš aizdara ūdeņus, kā nesūcās cauri, un izved gaismā, kas ir apslēpts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Bet gudrību, kur to atrod, un kur mājo atzīšana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Cilvēks nezin, ar ko lai to pērk un dzīvo zemē to nevar uziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Bezdibenis saka: te viņas nav; un jūra saka: tā nav pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Zeltu par viņu nevar dot, nedz sudraba maksu par viņu iesvērt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'To nevar uzsvērt ar Ofira zeltu nedz ar dārgiem oniksa un safīra akmeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'To neatsver ne zelts, ne spīdoši akmeņi, to nevar izmīt pret zelta glītumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Par pērlēm un kristālu nav ko runāt; jo gudrību mantot ir pārāki par pērlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Moru zemes topāzs viņai nav līdzīgs, un visu šķīstais zelts viņu nepanāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Nu tad, no kurienes nāk gudrība un kur mājo atzīšana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Jo tā ir apslēpta priekš visu acīm, kas dzīvo, un putniem apakš debess tā ir nezināma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Elle un nāve saka: ar savām ausīm gan esam dzirdējuši viņas slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Dievs pazīst viņas ceļu, un Tas zin viņas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Jo Viņš skatās līdz pasaules galiem, Viņš redz, kas apakš visām debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Kad Viņš vējam deva savu svaru un ūdeni nosvēra pēc mēra,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Kad Viņš lietum sprieda likumu un zibenim un pērkonam ceļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Tad Viņš to izredzēja un to izteica, Viņš to sataisīja un izdibināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Un sacīja uz cilvēku: redzi, Tā Kunga bijāšana, tā ir gudrība, un atstāties no ļauna, tā ir atzīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Un Ījabs teica vēl tālāk savus teikumus un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ak kaut es vēl būtu tāds kā pirmajos mēnešos, kā tai laikā, kad Dievs mani pasargāja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Kad Viņa spīdeklis spīdēja pār manu galvu, un es Viņa gaismā staigāju pa tumsību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Kā es biju savas jaunības laikā, kad Dievs mājoja pār manu dzīvokli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Kad tas Visuvarenais vēl bija ar mani, un mani bērni man apkārt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Kad savus soļus mazgāju krējumā, un akmens kalni man izlēja eļļas upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Kad es pa vārtiem izgāju pilsētā, kad savu krēslu noliku uz tirgus(laukuma);');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Tad jaunekļi mani redzot stājās pie malas, un sirmgalvji pacēlās un palika stāvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Virsnieki mitējās runāt un lika roku uz savu muti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Lielkungu balss apklusa, un viņu mēle pielipa pie zoda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Jo kura auss mani dzirdēja, tā mani teica laimīgu, un kura acs mani redzēja, tā deva man liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Jo es izglābu nabagu, kas brēca, un bāriņu, kam nebija palīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Svētība no tā, kas ietu bojā, nāca pār mani, un atraitņu sirdi es iepriecināju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Es apģērbos ar taisnību, un tā mani aptērpa, mana krietnība man bija kā mētelis un kā ķēniņa cepure.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Es biju aklam acs un biju tizlam kāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Nabagiem es biju par tēvu, un nezināma sūdzību es izvaicāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Es salauzīju netaisnā dzerokšļus un izrāvu laupījumu no viņa zobiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Un es sacīju: es nomiršu savā ligzdā un manu dienu būs daudz kā smiltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Mana sakne izpletīsies pie ūdens, un rasa paliks pa nakti uz manām lapām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Mana godība būs vienmēr jauna pie manis, un manam stopam labi izdosies manā rokā. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Uz mani klausījās un gaidīja un klusu saņēma manu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Pēc maniem vārdiem neviens vairs nerunāja, un mana valoda uz tiem pilēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Pēc manis ilgojās kā pēc lietus, un atpleta savu muti kā uz vasaras lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Es tiem uzsmaidīju, kad tiem nebija drošības, un mana vaiga gaišumu tie neskumdināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Es tiem biju ceļa rādītājs un sēdēju goda vietā un mājoju kā ķēniņš starp saviem pulkiem, kā noskumušu iepriecinātājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Bet nu par mani smejas, kas jaunāki nekā es, kuru tēvus es nebūtu cienījis likt pie saviem lopu suņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Viņu roku spēku kur es to liktu? viņu zaļums un krietnums bija pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'No trūkuma un bada izdēdējuši tie grauza noras, tumšās tuksneša un posta vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Tie nātres izplūca pa krūmiem un paegļu saknes tiem bija par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'No ļaužu vidus tie tapa izdzīti un tiem uzkliedza kā zagļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Bailīgās gravās tiem bija jādzīvo, ir zemes un akmeņu caurumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Krūmos tie brēca, un dadžos tie gūlās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Nesaprašu un negoda ļaužu bērni, kas no zemes bija izdzīti!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Bet nu es tiem esmu tapis par dziesmiņu un esmu tiem par pasaku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Tie mani tura par negantību, atstājās tālu no manis un nekaunas man vaigā spļaudīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Jo Dievs manu dvēseli ir darījis gurdenu un mani apbēdinājis; tad tie vairs nevaldās manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Pa labo roku ceļas puikas un stumda manas kājas un taisa savu ceļu, mani samaitāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Tie salauž manu laipu, tie palīdz mani gāzt, paši būdami bez palīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Tie nāk kā caur platu plīsumu; ar lielu troksni tie plūst šurpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Briesmas man uzbrukušas, kā ar vētru aizdzīta mana godība, un kā mākonis nozudusi mana laime.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Tādēļ nu mana dvēsele nerimst iekš manis, un bēdu laiks mani aizgrābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Naktī mani kauli top izurbti iekš manis, un kas mani grauž, nerimst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Caur varenu spēku mans apģērbs pārvērties; tas mani žņaudz, kā apkakle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Viņš mani iemetis dubļos, un es esmu tapis kā pīšļi un pelni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Es Tevi piesaucu, bet Tu man neatbildi, es gaidu, bet Tu tik skaties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Tu pret mani esi palicis briesmīgs, ar Savu vareno roku Tu man turies pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Tu mani pacēli, kā vējš mani aiznes, un man izkūst visa laime.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Jo es zinu, ka Tu mani nodosi nāvē, kur visi dzīvie kopā aiziet mājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Tomēr, vai krītot neizstiepj roku, jeb vai bojā ejot nebrēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Vai es neraudāju par grūtdienīti vai mana dvēsele nenoskuma par apbēdināto?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Bet kad es nu gaidīju labumu, tad nāca ļaunums; kad es cerēju uz gaišumu, tad nāca tumsība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Manas iekšas verd un nemitās, bēdu dienas man uzgājušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Es esmu melns, bet ne no saules, es paceļos un kliedzu draudzes vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Vilkiem esmu palicis par brāli un pūces bērniem par biedri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Mana āda palikusi melna uz manis, un mani kauli ir izkaltuši no karstuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Tādēļ mana kokle ir tapusi par žēlabām un mana stabule par vaimanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Es derību esmu derējis ar savām acīm, ka man nebija uzlūkot sievieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Bet kādu daļu Dievs man dod no augšienes, jeb kādu mantību tas Visuvarenais no debesīm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Vai netaisnam nepienākas nelaime un ļauna darītājam nedienas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Vai Viņš neredz manus ceļus, vai Viņš neskaita visus manus soļus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Ja esmu dzinis netaisnību un mana kāja steigusies uz nelietību, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Lai Viņš mani nosver taisnā svaru kausā, tad Dievs atzīs manu nenoziedzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Ja mani soļi no ceļa noklīduši, un mana sirds dzinusies pakaļ manām acīm, ja kas pielipis pie manām rokām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Tad lai es sēju, un cits to ēd, un mani iedēsti lai top izsakņoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Ja mana sirds ļāvās apmānīties sievas dēļ un ja esmu glūnējis pie sava tuvākā durvīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Tad lai mana sieva maļ citam, un svešs lai pie tās pieglaužas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Jo šī ir negantība un noziegums priekš tiesnešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Jo tas ir uguns, kas rij līdz pašai ellei un būtu izsakņojis visu manu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Ja esmu nicinājis sava kalpa vai savas kalpones tiesu, kad tiem kas bija pret mani:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Ko es tad varētu darīt, kad tas stiprais Dievs celtos, un kad Viņš meklētu, ko es varētu atbildēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Vai Tas, kas mani radījis mātes miesās, nav radījis viņu arīdzan? Vai Tas pats mūs miesās nav sataisījis(viena veida)?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Ja nabagam esmu liedzis, kad tam gribējās, vai licis izīgt atraitnes acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Ja esmu ēdis savu kumosu viens pats, tā ka bāriņš no tā arī nebūtu ēdis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Jo no manas jaunības viņš pie manis ir uzaudzis kā pie tēva, un no savas mātes miesām es viņu esmu žēlojis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Ja esmu redzējis kādu bojā ejam, kam drēbju nebija, un ka nabagam nebija apsega;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Ja viņa gurni man nav pateikušies, kad viņš bija sasilis no manu jēru ādām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Ja savu roku esmu pacēlis pret bāriņu, kad es redzēju savu palīgu vārtos:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Tad lai mans elkonis atkrīt no pleca un mana roka lai nolūst no stilba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Jo mani biedina Dieva sods un Viņa augstības priekšā esmu nespēcīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Ja uz zeltu esmu licis savu cerību, vai uz šķīstu zeltu sacījis: mans patvērums;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Ja esmu priecājies, ka man liela manta un ka mana roka ko laba sakrājusi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Ja saules gaišumu esmu uzlūkojis, kad tas spīdēja, vai mēnesi, kad tas spoži tecēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Un mana sirds būtu ļāvusies pievilties, ka savu roku no mutes uz tiem būtu pacēlis (tos godināt);');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Tas arī būtu noziegums priekš tiesnešiem, jo es būtu aizliedzis Dievu augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Ja esmu priecājies par sava nīdētāja nelaimi un lēkājis, kad posts to aizņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Jo es savai mutei neļāvu grēkot, ka es viņa dvēseli būtu lādējis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Ja manai saimei nebija jāsaka: vai kāds pie viņa galda gaļas nav paēdis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Svešiniekam nebija jāpaliek par nakti ārā, savas durvis es atdarīju pret ceļa pusi -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Ja kā Ādams esmu apklājis savus pārkāpumus, savu noziegumu apslēpdams savā sirdī');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Ka man bija bail no tā lielā pulka, vai ka radu pelšana man biedēja, ka es klusu turējos, negāju ārā pa durvīm -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ak kaut man būtu, kas mani klausītu! redzi, še mans raksts, lai Dievs man atbild, un tas raksts, ko mans pretinieks rakstījis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Tiešām, uz saviem kamiešiem es to gribu nest, to sev gribu apsiet kā kroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Visus savus soļus es tam gribu izstāstīt, kā valdnieks es pie tā gribu pieiet -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Ja mans tīrums par mani kliedz, un viņa vagas kopā raud,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Ja es viņa augļus esmu velti ēdis un arāju dvēselei licis nopūsties:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Tad lai man aug dadži kviešu vietā un ērkšķi miežu vietā! Tā Ījaba vārdi beidzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Tad tie trīs vīri mitējās Ījabam atbildēt, tāpēc ka tas pats sevi turēja par taisnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Bet Elihus, Baraheēļa dēls, tas Buzietis, no Rāma radiem, apskaitās pret Ījabu lielās dusmās, tāpēc ka tas savu dvēseli taisnoja pār Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Viņš arī apskaitās par saviem trim draugiem, ka tie atbildes neatrada un tomēr Ījabu pazudināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Jo Elihus bija gaidījis ar Ījabu runāt, tāpēc ka tie bija vecāki nekā viņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Bet kad Elihus redzēja, ka atbildes nebija to triju vīru mutē, tad viņš apskaitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Un Elihus, Baraheēļa dēls, tas Buzietis, atbildēja un sacīja: es esmu jauns, bet jūs esat veci, tāpēc es esmu gaidījis un bijājies, jums izteikt savu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Es domāju: lai tie gadi runā, un gadu vairums lai izteic gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Bet tas ir Tas Gars iekš cilvēka un tā visuvarenā Dieva dvaša, kas tos dara gudrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Veci nav tie gudrākie nedz sirmgalvji, kas prot tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Tādēļ es gribu runāt, - klausiet mani, es arīdzan parādīšu savu zināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Redzi, es esmu gaidījis uz jūsu vārdiem, esmu klausījies uz jūsu gudrību, vai jūs atrastu tos īstenos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Kad es nu jūs liku vērā, redzi, tad nav neviena, kas Ījabu būtu pārliecinājis, kas uz viņa vārdiem būtu atbildējis jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Tad nu nesakāt: mēs esam dzirdējuši gudrību; Dievs vien viņu pārvarēs, un ne cilvēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Pret mani vēl viņš vārda nav cēlis, un ar jūsu valodu es viņam gan neatbildēšu. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Tie ir izbiedēti, vairs nevar atbildēt, tiem trūkst valodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Es esmu gaidījis, bet tie nerunā, tie stāv klusu un vairs neatbild.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Tad nu es atbildēšu savu tiesu, es arīdzan parādīšu savu zināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Jo es esmu tik pilns vārdu, ka gars manu sirdi spiež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Redzi, mana sirds ir kā jauns vīns, kas nestāv vaļā, tā gribētu plīst, kā jauni ādas trauki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Es runāšu, lai es varu atpūsties, es atdarīšu savas lūpas un atbildēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Cilvēka vaigu es neuzlūkošu un nerunāšu nevienam pa prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Jo cilvēkam pa prātam runāt es nemāku, lai mans Radītājs mani ātri neaizņem projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Bet tu, Ījab, klausi jel manu valodu un ņem vērā visus manus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Redzi nu, es savas lūpas esmu atdarījis, mana mēle manā mutē runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Mani teikumi būs sirds taisnība, un manas lūpas skaidri izrunās, ko zinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Dieva Gars mani radījis, un tā Visuvarenā dvaša man devusi dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Ja tu vari, atbildi man, taisies pret mani un nostājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Redzi, es piederu Dievam tā kā tu, no zemes es arīdzan esmu ņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Redzi, iztrūcināt es tevi neiztrūcināšu, un mana roka pār tevi nebūs grūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Tiešām, tu esi runājis priekš manām ausīm, to vārdu balsi es esmu dzirdējis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '„Es esmu šķīsts, bez pārkāpšanas, es esmu skaidrs, un man nozieguma nav;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Redzi, Viņš atrod iemeslus pret mani, Viņš mani tura par Savu ienaidnieku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Viņš manas kājas liek siekstā, Viņš apsargā visus manus ceļus.“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Redzi, tur tev nav taisnības; es tev atbildu, ka Dievs ir daudz augstāks pār cilvēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Kāpēc tu pret Viņu tiepies, kad Viņš neatbild par visiem saviem darbiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Jo Dievs runā vienreiz, un vēl otrreiz, bet to neliek vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Sapnī caur nakts parādīšanām, kad ciets miegs cilvēkiem uzkrīt, kad tie guļ savā gultā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Tad Viņš atdara cilvēku ausi un apzieģelē, ko Viņš tiem grib mācīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Lai cilvēku novērš no nedarba un pasargā vīru no lepnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Lai izglābj viņa dvēseli no kapa un viņa dzīvību, ka nekrīt caur zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Viņš to arī pārmāca ar sāpēm gultā un lauž visus viņa kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Tā ka viņa sirds neņem pretī maizi, nedz viņa dvēsele kādu gardumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Viņa miesa nodilst, ka no tās nekā vairs neredz, un kauli nāk ārā, kas nebija redzami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Un viņa dvēsele nāk tuvu pie bedres, un viņa dzīvība pie nāves sāpēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Ja tad pie viņa nāk vēstnesis, ziņas devējs kā viens no tūkstošiem, rādīt cilvēkam kas pareizi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Tad Viņš tam ir žēlīgs. un saka: atpestī to, ka negrimst kapā, jo esmu atradis salīdzināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Tad viņa miesa būs zaļāka nekā jaunībā, tas nāks atkal pie savas jaunības dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Tas lūgs Dievu, un Viņš to žēlos, - tas uzskatīs Dieva vaigu ar prieku, un Dievs cilvēkam atmaksās viņa taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Tad šis izteiks cilvēkiem un sacīs: es biju grēkojis un pārgrozījis tiesu, bet Viņš to man nav pielīdzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Viņš ir atpestījis manu dvēseli, ka tā negrimst kapā, un mana dzīvība redz gaišumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Redzi, to visu dara tas stiprais Dievs divi un trīskārt cilvēkam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Ka viņa dvēseli novērstu no kapa, ka tā taptu apgaismota dzīvības gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Liec vērā, Ījab, klausies mani, ciet klusu, un es runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Jeb, ja tev ir ko sacīt, tad atbildi man; runā, jo es labprāt redzētu tavu taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Ja nav, tad klausies mani, ciet klusu, un es tev mācīšu gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Un Elihus atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Klausāties, gudrie, manu valodu, un prātīgie, atgriežat ausis pie manis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Jo auss pārbauda vārdus, tā kā mute bauda barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Lai pārspriežam savā starpā, lai kopā atzīstam, kas ir labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Jo Ījabs saka: es esmu taisns, bet Dievs ir atņēmis manu tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Lai gan man taisnība, mani tura par melkuli, manas mokas ir nedziedinājamas, lai gan neesmu noziedzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kur ir gan cilvēks, kā Ījabs, kas zaimošanu dzer kā ūdeni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Un draudzējās ar ļaundarītājiem un staigā ar bezdievīgiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Jo viņš saka: cilvēkam nekā nepalīdz, ka tas mīļo Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Tādēļ, gudrie vīri, klausāties mani. Nevar būt, ka Dievs ir ļauns un tas Visuvarenais netaisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Jo Viņš cilvēkam maksā pēc viņa darba, un ikkatram liek klāties pēc viņa gājuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Patiesi, Dievs nedara ļauna, un tas Visuvarenais nepārgroza tiesu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kam pasaule ir pavēlēta, ja ne Viņam, un kas ir radījis visu zemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Ja Viņš Savu sirdi grieztu uz Sevi pašu vien, un Savu garu un Savu dvašu ņemtu pie Sevis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Tad visa miesa kopā mirtu, un cilvēks taptu atkal par pīšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Ja nu tev ir saprašana, klausi to, ņem vērā manas valodas balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Vai jel, kas taisnību ienīst, varēs vadīt? Kā tad tev bija tiesāt to Vistaisnāko?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Viņu, kas uz ķēniņu var sacīt: tu netikli, un uz valdnieku: tu blēdi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Kas neuzlūko valdnieku vaigu un neieredz bagātus vairāk nekā nabagus, jo tie visi ir Viņa roku darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Acumirklī tie nomirst, un nakts vidū tautas top iztrūcinātas un iet bojā, un varenie top aizrauti un ne caur cilvēka roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Jo Viņa acis skatās uz cilvēka ceļiem, un Viņš redz visus viņa soļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Tumsas nav nedz nāves ēnas, kur ļaundarītāji varētu slēpties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Viņam cilvēks ilgi nav jāmeklē, ka lai nāk uz tiesu Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Viņš satriec varenos bez izmeklēšanas un ieceļ citus viņu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Tāpēc ka Viņš zina viņu darbus, Viņš tos apgāž naktī, ka tie top satriekti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Viņš tos šausta kā bezdievīgus, tādā vietā, kur visi redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Tāpēc ka tie no Viņa atkāpušies un nav apdomājuši visus Viņa ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Ka nabaga brēkšanai bija jānāk pie Viņa, un bēdīgā kliegšanu Viņš paklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Kad Viņš dod mieru, kas tad pazudinās? Kad Viņš Savu vaigu apslēpj, kas Viņu skatīs? Tā tas ir ar tautām, tā ar ikvienu cilvēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Lai nelieša cilvēks nevalda un tautai nav par valgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Jo uz Dievu jāsaka: man bija jācieš, es vairs negrēkošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Ko es neredzu, to māci tu man; ja esmu darījis netaisnību, tad to vairs nedarīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Vai Dievs lai atlīdzina pēc tava prāta? Jo tu neesi mierā! tad spriedi tu, ne es! Un ko tu taču māki sacīt!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Prātīgi ļaudis man sacīs, un ikviens gudrs vīrs, kas uz mani klausījies:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Ījabs runājis neprazdams, un viņa vārdi nav bijuši gudri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Kaut Ījabs taptu pārbaudīts līdz galam, ka viņš runā, kā bezdievīgi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Jo viņš krauj grēku uz grēku, viņš mūsu priekšā zaimo un runā daudz pret to stipro Dievu. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Un Elihus vēl atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Vai tev šķiet pareizi esam, ka tu saki: mana taisnība iet pāri par Dieva taisnību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Ka tu saki: kas man no tās atlec, ko es ar to vairāk panākšu nekā ar saviem grēkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Es tev vārdu atbildēšu un taviem draugiem pie tevis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Skaties pret debesi un redzi, uzlūko padebešus, kas ir augsti pāri pār tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Ja tu grēko, ko tu Viņam vari darīt? Un lai tavu pārkāpumu daudz, ko tu Viņam padarīsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Ja tu esi taisns, kas Viņam no tā tiek, jeb ko Viņš dabū no tavas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Tev cilvēkam tava bezdievība par postu, un tev cilvēka bērnam tava taisnība nāk par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Par varas darbu pulku tie brēc, tie kliedz lielo kungu elkoņa dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Bet neviens nesaka: kur ir Dievs, mans Radītājs, kas ir naktī dod slavas dziesmas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Kas mūs darījis jo izmācītus, nekā lopus virs zemes, un gudrākus pār putniem apakš debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Tie tur brēc, bet Viņš neatbild ļauno pārgalvības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Tiešām, Dievs netaisnību nepaklausa un tas Visuvarenais to neuzlūko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Jebšu tu saki, ka tu Viņu neredzēsi, tā tiesas lieta ir Viņa priekšā, gaidi tik uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Bet nu, ka Viņa dusmība vēl nepiemeklē, vai Viņš tādēļ vērā neliek, ka pārkāpumu ir tik daudz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Un tomēr Ījabs tukšiem vārdiem atvēris savu muti un daudz runājis bez saprašanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Un Elihus vēl runāja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Pagaidi man vēl maķenīt, es tev mācīšu, jo no Dieva puses vēl kas jāsaka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Es meklēšu savu atzīšanu no tālienes un gādāšu savam radītājam taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Jo tiešām, mana valoda nav meli; tavā priekšā ir, kam atzīšanas netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Redzi, Dievs ir varens un tomēr neatmet, Viņš ir varens gudrības spēkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Viņš bezdievīgam neliek dzīvot, un bēdīgam nes tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Viņš nenovērš savas acis no taisnā, bet pie ķēniņiem uz goda krēsla, tur Viņš tiem liek sēdēt mūžam, ka top paaugstināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Un kur cietuma ļaudis ir ķēdēs un top turēti bēdu saitēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Tur Viņš tiem dara zināmu viņu darbu un viņu pārkāpumus, ka cēlušies lepnībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Viņš tiem atdara ausi mācībai, un saka, lai atgriežas no netaisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Ja tie nu klausa un Viņam kalpo, tad tie pavada savas dienas labumā un savus gadus laimē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Un ja tie neklausa, tad tie krīt caur zobenu un mirst bez atzīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Bet kam neskaidra sirds, tie kurn, tie nepiesauc, kad Viņš tos saistījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Tā tad viņu dvēsele mirst jaunībā, un viņu dzīvība paiet ar mauciniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Bet bēdīgo Viņš izpestī viņa bēdās, un atver viņa ausis bēdu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Tāpat Viņš tevi izraus no bēdu rīkles uz klaju vietu, kur bēdu nav, un tavs galds būs pilns ar treknumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Bet ja tu esi pilns bezdievīgas tiesāšanās, tad tiesa un sodība tevi ķers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Lai sirds rūgtums tev jel neskubina zaimot, un tā lielā pārbaudīšana lai tevi nenovērš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Vai tu ar brēkšanu no bēdām tiksi vaļā, vai cīnīdamies ar visu spēku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Neilgojies pēc tās nakts, kas noceļ tautas no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Sargies, negriezies pie netaisnības, jo tā tev vairāk patīk nekā pacietība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Redzi, Dievs ir augsts savā spēkā; kur ir tāds mācītājs, kā Viņš?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kas Viņam raudzīs uz Viņa ceļu, vai kas uz Viņu sacīs: Tu dari netaisnību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Piemini, ka arī tu paaugstini Viņa darbu, par ko ļaudis dzied.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Visi ļaudis to skatās ar prieku, cilvēks to ierauga no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Redzi, Dievs ir augsts un neizmanāms, Viņa gadu pulku nevar izdibināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Viņš savelk ūdens lāsītes, un lietus līst no viņa miglas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Tas līst no padebešiem un pil uz daudz cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Vai var izprast, kā padebeši izplešas, un kā Viņa dzīvoklis rīb?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Redzi, Viņš ģērbjas zibeņu spīdumā un apklājās ar jūras dziļumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Jo tā Viņš soda tautas un dod barības papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Viņa abējās rokās spīdumi, un Viņš tiem rāda, kur lai sper.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Pērkona balss sludina Viņu nākam, un ganāmi pulki, ka Viņš tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Patiesi, par to trīc mana sirds un uzlec no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Klausiet, jel klausiet, kā Viņa pērkons rūc, un kāda balss no Viņa mutes iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Viņš to izlaiž pa visām debesīm, un Savu spīdumu pa visiem zemes galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Pēc tam rūc Viņa balss, Viņš liek pērkonam rībēt ar varenu skaņu un neaiztur tos (zibeņus), kad Viņa balss nāk dzirdama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Tas stiprais Dievs ar Savu balsi liek pērkonam rūkt brīnišķi, Viņš dara lielas lietas, ko neizprotam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Jo Viņš saka uz sniegu: krīti uz zemi, un uz stipro lietu, tad stiprais lietus ir klāt ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Viņš aizzieģelē visu cilvēku roku, lai Viņu pazīst visi ļaudis, ko viņš radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Zvēri iet savā alā un paliek savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'No dienvidu puses nāk vētra un no ziemeļa puses aukstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Caur tā stiprā Dieva pūšanu nāk salna, ka platas upes aizsalst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Viņš arī apkrauj ar ūdeņiem biezos mākoņus un izplēš Savus ugunīgos padebešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Tie griežas apkārt pēc Viņa gudrā prāta, ka tie padara visu, ko Viņš tiem pavēl pa visu plato pasauli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Vai par rīksti savai zemei, vai par labu Viņš tā liek notikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Liec to vērā, Ījab, stāvi klusu, un apdomā tā stiprā Dieva brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Vai tu zini, kad Dievs nodomājis, Savu debesu spīdumam likt spīdēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Vai tu zini padebešu lidināšanos, tā Visuzinātāja brīnumus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Tu, kam drēbes paliek karstas, kad Viņš zemi svilina dienas vidus bulā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Vai tu ar Viņu esi izpletis tos spožos padebešus, kas cieti stāv kā liets spieģelis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Stāsti mums, ko mums Viņam būs sacīt, jo aiz tumsības mēs nekā nevaram izdarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Vai Viņam lai saka, ka es runāšu? Jo kurš cilvēks vēlētos, lai viņu aprij!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Un nu gan saules gaismu neredz, kas pie debesīm spoži spīd, bet kad vējš pūš, tā skaidrojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'No ziemeļiem nāk zelts, - bet Dievs mājo bijājamā godībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'To Visuvareno, to mēs nepanāksim, kas liels spēkā, bet tiesu un taisnības pilnību Viņš negroza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Tāpēc cilvēki Viņu bīstas, Viņš neuzlūko nevienu pašgudru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Tad Tas Kungs Ījabam atbildēja no vētras un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kas tas tāds, kas (Dieva) padomu aptumšo ar neprātīgiem vārdiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Apjoz jel kā vīrs savus gurnus, tad Es tev gribu vaicāt, un tu Mani māci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kur tu biji, kad Es zemei liku pamatu? Izteic to, ja tev ir tāds gudrs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Vai tu zini, kas viņai mēru licis, jeb kas pār viņu ir vilcis mēra auklu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Uz ko viņas pamati ierakti, jeb kas licis viņas stūra akmeni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Kad rīta zvaigznes kopā priecīgi dziedāja, un visi Dieva bērni gavilēja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Jeb kas jūru aizslēdzis ar durvīm, kad tā izlauzās, un iznāca kā no mātes miesām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Kad Es to ģērbu ar padebešiem, un krēslībā ietinu tā kā tinamos autos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Kad Es tai noliku Savu robežu, un liku aizšaujamos un durvis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Un sacīju: tiktāl tev būs nākt un ne tālāki, un še būs apgulties taviem lepniem viļņiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Vai tu savā mūžā rītam licis aust, vai auseklim rādījis savu vietu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Lai satver zemes stūrus, ka tie bezdievīgie no tās top izkratīti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Ka tā pārvēršas kā zieģeļa vasks un visas lietas rādās kā apģērbā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Un bezdievīgiem zūd viņu gaišums, un pacelts elkonis salūst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Vai tu esi nācis līdz jūras avotam un staigājis bezdibeņu dziļumos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Vai tev atdarījušies nāves vārti, un vai tu esi redzējis nāves ēnas vārtus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Vai esi skatījies līdz pasaules malām? Stāsti, ja tu visu to zini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Kur ir tas ceļš, kur gaisma mājo, un tumsa - kur ir viņas vieta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Vai tu to varētu pārvest viņas robežā un izzināt viņas nama ceļus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Tu to zini, jo tai laikā tu biji piedzimis, un tev ir daudz to gadu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Vai tu esi nācis, kur tie sniega krājumi, un vai esi redzējis krusas krājumus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Ko Es taupu uz spaidu laiku, uz kaušanas un kara dienu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Pa kuru ceļu gaisma dalās un kā austrenis izplešas virs zemes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kas lietum rādījis, kur lai gāžas, un ceļu zibeņiem un pērkoniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Ka lietus līst, kur cilvēka nav, tuksnesī, kur neviens nedzīvo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Ka viņš dzirdina tukšo posta vietu un zālītei liek dīgt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Vai lietum ir tēvs, vai kas dzemdinājis rasas lāsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'No kura klēpja cēlies ledus, un no kā dzimusi debess salna,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Ka ūdeņi sastingst kā akmens, un jūras dziļumi aizsalst cieti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Vai tu vari sasiet Sietiņa saites, vai atraisīt Orijona zvaigžņu saiti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Vai tu zvaigznes vari izvest savā laikā un vadīt debess vāģus un viņu ratus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Vai tu zini debess likumus, jeb vai proti, kā tie valda virs zemes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Vai tu savu balsi vari pacelt uz padebešiem, lai ūdeņi plūst zemē uz tevi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Vai vari sūtīt zibeņus, ka tie iet un uz tevi saka: redzi, še mēs esam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kas lika gudrību tumšos mākoņos un prātu debess spīdumos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kas skaita mākoņus ar gudrību, un kas māk apgāzt padebešus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Ka pīšļi top aplieti, ka tie saskrien un salīp pītēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Vai tu māki medīt laupījumu priekš lauvas un pildīt jauno lauvu tukšo vēderu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'Kad tie nogulstas alās un biezos krūmos glūn?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kas gādā krauklim barību, kad viņa bērni uz Dievu brēc un šurpu turpu skraida, kad nav ko ēst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Vai tu zini to laiku, kad mežu kazas dzemdē, vai tu esi manījis stirnu dzemdēšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Vai tu vari skaitīt tos mēnešus, kad tās nesās, un vai zini to laiku, kad tās vedās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Kad tās lokās, saviem bērniem liek izplēsties cauri un nokrata savas sāpes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Viņu bērni nāk spēkā, uzaug laukā, tie iziet un neatgriežas pie tām atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kas meža ēzelim licis vaļā staigāt, un kas tā zvēra saites ir atraisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Kam Es klajumu esmu devis par māju un tuksnesi par dzīvokli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Viņš apsmej pilsētas troksni, un dzinēja brēkšanu tas nedzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Tas dzenās pa kalniem, kur viņam ir barība, un meklē visādu zaļu zāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Vai tu domā, ka meža vērsis tev kalpos, vai tas naktī paliks pie tavas siles?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Vai tu meža vērsi ar dzeņaukstēm māki piesiet pie arkla, vai tas pēc tava prāta ecēs ielejās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Vai tu uz to vari paļauties, ka tam daudz spēka, un viņu ņemsi savā darbā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Vai tu viņam vari uzticēt, ka tas tev atkal savāks tavu izsējumu un savedīs tavā piedarbā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Strausa spārni jautri plivinājās, vai tie ir mīlīgi, kā stārķa spārni un spalvas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Tas savas olas atstāj zemē, lai smiltīs silst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Un aizmirst, ka kāja tās var samīt, un lauka zvēri tās var samīdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Tas nežēlo savus bērnus, tā kā tie tam nepiederētu; un ka velti dējis, par to tas nebēdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Jo Dievs tam atņēmis gudrību un nav devis daļu pie saprašanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Bet kad tas projām šaujas, tad tas apsmej zirgu un jātnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Vai tu zirgam vari dot spēku un viņam kaklu pušķot ar krēpēm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Vai tu tam vēlējis lēkt kā sisenim? Kad tas lepni šņāc, tad jaizbīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Viņš cērt ar kāju ielejā un ir priecīgs ar spēku un iziet pretī apbruņotam pulkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Viņš smejas par bailēm un netrūkstas un nebēg atpakaļ no zobena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Kad bultas skan makā un šķēpi un zobeni zib,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Tad tas raustās, trako un uzcērt zemi un nav turams uz vietas, kad trumetes skan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Kad trumetes skan, tad tas iezviedzās, un samana kaušanu no tālienes, kara kungu saukšanu un kara troksni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Vai caur tavu padomu vanags lidinājās un izplēš savus spārnus pret dienasvidu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Vai uz tavu vārdu ērglis dodas uz augšu, un taisa savu ligzdu augstumā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Viņš dzīvo akmens kalnos un tur paliek uz augstām klintīm un kalnu galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'No turienes viņš lūko pēc barības, un viņa acis redz tālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Viņa bērni dzer asinis, un kur maitas, tur viņš ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Un Tas Kungs atbildēja Ījabam un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Vai vainotājs ies tiepties ar to Visuvareno? Kas Dievu pamāca, lai uz to atbild!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Bet Ījabs atbildēja Tam Kungam un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Redzi, es esmu mazs, ko lai es Tev atbildu? Es likšu roku uz muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Es reiz esmu runājis, bet vairs neatbildēšu; un otru reiz, bet vairs to nedarīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Un Tas Kungs atbildēja Ījabam no vētras un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Apjoz jel kā vīrs savus gurnus, tad Es tev gribu vaicāt, un tu mani māci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Vai tu Manu tiesu iznīcināsi, vai tu Mani pazudināsi, ka tu būtu taisns?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Jeb vai tev ir tāds elkonis kā tam stipram Dievam, vai tev ir pērkona balss kā viņam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Aptērpies tad ar greznību un augstību, un apģērbies ar lielu godu un godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Izgāz savas dusmības bardzību, un uzlūko visus lepnos un pazemo tos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Uzlūko visus lepnos un gāz tos zemē un satriec tos bezdievīgos savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Guldi tos kapā pīšļos un sedz viņu vaigus ar tumsību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Tad arī Es tevi teikšu, ka tava labā roka tev palīdzējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Redzi nu, beēmots (upes-zirgs), ko Es līdz ar tevi esmu radījis, ēd zāli kā vērsis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Redzi jel, viņa spēks ir viņa gurnos un viņa stiprums viņa vēdera dzīslās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Viņš kustina savu asti kā ciedra koku, viņa cisku dzīslas kopā ir sapītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Viņa kauli ir kā ciets varš, viņa locekļi kā dzelzs mieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Viņš ir Dieva ceļu pirmais; kas viņu radījis, Tas viņam devis savu zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Kalni viņam izdod barību, un tur trencās visi lauka zvēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Koku biezumā viņš apgulstas, niedrēs un dūņās paslēpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Koku biezums viņu apsedz ar savu ēnu, upes kārkli viņu apslēpj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Redzi, kad upe plūst, tad viņš nedreb, viņš ir drošs, kad Jardāne pat līdz viņa mutei celtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Vai viņu var gūstīt, viņa acīm redzot? vai viņam virvi var vilkt caur nāsīm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Vai tu levijatanu vari ķert ar makšķeri, jeb viņa mēli ar dziļi iemestu virvi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Vai tu viņam riņķi māki likt nāsīs un ar asmeni izdurt viņa žaunas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Vai tu domā, ka tas tevis daudz lūgsies un labus vārdus uz tevi runās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Vai viņš derēs derību ar tevi, ka tu viņu vari ņemt par mūžīgu vergu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Vai tu ar viņu varēsi spēlēties kā ar putniņu, jeb viņu saistīsi savām meitām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Vai zvejnieku biedrībā viņu pārdod, vai viņu izdala pircējiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Vai tu viņa ādu vari piedurt pilnu ar šķēpiem, jeb viņa galvu ar žebērkļiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Kad tu savu roku viņam pieliksi, tad pieminēsi, kāds tas karš, un vairs to nedarīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Redzi, tāda cerība ir velti; jau viņu ieraugot krīt gar zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Neviens nav tik drošs, viņu kaitināt, - kas tad būtu, kas Man varētu celties pretim?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Kas Man ko laba papriekš darījis, ka Man to bija atmaksāt? Kas ir apakš visām debesīm, tas Man pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Un lai vēl pieminu viņa locekļus, stiprumu un viņa vareno augumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Kas drīkstētu viņa bruņas atsegt, kas līst viņa zobu starpā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Kas viņa vaiga žokļus var atplēst? Ap viņa zobiem ir briesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Lepni ir viņa bruņu zvīņas, cieti kā ar zieģeli saspiesti kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Viens tik tuvu pie otra, ka ne vējš netiek starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Tie līp viens pie otra, un turas kopā, ka nešķiras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Viņš šķauda ugunis, un viņa acis ir kā rīta blāzmas stari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'No viņa mutes šaujās ugunis, degošas dzirksteles no tās izlec.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'No viņa nāsīm iziet dūmi kā no verdoša poda un katla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Viņa dvaša varētu iededzināt ogles, un liesmas iziet no viņa mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Viņa kakls ir visai stiprs, un viņa priekšā lec bailes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Viņa miesas locekļi kā sakalti, tie turas cieti kopā, ka nevar kustināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Viņa sirds ir cieta kā akmens un cieta kā apakšējais dzirnu akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Kad viņš ceļas, tad stiprie izbīstas, no bailēm tie paģībst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Kad viņam cērt ar zobenu, tas nekož, nedz šķēps, ne bulta, ne žebērklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Dzelzs priekš viņa kā salmi, un varš kā sapraulējis koks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Bulta viņu neaiztrieks; lingas akmeņi viņam ir kā pelus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Lielas bozes viņam ir kā pelus, viņš smejas, kad šķēps svelpj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Viņa pavēderē asi kasīkļi, un kā ar ecešām viņš brauc pa dubļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Viņš dara, ka dziļumi verd kā pods, un sajauc jūru kā zalves virumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Kur viņš gājis ceļš spīd; tie ūdens viļņi ir kā sudraboti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Virs zemes cits viņam nav līdzinājams, viņš tāds radīts, ka nebīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Viss, kas ir augsts, viņam nav nekas; viņš visu lepno zvēru ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Tad Ījabs Tam Kungam atbildēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Es atzīstu, ka Tu visu iespēji, un nekāds padoms Tev nav neizdarāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kas tas tāds, kas Dieva padomu neprātīgi aptumšo? Tā tad es esmu runājis, ko nesapratu, man visai brīnišķas lietas, ko nezināju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Klausi jel, un es runāšu, es tev vaicāšu, un Tu mani pamāci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Ausīm es no Tevis biju dzirdējis, bet nu mana acs Tevi redzējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Tāpēc man ir žēl un sirds man sāp par to pīšļos un pelnos. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Un notikās, kad Tas Kungs šos vārdus uz Ījabu bija runājis, tad Tas Kungs sacīja uz Elifasu no Temanas: manas dusmas ir iedegušās pret tevi un pret taviem diviem draugiem, jo jūs neesat pareizi runājuši par mani, kā Mans kalps Ījabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Tādēļ ņemat sev septiņus vēršus un septiņus aunus un ejat pie Mana kalpa Ījaba un upurējiet dedzināmos upurus priekš sevis, un lai Mans kalps Ījabs par jums lūdz; jo viņu Es uzlūkošu, ka Es jums nedaru pēc jūsu ģeķības; jo jūs neesat pareizi par Mani runājuši, kā Mans kalps Ījabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Tā Elifas no Temanas un Bildads no Šuhas un Cofars no Naēmas nogāja un darīja, kā Tas Kungs uz tiem bija sacījis, un Tas Kungs uzlūkoja Ījabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Un Tas Kungs novērsa Ījaba cietumu, kad viņš par saviem draugiem lūdza; un Tas Kungs atdeva Ījabam visu otrtik kā tam bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Un visi viņa brāļi un visas viņa māsas un visi, kas viņu iepriekš bija pazinuši, nāca pie viņa un ēda maizi ar to viņa namā, un žēloja viņu un iepriecināja viņu par visu nelaimi, ko Tas Kungs tam bija uzlicis. Un tie viņam deva ikkatrs vienu kesitu naudas un ikkatrs vienu zelta pieres rotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Un Tas Kungs svētīja Ījabu beidzot vairāk nekā papriekš, ka tam bija četrpadsmit tūkstoš avis un seštūkstoš kamieļi un tūkstoš jūgi vēršu un tūkstoš ēzeļu mātes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Viņam arī dzima septiņi dēli un trīs meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Un viņš nosauca tās pirmās vārdu Jemimu un tās otras vārdu Ķeciju un tās trešās vārdu Ķerenapuku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Un visā tai zemē tik skaistas sievas neatrada kā Ījaba meitas. Un viņu tēvs tām deva mantību starp viņu brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Un Ījabs dzīvoja pēc tam simts četrdesmit gadus un redzēja bērnus un bērnu bērnus līdz ceturtam augumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Un Ījabs nomira vecs un labi padzīvojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Svētīgs tas cilvēks, kas nestaigā bezdievīgo runās, nedz stāv uz grēcinieku ceļa, nedz sēž mēdītāju biedrībā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Bet kam labs prāts pie Tā Kunga bauslības, un kas Viņa bauslību pārdomā dienās, naktīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Jo tas ir kā koks stādīts pie ūdens upēm, kas savus augļus nes savā laikā, un viņa lapas nesavīst, un viss, ko viņš dara, tas labi izdodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Tā nav bezdievīgiem, bet tie ir kā pelus, ko vējš izputina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Tāpēc bezdievīgie nepastāvēs sodā, nedz grēcinieki taisno draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Jo Tas Kungs pazīst taisno ceļu, bet bezdievīgo ceļš ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Kāpēc pagāni trako, un ļaudis domā uz nelietību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Ķēniņi virs zemes saceļas un valdnieki sadomājās kopā pret To Kungu un pret Viņa svaidīto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Sarausim viņu saites un atmetīsim viņu virves!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Bet kas debesīs valda, smejas, un Tas Kungs tos tur par nieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Tad Viņš runās uz tiem Savās dusmās, un ar Savu bardzību Viņš tos iztrūcinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Bet Es Savu ķēniņu esmu svaidījis pār Ciānu, Savu svēto kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Es sludināšu likumu: Tas Kungs uz mani sacījis: tu esi Mans Dēls, šodien Es tevi esmu dzemdinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Prasi Man, tad Es tev došu tautas par mantību, un pasaules galus par īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Tu tos satrieksi ar dzelzs rīksti, kā podnieka trauku tu tos sadauzīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Nu tad, jūs ķēniņi, paliekat prātīgi, liekaties pamācīties, jūs soģi virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Kalpojiet Tam Kungam ar bijāšanu un priecājaties ar drebēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Skūpstāt To Dēlu, lai Viņš nedusmo un jūs bojā neejat uz ceļa, jo drīz Viņa dusmas iedegsies, bet svētīgi visi, kas pie Viņa tveras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Dāvida dziesma, kad tas bēga no sava dēla Absaloma. Ak Kungs! cik daudz manu pretinieku! Daudz, kas ceļas pret mani');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Daudz saka uz manu dvēseli: tai pestīšanas nav pie Dieva.(Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Bet Tu, Kungs, esi par bruņām ap mani, mana godība un kas paceļ manu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Es piesaucu To Kungu ar savu balsi, un Viņš mani paklausa no Sava svētā kalna. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Es apgūlos un aizmigu, un atmodos, jo Tas Kungs mani uztur');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Es nebīstos no daudz tūkstošiem ļaužu, kas visapkārt pret mani stājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Celies, Kungs, glābi mani, mans Dievs, jo Tu visiem maniem ienaidniekiem siti vaigā, Tu bezdievīgiem salauzi zobus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Pie Tā Kunga ir pestīšana! Tava svētība pār Taviem ļaudīm! (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Dāvida dziesma. Dziedātāju vadonim uz koklēm. Kad es saucu, tad paklausi mani, Tu, manas taisnības Dievs; bēdās Tu mani esi iepriecinājis; esi man žēlīgs un paklausi manu lūgšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Cilvēku bērni, cik ilgi mans gods paliks kaunā? Cik ilgi jūs mīlēsiet nīcīgas lietas un meklēsiet melus? (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Atzīstiet jel, ka Tas Kungs brīnišķi vadījis to, kas Viņu bīstas; Tas Kungs mani paklausa, kad es Viņu piesaucu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Dusmojiet, bet negrēkojiet, runājiet savā sirdī uz savām gultām un esiet klusu (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Upurējiet taisnības upurus un paļaujaties uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Daudzi saka: kas mums rādīs labumu? Pacel, ak Kungs, pār mums Sava vaiga gaišumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Tu manai sirdij devis vairāk prieka nekā viņiem, kad tiem labības un vīna papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Es apgulšos ar mieru un aizmigšu, jo Tu vien, Kungs dari, ka es droši dzīvoju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Dāvida dziesma. Dziedātāju vadonim uz stabulēm. Ak Kungs, klausies uz maniem vārdiem, ņem vērā manas domas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Samani manas kliegšanas balsi, mans ķēniņ un mans Dievs, jo es Tevi gribu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Rītos, ak Kungs, klausi manu balsi, rītos es uz Tevi gribu sataisīties un skatīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Jo Tu neesi tāds Dievs, kam bezdievība patīk; kas ir ļauns, tas pie Tevis nepaliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Trakotāji nepastāvēs priekš Tavām acīm, Tu ienīsti visus ļauna darītājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Tu nomaitā melkuļus, asins vainīgie un viltnieki Tam Kungam ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Bet es iešu Tavā namā caur Tavu lielo žēlastību, es pielūgšu Tava svētuma mājoklī, Tevi bīdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Kungs, vadi mani pēc Savas taisnības, manu glūnētāju dēļ, dari līdzenu Savu ceļu manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Jo viņu mutē nav nekādas patiesības, viņu sirdīs ir ļaunums, viņu rīkle ir atvērts kaps, ar savu mēli tie glauda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Sodi tos, ak Dievs, lai tie krīt no saviem padomiem; atstum tos viņu lielos noziegumos, jo tie pret Tevi sacēlušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Bet lai priecājās visi, kas uz Tevi cerē, mūžīgi lai tie gavilē, jo Tu tos pasargi; lai līksmojās iekš Tevis, kas Tavu vārdu mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Jo Tu, Kungs, svētīsi to taisno, un to pušķosi ar žēlastību kā ar bruņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Dāvida dziesma. Dziedātāju vadonim uz koklēm ar astoņām stīgām. Ak Kungs, nesodi mani Savā dusmībā, un nepārmāci mani Savā bardzībā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Kungs, esi man žēlīgs, jo es esmu noguris, dziedini mani, Kungs, jo mani kauli ir iztrūkušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Un mana dvēsele ir ļoti iztrūkusies, bet Tu, Kungs, cik ilgi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Griezies atpakaļ, Kungs, izglābi manu dvēseli, atpestī mani Tavas žēlastības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Jo nāvē Tevi nepiemin; kas kapā Tevi slavēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Es esmu piekusis no savas vaidēšanas, uz savas gultas es raudu cauru nakti, mana guļama vieta plūst no asarām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Mana acs ir noģindusi no skumības, un ir novītusi manu ienaidnieku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Atkāpjaties no manis, visi ļauna darītāji, jo Tas Kungs klausa manu raudu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Tas Kungs klausa manu lūgšanu, manu pielūgšanu Tas Kungs pieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Visi mani ienaidnieki paliks kaunā, tie ļoti iztrūksies, atkāpsies un paliks kaunā piepeši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Dāvida dziesma, ko viņš Tam Kungam dziedāja, par Benjaminieti Kušu. Kungs, mans Dievs, uz Tevi es paļaujos, atpestī mani no visiem maniem vajātājiem un izglābi mani,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Ka tas manu dvēseli nelaupa kā lauva, to saplosīdams, tādēļ ka glābēja nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Kungs, mans Dievs, ja to esmu darījis, ja netaisnība ir manās rokās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Ja esmu ļaunu maksājis tam, kas mierīgi ar mani dzīvoja, vai aplaupījis to, kas mani bez vainas apbēdināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Tad lai ienaidnieks manu dvēseli vajā un panāk, lai samin manu dzīvību pie zemes un noliek manu godu pīšļos. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Celies, ak Kungs, Savā dusmībā, stājies pretī manu spaidītāju bardzībai, uzmosties manis labad; Tu tiesu turēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Tautu pulks lai metās ap Tevi, bet Tu pār to atkal pacelies augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Tas Kungs nesīs tiesu tām tautām; tiesā mani, Kungs, pēc manas taisnības un manas bezvainības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Lai jel beidzās bezdievīgo niknums, bet stiprini to taisno, jo Tu pārbaudi sirdis un īkstis, ak taisnais Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Manas priekšturamās bruņas ir Dieva rokā, Viņš palīdz tiem sirds taisniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Dievs ir taisns soģis un tāds Dievs, kas ikdienas biedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Ja kas negrib atgriezties, tad viņš savu zobenu trinis, savu stopu uzvilcis un sataisījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Un priekš tā nāvīgus ieročus salicis, savas bultas darījis degošas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Redzi, kāds ieņem netaisnību un nesās ar nelaimi, bet dzemdē nieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Tas bedri racis un izmetis, bet iekritis tai bedrē, ko taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Viņa ļaunums atgriezīsies uz viņa galvu, un viņa varas darbs nometīsies uz viņa galvas virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Es slavēšu To Kungu Viņa taisnības dēļ, un dziedāšu Tā Kunga, tā Visaugstākā, Vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Dāvida dziesma, dziedātāju vadonim, uz Ģittit. Kungs, mūsu valdītājs, kāds augsti godājams ir Tavs Vārds visās zemēs, kas esi cēlis Savu godību pār debesīm!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'No bērniņu un zīdāmo mutes Tu esi sataisījis spēku, Savu pretinieku dēļ, apklusināt ienaidnieku un atriebēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Kad es redzu Tavu debesi, Tavu pirkstu darbu, mēnesi un zvaigznes, ko Tu esi taisījis: -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Kas ir tas cilvēks, ka Tu viņu piemini, un tas cilvēka bērns, ka Tu viņu uzlūko?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Tu viņu mazliet no Dieva esi atšķīris, un ar godību un jaukumu Tu viņu esi pušķojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Tu viņu esi iecēlis par valdnieku pār Tavu roku darbiem, visu Tu esi licis apakš viņa kājām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Avis un vēršus visnotaļ, arī lauka zvērus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Putnus apakš debess, zivis jūrā, kas jūras ceļus pārstaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Kungs, mūsu valdītājs, kāds augsti godājams ir Tavs Vārds visās zemēs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Dāvida dziesma, dziesmu vadonim, pēc „mūt-laben.“Es pateikšos Tam Kungam no visas sirds, es sludināšu visus Tavus brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Es priecāšos iekš Tevis un līksmošos, es dziedāšu Tavam Vārdam, ak Visuaugstākais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ka mani ienaidnieki ir griezušies atpakaļ, krituši un bojā gājuši Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Jo Tu esi iztiesājis manu tiesu un manu tiesas lietu, Tu sēdi uz Sava godības krēsla, taisns soģis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Tu rāji pagānus un nomaitā bezdievīgo, viņu vārdu Tu izdeldi mūžīgi mūžam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Ienaidnieks pagalam! Mūžīgi izpostīts! Pilsētas Tu esi nopostījis, viņu piemiņa ir iznīkusi līdz ar viņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Bet Tas Kungs valda mūžīgi, Savas godības krēslu Viņš sataisījis uz tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Un Viņš tiesās pasauli ar taisnību, un spriedīs par tautām ar patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Un Tas Kungs būs patvērums tam nabagam, patvērums bēdu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Un uz Tevi cerēs, kas Tavu Vārdu pazīst, jo Tu, ak Kungs, neatstāj, kas Tevi meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Dziedājiet Tam Kungam, kas Ciānā mājo, sludinājiet tiem ļaudīm Viņa darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Jo Viņš piemeklē asinis, Viņš tās piemin, Viņš neaizmirst nabaga brēkšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Esi man žēlīgs, ak Kungs, uzlūko manas bēdas, kas man notiek no maniem ienaidniekiem; Tu mani paaugstini no nāves vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Tādēļ es sludināšu visu Tavu slavu Ciānas meitas vārtos, es līksmošos par Tavu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Pagāni nogrimuši tai bedrē, ko tie bija rakuši, viņu kāja ir gūstīta tai tīklā, ko tie bija apslēpuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Tas Kungs ir parādījies, Viņš tiesu nesis, bezdievīgais ir satīstījies savā roku darbā: (kokļu skaņa. Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Bezdievīgie griezīsies atpakaļ uz elli, visi pagāni, kas Dievu aizmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Jo nabags nemūžam netaps aizmirsts, un bēdu ļaužu cerība neies bojā ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Celies, ak Kungs, ka cilvēki nepārvar, lai pagāni top tiesāti priekš Tava vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Met, ak Kungs, bailību uz tiem, lai pagāni atzīst, ka tie ir cilvēki. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Kāpēc Tu, Kungs, stāvi no tālienes, paslēpies bēdu laikā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'No bezdievīgā lepnības bailes nāk nabagam; lai tie top gūstīti savās blēņās, ko tie izdomājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Jo bezdievīgais lielās ar savas dvēseles kārību, plēsējs lād, viņš zaimo To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Bezdievīgais savā lielā lepnībā nebēdā par nevienu; visas viņa domas ir: Dieva neesam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Viņa ceļi allažiņ izdodas, Tava sodība ir tālu no viņa; šņākdams viņš turas pret visiem saviem pretiniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Viņš saka savā sirdī: es netapšu kustināts, jo ļaunumā es nenākšu līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Viņa mute pilna lāstu un viltus un varmācības, apakš viņa mēles ir grūtums un bēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Viņš, sēž paslēpies aiz sētām, viņš nokauj nenoziedzīgo slepenās vietās, viņa acis glūn uz nabagu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Viņš glūn slepenībā kā lauva savā alā, viņš glūn sakampt bēdīgo, viņš sakampj bēdīgo, to ievilkdams savā tīklā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Viņš tup un nometās un uzkrīt ar varu nelaimīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Viņš saka savā sirdī: Dievs ir aizmirsis, Viņš Savu vaigu apslēpis, Viņš neredz ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Celies, ak Dievs Kungs, pacel Savu roku, neaizmirsti bēdīgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Kādēļ bezdievīgais Dievu zaimos un sacīs savā sirdī: Tu nemeklēsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Tu gan redzi, jo Tu uzlūko mokas un sirdēstus, likdams to Savās rokās; nelaimīgais uz Tevi paļaujas, Tu esi bāriņa palīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Salauz bezdievīgā elkoni un meklē ļaunā bezdievību, ka to vairs neatrod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Tas Kungs ir ķēniņš mūžīgi mūžam; pagāni ir bojā gājuši no Viņa zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Nabagu ilgošanos Tu klausi, ak Kungs! Tu viņiem sirdi stiprini, Tava auss to liek vērā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Tiesu nesdams bāriņam un apspiestam, lai cilvēks, kas no zemes, vairs nedara varas darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Dāvida dziesma. Dziedātāju vadonim. 2. Es paļaujos uz To Kungu. Kā tad jūs sakāt uz manu dvēseli: skrej uz saviem kalniem kā putns!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Jo redzi, bezdievīgie uzvelk stopu, tie liek savas bultas uz auklām, slepeni šaut tos, kas sirds taisni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Jo pamati top nopostīti; ko darīs taisnais?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Tas Kungs ir Savā svētā namā, Tā Kunga godības krēsls ir debesīs, Viņa acis skatās, Viņa acu skati pārmana cilvēku bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Tas Kungs pārbauda taisno, bet bezdievīgo un varas darbu mīļotāju Viņa dvēsele ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Pār bezdievīgiem Viņš liks līt valgiem, ugunij un sēram, un varena vētra būs viņu daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Jo Tas Kungs ir taisns, Viņš mīļo taisnību, Viņa vaigs uzlūko taisno.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Dāvida dziesma, dziedātāju vadonim uz astoņām stīgām. Palīdz, ak Kungs! Jo svētie ir zustin zuduši, un ticīgo ir maz starp cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Tie runā nelietību ikviens ar savu tuvāko; lūpām smaidīdami, ar divējādu sirdi tie runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Lai Tas Kungs izdeldē visu liekulību, to mēli, kas runā lielību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Kas saka: mēs pārvarēsim ar savu mēli, mūsu mute ir ar mums; kas mums ir par kungu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Tad nu nabagu postīšanas dēļ un bēdīgo nopūšanās dēļ Es celšos, saka Tas Kungs: Es došu pestīšanu tam, kas pēc tās ilgojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Tā Kunga vārdi ir šķīsti vārdi, kā sudrabs mālu traukā kausēts un septiņkārt šķīstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Kaut Tu, ak Kungs, tos gribētu pasargāt, kaut Tu mūs gribētu paglabāt no šīs cilts mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Bezdievīgie lepni staigā visapkārt, kur netiklība augsti ceļas starp cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Dāvida dziesma. Dziedātāju vadonim. Cik ilgi, ak Kungs, Tu mani it visai aizmirsti? Cik ilgi Tu apslēpi Savu vaigu priekš manis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Cik ilgi man būs padomu meklēt savā dvēselē un savā sirdī ikdienas baiļoties? Cik ilgi mans ienaidnieks pār mani paaugstināsies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Skaties, paklausi mani, ak Kungs, mans Dievs, apgaismo manas acis, ka es nāvē neaizmiegu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Ka mans ienaidnieks nesaka: es viņu esmu pārvarējis, un ka mani pretinieki nepriecājās, ka es šaubos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Bet es cerēju uz Tavu žēlastību, mana sirds līksmojās iekš Tavas pestīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Es dziedāšu Tam Kungam, ka Viņš man labu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Dāvida dziesma. Dziedātāju vadonim. Ģeķi saka savā sirdī Dieva nav; tie ir samaitājušies un sagānījušies ar savu darbošanos, neviena nav, kas labu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Tas Kungs skatās no debesīm uz cilvēku bērniem, raudzīt, vai jel kas būtu prātīgs, kas meklē Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Bet tie visi atkāpušies, visnotaļ smirdoši tapuši, neviena nav, kas labu dara, nav it neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Vai tad nav nekādas atzīšanas tiem ļauna darītājiem, kas ēd manus ļaudis, tā kā ēd maizi, bet To Kungu tie nepiesauc?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Tad tie bīdamies izbīstas, jo Dievs ir pie tās taisnās cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Jūs nievājat nabaga padomu, bet Tas Kungs ir viņa patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ak! Kaut no Ciānas nāktu Israēla pestīšana! Kad Tas Kungs atkal atved Savus cietuma ļaudis, tad Jēkabs priecāsies un Israēls līksmosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Dāvida dziesma. Kungs, kas mājos Tavā dzīvoklī? un kas dzīvos uz Tava svētā kalna?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Kas bezvainīgi staigā un taisnību dara un patiesību runā no sirds dziļuma;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Kas ar savu mēli citu neaprunā, savam tuvākam ļauna nedara, un neceļ kauna valodu pret savu tuvāko;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Kas bezdievīgo neciena, bet godā tos, kas To Kungu bīstas, kas zvērējis sev par skādi, un to nepārkāpj;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Kas savu naudu nedod uz netaisniem augļiem un neņem dāvanas pret nenoziedzīgo. Kas tā turas, tas nešaubīsies ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Dāvida sirds dziesma. Pasargi mani, ak Dievs! jo es paļaujos uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Es saku uz To Kungu: Tu esi Tas Kungs, bez Tevis man labuma nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Pie tiem svētiem, kas virs zemes, un tiem godīgiem ir viss mans labais prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Tiem, kas pieņem citu dievu, būs lielas sāpes; es neupurēšu viņu asiņu dzeramos upurus, un neņemšu savā mutē viņu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Tas Kungs ir mana tiesa un mana daļa, Tu glabā manu mantas tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Man daļa tikusi jaukā vietā, tiešām, man ir nākusi skaista manta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Es slavēšu To Kungu, kas man dod padomu, pat naktī mana sirds mani pamāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Es turu To Kungu bez mitēšanās savā priekšā, jo Viņš man ir pa labai rokai, - es nešaubīšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Tādēļ mana sirds priecājās, un mans gods līksmojās, un pat mana miesa dzīvos droši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Jo Tu manu dvēseli nepametīsi kapā, Savam Svētam Tu neliksi redzēt satrūdēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu man dari zināmu dzīvības ceļu, priekš Tava vaiga ir līksmošanās pilnība, un prieks un jaukums pie Tavas labās rokas mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Dāvida lūgšana. Kungs, ņem vērā taisnību, klausies uz manu brēkšanu, griez savas ausis uz manu lūgšanu, kas nenāk no viltīgām lūpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'No tava vaiga lai nāk mana tiesa; tavas acis skatās uz to, kas ir taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Tu pārbaudi manu sirdi, Tu piemeklē to naktīs, Tu mani esi kausējis un nekā neatradis; es esmu apņēmies, ka manai mutei nebūs pārkāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Pie cilvēku darbiem es sargos caur Tavas mutes vārdu no pārkāpēja pēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Uzturi manu gājienu uz Taviem ceļiem, ka mani soļi nešaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Es Tevi piesaucu, jo Tu mani paklausi, ak Dievs! Griez\' Savu ausi pie manis, klausi manu valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Parādi brīnišķi Savu žēlastību, Tu, kas glābi no pretiniekiem tos, kas tvērās pie Tavas labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Pasargi mani kā acs raugu acī, apslēp mani savu spārnu pavēnī');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'No bezdievīgo vaiga, kas mani posta, no maniem nikniem ienaidniekiem, kas ap mani apmetās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Savu cieto sirdi tie aizslēguši, ar savu muti tie runā lepni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Tie nu ir visapkārt ap mums mūsu ceļos, ar savām acīm tie glūn, mūs gāzt pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Viņa ģīmis ir kā lauva, kas tīko saplosīt, un kā jauns lauva, kas sēž paslēpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Celies, Kungs, steidzies viņam pretī, nogāz viņu, izglāb ar Savu zobenu manu dvēseli no bezdievīgā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'No tiem ļaudīm ar Savu roku, ak Kungs! no šās pasaules ļaudīm, kam sava tiesa ir šai dzīvībā, kam vēderu Tu pildi ar Savu mantu, kam dēlu papilnam, un kas savu mantu atstāj saviem bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Bet es skatīšu Tavu vaigu iekš taisnības, uzmodies mielošos no Tava ģīmja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Dziedātāju vadonim, Dāvida, Tā Kunga kalpa, dziesma. Šīs dziesmas vārdus viņš runājis uz To Kungu, kad Tas Kungs viņu bija izglābis no visu ienaidnieku rokas un no Saula rokas; tad viņš sacīja: No sirds dziļuma es Tevi mīlēju, Kungs, mans stiprums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Tas Kungs ir mans akmens kalns, mana pils un mans glābējs, mans stiprais Dievs, mans patvērums, uz ko es paļaujos, manas priekšturamās bruņas un mans pestīšanas rags un mans augstais palīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Es piesaukšu To Kungu, kas teicams, tad es tapšu atpestīts no saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Nāves saites ap mani tinās, un Beliala(iznīcības) upes mani izbiedēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Elles saites mani apņēma, un nāves valgi mani pārvarēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Savās bēdās es piesaucu To Kungu un kliedzu uz savu Dievu, tad Viņš klausīja manu balsi no Sava nama, un mana brēkšana Viņa priekšā nāca Viņa ausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Zeme tapa kustināta un drebēja, un kalnu pamati trīcēja un kustējās, kad Viņš apskaitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Dūmi uzkāpa no Viņa nāsīm, un rijoša uguns no Viņa mutes, zibeņi no Viņa iedegās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Viņš nolaida debesis un nokāpa, un tumsa bija apakš Viņa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Un Viņš brauca uz ķeruba un skrēja, Viņš skrēja ātri uz vēja spārniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Viņš lika tumsību Sev par apsegu, Viņa dzīvoklis ap Viņu bija ūdeņu tumsība un biezi padebeši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'No spožuma Viņa priekšā šķēlās Viņa padebeši ar krusu un degošiem zibeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Tas Kungs lika pērkoniem rībēt no debesīm, un tas Visuaugstais pacēla Savu balsi, krusu un degošus zibeņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Un Viņš meta Savas bultas un tos izklīdināja, un daudz zibeņus un tos iztrūcināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Un ūdeņu dziļumi rādījās un zemes pamati tapa atklāti no Tavas bāršanās, - ak Kungs, no Tavu nāšu dvašas pūšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Viņš izstiepa roku no augstības un ņēma mani, Viņš mani izvilka no lieliem ūdeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Viņš mani atpestīja no mana stiprā ienaidnieka un no maniem nīdētājiem, jo tie bija jo vareni ne kā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Tie cēlās pret mani manā bēdu laikā; bet Tas Kungs bija mans patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Un Viņš mani izveda klajumā, Viņš mani izrāva, jo Viņam bija labs prāts uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Tas Kungs man atmaksā pēc manas taisnības, pēc manu roku šķīstības Viņš man atdod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Jo es esmu sargājis Tā Kunga ceļus, un neesmu atkāpies no sava Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Jo visas Viņa tiesas ir manā priekšā, un Viņa likumus es nelieku nost no sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Bet es esmu bezvainīgs Viņa priekšā un sargos no grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Un Tas Kungs man atdos pēc manas taisnības, pēc manu roku šķīstības priekš Viņa acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Pie tiem svētiem Tu rādies svēts un pie tiem sirdsskaidriem Tu rādies skaidrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Pie tiem šķīstiem Tu rādies šķīsts, un pie tiem pārvērstiem (un pretdabiskiem) Tu pārvērties (un maldini).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Jo bēdīgus ļaudis Tu atpestī un lepnas acis Tu pazemo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Jo Tu apgaismo manu spīdekli; Tas Kungs, mans Dievs, dara gaišu manu tumsību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Jo ar Tevi es varu sadauzīt kara spēku, un ar savu Dievu es varu lēkt pār mūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Tā stiprā Dieva ceļš ir bezvainīgs, Tā Kunga valoda ir šķīsta, Viņš ir par priekšturamām bruņām visiem, kas uz Viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Jo kur ir kāds Dievs kā vien Tas Kungs? Un kur ir kāds patvērums kā vien mūsu Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Dievs, tas mani apjož ar spēku un dara manus ceļus bezvainīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Viņš man kājas dara kā stirnām, un mani uzceļ manā augstā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Viņš manu roku māca karot, tā ka mans elkonis uzvelk vara stopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Un Tu man dod Savas pestīšanas priekšturamās bruņas, un Tava labā roka mani satur, un Tava laipnība mani paaugstina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Maniem soļiem Tu esi darījis platu ceļu apakš manis, ka mani krimšļi nav slīdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Es dzīšos pakaļ saviem ienaidniekiem un tos panākšu, un negriezīšos atpakaļ, kamēr tos būšu izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Es tos sadauzīšu, ka tie nevarēs celties, tiem jākrīt apakš manām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Jo Tu mani apjozīsi ar spēku uz karu, Tu nospiedīsi apakš manis, kas pret mani ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Tu maniem ienaidniekiem liksi bēgt manā priekšā, un savus nīdētājus es iznīcināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Tie brēks, bet glābēja nav, uz To Kungu, bet Viņš tiem neatbild.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Es tos sagrūdīšu kā pīšļus vēja priekšā, un tos izārdīšu kā dubļus uz ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Tu mani izglābsi no ļaužu ķildām, Tu mani iecelsi tautām par galvu; ļaudis, ko es nepazinu, man kalpos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Tie man klausīs ar paklausīgām ausīm, svešnieku bērni manā priekšā mīlīgi rādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Svešinieku bērni nonīks un drebēdami izies no savām pilīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Tas Kungs ir dzīvs, un slavēts lai ir mans patvērums, un augsti slavēts lai ir Dievs, mans Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Tas stiprais Dievs, kas man dod atriebšanu, un tautas nomet apakš manis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Kas mani izrauj no maniem ienaidniekiem; Tu mani paaugstini pār tiem, kas pret mani ceļas, Tu mani izglāb no varas darītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Tāpēc, ak Kungs, es Tevi gribu slavēt starp tautām un dziedāt Tavam vārdam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Jo Tu glābi Savu ķēniņu ar lielu glābšanu, un parādi žēlastību Savam svaidītam, Dāvidam un viņa dzimumam mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Dāvida dziesma. Dziedātāju vadonim. Debesis izteic tā stiprā Dieva godu, un izplatījums pasludina Viņa roku darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Diena dienai to liecina, un nakts naktij to dara zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Nav ne valodas ne runas, kur viņu balsi nedzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Viņu skaņa iziet pa visu zemes virsu, un viņu valoda līdz pasaules galam. Viņš saulei telti tur darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Un tā iziet kā brūtgāns no sava kambara, un priecājās kā kāds varonis ceļu tecēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'No viena debess gala viņa uzlec un tek apkārt līdz otram galam, un priekš viņas karstuma nekas nav apslēpts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Tā Kunga bauslība ir pilnīga un atspirdzina dvēseli, Tā Kunga liecība ir patiesīga un dara neprātīgo gudru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Tā Kunga pavēles ir taisnas un dara sirdi priecīgu, Tā Kunga bauslis ir šķīsts un apskaidro acis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Tā Kunga bijāšana ir šķīsta un pastāv mūžīgi, Tā Kunga tiesas ir patiesība un visas kopā taisnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Tās ir vairāk iekārojamas nekā zelts un daudz tīra zelta un, tās ir saldākas nekā medus un tīrs medus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Arī tavs kalps caur tām top skaidri pamācīts, tam ir daudz algas, kas tās tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Kas samana tās maldīšanās? Šķīsti mani no apslēptām vainām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Pasargi Savu kalpu arī no tīšiem grēkiem, ka tie nevalda pār mani; tad es būšu bezvainīgs un šķīsts no lielām pārkāpšanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Lai Tev patīk manas mutes valoda un manas sirds domas Tavā priekšā, ak Kungs, mans patvērums un mans Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Dāvida dziesma. Dziedātāju vadonim. Lai Tas Kungs tevi paklausa bēdu laikā, lai Jēkaba Dieva vārds tevi paaugstina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Lai Viņš tev palīdzību sūta no svētās vietas un tevi spēcina no Ciānas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Lai Viņš piemin visus tavus upurus, un tavus dedzināmos upurus tur par trekniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Lai Viņš tev dod pēc tavas sirds, un piepilda visus tavus padomus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Mēs priecāsimies par tavu pestīšanu, un sava Dieva vārdā mēs celsim karogu; lai Tas Kungs piepilda visas tavas lūgšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Nu es zinu, ka Tas Kungs Savam svaidītam palīdz; Viņš to paklausīs no Savām svētām debesīm caur Savas labās rokas stipro pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Šie paļaujas uz ratiem un šie uz zirgiem, bet mēs pieminam Tā Kunga, sava Dieva, vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Tie ir gāzušies un krituši, bet mēs esam cēlušies un stāvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Ak Kungs, palīdzi ķēniņam! Lai viņš mūs paklausa tai dienā, kad saucam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Dāvida dziesma. Dziedātāju vadonim. Kungs, par Tavu spēku ķēniņš priecājās, un cik ļoti viņš līksmojās par Tavu pestīšanu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Tu viņam dod, ko viņa sirds kāro, un neliedzi, ko viņa mute lūdz. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Jo Tu nāci viņam pretim ar labu svētīšanu, Tu lieci uz viņa galvu kroni no šķīsta zelta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Viņš lūdz no Tevis dzīvību, to Tu viņam esi devis, ilgu dzīvošanu mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Viņam ir liela godība caur Tavu pestīšanu, Tu lieci godību un jaukumu uz viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Jo Tu viņu iecēli par svētību mūžīgi, Savā priekšā Tu viņu iepriecini ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Jo ķēniņš cerē uz To Kungu, un caur tā Visuaugstākā žēlastību viņš nešaubīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Tava roka atradīs visus Tavus ienaidniekus, Tava labā roka atradīs Tavus nīdētājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Tu tos darīsi kā degošu cepli Savas dusmības laikā; Tas Kungs tos aprīs Savā bardzībā, un uguns tos norīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Viņu augļus Tu nomaitāsi no zemes virsas un viņu dzimumu no cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Jo tie ļaunu pret Tevi darījuši, tie izdomāja negantību, bet nespēja to izdarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Tu darīsi, ka tie griež muguru, Savu stopu Tu stiepsi pret viņu vaigiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Paaugstinājies, Kungs, Savā stiprumā, tad dziedāsim un teiksim Tavu varu ar dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Dāvida dziesma. Dziedātāju vadonim pēc: „rīta blāzmas stirna“. Mans Dievs! Mans Dievs! Kāpēc Tu mani esi atstājis? Tu esi tālu no manas palīdzības, no manas kaukšanas vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mans Dievs, es saucu dienā, bet Tu man neatbildi, un nakti es arī klusu neciešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Bet Tu esi svēts, dzīvodams starp Israēla slavas dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Uz Tevi mūsu tēvi cerējuši, tie ir cerējuši, un Tu tos esi izglābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Uz Tevi tie saukuši un ir izpestīti, tie cerējuši uz Tevi un nav palikuši kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Bet es esmu tārps un ne cilvēks, cilvēku apsmiekls un ļaužu nicināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Visi, kas mani redz, mani apmēda, atplēš lūpas un krata galvu sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Viņš to Tam Kungam sūdzējis; lai Tas viņu izrauj un viņu izglābj, ja Tam pie viņa ir labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Tomēr Tu tas esi, kas mani izvedis no mātes miesām; Tu man licis paļauties uz Tevi no mātes krūtīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Uz Tevi es esmu mests no mātes klēpja, no mātes miesām Tu esi mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Neesi tālu no manis, jo bailība ir tuvu, jo palīga nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Lieli vērši mani apstājuši, trekni buļļi ap mani apmetušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Tie atplēš savu rīkli pret mani kā lauva, plezdams un rūkdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Es esmu izgāzts kā ūdens, visi mani kauli ir izlauzti, mana sirds ir manās miesās kā izkausēts vasks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Mans spēks ir izkaltis kā poda gabals, un mana mēle līp pie mana zoda, un Tu mani nolieci nāves pīšļos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Jo suņi mani apstājuši, un ļaundarītāju bars ap mani ir apmeties, tie manas rokas un manas kājas ir izurbuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Es visus savus kaulus varu skaitīt, bet viņi skatās un lūko uz mani ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Tie dala manas drēbes savā starpā un met kauliņus par manu apģērbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Bet Tu, ak Kungs, neesi tālu, mans stiprums, steidzies man palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Izglāb manu dvēseli no zobena, manu vientuli no suņu varas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Izpestī mani no lauvas rīkles un paklausi mani no vēršu ragiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Es sludināšu Tavu vārdu saviem brāļiem, es Tevi slavēšu draudzes vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Slavējiet To Kungu, jūs, kas Viņu bīstaties, viss Jēkaba dzimums lai Viņu godā, un bīstaties, viss Israēla dzimums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Jo Viņš nav nicinājis nedz apsmējis bēdīga bēdas, nedz no tā apslēpis Savu vaigu, un kad tas Viņu piesauca, tad Viņš paklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'No Tevis es dziedāšu tai lielā draudzē, es maksāšu savus solījumus to priekšā, kas Viņu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Tie bēdīgie ēdīs un būs paēduši, un kas To Kungu meklē, Viņu slavēs; jūsu sirds dzīvos mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Visi zemes gali to pieminēs un atgriezīsies pie Tā Kunga, un visas pagānu tautas klanīsies Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Jo Tam Kungam pieder tā valstība, un Viņš valda pār tām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Visi treknie virs zemes ēdīs un pielūgs, visi, kas pīšļos guļ, klanīsies Viņa priekšā, arī tie, kas nevarēja uzturēt savu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Viņam būs dzimums, kas Viņam kalpos, par To Kungu sludinās līdz radu radiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Nāks un sludinās Viņa taisnību tiem ļaudīm, kas vēl dzims, ka Viņš to ir darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Dāvida dziesma. Tas Kungs ir mans gans, man netrūks nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Viņš man liek ganīties uz zālainām ganībām, Viņš mani vada pie palēna ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Viņš atspirdzina manu dvēseli, Viņš mani ved uz taisnības ceļiem Sava Vārda dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Jebšu es arī staigātu nāves ēnas ielejā, taču ļaunuma nebīstos; jo Tu esi pie manis, Tavs koks(ganu vēzda) un Tavs zizlis mani iepriecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Tu sataisi manā priekšā galdu pret maniem ienaidniekiem, Tu svaidi manu galvu ar eļļu, mans biķeris ir papilnam pieliets.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Tiešām, labums un žēlastība mani pavadīs visu manu mūžu, un es palikšu Tā Kunga namā vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Dāvida dziesma. tā zeme pieder Tam Kungam ar savu pilnumu, zemes virsas, un kas uz tā dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Jo Viņš to pie jūras stādījis un pie upēm to stiprinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kas kāps uz Tā Kunga kalnu? Un kas stāvēs Viņa svētā vietā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Kam ir nenoziedzīgas rokas un šķīsta sirds, kam dvēsele nenesās uz nelietību, un kas ar viltu nezvērē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Tas dabūs svētību no Tā Kunga, un taisnību no Dieva, sava Pestītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Šī tā cilts, kas pēc Viņa vaicā, kas tavu vaigu meklē iekš Jēkaba. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Jūs vārti, paceliet savas palodas, un topiet paaugstinātas, jūs mūžīgās durvis, lai tas godības Ķēniņš ieiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kas tas tāds godības Ķēniņš? Tas Kungs, stiprs un varens, Tas Kungs, varens karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Jūs vārti, paceliet savas palodas, un paaugstinājaties, jūs mūžīgās durvis, lai tas godības Ķēniņš ieiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kas tas tāds godības Ķēniņš? Tas Kungs Cebaot, tas ir tas godības Ķēniņš. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Dāvida dziesma. Mana dvēsele ilgojās, Kungs, pēc Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mans Dievs, uz Tevi es cerēju, nepamet mani kaunā, lai mani ienaidnieki par mani nepriecājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Jo neviens, kas uz Tevi gaida, nepaliek kaunā; tie top kaunā, kas velti dodas uz viltību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Kungs, dari man zināmus Tavus ceļus, māci man Tavas tekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Vadi mani Tavā patiesībā un māci mani, jo Tu esi mans Dievs un Pestītājs; cauru dienu es Tevi gaidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Piemini, Kungs, Savu apžēlošanu un Savu žēlastību, kas no mūžības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Nepiemini manas jaunības grēkus nedz manas pārkāpšanas, bet piemini mani pēc Tavas žēlastības, Tavas lēnības dēļ ak Kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Tas Kungs ir labs un taisns, tāpēc Viņš grēciniekiem māca to ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Pazemīgos Viņš vada taisnībā, un māca pazemīgiem Savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Tā Kunga ceļi visi ir žēlastība un patiesība tiem, kas tur Viņa derību un liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Tava vārda dēļ, ak Kungs! piedod manu noziegumu, jo tas ir liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kas ir tas, kas To Kungu bīstas? tam Viņš mācīs to ceļu, kas uzņemams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Viņa dvēsele mitīs labumā, un viņa dzimums iemantos zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Tā Kunga noslēpums ir pie tiem, kas Viņu bīstas, un Viņa derība tiem dod saprašanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Manas acis vienmēr raugās uz To Kungu, jo Viņš izvilks manu kāju no tīkla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Griezies pie manis un esi man žēlīgs, jo es esmu vientulis un bēdīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Mana sirds bailība ir varen liela, izved mani no manām bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Uzlūko manas bēdas un manas mokas, un piedod visus manus grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Redzi, ka daudz ir manu ienaidnieku, un ka tie ar briesmīgu nīdēšanu mani ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Pasargi manu dvēseli un izglāb mani, nepamet mani kaunā, jo es paļaujos uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Sirds skaidrība un taisnība lai mani pasargā, jo es gaidu uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Ak Dievs, izpestī Israēli no visām viņa bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Dāvida dziesma. Kungs, spried man tiesu, jo es staigāju savā sirds skaidrībā un paļaujos uz To Kungu - es nešaubīšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Pārbaudi mani, Kungs, un izmeklē mani, izlūko manas īkstis un manu sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Jo Tava žēlastība ir priekš manām acīm, un es staigāju Tavā patiesībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Es nesēžos pie neliešiem un netinos ar viltniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Es ienīstu ļaundarītāju draudzi, un nesēžu pie bezdievīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Es mazgāju savas rokas nenoziedzībā un esmu, Kungs, ap Tavu altāri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Lai ar teikšanas balsi daru zināmus un sludināju visus Tavus brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Kungs, es mīlēju Tava nama mājokli un Tavas godības telts vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Neaizrauj manu dvēseli līdz ar grēciniekiem nedz manu dzīvību līdz ar asins ļaudīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Viņu rokās ir negantība, un viņu labā roka ir pilna dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Bet es staigāju savā sirds skaidrībā; atpestī mani un apžēlojies par mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mana kāja stāv uz līdzena ceļa, draudzes sapulcēs es teikšu To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Dāvida dziesma. Tas Kungs ir mans gaišums un mana pestīšana, no kā man bīties? Tas Kungs ir manas dzīvības stiprums, no kā man baiļoties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Kad ļaunie, mani pretinieki un ienaidnieki, uz mani laužas manu miesu ēst, tad tiem būs piedauzīties un krist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Kad arī pulki pret mani apmetās, taču mana sirds nebīstas; kad karš pret mani ceļas, tad es paļaujos uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Vienu lietu es no Tā Kunga lūdzos, to es meklēju tikuši(mana sirds vēlēšanās), ka es varu dzīvot Tā Kunga namā visu savu mūžu, raudzīt Tā Kunga laipnību un pielūgt Viņa svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Jo ļaunā dienā Viņš mani paslēpj Savā dzīvoklī Viņš mani sargā Savas telts ēnā, Viņš mani paaugstina uz akmens kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Un nu mana galva taps paaugstināta pār maniem ienaidniekiem, kas ir ap mani; un es upurēšu Viņa teltī teikšanas upurus, es dziedāšu un slavēšu To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Klausi, ak Kungs, manu balsi; kad es saucu, tad žēlo mani un atbildi man.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mana sirds saka uz tevi: „Meklējiet Manu vaigu!“Es meklēju, Kungs, Tavu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Neapslēp Savu vaigu priekš manis, neatstum Savu kalpu dusmībā, - Tu esi mans palīgs; neatmet mani un neatstāj mani, ak Dievs, mans Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Jo mans tēvs un mana māte mani atstājuši, bet Tas Kungs mani uzņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Māci man, Kungs, Tavu ceļu, un vadi mani uz īstenu ceļu, manu ienaidnieku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Nenodod mani manu pretinieku prātam, jo viltīgi liecinieki ceļas pret mani un runā netaisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Ja es nebūtu ticējis, ka es redzēšu Tā Kunga labumu dzīvības zemē,(tad es būtu bojā gājis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Gaidi uz To Kungu, esi drošs un stiprs savā sirdī, un gaidi uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Dāvida dziesma. Tevi es piesaucu, Kungs, mans patvērums, nestāvi man klusu; ja Tu man klusu stāvēsi, tad es tapšu līdzīgs tiem, kas grimst bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Klausi manas sirds lūgšanas balsi, kad uz Tevi kliedzu, kad savas rokas paceļu pret Tava nama vissvēto vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Neaizrauj mani ar tiem bezdievīgiem un ļaundarītājiem, kas no miera runā ar savu tuvāko, bet ļaunums ir viņu sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Dod tiem pēc tā, ko tie dara, un pēc viņu blēdīgiem darbiem, dod tiem pēc viņu roku darbiem, atmaksā tiem pēc viņu nopelna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Jo tie neņem vērā, ko Tas Kungs dara, nedz viņa rokas darbu. Viņš tos sadauzīs un tos neuztaisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Slavēts lai ir Tas Kungs, jo Viņš ir klausījis manas sirds lūgšanas balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Tas Kungs ir mans stiprums un manas priekšturamās bruņas; mana sirds paļaujas uz Viņu, un man top palīdzēts; par to mana sirds priecājās, un es Viņam pateikšu ar dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Tas Kungs tiem ir par stiprumu, Viņš ir Sava svaidītā stiprums un pestīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Atpestī Savus ļaudis un svētī Savu īpašumu, un gani tos un paaugstini tos mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Dāvida dziesma. Dodiet Tam Kungam, jūs varenie, dodiet Tam Kungam godu un spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Dodiet Tam Kungam Viņa Vārda godu, pielūdziet To Kungu svētā glītumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Tā Kunga balss pār ūdeņiem, tas stiprais, godības pilnais Dievs liek pērkoniem rūkt, Tas Kungs pār lieliem ūdeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Tā Kunga balss iet ar spēku, Tā Kunga balss iet ar godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Tā Kunga balss salauž ciedra kokus, Tas Kungs salauž ciedra kokus uz Lībanus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Un liek tiem lēkāt kā teļam, Lībanum un Sirjonam kā jaunam vērsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Tā Kunga balss cērt ar uguns liesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Tā Kunga balss dara tuksnesi drebam, Tas Kungs dara drebam Kadešas tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Tā Kunga balss iztrūcina stirnas un atklāj mežus, un Viņa svētā vietā ikviens slavē Viņa godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Tas Kungs nosēdies, sūtīt ūdens plūdus; Tas Kungs sēdēs, viens ķēniņš mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Tas Kungs dos Saviem ļaudīm stiprumu, Tas Kungs svētīs Savus ļaudis ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Dziesma pie Dāvida nama iesvētīšanas. Es Tevi augsti teikšu, Kungs, jo Tu mani augsti esi cēlis, un maniem ienaidniekiem neesi ļāvis priecāties par mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Kungs, mans Dievs, kad es Tevi piesaucu, tad Tu mani dziedināji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Kungs, Tu manu dvēseli esi izvedis no elles, Tu mani dzīvu esi uzturējis, ka neesmu nogrimis kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Dziedājiet Tam Kungam, jūs Viņa svētie, un teiciet Viņa svēto piemiņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Jo Viņa dusmība pastāv acumirkli, Viņa žēlastība cauru mūžu: vakarā nāk raudāšana, bet rītā prieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Es gan sacīju, kad man labi klājās: es nešaubīšos ne mūžam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Jo, Kungs, caur Tavu labprātību Tu manu kalnu esi darījis pastāvīgu; bet kad Tu Savu vaigu paslēpi, tad es iztrūcinājos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Tevi es piesaucu, Kungs, un pielūdzu Tevi, ak Kungs no sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Kāds labums atlec no manām asinīm, kad es būšu kapā grimis? Vai pīšļi Tevi slavēs? Vai tie sludinās Tavu patiesību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Klausi, Kungs, un apžēlojies par mani: Kungs, esi man par palīgu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Manas žēlabas Tu esi pārvērtis par līksmību, Tu man to maisu esi novilcis un mani apjozis ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Tāpēc Tev dziedās mans gods un nestāvēs klusu; Kungs, mans Dievs, es Tev pateikšos mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Dāvida dziesma. Dziedātāju vadonim. Uz tevi, Kungs, es paļaujos, nepamet mani kaunā mūžīgi, izglāb mani caur Tavu taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Atgriez Savu ausi pie manis, izglāb mani drīz, esi man par stipru patvērumu, par stipru pili man palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Jo Tu esi mans akmens kalns un mana stiprā pils, un Tava Vārda dēļ ved un vadi mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Izved mani no tīkla, ko tie priekš manis paslēpuši, jo Tu esi mans stiprums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Tavā rokā es pavēlu savu garu, Tu mani esi atpestījis, Kungs, Tu stiprais patiesības Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Es ienīstu tos, kas dodas uz blēņu mācībām, bet es paļaujos uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Es priecāšos un līksmošos par Tavu žēlastību, ka Tu uzlūko manas bēdas, un vērā lieci manu dvēseli bailēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Un nenodod mani ienaidnieka rokā; Tu manām kājām lieci stāvēt plašā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Esi man žēlīgs, ak Kungs! Jo man ir bail\', no skumības ir sarucis mans vaigs, mana dvēsele un mana miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Jo mana dzīvība ir nonīkusi caur noskumšanu un mani gadi caur nopūšanos, mans spēks caur manu noziegumu ir sakritis, un mani kauli ir sanīkuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Caur visiem saviem pretiniekiem es esmu par kaunu tapis saviem kaimiņiem, un saviem pazīstamiem par biedēkli; kas mani uz ielām redz, tie bēg no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Es sirdīs esmu aizmirsts kā mironis, esmu tapis kā sadauzīts trauks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Jo es dzirdu no daudziem lamāšanās: bailība ir visapkārt; kad tie kopā sarunājās pret mani, tie domā paņemt manu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Bet es cerēju uz Tevi, Kungs; es saku tā: Tu esi mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Mani laiki stāv Tavā rokā; izglāb mani no manu ienaidnieku rokas un no tiem, kas mani vajā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Liec Savam vaigam spīdēt pār Savu kalpu, atpestī mani caur Tavu žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Kungs, neliec man kaunā palikt, jo es Tevi piesaucu; lai bezdievīgie paliek kaunā un top klusināti ellē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Lai mēmas paliek melkuļu lūpas kas bezkaunīgi runā pret taisno ar lepnību un nicināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Cik liels ir Tavs labums, ko Tu esi glabājis tiem, kas Tevi bīstas, un sataisījis tiem, kas cilvēku priekšā uz Tevi paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Tu tos slēpi Sava vaiga ēnā priekš cilvēku dumpjiem, Tu tos glabā kā namā priekš rējēju mēlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Slavēts lai ir Tas Kungs, jo Viņš brīnišķi man parādījis Savu žēlastību tā kā stiprā pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Gan es sacīju savās bailēs: es esmu atmests no Tava vaiga; taču Tu klausīji manas sirds lūgšanas balsi, kad es Tevi piesaucu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Mīlējiet To Kungu, visi Viņa svētie; Tas Kungs pasargā tos ticīgos, un atmaksā papilnam tam, kas dara pārgalvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Esiet droši un stipri savā sirdī, visi, kas cerējiet uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Dāvida pamācīšana. Svētīgs ir tas, kam pārkāpumi piedoti, kam grēki apklāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Svētīgs tas cilvēks, kam Tas Kungs noziegumus nepielīdzina, un kura garā viltības nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Kad es klusu cietu, tad panīka mani kauli caur manu kaukšanu cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Jo Tava roka dienām naktīm bija grūta uz manis, ka mans zaļums nokalta kā vasaras bullā. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Savus grēkus es Tev sūdzu un neapklāju savus noziegumus; es sacīju: es izteikšu Tam Kungam savus pārkāpumus, tad Tu piedevi manu grēku noziegumus. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Par to Tevi pielūgs visi svētie īstenā atrašanas laikā; tādēļ jebšu lieli ūdens plūdi nāktu, taču tie tos neaizņems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu esi mans patvērums, no bailēm Tu mani pasargāsi; Tu liksi atskanēt ap mani pestīšanas gavilēm. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '“Es tev došu saprašanu un tev mācīšu to ceļu, pa kuru jāiet; Es došu padomu, Mana acs būs pār tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Neesiet kā zirgi un zirgēzeļi, kam prāta nav, kam iemaukti un laužņi jāliek mutē, kad negrib nākt pie tevis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Bezdievīgam ir daudz sāpes, bet kas uz To Kungu cer, to žēlastība apkamps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Priecājaties iekš Tā Kunga un līksmojaties, jūs taisnie, un slavējiet, visi jūs sirds skaidrie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Dziedājiet priecīgi Tam Kungam, jūs taisnie; tiem sirds skaidriem pieklājās teikšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Pateiciet Tam Kungam ar koklēm un dziedājiet Viņam ar desmit stīgu spēlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Dziedājiet Viņam jaunu dziesmu, skandinājiet jauki ar bazūņu skaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Jo Tā Kunga vārds ir taisns, un viss Viņa darbs ir pastāvīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Viņš mīļo taisnību un tiesu; zeme ir pilna Tā Kunga žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Caur Tā Kunga vārdu debesis darītas, un viss viņu spēks caur Viņa mutes garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Viņš sakrāj jūras ūdeni kā kopu, un liek dziļumus slepenībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Bīstaties no Tā Kunga, visa pasaule, baiļojaties priekš Viņa, visi zemes iedzīvotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Kad Viņš runā, tad notiek, kad Viņš pavēl, tad stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Tas Kungs iznīcina tautu padomu, Viņš salauž ļaužu domas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Tā Kunga padoms pastāv mūžīgi, Viņa sirds domas uz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Svētīga tā tauta, kam Tas Kungs ir par Dievu, tie ļaudis, ko Viņš Sev izredzējis par īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Tas Kungs skatās no debesīm un uzlūko visus cilvēku bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Viņš raugās no Sava stiprā krēsla uz visiem, kas dzīvo virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Viņš sataisa visas viņu sirdis, Viņš liek vērā visus viņu darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ķēniņam nepalīdz viņa lielais spēks, vareno neizglābs viņa lielais stiprums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Arī zirgi nevar palīdzēt, un viņu lielais spēks nevar izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Redzi, Tā Kunga acs uzlūko tos, kas Viņu bīstas, kas cerē uz Viņa žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Ka Tas viņu dvēseli izpestī no nāves, un bada laikā tos uztur dzīvus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Mūsu dvēsele gaida uz To Kungu; Viņš mums ir par palīgu un par priekšturamām bruņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Jo mūsu sirds priecājās iekš Viņa, un mēs paļaujamies uz Viņa svēto vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Lai, ak Kungs, Tava žēlastība pār mums paliek, itin kā mēs uz Tevi cerējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Dāvida dziesma, kad viņš izlikās negudrs Abimeleka priekšā, kas viņu aizdzina, un viņš aizgāja. Es teikšu To Kungu allažiņ, Viņa teikšana būs manā mutē vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Mana dvēsele lielīsies ar To Kungu; pazemīgie to dzirdēs un priecāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Teiciet augsti To Kungu līdz ar mani; mēs kopā augsti slavēsim Viņa vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Es meklēju To Kungu, un Viņš man atbildēja, un izglāba mani no visām manām izbailēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Kas Viņu uzlūko un Viņam pieskrien(tuvojās priecīgi), to vaigs netaps kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Kad šis bēdīgais sauca, tad Tas Kungs klausīja un to izpestīja no visām viņa bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Tā Kunga eņģelis apmetās ap tiem, kas Viņu bīstas, un tos izglābj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Baudāt un redzat, ka Tas Kungs ir labs; svētīgs tas vīrs, kas uz Viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Bīstaties To Kungu, jūs Viņa svētie, jo kas Viņu bīstas, tiem netrūkst nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Jaunie lauvas cieš trūkumu un badu, bet kas To Kungu meklē, tiem netrūkst nekāda labuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Nāciet šurp, bērni, klausiet mani, es jums mācīšu Tā Kunga bijāšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kas tas vīrs, kam gribās dzīvot? Kam tīk redzēt labas dienas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Pasargi savu mēli no ļauna un savas lūpas no viltīgas valodas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Atkāpies no ļauna un dari labu, meklē mieru un dzenies tam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Tā Kunga acis lūko uz taisniem, un Viņa ausis uz viņu kliegšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Tā Kunga vaigs ir pretī tiem, kas ļaunu dara, ka Tas viņu piemiņu izdeldē no zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Kad taisnie sauc, tad Tas Kungs klausa, un tos izglābj no visām viņu bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Tas Kungs ir tuvu tiem, kam satriektas sirdis, un palīdz tiem, kam sagrauzts prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Taisnam ir daudz bēdu, bet no visām tām Tas Kungs to izpestī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Viņš pasargā visus viņa kaulus, ka neviens no tiem netiek salauzts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Blēdība nokaus bezdievīgo, un kas taisno ienīst, tie būs noziedzīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Tas Kungs izpestī Savu kalpu dvēseli, un visi, kas tic uz Viņu, nebūs noziedzīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Dāvida dziesma. Ej tiesā, Kungs, ar tiem, kas ar mani iet tiesā, karo ar tiem, kas ar mani karo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Sagrāb priekšturamās bruņas un ieroci un celies man par palīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Izvelc šķēpu un zobenu pret tiem, kas man dzenās pakaļ; saki uz manu dvēseli: Es esmu tava pestīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Lai top kaunā un par apsmieklu, kas manu dvēseli meklē, lai top dzīti atpakaļ un likti kaunā, kas pret mani ļaunu domā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Lai tie top kā pelavas vējā, un Tā Kunga eņģelis lai tos aizdzen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Viņu ceļš lai paliek tumšs un slidens, un Tā Kunga eņģelis lai tos vajā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Jo bez vainas tie priekš manis apslēpuši sava tīkla bedri, bez vainas tie priekš manas dvēseles rakuši bedri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Posts tam uzies, kad viņš to nezin, un viņa tīkls, ko tas ir paslēpis, sagūstīs viņu pašu; sev par postu viņš tur iekritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Bet mana dvēsele priecāsies iekš Tā Kunga, un līksmosies par Viņa pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Visi mani kauli sacīs: Kungs, kas ir kā Tu? Tu bēdīgo izglābi no tā, kas ir stiprāks, nekā viņš, arī bēdīgo un nabagu no viņa laupītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Viltus liecinieki ceļas, tie prasa no manis, ko es nezinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Tie man maksā ļaunu par labu; mana dvēsele ir atstāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Bet es, kad tie bija neveseli, apvilku maisu un mērdēju savu dvēseli ar gavēšanu un lūdzu no sirds dibina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Es tā staigāju, tā kā viņš man būtu par draugu un brāli, es gāju noskumis, nospiests, tā kā kas žēlojās par savu māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Bet kad es straipalēju, tad tie priecājās un sapulcējās, nelieši, ko es nepazinu, sapulcējās pret mani; tie plosās un nepaliek klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Ar viltīgiem mēdītājiem un kumosu lišķiem tie griež zobus pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Kungs, cik ilgi Tu to gribi redzēt? Izglāb manu dvēseli no viņu postīšanas, manu vientuli no jauniem lauvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Es Tev pateikšos lielā draudzē, ļaužu pulkā es Tevi slavēšu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Lai par mani nepriecājās, kas mani ienīst par nepatiesu, nedz mirkšķina ar acīm, kas mani nīdē bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Jo no miera tie nerunā, bet izgudro viltīgus vārdus pret tiem klusiem iekš zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Tie atplēš savu muti pret mani, tie saka: tā, tā, mūsu acs to redzējusi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Kungs, Tu to redzi, neciet klusu, Kungs, neesi tālu no manis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Uzmodies un celies par manu tiesu, mans Dievs un mans Kungs, par manu lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Tiesā mani pēc Tavas taisnības, Kungs, mans Dievs, ka tie par mani nepriecājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Lai tie nesaka savā sirdī: labi, tas mums pa prātam; lai tie nesaka: mēs viņu esam aprijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Lai kopā top kaunā un par apsmieklu, kas priecājās par manu nelaimi; lai top apģērbti ar kaunu un negodu tie, kas pret mani lielās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Priecīgi lai dzied un līksmojās, kam patīk mana taisnība, lai tie saka vienmēr: augsti slavēts lai ir Tas Kungs, kam labs prāts pie Sava kalpa labklāšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Tad mana mēle sludinās Tavu taisnību, un ikdienas Tavu slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Dāvida, Tā Kunga kalpa, dziesma. Dziedātāju vadonim. Savā sirds dziļumā es nomanu vienu Dieva vārdu par bezdievīgā pārkāpšanu: ka Dieva bijāšanas nav priekš viņa acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Jo tas pārrunājās pats savās acīs, ka viņa noziegumu neatradīs un nenīdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Viņa mutes vārdi ir nelietība un viltība, viņš vairs neprot laba darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Viņš izdomā nelietību savā gultā, viņš iet pa tādu ceļu, kas nav labs, ļaunu viņš neatmet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Ak Kungs, Tava žēlastība sniedzās līdz pat debesīm, un Tava patiesība līdz padebešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Tava taisnība stāv tāpat kā Dieva kalni, Tavas tiesas kā lieli dziļumi; Kungs, Tu palīdzi cilvēkiem un lopiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Cik dārga ir, ak Dievs, Tava žēlastība, ka cilvēku bērni patveras apakš Tavu spārnu ēnas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Tie top pildīti no Tava nama taukumiem, un Tu tos dzirdini no Tava garduma upēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Jo pie Tevis ir dzīvības avots, Tavā gaismā mēs redzam gaismu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Izplet Savu žēlastību pār tiem, kas Tevi pazīst, un Savu taisnību pār sirds skaidriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Lai lepno kāja nenāk pār mani, un bezdievīgo roka lai mani nevajā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Redzi, ļaundarītāji krīt; tie top zemē gāzti un vairs nevar celties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Dāvida dziesma. Neapskaities par bezdievīgiem, neiekarsies par ļauna darītājiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Jo tā kā zāle tie drīz top nocirsti, un savītīs kā zaļa zāle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Cerē uz To Kungu un dari labu, paliec savā zemē un uzturies ar uzticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Priecājies iekš Tā Kunga, tad Viņš tev dos tavas sirds lūgšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Pavēli Tam Kungam savu ceļu un cerē uz Viņu, tad Viņš gan darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Viņš liks aust tavai taisnībai kā gaismai un tavai tiesai kā dienas spožumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Ciet klusu Tam Kungam un gaidi uz Viņu, neapskaities par to, kam ceļš labi izdodas, par vīru, kas dodas uz blēdīgiem padomiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Atstājies no dusmības un mities no bardzības, nesaskaities, ka tu ļauna nedari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Jo ļaunie taps izdeldēti; bet kas uz To Kungu gaida, tie zemi iemantos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Mazs brīdis vēl, un bezdievīgā vairs nav; un kad Tu raudzīsi pēc viņa vietas, tad tā vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Bet lēnprātīgie iemantos zemi un priecāsies lielā mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Bezdievīgais glūn uz taisno un sakož savus zobus pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Bet Tas Kungs par viņu smejas, jo tas redz, ka viņa diena nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Bezdievīgie izvelk zobenu un uzvelk savu stopu, gāzt bēdīgo un nabagu un nokaut tos, kas uz taisniem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Bet viņu zobens ies viņu pašu sirdī, un viņu stopi taps salauzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Tas mazums, kas taisnam, ir labāks, nekā tā bagātība, kas daudz bezdievīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Jo bezdievīgiem elkonis taps salauzts, bet Tas Kungs uztur taisnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Tas Kungs zina sirds skaidro dienas, un viņu manta paliks mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Bēdu laikā tie netaps kaunā, un bada laikā tie taps paēdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Jo bezdievīgie ies bojā, un Tā Kunga ienaidnieki kā lauku jaukums iznīks, tie iznīks kā dūmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Bezdievīgais aizņem uz parādu un neatdod, bet taisnais ir žēlīgs un devīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Jo Tā Kunga svētītie iemantos zemi, bet Viņa nolādētie taps izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'No Tā Kunga būs stiprināti tāda vīra soļi, un ved tādu, kura ceļš viņam patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Ja viņš krīt, tad nepaliek guļam, jo Tas Kungs viņu tur pie rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Es esmu jauns bijis un arī vecs palicis, bet es neesmu redzējis taisno atstātu, nedz viņa dzimumu meklējam maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Vienmēr viņš apžēlojās un aizdod, un viņa dzimums ir par svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Atstājies no ļauna un dari labu, tad tu paliksi mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Jo Tas Kungs mīl tiesu un neatstās Savus svētos; tie top mūžīgi pasargāti, bet bezdievīgo dzimums top izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Taisnie iemantos zemi, un dzīvos iekš tās mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Taisnā mute izteic gudrību, un viņa mēle runā tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Dieva bauslība ir viņa sirdī, viņa soļi nestraipelēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Bezdievīgais glūn uz taisno un meklē viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Bet Tas Kungs to nepamet viņa rokā, un to nepazudina, kad to tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Gaidi uz To Kungu un sargi Viņa ceļu, tad Viņš tevi paaugstinās, ka tu zemi iemanto; tu redzēsi, ka bezdievīgie taps izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Es esmu redzējis vienu bezdievīgu, tas darīja varas darbus un zaļoja kā paša audzis koks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Bet tas iznīka, un redzi, tā nebija vairs; es pēc viņa vaicāju bet viņš netapa atrasts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Ņem vērā sirds skaidro un uzlūko taisno, jo tādam vīram beidzot labi klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Bet pārkāpēji kopā taps samaitāti, bezdievīgie taps beidzot izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Bet taisno palīdzība ir no Tā Kunga; Tas tiem ir par stiprumu bēdu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Un Tas Kungs tiem palīdzēs un tos izglābs, Viņš tos izglābs no bezdievīgiem, un tos izpestīs, jo tie paļaujas uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Dāvida dziesma, par piemiņu. Kungs, nesodi mani Savā dusmībā, un nepārmāci mani Savā bardzībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Jo Tavas bultas man ir iespiedušās, un Tava roka pār mani nolaidusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Nekādas veselības nav pie manas miesas caur Tavu dusmību, nekāda miera nav manos kaulos caur maniem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Jo mani noziegumi iet pāri pār manu galvu, kā grūta nasta tie man palikuši par daudz grūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Manas vātis smird un tek manas ģeķības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Es eju salīcis un ļoti nospiests, cauru dienu es eju noskumis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Jo manas iekšas ir moku pilnas, nekādas veselības nav pie manas miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Es esmu pavisam sastindzis un sasists, es kaucu savas sirds vaimanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Kungs, Tavā priekšā ir visa mana kārošana, un mana nopūšanās Tev nav apslēpta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Mana sirds trīc, mans spēks mani atstājis, arī pat manu acu gaismiņas man vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mani mīļie un mani draugi stāv tālu nost no manas mocības, un mani tuvākie stāv no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Un kas manu dvēseli meklē, liek man valgus, un kas manu nelaimi meklē, runā postu un izdomā viltību cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Bet es esmu kā kurls, kas nedzird, un kā mēms, kas neatver savu muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Un es esmu kā vīrs, kas nedzird, un kam mutē vārdu pretim nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Jo es gaidu, Kungs, uz Tevi, Tu paklausīsi, Kungs, mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Jo es sacīju: lai tie par mani nepriecājās; kad mana kāja šaubās, tad tie lai nelielās pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Jo es esmu pie pašas krišanas un manas sāpes ir vienmēr manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Jo savu noziegumu es izsūdzu, un man ir bail manu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Bet mani ienaidnieki dzīvo un ir vareni, un kas mani par nepatiesu ienīst, tie vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Un kas ļaunu par labu maksā, tie stāv man pretim, tāpēc ka es uz labu dzenos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Neatstājies no manis, Kungs, mans Dievs! neesi tālu no manis nost,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Steidzies man palīgā, Kungs, mana pestīšana!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Dāvida dziesma, dziedātāju vadonim, Jedutunam. Es esmu apņēmies, ka savu ceļu sargāšu, ka negrēkošu ar savu mēli; es sargāšu savu muti kā ar iemauktiem, kamēr bezdievīgais manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Es esmu palicis kā mēms un klusu cietis, un nepieminu vairs labuma, bet manas sāpes vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Mana sirds ir iekarsusi iekš manis; kad es uz to domāju, tad es iedegos kā uguns; es runāju ar savu mēli:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Kungs, māci man manu galu un kāds ir manu dienu mērs, lai es zinu, cik nīcīgs es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Redzi, Tu manas dienas esi licis plaukstas platumā, un mans mūžs ir kā nekas Tavā priekšā; tiešām niecība vien ir ikviens cilvēks savā stiprumā. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Cilvēks staigā kā ēna un nieka dēļ raizējās; viņš krāj, bet nezin, kas to dabūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Nu tad, uz ko man būs gaidīt, Kungs? Es cerēju uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Izglāb mani no visām manām pārkāpšanām, un neliec man ģeķiem palikt par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Es esmu klusu un neatdaru savu muti; jo Tu to esi darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Atņem Savu mocību no manis, jo es nīkstu no Tavas rokas grūtuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Kad Tu cilvēku pārmāci par noziegumiem, tad Tu iznīcini viņa skaistumu kā kodes; tiešām: visi cilvēki ir niecība.(Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Klausi, Kungs, manu lūgšanu, ņem vērā manu saukšanu, un neciet klusu pie manām asarām, jo es esmu svešinieks un piedzīvotājs Tavā priekšā, tā kā visi mani tēvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Atstājies no manis, ka es atspirgstos, pirms noeju un vairs neesmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Dāvida dziesma. Dziedātāju vadonim. Es gaidu gaidīdams uz To Kungu, Viņš griežas pie manis un paklausa manu kliegšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Jo Viņš mani izvilka no briesmīgas bedres un no dubļainām dūņām un cēla manas kājas uz akmens kalnu un stiprināja manus soļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Un ir licis manā mutē jaunu dziesmu, teikšanas dziesmu mūsu Dievam; daudzi to redzēs un bīsies un cerēs uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Svētīgs tas vīrs, kas savu cerību liek uz To Kungu, un negriežās pie tiem lepniem un pie tiem, kas ar meliem tinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Kungs, mans Dievs, lieli ir Tavi brīnumi, ko Tu mums parādi, un Tavi padomi; nekas Tev nav līdzinājams. Es tos gribu pasludināt un izteikt, tie nav izskaitāmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Upuri un ēdami upuri Tev nepatīk, ausis Tu man esi atvēris; dedzināmos upurus un grēku upurus Tu neprasi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Tad es sacīju: Redzi, es nāku, grāmatā stāv par mani rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Man ir prieks, darīt Tavu prātu, mans Dievs, un Tava bauslība ir manā sirds dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Es sludināšu taisnību lielā draudzē; redzi, savas lūpas es neaizdarīšu; Kungs, Tu to zini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Tavu taisnību es neslēpju savā sirdī, no Tavas patiesības un pestīšanas es runāju, Tavu žēlastību un uzticību es neslēpju lielā draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Tu, ak Kungs, nenovērs Savu apžēlošanu no manis; lai Tava žēlastība un patiesība vienmēr mani pasargā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Jo ap mani ir apmetušās bēdas, ko nevar skaitīt, mani noziegumi mani sagrābuši, ka nevaru redzēt; viņu ir vairāk, nekā matu uz manas galvas, un mana sirds mani atstājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Lai tev patīk, Kungs, mani izglābt, steidzies, ak Kungs, man palīgā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Lai top kaunā un kopā paliek par apsmieklu, kas manu dvēseli meklē, to samaitāt; lai top dzīti atpakaļ un paliek kaunā, kas par manu nelaimi priecājās!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Lai savas bezkaunības dēļ tie iztrūcinājās, kas no manis saka: tā, tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Lai priecājās un līksmojās iekš Tevis visi, kas Tevi meklē, un lai tie, kas Tavu pestīšanu mīļo, allažiņ saka: Tas Kungs ir augsti teicams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Gan es esmu bēdīgs un nabags, bet Tas Kungs par mani gādā. Tu esi mans palīgs un mans glābējs; ak, mans Dievs, nekavējies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Dāvida dziesma. Dziedātāju vadonim. Svētīgs tas, kas nabagu apgādā; to Tas Kungs izglābs ļaunā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Tas Kungs to pasargās un uzturēs pie dzīvības, Viņš tam liks labi klāties virs zemes un to nenodos viņa ienaidnieku prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Tas Kungs to atspirdzinās uz neveselības gultas; Tu viņam palīdzēsi guļā no visas viņa sērgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Es sacīju: ak Kungs, esi man žēlīgs, dziedini manu dvēseli, jo es pret Tevi esmu grēkojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Mani ienaidnieki runā ļaunu no manis: kad viņš nomirs un viņa vārds ies bojā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Un kad tie nāk, mani apraudzīt, tad tie viltu runā; ar savu sirdi tie sameklē niekus, iziet ārā un izplukšķ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Visi, kas mani ienīst, musina kopā pret mani, un domā ļaunu pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Blēņu darbu tie apņēmušies savā prātā: kad tas guļ, tad viņš vairs necelsies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Un pat mans draugs, kam es uzticējos, kas manu maizi ēda, mani min pa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Bet Tu, ak Kungs, esi man žēlīgs, un uzcel mani, tad es tiem to maksāšu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Pie tam es zinu, ka Tev labs prāts pie manis, ka mans ienaidnieks par mani negavilēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Bet Tu mani uzturi manā nenoziedzībā, un mani iecel Savā priekšā mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Slavēts lai ir Tas Kungs, Israēla Dievs, mūžīgi mūžam! Āmen, Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Koraha bērnu mācība, dziedātāju vadonim. Kā briedis brēc pēc ūdens upēm, tā mana dvēsele brēc, ak Dievs, pēc Tevis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Manai dvēselei slāpst pēc Dieva, pēc tā dzīvā Dieva; kad nākšu turp un parādīšos priekš Dieva vaiga?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Manas asaras ir mana barība dienām naktīm, tāpēc ka vienmēr uz mani saka: kur ir tavs Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'To es pieminu un izgāžu savu dvēseli pie sevis paša, jo es gribētu labprāt noiet ar to draudzi un ar tiem uz Dieva namu staigāt, ar priecīgām dziesmām un teikšanām tai pulkā, kas svētkus tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Ko tu bēdājies, mana dvēsele, un esi tik nemierīga iekš manis? Cerē uz Dievu, jo es viņam vēl pateikšu par viņa vaiga pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Mans Dievs, mana dvēsele ir noskumusi, tāpēc es Tevi pieminu no Jardānes un Hermona zemes, no Micar kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Tavi plūdi šņāc, un jūra uz jūru rūc, visas Tavas bangas un Tavi viļņi iet pāri pār manu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Dienā Tas Kungs ir cēlis savu žēlastību, un naktī es viņam dziedu, es pielūdzu savas dzīvības Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Un saku uz Dievu, savu akmens kalnu: kāpēc Tu mani esi aizmirsis? Kāpēc man būs staigāt noskumušam, kad ienaidnieks spaida?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Manu pretinieku mēdīšana ir kā nāve manos kaulos, kad tie uz mani vienmēr saka: kur ir tavs Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Ko tu bēdājies, mana dvēsele, un esi tik nemierīga iekš manis? Cerē uz Dievu, jo es Viņam vēl pateikšos, ka tas manam vaigam par pestīšanu un mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Tiesā mani, Dievs, un iztiesā manu tiesu pret tiem nesvētiem ļaudīm, izglāb mani no tiem viltīgiem un netaisniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Jo Tu esi mans stiprais Dievs, kāpēc Tu mani atstūmi? Kāpēc man būs staigāt noskumušam, kad ienaidnieks spaida?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sūti Savu gaišumu un Savu patiesību, ka tie mani vada un noved uz Tavu svēto kalnu un Tavā dzīvoklī;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Ka es ieeju pie Dieva altāra, pie tā stiprā Dieva, kas man par prieku un līksmību, un Tev uz koklēm pateicos, ak Dievs, mans Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Ko tu bēdājies, mana dvēsele, un esi tik nemierīga iekš manis? Cerē uz Dievu, jo es Viņam vēl pateikšos, ka tas manam vaigam par pestīšanu un mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Koraha bērnu pamācība. Dziedātāju vadonim. Dievs, ar savām ausīm mēs to esam dzirdējuši, mūsu tēvi to mums ir teikuši: vienu darbu Tu esi darījis viņu laikā sendienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Ar savu roku pagānus Tu esi izdzinis, bet viņus Tu esi dēstījis; tautas Tu esi mocījis, bet viņus Tu esi izplatījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Jo tie to zemi caur savu zobenu nav iemantojuši, un viņu elkonis tiem nav palīdzējis, bet Tava labā roka un Tavs elkonis un Tava vaiga gaišums, jo Tev bija labs prāts pie tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Tu tas esi, ak Dievs, mans ķēniņš; sūti Jēkabam pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Ar Tevi mēs gribam sadauzīt savus ienaidniekus, Tavā vārdā gribam samīt, kas mums ceļas pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Jo es neceru uz savu stopu, un mans zobens man nevar palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Bet Tu mūs izglābi no mūsu pretiniekiem, un Tu mūsu ienaidniekus lieci kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Ar Dievu mēs lielāmies cauru dienu un pateicamies Tavam vārdam mūžīgi. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Bet nu Tu mūs atstūmi un lieci mūs kaunā un neizej ar mūsu karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Tu mūs dzeni atpakaļ priekš mūsu pretiniekiem, ka mūsu ienaidnieki mūs aplaupa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Tu mūs nodevi kā avis par barību, un mūs izkaisi starp pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Tu pārdevi Savus ļaudis pa velti, un nespriedi priekš viņiem nekādas maksas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Tu mūs cēli par apsmieklu mūsu kaimiņiem, par nievāšanu un apmēdīšanu tiem, kas ir ap mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Tu mūs dari par sakāmu vārdu starp pagāniem, ka tautas par mums galvu krata.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Cauru dienu mans negods man ir klāt, un kauns apklāj manu vaigu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Mēdītāju un zaimotāju valodas pēc, ienaidnieku un atriebēju dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Viss tas mums uzgājis, taču mēs Tevi neesam aizmirsuši, nedz viltīgi darījuši pret Tavu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Mūsu sirds nav atpakaļ griezusies, nedz mūsu soļi noklīduši no Taviem ceļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Ka Tu mūs tā satriec zvēru vidū, un mūs apklāj ar nāves ēnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Ja mēs būtu aizmirsuši sava Dieva vārdu, un pacēluši savas rokas uz kādu svešu dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Vai Dievs to nevarētu samanīt? Jo Viņš zina sirds noslēpumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Bet Tevis pēc mēs topam nāvēti visaugošu dienu, un topam turēti līdzi kaujamām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Uzmosties, Kungs, kāpēc Tu guli? Mosties, neatstum mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Kāpēc Tu apslēpi Savu vaigu un aizmirsti mūsu bēdas un mokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Jo mūsu dvēsele ir nospiesta pīšļos, mūsu vēders līp pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Celies mums par palīgu, un izglāb mūs Savas žēlastības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Koraha bērnu mīlestības dziesma un pamācība. Dziedātāju vadonim, pēc, „lilijas.“Mana sirds izverd košu vārdu; es dziedāšu Ķēniņam; mana mēle ir veikla rakstītāja rakstāmais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Tu esi tas skaistākais starp cilvēku bērniem, Tavas lūpas ir laipnības pilnas, tādēļ Dievs Tevi svētī mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Apjozi Savu zobenu pie Saviem gurniem, Tu varenais, Savu godību un jaukumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Lai Tev labi izdodas Tavā godībā, celies patiesībai, lēnībai un taisnībai par labu, tad Tava labā roka Tev mācīs brīnuma darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Tavas bultas ir asas ķēniņa ienaidnieku sirdī; tautas apakš Tevis kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Tavs godības krēsls, ak Dievs, paliek mūžīgi mūžam, Tavas valstības scepteris ir taisns scepteris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Tu mīļo taisnību un ienīsti bezdievību, tādēļ Dievs, Tavs Dievs, Tevi svaidījis ar prieka eļļu pāri pār Taviem biedriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Visas Tavas drēbes ir(smaržu pilnas ar) mirres, alvejas un kasija(kanēlis), ziloņkaulu namos stīgu spēles Tevi iepriecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Tavā glītumā staigā ķēniņu meitas, brūte stāv Tev pa labo roku šķīstā Ofira zeltā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Klausies, meita, un redzi un griez šurp savas ausis, un aizmirsti savus ļaudis un sava tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Tad Ķēniņam patiks tavs skaistums, jo Viņš ir tavs Kungs, un tev būs Viņu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Cora meita būs klāt ar dāvanām, bagāti ļaudis tavā priekšā pielūgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Viscaur skaistums ir ķēniņa meitas pilī, viņas apģērbs ir no rakstīta zelta darba!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Izrakstītās drēbēs viņa top vadīta pie Ķēniņa, viņas draudzenes, tās jaunavas, kas iet viņai pakaļ, top vestas pie Tevis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Ar prieku un līksmību tās top vadītas, un ieiet Ķēniņa pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Tavu tēvu vietā Tev būs dēli, tos Tu celsi par lieliem kungiem pār visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Es pieminēšu Tavu vārdu uz visiem radu radiem, tādēļ tautas Tevi teiks mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Koraha bērnu dziesma. Dziedātāju vadonim, augstām balsīm. Dievs ir mūsu patvērums un stiprums, īsti varens palīgs bēdu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Tādēļ nebīstamies, lai arī zeme pazūd, un kalni pašā jūras vidū nogrimst,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Lai viņas ūdeņi kauc un plosās un no viņas greznošanās kalni dreb. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Taču upes strautiņi iepriecinās Dieva pilsētu, kur tā Visuaugstākā svētie dzīvokļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Dievs ir viņas vidū; tā nešaubīsies, Dievs viņai palīdzēs rītam austot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Pagāni kauc, valstis krīt, zeme izkūst, kad Viņš paceļ Savu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Tas Kungs Cebaot ir ar mums, Jēkaba Dievs ir mūsu augstais patvērums. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Nāciet un raugāt Tā Kunga darbus, kas postīšanu sūta virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kas kariem liek mitēties pa visu pasauli, kas stopus salauž un šķēpus sadauza, kas ratus ar uguni sadedzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Nostājaties un atzīstiet, ka Es esmu Dievs. - Es būšu paaugstināts starp pagāniem. Es būšu paaugstināts zemes virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Tas Kungs Cebaot ir ar mums, Jēkaba Dievs ir mūsu augstais patvērums. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Koraha bērnu dziesma. Dziedātāju vadonim. Plaukšķinājiet priecīgi, visi ļaudis, un gavilējiet Dievam ar priecīgu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Jo Tas Kungs, tas visuaugstais, ir bijājams, liels ķēniņš pa visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Viņš sadzīs tautas apakš mums, un ļaudis apakš mūsu kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Viņš mums izrauga mūsu mantojumu, Jēkaba godību, ko Viņš mīļo. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Dievs uzkāpj ar gavilēšanu, Tas Kungs ar skaņu bazūni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Dziediet Dievam, dziedājiet; dziediet mūsu Ķēniņam, dziedājiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Jo Dievs ir Ķēniņš pār visu zemi, dziediet Viņam dziesmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Dievs valda pār pagāniem, Dievs sēž uz Sava svētā krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Tautu lielkungi sapulcējušies par tautu Ābrahāma Dievam, jo zemes varenie pieder Dievam; Viņš ir ļoti paaugstināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Koraha bērnu dziesma. Dziedātāju vadonim. Tas Kungs ir liels un ļoti teicams mūsu Dieva pilsētā Viņa svētā kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Jauki paceļas Ciānas kalns, visas zemes prieks, ziemeļa pusē, tā lielā Ķēniņa pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Dievs viņas pilīs ir atzīts par patvērumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Jo redzi, ķēniņi sapulcējās un atnāca kopā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Tie redzēja un brīnījās, tie iztrūcinājās un steidzās projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Drebēšana tos tur aizņēma, mokas tā kā sievu bērnu sāpēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Tu sadauzi lielos jūras kuģus caur austriņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Tā kā bijām dzirdējuši, tā to esam redzējuši Tā Kunga Cebaot pilsētā, mūsu Dieva pilsētā. Dievs to stiprinās mūžīgi. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Ak Dievs, mēs pieminam Tavu žēlastību Tavā svētā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Ak Dievs, tā kā Tavs vārds, tāpat ir Tava slava līdz pasaules galam, Tava labā roka ir taisnības pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Lai Ciānas kalns priecājās un Jūda meitas lai līksmojās Tavu tiesu labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Ejat ap Ciānu un apmetaties ap viņu, skaitiet viņas torņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Liekat vērā viņas mūrus, apraugāt viņas augstos namus, ka pēcnākamiem radiem to varat izteikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Jo šis Dievs ir mūsu Dievs mūžīgi mūžam. Viņš mūs vadīs līdz mūža galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Koraha bērnu dziesma. Dziedātāju vadonim. Klausāties to, visi ļaudis, grieziet ausis šurp, visi pasaules iedzīvotāji,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Tā zemi kā augsti, bagāti kā nabagi kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Manas mutes runa ir gudrība, un manas sirds domas ir prātīgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Es griezīšu savu ausi pie viena sakāma vārda, un izteikšu savu mīklu uz koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Kāpēc man bīties ļaunās dienās, kad manu vajātāju noziegums ap mani metās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Tie paļaujas uz savu padomu un greznojās ar savu lielo bagātību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Savu brāli neviens nevar atpestīt nedz Dievam par to dot atpirkšanas maksu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(Jo visai dārga ir viņu dvēseles atpestīšana un no(tā) tam jāatstājas mūžīgi,)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Ka tas dzīvotu mūžam un kapu neredzētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Tiešām redzēs, ka gudri mirst, ka ģeķi un neprātīgi kopā iet bojā un savu mantu pamet citiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Tās ir viņu sirdsdomas, ka viņu namiem būs stāvēt mūžīgi, viņu dzīvokļiem līdz radu radiem; tie nosauc valstis pēc saviem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Bet cilvēks greznībā nepastāv, viņš līdzinājās lopiem, ko nokauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Šis ir tas ceļš ģeķiem un tiem, kas viņiem iet pakaļ un kam viņu vārdi patīk. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Tie taps noguldīti ellē kā avis, nāve tos ganīs; bet tie taisnie par tiem valdīs rītam austot, un viņu augumu aprīs elle, ka nebūs, kur palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Bet Dievs atpestīs manu dvēseli no elles varas, jo Viņš mani pieņems. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Nebēdājies par to, kad kāds top bagāts, kad viņa nama gods top liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Jo viņš mirdams neko neņems līdz, viņa godība tam neies pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Jebšu viņš savu dvēseli svētī, kamēr viņš dzīvo, un tevi teic, ka tu sev labas dienas sagādājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Tomēr tu noiesi pie viņa tēvu radiem, kas gaismu neredz ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Cilvēks, kas greznībā un nav prātīgs, tas līdzinājās lopiem, ko nokauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Asafa dziesma. Tas stiprais Dievs, Dievs Tas Kungs, runā, un sauc zemi no rītiem līdz vakariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'No Ciānas, kur tas pilnīgais skaistums, Dievs parādās ar spožumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Mūsu Dievs nāk un necieš klusu; rijoša uguns iet Viņa priekšā, un Viņam apkārt liela vētra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Viņš sauc debesīm augšā, un zemei, tiesāt Savus ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Sapulcinājiet Man Manus svētos, kas Manu derību derējuši ar upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Un debesis stāsta Viņa taisnību, jo Dievs pats ir soģis. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Klausiet, Mani ļaudis, Es runāšu; Israēl, Es došu liecību pret tevi: Es, Dievs, esmu tavs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Tavu upuru pēc Es tevi nepārmācu, nedz tavu dedzināmo upuru pēc, kas vienmēr Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'No tava nama Es vēršus neņemšu, nedz āžus no taviem laidariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Jo visi meža zvēri Man pieder, tie lopi uz kalniem pa tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Es zinu visus putnus uz kalniem, un tie zvēri laukā ir manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Ja Man gribētos ēst, tad Es tev to nesacītu, jo Man pieder pasaule un viņas pilnums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Vai Man ēst vērša gaļu un dzert āžu asinis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Upurē Dievam pateicību un maksā tam Visuaugstam savus solījumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Un piesauc Mani bēdu laikā, tad Es tevi gribu izraut, un tev būs Mani godāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Bet uz bezdievīgo Dievs saka: kā tu drīksti daudzināt Manus likumus un Manu derību ņemt savā mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Kad tu tomēr ienīsti pārmācību, un laidi pār galvu Manus vārdus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Kad tu zagli redzi, tad tu viņam skrej līdz, un tev ir dalība ar laulības pārkāpējiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Ar savu muti tu dodies uz ļaunu, un tava mēle dzen viltību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Tu sēdi runādams pret savu brāli, tavas mātes dēlu tu apmelo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'To tu dari, un kad Es ciešu klusu, tad tu domā, ka Es tāds pat esmu kā tu; bet Es tevi pārmācīšu un tev to turēšu priekš acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Saprotiet jel to, jūs, kas Dievu aizmirstat, lai Es nesaplosu, un izglābēja nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kas pateicību upurē, tas Mani tur godā; un tas ir tas ceļš, kā Es tam rādīšu Dieva pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Dāvida dziesma. Dziedātāju vadonim. Kad pravietis Nātans pie viņa nāca, kad viņš bija gājis pie Batsebas. Apžēlojies par mani, ak Dievs, pēc Savas žēlastības, izdeldē manus pārkāpumus pēc Savas lielās sirdsžēlastības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Mazgā mani labi no manas noziedzības un šķīstī mani no maniem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Jo es atzīstu savus pārkāpumus, un mani grēki ir manā priekšā vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Tev vienam es esmu grēkojis un ļaunu darījis priekš Tavām acīm, ka Tu palieci taisns Savos vārdos un šķīsts Savā tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Redzi, noziedzībā esmu dzemdināts, un grēkos māte mani ieņēmusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Redzi, tev patīk sirds patiesība, tad dari man zināmu to apslēpto gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Šķīstī mani no grēkiem ar īzapu, ka topu šķīsts, mazgā mani, ka topu baltāks nekā sniegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Liec man dzirdēt prieku un līksmību, ka tie kauli līksmojās, ko Tu esi satriecis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Apslēp Savu vaigu no maniem grēkiem un deldē visu manu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Radi iekš manis, ak Dievs, šķīstu sirdi un atjauno iekš manis pastāvīgu garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Nemet mani nost no Sava vaiga, un neatņem no manis Savu Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Atdod man atkal Savas pestīšanas prieku, un uzturi mani ar labprātīgu garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Tad es mācīšu pārkāpējiem Tavus ceļus, ka grēcinieki pie Tevis atgriežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Izglābi mani no asins vainām, ak Dievs, tu Dievs mans Pestītājs; tad mana mēle slavēs Tavu taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Kungs, atdari manas lūpas, tad mana mute izteiks Tavu slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Jo Tev netīk upuris, citādi es to gribētu dot, dedzināms upuris Tev nepatīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Dieva upuris ir satriekts gars; salauztu un sagrauztu sirdi Tu, Dievs, nesmādēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Dari labu Ciānai pēc Savas labprātības, uztaisi Jeruzālemes mūrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Tad Tev patiks taisnības upuri, dedzināmais un visa(kopējais) sadedzināmais upuris, tad upurēs vēršus uz Tava altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Dāvida mācības dziesma dziedātāju vadonim, Kad Doēgs, tas Edomietis, nāca un Saulam sludināja un tam sacīja: Dāvids ir nācis Aķimeleka namā. Ko tu lielies ar ļaunumu, tu varmāka? Dieva žēlastība pastāv vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Tava mēle meklē postu kā trīts dzenams nazis, tu viltus perētājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Tu mīļo ļaunumu vairāk nekā labumu, un melus vairāk nekā taisnību. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Tu labprāt runā posta vārdus, tu viltus mēle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Tad Dievs arī tevi postīs mūžīgi, Viņš tevi sagrābs un tevi izraus no dzīvokļa, un izsakņos no dzīvības zemes. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Un tie taisnie to redzēs un bīsies un smiesies par viņu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Redzi, tas ir tas vīrs, kas Dievu neturēja par savu spēku, bet paļāvās uz savu lielo bagātību; tas bija varens savā ļaunumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Bet es būšu kā zaļš eļļas koks Dieva namā, es paļaujos uz Dieva žēlastību mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Es Tev pateikšos mūžam, ka Tu to esi darījis, un gaidīšu uz Tavu Vārdu, jo tas ir labs priekš Taviem svētiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Dāvida mācības dziesma. Dziedātāju vadonim ar stabulēm. Ģeķis saka savā sirdī: Dieva nav. Tie samaitājās un sagānās ar netaisnību, nav neviena, kas labu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Dievs skatās no debesīm uz cilvēku bērniem, redzēt, vai jel kas esot prātīgs, kas Dievu meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Bet tie visi atkāpušies, tie kopā samaitājušies; nav, kas labu dara, it neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Vai tad to neatzīst tie ļauna darītāji, kas manus ļaudis ēd, kā ēd maizi, bet Dievu tie nepiesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Tad tiem uzkrita bailes, kur bailes nebija; jo Dievs izklīdināja tavu spaidītāju kaulus; Tu tos liki kaunā, jo Dievs tos bija atmetis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ak, kaut Israēla pestīšana nāktu no Ciānas! Kad Dievs novērsīs Savu ļaužu cietumu, tad Jēkabs priecāsies un Israēls līksmosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Dāvida mācības dziesma. Dziedātāju vadonim, uz koklēm. Kad Zifieši nāca un Saulam sacīja: vai Dāvids pie mums nav paslēpies? Ak Dievs atpestī mani caur Savu vārdu un nes man tiesu caur Savu varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Ak Dievs, klausi manu lūgšanu, liec vērā, ko mana mute runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Jo svešinieki ceļas pret mani, un briesmīgi ļaudis meklē manu dvēseli; tie netur Dievu priekš savām acīm. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Redzi, Dievs man ir par palīgu; Tas Kungs ir tas, kas manu dvēseli uztur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Viņš maksās to ļaunumu maniem nicinātājiem; izdeldē tos pēc Tavas uzticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Tad es Tev upurēšu ar labu prātu, es pateikšos, Kungs, Tavam Vārdam, ka tas ir tik labs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Jo Viņš mani izglābis no visām bēdām, ka mana acs ar prieku uzlūko manus ienaidniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Dāvida mācības dziesma, dziedātāju vadonim, uz koklēm. Griezies, ak Dievs, pie manas lūgšanas un nepaslēpies no manām sirds nopūtām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Liec mani vērā un paklausi mani; es esmu pilns nemiera savās raizēs, ka man jānopūšās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Tāpēc ka ienaidnieks kliedz un bezdievīgais spaida; jo tie gāž postu uz mani un ienīst mani ar dusmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Mana sirds mokās iekš manis, un nāves izbailes man uzkritušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Trīcēšana un drebēšana man uzgājusi, un bailes man uzbrukušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Es sacīju: kaut man būtu spārni kā balodim; es gribētu skriet, kur varētu palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Redzi, es tālu nobēgtu un apmestos tuksnesī. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Steigšus es izglābtos no bargas aukas un vētras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Aprij tos, Kungs, sajauc viņu mēles; jo es redzu varas darbus un ķildas pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Dienām naktīm tādas lietas ir pa viņas mūriem, un netaisnība un varas darbs ir viņas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Posts tur iekšā, pārestība un viltība neatstājās no viņas ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Jo tas nav ienaidnieks, kas mani apkauno, to es varētu panest; tas nav mans nīdētājs, kas pret mani lielās, priekš tā es varētu apslēpties;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Bet tu esi cilvēks no manas kārtas, mans biedrs un mans draugs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Mēs kopā mīļi sarunājamies un kopā gājām Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Lai nāve tiem uzbrūk, lai tie dzīvi nogrimst ellē, jo blēdības ir iekš viņu dzīvokļiem pašā viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Bet es piesaukšu Dievu, un Tas Kungs mani izpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Vakaros un rītos un dienas vidū es nopūtīšos un žēlošos, tad Viņš klausīs manu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Viņš uz mieru atpestī manu dvēseli no tiem, kas pret mani karo, jo to ir liels pulks man pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Tas stiprais Dievs, kas mūžam paliek, mani paklausīs un tos pazemos. (Sela.) Jo tie nemaz neatgriežas un Dievu nebīstas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Jo tie pieliek savas rokas pie viņa draugiem un sagāna viņa derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Viņu mute ir glumāka nekā sviests, bet viņu sirdī ir karš; viņu vārdi ir mīkstāki nekā eļļa, un ir taču pliki zobeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Met savu nastu uz To Kungu, Tas tevi uzturēs; Viņš ne mūžam neļaus, ka taisnais šaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Bet Tu, ak Dievs, tos nometīsi dziļā bedrē. Tie asins kārīgie un viltnieki nepanāks ne pusmūžu; bet es uz Tevi paļaujos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Dāvida sirds dziesma dziedātāju vadonim, pēc: „mēmais balodis svešumā“; kad Fīlisti Gatā viņu bija saņēmuši. Apžēlojies par mani, ak Dievs, jo cilvēki mani grib aprīt; cauru dienu pretinieks mani apbēdina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Mani ienaidnieki cauru dienu mani grib aprīt, jo daudz ir, kas man pretī stāv lepnībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Baiļu dienā es uz Tevi paļaujos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Iekš Dieva es slavēšu Viņa vārdu, es paļaušos uz Dievu un nebīšos; ko miesa man darīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Cauru dienu tie pārgroza manus vārdus, visas viņu domas pret mani ir uz ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Tie turas kopā un glūn, tie apsargā manas pēdas, tā kā kas pēc manas dvēseles tīko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Vai tad tie ar tādu netaisnību izglābsies? Gāz zemē, ak Dievs, tos ļaudis iekš dusmības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Tu skaiti manas bēgšanas, saņem traukā manas asaras; vai tās nav Tavā grāmatā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Tad mani ienaidnieki griezīsies atpakaļ tai dienā, kad es saukšu; to es zinu, ka Dievs ir ar mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Iekš Dieva es slavēšu to vārdu, iekš Tā Kunga es slavēšu to vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Es paļaujos uz Dievu, es nebīšos; ko cilvēki man var darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Tev, Dievs, es esmu apsolījies, Tev es maksāšu pateicības upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Jo Tu manu dvēseli esi izglābis no nāves, ir manu dvēseli no slīdēšanas, ka es priekš Dieva vaiga staigāju dzīvības gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Dāvida sirds dziesma. Dziedātāju vadonim, pēc: „nesamaitā“; kad tas no Saula bēga alā. Apžēlojies par mani, ak Dievs, apžēlojies par mani, jo uz Tevi cerē mana dvēsele, un apakš Tavu spārnu ēnas es gribu cerēt, kamēr nelaime būs pārgājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Es piesaukšu Dievu, to visuaugsto, to stipro Dievu, kas par mani visu izdarīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Viņš sūta no debesīm un palīdz man, un apkauno manu aprijēju. (Sela.) Dievs sūta Savu žēlastību un patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Mana dvēsele ir starp lauvām; es guļu starp cilvēku bērniem kā starp liesmām; viņu zobi ir šķēpi un bultas, un viņu mēle ass zobens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Parādi, Dievs, Savu augstību pār debesīm, un Savu godību pār visu pasauli!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Tie izpleš tīklu maniem soļiem, mana dvēsele ir nospiesta; manā priekšā tie bedri rakuši, paši krituši iekšā. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Mana sirds ir droša, Dievs, mana sirds ir droša, es dziedāšu un slavēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Uzmosties, mans gods, uzmostaties, stabules un kokles, es uzmodīšos ar rīta blāzmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Es Tev pateikšos, Kungs, starp tiem ļaudīm, es Tevi slavēšu starp tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Jo Tava žēlastība ir liela līdz debesīm, un Tava patiesība līdz padebešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Parādi, Dievs, Savu augstību pār debesīm, Savu godību pār visu pasauli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Dāvida sirds dziesma. Dziedātāju vadonim, pēc: „nesamaitā.“Vai tad jūs esat mēmi, ka nerunājat taisnību un nepareizi tiesājat, jūs cilvēku bērni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Tiešām, savā sirdī jūs darāt netaisnību virs zemes, ar savām rokām jūs dzenaties uz varas darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Bezdievīgie maldās no mātes klēpja, kas melus runā, alojās no pašām mātes miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Tiem ir tāds niknums kā čūsku dzelonis, kā kurlai odzei, kas savu ausi aizbāž,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Ka tā nedzird vārdotāja balsi, kas labi māk apvārdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Ak Dievs, salauzi viņiem zobus mutē, ak Kungs, izrauj jauno lauvu dzerokļus!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Lai tie izšķīst kā ūdens, kas notek; kad tie uzvelk savas bultas, tad lai tās ir kā aplauztas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Tā kā gliemezis, kas izkūst, tā lai tie izgaist tā kā sievas nelaikā dzimis bērns, tā lai tie neredz saules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Pirms jūsu ērkšķi dabūs asus galus, viņš tos aizraus dzīvus, kā ar karstu dusmību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Tas taisnais priecāsies, kad viņš redz atriebšanu, viņš mazgās savas kājas bezdievīgo asinīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Un cilvēki sacīs: tam taisnam būs augļi; tiešām, Dievs ir soģis virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Dāvida sirds dziesma, pēc: „nesamaitā“; kad Sauls nosūtīja, vaktēt to namu, ka viņu nokautu. Izglāb mani, mans Dievs, no maniem ienaidniekiem, pasargi mani no tiem, kas pret mani ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Izglāb mani no ļauna darītājiem un atpestī mani no asins ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Jo redzi tie glūn uz manu dvēseli, vareni sapulcējās pret mani, lai gan neesmu grēkojis nedz noziedzies, ak Kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Bez vainas tie tek un sataisās. Uzmosties man palīgā un skaties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Tu, ak Kungs, Dievs Cebaot, Israēla Dievs, uzmosties, piemeklēt visus pagānus, neapžēlojies par nevienu, kas tik viltīgi dodas uz netaisnību. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Vakarā tie atnāk, rūc kā suņi, un tekā(skraida) apkārt pa pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Redzi, tie ar savu muti plukšķ, zobeni ir viņu lūpās, jo - kas to dzird?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Bet Tu, Kungs, par tiem smiesies, Tu apmēdīsi visus pagānus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Pret viņu varu es gaidīšu uz Tevi, jo Dievs ir mans patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Dievs man bagātīgi parāda Savu žēlastību, Dievs man liek ar prieku uzlūkot savus pretiniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Nenokauj tos, ka mani ļaudis to neaizmirst, izklīdini tos ar Savu varu, un nogāz tos, ak Kungs, mūsu priekšturamās bruņas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Tīri grēks ir viņu lūpu vārdi, tāpēc lai tie top sagūstīti savā lepnībā, viņu lādēšanas un to melu pēc, ko tie runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Izdeldē tos dusmībā, izdeldē tos, ka to vairs nav, un lai atzīst, ka Dievs ir valdītājs iekš Jēkaba līdz pasaules galam. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Vakarā tie atnāk, rūc kā suņi, un tekā apkārt pa pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Tie skraida šurp un turp barības pēc, un kad nav paēduši, paliek pa nakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Bet es dziedāšu no Tava stipruma un teikšu rītos Tavu žēlastību, jo Tu man esi bijis augsts patvērums un glābšana bēdu dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'No Tevis es dziedāšu, mans stiprums, jo Tu, Dievs, esi mans patvērums, mans žēlīgais Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Dāvida sirds dziesma. Dziedātāju vadonim, iemācīt pēc: „lilija ir liecība“; Kad viņš kāvās ar Sīriešiem no Mezopotamijas un ar Sīriešiem no Cobas, un Joabs nāca atpakaļ un sakāva no Edomiešiem divpadsmit tūkstošus sāls ielejā. Dievs, Tu mūs esi atmetis, izkaisījis, Tu esi bijis dusmīgs, griezies atkal pie mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Tu zemi esi kustinājis un šķēlis, dziedini viņas plīsumus, jo viņa šaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Tu Saviem ļaudīm grūtumu esi licis redzēt, ar reibuma vīnu Tu mūs esi dzirdinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Tiem, kas Tevi bīstas, Tu esi devis karogu, celties patiesības labad. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Lai Tavi mīļie taptu atsvabināti, tad palīdzi nu ar Savu labo roku un paklausi mūs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Dievs runā Savā svētā vietā, par to es priecājos; es dalīšu Šehemi un mērošu Sukota ieleju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Gileāds Man pieder, un Manasus Man pieder, un Efraīms ir Manas galvas stiprums, Jūda ir Mans valdības zizlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moabs ir Mans mazgājamais trauks; Savu kāju Es stiepju pār Edomu; tu, Fīlistu zeme, kliedzi par Mani!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kas mani vadīs tai stiprā pilsētā? Kas mani pavadīs līdz Edomam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Vai ne tu, Dievs, kas mūs biji atmetis un neizgāji, ak Dievs, ar mūsu karaspēku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Dod mums palīgu bēdu laikā, jo cilvēku pestīšana nav nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Ar Dievu darīsim stiprus darbus. Viņš samīdīs mūsu pretiniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Dāvida dziesma. Dziedātāju vadonim, uz koklēm. Klausi, ak Dievs, manu saukšanu, ņem vērā manu lūgšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'No zemes gala es Tevi piesaucu, kad mana sirds bēdājās; vadi Tu mani uz akmens kalnu, jo man tas par augstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Jo Tu man esi patvērums, stiprs tornis pret maniem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Es palikšu Tavā dzīvoklī mūžīgi, es patveršos Tavu spārnu pavēnī. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Jo Tu, Dievs, esi klausījis manas solīšanas, Tu devis mantību tiem, kas Tavu Vārdu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Tu vairosi ķēniņam dzīvības laiku; viņa gadi paliks līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Viņš sēdēs mūžīgi Dieva priekšā; parādi viņam žēlastību un patiesību, kas viņu pasargā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Tad es dziedāšu Tavam Vārdam mūžīgi, lai es maksāju savus solījumus dienu no dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Dāvida dziesma. Dziedātāju vadonim, Jedutunam. Tiešām, mana dvēsele ir klusu uz Dievu, no Viņa nāk mana pestīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Tiešām, Viņš ir mans akmens kalns un mans Pestītājs, mans patvērums, ka es daudz nešaubīšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Cik ilgi jūs visi vienam krītat virsū, to satrieciet kā ielīkušu sienu un iedauzītu mūri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Viņi uz to vien domā, viņu nogāzt no viņa godības; tiem patīk meli; ar savu muti tie svētī, bet sirds dziļumā tie lād. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Tiešām, mana dvēsele, esi klusu uz Dievu, jo no Viņa ir mana cerība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Viņš vien ir mans akmens kalns un mans Pestītājs, mans patvērums, ka es nešaubīšos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Pie Dieva ir mana pestīšana un mans gods, mana stipruma klints, mana cerība stāv uz Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Cerējiet uz Viņu vienmēr, jūs ļautiņi, izgāziet savu sirdi Viņa priekšā; Dievs mums ir par patvērumu. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Tiešām, cilvēku bērni nav nekas, lieli ļaudis ir nelietība; uz svariem likti tie kopā būtu vieglāki nekā vējš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Nepaļaujaties uz netaisnību un uz laupījumu neliekat tukšu cerību; kad bagātība vairojās, tad nedodaties uz to ar savu sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Dievs vienu vārdu ir runājis, to dažkārt esmu dzirdējis, ka Dievs ir varens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Un Tu, ak Kungs, esi žēlīgs, jo Tu maksā ikvienam pēc viņa darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Dāvida dziesma, kad viņš bija Jūda tuksnesī. Ak Dievs! Tu esi mans stiprais Dievs, Tevi es meklēju pašā rītā, pēc Tevis slāpst manai dvēselei, pēc Tevis ilgojās mana miesa sausā un izkaltušā zemē, kur ūdens nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Tā es svētā vietā pēc Tevis esmu skatījies, redzēt Tavu spēku un Tavu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Jo Tava žēlastība ir labāka nekā dzīvība; manas lūpas Tevi slavē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Tā es Tevi gribētu teikt mūžam, un pacelt savas rokas Tavā Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Tad mana dvēsele taptu paēdināta kā ar taukumiem un gardumiem, un mana mute Tevi slavētu ar priecīgām lūpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Es Tevi pieminu apguldamies, un uzmozdamies es domāju uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Jo Tu esi mans palīgs, un Tavu spārnu pavēnī es dziedāšu priecīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Mana dvēsele Tev pieķeras, Tava labā roka mani tura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Bet tie, kas manu dvēseli meklē izpostīt, nogrims pašos zemes dziļumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Tos nodos zobena asmenim un tie būs lapsām par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Bet ķēniņš priecāsies iekš Dieva; kas pie tā zvēr, tas lielīsies; jo melkuļu mute taps aizbāzta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Dāvida dziesma. Dziedātāju vadonim. Klausi, ak Dievs, manu balsi, kad es žēlojos; pasargi manu dzīvību no ienaidnieku briesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Apslēp mani no ļaunu ļaužu padomiem, no ļaundarītāju trakošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Tie savas mēles trin kā zobenu, un uzvelk savas bultas, savus rūgtos vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Šaut slepeni nenoziedzīgam; tie šauj viņam piepeši un nebīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Tie iedrošinājās paši ļaunā padomā, tie runā, slepeni likt valgus, un saka: kas to redzēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Tie domā uz visādu blēdību, tiem gatavs ir viņu gudrais padoms, prātu un sirdi nevienam nevar izdibināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Bet Dievs ar bultu tos šaus piepeši, ka tiem gan sāpēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Caur savu pašu mēli tie taps apgāzti; ikkurš, kas uz tiem skatās, bēgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Un visi cilvēki bīsies un sacīs: to Dievs ir darījis, un sapratīs, ka tas ir Viņa darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Tas taisnais priecāsies iekš Tā Kunga, un paļausies uz Viņu, un visi sirdsskaidrie teiktin teiksies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Dāvida dziesma. Dziedātāju vadonim. Dievs, klusībā iekš Ciānas Tu topi slavēts, un solījumi Tev top maksāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Tu paklausi lūgšanas, visa miesa nāk pie Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Noziegumi mūs ir pārvarējuši, - mūsu pārkāpumus, tos Tu salīdzini!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Svētīgs tas, ko Tu izredzi, un kam Tu vaļu dod pie Tevis nākt un dzīvot Tavos pagalmos; mēs tapsim paēdināti no Tava nama labuma Tavā svētā dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Paklausi mūs pēc tās taisnības, kas brīnišķas lietas dara, ak Dievs, mūsu Pestītājs, Tu patvērums visām zemes robežām, un tiem, kas tālu pie jūras dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Tu stiprini kalnus ar Savu spēku, Tu apjozies ar varu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Tu klusini jūras kaukšanu, viņas viļņu kaukšanu un ļaužu troksni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Ka tie, kas dzīvo tanīs robežās, bīstas no Tavām zīmēm. Tu iepriecini visu, kas kust, vakarā un rītā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Tu piemeklē zemi un to dzirdini un to dari ļoti bagātu. Dieva upīte ir ūdens pilna. Tu liec viņu labībai labi izdoties, jo tā Tu zemi apkopi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Tu slacini viņas vagas, un liec lietum līt uz viņas arumiem; Tu tos dari mīkstus caur lāsēm, Tu svētī viņas asnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Tu pušķo gadu ar Savu labumu, un Tavas pēdas pil no taukumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Tuksneša ganības pil un pakalni ar prieku ir apjozti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Lauki ir apģērbti ar ganāmiem pulkiem, un ielejas ar labību apklātas, ka gavilē un dzied.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Dziesma dziedātāju vadonim. Gavilējiet Dievam, visa zeme!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Dziediet Viņa vārda godībai, teiciet Viņa godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sakait uz Dievu: kāds bijājams Tu esi Savos darbos! Tavi ienaidnieki Tev padosies Tavas lielās varas pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Lai visa zeme Tevi pielūdz un Tev dzied, lai dzied Tavam Vārdam! (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Nāciet un raugāt Dieva darbus. Viņš ir bijājams Savos darbos pie cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Viņš pārvērta jūru par sausumu, kājām varēja iet caur upi; par to mēs iekš Viņa priecājamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Viņš valda mūžīgi ar Savu spēku, Viņa acis raugās uz tautām, Viņš atkāpējiem neļauj paaugstināties. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Teiciet mūsu Dievu, jūs tautas, liekat dzirdēt Viņa teikšanas slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Viņš uztur dzīvas mūsu dvēseles un neliek slīdēt mūsu kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Jo Tu, Dievs, mūs esi pārbaudījis; Tu mūs esi kausējis, kā sudrabu kausē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu mums esi licis iekrist valgos, uz mūsu muguru Tu esi licis grūtu nastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Tu cilvēkiem esi licis celties pār mūsu galvu; mēs bijām nākuši ugunī un ūdenī, bet Tu mūs esi izvedis pie atspirgšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Es iešu Tavā namā ar dedzināmiem upuriem, es Tev maksāšu savu apsolījumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Uz ko manas lūpas ir atdarījušās, un ko mana mute runājusi, kad man bija bail.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Es tev upurēšu taukus dedzināmos upurus ar kvēpināšanu no auniem; es Tev upurēšu vēršus ar āžiem. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Nāciet, klausāties visi, kas Dievu bīstaties: es jums izteikšu, ko Viņš darījis pie manas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Viņu es piesaucu ar savu muti, un Viņš tapa slavēts no manas mēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Ja es netaisnību atrastu savā sirdī, tad Tas Kungs mani nebūtu klausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Bet tiešām, Dievs ir klausījis, manas lūgšanas balsi Viņš ņēmis vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Slavēts Dievs, kas nav atmetis manu lūgšanu, nedz novērsis Savu žēlastību no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Dziesma dziedātāju vadonim, dziedama uz koklēm. Lai Dievs par mums apžēlojās un mūs svētī, lai Viņš apgaismo Savu vaigu pār mums! (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Ka virs zemes Tavs ceļš top zināms, starp visiem pagāniem Tava pestīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Tev, Dievs, pateicās ļaudis, Tev pateicās visi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Tautas priecājās un gavilē, ka Tu ar taisnību tiesā ļaudis un vadi tautas zemes virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Tev, Dievs, pateicās ļaudis, Tev pateicās visi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Zeme izdod savus augļus; Dievs, mūsu Dievs, svētī mūs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Svēti mūs, Dievs, un visi zemes gali lai Viņu bīstas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Dāvida dziesma, dziedātāju vadonim dziedama. Lai Dievs ceļas, ka Viņa ienaidnieki top izklīdināti, un Viņa nīdētāji bēg Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Izdzen tos, tā kā dūmi top izdzīti; tā kā vasks ugunī top kausēts, tāpat bezdievīgie ies bojā Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Bet taisnie priecāsies un līksmosies Dieva priekšā, un no sirds dibina(dziļuma) priecāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Dziediet Dievam, dziediet Viņa vārdam, sataisiet ceļu Tam, kas brauc pa tuksnešiem. Viņa vārds ir Kungs, - un līksmojaties Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Viņš ir bāriņu tēvs un atraitņu tiesnesis, Viņš ir Dievs Savā svētā dzīvoklī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Tāds Dievs, kas vientuļiem dod namā dzīvot, kas cietumniekus izved pie labklāšanās; bet atkāpējiem jādzīvo tukšumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Dievs, kad Tu gāji Savu ļaužu priekšā, kad Tu staigāji tuksnesī, (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Tad zeme drebēja un debesis pilēja Dieva priekšā, un tas Sinaī, Tā Dieva priekšā, kas ir Israēla Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Tu, Dievs, devi nolīt bagātam lietum; Savu iemantojamo tiesu, kas bija noguruši, Tu spirdzināji,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Ka Tava draudzīte tur var dzīvot; Tu, Dievs, atspirdzini bēdīgos ar Savu labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Tas Kungs dod vēsti ar lielu pulku priecas sludinātāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Karaspēku ķēniņi bēga, tie bēga, un nama dzīvotāja izdalīja laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Kad lēģerī esat apmetušies, tad jūs spīdiet kā baložu spārni ar sudrabu apklāti, un kam ir spalvas kā zaļgans zelts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Kad tas Visuvarenais tur ķēniņus izkaisa, tad ir balts kā sniegs uz Zalmona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Dieva kalns ir Basanas kalns, kalns ar daudz virsotnēm ir Basanas kalns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Kāpēc jūs apskaužat, jūs augstie kalni to kalnu, kur Dievam patīk mājot? Tiešām, Tas Kungs tur dzīvos mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Dieva ratu ir daudz tūkstošu tūkstoši, Tas Kungs ir viņu vidū, tā kā uz Sinaī Savā svētumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Tu esi uzkāpis augstībā, cietumu Tu esi vedis cietumā, par dāvanām Tu esi dabūjis cilvēkus, arī atkāpējus, ka tie dzīvo, ak Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Slavēts lai ir Tas Kungs, ikdienas Viņš nes mūsu nastu; Dievs ir mūsu pestīšana. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Dievs mums ir Dievs, kas pilnīgi izpestī, un pie Tā Kunga Dieva ir izvešana no nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Tiešām, Dievs sadauzīs pieri Saviem ienaidniekiem, un matu pilno galvu tiem, kas staigā savos noziegumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Tas Kungs saka, Es atvedīšu, Es atvedīšu atkal no Basanas, Es atvedīšu atkal no jūras dziļumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Tādēļ tu mērksi savu kāju ienaidnieku asinīs, un tavi suņi tās laizīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Tavi gājumi, ak Dievs, top redzēti, mana stiprā Dieva, mana ķēniņa, gājumi svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Dziedātāji iet papriekš, spēlētāji pakaļ bungotāju meitu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Teiciet Dievu, To Kungu, draudzes sapulcē, jūs, kas no Israēla avota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Tur pār tiem valda mazais Benjamins, Jūda lielkungi ar saviem pulkiem, Zebulona lielkungi, Naftalus lielkungi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Tavs Dievs ir pavēlējis tavai valstij būt stiprai; stiprini, ak Dievs, ko Tu mums par labu esi darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Tava nama dēļ Jeruzālemē ķēniņi Tev atnesīs dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Rāj to zvēru niedrēs, to vēršu pulku ar tautu teļiem, lai tie zemē metās ar sudraba gabaliem. Viņš izklīdina tautas, kam tīk karot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Lieli kungi nāks no Ēģiptes, Moru zeme steigsies, izstiept savas rokas uz Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Jūs pasaules valstis, dziediet Dievam, dziediet Tam Kungam, (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Tam, kas brauc pa debesu debesīm, kas no iesākuma. Redzi, Viņš dos Savam pērkonam spēcīgu skaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Dodiet Dievam godu! Viņa augstība ir pār Israēli, un Viņa spēks pār augstiem padebešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Dievs, Tu esi bijājams no Savas svētās vietas, Tu stiprais Israēla Dievs. Viņš dod tiem ļaudīm stiprumu un spēku, - slavēts lai ir Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Dāvida dziesma. Dziedātāju vadonim, pēc: „lilijas“. Dievs, palīdz man; jo ūdeņi ir nākuši līdz pašai dvēselei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Es grimstu dziļos dubļos, kur nevar stāvēt, es esmu nācis dziļos ūdeņos un viļņi mani apklāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Es esmu piekusis no savas saukšanas, mans kakls ir aizsmacis, manas acis īgst, - tomēr es gaidu uz savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Vairāk nekā matu uz manas galvas ir to, kas mani bez vainas ienīst; vareni ir tie, kas mani grib samaitāt, kas mani par nepatiesu ienīst; man jāmaksā, ko es neesmu laupījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Ak Dievs, Tu zini manu ģeķību, un mani noziegumi Tev nav apslēpti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Lai pie manis netop kaunā, kas Tevi gaida, ak Kungs, Dievs Cebaot! lai pie manis netop kaunā, kas Tevi meklē, ak Israēla Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Jo Tevis pēc es nesu negodu; mans vaigs ir apklāts ar kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Es esmu palicis svešs saviem brāļiem un svešinieks savas mātes bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Jo karstums Tava nama labad mani ir ēdis, un Tavu zaimotāju zaimošana ir kritusi uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Un es raudu, un mana dvēsele gavē, bet tas man ir tapis par kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Es esmu apvilcis maisu, bet es tiem esmu tapis par sakāmu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Kas vārtos sēž, tie plukšķ par mani, un es esmu par smieklu vīna dzērājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Bet es Tevi pielūdzu, Kungs, pieņēmīgā laikā; pēc Savas lielās žēlastības, ak Dievs, paklausi mani, pestīdams pēc Savas patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Izrauj mani no dubļiem, ka es neapslīkstu, ka es topu izglābts no nīdētājiem un no dziļiem ūdeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Lai ūdens viļņi mani neapklāj, un dziļumi lai mani neaprij, un bedres malas lai nesagāžas kopā pār mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Paklausi mani, ak Kungs, jo Tava žēlastība ir laba; griezies pie manis pēc Savas lielās sirds žēlastības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Un neapslēp Savu vaigu priekš Sava kalpa, jo man ir bail; steidzies, paklausi mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Nāc klāt pie manas dvēseles, atpestī to, izglāb mani manu ienaidnieku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Tu zini manu kaunu un manu negodu un manu apsmieklu; visi mani pretinieki ir Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Kauns man lauž sirdi, un es nīkstu; es gaidīju, vai kādam nebūtu žēl, bet nav, - un uz iepriecinātājiem, bet es neatrodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Un tie man žulti dod ēst un etiķi dzert, kad es gauži izslāpis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Lai viņu galds viņu priekšā top par valgu, par atmaksu un par slazdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Lai viņu acis top apstulbotas, ka tie neredz, un lai viņu gurni allažiņ šaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Izgāz pār tiem Savu dusmību, un Tava karsta bardzība lai viņus sagrābj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Viņu māja lai top par posta vietu, un neviena lai nav, kas dzīvo viņu dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Jo tie to vajā, ko Tu esi sitis, un apsmej mokas tiem, ko Tu ievainojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Lai tiem krājās noziegums uz noziegumu, ka tie nenāk pie Tavas taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Izdeldē tos no dzīvības grāmatas, ka tie ar tiem taisniem netop uzrakstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Bet es esmu bēdīgs un moku pilns; ak Dievs, Tava pestīšana lai mani paceļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Es slavēšu Dieva vārdu ar dziesmu un Viņu paaugstināšu ar pateicību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Tas patiks Tam Kungam vairāk nekā vērsis, kam ragi un nagi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Tie bēdīgie raugās un priecājās, un jūs, kas Dievu meklējat, jūsu sirds dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Jo Tas Kungs paklausa nabagus, un nenicina Savus cietumniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Lai Viņu teic debesis un zeme, jūra un viss, kas iekš tās kustās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Jo Dievs atpestīs Ciānu un uztaisīs Jūda pilsētas, un tie tur dzīvos un to iemantos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Un Viņa kalpu dzimums to iemantos, un kas Viņa Vārdu mīļo, tie tur dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Dāvida dziesma, dziedātāju vadonim, par piemiņu. Steidzies, ak Dievs, mani izglābt, ak Kungs, man palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Lai top kaunā un kļūst apkaunoti, kas manu dvēseli meklē, lai top atpakaļ dzīti un paliek kaunā, kas priecājās par manu nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Lai tie griežas atpakaļ sava kauna dēļ, kas saka: Tā, tā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Iekš Tevis lai priecājās un līksmojās visi, kas Tevi meklē; lai tie, kas Tavu pestīšanu mīļo, vienmēr saka: augsti slavēts ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Bet es esmu bēdīgs un nabags; - ak Dievs, steidzies pie manis. Tu esi mans palīgs un mans glābējs, ak Kungs, nekavējies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Uz tevi, Kungs, es paļaujos, ne mūžam neliec man palikt kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Izglāb mani caur Savu taisnību un atsvabini mani, atgriez Savu ausi pie manis un atpestī mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Esi man par patvērumu, kur es varu dzīvot, kur vienmēr varu bēgt. Tu esi solījis, mani atpestīt, jo Tu esi mans kalns un mana stiprā pils.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mans Dievs, izglāb mani no bezdievīgā rokas, no netaisnā un varas darītāja rokas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Jo Tu esi mana cerība, Kungs, Dievs, mana drošība no manas jaunības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Uz Tevi es esmu paļāvies no mātes miesām, Tu mani esi izvilcis no mātes miesām, mana dziesma Tevi teic bez mitēšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Es esmu daudziem par ērmu, bet Tu esi mans stiprais patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Lai mana mute pildās ar Tavu teikšanu, cauru dienu ar Tavu godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Neatmet mani vecumā, neatstāj mani, kad spēks man zūd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Jo mani ienaidnieki mani aprunā, un kas uz manu dvēseli glūn, tie kopā spriež padomu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Sacīdami: Dievs viņu ir atstājis, dzenaties pakaļ, sagrābiet viņu, jo glābēja nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Dievs, neesi tālu no manis, mans Dievs, steidzies man palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Lai top kaunā, lai iet bojā, kas manai dvēselei turas pretī, ar kaunu un smieklu lai top apsegti, kas meklē manu nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Bet es vienmēr cerēšu un vairošu visu Tavu slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mana mute izteiks Tavu taisnību, cauru dienu Tavu pestīšanu, jebšu to nemāku izskaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Es staigāšu Tā Kunga spēkā, es pieminēšu Tavu taisnību, Tevi vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Ak Dievs, Tu mani esi mācījis no manas jaunības; un līdz šim es pasludināju Tavus brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Tad nu arīdzan, kad vecums un sirmi mati ir klāt, neatstāj mani, ak Dievs, tiekams es Tavu elkoni būšu pasludinājis bērnu bērniem un Tavu stiprumu visiem pēcnākamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Tava taisnība, ak Dievs, ir it augsta, Tu dari lielas lietas; Dievs, kas ir tāds kā Tu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Tu man lieci redzēt daudz bēdas un mokas, Tu mani darīsi atkal dzīvu, un mani izvilksi no zemes dziļumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Vairo manu godu, un iepriecini mani atkal.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Es Tevi arī slavēšu ar stīgu skaņām par Tavu uzticību, mans Dievs; es Tevi slavēšu ar koklēm, ak Svētais iekš Israēla!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Manas lūpas gavilēs, kad es Tev dziedāšu, un mana dvēsele, ko Tu esi atpestījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Un arī mana mēle Tavu taisnību izrunās cauru dienu, jo tie ir tapuši kaunā un apkaunoti, kas meklē manu nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salamana dziesma. Dievs, dod Savas tiesas ķēniņam, un Savu taisnību ķēniņa dēlam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Ka viņš Tavus ļaudis tiesā ar taisnību, un Tavus bēdīgos ar tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Kalni nesīs tiem ļaudīm mieru, ir pakalni caur taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Viņš nesīs tiesu bēdu ļaudīm un palīdzēs nabagu bērniem un sadauzīs nicinātājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Tevi bīsies, kamēr saule būs un mēnesis spīdēs, līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Viņš nolaidīsies kā lietus uz zāli, kā lāses, kas zemi slacina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Viņa laikā ziedēs taisnais un liels miers, tiekams mēneša vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Viņš valdīs no jūras līdz jūrai, no tās lielās upes līdz zemes galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Viņa priekšā locīsies, kas tuksnesī dzīvo, un Viņa ienaidnieki laizīs pīšļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Ķēniņi no Taršiša un no tām salām atnesīs meslus, Arābijas un Šebas ķēniņi atvedīs dāvanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Visi ķēniņi Viņa priekšā klanīsies, visi pagāni Viņam kalpos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Jo Viņš izglābs to bēdīgo, kas sauc, un to nabagu, kam palīga nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Viņš apžēlosies par nabagu un bēdīgo, un bēdīgo dvēseli Viņš izglābs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Viņš atsvabinās viņu dvēseles no viltības un varas darba, un viņu asinis būs dārgas Viņa acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Un Viņš dzīvos, un Viņam taps dots no Arābijas zelta, un vienmēr priekš Viņa lūgs, ikdienas Viņu teiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Zeme būs labības pilna līdz kalnu galiem, viņas augļi viļņos tā kā Lībanus, un tie, kas pilsētā ir, zaļos kā zāle virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Viņa vārds paliks mūžīgi; kamēr saule būs, Viņa vārds augļosies, un iekš Viņa svētīsies; visi pagāni Viņu slavēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Slavēts lai ir Dievs Tas Kungs, Israēla Dievs, kas vien brīnumus dara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Un slavēts lai ir Viņa godības vārds mūžīgi, un visa zeme lai top pilna Viņa godības. Āmen, Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Še Dāvida, Isajus dēla, lūgšanās beidzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Asafa dziesma. Tiešām, Dievs ir Israēla labums, tiem, kam sirdis ir šķīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Bet gandrīz es būtu paklupis ar savām kājām, mani soļi tik (tikko) neslīdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Jo man bija dusmas par lielīgiem, kad es redzēju, ka bezdievīgiem tik labi klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Jo vārgšanas tiem nav līdz nāvei, un tie resni nobarojušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Tie nav bēdās kā citi ļaudis, un netop mocīti kā citi cilvēki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Tādēļ ar lepnību tie izrotājās un ar blēdību tie apģērbjas kā ar skaistām drēbēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'No taukiem spīd viņu acs, viņu sirdsdomās plūst pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Tie zobo, runā nikni no varas darba, tie lielās pārlieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Tie paceļas ar savu muti līdz debesīm, un viņu mēle šaujās pa zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Tādēļ ļaudis piemetās tiem klāt, un tiem rodas ūdens papilnam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Un tie saka: kā Dievs zinās? Un vai tas Visuaugstais ir zinātājs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Redzi, tādi ir tie bezdievīgie, un tomēr tiem arvien labi klājās pasaulē, un tie vairo savu bagātību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Tiešām, velti es esmu šķīstījis savu sirdi un mazgājis savas rokas nenoziedzībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Un biju mocīts cauru dienu, un sods bija man klāt ik rītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Tomēr ja es sacītu: es runāšu tāpat kā viņi, redz, ar to es apgrēkotos pie Tavu bērnu draudzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Tāpēc es domāju, ka es to varētu saprast, bet tas bija visai grūti priekš manām acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Tiekams es gāju Dieva svētumā un ņēmu vērā, kas viņiem pēcgalā notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Tiešām, tu tos vedi uz slidenām vietām un tos nogāzi, ka tie iet postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kā viņi tik piepeši iet bojā! Tie iznīkst un iet bojā ar briesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Tā kā sapnis zūd, kad uzmostas, tā tev, Kungs, ceļoties viņi nebūs nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Kad rūgta taptu man sirds un riebtu man īkstis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Tad es būtu neprātīgs un nezinātu nekā; es būtu kā lops Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Bet pie Tevis es palieku vienmēr; Tu mani turi pie manas labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tu mani vadīsi pēc Sava padoma, un pēc mani uzņemsi godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kad Tu esi mans, tad man nevajag ne debess, ne zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Jebšu man arī mirtu miesa un sirds, taču Tu, Dievs esi manas sirds patvērums un mana daļa mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Jo redzi, kas tālu no Tevis, tie ies bojā; Tu izdeldē visus, kas no Tevis atkāpjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Bet man tas ir prieks, tuvu būt pie Dieva, ka es savu cerību lieku uz To Kungu Dievu, ka es izteicu visus Tavus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Asafa pamācība. Ak Dievs, kāpēc Tu mūs mūžīgi atstūmis, un Tava dusmība kūp pār Tavas ganības avīm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Piemini Savu draudzi, ko Tu mantojis no veciem laikiem, un Sev par mantību atpestījis, Ciānas kalnu, uz kā Tu dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Cel Savas kājas uz to mūžīgo postījumu; ienaidnieks visu ir samaitājis svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tavi pretinieki rūc Tavā namā, savas zīmes tie likuši par zīmēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Tie izrādās, tā kā biezā mežā cirtēji cirvjus cilā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Un nu tie viņas izgreznojumu visnotaļ sadauza ar cirvjiem un veseriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Tie Tavā svētā vietā met uguni, līdz zemei tie sagāna Tava vārda mājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Tie saka savā sirdī: izpostīsim tos(namus) pavisam; visus Dieva lūgšanas namus tai zemē tie ir sadedzinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Savas zīmes mēs neredzam: neviena pravieša vairs nav, nedz kāda cita pie mums, kas zinātu, cik ilgi tā būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Cik ilgi, ak Dievs, pretinieks nievās, un ienaidnieks zaimos Tavu vārdu mūžam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Kāpēc Tu atrauj Savu roku, ak, Savu labo roku? Izvelc to no Savas azotes un dari galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Taču Dievs ir mans ķēniņš no iesākuma, kas pasniedz visu palīgu zemes virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tu caur Savu spēku jūru esi pāršķīris, Tu esi salauzījis pūķu galvas ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tu esi satriecis levijatana galvas, Tu to esi devis par barību tai tautai tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tu esi izšķēlis avotus un upes, Tu esi izkaltējis varenas upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Tiem pieder diena un nakts, Tu esi radījis gaismu un sauli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tu zemei esi licis visas robežas, vasaru un ziemu Tu esi darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Piemini to, ka ienaidnieks To Kungu nievā, un ģeķu ļaudis zaimo Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Nenodod zvēram Savas ūbeles dvēseli, Savu bēdīgo pulku neaizmirsti mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Piemini to derību, jo zemes alas ir palikušas par slepkavu bedrēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Lai nospiestais neaiziet ar kaunu, lai bēdīgie un nabagi slavē Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Celies, Dievs, iztiesā Savas tiesas, piemini tās nievāšanas, kas Tev notiek no tiem ģeķiem ik dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Neaizmirsti Savu pretinieku kliegšanu; to troksni, kas vienmēr pret Tevi no Taviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Asafa dziesma, dziedātāju vadonim, dziedama, pēc: „nesamaitā!“Mēs Tev pateicamies, Dievs, mēs pateicamies, ka Tavs vārds ir it tuvu; Tavi brīnumi top slavēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '„Kad Es īsto laiku pratīšu, tad Es it taisni tiesāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Zeme un visi viņas iedzīvotāji trīc, bet Es viņas pīlārus esmu stiprinājis.“(Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Es sacīju uz tiem lielīgiem: nelielāties; un uz tiem bezdievīgiem: nelepojaties ar varu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Nelielāties ar varu, un nerunājiet tik pārgalvīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Ka (nekāds palīgs nenāks) nedz no rīta puses, nedz no vakara puses, nedz no tuksneša kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Bet Dievs ir soģis, kas citu pazemo un citu paaugstina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Jo Tam Kungam biķeris ir rokā, kur stiprs vīns papilnam iejaukts, un Viņš dod no tā dzert; bet visiem bezdievīgiem virs zemes būs dzert un izsūkt tās mieles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Bet es to pasludināšu mūžīgi, es dziedāšu Jēkaba Dievam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Un salauzīšu visiem bezdievīgiem galvas, ka taisniem galvas top paaugstinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Asafa dziesma, dziedātāju vadonim, dziedama ar koklēm. Dievs ir atzīts iekš Jūda, iekš Israēla viņa vārds ir liels;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Un Salemē ir Viņa telts, un Ciānā Viņa dzīvoklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Tur Viņš salauza stopa bultas, priekšturamās bruņas un zobenu un karu.(Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Spožs Tu esi un augsts uz kalniem, kur laupījumu sakrāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Tie sirds lepnie ir aplaupīti un guļ savā miegā; visiem vareniem ļaudīm rokas nogurušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'No Tavas rāšanās, ak Jēkaba Dievs, nāves miegā nogāzti rati un zirgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Tu, Tu esi bijājams, un kas Tavā priekšā var pastāvēt Tavas dusmības laikā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'No debesīm Tu lieci dzirdēt tiesu, zeme bīstas un top klusa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Kad Dievs ceļas uz sodību, palīdzēt visiem bēdīgiem virs zemes. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Kad cilvēki bargojās, tad Tavs gods paaugstinājās, un ar visukarstām dusmām Tu apjozies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Solāties un maksājiet Tam Kungam, savam Dievam. Visi, kas ap Viņu, lai nes dāvanas Tam bijājamam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Kas sirdi paņem lieliem kungiem, un ir bijājams pasaules ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Azava dziesma, dziedātāju vadonim Jedutunam. Es saucu ar savu balsi uz Dievu un brēcu, es saucu uz Dievu, un Viņš klausās uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Bēdu laikā es meklēju To Kungu, mana roka izstiepjas naktī un nenogurst, mana dvēsele negribās būt iepriecināma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Kad es Dievu pieminu, tad es nopūšos; kad es apdomāju, tad mana sirds bēdājās. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Tu turi nomodā manas acis es esmu tā izmisis, ka nespēju runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Es pieminu vecos laikus, senos gadus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Es atminu savu dziesmu naktī, mana sirds ir domu pilna, mans gars meklē gaismu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Vai tad Tas Kungs atstums mūžīgi un vairs nebūs žēlīgs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Vai tad Viņa žēlastība mitēsies mūžam? Vai tā solīšana pagalam uz bērnu bērniem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Vai tad Dievs ir aizmirsis žēlot? Vai Viņš aizslēdzis dusmībā Savu sirds žēlastību? (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Tad es saku: tās ir manas bēdas; tā Visuaugstākā labā roka to var nogriezt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Es pieminu Tā Kunga darbus, es tiešām pieminu Tavus brīnumus no veciem laikiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Es pārdomāju visus Tavus darbus un pieminu, ko Tu dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Ak Dievs, Tavs ceļš ir svēts; kur ir tāds liels Dievs, kā Tu, Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Tu esi tas stiprais Dievs, kas brīnumus dara; Savu spēku Tu esi darījis zināmu tautu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Savus ļaudis Tu esi atpestījis ar stipru elkoni, Jēkaba un Jāzepa bērnus. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Ūdeņi Tevi redzēja, ak Dievs! ūdeņi Tevi redzēja un drebēja, pat dziļumi trīcēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Biezie padebeši izgāza ūdeņus, augstie padebeši izlaida pērkonus, un Tavas bultas šaudījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Tavi pērkoni rūca viesulī, zibeņi apspulgoja zemi, zeme trīcēja un drebēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Tavs ceļš bija jūrā un Tavs gājums dziļos ūdeņos, un Tavas pēdas nebija manāmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Tu vadīji Savus ļaudis kā avju pulku caur Mozu un Āronu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Asafa pamācība. Klausiet, mani ļaudis, manu mācību, atgrieziet savas ausis uz manas mutes valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Es atdarīšu savu muti sakāmos vārdos un izrunāšu līdzības no veciem laikiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Ko esam dzirdējuši un zinām, un ko mūsu tēvi mums ir stāstījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'To mēs viņu bērniem neslēpsim, bet izteiksim tiem pēcnākamiem Tā Kunga teicamo slavu un Viņa stiprumu un Viņa brīnumus, ko Viņš darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Jo Viņš ir iecēlis liecību iekš Jēkaba un licis bauslību iekš Israēla, ko Viņš mūsu tēviem pavēlējis, to mācīt saviem bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Ka tie pēcnākamie to zinātu, tie bērni, kas vēl dzims; ka tie celtos un to stāstītu arī saviem bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Un ka tie savu cerību liktu uz Dievu un neaizmirstu Dieva darbus, bet sargātu Viņa pavēles;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Un ka tie nebūtu tādi kā viņu tēvi, atkāpēja un pārgalvīga tauta, kas savā sirdī nebija pastāvīga, un kam gars neturējās pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efraīma dēli, apbruņoti strēlnieki ar stopiem, atkāpās kaušanas dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Tie neturēja Dieva derību un liedzās staigāt Viņa bauslībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Un aizmirsa Viņa darbus un brīnumus, ko Viņš bija parādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Viņu tēvu priekšā Viņš darīja brīnumus Ēģiptes zemē, Coana laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Viņš pāršķīra jūru un lika tiem cauri iet, un pacēla ūdeņus stāvu kā kopu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Un vadīja tos ar padebesi dienā un cauri nakti ar uguns gaišumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Viņš pāršķēla klintis tuksnesī un tos dzirdināja papilnam kā no dziļumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Viņš arī izveda upes no akmens un lika tecēt ūdenim straumēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Taču tie joprojām grēkoja pret Viņu un apkaitināja to Visuaugstāko tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Un kārdināja Dievu savā sirdī, barību prasīdami savai dvēselei,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Un runāja pret Dievu un sacīja: vai Dievs gan varēs sataisīt galdu tuksnesī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Redzi, Viņš gan klinti sitis, ka ūdens iztecējis un upes izplūdušas, vai Viņš arī maizi varēs dot, vai Viņš varēs gādāt gaļu Saviem ļaudīm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Kad Tas Kungs to dzirdēja, tad tas apskaitās, un uguns iedegās pret Jēkabu, un bardzība cēlās pret Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Tāpēc, ka tie neticēja uz Dievu, nedz cerēja uz Viņa pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Tad Viņš pavēlēja padebešiem augšām un atdarīja debesu durvis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Un lika mannai uz tiem līt, ko ēst, un deva tiem labību no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Ikkurš no tiem ēda debesu maizi, Viņš tiem sūtīja barības papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Viņš lika celties austriņam no debesīm un atveda dienvidus vēju caur savu Spēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Un birdināja gaļu uz tiem kā putekļus un spārnainus putnus kā jūras smiltis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Un lika tiem krist viņu lēģera vidū, visapkārt ap viņu dzīvokļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Tad tie ēda un pārēdās; un Viņš tiem lika notikt pēc viņu kārības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Bet pirms tie savu kārību bija pildījuši, kamēr viņu barība vēl bija viņu mutē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Tad Dieva dusmība pret tiem cēlās un nokāva viņu stipros un nomaitāja Israēla jaunekļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Par visu to tie taču vēl vairāk grēkoja un neticēja Viņa brīnumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Tādēļ Tas nobeidza viņu dzīvību nīcībā un viņu gadus ātrā postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Kad Viņš tos kāva, tad tie vaicāja pēc Viņa un atgriezās un steigšus meklēja Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Un atminējās, Dievu esam viņiem par patvērumu, un to visaugstāko Dievu esam viņiem par Pestītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Un tie Viņam smaidīja ar savu muti un Viņam meloja ar savu mēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Jo viņu sirds nepastāvēja pie Viņa, un tie nebija uzticīgi Viņa derībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Bet Viņš bija sirdsžēlīgs un piedeva noziegumu un tos nesamaitāja, bet novērsa dažkārt Savu dusmību un nepamodināja visu Savu bardzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Jo Viņš pieminēja, ka tie ir miesa, tā kā vējš, kas aizskrien un atpakaļ negriežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Cik reiz tie Viņu apkaitināja tuksnesī un Viņu tirināja tai tukšā vietā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Jo tie kārdināja Dievu allaž no jauna un noskumdināja Israēla svēto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Tie nepieminēja Viņa roku nedz to dienu, kad Viņš tos no tā spaidītāja izglāba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Kad Viņš Savas zīmes parādīja Ēģiptē un Savus brīnumus Coana klajumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Un pārvērta viņu upes par asinīm un viņu strautus, ka nevarēja dzert,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Un sūtīja starp tiem kukaiņus, kas tos ēda, un vardes, kas tos samaitāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Un deva viņu augļus spradžiem, un viņu darbus siseņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Un nomaitāja viņu vīnakokus caur krusu un viņu vīģes kokus ar lieliem krusas gabaliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Un nokāva viņu govis ar krusu un viņu sīkos lopus ar zibeņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Un uzgāza tiem Savu karsto dusmību, bardzību un postu un bēdas, un uzlaida tiem nelaimes eņģeļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Un deva vaļu Savai dusmībai un neatrāva viņu dvēseles no nāves, un nodeva viņu lopus mērim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Un kāva visus pirmdzimušos Ēģiptē, vīru pirmdzemdinātos Hama dzīvokļos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Un veda Savus ļaudis kā avis un vadīja tos tuksnesī kā ganāmu pulku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Un vadīja tos bez bēdām, ka tie nebijās, bet viņu ienaidniekus jūra apklāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Un Viņš tos veda Savās svētās robežās, uz šo kalnu, ko Viņa labā roka uzņēmusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Un izdzina viņu priekšā pagānus, un tos izdalīja par mantības daļu un Israēla ciltīm lika dzīvot viņu mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Taču tie kārdināja un apkaitināja to visuaugstāko Dievu un neturēja Viņa liecības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Un atkāpās un atmeta ticību, tā kā viņu tēvi; tie atmuka kā viltīgs stops,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Un Viņu apkaitināja ar saviem elku kalniem un to tirināja ar savām bildēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Dievs dzirdēja un apskaitās, un Israēls Tam ļoti rieba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Un Dievs atstāja to dzīvokli iekš Šīlo, to telti, ko Viņš bija ņēmis par mājas vietu cilvēku starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Un deva viņu spēku cietumā un viņu godību pretinieka rokā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Un nodeva Savus ļaudis zobenam un apskaitās pret Savu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Uguns aprija viņu jaunekļus, un viņu jaunavām nedziedāja kāzu dziesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Viņu priesteri krita caur zobenu, un viņu atraitnes neraudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Tad Tas Kungs uzmodās kā viens, kas gulējis, tā kā varonis kliedz, kas vīnu dzēris,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Un sita Savus pretiniekus no aizmugures, un lika tos kaunā uz mūžīgiem laikiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Un atmeta Jāzepa dzīvokli, un neizvēlēja Efraīma cilti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Bet izvēlēja Jūda cilti, Ciānas kalnu, ko Viņš mīlēja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Un uztaisīja Savu svēto vietu kā debes\'augstumu, stipru, kā pasauli, ko uz mūžīgiem laikiem radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Un Viņš izredzēja Dāvidu, Savu kalpu, un ņēma to no avju laidariem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'No zīdītāju avīm Viņš tam lika nākt, ganīt Jēkabu, Savu tautu un Israēli, Savu mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Un viņš tos ganīja ar skaidru sirdi, un tos valdīja ar prātīgu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Asafa dziesma. Ak Dievs, pagāni Tavā tautā ir ielauzušies, tie ir sagānījuši Tavu svēto namu un Jeruzālemi darījuši par akmeņu kopām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Tavu kalpu apkautas miesas tie ir devuši putniem apakš debess par barību, Tavu svēto miesas zemes zvēriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Viņu asinis tie ir izlējuši ap Jeruzālemi kā ūdeni, un neviena nebija, kas apraka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Mēs saviem kaimiņiem esam palikuši par apsmieklu, mūs apmēda un apsmej tie, kas ap mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Cik ilgi, ak Kungs, vai tad Tu gribi mūžīgi dusmot? Vai tad Tavai bardzībai būs degt kā ugunij?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Izgāz Savu dusmību pār tiem pagāniem, kas Tevi nepazīst, un pār tām valstīm, kas Tavu Vārdu nepiesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Jo tie Jēkabu ēduši un postījuši viņa dzīvokļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Nepiemini mums mūsu tēvu noziegumus; steidzies, Tava sirds žēlastība lai mums nāk pretim, jo mēs esam ļoti panīkuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Palīdzi mums, ak Dievs, mūsu Pestītājs, Sava godājamā vārda dēļ un izglāb mūs un piedod mūsu grēkus Sava vārda dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Kāpēc pagāniem būs sacīt: kur ir viņu Dievs? Lai pagāni priekš mūsu acīm atzīst, ka Tu atriebi Savu kalpu izlietās asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Lai cietumnieku nopūšanās nāk Tavā priekšā: uzturi dzīvus nāves bērnus pēc Tava lielā elkoņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Un atmaksā septiņkārt mūsu kaimiņiem viņu klēpī to nievāšanu, ar ko tie Tevi, Kungs, nievājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Tad mēs, Tavi ļaudis un Tavas ganības avis, Tevi teiksim mūžīgi, Tavu slavu sludināsim uz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Asafa dziesma dziedātāju vadonim, pēc: „Lilijas ir liecība“. Israēla gans, klausies, Tu, kas Jāzepu vadi kā avis; Tu, kas sēdi pār ķerubiem, parādies ar spožumu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Uzmodini savu varu priekš Efraīma, Benjamina un Manasus, un nāc mūs pestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Ak Dievs, atgriez mūs un liec Savam vaigam spīdēt, tad tapsim pestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Kungs, Dievs Cebaot, cik ilgi Tava dusmība kūpēs pie Tavu ļaužu lūgšanas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Tu tos ēdini ar asaru maizi un tos dzirdini ar lielu mēru asaru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Tu mūs esi licis par ķildu mūsu kaimiņiem, un mūsu ienaidnieki mūs apmēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Dievs Cebaot, atgriezi mūs un liec Savam vaigam spīdēt, tad tapsim pestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Vienu vīna koku Tu esi atvedis no Ēģiptes, pagānus Tu esi izdzinis un to dēstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Vietu priekš viņa Tu esi sataisījis un viņam licis iesakņoties, ka viņš zemi piepildījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Kalni ar viņa ēnu ir apklāti un Dieva ciedru koki ar viņa zariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Viņš izplēta savus zarus līdz pat jūrai un savus jaunos zariņus līdz tai lielai upei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Kāpēc tad Tu viņa sētu esi salauzījis, ka visi, kas iet garām, viņu plosa?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Mežacūka viņu izrakusi, un lauka zvēri viņu noēduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Dievs Cebaot, atgriezies jel, skaties no debesīm un redzi un uzlūko šo vīna koku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'To stādu, ko Tava labā roka dēstījusi, un To Dēlu, ko Tu Sev esi izredzējis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Viņš ar uguni ir sadedzināts un izcirsts; no Tava vaiga rāšanas tie iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Tava roka lai ir pār to vīru pie Tavas labās rokas, pār To Cilvēka Dēlu, ko Tu Sev esi izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Tad mēs neatkāpsimies no Tevis; uzturi mūs dzīvus, tad mēs Tavu vārdu piesauksim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Ak Kungs, Dievs Cebaot, atgriez mūs, liec Savam vaigam spīdēt, tad tapsim pestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Asafa dziesma, dziedātāju vadonim uz Ģittit. Dziediet priecīgi Dievam, mūsu stiprumam, gavilējiet Jēkaba Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Uzdziedat dziesmas un dodiet šurp bungas, mīlīgas kokles ar stabulēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Pūtiet trumetes jaunā mēnesī, pilnā mēnesī, mūsu svētku laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Jo tas ir likums iekš Israēla, tiesa no Jēkaba Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'To Viņš licis par liecību iekš Jāzepa, kad izgāja pār Ēģiptes zemi, kad es dzirdēju valodu, ko nesapratu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '“Viņa kamiešiem Es esmu atņēmis nastu, un viņa rokas atsvabinājis no nestavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Kad tu Mani piesauci bēdās, tad Es tevi izglābu; Es tevi paklausīju, paslēpies pērkona padebešos, Es tevi pārmanīju pie bāršanās ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Klausāties, Mani ļaudis, Es jums došu liecību; Israēl, kaut tu Mani klausītu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Lai tavā starpā nav cita Dieva, un tev nebūs pielūgt svešu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Es esmu Tas Kungs, tavs Dievs, kas tevi izvedis no Ēģiptes zemes; atplet savu muti, lai Es to pildu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Bet Mani ļaudis neklausa Manu balsi un Israēlim Manis negribās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Tad Es tos arī esmu pametis viņu cietam sirds prātam, ka tie staigā pēc saviem padomiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Kaut Mani ļaudis Man klausītu, un Israēls staigātu uz Maniem ceļiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Es pazemotu viņu ienaidniekus drīz un grieztu Savu roku pret viņu spaidītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Kas To Kungu ienīst, tiem bija Viņam padoties, tad tie mūžīgi pastāvētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Un Viņš tos barotu ar briedušiem kviešiem, un ar medu no akmens kalna Es tevi pieēdinātu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Asafa dziesma. Dievs stāv Savā draudzē, Viņš tura tiesu starp tiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Cik ilgi jūs gribat netaisni tiesāt un uzlūkot bezdievīgo ļaužu vaigu? (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Izdodiet tiesu nabagam un bāriņam, taisnojiet bēdīgo un nabagu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Izglābiet nabagu un bēdīgo, izraujiet viņu no bezdievīgo rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Bet tie to neatzīst un nesaprot, tie staigā tumsībā; par to zemes pamatiem jāšaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Gan Es esmu sacījis: jūs esat dievi, un visi tā Visuaugstākā bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Bet jūs nomirsiet kā cilvēki un iesiet bojā tāpat kā citi lieli kungi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Celies, ak Dievs, tiesā pasauli, jo Tev būs par mantību visas tautas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Asafa dziesma. Ak Dievs, neciet klusu, neesi kā mēms un nekavējies, ak stiprais Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Jo redzi, Tavi ienaidnieki trako un Tavi nīdētāji paceļ galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Tie ņēmās viltīgus padomus pret Taviem ļaudīm un sarunājās pret tiem, ko Tu glabā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Tie saka tā: nāciet, izdeldēsim tos, ka tie vairs nav tauta, un ka Israēla vārds vairs netop pieminēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Jo no sirds tie kopā ir sarunājušies un derību pret Tevi derējuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Edoma un Ismaēliešu teltis, Moabs un Hagarieši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Ģebals, Amons un Amaleks, Fīlisti ar Tirus iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Arī Asurs stāv viņiem klāt un ir Lata bērniem par elkoni. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Dari tiem kā Midijanam, kā Siseram, kā Jabinam pie Kisones upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Tie ir samaitāti Endorā un palikuši zemei par mēsliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Dari tos un viņu lielos kungus tā kā Orebu un Zebu, un visus viņu virsniekus kā Zebahu un Calmunu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Kas sacīja: ņemsim to jauko Dieva zemi sev par mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Mans Dievs, dari tos par viesuli, par pelavām vēja priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Tā kā uguns mežu sadedzina, un kā liesma kalnus iededzina;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Tāpat dzenies tiem pakaļ ar Savu vētru un iztrūcini tos ar Savām aukām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Pildi viņu vaigus ar kaunu, ka tie, Kungs, meklē Tavu Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Lai tie top kaunā un iztrūcinājās mūžīgi mūžam un kļūst apkaunoti un iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Lai tie atzīst, ka Tu vien ar Savu Vārdu esi Tas Kungs, tas Visuaugstākais pār visu pasauli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Koraha bērnu dziesma uz Ģittit, dziedātāju vadonim. Cik mīlīgas ir Tavas mājvietas, ak Kungs Cebaot!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Mana dvēsele iekārojās un ilgojās ļoti pēc Tā Kunga pagalmiem, mana sirds un mana miesa priecājās iekš tā dzīvā Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Putniņš ir atradis namu un bezdelīga savu ligzdu, kur tā savus bērnus izperē, - pie Taviem altāriem, Kungs Cebaot, mans ķēniņš un mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Svētīgi ir, kas Tavā namā dzīvo, tie Tevi slavē vienmēr. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Svētīgi tie cilvēki, kas savu stiprumu meklē pie Tevis, kam sirdīs stāv Tavi ceļi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Kas caur raudu ieleju staigājot to dara par avoksnainu zemi; un lietus to pušķo ar svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Tie iet no spēka uz spēku, tie parādās Dieva priekšā iekš Ciānas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Kungs, Dievs Cebaot, klausi manu lūgšanu, atgriez ausis, ak Jēkaba Dievs. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Dievs, mūsu priekšturamās bruņas, skaties un uzlūko Sava svaidītā vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Jo viena diena Tavos pagalmos ir labāka nekā tūkstošas citas; man gribās labāki pie Dieva nama sliekšņa stāvēt, nekā mājot bezdievības dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Jo Dievs Tas Kungs ir saule un priekšturamās bruņas; Tas Kungs dod žēlastību un godu, Viņš neatrauj labumu tiem, kas nenoziedzībā staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Kungs Cebaot, svētīgs ir tas cilvēks, kas uz Tevi paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Koraha bērnu dziesma, dziedātāju vadonim. Tu, ak Kungs, Savai zemei lēnīgs bijis un Jēkaba cietumu novērsis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Tu Savu ļaužu noziegumu esi piedevis, visus viņu grēkus apklājis; (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Tu visu Savu dusmību atņēmis, no Savas karstās bardzības atstājies:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Atved mūs atpakaļ, ak Dievs, mūsu Pestītājs, un lai Tava dusmība pret mums mitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Vai tad Tu mūžīgi pret mums gribi dusmoties un Tavu bardzību turēt uz bērnu bērniem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Vai tad Tu negribi mūs atkal atspirdzināt, ka Tavi ļaudis iekš Tevis var priecāties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Parādi mums, Kungs, Tavu žēlastību un dod mums Tavu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Es klausīšu, ko Tas Kungs, tas stiprais Dievs, runā, jo Viņš sola mieru Saviem ļaudīm un Saviem svētiem, lai tie negriežās uz ģeķību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Tiešām, Viņa palīdzība ir tuvu klāt tiem, kas Viņu bīstas, ka mūsu zemē gods mājo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Ka žēlastība un uzticība sastopas, ka taisnība un miers skūpstās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Ka patiesība no zemes izaug un taisnība no debesīm skatās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Un Tas Kungs dos labumu un mūsu zeme dos savus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Taisnība staigās Viņa priekšā un ņemsies Viņa pēdas par ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Dāvida lūgšana. Kungs, atgriez Savas ausis, paklausi mani, jo es esmu bēdīgs un nabags.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Pasargi manu dvēseli, jo es esmu bezvainīgs; palīdz, mans Dievs, Savam kalpam, kas uz Tevi paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Esi man žēlīgs, ak Kungs! jo es saucu uz Tevi cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Iepriecini Sava kalpa dvēseli, jo mana dvēsele, Kungs, nesās uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Jo Tu, Kungs, esi labs, un piedod labprāt no lielas žēlastības visiem, kas Tevi piesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Kungs, klausies uz manu lūgšanu un ņem vērā manas piesaukšanas balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Bēdu laikā es Tevi piesaucu, jo Tu mani paklausi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Neviens starp tiem dieviem nav kā Tu, Kungs, un tā nav nekas kā Tavi darbi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Visas tautas, Kungs, ko Tu esi radījis, nāks un pielūgs Tavā priekšā, un godās Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Jo Tu esi liels un dari brīnumus, Tu esi Dievs, Tu vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Māci man, Kungs, Tavu ceļu, es staigāšu iekš Tavas patiesības; valdi manu sirdi pie tā viena, Tavu vārdu bīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Kungs, mans Dievs, es Tevi slavēšu no visas sirds, un godāšu Tavu vārdu mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Jo Tava žēlastība ir liela pār mani un Tu manu dvēseli esi atpestījis no tās dziļās elles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Ak Dievs, lepni ļaudis ceļas pret mani un varas darītāju bars meklē manu dvēseli un Tevi netur priekš savām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Bet Tu, Dievs Kungs, esi sirds žēlīgs un lēnprātīgs, pacietīgs un no lielas žēlastības un uzticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Atgriezies pie manis un esi man žēlīgs, dod Savu spēku Savam kalpam, un atpestī Savas kalpones dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Dari zīmi pie manis, ka man labi klājās, ka mani nīdētāji to redz un kaunas, ka Tu, Kungs, man palīdzi un mani iepriecini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Koraha bērnu dziesma. Viņas pamati ir likti uz svētiem kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Tas Kungs mīļo Ciānas vārtus pār visiem Jēkaba dzīvokļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Teicamas lietas par tevi top sludinātas, tu Dieva pilsēta. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Es pieskaitīšu Rahabu un Bābeli pie tiem, kas mani pazīst; redzi, Fīlisti un Tirus ar Moru ļaudīm: šis tur ir dzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Un par Ciānu sacīs: šis un tas tur ir dzimis, un tas Visuaugstais pats to stiprina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Tas Kungs skaitīs un rakstīs tās tautas: šis tur ir dzimis. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Un dziedot un dejot sauks: visi mani avoti, (ak Ciāna), ir iekš Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Koraha bērnu dziesma, dziedātāju vadonim, ar stabulēm dziedama. Hemana, Ezraka dēla, pamācība. Kungs, Dievs, mans Pestītājs, es Tevi piesaucu dienām naktīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Lai nāk mana lūgšana Tavā priekšā, atgriez Savu ausi pie manas kliegšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Jo mana dvēsele ir bēdu pilna, un mana dzīvība ir tikusi klāt pie elles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Es topu līdzināts tiem, kas bedrē nogrimst, es esmu kā vīrs, kam spēka nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Pie tiem nomirušiem es esmu piešķirts, tā kā tie nokautie, kas kapā guļ, ko Tu vairs nepiemini, un kas no Tavas rokas ir atšķirti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Tu mani esi licis visdziļākā bedrē, tumsībā un dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Tava bardzība mani spiež, Tu mani apbēdini ar visiem Saviem plūdiem. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Manus draugus Tu esi licis tālu no manis, tiem Tu mani esi darījis par negantību: es esmu kā cietumā un nevaru tikt ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Mana acs īgst no bēdām, ak Kungs. Es Tevi piesaucu ikdienas, es izstiepju savas rokas uz Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Vai tad Tu pie mirušiem darīsi brīnumus? Jeb vai aizmigušie celsies un Tev pateiksies? (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Vai kapā sludinās Tavu žēlastību un Tavu uzticību nāves vietā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Vai Tavus brīnumus tumsībā atzīs un Tavu taisnību tai zemē, kur neko vairs nepiemin?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Bet es Tevi piesaucu, Kungs, un mana lūgšana nāk agri Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Kāpēc Tu atstūmi, Kungs, manu dvēseli un paslēpi Savu vaigu priekš manis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Es esmu bēdīgs un novārdzis no pašas jaunības, es ciešu Tavas briesmas, ka es gandrīz izmistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Tava bardzība iet pār mani, Tavas briesmas mani nospaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Tās mani apņem kā ūdens plūdi cauru dienu, tās visai(pilnīgi) mani apstāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Tu dari, ka draugi un tuvākie paliek tālu nost no manis; mani pazīstamie priekš manis apslēpjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Etana, Ezraka dēla, pamācība. Es dziedāšu no Tā Kunga žēlastības mūžīgi un darīšu zināmu Viņa patiesību ar savu muti līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Jo es saku: “Mūžīga žēlastība uzcelta debesīs; tur Tu piestiprini Savu patiesību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '“Es esmu derību derējis ar Savu izredzēto, Es Dāvidam, Savam kalpam, esmu zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Es apstiprināšu tavu dzimumu mūžīgi un uztaisīšu tavu goda krēslu līdz bērnu bērniem.” (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Par to debesis slavē, ak Kungs, Tavus brīnumus, ir Tavu patiesību tai svētā draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Jo kas ir debesīs Tam Kungam līdzīgs? Kas ir kā Tas Kungs starp Dieva bērniem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Tas stiprais Dievs ir ļoti bijājams to svēto draudzē un bīstams pār visiem, kas ir ap Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Kungs, Dievs Cebaot, kas ir tāds kā Tu, tāds varens, ak Kungs! Un Tava patiesība ir ap Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Tu valdi pār grezno jūru; kad viņas viļņi ceļas, tad Tu tos klusini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Tu satrieci Rahabu kā nokautu, Tu izkaisi Savus ienaidniekus ar Savu vareno elkoni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Tev pieder debesis, arī zeme Tev pieder; zemes virsu un viņas pilnumu Tu esi radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Ziemeli un dienasvidu tu esi radījis; Tābors un Hermons gavilē par Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tev ir spēcīgs elkonis, stipra ir Tava roka un augsta Tava labā roka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Taisnība un tiesa ir Tava valdības krēsla pamati, žēlastība un patiesība iet Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Svētīgi tie ļaudis, kas māk gavilēt; ak Kungs, tie staigā Tava vaiga gaišumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Par Tavu vārdu tie priecājās vienmēr un caur Tavu taisnību tie ir paaugstināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Jo Tu esi viņu stipruma rota, un caur Tavu labprātību Tu mūsu ragu paaugstini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Jo mūsu priekšturamās bruņas ir no Tā Kunga, un no Israēla Svētā ir mūsu ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Citkārt Tu runāji caur parādīšanu Savam svētam un sacīji: Es esmu vienam varenam palīgu sniedzis, Es esmu paaugstinājis vienu izredzētu no tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Es Dāvidu, Savu kalpu, esmu atradis, ar Savu svēto eļļu Es to esmu svaidījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Mana roka būs līdz ar to vienmēr, un Mans elkonis viņu spēcinās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Ienaidnieks viņu nevajās un ļaundaris viņu nespaidīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Bet Es satriekšu viņa pretiniekus viņa priekšā un sadauzīšu viņa ienaidniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Un Mana uzticība un žēlastība būs ar viņu, un viņa rags caur Manu vārdu taps paaugstināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Un Es viņa roku likšu līdz jūrai, un viņa labo roku līdz tām lielupēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Viņš Mani piesauks: Tu esi mans Tēvs, mans Dievs un manas pestīšanas patvērums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Un Es viņu iecelšu par to pirmdzimušo, par to visaugsto starp tiem ķēniņiem virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Savu žēlastību Es viņam turēšu mūžīgi, un Mana derība ar viņu paliks pastāvīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Es viņam došu dzimumu mūžīgi un darīšu viņa goda krēslu kā debesu dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Bet kad viņa bērni Manu bauslību atstās un Manās tiesās nestaigās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Kad tie Manus likumus sagānīs un Manus baušļus neturēs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Tad Es viņu pārkāpumus piemeklēšu ar rīksti un viņu noziegumus ar sitieniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Bet Savu žēlastību Es no viņa neatraušu un Savu patiesību Es neaizliegšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Es Savu derību nesagānīšu un, ko Manas lūpas runājušas, to Es nepārgrozīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Vienu lietu pie Savas svētības Es esmu zvērējis: tiešām, Es Dāvidam nemelošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Viņa dzimums būs mūžīgi, un viņa goda krēsls manā priekšā kā saule.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Viņš būs mūžīgi stiprs kā mēnesis un būs pastāvīgs, kā tas liecinieks padebešos. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Bet nu Tu viņu esi atstūmis un atmetis, Tu esi apskaities pret Savu svaidīto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Tu Sava kalpa derību esi iznīcinājis, viņa kroni Tu esi nometis zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Tu esi salauzis visus viņa mūrus, viņa stiprās pilis Tu esi licis drupās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Visi, kas iet garām, viņu aplaupa; viņš saviem kaimiņiem ir palicis par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Tu paaugstināji viņa spaidītāju labo roku, Tu iepriecināji visus viņa ienaidniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Arī viņa zobena asmeni Tu esi atņēmis un neesi licis viņam pastāvēt karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Tu viņa glītumam licis mitēties un nogāzis zemē viņa goda krēslu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Tu esi paīsinājis viņa jaunības dienas, Tu viņu apsedzis ar kaunu. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Cik ilgi, ak Kungs, Tu gribi pilnīgi apslēpties, un cik ilgi Tava bardzība degs kā uguns?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Piemini, kāds ir mans mūžs, cik nīcīgus Tu visus cilvēku bērnus esi radījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kurš cilvēks dzīvo, kas nāvi neredzēs? Kas savu dvēseli izglābs no kapa varas? (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kungs, kur ir Tava senējā žēlastība, ko Tu Savā uzticībā Dāvidam esi zvērējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Piemini, ak Kungs, Savu kalpu kaunu, ko es savā sirdī nesu, no visām pasaules tautām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Ka Tavi ienaidnieki nievā, ak Kungs, ka tie nievā Tava svaidītā pēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Slavēts lai ir Tas Kungs mūžīgi! Āmen, Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Mozus, Tā Dieva vīra, lūgšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Kungs, Tu mums esi par patvērumu uz radu radiem; pirms kalni radušies un Tu zemi un pasauli biji sataisījis, Tu esi mūžīgi mūžam tas stiprais Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu cilvēkus dari par pīšļiem un saki: griežaties atpakaļ, jūs cilvēku bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Jo tūkstoši gadi Tavā priekšā ir kā tā diena, kas vakar pagājusi, un kā vienas nakts vaktis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Tu tos aizrauj kā plūdos; tie ir kā miegs, tie ir agrumā kā zāle, kas atzeļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Kas rītā zaļo un atzeļ, un vakarā top nopļauta un kalst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Jo caur Tavu dusmību mēs iznīkstam un caur Tavu bardzību mēs topam izbiedēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu lieci mūsu noziegumus Savā priekšā, mūsu apslēptos grēkus priekš Sava vaiga gaišuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Jo visas mūsu dienas aiziet caur Tavu dusmību; mēs pavadām savus gadus kā pasaku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Mūsu dzīvības laiks stāv septiņdesmit gadus, vai, ja kas ļoti stiprs, astoņdesmit gadus, un viņas labums ir grūtums un bēdas; jo tā aiziet ātri un mēs skrienam nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Bet kas atzīst Tavas dusmības stiprumu un Tavu bardzību, Tevi bīdamies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Māci mums mūsu dienas tā skaitīt, ka gudru sirdi dabūjam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Atgriezies, Kungs, atkal pie mums, - cik ilgi tad tas būs? un esi Saviem kalpiem žēlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Paēdini mūs agri ar Savu žēlastību, tad mēs gavilēsim, un priecāsimies visu savu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Iepriecini mūs pēc tām dienām, kur Tu mūs apbēdinājis, pēc tiem gadiem, kur esam redzējuši ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Parādi Saviem kalpiem Savus darbus un Savu godu viņu bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Un Tā Kunga, mūsu Dieva, laipnība lai paliek pār mums! Un pašķir pie mums mūsu roku darbu, mūsu roku darbu, to Tu pašķir!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Kas sēž tā Visuaugstākā patvērumā un mīt tā Visuvarenā ēnā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Tas saka uz To Kungu: mana cerība un mana stipra pils, mans Dievs, uz ko es paļaujos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Jo Viņš tevi glābj no mednieka valgiem, no kaitīgā mēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Viņš tevi sedz Saviem spārniem, un apakš Viņa spārniem tu esi glābts; Viņa patiesība ir par apsegu un par priekšturamām bruņām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Ka tev nav ko bīties no nakts baidekļiem, no bultām, kas dienā skraida,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'No mēra, kas tumsā lien, no sērgas, kas dienas vidū samaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Jebšu tūkstoši krīt tev sānis, un desmit tūkstoši pie tavas labās rokas, taču tevi neaizņems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Tiešām, ar savām acīm tu uzlūkosi un redzēsi, kā bezdievīgiem top atmaksāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Tu, Kungs, esi mans patvērums! To Visuaugstāko tu esi licis par savu stiprumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Ļaunums tev neuzies, un pie tava dzīvokļa mokas nepiestāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Jo Viņš Saviem eņģeļiem par tevi pavēlēs, tevi pasargāt uz visiem taviem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Tie tevi uz rokām nesīs, ka tu savu kāju pie akmens nepiedauzīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Pār lauvām un odzēm tu kāpsi un samīsi jaunos lauvas un pūķus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '„Viņš tveras pie Manis, un Es viņu izglābšu; Es viņu paaugstināšu, jo viņš pazīst Manu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Viņš Mani piesauc, un Es viņu paklausīšu. Es viņam klāt esmu bēdās, Es viņu gribu izraut un viņu pagodināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Ar ilgu dzīvošanu Es viņu gribu paēdināt un viņam parādīt Savu pestīšanu“.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Dziesma svētdienā dziedama. Laba lieta ir, To Kungu slavēt un dziedāt Tavam Vārdam, Tu Visuaugstākais,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Rītos izteikt Tavu žēlastību un naktīs Tavu uzticību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Uz tām desmit stīgām un uz stabulēm, ar spēlēšanu uz koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Jo, Kungs, Tu mani iepriecini ar Saviem darbiem; es gavilēju par to, ko Tava roka dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Ak Kungs, cik lieli ir Tavi darbi, cik ļoti dziļas Tavas domas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Nejēga to neatzīst, un ģeķis to nesaprot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Gan bezdievīgie zaļo kā zāle, un visi ļauna darītāji zeļ; tomēr tie top izdeldēti mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Bet Tu, Kungs, esi tas augstākais mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Jo redzi, Tavi ienaidnieki, ak Kungs, redzi, Tavi ienaidnieki iet bojā, visi ļaundarītāji top izkaisīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Bet Tu paaugstini manu ragu kā vērša ragu; es esmu apliets ar jaunu eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Un manas acis uzlūko ar prieku manus nicinātājus, manas ausis iepriecinājās par tiem, kas ļaunā prātā pret mani ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Taisnais zaļo kā palma koks, viņš aug kā ciedru koks uz Lībanus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Kas Tā Kunga namā ir stādīti, tie zaļo mūsu Dieva pagalmos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Vēl pašā vecumā tie nes augļus, tie ir auglīgi un zaļi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Un stāsta, ka Tas Kungs, mans patvērums, ir taisns, un netaisnības nav pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Tas Kungs ir ķēniņš un ar godību ģērbies, Tas Kungs ir ģērbies un apjozies ar spēku; tādēļ pasaule stāv stipra, ka nešaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Tavs valdības krēsls stāv stiprs no sendienām; Tu esi no mūžības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Upes paceļ, ak Kungs, upes paceļ savu kaukšanu, upes paceļ savu krākšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Pār lielu ūdeņu krākšanu, pār varenām jūras bangām Tas Kungs ir jo varens augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tavas liecības ir visai uzticamas; svētums ir Tava nama jaukums, ak Kungs, mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Kungs, Dievs, Tu atriebējs, ak Tu stiprais Dievs, Tu atriebējs, parādies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Celies, Tu pasaules soģi, atmaksā tiem lepniem pēc viņu nopelna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Cik ilgi tiem bezdievīgiem, Kungs, cik ilgi tiem bezdievīgiem būs priecāties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Pārplūstot tie runā pārgalvīgi, un visi ļaundarītāji greznojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Ak, Kungs, tie samin Tavus ļaudis un nospiež Tavu īpašumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Atraitnes un svešiniekus tie nokauj un nomaitā bāriņus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Un saka: Tas Kungs to neredz, un Jēkaba Dievs to nemana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Ņemiet vērā, jūs bezprātīgie starp tiem ļaudīm, un jūs ģeķi, kad jūs paliksiet gudri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Kas ausi ir dēstījis, vai tas nedzirdēs? Kas aci darījis, vai tas neredzēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Kas tautas pārmāca, vai tas nesodīs? Tas, kas cilvēkiem māca atzīšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Tas Kungs zin cilvēku domas, ka tās ir nelietīgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Svētīgs tas vīrs, ko Tu, Kungs, pārmāci, un kam Tu māci Savu bauslību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'To mierināt bēdu dienās, tiekams bezdievīgam bedri raks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Jo Tas Kungs neatstums Savus ļaudis un nepametīs Savu mantas tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Jo pie taisnības jāgriežas tiesai, un tam piekritīs visi sirdsskaidrie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kas mani aizstāv pret netaisniem? Un kas man stāv klāt pret ļaundarītājiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Ja Tas Kungs nebūtu mans palīgs, tad gan mana dvēsele drīz gulētu klusumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Kad es jau sacītu: kāja man slīd, tad Tava žēlastība, ak Kungs, mani tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Kad man daudz sirdēstu, tad Tava iepriecināšana ielīksmo manu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Vai Tu biedrs būtu tam posta krēslam, kas blēdību izperē taisnības vietā? -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Tie sapulcējās pret taisnā dvēseli un pazudina nenoziedzīgas asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Bet Tas Kungs ir mans patvērums, un mans Dievs mana pils, kur glābjos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Un Viņš tiem atmaksās viņu noziegumu un tos izdeldēs viņu blēdībā. Tas Kungs, mūsu Dievs, tos izdeldēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Nāciet, dziedāsim Tam Kungam priecīgi, gavilēsim savas pestīšanas patvērumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Ejam priekš Viņa vaiga ar pateikšanu, gavilēsim Viņam ar dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Jo Tas Kungs ir tas lielais un stiprais Dievs un tas lielais ķēniņš pār visiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Viņa rokā ir zemes dziļumi, un kalnu augstumi Viņam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Viņam pieder jūra, jo Viņš to radījis, un Viņa rokas sausumu ir cēlušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Nāciet, pielūgsim, klanīsimies un metīsimies ceļos priekš Tā Kunga, sava radītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Jo Viņš ir mūsu Dievs, un mēs esam Viņa ganības ļaudis un Viņa rokas avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Šodien, kad jūs Viņa balsi dzirdiet, tad neapcietinājiet savas sirdis, tā kā Meribā, tā kā Masā tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Kur jūsu tēvi Mani kārdināja, Mani pārbaudīja, lai gan Manus darbus redzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Man četrdesmit gadus raizes ir bijušas ar šo tautu, tā ka Es sacīju: tie ir ļaudis, kam sirds maldās un kas Manus ceļus nepazīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Tādēļ Es Savā dusmībā esmu zvērējis: tiešām, tiem nebūs nākt pie Manas dusas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Dziediet Tam Kungam jaunu dziesmu, dziediet Tam Kungam visa pasaule;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Dziediet Tam Kungam, teiciet Viņa Vārdu, sludinājiet dienu no dienas Viņa pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Izteiciet pagānu starpā Viņa godu, visu tautu starpā Viņa brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Jo Tas Kungs ir liels un ļoti teicams, Viņš ir bijājams pār visiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Jo visi tautu dievi ir elki, bet Tas Kungs ir radījis debesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Augstība un godība ir Viņa priekšā, spēks un glītums Viņa svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Dodiet Tam Kungam, jūs ļaužu tautas, dodiet Tam Kungam godu un spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Dodiet Tam Kungam Viņa vārda godu, nesiet dāvanas un nāciet Viņa pagalmos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Pielūdziet To Kungu svētā glītumā, priekš Viņa vaiga lai dreb visa pasaule.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Sakait starp tautām: Tas Kungs ir ķēniņš: tādēļ pasaule stāv stipra, ka nešaubās; Viņš tiesās tos ļaudis ar taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Priecājies, debess, un līksmojies, zeme, jūra lai krāc un viss, kas tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Lauks lai priecājās ar visu, kas tur stāv, visi meža koki lai gavilē');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Priekš Tā Kunga vaiga, jo Viņš nāk, jo Viņš nāk pasauli tiesāt. Zemes virsu Viņš tiesās ar taisnību un tos ļaudis ar Savu patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Tas Kungs ir ķēniņš, - lai priecājās zeme, un salas lai līksmojās lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Padebesis un krēslība ir ap Viņu, taisnība un tiesa ir Viņa godības krēsla stiprums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Uguns iet Viņa priekšā un iededzina visapkārt Viņa pretiniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Viņa zibeņi apgaismo pasauli; zemes virsas to redz un dreb.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Kalni izkūst kā vaski Tā Kunga priekšā, tā visas pasaules Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Debesis izstāsta Viņa taisnību, un visi ļaudis redz Viņa godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Kaunā top visi, kas bildēm kalpo un lielās ar elkiem; pielūdziet Viņu, visi dievi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Ciāna klausās un priecājās, Jūda meitas līksmojās, Kungs, kad Tu tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Jo Tu, Kungs, esi tas Visuaugstākais pār visu pasauli, ļoti paaugstināts pār visiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Ienīstiet ļaunu, jūs, kas To Kungu mīļojiet; Viņš pasargā Savu svēto dvēseles, no bezdievīgo rokas Viņš tos izglābs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Taisnam aust gaišums, un prieks sirdsskaidriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Priecājaties iekš Tā Kunga, jūs taisnie, un teiciet Viņa svēto vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Dziesma. Dziediet Tam Kungam jaunu dziesmu, jo Viņš dara brīnumus; Viņš palīdz ar Savu labo roku un ar Savu svēto elkoni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Tas Kungs ir zināmu darījis Savu pestīšanu, tautu priekšā Viņš parādījis Savu taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Viņš pieminējis Savu žēlastību un Savu uzticību Israēla namam, un visi zemes gali redz mūsu Dieva pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Gavilējiet Tam Kungam, visa zeme, skandinājiet priecīgi, līksmojaties priecīgi un dziediet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Dziediet Tam Kungam ar koklēm, ar koklēm un dziesmas skaņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Ar trumetēm un ar bazūņu skaņu, gavilējiet tā ķēniņa, Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Lai jūra krāc un kas iekš tās ir, zemes virsas un kas tur dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Lai upes plaukšķina, un kalni lai kopā līksmojās');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Tā Kunga priekšā, jo Viņš nāk zemi tiesāt; Viņš tiesās pasauli ar taisnību un tos ļaudis ar tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Tas Kungs ir ķēniņš, - tautas dreb; Viņš sēž pār ķerubiem, - zeme trīc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Tas Kungs ir liels iekš Ciānas, un Viņš ir augsts pār visiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Tavu lielo un bijājamo Vārdu lai teic, jo Tas ir svēts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Ar taisnību Tu esi nodibinājis ķēniņa stiprumu, kas tiesu mīļo; Tu esi iecēlis tiesu un taisnību iekš Jēkaba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Paaugstinājiet To Kungu, mūsu Dievu, un pielūdziet Viņa kāju pamesla priekšā; Viņš ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mozus un Ārons starp Viņa priesteriem, un Samuēls starp tiem, kas piesauc Viņa Vārdu; tie piesauca To Kungu, un Viņš tos paklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Viņš runāja uz tiem padebeša-stabā; tie turēja Viņa liecības un tos likumus, ko Viņš tiem bija devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Kungs, mūsu Dievs, Tu tos paklausīji, Tu stiprais Dievs tiem piedevi un biji atriebējs par viņu darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Paaugstinājiet To Kungu, mūsu Dievu, un pielūdziet Viņa svētā kalnā, jo Tas Kungs, mūsu Dievs, ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Pateicības dziesma. Gavilējiet Tam Kungam, visa pasaule.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Kalpojiet Tam Kungam ar prieku, nāciet priekš Viņa vaiga ar gavilēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Atzīstiet, ka Tas Kungs ir Dievs; Viņš mūs ir darījis, un ne mēs paši, par Saviem ļaudīm un par Savas ganības avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Ieejat pa Viņa vārtiem ar pateikšanu, Viņa pagalmos ar teikšanu; pateiciet Viņam, slavējiet Viņa Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Jo Tas Kungs ir labs; Viņa žēlastība paliek mūžīgi, un Viņa patiesība līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Dāvida dziesma. No žēlastības un tiesas es gribu dziedāt, - Tev, Kungs, es dziedāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Es likšu vērā nenoziedzības ceļu, - kad Tu nāksi pie manis? - Es staigāšu ar skaidru sirdi savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Uz ļaunām lietām es nelūkošu, grēka darbu es ienīstu, ka tas nebūs pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Nikna sirds lai ir tālu no manis, ļauna es negribu zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Kas savu tuvāko slepeni aprunā, to es izdeldēšu, kam lepnas acis un grezna sirds, to es necietīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Manas acis raugās uz tiem uzticīgiem iekš zemes, ka tie paliek pie manis; kas taisnu ceļu staigā, tas man kalpos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Kas blēdību dara, tas nepaliks manā namā; kas melus runā, nepastāvēs priekš manām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Ik rītus es nomaitāšu visus bezdievīgos iekš zemes, ka es izdeldu visus ļaundarītājus no Tā Kunga pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Bēdu cilvēka lūgšana, kad tas ir noskumis un savas žēlabas izgāž Tā Kunga priekšā. Ak Kungs, klausi manu lūgšanu, un mana saukšana lai nāk pie Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Neapslēp Savu vaigu priekš manis, atgriez Savu ausi pie manis bēdu laikā; tai dienā, kad es saucu, paklausi mani drīz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Jo manas dienas ir iznīkušas kā dūmi, un mani kauli ir izdeguši kā pagale.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Mana sirds ir sasista un izkaltusi kā zāle, tā ka es aizmirstu pat savu maizi ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mani kauli līp pie manas miesas no kaukšanas un nopūšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Es esmu tā kā dumpis tuksnesī, es esmu kā apogs (pūce) izpostītās vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Es esmu nomodā un tāpat kā vientulis putns uz jumta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Mani ienaidnieki mani nievā cauru dienu; kas pret mani trako, tie mani dara par lāsta vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Jo es ēdu pelnus kā maizi un sajaucu savu dzērienu ar asarām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Tavas bardzības un dusmības pēc, jo Tu mani esi pacēlis un atkal nogāzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Manas dienas ir kā ēna pavakarē, un es kalstu kā zāle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Bet Tu, Kungs, paliec mūžīgi un Tava piemiņa līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Kaut Tu celtos un apžēlotos par Ciānu, jo jau ir laiks par viņu apžēloties, jo tas nospriestais laiks ir atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Jo Tavi kalpi mīļo viņas akmeņus un žēlojās, ka tā guļ pīšļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Tad pagāni bīsies Tā Kunga Vārdu, un visi ķēniņi virs zemes Tavu godību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Kad Tas Kungs Ciānu uztaisīs un parādīsies Savā godībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Viņš griežas pie bēdu ļaužu lūgšanas un nenicina pielūgšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Lai tas top uzrakstīts pēcnākamiem, un tie ļaudis, kas vēl taps radīti, slavēs To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Jo Viņš skatās no Sava svēta augstuma, Tas Kungs lūko no debesīm uz zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Ka Viņš dzird cietumnieku nopūšanos un atsvabina nāves bērnus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Ka Tā Kunga vārds top sludināts Ciānā un Viņa slava Jeruzālemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Kad tautas sapulcējās kopā un valstis, Tam Kungam kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Bet Viņš ir pazemojis ceļā manu spēku un paīsinājis manas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Es saku: mans Dievs, neņem mani nost pusmūžā. Tavi gadi paliek līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Senlaikus Tu esi nodibinājis zemi, un debesis ir Tavu roku darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Tās zudīs, bet Tu pastāvēsi; tās sadils visas, kā drēbes; Tu tās pārvērtīsi kā drānas, un tās pārvērtīsies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Bet Tu palieci tas pats, un Tavi gadi nebeigsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Tavu kalpu bērni paliks, un viņu dzimums būs pastāvīgs Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Dāvida dziesma. Teici To Kungu, mana dvēsele, un viss, kas iekš manis, Viņa svēto vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Teici To Kungu, mana dvēsele, un neaizmirsti, ko Viņš tev laba darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Viņš piedod visus tavus grēkus un dziedina visas tavas vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Viņš izglābj tavu dzīvību no samaitāšanas un pušķo tevi ar žēlastību un apžēlošanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Viņš pieēdina tavu muti ar labumu, ka tu atjaunojies kā ērglis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Tas Kungs izdod taisnību un tiesu visiem, kas top apbēdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Viņš Mozum darījis zināmus Savus ceļus, Israēla bērniem Savus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Žēlīgs un lēnīgs ir Tas Kungs, pacietīgs un no lielas žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Viņš ķildu neturēs mūžam un nedusmosies mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Viņš mums nedara pēc mūsu grēkiem un mums nemaksā pēc mūsu noziegumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Jo cik augstas debesis ir pār zemi, tik spēcīga Viņa žēlastība pār tiem, kas Viņu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Cik tālu rīti no vakariem, tik tālu Viņš liek mūsu pārkāpumus nost no mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Tā kā tēvs apžēlojās par bērniem, tā Tas Kungs žēlo tos, kas Viņu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Jo Viņš zin, kāds radījums mēs esam, Viņš piemin, ka mēs esam pīšļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Cilvēks savā dzīvībā ir kā zāle, viņš zied kā puķe laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Kad vējš pār to pāriet, tad viņas vairs nav, un viņas vietu vairs nepazīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Bet Tā Kunga žēlastība paliek mūžīgi mūžam pār tiem, kas Viņu bīstas, un Viņa taisnība līdz bērnu bērniem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Pie tiem, kas Viņa derību tur un Viņa baušļus piemin, ka tie tos dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Tas Kungs ir stiprinājis Savu godības krēslu debesīs, un Viņa valstība valda pār visu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Teiciet To Kungu, Viņa eņģeļi, jūs stiprie karotāji, kas Viņa vārdu izdara, klausīdami Viņa vārda balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Teiciet To Kungu, visi Viņa spēcīgie pulki, jūs Viņa sulaiņi, kas dara pēc Viņa prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Teiciet To Kungu, visi Viņa darbi visās vietās, kur Viņš valda. Teici To Kungu, mana dvēsele.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Teici To Kungu, mana dvēsele! Kungs, mans Dievs, Tu esi ļoti liels, ar augstību un godību aptērpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Tu ģērbies gaišumā kā apģērbā; tu izklāj debesis kā telti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Tu ūdeņus augstībā sev lieci par grīdu, tu dari padebešus par saviem ratiem, tu staigā uz vēja spārniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Tu dari vējus par Saviem eņģeļiem un uguns liesmas par Saviem sulaiņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Zemi Tu esi dibinājis uz viņas pamatiem, ka tā nešaubās ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Ar jūras dziļumiem Tu to apsedzis kā ar apģērbu, ūdeņi stāvēja pār kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'No Taviem draudiem tie bēga, no Tava pērkona tie steidzās projām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Kalni cēlās un lejas nogrima tai vietā, ko Tu tām biji licis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Tu esi licis robežas, tās tie (ūdeņi) nepārkāps un zemi vairs neapklās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Tu izvadi avotus pa ielejām, ka tie tek starp kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Tie dzirdina visus lauka zvērus, tur atdzeras meža ēzeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Pie tiem mīt debesputni, zaros tie dzied.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Tu slapini kalnus no augšienes; ar augļiem, ko Tu radi, zeme top piepildīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Tu liec zālei augt priekš lopiem un sējai cilvēkam par labu, lai nāk maize no zemes');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Un vīns, kas iepriecina cilvēka sirdi, ka viņa vaigs top skaistāks nekā no eļļas, un ka maize spēcina cilvēka sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Tā Kunga koki top papilnam slacināti, ciedra koki uz Lībanus, ko Viņš ir dēstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Tur putni dara ligzdas un stārķi dzīvo uz priedēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Augstie kalni ir priekš mežu kazām, klintis kalna āpšiem par patvērumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Tu esi darījis mēnesi laikmetiem, saule zin savu noiešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Tu dari tumsu, ka nakts metās; tad kustās visi meža zvēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Jaunie lauvas rūc pēc laupījuma, meklēdami savu barību no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Un kad saule lec, tad tie atkal aizbēg un apguļas savās alās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Tad cilvēks iziet pie sava darba, pie sava lauka darba līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Cik lieli ir Tavi darbi, ak Kungs! Tos visus Tu esi darījis ar gudrību, - zeme ir Tava padoma pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Redzi, jūra, liela un plata uz abējām pusēm! Tur mudžēt mudž neskaitāmā pulkā visādi zvēri, lieli, mazi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Tur iet lielas laivas un Levijatans, ko Tu esi radījis, tur dzīvoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Tie visi uz Tevi gaida, ka Tu tiem barību dodi savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Kad Tu tiem dod, tad tie salasa; kad Tu Savu roku atveri, tad tie ar labumu top pieēdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Tu apslēpi Savu vaigu, tad tie iztrūkstas; Tu atņem viņiem dvašu, tad tie mirst un paliek atkal par pīšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Tu sūti Savu Garu, tad tie top radīti, un Tu atjauno zemes ģīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Tā Kunga godība paliek mūžīgi; Tas Kungs priecājās par Saviem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Viņš uzlūko zemi, tad tā dreb; Viņš aizskar kalnus, tad tie kūp.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Es dziedāšu Tam Kungam, kamēr es dzīvoju; es slavēšu savu Dievu ar dziesmām, kamēr šeit esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Manas domas Viņam lai patīk; es priecāšos iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Grēcinieki no zemes lai izzūd un bezdievīgo lai vairs nav. Teici To Kungu, mana dvēsele, Alleluja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Pateiciet Tam Kungam, piesauciet Viņa Vārdu, dariet zināmus starp tiem ļaudīm Viņa darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Dziediet Viņam, slavējiet Viņu ar dziesmām, pārdomājiet visus Viņa brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Slavējiet Viņa svēto vārdu; lai tās sirdis priecājās, kas To Kungu meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Vaicājiet pēc Tā Kunga un pēc Viņa spēka, meklējiet vienmēr Viņa vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Pieminiet Viņa brīnumus, ko Viņš ir darījis, Viņa brīnuma darbus un Viņa mutes tiesas, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Tu Ābrahāma, Viņa kalpa dzimums, jūs Jēkaba bērni, Dieva izredzētie!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Viņš ir Tas Kungs, mūsu Dievs; Viņa tiesas iet pār visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Viņš piemin Savu derību mūžam, to vārdu, ko Viņš ir iecēlis tūkstošiem dzimumiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Ko Viņš ar Ābrahāmu derējis un ko zvērējis Īzakam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'To Viņš arī Jēkabam ir iecēlis par likumu, Israēlim par mūžīgu derību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Sacīdams: tev Es došu Kanaāna zemi, jūsu mantības daļu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Kad tie vēl bija mazs pulciņš, ne daudz, un svešinieki iekš tās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Un staigāja no vienas tautas pie otras, no vienas valsts pie otras valsts ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Viņš nevienam neļāva tos apbēdināt, Viņš arī ķēniņus sodīja viņu dēļ:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Neaizskariet Manus svaidītos un nedariet ļauna Maniem praviešiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Viņš aicināja badu pār zemi, Viņš atņēma visu maizes padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Viņš sūtīja viņu priekšā vienu vīru; Jāzeps tapa pārdots par kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Viņa kājas tapa spaidītas siekstā, viņa miesas nāca dzelzīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Tiekams viņa vārds notika, un Tā Kunga sludinājums to pārbaudīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Tas ķēniņš sūtīja un lika to atraisīt, tas ļaužu valdītājs to atlaida vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Viņš to iecēla par kungu savam namam un par valdnieku visai savai mantai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Ka tas saistītu viņa lielkungus pēc sava prāta un mācītu gudrību viņa vecākajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Tā Israēls nāca Ēģiptes zemē un Jēkabs piemita Hama zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Un Viņš Saviem ļaudīm lika augumā augt un tos darīja jo varenus nekā viņu pretiniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Viņš pārvērsa viņu sirdi, ienīdēt Viņa ļaudis un ar viltu glūnēt uz Viņa kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Viņš sūtīja Mozu, Savu kalpu, un Āronu, ko Viņš bija izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Tie darīja viņu starpā Dieva brīnumus un brīnuma zīmes Hama zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Viņš sūtīja tumsu, tad kļuva tumšs; un tie Viņa Vārdam neturējās pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Viņš pārvērsa viņu ūdeņus par asinīm un nokāva viņu zivis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Viņu zeme mudžēja no vardēm viņu ķēniņu kambaros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Viņš runāja, tad nāca kukaiņi, utis visās viņu robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Viņš tiem deva krusu lietus vietā, uguns liesmas viņu zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Un sasita viņu vīna kokus un viņu vīģes kokus un salauzīja kokus viņu robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Viņš runāja, tad nāca siseņi un vaboles neizskaitāmā pulkā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Kas apēda visu zāli viņu zemē, un norija viņu zemes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Viņš kāva arī visus pirmdzimtos viņu zemē un visu viņu pirmo stiprumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Un tos izveda ar sudrabu un zeltu, un neviena gurdena nebija viņu ciltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Ēģiptes zeme priecājās, kad tie izgāja, jo viņu bailes uz tiem bija kritušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Viņš deva padebesi par apsegu, un uguni naktī par gaismu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Tie lūdza un viņš lika nākt paipalām un tos ēdināja ar debes\'maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Viņš pāršķēla klinti, tad ūdens iztecēja, un upes skrēja tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Jo Viņš pieminēja Savu svēto vārdu un Ābrahāmu, Savu kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Tā Viņš izveda Savus ļaudis ar prieku un Savus izredzētos ar gavilēšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Un tiem deva pagānu zemes; tie iemantoja tautu sviedrus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Lai turētu Viņa likumus un sargātu Viņa bauslību. Alleluja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Alleluja! Pateiciet Tam Kungam, jo Viņš ir labs, un Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kas var izteikt Tā Kunga varenos darbus un izstāstīt visu Viņa teicamo slavu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Svētīgi tie, kas tiesu tur un dara taisnību vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Piemini mani, ak Kungs, pēc Sava labā prāta uz Saviem ļaudīm, piemeklē mani ar Savu pestīšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Ka redzam labumu pie Taviem izredzētiem un priecājamies par Tavu ļaužu prieku un lielāmies ar Tavu īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Mēs esam grēkojuši līdz ar saviem tēviem, esam noziegušies un bijuši bezdievīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Mūsu tēvi Ēģiptē nelika vērā Tavus brīnumus, tie nepieminēja Tavu lielo žēlastību, bet bija pārgalvīgi jūrmalā pie niedru jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Viņš tiem palīdzēja Sava vārda dēļ, ka tiem parādītu Savu varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Un Viņš rāja niedru jūru, ka tā sasīka, un Viņš vadīja caur dziļumiem kā pa tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Un Viņš tos atpestīja no ienaidnieku rokas un tos atsvabināja no nīdētāju rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Ūdeņi apsedza viņu pretiniekus, ka neviens no tiem neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Tad tie ticēja Viņa vārdiem, tie dziedāja Viņa slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Bet steigšus tie aizmirsa Viņa darbus, tie nenogaidīja Viņa nodomu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Bet kārot iekārojās tuksnesī un kārdināja Dievu tai posta vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Tad Viņš tiem deva pēc viņu kārības, bet darīja viņu dvēseles nīkstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Un tie apskauda Mozu lēģerī un Āronu, Tā Kunga svēto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Zeme atvērās un aprija Datanu un apklāja Abirama biedrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Un uguns iedegās viņu pulkā, liesma sadedzināja tos bezdievīgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Tie taisīja teļu Horebā un klanījās tās bildes priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Un pārvērsa savu godu par vērša ģīmi, kas ēd zāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Viņi aizmirsa Dievu, savu Pestītāju, kas lielas lietas bija darījis Ēģiptes zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Brīnumus Hama zemē, briesmīgus darbus pie niedru jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Tā ka Viņš nodomāja tos izdeldēt, ja Mozus, Viņa izredzētais, nebūtu stājies tai plaisumā Viņa priekšā, novērst Viņa bardzību, lai nesamaitātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Tie necienīja to jauko zemi, tie neticēja Viņa Vārdam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Bet kurnēja savās teltīs un nepaklausīja Tā Kunga balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Tāpēc Viņš pacēla pret tiem Savu roku, tos nosist tuksnesī');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Un nogāzt viņu dzimumu starp pagāniem un tos izkaisīt pa tām zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Tie pieķērās arī BaālPeoram un ēda mirušu upurus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Un apkaitināja To Kungu ar saviem darbiem, ka mocība starp viņiem ielauzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Tad Pinehas cēlās un sodīja, un tā mocība mitējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Un tas viņam tapa pielīdzināts par taisnību uz bērnu bērniem mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Un tie Viņu apkaitināja pie bāršanās ūdens, ka Mozum viņu dēļ ļaunums uzgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Jo tie padarīja viņa sirdi rūgtu, ka viņš neapdomīgi runāja ar savām lūpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Tie arī neizdeldēja tās tautas, kā Tas Kungs tiem bija pavēlējis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Bet tie sajaucās ar pagāniem un mācījās viņu darbus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Un kalpoja viņu elkiem, un tie viņiem palika par valgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Pat savus dēlus un savas meitas tie upurēja nešķīstiem gariem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Un izlēja nenoziedzīgas asinis, savu dēlu un savu meitu asinis, ko tie upurēja Kanaāna elkiem, tā ka zeme tapa apgānīta caur asins vainām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Un tie sagānījās ar saviem darbiem un maukoja ar savām darīšanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Par to Tas Kungs ļoti iedusmojās pret Saviem ļaudīm un turēja par negantību Savu īpašumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Un Viņš tos nodeva pagānu rokā, un viņu nīdētāji par tiem valdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Un viņu ienaidnieki tos apbēdināja un tos pazemoja apakš savas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Viņš tos izglāba daudzkārt, taču tie Viņu apkaitināja ar savu padomu un iznīka savu noziegumu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Bet Viņš uzlūkoja viņu bēdas un dzirdēja viņu kliegšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Un pieminēja viņu labad Savu derību, un Viņam bija žēl pēc Savas lielās žēlastības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Un lika tiem atrast sirds žēlastību pie visiem, kas tos turēja cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Atpestī mūs, Kungs, mūsu Dievs, un sapulcini mūs no tiem pagāniem, ka mēs pateicamies Tavam svētam vārdam un lielāmies ar Tavu slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Slavēts lai ir Tas Kungs, Israēla Dievs, mūžīgi mūžam, un visi ļaudis lai saka: Āmen! Alleluja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Pateiciet Tam Kungam, jo Viņš ir labs, un Viņa žēlastība paliek mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Lai tā saka tie, ko Tas Kungs ir atpestījis, ko Viņš izglābis no spaidītāju rokas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Un sapulcinājis no tām zemēm, no rītiem un vakariem, no ziemeļiem un no jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Tie, kas tuksnesī maldījās pa nestaigātiem ceļiem un neatrada pilsētu, kur varēja dzīvot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Izsalkuši un izslāpuši, ka viņa dvēsele nogura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Tad tie To Kungu piesauca savās bēdās, un Viņš tos izglāba no viņu bailēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Un Viņš tos vadīja pa taisnu ceļu, ka tie gāja uz to pilētu, kur varēja dzīvot:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Tiem būs Tam Kungam pateikties par Viņa žēlastību un par Viņa brīnumiem pie cilvēku bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Ka Viņš paēdinājis iztvīkušo un ar labumu piepildījis izsalkušo. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Tie, kas tumsībā sēdēja un nāves ēnā, saistīti bēdās un dzelzīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Tāpēc ka tie bija pretī turējušies Dieva baušļiem un nicinājuši tā Visuaugstākā padomu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Tādēļ viņu sirds tapa apbēdināta ar grūtumu, un tie pakrita un palīga nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Tad tie To Kungu piesauca savās bēdās, un Viņš tos izglāba no viņu bailēm');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Un tos izveda no tumsības un nāves ēnas un saraustīja viņu saites:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Tiem būs Tam Kungam pateikties par Viņa žēlastību un par Viņa brīnumiem pie cilvēku bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Ka Viņš salauž vara durvis un sadauza dzelzs bultas. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Tie ģeķi, kas tapa mocīti savu grēku ceļu un savu noziegumu dēļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Tā ka viņu dvēselei riebās visa barība, un ka tie nogrima līdz pat nāves vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Tad tie To Kungu piesauca savās bēdās, un Viņš tos izglāba no viņu bailēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Viņš sūtīja Savu vārdu un tos dziedināja un tos izrāva no viņu bedrēm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Tiem būs Tam Kungam pateikties par Viņa žēlastību un par Viņa brīnumiem pie cilvēku bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Un pateikšanas upurus upurēt un Viņa darbus izteikt ar prieku. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Tie, kas ar lielām laivām pa jūru līgojās un strādāja savu darbu uz lieliem ūdeņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Kas Tā Kunga darbu redzējuši un Viņa brīnumus jūras dziļumos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Kad Viņš runāja un pacēla vētru, kas viļņus paaugstināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Un tie tā kā uz debesīm kāpa un atkal nogrima dziļumos, ka viņu dvēsele no bailības izkusa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Un tapa mētāti un zvalstījās, kā piedzēruši un visa viņu gudrība iznīka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Tad tie To Kungu piesauca savās bēdās, un Viņš tos izglāba no viņu bailēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Viņš klusināja vētru, tā ka viļņi norima;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Un tie priecājās, ka norima, un Viņš tos veda uz ostu, kurp tiem gribējās:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Tiem būs Tam Kungam pateikties par Viņa žēlastību un par Viņa brīnumiem pie cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Un Viņu paaugstināt ļaužu draudzē un Viņu slavēt vecaju vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Viņš upes padara par tuksnesi un ūdens avotus par izkaltušām vietām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Un auglīgu zemi Viņš padara par neauglīgu viņas iedzīvotāju blēdības dēļ;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Un tuksnesi viņš atkal padara ūdeņainu un sauso zemi avoksnainu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Un liek tur dzīvot tiem izsalkušiem, ka tie var uzcelt pilsētu, kur mājot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Un apsēt tīrumus un dēstīt vīna dārzus, kas nes bagātus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Un Viņš tos svētī, ka tie ļoti vairojās, un viņu lopi nenonīkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Un viņi bija mazumā gājuši un panīkuši caur nelaimes varu un bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Viņš izgāž nievāšanu uz lieliem kungiem un liek tiem aloties tuksnesī, kur ceļa nav;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Bet paaugstina bēdīgo no viņa bēdām un vairo viņa dzimumu kā avju pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'To sirdsskaidrie redz un priecājās, un visai blēdībai jātur mute.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kas gudrs, lai to ņem vērā un lai atzīst Tā Kunga žēlastības darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Dāvida dziesma. Ak Dievs, mana sirds ir droša, es dziedāšu un slavēšu ar dziesmām, mans gods arīdzan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Mostaties, stabules un kokles, ar ausekli es modīšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Es Tev pateikšos, Kungs, starp ļaudīm, es Tev dziedāšu starp tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Jo Tava žēlastība ir liela līdz pat debesīm un Tava patiesība līdz augstiem padebešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Paaugstinājies, Dievs, pār debesīm un Savu godību pār visu pasauli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Lai Tavi mīļie top atsvabināti; atpestī caur Savu labo roku un paklausi mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Dievs runā Tavā svētā vietā: “Par to Es priecājos. Es dalīšu Šehemi un mērošu Sukota leju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gileāds Man pieder, ir Manasus Man pieder, Efraīms ir Manas galvas stiprums, Jūda ir Mans valdības zizlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moābs ir Mans mazgājamais trauks, Savu kurpi Es metu pār Edomu, par Fīlistu zemi Es gavilēju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kas mani vadīs tai stiprā pilsētā? Kas man pavadīs līdz Edomam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Vai ne Tu, Dievs, kas mūs biji atmetis un neizgāji, ak Dievs, ar mūsu karaspēku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Dod mums palīgu bēdu laikā, jo cilvēku pestīšana nav nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Ar Dievu mēs darīsim stiprus darbus; Viņš saspārdīs mūsu spaidītājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Dāvida dziesma, dziedātāju vadonim. Ak Dievs, ko es slavēju, nestāv klusu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Jo bezdievīgu muti un viltīgu muti tie pret mani ir atvēruši, tie runā uz mani ar melu mēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Ar naidīgiem vārdiem tie metās ap mani un karo pret mani bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Par to, ka es tos mīlēju, tie turas man pretī; bet es lūdzu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Tie man maksā ļaunu par labu un ienaidību par mīlestību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Cel pār to vienu bezdievi, un viens pretinieks lai viņam stāv pa labo roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Kad viņš top tiesāts, tad lai top pazudināts, un viņa Dieva lūgšana lai viņam top par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Lai viņa dienas iet mazumā, un viņa amatu cits lai dabū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Viņa bērni lai paliek par bāriņiem un viņa sieva par atraitni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Lai viņa bērni skraida apkārt un ubago un maizes meklē tālu no savām izpostītām māju vietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Lai tas parādu dzinējs izplēš visu, kas tam pieder, un sveši lai aplaupa viņa peļņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Lai tam nav, kas parāda žēlastību, un lai nav, kas žēlo viņa bāriņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Lai viņa pēcnākamie top izdeldēti; viņu vārds lai izzūd otrā augumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Viņa tēvu noziegums lai top pieminēts Tā Kunga priekšā, un viņa mātes grēki lai neizzūd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Lai tie vienmēr paliek Tā Kunga priekšā, un viņa piemiņa lai no zemes top izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Tādēļ ka viņš nebūt nepieminēja žēlastību darīt, bet vajāja bēdīgo un nabagu un to, kam bija noskumusi sirds, ka viņš to nokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Tāpēc ka viņš lāstu gribēja, tas viņam nāks; un svētības viņam negribējās, tad tā arī paliks tālu no viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Un viņš aptērpās ar lāstu, tā kā ar drēbēm, un tas nāca viņa iekšās kā ūdens un kā eļļa viņa kaulos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Tad lai tas viņam ir kā apģērbs, ar ko tas apsedzās, un josta, ar ko tas allaž apjožas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Šī alga lai notiek no Tā Kunga maniem pretiniekiem un tiem, kas ļaunu runā pret manu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Bet Tu, ak Kungs, dari ar mani Sava vārda pēc, jo Tava žēlastība ir laba; izglāb mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Jo es esmu bēdīgs un nabags, un mana sirds iekš manis ir ievainota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Es aizeju kā ēna pavakarē, un topu vajāts kā sisenis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Mani ceļi šļūk no gavēšanas, un mana miesa izdilusi, ka treknuma vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Un es tiem esmu par apsmieklu; kad tie mani redz, tad tie krata galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Palīdz man, Kungs, mans Dievs, atpestī mani pēc Savas žēlastības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Tad tie atzīs, ka tā Tava roka, ka Tu, Kungs, to darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Kad tie lād, tad Tu svētī; kad tie ceļas, tad lai top kaunā; bet Tavs kalps lai priecājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Mani pretinieki lai ar kaunu top apģērbti un ar savu negodu apsegti kā ar svārkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Es Tam Kungam no sirds pateikšu ar savu muti un Tam dziedāšu lielā draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Jo tam bēdīgam Viņš stāv pa labo roku, to atpestīdams no tiem, kas viņa dvēseli notiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Dāvida dziesma. Tas Kungs sacījis uz manu Kungu: “Sēdies pa Manu labo roku, tiekams Es Tavus ienaidniekus lieku par pameslu Tavām kājām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Tas Kungs sūtīs Tava stipruma scepteri no Ciānas; valdi Savu ienaidnieku vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Tavā kara dienā Tavi ļaudis labprātīgi parādās svētā glītumā; Tavi jaunekļi Tev nāk kā rasa no ausekļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Tas Kungs ir zvērējis un Tam nebūs žēl: “Tu esi priesteris mūžīgi pēc Melhizedeka kārtas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Tas Kungs pie Tavas labās rokas satrieks ķēniņus Savas dusmības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Viņš turēs tiesu pagānu starpā; Viņš piepildīs zemi ar miroņiem. Viņš satrieks to, kas ir galva pār lielu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Viņš dzers no upes uz ceļa, tādēļ Viņš pacels galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Alleluja! Es pateicos Tam Kungam no visas sirds to taisno vidū un draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Tā Kunga darbi ir lieli; tie top meklēti no visiem, kam pie tiem labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Viņa darbi ir slava un godība, un Viņa taisnība pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Viņš saviem brīnumiem ir cēlis piemiņu, tas žēlīgais un sirds žēlīgais Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Viņš dod barību tiem, kas Viņu bīstas, un Savu derību Viņš piemin mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Viņš Saviem ļaudīm dara zināmus Savus spēcīgos darbus, ka Viņš tiem dod pagānu mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Viņa roku darbi ir patiesība un tiesa; visi Viņa baušļi ir uzticami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Tie ir stipri mūžīgi mūžam un notiek patiesi un taisni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Viņš sūta pestīšanu Saviem ļaudīm, Viņš pavēl, ka Viņa derībai būs stāvēt mūžīgi; svēts un bijājams ir Viņa Vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Tā Kunga bijāšana ir gudrības iesākums; tam ir laba saprašana, kas to (baušļus) dara; viņa gods pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Alleluja! Svētīgs ir tas vīrs, kas To Kungu bīstas, kam pie Viņa baušļiem labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Tā dzimums būs varens virs zemes; taisno cilts taps svētīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Padoms un bagātība ir viņa namā, un viņa taisnība pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Taisniem tumsībā aust gaišums; jo Viņš ir žēlīgs, sirds žēlīgs un taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Labi tam cilvēkam, kas apžēlojās un aizdod, tiesā tas savu lietu vedīs galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Jo tas nešaubīsies ne mūžam; taisnais paliks mūžīgā piemiņā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'No ļaunas slavas tas nebīstas viņa sirds ir stipra un paļaujas uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Viņa sirds ir droša un nebīstas; tiekams ar prieku skatās uz saviem pretiniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Viņš izdala un dod nabagiem; viņa taisnība paliek mūžīgi, viņa rags top paaugstināts ar godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Bezdievīgais to redzēs un apskaitīsies, viņš sakodīs savus zobus un iznīks; ko bezdievīgie kāro, ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Alleluja! Teiciet, jūs Dieva kalpi, teiciet Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Slavēts lai ir Tā Kunga vārds no šī laika mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'No saules uzlēkšanas līdz viņas noiešanai lai slavēts ir Tā Kunga vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Tas Kungs ir augsts pār visām tautām, Viņa gods iet pār debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kas ir tāds kā Tas Kungs, mūsu Dievs? Kas ļoti augsti ir apsēdies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Kas dziļi noskatās debesīs un virs zemes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Kas nabagu paceļ no pīšļiem un bēdīgo paaugstina no dubļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Ka Viņš to sēdina pie lieliem kungiem, pie savu ļaužu lielkungiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Kas neauglīgai liek dzīvot namā, ka tā top priecīga dēlu māte. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Kad Israēls izgāja no Ēģiptes, Jēkaba nams no svešas valodas ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Tad Jūda Viņam tapa par svētu daļu, un Israēls par Viņa valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Jūra redzēja un bēga, Jardāne griezās atpakaļ;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Kalni lēkāja kā auni, pakalni kā jēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Kas tev bija, jūra, ka tu bēdz, un tev, Jardāne, ka tu atpakaļ griezies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Jums, kalni, ka jūs lēkājāt kā auni, pakalni, kā jēri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Priekš Tā Kunga drebi, zeme, Jēkaba Dieva priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Kas klinti pārvērsa par ezeru un akmeņus par ūdens avotiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ne mums, ak Kungs! ne mums, bet Savam vārdam dod godu, pēc Savas žēlastības un patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Kāpēc pagāniem būs sacīt: kur nu ir viņu Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Bet mūsu Dievs ir debesīs; visu, ko Viņš grib, to Viņš dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Viņu dievekļi ir sudrabs un zelts, cilvēku roku darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Tiem ir mute, bet tie nerunā, tiem ir acis, bet tie neredz;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Tiem ir ausis un tie nedzird, tiem ir deguns un tie neož;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Rokas tiem ir, bet tie netausta; tiem ir kājas, bet tie nestaigā; tie nerunā ar savu rīkli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Kas tos taisa, ir tādi pat kā viņi, tādi pat visi, kas uz tiem paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israēl, cerē uz To Kungu! Viņš tiem ir palīgs un priekšturamās bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Ārona nams, cerē uz To Kungu! Viņš tiem ir palīgs un priekšturamās bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Jūs visi, kas To Kungu bīstaties, cerējiet uz To Kungu! Viņš tiem ir palīgs un priekšturamās bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Tas Kungs mūs piemin un mūs svētī; Viņš svētīs Israēla namu, Viņš svētīs Ārona namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Viņš tos svētīs, kas To Kungu bīstas, ir mazus, ir lielus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Tas Kungs lai jūs vairo, jūs un jūsu bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Jūs esat Tā Kunga svētītie; Viņš radījis debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Debesu debesis Tam Kungam pieder, bet zemi Viņš devis cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Nomirušie To Kungu neslavēs nedz tie, kas nogrimuši klusumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Bet mēs gribam slavēt To Kungu, no šī laika mūžīgi. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Es mīlu(to Kungu), ka Tas Kungs klausa manu balsi un manu pielūgšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Jo Viņš griež Savu ausi pie manis, tādēļ es Viņu piesaukšu visu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Nāves saites mani bija apņēmušas, un elles bēdas man bija uzgājušas, bēdas un bailes man nāca virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Bet es piesaucu Tā Kunga vārdu: ak Kungs, izglāb manu dvēseli!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Tas Kungs ir žēlīgs un taisns, un mūsu Dievs ir sirds žēlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Tas Kungs pasargā vientiesīgos; kad es biju bēdās, tad Viņš man palīdzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Esi atkal mierā, mana dvēsele, jo Tas Kungs tev dara labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Jo tu manu dvēseli esi izglābis no nāves, manas acis no asarām, manu kāju no slīdēšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Es staigāšu Tā Kunga priekšā dzīvo zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Es ticu, tāpēc es runāju. Es biju ļoti apbēdināts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Es sacīju savās bailēs: visi cilvēki ir melkuļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kā es Tam Kungam maksāšu visas labdarīšanas, ko Viņš pie manis darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Es pacelšu to pestīšanas biķeri un piesaukšu Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Es maksāšu Tam Kungam savus solījumus visu Viņa ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Viņa svēto nāve ir dārga Tā Kunga acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ak Kungs, es esmu tiešām Tavs kalps, es esmu Tavs kalps, Tavas kalpones dēls, Tu manas saites esi atraisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Tev es upurēšu pateicības upurus un piesaukšu Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Es maksāšu Tam Kungam savus solījumus visu Viņa ļaužu priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Tā Kunga nama pagalmos, tavā vidū, Jeruzāleme. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Teiciet To Kungu, visas tautas, slavējiet Viņu, visi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Jo Viņa žēlastība un patiesība ir varena pār mums mūžīgi. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Pateiciet Tam Kungam, jo Viņš ir laipnīgs, un Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Lai saka Israēls: Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Lai saka Ārona nams: Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Lai saka, kas To Kungu bīstas: Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'No bēdām es To Kungu piesaucu, un Tas Kungs mani paklausīja plašā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Tas Kungs ir ar mani, es nebīstos; ko cilvēki man var darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Tas Kungs ir mans palīgs, un es ar prieku skatīšos uz saviem nīdētājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Labāki ir, paļauties uz To Kungu, nekā cerēt uz cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Labāki ir, paļauties uz To Kungu, nekā cerēt uz lieliem kungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Visi pagāni apmetās ap mani, bet Tā Kunga Vārdā es tos izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Tie metās pret mani visapkārt, bet Tā Kunga Vārdā es tos izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Tie apmetās ap mani kā bites, bet tie izdziest kā uguns ērkšķos; Tā Kunga Vārdā es tos izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Tu man grūdin pagrūdi, lai es krītu; bet Tas Kungs ir mans palīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Tas Kungs ir mans stiprums un mana dziesma un ir mans Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Gavilēšanas un pestīšanas balss (atskan) taisno dzīvokļos; Tā Kunga labā roka dara varenus darbus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Tā Kunga labā roka ir paaugstināta, Tā Kunga labā roka dara varenus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Es nemiršu, bet dzīvošu un izteikšu Tā Kunga darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Gan Tas Kungs mani pārmāca, bet taču Viņš mani nenodod nāvei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Atdariet man taisnības vārtus, ka es pa tiem ieeju un Tam Kungam pateicos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Šie ir Tā Kunga vārti, pa tiem tie taisnie ieies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Es tev pateicos, ka tā mani esi paklausījis un man bijis par Pestītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Tas akmens, ko tie nama taisītāji atmetuši, ir palicis par stūra akmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Tas ir no Tā Kunga, un ir brīnums mūsu acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Šī ir tā diena, ko Tas Kungs darījis; priecāsimies un līksmosimies par to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ak Kungs, palīdzi nu! ak Kungs, lai labi izdodas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Slavēts lai ir, kas nāk Tā Kunga Vārdā; mēs svētījam jūs no Tā Kunga nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Tas Kungs ir tas stiprais Dievs, kas mūs apgaismo. Piesieniet svētku upurus ar saitēm līdz altāra ragiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu esi mans Dievs, un es Tev pateicos; mans Dievs, es Tevi paaugstināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Pateiciet Tam Kungam, jo Viņš ir laipnīgs, un Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Svētīgi tie, kas nenoziedzīgi savos ceļos, kas staigā Tā Kunga bauslībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Svētīgi tie, kas Viņa liecības tur, kas no visas sirds Viņu meklē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Netaisnību nedara, bet staigā pa Viņa ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu esi pavēlējis, Tavus baušļus cieti sargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Kaut mani ceļi uz to vien dzītos, Tavus likumus sargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Kad es raudzīšos uz visiem Taviem baušļiem, tad netapšu kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Es Tev pateikšos ar skaidru sirdi, kad būšu mācījies Tavas taisnības tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Es turēšu Tavus likumus; neatstāj mani pavisam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Kā jauneklis savu ceļu turēs šķīstu? Kad viņš turas pēc Taviem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Es Tevi meklēju no visas sirds; neliec man nomaldīties no Taviem baušļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Es paturu Tavus vārdus savā sirdī, ka negrēkoju pret Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Slavēts esi Tu, Kungs; māci man Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Ar savām lūpām es izteikšu visas Tavas mutes tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Es priecājos par Tavas liecības ceļu kā vien par kādu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Es pārdomāju Tavas pavēles un ņemu vērā Tavus ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Es priecājos par Taviem likumiem; Tavu vārdu es neaizmirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Dari labu Savam kalpam, ka es dzīvoju un pasargu Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Atdari manas acis, ka es uzlūkoju Tavas bauslības brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Es esmu svešinieks virs zemes; neapslēp priekš manis Tavus baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mana dvēsele ir satriekta caur ilgošanos pēc Tavām tiesām vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu rāji pārgalvjus, tos nolādētos, kas no Taviem baušļiem nomaldās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Novērs no manis kaunu un negodu, jo es turu Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Kaut arī lieli kungi sēž un runā pret mani, bet Tavs kalps apdomā Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Tavas liecības ir mans prieks un padoms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mana dvēsele līp pie pīšļiem; dari man dzīvu pēc Tava Vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Es izteicu savus ceļus, un Tu mani paklausi; māci man Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Liec man saprast Tavu likumu ceļus, ka es varu pārdomāt Tavus brīnumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mana dvēsele raud noskumusi; stiprini mani ar Tavu Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Novērs no manis viltības ceļu un dāvini man Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Patiesības ceļu es esmu izredzējies, Tavas tiesas esmu licis savā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Es turos pie Tavām liecībām, ak Kungs, nepamet mani kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Kad Tu manu sirdi atvieglini, tad es teku Tavas bauslības ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Māci man, Kungs, Tavu likumu ceļus, ka es tos pasargu līdz galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Dod man saprašanu, ka es Tavu bauslību sargu un to turu no visas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Vadi mani uz Tavas bauslības ceļu, jo pie tā man ir labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Loki manu sirdi pie Tavām liecībām, un ne pie mantu kārības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Nogriez manas acis, ka tās neskatās uz nelietību, dari mani dzīvu uz Tava ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Apstiprini Savam kalpam Tavu vārdu, tiem par labu, kas Tevi bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Novērs manu kaunu, par ko es bīstos, jo Tavas tiesas ir labas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Redzi, es mīlu Tavas pavēles; dari mani dzīvu pēc Tavas taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Kungs, lai man nāk Tava žēlastība, Tava pestīšana pēc Tava vārda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Ka varu atbildēt savam mēdītājam, jo es paļaujos uz Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Un neatrauj pavisam no manas mutes patiesības vārdu, jo es ceru uz Tavām tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Es turēšu Tavu bauslību vienmēr, mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Un es staigāšu bez bēdām, jo es meklēju Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Par Tavām liecībām es runāšu ķēniņu priekšā un nepalikšu kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Es priecājos par Taviem baušļiem, ko es mīlēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Un es paceļu savas rokas pie Taviem baušļiem, ko es mīlēju, un pārdomāju Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Piemini Savam kalpam to vārdu, uz ko Tu man lieci cerēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Šī ir mana iepriecināšana manās bēdās, jo Tava apsolīšana mani dara dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Pārgalvji mani apsmej pārlieku, bet es neatkāpjos no Tavas bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Kungs, kad es pieminu Tavas tiesas no senlaikiem, tad topu iepriecināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Lielas dusmas mani pārņēmušas to bezdievīgo dēļ, kas Tavu bauslību atstāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tava bauslība ir mana dziesma manas svešniecības namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Kungs, naktī es pieminu Tavu vārdu un turu Tavu bausli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Tā ir mana manta, ka es turu Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Tu, Kungs, esi mana daļa; es esmu solījis, turēt Tavus Vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Es Tevi pielūdzu no visas sirds; esi man žēlīgs pēc Tavas apsolīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Es apdomāju savus ceļus un griežu savas kājas pie Tavām liecībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Es steidzos un nekavējos, Tavus baušļus turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Bezdievīgie man apmetuši valgus, taču es neaizmirstu Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Nakts vidū es ceļos, Tev pateikties par Tavas taisnības tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Es piebiedrojos visiem, kas Tevi bīstas, un visiem, kas tur Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Kungs, zeme ir pilna Tavas žēlastības; māci man Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tu dari labu Savam kalpam, ak Kungs, pēc Sava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Māci man labu saprašanu un atzīšanu, jo es ticu Taviem baušļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Pirms tapu pazemots, es alojos; bet nu es turu Tavu Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu esi labs un dari labu, māci man Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Pārgalvji izperē melus pret mani, bet es turu Tavas pavēles no visas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Viņu sirds ir bieza kā tauki, bet es priecājos par Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Labi man, ka esmu apbēdināts, lai mācos Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Tavas mutes bauslība man ir labāka nekā tūkstoši zelta un sudraba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Tavas rokas mani radījušas un taisījušas; dari mani gudru, ka es mācos Tavus baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Kas Tevi bīstas, mani uzlūko un priecājās; jo es gaidu uz Taviem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Es zinu, Kungs, ka Tavas tiesas ir taisnas, un Tu mani esi pazemojis pēc Tavas uzticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Lai jel Tava žēlastība man ir par iepriecināšanu, tā kā Tu Savam kalpam esi solījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Lai Tava žēlastība man notiek, ka es dzīvoju, jo Tava bauslība ir mans prieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Lai top kaunā pārgalvji, kas mani ar meliem nospieduši; bet es pārdomāju Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Lai pie manis griežas, kas Tevi bīstas, un kas pazīst Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Lai mana sirds ir skaidra pie Taviem likumiem, ka netopu kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Manai dvēselei slāpst pēc Tavas pestīšanas; es ceru uz Taviem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Manas acis ilgojās pēc Tavām apsolīšanām, ka es saku: kad Tu mani iepriecināsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Jo es esmu kā ādas trauks dūmos; taču es neaizmirstu Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Cik tad Tavam kalpam dienu? Kad Tu turēsi sodu pār maniem vajātājiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Pārgalvji man rok bedres, tie, kas neturas pēc Tavas bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Visi Tavi baušļi ir patiesība; tie mani vajā ar meliem, - palīdzi man!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Tie mani gandrīz iznīcinājuši virs zemes, bet es neesmu atstājis Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Atspirdzini mani pēc Tavas žēlastības, tad es sargāšu Tavas mutes liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Kungs, Tavs vārds pastāv mūžīgi debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Tava patiesība stāv līdz radu radiem. Tu zemi esi stiprinājis, ka tā stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Pēc Taviem likumiem tie vēl šodien stāv, jo viss Tev kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Ja Tava bauslība nebūtu bijusi mans prieks, tad es jau sen būtu bojā gājis savās bēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Tavas pavēles es neaizmirsīšu ne mūžam, jo caur tām Tu mani esi atspirdzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Tavs es esmu, atpestī mani; jo es meklēju Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Bezdievīgie glūn uz mani, mani samaitāt, bet es lieku vērā Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Es esmu redzējis, ka ikvienam stiprumam ir gals, bet Tavs bauslis pastāv bez gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Cik ļoti es mīlēju Tavu bauslību! To es pārdomāju ikdienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Ar Saviem baušļiem Tu dari mani gudrāku pār maniem ienaidniekiem, jo tie (baušļi) ir mūžam pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Es esmu vairāk izmācīts nekā visi mani mācītāji, jo es pārdomāju Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Es esmu prātīgāks nekā tie vecie, jo es turu Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Es atrauju savu kāju no visiem blēžu ceļiem, ka es sargāju Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Es neatkāpjos no Tavām tiesām, jo Tu mani māci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Cik saldi ir Tavi vārdi manai mutei, saldāki par medu manām lūpām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Caur Tavām pavēlēm es topu prātīgs, tādēļ es ienīstu visus viltus ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Tavs vārds ir manas kājas spīdeklis un gaišums uz maniem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Es esmu zvērējis un to turēšu stipri, ka es sargāšu Tavas taisnības tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Es esmu ļoti apbēdināts, Kungs, atspirdzini mani pēc Tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Ak Kungs, lai Tev jel patīk manas mutes upuri, un māci man Tavas tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Mana dvēsele stāv vienmēr manā rokā, taču es neaizmirstu Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Bezdievīgie man liek valgus, taču es nealojos no Tavām pavēlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tavas liecības es turu par savu mantu mūžīgi, jo tās ir manas sirds līksmība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Es griežu savu sirdi, darīt Tavus likumus mūžīgi līdz pat galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Es ienīstu tos divprātīgos un mīlēju Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu esi mans patvērums un manas priekšturamās bruņas; uz Tavu vārdu es gaidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Atstājaties no manis, jūs ļauna darītāji, ka es varu turēt sava Dieva baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Uzturi mani pēc Tava Vārda, ka es dzīvoju, un lai es kaunā netopu savā cerībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Stiprini mani, ka topu vesels, tad es skatīšos uz Taviem likumiem vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu atmeti visus, kas no Taviem likumiem nomaldās; jo meli ir viņu viltus būšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu atmeti visus bezdievīgos virs zemes kā sārņus, tādēļ es mīļoju Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Es tā bīstos no Tevis, ka šaušalas pāriet pār manām miesām, un man ir bail no Tavām sodībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Es daru tiesu un taisnību; nenodod mani maniem varas darītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Aizstāvi Tu Savu kalpu uz labu, ka pārgalvji mani nepārvar.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Manas acis ilgojās pēc Tavas pestīšanas un pēc Tava taisnā vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Dari pēc Savas žēlastības Savam kalpam un māci man Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Es esmu Tavs kalps; dari man gudru, ka es atzīstu Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Laiks ir, ka Tas Kungs Savu darbu dara; tie lauzuši Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Tādēļ es mīļoju Tavu bauslību vairāk nekā zeltu un šķīstu zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Tādēļ es turu visas pavēles par it taisnām; ikkatru viltus ceļu es ienīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Tavas liecības ir brīnišķas, tādēļ mana dvēsele tās tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Kad Tavi Vārdi atveras, tad tie apgaismo un dara vientiesīgos gudrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Savu muti es atdaru ilgodamies, jo Tavu baušļu man gribās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Griezies pie manis un esi man žēlīgs, kā Tu mēdzi darīt tiem, kas Tavu vārdu mīl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Stiprini manus soļus iekš Taviem vārdiem, un lai ļaunums nevalda pār mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Atpestī mani no cilvēku spaidiem, tad es turēšu Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Apgaismo Savu vaigu pār Savu kalpu un māci man Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Manas acis izraud asaru upes, tāpēc ka netur Tavu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Kungs, Tu esi taisns un Tavas tiesas ir taisnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Taisnībā Tu esi piekodinājis un lielā patiesībā Savas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mans karstums mani gandrīz nomācis, tāpēc ka mani pretinieki aizmirst Tavus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Tavi Vārdi ir ļoti šķīsti, un Tavs kalps tos mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Es esmu mazs un nievāts, bet Tavas pavēles es neaizmirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Tava taisnība ir taisnība mūžīgi, un Tava bauslība ir patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Bēdas un bailes man uzgājušas, bet Tavi baušļi ir mans prieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Tavu liecību taisnība ir mūžīga; liec man to saprast, tad es dzīvošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Es saucu no visas sirds, paklausi mani, Kungs, tad es turēšu Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Es Tevi piesaucu, palīdzi man, ka turu Tavas liecības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Es nāku ar mazu gaismiņu un kliedzu; uz Tavu Vārdu es ceru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Agri manas acis mostas, pārdomāt Tavus Vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Klausi manu balsi pēc Tavas žēlastības; Kungs, atspirdzini mani pēc Tavām tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Kas dzenās pēc blēdības, tie laužās uz mani, tie atkāpjas tālu no Tavas bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Kungs, Tu esi tuvu, un visi Tavi baušļi ir patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'No iesākuma es zinu, ka Tu Savas liecības esi stiprinājis uz mūžību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Uzlūko manās bēdās un izglāb mani, jo Tavu bauslību es neaizmirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Iztiesā Tu manu tiesu un atpestī mani, atspirdzini mani pēc Taviem Vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Pestīšana paliek tālu no bezdievīgiem, jo tie nemeklē Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Kungs, liela ir Tava apžēlošanās; atspirdzini mani pēc Tavām tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Daudz ir manu vajātāju un pretinieku; bet es neatkāpjos no Tavām liecībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Es redzu pārkāpējus, un man sāp, ka tie netur Tavus Vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Uzlūko, ka es Tavas pavēles mīļoju; ak Kungs, atspirdzini mani pēc Tavas žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Tavs vārds visnotaļ ir patiesība, un visas Tavas taisnās tiesas paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Lieli kungi mani vajā bez vainas, bet mana sirds bīstas no Taviem Vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Es priecājos par Tavu Vārdu, kā kas dabūjis lielu laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Es ienīstu melus un turu tos par negantību; Tavu bauslību es mīļoju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Es Tevi teicu septiņkārt dienā par Tavām taisnām tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Kas Tavu bauslību mīļo, tiem ir liels miers un tie nekur nepiedurās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Ak Kungs, es gaidu uz Tavu pestīšanu un daru pēc Taviem baušļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mana dvēsele tur Tavas liecības, un es tās ļoti mīļoju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Es pasargu Tavas pavēles un Tavas liecības, jo visi mani ceļi ir Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Ak Kungs, lai mana saukšana nāk priekš Tava vaiga! Dari mani gudru pēc Tava Vārda!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Lai mana sirds lūgšana nāk priekš Tava vaiga! Izglāb mani pēc Tava Vārda!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Manas lūpas teiktin teiks Tavu slavu, kad tu man māci Tavus likumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Mana mēle dziedās no Taviem vārdiem, jo visi Tavi baušļi ir taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Lai Tava roka man nāk palīgā, jo Tavas pavēles es esmu izredzējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Kungs, man gribās Tavas pestīšanas, un Tava bauslība ir mans prieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Lai dzīvo mana dvēsele, ka tā Tevi var teikt, un lai Tavas tiesas man palīdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Es maldos kā pazudusi avs, - meklē Savu kalpu, jo es neaizmirstu Tavas pavēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Svētku dziesma. Es piesaucu To Kungu savās bēdās, un Viņš mani paklausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Kungs, izglāb manu dvēseli no melkuļu lūpām un viltnieku mēlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Ko viltīgā mēle Tev dos, jeb ko viņa Tev pieliks?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Tā ir kā varoņa asas bultas, kā degošas paegļu ogles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Ak vai, man, ka esmu svešinieks iekš Mešeha, un ka man jādzīvo Kedara dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Par ilgu manai dvēselei dzīvot pie tiem, kas mieru ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Es turu mieru, bet tikko es runāju, tad tie ceļ ķildu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Svētku dziesma. Es paceļu savas acis uz tiem kalniem, no kurienes man nāk palīdzība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Mana palīdzība nāk no Tā Kunga, kas debesis un zemi radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Viņš tavai kājai neliks slīdēt; kas tevi pasargā, Tas nesnauž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Redzi, Israēla sargs nesnauž un neguļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Tas Kungs tevi pasargā; Tas Kungs ir tava ēna pa tavu labo roku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Ka dienā saule tevi nespiež, nedz mēnesis naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Tas Kungs lai tevi pasargā no visa ļauna, lai Viņš sarga tavu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Tas Kungs lai pasargā tavu iziešanu un ieiešanu, no šī laika mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Dāvida svētku dziesma. Es priecājos ar tiem, kas uz mani saka: iesim Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Mūsu kājas stāvēs tavos vārtos, Jeruzāleme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jeruzāleme, kas atkal par pilsētu uzcelta, kas visapkārt sastiprināta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Kurp tās ciltis iet, Tā Kunga ciltis, kā Israēlim pavēlēts, pateikt Tā Kunga vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Jo tur tie tiesas krēsli likti, Dāvida nama krēsli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Vēlējiet mieru Jeruzālemei; lai labi klājās tiem, kas tevi mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Miers lai ir iekš taviem mūriem, labklāšana iekš taviem skaistiem namiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Savu brāļu un savu draugu labad es tev vēlēšu mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Tā Kunga, mūsu Dieva, nama labad, es meklēšu tavu labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Svētku dziesma. Es paceļu savas acis uz Tevi, kas sēdi debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Redzi, kā kalpu acis uz sava kunga rokām, un kā kalpoņu acis uz savas valdnieces rokām, tā mūsu acis skatās uz To Kungu, mūsu Dievu, tiekams Viņš mūs žēlos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Esi mums žēlīgs, ak Kungs, esi mums žēlīgs, jo mēs esam pārlieku nievāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Mūsu dvēsele pārlieku top mēdīta no grezniem un nievāta no augstprātīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Dāvida svētku dziesma. Ja Tas Kungs pie mums nebūtu bijis, tā lai jel Israēls saka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Ja Tas Kungs pie mums nebūtu bijis, kad cilvēki pret mums cēlās:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Tad tie mūs dzīvus būtu aprijuši, kad viņu dusmība pret mums apskaitās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Tad ūdens mūs būtu apslīcinājis, un upes būtu plūdušas pār mūsu dvēseli;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Tad augsti viļņi būtu gājuši pār mūsu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Lai Tas Kungs ir slavēts, kas mūs nav nodevis viņu zobiem par laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Mūsu dvēsele ir izglābta, kā putns no mednieka valgiem: valgs pārrauts, un mēs esam izglābti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Mūsu palīdzība ir iekš Tā Kunga vārda, kas radījis debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Svētku dziesma. Kas uz To Kungu cerē, tie nešaubīsies, bet mūžīgi stāvēs, kā Ciānas kalns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Ap Jeruzālemi ir kalni, bet Tas Kungs ir ap Saviem ļaudīm no šī laika mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Jo bezdievības scepteris nepaliks pār taisno ļaužu mantas daļu, ka tie taisnie neizstiepj savas rokas pie netaisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Kungs, dari labu labiem un tiem, kas savā sirdī skaidri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Bet kas nogriežas uz saviem līkiem ceļiem, tos Tas Kungs aizdzīs ar ļauna darītājiem; bet miers lai ir pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Svētku dziesma. Kad Tas Kungs atkal atveda Ciānas cietumniekus, tad mēs bijām tā kā kas sapņus redz;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tad mūsu mute bija pilna smiešanās un mūsu mēle pilna gavilēšanas; tad sacīja starp pagāniem: Tas Kungs lielas lietas pie šiem ir darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Tas Kungs lielas lietas pie mums ir darījis, par to priecājamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Ak Kungs, atved atpakaļ mūsu cietumniekus, kā upes dienvidu zemē!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Kas ar asarām sēj, ar gavilēšanu pļaus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Tie aiziet un raud, dārgu sēklu nesdami, bet tiešām ar prieku tie atkal nāks un nesīs savus kūlīšus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Salamana svētku dziesma. Ja Tas Kungs namu neuztaisa, tad darbojās velti, kas pie tā strādā; ja Tas Kungs pilsētu neapsargā, tad sargs velti nomodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Velti jums, agri celties un vēlu palikt nomodā un ēst savu maizi ar bēdām. Tiešām, Saviem mīļiem Viņš dod miegā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Redzi, bērni ir manta no Tā Kunga, un miesas auglis ir dāvana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Tā kā bultas stipra vīra rokās, tāpat ir jaunie bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Svētīgs tas vīrs, kas savu bultu maku ar to pildījis; tie netaps kaunā, kad tiem vārtos nāk runas ar saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Svētku dziesma. Svētīgs ikviens, kas To Kungu bīstas un staigā viņa ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Tu mitināsies no savu roku darba; svētīgs tu esi, tev labi klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Tava sieva būs kā auglīgs vīna koks ap tavu namu, tavi bērni kā eļļas zari ap tavu galdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Redzi, tā ir svētīts tas vīrs, kas To Kungu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Tas Kungs lai tevi svētī no Ciānas, ka tu redzi Jeruzālemes labumu visas savas mūža dienas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Un redzi savu bērnu bērnus: Miers lai ir pār Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Svētku dziesma. Tie mani daudzkārt apbēdinājuši no manas jaunības, tā lai Israēls saka;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Tie mani daudzkārt apbēdinājuši no manas jaunības, bet tie mani nav pārvarējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Arāji ir aruši uz manas muguras, tie savas vagas garas dzinuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Tas Kungs ir taisns, Viņš sacirtis bezdievīgo valgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Lai top kaunā un atpakaļ dzīti visi kas Ciānu ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Lai tie top kā zāle uz jumtiem, kas nokalst, pirms tā top plūkta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Ar ko pļāvējs nepilda savu roku, nedz kopiņu sējējs savu klēpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Un tie, kas garām iet, lai nesaka: Tā Kunga svētība lai nāk pār jums, mēs jūs svētījam Tā Kunga Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Svētku dziesma. No dziļumiem es Tevi piesaucu, Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Ak Kungs, klausi manu balsi, lai Tavas ausis uzmana uz manas sirds lūgšanas balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Ja Tu, Kungs, gribi noziegumus pielīdzināt, - ak Kungs, kas pastāvēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Bet pie Tevis ir piedošana, lai Tevi bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Es gaidu uz To Kungu, mana dvēsele gaida, un es ceru uz Viņa vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mana dvēsele gaida uz To Kungu vairāk nekā uz rīta gaismu sargi, kas rītu gaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israēls lai cerē uz To Kungu, jo pie Tā Kunga ir žēlastība un daudz pestīšanas pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Un Viņš atpestīs Israēli no visiem viņa noziegumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Dāvida svētku dziesma. Kungs, mana sirds nav lepna, un manas acis nav greznas; es netinos ar lielām lietām, kas man ir visai brīnišķas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Tiešām, savu dvēseli es esmu remdējis un klusinājis, kā bērnu, kas atšķirts no savas mātes; mana dvēsele ir pie manis kā atšķirts bērns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israēl, cerē uz To Kungu no šī laika un mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Svētku dziesma. Kungs, piemini Dāvidu un visas viņa rūpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Tas Tam Kungam zvērējis un solījies Jēkaba varenajam:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Es neiešu sava nama dzīvoklī, es nekāpšu savas gultas cisās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Es nedošu savām acīm miegu redzēt nedz snaust saviem acu vākiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Līdz kamēr būšu atradis vietu Tam Kungam un mitekli Jēkaba varenajam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Redzi, mēs par to esam dzirdējuši Efratā, mēs to esam atraduši Jaāra laukos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Iesim Viņa mājas vietā un pielūgsim priekš Viņa kāju pamesla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Celies, Kungs, uz Savu dusas vietu, Tu un Tavas spēcības šķirsts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Lai Tavi priesteri apģērbjās ar taisnību, un Tavi svētie lai gavilē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Neatmet Sava svaidītā vaigu, Sava kalpa Dāvida dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Tas Kungs Dāvidam tiešām ir zvērējis, no tā Viņš nenovērsīsies: No tavas miesas augļiem būs, ko celšu uz tavu godības krēslu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Ja tavi bērni turēs Manu derību un Manu liecību, ko Es tiem mācīšu, tad arī viņu bērni sēdēs uz tava godības krēsla mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Jo Tas Kungs Ciānu ir izredzējis, tur Viņam gribās dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Šī ir Mana dusas vieta mūžīgi, šeit Es dzīvošu, jo tās Man gribās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Svētīdams Es svētīšu viņas barību un paēdināšu viņas nabagus ar maizi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Un apģērbšu viņas priesterus ar pestīšanu, un viņas svētie gavilēt gavilēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tur Es Dāvidam uzcelšu ragu, došu spīdekli Savam svaidītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Viņa ienaidniekus Es apģērbšu ar kaunu, bet viņam ziedēs viņa kronis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Dāvida svētku dziesma. Redzi, cik jauki un cik mīlīgi, kad brāļi dzīvo vienprātīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Tas ir, kā tā vislabākā eļļa, kas no Ārona galvas notek viņa bārdā, kas notek līdz viņa drēbju vīlei,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Tā kā rasa, kas no Hermona nokrīt uz Ciānas kalniem; jo Tas Kungs tur apsola svētību un dzīvību mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Svētku dziesma. Redzi, teiciet To Kungu, visi Tā Kunga kalpi, kas naktī stāvat Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Paceliet savas rokas pret to svēto vietu un teiciet To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Tas Kungs, kas debesis un zemi radījis, Tas lai tevi svētī no Ciānas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Alleluja! Slavējiet Tā Kunga vārdu, slavējiet jūs, Tā Kunga kalpi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Kas stāvat Tā Kunga namā, mūsu Dieva nama pagalmos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Slavējiet To Kungu, jo Tas Kungs ir labs, dziediet Viņa vārdam, jo Viņš ir mīlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Jo Tas Kungs Jēkabu Sev izredzējis, Israēli par Savu īpašumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Jo es zinu, ka Tas Kungs ir liels, un mūsu Kungs lielāks nekā visi dievi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Visu, ko Tas Kungs grib, to Viņš dara, debesīs un virs zemes, jūrā un visos dziļumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Viņš uzved miglu no zemes galiem, dod zibeņus pie lietus, izved vēju no viņa kambariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Viņš nokāva Ēģiptes pirmdzimušos, gan cilvēkus gan lopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Viņš sūtīja zīmes un brīnumus tavā vidū, Ēģiptes zemē, pret Faraonu un visiem viņa kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Viņš kāva daudz tautas un nokāva varenus ķēniņus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihonu, Āmoriešu ķēniņu, un Ogu, Basanas ķēniņu, un visas Kanaāna valstis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Un deva viņu zemi par mantību, par mantību Saviem Israēla ļaudīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Kungs, Tavs vārds paliek mūžīgi, Kungs, Tava piemiņa paliek līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Jo Tas Kungs tiesās Savus ļaudis un apžēlosies par Saviem kalpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Pagānu elki ir sudrabs un zelts, cilvēku roku darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Tiem ir mute, bet tie nerunā, tiem ir acis, bet tie neredz,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Tiem ir ausis, bet tie nedzird, ir dvašas tiem nav mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Tādi pat kā viņi, ir tie, kas tos taisa, un visi, kas uz tiem paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Jūs, Israēla nams, teiciet To Kungu; jūs, Ārona nams, teiciet To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Jūs Levja nams, teiciet To Kungu; jūs, kas To Kungu bīstaties, teiciet To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Slavēts lai ir Tas Kungs no Ciānas, kas dzīvo Jeruzālemē. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Pateiciet Tam Kungam, jo Viņš ir laipnīgs, un Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Pateiciet tam dievu Dievam, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Pateiciet tam kungu Kungam, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Tam, kas vien lielus brīnumus dara, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Kas debesis ar gudrību radījis, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Kas zemi pār ūdeņiem izplatījis, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Kas lielus spīdekļus darījis, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Sauli, lai dienu valda, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Mēnesi un zvaigznes, lai nakti valda, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Kas ēģiptiešiem viņu pirmdzimtos nokāvis, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Un Israēli no viņu vidus izvedis; jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Ar stipru roku un izstieptu elkoni, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Kas Niedras jūru pāršķīris, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Un Israēli caur viņu cauri izvedis, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Un Faraonu ar viņa karaspēku iegāzis Niedras jūrā, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Kas savus ļaudis pa tuksnesi vadījis, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Kas lielus ķēniņus kāvis, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Un nokāvis varenus ķēniņus, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihonu, Āmoriešu ķēniņu, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Un Ogu, Basanas ķēniņu, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Un devis viņu zemi par mantību, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Par mantību Israēlim, savam kalpam, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Kas mūs pieminējis mūsu bēdās, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Un mūs izrāvis no mūsu spaidītājiem, jo Viņa žēlastība paliek mūžīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Kas visai miesai dod barību, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Pateiciet Dievam debesīs, jo Viņa žēlastība paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Pie Bābeles upēm, tur mēs sēdējām un raudājām, kad pieminējām Ciānu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Savas kokles tur pakārām vītolos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Jo mūsu aizvedēji cietumā tur no mums prasīja dziesmas un mūsu spaidītāji līksmību: Dziediet mums dziesmu no Ciānas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kā mēs varētu dziedāt Tā Kunga dziesmu svešā zemē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Ja es tevi aizmirstu, Jeruzāleme, tad lai mana labā roka top aizmirsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Mana mēle lai pielīp pie mana zoda, ja es tevi nepieminu, ja es nepaceļu Jeruzālemi par savu vislielāko prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Kungs, piemini Jeruzālemes dienu Edoma bērniem, kas sacīja: Nopostiet, nopostiet to līdz pat viņas pamatiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Tu posta pilna Bābeles meita, svētīgs ir, kas tev atmaksā, kā tu mums esi darījusi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Svētīgs būs, kas tavus jaunos bērnus sagrābs un tos satrieks pie akmens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Dāvida dziesma. Es Tev pateicos no visas savas sirds, dievu priekšā es Tev gribu dziedāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Es pielūgšu Tavā svētā namā, un pateikšos Tavam vārdam par Tavu žēlastību un patiesību, jo Tu pāri par Savu vārdu esi paaugstinājis Savas apsolīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Tai dienā, kad es piesaucu, tad Tu mani paklausīji, Tu manai dvēselei esi devis drošību un spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Visi ķēniņi virs zemes Tev pateiksies, Kungs, kad tie dzirdēs Tavas mutes vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Un tie dziedās no Tā Kunga ceļiem, jo Tā Kunga godība ir liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Jo Tas Kungs ir augsts, un taču Viņš uzlūko pazemīgo un pazīst lepno no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Kad es staigāju pašā bēdu vidū, tad Tu mani atspirdzini; Tu izstiep Savu roku pret manu ienaidnieku dusmību, un Tava labā roka man palīdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Tas Kungs to priekš manis izdarīs. Tava žēlastība, Kungs, paliek mūžīgi; Savu roku darbu Tu neatstāsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Dāvida dziesma, dziedātāju vadonim. Kungs, Tu mani pārmani un pazīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu zini manu sēdēšanu un celšanos, Tu noproti manas domas no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Lai eju, lai guļu, Tu esi ap mani, un Tev zināmi visi mani ceļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Jo nav ne vārda uz manas mēles; redzi, Kungs, to visu Tu zini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu meties ap mani pakaļā un priekšā un turi Savu roku pār mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Šī atzīšana man ir visai brīnišķa un augsta, es to nevaru izprast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kur man būs aiziet no Tava Gara, un kur man būs bēgt no Tava vaiga?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Ja es kāptu debesīs, tad Tu tur esi; ja es nogultos ellē, redzi, Tu tur arīdzan esi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Ja es ņemtu ausekļa spārnus un paliktu jūras galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Tad arī tur Tava roka mani vadīs, un Tava labā roka mani turēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Ja es sacītu: Lai tumsība mani apklāj un par nakti lai paliek gaisma ap mani:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Tad ir tumsība Tavā priekšā nebūtu tumša, un nakts spīdētu kā diena, tumsība būtu kā gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Jo Tu esi radījis manas īkstis, Tu mani esi apsedzis manas mātes miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Es Tev pateicos, ka es ļoti brīnišķi esmu darīts, brīnišķi ir Tavi darbi, un mana dvēsele to it labi zin.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Mani kauli Tev nebija apslēpti, kad es slepenībā tapu darīts, kad es tapu iztaisīts zemes dziļumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tavas acis redzēja mani, vēl neiztaisītu pīti(miesas iedīgli), un visas nākamās dienas bija rakstītas Tavā grāmatā, kad vēl nebija nevienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Cik dārgas man ir Tavas domas, ak Dievs! Cik liels ir viņu skaits!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Kad tās jāskaita, tad viņu vairāk nekā smiltis. Es uzmostos un vēl esmu pie Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ak Dievs, kaut Tu bezdievīgo nokautu, un kaut asinsvainīgie no manis atstātos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Tie par Tevi runā ar negantību un Tavi ienaidnieki lepojās ar viltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Vai man nebūs ienīdēt, kas Tevi, Kungs, ienīst, un ieriebt, kas pret Tevi ceļas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Ienīdēt es tos ienīstu, tie man ir ienaidnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Pārbaudi mani, ak Dievs, un atzīsti manu sirdi, izmeklē mani un atzīsti manas domas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Un redzi, vai es esmu negantā ceļā, un vadi mani uz mūžīgu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Dāvida dziesma, dziedātāju vadonim. Izglāb mani, Kungs, no ļauniem cilvēkiem, izrauj mani no varas darītājiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Kas ļaunu domā savā sirdī, kas ikdienas saceļ karu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Tie trin savu mēli kā čūska, odžu dzelonis ir apakš viņu lūpām. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Pasargi mani, Kungs, no bezdievīgo rokām, izglāb mani no varas darītājiem, kas domā nostumt manas kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Tie lepnie man liek valgus un virves, tie man izpleš tīklu ceļmalā un liek man slazdus. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Es saku uz To Kungu: Tu esi mans Dievs, klausies, ak Kungs, uz manas sirds lūgšanas balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Kungs, Dievs, mans stiprais Pestītājs, Tu apsedz manu galvu kaušanas laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Nedod, ak Kungs, tam bezdievīgam, ko viņš kāro, un lai viņa padoms neizdodas, jo tie greznojās. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Tiem, kas ap mani metās, lai nāk uz viņu galvu tā nelaime, par ko tie runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Degošas ogles lai krīt uz tiem. Viņš tos gāzīs ugunī, dziļās bedrēs, ka tie vairs necelsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Lielmutis nepastāvēs virs zemes, nelaime varmāku vajās un trieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Es zinu, ka Tas Kungs iztiesās nabaga lietas un bēdīgā tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Tiešām, taisnie Tavam vārdam pateiksies, sirdsskaidrie pastāvēs Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Dāvida dziesma. Kungs, Tevi es piesaucu, steidzies pie manis, klausies uz manu balsi, kad es Tevi piesaucu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Lai mana lūgšana Tavā priekšā top cienīta kā kvēpināmais upuris, manu roku pacelšana kā vakara upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Kungs, sargi manu muti un pasargi manas lūpas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Nedod manai sirdij griezties uz ļaunu, bezdievīgu darbu darīt ar ļaundarītājiem, ka nebaudu no viņu kārumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Lai taisnais mani sit, tā būs žēlastība, un lai viņš mani pārmāca, tā būs eļļa uz manu galvu, tam lai mana galva neliedzās; bet es vienmēr lūdzu pret viņu ļauniem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'No akmens kalniem viņu soģi lai top nogāzti; tad dzirdēs manus vārdus, ka tie mīlīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Kā zemi uzplēš un uzar, tā mūsu kauli ir izkaisīti līdz pašam kapam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Bet uz Tevi, Kungs, Dievs, manas acis raugās, uz Tevi paļaujos, neatstum manu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Pasargi mani no tā valga, ko tie man ir izmetuši, un no ļauna darītāju slazdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Bezdievīgie kritīs savos tīklos, kamēr es iešu garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Dāvida pamācība; lūgšana, kad viņš bija alā. Es piesaucu To Kungu ar savu balsi, es lūdzu To Kungu ar savu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Es izgāžu savu žēlošanos Viņa priekšā, es izstāstu Viņa priekšā savas bēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Kad mans gars iztrūcināts, tad Tu zini manu ceļu; tie man liek valgus ceļā, kur es eju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Skaties pa labo roku un redzi, tur nav neviena, kas mani grib pazīt: es nekur nevaru izbēgt, neviens nebēdā par manu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Tevi es piesaucu, Kungs; es saku: Tu esi mana cerība, mana daļa dzīvo zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Ņem vērā manu kliegšanu, jo es esmu ļoti nonīcis; izglāb mani no maniem vajātājiem, jo tie man ir visai vareni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Izved manu dvēseli no cietuma, ka es pateicos Tavam vārdam; par mani gavilēs taisnie, kad Tu man labu darīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Dāvida dziesma. Ak Kungs, klausi manu lūgšanu, ņem vērā manas sirds lūgšanas Savas patiesības dēļ, paklausi mani Savas taisnības dēļ!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Un neej sodā ar Savu kalpu, jo Tavā priekšā neviens, kas dzīvo, nav taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Jo ienaidnieks vajā manu dvēseli, viņš samin manu dzīvību pie zemes, viņš mani liek tumsībā, kā tos, kas jau sen miruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Un mans gars iekš manis iztvīcis, mana sirds iekš manis nonīkusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Es pieminu senos laikus, es pārdomāju visus Tavus darbus, es runāju pie sevis par to, ko Tava roka darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Es izplešu savas rokas uz Tevi, mana dvēsele ir Tavā priekšā kā izkaltusi zeme. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Steidzies mani paklausīt, Kungs, - mans gars nonīcis; neapslēp Savu vaigu priekš manis, lai netopu kā tie, kas grimst bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Liec man agri dzirdēt Tavu žēlastību, jo es paļaujos uz Tevi; dari man zināmu to ceļu, pa ko man jāiet; jo uz Tevi nesās mana dvēsele.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Izglāb mani, Kungs, no maniem ienaidniekiem, Tev es pavēlos(iekš Tevis es patveros).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Māci man darīt pēc Tava prāta, jo Tu esi mans Dievs, Tavs labais Gars lai mani vada pa taisnu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Tava vārda dēļ ak Kungs, atspirdzini mani, izved manu dvēseli no bēdām Savas taisnības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Un izposti manus ienaidniekus Savas žēlastības dēļ, un iznīcini visus, kas manu dvēseli apbēdina, jo es esmu Tavs kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Dāvida dziesma. Slavēts lai ir Tas Kungs, mans patvērums, kas manām rokām māca kauties, un maniem pirkstiem karot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Mans žēlotājs un mana stiprā pils, mans patvērums un mans izglābējs, manas priekšturamās bruņas, uz ko es paļaujos, kas manus ļaudis man dara paklausīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Kungs, kas ir cilvēks, ka Tu viņu piemini? Un cilvēka bērns, ka Tu viņu lieci vērā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Cilvēks ir kā dvaša, viņa laiks ir kā ēna, kas aiziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Kungs, nolaid Savas debesis un kāp zemē, aizskar kalnus, ka tie kūp.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Met zibeņus un izkaisi tos, šaudi Savas bultas un izbiedē tos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Izstiep Savas rokas no augstības, atpestī mani un izglāb mani no lieliem ūdeņiem, no svešinieku rokas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Viņu mute runā melus, un viņu labā roka ir viltus roka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Ak Dievs, es Tev dziedāšu jaunu dziesmu, es Tev dziedāšu ar desmit stīgu koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Tu ķēniņiem dod pestīšanu, un izglābi Savu kalpu Dāvidu no nikna zobena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Izglābi mani un atpestī mani no svešinieku rokas, kas ar savu muti melus runā, un viņu labā roka ir viltus roka;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Ka mūsu dēli uzaug savā jaunībā kā stādi, mūsu meitas kā izcirsti stūra pīlāri pils namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Ka mūsu klētis ir pilnas un izdod visādu mantu, ka mūsu ganāmie pulki pa tūkstošiem vedās un pa simts tūkstošiem mūsu laidaros;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Ka mūsu liellopi augļojās, un ka postīšanas, laupīšanas, vaidēšanas nav pa mūsu ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Svētīga tā tauta, kam tā klājās, svētīga tā tauta, kam Tas Kungs ir par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Dāvida teikšana. Es Tevi augsti teikšu, mans Dievs, Tu Ķēniņ, un slavēšu Tavu vārdu mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Ikdienas es Tevi gribu teikt un slavēšu Tavu vārdu mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Tas Kungs ir liels un ļoti slavējams, un Viņa augstība ir neizdibinājama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Bērnu bērni slavēs Tavus darbus un stāstīs Tavu varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Es teikšu Tavas godības augstību un pārdomāšu Tavus brīnuma darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Par Taviem vareniem spēka darbiem runās, un es sludināšu Tavu augstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Tavas lielās lēnības piemiņu teiktin teiks un Tavu taisnību slavēs ar dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Žēlīgs un sirds žēlīgs ir Tas Kungs, pacietīgs un no lielas lēnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Tas Kungs ir labs visiem, un Viņa apžēlošanās parādās pie visiem Viņa darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Visi Tavi darbi, Kungs, Tevi teiks, un Tavi svētie Tevi slavēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Tie izteiks Tavas valstības godību un runās par Tavu varu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Lai cilvēku bērniem Tava vara top zināma un Tavas valstības augstība un godība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Tava valstība ir mūžīga valstība, un Tava valdīšana paliek līdz visiem radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Tas Kungs ir atspaids visiem, kas krīt, un uzceļ visus nospiestos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Visas acis gaida uz Tevi un Tu tiem dod viņu barību savā laikā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Tu atveri Savu roku un pieēdini visus, kas dzīvo, ar labu prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Tas Kungs ir taisns visos Savos ceļos un svēts visos Savos darbos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Tas Kungs ir tuvu visiem, kas Viņu piesauc, visiem, kas Viņu piesauc patiesībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Viņš dara, ko tie grib, kas Viņu bīstas, un klausa viņu kliegšanu un tiem palīdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Tas Kungs pasargā visus, kas Viņu mīļo, un izdeldēs visus bezdievīgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Mana mute runās Tā Kunga slavu un visa miesa teiks Viņa svēto vārdu mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Alleluja! Slavē To Kungu, mana dvēsele.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Es slavēšu To Kungu, kamēr dzīvošu, es dziedāšu savam Dievam, kamēr vēl še būšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Nepaļaujaties uz lieliem kungiem, uz cilvēku bērniem, kas nekā nevar palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Cilvēka garam jāiziet, viņam jāpaliek atkal zemes kārtā, tai dienā visi viņa nodomi iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Svētīgs tas, kam Jēkaba Dievs par palīgu un kam cerība stāv uz To Kungu, savu Dievu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Viņš debesis un zemi radījis, jūru un visu, kas tur iekšā; Viņš uzticību tur mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Viņš tiesu nes tiem, kas varas darbus cieš, dod maizi izsalkušiem. Tas Kungs atsvabina cietumniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Tas Kungs atdara akliem acis, Tas Kungs uzceļ nospiestus; Tas Kungs mīļo taisnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Tas Kungs pasargā svešiniekus un bāriņus un uztur atraitnes, bet bezdievīgiem Viņš ceļus samaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Tas Kungs valdīs mūžīgi, tavs Dievs, ak Ciāna, līdz radu radiem. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Teiciet To Kungu, jo ir labi, mūsu Dievu slavēt; šī teikšana ir mīlīga un pieklājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Tas Kungs uztaisa Jeruzālemi, Viņš sapulcina Israēla ļaudis, kas bija izdzīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Viņš dziedina tos, kam satriektas sirdis, un remdē viņu sāpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Viņš skaita zvaigžņu pulku, Viņš sauc tās visas pa vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Mūsu Kungs ir liels un varens spēkā, Viņa gudrība ir neizmērojama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Tas Kungs paceļ bēdīgos un pazemo bezdievīgos līdz zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Pateiciet Tam Kungam ar slavas dziesmām, teiciet mūsu Dievu ar koklēm!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Viņš debesi apklāj ar mākoņiem, Viņš lietu dod zemei, Viņš liek zālei augt uz kalniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Viņš lopiem dod barību, jauniem kraukļiem, kad tie sauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Viņam nav labs prāts pie zirga stipruma, Viņam nepatīk vīra lieli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Tam Kungam patīk tie, kas Viņu bīstas, kas gaida uz Viņa žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Teici To Kungu, Jeruzāleme, slavē savu Dievu, Ciāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Jo Viņš stiprina tavu vārtu aizšaujamos, Viņš svētī tavus bērnus tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Viņš dod mieru tavām robežām, Viņš tevi paēdina ar briedušiem kviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Viņš sūta Savas apsolīšanas virs zemes, Viņa vārds tek(izplatās) ar steigšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Viņš dod sniegu kā vilnu, Viņš kaisa salnu kā pelnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Viņš met Savu krusu kā kumosus. Kas var pastāvēt priekš Viņa aukstuma?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Viņš sūta Savu vārdu, un kūst, Viņš liek savam vējam pūst, tad ūdeņi notek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Viņš Jēkabam dara zināmu Savu vārdu, Israēlim Savus likumus un tiesas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Tā Viņš nedara nevienai citai tautai; Viņa tiesas tās nepazīst. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Alleluja! Teiciet To Kungu debesīs, teiciet Viņu augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Teiciet Viņu, visi Viņa eņģeļi, teiciet Viņu, visi Viņa karapulki;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Teiciet Viņu, saule un mēnesis, teiciet Viņu visas spožās zvaigznes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Teiciet Viņu, jūs debesu debesis, un jūs ūdeņi, kas ir pār debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Lai tie Tā Kunga vārdu teic, jo kad Viņš pavēlēja, tad tie tapa radīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Viņš tiem liek pastāvēt mūžīgi mūžam, Viņš tiem ir likumu licis, ko tie nevar pārkāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Teiciet To Kungu virs zemes, jūs lielās jūras zivis un visi dziļumi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Uguns un krusa, sniegs un migla, vējš un auka, kas Viņa vārdu izdara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Kalni un visi pakalni, augļu koki un visi ciedru koki,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Meža zvēri un visi lopi, tārpi un spārnainie putni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Jūs ķēniņi virs zemes un visi ļaudis, lieli kungi un visi zemes soģi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Jaunekļi un jaunietes, veci ar jauniem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Tiem būs teikt Tā Kunga vārdu, jo Viņa vārds vien ir augsts, Viņa augstība ir pārāka par zemi un debesi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Un Viņš ir paaugstinājis Savu ļaužu ragu, slavu visiem Saviem svētiem, Israēla bērniem, tiem ļaudīm, kas Viņam tuvu. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Alleluja! Dziediet Tam Kungam jaunu dziesmu, svēto draudze lai Viņu teic.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Israēls lai priecājās iekš sava Radītāja, Ciānas bērni lai līksmojās par savu Ķēniņu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Lai tie Viņa vārdu teic ar stabulēm, lai tie Viņam dzied ar bungām un koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Jo Tam Kungam labs prāts pie Saviem ļaudīm, Viņš pagodina bēdīgos ar pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Svētie priecāsies godā, tie līksmosies savās gultās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Viņu mute paaugstinās Dievu, un viņu rokās būs abējās pusēs griezīgs zobens,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Atriebties pie pagāniem un sodīt tautas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Saistīt viņu ķēniņus ķēdēs un viņu lielkungus dzelzs pinekļos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Darīt tiem pēc tās tiesas, kas ir rakstīta. Tāds gods būs visiem Viņa svētiem. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Alleluja! Teiciet Dievu Viņa svētā vietā, teiciet To Kungu Viņa stiprā izplatījumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Teiciet Dievu par Viņa lielo varu, teiciet To Kungu Viņa lielās augstības pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Teiciet Viņu ar bazūnes skaņu, teiciet Viņu ar stabulēm un koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Teiciet Viņu ar bungām un stabulēm, teiciet Viņu ar stīgām un svilpēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Teiciet Viņu ar skaņiem pulksteņiem, teiciet Viņu ar gavilēšanas pulksteņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Viss, kam ir dvaša, lai slavē To Kungu. Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Salamana, Dāvida dēla, Israēla ķēniņa, sakāmie vārdi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Atzīt gudrību un mācību, un saprast prātīgu valodu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Pieņemties apdomībā, taisnībā, tiesā un skaidrībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Ka tiem vēl nejēgām tiek samaņa, jauniem atzīšana un apdomīgs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Kas gudrs, klausīs un pieaugs mācībā, un kas prātīgs, ņemsies labus padomus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Ka izprot sakāmus vārdus un mīklas, gudro valodas un viņu dziļos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Tā Kunga bijāšana ir atzīšanas iesākums; gudrību un mācību ģeķi nicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Klausi, mans bērns, sava tēva pārmācībai un nepamet savas mātes mācību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Jo tas ir jauks krāšņums tavai galvai un zelta rota tavam kaklam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mans bērns, kad grēcinieki tevi vilina, tad neklausi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Kad tie saka: „Nāc mums līdz, glūnēsim uz asinīm, glūnēsim uz nenoziedzīgo par nepatiesu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Kā elle norīsim viņus dzīvus, un sirds skaidrus kā tādus, kas bedrē grimst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Mēs atradīsim visādas dārgas mantas, pildīsim savus namus ar laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Tava daļa tev būs mūsu starpā, viens pats maks būs mums visiem.“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Mans bērns, nestaigā vienā ceļā ar tiem; sargi savu kāju no viņu pēdām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Jo viņu kājas skrien uz ļaunu un steidzās asinis izliet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Bet lai arī tīklu izplāta visiem putniem priekš acīm; tas ir par velti!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Tā arī viņi glūn uz savām pašu asinīm un glūn uz savu pašu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Tā iet visiem, kas plēš netaisnu mantu; kam šī ir, tam tā paņem dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Dieva gudrība skaņi sauc uz lielceļiem, uz ielām tā paceļ savu balsi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Tā izsaucās, kur ļaužu vislielais troksnis; kur ieiet pilsētas vārtos, tā runā savu valodu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Cik ilgi, nejēgas, jūs mīlēsiet nejēdzību, un smējējiem gribēsies apsmiet, un ģeķi ienīdēs atzīšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Griežaties pie manas mācības! Redzi, es jums došu savu garu un jums darīšu zināmus savus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Tādēļ nu, ka es aicināju, un jūs liedzaties, ka savu roku izstiepju, un nav, kas uzklausa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Un jūs visu manu padomu atmetiet un manas pārmācības negribiet;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Tādēļ arī es smiešos par jūsu postu, es smiešos, kad jums izbailes uzies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Kad pār jums izbailes nāks kā auka, un posts jums uzbruks kā vētra, kad briesmas un bailes jums uzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tad tie mani sauks, bet es neatbildēšu, tie mani meklēs agri, bet mani neatradīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Tādēļ ka tie atzīšanu ienīdējuši un Tā Kunga bijāšanu nav pieņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Tiem negribējās mana padoma, tie ir nicinājuši visu manu pārmācīšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Tādēļ tie ēdīs no sava ceļa augļiem, un būs paēduši no saviem padomiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Jo nesaprašu nomaldīšanās tos nokauj, un ģeķu pārdrošība tos nomaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Bet kas mani klausa, tas dzīvos droši, un savā mierā tas ļauna nebīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mans bērns, ja tu pieņemsi manus vārdus, un sirdī glabāsi manu mācību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Savu ausi griezt uz gudrību un savu sirdi uz atzīšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Tiešām, ja tu atzīšanas lūgsies un savu balsi pacelsi pēc saprašanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Ja tu viņu meklēsi kā sudrabu un tai pakaļ dzīsies kā mantai;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Tad tu sapratīsi Tā Kunga bijāšanu un atradīsi Dieva atzīšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, '(Jo Tas Kungs dod gudrību, no viņa mutes nāk atzīšana un saprašana:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Viņš taisniem paglabā labklāšanos un ir par bruņām tiem, kas bezvainībā staigā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Sargādams taisnības ceļus un pasargādams savu taisno tekas;)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Tad tu atzīsi, kas taisnība un tiesa, un kas skaidrība un ceļš uz visu labu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Ja gudrība nāks tavā sirdī, un atzīšana tavai dvēselei būs mīļa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Tad labs padoms tevi pasargās un saprašana tevi paglabās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Ka tā tevi izglābj no ļauna ceļa, no vīra, kas netiklību runā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Kas atstājuši skaidrības ceļus, staigā pa tumsības ceļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Kas priecājās ļaunu darīt un prieku atrod netiklībā un viltībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Kuru ceļi ir greizi, un kas savās tekās netikli;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Ka tā tevi izglābj no svešas sievas, no svešnieces ar mīkstiem vārdiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Kas atstāj savas jaunības vīru, un aizmirst sava Dieva derību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, '(Jo viņas nams pašķiebjās uz nāvi, un viņas ceļi pie miroņiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Visi, kas pie tās ieiet, negriežas atpakaļ, nedz atrod dzīvības ceļus;)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Ka, lai tu staigā pa labo ceļiem un sargi taisno tekas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Jo taisnie dzīvos zemē, un sirdsskaidrie tur paliks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Bet bezdievīgie no zemes taps izdeldēti, un kas ticību netur, no tās taps izsakņoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mans bērns, neaizmirsti manu mācību, bet lai tava sirds patur manus baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Jo tie tev pieliks daudz dienu un dzīvības gadus un mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Žēlastība un ticība tevi neatstās; sien tos ap savu kaklu un ieraksti tos savas sirds galdiņā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Tad tu atradīsi žēlastību un labprātību Dieva un cilvēku acīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Paļaujies uz To Kungu no visas savas sirds un nepaļaujies uz savu gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Visos savos ceļos ņem Viņu vērā, tad Viņš darīs līdzenas tavas tekas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Neesi gudrs savās acīs; bīsties To Kungu un atkāpies no ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Tās būs tavai miesai zāles, kas dziedina, un atspirgšana taviem kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Godā To Kungu no savas mantas, un no visa sava ienākuma pirmajiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Tad tavi šķūņi pildīsies ar pilnību, un tavi vīna spaidi plūdīs no jauna vīna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Mans bērns, neatmet Tā Kunga pamācīšanu, un lai viņa pārmācīšana tev neriebj;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Jo ko Tas Kungs mīļo, to Viņš pārmāca, kā tēvs dēlu, pie kā tam labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Svētīgs tas cilvēks, kas atradis gudrību, un cilvēks, kam tiek saprašana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Viņu mantot ir labāki nekā sudrabu mantot, un viņu krāt labāki nekā spožu zeltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Viņa ir dārgāka pār pērlēm un viss, ko tu kārotos, tai netiek līdzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Garš mūžs ir viņas labā rokā, un viņas kreisā bagātība un gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Viņas ceļi ir jauki ceļi, un visas viņas tekas ir miers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Viņa ir dzīvības koks tiem, kas viņu tver, un kas viņu cieti tur, tas ir laimīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Tas Kungs ar gudrību licis pamatus zemei, ar saprašanu viņš sataisījis debesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Caur viņa ziņu plūda ūdens plūdi, un padebeši pilēja ar rasu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mans bērns, lai tās neizzūd no tavām acīm, pasargi apdomīgu prātu un samaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Jo tā būs tavas dvēseles dzīvība un glītums tavam kaklam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tad tu savu ceļu staigāsi droši, un tava kāja nepiedauzīsies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Apguldamies tu nebīsies, bet gulēsi, un tavs miegs būs gards.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Tu nebīsies no piepešas izbailes, nedz no bezdievīgo posta, kad tas nāk;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Jo Tas Kungs būs tavs patvērums un pasargās tavu kāju no valgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Neliedzies labu darīt, kam tas nākas, ja Dievs devis, ka tev pie rokas, to darīt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Nesaki uz savu tuvāko: „Ej un nāc, es tev rīt došu!“un tev tomēr ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Neperē ļauna pret savu tuvāko, kad tas tev uzticēdamies pie tevis dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Nebaries par nepatiesu ar cilvēku ja viņš tev ļauna nav darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Neapskaudi varas darītāju un neizraugies sev neviena no viņa ceļiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Jo netiklais Tam Kungam ir negantība, bet viņam ir draudzība ar sirdsskaidriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Tā Kunga lāsti ir bezdievīga namā, bet taisno mājas vietu viņš svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Smējējus tiešām viņš apsmies, bet pazemīgiem dos žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Gudrie iemantos godu, bet ģeķi atradīs kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Klausāties, mani bērni, tēva pamācīšanu un meklējiet atzīšanu mācīties;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Jo es jums dodu labu mācību, neatmetiet manu bauslību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Jo es biju sava tēva dēls, savai mātei luteklītis un vienīgais;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Un viņš mani mācīja un sacīja: Lai tava sirds pieņem manus vārdus, turi manus baušļus, tad tu dzīvosi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Manto gudrību, manto atzīšanu; neaizmirsti un negriezies nost no manas mutes vārdiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Neatstāj to, tad viņa tevi paglābs; mīļo viņu, tad viņa tevi pasargās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Gudrības iesākums ir: Manto gudrību un ar visu savu padomu samanto atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Turi viņu augsti, tad viņa tevi paaugstinās, viņa tevi cels godā, ja tu viņu apkampsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Viņa dos jauku glītumu tavai galvai; krāšņu kroni viņa tev dāvinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Klausies, mans bērns, un pieņem manus vārdus, tad vairosies tavas dzīvības gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Es tev mācīšu gudrības ceļu, es tevi vadīšu uz taisna ceļa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Ka staigājot tavi soļi nemetās, un tekot tu nepiedauzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Turies cieti pie pamācības, neatstājies no tās, sargi to; jo tā ir tava dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Uz bezdievīgo tekas nenāc un uz ļauno ceļa neej!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Stājies no tā, nestaigā uz viņa; raujies no tā un ej garām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Jo tie neaiziet gulēt, pirms nav ļauna darījuši, un tiem nenāk miegs, pirms nav kādu zemē gāzuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Jo tie ēd bezdievības maizi un dzer negantības vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Bet taisno celiņš ir kā spožs gaišums, kas spīd un spīd, līdz diena aust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Bezdievīgo ceļš ir kā akla tumsība; tie nezin, pār ko tie kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Ņem vērā, mans dēls, manus vārdus, griez savu ausi uz manu valodu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Lai tie nezūd no tavām acīm; paglabā tos savā sirds dziļumā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Jo tie ir dzīvība tiem, kas tos atrod, un visai viņu miesai zāles, kas dziedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Pār visu, kas jāsargā, sargi savu sirdi; jo no tās iziet dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Atstādini no sevis netiklu muti, un netaisnas lūpas lai ir tālu no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Lai tavas acis taisni skatās, un tavi acu raugi taisni tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Nosver savu kāju soļus, tad visi tavi ceļi labi izdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Negriezies ne uz labo ne kreiso pusi; sargi savu kāju no ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mans bērns, ņem vērā manu gudrību, griez savu ausi pie manas mācības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Ka tu sargi apdomību, un tavas lūpas glabā atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Jo svešas sievas lūpas pil kā tīrs medus, un viņas mute ir glumāka nekā eļļa;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Bet gals tai ir rūgts kā vērmeles, un ass kā abējās pusēs griezīgs zobens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Viņas kājas nokāpj nāvē, viņas soļi aizsniedz elli;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Lai neapdomā dzīvības ceļus, viņas pēdas grozās, ka nezin kur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Nu tad, bērni, klausiet man un neatkāpjaties no manas mutes vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Lai tavs ceļš paliek tālu no viņas, un nenāc tuvu pie viņas nama durvīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Ka tu nedod svešām savu jaunības spēku un savus gadus tam briesmīgam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Ka sveši nepieēdās no tava spēka, un tavs grūtais pūliņš nenāk svešā namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Un tev pēcgalā nav jānopūšas, kad tava āda un miesa diltin nodilusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Un tev nav jāsaka: „Ak, kā es esmu nīdējis pamācīšanu, un mana sirds smējusies par rāšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Un neesmu klausījis sava pamācītāja balsi, un savu ausi neesmu griezis uz tiem, kas mani mācīja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Tikko nelaimē vēl neesmu visai(dziļi) iestidzis, pašā draudzes un ļaužu vidū!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Dzer ūdeni no savas akas, un tekošu ūdeni no sava avota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Vai tavi avoti lai iztek laukā, un ūdens upes uz ielām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Lai tās tev vien pieder, un nevienam svešam līdz ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Tavs avots lai ir svētīts, un tu priecājies par savas jaunības sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Ak kāda tā mīlīga, kā stirna, un daiļa, kā kalnu kaza! Pie viņas krūtīm pieglaudies allažiņ un ar viņas mīlestību ielīksmojies vienmēr!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Un kādēļ tu, mans bērns, ar citu gribi jaukties un svešas sievietes krūtis apkampt!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Jo cilvēka ceļi stāv priekš Tā Kunga acīm, un Tas sver visus viņa soļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Bezdievīgo gūstīs viņa paša noziegumi, un ar savu grēku saitēm viņš taps saistīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Bez pamācīšanas palicis, viņš nomirs, un savā lielā ģeķībā viņš gāzīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mans bērns, ja tu priekš sava tuvākā galvojis un roku devis priekš cita,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Tad tu esi sasaistīts ar savas mutes valodu un savaldzināts ar savas mutes vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Tad dari jel tā mans bērns, un izglābies, ja tu savam tuvākam rokā esi nācis; ej, meties zemē priekš viņa un spied savu tuvāko;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Nedod savām acīm miega, nedod savām acīm dusas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Izglābies kā stirna no viņa rokas un kā putns no mednieka rokas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Ej pie skudras, sliņķi, skaties viņas ceļus un topi gudrs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Lai tai nav valdnieka, ne virsnieka, ne kunga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Tā tomēr savu maizi sagādā vasarā, savu barību sakrāj pļaujamā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Cik ilgi tu gulēsi, sliņķi? Kad tu celsies no sava miega?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Guli maķenīt, snaudi maķenīt, saliec maķenīt rokas miegā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Tad tava nabadzība tev pienāks nākdama, un tavs trūkums, kā apbruņots vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Nelieša cilvēks ir tāds negants vīrs, kas staigā ar netiklu muti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Met ar acīm, piegrūž ar kājām, zīmē ar pirkstiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Netiklība ir viņa sirdī, viņš domā vienmēr uz ļaunu, saceļ ķildas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Tādēļ viņam nelaime nāks piepeši, viņš ātri taps satriekts un dziedināšanas nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Šās sešas lietas Tas Kungs ienīst, un tā septītā viņam ir negantība:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Lepnas acis, melu mēle un rokas, kas nenoziedzīgas asinis izlej,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Sirds, kas negantus nodomus perē; kājas, kas mudīgas uz ļaunu skriet;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Viltīgs liecinieks, kas droši melus runā, un kas ķildu ceļ starp brāļiem. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mans bērns, glabā sava tēva pamācīšanu un nepamet savas mātes mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Sasien to allažiņ uz savas sirds un sien to ap savu kaklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kad tu staigā, tad tā tevi pavadīs; kad tu apgulies, tad tā tevi apsargās, un kad tu uzmodies, tad tā ar tevi runās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Jo pamācīšana ir spīdeklis, un mācība gaišums, un kad pārmāca un rāj, tas ir dzīvības ceļš;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Ka tās tev izsargā no negodīgas sievas, no svešas sievietes mīkstās mēles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Nekāro savā sirdī pēc viņas skaistuma, un lai viņa tevi nesagūsta ar savām acīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Jo caur mauku tiek līdz maizes drupekļiem, un vīra sieva tev notvers pat dārgo dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Vai arī uguni var klēpī ņemt, un drēbes nesadegtu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Vai uz kvēlošām oglēm var iet un nesadedzinātu kājas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tāpat, kas ieiet pie otra sievas; nesodīts nepaliks, kas to aizskar.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Zaglim nepiedod vis, ka zog izsalcis, vēderu pildīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Bet pieķerts tas septiņkārt atlīdzinās, visu sava nama padomu tas atdos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Kas ar sievu laulību pārkāpj, tam prāta nav; to tik dara, kas sev dzīvību grib nogalināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Tam būs kāviens un kauns un negods bez gala;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Jo viņas vīra dusmas iekarsušās netaupīs atriebšanas laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Tas nebēdās ne par kādu līdzību(izpirkumu), un nebūs miera, cik dāvanu arī nedotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mans bērns, sargi manus vārdus un glabā pie sevis manu mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Sargi manu pamācīšanu, tad tu dzīvosi, un manu mācību kā savu acu raugu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Sien to ap saviem pirkstiem, ieraksti to savas sirds galdiņā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Saki uz gudrību: Tu esi mana māsa! un atzīšanu sauc par savu radinieci,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Ka tu sevi pasargi no svešas sievas, no svešinieces ar mīkstiem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Jo es skatījos pa sava nama logu, caur saviem skadriņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Un redzēju nejēgu vidū un ieraudzīju starp zēniem neprātīgu jaunekli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Tas gāja pa ielu ap nama stūri, staigāja pa viņas nama ceļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Pavakarē, krēslā, nakts vidū un tumsā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Un redzi, viņu sastapa sieva, maukas apģērbā un viltu sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Šī bija trakule un palaidne, viņas kājas nemetās mājā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Te viņa ārā, te uz ielām un glūn aiz visiem stūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Un tā viņu apkampa un skūpstīja kā bezkauņa un uz to sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '„Pateicības upuri man bija jānes; šodien es savu solījumu esmu pildījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Tādēļ esmu izgājusi tev pretī, tavu vaigu meklēt un tevi esmu atradusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Ar apsegiem esmu klājusi savu gultu, ar strīpainiem Ēģiptes palagiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Savu gultu esmu izkvēpinājusi ar mirrēm, alvejām un kanēli;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Nāc, lai izbaudām kārības līdz rītam, lai izpriecājamies mīlestībā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Jo vīrs nav mājās, viņš aizgājis tālā ceļā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Viņš naudas maku ņēmis līdz, tik uz svētkiem vēl pārnāks mājās.“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Viņa to pierunāja ar savu vārdu drūzmu, ar savu mīksto mēli tā viņu aizrāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Uz reizi tas viņai gāja pakaļ, kā vērsis iet pie kaušanas un kā nelietis, saistīts uz sodu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Kamēr bulta viņa aknas pāršķeļ; tā putns skrien sprostā un nezin, ka tas pret viņa dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Nu tad, bērni, klausiet mani, un ņemiet vērā manas mutes vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Lai tava sirds nenomaldās uz viņas ceļiem un nenoklīsti uz viņas gaitām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Jo daudz ir to nokauto, ko tā gāzusi zemē, un liels pulks, ko viņa nogalinājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Viņas nams ir ceļi uz elli, kas novada nāves kambaros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Vai gudrība nesauc, un atzīšana nepaceļ savu balsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Kalnu virsgalā tā stāv, ceļmalā uz ceļu jūtīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Pie vārtiem pilsētas priekšā, kur pa vārtiem ieiet, viņa skaņi sauc:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '„Uz jums, vīri, es saucu, un mana balss iet pie cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Ņemiet vērā, nejēgas, gudrību, un, ģeķi, paliekat prātīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Klausāties, jo es runāšu augstas lietas un atdarīšu savu muti ar skaidriem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Jo mana mute runās patiesību, un bezdievība manām lūpām ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Visi manas mutes vārdi stāv taisnībā, iekš tiem nav netiklības, nedz viltības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Tie ir visnotaļ taisni tam, kas tos saprot un skaidri tiem, kas atzīšanu atraduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Pieņemiet manu mācību labāki nekā sudrabu, un atzīšanu vairāk nekā tīru zeltu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Jo gudrība ir labāka pār pērlēm, un viss, ko tu kārotu, tai netiek līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Es, tā gudrība, mītu pie samaņas un atrodu vērtīgu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Tā Kunga bijāšana ir: ienīdēt ļaunu, lepnību, augstprātību un ļaunu ceļu, un es ienīstu netiklu muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Pie manis ir padoms un palīgs; es esmu atzīšana, man ir spēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Caur mani valda ķēniņi, un dod taisnus likumus valdītāji;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Caur mani valda varenie un lielkungi, visi zemes soģi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Es mīlēju tos, kas mani mīl, un kas mani tikuši(centīgi) meklē, tie mani atrod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Bagātība un gods ir pie manis, paliekama manta un taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mani augļi ir labāki nekā zelts un tīrs zelts, un mans ienākums nekā šķīsts sudrabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Es vadu uz taisnības ceļa, taisnas tiesas pēdās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Ka tiem, kas mani mīl, dodu iemantot pilnību un pildu viņu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Tas Kungs mani nolika par sava ceļa iesākumu, par savu radījumu pirmaju no mūžības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'No mūžības es esmu iecelta, no iesākuma, no pasaules gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Kad dziļumi vēl nebija, tad es piedzimu, kad avoti vēl nebija, no ūdeņiem grūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Pirms kalnu pamati tapa nolikti, priekš pakalniem, tad es piedzimu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Viņš vēl nebija radījis zemi nedz klajumus, nedz sācis pasaules pīšļus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Kad viņš debesis sataisīja, tad es tur biju; kad viņš izplatīja debess velvi pār dziļumiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Kad viņš padebešus augšām nostiprināja, kad dziļumu avoti krākdami krāca,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Kad viņš jūrai lika robežas, ka ūdeņi neplūstu pār viņas malām, kad viņš nostiprināja zemes pamatus:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Tad es biju pie viņa tā izdarītāja un biju viņa prieks dienu dienas un līksmojos viņa priekšā vienmēr:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Es līksmojos viņa pasaules virsū un mans prieks ir pie cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Tad klausiet nu mani, mani bērni; jo svētīgs, kas manus ceļus sargā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Klausiet pamācīšanai un topiet gudri, un neatmetat viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Svētīgs tas cilvēks, kas mani klausa, kas kavējās pie manām durvīm dienu no dienas, sargāt manu durvju stenderus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Jo kas mani atrod, tas atrod dzīvību un dabūs žēlastību no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Bet kas pret mani grēko, tas dara varu savai dvēselei; kas mani ienīst, tie visi līdz mīļo nāvi.“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Dieva gudrība ir uztaisījusi savu namu, viņa uzcirtusi savus septiņus pīlārus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Viņa nokāvusi savus kaujamos, jaukusi savu vīnu, ir jau klājusi savu galdu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Viņa izsūtījusi savas kalpones; viņa sauc no pilsētas augstākām vietām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '„Kas nejēga, lai griežas šurp!“kas neprātīgs, uz to viņa saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '„Nāciet, ēdiet no manas maizes, un dzeriet no vīna, ko esmu jaukusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Atstājiet nejēdzību, tad dzīvosiet, un staigājiet pa atzīšanas ceļu!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Kas smējēju pamāca, tas dabūs kaunu, un kas bezdievīgo pārmāca, apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Nepamāci smējēju, ka viņš tevi neienīst; pamāci prātīgo, tas tevi mīlēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Dod prātīgam, tad viņš tiks jo prātīgs, māci taisnu, tad viņš pieaugs mācībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Tā Kunga bijāšana ir gudrības iesākums, un izprast, kas svēts, tā ir atzīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Jo caur mani taps daudz tavu dienu un vairosies tev dzīvības gadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Ja tu gudrs, tad tu sev gudrs; ja tu smējējs, tad tu viens pats to nesīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Nejēdzība ir sieva tītīga, ģeķīga, kas neatjēdz nenieka');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Tā sēž sava nama durvīs uz goda krēsla pilsētas augstās vietās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Aicināt tos, kas iet garām pa ceļu, kas staigā savās taisnās tekās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Kas nejēga, lai griežas šurp! Un kas neprātīgs, uz to viņa saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '„Zagts ūdens ir salds, un slēpta maize garda!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Bet tas nemana, ka tur miroņi, un elles dziļumos viņas viesi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Salamana sakāmie vārdi. Gudrs dēls ir tēva prieks, bet ģeķīgs mātes sirdēsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Netaisnas mantas nelīdz nenieka, bet taisnība izpestī no nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Tas Kungs taisnai dvēselei neliek bada ciest; bet bezdievīga negausību viņš izšķiež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Kas slinku roku strādā, top nabags; bet čakla roka dara bagātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kas vasarā sakrāj, ir prātīgs; bet kas pļaujamā laikā guļ, paliek kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Svētība pār taisna galvu, bet bēdas aizbāzīs bezdievīgiem muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Taisnam piemiņa paliek svētīta, bet bezdievīgiem slava iznīks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Kam gudra sirds, tas pieņem mācību, bet kas muti palaiž, ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kas skaidrībā staigā, tas staigā ar mieru; bet kas savus ceļus groza, to pienāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kas ar acīm met, tas pieved bēdas; un kas muti palaiž, ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Taisnam mute ir dzīvības avots; bet bēdas aizbāzīs bezdievīgiem muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Ienaids ceļ bāršanos; bet mīlestība apklāj visus pārkāpumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Uz prātīga lūpām rodas gudrība, bet pār ģeķa muguru nāk rīkste.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Prātīgie pietur savu padomu, bet ģeķu mute ir briesmas tuvumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Bagātam manta ir viņa stiprā pils, bet tukšinieku briesmas ir viņu nabadzība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Taisna krājumiņš ir uz dzīvību, bet bezdievīga ienākums uz grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Pārmācīšanu pieņemt ir ceļš uz dzīvību, bet kas par mācību nebēdā, tas maldās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Viltīgas lūpas slēpj ienaidu, un kas niknu slavu ceļ, ir nelga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Vārdu pulkā netrūkst grēku, bet kas savas lūpas valda, ir gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Taisnam mēle ir tīrs sudrabs, bezdievīgā sirds neder nekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Taisna lūpas daudziem ganība, bet ģeķi nomirs savā sirds ģeķībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Tā Kunga svētība dara bagātu, un rūpes tur nekā nepieliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Ģeķim prieks, blēņas darīt, bet prātīgam vīram gudrība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'No kā bezdievīgais bīstas, tas viņam uziet, un ko taisnie vēlās, to Viņš tiem dod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Tā kā vētra pārskrien, tāpat bezdievīgā vairs nebūs, bet taisnais pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Kā skābums zobiem un dūmi acīm, tā sliņķis tiem, kas to sūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Tā Kunga bijāšana vairo dienas, bet bezdievīgo gadi top paīsināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Ko taisnie gaida, būs līksmība, bet bezdievīgo cerība zudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Tā Kunga ceļš sirdsskaidriem ir par stiprumu, bet ļauna darītājiem par izbailēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Taisnais nešaubīsies ne mūžam, bet bezdievīgie nepaliks zemes virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'No taisnā mutes zaļo gudrība, bet netikla mēle taps izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Taisnā lūpas zin, kas pieklājās, bet bezdievīgo mute ir netikla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Viltīgs svars Tam Kungam ir negantība, bet pilnīgs svara akmens Viņam patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kur nāk lepnība, tur arī nāk kauns, bet pie pazemīgiem ir gudrība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Taisno sirdsskaidrība tos vada, bet neliešu netiklība tos posta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Manta nepalīdz atriebšanas dienā, bet taisnība izpestī no nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Skaidram taisnība līdzina ceļu, bet bezdievīgais kritīs caur savu bezdievību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Taisno taisnība tos izglābs, bet nebēdnieki savaldzināsies savā kārībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Kad bezdievīgs cilvēks mirst, tad viņa cerība iznīkst, un netaisno gaidīšana ir pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Taisnais tiek izglābts no bēdām, un bezdievīgais nāk viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Blēdis savu tuvāko bendē ar muti, bet taisnie, to manot, paglābjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Kad taisnam labi klājās, tad pilsēta priecājās, un gavilē, kad bezdievīgais iet postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Caur taisna svētību pilsēta ceļas, bet caur bezdievīga muti tā top nopostīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Kas savu tuvāko nicina, tam nav saprašanas; bet gudrs vīrs cieš klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Mēlnesis apkārt lienot izmuld, kas slēpjams; bet kam uzticīgs prāts, tas to apklāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Kur vadīšanas nav, tur ļaudis nīkst; bet kur padoma devēju papilnam, tur labi izdodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Kas par svešu galvo, tam būs bēdu gan; bet kas galvošanu ienīst, tas paliek mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Mīlīga sieva panāk godu, tā kā varenie panāk bagātību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Žēlīgs vīrs savai paša dvēselei dara labu, bet niknais savai paša miesai dara grūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Bezdievīgais pelnās tukšu algu, bet kas taisnību sēj, tam alga pastāvīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Kā taisnība ir uz dzīvību, tā ļaunam pakaļ dzīties ir uz nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Kam netikla sirds, tas Tam Kungam ir negantība; bet kam skaidrs ceļš, tas Viņam patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Uz radu radiem paliek blēža vaina; bet taisno dzimums taps izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Skaista sieva, kas goda neprot, ir zelta gredzens cūkas purnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Ko taisnie vēlās, ir visnotaļ labums; bet bezdievīgo cerība ir pārgalvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Cits izkaisa, un tam vēl krājās; un cits taupa pārlieku, bet tik uz trūcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Tā dvēsele, kas svētī, tiks trekna, un kas dzirdina, tas atkal taps dzirdināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kas aiztur labību, to ļaudis lād, bet svētība būs pār pārdevēja galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kas dzenās pēc laba, tas ir patīkams, bet kas meklē ļaunu, tam tas arī nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kas uz savu bagātību palaižās, tas iznīks, bet taisnie zaļos kā lapas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kas savu namu pilda ar nemieru, tas mantos vēju, un ģeķis būs par kalpu tam, kam ir gudra sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Taisna auglis ir dzīvības koks, un gudrais manto sirdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Redzi, taisnam virs zemes top atmaksāts, cik vairāk vēl bezdievīgam un grēciniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kas labprāt panes pārmācīšanu, tas mīļo atzīšanu, bet kas nepanes rājienu, tas paliek muļķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Kas labs, tas Tam Kungam patīkams, bet vīru, kas viltu perē viņš pazudina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Cilvēks nepastāvēs, kad ir bezdievīgs, bet taisno sakne netaps kustināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Tikla sieva ir sava vīra kronis, bet netikla ir kā puve viņa kaulos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Taisno domas ir tiesa, bet bezdievīgo padomi viltība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Bezdievīgo vārdi glūn uz asinīm; bet taisno mute tos izpestī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Bezdievīgie top iznīcināti, ka to vairs nav; bet taisno nams pastāvēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Kā kuram saprašana, tā viņam slava; bet par apsmieklu būs, kam netikla sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Labāks tas zemais, kas sev pašam par kalpu, nekā kas lepojās, un maizes nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Taisnais gādā par sava lopa dzīvību, bet bezdievīgo sirds ir nežēlīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kas savu zemi kopj, būs maizes paēdis, bet kas niekus triec, tam nav jēgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Bezdievīgais traucās pēc blēžu medījuma; bet taisno sakne nes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Ļaunais savaldzinājās savas mutes grēkos; bet taisnais izies no bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Pēc savas mutes augļiem ikviens top pieēdināts ar labumu, un cilvēkam top maksāts pēc viņa roku darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Ģeķa ceļš ir taisns paša acīs, bet kas padomam klausa, tas ir gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Ģeķa apskaišanās tūdaļ top zināma; bet kas slēpj, ka ir apkaunots, tas ir gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kas patiesību runā, tas saka taisnību; bet nepatiess liecinieks teic melus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Dažs aplam runājot kā ar zobenu iedur; bet gudro mēle ir zāles, kas dziedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Patiesa mute pastāvēs mūžīgi, bet viltīga mēle tik acumirkli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Viltība ir sirdī tiem, kas ļaunu perē; bet kas dod miera padomu, dara prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Taisnam nekāds ļaunums nenotiks, bet bezdievīgiem ļaunuma uzies papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Viltīgas lūpas Tam Kungam ir negantība; bet kas uzticību dara, tas viņam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Gudrs cilvēks neizteic savu padomu; bet nejēgu sirds izkliedz ģeķību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Čakla roka valdīs, bet slinka dos meslus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Raizes sirdī nospiež cilvēku, bet labs vārds to iepriecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Taisnais savam tuvākam rāda ceļu, bet bezdievīgo ceļš maldina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Sliņķis neceps savu medījumu, bet uzcītīgam cilvēkam ir skaista manta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Uz taisnības ceļa ir dzīvība, un uz viņas ceļa tekām nav nāve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Gudrs dēls klausa tēva pārmācīšanai, bet mēdītājs neklausa rāšanai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Ikviens baudīs labumu no savas mutes augļiem, bet netiklo prieks ir mokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kas sarga savu muti, tas pasargā savu dvēseli; bet kas muti palaiž, tam briesmīgi klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Sliņķa dvēsele iekāro, - bet nekā; bet čaklo dvēsele dabū papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Taisnais ienīst melu valodu, bet bezdievīgais paliek kaunā un apsmieklā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Taisnība pasargā to, kas bezvainīgs savā ceļā, bet bezdievība gāž grēkos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Cits lielās, ka bagāts, kam nav it nenieka, un cits turas kā nabags, un tam liela manta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Bagātam, kad apvainojies, par dvēseli jāmaksā; bet kas nabags, tas nedzird draudus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Taisno gaišums spīdēs priecīgi, bet bezdievīgo spīdeklis apdzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Caur lepnību nāk riešana vien, bet gudrība dara apdomīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Manta vēja grābeklim iet mazumā, bet kas rokā sakrāj, tas to vairo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Cerība, kas kavējās, grauž sirdi, bet kad nāk, ko gaida, tas ir dzīvības koks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Kas par vārdu nebēdā; tas dara sev postu; bet kas mācību tur godā, tam labi klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Gudra vīra mācība ir dzīvības avots, izsargāties no nāves valgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Mīlīgs prāts dara patīkamu, bet netikļa ceļš dara sāpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Gudrais (savu darbu) dara apdomīgi, bet ģeķis dara aklus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Bezdievīgs kalps iekritīs nelaimē, bet uzticams kalps ir zāles, kas dziedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Kas par mācību nebēdā, tam nāk tukšība un kauns; bet kas pamācīšanu pieņem, tas kļūs godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Kad notiek, ko cerē, tas dvēselei gards; bet atstāties no ļauna ģeķiem ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kas draudzējās ar gudriem, tas taps gudrs; bet kas ģeķiem biedrs, tiks postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Nelaime dzīsies grēciniekiem pakaļ, bet taisniem ar labu tiks atmaksāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Kas ir labs, tā manta nāk uz bērnu bērniem; bet grēcinieka krājums taisnam top pataupīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Daudz maizes ir nabagu vagās, bet citi iet postā caur savu netaisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kas rīksti taupa, tas ienīst savu dēlu; bet kas viņu mīļo, tas to pārmāca drīz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Taisnais ēd, kamēr viņa dvēselei gan; bet bezdievīgo vēders paliek tukšs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Gudra sieva uztaisa savu namu, bet neprātniece to noposta pati savām rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kas savā skaidrībā staigā, tas bīstas To Kungu; bet netiklais savā ceļā nebēdā par Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Ģeķa mutē ir viņa lepnības rīkste, bet gudro lūpas viņus pasargā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Kur vēršu nav, tur sile tīra; bet caur vēršu spēku nāk liela raža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Patiess liecinieks nemelo, bet nepatiess liecinieks izverd melus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Garzobis meklē gudrību un neatrod; bet prātīgam atzīšana nāk lēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Ej nost no ģeķa acīm; jo gudru valodu tu nedzirdēsi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Prātīga vīra gudrība ir šī, savu ceļu saprast; bet nejēgu ģeķība ir aloties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Ģeķiem grēku upuris nelīdz, bet pie taisniem ir labpatikšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Sirds pati vien zina savas sāpes, un cits neviens nenomana viņas prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Bezdievīgo nams taps nopostīts, bet taisno būdiņa zaļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Dažs ceļš liekās iesākumā labs, savā galā ved nāvē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Pat smejoties sirds brīžam sāp, un līksmība beidzās bēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Kas atkāpjas, tā sirds baudīs savu darbu augļus, tāpat labs vīrs savus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Nejēga tic visu, bet prātīgais ņem vērā savus soļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Gudrais bīstas un izsargās no ļauna, bet ģeķis ir kā uguns un drošs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Ātras dusmas dara ģeķību, un niķainu cilvēku ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Nesaprašu mantība ir ģeķība, bet prātīgo kronis atzīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Ļauniem jāklanās priekš labiem, un bezdievīgiem taisna vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Pat draugs nabagu ienīst, bet bagātiem mīlētāju daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Kas pulgo savu tuvāko, grēko; bet svētīgs, kas par nabagu apžēlojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Vai tad neceļā nekļūs, kas ļaunu perē? bet kam prāts uz labu, panāks žēlastību un uzticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Kur sviedriem strādā, tur kas atliek; bet kur vārdi vien, tur trūcība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Bagātība ir gudriem par kroni, bet nejēgu ģeķība paliek ģeķība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Patiess liecinieks izpestī dvēseles, bet kas melus runā, ir blēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Tā Kunga bijāšanā ir liela drošība, un tā būs viņa bērniem par patvērumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Tā Kunga bijāšana ir dzīvības avots, izsargāties no nāves valgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Ķēniņa gods stāv ļaužu pulkā, bet ļaužu trūkums ir valdnieku vaidi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Lēnprātīgam liela gudrība, bet ātrais ir liels ģeķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Lēna sirds ir miesas dzīvība, bet ātrs prāts ir puveši kaulos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kas nabagu nospiež, pulgo viņa Radītāju; bet kas par sērdieni apžēlojās, tas godā Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Bezdievīgais pazūd savā postā, bet taisnais arī savā nāvē ir drošs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Prātīgo sirdī gudrība dus, bet ģeķu starpā tā parādās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Taisnība tautu paaugstina, bet grēks ir ļaužu posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Tiklam kalpam ķēniņa žēlastība, bet viņa dusmas bezkaunīgam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Lēna atbilde klusina bardzību, bet rūgta valoda ceļ dusmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Gudra mēle dara mācību mīlīgu, bet ģeķu mute izverd ģeķību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Tā Kunga acis ir visās malās un ņem vērā ļaunus un labus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Mēle, kas mierina, ir dzīvības koks, bet netikla lauž sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Ģeķis smejas par sava tēva pamācīšanu, bet kas mācību pieņem, pieaugs gudrībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Taisna namā ir liela svētība, bet pie bezdievīga ienākuma posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Gudro lūpas sēj atzīšanu, bet ģeķu sirds tāda vis nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Bezdievīgo upuris Tam Kungam ir negantība, bet taisno lūgšana viņam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Bezdievīga ceļš Tam Kungam ir negantība, bet kas pēc taisnības dzenās, to viņš mīl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Grūta pārmācīšana būs tam, kas no ceļa atstājās; kas pamācīšanu ienīst, tas nomirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Elle un viņas bezdibenis ir Tā Kunga priekšā, vai tad ne jo vairāk cilvēku bērnu sirdis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Mēdītājs nemīl to, kas viņu pamāca, viņš nemetās pie gudriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Priecīga sirds dara vaigu priecīgu, bet sirdēsti nospiež garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Prātīga vīra sirds meklē atzīšanu, bet ģeķu vaigs ganās ģeķībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Bēdīga cilvēka dienas ir visas līdz ļaunas, bet priecīgai sirdij ir dzīres bez mitēšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Labāk ir mazumiņš ar Tā Kunga bijāšanu, nekā liela manta, kur raizes klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Kāpostu virums ar mīlestību ir labāks, nekā barots vērsis ar naidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Sirdīgs(dusmīgs) vīrs ceļ ķildu, bet lēnprātīgais klusina bāršanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Sliņķa ceļš ir kā ērkšķu krūms, bet taisno tekas ir līdzenas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Gudrs dēls iepriecina tēvu, bet ģeķīgs cilvēks pulgo savu māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Ģeķība neprātīgiem ir prieks, bet prātīgs vīrs staigā pareizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Kur padoma nav, tur nodoms netiek galā, bet caur daudz padoma devējiem tas izdodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Vīrs priecājās par savas mutes atbildi, un vārds īstenā laikā, cik tas labs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Gudram dzīvības ceļš iet uz augšu, lai izbēg no elles apakšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Lepniem Tas Kungs namu noposta, bet uztaisa atraitnes ežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Ļauna vīra nodomi Tam Kungam ir negantība, bet laipnīga valoda šķīsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Rautin raujot cilvēks izposta savu namu, bet kas kukuļus ienīst, tas dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Taisna sirds apdomā, ko atbildēt, bet bezdievīgo mute izverd ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Tas Kungs ir tālu no bezdievīgiem, bet taisno lūgšanu viņš paklausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Spožas acis iepriecina sirdi; laba vēsts stiprina kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Auss, kas klausa dzīvības mācībai, mājos gudro vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kas mācību atmet, tas zaudē dvēseli; bet kas mācībai klausa, ņemas gudrībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Tā Kunga bijāšana ir pamācīšana uz gudrību, un pazemība ved godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Cilvēks sirdī gan apņemas, bet no Tā Kunga nāk, ko mēle runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Cilvēka ceļi visi ikkatram savās acīs šķīsti; bet Tas Kungs pārbauda sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Pavēli savus darbus Tam Kungam, tad tavi nodomi pareizi izdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Tas Kungs visu ir darījis pēc savas ziņas, arī bezdievīgo uz ļauno dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Ikviens, kam lepna sirds, Tam Kungam ir negantība, tiešām tiesa, tas nesodīts nepaliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Caur žēlastību un ticību noziegumi top salīdzināti, un caur Tā Kunga bijāšanu cilvēks izsargās no ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Kad cilvēka ceļi Tam Kungam patīk, tad tas pat viņa ienaidniekus ar to salīdzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Labāk ir mazumiņš ar taisnību, nekā liels ienākums ar netaisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Cilvēka sirds nodomā savu ceļu, bet Tas Kungs pašķir viņa gājumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Dieva padoms ir uz ķēniņa lūpām; viņa mutei neviļās tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Taisni svari un svara kausi ir no Tā Kunga, un visi svara akmeņi maisā viņa darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Bezdievību darīt ķēniņiem ir negantība; jo caur taisnību goda krēsls top stiprināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Taisnas lūpas ķēniņiem labi patīk; un kas patiesību runā, to tie mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Ķēniņa dusmas ir nāves vēsts, bet gudrs vīrs tās remdē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Ķēniņa vaiga spīdumā ir dzīvība, un viņa laipnība kā vēlais lietus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Gudrību iemantot, cik daudz labāki tas ir pār zeltu, un saprašanā ņemties sver vairāk nekā sudrabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Taisna ceļš ir izsargāties no ļauna, kas savu ceļu sargā, tas pasargā savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Lepojies un tu iesi postā; lielies un tu kritīsi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Labāki ir pazemīgam būt ar pazemīgiem, nekā laupījumu dalīt ar lepniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Kas gudrs visās lietās, atrod labumu; un svētīgs, kas uz To Kungu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Kam samanīga sirds, to sauc par gudru, un mīlīgas lūpas vairo atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Saprašana ir dzīvs avots tam, kam tā ir; bet ģeķu pamācīšana paliek ģeķība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Gudra sirds māca savu muti un vairo uz savām lūpām atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Laipnīga valoda ir tīrs medus, dvēselei salda un kauliem zāles, kas dziedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Dažs ceļš liekās iesākumā labs, bet savā galā ved nāvē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Kas (citu) apgrūtina, apgrūtina sev pašu; jo tāds savu muti atdara pret sev pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Nelietis saceļ nelaimi, un uz viņa lūpām ir kā degots uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Netikls cilvēks ceļ ķildas, un lišķis sarīdina radus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Kas savu tuvāko kārdina un viņu noved uz nelabu ceļu, tas padara varas darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Kas ar acīm met, tas nodomā blēņas; kas lūpas sakož, tas gatavs uz ļaunu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Sirmi mati ir goda kronis; uz taisnības ceļa to atrod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Lēnprātīgais ir labāks nekā stiprais; un kas sevi pašu valda, labāks nekā, kas pilsētu ieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Meslus met klēpī, bet Tas Kungs ir tas nolēmējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Sauss kumoss ar mieru ir labāks, nekā pilns nams ar kaujamiem, kur ķildas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Gudrs kalps valdīs pār netiklu dēlu un dalīs mantojumu starp brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Kausējamais katls sudrabu, un ceplis zeltu, bet Tas Kungs pārbauda sirdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Netiklis klausās uz blēņu valodām, melkulis griež ausi uz neliešu mēlēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kas nabagu apsmej, tas nievā viņa Radītāju, un kas par viņa bēdām priecājās, nepaliks nesodīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Sirmgalvju kronis ir bērnu bērni, un bērnu goda rota ir viņu tēvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Ģeķiem nepieder augsti vārdi, nedz lielam kungam melot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Kam ir ko dot, tam tas ir kā dārgs akmens; kur tik tas griežas, tur labi izdodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kas grēku apklāj, tas iekopj draudzību; bet kas vainu no jauna aizņem, sarīdina radus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Aprāšana vairāk satriec prātīgo, nekā simts sitienu ģeķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Dumpinieks meklē tik ļaunu vien, bet bargs vēstnesis pret viņu taps sūtīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Labāki lāču māti sastapt, kurai bērni paņemti, nekā ģeķi viņa ģeķībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kas labu ar ļaunu atmaksā, no tā nama ļaunums neatstāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Ķildu sākt ir kā ūdens dambi izplēst; pirms sāk jaukties, atstājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kas bezdievīgu taisno un taisnu pazudina, tie abi Tam Kungam ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Ko palīdz ģeķim maksa rokā, gudrību pirkt, kad jēgas nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Draugs mīļo ikkatrā laikā, bet brālis piedzen bēdu dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Tas ir negudrs, kas roku dod galvodams priekš sava tuvākā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kas ķildu mīļo, tas mīļo grēku; un kas savas durvis taisa augstas, tas meklē nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Kam nelieša sirds, tas laba neatradīs; un kam netikla mēle, tas iekritīs nelaimē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kas ģeķi dzemdina, tam tas būs par skumjām, un ģeķa tēvs nevar priecāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Priecīga sirds dziedina vainas, bet sagrauzts gars izkaltē kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Bezdievīgais ņem slepeni dāvanas, locīt taisnības ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Prātīga cilvēka vaigā ir gudrība, bet ģeķa acis laistās līdz pasaules galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Ģeķīgs dēls savam tēvam par sirdēstiem, un rūgtums tai, kas viņu dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Jau nav labi, taisno sodīt, ne vēl goda vīru sist taisnības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Kas savu muti valda, tam ir samaņa, un kam lēns gars, tas ir prāta vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Pat ģeķi, kad tik klusu cieš, notur par gudru, un par prāta vīru, kamēr savu muti tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Kas ar citiem kopā neturas, tas savu gribu tik meklē, un ir kavēklis visās lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Ģeķim netīk gudra valoda, bet tik vien atklāt savu paša sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Bezdievīgam staigā līdz negods un ar apsmieklu kauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Vārdi cilvēka mutē ir dziļš ūdens, un gudrības avots ir tekoša ūdens upīte.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Nav labi bezdievīga vaigu cienīt un nospiest taisno tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Ģeķa lūpas ieved ķildā, un viņa mute brēc pēc sitieniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Ģeķa mute sev pašai par postu, un viņa lūpas paša dvēselei par slazda valgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Lišķa vārdi ir kā saldi kumosi un iet visai pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Kas laisks pie darba, tas palaidņa brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Tā Kunga vārds ir stipra pils; tur taisnais glābjas un top izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Bagātam manta ir viņa stiprā pils un viņam šķiet augsts mūris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Priekš bojāiešanas cilvēka sirds top lepna, bet pazemība ved godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kas atbild, pirms dzirdējis, tas tam par ģeķību un kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Vīra gars panes savas bēdas, bet kad gars izmisis, kas to var panest?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Prātīga sirds iemanto atzīšanu, un gudra auss meklē atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Dāvanas cilvēkam līdzina ceļu un viņu ved kungu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Kas pirmais sūdz, tam taisnība; kad nu nāk viņa pretinieks, tad to tirda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Mesli nobeidz ķildas un izšķir varenos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Apkaitināts brālis ir cietāks nekā stipra pils, un ķilda nekā pils vārtu aizšaujamais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'No mutes augļiem ikkatrs savu vēderu pildīs, un viņa lūpu padoms to ēdinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Nāve un dzīvība stāv mēles galā; kā kurš runā, tā tam būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kas sievu atradis, tas atradis labumu un mantojis žēlastību no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Nabags runā lūgdamies, bet bagāts atbild bargi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Citam daudz draugu uz postu; bet ir draugi, kas labāki nekā brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Nabags savā vientiesībā staigādams ir labāks, nekā ģeķis ar netiklu muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Arī pārsteigšanās bez ziņas nav laba, un ātri skrejot klūp.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Ģeķība cilvēkam sajauc ceļus, ka viņa sirds kurn pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Manta pieved daudz draugu, bet nabagu draugs atstāj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Nepatiess liecinieks nesodīts nepaliks, un kas melus runā, neizglābsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Augstam kungam daudz pieglaužas, un ikkatrs ir devīgam vīram draugs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Nabagu ienīst visi viņa brāļi, cik vairāk viņa draugi no viņa atraujas; meklē tos pirmos vārdus, to nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Kas gudrību panāk, mīl savu dvēseli; kas ar prātu dzīvo, atrod labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Nepatiess liecinieks nesodīts nepaliks, un kas droši melus runā, aizies postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Ģeķim nepieder kārumā dzīvot, ne vēl kalpam pār kungiem valdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Prātīgs cilvēks ir lēns uz dusmām, un viņa rota ir, kaitināšanu aizmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Ķēniņa dusmība ir kā jauna lauvas rūkšana; bet Viņa žēlastība kā rasa uz zāles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Ģeķīgs dēls ir tēvam par sirdēstiem, un sievas riešana ir pilēšana bez gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Namu un mantu manto no vecākiem, bet prātīgu sievu no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Slinkums iemidzina miegā, un kūtra dvēsele cietīs badu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kas mācību sargā, tas sargā savu dvēseli; kas savu ceļu neņem vērā, tas mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kas par nabagu apžēlojās, tas aizdod Tam Kungam, un tas tam atmaksās viņa labdarīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Pārmāci savu dēlu, kamēr vēl cerība, bet nedod savai dvēselei vaļas, viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Kam liela sirds, tam jācieš sods; jo gribi novērst, jo iet vairumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Klausi padomam un pieņem mācību, ka tu pēcgalā palieci gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Cilvēka sirdī ir daudz nodomu, bet Tā Kunga padoms, tas pastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Cilvēka gods ir labu darīt, un nabags ir labāks, nekā melkulis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Tā Kunga bijāšana ir uz dzīvību; jo tāds būs paēdis un dzīvos, ļauna neaizskarts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Sliņķis slēpj roku azotē, pat pie mutes viņš to neliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Per garzobi, tad tas nejēga atjēgs, un pamāci prātīgo, tad viņš atzīs, kas der.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Kas tēvu posta un māti izdzen, tas ir bezkaunīgs un negants bērns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Neklausi, mans bērns, mācībai, kas nomaldina no gudrības vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Nelieša liecinieks apsmej tiesu, un bezdievīgo mute ierij netaisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Garzobiem sodība gatava un pēriens ģeķu mugurai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Vīns ir zobgalis, stiprs dzēriens trakgalvis; kas no tā straipalē, nav gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Ķēniņa draudi ir kā jauna lauvas rūkšana; kas viņu apkaitina, tas grēko pret savu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Vīram gods, būt tālu no bāršanās; bet kas vien ģeķis, iemaisās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Aukstuma dēļ sliņķis near; pļaujamā laikā viņš meklēs augļus, bet nekā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Vīra padoms sirdī ir dziļš ūdens, bet gudrs vīrs to izsmeļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Ir daudz, kas katrs savu labu sirdi teic; bet uzticamu vīru, kas to atradīs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Taisnais staigā savā skaidrībā; svētīgi būs viņa bērni pēc viņa!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Ķēniņš, uz soģa krēsla sēžot, izdeldē visu ļaunu ar savām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kas var sacīt: Es esmu šķīsts savā sirdī, es esmu tīrs no grēkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Divējāds svars un divējāds mērs, šie abi Tam Kungam ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Jau pie bērna darbošanās var nomanīt, vai viņa vīra darbi būs skaidri un taisni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ausi dzirdošu un aci redzošu, abas darījis Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Nemīlē miegu, ka nepalieci par nabagu; atdari savas acis, tad būsi maizes paēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '„Slikts, slikts!“saka pircējs; bet aizgājis, tad lielās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Ja arī zelta un pērļu ir daudz, tomēr tas skaistākais glītums ir gudras lūpas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, '„Atņem viņam drēbi, jo tas priekš sveša galvojis, un tā nezināmā parādnieka vietā ķīlā tu to!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Zagta maize dažam salda, bet pēcgalā viņa mute būs pilna zvirgzdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Ar padomu ved nodomus galā, un karu tu vedi ar gudriem padomiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Mēlnesis apkārt lienot izpļurkstē, kas slēpjams; bet tu netinies ar to, kas savu muti nevalda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Kas tēvu un māti lād, tā spīdeklis izdzisīs visu dziļākā tumsībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Mantība, ko no pirmā gala iegūst, beidzamā galā nebūs svētīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Nesaki: Es atriebšu ļaunu! Gaidi uz To Kungu, un viņš tevi izpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Divējāds svars Tam Kungam negantība, un viltīgs svara kauss nav labs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'No Tā Kunga ir cilvēka soļi; kā gan cilvēks izprastu savu ceļu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Svētas lietas aplam solīt un pēc apdomāt, būs cilvēkam par valgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Gudrs ķēniņš izdeldē bezdievīgos un ved skrituli pār tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Dieva gaišums ir cilvēka dvēsele, kas pārzina visu sirds dziļumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Žēlastība un ticība pasargā ķēniņu, un caur žēlastību stāv stiprs viņa goda krēsls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Jaunekļu krāšņums ir viņu spēks, un sirmi mati veco goda kronis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Zilu un jēlu sapērt, tā nelieti noberž tīru un ar sitieniem līdz kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Ķēniņa sirds ir Tā Kunga rokā kā ūdens upes, un viņš to loka, kurp gribēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Ikvienam savi ceļi liekās taisni; bet Tas Kungs pārbauda sirdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Darīt, kas taisnība un tiesa, Tam Kungam vairāk patīk, nekā upuris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Acu lepnība un sirds greznība, bezdievīga spīdeklis, ir grēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Darbīga cilvēka nodomi ved tik pie vairuma; bet kas pārsteidzīgs, tiek pie trūkuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Mantas ar meliem krāt ir zūdošs tvaiks tiem, kas meklē nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Bezdievīgo varas darbi posta pašus, ka liedzās taisnību darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Līkus ceļus staigā blēdis, bet taisnais ir skaidrs savā darbā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Nama augšā kaktiņā dzīvot ir labāki, nekā namā kopā ar rējēju sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Bezdievīga dvēsele kāro ļaunu; viņa acīs tuvākais neatrod žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Per garzobi, tad tas nejēga atjēgs; un pamāci prātīgo, tad viņš atzīs, kas der.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Taisns (Dievs) skatās uz bezdievīgā namu; viņš bezdievīgos gāž nelaimē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kas ausi aizbāž priekš nabaga kliegšanas, tas arīdzan sauks un netaps paklausīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Dāvanas, klusu dotas, klusina bardzību, un dāvanas klēpī bargas dusmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Prieks ir taisnam taisnību darīt, bet ļaundarītājiem būs izbailes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Cilvēks, kas nomaldījies no labiem ceļiem, dabūs dusu miroņu draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Par tukšinieku paliks, kas līksmībā dzīvo, un kas vīnu un eļļu mīļo, tas nepaliks bagāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Bezdievīgais priekš taisnā top nodots, un nelietis sirdsskaidrā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Labāk dzīvot tukšā zemē, nekā pie rējējas un dusmīgas sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Gudra dzīvoklī ir mīlīga manta un eļļa; bet ģeķa cilvēks to izšķērdē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kas dzenās pēc taisnības un apžēlošanas, atradīs dzīvību, taisnību un godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Gudrais uzņem varenu ļaužu pilsētu un apgāž stiprumu, uz ko viņi paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kas muti un mēli sargā, tas pasargā savu dvēseli no briesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Kas pārgalvis un lepns, to pareizi sauc par zaimotāju, un ko viņš dara, ir traka pārgalvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Slinkam gan iegribās, bet tas mirst; jo rokas liedzās strādāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Cauru dienu viņam gribās un gribās; bet taisnais dod un neliedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Bezdievīgo upuris ir negantība; jo vairāk, kad to upurē ļaunā sirds padomā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Melu liecinieks ies bojā; bet vīrs, kas dzirdējis, varēs vienmēr runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Bezdievīgam pierē bezkaunīga drošība; bet taisnais, šis drošs savā ceļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Nedz gudrība, nedz saprašana, nedz padoms palīdz pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Zirgu gan sakopj uz kaujas dienu; bet no Tā Kunga nāk uzvarēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Laba slava der vairāk, nekā liela bagātība; mīlestība pie ļaudīm labāka, nekā sudrabs un zelts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bagāts sastopas ar nabagu; Tas Kungs viņus visus radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Gudrais paredz nelaimi un paglābjas; bet neprāta ļaudis skrien vien un dabū ciest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Pazemības, proti Dieva bijības alga ir bagātība un gods un dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Ērkšķi un valgi ir netiklam ceļā; kas savu dvēseli sargā, paliks tālu no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Māci bērnam viņa ceļu, tad viņš, arī vecs palicis, no tā neatkāpsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bagātais valda pār nabagiem, un kas aizņēmās, ir aizdevēja kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kas netaisnību sēj, tas bēdas pļaus un ies bojā caur savas blēdības rīksti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Žēlīga acs taps svētīta; jo viņa no savas maizes dod nabagam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Izdzen garzobi, tad aizies ķilda, un riešana mitēsies un kauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kam šķīsta sirds un mute mīlīga, tam ķēniņš ir par draugu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Tā Kunga acis pasargā, kam atzīšana; bet nelieša vārdus viņš izdeldē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Slinkais saka: „Lauva ir ārā; ielas vidū mani saplosīs!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Maukas mute ir dziļa bedre; ko Tas Kungs ienīst, tas krīt tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Blēņas līp bērna sirdī; bet pārmācības rīkste tās izdzen tālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kas no nabaga plēš, savu mantu vairot, tas to atkal dos bagātam līdz pat trūcībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Griez savu ausi un klausies gudro vārdu un loki savu sirdi pie manas atzīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Jo tas būs jaukums, ja tu tos sirdī pasargāsi un tos visnotaļ stādīsi uz savām lūpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Lai tava cerība stāv uz To Kungu. Šodien es tevi mācu, tiešām tevi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Vai tev jau sen to neesmu rakstījis ar padomiem un mācībām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Ka tev rādītu taisnus un patiesīgus vārdus, atbildēt patiesības vārdus tiem, kas tevi sūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Neaplaupi nabagu, tādēļ ka tas nabags, un nenospaidi sērdieni tiesas priekšā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Jo Tas Kungs iztiesās viņu tiesu un laupīs dvēseli tiem, kas tos laupa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Netinies ar bargu, un nesameties ar to, kam ātras dusmas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Ka tu nemācies viņa tekas un nesavaldzini savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Neturies pie tiem, kas ar roku apsolās un par parādu galvo;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Kad tev nebūs ko maksāt, tad noņems tavu gultu apakš tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Neatcel vecās robežas, ko tavi tēvi likuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Ja tu vīru redzi, kas tikuši(prasmīgi) savu darbu dara, tas stāvēs ķēniņu priekšā, un nestāvēs šādu tādu ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Kad tu sēdies, maizi ēst ar valdnieku, tad ņem labi vērā, kas tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Tu nazi lieci pie savas rīkles, ja esi negausis cilvēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Neiegribies viņa gardumu; jo tā ir viltus maize.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Nedzenies bagāts tapt, atmet tādu savu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Vai tu savām acīm ļausi laisties, kur nav nekā? Jo tas tiešām ņemsies spārnus, kā ērglis, kas pret debesi skrien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Neēd tā maizi, kam skaudīga acs, un nekāro viņa gardumus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Jo kādas viņa sirds domas, tāds viņš ir. „Ēd un dzer!“tā viņš tev saka, bet viņa sirds nav ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Tavi kumosi, ko tu ieēdis, tev būs jāaizvemj, un tavi mīlīgie vārdi būs bijuši veltīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Nerunā priekš ģeķa ausīm; jo viņš tik nievās tavus prātīgos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Neatcel vecās robežas un nenāc uz bāreņu tīrumiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Jo viņu atriebējs ir varens; tas iztiesās viņu tiesu pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Loki savu sirdi pie pamācīšanas un savas ausis pie prātīgas valodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Neatrauj bērnam pārmācību; ja tu viņu ar rīkstēm šaustīsi, tad tādēļ jau nemirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Tu viņu šaustīsi ar rīkstēm un izglābsi viņa dvēseli no elles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mans dēls, ja tava sirds gudra, tad mana sirds priecāsies, tiešām tā priecāsies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Un manas īkstis no prieka lēks, ja tavas lūpas runās skaidrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Lai tava sirds nedeg uz grēciniekiem; bet turies vienmēr Tā Kunga bijāšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Jo tiešām nāks pastara diena, un tava gaidīšana nebūs veltīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Klausies tu, mans bērns, un esi gudrs un turi savu sirdi taisnā ceļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Neesi ar vīna dzērājiem, kas rijot savu pašu miesu rij;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Jo dzērājs un rijējs panīks, un paģiras vilks skrandas mugurā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Klausi savam tēvam, kas tevi dzemdinājis, un nenicini savu māti, kad tā būs veca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Pērc patiesību, un nepārdod gudrību, pamācīšanu un atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Ar lielu prieku priecāsies taisnā tēvs, un kas gudru dzemdina, tas līksmosies par viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Lai tavs tēvs un tava māte priecājās, un lai līksmojās, kas tevi dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Dod man savu sirdi, mans dēls, un lai mans ceļš tavām acīm labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Jo mauka ir dziļa bedre, un sveša sieva šaura aka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Tiešām tā glūn kā laupītājs, un vairo atkāpējus pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kam gaudas? Kam vaidi? Kam bāršanās? Kam žēlabas? Kam skrambas par velti? Kam neskaidras acis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Tiem, kas pie vīna kavējās, tiem, kas nāk salda dzēriena meklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Neskaties pēc vīna, ka viņš tāds sarkans, ka biķerī tas zvīļo, ka tik vēlīgi nostaigā lejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Pēc viņš dzeļ kā čūska un dur kā odze.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Tavas acis skatās pēc svešām sievām, un tava sirds runā netiklību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Un tu esi, kā kas jūras vidū guļ, un kā kas masta virsgalā guļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '„Mani sit, bet man nesāp; mani grūsta, bet es nejūtu. Kad jel uzmodīšos? Tad sākšu atkal no gala!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Neiekarsies uz nelabiem cilvēkiem un nekāro būt ar viņiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Jo viņu sirds domā uz postu, un viņu lūpas runā mokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Ar gudrību uzceļ namu un ar saprašanu to stiprina,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Un ar samaņu pilda kambarus ar visādu dārgu un jauku bagātību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Gudrs vīrs ir spēcīgs, un vīrs, kam atzīšana, ir varens spēkā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Jo ar gudriem padomiem tu izvedīsi savu karu, un uzvarēšana ir, kur padoma devēju papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Ģeķim gudrība ir neaizsniedzama; savu muti lai tas neatdara pilsētas vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kas tīšām ļaunu dara, tas jāsauc blēdis pār visiem blēžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Ģeķības nodomi ir grēks, un mēdītājs cilvēkiem ir negantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Ja tu bēdu dienā nogursi, tad tavs spēks pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Glāb, kas uz nāvi pazudināti, un kas pie kaušanas top vesti, vai tu no tiem atrausies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Ja tu saki: „Redzi, mēs to nezinām!“Vai tad tas, kas sirdis pārmana, to nemana, un kas tavu dvēseli pasargā, to nezin un cilvēkiem neatmaksās pēc viņu darba?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Ēd, mans dēls, medu, jo tas ir labs, un tīrs medus ir salds tavā mutē;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Tāpat tavai dvēselei būs gudrības atzīšana, ja tu to atrodi; jo ir pastara diena, un tava gaidīšana nebūs veltīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Neglūn, tu bezdievīgais, uz taisnā dzīvokli, neposti viņa vietu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Jo taisnais krīt septiņ reiz un ceļas augšām; bet bezdievīgie nogrimst nelaimē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Nepriecājies, kad tavs ienaidnieks krīt, un lai tava sirds nelīksmojās, kad viņš klūp,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Ka Tas Kungs to neredz, un tas viņa acīm neriebj, un viņš savu dusmību no tā nenovērš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Neapskaities par ļauniem un neiekarsies par bezdievīgiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Jo ļaunam nenāk cerētais gals; bezdievīgo spīdeklis izdzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mans dēls, bīsties To Kungu un ķēniņu, un nejaucies ar dumpiniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Jo piepeši nāks viņiem nediena, - un abēju sodu, kas to zin!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Arī šie ir gudro vārdi: Tiesā cilvēka vaigu uzlūkot nav labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Kas uz vainīgo saka: „Tev taisnība!“to cilvēki lād un ļaudis ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Bet tie (viņiem) mīļi, kas (tādu) pārmāca, un pār tiem nāks visu labākā svētība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Kas pareizi atbildējis, ir kā saldu muti devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Padari savu darbu laukā un apkopies tīrumā, un tad vēl uztaisi savu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Nedod velti liecību pret savu tuvāko! Vai tu mānīsi ar savām lūpām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Nesaki: „Kā viņš man darījis, tā es viņam darīšu; es tam atmaksāšu pēc viņa darba!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Es gāju gar sliņķa tīrumu un gar ģeķa vīna kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Un redzi, tur auga tik nātres vien, un dadži pārņēma visu, un viņa akmeņu mūris bija sagruvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Un es to ieraudzīju, to liku vērā: es to redzēju, ņēmos mācību:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Guli maķenīt, snaud maķenīt, saliec maķenīt rokas miegā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Tad tava nabadzība tev pienāks nākdama, un tavs trūkums kā apbruņots vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Šie arīdzan ir Salamana sakāmie vārdi, ko Hizkijas, Jūda ķēniņa, vīri ir sakrājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Dieva gods ir, kādu lietu apslēpt, bet ķēniņu gods ir, kādu lietu izdibināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Debess ir augsta, un zeme dziļa, un ķēniņu sirds neizdibinājama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Atšķir sārņus no sudraba, tad tiek kausētājam trauks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Atšķir bezdievīgo nost no ķēniņa, tad viņa goda krēsls ar taisnību top stiprināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Nelielies ķēniņa priekšā un nestājies lielu kungu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Jo tas ir labāki, ka tev saka: „Virzies augšup!“nekā ka tevi pazemo vareno priekšā, ko tavas acis redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Nepārsteidzies strīdēties; jo citādi, ko tu galā darīsi, kad tavs tuvākais tevi gānījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Izšķir pats savas ķildas ar savu tuvāko un neatklāj cita noslēpumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Ka tevi nerāj, kas to dzird, un tavam kaunam nav gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Vārds īstenā laikā runāts ir zelta āboli sudraba traukos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Gudrs pamācītājs paklausīgām ausīm ir zelta gredzens un zelta ķēdes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Kā sniega dzestrums pļaujamā laikā, tāds ir uzticams kalps tam, kas to sūta; jo tas atspirdzina sava kunga dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Kas ar dāvanām lielās melodams, ir kā mākoņi un vējš bez lietus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Ar lēnu garu pierunā valdnieku un ar mīkstu mēli lauž kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Medu atradis, ēd savu tiesu, ka tu pārēdies to neizvem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Reti vien cel savu kāju tuvākā namā, ka viņš tevis neapnīkst un tevis neienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Kas pret savu tuvāko dod nepatiesu liecību, ir kā veseris un zobens un asa bulta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Uz neuzticamu paļauties bēdu dienā ir izlūzis zobs un kliba kāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Kas noskumušai sirdij dziesmas dzied, ir kā kad drēbes novelk ziemas laikā un kā etiķis uz sāls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Kad tavs ienaidnieks izsalcis, ēdini viņu ar maizi, un kad izslāpis, dzirdini viņu ar ūdeni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Jo tā tu sakrāsi kvēlošas ogles uz viņa galvas, un Tas Kungs tev to atmaksās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Ziemelis dzemdē lietu, un glūnētāja mēle skābu ģīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Nama augšā kaktiņā dzīvot ir labāki, nekā namā kopā ar rējēju sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Laba ziņa no tālas zemes ir dzestrs ūdens izslāpušai dvēselei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Taisnais, kas bezdievīga priekšā lokās, ir sajukusi aka un sajaukts avots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Daudz medus ēst nav labi, un savu paša godu meklēt nav gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Kas prātu nemāk valdīt, ir izlauzta pilsēta bez mūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Kā sniegs vasarai un lietus pļaujamam laikam, tā ģeķim nepieder gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Kā putns nolidinājās, kā bezdelīga aizskrien, tā nenopelnīti lāsti neaizņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Zirgam pātaga, ēzelim iemaukti un ģeķa mugurai rīkste.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Neatbildi ģeķim pēc viņa ģeķības, ka tu viņam līdzi netopi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Atbildi ģeķim pēc viņa ģeķības, ka viņš pats neturās par gudru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Darbu uzticēt nelgam rokā, ir nocirst kājas un izbaudīt briesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Kā klibam karājās kājas, tā ģeķa mutē gudrības vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Kas ģeķim dod godu, ir kā kas akmeni piesien pie lingas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Kā ērkšķi, kas tikuši piedzēruša rokā, tāds ir sakāms vārds ģeķu mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Manīgs visu izdara; bet kas nelgu der, sader tekuli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Kā suns atiet pie saviem vēmekļiem, tā pat ģeķis atgriežas atpakaļ pie savas ģeķības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Kad tu redzi vīru, kas savās acīs gudrs, tad no muļķa vairāk cerības, nekā no tāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Sliņķis saka: „Jauns lauva uz ceļa, lauva uz ielām!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Durvis grozās eņģēs, un sliņķis savā gultā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Sliņķis slēpj savu roku azotē, un tam grūti to atkal pie mutes likt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Sliņķis savā prātā gudrāks nekā septiņi, kas runā prātīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kas garām ejot iejaucās citu ķildā, ir kā kas suni ņem aiz ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Tā kā, kad (ārprātīgs) par smieklu šautu ar šķēpiem un nāvīgām bultām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Tā pat ir, kas savu tuvāko pievīlis saka: Vai to par smieklu vien nedarīju?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Kad malkas nav, tad uguns izdziest, un kad lišķa nav, tad ķilda rimst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Kā ogles liesmu un malka uguni, tā rējējs cilvēks saceļ ķildu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Lišķa vārdi ir kā saldi kumosi un iet visai pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Dedzīgi vārdi, bet neganta sirds ir poda gabals pārvilkts ar netīru sudrabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Kas tevi ienīst, ir ar muti draugs, bet savā sirdī viņš domā uz viltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Kad tas mīlīgi runā, tad netici viņam, jo septiņas negantības viņa sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Lai gan ienaidu aizsedz ar viltu, tomēr viņa niknums ļaužu priekšā nāks gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kas bedri rok, tas tanī iekritīs, un kas akmeni veļ uz to tas atvelsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Viltus mēle ienīst to, kam pati dzēlusi, un mīksta mute padara nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Nelielies ar rītdienu; jo tu nezini, ko diena atnesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Lai cits tevi slavē un ne paša mute, svešs un ne paša lūpas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Akmens ir grūts un smiltis smagas, bet ģeķa sēras sūrākas nekā abi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Nežēlība ir briesmīga lieta un bardzība ir kā plūdi; bet priekš skaudības, kas tur pastāvēs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Labāki skaidri pārmācīt, nekā mīlestība, ko nedabū redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Drauga sitieni nāk no labas sirds, bet viltīga ir nīdētāja skūpstīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Paēdis arī tīru medu min pa kājām, bet izsalkušam ikviens rūgtums ir salds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Kā putns, kas savu ligzdu atstājis, tāds ir cilvēks, no dzimtenes aizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Eļļa un kvēpināšana iepriecina sirdi; tāds mīlīgs ir draugs, kas padomu dod no sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Neatstāj savu draugu, nedz sava tēva draugu, un savā bēdu laikā neej sava brāļa namā; labāks ir kaimiņš tuvumā, nekā brālis tālumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Esi gudrs, mans dēls, tad mana sirds priecāsies, un es varēšu atbildēt saviem nievātājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Gudrais paredz nelaimi un paglābjās; bet neprāta ļaudis skrien vien un dabū ciest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, '„Atņem tam drēbi; jo viņš priekš sveša galvojis, un tā nezināmā vietā ķīlā to.“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Ja arī cilvēks no paša rīta skaņā balsī savu tuvāko svētī, to viņam tomēr var pārgriezt par lāstiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Bez gala pil, kad lietus līst, un rējēja sieva tāda pat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kas tādu grib valdīt, tas valda vēju un tur eļļu savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Dzelzs trinās pie dzelzs un cilvēks trinās pie cilvēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kas vīģes koku kopj, ēdīs viņa augļus, un kas par savu kungu gādā, taps godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Kā vaigam vaigs atspīd ūdenī, tā cilvēka sirds cilvēkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Elle un bezdibenis nav pildāmi, tāpat cilvēka acis nav pildāmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Kausējams katls sudrabam, ceplis zeltam, un vīrs pēc savas slavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Ja tu ģeķi piestā ar piestalu putraimos sagrūstu, ģeķība no viņa neatstāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Liec labi ziņā savus sīkos lopus un ņem vērā savus ganāmos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Jo mantas nepaliek mūžīgi, nedz ķēniņa kronis uz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, '(Bet) kad siens nopļauts, un jauns zaļums nācis, un zāles uz kalniem salasītas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Tad tev jēri būs apģērbam, un āži par tīruma maksu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Un kazu piena būs diezgan tev un tavam namam par barību un par uzturu tavām kalponēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Bezdievīgais bēg, kur dzinēja nav; bet taisnie ir droši, kā jauns lauva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Caur dumpjiem zemei tiek daudz valdnieku; bet ja ļaudis prātīgi un apdomīgi, tad valdnieks paliek ilgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Nabaga kungs, kas nabagus apspiež, ir kā plūdu lietus, un maizes nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Kas paši mācību atstāj, tie slavē bezdievīgus; bet kas mācību tura, tie ļaunojās par tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Ļauni ļaudis neatzīst, kas Dieva tiesa, bet kas To Kungu meklē, tie atzīst visu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Labāks ir nabags, kas staigā skaidrībā, nekā bagāts netiklā ceļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kas glabā mācību, tas ir prātīgs bērns; bet kas rijēju biedrs, dara tēvam kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kas savu mantu vairo ar augļošanu un augļus ņemot, tas to krāj tādam, kas par nabagiem apžēlojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kas savu ausi nogriež no Dieva bauslības, pat tāda cilvēka lūgšana ir neganta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kas maldina bezvainīgus uz ļauniem ceļiem, tas pats kritīs savā bedrē; bet tie sirdsskaidrie iemantos labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Bagāts vīrs savā prātā gudrs; bet nabags, kas prātīgs, to izmana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Kad taisnie gavilē, tas ir liels jaukums; bet kad bezdievīgie galvu paceļ tad ļaudis slēpjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kas savus pārkāpumus apklāj, tam tas neizdosies; bet kas tos izsūdz un atstāj, tas dabūs žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Svētīgs, kas Dievu bīstas vienmēr; bet kas savu sirdi apcietina, kritīs postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Bezdievīgais, kas valda pār nabaga ļaudīm, ir rūkdams lauva un izsalcis lācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Valdnieks nav gudrs, ja mudīgs uz varas darbiem; bet kas labprāt neplēš, dzīvos ilgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Pie kā rokām cilvēka asinis līp, tas bēgs līdz bedrei; palīga tas nedabūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kas staigā vientiesībā, tam labi klāsies; bet blēdis pa diviem ceļiem vienā klups.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kas savu zemi kopj, būs maizes paēdis; bet kas niekus triec, būs bada paēdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Godīgs vīrs būs bagāti svētīts, bet kas dzenās bagāts palikt, nebūs nenoziedzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Nav labi, cilvēka vaigu uzlūkot; jo tāds arī par maizes kumosu dara netaisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Kas ar skaudīgu aci dzenās pēc bagātības, neapdomā, ka viņam trūcība pienāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kas cilvēku aprāj, tas pēc atradīs vairāk pateicības, nekā tāds, kam mīksta mēle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kas savu tēvu vai māti laupa un saka: „Tas nav grēks!“tāds ir slepkavas biedrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Negausis saceļ nemieru; bet kas uz To Kungu cerē, tas būs turīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kas uz savu sirdi paļaujas, ir ģeķis; bet kas ar gudrību staigā, tiks izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kas nabagam dod, tam nepietrūks; bet kas savas acis priekš tā aizslēdz, tam uzies daudz lāstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Kad bezdievīgie paceļ galvu, tad ļaudis slēpjas; bet kad tie beigti, tad taisnie iet vairumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Vīrs, kas pārmācīts, tomēr ciets, taps piepeši salauzts, un nebūs, kas dziedina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Kad taisnie iet vairumā, tad ļaudis priecājās; bet kad bezdievīgais valda, tad ļaudis nopūšās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Kas gudrību mīļo, iepriecina savu tēvu; bet kas ar maukām pinās, tas izplītē savu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Caur tiesu un taisnību ķēniņš dara valsti pastāvam; bet kas dāvanas plēš, tas to izposta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Kas otram mīksti pieglaužas, met tīklu viņa soļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Bezdievīgais savaldzinājās savos grēkos, bet taisnais priecājās un līksmojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Taisnais ņem vērā nabaga žēlošanos; bezdievīgais par to nemaz nebēdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Kam viss tik smiekls, sakurina pilsētu; bet gudrie apslāpē kaislību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Gudrs ar ģeķi pie tiesas, tad skaistās, tad smejas, galā netiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Asins vīri ienīst bezvainīgo, bet taisnie rūpējās par viņa dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Ģeķis izkrata visu savu padomu, bet gudrs vīrs to patur pie sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Kungs, kas uz meliem klausa, tam visi kalpi blēži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Nabagi un mantas plēsēji sastop viens otru; abiem Tas Kungs dod acu gaismu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Ķēniņš, kas nabagiem nes taisnu tiesu, tā goda krēsls pastāvēs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Rīkste un pārmācība dod gudrību; bet bērns savā vaļā dara mātei kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Kur bezdievīgie iet vairumā, tur vairojās grēki; bet taisnie redzēs viņu krišanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Pārmāci savu dēlu, tad tev būs prieks no viņa un tavai dvēselei līksmība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Kur Dieva mācības nav, tur ļaudis nevaldāmi; bet svētīgs, kas mācību sargā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Kalps ar vārdiem nav mācams; lai gan labi prot, taču neklausa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Kad tu vīru redzi, kam veikla mēle, tad no muļķa vairāk cerības nekā no tāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Kad kalpu no pirmā gala izlutina, tad pēcgalā grib būt par pašu dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Ātrs cilvēks saceļ bāršanos, un sirdīgs vīrs padara daudz grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Cilvēka lepnība viņu gāzīs, bet pazemīgs gars panāks godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kas ar zagli dalās, tas ienīst savu dvēseli; viņš dzird Dieva lāstus un nepierāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Priekš cilvēkiem drebēt ieved valgos; bet kas uz To Kungu paļaujas, ir drošā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Daudzi meklē valdnieka vaigu; bet no Tā Kunga nāk katram tā tiesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Netaisnais riebj taisniem, un kas bezvainīgs savā ceļā, riebj bezdievīgam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Agura, Jakes dēla, vārdi šā vīra sludināšana un mācība. Es esmu nodarbojies ar Dievu, esmu nodarbojies ar Dievu un noguris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Jo es esmu nejēga pār citiem, un man nav cilvēka saprašanas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Es arī gudrības neesmu mācījies, nedz svētu atzīšanu atzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kas ir uzkāpis debesīs un nācis zemē? Kas sagrābj vēju savās rokas? Kas saista ūdeni drēbē? Kas liek zemei visas robežas? Kāds viņam vārds, un kāds viņa dēlam vārds, ja tu to zini?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Visi Dieva vārdi ir šķīsti; Viņš ir par priekšturamām bruņām tiem, kas uz Viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nepieliec nekā pie viņa vārdiem, ka viņš tevi nesoda, un tu netopi atrasts melkulis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Divas lietas lūdzos no tevis, neliedz man tās, pirms es mirstu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Nelietība un meli lai paliek tālu no manis; nabadzību un bagātību nedod man, bet paēdini mani ar manu dienišķu maizi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Ka es paēdis tevi neaizliedzu un nesaku: Kas ir Tas Kungs? vai nabags palicis nezogu un sava Dieva vārdu velti nevalkāju. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Neapmelo kalpu pie viņa kunga, ka viņš tevi nelād, un tu netopi noziedzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Ir suga, kas tēvu lād un māti nesvētī;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Ir suga, kas pati savās acīs šķīsta, bet no saviem sārņiem nav mazgāta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Ir suga, cik augsti tā ceļ acis, cik augsti acu plakstiņus!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Ir suga, zobeni ir viņas zobi un naži viņas dzerokļi, rīt nabagus no zemes nost un sērdienīšus cilvēku starpā. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Asins sūcējai ir divas meitas: „Dod šurp, dod šurp!“- Šās trīs nav pieēdināmas, un tā ceturtā nesaka: Gan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Elle, neauglīgais klēpis, zeme, nepiedzirdināma ar ūdeni, un uguns nesaka: Gan. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Acs, kas tēvu apsmej un liedzās mātei klausīt, to izknābs kraukļi pie upes, un jaunie ērgļi to ēdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Šās trīs lietas man ir visai brīnums, un to ceturto es neizprotu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Ērgļa ceļš debesīs, čūskas ceļš pār klinti, laivas ceļš jūras vidū un vīra ceļš pie meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Tāds pat ir sievas ceļš, kas laulību pārkāpj; viņa ēd, noslauka muti un saka: Es ļauna neesmu darījusi. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Par trim lietām nodreb zeme, un ceturto tā nevar panest:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Par kalpu, kad tas paliek par kungu, un par ģeķi, kad tas maizes paēdis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Par nopeltu, kad tā tiek pie vīra, un par kalponi, kad tā top savas saimnieces mantiniece.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Šie četri ir mazi virs zemes un tomēr gudrāki nekā tie gudrie:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Skudras, nespēcīga tauta, tomēr savu barību vasarā sagādā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Truši, nespēcīga tauta, tomēr liek savus namus akmens kalnos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Siseņiem nav ķēniņa, tomēr viņi visi iziet, pulkos dalīti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Zirneklis auž abām rokām, un tomēr ir ķēniņu pilīs.-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Šiem trim ir laba gaita, un tas ceturtais iet it lepni:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Vecs lauva, varens starp zvēriem, kas nevienam ceļu negriež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Ērzelis, kam labi gurni, vai āzis, un ķēniņš, savus ļaudis vedot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Ja tu ģeķis bijis, paaugstinādamies, un ko nodomājis, tad: roku uz muti!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Satricini pienu, būs sviests; satrīcini degunu, būs asinis; un satrīcini dusmas, būs plēšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Ķēniņa Lemuēļa vārdi, tā mācība, ko viņa māte tam mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Ak, mans dēls! ak manas miesas dēls! tu manu solījumu dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Nedod sievām savu spēku, nedz savu ceļu tām, kas ķēniņus samaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ķēniņiem nebūs, ak Lemuēl, ķēniņiem nebūs vīna dzert, nedz valdniekiem stipra dzēriena iekārot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Ka dzerdami neaizmirst likumus, un nepārgroza tiesu visiem sērdieņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dodiet stipru dzērienu tam, kas iet bojā, un vīnu, kam noskumusi sirds:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Tāds lai dzer, ka aizmirst savu nabadzību, un vairs nepiemin savas bēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Atdari savu muti par mēmo un par visiem, kas ir atstāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Atdari savu muti, tiesā taisni un nes tiesu nabagam un sērdienim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Tikušu (tikumīgu) sievu, kas tādu atrod, pāri par pērlēm ir viņas dārgums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Uz viņu uzticas vīra sirds un labuma tam netrūkst nekāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Tā dara tam labu, ne ļaunu visās sava mūža dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Viņa gādā par vilnu un liniem un strādā priecīgām rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Tā ir kā laivinieka laiva, sagādā maizi no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Jau pašā naktī tā ceļas un dod barību savai saimei un kalponēm iespriesto tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'To zemes stūri, ko cerē, tā dabū, no savu roku augļiem tā dēsta vīna dārzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Ar spēku tā jož savus gurnus un savas rokas ar stiprumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Tā mana, ka viņas pūliņš labi sokas, un gaisma tai neapdziest naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Tā stiepj savu roku pie kodeļa un tver ar pirkstiem ratiņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Tā sērdieņus mīlīgi apkampj un pasniedz nabagiem roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Savam namam tā nebīstas sniega, jo saime divkārtīgi ģērbta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Tā sev taisa apsegus, dārgs audeklis un purpurs tai ir apģērbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Tai vīrs ir pazīstams vārtos, kad tas sēž ar zemes vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Viņa auž linu svārkus un pārdod, un izdod pircējiem jostas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Stiprums un gods tai apģērbs; tā smejas par nākamo laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Savu muti tā atdara ar gudrību, un uz viņas mēles ir jauka mācība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Viņa skatās pēc visām sava nama gaitām un neēd savu maizi ar slinkumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Viņas bērni pieceļas un teic viņu laimīgu; viņas vīrs, tas to slavē:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Daudz mātes meitām ir goda tikums, bet tu esi pāri par visām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Daiļums viļ un skaistums paiet; dievbijīga sieva, tā ir teicama!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Teiciet viņu par viņas roku augļiem, un viņas pašas darbi lai viņu ļaudīs teic!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Dāvida dēla, Jeruzālemes ķēniņa, mācības vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Niecība vien, saka tas mācītājs, niecība vien, viss ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Kāds labums cilvēkam atlec no visa viņa grūta darba, ar ko viņš nodarbojās pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Cits dzimums aiziet un cits dzimums nāk; bet zeme pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Saule lec un saule noiet un steidzās uz savu vietu, kur tā atkal uzlec.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Vējš iet pret dienasvidu un iet apkārt pret ziemeļa pusi; tas pūš visapkārt griezdamies un riņķī apgriežas atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Visas upes ietek jūrā, tomēr jūra netop pilnāka. Tai vietā, no kurienes upes nāk, turp tās atkal atgriežas atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Visās lietās ir tik daudz grūtuma, ka neviens to nevar izteikt. Acīm nepietiek redzot, un ausīm nepietiek dzirdot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Kas jau ir bijis, tas vēl būs; un kas jau ir darīts, tas vēl taps darīts; un it nekā jauna nav pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Vai ir kas, par ko varētu sacīt: redzi, tas ir jauns? Tas jau ilgi bijis vecos laikos, kas bijuši priekš mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Kas pagājis, netop pieminēts; un kas nāks, to arī nepieminēs tie, kas pēc tam būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Es, tas mācītājs, biju ķēniņš pār Israēli Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Un apņēmos savā sirdī, ar gudrību izmeklēt un izdibināt visu, kas apakš debess notiek. Šo grūto pūliņu Dievs cilvēku bērniem ir uzlicis, lai ar to nopūlējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Es uzlūkoju visus darbus, kas pasaulē notiek, un redzi, viss bija niecība un grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Kas līks, nevar palikt taisns; un kā nav, to nevar skaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Es runāju savā sirdī un sacīju: redzi, es gudrībā esmu augsti cēlies un pieņēmies vairāk nekā visi, kas priekš manis bijuši Jeruzālemē, un mana sirds ir redzējusi gudrības un zinības papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Un es apņēmos savā sirdī, atzīt gudrību un zinību, neprātību un ģeķību. Bet es samanīju, ka tā ir grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Jo kur daudz gudrības, tur ir daudz grūtības, un jo vairāk atzīšanas, jo vairāk bēdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Es sacīju savā sirdī: nu tad, gribu baudīt priekus un redzēt labas dienas; bet redzi, arī tā ir niecība!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Uz smiešanos es sacīju: tu esi neprātīga, un uz prieku: ko tu dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Tad es savā sirdī apņēmos, mielot savu miesu ar vīnu, un kamēr sirds uz gudrību dotos, arī baudīt ģeķību, tiekams es redzētu, kas cilvēku bērniem labi būtu, kas tiem jādara apakš debess savā dzīvības laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Es darīju lielus darbus; es uzcēlu sev ēkas, dēstīju vīna dārzus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Es sev kopu dārzus un jaukas birzes un stādīju tur visādus augļu kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Es sev izraku dīķus, no tiem slacināt birzi, kur koki zaļoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Es pirku kalpus un kalpones, man bija arī dzimta saime un vēršu un avju lielāks pulks, nekā visiem, kas priekš manis bijuši Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Es sev arī sakrāju sudrabu un zeltu un dārgumus no ķēniņiem un valstīm. Es sev sagādāju dziedātājus un dziedātājas, un ko cilvēku bērni mēdz iekārot, sievas pār sievām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Un es paliku lielāks un lielāks un pieņēmos pār visiem, kas priekš manis bijuši Jeruzālemē, arī mana gudrība man palika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Un visu, ko manas acis iekāroja, to es tām neatrāvu; es neliedzu savai sirdij nekāda prieka; jo mana sirds priecājās par visu manu pūliņu, un šī bija mana daļa no visa mana pūliņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Tad es uzlūkoju visus savus darbus, ko manas rokas bija darījušas, un to pūliņu, ar ko es grūti biju pūlējies, un redzi, viss bija niecība un grābstīšanās pēc vēja, un labuma nav pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Un es griezos, redzēt gudrību un neprātību un ģeķību. Jo ko tas cilvēks (darīs), kas nāks pēc ķēniņa? to pašu, kas jau sen darīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Un es redzēju, ka gudrība ir labāka nekā ģeķība, tā kā gaisma labāka nekā tumsība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Gudram acis stāv galvā, un ģeķis staigā tumsībā; bet es arī manīju, kā viņiem visiem vienāds liktenis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Tad es sacīju savā sirdī: kad man tāds pat liktenis kā ģeķim, kāpēc tad es tik pārlieku esmu dzinies pēc gudrības? Un es sacīju savā sirdī: Arī tā ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Jo gudro tāpat mūžam nepiemin kā ģeķi; jo kas tagad ir, tas nākošā laikā viss top aizmirsts, un tāpat gudrais mirst kā ģeķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Tādēļ es ienīdēju šo dzīvību, jo es turēju par ļaunu, kas pasaulē notiek; jo viss tas ir niecība un grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Es arī ienīdēju visu savu pūliņu, ar ko es biju nopūlējies pasaulē, ka man tas bija jāpamet cilvēkam, kas būs pēc manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Jo kas zin, vai viņš būs gudrs vai ģeķis; un tomēr viņš valdīs pār visu manu darbu, ar ko esmu nopūlējies, un ko ar gudrību esmu padarījis pasaulē; arī tā ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Tāpēc es griezos, ka mana sirds apnikusi atstātos no visa tā pūliņa, ar ko biju nopūlējies pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Jo jebšu kas savu darbu ar gudrību un ziņu un pareizi dara, taču viņam sava daļa jāpamet citam, kas pie tā nav strādājis; arī tā ir niecība un liela nelietība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Kas tad cilvēkam atlec no visa viņa darba un viņa sirds pūliņa, ar ko viņš nopūlējies pasaulē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Jo visas viņa dienas ir sāpes, un viņa darbs ir sirdēsti, arī naktī viņa sirds nedus; tā ir arīdzan niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Vai tad nebūs labāki cilvēkam, ka viņš ēd un dzer un savai dvēselei ļauj labumu baudīt pie sava pūliņa? Bet es esmu redzējis, ka arī tas nāk no Dieva rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Kas gan var ēst un kas var ko baudīt bez Viņa?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Jo cilvēkam, pie kā Viņam labs prāts, Viņš dod gudrību un atzīšanu un prieku, bet grēciniekam Viņš dod grūtumu, ka tas kopj un krāj un tomēr atstāj tam, pie kā Dievam labs prāts. Arī tā ir niecība un grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Katram darbam ir nolikts laiks un katram nodomam apakš debess ir savs brīdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Savs laiks piedzimt, savs laiks mirt, savs laiks dēstīt un savs laiks dēstīto ravēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Savs laiks nokaut un savs laiks dziedināt, savs laiks nolauzt un savs laiks uzcelt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Savs laiks raudāt un savs laiks smieties, savs laiks vaidēt un savs laiks diet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Savs laiks akmeņus mest un savs laiks akmeņus kraut, savs laiks apkampt un savs laiks šķirties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Savs laiks meklēt un savs laiks zaudēt, savs laiks glabāt un savs laiks nomest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Savs laiks saplēst un savs laiks sašūt, savs laiks klusu ciest un savs laiks runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Savs laiks mīlēt un savs laiks nīdēt, savs laiks karam un savs laiks mieram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Kāds labums strādniekam no sava pūliņa?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Es esmu redzējis grūtumu, ko Dievs cilvēku bērniem uzlicis, ar to mocīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Viņš visu jauki ir darījis savā laikā; pat mūžību viņš licis viņu sirdīs; tik cilvēks nevar izprast Dieva darbu, ne viņa iesākumu, ne galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Es samanīju, ka priekš viņiem nekas nav labāks, nekā priecāties un labu darīt savā laikā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Un ka ikkatrs cilvēks ēd un dzer un ko laba bauda pie visa sava pūliņa: tā ir Dieva dāvana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Es zinu, ka viss, ko Dievs dara, tas paliek mūžīgi, tam neko nevar pielikt nedz no tā ko atraut, un Dievs to dara, lai Viņu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Kas jau bijis, tas tagad ir, un kas vēl būs, tas jau bijis; un Dievs atjauno to, kas bija pagājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Un es vēl pasaulē esmu redzējis tiesas vietu, - tur bija bezdievība, un taisnības vietu, - tur bija bezdievība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Es sacīju savā sirdi: Dievs tiesās taisno un bezdievīgo; jo katram nodomam ir tur savs laiks, un visi darbi (taps tiesāti).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Es sacīju savā sirdī: tas ir cilvēku bērnu dēļ, Dievs tos grib pārbaudīt un tiem rādīt, ka tie paši par sevi ir kā lopi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Jo kāds cilvēku bērnu liktenis, tāds lopu liktenis; tiem ir viens liktenis: kā viens mirst, tā otrs mirst, - tiem visiem ir viena dvaša, un cilvēks nav pārāks pār lopiem; jo viss ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Visi noiet vienā vietā, visi ir no pīšļiem un visi griežas atpakaļ pīšļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kas pārmana cilvēku bērnu dvašu, vai tā augšup iet, un lopu dvašu, vai tā lejup nokāpj?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Tādēļ es redzēju, ka nekas nav labāks, nekā ka cilvēks priecājās pie sava darba; jo tā ir viņa daļa. Jo kas viņu vedīs tai vietā, kur tas varētu redzēt, kas pēc viņa notiks?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Un es griezos un redzēju visus spaidus, kas notiek pasaulē, un redzi, tur bija apspiesto asaras, un iepriecinātāja tiem nebija, un viņu spaidītāju roka tiem darīja pāri, un iepriecinātāja tiem nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Tad es slavēju tos mirušos, kas jau bija nomiruši, vairāk nekā tos dzīvos, kas vēl dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Un vēl labāki nekā tiem abiem ir tam, kas vēl nemaz nav, kas nemaz vēl nav redzējis to blēdību, kas notiek pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Vēl es redzēju visādu pūliņu un visādu darba izveicību, ar ko cits citam grib tikt pāri(skaudībā); arī tā ir niecība un grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Ģeķis saliek savas rokas un ēd savu paša miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Sauja pilna ar mieru ir labāka nekā abas rokas pilnas ar pūliņu un grābstīšanos pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Atkal es griezos un redzēju niecību pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Tur ir viens pats un ne divi, viņam arī nav ne dēla ne brāļa, un viņam ir pūliņu bez gala, un viņa acīm bagātības nepietiek. Kam tad par labu es pūlējos un atrauju savai dvēselei labumu? Tā ir arīdzan niecība un liels grūtums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Diviem ir labāki nekā vienam, jo tiem ir laba alga no sava pūliņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Jo kad tie krīt, tad draugs draugu uzceļ; bet vai tam, kas viens, kad tas krīt un otra nav, kas viņu uzceļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Kad divi kopā guļ, tad tiem ir silti, bet kā viens var sasildīties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Un ja kas to vienu pārvarētu, tad tie divi tam taču var pretī stāvēt, un trīskārtīgu auklu drīz nepārraus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Labāki nabaga bērns, kas gudrs, nekā vecs ķēniņš, kas ir ģeķis, un vairs nezin mācības pieņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Jo šis nāk no cietuma nama un top par ķēniņu, lai gan nabags bija piedzimis savā valstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Es ieraudzīju visus, kas dzīvo pasaulē, staigājam ar šo jaunekli, to otru, kam bija stāvēt viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Visu to ļaužu, kam viņš par priekšnieku, bija bezgalīgs pulks; bet tie, kas vēl pēc būs, par viņu nepriecāsies. Tiešām tā arī ir niecība un grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Sargi savu kāju, kad tu ej Dieva namā, un nāc labāk klausīties nekā upurēt kā ģeķi, jo tie nezina, ka tie ļaunu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Neesi ātrs ar savu muti un lai tava sirds nepārsteidzās, kādu vārdu Dieva priekšā izrunāt. Jo Dievs ir debesīs un tu virs zemes, tāpēc lai ir maz tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Jo kā sapnis nāk, kur lielas rūpes, tā ģeķa valoda, kur aplam daudz vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Ja tu Dievam solījumu solījis, tad nekavējies to maksāt; jo viņam nav labs prāts pie ģeķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Ko tu esi apsolījis, to pildi; labāki nesolīt, nekā solīt un nepildīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Nedod savai mutei vaļas, savu miesu apgrēcināt, un nesaki Dieva vēstneša priekšā, man ir misējies. Kāpēc Dievs lai apskaitās par tavu valodu un iznīcina tavu roku darbu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Jo kur daudz sapņu un arī, kur daudz vārdu, tur ir niecība; bet tu bīsties Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Kad tu redzi, ka nabagu apspiež kādā valstī un atrauj tiesu un taisnību, tad nebrīnies par to; jo vēl ir viens augstāks pār to augsto; tas liek vērā, un tas Visuaugstākais ir pār tiem visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Pie visa tā zemei par labu: ķēniņš, kam rūp zemes kopšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Kas naudu mīļo, tam naudas netiek gan; un kas bagātību mīļo, tas no tās laba neredzēs, - arī tā ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Kur manta vairojās, tur vairojās ēdāji; kāds tad labums tam, kam tā pieder, kā tik acīm skatīties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Strādniekam miegs gards, vai maz vai daudz ēdis; bet bagātais, kas pieēdies, netiek pie miega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Tas ir liels ļaunums, ko es redzēju pasaulē, kad bagātība tam, kas to sargā, pašam paliek par nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Jo tāda bagātība iet bojā caur kādu nelaimi, un kad tam dēls dzimis, tad šim nekā nav pie rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Tā kā viņš nācis no mātes miesām, tāpat viņš pliks atkal aizies, kā atnācis; viņš arī neņems nekā līdz no sava pūliņa, ko savā rokā varētu aiznest,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Un arī tas ir liels ļaunums, ka viņš itin tā atkal aiziet, kā atnācis. Kāds labums tad viņam atlec, ka viņš velti pūlējies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Ka viņš arī visu mūžu tumsā ēdis un lielos sirdēstos un vājībā un dusmās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Tad nu uzskatu par labu, ka jauki ir ēst un dzert, un labumu baudīt pie visa sava pūliņa, ar ko kāds pūlējās pasaulē to īso mūžu, ko Dievs tam dod; jo tā ir viņa daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Jo kuram cilvēkam Dievs devis bagātību un mantu, un tam dod vaļu no tās ēst un savu daļu ņemt un priecāties pie sava darba, tā ir Dieva dāvana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Jo viņš daudz nepiemin savas dzīvības dienas, tāpēc ka Dievs viņa sirdi ar prieku apdāvina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Ir ļaunums, ko es redzēju pasaulē, kas grūti panesams cilvēkiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Vīrs, kam Dievs devis bagātību un mantu un godu, un viņam priekš savas sirds nekāda trūkuma nav no visa, kas tik viņam gribās, un Dievs viņam nedod vaļas no tā ēst, bet svešs vīrs to apēd; tā ir niecība un liels ļaunums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Ja vīrs simts bērnus dzemdinātu un daudz gadus dzīvotu, un tam būtu garš mūžs, un viņa dvēsele nebautītu no tā labuma, un tam arī netiktu ne kapa vieta, tad es saku, ka nelaika(nedzīvi piedzimušam) bērnam labāki ir nekā tādam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Jo niecībā šis nāk, un tumsībā šis aiziet, un ar tumsību šī vārds top aizklāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Arī sauli šis nav redzējis nedz atzinis, - šim labāka dusa nekā tam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Un jebšu tas divtūkstoš gadus dzīvotu un laba neredzētu, - vai visi nenoiet uz vienu vietu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Viss cilvēka pūliņš ir priekš viņa mutes, bet sirds no tā nepaēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Jo kas atlec gudram vairāk nekā ģeķim? Kas nabagam, kas zin staigāt cilvēku vidū?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Labāki ir acīm redzēt, nekā sirdī iekārot; arī tā ir niecība un grābstīšanās pēc vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Kas notiek, tā vārds jau sen ir nosaukts, un ir nolikts, kas cilvēks būs, un viņš nespēj tiesāties ar to, kas ir stiprāks nekā viņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Tiešām, daudz vārdu ir, kas vairo niecību; un kas tur cilvēkam atlec?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Jo kas zin, kas cilvēkam ir par labu šinī mūžā, ko viņš savā niecībā pavada kā ēnu? Jo kas cilvēkam var stāstīt, kas pēc viņa notiks pasaulē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Laba slava ir labāka nekā salda eļļa, un miršanas diena labāka nekā dzimšanas diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Labāki ir vaidu namā iet nekā dzīru namā; jo tas ir visu cilvēku gals, un tas, kas dzīvo, to ņem pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Noskumt ir labāki nekā smieties; jo kad vaigs noskumis, tas sirdij labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Gudru ļaužu sirds ir vaidu namā, bet ģeķu sirds ir prieku namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Labāk ir klausīties gudra vīra rāšanu, nekā klausīties ģeķa dziesmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Jo kā ērkšķi sprakst apakš poda, tāpat ir ģeķa smiešanās, - tā ir arī niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Tiešām, netaisna peļņa arī gudru padara neprātīgu, un dāvanas samaitā sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Labāks ir kādas lietas gals nekā viņas iesākums. Lēnprātīgais ir labāks nekā lepnais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Neesi ātrs savā prātā dusmot, jo dusmība mājo ģeķu azotē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Nesaki: kā tas nāk, ka senās dienas bijušas labākas nekā šīs! Jo ar gudrību tu to nevaicā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Gudrība ir tik laba kā mantība un labums tiem, kas sauli redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Jo gudrības pavēnī ir kā naudas pavēnī; un tas ir atzīšanas labums, ka gudrība dod dzīvību tiem, kam tā ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Uzlūko Dieva darbu, jo kas to var darīt taisnu, ko viņš ir darījis līku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Baudi labumu labā dienā, bet ļaunu dienu ņem arī par labu; jo Dievs dara gan šo gan to, tāpēc ka cilvēkam nebūs zināt, kas būs pēc viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Visu to esmu redzējis savas niecības dienās: Cits ir taisns, kas savā taisnībā iet bojā, un cits ir bezdievīgs, kas savā blēdībā ilgi pastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Neesi pārlieku taisns un neturies pats par visai gudru, - kāpēc tu gribi iet bojā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Neesi pārlieku bezdievīgs, un neesi visai ģeķīgs; kāpēc tu gribi nomirt nelaikā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Labi ir, ka tu šo satver un arī no tā otra savu roku neatrauj; jo kas Dievu bīstas, tas no visa tā izsprūk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Gudrība stiprina gudro vairāk nekā desmit vareni, kas ir pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Tiešām, nav neviena cilvēka, kas taisns būtu virs zemes, kas labi darītu un negrēkotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Neliec arī vērā visus vārdus, kas top runāti, lai tev nav jādzird, ka tavs kalps tev lād.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Jo daudzkārt arī tava sirds zin, ka arī tu citus esi lādējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Visu šo es ar gudrību esmu izmeklējis. Es sacīju: es dabūšu gudrību, bet viņa bija vēl tālu no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Tālu ir, kas ir, un ļoti dziļš; kas to var atrast?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Es griezos ar savu sirdi, ka es zinātu un izvaicātu un meklētu gudrību un skaidrību, un ka es atzītu bezdievību par ģeķību un neprātību par nelietību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Un es atradu vienu lietu rūgtāku nekā nāvi: sievu, kā sirds ir tīkli un valgi un kā rokas ir saites. Kas labs ir Dieva priekšā, tas no viņas izglābsies, bet grēcinieks caur viņu taps sagūstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Redzi, šo esmu atradis, saka tas mācītājs, citu pēc cita, ka es to galavārdu atrastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'To mana dvēsele vēl meklē, un to es vēl neesmu atradis: Starp tūkstošiem es vienu vīru esmu atradis, bet sievu starp šiem visiem es neesmu atradis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Bet redzi, to tikai es esmu atradis, ka Dievs cilvēku ir radījis taisnu, bet tie dodas uz daudz gudrošanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kas ir kā gudrais un kas zin sacīt, kādas tās lietas ir? Cilvēka gudrība dara gaišu viņa vaigu un viņa bargums pārvēršās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Es (saku): liec vērā ķēniņa pavēli, kā tu Dievam esi zvērējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Nesteidzies no viņa vaiga iet nost, netinies nekādā ļaunā darbā; jo visu, ko viņš grib, to viņš dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Kur ķēniņa vārds ir, tur ir vara, un kas uz viņu var sacīt: ko tu dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kas bausli tur, tas neredzēs ļauna; un gudra sirds zin laiku un tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Jo ikkatram padomam ir savs laiks un sava tiesa; jo cilvēka ļaunums to smagi spiež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Jo viņš nezin, kas notiks un kas viņam sacīs, kā tas būs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Cilvēka nav, kam būtu vara pār garu, to garu aizturēt; viņam arī nav varas pār miršanas dienu, un nav atlaišanas karā; tā arī bezdievība to neizglābs, kas to dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Visu to es esmu redzējis, un esmu griezis savu sirdi uz ikvienu darbu, ko dara pasaulē. Dažkārt cilvēks pār cilvēku valda sev par nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Es arī vēl redzēju bezdievīgus, kas tika aprakti un nāca pie dusas; bet tālu aizgāja no svētās vietas un tika aizmirsti pilsētā, kas bija darījuši taisnību; arī tā ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Kad tiesu par ļauno darbu nenes drīzumā, tad cilvēku bērnu sirds paliek droša, ļaunu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Jebšu grēcinieks simts reizes ļaunu dara un dzīvo ilgi, tomēr es zinu, ka dievbijīgiem labi klāsies, kas priekš viņa bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Bet bezdievīgam labi neklāsies, un viņš ilgi nedzīvos, tā kā ēna; tādēļ ka viņš priekš Dieva nebīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Niecība ir, kas notiek virs zemes, ka ir taisni cilvēki, kam tā klājās, tā kā būtu darījuši bezdievīgi, un ir bezdievīgi, kam tā klājās, tā kā būtu darījuši taisni; es sacīju: arī tā ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Tādēļ es slavēju to prieku, ka cilvēkam cita labuma nav pasaulē, kā vien ēst un dzert un priecāties, un tas viņam atlec no viņa pūliņa viņa dzīvības laikā, ko Dievs viņam dod pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Kad es apņēmos, gudrību atzīt un ieraudzīt to grūtumu, kas virs zemes notiek, ka dažs ne dienu ne nakti miegu neredz savām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Tad es redzēju visu Dieva darbu, ka cilvēks to darbu nevar izprast, kas notiek pasaulē; jebšu cilvēks darbojās izdomāt, tomēr viņš to neizdibinās, un jebšu arī tas gudrais sacītu, ka viņš to zina, tomēr viņš to nevar atrast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Tiešām, visu to es esmu ņēmis pie sirds, visu to skaidri saprast, ka taisnie un gudrie ar saviem darbiem ir Dieva rokā. Un cilvēks arī nezin, vai piedzīvos mīlestību vai ienaidību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Visas lietas notiek visiem vienlīdzīgi, un viens liktenis taisnam un bezdievīgam, labam un šķīstam kā arī nešķīstam, tam, kas upurē, kā tam, kas neupurē, labam kā grēciniekam, tam, kas aplam zvēr, kā arī tam, kas no zvēresta bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Tā ir ļauna lieta pie visa, kas notiek pasaulē, ka visiem viens liktenis; un arī cilvēku bērnu sirds ir pilna ļaunuma, un neprātība ir viņu sirdīs, kamēr tie dzīvo, un pēc tiem jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Jo kas vien vēl dzīvs, priekš tā ir cerība; jo dzīvs suns ir labāks nekā nomiris lauva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Jo tie dzīvie zin, ka tiem jāmirst; bet tie nomirušie nezin it nekā, tiem arī vairs nav algas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Bet viņu piemiņa ir aizmirsta, un viņu mīlestība un viņu naids un viņu skaudība jau ir iznīkusi, un tiem nav vairs daļas ne mūžam pie nekā, kas notiek pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Ej tad, ēd savu maizi ar prieku, un dzer savu vīnu ar labu prātu; jo Dievam jau ir labs prāts pie tava darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Lai tavas drēbes allažiņ ir baltas, un eļļas lai tavai galvai netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Baudi šo dzīvību ar to sievu, ko tu mīļo, kamēr tev ir šī niecīgā dzīvība, ko viņš tev ir devis pasaulē, visu savu niecīgo mūžu; jo šī ir tava daļa šinī mūžā un pie tava pūliņa, ar ko tu pūlējies pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Visu, ko tava roka atrod, kas jādara, to dari tikuši(ar visu spēku), jo ne darba, ne padoma, ne ziņas, ne gudrības nav kapā, kur tu noej.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Atkal es redzēju pasaulē, ka pie skriešanas nepalīdz čaklam būt, pie karošanas nepalīdz stipram būt, pie maizes pelnīšanas nepalīdz gudram būt, pie bagātības nepalīdz prātīgam būt, pie goda nepalīdz mācītam būt, bet tiem visiem nāk savs laiks un sava laime.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Un cilvēks arī nezin savu laiku; kā zivis, kas top zvejotas ar ļaunu tīklu, un kā putniņi, kas ar valdziņiem top notverti, tāpat cilvēku bērni top savaldzināti nelabā dienā, kad tā piepeši tiem uzbrūk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Arī šo gudrību es esmu redzējis pasaulē, un tā man rādījās liela:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Maza pilsēta un ne daudz ļaužu iekš tās, un pret to nāca liels ķēniņš un to apstāja un uztaisīja lielas skanstes* ap viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Un tur atradās nabaga vīrs, tas bija gudrs, tas to pilsētu izpestīja caur savu gudrību, un neviens cilvēks šo nabaga vīru nepieminēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Tad es sacīju: gudrība ir labāka nekā stiprums, un tomēr tā nabaga gudrība top nicināta, un viņa vārdi netop klausīti');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Gudro vārdi, kas mierā top klausīti, ir labāki, nekā valdnieka brēkšana ģeķu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Gudrība ir labāka nekā kara bruņas; bet viens vienīgs blēdis samaitā daudz labuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Nosprāgušas mušas dara smirdam un rūgstam aptiekāra zāles; tāpat no lielāka svara, nekā gudrība un gods, ir maķenīt ģeķības (tāpat arī mazliet ģeķības pārsver cienījama vīra gudrību un godu).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Gudra vīra sirds ir pa viņa labo roku, bet ģeķa sirds ir pa viņa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Un arī kad ģeķis pa ceļu staigā, tad viņam prāta trūkst, un viņš saka uz ikkatru, ka esot ģeķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Ja valdnieka dusmība pret tevi ceļas, tad neatstājies no savas vietas, jo lēnprātība klusina lielus grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Vēl ir ļaunums, ko pasaulē esmu redzējis, proti misēklis, kas ceļas no valdnieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Dažs ģeķis top celts lielā godā, un bagātie sēž zemajā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Es esmu redzējis kalpus uz zirgiem, un lielus kungus kājām tāpat kā kalpus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kas bedri rok, tas kritīs iekšā; un kas sētu ārda, tam čūska iedzels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kas akmeņus veļ, tas no tiem dabūs sāpes; kas malku skalda, tas ievainosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Kad dzelzs ir nodilusi un viņas asmens netop tecināts(asināts), tad vairāk spēka jāpieliek; bet gudrība veicina darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Kad čūska iedzēlusi, pirms apvārdota, tad vārdotājam peļņas nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Vārdi no gudra vīra mutes ir jauki; bet ģeķa lūpas pašu aprij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Viņa mutes vārdu iesākums ir ģeķība, un viņa valodas gals ir neprātība un posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Ģeķis gan daudz runā, bet cilvēks nezin, kas notiks, un kas būs pēc viņa; kas viņam to teiks?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Ģeķa pūliņš to nogurdina, jo tas nezina ceļu uz pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Ak vai, tev, zeme, kam ķēniņš ir bērns, un kam lielkungi rīta laikā plītē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Labi tev, zeme, kam ķēniņš ir cienījams, un kam lielkungi īstā laikā ēd, stiprināties un ne plītēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Caur kūtrību sijas gāžas, un aiz slinkām rokām namam pil cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Dzīres top taisītas par prieku, un vīns ielīksmo tos, kas dzīvo, un nauda visu to gādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Nelādi ķēniņu savā sirdī, un nelādi bagātu savā guļamā kambarī, jo putni apakš debess aiznes to skaņu un ar spārniem skriedami izpauž to valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Met savu maizi ūdenī, ar laiku tu to atdabūsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Izdali to septiņiem vai astoņiem, jo tu nezini, kāda nelaime būs virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Kad padebeši pilni, tad tie izlej lietu uz zemi; un kā koks kritīs pret dienvidu vai pret ziemeli, - kur koks krīt, tur tas arī paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kas uz vēju mana, tas nesēj, un kas uz padebešiem raugās, tas nepļauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Tā kā tu nezini, kāds ceļš ir vējam, jeb kā kauli aug grūtas sievas miesās, tāpat tu nezini Dieva darbu, ko Viņš visu padara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'No rīta sēj savu sēklu un neliec mierā savu roku vakarā; jo tu nezini, kā jo labi izdosies, vai šā vai tā; un kad abējādi izdotos, tad būtu jo labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Gaišums ir salds un acīm tīk sauli redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Bet jebšu cilvēks daudz gadus dzīvo un arvienu priecājās, tad lai tomēr viņš arī piemin tās nebaltās dienas, jo viņu būs daudz. Viss, kas nāk, ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Priecājies, jaunekli, savā jaunībā, un lai tava sirds tur labu prātu savas jaunības dienās, un staigā kā tava sirds kāro un kā tavām acīm patīk; bet zini, ka Dievs par visu šo tevi vedīs priekš tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Tad izmet nu skumību no savas sirds un aizdzen ļaunumu no savām miesām; jo jaunība un rīta blāzma(bērnība) ir niecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Piemini savu Radītāju savā jaunībā, pirms tās ļaunās dienas nāk un tie gadi tuvojās, kur tu sacīsi: tie man nepatīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Pirms saule un gaišums un mēnesis un zvaigznes aptumšojās, un padebeši nāk atkal pēc lietus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Tai laikā, kad tie nama sargi trīcēs, un tie stiprie vīri locīsies, un tie malēji stāvēs klusu, tāpēc ka viņu palicis maz, un tie, kas pa logiem skatās, paliks tumši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Un tās divas durvis pret ielu taps aizslēgtas, tā ka malšanas skaņa paliks lēnāka, un viņš uzmostas, kad putniņa balsi dzird, un kad klusu skan visas dziesmas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Kad arī kalnus bīsies un baiļosies, pa ceļu ejot, un kad tas mandeļu koks ziedēs, un sisenis būs par nastu, un līksmība zudīs; jo cilvēks iet uz savu mūža namu, un tie žēlotāji ies apkārt pa ielām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Pirms tā sudraba virve trūks, un tas zelta trauks saplīst un tas smeļamais pie avota izkalst, un tas skritulis pie akas salūst;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Jo pīšļiem būs atkal zemē griezties, kā tie ir bijuši, un garam atkal pie Dieva, kas to ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Niecība vien! saka tas mācītājs, viss ir niecība!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Nu vēl atliek: šis mācītājs bija gudrs, un viņš ļaudīm mācīja atzīšanu, un sadomāja un izmeklēja un sastādīja daudz sakāmus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Tas mācītājs meklēja, skaistus vārdus atrast un taisnības vārdus pareizi sarakstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Gudru vīru vārdi ir kā dzenuļi, un kā iesistas naglas viņu (atziņas) krājumi, no viena Gana doti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Un beidzot: sargies, mans dēls! Grāmatu rakstīšanai nav gala un daudz lasīšanas nopūlē miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Visas mācības gala vārds ir šis: bīsties Dievu un turi Viņa baušļus, jo tas pienākas visiem cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Jo Dievs ikkatru darbu vedīs tiesā līdz ar visu, kas ir apslēpts, vai tas labs vai ļauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Salamana augstā dziesma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Lai viņš mani skūpsta ar savas mutes skūpstīšanu; jo tava mīlestība ir jo mīlīgāka nekā vīns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Tavai eļļai ir salda smarža; tavs vārds ir izlieta eļļa, tāpēc jaunavas tevi mīl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Velc mani, tad mēs tev tecēsim pakaļ; ķēniņš mani ved savos kambaros; mēs līksmosimies un priecāsimies par tevi; mēs pieminēsim tavu mīlestību vairāk nekā vīnu; patiesīgi tevi mīl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Es esmu melna, bet mīlīga, jūs Jeruzālemes meitas, tā kā Ķedara teltis, kā Salamana gardīnes(aizkari).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Neuzlūkojiet mani, ka esmu pamelna, jo saulē esmu nodegusi; manas mātes bērni pret mani apskaitušies, tie mani likuši par vīna dārzu sargātāju; savu pašu vīna dārzu neesmu apsargājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Saki man, tu, ko mana dvēsele mīl, kur tu gani, kur tu gulies pusdienā? Jo kāpēc man būs aloties pie tavu biedru ganāmiem pulkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Ja tu to nezini, tu visu skaistākā starp sievām, tad ej jel pa avju pēdām un gani savus kazlēnus pie ganu teltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Es tevi līdzināju, mana draudzene, ar tiem zirgiem pie Faraona ratiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Tavi vaigi ir mīlīgi sprādzēs, tavs kakls pērļu rotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Mēs tev taisīsim zelta sprādzes ar sudraba podziņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Kamēr ķēniņš pie galda, mana nardes puķīte dod savu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mans draugs man ir mirru pušķis, pie manām krūtīm piesprausts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mans draugs man ir vīna ķekars Enģedi vīna dārzos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Redzi, tu esi skaista, mana draudzene, redzi, tu esi skaista, tavas acis ir kā baložu acis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Redzi, tu esi skaists, mans draugs, un mīlīgs, un mūsu dusas vieta zaļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Mūsu namu baļķi ir ciedri, mūsu sijas ir cipreses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Es esmu roze Šaronā un lilija ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Tā kā lilija starp ērkšķiem, tāda ir mana draudzene starp tām meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Tā kā ābele starp meža kokiem, tāds ir mans draugs starp tiem dēliem. Es ilgojos sēdēt viņa pavēnī, un viņa auglis manai mutei salds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Viņš mani ved vīna namā, un mīlestība ir viņa karogs pār mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Atspirdzinājiet mani ar vīna ogām un spēcinājiet mani ar āboliem; jo es nīkstu no mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Viņa kreisā roka ir apakš manas galvas, un viņa labā roka mani apkampj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Es jūs mīļi lūdzu, jūs Jeruzālemes meitas, pie tām stirnām un kalnu kazām laukā, neuztraucat un nemodinājat mīlestību, kamēr tai pašai patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Šī ir mana drauga balss; redzi, viņš nāk un lēkā pa tiem kalniem un deij pa tiem pakalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mans draugs ir līdzīgs stirnai vai jaunam briedim. Redzi, viņš stāv aiz sienas, skatās caur logiem un raugās caur skadriņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mans draugs atbild un saka uz mani: celies, mana draudzene, mana skaistā, un nāc!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Jo redzi, ziema ir pagājusi, stiprais lietus jau ir pārgājis un nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Puķes rādās laukā, dziesmu laiks atnācis, un ūbeles balss dzirdama mūsu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Vīģes koks dabūjis pumpurus, un vīna koki plaukst un dod smaržu; celies, nāc, mana draudzene, mana skaistā, nāc šurp!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Mans balodis akmeņu kalnos, apslēptos plaisumos, parādi man savu vaigu, dod man savu balsi dzirdēt; jo tava balss ir salda, un tavs vaigs ir mīlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Gūstat mums lapsas, tās mazās lapsas, kas vīna dārzus maitā, jo mūsu vīna dārzi stāv ziedos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mans draugs ir mans, es esmu viņa, kas pa tām lilijām gana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Kamēr diena metās dzestra un ēnas bēg, atgriezies, mans draugs, kā stirna, vai kā jauns briedis pa kalnu plaisumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Naktī savā gultā es meklēju to, ko mana dvēsele mīl; es meklēju, bet viņu neatradu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Es celšos jel un iešu pilsētā apkārt pa gatvēm un ielām; es meklēšu to, ko mana dvēsele mīl. Es meklēju, bet viņu neatradu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Sargi mani atrada, kas pilsētā iet apkārt: vai jūs neesat redzējuši to, ko mana dvēsele mīl?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Kad es maķenīt tiem biju pagājusi garām, tad es atradu to, ko mana dvēsele mīl; es viņu turu un to neatlaidīšu, kamēr es viņu vedīšu savas mātes namā, savas dzemdētājas kambarī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Es jūs mīļi lūdzu, jūs Jeruzālemes meitas, pie tām stirnām un kalnu kazām, neuztraucat un nemodinājat mīlestību, kamēr tai pašai patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kas ir šī, kas no tuksneša nāk kā dūmu stabs, apkvēpināta ar mirrēm un vīraku, ar visādām veikalnieku zālēm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Redzi, ap Salamana krēslu apkārt ir sešdesmit varoņi no Israēla varoņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Tie visi tur zobenus, mācīti karot; ikkatram savs zobens pie gurniem pret nakts bailēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Ķēniņš Salamans sev licis taisīt nesamu krēslu no Lībanus kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Viņa stabus viņš taisīja no sudraba, to lēni no zelta, to sēdekli no purpura, viņa iekšpuse bija izpušķota no Jeruzālemes meitu mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Ejat ārā un uzlūkojiet, Ciānas meitas, ķēniņu Salamanu ar to kroni, ar ko viņa māte to kronēja viņa kāzu dienā un viņa sirds līksmības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Redzi, tu esi skaista, mana draudzene, redzi, tu esi skaista; tavas acis ir kā baložu acis aiz tava galvas apsega. Tavi mati ir kā kazu pulks, kas guļ uz Gileād kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Tavi zobi ir kā avju pulks, kas cirptas un iznāk no peldēšanas, kas visas dvīņus vedās, un neviena starp viņām nav neauglīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Tavas lūpas ir kā purpura aukla, un tava mute ir mīlīga. Tavi vaigi ir kā granātābola puses aiz tava galvas apsega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Tavs kakls ir kā Dāvida tornis, kas taisīts, lai tur ieročus uzkar, kur tūkstošas priekšturamās bruņas uzkārtas, visādas stipru vīru bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Tavas krūtis ir kā divas jaunas stirnas, kā kalnu kazas dvīņi, kas liliju starpā ganās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Kad diena metās dzestra, un ēnas bēg, tad iešu pie mirru kalna un pie vīraka pakalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Tu esi visai skaista, mana draudzene, un pie tevis nav vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Nāc man līdz no Lībanus, mana brūte, nāc man līdz no Lībanus. Skaties no Amana kalna gala, no Senira un Hermona gala, no lauvu alām, no leopardu kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Tu man sirdi esi paņēmusi, mana māsa, mīļā brūte; tu man sirdi esi paņēmusi ar vienu actiņu, ar vienu kakla ķēdīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Cik skaista ir tava mīlestība, mana māsa, mīļā brūte! Cik labāka ir tava mīlestība pār vīnu, un tavas eļļas smarža pār visām kvēpināmām zālēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Tavas lūpas, ak brūte! Pil no kausētā medus; medus un piens ir apakš tavas mēles, un tava drēbju smarža ir kā Lībanus smarža.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Tu esi aizslēgts dārzs, mana māsa, mīļā brūte, aizslēgts avots, aizslēgta aka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tavi zari ir kā jauks dārzs, kur granātu ābeles ar dārgiem augļiem, kovera puķes ar nardēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Narde un safrans, kalmes un kanēlis, ar visādiem vīraka kokiem, mirres un alvejas, līdz ar vislabākām smaržīgām zālēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Tā kā dārzu aka (tu esi), kā aka ar dzīvu ūdeni, un kā strauti no Lībanus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Celies, ziemeli, un nāc, dienvidu vējš, pūt pa manu dārzu, ka viņa zāles pil (smaržas no dārza augiem). Mans draugs lai nāk savā dārzā, un lai ēd savus skaistos augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Es nāku savā dārzā, mana māsa, mīļā brūte; es plūcu savas mirres un savu balzamu, es ēdu savas šūnas ar savu medu, es dzeru savu vīnu un savu pienu. Ēdiet, mīļie, dzeriet un padzeraties, draugi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Es guļu, bet mana sirds ir nomodā; tā ir mana drauga balss, kas klaudzina: atdari man, mana māsa, mana draudzene, mans balodis, mana sirds skaidrā; jo mana galva ir rasas pilna, mani mati ar nakts lāsēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '„Es savus svārkus esmu novilkusi, kā man tos atkal būs apvilkt? Es savas kājas esmu mazgājusi, kā man tās atkal būs darīt netīras?“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mans draugs savu roku stiepa pa logu, un mana sirds par to trīcēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Es pacēlos, savam draugam atdarīt, un no manām rokām pilēja mirres un no maniem pirkstiem tekošas mirres pie durvju atslēgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Es savam draugam atdarīju, bet mans draugs bija projām, viņš bija aizgājis. Mana dvēsele izgāja pēc viņa vārdiem. Es viņu meklēju, bet es viņu neatradu; es viņu saucu, bet viņš man neatbildēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Sargi, kas pilsētā iet apkārt, mani atrada; mani sita un mani ievainoja; tie mūru sargi norāva manu apsegu no manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Es jums piekodināju, Jeruzālemes meitas, kad jūs manu draugu atrodat, ko jūs viņam sacīsiet? Ka es esmu apsirgusi no mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Kāds tad ir tavs draugs pār citiem draugiem, tu visuskaistākā starp sievām? Kāds ir tavs draugs pār citiem draugiem, ka tu mums tā esi piekodinājusi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mans draugs ir balts un sarkans, pārāks pār tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Viņa galva ir visušķīstākais zelts, viņa mati ir kupli jo kupli, melni kā krauklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Viņa acis ir kā baložu acis pie ūdens strautiem, ar pienu mazgātas, skaistā pilnumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Viņa vaigi ir kā balzama dobes, tā kā smaržīgas puķes uz pakalniem. Viņa lūpas ir kā rozes, kur pil tekošas mirres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Viņa rokas ir kā zelta gredzeni ar turķizu akmeņiem pildīti. Viņa miesa ir kā daiļš ziloņkaulu darbs, ar safīriem pušķots;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Viņa lieli ir kā marmora pīlāri uz visšķīstākā zelta pamatiem. Viņa augums ir kā Lībanus, dižens kā ciedri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Viņa mute ir salda, un visa viņa būšana ļoti mīlīga. Tāds ir mans draugs, un tāds ir mans mīļākais, Jeruzālemes meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kurp tavs draugs ir nogājis, tu visu skaistākā starp sievām? Uz kuru pusi tavs draugs ir griezies, ka mēs līdz ar tevi viņu meklējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mans draugs ir nogājis savā dārzā, pie tām smaržīgām dobēm, pa dārzu pastaigāties un lilijas lasīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Mans draugs ir mans un es esmu viņa, kas starp lilijām gana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Tu esi skaista, mana draudzene, tā kā Tirca, mīlīga kā Jeruzāleme, briesmīga kā kara spēki ar karogiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Nogriez savas acis no manis, jo tās mani pārvarējušas. Tavi mati ir kā kazu pulks, kas guļ uz Gileād kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Tavi zobi ir kā avju pulks, kas nāk no peldēšanas, kas visas dvīņus vedās, un neviena starp viņām nav neauglīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Tavi vaigi ir kā granātābola puses aiz tava galvas apsega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Sešdesmit ir ķēniņienes un astoņdesmit liekas sievas un tas jaunavu pulks nav izskaitāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Bet viena vienīga ir mans balodis, mana sirds skaidrā, tā vienīgā savai mātei, tā mīļākā savai dzemdētājai. Kad tās meitas viņu redz, tad tās viņu teic, ķēniņienes un liekās sievas viņu slavē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kas tā tāda, kas spīd kā auseklis, skaista kā mēnesis, skaidra kā saule, briesmīga kā karaspēki ar karogiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Es nogāju riekstu dārzā, redzēt zaļos augļus pie upes, un lūkot, vai vīna koks zied un granātu koki plaukst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Es nesajutu, ka mana dvēsele mani bija pacēlusi uz manas slavētās tautas goda ratiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Atgriezies, atgriezies, ak Sulamite! Atgriezies, atgriezies, ka mēs tevi varam skatīt. Ko jūs redzat pie Sulamites? Kā diešanu pie Mahānaīma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Cik skaisti ir tavi soļi kurpēs, tu valdnieka meita. Tavi gurni tā ir salikti kā divas sprādzes, ko gudra meistara roka darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Tavs klēpis ir kā apaļš biķeris, kam dzēriena netrūkst; viņš ir kā kviešu kopa, apsprausta ar lilijām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Tavas krūtis ir kā divas stirnas, kā kalnu kazas dvīņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Tavs kakls ir kā tornis no ziloņkauliem, tavas acis ir kā tie dīķi Hešbonē pie Batrabim vārtiem, tavs deguns ir kā tornis uz Lībanus, kas pret Damasku skatās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Tava galva uz tevis ir kā Karmels, un tavi kuplie galvas mati kā purpurs, ķēniņš ar bizēm saistīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Cik skaista un cik mīlīga tu esi, ak mīlestība ar saviem jaukumiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Šis tavs augums ir līdzīgs palma kokam un tavas krūtis vīna ķekariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Es sacīšu: es kāpšu uz palma koku, es tveršu viņa zarus, lai tavas krūtis ir kā ķekari pie vīna koka, un tava vaiga smarža kā āboli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Un tava mute kā labs vīns, kas manam draugam viegli ieiet un miegaino lūpas dara runājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Es piederu savam draugam, un sirds viņam nesās uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Nāc, mans draugs, ejam laukā, mitīsim ciemos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Iesim agri uz vīna dārziem, lūkosim, vai vīna koks zied, vai jaunie pumpuri sprāgst, un granātu koki plaukst. Tur es tev rādīšu savu mīlestību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Tie dudaīm dod smaržu, un pie mūsu durvīm ir visādi dārgi augļi, jauni un veci; mans draugs, es tos priekš tevis esmu glabājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Kaut tu būtu mans brālis, kas zīdis manas mātes krūtis? Kad es tevi atrastu ārā, es tevi skūpstītu un netaptu nicināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Es tevi vadītu, es tevi vestu savas mātes namā, ka tu mani mācītu; tad es tev dotu dzert jauktu vīnu un no savu granātābolu sulas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Viņa kreisā roka ir apakš manas galvas, un viņa labā roka mani apkampj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Es jūs mīļi lūdzu, Jeruzālemes meitas, ko jūs uztraucat un modinājāt mīlestību, pirms tai pašai patīk?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kas tā tāda, kas nāk no tuksneša un atslienas uz savu draugu? Apakš ābeles es tevi esmu uzmodinājis; tur tava māte tevi ar sāpēm ir dzemdējusi, tur sāpes ir bijušas tavai dzemdētājai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Liec mani kā zieģeli pie savas sirds, kā gredzenu pie savas rokas! Mīlestība ir stipra kā nāve un viņas karstums ir varens kā elle; viņas liesmas ir degošas liesmas, Dieva liesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Lieli ūdeņi mīlestību nevar apdzēst, nedz upes viņu apslīcināt. Jebšu kas visu sava nama mantu gribētu dot par mīlestību, tomēr viņš paliktu tikai par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Mums ir viena maza māsa, kam krūšu vēl nav, - ko mēs ar savu māsu darīsim tai dienā, kad viņu precēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Ja viņa ir mūris, tad mēs uz viņu uztaisīsim sudraba torni; ja viņa ir durvis, tad mēs tās sargāsim ar ciedru dēļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Es biju mūris un manas krūtis bija kā torņi; tad es viņa acīs atradu mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salamanam bija vīna dārzs BaālAmonā, šo vīna dārzu viņš izdeva sargiem, ikviens par viņa augļiem deva tūkstoš sudraba gabalus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Mans vīna dārzs, kas man pieder, ir manā priekšā. Tie tūkstoš sudraba gabali ir priekš tevis, Salaman! Bet divsimt ir priekš viņa augļu sargiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Tu, kas tais dārzos dzīvo, tie biedri tavu balsi ņem vērā, dodi man to dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Steidzies, mans draugs, un esi tā kā stirna vai kā jauns briedis pa smaržīgiem puķu kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Jesajas, Amoca dēla, parādīšana, ko viņš redzējis par Jūdu un Jeruzālemi Uzijas, Jotama, Ahaza un Hizkijas, Jūda ķēniņu, dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Klausāties, debesis, un ņem vērā, zeme, jo Tas Kungs runā: “Bērnus Es esmu uzaudzinājis un izvilcis, bet tie no Manis atkāpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Vērsis pazīst savu kungu un ēzelis sava kunga sili; Israēls nepazīst, Mani ļaudis nesaprot.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ak vai, tai grēcīgai tautai, tiem ļaudīm, kas grūti noziegušies, tam ļaundarītāju dzimumam, tiem bērniem, kas samaitājās; tie ir atstājuši To Kungu, nicinājuši to Svēto iekš Israēla, nogriezušies atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Par ko jūs vēl vairāk būs sist, kad jūs vienmēr atkāpjaties? Visa galva ir vāja, un visa sirds nogurusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'No pēdas līdz pat galvai tur nav veseluma, bet vātis un brūces un jaunas vainas, kas nav izspiestas nedz sasietas nedz ar eļļu mīkstinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Jūsu zeme ir postaža, jūsu pilsētas ar uguni sadedzinātas, jūsu tīrumus, sveši ļaudis tos ēd, jums klāt esot, un ir posts, kā sveši ļaudis posta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Un Ciānas meita atlikusi kā būdiņa vīna dārzā, tā kā pieguļnieka vietiņa gurķu dārzā, kā aplēģerēta pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ja Tas Kungs Cebaot mums nebūtu atlicinājis kādu mazumu, mēs būtu kā Sodoma, mēs būtu tā kā Gomora.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Klausiet Tā Kunga vārdu, Sodomas virsnieki, ņemiet vērā mūsu Dieva mācību, Gomoras ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Kas man no jūsu upuru pulka? Saka Tas Kungs; Es esmu apnicis aunu dedzināmos upurus un barotu teļu taukus, un vēršu un jēru un āžu asinis Es negribu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Kad jūs nākat parādīties Manā priekšā, kas to no jums prasa, ka jūs saminat Manus pagalmus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Nenesiet vairs nelietīgu ēdamu upuri, tā Man ir neganta kvēpināšana; jaunos mēnešus un svētdienas un draudzes sapulces Es neieredzu, jūsu svētki ir blēdība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Mana dvēsele ienīst jūsu jaunos mēnešus un jūsu svētku laikus. Tie Man ir par nastu, Es esmu piekusis tos panest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Un kad jūs savas rokas izpletīsiet, Es apslēpju Savas acis no jums, un kad jūs daudz lūgšanas turiet, tomēr Es neklausu, jo jūsu rokas ir asiņu pilnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Mazgājaties, šķīstaties, atmetat savus ļaunos darbus no Manām acīm nost, nedarāt vairs ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Mācieties labu darīt, meklējat tiesu, atgriežat varas darītāju, izdodiet bāriņam tiesu, aizstāviet atraitni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Tad nāciet nu, tiesāsimies, saka Tas Kungs: kad jūsu grēki tik sarkani būtu kā asinis, taču tie taps balti kā sniegs, un jebšu tie būtu kā purpurs, taču tie kļūs tāpat kā vilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Ja jūs gribēsiet un klausīsiet, tad jūs ēdīsiet zemes labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Bet ja jūs liedzaties un turaties pretī, tad jūs no zobena tapsiet aprīti; jo Tā Kunga mute to runājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Kā tā ticīgā pilsēta palikusi par mauku? Tā bija pilna tiesas, taisnība tur mājoja, bet nu slepkavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Tavs sudrabs ir tapis par sārņiem, tavs vīns ir jaukts ar ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Tavi virsnieki ir atkāpēji un zagļu biedri; tie visi kāro dāvanas un dzenās pēc maksas; bāriņam tie neizdod tiesu un atraitnes sūdzība nenāk viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Tādēļ saka Tas Kungs Dievs Cebaot, Israēla Varenais: ak vai! Es iepriecināšos par Saviem pretiniekiem, es atriebšos pie Saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Un Es griezīšu Savu roku pret tevi un tīrīšu kā ar sārmu tavus sārņus un nošķiršu visu tavu alvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Un Es tev atkal došu soģus kā senāk, un padoma devējus kā vecos laikos. Pēc tam tu tapsi saukta taisnības pils, ticīgā pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Ciāna caur tiesu taps izpestīta un viņas(dēli) atgriezīsies caur taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Bet tie pārkāpēji un grēcinieki visi taps satriekti, un kas no Tā Kunga atkāpjās, ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Jo tie taps kaunā to ozolu dēļ, ko jūs bijāt iekārojuši, un jūs kaunēsities to dārzu dēļ, ko bijāt izredzējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Jo jūs būsiet tā kā ozols, kam lapas savīst, un kā dārzs, kam ūdens nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Tad varenais būs kā pakulas, un viņa darbs kā dzirkstele, un abi kopā degs un nebūs neviena, kas dzēš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Šis ir tas vārds, ko Jesaja, Amoca dēls, redzējis par Jūdu un Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Un notiks pastara laikā, tad Dieva nama kalns stāvēs pāri pār visiem kalniem un būs paaugstināts pār pakalniem, un visi pagāni uz viņu plūdīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Un daudz tautas ies un sacīs: ejam, kāpsim uz Tā Kunga kalnu, uz Jēkaba Dieva namu, lai Viņš mums māca Savus ceļus, un lai staigājam Viņa tekās, jo no Ciānas iziet mācība, un Tā Kunga vārds no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Un Viņš tiesās starp pagāniem un pārmācīs daudz tautas, un tie pārkals savus zobenus par lemešiem un savus šķēpus par cirpēm(ecešām). Jo tauta pret tautu nepacels zobenu un vairs nemācīsies karu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Jēkaba nams, nāc, staigāsim Tā Kunga gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Bet Tu esi atstājis Savus ļaudis, Jēkaba namu, jo tie ir pilni austruma ļaužu (bezdievības) un ir zīlnieki tā kā Fīlisti, un ar svešinieku bērniem tiem ir draudzība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Un viņu zeme ir pilna sudraba un zelta, un mantas tiem bez gala, un viņu zeme ir pilna zirgu, un ratu tiem bez gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Un viņu zeme ir pilna elka dievu, un savu roku darbu tie pielūdz, to, ko pašu pirksti taisījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Bet ļaudis tiek pazemoti, un vīri gāzti, un piedot tu viņiem nepiedosi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Lieni klints alā un paslēpies pīšļos priekš Tā Kunga iztrūcināšanas un priekš viņa augstās godības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Ļaužu lepnās acis taps pazemotas, un vīru augstība taps locīta, bet Tas Kungs vien būs augsts tanī dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Jo Tā Kunga Cebaot diena būs pret visu lepnumu un lielumu, un pret visu augstumu, ka tas top pazemots,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Un pret visiem lieliem un augstiem Lībanus ciedru kokiem un pret visiem Basanas ozoliem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Un pret visiem lieliem kalniem un pret visiem augstiem pakalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Un pret visiem augstiem torņiem un pret visiem stipriem mūriem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Un pret visiem jūras kuģiem un pret visiem skaistiem tēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Un ļaužu lepnība taps locīta, un vīru augstība pazemota, bet Tas Kungs vien būs augsts tanī dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Un elkadievi ies pavisam bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Tad ies kalnu alās un zemes plaisumos priekš Tā Kunga iztrūcināšanas un priekš viņa augstās godības, kad viņš celsies, iztrūcināt zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Tai dienā cilvēks savus sudraba elkus un savus zelta elkus, ko tie sev bija taisījuši pielūgt, nometīs kurmjiem un sikspārņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Un ies klints aizās un kalnu alās, priekš Tā Kunga iztrūcināšanas un priekš Viņa augstās godības, kad Viņš celsies, iztrūcināt zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Tad nepaļaujaties uz cilvēku, kam dvaša nāsīs; jo par ko tas turams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Jo redzi, Tas Kungs Dievs Cebaot atņems no Jeruzālemes un Jūda patvērumu un padomu, visu maizes padomu un visu ūdens padomu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Vareno un karavīru, soģi un pravieti un gudro un vecaju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Virsnieku pār piecdesmit un godināto un padoma devēju un amata pratēju un apvārdotāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Un Es viņiem došu puikas par virsniekiem, un nesaprašas pār viņiem valdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Un tie ļaudis māksies virsū cits citam, ikkatrs savam tuvākam, puika trakos pret sirmgalvi un nelga pret cienīgo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Tad satvers viens otru sava tēva namā un (sacīs): tev ir drēbes, esi mums par virsnieku, un lai tava roka nogriež šo postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Bet viņš tai dienā atbildēs un sacīs: es negribu būt tas dziedinātājs, manā namā ne maizes ne drēbju, neceļat mani par ļaužu virsnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Jo Jeruzāleme gruvusi, un Jūda ir kritis, tādēļ kā viņu mēles un darbi ir pret To Kungu, kaitināt Viņa godības acis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Viņu vaiga izskats dod liecību pret viņiem, un savus grēkus tie izteic, tā kā Sodoma, un tos neapslēpj. Vai viņu dvēselēm! Jo tie sev pašiem dara ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Sakait par taisno, ka tam labi klāsies, jo tas ēdīs savu darbu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Ak vai, tam bezdievīgam! Tam labi neklāsies, jo pēc viņa rokas darba viņam taps maksāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Mani ļaudis! Viņu dzinēji ir bērni, un sievas valda pār tiem; Mani ļaudis! Tavi vadoņi tevi maldina un to ceļu, kur tev jāstaigā, tie samaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Tas Kungs ceļas, tiesāties un stāv, tiesu spriest tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Tas Kungs nāk uz tiesu ar Savu ļaužu vecajiem un viņu lieliem kungiem: un jūs to vīna dārzu esat noēduši; nabaga laupījums ir jūsu namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Kas jums prātā, ka jūs saminat Manus ļaudis un satriecat bēdīgo vaigus? Saka Tas Kungs Dievs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Vēl Tas Kungs saka: tādēļ ka Ciānas meitas lepojās un staigā izstieptu kaklu un mirkšķina ar acīm un iet maziem solīšiem, skandinādamas savu kāju gredzenus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Tad Tas Kungs Ciānas meitām darīs pakausi pliku un atsegs viņu kaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Tai dienā Tas Kungs atņems tos skaistos kāju gredzenus, tās saulītes un tos mēnestiņus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Tos ausu glītumus, tās roku sprādzes un tos vaiga apsegus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Tās cepures un prievītes un jostas un ožamos trauciņus un pesteļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Tos pirkstu gredzenus un tās pieres sprādzes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Tās svētku drēbes un tos mēteļus un apsegus un makus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Un tos spieģeļus un dārgos kreklus un tos galvas lakatus un uzvalkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Un smaržas vietā būs puvums, un jostas vietā valgs, un sprogaino matu vietā plika galva, un plata mēteļa vietā šaurs maiss, un skaistuma vietā uguns vātis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Tavi vīri kritīs caur zobenu un tavs spēks(varoņi) karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Un viņas vārti bēdāsies un žēlosies, un iztukšota viņa sēdēs zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Un septiņas sievas sagrābs vienu vīru tanī dienā un sacīs: mēs ēdīsim savu pašu maizi un ģērbsimies ar savām pašu drēbēm, lai mēs tikai topam nosauktas pēc tava vārda, - atņem mūsu negodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Tanī dienā Tā Kunga Atvase būs par glītumu un par godu, un tas zemes Auglis par augstumu un krāšņumu Israēla izglābtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Un Ciānas atlikušie un Jeruzālemes atlicinātie taps nosaukti Viņam svēti, ikkatrs, kas Jeruzālemē rakstīts uz dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Kad Tas Kungs nomazgās Ciānas meitu sārņus un Jeruzālemes asinsvainas izdeldēs no viņas vidus caur sodības Garu un caur uguns Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Un Tas Kungs radīs pār visu Ciānas kalna vietu un pār viņas svētku sapulcēm padebesi dienā un dūmus un uguns liesmas spožumu naktī; jo pār visu godību būs apsegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Un būs telts par pavēni dienā pret karstumu un par glābšanu un par patvērumu pret plūdiem un lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Nu tad, es dziedāšu savam mīļam, sava drauga dziesmu par Viņa vīna dārzu: manam mīļam bija vīna dārzs taukā pakalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Un Viņš to aptaisīja ar sētu un tīrija no akmeņiem un tur stādīja labus vīna kokus un uztaisīja torni vidū un raka vīna spaidu iekšā un gaidīja, ka tas nesīs labus ogu ķekarus, bet tas nesa sūrus ķekarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nu tad, Jeruzālemes iedzīvotāji un Jūda vīri, tiesājat jel starp Mani un Manu vīna dārzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Ko tad vēl vairāk bija darīt pie Mana vīna dārza, nekā Es esmu darījis? Kāpēc Es esmu gaidījis, ka tas labus ogu ķekarus nestu, un viņš nesis sūrus ķekarus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Nu tad, Es jums teikšu, ko Es ar Savu vīna dārzu darīšu. Es atņemšu viņa sētu, ka viņš top noganīts, Es noārdīšu viņa mūri, ka viņš top samīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Un Es viņu darīšu par postažu: viņš netaps apgraizīts nedz apkapāts, bet dadži un ērkšķi tur uzdīgs, un Es pavēlēšu padebešiem, ka uz to nebūs līt lietum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Tiešām, Tā Kunga Cebaot vīna dārzs ir Israēla nams, un Jūda vīri ir Viņa līksmības stādi. Viņš gaida uz tiesu, un redzi, asins plūdi, uz taisnību, un redzi, vaidi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Ak vai, tiem, kas rauj namu pie nama, krāj tīrumu pie tīruma, kamēr vietas vairs neatliek, un ka jūs paliekat tie vienīgie iedzīvotāji zemē!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Tas Kungs Cebaot saka manās ausīs: tiešām, daudz namu būs postā, lieli un skaisti bez iedzīvotāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Tiešām, desmit vīna dārza birzumi nesīs vienu vienīgu batu, un viens gomers sēklas nesīs vienu ēfu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Ak vai, tiem, kas agri cēlušies skrien pēc stipra dzēriena, un kavējās līdz tumsai, kamēr vīns tos sakarsē!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Un tur ir kokles un soma stabules, bungas un stabules un vīns viņu dzīrēs; bet Tā Kunga darbu tie neuzlūko, uz Viņa roku darbu tie nerauga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Tādēļ Mani ļaudis cietumā taps aizvesti no nejauši, un viņu cienīgie cietīs badu, un viņu dzīrenieki iztvīks no slāpēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Tādēļ elle atpletusi savu rīkli un atdarījusi savu muti bez mēra, ka nogrimst (Jeruzālemes) greznums un viņas ļaužu drūzma, un viņas troksnis, un kas tur līksmojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Tad ļaudis taps locīti un vīri pazemoti, un lepno acis taps pazemotas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Bet Tas Kungs Cebaot parādīsies augsts tiesā, un Dievs, tas svētais, parādīsies svēts taisnībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Tad jēri (tur) barosies kā savās ganībās, un svešinieki noēdīs bagāto izpostītās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Ak vai, tiem, kas netaisnību velk ar nelietības valgiem, un grēku kā ar ratu virvēm!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Kas saka: Lai Viņš steidzās, lai Viņš drīz dara Savu darbu, ka mēs to redzam, un lai tuvojās un nāk tas padoms, kas Israēla Svētajam, ka mēs to manam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Ak vai, tiem, kas ļaunu saka labu esam un labu esam ļaunu, kas tumsību dara par gaismu un gaismu par tumsību, kas rūgtu dara par saldu un saldu par rūgtu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Ak vai, tiem, kas gudri savās acīs un prātīgi pēc pašu prāta!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Ak vai, tiem, kas varoņi uz vīna dzeršanu un spēka vīri uz stipru dzērienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Kas dāvanu dēļ bezdievīgo attaisno un taisniem atrauj taisnību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Tādēļ tā kā uguns liesma aprij rugājus un kā svelmē siens sagrūst, tāpat būs viņu sakne kā prauli, un viņu ataugas izputēs kā putekļi, tādēļ ka tie atmet Tā Kunga Cebaot bauslību un nicina Israēla Svētaja vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Tādēļ Tā Kunga dusmība iedegās pret Viņa ļaudīm, un Viņš izstiepj Savu roku pret tiem un tos sit, ka kalni dreb, un viņu miroņi ir kā dubļi ielas vidū. Ar visu to Viņa dusmība nenovēršas, un Viņa roka vēl ir izstiepta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Un Viņš paceļ karogu tiem pagāniem, kas tālu, un pasvilps kādam no zemes gala. Un redzi, ātri un steigšus tas nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Neviens nepiekūst un neklūp viņu starpā, neviens nesnauž nedz guļ, nedz viņa gurnu josta ir atraisīta, nedz viņa kurpju siksna sarauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Viņa bultas ir asas un visi viņa stopi uzvilkti, viņa zirgu nagi tik cieti kā akmens, un viņu rati kā viesulis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Viņu rūkšana ir kā briesmīgām lauvām, un tie rūc kā jauni lauvas un tas kauc un satver laupījumu un aiznes, un glābēja nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Un tas kauc pret viņiem tai diena, kā jūra kauc; kad zemi uzlūko, redzi, tā ir tumša, rīb un zib, tumši pār tiem arī debesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Tanī gadā, kad ķēniņš Uzija nomira, tad es To Kungu redzēju sēžam uz augsta un uzcelta godības krēsla, un Viņa (drēbju) vīles piepildīja Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafi stāvēja augšā ap viņu; ikvienam bija seši spārni; ar diviem tas apsedza savu vaigu, un ar diviem tas apsedza savas kājas, un ar diviem tas skrēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Un tie cits uz citu saucu un sacīja: svēts, svēts, svēts ir Tas Kungs Cebaot, visa zeme ir pilna viņa godības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Un sliekšņa pamati trīcēja no tām saucēju balsīm, un tas nams tapa pilns dūmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Tad es sacīju: Ak vai, man! Jo man jāiet bojā, jo es esmu vīrs nešķīstām lūpām un dzīvoju starp ļaudīm, kam nešķīstas lūpas; jo manas acis redzējušas to Ķēniņu, To Kungu Cebaot!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Tad viens no tiem serafiem atskrēja pie manis, un viņa rokā bija degoša ogle, ko viņš ar stangām bija ņēmis no altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Un viņš ar to aizskāra manu muti un sacīja: redzi, šī tavas lūpas aizskārusi, tā tavs noziegums no tevis atņemts, un tavi grēki salīdzināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Un es dzirdēju Tā Kunga balsi sakām: ko Es sūtīšu un kas mums ies? Tad es sacīju: redzi, še es esmu, sūti mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Tad Viņš sacīja: ej un saki uz šiem ļaudīm: dzirdēt dzirdiet, bet nesaprotiet, un redzēt redziet, bet neņemiet vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Apcietini šo ļaužu sirdi un dari viņu ausis biezas un apstulbo viņu acis, ka tie savām acīm neredz un savām ausīm nedzird un ar savu sirdi nesaprot un neatgriežas un netop dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Tad es sacīju: cik ilgi, Kungs? Un Viņš sacīja: līdz kamēr pilsētas būs izpostītas, ka vairs nav iedzīvotāja, un nami, ka vairs nav cilvēka, un zeme nopostīta par tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Jo Tas Kungs cilvēkus aizdzīs tālu nost, un atstātu vietu būs daudz zemes vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Un ja tanī vēl desmitā tiesa paliks, tad tā atkal ies postā. Bet kā ozols un kā liepa, kam celms paliek, kad to nocērt, - svēts dzimums būs tas celms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Un notikās Ahaza, Jūda ķēniņa, dienās, - tas bija Uzijas dēla Jotama dēls, - ka Recins, Sīrijas ķēniņš, un Pekas, Remalijas dēls, Israēla ķēniņš, uz Jeruzālemi cēlās, pret viņu karot, bet karodami pret viņu tie nekā neiespēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Un Dāvida namam teica un sacīja: Sīrieši apmetušies pret Efraīmu. Tad viņa sirds un viņa ļaužu sirds drebēja, tā kā meža koki dreb no vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Un Tas Kungs sacīja uz Jesaju: izej jel Ahazam pretī, tu un tavs dēls ŠearJašubs, augšēja dīķa grāvja galā, ceļmalā, pie vadmalnieku tīruma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Un saki uz viņu: sargies un esi klusu, nebīsties, un lai tava sirds nebaiļojās no šiem diviem kūpošiem prauliem, no Recina un Sīriešu un Remalijas dēla karstām dusmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Tādēļ ka Sīrieši pret tevi ļaunu sadomājuši ar Efraīmu un Remalijas dēlu sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Celsimies pret Jūdu un izbiedēsim to un uzņemsim to un celsim tur Tabeala dēlu par ķēniņu; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Tā saka Tas Kungs Dievs: tas nenotiks un nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Bet Damaskus būs Sīrijas galva, un Recins Damaskus galva, un vēl būs sešdesmit pieci gadi, tad Efraīms taps satriekts, ka vairs nebūs tauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Un Samarija būs Efraīma galva, un Remalijas dēls Samarijas galva. Ja neticēsiet, tad nepastāvēsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Un Tas Kungs runāja vēl uz Ahazu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Prasies kādu zīmi no Tā Kunga, sava Dieva, prasi to, vai dziļi dziļumā vai augsti augstumā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Tad Ahazs sacīja: es neprasīšu, es arī To Kungu nekārdināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Tad viņš sacīja: klausiet jel, jūs no Dāvida nama, vai tas jums vēl maz, kaitināt cilvēkus, ka nu arī kaitinājiet manu Dievu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Tādēļ Tas Kungs pats jums dos zīmi: redzi, jumprava būs grūta un dzemdēs dēlu un nosauks viņa vārdu Immanuel (Dievs ar mums).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Sviestu un medu viņš ēdīs, kad viņš zin ļaunu atmest un labu uzņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Jo pirms tas puisītis zin ļaunu atmest un labu uzņemt, zeme būs izpostīta, no kuras diviem ķēniņiem tev bailes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Un Tas Kungs atvedīs pār tevi un pār taviem ļaudīm un pār tavu tēva namu dienas, kādas nav nākušas no tā brīža, kamēr Efraīms no Jūda ir atkāpies, proti Asīrijas ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Jo tai dienā Tas Kungs pasvilps tām mušām, kas ir Ēģiptes upju galā, un to biti, kas Asīrijas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Un tie nāks un apmetīsies visi dziļās ielejās un kalnu gravās un visos ērkšķu krūmos un visās ganībās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Tai dienā Tas Kungs ar derētu dzenamu nazi, kas viņpus upes, caur Asīrijas ķēniņu, nodzīs galvu un kāju matus, ir visu bārdu Viņš nodzīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Un tai dienā cilvēks turēs kādu gotiņu un kādas divas aitiņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Un tie tik daudz piena dos, ka tas sviestu ēdīs, jo ikkatrs, kas tai zemē atliks, tas ēdīs sviestu un medu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Un tai dienā notiks, ka ikkatrā vietā, kur bijuši tūkstoš vīna koki, kas maksāja tūkstoš sudraba gabalus, tur būs ērkšķi un krūmi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Ka ar bultām un stopiem tur būs jāiet, jo visa tā zeme būs ērkšķi un krūmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Un uz visiem tiem kalniem, ko citkārt apkapāja ar kapļiem, tur tu neiesi, bīdamies no ērkšķiem un krūmiem, bet lieli lopi tur staigās, un sīki lopi tos mīdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Un Tas Kungs sacīja uz mani: ņem lielu galdu un raksti uz to ar cilvēka rakstu: „Māer šalal, kaš bas“(laupījums steidzās, laupīšana nāk ātri).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Un es sev ņēmu uzticamus lieciniekus, priesteri Ūriju, un Zakariju, Jebereķijas dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Un es gāju pie tās pravietes, un tā tapa grūta un dzemdēja dēlu. Un Tas Kungs sacīja: nosauc viņa vārdu: Māer šalal, kaš bas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Jo pirms tas zēns māk saukt: mans tēvs, mana māte! Tad Damaskus mantu un Samarijas laupījumu nesīs Asīrijas ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Tas Kungs vēl runāja uz mani un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Tādēļ ka šie ļaudis nicina Šiloas ūdeni, kas lēniņām tek, un tiem ir prieks pie Recina un Remalijas dēla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Redzi, tad Tas Kungs pār tiem atvedīs stipro un vareno lielupes ūdeni, Asīrijas ķēniņu un visu viņa godību, un tas plūdīs pār visiem saviem krastiem un ies pār visām savām malām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Un tas ielauzīsies Jūdā un to pārplūdīs, un ies cauri un sniegsies līdz pat kaklam, un tas izstieps savus spārnus un piepildīs visu tavu zemi, Immanuel!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Trakojiet, tautas, un topat satriektas! Ņemiet vērā, visi pasaules gali! Jožaties un topat satriekti, jožaties un topat satriekti!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Izdomājiet padomu, bet tas iznīks, runājiet vārdu, bet tas nenotiks, jo ar mums ir Dievs (Immanuels.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Jo tā Tas Kungs uz mani runājis, mani satverdams ar Savu roku, un mani mācījis, nestaigāt šo ļaužu ceļu, un sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Jums nebūs sacīt, „derība“visur, kur šie ļaudis saka „derība“, un nebūs bīties, kur tie bīstas, nedz baiļoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'To Kungu Cebaot, to jums būs svētīt, un Viņš lai ir jūsu bijāšana, un Viņš lai ir jūsu bailība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Tad Viņš jums būs par svētumu, bet par pieduršanās akmeni un par piedauzīšanās klinti abiem Israēla namiem, par valgu un slazdu Jeruzālemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Un daudzi no tiem klups un kritīs un taps satriekti un savaldzināti un sagūstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Sasien to liecību, aizzieģelē to mācību iekš maniem mācekļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Un es ceru uz To Kungu, kas Savu vaigu apslēpis no Jēkaba nama, un es gaidu uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Redzi, es un tie bērni, ko Tas Kungs man devis, par zīmēm un par brīnumiem iekš Israēla no Tā Kunga Cebaot, kas mājo Ciānas kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Kad tie nu uz jums sacīs: vaicājiet tos pareģus un zīmju cienītājus, kas čirkst un čukst, (tad sakāt): vai ļaudīm nebūs vaicāt savu Dievu? Vai tad mirušus būs vaicāt priekš dzīviem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '(Griežaties) Pie bauslības un liecības! Ja tie tā nerunās (saskaņā ar šo Vārdu), tad auseklis(gaisma) tiem neausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Bet tie ies apkārt, grūti apbēdināti un izsalkuši. Un kad būs izsalkuši, tad tie dusmosies un lādēs savu ķēniņu un savu dievu. Un kad tie skatās uz augšu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Vai uzlūko zemi, redzi, bēdas un tumsība; tie ir apstulboti bēdās un maldās tumsībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Bet tumsība nepaliks, kur (tagad) bēdas; pirmajā laikā Viņš kaunā licis Zebulona zemi un Naftalus zemi, bet pastara laikā Viņš cels godā jūrmalu, AizJardāni un pagānu Galileju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Tie ļaudis, kas staigā tumsībā, redz lielu gaišumu; kas dzīvo nāves ēnas zemē, pār tiem spīd spožums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'To tautu Tu esi vairojis; lielu prieku Tu tai esi devis; tie priecāsies Tavā priekšā, tā kā priecājās pļaujamā laikā, tā kā līksmojās laupījumu dalot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Jo viņu nastas jūgu un viņu muguras rīksti un viņu dzinēja dzenuli Tu esi salauzis kā Midijana laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Jo kurpes, autas uz kara troksni, un drēbes, apgānītas asinīm, taps sadedzinātas un no uguns aprītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Jo viens bērns mums dzimis, viens dēls mums dots, un valdība ir uz Viņa kamieša; un Viņa vārds top saukts: Brīnums, Padoma devējs, Varenais Dievs, Mūžīgais tēvs, Miera lielkungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Lai valdība top vairota, un mieram nav gala uz Dāvida goda krēsla un Viņa valstībā, ka Viņš to sataisa un stiprina ar tiesu un taisnību no šī laika mūžīgi. To darīs Tā Kunga Cebaot karstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Tas Kungs vienu vārdu ir sūtījis pie Jēkaba, un tas ir nolaidies pie Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Un visi ļaudis to samanīs, Efraīms un Samarijas iedzīvotāji, kas lielībā un sirds lepnībā saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Ķieģeļi gruvuši, bet ar cirstiem akmeņiem atkal uztaisīsim, meža vīģu koki ir nocirsti, bet viņu vietā stādīsim ciedru kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Jo Tas Kungs paaugstina Recina pretiniekus pār viņu un saskubina viņa ienaidniekus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Sīriešus no rītiem un Fīlistus no vakariem, ka tie Israēli ēd pilnā mutē. Ar visu to Viņa dusmība nenovēršas, un Viņa roka vēl ir izstiepta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Bet tie ļaudis negriežas pie Tā, kas tos sit, un nemeklē To Kungu Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Tādēļ Tas Kungs nocirtīs no Israēla galvu un asti, zaru un celmu vienā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Vecaji un augstie ir tā galva, bet pravietis, kas melus māca, tā aste.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Jo šo ļaužu vadoņi ir viltnieki, un kas no tiem top vadīti, tie iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Tādēļ Tas Kungs par viņu jaunekļiem nepriecāsies un neapžēlosies par viņu bāriņiem un atraitnēm, jo tie visi ir blēži un ļaundari, un ikviena mute runā blēņas. Ar visu to Viņa dusmība nenovēršas, un Viņa roka vēl ir izstiepta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Jo bezdievība deg kā uguns un aprij ērkšķus un dadžus un aizdedzina mežu biezumus un augsti dūmi paceļas gaisā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Jo caur Tā Kunga Cebaot bardzību zeme kvēlo, un ļaudis ir kā uguns barība, un viens otru nežēlo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Pa labo roku rij, un tomēr ir izsalkuši, un pa kreiso roku ēd, un tomēr nav paēduši, ikkatrs ēd sava elkoņa miesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasus Efraīmu, un Efraīms Manasu, un abi kopā pret Jūdu. Ar visu to Viņa dusmība nenovēršas, un Viņa roka vēl ir izstiepta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Ak vai, tiem, kas ceļ netaisnus likumus, un tiem rakstītājiem, kas raksta grūtu tiesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Ka nabagiem tiesu neizdod un tiesu laupa tiem bēdīgiem starp Maniem ļaudīm, ka atraitnes aplaupa un bāriņus posta!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Bet ko jūs darīsiet piemeklēšanas dienā un tai postā, kas nāk no tālienes? Pie kā bēgsiet pēc palīdzības, un kur glabāsiet savu godību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Bet jūs locīsities starp gūstītiem un kritīsiet starp nokautiem. Ar visu to Viņa dusmība nenovēršas, un Viņa roka vēl ir izstiepta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ak vai, Asuram! Tas ir Manas dusmības rīkste, un viņa rokā Manas bardzības zizlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Es viņu sūtu pret viltīgiem ļaudīm un viņam pavēlu pret ļaudīm, par kuriem Es apskaities, lai viņš tos laupīdams laupa un postīdams posta, un tos samin kā dubļus uz ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Bet viņam tā nešķiet, un viņa sirds tā nedomā; jo viņš apņēmies izdeldēt un izsakņot daudz tautas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Jo viņš saka: vai mani virsnieki visi kopā nav ķēniņi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Vai Kalno nav kā Karķemis? Vai Hamata nav kā Arvada? Vai Samarija nav kā Damaskus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Tā kā mana roka dabūjusi tās elku dievu valstis, jebšu viņu dievekļu bija vairāk nekā to, kas Jeruzālemē un Samarijā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Vai es nevarētu darīt pie Jeruzālemes un pie viņas elkiem tāpat, kā esmu darījis pie Samarijas un viņas elkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Bet kad Tas Kungs visu Savu darbu būs pabeidzis Ciānas kalnā un Jeruzālemē, tad (sacīs): Es piemeklēšu to sirds lepnības augli pie Asīrijas ķēniņa un viņa acu augsto greznību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Jo tas saka: caur savas rokas spēku es to esmu darījis un caur savu gudrību, jo es esmu prātīgs. Es esmu atņēmis tautu robežas un laupījis viņu mantas un kā varonis zemē gāzis valdniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Un mana roka atradusi tautu bagātību kā ligzdu, un es esmu sagrābis visu pasauli, kā sagrābj atstātas olas, un neviens nav bijis, kas spārnu būtu kustinājis vai muti atdarījis vai pīkstējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Vai tad cirvis lai lielās pret to, kas ar to cērt? Jeb vai zāģis lai turas pretī tam, kas to velk! tā kā zizlis to turētu, kas viņu paceļ, tā kā rīkste to cilātu, kas nav koks!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Tādēļ Tas Kungs Dievs Cebaot sūtīs diloni starp viņa (Asura) trekniem, un apakš viņa godības dedzin degs, kā uguns deg.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Un Israēla gaišums būs uguns, un viņa Svētais būs liesma, kas sadedzinās un norīs viņa ērkšķus un dadžus vienā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Un viņš aprīs viņa meža un viņa dārza godību, līdz ar dvēseli un miesu, un tas novārgs kā vārgulis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Un viņa meža atlikušie koki būs mazs pulciņš, ka zēns tos varētu sarakstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Tanī dienā Israēla atlikušie, un Jēkaba nama izglābtie nepaļausies vairs uz to, kas viņu sitis, bet uzticībā paļausies uz To Kungu, to Svēto iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Tie atlikušie atgriezīsies, Jēkaba atlikušie, pie tā visuvarenā Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Jo jebšu tavi ļaudis, Israēl, ir kā jūras smiltis, tomēr (tikai) viņu atlikums atgriezīsies. Jo gals ir nospriests pilnīgā taisnībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Jo Tas Kungs Dievs Cebaot nolikto gala spriedumu izdarīs pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Tāpēc Tas Kungs Dievs Cebaot saka tā: Mani ļaudis, kas dzīvojat Ciānā, nebīstaties no Asura, kad tas jūs sit ar rīksti, un savu zizli paceļ pret jums, kā notika Ēģiptē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Jo vēl mazs brīdis, tad dusmība būs pagalam, un Mana bardzība tos izdeldēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Jo Tas Kungs Cebaot pacels pātagu pret to, kā Viņš sita Midijanu pie Horeba kalna, un Ciņa zizlis ir pār jūru un viņš to paceļ kā Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Un tai dienā viņa nasta atstāsies no tava kamieša un viņa jūgs no tava kakla, un tas jūgs šķīdīs no treknuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Tas nāk uz Ajatu, tas iet caur Migronu, Mikmasā tas atstāj savas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Tie iet caur šaurumu, Ģebā tie paliek par nakti, Rāma dreb, Saula Ģibeja bēg.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Kliedz stiprā balsī, Galima meita! Klausies, Laīša! nabaga Anatota!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena bēg, Ģebimas iedzīvotāji glābjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Vēl šodien tas apmetīsies Nobā, pacels roku pret Ciānas meitas kalnu, pret Jeruzālemes pakalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Redzi, Tas Kungs Dievs Cebaot nokapā tos zarus ar briesmīgu varu, un tie, kas ir augsti augumā, top nocirsti, un tie lielie pazemoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Un Viņš nocērt ar dzelzi biezos meža krūmus, un Lībanus krīt caur vareno.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Un atvase nāks no Isajus celma, un zars no viņa saknēm nesīs augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Un uz Tā dusēs Tā Kunga Gars, gudrības un saprašanas Gars, padoma un stipruma Gars, atzīšanas un Dieva bijāšanas Gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Un salda smarža Viņam ir Tā Kunga bijāšana. Un Viņš netiesās pēc tam, ko Viņa acis redz, un nesodīs pēc tam, ko Viņa ausis dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Bet Viņš tiesās nabagus ar taisnību un spriedīs pazemīgiem tai zemē pēc patiesības un sitīs zemi ar Savas mutes zizli un nokaus bezdievīgo ar Savu lūpu dvašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Jo taisnība būs josta ap Viņa gurniem, un patiesība būs josta ap Viņa īkstīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Un vilks mājos pie jēra, un pardelis(pantēra) apgulsies pie kazlēna. Un teļš un jauns lauva un trekni lopi būs kopā, un mazs puisēns tos ganīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Govs un lāču māte būs kopā ganos, un viņu bērni gulsies kopā, un lauva ēdīs salmus kā vērsis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Un zīdāms bērns priecāsies pie odzes cauruma, un no krūts atšķirts bāzīs savu roku pūķa alā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ļauna nekur vairs nedarīs nedz noziegsies visā Manā svētā kalnā; jo zeme ir pilna Tā Kunga atzīšanas, tā kā ūdens apklāj jūras dibenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Un notiks tai dienā: pagāni vaicās pēc Isajus saknes, kas tautām stāv par karogu, un viņa dusas vieta būs godība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Un notiks tai dienā: Tas Kungs otram kārtam atkal izstieps Savu roku, sadabūt Savu ļaužu atlikušos, kas būs atlikuši no Asura un no Ēģiptes un no Patrus un Moru zemes un no Elama un no Sineāra un no Hamata un no jūras salām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Un Viņš uzcels karogu pagāniem un sapulcēs Israēla aizdzītos un Jūda izkaisītos no visiem četriem zemes stūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Un Efraīma skaudība mitēsies, un Jūda pretinieki taps izdeldēti; Efraīms neapskaudīs Jūdu, un Jūda nespaidīs Efraīmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Un tie skries Fīlistiem uz pleciem pret vakara pusi, tie kopā aplaupīs tos iedzīvotājus pret rītiem, pret Edomu un Moabu tie izstieps savu roku, un Amona bērni tiem būs paklausīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Un Tas Kungs izdeldēs Ēģiptes jūras mēli un cilās Savu roku pret lielupi Savā karstā dusmībā, un to sasitīs septiņās upītēs, ka ar kurpēm varēs iet cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Un staigājams ceļš būs Viņa ļaužu atlikušiem, kas būs atlikuši no Asura, tā kā Israēlim notika tai dienā, kad izgāja no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Un tai dienā tu sacīsi: es Tev pateicos, Kungs, ka Tu dusmīgs bijis uz mani, un Tava dusmība ir novērsusies, un Tu mani iepriecini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Redzi, Dievs ir mana pestīšana, es cerēšu un nebīšos, jo Tas Kungs Dievs ir mans stiprums un mana slavas dziesma, un Viņš man ir par pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Un ar prieku jūs smelsiet ūdeni no pestīšanas avotiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Un sacīsiet tai dienā: pateicieties Tam Kungam, piesauciet Viņa vārdu, dariet zināmus Viņa darbus starp tautām, pieminiet, ka Viņa vārds ir paaugstināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Dziedājiet Tam Kungam, jo Viņš ir darījis augsti teicamas lietas, lai tas tiek zināms pa visām zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Gavilē un slavē, Ciānas iedzīvotāja, jo Israēla Svētais ir liels tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Spriedums par Bābeli, ko Jesaja, Amoca dēls, redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Izceļat karogu augstā kalnā, paceļat balsi, metat ar roku, lai ieiet pa valdnieku vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Es esmu pavēlējis Saviem svētītiem, arī Savus stipros aicinājis uz Savu dusmību, tos, kas priecājās par Manu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Ļaužu troksnis ir kalnos, kā no lielas tautas, trokšņa skaņa no sapulcinātu tautu valstīm. Tas Kungs Cebaot pārlūko karaspēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Tie nāk no tālas zemes, no pasaules gala, Tas Kungs ar Savas dusmības rīkiem, postīt visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Kauciet, jo Tā Kunga diena ir tuvu, viņa nāk kā posts no tā Visuvarenā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Tādēļ visas rokas būs nogurušas, un visu cilvēku sirdis izkusīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Un tie iztrūcināsies, mokas un bēdas tos sagrābs, tiem būs sāpes, kā sievai, kas dzemdē; tie skatās kā stulbi cits uz citu, viņu vaigi deg kā liesmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Redzi, Tā Kunga diena nāk briesmīga, ar dusmām un ar karstu bardzību, un dara zemi par tuksnesi un izdeldē grēciniekus no viņas nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Jo debess zvaigznes un viņas spīdumi nedos savu gaismu, saule uzlecot aptumšosies, un mēnesis neļaus spīdēt savam gaišumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Jo Es piemeklēšu bezdievību pie pasaules, un viņu netaisnību pie ļauniem, Es iznīcināšu lepniem lielību un nogāzīšu vareniem greznību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Ka vīrs būs dārgāks nekā tīrs zelts, un cilvēks dārgāks nekā Ofira dārgumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Tāpēc es darīšu debesi drebam, un zeme taps kustināta no savas vietas, caur Tā Kunga Cebaot bardzību un caur viņa karstās dusmības dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Un tie būs kā izbiedināta stirna un kā avis, ko neviens nesapulcina; ikviens griezīsies pie savas tautas, un ikviens bēgs uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Ikvienu, ko atradīs, nodurs, un ikviens, ko gūstīs, kritīs caur zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Un viņu bērniņi taps satriekti priekš viņu acīm, viņu nami taps nopostīti, un viņu sievas piesmietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Redzi, Es pamodināšu pret tiem Mēdiešus, kas sudrabu necienī un zelta nekāro');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Un tie nošaudīs jaunekļus ar stopiem un nežēlos bērnus mātes miesās, bērnus viņu acis nesaudzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Un Bābele, valstu glītums, Kaldeju skaistums un lepnums, būs tā kā Sodoma un Gomora, ko Dievs apgāzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Tur ne mūžam neviens vairs nedzīvos, tur neviens nemājos līdz radu radiem, Arābi tur neapmetīsies, gani tur neganīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Bet tuksneša zvēri tur mitīs, un viņu namos mājos pūces pa pulkiem, un tur dzīvos strausi un jodi tur lēkās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Un vilki kauks cits pret citu viņas atstātos namos, un pūķi tanīs lepnās pilīs. Un viņas laiks jau tuvu nācis, un viņas dienas nekavēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Jo Tas Kungs apžēlosies par Jēkabu un atkal izredzēs Israēli un tos pārvedīs savā zemē. Un svešinieki ar tiem biedrosies un pieķersies Jēkaba namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Un tautas tos ņems un vadīs uz viņu vietām, un Israēla nams Tā Kunga zemē tos iemantos par kalpiem un kalponēm, un tie tos turēs cietumā, kas viņus bija cietumā turējuši, un valdīs par saviem dzinējiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Un notiks tai dienā, kad Tas Kungs tev dusu dos no tavām sāpēm un no tavām izbailēm un no tās grūtās kalpošanas, ar ko tie tevi kalpinājuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Tad tu šo dziesmu dziedāsi pret Bābeles ķēniņu un sacīsi: Kā tas dzinējs pagalam! Kā tie spaidi pagalam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Tas Kungs bezdievīgiem salauzis zizli, valdītājiem rīksti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Kas ļaudis briesmīgi mocīja ar mokām bez mitēšanās, kas ar bardzību valdīja pār tautām, ar spaidīšanu bez gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Visa zeme dus un atpūšas, tā skanēt skan no gavilēšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Un priedes priecājās par tevi un ciedru koki uz Lībanus (un saka): kamēr tu guli pie zemes, neviens nenāk, mūs nocirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Elle apakšā tevis dēļ rīb, tev pretim ejot; kad tu nāci, viņa tevis dēļ uzmodina mirušos, visus zemes lielkungus, viņa visiem tautu ķēniņiem liek celties no krēsliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Tie visi runā un saka uz tevi: arī tu esi palicis bez spēka tā kā mēs, tu mums palicis līdzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Tava greznība nogrimusi ellē un tavu kokļu skaņa; kodes būs tavas cisas, un tārpi tavs apsegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kā tu esi kritis no debesīm, tu rīta zvaigzne, tu ausekļa dēls! Kā tu nocirsts zemē, kas tautas pārvarēji?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Un tu sacīji savā sirdī: es uzkāpšu debesīs, es paaugstināšu savu goda krēslu pār Dieva zvaigznēm, es apsēdīšos uz saiešanas kalna ziemeļu galā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Es uzkāpšu padebešu kalnos, tam Visuaugstajam es līdzināšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Tiešām, ellē tu esi nogāzts, pašā bedres dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Kas tevi redz, tie uz tevi skatās un tevi aplūko: vai šis tas vīrs, kas zemi kustināja un darīja valstis drebam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Kas pasauli pārvērta par tuksnesi un viņas pilsētas postīja, kas viņas ļaudis no cietuma neatlaida mājās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Visi tautu ķēniņi, tie visi guļ zemē ar godu, ikviens savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Bet tu esi tālu atmests no sava kapa, kā nieka žagars, apklāts ar nokautiem, zobena nodurtiem, kas grimst akmeņu bedrē, - tā kā samīta maita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Ar viņiem kopā tu nebūsi kapā; jo savu zemi tu esi postījis un nokāvis savus ļaudis; ļauna darītāju dzimums netiks pieminēts mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Taisāties kaut viņa bērnus viņu tēvu nozieguma dēļ, ka tie neceļas un zemi neiemanto un nepiepilda pasauli ar pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Jo Es celšos pret tiem, saka Tas Kungs Cebaot, un izdeldēšu no Bābeles vārdu un dzimumu un bērnu un bērna bērnu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Un Es to došu par īpašumu ežiem un par ūdens purvu, un Es tos izmēzīšu ar izdeldēšanas slotu, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Tas Kungs Cebaot ir zvērējis un sacījis: tiešām, kā Es esmu nodomājis, tā notiks, un kā Es esmu nospriedis, tā būs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Ka Es Asuru satriekšu Savā zemē, un uz Saviem kalniem viņu samīdīšu, ka viņa jūgs no tiem top atņemts un viņa nasta zūd no viņu pleciem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Šis ir tas padoms, kas nospriests pār visu zemi, un šī ir tā roka, kas izstiepta pār visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Jo Tas Kungs Cebaot to nodomājis; kas to iznīcinās? Un Viņa roka ir izstiepta, kas to novērsīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Tai gadā, kad ķēniņš Ahazs nomira, notika šis spriedums:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Nepriecājies, visa Fīlistu zeme, ka tā rīkste salauzta, kas tevi sita. Jo no čūskas saknes nāk odze, un viņas auglis būs spārnains pūķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Jo visupēdīgie nabagi baudīs pilnību, un tukšinieki apgulsies ar mieru. Bet tavu sakni Es nokaušu caur badu, un tavus atlikušos viņš kaus zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Kauciet, vārti! Kliedz, pilsēta! Izkūsti, visa Fīlistu zeme! Jo no ziemeļa puses nāk dūmi, un neviens no viņa pulkiem nenoklīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Un ko tad atbildēs tautu vēstnešiem? Ka Tas Kungs Ciānu stiprinājis un Viņa ļaužu bēdīgie tur atrod patvērumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Spriedums par Moabu. Moaba Ara pa nakti postīta, izdeldēta! Tiešām, Moaba Ķire pa nakti postīta, izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Uz Baītu un Dibonu, uz elku kalniem iet raudāt; uz Nebus un uz Medbas Moabs kauc. Visas viņu galvas ir nodzītas plikas un visiem bārda nogriezta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Savās ielās tie iet apjozušies ar maisiem, pa saviem jumtiem un ceļiem visi kauc un plūst asarās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hešbona un Eleale brēc, viņas balss top dzirdēta līdz Jācai. Tādēļ vaid paši Moaba apbruņotie, dvēsele viņam trīc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mana sirds brēc par Moabu; viņa bēgļi bēg līdz Coārai, līdz EglatŠilišijai; jo uz Luķitu kāpj ar raudāšanu, un ceļā pret Horonaīm kliedz par izpostīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Jo Nimrim ūdeņi izsīkuši; jo zāle nokaltusi, zaļums iznīcis, nekas vairs nezeļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Tāpēc to krājumu, ko sakrājuši, un ko glabājuši, to tie ved pār kārklu upi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Jo brēkšana iet pa Moaba robežām, viņa kaukšana līdz Eglaīm, viņa kaukšana līdz Elim akai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Jo Dimonas ūdeņi ir pilni asiņu. Jo vēl vairāk Es uzlikšu Dimonai, lauvu tiem, kas Moabā izglābušies un tai zemē atlikuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Sūtait jērus zemes valdītājam no Zelas pa tuksnesi uz Ciānas meitas kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Jo kā putni no ligzdas izdzīti skraida, tā būs Moaba meitas pie Arnonas pārceļamām vietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Dodiet padomu, nesiet tiesu, dariet pavēni pašā dienas vidū kā naktī; apslēp izdzītos, nedari bēdzēju zināmu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Lai mani izdzītie tavā starpā piemīt, Moab, esi tu viņiem par patvērumu no postītāja! Jo spaidītājam nāks gals, postīšana beigsies, saminēji no zemes taps izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Un goda krēsls ir stiprināts caur žēlastību, un uz tā sēž ar patiesību Dāvida dzīvoklī tas, kas tiesu spriež un tiesu kopj un prot taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Moaba lepnību esam dzirdējuši, ka tas ļoti lepns, viņa augstprātību un lepnību un viņa pārgalvību un viņa tukšo lielību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Tādēļ Moabs kauks par Moabu, visi kopā kauks; par Ķirarezetes pamatiem jūs nopūtīsieties, tie pavisam salauzīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Jo Hešbonas druvas postītas, arī Sibmas vīna koks - tautu valdnieki saminuši viņa brangos stādus, tie sniedzās līdz Jaēzerai un stiepās pa tuksnesi, viņa zari izplētās un cēlās pār jūru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Tāpēc es gauži raudu kā Jaēzera par Sibmas vīna koku; es tevi slacināju ar savām asarām, Hešbona un Eleale; jo pār taviem vasaras augļiem un pār tavu pļaušanu nākusi kara kliegšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Tā ka prieks un līksmība atņemti no dārziem, un vīna kalnos nedzied un negavilē. Vīna spiedējs vīna nemin vīna spaidā, prieka dziesmām esmu licis mitēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Tāpēc manas iekšas trīc par Moabu kā kokle un mana sirds par Ķirarezeti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Un notiks, kad Moabs rādīsies un nomocīsies elku kalnā un ies pielūgt savā svētā vietā, tad viņš nespēs nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Šis ir tas vārds, ko Tas Kungs ir runājis pret Moabu sen laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Bet nu Tas Kungs runā un saka: pa trim gadiem, kādi ir algādža gadi, Moaba godība taps kaunā ar visu lielo ļaužu pulku, un kas atliek, to būs gauži maz, ne daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Spriedums par Damasku: Redzi, Damaska taps nomesta, ka vairs nav pilsēta, bet sagruvusi akmeņu kopa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Aroēra pilsētas būs atstātas ganāmiem pulkiem; tie tur apmetīsies un neviens tos neizbiedēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Un stiprums zudīs no Efraīma un valdīšana no Damaskas, un kas no Sīriešiem atlikuši, tie būs kā Israēla bērnu godība, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Un notiks tai dienā, ka Jēkaba godība ies mazumā, un viņa treknā miesa izdils.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Jo tā būs, kā pļāvējs sakampj labību, un viņa roka pļauj vārpas, un būs, kā kad vārpas lasa Refaīm ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Tomēr atlikums tur atliksies, kā pie eļļas koka, kad to nokrata, kādas divas trīs ogas pašā koka galā, un kādas četras piecas pie viņa auglīgiem zariem, saka Tas Kungs, Israēla Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Tanī dienā cilvēks skatīsies uz savu Radītāju, un viņa acis raudzīsies uz to Svēto iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Un neskatīsies uz tiem altāriem, ko paša rokas cēlušas, un neraudzīsies uz to, ko viņa pirksti ir taisījuši, nedz uz tām Ašerām nedz uz tiem saules stabiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Tanī dienā viņa stiprās pilsētas būs kā mežos un kalnos sagruvušas pilis, ko tie atstājuši, no Israēla bērniem bēgdami, un būs posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Jo tu esi aizmirsis Dievu, savu Pestītāju, un neesi pieminējis sava patvēruma klinti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Tādēļ tu gan stādīji skaistus dārzus un apstādīji ar svešas zemes stādiem. Tai dienā, kad tu tos stādīji, tu tos gan apkopi, un strādāji, ka tavam sējumam agri bija jāzied, bet tas pļaujamais iznīks bēdu laikā un nāves skumjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Vai, lielu tautu rūkšana, kas kauc, kā jūra kauc, un ļaužu pulku troksnis, kas rūc, kā vareni ūdeņi krāc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Tautas rūc, kā lieli ūdeņi krāc, bet Viņš to aprāj, un tas bēg tālu nost un top dzenāts kā pelus pa kalniem no vēja, kā putekļi no viesuļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Vakara laikā, - redzi, briesmas; pirms gaisma aust, pagalam! Šī ir tā alga mūsu laupītājiem, un tā tiesa mūsu postītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ak vai, zeme, kur spārni žvingst, viņpus Kūsa upēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Tā sūta vēstnešus pār jūru un niedru laivās pār ūdeņiem. Ejat, jūs čaklie vēstneši, pie tautas, kas bijājama tālu tālu, pie tautas, kas pavēlētāja un saminēja, kam upes zemi dala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Visi jūs pasaules iedzīvotāji un jūs ļaudis virs zemes, kad karogs taps izcelts kalnos, tad redziet, un kad trumete skanēs, tad dzirdiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Jo tā Tas Kungs uz mani sacījis: “Es turēšos klusu un skatīšos no Sava mājokļa, kā karstums spiež saulei spīdot un padebesis raso pļaujama laika karstumā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Jo priekš pašas pļaujas, kad ziedi noziedējuši un kad no ziediem ķekari jau ietekās, tad Viņš stīgas nogriezīs ar dārza nazi un zarus atņems un nokapās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Tie visi taps atstāti kalnu ērgļiem un zemes zvēriem, un tie ērgļi tur paliek pa vasaru un visi zemes zvēri tur mīt pa ziemu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Tanī laikā Tam Kungam Cebaot nesīs dāvanas no tās tautas, kas lielu slaiku augumu, un no tās tautas, kas bijājama tālu tālu, no tās tautas, kas pavēlētāja un saminēja, kam upes zemi dala, uz to vietu, kur Tā Kunga Cebaot vārds, uz Ciānas kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Spriedums par Ēģipti. Redzi, Tas Kungs brauc uz viegla padebeša un nāk uz Ēģiptes zemi; un Ēģiptes elkadievi dreb Viņa priekšā, un ēģiptiešu sirds iekš tiem izkūst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Jo Es sarīdinu Ēģipti pret Ēģipti, ka tie karos ikkatrs pret savu brāli, un ikkatrs pret savu tuvāko, pilsēta pret pilsētu, valsts pret valsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Un ēģiptiešu prāts panīks viņu sirdī, un viņu padomu Es iznīcināšu; tad tie vaicās savus dievekļus un tos vārdotājus un zīlniekus un zīmju cienītājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Un Es Ēģipti nodošu bargu kungu rokā, un briesmīgam ķēniņam būs pār tiem valdīt, saka Tas Kungs Dievs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Un ūdens izžūs jūrā, un tā upe izsīks un izžūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Un strauti smirdēs, Ēģiptes grāvji paliks sekli un sausi, niedres un ašķi(meldri) savītīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Upes līči, upes malas un viss sējums pie upes savītīs, izputēs un izzudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Un zvejnieki žēlosies un visi bēdāsies un vaidēs, kas makšķeri met upē, un kas tīklu met ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Un kaunā paliks, kas smalkas dzijas vērpj un kas baltas drānas auž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Un zemes pīlāri būs satriekti, un visi algādži apbēdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Tīri ģeķi ir Coana virsnieki, Faraona gudrie padoma devēji; padoms ir palicis par ģeķību. Kā jūs varat sacīt uz Faraonu: es esmu gudru ļaužu dēls, vecu ķēniņu dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kur nu ir tavi gudrie? Lai tie tev dara zināmu, ka tu atzīsti, ko Tas Kungs Cebaot nodomājis par Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Coana virsnieki ir palikuši par ģeķiem, Nofas virsnieki pievīlās un Ēģipti paved uz maldīšanos viņas cilšu galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Tas Kungs pār viņiem izlējis maldu garu, ka tie apmāna ēģiptiešus visā viņu darīšanā, un šie kā piedzērušies vārtās savos vēmekļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Un tad ēģiptiešiem nekāds darbs neizdosies, ne galvai, ne astei, ne celmam, ne zaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Tai dienā ēģiptieši būs kā sievas un bēdāsies un baiļosies no Tā Kunga Cebaot paceltās rokas, ko Viņš pret tiem paceļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Un Jūda zeme būs Ēģiptei par briesmām; kas viņu pieminēs, tas baiļosies no Tā Kunga Cebaot padoma, ko Viņš pret tiem nodomājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Tai dienā piecas pilsētas Ēģiptes zemē runās Kanaāna valodu un zvērēs Tam Kungam Cebaot; vienu sauks Irhāeres (saules pilsēta, vai posta pilsēta).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Tai dienā Tam Kungam būs altāris Ēģiptes vidū un piemiņas stabs pie viņas robežām priekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Un tas būs Tam Kungam Cebaot par zīmi un par liecību Ēģiptes zemē; kad tie brēks uz To Kungu apspiedēju dēļ, tad Viņš tiem sūtīs pestītāju un aizstāvētāju, kas tos atpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Un Tas Kungs Sevi darīs zināmu Ēģiptei, un Ēģipte tai dienā To Kungu atzīs un Viņam kalpos ar kaujamiem un ēdamiem upuriem un Tam Kungam solīs solījumus un tos nomaksās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Un Tas Kungs sitīs Ēģipti, Viņš to sitīs un dziedinās, un tie atgriezīsies pie Tā Kunga, un Viņš no tiem ļausies pielūgties un tos dziedinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Tai dienā būs liels ceļš no Ēģiptes uz Asīriju, un Asīrija ies uz Ēģipti un Ēģipte uz Asīriju, un Ēģipte līdz ar Asīriju kalpos (Tam Kungam.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Tai dienā Israēls būs tas trešais ar Ēģipti un Asīriju, par svētību virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Jo Tas Kungs Cebaot tos svētīs sacīdams: svētīti lai ir Mani ļaudis, Ēģipte un Asurs, Manu roku darbs, un Israēls, Mana mantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Tanī gadā, kad Tartans gāja uz Ašdodu, Asīrijas ķēniņa Zargona sūtīts, un karoja pret Ašdodu un to uzņēma,-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Tai laikā Tas Kungs runāja caur Jesaju, Amoca dēlu, sacīdams: ej un atraisi to maisu no saviem gurniem, un novelc savas kurpes no savām kājām. Un viņš tā darīja un staigāja pliks un basām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Tad Tas Kungs sacīja: tā kā Mans kalps Jesaja staigā pliks un basām kājām, trīs gadus par zīmi un priekšzīmi Ēģiptei un Moru zemei, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Tā Asīrijas ķēniņš aizvedīs Ēģiptes cietumniekus un Moru ļaužu aizdzītos, jaunus un vecus, plikus un basām kājām, ar atsegtu pakaļu Ēģiptei par kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Un iztrūcināsies un kaunēsies Moru ļaužu dēļ, uz ko paļāvās, un Ēģiptes dēļ ar ko lielījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Un šīs jūrmalas ļaudis sacīs tai dienā: redzi, vai šis ir mūsu patvērums, kurp mēs skrējām pēc palīga, ka tiktu izglābti no Asīrijas ķēniņa? Kā nu mēs izglābsimies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Spriedums par jūras tuksnesi. Tā kā aukas no dienvidiem(Negebas), kas visu apgāž, tā nāks no tuksneša, no briesmīgas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Grūta parādīšana man darīta zināma. Laupītājs laupa, postītājs posta. Nāc šurp, Elam, apstāj, Medija! Visām nopūtām par tiem es darīšu galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Tādēļ mani gurni dreb, raizes mani sagrābušas, kā dzemdētājas raizes. Es lokos, ka vairs nedzirdu, un iztrūcinājos, ka vairs neredzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Mana sirds trīc, izbailes mani iztrūcina, mīļā nakts tumsa man palikusi par biedēkli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Sataisi galdu, nostādi vaktis, ēd, dzer! Ceļaties, virsnieki, svaidat bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Jo tā Tas Kungs uz mani sacījis: ej, nostādi vaktnieku, lai tas stāsta, ko redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Un viņš redzēja ratus, jātniekus pa pāriem, ēzeļu pulku, kamieļu pulku, un viņš klausīdamies klausījās it uzmanīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Un sauca ar lauvas balsi: Kungs, es stāvu uz vakts torņa visu cauru dienu un vaktēdams vaktēju caurām naktīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Redzi, tur nāk rati ar vīriem un jātnieki pa pāriem. Tad viņš atbildēja un sacīja: kritusi, kritusi Bābele, un visi viņas dievekļu tēli ir sadauzīti pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Ak tu mans izkultais, tu mana klona labībiņa! Ko es esmu dzirdējis no Tā Kunga Cebaot, Israēla Dieva, to jums esmu pasludinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Spriedums par Dumu: uz mani sauc no Seīra: sargs, cik gara vēl nakts? Sargs, cik gara vēl nakts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Tas sargs saka: rīts nāk un atkal nakts. Ja gribat vaicāt, vaicājiet! Atgriežaties, nāciet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Spriedums par Arābiju: Arābijas tuksnešos paliekat par nakti, jūs Dedana ceļa vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Nāciet izslāpušiem pretī ar ūdeni, jūs Temas zemes iedzīvotāji, pasniedziet maizi bēdzējiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Jo tie bēg no zobena, no izvilkta zobena un no uzvilkta stopa un no briesmīgas kaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Jo tā Tas Kungs uz mani sacījis: gada laikā, kādi ir algādža gadi, tad beigsies visa Ķedara godība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Un strēlnieku atlikums no tiem vareniem Ķedara bērniem būs mazums; jo Tas Kungs, Israēla Dievs, to ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Spriedums par parādīšanas ieleju. Kas tev ir, ka jūs visi kāpiet uz jumtiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Tu biji trokšņa pilna, ļaužu pilna pilsēta, līksma pils. Tavi nokautie nav ar zobenu nokauti nedz karā krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Visi tavi virsnieki kopā bēguši, bez stopiem tie ir gūstīti, visi, kas pie tevis top atrasti, ir sasieti, tie tālu bēguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Tādēļ es saku: Atstājaties nost no manis, lai es gauži raudu, nepūlējaties, mani iepriecināt par manas tautas nopostīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Jo tā ir trokšņa un posta un jukas diena no Tā Kunga Dieva Cebaot parādīšanas ielejā, kur mūri grūst, un brēkšana atskan kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Jo Elams nes bultu maku, tur ir vīri uz ratiem, tur ir jātnieki, un Ķire nāk ar spožām priekšturamām bruņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Un tavas jaukās ielejas būs pilnas ratu, un jātnieki apmetīsies pret vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Viņš atsegs apsegu no Jūda, un tai dienā tu lūkosi pēc tām bruņām ciedru koku namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Un jūs redzat Dāvida pilsētas plaisas esam daudz, un jūs krājat lejas dīķa ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Un jūs skaitiet Jeruzālemes namus un nolaužat namus, mūri stiprināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Jūs rokat arīdzan grāvi starp abējiem mūriem priekš vecā dīķa ūdens. Bet jūs neskatāties uz to, kas to dara, un nelūkojiet uz to, kas to sen nolicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Un tai dienā Tas Kungs Dievs Cebaot aicinās raudāt un žēloties, un apcirpties un maisus apvilkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Bet redzi, prieks un līksmība, vēršu kaušana un avju kaušana, gaļas ēšana un vīna dzeršana: ēdīsim un dzersim, jo rītu mums jāmirst');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Bet Tas Kungs Cebaot darījis zināmu manās ausīs: tiešām, šis noziegums jums netaps piedots, kamēr jūs mirsiet, saka Tas Kungs Dievs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Tā saka Tas Kungs Dievs Cebaot: celies, ej pie šī mantas sarga, pie Šebnas, kas celts pār to namu, (un saki)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Ko tu še dari, un kam tu še to dari, ka tu še kapu sev izcērt, ka kalnā roc savu kapu, klintī sev izcērt mājokli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Redzi, Tas Kungs ar varenu sviedienu tevi nosviedīs, cieti tevi sagrābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Velšus Viņš tevi aizvels ar tādu velšanu kā lodi uz zemi, lielu un plašu; tur tu nomirsi, tur paliks tavas godības rati, tu negods sava kunga namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Un Es tevi nogāzīšu no tavas vietas, un no tava amata Es tevi nocelšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Un notiks tai dienā, tad Es aicināšu Savu kalpu Elijaķimu, Hilķijas dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Un Es viņu apģērbšu ar taviem svārkiem un viņu apjozīšu ar tavu jostu, un tavu valdīšanu Es nodošu viņa rokā, un viņš būs par tēvu Jeruzālemes iedzīvotājiem un Jūda namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Un Es Dāvida nama atslēgu likšu uz viņa pleciem, un kur viņš atvērs, tur neviens neaizslēgs, un kur viņš aizslēgs, tur neviens neatvērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Un Es viņu iesitīšu kā naglu stiprā vietā, un viņš būs par goda krēslu sava tēva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Un pie viņa pieķersies visa viņa tēva nama godība, bērni un bērnu bērni, visi mazie trauki, bļodas un krūzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Tai dienā, saka Tas Kungs Cebaot, tā nagla lieksies, kas stiprā vietā bija iesista, tā lūzīs un kritīs, un tā nasta pie tās ies bojā; jo Tas Kungs to ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Spriedums par Tiru. Kauciet, Taršiša kuģi, jo tur ir posts, ka nama vairs nav, neviens vairs uz turieni neiet. No Ķitiju zemes viņiem šī ziņa nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Paliekat klusu, jūs jūrmalas iedzīvotāji! Sidonas veikalnieki, tie jūras braucēji tevi citkārt pildīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Un tā sēkla no Šihora un tās upes labība pa lieliem ūdeņiem vesta, bija viņas krājums, un tur bija tas tautu tirgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Kaunies, Sidona! Jo tā jūra, tā jūras pils runā un saka: es neesmu bijusi grūta, nedz dzemdējusi, ne jaunekļus, ne jaunietes es neesmu uzaudzinājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Kad vēsts nonāk uz Ēģipti, tad iztrūcināsies, kas par Tiru dzirdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Ceļaties pāri uz Taršišu, kauciet, jūs jūrmalas iedzīvotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Vai šī ir jūsu līksmā pilsēta, kas cēlusies no vecu veciem laikiem? Viņas kājas to tālu aiznesušas, svešās zemēs apmesties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kas to nolēmis par Tiru, to kronētāju, kam veikalnieki ir lielkungi, kam tirgotāji ir tie cienīgie virs zemes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Tas Kungs Cebaot to ir nolēmis, ka Viņš kaunā liktu ikvienu glītu greznumu, un negodā visus cienīgos virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Pārplūsti pār savu zemi kā upe, tu Taršiša meita! Nava vairs, kas tevi saista.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Viņš Savu roku ir izstiepis pār jūru, valstis Viņš dara drebam. Tas Kungs pavēlējis par Kanaānu, viņas stiprās pilis izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Un Viņš sacījis: tu nelīksmosies vairs, tu apsmietā jaunava, Sidonas meita. Celies pie Ķitijiem, ej projām, arī tur tev dusas nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Redzi Kaldeju zemi, šī tauta, kas nav bijusi, (Asurs to tuksneša zvēriem ir sataisījis), tie savus stipros torņus ir uzcēluši un Tirus skaistos namus apgāzuši un to nopostījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Kauciet, Taršiša kuģi, jo jūsu stiprās pilis ir izpostītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Un notiks tai dienā, tad Tirus taps aizmirsts septiņdesmit gadus, viena ķēniņa mūžu; bet kad tie septiņdesmit gadi būs pagalam, tad Tirum tā ies, kā par mauku dzied:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Ņem kokli, ej apkārt pa pilsētu, tu aizmirstā mauka! Spēlē jautri, dziedi daudz, lai tevi piemin!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Un notiks pēc septiņdesmit gadiem, tad Tas Kungs piemeklēs Tiru, un Tirus atkal tiks pie savas maucības algas, un dzīs maucību ar visām pasaules valstīm, kas virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Bet viņa peļņa un viņa maucības alga Tam Kungam tiks svētīta, tā netaps sakrāta nedz glabāta; bet viņu peļņa būs tiem, kas Tā Kunga priekšā dzīvo, ka tie ēd un paēd un glīti apģērbjās.-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Redzi, Tas Kungs zemi dara tukšu, un to izposta un pārvērš viņas seju un izklīdina viņas iedzīvotājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Un kā tiem ļaudīm, tāpat klāsies priesterim; kā kalpam, tāpat viņa kungam; kā kalponei tāpat viņas saimniecei; kā pircējam, tāpat pārdevējam; kā aizdevējam, tāpat aizņēmējam; kā pagaidu dzinējam, tāpat pagaidu maksātajam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Postīt to zemi izpostīs, un laupīt viņu izlaupīs; jo Tas Kungs šo vārdu ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Zeme tvīkst un nīkst, zemes virsas gurst un vīst, ļaužu augstie tai zemē gurst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Jo zeme ir sagānīta no saviem iedzīvotājiem, jo tie pārkāpj bauslību un pārgroza likumu un lauž to mūžīgo derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Tādēļ lāsti zemi noēd, un kas tur dzīvo, tiem jācieš; tādēļ zemes iedzīvotāji nokalst un maz cilvēku atliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Vīns nonīcis, vīna koks savītis, visi, kam bija priecīga sirds, nopūšas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Bungu prieks apklusis, līksmu ļaužu troksnis nostājies, kokles prieks pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Vīnu vairs nedzer ar dziesmām, stiprais dzēriens dzērājiem rūgts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Tukša pilsēta izpostīta, visi nami aizslēgti, ka nevar ieiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Vīna pēc žēlojās uz ielām, zuduši visi prieki, zemes līksmība ir projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Posts vien pilsētā atlicis, un vārti salauzti drupu drupās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Jo tā notiks pa zemes virsu tautu starpā, kā kad eļļas koku nokrata, tā kā kad atlikas lasa pēc ķekaru noņemšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Tie paceļ savu balsi un dzied priecīgi, pār Tā Kunga godību tie gavilē no jūras puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Tādēļ godinājiet To Kungu austruma zemē, tais jūras salās Tā Kunga, Israēla Dieva, vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'No zemes gala mēs dzirdam dziesmas par godu tam taisnam. Bet man jāsaka: nelaime, nelaime, ak vai, man! Laupītāji laupa, laupīdami laupa laupītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Briesmas un bedre un valgs pār tevi, tu zemes iedzīvotājs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Kas no briesmu balss izbiedēts bēgs, tas kritīs bedrē, un kas no bedres izkāps, tas taps sagūstīts valgā. Jo augstības logi atvērti un zemes pamati trīc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Zeme sprāgdama sprāgs, zeme plīsdama plīsīs, zeme trīcēdama trīcēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Zeme streipuļos kā piedzēris vīrs un šūposies kā šūpulis, un viņas grēki uz viņas būs smagi, un viņa kritīs un necelsies vairs augšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Un tai dienā Tas Kungs piemeklēs to augstības karaspēku augstībā un tos zemes ķēniņus virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Un tie taps ieslodzīti kā cietumnieki bedrē, un taps saslēgti cietumā, un pēc ilga laika tie atkal taps piemeklēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Un mēnesis nosarks, un saule nobālēs, jo Tas Kungs Cebaot ir ķēniņš Ciānas kalnā un Jeruzālemē, un viņas vecaju priekšā būs godība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Kungs, Tu esi mans Dievs, es Tevi gribu paaugstināt, slavēt Tavu vārdu; jo Tu esi darījis brīnumus. Tavi padomi no sen dienām ir patiesība un uzticība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Jo Tu pilsētu esi padarījis par akmeņu kopu, stipru pili par gruvešiem, svešu ļaužu skaistos namus, ka tā vairs nav pilsēta, - nemūžam to vairs neuzcels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Tāpēc Tevi slavēs stipra tauta, varenu ļaužu pilsētas Tevi bīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Jo Tu esi patvērums nabagam, patvērums vājam viņa bēdās, aizsegs pret plūdiem, pavēnis pret karstumu; jo tie briesmīgie šņāc kā plūdi pret mūri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Tā kā karstumu izkaltušā zemē, tā Tu nospiedi svešo ļaužu trakumu; kā karstums caur padebeša ēnu, tā briesmīgo ļaužu dziesma apklusa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Un Tas Kungs Cebaot darīs uz šī kalna visām tautām taukas dzīres, dzīres no veca vīna, no taukiem ēdieniem un no veca izkāsta vīna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Un Viņš izdeldēs uz šī kalna to vaiga apsegu, ar ko visas tautas ir apsegtas, un to deķi, ar ko visi pagāni apklāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Viņš nāvi aprīs mūžīgi. Un Tas Kungs Dievs noslaucīs asaras no visiem vaigiem un atņems Savu ļaužu negodu no visas zemes virsas; jo Tas Kungs to ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Un tai dienā sacīs: redzi, šis ir mūsu Dievs, uz Viņu esam gaidījuši, ka Viņš mūs izpestī. Šis ir Tas Kungs, uz Viņu esam gaidījuši, lai priecājamies un līksmojamies par Viņa pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Jo Tā Kunga roka dusēs uz šā kalna. Bet Moabs taps samīts apakš Viņa, tā kā salmi top samīdīti mēslos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Un Viņš tur izpletīs Savas rokas tā kā peldētājs tās izpleš peldēdams, un Dievs pazemos viņa greznību līdz ar viņa roku viltību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Un tavus augstos stipros pils mūrus Viņš gāzīs, pazemos un pīšļos metīs pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Tai dienā šo dziesmu dziedās Jūda zemē: mums ir stipra pilsēta, pestīšanu Viņš mums ceļ par mūri un par stipru pili.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Atveriet vārtus, lai taisni ļaudis ieiet, kas ticību tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Kam nešaubīgs prāts, tam Tu uzturi pastāvīgu mieru, jo uz Tevi viņš paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Paļaujaties uz To Kungu mūžīgi, jo Tas Kungs Dievs ir viens akmens kalns mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Jo Viņš nogāž, kas augstībā dzīvo, to augsto pili, to Viņš pazemo, to Viņš pazemo pie zemes, to Viņš met pīšļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Kājas viņu samīs, zemu ļaužu kājas, nabagu pēdas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Taisnam ceļš ir līdzens, taisnam teku Tu līdzini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Uz Tevi, uz Tavas tiesāšanas ceļu mēs arī gaidām, Kungs; pēc Tava vārda un pēc Tavas piemiņas dvēsele kāro!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Mana dvēsele ilgojās pēc Tevis naktī, un mans gars iekš manis agri Tevi meklē. Jo kad Tava sodība parādās virs zemes, tad pasaules iedzīvotāji mācās taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Kad bezdievīgam parāda žēlastību, tad viņš nemācās taisnību; viņš dara netaisnību taisnā zemē, jo viņš neredz Tā Kunga augstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Kungs, Tava roka ir paaugstināta, to tie neredz; tie redzēs kaunēdamies to karstumu par Taviem ļaudīm, un uguns aprīs Tavus pretiniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Kungs, Tu mums dosi mieru, jo visu mūsu darbu Tu mums esi padarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Kungs, mūsu Dievs, citi kungi bez Tevis pār mums valdījuši; bet caur Tevi vien mēs pieminam Tavu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Tie ir nomiruši un netaps dzīvi, tie ir ēnas un vairs necelsies; tā Tu tos esi piemeklējis un izdeldējis un visu viņu piemiņu iznīcinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Tu, Kungs, esi vairojis tos ļaudis, vairojis tos ļaudis, parādījis savu godību, tālu aizcēlis visas zemes robežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Kungs, bēdās tie Tevi meklē, kad Tu tos pārmāci, tad tie gauži lūdzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Tā kā grūtai sievai ir sāpes, kad viņai dzemdēšana uziet, un tā brēc savās raizēs, tā mēs bijām, Kungs, Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Mēs bijām grūti, mēs bijām raizēs, bet dzemdējām tik vēju; mēs tai zemei nevarējām palīdzēt, un pasaules iedzīvotāji nedzima.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Tavi mirušie dzīvos, mani miroņi celsies augšām. Uzmostaties un gavilējiet, jūs, kas pīšļos guliet; jo Tava rasa ir kā rasa uz zāli, un mirušos zeme izdos ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Ejat, Mani ļaudis, ejat savos kambaros, un aizslēdzat savas durvis aiz sevis, paslēpjaties kādu mazu brīdi, kamēr tā dusmība pāriet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Jo redzi, Tas Kungs izies no Savas vietas, piemeklēt netaisnību pie zemes iedzīvotājiem, un zeme atsegs savas asinis un neapklās vairs savus nokautos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Tai dienā Tas Kungs ar Savu cieto, lielo un stipro zobenu piemeklēs Levijatanu, to žiglo čūsku, un Levijatanu, to lunkano čūsku, un nokaus to lielo pūķi, kas jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Tai dienā būs jauks vīna dārzs, dziediet par to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Es, Tas Kungs, to pasargu, ik acumirkli Es to slacinu, lai neviens to neaiztiek, nakti un dienu Es to sargāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Dusmu Man vairs nav. - Ja būtu Manā priekšā ērkšķi un dadži, karā Es pret tiem celtos un tos visus sadedzinātu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ja tie nemeklē Manu palīgu, un neder mieru ar Mani, mieru ja neder ar Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Nākošā laikā Jēkabs iesakņosies, Israēls zaļos un ziedēs un zemes virsu pildīs ar augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Vai Viņš to tā sitis, kā Viņš viņa sitējus sitis? Vai Viņš to tā kāvis, kā Viņš viņu kāvējus kāvis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Mēreni Tu viņu sodīji, kad to liki aizvest, to gauži vētīdams rīta vēja dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Tādēļ Jēkaba noziegums caur to top salīdzināts, un kad viņa grēki atņemti, tad šie ir visi tie augļi, ka visus altāra akmeņus darīs par izkaisītiem gruvekļiem; Ašeras un saules stabi nepastāvēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Jo tā stiprā pilsēta būs tukša, tās mājvietas taps pamestas un atstātas kā tuksnesis; tur teļi taps ganīti, un tur tie gulsies un noēdīs viņa krūmus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Kad viņa zari būs nokaltuši, tad tie taps nolauzti, un sievas nāks un ar tiem kurinās. Jo tie ir ļaudis, kam prāta nav, tādēļ viņu Radītājs par tiem neapžēlosies, un kas tos ir darījis, tas viņiem žēlastības neparādīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Un notiks tai dienā, tad Tas Kungs augļus sakrās no lielupes malas līdz Ēģiptes upei; un jūs visi līdz tapsiet salasīti, Israēla bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Un tai dienā ar lielu bazūni taps bazūnēts, un tad nāks, kas pazuduši Asura zemē un kas izdzīti Ēģiptes zemē, un pielūgs To Kungu uz tā svētā kalna Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Ak vai, tam kronim, ar ko lepojās Efraīma piedzērušies, vai tai savītušai puķei, viņu goda glītumam, kas pušķo bagātās ielejas galvu tiem, kas vīna pārvarēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Redzi, viens stiprs un varens no Tā Kunga tā kā barga krusa, kā briesmīga vētra, tā kā vareni ūdens plūdi, kas varen uzplūst, tā Viņš gāzīs pie zemes ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Kājām samīs to kroni, ar ko lepojās Efraīma piedzērušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Un tai vīstošai puķei, viņu goda glītumam, kas pušķo tās bagātās ielejas galvu, notiek kā agri ienākušai vīģei priekš lasāmā laika; tiklīdz kas to redz un dabū savā rokā, tas to tūdaļ apēd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Tai dienā Tas Kungs Cebaot būs par skaistu kroni un par krāšņu vainagu Savu ļaužu atlikumam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Un par tiesas Garu tiem, kas sēž tiesas amatā, un par stiprumu tiem, kas karu(ienaidu) dzen atpakaļ līdz vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Bet arī šie streipuļo no vīna un sajukuši no stipra dzēriena. Priesteris un pravietis streipuļo no stipra dzēriena, tie ir vīna pārvarēti, tie sajukuši no stipra dzēriena, tie streipuļo pie parādīšanām un klūp tiesu spriezdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Jo visi galdi ir pilni netīru vēmekļu, ka vietas vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Kam tad tas atzīšanu mācīs, un kam tas mācību darīs zināmu? Tiem no piena atradinātiem, tiem no krūtīm nošķirtiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Jo (tie saka:) pavēli uz pavēli, pavēli uz pavēli, likumu uz likumu, likumu uz likumu, maķenīt še, maķenīt te!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Tāpēc ar lūpām, kas stostās, un ar svešu mēli viņš runās uz šiem ļaudīm, kam viņš bija sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, '„Še ir dusa, dodiet piekusušam atpūsties! Un še ir atspirgšana,“- bet tie to negribēja dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Tādēļ tiem notiks Tā Kunga vārds: pavēli uz pavēli, pavēli uz pavēli, likumu uz likumu, likumu uz likumu, maķenīt še, maķenīt te, ka tie ies un atpakaļ kritīs un sadauzīsies un taps savaldzināti un sagūstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Tādēļ klausiet Tā Kunga vārdu, jūs mēdītāji, kas valda pār šiem Jeruzālemes ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Jo jūs sakāt, mēs derību esam derējuši ar nāvi un esam saderējušies ar elli; lai arī tādas pātagas nāk kā plūdi, tomēr tās mūs neaizņems; jo melus esam likuši sev par patvērumu, un apakš viltus esam apslēpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Tādēļ tā saka Tas Kungs Dievs: redzi, Es esmu, kas Ciānā liek pamata akmeni, izraudzītu akmeni, dārgu stūra akmeni, kas it stipri nolikts: kas tic, tas nebēgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Un Es iecelšu tiesu par mēru un taisnību par svaru, un krusa aizraus to melu patvērumu, un ūdens pārpludinās to slēpšanas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Un jūsu derība ar nāvi taps iznīcināta, un jūsu līgums ar elli, tas nepastāvēs. Kad tās pātagas nāks kā plūdi, tad jūs no tām tapsiet samīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Cikkārt tās nāks, tās jūs aizraus, jo ik rītu tās nāks, dienu nakti. Tikai briesmas būs, dzirdēt to sludināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Jo gulta ir īsa, ka nevar izstiepties, un apsegs šaurs, ka nevar ietīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Jo Tas Kungs tāpat celsies kā pie Pracim kalna, Viņš tāpat dusmosies kā Gibeonas ielejā, Savu darbu darīt, - Viņa darbs būs dīvains, un Savu strādāšanu pastrādāt, Viņa strādāšana būs dīvaina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Nu tad, nemēdiet vairs, ka jūsu saites netop cietākas, jo es esmu dzirdējis izdeldēšanu, noliktu no Tā Kunga Dieva Cebaot pār visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Griežat šurp ausis un klausiet manu balsi, ņemiet vērā un klausiet, ko es runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Vai tad arājs vienmēr ars, kad grib sēt, kārtos un ecēs savu zemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Vai nav tā? Kad viņš to virsu ir līdzinājis, tad kaisa dilles un met ķimenes, vai sēj kviešus pēc kārtas, vai miežus, vai rudzus, ikkatru savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Un viņa Dievs viņam rādījis, kā piederas, un viņu pamācījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Jo dilles netop kultas ar ruļļiem, nedz bluķi top vesti pār ķimenēm, bet dilles top kultas ar spriguli, un ķimenes ar kulstekli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Vai maizes labība top sagrūsta? Nē, to nesakuļ pavisam; to izkuļ ar saviem bluķiem un zirgiem, bet nesagrūž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Arī tas nāk no Tā Kunga Cebaot, Viņš ir brīnišķīgs padomā un liels gudrībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ak vai, Ariel, Ariel, pilsēta, kur Dāvids mitis, lai vēl gads ar gadu mijās, lai vēl svētki savā rindā pāriet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Tad Es Arieli gribu apbēdināt, un tur būs vaidi un skumjas, un Man tomēr būs kā Ariels (Dieva lauva).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Jo Es gan apmetīšos visapkārt pret tevi un tevi spaidīšu ar karaspēku un uzcelšu pret tevi vaļņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Tad tu tapsi pazemota, tu runāsi no zemes, un tava valoda skanēs klusiņām no pīšļiem, un tava balss būs kā burvja balss no zemes, un tava valoda čukstēs no pīšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Un tavu ienaidnieku pulks būs tāpat kā smalki putekļi, un tas varas darītāju pulks kā vieglas pelavas, un tas notiks vienā acumirklī piepeši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Tu tapsi piemeklēta no Tā Kunga Cebaot ar pērkoni un ar zemes trīcēšanu un ar lielu rūkšanu, ar viesuli un ar aukām un ar rijošu uguns liesmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Bet kā sapņa parādīšana naktī, tā būs visu pagānu pulks, kas karos pret Arieli, un visi, kas karos pret viņu un pret viņa pilīm un to spaidīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Tas būs tā, kā kad izsalcis sapnī redz, ka tas ēd, bet kad uzmostas, tad viņa sirds tukša, vai kā kad izslāpis sapnī redz, ka tas dzer, bet kad uzmostas, tad vēl ir izslāpis, un viņa sirds tvīkst. Tā būs ar visu pagānu pulku, kas karo pret Ciānas kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Iztrūcinājāties un brīnāties, paliekat stulbi un akli! Tie ir piedzērušies, bet ne no vīna, tie streipuļo, bet ne no stipra dzēriena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Jo Tas Kungs pār jums izlējis grūta miega garu, un jūsu acis, tos praviešus, Viņš ir aizdarījis, un jūsu galvas, tos redzētājus, apstulbojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Tādēļ jums visa parādīšana palikusi kā aizzieģelētas grāmatas vārdi, ko vienam dod, kas māk lasīt, un saka: lasi jel šo! Un viņš saka: es nevaru, ja tā ir aizzieģelēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Un to grāmatu dod vienam, kas nemāk lasīt, un saka: lasi jel šo! Un viņš saka: es nemāku lasīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Jo Tas Kungs ir sacījis: tādēļ ka šie ļaudis pie Manis nāk ar savu muti un Mani godā ar savām lūpām, bet viņu sirds ir tālu no Manis nost, un ka tie Mani bīstas pēc cilvēku baušļiem, kas tiem top mācīti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Tādēļ, redzi, Es joprojām ar šiem ļaudīm darīšu brīnišķi, brīnišķi un apbrīnojami, ka viņu gudro gudrība zudīs, un viņu prātīgo prāts apslēpsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Ak vai, tiem, kas savu padomu dziļi grib apslēpt no Tā Kunga, un kuru darbi notiek tumsībā, un kas saka: kas mūs redz un kas mūs pazīst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Ak tavu bezprātību! Vai māls turams podniekam līdzi, ka darbs sacītu par savu darītāju: viņš mani nav darījis, un tēls par savu tēlotāju: viņš neprot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Vai nav tikai mazs brīdis vēl, ka Lībanus taps darīts par auglīgu tīrumu, un auglīgais tīrums taps turēts par mežu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Un tai dienā kurlie dzirdēs grāmatas vārdus, un aklo acis redzēs no krēslas un tumsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Un bēdīgiem būs atkal prieks iekš Tā Kunga, un nabagi starp cilvēkiem līksmosies iekš Israēla Svētā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Ka varas darītājam gals klāt, un mēdītājs beigts, un visi izdeldēti, kas uz blēņām domā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Kas viena vārda dēļ cilvēku notiesā un liek valgus tam, kas vārtos pārmāca, un taisno nospiež ar viltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Tādēļ Tas Kungs, kas Ābrahāmu atpestījis, saka uz Jēkaba namu: Jēkabs vairs netaps kaunā, un viņa vaigs vairs nenobālēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Jo kad viņš, kad viņa bērni redzēs Manu roku darbu savā vidū, tad tie svētīs Manu Vārdu un svētīs to Svēto iekš Jēkaba un bīsies Israēla Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Un tie, kam gars alojās, nāks pie saprašanas, un kurnētāji pieņems mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Ak vai, tiem stūrgalvīgiem bērniem, saka Tas Kungs, kas padomu ņemas, bet ne no Manis, un derību der, bet bez Mana Gara, un krāj grēku uz grēku!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Kas ceļas iet uz Ēģipti, nevaicādami Manu muti, un stiprinājās ar Faraona spēku un meklē patvērumu apakš Ēģiptes ēnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Faraona spēks jums būs par kaunu, un tas patvērums apakš Ēģiptes ēnas par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Jo viņa (t.i. Jūda) virsnieki gan bijuši Coanā, un viņa vēstneši nākuši līdz Hanesai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Bet visi paliks kaunā pie tās tautas, kas viņiem nederēs nedz par palīgu, nedz par citu labumu, bet būs par kaunu vien un par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Spriedums par dienvidu Beēmotu(zvēru). Pa bēdu un izbaiļu zemi, kur lauvu mātes un lauvas, odzes un skrejoši pūķi, tie savu mantu vedīs kumeļu mugurā, un savu bagātību uz kamieļu kupriem, pie tautas, kas nekā nepalīdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Jo Ēģiptes zeme nav nekas un it nekā nepalīdzēs; tādēļ Es to nosaucu par lielmuti, kas paliek sēžot uz vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Nu tad ej, raksti to viņu priekšā uz galdu un ieraksti to grāmata, ka tas paliek uz nākamām dienām mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Jo tā ir stūrgalvīga tauta, tie ir melkuļu bērni, bērni, kas Tā Kunga bauslību negrib klausīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Kas uz redzētājiem saka: neredziet! Un uz sludinātājiem: nesludinājiet mums patiesīgu mācību! Runājiet uz mums ar mīkstu mēli! Sludinājiet viltu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Atkāpjaties no ceļa, atstājaties no tekas, lai paliek nost no mums Israēla Svētais!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Tādēļ Israēla Svētais tā saka: Tāpēc ka jūs šo vārdu atmetat un ceriet uz varas darbu un blēdību un uz to paļaujaties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Tāpēc jums šis noziegums būs tā kā plaisums ielīkušā krītošā augstā mūrī, kas piepeši vienā acu mirklī sagrūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Un tas tos sadauzīs tāpat kā podnieks sadauza trauku, ko dauzot netaupa, un kad tas satriekts, neviena gabaliņa neatliek, ar ko uguni varētu ņemt no ugunskura vai ūdeni smelt no akas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Jo tā saka Tas Kungs Dievs, tas Svētais iekš Israēla: caur atgriešanos un norimšanu jūs taptu izglābti, caur klusu sirdi un cerību jūs varētu stipri būt, bet jūs neesat gribējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Un jūs sakāt: nē, bet uz zirgiem mēs gribam skriet: tāpēc jums būs skriet; un uz čakliem zirgiem mēs gribam jāt: tāpēc arī tie jās čakli, kas jums dzenās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Viens tūkstotis (bēgs) no viena vienīga (vīra) draudiem, no piecu draudiem jūs bēgsiet, līdz kamēr no jums atliksies tik kā masta koks kalna galā un kā karogs pakalna virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Un tādēļ Tas Kungs gaidīs, pirms jums būs žēlīgs, un augsti pacelsies, pirms pār jums apžēlosies; jo Tas Kungs ir Dievs, kas tiesās: svētīgi visi, kas uz Viņu cerē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Jo tu, Ciānas tauta, kas dzīvo Jeruzālemē, raudot tu vienmēr neraudāsi, apžēlodamies Viņš par tevi apžēlosies uz tavas saukšanas balsi; kad Viņš tevi dzirdēs, tad tev atbildēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Tas Kungs jums dos bēdās maizi un izbailēs ūdeni. Un tavi mācītāji vairs neapslēpsies, bet tavas acis redzēs tavus mācītājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Un tavas ausis dzirdēs aiz tevis šo vārdu: šis ir tas ceļš, staigājiet pa to! Kad jūs nogriezušies vai pa labo vai pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Un jūs sagānīsiet savu izgriezto sudraba bilžu uzvalkus un savu izlieto zelta bilžu drēbes; tās tu nometīsi tā kā sārņus un sacīsi uz tām: nost!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Tad Viņš dos lietu tavai sēklai, ar ko tu savu zemi esi apsējis, un maizi no zemes augļiem, un tā būs trekna un tauka. Un tavi lopi tai dienā taps ganīti plašās ganībās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Un tie vērši un ēzeļi, ar ko zemi strādās, ēdīs sālītu mistru, kas vētīts ar liekšķeri un vētekli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Un pa visiem augstiem kalniem un pa visiem lieliem pakalniem būs upītes un ūdens strauti, tās lielās kaušanas dienā, kad torņi sagrūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Un mēness gaišums būs kā saules gaišums, un saules gaišums septiņkārt gaišāks nekā septiņu dienu gaišums, tai dienā, kad Tas Kungs Savu ļaužu vainu sasies un to vāti dziedinās, ar ko tie ievainoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Redzi, Tā Kunga vārds nāk no tālienes, Viņa dusmība deg un ir grūti nesama, Viņa lūpas ir bardzības pilnas, un Viņa mēle tā kā rijoša uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Un Viņa dvaša ir kā ūdens plūdi, kas sniedzās līdz kaklam, ka Viņš pagānus sijā ar posta sietu un tautām žokļos liek iemauktus, kas maldina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Tad pie jums dziedās kā svētku naktī, un jūsu sirds priecāsies it(kā tiem), kas ar stabulēm nāk uz Tā Kunga kalnu, uz Israēla akmens kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Un Tas Kungs liks dzirdēt Savas balss godību un liks redzēt Savu izstiepto elkoni ar bargām dusmām un ar rijošu uguns liesmu, ar zibeni un ar plūdiem un ar krusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Jo Asurs iztrūcināsies no Tā Kunga balss, kad Viņš ar rīksti sitīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Un pie katra cirtiena ar to nospriesto rīksti, ko Tas Kungs laidīs Asuram virsū, skanēs bungas un kokles, un ar karstu karošanu Viņš pret to karos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Jo bedre jau sen ir gatava, arī priekš ķēniņa tā ir gatava, dziļa un plata; viņas uguns- un malkas- kopa ir varen liela; Tā Kunga dvaša to iededzinās kā sēra strautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Ak vai, tiem, kas uz Ēģipti iet pēc palīdzības un paļaujas uz zirgiem un cerē uz ratiem, tāpēc ka to ir daudz, un uz jātniekiem, tāpēc ka to ir liels pulks, bet uz to Svēto iekš Israēla nerauga un To Kungu nemeklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Bet arī Viņš ir gudrs un liek ļaunumam nākt un neņem atpakaļ Savus vārdus, bet ceļas pret bezdievīgo namu un pret ļauna darītāju palīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Jo ēģiptieši ir cilvēki un ne Dievs, un viņu zirgi ir miesa un ne gars. Un Tas Kungs izstieps Savu roku, un tas palīgs klūp un, kam top līdzēts, tas krīt, un tie visi kopā iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Jo tā Tas Kungs uz mani sacījis: tā kā lauva un kā jauns lauva rūc par savu laupījumu, un, jebšu pret viņu liels ganu pulks top sasaukts, tomēr viņš neizbīstas priekš viņu balss un nebaidās no viņa lielā pulka, tāpat Tas Kungs Cebaot nolaidīsies, karot uz Ciānas kalna un uz viņas augstuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Tā kā putni lidinājās, tāpat Tas Kungs Cebaot apklās Jeruzālemi, un apklādams izpestīs un žēlodams izglābs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Atgriežaties, Israēla bērni, pie Tā, no kā tik tālu esat atkāpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Jo tai dienā tie atmetīs ikkatrs savus sudraba elkus un savus zelta elkus, ko jūsu rokas ir taisījušas sev par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Un Asurs kritīs caur zobenu, bet ne caur vīra zobenu, un to norīs, bet ne cilvēka zobens, un tas bēgs no zobena un viņa jaunekļi paliks par vergiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Un viņa kalns trīcēs no bailēm, un viņa lielkungi iztrūcināti bēgs no karoga; to saka Tas Kungs, kam Ciānā uguns un Jeruzālemē ugunskurs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Redzi, viens ķēniņš valdīs ar taisnību, un lielkungi valdīs pēc tiesas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Un ikkatrs būs kā patvērums pret vēju un pavēnis pret negaisu, tā kā ūdens upes izkaltušā zemē, kā varena klints kalna ēna iztvīkušā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Un redzētāju acis nebūs vairs aptumšotas, un klausītāju ausis klausīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Un neapdomīgiem sirds zinās saprast, un tiem, kam grūta valoda, mēle būs čakla un runās skaidri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Ģeķi vairs nesauks par lielkungu, un blēdi vairs nesauks par cienīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Jo ģeķis runā ģeķību, un viņa sirds dara blēņas, tas dzen negantību, un runā māņus pret To Kungu un pamet izsalkušā dvēseli tukšu un nedod dzert noslāpušam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Jo blēža padomi ir neganti, viņš izdomā viltu, samaitāt bēdu ļaudis ar melu valodu, arī kad nabags taisnību runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Bet tiem cienīgiem ir cienīgas domas un tie pastāvīgi turas pie tam, kas cienījams. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ceļaties, lepnās sievas, klausiet manu balsi, jūs meitas, kas tik droši dzīvojat, ņemat vērā manu valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Pēc gada un kādām dienām jūs drošās drebēsiet; jo vīna ogas nelasīs un dārza augļus nesaņems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Trīciet, lepnās! Drebiet, drošās, noģērbjaties un atsedzaties un apjožaties ap saviem gurniem (ar maisu)!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Raudot sitīsiet pie krūtīm par tiem jaukiem tīrumiem, par tiem auglīgiem vīna kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Manu ļaužu zemē uzdīgs ērkšķi un dadži, ir visos prieka namos tai līksmā pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Jo tie augstie nami taps atstāti, pilsētas troksnis apklusīs, torņi un pils vietas būs par alām mūžīgi, meža ēzeļiem par līksmību un ganāmiem pulkiem par ganību, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Līdz kamēr pār mums top izliets Tas Gars no augšienes. Tad tuksnesis būs par auglīgu tīrumu, un auglīgais tīrums kā mežs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Un tiesa dzīvos tuksnesī, un taisnība mājos uz auglīga tīruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Un taisnības nopelns būs miers, un taisnības auglis būs klusums un drošība mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Un mani ļaudis dzīvos miera namos un drošos dzīvokļos un netraucētos mitekļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Bet krusa būs, kad mežs gāzīsies, un pilsēta nogrims zemībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Svētīgi jūs, kas sējat pie visiem ūdeņiem, kas vērša un ēzeļa kāju tur varat palaist vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Ak vai, tev, postītāj, kas pats neesi postīts, un laupītāj, kas neesi aplaupīts; kad būsi beidzis postīt, pats tapsi postīts, kad būsi beidzis laupīt, tad tevi aplaupīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Kungs, esi mums žēlīgs, uz Tevi mēs gaidām; esi viņu elkonis ikkatru rītu, un mūsu pestīšana bēdu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Tautas bēg no trokšņa rībēšanas, pagāni izklīst, kad tu celies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Jūsu laupījumu sagrābj, tā kā vaboles lauku noēd, tā kā siseņi skraida, tā tur skraida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Tas Kungs ir paaugstināts, jo viņš dzīvo augstībā, viņš Ciānu piepildījis ar tiesu un taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Un tavā laikā būs ticība, pestīšanas bagātība, gudrība un atzīšana, Tā Kunga bijāšana būs Viņa manta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Redzi, viņu varenie ārā brēc, tie miera vēstneši gauži raud.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Lielceļi ir tukši, un tur nav ceļa gājēju, Viņš lauž derību, Viņš atmet pilsētas un nebēdā par cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Zeme vaid un tvīkst, Lībanus kaunās un kalst, Šarona ieleja palikusi kā tuksnesis, Basans un Karmels birdina savas lapas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nu Es celšos, saka Tas Kungs, nu Es paaugstināšos, nu Es parādīšos liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Jūs nesaties ar salmiem, rugājus jūs dzemdēsiet; jūsu trakums ir uguns, kas pašus aprīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Tautas taps dedzinātas kā kaļķi, ar uguni taps sadedzināti, kā nocirsti ērkšķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Klausiet jūs, kas esat tālu, ko Es esmu darījis, un kad esat tuvu, atzīstiet Manu varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Grēcinieki Ciānā ir izbijušies, drebēšana uzkrīt bezdievīgiem, (tie saka): kurš no mums var dzīvot rijošā ugunī? Kurš no mums var palikt mūžīgās liesmās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Kas taisnībā staigā un runā patiesību, kas netaisnu peļņu ienīst, kas savas rokas sargā no dāvanu ņemšanas, kas savas ausis aizbāž, neklausīties uz asins padomu, kas savas acis aizdara, nelūkot uz ļaunu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Tas dzīvos augstībā, kalnu stiprumi viņam būs par patvērumu; viņam būs sava maize, ūdens viņam nepietrūks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Tavas acis redzēs ķēniņu viņa skaistumā. Tās redzēs plašu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Tava sirds pieminēs to bailību un sacīs: Kur ir tas rakstītājs, kur ir tas svērējs, kur ir tas torņu uzzīmētājs');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'To briesmīgo tautu tu vairs neredzēsi, tos ļaudis, kam sveša mēle, ka nevar izprast, kas valodā stostās, ka nevar saprast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Redzi Ciānu, mūsu saiešanas pilsētu! Tavas acis redzēs Jeruzālemi, drošu dzīvokli, telti, kas netop aizvesta, kam vadži netop izvilkti ne mūžam, un kam virves netop saraustītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Jo Tas Kungs būs tur pie mums, tas augsti teicamais; tā būs vieta, kur upes un plati strauti, ka laiva ar airiem tur neies, un liela laiva tur necelsies pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Jo Tas Kungs ir mūsu tiesātājs, Tas Kungs ir mūsu bauslības devējs, Tas Kungs ir mūsu ķēniņš, Viņš mūs atpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tavas virves būs vaļējas, tās masta koku stingri neturēs, arī karogs nebūs izplests, - tad taps daudz laupījuma izdalīts, kā arī tizlie laupīs laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Un neviens iedzīvotājs nesacīs: es esmu vājš; jo tiem ļaudīm, kas tur dzīvo, grēki būs piedoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Nāciet klāt, pagāni, klausīties, un tautas, ņemiet vērā! Lai dzird zeme un kas tur mīt, pasaule un viss, kas tur rodas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Jo Tā Kunga dusmība ir pār visiem pagāniem un bardzība pār visu viņu pulku; Viņš tos izdeldēs un tos nodos uz kaušanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Un viņu nokautie taps nosviesti, un no viņu līķiem celsies smaka, un kalni izkusīs no viņu asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Un viss debesu pulks iznīkst, un debesis top satītas kā grāmatu rullis, un viss viņu pulks savīst, tā kā lapas vīst pie vīnakoka, un kā tās vīst pie vīģes koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Jo Mans zobens ir dusmu pilns debesīs; redzi, tas nolaidīsies par sodību uz Edomu un uz tiem ļaudīm, ko Es izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Tā Kunga zobens aptraipās asinīm un taukiem, jēru un āžu asinīm, aunu īkšķu(nieru) taukiem; jo Tam Kungam ir upurēšana Bocrā un liela kaušana Edoma zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Tad sumbri līdz ar viņiem kritīs pie zemes, un jauni vērši līdz ar barotiem, un viņu zeme būs piedzērusies no asinīm un viņu pīšļi taps trekni no taukiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Jo šī būs atriebšanas diena Tam Kungam, atmaksāšanas gads, lai Ciāna dabū taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Un (Edoma) upes pārvērtīsies par darvu un viņa pīšļi par sēru, un viņa zeme taps par degošu darvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Ne nakti, ne dienu tas neizdzisīs, bet viņas dūmi uzkāps mūžīgi, līdz cilšu ciltīm tā būs postā, neviens tur nestaigās ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Bet pelikāns un ezis to iemantos, un pūce un krauklis tur mājos; jo viņš to atmēros tuksnesim un nosvērs postam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Viņas cienīgie, - tiem vairs nebūs ķēniņa, ko lai izsauc, un visi viņas lielkungi būs par nieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Un viņas skaistos namos uzdīgs ērkšķi, nātres un dadži viņas pilīs, un būs mājas vieta vilkiem un pagalms jauniem strausiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Tur satiekās tuksneša vilki un šakāļi, un jods(āžkāja) brēc uz jodu, ir nakts biedēklis tur apmetīsies un dusēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Un tas lēkātājs zalktis tur darīs ligzdu un dēs un perēs un sapulcinās savu perēkli apakš savas ēnas, arī vanagi viens ar otru tur pulcēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Meklējiet Tā Kunga grāmatā un lasiet! Neviena no tiem netrūkst, tie visi sarodas kopā; jo (Tā Kunga) mute to ir pavēlējusi, un Viņa Gars tos sapulcinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Un Viņš pats tiem to daļu nolēmis, un Viņa roka tiem to ir nomērojusi par tiesu, mūžam tie to paturēs, uz dzimumu dzimumiem tie tur mitīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Sausā un tukšā zeme priecāsies, un klajums līksmosies un ziedēs kā rozes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Ziedēt tas ziedēs un līksmosies ar prieku un gavilēšanu; Lībanus godība tam ir dota, Karmeļa un Šarona glītums, - tie redzēs Tā Kunga godību, mūsu Dieva glītumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Stiprinājiet nogurušās rokas un dariet stingrus gurdenos ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Sakāt tām samisušām sirdīm: esiet stipras, nebīstaties! Redzi, jūsu Dievs! Atriebšana nāk, atmaksāšana no Dieva; Viņš nāk un jūs atpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Tad aklu acis taps atvērtas un kurlu ausis atdarītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Tad tizlais lēkās kā stirna, un mēmu mēle slavēs priecīgi. Jo tuksnesī izvirs ūdeņi, un upes klajumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Un sausums taps par ezeru un izkaltusi zeme par ūdens avotiem. Tanīs vietās, kur vilki mituši, būs zāle ar niedrēm un ašķiem(ezera meldrs).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Un tur būs liels ceļš. Ceļš, ko nosauks par svētu ceļu; kas nešķīsts, pa to nestaigās, jo tas pieder šķīstiem, kas pa to ceļu staigā, - pašas nesaprašas tur nevar maldīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Tur nebūs lauvas, un plēsīgs zvērs tur nerādīsies un neatradīsies, bet tie atpestītie pa to staigās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Un Tā Kunga atpirktie griezīsies atpakaļ un nāks uz Ciānu ar gavilēšanu, un mūžīga līksmība būs pār viņu galvām; prieks un līksmība tos apkamps, bet skumjas un bēdas bēgs projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Un notikās ķēniņa Hizkijas četrpadsmitā gadā, tad Sanheribs, Asīrijas ķēniņš, cēlās pret visām stiprām Jūda pilsētām un tās uzņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Un Asīrijas ķēniņš sūtīja Rabzaku no Laķisa uz Jeruzālemi pie ķēniņa Hizkijas ar varen lielu karaspēku, un viņš stāvēja pie augšēja dīķa grāvjiem, vadmalnieka tīruma ceļa malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Tad pie viņa izgāja nama uzraugs Elijaķims, Hilķijas dēls, un skrīveris Šebna, un kanclers Joaks, Asafa dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Un Rabzakus uz tiem sacīja: sakāt jel Hizkijam: Tā saka tas lielais ķēniņš, Asīrijas ķēniņš: Kas tas tāds patvērums, uz ko tu paļaujies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Es saku: tas ir tukšs vārds, ka diezgan esot padoma un spēka uz karu; uz ko tad tu paļaujies, ka tu no manis esi atkritis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Redzi, tu paļaujies uz to salūzušo niedri, uz Ēģipti. Kas uz to atspiežas, tam tā ies rokā un to pārdurs. Tāds ir faraons, Ēģiptes ķēniņš, visiem, kas uz viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Bet ja tu uz mani saki: Mēs paļaujamies uz To Kungu, savu Dievu, - vai tas nav tas pats, kam kalnus un altārus Hizkija ir nopostījis un sacījis uz Jūdu un Jeruzālemi: priekš šī altāra še jums būs pielūgt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Nu tad, noderi jel ar manu kungu, Asīrijas ķēniņu, un es tev došu divtūkstoš zirgus, ja tev ir jātnieki, ko tiem likt virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kā tad tu varēsi atsist atpakaļ vienu pašu virsnieku no mana kunga vismazākiem kalpiem? Bet tu paļaujies uz Ēģipti, ratu un jātnieku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Vai tad nu es bez Tā Kunga esmu cēlies pret šo zemi, to izpostīt? Tas Kungs uz mani sacījis: Celies pret šo zemi un izposti to!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Tad Elijaķims un Šebna un Joāks sacīja uz Rabzaku: Runā jel ar saviem kalpiem sīriski, mēs to gan protam, un nerunā ar mums jūdiski priekš šo ļaužu ausīm, kas ir uz mūra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Bet Rabzakus sacīja: Vai mans kungs mani sūtījis pie tava kunga un pie tevis, šos vārdus runāt, vai ne pie tiem vīriem, kas sēž uz mūra, kam līdz ar jums būs jāēd savi sūdi un jādzer savi mīzali?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Un Rabzakus nostājās un sauca ar stipru balsi jūdiski un sacīja: klausāties tā lielā ķēniņa, Asīrijas ķēniņa, vārdus!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Tā saka ķēniņš: Lai Hizkija jūs neapmāna, jo viņš jūs nevarēs izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Lai arī Hizkija jums nedara cerību uz To Kungu, sacīdams: tiešām, Tas Kungs mūs izglābs, šī pilsēta netaps dota Asīrijas ķēniņa rokā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Neklausāties uz Hizkiju. Jo tā saka Asīrijas ķēniņš: Deriet ar mani mieru un nākat pie manis ārā, tad ikviens ēdīs no sava vīna koka un ikviens no sava vīģes koka, un ikviens dzers ūdeni no savas akas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Kamēr es nākšu, un jūs aizvedīšu tādā zemē, kā jūsu zeme, zeme, kur ir labība un vīns, zeme, kur ir maize un vīna dārzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Lai Hizkija jūs nepieviļ, sacīdams: Tas Kungs mūs izglābs! Vai gan pagānu dievi ikviens savu zemi izglābuši no Asīrijas ķēniņa rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kur ir Hamatas un Arpadas dievi, kur ir Sefarvaimas dievi? Vai tie gan Samariju izglābuši no manas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kurš no visiem šo zemju dieviem savu zemi izglābis no manas rokas? Kā tad Tas Kungs Jeruzālemi izglābs no manas rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Bet tie cieta klusu un viņam neatbildēja neviena vārda, jo ķēniņš bija pavēlējis un sacījis: Jums nebūs viņam atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Tad nama uzraugs Elijaķims, Hilķijas dēls, un skrīveris Šebna un kanclers Joaks, Asafa dēls, nāca pie Hizkijas ar saplēstām drēbēm un viņam stāstīja Rabzakus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Kad nu ķēniņš Hizkija to dzirdēja, tad viņš saplēsa savas drēbes un apsedzās ar maisu un gāja Tā Kunga namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Un sūtīja nama uzraugu Elijaķimu un skrīveri Šebnu un tos priesteru vecajus, maisos ģērbušos, pie pravieša Jesajas, Amoca dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Un tie uz viņu sacīja: Tā saka Hizkija: Šī diena ir bēdu- un sodības- un kauna- diena; jo bērni nākuši uz dzimšanu, un spēka nav dzemdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Kaut Tas Kungs, tavs Dievs, dzirdētu Rabzakus vārdus, ko viņa kungs, Asīrijas ķēniņš, ir sūtījis, zaimot to dzīvo Dievu, un pārmācītu par tiem vārdiem, ko Viņš ir dzirdējis, Tas Kungs, tavs Dievs! Celies tad un lūdz par tiem atlikušiem, kas vēl atrodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Un ķēniņa Hizkijas kalpi nāca pie Jesajas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Un Jesaja uz tiem sacīja: tā jums būs sacīt savam kungam: tā saka Tas Kungs: nebīsties par tiem vārdiem, ko tu esi dzirdējis, ar ko Asīrijas ķēniņa sulaiņi Mani zaimojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Redzi, Es tam došu tādu garu, ka tas dzirdēs baumas un ies atpakaļ uz savu zemi, un Es viņam likšu krist caur zobenu viņa zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Tad Rabzakus gāja atpakaļ un atrada Asīrijas ķēniņu pret Libnu karojam, jo viņš bija dzirdējis, ka tas no Laķisa jau bija aizgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Un viņš par Tiraku, Moru ķēniņu, dzirdēja sakām: viņš ir izgājis, ar tevi karot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Kad viņš to dzirdēja, tad viņš atkal sūtīja vēstnešus pie Hizkijas un sacīja: tā runājiet uz Hizkiju, Jūda ķēniņu, un sakāt: lai tevi nepieviļ tavs Dievs, uz ko tu paļaujies sacīdams: Jeruzāleme netaps dota Asīrijas ķēniņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Redzi, tu esi dzirdējis, ko Asīrijas ķēniņi darījuši visām zemēm, tās izdeldēdami; un tu domā izglābties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Vai pagānu dievi tos glābuši, ko mani tēvi postījuši, Gozanu un Haranu un Recevu un Edeņa bērnus, kas bija Telasarā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kur ir Hamatas ķēniņš un Arpadas ķēniņš un Sefarvaimas pilsētas, Enas un Ivas ķēniņš?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Kad nu Hizkija bija dabūjis tās grāmatas no vēstneša rokas un tās izlasījis, tad viņš gāja Tā Kunga namā, un Hizkija tās atpleta Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Un Hizkija pielūdza Tā Kunga priekšā un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Ak Kungs Cebaot, Tu Israēla Dievs, kas sēž pār ķerubiem, Tu viens pats esi Dievs pār visām zemes valstīm, Tu esi radījis debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Atgriez, ak Kungs, Savas ausis un klausies, atveri, ak Kungs, Savas acis un redzi, un dzirdi visus Sanheriba vārdus, ko viņš sūtījis, zaimot to dzīvo Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Patiesi, Kungs, Asīrijas ķēniņi ir postījuši visas zemes malas ar visām viņu valstīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Un viņu dievus metuši ugunī, jo tie nebija dievi, bet cilvēku roku darbs, koks un akmens, tāpēc tie tos ir postījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Nu tad, ak Kungs, mūsu Dievs, izglāb mūs jel no viņa rokas, lai visas valstis virs zemes atzīst, ka Tu vien esi Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Tad Jesaja, Amoca dēls, sūtīja pie Hizkijas un lika sacīt: Tā saka Tas Kungs, Israēla Dievs: par ko tu Mani esi pielūdzis pret Sanheribu, Asīrijas ķēniņu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Šis ir tas vārds, ko Tas Kungs pret viņu runājis: tevi nievā, tevi apsmej jaunava Ciānas meita, aiz tevis galvu krata Jeruzālemes meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Ko tu esi apsmējis un zaimojis, un pret ko tu esi pacēlis balsi un augsti uzcēlis savas acis? Pret To Svēto iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Caur saviem kalpiem tu To Kungu esi apmēdījis un sacījis: ar savu ratu pulku es uzkāpju kalnu galos, Lībanus virsgalā, un izcērtu viņa augstos ciedru kokus un izlasītās priedes, un tieku līdz pat viņa galam, viņa kuplākam mežam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Es roku un dzeru ūdeni un no manu kāju pēdām paliek sausas visas Ēģiptes upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Vai tu neesi dzirdējis, ka Es jau sen iepriekš to esmu sataisījis, jau vecos laikos to esmu apņēmies. Un tagad Es tam esmu licis notikt, ka tu izposti stipras pilsētas un dari par akmeņu kopām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Tāpēc viņu iedzīvotājiem nogura rokas, un tie iztrūcinājās un tapa kaunā, un tie bija ka zāle laukā un kā uzzēlis zaļums, tā kā zāle uz jumtiem, kā rūsaina labība, pirms nāk stiebros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Bet Es zinu tavu sēdēšanu un tavu iziešanu un tavu ieiešanu un tavu trakošanu pret Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Tavas trakošanas dēļ pret Mani un tavas pārgalvības pēc, kas nākusi Manās ausīs, Es Savu kāsi likšu tavās nāsīs un Savus laužņus tavā mutē, un Es tev likšu griezties atpakaļ pa to ceļu, kur tu esi nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Un tas tev būs par zīmi: šai gadā ēdīs papuvē augušu un otrā gadā ataugu, bet trešā gadā sējat un pļaujat un stādāt vīna dārzus un ēdat viņu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Un kas no Jūda nama ir izglābts un atlicis, sakņos atkal zemjup un nesīs augļus augšup.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Jo no Jeruzālemes izies atlikuši un atpestīti no Ciānas kalna. To darīs Tā Kunga Cebaot karstums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Tādēļ tā saka Tas Kungs par Asīrijas ķēniņu: viņš šai pilsētā nenāks un tanī neiešaus nevienu bultu un nepacels pret to priekšturamās bruņas un neuzmetīs pret to valni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Pa to pašu ceļu, kur viņš nācis, viņam būs griezties atpakaļ, bet šai pilsētā viņš nenāks, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Jo Es šo pilsētu paglabāšu un izpestīšu, Sevis labad un Sava kalpa Dāvida labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Tad Tā Kunga eņģelis izgāja un nokāva Asiriešu lēģerī simts astoņdesmit piecus tūkstošus. Un kad no rīta agri cēlās, redzi, tad tur viss bija pilns miroņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Tā Sanheribs, Asīrijas ķēniņš, aizgāja un gāja projām un griezās atpakaļ un palika Ninivē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Un kad viņš pielūdza Nizroka, sava dieva, namā, tad Adrameleķs un Sarecers, viņa dēli, to nokāva ar zobenu un aizbēga uz Ararat zemi. Un viņa dēls Asaradons palika par ķēniņu viņa vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Tanī laikā Hizkija palika slims uz miršanu, un pravietis Jesaja, Amoca dēls, nāca pie tā un uz to sacīja: Tā saka Tas Kungs: Apkopi savu namu, jo tu mirsi un nepaliksi vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Tad Hizkija savu vaigu pagrieza pret sienu un pielūdza To Kungu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Ak Kungs, piemini jel, ka es Tavā priekšā esmu staigājis patiesībā no visas sirds un darījis, kas Tev patīk. Un Hizkija raudāja gauži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Tad Tā Kunga vārds tā notika uz Jesaju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Ej un saki Hizkijam: Tā saka Tas Kungs, tava tēva Dāvida Dievs: Es tavu lūgšanu esmu klausījis, Es tavas asaras esmu redzējis. Redzi, Es tavām dienām pielikšu vēl piecpadsmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Un tevi un šo pilsētu es izpestīšu no Asīrijas ķēniņa rokas un pasargāšu šo pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Un šī būs tā zīme no Tā Kunga, ka Tas Kungs šo lietu darīs, ko Viņš runājis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Redzi, tai ēnai, kas ar sauli pa tiem kāpieniem pie Ahaza saules stundeņa uz priekšu gājusi, Es likšu iet atpakaļ desmit kāpienus. Un saule gāja atpakaļ desmit kāpienus pa tiem pašiem kāpieniem, kā tā bija gājusi uz priekšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Šis ir Hizkijas, Jūda ķēniņa, raksts, kad viņš bija slims bijis un no savas slimības palicis vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Es sacīju: Pašās savās labākās dienās man jānokāpj kapa vārtos, mani atliekamie gadi man top atņemti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Es sacīju: Es vairs neredzēšu To Kungu, To Kungu tai zemē, kur tie dzīvie, es vairs neieraudzīšu cilvēkus tai vietā, kur tie aizmigušie mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Mans nams top noplēsts un aizcelts, kā ganu būdiņa; es savu dzīvību satinu kā audējs (savu audekli). Viņš mani nogriež kā no riestavas. Pirms nakts metās, Tu man dari galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Es gaidīju līdz rītam, bet kā lauva Viņš salauž visus manus kaulus. Pirms nakts metās, Tu man darīsi galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Es kliedzu kā dzērve un bezdelīga, es vaidēju kā balodis, manas acis nogura uz augšu skatoties. Ak Kungs, man ir bail, izpestī mani!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Ko lai es saku? Kā viņš man solījis, tā viņš ir darījis; klusu es nu staigāšu visu savu mūžu manas dvēseles skumju dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Ak Kungs! No tā cilvēks atdzīvojās, un iekš tā visa stāv mana gara dzīvība, Tu mani atspirdzināsi un mani atkal darīsi dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Redzi, rūgtums palicis man par svētību, pats rūgtums, bet Tu manu dvēseli mīlīgi esi apkampis, ka tā nenāktu trūdēšanas bedrē, jo Tu visus manus grēkus esi metis aiz Sevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Jo elle Tevi neteic, un nāve Tevi neslavē; tie, kas grimst bedrē, necerē uz Tavu patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Tie dzīvie, tie dzīvie, tie Tevi slavē, kā es šodien; tēvs bērniem dara zināmu Tavu patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Tas Kungs ir man par pestīšanu, un mēs dziedāsim savas dziesmas, kamēr dzīvosim Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Un Jesaja sacīja: Lai ņem vienu vīģu rausi un liek plāksteri uz to trumu, tad viņš paliks vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Un Hizkija sacīja: Kāda ir tā zīme, ka es noiešu Tā Kunga namā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Tanī laikā Merodaks BalAdans, BalAdana dēls, Bābeles ķēniņš, sūtīja grāmatas un dāvanas pie Hizkijas, jo tas bija dzirdējis, ka viņš bija slims bijis un atkal palicis vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Un Hizkija priecājās par tiem un tiem rādīja savu mantas namu, to sudrabu un zeltu, tās dārgās zāles un to smalko eļļu un visu savu bruņu namu un visu, kas viņa mantās bija; nekas nebija visā viņa namā un visā viņa valstī, ko Hizkija tiem nebūtu rādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Tad pravietis Jesaja nāca pie ķēniņa Hizkijas un uz to sacīja: Ko šie vīri sacījuši un no kurienes tie pie tevis nākuši? Un Hizkija sacīja: Tie no tālas zemes pie manis nākuši, no Bābeles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Un viņš sacīja: Ko tie laba redzējuši tavā namā? Un Hizkija sacīja: Tie visu redzējuši, kas manā namā, nekā nav no manām mantām, ko es tiem nebūtu rādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Tad Jesaja sacīja uz Hizkiju: Klausies Tā Kunga Cebaot vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Redzi, dienas nāks, ka viss, kas ir tavā namā, un ko tavi tēvi līdz šai dienai sakrājuši, taps novests uz Bābeli, nekas netaps atlicināts, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Un no taviem dēliem, kas no tevis nāks, ko tu dzemdināsi, viņi ņems, ka tie būs par kambar junkuriem Bābeles ķēniņa pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Un Hizkija sacīja uz Jesaju: Tā Kunga vārds ir labs, ko tu runājis. Un viņš sacīja: Kad tik miers un drošība pastāv manā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Iepriecinājiet, iepriecinājiet Manus ļaudis, saka jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Runājiet laipnīgi ar Jeruzālemi un sauciet uz viņu, ka viņas karošana pagalam, ka viņas noziegums salīdzināts, ka viņa divkārtīgu tiesu dabūjusi no Tā Kunga rokas par visiem saviem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Saucēja balss ir tuksnesī: sataisiet Tam Kungam ceļu, dariet klajumā staigājamu ceļu mūsu Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Visas ielejas taps paaugstinātas un visi kalni taps pazemoti, un kas nelīdzens, taps līdzens, un kas celmains, taps klajums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Un Tā Kunga godība taps parādīta un visa miesa kopā to redzēs, jo Tā Kunga mute ir runājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Balss saka: Sauc! Un viņš saka: Ko man būs saukt? Visa miesa ir zāle, un viss viņas labums kā puķe laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Zāle nokalst, puķe savīst, kad Tā Kunga Gars pūš virsū; tiešām tie ļaudis ir zāle.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Zāle nokalst, puķe savīst, bet mūsu Dieva vārds pastāv mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Ciāna, labas vēsts sludinātāja, kāp uz augstu kalnu; Jeruzāleme, labas vēsts sludinātāja, pacel savu balsi ar spēku, pacel to, nebīsties! Saki Jūda pilsētām: redzi, jūsu Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Redzi, Tas Kungs Dievs nāk varens, un Viņa elkonis valdīs, redzi, Viņa alga ir pie Viņa, un Viņa atmaksāšana Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Viņš ganīs Savu ganāmo pulku kā gans, Viņš sapulcinās tos jērus Savās rokās un nesīs Savā klēpī un vedīs lēnītiņām tās grūtās avju mātes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kas izmērojis ūdeni ar sauju un apņēmis debesis ar sprīdi un satvēris zemes pīšļus ar sieciņu(mērtrauku) un nosvēris kalnus ar svaru un pakalnus svaru kausā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kas ir pamācījis Tā Kunga Garu un bijis Viņa padoma devējs, kas Viņam būtu mācījis gudrību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Pie kā Viņš padomu meklējis, ka tas Viņam saprašanu būtu devis un Viņam būtu mācījis tiesas ceļu, un Viņam būtu mācījis atzīšanu un Viņam zināmu darījis gudrības ceļu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Redzi, tautas ir kā pilīte pie spaiņa un kā puteklītis svaru kausā; redzi, Viņš salas paceļ kā putekļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Un ar Lībanu nepietiek priekš dedzināšanas, un ar viņa zvēriem priekš Viņa dedzināmiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Visas tautas ir kā nekas priekš Viņa, un pie Viņa top turētas par nieku un par neko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Kam jūs līdzināsiet to stipro Dievu? Jeb kādu līdzību jūs Viņam gribat taisīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Gan amatnieks lej bildi un sudrabkalis to apvelk ar zeltu un pielej sudraba ķēdes klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kas ir nabags, kam maz pie rokas upurēt, tas izmeklē koku, kas nesatrūd, viņš sev meklē gudru meistaru, taisīt bildi, kas nešķobās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Vai jūs nezināt? Vai jūs nedzirdat? Vai jums no iesākuma nav stāstīts? Vai jūs neesat izpratuši zemes radīšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Viņš sēž pār zemes virsu, un viņas iedzīvotāji ir kā siseņi. Viņš debesis izklāj kā smalku palagu un tās izpleš kā telti, kur dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Viņš lielus kungus dara par nieku un zemes soģus par neko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Tā kā tie nebūtu ne dēstīti, ne sēti, nedz viņu celms iesakņojies zemē; kad Viņš uz tiem pūtīs, tad tie nokaltīs, un viesulis tos aizvedīs kā pelus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Ar ko tad jūs Mani līdzināsiet, kam Es būtu līdzīgs? Saka tas Svētais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Paceļat savas acis uz augšu un skatāties, kas šīs lietas ir radījis un izved viņu pulku pēc skaita? Viņš tos visus sauc pie vārda pēc sava lielā spēka, un viņa stiprums ir tik varens, ka neviena netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Kāpēc tad tu saki, Jēkab, un tu Israēl, runā: mans ceļš ir priekš Tā Kunga paslēpts, un mana tiesa aiziet manam Dievam garām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Vai tu to nezini, vai tu to neesi dzirdējis? Mūžīgs Dievs ir Tas Kungs, kas zemes galus radījis; viņš nepiekūst un nenogurst, viņa prāts ir neizprotams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Viņš piekusušiem dod spēku un vairo stiprumu nespēcīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Jaunie piekusīs un nogurs un jaunekļi kritin kritīs:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Bet kas uz To Kungu paļaujas, dabūs jaunu spēku; tie skries uz augšu ar spārniem kā ērgļi, tie tecēs un nepiekusīs, tie staigās un nenogurs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Ciešat Man klusu, salas, un lai tautas ņemas jaunu spēku. Lai tie atnāk, lai nu runā, ejam kopā tiesāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kas no austruma puses to uzmodinājis, kam taisnība iet līdz, kur viņš staigā? Kas tautas viņa priekšā ir nodevis un darījis, ka viņš valda pār ķēniņiem, un tos devis viņa zobenam kā pīšļus un viņa stopam kā izkaisītas pelavas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Ka viņš tiem dzenās pakaļ un neaiztikts iet ceļu, kur viņa kāja nebija gājusi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kas to ir darījis un pastrādājis? Tas, kas cilvēku ciltis aicinājis no iesākuma. Es Tas Kungs esmu tas pirmais un pie tiem pēcnākamiem Es vēl esmu tas pats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Salas to redzēja un bijājās, zemes gali drebēja; tie atnāca tuvu un piegāja klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Viens palīdzēja otram un sacīja uz savu brāli: Esi stiprs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Un kalējs drošināja sudrabkali, kas ar veseri gludina to, kas sit uz laktu, un sacīja par to taisīto darbu: Tas būs labs; pēc viņš to stiprināja ar naglām, lai nekust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Bet tu, Israēl, Mans kalps, Jēkab, ko Es esmu izredzējis, Ābrahāma, Mana mīļā, dzimums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Tu, ko Es esmu sagrābis no pasaules galiem un esmu aicinājis no viņas malām, un uz ko Es sacījis: Tu esi Mans kalps, tevi Es esmu izredzējis un tevi neesmu atmetis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Nebīsties, jo Es esmu ar tevi, neatkāpies, jo Es esmu tavs Dievs; Es tevi stiprināju, Es tev arī palīdzu, Es tevi arī turu ar Savas taisnības labo roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Redzi, kaunā taps un par apsmieklu visi, kas pret tevi iedegās; iznīks un ies bojā tie ļaudis, kas ar tevi strīdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Tu tos meklēsi, bet tos neatradīsi; tie ļaudis, kas ar tevi strīdās, iznīks, un kas ar tevi karo, taps par nieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Jo Es Tas Kungs, tavs Dievs, satveru tavu labo roku, Es, kas uz tevi saku: Nebīsties, Es tev palīdzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Nebīsties, tārpiņ Jēkab, Israēla pulciņ; Es tev palīdzu, saka Tas Kungs, un tavs Pestītājs ir Tas Svētais iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Redzi, Es tevi daru par asiem jauniem kuļamiem ratiem, kam asas naglas, tu kalnus sakulsi un satrieksi un darīsi pakalnus par pelavām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Tu tos vētīsi, ka vējš tos aiznes un viesulis tos izkaisa. Bet tu priecāsies iekš Tā Kunga un lielīsies iekš Israēla svētā Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Tie bēdīgie un nabagi meklē ūdeni, un nav, viņu mēle kalst no tvīkšanas. Es Tas Kungs tos paklausīšu, Es, Israēla Dievs, tos neatstāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Es upes izlaidīšu no plikiem kalniem un avotus pašās ielejās; Es tuksnesi darīšu par ūdens ezeru un sausu zemi par ūdens avotiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Es tuksnesī stādīšu ciedrus, akācijas un mirtes un eļļas kokus; Es sausā klajumā stādīšu priedes, egles un buksu kokus kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Lai tie redz un atzīst, apdomā un visi kopā saprot, ka Tā Kunga roka to ir darījusi, un tas Svētais iekš Israēla to ir radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Nesiet šurp savas tiesas lietas, saka Tas Kungs, atnesiet, ar ko jūs savu taisnību varat pierādīt, saka Jēkaba ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Lai nāk un mums sludina tās lietas, kas vēl notiks. Stāstiet tās pirmās lietas, kas ir bijušas, ka mēs tās savā sirdī ievērojam un zinām viņu galu, vai sludinājiet mums tās nākamās lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Stāstiet tās zīmes, kas vēl būs, ka atzīstam, jūs esam dievus. Un dariet ko darīdami, vai labu, vai ļaunu, tad saskatīsimies un to kopā redzēsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Redzi, jūs neesat nekas, un jūsu darbs nav it nekas; negantība ir, pēc jums kārot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Es to pamodināju no ziemeļa puses, un viņš nāk no saules lēkšanas, kas piesauc Manu vārdu; viņš ies pār valdniekiem kā pār dubļiem, un kā podnieks min mālus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kas to stāstījis no iesākuma, ka mēs to zinātu, jeb pagājušos laikos, ka mēs sacītu: Taisnība? Bet neviena nav, kas to stāstījis, un neviena, kas ko labu sludinājis, un neviena, kas no jums būtu dzirdējis vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Es tas pirmais saku uz Ciānu: Redzi, te tas ir! - un uz Jeruzālemi: Es došu prieka vēstnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Un Es skatos, bet tur nav neviena, un viņu starpā tur nav padoma devēja, ka Es tos vaicātu un tie dotu atbildi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Redzi, tie visi nav nekas, viņu darbi nav it nekas, viņu lietās bildes ir tukšs vējš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Redzi, Tas ir Mans kalps, kam Es palīdzu, Manis izredzēts, pie kā Manai dvēselei labs prāts. Es savu Garu esmu licis uz Viņu, tautām iznest tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Viņš nebrēks nedz pacels Savu balsi, un Viņa balsi nedzirdēs pa ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Ielūzušu niedri Viņš nesalauzīs un kvēlošu dakti Viņš neizdzēsīs, Viņš tiesu nesīs ar patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Viņš nenogurs un nesalūzīs, kamēr iecels tiesu virs zemes, un jūras salas cerēs uz Viņa bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tā saka Dievs, Tas Kungs, kas debesis radījis un izplāta, kas zemi izklājis ar viņas augļiem, kas dvašu dod tiem ļaudīm, kas tur mīt, un garu tiem, kas virs tās staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '“Es Tas Kungs Tevi esmu aicinājis iekš taisnības un Tevi satveru pie Tavas rokas un Tevi pasargāju un Tevi ieceļu par derību ļaudīm, par gaišumu pagāniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Atvērt akliem acis un saistītos izvest no cietuma un no cietuma nama tos, kas sēž tumsībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Es esmu Tas Kungs, tas ir Mans vārds, un Savu godu Es citam nedošu, nedz Savu slavu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Redzi, kas papriekš sludināts, tas ir noticis, un jaunu Es stāstu; pirms tas izplaukst, Es jums to dodu dzirdēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Dziediet Tam Kungam jaunu dziesmu, Viņa slavu no zemes galiem; jūras braucēji ar viņas pilnumu, salas ar saviem iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Tuksnesis un viņa pilsētas lai paceļ balsi, un ciemi, kur Ķedars dzīvo; lai gavilē, kas dzīvo klints kalnos, lai tie sauc no kalnu galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Lai Tam Kungam dod godu un lai pasludina Viņa slavu salās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Tas Kungs iziet kā varonis, kā karavīrs Viņš iekarsis dusmās; Viņš sauc, Viņš kliedz, Saviem ienaidniekiem Viņš rādās varens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Sen laiku Es esmu klusu cietis, esmu klusu bijis un savaldījies. Bet nu Es brēkšu, kā sieva, kas dzemdē, elzdams un pūzdams ar varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Es postīšu kalnus un pakalnus un likšu sakalst visam viņu zaļumam un darīšu upes par salām, un izžāvēšu ezerus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Un Es vadīšu aklus pa ceļu, ko tie nav zinājuši, Es tiem likšu staigāt pa tekām, ko tie nav pazinuši, Es darīšu tumsību priekš viņu acīm par gaismu un nelīdzenumu par līdzenumu. Tā Es darīšu un tos neatstāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Bet atpakaļ būs griezties un palikt visiem kaunā, kas paļaujas uz elkiem un saka uz lietām bildēm: Jūs esat mūsu dievi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Klausāties, kurlie, un skatāties, aklie, un redziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kas ir tik akls kā Mans kalps un tik kurls kā Mans vēstnesis, ko Es sūtu? Kas ir tik akls kā Tas mīļais, un tik akls kā Tā Kunga kalps?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Tu esi daudz redzējis, bet neesi ievērojis, ausis atdarījis, bet viņš nedzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Tam Kungam bija labs prāts Savas taisnības dēļ, dot lielu un augstu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Bet tie ir postīti un aplaupīti ļaudis, visi saistīti alās un apslēpti cietuma namos, tie ir palikuši par laupījumu, un nav neviena, kas tos izglābj, par postījumu, un nav neviena, kas saka: Atdod atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kas jūsu starpā to liek vērā, kas uzmana un klausās, kas pēc būs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kas Jēkabu nodeva uz postu un Israēli laupītājiem? Vai ne Tas Kungs, pret ko esam grēkojuši? - Jo tie negribēja staigāt Viņa ceļos un neklausīja Viņa bauslībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Tāpēc Viņš pār tiem ir izgāzis Savas dusmības bardzību un kara briesmas, ka visapkārt dega; bet tie to neatzina, - un Viņš tos iededzināja, bet tie to neņēma pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Bet nu Tas Kungs, tavs Radītājs, Jēkab, un tavs darītājs, Israēl, saka tā: nebīsties, jo Es tevi esmu atpestījis, Es tevi esmu saucis pie tava vārda; tu esi Mans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Kad tu iesi caur ūdeņiem, tad Es būšu pie tevis, un caur upēm, tad tās tevi nepārplūdīs. Kad tu iesi caur uguni, tad tu nesadegsi, un liesma tevi neaizdedzinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Jo Es esmu Tas Kungs, tavs Dievs, tas Svētais iekš Israēla, tavs Pestītājs. Ēģipti Es dodu par tavu izpirkšanas maksu, Moru zemi un Sabu tavā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Tāpēc ka tu esi dārgs Manās acīs un cienīgs, un Es tevi mīļoju, Es esmu devis cilvēkus tavā vietā un tautas par tavu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Nebīsties, jo Es esmu pie tevis, Es atvedīšu tavu dzimumu no rīta puses un tevi sapulcināšu no vakara puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Es sacīšu uz ziemeli: Dod šurp! Un uz dienvidu: Neaiztur! Atved Manus dēlus no tālienes un Manas meitas no zemes galiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Ikkatru, kas pēc Mana Vārda nosaukts, un ko Es esmu radījis Sev par godu, ko esmu taisījis un darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Atved tos aklos ļaudis, kam tomēr acis, un tos kurlos, kam tomēr ausis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Lai visi pagāni top sapulcināti, un tautas lai sanāk kopā. Kurš no tiem to stāstīs? Lai tie mums stāsta tās pagājušās lietas, lai tie atved savus lieciniekus un taisnojās, ka šie dzird un saka: Tas ir tiesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Jūs esat Mani liecinieki, saka Tas Kungs, un Mans kalps, ko esmu izredzējis, lai jūs atzīstat un Man ticat un saprotat, ka Es tas esmu. Priekš Manis neviens dievs nav bijis un pēc Manis neviens nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Es, Es esmu Tas Kungs, un Pestītāja nav kā vien Es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Es esmu pasludinājis, Es esmu palīdzējis, Es esmu zināmu darījis, un sveša(dieva) nebija jūsu starpā. Un jūs esat Mani liecinieki, saka Tas Kungs, ka Es esmu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Arī no šīs dienas Es esmu tas pats, un neviena nav, kas var izglābt no Manas rokas; ko Es daru, kas to var novērst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Tā saka Tas Kungs, jūsu Pestītājs, tas Svētais iekš Israēla: jūsu dēļ Es uz Bābeli esmu sūtījis un visus Kaldejus aizdzinis, ka bija jābēg ar tām laivām, ar kurām bija līksmojušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Es esmu Tas Kungs, jūsu Svētais, Israēla Radītājs, jūsu ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Tā saka Tas Kungs, kas ceļu darījis jūrā un teku stipros ūdeņos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Kas izved ratus un zirgus, kara pulku un spēku, - kopā tie ir apgūlušies, tie necelsies atkal augšām, tie ir izdzēsti, kā dakts tie ir izdzisuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Nepieminiet tās vecās lietas un nedomājiet vairs uz to, kas pagājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Redzi, Es daru jaunas lietas; jau plaukst, jūs to atzīsiet; Es darīšu ceļu tuksnesī un upes tukšās vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Zvēri laukā Mani godās, šakāļi un strausi, jo Es ūdeni došu tuksnesī un upes tukšā vietā, dzirdināt Savus ļaudis, Savus izredzētos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Šos ļaudis Es Sev esmu radījis, tie teiks Manu slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Un tu Mani neesi piesaucis, Jēkab, nedz Manis pēc pūlējies, Israēl!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Tu Man neesi atnesis savu dedzināmo upuru avis, nedz Mani godājis ar saviem kaujamiem upuriem. Es tevi neesmu kalpinājis ar ēdamiem upuriem, nedz tevi apgrūtinājis ar vīraku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Tu Man neesi par naudu pircis smaržīgas kalmes un neesi Mani mielojis ar savu upuru taukiem. Bet tu Mani esi kalpinājis ar saviem grēkiem, tu Mani esi apgrūtinājis ar saviem noziegumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Es, Es tas esmu, kas izdeldu tavus pārkāpumus Sevis dēļ un nepieminu tavus grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Atgādini Mani, lai mēs kopā tiesājamies, teic jel, kā tu vari taisnoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Tavs pirmais tēvs ir grēkojis un tavi aizstāvētāji pret Mani noziegušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Tāpēc Es esmu licis negodā svētuma virsniekus un Jēkabu nodevis lāstam un Israēli kaunam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Bet nu klausies, mans kalps Jēkab, un Israēl, ko esmu izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Tā saka Tas Kungs, kas tevi radījis un taisījis no mātes miesām, kas tev palīdz: Nebīsties, Mans kalps Jēkab, un tu Ješurun, ko Es esmu izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Jo Es liešu ūdeni uz iztvīkušiem un straumes uz izkaltušiem. Es izliešu Savu Garu uz tavu dzimumu un Savu svētību uz taviem bērnu bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Ka tie zaļos kā zāle, kā vītoli pie ūdens strautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Šis sacīs: Es piederu Tam Kungam! Un cits sauks Jēkaba vārdu, un trešais rakstīs ar savu roku: Es padodos Tam Kungam! Un godās Israēla vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Tā saka Tas Kungs, Israēla ķēniņš un viņa Pestītājs, Tas Kungs Cebaot: Es esmu tas pirmais un Es esmu tas pēdīgais, un cita Dieva nav, kā Es vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Un kas tā var sludināt kā Es, lai saka un lai liek Man priekšā, kamēr Es esmu licis pirmos ļaudis pasaulē. Lai tie jel stāsta tās nākamās lietas un kas notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Neizbaiļojaties un nebīstaties, - vai Es to sen jau tev neesmu darījis zināmu un stāstījis? Un jūs esat Mani liecinieki, vai ir cits Dievs nekā Es vien? Tiešām, nav cita akmens kalna, Es nezinu neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Elku taisītāji visi nav nekas, un viņu mīlulīši neder nekam, un paši ir viņu liecinieki, ka tie neredz un nesaprot; tādēļ tie paliks kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kas ir dievu taisījis un elku lējis, kas nekam neder?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Redzi, visi viņu biedri paliks kaunā, jo tie taisītāji ir cilvēki. Tad lai tie visi gan sapulcinājas un ceļas, tomēr tie izbīsies un kopā paliks kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kalējs taisa cirvi un strādā svelmē un to pataisa ar veseriem un to izstrādā ar sava elkoņa stiprumu; viņš cieš arī badu, ka paliek bez spēka, viņš nedzer ūdeni, ka paliek gurdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Kas koka darbu strādā, izvelk mēra auklu, nozīmē to ar sarkanu krītu, aptēš to ar cirvjiem un apraksta to ar cirkuli un dara to pēc vīra ģīmja, kā skaistu cilvēku, lai stāv namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Viņš sev cērt ciedru kokus, ņem kļavu vai ozolu, un izlasās kādu starp meža kokiem; osi viņš dēstījis un lietus to ir uzaudzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Tie ir cilvēkam dedzināt, un viņš ņem no tiem un sildās, un iededzina un cep maizi un arī iztaisa dievekli un to pielūdz, dara elku un metās priekš tā ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Vienu pusi viņš sadedzina ugunī, no tās puses viņš ēd gaļu, viņš cep cepešus un paēd, pats arī sildās un saka: nu labi, man paliek silti, es samanu uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Un to, kas atliek, viņš taisa par dievu, sev par elku; priekš tā viņš metās ceļos un klanās un to pielūdz un saka: izpestī mani, jo tu esi mans dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Tie neatzīst un nesaprot, jo viņu acis aizlipušas, ka tie neredz, un viņu sirdis, ka tie nesaprot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Un neviens to neņem pie sirds, un nav ne atzīšanas, ne saprašanas, ka sacītu: vienu pusi es esmu sadedzinājis ar uguni un uz tām oglēm arī maizi cepis, es gaļu pie tā esmu cepis un ēdis, vai nu man to, kas atliek bija darīt par negantību, vai man priekš koka gabala bija ceļos mesties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Kam prāts nesās uz pelniem, to apmānītā sirds maldina, un viņš neizglābj savu dvēseli un nesaka: vai nav viltība manā labā rokā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Piemini to, Jēkab un Israēl, jo tu esi Mans kalps; Es tevi esmu radījis, tu esi Mans kalps, Israēl, neaizmirsti Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Es izdeldu tavus pārkāpumus kā miglu un tavus grēkus ka mākoni. Atgriezies pie Manis, jo Es tevi esmu atpestījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Gavilējat, debesis, jo Tas Kungs to ir darījis, sauciet priecīgi, zemes dziļumi, ceļat troksni, kalni, ar prieku dziesmām, meži un visi koki iekš tā; jo Tas Kungs Jēkabu atpestījis un Israēli pagodinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Tā saka Tas Kungs, tavs Pestītājs, kas tevi taisījis no mātes miesām. Es esmu Tas Kungs, kas visu dara, kas debesi izpletis, Es viens pats, un kas zemi izklājis, bez cita neviena,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Kas iznīcina zīlnieku zīmes un zvaigžņu cienītājus dara trakus, kas gudriem liek atpakaļ griezties un viņu gudrību dara par ģeķību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Kas apstiprina Sava kalpa vārdu un liek izdoties Savu vēstnešu padomam; kas uz Jeruzālemi saka, lai tur atkal ļaudis dzīvo, un uz Jūda pilsētām: Jūs tapsiet atkal uztaisītas, un Es uztaisīšu viņas postītās vietas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Kas uz dziļumu saka: Izsīksti! Un tavus strautus Es darīšu sausus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Kas uz Kiru saka: Mans gans! Un viņš izdarīs visu Manu prātu, sacīdams uz Jeruzālemi: topi celta! Un Dieva nams lai top taisīts!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Tā saka Tas Kungs uz savu svaidīto, Kiru: Es to satveru pie viņa labās rokas, ka Es tautas viņa priekšā metu pie zemes, un atraisu ķēniņu jostas, un atdaru priekš viņa durvis, un vārti nepaliek aizslēgti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Es iešu tavā priekšā un darīšu līdzenus nelīdzenos ceļus, es salauzīšu vara durvis un sadauzīšu dzelzs aizšaujamos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Un Es tev došu mantas, kas tumsā, un apslēpto bagātību, lai tu atzīsti, ka Es esmu Tas Kungs, kas tevi sauc pie vārda, tas Israēla Dievs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Jēkaba, Mana kalpa dēļ, un Israēla, Mana izredzētā, dēļ. Un Es tevi saucu pie tava vārda, Es tevi mīlīgi uzrunāju, kad tu Mani vēl nepazini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Es esmu Tas Kungs, un cits neviens, dieva nav, kā Es vien. Es tevi esmu apjozis, jebšu tu Mani nepazini,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Lai zināms top no saules uzlēkšanas un noiešanas, ka neviena nav bez Manis: Es esmu Tas Kungs, un cits neviens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Es ceļu gaismu un radu tumsu, Es daru mieru un radu ļaunumu. Es Tas Kungs daru to visu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Piliet, debesis, no augšienes, un padebeši lai izlej taisnību; lai zeme atveras un izdod pestīšanu, un taisnība lai līdz izaug: Es Tas Kungs to esmu radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Vai tam, kas pretī runā savam radītājam, poda gabals starp poda gabaliem no zemes! Vai gan māls saka uz savu taisītāju: ko tu dari? Jeb vai tavs darbs sacīs: viņam nav rokas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ak vai, tam, kas saka uz tēvu: kam tu dzemdini? Un uz māti: kam tu dzemdē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Tā saka Tas Kungs, tas Svētais iekš Israēla un viņa Radītājs: Vaicājiet no Manis nākamas lietas; Manus bērnus un Manas rokas darbu pavēliet Man.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Es esmu darījis zemi un radījis cilvēku zemes virsū. Es tas esmu, Manas rokas izplātījušas debesis, un Es pavēlu visam viņu spēkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Es viņu esmu uzmodinājis taisnībā un darīšu visus viņa ceļus līdzenus. Viņš uzcels Manu pilsētu un atlaidīs Manus cietumniekus, ne par maksu un ne par dāvanām, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Tā saka Tas Kungs: ēģiptiešu padoms, Moru ļaužu manta un Zabieši, vīri garu augumu, nāks pie tevis un tev piederēs, un staigās tev pakaļ; saistīti tie atnāks un klanīsies priekš tevis, tie tevi pielūgs: Patiesi, Dievs ir ar tevi, un nav cita Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Patiesi, Tu esi apslēpts Dievs, Israēla Dievs, Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Tie taps kaunā un par apsmieklu visi; tie aizies kopā ar kaunu, kas taisa elka dievus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Bet Israēls top atpestīts caur To Kungu ar mūžīgu pestīšanu; jūs netapsiet kaunā nedz par apsmieklu mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Jo tā saka Tas Kungs, kas debesis radījis, tas Dievs, kas zemi iztaisījis un darījis; Viņš to ir cēlis, Viņš to nav radījis, ka būtu tukša, bet Viņš to taisījis, lai tur dzīvo: Es esmu Tas Kungs, un cits neviens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Es neesmu slepeni runājis kādā tumšā zemes vietā. Es uz Jēkaba dzimumu neesmu sacījis: meklējiet Mani velti! Es esmu Tas Kungs, kas runā taisnību un sludina patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Sapulcējaties un nāciet, tuvojaties visi līdz, kas izglābti no pagāniem! Tie nezin nenieka, kas apkārt nēsā savus izgrieztos koka tēlus, un pielūdz dievu, kas nevar izpestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Sludiniet un nāciet klāt, sarunājaties kopā. Kas to ir darījis zināmu no veciem laikiem, kas to sen stāstījis? Vai ne Es, Tas Kungs? Un cita Dieva nav, kā Es vien, taisna Dieva un Pestītāja neviena nav, kā Es vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Griežaties pie Manis, tad jūs tapsiet pestīti, visas pasaules gali, jo Es esmu Dievs, un cits neviens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Es esmu zvērējis pie Sevis paša, taisnība no Manas mutes izgājusi, vārds, kas nav pārgrozāms: tiešām, visi ceļi Manā priekšā locīsies, visas mēles Man zvērēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Par Mani sacīs: tiešām, iekš Tā Kunga ir taisnības darbi un stiprums. Pie Viņa ies. Bet kas Viņam turas pretī, paliks kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Iekš Tā Kunga taps taisnoti un lielīsies visi, kas no Israēla dzimuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bels grūst, Nebus krīt, viņu tēlus uzliek kustoņiem un lopiem; ko jūs nesat, ir nesama nasta piekusušiem (lopiem).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Tie visi kopā klūp un krīt, tie nevar izglābt to nastu, bet iet paši cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Klausies uz Mani, Jēkaba nams, un visi atlikušie no Israēla nama, ko esmu nesis no mātes miesām un uzņēmis no mātes klēpja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Un līdz pašam vecumam Es būšu tas pats, kamēr jūs topat sirmi, Es nesīšu. Es to esmu darījis, un Es jūs uzņemšu, un Es nesīšu un izglābšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Kam jūs Mani līdzināsiet un turēsiet līdzīgu? Ar ko Mani salīdzināsiet, ka būtu vienādi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Tie izber zeltu no maka un sver sudrabu ar svaru, tie sader sudraba kalēju, un tas to iztaisa par dievekli, tie metās ceļos un to pielūdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Tie to ceļ uz pleciem, to nes, un to noliek savā vietā. Tur viņš stāv un neatstājās no savas vietas; viņu arī piesauc, bet tas neatbild un neviena neizglābj no bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Pieminiet to un turaties stipri, jūs pārkāpēji, ņemiet to pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Pieminiet pagājušās lietas no vecu veciem laikiem; jo Es esmu Dievs, un cits neviens, Es esmu Dievs, un nav neviena kā Es,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Kas no iesākuma galu dara zināmu, un no senlaikiem to, kas vēl nav noticis, kas saka: Mans padoms pastāvēs, un Es darīšu visu, kas Man patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Es aicināju ērgli no rīta puses un vīru pēc Sava padoma no tālas zemes. Es to esmu runājis un tam likšu nākt, Es to esmu apņēmies, Es to arī izdarīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Klausāties uz Mani, cietsirdīgie, kas esat tālu no taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Es Savu taisnību tuvu esmu atnesis, tā nebūs tālu, un Mana pestīšana nekavēsies, jo Es došu pestīšanu Ciānā, iekš Israēla Savu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Kāp zemē un sēdi pīšļos, jaunava, Bābeles meita; sēdies zemē, Kaldeju meita, goda krēsla nav! Jo tevi vairs nesauks par smalku un kāru(mīlīgu).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Ņem dzirnas un mal miltus, atklāj savu apsegu, atsedz kājas, atklāj ceļus, brien caur upēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Tavs kailums taps atsegts, un tavs kaunums būs redzams, Es atriebšos un nežēlošu neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Mūsu Pestītāja vārds ir Kungs Cebaot, tas Svētais iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sēdi klusu un lien tumsā, Kaldeju meita, jo tevi vairs nesauks par valstu valdnieci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Es biju dusmīgs par Saviem ļaudīm, Es liku negodā Savu mantības tiesu, un tos nodevu tavā rokā. Bet tu viņiem neparādīji žēlastības, tiem veciem tu uzliki savu ļoti grūto jūgu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Un sacīji: Es būšu mūžīgi valdniece; tā ka tu šīs lietas neesi pie sirds ņēmusi, tu neesi apdomājusi galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Tad nu, klausies šo, tu vēlīgā, kas bez bēdām sēdi un saki savā sirdī: es un cita neviena! Es nepalikšu par atraitni un nebūšu bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Tomēr šīs divas lietas piepeši nāks pār tevi vienā dienā: bērnu nebūs, un atraitne būsi, ar pilnu mēru tas nāks pār tevi, ar visu tavu lielo buršanu un ar visu tavu varen lielo vārdošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Jo tu esi paļāvusies uz savu blēdību un sacījusi: neviens mani neredz. Tava gudrība un tava zināšana tevi pievīlusi, un tu esi sacījusi savā sirdī: es un cita neviena!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Tādēļ pār tevi nāks ļaunums ko tu nemācēsi atburt, un uz tevi kritīs posts, ko tu ar upuriem nevarēsi novērst, jo piepeši pār tevi nāks nelaime, ko tu neparedzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Paliec jel pie savas vārdošanas un pie savas lielās buršanas, ar ko tu esi darbojusies no savas jaunības, varbūt varēsi izpestīties, varbūt ko izbiedēt!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tu esi piekususi no savu padomu pulka. Lai jel nu ceļas un lai tevi glābj tie debess dalītāji un zvaigžņu skaitītāji, kas pēc mēnešiem ziņo to, kas pār tevi nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Redzi, tie ir kā rugāji, uguns tos aprīs, tie savas dvēseles nevarēs izglābt no varenas liesmas. Tās nebūs ogles, kur sildīties, nedz uguns, pie ka atsēsties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tādi tev būs tie, ar ko esi darbojusies, tavi biedri no tavas jaunības; ikviens maldīsies pa savu ceļu, neviens tevi neizpestīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Klausāties šo, Jēkaba nams, ko sauc pēc Israēla vārda un kas iztecējuši no Jūda avota, kas zvērējāt pie Tā Kunga vārda un pieminat Israēla Dievu, bet nevis patiesībā nedz taisnībā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Jo tie nosaucās pēc tās svētās pilsētas un paļaujas uz Israēla Dievu; Kungs Cebaot ir viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, '“Tās priekšējās lietas Es sen jau esmu pasludinājis, un no Manas mutes tās nākušas, un Es tās esmu darījis zināmas. Piepeši tās esmu izdarījis, un tās notikušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Es zināju tevi esam stūrgalvīgu, un ka tavs pakausis ir dzelzs gabals un tava piere varš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Tādēļ tev to sen esmu pasludinājis, pirms tas notika, Es tev to esmu devis dzirdēt, ka tu nesacītu: mans elkadievs to darījis un mans tēls un mana bilde to pavēlējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Tu to esi dzirdējis, redzi nu visu to! Vai tad jums to nebūs pasludināt? No šā brīža Es tev daru zināmas jaunas lietas un apslēptas lietas, ko tu nezini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Tagad tās radītas un nevis sen, un ne dienu iepriekš tu no tām neesi dzirdējis, lai nevari sacīt: redzi, es to esmu zinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'To tu neesi ne dzirdējis ne zinājis nedz tava auss senāk bijusi atdarīta. Jo Es zināju, ka tu esi pavisam neuzticams, un ka no mātes miesām tevi sauc (par) pārkāpēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Sava vārda dēļ Es Savu dusmību pavilcināju, un Savas slavas dēļ Es savaldos tev par labu, ka tevi neizdeldu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Redzi, Es tevi esmu šķīstījis, tomēr nekā sudrabu, Es tevi esmu pārbaudījis bēdu ceplī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Manis dēļ, Manis dēļ Es to daru, lai(Mans vārds) netop zaimots. Un Savu godu Es nedošu citam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Klausies uz Mani, Jēkab, un Israēl, Manis aicināts, Es tas esmu, Es tas pirmais un Es tas pēdīgais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Tiešām, Mana roka zemi ir likusi, un Mana labā roka izplātījusi debesis; kad Es uz tām saucu, tad tās visnotaļ stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Sapulcējaties visi un klausāties, kurš no šiem šīs lietas pasludinājis? Tas, ko Tas Kungs mīl, tas izdarīs Viņa prātu pret Bābeli, un Viņa elkonis būs pret Kaldejiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Es, Es to esmu runājis, un Es viņu esmu aicinājis, Es viņam likšu nākt, un viņa ceļš labi izdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Nākat klāt pie Manis, klausāties šo: no iesākuma Es nekā neesmu runājis slepenībā, (bet) no tā laika, kad tas sācies, es še esmu.” Un nu Tas Kungs Dievs mani sūtījis un Viņa Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Tā saka Tas Kungs, tavs Pestītājs, tas Svētais iekš Israēla: Es Tas Kungs, tavs Dievs, Es tevi mācu, kas piederas, Es tevi vadu pa to ceļu, kur jāiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Kaut tu Manus baušļus liktu vērā, tad tavs miers būtu kā upe, un tava taisnība kā jūras viļņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Un tavs dzimums būtu kā smiltis, un tavas miesas augļi kā viņu zvirgzdes, un viņa vārds neizzustu nedz taptu izdeldēts Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Ejat ārā no Bābeles, bēdziet no Kaldejiem, ar prieka balsīm sludinājiet, dariet to zināmu, izpaudiet to līdz zemes galiem, sakāt: Tas Kungs Savu kalpu Jēkabu atpestījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Un tie neizslāpa, kad Viņš tos vadīja pa tuksnesi, Viņš tiem ūdeni iztecināja no klints un šķēla klinti, ka ūdens iztecēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Bet bezdievīgiem nav miera, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Klausāties uz mani, salas, un ņemiet vērā, tauta no tālienes: Tas Kungs mani aicinājis no mātes miesām, Viņš manu vārdu minējis, kad es vēl biju mātes miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Un Viņš manu muti darījis kā asu zobenu, Savas rokas ēnā Viņš mani apslēpis. Viņš mani iecēlis par spožu bultu un glabājis Savā bultu makā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Un Viņš uz mani sacījis: tu esi Mans kalps, Israēl, pie kā Es pagodināšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Bet es sacīju: es esmu velti strādājis, es savu spēku esmu tērējis par neko un velti; tomēr mana tiesa ir pie Tā Kunga un mana alga pie mana Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Un nu saka Tas Kungs, kas no mātes miesām mani darījis Sev par kalpu, Jēkabu atkal atvest pie Viņa un Israēli pie Viņa sapulcināt - un es esmu pagodināts Tā Kunga acīs, un mans Dievs ir mans stiprums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Viņš saka: tas ir maz, ka tu esi Mans kalps, uztaisīt Jēkaba ciltis un atkal atvest Israēla izsargātos; bet Es tevi arī pagāniem esmu iecēlis par gaišumu, ka tu esi Mana pestīšana līdz pasaules galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Tā saka Tas Kungs, Israēla Pestītājs, viņa Svētais, uz to, kam dvēsele top nicināta, ko ļaudis tur par negantību, kas varas darītājiem par kalpu. Ķēniņi redzēs un pacelsies, lielkungi metīsies zemē Tā Kunga dēļ, kas ir uzticīgs, Israēla Svētā dēļ, kas tevi izredzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Tā saka Tas Kungs: Es tevi esmu paklausījis labā pieņemīgā laikā, un tev esmu palīdzējis pestīšanas dienā. Un Es tevi pasargāšu un tevi iecelšu tautai par derību, zemi uztaisīt, ka ikviens iemanto savu postīto daļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Un sacīt uz tiem, kas cietumā: ejat ārā! Uz tiem, kas tumsā: nāciet gaismā! Tie ganīsies ceļmalā un ganība tiem būs visās augstās vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Tie ne izsalks, nedz izslāps, tos arī nespiedīs ne karstums, ne saule; jo viņu apžēlotājs tos vadīs un tos vedīs lēniņām pie ūdens avotiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Un Es darīšu visus Savus kalnus par ceļu, un Mani lielceļi taps paaugstināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Redzi, šie nāks no tālienes, un redzi, šie no ziemeļa puses un no jūras, un šie no Sinimas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Gavilējat, debesis, un priecājies, zeme, sākat gavilēt, kalni, jo Tas Kungs iepriecina Savus ļaudis un apžēlojās par Saviem bēdīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Bet Ciāna saka: Tas Kungs mani atstājis, un Tas Kungs mani aizmirsis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Vai sieva var aizmirst savu zīdāmo bērnu, neapžēlodamās par savu miesīgo dēlu? Un jebšu viņa to aizmirstu, tomēr Es tevi neaizmirsīšu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Redzi, Savās rokās Es tevi esmu rakstījis, tavi mūri ir vienmēr Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Tavi bērni steigsies šurp, bet tavi postītāji un izdeldētāji ies projām no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Pacel savas acis visapkārt, un redzi: visi šie sapulcinājās un nāk pie tevis. Tik tiešām kā Es dzīvoju, saka Tas Kungs, tu tapsi ar visiem šiem apģērbta tā kā ar glītumu un apjozīsies ar tiem kā brūte,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Jo tava aplaupītā, iztukšotā, nopostītā zeme tev nu taps visai šaura tik daudz iedzīvotāju dēļ, un tavi aprijēji atkāpsies tālu no tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Tad tie bērni, kas bija zuduši, sacīs priekš tavām ausīm: tā vieta priekš manis ir šaura; ej tālāk, ka es varu dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Bet tu sacīsi savā sirdī: kas man šos dzemdinājis, jo es biju bez bērniem, vientule, es biju cietumā vesta un atstumta; kas tad šos man ir uzaudzinājis? Redzi, es biju atstāta viena, kur tad šie bija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Tā saka Tas Kungs Dievs: redzi, Es pacelšu Savu roku uz pagāniem un izcelšu tautām Savu karogu, tad tie tavus dēlus atnesīs klēpī, un tavas meitas nesīs uz kamiešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Un ķēniņi būs tavi audzinātāji un viņu ķēniņienes tavas zīdītājas. Tie metīsies uz vaigu zemē priekš tevis un laizīs tavu kāju pīšļus. Tad tu manīsi, ka Es esmu Tas Kungs, pie kā netop kaunā, kas uz Mani cerē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Vai gan varenam var atņemt laupījumu? Jeb vai taisni var izsprukt no viņa cietuma?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Bet nu Tas Kungs tā saka: tiešām, cietumnieki varenajam taps atņemti, un laupījums izspruks varas darītājam; jo taviem pretiniekiem Es stāšos pretī, un tavus bērnus Es izpestīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Un tavus spaidītājus Es ēdināšu ar viņu pašu miesām, un tie piedzersies no savām pašu asinīm kā no salda vīna, un visa miesa manīs, ka Es esmu Tas Kungs, tavs Pestītājs un tavs izglābējs, tas Varenais iekš Jēkaba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Tā saka Tas Kungs: Kur ir jūsu mātes šķiršanās grāmata, ar ko Es viņu būtu atstādinājis, un kur ir Mans parādu dzinējs, kam Es jūs būtu pārdevis? Redzi, jūs savu noziegumu dēļ esat pārdoti, un jūsu pārkāpumu dēļ jūsu māte ir atstādināta');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Kāpēc Es nācu, un neviena tur nebija? Kāpēc Es saucu, un neviens neatbildēja? Vai tad Mana roka īsin paīsināta, ka tā nevar atpestīt? Jeb vai Man spēka nav izglābt? Redzi, ar Saviem draudiem Es jūru daru sausu, pārvēršu straumes par tuksnesi, ka viņu zivis smird, jo ūdens nav, un tās mirst aiz slāpēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Es apģērbju debesis ar krēslību un daru maisu viņām par apsegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Tas Kungs Dievs man ir devis mācītu mēli, ka es zinu ar vārdiem stiprināt nogurušus. Viņš uzmodina ik rītu, Viņš uzmodina manu ausi, klausīties kā tie, kas mācās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Tas Kungs Dievs man ausi ir atdarījis, un es neesmu bijis stūrgalvīgs un neesmu atkāpies atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Es savu muguru devu tiem, kas mani sita, un savu vaigu tiem, kas mani plūca; es neapslēpu savu vaigu no nievāšanas un spļaudalām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Jo Tas Kungs Dievs man palīdz, tādēļ es nepaliku kaunā. Tāpēc es savu vaigu esmu darījis kā kramu, jo es zinu, ka nepalikšu kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Viņš ir tuvu, kas mani taisno, kas gan ar mani tiesāsies? Saiesim kopā! Kas ir mans pretinieks tiesā? Lai nāk klāt pie manis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Redzi, Tas Kungs Dievs man palīdz; kas mani pazudinās? Redzi, tie visi sadils kā drēbe, kodes tos ēdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kurš jūsu starpā bīstas To Kungu, un klausa Viņa kalpa balsi? Kas tumsībā staigā, kur gaismas nav, tas lai paļaujas uz Tā Kunga vārdu un cerē uz savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Redzi, jūs visi, kas uguni sakurat un sataisāt ugunīgas bultas, ejat paši savās uguns liesmās un tais bultās, ko esat iededzinājuši! Tas jums notiek no Manas rokas, sāpēs jums jāguļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Klausāties uz Mani, kas taisnībai dzenaties pakaļ, kas To Kungu meklējat. Uzlūkojiet to akmens kalnu, no kā esat cirsti, un to akas bedri, kur esat izrakti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Uzlūkojiet Ābrahāmu, savu tēvu, un Sāru, kas jūs dzemdējusi. To Es aicināju, kad viņš vēl bija viens pats, un Es to svētīju un vairoju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Jo Tas Kungs iepriecinās Ciānu, Viņš iepriecinās visas viņas tukšās vietas un darīs viņas tuksnesi kā Edeni un viņas lauku kā Tā Kunga dārzu; prieku un līksmību tur atradīs, pateikšanu un slavas dziesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Ņem Mani vērā, Mana tauta, atgriežat ausis pie Manis, Mani ļaudis, jo no Manis iziet bauslība, un Savu tiesu Es iecelšu tautām par gaišumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Mana taisnība ir tuvu klāt, Mana pestīšana parādās, un Mans elkonis sodīs tautas. Uz Mani salas gaida un cerē uz Manu elkoni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Paceliet savas acis uz debesīm un skatāties uz zemi apakšā; jo debesis iznīks kā dūmi, un zeme nodils kā drēbe, un viņas iedzīvotāji nomirs kā mušas. Bet Mana pestīšana pastāvēs mūžīgi, Mana taisnība netiks apgāzta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Klausāties uz Mani, kas taisnību pazīstat, ļaudis, kam Mana bauslība ir sirdī. Nebīstaties par cilvēku nievāšanu un neiztrūcinājāties no viņu zaimošanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Jo tārpi tos ēdīs kā drēbi, un kodes tos sakapās kā vilnu, bet Mana taisnība pastāvēs mūžīgi un Mana pestīšana uz cilšu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Uzmosties, uzmosties, apvelc stiprumu, Tā Kunga elkonis, uzmosties kā sendienās, vecu vecos laikos! Vai Tu neesi tas, kas Rahabu (Ēģipti) pāršķēlis un to pūķi nodūris?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Vai Tu neesi, kas jūru darījis sausu, tos lielos ūdeņu dziļumus darījis par ceļu, ka tie atpestītie gāja cauri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Un Tā Kunga atpirktie griezīsies atpakaļ un nāks uz Ciānu ar gavilēšanu, un mūžīga līksmība būs pār viņu galvām; prieks un līksmība tos apkamps, skumjas un bēdas bēgs projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Es, Es esmu jūsu iepriecinātājs: kas tu esi, ka bīsties no cilvēkiem, kam jāmirst, un no cilvēku bērniem, kas iznīkst kā zāle,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Un aizmirsti To Kungu, savu Radītāju, kas debesis izpletis un zemi dibinājis, un bīsties bez mitēšanās cauru dienu no spaidītāja bardzības, kad tas taisās maitāt? Bet kur nu ir tā spaidītāja bardzība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Steigšus saslēgtais tiek svabads un nenomirs bedrē, un maizes viņam netrūks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Jo Es esmu Tas Kungs, tavs Dievs, kas kustina jūru, ka viņas viļņi kauc: Kungs Cebaot ir Viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Un Es lieku Savus vārdus tavā mutē un tevi apklāju ar Savas rokas ēnu, ka Es dēstu debesis un stādu zemi un saku uz Ciānu: tu esi Mana tauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Uzmosties, uzmosties, celies Jeruzāleme, kas no Tā Kunga rokas esi dzērusi Viņa bardzības biķeri; reibuma biķeri tu esi izdzērusi un izsūkusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'No visiem bērniem, ko tā ir dzemdējusi, neviena nebija, kas viņu būtu vadījis(drošībā un miera vietā), un no visiem bērniem, ko tā uzaudzinājusi, neviena, kas viņu pie rokas būtu ņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Šīs divējas lietas tev ir notikušas, kas tad tevi žēlos? Posts un nelaime un bads un zobens, kas tad tevi var iepriecināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tavi bērni pamiruši, tie guļ uz visu ielu stūriem kā stirna tīklā, tie bija pilni Tā Kunga bardzības, tava Dieva draudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Tāpēc klausies jel šo, tu apbēdinātā un apreibusī, bet ne no vīna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Tā saka tavs Kungs, Tas Kungs, un tavs Dievs, kas Saviem ļaudīm tiesu nesīs: redzi, Es ņemu no tavas rokas to reibuma biķeri, Savas bardzības biķeri, tev vairs to nebūs dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Bet Es to došu rokā taviem spaidītājiem, kas uz tavu dvēseli saka: lokies, ka mēs ejam pāri, un noliec savu muguru pār zemi un par ielu tiem, kas staigā pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Uzmosties, uzmosties! Apvelc savu stiprumu, Ciāna! Apvelc savas goda drēbes, svētā pilsēta Jeruzāleme! Jo neviens, kas neapgraizīts un nešķīsts, pie tevis vairs nenāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Nokrati pīšļus, celies, apsēdies, Jeruzāleme! Atraisi sava kakla saites, apcietinātā Ciānas meita!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Jo tā saka Tas Kungs: jūs esat par velti pārdoti, jūs arī bez naudas tapsiet atpirkti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Jo tā saka Tas Kungs Dievs: vecos laikos Mani ļaudis nogāja uz Ēģipti, tur piemist, un Asurs tos bez vainas apbēdinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Un nu, kas nu Man še? Saka Tas Kungs. Jo Mani ļaudis ir par velti atņemti, viņu pārvarētāji gavilē, saka Tas Kungs, un Mans Vārds top zaimots bez mitēšanās cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Tādēļ Mani ļaudis Manu Vārdu pazīs tai dienā, ka Es tas esmu, kas saka: še Es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Cik jaukas ir uz kalniem prieka vēstnešu kājas, kas sludina mieru, sola labumu, sludina pestīšanu un uz Ciānu saka: tavs Dievs ir ķēniņš!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Klau, tavu sargu balss! Tie paceļ balsi un gavilē visi, jo tie acīm redz, ka Tas Kungs Ciānu atkal ved atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Sauciet, gavilējiet, visas Jeruzālemes mūru drupas, jo Tas Kungs Savus ļaudis ir iepriecinājis, Viņš Jeruzālemi atpestījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Tas Kungs ir atsedzis Savu svēto elkoni priekš visu pagānu acīm, un visas zemes gali redzēs mūsu Dieva pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Ārā, ārā, izejiet no turienes ārā, neaizskariet nešķīstu, ejat ārā no viņu vidus, šķīstaties, kas Tā Kunga rīkus nesat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Neizejat steigšus un neejat projām bēgšus, jo Tas Kungs ies jūsu priekšā, un jums pakaļ ies Israēla Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Redzi, Mans kalps darīs prātīgi, viņš būs paaugstināts un augsti celts un ļoti augsti turēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Kā daudz tevis dēļ ir iztrūkušies, - tik nejauks bija viņa vaigs un ne pēc cilvēka, un viņa ģīmis ne pēc cilvēka bērniem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Tā viņš iztrūcinās daudz tautas, un ķēniņi saturēs savu muti viņa priekšā. Jo kam par to nebija sludināts, tie to redzēs, un kas to nebija dzirdējuši, tie to samanīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kas tic mūsu sludināšanai? Un kam Tā Kunga elkonis ir parādīts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Jo Tas uzaug Viņa priekšā tā kā zariņš un kā sakne no sakaltušas zemes. Viņam nebija nekāda jaukuma nedz skaistuma, un mēs viņu uzlūkojām, un tur nebija nekāda krāšņuma, kas mums būtu paticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Viņš bija nievāts un ļaužu atstāts, pulgots, pilns sāpju un vājības. Un Viņš bija pulgots, ka vaigu priekš Viņa apslēpa, un mēs Viņu necienījām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Tiešām, Viņš nesa mūsu sērgas un uzkrāvās mūsu sāpes; bet mēs Viņu turējām par sodītu, Dieva sasistu un nospaidītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Bet Viņš mūsu pārkāpumu dēļ ir ievainots un mūsu grēku dēļ sagrauzts. Tā sodība guļ uz Viņa, caur ko mums miers nāk, un caur Viņa brūcēm mēs esam dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Mēs visi maldījāmies kā avis, mēs raudzījāmies ikviens uz savu ceļu, bet Tas Kungs Viņam uzlika visus mūsu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Vārdzināts Viņš zemojās un neatdarīja Savu muti, tā kā jērs, kas top vests pie kaušanas un kā avs, kas klusu paliek priekš sava cirpēja; tāpat Viņš neatdarīja Savu muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'No bailības un sodības Viņš ir izrauts, bet kas no Viņa cilts to apdomāja, ka Viņš tapa aizrauts no dzīvo zemes un bija mocīts Manas tautas pārkāpumu dēļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Kapu Viņam lēma pie bezdievīgiem, un pie tā bagātā Viņš bija Savā nāvē, lai gan netaisni nebija darījis nedz viltība bijusi Viņa mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Bet Tas Kungs gribēja Viņu sagrauzt ar sāpēm: Kad Tu Viņa dvēseli būsi nodevis par nozieguma upuri, tad Viņš redzēs dzimumu un dzīvos ilgi, un Tā Kunga prāts labi izdosies caur Viņa roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Tādēļ ka Viņa dvēsele grūti strādājusi, Viņš redzēs prieku un (panākumu) papilnam. Caur Savu atzīšanu Mans kalps, Tas Taisnais, darīs daudz taisnus, jo Viņš nesīs viņu noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Tāpēc Es Viņam došu lielu pulku par daļu, un Viņš dalīs tos varenos kā laupījumu, tādēļ ka Viņš līdz pat nāvei pazemojies un ir pieskaitīts pārkāpējiem; un Viņš daudzu grēkus nesis un par pārkāpējiem lūdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Dziedi priecīgi, neauglīgā, kas neesi dzemdējusi, līksmodamies slavē un gavilē, kam bērnu sāpes nav bijušas. Jo tai vientulei ir vairāk bērnu, nekā tai laulātai, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Paplēti savas telts vietu, un paplašini sava dzīvokļa aizkarus, nekavē, pagarini savas virves un stiprini savus telts mietus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Jo tu vairosies pa labo un pa kreiso roku, un tavs dzimums iemantos tautas un dzīvos postītās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Nebīsties, jo tu netapsi kaunā, un nekaunies, jo tu netapsi apsmieklā, jo tu aizmirsīsi savas jumpravības kaunu un savas atraitnības negodu tu vairs nepieminēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Jo tavs Radītājs ir tavs vīrs, Kungs Cebaot ir Viņa vārds, un tas Svētais iekš Israēla ir tavs Pestītājs, - Viņš tiek saukts visas pasaules Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Jo Tas Kungs tevi aicinājis kā atstātu un no sirds noskumušu sievu, un kā jaunības sievu, kas bija nicināta, saka tavs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Mazu acumirkli Es tevi biju atstājis, bet ar lielu žēlastību Es tevi gribu sapulcināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Dusmu brīdī Es Savu vaigu esmu apslēpis no tevis kādu acumirkli, bet ar mūžīgu žēlastību Es par tevi gribu apžēloties, saka Tas Kungs, tavs Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Jo tas Man būs kā Noas ūdeņi, kur Es zvērēju, ka Noas ūdeņiem nebija vairs pārplūst zemi; tāpat Es esmu zvērējis, ka Es par tevi vairs negribu dusmoties, nedz tevi rāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Jo kalni atkāpsies un pakalni šaubīsies, bet Mana žēlastība no tevis neatkāpsies, un Mana miera derība nešaubīsies, saka Tas Kungs, tavs apžēlotājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Tu apbēdinātā, vētrām šaubītā, tu neiepriecinātā, redzi, Es tavus akmeņus likšu skaistumā un tevi uztaisīšu uz safīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Un tavus logus Es darīšu no kristāla un tavus vārtus no rubīna akmeņiem un visas tavas robežas no dārgiem akmeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Un visi tavi bērni būs no Tā Kunga mācīti, un tavu bērnu miers būs liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Caur taisnību tu tapsi stiprināta. Tu būsi tālu no bēdām, jo tev nav ko bīties, un no briesmām, jo tās tev neuznāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Redzi, pulcēt sapulcējās, bet tas nav no manis; kas vien pret tevi pulcējās, tas tevis pēc kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Redzi, Es kalēju esmu radījis, kas ogles uzpūš ugunī un ieroci taisa pēc sava amata, arī to postītāju Es esmu radījis priekš postīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nevienam ierocim, kas pret tevi taisīts, neizdosies, un tu notiesāsi katru mēli, kas ceļas tiesā pret tevi. Šī ir Tā Kunga kalpu daļa, un viņu taisnība ir no Manis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Nu tad, visi iztvīkušie, nāciet pie ūdens, un kam naudas nav, nāciet, pērciet un ēdiet, nāciet un pērciet bez naudas un bez maksas, vīnu un pienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Kāpēc jūs naudu nosverat par to, kas maize nav, un savu pelņu par to, no kā nevar paēst? Klausāties, klausāties uz Mani tad baudīsiet labumu un jūsu dvēsele atspirdzināsies taukumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Griežat šurp savu ausi un nāciet pie Manis, klausiet, tad jūsu dvēsele dzīvos! Jo Es jums celšu mūžīgu derību: Dāvida pastāvīgās apžēlošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Redzi, Es viņu esmu iecēlis tautām par liecinieku, tautām par virsnieku un valdītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Redzi, tu sauksi tautas, ko nepazini, un ļaudis, kas tevi nepazina, pie tevis steigsies, Tā Kunga, tava Dieva, Israēla Svētā, dēļ, jo Tas tevi pagodinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Meklējiet To Kungu, kamēr Tas atrodams, piesauciet Viņu, kamēr Tas tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Lai bezdievīgais atstāj savu ceļu un ļaundarītājs savas domas un atgriežas pie Tā Kunga, tad Viņš par to apžēlosies un pie mūsu Dieva, jo pie Viņa ir daudz piedošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Jo Manas domas nav jūsu domas un jūsu ceļi nav Mani ceļi, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Jo tā kā debesis augstākas nekā zeme, tā Mani ceļi augstāki nekā jūsu ceļi, un Manas domas nekā jūsu domas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Jo tā kā lietus un sniegs nāk no debesīm un turp neatgriežas, bet slapina zemi un dara to auglīgu un zaļojam, ka tā dod sēklu sējējam un maizi ēdējam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Tāpat būs Mans vārds, kas iziet no Manas mutes; tas neatgriezīsies pie Manis tukšs, bet darīs, kas Man patīk, un izdosies labi, par ko Es to sūtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Jo ar prieku jūs iziesiet un ar mieru jūs tapsiet vadīti, kalni un pakalni jūsu priekšā gavilēs gavilēdami, un visi koki laukā plaukšķinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Ērkšķu vietā uzaugs priedes, un dadžu vietā uzaugs mirtes, un tas Tam Kungam būs par slavu un par mūžīgu zīmi, kas netaps izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Tā saka Tas Kungs: turiet tiesu un dariet taisnību; jo Mana pestīšana ir tuvu nākusi, un Mana taisnība parādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Svētīgs tas cilvēks, kas to dara, un tas cilvēka bērns, kas stipri pie tā turas, kas svētdienu svēti un to nesagāna, un sargā savu roku, ka nedara ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Un tas svešinieks, kas Tam Kungam pieķeras, lai nerunā un nesaka: Tas Kungs mani patiesi atšķirs no saviem ļaudīm; un, kas rāmits(kastrēts), lai nesaka: redzi, es esmu sakaltis koks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Jo tā saka Tas Kungs uz tiem rāmitiem: kas svētī Manas svētdienas un to pieņem, kas Man patīk, un stipri tura Manu derību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Tiem Es došu vietu Savā namā un Savos mūros, un vārdu, kas labāks nekā dēli un meitas, mūžīgu vārdu Es tiem došu, kas netaps izdeldēts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Un tos svešiniekus, kas Tam Kungam pieķeras, Viņam kalpot un Tā Kunga vārdu mīlēt, Viņam būt par kalpiem, - visus, kas svētdienu svētī un to nesagāna, un kas stipri turas pie Manas derības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Tos Es nesīšu uz Savu svēto kalnu un tos iepriecināšu Savā lūgšanas namā; viņu dedzināmie un viņu kaujamie upuri būs patīkami uz Mana altāra. Jo Mans nams taps nosaukts lūgšanas nams visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Tas Kungs Dievs, kas sapulcina Israēla izdzītos, saka: Es pie viņa vēl vairāk sapulcināšu pār tiem, kas jau ir sapulcināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Visi lauka zvēri, nāciet ēst, arī visi meža zvēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Visi viņu sargi ir akli, tie nezin nekā, tie visi ir mēmi suņi, kas nemāk riet, sapņodami tie guļ, iemīl miegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Un šie suņi ir plēsīgi un nepieēdināmi. Un šie ir gani, kam pašiem nav saprašanas, tie visi līdz beidzamam iet ikviens pa savu ceļu, pēc savas peļņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Nāciet šurp, (tie saka) es dabūšu vīnu, un dzersim stipru dzērienu un rītā lai ir kā šodien, papilnam, jo vairāk jo labāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Taisnais iet bojā, un nav neviena, kas to ņem pie sirds, un dievbijīgie top aizrauti, un neviens to neliek vērā. Jo taisnais top aizrauts, pirms ļaunums nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Kas savu taisno ceļu gājuši, nāk pie miera un dus savos kambaros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Bet jūs, nākat šurp, zīlnieces bērni, laulības pārkāpēja un maucinieces dzimums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Par ko jūs smejaties? Pret ko jūs atplēšat savu muti un izstiepjat savu mēli? Vai jūs neesat pārkāpēju bērni un viltnieku dzimums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Jūs esat sakarsuši uz dievekļiem apakš visiem zaļiem kokiem un nokāvāt bērnus pie upēm apakš akmens kalnu stūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Pie gludeniem upes akmeņiem bija tava daļa, tā bija tava tiesa, un tiem tu izlēji dzeramu upuri un upurēji ēdamu upuri; vai Man ar to bija mierā būt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Tu taisīji savu gultu lielā un augstā kalnā, ir tur tu uzkāpi, upurus upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Un aiz durvīm un stenderēm tu liki savu piemiņas zīmi, jo atstādamies no manis tu atsedzi un kāpi un taisīji platu savu gultu un līki ar tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Tu iemīlēji viņu gultu un uzlūkoji to vietu. Tu gāji ar eļļu pie ķēniņa un nesi daudz smaržīgu zāļu, un tālu sūtīji savus vēstnešus un meties zemē līdz ellei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Tu nopūlējies savā garā ceļā un nesacīji: velti! Tu atradi jaunu spēku, tāpēc tu nenoguri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Bet no kā tev bija bail un ko tu bijies? Jo tu paliki par meli un Mani nepieminēji un neņēmi pie sirds. - Vai nav tā, kad Es sen dienām klusu cietis, tad tu Manis nebīsties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Es darīšu zināmu tavu taisnību un tavus darbus, ka tie tev nepalīdzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Kad tu brēksi, tad lai tev palīdz tavs (dievekļu) pulks; bet vējš tos visus aiznesīs, un vēsma tos aizraus. Bet kas uz Mani paļaujas, tas iemantos zemi un Manu svēto kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Un Viņš sacīs: līdziniet, līdziniet, sataisiet ceļu, atņemat šķēršļus no Manu ļaužu ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Jo tā saka tas Augstais un Varenais, kas dzīvo mūžīgi un kā vārds ir svēts: Es dzīvoju augstībā un svētā vietā un pie tā, kam sagrauzts un pazemīgs gars, ka dzīvu daru garu pazemīgiem un dzīvu daru sirdi sagrauztiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Jo Es nebāršos mūžīgi nedz dusmošos bez gala; jo priekš Mana vaiga nonīktu gars un tās dvēseles, ko esmu radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Es biju apskaities par viņu grēcīgo mantas kārību un tos situ un apslēpos un apskaitos, taču tie atkāpušies aizgāja pa savas sirds ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Es ieraudzīju viņu ceļus, un tos dziedināšu, un Es tos vadīšu un došu prieku tiem, kas apbēdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Es radīšu lūpu augļus: miers, miers lai ir tiem, kas tālu un kas tuvu, saka Tas Kungs, un Es tos dziedināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Bet tie bezdievīgie ir kā aizkustināta jūra, kas nevar nostāties, un viņas viļņi izmet dūņas un dubļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Bezdievīgiem nav miera, saka mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Sauc pilnā kaklā, netaupi, pacel savu balsi kā bazūni, un pasludini Maniem ļaudīm viņu pārkāpumus un Jēkaba namam viņa grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Jo Tie Mani meklē ikdienas, tā kā tiem būtu labs prāts pie Manu ceļu atzīšanas. Kā ļaudis, kas darījuši taisnību un nebūtu atstājuši sava Dieva tiesu, tie prasa no Manis taisnības tiesu; tie grib, lai Dievs tiem tuvojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Kāpēc (tā tie saka) mēs gavējam, un tu to neuzlūko? Kāpēc mēs mērdējam savu dvēseli, un tu to negribi zināt? Redzi, tai dienā, kad jūs gavējat, tad jūs ejat pēc savas peļņas un dzenat visus savus strādniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Redzi, jūs gavējat bārdamies un riedamies un bezdievīgi kaudamies ar dūri. Jūs negavējat, kā pieklājās, lai jūsu balsis būtu dzirdamas augstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Vai tāda ir gavēšana, kas Man patīk, diena, kur cilvēks savu dvēseli mērdē? Kad galvu nokar kā niedre un gulstas uz maisa un pelnos, vai jūs to saucat par gavēšanu un par dienu, kas Tam Kungam patīk?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Vai tā nav gavēšana, kas Man patīk: atraisīt no netaisnām saitēm, no jūga atsvabināt, spaidītus atlaist vaļā un salauzt ikkatru jūgu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Vai tā nepiederas, maizi lauzt izsalkušiem, namā ievest nabaga izdzītus, kailu ieraugot, to apsegt un neapslēpties no sava tuvāka?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Tad ausīs tava gaisma kā dienas blāzma, un tava dzīvība no jauna zels, un tava taisnība ies tavā priekšā, un Tā Kunga godība tevi pavadīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Tad tu sauksi, un Tas Kungs atbildēs, tu brēksi, un Viņš sacīs: redzi, še Es esmu. Ja no sava vidus izraidīsi varmācību, mitēsies ar pirkstiem rādīt un nerunāsi ļauna,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Un ja tu izsalkušam atdarīsi savu sirdi un paēdināsi apbēdināto dvēseli, tad tava gaisma atspīdēs tumsībā, un tava krēsla būs kā dienas vidus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Un Tas Kungs tevi vadīs bez mitēšanās un pieēdinās tavu dvēseli tuksnesī un stiprinās tavus kaulus. Un tu būsi kā slacināts dārzs un kā ūdens avots, kam ūdens netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Un tavi bērni uzcels vecu vecās posta vietas, tu atjaunosi pagājušu cilšu pamatus un tevi sauks (par) plaisumu aizmūrētāju un ceļu atjaunotāju, kur var dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Ja tu savu kāju savaldi svētdienā un nedari, kas tev patīk, Manā svētā dienā, un ja tu dusas dienu nosauci par līksmību, par Tā Kunga svēto (dienu), kas cienījama, un tu tā viņu godā turi, ka nestaigā savus ceļus nedz ej pēc savas pelņas nedz runā liekus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Tad tu priecāsies iekš Tā Kunga, un Es tevi vadīšu pār zemes augstumiem, un Es tevi mielošu ar tava tēva Jēkaba mantību; jo Tā Kunga mute to runājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Redzi, Tā Kunga roka nav paīsināta, palīdzēt, un Viņa auss nav bieza, dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Bet jūsu noziegumi jūs atšķir no jūsu Dieva, un jūsu grēki apslēpj Viņa vaigu no jums, ka Viņš neklausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Jo jūsu rokas ir sagānītas ar asinīm un jūsu pirksti ar netaisnību, jūsu lūpas runā viltību, un jūsu mēle izdomā nepatiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Neviena nav, kas taisnību sludina, un neviena, kas uzticīgi tiesā; tie paļaujas uz tukšiem niekiem un runā viltu, tie nesās ar nelietību un dzemdē postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Tie perē čūsku pautus(olas) un auž zirnekļa tīklus. Kas no viņu pautiem ēd, tam jāmirst, un kad vienu samin, tad odze izlec.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Viņu audumi neder drēbēm, un ar viņu darījumiem nevar apsegties, viņu darbi ir nelietīgi darbi, un varmācība ir viņu rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Viņu kājas skrien uz ļaunumu un steidzās izliet nenoziedzīgas asinis, viņu domas ir nelietīgas domas, posts un nelaime ir uz viņu ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Miera ceļu tie nezin, un tiesa nav viņu gājumos, tie groza savus ceļus; neviens, kas pa tiem staigā, nezin mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Tādēļ tiesa ir tālu no mums, un taisnība mūs nepanāk, mēs gaidām uz gaismu, bet redzi, te ir tumsa, - uz spožumu, bet mēs staigājam krēslā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Mēs grābstāmies gar sienām, kā akli, un kā kam acu nav, tā mēs grābstāmies; mēs piedauzamies dienas vidū tā kā krēslā, pašā zaļā dzīvībā esam kā miruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Mēs rūcam visi kā lāči, vaidam kā baloži, gaidām uz tiesu bet nav, uz pestīšanu, bet tā no mums tālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Jo mūsu pārkāpumu ir daudz Tavā priekšā, un mūsu grēki dod pret mums liecību. Jo mūsu pārkāpumi ir mūsu priekšā, un mēs zinām savus noziegumus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Mēs esam atkāpušies un To Kungu aizlieguši, nogriezušies no sava Dieva, runājam varmācību un bezdievību, sadomājam un izgāžam no sirds melu valodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Tiesa ir atstumta nost, un taisnība stāv no tālienes, jo patiesība klūp uz ielas, un skaidrība netiek iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Tiešām, patiesība palikusi reta, un kas no ļauna atkāpjas, paliek par laupījumu. Tas Kungs to redzēja, un tas viņam nepatika, ka taisnības nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Un Viņš redzēja, ka neviena nav, un brīnījās, ka aizstāvētāja nav. Un Viņam palīdzēja Viņa elkonis, un Viņa taisnība Viņu turēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Un Viņš apvilka taisnību kā krūšu bruņas un lika galvā pestīšanas bruņu cepuri, un Viņš apvilka par apģērbu atriebšanas drēbes un apņēma karstu dusmību kā mēteli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Tā kā pelnījuši, tā Viņš atmaksās, bardzību Saviem pretiniekiem, atmaksu Saviem ienaidniekiem, salām Viņš atlīdzinās, kā pelnījušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Tad bīsies Tā Kunga vārdu no vakara puses un no saules uzlēkšanas Viņa godību; jo Viņš nāks kā uzplūdusi upe, ko Tā Kunga dvaša dzen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Un Pestītājs nāks Ciānai un tiem, kas iekš Jēkaba atgriežas no pārkāpšanas, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, '“Šī ir Mana derība ar tiem,” saka Tas Kungs: “Mans Gars, kas uz tevi, un mani vārdi, ko esmu licis tavā mutē, tie neatstāsies no tavas mutes, nedz no tava dzimuma mutes, nedz no tavu bērnu bērnu mutes,” saka Tas Kungs, “no šī laika mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Celies, topi apgaismota, jo tava gaisma nāk, un Tā Kunga godība uzlec pār tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Jo redzi, tumsība apklāj zemi un krēslība ļaudis, bet pār tevi uzlēks Tas Kungs, un Viņa godība pār tevi rādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Un pagāni staigās tavā gaismā un ķēniņi tai spožumā, kas pār tevi uzlēcis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Pacel savas acis visapkārt un skaties: visi tie ir sapulcināti un nāk pie tevis. Tavi dēli nāk no tālienes, un tavas meitas uz rokām top atnestas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Tad tu redzēsi un izplūdīsi kā upe, un tava sirds brīnīsies un izpletīsies, jo jūras draudze pie tevis atgriezīsies un pagānu spēks nāks pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Tevi apklās kamieļu pulks, čaklie kamieļi no Midijanas un Epas, visi tie nāks no Sabas, zeltu un vīraku tie atnesīs un teiks Tā Kunga slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Visas avis no Ķedara sapulcēsies pie tevis, tie auni no Nebajota tev kalpos, tie nāks par labprātību uz Manu altāri, un Es pagodināšu Savas godības namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kas ir tie, kas skriedami nāk kā padebeši, un kā baloži pie saviem logiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Jo salas gaida uz Mani un Taršiša kuģi iet papriekš, tavus bērnus atvest no tālienes, un viņu zeltu un sudrabu līdz ar tiem, Tā Kunga, tava Dieva vārdam un tam Svētajam iekš Israēla; jo Viņš tevi pagodinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Un sveši uzcels tavus mūrus, un viņu ķēniņi tev kalpos; jo Savā dusmībā Es tevi esmu sitis, bet Savā žēlastībā Es par tevi esmu apžēlojies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Un tavi vārti stāvēs vienmēr vaļā un netaps aizslēgti ne dienu ne nakti, ka pie tevis var atvest pagānu spēku un viņu ķēniņus ar pavadīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Jo tās tautas un valstis, kas tev negrib kalpot, ies bojā, un šīs tautas pavisam taps izdeldētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Lībanus godība nāks pie tevis, priede, kļava un bukses koks, tie visi, un pušķos Mana svētuma vietu, un Es pagodināšu to vietu, kur Manas kājas dus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Un pazemīgi nāks pie tevis tavu spaidītāju bērni, un visi, kas tevi zaimojuši, klanīsies līdz tavām pēdām un tevi nosauks par Tā Kunga pilsētu, par Ciānu, kur tas Israēla Svētais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Par to, ka tu esi bijusi atstāta un ienīdēta un neapmeklēta, Es tevi iecelšu par mūžīgu greznumu, par prieku līdz cilšu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Un tu zīdīsi pagānu pienu, un ķēniņu krūtis tu zīdīsi. Un tu atzīsi, ka Es, Tas Kungs, esmu tavs Pestītājs un tavs izglābējs, tas varenais iekš Jēkaba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Vara vietā Es atnesīšu zeltu, un dzelzs vietā Es atnesīšu sudrabu un koku vietā varu un akmeņu vietā dzelzi, un darīšu mieru par tavu valdītāju un taisnību par tavu uzraugu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Varas darbs tavā zemē vairs netaps dzirdēts, un ne posts ne pazušana tavās robežās, bet tu nosauksi pestīšanu par saviem mūriem un slavu par saviem vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Saule tev vairs nebūs par gaismu dienā, nedz mēnesis tev spīdēs par spīdekli, bet Tas Kungs tev būs par mūžīgu gaismu, un tavs Dievs par tavu greznumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Tava saule vairs nenoies un tavs mēnesis vairs nemainīsies; jo Tas Kungs tev būs par mūžīgu gaismu, un tavām skumju dienām būs gals.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Un tavi ļaudis būs visnotaļ taisni, tie turēs to zemi par īpašumu mūžam, tie būs Manis dēstīts zars un Manu roku darbs, Man par godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Tas mazākais paliks par tūkstoti un tas sīkākais par varenu tautu. Es Tas Kungs to pasteigšu (izpildīt) savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Tā Kunga Dieva Gars ir uz manis, jo Tas Kungs mani svaidījis, nabagiem sludināt prieka vēsti, mani sūtījis, sagrauztas sirdis dziedināt, cietuma ļaudīm sludināt atsvabināšanu un saistītiem pilnīgu atraisīšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Pasludināt Tā Kunga žēlastības gadu un mūsu Dieva atriebšanas dienu, iepriecināt visus noskumušos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Tiem apbēdinātiem iekš Ciānas uzlikt un dāvināt glītumu pelnu vietā, prieka eļļu skumības vietā, skaistas drēbes izmisuša prāta vietā, ka tie top nosaukti stipri taisnības koki, Tā Kunga iedēsti Viņam par godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Un tie uztaisīs vecās posta vietas un uzcels senlaiku drupas un atjaunos sagruvušas pilsētas, kas jau priekš cilšu ciltīm bijušas postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Un svešinieki stāvēs un ganīs jūsu lopus, un svešuma bērni būs jūsu arāji un jūsu vīna dārznieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Bet jūs tapsiet saukti Tā Kunga priesteri, uz jums sacīs: mūsu Dieva kalpi. Jūs ēdīsiet pagānu spēku un mantosiet viņu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Sava kauna vietā jūs dabūsiet divkārtīgi (godu), un negoda vietā tie gavilēs par savu tiesu. Jo tie mantos savā zemē divkārtīgu daļu, un tiem būs mūžīga līksmība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Jo Es Tas Kungs mīlu tiesu un ienīstu netaisnu laupījumu. Un Es tiem dodu viņu algu pēc taisnības un daru ar tiem mūžīgu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Un viņu dzimums taps pazīstams starp pagāniem, un viņu bērnu bērni starp tautām; visi, kas tos redzēs, tos pazīs, jo tie ir dzimums, ko Tas Kungs svētījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Es priecājos ar lielu prieku iekš Tā Kunga, mana dvēsele līksmojās iekš mana Dieva. Jo Viņš mani apģērbis ar pestīšanas drēbēm, ar taisnības svārkiem Viņš mani apsedzis, tā kā brūtgāns ģērbjas svētku glītumā, un kā brūte greznojās savā skaistā apģērbā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Jo kā zeme izdod savus augļus, un kā dārzs liek uzdīgt savam sējumam, tā Tas Kungs Dievs liks izplaukt taisnībai un slavai priekš visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Ciānas dēļ es klusu necietīšu un Jeruzālemes labad es nerimšu, kamēr viņas taisnība aust kā spožums un viņas pestīšana iedegās kā uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Un tautas redzēs tavu taisnību un visi ķēniņi tavu godību, un tevi sauks ar jaunu vārdu, ko Tā Kunga mute skaidri noteiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Un tu būsi skaists kronis Tā Kunga rokā un ķēniņa galvas glītums tava Dieva rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Uz tevi vairs nesacīs: atstāta, un uz tavu zemi vairs nesacīs: izpostīta. Bet tevi nosauks: pie kā Man ir labs prāts, - un tavu zemi: tā laulātā. Jo Tam Kungam ir labs prāts pie tevis, un tava zeme taps laulāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Jo kā jauneklis laulājās ar jaunavu, tā ar tevi laulāsies tavi bērni, un kā brūtgāns priecājās par brūti, tā par tevi priecāsies tavs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Jeruzāleme, Es iecelšu sargus uz taviem mūriem, kas nekad ne dienu ne nakti necietīs klusu! Jūs, kas To Kungu piesaucat, nestāviet klusu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Neliekat Viņu mierā, kamēr Viņš stiprina Jeruzālemi un to padara slavenu virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Tas Kungs ir zvērējis pie Savas labās rokas un pie Sava stiprā elkoņa: Tavu labību Es vairs nedošu ēst taviem ienaidniekiem, un svešinieki nedzers vairs tavu vīnu, ar ko tu esi pūlējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Bet kas to sakrāj, tie to ēdīs un slavēs To Kungu, un kas to lasīs, tie to dzers Manos svētos pagalmos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Izejiet, izejiet pa vārtiem, sataisiet tiem ļaudīm ceļu, līdziniet, līdziniet staigājamu ceļu, atņemiet akmeņus, izceļat karogu pār tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Redzi, Tas Kungs sludina līdz pasaules galam: sakāt Ciānas meitai: redzi, tava pestīšana nāk, redzi, Viņa alga ir pie Viņa un Viņa atmaksa ir Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Un tos sauks: „Svētā tauta“, „Tā Kunga atpestītie“un tevi sauks „Meklētā“, „neatstātā pilsēta“.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kas tas ir, kas nāk no Edoma, sarkanām drēbēm no Bocras, grezns Savā apģērbā, lepns Savā lielā spēkā? Es, kas runāju taisnību, un varens esmu atpestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Kāpēc tad tavs apģērbs tik sarkans un tavas drēbes kā vīna spaida minējam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Es to spaidu esmu minis viens pats, un neviens no tautām nebija ar Mani. Un Es tos esmu minis Savā dusmībā un saminis Savā bardzībā. Tad viņu sula apslacināja Manas drēbes, un viss Mans apģērbs tapa aptraipīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Jo atriebšanas diena ir Manā sirdī, un Mans pestīšanas gads ir atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Jo Es skatījos, un palīga nebija, un Es brīnījos, bet atspaida nebija; tāpēc Man palīdzēja Mans elkonis, un Mana bardzība Man bija par atspaidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Un Es saminu tautas Savā dusmībā un tās piedzirdināju Savā bardzībā un nometu zemē viņu spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Es pieminēšu Tā Kunga žēlastību, Tā Kunga teicamo slavu par visu, ko Tas Kungs mums parādījis, un par to lielo labumu pie Israēla nama, ko Viņš tiem darījis pēc Savas bagātās žēlastības un pēc Savas lielās apžēlošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Jo Viņš sacīja: tie tomēr ir Mani ļaudis, bērni, kas nevils; un Viņš tiem palika par Pestītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Visās viņu bēdās Viņš par tiem bēdājās, un Viņa vaiga eņģelis tos izglāba. Caur Savu mīlestību un caur Savu žēlastību Viņš tos atpestīja un uzņēma un tos nesa no veciem laikiem allažiņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Bet tie turējās pretī un apkaitināja Viņa Svēto Garu, tāpēc Viņš tiem pārvērtās par ienaidnieku, Viņš pats karoja pret tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Tad Viņa tauta pieminēja vecos Mozus laikus: Kur ir, kas tos no jūras izveda ar Sava ganāmā pulka ganu? Kur ir, kas viņu sirdīs deva Savu Svēto Garu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Kas Mozu pie labās rokas pavadīja ar Savas godības elkoni, kas ūdeņus pāršķēla viņu priekšā un Sev darīja mūžīgu vārdu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Kas tos vadīja caur dziļumiem, kā zirgu pa klajumu, un tie neklupa?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Tā kā ganāms pulks nokāpj ielejā, tā Tā Kunga Gars tos vadījis pie dusas. Tā Tu Savus ļaudis esi vadījis, ka Tu Sev darītu slavenu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Raugies no debesīm un skaties zemē no tās vietas, kur Tava svētā godība mājo. Kur ir Tava karstā mīlestība un Tava vara, Tava lielā sirds iežēlošanās un Tava žēlastība? Tās turas cieti pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Tu tomēr esi mūsu Tēvs, jo Ābrahāms mūs nezin un Israēls mūs nepazīst. Tu, Kungs, esi mūsu Tēvs, mūsu Pestītājs, no veciem laikiem tas ir Tavs vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Kungs, kāpēc Tu mums lieci maldīties no Taviem ceļiem, kāpēc Tu mūsu sirdi apcietini, ka Tevi nebīstamies? Griezies atpakaļ Savu kalpu dēļ, to cilšu labad, kas Tava mantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Uz īsu laiku Tava svētā tauta bija mantojusi, - mūsu pretinieki samina Tavu svēto vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Mēs esam palikuši tā kā tādi, par kuriem Tu ne mūžam neesi valdījis, un kas nav nosaukti pēc Tava vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Ak kaut Tu pārplēstu debesis un nonāktu zemē, ka kalni izkustu Tavā priekšā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Tā kā uguns iededzina žagarus, un kā uguns ūdeni dara uzverdam, - ka Tavs vārds tiktu zināms Taviem pretiniekiem, ka pagāni drebētu Tavā priekšā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Caur tiem brīnumiem, ko Tu dari mums negaidot, kaut Tu nonāktu zemē, kaut kalni izkustu Tavā priekšā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Nemūžam nav dzirdēts, nedz samanīts, nedz acīm redzēts cits Dievs, kā vien Tu, kas tā dara tam, kas uz Viņu gaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Tu nāci tiem tuvu, kas taisnību dara ar prieku, kas Tevi piemin uz Taviem ceļiem. Redzi, Tu esi apskaities, tāpēc ka mēs esam grēkojuši, un ilgi tā esam palikuši; vai tapsim izglābti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Mēs visi esam kā nešķīsti, un visa mūsu taisnība kā sārņaina drēbe. Un mēs visi novīstam kā lapa, un mūsu grēki mūs aizrauj kā vējš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Un neviena nav, kas Tavu Vārdu piesauc, kas uzmostas un tveras pie Tevis. Jo Tu apslēpi Savu vaigu no mums un liec mums nīcin iznīkt caur mūsu grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Nu tad, Kungs, Tu esi mūsu Tēvs, mēs esam māls, un Tu esi mūsu darītājs, un mēs visi esam Tavas rokas darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Neapskaisties, Kungs, tik ļoti, un nepiemini noziegumu mūžīgi, redzi, uzlūko jel, ka mēs visi esam Tavi ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Tavas svētās pilsētas palikušas par tuksnesi, Ciāna par tuksnesi, Jeruzāleme par postažu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Mūsu svētais un skaistais Dieva nams, kur mūsu tēvi Tevi slavējuši, ir sadedzināts ar uguni, un viss mūsu acu prieks ir bojā gājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Kungs, vai Tu būsi ciets, šās lietas redzēdams? Vai Tu klusu cietīsi, un mūs tik ļoti apbēdināsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Es topu meklēts no tiem, kas pēc Manis nevaicāja, Es topu atrasts no tiem, kas Mani nemeklēja. Es esmu sacījis uz tautu, kas Manu vārdu nepiesauca: redzi, še Es esmu, redzi, še Es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Es izplešu Savas rokas cauru dienu uz pārgalvīgiem ļaudīm, kas uz nelaba ceļa staigā pēc savām pašu domām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Uz ļaudīm, kas vienmēr Mani kaitina, kas Manā priekšā upurē dārzos un kvēpina uz ķieģeļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Kas sēž pie kapenēm un kapu alās paliek pa naktīm un ēd cūku gaļu, un negantas sulas ir viņu traukos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Kas saka: paliec, nenāc man klāt, jo es esmu svēts priekš tevis. Šie būs par dūmiem Manā dusmībā, par uguni, kas deg cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Redzi, tas ir Manā priekšā rakstīts: Es necietīšu klusu, bet Es atmaksāšu, un pat viņu azotē Es atmaksāšu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Jūsu noziegumus un jūsu tēvu noziegumus kopā, saka Tas Kungs, ka ir kvēpinājuši uz kalniem un Mani zaimojuši uz pakalniem; tāpēc viņu algu Es papriekš atmaksāšu viņu azotē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Tā saka Tas Kungs: tā kā kad vīnu atrod ķekarā un saka: nemaitā to, jo svētība tur iekšā, tāpat Es darīšu Savu kalpu dēļ, ka Es tos visus nenomaitāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Bet Es no Jēkaba radīšu dzimumu un no Jūda, kas manto Manus kalnus, un Mani izredzētie to iemantos, un Mani kalpi tur dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Un Šarons taps par avju ganībām, un Ahora ieleja par lopu laidaru priekš Maniem ļaudīm, kas Mani meklējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Bet jūs, kas no Tā Kunga atkāpušies, kas Manu svēto kalnu aizmirstat un galdu sataisiet tam Gad (Liktenim) un dzeramus upurus ielejat tai Meni (Laimei), -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Es jūs arī nolikšu zobenam, ka jums visiem būs locīties pie kaušanas, tāpēc ka Es esmu aicinājis, bet jūs neesat atbildējuši, Es esmu runājis, un jūs neesat klausījuši, bet darījuši, kas ļauns bija Manās acīs, un izraudzījušies, kas Man nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Tādēļ Tas Kungs Dievs tā saka: redzi, Mani kalpi ēdīs, bet jūs būsiet izsalkuši; redzi, Mani kalpi dzers, bet jūs iztvīksiet; redzi, Mani kalpi priecāsies, bet jūs tapsiet kaunā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Redzi, Mani kalpi gavilēs sirds priekā, bet jūs brēksiet sirdēstos un kauksiet satriektā garā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Un jūs atstāsiet savu vārdu Maniem izredzētiem par lāstu vārdu, un Tas Kungs Dievs tevi nokaus, bet Savus kalpus Viņš nosauks ar citu vārdu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Un kas virs zemes svētīsies, tas svētīsies pie tā patiesā Dieva, un kas virs zemes zvērēs, tas zvērēs pie tā patiesā Dieva; jo tās pirmās bēdas būs aizmirstas un priekš Manām acīm apslēptas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Jo redzi, Es radu jaunas debesis un jaunu zemi, un tās pirmās lietas vairs nepieminēs, un tās vairs nenāks prātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Bet priecājaties un līksmojaties mūžīgi mūžam par to, ko Es radu. Jo redzi, Es radīšu Jeruzālemi par prieku un viņas ļaudis par līksmību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Un Es priecāšos par Jeruzālemi un līksmošos par Saviem ļaudīm, un tur vairs netaps dzirdēta ne raudāšanas balss, ne kaukšanas balss.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Tur nebūs vairs bērniņi, kas ilgi nedzīvos, nedz veci, kas savas dienas nepiepilda; bet jauneklis mirs simts gadus vecs būdams, un bezdievīgais taps nolādēts simts gadus vecs būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Un tie uztaisīs namus un dzīvos iekš tiem, tie dēstīs vīna dārzus un ēdīs viņu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Tie neuztaisīs, lai cits tur dzīvo, un nedēstīs, lai cits to ēd; jo Manu ļaužu mūžs būs ka koku mūžs un Mani izredzētie baudīs savu roku darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Tie nestrādās velti, nedz dzemdēs bērnus briesmīgam galam. Jo tie ir Tā Kunga svētīto dzimums un viņu bērnu bērni līdz ar tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Un notiks, pirms tie sauc, tad Es atbildēšu, kad tie vēl runā, tad Es klausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Vilki un jēri ies kopā ganos un lauva ēdīs salmus kā vērsis, un pīšļi būs čūskas barība; tie nedarīs ļauna un nedarīs posta visā Manā svētā kalnā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Tā saka Tas Kungs: Debesis ir Mans goda krēsls, un zeme ir Mans kāju pamesls; kur būtu tas nams, ko jūs Man taisītu, un kur būtu vieta priekš Manas dusas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Jo Mana roka visas šīs lietas radījusi, un tā visas tās cēlušās, saka Tas Kungs; bet uz to Es skatīšos, proti uz nabagu, un kam sagrauzts gars, un kas priekš Mana Vārda dreb.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Kas vērsi nokauj, ir kā kas vīru nokauj; kas jēru upurē, ir kā kas sunim lauž kaklu; kas ēdamu upuri upurē, ir kā kas upurē cūku asinis; kas vīraku dedzina par piemiņas upuri, ir kā kas elku teic. Jo tie izvēlās savus pašu ceļus, un viņu dvēselei ir labs prāts pie savām negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Tad arī Es tiem novēlēšu mokas un atvedīšu pār tiem briesmas, tāpēc ka Es saucu, un neviens neatbildēja, Es runāju, un neviens neklausīja, bet tie ir darījuši, kas ļauns priekš Manām acīm, un izvēlējušies, kas Man nepatika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Klausiet Tā Kunga vārdu, kas Viņa vārdu bīstaties. Jūsu brāļi, kas jūs ienīst, kas jūs atstumj Mana Vārda dēļ, saka: lai Tas Kungs pagodinājās, ka mēs redzam jūsu prieku; bet tie taps kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Trokšņa balss būs pilsētā, balss no Dieva nama, Tā Kunga balss, kas Saviem ienaidniekiem atmaksā, kā tie pelnījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Pirms nāca bērnu sāpes, viņa ir dzemdējusi, pirms viņai uzgāja bailība, viņai dēls ir dzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kas jel jebkad šo dzirdējis, kas šādas lietas redzējis? Vai zeme var piedzimt vienā dienā, vai tautu var dzemdēt vienā reizē? Jo Ciāna, tikko tai bērnu sāpes uznāca, arī dzemdējusi savus bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Vai Es liktu nākt līdz dzimšanai un neļautu dzemdēt? Saka Tas Kungs: Vai Es, kas dod spēku dzemdēt, atkal aizturētu? Saka tavs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Priecājaties ar Jeruzālemi un līksmojaties par viņu visi, kas to mīlējāt, priecājaties priecādamies ar viņu visi, kas par to bijāt noskumuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Ka zīžat un papilnam dabūjat no viņas iepriecināšanas krūtīm, ka baudāt un atspirdzinājaties no viņas godības pilnuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Jo tā saka Tas Kungs: redzi, Es vedīšu mieru pār to kā upi un pagānu godību kā izplūdušu strautu; tad jūs zīdīsiet, tapsiet klēpī nesti un uz ceļiem mīļi auklēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Tā kā tādu, ko māte iepriecina, tāpat Es jūs iepriecināšu, un Jeruzālemē jūs tapsiet iepriecināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Un jūs to redzēsiet, un jūsu sirds līksmosies, un jūsu kauli zaļos kā zāle. Tad Tā Kunga roka būs zināma visiem Viņa kalpiem, un Viņa ienaidniekiem Viņa dusmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Jo redzi, Tas Kungs nāks ar uguni, un Viņa rati kā viesulis, bargi izgāzt Savu dusmību un rāt ar uguns liesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Jo ar uguni Tas Kungs tiesās un ar Savu zobenu visu miesu, un liels pulks būs Tā Kunga nokauto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Kas svētījās un šķīstās elku dārzos cits par citu un ēd cūkas gaļu un negantību un peles, tie kopā taps izdeldēti, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Bet Es (zinu) viņu darbus un viņu domas! Notiks, ka Es sapulcināšu visas tautas un mēles, un tie nāks un redzēs Manu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Un Es tiem celšu zīmi un sūtīšu no tiem izglābtiem pie pagāniem uz Taršišu, Pulu un Ludu, pie tiem stopu strēlniekiem, pie Tūbala un Javana, uz tālejām salām, kas Manu slavu nav dzirdējuši un Manu godību nav redzējuši, un tie tām tautām darīs zināmu Manu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Un tie atvedīs visus jūsu brāļus no visām tautām Tam Kungam par upuri, uz zirgiem un ratiem un uz nestavām un uz zirgēzeļiem un uz čakliem kamieļiem, pie Mana svētā kalna uz Jeruzālemi, saka Tas Kungs, tā kā Israēla bērni upuri atnes šķīstā traukā uz Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Un arī no tiem Es ņemšu par priesteriem un par levitiem, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Jo tā kā tās jaunās debesis un tā jaunā zeme, ko Es radu, stāvēs Manā priekšā, saka Tas Kungs, tāpat stāvēs arī jūsu dzimums un jūsu vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Un notiks, ka visa miesa nāks ik jaunus mēnešus un ik svētdienas un pielūgs Manā priekšā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Un tie izies ārā un redzēs to nomirušo miesas, kas no Manis atkāpušies. Jo viņu tārps nemirs un viņu uguns neizdzisīs, un tie būs negantība visai miesai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Jeremijas vārdi, kas bija Hilķijas dēls, no tiem priesteriem Anatotā Benjamina zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Uz to Tā Kunga vārds notika Josijas, Amona dēla, Jūda ķēniņa dienās, viņa valdīšanas trīspadsmitā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Tāpat uz viņu notika Jojaķima, Josijas dēla, Jūda ķēniņa dienās, kamēr beidzās Cedeķijas, Josijas dēla, Jūda ķēniņa, vienpadsmitais gads, kad Jeruzālemes ļaudis tapa aizvesti piektā mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Un Tā Kunga vārds notika uz mani un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Pirms Es tevi radīju mātes miesās, Es tevi esmu pazinis, un pirms tu iznāci no mātes miesām, Es tevi esmu svētījis; tautām par pravieti Es tevi esmu licis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Tad es sacīju: ak Kungs, Dievs, redzi, es neprotu runāt, jo es esmu jauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Bet Tas Kungs uz mani sacīja: nesaki, es esmu jauns; jo visur, kurp Es tevi sūtīšu, tev būs iet, un visu, ko Es tev pavēlēšu, tev būs runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Nebīsties no viņiem, jo Es esmu ar tevi un tevi izglābšu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Un Tas Kungs izstiepa Savu roku un aizskāra manu muti, un Tas Kungs sacīja uz mani: redzi, Es lieku Savus vārdus tavā mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Redzi, Es tevi šodien ieceļu pār tautām un pār valstīm, izraut un salauzīt un izdeldēt un izpostīt, tad uztaisīt un dēstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Un Tā Kunga vārds uz mani notika un sacīja: ko tu redzi, Jeremija? Un es sacīju: es redzu zizli (mandeļu koka zaru).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Un Tas Kungs uz mani sacīja: tu esi labi redzējis; jo Es būšu nomodā par Savu vārdu, ka Es to daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Un Tā Kunga vārds notika uz mani otru reiz un sacīja: ko tu redzi? Un es sacīju: es redzu verdošu podu no ziemeļa puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Un Tas Kungs uz mani sacīja: no ziemeļa puses ļaunums gāzīsies pār visiem zemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Jo redzi, Es saucu visas ķēniņu valstu ciltis no ziemeļa puses, saka Tas Kungs, un tie nāks un cels ikviens savu krēslu priekš Jeruzālemes vārtu durvīm un pret visiem viņas mūriem visapkārt un pret visām Jūda pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Un Es spriedīšu Savu sodību pret viņiem par visu viņu ļaunumu, ka tie Mani atstājuši un kvēpinājuši citiem dieviem un klanījušies priekš savu roku darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Tu tad apjoz savus gurnus un celies un runā uz tiem visu, ko Es tev pavēlēšu; neiztrūcinājies priekš viņiem, lai Es tevi neiztrūcināju viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Jo redzi, Es tevi šodien ceļu par stipru pilsētu un par dzelzs stabu un par vara mūri pret visu šo zemi, pret Jūda ķēniņiem, pret viņu lielkungiem, pret viņu priesteriem un pret tās zemes ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Un tie karos pret tevi, bet nekā neiespēs pret tevi; jo Es esmu ar tevi, saka Tas Kungs, tevi izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Un Tā Kunga vārds uz mani notika un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Ej un sauc Jeruzālemes ausīs un saki: Tā saka Tas Kungs: Es tevi pieminēju, kad tu vēl biji mīlīga meita un mīļa brūte, kad tu Man staigāji pakaļ tuksnesī, neapsētā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Israēls bija Tam Kungam svētīts un viņa augļu pirmaji; visi, kas to ēda, tie tapa noziedzīgi, ļaunums nāca pār tiem, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Klausiet Tā Kunga vārdu, Jēkaba nams, visas Israēla nama ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Tā saka Tas Kungs: kādu netaisnību jūsu tēvi pie Manis atraduši, ka tie tālu no Manis atkāpušies un nelietībai dzinušies pakaļ un tapuši nelieši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Un nav sacījuši: kur ir Tas Kungs, kas mūs izveda no Ēģiptes zemes, kas mūs vadīja tuksnesī, tukšā un nestaigātā zemē, izkaltušā un nāves ēnas zemē, tai zemē, kur neviens negāja cauri un kur neviens cilvēks nedzīvoja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Un Es jūs ievedu auglīgā zemē, ēst viņas augļus un viņas labumu. Bet kad jūs nācāt iekšā, tad jūs Manu zemi sagānījāt un darījāt Manu īpašumu par negantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Priesteri nesacīja: kur ir Tas Kungs? Un bauslības mācītāji Mani nepazina un gani atkāpās no Manis, un pravieši mācīja Baāla vārdā un dzinās pakaļ tiem, kas nekā neder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Tāpēc Es vēl ar jums tiesāšos, saka Tas Kungs, un ar jūsu bērnu bērniem Es tiesāšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Jo ceļaties pāri uz Ķitiju salām un lūkojiet un sūtiet uz Ķedaru un ņemiet labi vērā un raugiet, vai tur tā noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Vai kādi pagāni dievus pārmijuši, jebšu tie nav dievi? Bet Mani ļaudis savu godību pārmijuši ar to, kas nekā neder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Iztrūcinājaties par to, debesis, un trīciet un drebiet ļoti, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Jo Mani ļaudis dara divkārtīgu ļaunumu: tie Mani atstāj, to dzīvo ūdens avotu, un izcērt sev akas, cauras akas, kas ūdeni netur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Vai Israēls ir kalps jeb dzimts vergs? Kāpēc tad viņš ir palicis par laupījumu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Jaunie lauvas rūc pret viņu, tie paceļ savas balsis un posta viņa zemi; viņa pilsētas ir sadedzinātas, ka neviens tur nedzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Arī Nofas un Takvanesas bērni tev nogana galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Vai tu pats sev to nedari, ka tu To Kungu, savu Dievu atstāji tanī laikā, kad Viņš tevi veda uz ceļu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Un nu, ko tev iet Ēģiptes ceļu, dzert Šihora ūdeni? Un ko tev iet Asura ceļu, dzert lielās upes ūdeni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Tava blēdība tevi pārmācīs, un tava atkāpšanās tevi sodīs. Tāpēc atzīsti un redzi, ka tas ir ļauni un rūgti, ka tu To Kungu, savu Dievu, atstāji, un Manas bijāšanas nav pie tevis, saka Tas Kungs Dievs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Jo no veciem laikiem tu savu jūgu esi salauzusi un savas saites saraustījusi un saki: es nekalpošu; jo uz visiem augstiem pakalniem un apakš visiem zaļiem kokiem tu skraidīji, maucību dzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Es tevi biju dēstījis par jauku vīna koku, par it taisnu sēklu; kā tad tu Man esi pārvērtusies par sveša vīna koka rūgto meža zaru?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Jo jebšu tu mazgātos ar sārmu un ņemtu daudz ziepes klāt, tomēr tavs noziegums paliek iezīmēts manā priekšā, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kā tu vari sacīt, es neesmu sagānījusies, es Baāliem neesmu dzinusies pakaļ? Redzi savu ceļu tai ielejā, ņem vērā, ko tu esi darījusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Tu čaklā kamieļu māte, kas šurpu turpu skraida, meža ēzeļu māte, ar tuksnesi apradusi, kas savā kārībā elš, - kas viņas karstumu savaldīs? Kas to grib meklēt tam nav jāpiekūst; jaunā mēnesī to var atrast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Neskrej tā, ka tev apavi nokrīt un ka tu noslāpsti. Bet tu saki: tas ir velti, nekā! Jo es mīlēju tos svešos un dzīšos tiem pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Tā kā zaglis kaunas, kad to pienāk, tā Israēla nams taps kaunā, paši, viņu ķēniņi, viņu lielkungi un viņu priesteri un viņu pravieši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Kas uz koku saka: tu esi mans tēvs, - un uz akmeni: tu mani esi dzemdinājis. Jo tie Man piegriež muguru, ne vaigu. Bet nelaimes dienā tie saka: celies un izpestī mūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Kur tad ir tavi dievi, ko tu sev esi taisījusi? Lai tie ceļas, vai tie bēdu laikā tevi var izpestīt; jo cik tev pilsētu, tik tev arī dievu, Jūda!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Kāpēc jūs strīdaties pret Mani? Jūs visi no Manis esat atkāpušies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Jūsu bērnus Es esmu velti sitis, tie to pārmācību nav pieņēmuši. Jūsu zobens ir aprijis jūsu praviešus, kā plēsīgs lauva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Ak tu tauta, ņem jel vērā Tā Kunga vārdu! Vai tad Es Israēlim esmu tuksnesis vai tumša zeme? Kāpēc tad Mani ļaudis saka: mēs iesim savā vaļā, mēs nenāksim vairs pie Tevis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vai jaunava aizmirst savu rotu, vai brūte savu greznumu? Bet Mani ļaudis Mani ir aizmirsuši jau neskaitāmas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Cik brangi tavi ceļi, meklēt mīlestību! Tāpēc tu arī radini savus ceļus uz blēdībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Pat pie tavu drēbju vīlēm atrodas nabagu nenoziedzīgu dvēseļu asinis, ko tu nepienāci kā ielauzušos. Bet par to visu (Es ar tevi tiesāšos).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Un tu saki: es esmu nenoziedzīga, tāpēc lai viņa bardzība no manis nogriežas. Redzi, Es par to tiesāšos ar tevi, ka tu saki: es neesmu grēkojusi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Kam tu tik ļoti steidzies pārgrozīt savu ceļu? Pie Ēģiptes tu tāpat paliksi kaunā, ka tu kaunā palikusi pie Asura.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Arī no turienes tu iziesi, rokas pār galvu sasizdama. Jo Tas Kungs ir atmetis, uz ko paļaujies, un tev ar viņiem labi neizdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Un Viņš saka: kad vīrs atstumj savu sievu, un tā aiziet no viņa un ņem citu vīru, vai tas viņu atkal drīkst pieņemt? Vai tāda zeme netaptu ļoti sagānīta? Bet tu ar daudz drauģeļiem esi maucību dzinusi un griezies atkal pie Manis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Pacel savas acis uz tiem elku kalniem un skaties: kur tu neesi tapusi apsmieta! Tu viņu dēļ esi ceļmalā sēdējusi kā Arābs tuksnesī; tā tu zemi esi sagānījusi ar savu maucību un ar savu blēdību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Tādēļ agrais lietus top aizturēts, un vēlais lietus nenāk. Bet tev ir maukas piere, tu negribi kaunēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Un taču no šī laika tu Mani piesauci: mans Tēvs! Tu esi manas jaunības draugs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Vai Viņš vienmēr dusmosies, vai Viņš bardzību turēs mūžīgi? Redzi, tā tu runā un dari ļaunu cik spēdama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Un Tas Kungs sacīja uz mani ķēniņa Josijas dienās: Vai esi redzējis, ko Israēla cilts atkāpdamās darījusi? Viņa gāja uz ikkatru elka kalnu un apakš visiem zaļiem kokiem un tur maukoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Un Es sacīju, kad tā visu to bija darījusi, atgriezies pie Manis; bet tā neatgriezās; un to redzēja viņas māsa, tā neuzticīgā Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Un Es redzēju, lai gan Es tādēļ, ka tā pārkāpēja Israēla cilts laulību bija pārlauzusi, viņu biju atstājis un tai devis šķiršanās grāmatu, ka tomēr viņas māsa, neuzticīgā Jūda cilts, nebijās, bet nogāja un dzina pati arīdzan maucību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Un ar savas maucības slavu tā ir sagānījusi zemi, jo tā lauza laulību ar akmeņiem un kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Un pie visa tā arī viņas māsa, neuzticīgā Jūda cilts, pie Manis nav atgriezusies no visas savas sirds, bet ar viltu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Un Tas Kungs sacīja uz mani: Israēla cilts, tā atkāpēja, izturas taisnāki, nekā neuzticīgā Jūda cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Ej un sauc šos vārdus pret ziemeļa pusi un saki: atgriezies, Israēla cilts, tu atkāpēja, saka Tas Kungs, tad Es Savu dusmību negriezīšu uz tevi. Jo Es esmu žēlīgs, saka Tas Kungs, Es negribu mūžīgi dusmoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Atzīsti tikai savu noziegumu, ka tu esi apgrēkojusies pret To Kungu, savu Dievu, un šurp turp esi skraidījusi pie svešiem, apakš ikkatra zaļa koka, bet Manai balsij jūs neesat paklausījuši, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Atgriežaties, atkāpēji bērni, saka Tas Kungs, - jo Es jūs esmu precējis un jūs uzņemšu, vienu no pilsētas un divas no cilts, un Es jūs vedīšu uz Ciānu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Un Es jums došu ganus pēc Mana prāta, un tie jūs ganīs ar ziņu un prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Un notiks, kad jūs vairosities un būsiet auglīgi tai zemē tanīs dienās, saka Tas Kungs, tad vairs nesacīs: „Tā Kunga derības šķirsts“un tas arī vairs prātā nenāks un to arī vairs nepieminēs nedz meklēs nedz to atkal uztaisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Tanī laikā Jeruzāleme taps nosaukta: „Tā Kunga goda krēsls“, un pie viņas visi pagāni taps sapulcināti, tādēļ ka Tā Kunga vārds ir Jeruzālemē; un tie nestaigās vairs pēc savas niknās sirds domām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Tanīs dienās Jūda nams ies pie Israēla nama, un tie nāks kopā no ziemeļu zemes uz to zemi, ko es jūsu tēviem esmu devis par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Es gan sacīju: kā Es tevi stādīšu starp tiem bērniem un tev došu jauku zemi, visglītāko mantību starp tautu glītumiem! Un sacīju: „Mans Tēvs!“jūs Mani sauksiet un no Manis neatkāpsities.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Patiesi, tā kā sieva savam draugam ir neuzticīga, tā jūs esat bijuši neuzticīgi pret Mani, jūs no Israēla nama, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Balss taps dzirdēta uz kalniem, Israēla bērnu raudāšana un žēlošanās, ka tie pārgrozījuši savu ceļu un aizmirsuši To Kungu, savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Atgriežaties, atkāpēji bērni, Es jūsu atkāpšanos dziedināšu. Redzi, mēs nākam pie Tevis, jo Tu, Kungs, esi mūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Patiesi, tas ir viltus ar tiem pakalniem un ar visiem tiem kalniem; patiesi, pie Tā Kunga, mūsu Dieva, ir Israēla pestīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Jo tas kauna darbs ir apēdis mūsu tēvu pūliņu no mūsu jaunības, viņu avis un viņu vēršus, viņu dēlus un viņu meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Mēs guļam savā kaunā, un mūsu negods mūs apklāj. Jo mēs esam grēkojuši pret To Kungu, savu Dievu, mēs un mūsu tēvi no savas jaunības līdz šai dienai, un neesam klausījuši uz Tā Kunga, sava Dieva, balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Ja tu atgriezīsies, Israēl, saka Tas Kungs, pie Manis atgriezīsies, un ja tu savas negantības Manā priekšā atstāsi un neskraidīsi apkārt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Un ja tu zvērēsi: „tik tiešām kā Tas Kungs dzīvo!“Ar patiesību, ar tiesu un ar taisnību, tad tautas iekš viņa svētīsies un ar viņu lielīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Jo tā saka Tas Kungs uz Jūda un Jeruzālemes vīriem: ariet sev jaunu zemi un nesējat ērkšķos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Apgraizaties Tam Kungam un atņemat nost savas sirds priekšādu, Jūda vīri un Jeruzālemes iedzīvotāji, ka Mana bardzība neizšaujās kā uguns un nedeg, ka neviens nevar dzēst, jūsu nedarbu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Sludinājiet Jūdā un Jeruzālemē, liekat to dzirdēt un stāstiet, bazūnējat ar bazūni tai zemē, sauciet ar pilnu muti un sakāt: sapulcinājaties un iesim stiprās pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Paceļat karogu uz Ciānu, bēgat, nestāvat. Jo Es atvedu nelaimi no ziemeļa puses un lielu postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Lauva ceļas no sava biezuma, un tautu maitātājs nāk; viņš ir izgājis no savas vietas, tavu zemi darīt tukšu, lai tavas pilsētas top izpostītas, ka neviens tur vairs nedzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Tādēļ apjoziet maisus, žēlojaties un kauciet, jo Tā Kunga bardzības karstums no mums neatstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Tai dienā, saka Tas Kungs, iznīks ķēniņa sirds drošība un lielo kungu sirds drošība, un priesteri izbīsies, un pravieši iztrūcināsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Tad es sacīju: ak Kungs, Dievs! Patiesi, šiem ļaudīm un Jeruzālemei Tu esi ļāvis kļūt lielā viltū, ka sacīja: jums būs miers! Kur tomēr zobens sniedzās līdz pat dvēselei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Tanī laikā sacīs uz šiem ļaudīm un uz Jeruzālemi: sauss vējš nāk no augstiem tuksneša kalniem pret Manu tautu, ne vētīšanas, ne tīrīšanas pēc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Vējš Man nāks, kas stiprāks būs nekā viņi, tad arī Es nesīšu tiesu pret viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Redzi, viņš cēlās kā debesis, un viņa rati ir kā viesulis, viņa zirgi ir čaklāki nekā ērgļi, - ak vai, mums, jo mēs esam postā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Mazgā savu sirdi no ļaunuma, Jeruzāleme, ka topi izglābta; cik ilgi tu savas nelietības domas glabāsi savā sirdī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Jo balss sludina no Dana un ziņo bēdas no Efraīma kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Dariet pagāniem zināmu, redzi, sludinājiet par Jeruzālemi: sargi nāk no tālas zemes, un tie paceļ savu balsi pret Jūda pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Kā sargi ap tīrumu, tā tie būs visapkārt pret viņu, tādēļ ka tā pret Mani cēlusies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Tavs ceļš un tavi nedarbi tev to padara; tā ir tava blēdība, kas tik rūgta, ka tā sniedzās līdz pat tavai sirdij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Ak manas iekšas, manas iekšas! Kā bērnu sāpes man spiežas caur manu sirdi, mana sirds lec iekš manis, es nevaru klusu ciest, jo mana dvēsele dzird bazūnes skaņu un kara troksni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Posts pār postu tiek daudzināts. Jo visa zeme ir postīta, piepeši ir postīti mani dzīvokļi, acumirklī manas teltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Cik ilgi jel man būs redzēt karogu, dzirdēt bazūnes skaņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Tiešām, mani ļaudis ir traki un mani nepazīst; tie ir ģeķīgi bērni un neprātīgi. Tie gan ir gudri, ļaunu darīt, bet labu darīt tie nemāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Es uzlūkoju zemi, un redzi, tā ir tumša un tukša, - un debesi, un viņai nav sava gaišuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Es uzlūkoju kalnus, un redzi, tie dreb, un visi kalni trīc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Es lūkoju, un redzi, neviena cilvēka nav, un visi putni apakš debess ir aizskrējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Es lūkoju, un redzi, auglīgais lauks ir tuksnesis, un visas viņa pilsētas ir salauztas priekš Tā Kunga un priekš Viņa bardzības karstuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Jo tā saka Tas Kungs: visa tā zeme būs postā, tomēr Es to neizpostīšu pavisam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Tādēļ zeme bēdāsies, un debess augšām aptumšosies, jo Es to esmu runājis un apņēmies, un tas Man nebūs žēl, un no tā Es neatkāpšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Visas pilsētas bēgs no jātnieku un strēlnieku trokšņa, tie ies biezos mežos un kāps uz klints kalniem, visas pilsētas taps atstātas, un neviena nebūs, kas tur dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Ko tu tad darīsi, tu postītā? Jebšu tu apģērbsies ar purpuru, jebšu tu izgreznosies ar zelta glītumu, jebšu tu savas acis darīsi jaukas, tad tu tomēr velti izgreznosies. Tie drauģeļi tevi apsmies, tie meklēs tavu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Jo Es dzirdu kā dzemdētājas balsi, vaidēšanu, kā no tās, kas cieš pirmās bērnu sāpes, Ciānas meitas balsi; tā vaid un izpleš savas rokas: ak vai, man! Jo manu dvēseli nomāc slepkavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Ejat apkārt pa Jeruzālemes ielām un pieraugāt jel un ņemiet vērā un meklējiet pa viņas platām ielām, vai jūs varat kādu atrast, vai ir kāds, kas taisnību dara un patiesību meklē, - tad Es viņai piedošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Un jebšu tie visi saka: tik tiešām kā Tas Kungs dzīvo, tomēr tie zvēr nepatiesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Ak Kungs! Vai Tavas acis (neraugās) uz ticību? Tu tos siti, bet tie nejūt sāpes, Tu tos apbēdini, bet tie negrib pieņemt pārmācību; tie savus vaigus apcietinājuši vairāk nekā akmeni, tie negrib atgriezties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Un es sacīju: tiešām, tie ir nabagi, tie ir neprātīgi, tādēļ ka tie nezin Tā Kunga ceļu, sava Dieva tiesu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Es iešu pie tiem lieliem un runāšu ar tiem, jo tie zin Tā Kunga ceļu, sava Dieva tiesu. Bet tie visi kopā to jūgu salauzuši un tās saites saraustījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Tādēļ tos sitīs lauva no meža, un vilks no tuksneša tos postīs, pardelis(leopards) glūn pret viņu pilsētām, visi, kas no turienes iziet, taps saplosīti. Jo viņu grēki ir vairojušies, viņu pārkāpumi augumā auguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kādēļ tad lai Es tevi žēloju? Tavi bērni Mani atstāj un zvērē pie tā, kas dievs nav. Kad Es nu tos esmu pieēdinājis, tad tie lauž laulību un iet pa pulkiem mauku namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Kā baroti ērzeļi tie ceļas agri, ikviens zviedz pēc sava tuvākā sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Vai Man tos nebūs piemeklēt, saka Tas Kungs, jeb vai Manai dvēselei nav jāatriebjās pie tādiem ļaudīm, kā šie?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Kāpjat uz viņas mūriem un samaitājiet tos, bet neizpostiet tos pavisam. Atņemiet viņas stīgas, jo tās nav no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Jo Israēla nams un Jūda nams palikuši visai neuzticīgi pret Mani, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Tie aizliedz To Kungu un saka: viņš nav tas, un mums ļaunums neuzies, mēs neredzēsim nedz zobenu nedz badu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Arī pravieši aizies vējā, jo (Dieva) vārds nav pie viņiem; pašiem tiem tas tā notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Tādēļ saka Tas Kungs, tas Dievs Cebaot: Tāpēc ka jūs šo vārdu sakāt, redzi, Es Savu vārdu tavā mutē darīšu par uguni un šos ļaudis par malku, un tas tos aprīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Redzi, Es atvedīšu pār jums tautu no tālienes, Israēla nams, saka Tas Kungs. Tā ir stipra tauta, veca tauta, tauta, kam valodu tu nesaproti, un nesajēdzi, ko tā runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Viņas bultu maks ir kā atvērts kaps, tie visi ir varoņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Un tā ēdīs tavu pļāvumu un tavu maizi, tā ēdīs tavus dēlus un tavas meitas, tā ēdīs tavas avis un tavus vēršus, tā ēdīs tavu vīna koku un tavu vīģes koku; tavas stiprās pilsētas, uz ko tu paļaujies, tā izpostīs ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Tomēr ir tanīs dienās Es jums pavisam negribu galu darīt, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Un kad jūs sacīsiet: kādēļ Tas Kungs, mūsu Dievs, mums visas šās lietas ir darījis? Tad tev uz viņiem būs sacīt: tā kā jūs Mani esat atstājuši un kalpojuši svešiem dieviem savā zemē, tāpat jūs kalposiet svešiem zemē, kas jums nepieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Sludinājiet to Jēkaba namā, liekat to dzirdēt iekš Jūda un sakāt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Klausiet jel to, ģeķīgie un neprātīgie ļaudis, kam acis ir, un neredz, kam ausis ir, un nedzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Vai jūs Mani negribat bīties? Saka Tas Kungs, vai Manā priekšā negribat drebēt? Es smiltis lieku jūrai par ežu, par mūžīgu robežu, ka par to nebūs iet pāri; jebšu viņas viļņi kust, tad tie tomēr nekā neiespēj, jebšu tie gan kauc, tad tie tomēr pār to neiet pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Bet šiem ļaudīm ir bezdievīga un stūrgalvīga sirds, tie atkāpjas un aiziet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Un nesaka savā sirdī: lai jel bīstamies To Kungu, savu Dievu, kas mums dod lietu agri un vēlu - savā laikā, kas mums pasargā pļaujamā laika noliktās nedēļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Jūsu noziegumi to aizkavē, un jūsu grēki to labumu jums aiztur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Jo starp Maniem ļaudīm atrodas bezdievīgi; tie glūn, kā mednieki mēdz, tie liek valgus un gūsta cilvēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Kā putnu sprosts ir pilns putnu, tā viņu nams ir pilns viltības, tādēļ tie ir palikuši lieli un bagāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Tie ir tauki, tie ir gludeni, no tiem plūst ļaunums, tie neiztiesā tiesu nedz bāriņa lietas, ka šiem būtu labi, un nabagiem tie tiesu neizdod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Vai Man tos nebūs piemeklēt? saka Tas Kungs. Vai Manai dvēselei nebūs atriebties pie tādiem ļaudīm, kā šie?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Briesmīgas un negantas lietas notiek šai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Pravieši māca viltīgi, un priesteri valda pēc sava padoma, un Maniem ļaudīm tas tā patīk. Bet ko tad jūs pēcgalā darīsiet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Bēgat, Benjamina bērni, no Jeruzālemes, bazūnējat Tekoā, ceļat ugunszīmi BetKeremē, jo bēdas rādās no ziemeļa puses un liels posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Es izdeldu Ciānas meitu, to jauko un vēlīgo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Gani uz viņu nāks ar saviem ganāmiem pulkiem, tie uzcels teltis visapkārt ap viņu, tie noganīs ikviens savu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Taisāties uz karu pret viņu, ceļaties, ejam pašā dienas vidū. Ak vai, (bēdas) mums! Jo vakars metās un ēnas paliek garākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Ceļaties, un ejam pašā naktī un izpostīsim viņas jaukos namus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Jo tā saka Tas Kungs Cebaot: nocērtiet kokus un uzmetiet valni pret Jeruzālemi; šī ir tā pilsēta, kas taps piemeklēta. Viņas vidū ir tik netaisnība vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Kā avots izverd savu ūdeni, tā viņa izverd savu ļaunumu. Varasdarbu un postu tur dzird, kaušanās un plēšanās bez mitēšanās ir manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Pieņem mācību, Jeruzāleme, lai Mana dvēsele no tevis nenogriežas, lai Es tevi nedaru par tuksnesi, par zemi bez iedzīvotāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Tā saka Tas Kungs Cebaot: kas atliek no Israēla, to tie otrā reizē nolasīs kā vīna koku. Ņem traukus atkal rokā kā vīna ogu lasītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Uz ko lai es runāju un dodu liecību, ka tie to dzird? Redzi, viņu ausis ir neapgraizītas, ka tie nevar dzirdēt. Redzi, Tā Kunga vārds tiem ir par apsmieklu, pie tā tiem nav labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Tādēļ es esmu pilns Tā Kunga bardzības, ka nevaru valdīties. Izgāz to arī pār bērniem uz ielām, un pār to jaunekļu draudzi kopā, jo vīri un sievas tiks aizņemti, veci un kas mūžu piedzīvojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Un viņu nami taps citiem līdz ar tīrumiem un sievām; jo Es izstiepšu Savu roku pret tās zemes iedzīvotājiem, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Jo visi ir mantas kārīgi, tā mazi kā lieli; tā pravietis kā priesteris, visi dzen viltību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Un tie dziedina Manas tautas vainu kā par nieku, sacīdami: miers, miers! Kur tomēr miera nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Tie krituši kaunā, ka darījuši negantību. Bet tie nemaz nekaunas un neprot kauna. Tāpēc tie kritīs starp tiem kritušiem; kad es tos piemeklēšu, tad tiem būs krist, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Tā saka Tas Kungs: stājaties uz ceļiem un raugāt un vaicājiet pēc tiem senajiem ceļiem, kurš tas labais ceļš, un staigājiet pa to, tad jūs atradīsiet dusu savai dvēselei. Bet tie saka: mēs negribam staigāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Es arī esmu iecēlis sargus pār jums, klausāties uz trumetes skaņu. Bet tie saka: mēs negribam klausīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Tāpēc klausāties, tautas, un ņem vērā, draudze, kas viņu starpā notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Klausies, zeme! Redzi, Es vedīšu ļaunumu pār šiem ļaudīm, viņu padomu augļus, jo tie neklausās uz Manu vārdu, un Manu bauslību tie atmet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Par ko tad Man tas vīraks, kas nāk no Sabas, un tās labās niedres no tālās zemes? Jūsu dedzināmie upuri Man nepatīk, un jūsu kaujamie upuri Man nemīlami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Tādēļ Tas Kungs tā saka: redzi, Es šiem ļaudīm likšu piedauzekļus, un tēvi un bērni kopā pie tiem piedauzīsies, kaimiņš ar kaimiņu ies bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tā saka Tas Kungs: redzi, tauta nāk no ziemeļa zemes, un liela tauta celsies no pasaules malām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Tā nes stopus un šķēpus, tā ir briesmīga un nežēlīga, viņu balss kauc kā jūra, un tie jāj uz zirgiem; tie ir apbruņoti kā karavīri pret tevi, Ciānas meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Kad mēs par viņiem baumas dzirdējām, tad mūsu rokas nogura, bailība mums uzbruka un sāpes kā dzemdētājai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Neizejat laukā un nestaigājat pa ceļu, jo ienaidnieka zobens ir visapkārt par iztrūcināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Ak, mana tauta, apjoz maisu un nometies pelnos, žēlojies kā par vienīgo dēlu, bēdājies gauži, jo postītājs nāk pār mums piepeši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Es tevi esmu iecēlis par pārbaudītāju starp Maniem ļaudīm kā stipru pili, ka tev viņu ceļu būs atzīt un pārbaudīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Tie visi ir tie lielākie atkāpēji un staigā viltībā, tie ir varš un dzelzs, tie visi ir samaitātāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Plēšas ir sadegušas, no viņu uguns nāk tikai svins, kausētājs velti kausējis, jo sārņi nav atšķirti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Tie top nosaukti par atmestu sudrabu, jo Tas Kungs tos ir atmetis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Šis ir tas vārds, kas notika uz Jeremiju no Tā Kunga, kas sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stājies Tā Kunga nama vārtos un sludini tur šo vārdu un saki: klausiet Tā Kunga vārdu, visi no Jūda, kas caur šiem vārtiem ieejat, To Kungu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: dariet taisnus savus ceļus un savus darbus, tad es jums likšu dzīvot šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Nepaļaujaties uz melu vārdiem, kad saka: šis ir Tā Kunga nams, Tā Kunga nams, Tā Kunga nams!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Bet ja patiesi darīsiet labus savus ceļus un savus darbus un nesīsiet tikuši(taisnīgu) tiesu cits citam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Ja neapbēdināsiet svešinieku, bāriņu un atraitni un neizliesiet nenoziedzīgas asinis šinī vietā un nedzīsities pakaļ svešiem dieviem, sev pašiem par postu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Tad Es jums likšu dzīvot šai vietā, tai zemē, ko Es esmu devis jūsu tēviem, mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Redzi, jūs paļaujaties uz melu vārdiem, kas nekam nelīdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Vai tad jums bija zagt, nokaut un laulību pārkāpt un nepatiesi zvērēt un Baālam kvēpināt un dzīties pakaļ citiem dieviem, ko nepazīstat,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Un tad nākt un stāties Manā priekšā šinī namā, kas nosaukts pēc Mana Vārda, un sacīt: mēs esam glābti, šo negantību darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Vai tad šis nams, kas nosaukts pēc Mana Vārda, ir slepkavu bedre jūsu acīs? Redzi, Es to gan esmu redzējis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Jo ejat jel uz Manu vietu, kas bija Šīlo, kur Es Savam vārdam papriekš liku mājot, un lūkojiet, ko Es tur esmu darījis Savu Israēla ļaužu ļaunuma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Un nu tādēļ ka jūs visus šos darbus darāt, saka Tas Kungs, un Es uz jums tikuši(nemitīgi) esmu runājis, bet jūs neesat klausījuši, Es jūs esmu aicinājis, bet jūs neesat atbildējuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Tad Es šim namam, kas pēc Mana Vārda nosaukts, uz ko jūs paļaujaties, un pie šās vietas, ko Es jums un jūsu tēviem esmu devis, tāpat darīšu, kā esmu darījis Šīlo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Un Es jūs atmetīšu no Sava vaiga, tā kā esmu atmetis visus jūsu brāļus un visu Efraīma dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Tu tad nelūdz priekš šiem ļaudīm un nenes Manā priekšā par viņiem ne piesaukšanu ne lūgšanu, un neaizlūdz pie Manis, jo Es tevi neklausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Vai tu neredzi, ko tie dara Jūda pilsētās un Jeruzālemes ielās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Bērni salasa malku, un tēvi kurina uguni, un sievas mīca mīklu un taisa raušus debess ķēniņienei un upurē dzeramus upurus citiem dieviem, Mani kaitināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Bet vai tad tie Mani apkaitina? saka Tas Kungs. Vai tie to (nedara) sev pašiem par kaunu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Tādēļ tā saka Tas Kungs Dievs: redzi, Mana dusmība un Mana bardzība izgāzīsies pār šo vietu, pār cilvēkiem un lopiem un meža kokiem un zemes augļiem un degs un neizdzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: liekat savus dedzināmos upurus klāt pie saviem kaujamiem upuriem un ēdat gaļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Jo jūsu tēviem, kad Es tos izvedu no Ēģiptes zemes, Es neesmu ne teicis ne pavēlējis par dedzināmiem upuriem nedz kaujamiem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Bet šo vārdu Es tiem esmu pavēlējis un sacījis: klausiet Manu balsi, tad Es jums būšu par Dievu un jūs Man būsiet par ļaudīm, un staigājiet pa visiem tiem ceļiem, ko Es jums pavēlēšu, lai jums labi klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Bet tie nav klausījuši nedz savas ausis atgriezuši, bet staigājuši pēc savas ļaunās sirds padoma un prāta, un Man ir pagriezuši muguru un ne vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'No tās dienas, kad jūsu tēvi izgājuši no Ēģiptes zemes līdz šai dienai, Es vienā sūtīšanā pie jums esmu sūtījis visus Savus kalpus, tos praviešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Bet tie Mani nav klausījuši, nedz savas ausis atgriezuši, bet bijuši stūrgalvīgi, niknāki turēdamies nekā viņu tēvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Tu gan visus šos vārdus uz viņiem runāsi, bet tie tevi neklausīs, tu tos gan aicināsi, bet tie neatbildēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Tāpēc saki uz tiem: šie ir tie ļaudis, kas Tā Kunga, sava Dieva, balsi neklausa un mācību nepieņem. Patiesība bojā gājusi un iznīkusi no viņu mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Nocērp savas galvas greznumu un met to nost, un raudi gauži uz kailiem kalniem, jo Tas Kungs atmetis un atstājis šo Savas dusmības cilti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Jo Jūda bērni ir darījuši, kas ļauns Manās acīs, saka Tas Kungs. Tie savus negantos elkus likuši tai namā, kas nosaukts pēc Mana Vārda, to sagānīdami;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Un ir uzcēluši Tovetes altārus Ben-Inoma ielejā, sadedzināt savus dēlus un savas meitas ar uguni, ko Es neesmu pavēlējis, un kas nav nācis Manā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Tādēļ redzi, nāks dienas, saka Tas Kungs, ka to vairs nesauks par Toveti un Ben-Inoma ieleju, bet par slepkavu ieleju, un Tovetē apbedīs, jo citur vietas nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Un šo ļaužu miroņi būs par barību putniem apakš debess un zvēriem virs zemes, un neviens tos neaizdzīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Un Es darīšu, ka Jūda pilsētās un Jeruzālemes ielās mitēsies prieka balss un līksmības balss, brūtgāna balss un brūtes balss; jo tā zeme būs postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Tanī laikā, saka Tas Kungs, Jūda ķēniņu kaulus un viņu lielkungu kaulus un viņu priesteru kaulus un praviešu kaulus un Jeruzālemes iedzīvotāju kaulus izmetīs no viņu kapiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Un izmētās pret sauli un pret mēnesi un pret visu debess pulku, ko tie mīlējuši un kam tie kalpojuši un kam tie dzinušies pakaļ un ko tie meklējuši un ko tie pielūguši. Ne tos sakrās, ne tos apraks, tie būs par mēsliem zemes virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Un nāvi vēlēsies dzīvības vietā visi atlikušie, kas no šās niknās cilts atliks visās malās, kurp Es tos atlikušos būšu aizdzinis, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Un saki uz tiem: tā saka Tas Kungs: kad krīt, vai atkal neceļas: kad nogriežas, vai atkal negriežas atpakaļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Kāpēc tad šie Jeruzālemes ļaudis atkāpjas bez mitēšanās atkāpdamies? Tie stipri turas pie viltus un liedzās atgriezties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Es esmu vērā ņēmis un dzirdējis: tie runā, kas nepareizi; neviena nav, kam būtu žēl savas blēdības, kas sacītu: ko esmu darījis? Visi atkāpjas, skriedami kā traks ērzelis kas karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Stārķis apakš debess zin savus laikus, un ūbele un dzērve un bezdelīga ņem vērā savu atnākšanas laiku, bet mani ļaudis neatzīst Tā Kunga tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kā tad jūs sakāt: mēs esam gudri, un Tā Kunga bauslība ir pie mums? Tiešām, redzi, rakstu mācītāju viltīgie raksti to pārvērtuši par meliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Gudrie top apkaunoti, iztrūcināti un sagūstīti; redzi, Tā Kunga vārdu tie ir atmetuši, kāda gudrība tad tiem ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Tādēļ Es viņu sievas došu citiem, viņu tīrumus svešiem mantiniekiem; jo mazi un lieli, visi kāri pēc mantas; pravietis un priesteris, abi dzen viltību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Un tie dziedina Manas tautas vainu kā par nieku un saka: miers! Miers! Kur tomēr miera nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Tie ir tapuši kaunā, tāpēc ka darījuši negantību, bet tie nemaz nekaunas un kauna neprot; tādēļ tie kritīs starp tiem kritušiem, savas piemeklēšanas laikā tie gāzīsies pie zemes, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Es tos rautin aizraušu, saka Tas Kungs, ka ķekari nepaliks pie vīna koka nedz vīģes pie vīģes koka, ir lapas nokritīs, un Es tiem dodu, kas pār tiem nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Ko tad kavējamies? Pulcējaties un iesim stiprās pilsētās un meklēsim tur galu! Jo Tas Kungs, mūsu Dievs, mums nolicis galu un mūs dzirdinājis ar žulti, tāpēc ka esam apgrēkojušies pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Gaida mieru, bet nav labuma, dziedināšanas laiku, bet redzi, izbailes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'No Dana jau dzirdama viņa zirgu* šņākšana; visa zeme dreb no viņa ērzeļu zviegšanas skaņas; tie nāk un noēd zemi ar viņas pilnumu, pilsētas un kas tur dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Jo redzi, Es sūtu jūsu starpā čūskas un odzes, pret ko nepalīdz vārdošana, - tās jūs kodīs, saka Tas Kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Kas mani iepriecinās skumjās! Mana sirds man gurst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Redzi, Manas tautas kliegšanas balss skan no tālas zemes: vai tad Tas Kungs vairs nav Ciānā? Vai viņas ķēniņš tur nav? Kāpēc tie Mani apkaitinājuši ar saviem dievekļiem, ar svešām nelietībām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Pļauja ir pagājusi, augļu laiks pagalam, bet mēs neesam atpestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Es esmu satriekts savas tautas posta dēļ, es esmu noskumis, izbailes mani sagrābušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Vai tad zāļu nav Gileādā? Vai tur nav ārsta? Kāpēc tad manas tautas sērga nav dziedināta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Ak kaut manā galvā jel būtu ūdens un manas acis taptu par asaru avotiem, tad es dienām naktīm apraudātu savas tautas nokautos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Ak kaut man tuksnesī būtu ceļavīra mājas vieta, tad es savus ļaudis atstātu un no tiem aizietu, jo tie visi ir laulības pārkāpēji, blēžu draudze.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Tie uzvelk savu mēli kā stopu uz meliem un ne uz patiesību, tie top vareni virs zemes, tie dodas no ļaunuma uz ļaunumu, bet Mani tie nepazīst, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Sargājaties ikviens no sava drauga, un nepaļaujaties ne uz savu brāli; jo brālis brāli krāpj, un draugs staigā draugu aprunādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Cits pret citu dzen viltību un nerunā patiesību, tie māca savu mēli melot, tie nopūlējās netaisnību darīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Tava mājas vieta ir pašas viltības vidū, caur viltību tie liedzās Mani pazīt, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Tādēļ, tā saka Tas Kungs Cebaot: redzi, Es tos kausēšu un pārbaudīšu, - jo kā lai Es citādi daru Savas tautas priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Viņu mēle ir nāvīga bulta, tā runā viltu, ikviens ar savu muti runā par mieru ar savu tuvāku, bet savā sirdī tam liek valgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Vai Man tos nebūs piemeklēt? saka Tas Kungs. Vai Manai dvēselei nebūs atriebties pie tādiem ļaudīm, kā šie?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Man jāsāk raudāšana un kaukšana par kalniem un raudu dziesma par ganībām tuksnesī; jo tās ir nodedzinātas, ka neviens tur nestaigā, un ganāmā pulka balsi tur nedzird; putni apakš debess un lopi ir aizskrējuši un aizgājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Un Jeruzālemi Es likšu par akmeņu kopu un par mājokli tuksneša zvēriem, un Jūda pilsētas Es darīšu par postažu bez iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kas ir tāds gudrs vīrs, kas to saprot? Un uz ko Tā Kunga mute runājusi, ka tas to var pasludināt? Kādēļ zeme iet bojā un izdeg kā tuksnesis, kur neviens nestaigā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Un Tas Kungs sacīja: tādēļ ka tie atstājuši Manu bauslību, ko Es tiem esmu licis priekšā, un nav klausījuši Manu balsi nedz pēc tās staigājuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Bet staigājuši pēc savas sirds stūrgalvības un Baāliem pakaļ, kā viņu tēvi tos mācījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Tādēļ, tā saka Tas Kungs Cebaot, Israēla Dievs: Redzi, Es šos ļaudis ēdināšu ar vērmelēm un tos dzirdināšu ar žultīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Un Es tos izkaisīšu starp tautām, ko tie nav pazinuši nedz viņu tēvi, un sūtīšu zobenu tiem pakaļ, tiekams Es tos būšu izdeldējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Tā saka Tas Kungs Cebaot: ņemiet to vērā un aicinājiet raudu sievas, lai tās nāk, un sūtat pēc tām gudrām sievām, lai tās atnāk,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Un steigšus sāk par mums raudāšanu, ka mūsu acis tek asarām un mūsu acu plakstiņi plūst ūdenim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Jo kaukšanas balss dzirdama no Ciānas: ak! Kā esam postīti, ļoti kaunā likti, jo mēs atstājam zemi, jo tie apgāzuši mūsu mājokļus!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Klausiet tad Tā Kunga vārdu, sievas, un lai jūsu auss uzņem viņa mutes vārdu, un mācat savām meitām raudu dziesmas, un viena otrai lai māca gaudas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Jo nāve kāpj iekšā pa mūsu logiem, tā nāk mūsu jaukos namos, nokaut bērniņus pa ielām un jaunekļus pa gatvēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Runā, tā saka Tas Kungs: miroņu miesas gulēs kā mēsli uz tīruma un kā kūļi aiz pļāvēja, ko neviens nesaņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Tā saka Tas Kungs: gudrais lai nelielās ar savu gudrību, stiprais lai nelielās ar savu stiprumu, bagātais lai nelielās ar savu bagātību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Bet kas grib lielīties, tas lai lielās ar to, ka viņš Mani pazīst un zin, ka Es esmu Tas Kungs, kas dara žēlastību, tiesu un taisnību virs zemes; jo pie tām Man ir labs prāts, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Redzi, nāk dienas, saka Tas Kungs, ka Es piemeklēšu apgraizītos līdz ar neapgraizītiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Ēģiptes zemi un Jūdu un Edomu un Amona bērnus un Moabu un visus, kam apcirptas bārdas, kas tuksnesī dzīvo. Jo visi pagāni ir neapgraizīti, bet Israēla namam ir neapgraizīta sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Klausiet to vārdu, ko Tas Kungs uz jums runā, Israēla nams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Tā saka Tas Kungs: nemācaties pagānu ceļu un neizbīstaties no debess zīmēm, jebšu pagāni no tām izbīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Jo pagānu likumi ir nelietība. Jo tas ir koks, mežā cirsts, darbs no amatnieka rokām ar cirvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Viņš to izgrezno ar sudrabu un ar zeltu, stiprina ar naglām un ar āmuriem, ka nešaubās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Tie ir kā tēsti stabi un nerunā, tie top apkārt nēsāti, jo paši nestaigā. Nebīstaties no viņiem, jo tie nedara ļauna, arī labu darīt tie nevar.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Bet nu neviena nav, kā Tu, Kungs; Tu esi liels, un liels ir Tavs vārds ar spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kas Tevi nebītos, Tu tautu Ķēniņ? Jo tas Tev nākas, tādēļ ka starp visiem pagānu gudriem un visās viņu valstīs neviena tāda nav, kā Tu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Tiešām, tie visi kopā ir neprātīgi un ģeķīgi. Jo viņu mācība ir nelietība, tie ir koks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Izkalts sudrabs top atvests no Taršiša un zelts no Ūpaza, kalēja darbam un kausētāja rokām; pazilas drēbes un purpurs ir viņu apģērbs; tie visi ir amatnieku darbs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Bet Tas Kungs ir patiesi Dievs, Viņš ir dzīvs Dievs un mūžīgs Ķēniņš. No Viņa bardzības zeme dreb, un tautas Viņa dusmību nevar panest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Tā jums uz tiem būs sacīt: tiem dieviem, kas debesi un zemi nav darījuši, tiem būs iet bojā no zemes un no šīs pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Viņš zemi radījis caur Savu spēku un pasauli dibinājis caur Savu gudrību un debesis izpletis caur Savu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Kad Viņa balss atskan, tad ūdeņi krāc debesīs, un Viņš liek miglai celties no zemes galiem, Viņš dara zibeņus ar lietu un liek vējam nākt no Viņa alām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Visi cilvēki paliek stulbi bez saprašanas, visi kausētāji top kaunā ar saviem tēliem, jo ko tie lej, ir meli, un dvašas tur nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Tie ir nelietība un apsmejams darbs; piemeklēšanas laikā tie iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Tā kā šie nav Jēkaba daļa, jo Viņš ir visu lietu Radītājs, un Israēls ir Viņa mantības cilts, - Kungs Cebaot ir Viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Pacel savu paunu no zemes, tu kas sēdi spaidos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Jo tā saka Tas Kungs: redzi, šoreiz Es metu projām tās zemes iedzīvotājus kā ar lingu, un Es tos spaidīšu, ka tiek atrasti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Vai manu bēdu! Mana vaina ir sāpīga! Bet es saku: tās ir gan sāpes, bet man tās jāpanes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mana telts ir postīta, un visas manas virves ir sarautas; mani bērni no manis aizgājuši un to vairs nav. Neviena nav, kas manu dzīvokli uztaisa un manas teltis uzceļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Jo tie gani palikuši stulbi un nav To Kungu meklējuši, tādēļ tiem nav labi izdevies, bet viss viņu ganāmais pulks izklīdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Klau, ko dzird! Redzi, nāk liels troksnis no ziemeļa zemes, postā likt Jūda pilsētas un darīt par mājokli tuksneša zvēriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Es zinu, ak Kungs, ka cilvēka ceļš pie viņa paša nestāv; tas nestāv pie vīra, kā lai staigā, kurp tas lai sper savus soļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Pārmāci mani, ak Kungs, bet ar žēlastību, ne savā bardzībā, ka Tu mani neiznīcini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Izgāz Savu dusmību pār tiem pagāniem, kas tevi nepazīst, un pār tām ciltīm, kas Tavu vārdu nepiesauc. Jo tie Jēkabu aprijuši, tie viņu apēduši un viņu izdeldējuši un viņa druvas izpostījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Šis ir tas vārds, kas no Tā Kunga tā notika uz Jeremiju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Klausiet šās derības vārdus un runājiet uz Jūda vīriem un uz Jeruzālemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Un saki uz tiem: tā saka Tas Kungs, Israēla Dievs: nolādēts lai ir tas cilvēks, kas neklausa šās derības vārdiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Ko Es jūsu tēviem esmu pavēlējis, kad tos izvedu no Ēģiptes zemes, no tā dzelzs cepļa, un sacīju: klausiet Manu balsi, un dariet to, tā kā Es jums pavēlu, tad jūs Man būsiet par ļaudīm, un Es jums būšu par Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Lai Es to zvērestu piepildu, ko Es jūsu tēviem esmu zvērējis, viņiem dot zemi, kur piens un medus tek, tā kā tas šodien ir. Tad es atbildēju un sacīju: Āmen, Kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Un Tas Kungs sacīja uz mani: izsauc visus šos vārdus pa Jūda pilsētām un pa Jeruzālemes ielām, un saki: klausiet šās derības vārdus un dariet tos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Jo Es jūsu tēviem skaidri esmu apliecinājis tai dienā, kad tos izvedu no Ēģiptes zemes, līdz šai dienai, tikuši(vienmēr) liecību dodams, un sacīju: klausiet Manu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Bet tie nav klausījuši nedz savas ausis atgriezuši, bet staigājuši ikviens pēc savas niknās sirds stūrgalvības. Tāpēc Es liku pār tiem nākt visiem šīs derības vārdiem, ko Es pavēlēju darīt, un tie nav darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Un Tas Kungs uz mani sacīja: sabiedrība rodas starp Jūda vīriem un Jeruzālemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Tie ir atgriezušies pie savu vectēvu noziegumiem, kas liegušies Maniem vārdiem klausīt, un citiem dieviem dzinušies pakaļ, tiem kalpot. Israēla nams un Jūda nams pārkāpuši Manu derību, ko Es ar viņu tēviem esmu cēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Tādēļ tā saka Tas Kungs: redzi Es pār tiem vedīšu ļaunumu, no kā tie nevarēs izbēgt; kad tie tad uz Mani brēks, tad Es tos neklausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Un Jūda pilsētas un Jeruzālemes iedzīvotāji noies un brēks uz tiem dieviem, kam tie kvēpinājuši; bet pestīt tie tos neatpestīs viņu nelaimes laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Jo cik tev pilsētu, Jūda, tik arī tavu dievu, un cik Jeruzālemē ielu, tik altāru jūs esat cēluši par kaunu, altārus Baālam kvēpināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Tu tad nelūdz par šiem ļaudīm un nenes par tiem piesaukšanu un lūgšanu, jo Es neklausīšu, kad tie Mani piesauks par savu nelaimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Kas Manam mīļam ir Manā namā, kur tā top darīts, tāda blēdība no tāda pulka! Vai solījumi un upura gaļa atņems nelaimi no tevis? Tad tu varētu gavilēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Tas Kungs tevi nosauca par zaļu eļļas koku, kas jauks un auglīgs, bet nu Viņš tam uguni pielicis ar lielu trokšņa skaņu, un viņa zari lūst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Jo Tas Kungs Cebaot, kas tevi dēstījis, tas par tevi nospriedis nelaimi, Israēla nama un Jūda nama niknuma dēļ, ko tie savā starpā dara, Mani apkaitināt, Baālam kvēpinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Nu Tas Kungs man to ir zināmu darījis, un es to zinu; Tu man esi rādījis viņu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Un es biju tā kā lēna avs, ko ved pie kaušanas, un es nezināju, ka tie pret mani bija domājuši tādas domas: lai to koku ar viņa augļiem maitājam un viņu izdeldam no dzīvo zemes, ka viņa vārdu vairs nepieminētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Bet Tu, Kungs Cebaot, taisnais soģi, kas pārbaudi īkstis un sirdis, liec man redzēt Tavu atriebšanu pie viņiem, jo Tev es esmu pavēlējis savu tiesas lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Tādēļ tā saka Tas Kungs pret Anatotas vīriem, kas tavu dvēseli meklē un saka: nesludini pret mums Tā Kunga Vārdā, ja negribi mirt caur mūsu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Tādēļ tā saka Tas Kungs Cebaot: redzi, Es tos piemeklēšu un tiem jaunekļiem būs mirt caur zobenu, viņu dēli un viņu meitas mirs badā, ka no tiem nekas neatliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Jo nelaimei Es likšu nākt pār Anatotas vīriem viņu piemeklēšanas gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Tu, ak Kungs, palieci taisns, kad es ar Tevi gribētu tiesāties; tomēr par tiesu ar Tevi gribu runāt. Kāpēc bezdievīgiem ceļš labi izdodas, un visiem, kas dara viltu, labi klājās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Tu tos esi dēstījis, un tie ir iesakņojušies un aug un nes augļus; Tu gan esi tuvu viņu mutei, bet tālu no viņu sirdīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Bet mani, ak Kungs, Tu pazīsti, mani Tu redzi un pārbaudi manu sirdi, kāda tā ir tavā priekšā. Aizrauj viņus kā avis uz kaušanu un nolieci tos uz nokaušanas dienu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Cik ilgi tad zeme lai bēdājās un zāle visur laukā lai savīst? Iedzīvotāju blēdības dēļ lopi un putni iet bojā. Jo tie saka: viņš neredz, kā mums pēcgalā klāsies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Kad tu skrēji ar kājniekiem un tie tevi nokausēja, kā tad tu varētu skrieties ar zirgiem? Un ja tu jūties drošs miera zemē, ko tad tu darīsi Jardānes varenos biezumos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Jo, pat tavi brāļi un tavs tēva nams ir neuzticīgi pret tevi un sauc pilnā balsī tev pakaļ. Neuzticies tiem, kad tie laipnīgi ar tevi runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Es Savu namu esmu atstājis un atmetis Savu mantas tiesu un to, ko Mana dvēsele mīļo, nodevis viņa ienaidniekiem rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mana mantība Man ir palikusi kā lauva mežā; tā savu balsi pret Mani pacēlusi, tādēļ Es to esmu ienīdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mana mantība Man ir kā raibs putns, kam putni uzkrīt no visām pusēm. Nāciet, sapulcinājaties, visi zvēri laukā, nāciet un ēdiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Daudz gani maitājuši Manu vīna dārzu, tie ir saminuši Manu tīrumu, Manu jauko tīrumu tie darījuši par tukšu postažu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Tas ir postā, izpostīts tas bēdājās Manā priekšā; visa zeme ir postīta, jo neviena nav, kam sirds to ņem vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Pa visiem tuksneša kalniem postītāji nākuši, jo Tā Kunga zobens rij no viena zemes gala līdz otram, un miera nav nevienai miesai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Tie sēj kviešus, bet ērkšķus tie pļauj, tie gan grūti strādā, bet nepelna nekā. Tā tad topat kaunā ar saviem augļiem caur Tā Kunga karsto bardzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Tā saka Tas Kungs par visiem maniem nikniem kaimiņiem, kas aizskar to mantību, ko Es esmu devis mantot Saviem Israēla ļaudīm: Es tos izraušu no viņu zemes un Jūda namu Es izraušu no viņu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Un notiks, kad Es tos būšu izrāvis, tad Es atkal par tiem apžēlošos, Es tos vedīšu atpakaļ, ikkatru savā daļā un ikkatru savā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Un ja tie Manu ļaužu ceļu tikuši(rūpīgi) mācīsies un zvērēs pie Mana Vārda: „Tik tiešām kā Tas Kungs dzīvo!“Tā kā tie Manus ļaudis ir mācījuši pie Baāla zvērēt, - tad tie taps uzņemti Manu ļaužu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Bet ja tie neklausīs, tad Es šo tautu izraušu un to pavisam izdeldēšu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Tā Tas Kungs uz mani sacījis: ej un pērc sev nātnu(linu) jostu un jozies ar to ap saviem gurniem, bet neliec to ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Tad es pirku jostu pēc Tā Kunga vārda un apjozos ar to ap saviem gurniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Un Tā Kunga vārds notika uz mani otru reiz un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Ņem to jostu, ko tu esi pircis, kas ap taviem gurniem, un celies, ej pie Eifrates un apslēp to tur kādā klints plaisumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Un es gāju un to apslēpu pie Eifrates, kā Tas Kungs man bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Tad pēc ilgāka laika Tas Kungs uz mani sacīja: celies, ej pie Eifrates un ņem to jostu no turienes, ko Es tev esmu pavēlējis, tur apslēpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Tad es gāju pie Eifrates un raku un ņēmu to jostu no tās vietas, kur to biju apslēpis, un redzi, tā josta bija maitāta un nederēja vairs nekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Tad Tā Kunga vārds uz mani notika un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Tā saka Tas Kungs: tāpat Es maitāšu Jūda lepnību un Jeruzālemes lielo lepnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Šie niknie ļaudis, kas negrib klausīt Manus vārdus un staigā pēc savas sirds stūrgalvības un dzenās citiem dieviem pakaļ, viņiem kalpot un priekš viņiem klanīties, tie būs kā šī josta, kas nekam vairs neder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Jo kā josta pieglaužas pie vīra gurniem, tā Es visu Israēla namu un visu Jūda namu esmu sev pieglaudījis, saka Tas Kungs, ka tie Man būtu par ļaudīm un par vārdu un par slavu un par godu, bet tie nav klausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Tāpēc saki uz tiem šo vārdu: tā saka Tas Kungs, Israēla Dievs: visi trauki top ar vīnu pildīti. Kad tie uz tevi sacīs: Vai tad mēs to nezinām, ka visi trauki ar vīnu top pildīti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Tad tev uz viņiem būs sacīt: tā saka Tas Kungs: redzi, visus šās zemes iedzīvotājus, un ķēniņus, kas uz Dāvida goda krēsla sēž, un priesterus un praviešus un visus Jeruzālemes iedzīvotājus Es pildīšu ar reibumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Un Es tos sadauzīšu vienu pret otru, tēvus un bērnus, visus kopā, saka Tas Kungs, Es nesaudzēšu un netaupīšu, nedz apžēlošos, ka Es tos neizdeldētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Klausiet un ņemiet vērā, nelepojaties, jo Tas Kungs to runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dodiet Tam Kungam, savam Dievam, godu, pirms tumsa metās, un pirms jūsu kājas piedauzās pie krēslības kalniem, un jūs uz gaismu gaidāt, bet Viņš to darīs par nāves ēnu un pārvērtīs par tumsību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Bet kad jūs to neklausīsiet, tad mana dvēsele raudās slepeni tādas lepnības dēļ. Un manas acis izlies gaužas asaras un asarām plūdīs, tādēļ ka Tā Kunga ganāmais pulks top aizvests cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Saki uz ķēniņu un uz ķēniņieni: zemojaties, sēžaties zemē, jo viss jūsu galvas glītums, jūsu godības kronis, ir nokritis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Pilsētas pret dienvidiem ir aizslēgtas, un nav, kas tās atver, visa Jūda cilts ir aizvesta, tā ir pavisam aizvesta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Paceļat savas acis un raugāt, kas nāk no ziemeļiem. Kur ir tas ganāmais pulks, kas tev bija dots, tavas godības avis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Ko tu sacīsi, kad Viņš tev cels par galvu tos, ko tu sev pielabinājis par draugiem? Vai tad tevi sāpes nesagrābs, kā sievu, kas dzemdē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Kad tu tad savā sirdī sacīsi: Kāpēc man tas notiek? Tavu lielo noziegumu dēļ tavu drēbju vīles ir atsegtas un tavas kājas piesmietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Vai Moru vīrs var savu ādu pārvērst jeb pardelis(leopards) savus raibumus? Tad arī jūs varētu labu darīt, kad esat ieraduši ļaunu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Tādēļ Es tos gribu izkaisīt kā pelavas, kas izput no tuksneša vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Šī būs tava daļa, tā tiesa, ko Es tev esmu nospriedis, saka Tas Kungs, tāpēc ka tu mani esi aizmirsusi un paļāvusies uz meliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Tad arī Es tavas drēbju vīles atsegšu pār tavu vaigu, ka tavs kauns top redzams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Jo Es esmu redzējis tavu laulības pārkāpšanu, tavu nešķīsto iekārošanu, tavu neganto maukošanu uz elku kalniem, laukā tavu negantību. Ak vai, tev, Jeruzāleme! Vai tad tu negribi palikt šķīsta, cik ilgi tas vēl būs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Šis ir Tā Kunga vārds, kas noticis uz Jeremiju, par to bula(sausuma) laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Jūda bēdājās, un viņa vārti tvīkst, sērodamies tie guļ pie zemes, un Jeruzālemes brēkšana kāpj uz augšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Un viņu cienīgie sūta savus zemos pēc ūdens; tie nāk pie akām, neatrod ūdens, atgriežas ar saviem traukiem tukšā, top kaunā un noskumst un apsedz savu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Tāpēc ka zeme iztrūkusies, ka lietus nav virs zemes, arāji ir nokaunējušies, apsedz savu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Pat stirna laukā atnesās un atstāj (savus bērnus), tāpēc ka zāles nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Un meža ēzeļi stāv pakalnos un tvarsta vēju, kā tuksneša vilki; viņu acis pamirst, tāpēc ka zāles nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ak Kungs, jebšu mūsu noziegumi liecina pret mums, tomēr palīdzi Tava Vārda dēļ, jo mūsu atkāpšanās ir liela, pret Tevi esam grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Ak Israēla cerība, viņa Pestītājs bēdu laikā, kāpēc Tu gribi būt kā svešinieks šai zemē, jeb kā ceļavīrs, kas nāk, tik palikt par nakti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Kāpēc Tu gribi būt kā vīrs, kas iztrūcies, kā varonis, kas nevar glābt? Tomēr Tu Kungs esi mūsu vidū, un mēs pēc Tava Vārda esam nosaukti, neatstājies no mums!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Tā saka Tas Kungs uz šiem ļaudīm: tie mīļo šurp un turp skraidīt un nevalda savas kājas, tāpēc Tam Kungam nav labs prāts pie tiem. Nu Viņš pieminēs viņu noziegumu un piemeklēs viņu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Un Tas Kungs sacīja uz mani: nelūdz par šiem ļaudīm, tiem par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Jebšu tie gavē, taču Es viņu brēkšanu neklausīšu, un jebšu tie upurē dedzināmus upurus un ēdamus upurus, tad Man tomēr pie tiem nebūs labs prāts, bet caur zobenu un caur badu un caur mēri Es tos izdeldēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Tad es sacīju: ak Kungs, Dievs! Redzi, pravieši saka uz tiem: jūs neredzēsiet zobenu, un bads jūs neaizņems, bet es jums došu īstenu mieru šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Un Tas Kungs sacīja uz mani: tie pravieši sludina melus Manā Vārdā, Es tos neesmu sūtījis nedz tiem pavēlējis nedz uz tiem runājis. Tie jums sludina melu parādīšanu un zīlēšanu un nelietību un savu pašu sirds viltību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Tādēļ saka Tas Kungs tā par tiem praviešiem, kas Manā Vārdā sludina, ko Es neesmu sūtījis, un kas saka, zobens nebūs nedz bads šinī zemē: caur zobenu un caur badu šie pravieši taps aprīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Un tie ļaudis, kam šie sludina, gulēs uz Jeruzālemes ielām aiz bada un zobena, un nebūs, kas tos aprok ar viņu sievām un ar viņu dēliem un ar viņu meitām; tā Es viņu ļaunumu izgāzīšu pār viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Tāpēc saki uz tiem šo vārdu: manas acis plūst asarām dienās un naktīs un nemitās; jo tā jaunava, manu ļaužu meita, ir satriekta ar lielu triecienu, ar varen lielu mocību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Kad es izeju laukā, tad redzi, tur ir zobena nokauti, kad es nāku pilsētā, tad redzi, tur guļ badu miruši. Un pravieši un priesteri iet apkārt pa zemi, ko tie nepazīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Vai tad Tu Jūdu pavisam esi atmetis, jeb vai Tava dvēsele Ciānu apnikusi? Kāpēc Tu mūs esi sitis, ka mums dziedināšanas vairs nav? Gaida uz mieru, bet labuma nav, un uz dziedināšanas laiku, bet redzi, izbailes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Kungs, mēs atzīstam savu bezdievību un savu tēvu noziegumu, ka pret tevi esam grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Neatmet mūs Tava Vārda dēļ, un lai Tavs godības krēsls netop nievāts; piemini un neiznīcini Savu derību ar mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Vai ir starp pagānu elkiem, kas liek lietum līt, jeb vai debess var dot lietu? Vai Tu tas neesi, ak Kungs, mūsu Dievs? Tāpēc mēs uz Tevi gribam gaidīt, jo Tu dari visas šīs lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Un Tas Kungs sacīja uz mani: jebšu pat Mozus un Samuēls Manā priekšā stāvētu, tomēr Man nebūtu labs prāts pie šiem ļaudīm; dzen tos nost no Mana vaiga, lai tie iet projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Un kad tie uz tevi sacīs: kurp mums būs iet? Tad saki uz tiem: tā saka Tas Kungs: kam nāve uziet, tam lai uziet, un kam zobens uziet, tam lai uziet, un kam bads uziet, tam lai uziet, un kam cietums uziet, tam lai uziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Jo Es tos piemeklēšu ar četrkārtīgām mocībām, saka Tas Kungs: ar zobenu tos nokaudams un ar suņiem tos raustīdams un ar putniem apakš debess un ar zemes zvēriem, ka tie top aprīti un izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Un Es tos nodošu uz vārdzināšanu visās pasaules valstīs, Manasus, Hizkijas dēla, Jūda ķēniņa dēļ, par to, ko viņš Jeruzālemē darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Jo kas tevi saudzēs, Jeruzāleme, jeb kas tevi žēlos, jeb kas noies, vaicāt pēc tavas labklāšanās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tu mani esi atstājusi, saka Tas Kungs, tu esi atpakaļ gājusi; tāpēc Es Savu roku pret tevi gribu izstiept un tevi izdeldēt; Es esmu apnicis žēlot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Un Es tos ar vētekli izvētīšu ārā pa zemes vārtiem, un Es Saviem ļaudīm nolaupīšu bērnus un tos izdeldēšu, tādēļ ka tie neatgriežas no saviem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Atraitņu Man būs vairāk viņu starpā nekā jūras smiltis. Es tiem uzvedīšu pār jaunekļu māti postītāju dienas vidū, Es piepeši uz to metīšu bailes un briesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Kas septiņus bērnus dzemdējusi, iztvīks un izlaidīs savu dvēseli. Viņas saule noies vēl dienas laikā, viņa taps kaunā un par apsmieklu; un viņu atlikušos Es nodošu zobenam viņu ienaidnieku priekšā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Ak vai, man, mana māte, ka tu mani esi dzemdējusi, strīdus vīru un ķildas vīru visai zemei! Es neesmu aizdevis un man nav aizdevuši tomēr visi mani lād.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Tas Kungs sacīja: tiešām, Es tevi stiprināju uz labu, tiešām, Es daru, ka nelaimes laikā un spaidu laikā ienaidnieks lūgdamies pie tevis griezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Vai tad ar dzelzi var salauzt, ziemeļa dzelzi un varu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Tavu padomu un tavu mantu Es nodošu par laupījumu bez maksas, un to visu tavu grēku dēļ pa visām tavām robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Un Es likšu taviem ienaidniekiem to nest uz zemi, ko tu nepazīsti. Jo Manas bardzības uguns ir iededzies, tas degs pār jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ak Kungs, Tu to zini, piemini mani un piemeklē mani un atrieb mani pie maniem vajātājiem! Pēc Savas lēnprātības neņem mani nost; zini, ka es Tevis dēļ topu nievāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Kad Tavs Vārds man notika, tad es to esmu uzņēmis, un Tavs Vārds man ir bijis par prieku un par sirds līksmību, jo es esmu nosaukts pēc Tava Vārda, ak Kungs Dievs Cebaot!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Es neesmu sēdējis smējēju draudzē un neesmu priecājies (ar tiem); Tavas rokas dēļ es esmu vientulis sēdējis, jo Tu mani esi pildījis ar skumību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Kāpēc tad manas sāpes nemitās, un mana mocība ir tik grūta, ka negribās dziedinājumu? Vai Tu man gribi būt kā viltīga upe, kā ūdens, kas izsīkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Tāpēc Tas Kungs tā saka: ja tu atgriezīsies, tad Es tevi griezīšu atpakaļ un tu stāvēsi Manā priekšā. Un ja tu izšķirsi to, kas cienīgs no tā, kas niecīgs, tad tu būsi tā kā Mana mute. Tiem būs pie tevis griezties, bet tu negriezīsies pie viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Jo Es tevi ceļu šiem ļaudīm par stipru vara mūri; tie gan pret tevi karos, bet tevi nepārspēs; jo Es esmu ar tevi, tevi atpestīt un tevi izglābt, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Tiešām, Es tevi atpestīšu no ļauno rokas un tevi izglābšu no briesmīgo dūres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Un Tā Kunga vārds uz mani tā notika:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Tev nebūs sievu ņemt, tev arī nebūs šinī vietā dzemdināt ne dēlus ne meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Jo tā saka Tas Kungs par tiem dēliem un par tām meitām, kas šai vietā piedzimuši, ir par viņu mātēm, kas tos dzemdē un par viņu tēviem, kas tos dzemdina šai zemē:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Tie nomirs ar nāvīgām sērgām, tie netaps apraudāti nedz aprakti, tie būs par mēsliem virs zemes; tie taps aprīti caur zobenu un caur badu, un viņu miesas būs par barību putniem apakš debess un zvēriem virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Jo tā saka Tas Kungs: tev nebūs iet raudu namā, un neej gaust nedz par tiem žēloties. Jo tā saka Tas Kungs: No šiem ļaudīm Es esmu atņēmis Savu mieru, žēlastību un apžēlošanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Tā ka lieli un mazi šai zemē nomirs un netaps aprakti, tie arī netaps apraudāti un nevienam nebūs graizīties, nedz apcirpties viņu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Tiem arī nebūs lauzt sēru maizi, tos iepriecināt par mirušu, un tos nebūs dzirdināt ar iepriecināšanas biķeri par tēvu vai māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Tāpat neej dzīru namā pie tiem sēdēt ēst un dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, šinī vietā priekš jūsu acīm un jūsu dienās Es likšu mitēties prieka balsij un līksmības balsij, brūtgāna balsij un brūtes balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Un kad tu šiem ļaudīm visus šos vārdus teiksi un tie uz tevi saka: Kāpēc Tas Kungs pret mums runā visu šo lielo ļaunumu? Un kas ir mūsu noziegums, un kas ir mūsu grēks, ar ko esam apgrēkojušies pret To Kungu, savu Dievu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Tad tev uz tiem būs sacīt: tādēļ ka jūsu tēvi Mani atstājuši, saka Tas Kungs, un citiem dieviem dzinušies pakaļ un tiem kalpojuši un tos pielūguši, bet Mani atstājuši un nav turējuši Manu bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Un jūs esat niknāki darījuši nekā jūsu tēvi. Jo redzi, jūs staigājat ikviens pēc savas niknās sirds stūrgalvības un Mani neklausiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Un tā tad Es jūs izmetīšu no šīs zemes uz zemi, ko nepazināt, ne jūs ne jūsu tēvi, un tur jūs kalposiet citiem dieviem dienām naktīm, tādēļ ka Es jums neparādīšu žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Tādēļ redzi, nāks dienas, saka Tas Kungs, ka vairs nesacīs: „Tik tiešām kā Tas Kungs dzīvo, kas Israēla bērnus no Ēģiptes zemes izvedis,“-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Bet: „Tik tiešām kā Tas Kungs dzīvo, kas Israēla bērnus no ziemeļu zemes izvedis un no visām zemēm, kurp viņš tos bija aizdzinis“; jo Es tos atkal atvedīšu viņu zemē, ko esmu devis viņu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Redzi, Es sūtīšu pēc daudz zvejniekiem, saka Tas Kungs, - tiem tos būs zvejot, un pēc tam Es sūtīšu pēc daudz medniekiem, tie tos medīs pa visiem kalniem un pa visiem pakalniem, un pat akmens kalnu plaisumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Jo Manas acis redz visus viņu ceļus, Manā priekšā tie nav apslēpti, nedz viņu noziegums apklāts priekš Manām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Bet papriekš Es viņu noziegumu un viņu grēku atmaksāšu divkārtīgi, tāpēc ka tie Manu zemi sagānījuši ar savu elka dievu maitām un Manu mantas tiesu piepildījuši ar savām negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Ak Kungs, tu esi mans spēks un mans stiprums un mans patvērums bēdu dienā. Pie tevis nāks tautas no pasaules galiem un sacīs: tiešām, mūsu tēvi turējuši viltīgus un nelietīgus dievekļus, kas nekā nevarēja palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Vai tad cilvēkam sev būs dievus taisīt, kas dievi nav?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Tādēļ redzi, Es, šim brīdim, tiem darīšu zināmu, Es tiem darīšu zināmu Savu roku un Savu varu, un tiem būs atzīt, ka Mans vārds ir: Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Jūda grēki ir rakstīti ar dzelzs rakstāmo, ar dimanta asmeni, tie ir ierakstīti viņu sirds galdā un uz jūsu altāru ragiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Tā ka viņu bērni piemin savus altārus un savas Ašeras pie zaļiem kokiem uz augstiem pakalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Bet Es Savu kalnu līdz ar to tīrumu, tavu padomu un visas tavas mantas nodošu par laupījumu līdz ar taviem elku kalniem, to grēku dēļ, kas visās tavās robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Tā tu caur savu paša vainu no savas daļas tapsi izdzīts, ko Es tev biju devis. Un Es tev likšu kalpot taviem ienaidniekiem zemē, ko tu nepazīsti; jo jūs Manas bardzības uguni esat iededzinājuši, kas degs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tā saka Tas Kungs: Nolādēts tas cilvēks, kas paļaujas uz cilvēkiem un ieceļ miesu par savu elkoni, un kā sirds no Tā Kunga atkāpjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Jo tas būs tā kā vientulis koks klajumā un neredzēs labumu nākam, bet paliek izkaltušās tuksneša vietās, neauglīgā zemē, kur neviens nedzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Svētīgs tas cilvēks, kas uz To Kungu paļaujas, un kura cerība ir Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Jo tas būs kā koks, kas pie ūdens dēstīts, kas savas saknes izlaiž pie upes un nejūt, kad karstums nāk; viņa lapas paliek zaļas, un sausā gadā viņš nebēdā un nemitās augļus nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Sirds ir viltīga pār visām lietām un samaitāta, kas to var izzināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Es, Tas Kungs, izmanu sirdi un pārbaudu īkstis un dodu ikvienam pēc viņa ceļiem, pēc viņa darbu augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Tā kā irbe perē olas, ko nav dējusi, tāpat ir, kas bagātību sakrāj, bet ne ar taisnību; pusmūžā viņam tā jāatstāj un galā viņš ir ģeķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Bet Tu godības sēdeklis, augsts no iesākuma, mūsu svētuma vieta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Ak Kungs, Tu Israēla cerība, visi, kas Tevi atstāj, taps kaunā! “Tie, kas no Manis atkāpjas, taps zemē rakstīti, jo tie atstāj To Kungu, to dzīvā ūdens avotu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Dziedini mani, ak Kungs, tad es būšu dziedināts, atpestī mani, tad es būšu atpestīts, jo tu esi mana slava.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Redzi, tie uz mani saka: kur ir Tā Kunga vārds? Lai jel nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Bet es neesmu liedzies, par ganu būt, Tev pakaļ iet, un nelaimes dienas es neesmu vēlējies. Tu to zini: kas no manas mutes izgājis, tas ir atklāts Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Neesi man par briesmām! Tu esi mans patvērums ļaunā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Lai mani vajātāji top kaunā, bet lai es netopu kaunā; lai tie top iztrūcināti, bet lai es netopu iztrūcināts; lai nāk pār tiem nelaimes diena, un satriec tos ar divkārtīgu satriekšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Tā Tas Kungs uz mani sacīs: ej un stāvi ļaužu vārtos, kur Jūda ķēniņi ieiet, un kur tie iziet, un visos Jeruzālemes vārtos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Un saki uz tiem: klausiet Tā Kunga vārdu, Jūda ķēniņi, un visa Jūda cilts, un visi Jeruzālemes iedzīvotāji, kas pa šiem vārtiem ieejat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tā saka Tas Kungs: sargājaties par savām dvēselēm, un nenesiet nekādu nastu svētdienā, un nevediet nekā pa Jeruzālemes vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Un neiznesiet nastas no saviem namiem svētdienā un nedariet nekādu darbu, bet svētījiet to svēto dienu, kā Es jūsu tēviem esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Bet tie nav klausījuši nedz savas ausis atgriezuši, bet tie bijuši stūrgalvīgi un nav klausījuši un mācību nav pieņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Tad nu tā notiks: ja jūs Mani klausīt klausīsiet, saka Tas Kungs, un nenesīsiet nastas pa šīs pilsētas vārtiem svētdienā, un svētīsiet to svēto dienu, tai dienā nekādu darbu nedarīdami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Tad pa šīs pilsētas vārtiem ies ķēniņi un lielkungi, kas sēž uz Dāvida goda krēsla un brauks ar ratiem un zirgiem, tie un viņu lielkungi, Jūda vīri un Jeruzālemes iedzīvotāji, un šī pilsēta stāvēs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Un nāks no Jūda pilsētām un no Jeruzālemes apkārtnes un no Benjamina zemes un no lejas un no kalniem un no dienvidiem(Negebas) un atnesīs dedzināmu upuri un kaujamu upuri un ēdamu upuri un vīraku, un pienesīs teikšanas upuri Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Bet ja jūs Mani neklausīsiet, svēto dienu nesvētīdami un svētdienā nastas nesdami pa Jeruzālemes vārtiem, tad Es viņas vārtos iededzināšu uguni, kas aprīs Jeruzālemes skaistos namus un neizdzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Šis ir tas vārds, kas no Tā Kunga tā notika uz Jeremiju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Celies un noej podnieka namā, un tur Es tev likšu dzirdēt Savus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Tad es nogāju podnieka namā, un redzi, viņš strādāja darbu uz skrituļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Un tas pods, ko viņš no māliem taisīja, neizdevās podnieka rokā, tad viņš no tā atkal taisīja citu podu, kā tas podniekam patika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Tad Tā Kunga vārds uz mani tā notika:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Vai Es jums tā nevaru darīt, kā šis podnieks, tu Israēla nams? Saka Tas Kungs. Redzi, kā māls podnieka rokā, tā jūs esat Manā rokā, tu Israēla nams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Vienreiz Es runāju par vienu tautu un par vienu valsti, ka Es to gribu izdeldēt un postīt un nomaitāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Bet ja šī tauta atgriežas no sava ļaunuma, par ko Es esmu runājis, tad Man tā ļaunuma arī būs žēl, ko Es viņai gribēju darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Un atkal Es par vienu tautu un par vienu valsti runāju, ka Es to gribu uztaisīt un dēstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Bet ja tā priekš Manām acīm ļaunu dara un Manu balsi neklausa, tad Man arī būs žēl tā labuma, ko Es biju solījis viņai darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Un nu runā jel uz Jūda vīriem un uz Jeruzālemes iedzīvotājiem un saki: tā saka Tas Kungs: redzi, Es pret jums daru ļaunumu un Man ir nodoms pret jums. Atgriežaties jel ikviens no sava ļaunā ceļa un griežaties uz labiem ceļiem un pie labiem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Bet tie saka: velti! Jo mēs staigāsim pēc savām domām un darīsim ikviens pēc savas ļaunās sirds stūrgalvības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Tādēļ tā saka Tas Kungs: vaicājiet jel starp pagāniem, kas tādas lietas dzirdējis? Israēla meita dara ļoti negantas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Vai Lībanus sniegs atstājās no lauku klints? Vai svešie aukstie tekošie ūdeņi izsīkst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Jo Mani ļaudis Mani aizmirsuši; tie kvēpina tiem nelietīgiem; šie tos darījuši klūpam viņu ceļos uz tām vecām tekām, ka tiem bija jāstaigā pa nestaigāta ceļa tekām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Ka viņu zeme paliek postā un par apsmieklu mūžīgi; visi, kas tur iet garām, iztrūcināsies un kratīs savu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Kā rīta vējš, tā Es tos izkaisīšu ienaidnieku priekšā, Es tiem rādīšu muguru un ne vaigu viņu nelaimes dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Tad tie sacīja: nāciet, sadomāsim padomu pret Jeremiju, jo bauslība nevar zust priesteriem nedz padoms gudriem nedz mācība praviešiem. Nāciet, kausim to ar mēli un neklausīsim nepavisam viņa vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Kungs, ņem mani vērā un klausi uz manu pretinieku balsi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Vai tad labu būs atmaksāt ar ļaunu? Jo tie manai dvēselei bedri rakuši. Piemini, ka es tavā priekšā esmu stāvējis un priekš tiem labu runājis, novērst tavu dusmību no viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Tāpēc nodod viņu bērnus badam, un lai tie aiziet caur zobena varu, un lai viņu sievas paliek bez bērniem un par atraitnēm, un lai viņu vīri kautin top nokauti un viņu jaunekļi ar zobenu nosisti karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Lai brēkšana top dzirdēta viņu namos, kad piepeši pār tiem nāk karapulki; tāpēc ka tie bedri rakuši, mani gūstīt, un slepeni valgus likuši manām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Jo Tu, Kungs, zini visu viņu padomu pret mani, ka tie mani grib nokaut; neliecies salīdzināties par viņu noziegumiem un neizdeldē viņu grēkus Tavā priekšā, bet lai tie top nogāzti Tavā priekšā; tā dari ar tiem Tavas bardzības laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Tā saka Tas Kungs: ej un pērc sev no podnieka māla krūzi, un ņem pie sevis kādus no ļaužu vecajiem un no priesteru vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Un ej ārā uz Ben-Inoma ieleju, kas ir priekš Ķieģeļu vārtiem, un sludini tur tos vārdus, ko Es uz tevi runāšu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Un saki: klausiet Tā Kunga vārdu, Jūda ķēniņi un Jeruzālemes iedzīvotāji! Tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, Es vedīšu nelaimi pār šo vietu, no kā visiem, kas to dzirdēs, ausīs skanēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Tāpēc ka tie Mani atstāj un šo vietu svešiem nodevuši un tur kvēpinājuši svešiem dieviem, ko ne viņi, ne viņu tēvi, ne Jūda ķēniņi nav pazinuši, un to vietu piepildījuši ar nenoziedzīgām asinīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Un Baālam uztaisījuši altārus un savus bērnus ar uguni sadedzinājuši Baālam par dedzināmiem upuriem, ko Es neesmu pavēlējis, un neesmu runājis, un kas Man nav nācis sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Tādēļ, redzi, nāks dienas, saka Tas Kungs, ka šī vieta vairs netaps nosaukta Tovete vai Ben-Inoma ieleja, bet slepkavu ieleja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Jo Es iznīcināšu Jūda un Jeruzālemes padomu šinī vietā, un tiem likšu krist caur zobenu priekš viņu ienaidniekiem un caur to rokām, kas viņu dvēseli meklē, un Es nodošu viņu miesas par barību putniem apakš debess un zvēriem virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Un šo pilsētu Es likšu par posta vietu un par apsmieklu; visi, kas iet garām, tie iztrūksies un svilpos par visām viņu mokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Un Es tiem došu ēst viņu dēlu miesas un viņu meitu miesas, un tie ēdīs ikviens sava tuvāka miesas tais bēdās un bailēs, ar ko tos spaidīs viņu ienaidnieki un kas viņu dvēseles meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Tad tev to krūzi būs sadauzīt priekš to vīru acīm, kas tev gājuši līdz,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Un uz tiem sacīt: tā saka Tas Kungs Cebaot: tāpat es šos ļaudis un šo pilsētu sadauzīšu, tā kā sadauza māla trauku, kas vairs nevar vesels tapt, un Tovetē raks līķus, tāpēc ka citas kapu vietas nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tā es šai vietai darīšu, saka Tas Kungs, un viņas iedzīvotājiem, un darīšu šo pilsētu kā Toveti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Un Jeruzālemes nami un Jūda ķēniņu nami būs sagānīti, tā kā Tovetes vieta, un visi tie nami, uz kuru jumtiem tie kvēpinājuši visam debess spēkam un dzeramus upurus upurējuši svešiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Kad nu Jeremija no Tovetes pārnāca, kurp Tas Kungs viņu bija sūtījis sludināt, tad viņš nostājās Tā Kunga nama pagalmā un sacīja uz visu tautu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, Es likšu nākt pār šo pilsētu un visām viņas pilsētām visai nelaimei, ko Es par to esmu runājis, tādēļ ka tie savu pakausi apcietinājuši un Manus Vārdus nav klausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Kad nu priesteris Pašhurs, Imera dēls, kas Tā Kunga namā bija iecelts par uzraugu, dzirdēja, ka Jeremija šos vārdus sludināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Tad Pašhurs sita pravieti Jeremiju un viņu ielika cietumā, kas bija augšējos Benjamina vārtos pie Tā Kunga nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Un otrā dienā Pašhurs Jeremiju izveda ārā no cietuma, un Jeremija uz viņu sacīja: Tas Kungs tavu vārdu nenosauc Pašhur, bet Magur Misabib*.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Jo tā saka Tas Kungs: redzi, Es tevi darīšu par izbailēm tev un visiem taviem draugiem, un tie kritīs caur savu ienaidnieku zobenu, tavām acīm to redzot. Un visu Jūdu Es nodošu Bābeles ķēniņam rokā; tas tos aizvedīs uz Bābeli un tos sitīs ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Un visu šīs pilsētas padomu un visu viņas sagādu(krājumus) un visus viņas dārgumus un visas Jūda ķēniņu mantas Es nodošu viņu ienaidniekiem rokā, un tie tos aplaupīs un tos ņems un tos vedīs uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Un tu, Pašhur, un visi tava nama iedzīvotāji, iesiet cietumā, un tu nāksi uz Bābeli un tur nomirsi un tur tapsi aprakts, tu un visi tavi draugi, kam tu melus esi sludinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Kungs, Tu mani esi pārrunājis, un es esmu licies pārrunāties, Tu esi stiprāks bijis ne kā es un pārvarējis. Bet es esmu cauru dienu par apsmieklu, visi tie mani apmēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Jo kamēr es runāju, brēcu un saucu par varas darbu un postu, tikmēr man Tā Kunga vārds ir tapis par apsmieklu un apmēdīšanu katru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Tad es domāju: es Viņu vairs nepieminēšu un nerunāšu vairs Viņa vārdā. Bet tas manā sirdī bija kā degots uguns, ieslēgts manos kaulos, un es piekusu to visu ciest, un nevarēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Jo es esmu dzirdējis no daudziem aprunāšanu: bailība visapkārt! Apsūdziet to, lai to apsūdzam! Visi mani draugi glūn uz manu klupšanu; tie saka, tas gan taps pārrunāts un mēs to pārspēsim un pie tā atriebsimies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Bet Tas Kungs ir pie manis stiprs un varens, tāpēc mani vajātāji klups un neiespēs nekā, tie visai taps kaunā, ka tie neprātīgi darījuši, ar mūžīgu negodu, ko neaizmirsīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Tad, Kungs Cebaot, kas pārbaudi to taisno, kas redzi īkstis un sirdis, lai es pie tiem redzu Tavu atriebšanu; jo Tev es savu lietu esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Dziediet Tam Kungam, slavējiet To Kungu, jo viņš nabaga dvēseli atpestījis no ļaundarītāju rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Nolādēta lai ir tā diena, kad es esmu dzimis; tā diena, kad mana māte mani dzemdējusi, lai tā nav svētīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Nolādēts lai ir tas vīrs, kas manam tēvam to prieku teicis un sacījis: tev dēliņš piedzimis, prieka vēsti tam atnesdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Šis vīrs lai ir kā tās pilsētas, ko Tas Kungs ir apgāzis bez žēlastības; lai tas agri dzird brēkšanu un pusdienā kara troksni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Ka viņš mani nav nokāvis mātes miesās, ka mana māte būtu bijusi mans kaps un viņas miesas mūžam būtu palikušas grūtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Kāpēc es esmu izgājis no mātes miesām, redzēt grūtumu un sirdēstus, un pavadīt savas dienas ar kaunu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Šis ir tas vārds, kas notika uz Jeremiju no Tā Kunga, kad ķēniņš Cedeķija pie viņa sūtīja Pašhuru, Malhijas dēlu, un priesteri Cefaniju, Maāsejas dēlu, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Vaicā jel To Kungu par mums; jo Nebukadnecars, Bābeles ķēniņš, pret mums karo. Varbūt ka Tas Kungs ar mums darīs pēc saviem brīnumiem, ka šis no mums atstātos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Tad Jeremija uz tiem sacīja: sakāt tā Cedeķijam:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Tā saka Tas Kungs Israēla Dievs: redzi, Es griezīšu atpakaļ tos kara ieročus, kas ir jūsu rokās, ar ko jūs karojat pret Bābeles ķēniņu un pret Kaldejiem, kas pret jums ārpus mūriem apmetušies, un tos sapulcināšu šīs pilsētas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Un Es pats pret jums karošu ar izstieptu roku un ar stipru elkoni un ar bardzību un ar karstumu un lielām dusmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Un Es kaušu šās pilsētas iedzīvotājus, gan cilvēkus, gan lopus; caur lielu mēri tiem būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Un pēc tam, saka Tas Kungs, Es nodošu Cedeķiju, Jūda ķēniņu, un viņa kalpus un tos ļaudis, kas šai pilsētā atlikuši no mēra, no zobena un no bada, Nebukadnecara, Bābeles ķēniņa, rokā un viņu ienaidnieku rokā un to rokā, kas viņu dzīvību meklē. Un viņš tos sitīs ar zobena asmeni, viņš tos nesaudzēs, netaupīs, nežēlos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Un uz šiem ļaudīm tev būs sacīt: tā saka Tas Kungs: redzi, Es jums lieku priekšā dzīvības ceļu un nāves ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Kas šai pilsētā paliek, tie mirs caur zobenu, caur badu un caur mēri. Bet kas iziet un dodas pie tiem Kaldejiem, kas pret jums ir apmetušies, tas dzīvos un mantos savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Jo Es Savu vaigu esmu griezis pret šo pilsētu par ļaunu un ne par labu, saka Tas Kungs; tā Bābeles ķēniņam taps rokā dota un viņš to sadedzinās ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Un par Jūda ķēniņa namu klausiet Tā Kunga vārdu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Ak Dāvida nams, tā saka Tas Kungs, nesiet ik rītu tiesu un izglābiet aplaupīto no spaidītāja rokas, ka Mana dusmība neizšaujās kā uguns un nedeg, ka neviens nevar dzēst, jūsu darbu ļaunuma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Redzi, Es celšos pret tevi, kas dzīvo ielejā, tu klajuma klints, saka Tas Kungs, pret jums, kas teiciet: kas mums varētu uzbrukt vai nākt mūsu māju vietās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Es jūs piemeklēšu pēc jūsu darbu augļiem, saka Tas Kungs, un Es iededzināšu viņas mežā uguni, tas aprīs visu viņas apkārtni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Tā saka Tas Kungs: noej Jūda ķēniņa namā un runā tur šo vārdu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Un saki: klausi Tā Kunga vārdu, Jūda ķēniņ, kas sēdi Dāvida goda krēslā, tu un tavi kalpi un tavi ļaudis, visi, kas ieejat pa šiem vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Tā saka Tas Kungs: nesiet tiesu un taisnību un izglābiet aplaupīto no spaidītāja rokas, un neplēšat svešinieku, bāriņu, atraitni, nedariet varas darbu un neizlejat šai vietā nenoziedzīgas asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Jo kad jūs tā darīsiet, tad pa šā nama vārtiem ieies ķēniņi, kas sēdēs uz Dāvida goda krēsla, un brauks ar ratiem un zirgiem, pats un viņa kalpi un viņa ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Bet ja jūs šos vārdus neklausīsiet, tad Es pie Sevis esmu zvērējis, saka Tas Kungs, ka šim namam būs palikt par posta vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Jo tā saka Tas Kungs par Jūda ķēniņa namu: tu Man esi kā Gileāda, kā Lībanus galva, bet tiešām, Es tevi darīšu par tuksnesi un tās pilsētas bez iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Jo Es pret tevi iecelšu postītājus, ikvienu ar saviem ieročiem; tie nocirtīs tavus labākos ciedru kokus un tos metīs ugunī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Tad daudz pagānu šai pilsētai ies garām un sacīs cits uz citu: kādēļ Tas Kungs šai lielai pilsētai tā darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Un tie sacīs: tādēļ ka tie atstājuši Tā Kunga, sava Dieva, derību un zemē metušies priekš citiem dieviem un tiem kalpojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Neraudiet par nomirušo un nežēlojiet viņu; raudiet raudādami par to, kas aiziet, jo tas neatgriezīsies atpakaļ, redzēt savas dzimtenes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Jo tā saka Tas Kungs par Šallumu, Josijas dēlu, Jūda ķēniņu, kas valda sava tēva Josijas vietā, kas no šās vietas aizgājis: viņš vairs negriezīsies atpakaļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Bet tai vietā, kurp tie viņu aizveduši, viņš mirs un šo zemi viņš vairs neredzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Vai tam, kas savu namu uztaisa ar netaisnību un savas istabas ar viltu, kas savam tuvākam liek velti strādāt, un tam nedod savu algu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Kas domā: es sev uztaisīšu augstu namu un plašas istabas, un liek sev logus izcirst un ar ciedru kokiem apsegt un ar sarkanumu apsvaidīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Vai tu domā valdīt, tādēļ ka tu ar ciedru kokiem greznojies? Vai tavs tēvs neēda un nedzēra un darīja tiesu un taisnību? Tad viņam labi klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Viņš izdeva tiesu nabagam un bēdīgam, tad viņam labi klājās. Vai tas nav mani atzīt? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Bet tavas acis un tava sirds uz citu neskatās kā vien mantu krāt un nenoziedzīgas asinis izliet, apspiest un darīt varas darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Tādēļ, tā saka Tas Kungs par Jojaķimu, Josijas, Jūda ķēniņa dēlu: par to nevaidēs: vai, mans brāli! Vai, mana māsa! par to nevaidēs: vai, kungs! Vai, cienīgais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Bet kā ēzeli aprok, tā viņu apraks, un viņš taps rauts un izmests tālu no Jeruzālemes vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Kāp uz Lībanu un sauc un pacel savu balsi Basanā un brēc no Abarima, jo visi tavi mīluļi ir satriekti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Es runāju uz tevi, kad tev vēl labi klājās, bet tu sacīji: es neklausīšu. Tas ir tavs ceļš no pašas jaunības, ka tu Manu balsi neesi klausījis');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Vējš aizraus visus tavus ganus, un tavi mīluļi ies cietumā; tad tu tiešām tapsi kaunā un par apsmieklu visas savas blēdības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Tu uz Lībanus dzīvo un ciedru kokos taisi ligzdas, kā tev klāsies, kad tev sāpes uzies, mokas, kā dzemdētājai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Tik tiešām kā Es dzīvoju, saka Tas Kungs: kaut arī Kanija, Jojaķima dēls, Jūda ķēniņš, būtu pie Manas labās rokas spiežamais gredzens, tomēr Es tevi no tejienes aizraušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Un Es tevi nodošu rokā tiem, kas tavu dvēseli meklē, un tiem rokā, priekš kā vaiga tu bīsties, proti Nebukadnecera, Bābeles ķēniņa, un Kaldeju rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Un Es izmetīšu tevi un tavu māti, kas tevi dzemdējusi, uz citu zemi, kur jūs neesiet dzimuši, un tur jums būs jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Un tai zemē, kurp viņu dvēselei gribēsies atpakaļ griezties, turp tie neatgriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Vai šis vīrs Kanija ir viens nieka sadauzāms pods, jeb vai viņš trauks, kas nevienam nepatīk? Kāpēc viņš un viņa dzimums atmesti uz to zemi, ko tie nepazīst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Ak zeme, zeme, zeme! Klausi Tā Kunga vārdu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Tā saka Tas Kungs: pieraksti šo vīru par neauglīgu, par vīru, kam savu mūžu labi neizdosies. Jo nevienam no viņa dzimuma labi neklāsies, kas varētu sēdēt uz Dāvida goda krēsla un turpmāk valdīt pār Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Ak vai, jums, gani, kas Manas ganības avis nomaitājat un izklīdinājāt, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Tādēļ tā saka Tas Kungs, Israēla Dievs, par tiem ganiem, kas Manus ļaudis gana: Jūs Manas avis esat izklīdinājuši un tās esat izdzinuši un par tām neesiet zinājuši. Redzi! Es jūs piemeklēšu jūsu ļauno darbu dēļ, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Un Es pats sapulcināšu Savas atlikušās avis no visām zemēm, kurp tās esmu izdzinis, un tās atkal atvedīšu uz viņu ganībām, un tās būs auglīgas un vairosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Un Es pār tām iecelšu ganus, kas tās ganīs, un tās vairs nebīsies, nedz baiļosies, nedz taps piemeklētas, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Redzi, nāks dienas, saka Tas Kungs, kad Es Dāvidam uzcelšu taisnības Atvasi, un Tas valdīs kā ķēniņš, un Viņam labi izdosies, un Viņš darīs tiesu un taisnību virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Viņa laikā Jūda taps atpestīts un Israēls dzīvos droši. Un tas būs Viņa vārds, ar ko Viņš taps nosaukts: Tas Kungs mūsu taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Tāpēc redzi, nāks dienas, saka Tas Kungs, ka vairs nesacīs: “Tik tiešām ka Tas Kungs dzīvo, kas Israēla bērnus izvedis no Ēģiptes zemes“,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Bet: „Tik tiešām, ka Tas Kungs dzīvo, kas Israēla nama dzimumu izvedis un atvedis no tās zemes pret ziemeļa pusi, un no visām zemēm, kurp Es to biju aizdzinis“, jo tie dzīvos savā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Par tiem praviešiem mana sirds iekš manis ir salauzta, visi mani kauli dreb, es esmu kā piedzēris vīrs un kā vīrs, ko vīns pārvarējis Tā Kunga priekšā un priekš Viņa svētiem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Jo zeme ir pilna laulības pārkāpēju, jo zeme bēdājās lāstu dēļ tuksneša ganības izkalst, tādēļ ka viņu ceļš ir ļauns, un viņu vara netaisna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Jo tā pravietis kā priesteris ir nesvēti, pat Savā namā Es atrodu viņu blēdību, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Tāpēc viņu ceļš būs kā slidenums tumsībā, tur piedauzīsies un kritīs. Jo Es vedīšu pār tiem nelaimi viņu piemeklēšanas gadā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Pie tiem praviešiem Samarijā Es gan redzēju ģeķību, jo tie sludināja caur Baālu un pievīla Manus Israēla ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Bet pie tiem praviešiem Jeruzālemē Es redzu negantību; tie pārkāpj laulību un tinās ar viltību un stiprina ļaundarītāju rokas, ka tie neatgriežas neviens no sava ļaunuma; tie visi Man ir kā Sodoma un viņas iedzīvotāji kā Gomora.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Tāpēc Tas Kungs Cebaot par šiem praviešiem tā saka: redzi, Es tos ēdināšu ar vērmelēm un tos dzirdināšu ar žultīm, jo no Jeruzālemes praviešiem bezkaunība izgājusi pa visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Tā saka Tas Kungs Cebaot: neklausiet to praviešu vārdiem, kas jums sludina; tie jūs ved nelietībā, tie runā savas sirds parādīšanu, ne no Tā Kunga mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Tie saka allažiņ uz tiem, kas Mani zaimo: Tas Kungs ir runājis, ka jums būs miers, un uz visiem, kas pēc savas sirds stūrgalvības staigā, tie saka: nelaime nenāks pār jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Jo kas bijis Tā Kunga padoma devējs? Kas viņa vārdu redzējis vai dzirdējis? Kas viņa vārdu vērā ņēmis un klausījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Redzi, Tā Kunga vētra celsies ar bardzību, un briesmīgs viesulis, tas gāzīsies bezdievīgiem uz galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Tā Kunga bardzība negriezīsies atpakaļ, tiekams Viņš nebūs padarījis un piepildījis Savas sirds domas; nākamās dienās jūs to gan manīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Es nesūtīju praviešus, un tomēr tie tecēja; Es nerunāju, un tomēr tie sludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Bet ja tie būtu stāvējuši Manā padomā, tad tie Manu vārdu būtu darījuši zināmu Maniem ļaudīm un tos būtu nogriezuši no viņu ļaunā ceļa un no viņu ļauniem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Vai Es esmu Dievs, kas tikai ir tuvu, saka Tas Kungs, un neesmu arī Dievs, kas ir tālu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Vai kas laban arī var tverties apslēptās vietās, ka Es to neredzētu? saka Tas Kungs. Vai Es nepiepildu debesis un zemi? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Es to esmu dzirdējis, ko tie pravieši saka, kas Manā Vārdā sludina melus un saka: es esmu sapni redzējis, es esmu sapni redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Cik ilgi tas būs to praviešu sirdī, kas sludina melus un sludina savas sirds viltību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Kas uz to dodas, lai Mani ļaudis Manu vārdu aizmirst caur viņu sapņiem, ko tie cits citam stāsta, kā viņu tēvi Manu vārdu aizmirsuši caur Baālu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Lai tas pravietis, kas sapņus redz, sapņus stāsta, un pie kā Mans vārds ir, tas lai Manu vārdu runā patiesībā. Kāda daļa pelavām ar graudiem? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Vai Mans vārds nav kā uguns, saka Tas Kungs, un kā veseris, kas sagrauž akmens kalnus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Tādēļ redzi, Es celšos, saka Tas Kungs, pret tiem praviešiem, kas Manus vārdus zog cits citam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Redzi, Es celšos, saka Tas Kungs, pret tiem praviešiem, kas runā savus pašu vārdus un saka: Viņš to runājis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Redzi, Es celšos pret tiem, kas sludina melu sapņus, saka Tas Kungs, un tos stāsta un pieviļ Manus ļaudis ar saviem meliem un ar savām tukšām blēņām, un Es tomēr tos neesmu sūtījis un tiem nekā neesmu pavēlējis, un tie nepavisam neder šiem ļaudīm, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Kad nu šie ļaudis vai kāds pravietis vai priesteris tev vaicās un sacīs: kas ir Tā Kunga nasta? Tad tev tiem būs sacīt, jūs esat tā nasta, un Es jūs gribu atmest, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Un ja būs kāds pravietis, vai priesteris, vai cilvēks, kas sacīs: Tā Kunga nasta, - to vīru un viņa namu Es piemeklēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Tā jums būs sacīt ikvienam uz savu tuvāku un ikvienam uz savu brāli: ko Tas Kungs atbildējis, un ko Tas Kungs runājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Bet Tā Kunga nastu jums vairs nebūs pieminēt, jo ikvienam savs vārds būs par nastu, tāpēc ka jūs esat pārgrozījuši tā dzīvā Dieva, Tā Kunga Cebaot, mūsu Dieva, vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tā tev būs sacīt uz to pravieti: ko tev Tas Kungs atbildējis, un ko Tas Kungs runājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Bet tāpēc ka jūs sakāt: Tā Kunga nasta, tad Tas Kungs tā saka: Tāpēc ka jūs šo vārdu sakāt: Tā Kunga nasta, - kur Es taču pie jums esmu sūtījis un sacījis, jums nebūs sacīt: Tā Kunga nasta, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Tādēļ, redzi, Es jūs pavisam aizmirsīšu un jūs atmetīšu no Sava vaiga, ar visu to pilsētu, ko Es jums un jūsu tēviem esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Un Es pār jums celšu mūžīgu kaunu un mūžīgu negodu, ko neaizmirsīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Tas Kungs man rādīja un redzi, tur bija nolikti divi vīģu kurvji Tā Kunga nama priekšā, kad Nebukadnecars, Bābeles ķēniņš, bija aizvedis Jekoniju, Jojaķima dēlu, Jūda ķēniņu līdz ar Jūda lielkungiem, un amatniekus un kalējus, un tos bija novedis no Jeruzālemes uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Vienā kurvī bija ļoti labas vīģes, kā agrejās vīģes, bet otrā kurvī bija ļoti nelāga vīģes, ko nevarēja ēst aiz viņu nelāguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Un Tas Kungs sacīja uz mani: ko tu redzi, Jeremija? Un es sacīju: vīģes. Tās labās vīģes ir ļoti labas un tās nelāga vīģes ir ļoti nelabas, ka nevar ēst aiz nelāguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Tad Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Tā saka Tas Kungs, Israēla Dievs: tā kā šās vīģes labas, tā Es atzīšu par labiem tos, kas no Jūda aizvesti, ko no šās vietas esmu aizsūtījis uz Kaldeju zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Un Es Savu aci uz tiem metīšu par labu, un tos atvedīšu atpakaļ uz šo zemi, un tos uztaisīšu un nenolauzīšu, Es tos dēstīšu un neizraušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Un Es tiem došu sirdi, Mani atzīt, ka Es esmu Tas Kungs, un tie Man būs par ļaudīm, un Es tiem būšu par Dievu; jo tie pie Manis atgriezīsies no visas savas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Bet kādas tās nelāga vīģes ir, ko nevar ēst aiz nelāguma, tā saka Tas Kungs, par tādiem Es darīšu Cedeķiju, Jūda ķēniņu, un viņa lielkungus un Jeruzālemes atlikušos, kas atlikuši šai zemē un kas dzīvo Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Un Es tos nodošu uz vārdzināšanu, uz nelaimi visās pasaules valstīs, uz nievāšanu un uz lamāšanu, uz mēdīšanu un lādēšanu visās vietās, kurp tos būšu aizdzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Un Es tiem sūtīšu zobenu, badu un mēri, tiekams tie būs izdeldēti no tās zemes, ko Es tiem un viņu tēviem esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Šis ir tas vārds, kas notika uz Jeremiju par visiem Jūda ļaudīm Jūda ķēniņa Jojaķima, Josijas dēla, ceturtā gadā; tas bija Nebukadnecara, Bābeles ķēniņa, pirmais gads; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'To pravietis Jeremija runājis uz visiem Jūda ļaudīm un uz visiem Jeruzālemes iedzīvotājiem un sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'No Jūda ķēniņa Josijas, Amona dēla, trīspadsmitā gada līdz šai dienai, šos divdesmit trīs gadus, Tā Kunga vārds uz mani noticis, un es uz jums esmu runājis vienā runāšanā, bet jūs neesat klausījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Un Tas Kungs pie jums vienmēr sūtījis vienā sūtīšanā visus Savus kalpus, tos praviešus, bet jūs neesat klausījuši un neesat savas ausis atgriezuši paklausīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Tie sacīja: atgriežaties jel ikviens no sava niknā ceļa un no sava darba ļaunuma, tad dzīvosiet tai zemē, ko Tas Kungs devis jums un jūsu tēviem, mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Nedzenaties citiem dieviem pakaļ tiem kalpot un tos pielūgt, un neapkaitinājat Mani caur savu roku darbu, ka Es jums nedaru ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Bet jūs Mani neesat klausījuši, saka Tas Kungs, Mani kaitinādami caur savu roku darbu, sev pašiem par ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Tādēļ tā saka Tas Kungs Cebaot: Tāpēc ka jūs neesat klausījuši Manus Vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Redzi, tad Es sūtīšu un ņemšu visas ciltis no ziemeļa puses, saka Tas Kungs, līdz ar Nebukadnecaru, Bābeles ķēniņu, Savu kalpu, un tās vedīšu pār šo zemi un pār viņas iedzīvotājiem un pār visiem ļaudīm visapkārt, un Es tos izdeldēšu un tos darīšu par biedēkli un par apsmieklu un mūžīgu tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Un Es tiem iznīcināšu prieka balsi un līksmības balsi, brūtgāna balsi un brūtes balsi, dzirnavu troksni un sveces spīdumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Un visa šī zeme paliks par posta vietu un par tuksnesi. Un šie ļaudis kalpos Bābeles ķēniņam septiņdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Bet kad tie septiņdesmit gadi būs pilni, tad Es, saka Tas Kungs, piemeklēšu pie Bābeles ķēniņa un pie šiem ļaudīm, viņu noziegumu, tāpat pie Kaldeju zemes, un to darīšu par mūžīgu tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Un Es vedīšu pār šo zemi visus Savus Vārdus, ko Es par to esmu runājis, visu, kas šai grāmatā rakstīts, ko Jeremija par visiem šiem ļaudīm sludinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Jo arī tos kalpinās varenas tautas un lieli ķēniņi. Tā Es tiem atmaksāšu pēc viņu darīšanas un pēc viņu roku darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Jo tā Tas Kungs, Israēla Dievs, uz mani sacījis: ņem no Manas rokas šo biķeri bardzības vīna un dodi to dzert visiem ļaudīm, pie kā Es tevi sūtu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Lai tie dzer, streipuļo un trako caur to zobenu, ko Es viņu starpā sūtīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Un es ņēmu to biķeri no Tā Kunga rokas un devu visiem ļaudīm dzert, pie kā Tas Kungs mani bija sūtījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Proti Jeruzālemei un Jūda pilsētām un viņas ķēniņiem un viņas lielkungiem, tos darīt par postu un par biedēkli, par apsmieklu un par lāstu, tā kā tas šodien ir,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Faraonam, Ēģiptes ķēniņam un viņa kalpiem un viņa lielkungiem un visiem viņa ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'Un visām jauktām tautām, un visiem ķēniņiem Uc zemē un visiem ķēniņiem Fīlistu zemē un Askalonai un Gazai un Ekronei un Ašdodas atlikušiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomam un Moabam un Amona bērniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Un visiem Tirus ķēniņiem un visiem Sidonas ķēniņiem, tiem ķēniņiem, kas salās viņpus jūras,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedanam un Temanam un Buzam un tiem, kam apcirptas bārdas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'Un visiem Arābijas ķēniņiem un visiem ķēniņiem pār jauktām tautām, kas tuksnesī dzīvo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Un visiem Zimrus ķēniņiem un visiem Elama ķēniņiem un visiem Medijas ķēniņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Un visiem ziemeļu ķēniņiem tuvu un tālu, vienam kā otram, un visām zemes valstīm, kas virs zemes, un Šešaka ķēniņš dzers pēc viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Tev uz tiem būs sacīt: tā saka Tas Kungs Cebaot, Israēla Dievs: dzeriet un piedzeraties un vemjat un krītat, ka jūs atkal neceļaties priekš tā zobena, ko Es sūtīšu jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Un kad tie liegsies to biķeri ņemt no tavas rokas un dzert, tad tev uz tiem būs sacīt: tā saka Tas Kungs Cebaot: tiešām, jums būs dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Jo redzi, tai pilsētā, kas nosaukta pēc Mana Vārda, Es iesāku ar to ļaunumu; vai jūs paliksiet itin bez soda? Jūs nepaliksiet bez soda, jo Es zobenu atsaucu pār visiem zemes iedzīvotājiem, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Tad tev visus šos vārdus tiem būs sludināt un uz tiem sacīt: Tas Kungs rūks no augšienes un pacels Savu balsi no Savas svētās vietas, Viņš rūkdams rūks pret Savu mājokli, Viņš kliegšanu cels, kā vīna minēji, pret visiem zemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Skaņa ies līdz pasaules galam, jo Tam Kungam ir strīdus ar tautām, Viņš turēs tiesu pār visu miesu; bezdievīgos Viņš nodod zobenam, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Tā saka Tas Kungs Cebaot: redzi, nelaime izies no tautas uz tautu, un liela vētra celsies no pasaules gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Un Tā Kunga nokautie gulēs tai dienā no viena pasaules gala līdz otram, tie netaps žēloti nedz salasīti nedz aprakti, tie būs par mēsliem virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Kauciet, gani, un brēciet un vārtaties pelnos, ganāmā pulka lepnie; jo jūsu dienas ir piepildītas uz kaušanu, un Es jūs izklīdināju, ka jūs krītat kā dārgs trauks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Un tie gani nevarēs izbēgt, un tā ganāmā pulka lepnie neizmuks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Klau! Gani brēc un ganāmā pulka lepnie kauc, jo Tas Kungs viņu ganību postījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Un miera lauki taps postīti caur Tā Kunga bardzības karstumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Viņš kā jauns lauva atstājis Savu dzīvokli; jo viņu zeme ir tapusi par posta vietu caur to briesmīgo dusmību un Viņa bardzības karstumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Jojaķima, Josijas dēla, Jūda ķēniņa, valdīšanas iesākumā šis vārds no Tā Kunga notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Tā saka Tas Kungs: stājies Tā Kunga nama pagalmā, un runā uz visām Jūda pilsētām, kas nāk pielūgt Tā Kunga namā, visus vārdus, ko Es tev esmu pavēlējis uz tiem runāt, neatrauj ne vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Varbūt tie klausīs un atgriezīsies ikviens no sava niknā ceļa, tad Man arī būs žēl tā ļaunuma, ko Es tiem domāju darīt viņu darbu ļaunuma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Saki tad uz tiem: tā saka Tas Kungs: ja jūs Man neklausīsiet un nestaigāsiet Manā bauslībā, ko Es jums esmu devis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Ka jūs klausiet Manu kalpu, to praviešu, vārdiem, ko Es vienmēr pie jums sūtu vienā sūtīšanā, kam jūs taču neesat klausījuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Tad Es šo namu darīšu tā kā Šīlo, un šo pilsētu Es likšu par lāstu visām zemes tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Un priesteri un pravieši un visi ļaudis dzirdēja Jeremiju šos vārdus runājam Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Kad Jeremija bija pabeidzis visu runāt, ko Tas Kungs bija pavēlējis runāt uz visiem ļaudīm, tad priesteri un pravieši un visi ļaudis viņu sagrāba un sacīja: tiešām, mirt tev jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Kā tu drīksti Tā Kunga Vārdā sludināt un sacīt: šis nams būs tā kā Šīlo, šī pilsēta būs postā bez iedzīvotāja! Un visi ļaudis sapulcējās pret Jeremiju Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Kad nu Jūda lielkungi to dzirdēja, tad tie nogāja no ķēniņa nama uz Tā Kunga namu un apsēdās priekš Tā Kunga jauno vārtu durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Tad tie priesteri un tie pravieši runāja uz tiem lielkungiem un uz visiem ļaudīm un sacīja: šis vīrs ir nāvi pelnījis, jo viņš pret šo pilsētu ir sludinājis, kā jūs savām ausīm dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Bet Jeremija runāja uz visiem lielkungiem un uz visiem ļaudīm un sacīja: Tas Kungs mani sūtījis, sludināt pret šo namu un pret šo pilsētu visus vārdus, ko jūs esat dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Nu tad, griežaties uz labiem ceļiem un pie labiem darbiem, un paklausiet Tā Kunga, sava Dieva, balsij, tad Tam Kungam būs žēl tā ļaunuma, ko Viņš pret jums runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Bet es, redzi, es esmu jūsu rokās, dariet man, kā jūsu acīs labi un pareizi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Bet tomēr ziniet, kad jūs mani nokausiet, tad jūs nenoziedzīgas asinis krāsiet uz sevi un uz šo pilsētu un uz viņas iedzīvotājiem, jo Tas Kungs mani patiesi pie jums sūtījis, visus šos vārdus runāt jūsu ausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Tad tie lielkungi un visi ļaudis sacīja uz tiem priesteriem un uz tiem praviešiem: pie šā vīra nav nāves vainas, jo viņš uz mums runājis Tā Kunga, mūsu Dieva, vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Arī citi vīri no zemes vecajiem cēlās un runāja uz visu ļaužu draudzi un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Miha no Marezas ir sludinājis Hizkijas, Jūda ķēniņa dienās, un uz visiem Jūda ļaudīm runājis un sacījis: tā saka Tas Kungs Cebaot: Ciāna taps arta kā tīrums, un Jeruzāleme būs par akmeņu kopu, un šā nama kalns taps par meža kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Vai Hizkija, Jūda ķēniņš, un visa Jūda cilts viņu nokāvuši? Vai viņš nebijās To Kungu un nepielūdza Tā Kunga priekšā. Tad Tam Kungam bija žēl tā ļaunuma, ko Viņš pret tiem bija runājis. Un vai mēs lai darām lielu ļaunumu pret savām dvēselēm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Un atkal viens vīrs bija sludinājis Tā Kunga Vārdā, Ūrija, Šemajas dēls, no KiriatIearimas, un tas sludināja pret šo pilsētu un šo zemi ar tādiem pat vārdiem kā Jeremija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Kad nu ķēniņš Jojaķims un visi viņa varenie un visi lielkungi viņa vārdus dzirdēja, tad ķēniņš viņu meklēja nokaut. Bet Ūrija to dzirdējis bijās un bēga un nāca uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Bet ķēniņš Jojaķims sūtīja vīrus uz Ēģiptes zemi, Elnatanu, Akbora dēlu, un citus vīrus uz Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Tie izveda Ūriju no Ēģiptes un atveda pie ķēniņa Jojaķima, un tas viņu nokāva ar zobenu, un meta viņa miesas zemu ļaužu kapos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Bet Aīkama, Safana dēla, roka bija ar Jeremiju, ka viņš tiem ļaudīm netapa rokā dots, viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Jojaķima (Cedeķijas), Josijas dēla, Jūda ķēniņa valdīšanas iesākumā šis vārds no Tā Kunga notika uz Jeremiju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Tā saka Tas Kungs uz mani: taisi sev saites un jūgus un liec tos pie sava kakla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Un sūti tos pie Edoma ķēniņa, pie Moaba ķēniņa, pie Amona bērnu ķēniņa un pie Tirus ķēniņa un pie Sidonas ķēniņa ar tiem vēstnešiem, kas nākuši uz Jeruzālemi pie Jūda ķēniņa Cedeķijas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Un pavēli tiem sacīt uz saviem kungiem: tā saka Tas Kungs Cebaot, Israēla Dievs: tā jums saviem kungiem būs sacīt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Es esmu radījis zemi un cilvēkus un lopus, kas virs zemes, ar Savu lielo spēku un ar Savu izstiepto elkoni, un Es to dodu tam, kas Manām acīm patiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Nu tad visas šās zemes Es dodu rokā Nebukadnecaram, Bābeles ķēniņam, Savam kalpam, un pat zvērus laukā Es dodu viņam kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Un visiem ļaudīm būs kalpot viņam un viņa dēlam un viņa dēla dēlam, tiekams laiks nāks arī viņa zemei, tad lielas tautas un lieli ķēniņi viņu sev kalpinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Un tos ļaudis un to valsti, kas viņam, Nebukadnecaram, Bābeles ķēniņam, nekalpos, un kas savu kaklu negribēs likt apakš Bābeles ķēniņa jūga, to tautu Es piemeklēšu ar zobenu un ar badu un ar mēri, saka Tas Kungs, tiekams Es tos būšu izdeldējis caur viņa roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Jūs tad neklausiet saviem praviešiem un saviem zīlniekiem un saviem sapņotājiem un saviem vārdotājiem un saviem burvjiem, kas uz jums runā un saka: jūs nekalposiet Bābeles ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Jo tie jums sludina melus, lai Es jūs tālu aizvedu no jūsu zemes, un lai Es jūs izdzenu, un lai jūs ejat bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Bet tiem ļaudīm, kas savu kaklu pados Bābeles ķēniņa jūgam un viņam kalpos, tiem Es likšu palikt savā zemē, saka Tas Kungs, un tie to apkops un tur dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Un Es runāju pēc visiem šiem vārdiem uz ķēniņu Cedeķiju, Jūda ķēniņu, un sacīju: padodiet savus kaklus Bābeles ķēniņa jūgam un kalpojiet viņam un viņa ļaudīm, tad jūs dzīvosiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Kāpēc jūs gribat mirt, tu un tavi ļaudis, caur zobenu, caur badu un caur mēri, kā Tas Kungs runājis par tiem ļaudīm, kas Bābeles ķēniņam nekalpos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Tad neklausiet to praviešu vārdiem, kas uz jums runā un saka: jūs nekalposiet Bābeles ķēniņam, - jo tie jums sludina melus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Jo Es tos neesmu sūtījis, saka Tas Kungs, un tie Manā Vārdā sludina melus, lai Es jūs izdzenu, un jūs ejat bojā, jūs un tie pravieši, kas jums sludina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Es runāju arī uz tiem priesteriem un uz visiem šiem ļaudīm un sacīju: tā saka Tas Kungs: neklausiet savu praviešu vārdiem, kas jums sludina un saka: redzi, Tā Kunga nama trauki drīz taps pārvesti no Bābeles, jo tie jums sludina melus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Neklausiet tiem, kalpojiet Bābeles ķēniņam, tad jūs dzīvosiet. Kāpēc tad šai pilsētai būs tapt postītai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Bet ja tie ir pravieši, un ja Tā Kunga vārds ir pie viņiem, tad lai tie jel To Kungu Cebaot pielūdz, ka tie trauki, kas Tā Kunga namā un Jūda ķēniņa namā un Jeruzālemē atlikuši, nenāk uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Jo tā saka Tas Kungs Cebaot par tiem pīlāriem un par to jūru un par tiem krēsliem un par tiem atlikušiem traukiem, kas šai pilsētā atlikuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Ko Nebukadnecars, Bābeles ķēniņš, nav paņēmis, kad viņš Jekaniju, Jojaķima dēlu, Jūda ķēniņu, no Jeruzālemes aizveda uz Bābeli līdz ar visiem Jūda un Jeruzālemes cienīgiem -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs, par tiem rīkiem, kas atlikuši Tā Kunga namā un Jūda ķēniņa namā un Jeruzālemē:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Tie taps aizvesti uz Bābeli, un tur tie būs līdz tai dienai, kad Es tos piemeklēšu, saka Tas Kungs, jo Es tos atvedīšu atpakaļ uz šo vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Un tanī gadā, Cedeķijas, Jūda ķēniņa, valdīšanas iesākumā, ceturtā gadā, piektā mēnesī, pravietis Kananija, Acura dēls, no Gibeonas, runāja uz mani Tā Kunga namā priekš priesteru un visu ļaužu acīm un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Tā runā Tas Kungs Cebaot, Israēla Dievs, un saka: Es Bābeles ķēniņa jūgu esmu salauzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Vēl būs divi pilni gadi, tad Es atkal uz šo vietu atvedīšu visus Tā Kunga nama rīkus, ko Nebukadnecars, Bābeles ķēniņš, ir paņēmis no šīs vietas un aizvedis uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Un Jekaniju, Jojaķima dēlu, Jūda ķēniņu, un visus no Jūda aizvestos, kas uz Bābeli nākuši, Es atvedīšu uz šo vietu, saka Tas Kungs, jo Es salauzīšu Bābeles ķēniņa jūgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Tad pravietis Jeremija sacīja uz pravieti Kananiju priekš priesteru un visu ļaužu acīm, kas tur stāvēja Tā Kunga namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Un pravietis Jeremija sacīja: Āmen! Tā lai Tas Kungs dara, lai Tas Kungs tavus vārdus apstiprina, ko tu esi sludinājis, ka Viņš atved Dieva nama rīkus un visus aizvestos no Bābeles atkal uz šo vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Bet klausi jel šo vārdu, ko es runāšu priekš tavām ausīm un priekš visu ļaužu ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Tie pravieši, kas no sen laikiem priekš manis un priekš tevis bijuši, tie pret daudz zemēm un lielām valstīm sludinājuši par karu un par postu un par mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Bet tas pravietis, kas mieru sludina, kad tā pravieša vārds notiek, tiks atzīts par pravieti, ko Tas Kungs tiešām sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Tad pravietis Kananija ņēma to jūgu no pravieša Jeremijas kakla un to salauza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Un Kananija runāja priekš visu ļaužu acīm un sacīja: tā saka Tas Kungs: tāpat Es salauzīšu Nebukadnecara, Bābeles ķēniņa, jūgu, no visu ļaužu kakla, pirms divi gadi būs pagalam. Un pravietis Jeremija gāja savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Tad Tā Kunga vārds notika uz Jeremiju, kad pravietis Kananija to jūgu no pravieša Jeremijas kakla bija salauzis, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Ej un runā uz Kananiju un saki: tā saka Tas Kungs: koka jūgus tu esi salauzis, bet viņu vietā taisījis dzelzs jūgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs: dzelzs jūgu Es visiem šiem ļaudīm esmu licis ap kaklu, ka tiem būs kalpot Nebukadnecaram, Bābeles ķēniņam, un tiem būs viņam kalpot, jo pat zvērus laukā Es viņam esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Un pravietis Jeremija sacīja uz pravieti Kananiju: klausi jel, Kananija! Tas Kungs tevi nav sūtījis, un tu dari, ka šie ļaudis paļaujas uz meliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Tādēļ Tas Kungs tā saka: redzi! Es tevi atmetīšu no zemes virsas; šinī gadā tu mirsi, jo tu esi mācījis atkāpties no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Tā pravietis Kananija nomira tanī gadā, septītā mēnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Un šie ir tās grāmatas vārdi, ko pravietis Jeremija sūtīja no Jeruzālemes tiem atlikušiem vecajiem, kas bija aizvesti, un tiem priesteriem un tiem praviešiem un visiem ļaudīm, ko Nebukadnecars no Jeruzālemes bija aizvedis uz Bābeli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Kad ķēniņš Jekanija un ķēniņiene un ķēniņa sulaiņi un Jūda un Jeruzālemes lielkungi līdz ar tiem amatniekiem un kalējiem no Jeruzālemes bija projām, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Caur Eleazu, Safana dēlu, un Gemariju, Hilķijas dēlu, ko Cedeķija, Jūda ķēniņš, uz Bābeli sūtīja pie Nebukadnecara, Bābeles ķēniņa:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Tā saka Tas Kungs Cebaot, Israēla Dievs, uz visiem aizvestiem, kas no Jeruzālemes aizvesti uz Bābeli:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Uztaisiet namus un dzīvojiet iekš tiem un dēstiet dārzus un ēdiet no viņu augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Ņemiet sievas un dzemdinājiet dēlus un meitas un vediet saviem dēliem sievas un dodiet savas meitas vīriem, lai tās dzemdē dēlus un meitas, un vairojaties tur un neejat mazumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Un meklējiet tās pilsētas labklāšanos, kurp Es jūs esmu licis aizvest, un pielūdziet To Kungu viņas dēļ, jo kad viņai labi klāsies, tad arī jums labi klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs: lai jūsu pravieši un jūsu zīlnieki, kas jūsu vidū, jūs nepieviļ, un neklausiet saviem sapņiem, ko jūs sapņojat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Jo tie jums sludina melus Manā Vārdā; Es tos neesmu sūtījis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Jo tā saka Tas Kungs: tiešām, kad septiņdesmit gadi Bābelē būs pagalam, tad Es jūs piemeklēšu un jums likšu notikt pēc Sava žēlīgā vārda un jūs atvedīšu atpakaļ uz šo vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Jo Es zinu, kādas domas Es par jums domāju, saka Tas Kungs: miera domas un ne ļaunas domas, ka Es jums dodu to cerēto galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Tad jūs Mani piesauksiet un iesiet un Mani pielūgsiet, un Es jūs paklausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Un jūs meklēsiet un Mani atradīsiet, kad jūs pēc Manis vaicāsiet no visas savas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Un Es no jums likšos atrasties, saka Tas Kungs, un atgriezīšu (atpakaļ no) jūsu cietuma un jūs sapulcināšu no visām tautām un no visām vietām, kurp Es jūs esmu aizdzinis, saka Tas Kungs, un jūs vedīšu atkal uz to vietu, no kurienes Es jūs esmu licis aizvest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Kad jūs sakāt: Tas Kungs mums Bābelē praviešus cēlis -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Tiešām, tā saka Tas Kungs, par to ķēniņu, kas sēž uz Dāvida goda krēsla, un par visiem ļaudīm, kas šai pilsētā dzīvo, par jūsu brāļiem, kas ar jums nav gājuši cietumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Tā saka Tas Kungs Cebaot: redzi, Es sūtīšu starp viņiem zobenu, badu un mēri, un darīšu tos kā nelāga vīģes, ko nevar ēst aiz nelāguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Un Es tiem dzīšos pakaļ ar zobenu, ar badu un ar mēri, un tos nodošu uz vārdzināšanu visās zemes valstīs, par lāstu, par biedēkli un par apsmieklu un par negodu starp visām tautām, kurp Es tos aizdzīšu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Par to, ka tie Maniem vārdiem nav klausījuši, saka Tas Kungs, kad Es Savus kalpus, tos praviešus, pie tiem tikuši(neatlaidīgi) sūtīju vienā sūtīšanā; bet jūs neesat klausījuši, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Tad klausiet Tā Kunga vārdu, jūs visi, kas esat aizvesti, ko Es no Jeruzālemes uz Bābeli esmu nosūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tā saka Tas Kungs Cebaot, Israēla Dievs, pret Ahabu, Kolajas dēlu, un pret Cedeķiju, Mazejas dēlu, kas jums melus sludina Manā Vārdā! Redzi, Es tos nodošu Nebukadnecaram, Bābeles ķēniņam, rokā, tas tos sitīs priekš jūsu acīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Un no tiem celsies lāstu vārdi pie visiem no Jūda aizvestiem, kas ir Bābelē, un sacīs: lai Tas Kungs tev dara kā Cedeķijam un kā Ahabam, ko Bābeles ķēniņš pie uguns cepis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Tādēļ ka tie ģeķību darījuši iekš Israēla un laulību pārkāpuši ar savu tuvāko sievām un runājuši melu vārdus Manā Vārdā, ko Es tiem nebiju pavēlējis, un Es esmu Tas, kas to zin un apliecina, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Un pret Nekalamieti Šemaju runā un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Tā runā Tas Kungs Cebaot, Israēla Dievs, un saka: tādēļ, ka tu grāmatas sūtījis savā vārdā visiem ļaudīm Jeruzālemē un priesterim Cefanijam, Mazejas dēlam, un visiem priesteriem ar tiem vārdiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Tas Kungs tevi licis par priesteri priestera Jojadas vietā, ka jums būs uzraugiem būt Tā Kunga namā pār ikkatru vīru, kas trako un sevi par pravieti turas, ka tev tos būs likt cietumā un siekstā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Nu tad, kāpēc tu Jeremiju no Anatotas neesi aprājis, kas jūsu starpā turas par pravieti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Tāpēc ka viņš pie mums uz Bābeli sūtījis un sacījis: būs ilgi, uztaisiet namus un dzīvojiet un dēstiet dārzus un ēdiet viņu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Un priesteris Cefanija lasīja šo grāmatu priekš pravieša Jeremijas ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Tad Tā Kunga vārds tā notika uz Jeremiju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Sūti jel pie visiem aizvestiem un saki: tā saka Tas Kungs pret Nekalamieti Šemaju: tādēļ ka Šemaja jums ir sludinājis, un Es to neesmu sūtījis, un ir darījis, ka jūs paļaujaties uz meliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Tādēļ Tas Kungs tā saka: redzi, Es piemeklēšu Nekalamieti Šemaju un viņa dzimumu; viņam neviena nebūs, kas šo ļaužu vidū dzīvos un redzēs to labumu, ko Es Saviem ļaudīm darīšu, saka Tas Kungs, jo viņš ir mācījis atkāpties no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Šis ir tas vārds, kas notika uz Jeremiju no Tā Kunga sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Tā runā Tas Kungs, Israēla Dievs, un saka: raksti sev grāmatā visus šos vārdus, ko Es uz tevi esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Jo redzi, nāks dienas, saka Tas Kungs, ka Es vedīšu atpakaļ Savu Israēla ļaužu un Jūda cietumniekus, saka Tas Kungs; un Es tos vedīšu atpakaļ uz to zemi, ko Es viņu tēviem esmu devis, to iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Un šie ir tie vārdi, ko Tas Kungs runājis par Israēli un par Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Jo tā saka Tas Kungs: mēs dzirdam briesmu balsi, tur ir bailes un nemiers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Vaicājiet jel un raugāt, vai vīrietis dzemdē? Kāpēc tad es redzu, ka ikkatrs vīrs savas rokas uz ciskām tura, tā kā sieva, kas dzemdē, un visi vaigi palikuši bāli?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ak vai! Jo tā diena ir tik liela, ka citas tādas nav, un tas ir Jēkaba bēdu laiks; tomēr viņš no tā taps izpestīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Jo notiks tai dienā, saka Tas Kungs Cebaot, ka Es nolauzīšu viņa jūgu no tava kakla un saraustīšu tavas saites, ka sveši viņu vairs nekalpinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Bet tie kalpos Tam Kungam, savam Dievam, un Dāvidam, savam ķēniņam, ko Es tiem celšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Bet tu nebīsties, Mans kalps Jēkab, saka Tas Kungs, un nebaiļojies, Israēl. Jo redzi, Es tevi izpestīšu no tās tālās zemes, un tavu dzimumu no viņa cietuma zemes, un Jēkabs pārnāks un dzīvos mierīgi un droši un neviens viņu netraucēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Jo Es esmu pie tevis, saka Tas Kungs, ka Es tevi izglābju. Jo Es daru galu visiem pagāniem, kurp Es tevi esmu izklīdinājis, bet tev Es nedarīšu galu, bet Es tevi pārmācīšu pēc taisnības, un nepārmācītu tevi nepametīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Jo tā saka Tas Kungs: tava vaina ir nāvīga, tava vāts nav dziedinājama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Neviena nav, kas tavu vainu pārrauga un aizsien: dziedinājamas zāles tev nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Visi tavi mīļotāji tevi aizmirsuši, tie nevaicā pēc tevis; jo Es tevi esmu sitis ar ienaidnieka sitieniem, ar briesmīgu pārmācīšanu tavu daudzo noziegumu dēļ tāpēc ka tavu grēku ļoti daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Ko tu kliedz par savu vainu, un ka tavas sāpes ir nāvīgas? Tavas lielās noziedzības dēļ ka tavu grēku ir ļoti daudz, Es tev to esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Tādēļ visi, kas tevi rij, taps aprīti, un visi tavi pretinieki, tie visi ies cietumā, un kas tevi aplaupa, būs paši par laupījumu, un visi, kas tevi posta, tos Es nodošu, ka taps izpostīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Jo Es atkal aizsiešu tavas vātis un dziedināšu tavas vainas, saka Tas Kungs, tāpēc ka tie tevi nosauc par aizdzītu: „šī ir Ciāna, neviens pēc tās nevaicā“.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Tā saka Tas Kungs: redzi, Es vedīšu atpakaļ Jēkaba dzīvokļu cietumniekus un apžēlošos par viņa mājas vietām, un tā pilsēta taps uztaisīta uz sava kalna, un tas augstais nams stāvēs savā vecā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Un no tiem izies pateikšana un līksmošanās balss, un Es tiem likšu vairumā iet un ne mazumā, un Es tos pagodināšu, ka vairs nebūs nievājami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Un viņa dēli būs kā citkārt, un viņa draudze Manā priekšā pastāvēs, un Es piemeklēšu visus viņa spaidītājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Un viņa cienīgais būs no viņa, un viņa valdnieks nāks no viņa vidus, un Es viņam likšu nākt tuvu, un viņš nāks pie Manis klāt. Jo kas tas tāds, kas iedrošinātos Man tuvoties? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Un jūs Man būsiet par ļaudīm, un Es jums būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Redzi, vētra no Tā Kunga celsies ar bardzību, briesmīga vētra, tā gāzīsies bezdievīgiem uz galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Tā Kunga bardzības karstums nemitēsies, tiekams Viņš izdarīs un piepildīs Savas sirds domas. Nākamās dienās jūs gan to samanīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Tanī laikā, saka Tas Kungs, Es visām Israēla ciltīm būšu par Dievu, un tās Man būs par ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Tā saka Tas Kungs: Tie ļaudis, kas atlikuši no zobena, atraduši žēlastību tuksnesī; Es iešu, Israēli vest pie dusas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Tas Kungs man parādījies no tālienes: Es tevi esmu mīļojis ar mūžīgu mīlestību, tādēļ Es tevi žēlīgi esmu vilcis pie Sevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Es tevi atkal uztaisīšu, un tu tapsi uzcelta, Israēla meita! Tu atkal pušķosies ar savām bungām un iziesi priecīgi diedama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Tu atkal dēstīsi vīna dārzus Samarijas kalnos, dēstītāji tos dēstīs un droši baudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Jo būs diena, kad sargi sauks uz Efraīma kalniem: ceļaties, ejam augšā uz Ciānu pie Tā Kunga, mūsu Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Jo tā saka Tas Kungs: sauciet par Jēkabu ar līksmību un gavilējiet par tautu galvu, sludinājiet, teiciet un sakiet: ak Kungs, pestī Savus ļaudis, Israēla atlikušos!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Redzi, Es tos atvedīšu no ziemeļu zemes un tos sapulcināšu no zemes galiem; viņu starpā būs akli un tizli, grūtas un dzemdētājas kopā, lielā pulkā tie šurp atgriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Tie nāks ar raudāšanu, un ar pielūgšanu Es tos gribu vest un vadīt pie ūdens strautiem pa līdzenu ceļu, kur tie nepaklups; jo Es esmu Israēlim palicis par tēvu un Efraīms ir Mans pirmdzimtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Klausiet Tā Kunga vārdu, jūs tautas, un sludiniet pa tām salām, kas tālu, un sakāt: kas Israēli izklīdinājis, Tas viņu atkal sapulcinās un to sargās kā gans savu ganāmo pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Jo Tas Kungs Jēkabu atpircis un viņu izglābis no rokas, kas bija stiprāka nekā viņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Un tie nāks un gavilēs Ciānas kalnā un plūdīs pie Tā Kunga dāvanām, pie labības un pie vīna un pie eļļas un pie jauniem jēriem un vēršiem, un viņu dvēsele būs kā mitrs dārzs, un tie vairs nebūs noskumuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Tad jaunava priecāsies diedama un jaunekļi un sirmgalvji kopā. Jo Es pārvērtīšu viņu skumību par prieku un tos iepriecināšu un ielīksmošu pēc viņu noskumšanas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Un Es mielošu priesteru dvēseli ar taukumiem, un Mani ļaudis taps pieēdināti ar Manu labumu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Tā saka Tas Kungs: brēkšana ir dzirdama Rāmā, žēlošanās un gauža raudāšana; Rahēle apraud savus bērnus, un negribās iepriecinājuma par saviem bērniem, jo to vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Tā saka Tas Kungs: atrauj savu balsi no raudāšanas un savas acis no asarām, jo tur ir alga tavam darbam, saka Tas Kungs; tie atgriezīsies no ienaidnieka zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Un cerība ir tavai nākamībai, saka Tas Kungs: jo tavi bērni nāks atpakaļ savās robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Es klausīt esmu klausījies, ka Efraīms žēlojās: Tu mani esi pārmācījis, un es esmu pārmācīts kā nevaldāms teļš. Atgriez mani, tad es atgriezīšos. Jo Tu, Kungs, esi mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Tiešām, kad es nogriezos, tad man nāca žēlums, un kad es to atzinu, tad es situ uz saviem gurniem, jo es esmu apkaunots un kaunā tapis, nesdams savas jaunības negodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Vai Efraīms Man nav dārgs dēls un mīļš bērns, ka cikkārt Es par viņu runāju, pieminēdams Es viņu pieminu? Tāpēc Mana sirds trīc par viņu, ka Es apžēlodamies par viņu apžēlojos, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Uzcel sev stabus, liec sev zīmes, un ņem vērā to ceļu, ko tu staigājis: Griezies atpakaļ, Israēla meita, griezies atpakaļ uz šīm savām pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Cik ilgi tu maldīsies, tu atkāpēja meita? Jo Tas Kungs ir radījis ko jaunu virs zemes: sieva būs ap vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: “šo vārdu tie vēl runās Jūda zemē un viņas pilsētās, kad Es atpakaļ vedīšu viņa cietumniekus: lai Tas Kungs tevi svētī, tu taisnības mājokli, tu svētais kalns!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Un Jūda ar visām savām pilsētām kopā tur dzīvos, arāji un kas staigā ar ganāmiem pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Jo Es dzirdināšu iztvīkušo dvēseli un atspirdzināšu ikkatru noskumušu dvēseli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Tāpēc es uzmodos un skatījos, un mans miegs man bija gards.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Redzi, nāks dienas, saka Tas Kungs, ka Es Israēla namu un Jūda namu augļošu ar cilvēku dzimumu un ar lopu dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Un kā Es pret tiem esmu bijis nomodā, tos izraudams un nolauzdams un postīdams un samaitādams un mocīdams, tā Es par tiem gribu nomodā būt, tos uztaisīdams un dēstīdams, saka Tas Kungs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Tanīs dienās vairs nesacīs: tēvi ēduši skābas vīnogas, un bērniem zobi apmizējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Bet ikvienam sava nozieguma dēļ būs mirt, ikviens cilvēks, kas ēd skābas vīnogas, tam zobi apmizēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Redzi, nāks dienas, saka Tas Kungs, ka Es jaunu derību celšu ar Israēla namu un ar Jūda namu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Ne tādu derību, kā esmu cēlis ar viņu tēviem, kad tos pie rokas satvēru un izvedu no Ēģiptes zemes; to Manu derību tie iznīcinājuši, tad Es arīdzan par tiem neesmu bēdājis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Bet šī ir tā derība, ko Es ar Israēla namu celšu pēc šīm dienām, saka Tas Kungs: Es došu Savu bauslību viņu prātā un to rakstīšu viņu sirdī, un Es tiem būšu par Dievu, un tie Man būs par tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Un tad draugs draugu vairs nemācīs nedz brālis brāli, sacīdams: atzīstiet To Kungu! Jo tie visi Mani atzīs, ir viņu mazie, ir viņu lielie, saka Tas Kungs. Jo Es piedošu viņu noziegumus un nepieminēšu vairs viņu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Tā saka Tas Kungs, kas sauli dienā dod pār spīdekli, mēnesi un zvaigznes pēc saviem likumiem par spīdekļiem naktī, kas jūru kustina, ka viņas viļņi kauc, Kungs Cebaot ir Viņa vārds:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Kad šie likumi Manā priekšā zudīs, saka Tas Kungs, tad arī Israēla dzimums zudīs, ka nebūs vairs tauta Manā priekšā mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Tā saka Tas Kungs: Kad debesis augšām varēs mērot un zemes dibenus apakšā varēs izmanīt, tad Es arī atmetīšu visu Israēla dzimumu, visa tā dēļ, ko tie darījuši, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Redzi, nāks dienas, saka Tas Kungs, ka šī pilsēta Tam Kungam taps uzcelta no Hananeēļa torņa līdz stūru vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Un mēra aukla izstiepsies tālāki uz priekšu līdz Gāreba pakalnam un griezīsies uz Goātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Un visa miroņu un pelnu ieleja, un visi tīrumi līdz Kidronas upei, līdz zirgu vārtu stūrim pret rītiem, būs Tam Kungam svēti; tur vairs neko neizdeldēs nedz nolauzīs ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Šis ir tas vārds, kas uz Jeremiju notika no Tā Kunga, Cedeķijas, Jūda ķēniņa, desmitā gadā, - šis gads bija Nebukadnecara astoņpadsmitais gads.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'To brīdi Bābeles ķēniņa karaspēks bija apmeties pret Jeruzālemi, un pravietis Jeremija bija ieslēgts cietuma pagalmā Jūda ķēniņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Jo Cedeķija, Jūda ķēniņš, viņu bija cietumā ieslēdzis un sacījis: Kāpēc tu sludini un saki: tā saka Tas Kungs: redzi, Es nododu šo pilsētu Bābeles ķēniņa rokā, un viņš to uzņems,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Un Cedeķija, Jūda ķēniņš, neizspruks no Kaldeju rokas, bet viņš tiešām taps nodots Bābeles ķēniņa rokā, un viņš to bildinās muti pret muti un to redzēs aci pret aci,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Un tas novedīs Cedeķiju uz Bābeli, un tur viņš paliks, kamēr Es viņu piemeklēšu, saka Tas Kungs. Jo kad jūs pret Kaldejiem karosiet, tad tas jums labi neizdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Un Jeremija sacīja: Tā Kunga vārds uz mani tā noticis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Redzi, Hanameēls, tava tēva brāļa Šaluma dēls, nāks pie tevis un sacīs: pērc manu tīrumu Anatotā; jo tev krīt atpirkšanas tiesa, viņu pirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Un Hanameēls, mana tēva brāļa dēls, nāca pie manis cietuma pagalmā pēc Tā Kunga vārda un sacīja uz mani: pērc jel manu tīrumu, kas ir Anatotā Benjamina zemē, jo tev krīt mantošanas un atpirkšanas tiesa, pērc to sev.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Tad es nomanīju, ka tas bija Tā Kunga vārds, un es pirku no Hanameēļa, sava tēva brāļa dēla, to tīrumu Anatotā, un es viņam iesvēru to naudu, septiņus sēķeļus un desmit sudraba gabalus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Un es rakstīju to grāmatā un to aizzieģelēju un to liku apliecināt caur lieciniekiem un iesvēru to naudu uz svariem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Un es paņēmu to aizzieģelēto pirkšanas norakstu, pirkšanas grāmatu ar to norunu un nosacījumu, un arī to neaizzieģelēto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Un es devu to pirkšanas norakstu Bārukam, Nerijas, Makazejas dēla, dēlam priekš Hanameēļa, sava tēva brāļa, acīm, un priekš to liecinieku acīm, kas bija parakstījušies pirkšanas norakstā un priekš visu Jūdu acīm, kas sēdēja cietuma pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Un es pavēlēju Bārukam priekš viņu acīm un sacīju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: ņem šos rakstus, šo pirkšanas norakstu, to aizzieģelēto, un šo neaizzieģelēto norakstu, un liec tos mālu traukā, ka tie ilgi var pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs: vēl šai zemē taps pirkti nami un tīrumi un vīna dārzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Un es pielūdzu To Kungu, kad es to pirkšanas norakstu biju devis Bārukam, Nerijas dēlam, un sacīju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Kungs, redzi, debesis un zemi Tu esi radījis ar Savu lielo spēku un ar Savu izstiepto elkoni, Tev nekas nav neiespējams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Tu dari žēlastību pie tūkstošiem un atmaksā tēvu noziegumu uz viņu bērnu galvām pēc viņiem, tu lielais un varenais Dievs, kam vārds ir Kungs Cebaot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Liels padomā un varens darbos; jo Tavas acis ir atvērā pār visiem cilvēku bērnu ceļiem, ikvienam dot pēc viņa ceļiem un pēc viņa darbu augļiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Zīmes un brīnumus Tu esi darījis Ēģiptes zemē līdz šai dienai, gan pie Israēla, gan pie (citiem) cilvēkiem, un esi Sev vārdu cēlis, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Un Savus Israēla ļaudis Tu esi izvedis no Ēģiptes zemes ar zīmēm un brīnumiem un ar stipru roku un izstieptu elkoni un lielām briesmām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Un tiem esi devis šo zemi, ko Tu viņu tēviem biji zvērējis, tiem to dot, zemi, kur piens un medus tek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Un tie ir nākuši un to iemantojuši, bet Tavu balsi tie nav klausījuši un Tavā bauslībā tie nav staigājuši; neko, ko Tu viņiem esi pavēlējis darīt, tie nav darījuši; tad Tu visam šim ļaunumam esi licis nākt pār viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Redzi, tie valņi nākuši līdz pat pilsētai, to uzņemt, un tā pilsēta caur zobenu un badu un mēri taps dota Kaldeju roka, kas pret to karo, un ko Tu esi runājis, tas tā noticis, un raugi, Tu pats to redzi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Un tomēr Tu, Kungs, Dievs, uz mani esi sacījis: pērc sev tīrumu par naudu, un lai liecinieki to apliecina, jebšu tā pilsēta ir dota Kaldeju rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Tad Tā Kunga vārds tā notika uz Jeremiju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Redzi, Es esmu Tas Kungs, Dievs pār visu miesu. Vai kāda lieta Man neiespējama?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Tāpēc tā saka Tas Kungs: redzi, Es šo pilsētu nododu Kaldeju rokā, Bābeles ķēniņa Nebukadnecara rokā, un viņš to uzņems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Un Kaldeji, kas pret šo pilsētu karo, nāks un iededzinās šo pilsētu ar uguni un to sadedzinās līdz ar tiem namiem, uz kuru jumtiem tie kvēpinājuši Baālam un citiem dieviem upurējuši dzeramus upurus, mani kaitinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Jo Israēla bērni un Jūda bērni ir darījuši tikai, kas ļauns Manās acīs, no savas jaunības, tiešām, Israēla bērni Mani tikai kaitinājuši ar savu roku darbiem, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Jo šī pilsēta Mani ir kaitinājusi uz dusmību un uz bardzību no tās dienas, kad tie to cēluši līdz šai dienai, tā ka tā Man jāatmet no Mana vaiga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Visa Israēla bērnu un Jūda bērnu ļaunuma dēļ ko tie darījuši, Mani kaitinādami, viņi, viņu ķēniņi, viņu lielkungi, viņu priesteri un viņu pravieši un Jūda vīri un Jeruzālemes iedzīvotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Tie Man griezuši muguru un ne vaigu. Jebšu Es tos vienmēr pamācīju vienā mācīšanā, tomēr tie neklausīja, mācību pieņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Bet tie savas negantības ir likuši tai namā, kas pēc Mana Vārda nosaukts, to sagānīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Un tie ir altārus cēluši Baālam Ben-Inoma ielejā, un savus dēlus un savas meitas tie upurējuši Molokam, ko Es tiem neesmu pavēlējis un kas nav nācis Manā sirdī, ka tiem bija šo negantību darīt un Jūdu apgrēcināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Un nu tāpēc Tas Kungs, Israēla Dievs, tā saka par to pilsētu, par ko jūs sakāt: tā ir Bābeles ķēniņam rokā dota caur zobenu un caur badu un caur mēri:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Redzi, Es tos sapulcināšu no visām zemēm, kurp tos esmu aizdzinis Savā karstumā un Savā bardzībā un Savā lielā dusmībā, un tos vedīšu atpakaļ uz šo vietu, un tiem likšu dzīvot bez bailēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Un tie Man būs par tautu, un Es tiem būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Un Es tiem došu vienādu sirdi un vienādu ceļu, ka tie Mani bīstas visu savu mūžu, sev pašiem par labu un saviem bērniem pēc viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Un Es ar tiem derēšu mūžīgu derību, ka Es negribu mitēties labu darīt, un Es Savu bijāšanu viņiem došu sirdī, ka tie no Manis neatkāpjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Un Es priecāšos viņiem labu darīt, un Es tos šai zeme dēstīšu uzticībā, no visas Savas sirds un no visas Savas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Jo tā saka Tas Kungs: (Tā) kā Es šiem ļaudīm esmu uzvedis visu šo lielo ļaunumu, tā Es tiem atvedīšu visu labu, ko Es par tiem runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Un tīrumi taps pirkti šai zemē, par ko jūs sakāt: tā ir postaža bez cilvēka un lopa, tā ir dota Kaldejiem rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Tīrumi taps par naudu pirkti un grāmatas rakstītas un aizzieģelētas, un liecinieki to apliecinās Benjaminas zemē un ap Jeruzālemi un pa Jūda pilsētām un pa kalnu pilsētām un pa ielejas pilsētām un pa dienvidu(Negebas) pilsētām; jo Es vedīšu atpakaļ viņu cietumniekus, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Un Tā Kunga vārds notika uz Jeremiju otru reizi, kad viņš vēl bija ieslēgts cietuma pagalmā, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Tā saka Tas Kungs, kas to dara, Tas Kungs, kas to izdara, lai tas notiek - Kungs ir viņa vārds -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Piesauc Mani, tad Es tev atbildēšu un tev darīšu zināmas lielas un brīnišķas lietas, ko tu nezini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Jo tā saka Tas Kungs, Israēla Dievs, par šīs pilsētas namiem un par Jūda ķēniņa namiem, kas tiek nolauzīti vaļņu un zobena priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Par tiem, kas nāk karot pret Kaldejiem, lai tos (namus) pilda ar miroņu miesām, ko Es nokauju Savā bardzībā un Savā dusmībā, un tādēļ ka Es Savu vaigu no šīs pilsētas esmu apslēpis, visa viņu ļaunuma dēļ:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Redzi, Es to sasiešu un dziedināšu, un tos darīšu veselus, un tiem parādīšu pilnīgu un pastāvīgu laimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Un Es vedīšu atpakaļ Jūda cietumniekus un Israēla cietumniekus, un tos uztaisīšu tā kā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Un Es tos šķīstīšu no visa viņu nozieguma, ar ko tie pret Mani grēkojuši, un Es tiem piedošu visus viņu pārkāpumus, ar ko tie pret Mani grēkojuši un ar ko tie no Manis atkāpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Un tad(Jeruzāleme) Man būs par prieka vārdu, par slavu un par godu pie visām tautām virs zemes, kas dzirdēs visu to labumu, ko Es tiem daru, un tās bīsies un drebēs par visu to labumu un par visu to mieru, ko Es viņai dodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Tā saka Tas Kungs: šinī vietā, par ko jūs sakāt, tā ir postaža bez cilvēka un lopa, pa Jūda pilsētām un pa Jeruzālemes ielām, kas ir postītas, ka tur nav ne cilvēka, ne iedzīvotāja, ne lopa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Tur atkal dzirdēs prieka balsi un līksmības balsi, brūtgāna balsi un brūtes balsi, balsi no tiem, kas saka: teiciet To Kungu Cebaot, jo Tas Kungs ir labs, jo Viņa žēlastība paliek mūžīgi, - un kas nes pateicības upuri Tā Kunga namā. Jo Es vedīšu atpakaļ tās zemes cietumniekus kā papriekš, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Tā saka Tas Kungs Cebaot: šinī vietā, kas ir postaža bez cilvēka un lopa, un visās apkārtējās pilsētās būs atkal ganu dzīvokļi, kas ganīs ganāmus pulkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Pa kalnu pilsētām un lejas pilsētām un pa dienvidu(Negebas) pilsētām un Benjamina zemē un ap Jeruzālemi un pa Jūda pilsētām ganāmi pulki atkal ies apakš skaitītāju rokām, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Redzi, nāks dienas, saka Tas Kungs, ka Es piepildīšu to labo vārdu, ko Es esmu runājis uz Israēla namu un Jūda namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Tanīs dienās un tanī laikā Es Dāvidam likšu izplaukt taisnības Zaram, un tas darīs tiesu un taisnību virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Tanīs dienās Jūda taps atpestīts, un Jeruzāleme dzīvos bez bailēm, un šis ir tas (vārds), ar ko Viņu sauks: Tas Kungs mūsu taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Jo tā saka Tas Kungs: Dāvidam netrūks vīra, kas sēdēs Israēla nama goda krēslā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Arī priesteru, levitu netrūks Manā priekšā, kas upurē dedzināmos upurus un iededzina ēdamus upurus un sataisa kaujamus upurus mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Un Tā Kunga vārds notika uz Jeremiju un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Tā saka Tas Kungs: ja jūs varat iznīcināt Manu derību ar dienu un Manu derību ar nakti, ka dienas un nakts vairs nav savā laikā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Tad arī iznīks Mana derība ar Manu kalpu Dāvidu, ka tam dēla nebūs, kas valda uz viņa goda krēsla, un (Mana derība) ar levitiem, priesteriem, Maniem kalpotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Tā kā debess pulku nevar skaitīt un jūras smiltis nevar mērot, tāpat Es vairošu Sava kalpa Dāvida dzimumu un levitus, kas Man kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Un Tā Kunga vārds notika uz Jeremiju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Vai tu neredzi, ko šie ļaudis runā un saka? Tās divas ciltis, ko Tas Kungs bija izredzējis, Viņš nu atmetis, un tie nievā Manus ļaudis, tā kā tie vairs nebūtu tauta viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Tā saka Tas Kungs: ja Mana derība ar dienu un nakti nepastāv, ja Es debess un zemes likumus neesmu cēlis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Tad Es arī atmetīšu Jēkaba un Sava kalpa Dāvida dzimumu, ka neņemu no viņa dzimuma valdītājus pār Ābrahāma, Īzaka un Jēkaba dzimumu. Jo Es vedīšu atpakaļ viņu cietumniekus un apžēlošos par viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Šis ir tas vārds, kas uz Jeremiju notika no Tā Kunga, kad Nebukadnecars, Bābeles ķēniņš, un viss viņa karaspēks un visas pasaules valstis, kas bija apakš viņa valdīšanas, un visas tautas karoja pret Jeruzālemi un visām viņas pilsētām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Tā saka Tas Kungs, Israēla Dievs: ej un runā uz Cedeķiju, Jūda ķēniņu, un saki uz to: tā saka Tas Kungs: Redzi, Es šo pilsētu dodu Bābeles ķēniņam rokā, un viņš to sadedzinās ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Un tu neizbēgsi no viņa rokas, bet tapsi grābtin sagrābts un viņam dots rokā, un tavas acis redzēs Bābeles ķēniņa acis un viņš ar tevi runās muti pret muti un tu nāksi uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Bet klausi Tā Kunga vārdu, Cedeķija, Jūda ķēniņ! Tā saka Tas Kungs uz tevi: tu nemirsi caur zobenu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Tu nomirsi mierā. Un kā sārtu dedzinājuši taviem tēviem, tiem agrākajiem ķēniņiem, kas priekš tevis bijuši, tāpat tev dedzinās un par tevi žēlosies: “Ak vai, Kungs!” Jo Es šo vārdu esmu runājis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Un pravietis Jeremija sacīja visus šos vārdus uz Cedeķiju, Jūda ķēniņu, Jeruzālemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Kad Bābeles ķēniņa kara spēks karoja pret Jeruzālemi un pret visām atlikušām Jūda pilsētām, pret Laķisu un pret Azeku; jo šīs stiprās pilsētas bija atlikušas no Jūda pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Šis ir tas vārds, kas notika uz Jeremiju no Tā Kunga, kad ķēniņš Cedeķija bija derību derējis ar visiem ļaudīm, kas Jeruzālemē, viņiem izsaukt svabadības gadu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Ka ikvienam bija atlaist savu kalpu un ikvienam savu kalponi, kas vien no Ebreju cilts, ka Jūdu starpā neviens savu brāli nekalpinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Tad paklausīja visi lielkungi un visi ļaudis, kas šo derību bija derējuši, ka ikviens savu kalpu un savu kalponi atlaistu vaļā un vairs nekalpinātu, - tie paklausīja un tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Bet pēc tie tiem kalpiem un tām kalponēm, ko tie bija atlaiduši vaļā, lika nākt atkal atpakaļ un tos spieda atkal būt par kalpiem un par kalponēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Tādēļ Tā Kunga vārds notika uz Jeremiju no Tā Kunga sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Tā saka Tas Kungs, Israēla Dievs: Es esmu derību derējis ar jūsu tēviem, kad tos izvedu no Ēģiptes zemes, no tā vergu nama, un sacīju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Septītā gadā jums būs atlaist ikvienam savu brāli, kas ir Ebrejs, kas tev ir pārdots un sešus gadus tev kalpojis, un tev būs viņu atlaist no sevis svabadu; bet jūsu tēvi Mani neklausīja un nepiegrieza savas ausis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Tad jūs nu šodien bijāt atgriezušies un darījuši, kas bija tiesa Manās acīs, izsaukdami svabadību ikviens savam tuvākam, un jūs bijāt derību derējuši Manā priekšā, tai namā, kas pēc Mana Vārda nosaukts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Bet jūs esat atkāpušies, Manu Vārdu sagānījuši un ņēmuši atpakaļ ikviens savu kalponi, ko bijāt atlaiduši svabadus savā vaļā, un esiet tos spieduši, būt par kalpiem un par kalponēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Tādēļ tā saka Tas Kungs: jūs Mani neesat klausījuši, svabadību izsaukt ikviens savam brālim un ikviens savam tuvākam. Redzi, tad Es pret jums izsaucu svabadību, saka Tas Kungs, zobenam, mērim un badam, un Es jūs nodošu uz vārdzināšanu visās pasaules valstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Un Es nodošu tos vīrus, kas Manu derību pārkāpuši, kas nav turējuši tās derības vārdus, ko tie Manā priekšā derējuši, tā kā to teļu, ko tie divējos gabalos pārcirtuši un kuru gabalu starpā gājuši cauri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Jūda lielkungus un Jeruzālemes lielkungus, ķēniņa sulaiņus un priesterus un visus zemes ļaudis, kas starp tā teļa gabaliem gājuši cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Un Es tos nodošu viņu ienaidniekiem rokā, tiem rokā, kas viņu dvēseli meklē, un viņu miesas būs par barību putniem apakš debess un zvēriem virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Un Cedeķiju, Jūda ķēniņu, un viņa lielkungus es nodošu viņu ienaidniekiem rokā un tiem rokā, kas viņu dvēseli meklē, proti Bābeles ķēniņa karaspēka rokā, kas tagad no jums aizcēlies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Redzi, Es došu pavēli, saka Tas Kungs, un tos atvedīšu atkal uz šo pilsētu, un tie pret to karos un to uzņems un to sadedzinās ar uguni, un Es izpostīšu Jūda pilsētas, ka nevienam tur nebūs dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Šis ir tas vārds, kas notika uz Jeremiju no Tā Kunga, Jojaķima, Josijas dēla, Jūda ķēniņa, dienās sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Noej pie Rekabiešiem un runā ar tiem un ved tos Tā Kunga namā, vienā no tiem kambariem, un dod tiem vīnu dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Tad es ņēmu Jaazaniju, Jeremijas dēlu, Habacinijas dēla dēlu, līdz ar viņa brāļiem un visiem viņa dēliem un visu Rekabiešu namu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Un tos vedu Tā Kunga namā Jegdalijas dēla, Dieva vīra Anana dēlu kambarī, kas ir sānis lielkungu kambarim, virs durvju sarga Mazejas, Šaluma dēla, kambara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Un Rekabiešu nama bērniem es cēlu priekšā kausus pilnus ar vīnu un biķerus un uz tiem sacīju: dzeriet vīnu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Bet tie sacīja: mēs nedzeram vīna, jo Jonadabs, Rekaba dēls, mūsu tēvs, mums pavēlējis un sacījis: jums nebūs vīna dzert, ne jums, ne jūsu bērniem ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Un namus jums nebūs taisīt nedz sēklu sēt nedz vīna dārzus dēstīt nedz turēt, bet jums būs teltīs dzīvot visu savu mūžu, ka ilgi dzīvojat tai zemē, kur jūs piemītat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Tad mēs Jonadaba, Rekaba dēla, sava tēva, balsij esam klausījuši visās lietās, ko viņš mums pavēlējis, tā ka mēs vīna savu mūžu nedzeram, ne mēs, ne mūsu sievas, ne mūsu dēli, ne mūsu meitas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Un ka mēs namus neuztaisam sev par mājokli, arī vīna dārzu mums nav, ne tīruma, ne sējuma;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Bet mēs mītam teltīs, un klausam un darām visu, ko mums mūsu tēvs Jonadabs pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Bet notikās, kad NebukadNecars, Bābeles ķēniņš, pret šo zemi cēlās, tad mēs sacījām: nāciet, iesim uz Jeruzālemi no Kaldeju kara spēka un no Sīriešu spēka; tā mēs esam apmetušies Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Tad Tā Kunga vārds notika uz Jeremiju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Tā saka Tas Kungs Cebaot Israēla Dievs: ej un saki Jūda vīriem un Jeruzālemes iedzīvotājiem: Vai negribat mācību pieņemt un klausīt Maniem Vārdiem? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Jonadaba, Nekaba dēla, vārdi tiek pastāvīgi turēti, kas saviem bērniem aizliedzis vīnu dzert, un tie līdz šai dienai nav dzēruši, bet klausījuši sava tēva pavēlei. Bet Es uz jums esmu runājis vienmēr vienā runāšanā, un jūs Man neesat klausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Un Es pie jums esmu sūtījis bez mitas vienā sūtīšanā visus Savus kalpus, tos praviešus, un sacījis: atgriežaties jel ikviens no sava niknā ceļa un dariet labus darbus un nedzenaties citiem dieviem pakaļ, tiem kalpot, tad jūs paliksiet tai zemē, ko esmu devis jums un jūsu tēviem. Bet jūs savas ausis neesat atgriezuši nedz Mani klausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Jonadaba, Rekaba dēla, bērni pastāvīgi ir turējuši sava tēva pavēli, ko viņš pavēlējis, bet šie ļaudis Man neklausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Tādēļ, tā saka Tas Kungs, tas Dievs Cebaot, Israēla Dievs: redzi, Es vedīšu pār Jūdu un pār visiem Jeruzālemes iedzīvotājiem visu ļaunumu, ko Es pret tiem esmu runājis, tādēļ ka Es uz tiem esmu runājis, bet tie nav klausījuši, Es tos esmu aicinājis, bet tie nav atbildējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Un uz Rekabiešu namu Jeremija sacīja: tā saka Tas Kungs Cebaot, Israēla Dievs: tādēļ ka jūs esat klausījuši Jonadaba, sava tēva, likumam un sargājuši visas viņa pavēles un darījuši visu, ko viņš jums bija pavēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Tādēļ tā saka Tas Kungs Cebaot, Israēla Dievs: Jonadabam, Rekaba dēlam, ne mūžam netrūks vīra, kas stavēs Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Un Jojaķima, Josijas dēla, Jūda ķēniņa, ceturtā gadā notika uz Jeremiju šis vārds no Tā Kunga:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Ņem sev grāmatu un raksti tanī visus vārdus, ko Es uz tevi esmu runājis par Israēli un par Jūdu un par visām tautām, kamēr Es uz tevi esmu runājis, no Josijas dienām līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Varbūt ka Jūda nams liks vērā visu to ļaunumu, ko Es tiem domāju darīt, ka ikviens atgriežas no sava ļaunā ceļa, un Es piedošu viņu noziegumus un viņu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Tad Jeremija aicināja Bāruku, Nerijas dēlu, un Bāruks rakstīja no Jeremijas mutes grāmatā visus Tā Kunga vārdus, ko viņš uz to bija runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Un Jeremija pavēlēja Bārukam un sacīja: es topu aizturēts, ka nevaru iet Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Tad ej tu un lasi no tās grāmatas, ko tu no manas mutes esi rakstījis, Tā Kunga vārdus priekš to ļaužu ausīm Tā Kunga namā gavēņa dienā, arī priekš visas Jūda cilts ausīm, kas atnāk no savām pilsētām, tev tos būs lasīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Varbūt ka tie zemē metīsies un pielūgs Tā Kunga priekšā un atgriezīsies ikviens no sava ļaunā ceļa, jo tā dusmība un bardzība ir liela, ko Tas Kungs ir runājis pret šiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Un Bāruks, Nerijas dēls, darīja, tā kā pravietis Jeremija viņam bija pavēlējis, un lasīja no tās grāmatas Tā Kunga vārdus Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Un notikās Jojaķima, Josijas dēla, Jūda ķēniņa, piektā gadā, devītā mēnesī, tad izsauca gavēni Tā Kunga priekšā visiem ļaudīm Jeruzālemē un visiem ļaudīm, kas no Jūda pilsētām nāca uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Tad Bāruks no tās grāmatas lasīja priekš visu ļaužu ausīm Jeremijas vārdus Tā Kunga namā, rakstītāja Ģemarijas, Safana dēla, kambarī, augšējā pagalmā, pie Tā Kunga nama jauniem vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Kad nu Mikaja, Ģemarijas dēls, Safana dēla dēls, no tās grāmatas dzirdēja visus Tā Kunga vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Tad viņš nogāja ķēniņa namā, rakstītāja kambarī, un redzi, tur sēdēja visi lielkungi, rakstītājs Elišamus un Delaja, Šemajas dēls, un Elnatans, Akbora dēls, un Ģemarija, Safana dēls, un Cedeķija, Kananijas dēls, un visi lielkungi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Un Mikaja tiem teica visus tos vārdus, ko bija dzirdējis Bāruku no tās grāmatas lasam priekš ļaužu ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Tad visi tie lielkungi sūtīja pie Bāruka Jehūdi, Netanijas dēlu, kas bija Kušijas dēla Šelamijas dēls, un sacīja: to grāmatu, no kuras tu esi lasījis priekš ļaužu ausīm, ņem savā rokā un nāc. Tā Bāruks, Nerijas dēls, ņēma to grāmatu savā rokā un gāja pie tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Un tie uz viņu sacīja: apsēdies un lasi to priekš mūsu ausīm. Un Bāruks lasīja priekš viņu ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Un kad tie visus tos vārdus dzirdēja, tad cits uz citu bailīgi skatījās, un tie sacīja uz Bāruku: tiešām, visi šie vārdi mums jāsaka ķēniņam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Un tie Bāruku vaicāja un sacīja: teic mums jel, kā tu visus šos vārdus no viņa mutes esi rakstījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Un Bāruks uz tiem sacīja: viņš visus šos vārdus no savas mutes uz mani teica, un es tos ar tinti rakstīju grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Tad tie lielkungi sacīja uz Bāruku: ej un paslēpies, tu un Jeremija, un lai neviens nezin, kur jūs esat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Tad tie gāja pie ķēniņa pils pagalmā, bet to grāmatu tie nolika rakstītāja Elišamus kambarī, un teica priekš ķēniņa ausīm visus šos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Tad ķēniņš sūtīja Jehūdi pēc tās grāmatas, un tas to ņēma no rakstītāja Elišamus kambara, un Jehūdis lasīja priekš ķēniņa ausīm un priekš visu lielkungu ausīm, kas pie ķēniņa stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Bet ķēniņš sēdēja ziemas namā devītā mēnesī, un viņa priekšā uguns kurējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Un kad Jehūdis trīs vai četrus gabalus bija lasījis, tad viņš to sagrieza ar spalvas nazi un iemeta ugunī ugunskurā, tiekams visa grāmata sadega tai ugunī, kas bija ugunskurā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Un tie neizbijās nedz saplēsa savas drēbes, ne ķēniņš, ne viņa kalpi, kas bija dzirdējuši visus šos vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Un lai gan Elnatans un Delaja un Ģemarija ķēniņu lūdza, to grāmatu nesadedzināt, viņš tos neklausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Un ķēniņš pavēlēja Jerameēlim, Ameleķa dēlam, un Serajam, Asriēļa dēlam, un Šelamijam, Abdeēļa dēlam, sagrābt rakstītāju Bāruku un pravieti Jeremiju, bet Tas Kungs tos bija apslēpis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Tad Tā Kunga vārds notika uz Jeremiju, kad ķēniņš to grāmatu un tos vārdus bija sadedzinājis, ko Bāruks no Jeremijas mutes bija sarakstījis, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '“Ņem sev atkal citu grāmatu un raksti tanī visus tos pašus vārdus, kas stāvēja tai pirmā grāmatā, ko Jojaķims, Jūda ķēniņš, sadedzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Un saki par Jojaķimu, Jūda ķēniņu: tā saka Tas Kungs: tu šo grāmatu esi sadedzinājis un sacījis: Kāpēc tu tanī esi rakstījis un sacījis: Bābeles ķēniņš nācin nāks un samaitās šo zemi un no tās izdeldēs cilvēkus un lopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Tāpēc Tas Kungs tā saka par Jojaķimu, Jūda ķēniņu: viņam nebūs neviena, kas sēdēs uz Dāvida goda krēsla, un viņa līķis nomests gulēs dienas karstumā un nakts aukstumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Un Es pie viņa un pie viņa dzimuma un pie viņa kalpiem piemeklēšu viņa noziegumu, un vedīšu pār tiem un pār Jeruzālemes iedzīvotājiem un pār visiem Jūda vīriem visu to ļaunumu, ko Es pret tiem esmu runājis, bet tie nav klausījuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Un Jeremija ņēma citu grāmatu un to deva rakstītājam Bārukam, Nerijas dēlam, un tas no Jeremijas mutes tanī rakstīja visus tās grāmatas vārdus, ko Jojaķims, Jūda ķēniņš, bija sadedzinājis ar uguni, un pie tiem vēl tapa pielikti daudz tādi pat vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Un ķēniņš Cedeķija, Josijas dēls, valdīja Jekanijas, Jojaķima dēla, vietā; to Nebukadnecars, Bābeles ķēniņš, bija iecēlis par ķēniņu Jūda zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Bet ne viņš, ne viņa kalpi, ne tie ļaudis tai zemē neklausīja Tā Kunga vārdiem, ko viņš bija runājis caur pravieti Jeremiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Un ķēniņš Cedeķija sūtīja Juhalu, Šelemijas dēlu, un priesteri Cefaniju, Mazejas dēlu, pie pravieša Jeremijas un lika sacīt: lūdz jel par mums To Kungu, mūsu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jo Jeremija gāja vēl iekšā un ārā starp tiem ļaudīm un vēl nebija cietumā ielikts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Un Faraona karaspēks bija cēlies no Ēģiptes zemes, un tie Kaldeji, kas ap Jeruzālemi bija apmetušies, to baumi par tiem dzirdējuši, no Jeruzālemes bija aizgājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Tad Tā Kunga vārds notika uz pravieti Jeremiju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Tā saka Tas Kungs, Israēla Dievs: tā jums būs atsacīt Jūda ķēniņam, kas jūs pie Manis sūtījis, Mani vaicāt: redzi, Faraona karaspēks, kas jums izgājis palīgā, griezīsies atpakaļ uz savu zemi, uz Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Un Kaldeji nāks atpakaļ un karos pret šo pilsētu un to uzņems un to sadedzinās ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Tā saka Tas Kungs: nepieviļat savas dvēseles, sacīdami: Kaldeji tiešām no mums aizies projām, - jo tie neaizies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Jo jebšu jūs kautu visu Kaldeju spēku, kas pret jums karo, un atliktos no tiem (tikai) kādi ievainoti vīri, tad tie celsies ikkatrs savā teltī un sadedzinās šo pilsētu ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Un notikās, kad Kaldeju spēks no Jeruzālemes bija aizgājis priekš Faraona karaspēka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Tad Jeremija izgāja no Jeruzālemes, iet uz Benjamina zemi un tur uzņemt savu daļu to ļaužu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Un kad viņš nāca Benjamina vārtos, tad tur bija tas sargu virsnieks, Jerija vārdā, Šelemijas dēls, Kananijas dēla dēls, tas sagrāba pravieti Jeremiju un sacīja: tu gribi pāriet pie Kaldejiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Un Jeremija sacīja: tas nav tiesa, es nepāriešu pie Kaldejiem. Bet Jerija viņu neklausīja un sagrāba Jeremiju un to noveda pie tiem lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Un tie lielkungi apskaitās par Jeremiju un viņu sita un lika cietumā, rakstītāja Jonatana namā, jo to tie bija darījuši par cietuma namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Tā Jeremija gāja cietumā tais pagrabos, un tur Jeremija sēdēja daudz dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Tad ķēniņš Cedeķija sūtīja un lika viņu atvest, un ķēniņš viņu vaicāja paslepeni savā namā un sacīja: vai ir kāds vārds no Tā Kunga? Un Jeremija sacīja: ir. Un viņš sacīja: tu Bābeles ķēniņam tapsi dots rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Un Jeremija sacīja uz ķēniņu Cedeķiju: ko es esmu grēkojis pret tevi un pret taviem kalpiem un pret šiem ļaudīm, ka jūs mani esat likuši cietumā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Kur nu ir jūsu pravieši, kas jums sludināja un sacīja: Bābeles ķēniņš nenāks pret jums nedz pret šo zemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Tad nu, klausi jel, ak kungs un ķēniņ! Lai jel mana lūgšana tavā priekšā ir pieņēmīga, un neved mani atpakaļ rakstītāja Jonatana namā, ka es tur nemirstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Tad ķēniņš Cedeķija pavēlēja, lai Jeremiju tura cietuma pagalmā, un viņam ikdienas tapa dots viens maizes rieciens no cepēju ielas, tiekams visa maize pilsētā bija apēsta. Tā Jeremija palika cietuma pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Bet Šefatija, Matana dēls, un Ģedalija, Pašhura dēls, un Juhals, Šelemijas dēls, un Pašhurs, Malhijas dēls, dzirdēja tos vārdus, ko Jeremija uz visiem ļaudīm runāja sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Tā saka Tas Kungs: kas šai pilsētā paliek, tas mirs caur zobenu, caur badu un caur mēri, bet kas iet ārā pie Kaldejiem, tas dzīvos un savu dvēseli paturēs un dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Tā saka Tas Kungs: šī pilsēta dotin taps dota Bābeles ķēniņa karaspēkam rokā, ka tas to uzņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Tad tie lielkungi sacīja uz ķēniņu: liec jel šo vīru nokaut; jo tā viņš rokas dara gurdenas tiem karavīriem, kas vēl atliek šai pilsētā, un rokas visiem ļaudīm, kad viņš tādus vārdus uz tiem runā; jo šis vīrs nemeklē šo ļaužu labumu, bet viņu ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Un ķēniņš Cedeķija sacīja: redzi, viņš ir jūsu rokās, jo ķēniņš pret jums nekā nespēj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Tad tie ņēma Jeremiju, un to iemeta Malhijas, ķēniņa dēla, bedrē, kas bija cietuma pagalmā, un Jeremiju nolaida ar virvēm, bet tai bedrē nebija ūdens, bet dubļi, un Jeremija iegrima dubļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Un Ebedmelehs, Moru vīrs, ķēniņa sulainis, kas bija ķēniņa namā, dzirdēja, ka tie Jeremiju bija metuši bedrē, un ķēniņš sēdēja Benjamina vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Tad Ebedmelehs izgāja no ķēniņa nama un runāja uz ķēniņu un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Mans kungs un ķēniņ, šie vīri ir ļaunu darījuši ar visu, ko tie darījuši pravietim Jeremijam, ko tie metuši bedrē, un viņam savā vietā badu jāmirst, tāpēc ka maizes pilsētā vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Tad ķēniņš Ebedmeleham, tam Moru vīram, pavēlēja un sacīja: ņem no šejienes trīsdesmit vīrus līdz un izvelc pravieti Jeremiju no bedres, pirms viņš mirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Tad Ebedmelehs ņēma tos vīrus un nāca ķēniņa namā apakš mantu kambara un ņēma no turienes kādas vecas saplīsušas drēbju lupatas un tās nolaida ar virvēm pie Jeremijas bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Tad tas Moru vīrs Ebedmelehs sacīja uz Jeremiju: liec jel tās vecās saplīsušās drēbju lupatas apakš savām roku padusēm ap tām virvēm, un Jeremija tā darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Un tie Jeremiju izvilka ar tām virvēm un viņu izcēla no bedres, un Jeremija palika cietuma pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Tad ķēniņš Cedeķija nosūtīja un lika atvest pravieti Jeremiju pie sevis trešajā ieejamā vietā pie Tā Kunga nama. Un ķēniņš sacīja uz Jeremiju: es tev ko vaicāšu, neapslēp man nekā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Tad Jeremija sacīja uz Cedeķiju: kad es tev to sacīšu, tad tu mani kautin nokausi, un kad es tev padomu došu, tad tu tomēr mani neklausīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Un ķēniņš Cedeķija Jeremijam zvērēja paslepeni un sacīja: tik tiešām kā Tas Kungs dzīvo, kas mums šo dvēseli radījis, es tevi nenokaušu un tevi nenodošu šiem vīriem rokā, kas tavu dvēseli meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Tad Jeremija sacīja uz Cedeķiju: tā saka Tas Kungs, tas Dievs Cebaot, Israēla Dievs: ja tu iet iziesi pie Bābeles ķēniņa lielkungiem, tad tava dvēsele dzīvos, un šī pilsēta netaps ar uguni sadedzināta, un tad tu dzīvosi, tu un tavs nams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Bet ja tu neiziesi pie Bābeles ķēniņa lielkungiem, tad šī pilsēta Kaldejiem taps dota rokā, un tie to sadedzinās ar uguni, un tu no viņu rokas neizspruksi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Un ķēniņš Cedeķija sacīja uz Jeremiju: es bīstos no tiem Jūdiem, kas Kaldejiem piekrituši, ka mani nenodod viņu rokā, un tie mani neapmēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Un Jeremija sacīja: tevi nenodos; klausi jel Tā Kunga balsij, ko es uz tevi runāju, tad tev labi klāsies, un tava dvēsele dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Bet ja tu liedzies iet ārā, tad šis ir tas vārds, ko Tas Kungs man parādījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Redzi, visas sievas, kas Jūda ķēniņa namā atliek, taps izvestas pie Bābeles ķēniņa lielkungiem, un tās sacīs: tavi draugi tevi pievīluši un tevi pārvarējuši, un kad nu tavas kājas iegrimušas dubļos, tad tie griezušies atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Un visas tavas sievas un visi tavi bērni taps izvesti pie Kaldejiem, un tu pats neizspruksi no viņu rokām, bet tu tapsi sagrābts caur Bābeles ķēniņa roku un sadedzināsi šo pilsētu ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Tad Cedeķija sacīja uz Jeremiju: lai neviens nezin par šiem vārdiem, ka tu nemirsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Un kad tie lielkungi dzirdēs, ka es ar tevi esmu runājis, un tie nāk pie tevis un uz tevi saka: saki mums jel, ko tu ar ķēniņu esi runājis, neslēp to mums, tad mēs tevi nenokausim, un ko ķēniņš uz tevi runājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Tad tev uz tiem būs sacīt: es pakritu lūgdams ķēniņa priekšā, ka tas mani neliktu vest Jonatana namā, tur mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Kad nu visi lielkungi pie Jeremijas nāca un viņu vaicāja, tad viņš tiem sacīja pēc visiem šiem vārdiem, ko ķēniņš bija pavēlējis. Un tie viņu atstāja mierā, jo tie to lietu nedabūja dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Un Jeremija palika cietuma pagalmā līdz tai dienai, kad Jeruzāleme tapa uzņemta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Un notikās, kad Jeruzāleme bija uzņemta: (Cedeķijas, Jūda ķēniņa, devītā gadā, desmitā mēnesī, Nebukadnecars, Bābeles ķēniņš, un viss viņa karaspēks nāca pret Jeruzālemi un apmetās ap viņu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Vienpadsmitā Cedeķijas gadā, ceturtā mēnesī, devītā mēneša dienā tie ielauzās pilsētā)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Tad visi Bābeles ķēniņa lielkungi iegāja iekšā un apstājās pie vidējiem vārtiem, proti NergalSarecers, SamgarNebo, kambarjunkuru virsnieks Sarzeķims, gudro virsnieks NergalSarecers, un visi citi Bābeles ķēniņa lielkungi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Un notikās, kad Cedeķija, Jūda ķēniņš, un visi karavīri tos redzēja, tad tie bēga un izgāja naktī no pilsētas ārā pa to ceļu pie ķēniņa dārza, pa vārtiem starp tiem diviem mūriem, un viņš gāja pa klajuma ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Bet Kaldeju spēks viņiem dzinās pakaļ un panāca Cedeķiju Jērikus klajumos un to saņēma un veda augšām pie Nebukadnecara, Bābeles ķēniņa, uz Riblu Hamatas zemē, un tas par viņu sprieda tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Un Bābeles ķēniņš nokāva Cedeķijas bērnus Riblā priekš viņa acīm, un visus cienīgos no Jūda Bābeles ķēniņš nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Un viņš lika izdurt Cedeķijas acis un to saistīja ar divām vara ķēdēm, viņu aizvest uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Un Kaldeji sadedzināja ķēniņa namu un tos ļaužu namus ar uguni un noārdīja Jeruzālemes mūrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Bet tos atlikušos ļaudis, kas pilsētā bija atlikuši, un tos bēgļus, kas pie viņa bija pārgājuši, līdz ar tiem citiem ļaudīm, kas bija atlikuši, pils karavīru virsnieks Nebuzaradans noveda uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Bet no tiem ļaudīm, kas bija zemas kārtas, kam nekā nebija, pils karavīru virsnieks Nebuzaradans, pameta Jūda zemē un deva tiem tai dienā vīna dārzus un tīrumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Bet par Jeremiju Nebukadnecars, Bābeles ķēniņš, bija pavēlējis pils karavīru virsniekam Nebuzaradanam un sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Ņem viņu un lūko labi pēc viņa un nedari viņam nekā ļauna, bet kā viņš tev sacīs, tā dari ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Tad sūtīja pils karavīru virsnieks Nebuzaradans un kambarjunkuru virsnieks Nebuzazbans un gudro virsnieks NergalSarecers un Bābeles ķēniņa virsnieki visi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Tie sūtīja un ņēma Jeremiju no cietuma pagalma un nodeva viņu Ģedalijam, Aīkama dēlam, Safana dēla dēlam, viņu vest namā; tā viņš palika pie tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Bet Tā Kunga vārds bija noticis uz Jeremiju, kad viņš vēl cietuma pagalmā tapa turēts, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Ej un runā uz to Mora vīru Ebedmelehu un saki: tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, Es Saviem vārdiem likšu nākt pār šo pilsētu par ļaunu un ne par labu, un tai dienā tas būs priekš tavām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Bet tevi Es tai dienā gribu izglābt un tu netapsi nodots tiem vīriem rokā, no kā tu bīsties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Jo Es tiešām tevi izglābšu un tu nekritīsi caur zobenu, bet savu dvēseli paturēsi, tāpēc ka tu esi paļāvies uz Mani, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Šis ir tas vārds, kas uz Jeremiju notika no Tā Kunga, kad pils karavīru virsnieks Nebuzaradans viņu ņēma un atlaida no Rāmas, kur viņš bija ķēdēs saslēgts starp visiem Jeruzālemes un Jūda ļaudīm, kas tapa aizvesti uz Bābeli cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Bet pils karavīru virsnieks lika Jeremiju atvest un sacīja uz viņu: Tas Kungs, tavs Dievs, šo ļaunumu par šo vietu runājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Un Tas Kungs tam ir licis nākt un darījis, kā viņš ir runājis, jo jūs esat grēkojuši pret To Kungu un neesat klausījuši viņa balsij, tāpēc jums tā noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Tad nu redzi, es tevi šodien laižu vaļā no tām ķēdēm pie tavām rokām; ja tev patīk man nākt līdz uz Bābeli, tad nāc, es labi par tevi gādāšu. Bet ja tas tev nepatīk, man nākt līdz uz Bābeli, tad lai paliek. Redzi, visa zeme ir tavā priekšā, kurp iet tev liekās labi un taisni, turp ej.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Un viņam vēl projām neejot, tas sacīja: tad griezies pie Ģedalijas, Aīkama dēla, Safana dēla dēla, ko Bābeles ķēniņš iecēlis pār Jūda pilsētām, un dzīvo pie tā starp tiem ļaudīm, jeb visur, kur tev patīk iet, turp ej. Un pils karavīru virsnieks viņam deva ceļa maizi un dāvanu un viņu atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Tā Jeremija nāca pie Ģedalijas, Aīkama dēla, uz Micpu, un dzīvoja pie tā starp tiem ļaudīm, kas bija atlikuši tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Kad nu visi kara virsnieki, kas laukā turējās līdz ar saviem karavīriem, dzirdēja, ka Bābeles ķēniņš Ģedaliju, Aīkama dēlu, bija iecēlis pār to zemi, un ka viņš tam bija novēlējis vīrus un sievas un bērniņus un tās zemes ļaudis no zemas kārtas, kas uz Bābeli nebija aizvesti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Tad tie nāca pie Ģedalijas uz Micpu, proti Ismaēls, Netanijas dēls, un Jehohanans un Jonatans, Kareūs dēli, un Seraja, Tanumeta dēls, un Evajus dēli no Netofas un Jaazanija, Maāhatus dēls, līdz ar saviem vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Un Ģedalija, Aīkama dēls, Safana dēla dēls, zvērēja tiem un viņu vīriem un sacīja: nebīstaties Kaldejiem kalpot, palieciet šai zemē un kalpojiet Bābeles ķēniņam, tad jums labi klāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Un redzi, es dzīvoju Micpā, stāvēt Kaldeju priekšā, kas pie mums nāk; tad nu krājiet vīnu un labību un eļļu un liekat to savos traukos un dzīvojiet savās pilsētās, ko esat uzņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Un visi Jūdi, kas bija Moabā un pie Amona bērniem un Edomā un visās tanīs valstīs, kad dzirdēja, ka Bābeles ķēniņš kādus bija atstājis iekš Jūda, un pār tiem bija iecēlis Ģedaliju, Aīkama dēlu, Safana dēla dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Tad visi Jūdi griezās atpakaļ no visām vietām, kurp tie bija aizdzīti, un nāca uz Jūda zemi pie Ģedalijas uz Micpu un sakrāja vīnu un labību lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Bet Jehohanans, Kareūs dēls, un visi kara virsnieki, kas laukā turējās, nāca pie Ģedalijas uz Micpu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Un sacīja uz viņu: vai tu gan zini, ka Baālis, Amona bērnu ķēniņš, ir sūtījis Ismaēli, Netanijas dēlu, tev ņemt dzīvību? Bet Ģedalija, Aīkama dēls, viņiem neticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Tad Jehohanans, Kareūs dēls, runāja uz Ģedaliju paslepeni Micpā un sacīja: lūdzams liec man iet un nokaut Ismaēli, Netanijas dēlu, ka neviens to nezin. Kāpēc viņam tevi būs nokaut un visiem Jūdiem, kas pie tevis sapulcinājušies, izklīst un tiem atlikušiem no Jūda iet bojā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Bet Ģedalija, Aīkama dēls, sacīja uz Jehohananu, Kareūs dēlu: Nedari tā, jo tu runā melus par Ismaēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Bet septītā mēnesī Ismaēls, Netanijas dēls, Elišama dēla dēls, no ķēniņa dzimuma, un ķēniņa virsnieki nāca līdz ar desmit vīriem pie Ģedalijas, Aīkama dēla, uz Micpu, un tie tur kopā ēda maizi Micpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Un Ismaēls, Netanijas dēls, cēlās ar tiem desmit vīriem, kas pie viņa bija, un sita ar zobenu Ģedaliju, Aīkama dēlu, Safana dēla dēlu; tā viņš to nokāva, ko Bābeles ķēniņš bija iecēlis pār to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Un Ismaēls kāva arī visus Jūdus, kas Micpā bija pie viņa, pie Ģedalijas, un tos Kaldejus, kas tur atradās, tos karavīrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Un otrā dienā pēc Ģedalijas nokaušanas, kad neviens par to nezināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Tad vīri nāca no Sihemas, no Šīlo un no Samarijas, astoņdesmit vīri, ar nodzītu bārdu un saplēstām drēbēm un iegraizītām miesām, un viņu rokā bija ēdams upuris un vīraks, ka to nestu Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Un Ismaēls, Netanijas dēls, izgāja no Micpas viņiem pretī, un raudāja iedams. Un kad tos sastapa, tad viņš uz tiem sacīja: nāciet pie Ģedalijas, Aīkama dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Bet kad tie nāca pilsētas vidū, tad Ismaēls, Netanijas dēls, tos nokāva (un iemeta) bedrē, viņš un tie vīri, kas bija pie viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Bet starp tiem bija desmit vīri, tie sacīja uz Ismaēli: nenokauj mūs, jo mums ir apslēptas mantas tīrumā, kvieši un mieži un eļļa un medus. Tad viņš tos atstāja un nenokāva ar viņu brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Un tā bedre, kurp Ismaēls nometa to vīru līķus, ko viņš līdz ar Ģedaliju bija nokāvis, bija tā pati, ko ķēniņš Asa bija racis pret Baešu, Israēla ķēniņu; šo Ismaēls, Netanijas dēls, pildīja ar tiem nokautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Un Ismaēls aizveda visus atlikušos ļaudis, kas bija Micpā, proti ķēniņa meitas un visus ļaudis, kas Micpā bija atstāti, ko pils karavīru virsnieks Nebuzaradans bija atstājis pie Ģedalijas, Aīkama dēla, un Ismaēls, Netanijas dēls, tos aizveda un gāja pāri pie Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Kad nu Jehohanans, Kareūs dēls, un visi kara virsnieki, kas bija pie viņa, dzirdēja to ļaunumu, ko Ismaēls, Netanijas dēls, bija darījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Tad tie ņēma visus (kara)vīrus, un gāja karot pret Ismaēli, Netanijas dēlu, un to atrada pie tā lielā ūdens, kas ir pie Gibeonas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Un kad visi ļaudis, kas bija pie Ismaēla, redzēja Jehohananu, Kareūs dēlu, un visus kara virsniekus, kas pie viņa, tad tie priecājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Un visi ļaudis, ko Ismaēls no Micpas bija aizvedis, griezās un gāja atpakaļ pie Jehohanana, Kareūs dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Tomēr Ismaēls, Netanijas dēls, ar astoņiem vīriem izmuka no Jehohanana un gāja pie Amona bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Tad Jehohanans, Kareūs dēls, un visi kara virsnieki, kas bija pie viņa, paņēma visus atlikušos ļaudis, ko viņš atkal bija atvedis no Ismaēla, Netanijas dēla, no Micpas, kad šis bija nokāvis Ģedaliju, Aīkama dēlu, karavīrus, sievas un bērnus un ķēniņa sulaiņus, ko viņš no Gibeonas atkal bija atvedis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Un gāja un apmetās Ķimkama mājas vietā pie Bētlemes, iedami uz Ēģipti Kaldeju priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Jo tie bijās no viņiem, tāpēc ka Ismaēls, Netanijas dēls, bija nokāvis Ģedaliju, Aīkama dēlu, ko Bābeles ķēniņš bija iecēlis pār to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Tad visi kara virsnieki, Jehohanans, Kareūs dēls, un Jaazanija, Ozajas dēls, un visi ļaudis, mazi un lieli, piegāja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Un sacīja uz pravieti Jeremiju: lai jel mūsu sirsnīgā lūgšana tev ir pieņēmīga, un lūdz mūsu dēļ To Kungu, savu Dievu, par šiem atlikušiem, jo no daudziem mēs mazums esam atlikušies, kā tavas acis mūs redz,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Ka Tas Kungs, tavs Dievs, mums darītu zināmu to ceļu, pa ko mums jāstaigā un to vārdu, pēc kā mums jādara!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Un pravietis Jeremija uz tiem sacīja: es paklausīšu, redzi, es pielūgšu To Kungu, jūsu Dievu, pēc jūsu vārdiem, un visu, ko Tas Kungs atbildēs, to es jums sacīšu un nekā neslēpšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Tad tie sacīja uz Jeremiju: lai Tas Kungs pret mums ir patiesīgs un taisns liecinieks, ja mēs nedarīsim pēc ikkatra vārda, ko Tas Kungs, tavs Dievs, mums pavēlēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Lai būtu labs, lai ļauns, mēs klausīsim Tā Kunga, sava Dieva balsij, pie kā mēs tevi sūtam; lai mums labi klājās, kad mēs Tā Kunga, sava Dieva, balsij klausīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Un pēc desmit dienām Tā Kunga vārds notika uz Jeremiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Tad viņš aicināja Jehohananu, Kareūs dēlu, un visus kara virsniekus, kas bija pie viņa, un visus ļaudis, mazus un lielus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Un viņš uz tiem sacīja: tā saka Tas Kungs, Israēla Dievs, pie kā jūs mani esat sūtījuši, jūsu lūgšanu nest priekš Viņa vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Ja jūs paliksiet dzīvot šai zemē, tad Es jūs gribu uztaisīt un nenolauzīt, Es jūs gribu dēstīt un neizraut, jo Man jau ir žēl tā ļaunuma, ko Es jums esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Nebīstaties no Bābeles ķēniņa, no kā vaiga jūs bīstaties; nebīstaties no viņa, saka Tas Kungs; jo Es esmu ar jums, jūs atpestīt un jūs izglābt no viņa rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Un Es jums došu žēlastību, ka viņš par jums apžēlojās un jūs atkal atlaiž uz jūsu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Bet ja jūs sacīsiet: mēs šai zemē negribam palikt, un neklausīsiet Tā Kunga, sava Dieva, balsij,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Un sacīsiet: Nē, bet mēs iesim uz Ēģiptes zemi, kur neredzēsim karu un nedzirdēsim trumetes balsi, nedz būsim izsalkuši pēc maizes, un tur mēs gribam dzīvot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Nu tad klausiet Tā Kunga vārdu, jūs atlikušie no Jūda! Tā saka Tas Kungs Cebaot, Israēla Dievs: ja jūs savu vaigu griezīsiet, iet uz Ēģipti un iesiet tur piemājot, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Tad tas zobens, no kā jūs bīstaties, jūs panāks Ēģiptes zemē, un tas bads, par ko jūs bēdājaties, jums tur noies pakaļ, un jūs tur nomirsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Tā visiem vīriem, kas savu vaigu griež, iet uz Ēģipti, tur piemājot, būs mirt caur zobenu un caur badu un caur mēri, un no tiem neviens neatliks un neizbēgs no tā ļaunuma, ko Es pār tiem vedīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs: tā kā Mana dusmība un Mana bardzība ir izgāzta pār Jeruzālemes iedzīvotājiem, tā Mana bardzība pār jums izgāzīsies, kad jūs iesiet uz Ēģipti, un jūs būsiet par lāstu un briesmām un par apsmieklu un kaunu, un vairs neredzēsiet šo vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Tas Kungs pret jums runājis, jūs atlikušie no Jūda: neejat uz Ēģipti. Ziniet zinādami, ka es šodien pret jums esmu liecību devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Jo jūs pieviļat savas dvēseles: Jūs mani esat sūtījuši pie Tā Kunga, sava Dieva, un sacījuši: lūdz par mums To Kungu, mūsu Dievu, un tā kā Tas Kungs, mūsu Dievs, sacīs, tā mums to dari zināmu, un mēs to gribam darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Nu es jums to esmu sacījis, bet jūs neklausāt Tā Kunga, sava Dieva, balsij, nedz tam, ar ko Viņš mani pie jums sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Tad ziniet nu, ka jūs caur zobenu, caur badu un caur mēri mirsiet tai vietā, kurp gribat iet, tur piemājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Un kad Jeremija bija beidzis runāt uz visiem ļaudīm visus Tā Kunga, viņu Dieva, vārdus, ar ko Tas Kungs, viņu Dievs, viņu pie tiem bija sūtījis, (proti) visus šos vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Tad runāja Azarija, Ozajas dēls, un Jehohanans, Kareūs dēls, un visi tie nebēdnieki, un sacīja uz Jeremiju: tu runā melus; Tas Kungs, mūsu Dievs, tevi nav sūtījis nedz sacījis: jums nebūs iet uz Ēģipti, tur piemist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Bet Bāruks, Nerijas dēls, tevi pret mums skubina, mūs nodot Kaldejiem rokā, lai tie mūs nokauj un aizved uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Un Jehohanans, Kareūs dēls, un visi tie kara virsnieki un visi tie ļaudis neklausīja Tā Kunga balsij, palikt Jūda zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Bet Jehohanans, Kareūs dēls, un visi kara virsnieki ņēma visus Jūda atlikušos, kas no visām tautām, kurp tie bija aizdzīti, bija griezušies atpakaļ dzīvot Jūda zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Vīrus un sievas un bērnus un ķēniņa meitas, un visas tās dvēseles, ko pils karavīru virsnieks Nebuzaradans, bija atstājis pie Ģedalijas, Aīkama dēla, Safana dēla dēla, ir pravieti Jeremiju un Bāruku, Nerijas dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Un tie gāja uz Ēģiptes zemi, jo tie neklausīja Tā Kunga balsij, un tie nāca uz Takvanesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Tad Tā Kunga vārds notika uz Jeremiju Takvanesā sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Ņem savā rokā lielus akmeņus un ieroc tos mālos akmeņu bruģī, kas ir pie Faraona nama durvīm Takvanesā, priekš Jūdu vīru acīm, un saki uz tiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, Es sūtīšu un atvedīšu Nebukadnecaru, Bābeles ķēniņu, Savu kalpu, un celšu viņa goda krēslu pār šiem akmeņiem, ko Es esmu ieracis, un viņš izplētīs savu skaisto telti tur virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Un viņš nāks un sitīs Ēģiptes zemi; kam nāve uziet, tam lai uziet, un kam cietums uziet, tam lai uziet, un kam zobens uziet, tam lai uziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Un Es iededzināšu uguni Ēģiptes dievu namos, un viņš tos sadedzinās un aizvedīs. Un viņš apvilks Ēģiptes zemi, ka gans apvelk savu mēteli, un viņš izies no turienes ar mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Un viņš satrieks BetŠemes (saules dieva) pīlārus Ēģiptes zemē un sadedzinās Ēģiptes dievu namus ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Šis ir tas vārds, kas notika uz Jeremiju pret visiem Jūdiem, kas Ēģiptes zemē dzīvoja, kas Migdolā dzīvoja un Takvanesā un Novā un Patros zemē, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Tā saka Tas Kungs Cebaot, Israēla Dievs: jūs esat redzējuši visu ļaunumu, ko Es esmu vedis pār Jeruzālemi un pār visām Jūda pilsētām, un redzi, tā ir šodien posta vieta bez iedzīvotāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Viņu bezdievības dēļ ko tie darījuši, Mani kaitinādami, kad tie gāja kvēpināt un kalpot citiem dieviem, ko tie nepazina, ne paši, ne jūs, ne jūsu tēvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Un Es pie jums vienmēr esmu sūtījis vienā sūtīšanā visus Savus kalpus, tos praviešus, un sacījis: nedariet jel šo negantību, ko Es ienīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Bet tie nav klausījuši, nedz savas ausis griezuši, ka atgrieztos no savas bezdievības, nekvēpināt citiem dieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Tāpēc Mana bardzība un Mana dusmība izgāzusies un degusi Jūda pilsētās un Jeruzālemes ielās, tā ka tās palikušas par tuksnesi un posta vietu, tā kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Un nu, tā saka Tas Kungs Cebaot, Israēla Dievs: Kāpēc jūs darāt tādu lielu ļaunumu pret savām dvēselēm, ka top izdeldēti jūsu starpā vīrs un sieva, bērns un zīdāmais no Jūda vidus, un nekā no jums neatliek,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Mani kaitinādami ar savu roku darbiem un kvēpinādami citiem dieviem Ēģiptes zemē, kurp jūs esat gājuši, tur piemājot, lai paši sev sataisāt izdeldēšanu un topat par lāstu un apsmieklu starp visām zemes tautām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Vai esiet aizmirsuši savu tēvu bezdievību un Jūda ķēniņu bezdievību un viņu sievu bezdievību un savu bezdievību un savu sievu bezdievību, ko tie darījuši Jūda zemē un Jeruzālemes ielās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Un tomēr tie līdz šai dienai vēl nav sagrauzti un nebīstas nedz staigā Manā bauslībā un Manos likumos, ko Es esmu licis priekšā jums un jūsu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Tādēļ tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, Es griezīšu Savu vaigu uz jums par ļaunumu un izdeldēšu visu Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Un Es ņemšu Jūda atlikušos, kas savu vaigu griezuši, iet uz Ēģiptes zemi, tur piemājot, un tie visi dabūs galu Ēģiptes zemē, tie kritīs caur zobenu, caur badu tiem būs gals, gan maziem gan lieliem, caur zobenu un caur badu tie mirs un būs par lāstu un briesmām un par apsmieklu un kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Es arī tos piemeklēšu, kas dzīvo Ēģiptes zemē, tā kā es Jeruzālemi esmu piemeklējis ar zobenu, ar badu un ar mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Un neviens neizbēgs un neizspruks no Jūda atlikušiem, kas nākuši uz Ēģiptes zemi, tur piemājot, lai varētu atgriezties uz Jūda zemi, uz kurieni viņu dvēsele ilgojās atpakaļ griezties un tur dzīvot; jo tie negriezīsies atpakaļ, bez tiem vien, kas izbēg.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Tad visi vīri, kas zināja savas sievas citiem dieviem kvēpinām, un visas sievas, kas tur stāvēja lielā pulkā, līdz ar visiem ļaudīm, kas dzīvoja Ēģiptes zemē iekš Patros atbildēja Jeremijam un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Uz to vārdu, ko tu mums esi sacījis Tā Kunga Vārdā, mēs tev negribam klausīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Bet mēs darīsim pēc visiem vārdiem, kas no mūsu mutes nākuši, un kvēpināsim debess ķēniņienei un upurēsim viņai dzeramus upurus, tā kā mēs esam darījuši paši un mūsu tēvi, mūsu ķēniņi un mūsu lielkungi pa Jūda pilsētām un Jeruzālemes ielām; tad mums bija maizes papilnam un mēs bijām līksmi un neredzējām ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Bet no tā brīža, ka esam mitējušies kvēpināt debess ķēniņienei un viņai upurēt dzeramus upurus, tad mums ir bijis visāds trūkums, un mēs ejam bojā caur zobenu un caur badu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Un kad mēs tai debess ķēniņienei kvēpinām un viņai upurējam dzeramus upurus, vai tad mēs bez savu vīru ziņas tai taisām raušus, to tēlodami, un tai upurējam dzeramus upurus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Tad Jeremija runāja uz visiem ļaudīm, uz vīriem un uz sievām un uz visiem ļaudīm, kas viņam to vārdu bija atbildējuši, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Vai Tas Kungs nav pieminējis un pie sirds ņēmis to kvēpināšanu, ko jūs esat kvēpinājuši pa Jūda pilsētām un Jeruzālemes ielām, jūs un jūsu tēvi, jūsu ķēniņi un jūsu lielkungi un tās zemes ļaudis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Un Tas Kungs vairs nevarēja paciest to bezdievību, ko jūs darījāt un to negantību, ko jūs darījāt. Tādēļ jūsu zeme ir tapusi par postu un par briesmām un par lāstu, ka neviens tur nedzīvo, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Tāpēc ka jūs esat kvēpinājuši un pret To Kungu grēkojuši un neesat klausījuši Tā Kunga balsij nedz staigājuši viņa bauslībā un viņa likumos un viņa liecībās, tādēļ jums šis ļaunums noticis, kā tas šodien ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Un Jeremija sacīja uz visiem ļaudīm un uz visām sievām: klausiet Tā Kunga vārdu, jūs visi no Jūda cilts, kas esat Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Tā runā Tas Kungs Cebaot, Israēla Dievs, sacīdams: jūs un jūsu sievas ar savu muti esat runājuši un ar savām rokām to darījuši. Jūs esat sacījuši: mēs turēsim savus solījumus, ko esam apsolījuši, kvēpināt debess ķēniņienei un tai upurēt dzeramus upurus. Nu tad turat stipri savus solījumus un dariet, ko esat apsolījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Tad nu klausiet Tā Kunga vārdu, jūs visi no Jūda, kas dzīvojat Ēģiptes zemē: redzi, Es zvērēju pie Sava lielā vārda, saka Tas Kungs, ka Mans Vārds no nekāda vīra mutes vairs netaps saukts visā Ēģiptes zemē, kas sacītu: tik tiešām kā Tas Kungs Dievs dzīvo!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Redzi, Es būšu nomodā pār tiem uz ļaunu un ne uz labu, un visi vīri no Jūda, kas Ēģiptes zemē, taps izdeldēti ar zobenu un ar badu, tiekams būs pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Bet kas izbēgs zobenam, tie griezīsies atpakaļ no Ēģiptes zemes uz Jūda zemi, mazs pulciņš, un tad visi Jūda atlikušie, kas nākuši piemist Ēģiptes zemē, atzīs, kura vārds pastāvēs, vai Mans, vai viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Un tas jums būs par zīmi, saka Tas Kungs, ka Es jūs šai vietā piemeklēšu, lai zināt, ka Mani vārdi piepildīsies pie jums uz ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Tā saka Tas Kungs: redzi, Es nodošu Faraonu Hofru, Ēģiptes ķēniņu, viņa ienaidniekiem rokā, un tiem rokā, kas meklē viņa dvēseli, tā kā Es Cedeķiju, Jūda ķēniņu, esmu devis rokā Nebukadnecaram, Bābeles ķēniņam, viņa ienaidniekam, un tiem, kas viņa dvēseli meklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Šis ir tas vārds, ko pravietis Jeremija runājis uz Bāruku, Nerijas dēlu, kad viņš šos vārdus no Jeremijas mutes rakstīja grāmatā, Jojaķima, Josijas dēla, Jūda ķēniņa, ceturtā gadā, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Tā saka Tas Kungs, Israēla Dievs, uz tevi, Bāruk:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Tu saki: vai man! Jo Tas Kungs bēdas pielicis manām sāpēm; es esmu piekusis no savas vaidēšanas un neatrodu miera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tā tev būs sacīt uz viņu: tā saka Tas Kungs: redzi, ko Es esmu uztaisījis, to Es nolaužu, un ko esmu dēstījis, to Es izrauju, un tā klāsies visai šai zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Un tu sev meklē lielas lietas? Nemeklē tās! Jo redzi, Es vedu ļaunumu pār visu miesu, saka Tas Kungs. Bet tev Es došu paturēt tavu dvēseli visur, kur vien tu iesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Šis ir Tā Kunga vārds, kas notika uz pravieti Jeremiju pret pagānu tautām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Pret Ēģipti, pret Faraonu Nekus, Ēģiptes ķēniņa, karaspēku, kas bija pie Eifrat upes, pie Karķemisa, ko Nebukadnecars, Bābeles ķēniņš, sakāva Jojaķima, Josijas dēla, Jūda ķēniņa, ceturtā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Taisiet gatavas bruņas un sedzamas bruņas un ejat karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Sedlojiet zirgus un kāpiet virsū, jātnieki, nostājaties vara cepurēs, triniet šķēpus, apvelciet krūšu bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Kāpēc Es tos redzu bailīgus un atpakaļ bēgam, un viņu varenos sakautus un bēgam, ka neskatās atpakaļ? Briesmas visapkārt, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Ne čaklais var izbēgt, ne varenais izsprukt; pret ziemeli pie Eifrat upes krasta tie klūp un krīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kas tas, kas ceļas, kā upe, kam ūdeņi veļas kā straumes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Ēģiptes zeme ceļas kā upe, un viņas ūdeņi veļas kā straumes un saka: “Es celšos liela, es apklāšu zemi, es maitāšu pilsētas, un kas tur dzīvo.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Ceļaties, zirgi, rībiet, rati! Lai varoņi iziet, Moru ļaudis un no Puta, kas bruņas tura, un Līdieši, kas stopu nes un uzvelk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Šī diena ir Tā Kunga, Tā Kunga Cebaot atriebšanās diena, ka Viņš atriebjās pie Saviem pretiniekiem, un zobens ēdīs un rīs un piedzersies no viņu asinīm. Jo Tam Kungam, Tam Kungam Cebaot, ir kauja ziemeļu zemē pie Eifrat upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Ej augšā uz Gileādu un dabū zalves(balzāmu), jaunava, Ēģiptes meita! Velti, ka tu daudz zāļojies, jo dziedināšanas tev nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Tautas dzird tavu kaunu, un zeme ir pilna tavas kaukšanas, jo ir straipelejuši varonis uz varoni, un abi kopā krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Šis ir tas vārds, ko Tas Kungs runāja uz pravieti Jeremiju par Nebukadnecara, Bābeles ķēniņa, nākšanu, kaut Ēģiptes zemi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Sludinājiet Ēģiptes zemē, dariet zināmu Migdalā, sauciet to arī Novā un Takvanesā, sakāt: celies un taisies gatava, jo zobens ir aprijis, kas ap tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Kāpēc tavi varenie nogāzti? Tie nepastāvēja, jo Tas Kungs tos gāzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Viņš dara, ka daudzi gāžas, un viens krīt uz otru, un tie saka: ceļaties, iesim atpakaļ pie saviem ļaudīm un uz savu dzimteni no rijēja zobena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Tur sauc: Faraons, Ēģiptes ķēniņš, ir pagalam, viņš savu laiku nav licis vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Tik tiešām kā Es dzīvoju, saka tas Ķēniņš, kam vārds ir Kungs Cebaot: viņš nāks kā Tābors starp kalniem un kā Karmels jūrmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Gādā sev ceļa lietas, iedzīvotāja, Ēģiptes meita, jo Nofa taps par tuksnesi un taps sadedzināta, ka neviens tur nedzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Ēģipte ir dižena tele, dundurs no ziemeļiem nāk, tiešām nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Arī viņas karavīri viņas vidū ir kā baroti teļi; tomēr arī tie griež muguru, visi kopā bēg un nestāv, jo viņu nelaimes diena tiem uzbrukusi, viņu piemeklēšanas laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Viņas balss būs, tā kā čab, čūskai lienot, jo tie celsies uz turieni ar karaspēku un nāks pie viņiem ar cirvjiem, kā malkas cirtēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Tie nocirtīs viņas mežu, saka Tas Kungs, jebšu tas ir liels un biezs, jo to ir vairāk nekā siseņu, ka tos nevar skaitīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Ēģiptes meita stāv kaunā, rokā dota ļaudīm no ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Tas Kungs Cebaot, Israēla Dievs, saka: redzi, Es piemeklēšu Amonu Noā un Faraonu un Ēģipti un viņas dievus un viņas ķēniņus, Faraonu un tos, kas uz viņu paļaujas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Un Es tos nodošu tiem rokā, kas viņu dvēseles meklē, un Nebukadnecara, Bābeles ķēniņa, rokā, un viņa kalpu rokā. Bet pēcgalā tur dzīvos tā kā vecos laikos, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Bet tu, nebīsties, Mans kalps Jēkab, un neiztrūcinājies, Israēl! Jo redzi, Es tevi atpestīšu no tālienes un tavu dzimumu no viņa cietuma zemes; un Jēkabs griezīsies atpakaļ un paliks mierā, un viņam klāsies labi, un neviens viņu neiztrūcinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Tu tad nebīsties, Mans kalps Jēkab, saka Tas Kungs; jo Es esmu pie tevis. Jo Es darīšu galu visām pagānu tautām, kurp Es tevi biju aizdzinis, bet tev Es nedarīšu galu, bet Es tevi pārmācīšu pēc taisnības, un tevi nepametīšu nepārmācītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Šis ir tas vārds, kas notika uz pravieti Jeremiju pret Fīlistiem, pirms Faraons sakāva Gacu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Tā saka Tas Kungs: redzi, ūdens celsies no ziemeļiem un plūdīs un pārplūdīs zemi un visu viņas pilnumu, pilsētas, un viņas iedzīvotājus; un tie cilvēki brēks, un visi zemes iedzīvotāji kauks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'No skrejošu zirgu varenā trokšņa, no viņu ratu rībēšanas un no viņu riteņu rūkšanas tēvi neraudzīsies atpakaļ pēc bērniem, jo rokas būs nogurušas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Tās dienas dēļ kas nāk, postīt visus Fīlistus un izdeldēt Tiru un Sidonu līdz ar tiem citiem palīgiem; jo Tas Kungs izpostīs Fīlistus, kas atlikušies no Kaftora salas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kailums nāk pār Gacu, Askalona izdeldēta, tas atlikums viņas ielejā. Cik ilgi tu pats gribi graizīties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ak vai, Tā Kunga zobens! Cik ilgi tu nerimsi? Lien jel savās makstīs, dusi un esi klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Bet kā tam rimt? Jo Tas Kungs tam pavēlējis pret Askalonu un pret jūrmalu; uz turieni Viņš to sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Pret Moabu Tas Kungs Cebaot, Israēla Dievs, tā saka: Ak vai, par Nebu! Tas ir postīts, Kiriataīma tapusi kaunā un ieņemta, tas augstais patvērums ir kaunā un izbiedināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Moaba lielība pagalam; Hešbonā domā ļaunu pret viņu: nāciet, izdeldēsim to, ka nav vairs tauta. Arī tu, Madmene, nogursi, zobens dzīsies tev pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Klau, brēkšana no Horonaīmas, posts, drupas un gruvekļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moabs ir satriekts, viņa bērnus dzird kliedzam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Pa Luķitas teku iet uz augšu un raud raudādami, un kur iet lejā no Horonaīmas, dzird bailīgu kliegšanu par postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Bēdziet, glābiet savas dvēseles, bet tu būsi kā vientulis koks tuksnesī!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Jo tāpēc ka tu paļaujies uz saviem darbiem un uz savām mantām, tu arīdzan tapsi uzņemts, un Kamos aizies cietumā līdz ar visiem saviem svētītājiem un saviem lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Jo postītājs nāks pār ikkatru pilsētu, ka neviena pilsēta neizmuks, un ieleja taps maitāta, un klajums taps postīts, kā Tas Kungs to runājis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dodiet Moabam spārnus, jo tā kā skriešus viņš aizies, un viņa pilsētas taps par posta vietām bez iedzīvotāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Nolādēts lai ir, kas Tā Kunga darbu kūtri dara, un nolādēts lai ir, kas savu zobenu aiztur no asinīm!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moabs no savas jaunības bijis bez bēdām un klusu ir gulējis uz savām mielēm un nav pārliets no trauka traukā, un nav cietumā gājis, tāpēc viņam palikusi sava smaka, un viņa smarža nav pārvērtusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Tādēļ redzi, nāks dienas, saka Tas Kungs, ka Es pie tā sūtīšu gāzējus, kas viņu gāzīs un iztukšos viņa traukus un saplēsīs viņa ādas traukus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Un Moabs taps kaunā par Kamosu, kā Israēla nams ir kaunā tapis par Bēteli, uz ko tie paļāvās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kā jūs varat sacīt: mēs esam varoņi un stipri vīri karā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moabs ir postīts un viņa pilsētās kāpj iekšā, un viņa izlasītie jaunekļi iet pie kaušanas, saka tas ķēniņš, Kungs Cebaot ir viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Moaba posts ir tuvu atnācis, un viņa nelaime ļoti steidzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Žēlojiet viņu visi kaimiņi un visi, kas pazīstat viņa vārdu, sakāt: Ak kā ir salūzis varas scepteris un godības zizlis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Kāp zemē no savas godības, sēdi izkaltušā zemē, iedzīvotāja, Dibonas meita, jo Moaba postītājs pret tevi ceļas un maitā tavas stiprās pilis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Stāvi ceļmalā un raugi, Aroēra iedzīvotāja, vaicā bēglim un prasi izglābtai: kas ir noticis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moabs stāv kaunā, tas ir izbiedināts; kauciet un kliedziet, pasludinājiet pie Arnonas, ka Moabs izpostīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Sodība ir nākusi pār to klajo zemi, pār Holonu un pār Jacku un pār Mevaotu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Un pār Dibonu un pār Nebu un pār BetDiblataīmu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Un pār Kiriataīmu un pār BetGamulu un pār BetMeonu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Un pār Ķiriotu un pār Bacru, un pār visām Moaba zemes pilsētām, kas tālu un tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Moaba rags nocirsts un viņa elkonis satriekts, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Piedzirdinājiet viņu, jo viņš pret To Kungu ir paaugstinājies, lai Moabs žņaudz rokas savā vemšanā, un lai arī viņš ir par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Jo vai Israēls tev nav bijis par apsmieklu? Vai tad viņš tapa pieķerts starp zagļiem, ka tu galvu kratīji, par viņu runādams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Atstājiet pilsētas un dzīvojiet akmens kalnos, Moaba iedzīvotāji, un topiet kā baloži, kas taisa ligzdu pie stāva bezdibeņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Mēs Moaba lepnību esam dzirdējuši, ka tas ir ļoti lepns, viņa augstību un viņa lepnību un viņa greznību un viņa sirds lielību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Es pazīstu viņa trakumu, bet tas neizdosies, saka Tas Kungs, un viņa lielīšanās to nepadarīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Tādēļ Es kaukšu par Moabu un brēkšu par visu Moabu, un kliegšu par Ķirarezetes ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Kā par Jaēzeru, tā Es par tevi raudāšu, tu vīna koks Sibmā! Tavas vīna stīgas cēlušās pār jūru un sniegušās līdz Jaēzeras jūrai; tas postītājs uzkritis dārza un vīna kalna augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Prieks un līksmība ir nost no tā auglīgā tīruma, no Moaba zemes; Es atraušu vīnu no vīna spaidiem, tur nemīdīs vīna ogas ar gavilēm; tās gaviles nav gaviles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'No Hešbonas brēc līdz Elealei, līdz Jācai tie paceļ savu balsi, no Coāras līdz Horonaīmai, līdz EglatŠilišijai, jo ir Nimrimas ūdeņi taps postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Un Es iznīcināšu Moabā, saka Tas Kungs, tos, kas uz elku kalniem upurē, un kas saviem dieviem kvēpina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Tādēļ Mana sirds vaid par Moabu kā stabules, un Mana sirds vaid kā stabules par Ķirarezetes ļaudīm, jo viņu manta, ko tie krājušies, iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Jo visas galvas būs plikas un visas bārdas nodzītas, visas rokas būs sagraizītas, un ap gurniem būs maiss');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Uz visiem Moaba jumtiem un uz visām viņu ielām ir vaidas vien, jo es Moabu esmu sadauzījis tā kā nepatīkamu trauku, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Kā viņš ir iztrūcināts, kā tie kauc, kā Moabs muguru griež savā kaunā! Moabs visiem saviem kaimiņiem ir par apsmieklu un par biedēkli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Jo tā saka Tas Kungs: redzi, viņš ātri skrien kā ērglis, un izplēš savus spārnus pār Moabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Pilsētas ir uzvarētas un stiprās pilis ir uzņemtas, un Moaba vareno sirds būs tai dienā kā sievas sirds bērnu sāpēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Jo Moabs taps izdeldēts, ka vairs nav tauta, jo viņš pret To Kungu ir paaugstinājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Briesmas un bedre un valgs pār tevi, Moaba iedzīvotājs! saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kas izbēg no briesmām, kritīs bedrē, un kas izkāpj no bedres, taps gūstīts valgā, jo Es Moabam sūtīšu viņu piemeklēšanas gadu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Hešbonas ēnā stāv bēdzēji bez spēka, bet no Hešbonas izies uguns un liesma no Sihona un aprīs Moaba pakausi un to trokšņa darītāju galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Vai tev, Moab! Kamosa ļaudis ir gājuši bojā, jo tavi dēli aizvesti cietumā, arī tavas meitas ir cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Bet pēclaikā Es vedīšu atpakaļ Moaba cietumniekus, saka Tas Kungs. Tik daudz par Moaba sodību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Pret Amona bērniem Tas Kungs tā saka: vai tad Israēlim nav bērnu, vai viņam nav mantinieka? Kāpēc tad Malkoms ir Gada mantinieks, un viņa ļaudis dzīvo šajās pilsētās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Tādēļ redzi, nāks dienas, saka Tas Kungs, ka Es pār Amona Rabu likšu dzirdēt kara brēkšanu, un tā taps par gruvešu kopu, un viņas apkārtēji ciemi taps ar uguni sadedzināti. Un Israēls iemantos savus mantotājus, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Kauc, Hešbona, jo Aja ir postīta; kauciet, Rabas meitas, apjoziet maisus, vaidiet un skraidiet apkārt gar mūriem, jo Malkoms ies cietumā ar visiem saviem svētītājiem un lielkungiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Ko tu lielies ar savām ielejām? Tavas ielejas ir pārplūdušas, tu atkāpēja meita, kas paļaujies uz savām mantām (un saki): kas celsies pret mani?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Redzi, saka Tas Kungs Dievs Cebaot, es pār tevi vedīšu bailes no visiem, kas ir ap tevi; jūs tapsiet izdzīti, ikkatrs taisni projām, un neviena nebūs, kas tos bēdzējus sapulcina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Bet pēclaikā Es vedīšu atpakaļ Amona bērnu cietumniekus, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Pret Edomu Tas Kungs Cebaot tā saka: vai tad gudrības vairs nav Temanā? Vai padoms iznīcis pie tiem prātīgiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Vai viņu gudrība izzudusi? Bēdziet, griežaties, slēpjaties, Dedana iedzīvotāji, jo Es vedu nelaimi pār Ēsavu viņa piemeklēšanas laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Ja vīna lasītāji tev būtu uznākuši, tad tie kādus ķekarus būtu atstājuši; kad zagļi būtu nākuši naktī, vai tie nebūtu samaitājuši pēc vajadzības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Bet Es Ēsavu esmu atsedzis, Es viņa slepenās vietas esmu atklājis, ka tas nevarēs apslēpties; viņa dzimums ir postīts un viņa brāļi un viņa kaimiņi, un to vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Atstāj savus bāriņus, tad Es tos uzturēšu dzīvus, un savas atraitnes, lai tās cerē uz Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Jo tā saka Tas Kungs: redzi, kam tiesa nebija biķeri dzert, tiem tiešām jādzer, vai tad tu paliksi bez sodības? Tu nepaliksi bez sodības, bet tu tiešām dzersi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Jo Es esmu zvērējis pie Sevis paša, saka Tas Kungs, ka Bocrai būs tapt par posta vietu, par apsmieklu, par tuksnesi un par lāstu, un visas viņas pilsētas taps par mūžīgiem tuksnešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Es esmu dzirdējis ziņu no Tā Kunga, un vēsts ir sūtīta tautām: sapulcinājaties un nāciet pret viņu un ceļaties karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Jo redzi, Es tevi mazu daru tautu starpā, nicinātu pie cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Bailes no tevis tevi pievīlušas, un tava sirds lepnība, tāpēc ka tu dzīvo klints plaisumos un mīti uz augstiem kalniem. Jebšu tu savu ligzdu tik augsti taisītu kā ērglis, tomēr Es tevi no turienes nogrūdīšu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Tā Edoms būs par tuksnesi, visi, kas viņam ies garām, iztrūcināsies un svilpos par visām viņa mokām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Tā kā Sodoma un Gomora ir apgāztas līdz ar saviem kaimiņiem, saka Tas Kungs, tā tur neviens nedzīvos, un cilvēka bērns tur nemitīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Redzi, viņš ceļas kā lauva no Jardānes vareniem biezumiem pret stipriem dzīvokļiem; jo Es viņu no turienes piepeši aizdzīšu, un kas izredzēts, to Es pār to celšu. Jo kas ir tāds kā Es, un kas Mani sauks tiesā, un kas ir tas gans, kas Manā priekšā pastāvēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Tāpēc klausiet Tā Kunga padomu, ko Viņš nospriedis par Edomu, un Viņa domas, ko Viņš nodomājis par Temana iedzīvotājiem. Tiešām, viņus aizvedīs kā ganāmā pulka jērus; tiešām, viņu ganības iztrūcināsies par viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Zeme trīcēs no viņu krišanas trokšņa; kliegšana, viņas balss būs dzirdama pie niedru jūras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Redzi, viņš celsies un skries kā ērglis un izplētīs savus spārnus pār Bocru. Un Edoma vareno sirds būs tai dienā kā sievas sirds bērnu sāpēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Pret Damasku: Hamata un Arpada kaunas; tās izbijušās, tāpēc ka dzirdējušas bailīgu ziņu; jūrmalā ir bailes, ka nevar dusēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damaskus ir noguris, ir griezies uz bēgšanu, drebuļi to sagrābuši, bailība un sāpes to sagrābušas kā sievu, kas dzemdē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kā? Vai tā nu nav atstāta, tā slavenā pilsēta, Mana prieka pilsēta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Tāpēc viņas jaunekļi kritīs pa viņas ielām, un visi karavīri taps izdeldēti tai dienā, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Un es iededzināšu uguni Damaskus mūros, un tas norīs BenHadada skaistos namus. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Pret Ķedaru un Hacora valstīm, ko Nebukadnecars, Bābeles ķēniņš, sakāva, Tas Kungs tā saka: ceļaties, ejat pret Ķedaru, un postait austruma bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Tie paņems viņu dzīvokļus un ganāmos pulkus, viņu teltis un visus viņu rīkus, un aizvedīs sev viņu kamieļus un izsauks pār tiem: briesmas visapkārt!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Bēdziet, skrieniet ātri, paslēpjaties, Hacora iedzīvotāji, saka Tas Kungs! Jo Nebukadnecars, Bābeles ķēniņš, pret jums nospriedis padomu un pret jums nodomājis domas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Ceļaties, ejat pret tiem ļaudīm, kas mierīgi un droši dzīvo, saka Tas Kungs, kam nedz durvju, nedz aizšaujamo, - tie dzīvo par sevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Viņu kamieļi būs par laupījumu, un viņu lielie ganāmie pulki taps aizvesti. Un Es izkaisīšu visos vējos tos, kam apcirptas bārdas, un no visām pusēm Es pār viņiem atvedīšu samaitāšanu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Un Hacors būs par mājas vietu tuksneša zvēriem un postā(neauglīgu vietu) mūžam; tur neviens nedzīvos, cilvēka bērns tur nemitīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Šis ir Tā Kunga vārds, kas notika uz pravieti Jeremiju pret Elamu, Cedeķijas, Jūda ķēniņa, valdīšanas iesākumā, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Tā saka Tas Kungs Cebaot: redzi, Es salauzīšu Elama stopu, viņa stiprāko varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Un Es vedīšu pār Elamu tos četrus vējus no tām četrām debess malām, un Es tos izkaisīšu šinīs vējos, un tautas nebūs, kurp nenāks Elama aizdzītie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Un Es izbiedināšu Elamu viņa ienaidnieku priekšā un to priekšā, kas meklē viņa dvēseli, un vedīšu pār tiem ļaunumu, savas dusmības karstumu, saka Tas Kungs; un Es sūtīšu zobenu tiem pakaļ, tiekams tiem būšu galu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Un Es celšu Savu goda krēslu Elamā un iznīcināšu no turienes ķēniņu un lielkungus, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Bet pēclaikā Es vedīšu atpakaļ Elama cietumniekus, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Šis ir tas vārds, ko Tas Kungs runājis pret Bābeli, pret Kaldeju zemi, caur pravieti Jeremiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Sludinājiet starp tautām un izsauciet to un izceļat karogu, izsauciet un neapslēpiet to, sakāt: Bābele uzņemta, Bels stāv kaunā, Merodaks satriekts, viņu dievekļi apkaunoti, viņu elkudievi satriekti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Jo pret viņu nāk tauta no ziemeļa puses; tā viņas zemi darīs par tuksnesi bez iedzīvotāja; tā cilvēki kā lopi bēguši, aizgājuši projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Tanīs dienās un tanī laikā, saka Tas Kungs, Israēla bērni līdz ar Jūda bērniem nāks; tie ies raudādami vienā raudāšanā un meklēs To Kungu, savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Tie vaicās pēc Ciānas, viņu vaigi (griezīsies) šurp pa to ceļu. Nāciet, pieķersimies Tam Kungam mūžīgā derībā, kas netaps aizmirsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mani ļaudis bija pazudušas avis, viņu gani tās bija pievīluši, tie tās bija maldinājuši kalnos, ka gāja no kalniem uz pakalniem, aizmirsa savus laidarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Visi, kas tos atrada, tos aprija, un viņu pretinieki sacīja: mēs nebūsim noziedzīgi, jo tie ir grēkojuši pret To Kungu, pret to taisnības dzīvokli un viņu tēvu patvērumu, pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Bēdziet no Bābeles un ejat ārā no Kaldeju zemes un esiet tie auni ganāmā pulka priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Jo redzi, Es celšu lielu tautu pulku no ziemeļa zemes un to vedīšu pret Bābeli; tie pret viņu nostāsies, un tad viņa taps uzņemta. Viņu bultas būs kā no krietna karavīra, neviena neatgriezīsies tukša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Un Kaldeju zeme būs par laupījumu; visi, kas to aplaupa, pieēdīsies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Jo priecājaties tik vien un lecat no prieka, jūs Manas mantības postītāji; lecat tik vien kā tele uz metiena un zviedzat kā ērzeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Jūsu māte taps ļoti apkaunota, kas jūs dzemdējusi, tā nosarks; redzi, pagānu gals ir tuksnesis, sausums un posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Aiz Tā Kunga dusmības tur nedzīvos, bet tā būs pavisam tuksnesis; visi, kas Bābelei ies garām, brīnīsies un svilpos par viņas mokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Taisāties pret Bābeli visapkārt, visi, kas stopu velk, šaujiet uz to, netaupiet bultas, jo tā grēkojusi pret To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Ceļat visapkārt kara troksni pret to! Tā padevusies, viņas pamati gruvuši, viņas mūri noārdīti. Jo tā ir Tā Kunga atriebšana; atriebjaties pret viņu, tā kā viņa darījusi, tā dariet viņai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Izdeldat no Bābeles tā sējēju, kā to, kas sirpi ņem rokā pļaujamā laikā! No tā briesmīgā zobena ikviens griezīsies pie savas tautas un ikviens bēgs uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israēls ir noklīdusi avs, ko lauvas trenkājušas. Tas pirmais, kas viņu ēdis, bija Asīrijas ķēniņš, un nu pēdīgi Nebukadnecars, Bābeles ķēniņš, satriecis viņa kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Tādēļ tā saka Tas Kungs Cebaot, Israēla Dievs: redzi, Es piemeklēšu Bābeles ķēniņu un viņa zemi, tā kā esmu piemeklējis Asīrijas ķēniņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Un vedīšu Israēli atpakaļ viņa dzīvoklī, un tas ganīsies pa Karmeli un Basanu, un viņa dvēsele taps pieēdināta pa Efraīma un Gileāda kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Tanīs dienās un tanī laikā, saka Tas Kungs, Israēla noziegums taps meklēts, bet vairs nebūs, un Jūda grēki, bet tie netaps atrasti, jo Es tiem piedošu, ko Es atlicināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Celies pret to divkārtīgo dumpotāju zemi un pret tiem iedzīvotājiem, kas taps piemeklēti; posti un deldē viņiem pakaļ dzīdamies, saka Tas Kungs, un dari, tā kā Es tev esmu pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Kara troksnis tai zemē un liels posts!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kā visas pasaules veseris salauzts un satriekts! Kā Bābele palikusi par posta vietu starp tautām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Es tev esmu licis valgus, un tu nezinot esi savaldzināta, Bābele; tu esi atrasta un sagrābta, tādēļ ka tu Tam Kungam esi turējusies pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Tas Kungs Savu mantas namu atdarījis un Savas dusmības rīkus ņēmis ārā, jo Tam Kungam, Tam Kungam Cebaot, ir darbs Kaldeju zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Nāciet šurp pret viņu no pasaules gala, atdariet viņas klētis, sametiet to kā labību kaudzēs, un izdeldiet to, ka no tās nekas neatliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Nokaujiet visus viņas vēršus, lai tie iet pie kaušanas. Ak vai, par tiem! Jo viņu diena ir nākusi, viņu piemeklēšanas laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Klau! Bēgļi un izsprukušie no Bābeles zemes, lai pasludina Ciānā Tā Kunga, mūsu Dieva, atriebšanu, to atriebšanu Viņa nama dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Sasauciet pret Bābeli strēlniekus; visi, kas stopu velkat, apmetaties ap viņu, ka neviens neizsprūk, atmaksājiet viņai pēc viņas darba, dariet viņai, tā kā viņa darījusi. Jo tā ir lepojusies pret To Kungu, to Svēto iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Tāpēc viņas jaunekļi kritīs pa viņas ielām, un visi viņas karavīri tai dienā taps izdeldēti, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Redzi, Es ceļos pret tevi, tu lepnā, saka Tas Kungs, Tas Kungs Cebaot: jo tava diena ir nākusi, tavas piemeklēšanas laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Tad tā lepnā klups un kritīs, un nebūs, kas viņu uzcels, jo Es iededzināšu uguni viņas pilsētās; tas visu norīs visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Tā saka Tas Kungs Cebaot: Israēla bērni līdz ar Jūda bērniem ir nospaidīti, un visi, kas tos cietumā likuši, viņus tura stipri un liedzās viņus atlaist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Bet viņu Pestītājs ir stiprs, Kungs Cebaot ir viņa vārds, viņš tiesādams tiesās viņu lietu, ka šo zemi dara dusam, bet Bābeles iedzīvotājus drebam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Zobens nāks pār Kaldejiem, saka Tas Kungs, un pār Bābeles iedzīvotājiem, un pār viņas lielkungiem un pār viņas gudriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Zobens nāks pār viņas zīlniekiem, ka tie top par ģeķiem, zobens pār viņas vareniem, ka tie baiļojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Zobens pār viņas zirgiem un pār viņas ratiem un pār visu saskrējušo ļaužu pulku, kas ir viņas vidū, ka tie paliek par bābām; zobens pār viņas mantām, ka tās top laupītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Kaltētājs nāks pār viņas ūdeņiem, ka tie izsīkst; jo tā ir elkdievīga zeme un trako ar saviem dievekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Tāpēc tur mitīs tuksneša zvēri un kaucēji, ir jauni strausi tur dzīvos, un tā vairs netaps apdzīvota ne mūžam, un tur iedzīvotāju nebūs līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Tā kā Dievs apgāzis Sodomu un Gomoru un viņu kaimiņus, saka Tas Kungs, tā tur neviens nedzīvos nedz cilvēku bērns tur mitīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Redzi, tauta nāk no ziemeļa puses, liela tauta, un daudz ķēniņi cēlās no pasaules galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Tiem ir stopi un šķēpi, tie ir bargi un nebūs žēlīgi, viņu balss kauks kā jūra, un tie jās uz zirgiem apbruņoti kā karavīri pret tevi, Bābeles meita!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Bābeles ķēniņš dzird viņu baumu, un viņa rokas nogurst, bailes viņu sagrābj, sāpes kā sievu, kas dzemdē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Redzi, viņš ceļas kā lauva no Jardānes vareniem biezumiem pret stipriem dzīvokļiem; jo Es viņu no turienes piepeši aizdzīšu, un kas ir izredzēts, to Es pār to celšu. Jo kas ir tāds kā Es, un kas Mani sauks tiesā, un kas ir tas gans, kas Manā priekšā pastāvēs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Tāpēc klausāt Tā Kunga padomu, ko Viņš nospriedis par Bābeli, un Viņa domas, ko Viņš nodomājis par Kaldeju zemi. Tiešām, viņus aizvedīs kā ganāmā pulka jērus; tiešām, viņu ganības iztrūcināsies par viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Un zeme trīcēs no trokšņa, ka Bābele uzņemta, un brēkšana būs dzirdama starp tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Tā saka Tas Kungs: redzi, Es celšu maitātāja garu pret Bābeli un pret tiem, kas dzīvo Manu pretinieku serdē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Un Es sūtīšu Bābelei vētītājus, kas tos vētīs un iztukšos viņas zemi, jo tie būs visapkārt ap viņu nelaimes dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Lai strēlnieks stopu uzvelk pret strēlnieku un pret to, kas lepojās savās krūšu bruņās. Un nežēlojiet viņas jaunekļus, izdeldiet visu viņas spēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Ka nokauti krīt Kaldeju zemē un nodurti pa viņas ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Jo Israēls un Jūda savā atraitnībā netaps pamesti no sava Dieva, Tā Kunga Cebaot, jebšu viņu zeme noziegusies pret to Svēto iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Bēdziet no Bābeles un izglābiet ikviens savu dvēseli, ka neejat bojā viņas noziegumā, jo šis ir Tā Kunga atriebšanas laiks, Viņš tai atmaksā algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Bābele bija zelta biķeris Tā Kunga rokā, kas piedzirdināja visu pasauli; tautas dzēra no viņas vīna, tāpēc tautas palika trakas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Bābele ir piepeši kritusi un satriekta. Kauciet par viņu, ņemiet zāles viņas vātīm, varbūt tā taps dziedināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Mēs Bābeli dziedinājām, bet tā nav sadzijusi. Atstājiet viņu, un ejam ikviens uz savu zemi, jo viņas sodība iet līdz pat debesīm un aizsniedz padebešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Tas Kungs ir gaismā nesis mūsu taisnību, nāciet, lai izteicam Ciānā Tā Kunga, sava Dieva, darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Trinat bultas, sagrābiet bruņas; Tas Kungs pamodinājis Mēdiešu ķēniņu sirdi, jo Viņa padoms ir pret Bābeli, to samaitāt; jo šī ir Tā Kunga atriebšana, atriebšana Viņa nama dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Izceļat karogu uz Bābeles mūriem, vairojiet sargāšanu, ieceļat sargus, liekat karotājus slepenās vietās; jo Tas Kungs ir ko apņēmies un darīs arīdzan, ko Viņš runājis pret Bābeles iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Tu, kas pie tā lielā ūdens dzīvo, kam daudz mantas, tavs gals nācis, un tavas mantas kārības mērs ir pilns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Tas Kungs Cebaot ir zvērējis pie Savas dvēseles: “Lai gan Es tevi esmu pildījis ar cilvēkiem kā ar siseņiem; tomēr pret tevi dziedās prieka dziesmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Kas zemi radījis ar Savu spēku, kas pasauli iztaisījis ar Savu gudrību un debesis izpletis ar Savu saprašanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kad viņa balss atskan, tad ūdeņi krāc debesīs; Viņš liek miglai celties no zemes galiem. Viņš dara zibeņus ar lietu un liek vējam ārā nākt no savām alām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Visi cilvēki paliek stulbi bez saprašanas, visi kausētāji top kaunā ar saviem tēliem; jo ko tie lej, ir meli, un dvašas tur nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Tie ir nelietība un apsmejams darbs, piemeklēšanas laikā tie iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Tā kā šie nav Jēkaba daļa, jo viņš ir visu lietu un savas tautas Radītājs, Kungs Cebaot ir viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Tu esi Mans veseris, Manas kara bruņas, un caur tevi Es sadauzu tautas, un caur tevi Es maitāju valstis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Un caur tevi Es sadauzu zirgu un viņa jātnieku, un caur tevi Es sadauzu ratus un braucējus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Un caur tevi Es sadauzu vīrus un sievas, un caur tevi Es sadauzu vecus un jaunus, un caur tevi Es sadauzu jaunekļus un jaunietes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Un caur tevi Es sadauzu ganu un viņa ganāmo pulku, caur tevi Es sadauzu arāju un viņa jūgu, un caur tevi Es sadauzu kungus un valdniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Bet Bābelei un visiem Kaldeju zemes iedzīvotājiem Es atmaksāšu pēc visas viņu bezdievības, ko tie darījuši pie Ciānas priekš jūsu acīm, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Redzi, saka Tas Kungs, Es celšos pret tevi, maitātāja kalns, kas visu pasauli samaitā, un Es izstiepšu Savu roku pret tevi un tevi novelšu no taviem akmeņu kalniem, un darīšu tevi par degošu kalnu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Ka no tevis nevar ņemt nedz stūra akmeni nedz pamata akmeni, jo tu būsi par mūžīgu posta vietu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Izceļat karogu virs zemes, bazūnējat ar bazūnēm starp tautām, sataisiet tautas uz karu pret viņu, aicinājiet pret viņu Ararata, Meni un Aškenasa valstis, ieceļat kara virsnieku pret viņu, atvediet zirgus kā briesmīgus siseņus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Sataisiet tautas uz karu pret viņu, Medijas ķēniņus, viņas valdniekus un visus viņas lielkungus un visas viņu valstis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Tad zeme drebēs un trīcēs, jo Tā Kunga domas pret Bābeli piepildās, darīt Bābeles zemi par posta vietu bez iedzīvotāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Bābeles varenie mitējušies karot, tie paliek stiprās pilīs, viņu vara ir izsīkusi, tie ir tapuši par bābām, viņas māju vietas iededzinātas, viņas aizšaujamie salauzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Bēglis tek bēglim pretī un vēstnesis vēstnesim, un stāsta Bābeles ķēniņam, ka viņa pilsēta ieņemta no visām pusēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Un ka braslas ieņemtas, un dīķi ugunī nodeguši, un karavīri noguruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Jo tā saka Tas Kungs Cebaot, Israēla Dievs: Bābeles meita ir kā klons kuļamā laikā; vēl maķenīt, tad viņai nāks pļaujamais laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebukadnecars, Bābeles ķēniņš, mani aprijis, viņš mani sadauzījis, viņš mani darījis par tukšu trauku, viņš mani aprijis kā pūķis, viņš savu vēderu pildījis ar maniem gardumiem, viņš mani aizdzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Tas varas darbs, kas man un manai miesai darīts, lai nāk pār Bābeli, tā lai saka Ciānas iedzīvotāja, un manas asinis lai nāk pār Kaldejas iedzīvotājiem, tā lai saka Jeruzāleme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Tādēļ Tas Kungs tā saka: “Redzi, Es tiesāšu tavu lietu un tevi atriebšu, un Es viņas jūrai likšu izsīkt un viņas avotiem izžūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Un Bābele taps par akmeņu kopu, par šakāļu mājokli, par tuksnesi un par apsmieklu, bez iedzīvotāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Tie kopā rūks kā lauvas un ņurdēs kā jauni lauvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Kad tie būs iekarsēti, tad es tiem celšu priekšā viņu dzērienu un tos piedzirdināšu, ka tie bļaustīsies, bet aizmigsies uz mūžīgu miegu un ne mūžam vairs neuzmodīsies,” saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, '“Es tos vedīšu kā jērus pie kaušanas, kā aunus ar āžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kā Šešaks tā ir ieņemts un pasaules slava tā pārvarēta! Kā Bābele ir tapusi par biedēkli starp tautām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Jūra ir plūdusi pār Bābeli, un ar viņas viļņu pulku tā ir apklāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Viņas pilsētas palikušas par tuksnesi, par izkaltušu sausu zemi, par zemi, kur neviens nedzīvo, kur cilvēka bērns nestaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Un Es piemeklēšu Belu Bābelē un izraušu no viņa rīkles, ko viņš ierijis, un tautas vairs netecēs pie viņa, jo arī Bābeles mūri ir krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Izejiet, Mani ļaudis, no viņas vidus, un izglābiet ikviens savu dvēseli no Tā Kunga bardzības karstuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Un jūsu sirds lai netop bailīga, un neizbīstaties no tās baumas, kas tai zemē taps dzirdēta; jo bauma nāks vienā gadā, un pēc tam cita bauma otrā gadā, un varas darbs būs tai zemē, valdnieks pret valdnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Tāpēc redzi, nāk dienas, tad Es piemeklēšu Bābeles dievekļus, un visa viņas zeme taps kaunā un visi viņas nokautie gulēs viņas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Un par Bābeli gavilēs debesis un zeme, un viss, kas tur ir, ka no ziemeļa puses pār viņu nāk postītāji, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Un kā Bābele gāzusi Israēla nokautos, tā Bābelē kritīs visas zemes nokautie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Jūs no zobena izglābtie, ejat un nestāviet! Pieminiet To Kungu tālā zemē un turat Jeruzālemi savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Mēs esam palikuši kaunā, jo mēs esam dzirdējuši apsmieklu; kauns ir apklājis mūsu vaigu, tāpēc ka sveši nākuši pār Tā Kunga nama svētumu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, '“Tāpēc redzi, nāk dienas,” saka Tas Kungs, “tad Es piemeklēšu viņas dievekļus, un visā viņas zemē vaidēs nāvīgi ievainotie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Jebšu Bābele kāptu debesīs un stiprinātu savu varu augstībā, tad tomēr postītāji no Manis nāks pār viņu,” saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Kliegšanas balss ir dzirdama no Bābeles un liels posts no Kaldejas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Jo Tas Kungs izposta Bābeli un iznīcina no tās to lielo troksni, jo viņu viļņi kauc kā vareni ūdeņi, viņu varenais troksnis skan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Jo postītājs nāk pār viņu, pār Bābeli, un viņas varenie top gūstīti, viņu stopi top salauzti. Jo Tas Kungs ir Dievs, tas atmaksātājs, atmaksādams viņš atmaksā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, '“Un Es piedzirdināšu viņas lielkungus un viņas gudros, viņas valdniekus un viņas virsniekus un viņas varoņus, un tie gulēs mūžīgu miegu un neuzmodīsies,” saka tas ķēniņš, kam vārds ir Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Tā saka Tas Kungs Cebaot: “Platie Bābeles mūri visai(pilnīgi) taps nopostīti, un viņas augstie vārti ar uguni sadedzināti, tā ka tautas velti strādājušas, un ļaudis ugunij par labu pūlējušies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Šis ir tas vārds, ko pravietis Jeremija pavēlēja Serajam, Nerijas dēlam, Mazejas dēla dēlam, kad šis ar Cedeķiju, Jūda ķēniņu, gāja uz Bābeli, viņa valdīšanas ceturtā gadā, un Seraja bija tas ceļa lielkungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Un Jeremija rakstīja visu to ļaunumu, kam bija nākt pār Bābeli, grāmatā, visus šos vārdus, kas rakstīti pret Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Un Jeremija sacīja uz Seraju: “Kad tu nonāksi Bābelē, tad pielūko un lasi visus šos vārdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Un saki: ak Kungs, Tu pret šo vietu esi runājis, ka to gribi izdeldēt, tā ka tur vairs nepaliek iedzīvotāju, ne cilvēku ne lopu, bet ka tai jāpaliek par mūžīgu posta vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Un kad tu šo grāmatu esi izlasījis, tad piesien pie tās akmeni un iemet to Eifrat upē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'Un saki: tāpat Bābele nogrims un nenāks vairs augšā aiz tās nelaimes, ko Es pār viņu vedīšu, un tie nogurs.” Tik tālu Jeremijas vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Cedeķija bija divdesmit un vienu gadu vecs, kad tapa par ķēniņu, un valdīja vienpadsmit gadus Jeruzālemē; viņa mātes vārds bija Amutale, Jeremijas meita no Libnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Un viņš darīja, kas bija ļauns Tā Kunga acīs, tā kā Jojaķims bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Jo tā notika Tā Kunga bardzības dēļ pret Jeruzālemi un pret Jūdu, līdz kamēr Viņš tos atmeta no Sava vaiga. Un Cedeķija atkāpās no Bābeles ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Un viņa valdīšanas devītā gadā, desmitā mēnesī, desmitā mēneša dienā, Nebukadnecars, Bābeles ķēniņš, nāca pats ar visu savu karaspēku pret Jeruzālemi, un tie apmetās ap viņu un uztaisīja pret viņu visapkārt vaļņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Tā tā pilsēta tapa apsēsta līdz ķēniņa Cedeķijas vienpadsmitam gadam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Ceturtā mēnesī, devītā mēneša dienā, bads augtin auga pilsētā, un zemiem ļaudīm nebija vairs maizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Tad ielauzās pilsētā un visi karavīri bēga un izgāja naktī no pilsētas ārā pa vārtu ceļu starp abiem mūriem pie ķēniņa dārza. Bet Kaldeji bija visapkārt ap pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Un viņi gāja pa klajuma ceļu; bet Kaldeju spēks dzinās ķēniņam pakaļ un panāca Cedeķiju Jērikus klajumos, un viss viņa spēks izklīda no viņa nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Tad tie sagrāba ķēniņu un viņu noveda pie Bābeles ķēniņa uz Riblu Hamatas zemē, un tas sprieda tiesu par viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Un Bābeles ķēniņš nokāva Cedeķijas bērnus priekš viņa acīm, ir visus Jūda lielkungus viņš nokāva Riblā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Un viņš izdūra Cedeķijam acis un viņu saistīja ar divām vara ķēdēm; un Bābeles ķēniņš viņu noveda uz Bābeli un viņu lika cietuma namā līdz viņa miršanas dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Pēc tam, piektā mēnesī, desmitā mēneša dienā, tas bija ķēniņa Nebukadnecara, Bābeles ķēniņa, deviņpadsmitais gads, NebuzarAdans, pils karavīru virsnieks, kas stāvēja Bābeles ķēniņa priekšā, nāca uz Jeruzālemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Un sadedzināja Tā Kunga namu un ķēniņa namu līdz ar visiem Jeruzālemes namiem, un visus lielos namus viņš sadedzināja ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Un viss Kaldeju spēks, kas bija pie pils karavīru virsnieka, nolauza visus Jeruzālemes mūrus visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Bet zemas kārtas ļaudis un tos atlikušos, kas pilsētā bija atlicināti, un tos bēgļus, kas bija pārgājuši pie Bābeles ķēniņa, un tos citus darba ļaudis, pils karavīru virsnieks Nebuzar Adans, aizveda projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Bet no tiem zemas kārtas ļaudīm tai zemē pils karavīru virsnieks NebuzarAdans kādus atlicināja par vīna dārzniekiem un arājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Un Kaldeji nolauza tos vara pīlārus pie Tā Kunga nama un tos krēslus un to vara jūru, kas bija Tā Kunga namā, un veda visu viņas varu uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Tie paņēma arī tos podus un tās lāpstas un dakšas un tos slakāmos traukus un biķerus un visus vara traukus, ko lietoja pie kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Un pils karavīru virsnieks paņēma līdz tos kausus un vīraka traukus un slakāmos kausus un podus un lukturus un karotes un krūzes, kas bija tīra zelta un tīra sudraba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Tos abus pīlārus, to vienu jūru, tos divpadsmit vara vēršus apakš tās un tos krēslus, ko ķēniņš Salamans bija taisījis priekš Tā Kunga nama. Tas varš no tā, no visiem tiem rīkiem, nebija sverams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Un katra pīlāra augstums bija astoņpadsmit olektis un divpadsmit olekšu aukla gāja ap pīlāri apkārt, un tas varš bija četru pirkstu biezumā un vidū tukšs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Un tas kronis uz pīlāra bija no vara, un ikkatra kroņa augstums bija piecas olektis, un tīkla darbs un granātāboli bija ap to kroni visapkārt, viss no vara; un tāpat arī bija pie tā otra pīlāra, un arī tie granātāboli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Un to granātābolu bija deviņdesmit seši pret visiem vējiem, visu granātābolu bija simts tam tīkla darbam visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Pils karavīru virsnieks ņēma augsto priesteri Seraju un to otru priesteri Cefaniju un trīs sliekšņa sargus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Un no pilsētas viņš ņēma vienu ķēniņa sulaini, kas bija celts pār tiem karavīriem, un septiņus vīrus no tiem, kas bija ap ķēniņu, kas pilsētā tapa atrasti, ir kara vadoņa rakstītāju, kas tās zemes ļaudis priekš kara uzrakstīja, un sešdesmit vīrus no tās zemes ļaudīm, kas pilsētā tapa atrasti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Tos pils karavīru virsnieks NebuzarAdans ņēma un veda pie Bābeles ķēniņa uz Riblu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Un Bābeles ķēniņš tos sita un nokāva Riblā Hamatas zemē. Tā Jūda no savas zemes tapa aizvests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Šie ir tie ļaudis, ko Nebukadnecars aizveda septītā gadā: trīs tūkstoš divdesmit trīs Jūdus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Nebukadnecara astoņpadsmitā gadā: astoņsimt trīsdesmit divas dvēseles no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Nebukadnecara divdesmit trešā gadā, pils karavīru virsnieks NebuzarAdans aizveda septiņsimt četrdesmit piecas Jūdu dvēseles; pavisam četrtūkstoš un sešsimt dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Bet trīsdesmit septītā gadā pēc Jojaķima, Jūda ķēniņa, aizvešanas, divpadsmitā mēnesī, divdesmit piektā mēneša dienā, Evil-Merodaks Bābeles ķēniņš savā pirmā valdīšanas gadā, paaugstināja Jojaķima, Jūda ķēniņa, galvu un to izveda no cietuma nama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Un runāja laipnīgi ar viņu un cēla viņa krēslu pār to ķēniņu krēsliem, kas pie viņa bija Bābelē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Un pārmija viņa cietuma drēbes, un šis ēda maizi vienmēr viņa priekšā visu savu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Un barība viņam vienmēr no Bābeles ķēniņa tapa dota, ikdienas nospriesta tiesa, līdz viņa miršanas dienai visu viņa mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Ak cik vientule palikusi tā pilsēta, kas bija ļaužu pilna! Tā ir kā atraitne, kas bija liela starp tautām, tā valdniece starp valstīm ir palikusi par kalponi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Viņa raudāt raud naktīm, un viņas asaras tek pār viņas vaigu; iepriecinātāja tai nav starp visiem viņas mīļotājiem; visi viņas draugi turas viltīgi pret viņu, tie viņai palikuši par ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Jūda cilts gājusi svešumā aiz bēdām un aiz grūtas kalpošanas, tā dzīvo starp pagāniem, neatrod dusas; visi viņas vajātāji to panākuši šaurumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Ciānas ceļi bēdājās, ka neviens nenāk svētkos; visi viņas vārti ir postīti; viņas priesteri nopūšas, viņas jaunavas noskumušas, un viņai ir rūgtas bēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Viņas pretiniekiem tikusi virsroka, viņas ienaidniekiem klājās labi; jo Tas Kungs viņu apbēdinājis viņas lielās pārkāpšanas dēļ; viņas bērniņi iet cietumā pretinieka priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'No Ciānas meitas nozudis viss viņas jaukums; viņas lielkungi ir kā stirnas, kas neatrod ganību un iet bez spēka vajātāja priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jeruzāleme savās bēdu- un klaidu- dienās piemin visu savu jaukumu, kas viņai bijis pagājušā laikā; kad nu viņas ļaudis krīt caur pretinieku roku, un palīga viņai nav, pretinieki viņai skatās virsū un apsmej viņas svētās dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jeruzāleme ļoti grēkojusi, tāpēc viņa tapusi kā sārņaina sieva; visi, kas viņu cienīja, viņu tur negodā, tāpēc ka redz viņas kaunu; un viņa vaid un ir griezusies atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Viņas sārņi līp pie viņas vīlēm; tā nav domājusi uz savu galu, tāpēc viņa brīnišķi ir nogāzta, un iepriecinātāja tai nav; uzlūko, Kungs, manas bēdas, jo ienaidnieks lielās!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Pretinieks savu roku ir izstiepis pie visiem viņas dārgumiem; jo viņai bija jāredz, kā pagāni gāja tai svētā vietā, par kuriem tu esi pavēlējis, ka tiem nebūs nākt tavā draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Visi viņas ļaudis nopūšās, meklēdami maizes; tie savus dārgumus izdevuši par barību, dvēseli atspirdzināt; redzi, Kungs, un ņem vērā, kā es esmu nākusi negodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Vai jūs to neievērojat visi, kas pa ceļu staigājiet? Skatāties un raugiet, vai kādas sāpes ir kā manas sāpes, kas man uznākušas, ar ko Tas Kungs mani apbēdinājis Savas karstās bardzības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'No augšienes Viņš uguni metis manos kaulos, un tas tos pārspējis. Viņš manām kājām izpletis tīklu un man licis atpakaļ griezties, Viņš mani postījis un darījis sērdzīgu(vāju) cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Manu grēku jūgs ir sasiets caur Viņa roku, tie ir sapinušies un nākuši pār manu kaklu; Viņš manu spēku ir salauzis; Tas Kungs mani nodevis tādiem rokā, kam nevaru pretī turēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Tas Kungs aizrāvis visus manus varenos manā vidū; Viņš ir izsaucis sapulci pār mani, satriekt manus jaunekļus. Tas Kungs vīna spaidu minis tai jaunavai, Jūda meitai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Par to mana acs raud, manas acis asaru pilnas, tāpēc ka iepriecinātājs ir tālu no manis, kas varētu atspirdzināt manu dvēseli; mani bērni ir postīti, jo ienaidnieks ir pārvarējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Ciāna izpleš savas rokas, iepriecinātāja tai nav; jo Tas Kungs ir sasaucis pret Jēkabu viņa spaidītājus visapkārt; Jeruzāleme ir kā sārņaina sieva viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Tas Kungs ir taisns, jo es Viņa mutei(baušļiem) esmu pretī turējusies. Klausiet jel, visas tautas, un redziet manas sāpes; manas jaunavas un mani jaunekļi ir gājuši cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Es piesaucu savus mīļotājus, bet tie mani vīluši; mani priesteri un vecaji pilsētā nonīkuši, kad meklēja sev barības, atspirdzināt savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Redzi, Kungs, kā man ir bail; manas iekšas rūgst, mana sirds lec iekš manis, jo es esmu gauži turējusies pretī; ārā zobens man laupījis bērnus un iekšā nāve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Tie gan dzird mani vaidam, bet iepriecinātāja nav; visi mani ienaidnieki dzird manu nelaimi un priecājās, ka Tu tā esi darījis; kad Tu to dienu atvedīsi, ko esi sludinājis, tad tie būs tā kā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Lai nāk visa viņu bezdievība Tavā priekšā, un dari tiem, kā Tu man esi darījis visu manu pārkāpumu dēļ, jo manu nopūtu ir daudz, un mana sirds ir nogurusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Ak kā Tas Kungs ar Savu dusmību apklājis Ciānas meitu! Israēla godību Viņš nometis no debesīm zemē, nav pieminējis Savu kāju pameslu Savas dusmības dienā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Tas Kungs visus Jēkaba dzīvokļus aprijis un nav žēlojis; Viņš Jūda meitas stiprās pilis ir nolauzījis Savā dusmībā; Viņš nometis pie zemes, Viņš sagānījis to valsti un viņas valdniekus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Savā bargā dusmībā Viņš salauzis ikvienu Israēla ragu; Viņš Savu labo roku atvilcis, kad ienaidnieki nāca, Viņš iededzies pret Jēkabu kā uguns liesma, kas rij visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Viņš Savu stopu uzvilcis kā ienaidnieks, un Savu labo roku pacēlis kā pretinieks un visu nokāvis, kas acīm patīk; Viņš Savu bardzību izgāzis kā uguni Ciānas meitas dzīvoklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Tas Kungs palicis par ienaidnieku, Viņš Israēli aprijis; Viņš aprijis visus viņa skaistos namus, Viņš nopostījis viņa stiprās pilis un Jūda meitai ir vairojis nopūtas un vaidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Viņš noplēsis Savu dzīvokli, kas bija kā dārzs, un nopostījis Savu saiešanas vietu; Tas Kungs Ciānā licis aizmirst svētkus un svētdienas, un Savā bargā dusmībā atmetis ķēniņu un priesteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Tas Kungs atmetis Savu altāri, Viņš iznīcinājis Savu svēto vietu; viņas skaisto namu mūrus Viņš ienaidniekiem devis rokā, šie Tā Kunga namā balsi pacēluši tā kā svētku dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Tas Kungs nodomājis samaitāt Ciānas meitas mūrus, Viņš to mērauklu vilcis, Savu roku Viņš nav atgriezis, kamēr to aprija; un Viņš apbēdinājis valni un mūri; tie abi sagruvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Viņas vārti nogrimuši zemē, Viņš viņas aizšaujamos maitājis un satriecis; viņas ķēniņš un viņas lielkungi ir starp pagāniem, bez bauslības, arī viņas pravieši neatrod vairs parādīšanu no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Ciānas meitas vecaji sēž pie zemes un cieš klusu, tie met pīšļus uz savu galvu un apjozuši maisus; Jeruzālemes meitas nokārušas savu galvu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Manas acis izēstas no asarām, manas iekšas rūgst; manas aknas ir izkratītas pie zemes manu ļaužu meitas posta dēļ, tādēļ ka bērniņi un zīdāmie iztvīkst pa pilsētas ielām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Uz savām mātēm tie sauca: kur ir labība un vīns? Kad tie pamira kā nokauti pa pilsētas ielām, un savu dvēseli izlaida savas mātes klēpī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kādu liecību es tev varu atnest, kam es tevi varu līdzināt, Jeruzālemes meita? Kam es tevi varu līdzināt, ka es tevi iepriecinātu, ak jaunava, Ciānas meita! Jo tavs posts ir liels kā jūra; kas tevi var dziedināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Tavi pravieši tev sludinājuši nelietību un viltu un tev nav atklājuši tavu noziegumu, ka tavu cietumu novērstu, bet tev sludinājuši nelietīgas un viltīgas mācības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Visi, kas tev iet garām, plaukšķina ar rokām par tevi, tie svilpo un krata savas galvas par Jeruzālemes meitu: „Vai šī tā pilsēta, par ko sacīja: ka tā, tā visskaistākā un visas zemes prieks?“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Visi tavi ienaidnieki atplēš savu muti pret tevi, svilpo un sakož zobus un saka: mēs to esam aprijuši. Redzi, šī ir tā diena, uz ko mēs gaidījām, mēs to esam sagaidījuši, mēs to esam redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Tas Kungs ir darījis, ko bija nodomājis, Viņš Savu vārdu piepildījis, ko bija pavēlējis sendienās; Viņš ir salauzis un nav žēlojis un ienaidnieku par tevi darījis priecīgu un paaugstinājis tavu pretinieku ragu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Viņu sirds brēc uz To Kungu. Ak Ciānas meitas mūri, lai dienām naktīm asaras plūst kā upe, un nedodies mierā, un tava acs lai nežūst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Celies, brēc naktī; kad sāk tumsa mesties, tad izgāz Tā Kunga priekšā savu sirdi kā ūdeni, pacel savas rokas uz Viņu par savu bērniņu dvēselēm, kas badu miruši pa visu ielu galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Redzi, Kungs, lūko jel, kam Tu tā esi darījis? Vai tad sievām būs ēst savas miesas augļus, tos bērniņus, ko auklējušas? Vai tad priesteriem un praviešiem būs tapt nokautiem Tā Kunga svētā vietā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Jauni un veci guļ pie zemes pa ielām, manas jaunavas un mani jaunekļi krituši caur zobenu; Tu tos esi nokāvis Savas bardzības dienā, Tu esi nokāvis un neesi žēlojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Tu manus iztrūcinātājus visapkārt esi saaicinājis, kā uz svētku dienu, un Tā Kunga bardzības dienā neviens nav izglābies nedz atlicis; ko es auklēju un audzināju, mans ienaidnieks tos nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Es esmu tas vīrs, kas redzējis bēdas caur viņa dusmības rīksti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Viņš mani vedis un licis iet tumsībā un ne gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Tiešām, pret mani Viņš turējis Savu roku arvien atkal cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Manu miesu un manu ādu Viņš darījis vecu, manus kaulus Viņš satriecis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Viņš pret mani cēlis un ap mani stādījis žulti un rūgtumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Tumsā Viņš mani nolicis, tā kā tos, kas sen miruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Viņš mani aizmūrējis, ka es nevaru iziet, Viņš mani licis grūtos pinekļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Un jebšu es saucu un brēcu, tomēr Viņš aizslēdz Savas ausis priekš manas lūgšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Viņš manu ceļu aizmūrējis ar izcirstiem akmeņiem, Viņš manas tekas aizķīlājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Viņš ir glūnējis uz mani kā lācis, kā lauva slepenās vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Viņš man no ceļa licis noklīst, Viņš mani saplosījis, Viņš mani postījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Viņš savu stopu uzvilcis un mani bultai licis par mērķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Viņš savas bultas iešāvis manās īkstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Es visiem saviem ļaudīm esmu par apsmieklu, viņiem par dziesmiņu cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Viņš mani ēdinājis ar rūgtumiem, Viņš mani dzirdinājis ar vērmelēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Viņš manus zobus ar zvirgzdiem(grants akmeņiem) sagrūdis, Viņš mani aprausis ar pelniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Tu manai dvēselei esi atņēmis mieru, man labums jāaizmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Tad es sacīju: mana drošība un mana cerība uz To Kungu ir pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Piemini manas bēdas un manu grūtumu, tās vērmeles un to žulti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Pieminēdama to piemin mana dvēsele un zemojās iekš manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'To es likšu pie savas sirds, tāpēc es gribu cerēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Tā Kunga žēlastība to dara, ka mēs vēl neesam pagalam, jo Viņa apžēlošanās ir bez gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Tā ir ik rītu jauna, Tava uzticība ir ļoti liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Tas Kungs ir mana daļa, saka mana dvēsele, tādēļ es gribu cerēt uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Tas Kungs ir labs tiem, kas uz Viņu gaida, tai dvēselei, kas Viņu meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Tā ir laba lieta, klusā garā gaidīt uz Tā Kunga palīdzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Tas ir labi cilvēkam, ka viņš jūgu nes savā jaunībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Viņš sēž vientulis un cieš klusu, kad tam nasta uzlikta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Lai krīt uz savu muti pīšļos, - varbūt vēl cerība, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Lai padod savu vaigu tam, kas viņu sit, un saņem nievāšanas papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Jo Tas Kungs neatmet mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Bet Viņš gan apbēdina, un tad Viņš apžēlojās pēc Savas lielās žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Jo ne no Savas sirds Viņš moka un apbēdina cilvēka bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Kad apakš kājām min visus cietumniekus virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Kad loka vīra tiesu tā Visuaugstākā priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Kad pārgroza cilvēka tiesu, vai Tas Kungs to neredz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kas ko sacījis un tas noticis, ko Tas Kungs nav pavēlējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Vai no tā Visuaugstākā mutes nenāk labums un ļaunums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Ko tad cilvēks kurn visu savu mūžu? Ikviens lai kurn pret saviem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Izmeklēsim un pārbaudīsim savus ceļus un atgriezīsimies pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Pacelsim savu sirdi un savas rokas uz Dievu debesīs (sacīdami):');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Mēs esam grēkojuši un esam bijuši neklausīgi, tāpēc Tu neesi žēlojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Tu esi ģērbies dusmībā un mūs vajājis, nokāvis un neesi žēlojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Tu ar padebesi esi apsedzies, ka lūgšana nevarēja tikt cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tu mūs esi licis par mēsliem un īgnumu tautu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Visi mūsu ienaidnieki atpleš savu muti pret mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Bailes un bedre nāk pār mums, nelaime un posts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Manas acis plūst kā ūdens upes manas tautas meitas posta dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Manas acis plūst un nevar stāties, mitēšanās nav,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Tiekams Tas Kungs no debesīm skatīsies un ņems vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mana acs dara grūti manai dvēselei visu manas pilsētas meitu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Mani ienaidnieki vajāt mani vajājuši kā putnu bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Tie manu dzīvību nomaitājuši bedrē un akmeņus metuši uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Ūdeņi plūda pār manu galvu; tad es sacīju: nu esmu pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Es piesaucu, ak Kungs, Tavu vārdu no dziļās bedres,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Un Tu paklausīji manu balsi. Tu neapslēpi Savu ausi no manām vaimanām, no manas kliegšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Tu nāci tuvu klāt tai dienā, kad es Tevi piesaucu, un sacīji: “Nebīsties!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Tu, Kungs, iztiesā manas dvēseles tiesu, Tu izpestī manu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Tu, Kungs, redzi to netaisnību, kas man notiek, - tiesā tu manu tiesu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Tu redzi visu viņu atriebšanos, visas viņu domas pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Tu, Kungs, dzirdi viņu nievāšanu, visas viņu domas pret mani,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Manu pretinieku lūpas un viņu domas pret mani cauru dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Lūko jel: Vai tie sēž vai ceļas, es esmu viņu dziesmiņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Tu tiem atmaksāsi, Kungs, maksu pēc viņu roku darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Tu tiem dosi apstulbotu sirdi, - Tavi lāsti lai ir pār viņiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Tu tos vajāsi ar dusmību un tos izdeldēsi apakš Tā Kunga debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kā zeltam spožums zudis un šķīstam zeltam jaukums, svētās vietas akmeņi izkaisīti visos ielu stūros!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Ciānas dārgie bērni, kas bija līdzīgi šķīstam zeltam, kā tie nu top turēti par māla traukiem, par podnieka rokas darbu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Pat zvēri dod krūti un zīdina savus bērnus; bet manas tautas meita palikusi nežēlīga, tā kā strausi tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Zidama bērna mēle līp pie zoda no tvīkšanas, bērniņi prasa maizes, bet neviena nav, kas tiem to lauž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Kas gardumus ēda, nu pamirst pa ielām; kas purpurā uzaudzināti, tie nu apkampj mēslus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Un manas tautas meitas noziegums ir lielāks, nekā Sodomas grēki, kas piepeši tapa apgāzta, nevienam nepieliekot rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Viņas lielkungi bija spožāki nekā sniegs un baltāki nekā piens, viņu ģīmis bija sārtāks nekā krelles, tie bija skaisti kā safīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Bet nu viņu ģīmis tumšāks nekā melnums, ka tos nepazīst uz ielām; un viņu āda līp pie viņu kauliem, - tā ir izkaltusi kā malka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Zobena nokautie ir jo laimīgi nekā bada nokautie, jo šie pamirst kā nodurti, tādēļ ka nav zemes augļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Žēlīgu sievu rokas vārījušas savus bērnus, tie viņām bijuši par barību manas tautas meitas postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Tas Kungs izdarījis Savu bardzību, Viņš izgāzis Savas dusmības karstumu un Ciānā iededzinājis uguni, kas aprijis viņas pamatus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'To nebija ticējuši zemes ķēniņi, nedz kāds no pasaules iedzīvotājiem, ka pretinieki un ienaidnieki ieies pa Jeruzālemes vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Bet tas noticis viņas praviešu grēku dēļ, viņas priesteru noziegumu dēļ, tie viņas vidū izlējuši taisno asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Tie skraidīja šurp un turp kā akli pa ielām, sagānīti asinīm, tā ka nevarēja aizskart viņu drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Un tiem sauca: atkāpjaties, jūs nešķīstie, atkāpjaties, atkāpjaties, neaizskariet nekā! Kad tie nu skrēja, maldījās, tad starp pagāniem sacīja: tiem vairs ilgāki nebūs mist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Tā Kunga dusmība tos izkaisījusi, Viņš tos vairs neuzlūkos; tie priesterus nav cienījuši un vecus nav žēlojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Mūsu acis vēl īgst, skatīdamās pēc mūsu palīga, kas veltīgs, mēs gaidīt gaidām uz tautu, kas nevar izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Tie mūsu pēdas dzinuši, ka nevarējām staigāt pa savām ielām; mūsu gals ir tuvu, mūsu dienas ir pagalam, jo mūsu gals atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Mūsu dzinēji bijuši čaklāki nekā ērgļi apakš debess, tie mūs vajājuši pa kalniem, tuksnesī tie mums likuši valgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Tā Kunga svaidītais, uz ko mūsu dzīvība stāvēja, ir gūstīts viņu bedrē, par ko sacījām: apakš viņa ēnas dzīvosim starp pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Priecājies un līksmojies, Edoma meita, Uc zemes iedzīvotāja! Tomēr tas biķeris nāks pie tevis arīdzan, tu piedzersies un tapsi kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Tavs noziegums ir deldēts, Ciānas meita, Viņš tevi vairs neliks aizvest. Bet tavu noziegumu, Edoma meita, Viņš piemeklēs, tavus grēkus Viņš atklās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Piemini, Kungs, kas mums noticis, skaties un uzlūko mūsu kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Mūsu mantas tiesa svešiniekiem kļuvusi, mūsu nami ārzemniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Mēs esam bāriņi bez tēva, mūsu mātes ir kā atraitnes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Savu ūdeni mēs dzeram par naudu, savu malku pērkam par maksu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Mēs topam vajāti pār kaklu pār galvu, mēs esam noguruši, dusas mums nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Mēs esam devušies rokā ēģiptiešiem un Asiriešiem, lai dabūtu maizes paēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Mūsu tēvi apgrēkojušies, un to vairs nav, bet mēs nesam viņu noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Kalpi valda pār mums, un neviena nav, kas mūs izglābj no viņu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Mums sava maize jāatved ar nāves bailēm, tuksneša zobena priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Mūsu āda ir nomelnējusi kā ceplī no tāda briesmīga bada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Sievas Ciānā apsmietas, jaunavas Jūda pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Lielkungi caur viņu roku ir pakārti, un vecaju vaigs nav turēts godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Jaunekļus dzen pie malšanas, un puiši klūp malku nesdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Vecaji atstājās no vārtiem un jaunekļi no savām dziesmām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Mūsu sirds līksmība ir pagalam, mūsu diešana palikusi par vaimanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Mūsu galvas kronis nokritis, - ak vai mums, ka esam grēkojuši!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Tādēļ mūsu sirds gurdena, tādēļ mūsu acis palikušas tumšas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Ciānas kalna dēļ, kas izpostīts, ka lapsas pār to tekā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Tu, Kungs, paliec mūžīgi, Tavs godības krēsls līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Kādēļ Tu mūs mūžam gribi aizmirst, kāpēc Tu mūs tik ilgi gribi atstāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Kungs, atgriezi mūs pie Tevis, tad atgriezīsimies, atjauno mūsu dienas, tā kā vecos laikos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Jeb vai Tu mūs pavisam esi atmetis un tik ļoti par mums apskaities?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Un notikās trīsdesmitā gadā, ceturtā mēnesī, piektā mēneša dienā, kad es biju starp tiem aizvestiem pie Ķebaras upes, tad debesis atvērās, un es redzēju Dieva parādīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Piektā mēneša dienā (tas bija tas piektais gads pēc ķēniņa Jojaķima aizvešanas cietumā),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Tā Kunga vārds notika uz Ecehiēli, Buzus dēlu, priesteri Kaldeju zemē, pie Ķebaras upes, un Tā Kunga roka nāca pār viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Tad es skatījos, un redzi, vētra nāca no ziemeļa puses un liels padebesis, un uguņi laistījās un spožums tam bija visapkārt, un pašā vidū spulgoja kā gaišs zelts no uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Un no viņa vidus rādījās tā kā četri dzīvi radījumi, un tie izskatījās pēc cilvēku līdzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Un ikvienam no viņiem bija četri vaigi, un ikvienam bija četri spārni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Un viņu kājas bija taisnas un viņu pēdas bija kā teļa nagi un spīdēja kā gludena vara spožums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Un cilvēku rokas bija apakš viņu spārniem viņu četros sānos, un visiem četriem bija savi vaigi un savi spārni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Viņu spārni bija salikti viens pie otra. Kad tie gāja, tad tie negriezās, ikkatrs gāja taisni uz priekšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Un viņu vaigu izskats (priekšā) bija visiem četriem cilvēka vaigs un pa labo roku lauvas vaigs, un pa kreiso roku bija visiem četriem vērša vaigs un ērgļa vaigs visiem četriem (iekšpusē).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Un viņu vaigi un viņu spārni augšā šķīrās; ikvienam divi (spārni) sitās kopā un divi apklāja viņu miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Un tie gāja ikviens taisni uz priekšu; kurp gars dzinās, turp tie gāja un neapgriezās iedami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Un izskats šiem dzīviem bija kā degošu ogļu izskats, kā lāpu spīdums; šis uguns spulgoja to dzīvo starpā. Un tām ugunīm bija spožums, un no tā uguns izšāvās zibeņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Un tie dzīvie šāvās šurp un turp kā zibeņi zibēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Un es uzskatīju tos dzīvos, un redzi, zemē pie tiem dzīviem bija pa skritulim viņu četru vaigu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Skrituļa izskats un viņu darbs bija kā topāza izskats un visiem četriem bija vienāds izskats, un viņu izskats un viņu darbs bija tā kā būtu skritulis iekš skrituļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Iedami tie gāja uz savām četrām pusēm; tie neapgriezās, kad tie gāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Un viņu loki bija augsti un briesmīgi, un viņu loki bija pilni acu visapkārt pie visiem četriem skrituļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Un kad tie dzīvie gāja, tad tie skrituļi tiem gāja līdz, un kad tie dzīvie no zemes pacēlās, tad arī tie skrituļi pacēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kurp gars dzinās, turp tie gāja pēc gara dzīšanās, un tie skrituļi tiem pacēlās līdz; jo to dzīvo gars bija iekš tiem skrituļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Kad tie gāja, tad arī šie gāja, un kad tie stāvēja, tad arī šie stāvēja; un kad tie no zemes pacēlās, tad arī tie skrituļi tiem pacēlās līdz; jo to dzīvo gars bija iekš tiem skrituļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Un virs to dzīvo galvām bija tā kā debess izplatījums, bijājams, kristāla izskatā, augšā plētās pār viņu galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Un apakš šī izplatījuma viņu spārni bija pacelti vienam pret otru, ikvienam divi spārni, kas apsedza viņu miesas vienā pusē un otrā pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Un tiem ejot es dzirdēju viņu spārnu troksni, ik kā varenu ūdeņu krākšanu, kā tā Visuvarenā balsi, kā ļaužu bara troksni, kā kara spēka troksni. Un kad tie stāvēja, tad tie savus spārnus nolaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Un balss atskanēja no tā izplatījuma, kas virs viņu galvām; kad tie stāvēja, tad tie savus spārnus nolaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Un uz tā izplatījuma virs viņu galvām bija redzams kā godības krēsls, kā safīra akmeņu izskats, un uz tā godības krēsla bija tā kā cilvēks, kas uz tā sēdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Un es redzēju tā kā gaiša zelta spožumu, kā uguns liesmas visapkārt un iekšā, no viņa gurniem uz augšu un no viņa gurniem uz apakšu es redzēju kā uguni, un spožums viņam bija visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Tā kā varavīksne, kas padebešos stāv lietus laikā, tāds bija tas spožums visapkārt. Tā izskatījās Tā Kunga godības līdzība. Un kad es to redzēju, tad es kritu uz savu vaigu, un dzirdēju viena runātāja balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Un Viņš sacīja uz mani: Cilvēka bērns, stājies kājās, tad Es ar tevi runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Un kad Viņš uz mani runāja, tad nāca gars iekš manis un cēla mani kājās, un es dzirdēju To, kas uz mani runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Un Viņš sacīja uz mani: Cilvēka bērns, Es tevi sūtu pie Israēla bērniem, pie tiem stūrgalvīgiem ļaudīm, kas sacēlušies pret Mani; viņi un viņu tēvi no Manis atkāpušies līdz šai pašai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Un tie bērni ir stūrgalvji un cietām sirdīm: Es tevi sūtu pie tiem, un tev būs uz tiem sacīt: tā saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Un vai tie klausa, vai neklausa - jo tie ir pārgalvju suga - taču tiem būs zināt, ka pravietis ir viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Bet tu, cilvēka bērns, nebīsties no tiem un nebīsties no viņu vārdiem: jebšu dadži un ērkšķi ap tevi, un tu dzīvo pie skorpioniem, tomēr nebīsties no viņu vārdiem un neiztrūksties no viņu vaiga; jo tie ir atkāpēju suga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Un tev būs Manus vārdus uz tiem runāt, vai tie klausa, vai neklausa; jo tie ir stūrgalvji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Bet tu, cilvēka bērns, klausi, ko es tev saku: neesi neklausīgs, tā kā tā nepaklausīgā tauta. Atver savu muti un ēd, ko es tev dodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Tad es redzēju, un raugi, roka pret mani bija izstiepta, un redzi, iekš tās bija satīta grāmata.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Un viņš to attaisīja manā priekšā, un tā bija aprakstīta iekšpusē un ārpusē, un tur bija uzrakstītas raudu dziesmas, nopūtas un vaimanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Un Viņš sacīja uz mani: Cilvēka bērns, ēd, kas tavā priekšā, ēd šo satīto grāmatu, un ej un runā uz Israēla namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Tad es atdarīju savu muti, un Viņš man deva ēst to satīto grāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Un Viņš sacīja uz mani: Cilvēka bērns, dod savam vēderam ēst un pildi savas iekšas ar šo satīto grāmatu, ko Es tev dodu. Tad es ēdu, un tas bija manā mutē tik salds kā medus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Un Viņš sacīja uz mani: Cilvēka bērns, ej pie Israēla nama un runā uz tiem Manus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Jo tu netopi sūtīts pie ļaudīm, kam tumša valoda un grūta mēle, bet uz Israēla namu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Ne pie lielām tautām, kam tumšas valodas un grūtas mēles, kuru vārdus tu nevari saprast; bet pie tiem Es tevi esmu sūtījis, tie tevi var saprast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Bet Israēla nams negribēs tevi klausīt, tāpēc ka tie Mani negrib klausīt. Jo visam Israēla namam ir bieza piere un cieta sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Redzi, tavu vaigu Es daru cietu kā viņu vaigu, un tavu pieri biezu kā viņu pieri');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Tavu pieri Es esmu darījis kā dimantu, cietāku pār klinti. Nebīsties no tiem un neiztrūksties no viņu vaiga; jo tie ir atkāpēju suga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Un Viņš sacīja uz mani: Cilvēka bērns, ņem pie sirds visus Manus vārdus, ko Es uz tevi runāšu, un klausies tos ar savām ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Un ej pie tiem aizvestiem, pie savu ļaužu bērniem, un runā uz tiem un saki uz tiem: tā saka Tas Kungs Dievs; - vai tie nu klausa, vai neklausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Tad Tas Gars mani pacēla, un es dzirdēju aiz sevis liela trokšņa balsi, kad Tā Kunga godība pacēlās no savas vietas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Un (es dzirdēju) to dzīvo spārnus, kas viens pie otra sniedzās, un to skrituļu rībēšanu viņiem līdzās un liela trokšņa skaņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Tad Tas Gars mani pacēla un mani aizņēma, un es gāju rūgts sava gara karstumā, bet Tā Kunga roka bija pār mani stipra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Un es nonācu uz Telabību pie tiem aizvestiem, kas dzīvoja pie Ķebaras upes, un paliku tur, kur tie dzīvoja, un paliku tur viņu vidū septiņas dienas ļoti noskumis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Un pēc septiņām dienām Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Cilvēka bērns, Es tevi esmu licis par sargu Israēla namam, ka tev no Manas mutes būs klausīties to vārdu un viņiem no Manas puses piekodināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Kad Es saku uz bezdievīgo: tu mirdams mirsi, - un tu viņu nepamāci un nerunā, ka tu bezdievīgo atgriezi no viņa bezdievīgā ceļa un viņu paturi dzīvu, tad bezdievīgais nomirs savā noziegumā, bet viņa asinis Es prasīšu no tavas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Bet kad tu bezdievīgo pamāci un viņš neatgriežas no savas bezdievības un no sava bezdievīgā ceļa, tad viņš nomirs savā noziegumā, bet tu savu dvēseli esi izglābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Un kad taisnais nogriežas no savas taisnības un dara ļaunu, tad Es viņam likšu piedauzīties, un tas mirs; kad tu viņu neesi pamācījis, tad viņš nomirs savos grēkos, un viņa taisnība, ko viņš darījis, netaps pieminēta, bet viņa asinis Es prasīšu no tavas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Bet kad tu taisno pamāci, ka tam taisnam nebūs grēkot, un viņš negrēko, tad viņš tiešām dzīvos, tāpēc ka tas ir tapis pamācīts, un tu savu dvēseli esi izglābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Un Tā Kunga roka bija tur uz manis, un Viņš uz mani sacīja: celies, ej ārā ielejā, un tur Es ar tevi runāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Tad es cēlos un izgāju ielejā, un redzi, tur stāvēja Tā Kunga godība, tā kā tā godība, ko es biju redzējis pie Ķebaras upes. Un es nokritu uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Tad gars nāca iekš manis un mani cēla kājās, un Viņš runāja uz mani un sacīja uz mani: ej, ieslēdzies savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Un redzi, tu cilvēka bērns, tev apliks virves, un tevi ar tām saistīs, un tu no tām nevarēsi noiet viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Un Es tavai mēlei likšu pielipt pie zoda, un tu paliksi mēms un tiem nebūsi par pārmācītāju; jo tie ir atkāpēju suga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Bet kad Es ar tevi runāšu, tad Es atdarīšu tavu muti, un tev būs sacīt uz tiem: tā saka Tas Kungs Dievs! Kas klausa, lai klausa, un kas neklausa, lai neklausa; jo tie ir atkāpēju suga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Un tu cilvēka bērns, ņem sev ķieģeli un liec to savā priekšā un raksti uz to Jeruzālemes pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Un taisi aplēģerēšanu pret to un uztaisi bulverķus(ielenkšanas torņi) pret to un uzmet valni pret to un nostādi karaspēku pret to un liec tai āžus(mūru dragājamais) visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Un ņem sev dzelzs pannu un liec to par dzelzs mūri starp sevi un pilsētu, un griez savu vaigu pret to, un tā lai tā top apsēsta, un tu to apsēdi. Tā lai ir zīme Israēla namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Un tu gulies uz saviem kreisiem sāniem un liec uz tiem Israēla nama noziegumu; pēc to dienu skaita, cik uz tiem gulēsi, tev būs nest viņu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Jo Es tos gadus, cik viņi grēkojuši, tev skaitīšu par dienām, trīssimt deviņdesmit dienas; tik ilgi tev būs nest Israēla nama noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Un kad tu šās pabeigsi, tad gulies otru reizi uz saviem labiem sāniem un tev būs nest Jūda nama noziegumu četrdesmit dienas; Es tev dodu ik dienu par ik gadu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Un griez savu vaigu un savu atsegto elkoni pret apsēsto Jeruzālemi, un sludini pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Un redzi, Es tev aplikšu virves, ka nevarēsi grozīties no vieniem sāniem uz otriem, kamēr būsi pabeidzis savas aplēģerēšanas(aplenkuma) dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Un tu ņem sev kviešus un miežus un pupas un lēcas, putraimus un rudzus, un liec tos traukā, un taisi sev no tiem maizi, pēc to dienu skaita, cik tu gulēsi uz saviem sāniem, ka tev ir ko ēst trīssimt un deviņdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Tava barība, ko tu ēdīsi, lai sver divdesmit sēķeļus uz dienu; savos laikos tev to būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Arī ūdeni tev būs dzert ar mēru, inna sesto tiesu, savos laikos tev to būs dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Un tev būs ēst miežu karašas, un tās cept uz cilvēka sūdiem priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Un Tas Kungs sacīja: Israēla bērni tāpat ēdīs savu maizi nešķīstu starp tiem pagāniem, kurp Es tos aizdzīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Tad es sacīju: ak Kungs, Dievs! Redzi, mana dvēsele nekad nav sagānījusies, jo no savas jaunības es neesmu ēdis ne maitu, ne saplosītu, un neganta gaļa nav nākusi manā mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Un Viņš uz mani sacīja: redzi, Es tev atvēlu ņemt lopu sūdus cilvēku sūdu vietā, uz kuriem tev būs sataisīt savu maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Un Viņš uz mani sacīja: cilvēka bērns! Redzi, Es atņemšu maizes padomu Jeruzālemē, un tie maizi ēdīs pēc svara un ar sirdēstiem, un dzers ūdeni ar mēru un ar izbailēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Tādēļ ka tiem būs maizes un ūdens trūkums, un tie iztrūksies viens ar otru un ies bojā savos noziegumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Un tu, cilvēka bērns, ņem sev asu nazi, bārdas dzinēja nazi tev būs ņemt, un nodzen ar to savu galvu un savu bārdu; pēc ņem svarus un dali tos (matus).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Trešo tiesu sadedzini ar uguni pilsētas vidū, kad aplēģerēšanas dienas pagalam; trešo tiesu ņem un sacērt to ar zobenu viņai visapkārt, un trešo tiesu izkaisi vēja, un Es izvilkšu zobenu viņiem pakaļ');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Un ņem no tiem kādu mazumiņu un iesien to savas drēbes stūrī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Un ņem vēl no tiem un iemet ugunī un sadedzini tos ar uguni; no tiem izies uguns pār visu Israēla namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Tā saka Tas Kungs Dievs: šī ir Jeruzāleme, ko Es esmu iecēlis vidū starp pagāniem, un viņai visapkārt ir zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Bet viņa turējās pretī Manām tiesām, noziegdamās vairāk nekā pagāni, un Maniem likumiem nekā tās valstis, kas viņai visapkārt; jo tie ir atmetuši Manas tiesas un nav staigājuši Manos likumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Tādēļ Tas Kungs Dievs tā saka: Tāpēc ka jūs vairāk trakojāt nekā tie pagāni, kas apkārt ap jums, un Manos likumos nestaigājāt un nedarījāt Manas tiesas un nedarījāt arī pēc to pagānu tiesām, kas apkārt ap jums, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Tāpēc Tas Kungs Dievs tā saka: redzi, Es (celšos) pret tevi, tiešām, Es pats! Tavā starpā Es turēšu tiesu priekš pagānu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Un Es darīšu tavā starpā, kā Es vēl neesmu darījis un kā vairs nedarīšu, visu tavu negantību dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Tāpēc tēvi ēdīs savus bērnus tavā starpā, un bērni ēdis savus tēvus, un Es tavā starpā turēšu tiesu un visus tavus atlikušos izkaisīšu visos vējos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Tādēļ, tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs: Tāpēc ka tu esi sagānījusi Manu svēto vietu ar visādiem gānekļiem un ar visādu negantību, tad Es cirpšu, un Mana acs nežēlos, un Es netaupīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Trešā tiesa no tevis nomirs ar mēri un iznīks tavā starpā badā, un trešā tiesa kritīs caur zobenu visapkārt ap tevi, un trešo tiesu Es izkaisīšu visos vējos, un Es izvilkšu zobenu tiem pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Tā Mana dusmība pilnīgi notiks un Mana bardzība izgāzīsies uz viņiem, un Es pie tiem atriebšos, un tie sajutīs, ka Es esmu Tas Kungs, kas Savā karstumā runājis, kad Savu bardzību pret tiem pilnīgi būšu parādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Es tevi likšu par tuksnesi un par kaunu starp tiem pagāniem, kas visapkārt ap tevi, priekš visu to acīm, kas iet garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Un tu būsi par apsmieklu un kaunu, par mācību un biedēkli tiem pagāniem, kas visapkārt ap tevi, kad Es tevi sodīšu dusmībā un bardzībā un ar briesmīgām sodībām, - Es Tas Kungs to esmu runājis, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Kad Es izsūtīšu pret tiem niknas bada bultas, kas nomaitās, ko Es izsūtīšu jūs nomaitāt; un Es vairošu badu pār jums un jums atņemšu maizes padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Un Es pār jums sūtīšu badu un niknus zvērus, tie laupīs tavus bērnus; un mēris un asinis ies apkārt tavā starpā, un Es vedīšu zobenu pār tevi; Es Tas Kungs to esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Cilvēka bērns! Griez savu vaigu pret Israēla kalniem un sludini pret tiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Un saki: Israēla kalni, klausāties Tā Kunga Dieva vārdu! Tā saka Tas Kungs Dievs uz kalniem un pakalniem, uz upēm un ielejām: redzi! Es vedu pār jums zobenu un izdeldu jūsu elku altārus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Un jūsu altāri taps nopostīti un jūsu saules stabi nolauzti, un es gāzīšu jūsu nokautos jūsu elku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Un Es nodošu Israēla bērnu trūdus viņu elku priekšā un kaisīšu jūsu kaulus ap jūsu altāriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Visur, kur jūs mājojat, pilsētas būs postītas un elku kalni atstāti, jo jūsu altāri būs sagāzti un nopostīti un jūsu elki būs salauzti un izdeldēti, un jūsu saules stabi tiks nocirsti un jūsu darījumi iznīcināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Un jūsu vidū gulēs nokauti, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Bet Es (kādus) atlicināšu, ka jums paliek, kas zobenam izmūk starp pagāniem, kad jūs tapsiet izkaisīti pa zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Tad jūsu izglābtie mani pieminēs starp pagāniem, kur tie būs cietumā, kad Es būšu salauzis viņu mauku sirdis, kas no Manis atkāpušās, un viņu acis, kas mauko pakaļ viņu elkiem, un tiem riebsies tas ļaunums, ko tie darījuši visās savās negantībās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Un tiem būs samanīt, ka Es esmu Tas Kungs; Es nebūt neesmu velti runājis, ka viņiem darīšu šo ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Tā saka Tas Kungs Dievs: sasit savas rokas un sit ar kāju pie zemes un sauc: ak vai! Pār visām niknām Israēla nama negantībām, jo tie kritīs caur zobenu, caur badu un caur mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Kas tālu, tas kritīs caur mēri, un kas tuvu, tas kritīs caur zobenu, bet kas atliksies un izglābsies, nomirs badā. Tā Es pret tiem izdarīšu savu bardzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Tad jūs samanīsiet, ka Es esmu Tas Kungs, kad viņu nokautie gulēs viņu elku priekšā ap viņu altāriem pa visiem augstiem pakalniem, pa visiem kalnu galiem un apakš visiem zaļiem kokiem un apakš visiem kupliem ozoliem, tais vietās, kur tie saldu smaržu upurēja visiem saviem elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Un Es izstiepšu savu roku pār viņiem, un darīšu zemi par postažu un tuksnesi vairāk nekā Diblas tuksnesi, visur, kur viņi mājo; un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Un tu, cilvēka bērns, tā Tas Kungs Dievs saka par Israēla zemi: gals, gals nāk pār tiem četriem zemes stūriem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nu nāk gals pār tevi, jo Es sūtīšu savu dusmību pret tevi, un tevi sodīšu pēc taviem ceļiem un atmaksāšu tev par visām tavām negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Un Mana acs tevi nežēlos, un Es netaupīšu, bet Es tev darīšu pēc taviem ceļiem, un atmaksāšu tavas negantības, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Tā saka Tas Kungs Dievs: nelaime, redzi, nelaime vien nāk!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Gals nāk, gals nāk, tas ir uzmodies pret tevi, redzi, tas nāk!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Tavs liktenis nāk, zemes iedzīvotājs. Laiks nāk, diena ir tuvu, troksnis, ne gaviles uz kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nu Es drīz gribu izgāzt Savu bardzību pār tevi un izdarīt Savu dusmību pret tevi un tevi sodīt pēc taviem ceļiem un atmaksāt tev visas tavas negantības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Un Mana acs nežēlos, un Es netaupīšu; pēc taviem ceļiem Es tev došu un tavas negantības Es tev atmaksāšu, un jūs samanīsiet, ka Es esmu Tas Kungs, kas sit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Redzi, diena, redzi, tā nāk, liktenis nāk; rīkste zied, lepnība zaļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Varas darbs ir uzaudzis par rīksti bezdievībai, neviens no tiem neatliksies, neviens no viņu draudzes, neviens no viņu pulka, nekādas žēlabas par tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Laiks nāk, diena nāk. Lai pircējs nepriecājās, un pārdevējs lai nenoskumst; jo bardzība nāk pār visu viņas draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Jo pārdevējs neatdabūs, ko pārdevis, jebšu vēl dzīvos; jo tā parādīšana nebūs velti notikusi pār visu viņas draudzi, un neviens, kas noziegumā, neizglābs savu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Lai pūš ar trumetēm un visu dara gatavu, tomēr nebūs, kas ies karā; jo mana dusmība ir pār visu viņas draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Zobens ir ārā, un mēris un bads ir iekšā. Kas laukā, tas nomirs caur zobenu, un kas pilsētā, to aprīs bads un mēris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Un viņu bēgļi, kas izbēg, būs kalnos un visi vaidēs kā baloži ielejā, ikkatrs sava nozieguma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Visas rokas nogurs un visi ceļi sašļuks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Tie apvilks maisus, un bailība tos apklās, un pār visiem viņu vaigiem būs kauns un visas viņu galvas būs plikas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Tie izmetīs savu sudrabu uz ielām, un viņu zelts būs par sūdiem, viņu sudrabs un viņu zelts tos nevarēs izglābt Tā Kunga dusmības dienā. Ar to tie nepieēdinās savu dvēseli, nedz pildīs savu vēderu; jo tas tiem bija par apgrēcību, ka noziedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Ar savu skaisto glītumu tie dzinuši lepnību, un no tā taisījuši savus negantos tēlus, savus riebīgos elkus. Tāpēc Es to tiem esmu darījis par sūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Un Es to nodošu svešiem rokā par laupījumu, un bezdievīgiem virs zemes, ka tie to laupa un ka tie to sagāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Un Savu vaigu Es no tiem gribu nogriezt, ka tie Manu mantu sagāna, un postītāji pār to nāks un to sagānīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Taisi ķēdes, jo zeme ir pilna asins grēku, un pilsēta pilna varas darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Tāpēc Es atvedīšu no pagāniem tos niknākos, tie viņu namus iemantos, un to vareno lepnībai Es darīšu galu, viņu svētekļi tiks sagānīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Posts klāt; mieru meklēs, bet nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Bēdas nāks pār bēdām un vēsts pār vēsti; tad meklēs parādīšanas no praviešiem, bet bauslība iznīks priesteriem un padoms vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Ķēniņš bēdāsies, un lielkungi būs apģērbti ar izbailēm, un tās zemes ļaudīm rokas nogurs. Es tiem darīšu pēc viņu ceļiem un pēc viņu nopelna Es tos gribu sodīt, un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Un notikās sestā gadā, sestā mēnesī, piektā mēneša dienā: kad es sēdēju savā namā, un Jūda vecaji sēdēja manā priekšā, tad tur Tā Kunga Dieva roka krita uz mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Un es redzēju, un raugi, tur bija viens, kam ģīmis bija kā uguns; no viņa gurniem lejup tas bija kā uguns, un no viņa gurniem augšup tas bija kā debess gaišums un kā gaiša zelta spožums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Un Viņš izstiepa tā kā roku un mani sagrāba pie manas galvas matiem. Un Tas Gars mani pacēla starp zemi un debesi un mani aiznesa Dieva parādīšanā uz Jeruzālemi priekš iekšējā pagalma vārtu durvīm, kas stāv pret ziemeli, tur bija vieta tam riebīgam elka tēlam, kas bija par riebšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Un redzi, tur bija Israēla Dieva godība tāda pat, kādu es biju redzējis ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Un Viņš uz mani sacīja: cilvēka bērns, pacel jel savas acis pret ziemeli! Un es pacēlu savas acis pret ziemeli, un redzi, pret ziemeļa pusi pie altāra vārtiem bija šis riebīgais elks, kur iet iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Un Viņš sacīja uz mani: cilvēka bērns, vai tu redzi, ko tie dara, tās lielās negantības, ko Israēla nams šeit dara, ka Man jāatstāj Sava svētā vieta? Bet tu redzēsi vēl lielākas negantības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Tad Viņš mani veda pie pagalma durvīm; un es redzēju, un raugi, tur bija caurums sienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Un Viņš sacīja uz mani: cilvēka bērns, lauzies jel caur to sienu! Un es lauzos caur to sienu, un redzi, tur bija durvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Tad Viņš sacīja uz mani: ej iekšā un redzi tās niknās negantības, ko tie še dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Un es gāju iekšā un skatījos, un redzi, tur bija visādas bildes no līdējiem tārpiem un negantiem lopiem, visādi Israēla nama elkadievi, rakstīti pie sienas visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Un septiņdesmit vīri no Israēla nama vecajiem un Jazanija, Safana dēls, šo vidū, stāvēja viņu priekšā, un ikvienam bija rokā savs kvēpināmais trauks, un smaržīgu dūmu mākonis cēlās uz augšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Tad Viņš sacīja uz mani: vai tu redzi, cilvēka bērns, ko Israēla nama vecaji dara tumsībā, ikviens savā elku kambarī? Jo tie saka: Tas Kungs mūs neredz, Tas Kungs zemi atstājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Un Viņš sacīja uz mani: tu vēl redzēsi lielas negantības, ko tie dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Un Viņš mani veda pie Tā Kunga nama vārtu durvīm, kas pret ziemeli, un redzi, tur sēdēja sievas, tās apraudāja Tamusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Un Viņš uz mani sacīja: vai tu to redzi, cilvēka bērns? Tu redzēsi vēl lielākas negantības nekā šīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Un Viņš mani ieveda Tā Kunga nama iekšējā pagalmā, un redzi, pie Tā Kunga nama durvīm starp priekšnamu un altāri bija kādi divdesmit pieci vīri, ar muguru pret Tā Kunga namu un ar vaigu uz rītiem, un tie klanījās pret rīta pusi saules priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Tad Viņš uz mani sacīja: vai tu to redzi, cilvēka bērns? Vai Jūda namam tā maza lieta, darīt tādas negantības, ko tie še dara, ka zemi piepilda ar varas darbu, un arvienu atkal Mani kaitina; jo redzi, vīna stīgas tie tur pie sava deguna!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Tāpēc Es arīdzan darīšu pēc Savas bardzības, un Mana acs nežēlos, un Es nesaudzēšu. Jebšu tie ar stipru balsi kliedz priekš Manām ausīm, tomēr Es tos neklausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Un Viņš sauca priekš manām ausīm ar stipru balsi un sacīja: lai nāk tuvu tie pilsētas piemeklētāji, un ikviens ar saviem kaujamiem ieročiem rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Un redzi, seši vīri nāca no augšvārtu ceļa, kas pret ziemeli, ikviens savu kaujamo ieroci rokā. Bet viens vīrs bija viņu vidū, audeklī ģērbies, un rakstāmās lietas pie gurniem. Un tie nāca iekšā un nostājās vara altārim sānis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Un Israēla Dieva godība aizcēlās no tā ķeruba, virs kā tā bija, pie nama sliekšņa, un sauca tam vīram, kas ģērbies audeklī, kam tās rakstāmās lietas bija pie gurniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Un Tas Kungs uz viņu sacīja: ej pa pilsētu cauri, pa Jeruzālemi cauri, un apzīmē ar zīmi pie pierēm tos ļaudis, kas nopūšas un vaid par visām šīm negantībām, kas viņu starpā top darītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Bet uz tiem citiem Viņš sacīja priekš manām ausīm: ejat pa pilsētu viņam pakaļ un kaujiet jūsu acs lai nežēlo, un nesaudzējiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Nokaujiet sirmgalvjus, jaunekļus un jaunietes un bērnus un sievas, kamēr jūs tos izdeldējat. Bet neaizskariet nevienu no tiem, pie kā tā zīme ir. Un iesāciet no manas svētās vietas. Un tie iesāka pie tiem vecajiem, kas tā nama priekšā bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Un Viņš uz tiem sacīja: sagāniet to namu un piepildiet tos pagalmus ar nokautiem; izejiet! Un tie izgāja un sita to pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Un notikās, kad tie tos sita un es atliku, tad es kritu uz savu vaigu un brēcu un sacīju: ak Kungs, Dievs! Vai Tu visus atlikušos iekš Israēla gribi izdeldēt, izgāzdams Savu bardzību pār Jeruzālemi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Tad Viņš uz mani sacīja: Israēla un Jūda nama noziegums ir ļoti varen liels, un zeme ir ar asinīm piepildīta, un pilsēta ir netaisnības pilna; jo tie saka: Tas Kungs zemi atstājis, un Tas Kungs neredz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Tad ir Mana acs nežēlos, un Es nesaudzēšu, Es metīšu viņu grēkus uz viņu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Un redzi, tas vīrs, kas ģērbies audeklī, kam tās rakstāmās lietas bija pie gurniem, atnesa vēsti atpakaļ un sacīja: es esmu darījis, kā Tu man pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Un es redzēju, un raugi, uz tā izplatījuma pār to ķerubu galvām bija kā safīra akmens, tā kā goda krēsls redzams pār viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Un Viņš runāja uz to vīru, kas bija ģērbies audeklī, un sacīja: ej iekšā starp tiem skrituļiem apakš tiem ķerubiem, un pildi savas rokas ar degošām oglēm, kas starp tiem ķerubiem, un kaisi tās pār to pilsētu. Un viņš gāja iekšā priekš manām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Un tie ķerubi stāvēja tam namam pa labo roku, kad tas vīrs iegāja, un padebesis piepildīja iekšēju pagalmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Tad Tā Kunga godība pacēlās no tiem ķerubiem pie tā nama sliekšņa, un tas nams piepildījās ar padebesi, un tas pagalms bija pilns spožuma no Tā Kunga godības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Un to ķerubu spārnu troksni dzirdēja līdz ārējam pagalmam, kā tā visuvarenā Dieva balsi, kad Tas runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Un kad Viņš tam vīram, kas ģērbies audeklī, bija pavēlējis un sacījis: ņem uguni no tiem skrituļiem starp tiem ķerubiem, tad viņš gāja iekšā un piestājās pie viena skrituļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Tad ķerubs izstiepa savu roku starp tiem ķerubiem pēc tā uguns, kas bija starp tiem ķerubiem, un to ņēma un deva tam vīram rokā, kas bija ģērbies audeklī; tas to ņēma un izgāja ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Un tur parādījās pie tiem ķerubiem tā kā cilvēka roka apakš viņu spārniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Tad es redzēju, un raugi, četri skrituļi bija pie tiem ķerubiem, pie ikkatra ķeruba viens skritulis, un tie skrituļi izskatījās kā turkisa akmeņi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Un tie četri bija vienādi pēc izskata, tā kā būtu skritulis iekš skrituļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Ejot tie gāja uz savām četrām pusēm, tie ejot negriezās, bet kurp galva turējās, turp tie gāja pakaļ, tie ejot negriezās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Un visa viņu miesa un viņu mugura un viņu rokas un viņu spārni un tie skrituļi bija pilni acu visapkārt pie tiem četriem un viņu skrituļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Tie skrituļi tapa nosaukti viesulis priekš manām ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Un ikvienam bija četri vaigi, tas pirmais vaigs bija ķeruba vaigs, un tas otrais vaigs bija cilvēka vaigs, un tas trešais bija lauvas vaigs, un tas ceturtais bija ērgļa vaigs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Un tie ķerubi cēlās. Tie bija tie paši dzīvie, ko biju redzējis pie Ķebaras upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Un kad tie ķerubi gāja, tad tie skrituļi gāja viņiem sānis, un kad tie ķerubi savus spārnus pacēla, no zemes uz augšu skriet, tad ir tie skrituļi no viņu sāniem nešķīrās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Kad tie stāvēja, tad ir šie stāvēja, un kad tie cēlās, tad ir šie cēlās, jo tā dzīvā gars bija iekš tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Un Tā Kunga godība gāja nost no tā nama sliekšņa un stāvēja uz tiem ķerubiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Un tie ķerubi cilāja savus spārnus un pacēlās no zemes uz augšu priekš manām acīm iziedami, un tie skrituļi gāja viņiem sānis; un tie nostājās pie Tā Kunga nama vārtu durvīm pret rīta pusi, un Israēla Dieva godība bija virsū pār viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Šie bija tie dzīvie, ko es redzēju apakš Israēla Dieva pie Ķebaras upes, un es nomanīju, tos esam ķerubus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Ikvienam bija četri vaigi un ikvienam bija četri spārni un apakš viņu spārniem bija kā cilvēku rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Un viņu vaigi izskatījās kā tie, ko biju redzējis pie Ķebaras upes, šiem un viņiem bija vienāds izskats; un ikviens gāja taisni uz priekšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Un Gars mani pacēla un mani nesa pie Tā Kunga nama priekšējiem vārtiem, kas pret rītiem stāv; un redzi, pie vārtu durvīm bija divdesmit un pieci vīri, un viņu vidū es redzēju Jazaniju, Asura dēlu, un Platiju, Benajas dēlu, ļaužu virsniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Un Viņš uz mani sacīja: cilvēka bērns, šie ir tie vīri, kas netaisnību izdomā un dod ļaunu padomu šinī pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Tie saka: laiks vēl nav klāt, namus celt! Šī (pilsēta) ir tas pods un mēs tā gaļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Tāpēc sludini pret tiem, sludini, cilvēka bērns!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Tad Tā Kunga Gars krita uz mani un uz mani sacīja: runā: tā saka Tas Kungs: jūs, ak Israēla nams, sakāt tā, jo Es zinu, kādas domas jums nāk prātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Varen daudz ir to, ko esat nokāvuši šinī pilsētā, un viņas ielas jūs esat pildījuši ar nokautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Tādēļ Tas Kungs Dievs tā saka: jūsu nokautie, ko jūs viņas vidū esat nogāzuši, tie ir tā gaļa, un šī ir tas pods, bet jūs no viņas vidus izvedīs ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Jūs bīstaties no zobena, un zobenu Es vedīšu pār jums, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Es jūs no viņas vidus izvedīšu ārā un jūs nodošu svešiem rokā un nesīšu jums tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Jūs kritīsiet caur zobenu, Es jūs sodīšu pie Israēla robežām, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Šī (pilsēta) jums nebūs par podu, un jūs nebūsiet par gaļu viņas vidū; pie Israēla robežām Es jūs gribu sodīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Un jūs samanīsiet, ka Es esmu Tas Kungs, tāpēc ka neesat staigājuši Manos likumos nedz darījuši Manas tiesas, bet turējušies pēc pagānu tiesām, kas jums visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Un notikās, kad es sludināju, tad Platija, Benajas dēls, nomira. Tad es kritu uz savu vaigu un brēcu ar stipru balsi un sacīju: Ak Kungs Dievs, vai tu pavisam galu darīsi Israēla atlikušiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Tad Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Cilvēka bērns, tie ir tavi brāļi, tavi brāļi, tavi radi, un viss Israēla nams visnotaļ ir tie, uz ko Jeruzālemes iedzīvotāji saka: atkāpjaties tālu no Tā Kunga, šī zeme mums ir dota par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Tādēļ saki: tā saka Tas Kungs Dievs: jebšu Es tos tālu esmu aizvedis starp tautām un tos izkaisījis pa valstīm: taču Es par mazu brīdi tiem būšu par svētumu tanīs valstīs, kur tie nākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Tādēļ saki: tā saka Tas Kungs Dievs: tiešām, Es jūs sapulcināšu no tām tautām un jūs salasīšu no tām valstīm, kur esat izkaisīti, un Es jums došu Israēla zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Un tie nāks uz turieni un ņems visus viņas gānekļus un visas viņas negantības no tās nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Un Es tiem došu vienādu sirdi un Es jums došu jaunu garu, un atņemšu to akmens sirdi no viņu miesām un tiem došu miesīgu sirdi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Lai tie staigā Manos likumos un sarga Manas tiesas un tās dara, un tie Man būs par ļaudīm, un Es tiem būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Bet tiem, kam sirds pēc savu gānekļu un neganto elku prāta dzenās, tiem Es viņu grēkus metīšu uz viņu galvu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Tad tie ķerubi pacēla savus spārnus un tie skrituļi bija viņiem sānis, un Israēla Dieva godība bija virsū pār tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Un Tā Kunga godība cēlās no pilsētas vidus un nostājās uz tā kalna, kas pilsētai pret rītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Tad Gars mani pacēla un mani aizveda parādīšanā un caur Dieva Garu uz Kaldeju pie tiem aizvestiem, un tā parādīšana, ko es biju redzējis, no manis nozuda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Un es tiem aizvestiem runāju visus Tā Kunga vārdus, ko Viņš man bija parādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Cilvēka bērns, tu dzīvo atkāpēju sugā, kam acis ir redzēt, bet tie neredz, kam ausis ir dzirdēt, bet tie nedzird, jo tie ir atkāpēju suga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Bet tu, cilvēka bērns, taisi sev ceļa rīkus un izej pašā dienas laikā priekš viņu acīm un aizej no savas vietas uz citu vietu priekš viņu acīm, vai tie varbūt samanīs, ka tie ir atkāpēju suga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Tāpēc iznes savus rīkus, kā ceļa rīkus pašā dienas laikā priekš viņu acīm, un tad izej vakarā priekš viņu acīm, kā tie iziet, kas uz ceļu dodās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Lauzies caur sienu priekš viņu acīm un iznes tur (savus rīkus).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Priekš viņu acīm tev tos būs nest uz pleciem, tumsā tev tos būs iznest, savu vaigu tev būs apsegt, ka neredzi zemi. Jo Es tevi esmu licis par brīnuma zīmi Israēla namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Un es darīju, kā man bija pavēlēts; es iznesu savus rīkus dienas laikā, kā ceļa rīkus, un vakarā es caur sienu izlauzos ar roku; es tos iznesu tumsā, un tos nesu uz pleciem priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Un no rīta Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Cilvēka bērns! Vai Israēla nams, tā atkāpēju suga, uz tevi nav sacījis: ko tu dari!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Saki uz tiem: tā saka Tas Kungs Dievs: šī nasta ir Jeruzālemes valdnieks un viss Israēla nams, kas tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Saki: es esmu jūsu brīnuma zīme; kā es esmu darījis, tā viņiem darīs, tie aizies un taps vesti cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Un tas valdnieks, kas viņu vidū, nesīs uz pleciem tumsā un aizies; tie lauzīsies caur sienu, viņu tur izvest, viņa vaigs taps apsegts, tādēļ ka viņam ar acīm zemi nebūs redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Un Es izplētīšu savu tīklu pār viņu, ka viņš top gūstīts manos valgos, un Es viņu vedīšu uz Bābeli Kaldeju zemē, viņš to neredzēs, bet tur mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Un visus, kas ap viņu, viņa palīgus, un visus viņa pulkus Es izkaisīšu visos vējos un izvilkšu zobenu viņiem pakaļ');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Tā tie samanīs, ka Es esmu Tas Kungs, kad Es tos izklīdināšu pa tautām un tos izkaisīšu pa valstīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Tomēr kādu mazu pulciņu no tiem Es atlicināšu no zobena, no bada un no mēra, lai tie viņu negantības stāsta tautu vidū, kurp tie nāks, un lai samana, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Cilvēka bērns, tev savu maizi būs ēst ar drebēšanu un savu ūdeni dzert ar trīcēšanu un bēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Un tev būs sacīt uz tās zemes ļaudīm: tā saka Tas Kungs Dievs par Jeruzālemes iedzīvotājiem Israēla zemē: tie ēdīs savu maizi ar bēdām un dzers savu ūdeni ar sirdēstiem, tādēļ ka viņu zeme taps tukša no savas pilnības, visu savu iedzīvotāju varas darbu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Un tās pilsētas, kas iedzīvotāju pilnas, kļūs postītas, un tā zeme būs par tuksnesi, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Cilvēka bērns, kas tas jums par sakāmu vārdu Israēla zemē, ka jūs sakāt: laiks ilgi velkās, un visa parādīšana būs nieki!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Tādēļ saki uz tiem: tā saka Tas Kungs Dievs: Es šim sakāmam vārdam likšu zust, ka to par sakāmu vārdu vairs nelietos iekš Israēla. Bet runā uz tiem: tās dienas nākušas tuvu līdz ar ikvienu parādīšanas vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Jo vairs nebūs veltīgas parādīšanas un viltīgas sludināšanas iekš Israēla nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Jo Es, Tas Kungs, Es runāju; tas vārds, ko Es runāju, notiks un vairs nevilcināsies; jo jūsu dienās, atkāpēju suga, Es runāšu vienu vārdu, un tam likšu notikt, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Cilvēka bērns, redzi, Israēla nams saka: tā parādīšana, ko šis redz, velkas uz ilgu laiku, un šis sludina par laikiem, kas ir tālu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Tāpēc saki uz tiem: tā saka Tas Kungs Dievs, neviens no Maniem vārdiem vairs nevilcināsies; tas vārds, ko Es runāšu, notiks, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Cilvēka bērns, sludini pret Israēla praviešiem, kas nākošas lietas sludina, un saki uz tiem praviešiem, kas no savas pašu sirds sludina: klausiet Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Tā saka Tas Kungs Dievs: ak vai, tiem trakiem praviešiem, kas pēc sava pašu prāta staigā, un nekā neredz!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Tavi pravieši, ak Israēl, ir kā lapsas sagruvušos mūros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Jūs nestājaties plaisumos nedz taisiet sētu ap Israēla namu, un nestāviet karā Tā Kunga dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Viņu skatīšana ir viltus un viņu sludināšana meli, kad tie saka: Tas Kungs to ir sacījis, un tomēr Tas Kungs tos nav sūtījis, un cerē, ka viņu vārds piepildīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Vai jūsu skatīšana nebija viltus un jūsu sludināšana nebija meli? Jūs sakāt, Tas Kungs to ir runājis, un tomēr Es neesmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Tādēļ tā saka Tas Kungs Dievs: Tāpēc ka jūs runājiet melus un skatiet viltu, tādēļ, redzi, Es celšos pret jums, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Un Mana roka būs pret tiem praviešiem, kas viltu redz un melus sludina. Tiem nebūs būt Manu ļaužu draudzē un nebūs tapt rakstītiem Israēla nama rakstā un nebūs nākt Israēla zemē, un jūs samanīsiet, ka Es esmu Tas Kungs:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Tāpēc, tāpēc ka tie Manus ļaudis pieviļ un saka: miers, kur miera nav. Šis uztaisa sienu no māliem, un citi to apmet ar kaļķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Saki uz tiem, kas ar kaļķiem apmet: kritīs; stiprs lietus gāzīsies, un Es metīšu lielus krusas gabalus, un liels viesulis plosīsies, redzi, tad tā siena kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Vai uz jums nesacīs: kur nu ir tie kaļķi, ar ko jūs esat apmetuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Tāpēc tā saka Tas Kungs Dievs: tiešām, Es sūtīšu lielu viesuli savā bardzībā, un gāzīšu stipru lietu savā dusmībā, un lielus krusas gabalus savā karstumā, kas tai darīs galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Tā Es nolauzīšu to sienu, ko jūs esat apmetuši ar kaļķiem, un to gāzīšu pie zemes, un viņas pamats taps atsegts; tā viņa grūs un jūs viņas vidū iesiet bojā, un samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Tā Es izdarīšu savu bardzību pret to sienu un pret tiem, kas viņu apmet ar kaļķiem; un Es uz jums sacīšu: tur vairs nav nedz sienas, nedz to, kas viņu apmet (ar kaļķiem),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'To Israēla praviešu, kas Jeruzālemei sludina, un priekš viņas redz miera parādīšanas, un tomēr miera nav, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Un tu, cilvēka bērns, griez savu vaigu pret savu ļaužu meitām, kas no savas pašu sirds sludina, un sludini pret viņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Un saki: tā saka Tas Kungs Dievs: ak vai tām, kas šuj spilvenus apakš visu roku padusēm un taisa pagalvju spilvenus priekš jauniem un veciem, gūstīt dvēseles! Jūs gūstat manu ļaužu dvēseles; bet savas pašu dvēseles gribat paturēt dzīvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Un jūs Mani sagāniet pie Maniem ļaudīm par kādām saujām miežu un par kādiem maizes kumosiem, un nokaujat tās dvēseles, kam nebija mirt, un paturat dzīvas tās dvēseles, kam nebija dzīvot, caur saviem meliem pie Maniem ļaudīm, kas melus klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Tādēļ tā saka Tas Kungs Dievs: redzi, Es celšos pret jūsu spilveniem(burvju apsēji), ar ko jūs dvēseles gūstat, ka tās tiek vaļā, un tos raušu no jūsu rokām un atsvabināšu tās dvēseles, tās dvēseles, ko jūs gūstat, ka tās tiek vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Es arī saplēsīšu jūsu pagalvju spilvenus, un atpestīšu Savus ļaudis no jūsu rokas, tā ka tie jūsu rokā vairs nebūs par medījumu, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Tādēļ ka jūs apbēdinājāt tā taisnā sirdi ar viltu, ko Es neesmu apbēdinājis, un stiprinājāt tā bezdievīgā rokas, lai tas neatgriežas no sava ļaunā ceļa, ka dzīvotu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Tādēļ jums vairs nebūs viltu skatīt nedz melus sludināt, bet Es izglābšu Savus ļaudis no jūsu rokas, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Un pie manis atnāca kādi Israēla vecaji un apsēdās manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Tad Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Cilvēka bērns, šie vīri savus elkadievus uzņēmuši savā sirdī un to, kas viņus apgrēcina, cēluši priekš savām acīm; vai tad tādiem bija Mani jautāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Tādēļ runā ar tiem un saki uz tiem: tā saka Tas Kungs Dievs: ikviens no Israēla nama, kas savā sirdī uzņem elkudievus un ceļ priekš savām acīm, kas viņus apgrēcina, un nāk pie pravieša, - tad Es Tas Kungs viņam atbildēšu pēc viņu elkadievu pulka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Lai Es Israēla namam sirdi aizgrābju, jo tie visi no Manis ir atkāpušies caur saviem elkadieviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Tāpēc saki uz Israēla namu: tā saka Tas Kungs Dievs: atgriežaties un nogriežaties no saviem elkadieviem un nogriežat savu vaigu no visām savām negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Jo ikviens no Israēla nama un no tiem svešiniekiem, kas Israēla starpā dzīvo, kas no Manis atkāpjas un uzņem savus elkadievus savā sirdī un ceļ priekš savām acīm, kas viņus apgrēcina, un nāk pie pravieša caur viņu Mani vaicāt, - Es esmu Tas Kungs, - tam no Manis kļūs atbilde,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Un Es celšu Savu vaigu pret šo vīru un to likšu par zīmi un sakāmu vārdu un to izdeldēšu no viņa ļaužu vidus, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Kad nu kāds pravietis pievilsies un kaut ko runās, šim pravietim Es, Tas Kungs, atkal likšu pievilties, un izstiepšu Savu roku pret viņu un to izdeldēšu no Savu Israēla ļaužu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Tā tie nesīs savu noziegumu; kā tā vaicātāja noziegums būs, tāpat būs tā pravieša noziegums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Lai Israēla nams no Manis vairs nenomaldās un vairs neapgānās ar visiem saviem pārkāpumiem; tad tie Man būs par ļaudīm, un Es tiem būšu par Dievu, saka Tas Kungs, Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Atkal Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Cilvēka bērns, kad kāda zeme pret Mani apgrēkojās un no Manis atkāpjas, tad Es izstiepšu Savu roku pret viņu un viņai atņemšu maizes padomu un tai sūtīšu badu un izdeldēšu no tās cilvēkus un lopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Jebšu šie trīs vīri, Noa, Daniēls un Ījabs būtu viņas vidū, tad tie caur savu taisnību tikai izglābtu savas dvēseles, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Un ja Es sūtītu niknus zvērus tai zemē, ka tā paliktu bez ļaudīm un par tuksnesi un to zvēru dēļ neviens tur nestaigātu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Un šie trīs vīri būtu viņas vidū, - tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, tie neizglābtu nedz dēlus nedz meitas; tie paši vien izglābtos, bet tā zeme paliktu par tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Jeb kad Es zobenu sūtītu pār šo zemi un sacītu: zoben, ej pa to zemi! Un Es no tās izdeldētu cilvēkus un lopus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Jebšu tie trīs vīri būtu viņas vidū, tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, tie neizglābtu nedz dēlus nedz meitas, bet paši vien izglābtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Jeb kad Es mēri sūtītu šai zemē, un pār to izgāztu savu bardzību ar asinīm, un izdeldētu no tās cilvēkus un lopus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Jebšu Noa, Daniēls un Ījabs būtu viņas vidū, tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, tie neizglābtu nedz dēlus nedz meitas, bet caur savu taisnību tie izglābtu tikai savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Bet tā saka Tas Kungs Dievs: jebšu Es pret Jeruzālemi sūtīšu Savas četras sodības, zobenu un badu un niknus zvērus un mēri, un izdeldēšu cilvēkus un lopus no turienes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Tomēr redzi, tur atliks kādi izglābti, kas taps izvesti, dēli un meitas; redzi, tie nāks pie jums, un jūs redzēsiet, kā tiem klājās un ko tie dara, un tapsiet iepriecināti pār to ļaunumu, ko Es esmu vedis pār Jeruzālemi ar visu to citu, ko Es pār to esmu vedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Tie jūs iepriecinās, kad jūs redzēsiet, kā tiem klājās un ko tie dara, un jūs redzēsiet, ka Es neesmu darījis bez iemesla, ko Es tur esmu darījis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Cilvēka bērns! Vai vīna koks pārāks par citu koku, vīna stīga, kas ir starp meža kokiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Vai no tā ņem lietas koku, ko taisīt? Vai no tā ņem vadzi, pie tā pakārt kādu rīku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Redzi, ugunij to nodod par barību; uguns ēd viņa abus galus un apsvilina viņa vidu; vai tas vēl der kādai lietai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Redzi, kad tas vēl bija vesels, tad tas nederēja nekādai lietai, ne nu vēl, kad uguns to ēdis un apsvilinājis, vai no tā vēl ko var taisīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Tāpēc tā saka Tas Kungs Dievs: tā kā vīna koku starp meža kokiem Es nododu ugunij, lai to aprij, tā Es nodošu Jeruzālemes iedzīvotājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Un Es pret tiem griezīšu Savu vaigu; no uguns tie iznākuši un uguns tos aprīs, lai jūs atzīstat, ka Es esmu Tas Kungs, kad Es pret tiem griežu Savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Un Es darīšu to zemi par posta vietu, tāpēc ka tie visi no Manis atkāpušies, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Atkal Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Cilvēka bērns, dari Jeruzālemei zināmas viņas negantības un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Tā saka Tas Kungs Dievs uz Jeruzālemi: tavs rads un tava dzimtene ir no Kanaāna zemes, tavs tēvs bija Amorietis, un tava māte Etiete.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Un tava piedzimšana (bija tāda): tai dienā, kad tu dzimi, tava naba netapa apgraizīta, un ar ūdeni tu netapi mazgāta, ka kļūtu šķīsta, nedz ar sāli berzta, nedz autos ietīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Neviena acs par tevi neapžēlojās, ka kaut kā žēlodama tevi būtu kopusi, bet tevi nometa laukā; tik nicināta bija tava dvēsele tai dienā, kad tu dzimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Kad Es tev garām gāju, tad Es tevi redzēju tavās asinīs saminamu, un sacīju uz tevi tavās asinīs: dzīvo! Tiešām, Es sacīju uz tevi tavās asinīs: dzīvo!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Es tevi ļoti esmu vairojis, kā augļus tīrumā, un tu esi iezēlusi un uzaugusi un ienākusies lielā skaistumā. Tavas krūtis ir piebriedušas un tavi mati paauguši; bet tu biji kaila un plika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Un kad Es tev garām gāju un tevi redzēju, raugi, tad bija tas laiks tevi iemīlēt. Tad Es Savus spārnus izpletu pār tevi un apsedzu tavu kailumu un tev zvērēju un nācu ar tevi derībā, saka Tas Kungs Dievs, un tu Man piederēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Un Es tevi mazgāju ar ūdeni un noskaloju tavas asinis no tevis un svaidīju tevi ar eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Es tevi arī apģērbu ar izrakstītām drēbēm un tev apvilku pasarkanas kurpes, un tev apjozu šķīstu audekli un tevi apsedzu ar zīdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Un Es tevi skaisti izpušķoju un liku gredzenus ap tavām rokām un ķēdi ap tavu kaklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Es liku arī pieres sprādzi pie tava vaiga un ausu sprādzi pie tavām ausīm un goda kroni uz tavu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Tā tu biji izgreznota ar zeltu un sudrabu, un tavas drēbes bija dārgs audeklis un zīds un izrakstīts darbs. Tu ēdi kviešus un medu un eļļu, un tu biji ļoti skaista, un tev izdevās labi, un tu tiki ķēniņa godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Un slava no tevis izgāja pa pagānu tautām par tavu skaistumu, jo tas bija pilnīgs caur Manu glītumu, ko Es tev biju pielicis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Bet tu biji droša ar savu skaistumu un paļaudamās uz savu slavu tu paliki par mauku un padevies maucībā ikkatram, kas gāja garām, un viņam piederēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Un tu ņēmi no savām drēbēm un taisīji sev raibus elku altārus un maukoji tur, kā vēl nav ne bijis, nedz būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Tu arī ņēmi Mana zelta un Mana sudraba jaukos glītumus, ko Es tev biju devis, un taisīji sev vīru tēlus un maukoji ar tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Un tu ņēmi savas izrakstītās drēbes un tās tiem uzsedzi, un liki Manu eļļu un Manas kvēpināmās zāles tiem priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Un Manu maizi, ko Es tev devu, miltus un eļļu un medu, ar ko Es tevi ēdināju, to arīdzan tu viņiem cēli priekšā par saldu smaržu. Tā tas noticis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Tu arī ņēmi savus dēlus un savas meitas, ko tu man biji dzemdējusi, un tos tiem upurēji par barību. Tā kā vēl par maz būtu, maucību vien dzīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Tu arī Manus bērnus kāvi un tos nodevi, un tiem liki priekš viņiem caur uguni iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Un visā savā negantībā un savā maucībā tu nepieminēji savas jaunības dienas, kad tu biji plika un kaila un saminama savās asinīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Un notika pēc visas tavas bezdievības, - (Vai! Vai tev! saka Tas Kungs Dievs.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Tu sev taisīji kalnu altārus un elku altārus ikkatrā ielā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Un pie visām ceļu jūtīm(sākumiem) tu uztaisīji savus elku altārus, un sagānīji savu skaistumu; tu izpleti savas kājas pret visiem, kas gāja garām, un dzini lielu maucību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Tu maukojies ar Ēģiptes bērniem, saviem kaimiņiem, kas lieli miesā un tu vairoji savu maukošanu, Mani kaitināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Redzi! Tad Es Savu roku izstiepu pret tevi un atrāvu Savu nospriesto tiesu un tevi nodevu tavām ienaidniecēm, Fīlistu meitu prātam, kas tava negodīga ceļa dēļ kaunējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Un tad tu maukojies ar Asura bērniem, jo tu nevarēji gan dabūt; tiešām, tu ir ar tiem maukodamās nevarēji gan dabūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Bet tu savu maukošanu vairoji līdz veikalnieku zemei, līdz Kaldejai, arī ar to tev nebija gan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Tik kārīga ir tava sirds, saka Tas Kungs Dievs, ka tu tādas lietas dari, proti lielas maukas darbu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Ka tu savus kalna altārus taisīji pie visām ceļu jūtīm un savus elku altārus taisīji ikkatrā ielā, un nebija kā cita mauka, smādēdama maukas algu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Tā kā laulības pārkāpēja sieva, kas sava vīra vietā pielaiž svešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Visām citām maukām top dota alga, bet tu savu algu dod visiem saviem drauģeļiem un tos apdāvini, lai tie visapkārt pie tevis nāk, ar tevi maukoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Tā notiek pie tevis citādi, nekā pie citām sievām tavā maucībā, tādēļ ka neviens tev nedzenās pakaļ maukoties; tu piedāvā naudu, bet tev naudas nedod; citāda tu esi tapusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Tādēļ, tu mauka, klausi Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Tā saka Tas Kungs Dievs: Tāpēc ka tavs kauns izgāzts un tavs kailums atklāts tavā maucībā ar taviem drauģeļiem un ar visiem taviem negantiem elkiem, ka tu esi izlējusi savu bērnu asinis, ko tiem esi devusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Tādēļ redzi, Es sapulcināšu tavus drauģeļus, ar ko tu esi jaukusies, un visus, ko tu esi mīlinājusi, līdz ar visiem, ko tu esi ienīdējusi, un Es tos sapulcināšu visapkārt pret tevi, un atsegšu priekš viņiem tavu kaunu, ka tiem būs redzēt visu tavu plikumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Es tevi sodīšu pēc laulības pārkāpēju un asins izlējēju tiesas, un izliešu tavas asinis bargās dusmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Un Es tevi nodošu viņu rokā, un tie nolauzīs tavus kalna altārus un apgāzīs tavus elku altārus un tev novilks tavas drēbes un tev atņems tavus dārgos greznumus un tevi atstās pliku un kailu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Un tie sasauks pret tevi ļaužu pulku un tevi nomētās ar akmeņiem un tevi sakaus ar saviem zobeniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Un tavus namus tie sadedzinās ar uguni un tev nesīs tiesu priekš daudz sievu acīm. Es tavai maucībai darīšu galu, ka tu vairs nepiedāvāsi maukas algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Un Es izdarīšu Savu bardzību pret tevi, ka Mana karstā dusmība atstājās no tevis un Es tieku pie miera un vairs nedusmojos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Tāpēc ka tu neesi pieminējusi savas jaunības dienas un Mani ar visu to kaitinājusi, redzi, tad ir Es metu tavus grēkus uz tavu galvu, saka Tas Kungs Dievs; lai tu vairs nepadodies bezkaunībai pie visām tavām negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Redzi, ikviens, kas runā līdzībās, par tevi sacīs: kāda māte, tāda meita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Tu esi savas mātes meita, kas apnikusi savu vīru un savus bērnus, un tu esi savu māsu māsa, kas apnikušas savus vīrus un savus bērnus. Jūsu māte ir Etiete un jūsu tēvs Amorietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Tava vecākā māsa ir Samarija ar savām meitām, kas tev dzīvo pa kreiso roku, un tava jaunākā māsa, kas dzīvo pa tavu labo roku, tā ir Sodoma ar savām meitām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Bet tu neesi staigājusi viņu ceļos un neesi darījusi pēc viņu negantības tik mazu brīdi; tu esi palikusi niknāka pār viņām visos savos ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, Sodoma, tava māsa, līdz ar savām meitām tā nav darījusi, kā tu esi darījusi ar savām meitām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Redzi, šis bija tavas māsas Sodomas noziegums: lepnība un maizes pilnība un dzīve bez bēdām bija viņai un viņas meitām; bet nabagam un bēdīgam tā nesniedza roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Bet tie bija lepni un darīja negantības manā priekšā; to redzēdams Es tos esmu atmetis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Arī Samarija ne uz pusi tik daudz nav grēkojusi kā tu, un tu esi darījusi vairāk negantības nekā viņa, tā ka tu savu māsu esi taisnojusi ar visām savām negantībām, ko tu darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Tad tu nesi arī savu kaunu, kad esi aizstāvējusi savas māsas ar saviem grēkiem, jo tu negantākus esi darījusi, nekā tās; viņas ir taisnākas nekā tu. Tāpēc kaunies tu arī un nesi savu kaunu, tādēļ ka tu esi taisnojusi savas māsas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Bet Es novērsīšu viņu cietumu, Sodomas un viņas meitu cietumu, un Samarijas un viņas meitu cietumu, un tavu cietumnieku cietumu viņu starpā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Lai tu nesi savu kaunu un kaunies par visu, ko esi darījusi, viņiem par iepriecināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Kad tavas māsas, Sodoma un viņas meitas, atgriezīsies pie savas vecās būšanas, un Samarija ar savām meitām atgriezīsies pie savas vecās būšanas, tad ir tu ar savām meitām atgriezīsies pie savas vecās būšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Un tava māsa Sodoma nebija par valodu tavā mutē tavas lepnības laikā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Pirms tava bezdievība tapa atklāta, kā tanī laikā, kad tevi pulgoja Sīrijas meitas un visas apkārtējās Fīlistu meitas tevi nievāja no visām pusēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Tava bezkaunība un tavas negantības tev jānes, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Jo tā saka Tas Kungs Dievs: Es tev darīšu tāpat, kā tu esi darījusi, kas esi nicinājusi zvērestu un lauzusi derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Bet Es pieminēšu Eavu derību, ko ar tevi esmu derējis tavas jaunības dienās, un Es celšu ar tevi mūžīgu derību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Tad tu pieminēsi savus ceļus, un kaunēsies, kad uzņemsi savas lielās un mazās māsas, jo Es tev tās došu par meitām, lai tās gan nav no tavas derības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Jo Es apstiprināšu Savu derību ar tevi, un tu samanīsi, ka Es esmu Tas Kungs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Lai tu to piemini un kaunies, un savu muti vairs neatdari sava kauna dēļ, kad Es tev visu piedošu, ko tu esi darījusi, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Cilvēka bērns, liec Israēla namam mīklu priekšā un stāsti līdzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Un saki: tā saka Tas Kungs Dievs: liels ērglis ar lieliem spārniem, ar stipriem locekļiem un kuplām raibām spalvām nāca uz Lībanu un paņēma ciedra koka galotni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Viņš nolauza pašu virsgalu un to aiznesa uz vienu tirgoņu zemi un to iestādīja vienā tirgotāju pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Viņš paņēma arīdzan no tās zemes sēklas un lika to sējamā tīrumā, viņš to paņēma un stādīja kā vītolu pie liela ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Un tā izplauka un palika par kuplu vīna koku ar zemu augumu, jo viņa stīgas locījās uz viņu, un viņa sakne bija apakš viņa; tā viņš tapa par vīna koku, kas izlaida stīgas un dabūja zarus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Un vēl viens ērglis bija ar lieliem spārniem un kuplām spalvām, un redzi, tas vīna koks locīja savas saknes uz viņu un izstiepa savus zarus pret viņu, ka viņš šo slacinātu no sava stādījuma dobēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Gan tas bija dēstīts labā zemē pie liela ūdens, ka tam bija stīgas izlaist un augļus nest un palikt par it labu vīna koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Saki tad: tā saka Tas Kungs Dievs: vai tam labi izdosies? Vai viņa saknes netaps izrautas un viņa augļi nogriezti, ka sakalst un visas viņa zaļās lapas savīst? Un tas nenotiks caur lielu elkoni nedz caur lielu ļaužu pulku, ka to izcels no viņa saknēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Redzi jel! Viņš gan ir dēstīts, bet vai tam labi izdosies? Vai tas, kad rīta vējš to aizskars, kaltin nenokaltīs? Uz tām dobēm, kur tas dēstīts, tas nokaltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Saki jel uz to atkāpēju sugu: vai jūs nezināt, kas tas ir? Saki: redzi, Bābeles ķēniņš ir nācis uz Jeruzālemi un paņēmis viņas ķēniņu līdz ar viņas lielkungiem un tos aizvedis pie sevis uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Un viņš no ķēniņa dzimuma vienu ir ņēmis un ar to cēlis derību un tam licis zvērēt un atņēmis zemes varenos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Lai tā valsts būtu zema un nepaaugstinātos, un lai tā derību turēdama pastāvētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Bet tas no viņa atkāpās un sūtīja savus vēstnešus uz Ēģipti, lai tam sūtītu zirgus un ļaužu pulku. Vai tam izdosies? Vai tas izglābsies, kas to dara? Vai derības lauzējs izglābsies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, tā ķēniņa zemē, kas viņu darījis par ķēniņu, kam zvērestu viņš nicinājis un kam derību viņš lauzis, pie tā viņš nomirs Bābelē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Un Faraons karā viņam klāt nestāvēs ar lielu karaspēku un ar lielu pulku, kad uzmetīs valni un uztaisīs bulverķus, izdeldēt daudz dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Jo viņš nicinājis zvērestu un lauzis derību; redzi, jebšu viņš savu roku bija devis, tomēr viņš visu to ir darījis, tāpēc viņš neizglābsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Tādēļ tā saka Tas Kungs Dievs: tik tiešām kā Es dzīvoju, Es Savu zvērestu, ko viņš nicinājis, un Savu derību, ko viņš lauzis, gribu mest uz viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Un Es Savu tīklu izpletīšu pār viņu, ka viņš Manos valgos taps gūstīts, un Es viņu likšu novest uz Bābeli un tur ar viņu tiesāšos par viņa atkāpšanos, ka viņš no Manis atkāpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Un visi viņa bēgļi ar visiem viņa piederīgiem kritīs caur zobenu, un tie atlikušie taps izkaisīti visos vējos, un jūs samanīsiet, ka Es, Tas Kungs, to esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Tā saka Tas Kungs Dievs: Es ņemšu no tā augstā ciedra koka galotnes, un to stādīšu, no paša viņa virsgala es ņemšu zariņu, un to dēstīšu ļoti augstā kalnā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Israēla augstā kalnā Es to stādīšu, un viņš izlaidīs zarus un nesīs augļus un taps par krāšņu ciedra koku, tā ka apakš viņa dzīvos visādi putni no visādām spalvām; viņa zaru pavēnī tie dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Un visi koki laukā samanīs, ka Es, Tas Kungs, to augsto koku esmu pazemojis un to zemo koku paaugstinājis, to zaļo koku kaltējis un to sakaltušo koku darījis zaļojam. Es, Tas Kungs, to esmu runājis un to darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Kāpēc jūs lietojiet šo sakāmo vārdu Israēla zemē un sakāt: tēvi ēduši skābas vīnogas un bērniem atmizējuši zobi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, pie jums vairs nenotiks ka šo sakāmo vārdu lietos iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Redzi, visas dvēseles Man pieder; kā tēva dvēsele, tā arī dēla dvēsele, Man tās pieder. Kura dvēsele apgrēkojās, tā mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Kad nu kas ir taisns un dara, kas tiesa un taisnība,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Kas neēd uz (elku)kalniem un nepaceļ savas acis uz Israēla nama elkiem, kas sava tuvāka sievu neapgāna un neguļ pie sārņainas sievas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Un kas nevienu nenospaida un parādniekam dod atpakaļ viņa ķīlu, kas nelaupa, bet izsalkušam dod maizes un apģērbj pliko ar drēbēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Kas augļus nedzen nedz pagaidus plēš, savu roku izsargā no netaisnības un taisnu tiesu nes starp vienu un otru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Kas staigā Manos likumos un sargā Manas tiesas, turēdams ticību, - tas ir taisns, tas dzīvos, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Bet ja tas dzemdinājis dēlu, kas ir laupītājs, kas asinis izlej, kas savam brālim dara vienu no šīm lietām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Un kas nedara visas šīs lietas, bet ēd uz (elku)kalniem un apgāna sava tuvāka sievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Kas nospaida nabagu un bēdīgo, laupa laupījumu, neatdod ķīlu un paceļ savas acis uz elkiem, dara negantību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Izdod uz augļiem un plēš pagaidus, - vai tam būs dzīvot? Tam nebūs dzīvot; tāpēc ka tas ir darījis visas tādas negantības, mirtin tam būs mirt, - viņa asinis lai paliek uz viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Bet redzi, ja tas dzemdinājis dēlu, kas redz visus tēva grēkus, ko tas dara, un bīstas un nedara tāpat,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Neēd uz (elku)kalniem un nepaceļ savas acis uz Israēla nama elkiem, neapgāna sava tuvākā sievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Un nevienu nenospaida, ķīlu nepatur un laupījumu nelaupa, savu maizi dod izsalkušiem un pliko apģērbj ar drēbēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Savu roku izsargā no netaisnības, neplēš augļus un pagaidus, dara Manas tiesas un staigā Manos likumos, tam nebūs mirt par sava tēva netaisnību, bet tiešām tam būs dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Bet viņa tēvs, tāpēc ka darījis varas darbu, laupījis brāļa mantu, un darījis savu ļaužu starpā, kas nebija labi, redzi, tam būs mirt par savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Bet jūs sakāt: Kāpēc dēlam nebūs nest sava tēva noziegumu? Tiešām, dēls, kas darījis tiesu un taisnību, turējis visus Manus likumus un tos darījis, tam tiešām būs dzīvot! Tai dvēselei, kas grēko, tai būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Dēlam nebūs nest tēva noziegumu, nedz tēvam nest dēla noziegumu, uz taisna paliks viņa taisnība, un uz bezdievīga paliks viņa bezdievība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Bet kad bezdievīgais atgriežas no visiem saviem grēkiem, ko tas darījis, un tur visus Manus likumus un dara, kas tiesa un taisnība, tad tas tiešām dzīvos un nemirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Visi viņa grēki, ko viņš darījis, viņam netaps pieminēti; savas taisnības dēļ, ko viņš dara, viņš dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Vai Man bezdievīgā nāve varētu patikt? saka Tas Kungs Dievs, vai Man nepatīk, ka viņš atgriežas no sava ceļa un dzīvo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Bet kad taisnais nogriežas no savas taisnības un dara netaisnību un dara visu negantību, ko bezdievīgais dara, vai tam būs dzīvot? Visa viņa taisnība, ko viņš darījis, netaps pieminēta tās pārkāpšanas dēļ, ar ko viņš pārkāpis, un to grēku dēļ, ar ko viņš apgrēkojies, viņš mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Bet jūs sakāt: Tā Kunga ceļš nav taisns. Klausiet tad, jūs no Israēla nama! Vai Mans ceļš nav taisns? Vai jo vairāk jūsu ceļi nav netaisni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Kad taisnais nogriežas no savas taisnības un dara netaisnību un mirst tās dēļ, tad viņš mirst tās netaisnības dēļ, ko viņš darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Bet kad bezdievīgais atgriežas no savas bezdievības, ko viņš darījis, un dara, kas tiesa un taisnība, tas paturēs savu dvēseli dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Tāpēc ka viņš liek vērā un atgriežas no visiem saviem grēkiem, ko viņš darījis, tad viņš tiešām dzīvos, viņš nemirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Un tomēr Israēla nams saka: Tā Kunga ceļš nav taisns. Vai Mani ceļi, ak Israēla nams, nav taisni? Vai jo vairāk jūsu ceļi nav netaisni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Tādēļ Es jūs tiesāšu, jūs no Israēla nama, ikvienu pēc viņa ceļiem, saka Tas Kungs Dievs. Atgriežaties un griežaties atpakaļ no visiem saviem pārkāpumiem, ka noziegums jums nepaliek par valgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Atmetiet nost no sevis visus savus pārkāpumus, ar ko jūs esat pārkāpuši, un dariet sev jaunu sirdi un jaunu garu. Jo kāpēc jūs gribat mirt, jūs no Israēla nama?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Jo Man nav patikšanas pie mirēja nāves, saka Tas Kungs Dievs. Tāpēc atgriežaties un dzīvojiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Bet tu sāc raudu dziesmu par Israēla valdniekiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Un saki: kas bija tava māte? Lauvu māte starp lauvām apguldamās, viņa uzaudzināja savus bērnus starp jauniem lauvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Un viņa uzaudzināja vienu no saviem bērniem, kas kļuva par jaunu lauvu un mācījās laupīt laupījumu, viņš aprija cilvēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Kad tautas to par viņu dzirdēja, tad tas tapa gūstīts viņu bedrē, un tie viņu aizveda ar ķēdēm uz Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Kad viņa nu redzēja, ka bija velti un ka viņas cerība izzudusi, tad viņa ņēma citu no saviem bērniem un to cēla par jaunu lauvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Tas staigāja starp lauvām, kļuva par jaunu lauvu, un mācījās laupījumu laupīt, viņš aprija cilvēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Viņš atzina viņu atraitnes un postīja viņu pilsētas, tā ka zeme, un kas iekš tās, iztrūcinājās no viņa rūkšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Tad tās tautas no apkārtējām valstīm cēlās pret viņu un izplēta savu tīklu pār viņu; viņu bedrē tas tapa gūstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Un tie viņu lika pinekļos un ķēdēs, un viņu aizveda pie Bābeles ķēniņa; tie viņu aizveda stiprās pilīs, ka viņa balss vairs netapa dzirdēta uz Israēla kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Tava māte bija kā vīna koks, tāpat kā tu, dēstīts pie ūdens, auglīgs un kupls pie lieliem ūdeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Un viņam bija stipri zari, kas derēja par valdītāju scepteriem, un viņš uzauga augsti kuplu zaru vidū un nāca redzams savā augstumā un savu zaru kuplumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Bet viņš tapa izrauts ar bardzību un nomests pie zemes, un rīta vējš izkaltēja viņa augļus; viņa stiprās stīgas tapa nolauztas un sakalta, uguns tās aprija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Un nu tas tuksnesī ir dēstīts, izkaltušā un iztvīkušā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Un uguns ir izlēcis no viņa stīgu zara un ir aprijis viņa augļus, tā ka pie viņa vairs nav stipra zara par valdīšanas scepteri. Tā ir raudu dziesma un būs par raudu dziesmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Un notikās septītā gadā, piektā mēnesī, desmitā mēneša dienā, tad nāca vīri no Israēla vecajiem, To Kungu vaicāt, un apsēdās manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Tad Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Cilvēka bērns, runā uz Israēla vecajiem un saki uz tiem: tā saka Tas Kungs Dievs: vai jūs esat nākuši, Mani vaicāt? Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs: Es negribu, ka jūs Mani vaicājiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Vai tu tos gribi tiesāt? Vai tu gribi tiesāt, cilvēka bērns? Tad stāsti tiem viņu tēvu negantības!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Un saki uz tiem: tā saka Tas Kungs Dievs: tai dienā, kad Es Israēli izredzēju, tad Es pacēlu Savu roku pār Jēkaba nama dzimumu un tiem parādījos Ēģiptes zemē; Es pacēlu Savu roku pār tiem un sacīju: Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Tai dienā Es pacēlu Savu roku pār tiem un tos izvedu no Ēģiptes zemes uz zemi, ko Es priekš viņiem biju izlūkojis, kur piens un medus tek, kas ir jaukāka pār visām zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Un Es uz tiem sacīju: atmetiet ikviens savu acu gānekļus no sevis nost un neapgānāties ar Ēģiptes elkiem; Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Bet tie bija stūrgalvīgi pret Mani un negribēja Mani klausīt; neviens neatmeta savu acu gānekļus un neatstājās no Ēģiptes elkiem. Tāpēc Es sacīju: Es pār tiem izgāzīšu Savu bardzību un izdarīšu pie tiem Savu dusmību pašā Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Bet es darīju sava vārda dēļ, ka tas netaptu sagānīts priekš pagānu acīm, kuru vidū tie bija, priekš kuru acīm Es tiem biju parādījies, tos izvest no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Un Es tos izvedu no Ēģiptes zemes un tos vadīju tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Un Es tiem devu Savus likumus un tiem darīju zināmas tiesas, ko cilvēkam būs darīt, lai caur tām dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Es tiem arī devu Savas svētās dienas, ka tās būtu par zīmi starp Mani un viņiem, lai tie atzītu, ka Es esmu Tas Kungs, kas tos svētī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Bet Israēla nams bija stūrgalvīgs pret Mani tuksnesī; tie nestaigāja Manos likumos un atmeta Manas tiesas, ko cilvēkam būs darīt, lai caur tām dzīvo; un tie ļoti sagānīja Manas svētās dienas, tā ka Es sacīju: Es Savu bardzību pār tiem gribu izgāzt tuksnesī un tiem darīt galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Bet Es darīju Sava vārda dēļ, ka tas netaptu sagānīts priekš to pagānu acīm, priekš kuru acīm Es tos biju izvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Un tomēr Es Savu roku pacēlu pret tiem tuksnesī, tos nevest tai zemē, ko Es tiem biju devis, kur piens un medus tek, kas ir jaukāka pār visām zemēm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Tādēļ ka tie atmeta Manas tiesas un nestaigāja Manos likumos un sagānīja Manas svētās dienas; jo viņu sirds dzinās pakaļ viņu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Bet Mana acs tos žēloja, ka Es tos nenomaitāju un tiem galu nedarīju tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Un Es sacīju uz viņu bērniem tuksnesī: nestaigājiet savu tēvu likumos un nesargājiet viņu tiesas un neapgānāties ar viņu elkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Es esmu Tas Kungs, jūsu Dievs; staigājiet manos likumos un sargājiet manas tiesas un dariet tās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Un svētījiet manas svētās dienas, lai tās ir par zīmi starp mani un jums, un jūs samanāt, ka Es esmu Tas Kungs, jūsu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Bet arī tie bērni bija stūrgalvīgi pret Mani, tie nestaigāja Manos likumos un nesargāja Manas tiesas, tās nedarīdami, ko cilvēkam būs darīt, lai caur tām dzīvo; tie sagānīja Manas svētās dienas, tā ka Es sacīju: Es Savu bardzību pār tiem gribu izgāzt un Savu dusmību pret tiem izdarīt tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Bet Es atturēju Savu roku Sava vārda dēļ, ka tas netaptu sagānīts priekš to pagānu acīm, priekš kuru acīm Es tos biju izvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Un taču Es pacēlu Savu roku pret tiem tuksnesī, tos izkaisīt starp tiem pagāniem un tos izputināt pa tām valstīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Tādēļ ka tie Manas tiesas nebija darījuši, bet bija atmetuši Manus likumus un sagānījuši Manas svētās dienas un viņu acis dzinās pakaļ viņu tēvu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Tāpēc Es tiem arī devu likumus, kas nebija labi, un tiesas, caur ko tie nevarēja dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Un Es tos sagānīju ar viņu dāvanām, caur to, ka tie ikvienai pirmdzimtībai lika caur uguni iet, lai Es tos nopostītu, lai tie samanītu, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Tādēļ cilvēka bērns, runā uz Israēla namu un saki uz tiem: tā saka Tas Kungs Dievs: jūsu tēvi Mani vēl ir zaimojuši, atkāpdamies no Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Kad Es tos biju novedis uz to zemi, par ko Savu roku biju pacēlis, viņiem to dot, tad tie izraudzījās ikkatru augstu pakalnu un ikkatru kuplu koku, un upurēja tur savus upurus un nonesa tur savas riebīgās dāvanas un kvēpināja tur savu saldo smaržu un upurēja turpat savus dzeramos upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Un Es uz tiem sacīju: kas tas par kalnu, kurp jūs ejat? Bet šī vārds līdz šai dienai ir nosaukts elka kalns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Tādēļ saki uz Israēla namu: tā saka Tas Kungs Dievs: jūs esat sagānījušies pa savu tēvu ceļiem un maukojušies viņu gānekļiem pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Tiešām, savas dāvanas upurēdami, saviem bērniem likdami caur uguni iet, jūs esat apgānījušies pie visiem saviem elkiem līdz šai dienai; vai Es no jums ļautos vaicāties, ak Israēla nams! Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, Es negribu, ka jūs Mani vaicājiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Un kas jums prātā nācis, tas mūžam nenotiks, ka jūs sakāt: mēs turēsimies kā tās (pagānu) tautas un kā tās ciltis visās zemēs kalposim kokam un akmenim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, ar stipru roku un izstieptu elkoni un ar izgāztu bardzību Es pār jums gribu valdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Es jūs izvedīšu no tām tautām un jūs sapulcināšu no tām valstīm, kurp esat izkaisīti, ar stipru roku un izstieptu elkoni un ar izgāztu bardzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Un Es jūs vedīšu uz tautu tuksnesi, un tur es ar jums tiesāšos vaigu vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Tā kā Es ar jūsu tēviem esmu tiesājies Ēģiptes zemes tuksnesī, tāpat Es ar jums tiesāšos, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Un Es jums likšu staigāt apakš rīkstes un jūs vedīšu derības saitēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Un Es izmēzīšu no jums tos atkāpējus un atkritējus no Manis, un Es tos gan izvedīšu no tās zemes, kur piemita, bet uz Israēla zemi tie vairs nenāks, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Bet jūs no Israēla nama, tā saka Tas Kungs Dievs: noejat, kalpojiet ikviens saviem elkiem! Bet pēclaikā, tad tiešām jūs Mani klausīsiet un vairs neapgānīsiet Manu svēto vārdu ar savām dāvanām un ar saviem elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Jo uz Mana svētā kalna, uz Israēla augstā kalna, saka Tas Kungs Dievs, tur Man kalpos viss Israēla nams, visi, kas tanī zemē; tur man pie tiem būs labs prāts, un tur Es prasīšu jūsu cilājamos upurus un jūsu upuru pirmajus, ar visu, ko jūs Man svētījat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Man būs labs prāts pie jums kā pie saldas smaržas, kad Es jūs no tām tautām izvedīšu un jūs sapulcināšu no tām valstīm, kur bijāt izkaisīti, un Es caur jums pagodināšos priekš pagānu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Un jūs samanīsiet, ka Es esmu Tas Kungs, kad Es jūs ievedīšu Israēla zemē, tai zemē, par ko Es Savu roku esmu pacēlis, to dot jūsu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Tad jūs tur pieminēsiet savus ceļus un visus savus darbus, ar ko jūs esat apgānījušies, un jums pašiem riebs visa jūsu bezdievība, ko esat darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Tā jūs samanīsiet, ka Es esmu Tas Kungs, kad Es ar jums būšu darījis Sava vārda dēļ, ne pēc jūsu nikniem ceļiem un netikliem darbiem, ak Israēla nams, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Cilvēka bērns, griez savu vaigu pret dienvidiem, un lai (tava valoda) pil pret dienvidiem, un sludini pret to mežu dienvidu klajumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Un saki uz to mežu dienvidos: klausi Tā Kunga vārdu! Tā saka Tas Kungs Dievs: redzi Es iededzināšu uguni iekš tevis, un tas iekš tevis aprīs visus zaļos kokus un visus sausos kokus; tās varenās liesmas nevarēs izdzēst, un tā sadegs viss, kas ir no dienvidiem līdz ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Un visa miesa redzēs, ka Es Tas Kungs to esmu iededzinājis; tas netaps izdzēsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Un es sacīju: ak Kungs Dievs! Tie par mani saka: vai tas nav līdzības stāstītājs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Cilvēka bērns, griez savu vaigu pret Jeruzālemi, un lai (tava valoda) pil pret tām svētām vietām un sludini pret Israēla zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Un saki uz Israēla zemi: tā saka Tas Kungs: redzi, Es pret tevi celšos un izvilkšu Savu zobenu no makstīm un izsakņošu no tevis taisnus un bezdievīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Lai Es nu no tevis izdeldu gan taisnus gan bezdievīgus, tad Mans zobens no savām makstīm izlēks pret visu miesu no dienvidiem līdz ziemeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Un visa miesa atzīs, ka Es, Tas Kungs, esmu izvilcis Savu zobenu no makstīm; tas atkal vairs netaps iebāzts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Bet tu, ak cilvēka bērns, nopūties! Ar satriektiem gurniem un rūgtās skumjās nopūties priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Un kad tie uz tevi sacīs: ko tu vaidi? Tad tev būs sacīt: tās baumas dēļ ka tā nāk, un visas sirdis izkusīs, un visas rokas nogurs, un visa drošība zudīs, un visi ceļi sašļuks; redzi, tā nāks un notiks, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Cilvēka bērns, sludini un saki: tā saka Tas Kungs: saki: zobens, zobens ir trīts un asināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Tas ir trīts, lai kautin kauj, tas ir asināts, lai spīd kā zibens. Vai tad mums būs priecāties, Mana dēla(Jūda) scepteris nicina visus kokus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Un Viņš to (zobenu) devis, lai gludina(spodrina) ka to ņem rokā; tas zobens ir trīts un asināts, lai kāvējam to dod rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Kliedz un kauc, cilvēka bērns! Jo tas celsies pret Maniem ļaudīm, tas celsies pret visiem Israēla valdniekiem; zobenam tie nodoti līdz ar Maniem ļaudīm; tādēļ sit uz saviem gurniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Tiešām, tas zobens ir pārbaudīts; un kas būs, kad tas scepteris, kas nicina, iznīks? saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Tad nu tu, cilvēka bērns, sludini un sasit rokas, jo tas zobens nāks ar divkārtīgu spēku trešo reiz, kaujams zobens, tas lielais kaujamais zobens, tiem visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Lai sirds izkūst un kritušo ir daudz, visos viņu vārtos Es sūtu draudošu zobenu. Ak, tas ir taisīts, lai zib, un ir trīts, lai kauj!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Cērt spēcīgi, sit pa labo roku, griezies, sit pa kreiso roku, kurp tavs asmens griežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Arī Es pats sasitīšu Savas rokas un izdarīšu Savu bardzību; Es, Tas Kungs, to esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Tu tad, ak cilvēka bērns, taisi sev divus ceļus, pa kuriem Bābeles ķēniņa zobenam jānāk; no vienas zemes tiem abiem būs iziet. Taisi roku(virziena rādītājs) ceļa iesākumā, kas rāda uz pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Taisi ceļu, pa ko tas zobens lai nāk pret Amona bērnu Rabu un (otru) pret Jūdu uz stipro Jeruzālemes pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Jo Bābeles ķēniņš stāvēs uz ceļa jūtīm, kur tie divi ceļi šķirās, ar zīlēšanu zīlēdams, viņš metīs bultas, viņš vaicās elkadievus, viņš apraudzīs (upuru)aknas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Tā zīlēšana zīmēs pa viņa labo roku uz Jeruzālemi, tur pievest āžus, atvērt muti uz kliegšanu, pacelt balsi uz kara troksni, likt āžus pret vārtiem, uzmest vaļņus un uztaisīt bulverķus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Šī būs kā aplama zīlēšana viņu acīs, tās zvērēšanas dēļ kas viņiem zvērēta; bet Viņš pieminēs to noziegumu un tos gūstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Tādēļ tā saka Tas Kungs Dievs: Tāpēc ka jūs savus noziegumus esat atgādinājuši, savus pārkāpumus atklādami, tā ka jūsu grēki top redzēti visos jūsu darbos; tāpēc ka jūs topat pieminēti, tad jūs ar rokām tapsiet gūstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Un tu, nesvētais, bezdievīgais Israēla valdnieks, kam pienākusi sava diena, kurā noziegumi beidzās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Tā saka Tas Kungs Dievs: liec nost galvas glītumu un ņem zemē kroni, jo tas nepaliks, kā tas bija: zemais tiks paaugstināts un augstais pazemots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Es to likšu postā, postā, postā, un šī nebūs, līdz kamēr nāk, kam tā tiesa pieder, - tam Es to došu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Un tu, cilvēka bērns, sludini un saki: tā saka Tas Kungs Dievs par Amona bērniem un par viņu nievāšanu un saki: zobens, zobens izvilkts, lai kauj, trīts, lai spīd un zib.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Kamēr tev aplamas parādīšanas rāda, kamēr tev melus sludina, tas tevi liks pie nokauto nesvēto kakliem, kuru diena nāk gala nozieguma laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Bāz zobenu makstīs! Es tevi sodīšu tai vietā, kur tu radīts, tai zemē, kur tu dzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Un Es izgāzīšu pār tevi Savu dusmību, Es uzpūtīšu pret tevi Savas bardzības uguni, un tevi nodošu nežēlīgu cilvēku, niknu postītāju rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Tu būsi ugunij par barību, tavas asinis tecēs pašā tavā zemē, un tevi vairs nepieminēs; jo Es Tas Kungs to esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Tad nu, ak cilvēka bērns, vai gribi tiesāt, vai gribi tiesāt to asins pilsētu? Tad rādi viņai visas viņas negantības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Un saki: tā saka Tas Kungs Dievs: ak pilsēta, kas asinis izlej savā vidū, lai viņas laiks nāk, un kas sev taisa elkus un apgānās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Caur tām asinīm, ko izlējusi, tu esi noziegusies, un ar saviem elkiem, ko taisījusi, tu esi sagānījusies, un tavām dienām esi likusi tuvu nākt, un esi nākusi savos gados. Tādēļ Es tevi esmu nodevis pagāniem par nievāšanu un visām zemēm par apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Kas tuvu un kas tālu no tevis, tie tevi apsmies, tevi, kam vārds sagānīts un kas nekārtības pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Redzi, Israēla valdnieki ikviens cik spēdams izlej asinis tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Tēvu un māti tie pie tevis nicina, svešiniekam tie dara varas darbu tavā vidū, bāriņus un atraitnes tie apspiež pie tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Manus svētumus tu nicini, un Manas svētās dienas tu sagāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Mēlneši ir pie tevis, kas asinis izlej; tie ēd tavā vidū uz (elku)kalniem, dara bezkaunību tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Tie atsedz pie tevis tēva kaunumu, un pieguļ pie tevis sārņiem nešķīstas sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Cits ar sava tuvāka sievu dara negantību, cits bezkaunīgi apgāna savu vedeklu, atkal cits atzīst savu māsu, sava tēva meitu, tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Tie ņem pie tevis dāvanas, izliet asinis; tu piedzen augļus un plēs pagaidus, un esi plēsīga pie sava tuvākā ar varasdarbu, bet Mani tu esi aizmirsusi, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Redzi, tad Es sasitu savas rokas par to mantu, ko tu plēsi, un par tām asinīm, kas tavā vidū izlietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Vai tava sirds pastāvēs, vai tavas rokas būs stipras tanīs dienās, kad Es ar tevi tiesāšos? Es Tas Kungs to esmu runājis un to darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Un Es tevi izkaisīšu starp tautām un tevi izklīdināšu pa valstīm un darīšu galu tavai nešķīstībai tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Un tu būsi nesvēta caur sevi pašu priekš pagānu acīm un samanīsi, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Cilvēka bērns! Israēla nams Man ir palicis par sārņiem, tie visi ir varš un alva un dzelzs un svins ceplī, tie ir palikuši par sudraba sārņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Tādēļ tā saka Tas Kungs Dievs: Tāpēc ka jūs visi esat palikuši par sārņiem, tad redzi, Es jūs sapulcināšu Jeruzālemes vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Tā kā sudrabu un varu un dzelzi un svinu un alvu kopā liek ceplī, un uguni uzpūš apakšā, lai kausē, tā Es jūs sapulcināšu Savā dusmībā un bardzībā, un jūs ielikšu un kausēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Tiešām, Es jūs sapulcināšu un uzpūtīšu pret jums Savas dusmības uguni, ka jūs tur iekšā topat kausēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Tā kā sudrabs ceplī top kausēts, tāpat jūs tur tapsiet kausēti, un jūs samanīsiet, ka Es, Tas Kungs, Savu bardzību esmu izlējis pār jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Cilvēka bērns, saki uz to: tu esi zeme, kas nav šķīstīta, kur nelīst dusmības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Viņas pravieši cēluši dumpi viņas vidū; tā kā rūcošs lauva, kad tas laupījumu laupa, tā tie ēd dvēseles, tie plēš naudu un mantu, tie dara daudz atraitņu viņas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Viņas priesteri neganti pārkāpj manu bauslību un sagāna manus svētumus, tie neizšķir svētu un nesvētu un nemāca izšķirt, kas šķīsts un kas nešķīsts, tie apsedz savas acis priekš manām, svētām dienām, un es viņu starpā topu sagānīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Viņas virsnieki ir viņas vidū kā vilki, kas laupa laupījumu, izlej asinis, samaitā dvēseles, mantas kārības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Un viņas pravieši tos apmet ar nelīpamiem kaļķiem un redz aplamas parādīšanas un sludina tiem melus un saka: tā saka Tas Kungs Dievs; un tomēr Tas Kungs nav runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Tie ļaudis tai zemē dara varas darbu un laupīt laupa, un nabagu un bēdīgu tie plēš un svešinieku tie nospaida bez tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Tad Es meklēju kādu vīru no tiem, kas atkal sataisītu sētu un stātos plaisumā, manā priekšā aizstāvēt to zemi, ka Es to nemaitātu, bet Es neatradu neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Tāpēc Es pār tiem esmu izlējis Savu bardzību, ar Savas dusmības uguni Es tiem esmu galu darījis, viņu grēkus Es tiem esmu metis uz viņu galvu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Cilvēka bērns! Divas sievas bija vienas mātes meitas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Tās dzina maucību Ēģiptes zemē, savā jaunībā tās maukojās, tur viņu krūtis tapa apkamptas, un viņu jumpravības krūtis aptaustītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Un tai vecākai bija vārds Aāla, un viņas māsai Aāliba, un tās Man kļuva par sievām un dzemdēja dēlus un meitas. Šie bija viņu vārdi: Aāla ir Samarija, un Aāliba ir Jeruzāleme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Un Aāla dzina maucību, pie Manis būdama, un iekarsa pret saviem drauģeļiem, pret Asiriešiem, kas bija tuvumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Kas bija apģērbti ar pazilām purpura drēbēm un bija lielkungi un valdnieki, visnotaļ iekārojami jaunekļi, jātnieki, kas uz zirgiem jāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Tā viņa maukoja ar visiem tiem skaistiem Asiriešu bērniem, pie visiem, pret ko viņa iekarsa, tā sagānījās ar visiem viņu elkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Un viņa arī nepameta savu maucību ar Ēģipti, jo tie pie viņas bija gulējuši viņas jaunībā, un viņas jumpravības krūtis bija aptaustījuši un lielu maucību ar to dzinuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Tāpēc Es viņu nodevu viņas drauģeļu rokā, Asura bērnu rokā, pret kuriem tā bija iekarsusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Šie atsedza viņas kaunumu, ņēma nost viņas dēlus un viņas meitas, un pašu nokāva ar zobenu. Un viņa palika par pasaku starp sievām pēc tam, kad sodība par viņu bija turēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Kad nu viņas māsa Aāliba to redzēja, tad viņa iekarsa niknāki nekā tā otra, un viņas maukošana bija lielāka nekā viņas māsas maukošana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Viņa iekarsa pret Asura bērniem, tiem lielkungiem un valdniekiem, kas bija tuvumā, kas bija apģērbti pilnās bruņās, jātnieki, kas uz zirgiem jāj, visnotaļ iekārojami jaunekļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Tad Es redzēju, ka viņa bija sagānīta, viņām abām bija vienāds ceļš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Tomēr šī vēl vairāk dzina maucību, jo kad viņa pie sienas redzēja nomālētus vīrus, Kaldeju tēlus, ar sarkanumu rakstītus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Apjoztus ar jostu ap saviem gurniem un ar augstām cepurēm uz savām galvām, kas visi kā valdītāji izskatījās, tā kā Bābeles bērni Kaldejā, savā dzimtenē, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Tad viņa pret tiem iekarsa, kad viņas acis tos ieraudzīja, un sūtīja vēstnešus pie tiem uz Kaldeju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Un Bābeles dēli nāca pie viņas uz kārības gultu un sagānīja viņu ar savu maukošanu, un viņa ar tiem sagānījās; un tad viņas dvēsele viņus apnika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Un kad viņa parādīja savu maucību un atsedza savu kaunumu, tad Mana dvēsele viņu apnika, tā kā Mana dvēsele bija apnikusi viņas māsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Bet viņa vairot vairoja savu maukošanu un pieminēja savas jaunības dienas, kur viņa bija maukojusi Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Un viņa iekarsa pret saviem drauģeļiem, kuru miesa ir kā ēzeļu miesa un kuru braulums(sēkla) ir kā ērzeļu braulums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tā tu esi atjaunojusi savas jaunības bezkaunību, kur tie no Ēģiptes aptaustīja tavas krūtis, tavas jaunības krūšu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Tādēļ, ak Aāliba, tā saka Tas Kungs Dievs, redzi, Es pamodināšu pret tevi tavus drauģeļus, no kuriem tava dvēsele ir nogriezusies, un tos atvedīšu visapkārt pret tevi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Bābeles dēlus un visus Kaldejus, Pekodu un Šou un Kou un visus Asura dēlus līdz ar tiem, iekārojamus jaunekļus, kas visi ir lielkungi un valdnieki, virsnieki un cienīgi, kas visnotaļ jātnieki uz zirgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Un tie nāks pret tevi ar ratiem, vāģiem un riteņiem un ar tautu pulkiem; ar krūšu bruņām un priekšturamām bruņām un dzelzs cepurēm tie pret tevi apmetīsies visapkārt. Un Es viņiem pavēlēšu sodu, un tie tevi sodīs pēc savām tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Un Es pie tevis parādīšu savu karstumu un tie pret tevi turēsies bargi: tie tev nocirtīs degunu un ausis, un kas no tevis atliek, tas kritīs caur zobenu. Tie atņems tavus dēlus un tavas meitas, un kas no tevis atliek, to uguns aprīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Arī tavas drēbes tie tev novilks un noņems tavu jaukumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Tā Es darīšu galu tavai bezkaunībai un tavai maukošanai, kas no Ēģiptes zemes, ka tu savas acis vairs uz tiem nepacel un Ēģipti vairs nepiemini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Jo tā saka Tas Kungs Dievs: redzi, Es tevi nodošu rokā tiem, ko tu ienīsti, rokā tiem, ko tava dvēsele apnikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Tie ar tevi darīs kā ienaidnieki, un noņems visu tavu sagādu un tevi pametīs kailu un pliku, ka tavs mauku kaunums top atsegts līdz ar tavu bezkaunību un ar tavu maucību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Tas tev notiks, tāpēc ka tu pagāniem pakaļ esi maukojusi un ar viņu elkiem sagānījusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Savas māsas ceļu tu esi staigājusi, tāpēc Es viņas biķeri došu tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Tā saka Tas Kungs Dievs: tavas māsas biķeris tev jādzer, tas dziļais un platais, kur daudz saiet iekšā; par apsmieklu un kaunu tas būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Tu būsi pilna reibuma un skumības, tavas māsas Samarijas biķeris ir spaidu un vaidu biķeris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Tu to dzersi un izlaizīsi un satrieksi viņa gabalus un saplosīsi tavas krūtis, jo Es to esmu runājis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Tāpēc tā saka Tas Kungs Dievs: tādēļ ka tu Mani esi aizmirsusi un Mani aiz muguras metusi, tad arī nes savu bezkaunību un maucību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Un Tas Kungs sacīja uz mani: cilvēka bērns, vai tu negribi Aālu un Aālibu tiesāt? Tad teici tām viņu negantības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Jo tās pārkāpušas laulību, un asinis ir viņu rokās, un ar saviem elkiem tās pārkāpušas laulību, saviem bērniem, ko Man bija dzemdējušas, tās ir likušas caur uguni iet, viņiem par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Tad tās Man vēl to ir darījušas: to brīdi tās Manu svēto vietu darījušas nešķīstu un sagānījušas Manas svētās dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Jo kad tās bija nokāvušas savus bērnus saviem elkiem, tad tās tai pašā dienā nāca Manā svētā vietā, to sagānīt, un redzi, tā tās ir darījušas Manā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Tās arī pēc vīriem ir sūtījušas, kam no tālienes bija jānāk; kad vēstnesis uz turieni tapa sūtīts, redzi, tad tie nāca; priekš tiem tu mazgājies un svaidīji savas acis un izgreznojies ar skaistumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Un sēdēji uz krāšņa sēdekļa, un tam priekšā stāvēja sataisīts galds, un uz tā tu liki Manas kvēpināmās zāles un Manu eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Un tur atskanēja nebēdnīgs troksnis un pie tā lielā vīru pulka tika atvesti dzērāji no tuksneša, tie lika roku sprādzes ap viņu rokām un krāšņus kroņus uz viņu galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Un Es sacīju par to, kas veca palikusi maucībā, vai ar to arīdzan vēl maukot maukosies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Un tie pie tās iegāja, kā iet pie maukas, tā tie iegāja pie Aālas un pie Aālibas, tām bezkaunīgām sievām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Tāpēc taisni vīri viņas sodīs pēc laulības pārkāpēju un asins izlējēju tiesas, jo tās ir laulības pārkāpējas un asinis ir viņu rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Jo tā saka Tas Kungs Dievs: es atvedīšu pret tām pulku, un tās nodošu par laupījumu un postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Un tas pulks viņas nomētās ar akmeņiem, un tās sasitīs ar saviem zobeniem, tie nokaus viņu dēlus un viņu meitas un sadedzinās viņu namus ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Tā Es izdeldēšu to bezkaunību no zemes, ka visas sievas dabū mācību, ka tās nedara pēc jūsu bezkaunības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Tā jūsu bezkaunība jums taps uzlikta, un jūs nesīsiet savu elku grēkus un samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Un Tā Kunga vārds notika uz mani devītā gadā, desmitā mēnesī, desmitā mēneša dienā, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Cilvēka bērns, uzraksti sev šīs dienas, šīs pašas dienas vārdu: Bābeles ķēniņš šai dienā ir apmeties pret Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Saki līdzību pret to atkāpēju sugu un saki uz tiem: tā saka Tas Kungs Dievs: cel podu pie uguns, cel to klāt, ielej arīdzan ūdeni iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Saliec tos gabalus tur iekšā, visus labos gabalus, cisku un pleci, pildi to ar tiem visulabākiem kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Ņem no visulabākām avīm un iekuri arī uguni apakš tiem kauliem, lai labi vārās, un kauli, kas iekšā, lai labi izvārās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Tādēļ tā saka Tas Kungs Dievs: Ak vai tai asins pilsētai, tam podam, kas sarūsējis un kam rūsa negrib noiet. Gabalu pēc gabala ņem ārā, meslus par to nemet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Jo viņas asinis ir viņas vidū, viņa tās ir izlējusi uz kailas klints un tās nav izgāzusi zemē, ka pīšļi tās apklātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Sūtīt bardzību un parādīt atriebšanu, Es viņas asinis esmu licis izliet uz kailas klints, ka netop apklātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Tādēļ tā saka Tas Kungs Dievs: Ak vai, tai asins pilsētai! Arī es kurināšu uguni lielu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Pienesi daudz malkas, iededzini uguni, savāri gaļu, un zāļo to ar zālēm, un lai tie kauli savārās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Pēc tam cel viņu tukšu uz oglēm, lai tas top karsts un lai viņa varš nodeg sarkans un viņa netīrums, kas tur iekšā, izkūst, un viņa rūsa top izdeldēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Viņš dara lielu pūliņu, un viņa rūsa negrib noiet, viņa rūsa pastāv ugunī');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Tavas negantās nešķīstības dēļ; tādēļ ka Es tevi esmu šķīstījis, un tu neesi palikusi šķīsta, tad tu no savas nešķīstības vairs netapsi šķīsta, kamēr Es Savu bardzību pie tevis bušu izdarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Es Tas Kungs to esmu runājis, tā būs, un to Es darīšu, Es no tā neatstāšos un nesaudzēšu un neapželošos; pēc taviem ceļiem un pēc taviem darbiem tevi sodīs, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Cilvēka bērns, redzi, Es atņemšu tavu acu jaukumu caur vienu sitienu; tomēr tev nebūs žēloties nedz raudāt nedz asaras izliet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Nopūties klusiņām, necel raudas par mirušiem. Bet uzsien savu cepuri un apvelc savas kurpes kājās, neaptin savu muti, tev arī nebūs ēst raudu maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Tā es runāju uz tiem ļaudīm no rīta, un vakarā mana sieva nomira. Un es darīju no rīta, kā man bija pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Tad tie ļaudis uz mani sacīja: vai tu negribi mums stāstīt, kādēļ mums šīs lietas rāda, ka tu tā dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Un es uz tiem sacīju: Tā Kunga vārds uz mani noticis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Saki Israēla namam: tā saka Tas Kungs Dievs: redzi, Es sagānīšu Savu svēto vietu, jūsu lepno stiprumu, jūsu acu jaukumu un jūsu dvēseļu mīlību, un jūsu dēli un jūsu meitas, ko jūs esat atstājuši, kritīs caur zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Tad jūs darīsiet, kā Es esmu darījis, muti jūs neaptīsiet un raudu maizi neēdīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Un jūsu cepures būs uz jūsu galvām un jūsu kurpes jūsu kājās. Jūs nežēlosities nedz raudāsiet, bet iznīksiet savos noziegumos, un vaidēsiet cits pret citu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Tā Ecehiēls jums būs par zīmi; itin kā viņš darījis, tā jūs darīsiet; kad tas notiks, tad jūs samanīsiet, ka Es esmu Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Un tu, cilvēka bērns, vai tas nebūs tai dienā, kad Es no tiem atņemšu viņu drošumu, viņu slavu un prieku, viņu acu jaukumu un viņu dvēseles mīlību, viņu dēlus un viņu meitas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Tai dienā nāks pie tevis viens, kas izglābies un to tavām ausīm stāstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Tai dienā tava mute atvērsies kā arī tam izglābtam, un tu runāsi un nebūsi vairs mēms. Tā tu būsi par brīnuma zīmi un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Cilvēka bērns, griez savu vaigu pret Amona bērniem un sludini pret tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Un saki uz Amona bērniem: klausiet Tā Kunga Dieva vārdu! Tā saka Tas Kungs Dievs: Tāpēc ka jūs par Manu svēto vietu sakāt: re, re! Tā ir sagānīta! Un par Israēla zemi: tā ir izpostīta! Un par Jūda namu: tie ir cietumā gājuši! -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Tādēļ redzi, Es tevi nodošu austruma bērniem par mantību, ka tie tavā vidū uzceļ savas teltis un tavā vidū uztaisa savas māju vietas; tie ēdīs tavus augļus un dzers tavu pienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Un Es Rabu darīšu par kamieļu ganību un Amona bērnus par avju laidaru, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Jo tā saka Tas Kungs Dievs: tādēļ ka tu esi plaukšķinājusi ar rokām un situsi ar kājām un no visas sirds lepni(nievājot) esi priecājusies par Israēla zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Tāpēc redzi, Es izstiepšu Savu roku pret tevi un tevi nodošu pagāniem par laupījumu un tevi izdeldēšu no tautām un tevi nomaitāšu no valstīm; Es tevi izdeldēšu, un tu samanīsi, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Tā saka Tas Kungs Dievs: Tāpēc ka Moabs un Seīrs saka: redzi, Jūda nams ir tā kā visi pagāni, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Tādēļ redzi, Es atvēršu Moaba sānus no tām pilsētām, no viņa robežu pilsētām sākot, viņa zemes jaukumu, Betjesivotu, Baāl Meonu un līdz Kiriataīmai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Austruma bērniem klāt pie Amona bērniem Es viņu atdošu par mantību, tā kā Amona bērni starp tautām vairs netaps pieminēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Un Es turēšu tiesu par Moabu, un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Tā saka Tas Kungs Dievs: tādēļ ka Edoms ar atriebšanu ir atriebies pret Jūda namu, un tie ļoti ir noziegušies, pie tiem atriebdamies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Tādēļ tā saka Tas Kungs Dievs: Es izstiepšu Savu roku pret Edomu un izdeldēšu no viņa cilvēkus un lopus, un Es to darīšu par posta vietu, un tie kritīs caur zobenu no Temana līdz Dedanam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Un Es atriebšos pie Edoma caur Savu Israēla ļaužu roku, un tie ar Edomu darīs pēc Manas dusmības un pēc Manas bardzības, tā tie samanīs Manu atriebšanu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Tā saka Tas Kungs Dievs: tādēļ ka Fīlisti atriebušies un no sirds lepni atriebušies uz izdeldēšanu pēc veca ienaida,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Tādēļ tā saka Tas Kungs Dievs: redzi, Es izstiepju Savu roku pār Fīlistiem un izdeldēšu Krietus un nomaitāšu tos atlikušos jūrmalā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Un Es pie tiem izdarīšu lielu atriebšanu ar bargām sodībām, un tie samanīs, ka Es esmu Tas Kungs, kad Es Savu atriebšanu pie tiem būšu izdarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Un notikās vienpadsmitā gadā, pirmā mēneša dienā, tad Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Cilvēka bērns! Tāpēc ka Tirus par Jeruzālemi sacījis: redzi, tautu vārti ir nolauzti, nu pie manis griežas, es nu pildīšos, viņa ir postīta!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Tādēļ tā saka Tas Kungs Dievs: redzi, Es celšos pret tevi, ak Tiru, un atvedīšu pagānu pulkus pret tevi, kā jūra ceļas ar saviem viļņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Tie postīs Tirus mūrus un nolauzīs viņa torņus, un Es nomēzīšu viņa pīšļus no viņa un to darīšu par kailu klinti');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Kur tīklus izplētīs jūras vidū; jo es to esmu runājis, saka Tas Kungs Dievs; un tas būs tautām par laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Un viņa ciemi laukā ar zobenu taps apkauti un samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Jo tā saka Tas Kungs Dievs: redzi, Es atvedīšu pret Tiru NebukadNecaru, Bābeles ķēniņu, to ķēniņu ķēniņu no ziemeļiem, ar zirgiem un ratiem un jātniekiem un lieliem ļaužu pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Viņš apkaus tavus ciemus laukā ar zobenu un taisīs pret tevi bulverķus un uzmetīs pret tevi valni un uzcels pret tevi sedzamas bruņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Un viņš cels savus āžus pret taviem mūriem un nolauzīs tavus torņus ar saviem dzelzs ieročiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Putekļi no viņa zirgu pulka tevi apklās. Tavi mūri drebēs no jātnieku un riteņu un ratu trokšņa, kad viņš ieies pa taviem vārtiem, kā ieiet salauztā pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Viņš samīs ar savu zirgu nagiem visas tavas ielas; tavus ļaudis viņš nokaus ar zobenu un nogāzīs pie zemes tavus stipros pīlārus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Un tie laupīs tavu padomu un postīs tavas preces un nolauzīs tavus mūrus un apgāzīs tavus skaistos namus un nometīs tavus akmeņus un tavus kokus un tavus pīšļus ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Tad Es darīšu galu tavu dziesmu skaņai un tavu kokļu balsi vairs nedzirdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Un Es tevi darīšu par kailu klinti, tu būsi vieta, kur izplēst tīklus, tu vairs netapsi uztaisīts; jo Es, Tas Kungs, to esmu runājis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Tā saka Tas Kungs Dievs pret Tiru: vai tās salas no tavas krišanas trokšņa netrīcēs, kad ievainotie vaidēs, kad kautin kausies tavā vidū?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Un visi jūras lielkungi nokāps no saviem goda krēsliem un nometīs savus svārkus un novilks savas izrakstītās drēbes; tie apģērbsies ar trīcēšanu, apsēdīsies zemē un ik acumirkli drebēs un iztrūcināsies par tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Un tie par tevi sāks raudu dziesmu un uz tevi sacīs: Ak vai, kā tu esi bojā gājusi, ļaužu pilnā jūras pilsēta, tu slavenā pilsēta, kas bija varena uz jūras, pati un viņas iedzīvotāji, kas izbiedēja visus, kas gar viņu dzīvoja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nu salas trīc tavas krišanas dienā, tiešām salas jūrā dreb par tavu galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Jo tā saka Tas Kungs Dievs: kad Es tevi darīšu par postītu pilsētu, tā kā tās pilsētas, kur vairs nedzīvo, kad Es jūru pār tevi vedīšu, un liels ūdens tevi apklās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Tad Es tevi metīšu zemē pie tiem, kas grimuši bedrē, pie tiem senajiem ļaudīm, un Es tevi nostumšu zemē, apakšējās un tukšās zemes vietās mūžīgi, pie tiem, kas nogrimuši bedrē, tā ka iekš tevis nedzīvos; bet jaukumu Es celšu dzīvo zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Es tev darīšu briesmīgu galu, un tu vairs nebūsi; kad tevi meklēs, tad tevi ne mūžam vairs neatradis, saka Tas Kungs Dievs:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Tu tad, ak cilvēka bērns, uzņem raudu dziesmu par Tiru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Un saki uz Tiru, kas dzīvo pie jūras ostām un tirgojās ar tautām daudz salās: tā saka Tas Kungs Dievs: ak Tiru, tu saki: es esmu brīnum skaists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Tavas robežas ir jūras vidū, tavi cēlēji tevi darījuši brīnum skaistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Tie visus tavus galdus ir taisījuši no Senira priedēm, tie ņēmuši ciedru kokus no Lībanus, tev taisīt masta kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Tavus airus tie taisījuši no Basanas ozoliem, tavus galdus tie taisījuši no ziloņkauliem uz dārgu priežu koka no Ķitim krastiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Dārgs audekls ar izrakstītu darbu no Ēģiptes bija tavs zēģelis, tev par karogu; no zila un sarkana purpura no Elisus salām bija tavi apsegi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Sidonas un Arvadas iedzīvotāji bija tavi airētāji; tavi gudrie, ak Tiru, bija pie tevis tavi stūrētāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Ģebalas vecaji un viņas gudrie bija pie tevis, izlabot tavu laivu plaisumus. Visas jūras laivas un visi laivinieki bija pie tevis, izmainīt tavas preces.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persieši un Lidieši un Libieši bija tavā karaspēkā tavi karavīri; priekšturamās bruņas un dzelzs cepures tie pie tevis uzkāra; tie tevi greznoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvadas bērni un tavs spēks bija visapkārt uz taviem mūriem, un sargi bija uz taviem torņiem, tie uzkāra savas priekšturamās bruņas visapkārt pie taviem mūriem; tie tevi darīja brīnum skaistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Taršišs tirgojās ar tevi ar daudz un dažādām precēm: sudrabu, dzelzi, alvu un svinu noveda tavos tirgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javans, Tubals un Mešehs, tie bija tavi veikalnieki: ar cilvēkiem un vara lietām tie ar tevi tirgojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'No Togarmas nama noveda tavos tirgos braucamus un jājamus zirgus un zirgēzeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Dedana bērni bija tavi veikalnieki, daudz salas tirgojās caur tavu roku; ziloņkaulus un ebon kokus(melnkoks) tie tev atdeva par maksu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Sīrija ar tevi tirgojās tavu daudzkārtīgu amata darbu dēļ: rubīnus, purpuru un rakstītu darbu, dārgu audekli un dārgas krelles un dārgus akmeņus tie noveda tavos tirgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Jūda un Israēla zeme, tie bija tavi veikalnieki: kviešus no Minites un saldi smaržīgas zāles un medu un eļļu un balzamu tie mainīja tavos tirgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus ar tevi tirgojās tavu daudzkārtīgu amata darbu dēļ ar dažādām precēm, ar saldu vīnu un baltu vilnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedans un UzalaJavans veda uz taviem tirgiem izstrādātu dzelzi; kasīju un kalmu tie pie tevis izmainīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedans ar tevi tirgojās ar skaistām vadmalām priekš segliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arābija un visi Ķedara lielkungi, tie tirgojās caur tavu roku, ar jēriem un auniem un āžiem tie ar tevi tirgojās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Sabas un Raēmas veikalnieki, tie ar tevi tirgojās; visādas dārgas zāles, dārgus akmeņus un zeltu tie noveda tavos tirgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Harans un Kane un Edens, Zebas, Asura un Ķilmada veikalnieki ar tevi tirgojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Tie bija tavi veikalnieki ar dārgām drēbēm, ar purpura ziliem un raibi austiem mēteļiem un ar strīpainām (grīdas)segām un ar pītām un tītām virvēm tavos tirgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Taršiša laivas bija tās vedējas uz taviem tirgiem. Un tu tapi bagāts un augstā godā celts jūru vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Tavi laivinieki tevi veda pa vareniem ūdeņiem, bet rīta vējš tevi satriecis jūru vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tava manta un tavas preces un tava tirgošana, tavi laivinieki un tavi stūrmaņi un tavi laivu taisītāji, un kas ar tevi tirgojās, un visi tavi karavīri, kas pie tevis, un visa tava draudze, kas tavā vidū, kritīs jūras vidū tai dienā, kad tu iesi bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'No tavu laivinieku brēkšanas lauki drebēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Un visi airētāji, stūrmaņi ar visiem jūras laiviniekiem izkāps no savām laivām un stāvēs uz zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Un tie par tevi brēks un gauži kliegs un metīs pīšļus uz savām galvām, - tie vārtīsies pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Tie tevis dēļ apcirpsies un apjozīs maisus un raudās par tevi ar dvēseles rūgtumu un gaužām žēlabām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Un tie vaidēdami par tevi sāks raudu dziesmu un vaidēs par tevi un sacīs: kas ir kā Tirus, tā izdeldēts jūras vidū?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Kad tavas preces jūrā tapa vestas, tad tu daudz tautas pieēdināji ar savām dažādām mantām, un ar savu tirgošanu tu ķēniņus virs zemes esi darījis bagātus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Bet nu, kad tu no jūras esi satriekts dziļos ūdeņos, tad tava tirgošana un visa tava draudze tavā vidū ir gājusi bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Visi salu iedzīvotāji par tevi iztrūcinājās, un viņu ķēniņiem mati cēlās stāvu, viņu vaigi nobāl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Tie veikalnieki pa tautām svilpo par tevi; tu esi galu ņēmis ar briesmām un nebūsi vairs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Cilvēka bērns, saki uz Tirus valdnieku: tā saka Tas Kungs Dievs: Tāpēc ka tava sirds lepojās un saka, es esmu dievs, es sēžu uz dieva krēsla jūru vidū, un tu tomēr esi cilvēks un ne Dievs, un tu pacēli savu sirdi, kā Dieva sirdi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Redzi, tu esot gudrāks nekā Daniēls, tev nekas neesot ne apslēpts ne tumšs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Caur savu gudrību un caur savu saprašanu tu sev esot dabūjis spēku un krājis zeltu un sudrabu pie savas mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Caur savu lielo gudrību tu tirgodamies esot vairojis savu bagātību, un tava sirds lepojās tavas bagātības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Tāpēc tā saka Tas Kungs Dievs, tādēļ ka tu savu sirdi esi paaugstinājis, kā Dieva sirdi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Tad redzi, Es vedīšu svešus pār tevi, tos visbriesmīgākos starp tautām; tie izvilks savus zobenus pār tavu jauko gudrību un apgānīs tavu spožumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Tie tevi nometīs bedrē, un tu nomirsi kā nokauti mirst pat jūru vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Vai tu tad sava kāvēja priekšā sacīsi: es esmu dievs, un tu tomēr esi cilvēks un ne Dievs, un esi sava kāvēja rokā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Tu nomirsi kā neapgraizītie mirst caur svešu roku; jo Es to esmu runājis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Atkal Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Cilvēka bērns! Sāc raudu dziesmu par Tirus ķēniņu un saki uz viņu: tā saka Tas Kungs Dievs: tu kārtības zieģelis, pilns gudrības un liela skaistuma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Tu biji Edenē, Dieva dārzā, visādi dārgi akmeņi bija tavs apsegs: sardi, topāzi, dimanti, turķisi, oniķi, jaspisi, safīri, ametisti, smaragdi un zelts. Tavas bungas un tavas stabules skanēja tavā priekšā, tai dienā, kad tevi (par ķēniņu) cēla, tās bija gatavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Tu biji svaidīts ķerubs, kas sargā; Es tevi tā biju iecēlis: tu biji uz Dieva svētā kalna, tu staigāji degošu akmeņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Tu biji skaidrs savos ceļos, no tās dienas, kad tevi (par ķēniņu) cēla, kamēr bezdievība pie tevis tapa atrasta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Caur tavu lielo tirgošanos tava sirds pildījās ar netaisnību, un tu esi apgrēkojies; tāpēc Es tevi izmetu kā sagānītu no Dieva kalna un izdeldu tevi, to ķerubu, kas sargā, no to degošo akmeņu vidus nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Tava sirds lepojās tava skaistuma dēļ, tu savu gudrību esi pazaudējis caur savu spožumu, tāpēc Es tevi metu pie zemes un lieku tevi par mācību ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Ar savu noziegumu pulku caur savu netaisno tirgošanos tu esi sagānījis savus svētumus. Tāpēc Es lieku ugunij iziet no tava vidus; tas tevi aprīs, un Es tevi daru par pelniem virs zemes, priekš visu acīm, kas tevi ierauga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Visi, kas tevi pazīst starp tautām, par tevi iztrūcinājās; tu esi galu ņēmis ar briesmām un nebūsi vairs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Atkal Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Cilvēka bērns, griez savu vaigu pret Sidonu un sludini pret to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Un saki: tā saka Tas Kungs Dievs: redzi, Es celšos pret tevi, Sidona, un pagodināšos tavā vidū, un tie samanīs, ka Es esmu Tas Kungs, kad Es tiesu nesīšu pār viņu un svēts parādīšos pie viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Jo Es sūtīšu mēri pie viņas un asinis pa viņas ielām, un kautie kritīs viņas vidū caur zobenu, kas visapkārt nāks pret viņu, un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Un Israēla namam vairs nebūs asu ērkšķu, nedz sāpīgu dadžu no visiem tiem apkārtējiem, kas tos vajā, un tie samanīs, ka Es esmu Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Tā saka Tas Kungs Dievs: kad Es Israēla namu sapulcināšu no tām tautām, starp kurām tie izkaisīti, un Es pie viņiem svēts parādīšos priekš pagānu acīm, tad tie dzīvos savā zemē, ko Es savam kalpam Jēkabam esmu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Un tie tur dzīvos droši un uztaisīs namus un dēstīs vīna dārzus. Tiešām, tie dzīvos droši, kad Es tiesu nesīšu pret visiem tiem apkārtējiem, kas tos vajājuši, un tie samanīs, ka Es esmu Tas Kungs, viņu Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Desmitā gadā, desmitā mēnesī, divpadsmitā mēneša dienā, Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Cilvēka bērns, griez savu vaigu pret Faraonu, Ēģiptes ķēniņu, un sludini pret viņu un pret visu Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Runā un saki: tā saka Tas Kungs Dievs: Es celšos pret tevi, Faraonu, Ēģiptes ķēniņ, tu lielais jūras zvērs, kas savu upju vidū guļ un saka: mana upe ir mana, un to es sev esmu taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Bet Es likšu makšķeri tavā pažoklī, un likšu tavu upju zivīm pielipt pie tavām zvīņām, un izvilkšu no tām upēm tevi un visas tavu upju zivis, kas līp pie tavām zvīņām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Un Es tevi nometīšu tuksnesī, tevi, un visas tavu upju zivis; tu kritīsi uz lauku, tu netapsi sakrāts nedz salasīts; zvēriem virs zemes un putniem apakš debess Es tevi dodu par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Un visi Ēģiptes iedzīvotāji samanīs, ka Es esmu Tas Kungs, tāpēc ka tie bijuši niedru stobrs Israēla namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Kad tie tevi satvēra rokā, tad tu lūzi un tiem pāršķēli sānus, un kad tie uz tevi atspiedās, tad tu salūzi un darīji tiem gurnus slābanus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Tāpēc tā saka Tas Kungs Dievs: redzi, Es vedīšu pār tevi zobenu un no tevis izdeldēšu cilvēkus un lopus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Un Ēģiptes zeme taps postā un par tuksnesi, un tie samanīs, ka Es esmu Tas Kungs, tāpēc ka viņš sacījis: tā upe ir mana, es to esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Tad nu redzi, Es celšos pret tevi un pret tavām upēm, un darīšu Ēģiptes zemi par tukšu posta vietu, no Migdalas līdz Ziēnei un līdz Moru zemes robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Pa viņu cilvēka kāja nestaigās, un arī lopa kāja pa viņu neies un tur nedzīvos caurus četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Jo Es Ēģiptes zemi darīšu par posta vietu starp postītām zemēm, un viņas pilsētas būs postā starp postītām pilsētām četrdesmit gadus, un Es ēģiptiešus izkaisīšu starp tautām un tos izputināšu pa valstīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Tomēr tā saka Tas Kungs Dievs: kad četrdesmit gadi būs pagalam, tad Es sapulcināšu ēģiptiešus no tām tautām, kurp tie bija izkaisīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Un Es pārvedīšu ēģiptiešus no cietuma un tos atkal atvedīšu Patrus zemē, viņu dzimtā zemē, un tur tie būs viena maza valsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Un tā būs mazāka nekā citas valstis un necelsies vairs pār tām tautām, jo Es viņus mazināšu, lai nevalda vairs pār tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Un Israēla namam tie vairs nebūs par atspaidu, atgādinādami noziegumu, kad pēc viņiem skatās; bet tie samanīs, ka Es esmu Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Un notikās divdesmit septītā gadā, pirmā mēnesī, pirmā mēneša dienā, tad Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Cilvēka bērns! Nebukadnecars, Bābeles ķēniņš, savam karaspēkam licis grūtu darbu darīt pret Tiru; visas galvas ir plikas un visi pleci noberzti; tomēr nedz viņam nedz viņa karaspēkam nekāda alga nav tikusi Tirus dēļ, par to grūto darbu, kas viņam pret to bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Tāpēc tā saka Tas Kungs Dievs: Nebukadnecaram, Bābeles ķēniņam, Es došu Ēģiptes zemi, un viņš aizvedīs visu viņas pulku un laupīs viņas laupījumu un mantos viņas mantu, un tā būs tā alga viņa karaspēkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Par darba algu Es tam atdošu Ēģiptes zemi, par to darbu, ko tie Man darījuši, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Tai dienā Es likšu izplaukt Israēla nama ragam, un atdarīšu tev muti viņu vidū; un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Cilvēka bērns, sludini un saki: tā saka Tas Kungs Dievs: kauciet: Ak vai, tai dienai!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Jo tā diena ir tuvu, tiešām Tā Kunga diena ir tuvu, diena tumši apmākusies, pagānu laiks ir klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Un zobens nāks Ēģiptes zemē, un Moru zemē būs lielas sāpes, kad kautie kritīs Ēģiptes zemē, un viņas pulki taps aizvesti, un viņas pamati taps nolauzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Moru zeme un Libija un Lidija un visādi ļaudis un Kubs un tās derības zemes bērni kritīs līdz ar viņiem caur zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Tā saka Tas Kungs: tiešām, Ēģiptes palīgi kritīs, un viņas lepnais stiprums taps nogāzts, no Migdolas līdz Ziēnei tie tur kritīs caur zobenu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Un tie taps postīti vidū starp postītām zemēm, un viņu pilsētas būs starp postītām pilsētām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Un tie samanīs, ka Es esmu Tas Kungs, kad Es uguni kuršu Ēģiptes zemē, un visi viņas palīgi taps satriekti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Tai dienā no Manis izies vēstneši ar laivām, iztrūcināt Moru zemi, kas droši dzīvo, un pie tiem būs lielas bēdas, tā kā Ēģiptes dienā, jo redzi, (tie) nāk!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Tā saka Tas Kungs Dievs: tiešām, Es nobeigšu Ēģiptes pulkus caur Nebukadnecara, Bābeles ķēniņa, roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Šis un viņa ļaudis līdz ar viņu, tie visbriesmīgākie starp tautām, taps atvesti, postīt zemi, un izvilks savus zobenus pret Ēģipti un piepildīs zemi ar nokautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Un Es upes darīšu sausas un zemi pārdošu tiem nikniem rokā, un zemi un kas tur ir, Es izpostīšu caur svešinieku roku; Es Tas Kungs to esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Tā saka Tas Kungs Dievs: un Es izdeldēšu tos elkus un darīšu galu Nofas(Memfisas) dievekļiem, un valdnieka vairs nebūs Ēģiptes zemē; un Es sūtīšu izbailes pār Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Un Es izpostīšu Patrus zemi, un kuršu uguni Coanā, un turēšu tiesu Noā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Un Es izgāzīšu Savu bardzību pār Sinu, Ēģiptes stiprumu, un izdeldēšu tos pulkus Noā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Un iededzināšu uguni Ēģiptes zemē; Sina cietīs lielas sāpes, un No taps sašķelta, un Nofa dienas vidū taps spaidīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Avenas un Pibozetes jaunekļi kritīs caur zobenu, un pašas aizies cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Un Takvanesā gaisma taps aptumšota, kad Es Ēģiptes jūgu tur salauzīšu un viņas lepno stiprumu tur nobeigšu; mākonis viņu apklās, un viņas meitas ies cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Tā Es turēšu tiesu Ēģiptes zemē, lai tie atzīst, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Un vienpadsmitā gadā, pirmā mēnesī, septītā mēneša dienā Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Cilvēka bērns! Faraona, Ēģiptes ķēniņa, elkoni Es esmu satriecis, un redzi, to nesasies, plāksteri neuzliks, ar autiem neaptīs, un tas vairs neatspirgs, ka varētu zobenu turēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Tāpēc tā saka Tas Kungs Dievs: redzi, Es celšos pret Faraonu, Ēģiptes ķēniņu, un satriekšu viņa elkoņus, to stipro kā to satriekto, un Es viņa zobenam likšu izkrist no viņa rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Un Es ēģiptiešus izkaisīšu starp tautām un tos izputināšu pa zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Un Es stiprināšu Bābeles ķēniņa elkoņus, un Savu zobenu došu viņa rokā, bet Faraona elkoņus Es satriekšu, ka tam viņa priekšā būs vaidēt, tā kā ievainots vaid.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Tiešām, Es stiprināšu Bābeles ķēniņa elkoņus, bet Faraona elkoņi nogurs, un tie samanīs, ka Es esmu Tas Kungs, kad Es Savu zobenu došu Bābeles ķēniņam rokā, un viņš to pacels pār Ēģiptes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Un Es izkaisīšu ēģiptiešus starp tautām un tos izputināšu pa zemēm, lai tie atzīst, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Un vienpadsmitā gadā, trešā mēnesī, pirmā mēneša dienā Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Cilvēka bērns, runā uz Faraonu, Ēģiptes ķēniņu, un uz viņa ļaužu pulku: kam tu esi līdzīgs savā augstībā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Redzi, Asurs bija ciedra koks uz Lībanus, skaistiem zariem un kuplām lapām un slaiku augumu, un viņa galotne bija iekš mākoņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Ūdens viņu darīja lielu, un jūras dziļumi viņu paaugstināja, viņa upes gāja apkārt ap dārziem, un savus ūdeņus tas sūtīja pie visiem lauka kokiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Tāpēc viņa augums bija augstāks pār visiem lauka kokiem, un viņa zari vairojās un viņa zariņi plaukstot pagarinājās caur to lielo ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Visi putni apakš debess taisīja ligzdas viņa zaros, un visi lauka zvēri vedās apakš viņa zariem, un visas lielās tautas sēdēja viņa pavēnī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Tā tas bija skaists savā lielumā un savu zaru garumā, jo viņa sakne bija pie daudz ūdeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Ciedru koki Dieva dārzā viņu neaptumšoja un priedes viņa zariem nelīdzinājās, un kļavu koki nebija tādi kā viņa zariņi, neviens koks Dieva dārzā viņam nelīdzinājās skaistumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Es viņu biju darījis tik skaistu caur viņa zaru pulku, ka visi Ēdenes koki Dieva dārzā viņu apskauda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Tāpēc tā saka Tas Kungs Dievs: tādēļ ka tu tā biji cēlies garumā, un ka viņš savu galotni izstiepis līdz padebešiem, un viņa sirds sava augstuma dēļ lepojās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Tāpēc Es viņu nodevu rokā tautu varenajam, ar viņu darīt pēc patikšanas; Es viņu izdzinu viņa bezdievības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Un sveši, tie tautu briesmīgākie, viņu nocirta un to nometa, viņa zari krita uz kalniem un pa visām ielejām, un viņa zariņi tapa nogāzti visās zemes gravās. Un visas zemes tautas aizgāja no viņa pavēņa un viņu atstāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Visi putni apakš debess nolaidās uz viņa, un visi lauka zvēri bija uz viņa zariem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Lai nekādi pie ūdens dēstīti koki nelepojās sava auguma pēc, un savu galotni nestiepj līdz mākoņiem, un nekādi no ūdens slacināti koki nepaļaujas uz sev pašiem sava augstuma dēļ; jo tie visi nāvei ir nodoti uz zemes apakšu, cilvēka bērnu vidū, pie tiem, kas grimst bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Tā saka Tas Kungs Dievs: tai dienā, kad tas ellē nogrima, tad Es cēlu bēdas, Es viņa dēļ apklāju dziļumus un aizturēju viņa upes, un tie varenie ūdeņi apstājās, un Es darīju, ka Lībanus viņa dēļ sērojās, un visi lauka koki nokalta viņa dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'No viņa kritiena trokšņa Es pagānus darīju drebam, kad Es viņu ellē nogrūdu pie tiem, kas grimst bedrē. Un visi Ēdenes koki, tie izlasītie un labākie uz Lībanus, visi no ūdens slacinātie koki iepriecinājās zemes apakšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Tie nogrima arīdzan līdz ar viņu ellē pie tiem zobena nokautiem, kas kā viņa palīgi bija sēdējuši viņa pavēnī starp tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Kam starp Ēdenes kokiem tu tad esi līdzīgs godā un augstumā? Arī tu tapsi nogrūsts ar Ēdenes kokiem zemes apakšā, tu gulēsi vidū starp neapgraizītiem, pie zobenu nokautiem. Tas ir Faraons un viss viņa ļaužu pulks, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Un divpadsmitā gadā, divpadsmitā mēnesī pirmā mēneša dienā Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Cilvēka bērns, sāc raudu dziesmu par Faraonu, Ēģiptes ķēniņu, un saki uz viņu: ak tautu lauva, tu esi pagalam! Un tu biji kā jūras zvērs jūrā un izlēci savās upēs un sajauci ūdeņus ar savām kājām un samini upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Tā saka Tas Kungs Dievs: Es tādēļ Savu tīklu izplētīšu pār tevi daudz tautu sapulcē, kas tevi izvilks Manā tīklā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Tad Es tevi metīšu uz zemi, Es tevi nosviedīšu uz lauku un visiem putniem apakš debess Es likšu mist uz tevis un visiem zvēriem virs zemes no tevis pieēsties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Un metīšu tavu maitu uz kalniem un pildīšu tās ielejas ar tavām miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Un Es dzirdināšu zemi ar tām asinīm, kas no tevis izplūst līdz kalniem, un upes no tevis taps pildītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Un kad Es tevi izdzēsīšu, tad Es apsegšu debesi un aptumšošu viņas zvaigznes, sauli Es apklāšu ar mākoņiem, un mēneša gaišums vairs nespīdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Visus spožos debess spīdekļus Es tevis dēļ aptumšošu un vedīšu tumsību pār tavu zemi, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Es arī darīšu skumīgas daudz tautu sirdis, kad Es tavu mocību iznesīšu starp tautām, tanīs valstīs, ko tu nepazīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Un Es darīšu, ka daudz tautas par tevi iztrūcinājās, un viņu ķēniņiem mati celsies stāvu par tevi, kad Es cilāšu Savu zobenu viņu priekšā, un tie drebēs ik acumirkli ikviens par savu dvēseli tai dienā, kad tu kritīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Jo tā saka Tas Kungs Dievs: Bābeles ķēniņa zobens nāks pār tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Un Es tavu pulku nogāzīšu caur vareno zobeniem, tie visi ir tie visbriesmīgākie starp tautām, tie izpostīs Ēģiptes lepnību, un viss viņas pulks taps izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Un visus viņas lopus Es izdeldēšu pie tā lielā ūdens, ka cilvēka kāja to vairs nesajauks, ir lopu nags to nesajauks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Tad Es viņu ūdeņus darīšu skaidrus un viņu upēm likšu tecēt kā eļļai, saka Tas Kungs Dievs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Kad Es Ēģipti būšu darījis par posta vietu, un zeme no savas pilnības būs palikusi tukša, kad Es visus viņas iedzīvotājus būšu kāvis, - tad samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Šī ir tā raudu dziesma, un tā jādzied; tautu meitas šo raudu dziesmu dziedās; par Ēģipti un par visu viņas ļaužu pulku tās dziedās šo raudu dziesmu, saka Tas Kungs Dievs. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Un divpadsmitā gadā, piecpadsmitā mēneša dienā Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Cilvēka bērns, žēlojies par Ēģiptes ļaužu pulku un nogremdē to līdz ar tām lepno tautu meitām zemes apakšā pie tiem, kas grimuši dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Par ko tu nu esi skaistāka? Kāp zemē un apgūlies pie neapgraizītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Tie kritīs starp zobena nokautiem. Viņa ir nodota zobenam; aizraujiet viņu ar visu viņas ļaužu pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Tie varoņu varenie un viņas palīgi ar viņu runās elles vidū: tie ir nogrimuši, tie guļ starp neapgraizītiem un zobena nokautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tur ir Asurs ar visu savu ļaužu pulku, viņu kapi ir visapkārt ap viņu; tie visi nokauti, caur zobenu krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Viņa kaps ir tai visdziļākā bedrē, un viņa ļaužu pulks ir visapkārt ap viņa kapu; visi nokauti, caur zobenu krituši, kas briesmas bija cēluši dzīvo zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tur ir Elams ar visu savu ļaužu pulku visapkārt ap viņa kapu; tie visi nokauti, caur zobenu krituši; tie grimuši neapgraizīti zemes apakšā, kas briesmas bija cēluši dzīvo zemē, tie nes savu kaunu pie tiem, kas grimuši dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Pie nokautiem cisas sataisītas viņam un visam viņa ļaužu pulkam, viņu kapi ir visapkārt ap viņu; tie visi, neapgraizīti, caur zobenu ir nokauti; tāpēc ka tie briesmas cēluši dzīvo zemē, tie nes savu kaunu pie tiem, kas grimuši dziļumā, - viņš guldināts nokauto vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tur ir Mešehs un Tūbals ar visu savu ļaužu pulku, visapkārt ap viņu ir viņu kapi, tie visi, neapgraizīti, ir nokauti ar zobenu, tāpēc ka bija briesmas cēluši dzīvo zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Tie neguļ pie tiem kritušiem neapgraizīto varoņiem, kas ellē nogrimuši ar savām bruņām, kam zobeni likti apakš galvām; viņu noziegumi nākuši pār viņu kauliem, tāpēc ka bija varoņi par briesmām dzīvo zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Arī tu tapsi satriekts neapgraizītu vidū un gulēsi pie zobena nokautiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tur ir Edoms, viņa ķēniņi un visi viņa lielkungi, kas ar savu varoņu godu ir likti pie zobena nokautiem; tie guļ pie neapgraizītiem un pie tiem, kas grimuši dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tur ir visi ziemeļa valdnieki un visi Sidonieši, kas nogrimuši pie nokautiem un kaunā likti, lai gan ar savu varu bijuši par iztrūcināšanu, un tie guļ neapgraizīti pie tiem, kas zobena nokauti, un nes savu kaunu pie tiem, kas nogrimuši dziļumā. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Faraons tos redzēs un iepriecināsies ar visu savu ļaužu pulku; ar zobenu ir nokauti, Faraons un viss viņa karaspēks, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Jo Es viņam esmu licis briesmas celt dzīvo zemē, un viņš ir nolikts neapgraizīto vidū pie tiem, kas zobena nokauti, Faraons ar visu savu ļaužu pulku, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Cilvēka bērns, runā uz savu ļaužu bērniem un saki uz tiem: kad Es zobenu vedu pār kādu zemi, un tās zemes ļaudis ņem vienu vīru no savām robežām un to ieceļ sev par sargu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Un viņš redz zobenu pār to zemi nākam un pūš ar bazūni un pamāca tos ļaudis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Un ja kas to bazūnes skaņu dzirdēt dzird un neļaujas pamācīties, un zobens nāk un ņem viņu nost, - šī asinis lai ir uz viņa galvas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Viņš dzirdēja bazūnes skaņu, bet nelikās pamācīties, viņa asinis ir uz viņa. Bet kas ļaujas pamācīties, tas izglābs savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Bet kad tas sargs redz zobenu nākam un nepūš ar bazūni, tā ka tie ļaudis netiek pamācīti, un zobens nāk un ņem no tiem kādu dvēseli nost: tas gan savā noziegumā ir noņemts, bet viņa asinis Es prasīšu no tā sarga rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Tu tad cilvēka bērns, Es tevi esmu licis par sargu Israēla namam, ka tev nu no Manas mutes to vārdu būs klausīt un tos pamācīt no Manas puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Kad Es uz bezdievīgo saku. bezdievīgais, tu mirdams mirsi, un tu nemāci bezdievīgo, lai atgriežas no sava ļaunā ceļa, tad bezdievīgais nomirs savā noziegumā, bet viņa asinis Es prasīšu no tavas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Bet ja tu bezdievīgo pamāci, lai atgriežas no sava ceļa, un viņš neatgriežas no sava ceļa, tad viņš mirs savā noziegumā, bet tu savu dvēseli esi izglābis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Tādēļ, cilvēka bērns, saki uz Israēla namu: jūs runājiet tā un sakāt: mūsu pārkāpumi un mūsu grēki ir uz mums, un mēs iekš tiem ejam bojā, kā tad mēs varam dzīvot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Saki uz tiem: tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, Man nepatīk bezdievīgā nāve, bet ka bezdievīgais atgriežas no sava ceļa un dzīvo. Atgriežaties, atgriežaties no saviem ļauniem ceļiem. Jo kāpēc jūs gribat mirt, jūs no Israēla nama?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Tu tad, cilvēka bērns, saki uz savu ļaužu bērniem: taisno taisnība neizglābs viņa pārkāpšanas dienā, un bezdievīgais savas bezdievības dēļ neies bojā, kad tas atgriežas no savas bezdievības. Un pats taisnais nevar dzīvot caur savu taisnību, kad viņš apgrēkojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Kad Es uz taisno saku, ka tas dzīvot dzīvos, un tas paļaujas uz savu taisnību un dara nepareizi, tad visa viņa taisnība netaps pieminēta, bet viņš mirs tai netaisnībā, ko viņš dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Un kad Es uz bezdievīgo saku: tu mirdams mirsi, un tas atgriežas no saviem grēkiem un dara tiesu un taisnību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Tā ka bezdievīgais ķīlu atdod, laupījumu maksā un staigā dzīvības likumos, nevienam nedarīdams nepareizi, - tad tas dzīvot dzīvos un nemirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Visi viņa grēki, ko viņš darījis, viņam netaps pieminēti; viņš darījis tiesu un taisnību, dzīvot viņš dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Tomēr tavu ļaužu bērni saka: Tā Kunga ceļš nav taisns! Bet viņu ceļš nav taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Kad taisnais nogriežas no savas taisnības un dara nepareizi, tad viņš caur to mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Un kad bezdievīgais nogriežas no savas bezdievības un dara tiesu un taisnību, tad viņš caur to dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Bet jūs sakāt: Tā Kunga ceļš nav pareizs. Es jūs tiesāšu, ikvienu pēc viņa ceļiem, ak Israēla nams! -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Un notikās divpadsmitā gadā pēc mūsu aizvešanas, desmitā mēnesī, piektā mēneša dienā, tad viens pie manis atnāca, kas no Jeruzālemes bija izglābies, un sacīja: tā pilsēta ir izkauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Bet Tā Kunga roka vakarā, iepriekš tā izglābtā atnākšanas, bija nākusi pār mani un atvērusi manu muti, pirms šis rītā pie manis nāca, un mana mute palika atvērta, un es nebiju vairs mēms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Tad Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Cilvēka bērns! Tie, kas viņās posta vietās dzīvo Israēla zemē, runā un saka: Ābrahāms bija viens vienīgs un iemantoja to zemi, bet mūsu ir daudzi, tā zeme mums ir dota par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Tādēļ saki uz tiem: tā saka Tas Kungs Dievs: jūs ēdat asinis un paceļat savas acis uz saviem elkiem un izlejat asinis, - un jūs to zemi gribat paturēt par mantību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Jūs stāvat uz savu zobenu, jūs darāt negantību un apgānāt cits cita sievu, un jūs to zemi gribat paturēt par mantību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tā tev uz viņiem būs sacīt: tā saka Tas Kungs Dievs: tik tiešām kā Es dzīvoju, tie, kas tais posta vietās dzīvo, kritīs caur zobenu, un to, kas uz lauka, Es nodošu zvēriem par barību, un tie, kas stiprās vietās un alās, mirs caur mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Un to zemi Es darīšu par posta vietu un tuksnesi, un viņas lepnais stiprums beigsies, un Israēla kalni būs postā, ka tur neviens pāri neies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Tad tie samanīs, ka Es esmu Tas Kungs, kad Es to zemi būšu darījis par posta vietu un par tuksnesi visas viņu negantības dēļ, ko tie darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Un tu, cilvēka bērns, tavu ļaužu bērni runā pret tevi istabās un nama durvīs, un viens runā ar otru, ikviens ar savu brāli, un saka: nāciet jel, dzirdēsim, kas tas tāds vārds, kas no Tā Kunga nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Un tie nāks pie tevis, tā kā ļaudis mēdz nākt, un sēž tavā priekšā kā Mani ļaudis un klausa tavus vārdus, bet tos nedara; jo tie ir mīlīgi ar savu muti, bet viņu sirds dzenās mantai pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Un redzi! Tu tiem esi kā jauka dziesmiņa, kā skaista balss, kas labi skan, tādēļ tie klausa tavus vārdus, bet tos nedara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Bet kad nāks, - un redzi, nāk! - Tad tie samanīs, ka pravietis ir bijis viņu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Cilvēka bērns, sludini pret Israēla ganiem, sludini un saki uz tiem, uz tiem ganiem: tā saka Tas Kungs Dievs: Ak vai, Israēla ganiem, kas sevi pašus gana! Vai ganiem nebūs avis ganīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Jūs ēdat tos taukus un apģērbjaties ar to vilnu, jūs kaujat to baroto, bet tās avis jūs neganiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Tās vājās jūs nespēcinājāt, un to neveselo jūs nedziedinājāt, un to satriekto jūs nesasienat, un to aizdzīto jūs nenesāt atpakaļ un to pazudušo jūs nemeklējāt, bet jūs valdāt pār tiem bargi un ar grūtumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Tā tās izklīdušas, tāpēc ka gana nebija, un paliek par barību visiem lauka zvēriem un izklīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Manas avis maldās pa visiem kalniem un pa visiem augstiem pakalniem, Manas avis izklīdušas pa visu zemes virsu, un nav neviena, kas pēc tām skatās, un neviena, kas tās meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Tādēļ, gani, klausiet Tā Kunga vārdu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, tāpēc ka Manas avis ir tapušas par laupījumu, un Manas avis visiem lauka zvēriem par barību, tāpēc ka gana nebija, un ka Mani gani nelūko pēc Manām avīm, bet tie gani gana sevi pašus, bet Manas avis tie negana, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Tādēļ, gani, klausiet Tā Kunga vārdu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Tā saka Tas Kungs Dievs: redzi, Es celšos pret tiem ganiem, un prasīšu Savas avis no viņu rokas un darīšu, ka tie Manas avis vairs neganīs, un tie gani vairs neganīs sevi pašus. Un Es izraušu Savas avis no viņu mutes, ka tās tiem vairs nebūs par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Jo tā saka Tas Kungs Dievs: redzi, Es, tiešām Es vaicāšu pēc Savām avīm un tās meklēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Jo kā gans meklē savu ganāmo pulku tai dienā, kad viņš ir savu izklīdušo avju vidū, tā Es meklēšu Savas avis un tās izpestīšu no visām tām vietām, kurp tās noklīdušas tumšā un vētrainā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Un Es tās izvedīšu no tām tautām un tās sapulcināšu no tām zemēm un tās pārvedīšu viņu pašu zemē un tās ganīšu uz Israēla kalniem, pa tām lejām un pa visām vietām, kur tai zemē mīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Es tās ganīšu labā ganībā, un viņu mitekļi būs uz Israēla augstiem kalniem; tur tie apgulsies labos mitekļos un ganīsies taukā ganībā uz Israēla kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Es pats ganīšu Savas avis un Es pats tās guldināšu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Pazudušo Es gribu meklēt un aizdzīto Es gribu nest atpakaļ un satriekto Es gribu sasiet un vārguli Es gribu spēcināt, bet tauko un stipro Es gribu izdeldēt; Es tās ganīšu ar taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Jūs, Manas avis! - Tas Kungs Dievs saka tā: redzi, Es tiesāšu starp avi un avi, starp auniem un āžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Vai tas jums vēl ir maz, ka jūs noganiet to labo ganību? Vai gribat arī savu atlikušo ganību samīdīt ar savām kājām? - Un ka jūs dzerat no skaidra ūdens, - vai to atlikušo gribat sajaukt ar savām kājām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Vai tad Manām avīm būs ēst, kas no jūsu kājām ir samīts, un dzert, kas no jūsu kājām ir sajaukts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Tādēļ Tas Kungs Dievs tā saka uz tiem: redzi, Es, tiešām Es tiesāšu starp tām taukām avīm un tām liesām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Tāpēc ka jūs visas vājās stumdiet ar sāniem un ar pleciem un badiet ar saviem ragiem, kamēr jūs tās esat izdzinuši ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Tāpēc Es Savas avis gribu pestīt, lai tās vairs nav par laupījumu, un Es tiesāšu starp avi un avi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Un Es par tiem iecelšu vienu vienīgu ganu, kas lai tās gana, proti Savu kalpu Dāvidu; tas tās ganīs, un tas tām būs par ganu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Un Es Tas Kungs tiem būšu par Dievu, un mans kalps Dāvids būs tas valdnieks viņu vidū. Es, Tas Kungs, to esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Un Es ar tiem darīšu miera derību, un izdeldēšu ļaunos zvērus no zemes, un tie dzīvos tuksnesī bez bailēm un gulēs mežos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Un Es darīšu viņus un tās vietas ap Manu kalnu par svētību, un Es došu lietu savā laikā; tas būs svētības lietus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Un koki uz lauka dos savus augļus, un zeme dos savus augļus, un tie būs bez bailēm savā zemē un samanīs, ka Es esmu Tas Kungs, kad Es būšu salauzis viņu jūga kokus un tos izglābis no viņu kalpinātāju rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Un tie nebūs vairs pagāniem par laupījumu, un zvēri virs zemes tos vairs neaprīs, bet tie dzīvos droši, un neviens tos neizbiedēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Un Es tiem audzināšu stādu par slavu, un tie tai zemē vairs netaps aizgrābti caur badu un nenesīs vairs apsmieklu no pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Un tie samanīs, ka Es, Tas Kungs, viņu Dievs, esmu ar viņiem, un tie, Israēla nams, ir Mani ļaudis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Un jūs esat Manas avis, Manas ganāmās avis; cilvēki jūs esat, Es esmu jūsu Dievs, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Atkal Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Cilvēka bērns, griez savu vaigu pret Seīra kalniem un sludini pret tiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Un saki uz tiem: tā saka Tas Kungs Dievs: redzi, Es celšos pret tevi, Seīra kalns, un Es izstiepšu Savu roku pret tevi un tevi darīšu par postažu un tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Es tavas pilsētas darīšu par gruvešiem, un tu tapsi par postažu un samanīsi, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Tādēļ ka tev bija mūžīgs ienaids, un tu Israēla bērnus esi aizdzinis caur zobena varu viņu nelaimes laikā, viņu gala nozieguma laikā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Tādēļ, tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, Es tevi darīšu par asinīm, un asinis tevi vajās; tāpēc ka tu asinis neesi ienīdējis, tad arī asinis tevi vajās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Un Es darīšu Seīra kalnu par tuksnesi un postažu, un no viņa izdeldēšu, kas tur iet un nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Un Es viņa kalnus piepildīšu ar viņa nokautiem; uz taviem pakalniem un tavās ielejās un visās tavās gravās gulēs zobena nokautie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Es tevi darīšu par mūžīgu postažu, un tavās pilsētās nedzīvos; tā jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Tādēļ ka tu saki: šīs divas tautas un šīs divas valstis man tiks rokā, un mēs tās gribam iemantot, jebšu Tas Kungs pats tur būtu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Tādēļ, tik tiešām kā Es dzīvoju, saka Tas Kungs Dievs, Es darīšu pēc tavas bardzības un pēc tavas skaudības, kā tu savā ienaidā pret tiem esi turējies, un Es Sevi tiem darīšu zināmu, kad Es tevi sodīšu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Un tu samanīsi, ka Es, Tas Kungs, esmu dzirdējis visas tavas zaimošanas, ko tu pret Israēla kalniem esi runājis un sacījis: tie ir postīti, tie mums ir doti, ka tos aprijam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Tā jūs ar savu muti pret mani esat lielījušies un savus vārdus pret mani vairojuši, - Es to esmu dzirdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Tā saka Tas Kungs Dievs: Es tevi darīšu par posta vietu, tā ka visa zeme priecāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Tā kā tu esi priecājies par Manu mantības tiesu, Israēla namu, tāpēc ka tas ir postīts, tāpat Es tev darīšu. Seīra kalni un viss Edoms taps visnotaļ par postažu, un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Un tu cilvēka bērns, sludini par Israēla kalniem un saki: Israēla kalni, klausiet Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Tā saka Tas Kungs Dievs: tādēļ ka ienaidnieks par jums saka: redzi, tie mūžīgie kalni mums ir tikuši par mantību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Tādēļ sludini un saki: tā saka Tas Kungs Dievs: Tāpēc ka jūs visapkārt esat postīti un aprīti, ka jūs tiem atlikušiem pagāniem esat par mantību un esat nākuši ļaužu mēlēs un valodās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Tāpēc, Israēla kalni, klausiet Tā Kunga Dieva vārdu. Tā saka Tas Kungs Dievs uz kalniem un pakalniem, gravām un ielejām, tukšām posta vietām un atstātām pilsētām, kas ir palikušas par laupījumu un apsmieklu visām atlikušām tautām visapkārt, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Tāpēc tā saka Tas Kungs Dievs: tiešām, Es Sava karstuma ugunī runāju pret tām atlikušām tautām un pret visu Edomu, kas Manu zemi sev ņēmuši par mantību ar visas sirds prieku, ar lielu nicināšanu, to izpostīt un aplaupīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Tāpēc sludini Israēla zemei un saki uz kalniem un pakalniem, gravām un ielejām: tā saka Tas Kungs Dievs: redzi, Es Savā karstumā un Savā bardzībā esmu runājis, tāpēc ka jums apsmiekls bija jānes no pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Tādēļ Tas Kungs Dievs tā saka: Es, Es paceļu Savu roku, tiešām, tām tautām, kas visapkārt ap jums, pašām būs nest savu apsmieklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Bet jūs, jūs Israēla kalni, atkal zaļosiet un nesīsiet savus augļus Maniem Israēla ļaudīm, jo īsā laikā tie pārnāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Jo redzi, Es būšu pie jums, un Es skatīšos uz jums, un jūs tapsiet kopti un apsēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Un Es vairošu pie jums cilvēkus, visu Israēla namu visnotaļ: un pilsētās dzīvos un postītas vietas uztaisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Un Es pie jums vairošu cilvēkus un lopus, tie vairosies un vaislosies, un Es iekš jums likšu dzīvot kā jūsu vecos laikos, un Es jums darīšu vairāk labuma nekā jūsu senajos laikos, un jūs samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Un Es pie jums atvedīšu cilvēkus, Savus Israēla ļaudis, tie tevi iemantos, un tu tiem būsi par mantību un tiem vairs nelaupīsi bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Tā saka Tas Kungs Dievs: tādēļ ka uz jums saka: tu esi cilvēku rijēja un savu ļaužu bērnu aplaupītāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Tādēļ tu cilvēkus vairs nerīsi un saviem ļaudīm vairs nelaupīsi bērnus, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Un Es tev vairs nelikšu dzirdēt pagānu apsmieklu, un tu nenesīsi vairs tautu negodu un saviem ļaudīm vairs nelaupīsi bērnus, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Atkal Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Cilvēka bērns, Israēla nams, kad tie savā zemē dzīvoja, tad tie to sagānīja ar savu ceļu un ar saviem darbiem; viņu ceļš bija Manā priekšā kā sārņainas sievas nešķīstība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Tādēļ Es Savu bardzību pār viņiem izgāzu to asiņu dēļ, ko tie tai zemē bija izlējuši, un viņu elku dēļ ar ko to bija sagānījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Un Es tos izkaisīju starp tautām, un tie tapa izputināti pa valstīm, Es tos sodīju pēc viņu ceļa un pēc viņu darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Kad tie nu pie tām tautām nonāca, kurp tie bija gājuši, tad tie sagānīja manu svēto vārdu, tāpēc ka no tiem tapa sacīts: šie ir Tā Kunga ļaudis un izgājuši no viņa zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Bet Man ir žēl Sava svētā Vārda, ko Israēla bērni sagānījuši starp tām tautām, kur tie bija nākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Tāpēc saki uz Israēla namu: tā saka Tas Kungs Dievs: Es to nedaru jūsu dēļ, Israēla nams, bet Sava svētā Vārda dēļ, ko jūs esat sagānījuši starp tām tautām, kur esat nākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Jo Es pagodināšu Savu lielo Vārdu, kas starp pagāniem ir sagānīts, ko jūs viņu vidū esat sagānījuši. Un pagāni samanīs, ka Es esmu Tas Kungs, saka Tas Kungs Dievs, kad Es pie jums svēts parādīšos priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Jo Es jūs atvedīšu no tām tautām un jūs sapulcināšu no visām valstīm, un Es jūs atvedīšu atkal jūsu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Un Es uz jums slacināšu šķīstu ūdeni, ka topat šķīsti; no visas jūsu nešķīstības un no visiem jūsu elkiem Es jūs šķīstīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Un Es jums došu jaunu sirdi un došu jums jaunu garu, un atņemšu to akmens sirdi no jūsu miesām un došu jums miesīgu sirdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Un Es jums došu Savu Garu un darīšu, ka jūs staigāsiet Manos likumos un sargāsiet un darīsiet Manas tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Un jūs dzīvosiet tai zemē, ko Es jūsu tēviem esmu devis, un jūs Man būsiet par ļaudīm, un Es jums būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Un Es jūs atpestīšu no visas jūsu nešķīstības un aicināšu labību un to vairošu un nevedīšu pār jums badu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Un Es vairošu koku augļus un tīruma augļus, ka jūs bada dēļ starp tautām vairs netopat nicināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Tad jūs pieminēsiet savus ļaunos ceļus un savus nelabos darbus un būsiet paši sev riebīgi par saviem noziegumiem un par savām negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Un to Es nedaru jūsu dēļ, saka Tas Kungs Dievs, to jums būs zināt. Kaunaties un nosarkstiet savu ceļu dēļ, jūs, Israēla nams!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Tā saka Tas Kungs Dievs: tai dienā, kad Es jūs šķīstīšu no visas jūsu nešķīstības, tad Es pilsētās likšu dzīvot, un postažas taps uztaisītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Un tā tukšā zeme atkal taps apkopta, kur posts bija priekš ikviena acīm, kas gāja garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Un sacīs: šī zeme, kas bija postā, ir palikusi kā Ēdenes dārzs, un tās iztukšotās un izpostītās un sagruvušās pilsētas ir stipras un apdzīvotas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Tad tās tautas, kas atlikušas visapkārt ap jums, samanīs, ka Es, Tas Kungs, uztaisu sagruvušas vietas un apdēstu, kas ir izpostīts; Es, Tas Kungs, to esmu runājis, un Es to darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Tā saka Tas Kungs Dievs: Es ļaušos atkal pielūgties no Israēla nama, ka Es tiem parādos; Es vairošu tos ļaudis kā ganāmu pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Tā kā tās svētās avis, kā Jeruzālemes avis savos svētkos, tā būs tās tukšās vietas ar cilvēkiem kā ar ganāmu pulku pilnas, un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Tā Kunga roka nāca pār mani un mani izveda caur Tā Kunga Garu, un mani nolika ielejas vidū; tā bija pilna kaulu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Un Viņš mani veda gar tiem visapkārt, un redzi, tur bija ļoti daudz tai ielejā, un redzi, tie bija ļoti izkaltuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Un Viņš uz mani sacīja: cilvēka bērns, vai šie kauli taps dzīvi? Un es sacīju: Kungs Dievs, Tu to zini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Tad Viņš uz mani sacīja: sludini par šiem kauliem un saki uz tiem: jūs sakaltušie kauli, klausiet Tā Kunga vārdu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Tā saka Tas Kungs Dievs uz šiem kauliem: redzi, Es vedīšu garu iekš jums, un jūs tapsiet dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Un Es likšu dzīslas uz jums un likšu miesai pār jums augt un jums pārvilkšu ādu un došu iekš jums garu, un jūs tapsiet dzīvi un samanīsiet, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Tad es tā sludināju, kā man bija pavēlēts, un tur brakšķēja, kad es sludināju, un redzi, tur kustējās, un tie kauli radās kopā, kauls pie kaula.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Un es skatījos, un redzi, dzīslas radās pār tiem un miesa cēlās, un āda pār tiem pārvilkās, bet gara iekš tiem nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Un Viņš uz mani sacīja: sludini par to garu, cilvēka bērns, sludini un saki uz to garu: tā saka Tas Kungs Dievs: gars, nāc no tiem četriem vējiem un pūt uz tiem nokautiem, ka tie top dzīvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Un es sludināju, kā Viņš man bija pavēlējis. Tad gars nāca iekš viņiem, un tie tapa dzīvi un stājās uz savām kājām, ļoti ļoti liels pulks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Tad Viņš uz mani sacīja: cilvēka bērns! Šie kauli ir viss Israēla nams; redzi, tie saka: mūsu kauli sakaltuši un mūsu cerība iznīkusi, un mēs esam beigti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Tāpēc sludini un saki uz tiem: tā saka Tas Kungs Dievs: redzi, Es atvēršu jūsu kapus un jūs izvedīšu no jūsu kapiem, Mani ļaudis, un Es jūs vedīšu uz Israēla zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Un jūs samanīsiet, ka Es esmu Tas Kungs, kad Es jūsu kapus būšu atvēris un jūs izvedis no jūsu kapiem, ak Mani ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Un Es došu Savu garu iekš jums, un jūs dzīvosiet, un Es jūs ielikšu jūsu zemē, un jūs samanīsiet, ka Es Tas Kungs to esmu runājis un darījis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Atkal Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Tu tad, cilvēka bērns, ņem sev galdu un raksti uz to: priekš Jūda un priekš Israēla bērniem, viņa biedriem. Un ņem vēl vienu galdu un raksti uz to: priekš Jāzepa, Efraīma un visa Israēla nama, viņa biedru, galds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Un tad saliec vienu pie otra par vienu galdu, ka tie top viens tavā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Un kad tavu ļaužu bērni uz tevi runās un sacīs: vai tu mums negribi sacīt, kas tas tev ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Tad runā uz tiem: tā saka Tas Kungs Dievs: redzi, Es ņemšu Jāzepa galdu, kas ir bijis Efraīma, un Israēla cilšu, viņu biedru, rokā un tos salikšu ar Jūda galdu un tos darīšu par vienu vienīgu galdu, un tie taps par vienu Manā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Lai tad tie galdi, uz kuriem tu būsi rakstījis, ir tavā rokā priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Un tu runā uz tiem: tā saka Tas Kungs Dievs: redzi, Es izvedīšu Israēla bērnus no to pagānu vidus, kurp tie aizgājuši, un tos sapulcināšu no visām pusēm un tos pārvedīšu viņu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Un es tos darīšu par vienu vienīgu tautu tai zemē, uz Israēla kalniem, un viens vienīgs ķēniņš būs tiem visiem par ķēniņu. Un tie nebūs vairs divas tautas un nebūs vairs dalīti divējās valstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Un tie nesagānīsies vairs ar saviem elkiem un ar savām negantībām un ar savām pārkāpšanām. Es tos atpestīšu no visām viņu mājas vietām, kur tie apgrēkojušies, un Es tos šķīstīšu: tad tie Man būs par ļaudīm, un Es tiem būšu par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Un Mans kalps Dāvids būs tiem par ķēniņu, un tiem visiem būs viens vienīgs gans, un tie staigās Manās tiesās un turēs Manus likumus un darīs pēc tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Un tie dzīvos tai zemē, ko Es Savam kalpam Jēkabam esmu devis, kur jūsu tēvi dzīvojuši. Tiešām, tie tur dzīvos līdz ar saviem bērniem un bērnu bērniem mūžīgi, un mans kalps Dāvids būs viņu valdnieks mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Un Es ar tiem darīšu miera derību, un tā būs mūžīga derība ar tiem, un Es tos iecelšu un tos vairošu un likšu Savu svēto vietu viņu vidū mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Un Mans dzīvoklis būs pie tiem, un Es tiem būšu par Dievu, un tie Man būs par ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Un pagāni samanīs, ka Es esmu Tas Kungs, kas Israēli svētī, kad Mana svētā vieta viņu vidū būs mūžīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Cilvēka bērns, griez savu vaigu pret Gogu Magoga zemē, Roša, Mešeha un Tūbala valdnieku, un sludini pret viņu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Un saki: tā saka Tas Kungs Dievs: redzi, Es celšos pret tevi, Gog, tu Roša, Mešeha un Tūbala valdnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Un Es tevi vedīšu un likšu makšķeri tavos žokļos, un tevi izvedīšu ar visu tavu karaspēku, zirgiem un jātniekiem, kas visi labi ģērbti, lielu pulku, ar krūšu bruņām un priekšturamām bruņām, kas visi nes zobenus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persieši, Moru ļaudis un Libieši viņiem līdz, tie visi ar priekšturamām bruņām un dzelzs cepurēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomers un visi viņa karavīri, Togarmas nams, kas pašā ziemeļu galā, ar visiem saviem karogiem; daudz tautu līdz ar tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Esi gatavs un taisies, tu un viss tavs pulks, kas pie tevis sapulcēts, un esi tiem par vadoni. Pēc daudz dienām tu tapsi piemeklēts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Un pēdīgā laikā tu nāksi uz to zemi, kas ir atkal atvesta no zobena un sapulcēta no daudz tautām, uz Israēla kalniem, kas bez mitēšanās tapa postīti, un tā ir izvesta no tautām, un tie visnotaļ dzīvos droši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Tad tu celsies, nāksi kā vētra, būsi kā padebesis, kas zemi apklāj, līdz ar visiem taviem karogiem, un daudz tautu tev līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Tā saka Tas Kungs Dievs: tai dienā celsies tavā sirdī padomi, un tu domāsi niknas domas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Un sacīsi: es celšos pret to neapstiprināto zemi, es nākšu pret tiem, kas dzīvo mierīgi un droši, kas dzīvo visi bez mūriem, un kam nav nedz aizšaujamo, nedz vārtu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Laupīt laupīdams un postīt postīdams, savu roku griezdams pret tām posta vietām, kur atkal dzīvo, un pret tiem ļaudīm, kas no pagāniem ir sapulcēti, kas lopus un mantu krājās un dzīvo zemes vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Zaba un Dedans un Taršiša tirgotāji un visi viņu varenie uz tevi sacīs: vai tu nāci laupīdams laupīt? Vai tu savu pulku esi sapulcinājis postīdams postīt, sudrabu un zeltu projām vest, lopus un mantu atņemt, lielu laupījumu laupīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Tādēļ sludini, cilvēka bērns, un saki uz Gogu: tā saka Tas Kungs Dievs, vai tu tai dienā, kad Mani Israēla ļaudis dzīvos droši, to nemanīsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Tad tu nāksi no savas vietas no ziemeļa gala, tu un daudz tautas tev līdz, visi, zirgu jājēji, liels pulks un varens spēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Un tu celsies pret Maniem Israēla ļaudīm kā padebesis, zemi apklāj. Tas notiks pēdīgā laikā, ka Es tevi vedīšu pret Savu zemi, lai tās tautas Mani pazīst, kad Es pie tevis, Gog, svēts parādīšos priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Tā saka Tas Kungs Dievs: tu tas esi, par ko Es pagājušos laikos esmu runājis caur Saviem kalpiem, Israēla praviešiem, kas tanīs dienās, caur daudz gadiem, sludināja, ka Es tevi vedīšu pret tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Bet notiks tai dienā, kad Gogs nāks pret Israēla zemi, saka Tas Kungs Dievs, tad Mana bargā dusmība iedegsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Un Es Savā karstumā esmu runājis un Savas dusmības ugunī, ka tai dienā liela drebēšana būs Israēla zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Tā ka Manā priekšā trīcēs zivis jūrā, un putni apakš debess un zvēri laukā un visi tārpi, kas virs zemes lien, un visi cilvēki, kas zemes virsū, un kalni gāzīsies, un kalnu gali kritīs, un visi mūri grūs pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Un Es aicināšu zobenu pret viņu uz visiem Maniem kalniem, saka Tas Kungs Dievs, brāļa zobens būs pret brāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Un Es ar tiem tiesāšos caur mēri un caur asinīm un likšu stipram lietum līt ar lielu krusu, uguni un sēru uz viņu un uz viņa karogiem un uz visām tām tautām, kas viņam līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Tā Es parādīšos liels un svēts un Sevi darīšu zināmu daudz tautu acīs, un tās atzīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Un tu, cilvēka bērns, sludini pret Gogu un saki: tā saka Tas Kungs Dievs: redzi, Es celšos pret tevi, Gog, tu Roša, Mešeha un Tūbala valdnieks!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Un Es tevi griezīšu un vadīšu un tevi atvedīšu no paša ziemeļa gala un tevi vedīšu uz Israēla kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Un Es tavu stopu izsitīšu no tavas kreisās rokas un tavām bultām likšu izkrist no tavas labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Uz Israēla kalniem tu kritīsi ar visiem saviem karogiem un ļaudīm, kas tev līdz. Visādiem plēsīgiem putniem un lauka zvēriem Es tevi došu par barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Tev būs krist uz lauka; jo Es to esmu runājis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Un Es sūtīšu uguni uz Magogu, un starp tiem, kas salās droši dzīvo, un tie samanīs, ka Es esmu Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Un Savu svēto Vārdu Es darīšu zināmu Saviem Israēla ļaudīm, un vairs neļaušu sagānīt Savu svēto Vārdu, un pagāni samanīs, ka Es esmu Tas Kungs, tas Svētais iekš Israēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Redzi, tas nāks un notiks, saka Tas Kungs Dievs; šī ir tā diena, par ko Es esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Israēla pilsētu iedzīvotāji izies un iededzinās uguni un sadedzinās tās bruņas un priekšturamās bruņas un krūšu bruņas un stopus un bultas un bozes un šķēpus, un kurs no tiem uguni septiņus gadus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Tā ka tiem malka nebūs jānes no lauka nedz jācērt mežos, bet tie kurs uguni no tiem kara rīkiem, un aplaupīs tos, kas viņus bija aplaupījuši, un postīs tos, kas viņus bija postījuši, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Un notiks tai dienā, ka Es Gogam došu kapu vietu iekš Israēla, to ieleju, kur no jūras iet pret rīta pusi, tā ka ceļa ļaudīm ceļš būs aiztaisīts; tur apraks Gogu un visu viņa pulku, un to nosauks par Goga pulka ieleju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Un Israēla nams tos apraks, lai zeme top šķīsta, veselus septiņus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Un visi zemes ļaudis raks, un tas tiem būs par slavu tai dienā, kad es būšu pagodinājies, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Un tie izvēlēs vīrus, kas bez mitēšanās zemi pārstaigā, un kapu racējus tiem līdz, kas staigā apkārt un tos zemes virsū atlikušos aprok, to (zemi) šķīstīt; pēc beigtiem septiņiem mēnešiem tie sāks meklēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Un tie pārstaigātāji ies pa to zemi, un kas cilvēka kaulu redz, tas liks zīmi pie tā, kamēr tie kapu racēji to apraks Goga pulka ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Un būs arī vienas pilsētas vārds: Amona (pulks); tā tie to zemi šķīstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Tu tad, cilvēka bērns, tā saka Tas Kungs Dievs: saki uz visiem spārnainiem putniem un uz visiem lauka zvēriem: sapulcējaties un nāciet, sakrājaties no tām apkārtējām vietām pie Mana kaujamā upura, ko Es priekš jums esmu upurējis, pie tā lielā kaujamā upura uz Israēla kalniem, un ēdat gaļu un dzerat asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Jums būs ēst gaļu no varoņiem un dzert asinis no valdniekiem virs zemes, no jēriem, no auniem un āžiem un vēršiem, kas visi Bāsanā baroti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Un jums būs ēst taukus, kamēr jūs pieēdaties, un dzert asinis, kamēr jūs piedzeraties no Mana kaujamā upura, ko Es jums esmu kāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Un jūs tapsiet pie Mana galda pieēdināti no zirgiem un jātniekiem, no varoņiem un visādiem karavīriem, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Un Es parādīšu Savu godību pagānu starpā, un visi pagāni redzēs Manu sodu, ko Es esmu turējis, un Manu roku, ko Es pie tiem esmu pielicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Un Israēla nams samanīs, ka Es esmu Tas Kungs, viņu Dievs, no tās dienas un tā joprojām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Un pagāni samanīs, ka Israēla nams savu noziegumu dēļ aizvests, tāpēc ka tie no Manis bija atkāpušies, un ka Es Savu vaigu no tiem biju apslēpis un tos biju rokā devis viņu pretiniekiem, tā ka tie visi caur zobenu krituši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Pēc viņu nešķīstības un pēc viņu pārkāpšanām Es viņiem esmu darījis un no tiem apslēpis Savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Tāpēc tā saka Tas Kungs Dievs: nu Es Jēkaba cietumniekus atkal atvedīšu un apžēlošos par visu Israēla namu, un Es atriebšos Sava svētā Vārda dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Un tie nesīs savu kaunu un visu savu pārkāpumu, ar ko tie pret Mani apgrēkojušies, kad tie savā zemē droši dzīvos, un nebūs neviena, kas viņus iztrūcina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Kad Es tos būšu atvedis no tautām un tos sapulcinājis no viņu ienaidnieku valstīm, - un Es pie tiem parādīšos svēts priekš daudz pagānu acīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Tad tie samanīs, ka Es esmu Tas Kungs, viņu Dievs, kas tos esmu licis aizvest pie pagāniem, bet tos atkal sapulcinājis viņu zemē un tur vairs neesmu atstājis neviena no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Un Es no tiem vairs neapslēpšu Savu vaigu, kad Es Savu Garu būšu izlējis pār Israēla namu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Divdesmit piektā gadā pēc mūsu aizvešanas, gada iesākumā, desmitā mēneša dienā, četrpadsmitā gadā pēc tam, kad pilsēta bija kauta, tai pašā dienā Tā Kunga roka nāca pār mani,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Un Tas Kungs mani aizveda turp; caur Dieva parādīšanām viņš mani aizveda Israēla zemē un mani nolika uz ļoti augstu kalnu, un uz tā bija kā pilsētas uztaisījums pret dienvidu pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Un kad Viņš mani turp bija aizvedis, redzi, tad tur bija viens vīrs, tā ģīmis izlikās kā no vara, un viņa rokā bija linu aukla un mērojama kārts, un viņš stāvēja vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Un tas vīrs sacīja uz mani: cilvēka bērns, skaties ar savām acīm un klausies ar savām ausīm, un liec vērā visu, ko es tev rādīšu, jo tāpēc tu esi šurp atvests, lai es tev to rādu; sludini tad visu, ko tu redzi, Israēla namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Un redzi, mūris bija ārā ap to namu visapkārt, un tā vīra rokā bija mērojamā kārts, sešas olektis gara; vienai olektij bija garums olekts un plauksta. Un viņš mēroja tās ēkas platumu vienu kārti un to augstumu vienu kārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Un viņš nāca pie tiem vārtiem, kas bija pret rīta pusi, un viņš uzkāpa uz viņu pakāpēm un mēroja vārtu slieksni, - tam platums bija viena kārts, un otru slieksni, tam platums bija viena kārts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Un ikkatrs kambaris bija vienu kārti garš un vienu kārti plats, un starp tiem kambariem (viņš mēroja) piecas olektis, un to vārtu slieksni pie vārtu pagalma no iekšpuses vienu kārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Un viņš mēroja to vārtu pagalmu no iekšpuses vienu kārti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Un viņš mēroja to vārtu pagalmu, - tur bija astoņas olektis, un viņa pīlārus divas olektis; un to vārtu pagalms bija no iekšpuses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Un to vārtu kambaru pret rītiem bija trīs no šīs un trīs no otras puses; tiem trim bija vienāds mērs, - arī tiem pīlāriem no šīs un viņus puses bija vienāds mērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Un viņš mēroja vārtu durvju platumu desmit olektis, vārtu garumu trīspadsmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Un kambaru priekšā bija vienas olekts starpība no šīs puses un vienas olekts starpība no viņas puses, bet ikkatrs kambaris bija sešas olektis no šīs puses un sešas olektis no viņas puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Tad viņš mēroja tos vārtus no viena kambara jumta līdz (otra kambara) jumtam, - tas platums bija divdesmit piecas olektis, un durvis bija pret durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Viņš taisīja arī pīlārus sešdesmit olektis, un priekš ikkatra pīlāra vienu pagalmu visapkārt ap tiem vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Un no vārtu priekšas, kur ieiet, līdz pagalma priekšgalam pie iekšējiem vārtiem bija piecdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Un šauri logi bija pie tiem kambariem un pie viņu pīlāriem uz iekšu pie tiem vārtiem visapkārt, tā arī pie tiem priekšnamiem, un tie logi bija visapkārt uz iekšu, un pie tiem pīlāriem bija palmu koki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Un viņš mani veda ārējā pagalmā, un redzi, tur bija kambari un grīda, kas pagalmā bija taisīta visapkārt; uz tās grīdas bija trīsdesmit kambari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Un tā grīda bija sānis tiem vārtiem, tam vārtu garumam pretī; šī bija tā lejas grīda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Un viņš mēroja to platumu no lejas vārtu priekšgala uz iekšēja pagalma priekšu no ārienes, simts olektis pret rīta pusi un pret ziemeļa pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Un tos vārtus, kas pret ziemeļa pusi bija pie tā ārējā pagalma, tur viņš mēroja to pašu garumu un viņu platumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Un viņu kambarus, trīs no šīs puses un trīs no viņas puses. Un viņu pīlāri un viņu priekšnami bija pēc tā pirmaju vārtu mēra, piecdesmit olektis bija viņu garums un divdesmit piecas olektis viņu platums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Un viņu logi un viņu priekšnami un viņu palmu koki bija pēc to vārtu mēra, kas bija uz ceļa pret rīta pusi; tur pa septiņām pakāpēm bija jākāpj, un viņu priekšnami bija viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Un iekšēja pagalma vārti bija pretī tiem vārtiem pret ziemeļa pusi un rīta pusi, un viņš mēroja no vārtiem līdz vārtiem simts olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Un viņš mani veda uz to ceļu pret dienvidu pusi, un redzi, tur bija vārti pret dienvidu pusi, un viņš mēroja šos pīlārus un viņu priekšnamus pēc tā paša mēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Un tiem bija arīdzan logi pie viņu priekšnamiem visapkārt, tā kā tie citi logi; tas garums bija piecdesmit olektis un tas platums divdesmit piecas olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Un viņu uzkāpjamie bija septiņas pakāpes, un viņu priekšnami bija viņu priekšā, un palmu koki bija pie viņu pīlāriem, viens no šās un viens no viņas puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Un vārti bija iekšējā pagalmā arī pret dienvidu pusi, un viņš mēroja no vārtiem līdz vārtiem dienvidu pusē simts olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Un viņš mani veda caur Dienvidu vārtiem iekšējā pagalmā, un viņš mēroja Dienvidu vārtus pēc tā paša mēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Un viņu kambari un viņu pīlāri un viņu priekšnami bija pēc tā paša mēra, un tiem arī bija logi viņu priekšnamos visapkārt; tas garums bija piecdesmit olektis, un tas platums divdesmit piecas olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Un priekšnami bija visapkārt; garums bija divdesmit piecas olektis un platums piecas olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Un viņu priekšnami bija pie ārējā pagalma, palmu koki bija arīdzan pie viņu pīlāriem, un viņu uzkāpjamie bija astoņas pakāpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Tad viņš mani veda tai iekšējā pagalmā pret rīta pusi, un viņš mēroja tos vārtus pēc tā paša mēra,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Un viņu kambarus un viņu pīlārus un viņu priekšnamus pēc tā paša mēra, un tiem arī bija logi pie viņu priekšnamiem visapkārt; garums bija piecdesmit olektis un platums divdesmit piecas olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Un viņu priekšnami bija pie ārējā pagalma, ir palmu koki bija pie viņu pīlāriem no šīs un no viņas puses, un viņu uzkāpjamie bija astoņas pakāpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Pēc viņš mani veda pie tiem vārtiem pret ziemeļa pusi, un viņš mēroja pēc tiem pašiem mēriem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Viņu kambarus, viņu pīlārus un viņu priekšnamus; viņiem arīdzan bija logi visapkārt, - garums bija piecdesmit olektis, un platums divdesmit piecas olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Un viņu pīlāri bija pie ārējā pagalma, un palmu koki bija pie viņu pīlāriem, no šīs un no viņas puses, un viņu uzkāpjamie bija astoņas pakāpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Un viens kambaris un viņa durvis bija pie vārtu pīlāriem; lai tur mazgātu dedzināmos upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Un vārtu priekšnamā bija divi galdi no vienas puses un divi galdi no otras puses, uz kuriem lai kautu dedzināmos upurus, grēku upurus un nozieguma upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Un āra pusē, kur uzkāpj pie Ziemeļu vārtu durvīm, bija divi galdi, un otrā pusē, kas pie vārtu priekšnamiem, bija divi galdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Četri galdi no vienas puses, un četri galdi no otras puses sānis tiem vārtiem; tas ir astoņi galdi, uz kuriem tapa kauts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Un četri galdi priekš dedzināmā upura bija no cirstiem akmeņiem, - garums bija pusotras olektis un platums pusotras olektis un augstums viena olekts; uz tiem tie rīki tapa nolikti, ar ko dedzināmie upuri un tie citi upuri tapa kauti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Un tās malas bija plaukstas platumā, iekšpusē piestiprinātas visapkārt, un uz tiem galdiem bija upura gaļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Un iekšēju vārtu āra pusē bija divi kambari iekšējā pagalmā, viens bija sānis Ziemeļu vārtiem un viņa priekša bija pret dienvidiem, viens bija sānis Rīta vārtiem un viņa priekša bija pret ziemeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Un viņš uz mani sacīja: šis kambaris, kam priekša ir pret dienvidu pusi, ir priekš tiem priesteriem, kas to namu kopj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Bet tas kambaris, kam priekša ir pret ziemeļa pusi, ir priekš tiem priesteriem, kas altāri kopj. Tie ir Cadoka bērni, kas no Levja bērniem Tam Kungam tuvojās, Viņam kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Un viņš mēroja to pagalmu - garums bija simts olektis un platums simts olektis, tas bija četrstūris, un altāris bija tā nama priekšā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Tad viņš mani veda tā nama priekšnamā un mēroja priekšnama pīlāru, tam bija piecas olektis no šīs un piecas olektis no viņas puses, un vārtu platums bija trīs olektis no šīs un trīs olektis no viņas puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Priekšnama garums bija divdesmit olektis, un platums vienpadsmit olektis, un tam bija pakāpes, kur bija jāuzkāpj, un stabi bija pie tiem pīlāriem, viens no šīs un viens no viņas puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Un viņš mani noveda Dieva namā, un viņš mēroja tos pīlārus, sešas olektis bija platums no šīs puses un sešas olektis platums no viņas puses, tik plats bija tas dzīvoklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Un durvju platums bija desmit olektis, un durvīm sānis piecas olektis no šīs un piecas olektis no viņas puses. Un viņš mēroja viņa garumu četrdesmit olektis un platumu divdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Tad viņš iegāja iekšā un mēroja durvju pīlārus divas olektis un durvis sešas olektis, un durvju platums bija septiņas olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Un viņš mēroja to garumu divdesmit olektis un to platumu divdesmit olektis Dieva nama priekšā. Un viņš uz mani sacīja: šī ir tā visusvētākā vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Un viņš mēroja tā nama sienu sešas olektis, ikkatra sānu kambara platumu četras olektis visapkārt tam namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Un tie sānu kambari bija viens pie otra trīsdesmit un trīs sānu kambari, un tie satecēja tai sienā, kas pie tā nama bija priekš sānu kambariem visapkārt, ka tie taptu stipri turēti, jo tie nebija stiprināti tā nama sienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Un tie sānu kambari izplētās jo augstāki jo platāki, jo tas nams tapa allažiņ uz augšu aptaisīts visapkārt, tāpēc tas nams uz augšu bija platāks, un no apakšas kambara bija jāiet uz augškambari caur vidējo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Un es redzēju tā nama augstumu visapkārt: sānu kambaru pamati bija vesela kārts, sešas lielas olektis no zemes līdz augšai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Un tās sienas platums, kas priekš tiem sānu kambariem bija uz ārpusi, bija piecas olektis, un kas atlikās, bija sānu kambaru iekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Un starp tiem kambariem bija platums divdesmit olektis visapkārt tam namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Un sānu kambaru durvis bija pie tā atlikuma, vienas durvis pret ziemeli un otras durvis pret dienvidiem, un tā atlikuma platums bija piecas olektis visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Tai ēkai, kas tā atlikuma priekšā bija pret vakara pusi, platums bija septiņdesmit olektis, un tās ēkas siena piecas olektis platumā visapkārt, un viņas garums deviņdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Tad viņš mēroja to namu, viņa garums bija simts olektis, (proti) tas atlikums un tā ēka un viņas sienas bija simts olektis garumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Un nama priekšas platums un tas atlikums pret rīta pusi bija arīdzan simts olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Viņš mēroja arī tās ēkas garumu pret to atlikumu, kas aiz viņas bija, līdz ar viņas margām: no šīs un no viņas puses bija simts olektis. Un iekšējais Dieva nams un pagalma priekšnami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Līdz ar tiem sliekšņiem un šauriem logiem un tām margām visapkārt trijās rindās, slieksnim pretī bija apklāti ar dēļiem visapkārt no zemes līdz logiem, un tie logi bija apsegti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Un izgriezumi bija virs durvīm un līdz iekšējam namam un ārā un pie visām sienām visapkārt, gan ārā, gan iekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Un bija taisīti ķerubi un palmu koki, tā ka viens palma koks bija starp ķerubu un ķerubu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Un ikvienam ķerubam bija divi vaigi, cilvēka vaigs pret šīs puses palma koku, un lauvas vaigs pret viņas puses palma koku; tā tas bija taisīts visā namā visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'No zemes līdz pāri pār durvīm bija ķerubi un palmu koki taisīti, un pie Dieva nama sienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Un Dieva nama stenderi bija četrām kantīm, un svētās vietas priekša tāpat izskatījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Altāris bija no koka, trīs olektis augstumā un divas olektis garumā, un viņa virsas un viņa sienas bija no koka. Un viņš uz mani runāja: šis ir tas galds, kas stāv Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Un Dieva namam un tai svētai vietai bija katram divas durvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Un pie tām durvīm bija divi spārni, ko varēja atvērt un aizvērt, divi pie vienām durvīm un divi spārni pie otrām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Un pie tām, proti pie Dieva nama durvīm, bija taisīti ķerubi un palmu koki, tā kā bija taisīti pie sienām, un priekšnama priekšā no āra puses bija koka slieksnis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Un pie tiem šauriem logiem bija arīdzan palmu koki no šīs un no viņas puses priekšnama sānos, un pie tā nama sānu kambariem un pie tiem sliekšņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Un viņš mani izveda ārējā pagalmā pret ziemeli, un viņš mani noveda pie tiem kambariem, kas bija tam atlikumam pretī un tai ēkai pretī uz ziemeļa pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Tās priekšas garums bija simts olektis līdz ziemeļa puses durvīm, un platums bija piecdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Pret tām divdesmit olektīm, kas bija iekšējam pagalmam, un pret to grīdu, kas bija ārējam pagalmam, stāvēja marga pret margu trijās rindās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Un priekš tiem kambariem bija staigājams ceļš desmit olektis plats; uz iekšpusi ceļš simts olekšu, un viņu durvis bija pret ziemeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Un tie augškambari bija šaurāki nekā tie apakšējie un tie vidējie; jo tās margas aizņēma rūmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Jo jebšu tie trejās rindās stāvēja, tad tomēr šiem nebija nekādi stabi kā tie pagalmu stabi, tāpēc tie bija šaurāki nekā tie apakšējie un tie vidējie no zemes uz augšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Un tas mūris, kas kambaru ārapusē bija, līdz ārējam pagalmam tai kambaru priekšā, tā garums bija piecdesmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Jo kambaru garums ārējā pagalmā bija piecdesmit olektis, un redzi pret Dieva namu bija simts olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Un apakš šiem kambariem bija ieiešana no rīta puses, kad nāca no ārējā pagalma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Un gar pagalma mūri pret rīta pusi tā atlikuma un tās ēkas priekšā bija kambari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Un ceļš bija viņu priekšā tāds pat kā to kambaru priekšā, kas pret ziemeli; kā viņu garums, tā viņu platums, un visas viņu izejamās vietas bija pēc viņu līdzības un tāpat kā tās citas durvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Un tādas pat bija tās durvis tiem kambariem pret dienvidiem, un vienas durvis bija tai priekšā, it klāt pie tā stāvā mūra, kad nāk no rīta puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Tad viņš uz mani sacīja: tie kambari ziemeļa pusē un tie kambari dienvidu pusē, kas tā atlikuma priekšā, tie ir svēti kambari, kur priesteriem, kas pie Tā Kunga pieiet, būs ēst tās augsti svētās dāvanas. Tur tiem tās augsti svētās dāvanas būs nolikt, proti ēdamo upuri un grēku upuri un nozieguma upuri, jo tā vieta ir svēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Kad tie priesteri ieiet, tad tiem no svētās vietas nebūs atkal iziet ārējā pagalmā, bet tiem turpat būs nolikt savas drēbes, kurās tie kalpojuši, jo tās ir svētas. Tad tiem būs apvilkt citas drēbes un iziet ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Kad viņš nu tā nama iekšpuses mērošanu bija pabeidzis, tad viņš mani veda ārā pie tiem vārtiem pret rīta pusi, un viņš to mēroja visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Viņš mēroja rīta pusi ar mērojamo kārti, piecsimt kārtis bija ar mērojamo kārti visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Viņš mēroja ziemeļa pusi, piecsimt kārtis ar mērojamo kārti visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Arī dienvidu pusi viņš mēroja piecsimt kārtis ar mērojamo kārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Tad viņš griezās uz vakara pusi un tur mēroja piecsimt kārtis ar mērojamo kārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Viņš to mēroja uz visām četrām pusēm. Visapkārt bija mūris: garumā piecsimt kārtis un platumā piecsimt, atšķirt to svēto no tā nesvētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Un viņš mani noveda pie tiem vārtiem, kas pret rīta pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Un redzi, Israēla Dieva godība nāca no rīta puses, un viņa rībēšana bija kā varenu ūdeņu rūkšana, un zeme tapa apgaismota no Viņa godības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Un viņa parādīšanās bija tāda pati, kādu es redzēju, kad es nācu, to pilsētu postīt, un tā parādīšanās bija tā kā tā, ko es redzēju pie Ķebaras upes, un es kritu uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Un Tā Kunga godība nāca tai namā pa tiem vārtiem, kas pret rīta pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Un Tas Gars mani pacēla un mani ieveda iekšējā pagalmā, un redzi, Tā Kunga godība piepildīja to namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Un no tā nama es dzirdēju vienu ar mani runājam, un viens vīrs stāvēja pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Un Tas uz mani sacīja: “Cilvēka bērns, šī ir Mana godības krēsla vieta un Manu pēdu vieta, kur Es Israēla bērnu vidū dzīvošu mūžīgi. Un Israēla nams, viņi ar saviem ķēniņiem vairs nesagānīs Manu svēto Vārdu ar savu maucību un ar savu ķēniņu mirušām miesām pie viņu miršanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Kad tie savu slieksni lika pie mana sliekšņa un savus stabus pie maniem stabiem, ka tikai siena bija starp mani un viņiem, un sagānīja manu svēto vārdu ar savām negantībām, ko tie darīja; tāpēc es tos esmu aprijis savā dusmībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nu tie atņems savu maucību un savu ķēniņu mirušās miesas tālu nost no manis un es dzīvošu viņu vidū mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Tu cilvēka bērns, dari zināmu Israēla namam šo namu, lai tie kaunas savu noziegumu dēļ, un lai tie to ēku mēro.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Kad tie nu kaunas par visu, ko tie darījuši, tad rādi tiem tā nama izskatu un viņa kārtību un viņa izejamās un ieejamās durvis un visu viņa izskatu un visus viņa likumus un visu viņa stāvu, un visu viņa bauslību dari tiem zināmu un raksti priekš viņu acīm, ka tie visu viņa izskatu un visus viņa likumus patur un tos dara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Šī ir Tā Dieva nama bauslība: kalna galā visapkārt līdz viņa robežām ir vissvētākā vieta; redzi, šī ir tā nama bauslība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Un šie ir altāra mēri pēc tās olekts, kas ir lielāka nekā cita olekts par vienu plaukstu. Viņa pamats ir vienu olekti (augstumā) un vienu olekti garumā, un viņa malas zimze(apmale) ir vienu sprīdi visapkārt; un tas ir altāra augstums:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'No pamata pie zemes līdz apakšējai pakāpei bija divas olektis un platums viena olekts. Bet no tās mazās pakāpes līdz tai lielai ir četras olektis un platums viena olekts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Un altāra ugunskurs bija četras olektis augstumā, un no ugunskura uz augšu bija tie četri ragi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Un altāra ugunskurs bija divpadsmit olektis garumā un divpadsmit olektis platumā, četrkantīgs uz saviem četriem sāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Un tā (augšēja) pakāpe bija četrpadsmit olektis garumā un četrpadsmit olektis platumā savos četros sānos, un tā mala ap viņu bija vienu pusolekti, un tas pamats pie tās bija viena olekts visapkārt, un uzkāpšana bija no rīta puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Un viņš uz mani sacīja: cilvēka bērns, tā saka Tas Kungs Dievs: šie ir altāra likumi tai dienā, kad viņš taps taisīts, uz tā upurēt dedzināmos upurus un uz to slacināt asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Un tiem priesteriem, Levja bērniem, kas ir no Cadoka dzimuma, kas man tuvojās, man kalpot, saka Tas Kungs Dievs: tiem tev būs dot vienu jaunu vērsi par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Un tev no viņa asinīm būs ņemt un to likt pie viņa četriem ragiem un pie tiem četriem pakāpes stūriem un pie tās apkārtējās malas, tā tev to būs šķīstīt un svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Un tev būs ņemt grēku upura vērsi, un to būs sadedzināt ierādītā nama vietā, ārā no tās svētās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Un otrā dienā tev būs upurēt vienu āzi, kas bez vainas, par grēku upuri, un altāri būs svētīt, tā kā to svētīja ar to vērsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Kad tu nu to svētīšanu būsi pabeidzis, tad tev no ganāmā pulka būs upurēt vienu jaunu vērsi, kas bez vainas, un vienu aunu, kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Un tev tos būs upurēt Tā Kunga priekšā, un priesteriem būs sāli uz tiem mest un tos upurēt par dedzināmo upuri Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Septiņas dienas tev būs upurēt ikdienas vienu āzi par grēku upuri, viņiem arī būs upurēt vienu jaunu vērsi un vienu aunu no ganāmā pulka, kas abi bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Septiņas dienas tiem altāri būs svētīt un viņu šķīstīt un savas rokas pildīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Un pēc šīm dienām priesteriem astotā dienā un joprojām būs upurēt jūsu dedzināmos upurus un jūsu pateicības upurus uz altāra, un man būs labs prāts pie jums, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Un viņš mani veda atpakaļ pie svētās vietas ārējiem vārtiem, kas ir pret rīta pusi, un tie bija aizslēgti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Un Tas Kungs uz mani sacīja: šie vārti lai stāv aizslēgti, tie nav jāatver, un neviens pa tiem lai neieiet, tāpēc ka Tas Kungs, Israēla Dievs, pa tiem ir iegājis, tāpēc lai tie stāv aizslēgti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Par valdnieku jāsaka: kas valdnieks, tas lai tur sēž, maizi ēst Tā Kunga priekšā; pa vārtu priekšnamu tam būs ieiet un pa to pašu ceļu tam būs iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Un viņš mani veda pie ziemeļa vārtiem nama priekšā, un es redzēju, un raugi, Tā Kunga godība piepildīja to namu; tad es kritu uz savu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Un Tas Kungs sacīja uz mani: cilvēka bērns, ņem vērā un redzi ar savām acīm un klausies ar savām ausīm visu, ko Es ar tevi runāju par visiem Tā Kunga nama likumiem un par visiem viņa baušļiem, un ņem vērā tā nama ieejamo vietu ar visām tām svētās vietas izejamām vietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Un saki uz tiem pārgalvīgiem, uz Israēla namu; tā saka Tas Kungs Dievs: nu ir gan, Israēla nams, ar visu jūsu negantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Ja jūs esat ieveduši svešiniekus ar neapgraizītām sirdīm un neapgraizītām miesām, ka tie bija Manā svētā vietā, to sagānīt, Manu namu, kad jūs upurējāt Manu maizi, taukus un asinis, un tie Manu derību lauza pie visām jūsu negantībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Un jūs neesat izpildījuši savu svēto kalpošanu, bet citus sev esat iecēluši, kalpot Manā svētā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Tā saka Tas Kungs Dievs: nevienam svešiniekam, kam neapgraizīta sirds un neapgraizīta miesa, nebūs ieiet Manā svētā vietā, no visiem tiem svešiniekiem, kas ir starp Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Bet tie leviti, kas tālu no Manis atkāpušies, kad Israēls maldīdamies no manis nomaldījās saviem elkiem pakaļ, tie gan nesīs savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Un tiem būs kalpot Manā svētā vietā par sargiem pie nama vārtiem, un tiem būs to namu apkopt, tiem būs kaut dedzināmos un kaujamos upurus priekš tiem ļaudīm, un viņu priekšā stāvēt, viņiem kalpodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Tāpēc ka tie viņiem ir kalpojuši viņu elku priekšā un Israēla namam bijuši par apgrēcību uz noziedzību, tāpēc Es paceļu Savu roku pret tiem, saka Tas Kungs Dievs, ka tiem būs nest savu noziegumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Un tiem nebūs Man tuvoties, Man būt par priesteriem nedz pieiet pie visām Manām svētām un tām visu svētākām lietām, bet tiem būs savu kaunu nest un savas negantības, ko tie darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Tāpēc Es tos ieceļu par sargiem, to namu kopt pie viņa darba, un pie visa, kas iekš tā būs jādara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Bet tie priesteri un Levja cilts, Cadoka bērni, kas to kalpošanu izpildījuši Manā svētā vietā, kad Israēla bērni no Manis nomaldījās, tiem Man būs tuvoties, Man kalpot un stāvēt Manā priekšā, Man upurēt taukus un asinis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Tiem būs ieiet Manā svētā vietā, un tiem būs nostāties pie Mana galda, Man kalpot un Manu kalpošanu izpildīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Un kad tie nāks pie tā iekšējā pagalma vārtiem, tad tiem būs apvilkt linu drēbes, bet vilnainās tiem nebūs ģērbties, kad tie iekšējā pagalma vārtu iekšpusē kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Linu autiem būs būt uz viņu galvām un linu ūzām(biksēm) uz viņu gurniem, un tiem nebūs apjozties sviedros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Un kad tie iziet ārējā pagalmā, proti ārējā pagalmā pie tiem ļaudīm, tad tiem būs novilkt savas drēbes, ar ko tie kalpojuši, un tās nolikt svētās vietas kambaros, un tiem būs apvilkt citas drēbes, lai tie tos ļaudis nesvētī ar savām drēbēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Un tiem savu galvu nebūs pliku nodzīt nedz arī saviem matiem likt gari izaugt, bet tiem savus matus būs apcirpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Un nevienam priesterim nebūs vīna dzert, kad tiem jāiet iekšējā pagalmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Tiem arīdzan nebūs ņemt nedz atraitni nedz atšķirtu par sievu, bet jumpravas no Israēla nama dzimuma; bet atraitni, kas ir priestera atraitne, to viņi var ņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Un tiem būs mācīt Maniem ļaudīm izšķirt svētu un nesvētu, un tiem darīt zināmu starpību starp nešķīstu un šķīstu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Un tiem būs stāvēt par tiesas lietām un tiesāt, pēc Manām tiesām tiem būs tiesāt, un tiem būs turēt Manus baušļus un Manus likumus visos Manos svētkos un svētīt Manas svētdienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Un nevienam no tiem nebūs iet pie kāda miruša cilvēka, lai netop nešķīsts; bet tēva un mātes dēļ, vai dēla un meitas dēļ, brāļa un māsas dēļ, kas nav bijusi pie vīra, tiem ir brīv tapt nešķīstiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Un pēc viņa šķīstīšanās vēl septiņas dienas jāpieskaita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Un tai dienā, kad viņš ieies svētā vietā, iekšējā pagalmā, kalpot svētā vietā, tad tam būs upurēt savu grēku upuri, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Un tas tiem būs par mantību: Es esmu viņu mantība; tāpēc jums tiem nekādu sevišķu daļu nebūs dot iekš Israēla, - Es esmu viņu daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ēdamo upuri un grēku upuri un nozieguma upuri, tos tiem būs ēst, un viss, kas iekš Israēla (Dievam) apsolīts, tiem piederēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Un visu pirmo augļu pirmaji no visa un visi cilājamie upuri no visiem jūsu cilājamiem upuriem lai pieder priesteriem. Arī savas mīklas pirmajus jums būs dot priesterim, lai svētība paliek uz tava nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Nekādu maitu, nedz saplosītu no putniem un no lopiem priesteriem nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Kad jūs nu to zemi izdalīsiet par mantību, tad jums Tam Kungam būs upurēt cilājamu upuri no zemes, vienu svētu zemes daļu, divdesmit un pieci tūkstoši mērojamas kārtis garumā un desmit tūkstoši platumā; tā būs viena svēta daļa visās savās ežās(robežās) visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'No tā tai svētai vietai piederēs pa piecsimt (mērojamām kārtīm) četriem stūriem visapkārt, un piecdesmit olektis būs par apgabalu visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Tā tev no šī mēra būs mērot garumu divdesmit un piectūkstoš, un platumu desmit tūkstošus (mērojamās kārtis), un tur būs tā svētā vieta ar to visu svētāko vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Šī būs tās zemes svētā daļa, un būs priekš tiem priesteriem, kas kalpo svētā vietā, kas nāk klāt Tam Kungam kalpot, un tā tiem būs vieta priekš namiem, un svēta vieta atšķirta priekš tā svētuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Bet divdesmit un piectūkstoš (mērojamas kārtis) garumā un desmit tūkstošus platumā lai ir par daļu levitiem, tā nama sulaiņiem, priekš pilsētām, kur dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Un pilsētai jums būs dot zemes gabalu, piectūkstoš (mērojamas kārtis) platumā un divdesmit un piectūkstoš garumā, sānis tam svētam zemes gabalam; tas būs priekš visa Israēla nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Un valdniekam lai ir sava daļa tā svētā zemes gabala un tās pilsētas daļas šinī un viņā pusē, tā svētā zemes gabala un tās pilsētas daļas vakarā pusē pret vakara pusi un rīta pusē pret rīta pusi, un tas garums lai ir blakām vienai no šīm daļām, no vakara puses līdz rīta pusei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, '(Šis) zemes (gabals) tam lai ir par daļu iekš Israēla, un mani valdnieki lai nedara vairs grūti maniem ļaudīm, bet lai Israēla namam to zemi atstāj pēc viņu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Tā saka Tas Kungs Dievs: lai tas jums pietiek, Israēla valdnieki! Atstājat varas darbu un postīšanu un dariet tiesu un taisnību, neizdzenāt vairs Manus ļaudis, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Jums būs turēt taisnu svaru un taisnu ēfu un taisnu batu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Êfa un bats lai ir vienādi, tā ka bats ir desmitā tiesa no viena homera, un ēfa ir desmitā tiesa no viena homera; viņas mērs lai ir pēc homera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Un vienam sēķelim būs turēt divdesmit ģera. Pieci sēķeļi lai ir pieci un desmit sēķeļi lai ir desmit, un piecpadsmit sēķeļi lai jums ir viena mīne.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Šis ir tas cilājamais upuris, ko jums būs cilāt, vienas ēfas sesto tiesu no viena homera kviešu, - jums arī būs dot vienas ēfas sesto tiesu no viena homera miežu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Un par eļļu ir šis tas likums: no bata eļļas jums būs upurēt viena bata desmito tiesu no viena kora, tas ir viens homers no desmit batiem, jo desmit bati ir viens homers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Atkal no ganāmā pulka pa jēru no divsimt, no Israēla taukām ganībām par ēdamo upuri un dedzināmo upuri un pateicības upuriem, tiem par salīdzināšanu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Visiem ļaudīm iekš zemes nāksies šo cilājamo upuri dot priekš Israēla valdnieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Un valdniekam pienāksies upurēt dedzināmos upurus un ēdamu upuri un dzeramu upuri svētkos un jaunos mēnešos un svētdienās. Visos augstos Israēla nama svētku laikos viņam grēku upuri un ēdamu upuri un dedzināmu upuri un pateicības upurus būs upurēt Israēla namam par salīdzināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Tā saka Tas Kungs Dievs: pirmā mēnesī, pirmā mēneša dienā, tev būs ņemt vienu jaunu vērsi, kas bez vainas, un to svēto vietu svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Un priesterim būs ņemt no tām grēku upura asinīm, un slacināt uz nama stenderes un uz altāra pakāpes četriem stūriem un iekšēja pagalma vārtu stenderes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tāpat tev būs darīt septītā mēneša dienā priekš tiem, kas ir grēkojuši, maldīdamies vai nezinādami; tā jums to namu būs svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Pirmā mēnesī, četrpadsmitā mēneša dienā jums būs turēt Pasa svētkus; septiņas dienas būs svētīt un neraudzētu maizi ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Un valdniekam tai dienā būs upurēt priekš sevis un visiem ļaudīm iekš zemes vērsi par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Un tanīs septiņās svētku dienās viņam būs upurēt Tam Kungam par dedzināmo upuri septiņus vēršus un septiņus aunus, kas bez vainas, ikdienas visas septiņas dienas, un ikdienas vienu āzi par grēku upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Un viņam būs nest par ēdamu upuri vienu ēfu pie vērša un vienu ēfu pie auna un vienu innu eļļas pie ēfas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Un septītā mēnesī, piecpadsmitā mēneša dienā viņam svētkos tāpat būs darīt, septiņas dienas ar tādu pat grēku upuri un dedzināmu upuri un ēdamu upuri un eļļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Tā saka Tas Kungs Dievs: iekšēja pagalma vārti, kas pret rītiem, lai sešās darba dienās ir aizslēgti, bet svētdienā lai tie top atvērti, un jauna mēneša dienā lai tie top atvērti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Un valdniekam būs ieiet pa vārtu priekšnamu no ārienes, un nostāties pie vārtu stenderes, un priesteriem būs upurēt viņa dedzināmo upuri un viņa pateicības upurus, un viņam pašam būs pielūgt pie vārtu sliekšņa, un tad iziet, bet vārtiem nebūs tapt aizslēgtiem līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Un zemes ļaudīm būs pielūgt pie to pašu vārtu durvīm svētdienās un jaunos mēnešos Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Un tas dedzināmais upuris, ko valdnieks lai upurē Tam Kungam svētdienā, lai ir seši jēri, kas bez vainas, un viens auns, kas bez vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Un ēdamais upuris lai ir viena ēfa pie auna, bet pie tiem jēriem lai ir ēdamais upuris, cik viņa roka dod, un eļļas viens ins pie ēfas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Bet jauna mēneša dienā: viens jauns vērsis, kas bez vainas, un seši jēri un viens auns, - tiem būs bez vainas būt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Un viņam par ēdamo upuri būs pienest vienu ēfu pie vērša un vienu ēfu pie auna, bet pie tiem jēriem, cik viņa roka spēs, un viens ins eļļas pie ēfas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Un kad valdnieks ieiet, tad viņam pa priekšnama vārtiem būs ieiet un pa to pašu ceļu atkal iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Bet kad zemes ļaudis Tā Kunga priekšā nāk augstos svētkos, tad tiem, kas pa Ziemeļa vārtiem ieiet pielūgt, pa Dienvidu vārtiem atkal būs iziet, un kas ieiet pa Dienvidu vārtiem, tiem atkal būs iziet pa Ziemeļa vārtiem; tiem nebūs atkal iet pa tiem vārtiem, pa kuriem tie iegājuši, bet tiem būs taisni projām iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Un valdniekam būs līdz ar viņiem ieiet, un kad tie iziet, tiem kopā būs iziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Bet svētkos un augstos svētku laikos lai ēdamais upuris ir viena ēfa pie vērša un viena ēfa pie auna, bet pie jēriem, cik viņa roka dod, un viens ins eļļas pie ēfas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Un kad valdnieks labprātīgi upurē Tam Kungam dedzināmo upuri vai pateicības upuri no laba prāta, tad viņam būs atdarīt tos vārtus, kas ir pret rīta pusi, un viņam savu dedzināmo upuri un savus pateicības upurus nesot būs darīt, kā viņš svētdienā darījis, un kad viņš atkal iziet, būs vārtus aizslēgt, kad viņš būs izgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Un gadu vecu jēru, kas bez vainas, tev ikdienas Tam Kungam būs upurēt par dedzināmo upuri; ik rītu tev to būs pienest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Un par ēdamu upuri pie tā tev ik rītu būs nest sesto tiesu ēfas un eļļu trešo tiesu inna, tos kviešu miltus ar to aptraipīt par ēdamu upuri Tam Kungam, tas ir mūžīgs likums, kam nebūs mitēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Un to jēru un to ēdamo upuri un to eļļu ik rītu būs upurēt par nemitējamu dedzināmo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Tā saka Tas Kungs Dievs: kad valdnieks kādam no saviem dēliem dod dāvanu, tā ir viņa mantība, tā lai pieder viņa dēliem; tas ir viņu īpašums par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Bet kad viņš no savas mantības kādam no saviem kalpiem dos dāvanu, tam to būs turēt līdz vaļas gadam, tad valdniekam to atkal būs atdabūt, tik viņa dēliem var tikt viņa mantība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Valdniekam arī nekā nebūs ņemt no ļaužu mantības, tiem nebūs laupīt viņu tiesu. Lai viņš no sava paša padoma atstāj mantību saviem dēliem, ka mani ļaudis netop izdzīti, neviens no savas mantības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Un viņš mani ieveda pa tām durvīm, kas bija sānis tiem vārtiem, priesteru svētos kambaros, kas pret ziemeļa pusi, un redzi, galā bija viena vieta pret vakara pusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Un viņš uz mani sacīja: šī ir tā vieta, kur priesteriem būs vārīt nozieguma un grēka upuri, un kur tiem būs cept ēdamo upuri, lai tie to neiznes ārējā pagalmā, tos ļaudis svētīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Tad viņš mani izveda ārējā pagalmā un mani veda apkārt pa tiem četriem pagalma stūriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Un redzi, ikkatra pagalma stūrī bija atkal pagalms, tais četros pagalma stūros bija atšķirti pagalmi, četrdesmit olektis garumā un trīsdesmit platumā, un visām tām četrām stūru vietām bija vienāds mērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Un mūris bija visapkārt ap visām četrām un apakšā pie tiem mūriem bija taisīti ugunskuri visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Un viņš uz mani sacīja: šie ir tā nama ugunskuri, kur tā nama sulaiņiem būs vārīt ļaužu upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Un viņš mani veda atpakaļ pie tā nama durvīm, un redzi, tur ūdens iztecēja apakš tā nama sliekšņa pret rītiem, jo tā nama priekšgals bija pret rītiem, un tas ūdens notecēja no apakšas no tā nama labās puses, sānis altārim pret dienvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Un viņš mani izveda pa Ziemeļa vārtiem, un mani apveda apkārt pa āra ceļu pie ārējiem vārtiem, kas pret rītiem, un redzi, ūdens iztecēja no labās puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Kad nu tas vīrs izgāja pret rītiem, tad mēra aukla bija viņa rokā, un viņš mēroja tūkstoš olektis, un lika man brist pār to ūdeni, un tas ūdens man sniedzās līdz krimšļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Atkal viņš mēroja tūkstoš olektis un lika man brist pār to ūdeni, un tas ūdens man sniedzās līdz ceļiem, un viņš mēroja vēl tūkstoš olektis, un lika man pārbrist, un tas ūdens man sniedzās līdz gurniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Atkal viņš mēroja tūkstoš olektis, tad bija upe, ko es nevarēju izbrist, jo tas ūdens bija dziļš, ūdens, kur bija jāpeld, upe, kur nevarēja iet cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Un viņš uz mani sacīja: vai tu to esi redzējis, cilvēka bērns? Tad viņš mani veda atkal atpakaļ upes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Kad es nu nācu atpakaļ, redzi, tad upes malā bija ļoti daudz koku, šinī un viņā pusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Un viņš uz mani sacīja; šis ūdens iztek pret rīta pusi un notek klajumā, pēc tas nāk jūrā, un jūrā notecējis tas ūdens taps veselīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Un notiek, ka ikviena dzīva dvaša, kas kustās, kurp šī upe(no diviem avotiem) nāk, dzīvos, un tur būs ļoti daudz zivju, tāpēc ka šis ūdens turp nāks, un būs veseli un viss dzīvos, kur šī upe nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Un zvejnieki pie tās stāvēs no Enģediem līdz EnEģlaīm, tur būs vietas, kur tīklus izmetīs. Viņu zivis būs pēc savas kārtas, kā tās lielās zivis jūrā, ļoti daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Bet viņas paltis(dumbrāji) un viņas dīķi netaps veselīgi; tie būs priekš sāls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Un pie tās upes viņas malas abējās pusēs augs visādi augļu koki, kam lapas nesavītīs un augļi nemitēsies, un ikmēnešus tie nesīs jaunus augļus. Jo viņas ūdens iztek no tās svētās vietas, un viņas augļi būs par barību un viņas lapas par dziedināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Tā saka Tas Kungs Dievs: šī lai ir robeža, pēc kuras jums to zemi būs ņemt par mantību pēc tām divpadsmit Israēla ciltīm: Jāzepam pienākas divas daļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Un jums to būs iemantot, vienam kā otram; par to es savu roku esmu pacēlis, to dot jūsu tēviem; un šī zeme jums piekritīs par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Šī nu ir tās zemes robeža: pret ziemeli no lielās jūras pār Etlonu, kamēr nāk uz Cedadu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamata, Berota, Zibraīma, kas ir starp Damaskus robežu un Hamatas robežu, AcarTikons, kas ir pie Averana robežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Tā būs tā robeža no jūras līdz AcarEnonam, Damaskus robežai; un tālāk pret ziemeli ir Hamatas robeža, un šī būs tā ziemeļa mala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Un tā rītu mala starp Averanu un Damasku un starp Gileādu un Israēla zemi jums būs Jardāne; no tās robežas līdz rītu jūrai jums būs mērot. Un šī ir tā rītu mala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Un tā dienvidu mala pret dienvidiem lai ir no Tamāra līdz Kādeša strīdus ūdenim, un tad gar upi līdz lielai jūrai. Un šī būs tā dienvidu mala pret dienvidiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Un tā vakaru mala lai ir tā lielā jūra no tās robežas, līdz kamēr iet uz Hamatu. Šī būs tā vakaru mala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Un jums šo zemi savā starpā būs izdalīt pēc Israēla ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Un jums to būs izdalīt par mantību sev un arī tiem svešiniekiem, kas jūsu starpā dzīvo un bērnus dzemdinājuši jūsu vidū, un tie lai jums ir kā tas, kas no Israēla bērniem dzimis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Tiem būs līdz ar jums mantot Israēla cilšu vidū, un tai ciltī, pie kuras tas svešinieks dzīvo, tur jums viņam būs dot daļu, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Šie nu ir tie cilšu vārdi: no ziemeļa puses sānis Etlona ceļam, kur iet uz Hamatu, AcarEnons, Damaskus robeža pret ziemeļa pusi, sānis Hamatai: no rīta puses līdz vakara pusei lai ir Danam, viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Un pie Dana robežas no rīta puses līdz vakara pusei Ašeram viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Un pie Ašera robežas no rīta puses līdz vakara pusei Naftalum viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Un pie Naftalus robežas no rīta puses līdz vakara pusei Manasum viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Un pie Manasus robežas no rīta puses līdz vakara pusei Efraīmam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Un pie Efraīma robežas no rīta puses līdz vakara pusei Rūbenam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Un pie Rūbena robežas no rīta puses līdz vakara pusei Jūdam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Un pie Jūda robežas no rīta puses līdz vakara pusei lai ir tas svētais zemes gabals, ko jums būs atšķirt, divdesmit un pieci tūkstošus (mērojamās kārtis) platumā un garumā, tā kā viena no tām citām daļām no rīta puses līdz vakara pusei, un tur vidū lai ir tā svētā vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Tas svētais zemes gabals, ko jums būs atšķirt Tam Kungam, lai ir garumā divdesmit un pieci tūkstošus (mērojamas kārtis) un platumā desmit tūkstošus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Un šiem lai tas svētais zemes gabals pieder: priesteriem, pret ziemeļa pusi divdesmit pieci tūkstošus (olektis), un pret vakara pusi desmit tūkstošus platumā, un pret rīta pusi desmit tūkstošus platumā, un pret dienasvidu divdesmit un pieci tūkstošus garumā. Un Tā Kunga svētā vieta lai ir viņa vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Tas būs priekš tiem priesteriem, tiem svētītiem, Cadoka bērniem, kas Manu kalpošanu izpildījuši, kas nav atkāpušies, kad Israēla bērni atkāpās, kā leviti ir atkāpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Un tiem būs dabūt vienu gabalu no tā svētā gabala, kas tas vissvētākais gabals ir pie levitu robežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Tiem levitiem, sānis priesteru robežai, būs dabūt divdesmit un piectūkstoš (olektis) garumā un desmit tūkstošus platumā; viss garums lai ir divdesmit un pieci tūkstošus, un platums desmit tūkstošus (olektis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Un tiem no tā nekā nebūs pārdot, nedz pārmainīt, nedz citam izdot zemes pirmajus; jo tas ir Tam Kungam svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Bet tās piectūkstošas (olektis), kas platumā atlikušas no tām divdesmit pieci tūkstoš (olektīm), tās lai nav svētas, pilsētai priekš dzīvokļiem un ganībām, un tā pilsēta lai tur ir vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Un šie ir viņas mēri: ziemeļa malā četrtūkstoš un piecsimt olektis, un dienvidu malā četrtūkstoš un piecsimt, un rīta malā četrtūkstoš un piecsimt, un vakara malā četrtūkstoš un piecsimt (olektis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Un pilsētas apgabals lai ir pret ziemeli divsimt un piecdesmit, un pret dienasvidu divsimt un piecdesmit, un pret rītiem divsimt un piecdesmit, un pret vakaru divsimt un piecdesmit (olektis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Un tas atlikums garumā gar to svēto zemes gabalu desmit tūkstoši pret rīta pusi, un desmit tūkstoši pret vakara pusi, gar to svēto zemes gabalu; viņa augļi būs par uzturu pilsētas kalpotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Un pilsētas kalpotāji lai to apstrādā no visām Israēla ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Viss svētais zemes gabals lai ir divdesmit un pieci tūkstoš (olektis) garumā un divdesmit un piectūkstoš (olektis) platumā; to jums būs atšķirt par svētu zemes gabalu līdz ar to pilsētas tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Un kas atliek, tas lai pieder valdniekam, tā svētā zemes gabala un pilsētas tiesas šinī un viņā pusē gar tā svētā gabala divdesmit pieci tūkstoš (olektīm) līdz rīta robežai un pret vakara pusi gar tām divdesmit piectūkstoš (olektīm) līdz vakara robežai, sānis tām citām daļām; tas būs priekš valdnieka. Un tas svētais zemes gabals ar tā nama svēto vietu lai ir viņa vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Un (sākot) no levitu tiesas un no pilsētas tiesas, (vidū tam, kas valdniekam pieder,) starp Jūda un Benjamina robežām, tas lai valdniekam pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Tad lai tās citas tiesas nāk; no rīta puses līdz vakara pusei Benjaminam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Un pie Benjamina robežas no rīta puses līdz vakara pusei Sīmeanam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Un pie Sīmeana robežas no rīta puses līdz vakara pusei Īsašaram viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Un pie Īsašara robežas no rīta puses līdz vakara pusei Zebulonam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Un pie Zebulona robežas no rīta puses līdz vakara pusei Gadam viena daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Un pie Gada robežas dienvidu malā pret dienvidiem būs tā robeža no Tamāra uz Kādeša strīdus ūdeni un tad uz to upi līdz lielai jūrai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Šī ir tā zeme, ko jums ar mesliem būs izdalīt par mantību visām Israēla ciltīm, un šīs lai ir viņu daļas, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Un šīs lai ir tās pilsētas robežas: ziemeļa pusē četrtūkstoš un piecsimt mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Un pilsētas vārti lai ir pēc Israēla cilšu vārdiem, trīs vārti pret ziemeli: Rūbena vārti, vieni, Jūda vārti, vieni, Levja vārti, vieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Un pret rītiem četrtūkstoši un piecsimt (mēri) un trīs vārti: Jāzepa vārti, vieni, Benjamina vārti, vieni, Dana vārti, vieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Pret dienasvidu arīdzan četrtūkstoši un piecsimt mēri un trīs vārti: Sīmeana vārti, vieni, Īsašara vārti, vieni, Zebulona vārti, vieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Pret vakariem četrtūkstoš un piecsimt (mēri) un trīs vārti: Gada vārti, vieni, Ašera vārti, vieni, Naftalus vārti, vieni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Visapkārt astoņpadsmit tūkstoš (mēri). Un pilsētas vārds būs no tās dienas: še ir Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Jojaķima, Jūda ķēniņa, trešā valdīšanas gadā Nebukadnecars, Bābeles ķēniņš, nāca uz Jeruzālemi un apmetās pret to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Un Tas Kungs nodeva Jojaķimu, Jūda ķēniņu, viņa rokā un vienu daļu Dieva nama trauku, un viņš tos noveda uz Sineāra zemi sava dieva namā, un tos traukus viņš nolika sava dieva mantu namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Un ķēniņš sacīja uz Aspenasu, savu kambarjunkuru uzraugu, lai no Israēla bērniem, no ķēniņu un lielkungu dzimuma izlasa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Jaunekļus, kas bez vainas, skaistus vaigā un samanīgus visādā gudrībā un labi mācītus un kam gudrs prāts, un kas būtu derīgi ķēniņa pilī stāvēt, ka tie taptu mācīti Kaldeju rakstā un valodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Un ķēniņš tiem sprieda, ko tiem ikdienas būs dot no ķēniņa ēdiena un no tā vīna, ko pats dzēra, un ka tie trīs gadus tā taptu audzināti, un ka pēc stāvētu ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Starp tiem nu bija no Jūda bērniem Daniēls, Ananija, Mišaēls un Azarija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Un kambarjunkuru uzraugs tiem deva citus vārdus un nosauca Daniēli par Beltsacaru un Ananiju par Sadrahu un Mišaēli par Mesahu un Azariju par AbedNegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Bet Daniēls apņēmās savā sirdī, nesagānīties ar ķēniņa ēdienu nedz ar to vīnu, ko viņš dzēra, tādēļ tas lūdza kambarjunkuru uzraugam, lai viņam atļautu nesagānīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Un Dievs Daniēlim deva žēlastību un apžēlošanu kambarjunkuru uzrauga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Un kambarjunkuru uzraugs sacīja uz Daniēli: es bīstos savu kungu, ķēniņu, kas jūsu ēdienu un dzērienu tā nospriedis, ka viņš neierauga, ka jūsu vaigi vājāki nekā to citu jaunekļu, kas jūsu vecumā. Tad jūs pār manu galvu vestu gatavu nāvi no ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Bet Daniēls sacīja uz to barības sargu, ko kambarjunkuru uzraugs bija iecēlis pār Daniēli, Ananiju, Mišaēli un Azariju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Raugi jel saviem kalpiem dot kādas desmit dienas zemes augļus ēst un ūdeni dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Un tad lai apskata, kāds mūsu ģīmis būs tavā priekšā, un kāds to jaunekļu ģīmis, kas ķēniņa ēdienu ēd, un dari tad ar saviem kalpiem, kā tu pats redzēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Un viņš tiem paklausīja šinī lietā un raudzīja desmit dienas ar tiem tā darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Un pēc desmit dienām tas atrada viņu izskatu skaistāku un viņu miesas pilnīgākas, nekā visu citu jaunekļu, kas ēda no ķēniņa ēdiena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Tad tas barības sargs atņēma to viņiem nospriesto ēdienu un vīnu un tiem deva ēst zemes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Un šiem četriem jaunekļiem Dievs deva zināšanu un saprašanu visādā rakstā un gudrībā, bet Daniēlim viņš deva saprast visādas parādīšanas un sapņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Un kad tas laiks bija pagājis, ko ķēniņš bija pavēlējis, viņus priekšā vest, tad kambarjunkuru uzraugs tos veda pie Nebukadnecara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Un ķēniņš ar tiem runāja, bet starp visiem neatradās neviena tāda, kā Daniēls, Ananija, Mišaēls un Azarija, un tie kalpoja ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Un visādā gudrībā un zināšanā, ko ķēniņš tiem jautāja, viņš tos atrada desmitkārt pārākus nekā visus zīlniekus un vārdotājus pa visu savu valsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Un Daniēls tur palika līdz ķēniņa Kirus pirmam gadam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Un Nebukadnecara valdīšanas otrā gadā Nebukadnecars redzēja sapņus. No tām viņa gars iztrūcinājās, ka viņš no miega uzmodās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Un ķēniņš pavēlēja, atsaukt tos gudros un vārdotājus un pareģus un Kaldejus, lai tie ķēniņam izstāstītu viņa sapņus. Un tie nāca un stāvēja ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Un ķēniņš uz tiem sacīja: es esmu redzējis sapni, un mans gars ir iztrūcināts, un es gribu to sapni zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Tad tie Kaldeji uz viņu sacīja kaldejiski: lai ķēniņš dzīvo mūžīgi! Saki saviem kalpiem to sapni, tad mēs to izstāstīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Ķēniņš atbildēja un sacīja uz tiem Kaldejiem: mans vārds ir teikts: ja jūs man nedarīsiet zināmu to sapni un kā viņš izstāstāms, tad jūs tiksiet sasisti gabalos, un jūsu namus darīs par mēslu čupu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Bet ja jūs man darīsiet zināmu to sapni un kā tas izstāstāms, tad jūs dabūsiet dāvanas un mantas un lielu godu no manis; tādēļ darāt man zināmu to sapni un kā tas izstāstāms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Tie atbildēja otru reiz\' un sacīja: lai ķēniņš saka saviem kalpiem to sapni, tad mēs to izstāstīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Ķēniņš atbildēja un sacīja: tiešām, es nomanu, ka jūs tikai laiku gribat vilcināt; jo jūs redzat, ka mans vārds ir teikts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Bet ja jūs man to sapni nesakāt, tad jums nāks tā nospriestā sodība, tāpēc ka jūs esat apņēmušies manā priekšā runāt melus un nieku vārdus, tiekams laiks paiet. Tāpēc sakāt man to sapni, tad es atzīšu, ka jūs arī varēsiet man to izstāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Tie Kaldeji ķēniņam atbildēja un sacīja: neviena cilvēka nav virs zemes, kas ķēniņam to lietu varētu sacīt, un nav bijis neviens liels un varens ķēniņš, kas tādu lietu būtu prasījis no kāda zīlnieka vai vārdotāja vai Kaldeja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Jo šī lieta, ko ķēniņš prasa, ir par daudz grūta, un cita neviena nav, kas ķēniņam to var darīt zināmu, kā tie dievi vien, kas pie cilvēkiem nedzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Par to ķēniņš palika dusmīgs un apskaitās ļoti un pavēlēja, visus gudros Bābelē nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Un pavēle izgāja, tos gudros kaut, un arī Daniēls un viņa biedri tapa meklēti, ka tos nokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Tad Daniēls gudri un prātīgi atbildēja Ariokam, ķēniņa pils karavīru virsniekam, kas bija izgājis, tos gudros Bābelē nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Viņš atbildēja un sacīja Ariokam, ķēniņa varenajam: Kāpēc tāda briesmīga pavēle no ķēniņa? Tad Arioks Daniēlim to lietu teica.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Un Daniēls gāja iekšā un lūdza ķēniņu, viņam laiku dot, ka ķēniņam to izstāstīšanu varētu sacīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Tad Daniēls nogāja savā namā un to sacīja Ananijam, Mišaēlim un Azarijam, saviem biedriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Lai tie no tā debesu Dieva žēlastību lūgtu par šo noslēpumu, ka Daniēls un viņa biedri ar tiem vēl atlikušiem gudriem Bābelē netiktu nokauti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Tad Daniēlim nakts parādīšanā tas noslēpums tapa parādīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Par to Daniēls teica to debesu Dievu, un Daniēls atbildēja un sacīja: slavēts lai ir Dieva vārds mūžīgi mūžam, jo Viņam pieder gudrība un spēks!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Jo Viņš pārceļ laikus un stundas, Viņš noceļ ķēniņus un ieceļ ķēniņus, Viņš gudriem dod gudrību un saprašanu prātīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Viņš parāda dziļas un apslēptas lietas, Viņš zin, kas ir tumsībā, jo pie Viņa mīt gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Es Tevi teicu un slavēju, manu tēvu Dievs, ka Tu man gudrību un spēku esi devis, un man nu esi darījis zināmu, ko mēs no Tevis esam lūguši, jo Tu mums ķēniņa lietu esi darījis zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Tad Daniēls nogāja pie Arioka, kam ķēniņš bija pavēlējis, tos gudros Bābelē nokaut, - viņš nogāja un tā uz viņu sacīja: nenokauj tos gudros Bābelē; ved mani pie ķēniņa iekšā, jo es ķēniņam to izstāstīšanu darīšu zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Tad Arioks steigšus ieveda Daniēli iekšā pie ķēniņa un runāja tā uz viņu: es esmu atradis vienu vīru no tiem atvestiem Jūdiem, kas ķēniņam grib sacīt to izstāstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Ķēniņš atbildēja un sacīja uz Daniēli, ko sauca par Beltsacaru: vai tu spēji man to sapni stāstīt, ko es esmu redzējis, un arī izstāstīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniēls atbildēja ķēniņa priekšā un sacīja: to noslēpumu, ko ķēniņš prasa, to tie gudrie, vārdotāji, zīlnieki un pareģi ķēniņam nevar sacīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Bet ir viens Dievs debesīs, kas parāda noslēpumus; Tas ķēniņam Nebukadnecaram dara zināmu, kas notiks nākamos laikos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tavs sapnis un kas tavam prātam uz gultas rādījās, ir šis: tu, ķēniņ, uz gultas gulēdams, domāji, kas pēcgalā notiks, un Tas, kas noslēpumus parāda, tev ir darījis zināmu, kas notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Man tad tas noslēpums ir parādīts ne caur manu gudrību tā kā tā man būtu lielāka nekā citiem, kas dzīvo, bet tāpēc, ka ķēniņam tā izstāstīšana taptu zināma, un tu savas sirds domas dabūtu zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Tu, ķēniņ, skatījies, un redzi, bija liels tēls; šis tēls bija varens un viņa spožums bija brīnišķīgs; tas stāvēja tavā priekšā un viņa izskats bija briesmīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Šī tēla galva bija no laba zelta, viņa krūtis un rokas no sudraba, viņa vēders un gurni bija no vara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Viņa lieli no dzelzs, viņa kājas bija puse no dzelzs un puse no māla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Šo tu redzēji, tiekams viens akmens taisījās vaļā bez rokām, tas sita to tēlu pie viņa dzelzs un māla kājām, un tās satrieca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Tad uz reizi tapa satriekti dzelzs, māls, varš, sudrabs un zelts, un tapa tāpat kā pelavas uz vasaras kloniem, un vējš tos aiznesa, tā ka vieta tiem netapa atrasta. Bet tas akmens, kas to bija sasitis, palika par lielu kalnu un piepildīja visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Šis ir tas sapnis. Nu mēs ķēniņam gribam sacīt viņa izstāstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Tu, ķēniņ, esi ķēniņš pār ķēniņiem, jo Tas debesu Dievs tev ir devis valdību, varu, spēku un godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Un visur, kur cilvēki dzīvo, Viņš lopus laukā un putnus apakš debess ir devis tavā rokā un tevi iecēlis par valdītāju pār to visu: tu esi tā zelta galva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Un pēc tevis celsies cita valsts, mazāka nekā tava. Pēc tās tā trešā valsts no vara; tā valdīs pār visu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Un tā ceturtā valsts būs cieta kā dzelzs. Jo itin kā dzelzs visu satriec un sadauza, tāpat kā dzelzs, kas sadauza, arī šī visas tās sadauzīs un satrieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Un ka tu esi redzējis tās kājas un viņu pirkstus pusi no podnieka māla un pusi no dzelzs, tā būs dalīta valsts; taču tur no dzelzs stipruma būs iekšā, tā kā tu esi redzējis dzelzi sajauktu ar podnieka māliem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Un tos kāju pirkstus pusi no dzelzs un pusi no māla - tā valsts būs uz pusi cieta un uz pusi gļēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Un kā tu esi redzējis dzelzi sajauktu ar podnieka māliem, - tie gan caur cilvēku sadzīvi sajauksies, bet viens pie otra nepielips, itin kā dzelzs nesajaucās ar māliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Un šo ķēniņu laikā tas debesu Dievs uzcels valstību, kas mūžīgi netaps izpostīta, un šī valstība netaps atdota nevienai citai tautai; tā satrieks un iznīcinās visas valstis, bet pati viņa pastāvēs mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Tāpēc tu esi redzējis, ka no kalna akmens bez rokām attaisījās vaļā, kas satrieca to dzelzi, varu, mālu, sudrabu un zeltu. Tas lielais Dievs ķēniņam ir darījis zināmu, kas pēc šim notiks. Šis ir tiešām tas sapnis un viņa izstāstīšana ir patiesīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Tad ķēniņš Nebukadnecars nometās uz savu vaigu un pielūdza Daniēli un pavēlēja, lai tam nes ēdamus un kvēpināmus upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Un ķēniņš atbildēja Daniēlim un sacīja: tas ir tiešām tiesa, ka jūsu Dievs ir Dievs pār visiem dieviem un Kungs pār ķēniņiem, un parāda noslēpumus, tāpēc ka tu šo noslēpumu varējis izstāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Tad ķēniņš Daniēli paaugstināja un tam deva daudz lielas dāvanas un to iecēla par valdītāju pār visu Bābeles valsti un par virsnieku pār visiem Bābeles gudriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Un Daniēls lūdza ķēniņu, un tas iecēla Sadrahu, Mesahu un AbedNegu par valdniekiem pār Bābeles valsti. Bet Daniēls palika ķēniņa pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Ķēniņš Nebukadnecars lika taisīt tēlu no zelta; tam bija augstums sešdesmit olektis, un platums sešas olektis; to viņš uzcēla Bābeles valstī, Duras klajumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Un ķēniņš Nebukadnecars sūtīja un sapulcināja lielkungus, valdītājus, zemes soģus, tiesas kungus, uzraugus, runas kungus, tiesnešus un visus valsts valdniekus, ka tie nāktu, to tēlu iesvētīt, ko ķēniņš Nebukadnecars bija uzcēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Tad sanāca tie lielkungi, valdītāji, zemes soģi, tiesas kungi, uzraugi, runas kungi, tiesneši un visi valsts valdnieki uz šī tēla iesvētīšanu, ko ķēniņš Nebukadnecars bija uzcēlis, un tie stāvēja tā tēla priekšā, ko Nebukadnecars bija uzcēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Un tas izsaucējs izsauca ar stipru balsi: jums top piekodināts, jūs tautas, ļaudis un valodas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Kad jūs dzirdēsiet bazūnes skaņu un trumetes, kokles, vijoles, somastabules, jaukas dziesmas un visādus mūzikas rīkus, tad jums būs nomesties un to zelta tēlu pielūgt, ko ķēniņš Nebukadnecars uzcēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Un kas nenometīsies un nepielūgs, tas tai pašā stundā taps iemests degošā ceplī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Kad nu visi ļaudis dzirdēja bazūnes skaņu un trumetes, kokles, vijoles, somastabules un visādus mūzikas rīkus, tad visi ļaudis, tautas un valodas nometās un pielūdza to zelta tēlu, ko ķēniņš Nebukadnecars bija uzcēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Tai pašā laikā kādi Kaldeju vīri piegāja un apsūdzēja Jūdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Tie iesāka un sacīja uz ķēniņu Nebukadnecaru: lai ķēniņš dzīvo mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Tu, ķēniņ, esi pavēlējis, ka visiem cilvēkiem, kad tie dzird bazūnes skaņu un trumetes, kokles, vijoles, somastabules, jaukas dziesmas un visādus mūzikas rīkus, būs nomesties un to zelta tēlu pielūgt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Un ka to, kas pie zemes nenometīsies un nepielūgs, būs iemest degošā ceplī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Te ir Jūdu vīri, ko tu esi iecēlis par Bābeles valsts valdniekiem, Sadrahs, Mesahs un AbedNegus, šie vīri neliek vērā, ko tu, ķēniņ, esi pavēlējis, un negodā tavus dievus un nepielūdz to zelta tēlu, ko tu esi uzcēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Tad Nebukadnecars ar dusmām un bardzību pavēlēja atvest Sadrahu, Mesahu un AbedNegu. Un tie vīri tapa atvesti ķēniņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Tad Nebukadnecars iesāka un uz tiem sacīja: vai jūs, Sadrah, Mesah un AbedNegu, tīši manus dievus necienījāt un to zelta tēlu nepielūdzāt, ko es esmu uzcēlis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nu tad, taisāties, kad jūs dzirdēsiet bazūnes skaņu un trumetes, kokles, vijoles, somastabules, jaukas dziesmas un visādus mūzikas rīkus, tad nometaties un pielūdziet to tēlu, ko es esmu taisījis, bet ja jūs to nepielūgsiet, tad jūs tai pašā stundā tapsiet iemesti degošā ceplī; jo kurš ir tas Dievs, kas jūs no manām rokām varētu izpestīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Tad Sadrahs, Mesahs un AbedNegus atbildēja un sacīja uz ķēniņu Nebukadnecaru: mums nevajag uz šo lietu atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Redzi, mūsu Dievs, ko mēs godājam, gan ir varens mūs izglābt no degoša cepļa un mūs arī izpestīt no tavas rokas, ak ķēniņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Un jebšu Viņš to arī nedarītu, taču tev būs zināt, ka mēs tavus dievus negribam godāt nedz pielūgt to zelta tēlu, ko tu esi taisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Tad Nebukadnecars apskaitās, un viņa vaiga izskats pārvērtās pret Sadrahu, Mesahu un AbedNegu, un viņš atbildēja un pavēlēja, cepli septiņkārt karstāku kurināt nekā to mēdza kurināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Un viņš pavēlēja tiem stiprākiem vīriem, kas bija viņa karaspēkā, siet Sadrahu, Mesahu un AbedNegu un iemest degošā ceplī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Tā šie vīri tapa saistīti ar saviem mēteļiem, kurpēm, cepurēm un citām drēbēm un iemesti degošā ceplī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Kad nu ķēniņa vārds drīz bija jāizdara un ceplis bija briesmīgi karsts, tad tās liesmas nomaitāja tos vīrus, kas Sadrahu, Mesahu un AbedNegu iemeta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Bet tie trīs vīri, Sadrahs, Mesahs un AbedNegus, iekrita saistīti tai degošā ceplī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Tad ķēniņš Nebukadnecars iztrūcinājās un pacēlās ātri un sacīja uz saviem runas kungiem: vai mēs neesam trīs vīrus saistītus metuši ugunī? Tie atbildēja un sacīja uz ķēniņu: tā tas ir, kungs ķēniņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Viņš atbildēja un sacīja: raugi, es redzu četrus vīrus vaļā staigājam ugunī, un tiem nekas nekaiš un tā ceturtā izskats ir kā kādam dievu dēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Tad Nebukadnecars piegāja pie tā degošā cepļa durvīm, iesāka un sacīja: Sadrah, Mesah un AbedNegu, jūs tā visuaugstākā Dieva kalpi, izejiet ārā un nāciet šurp. Tad Sadrahs, Mesahs un AbedNegus izgāja no uguns ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Un tie lielkungi, valdītāji, zemes soģi un ķēniņa runas kungi sapulcinājās, šos vīrus apraudzīt, ka uguns viņu miesas nebija pārvarējis, un ka viņu galvas mati nebija apsviluši, un viņu mēteļi nebija aizskarti, ka arī nekāda deguma smaka pie tiem netapa saosta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Tad Nebukadnecars iesāka un sacīja: slavēts lai ir Sadraha, Mesaha un AbedNegus Dievs, kas Savu eņģeli sūtījis un Savus kalpus atpestījis, kas uz Viņu paļāvušies un pārkāpuši ķēniņa vārdu un savas miesas nodevuši, lai citu dievu ne godātu nedz pielūgtu kā vien savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Tādēļ es pavēlu, ka visus ļaudis, tautas un mēles, kas Sadraha, Mesaha un AbedNegus Dievu zaimo, būs sasist gabalos un viņu namus darīt par mēslu čupu. Jo cita tāda Dieva nav, kas tā varētu atpestīt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Un ķēniņš Sadraham, Mesaham un AbedNegum deva lielu varu Bābeles valstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Ķēniņš Nebukadnecars visiem ļaudīm, tautām un mēlēm, kas dzīvo pa visu zemi: miers lai jums ir papilnam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Man ir paticis izsludināt tās zīmes un tos brīnumus, ko tas visuaugstākais Dievs pie manis darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Jo Viņa zīmes ir lielas un Viņa brīnumi ir vareni, Viņa valstība ir mūžīga valstība un Viņa valdīšana paliek līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Es, Nebukadnecars, dzīvoju droši savā namā un laimīgi savā pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Tad es redzēju sapni, kas mani izbiedēja, un tās domas, ko es savā gultā domāju, un manas galvas parādīšanas mani iztrūcināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Un es pavēlēju visus Bābeles gudros atvest manā priekšā, lai tie man teiktu šī sapņa izstāstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Tad tie gudrie, vārdotāji, Kaldeji un pareģi atnāca, un es tiem teicu to sapni, bet tie man to neizstāstīja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Tiekams pēdīgi manā priekšā nāca Daniēls, ko sauc par Beltsacaru pēc mana dieva vārda un iekš kā ir to svēto dievu gars, un es tam teicu to sapni:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Beltsacar, gudro virsniek, par ko es zinu, ka svēto dievu gars ir iekš tevis, un nekāds noslēpums tev nav grūts, tad saki nu mana sapņa parādīšanu, ko es esmu redzējis, un viņa izstāstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Bet tas ir, kas manam prātam rādījās uz manas gultas. Es skatījos, un redzi, viens koks bija zemes vidū, un tas bija ļoti augsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Tas koks bija liels un resns, un viņa augstums sniedzās līdz debesīm, un tas bija redzams līdz pasaules galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Viņa zari bija skaisti, un viņa augļi bagāti, un barība tam bija priekš visiem; zemes zvēri apakš viņa atrada pavēni, un putni apakš debess dzīvoja uz viņa zariem, un visa miesa no tā barojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Un es redzēju savas galvas parādīšanā uz savas gultas, un raugi, svēts sargs nonāca no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Tas sauca ar spēku un sacīja tā: nocērtiet to koku un apcērtiet viņa zarus un noplūciet viņa lapas un izkaisiet viņa augļus, lai zvēri apakš viņa aizbēg un putni no viņa zariem aizskrien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Bet to celmu ar saknēm atstājiet zemē, bet vara un dzelzs pinekļos, lauka zālē, lai viņš no debess rasas top slacināts, un viņa daļa lai ir kā lopiem zāle laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Viņa sirds lai top pārvērsta, ka vairs nav cilvēka sirds, un lopa sirds lai viņam top dota, kamēr septiņi laiki paiet pār viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Tas ir to sargu padoms, kas top sludināts, to svēto spriedums ir tā lieta; lai, kas dzīvo, atzīst, ka tam Visuvaldītājam vara ir pār cilvēku valstību, un viņš to dod, kam gribēdams, un pār to ieceļ to zemāko starp cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Šo sapni es, ķēniņš Nebukadnecars, esmu redzējis. Tu tad, Beltsacar, izstāsti to, tādēļ ka visi manas valsts gudrie man to nevar izstāstīt, bet tu to gan māki, tāpēc ka svēto dievu gars ir iekš tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Tad Daniēls, kam Beltsacars vārdā, iztrūcinājās vienu stundu, un viņa domas viņu izbiedēja. Tad ķēniņš iesāka un sacīja: Beltsacar, lai tas sapnis un viņa izstāstīšana tevi neizbiedē. Beltsacars atbildēja un sacīja: mans kungs, šis sapnis lai notiek taviem ienaidniekiem un viņa izstāstīšana taviem pretiniekiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Tas koks, ko tu esi redzējis tik lielu un resnu, un kura augstums sniedzās līdz debesīm, un kas bija redzams pa visu pasauli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Un kura zari skaisti, un kam bija daudz augļu, un kur barība bija priekš visiem, apakš tā lauka zvēri dzīvoja, un kura zaros putni apakš debess ligzdas taisīja, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Tas tu esi, ķēniņ, kas palicis liels un stiprs, jo tava augstība ir tā augusi, ka tā sniedzās līdz debesīm, un tava valstība iet līdz pasaules galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Ka nu ķēniņš vienu sargu, vienu svētu, redzējis no debesīm nākam un sakām: nocērtiet to koku un samaitājiet viņu, bet atstājiet to celmu ar saknēm zemē, bet vara un dzelzs pinekļos laukā zālē, ka viņš no debess rasas top slacināts, un viņa daļa lai ir ar lopiem uz lauka, tiekams septiņi laiki pār viņu paiet; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Šī ir tā izstāstīšana, kungs ķēniņ, un šis ir tā Visuaugstākā padoms, kas nāks pār manu kungu, ķēniņu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Tu tapsi izstumts no cilvēkiem un dzīvosi pie lopiem laukā, un tev dos ēst zāli kā vēršiem, un debess rasa tevi slacinās, un septiņi laiki paies pār tevi, tiekams tu atzīsti, ka tam Visuaugstākam vara ir pār cilvēku valstīm, tās dot, kam Viņš grib.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Bet kā ir sacīts, lai to celmu ar tā koka saknēm atstāj zemē: tava valsts tev pastāvēs, kad būsi atzinis, ka tas debesu Dievs valda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Tādēļ, kungs ķēniņ, lai tev mans padoms patīk, un atsvabinājies no saviem grēkiem caur taisnību un no saviem noziegumiem caur žēlastību pret nabagiem, redzi, vai varbūt tava labklāšanās nepastavēs vēl ilgāki. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Tas viss uzgāja ķēniņam Nebukadnecaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Jo pēc divpadsmit mēnešiem, kad Viņš staigāja ķēniņa pilī Bābelē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Tad viņš, tas ķēniņš, runāja un sacīja: vai šī nav tā lielā Bābele, ko es esmu uztaisījis ķēniņam par mājokli caur savas varas stiprumu un par savas augstības godību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Šis vārds vēl bija ķēniņa mutē, tad balss no debesīm krita: tev, ķēniņ Nebukadnecar, top sacīts: tava valdība no tevis ir atņemta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Un tu no cilvēkiem tapsi izstumts un tava dzīve būs pie lopiem laukā, tev dos zāli ēst kā vēršiem, un tā paies septiņi laiki, tiekams tu atzīsti, ka tam Visuaugstākam vara ir pār cilvēku valstīm, un viņš tās dod kam gribēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Tai pašā stundā šis vārds notika par Nebukadnecaru, un viņš no cilvēkiem tapa izstumts un ēda zāli kā vērši, un viņa miesas no debess rasas tapa slacinātas, tiekams viņa mati auga kā ērgļu spalvas un viņa nagi kā putnu nagi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Un pēc šā laika es, Nebukadnecars, pacēlu savas acis pret debesīm, jo mana saprašana man nāca atpakaļ, un es teicu to Visuaugstāko un slavēju un pagodināju to, kas dzīvo mūžīgi, tāpēc ka Viņa valdība ir mūžīga valdība, un Viņa valstība paliek līdz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Un visi zemes iedzīvotāji ir tā kā nekas, un Viņš dara pēc sava prāta ar debesu spēku un ar zemes iedzīvotājiem, un neviena nav, kas Viņa roku varētu aizturēt, vai uz Viņu sacīt: ko Tu dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Tanī laikā mans prāts man nāca atpakaļ ir mana valsts godība, mana augstība un mans spožums man nāca atpakaļ un mani runas kungi un varenie mani meklēja un es atkal tapu iecelts savā valstībā, un dabūju vēl lielāku godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Nu es, Nebukadnecars, slavēju un paaugstināju un pagodināju to debesu Ķēniņu, jo visi Viņa darbi ir patiesība un Viņa ceļi taisnība, Viņš ir varens, tos pazemot, kas lepnībā staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Ķēniņš Belsacars taisīja lielas dzīres saviem tūkstoš virsniekiem un dzēra vīnu ar tiem tūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Kad nu Belsacars vīnu bija baudījis, tad viņš pavēlēja, atnest tos zelta un sudraba traukus, ko viņa tēvs Nebukadnecars bija paņēmis no Jeruzālemes Dieva nama, ka ķēniņš un viņa varenie un viņa sievas un viņa liekās sievas no tiem dzertu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Tā tie zelta trauki tapa atnesti, kas no Jeruzālemes Dieva nama bija ņemti, un ķēniņš un viņa varenie un viņa sievas un viņa liekās sievas no tiem dzēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Tie dzēra vīnu un slavēja tos zelta un sudraba, vara, dzelzs, koka un akmens dievus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Tai pašā acumirklī tur iznāca cilvēka rokas pirksti, tie rakstīja pretim lukturim uz ķēniņa pils balto sienu, un ķēniņš redzēja tās rokas pirkstus, kas rakstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Tad ķēniņa ģīmis palika bāls un viņa domas to iztrūcināja, un viņa gurni nogura; un viņa lieli drebēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Un ķēniņš brēca stipri, lai atved tos vārdotājus, Kaldejus un pareģus; un ķēniņš iesāka un sacīja uz Bābeles gudriem: kas šos rakstus lasīs un tos man izstāstīs, tas taps apģērbts ar purpuru, ar zelta ķēdi ap kaklu, un viņš būs par trešo valdītāju šinī valstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Tad visi ķēniņa gudrie nāca iekšā, bet tie tos rakstus nevarēja lasīt, nedz ķēniņam tos izstāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Tad ķēniņš Belsacars ļoti iztrūcinājās, un viņa ģīmis palika bāls, un viņa varenie izbijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Kad ķēniņiene dzirdēja ķēniņa un viņa vareno vārdus, tad tā iegāja tai istabā, kur tās dzīres bija, un ķēniņiene runāja un sacīja: lai ķēniņš dzīvo mūžīgi, un lai tavas domas tevi neizbiedē, un lai tavs ģīmis nav bāls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Te ir viens vīrs tavā valstī, iekš tā ir to svēto dievu gars, jo tava tēva laikā pie viņa atrasts gaišums un saprašana un gudrība, itin kāda ir dievu gudrība, un tavs tēvs Nebukadnecars to iecēla par virsnieku tiem gudriem, vārdotājiem, Kaldejiem un pareģiem, tavs tēvs, ak ķēniņ!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Tādēļ ka augsts gars pie tā tapa atrasts un saprašana, izstāstīt sapņus un uzminēt mīklas un izsacīt noslēpumus, proti pie Daniēla, ko ķēniņš lika nosaukt Belsacaru. Aicini nu Daniēli, tas tev to izstāstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Tad Daniēls tapa atvests ķēniņa priekšā. Un ķēniņš iesāka un sacīja uz Daniēli: vai tu esi Daniēls, viens no tiem atvestiem Jūdiem, ko ķēniņš, mans tēvs, no Jūda ir atvedis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Es par tevi esmu dzirdējis, ka dievu gars ir iekš tevis, un ka gaisma un saprašana un liela gudrība pie tevis atrodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nu manā priekšā ir atvesti tie gudrie un vārdotāji, šos rakstus lasīt un man darīt zināmu viņu izstāstīšanu, bet tie man tos vārdus nav varējuši izstāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Bet par tevi es esmu dzirdējis, ka tu mākot izstāstīt un noslēpumus izsacīt. Nu tad, ja tu šos rakstus māki lasīt un man izstāstīt, tad tu tapsi apģērbts ar purpuru un ar zelta ķēdi ap savu kaklu un būsi tas trešais valdītājs šinī valstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Tad Daniēls atbildēja un sacīja ķēniņa priekšā: paturi sev savas dāvanas un dod savas mantas citam; bet es tomēr tos rakstus ķēniņam lasīšu un viņam tos izstāstīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Kungs ķēniņ! Dievs, tas visuaugstais tavam tēvam Nebukadnecaram ir devis valstību un varu, godu un augstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Un tās augstības dēļ ko viņš tam bija devis, drebēja un trīcēja visi ļaudis, visas tautas un mēles viņa priekšā. Ko gribēja, to viņš nokāva, un ko gribēja, to viņš paturēja dzīvu, un ko gribēja, to viņš paaugstināja, un ko gribēja, to viņš pazemoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Bet kad viņa sirds metās lepna, un viņa gars apcietinājās līdz pārgalvībai, tad viņš no savas valstības krēsla tapa nostumts un viņa gods tapa atņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Un viņš no cilvēku bērniem tapa izstumts, un viņa sirds palika kā lopa sirds, un viņam bija jādzīvo pie meža ēzeļiem, un zāle jāēd kā vēršiem, un viņa miesa no debess rasas tapa slacināta, tiekams viņš atzina, ka tas visu augstākais Dievs ir valdītājs pār cilvēku valstīm un ieceļ pār tām, kuru gribēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Un tu, Belsacar, viņa dēls, neesi pazemojis savu sirdi, jebšu tu visu gan labi esi zinājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Bet esi cēlies pret to debesu Kungu, un Viņa nama trauki ir atnesti tavā priekšā, un tu un tavi varenie un tavas sievas un tavas liekās sievas no tiem esat vīnu dzēruši un slavējuši tos sudraba un zelta, vara, dzelzs, koka un akmens dievus, kas nedz redz nedz dzird nedz saprot; bet to Dievu, kam rokā tava dvaša un pie kā stāv visi tavi ceļi, Tam tu neesi godu devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Tad tās rokas pirksti no viņa ir sūtīti un šie raksti rakstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Un šis ir tas raksts, kas rakstīts: Mene, Mene, Teķel Parsin.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Un šī ir to vārdu izstāstīšana: Mene: - Dievs tavu valstību skaitījis un dara tai galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Teķel: - tu svaru kausā esi svērts un esi atrasts visai viegls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres: - tava valstība ir dalīta un Mēdiešiem un Persiešiem dota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Tad Belsacars pavēlēja, un tie apģērba Daniēli ar purpuru un ar zelta ķēdi ap kaklu, un izsauca par viņu, ka viņš tas trešais valdnieks valstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Bet tai pašā naktī Kaldeju ķēniņš Belsacars tapa nokauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Un Dārijs, tas Medietis, uzņēma valdību, sešdesmit un divus gadus vecs būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Un Dārijam patika, iecelt pār valsti simts un divdesmit valdniekus, kas lai būtu pār visu valsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Un pār tiem atkal trīs virsniekus, kuru starpā Daniēls bija tas pirmais; tiem tie valdnieki deva atbildēšanu, lai ķēniņam nebūtu rūpes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Bet Daniēls bija pārāks par visiem virsniekiem un valdniekiem, tāpēc ka gudrs gars bija iekš viņa, un ķēniņš nodomāja viņu iecelt pār visu valsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Tad tie virsnieki un valdnieki meklēja iemeslus pret Daniēli tās valdības dēļ. Bet tie nekādu iemeslu nedz vainu nevarēja atrast, jo viņš bija uzticīgs, ka nekādu noziegumu nedz vainu pie viņa neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Tad tie vīri sacīja: mēs neatradīsim pret Daniēli nekādus iemeslus, ja mēs pret viņu nekā neatrodam viņa Dieva kalpošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Tad tie virsnieki un valdnieki nāca lielā pulkā pie ķēniņa un tā uz viņu sacīja: lai ķēniņš Dārijs dzīvo mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Visi valsts virsnieki, priekšnieki, valdnieki, runas kungi un zemes soģi ir sarunājušies, ka ķēniņam būtu jāceļ likums un jāizlaiž stipra pavēle, ka ikviens, kas pa trīsdesmit dienām ko laba lūgs no kaut kāda dieva vai cilvēka, bez vien no tevis, kungs ķēniņ, taptu iemests lauvu bedrē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Nu tad, kungs ķēniņ, apstiprini šo pavēli, un raksti to grāmatā, ka tā netop pārgrozīta, pēc Mēdiešu un Persiešu neatsaucamiem likumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Tad ķēniņš Dārijs rakstīja tādu grāmatu un pavēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Kad nu Daniēls dzirdēja, tādu grāmatu esam rakstītu, tad viņš gāja savā namā, bet viņam bija savā augšistabā atvērti logi pret Jeruzālemi, un viņš par dienu trīs reiz metās ceļos, lūdza, teica un pateicās savam Dievam, tā kā viņš arvienu mēdza darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Tad tie vīri nāca lielā pulkā un atrada Daniēli lūdzam un savu Dievu piesaucam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Un tie piegāja un runāja ķēniņa priekšā par ķēniņa pavēli: vai tu, ak ķēniņ, neesi likumu rakstījis, ka ikviens, kas pa trīsdesmit dienām no kaut kāda dieva vai cilvēka ko laba lūgs, bez vien no tevis, ķēniņ, taptu iemests lauvu bedrē? Ķēniņš atbildēja un sacīja: tas ir tiesa pēc Mēdiešu un Persiešu neatsaucamiem likumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Tad tie atbildēja un sacīja ķēniņa priekšā: Daniēls, viens no tiem atvestiem Jūdiem, ķēniņ, nav licis vērā ne tevi, ne tavu pavēli, ko tu esi rakstījis, jo viņš lūdz trīsreiz par dienu savu lūgšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Šo valodu dzirdējis, ķēniņš ļoti noskuma un nodarbojās no visas sirds, ka viņš Daniēli izpestītu; - tiekams saule nogāja, viņš to meklēja izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Bet tie vīri nāca lielā pulkā ķēniņa priekšā un sacīja uz ķēniņu: tu zini, kungs ķēniņ, ka Mēdiešu un Persiešu likumi ir tādi, ka nevienu pavēli, ne likumu, ko ķēniņš ir iecēlis, nevar pārgrozīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Tad ķēniņš pavēlēja, Daniēli atvest un iemest lauvu bedrē, un ķēniņš iesāka un sacīja uz Daniēli: tavs Dievs, ko tu bez mitēšanās godā, Tas lai tevi izpestī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Un akmens tapa atnests un likts uz bedres caurumu; to ķēniņš aizzieģelēja ar savu gredzenu un ar savu lielkungu gredzenu, ka tas spriedums par Daniēli netaptu pārgrozīts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Tad ķēniņš nogāja uz savu pili un palika cauru nakti neēdis un nelika sev celt priekšā barību un nevarēja arī gulēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'No rīta agri, ar mazu gaismiņu, ķēniņš cēlās un gāja steigšus pie lauvu bedres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Un pie bedres nācis, viņš Daniēli sauca ar noskumušu balsi: ķēniņš sauca un sacīja uz Daniēli: Daniēl, tu dzīvā Dieva kalps, vai tavs Dievs, ko tu bez mitēšanās godā, tevi varējis izpestīt no lauvām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Tad Daniēls sacīja uz ķēniņu: lai ķēniņš dzīvo mūžīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Mans Dievs savu eņģeli sūtījis, tas lauvām aizturējis rīkli, ka tie mani nav ievainojuši, tāpēc ka viņa priekšā esmu atrasts nenoziedzīgs un arī pret tevi, kungs ķēniņ, es nekā ļauna neesmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Tad ķēniņš palika priecīgs un pavēlēja Daniēli no bedres izvilkt; un kad Daniēls no bedres tapa izvilkts, tad nekādas vainas pie viņa neatrada, tāpēc ka viņš savam Dievam bija uzticējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Un ķēniņš pavēlēja, tos vīrus atvest, kas Daniēli bija apsūdzējuši, un tos meta lauvu bedrē līdz ar viņu bērniem un sievām, un tie vēl nenonāca dibenā, tad jau tie lauvas tos sagrāba un satrieca visus viņu kaulus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Tad ķēniņš Dārijs rakstīja visiem ļaudīm, visām tautām un mēlēm, kas visapkārt virs zemes: miers lai jums vairojās!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'No manis nāk pavēle, ka visās manas valsts tiesās būs bīties un drebēt priekš Daniēla Dieva, jo Viņš ir tas dzīvais Dievs un pastāvīgs mūžīgi, un Viņa valstība nav nīcīga un Viņa valdībai nav gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Viņš atpestī un izglābj un dara brīnumus un zīmes debesīs un virs zemes; tas Daniēli izpestījis no lauvu varas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Un šis Daniēls palika varens Dārija valstī un arī Kirus, Persiešu ķēniņa, valstī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Belsacara, Bābeles ķēniņa, pirmā gadā Daniēls redzēja sapni un savas galvas parādīšanas uz savas gultas. Tad viņš to sapni uzrakstīja, stāstīdams tās svarīgās lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniēls iesāka un sacīja: es redzēju savā parādīšanā naktī, un raugi, tie četri debess vēji lauzās uz lielo jūru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Un četri lieli zvēri izkāpa no jūras, ikkatrs savu izskatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Pirmais bija kā lauva, un tam bija kā ērgļu spārni. Es skatījos, tiekams viņam spārni tapa izrauti un tas no zemes tapa uzcelts un stāvēja uz kājām kā cilvēks, un tam tapa dota cilvēka sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Un redzi, tur bija cits zvērs itin kā lācis, tas stāvēja vienā malā, un tam bija trīs lieli zobi mutē starp saviem citiem zobiem, un uz to tapa tā sacīts: celies un ēd daudz gaļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Pēc tam es redzēju, un raugi, tur bija vēl cits zvērs itin kā pardelis(leopards), tam bija četri putnu spārni uz muguras, un šim zvēram bija četras galvas, un tam tapa dota vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Un pēc tam es redzēju nakts parādīšanās, un raugi, ceturtais zvērs, briesmīgs un negants un ļoti stiprs, un tam bija lieli dzelzs zobi, tas ēda un satrieca un to, kas atlika, tas samina ar kājām, un tas bija citāds nekā tie citi zvēri priekš viņa, un tam bija desmit ragi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Un es tos ragus liku vērā, un redzi, vēl viens mazs rags cēlās starp tiem, un viņa priekšā trīs no tiem pirmajiem ragiem tapa izlauzti, un redzi, tanī ragā bija acis kā cilvēka acis un mute, kas lielas lietas runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Es skatījos, tiekams krēsli tapa nolikti, un laiku Vecais apsēdās, kam drēbes bija baltas kā sniegs un galvas mati kā šķīsta vilna, Viņa krēsls bija kā uguns liesmas, un Viņa skrituļi bija degošs uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Un no Viņa priekšas iztecēja uguns upe. Tūkstošu tūkstoši Viņam kalpoja, un desmit reiz\' tūkstošu tūkstoši stāvēja Viņa priekšā; tiesa tapa turēta, un grāmatas tapa atvērtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Es skatījos tās lielās valodas dēļ, ko tas rags runāja, es skatījos, kamēr tas zvērs tapa nonāvēts un viņa miesa nokauta un nodota, ka ugunī taptu sadedzināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Arī tiem citiem zvēriem vara tapa atņemta, jo tiem bija laiks un stunda nolikta, cik ilgi tiem bija dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Es redzēju nakts parādīšanās, un raugi, viens nāca debess padebešos kā Cilvēka Dēls, un nāca pie tā laiku Vecā, un tapa vests Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Un Viņam tapa dota valdība un godība un valstība: visiem ļaudīm, visām tautām un valodām būs Viņam kalpot; Viņa valdība ir mūžīga valdība, kas neiznīkst un Viņa valstībai nav gala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Man, Daniēlim, sirds miesās nogura, un manas galvas parādīšanas mani iztrūcināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Es piegāju pie viena no tiem, kas tur stāvēja, un vaicāju no tā skaidru patiesību par visu to. Un viņš man to izteica un man izstāstīja šīs lietas:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Tie četri lielie zvēri ir četri ķēniņi, kas celsies virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Bet tā Visuaugstākā svētie iedabūs to valstību, un to turēs mūžīgi un mūžu mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Pēc tam es gribēju zināt skaidru patiesību par to ceturto zvēru, kas bija citāds nekā visi tie citi, ļoti briesmīgs, kam bija dzelzs zobi un vara nagi, kas rija un satrieca un to, kas atlika, samina ar savām kājām, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Un par viņa desmit ragiem uz viņa galvas, un par to vienu, kas cēlās, priekš kā trīs bija izkrituši, proti par to ragu, kam acis bija un mute, kas lielas lietas runāja, un kas bija lielāks, nekā tie citi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Es redzēju šo ragu karojam pret tiem svētiem un arī tos pārvaram,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Tiekams tas laiku Vecais nāca un tā Visuaugstākā svētiem nesa tiesu, un tas nospriestais laiks nāca, kur tiem svētiem bija iedabūt to valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Viņš sacīja tā: tas ceturtais zvērs būs tā ceturtā valsts virs zemes; tā būs citāda nekā visas citas valstis, un tā aprīs visu pasauli un to samīs un satrieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Un tie desmit ragi nozīmē, ka no tās valsts celsies desmit ķēniņi, un cits pēc tiem celsies, un tas būs jo varens nekā tie pirmaji un pazemos trīs ķēniņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Un tas runās vārdus pret to Visuaugstāko un postīs tā Visuaugstākā svētos un apņemsies pārgrozīt svētku laikus un bauslību, un tie viņam taps rokā doti vienu laiku un divus laikus un puslaiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Pēc tam tiesa taps turēta, un viņam vara atņemta, ka tas pagalam top izdeldēts un iznīcināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Bet tā valstība un valdība un augstība pār visām valstīm apakš visām debesīm taps dota tā Visuaugstākā svētiem ļaudīm; tā valstība būs mūžīga valstība, un visi varenie Viņam kalpos un Viņam paklausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Tas bija to vārdu gals. Bet es, Daniēls, savās domās tapu iztrūcināts, un mans ģīmis nobāla, un es tos vārdus paturēju savā sirdī');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Ķēniņa Belsacara trešā valdīšanas gadā man, Daniēlim, rādījās parādīšana, pēc tās, kas man papriekš bija parādījusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Un es skatījos tai parādīšanā, un notika, ka es skatīdamies biju Sūsanas pilī Elama valstī, un es skatījos tai parādīšanā, un es biju pie Ulaī upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Un es pacēlu savas acis un skatījos, redzi, auns stāvēja upes malā, tam bija divi ragi, un tie divi ragi bija augsti, un viens bija augstāks nekā otrs, un tas augstākais izcēlās vēlāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Es redzēju, ka tas auns ar saviem ragiem badīja pret vakariem un pret ziemeļa pusi un pret dienasvidu, un neviens zvērs pret viņu nevarēja pastāvēt, un neviens no viņa rokas neizglābās, bet viņš darīja, kas tam patika un paaugstinājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Un kamēr es to pārdomāju, redzi, tad āzis nāca no vakariem pār visu zemes virsu un neaizskāra zemi, un tam āzim bija skaists rags starp viņa acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Un tas nāca pie tā auna ar tiem diviem ragiem, ko es biju redzējis stāvam upes malā, un tas lauzās pret viņu ar stipru karstumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Un es redzēju, ka tas tuvu nāca pie tā auna un pret viņu apskaitās un badīja to aunu un salauza viņa divus ragus, un tam aunam nebija spēka, viņa priekšā pastāvēt, un viņš to nometa zeme un to samina, un neviena nebija, kas to aunu izglābtu no viņa rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Un tas āzis ļoti paaugstinājās, bet kad tas bija palicis stiprs, tad tas lielais rags salūza, un viņa vietā četri skaisti ragi izauga pret tiem četriem debess vējiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Un no viena no tiem iznāca viens mazs rags, tas tapa ļoti liels pret dienasvidu un pret rītiem un pret to mīlīgo zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Un tas tapa liels līdz debess pulkam un nometa kādus no tā pulka un no tām zvaigznēm zemē un tos samina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Un tas tapa liels līdz debess pulka valdniekam, un šim tapa atņemts tas dienišķais upuris, un viņa svētās vietas dzīvoklis tapa izpostīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Un karapulks tika nodots līdz ar dienišķo upuri apgrēkošanās dēļ, un tas (rags) nometa patiesību pie zemes, un ko viņš darīja, tas viņam izdevās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Un es dzirdēju vienu svētu runājam, un cits svēts sacīja uz to, kas runāja: uz cik ilgu laiku tad zīmējās tā parādīšana par to dienišķo upuri un par to briesmīgo grēku, ka ir tā svētā vieta, ir tas karapulks top nodoti samīšanai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Un viņš uz mani sacīja: divi tūkstoši un trīssimt dienas būs skaitāmas no vakara līdz rītam, tad tā svētā vieta atkal taps iesvētīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Un kad es, Daniēls, to parādīšanu redzēju, tad es to meklēju saprast, un redzi, tur stāvēja manā priekšā viens, no izskata kā vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Un es dzirdēju starp Ulaī upes (malām) cilvēka balsi, tā sauca un sacīja: Gabriel, izskaidro šim to parādīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Un viņš nāca tuvu, kur es stāvēju; un kad viņš nāca, tad es izbijos un kritu uz savu vaigu; un viņš uz mani sacīja: ņem vērā, cilvēka bērns, jo šī parādīšana iet uz pastara laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Kad viņš nu ar mani runāja, tad es nokritu pamiris pie zemes, bet viņš mani aizskāra un mani uzcēla stāvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Un viņš sacīja: redzi, es tev daru zināmu, kas notiks dusmības gala laikā; jo tas iet uz to nolikto laika galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Tas auns ar tiem diviem ragiem, ko tu esi redzējis, tie ir Mēdiešu un Persiešu ķēniņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Un tas sprogainais āzis ir Grieķu ķēniņš, un tas lielais rags starp viņa acīm, ir tas pirmais ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Un kad tas būs salūzis, tad četri nāks viņa vietā; četras valstis celsies no tās tautas, bet ne ar tādu spēku, kāds viņam bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Bet šīs valsts pastara laikā, kad tie atkāpēji augumā būs auguši, celsies nikns un izmanīgs ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Un viņa spēks būs stiprs, bet ne caur paša spēku, un viņš brīnišķi postīs un viņam laimēsies, un viņš to padarīs. Un viņš postīs tos varenos un to svēto tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Un caur viņa gudrību viltus viņa rokā tam izdosies, un viņš savā sirdī leposies un nejauši postīs lielu pulku, un celsies pretī tam valdnieku Valdniekam, bet viņš bez rokas taps salauzts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Un tas parādījums par vakaru un rītu, par ko runāts, ir patiesīgs un tu apslēp šo parādījumu, jo vēl ir ilgs laiks līdz tam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Un es, Daniēls, paliku vājš un biju kādas dienas slims. Tad es cēlos un darīju ķēniņa darbu, un iztrūcinājos par šo parādījumu, bet neviens to nemanīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Pirmā gadā, kad Dārijs, Ahasverus dēls, no Mēdiešu dzimuma, bija celts par ķēniņu Kaldeju valstī, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Viņa valdīšanas pirmā gadā, es, Daniēls, grāmatā ņēmu vērā to gadu skaitu, par ko Tā Kunga vārds caur pravieti Jeremiju bija noticis, ka Jeruzālemei pilnus septiņdesmit gadus jāstāv postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Un es griezu savu vaigu pie Dieva, Tā Kunga, Viņu meklēt ar lūgšanām un pielūgšanām, ar gavēšanu maisā un pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Un es pielūdzu To Kungu, savu Dievu, sūdzēju un sacīju: ak Kungs, stiprais Dievs, Tu lielais un bijājamais, kas derību un žēlastību turi tiem, kas Tevi mīl un tura Tavu bauslību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Mēs esam grēkojuši un netaisnību darījuši un bijuši bezdievīgi un esam pretī turējušies un atkāpušies no Taviem baušļiem un no Tavām tiesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Mēs arī neesam klausījuši Taviem kalpiem, tiem praviešiem, kas Tavā vārdā runājuši uz mūsu ķēniņiem, valdniekiem un mūsu tēviem un visiem zemes ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Tu, Kungs, esi taisns, bet mums jākaunas, kā tas šodien redzams, gan Jūda vīriem, gan Jeruzālemes iedzīvotājiem un visiem Israēla bērniem, kas tuvu un kas tālu pa visām zemēm, kur Tu tos esi izdzinis viņu pārkāpšanas dēļ, ar ko tie pret Tevi grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ak Kungs, mums jākaunas, ir mūsu ķēniņiem, valdniekiem un mūsu tēviem, ka mēs pret Tevi esam grēkojuši!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Bet pie Tā Kunga, mūsu Dieva, ir žēlastība un piedošana, jebšu mēs Viņam esam pretī turējušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Un neesam klausījuši Tā Kunga, sava Dieva balsi, staigāt Viņa bauslībā, ko Viņš mums bija devis caur Savu kalpu, to praviešu, roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Bet viss Israēls Tavu bausli ir pārkāpis un ir atkāpies, neklausīdams Tavu balsi. Tādēļ tas lāsts mums ir uzgājis, un kas ir zvērēts, kā rakstīts Dieva kalpa Mozus bauslībā, tāpēc ka mēs pret Viņu esam grēkojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Un Viņš savus vārdus ir stipri turējis, ko Viņš runājis pret mums un pret mūsu tiesas kungiem, kas mūs tiesāja, lielu ļaunumu pār mums vezdams, kāds nav noticis apakš visas debess, un kā nu noticis Jeruzālemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Kā stāv rakstīts Mozus bauslībā, tā viss tas ļaunums pār mums nācis. Un mēs Tā Kunga, sava Dieva, vaigu nepielūdzām, ka no grēkiem būtu atgriezušies un vērā likuši Tavu patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Tādēļ Tas Kungs ir modrīgs bijis ar ļaunumu un mums to uzvedis, jo Tas Kungs, mūsu Dievs, ir taisns visos Savos darbos, ko Viņš dara, bet mēs Viņa balsi neesam klausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Un nu, Kungs, mūsu Dievs, kas esi izvedis Savus ļaudis no Ēģiptes ar stipru roku un Sev vārdu esi darījis, kā tas vēl šodien ir, mēs esam grēkojuši, mēs esam bijuši bezdievīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ak Kungs, pēc visas Tavas taisnības lai jel Tava dusmība un bardzība nogriežas no Tavas Jeruzālemes pilsētas, no Tava svētā kalna. Jo mūsu grēku dēļ un mūsu tēvu noziegumu dēļ Jeruzāleme un tavi ļaudis tapuši kaunā priekš visiem, kas ap mums dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Un nu, mūsu Dievs, klausi Sava kalpa lūgšanu un viņa piesaukšanu, un apgaismo Savu vaigu pār Savu svēto vietu, kas ir postīta, Tevis paša dēļ, ak Kungs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Atgriez Savu ausi, ak Dievs, un klausi, atver Savas acis un uzlūko, kā mēs esam postīti, un to pilsētu, kas pēc Tava vārda nosaukta. Jo mēs nometamies ar savām lūgšanām Tavā priekšā, ne uz savu taisnību, bet uz Tavu lielo žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ak Kungs, klausi! Ak Kungs, piedod! Ak Kungs, ņem vērā un dari to un nekavējies Tevis paša dēļ, mans Dievs, jo Tava pilsēta un Tavi ļaudis pēc Tava vārda nosaukti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Kamēr es vēl runāju un lūdzos un savus grēkus un savu Israēla ļaužu grēkus sūdzēju un ar savu pielūgšanu nometos Tā Kunga, sava Dieva, priekšā sava Dieva svētā kalna dēļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Kamēr es tā lūgdamies vēl runāju, steigšus pie manis atskrēja tas vīrs Gabriēls, ko es pirmāk biju redzējis parādīšanā, un aizskāra mani ap vakara upura laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Un viņš mani mācīja un runāja ar mani un sacīja: Daniēl, tagad es esmu izgājis, tev mācīt saprašanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Kad tu sāki lūgt, tad šis vārds izgāja, un es esmu nācis, to pasludināt; jo tu esi ļoti mīļš. Tādēļ saproti to vārdu un ņem vērā to parādīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Septiņdesmit nedēļas ir nospriestas par tavu tautu un par tavu svēto pilsētu, aizslēgt atkāpšanos, aizzieģelēt grēkus, salīdzināt noziegumu, atvest mūžīgu taisnību, aizzieģelēt parādīšanas un praviešu vārdus un svaidīt visu svētāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Tādēļ zini un proti: kamēr tas vārds izgājis, Jeruzālemi atkal uzcelt un uztaisīt līdz vienam Svaidītam (Kristum), Valdniekam, ir septiņas nedēļas, un sešdesmit un divas nedēļas, tad atkal uzcels un uztaisīs ar ielām un grāvjiem, jebšu spaidu laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Un pēc tām sešdesmit un divām nedēļām Svaidītais (Kristus) tiks izdeldēts, bet ne Sevis dēļ. Un to pilsētu un svēto vietu izpostīs kāda valdnieka ļaudis, kas nāks un kam gals būs plūdos, un līdz pat galam būs karš un noliktā postīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Un viņš ar daudziem derību apstiprinās vienu nedēļu, un nedēļas vidū kaujamais un ēdamais upuris mitēsies, un viņš nāks ar negantības spārniem kā postītājs, kamēr noliktā sodība izgāžas un nobeidz postītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Kirus, Persiešu ķēniņa, trešā gadā Daniēlim, kas nosaukts Beltsacars, šī parādīšana tapa parādīta, un tas vārds ir patiesīgs un zīmē lielas bēdas, un viņš to lika vērā un saprata to parādīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Tanīs dienās es, Daniēls, biju noskumis cauras trīs nedēļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Gardas barības es neēdu, un ne gaļa ne vīns nenāca manā mutē, es arī nesvaidījos, tiekams trīs veselas nedēļas bija pagājušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Un pirmā mēneša divdesmit ceturtā dienā es biju Hideķeles lielupes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Un es pacēlu savas acis un skatījos, un redzi, tur bija vīrs nātnu(linu) drēbēs ģērbts, un viņa gurni bija apjozti ar šķīstu zeltu no Upas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Un viņa miesas bija kā krizolita akmens un viņa vaigs kā zibens un viņa acis kā degošas lāpas un viņa rokas un kājas kā degošs varš un viņa valodas balss kā trokšņa skaņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Un es, Daniēls, redzēju to parādīšanu viens pats, bet tie vīri, kas bija pie manis, to neredzēja, bet liela bailība tiem uzgāja, ka tie bēga un paslēpās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Es tad atliku viens pats un redzēju šo lielo parādīšanu, un pie manis spēka nepalika, un mans vaigs nejauki nobāla, un man spēka vairs neatlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Un es dzirdēju viņa valodas balsi, un kad es viņa valodas balsi dzirdēju, tad es nokritu pamiris uz savu vaigu pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Un redzi, roka mani aizskāra un palīdzēja, ka es pacēlos uz saviem ceļiem un uz savām rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Un viņš uz mani sacīja: Daniēl, tu mīļais vīrs, ņem vērā tos vārdus, ko es uz tevi runāšu, un celies stāvu, jo tagad es pie tevis esmu sūtīts. Un kad viņš to vārdu ar mani runāja, tad es cēlos trīcēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Un viņš uz mani sacīja: nebīsties, Daniēl! Jo no tās pirmās dienas, kad tu savā sirdī esi dzinies to saprast un esi mērdējies sava Dieva priekšā, tad tavi vārdi ir paklausīti, un es tavu vārdu dēļ esmu atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Bet Persiešu valsts valdnieks man stāvēja pretī divdesmit un vienu dienu, un redzi, Miķelis, viens no tiem pirmajiem valdniekiem, man nāca palīgā, tad es tur uzvarēju pie tiem Persiešu ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Nu es esmu nācis, tev ziņu dot, kas taviem ļaudīm notiks nākamā laikā, jo arī vēl šī parādīšana notiks pēc ilga laika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Un kad viņš šos vārdus ar mani runāja, tad es ar savu vaigu skatījos pie zemes un paliku klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Un redzi, viens, kas cilvēka bērniem bija līdzīgs, aizskāra manas lūpas. Tad es atdarīju savu muti un sacīju uz to, kas pie manis stāvēja: mans Kungs, par šo parādīšanu mani locekļi dreb, ka man spēka nepaliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Un kā šā sava kunga kalps var runāt ar šo savu kungu, jo no šī laika spēka pie manis nepaliek, un man arī dvašas neatliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Tad atkal viens mani aizskāra, kam bija cilvēka izskats, un mani spēcināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Un viņš sacīja: nebīsties, tu mīļais vīrs! Miers lai ir ar tevi! Un ņemies drošu, drošu prātu! Un viņam ar mani runājot, es atspirgu un sacīju: runā, mans Kungs, jo tu mani esi atspirdzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Tad viņš sacīja: vai tu zini, kāpēc es pie tevis esmu nācis? Es nu griezīšos atpakaļ, ar Persiešu valdnieku karot, un kad es būšu izgājis, tad nāks Grieķu valdnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Bet es tev stāstīšu, kas patiesības rakstos uzrakstīts; un neviena nav, kas mani pret viņiem spēcina, kā vien jūsu valdnieks Miķelis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Bet arī es, Dārija, tā Mēdieša, pirmajā(valdīšanas) gadā pie viņa stāvēju, viņu spēcināt un stiprināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Un nu es tev stāstīšu patiesību. Redzi, trīs ķēniņi vēl celsies Persiešu zemē, un tas ceturtais būs ļoti bagāts, vairāk nekā tie citi, un kad viņš savā bagātībā būs spēcinājies, tad viņš visu pazudinās pret Grieķu valsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Pēc celsies varens ķēniņš; tas valdīs ar lielu varu un darīs, kas viņam patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Un kad viņš tā stāvēs, tad viņa valsts salūzīs un taps dalīta pēc četriem debess vējiem, bet nenāks uz viņa pēcnākamiem, nedz ar tādu varu, ar ko viņš valdījis; jo viņa valsts taps izdeldēta un nāks citiem rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Un dienvidu ķēniņš paliks stiprs, bet viens no viņa valdniekiem būs jo stiprāks nekā viņš, un tas valdīs un viņa valstība būs liela valstība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Un pēc kādiem gadiem tie kopā apdraudzināsies, un dienvidu ķēniņa meita ies pie ziemeļa ķēniņa, mieru derēt, bet tai nepaliks elkoņa stiprums, un ne viņš, ne viņa elkonis nepastāvēs. Bet tā taps nodota līdz ar tiem, kas to bija atveduši, un līdz ar to, kas viņu dzemdinājis un kas viņu tanīs laikos stiprinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Bet viena atvase no viņas celma celsies viņa vietā, tas nāks pret to karaspēku un uzies ziemeļa puses ķēniņa stiprām pilīm, un tās pārvarēs un būs spēcīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Un arī viņu dievus un viņu elku tēlus ar viņu dārgiem sudraba un zelta traukiem viņš aizvedīs uz Ēģipti, un pastāvēs kādus gadus priekš ziemeļa ķēniņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Un gan viņš nāks dienvidu ķēniņa valstī, bet atkal griezīsies atpakaļ uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Bet viņa dēli taisīsies uz karu un sapulcinās lielu karaspēku, un tas nāks nākdams kā straume un plūdīs cauri, un nāks atkal atpakaļ un karos līdz viņa stiprām pilīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Un dienvidu ķēniņš apskaitīsies un celsies un karos ar viņu, ar ziemeļa ķēniņu, un šis gan sakrās lielu pulku, bet šis pulks taps nodots viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Kad tas pulks celsies, tad viņa sirds leposies, un viņš noguldīs daudz tūkstošus; taču viņš nedabūs virsroku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Jo ziemeļa ķēniņš atkal sakrās lielāku pulku, nekā tas pirmais, un pēc kādu gadu laika viņš nākdams atnāks ar lielu spēku un ar lielu varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Un tanī laikā daudzi celsies pret dienvidu ķēniņu, un kādi varmāki no taviem ļaudīm lepni pacelsies, lai praviešu parādīšana piepildās, bet tie kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Un ziemeļa ķēniņš nāks un uzmetīs vaļņus un uzņems stipru pilsētu, un dienvidu karaspēki nepastāvēs, nedz viņa izlasītie ļaudis, pat tiem spēka nebūs pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Bet kas pret viņu nāks, darīs, kas viņam patīk, jo neviens viņa priekšā nepastāvēs. Viņš apmetīsies arī tai mīlīgā zemē un to postīs ar savu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Un viņš taisīsies nākt ar visu savu valsts spēku, un līgs mieru ar to un tam dos vienu meitu par sievu, gribēdams to zemē gāzt, bet tas nenotiks un neizdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Pēc viņš griezīsies pret tām salām un uzņems daudz, bet viens karavirsnieks darīs viņa nievāšanai galu un viņam atmaksās to nievāšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Tā viņš griezīsies atpakaļ uz savas zemes stiprām pilīm un piedauzīsies un kritīs, ka nekur vairs netaps atrasts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Un viņa vietā celsies viens, kas izsūtīs plēsējus uz savas valsts godību, bet viņš pa kādām dienām taps salauzts, ne caur dusmību, ne caur karu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Un viņa vietā celsies viens nelietis, tam ķēniņa gods nav dots, taču viņš nejauši nāks un uzņems valsti ar mīkstiem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Un tie karaspēki, kas bija uzplūduši, viņa priekšā taps aizplūdināti un salauzti, ir tas valdnieks, kas viņam biedrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Jo viņš ar to būs viltīgi apbiedrinājies un celsies un to pārvarēs ar maz ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Nejauši viņš nāks tanīs bagātās (zemes) vietās, un padarīs, ko ne viņa tēvi, ne tēvu tēvi nebija darījuši; laupījumu un mantu viņš bagāti starp tiem izdalīs, un tam būs nodomi pret tām stiprām pilīm kādu noliktu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Un viņš pamodinās savu spēku un savu sirdi pret dienvidu ķēniņu ar lielu karaspēku, un dienvidu ķēniņš taisīsies uz karu pret viņu ar varen lielu un stipru karaspēku, bet viņš nepastāvēs, jo viltība pret viņu taps izdomāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Un kas viņa maizi ēdīs, tie viņu gāzīs postā, un viņa (ziemeļa puses ķēniņa) karaspēks ielauzīsies, un daudz nokauti kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Un šo abēju ķēniņu sirds uz to stāvēs, ka tie varētu ļaunu darīt (viens otram), un pie viena galda tie viltīgi runās, bet tiem tā neizdosies, jo tas gals vēl ir nolikts uz citu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Un viņš griezīsies atpakaļ uz savu zemi ar lielu mantu, un viņa sirds stāvēs pret to svēto derību, un viņš to izdarīs un griezīsies atpakaļ uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Bet savā laikā viņš atkal nāks un celsies pret dienasvidu, bet tā pēdējā reize nebūs kā tā pirmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Jo lielas laivas no Ķitim nāks pret viņu, tādēļ viņš ar bailību taps apņemts un griezīsies atpakaļ un apskaitīsies pret to svēto derību un to izdarīs, un atpakaļ griezdamies viņš tos ņems vērā, kas atkāpjas no tās svētās derības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Un tad no viņa celsies karapulki, kas sagānīs to svēto vietu, to pili, un atņems dienišķo upuri un darīs negantību un postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Un ar mīkstiem vārdiem viņš atvils tos, kas bezdievīgi pārkāpj derību; bet tie ļaudis, kas savu Dievu pazīst, stipri rādīsies, un tiem izdosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Un tie prātīgie starp ļaudīm daudz citus pamācīs, bet kritīs caur zobenu un caur liesmām, caur cietumu un aplaupīšanu kādu laiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Kad tie nu tā kritīs, tad tiem ar mazu palīgu taps palīdzēts, bet daudz pie tiem piestāsies ar viltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Un no tiem prātīgiem citi kritīs, ka top kausēti viņu vidū un šķīstīti un iztīrīti līdz pat beidzamam galam; jo tas vēl iet līdz noliktam laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Un tas ķēniņš darīs, kas viņam patīk, un paaugstināsies un lielīsies pret visu, kas ir dievs, un pret to stipro Dievu, kas pār visiem dieviem, tas runās negantas lietas, un tam laimēsies līdz kamēr tās dusmas beigsies; jo kas nospriests, tas notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Un savu tēvu dievus tas neliks vērā nedz sievu iekārošanu, tas arī nekādu dievu necienīs, jo tas paaugstināsies pār visu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Bet tai vietā tas godās cietokšņa dievu, dievu, ko viņa tēvi nav pazinuši, to tas godās ar zeltu, sudrabu, dārgiem akmeņiem un citām dārgām lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Un tām stiprām pilīm tas gādās sveša dieva ļaudis, un ko tas atzīs, tiem tas dos lielu godu, un liks tiem valdīt pār daudziem, un izdalīs zemi par algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Un gala laikā dienvidu ķēniņš ar to badīsies, un ziemeļa ķēniņš lauzīsies pret viņu ar ratiem un jātniekiem un lielām laivām un nāks uz tām zemēm un tās pārplūdīs un izstaigās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Un viņš nāks uz to mīlīgo zemi, un daudzi kritīs, bet šie taps izglābti no viņa rokas: Edoms un Moabs un Amona bērnu lielā puse.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Un viņš izstieps savu roku pār zemēm, arī Ēģiptes zeme neizbēgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Un viņš valdīs pār zelta un sudraba mantām un pār visām dārgām Ēģiptes lietām, un Lībieši un Moru ļaudis viņam klausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Bet baumas no rīta puses un ziemeļa puses viņu iztrūcinās, tādēļ viņš celsies ar lielu bardzību, daudz nomaitāt un izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Un viņš uzcels savas teltis starp tām jūrām pie tās mīlīgās zemes svētā kalna, un viņam nāks savs gals, un nebūs palīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Tanī laikā celsies Miķelis, tas lielais valdnieks, kas tavu ļaužu bērnus aizstāv, un tad būs tāds bēdu laiks, kāds vēl nav bijis, kamēr ļaudis bijuši, līdz tam laikam. Un tanī laikā tavi ļaudis taps izpestīti, visi, kas atrodas grāmatā rakstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Un daudz no tiem, kas guļ zemes pīšļos, uzmodīsies, citi uz mūžīgu dzīvošanu, bet citi uz mūžīgu kaunu un negantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Bet mācītāji spīdēs kā debess spožums, un kas daudzus veduši uz taisnību, kā zvaigznes mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Un tu, Daniēl, apslēp šos vārdus un aizzieģelē šo grāmatu līdz pēdējam laikam, tad daudzi meklēs tikuši(visapkārt), un atzīšana vairosies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Un es, Daniēls, skatījos, un redzi, divi citi stāvēja, viens šai upes malā un otrs otrā upes malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Un viens sacīja uz to vīru, kas bija ģērbts nātnu drēbēs, kas upes virsū stāvēja: cik ilgi tas būs, kad tiem brīnumiem būs gals?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Un es dzirdēju to vīru, kas bija ģērbts nātnu drēbēs un stāvēja upes virsū, tas pacēla savu labo un kreiso roku pret debesīm un zvērēja pie Tā, kas dzīvo mūžīgi, ka viss tas notiks pēc viena laika, diviem laikiem un pus laika, un kad tās svētās tautas klīšana būs beigta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'To es dzirdēju, bet nesapratu, un sacīju: mans kungs, kas būs tam visam gals?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Un viņš sacīja: ej, Daniēl, jo šie vārdi ir apslēpti un aizzieģelēti līdz gala laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Daudzi taps šķīstīti un tīrīti un kausēti, un tie bezdievīgie būs bezdievīgi, un tie bezdievīgie visi to neliks vērā, bet tie prātīgie to liks vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Un no tā laika, kad tas ikdienas upuris kļūs atņemts un tā negantība un postīšana notiks, būs tūkstoš divi simti un deviņdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Svētīgs ir, kas sagaida un aizsniedz tūkstoš trīs simti trīsdesmit un piecas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Bet tu noej līdz galam, un tu dusēsi un atkal celsies, savu daļu dabūt pastarā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Šis ir Tā Kunga vārds, kas notika uz Hozeju, Beērus dēlu, Uzijas, Jotama, Ahazs, Hizkijas, Jūda ķēniņu, dienās un Jerobeama, Jehoas dēla, Israēla ķēniņa dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Šis ir tas iesākums, kā Tas Kungs runāja ar Hozeju. Tas Kungs sacīja uz Hozeju: ej, ņem sev maukas sievu un maukas bērnus, jo zeme dzenās tiešām maucībai pakaļ no Tā Kunga nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Tad viņš nogāja un ņēma Gomeri, Diblaima meitu, un tā tapa grūta un dzemdēja viņam dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Un Tas Kungs uz viņu sacīja: Sauc viņa vārdu Jezreēli (tas Kungs izkaisīs); jo par īsu laiku Es piemeklēšu Jezreēļa asins vainu pie Jeūs nama un darīšu galu Israēla nama valstībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Un tai dienā Es salauzīšu Israēla stopu Jezreēļa ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Un viņa tapa atkal grūta un dzemdēja meitu. Un Viņš uz to sacīja: nosauc viņas vārdu LoRukama (neapžēlota), jo Es joprojām vairs neapžēlošos par Israēla namu, ka Es tiem piedotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Bet par Jūda namu Es apžēlošos un tos atpestīšu caur To Kungu, viņu Dievu; bet Es tos neatpestīšu ne caur stopu, ne caur zobenu, ne caur karu, ne caur zirgiem, ne caur jātniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Kad tā nu to LoRukamu bija atšķīrusi, tad viņa tapa grūta un dzemdēja dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Un Viņš sacīja: sauc viņa vārdu LoAmmi (ne Mana tauta); jo jūs neesat Mana tauta, un arī Es nebūšu jūsu (Dievs).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Bet Israēla bērnu pulks būs kā jūras smiltis, ko nevar ne mērot, ne skaitīt. Un notiks tai vieta, kur uz tiem sacīja: jūs neesat Mani ļaudis, - uz tiem sacīs: Jūs tā dzīvā Dieva bērni!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Un Jūda bērni un Israēla bērni sapulcināsies kopā un iecels pār sevi vienu galvu un atnāks no tās zemes jo Jezreēļa diena būs liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Sakait uz saviem brāļiem: Mani ļaudis, - un uz savām māsām: Ak apžēlotas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Ejat tiesāties ar savu māti, ejat tiesāties, jo tā nav Mana sieva, un Es neesmu viņas vīrs, lai viņa savu maucību noliek no sava vaiga un savu laulības pārkāpšanu no savām krūtīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Ka Es to nenovelku pliku un viņu nenostādu kā tai dienā, kad viņa piedzima, un viņu nedaru par tuksnesi un nelieku par sausu zemi un viņu nenonāvēju caur tvīkšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Un ka neapžēlojos par viņas bērniem, jo tie ir maukas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Jo viņu māte dzen maucību, viņu dzemdētāja ir negodīga; jo tā saka: es iešu saviem drauģeļiem pakaļ, kas man dod manu maizi un manu ūdeni, manu vilnu un manus linus, manu eļļu un manu dzērienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Tādēļ redzi, Es tavu ceļu aiztaisīšu ar ērkšķiem un darīšu tur sienu priekšā, ka viņa savas tekas nevar atrast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Un viņa dzīsies saviem drauģeļiem pakaļ, bet tos nepanāks, un viņa tos meklēs, bet neatradīs; tad viņa sacīs: es iešu un atgriezīšos pie sava pirmā vīra, jo to brīdi man bija labāki nekā tagad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Jo viņa neatzīst, ka Es tas esmu, kas viņai devis labību un vīnu un eļļu, un vairojis viņas sudrabu un zeltu, ko tie priekš Baāla ir lietojuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Tādēļ Es atkal atņemšu Savu labību savā laikā un Savu vīnu savā brīdī, un atraušu Savu vilnu un Savus linus, ar ko tie apseguši savu plikumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Un nu Es viņas kaunu atklāšu priekš viņas drauģeļu acīm, un neviens viņu neizglābs no Manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Un Es nobeigšu visu viņas līksmību, viņas svētkus, viņas jaunos mēnešus un viņas svētdienas un visus viņas svētos laikus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Un Es postīšu viņas vīna koku un vīģes koku, par ko viņa saka: tā ir mana maukas alga, ko man mani drauģeļi devuši; bet Es tos darīšu par mežu, un zvēriem laukā tos būs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Un Es pie viņas piemeklēšu tās Baālu dienas, ka viņa tiem ir kvēpinājusi un greznojusies ar savām sprādzēm un glītumiem un dzinusies pakaļ saviem drauģeļiem, bet Mani ir aizmirsuši, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Tādēļ redzi, Es viņu labināšu un viņu vedīšu tuksnesī un runāšu mīlīgi ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Un Es tai atdošu viņas vīna dārzus no tejienes un to Ahora ieleju par cerības durvīm. Un tur viņa dziedās kā savas jaunības dienās, un kā tai laikā, kad viņa cēlās no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Un tai dienā, saka Tas Kungs, tu sauksi: mans vīrs, un tu Mani vairs nesauksi: mans Baāl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Un Es Baālu vārdus izraušu no viņas mutes, ka tos ar viņu vārdiem vairs nepieminēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Un tai dienā Es darīšu priekš viņiem derību ar zvēriem laukā un ar putniem apakš debess un ar tārpiem virs zemes, un salauzīšu stopu un zobenu un karu no zemes, un likšu tiem droši dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Un Es ar tevi saderēšos uz mūžību, un Es ar tevi saderēšos taisnībā un tiesā un žēlastībā un apžēlošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Un Es ar tevi saderēšos ticībā, un tu atzīsi To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Un tai dienā Es paklausīšu, saka Tas Kungs; Es paklausīšu debesi, un tā paklausīs zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Un zeme paklausīs labību un vīnu un eļļu, un tie paklausīs Jezreēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Un Es tos darīšu Sev par dzimumu virs zemes un apžēlošos par to neapžēloto un sacīšu uz tiem, kas nebija Mani ļaudis: jūs esat Mani ļaudis; un tie sacīs: mans Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Un Tas Kungs uz mani sacīja: noej atkal, mīli vienu sievu, kas top mīlēta no sava drauga un tomēr pārkāpj laulību, tā kā Tas Kungs Israēla bērnus mīl, bet tie griežas pie citiem dieviem un iemīl vīna ogu raušus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Un es to sev pirku par piecpadsmit sudraba gabaliem un pusotru omeru miežu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Un es uz viņu sacīju: daudz dienas tu man sēdēsi un nedzīsi maucību, nedz būsi pie vīra: tāpat es turēšos pret tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Jo Israēla bērni paliks ilgu laiku bez ķēniņa un bez valdītāja un bez upura un bez altāra un bez plecu segas(efoda) un bez tēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Pēc tam Israēla bērni atgriezīsies un meklēs To Kungu, savu Dievu, un Dāvidu, savu ķēniņu, un nāks bīdamies pie Tā Kunga un pie Viņa žēlastības pēdīgās dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Klausiet Tā Kunga vārdu, Israēla bērni! Jo Tam Kungam ir tiesas lieta ar zemes iedzīvotājiem, tāpēc ka ne uzticības, ne mīlestības, ne Dieva atzīšanas nav tai zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Bet lādēšana un melošana un kaušana un zagšana un laulības pārkāpšana laužas iekšā, un asins vaina nāk pēc asins vainas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Tādēļ zeme bēdājās, un visi viņas iedzīvotāji vaid līdz ar zvēriem laukā un ar putniem apakš debess, un pat jūras zivis iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Tomēr lai neviens nestrīdās un netiesājās ar otru, jo tavi ļaudis ir kā tādi, kas ar priesteri strīdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Tādēļ tu klupsi dienā, un pats pravietis klups ar tevi naktī, un Es izdeldēšu tavu māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mani ļaudis top izdeldēti, tādēļ ka tie bez atzīšanas. Jo kā tu atzīšanu esi atmetis, tad arī Es tevi atmetīšu, ka tev Man nebūs būt par priesteri. Un tāpēc ka tu esi aizmirsis sava Dieva bauslību, tad arī Es aizmirsīšu tavus bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Cik daudz viņi bijuši, tik tie pret Mani apgrēkojušies. Es viņu godu pārvērtīšu par kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Tie ēd Manu ļaužu grēku upurus un ilgojās ikviens savā dvēselē pēc viņu noziegumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Tādēļ priesteris būs tāpat kā tie ļaudis, un Es pie viņa piemeklēšu viņu ceļus un viņam atmaksāšu viņu darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Un tie ēdīs, bet nepaēdīs, tie maukos, bet nevairosies, tādēļ ka tie To Kungu atstājuši un viņu nav cienījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Maucība un vīns un jauns vīns paņem prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mani ļaudis vaicā savu koku, un viņu spieķis tiem dod ziņas, jo maucības gars tos pieviļ, ka tie maukodamies no sava Dieva atkāpjas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Kalnu galos tie upurē un pakalnos tie kvēpina, apakš ozoliem, liepām un kļavām, tāpēc ka viņu ēna ir laba; tādēļ jūsu meitas dzen maucību, un jūsu brūtes pārkāpj laulību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Es nepiemeklēšu jūsu meitas, ka tās dzen maucību, nedz jūsu brūtes, ka tās pārkāpj laulību, jo tie paši iet savrup ar maukām un upurē ar nešķīstām, tādēļ tie neprātīgie ļaudis ies postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Ja tu, Israēl, gribi maukot, tad lai Jūda nenoziedzās arīdzan. Nenāciet uz Gilgalu un neejat augšām uz BetAvenu, un nezvērējiet: tik tiešām kā Tas Kungs dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Ja Israēls ir trakgalvīgs kā trakgalvīga govs, tad arī Tas Kungs tos ganīs kā jērus plašā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraīms ir apbiedrinājies ar dievekļiem, laižat to mierā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Plītēšanā tie palaidušies, maukot tie maukojās, viņu valdnieki mīl negodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Vējš ar saviem spārniem tos sagrābs, un tie taps kaunā ar saviem upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Klausiet šo, jūs priesteri, un ņemiet vērā, Israēla nams, un atgriežat ausis, ķēniņa nams, jo pār jums nāks sodība, ka esat par valgu tapuši Micpā un par izplestu tīklu Tāborā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Tie atkāpjās un dziļi samaitājās, bet Es tiem visnotaļ būšu par pārmācītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Es pazīstu Efraīmu, un Israēls priekš Manis nav apslēpts, ka tu, Efraīm, tagad maucību dzeni, un Israēls sagānās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Viņu darbi nevēl pie Dieva atgriezties, jo maucības gars ir viņu sirdī, un To Kungu tie neatzīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Israēla gods dos liecību pret viņa vaigu, un Israēls un Efraīms kritīs caur savu noziegumu, arī Jūda kritīs līdz ar viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Tad tie nāks ar savām avīm un ar saviem vēršiem, To Kungu meklēt, bet neatradīs, - Viņš no tiem ir atrāvies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Tie palikuši neuzticīgi pret To Kungu, jo tie dzemdinājuši svešus bērnus, un jaunais mēnesis tos norīs ar viņu daļām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Bazūnējiet ar bazūnēm Ģibejā, ar trumetēm Rāmā, sauciet skaņi BetAvenā: „aiz tevis, Benjamin!“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraīms taps par tuksnesi sodības dienā; par Israēla ciltīm Es esmu darījis zināmu, kas tiešām notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Jūda lielkungi ir tapuši kā tie, kas robežu pārceļ, Es izgāzīšu pār tiem savas dusmas kā ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraīms top nospaidīts, sasists sodā, jo viņam gribējās pakaļ dzīties (cilvēku) likumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Tāpēc Es Efraīmam būšu kā kode, un Jūda namam kā kāpurs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Kad Efraīms redzēja savu sērgu un Jūda savu vainu, tad Efraīms cēlās pie Asura un sūtīja pie ķēniņa Jareba, bet tas nevar jūs darīt veselus, nedz dziedināt jūsu vainu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Jo Es būšu Efraīmam kā lauva un Jūda namam kā jauns lauva. Es, Es saplosīšu un iešu projām, Es aiznesīšu, un nebūs glābēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Es iešu un atgriezīšos uz savu vietu, tiekams tie savu noziegumu atzīst un meklē manu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Kad tiem būs bail, tad tie Mani meklēs: ejam, atgriezīsimies pie Tā Kunga. Jo Viņš ir saplēsis, un Viņš mūs dziedinās, Viņš ir sasitis, un Viņš mūs sasies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Viņš mūs darīs dzīvus pēc divām dienām, trešā dienā Viņš mūs uzcels, ka dzīvosim Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Tad ņemsim vērā, dzīsimies To Kungu atzīt; Viņš tiešām ausīs kā auseklis un nāks pie mums kā stiprs lietus, kā vēlais lietus slacina zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Ko lai tev daru, Efraīm, ko lai tev daru, Jūda? Jo jūsu mīlestība ir kā rīta mākonis un kā rasa, kas agri izzūd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Tādēļ Es esmu cirtis ar tiem praviešiem, Es tos esmu kāvis ar Savas mutes vārdiem, un Mana tiesa ausa kā gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Jo Man patīk mīlestība un ne upuris, un Dieva atzīšana vairāk nekā dedzināmie upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Bet tie pārkāpj derību kā Ādams, tur tie pret Mani palikuši neuzticīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gileāda ir pilsēta pilna ļauna darītāju, ar asiņainām pēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Un kā laupītāji glūn uz kādu cilvēku, tāda ir tā priesteru draudze, uz Sihemas ceļa tie dzen slepkavību, tiešām tie dara negantus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Israēla namā Es redzu briesmīgas lietas: tur ir Efraīma maucība, Israēls ir sagānījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Arī tev, Jūda, ir pļauja priekšā, kad Es pārvedīšu Savus cietuma ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Kad Es Israēli dziedināšu, tad Efraīma noziegums taps atsegts un Samarijas ļaunums, jo tie dara viltību; zagļi ir iekšā, un laupītāji ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Un tie nedomā savā sirdī, ka Es visu viņu ļaunumu pieminu. Bet nu viņu darbi apmetās pret tiem, tie ir Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Ar savu ļaunumu tie iepriecina ķēniņu un lielkungus ar saviem meliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Tie visi ir laulības pārkāpēji, tie ir kā ceplis, kurināts no cepēja, kas mīklu samīcījis, mitējās kurināt, kamēr tā ir uzrūgusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Mūsu ķēniņa dienā lielkungi paliek vāji no vīna karstuma; viņš sniedz savu roku smējējiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Jo tie ar savu sirdi dodās uz viltību kā ceplī. Viņu cepējs guļ cauru nakti, rītā viņš deg kā uguns liesmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Tie visi ir iekarsuši kā ceplis un aprij savus tiesnešus, visi viņu ķēniņi krīt, neviens no tiem mani nepiesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraīms jaucās ar tautām, Efraīms ir rausis, ko neapgriež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Sveši norij viņa spēku, un viņš to nemana, arī sirmums viņam ir uznācis, un viņš to neatzīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Un Israēla gods dod liecību pret viņa vaigu, bet tie neatgriežas pie Tā Kunga, sava Dieva, un tomēr viņu nemeklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Jo Efraīms ir kā nejēdzīgs balodis bez prāta; Ēģipti tie piesauc, pie Asura tie staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Kad tie nu tā staigā, tad Es Savu tīklu pār tiem izpletīšu, Es tos nometīšu(lejā) kā putnus apakš debess, Es tos pārmācīšu, tā kā ir sludināts viņu draudzei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Vai tiem! Jo tie bēg no Manis; posts pār viņiem! Jo tie ir noziegušies pret Mani. Es tos gan gribētu atpestīt, bet tie runā melus pret Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Un tie Mani nepiesauc no sirds, kad tie kauc uz savām gultām. Tie sapulcējās labības un vīna dēļ bet Man tie turas pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Gan Es tos pamācu un stiprināju viņu elkoņus, bet tie domā ļaunu pret Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Tie griežas, bet ne uz to, kas augšā; tie ir kā viltīgs stops; viņu lielkungi kritīs caur zobenu viņu trakās mēles dēļ; tas būs viņu apsmiekls Ēģiptes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Liec bazūni pie savas mutes; Viņš nāk kā ērglis pret Tā Kunga namu, tādēļ ka tie Manu derību pārlauzuši un no Manas bauslības atkāpušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Tad tie uz Mani kliegs: mans Dievs! Mēs, Israēls, mēs Tevi pazīstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israēls atmet labu, ienaidnieks viņu vajās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Tie ieceļ ķēniņus, bet bez Manis; tie ieceļ virsniekus, bet Es tos nepazīstu, no sava sudraba un no sava zelta tie sev taisa dievekļus, lai tas top izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Tavs teļš, Samarija, ir riebīgs; Mana dusmība pār tiem iedegusies, - cik ilgi tie nevar palikt nenoziedzīgi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Jo arī tas ir no Israēla, kalējs to ir taisījis, un tas nav nekāds dievs; tāpēc Samarijas teļš taps par gruvešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Jo tie sēj vēju un pļaus auku; viņu druvas necelsies, un kas izplaukst, tas nedos miltus, un jebšu tas ko dotu, tomēr sveši to aprīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israēls top aprīts; tie ir starp pagāniem kā trauks, ko neviens negrib,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Tāpēc ka tie skrien pie Asura, kā meža ēzelis, kas skrien par sevi; Efraīms sader drauģeļus par maksu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Kad tie nu saderās(nolīgst sabiedrotos) starp pagāniem, tad tūlīt arī es tos sapulcināšu, un tiem drīz uzies raizes no tā valdnieku ķēniņa nastas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Jo Efraīms ir vairojis altārus par apgrēkošanos, viņam altāri palikuši par apgrēkošanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Es tam uzrakstīju lielu pulku savu baušļu, bet tie tapa turēti kā sveša lieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Par upuru dāvanu tie gan gaļu upurē un to ēd, bet Tam Kungam nav labs prāts pie tiem; un Viņš pieminēs viņu noziegumus un piemeklēs viņu grēkus; tie griežas atpakaļ uz Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Jo Israēls ir aizmirsis savu Radītāju un cēlis pilis, un Jūda vairo stipras pilsētas, bet Es sūtīšu uguni viņu pilsētās, tas aprīs viņu pilis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Nepriecājies, Israēl, ar gavilēšanu kā tās tautas, jo tu dzen maucību, atkāpdamies no sava Dieva, tu mīļo mauku algu uz visiem labības kloniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Klons un eļļas spaids viņus nemielos un jaunais vīns tos pievils.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Tie nepaliks Tā Kunga zemē, bet Efraīms griezīsies atpakaļ uz Ēģipti, un Asīrijā tie ēdīs nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Tie Tam Kungam nenesīs dzeramus upurus no vīna, un viņu kaujamie upuri viņam nepatiks; tie viņiem būs kā bēru maize. Visi, kas to ēd, apgānās, jo viņu maize ir priekš viņiem pašiem, un nenāk Tā Kunga namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Ko tad jūs darīsiet svētkos un Tā Kunga svētā dienā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Jo redzi, tiem jāaiziet tā posta dēļ, Ēģipte tos sapulcinās, Memfisa viņus apraks. Nātres mantos viņu sudraba dārgumus, ērkšķi būs viņu dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Piemeklēšanas dienas nākušas, atmaksāšanas dienas ir klāt, Israēls to samanīs! Tie pravieši ir ģeķi, tie gara vīri ir traki, - visa tava lielā nozieguma un lielā naida dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Efraīms lūko manam Dievam garām, un pravieši ir palikuši par slazda valgiem uz visiem viņa ceļiem, naids ir viņu dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Tie ir dziļi maitājušies tā kā Ģibejas dienās; viņš pieminēs viņu noziegumu, viņš piemeklēs viņu grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Es atradu Israēli kā vīna ogu ķekarus tuksnesī, Es ieraudzīju jūsu tēvus kā pirmajus augļus pie vīģes koka; bet tie nogāja pie BaālPeora un padevās tam bezkaunīgam un tapa tik neganti kā viņu drauģeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraīma godība aizskries kā putns, ka tur ne dzemdēs, nedz taps grūtas, nedz ieņems.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Un jebšu tie savus bērnus uzaudzinātu, tomēr Es tiem tos gribu laupīt, ka cilvēku neatliek. Ak vai, tiem, kad Es no tiem būšu atstājies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraīms, ko Es biju izredzējis, būt par Tiru, bija stādīts skaistā vietā, bet Efraīmam savi bērni jaiznes slepkavam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Dod tiem, ak Kungs! Ko lai Tu dodi? Dod tiem neauglīgas miesas un izsīkušas krūtis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Visa viņu negantība ir Gilgalā, tur Es tos ienīdēju. Viņu ļauno darbu dēļ Es tos izdzīšu no Sava nama, Es joprojām tos vairs nemīļošu; - visi viņu lielkungi ir atkāpēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraīms ir sasists, viņu sakne ir izkaltusi; tie nenesīs nekādus augļus; un jebšu tie dzemdinātu, tomēr Es viņu miesas mīlulīšus gribu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mans Dievs tos atmetīs, tāpēc ka tie Viņam neklausīja, un tie būs bēguļi starp tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israēls ir kupls vīna koks, kas nes augļus; jo vairāk bija viņa augļu, jo vairāk viņš cēla altāru; jo labāka viņa zeme, jo labāki viņš iztaisīja elku stabus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Viņu sirds ir viltīga; nu tiks atmaksāts. Viņš salauzīs viņu altārus, postīs viņu elku stabus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Nu tie sacīs: ķēniņa mums nav, jo mēs To Kungu neesam bijušies; ko mums ķēniņš var darīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Tie runāja vārdus, nepatiesi zvērēdami un derības derēdami, tāpēc sodība zaļos kā nāves zāle uz tīruma vagām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Samarijas iedzīvotāji iztrūcinājās par BetAvenas teļu, viņa ļaudis par to bēdājās un viņa priesteri par to trīc, jo viņa godība no tā aiziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Arī to pašu(elka teļu) vedīs uz Asīriju par dāvanu priekš ķēniņa Jareba; Efraīms paliks kaunā, un Israēls taps apkaunots sava padoma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Samarijas ķēniņš ir izzudis kā putas ūdens virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Un Avenas kalni, kur Israēls apgrēkojās, taps izdeldēti, ērkšķi un dadži augs uz viņu altāriem, un tie sacīs uz tiem kalniem: apklājiet mūs! - un uz tiem pakalniem: krītiet pār mums!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'No Ģibejas dienām tu esi grēkojis, Israēl: tur tie pastāvējuši; tā kauja Ģibejā pret tiem negantības bērniem tos neaizņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Pēc Sava prāta Es tos pārmācīšu, un tautas pret tiem sapulcināsies, kad Es tos sodīšu viņu divēju grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Jo Efraīms ir teļš, ieradis labprāt kult, bet Es nākšu par viņa kakla skaistumu, Es Efraīmu iejūgšu, Jūda ars, un Jēkabs ecēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Sējiet sev pēc taisnības, pļaujiet pēc žēlastības, plēsiet sev jaunu zemi, jo laiks ir, To Kungu meklēt, tiekams tas nāk un jums māca taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Jūs arat bezdievību, ļaunumu jūs pļaujat un ēdat melu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Jo tu paļaujies uz savu ceļu, uz savu varoņu pulku. Tāpēc liels troksnis celsies pret taviem ļaudīm, un visas tavas stiprās vietas taps postītas, tā kā Zalmans BetArbeli postīja kara laikā, kur māte līdz ar bērniem tapa satriekta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Tāpat jums notiks caur Bēteli jūsu niknās blēdības dēļ; Israēla ķēniņš dienai austot nīcin iznīks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Kad Israēls bija bērns, tad Es viņu mīlēju, un Savu dēlu atsaucu no Ēģiptes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Bet jo (tie pravieši) tos sauca, jo vairāk tie no viņiem nogāja; tie upurēja Baāliem un kvēpināja elku tēliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Es tomēr Efraīmu mācīju staigāt, Es tos ņēmu uz Savām rokām, bet tie neatzina, ka Es tos dziedināju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Es tos vilku ar cilvēka valgiem, ar mīlestības saitēm, un tiem biju kā kas apaušus no viņu žokļiem atvieglina, un Es tiem pasniedzu barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Viņš neatgriezīsies atpakaļ uz Ēģiptes zemi, bet Asurs, tas būs viņa ķēniņš, tāpēc ka tie liedzās atgriezties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Un zobens zibēs viņu pilsētās un nobeigs un aprīs viņu aizšaujamos viņu padomu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Jo Maniem ļaudīm prāts nesās, no Manis nogriezties; tie gan top aicināti uz augšu, bet neviena nav, kas ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Kā Es tev darīšu, Efraīm? Vai Man tevi būs nodot, Israēl? Vai Es tev darīšu kā Admai? Vai tevi postīšu kā Ceboīmu? Mana sirds ir griezusies, un Mana apžēlošanās visai iedegusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Es nedarīšu pēc Savas bardzības karstuma, nedz Efraīmu atkal postīšu, jo Es esmu Dievs un ne cilvēks, tas Svētais tavā vidū. Un dusmās Es nenākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Tad tie dzīsies Tam Kungam pakaļ, Viņš kauks kā lauva, un kad Viņš kauks, tad tie bērni no vakara puses drebēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Tie drebēdami nāks no Ēģiptes, kā putns un kā balodis no Asura zemes, un Es tiem likšu dzīvot viņu namos, tā saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Efraīms Mani apstāj ar meliem un Israēla nams ar viltu, un Jūda vēl šaubās ap Dievu, to uzticīgo un svēto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraīms grābstās pēc vēja un dzenās pakaļ rīta vētrai, cauru dienu viņš vairo postu, un tie ceļ derību ar Asuru, un eļļa top vesta uz Ēģipti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Tam Kungam jātiesājas ar Jūdu, un Jēkabu Viņš piemeklēs pēc viņa ceļiem, pēc viņa darbiem Viņš tam atmaksās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Mātes miesās viņš pamina savu brāli, un savā (vīra) spēkā viņš cīnījās ar Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Viņš stipri cīnījās ar to eņģeli un pārvarēja; viņš raudāja un Viņu lūdza; Bētelē Viņš to atrada, un tur Viņš ar mums runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Un Tas Kungs ir tas Dievs Cebaot, Kungs ir Viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Tu tad atgriezies pie sava Dieva, pasargi žēlastību un tiesu un gaidi bez mitēšanās uz savu Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Kanaāns, viņa rokā ir viltīgs svars, viņam mīl varas darbu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Efraīms saka: taču es esmu tapis bagāts, esmu sev dabūjis lielu mantu, pie visas manas peļņas vainas nav, kas būtu grēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Bet Es esmu Tas Kungs, tavs Dievs, kamēr no Ēģiptes zemes; Es tevi vēl likšu lieveņos dzīvot, kā svētku laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Un Es runāju caur praviešiem, un vairoju parādīšanas, un caur praviešiem Es stāstu līdzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Ja Gileādā griežas uz grēku, tad tiešām tie paliks par nieku; Gilgalā tie upurē vēršus; un viņu altāri būs kā akmeņu kopa tīruma vagās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jēkabs bēga uz Sīrijas klajumu, un Israēls kalpoja par sievu, sievas dēļ viņš bija gans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Un Tas Kungs Israēli izveda no Ēģiptes caur vienu pravieti, un caur vienu pravieti tas tapa ganīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Bet Efraīms Viņu rūgti apkaitināja, tāpēc viņa Kungs viņa asinīm liks uz tā palikt, un tam atmaksās Viņa nievāšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Kad Efraīms runāja, tad cēlās bailes; viņš augsti cēlās iekš Israēla, bet viņš noziedzās caur Baālu un mira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Un nu tie vēl vairāk grēko, un no sava sudraba tie sev taisa elku stabus, dievekļus pēc sava prāta; tas visnotaļ ir kalēju darbs; uz tiem šie runā, cilvēku upurētāji, tie skūpsta teļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Tādēļ tie būs kā rīta mākoņi un kā rīta rasa, kas izzūd kā pelavas no klona, un kā dūmi no skursteņa top aizdzīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Bet Es esmu Tas Kungs, tavs Dievs, kamēr no Ēģiptes zemes, un Dieva bez manis tu nepazīsti neviena, un Pestītāja bez Manis nav neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Es par tevi zināju tuksnesī, tai sausā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Kad tiem bija ganība, tad tie pieēdās; kad tie bija pieēdušies, tad viņu sirds lepojās, tāpēc tie Mani aizmirsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Tādēļ Es tiem paliku kā lauva, kā pardelis Es glūnēju uz ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Es tos sastapšu kā lācis, kam bērni laupīti, un saplosīšu viņu cieto sirdi, Es tos tur aprīšu kā lauva; tie zvēri virs zemes tos saplosīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Tas tev par postu, Israēl, ka tu esi pret Mani, pret savu palīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Kur nu ir tavs ķēniņš? Lai tas tev palīdz visās tavās pilsētās! Un kur tavi tiesneši, par kuriem tu sacīji: dod man ķēniņu un virsniekus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Es tev devu ķēniņu savā dusmībā un to esmu atņēmis savā bardzībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Efraīma noziegumi ir sakrāti, viņa grēki ir glabāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Viņam nāks dzemdētājas sāpes; viņš ir negudrs bērns, jo tas laikā neiet mātes ceļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Es tos atpestīšu no elles, Es tos atsvabināšu no nāves. Nāve, kur ir tavs mēris, elle, kur ir tavs posts! Žēlums nebūs priekš Manām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Lai viņš arī augļus nes brāļu vidū, bet rīta vējš nāks, Tā Kunga vējš celsies no tuksneša, un viņa aka izkaltīs, un viņa avots izsīks; šis laupīs mantu un visus dārgumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samarija ies postā, jo tā savam Dievam ir turējusies pretī, tā kritīs caur zobenu, viņu bērni taps satriekti un viņu grūtās sievas taps uzšķērstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Atgriezies, ak Israēl, pie Tā Kunga, sava Dieva, jo tu esi kritis sava nozieguma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Ņemiet šos vārdus līdz un atgriežaties pie Tā Kunga un sakāt uz Viņu: piedod visu noziegumu un parādi žēlastību, ka mēs nesam savu lūpu upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Asurs mūs neizpestīs, mēs nejāsim uz zirgiem un nesacīsim vairs uz savu roku darbu: tu esi mūsu dievs! Jo pie Tevis bāriņš atrod žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Es dziedināšu viņu atkāpšanos, Es tos mīlēšu ar labu prātu, jo Mana dusmība no viņa novērsīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Es Israēlim būšu kā rasa: viņš zaļos kā lilija un iesakņosies kā Libānas(ciedrs).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Viņa zari izplētīsies, un skaistums viņam būs kā eļļas kokam, un smarža viņam būs kā Libānas(ciedram).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Tie, sēdēdami viņa ēnā, atkal audzinās labību un zaļos kā vīna koks; tam būs slava kā vīnam no Libānas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efraīm, kas Man vēl ar dievekļiem? Es paklausīšu un viņu uzlūkošu. Es būšu kā zaļa priede, pie Manis tavs auglis rodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kas ir gudrs, ka saprot šās lietas? Kas ir prātīgs, ka tās atzīst? Jo Tā Kunga ceļi ir taisni, un taisnie pa tiem staigās, bet pārkāpēji pa tiem kritīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Šis ir Tā Kunga vārds, kas notika uz Joēli, Petuēļa dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Klausiet šo vārdu, vecaji, un atgriežat ausis, visi zemes iedzīvotāji! Vai tāda lieta notikusi jūsu dienās vai jūsu tēvu dienās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Sludinājiet to saviem bērniem, un lai jūsu bērni to stāsta saviem bērniem, un atkal viņu bērni nākamam augumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Ko kāpuri atlicina, to ēd siseņi, un ko siseņi atlicina, to ēd vaboles un ko vaboles atlicina, to ēd kukaiņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Uzmostaties, piedzērušie, un raudiet! Un kauciet, visi vīna plītnieki, par to jauno vīnu, jo tas ir atrauts no jūsu mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Jo tauta ceļas pret manu zemi, varena un neskaitāma; viņas zobi ir lauvas zobi, un dzerokļi viņai ir kā vecam lauvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Tā ir izpostījusi manu vīna koku un par žagariem darījusi manu vīģes koku; viņa to mizot ir nomizojusi un nometusi, viņa zari ir palikuši balti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Vaidi kā jumprava, ar maisu apjozusies, sava jaunības brūtgāna dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Ēdamais upuris un dzeramais upuris ir atrauts no Tā Kunga nama; priesteri, Tā Kunga sulaiņi, bēdājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Tīrums ir postīts, zeme noskumusi, jo labība ir postīta, vīns sakaltis un eļļa iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Arāji paliek kaunā, vīna dārznieki kauc par kviešiem un miežiem, jo tīruma pļaušana ir pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Vīna koks ir sakaltis un vīģes koks iet bojā, granātābele un palmu koks un ābele, visi koki laukā ir nokaltuši, un līksmība ir nonīkusi pie cilvēku bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Apjožaties un žēlojaties, priesteri, kauciet, altāra sulaiņi, ejat, paliekat maisos cauru nakti, mana Dieva sulaiņi, jo ēdamais upuris un dzeramais upuris ir atrauts no mana Dieva nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Svētījat gavēni, izsauciet sapulces dienu, sapulcinājiet vecajus, visus zemes iedzīvotājus uz Tā Kunga, sava Dieva, namu un piesauciet To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ak vai, par to dienu! Jo Tā Kunga diena ir tuvu un nāks kā posts no tā Visuvarenā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Vai barība priekš mūsu acīm nav atrauta, prieks un līksmība no mūsu Dieva nama?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Graudi apakš zemes satrūdējuši, mantu nami ir tukši, šķūņi sagruvuši, jo labība nokaltusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Ak, kā vaid lopi! Vēršu ganāmie pulki apstulbuši, jo tiem nav ganības, un avju pulki iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Tevi, ak Kungs, es piesaucu, jo uguns ir aprijis tuksneša ganības, un liesma ir iededzinājusi visus kokus laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Pat zvēri laukā Tevi piesauc, jo ūdensupes izsīkušas, un uguns ir aprijis tuksneša ganības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Bazūnējiet ar bazūni Ciānā, un lai skan stipri Manā svētā kalnā; lai visi zemes iedzīvotāji dreb, jo Tā Kunga diena nāk, jo tā ir tuvu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Melna un tumša diena, apmākusies un miglaina diena. Kā rīta blāzma izplešas pār kalniem, tā liela un varena tauta, kāda nemūžam nav bijusi un pēc vairs nemūžam nebūs uz radu radiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Viņas priekšā rij uguns, un viņai nopakaļ deg liesma; zeme viņas priekšā ir kā Ēdenes dārzs, bet aiz viņas tukša posta vieta; neviens no tās nevar izbēgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Viņu ģīmis ir kā zirgu ģīmis, un kā jātnieki, tāpat viņi skrien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Tie atlec pa kalnu virsgaliem, kā rati rīb, kā uguns liesma sprēgā, kas rugājus aprij, kā varena tauta, kas apbruņota uz karu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Viņu ieraudzīdami, ļaudis iztrūcinājās, visu vaigu sārtums nobāl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Tie skrien kā varoņi, kā kara vīri tie uzkāpj uz mūriem; un tie ikviens iet pa savu ceļu un neatkāpjās no savas tekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Tie nespiež viens otru, ikviens staigā savā kārtā, un jebšu krīt kara ieročos, tomēr tie netop aizturēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Tie staigā pa pilsētu, tie skrien pa mūriem, tie iekāpj namos, tie nāk caur logiem iekšā kā zaglis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Viņas priekšā dreb zeme, debess trīc, saule un mēnesis aptumšojās, un zvaigznes ierauj savu spožumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Un Tas Kungs paceļ Savu balsi Sava karaspēka priekšā, jo Viņa lēģeris ir varen liels, jo varens ir Viņa vārda izdarītājs, jo Tā Kunga diena ir liela un ļoti briesmīga, - kas to var panest?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Bet arī tagad Tas Kungs saka: atgriežaties pie Manis ar visu savu sirdi, un ar gavēšanu un ar raudāšanu un ar nožēlošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Un saplēšat savas sirdis un ne savas drēbes, un atgriežaties pie Tā Kunga, sava Dieva, jo viņš ir laipnīgs un sirdsžēlīgs, lēnprātīgs un no lielas žēlastības, un viņam ir žēl par to postu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kas zin, varbūt ka Viņš atgriezīsies, un Viņam būs žēl, un atstās svētību aiz Sevis, ēdamu upuri un dzeramu upuri priekš Tā Kunga, jūsu Dieva!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Bazūnējiet ar bazūni Ciānā, svētījiet gavēni, izsauciet sapulces dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Sapulcinājiet ļaudis, svētījiet draudzi, sapulcinājiet vecajus, sasauciet bērniņus un zīdāmos pie krūtīm. Lai brūtgāns iet no sava kambara un brūte no savas vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Starp priekšnamu un altāri lai raud priesteri, Tā Kunga sulaiņi, un lai saka: ak Kungs, žēlo Savus ļaudis un nenodod Savu mantību par nievāšanu, ka pagāni tos neapsmej! Kādēļ starp tautām būs sacīt: kur viņu Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Tad Tas Kungs iekarsa Savas zemes pēc un saudzēja Savus ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Un Tas Kungs atbildēja un sacīja uz Saviem ļaudīm: redzi, Es jums sūtīšu labību un vīnu un eļļu, ka jūs ar to topat pieēdināti, un Es jūs vairs nenodošu par nievāšanu starp pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Un Es atstādināšu tālu no jums to ziemeļnieku un to aizdzīšu sakaltušā un tukšā zemē, viņa priekšējus(pulkus) rīta jūrā un viņa pakaļējus(pulkus) vakara jūrā. Un viņa smarža kāps uz augšu, un viņa smirdums uzcelsies, jo viņš lielījās savos darbos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Nebīsties, zeme! Priecājies un esi līksma, jo Tas Kungs dara lielas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Nebīstaties, zvēri laukā! Jo ganības tuksnesī atkal nesīs jaunu zāli, jo koki nesīs savus augļus, vīna koks un vīģes koks izdos savu spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Un Ciānas bērni, priecājaties un līksmojaties iekš Tā Kunga, sava Dieva! Jo Viņš jums dos taisnības mācītāju un jums sūtīs lietu, agro lietu un vēlo lietu kā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Un kloni būs pilni labības, un spaidi pārtecēs no vīna un eļļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Tā Es jums atmaksāšu tos gadus, ko siseņi, vaboles un kukaiņi un kāpuri ir noēduši, Mans lielais karaspēks, ko Es jums biju sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Un jūs ēdin ēdīsiet un pieēdīsities un slavēsiet Tā Kunga, sava Dieva, vārdu, kas brīnišķi jums ir darījis, un Mani ļaudis netaps kaunā ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Un jūs manīsiet, ka Es esmu Israēla vidū, un ka Es esmu Tas Kungs, jūsu Dievs, un cits neviens, un Mani ļaudis netaps kaunā ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Pēc tam tas notiks, ka Es Savu Garu izliešu pār visu miesu, un jūsu dēli un jūsu meitas sludinās praviešu mācību, jūsu vecaji sapņos sapņus, jūsu jaunekļi redzēs parādīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Arī pār kalpiem un pār kalponēm Es izliešu Savu Garu tanīs dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Un Es darīšu brīnumus debesīs un zemes virsū, asinis un uguni un dūmu tvaiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Saule taps pārvērsta par tumsību un mēnesis par asinīm, pirms nekā nāks Tā Kunga lielā un bijājamā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Un notiks, ka ikviens, kas Tā Kunga vārdu piesauks, taps izglābts. Jo Ciānas kalnā un Jeruzālemē būs glābšana, kā Tas Kungs ir runājis, un pie tiem atlikušiem būs tie, ko Tas Kungs aicinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Jo redzi, tanīs dienās un tanī laikā, kad Es Jūda un Jeruzālemes cietumu atgriezīšu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Tad Es sapulcināšu visus pagānus un tos novedīšu uz Jehošafata ieleju un tur ar tiem tiesāšos Savu ļaužu dēļ un Sava īpašuma, Israēla, dēļ, ko tie izkaisījuši tautu starpā un izdalījuši Manu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Un par Maniem ļaudīm tie meslus metuši un puisēnu devuši par mauku un meiteni pārdevuši par vīnu un ir dzēruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Un jūs no Tirus un Sidonas un visām Fīlistu robežām, kas jums ar Mani? Vai jūs Man ko gribat atdarīt, ko Es jums darījis, jeb vai jūs Man ko gribat padarīt? Ātri un piepeši Es to atmaksāšu uz jūsu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Tāpēc ka jūs esat laupījuši Manu sudrabu un Manu zeltu, un Manus dārgumus nesuši savu dievekļu namos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Un Jūda bērnus un Jeruzālemes bērnus jūs esat pārdevuši Grieķiem, tos tālu aizdzīt no viņa robežām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Redzi, Es tos uzmodināšu no tās vietas, kurp jūs tos esat pārdevuši, un atmaksāšu jūsu maksu uz jūsu galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Un Es jūsu dēlus un jūsu meitas pārdošu Jūdu bērniem rokā; tie tos pārdos uz Sabu, tautai, kas tālu dzīvo, - jo Tas Kungs to ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Izsauciet to starp pagāniem, svētījiet karu, pamodinājiet tos varenos, lai atnāk un ceļas visi karavīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Kaļat savus lemešus par zobeniem un savas cirpes par šķēpiem! Vājais lai saka: es esmu stiprs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Sapulcējaties un nāciet šurp, visas tautas visapkārt, un sakrājaties! Turp noved, Kungs, savus varenos!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Tautas lai ceļas un sanāk Jehošafata ielejā, jo tur Es sēdēšu un tiesāšu visas tautas visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Pieliekat cirpi, jo pļaujamais ir gatavs; nāciet, minat, jo vīna spaids ir pilns, un trauki tek pāri, jo viņu blēdība ir liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Troksnis, troksnis tai tiesas ielejā, jo Tā Kunga diena ir tuvu klāt tiesas ielejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Saule un mēnesis aptumšojās un zvaigznes ierauj savu spožumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Un Tas Kungs rūc no Ciānas, un no Jeruzālemes viņš paceļ Savu balsi, tā ka debess un zeme dreb. Bet Tas Kungs ir patvērums Saviem ļaudīm un stiprums Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Un jūs manīsiet, ka Es esmu Tas Kungs, jūsu Dievs, kas dzīvo Ciānā, Savā svētā kalnā, un Jeruzāleme būs svēta vieta, un sveši tur vairs neies cauri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Un tai dienā pilēs salds vīns no kalniem un piens tecēs no pakalniem, un visi Jūda strauti būs pilni ūdens, un avots izlēks no Tā Kunga nama, tas slacinās visu Sitimas ieleju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Ēģipte taps postā un Edoms par tukšu vietu, tā varas darba dēļ, kas darīts pie Jūda bērniem, kuru zemē tie izlējuši nenoziedzīgas asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Bet Jūda pastāvēs mūžīgi un Jeruzāleme uz cilšu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Un Es atriebšu tās asinis, ko Es vēl nebiju atriebis. Un Tas Kungs dzīvos Ciānā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Šie ir Amosa, Tekoas avju gana, vārdi, ko viņš ir redzējis pār Israēli Uzijas, Jūda ķēniņa, dienās, un Jerobeama, Jehoas dēla, Israēla ķēniņa, dienās, divus gadus priekš tās zemes trīcēšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Un viņš sacīja: Tas Kungs rūc no Ciānas un paceļ Savu balsi no Jeruzālemes, ka ganības bēdājās, un Karmeļa galva nokalst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Tā saka Tas Kungs: treju vai četru Damaskus pārkāpumu dēļ - to Es nenovērsīšu, - tāpēc ka tie Gileādu kūluši ar asiem dzelzs spriguļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Tāpēc Es sūtīšu uguni Azaēļa namā, tas aprīs BenHadada skaistās pilis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Un Es salauzīšu Damaskus aizšaujamo un izdeldēšu tos iedzīvotājus no Avenas ielejas un to, kas scepteri tur no BetEdenas; un Sīrijas ļaudis taps aizvesti uz Ķiru, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Tā saka Tas Kungs: triju vai četru Gacas pārkāpumu dēļ, - to Es nenovērsīšu, - tādēļ ka tie (Manus ļaudis) lielā pulkā aizveduši, tos nodot Edomam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Tādēļ Es sūtīšu uguni Gacas mūros, tas aprīs viņas skaistos namus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Un Es izdeldēšu tos iedzīvotājus no Ašdodas, un, kas scepteri tur, no Askalonas, un Es griezīšu Savu roku pret Ekronu, ka bojā ies viss Fīlistu atlikums, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Tā saka Tas Kungs: treju vai četru Tirus pārkāpumu dēļ, - to Es nenovērsīšu, - tāpēc ka tie Manus ļaudis lielā pulkā nodevuši Edomam un nav pieminējuši brāļu derību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Tāpēc Es sūtīšu uguni Tirus mūros, un tas aprīs viņa skaistos namus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Tā saka Tas Kungs: triju vai četru Edoma pārkāpumu dēļ, - to Es nenovērsīšu, - tāpēc ka viņš savu brāli ar zobenu vajājis, un savu mīlestību iznīcinājis un savā bardzībā arvien plosās un patur mūžam savas dusmas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Tāpēc Es sūtīšu uguni Temanā, tas aprīs Bocras skaistos namus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Tā saka Tas Kungs: triju vai četru Amona bērnu pārkāpumu dēļ - to Es nenovērsīšu, - tāpēc ka tie Gileādas grūtās sievas uzšķērduši savas robežas izplest,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Tāpēc Es iededzināšu uguni Rabas mūros, tas aprīs viņas skaistos namus, kara dienas kliegšanā un vētras dienas aukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Un viņu ķēniņš ies cietumā ar saviem lielkungiem, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Tā saka Tas Kungs: triju vai četru Moaba pārkāpumu dēļ - to Es nenovērsīšu, - tādēļ ka viņš sadedzinājis Edoma ķēniņa kaulus par kaļķiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Tādēļ Es sūtīšu uguni Moabā, tas aprīs Ķiriota skaistos namus, un Moabs nomirs troksnī, kliegšanā un bazūņu skaņā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Un Es izdeldēšu soģi no viņa vidus un nokaušu visus viņa lielkungus līdz ar viņu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Tā saka Tas Kungs: triju vai četru Jūda pārkāpumu dēļ, - to Es nenovērsīšu, - tādēļ ka tie Tā Kunga bauslību atmetuši un Viņa likumus nav sargājuši, un viņu meli(elki) tos pievīluši, kuriem viņu tēvi dzinušies pakaļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Tādēļ Es sūtīšu uguni Jūdā, tas aprīs Jeruzālemes skaistos namus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Tā saka Tas Kungs: triju vai četru Israēla pārkāpumu dēļ - to Es nenovērsīšu, - tāpēc ka tie taisno pārdod par naudu un nabagu par pāri kurpju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Tie ilgojās, ka zemes pīšļi nabagiem nāk uz galvu, un bēdīgā ceļu tie kavē. Vīrs ar savu tēvu iet pie tās pašas meitas un sagāna Manu svēto vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Tie apmetās pie ikkatra altāra uz ķīlātām drēbēm, un dzer vīnu no notiesātiem, savu dievu namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Es tomēr esmu izdeldējis to Amorieti viņu priekšā, kam augstums bija kā ciedru augstums, un kas bija stiprs kā ozoli; bet Es esmu nomaitājis viņa augļus augšā un viņa saknes apakšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Un Es tomēr jūs esmu izvedis no Ēģiptes un četrdesmit gadus jūs vadījis tuksnesī, ka jums bija iemantot Amoriešu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Un citus no jūsu dēliem Es esmu cēlis par praviešiem un no jūsu jaunekļiem citus par nazīriem; vai tas tā nav, Israēla bērni? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Bet jūs nazīriem dodiet vīnu dzert, un pavēliet praviešiem un sakāt: jums nebūs sludināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Redzi, Es jums likšu čīkstēt kā rati čīkst, kas pilni kūļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Tā ka čaklais neizbēgs, nedz stiprais ar savu spēku ko iespēs, nedz varenais savu dvēseli varēs izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Un stopu vilcējs nepastāvēs, un kas vieglām kājām, neizglābsies, un ne jājējs neizglābs savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Un sirdsvarenais starp tiem stipriem aizbēgs kails tai dienā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Klausiet šo vārdu, ko Tas Kungs runā uz jums, Israēla bērni, proti uz visām tām ciltīm, ko Es no Ēģiptes zemes esmu izvedis, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Es jūs vien esmu atzinis no visām zemes tautām, tādēļ Es pie jums piemeklēšu visus jūsu noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Vai divi gan kopā staigā, ja tie papriekš nav saderējušies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Vai lauva mežā rūc, kad viņam laupījuma nav? Vai jauns lauva balsi paceļ no savas alas, kad neko nav gūstījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Vai putns iekrīt valgā pie zemes, kur valga priekš viņa nav? Vai valgs no zemes ceļas, ar ko nekas nav gūstīts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Vai pilsētā bazūnē ar bazūni, un ļaudis neiztrūkstās? Vai kāda nelaime notiek pilsētā, ko Tas Kungs nedara?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Tiešām, Tas Kungs Dievs nekā nedara, kad viņš savu noslēpumu neparāda saviem kalpiem, tiem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Kad lauva rūc, kas nebītos? Tas Kungs Dievs runā, kam nebūtu jāsludina?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Liekat to dzirdēt Ašdodas skaistos namos un Ēģiptes zemes pilīs un sakāt: sapulcinājaties uz Samarijas kalniem un redziet tos lielos trokšņus viņas vidū, un tos nospaidītos viņas starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Jo tie nezin darīt, kas tiesa(taisnība), saka Tas Kungs, krādami netaisnību un varas darbu savās pilīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Tāpēc Tas Kungs Dievs tā saka: spaidi zemei visapkārt! Un viņš nogāzīs tavu stiprumu, un tavi skaistie nami taps izpostīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Tā saka Tas Kungs: kā gans izrauj no lauvas rīkles divus stilbus vai kādu auss gabaliņu, tā Israēla bērni tiks izglābti, kas Samarijā sēž gultas kaktā uz Damaskus pēļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Klausiet un dodiet liecību Jēkaba namam, saka Tas Kungs Dievs, tas Dievs Cebaot:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Tai dienā, kad Es Israēla pārkāpumus pie viņa piemeklēšu, tad Es piemeklēšu Bēteles altārus, un tie altāra ragi taps nocirsti un kritīs zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Un Es sitīšu tiklab ziemas pili kā vasaras pili, un tie ziloņkaulu nami ies bojā, un daudz nami taps izpostīti, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Klausiet šo vārdu, Basanas govis, kas Samarijas kalnā, kas nospaida mazos, satriec nabagus, kas uz saviem kungiem saka: nesiet šurp, ka dzeram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Tas Kungs Dievs ir zvērējis pie Sava svētuma: redzi, dienas nāks pār jums, ka jūs aizvilks ar kāšiem un jūsu beidzamos ar zivju makšķerēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Un jūs iziesiet caur mūru plaisām, ikviena taisni projām, un tapsiet nomestas pret Armonu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Ejat uz Bēteli un grēkojiet! (Ejat) uz Gilgalu un vairojiet pārkāpšanu! Un nesiet savus upurus rītos, savas desmitās(tiesas) ik trešo dienu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Un kvēpinājiet pateicības upurus no raudzēta, un izsauciet labprātības upurus, liekat to dzirdēt! Jo tā tas jums patīk, Israēla bērni, saka Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Tāpēc es arīdzan jūsu zobiem esmu devis mieru visās jūsu pilsētās un maizes trūkumu visās jūsu vietās; tomēr jūs pie Manis neesat atgriezušies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Un arī lietu Es jums esmu aizturējis, kad vēl trīs mēneši bija līdz pļaujamam laikam, un esmu licis līt pār vienu pilsētu, bet pār otru ne, viens zemes gabals aplija, bet otrs gabals sakalta, kur lietus nelija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Un divas, trīs pilsētas vilkās uz vienu pilsētu, ūdeni dzert, bet nedabūja nodzerties; taču jūs pie Manis neesat atgriezušies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Es jūs esmu sitis ar bulu un ar rūsu, un siseņi ēda visu, kas aug jūsu dārzos un jūsu vīna dārzos un uz jūsu vīģes kokiem un eļļas kokiem, taču jūs pie Manis neesat atgriezušies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Es esmu sūtījis mēri jūsu vidū, kā Ēģiptes zemē, Es nokāvu jūsu jaunekļus caur zobenu un liku jūsu zirgus aizvest, un jūsu karaspēka smaržai Es liku uzkāpt jūsu nāsīs; taču jūs pie Manis neesat atgriezušies, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Es esmu sūtījis postu jūsu vidū, kā Dievs postījis Sodomu un Gomoru un jūs bijāt kā pagale izrauta no uguns, taču jūs neesat atgriezušies pie Manis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Tādēļ Es tev tā darīšu, Israēl! Kad Es tev tā gribu darīt, nu tad sataisies, Israēl, savam Dievam pretim!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Jo redzi, kas taisa kalnus, rada vēju un cilvēkam dara zināmu, kas viņa domās, kas par rīta gaismu dara tumsu un staigā pār zemes augstumiem, Kungs Dievs Cebaot ir Viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Klausiet šo vārdu, ar ko es par jums sāku raudu dziesmu, Israēla nams!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Israēla meita ir kritusi, viņa vairs necelsies, viņa ir atstāta zemē, neviena nav, kas to uzceļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Jo tā saka Tas Kungs Dievs: tai pilsētai, kur iziet tūkstoši, atliksies simts, un kur iziet simts, atliksies desmit Israēla namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Jo tā saka Tas Kungs uz Israēla namu: meklējiet Mani un dzīvojiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Bet nemeklējiet Bēteli un nenāciet uz Gilgalu un nenoejat uz Bēršebu, jo Gilgala taps aizvesta un Bētele paliks par neko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Meklējiet To Kungu un dzīvojiet, - lai Viņš neizšaujas Jāzepa namā kā uguns, kas to norij, un neviens to nevar dzēst Bētelē, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Jūs, kas tiesu pārvēršat par vērmelēm un stumjat taisnību pie zemes:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Kas radījis Sietiņu un Orijonu un nāves ēnu pārvērš par rīta gaismu un dienu aptumšo, ka nakts metās, kas jūras ūdeni sauc un to izgāž pa zemes virsu, - Kungs ir Viņa vārds,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Tam prāts ir, to spēcīgo postīt, ka posts nāk pār stipro pili.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Tie ienīst to, kas vārtos pārmāca, un kas patiesību runā, to tie tur par negantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Tādēļ ka jūs apbēdinājāt nabagu un ņemat labības dāvanu no viņa, tad jūs gan esiet uztaisījuši namus no cirstiem akmeņiem, bet jūs tanīs nedzīvosiet, jūs esat stādījuši diženus vīna dārzus, bet viņu vīnu jūs nedzersiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Jo es zinu, ka jūsu pārkāpumu daudz un jūsu grēku varen daudz. Tie nospaida taisno un ņem dāvanas, un nomāc nabagus vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Tādēļ prātīgais šinīs laikos cieš klusu, jo tie ir nikni laiki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Meklējiet labu un ne ļaunu, lai jūs dzīvojat, un tā Tas Kungs, tas Dievs Cebaot, būs ar jums, kā jūs sakāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Ienīstiet ļaunu un mīļojiet labu un spriežat vārtos tiesu, vai varbūt Tas Kungs, tas Dievs Cebaot, neapžēlosies par Jāzepa atlikušiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Tādēļ tā saka Tas Kungs, tas Dievs Cebaot, Tas Kungs: visās ielās vaimanas un visās gatvēs saka: vai, vai! Arāju sauc pie asarām, un pie vaimanām vaidētājus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Un visos vīna dārzos būs vaimanas, jo Es iešu caur jūsu vidu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Ak vai, tiem, kas ilgojās pēc Tā Kunga dienas! Par ko tad jums būs Tā Kunga diena? Tā būs tumsa un ne gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Tā kā kad vīrs bēgtu no lauvas un to sastaptu lācis! Un nāktu namā un atslietos ar roku pie sienas, un čūska viņam iedzeltu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Vai tad Tā Kunga diena nebūs tumsa un ne gaisma, un nakts, kam nav spožuma?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Es ienīstu un atmetu jūsu svētkus un negribu ost jūsu sapulces.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Jo kad jūs Man dedzināmos upurus upurējat līdz ar saviem ēdamiem upuriem, tad Man pie viņiem nav labs prāts, un pateicības upuri no jūsu barotiem lopiem Es negribu ieredzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Atstājies jel no Manis ar savu dziesmu bļaušanu, un tavu kokļu skaņu Es negribu dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Bet lai plūst tiesa kā ūdens un taisnība kā stipra upe.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Vai četrdesmit gadus tuksnesī jūs Man esat nesuši upurus un ēdamus upurus, Israēla nams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Bet jūs nesāt sava(Sikuta) ķēniņa būdu un sava Ķijuna bildi, sava dieva zvaigzni, ko jūs sev pašiem bijāt taisījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Tādēļ Es jūs aizvedīšu tālu viņpus Damaskus, saka Tas Kungs, kam vārds ir Dievs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Ak vai, tiem, kas droši dzīvo Ciānā un bez bēdām uz Samarijas kalna, tiem vareniem pirmajā tautā, pie kuriem nāk tie no Israēla nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Ejat uz Kalni un skatāties, un no turienes ejat uz Hamatu, to lielo pilsētu, tad noejat uz Gadu Fīlistos, vai tās ir labākas nekā šīs valstis, jeb vai viņu robežas lielākas nekā jūsu robežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Jūs, kam šķiet nelaimes dienu tālu esam un kas tuvu ceļat varasdarba krēslu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Kas guļat uz ziloņkaulu gultām un staipāties savās guļās un ēdat jērus no ganāmā pulka un barotos teļus no laidaru vidus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Kas pūšat somastabules un izdomājat mūzikas rīkus kā Dāvids,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Kas vīnu dzerat no kausiem un svaidāties ar visdārgāko eļļu, bet nebēdājaties par Jāzepa vainu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Tādēļ tie nu ies cietumā paši pirmie starp cietumniekiem, un plītnieku kliegšana mitēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Tas Kungs Dievs ir zvērējis pie savas dvēseles, saka Tas Kungs, tas Dievs Cebaot: Man riebj Jēkaba lepnība un Es ienīstu viņa skaistos namus, tādēļ Es to pilsētu nodošu ar visu, kas tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Un notiks, ja tur desmit vīri būs atlikuši vienā namā, tie mirs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Un kad ko ņems viņa svainis vai viņa dedzinātājs, un iznesīs tos kaulus no nama un sacīs uz to, kas nama kambarī: vai tur vēl kāds pie tevis? Un tas sacīs: nav neviena. Tad viņš sacīs: ciet klusu! Jo Tā Kunga vārdu nebūs pieminēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Jo redzi, Tas Kungs dod pavēli, un sitīs to lielo namu, ka sagrūs, un to mazo namu, ka sadrups.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Vai zirgi var skriet pa klintīm? Vai tur virsū var art ar vēršiem? Jo jūs esat pārvērtuši tiesu par žulti un taisnības augļus par vērmelēm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Jūs, kas priecājaties par nieku un sakāt: Vai mēs caur savu stiprumu sev neesam varu dabūjuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Jo redzi, pret jums, jūs Israēla nams, saka Tas Kungs, tas Dievs Cebaot, Es celšu vienu tautu, - un tā jūs nospaidīs no Hamatas ceļa līdz tuksneša upei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Tas Kungs Dievs man šādu lietu lika redzēt, un redzi, Viņš rādīja siseņus, kad atāls sāka augt, un redzi, atāls bija audzis pēc ķēniņa pļaušanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Un kad tie zāli zemes virsū visnotaļ bija aprijuši, tad es sacīju: Kungs Dievs, piedod jel! Kā Jēkabs varēs pastāvēt, jo viņš ir mazs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Tad Tam Kungam bija žēl; tas nenotiks, sacīja Tas Kungs. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Atkal Tas Kungs Dievs man šādu lietu lika redzēt, un redzi, Tas Kungs Dievs sauca un gribēja ar uguni sodīt, un tas jau norija to lielo jūru un aprija arī vienu zemes gabalu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Tad es sacīju: Kungs Dievs, mitējies jel! Kā Jēkabs varēs pastāvēt, jo viņš ir mazs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Tad tas Tam Kungam bija žēl; ir tas nenotiks, - sacīja Tas Kungs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Atkal viņš man šādu lietu lika redzēt, un redzi, Tas Kungs stāvēja uz stāva mūra, un lote(svina svērtenis) bija Viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Un Tas Kungs sacīja uz mani: ko tu redzi, Amos? Tad es sacīju: loti. Tad Tas Kungs sacīja: redzi, Es pielikšu loti vidū Maniem Israēla ļaudīm, un viņus vairs netaupīšu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Bet Īzaka elku kalni taps iznīcināti, un Israēla svētās vietas taps nopostītas, un Es celšos pret Jerobeama namu ar zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Tad Amacīja, Bēteles priesteris, sūtīja pie Jerobeama, Israēla ķēniņa, un sacīja: Amos ceļ dumpi pret tevi Israēla nama vidū, zeme nevar panest visus viņa vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Jo tā saka Amos: Jerobeams nomirs caur zobenu, un Israēls vešus no savas zemes taps aizvests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Un Amacīja sacīja uz Amosu: tu redzētāj, ej, bēdz uz Jūda zemi, un ēd tur savu maizi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Un sludini tur, bet Bētelē tev joprojām vairs nebūs sludināt, jo te ir ķēniņa svētā vieta, un te ir valsts pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Tad Amos atbildēja un sacīja uz Amacīju: es neesmu pravietis nedz pravieša dēls, bet es esmu lopu gans un lasu meža vīģes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Bet Tas Kungs mani ņēmis no ganāmā pulka, un Tas Kungs uz mani sacījis: ej, sludini Maniem Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Nu tad, klausi Tā Kunga vārdu! Tu saki: nesludini pret Israēli un nemāci pret Īzaka namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Tādēļ, tā saka Tas Kungs: tava sieva pilsētā taps par mauku, un tavi dēli un tavas meitas kritīs caur zobenu, un tava zeme taps mērota un izdalīta, un tu mirsi nešķīstā zemē, un Israēls vešus no savas zemes taps aizvests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Tas Kungs Dievs man šādu lietu lika redzēt, un raugi, tur bija kurvis ar vasaras augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Un Viņš sacīja: ko tu redzi, Amos? Un es sacīju: kurvi ar vasaras augļiem. Tad Tas Kungs uz mani sacīja: gals ir nācis maniem Israēla ļaudīm, Es tos vairs netaupīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Un Dieva nama dziesmas tai dienā taps par kaukšanu, saka Tas Kungs Dievs; tur būs daudz nomirušas miesas, ikkatrā vietā tās klusi taps nomestas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Klausiet šo vārdu, jūs, kas aprijat nabagu un izdeldat bēdu ļaudis tai zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Un sakāt: kad jaunais mēnesis pāries, ka labību pārdodam? Un svētdiena, ka labības klētis varam atdarīt un mazāku darām ēfu un sēķeli lielāku, viltīgi pārgrozīdami svaru?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Ka tos mazos varam pirkt par naudu un tos nabagus par pāri kurpju, tad pelus pārdosim par labību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Tas Kungs ir zvērējis pie Jēkaba goda: Es visus viņu darbus neaizmirsīšu nemūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Vai šādas lietas dēļ zemei nebūs kustināties, un visiem iedzīvotājiem iekš tās nebūs bēdāties? Tā visai uzplūdīs kā upe un plūdīs un nosīks kā Ēģiptes upe.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Un notiks tai dienā saka Tas Kungs Dievs, tad Es saulei likšu noiet dienas vidū un aptumšošu zemi pašā gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Un Es pārvērtīšu jūsu svētkus par bēdām un visas jūsu dziesmas par vaimanām, un uz visiem gurniem likšu maisu un uz visām galvām pleiķi(noskūt galvu), un Es likšu bēdāties kā par vienīgo dēlu, un gals būs rūgta diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Redzi, dienas nāk, saka Tas Kungs Dievs, ka es badu sūtīšu tai zemē, ne badu pēc maizes un ne tvīkšanu pēc ūdens, bet klausīt Tā Kunga vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Un tie skraidīs no vienas jūras līdz otrai, un tecēs apkārt no ziemeļa puses līdz rīta pusei Tā Kunga vārdu meklēt, bet neatradīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Tai dienā skaistās jaunavas un jaunekļi apģībs no tvīkšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Kas pie Samarijas nozieguma zvērē un saka: tik tiešām kā tavs Dievs dzīvo, Dan, tik tiešām kā tas ceļš uz Bēršebu! Un tie kritīs un vairs necelsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Es redzēju To Kungu stāvam pār altāri, un Viņš sacīja: sit uz (pīlāra) kroni, ka stenderi trīc, un sit tos uz pusēm uz visu viņu galvām! Un Es nokaušu ar zobenu, kas no viņiem atliek; kas no viņiem bēg, tas neizbēgs, un kas no viņiem skrien, tas neizglābsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Jebšu tie ieraktos ellē, taču Mana roka tos dabūs no turienes, un jebšu tie uzkāptu debesīs, taču Es tos no turienes nometīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Un jebšu tie apslēptos Karmeļa virsgalā, taču Es dzīšos pakaļ un tos no turienes atvedīšu. Un jebšu tie priekš Manām acīm apslēptos jūras dziļumā, taču Es no turienes čūskai pavēlēšu, un tā viņiem iedzels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Un jebšu tie cietumā ietu savu ienaidnieku priekšā, taču Es zobenam pavēlēšu, un tas tos nokaus, un Es Savu aci pret tiem pacelšu par ļaunu un ne par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Jo Tas Kungs Dievs Cebaot, kad Viņš zemi aizskar, tad tā izkūst, un visi iedzīvotāji tur bēdājās, un tā uzplūst kā upe un nosīkst kā Ēģiptes upe.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Viņš savu mājokli taisa debesīs un stiprina savu dzīvokli virs zemes, Viņš sauc jūras ūdeni un to izlej pa zemes virsu, - Kungs ir Viņa vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Vai jūs Man neesat kā Moru bērni, jūs Israēla bērni? saka Tas Kungs. Vai Es Israēli neesmu izvedis no Ēģiptes zemes un Fīlistus no Kaftora un Sīriešus no Ķiras?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Redzi, Tā Kunga Dieva acis (skatās) uz šo grēcīgo valsti, un Es to izdeldu no zemes virsas, jebšu Es Jēkaba namu visai(pilnīgi) neizdeldēšu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Jo redzi, Es pavēlēšu un sijāšu Israēla namu starp visiem pagāniem, tā kā (sēkla) top sijāta sietā, un neviens graudiņš nekrīt pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Caur zobenu visi grēcinieki Manā tautā nomirs, kas saka: ļaunums mums klāt nenāks un mums neuzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Tai dienā Es atkal uzcelšu Dāvida sagruvušo dzīvokli un aptaisīšu viņa šķirbas ar sētu, un kas pie tā ir salauzīts, to Es atkal uztaisīšu un to uzcelšu kā vecos laikos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Ka tie iemantos, kas no Edoma atlicis, un visus pagānus, kas pēc Mana Vārda taps nosaukti, saka Tas Kungs, un tas šo dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Redzi, dienas nāk, saka Tas Kungs, ka arājs panāks pļāvēju, un vīna ķekaru minējs sēklas sējēju un kalni pilēs no salda vīna, un visi pakalni plūdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Un Es savus Israēla ļaudis atkal pārvedīšu no cietuma, un tie uztaisīs izpostītās pilsētas un tur dzīvos un dēstīs vīna dārzus un dzers viņu vīnu un kops dārzus un ēdīs viņu augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Un Es tos dēstīšu viņu zemē, un tie vairs netaps izrauti no savas zemes, ko Es tiem esmu devis, saka Tas Kungs, tavs Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Obadijas parādīšana. Tā saka Tas Kungs Dievs par Edomu. Mēs esam vēsti dzirdējuši no Tā Kunga, un vēstnesis ir sūtīts starp pagāniem: ceļaties! Tad celsimies pret viņu karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Redzi, Es tevi esmu mazu darījis starp tiem pagāniem, tu esi ļoti nicināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Tava sirds lielība tevi pievīlusi; tu dzīvo klints alās, savos augstos dzīvokļos, un saki savā sirdī: kas mani nometīs pie zemes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Jebšu tu celtos kā ērglis, un jebšu tu savu ligzdu taisītu starp zvaigznēm, taču Es tevi no turienes nometīšu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Kad zagļi vai laupītāji pie tevis naktī būtu nākuši, (ak, kā tu esi izdeldēts!) vai tie nebūtu zaguši savu tiesu? Kad vīna lasītāji pie tevis būtu nākuši, vai tie kādas vīna stīgas nebūtu atlicinājuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Kā Ēsava (mantas) ir izmeklētas un viņa apslēptās lietas izvaicātas!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Visi tavi biedri tevi izdzen no savām robežām ārā, tavi draugi tevi pieviļ un pārvar; kas tavu maizi ēd, tie tevi ievaino. Saprašanas pie viņa nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Vai tas nenotiks tai dienā, saka Tas Kungs, ka Es iznīcināšu tos gudros no Edoma un saprašanu no Ēsava kalniem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Tavi varenie, Tēman, baiļosies, lai ikviens no Ēsava kalniem top izdeldēts kaujā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Tā varas darba dēļ, ko tu savam brālim Jēkabam esi padarījis, kauns tevi apsegs, un tu tapsi izdeldēts mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Tai dienā, kad tu viņam stāvēji pretī, tai dienā, kad naidnieki viņa spēku aizveda cietumā un svešinieki iegāja pa viņa vārtiem un meslus meta par Jeruzālemi, tad tu arīdzan biji kā viens no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Bet tev vairs ar prieku nebūs redzēt sava brāļa dienu, viņa nelaimes dienu, nedz līksmoties par Jūda bērniem viņu bēdu dienā, nedz lepoties ar savu muti bailības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Neej pa Manu ļaužu vārtiem viņu nelaimes dienā, nedz skaties uz viņu ļaunumu viņu posta dienā, nedz izstiep (rokas) pēc viņu mantām viņu bēdu dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Nestāvi uz ceļa jūtīm, viņu bēgļus izdeldēt, nedz nodod viņu atlikušos bēdu dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Jo Tā Kunga diena ir klāt pār visiem pagāniem. Tā kā tu esi darījis, tāpat tev darīs, tavi darbi atgriezīsies uz tavu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Jo kā jūs esiet dzēruši (Manu dusmu kausu) uz Mana svētā kalna, tā visi pagāni dzers bez mitēšanās, it tiešām tie dzers un plītēs, un būs tā kā tie tur nebūtu bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Bet uz Ciānas kalna būs izglābšana, un tas būs par svētumu, un tie no Jēkaba nama iemantos savas tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Un Jēkaba nams būs uguns, un Jāzepa nams liesma, un Ēsava nams būs par rugājiem, un tie pret tiem iedegsies un tos aprīs, tā ka Ēsava namam neviens neatliks, jo Tas Kungs to ir runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Un tie no dienas vidus iemantos Ēsava kalnus, un kas ielejā dzīvo, iemantos Fīlistus, un tie iemantos Efraīma lauku un Samarijas lauku, un Benjamins Gileādu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Un tie aizvestie no Israēla bērnu kara spēka iemantos to, kas Kanaāniešiem piederēja līdz Sareptai, un tie aizvestie no Jeruzālemes, kas ir Sefaradā, iemantos tās pilsētas pret dienvidiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Un pestītāji celsies uz Ciānas kalna, tiesāt Ēsava kalnus, un valstība piederēs Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Tā Kunga vārds notika uz Jonu, Amitajus dēlu, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Celies, ej uz Ninivi, to lielo pilsētu, un sludini pret to, jo viņas bezdievība ir uzkāpusi Manā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Bet Jona cēlās, bēgt no Tā Kunga vaiga uz Taršišu; un viņš nogāja uz Joppi un tur atrada laivu, kas gāja uz Taršišu, un nodeva maksu un kāpa iekšā, ar tiem braukt uz Taršišu, nost no Tā Kunga vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Bet Tas Kungs lika nākt lielam vējam jūrā, un liela vētra cēlās jūrā, tā ka tā laiva taisījās lūst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Tad tie laivinieki bijās un kliedza ikviens uz savu dievu un meta tos rīkus, kas laivā bija, jūrā, laivu atvieglināt no tiem. Bet Jona bija nogājis laivas apakšā un gulēja cietā miegā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Tad laivas virsnieks pie viņa nāca un uz viņu sacīja: ko tu guli? Celies, piesauc savu Dievu, varbūt ka tas Dievs mūs pieminēs, ka mēs neejam bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Un tie sacīja cits uz citu: iesim, metīsim meslus(lozes), lai zinām, kura dēļ šis ļaunums mums uziet? Un kad tie mesloja, tad Jona tapa iezīmēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Tad tie uz viņu sacīja: saki mums jel, kādēļ šis ļaunums pār mums nāk? Kāds tavs amats un no kurienes tu nāci? Kura ir tava zeme, un no kuras tautas tu esi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Tad viņš uz tiem sacīja: es esmu Ebrejs un bīstos To Kungu, to debes\' Dievu, kas jūru un sausumu radījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Tad tie vīri bijās ar lielu bijāšanu un uz viņu sacīja: kā tu tā esi darījis? Jo tie vīri zināja, ka viņš no Tā Kunga vaiga bēga, jo viņš tiem to bija stāstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Un tie uz viņu sacīja: ko lai mēs ar tevi darām, ka jūra mums nostājās? Jo jūra palika arvienu briesmīgāka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Un viņš uz tiem sacīja: ņemiet mani un metiet mani jūrā, tad jūra jums nostāsies; jo es zinu, ka šī lielā vētra pār jums nāk manis dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Bet tie vīri airēja un gribēja laivu vest malā, bet tie neiespēja, jo jūra palika arvienu briesmīgāka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Tad tie piesauca To Kungu un sacīja: ak Kungs, lai jel mēs neejam bojā šā vīra dvēseles dēļ, un nepielīdzini mums nenoziedzīgas asinis, jo Tu, Kungs, esi darījis, kā Tev bija pa prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Un tie ņēma Jonu un viņu iemeta jūrā; tad jūra nostājās no savas kaukšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Tad tie vīri bijās To Kungu ar lielu bijāšanu un upurēja Tam Kungam upurus un solīja solījumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Un Tas Kungs sūtīja lielu zivi, Jonu aprīt, un Jona sabija tās zivs vēderā trīs dienas un trīs naktis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Un Jona pielūdza To Kungu, savu Dievu, no zivs vēdera');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Un sacīja: es piesaucu To Kungu savās bēdās, un Viņš man atbildēja, es kliedzu no elles vēdera, un Tu klausīji manu balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Tu mani nometi dziļumā, jūras apakšā, un ūdens mani apstāja, visi Tavi plūdi un Tavi viļņi gāja pār mani pāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Tad es sacīju: es esmu atmests no Tavām acīm, tomēr es atkal skatīšu Tavu svēto namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Ūdens mani apstāja līdz pašai dvēselei, dziļumi mani apkampa, ašķi apsedza manu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Es nogrimu pie kalnu pamatiem, zeme savas durvis pār mani bija aizdarījusi mūžīgi, bet Tu manu dzīvību esi izvedis no posta, Kungs, mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Kad mana dvēsele iekš manis izsamisējās, tad es pieminēju To Kungu, un mana lūgšana nāca pie Tevis Tavā svētā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Kas turas pie viltīgas nelietības tie zaudē savu žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Bet es Tev upurēšu ar pateicības balsi; ko esmu solījis, to es maksāšu. Pie Tā Kunga ir pestīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Un Tas Kungs runāja uz to zivi, un tā izvēma Jonu malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Un Tā Kunga vārds notika otru reizi uz Jonu sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Celies, ej uz Ninivi, to lielo pilsētu, un sludini pret viņu to sludināšanu, ko Es tev sacīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Tad Jona cēlās un gāja uz Ninivi pēc Tā Kunga vārda. Bet Ninive bija liela Dieva pilsēta treju dienu gājumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Un Jona sāka pilsētā iet vienas dienas gājumu un sludināja un sacīja: vēl četrdesmit dienas, tad Ninive taps apgāzta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Tad Ninives ļaudis ticēja uz Dievu un izsauca gavēni un apģērbās ar maisiem, gan lieli, gan mazi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Un kad tas vārds Ninives ķēniņa priekšā nāca, tad viņš cēlās no sava goda krēsla un nolika savas ķēniņa drēbes no sevis un apvilka maisu un apsēdās pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Un viņš lika izsaukt un sludināt Ninivē ķēniņa un viņa lielkungu pavēli: lai ne cilvēks, ne lops, ne vērsis, ne avs nekā nebauda, lai neiet ganos un nedzer ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Bet cilvēki un lopi lai sedzās ar maisiem un Dievu gauži piesauc, un lai tie atgriežas ikviens no sava ļaunā ceļa un no tā varas darba, kas viņu rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Varbūt ka Dievs atgriezīsies, un Viņam būs žēl un atkāpsies no Savas dusmības karstuma, ka mēs neejam bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Un Dievs redzēja viņu darbus, ka tie atgriezās no sava niknā ceļa, un Dievam palika žēl viss tas ļaunums, ko Viņš bija runājis, tiem darīt, un to nedarīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Tas rieba Jonam ar gaužu riebšanu, un viņa dusmība iedegās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Un viņš pielūdza To Kungu un sacīja: ak Kungs, vai es tā nesacīju, kad es vēl biju savā zemē? Tāpēc es papriekš steidzos bēgt uz Taršišu, jo es zināju, ka Tu esi žēlīgs un žēlsirdīgs Dievs, lēnprātīgs un no lielas žēlastības, kam paliek žēl par to ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Tad nu, Kungs, ņem manu dvēseli no manis, jo man ir labāki mirt nekā dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Bet Tas Kungs sacīja: vai tu gan dusmo pareizi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Un Jona izgāja no pilsētas un apsēdās pret rīta pusi no pilsētas un tur sev taisīja būdiņu un apsēdās tur pavēnī, tiekams redzētu, kas ar to pilsētu būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Tad Dievs Tas Kungs deva rīcinus stādu (ar lielām lapām); tas uzauga pār Jonu, lai viņam būtu ēna pār galvu un lai viņu atsvabinātu no viņa ļaunuma; un Jona priecājās par to rīcinus stādu ar lielu prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Bet Dievs deva tārpu otrā dienā, kad saule uzlēca, tas dūra to rīcinus stādu, ka tas nokalta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Un kad saule uzlēca, tad Dievs deva sausu rīta vēju, un saule spieda Jonam uz galvu, ka tas kļuva gurdens, un viņš savai dvēselei vēlēja mirt un sacīja: labāk man būtu mirt nekā dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Tad Dievs sacīja uz Jonu: vai tev šķiet, ka tu pareizi dusmo par to rīcinus stādu? Un viņš sacīja: gan pareizi es dusmoju līdz pat nāvei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Bet Tas Kungs sacīja: tev ir žēl tā rīcinus stāda, pie kā tu neesi ne strādājis ne to audzinājis, kas vienā naktī cēlies un vienā naktī nozudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Un Man nebija žēlot to lielo pilsētu Ninivi, kur iekšā daudz vairāk nekā simts un divdesmit tūkstoši cilvēku, kas nezin izšķirt labo no kreisās rokas, un daudz lopu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Šis ir Tā Kunga vārds, kas noticis uz Mihu, to Marezieti, Jotama, Ahazs, Hizkijas, Jūda ķēniņu, dienās, ko viņš redzējis par Samariju un Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Klausāties, tautas visas, ņem vērā, zeme un viss, kas tur iekšā, jo Tas Kungs Dievs pret jums būs liecinieks, Tas Kungs no Sava svētā nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Jo redzi, Tas Kungs iziet no Savas vietas, viņš nolaižas un stāv uz zemes augstumiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Un kalni apakš Viņa izkūst, un ielejas izšķīst kā vasks ugunī, kā ūdens, kas gāžas uz leju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Šo visu Viņš darīs Jēkaba nozieguma dēļ un Israēla bērnu grēku dēļ. Bet kur ir Jēkaba noziegums? Vai ne Samarijā? Un kur ir Jūda elku altāri? Vai ne Jeruzālemē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Tāpēc Es Samariju darīšu par akmeņu kopu laukā, par vīna dārzu, un Es viņas akmeņus nogāzīšu ielejā un atklāšu viņas pamatus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Un visi viņas dievekļi taps sadauzīti, un visas viņas mauku dāvanas taps sadedzinātas ar uguni, un visus viņas elkadievus Es darīšu par tuksnesi; jo tie ir sakrāti no mauku algas, un paliks atkal par mauku algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Par to man jābēdājas un jāraud, es iešu aplaupīts un kails, es sākšu kaukt kā šakāļi un gaust kā jauni strausi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Jo viņas mocības ir nāvīgas, jo tās ir nākušas līdz Jūdam, un stiepjas līdz manu ļaužu vārtiem, līdz Jeruzālemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Nesludinājiet to Gatā, neraudiet tik gauži, vārtaties pīšļos pīšļu namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Aizej Šafīras iedzīvotāja, bezkaunīgi atsegta! Caēnanas iedzīvotāja neiziet; žēlošana Betecelē nestājās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Jo Marotas iedzīvotāja noskumst par to (zudušo) labumu, ka ļaunums no Tā Kunga ir nācis līdz Jeruzālemes vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Jūdz zirgus ratos, Lakisas iedzīvotāja; še ir grēku iesākums Ciānas meitai, ka iekš tevis Israēla noziegumi ir atrasti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Tādēļ sūti dāvanas uz Gatas Marezeti. Aksibas nami Israēla ķēniņiem paliks par meliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Es tev vēl reiz atvedīšu mantinieku, Marezas iedzīvotāja; uz Adulamu aizies Israēla gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Nodzeni sev galvu pliku savu mīļo bērnu dēļ, dari savu pleiķi platu kā (maitu)lijai, tāpēc ka tie no tevis ir aizvesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Ak vai, tiem, kas domā netaisnību un sataisa ļaunumu uz savām cisām; rīta gaismā tie to izdara, jo viņu roka to iespēj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Un tie iekāro tīrumus un tos laupa, un namus, un tos paņem; tā tie dara varas darbu pie vīra un viņa nama, pie cilvēka un viņa mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Tādēļ Tas Kungs tā saka: redzi, Es domāju ļaunumu pret šo cilti, no tā jūs savus kaklus neizvilksiet un nestaigāsiet tik grezni; jo laiks ir ļauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Tai dienā cels sakāmu vārdu par jums un gauži žēlosies: „tas noticis“, sacīs: „mēs pavisam postīti! Manu ļaužu tiesa top izmīta; kā Viņš man to atrauj! Atkāpējiem Viņš izdala mūsu tīrumus.“');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Tāpēc tev nebūs neviena, kas tev zemi mēros un dalīs Tā Kunga draudzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '„Nesludinājiet!” Tā tie sludina. Ja tiem nesludinās, tad negods nezudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Tu, ko sauc par Jēkaba namu, vai tad Tas Kungs nepacietīgs? Vai tādi ir viņa darbi? Vai Mani vārdi nav laipnīgi tam, kas staigā, kā piederās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Bet nesen Mani ļaudis cēlās kā ienaidnieki; jūs laupāt no apģērba mēteli tiem, kas mierīgi iet garām un nemeklē kara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Jūs izdzenāt Manu ļaužu sievas no viņu skaistiem namiem, jūs atņemat viņu bērniņiem Manu glītumu mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Ceļaties un ejat projām, jo šī zeme jums nebūs par dusu tās nešķīstības dēļ, kas pavisam maitāt samaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Ja es būtu tāds vīrs, kas pēc vēja un viltības grābstās un melotu, ja es tev sludinātu par vīnu un dzērienu, tad es būtu pravietis priekš šiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Pulcināt Es tevi sapulcināšu, Jēkab, lasīt Es salasīšu kopā Israēla atlikušos, Es tos kā avis likšu stiprā kūtī, kā ganāmu pulku viņu laidaros, - tur no cilvēkiem rībēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Lauzējs staigās viņu priekšā, tie lauzīsies iekšā un ieies pa vārtiem un atkal izies tur ārā, un viņu ķēniņš tiem ies priekšā, un Tas Kungs būs viņu vadonis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Un es sacīju: “Klausāties jel, Jēkaba virsnieki un Israēla nama valdnieki: Vai jums nepiekrīt tiesu zināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Jūs ienīstat labu un mīļojat ļaunu, jūs tiem noplēšat ādu un gaļu no viņu kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Tiešām tie ir, kas ēd Manu ļaužu gaļu un tiem nodīrā ādu un satriec viņu kaulus un pa gabaliem saliek tā kā podā un kā gaļu katlā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Tad tie brēks uz To Kungu, bet Viņš tos nepaklausīs, Viņš tanī laikā Savu vaigu no viņiem apslēps, tā kā viņu darbi bijuši ļauni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Tā saka Tas Kungs pret tiem praviešiem, kas Manus ļaudis maldina, kas izsauc mieru, kad viņu zobiem ir ko kost; bet kas viņiem nekā nedod mutē, pret to viņi sludina karu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, '“Nakts pār jums metīsies parādīšanu vietā, un tumsa būs pār jums zīlēšanas vietā, un saule noies pār šiem praviešiem, un diena taps melna pār viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Un pareģi taps kaunā, un zīlnieki nosarks, un tiem visiem būs aptīt savu muti, jo Dieva atbildes nebūs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Bet es esmu pilns spēka no Tā Kunga Gara un pilns tiesas un sirds drošības, pasludināt Jēkabam viņa pārkāpumu un Israēlim viņa grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Klausiet jel šo, Jēkaba nama virsnieki un Israēla nama valdnieki, kam taisnība ir riebīga un kas pārgrozāt visu patiesību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Un uztaisāt Ciānu ar asinīm un Jeruzālemi ar netaisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Viņas virsnieki tiesā par dāvanām, un viņas priesteri māca par algu, un viņas pravieši zīlē par naudu, tomēr tie paļaujas uz To Kungu un saka: “Vai Tas Kungs nav mūsu vidū? Mums ļaunums neuzies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Tāpēc jūsu dēļ Ciāna taps arta kā tīrums, un Jeruzāleme paliks par akmeņu kopu un šī nama kalns par meža kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Un notiks pastara laikā, tad Tā Kunga nama kalns stāvēs pāri pār visiem kalniem un būs paaugstināts pār pakalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Un tautas tur plūdīs un daudz pagāni tur noies un sacīs: “Nāciet, ejam augšā uz Tā Kunga kalnu un uz Jēkaba Dieva namu, ka Viņš mums māca Savus ceļus, un mēs staigājam Viņa tekās”, jo no Ciānas izies mācība un Tā Kunga vārds no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Un Viņš tiesās lielas tautas un sodīs varenus pagānus it tālu, un tie pārkals savus zobenus par lemešiem un savus šķēpus par cirpēm (ecešām), tauta pret tautu nepacels zobenu un vairs nemācīsies karot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Bet tie sēdēs ikviens apakš sava vīna koka un apakš sava vīģes koka, un nebūs neviena, kas tos iztrūcinās, jo Tā Kunga Cebaot mute to runājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Jo visas tautas staigā ikviena sava dieva vārdā, bet mēs staigāsim Tā Kunga, sava Dieva, vārdā mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, '“Tai dienā,” saka Tas Kungs, “Es sapulcināšu, kas klibo, un salasīšu, kas aizdzīts, un ko Es biju mocījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Un Es darīšu, ka klibajam būs atlikums un ka aizdzītais paliks par varenu tautu, un Tas Kungs būs ķēniņš pār tiem Ciānas kalnā no šā laika un mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Un tu ganības torni, Ciānas meitas stiprums, pie tevis nāks un tev tiks tā pirmā valdība, Jeruzālemes meitas valstība.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Nu tad, kāpēc tu brēc ar tādu brēkšanu? Vai tev nav ķēniņa? Vai tavs padoma devējs gājis bojā, ka tevi sāpes sagrābušas, kā dzemdētāju?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Ciet jel un vaidi, Ciānas meita, kā dzemdētāja. Jo nu tu gan iziesi no pilsētas ārā un dzīvosi laukā un iesi uz Bābeli, bet tur tu tapsi izglābta, tur tevi Tas Kungs izpestīs no tavu ienaidnieku rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Nu gan daudz pagānu pret tevi sapulcināti un saka: lai viņa top sagānīta, lai mūsu acis (prieku) redz pie Ciānas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Bet tie nezin Tā Kunga domas un nesaprot Viņa padomu, ka Viņš tos sakrājis kā kūlīšus piedarbā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Celies un kul, Ciānas meita, jo Es tavu ragu darīšu par dzelzi un tavus nagus par varu, un tu sakulsi daudz tautas; tad es Tam Kungam nosvētīšu, ko viņi laupījuši, un viņu padomu visas pasaules Valdītājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Nu tad pulcējies, pulku meita; viņi pret mums apmetīsies. Tie ar rīksti sitīs Israēla soģi vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Un tu Bētleme Efrata, jebšu tu esi maza starp tiem tūkstošiem no Jūda, no tevis Man izies (Tas), kas būs Valdnieks iekš Israēla, un kura iziešana ir no iesākuma, no mūžīgām dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Tādēļ Viņš tos nodos līdz tam laikam, kur dzemdētāja dzemdēs. Tad viņa atlikušie brāļi atgriezīsies pie Israēla bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Un Viņš stāvēs un ganīs Tā Kunga spēkā, ar Tā Kunga, sava Dieva, vārda augstību. Un tie dzīvos, jo nu Viņš taps liels līdz pasaules galiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Un šis būs miers. Kad Asurs nāks mūsu zemē un ieies mūsu pilīs, tad mēs pret to iecelsim septiņus ganus un astoņus cilvēku virsniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Tie noganīs Asura zemi ar zobenu un Nimroda zemi viņas vārtos. Tā Viņš mūs izglābs no Asura, kad tas nāks mūsu zemē, un kad ieies mūsu robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Un Jēkaba atlikums būs daudz tautu starpā kā rasa no Tā Kunga, kā lietus lāses uz zāles, kas negaida uz nevienu nedz cerē uz cilvēka bērnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Tiešām, Jēkaba atlikums būs pagānu starpā, daudz tautu vidū, kā lauva starp meža zvēriem, kā jauns lauva starp avju ganāmiem pulkiem, kas ielauzies samin un saplosa, un nav glābēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Tava roka būs paaugstināta pār taviem pretiniekiem, un visi tavi ienaidnieki taps izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, '“Un notiks tai dienā”, saka Tas Kungs, “ka Es izdeldēšu tavus zirgus no tava vidus un iznīcināšu tavus ratus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Un Es izdeldēšu tavas zemes pilsētas un nolauzīšu visas tavas stiprās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Un Es izdeldēšu buršanu no tavas rokas, ka zīlnieki pie tevis vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Un Es izdeldēšu tavus dievekļus un tavus elkudievu stabus no tava vidus, un tu nemetīsies zemē priekš savu roku darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Es izraušu tavas ašeras no tava vidus un iznīcināšu tavas pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Un Es atriebšos ar dusmību un bardzību pie tiem pagāniem, kas neklausa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Klausāties jel, ko Tas Kungs saka: “Celies, tiesājies ar kalniem, un pakalni lai dzird tavu balsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Klausāties, kalni, Tā Kunga tiesāšanos un jūs stiprie zemes pamati, jo Tam Kungam ir tiesas lieta ar Saviem ļaudīm, un Viņš grib tiesāties ar Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '“Ak Mana tauta, ko Es tev esmu darījis? Ar ko Es tevi esmu apgrūtinājis? Atbildi Man!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Gan Es tevi esmu izvedis no Ēģiptes zemes un tevi izpestījis no vergu nama un tavā priekšā sūtījis Mozu un Āronu un Mirjamu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mana tauta, piemini jel, ko Balaks, Moaba ķēniņš, izdomāja, un ko Bileāms, Peora dēls, viņam atbildēja, no Sitimas līdz Gilgalai, lai tu atzīsti Tā Kunga taisnību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Ar ko es iešu pretī Tam Kungam? Kā zemošos tā augstā Dieva priekšā? Vai iešu Viņam pretī ar dedzināmiem upuriem, ar gada veciem teļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Vai Tam Kungam būtu labs prāts pie tūkstošiem auniem? Vai pie desmit tūkstošām eļļas upēm? Vai došu savu pirmdzimto par savu noziegumu, savas miesas augli par savas dvēseles grēkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Viņš tev, cilvēks, darījis zināmu, kas labs, un ko Tas Kungs no tevis prasa: tikai taisnību darīt, žēlastību mīlēt un pazemīgi staigāt sava Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Tā Kunga balss sauc pilsētai un gudrība ir Tavu Vārdu bīties: “Klausies to rīksti(zizli) un Kas to draud.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Vai bezdievīga namā vēl paliek netaisnas mantas un tā sasodītā mazā ēfa?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Vai nenoziedzīgs būšu pie bezdievīga svara un pie maisa ar viltīgiem svara akmeņiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Viņas bagātie piepildās ar varas darbu, un viņas iedzīvotāji runā melus, un viņu mēle ir viltīga viņu mutē!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Tādēļ arī Es tevi ievainošu, un tevi sitīšu un postīšu tavu grēku dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Tu ēdīsi, bet nepieēdīsies, un tavs vēders būs tukšs; un ko tu nesīsi, to tu neaiznesīsi, un ko tu aiznesīsi, to es nodošu zobenam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Tu sēsi, bet nepļausi, tu mīsi eļļas ogas, bet ar eļļu nesvaidīsies, un jaunu vīnu(darināsi), bet vīna nedzersi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Jo tur cienī Omrus ieradumu un visus Ahaba nama darbus, un jūs staigājat viņu padomos. Tādēļ Es tevi nodošu par postu un viņas iedzīvotājus par apsmieklu, un jūs nesīsiet Manu ļaužu negodu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Vai man, jo es esmu, kā kad koku augļi sakrāti, kā kad vīna ogas otru reiz nolasītas; neviena ķekara ko ēst, nevienas agrīnās vīģes, kas manai dvēselei gribās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Dievbijīgie iznīkuši no zemes, un taisna nav cilvēku vidū; tie visnotaļ glūn uz asinīm, cits citam tie met tīklus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Abām rokām tie dara ļaunu cik spēdami; valdnieks prasa un soģis tiesā par maksu, un lielskungs izrunā savas sirds kārību, un tā tie to sapin.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Tas labākais no tiem ir kā ērkšķis, un tas taisnākais kā ērkšķu krūms. Tavu sargu diena, tava piemeklēšana nāk - tad tie būs izsamisuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Neticat tuvākam un nepaļaujaties uz draugu; pasargi savas mutes durvis priekš tās, kas guļ tavā klēpī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Jo dēls nicina tēvu, meita ceļas pret savu māti, vedekla pret savu vīra māti, cilvēka ienaidnieki ir viņa paša mājas ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Bet es cerēšu uz To Kungu, es gaidīšu uz Dievu, savu Pestītāju; mans Dievs mani paklausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Nepriecājies, mana ienaidniece! Kad es esmu kritis, es atkal celšos; kad es sēžu tumsībā, tad Tas Kungs ir mans gaišums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Es nesīšu Tā Kunga dusmību, jo es pret Viņu esmu grēkojis, tiekams Viņš iztiesās manu tiesas lietu un man nesīs tiesu. Viņš mani vedīs gaismā, es redzēšu ar prieku Viņa taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Un mana ienaidniece to redzēs un taps apsegta ar kaunu, - kas uz mani saka: kur ir Tas Kungs, tavs Dievs? Manas acis redzēs, ka viņu samīs kā dubļus ielā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Nāks diena, tad tavi mūri taps uzcelti, tanī dienā robeža tālu sniegsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Tanī dienā pie tevis nāks no Asura un Ēģiptes pilsētām, un no Ēģiptes līdz lielupei, un no vienas jūras līdz otrai un no viena kalna līdz otram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Bet zeme taps postā savu iedzīvotāju dēļ, viņu darba augļu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Tu tad gani Savus ļaudis ar Savu zizli, Savas mantības ganāmo pulku, kas savrup dzīvo Karmeļa mežā; lai tie gana pa Basanu un Gileādu tā kā vecos laikos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Es tiem likšu brīnumus redzēt, kā tanīs dienās, kad jūs izgājāt no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Pagāni to redzēs un taps kaunā ar visu savu varu, tie roku liks uz muti, viņu ausis taps kurlas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Tie laizīs pīšļus kā čūska, kā zemes tārpi tie trīcēs savās pilīs, tie bīsies To Kungu, mūsu Dievu, un baiļosies no Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kur ir tāds Dievs kā Tu? Kas piedod noziegumu un pamet pārkāpumu Savas mantības atlikušiem; Viņš nepatur Savu dusmību mūžīgi, jo Viņam ir labs prāts žēlot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Viņš atkal par mums apžēlosies, Viņš deldēs mūsu noziegumus. Tiešām, Tu visus viņu grēkus metīsi jūras dziļumos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Jēkabam Tu parādīsi uzticību, Ābrahāmam žēlastību, ko mūsu tēviem esi zvērējis no vecām dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Spriedums par Ninivi. Nakuma, tā Elkozieša, parādīšanas grāmata.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Bargs Dievs un atriebējs ir Tas Kungs, Tas Kungs ir atriebējs un ļoti bargs, Tas Kungs ir atriebējs Saviem pretiniekiem, un atmaksā Saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Tas Kungs ir lēnprātīgs un liels spēkā, bet nepamet nesodītu; Tā Kunga ceļš ir viesulī un vētrā, un padebesī ir Viņa kāju pīšļi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Viņš rāj jūru, un tā izsīkst, Viņš izžāvē visas upes; Basana un Karmels vīst, arī Lībanus zaļums nokalst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Kalni Viņa priekšā dreb, un pakalni izkūst, zeme trīc Viņa priekšā un pasaule un visi, kas tur dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kas pastāvēs priekš Viņa dusmības, un kas pacelsies Viņa bardzības karstumā? Viņa dusmība ir izgāzta kā uguns, un akmens kalni no Viņa top sašķelti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Tas Kungs ir labs, patvērums bēdu dienā, Viņš pazīst tos, kas uz Viņu paļaujas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Bet ar lielu lieliem plūdiem Viņš iznīcinās viņas(Ninives) vietu, un tumsība vajās Savus(Viņa) ienaidniekus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Ko jūs domājat pret To Kungu? Viņš darīs galu; bēdas divreiz necelsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Jo lai tie ir sapinušies kā ērkšķi un pilni kā mucas, tie taps pavisam aprīti kā sausi rugāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'No tevis(Ninive) ir izgājis, kas ļaunu domā pret To Kungu, nesās ar negantu padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Tā saka Tas Kungs: jebšu tiem labi izdodas, un jebšu viņu ir daudz, taču tie taps nocirsti un būs pagalam. Es tevi(Jūda) gan esmu spaidījis, bet Es tevi vairs nespaidīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Bet nu Es viņa jūgu no tevis salauzīšu un saraušu tavas saites,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Bet pret tevi Tas Kungs ir pavēlējis, ka no tava vārda vairs nebūs dzimums; no tava dieva nama Es izdeldēšu grieztas un lietas bildes; Es tev rakšu tavu kapu, jo tu esi viegls atrasts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Redzi, uz kalniem prieka vēstnešu kājas, kas mieru sludina; svētī savus svētkus, ak Jūda, maksā savus solījumus; jo tas negantais pie tevis vairs nenāks, viņš ir pavisam izdeldēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Postītājs ceļas pret tevi, - sargi pili, lūko uz ceļu, stiprini gurnus un centies spēcīgi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Jo Tas Kungs atkal uzceļ Jēkaba godību, tā kā Israēla godību, jo laupītāji tos aplaupījuši un maitājuši viņu vīna stīgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Viņa varoņu priekšturamās bruņas ir sarkanas, viņa kara ļaudis purpurā ģērbušies, rati spīd kā uguns liesmas tai dienā, kad viņš apbruņojās, un šķēpi top cilāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Rati rīb uz ielām, tie skraida gatvēs, viņu izskats ir kā uguns lāpas, tie laistās kā zibeņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Viņš piemin savus varenos, tie klūp savā ceļā, tie steidzās uz mūriem un sataisa patvērumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Upju vārti ir atdarīti, un pils iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Un ķēniņiene krīt kaunā un top aizvesta, un viņas kalpotājas vaid kā baloži un sit pie savām krūtīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Jo Ninive bija kā ūdeņu ezers no tā laika, kad tā cēlusies. Bet tie bēg. Stāvat, stāvat! Bet neviens neskatās atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Laupāt sudrabu, laupāt zeltu, jo tur mantas bez gala un visādu dārgumu papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Posts un postaža un tuksnesis, sirds izkūst, ceļi dreb, un visi gurni gurst, un visi viņu vaigi nobāl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Kur nu ir tas lauvu dzīvoklis un tā jauno lauvu ganība, kur tas lauva, tā lauvu māte ar tiem lauvu bērniem staigāja, un nebija, kas tos iztraucēja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Bet tas lauva laupīja gan priekš saviem bērniem un žņaudza priekš tām lauvu mātēm, savas alas viņš pildīja ar laupījumu un savus dzīvokļus ar to, ko saplosīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Redzi, Es celšos pret tevi, saka Tas Kungs Cebaot; un sadedzināšu dūmos viņas ratus un zobens aprīs tavus lauvu bērnus, un Es izdeldēšu tavu laupījumu no zemes, un tavu vēstnešu balsi vairs nedzirdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Ak vai, tai asins pilsētai, kas visa pilna melu un varas darbu; laupīšana tur nemitās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Klau, pātagas plīkšķ, riteņi rīb, zirgi skraida un rati rūc!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Jātnieki jāj, zobeni zib, šķēpi spīd! Bez skaita nokauto, pulkiem mirušo, bez gala līķu, ka krīt pār līķiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Viss tas notiks caur tās daiļās maukas, tās gudrās burves, lielo maucību, kas ar savu maukošanu tautas apmānījusi un ciltis ar savu buršanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Redzi, Es esmu pret tevi, saka Tas Kungs Cebaot, un Es atsegšu tavas (drēbju) vīles tavā priekšā, un rādīšu pagāniem tavu plikumu un valstīm tavu kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Es metīšu uz tevi gānekļus un tevi sagānīšu un likšu tevi par biedēkli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Ka visi, kas tevi redz, no tevis bēgs un sacīs: Ninive ir postīta! Kam tās būs žēl? Kur man tev meklēt iepriecinātājus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Vai tu esi labāka nekā NoAmona, kas sēdēja pie upēm, kam visapkārt bija ūdeņi, kam jūra bija par stiprumu un jūra par mūri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Moru(Etiopiešu) zeme bija viņas stiprums un Ēģipte bez gala, Puts un Libija tev bija par palīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Viņa arīdzan ir aizvesta un gājusi cietumā, arī viņas bērni ir nokauti visu ielu stūros, un par viņas goda vīriem meta meslus, un visus viņas lielkungus slēdza ķēdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Tāpat tev būs piedzerties un krist tumsā un meklēt patvērumu no saviem ienaidniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Visas tavas stiprās pilis ir kā vīģes koki ar pirmiem augļiem; kad tos krata, tad tie krīt mutē ēdējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Redzi, tavi ļaudis tavā vidū ir bābas, tavas zemes vārti atveras taviem ienaidniekiem, uguns aprij tavus aizšaujamos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Smelies ūdeni, jo tu tapsi apsēsta, stiprini savas pilis, ej uz ķieģeļu cepli un min mālus, taisi stiprus ķieģeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Uguns tevi aprīs, zobens tevi izdeldēs, viņš tevi norīs kā vaboli; vairojies kā vaboles, vairojies kā siseņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Tev ir vairāk tirgotāju nekā debess zvaigznes; vaboles izpleš spārnus un aizskrien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Tavi cienīgie ir kā siseņi, un tavi virsnieki kā vaboles, kas apmetās pie sētām dzestrā laikā, bet kad saule uzlec, tad tie aizskrien, tā ka viņu vietu nezin, kur tie ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Tavi gani, ak Asīrijas ķēniņ, guļ, tavi cienīgie dus, tavi ļaudis izklīduši pa kalniem, un neviens tos nesapulcina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Tavai vainai nav dziedināšanas, tava kaite ir nāvīga; visi, kas par tevi dzird, sasit rokas par tevi. Jo kam tavs niknums nav uzgājis bez mitēšanās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Spriedums, ko pravietis Habakuks redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Cik ilgi, ak Kungs, es kliegšu un Tu nepaklausi? Cik ilgi es Tevi piesaukšu par varas darbu, un Tu neizglābi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Kāpēc Tu man lieci redzēt netaisnību un skaties uz varas darbu? Jo posts un varas darbs ir manā priekšā, un ķildas rodas un bāršanās ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Tāpēc bauslība paliek bez spēka un tiesa nekad nenāk gaismā, jo bezdievīgie apstāj taisno, tādēļ tiesa tiek pārgrozīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Skatāties uz tautām un ņemat vērā un brīnīdamies brīnaties, jo Es daru darbu jūsu dienās, ko jūs neticēsiet, kad to stāstīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Jo redzi, Es atvedīšu Kaldejus, rūgtu un čaklu tautu, kas izplētīsies pār zemi un iemantos mājas vietas, kas viņai nepieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Šī ir briesmīga un bijājama(tauta), viņas tiesa un augstība iziet no viņas pašas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Jo viņas zirgi ir čaklāki nekā pardeļi un žiglāki nekā vilki vakarā. Un viņas jātnieki skraida, viņas jātnieki nāk no tālienes un atskrien kā ērglis, kas steidzās uz barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Tie visi nāk uz varas darbu; kurp tie savu vaigu griež, tur tie laužās cauri kā rīta vējš un sagrābj cietumniekus kā smiltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Un viņš apmēda ķēniņus, un valdnieki tam par apsmieklu, viņš apsmej visas stiprās pilis un saber pīšļus un tās uzņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Tad viņš griežas kā vējš un aizskrien un noziedzās, turēdams savu spēku par savu dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Vai Tu neesi no iesākuma Tas Kungs, mans Dievs, mans Svētais? Mēs nemirsim. Tu, Kungs, viņu esi iecēlis par sodību, un viņu apstiprinājis, Tu akmens kalns, par pārmācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Tavas acis ir šķīstas, ka nevar ieredzēt ļaunumu, un grūtumu Tu nevari uzlūkot. Kāpēc Tu gribi skatīties uz atkāpējiem un klusu ciest, kad bezdievīgais to aprij, kas taisnāks nekā viņš?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Un kāpēc Tu cilvēkus gribi darīt kā zivis jūrā, kā līdējus tārpus, kam valdnieka nav?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Viņš visus izvelk ar makšķeri, viņš tos sakrāj savā tīklā, un tos sapulcina savos valgos, tāpēc viņš priecājās un līksmojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Tādēļ viņš upurē savam tīklam un kvēpina saviem valgiem, jo caur tiem viņa tiesa ir palikusi tauka un viņa barība garda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Vai viņš tad tāpēc iztukšos savu tīklu? Vai viņš arvien tautas apkaus bez žēlastības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Es stāvu uz vakts un kāpju tornī un skatos, lai redzu, ko Viņš man sacīs, un ko man būs atbildēt uz manu sūdzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Un Tas Kungs man atbildēja un sacīja: raksti to parādīšanu un uzraksti to uz galdiem, ka to var viegli lasīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Tai parādīšanai ir savs noliktais laiks un tā steidzās uz galu un nevils; jebšu tā gan kavējās, tomēr gaidi, jo tā nāktin nāks un nepaliks nepiepildīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Redzi, dvēsele viņam ir pārgalvīga un netaisna, bet taisnais dzīvos caur savu ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Un turklāt kā viltīgs vīns ir lepns vīrs; tas nepastāv; tas atpleš savu dvēseli platu kā elli, un kā nāve tas nav pieēdināms; tas rauj pie sevis visas tautas un sakrāj pie sevis visus ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Vai tad šie visi par to neuzņems sakāmu vārdu un mīklu un dziesmas par to? Un tie sacīs: vai tam, kas savu padomu vairo ar svešu mantu, - cik ilgi tas būs? Un uzkrauj sev smagus parādus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Vai tad nejauši necelsies tavi parādu dzinēji un neuzmodīsies tavi spaidītāji? Un tu viņiem tapsi par laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Tāpēc ka tu daudz tautas esi aplaupījis, tad visas atlikušās tautas tevi aplaupīs, cilvēku asiņu dēļ un tā varas darba dēļ pie zemes, pie pilsētām un pie visiem viņu iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Vai tam, kas netaisnu mantu krāj savam namam, ka savu ligzdu taisa augstā vietā, lai no ļaunuma izglābjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Kauna lietu tu esi izdomājis savam namam, izdeldēdams daudz ļaužu; tā tu esi grēkojis pret savu dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Jo akmens mūrī brēks un baļķis griestos viņam atbildēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Vai tam, kas pilsētas uzceļ ar asinīm un kas pilis uztaisa ar netaisnību!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Redzi, vai tas nav no Tā Kunga Cebaot, ka ļaudis strādā priekš uguns un tautas darbojās velti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Jo zeme taps piepildīta ar Tā Kunga godības atzīšanu, kā ūdens apklāj jūras dibenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Vai tam, kas savu tuvāku dzirdina, Tavas dusmas piejaukdams, un viņu piedzirdina, ka var redzēt viņa plikumu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Tu esi pieēdināts ar kaunu, ne ar godu. Dzer tu arīdzan un atklāji priekšādu! Tā Kunga labās rokas biķeris griezīsies pie tevis un negods nāks pār tavu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Jo tas varas darbs pie Lībanus tevi apklās, un tā zvēru izskaušana, ar ko tu tos iztraucējis, to cilvēku asiņu dēļ un tā varas darba dēļ pie zemes, pie pilsētām un pie visiem viņu iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Ko tad palīdzēs tēls, ka griezējs to izgriezis, un lieta bilde un melu mācītājs, un ka tēlotājs paļaujas uz savu tēlu un taisa mēmus dievekļus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Vai tam, kas uz koku saka: uzmosties! - un uz mēmo akmeni: celies! Vai tas varētu mācīt? Redzi, tas ir aplikts ar zeltu un sudrabu, bet dvašas iekš viņa nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Bet Tas Kungs ir savā svētā namā; ciet klusu viņa priekšā, visa pasaule!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Pravieša Habakuka lūgšana, pēc augstas dziesmas dziedama: Kungs, kad es dzirdēju Tavu slavu, tad es izbijos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Kungs, tas ir Tavs darbs, izdari to gadiem ritot, gadiem ritot dari to zināmu. Dusmībā piemini žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Dievs nāk no Tēmana un tas Svētais no Pārana kalniem. (Sela.). Viņa augstība apklāj debesis, un zeme ir pilna Viņa slavas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Un spožums atspīd kā (saules) gaisma un stari Viņam abējās pusēs, un tur Viņa spēcība slēpjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Viņa priekšā iet mēris, un sērga uz viņa pēdām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Viņš stāv un satrīcina zemi, Viņš skatās un biedina tautas, mūžīgie kalni šķīst, vecu vecie pakalni grimst; Viņš staigā mūžības ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Es redzēju Moru ļaužu teltis postā un Midijaniešu dzīvokļus drebam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Vai Tu par upēm esi apskaities, ak Kungs, vai Tev dusmas par ūdeņiem, vai Tev bardzība par jūru, ka Tu brauci ar Saviem zirgiem uz Saviem glābšanas ratiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Tavs stops izvilkts spīd, rīkste, vārdos zvērēta (Sela.). Zemi Tu skaldi upēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Kalni Tevi ierauga, un tiem paliek bail, ūdens plūdi plūst, dziļums kauc, un augsti paceļ savas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Saule un mēness paliek stāvot savā mājoklī, Tavām bultām šaujoties un spīdot, Taviem šķēpiem spīdot un zibot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Dusmībā Tu samini zemi, bardzībā Tu sadragā tautas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Tu izej, glābt Savus ļaudis, glābt Savu svaidīto, Tu satrieci bezdievīgā nama galvu, atsegdams pamatu līdz pat kaklam. (Sela.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Ar viņa paša šķēpiem Tu satrieci viņa karavīru galvu, kas kā vētra nāk, mani izkaisīt, kam prieks, nabagu aprīt slepenībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Tu jāji ar saviem zirgiem pa jūru, pa varenu ūdeņu plūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Kad es to dzirdēju, tad manas iekšas trīcēja, no tās balss drebēja manas lūpas; puveši nāk manos kaulos, es trīcu savā vietā, ka man klusu jāgaida tā bēdu diena, kad celsies pret tiem ļaudīm, kas tos spaidīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Ja vīģes koks nezaļos, un augļu nebūs vīna kokam; eļļas koka augums nepiepilda cerības, un tīrumi nenes barību, avis izzudušas no ganībām un lopa nav laidaros.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Bet tomēr es priecāšos iekš Tā Kunga, es līksmošos iekš Dieva, sava Pestītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Tas Kungs Dievs ir mans stiprums, viņš dara man kājas kā stirnām un mani vedīs pa maniem kalniem. - Dziedātāju vadonim uz manām koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Tā Kunga vārds, kas notika Josijas, Amona dēla, Jūda ķēniņa, dienās uz Cefaniju, Kuzus dēlu; tas bija Ģedalijas, tas Amarijas, tas Hizkijas dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Rautin Es aizraušu visu no zemes virsas, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Es aizraušu cilvēkus un lopus, Es aizraušu putnus apakš debess un zivis jūrā un apgrēcības līdz ar bezdievīgiem, un Es izdeldēšu cilvēkus no zemes virsas, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Un Es izstiepšu savu roku pret Jūdu un pret visiem Jeruzālemes iedzīvotājiem, un izdeldēšu no šās vietas, kas atlicies no Baāla, un elka kalpu vārdu līdz ar tiem priesteriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Līdz ar tiem, kas pielūdz debess spēku uz jumtiem, un kas pielūdz un zvērē pie Tā Kunga un arī zvērē pie sava ķēniņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Un kas atkāpjas no Tā Kunga, un kas nemeklē To Kungu un pēc viņa nevaicā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Ciet klusu priekš Tā Kunga Dieva, jo Tā Kunga diena ir tuvu, jo Tas Kungs ir sataisījis upuri, viņš ir svētījis savus viesus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Un Tā Kunga upura dienā Es piemeklēšu virsniekus un ķēniņu bērnus un visus, kas ģērbjās ārzemes drēbēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Un tai dienā Es piemeklēšu visus, kas lec pār slieksni un kas sava kunga namu pilda ar laupījumu un viltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Un tai dienā, saka Tas Kungs, celsies brēkšanas balss no Zivju vārtiem un kaukšana no otra gala un lielas vaimanas no pakalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Kauciet, ielejas iedzīvotāji; jo visi tirgotāji izdeldēti, visi naudas krājēji nomaitāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Un tanī laikā Es Jeruzālemi izmeklēšu ar uguni un piemeklēšu tos vīrus, kas sēž uz savām mielēm, kas saka savās sirdīs: Tas Kungs nedara ne laba, ne ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Tāpēc viņu manta paliks par laupījumu un viņu nami par postažām. Tie gan uztaisa namus, bet tur nedzīvos, tie dēsta vīna dārzus, bet to vīnu nedzers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Tā Kunga lielā diena ir tuvu un ļoti steidzās. Klau, Tā Kunga diena! Briesmīgi brēc paši varenie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Šī diena būs bardzības diena, bēdu un bailības diena, vētras un posta diena, melna un tumša diena, apmākusies un miglaina diena,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Bazūnes un kara trokšņa diena pret visām stiprām pilsētām un augstām pilīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Un Es izbiedēšu cilvēkus, ka tie iet kā akli; jo tie grēkojuši pret To Kungu, un viņu asinis taps izgāztas kā pīšļi, un viņu miesas kā mēsli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ne viņu sudrabs, ne viņu zelts tos neizglābs Tā Kunga bardzības dienā, bet Viņa karstuma ugunī visa zeme taps aprīta; jo ātru galu Viņš darīs visiem zemes iedzīvotājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Pārbaudaties paši un izmeklējaties, jūs bezkaunīgie ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Pirms spriedums nenotiek, - kā pelavas skrien diena, - pirms Tā Kunga bardzības karstums jums neuziet, pirms Tā Kunga dusmības diena jums neuznāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Meklējiet To Kungu, visi bēdu ļaudis virs zemes, kas dariet viņa tiesu, meklējiet taisnību, meklējiet pazemību! Vai jūs, kas zin, netapsiet izglābti Tā Kunga bardzības dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Jo Gaca taps atstāta un Askalona par posta vietu, Ašdoda dienas vidū taps aizdzīta, un Ekrone taps izsakņota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Ak vai, tiem, kas dzīvo gar jūru, Krietu tautai. Tā Kunga vārds nāks pār jums, Kanaāna, Fīlistu zeme! Un Es tevi izdeldēšu, ka tur vairs nebūs iedzīvotāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Un jūrmalas tiesa paliks par atmatām, ganu alām un avju laidariem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Un tā būs daļa Jūda nama atlikušiem, kur ganīt. Vakaros tie apgulsies Askalonas namos, kad Tas Kungs, viņu Dievs, tos piemeklēs, un būs novērsis viņu cietumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Moaba mēdīšanu Es esmu dzirdējis, un Amona bērnu lamāšanu, ar ko tie mēdījuši Manus ļaudis un lielījušies pret viņu robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Tādēļ tik tiešām ka Es dzīvoju, saka Tas Kungs Cebaot, Israēla Dievs: Moabs būs kā Sodoma un Amona bērni kā Gomora, nātru krūms un sāls bedre un posta vieta mūžīgi. Manu ļaužu atlikušie tos aplaupīs, un Manas tautas atlikums tos iemantos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Tas viņiem notiks par viņu lepnību, jo tie ir mēdījuši un lielījušies pret Tā Kunga Cebaot ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Tas Kungs būs briesmīgs pret viņiem, jo Viņš izdeldēs visus pasaules dievus, un ikviens no savas vietas Viņu pielūgs, visas pagānu salas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Arī jūs, Moru(Etiopiešu) ļaudis, tapsiet nokauti caur Manu zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Un Viņš izstieps Savu roku pret ziemeli un izdeldēs Asuru, un darīs Ninivi par postažu, tik sausu kā tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Un viņas vidū ganāmi pulki apgulsies, visādi zvēri, dumpis un ezis mājos viņu granātābolu dārzos, viņu balsis dziedās logos, gruveši būs uz sliekšņiem, jo ciedra galdi taps noplēsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Šī ir tā pilsēta, kas tā priecājās, kas droši dzīvo, kas savā sirdī saka: es, un cita neviena. Kā tā ir palikusi par postažu, zvēriem par migu! Visi, kas tai iet garām, svilpo un met ar roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Vai tai stūrgalvīgai un apgānītai un varmācīgai pilsētai!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Tā neklausa, ko saka, tā nepieņem mācību un nepaļaujas uz To Kungu, nenāk pie sava Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Viņas lielkungi viņas vidū ir lauvas, kas rūc, viņas soģi ir kā vilki vakarā, kas nekā neatlicina līdz rītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Viņas pravieši ir lielmutes, viltnieki, viņas priesteri sagāna svētumu un lauž bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Tas Kungs ir taisns viņu vidū, Viņš nedara netaisnību, ik rītu Viņš nes gaismā Savu tiesu bez kavēšanās, tomēr nelieši neprot kauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Tautas Es esmu izdeldējis, viņu pilis ir postītas, viņu ielas Es esmu darījis tukšas, ka neviens tur nestaigā, viņu pilsētas ir postītas, palikušas bez cilvēka un bez iedzīvotāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Es sacīju: kaut tu Mani bītos un pieņemtu mācību, tad viņu mājas vieta netaptu izdeldēta pēc visa, ko Es par tiem esmu nospriedis. Bet tie ir ļaunu darījuši, ko vien darīdami');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Tādēļ jums būs Mani gaidīt, saka Tas Kungs, tai dienā, kad Es celšos uz laupījumu, jo Mana tiesa ir sapulcināt tautas, sakrāt valstis un pār tām izgāzt Savu bardzību un visu Savu dusmības karstumu, jo visa pasaule taps aprīta Mana karstuma ugunī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Tad Es tiem ļaudīm došu šķīstas lūpas, ka visiem būs piesaukt Tā Kunga vārdu un Viņam kalpot vienprātībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'No viņpus Moru upēm Mani pielūdzēji Man nesīs upurus, Manu izkaisīto ļaužu draudze.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Tai dienā tu netapsi kaunā visu savu darbu dēļ, ar ko tu pret Mani noziegusies. Jo tad Es no tava vidus atņemšu tavus lepnos lielītājus, un tu vairs nebūsi lepna Manā svētā kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Un tavā vidū Es atlicināšu bēdu ļaudis un pazemīgos, tie paļausies uz Tā Kunga vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Israēla atlikušie nedarīs netaisnību un nerunās melus, un viņu mutē neatradīs viltus mēli, bet tie ganīsies un apgulsies, un neviens tos netraucēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Dzied priecīgi, Ciānas meita! Gavilē, Israēl! Priecājies un līksmojies no visas sirds, Jeruzālemes meita!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Tas Kungs ir atņēmis tavu sodību, Viņš tavu ienaidnieku ir aizmēzis projām. Tas Kungs, Israēla ķēniņš, ir tavā vidū, ļaunuma tu vairs neredzēsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Tai dienā sacīs uz Jeruzālemi: nebīsties, Ciāna! Lai tavas rokas nenogurst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Tas Kungs, tavs Dievs, ir tavā vidū, stiprs Pestītājs, Viņš priecāsies par tevi ar līksmību, Viņš cietīs klusu savā mīlestībā, Viņš priecāsies par tevi ar gavilēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Es sapulcināšu tos, kas bija noskumuši svētku sapulces dēļ; tie tev pieder; negods tiem uzkrauts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Redzi, tanī laikā Es tā darīšu visiem taviem spaidītājiem, un Es pasargāšu klibo un sapulcināšu izdzīto, un tos iecelšu par teikšanu un par slavu ikvienā zemē, kur tie bija kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Tanī laikā Es jūs atvedīšu, un to brīdi Es jūs sapulcināšu. Jo Es jūs iecelšu par slavu un par teikšanu pie visām pasaules tautām, kad Es jūsu cietumu novērsīšu priekš jūsu acīm, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Ķēniņa Dārija otrā gadā, sestā mēnesi, pirmā mēneša dienā, Tā Kunga vārds notika caur pravieti Hagaju uz Zerubabeli Šealtiēļa dēlu, Jūda valdnieku, un uz Jozua, Jocadaka dēlu, augsto priesteri, un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Tā runā Tas Kungs Cebaot un saka: šie ļaudis runā: laiks vēl nav nācis, uzcelt Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Un Tā Kunga vārds notika caur pravieti Hagaju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Vai tad jums ir laiks, dzīvot glītos namos un šim namam būs stāvēt postā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nu tad tā saka Tas Kungs Cebaot: ņemat vērā savus ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Jūs sējat daudz un pļaujat maz, jūs ēdat, bet nepaēdat, jūs dzerat bet nepadzerat, jūs ģērbjaties, bet jums nepaliek silti, un algādzis pelna algu cauram makam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Tā saka Tas Kungs Cebaot: liekat vērā savus ceļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Ejat augšā kalnos un vediet kokus un uztaisiet šo namu; pie tā Man būs labs prāts, un Es tapšu pagodināts, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Jūs gan gaidāt uz daudz, bet redzi, jūs dabūjat maz, un jebšu jūs to esat mājās pārnesuši, taču Es to izputināju. Kāpēc tā? saka Tas Kungs Cebaot. Mana nama labad, kas stāv postā, kamēr ikviens skrien sava nama labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Tādēļ debess jums aiztur rasu, un zeme aiztur savus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Un sausumu Es saucu(sūtu) pār zemi un pār kalniem un pār labību un pār vīnu un pār eļļu un pār visu, kas izaug no zemes, un pār cilvēkiem un pār lopiem un pār ikvienu rokas darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Tad Zerubabels, Šealtiēļa dēls, un Jozuas, Jocadaka dēls, augstais priesteris, un visi atlikušie ļaudis klausīja Tā Kunga, sava Dieva, balsij un pravieša Hagaja vārdiem it(tieši) kā Tas Kungs, viņu Dievs, to bija sūtījis, un tie ļaudis bijās no Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Tad sacīja Hagaja, Tā Kunga vēstnesis, kam Tā Kunga vēsts bija uz tiem ļaudīm: Es esmu ar jums, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Un Tas Kungs pamodināja Zerubabela, Šealtiēļa dēla, Jūdas ķēniņa garu un Jozuas, Jocadaka dēla, augstā priestera garu un visu atlikušo ļaužu garu, ka tie gāja un darīja darbu pie Tā Kunga Cebaot, sava Dieva, nama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Sestā mēneša divdesmit ceturtā dienā ķēniņa Dārija otrā gadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Septītā mēneša divdesmit pirmā dienā notika Tā Kunga vārds caur pravieti Hagaju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Runā jel uz Zerubabeli, Šealtiēļa dēlu, Jūda valdnieku, un uz Jozua, Jocadaka dēlu, augsto priesteri, un uz tiem atlikušiem ļaudīm un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kurš ir jūsu starpā atlicis, kas šo namu redzējis viņa pirmā godībā un to tagad redz? Vai šis(nams) pret viņu nav tā kā nekas jūsu acīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Tomēr nu, Zerubabel, esi drošs! saka Tas Kungs, un Jozua, Jocadaka dēls, augstais priesteri, esi drošs, un esiet droši, visi šīs zemes ļaudis! saka Tas Kungs, un strādājiet, jo Es esmu ar jums, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Tas vārds, caur ko Es ar jums derību cēlis, kad jūs izgājāt no Ēģiptes zemes, un Mans gars paliek jūsu vidū. Nebīstaties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Jo tā saka Tas Kungs Cebaot: vēl mazs brīdis, tad Es kustināšu debesis un zemi, jūru un sausumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Un visus pagānus Es kustināšu, un tad nāks visu tautu prieks. Un Es piepildīšu šo namu ar godību, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Man pieder sudrabs un Man pieder zelts, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Šā pēdīgā nama godība būs lielāka nekā tā pirmā, saka Tas Kungs Cebaot. Un šai vietai Es došu mieru, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Divdesmit ceturtā dienā, devītā mēnesī, Dārija otrā gadā, Tā Kunga vārds notika caur pravieti Hagaju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Tā saka Tas Kungs Cebaot: vaicā jel priesteriem par bauslību un saki:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Redzi, kad kas svētu gaļu nestu savas drēbes stūrī, un ar savu stūri aizskartu maizi vai pavalgu vai vīnu vai eļļu vai kādu citu barību, vai tā būtu svētīta? Tad tie priesteri atbildēja un sacīja: Nebūtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Tad Hagaja sacīja: ja kāds, nešķīsts būdams no miroņa, visu šo aizskar, vai tas paliktu nešķīsts? Un priesteri atbildēja un sacīja: tas paliktu nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Tad Hagaja atbildēja un sacīja: tādi ir šie ļaudis, un tāda ir šī tauta Manā priekšā, saka Tas Kungs, un tāds viss viņu roku darbs, un ko tie tur upurē, tas ir nešķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Un nu ņemiet vērā savā sirdī, kas bijis no šās dienas atpakaļ un vēl senāki, pirms akmens tapa likts uz akmeni pie Tā Kunga nama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Pirms tas notika, kad kāds gāja pie labības kopas no divdesmit pūriem, tad tur bija tikai desmit, kad viņš gāja pie vīna spaida un gribēja smelt piecdesmit mērus, tad bija tikai divdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Es jūs situ ar bulu, rūsu un krusu, visu jūsu roku darbu, un jūs neatgriežaties pie manis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Ņemiet jel vērā savā sirdi, kas būs no šās dienas un uz priekšu, no devītā mēneša divdesmit ceturtās dienas, no tās dienas, kad pamats ir likts pie Tā Kunga nama, ņemiet to vērā savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Vai vēl ir sēkla klētī? Un vīna koks un vīģes koks un granātkoks un eļļas koks, tie nav nesuši(augļus). No šās dienas es svētīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Un Tā Kunga vārds otrreiz notika uz Hagaju divdesmit ceturtā mēneša dienā sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Runā uz Zerubabeli, Jūda valdnieku, un saki: Es kustināšu debesis un zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Un Es apgāzīšu ķēniņu goda krēslus un izdeldēšu stiprās pagānu valstis un apgāzīšu ratus un braucējus, un kritīs zirgi un jātnieki, cits caur cita zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Tai dienā, saka Tas Kungs Cebaot, Es tevi ņemšu, Zerubabel, Šealtiēļa dēls, Mans kalps, saka Tas Kungs, un tevi turēšu kā spiežamu gredzenu, jo tevi Es esmu izredzējis, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Astotā mēnesī, Dārija otrā gadā, Tā Kunga vārds notika uz pravieti Zahariju, Bereķijas, Idus dēla, dēlu, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Tas Kungs dusmodamies dusmojies par jūsu tēviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Tāpēc saki uz tiem: tā saka Tas Kungs Cebaot: atgriežaties atkal pie Manis, saka Tas Kungs Cebaot, tad Es atkal griezīšos pie jums, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Neesiet kā jūsu tēvi, uz ko tie pirmie pravieši sauca un sacīja: tā saka Tas Kungs Cebaot: atgriežaties jel no saviem ļauniem ceļiem un saviem ļauniem darbiem! Bet tie neklausīja un Mani neņēma vērā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Jūsu tēvi, kur tie ir? Un tie pravieši, vai tie var mūžīgi dzīvot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Bet Mani vārdi un Mani likumi, ko Es biju pavēlējis Saviem kalpiem, tiem praviešiem, vai tie nav nākuši pār jūsu tēviem? Tā ka tie atgriezdamies sacīja: tā kā Tas Kungs Cebaot bija nodomājis mums darīt pēc mūsu ceļiem un pēc mūsu darbiem, tā Viņš mums ir darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Divdesmit ceturtā dienā, vienpadsmitā mēnesī, tas bija Zebat mēnesis, Dārija otrā gadā, Tā Kunga vārds notika uz pravieti Zahariju, Bereķijas, Idus dēla, dēlu, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Es redzēju naktī un raugi, vīrs jāja uz sarkana zirga, un tas stāvēja starp mirtēm ielejā, un aiz viņa bija sarkani, bēri un balti zirgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Tad es sacīju: mans kungs, kas tie tādi? Un tas eņģelis, kas ar mani runāja, sacīja uz mani: es tev rādīšu, kas šie tādi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Tad tas vīrs, kas stāvēja starp tām mirtēm, atbildēja un sacīja: šie ir tie, ko Tas Kungs izsūtījis, pārstaigāt zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Un tie atbildēja Tā Kunga eņģelim, kas stāvēja starp tām mirtēm, un sacīja: mēs zemi esam pārstaigājuši, un redzi, visa zeme ir klusa un mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Tad Tā Kunga eņģelis atbildēja un sacīja: Kungs Cebaot! Cik ilgi Tu neapžēlosies par Jeruzālemi un par Jūda pilsētām, par kurām Tu esi dusmojies šos septiņdesmit gadus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Un Tas Kungs tam eņģelim, kas ar mani runāja, atbildēja labus vārdus, prieka vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Un tas eņģelis, kas ar mani runāja, sacīja uz mani: sludini un saki: tā saka Tas Kungs Cebaot: Es esmu iekarsis par Jeruzālemi un par Ciānu ar lielu karstumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Un ar lielām dusmām Es dusmojos par tiem drošiem pagāniem, jo Es biju maķenīt dusmīgs, bet tie palīdzēja uz ļaunumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Tāpēc tā saka Tas Kungs: Es atgriezīšos uz Jeruzālemi ar apžēlošanu, Mans nams tur taps uztaisīts, saka Tas Kungs Cebaot, un mēra auklu vilks pār Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Sludini vēl un saki: tā saka Tas Kungs Cebaot: Manām pilsētām atkal labi klāsies, jo Tas Kungs atkal iepriecinās Ciānu un atkal izredzēs Jeruzālemi. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Un es pacēlu savas acis un skatījos, un redzi, tur bija četri ragi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Un es sacīju uz to eņģeli, kas ar mani runāja: kas tie tādi? Un viņš sacīja uz mani: šie ir tie ragi, kas izkaisījuši Jūdu un Israēli un Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Un Tas Kungs man rādīja četrus kalējus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Tad es sacīju: ko tie nāk darīt? Un viņš runāja un sacīja: še ir tie ragi, kas Jūdu izkaisījuši, tā ka neviens savu galvu nepaceļ, bet šie ir nākuši tos biedināt un nosist zemē ragus tiem pagāniem, kas bija ragu pacēluši pret Jūda zemi, to izkaisīt. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Es atkal pacēlu savas acis un skatījos, un redzi, tur bija vīrs, un viņa rokā mēra aukla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Un es sacīju: kurp iedams? Un viņš sacīja uz mani: Jeruzālemi mērot un lūkot, kāds viņas platums un kāds viņas garums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Un redzi, tas eņģelis, kas ar mani runāja, izgāja ārā. Un viens cits eņģelis tam nāca pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Un viņš uz to sacīja: teci, runā uz šo jaunekli un saki: Jeruzālemē dzīvos bez mūriem aiz liela cilvēku un lopu pulka viņas vidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Un Es, saka Tas Kungs, viņai būšu par degošu mūri visapkārt, un Es būšu par godību viņas vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Vai, vai, bēdziet jel no ziemeļa zemes! saka Tas Kungs; jo Es jūs izpletīšu uz tiem četriem debess vējiem, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Vai, Ciāna, glābies, tu, kas dzīvo pie Bābeles meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Jo tā saka Tas Kungs Cebaot: pēc godības Viņš mani sūtījis pie tiem pagāniem, kas jūs aplaupījuši; jo kas jūs aizskar, tas aizskar Viņa acs raugu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Jo redzi, Es cilāšu Savu roku pār tiem; tie būs par laupījumu saviem kalpiem; tā jūs samanīsiet, ka Tas Kungs Cebaot mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Gavilē un priecājies, Ciānas meita, jo redzi, Es nāku un dzīvošu tavā vidū, saka Tas Kungs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Un daudz pagāni tai dienā piebiedrosies Tam Kungam, un tie Man būs par ļaudīm, un Es dzīvošu tavā vidū, un tu samanīsi, ka Tas Kungs Cebaot mani pie tevis sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Tad Tas Kungs iemantos Jūdu par Savu tiesu tai svētā zemē un izredzēs atkal Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Ciet klusu, visa miesa, Tā Kunga priekšā! Jo Viņš ir uzcēlies no Savas svētās vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Un viņš man rādīja augsto priesteri Jozua, stāvam Tā Kunga eņģeļa priekšā. Un sātans stāvēja viņam pa labo roku, viņu apsūdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Bet Tas Kungs sacīja uz sātanu: lai Tas Kungs tevi rāj, sātan: lai tevi rāj Tas Kungs, kas Jeruzālemi izredzējis! Vai šī nav pagale, no uguns izrauta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Un Jozuas bija apģērbts netīrās drēbēs, kad viņš stāvēja tā eņģeļa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Tad viņš (tas eņģelis) atbildēja un runāja uz tiem, kas viņa priekšā stāvēja, un sacīja: atņemiet tam tās netīrās drēbes. Un viņš uz to sacīja: redzi, tavu noziegumu es tev esmu atņēmis, un tevi apģērbšu ar svētku drēbēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Un es sacīju: lai liek tīru cepuri viņam galvā. Un tie tam lika tīru cepuri galvā un tam apvilka drēbes, un Tā Kunga eņģelis stāvēja tur klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Tad Tā Kunga eņģelis Jozuam apliecināja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Tā saka Tas Kungs Cebaot: ja tu staigāsi Manos ceļos un sargāsi Manu likumu, tad tev arī Manu namu būs tiesāt un arī Manus pagalmus sargāt, un Es tev došu pieiešanu to starpā, kas te stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Klausies nu jel, Jozua, augstais priesteri, tu un tavi draugi, kas tavā priekšā, jo tie ir par brīnuma zīmi. Jo redzi, Es likšu nākt Savam kalpam Cemak (Atvasei).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Jo redzi to akmeni, ko Es Jozuas priekšā esmu nolicis! Uz to vienu akmeni (skatās) septiņas acis. Redzi, Es ierakstīšu viņa rakstu, saka Tas Kungs Cebaot, un atņemšu šās zemes noziegumu vienā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Tai dienā, saka Tas Kungs Cebaot, jūs aicināsiet cits citu apakš vīna koka un apakš vīģes koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Un tas eņģelis, kas ar mani runāja, atkal nāca un mani modināja, kā vīru, kas no sava miega top uzmodināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Un viņš uz mani sacīja: ko tu redzi? Un es sacīju: es redzu, un raugi, tur ir lukturis no tīra zelta ar eļļas kausu virsgalā, un viņa septiņi eļļas lukturīši uz viņa, un tiem eļļas lukturīšiem ir pa septiņiem zariem (caurulītēm savienotas) viņa virsgalā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Un tur klāt divi eļļas koki, viens tam eļļas kausam pa labo un otrs viņam pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Un es atbildēju un runāju uz to eņģeli, kas ar mani runāja, un sacīju: mans kungs, kas tie ir?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Un tas eņģelis, kas ar mani runāja, atbildēja un sacīja uz mani: vai tu nezini, kas tie ir? Un es sacīju: nē, mans kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Tad viņš atbildēja un runāja uz mani un sacīja: šis ir Tā Kunga vārds uz Zerubabeli, sacīdams: ne caur spēku, nedz caur varu, bet caur manu Garu (tas notiks), saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Kas tu tāds esi, tu lielais kalns? Priekš Zerubabela tu tapsi par klajumu. Jo viņš uzliks to gala akmeni, ka tur visā spēkā sauks: žēlastība, žēlastība viņam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Un Tā Kunga vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Zerubabela rokas šo namu sākušas, viņa rokas to arī pabeigs, ka jūs saprotat, ka Tas Kungs Cebaot mani pie jums sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Jo kas nicina sīka iesākuma dienu? Jo priecīgi ierauga to loti Zerubabela rokā šie septiņi, kas ir Tā Kunga acis, kas iet pa visu pasauli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Tad es atbildēju un uz viņu sacīju: kas tie tādi divi eļļas koki pa labo roku tam lukturim un pa kreiso roku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Un es atkal atbildēju un uz viņu sacīju: kas tie tādi divi eļļas koka zari, kas sānis tiem diviem zelta kausiem, kas zeltu izlej');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Un viņš uz mani runāja un sacīja: vai tu nezini, kas tie ir? Un es sacīju: nē, mans kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Un viņš sacīja: šie ir tie divi svaidītie, kas stāv priekš visas pasaules valdītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Un es savas acis atkal pacēlu un skatījos, un redzi, satīta grāmata skrēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Un viņš uz mani sacīja: Ko tu redzi? Un es sacīju: es redzu satītu grāmatu skrienam, tai garums ir divdesmit olektis un platums tai ir desmit olektis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Un viņš uz mani sacīja: šis ir tas lāsts, kas iziet pa visas zemes virsu, jo ikkatrs, kas zog, pēc tā taps izdeldēts no šejienes, un ikkatrs, kas nepareizi zvēr, pēc tā taps izdeldēts no šejienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Es to izlaižu, saka Tas Kungs Cebaot, un tam (lāstam) būs iet zagļa namā, un tā namā, kas pie Mana Vārda nepatiesi zvērē, un tas piemājos viņa namā un to nobeigs ar viņa baļķiem un akmeņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Un tas eņģelis, kas ar mani runāja, iznāca un uz mani sacīja: pacel jel savas acis un redzi, kas tas ir, kas tur iziet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Un es sacīju: kas tas ir? Tad viņš sacīja: tā ir ēfa(labības mērs), kas iziet. Atkal viņš sacīja: tā viņi izskatās visā zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Un redzi, apaļš svina vāks pacēlās, un tur bija sieva, tā sēdēja tai ēfā iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Un viņš sacīja: šī ir tā bezdievība; un viņš to iemeta tai ēfā iekšā, un meta to svina vāku uz to virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Un es pacēlu savas acis un skatījos, un redzi, divas sievas iznāca, un vējš bija viņu spārnos, un viņu spārni bija kā stārķu spārni, un tās nesa to ēfu vidū starp zemi un debesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Tad es sacīju uz to eņģeli, kas ar mani runāja: kurp tie nes šo ēfu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Un viņš uz mani sacīja: tai uztaisīt namu Sineāra zemē, un to tur nolaist un nolikt zemē savā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Un es atkal pacēlu savas acis un skatījos, un redzi, tur četri rati iznāca starp diviem kalniem, un tie kalni bija vara kalni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Priekš tiem pirmiem ratiem bija sarkani zirgi, un priekš tiem otriem ratiem melni zirgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'Un priekš tiem trešiem ratiem balti zirgi, un priekš tiem ceturtiem ratiem bija raibi stipri zirgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Un es atbildēju un sacīju uz to eņģeli, kas ar mani runāja: kas tie tādi, mans kungs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Tad tas eņģelis atbildēja un sacīja: šie ir tie četri debess vēji, kas iznāk, kad tie bija stāvējuši priekš visas pasaules valdnieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Priekš kuriem ratiem tie melnie zirgi ir, tie iziet uz ziemeļa zemi, un tie baltie šiem iziet pakaļ. Un tie raibie iziet uz dienvidu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Un tie stiprie zirgi izgāja un meklēja pārstaigāt zemi. Jo viņš bija sacījis: ejat, pārstaigājiet zemi, un tie pārstaigāja zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Un viņš mani aicināja un uz mani runāja un sacīja: redzi, šie, kas ir izgājuši uz ziemeļa zemi, Manu Garu ir klusinājuši ziemeļa zemē. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Un Tā Kunga vārds notika uz mani sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Ņem no tiem aizvestiem, no Ķeldajus, no Tobias un no Jedajas, - un ej tai dienā un ej Josijas, Cefanijas dēla, namā, kur tie no Bābeles pārnākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Un ņem sudrabu un zeltu un taisi kroni un liec to galvā augstam priesterim Jozuam, Jocadaka dēlam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Un runā uz viņu un saki: tā saka Tas Kungs Cebaot: redzi, vīrs, kam vārds ir Cemaks (Atvase), izplauks no savas vietas, un tas uztaisīs Tā Kunga namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Tiešām, viņš uztaisīs Tā Kunga namu, un viņš nesīs to godības glītumu un sēdēs un valdīs uz sava goda krēsla un būs priesteris uz sava goda krēsla, un miera padoms būs starp abiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Un tas kronis būs Tā Kunga namā par piemiņu Ķelemam un Tobijam un Jedajam un Cefanijas dēla laipnībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Un tie, kas ir tālu, atnāks un strādās pie Tā Kunga nama, un jūs manīsiet, ka Tas Kungs Cebaot mani pie jums sūtījis. Tas notiks, kad jūs klausīt klausīsiet Tā Kunga, sava Dieva, balsij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Un notikās ķēniņa Dārija ceturtā gadā, tad Tā Kunga vārds notika uz Zahariju devītā, tas ir Ķislev mēneša, ceturtā dienā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Tad Bētele sūtīja Sareceru un ReģemMeleķu ar saviem vīriem, To Kungu pielūgt');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Un sacīt uz tiem priesteriem Tā Kunga Cebaot namā un uz tiem praviešiem: Vai man jāraud piektā mēnesī un jāgavē, kā es tik daudz gadus esmu darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Tad Tā Kunga Cebaot vārds notika uz mani un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Runā uz visiem zemes ļaudīm un uz priesteriem un saki: kad jūs gavējāt un žēlojaties piektā un septītā mēnesī šos septiņdesmit gadus, vai jūs tādu(patiesu) gavēšanu esiet Man gavējuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Bet kad jūs ēdat un kad jūs dzerat, vai jūs tie neesat, kas ēd un dzer?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Vai šie nav tie vārdi, ko Tas Kungs izsauca caur tiem pirmiem praviešiem, kad Jeruzāleme dzīvoja mierā, un viņas pilsētas visapkārt, un dienvidu puse un ieleja bija apdzīvota?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Atkal Tā Kunga vārds notika uz Zahariju sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Tā runā Tas Kungs Cebaot un saka: nesiet patiesīgu tiesu un parādiet ikviens savam brālim žēlastību un apžēlošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Un neapbēdiniet ne atraitni, nedz bāriņu, nedz svešinieku, nedz nabagu, un nedomājiet ļauna cits pret citu savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Bet tie negribēja klausīt un palika stūrgalvīgi un apcietināja savas ausis, nepaklausīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Un savu sirdi tie darīja par dimantu, ka neklausītu bauslību un tos vārdus, ko Tas Kungs Cebaot sūtīja ar Savu Garu caur tiem pirmiem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Tādēļ tāda liela dusmība nākusi no Tā Kunga Cebaot. Tāpēc noticis, tā kā Viņš bija saucis, un tie nebija klausījuši; tāpat tie arīdzan sauca, bet Es neklausīju, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Tā Es tos esmu izputinājis starp visiem pagāniem, ko tie nepazina, un tā zeme aiz tiem tapa postīta, tā ka neviens tur nestaigāja, un tā viņi to jauko zemi darīja par postažu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Un Tā Kunga Cebaot vārds notika un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Tā saka Tas Kungs Cebaot: Es biju iekarsis par Ciānu ar lielu karstumu, pat ar lielu bardzību Es par to biju iekarsis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Tā saka Tas Kungs: Es griežos atpakaļ uz Ciānu un dzīvošu Jeruzālemes vidū, un Jeruzālemi sauks par patiesības pilsētu un Tā Kunga Cebaot kalnu par svētu kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Tā saka Tas Kungs Cebaot: tur sēdēs vēl sirmi vīri un sirmas sievas Jeruzālemes ielās; ikvienam savs spieķis būs savā rokā aiz liela vecuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Un pilsētas ielas būs pilnas ar puisēniem un meitenēm, kas pa viņas ielām spēlējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Tā saka Tas Kungs Cebaot: Kad tas būs brīnums šo atlikušo ļaužu acīs tanīs dienās, vai tas arī būs brīnums Manās acīs? saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Tā saka Tas Kungs Cebaot: Redzi, Es atpestīšu Savus ļaudis no austruma zemes un no saules rieta zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Un Es tos atvedīšu, ka tiem būs dzīvot Jeruzālemes vidū. Un tie Man būs par ļaudīm, un Es tiem būšu par Dievu patiesībā un taisnībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Tā saka Tas Kungs Cebaot: Lai jūsu rokas paliek stipras, kas šos vārdus esat dzirdējuši šinīs dienās no praviešu mutes, kas bija tai dienā, kad sāka celt Tā Kunga Cebaot dzīvokli, taisīt Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Jo priekš šīm dienām cilvēkiem alga netika un lopiem algas nebija, un tiem, kas izgāja un iegāja, nebija miera no ienaidnieka, jo Es palaidu visus cilvēkus citu pret citu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Bet nu Es pret šiem atlikušiem ļaudīm neturēšos kā viņā laika, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Bet sēkla labi izdosies, vīna koks dos savas ogas, un zeme izdos savus augļus, un debesis dos savu rasu, un šiem atlikušiem ļaudīm Es došu visu šo iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Un notiks, tā kā jūs, Jūda nams un Israēla nams, esiet bijuši lāsts tautu vidū, tāpat Es jūs izglābšu, ka būsiet svētība; nebīstaties, un lai jūsu rokas paliek stipras.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Jo tā saka Tas Kungs Cebaot: tā kā Es esmu domājis, jums ļaunu darīt, kad jūsu tēvi Mani apkaitināja, saka Tas Kungs Cebaot, un tas Man nebija žēl,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Tāpat Es atkal šinīs dienās domāju labu darīt Jeruzālemei un Jūda namam, - nebīstaties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Šās ir tās lietas, ko jums būs darīt: runājiet patiesi ikviens ar savu tuvāku, tiesājiet taisni, un nesiet tiesu, lai miers valda jūsu vārtos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Un nedomājiet ļaunu cits pret citu savā sirdī un lai jums ir nemīlama nepatiesa zvērēšana, jo visu šo es ienīstu, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Atkal Tā Kunga Cebaot vārds uz mani notika sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Tā saka Tas Kungs Cebaot: tā gavēšana ceturtā un piektā un septītā un desmitā mēnesī Jūda namam būs par prieku un par līksmību un par jaukiem svētkiem; bet mīļojiet patiesību un mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Tā saka Tas Kungs Cebaot: vēl nāks tautas un daudz pilsētu iedzīvotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Un vienas pilsētas iedzīvotāji ies pie otras iedzīvotājiem un sacīs: ejam pielūgt To Kungu un meklēt To Kungu Cebaot, - arī es iešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Tā nāks daudz ļaužu, un varenas tautas meklēs To Kungu Cebaot Jeruzālemē un pielūgs To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Tā saka Tas Kungs Cebaot: tanīs dienās notiks, ka desmit vīri no visādām pagānu valodām satvers viena Jūda vīra (drēbju) stūri un sacīs: mēs iesim jums līdz, jo mēs esam dzirdējuši, ka Dievs ir ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Tā Kunga vārda spriedums par Hadraha zemi, un kas apmetās Damaskū; jo Tas Kungs skatās uz cilvēkiem un uz visām Israēla ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Un uz Hamatu pie viņas robežām, uz Tiru un Sidonu, jo tur ir liela gudrība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Un Tirus sev ir uzcēlusi stipru pili un sakrājusi sudrabu kā pīšļus, un zeltu kā dubļus uz ielām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Redzi, Tas Kungs viņu uzvarēs un satrieks viņas spēku jūrā, un uguns viņu aprīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askalona to redzēs un bīsies, un arī Gaca, un drebēs, līdz ar Ekroni, tāpēc ka viņu cerība ir palikusi kaunā. Un Gacas ķēniņš ies bojā, un Askalonā nedzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Un Ašdodā dzīvos sveši, un Es izdeldēšu Fīlistu lepnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Un Es atņemšu viņu asinis no viņu mutes un viņu negantību no viņu zobiem. Tā tie arīdzan atliksies mūsu Dievam, un tie būs kā valdnieki iekš Jūda, un Ekronekā Jebusieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Un Es pats apmetīšos ap Savu namu pret karaspēku un pret sirotājiem, ka spaidītājs tur vairs nestaigās; jo nu Es to ar Savām acīm esmu redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Priecājies ļoti, Ciānas meita, un gavilē, Jeruzālemes meita! Redzi, tavs ķēniņš nāk pie tevis, taisns un Pestītājs Viņš ir, pazemīgs un jādams uz ēzeļa, uz ēzeļa mātes kumeļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Un Es izdeldēšu ratus no Efraīma un zirgus no Jeruzālemes, un kara stops taps izdeldēts. Un tautām Viņš mācīs mieru, un Viņa valdīšana būs no vienas jūras līdz otrai un no lielupes līdz pasaules galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Un arī tu, - tavas derības asiņu dēļ Es tavus cietumniekus izlaidīšu no bedres, kur ūdens nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Atgriežaties atpakaļ uz to stipro vietu, jūs cietumnieki, kam cerība. Šodien pat Es saku, ka Es tev divkārtīgi atmaksāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Jo Jūdu Es Sev esmu uzvilcis kā stopu un Efraīmu licis par bultu, un Es pamodināšu tavus bērnus, Ciāna, pret taviem bērniem, Grieķu zeme, un tevi darīšu kā varoņa zobenu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Un Tas Kungs parādīsies pār viņiem, un Viņa bultas izies kā zibens, un Tas Kungs Dievs bazūnēs ar bazūni un nāks kā aukas no dienvidiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Tas Kungs Cebaot tos pasargās, un tie rīs un samīs lingas akmeņus, un tie dzers un cels troksni tā kā no vīna, un taps pilni kā upuru kausi, kā altāra stūri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Un Tas Kungs, viņu Dievs, tos izpestīs tanī dienā kā Savu ļaužu ganāmo pulku, jo tie ir kroņa akmeņi, mirdzēdami Viņa zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Jo cik liels būs viņu labums? Un cik liels būs viņu daiļums? Labība jaunekļus izaudzinās un vīns jaunietes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Lūdziet lietu no Tā Kunga vēlajā lietus laikā! Tas Kungs rada zibeņus; Viņš tiem dos lietus papilnam ikkatrai zālei laukā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Jo dievekļi runā nelietību, un zīlnieki rauga viltību un runā melu sapņus un iepriecina ar niekiem. Tādēļ tie maldās kā avis, tie ir nospaidīti, jo tur nav gana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Pret tiem ganiem Mana bardzība iedegusies, un tos āžus Es piemeklēšu. Jo Tas Kungs Cebaot piemeklē Savu ganāmo pulku, Jūda namu, un to ieceļ Sev par goda zirgu karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'No viņa iznāks stūra akmens, nagla, kara stops un visi valdnieki līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Un tie būs kā varoņi, kas kaušanā samin ielas dubļus, un tie kausies, jo Tas Kungs būs ar viņiem, un tie liks kaunā zirgu jājējus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Un Es stiprināšu Jūda namu un atpestīšu Jāzepa namu, un Es tos atkal iestādīšu, jo Es par tiem esmu apžēlojies, un tie būs, tā kā Es tos nebūtu atmetis, jo Es esmu Tas Kungs, viņu Dievs, un tos paklausīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Un Efraīms būs kā varonis un viņa sirds priecāsies kā no vīna. Un viņa bērni to redzēdami līksmosies, viņu sirds priecāsies iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Un Es tos ataicināšu un sapulcēšu, jo Es tos gribu izpestīt, un tie vairosies, kā tie citkārt vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Un Es tos sēšu starp tautām, un tie Mani pieminēs tālās zemēs, un tie dzīvos ar saviem bērniem un atgriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Un Es tos atvedīšu no Ēģiptes zemes un tos sapulcināšu no Asīrijas un tos vedīšu uz Gileāda zemi un Tībanu, ka viņam nepietiks vietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Un viņš iet caur bēdu jūru un sit viļņus jūrā, un visi upes dziļumi izsīks; tad Asura lepnība taps nogāzta, un Ēģiptes scepteris zudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Un Es tos stiprināšu iekš Tā Kunga, un tie staigās Viņa vārdā, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Atdari savas durvis, Lībanus, lai uguns aprij tavus ciedru kokus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Kauciet, priedes, ka ciedru koki krituši un varenie postīti. Kauciet, Basanas ozoli, ka tas biezais mežs gāzies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Tur ir ganu kaukšanas balss, tāpēc ka viņu godība postīta; jaunu lauvu rūkšanas balss, tāpēc ka Jardānes greznība postīta. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Tā saka Tas Kungs, mans Dievs: gani šās kaujamās avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Jo tie, kam tās pieder, tās nokauj un to netur par noziegumu, un ikviens no viņu pārdevējiem saka: slavēts lai ir Tas Kungs, ka esmu bagāts tapis, un viņu gani tās netaupa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Tiešām, šās zemes iedzīvotājus Es vairs netaupīšu, saka Tas Kungs: bet redzi, Es cilvēkus nodošu ikvienu viņa tuvākā rokā un viņa ķēniņa rokā, ka tiem šo zemi būs sagrauzt, un Es tos negribu izpestīt no viņu rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Un es ganīju šās kaujamās avis, un tā arī tās nabaga avis, un es sev ņēmu divus zižļus, to vienu es nosaucu Laipnību, un to otru Saites, un ganīju tās avis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Un es izdeldēju trīs ganus vienā mēnesī; jo mana dvēsele tos bija apnikusi, un arī viņu dvēselei es biju riebīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Un es sacīju: es jūs vairs neganīšu; kas mirst, lai mirst, kas zūd, lai zūd, un kas atliek, tas lai aprij cits cita miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Un es ņēmu savu zizli, Laipnību, un to salauzu un iznīcināju savu derību, ko biju derējis ar visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Un tā tai dienā tapa iznīcināta. Tad tās nabaga avis, kas mani lika vērā, atzina, ka tas bija Tā Kunga vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Un es uz tiem sacīju: ja jums patīk, tad dodat man savu algu, bet ja ne, tad lai paliek. Un tie nosvēra manu algu, trīsdesmit sudraba gabalus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Un Tas Kungs uz mani sacīja: nomet to podniekam, to dārgo algu, cik dārgu tie Mani turējuši. Un es ņēmu tos trīsdesmit sudraba gabalus un tos nometu Tā Kunga namā podniekam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Tad es salauzu savu otru zizli, Saites, un iznīcināju brālību starp Jūdu un Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Un Tas Kungs uz mani sacīja: ņem atkal ģeķīgā(neapdomīgā) gana rīkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Jo redzi, Es celšu ganu zemē, kas neņem vērā bojā ejošo, nemeklē noklīdušo un nedziedina satriekto un neapkopj neveselo, bet kas ēd treknā gaļu un salauž viņu nagus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Vai tam nelieša ganam, kas atstāj ganāmo pulku! Zobens pār viņa elkoni un pār viņa labo aci! Viņa elkonis kaltin lai sakalst un viņa labā acs lai pavisam izdziest!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Tā Kunga vārda spriedums par Israēli. Tā saka Tas Kungs, kas debesis izpletis un zemi dibinājis un radījis cilvēka garu iekš viņa:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Redzi, Jeruzālemi Es darīšu par straipalējamo biķeri visām tautām visapkārt, un tas nāks arī pār Jūdu, kad Jeruzālemi apsēdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Un notiks tai dienā, Es Jeruzālemi darīšu par nastas akmeni visām tautām; visi, kas viņu grib uzcelt, tie ievainosies, un visas pasaules tautas pret viņu sapulcēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Tai dienā, saka Tas Kungs, Es visus zirgus sitīšu ar bailību un viņu jātniekus ar bezprātību, bet pār Jūda namu Es atvēršu savas acis un tautām sitīšu visus zirgus ar aklību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Tad Jūda virsnieki savā sirdī sacīs: stiprums man ir Jeruzālemes iedzīvotāji iekš Tā Kunga Cebaot, sava Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Tai dienā Es Jūda virsniekus celšu kā degošu ugunskuru malkā un kā degošu lāpu kūlīšos, un pa labo un kreiso pusi tie aprīs visas tautas visapkārt, un Jeruzāleme vēl paliks savā vietā Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Un Tas Kungs papriekš izpestīs Jūda dzīvokļus, lai Dāvida nama augstība un Jeruzālemes iedzīvotāju godība nelielās pret Jūdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Tai dienā Tas Kungs pasargās Jeruzālemes iedzīvotājus, un pats nespēcīgākais viņu starpā tai dienā būs kā Dāvids, un Dāvida nams būs kā Dievs, kā Tā Kunga eņģelis viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Un tai dienā Es meklēšu izdeldēt pagānus, kas ceļas pret Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Bet pār Dāvida namu un pār Jeruzālemes iedzīvotājiem Es izliešu žēlastības un lūgšanas garu. Un tie uz Mani raudzīsies, ko tie ir cauri dūruši. Un par Viņu tie žēlosies, kā žēlojās par vienīgo, un tie gauži par Viņu vaimanās, ka vaimanā par pirmdzimto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Tai dienā Jeruzālemē būs lielas raudas, kā raudāja pie HadadRimona Meģidus lejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Un zeme žēlosies, ikviena cilts par sevi, Dāvida nama cilts sevišķi un viņu sievas sevišķi, un Nātana nama cilts sevišķi un viņu sievas sevišķi, Levja nama cilts sevišķi un viņu sievas sevišķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Šimejus cilts sevišķi un viņu sievas sevišķi, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Visas citas ciltis, ikviena par sevi, un viņu sievas par sevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Tai dienā avots būs atvērts Dāvida namam un Jeruzālemes iedzīvotājiem pret grēkiem un pret nešķīstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Un tai dienā, saka Tas Kungs Cebaot, Es no zemes izdeldēšu dievekļu vārdus, ka tos vairs nepieminēs; arī (dievekļa) praviešus un nešķīsto garu Es atņemšu no zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Un notiks, ja kas vēl sludinās kā pravietis, tad viņa tēvs un viņa māte, kas viņu dzemdinājuši, uz to sacīs: tev nebūs dzīvot, jo viltu tu esi runājis Tā Kunga Vārdā, un viņa tēvs un viņa māte, kas to dzemdinājuši, to nodurs, kad tas sludinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, '4, Un notiks tai dienā, ka pravieši kaunēsies ikviens par savu parādīšanu, to pasludināt, un vairs neapvilks spalvas mēteli uz meliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Bet sacīs: es neesmu pravietis, es esmu zemes kopējs, jo viens mani saderējis no manas jaunības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Un ja kas sacīs: kas tās tādas rētas tavās rokās? Tad viņš sacīs: tā es esmu sakults savu mīļo namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Zoben, uzmosties pret Manu ganu un pret to vīru, kas Mans biedrs, saka Tas Kungs Cebaot; sit ganu, tad avis izklīdīs, bet es savu roku griezīšu pie tiem maziņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Un notiks visā zemē, saka Tas Kungs: divas daļas tur taps izdeldētas un izmirs, un trešā daļa tur atliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Un trešo daļu Es likšu ugunī un tos šķīstīšu, kā sudrabu šķīstī, un tos pārbaudīšu, kā zeltu pārbauda. Tie piesauks Manu vārdu, un Es tos paklausīšu un sacīšu: tie ir Mani ļaudis; un tie sacīs: Tas Kungs ir mans Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Redzi, diena nāk Tam Kungam, ka tavs laupījums taps izdalīts tavā vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Jo Es sapulcināšu visus pagānus karā pret Jeruzālemi, un pilsēta taps uzņemta un nami postīti un sievas apsmietas. Un puse pilsētas aizies cietumā, bet tie atlikušie ļaudis pilsētā netaps izdeldēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Un Tas Kungs izies un karos pret šiem pagāniem, tā kā tai dienā, kad viņš karo, kaujas dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Un Viņa kājas tai dienā stāvēs uz Eļļas kalna, kas Jeruzālemes priekšā pret rītiem, un Eļļas kalns šķelsies divējos gabalos pret rīta un vakara pusi, tā ka tur būs ļoti liela ieleja, un viena kalna puse atkāpsies pret ziemeli, un otra pret dienvidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Tad jūs bēgsiet Manu kalnu ielejā, (jo šī kalnu ieleja sniegsies līdz Ācelei) un jūs bēgsiet, kā jūs bēgāt no zemes trīcēšanas Uzijas, Jūda ķēniņa, dienās. Tad nāks Tas Kungs, mans Dievs, un visi svētie līdz ar Tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Un tai dienā nebūs gaismas, spīdekļi izzudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Bet tā būs savāda diena, kas Tam Kungam zināma; tur nebūs nedz dienas, nedz nakts. Un notiks, ap vakara laiku būs gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Un notiks tai dienā, dzīvs ūdens iztecēs no Jeruzālemes, viena puse pret rīta jūru un otra puse pret vakara jūru, un tas būs vasarā un ziemā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Un Tas Kungs būs ķēniņš pār visu zemi. Tai dienā Tas Kungs būs viens vienīgs, un Viņa vārds viens vienīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Visa šī zeme taps darīta par klajumu, no Ģibejas līdz Rimonai, pret dienasvidu no Jeruzālemes. Un tā taps paaugstināta un dzīvos savā vietā, no Benjamina vārtiem līdz veco vārtu vietai, līdz Stūru vārtiem, no Kananeēļa torņa līdz ķēniņa vīna spaidam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Un tur dzīvos, un lāsta vairs nebūs, un Jeruzāleme dzīvos drošībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Un šī būs tā mocība, ar ko Tas Kungs mocīs visus ļaudis, kas pret Jeruzālemi karojuši: miesa satrūdēs viņiem uz kājām stāvot un viņu acis satrūdēs savos dobumos un viņu mēle satrūdēs viņu mutē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Un notiks tai dienā, ka viņu starpā būs liela sajukšana no Tā Kunga, tā ka viens satvers otra roku, un cits pret citu pacels savu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Un Jūda karos Jeruzālemē, tā kā visapkārt savāks visu pagānu mantu, zeltu un sudrabu un drēbes lielā pulkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Tāda pat mocība būs zirgiem, zirgēzeļiem, kamieļiem un ēzeļiem un visiem lopiem, kas būs lēģeros, tā kā šī mocība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Un notiks, ka visi atlikušie no visām tautām, kas cēlušās pret Jeruzālemi, nāks ik gadus, pielūgt to ķēniņu, To Kungu Cebaot, un turēt lieveņu svētkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Un notiks, ja kāda no zemes ciltīm nenāks uz Jeruzālemi, pielūgt Ķēniņu, To Kungu Cebaot, tad lietus pār tiem nelīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Un kad Ēģiptes cilts nenāks, tad lietus arī nelīs pār viņiem, un tā mocība būs pār tiem, ar ko Tas Kungs tautas mocīs, kas nenāks svētīt lieveņu svētkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Šis Ēģiptei būs par grēku un visām tautām par grēku, kas nenāks svētīt lieveņu svētkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Tai dienā stāvēs uz zirgu zvārguļiem: svēts Tam Kungam, un tie podi Tā Kunga namā būs kā upuru kausi altāra priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Jo visi podi Jeruzālemē un Jūdā būs svēti Tam Kungam Cebaot, tā ka visi, kas grib upurēt, nāks un no tiem ņems un tanīs vārīs, un tai dienā Kanaānieša vairs nebūs Tā Kunga Cebaot namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Tā Kunga vārda spriedums par Israēli caur Malahiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Es jūs esmu mīlējis, saka Tas Kungs; bet jūs sakāt: kā Tu mūs esi mīlējis? Vai Ēsavs nav Jēkabam brālis? Saka Tas Kungs; tomēr Es Jēkabu mīlēju');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Un Ēsavu Es ienīdēju un viņa kalnus darīju par posta vietu un viņa mantas tiesu priekš šakāļiem tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Un jebšu Edoms sacītu: mēs esam salauzti, tomēr tās posta vietas atkal gribam uztaisīt, - tad Tas Kungs Cebaot saka tā: tie uztaisīs, bet Es noārdīšu, un tos nosauks par bezdievības robežām un par ļaudīm, par ko Tas Kungs mūžīgi dusmo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Un jūsu acis to redzēs, un jūs sacīsiet: Tas Kungs pagodināsies pāri pār Israēla robežām. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Dēlam būs godāt savu tēvu, un kalpam savu kungu. Ja Es esmu Tēvs, kur ir Mans gods? Un ja Es esmu Kungs, kur ir Mana bijāšana? saka Tas Kungs Cebaot uz jums priesteriem, Mana Vārda nicinātajiem; bet jūs sakāt: kā tad mēs nicinājam Tavu Vārdu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Jūs nesat uz Manu altāri sagānītu maizi. Tad jūs sakāt: ar ko mēs Tevi sagānījām? Ar to, ka jūs sakāt: Tā Kunga galds nav cienījams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Jo kad jūs ko aklu atnesat upurēt, tad tas jums nav nelabs, un ja jūs ko tizlu vai vāju atnesat, tad tas nav nelabs. Atnesat to jel savam valdītājam, vai viņam pie tevis būs labs prāts, jeb vai viņš tavu vaigu žēlīgi uzlūkos? saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Nu tad pielūdziet jel Dieva vaigu, lai Viņš mums ir žēlīgs. No jūsu rokas tas noticis: vai tad Viņš jūsu vaigu žēlīgi uzskatīs? saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Kaut jel kāds būtu jūsu starpā, kas durvis aizslēdz, lai jūs velti uguni neiededzinājāt uz Mana altāra; Man nav labs prāts pie jums, saka Tas Kungs Cebaot, un tas upuris no jūsu rokām Man nepatīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Jo no saules uzlēkšanas līdz noiešanai Mans Vārds ir paaugstināts starp tautām, un ikkatrā vietā Manam Vārdam top kvēpināts un šķīsts upuris atnests. Jo Mans Vārds ir liels starp tautām, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Bet jūs to sagānat, sacīdami: Tā Kunga galds, tas ir sagānīts, un viņa ienākumu riebj baudīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Un jūs sakāt: redzi, kāds grūtums! Un nebēdājat par to, saka Tas Kungs Cebaot, jūs atnesat, kas ir laupīts, un kas tizls un vājš, un tā upurējat upuri. Vai tas Man var patikt no jūsu rokas? saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Nolādēts tas blēdis, kam savā ganāma pulkā ir auniņš, un kas sola un upurē Tam Kungam ko maitātu! Jo Es esmu liels Ķēniņš, saka Tas Kungs Cebaot: un Mans Vārds ir bijājams starp tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Un nu, jūs priesteri, šis bauslis jums ir dots:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Ja jūs negribat klausīt, nedz ņemt pie sirds, Manam Vārdam dot godu, saka Tas Kungs Cebaot, tad Es sūtīšu lāstu pret jums un nolādēšu jūsu svētību, tiešām, Es to nolādēšu, tāpēc ka jūs neņemat pie sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Redzi, Es jums maitāšu sēklu un kaisīšu sūdus uz jūsu vaigiem, jūsu svētku sūdus, tā ka jūs līdz ar tiem tapsiet izmēzti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Tad jūs samanīsiet, ka Es šo bausli pie jums esmu sūtījis, ka tā būtu Mana derība ar Levi, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mana derība ar viņu bija dzīvība un miers, un to Es viņam devu, lai Mani bīstas, un viņš Mani bijās, un viņš drebēja priekš Mana Vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Patiesības bauslība bija viņa mutē, un nelietība nebija atrodama uz viņa lūpām. Viņš ar Mani staigāja mierā un taisnībā un atgrieza daudz ļaudis no nozieguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Jo priestera lūpām būs sargāt atzīšanu, un no viņa mutes būs meklēt mācību, jo viņš ir Tā Kunga Cebaot vēstnesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Bet jūs esat nogriezušies no ceļa, jūs esat darījuši, ka daudz pie bauslības piedauzījušies, jūs Levja derību esiet samaitājuši, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Tad Es arīdzan jūs esmu darījis nievājamus un necienīgus priekš visiem ļaudīm, tāpēc ka jūs neturat Manus ceļus, bet bauslībā uzlūkojiet cilvēka vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Vai mums visiem nav viens tēvs? Vai viens Dievs mūs nav radījis? Kāpēc tad mēs cits citam neturam ticību, bet sagānam savu tēvu derību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Jūda netur ticību, un iekš Israēla un Jeruzālemē notiek negantība. Jo Jūda sagānījis Tā Kunga svētumu, ko viņš mīļo, un precējis sveša dieva meitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Tas Kungs lai izdeldē tam vīram, kas tā dara, no Jēkaba dzīvokļa tos, kas prasa un kas atbild, un tos, kas upurē Tam Kungam Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Otrkārt jūs šo dariet: jūs Tā Kunga altāri apklājat ar asarām, ar raudām un ar nopūtām, tā ka Viņš to upuri vairs nevar ieredzēt nedz labprāt saņemt no jūsu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Tad jūs sakāt: Kāpēc tā? Tāpēc ka Tas Kungs ir liecinieks starp tevi un tavas jaunības sievu, kurai tu ticību neesi turējis, un viņa tomēr ir tava biedrene un tava saderētā sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Tā neviens nav darījis, kam vēl gars atlicies. Bet ko tas viens darīja? Viņš meklēja dzimumu no Dieva. Tāpēc sargājaties savā garā, un neatstāji savas jaunības sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Jo Es ienīstu šķiršanu, saka Tas Kungs, Israēla Dievs, un to, kas savas drēbes apgāna ar varas darbu, saka Tas Kungs Cebaot; tāpēc sargājaties savā garā, ka turat ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Jūs apkaitināt To Kungu ar savu valodu; bet jūs sakāt: ar ko mēs Viņu apkaitinājām? Ar to, ka jūs sakāt: kas ļaunu dara, tas ir labs priekš Tā Kunga acīm, un pie tādiem Viņam ir labs prāts, jeb: kur ir tas Dievs, kas soda?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Redzi, Es sūtu Savu eņģeli, lai tas Manā priekšā sataisa ceļu. Un drīz nāks uz Savu namu Tas Kungs, ko jūs meklējat un tas derības eņģelis, pie kā jums labs prāts. Redzi, Viņš nāk, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Bet kas panesīs Viņa atnākšanas dienu, un kas pastāvēs, kad Viņš rādīsies? Jo Viņš būs kā kausētāja uguns un kā mazgātāju sārms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Un Viņš sēdēs, sudrabu kausēt un šķīstīt, un šķīstīs Levja bērnus un tos iztīrīs kā zeltu un sudrabu; tad tie Tam Kungam upuri nesīs taisnībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Tad Jūda un Jeruzālemes upuris Tam Kungam būs salds, kā vecos laikos un senajos gados.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Es pie jums nākšu uz tiesu un būšu ātrs liecinieks pret burvjiem un laulības parkāpējiem un pret tiem, kas nepatiesi zvēr, un pret tiem, kas nospiež algādža algu, atraitni un bāriņu, un kas spaida svešinieku un Mani nebīstas, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Jo Es Tas Kungs citāds nepalieku, tāpēc jums, Jēkaba bērni, gals vēl nav darīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'No savu tēvu laika jūs esiet atkāpušies no Maniem likumiem un tos neesat turējuši. Atgriežaties atkal pie Manis, tad Es atgriezīšos pie jums, saka Tas Kungs Cebaot. Bet jūs sakāt: kā lai atgriežamies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Vai gan cilvēks Dievu var apkrāpt, kā jūs Mani apkrāpjat? Un jūs sakāt: kā mēs Tevi apkrāpjam? Ar desmito(tiesu) un ar cilājamo upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Tāpēc jūs esat ar lāstu nolādēti, ka jūs Mani apkrāpjat, visi ļaudis kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Nesiet pilnu desmito(tiesu) mantu namā, ka barība ir Manā namā, un pārbaudiet jel Mani tā, saka Tas Kungs Cebaot: vai Es jums neatvēršu debess logus un jums nedošu svētības pārpārēm?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Un jūsu dēļ Es rāšu ēdēju, lai tas jums nemaitā zemes augļus, un lai vīna koks tīrumā jums nav neauglīgs, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Un visas tautas jūs teiks laimīgus, jo jūs būsiet jauka zeme, saka Tas Kungs Cebaot. -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Jūsu vārdi ir cieti pret Mani, saka Tas Kungs. Un jūs sakāt: ko mēs pret Tevi runājam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Jūs sakāt: tas ir velti, Dievam kalpot, jo kāds labums atlec, kad turam Viņa bausli, un ka bēdās staigājam priekš Tā Kunga Cebaot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Bet nu mēs teicam laimīgus tos pārgalvīgos, jo bezdievības darītāji pieaug, tie Dievu kārdina un taču izsprūk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Tad tie, kas To Kungu bīstas, runāja cits ar citu, un Tas Kungs nomanīja un ieklausījās, un piemiņas grāmata ir rakstīta Viņa priekšā tiem, kas To Kungu bīstas, un tiem, kas Viņa vārdu piemin.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Un tai dienā, ko Es darīšu, saka Tas Kungs Cebaot, tie Man būs par īpašumu, un Es tos žēlošu, kā vīrs savu dēlu žēlo, kas viņam kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Tad jūs atkal redzēsiet to starpību starp taisnu un bezdievīgu, starp to, kas Dievam kalpo, un to, kas Viņam nekalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Jo redzi, tā diena nāk degoša kā ceplis, tad visi lepnie un visi bezdievības darītāji būs rugāji, un tā nākamā diena tos iededzinās, saka Tas Kungs Cebaot, kas tiem nepametīs nedz sakni, nedz zaru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Bet jums, kas Manu vārdu bīstaties, taisnības saule uzlēks, un dziedināšana būs apakš viņas spārniem, un jūs iziesiet un lēksiet kā baroti teļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Un jūs samīsiet bezdievīgos, jo tie būs pelni apakš jūsu pēdām tai dienā, ko Es darīšu, saka Tas Kungs Cebaot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Pieminiet Mozus, Mana kalpa, bauslību, ko Es viņam esmu pavēlējis Horeba kalnā priekš visa Israēla, tos likumus un tās tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Redzi, Es jums sūtu pravieti Eliju, pirms nāks Tā Kunga lielā un bijājamā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Un viņš atgriezīs tēvu sirdis pie bērniem un bērnu sirdis pie tēviem, lai Es nenāku, zemi izdeldēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Jēzus Kristus cilts grāmata. Jēzus bija Dāvida, Dāvids Ābrahāma dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Ābrahāms dzemdināja Īzaku, un Īzaks dzemdināja Jēkabu, un Jēkabs dzemdināja Jūdu un viņa brāļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Un Jūda dzemdināja Vārecu un Cāru no Tamaras; un Vārecs dzemdināja Hecronu, un Hecrons dzemdināja Aramu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Un Arams dzemdināja Aminadabu, un Aminadabs dzemdināja Nahšonu, un Nahšons dzemdināja Zalmanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Un Zalmans dzemdināja Boasu no Rahabas, un Boas dzemdināja Obedu no Rutes, un Obeds dzemdināja Isaju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Un Isajus dzemdināja ķēniņu Dāvidu, un ķēniņš Dāvids dzemdināja Salamanu no Ūrijas sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Un Salamans dzemdināja Rekabeamu, un Rekabeams dzemdināja Abiju, un Abija dzemdināja Asu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Un Asus dzemdināja Jehošafatu, un Jehošafats dzemdināja Jehoramu, un Jehorams dzemdināja Ociju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Un Ocija dzemdināja Joatamu, un Joatams dzemdināja Akacu, un Akacs dzemdināja Eceķiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Un Eceķija dzemdināja Manasu, un Manasus dzemdināja Amonu, un Amons dzemdināja Josiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Un Josija dzemdināja Jekoniju un viņa brāļus ap to aizvešanu uz Bābeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Un pēc aizvešanas uz Bābeli Jekonija dzemdināja Zalatiēli, un Zalatiēls dzemdināja Corobabeli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Un Corobabels dzemdināja Abiudu, un Abiuds dzemdināja Eliaķimu, un Eliaķims dzemdināja Hacoru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Un Hacors dzemdināja Cadoku, un Cadoks dzemdināja Aķimu, un Aķims dzemdināja Eliudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Un Eliuds dzemdināja Eleazaru, un Eleazars dzemdināja Mattanu, un Mattans dzemdināja Jēkabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Un Jēkabs dzemdināja Jāzepu, Marijas vīru, no kuras ir piedzimis Jēzus, kas top saukts Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Tad nu pavisam no Ābrahāma līdz Dāvidam ir četrpadsmit augumi; un no Dāvida līdz aizvešanai uz Bābeli ir četrpadsmit augumi; un no aizvešanas uz Bābeli līdz Kristum četrpadsmit augumi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Bet Jēzus Kristus piedzimšana bija tāda: kad Marija, viņa māte, Jāzepam bija saderēta, pirms tie nāca kopā, tā atradās grūta no Svētā Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Bet Jāzeps, viņas vīrs, taisns būdams un negribēdams tai kaunu darīt, gribēja to slepeni atstāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Bet viņam tā savā prātā domājot, redzi, Tā Kunga eņģelis sapnī parādījās sacīdams: Jāzep, tu Dāvida dēls, nebīsties, Mariju, savu sievu, ņemt pie sevis; jo kas iekš tās dzimis, tas ir no Svētā Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Un viņa dzemdēs dēlu, un Tā vārdu tev būs saukt Jēzus; jo Viņš izpestīs Savus ļaudis no viņu grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Bet viss tas ir noticis, lai piepildītos, kas runāts no Tā Kunga caur to pravieti, kas saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '“Redzi, tā jumprava būs grūta un dzemdēs Dēlu, un Viņa vārdu sauks Immanuels,” tas ir tulkots: “Dievs ar mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Bet Jāzeps no miega uzmodies darīja, kā viņam Tā Kunga eņģelis bija pavēlējis, un ņēma savu sievu pie sevis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Un viņu neatzina, līdz kamēr viņa bija dzemdējusi savu pirmdzimto Dēlu, un nosauca Viņa vārdu Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Un kad Jēzus bija dzimis Bētlemē iekš Jūdu zemes ķēniņa Hērodus laikā, redzi, tad gudri (vīri) no austruma zemes nāca uz Jeruzālemi un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Kur ir Tas piedzimušais Jūdu ķēniņš? Jo mēs Viņa zvaigzni esam redzējuši austruma zemē un nākuši, Viņu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Kad ķēniņš Hērodus to dzirdēja, tad viņš izbijās un visa Jeruzāleme līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Un saaicinājis visus Jūdu augstos priesterus un rakstu mācītājus, viņš izklausināja no tiem, kur Kristum bija dzimt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Un tie tam sacīja: “Bētlemē iekš Jūdu zemes; jo tā ir rakstīts caur to pravieti:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '“Un tu, Bētleme Jūdu zemē, tu nebūt neesi tā mazākā starp tiem lieliem kungiem no Jūda; jo no tevis nāks Tas Valdnieks, kas valdīs pār Maniem Israēla ļaudīm.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tad Hērodus paslepen aicināja tos gudros un īsteni izklausināja no tiem to laiku, kad tā zvaigzne atspīdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Un viņš tos sūtīja uz Bētlemi un sacīja: ejat un izklausinājiet it labi par To Bērnu un To atraduši atsakāt man, ka arī es nāku, To pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Tie nu to ķēniņu dzirdējuši aizgāja. Un redzi, tā zvaigzne, ko tie austruma zemē bija redzējuši, gāja tiem priekšā, kamēr tā nāca un apstājās virsū, kur Tas Bērns bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Un to zvaigzni ieraudzījuši, tie priecājās ar varen lielu prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Un namā iegājuši, tie atrada To Bērnu līdz ar Mariju, Viņa māti, un pie zemes mezdamies tie Viņu pielūdza; pēc tam, savu mantu atdarījuši, tie To apdāvināja ar zeltu un vīraku un mirrēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Un Dievs tiem parādīja sapnī, lai negriežās atpakaļ pie Hērodus; un tie aizgāja pa citu ceļu uz savu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Bet kad tie bija aizgājuši, redzi, tad Dieva eņģelis Jāzepam parādījās sapnī un sacīja: celies un ņem To Bērnu un Viņa māti un bēdz uz Ēģiptes zemi un paliec tur, kamēr es tev sacīšu; jo Hērodus meklē To Bērnu nomaitāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Un cēlies viņš ņēma To Bērnu un Viņa māti nakts laikā un aizgāja uz Ēģiptes zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Un palika turpat, līdz kamēr Hērodus bija miris; ka piepildītos, ko Tas Kungs caur to pravieti bija runājis, kas saka: “No Ēģiptes zemes Es Savu Dēlu esmu aicinājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Kad nu Hērodus redzēja, ka bija piekrāpts no tiem gudriem, tad viņš ļoti apskaitās un izsūtījis apkāva visus bērnus Bētlemē un pa visu Bētlemes tiesu, divus gadus vecus un vēl jaunākus, pēc tā laika, ko tas no tiem gudriem īsteni bija izklausinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tad piepildījās, ko pravietis Jeremija runājis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '“Brēkšana ir dzirdēta Rāmā, žēlošanās, raudāšana un daudz kaukšanas. Rahēle apraud savus bērnus un negribās iepriecinājuma, jo to vairs nav.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Bet kad Hērodus bija nomiris, lūk, tad Tā Kunga eņģelis sapnī parādījās Jāzepam Ēģiptes zemē');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Un sacīja: celies un ņem To Bērnu un Viņa māti, un ej uz Israēla zemi; jo tie ir nomiruši, kas Tā Bērna dvēseli meklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Un viņš cēlās un ņēma To Bērnu un Viņa māti, un nonāca Israēla zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Bet kad viņš dzirdēja, Arhelaus Jūdu zemē valdām sava tēva Hērodus vietā, tad viņš bijās turp noiet; un sapnī no Dieva pamācīts, viņš atkāpās Galilejas robežās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'Un tur nonācis viņš apmetās tai pilsētā, ko sauc Nacareti, ka piepildītos, kas sacīts caur tiem praviešiem: “Viņš taps nosaukts Nacarietis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Tanīs dienās nāca Jānis, tas Kristītājs, un sludināja Jūdu zemes tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Sacīdams: “Atgriežaties no grēkiem, jo Debesu valstība ir tuvu klāt nākusi,”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Jo šis ir tas, no kā pravietis Jesaja runājis sacīdams: “Saucēja balss tuksnesī: “Sataisiet Tā Kunga ceļu; dariet līdzenas Viņa tekas.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Bet viņš, Jānis, valkāja kamieļu spalvu drēbes un ādas jostu ap saviem gurniem; un viņa barība bija siseņi un kameņu medus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tad izgāja pie viņa Jeruzāleme un visa Jūdu zeme un viss Jardānes apgabals,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Un tapa no viņa kristīti Jardānē, izsūdzēdami savus grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Un daudz farizeju un saduceju ieraudzījis nākam pie kristības, viņš uz tiem sacīja: “Jūs odžu dzimums, kas jums ir rādījis, izbēgt no nākamās dusmības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Tāpēc nesiet pienākamus atgriešanās augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Un nedomājiet pie sevis sacīt: “Mums ir Ābrahāms par tēvu.” Jo Es jums saku, ka Dievs no šiem akmeņiem spēj Ābrahāmam bērnus radīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Un cirvis kokiem jau pie saknes ir pielikts; tāpēc ikviens koks, kas nenes labus augļus, top nocirsts un ugunī iemests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Es jūs gan kristīju ar ūdeni uz atgriešanos no grēkiem, bet kas pēc manis nāk, Tas ir jo spēcīgāks nekā es; Tam es neesmu cienīgs kurpes nest; Tas jūs kristīs ar Svēto Garu un ar uguni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Tam vēteklis rokā, un Tas Savu klonu tīrīs caur caurim un sakrās Savus kviešus klētī, bet tās pelavas Viņš sadedzinās ar neizdzēšamu uguni.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tanī laikā Jēzus nāca no Galilejas uz Jardāni pie Jāņa, ka no tā taptu kristīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Bet Jānis Tam neļāva un sacīja: “Man vajadzētu no Tevis tapt kristītam, un Tu nāci pie manis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Bet Jēzus atbildēja un uz to sacīja: “Lai nu tā ir; jo tā mums pieklājās, piepildīt visu taisnību.” Tad viņš to Tam ļāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Un kad Jēzus bija kristīts, tad Viņš tūdaļ no ūdens izkāpa. Un redzi, debesis atvērās pār Viņu, un Jānis redzēja Dieva Garu kā balodi nolaižamies un uz Viņu nākam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Un redzi, balss no debesīm sacīja: “Šis ir Mans mīļais Dēls, pie kā Man ir labs prāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tad Jēzus no Tā Gara tapa aizvests tuksnesī, ka no velna taptu kārdināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Un kad Viņš četrdesmit dienas un četrdesmit naktis bija gavējis, tad Viņam gribējās ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Un tas kārdinātājs piestājās pie Viņa un sacīja: “Ja Tu esi Dieva Dēls, tad saki, lai šie akmeņi top par maizi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Un Viņš atbildēja un sacīja: “Stāv rakstīts: “Cilvēks nedzīvo no maizes vien, bet no ikkatra vārda, kas iziet no Dieva mutes.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Tad velns Viņu noveda sev līdz uz to svēto pilsētu un Viņu cēla pašā Dieva nama jumta galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Un uz Viņu sacīja: “Ja Tu esi Dieva Dēls, tad nolaidies zemē! Jo stāv rakstīts: “Viņš Saviem eņģeļiem par Tevi pavēlēs, un tie Tevi uz rokām nesīs, ka Tu Savu kāju pie akmens nepiedauzīsi.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Tad Jēzus uz to sacīja: “Atkal stāv rakstīts: “Dievu, savu Kungu, tev nebūs kārdināt.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Atkal velns to veda sev līdz uz ļoti augstu kalnu un Viņam rādīja visas pasaules valstis un viņu godību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Un uz To sacīja: “To visu es Tev gribu dot, ja Tu zemē mezdamies mani pielūgsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tad Jēzus uz to sacīja: “Atkāpies, sātan! Jo stāv rakstīts: “Tev būs pielūgt Dievu, savu Kungu, un Viņam vien kalpot.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Tad velns Viņu atstāja. Un redzi, eņģeļi pie Viņa piestājās un Viņam kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Bet Jēzus dzirdējis, Jāni esam nodotu, atkal gāja uz Galileju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Un Nacareti atstājis, Viņš nāca un mājoja Kapernaūmā, jūrmalas pilsētā Zebulona un Naftalus robežās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Ka piepildītos, kas ir runāts caur pravieti Jesaju, kas tā saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '“Zebulona zeme un Naftalus zeme uz jūrmalas pusi, AizJardāne, pagānu Galileja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Tie ļaudis, kas tumsībā sēž, redzējuši lielu gaišumu, un tiem, kas sēž nāves zemē un ēnā, gaisma uzlēkusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'No tā laika Jēzus iesāka sludināt un sacīt: “Atgriežaties no grēkiem, jo Debesu valstība tuvu klāt nākusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Un staigādams pie Galilejas jūras, Jēzus ieraudzīja divus brāļus, Sīmani, kas nosaukts Pēteris, un Andreju, viņa brāli, tīklu jūrā metam, jo tie bija zvejnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Un Viņš uz tiem sacīja: “Nāciet Man pakaļ, Es jūs darīšu par cilvēku zvejniekiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Un tūdaļ savus tīklus atstājuši, tie Viņam gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Un no turienes tālāki gājis, Viņš ieraudzīja citus divus brāļus, Jēkabu, Cebedeja dēlu, un Jāni, viņa brāli, laivā ar savu tēvu Cebedeju savus tīklus lāpam, un Viņš tos sauca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Tad tie tūdaļ to laivu un savu tēvu atstājuši, Viņam gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Un Jēzus izstaigāja visu Galileju, mācīdams viņu baznīcās un sludinādams to priecas mācību no tās valstības un dziedinādams tiem ļaudīm visas slimības un visas vājības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Un Viņa slava izpaudās pa visu Sīriju, un pie Viņa atnesa visus neveselus, no dažādām sērgām un sāpēm pārņemtus un velna apsēstus un mēnessērdzīgus un melmeņu sērdzīgus, un Viņš tos darīja veselus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Un daudz ļaužu Viņam gāja pakaļ no Galilejas un no tām desmit pilsētām un no Jeruzālemes un no Jūdu zemes un no viņpus Jardānes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Bet kad Viņš tos ļaudis redzēja, tad Viņš uzkāpa uz kalnu un apsēdās, un Viņa mācekļi pie Viņa piestājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Un Savu muti atdarījis, Viņš tos mācīja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '“Svētīgi tie, kas garā nabagi, jo Debesu valstība viņiem pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Svētīgi tie, kam ir bēdas, jo tie taps iepriecināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Svētīgi tie lēnprātīgie, jo tie to zemi iemantos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Svētīgi tie, kas izsalkuši un kam slāpst pēc taisnības, jo tie taps piepildīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Svētīgi tie sirdsžēlīgie, jo tie žēlastību dabūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Svētīgi tie sirdsšķīstie, jo tie Dievu redzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Svētīgi tie, kas mieru tur, jo tie taps saukti Dieva bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Svētīgi tie, kas taisnības dēļ vajāti, jo Debesu valstība viņiem pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Svētīgi jūs esat, ja Manis dēļ jūs lamā un vajā un visu ļaunu par jums runā, melodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Esat priecīgi un līksmi, jo jūsu alga ir liela debesis; jo tā tie vajājuši tos praviešus, kas priekš jums bijuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Jūs esat tās zemes sāls; ja nu sāls nelietīga, ar ko tad to sālīs? Tā neder vairs nekam, bet tikai ārā metama un no ļaudīm saminama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Jūs esat tās pasaules gaišums; pilsēta, kas stāv kalnā, nevar būt apslēpta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Tā arī sveci iededzinājis, neviens to neliek apakš pūra, bet uz lukturi; tad tā visiem spīd, kas ir namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tāpat lai jūsu gaisma spīd ļaužu priekšā, ka tie ierauga jūsu labos darbus un godā jūsu Tēvu, kas ir debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Nedomājiet, ka Es esmu nācis, atmest bauslību un praviešus. Es neesmu nācis atmest, bet piepildīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Jo patiesi, Es jums saku: tiekams debess un zeme zudīs, nezudīs neviena, ne vismazākā rakstu zīmīte jeb raksta galiņš no bauslības, tiekams viss notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Tāpēc, ja kas vienu no šiem vismazākiem baušļiem atmetīs un ļaudis tā mācīs, tas taps dēvēts tas vismazākais Debesu valstībā: bet ja kas darīs un mācīs, tas taps dēvēts liels Debesu valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Jo Es jums saku: ja jūsu taisnība nav labāka nekā to rakstu mācītāju un farizeju, tad jūs Debesu valstībā nenāksiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Jūs esat dzirdējuši, ka vecajiem ir sacīts: tev nebūs nokaut; un kas nokauj, tas būs sodāms caur tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Bet Es jums saku: kas ar savu brāli dusmo, tas būs sodāms caur tiesu; bet kas uz savu brāli saka: raka(nevērtīgs)! Tas būs sodāms caur augsto tiesu; bet kas saka: ģeķi(bezdievis)! Tas būs sodāms elles ugunī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Tāpēc, kad tu savu dāvanu uz altāra upurē un turpat atminies, ka tavam brālim kas ir pret tevi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Tad atstāj tur altāra priekšā savu dāvanu un noej, saderies(izlīgsti) papriekš ar savu brāli, un tad nāc un upurē savu dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Esi labprātīgs savam pretiniekam drīz, kamēr ar viņu vēl esi uz ceļa, ka pretinieks tevi nenodod soģim, un soģis tevi nenodod sulainim, un tu netopi iemests cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Patiesi, Es tev saku, tu no turienes neiziesi, kamēr nenomaksāsi pēdējo artavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Jūs esat dzirdējuši, ka vecajiem ir sacīts, tev nebūs laulību pārkāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Bet Es jums saku, ka ikviens, kas sievu uzskata, to iekārodamies, tas ar viņu laulību jau pārkāpis savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Bet ja tava labā acs tevi apgrēcina, izrauj to un met nost; jo tas tev labāki, ka viens no taviem locekļiem pazūd, nekā kad visa tava miesa top iemesta ellē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Un ja tava labā roka tevi apgrēcina, nocērt to un met nost; jo tas tev labāki, ka viens no taviem locekļiem pazūd, nekā kad visa tava miesa top iemesta ellē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Ir arī sacīts: kas no savas sievas šķirās, tas lai tai dod šķiršanās grāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Bet Es jums saku: kas no savas sievas šķirās bez vien maucības vainas dēļ, tas viņu spiež laulību pārkāpt; un ja kas atšķirtu precē, tas pārkāpj laulību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Jūs vēl esat dzirdējuši, ka vecajiem ir sacīts: tev nebūs nepatiesi zvērēt, bet Tam Kungam turēt, ko tu zvērēdams esi solījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Bet Es jums saku, ka jums ne pavisam nebūs zvērēt, nedz pie debess, jo tā ir Dieva goda krēsls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Nedz pie zemes, jo tā ir Viņa kāju pamesls, nedz pie Jeruzālemes, jo tā ir tā lielā ķēniņa pilsēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Tev arī nebūs zvērēt pie savas galvas, jo tu nespēji nevienu matu ne baltu pataisīt ne melnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Bet jūsu vārds lai ir: jā, jā! nē, nē! kas pāri par to, tas ir no ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Jūs esat dzirdējuši, ka ir sacīts: aci pret aci un zobu pret zobu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Bet Es jums saku, ka jums nebūs pretī stāvēt tam ļaunam, bet kas tevi vaigā sit labajā pusē, tam sniedz arī otru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Un kas ar tevi grib tiesāties un ņemt tavus svārkus, tam palaid arī to uzvalku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Un kas tevi dzen vienu jūdzi, ar to paej divus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Dod tam, kas tevi lūdz, un neatraujies no tā, kas ko no tevis grib aizņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Jūs esat dzirdējuši, ka ir sacīts: tev būs savu tuvāko mīlēt un savu ienaidnieku ienīdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Bet Es jums saku: mīļojiet savus ienaidniekus, svētījiet tos, kas jūs nolād, dariet labu tiem, kas jūs ienīst, un lūdziet par tiem, kas jūs kaitina un vajā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Ka jūs topat sava debesu Tēva bērni; jo Viņš liek Savai saulei uzlēkt pār ļauniem un labiem un liek lietum līt pār taisniem un netaisniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Jo ja jūs tos vien mīļojiet, kas jūs mīļo, kāda alga jums nākas? Vai muitnieki nedara tāpat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Un kad jūs sveicinājiet tikai savus brāļus, ko teicamu jūs dariet? Vai muitnieki nedara tāpat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Tāpēc esat pilnīgi, tā kā jūsu Tēvs debesīs ir pilnīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Ņemiet vērā, ka savas nabagu dāvanas nedodat cilvēku priekšā, lai šie jūs redz; citādi jums nav nekādas algas pie sava Tēva debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Kad tu nu nabagus apdāvini, tad neliec savā priekšā trumetes pūst, tā kā tie liekuļi dara baznīcās un ielās, lai no ļaudīm top godināti. Patiesi, Es jums saku, tiem jau ir sava alga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Bet kad tu nabagus apdāvini, tad lai tava kreisā roka nezina, ko labā dara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Tā ka tava dāvināšana paliek apslēpta; un tavs Tēvs, kas redz slepenībā, Tas tev to atmaksās gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Un kad tu Dievu lūdzi, tad neturies kā tie liekuļi, jo tiem patīk stāvēt un Dievu lūgt baznīcās un ielu stūros, lai no ļaudīm top redzēti. Patiesi, Es jums saku, tiem jau ir sava alga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Bet kad tu Dievu lūdzi, tad ej savā kambarī un, savas durvis aizslēdzis, pielūdzi savu Tēvu slepenībā, un tavs Tēvs, kas redz slepenībā, Tas tev to atmaksās gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Bet Dievu lūdzot nepļāpājiet kā tie pagāni; jo tie domā, ka tie savas pļāpāšanas dēļ top paklausīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Tad nu nepaliekat tiem līdzīgi; jo jūsu Tēvs gan zina, kā jums vajag, pirms jūs Viņu lūdzat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Tāpēc jums būs tā lūgt: “Mūsu Tēvs debesīs. Svētīts lai top Tavs vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Lai nāk Tava valstība. Tavs prāts lai notiek kā debesīs tā arī virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Mūsu dienišķu maizi dod mums šodien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Un piedod mums mūsu parādus, kā arī mēs piedodam saviem parādniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Un neievedi mūs kārdināšanā; bet atpestī mūs no tā ļauna. Jo Tev pieder tā valstība un tas spēks un gods mūžīgi. Āmen.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Jo kad jūs cilvēkiem viņu noziegumus piedodat, tad jums jūsu Debesu Tēvs arīdzan piedos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Bet ja jūs cilvēkiem viņu noziegumus nepiedodat, tad jums jūsu Debesu Tēvs jūsu noziegumus arī nepiedos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Un kad jūs gavējat, tad neesat saīguši kā tie liekuļi, jo tie dara savus vaigus nejaukus, lai ļaudīm kā gavētāji izrādās. Patiesi, Es jums saku, tiem jau ir sava alga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Bet tu gavēdams svaidi savu galvu un mazgā savu vaigu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Ka tu nerādies ļaudīm gavēdams, bet savam Tēvam, kas redz slepenībā. Un tavs Tēvs, kas redz slepenībā, Tas tev to atmaksās gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Nekrājiet sev mantas virs zemes, kur kodes un rūsa tās maitā, un kur zagļi rok un zog;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Bet krājiet sev mantas debesīs, kur ne kodes ne rūsa tās nemaitā, un kur zagļi nerok un nezog.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Jo kur jūsu manta, tur būs arī jūsu sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Acs ir miesas spīdeklis; ja nu tava acs skaidra, tad visa tava miesa būs gaiša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Bet ja tava acs kaitīga, tad visa tava miesa būs tumša. Ja nu tas gaišums iekš tevis ir tumsība, cik liela būs tā tumsība pati?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Neviens diviem kungiem nevar kalpot; jo tas vienu ienīdīs un otru mīlēs, jeb tas vienam pieķersies un otru atmetīs. Jūs nevarat kalpot Dievam un mantai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Tāpēc Es jums saku: nezūdāties savas dzīvības pēc, ko ēdīsiet un dzersiet; nedz arī par savām miesām, ar ko ģērbsities. Vai dzīvība nav labāka nekā barība? Un vai miesas nav labākas nekā drēbes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Skatāties uz putniem gaisā: ne tie sēj, ne tie pļauj, ne tie sakrāj šķūņos, un jūsu Debesu Tēvs tos baro. Vai tad jūs neesat daudz labāki nekā viņi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kurš jūsu starpā savam mūžam var pielikt vienu olekti, jebšu tas tādēļ bēdājās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Un kāpēc jūs zūdāties apģērba dēļ? Mācaties pie puķēm laukā, kā tās aug. Ne tās strādā, ne tās vērpj;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Tomēr Es jums saku, ka pat Salamans visā savā godībā tā nav bijis apģērbts kā viena no tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Ja tad Dievs tā ģērbj zāli laukā, kas šodien stāv un rītu krāsnī top iemesta, vai tad ne daudz vairāk jūs? Ak jūs mazticīgie!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Tāpēc jums nebūs zūdīties nedz sacīt: ko ēdīsim, jeb ko dzersim, jeb ar ko ģērbsimies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Jo pēc visa tā pagāni dzenās; jo jūsu Debesu Tēvs zina, ka jums visa tā vajag.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Bet dzenaties papriekš pēc Dieva valstības un pēc Viņa taisnības, tad jums visas šās lietas taps piemestas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Tāpēc nezūdāties nākošā rīta pēc, jo rītdiena pati par sevi zūdīsies. Ir diezgan, ka ikvienai dienai savas pašas bēdas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Netiesājiet, lai jūs netopat tiesāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Jo ar kādu tiesu jūs tiesājiet, jūs tapsiet tiesāti, un ar kādu mēru jūs mērojiet, jums taps atmērots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Un ko tu redzi skabargu sava brāļa acī, bet baļķi savā acī tu nenomani?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Jeb kā tu sacīsi uz savu brāli: laid, es izvilkšu to skabargu no tavas acs, - un redzi, baļķis ir tavā paša acī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Tu liekuli, velc papriekš to baļķi no savas acs un tad pielūko izvilkt to skabargu no sava brāļa acs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Nedodiet to svētumu suņiem un nemetiet savas pērles cūkām priekšā, ka tās ar savām kājām viņas nesamin un atgriezdamās jūs nesaplosa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Lūdziet, tad jums taps dots; meklējiet, tad jūs atradīsiet; klaudziniet, tad jums taps atvērts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Jo ikviens, kas lūdzās, dabū, un kas meklē, atrod, un tam, kas klaudzina, top atvērts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Jeb kurš cilvēks ir jūsu starpā, kas savam dēlam, kad tas maizes lūdzās, dotu akmeni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Jeb kad tas zivi lūdzās, tam dotu čūsku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Ja tad jūs, ļauni būdami, zināt saviem bērniem dot labas dāvanas, vai jo vairāk jūsu Tēvs debesīs nedos laba tiem, kas Viņu lūdz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Tad nu visu, ko jūs gribat, lai cilvēki jums dara, tāpat dariet arī jūs viņiem. Jo šī ir tā bauslība un tie pravieši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Ieejat caur tiem šauriem vārtiem, jo tie vārti ir plati un tas ceļš ir plats, kas aizved uz pazušanu, un to ir daudz, kas caur tiem ieiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Un tie vārti ir šauri un šaurs tas ceļš, kas aizved uz dzīvību, un to ir maz, kas to atrod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Bet sargājieties no tiem viltīgiem praviešiem, kas pie jums nāk avju drēbēs, bet no iekšpuses tie ir plēsīgi vilki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Pēc viņu augļiem jums tos būs pazīt. Kas var lasīt vīnogas no ērkšķiem, jeb vīģes no dadžiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Tāpat ikkatrs labs koks nes labus augļus, bet nelāga koks nes nelabus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Labs koks nevar nest nelabus augļus, un nelāga koks nevar nest labus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Ikkatrs koks, kas nenes labus augļus, top nocirsts un ugunī iemests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Tāpēc pēc viņu augļiem jums tos būs pazīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ne ikkatrs, kas uz Mani saka: Kungs! Kungs! ieies Debesu valstībā; bet tas, kas Mana debes\'Tēva prātu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Daudzi uz Mani sacīs tanī dienā: Kungs! Kungs! Vai mēs Tavā vārdā neesam nākošas lietas sludinājuši? Vai mēs Tavā vārdā neesam velnus izdzinuši? Vai mēs Tavā vārdā neesam daudz varenus darbus darījuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Un tad Es tiem it skaidri sacīšu: Es nekad jūs neesmu pazinis; ejat nost no Manis, jūs ļaundarītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Tāpēc ikvienu, kas šos Manus vārdus dzird un dara, to Es līdzināšu kādam gudram vīram, kas savu namu uztaisījis uz klints kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Kad nu stiprs lietus lija un straumes nāca un vēji pūta un piesitās pie tā nama, tad tas tomēr neapgāzās; jo tas bija uztaisīts uz klints.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Un ikviens, kas šos Manus vārdus dzird un nedara, tas taps līdzināts ģeķim, kas savu namu uztaisījis uz smiltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Kad nu stiprs lietus lija un straumes nāca un vēji pūta un sitās pie tā nama, tad tas apgāzās un gāja viss postā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Un notikās, kad Jēzus šos vārdus bija beidzis, tad tie ļaudis izbrīnījās par Viņa mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Jo Viņš tos mācīja tā kā pats varenais, un nekā tie rakstu mācītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Un kad Viņš no kalna nogāja, tad daudz ļaužu Viņam staigāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Un redzi, viens spitālīgs vīrs nāca, un Viņa priekšā metās zemē un sacīja: “Kungs, ja Tu gribi, Tu mani gan vari šķīstīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Un Jēzus roku izstiepis viņu aizskāra un sacīja: “Es to gribu, topi šķīsts!” Un tūdaļ tas tapa šķīsts no savas spitālības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Un Jēzus uz to sacīja: “Pielūko un nesaki to nevienam, bet noej un rādies priesterim un upurē to dāvanu, ko Mozus pavēlējis, tiem par liecību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Bet kad Jēzus Kapernaūmā iegāja, tad viens virsnieks nāca pie Viņa, To lūdza');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Un sacīja: “Kungs, mans kalps guļ melmeņu sērdzīgs mājās un cieš lielas mokas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Un Jēzus uz to sacīja: “Es gribu nākt un to veselu darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Un tas virsnieks atbildēja un sacīja: “Kungs, es neesmu cienīgs, ka Tu nāci apakš mana jumta, bet saki vienu vārdu, tad mans kalps kļūs vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Jo arī es esmu cilvēks apakš valdīšanas, un apakš manis ir karavīri; un kad es vienam saku: Ej! Tad viņš iet, - un otram: Nāc šurp! Tad viņš nāk, - un savam kalpam: Dari to! Tad viņš dara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Kad Jēzus to dzirdēja, tad Viņš brīnījās un sacīja uz tiem, kas Viņam staigāja pakaļ: “Patiesi, Es jums saku, ka iekš Israēla Es neesmu atradis tādu ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Bet Es jums saku, ka daudzi nāks no rīta un no vakara puses un sēdēs ar Ābrahāmu, Īzaku un Jēkabu Debesu valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Bet tie valstības bērni taps izstumti galējā tumsībā; tur būs kaukšana un zobu trīcēšana.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Un Jēzus sacīja uz to virsnieku: “Ej, lai tev notiek, kā tu ticējis.” Un viņa kalps palika vesels tanī pašā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Un Pētera namā nācis, Jēzus redzēja viņa sievas māti ar drudzi guļam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Un Tas satvēra viņas roku, tad drudzis no viņas atstājās, un viņa uzcēlusies tiem kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Un kad vakars metās, tad tie atveda pie Viņa daudz velna apsēstus, un Viņš izdzina tos garus caur vārdu un dziedināja visus sērdzīgos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Ka piepildītos, ko pravietis Jesaja runājis sacīdams: “Viņš ņēma uz sevi mūsu vājības un nesa mūsu sērgas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Bet lielus ļaužu pulkus pie Sevis redzēdams, Jēzus pavēlēja uz otru malu pārcelties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Un viens rakstu mācītājs atnāca un uz Viņu sacīja: “Mācītāj, es Tev iešu pakaļ, kurp Tu iesi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Un Jēzus uz to sacīja: “Lapsām ir alas un putniem apakš debess ir ligzdas, bet Tam Cilvēka Dēlam nav, kur likt Savu galvu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Un cits no Viņa mācekļiem uz Viņu sacīja: “Kungs, vēli man papriekš noiet un aprakt savu tēvu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Bet Jēzus uz to sacīja: “Nāc Man pakaļ, un lai miroņi savus miroņus paši aprok.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Un Viņš iekāpa laivā un Viņa mācekļi Viņam gāja līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Un redzi, liela vētra pacēlās jūrā, ka laiva viļņiem tapa pārņemta, un Viņš gulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Un tie mācekļi piegājuši Viņu modināja un sacīja: “Kungs, palīdzi mums, mēs grimstam!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Un Viņš uz tiem sacīja: “Jūs mazticīgie, kam esat tik bailīgi?” Un Viņš cēlās, apsauca vēju un jūru, tad palika it klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Bet tie cilvēki brīnīdamies sacīja: “Kas Tas tāds, ka vēji un jūra Tam paklausa?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Un otrā jūrmalā nākot Ģerģesiešu tiesā Viņu sastapa divi velna apsēsti, no kapiem nākdami, ļoti nikni, tā ka neviens nedrīkstēja pa to ceļu staigāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Un redzi, tie brēkdami sacīja: “Kas mums ar Tevi, Jēzu, Tu Dieva Dēls? Vai Tu esi nācis priekšlaikus, mūs mocīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Bet tālu no viņiem bija liels cūku pulks ganībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Un tie velni Viņam lūdza un sacīja: “Ja Tu mūs izdzen, tad atvēli mums, ieskriet tai cūku pulkā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Un Viņš uz tiem sacīja: “Ejat!” Un izbēguši tie ieskrēja tai cūku pulkā, un redzi, viss cūku pulks iegāzās no kraujas jūrā un noslīka ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Un tie gani bēga un nākuši pilsētā pasludināja visu to un, kas ar tiem apsēstiem bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Un redzi, visa pilsēta izgāja Jēzum pretī. Un kad tie Viņu redzēja, tad tie lūdza, ka Viņš aizietu no viņu robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Un laivā kāpis Viņš cēlās pāri un nāca Savā pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Un lūk, pie Viņa atnesa melmeņu sērdzīgu, tas gulēja gultā. Kad nu Jēzus redzēja viņu ticību, tad Viņš sacīja uz to melmeņu sērdzīgo: “Ņemies drošu sirdi, Mans dēls, tavi grēki tev piedoti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Un lūk, kādi no tiem rakstu mācītājiem runāja paši pie sevis: “Šis zaimo Dievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Un Jēzus redzēja viņu domas un sacīja: “Kāpēc jūs domājiet ļaunu savās sirdīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Kas ir vieglāki? Vai sacīt: “Tev tavi grēki top piedoti,” Vai sacīt: “Celies un staigā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Bet lai jūs zināt, Tam Cilvēka Dēlam varu esam virs zemes grēkus piedot,” (tad Viņš uz to melmeņu sērdzīgo sacīja:) “Celies, ņem savu gultu un ej uz mājām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Un viņš cēlās un gāja mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Kad tie ļaudis to redzēja, tad tie brīnījās un teica Dievu, kas tādu varu cilvēkiem devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Un kad Jēzus no turienes aizgāja, tad Viņš redzēja vienu cilvēku pie muitas būdas sēžam, vārdā Mateju (jeb: Levi), un uz to sacīja: “Nāc Man pakaļ.” Un tas cēlās un gāja Viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Un notikās, Tam pie galda sēžot viņa namā, redzi, daudz muitnieku un grēcinieku nāca un sēdēja līdz ar Jēzu un Viņa mācekļiem pie galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Kad tie farizeji to redzēja, tad tie sacīja uz Viņa mācekļiem: “Kāpēc jūsu mācītājs ēd ar muitniekiem un grēciniekiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Bet to dzirdējis Jēzus uz tiem sacīja: ‘Veseliem ārsta nevajag, bet neveseliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Tad ejat nu un mācaties, kas tas ir: “Man patīk žēlastība un ne upuris!” Jo Es neesmu nācis, taisnus aicināt pie atgriešanās no grēkiem, bet grēciniekus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Tad Jāņa mācekļi pie Viņa nāca un sacīja: “Kāpēc mēs un tie farizeji tik daudz gavējam, un Tavi mācekļi negavē?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Un Jēzus uz tiem sacīja: “Vai kāzu ļaudis var bēdāties, kamēr brūtgāns pie viņiem? Bet nāks dienas, kad tas brūtgāns viņiem būs atņemts, un tad tie gavēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Un neviens nelāpa vecas drēbes ar jaunas vadmalas ielāpu, jo tas ielāps noplīst no tām drēbēm un plīsums paliek lielāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Un jaunu vīnu nelej vecos ādas traukos, citādi tie trauki plīst, un vīns izgāžas, un tie trauki iet bojā. Bet jaunu vīnu lej jaunos traukos, tad abi kopā paliek veseli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Un Viņam ar tiem tā runājot, redzi, viens virsnieks nāca un Viņa priekšā metās zemē un sacīja: “Mana meita nupat nomirusi, bet nāc un liec Savu roku uz viņu, tad tā taps dzīva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Un Jēzus piecēlies gāja tam pakaļ ar Saviem mācekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, '(Un redzi, viena sieva, kas divpadsmit gadus bijusi asins sērdzīga, nāca no aizmugures un aizskāra Viņa drēbju vīli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Jo tā sacīja pati pie sevis: “Kaut vien Viņa drēbes varētu aizskart, tad es paliktu vesela.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Tad Jēzus atgriezās un to ieraudzījis sacīja: “Ņemies drošu sirdi, Mana meita! Tava ticība tev palīdzējusi.” Un tā sieva palika vesela tanī pašā stundā.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Kad nu Jēzus tā virsnieka namā nāca un redzēja tos stabulniekus un to ļaužu troksni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Tad Viņš uz tiem sacīja: “Atkāpjaties! Jo tā meitene nav mirusi, bet guļ.” Bet tie par Viņu smējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Bet kad tas ļaužu pulks bija izdzīts, tad Viņš gāja iekšā un to satvēra pie rokas. Tad tā meitiņa cēlās augšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Un šī slava tapa daudzināta pa visu to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Un kad Jēzus no turienes aizgāja, tad divi akli Viņam nāca pakaļ brēkdami un sacīdami: “Tu Dāvida dēls, apžēlojies par mums!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Un Viņam namā ieejot tie aklie piestājās, un Jēzus uz tiem sacīja: “Vai jūs ticat, ka Es spēju to darīt?” Tie uz Viņu sacīja: “Ticam gan, Kungs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Tad Tas aizskāra viņu acis sacīdams: “Lai jums notiek pēc jūsu ticības.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Un viņu acis tapa atvērtas. Un Jēzus tiem stipri aizliedza un sacīja: “Pielūkojiet, ka neviens to nedabū zināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Bet tie aizgājuši Viņu izslavēja pa visu to zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Kad nu tie bija aizgājuši, redzi, tad pie Viņa atnesa cilvēku, kas bija mēms un velna apsēsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Un kad velns bija izdzīts, tad tas mēmais runāja. Un tie ļaudis brīnījās un sacīja: “Tas vēl nekad iekš Israēla nav redzēts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Bet tie farizeji sacīja: “Viņš izdzen velnus caur velnu virsnieku.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Un Jēzus gāja apkārt pa visām pilsētām un miestiem, mācīdams viņu baznīcās un sludinādams to priecas mācību no Tās Valstības un dziedinādams tiem ļaudīm visas sērgas un visas vājības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Un kad Viņš tos ļaužu pulkus redzēja, tad Viņam sirds par tiem iežēlojās, jo tie bija izklīduši un pamesti, kā avis, kam nav gana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tad Viņš uz Saviem mācekļiem sacīja: “Pļaujama gan daudz, bet maz pļāvēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Tāpēc lūdziet tā pļaujamā Kungu, lai izdzen strādniekus Savā pļaujamā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Un Savus divpadsmit mācekļus pieaicinājis, Viņš tiem deva varu pār nešķīstiem gariem, tos izdzīt un dziedināt visas sērgas un visas vājības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Bet to divpadsmit apustuļu vārdi ir šie: tas pirmais Sīmanis, kas top saukts Pēteris, un Andrejs, viņa brālis; Jēkabs, Cebedeja dēls, un Jānis, viņa brālis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filips un Bērtulis, Toms un Matejs, tas muitnieks, Jēkabs, Alfeja dēls, un Lebejs ar pavārdu Taddejs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Sīmanis no Kānas un Jūdas Iskariots, kas Viņu arī nodeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Šos divpadsmit Jēzus izsūtīja, tiem pavēlēdams un sacīdams: “Nenoejat uz pagānu ceļu un neieejat Samariešu pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Bet ejat visvairāk pie tām pazudušām avīm no Israēla cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Bet izgājuši pasludiniet un sakiet: “Debesu valstība ir tuvu klāt nākusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Dziedinājiet sērdzīgus, šķīstiet spitālīgus, uzmodinājiet mirušus, izdzeniet velnus. Bez maksas to esat dabūjuši, bez maksas to dodiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Neiegādājieties zelta nedz sudraba nedz vara savās jostās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ne kulīti uz ceļu, nedz divus svārkus, nedz kurpes, nedz zizli, jo strādniekam sava barība nākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Un kurā pilsētā jeb miestā jūs nāksiet, izmeklējat, kas tur vērts, un tur paliekat, tiekams jūs no turienes iziesiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Un namā iegājuši sveicināt to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Un ja tas nams ir vērts, tad jūsu miers pār to nāks, bet ja tas nav vērts, tad jūsu miers pie jums atkal atgriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Un ja kas laban jūs negrib uzņemt nedz klausīt jūsu vārdus, tad izejat no tā nama vai no tās pilsētas, un nokratiet pīšļus no savām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Patiesi, Es jums saku: “Sodomas un Gomoras zemei vieglāki nāksies soda dienā nekā tādai pilsētai.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Redzi, Es jūs sūtu kā avis vilku starpā; tāpēc esat gudri kā čūskas un bez viltus kā baloži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Bet sargājaties no cilvēkiem, jo tie jūs nodos savās tiesās un jūs šaustīs savās baznīcās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Un jūs tapsiet vesti Manis dēļ valdnieku un ķēniņu priekšā, viņiem un tiem pagāniem par liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Kad tie nu jūs nodos, tad nebēdājaties, kā un ko jūs runāsiet, jo tanī pašā stundā jums taps dots, kas jums jārunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Jo jūs neesat tie runātāji, bet jūsu Tēva Gars ir tas runātājs iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Bet tur brālis brāli nodos pie nāves un tēvs dēlu; un bērni celsies pret vecākiem un tos nonāvēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Un jūs būsiet ienīdēti no visiem Mana Vārda dēļ. Bet kas pastāv līdz galam, tas taps izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Bet kad tie jūs vajā šinī pilsētā, tad bēgat uz citu. Patiesi, Es jums saku: jūs nebūsiet vēl izstaigājuši Israēla pilsētas, tiekams Tas Cilvēka Dēls nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Māceklis nav augstāks pār savu mācītāju, nedz kalps pār savu kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Tas ir māceklim gan, kad tas top kā viņa mācītājs, un kalps kā viņa kungs; kad tie to nama kungu saukuši (par) Belcebulu, tad jo vairāk viņa saimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Tāpēc nebīstaties no tiem. Jo nekas nav apslēpts, kas nenāks gaismā, nedz slepens, kas netaps zināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Ko Es jums saku tumsībā, to runājat gaismā; un kas jums klusiņām sacīts ausi, to sludinājiet uz jumtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Un nebīstaties no tiem, kas miesu nokauj un dvēseli nevar nokaut; bet bīstaties vairāk no tā, kas miesu un dvēseli var nomaitāt ellē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Vai divi zvirbuļi netop pirkti par vienu artavu? Un neviens no tiem nekrīt zemē bez jūsu Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Bet arī jūsu galvas mati visi ir skaitīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Tāpēc nebīstaties: jūs esat labāki nekā daudz zvirbuļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Tad nu ikkatru, kas Mani apliecinās cilvēku priekšā, to arī Es apliecināšu Sava Tēva priekšā, kas ir debesis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Bet kas Mani aizliegs cilvēku priekšā, to Es arīdzan aizliegšu Sava Tēva priekšā, kas ir debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Nedomājiet, ka Es esmu nācis, mieru atnest virs zemes; Es neesmu nācis, mieru atnest, bet zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Es esmu nācis, cilvēku savest ienaidā ar viņa tēvu, un meitu ar viņas māti, un vedeklu ar viņas vīra māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Un cilvēka ienaidnieki būs viņa paša mājas ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kas tēvu un māti vairāk mīļo nekā Mani, tas Manis nav vērts, un kas dēlu vai meitu vairāk mīļo nekā Mani, tas Manis nav vērts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Un kas savu krustu uz sevi neņem un Man neiet pakaļ, tas Manis nav vērts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kas savu dzīvību atrod, tam tā zudīs, un kam Manis dēļ dzīvība zūd, tas to atradīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kas jūs uzņem, tas Mani uzņem, un kas Mani uzņem, tas uzņem To, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kas pravieti uzņem pravieša vārdā, tas pravieša algu dabūs; un kas taisnu uzņem taisnā vārdā, tas taisnā algu dabūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Un kas vienu no šiem vismazākiem dzirdinās tikai ar vienu biķeri auksta ūdens, tāpēc ka tam ir mācekļa vārds, patiesi, Es jums saku, tam sava alga nezudīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Un notikās pēc tam, kad Jēzus Saviem divpadsmit mācekļiem tās pavēles bija devis, tad Viņš no turienes aizgāja, mācīt un sludināt viņu pilsētās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Un kad Jānis cietumā par Kristus darbiem dzirdēja, tad viņš sūtīja divus no saviem mācekļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Un tam lika sacīt: “Vai Tu esi Tas, kam būs nākt, jeb vai mums būs citu gaidīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Un Jēzus atbildēja un uz tiem sacīja: “Noejat un atsakāt Jānim, ko jūs dzirdat un redzat:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Akli redz, tizli iet, spitālīgi top šķīsti, kurli dzird, miroņi ceļas augšām, un nabagiem prieka vēsts top sludināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Un svētīgs ir, kas pie Manis neapgrēcinās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Kad tie nu aizgāja, tad Jēzus iesāka runāt uz tiem ļaudīm par Jāni: “Ko jūs esat izgājuši tuksnesī skatīties? Vai kādu niedri, ko vējš šurpu turpu šauba?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Jeb ko jūs esat izgājuši redzēt? Vai kādu cilvēku mīkstās drēbēs? Redziet, kas mīkstas drēbes valkā, tie ir ķēniņu namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Jeb ko jūs esat izgājuši redzēt? Vai kādu pravieti? Tiešām, Es jums saku, tas arī augstāks nekā pravietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Jo šis ir tas, par ko rakstīts: “Redzi, Es sūtu Savu eņģeli Tavā priekšā, kam ceļu priekš Tevis būs sataisīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Patiesi, Es jums saku: “No tiem, kas no sievām dzimuši, neviens nav cēlies, kas lielāks nekā Jānis, tas Kristītājs; bet tas mazākais Debesu valstībā ir lielāks pār viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Bet no Jāņa tā Kristītāja laika līdz tagad Debesu valstībā ar varu laužas iekšā; un tie varas darītāji to rauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Jo visi pravieši un bauslība līdz Jānim sludinājuši par to, kas bija nākams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Un ja jūs gribat pieņemt: viņš ir Elija, kam bija jānāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kam ausis dzirdēt, tas lai dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Bet kam Es šo cilti līdzināšu? Tā ir līdzinājama bērniem, kas sēž uz tirgus un sauc uz saviem biedriem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Un saka: “Mēs jums stabulējuši un jūs neesat dejojuši, mēs jums raudu dziesmas dziedājuši, un jūs neesat raudājuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Ja Jānis ir nācis, ne ēdis, ne dzēris; un tie saka: “Viņam ir velns.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Tas Cilvēka Dēls ir nācis, ēd un dzer; un tie saka: “Redzi, kāds rijējs un vīna plītnieks, muitnieku un grēcinieku draugs;” un gudrība top taisnota no saviem bērniem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tad Viņš iesāka tās pilsētas rāt, kur Viņa brīnumi visvairāk bija notikuši, ka tās no grēkiem nebija atgriezušās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '“Vai tev, Horacin! Vai tev, Betsaida! Jo kad Tirū vai Sidonā tie brīnumi būtu notikuši, kas pie jums notikuši, tad tie jau sen no grēkiem būtu atgriezušies maisos un pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Tomēr Es jums saku, ka Tirum un Sidonai vieglāki būs soda dienā, nekā jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Un tu Kapernaūma, kas līdz debesīm esi paaugstināta, tu līdz ellei tapsi nogāzta; jo kad Sodomā tie brīnumi būtu notikuši, kas iekš tevis notikuši, tad viņa vēl šodien stāvētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Tomēr Es jums saku, ka Sodomas zemei vieglāki būs soda dienā, nekā tev.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Tanī pašā laikā Jēzus atbildēja un sacīja: “Es Tev pateicos, Tēvs, debesu un zemes Kungs, ka Tu šīs lietas esi slēpis gudriem un prātniekiem, un tās esi zināmas darījis bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Patiesi, Tēvs, jo tā Tavs labais prāts ir noticis Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Visas lietas Man ir iedotas no Mana Tēva, un neviens nepazīst To Dēlu, kā vien Tas Tēvs, un neviens nepazīst To Tēvu kā vien Tas Dēls, un kam Tas Dēls to grib darīt zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Nāciet šurp pie Manis visi, kas esat bēdīgi un grūtsirdīgi, Es jūs gribu atvieglināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Ņemiet uz sevi Manu jūgu un mācaties no Manis; jo Es esmu lēnprātīgs un no sirds pazemīgs; tad jūs atradīsiet atvieglošanu savām dvēselēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Jo Mans jūgs ir laipnīgs, un Mana nasta viegla.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Tanī laikā Jēzus staigāja svētdienā caur labību; un Viņa mācekļi bija izsalkuši un sāka vārpas plūkt un ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Bet tie farizeji, to redzēdami, uz Viņu sacīja: “Redzi, Tavi mācekļi dara, ko svētdienā darīt nav brīvi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Un Viņš uz tiem sacīja: “Vai jūs neesat lasījuši, ko Dāvids darījis, kad viņš bija izsalcis līdz ar tiem, kas pie viņa bija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Ka viņš ir Dieva namā gājis un tās noliktās maizes ēdis, ko ēst nebija brīvi, ne viņam, ne tiem, kas pie viņa bija, bet priesteriem vien?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Jeb vai jūs bauslībā neesat lasījuši, ka priesteri svētdienās svētdienu Dieva namā pārkāpj un ir nevainīgi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Bet Es jums saku, ka Tas kas šeitan, ir lielāks, nekā tas Dieva nams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Bet kad jūs zinātu, kas tas ir: “Man patīk sirds žēlastība un ne upuris,” tad jūs šos nevainīgos nebūtu notiesājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Jo Tas Cilvēka Dēls ir arī svētdienas kungs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Un Viņš no turienes izgājis nāca viņu baznīcā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Un redzi, tur bija cilvēks, tam bija sakaltusi roka, un tie Viņam vaicāja, sacīdami: “Vai brīvi svētdienā dziedināt?” Ka tie Viņu apsūdzētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Bet Viņš uz tiem sacīja: “Kurš cilvēks būs jūsu starpā, kam ir viena avs, un kad tā svētdienā iekrīt bedrē, vai tas to nesatvers un neizvilks ārā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Vai tad nu cilvēks nav daudz labāks, nekā avs? Tāpēc ir brīvi, svētdienā labu darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Tad Viņš uz to cilvēku sacīja: “Izstiepi savu roku!” Un viņš to izstiepa. Tad tā viņam palika atkal vesela kā tā otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Tad tie farizeji izgāja un aprunājās pret Viņu, kā tie To nomaitātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Bet Jēzus to nomanīdams aizgāja no turienes. Un daudz ļaužu Viņam gāja pakaļ, un Viņš tos visus dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Un Viņš tiem piekodināja, ka tie Viņu nedarītu zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Ka piepildītos, ko pravietis Jesaja runājis, sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '“Redzi, Mans kalps, ko Es izredzējies, un Mans mīļais, pie kā Manai dvēselei labs prāts; Es likšu uz Viņu Savu Garu, un Tas pasludinās tautām tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ne Viņš bārsies, ne brēks, un neviens nedzirdēs uz ielām Viņa balsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Ielūzušu niedri Viņš nesalauzīs, un kvēlošu dakti Viņš neizdzēsīs, tiekams Viņš tiesai dos uzvarēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Un tautas cerēs uz Viņa vārdu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Tad viens velna apsēsts pie Viņa tapa novests, akls un mēms būdams. Un Viņš to darīja veselu, tā ka tas aklais un mēmais runāja un redzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Un visi ļaudis iztrūkās un sacīja: “Vai Šis nav Dāvida dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Bet tie farizeji to dzirdēdami, sacīja: “Šis velnus neizdzen, kā tik vien caur Belcebulu, velnu virsnieku.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Bet Jēzus viņu domas nomanījis, uz tiem sacīja: “Ikviena valsts, kas savā starpā ienaidā, tā aiziet postā, un ikkatra pilsēta vai nams, kas savā starpā ienaidā, nevar pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Ja nu sātans sātanu izdzen, tad viņš ir ienaidā ar sevi pašu; kā tad viņa valsts var pastāvēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Un ja Es caur Belcebulu velnus izdzenu, caur ko tad jūsu bērni tos izdzen? Tāpēc tie būs jūsu tiesātāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Bet ja Es caur Dieva Garu velnus izdzenu, tad Deva valstība jau pie jums atnākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Jeb kā kas var ieiet tā stiprā namā un paņemt viņa lietas, ja tas papriekš to stipro nesaista? Un tad tas viņa namu aplaupīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kas nav ar Mani, tas ir pret Mani, un kas ar Mani nesakrāj, tas izkaisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Tāpēc Es jums saku: ikkatru grēku un ikkatru zaimošanu cilvēkiem piedos, bet Tā Gara zaimošana cilvēkiem netaps piedota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Un kas ko runā pret To Cilvēka Dēlu, tam tas taps piedots; bet kas ko runā pret Svēto Garu, tam netaps piedots nedz šinī, nedz nākošā mūžā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ņemiet labu koku, tad arī viņa augļi būs labi, vai ņemiet nelāga koku, tad arī tie augļi būs nelabi; jo koks top pazīts pie saviem augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Jūs odžu dzimums, kā jūs varat ko laba runāt, ļauni būdami? Jo no sirds pilnības mute runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Labs cilvēks no labas sirds mantas izdod labu, un ļauns cilvēks no ļaunas mantas izdod ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Bet Es jums saku, ka par ikkatru veltīgu vārdu, ko cilvēki runās, tiem būs jāatbild soda dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Jo pēc saviem vārdiem tu tapsi taisnots, un pēc saviem vārdiem tu tapsi pazudināts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tad kādi no rakstu mācītājiem un farizejiem atbildēja un sacīja: “Mācītāj, mēs no tevis kādu zīmi gribam redzēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Bet Viņš atbildēja un uz tiem sacīja: “Nikna un laulību pārkāpēja tauta meklē zīmi; un viņai nekāda zīme netaps dota, kā vien pravieša Jonas zīme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Jo kā Jona trīs dienas un trīs naktis bija lielas jūras zivs vēderā, tā arī Tas Cilvēka Dēls trīs dienas un naktis būs zemes klēpī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Ninivieši celsies soda dienā pret šo cilti un to pazudinās; jo tie no grēkiem ir atgriezušies uz Jonas sludināšanu, un redzi, šeit ir vairāk, nekā Jona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Tā ķēniņiene no dienvidu puses celsies soda dienā pret šo cilti un to pazudinās; jo tā no pasaules gala ir nākusi, Salamana gudrību dzirdēt; un redzi, šeit ir vairāk nekā Salamans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Bet kad tas nešķīstais gars no cilvēka izgājis, tad tas pārstaigā sausas vietas un meklē dusu, un to neatrod.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Tad tas saka: es gribu atpakaļ griezties uz savu namu, no kurienes es izgājis; un kad viņš nāk, tad tas to atrod tukšu, ar slotām mēztu un izpušķotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Tad tas noiet un ņem pie sevis septiņus garus, kas jo niknāki nekā viņš pats, un tur iekšā nākuši tie tur dzīvo, un pēc ar to cilvēku paliek niknāki nekā papriekš. Tāpat arī notiks šai ļaunai tautai.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Un Viņam tā uz tiem ļaudīm vēl runājot, redzi, Viņa māte un viņa brāļi stāvēja ārā, meklēdami viņu bildināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Un kāds uz Viņu sacīja: “Redzi, Tava māte un Tavi brāļi stāv ārā, meklēdami Tevi bildināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Un Viņš atbildēdams sacīja tam, kas Viņam to teica: “Kas ir Mana māte, un kas ir Mani brāļi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Un Savu roku izstiepis pār Saviem mācekļiem, Viņš sacīja: “Redzi, Mana māte un Mani brāļi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Jo kas Mana debesu Tēva prātu darīs, tas ir Mans brālis un Mana māsa un Mana māte.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Tanī dienā Jēzus no nama izgājis, apsēdās jūrmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Un daudz ļaužu pie viņa sapulcējās, tā ka Viņš laivā iekāpis tur atsēdās, un visi tie ļaudis stāvēja malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Un Viņš uz tiem daudz runāja caur līdzībām un sacīja: “Redzi, sējējs izgāja sēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Un viņam sējot cita sēkla krita ceļmalā; un putni nāca un to apēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Un cita krita uz akmenāju, kur tai nebija daudz zemes; un tā tūdaļ uzdīga, tāpēc ka tai nebija dziļas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Bet kad saule bija uzlēkusi, tad tā savīta un nokalta, tāpēc ka viņai nebija saknes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Bet cita krita starp ērkšķiem, un ērkšķi uzauga un to apmāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Bet cita krita uz labu zemi un nesa augļus, cita simtkārtīgus un cita sešdesmitkārtīgus un cita trīsdesmitkārtīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kam ausis dzirdēt, tas lai dzird.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Un tie mācekļi piegājuši uz Viņu sacīja: “Kādēļ Tu uz tiem runā caur līdzībām?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Bet Viņš atbildēja un uz tiem sacīja: “Jums ir dots zināt Dieva valstības noslēpumus, bet tiem tas nav dots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Jo kam ir, tam taps dots, un tam būs pārlieku; bet kam nav, no tā taps atņemts arī tas, kas tam ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Tāpēc Es uz tiem runāju caur līdzībām, lai tie redzēdami neredz, un dzirdēdami nedzird, nedz saprot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Un pie tiem pravieša Jesajas vārdi piepildās, kas saka: “Ausīm jūs dzirdēsiet, bet nesapratīsiet; un redzēdami jūs redzēsiet, bet nenomanīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Jo šo ļaužu sirds ir palikusi cieta, un ar ausīm tie ir pakurli un savas acis tie aizdarījuši, ka tie acīm neredz un ausīm nedzird un sirdī nesaprot, un neatgriežas, ka Es tos dziedinātu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Bet svētīgas ir jūsu acis, jo tās redz, un jūsu ausis, jo tās dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Jo patiesi, Es jums saku, ka daudz pravieši un taisni ir vēlējušies redzēt, ko jūs redzat, un nav redzējuši, un dzirdēt, ko jūs dzirdat, un nav dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Tad nu klausāties jūs to līdzību par to sējēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Kad kas to vārdu par to valstību dzird un neprot, tad nāk tas ļaunais un rauj to nost, kas viņa sirdī ir sēts. Šis ir tas, kas sēts ceļmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Bet kas uz akmenāju sēts, ir tas, kas to vārdu dzird, un tūdaļ to ar prieku saņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Bet viņam nav saknes iekš sevis, un viņš ir nepastāvīgs. Kad nu bēdas uziet un vajāšana tā vārda dēļ, tad viņš tūdaļ ņem apgrēcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Bet kas starp ērkšķiem sēts, ir tas, kas to vārdu dzird, un šīs pasaules zūdīšanās un bagātības viltība apslāpē to vārdu, un tas nenes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Bet kas uz labu zemi sēts, ir tas, kas to vārdu dzird un saprot un turklāt nes augļus, cits simtkārtīgus un cits sešdesmitkārtīgus un cits trīsdesmitkārtīgus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Vēl citu līdzību Viņš tiem stāstīja un sacīja: “Debesu valstība ir kā kāds cilvēks, kas labu sēklu sēja savā tīrumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Bet ļaudīm guļot viņa ienaidnieks nāca un iesēja niknu zāli kviešu starpā un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Kad nu labība auga un vārpās metās, tad tā niknā zāle arīdzan rādījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Tad tie kalpi gāja pie tā nama tēva un uz to sacīja: “Kungs, vai tu neesi sējis labu sēklu savā tīrumā? No kurienes tad tā niknā zāle rodas?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Un viņš uz tiem sacīja: “To tas ienaidnieks darījis.” Tad tie kalpi uz to sacīja: “Vai tad tu gribi, ka mēs ejam, to izravēt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Viņš sacīja: “Nē, ka jūs, to nikno zāli izravēdami, neizplūcat ir tos kviešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Lai aug abi kopā līdz pļaujamam laikam; un pļaujamā laikā es sacīšu tiem pļāvējiem: “Sakrājiet kopā papriekš to nikno zāli un sieniet to kūlīšos, lai tā top sadedzināta; bet tos kviešus sakrājiet manā šķūnī.”””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Vēl citu līdzību Viņš tiem stāstīja un sacīja: “Debesu valstība līdzinājās sinepju graudiņam, ko cilvēks ņēmis savā laukā iesēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Šī gan ir tā mazākā starp visām sēklām, bet kad tā uzaug, tad tā ir lielāka pār citiem dārza stādiem un paliek par koku, tā ka tie putni apakš debess nāk un ligzdas taisa viņa zaros.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Vēl citu līdzību Viņš tiem sacīja: “Debesu valstība līdzinājās raugam, ko sieva ņēmusi iejauca trīs mēros miltu, tiekams viss sarūga.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Visu to Jēzus runāja caur līdzībām uz tiem ļaudīm, un bez līdzībām Viņš uz tiem nerunāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Lai piepildītos, ko tas pravietis runājis sacīdams: “Es Savu muti atdarīšu līdzībās, Es izrunāšu lietas, kas no pasaules iesākuma apslēptas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Tad Jēzus tos ļaudis atlaida un pārgāja mājās, un Viņa mācekļi pie Tā piegāja un sacīja: “Izstāsti mums to līdzību par to nikno zāli tīrumā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Un Viņš atbildēja un uz tiem sacīja: “Tas, kas to labo sēklu sēj, ir Tas Cilvēka Dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Bet tas lauks ir pasaule, un tā labā sēkla ir tie valstības bērni, un tā niknā zāle ir tā ļaunā bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Un tas ienaidnieks, kas to sējis, ir velns, un tas pļaujamais laiks ir šīs pasaules pastara gals, un tie pļāvēji ir tie eņģeļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Tad nu tā kā tā niknā zāle top salasīta un ugunī sadedzināta, tā arī notiks šīs pasaules pastara galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Tas Cilvēka Dēls sūtīs savus eņģeļus, un tie salasīs no Viņa valstības visas apgrēcības un tos, kas dara netaisnību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'Un tos metīs degošā ceplī; tur būs raudāšana un zobu trīcēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Tad tie taisnie spīdēs kā saule sava Tēva valstībā. Kam ausis dzirdēt, tas lai dzird!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Vēl Debesu valstība ir kā tīrumā apslēpta manta, ko cilvēks atradis apslēpa, un priecādamies par to, noiet un pārdod visu, kas tam ir, un pērk šo tīrumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Vēl Debesu valstība ir līdzinājama tirgotājam, kas labas pērles meklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Un atradis vienu it dārgu pērli, nogāja un pārdeva visu, kas tam bija, un to nopirka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Vēl Debesu valstība līdzinājās tīklam, jūrā izmestam, kas visādas zivis savilka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Un kad tas bija pilns, tad tie to pie malas vilkuši un apsēdušies, tās labās ir salasījuši traukos, bet tās sapuvušās metuši ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Tā tas būs pasaules pastara galā; tie eņģeļi izies un atšķirs ļaunos no taisniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'Un tos metīs degošā ceplī; tur būs raudāšana un zobu trīcēšana.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Jēzus uz tiem saka: “Vai jūs to visu esat sapratuši?” Tie uz Viņu sacīja: “Esam gan, Kungs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Tad Viņš uz tiem sacīja: “Tāpēc ikkatrs rakstu mācītājs, uz Debesu valstību mācīts, ir līdzīgs nama kungam, kas no savas mantas izdod jaunas un vecas lietas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Un notikās, kad Jēzus šīs līdzības bija beidzis, tad Viņš aizgāja no turienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Un savā tēva pilsētā nācis, Viņš tos mācīja viņu baznīcā, tā ka tie iztrūcinājās un sacīja: “Kur Šim nāk tāda gudrība un tāds spēks?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Vai Šis nav tā amatnieka dēls? Vai Viņa māte netop saukta Marija un Viņa brāļi Jēkabs un Jāzeps un Sīmanis un Jūda?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Un vai nav visas Viņa māsas pie mums? Kur tad Šis visu to dabūjis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Un tie ņēma apgrēcību pie Viņa. Bet Jēzus uz tiem sacīja: “Pravietis nekur netop mazāki cienīts nekā savā tēva zemē un savās mājās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Un Viņš tur nedarīja daudz brīnumus viņu neticības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Tanī laikā Hērodus, viens no tiem četriem Jūdu zemes valdniekiem, dzirdēja to slavu par Jēzu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Un sacīja uz saviem kalpiem: “Šis ir Jānis, tas Kristītājs; tas ir uzmodināts no miroņiem, tāpēc tas spēj šos brīnumus darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Jo Hērodus Jāni bija saņēmis, viņu sējis un cietumā licis Hērodeijas dēļ, kura bija Filipa, viņa brāļa, sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Jo Jānis uz viņu bija sacījis: “Tas tev nepieklājās, ka viņa tev ir.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Un viņš gribēja to nokaut, bet bijās no tiem ļaudīm, jo tie to turēja par pravieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Bet, kad Hērodus dzimšanas diena tapa turēta, tad Hērodeijas meita dejoja viņu priekšā un patika Hērodum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Tāpēc tas zvērēdams viņai solīja, ka gribot dot, ko viņa lūgšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Un viņa, no savas mātes papriekš pamācīta, sacīja: “Dod man šeit bļodā Jāņa, tā Kristītāja, galvu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Tad ķēniņš noskuma; bet tās zvērēšanas dēļ un to dēļ, kas līdz pie galda sēdēja, viņš pavēlēja, to dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Un aizsūtījis cietumā, nocirta Jānim galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Un viņa galva tapa bļodā atnesta un tai meitenei dota; un viņa to nonesa savai mātei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Un viņa mācekļi nāca, ņēma tās miesas un tās apraka; un nāca un to pasludināja Jēzum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Un to dzirdējis, Jēzus no turienes aizbrauca ar laivu savrup uz kādu tukšu vietu, un tie ļaudis to dzirdējuši, Viņam no tām pilsētām kājām gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Un Jēzus izgājis redzēja daudz ļaužu, un Viņam sirds iežēlojās par tiem, un Viņš dziedināja viņu neveselos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Kad nu vakars metās, Viņa mācekļi pie Viņa piegāja un sacīja: “Šī vieta ir tuksnesis, un laiks jau ir pagājis; atlaidi tos ļaužu pulkus, ka tie var iet miestos un sev pirkt barību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Un Jēzus uz tiem sacīja:”Ttiem nevajag iet; dodiet jūs tiem ēst.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Bet tie uz Viņu sacīja: “Mums šeitan vairāk nav kā piecas maizes un divas zivis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Un Viņš sacīja: “Nesiet Man tās šurp.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Un tiem ļaudīm pavēlējis, zālē sēsties, Viņš ņēma tās piecas maizes un divas zivis, skatījās uz debesīm, pateicās un pārlauzis deva Saviem mācekļiem tās maizes, un tie mācekļi tiem ļaužu pulkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Un visi tie ēda un paēda; un salasīja no atlikušām druskām divpadsmit pilnus kurvjus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Un to vīru bija pie piectūkstoš, kas bija ēduši, bez sievām un bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Un Jēzus tūdaļ Saviem mācekļiem lika kāpt laivā un papriekš pārcelties, tiekams Viņš tos ļaudis atlaistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Un tos ļaudis atlaidis, Viņš gāja savrup uz vienu kalnu, Dievu lūgt. Un kad vakars metās, Viņš tur bija viens pats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Bet tā laiva jau bija jūras vidū un tapa mētāta no viļņiem; jo vējš bija pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Bet gaiļos Jēzus pie tiem nāca, pa jūru staigādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Un kad Viņa mācekļi To redzēja pa jūru staigājam, tad tie izbijās un sacīja: “Tas ir ķēms;” un brēca no bailēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Bet tūdaļ Jēzus uz tiem runāja un sacīja: “Turat drošu prātu, Es tas esmu! Nebīstaties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Un Pēteris Viņam atbildēja un sacīja: “Kungs, ja Tu tas esi, tad liec man pie Tevis nākt pa ūdens virsu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Un Viņš sacīja: “Nāc!” Un Pēteris izkāpa no laivas un gāja pa ūdens virsu, ka pie Jēzus nāktu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Bet to lielo vētru redzēdams, viņš izbijās un sāka grimt, brēca un sacīja: “Kungs, palīdzi man!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Un tūdaļ roku izstiepis, Jēzus viņu satvēra un uz viņu sacīja: “Tu mazticīgais, kāpēc tu esi šaubījies?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Un kad tie bija iekāpuši laivā, tad vējš nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Un tie, kas bija laivā, nāca un metās ceļos priekš Viņa un sacīja: “Patiesi, Tu esi Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Un tie pārcēlušies nāca uz Ģenecaretes zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Un kad tie ļaudis Viņu tai vietā nomanīja, tad tie sūtīja pa visu to apgabalu visapkārt, un atveda pie Viņa visādus neveselus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Un Viņu lūdza, ka Viņa drēbju vīli varētu aizskart; un cik to aizskāra, tie tapa dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Tad rakstu mācītāji un farizeji no Jeruzālemes nāca pie Jēzus sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '“Kāpēc Tavi mācekļi pārkāpj vecaju likumus? Jo tie savas rokas nemazgā, kad maizi ēd.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Bet Viņš atbildēja un uz tiem sacīja: “Kāpēc jūs arīdzan pārkāpjat Dieva bauslību caur saviem likumiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Jo Dievs ir pavēlējis un sacījis: “Godā savu tēvu un māti!” Un: “Kas savu tēvu vai māti lād, tam būs mirt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Bet jūs māciet, ja kas sakot uz tēvu vai māti: “Kas tev no manis varētu par labu nākt, tas lai ir Dievam par upuri!” tas labi darot. Tāds tiešām savu tēvu un savu māti negodās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Tad jūs nu Dieva bauslību nicināt caur saviem likumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Jūs liekuļi, pareizi Jesaja par jums sludinājis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '“Šie ļaudis pie Manis turas ar savu muti un godā Mani ar savām lūpām; bet viņu sirds ir tālu no Manis nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Bet velti tie Mani cienī, mācīdami mācības, kas ir cilvēku pavēles,””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Un Viņš tos ļaudis pieaicinājis uz tiem sacīja: “Klausāties un saprotiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Kas mutē ieiet, tas cilvēku nesagāna; bet kas no mutes iziet, tas cilvēku sagāna.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tad Viņa mācekļi piegājuši sacīja uz Viņu: “Vai Tu zini, ka tie farizeji, Tavus vārdus dzirdēdami, apgrēcību ņēmuši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Bet Viņš atbildēja un sacīja: “Visi dēsti, ko Mans Debesu Tēvs nav dēstījis, taps izrauti ar saknēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Atstājiet no tiem; tie ir akli aklu ceļa rādītāji; bet ja akls aklam ceļu rāda, tad abi divi kritīs bedrē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Tad Pēteris atbildēja un uz Viņu sacīja: “Izstāsti mums šo līdzību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Un Jēzus sacīja: “Vai tad ir jūs vēl esat nesaprašas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Vai jūs vēl nenomanāt, ka viss, kas mutē ieiet tas noiet vēderā un top izmests caur vēderu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Bet kas no mutes iziet, tas nāk no sirds, un tas cilvēku sagāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Un no sirds nāk ļaunas domas, slepkavības, laulības pārkāpšanas, maucības, zādzības, nepatiesas liecības, zaimošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Viss tas cilvēku sagāna; bet nemazgātām rokām ēst tas cilvēku nesagāna.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Un no turienes izgājis, Jēzus atkāpās pret Tirus un Sidonas robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Un redzi, viena Kanaāniešu sieva, no tām pašām robežām izgājusi, uz Viņu sauca sacīdama: “Ak Kungs, Tu Dāvida dēls, apžēlojies par mani; mana meita top no velna nežēlīgi vārdzināta.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Un Viņš tai neatbildēja neviena vārda. Un Viņa mācekļi piegājuši Viņu lūdza un sacīja: “Atlaidi to, jo tā brēc mums pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Bet Viņš atbildēja un sacīja: “Es neesmu sūtīts kā vien pie tām pazudušām avīm no Israēla cilts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Bet tā nāca, metās zemē priekš Viņa un sacīja: “Kungs, palīdzi man!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Bet Viņš atbildēja un sacīja: “Neklājās, bērniem maizi atņemt un sunīšiem mest priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Viņa sacīja: “Tā ir gan, Kungs! Bet tomēr sunīši ēd no tām drusciņām, kas no viņu kungu galda nokrīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tad Jēzus atbildēja un uz to sacīja: “Ak sieva, tava ticība ir liela; lai tev notiek, kā tu gribi;” un viņas meita tapa vesela tai pašā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Un Jēzus aizgāja no turienes un nāca pie Galilejas jūras, un uzkāpa kalnā un tur apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Un daudz ļaužu atnāca pie Viņa un atveda līdz tizlus, aklus, mēmus, kropļus un daudz citus, un nometa tos Jēzum pie kājām, un Viņš tos dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Tā ka tie ļaudis brīnījās, kad redzēja mēmus runājam, kropļus veselus, tizlus staigājam un aklus redzam, un teica Israēla Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Un Jēzus, Savus mācekļus pie Sevis aicinājis, sacīja: “Mana sirds par tiem ļaudīm, iežēlojās, jo tie nu trīs dienas pie Manis palikuši, un tiem nav ko ēst; un Es tos negribu atlaist neēdušus, ka tie uz ceļa nenonīkst badā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Un Viņa mācekļi uz To sacīja: “Kur lai ņemam šeitan tuksnesī tik daudz maizes, ka pieēdinājām tādu pulku ļaužu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Un Jēzus uz tiem sacīja: “Cik jums maizes?” Tie sacīja: “Septiņas un maz zivtiņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Un Viņš tiem ļaudīm lika pie zemes apsēsties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Un tās septiņas maizes un tās zivis ņēmis, Viņš pateicās un pārlauza un deva Saviem mācekļiem, un tie mācekļi tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Un tie visi ēda un paēda un salasīja no atlikušām druskām septiņus kurvjus pilnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Un to, kas bija ēduši, bija četrtūkstoš vīri, bez sievām un bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Un Viņš tos ļaudis atlaidis, kāpa laivā un nāca uz Magdaļas robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Tad farizeji un saduceji nāca pie Viņa kārdinādami un prasīja Viņam, lai tiem parāda kādu zīmi no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Bet Viņš atbildēja un uz tiem sacīja: “Kad vakars metās, tad jūs sakāt: “Būs skaidrs gaiss, jo debess ir sarkana.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Un no rīta agrumā: “Šodien būs negaiss, jo debess ir sarkana un apmākusies.” Jūs liekuļi, debess izskatu jūs zināt noprast, vai jūs nevarat arī noprast laiku zīmes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Nikna un laulību pārkāpēja tauta meklē zīmi, un viņai nekāda zīme netaps dota, kā vien pravieša Jonas zīme.” Un Viņš tos atstāja un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Un Viņa mācekļi pārcēlušies bija aizmirsuši maizi ņemt līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Un Jēzus uz tiem sacīja: “Pielūkojiet un sargājaties no farizeju un saduceju rauga.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Bet tie domāja pie sevis un sacīja: “Tas ir, ka mēs maizes neesam ņēmuši līdz.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Un Jēzus, to nomanīdams, uz tiem sacīja: “Ko jūs domājat pie sevis, jūs mazticīgie, ka jūs maizes neesat ņēmuši līdz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Vai jūs vēl neprotat, nedz atminat tās piecas maizes pie tiem piectūkstošiem, un cik kurvju jūs esat salasījuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Nedz tās septiņas maizes pie tiem četrtūkstošiem, un cik kurvju jūs esat salasījuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Kā tad nu jūs neprotat, ka Es uz jums neesmu runājis par maizi, sacīdams: “Sargājaties no farizeju un saduceju rauga?””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Tad tie saprata, ka Viņš nebija sacījis, ka lai tie sargās no maizes rauga, bet no farizeju un saduceju mācības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Un Jēzus nāca uz Filipa Cezarejas robežām un vaicāja Saviem mācekļiem un sacīja: “Ko ļaudis saka, To Cilvēka Dēlu esam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Un viņi atbildēja: “Citi saka: Jānis tas Kristītājs; citi: Elija; citi: Jeremija, vai kāds no tiem praviešiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Viņš uz tiem sacīja: “Bet ko tad jūs sakāt, kas Es esmu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Tad Sīmanis Pēteris atbildēja un sacīja: “Tu esi Kristus, Tā dzīvā Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Un Jēzus atbildēja un uz to sacīja: “Svētīgs tu esi, Sīmani, Jonas dēls, jo miesa un asinis tev to nav sacījušas, bet Mans Tēvs debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Un Es arīdzan tev saku: “Tu esi Pēteris, un uz šo akmeni Es Savu draudzi gribu uztaisīt, un elles vārtiem to nebūs uzvarēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Un Es tev došu Debesu valstības atslēgas; un ko tu virs zemes siesi, tam būs arī būt sietam debesīs; un ko tu virs zemes atraisīsi, tam būs arī būt atraisītam debesīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Tad Viņš Saviem mācekļiem aizliedza, ka tie nevienam nesacītu, ka Viņš Jēzus Tas Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'No tā laika Jēzus Saviem mācekļiem iesāka rādīt, ka Viņam vajagot noiet uz Jeruzālemi un daudz ciest no tiem vecajiem un augstiem priesteriem un rakstu mācītājiem, un tapt nokautam un trešā dienā augšāmcelties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Un Pēteris, Viņu savrup ņēmis, iesāka viņu apsaukt sacīdams: “Dievs pasargā! Kungs, lai Tev tā nenotiek!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Bet Viņš atgriezdamies sacīja uz Pēteri: “Atkāpies no Manis, sātan, tu Man esi par apgrēcību. Jo tu nedomā, kas Dievam, bet kas cilvēkiem tīk.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Tad Jēzus uz Saviem mācekļiem sacīja: “Ja kas Man grib nākt pakaļ, tam būs sevi pašu aizliegt, savu krustu uz sevi ņemt un Man iet pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Jo kas savu dzīvību grib izglābt, tam tā zudīs, un kam dzīvība Manis dēļ zūd, tas to atradīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Jo ko tas cilvēkam līdz, kad tas iemanto visu pasauli, un tam tomēr dvēsele zūd? Jeb ko cilvēks var dot par savas dvēseles atpirkšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Jo Tas Cilvēka Dēls nāks iekš Sava Tēva godības ar Saviem eņģeļiem, un tad Tas ikkatram atmaksās pēc viņa darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Patiesi, Es jums saku: kādi no tiem, kas šeitan stāv, nāvi nebaudīs, iekams neredzēs To Cilvēka Dēlu nākam Savā Valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Un pēc sešām dienām Jēzus ņēma Pēteri un Jēkabu un šā brāli, Jāni, un tos veda savrup uz augstu kalnu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Un tapa apskaidrots viņu priekšā, un Viņa vaigs spīdēja kā saule, un Viņa drēbes tapa baltas kā gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Un redzi, Mozus un Elija tiem parādījās un runāja ar Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Un Pēteris vērsās pie Jēzus un sacīja: “Kungs, šeit mums labi! Ja Tu gribi, tad mēs šeitan trīs būdas taisīsim, vienu Tev, vienu Mozum, un vienu Elijam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Tam vēl runājot, redzi, spožs padebesis tos apēnoja, un redzi, balss no tā padebeša sacīja: “Šis ir Mans mīļais Dēls, pie kā Man ir labs prāts, To jums būs klausīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Kad tie mācekļi to dzirdēja, tad tie krita uz savu vaigu un izbijās ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Bet Jēzus nāca, tos aizskāra un sacīja: “Ceļaties un nebīstaties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Bet kad tie savas acis pacēla, tad tie neredzēja nevienu kā tik vien Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Un no kalna noejot, Jēzus tiem pavēlēja un sacīja: “Nesakiet nevienam šo parādīšanos, tiekams Tas Cilvēka Dēls nebūs uzcēlies no miroņiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Un Viņa mācekļi Viņam vaicāja sacīdami: “Ko tad tie rakstu mācītāji saka, ka Elijam jānāk papriekš?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Bet Jēzus atbildēja un uz tiem sacīja: “Elija gan nāk papriekš un visu atkal sataisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Bet Es jums saku, ka Elija jau ir nācis, tomēr tie viņu nav atzinuši, bet ar viņu darījuši, ko gribēdami. Tā arī Tam Cilvēka Dēlam būs jācieš no viņiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tad tie mācekļi saprata, ka Viņš tiem sacījis no Jāņa, tā Kristītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Un kad tie nāca pie tiem ļaudīm, tad viens cilvēks pie Viņa atnāca un metās ceļos Viņa priekšā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Un sacīja: “Kungs, apžēlojies par manu dēlu, jo viņš ir mēnessērdzīgs un viņam briesmīgi jācieš; jo dažkārt viņš krīt ugunī un dažkārt ūdenī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Un es to pie Taviem mācekļiem esmu atvedis, bet tie to nevarēja veselu darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Bet Jēzus atbildēja un sacīja: “Ak tu neticīgā un netiklā cilts, cik ilgi Es vēl būšu pie jums? Cik ilgi Es jūs panesīšu? Vediet Man viņu šurp.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Un Jēzus viņu apdraudēja, un velns no viņa izbēga; un tas zēns palika vesels tanī pašā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Tad tie mācekļi piegāja pie Jēzus atsevišķi un sacīja: “Kāpēc mēs viņu nevarējām izdzīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Un Jēzus uz tiem sacīja: “Jūsu neticības dēļ; jo patiesi, Es jums saku: kad jums ticība ir kā sinepju graudiņš, tad jūs sacīsiet šim kalnam: nocelies no šejienes uz turieni, un viņš nocelsies, un nekas jums nebūs neiespējams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Bet šī suga neizbēg kā vien caur lūgšanu un gavēšanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Kad nu tie Galilejā apkārt staigāja, tad Jēzus uz tiem sacīja: “Tas Cilvēka Dēls taps nodots cilvēku rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'Un Viņu nokaus, un trešā dienā Viņš celsies augšām;” un tie ļoti noskuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Un kad tie Kapernaūmā nāca, tad tie nodokļu saņēmēji atnāca pie Pētera un sacīja: “Vai jūsu Mācītājs nodokli nedod?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Viņš sacīja: “Dod gan.” Un kad tas namā bija iegājis, Jēzus viņam papriekš vaicāja sacīdams: “Ko tu domā, Sīman? No kuriem laicīgie ķēniņi ņem muitu un nodokli? Vai no saviem bērniem, vai no svešiniekiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Pēteris uz Viņu sacīja: “No svešiniekiem.” Tad Jēzus uz to sacīja: “Tad tie bērni ir svabadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Bet lai mēs tiem nedodam apgrēcību, tad ej jūrmalā un izmet makšķeri, un to pirmo zivi, kas piekodīsies, ņem, un viņas muti atdarījis, tu atradīsi vienu stateri, to ņem un dod viņiem priekš Manis un tevis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Tanī pašā stundā tie mācekļi gāja pie Jēzus un sacīja: “Kas ir tas lielākais Debesu valstībā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Un Jēzus aicināja vienu bērnu pie Sevis, un to veda pašā viņu vidū,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'Un sacīja: “Patiesi, Es jums saku, ja jūs neatgriežaties un netopat kā bērni, tad jūs nenāksiet Debesu valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Tāpēc, kas pats zemojās, kā šis bērns, tas ir tas lielākais Debesu valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Un kas tādu bērnu uzņem Manā Vārdā, tas uzņem Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Bet kas apgrēcina vienu no šiem vismazākiem, kas tic uz Mani, tam būtu labāki, ka tam pakārtu pie kakla dzirnu akmeni un to noslīcinātu jūrā, visdziļākā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Vai pasaulei apgrēcības dēļ! Apgrēcībai gan vajag nākt, bet vai tam cilvēkam, caur ko nāk apgrēcība!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Tāpēc, ja tava roka vai tava kāja tevi apgrēcina, tad nocērt to un met to nost; jo tas tev labāki, ka tu ieej dzīvošanā tizls vai kroplis, nekā tev ir divas rokas vai kājas, un tu topi iemests mūžīgā ugunī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Un ja tava acs tevi apgrēcina, izrauj to un met to nost; tas tev labāki, ar vienu aci ieiet dzīvošanā, nekā tev ir divas acis, un tu topi iemests elles ugunī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Pielūkojiet, ka jūs nevienu no šiem mazajiem nenicinājiet; jo es jums saku, ka viņu eņģeļi debesīs vienmēr redz Mana debes\' Tēva vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Jo Tas Cilvēka Dēls ir nācis, atpestīt to, kas pazudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Kā jums šķiet? Ja kādam cilvēkam būtu simts avis, un viena no tām būtu nomaldījusies, vai viņš neatstātu tās deviņdesmit deviņas un neietu kalnos, to meklēt, kas nomaldījusies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Un ja tas notiek, ka to atrod, patiesi, Es jums saku, ka tas vairāk par to priecājās, nekā par tām deviņdesmit un deviņām, kas nav nomaldījušās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Tāpat tas nav jūsu debes\' Tēva prāts, ka vienam no šiem mazajiem būs pazust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Bet ja tavs brālis pret tevi grēko, tad noej un pārmāci viņu starp sevi un viņu vienu pašu; kad viņš tevi klausa, tad tu savu brāli esi mantojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Un ja viņš negrib klausīt, tad ņem klāt vēl vienu vai divus, lai no divēju vai treju liecinieku mutes ikkatrs vārds top apstiprināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Bet ja viņš tos neklausa, tad saki to draudzei; bet ja viņš arī draudzi neklausa, tad turi viņu par pagānu un muitnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Patiesi, Es jums saku, ko vien jūs virs zemes siesiet, tas arī būs siets debesis; un ko vien jūs virs zemes atraisīsiet, tas arī būs atraisīts debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Atkal Es jums saku: ja divi no jums virs zemes ir vienā prātā jebkuras lietas dēļ, ko tie grib lūgt, tad tā tiem taps dota no Mana Tēva, kas ir debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Jo kur divi vai trīs ir sapulcināti Manā Vārdā, tur Es esmu viņu vidū.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tad Pēteris gāja pie Viņa un sacīja: “Kungs, cikkārt man būs piedot savam brālim, kas pret mani grēko? Vai ir diezgan septiņ reiz?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jēzus uz to saka: “Es tev nesaku septiņ reiz, bet septiņdesmit reiz septiņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Tāpēc Debesu valstība ir kā kāds ķēniņš, kas ar saviem kalpiem gribēja parādu izlīdzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Un kad viņš iesāka līdzību turēt, viens viņam tapa pievests, tas bija viņam parādā desmit tūkstošus podus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Un kad tas to nespēja maksāt, tad tas kungs pavēlēja, viņu pārdot ar sievu un bērniem un visu, kas tam bija, un maksāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Tad tas kalps pie zemes krizdams viņu gauži lūdzās un sacīja: “Kungs, cieties ar mani, es tev visnotaļ gribu maksāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Tad tam kungam palika tā kalpa žēl, un viņš to palaida un to parādu tam arī atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Bet kad tas pats kalps bija ārā izgājis, tad tas atrada vienu no saviem darba biedriem; tas bija viņam parādā simts sudraba grašus, un viņš sakampis to žņaudza un sacīja: “Maksā, ko tu man esi parādā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Tad viņa darba biedrs tam krita pie kājām, lūdzās un sacīja: “Cieties ar mani, es tev visnotaļ maksāšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Un viņš negribēja; un nogājis to iemeta cietumā, tiekams tas maksātu, ko bija parādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Kad nu viņa darba biedri to redzēja, tad tas tiem gauži sāpēja, un nākuši tie pasacīja savam kungam visu, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tad viņa kungs to aicināja priekšā un uz to sacīja: “Tu blēdīgais kalps, visu šo parādu es tev esmu atlaidis, kad tu mani lūdzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Vai tad tev arīdzan nebija apžēloties par savu darba biedru, kā es tevi esmu žēlojis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Un viņa kungs apskaities to nodeva tiem mocītājiem, kamēr tas maksātu visu, ko tam bija parādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Tā arī Mans Debesu Tēvs jums darīs, ja jūs nepiedosiet no sirds ikviens savam brālim viņa pārkāpšanas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Un notikās, kad Jēzus šos vārdus bija pabeidzis, tad Viņš aizgāja no Galilejas un nāca gar Jardānes otru pusi uz Jūdu zemes robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Un daudz ļaužu Viņam gāja pakaļ, un Viņš tos tur darīja veselus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Un tie farizeji nāca pie Viņa, To kārdinādami, un uz Viņu sacīja: “Vai cilvēkam jebkādas vainas dēļ brīv no sievas šķirties?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Bet Viņš atbildēja un uz tiem sacīja: “Vai jūs neesat lasījuši, ka Radītājs iesākumā viņus radījis vīru un sievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'Un sacījis: “Tādēļ cilvēks atstās tēvu un māti un pieķersies pie savas sievas; un tie divi būs viena miesa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Tad nu tie nav vairs divi, bet viena miesa; ko nu Dievs savienojis, to nevienam cilvēkam nebūs šķirt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Tie uz Viņu saka: “Kā tad Mozus ir pavēlējis, šķiršanās grāmatu dot un šķirties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Viņš uz tiem saka: “Mozus jūsu sirds cietības dēļ jums vaļu devis, no savām sievām šķirties, bet no iesākuma tas tā nav bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Bet Es jums saku, kas no savas sievas šķirās, ja ne maucības dēļ, un precē citu, tas pārkāpj laulību, un kas atšķirtu precē, tas pārkāpj laulību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Viņa mācekļi uz Viņu saka: “Ja tas tā ir vīra un sievas starpā, tad nav labi precēties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Bet Viņš uz tiem sacīja: “Visi šo vārdu nespēj saņemt, bet tie vien, kam tas ir dots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Jo tur ir rāmiti, kas no mātes miesām tādi dzimuši, un tur ir rāmiti, kas no cilvēkiem rāmiti; un tur ir rāmiti, kas paši rāmijušies Debesu valstības dēļ. Kas to spēj saņemt, tas lai saņem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tad bērniņi pie Viņa tapa pienesti, ka Viņš tiem rokas uzliktu un Dievu lūgtu; bet tie mācekļi tos aprāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Bet Jēzus sacīja: “Laidiet tos bērniņus un neliedziet tiem, pie Manis nākt; jo tādiem pieder Debesu valstība.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Un Viņš tiem rokas uzlicis, aizgāja no turienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Un redzi, viens piegājis uz Viņu sacīja: “Labais Mācītāj, ko laba man būs darīt, lai es dabūju mūžīgu dzīvošanu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Un Viņš uz to sacīja: “Ko tu Mani sauc par labu? Neviens nav labs, kā vien Tas Vienīgais Dievs. Bet ja tu gribi dzīvībā ieiet, tad turi tos baušļus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Tas uz Viņu saka: Kādus?” Un Jēzus sacīja: “Šos: tev nebūs nokaut; tev nebūs laulību pārkāpt; tev nebūs zagt; tev nebūs nepatiesu liecību dot;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Godā savu tēvu un māti; un tev būs savu tuvāko mīlēt, kā sevi pašu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Tas jauneklis uz Viņu saka: “Visu to es esmu turējis no savas jaunības; kā man vēl trūkst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jēzus uz to sacīja: “Ja tu gribi būt pilnīgs, tad noej, pārdod, kas tev ir, un dod nabagiem; tad tev būs manta debesīs; un tad nāc, staigā Man pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Bet tas jauneklis, šo vārdu dzirdējis, aizgāja noskumis, jo tam bija daudz mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Bet Jēzus uz Saviem mācekļiem sacīja: “Patiesi, Es jums saku: bagāts grūti ieies Debesu valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Un atkal Es jums saku: vieglāki ir kamielim iet caur adatas aci, nekā bagātam kļūt Dieva valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Un to dzirdējuši, Viņa mācekļi ļoti pārbijās un sacīja: “Kas tad var kļūt Debesu valstībā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Un Jēzus tos uzlūkoja un uz tiem sacīja: “Cilvēki to neiespēj, bet Dievam visas lietas iespējamas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Tad Pēteris atbildēdams uz Viņu sacīja: “Redzi, mēs visu esam atstājuši un Tev gājuši pakaļ; kas mums par to būs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Bet Jēzus uz tiem sacīja: “Patiesi, Es jums saku, ka jūs, kas Man pakaļ gājuši, tanī atdzimšanā, kad Tas Cilvēka Dēls sēdēs uz Sava godības krēsla, arī sēdēsiet uz divpadsmit krēsliem un tiesāsiet tās divpadsmit Israēla ciltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Un kas atstāj mājas vai brāļus, vai māsas, vai tēvu, vai māti, vai sievu, vai bērnus, vai tīrumus Mana Vārda dēļ, tas to ņems simtkārtīgi, un iemantos mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Bet daudzi, kas tie pirmie, būs tie pēdējie, un tie pēdējie būs tie pirmie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Jo Debesu valstība ir kā kāds nama tēvs, kas no rīta agrumā izgāja, strādniekus derēt savā vīna kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Un saderējis ar tiem strādniekiem par vienu sudraba grasi par dienas algu, viņš tos nosūtīja savā vīna kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Un izgājis ap trešo stundu, viņš redzēja vēl citus pie tirgus bez darba stāvam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Un uz tiem sacīja: “Noejat arī jūs vīna kalnā, es jums došu, kas nākas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Un tie nogāja. Atkal viņš izgāja ap sesto un devīto stundu un darīja tāpat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Bet ap vienpadsmito stundu izgājis, viņš atrada vēl citus bez darba stāvam, un uz tiem saka: “Ko jūs visu dienu še stāviet bez darba?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Tie uz viņu saka: “Neviens mūs nav derējis.” Viņš uz tiem saka: “Ejat jūs arīdzan vīna kalnā, un kas nākas, to jūs dabūsiet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Kad nu vakars metās, tad tas vīna kalna kungs saka savam uzraugam: “Sauc tos strādniekus un dod tiem to algu, no pēdējiem sākdams, pie pirmajiem beigdams.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Tad tie nāca, kas ap vienpadsmito stundu derēti, un dabūja savu grasi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Bet kad tie pirmie nāca, tad tie cerēja vairāk dabūt; un tie arī dabūja ikviens savu grasi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'To dabūjuši, tie kurnēja pret to nama tēvu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Un sacīja: “Šie pēdējie vienu stundu vien strādājuši, un tu tos esi līdzinājis mums, kas dienas nastu un karstumu esam cietuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Bet viņš atbildēja un uz vienu no tiem sacīja: “Draugs, es tev netaisnību nedaru. Vai tu ar mani neesi saderējis par vienu grasi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Ņem, kas tev pieder, un ej; bet es šiem pēdējiem gribu tā dot kā tev.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Jeb vai man nav brīv, darīt ar savu mantu, kā es gribu? Jeb vai tava acs tāpēc skauž, ka es esmu labs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Tā tie pēdējie taps tie pirmie, un tie pirmie tie pēdējie. Jo daudz ir aicināti, bet maz izredzēti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Un noiedams uz Jeruzālemi, Jēzus ņēma tos divpadsmit mācekļus pie Sevis un ceļā uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '“Redzi, mēs noejam uz Jeruzālemi, un Tas Cilvēka Dēls taps nodots tiem augstiem priesteriem un rakstu mācītājiem, un tie Viņu pazudinās pie nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'Un Viņu nodos tiem pagāniem; tie Viņu apmēdīs, šaustīs un krustā sitīs, un trešā dienā Viņš atkal celsies augšām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tad Cebedeja dēlu māte ar saviem dēliem nāca pie Viņa, metās zemē un lūdza ko no Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Un Viņš tai sacīja: “Ko tu gribi?” Tā uz Viņu sacīja: “Saki, lai šie mani divi dēli sēž Tavā valstībā viens Tev pa labo un otrs pa kreiso roku.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Bet Jēzus atbildēja un sacīja: “Jūs nezināt, ko jūs lūdzat. Vai jūs varat dzert to biķeri, ko Es dzeršu, un likties kristīties ar to kristību, ar ko Es topu kristīts?” Tie uz viņu sacīja: “Varam gan.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Un Viņš uz tiem saka: “Manu biķeri jums gan būs dzert, un ar to kristību, ar ko Mani kristīs, jums būs tapt kristītiem; bet sēdēt pie Manas labās un kreisās rokas, Man nepieder dot, bet tas būs tiem, kam Mans Tēvs to novēlējis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Un kad tie desmit to dzirdēja, tad tie apskaitās par tiem diviem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Bet Jēzus tos aicināja pie Sevis un sacīja: “Jūs zināt, ka tie pasaules valdnieki pār ļaudīm valda, un tiem lieliem kungiem pār tiem ir vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Bet pie jums tā nebūs būt; bet ja kas no jums grib būt liels, tas lai ir jūsu sulainis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'Un ja kas grib būt jūsu starpā tas pirmais, tas lai ir jūsu kalps;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Tā kā Tas Cilvēka Dēls nav nācis, ka Viņam taptu kalpots, bet ka Viņš kalpotu, un Savu dzīvību dotu par atpirkšanas maksu priekš daudziem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Un kad tie no Jērikus izgāja, tad Viņam daudz ļaužu nāca pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Un redzi, divi akli sēdēja ceļmalā; kad tie dzirdēja Jēzu secen ejam, tad tie brēca un sacīja: “Apžēlojies par mums, Kungs, Tu Dāvida dēls!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Bet tie ļaudis tos apsauca, ka tie klusu ciestu; bet tie brēca vēl vairāk un sacīja: “Apžēlojies par mums, Kungs, Tu Dāvida dēls!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Un Jēzus apstājās, tos aicināja un sacīja: “Ko jūs gribat, lai Es jums daru?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Tie uz Viņu saka: “Kungs, ka mūsu acis top atdarītas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Un Jēzum palika žēl, un Viņš aizskāra viņu acis, un tūdaļ viņu acis tapa gaišas, un tie Viņam gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Un kad tie tuvu pie Jeruzālemes nāca, pie Betfagas, pie Eļļas kalna, tad Jēzus sūtīja divus no Saviem mācekļiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Un tiem sacīja: “Ejat uz to miestu, kas jūsu priekšā; un tūdaļ jūs atradīsiet ēzeļa māti piesietu un pie tās kumeļu. Atraisījuši atvediet tos pie Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Un ja kas jums ko sacīs, tad atsakāt: “Tam Kungam to vajag,” tūdaļ viņš jums tos atlaidīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Bet viss tas notika, lai piepildās, ko tas pravietis sacījis sludinādams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '“Sakait Ciānas meitai: redzi, tavs ķēniņš nāk pie tevis, lēnprātīgs, jādams uz ēzeļa un nastu nesējas ēzeļa mātes kumeļa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Tie mācekļi nogāja un darīja, kā Jēzus tiem bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Un atveda to ēzeļa māti un to kumeļu, un uzlika savas drēbes un sēdināja Viņu tur virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Bet daudz ļaužu izklāja savas drēbes uz ceļa; bet citi cirta zarus no kokiem un izkaisīja tos uz ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Bet tie ļaudis, kas priekšā gāja un no aizmugures staigāja, kliedza un sauca: “Ozianna Tam Dāvida dēlam, slavēts, kas nāk Tā Kunga Vārdā! Ozianna visaugstākās debesīs!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Bet kad Viņš Jeruzālemē iejāja, tad visa pilsēta cēlās un sacīja: “Kas Tas tāds?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Bet tie ļaudis sacīja: “Šis ir Jēzus, tas pravietis no Nacaretes iekš Galilejas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Un Jēzus iegāja Dieva namā un izdzina visus, kas Dieva namā pārdeva un pirka, un apgāza galdus tiem naudas mijējiem un krēslus tiem baložu pārdevējiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Un uz tiem sacīja: “Stāv rakstīts: “Mans nams taps nosaukts lūgšanas nams,” bet jūs to esat darījuši par slepkavu bedri.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Un tur akli un tizli nogāja pie Viņa Dieva namā, un Viņš tos dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Bet kad tie augstie priesteri un rakstu mācītāji redzēja tos brīnuma darbus, ko Viņš darīja, un tos bērnus Dieva namā brēcam un sakām: “Ozianna tam Dāvida dēlam!” tad tie apskaitās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'Un uz Viņu sacīja: “Vai Tu nedzirdi, ko šie saka?” Bet Jēzus uz tiem sacīja: “Dzirdu gan. Vai jūs nekad neesat lasījuši: no bērniņu un zīdāmu mutes Es slavu sataisīšu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Un tos atstājis, Viņš izgāja no pilsētas ārā uz Betaniju un tur pārgulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Bet kad Viņš no rīta agrumā atkal uz pilsētu gāja, Viņam gribējās ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Un Viņš redzēja vienu vīģes koku ceļmalā, piegāja pie tā un neatrada uz tā nenieka, kā tik lapas vien, un uz to sacīja: “Uz tevis lai nemūžam vairs auglis neaug.” Un tūdaļ tas vīģes koks nokalta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Un tie mācekļi to redzējuši, brīnījās un sacīja: “Kā tas vīģes koks tik drīz nokaltis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Bet Jēzus atbildēja un uz tiem sacīja: “Patiesi, Es jums saku: ja jums ticība ir, un jūs prātā nešaubaties, tad jūs nevien to darīsiet ar to vīģes koku, bet arī, kad jūs šim kalnam sacīsiet: celies no savas vietas un meties jūrā, tad tas notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Un visu, ko jūs savā lūgšanā lūgsiet ticēdami, to jūs dabūsiet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Un kad Viņš nāca Dieva namā, tad Viņam mācot tie augstie priesteri un ļaužu vecaji piegāja un sacīja: “Kādā varā Tu šīs lietas dari? Un kas Tev tādu varu devis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Bet Jēzus atbildēja un uz tiem sacīja: “Es jums arīdzan vienu vārdu gribu vaicāt? ja jūs Man to sacīsiet, tad Es jums arī sacīšu, kādā varā Es šīs lietas daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'No kurienes bija Jāņa kristība? Vai no debesīm, vai no cilvēkiem?” Bet tie apdomāja savā starpā sacīdami: “Ja mēs sakām: no debesīm, tad Viņš mums sacīs: Kāpēc tad jūs viņam neesat ticējuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Bet ja mēs sakām: no cilvēkiem, tad mums no tiem ļaudīm jābīstas; jo visi Jāni tur par pravieti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Un tie atbildēja un sacīja: “Mēs nezinām.” Viņš uz tiem sacīja: “Tad arī Es jums nesaku, kādā varā Es šīs lietas daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Bet kā jums šķiet? Vienam cilvēkam bija divi dēli, un tas gāja pie tā pirmā un sacīja: dēls, ej, strādā šodien manā vīna kalnā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Bet tas atbildēja un sacīja: es negribu. Bet pēc tas viņam bija žēl un viņš nogāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Un tas tēvs gāja pie tā otra un sacīja tāpat. Bet tas atbildēja un sacīja: es iešu, kungs! un viņš nenogāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Kurš no tiem diviem ir darījis sava tēva prātu?” Tie uz Viņu saka: “Tas pirmais.” Jēzus uz viņiem saka: “Patiesi, Es jums saku: muitnieki un maukas drīzāk nāks Dieva valstībā, nekā jūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Jo Jānis pie jums ir nācis pa taisnības ceļu, un jūs viņam neesat ticējuši, bet muitnieki un maukas viņam ticējuši. Bet jebšu jūs to redzējāt, tomēr jums nebija žēl, tā ka viņam pēc būtu ticējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Klausāties citu līdzību. Bija nama tēvs, kas vīna kalnu dēstīja un to aptaisīja ar sētu un tur iekšā izraka vīna spaidu un uztaisīja torni un to izdeva strādniekiem un aizgāja citur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Kad nu augļu laiks atnāca, tad viņš sūtīja savus kalpus pie tiem strādniekiem savus augļus dabūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Bet tie strādnieki viņa kalpus ņēmuši, vienu šauta un otru nokāva un trešo akmeņiem nomētāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Atkal tas sūtīja citus kalpus, vairāk nekā papriekš, un tie viņiem tāpat darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Beidzot viņš pie tiem sūtīja savu dēlu un sacīja: taču tie kaunēsies no mana dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Bet kad tie strādnieki to dēlu redzēja, tad tie sacīja savā starpā: šis ir tas mantinieks; nāciet, nokausim to un paturēsim viņa mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Tad tie viņu ņēmuši izmeta no vīna kalna ārā un nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Kad nu tas vīna kalna kungs nāks, ko viņš šiem strādniekiem darīs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Viņi uz To sacīja: “Viņš šos ļaundarītājus nežēlīgi nomaitās un to vīna kalnu izdos citiem strādniekiem, kas viņam augļus dos īstenā laikā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jēzus uz tiem sacīja: vai jūs nekad Dieva rakstos neesat lasījuši: tas akmens, ko tie nama taisītāji atmetuši, tas ir palicis par stūra akmeni; tas ir no Tā Kunga un ir brīnums mūsu acīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Tāpēc Es jums saku: Dieva valstība jums taps atņemta un pagāniem dota, kas nes viņas augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Un kas uz šo akmeni kritīs, tas sadauzīsies, bet uz ko tas krīt, to tas satrieks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Un kad tie augstie priesteri un farizeji Viņa līdzības dzirdēja, tad tie nomanīja, ka Tas par viņiem runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Un meklēdami Viņu tvert, tie bijās no tiem ļaudīm, tāpēc ka tie Viņu cienīja par pravieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Un Jēzus atbildēja un runāja atkal caur līdzībām, uz tiem sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '“Debesu valstība līdzinājās ķēniņam, kas savam dēlam kāzas taisīja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Un izsūtīja savus kalpus, tos viesus aicināt kāzās, bet tie negribēja nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Atkal viņš citus kalpus izsūtīja un sacīja: sakāt tiem viesiem: redzi, mans mielasts ir sataisīts, mani vērši un baroti lopi nokauti, un visas lietas sataisītas; nāciet kāzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Bet tie to nicināja un nogāja cits uz savu tīrumu un cits pie savas tirgošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Bet citi viņa kalpus sagrāba un tos lika smieklā un tos nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Kad tas ķēniņš to dzirdēja, tad viņš tapa dusmīgs un sūtīja savu karaspēku un lika šos slepkavas nokaut un iededzināja viņu pilsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Tad viņš uz saviem kalpiem sacīja: tās kāzas gan ir sataisītas, bet tie viesi nebija cienīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Tāpēc ejat uz lielceļiem un aicinājiet kāzās, kādus jūs atrodat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Un tie kalpi izgāja uz tiem ceļiem un sameklēja kādus atrazdami, ļaunus un labus, un visi galdi pildījās ar viesiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Tad tas ķēniņš iegāja, tos viesus aplūkot, un tur ieraudzīja vienu cilvēku, kas nebija apģērbies kāzu drēbēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Un viņš uz to sacīja: draugs, kā tu šeit esi ienācis, neapģērbies kāzu drēbēs? Bet tas palika kā mēms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tad tas ķēniņš sacīja uz saviem kalpiem: sieniet tam kājas un rokas, ņemiet to un izmetiet to galējā tumsībā, tur būs raudāšana un zobu trīcēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Jo daudz aicināti, bet maz izredzēti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tad tie farizeji nogāja un sarunājās, ka tie Jēzu Viņa valodā savaldzinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Un tie sūtīja pie Viņa savus mācekļus ar ķēniņa Hērodus sulaiņiem, kas sacīja: “Mācītāj, mēs zinām, ka Tu esi patiesīgs un māci Dieva ceļu patiesīgi, un Tu nebēdā par nevienu: jo Tu neuzlūko cilvēka vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Tāpēc saki mums: kā Tev šķiet? Vai ir brīv, ķeizaram meslus dot, vai ne?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Un Jēzus, viņu blēdību nomanīdams, sacīja: “Jūs viltnieki, kam jūs Mani kārdināt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Rādiet Man šurp to nomas naudu.” Un tie Tam rādīja vienu sudraba grasi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Un Viņš uz tiem sacīja: “Kam ir šī zīme un tas virsraksts?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Tie uz Viņu sacīja: “Ķeizara.” Tad Viņš uz tiem sacīja: “Tad dodiet ķeizaram, kas ķeizaram pieder, un Dievam, kas Dievam pieder.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Un to dzirdēdami, tie brīnījās, un To pameta un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Tanī pašā dienā nāca pie Viņa saduceji, kas saka, augšāmcelšanos neesam, un Viņam vaicāja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Sacīdami: “Mācītāj, Mozus ir sacījis: ja kas mirst, un tam bērnu nav, tad viņa brālim būs viņa sievu precēt un savam brālim celt dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Tad nu pie mums bija septiņi brāļi, un tas pirmais apņēma sievu un nomira, un kad tam nebija bērnu, tad tas pameta savu sievu savam brālim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Tā arī otrais un trešais līdz septītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Un beidzot pēc visiem arī tā sieva nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Tad nu augšāmcelšanās dienā kuram no tiem septiņiem tā sieva piederēs? Jo tie visi viņu bija apņēmuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Bet Jēzus atbildēja un sacīja: “Jūs alojaties, neprazdami nedz tos rakstus, nedz Dieva spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Jo augšāmcelšanās laikā tie nedz precēs nedz taps precēti, bet tie būs itin kā Dieva eņģeļi debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Bet vai jūs par miroņu augšāmcelšanos neesat lasījuši, ko Dievs jums ir runājis sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '„Es esmu Ābrahāma Dievs un Īzaka Dievs un Jēkaba Dievs?“Dievs nav mirušu, bet dzīvu Dievs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Un kad tie ļaudis to dzirdēja, tad tie iztrūcinājās par Viņa mācību');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Bet farizeji dzirdējuši, ka Viņš saducejiem muti bija aizbāzis, sapulcējās kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Un viens no tiem, viens bauslības mācītājs, kārdinādams Tam jautāja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '“Mācītāj, kurš tas augstākais bauslis bauslībā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Bet Jēzus uz to sacīja: “Tev būs Dievu, savu Kungu, mīļot no visas savas sirds un no visas savas dvēseles un no visa sava prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Šis ir tas pirmais un augstākais bauslis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Bet tas otrs tam līdz: tev būs savu tuvāku mīļot kā sevi pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Šinīs divējos baušļos karājās visa bauslība un tie pravieši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Kad nu tie farizeji bija sagājuši, Jēzus tiem jautāja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Un sacīja: “Kas jums šķiet no Kristus, kā dēls Viņš ir?” Tie uz Viņu sacīja: “Dāvida.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Un Viņš uz tiem sacīja: “Kā tad Dāvids Viņu garā sauc par Kungu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Tas Kungs sacījis uz manu Kungu: sēdies pa Manu labo roku, tiekams Es Tavus ienaidniekus lieku par pameslu Tavām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Ja nu Dāvids To sauc par Kungu, kā tad Tas viņa Dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Un neviens nezināja Viņam atbildēt neviena vārda un no tās dienas arī neviens nedrīkstēja vairs Viņu jautāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tad Jēzus runāja uz tiem ļaudīm un uz Saviem mācekļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Sacīdams: “Uz Mozus krēsla rakstu mācītāji un farizeji ir apsēdušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Visu nu, ko tie saka, lai jūs turiet, to turiet un dariet; bet pēc viņu darbiem nedariet. Jo tie gan māca, bet paši to nedara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Jo tie sasien grūtas un nepanesamas nastas un liek tās cilvēkiem uz pleciem, bet paši tās ne ar pirkstu negrib pakustināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Bet visus savus darbus tie dara, lai tie no ļaudīm top redzēti. Tie izplata savus piemiņas rakstus un dara savām drēbēm platas bārkstis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Un tiem tīk viesībās sēdēt augstajās vietās un augstajos krēslos baznīcās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'Un ka top sveicināti tirgos un no ļaudīm saukti: rabbi, rabbi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Bet jums nebūs sauktiem tapt: rabbi! Jo viens ir jūsu vadonis, Kristus, bet jūs visi esat brāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Jums arī nevienu virs zemes nebūs saukt par tēvu, jo viens ir jūsu Tēvs, kas debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Un neliekaties saukties par mācītājiem, jo viens ir jūsu mācītājs, Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Bet tas lielākais no jums lai ir jūsu kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Un kas pats paaugstināsies, tam būs tapt pazemotam, un kas pats pazemosies, tam būs tapt paaugstinātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Bet ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi! Jo jūs aizslēdzat Debesu valstību priekš tiem cilvēkiem, un paši jūs neieejat, un neļaujat ieiet tiem, kas grib tikt iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi, jo jūs aprijat atraitņu namus un taisnojaties ar savām garām lūgšanām, tāpēc jūs dabūsiet jo grūtu sodību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi! Jo jūs pārstaigājat jūru un zemi, ka jūs vienu par Jūdu ticības biedri darāt, un kad tas tāds palicis, tad jūs viņu darāt par elles bērnu divkārt vairāk, nekā jūs paši esat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Ak vai jums, akliem ceļa rādītājiem! kas sakāt: ja kas pie Dieva nama zvērēšot, tas neesot nekas, bet ja kas pie Dieva nama zelta zvērēšot, tam tas jāpilda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Jūs ģeķi un aklie! Jo kas ir vairāk? Vai tas zelts, vai tas Dieva nams, kas to zeltu svētī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Un ja kas pie altāra zvērēšot, tas neesot nekas; bet ja kas zvērēšot pie tās dāvanas, kas tur virsū, tam tas jāpilda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Jūs ģeķi un aklie! Jo kas ir augstāks, vai tā dāvana, vai tas altāris, kas to dāvanu svētī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Tad nu, kas pie altāra zvēr, tas zvēr pie tā un pie visa, kas tur virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Un kas pie Dieva nama zvēr, tas zvēr pie tā un arī pie Tā, kas tur mīt iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Un kas pie debess zvēr, tas zvēr pie Dieva goda krēsla un pie Tā, kas tur sēž virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi! Jo jūs dodat to desmito tiesu no mētrām, dillēm un ķimenēm, un pametat to, kas tas grūtākais bauslībā, tiesu un sirds žēlastību un ticību. Šo jums bija darīt un to nepamest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Jūs aklie ceļa rādītāji, kas odus izkāšat un kamieļus aprijat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi! Jo jūs šķīstat biķera un bļodas ārpusi, bet no iekšpuses tie ir pilni ar laupījumu un negausību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Tu aklais farizejs, šķīsti papriekš biķera un bļodas iekšpusi, lai arī viņu ārpuse top šķīsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi! Jo jūs esat līdzināmi tiem nobaltētiem kapiem, kas no ārienes jauki uzskatāmi, bet no iekšienes ir piepildīti ar miroņu kauliem un visādu negantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Tā arī jūs no ārienes gan spīdat priekš ļaudīm kā taisni esoši, bet no iekšienes jūs esat liekulības un netaisnības pilni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Ak vai jums, rakstu mācītājiem un farizejiem! Jūs liekuļi! Jo jūs uztaisiet praviešu kapus un izgreznojiet taisno bedres,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Un sakāt: ja mēs būtu bijuši savu tēvu laikos, tad mēs nebūtu bijuši viņu biedri uz praviešu asins izliešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Tad nu jūs liecību dodat pret sev pašiem, ka jūs esat bērni tiem, kas tos praviešus nokāvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Jūs tad arī piepildāt savu tēvu mēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Jūs čūskas un odžu dzimums, kā jūs izbēgsiet no elles sodības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Tāpēc redzi, Es pie jums sūtu praviešus un gudrus un rakstu mācītājus; no tiem jūs citus nokausiet un krustā sitīsiet, un citus no tiem jūs šaustīsiet savās baznīcās un vajāsiet tos no vienas pilsētas uz otru:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Ka uz jums nāks visas tās taisnās asinis, kas izlietas virs zemes no tā taisnā Ābela asinīm līdz Zaharijas, Bereķijas dēla, asinīm, ko jūs nokāvuši starp Dieva namu un altāri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Patiesi, Es jums saku, ka tas visnotaļ nāks uz šo tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jeruzāleme! Jeruzāleme! tu, kas nokauj praviešus un ar akmeņiem nomētā, kas pie tevis sūtīti! Cik reiz Es tavus bērnus esmu gribējis sakrāt, kā vista sakrāj savus cālīšus apakš spārniem, bet jūs negribējāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Redzi, jūsu nams jums taps atstāts postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Jo Es jums saku: jūs Mani no šī laika neredzēsiet, tiekams jūs sacīsiet: slavēts, kas nāk Tā Kunga Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Un no Dieva nama izgājis Jēzus aizgāja. Un Viņa mācekļi piegāja pie Viņa un rādīja Viņam, kā tas Dieva nams uztaisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Bet Jēzus uz tiem sacīja: “Vai jūs to visu neredzat? Patiesi, Es jums saku, šeit akmens uz akmens netaps pamests, kas netaps nolauzīts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Un Viņam uz Eļļas kalna sēžot, tie mācekļi piegāja sevišķi un sacīja: “Saki mums, kad šīs lietas notiks, un kāda būs Tavas atnākšanas un pastara laika zīme?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Un Jēzus atbildēja un uz tiem sacīja: “Pielūkojiet, ka neviens jūs nepieviļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Jo tur daudz nāks Manā Vārdā un sacīs: es esmu Kristus, un daudz pievils.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Bet jūs dzirdēsiet karus un karu daudzināšanu. Lūkojiet, nebēdājaties, jo visam tam tā būs notikt, bet tad vēl nav tas gals.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Jo tad celsies tauta pret tautu un valsts pret valsti, un tad būs bada laiki un mēris un zemes trīcēšanas dažās vietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Bet viss tas būs tikai to lielo bēdu iesākums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Tad tie jūs nodos mokās un jūs nokaus, un jūs tapsiet ienīdēti no visiem ļaudīm Mana Vārda dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Un tad daudz apgrēcināsies, un viens otru nodos, un viens otru nīdēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Jo tad daudz viltīgi pravieši celsies un daudz pievils.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Un tāpēc, ka netaisnība ies vairumā, mīlestība pie daudziem izdzisīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Bet kas pastāv līdz galam, tas tiks izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Un šis evaņģēlijs no (Dieva) valstības visā pasaulē taps sludināts visām tautām, un tad nāks tas gals.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Kad jūs nu redzēsiet to izpostīšanas negantību, par ko pravietis Daniēls sacījis, ka tā stāv tai svētā vietā, (kas to lasa, tas lai to labi apdomā!)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Kas tad ir Jūdu zemē, tie lai bēg kalnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Un kas ir uz jumta, tas lai nekāpj zemē, kādu lietu no sava nama iznest;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'Un kas ir laukā, tas lai neatgriežas, savas drēbes paņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Bet vai tām grūtām un zīdītājām tanī laikā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Bet lūdziet, ka jūsu bēgšana nenotiek ziemas laikā nedz svētā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Jo tad būs tādas lielas bēdas, kādas nav bijušas no pasaules iesākuma līdz šim laikam, un kādas arī vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Un ja šīs dienas netaptu paīsinātas, tad neviens cilvēks netaptu izglābts; bet to izredzēto labad tās dienas taps paīsinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Ja tad kas uz jums sacīs: redzi, še ir Kristus, vai tur; tad neticiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Jo viltīgi kristi un viltīgi pravieši celsies un lielas zīmes un brīnumus darīs, ka arī tie izredzētie, ja tas varētu būt, uz alošanu taptu pievilti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Redziet, Es jums to papriekš esmu sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Tāpēc, kad tie uz jums sacīs: redzi, Viņš ir tuksnesī, - tad neejat ārā; redzi, Viņš ir kambaros, - tad neticat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Jo kā zibens izšaujas no rīta puses un atspīd līdz vakara pusei, tā būs arī Tā Cilvēka Dēla atnākšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Jo kur ir maita, tur arī ērgļi sakrāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Bet tūdaļ pēc šā laika bēdām saule taps aptumšota, un mēnesis nedos savu spīdumu, un zvaigznes kritīs no debess, un debess stiprumi kustināsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Un tad Tā Cilvēka Dēla zīme rādīsies debesī, un tad visas ciltis virs zemes kauks un redzēs To Cilvēka Dēlu nākam debess padebešos ar lielu spēku un godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Un Viņš sūtīs Savus eņģeļus ar lielu bazūnes skaņu, un tie Viņa izredzētos sakrās no tiem četriem vējiem, no viena debess gala līdz otram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Mācaties līdzību no vīģes koka: kad jau viņa zaros pumpuri metās, un lapas plaukst, tad jūs zināt, vasaru esam klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Tā arīdzan, kad jūs visu to redzēsiet, tad ziniet, ka tas ir tuvu priekš durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Patiesi, Es jums saku: šī cilts nezudīs, tiekams viss tas būs noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Debess un zeme zudīs, bet Mani vārdi nezudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Bet par to dienu un stundu neviens nezina, ne tie debesu eņģeļi, kā vien Mans Tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Bet tā, kā bija Noas dienās, tāpat arī būs Tā Cilvēka Dēla atnākšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Jo itin kā tie tais dienās priekš tiem grēku plūdiem rija un plītēja, precējās un laulībā devās līdz tai dienai, kad Noa iegāja šķirstā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'Un tie neņēma vērā, tiekams tie plūdi nāca un visus aizņēma; tāpat būs arī Tā Cilvēka Dēla atnākšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Tad divi būs laukā; viens taps pieņemts, otrs atmests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Divas mals dzirnavās, viena taps pieņemta, otra atmesta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Tāpēc esiet modrīgi, jo jūs nezināt, kurā stundā jūsu Kungs nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Bet to protiet, kad nama kungs zinātu, kurā stundā zaglis nāks, tad tas paliktu nomodā un neļautu savā namā ielauzties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Tāpēc arī jūs esiet gatavi, jo tanī stundā, kurā jūs nedomājiet, Tas Cilvēka Dēls nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kurš nu ir tas uzticīgais un gudrais kalps, ko tas kungs iecēlis pār savu saimi, tiem maizi dot savā laikā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Svētīgs tas kalps, ko tas kungs pārnācis atradīs tā darām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Patiesi, Es jums saku, ka viņš to iecels pār visām savām mantām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Bet ja tas ļaunais kalps savā sirdī sacīs: mans kungs kavējās nakt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'Un iesāks savus darba biedrus sist un ar tiem plītniekiem rīt un plītēt:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Tad tā kalpa kungs nāks tādā dienā, kad šis negaida, un tādā stundā, ko šis nezina,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Un to šķels pušu un tam dos algu ar tiem liekuļiem. Tur būs raudāšana un zobu trīcēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Tad Debesu valstība būs līdzīga desmit jumpravām, kas savus eļļas lukturus ņēma un izgāja brūtgānam pretim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Bet piecas no tām bija gudras, un piecas bija ģeķīgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Kas bija ģeķīgas, tās paņēma savus eļļas lukturus, bet eļļu tās neņēma līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Bet tās gudrās paņēma eļļu savos traukos līdz ar tiem eļļas lukturiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Kad nu tas brūtgāns kavējās, tad visas aizmiga un snauda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Bet nakts vidū balss atskanēja: redzi, brūtgāns nāk, ejat ārā viņam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tad visas tās jumpravas cēlās un sataisīja savus eļļas lukturus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Bet tās ģeķīgās sacīja uz tām gudrām: dodiet mums no savas eļļas, jo mūsu eļļas sveces izdziest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Bet tās gudrās atbildēja un sacīja: ne tā, ka nepietrūkst mums un jums, bet noejat labāk pie pārdevējiem un pērkat sev.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Un kad tās nogāja pirkt, tad tas brūtgāns nāca, un kas bija gatavas, iegāja ar viņu kāzās, un durvis tapa aizslēgtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Pēc arī tās citas jumpravas atnāca un sacīja: Kungs, Kungs, atdari mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Bet tas atbildēja un sacīja: patiesi, es jums saku, es jūs nepazīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Tāpēc esiet modrīgi, jo jūs nezināt ne to dienu, nedz to stundu, kurā Tas Cilvēka Dēls nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Jo tā kā viens cilvēks citur aiziedams aicināja savus kalpus un tiem iedeva savu mantu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Un vienam deva piecus podus un otram divus un trešam vienu, ikkatram pēc viņa spēka, un tūdaļ aizgāja projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Tad tas nogāja, kas piecus podus bija dabūjis, un pelnījās ar tiem un sapelnīja citus piecus podus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Tā arī, kas divus dabūjis, ir tas sapelnīja divus citus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Bet tas, kas vienu bija dabūjis, nogāja un to ieraka zemē un paslēpa sava kunga naudu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Bet pēc ilga laika šo kalpu kungs nāca un ar tiem izlīdzinājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Un tas, kas bija dabūjis tos piecus podus, nāca un atnesa vēl citus piecus podus un sacīja: kungs, tu man piecus podus esi iedevis; redzi, es pāri par tiem esmu sapelnījis vēl citus piecus podus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Un viņa kungs uz to sacīja: labi, tu godīgais un uzticīgais kalps; pie mazuma tu esi bijis uzticīgs, es tevi iecelšu pār daudzumu; ieej sava kunga priekā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Un tas arīdzan, kas bija dabūjis tos divus podus, atnācis sacīja: kungs, tu man divus podus esi iedevis; redzi, es pāri par tiem esmu sapelnījis vēl divus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Viņa kungs uz to sacīja: labi, tu godīgais un uzticīgais kalps. Tu pie mazuma esi bijis uzticīgs, es tevi iecelšu pār daudzumu; ieej sava kunga priekā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Tad arī tas, kas bija dabūjis to vienu podu, piegājis sacīja: kungs, es zināju tevi bargu cilvēku esam, ka tu pļauj, kur tu neesi sējis, un krāji, kur tu neesi kaisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Un bīdamies es nogāju un apslēpu tavu podu zemē; redzi še ir, kas tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Bet viņa kungs atbildēja un uz viņu sacīja: tu blēdīgais un kūtrais kalps, ja tu zināji, ka es pļauju, kur es neesmu sējis, un krāju, kur es neesmu kaisījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Tad tev bija dot manu naudu mijējiem; un pārnācis es būtu atdabūjis ar augļiem, kas man pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Tāpēc ņemiet no viņa to podu un dodiet tam, kam ir desmit podi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Jo ikkatram, kam ir, tam taps dots, un tam būs papilnam; bet no tā, kam nav, taps vēl atņemts, kas tam ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Un to nelietīgo kalpu izmetiet galējā tumsībā, tur būs raudāšana un zobu trīcēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Bet kad Tas Cilvēka Dēls nāks Savā godībā, un visi svētie eņģeļi līdz ar Viņu, tad Viņš sēdēs uz Sava godības krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Un visi ļaudis taps sapulcināti Viņa priekšā, un Viņš tos šķirs tā, kā gans avis šķir no āžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Un stādīs tās avis pa Savu labo roku, bet tos āžus pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Tad Tas Ķēniņš sacīs uz tiem pie Savas labās rokas: nāciet šurp, jūs Mana Tēva svētītie, iemantojiet to Valstību, kas jums ir sataisīta no pasaules iesākuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Jo Es biju izsalcis, un jūs Mani esat ēdinājuši; Es biju izslāpis, un jūs Mani esat dzirdinājuši; Es biju viesis, un jūs Mani esat uzņēmuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Es biju pliks, un jūs Mani esat ģērbuši; Es biju nevesels, un jūs Mani esat apmeklējuši; Es biju cietumā, un jūs pie Manis esat nākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tad tie taisnie Viņam atbildēs sacīdami: Kungs, kad mēs Tevi esam redzējuši izsalkušu un Tevi esam ēdinājuši? Vai izslāpušu un Tevi esam dzirdinājuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Kad mēs Tevi esam redzējuši kā viesi un uzņēmuši? Vai pliku un Tevi esam ģērbuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Kad mēs Tevi esam redzējuši neveselu vai cietumā un pie Tevis esam nākuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Tad Tas Ķēniņš tiem atbildēs un sacīs: patiesi, Es jums saku, ko jūs darījuši vienam no šiem Maniem vismazākajiem brāļiem, to jūs Man esat darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Tad viņš arī uz tiem pa kreiso roku sacīs: ejat nost no Manis, jūs nolādētie, mūžīgā ugunī, kas ir sataisīts velnam un viņa eņģeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Jo Es biju izsalcis, un jūs Mani neesat ēdinājuši: Es biju izslāpis, un jūs Mani neesat dzirdinājuši:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Es biju viesis, un jūs Mani neesat uzņēmuši; Es biju pliks, un jūs Mani neesat ģērbuši; Es biju nevesels un cietumā, un jūs Mani neesat apmeklējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tad tie arīdzan Viņam atbildēs un sacīs: Kungs, kad mēs Tevi esam redzējuši izsalkušu vai izslāpušu, vai viesi, vai pliku, vai neveselu, vai cietumā un Tev neesam kalpojuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Tad Viņš atbildēs un sacīs: patiesi, Es jums saku, ko jūs neesat darījuši vienam no šiem vismazākajiem, to jūs Man arīdzan neesat darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Un tie ieies mūžīgās mokās, bet tie taisnie mūžīgā dzīvošanā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Un notikās, kad Jēzus visus šos vārdus bija pabeidzis, tad Viņš uz Saviem mācekļiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '“Jūs zināt, ka pēc divām dienām būs Lieldiena, un Tas Cilvēka Dēls kļūs nodots, ka Tas taptu krustā sists.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tad sapulcējās tie augstie priesteri un rakstu mācītāji un ļaužu vecaji tā augstā priestera namā, kam vārds bija Kajafas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'Un tie sarunājās, kā tie Jēzu ar viltu dabūtu rokā un nokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Bet tie sacīja: “Tikai ne uz svētkiem, lai ļaudīs neceļas dumpis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Un kad Jēzus bija iekš Betanijas, Sīmaņa, tā spitālīgā, namā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Tad viena sieva pie Tā piegāja, tai bija akmens trauciņš ar dārgām zālēm, un tā lēja tās uz Viņa galvu, Tam pie galda sēžot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Kad tie mācekļi to redzēja, tad tie apskaitās un sacīja: “Kālabad šī izšķērdēšana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Tās zāles varēja dārgi pārdot un izdalīt nabagiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Bet Jēzus to nomanījis uz tiem sacīja: “Kam jūs šo sievu apgrūtinājiet? Jo tā labu darbu pie Manis darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Jo nabagi ir arvienu pie jums, bet Es neesmu arvienu pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Jo tās zāles izliedama pār Manu miesu, tā to darījusi tādēļ, ka Man būs tapt apraktam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Patiesi, Es jums saku: kur vien visā pasaulē šo prieka vārdu sludinās, tur arī sacīs, ko šī ir darījusi, viņai par piemiņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Tad viens no tiem divpadsmit, kas tapa saukts Jūdas Iskariots, pie tiem augstiem priesteriem nogājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Sacīja: “Ko jūs man gribat dot, tad es jums Viņu nodošu?” Tie tam iedeva trīsdesmit sudraba gabalus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Un no tā brīža tas meklēja izdevīgu laiku, ka Viņu nodotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Bet pirmā neraudzētās maizes dienā tie mācekļi gāja pie Jēzus un sacīja uz Viņu: “Kur Tu gribi, lai mēs Tev sataisām Lieldienas jēru ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Bet Viņš sacīja: “Ejat pilsētā pie kāda un sakāt tam: Tas Mācītājs saka: Mans laiks ir tuvu klātu, Es turēšu pie tevis Lieldienu ar Saviem mācekļiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Un tie mācekļi darīja, kā Jēzus tiem bija pavēlējis, un sataisīja Lieldienas jēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Un kad vakars metās, Viņš apsēdās ar tiem divpadsmit,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Un sacīja tiem ēdot: “Patiesi, Es jums saku, viens no jums Mani nodos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Un tie ļoti noskuma, un ikviens no tiem iesāka uz Viņu sacīt: “Kungs, vai es tas esmu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Bet Viņš atbildēja un sacīja: “Tas, kas ar Mani savu roku mērc bļodā, tas Mani nodos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Tas Cilvēka Dēls gan tā aiziet, kā par Viņu rakstīts. Bet vai tam cilvēkam, caur ko Tas Cilvēka Dēls top nodots; tam būtu labāki, ka tas cilvēks nemaz nebūtu dzimis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Bet Jūdas, kas Viņu nodeva, atbildēja un sacīja: “Vai es tas esmu, Rabbi?” Viņš uz to sacīja: “Tu to saki.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Bet tiem vēl ēdot, Jēzus ņēma to maizi, un svētījis pārlauza un deva to Saviem mācekļiem un sacīja: “Ņemiet, ēdiet, tā ir Mana miesa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Un to biķeri ņēma un pateicās, Viņš tiem to deva un sacīja: “Dzeriet visi no tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Jo šīs ir Manas asinis, tās jaunās derības asinis, kas par daudziem top izlietas par grēku piedošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Bet Es jums saku, ka Es no šā laika vairs nedzeršu no šiem vīnakoka augļiem līdz tai dienai, kad Es to ar jums no jauna dzeršu Sava Tēva valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Un to pateicības dziesmu nodziedājuši, tie gāja ārā uz Eļļas kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tad Jēzus uz tiem saka: “Jūs visi šai naktī pie Manis apgrēcināsities, jo stāv rakstīts: Es to ganu sitīšu un tā ganāmā pulka avis izklīdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Bet kad Es būšu augšāmcēlies, tad Es jūsu priekšā noiešu uz Galileju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Bet Pēteris atbildēja un uz Viņu sacīja: “Kad tie arī visi pie Tevis apgrēcinātos, tad tomēr es nemūžam neapgrēcināšos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jēzus uz to sacīja: “Patiesi, Es tev saku: šinī naktī, pirms gailis dziedās, tu Mani trīsreiz aizliegsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pēteris uz Viņu saka: “Jebšu man ar Tevi būtu jāmirst, taču es Tevi negribu aizliegt.” Tāpat arī visi mācekļi sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tad Jēzus nāk ar tiem uz vienu muižu ar vārdu Getzemane un saka uz tiem mācekļiem: “Sēžaties šeitan, kamēr Es tur noeju un Dievu lūdzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Un Viņš ņēma līdz Pēteri un tos divus Cebedeja dēlus un iesāka noskumties un baiļoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Tad Viņš uz tiem saka: “Mana dvēsele ir visai noskumusi līdz nāvei; paliekat šeitan un esat ar Mani nomodā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Un maķenīt pagājis Viņš krita uz Savu vaigu pie zemes, Dievu lūgdams un sacīdams: “Mans Tēvs, ja tas var būt, tad lai šis biķeris Man iet garām, tomēr ne kā Es gribu, bet kā Tu gribi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Un Viņš nāk pie tiem mācekļiem un atrod tos guļam, un saka uz Pēteri: “Tā tad jūs nespējāt nevienu pašu stundu ar Mani būt nomodā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Esiet modrīgi un lūdziet Dievu, ka jūs neiekrītat kārdināšanā. Gars gan ir labprātīgs, bet miesa ir vāja.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Viņš atkal otru lāgu nogājis, lūdza sacīdams: “Mans Tēvs, ja šis biķeris Man nevar iet garām, ka Es to nedzeru, tad lai notiek Tavs prāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Un Viņš nāk un atrod tos atkal guļam, jo viņu acis bija miega pilnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Un Viņš tos pameta, un atkal nogāja un lūdza Dievu trešu lāgu, tos pašus vārdus sacīdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Tad Viņš nāk pie Saviem mācekļiem, un uz tiem saka: “Guliet nu vēl un dusiet! redzi, tā stunda ir klāt, un Tas Cilvēka Dēls top nodots grēcinieku rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Ceļaties, ejam! Redzi, kas Mani nodod, ir klāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Un Viņam vēl runājot, redzi, tad nāca Jūdas, viens no tiem divpadsmit un līdz ar to liels pulks ar zobeniem un nūjām no tiem augstiem priesteriem un ļaužu vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Bet kas Viņu nodeva, tas tiem bija devis tādu zīmi un sacījis: “Kuru es skūpstīšu, tas ir Tas, To gūstat.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Un tūdaļ viņš pie Jēzus piegāja un sacīja: “Esi sveicināts, Rabbi!” un Viņu skūpstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Bet Jēzus uz to sacīja: “Draugs, kāpēc tu še esi?” Tad tie piegāja un pielika rokas pie Jēzus un To saņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Un redzi, viens no tiem, kas pie Jēzus bija, roku izstiepis, izvilka savu zobenu un cirta tā augstā priestera kalpam un tam nocirta ausi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tad Jēzus uz to saka: “Bāz savu zobenu savā vietā, jo visi, kas zobenu ņem, tie caur zobenu tiks nomaitāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Jeb vai tev šķiet, ka Es nevarētu tagad Savu Tēvu lūgt, un Viņš Man nevarētu dot vairāk nekā divpadsmit leģionus eņģeļu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Kā tad tie raksti taptu piepildīti? Jo tam būs tā notikt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Tanī pašā stundā Jēzus sacīja uz to pulku: “Kā pie slepkavas jūs esat izgājuši ar zobeniem un nūjām, Mani gūstīt. Ikdienas Es pie jums esmu sēdējis un mācījis Dieva namā, un jūs Mani neesat gūstījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Bet viss tas noticis, ka praviešu raksti piepildītos.” Tad visi mācekļi Viņu atstāja un bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Bet tie Jēzu saņēma un To noveda pie tā augstā priestera Kajafasa, kur tie rakstu mācītāji un vecaji bija sapulcējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Bet Pēteris no tālienes Viņam gāja pakaļ līdz tā augstā priestera namam, un iegājis tas apsēdās pie tiem sulaiņiem, nolūkot to galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Bet tie augstie priesteri un tie vecaji un visa tā augstā tiesa meklēja viltīgu liecību pret Jēzu, ka Viņu varētu nokaut;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Un neatrada, un jebšu gan daudz viltīgu liecinieku nāca priekšā, tomēr neatrada nenieka; bet visupēc divi viltīgi liecinieki nāca priekšā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Un sacīja: “Šis ir sacījis: Es Dieva namu varu noplēst un trijās dienās to uztaisīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Un tas augstais priesteris pacēlās un uz Viņu sacīja: “Vai Tu nekā neatbildi uz to, ko tie pret Tevi liecina?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Bet Jēzus cieta klusu; un tas augstais priesteris atbildēja un uz To sacīja: “Pie tā dzīvā Dieva es Tevi zvērinu, saki mums: vai Tu esi Kristus, Dieva Dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jēzus uz to saka: “Tu to esi sacījis. Bet Es jums saku: no šī laika jūs redzēsiet To Cilvēka Dēlu sēžam pie Tā Visspēcīgā labās rokas un nākam uz debess padebešiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tad tas augstais priesteris saplēsa savas drēbes un sacīja: “Viņš Dievu zaimojis: kam mums vēl liecinieku vajag? Redziet, tagad jūs Viņa Dieva zaimošanu esat dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Kā jums šķiet?” Bet tie atbildēja un sacīja: “Viņš nāvi pelnījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Tad tie Viņam spļāva vaigā un Viņu pliķēja; bet citi Viņu sita ar dūrēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Un sacīja: “Pravietis būdams, saki mums, Kristu, - kurš ir tas, kas Tevi sitis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Bet Pēteris sēdēja priekšnamā. Un viena jauna meita nāca pie viņa un sacīja: “Tu arīdzan biji ar To Jēzu no Galilejas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Bet viņš liedzās priekš visiem sacīdams: “Es nezinu, ko tu runā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Un kad viņš priekš vārtiem bija izgājis, cita viņu redzēja un saka uz tiem, kas tur bija: “Šis arīdzan bija pie Tā Jēzus no Nacaretes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Un viņš atkal liedzās zvērēdams: “Es to Cilvēku nepazīstu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Un par mazu brīdi tie, kas tur stāvēja, piegāja un uz Pēteri sacīja: “Patiesi, tu esi viens no tiem; jo no tavas valodas to var noprast.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tad viņš iesāka nolādēties un nodievoties: “Es to Cilvēku nepazīstu.” Un tūdaļ gailis dziedāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Un Pēteris pieminēja Jēzus vārdus, ko Viņš tam bija sacījis: “Pirms gailis dziedās, tu Mani trīsreiz aizliegsi.” Un ārā izgājis viņš raudāja gauži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Bet rīta agrumā visi augstie priesteri un ļaužu vecaji sarunājās pret Jēzu, ka Viņu nonāvētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Un Viņu saistīja, aizveda un nodeva zemes valdītājam Poncium Pilatum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Kad Jūdas, kas Viņu nodeva, redzēja, ka Viņš bija pazudināts; tad tas tam bija žēl, un tas atnesa atpakaļ tos trīsdesmit sudraba gabalus tiem augstiem priesteriem un vecajiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Un sacīja: “Es esmu grēkojis, nenoziedzīgas asinis nododams.” Bet tie sacīja: “Kas mums par to, bēdas? Raugi tu pats.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Un tos sudraba gabalus Dieva namā nometis, tas aizgāja un pakārās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Bet tie augstie priesteri tos sudraba gabalus ņēma un sacīja: “Tas nepieklājās, ka mēs tos metam Dieva šķirstā, jo tā ir asins nauda.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Bet tie sarunājās un par tiem pirka to podnieka tīrumu svešiniekiem par kapsētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Tāpēc tas tīrums ir nosaukts asins tīrums līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Tad ir piepildīts, ko pravietis Jeremija runājis sacīdams: “Un tie ir ņēmuši trīsdesmit sudraba gabalus, to maksu par To Visdārgāko, ko tie pirkuši no Israēla bērniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'Un tos devuši par to podnieka tīrumu, kā Tas Kungs man ir pavēlējis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Bet Jēzus stāvēja zemes valdītāja priekšā, un zemes valdītājs Viņam vaicāja un sacīja: “Vai Tu esi tas Jūdu ķēniņš?” Bet Jēzus uz viņu sacīja: “Tu to saki.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Un kad viņš no tiem augstiem priesteriem un vecajiem tapa apsūdzēts, viņš nekā neatbildēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tad Pilatus uz Viņu saka: “Vai Tu nedzirdi, cik briesmīgi tie pret Tevi liecina?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Un Viņš tam neatbildēja ne uz vienu vārdu, tā ka tas zemes valdītājs it ļoti brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Bet svētkos zemes valdītājs bija ieradis tiem ļaudīm atlaist vienu cietumnieku, kādu tie gribēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Bet to brīdi tam bija viens zināms cietumnieks, Baraba vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Un kad tie bija sapulcējušies, Pilatus uz tiem sacīja: “Kuru jūs gribat, lai es jums atlaižu? Barabu vai Jēzu, kas top saukts Kristus?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Jo viņš zināja, ka tie To no skaudības bija nodevuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Bet viņam uz soģa krēsla sēžot, viņa sieva pie tā sūtīja un sacīja: “Pielūko, ka tev nekas nav ar šo taisno, jo es šo nakti sapnī daudz esmu cietusi Viņa dēļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Bet tie augstie priesteri un vecaji pārrunāja tos ļaudis, izlūgties Barabu, bet Jēzu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Un zemes valdītājs atbildēja un uz tiem sacīja: “Kuru jūs gribat no šiem diviem, lai es jums atlaižu?” Bet tie sacīja: “Barabu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Tad Pilatus uz tiem saka: “Ko tad lai es daru ar Jēzu, kas top saukts Kristus?” Tie visi saka: “Sit To krustā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Bet zemes valdītājs sacīja: “Ko tad Viņš ļauna darījis?” Bet tie vēl vairāk brēca un sacīja: “Sit To krustā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Bet kad Pilatus redzēja, ka viņš nenieka nespēja izdarīt, bet ka jo liels troksnis cēlās, tad viņš ņēma ūdeni un mazgāja rokas ļaužu priekšā un sacīja: “Es esmu nenoziedzīgs pie šī taisnā asinīm; raugāt paši!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Un visi ļaudis atbildēja un sacīja: “Viņa asinis lai nāk pār mums un pār mūsu bērniem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Tad viņš tiem to Barabu atlaida, bet Jēzu šauta un nodeva, ka taptu krustā sists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tad zemes valdītāja karavīri ņēma Jēzu pie sevis tiesas namā, un sasauca ap Viņu visu to pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Un tie Viņu noģērba un Viņam aplika purpura mēteli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Un ērkšķu kroni nopinuši lika uz Viņa galvu un deva Tam niedri labajā rokā, un locīja ceļus Viņa priekšā, Viņu apsmēja un uz Viņu sacīja: “Sveiks, Jūdu ķēniņ!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Un tie Viņam spļāva acīs, ņēma to niedri un sita Viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Un kad Viņu bija apmēdījuši, tad tie Viņam novilka to mēteli un Tam apvilka Viņa paša drēbes, un Viņu noveda, ka taptu krustā sists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Bet iziedami tie atrada vienu cilvēku no Kirenes, vārdā Sīmani; to tie spieda, Viņam to krustu nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Un nākuši uz to vietu, ko sauc par Golgatu, tas ir pieres vieta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Tie Viņam deva dzert etiķi ar žulti samaisītu, un kad Viņš to baudīja, tad Viņš to negribēja dzert.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Un Viņu krustā situši, tie izdalīja Viņa drēbes, kauliņus mezdami; ka piepildītos, ko tas pravietis sacījis: “Tie Manas drēbes savā starpā izdalījuši un par Maniem svārkiem kauliņus metuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Un tie sēdēja un sargāja Viņu turpat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Un lika pār Viņa galvu Viņa nāves vainu tā rakstītu: Šis ir Jēzus, tas Jūdu Ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Tad divi slepkavas ar Viņu tapa krustā sisti, viens pa labo, otrs pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Bet tie, kas gāja garām, zaimoja Viņu, kratīja savas galvas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'Un sacīja: “Tu, kas Dieva namu noplēsi un trijās dienās atkal uztaisi, atpestī pats Sevi; ja Tu esi Dieva Dēls, tad kāp no krusta zemē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Tāpat arī tie augstie priesteri Viņu apmēdīja līdz ar tiem rakstu mācītājiem un vecajiem un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '“Citus Viņš pestījis un Sevi pašu nevar pestīt. Ja Viņš tas Israēla Ķēniņš, lai Viņš nu nokāpj no krusta; tad mēs Viņam ticēsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Viņš Dievam ir uzticējies, lai Tas Viņu atpestī, ja tas Tam tīk; to Viņš ir sacījis: Es esmu Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'To Viņam arī tie slepkavas pārmeta, kas līdz ar Viņu bija krustā sisti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Bet no sestās stundas metās tumšs pār visu to zemi līdz devītajai stundai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Bet ap devīto stundu Jēzus brēca lielā brēkšanā un sacīja: “Eli, Eli, lama zabaktani?” tas ir: Mans Dievs, Mans Dievs, kāpēc Tu Mani esi atstājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Bet citi no tiem, kas tur stāvēja, kad tie to dzirdēja, sacīja: “Šis sauc Eliju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Un tūlīt viens no tiem notecēja un sūkli ņēmis to pildīja ar etiķi un lika uz niedri un Viņu dzirdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Bet tie citi sacīja: “Gaidi, lūkosim, vai Elija nāks un Viņu pestīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Bet Jēzus atkal lielā brēkšanā brēcis izlaida dvēseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Un redzi, tas priekškaramais auts Dieva namā pārplīsa divējos gabalos no augšas līdz zemei, un zeme trīcēja, un akmens kalni plīsa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Un kapi atdarījās, un daudz miesu no svētiem, kas gulēja, cēlās augšām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'Un no kapiem izgājuši pēc Viņa augšām celšanās tie nāca tai svētā pilsētā un parādījās daudziem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Bet tas kapteinis un tie, kas pie Viņa bija un Jēzu sargāja, redzēdami to zemes trīcēšanu un kas tur notika, izbijās ļoti un sacīja: “Patiesi, Šis bija Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Bet tur bija daudz sievas, kas Jēzum bija pakaļ gājušas no Galilejas un Viņam kalpojušas; tās skatījās no tālienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Starp tām bija Marija Madaļa un Marija, Jēkaba un Jāzepa māte, un tā Cebedeja dēlu māte.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Bet vakarā nāca viens bagāts cilvēks no Arimatijas, Jāzeps vārdā, kas arī bija Jēzus māceklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Šis nogājis pie Pilatus izlūdzās Jēzus miesas. Tad Pilatus pavēlēja, tās dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Un Jāzeps tās miesas ņēmis ietina smalkā audeklī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'Un ielika savā jaunā kapā, ko viņš klintī bija izcirtis, un lielu akmeni priekš kapa durvīm pievēlis, viņš aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Bet tur bija Marija Madaļa un tā otra Marija, tās apsēdās tam kapam pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Bet otrā dienā, kas nāk pēc tās sataisīšanas dienas, tie augstie priesteri un farizeji pie Pilatus sapulcējās');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Un sacīja: “Kungs, mēs atminamies, ka Šis viltnieks vēl dzīvs būdams sacīja: “Pēc trim dienām Es gribu augšāmcelties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Tāpēc pavēli, ka tas kaps stipri top apsargāts līdz trešai dienai, ka Viņa mācekļi naktī nenāk un Viņu nenozog, un tiem ļaudīm nesaka: “Viņš no miroņiem ir augšāmcēlies.” Un tā pēdēja viltība būs niknāka nekā tā pirmā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Bet Pilatus uz tiem sacīja: “Te jums ir sargi, ejat un sargājiet, kā zinādami.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Tie nogāja un apsargāja to kapu ar sargiem un aizzieģelēja to akmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Bet pēc tās svētās dienas, pirmai nedēļas dienai austot, Marija Madaļa un tā otra Marija nāca, to kapu apraudzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Un redzi, liela zemes trīcēšana notika, jo Tā Kunga eņģelis, no debesīm nonācis, piegāja un to akmeni novēla no tām durvīm un uzsēdās virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Un viņa ģīmis bija kā zibens, un tā drēbe tik balta kā sniegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Bet tie sargi no lielām izbailēm drebēja un palika tā kā miruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Bet tas eņģelis uzrunāja un uz tām sievām sacīja: “Nebīstaties, jo es zinu, ka jūs meklējat Jēzu, to krustā sisto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Viņš nav šeitan, jo Viņš ir augšāmcēlies, tā kā Viņš ir sacījis. Nāciet šurp, raugāt to vietu, kur Tas Kungs gulējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Un ejat steigšus un sakāt Viņa mācekļiem, ka Viņš no miroņiem ir augšāmcēlies; un redzi, Viņš noies jūsu priekšā uz Galileju, tur jūs Viņu redzēsiet. Redzi, es jums to esmu sacījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Un tās izgāja ātri no kapa ārā ar bijāšanu un lielu prieku, un tecēja, Viņa mācekļiem to stāstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Bet kad tās gāja, Viņa mācekļiem to vēsti nest, redzi, tad Jēzus tās sastapa un sacīja: “Esiet sveicinātas!” Bet tās piegāja pie Viņa, apkampa Viņa kājas un krita Viņa priekšā pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tad Jēzus uz tām saka: “Nebīstaties! Ejat, stāstiet to Maniem brāļiem, lai tie noiet uz Galileju, un tur tie Mani redzēs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Bet šīm noejot, redzi, kādi no tiem sargiem pilsētā nākuši stāstīja tiem augstiem priesteriem visu to, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Un ar tiem vecajiem sapulcējušies, tie sarunājās un deva tiem karavīriem papilnam naudas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Un sacīja: “Sakāt, ka Viņa mācekļi naktī nākuši un mums guļot To izzaguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Ja tas tam zemes valdītājam taps zināms, mēs to gan pārrunāsim, un jūs varēsiet palikt bez bēdām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Un viņi to naudu ņēmuši, darīja, kā bija izmācīti. Un šī valoda ir izpaudusies pie tiem Jūdiem līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Bet tie vienpadsmit mācekļi nogāja uz Galileju, uz to kalnu, kur tiem Jēzus bija pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Un kad tie Viņu redzēja, tad tie Viņu pielūdza, bet citi vēl šaubījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Un Jēzus piegājis, runāja ar tiem un sacīja: “Man ir dota visa vara debesīs un virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Tāpēc ejiet un dariet par mācekļiem visus ļaudis, tos kristīdami Tā Tēva un Tā Dēla un Tā Svētā Gara vārdā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Tos mācīdami turēt visu, ko Es jums esmu pavēlējis; un, redzi, Es esmu pie jums ikdienas līdz pasaules galam. Āmen.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Jēzus Kristus, Dieva Dēla, evaņģēlija iesākums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Itin kā ir rakstīts pie tiem praviešiem: “Redzi, Es sūtu Savu eņģeli Tavā priekšā, kam būs sataisīt Tavu ceļu;”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '“Saucēja balss tuksnesī: sataisiet Tam Kungam ceļu, dariet līdzenas Viņa tekas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Notikās, ka Jānis kristīja tuksnesī un sludināja kristību uz atgriešanos no grēkiem par grēku piedošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Un pie viņa izgāja visa Jūdu zeme un visi Jeruzālemes ļaudis; un tie no viņa tapa kristīti Jardānes upē, izsūdzēdami savus grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Un Jānis bija apģērbies ar kamieļu spalvas drēbēm un ādas jostu ap saviem gurniem, un ēda siseņus un kameņu medu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Un sludināja sacīdams: “Viens jo spēcīgāks nekā es nāk pēc manis, kam es neesmu cienīgs locīdamies atraisīt Viņa kurpju siksnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Es gan jūs esmu kristījis ar ūdeni, bet Viņš jūs kristīs ar Svēto Garu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Un notikās tanīs dienās, ka Jēzus nāca no Nacaretes iekš Galilejas un Jardānē no Jāņa tapa kristīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Un tūdaļ no ūdens izkāpdams Viņš redzēja debesis atvērtas un to Garu kā balodi uz Sevi nolaižamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Un balss notika no debesīm: “Tu esi Mans mīļais Dēls, pie kā Man ir labs prāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Un Tas Gars Viņu tūdaļ aizveda tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Un Viņš bija tuksnesī četrdesmit dienas un tapa kārdināts no sātana un bija pie zvēriem. Un eņģeļi Viņam kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Bet pēc tam, kad Jānis bija nodots, Jēzus nāca uz Galileju, sludinādams Dieva evaņģēliju');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Un sacīdams: “Tas laiks ir piepildīts, un Dieva valstība ir tuvu atnākusi! Atgriežaties no grēkiem un ticat uz to evaņģēliju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Un pie Galilejas jūras staigādams, Viņš redzēja Sīmani un Andreju, viņa brāli, tīklu jūrā metam; jo tie bija zvejnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Un Jēzus uz tiem sacīja: “Nāciet Man pakaļ, un Es jūs darīšu par cilvēku zvejniekiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Un tūdaļ savus tīklus atstājuši, tie Viņam gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Un no turienes maķenīt pagājis, Viņš redzēja Jēkabu, Cebedeja dēlu, un Jāni, viņa brāli, un tos laivā tīklus lāpām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Un tūdaļ Viņš tos aicināja. Un savu tēvu Cebedeju ar tiem algādžiem laivā atstājuši, tie nogāja Viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Un tie nāca Kapernaūmā. Un tūdaļ svētdienā Viņš iegāja baznīcā un mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Un tie izbrīnījās par Viņa mācību, jo Viņš tos mācīja tā kā pats varenais un nekā tie rakstu mācītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Un viņu baznīcā bija cilvēks ar nešķīstu garu, un tas brēca');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Sacīdams: Vai! Kas mums ar Tevi, Jēzu no Nacaretes? Vai Tu esi nācis, mūs nomaitāt? Mēs Tevi pazīstam, kas Tu esi, Tas Dieva Svētais.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Un Jēzus viņu apdraudēja sacīdams: “Palieci klusu un izej no tā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Un to raustīdams un ar stipru balsi brēkdams, tas nešķīstais gars no tā izgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Un tie visi iztrūcinājās, tā ka tie savā starpā apjautājās sacīdami: “Kas tas ir? Kas tā tāda jauna mācība? Jo Viņš ar varu pat tiem nešķīstiem gariem pavēl, un tie Viņam paklausa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Un tūdaļ Viņa slava izgāja visapkārt pa Galilejas tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Un no baznīcas izgājuši, tie tūdaļ nāca Sīmaņa un Andreja namā ar Jēkabu un Jāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Un Sīmaņa sievas māte gulēja ar drudzi, un tie Viņam tūdaļ par to sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Un piegājis Viņš to uzcēla un to ņēma pie rokas, un drudzis tūlīt no tās atstājās, un viņa tiem kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Un kad vakars metās, un saule bija nogājusi, tad tie pie Viņa nesa visādus neveselus un velna apsēstus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Un visa pilsēta priekš durvīm bija sapulcējusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Un Viņš dziedināja daudz neveselus no dažādām slimībām un izdzina daudz velnus, un Viņš tiem velniem neļāva runāt, jo tie Viņu pazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Un no rīta gaiļos Viņš cēlās un izgāja; un nogāja kādā vientuļā vietā un tur Dievu pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Un Sīmanis līdz ar tiem, kas pie Viņa bija, Viņam steidzās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Un Viņu atraduši, tie uz Viņu sacīja: “Visi Tevi meklē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Un Viņš uz tiem sacīja: “Noejam tuvējos miestos, ka Es tur arīdzan sludināju; jo tāpēc Es esmu izgājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Un Viņš sludināja viņu baznīcās pa visu Galileju un izdzina velnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Un viens spitālīgs nāca pie Viņa, Viņu lūgdams un Viņa priekšā ceļos mezdamies un uz Viņu sacīdams: “Ja Tu gribi, tad Tu mani vari šķīstīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Un Jēzus sirdī aizkustināts roku izstiepa, to aizskāra un uz to sacīja: “Es gribu, topi šķīsts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Un Viņam runājot tūlīt spitālība no tā nogāja, un tas palika šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Un Viņš to apdraudēja un to tūlīt aizdzina');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Un uz to sacīja: “Raugi, nesaki nevienam neko, bet ej, rādies priesterim un nones par savu šķīstīšanu, ko Mozus ir pavēlējis, viņiem par liecību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Bet tas izgājis iesāka daudz pasludināt un šo lietu izpaust, tā ka Jēzus ļaudīm redzot vairs nevarēja ieiet pilsētā. Bet Viņš bija laukā vientuļās vietās, un no visām malām tie nāca pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Un pēc kādām dienām Viņš gāja atkal uz Kapernaūmu, un ļaudis dzirdēja, Viņu esam namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Un tūdaļ daudz sapulcējās, tā ka tiem pat ārā priekš durvīm vairs nebija rūmes, un Viņš tiem to vārdu sludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Un pie Viņa nāca ar vienu melmeņu sērdzīgu, ko četri nesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Un kad tie nevarēja pie Viņa klāt tikt to ļaužu dēļ, tad tie atklāja to jumtu, kur Viņš bija iekšā, un to uzplēsuši, nolaida to gultu, uz kuras tas melmeņu sērdzīgais gulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Un redzēdams viņu ticību, Jēzus sacīja uz to melmeņu sērdzīgo: “Mans bērns, tavi grēki tev ir piedoti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Bet tur bija kādi no tiem rakstu mācītājiem, tie sēdēja turpat un domāja savās sirdīs:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '“Kā Šis tā runā? Viņš zaimo Dievu. Kas var grēkus piedot, kā vien Tas Vienīgais Dievs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Un tūdaļ Jēzus Savā garā nomanīja, tos pie sevis pašiem tā domājam, un uz tiem sacīja: “Kam jūs tā domājiet savās sirdīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Kas ir vieglāki: - vai sacīt uz to melmeņu sērdzīgo: grēki tev ir piedoti; - vai sacīt: celies, ņem savu gultu un staigā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Bet lai jūs zināt, ka Tam Cilvēka Dēlam vara ir virs zemes, grēkus piedot,” (Viņš sacīja uz to melmeņu sērdzīgo:)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '“Es tev saku, celies, ņem savu gultu un ej mājās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Un tas tūdaļ cēlās un to gultu paņēmis, aizgāja visiem redzot, tā ka visi izbrīnījās un Dievu teica sacīdami: “To mēs nemūžam vēl neesam redzējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Un Viņš izgāja atkal pie jūras, un visi ļaudis nāca pie Viņa, un Viņš tos mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Un garām iedams Viņš redzēja Levi, Alfeja dēlu, pie muitas sēžam un uz to sacīja: “Staigā Man pakaļ!” Un tas cēlies staigāja Viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Un notikās, tam viņa namā pie galda sēžot, arī daudz muitnieku un grēcinieku piesēdās līdz ar Jēzu un Viņa mācekļiem, jo to bija daudz, un tie staigāja Viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Un kad tie rakstu mācītāji un farizeji Viņu redzēja ēdam ar tiem muitniekiem un grēciniekiem, tad tie sacīja uz Viņa mācekļiem: “Viņš ēd un dzer ar muitniekiem un grēciniekiem!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Un to dzirdējis, Jēzus uz tiem sacīja: “Spirgtiem ārsta nevajag, bet vājiem. Es neesmu nācis, taisnus aicināt pie atgriešanās no grēkiem, bet grēciniekus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Un Jāņa mācekļi un tie farizeji gavēja, un tie nāca un uz Viņu sacīja: “Kāpēc Jāņa un farizeju mācekļi gavē, bet Tavi mācekļi negavē?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Un Jēzus uz tiem sacīja: “Kā kāzu ļaudis var gavēt, kamēr brūtgāns pie tiem ir? Kamēr brūtgāns pie viņiem, tie nevar gavēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Bet nāks dienas, ka tas brūtgāns no tiem taps atņemts, un tad tie gavēs tanīs dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Neviens jaunas vadmalas ielāpu nešuj uz vecām drēbēm; citādi tas jaunais ielāps noplīst no tām vecām drēbēm un tas plīsums paliek jo liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Un neviens jaunu vīnu nelej vecos ādas traukos; citādi tas vīns tos traukus pārplēš, un vīns un trauki iet bojā, bet jauns vīns jālej jaunos traukos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Un notikās, Viņam svētdienā caur labību ejot, tad Viņa mācekļi pa ceļu iedami sāka vārpas plūkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Un tie farizeji uz Viņu sacīja: “Raugi, ko tie dara svētdienā, kas nav brīv?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Un Viņš uz tiem sacīja: “Vai jūs nekad neesat lasījuši, ko Dāvids darījis, kad tam bija vajadzība un tas bija izsalcis, pats un tie, kas pie viņa bija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Kā tas iegāja Dieva namā tā augstā priestera Abjatara laikā un ēda tās Dieva priekšā noliktās maizes, ko ēst nav brīv, kā tik vien priesteriem, un deva arī tiem, kas pie viņa bija.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Un Viņš uz tiem sacīja: “Svētdiena ir celta cilvēka dēļ un ne cilvēks svētdienas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Tā nu Tas Cilvēka Dēls ir kungs arī pār svētdienu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Un Viņš atkal iegāja baznīcā. Un tur bija cilvēks, kam bija nokaltusi roka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Un tie uz Viņu glūnēja, vai Viņš svētdienā to dziedinās, ka Viņu varētu apsūdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Un Viņš sacīja tam cilvēkam, kam tā nokaltusi roka bija: “Nāc te šurp.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Un Viņš uz tiem sacīja: “Vai ir brīv svētdienā labu darīt vai ļaunu darīt? Dvēseli glābt vai maitāt?” Bet tie stāvēja klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Un Viņš tos uzlūkoja visapkārt ar dusmību un turklāt viņu sirds cietības dēļ noskumis Viņš tam cilvēkam sacīja: “Izstiep savu roku!” Un tas to izstiepa, un viņa roka palika atkal vesela tā kā tā otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Un tie farizeji izgāja un sarunājās tūdaļ ar Hērodus sulaiņiem pret Viņu, ka Viņu nomaitātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Bet Jēzus aizgāja ar Saviem mācekļiem pie jūras, un liels ļaužu pulks no Galilejas un Jūdu zemes Viņam gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Arī no Jeruzālemes un Idumejas un no viņpus Jardānes un tie, kas pie Tirus un Sidonas, liels pulks, dzirdējuši, ko Viņš darīja, nāca pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Un Viņš Saviem mācekļiem sacīja, lai kāda laiviņa Viņam būtu gādāta to ļaužu dēļ, ka tie Viņu nemāktu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Jo Viņš darīja daudzus veselus, tā ka tie, kam kādas kaites bija, Viņam lauzās klāt, lai Viņu aizskartu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Un tie nešķīstie gari, kad tie Viņu redzēja, krita pie zemes viņa priekšā un brēca sacīdami: “Tu esi Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Un Viņš tos stipri aprāja, lai Viņu nedarītu zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Un Viņš uzkāpa tai kalnā un aicināja, kurus pats gribēja, un tie nāca pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Un Viņš iecēla divpadsmit (ko nosauca par apustuļiem), lai tie pie Viņa būtu, un Viņš tos izsūtītu, Dieva vārdu sludināt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Un lai tiem vara būtu, neveselības dziedināt un velnus izdzīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Un Viņš Sīmanim pielika to pavārdu Pēteris;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Un Jēkabu, to Cebedeja dēlu, un Jāni, Jēkaba brāli, un tiem pielika pavārdus: Boānerges, tas ir: pērkona bērni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Un Andreju un Filipu un Bērtuli un Mateju un Tomu un Jēkabu, Alfeja dēlu, un Tadeju un Sīmani no Kānas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Un Jūdasu Iskariotu, kas Viņu arī nodeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Un tie nāca mājās. Un tie ļaudis atkal sapulcējās, tā ka tiem vaļas nebija, ne maizi ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Un kad tie(savējie), kas pie Viņa bija, to dzirdēja, tad tie izgāja, Viņu savaldīt. Jo tie sacīja: “Viņš ir bez prāta.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Un tie rakstu mācītāji, kas no Jeruzālemes bija nākuši, sacīja: “Viņam ir Belcebuls, un caur velnu virsnieku Viņš velnus izdzen.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Un tos pieaicinājis, Viņš tiem sacīja caur līdzībām: “Kā var sātans sātanu izdzīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Un ja kāda valsts savā starpā top ienaidā, tad tāda valsts nevar pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Un ja kāds nams pret sevi pašu nemierā, tad tāds nams nevar pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Ja nu sātans ceļas pret sevi un pats nīstās, tad viņš nevar pastāvēt, bet viņa gals ir klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Bet neviens nevar tā varenā namā ieiet un viņa rīkus laupīt, ja tas papriekš to vareno nesaista un tad viņa namu laupa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Patiesi, Es jums saku: visi grēki cilvēku bērniem top piedoti, arī pat Dieva zaimošanas, ar ko tie Dievu zaimo;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Bet kas To Svēto Garu zaimo, tas nemūžam nedabū piedošanu, bet ir sodāms caur mūžīgu sodību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Jo tie sacīja: “Viņam ir nešķīsts gars.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Tad Viņa māte un Viņa brāļi nāca un ārā stāvēdami pie Viņa sūtīja un Viņu sauca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Un tie ļaudis sēdēja ap Viņu un uz Viņu sacīja: “Redzi, Tava māte un Tavi brāļi ārā Tevi meklē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Un Viņš tiem atbildēja un sacīja: “Kas ir Mana māte un Mani brāļi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Un Viņš visapkārt uzlūkoja tos, kas ap Viņu sēdēja, un sacīja: “Redzi, Mana māte un Mani brāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Jo, ja kas Dieva prātu dara, tas ir Mans brālis un Mana māsa un Mana māte.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Un Viņš atkal iesāka mācīt pie jūras, un daudz ļaužu pie Viņa sapulcējās, tā ka Viņš laivā kāpis nosēdās uz jūras un visi ļaudis stāvēja jūrmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Un Viņš tiem daudz mācīja caur līdzībām un Savā mācībā uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '“Klausiet: redzi, sējējs izgāja sēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Un notikās, sējot cits krita ceļmalā, un tie putni apakš debess nāca un to apēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Un cits krita uz akmenāju, kur tam nebija daudz zemes, un uzdīga tūdaļ, tāpēc ka tam nebija dziļas zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Bet kad saule bija uzlēkusi, tad tas savīta un nokalta, tāpēc ka nebija saknes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Un cits krita starp ērkšķiem, un tie ērkšķi uzauga un to nomāca, un tas nenesa augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Un cits krita uz labu zemi un nesa augļus, kas augtin auga, un cits nesa trīsdesmitkārtīgi, cits sešdesmit kārtīgi un cits simtkārtīgi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Un Viņš uz tiem sacīja: “Kam ausis ir dzirdēt, tas lai dzird.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Un kad Viņš viens pats bija, tad tie, kas līdz ar tiem divpadsmit pie Viņa bija, Viņu vaicāja šās līdzības dēļ');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Un Viņš uz tiem sacīja: “Jums ir dots, zināt Dieva valstības noslēpumu; bet tiem, kas ārā, viss tas notiek caur līdzībām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Ka tie redzot redz un nenomana, un dzirdot dzird un nesaprot; ka tie neatgriežas, un grēki tiem netop piedoti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Un Viņš uz tiem sacīja: “Vai jūs šo līdzību nesaprotat? Kā tad jūs sapratīsiet visas tās citas līdzības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Tas sējējs sēj to vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Bet šie ir tie, kas ceļmalā, kur tas vārds top sēts, un kad tie to ir dzirdējuši, tad tūdaļ sātans nāk un to vārdu noņem, kas viņu sirdīs ir sēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Un tāpat tie, kas uz to akmenāju sēti, ir tie, kas to vārdu dzirdējuši, tūdaļ to uzņem ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Bet tiem nav saknes iekš sevis, bet tik kādu laiku tie ir ticīgi. Kad bēdas un vajāšana uziet tā vārda dēļ, tad viņi tūdaļ ņem apgrēcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Un kas starp ērkšķiem sēti, ir tie, kas to vārdu dzird,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Un šīs pasaules rūpes un bagātības viltība un citas kārības iemetās un noslāpē to vārdu un tas paliek neauglīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Un kas uz to labo zemi sēti, ir tie, kas to vārdu dzird un pieņem un augļus nes, cits trīsdesmitkārtīgi, cits sešdesmitkārtīgi, cits simtkārtīgi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Un Viņš uz tiem sacīja: “Vai svece top iededzināta, lai to liek apakš pūra, vai apakš galda? Vai ne tāpēc, lai to liek uz lukturi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Jo nekas nav apslēpts, kas nebūtu nācis gaismā; un nekas nenotiek slepeni, kas netaptu zināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Jo kam ausis ir dzirdēt, tas lai dzird.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Un Viņš uz tiem sacīja: “Pieraugāt, ko jūs dzirdat. Ar kādu mēru jūs mērojat, mēros jums, un pieliks jums vēl klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Jo kam ir, tam taps dots; un kam nav, no tā arī taps atņemts, kas tam ir.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Un Viņš sacīja: “Dieva valstība ir tāpat, kā kāds cilvēks sēklu met zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Un guļ un ceļas, nakti un dienu; un tā sēkla uzdīgst un uzaug, tā ka viņš pats to nenomana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Jo zeme pati no sevis nes augļus, papriekš stiebru, tad vārpu, tad pilnus kviešus iekš vārpas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Un kad tie augļi ienākušies, tad viņš tūdaļ cirpi sūta, jo tas pļaujamais laiks ir klātu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Un Viņš sacīja: “Kam mēs Dieva valstību līdzināsim? Jeb caur kādu līdzību mēs to nozīmēsim?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Itin kā sinepju graudiņš, kas zemē sēts, mazākais no visām sēklām virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Un kad tas ir sēts, tad tas augtin aug un top lielāks pār visiem stādiem un dabū lielus zarus, tā ka putni apakš debess viņa pavēnī var ligzdas taisīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Un caur daudz tādām līdzībām Viņš uz tiem to vārdu runāja, tā ka tie to varēja saprast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Un bez līdzībām Viņš uz tiem neko nerunāja; bet Saviem mācekļiem Viņš visu īpaši izstāstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Un Viņš uz tiem sacīja tanī dienā, kad vakars metās: “Pārcelsimies uz viņu malu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Un tos ļaudis atstājuši, tie Viņu ņēma līdz, tā kā Viņš laivā bija, un tur vēl citas laivas bija pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Un liela vētra cēlās, un viļņi gāzās laivā, tā ka tā laiva jau pildījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Un Viņš laivas galā uz spilvena gulēja; un tie Viņu modina un saka uz Viņu: “Mācītāj, vai Tu nebēdā, ka ejam bojā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Un uzmodies Viņš apdraudēja vēju un sacīja uz jūru: “Klusu, mierā!” Un vējš nostājās, un jūra palika it klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Un Viņš uz tiem sacīja: “Kam jūs esat tik bailīgi? Kā jums nav ticības?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Un tie ļoti izbijās un sacīja savā starpā: “Kas Tas tāds? Jo vējš un jūra Viņam paklausa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Un tie nonāca viņpus jūras, Gadariešu tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Un Viņam no laivas izejot tūdaļ sastapās no kapiem cilvēks ar nešķīstu garu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Tam bija sava mītne kapos, un neviens viņu nevarēja ne ar ķēdēm saistīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Jo tas ar pinekļiem un ķēdēm daudzkārt bija saistīts; bet viņš salauza tās ķēdes un sarāva tos pinekļus, un neviens to nespēja valdīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Un tas bija vienmēr naktīm un dienām kalnos un iekš kapiem, brēkdams un sevi ar akmeņiem sizdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Bet Jēzu no tālienes ieraudzījis, tas skrēja un metās priekš Viņa zemē');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Un brēca ar stipru balsi un sacīja: “Kas man ar Tevi, Jēzu, Tu Dieva, Tā Visaugstākā, Dēls? No Dieva puses Tevi lūdzu, nemoki mani!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Jo Viņš uz to sacīja: “Izej, tu nešķīstais gars, no tā cilvēka.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Un Viņš tam jautāja: “Kāds tev vārds?” Un tas atbildēja sacīdams: “Vārds man leģions, jo mēs esam daudz.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Un tas Viņu ļoti lūdza, lai Viņš tos no tā apgabala neizdzītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Bet tur pie tā kalna bija liels cūku pulks ganos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Un visi tie velni Viņu lūdza sacīdami: “Sūti mūs tais cūkās, ka tanīs ieskrienam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Un tūlīt Jēzus tiem to ļāva, un tie nešķīstie gari izgājuši ieskrēja tais cūkās; un tas cūku pulks no kraujas iegāzās jūrā (bet to bija pie divtūkstoš) un noslīka jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Un tie cūku gani bēga un stāstīja pilsētā un uz lauka; un tie izgāja raudzīt, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Un tie nāca pie Jēzus un ieraudzīja to velna apsēsto tur sēžam, apģērbtu un pie pilna prāta, to pašu, kam tas leģions bijis; un tie izbijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Un tie, kas to bija redzējuši, viņiem stāstīja, kā tam velna apsēstam bija noticis, un par tām cūkām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Un tie sāka Viņu lūgt, lai no viņu robežām aizejot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Un kad Viņš kāpa laivā, tas velna apsēstais Viņu lūdza, ka pie Viņa varētu palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Bet Jēzus to neļāva, bet uz to sacīja: “Ej savās mājās pie tiem savējiem un stāsti tiem, kādas lietas Tas Kungs tev darījis, un kā Viņš par tevi apžēlojies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Un tas nogāja un sāka sludināt pa tām desmit pilsētām, ko Jēzus tam bija darījis, un visi brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Un kad Jēzus atkal laivā bija pārcēlies uz otru malu, tad daudz ļaužu pie Viņa sapulcējās, un Viņš bija jūrmalā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Un redzi, tad nāca viens no tiem baznīcas priekšniekiem, Jaīrus ar vārdu; un Viņu redzēdams, tas krita Viņam pie kājām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Un Viņu ļoti lūdza sacīdams: “Mana meitiņa guļ uz nāvi, lūdzams, nāc un uzliec tai rokas, ka viņa top vesela un dzīvo.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Un Viņš ar to nogāja. Un daudz ļaužu Viņam gāja pakaļ un Viņu spieda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Un tur bija viena sieva, tai jau divpadsmit gadus bija asinssērga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Un tā daudz bija cietusi no daudz ārstiem un visu savu nabadzību iztērējusi un nekādu palīdzību nebija atradusi, bet tā sērga bija vēl niknāka palikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Šī par Jēzu dzirdējusi nāca ļaužu pulkā no aizmugures un aizskāra Viņa drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Jo tā sacīja: “Ja vien Viņa drēbes aizskaršu, tad tapšu vesela.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Un tūdaļ viņas asins avots izsīka; un viņa noprata pie savām miesām, ka no tās kaites bija dziedināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Un Jēzus tūdaļ pie Sevis nomanīdams, ka spēks no Viņa izgājis, apgriezās uz tiem ļaudīm un sacīja: “Kas Manas drēbes aizskāris?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Un Viņa mācekļi uz Viņu sacīja: “Tu redzi, ka tie ļaudis Tev virsū mācās, un Tu saki: kas Mani aizskāris?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Un Viņš skatījās apkārt, to ieraudzīt, kas to bija darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Bet tā sieva bīdamies un drebēdama zināja, kas pie viņas bija noticis, nāca un krita Viņa priekšā pie zemes un Viņam visu to patiesību izteica.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Bet Viņš uz to sacīja: “Mana meita, tava ticība tev palīdzējusi. Ej ar mieru un paliec vesela no tavas kaites.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Viņam to vēl runājot, kādi no tā baznīcas priekšnieka nāca un sacīja: “Tava meita jau nomirusi, ko tu To Mācītāju vēl apgrūtini.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Bet Jēzus to vārdu, ko tie teica, dzirdējis, sacīja uz to baznīcas priekšnieku: “Nebīsties, tici vien!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Un Viņš neļāva nevienam Sev līdz iet kā vien Pēterim un Jēkabam un Jānim, Jēkaba brālim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Un Viņš nāca tā baznīcas priekšnieka namā un redzēja troksni un ļaudis daudz raudam un kaucam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Un Viņš iegājis uz tiem sacīja: “Ko jūs dariet troksni un raudiet? Tas bērns nav miris, bet guļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Un tie Viņu izsmēja. Bet Viņš visus izdzina un ņēma pie Sevis tā bērna tēvu un māti un tos, kas līdz ar Viņu bija, un iegāja, kur tas bērns gulēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Un Viņš satvēra tā bērna roku un sacīja uz to: “Talita, kūmi!” Tas ir tulkots: “Meitiņa, Es tev saku, celies augšām!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Un tā meitiņa tūlīt cēlās un staigāja; jo tā bija divpadsmit gadus veca. Un tie iztrūcinājās ar lielu iztrūcināšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Un Viņš tiem stipri piekodināja, ka neviens to nedabūtu zināt, un lika tai dot ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Un Viņš no turienes izgāja un nāca Savā tēva pilsētā, un Viņa mācekļi Viņam gāja līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Un kad svētdiena nāca, Viņš iesāka baznīcā mācīt; un daudzi Viņu dzirdēdami izbrīnījās un sacīja: “Kur Šim tas nāk? Un kas tā par gudrību, kas Viņam dota, un kā tādi brīnumi notiek caur Viņa rokām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Vai Viņš nav tas amatnieks, Marijas dēls, un Jēkaba un Jāzepa un Jūdas un Sīmaņa brālis, un vai Viņa māsas nav šeit pie mums?” Un tie ņēma apgrēcību pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Bet Jēzus uz tiem sacīja: “Pravietis nekur nav mazāk cienīts nekā savā tēva zemē un pie saviem radiem un savās mājās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Un Viņš tur nevienu brīnumu nevarēja darīt, tik vien retiem vājiem Viņš rokas uzlika un tos dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Un Viņš brīnījās par viņu neticību un pārstaigāja tos miestus, visapkārt mācīdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Un Viņš sasauca tos divpadsmit un iesāka tos sūtīt pa diviem un tiem deva varu pār tiem nešķīstiem gariem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Un tiem pavēlēja, ka tie neko neņemtu līdz uz ceļu kā vien spieķi, ne kulīti, ne maizes, nedz naudas jostā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Bet ka kurpes apautu un neapvilktu divus svārkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Un Viņš uz tiem sacīja: “Kur jūs kādā namā ieiesiet, tur paliekat, tiekams jūs no turienes aizejat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Un ja kādā vietā jūs nepieņems, nedz jūs klausīs, tad izejat no turienes un nokratiet tos pīšļus no savām kājām viņiem par liecību. Patiesi, Es jums saku: Vieglāki būs Sodomas un Gomoras ļaudīm soda dienā nekā tādai pilsētai.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Un izgājuši tie sludināja, lai atgriežas no grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Un izdzina daudz velnus un svaidīja daudz vājus ar eļļu un darīja tos veselus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Un ķēniņš Hērodus to dzirdēja (jo Viņa Vārds bija tapis zināms) un sacīja: “Jānis, tas Kristītājs, no miroņiem ir uzmodināts, un tādēļ Viņš dara tādus varenus brīnumus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Citi sacīja: “Viņš ir Elija,” un citi sacīja: “Viņš ir pravietis, jeb tā kā viens no tiem praviešiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Bet Hērodus to dzirdējis sacīja: “Viņš ir Jānis, kam es galvu nocirtis, tas no miroņiem ir uzmodināts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Jo viņš, Hērodus, bija sūtījis un Jāni grābis un to cietumā licis Hērodeijas, Filipa, viņa brāļa, sievas dēļ; jo viņš to bija precējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Jo Jānis uz Hērodu bija sacījis: “Tev nepieklājās, ka tev ir sava brāļa sieva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Bet Hērodeija viņu nīdēja un viņu gribēja nokaut; un nevarēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Jo Hērodus Jāni bijās zinādams, viņu esam taisnu un svētu vīru, un viņu turēja cieņā, un viņu klausīdams viņš daudz ko darīja un labprāt viņu dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Un tur prieka diena gadījās, kad Hērodus savā dzimšanas dienā saviem lieliem kungiem un tiem virsniekiem un tiem augstākajiem iekš Galilejas dzīres taisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Un Hērodeijas meita ienākusi dejoja un labi patika Hērodum un tiem, kas līdz pie galda sēdēja. Tad ķēniņš sacīja uz to meiteni: “Lūdz no manis ko gribēdama, es tev došu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Un viņš tai zvērēja: “Ko tu no manis lūgsi, to es tev došu, ar līdz pat pusei no manas valsts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Bet viņa izgājusi sacīja savai mātei: “Ko lai es lūdzu?” Bet tā sacīja: “Jāņa, tā Kristītāja, galvu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Un tūdaļ viņa gāja steigšus iekšā pie ķēniņa, lūdza un sacīja: “Es gribu, ka tu man tūlīt dod kādā bļodā Jāņa, tā Kristītāja, galvu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Un ķēniņš ļoti noskuma; tomēr tās zvērēšanas un to dēļ, kas pie galda sēdēja, viņai to negribēja liegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Un ķēniņš tūdaļ sūtīja bendi, un pavēlēja, viņa galvu atnest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Un tas nogājis, viņam cietumā galvu nocirta un atnesa viņa galvu bļodā un deva to tai meitenei, un tā meitene to deva savai mātei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Un kad viņa mācekļi to dzirdēja, tad tie nāca un paņēma viņa miesas un tās ielika kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Un tie apustuļi sapulcējās pie Jēzus un Tam stāstīja visu, ko tie bija darījuši un ko tie bija mācījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Un Viņš uz tiem sacīja: “Nāciet savrup kādā vientuļa vietā un atpūšaties maķenīt.” Jo daudz bija, kas nāca un gāja, un tiem nebija vaļas ne ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Un tie laivā nogāja savrup uz kādu tukšu malu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Un tie ļaudis redzēja, ka tie nocēlās, un daudzi Viņu pazina un satecēja kājām no visām pilsētām kopā un atnāca tur papriekš un sapulcējās pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Un Jēzus iziedams redzēja daudz ļaužu, un sirds Viņam par tiem iežēlojās, jo tie bija kā avis, kam gana nav. Un Viņš iesāka tos daudz mācīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Un pašā pavakarē Viņa mācekļi pie Tā nāca un sacīja: “Šī vieta ir tukša, un diena jau drīz pagalam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Atlaidi tos, ka tie var noiet pa tām apkārtējām sētām un miestiem un sev maizi pirkt, jo tiem nav ko ēst.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Bet Viņš atbildēdams uz tiem sacīja: “Dodiet jūs viņiem ēst.” Un tie uz Viņu sacīja: “Vai tad mums būs noiet un par divsimt grašiem maizi pirkt un tiem dot ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Bet Viņš uz tiem sacīja: “Cik maizes jums ir? Ejat un raugāt.” Un tie raudzījuši sacīja: “Piecas un divas zivis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Un Viņš tiem visiem pavēlēja pa pulkiem zaļā zālē apsēsties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Un tie apsēdās rindās pa simtiem un pa piecdesmitiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Un Viņš ņēma tās piecas maizes un tās divas zivis, skatījās uz debesīm, pateicās un pārlauza tās maizes un deva Saviem mācekļiem, ka tie viņiem liktu priekšā, arī tās divas zivis Viņš visiem izdalīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Un tie visi ēda un paēda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Un salasīja no tām druskām divpadsmit pilnus kurvjus, un no tām zivīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Un to vīru, kas bija ēduši no tām maizēm, bija pie piectūkstošiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Un Viņš tūdaļ Saviem mācekļiem lika laivā kāpt un papriekš pārcelties uz Betsaidu, kamēr Viņš tos ļaudis atlaistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Un tos atlaidis, Viņš gāja uz kalnu, Dievu lūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Un kad vakars metās, tad tā laiva bija jūras vidū un Viņš viens pats uz zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Un redzēdams tos braucot bēdās esam (jo vējš tiem bija pretī), Viņš naktī gaiļos pie tiem nāca, pa jūru staigādams un gribēja tiem iet garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Bet kad tie Viņu redzēja pa jūru staigājam, tad tiem šķita ķēmu esam un tie iebrēcās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, '(Jo visi Viņu redzēja un izbijās.) Un tūdaļ Viņš ar tiem runāja un uz tiem sacīja: “Turat drošu prātu, Es tas esmu; nebīstaties!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Un Viņš iekāpa pie tiem laivā, un vējš nostājās, un tie pārlieku iztrūcinājās pie sevis un brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Jo viņi pie tām maizēm neko nebija nopratuši, jo viņu sirds bija cieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Un pārcēlušies tie nāca uz Ģenecaretes zemi un laida tur pie malas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Un kad tie no laivas izkāpa, tad tie ļaudis Viņu tūdaļ nomanīja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Un skrēja pa visu to tiesu un iesāka tos vājos uz gultām šurp un turp vest, kur tie dzirdēja Viņu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Un kur Tas iegāja miestos vai pilsētās vai ciemos, tur tie tos neveselos nolika uz tiem tirgiem un Viņu lūdza, ka tikai Viņa drēbju vīli varētu aizskart. Un cik Viņu aizskāra, tie tapa glābti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Un pie Viņa sapulcējās farizeji un kādi no tiem rakstu mācītājiem, no Jeruzālemes nākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Un redzēdami kādus no Viņa mācekļiem netīrām, tas ir, nemazgātām rokām maizi ēdam, tie tos rāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Jo tie farizeji un visi Jūdi neēd, ja tie rokas daudzkārt nav mazgājuši, to vecaju likumus turēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Un no tirgus nākot tie neēd, ja tie nav mazgājušies. Un vēl ir daudz, ko tie uzņēmušies darīt, dzeramu trauku un krūžu un vara rīku un gultu mazgāšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Tad tie farizeji un rakstu mācītāji Viņam vaicāja: “Kāpēc Tavi mācekļi nedzīvo pēc vecaju likumiem, bet maizi ēd nemazgātām rokām?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Bet Viņš atbildēdams uz tiem sacīja: “Gan labi Jesaja par jums liekuļiem ir sludinājis, kā ir rakstīts: “Šie ļaudis ar lūpām mani godā, bet viņu sirds ir tālu no Manis nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Bet tie Mani velti cienī, mācīdami tādas mācības, kas ir cilvēku pavēles.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Jo Dieva bausli atmetuši, jūs turat cilvēku likumus, krūžu un biķeru mazgāšanas, un darāt vēl daudz citas tādas lietas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Un Viņš uz tiem sacīja: “It jauki jūs Dieva bausli atmetat, lai savu likumu turētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Jo Mozus ir sacījis: godā savu tēvu un savu māti; un kas ļaunu runā pret tēvu vai māti, tam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Bet jūs sakāt: ja cilvēks uz tēvu vai māti saka: korban, tas ir: lai tas ir Dievam par upuri, kas tev no manis varētu par labu nākt; -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Tad jūs viņam vairs neļaujat nenieka darīt priekš tēva vai mātes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Iznīcinādami Dieva vārdu ar savu likumu, ko jūs esat iecēluši. Un daudz tādas lietas jūs dariet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Un tos ļaudis atkal pieaicinājis, Viņš uz tiem sacīja: “Klausiet Mani visi un saprotiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nekas cilvēku nevar apgānīt, kas no ārienes iekš tā ieiet, bet kas no tā iziet, tas cilvēku apgāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Kam ausis ir dzirdēt, tas lai dzird.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Un kad Viņš no tiem ļaudīm nogāja namā, Viņa mācekļi vaicāja pēc šās līdzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Un Viņš uz tiem sacīja: “Vai ir jūs esat tādas nesaprašas? Vai jūs neprotat, ka tas, kas no ārpuses cilvēkā ieiet, viņu nevar apgānīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Jo tas neiet viņa sirdī, bet vēderā, un iziet pa zināmu ceļu, pa ko visa barība izkārnās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Bet Viņš sacīja: “Kas no cilvēka iziet, tas cilvēku apgāna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Jo no iekšienes, no cilvēka sirds, iziet niknas domas, laulības pārkāpšanas, maucības, slepkavības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Zādzības, negausības, blēdības, viltība, nešķīstība, skauģa acs, Dieva zaimošana, lepnība, bezprātība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Viss tāds ļaunums iziet no iekšienes un cilvēku apgāna.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Un no turienes cēlies, Viņš nogāja uz Tirus un Sidonas robežām. Un kādā namā iegājis, Viņš gribēja, ka neviens to nemanītu; bet nevarēja palikt paslēpts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Jo viena sieva, kuras meitiņai bija nešķīsts gars, par Viņu dzirdējusi, nāca un nometās priekš Viņa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Bet tā bija Grieķu sieva, no dzimuma Siro-Feniķiete, un Viņu lūdza, lai to velnu izdzītu no viņas meitas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Bet Jēzus uz to sacīja: “Lai papriekš bērni top paēdināti, jo neklājās bērniem maizi atņemt un sunīšiem mest priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Un viņa atbildēja un uz To sacīja: “Tā gan ir, Kungs; bet tomēr sunīši ēd apakš galda no bērnu druskām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Un Viņš uz to sacīja: “Šī vārda dēļ ej! velns ir izbēdzis no tavas meitas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Un nogājusi savās mājās, viņa atrada to meitiņu uz gultas guļam, un ka velns bija izbēdzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Un atkal izgājis no Tirus un Sidonas robežām, Viņš nāca pie Galilejas jūras vidū starp to desmit pilsētu robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Un pie Viņa atveda vienu kurlmēmu, un Viņu lūdza, ka tam uzliktu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Un Viņš to ņēma no tiem ļaudīm savrup pie malas un lika Savus pirkstus viņa ausīs un izspļāvis aizskāra viņa mēli;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Un skatījās uz debesi, nopūtās un sacīja uz to: “Epata,” tas ir: “Atveries!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Un tūdaļ viņa ausis atvērās, un viņa mēles saite tapa svabada, un viņš runāja pareizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Un Viņš tiem aizliedza, lai nevienam to nesaka; bet jo Viņš to aizliedza, jo vairāk tie to sludināja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Un brīnījās ļoti par to un sacīja: “Viņš visas lietas ir labi darījis; Viņš kurlus dara dzirdošus un mēmus runājošus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Tanīs dienās, kad tur daudz ļaužu bija un tiem nebija ko ēst, Jēzus aicināja Savus mācekļus pie Sevis un uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '“Mana sirds iežēlojās to ļaužu dēļ, jo tie jau trīs dienas pie Manis palikuši un tiem nav ko ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Un kad es tos neēdušus uz mājām atlaidīšu, tad tie uz ceļa badā nonīks; jo citi bija no tālienes nākuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Un Viņa mācekļi tam atbildēja: “Kur, kas šos ar maizi var pieēdināt šeitan tuksnesī?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Un Viņš tiem jautāja: “Cik jums maizes?” Tie sacīja: “Septiņas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Un Viņš tiem ļaudīm pavēlēja, pie zemes apmesties. Un Viņš ņēma tās septiņas maizes un pateikdams tās pārlauza un deva Saviem mācekļiem, lai tās liek priekšā; un tie lika tiem ļaudīm priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Tiem bija arī mazums zivtiņu; un pateicību sacījis, Viņš pavēlēja, arī tās likt priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Bet tie ēda un paēda un pielasīja ar atlikušām druskām septiņus kurvjus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Un to bija pie četrtūkstošiem, kas bija ēduši. Un Viņš tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Un tūdaļ Viņš iekāpa laivā ar Saviem mācekļiem un nāca Dalmanutas tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Un farizeji izgāja un iesāka ar Viņu apjautāties un meklēja no Viņa kādu zīmi no debess, Viņu kārdinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Un Viņš gauži nopūtās Savā garā un sacīja: “Ko šī tauta meklē zīmes? Patiesi, Es jums saku: šai tautai nekāda zīme netaps dota.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Un Viņš tos atstājis, kāpa atkal laivā un nocēlās uz viņu malu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Un tie bija aizmirsuši maizi ņemt līdz, un tiem vairāk nebija, kā viena maize vien pašiem klāt laivā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Un Viņš tiem pavēlēja sacīdams: “Raugāt, sargājaties no farizeju un no Hērodus rauga!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Un tie domāja savā starpā sacīdami: “Tas ir, ka mums maizes nav.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Un to nomanīdams, Jēzus uz tiem sacīja: “Ko jūs domājat, ka jums maizes nav? Vai jūs vēl nesamanāt, nedz noprotat? Vai jums sirds vēl ir apcietināta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Jums ir acis, un jūs neredzat; jums ir ausis, un jūs nedzirdat un neatminaties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Kad Es tās piecas maizes tiem piectūkstošiem lauzu, cik kurvju ar druskām jūs esat pielasījuši?” Tie uz Viņu sacīja: “Divpadsmit.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '“Bet kad Es tās septiņas maizes tiem četrtūkstošiem lauzu, cik kurvju ar atlikušām druskām jūs esat pielasījuši?” Un tie sacīja: “Septiņus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Un Viņš uz tiem sacīja: “Kā tad jūs nesaprotat?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Un Viņš nāca uz Betsaidu; tad tie Viņam pieveda vienu neredzīgu un Viņam lūdza, ka Viņš to aizskartu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Un Viņš to neredzīgo pie rokas ņēma un to izveda ārā no tā miesta un spļāva viņa acīs un uzlika tam rokas un tam jautāja, vai tas ko redzot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Un acis pacēlis, tas sacīja: “Es redzu cilvēkus kā kokus staigājam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Tad Viņš atkal uzlika rokas uz viņa acīm un viņam lika acis pacelt, un viņš tapa atkal vesels un redzēja visu it skaidri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Un Viņš to sūtīja mājās sacīdams: “Neej miestā un nesaki to nevienam miestā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Un Jēzus un Viņa mācekļi izgāja uz Filipa Cezarejas miestiem, un vaicāja Saviem mācekļiem uz ceļa, tiem sacīdams: “Ko tie ļaudis saka, Mani esam?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Bet tie atbildēja: “Tu esot Jānis, tas Kristītājs; un citi: Tu esot Elija; un citi: viens no tiem praviešiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Un Viņš uz tiem sacīja: “Bet jūs, ko jūs sakāt, Mani esam?” Bet Pēteris atbildēdams uz to sacīja: “Tu esi Tas Kristus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Un Viņš tiem stipri piekodināja, lai nevienam par Viņu neko nesaka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Un Viņš iesāka tos mācīt, ka Tam Cilvēka Dēlam daudz būs ciest un tapt atmestam no tiem vecajiem un augstiem priesteriem un rakstu mācītājiem un tapt nokautam un pēc trim dienām augšām celties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Un Viņš šo vārdu it skaidri runāja, un Pēteris, Viņu savrup vedis, iesāka Viņu apsaukt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Bet Viņš atgriezdamies un Savus mācekļus uzlūkodams apdraudēja Pēteri sacīdams: “Atkāpies no Manis, sātan! Jo tu nedomā pēc Dieva, bet pēc cilvēku prāta.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Un tos ļaudis līdz ar Saviem mācekļiem pieaicinājis, Viņš uz tiem sacīja: “Kas Man grib nākt pakaļ, tas lai pats sevi aizliedz, lai ņem savu krustu un lai staigā Man pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Jo kas savu dzīvību grib glābt, tas to zaudēs; un kas savu dzīvību zaudē Manis un evaņģēlija dēļ, tas to izglābs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Jo ko tas cilvēkam palīdz, ka viņš samanto visu pasauli un tam sava dvēsele zūd?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Jeb ko cilvēks var dot par savas dvēseles atpirkšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Jo kas Manis un Manu vārdu dēļ kaunas iekš šīs laulību pārkāpējas un grēcīgas tautas, tā paša dēļ arī Tas Cilvēka Dēls kaunēsies, kad Viņš nāks ar tiem svētiem eņģeļiem iekš Sava Tēva godības.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Un Viņš uz tiem sacīja: “Patiesi, Es jums saku: citi no tiem, kas še stāv, nāvi nebaudīs, pirms tie nebūs redzējuši Dieva valstību ar spēku nākam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Un pēc sešām dienām Jēzus ņēma līdz Pēteri un Jēkabu un Jāni un tos veda savrup uz vienu augstu kalnu. Un Viņš tapa apskaidrots viņu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Un Viņa drēbes tapa spožas un ļoti baltas tā kā sniegs, ka neviens balinātājs virs zemes tā nevar balināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Un tiem Elija ar Mozu parādījās un runāja ar Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Un Pēteris atbildēja un uz Jēzu sacīja: “Rabbi, šeit mums labi; taisīsim trīs būdas, vienu Tev un vienu Mozum un vienu Elijam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Jo tas nezināja, ko tas runāja; jo tie bija pārbijušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Un viens padebesīs nāca, tos apēnodams; un balss nāca no tā padebeša sacīdama: “Šis ir Mans mīļais Dēls, klausiet Viņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Un tūdaļ tie skatījās visapkārt un nevienu vairs pie sevis neredzēja, bet Jēzu vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Un noejot no tā kalna, Viņš tiem piekodināja, ka tie nevienam nesacītu, ko tie redzējuši, pirms Tas Cilvēka Dēls no miroņiem nebūs augšām cēlies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Un tie to vārdu paturēja savā prātā un apjautājās, kas tas esot: no miroņiem augšām celties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Un tie Viņam jautāja sacīdami: “Kā tad tie rakstu mācītāji saka, ka Elijam jānāk papriekš?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Bet Viņš atbildēdams uz tiem sacīja: “Gan Elija papriekš nākdams atkal visu sataisīs; un kā ir rakstīts par To Cilvēka Dēlu, ka Tam daudz būs ciest un tapt nicinātam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Bet Es jums saku: ka Elija arī ir nācis, bet tie tam ir darījuši, ko gribēdami, tā kā par to ir rakstīts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Un Viņš pie Saviem mācekļiem nācis, redzēja daudz ļaužu pie tiem un rakstu mācītājus, kas ar tiem apjautājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Un tūdaļ visi ļaudis, kad tie To redzēja, izbijās un pieskrējuši To sveicināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Un Viņš tiem rakstu mācītājiem vaicāja: “Ko jūs ar tiem apjautājaties?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Un viens no tiem ļaudīm atbildēdams sacīja: “Mācītāj, es savu dēlu pie Tevis esmu atvedis, tam ir mēms gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Un kad tas viņu sakampj, tad tas to rausta; un tas puto un griež zobus un izdilst; un es Taviem mācekļiem esmu sacījis, lai tie to izdzen, bet tie nav varējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Bet Viņš tam atbildēja un sacīja: “Ak tu neticīgā cilts? Cik ilgi Es pie jums būšu? Cik ilgi Es jūs panesīšu? Vediet to pie Manis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Un tie to atveda pie Viņa, un kad tas gars Viņu redzēja, tad tas tūdaļ to plosīja, un tas pie zemes krizdams vārtījās putodams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Un Viņš viņa tēvam jautāja: “Cik ilgi viņam tā noticies?” Bet tas sacīja: “No bērnu dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Un dažkārt viņš to ir iemetis ugunī, ka viņš to nomāktu; bet ja Tu ko spēj, tad palīdzi mums, apžēlojies par mums!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Bet Jēzus uz to sacīja: “Kaut tu varētu ticēt! tas visu spēj, kas tic.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Un tūdaļ tā bērna tēvs brēca un sacīja ar asarām: “Es ticu, Kungs, palīdzi manai neticībai!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Bet Jēzus redzēdams, ka tie ļaudis satecēja, apdraudēja to nešķīsto garu, uz to sacīdams: “Tu mēmais un kurlais gars, Es tev pavēlu, izej ārā no tā un neieej vairs iekš tā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Un tas izgāja, brēkdams un to gauži plosīdams, un viņš tapa tā kā mironis, tā ka daudzi sacīja: tas ir nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Bet Jēzus to ņēma pie rokas, to uzcēla, un tas pacēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Un kad Viņš namā bija iegājis, Viņa mācekļi tam savrup jautāja: “Kāpēc mēs nespējām to izdzīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Un Viņš uz tiem sacīja: “Šī suga citādi nevar iziet, kā vien caur lūgšanu un gavēšanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Un no turienes izgājuši, tie pārstaigāja Galileju, un Viņš negribēja, ka to kas zinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Jo Viņš Savus mācekļus mācīja un uz tiem sacīja: “Tas Cilvēka Dēls taps nodots cilvēku rokās, un tie To nokaus, un nokauts Viņš trešā dienā augšām celsies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Bet tie šo vārdu nesaprata un bijās Viņu jautāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Un Viņš nāca Kapernaūmā, un mājās būdams Viņš tiem jautāja: “Ko jūs savā starpā esat apjautājušies uz ceļa?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Bet tie cieta klusu; jo tie savā starpā bija sarunājušies uz ceļa, kurš esot tas lielākais?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Un Viņš apsēdās, atsauca tos divpadsmit un uz tiem sacīja: “Ja kas grib pirmais būt, tas lai ir no visiem tas pēdīgais un visu kalps.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Un Viņš ņēma vienu bērnu un to veda viņu vidū un to skūpstīja un uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '“Ja kas vienu no šiem bērniem uzņem Manā Vārdā, tas Mani uzņem; bet kas Mani uzņem, tas neuzņem Mani, bet To, kas Mani sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Bet Jānis Tam atbildēja un sacīja: “Mācītāj! Mēs vienu redzējām Tavā Vārdā velnus izdzenam, tas neturas pie mums, un mēs tam to esam lieguši, tāpēc ka tas neturas pie mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Bet Jēzus sacīja: “Neliedziet viņam, jo neviens nedara brīnumu Manā Vārdā, kas tūdaļ no Manis varētu ļaunu runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Jo kas nav pret mums, tas ir ar mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Jo, ja kas jūs dzirdinās ar biķeri ūdens Manā Vārdā, tāpēc ka jūs Kristum piederat, patiesi, Es jums saku: tam sava alga nezudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Un ja kas apgrēcina vienu no šiem vismazākajiem, kas tic uz Mani, tam būtu labāki, ka tam dzirnu akmeni pie kakla piekārtu un to iemestu jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Jeb kad tev tava roka apgrēcina, nocērt to; tas tev ir labāki, ka tu kroplis ieej dzīvošanā, nekā tev ir divas rokas, un tu noej ellē, tai neizdzēšamā ugunī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Kur viņu tārps nemirst, un tas uguns neizdziest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Un kad tava kāja tevi apgrēcina, tad nocērt to; tas tev ir labāki, ka tu tizls ieej dzīvošanā, nekā tev ir divas kājas, un topi mests ellē, tai neizdzēšamā ugunī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Kur viņu tārps nemirst, un tas uguns neizdziest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Un kad tava acs tevi apgrēcina, tad izrauj to; tas tev ir labāki, ka tu vienacis ieej Dieva valstībā, nekā tev ir divas acis, un tu topi iemests elles ugunī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Kur viņu tārps nemirst, un tas uguns neizdziest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Jo ikviens ugunī taps sālīts; un ikkatrs upuris ar sāli taps sālīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Sāls gan ir laba lieta, bet ja sāls tapusi nesālīga, ar ko tad to darīs derīgu? Turat sāli iekš sevis un turat mieru savā starpā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Un no turienes cēlies Viņš nāca uz Jūdu zemes robežām, gar Jardānes otru pusi; un ļaudis nāca atkal kopā pie Viņa, un Viņš tā, kā ieradis, tos atkal mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Un farizeji piegāja un Viņam jautāja, Viņu kārdinādami: “Vai vīram brīv no savas sievas šķirties?’');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Bet Viņš atbildēja un uz tiem sacīja: “Ko Mozus jums ir pavēlējis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Bet tie sacīja: “Mozus vaļu devis, šķiršanās grāmatu rakstīt un šķirties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Un Jēzus atbildēja un uz tiem sacīja: “Jūsu sirds cietības dēļ viņš jums šo bausli rakstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Bet no pasaules iesākuma Dievs viņus radījis vīru un sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Tādēļ cilvēks atstās savu tēvu un māti un pieķersies pie savas sievas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Un tie divi būs viena miesa. Tad nu tie nav vairs divi, bet viena miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Tāpēc, ko Dievs savienojis, to cilvēkam nebūs šķirt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Un mājās Viņa mācekļi To atkal jautāja par to pašu lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Un Viņš uz tiem sacīja: “Ja kas no savas sievas šķirās un citu precē, tas laulību pārkāpj pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Un ja sieva no sava vīra šķirās un ar citu apprecējās, tā laulību pārkāpj.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Un tie bērniņus nesa pie Jēzus, ka Viņš tos aizskartu. Bet tie mācekļi tos aprāja, kas tos atnesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Bet kad Jēzus to redzēja, tad Viņš apskaitās un uz tiem sacīja: “Laidiet tos bērniņus pie Manis un neliedziet tiem, jo tādiem pieder Dieva valstība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Patiesi, Es jums saku, ja kas Dieva valstību nedabū kā bērniņš, tas nenāks tur iekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Un viņš tos apkampa, rokas tiem uzlika un tos svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Un kad Viņš bija izgājis uz ceļu, tad viens pieskrēja un ceļos nometies Viņu lūdza: “Labais Mācītāj, ko man būs darīt, lai iemantoju mūžīgu dzīvošanu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Bet Jēzus uz to sacīja: “Kāpēc tu Mani sauci par labu? Neviens nav labs kā vien Tas Vienīgais Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu tos baušļus zini: tev nebūs laulību pārkāpt; tev nebūs nokaut; tev nebūs zagt; tev nebūs nepatiesu liecību dot; tev nebūs nevienam neko atraut; godā savu tēvu un māti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Bet tas atbildēja un uz Viņu sacīja: “Mācītāj, šo visu es esmu darījis no savas jaunības.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Bet Jēzus, to uzlūkodams, to iemīlēja un sacīja uz to: “Vienas lietas tev trūkst, ej un pārdod visu, kas tev ir, un dod nabagiem; tad tev būs manta debesīs; un nāc, staigā Man pakaļ, to krustu uz sevi ņēmis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Bet par to vārdu noskumis, tas aizgāja bēdīgs, jo tam bija daudz mantas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Un Jēzus skatījās apkārt un sacīja uz Saviem mācekļiem: “Cik grūti bagātie ieies Dieva valstībā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Un tie mācekļi iztrūcinājās par Viņa vārdiem. Bet Jēzus atkal atbildēja un uz tiem sacīja: “Bērni, cik grūti ir, Dieva valstībā ieiet tiem, kas uz bagātību liek savu cerību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Vieglāki ir kamielim iet caur adatas aci, nekā bagātam ieiet Dieva valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Bet tie vēl vairāk pārbijās un sacīja savā starpā: “Kas tad var tapt svētīgs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Bet Jēzus tos uzlūkoja un sacīja: “Cilvēkiem tas neiespējams, bet ne Dievam, jo Dievam visas lietas iespējamas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Un Pēteris iesāka uz Viņu sacīt: “Redzi, mēs visu esam atstājuši un Tev staigājuši pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Bet Jēzus atbildēja un sacīja: “Patiesi, Es jums saku: neviens nav, kas atstājis namu vai brāļus vai māsas vai tēvu vai māti vai sievu vai bērnus vai tīrumus Manis un evaņģēlija dēļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'Kas nedabūs simtkārtīgi jau šinī laikā namus un brāļus un māsas un mātes un bērnus un tīrumus pie tām vajāšanām, un nākošā laikā mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Bet daudz, kas tie pirmie, būs tie pēdējie, un tie pēdējie būs tie pirmie.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Bet tie bija uz ceļa, iedami uz Jeruzālemi. Un Jēzus gāja viņiem priekšā, un tie iztrūcinājās un bijās līdz iedami, un Viņš ņēma atkal pie Sevis tos divpadsmit un iesāka tiem sacīt, kas Viņam notikšot:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '“Jo redzi, mēs noejam uz Jeruzālemi, un Tas Cilvēka Dēls taps nodots tiem augstiem priesteriem un rakstu mācītājiem, un tie Viņu pie nāves pazudinās un Viņu nodos pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Un tie To apmēdīs un To šaustīs un To apspļaudīs un To nokaus; un Viņš trešā dienā augšām celsies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Tad Jēkabs un Jānis, tie Cebedeja dēli, pie Viņa piegāja un sacīja: “Mācītāj, mēs gribam, ka Tu mums darītu, ko Tev lūgsim.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Un Viņš uz tiem sacīja: “Ko jūs gribat, lai Es jums daru?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Bet tie uz Viņu sacīja: “Dod mums, ka mēs varam sēdēt Tavā godībā, viens pa Tavu labo un otrs pa kreiso roku.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Bet Jēzus uz tiem sacīja: “Jūs nezināt, ko jūs lūdzat. Vai jūs varat dzert to biķeri, ko Es dzeršu, un tapt kristīti ar to kristību, ar ko Es topu kristīts?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Bet tie uz Viņu sacīja: “Varam.” Bet Jēzus uz tiem sacīja: “Jūs gan to biķeri dzersiet, ko Es dzeru, un tapsiet kristīti ar to kristību, ar ko Es topu kristīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Bet pie Manas labās un kreisās rokas sēdēt, Man nepiederas dot, bet kuriem tas ir sataisīts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Un kad tie desmit to dzirdēja, tad tie iesāka skaisties par Jēkabu un Jāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Bet Jēzus tos sauca un uz tiem sacīja: “Jūs zināt, ka tie, kas par ļaužu valdniekiem tiek turēti, tie pār tiem valda un viņu lieliem kungiem ir vara pār tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Bet tā jūsu starpā nebūs būt; bet ja kas no jums grib liels tapt, tas lai ir jūsu sulainis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'Un ja kas starp jums grib tas pirmais būt, tas lai ir visu kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Jo arī Tas Cilvēka Dēls nav nācis, ka Viņam taptu kalpots, bet ka Viņš kalpotu un Savu dzīvību dotu par atpirkšanas maksu priekš daudziem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Un tie nāca uz Jēriku, un Viņam ar Saviem mācekļiem un daudz ļaudīm no Jērikus izejot, Timeja dēls Bartimejs, tas aklais, sēdēja ceļmalā un nabagoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Un kad tas dzirdēja, ka tas Jēzus no Nacaretes esot, tad tas iesāka saukt un sacīt: “Jēzu, Tu Dāvida dēls, apžēlojies par mani.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Un daudzi to apsauca, lai paliek klusu. Bet tas jo vairāk brēca: “Tu Dāvida Dēls, apžēlojies par mani.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Un Jēzus apstājās un lika to aicināt; un tie aicināja to aklo, uz to sacīdami: “Turi drošu prātu, celies, Viņš tevi aicina.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Un savu uzvalku nometis, tas cēlās un nāca pie Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Un Jēzus atbildēja un uz to sacīja: “Ko tu gribi, lai Es Tev daru?” Bet tas aklais uz Viņu sacīja: “Rabbuni, ka es varētu redzēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Bet Jēzus uz to sacīja: “Ej, tava ticība tev palīdzējusi,” un tūdaļ tas tapa redzīgs un gāja Jēzum uz ceļa pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Un kad tie tuvu pie Jeruzālemes nāca, pie Betfagas un Betanijas pie Eļļas kalna, tad Viņš sūtīja divus no Saviem mācekļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Un uz tiem sacīja: “Noejat tanī miestā, kas jūsu priekšā, un iegājuši jūs tūdaļ atradīsiet piesietu kumeļu, uz kā vēl neviens cilvēks nav sēdējis. Atraisījuši to atvediet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Un ja kas jums sacīs: Kāpēc jūs to dariet? Tad atsakāt: Tam Kungam tā vajag; un tūdaļ tas to atsūtīs šurp.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Un tie nogāja un atrada to kumeļu ārā pie durvīm piesietu uz ielas, un to atraisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Un kādi no tiem, kas tur stāvēja, uz viņiem sacīja: “Ko jūs darāt, ka atraisiet to kumeļu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Un viņi uz tiem sacīja, kā Jēzus bija pavēlējis. Un tie tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Un viņi to kumeļu atveda pie Jēzus un savas drēbes uzlika un To sēdināja virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Un daudzi savas drēbes izklāja uz ceļu; un citi zarus cirta no kokiem un tos izkaisīja uz ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Un tie, kas gāja priekšā un pakaļā, kliedza un sauca: “Ozianna, slavēts, kas nāk Tā Kunga Vārdā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Slavēta ir mūsu tēva Dāvida valstība, kas nāk! Ozianna augstībā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Un Jēzus iegāja Jeruzālemē un Dieva namā. Un kad Viņš visu visapkārt bija uzlūkojis, un jau vakars bija, tad Viņš izgāja ar tiem divpadsmit uz Betaniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Un otrā dienā, kad tie no Betanijas izgāja, tad Viņam gribējās ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Un no tālienes redzēdams vienu vīģes koku, kam lapas bija, Viņš nāca, lai Viņš tanī ko atrastu; un pie tā piegājis Viņš neatrada nenieka kā vien lapas: jo nebija vīģu laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Un Jēzus uzrunāja un uz to sacīja: “Lai neviens nemūžam vairs neēd augļus no tevis.” Un Viņa mācekļi klausījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Un tie nāca uz Jeruzālemi, un Dieva namā iegājis Viņš iesāka izdzīt visus, kas pārdeva un pirka Dieva namā, un apgāza to mijēju galdus un to baložu pārdevēju krēslus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Un neļāva nevienu lietu nest caur Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Un mācīja un uz tiem sacīja: “Vai nav rakstīts: “Mans nams taps nosaukts lūgšanas nams visām tautām?” Bet jūs to esat darījuši par slepkavu bedri.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Un tie rakstu mācītāji un augstie priesteri to dzirdēja un meklēja, kā Viņu nomaitātu; jo tie bijās no Viņa, tāpēc ka visi ļaudis izbrīnījās par Viņa mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Un kad vakars metās, tad Viņš izgāja no pilsētas ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Un no rīta agrumā garām iedami tie redzēja to vīģes koku nokaltušu no pašām saknēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Pēteris atminējies uz Viņu sacīja: “Mācītāj, redzi, tas vīģes koks, ko Tu esi nolādējis, tas ir nokaltis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Un Jēzus atbildēja un uz tiem sacīja: “Ticat uz Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Jo patiesi, Es jums saku: ja kas šim kalnam sacīs: celies un meties jūrā! un nešaubīsies savā sirdī, bet ticēs, ka notiks, ko viņš saka: tad viņam notiks, ko viņš saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Tāpēc Es jums saku: visu, ko jūs lūgdami lūgsiet, ticat, ka jūs dabūsiet, tad tas jums notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Un kad jūs stāvat, Dievu lūgdami, tad piedodat, ja jums kas ir pret kādu, lai arī jūsu Tēvs, kas debesīs, jums piedod jūsu noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Bet ja jūs nepiedodat, tad arī jūsu Tēvs debesīs jūsu noziegumus nepiedos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Un tie nāca atkal uz Jeruzālemi, un Viņam Dieva namā staigājot, nāca pie Viņa tie augstie priesteri un rakstu mācītāji un tie vecaji,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'Un uz To sacīja: “Kādā varā Tu šo visu dari? Un kas Tev šo varu devis, ka Tu to dari?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Bet Jēzus atbildēja un uz tiem sacīja: “Es arīdzan jums vienu vārdu vaicāšu, un atbildiet Man; tad Es jums arīdzan sacīšu, kādā varā Es to daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Vai Jāņa kristība bija no debesīm, vai no cilvēkiem? Atbildiet Man.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Un tie domāja savā starpā un sacīja: ja mēs sakām: “No debesīm,” tad Viņš sacīs: “Kāpēc tad jūs viņam neesat ticējuši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Bet ja sacīsim: “No cilvēkiem,” - viņi bijās no tiem ļaudīm. Jo visi to Jāni turēja, ka tas patiesi pravietis bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Un tie atbildēja un uz Jēzu sacīja: “Mēs nezinām.” Un Jēzus atbildēja un uz tiem sacīja: “Tad Es arīdzan jums nesaku, kādā varā Es to daru.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Un Viņš iesāka runāt uz tiem caur līdzībām: “Viens cilvēks stādīja vīna kalnu un to aplika ar sētu un raka vīna spaidu un uztaisīja torni un to izdeva dārzniekiem un nogāja citur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Un kad tas laiks bija, tad viņš sūtīja pie tiem dārzniekiem vienu kalpu, ka tas no tiem dārzniekiem saņemtu no tiem vīna kalna augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Bet tie to ņēma un šauta un sūtīja tukšā atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Un viņš sūtīja atkal pie tiem citu kalpu; un šo tie nomētāja ar akmeņiem un tam galvu sadauzīja un apsmietu aizsūtīja projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Un viņš sūtīja atkal citu. Un šo tie nokāva. Un vēl daudz citus; un no tiem tie citus šauta un citus nokāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Un viņam bija vēl viens vienīgs dēls, ko viņš mīlēja, arī to viņš beidzot pie tiem sūtīja un sacīja: “Taču tie kaunēsies no mana dēla.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Bet tie dārznieki sacīja cits uz citu: “Šis ir tas mantinieks! Nāciet, nokausim to, tad mums būs tā mantība.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Un tie to ņēma, nokāva un izmeta no tā vīna kalna ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Ko nu tā vīna kalna kungs darīs? Viņš nāks un nomaitās tos dārzniekus un izdos to vīna kalnu citiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Vai jūs šo rakstu neesat lasījuši: “Tas akmens, ko tie nama taisītāji atmetuši, tas ir palicis par stūra akmeni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'No Tā Kunga tas noticis un ir brīnums mūsu acīs?””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Un tie meklēja Viņu rokā dabūt un bijās no tiem ļaudīm, jo tie nomanīja, ka Viņš uz tiem šo līdzību bija sacījis, un Viņu atstājuši tie aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Un tie sūtīja pie Viņa kādus no tiem farizejiem un Hērodus sulaiņiem, ka tie Viņu savaldzinātu Viņa valodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Un tie nāca un uz Viņu sacīja: “Mācītāj, mēs zinām, ka Tu esi patiesīgs un nebēdā par nevienu; jo Tu neuzlūko cilvēka vaigu, bet māci Dieva ceļu patiesi: vai ir brīv ķeizaram meslus dot vai ne? Vai dosim, vai nedosim?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Bet Viņu viltību zinādams, Viņš uz tiem sacīja: “Kam jūs Mani kārdināt? Atnesiet Man vienu sudraba grasi, lai Es to redzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Un tie atnesa. Tad Viņš uz tiem sacīja: “Kam ir šī zīme un tas virsraksts?” Bet tie uz Viņu sacīja: “Ķeizara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Un Jēzus atbildēja un uz tiem sacīja: “Tad dodiet ķeizaram, kas ķeizaram pieder, un Dievam, kas Dievam pieder.” Un tie izbrīnījās par Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Un tie saduceji, kas saka augšāmcelšanos neesam, nāca pie Viņa un Viņu jautāja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '“Mācītāj, Mozus mums ir rakstījis: ja kam brālis mirst, kas sievu pamet bez bērniem, tad viņa brālim būs to sievu apņemt un savam brālim celt dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Tad nu bija septiņi brāļi. Un pirmais apņēma sievu un mirdams nepameta dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Un otrais viņu apņēma un nomira un tas arīdzan nepameta dzimumu. Un tāpat trešais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Un visi septiņi to apņēma un bērnus nepameta. Beidzot pēc visiem arī tā sieva nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Tad nu pie augšāmcelšanās, kad tie augšāmcelsies, kuram tā sieva būs? Jo visiem septiņiem tā bijusi par sievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Bet Jēzus atbildēja un uz tiem sacīja: “Vai jūs nealojaties, tādēļ ka jūs tos rakstus neprotat, nedz Dieva spēku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Jo kad tie no miroņiem augšām celsies, tad tie nedz precēs, nedz taps precēti, bet tie būs itin kā tie eņģeļi, kas debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Bet par tiem mirušiem, ka tie taps uzmodināti: vai jūs Mozus grāmatā neesat lasījuši, kā Dievs pie tā krūma uz to runājis sacīdams: Es esmu Ābrahāma Dievs un Īzaka Dievs un Jēkaba Dievs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Dievs nav mirušu, bet dzīvu Dievs! Tad nu jūs briesmīgi alojaties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Un viens no tiem rakstu mācītājiem, kas bija dzirdējis, ka tie bija apjautājušies, zinādams, ka Viņš tiem bija labi atbildējis, nāca un Viņam vaicāja: “Kurš ir tas augstākais bauslis pār visiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Bet Jēzus tam atbildēja: “Tas augstākais bauslis pār visiem ir: klausies Israēl, Tas Kungs, mūsu Dievs, ir viens vienīgs Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Un tev būs To Kungu, savu Dievu, mīlēt no visas savas sirds un no visas savas dvēseles un no visa sava prāta un no visa sava spēka, šis ir tas augstākais bauslis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Tas otrais, šim līdzīgs, ir tas: tev būs savu tuvāko mīlēt kā sevi pašu; cita lielāka baušļa pār šiem nav.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Un tas rakstu mācītājs uz Viņu sacīja: “Gan labi, Mācītāj, tas ir tiesa, ko Tu sacījis: viens vienīgs Dievs ir, un cita nav, kā Viņš vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Un To mīlēt no visas sirds un no visa prāta un no visas dvēseles un no visa spēka, un tuvāku mīlēt kā sevi pašu, tas ir vairāk nekā visi dedzināmie upuri un citi upuri.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Un Jēzus redzēdams, ka tas gudri bija atbildējis, uz to sacīja: “Tu neesi tālu no Dieva valstības.” Un neviens nedrīkstēja vairs Viņu jautāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Un Jēzus atbildēja un sacīja, mācīdams Dieva namā: “Kā tie rakstu mācītāji saka, ka Kristus esot Dāvida dēls?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Jo tas pats Dāvids ir sacījis caur Svēto Garu: Tas Kungs ir sacījis uz manu Kungu: sēdies pa Manu labo roku, tiekams Es Tavus ienaidniekus lieku par pameslu Tavām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Kad nu Dāvids pats Viņu sauc par Kungu, kā tad tas ir viņa dēls?” Un daudz ļaužu Viņu labprāt dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Un Viņš Savā mācībā uz tiem sacīja: “Sargājaties no tiem rakstu mācītājiem, kam tīk garos svārkos staigāt un uz tirgiem tapt sveicinātiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'Un baznīcās jo augstos krēslos sēdēt un jo augstā vietā viesībās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Kas atraitņu namus aprij un taisnojās ar savām garām lūgšanām. Šie dabūs jo grūtu sodību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Un Jēzus sēdās Dieva šķirstam pretī un lūkoja, kā tie ļaudis naudu meta Dieva šķirstā; un daudz bagāti iemeta daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Un viena nabaga atraitne nāca un iemeta divas artavas, tas ir viens kvadrants.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Un Viņš Savus mācekļus aicināja un uz tiem sacīja: “Patiesi, Es jums saku, šī nabaga atraitne vairāk ir iemetusi nekā visi, kas Dieva šķirstā ir metuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Jo visi no savas bagātības ir metuši; bet šī no savas nabadzības ir iemetusi visu, kas tai bija, visu savu padomu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Un Viņam no Dieva nama izejot, viens no Viņa mācekļiem uz To sacīja: “Mācītāj, lūk, kādi akmeņi tie ir, un kādas ēkas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Un Jēzus atbildēja un uz to sacīja: “Vai tu visas šās lielās ēkas redzi? Tur akmens uz akmens netaps atstāts, kas netaps noplēsts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Un kad Viņš sēdēja uz Eļļas kalna Dieva namam pretī, tad Pēteris un Jēkabs un Jānis un Andrejs Viņu jautāja sevišķi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '“Saki mums, kad tas būs, un kāda tā zīme, kad viss tas piepildīsies?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Bet Jēzus tiem atbildēja un iesāka runāt: “Pielūkojiet, ka neviens jūs nepieviļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Jo daudzi nāks Manā Vārdā sacīdami: es tas esmu; un daudz pievils.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Bet kad jūs dzirdēsiet karus un kara valodas, tad nebēdājaties, jo tam būs tā notikt; bet tas gals vēl nav klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Jo tauta celsies pret tautu un valsts pret valsti un vietām būs zemes trīcēšanas, bada laiki un dumpji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Tas būs to grūto bēdu iesākums; bet lūkojiet jūs uz sevi pašiem; jo tie jūs nodos augstās tiesās un baznīcās; un jūs tapsiet šausti un Manis dēļ valdnieku un ķēniņu priekšā vesti, tiem par liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Un evaņģēlijam būs papriekš tapt sludinātam visām tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Kad nu tie jūs vedīs, jūs nododami, tad nebēdājaties iepriekš, kas jums būs jārunā, nedz apdomājaties; bet kas jums tanī pašā stundā taps dots, to runājiet; jo jūs neesat tie, kas runā, bet Tas Svētais Gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Bet tad brālis brāli nodos pie nāves un tēvs dēlu; un bērni celsies pret vecākiem un viņus nonāvēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Un jūs tapsiet ienīdēti no visiem Mana Vārda dēļ; bet kas pastāv līdz galam, tas taps izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Bet kad jūs to izpostīšanas negantību redzēsiet, par ko pravietis Daniēls ir runājis, ka tā stāv, kur neklājās (kas to lasa, tas lai to labi apdomā), tad lai bēg uz kalniem tie, kas ir Jūdu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Un kas uz jumta ir, tas lai nenokāpj namā un tur lai neieiet, ko no sava nama iznest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Un kas ir laukā, tas lai neatgriežas atpakaļ savas drēbes paņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Bet vai tām grūtām un tām zīdītājām tanīs dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Bet lūdzat, ka jūsu bēgšana nenotiek ziemas laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Jo tanī laikā būs tādas lielas bēdas, kādas nav bijušas no paša iesākuma, kamēr Dievs pasauli radījis līdz šim, un kādas arī nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Un ja Tas Kungs šās dienas nepaīsinātu, tad neviens netaptu izglābts; bet to izredzēto dēļ ko Viņš izredzējis, Viņš tās dienas ir paīsinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Un ja kas tanī laikā uz jums sacīs: redzi, še ir Kristus, jeb redzi, tur Viņš ir; tad neticiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Jo viltīgi Kristi un viltīgi pravieši celsies un lielas zīmes un brīnumus darīs, ka pieviltu, ja tas varētu notikt, arī tos izredzētos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Bet jūs pielūkojiet; redzi, Es jums to visu papriekš esmu sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Bet tanīs dienās, pēc tām bēdām, saule aptumšosies, un mēnesis nedos savu spīdumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Un debess zvaigznes nokritīs, un debess stiprumi kustināsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Un tad redzēs To Cilvēka Dēlu nākam padebešos ar lielu spēku un godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Un tad Viņš sūtīs Savus eņģeļus un sakrās Savus izredzētos no tiem četriem vējiem, no zemes gala līdz debess galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Bet mācaties līdzību no vīģes koka: kad viņa zars jau iezeļ, un lapas plaukst, tad jūs nomaniet, vasaru esam klātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Tā arīdzan, kad jūs šo visu redzēsiet notiekam, tad ziniet, ka tas ir tuvu priekš durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Patiesi, Es jums saku: šī cilts nezudīs, tiekams viss tas būs noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Debess un zeme zudīs, bet Mani vārdi nezudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Bet par to dienu jeb stundu neviens nezina, ne tie eņģeļi, kas debesīs, ne Tas Dēls, kā vien Tas Tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Pielūkojiet, esiet modrīgi un lūdziet, jo jūs nezināt, kad tas laiks ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Tā kā viens cilvēks, citur noiedams, atstāja savu namu un deva saviem kalpiem varu un ikkatram savu darbu, un pavēlēja durvju sargam būt nomodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Tad nu esat nomodā! Jo jūs nezināt, kad tas nama kungs nāk, vai vakarā, vai nakts vidū, vai gaiļos, vai no rīta agri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Ka tas nejauši nākdams, jūs neatrod guļam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Bet ko Es jums saku, to Es saku visiem: esat nomodā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Un pēc divām dienām bija Lieldiena un neraudzētās maizes svētki. Un tie augstie priesteri un rakstu mācītāji meklēja, kā tie Jēzu ar viltu saņemtu un nokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Bet tie sacīja: “Tik ne svētkos, lai dumpis neceļas starp ļaudīm.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Un kad Viņš bija Betanijā, Sīmaņa, tā spitālīgā, namā, un pie galda sēdēja, tad viena sieva nāca; tai bija akmens trauciņš ar ļoti dārgu un it tīru nardes eļļu, un, to trauciņu salauzusi, tā to lēja uz Viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Un tur bija kādi, kas pie sevis apskaitās un sacīja: “Ka labad šī eļļas izšķērdēšana notikusi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Jo šo eļļu varēja pārdot dārgāki nekā par trīssimt grašiem un izdalīt nabagiem;” un tie kurnēja par to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Bet Jēzus sacīja: “Liekat to mierā. Ko jūs tai raizes darāt? tā labu darbu pie Manis darījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Jo nabagi ir arvienu pie jums, un kad gribat, jūs tiem varat labu darīt; bet Es neesmu arvienu pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Šī ir darījusi, ko spējusi; tā jau iepriekš Manu miesu ir svaidījusi uz bērēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Patiesi, Es jums saku: kur vien šis evaņģēlijs kļūs sludināts pa visu pasauli, tur arī to teiks, ko šī darījusi, viņai par piemiņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Un Jūdas Iskariots, viens no tiem divpadsmit, nogāja pie tiem augstiem priesteriem, ka Viņu tiem nodotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Un tie to dzirdējuši priecājās un solīja tam dot naudu; un tas meklēja, kā tas Viņu izdevīgā laikā nodotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Bet pirmā neraudzētās maizes dienā, kad Lieldienas jēru nokāva, Viņa mācekļi uz Viņu sacīja: “Kur Tu gribi, lai mēs noejam un sataisām, ka Tu Lieldienas jēru vari ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Un Viņš sūtīja divus no Saviem mācekļiem un uz tiem sacīja: “Noejat uz pilsētu. Un jūs sastaps viens cilvēks, ūdens krūzi nesdams. Ejat tam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Un kur viņš ieiet, tur teiciet tam saimniekam: Mācītājs saka: kur ir tā vieta priekš Manis, kur ar Saviem mācekļiem varu ēst Lieldienas jēru?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Un viņš jums rādīs lielu, ar deķiem izklātu gatavu istabu. Turpat sataisiet priekš mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Un Viņa mācekļi izgāja un nāca pilsētā un atrada tā, kā Viņš tiem bija sacījis: un sataisīja to Lieldienas jēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Un kad vakars metās, tad Viņš nāca ar tiem divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Un tiem pie galda sēžot un ēdot, Jēzus sacīja: “Patiesi, Es jums saku: viens no jums, kas ar Mani ēd, Mani nodos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Un tie iesāka noskumt un cits pēc cita uz Viņu sacīt: “Vai es tas esmu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Bet Viņš atbildēja un uz tiem sacīja: “Viens no tiem divpadsmit, kas ar Mani mērc bļodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Tas Cilvēka Dēls gan aiziet tā, kā par Viņu ir rakstīts. Bet vai tam cilvēkam, caur ko Tas Cilvēka Dēls top nodots. Šim cilvēkam būtu labāki, ka nemaz nebūtu dzimis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Un tiem ēdot, Jēzus ņēma maizi, svētīja to, pārlauza un tiem to deva un sacīja: “Ņemiet, ēdiet, tā ir Mana miesa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Un Viņš ņēma to biķeri, pateicās un tiem to deva. Un tie visi dzēra no tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Un Viņš uz tiem sacīja: “Šīs ir Manas asinis, tās jaunās derības asinis, kas par daudziem top izlietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Patiesi, Es jums saku, ka Es vairs nedzeršu no vīna koka augļiem līdz tai dienai, kad Es to no jauna dzeršu Dieva valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Un to pateicības dziesmu dziedājuši, tie izgāja uz Eļļas kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Un Jēzus uz tiem sacīja: “Jūs visi šinī naktī apgrēcināsities pie Manis, jo stāv rakstīts: Es ganu sitīšu, un avis taps izklīdinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Bet kad Es augšām celšos, tad Es jūsu priekšā gribu noiet uz Galileju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Bet Pēteris uz To sacīja: “Un ja visi pie Tevis apgrēcinātos, tomēr es ne.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Un Jēzus uz to sacīja: “Patiesi, Es tev saku: šodien, šinī naktī, pirms gailis otrreiz dziedās, tu Mani trīskārt aizliegsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Bet tas runāja vēl daudz vairāk: “Jebšu man būtu līdz ar Tevi jāmirst, taču es Tevi negribu aizliegt!” Un tāpat arī visi sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Un tie nāca uz vienu muižu, kam vārds Ģetzemane, un Viņš uz Saviem mācekļiem sacīja: “Apsēžaties šeit, kamēr Es Dievu lūgšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Un Viņš ņēma pie sevis Pēteri un Jēkabu un Jāni, un iesāka baiļoties un trīcēt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Un uz tiem sacīja: “Mana dvēsele ir visai noskumusi līdz nāvei. Paliekat šeitan un esiet nomodā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Un maķenīt pagājis Viņš krita pie zemes un lūdza, ja tas varētu būt, lai tā stunda Viņam aizietu garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Un Viņš sacīja: “Abba, Tēvs, Tu spēji visas lietas! Ņem šo biķeri no Manis! Tomēr ne ko Es gribu, bet ko Tu gribi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Un Viņš nāk un atrod tos guļam un saka uz Pēteri: “Sīmani, vai tu guli? Vai tu nevienu stundu nespēji būt nomodā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Esat nomodā un lūdzat Dievu, ka neiekrītat kārdināšanā. Gars gan ir labprātīgs, bet miesa ir vāja.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Un Viņš atkal nogājis, Dievu lūdza, sacīdams šos pašus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Un Viņš griezās atpakaļ, un atrada tos atkal guļam, jo viņu acis bija miega pilnas, un tie nezināja, ko Viņam atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Un Viņš nāca trešu lāgu un uz tiem sacīja: “Guliet nu vēl un dusiet! jau ir gan; tā stunda ir nākusi! Redzi, Tas Cilvēka Dēls top nodots grēcinieku rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Ceļaties, ejam; redzi, kas Mani nodod, tas ir tuvu klāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Un tūdaļ, Viņam vēl runājot, atnāca Jūdas, viens no tiem divpadsmit, un līdz ar viņu daudz ļaužu ar zobeniem un nūjām no tiem augstiem priesteriem un rakstu mācītājiem un vecajiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Bet tas, kas Viņu nodeva, tiem bija devis zīmi sacīdams: “Kuru es skūpstīšu, tas ir Tas, To gūstat, un To novediet droši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Un tas nāca un tūdaļ Viņam piegājis sacīja: “Rabbi, Rabbi!” un Viņu skūpstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Un tie rokas pielika pie Viņa un To saņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Bet viens no tiem, kas pie Viņa stāvēja, zobenu izvilcis, cirta tā augstā priestera kalpam un tam nocirta ausi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Un Jēzus atbildēja un uz tiem sacīja: “Tā kā uz kādu slepkavu jūs esat izgājuši ar zobeniem un nūjām, Mani gūstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Ikdienas Es pie jums esmu sēdējis, Dieva namā mācīdams, un jūs Mani neesat gūstījuši. Bet lai tie raksti taptu piepildīti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Un visi Viņa mācekļi Viņu atstāja un bēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Un viens jauneklis Viņam gāja pakaļ, tas bija ar audekli apsedzies uz kailām miesām, un tie jaunekļi pēc tā tvarstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Bet to audekli pamezdams, tas no tiem izbēga pliks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Un tie Jēzu noveda pie tā augstā priestera, un tur sapulcējās visi augstie priesteri un vecaji un rakstu mācītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Un Pēteris no tālienes Viņam gāja pakaļ tā augstā priestera pilī iekšā, un sēdēja pie tiem sulaiņiem un sildījās pie uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Bet tie augstie priesteri un visa tā tiesa meklēja liecību pret Jēzu, ka tie Viņu nonāvētu, un neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Jo daudzi deva viltīgu liecību pret Viņu, un viņu liecības nebija vienādas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Un citi cēlušies deva viltīgu liecību pret Viņu, sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '“Mēs esam dzirdējuši, ka Viņš sacījis: “Es gribu šo rokām taisīto Dieva namu noplēst un trijās dienās citu, ne rokām taisītu, uzcelt.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Un arī šī viņu liecība nebija vienāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Un tas augstais priesteris cēlās viņu vidū, jautāja Jēzum un sacīja: “Vai Tu uz to nekā neatbildi, ko šie pret Tevi liecina?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Bet Viņš cieta klusu un neatbildēja nenieka. Un atkal tas augstais priesteris Viņam jautāja un uz Viņu sacīja: “Vai Tu esi Kristus, tā Augsti teicamā Dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Bet Jēzus sacīja: “Es tas esmu. Un jūs redzēsiet To Cilvēka Dēlu sēžam pie Tā Visuspēcīgā labās rokas un nākam ar debess padebešiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Tad tas augstais priesteris saplēsa savus svārkus un sacīja: “Kam vēl vajag liecinieku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Jūs Viņa zaimošanu esat dzirdējuši! Kā jums šķiet?” Bet tie visi Viņu notiesāja, ka Viņš nāvi esot pelnījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Un citi iesāka Viņu apspļaudīt un apsegt Viņa vaigu un Viņu sist dūrēm un uz Viņu sacīt: “Uzmini mūs, pravietis būdams.” Un tie sulaiņi Viņam sita vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Un kad Pēteris priekšnamā bija, tad viena no tā augstā priestera kalponēm nāca,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Un redzēja, ka Pēteris sildījās, un to uzlūkoja un sacīja: “Tu arīdzan biji pie Tā Jēzus no Nacaretes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Bet viņš liedzās, sacīdams: “Es Viņu nepazīstu, nedz zinu, ko tu runā.” Un tas izgāja no tā priekšnama. Un gailis dziedāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Un tā meita to atkal redzēja un iesāka sacīt uz tiem, kas klāt stāvēja: “Šis ir viens no tiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Bet tas atkal liedzās. Un par mazu brīdi tie, kas apkārt stāvēja, atkal uz Pēteri sacīja: “Patiesi, tu esi viens no tiem, jo tu esi Galilejs, un tava valoda tiem ir līdzīga.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Un tas sāka nolādēties un nodievoties: “Es nepazīstu To Cilvēku, par ko jūs runājiet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Un gailis dziedāja otru reizi; un Pēteris pieminēja to vārdu, ko Jēzus uz to bija sacījis: “Pirms nekā gailis divreiz dziedās, tu Mani trīs reiz aizliegsi;” un viņš iesāka raudāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Un tūlit no rīta tie augstie priesteri ar tiem vecajiem un rakstu mācītājiem un visa tā augstā tiesa sarunājās, un tie sēja Jēzu, noveda un nodeva Viņu Pilatum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Un Pilatus Viņam jautāja: “Vai Tu esi tas Jūdu ķēniņš?” Un Viņš atbildēja un uz to sacīja: “Tu to saki.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Un tie augstie priesteri Viņu gauži apsūdzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Bet Pilatus Viņam atkal vaicāja sacīdams: “Vai Tu nekā neatbildi? Redzi, cik gauži tie Tevi apsūdz!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Bet Jēzus neatbildēja vairs nenieka, tā ka Pilatus brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Bet uz svētkiem tas viņiem atlaida vienu cietumnieku, kuru tie prasīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Bet tur bija viens ar vārdu Baraba, gūstīts ar tiem dumpiniekiem, kas dumpī vienu bija nokāvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Un tie ļaudis augšā sanākuši iesāka prasīt, ka tiem tā darītu, kā allažiņ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Bet Pilatus tiem atbildēja un sacīja: “Vai jūs gribat, ka es jums To Jūdu ķēniņu atlaižu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Jo viņš zināja, ka tie augstie priesteri To no skaudības bija nodevuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Bet tie augstie priesteri tiem ļaudīm piekodināja, lai labāki tiem atlaistu to Barabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Bet Pilatus atbildēja un atkal uz tiem sacīja: “Ko tad jūs gribat, lai daru Tam, ko jūs saucat par Jūdu ķēniņu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Bet tie atkal brēca: “Sit Viņu krustā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Bet Pilatus uz tiem sacīja: “Ko tad Viņš ļaunu darījis?” Bet tie vēl vairāk brēca: “Sit Viņu krustā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Bet Pilatus gribēdams tiem ļaudīm izpatikt, tiem atlaida Barabu un nodeva Jēzu, kad Viņu bija šaustījis, ka taptu krustā sists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Bet tie karavīri Viņu noveda pilī, tas ir tiesas namā, un sasauca visu to pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Un tie Viņam apvilka sarkanu mēteli, un kroni no ērkšķiem nopinuši Viņam lika uz galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Un tie iesāka Viņu sveicināt: “Sveiks, Jūdu ķēniņ!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Un sita Viņa galvu ar niedri un Viņu apspļaudīja, un ceļus locīja un Viņu pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Un kad tie Viņu bija apsmējuši, tad Viņam novilka to sarkano mēteli un Viņam apvilka Viņa paša drēbes un Viņu izveda, ka Viņu krustā sistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Un tie spieda kādu, kas no lauka nākdams garām gāja, Sīmani no Kirenes, Aleksandera un Rufa tēvu, ka Viņa krustu nestu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Un tie Viņu noveda pie tās vietas Golgata, tas ir tulkots: pieres vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Un Viņam deva dzert vīnu, ar mirrēm sajauktu, bet Viņš to neņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Un kad To bija krustā situši, tad tie izdalīja Viņa drēbes un meta kauliņus par tām, ko kurš dabūtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Un tā bija tā trešā stunda, un Viņu sita krustā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Un tur virsraksts par Viņa vainu bija virsū uzrakstīts: Tas Jūdu Ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Un līdz ar Viņu sita krustā divas slepkavas, vienu pa labo, otru pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Un tie raksti ir piepildīti, kas saka: “Viņš ir līdzināts ļauna darītājiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Un tie, kas gāja garām, Viņu zaimoja, kratīja savas galvas un sacīja: “Raugi, kā Tu Dieva namu noplēsi un to uztaisi trejās dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Palīdzies pats un kāpi no krusta zemē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Tāpat arīdzan tie augstie priesteri ar tiem rakstu mācītājiem Viņu apmēdīja un sacīja: “Citus Viņš pestījis, Sevi pašu Viņš nevar pestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Lai nu Kristus, tas Israēla ķēniņš, no krusta nokāpj, ka mēs redzam un ticam.” Un arī tie, kas līdz ar Viņu bija krustā sisti, Viņu apsmēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Un ap sesto stundu palika tumšs pār visu zemi līdz devītajai stundai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Un ap devīto stundu Jēzus stiprā balsī brēca saukdams: “Eli, Eli, lama zabaktani!” Tas ir tulkots: Mans Dievs, Mans Dievs, kāpēc Tu Mani esi atstājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Un citi no tiem, kas tur klāt stāvēja, kad to dzirdēja, sacīja: “Redzi, Viņš sauc Eliju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Bet viens tecēja un pildīja sūkli ar etiķi un to lika uz niedri un Viņu dzirdināja sacīdams: “Laidiet, redzēsim, vai Elija nāks un Viņu noņems.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Bet Jēzus stiprā balsī brēcis dvēseli izlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Un priekškaramais auts Dieva namā pārplīsa divējos gabalos no augšas līdz zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Bet tas virsnieks, kas tur klāt stāvēja Viņam it pretī, redzēdams, ka Viņš tā brēkdams garu bija izlaidis, sacīja: “Patiesi, šis cilvēks bija Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Un tur bija arī sievas, kas no tālienes skatījās; starp tām bija Marija Madaļa un Marija, tā jaunākā, Jēkaba un Jāzepa māte, un Salome,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Kas arīdzan, kad Viņš bija Galilejā, Viņam bija gājušas pakaļ un Viņam kalpojušas, un daudz citas, kas līdz ar Viņu bija nākušas uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Un tās sataisāmās dienas vakarā, tas ir tai svētā vakarā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Jāzeps no Arimatijas, viens godīgs runas kungs, kas pats arīdzan uz Dieva valstību gaidīja, nāca un iegāja droši pie Pilatus un izlūdzās Jēzus miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Bet Pilatus brīnījās, ka Tas jau bija nomiris, un to kapteini aicinājis, tam jautāja, vai jau ilgi, kamēr Viņš nomiris?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Un no tā kapteiņa izklausinājis, viņš Jāzepam Jēzus miesas atvēlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Un tas smalku audekli pircis, Viņu noņēma un ietina tai smalkā audeklī un Viņu ielika kapā, kas klintī bija izcirsts, un pievēla akmeni priekš tā kapa durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Bet Marija Madaļa un Marija, Jāzepa māte, skatījās, kur Tas tapa nolikts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Un kad tā svēta diena bija pagājusi, tad Marija Madaļa un Marija, Jēkaba māte, un Salome pirka dārgas svaidāmas zāles, ka tās nāktu un Viņu svaidītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Un pirmajā nedēļas dienā ļoti agri, saulei lecot, tās nāca pie kapa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Un runāja savā starpā: “Kas mums to akmeni novels no kapa durvīm?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Un paskatīdamās tās redzēja, ka tas akmens bija novelts; jo tas bija ļoti liels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Un kapā iegājušas tās redzēja vienu jaunekli pa labo roku sēžam, apģērbtu baltās garās drēbēs. Un tās izbijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Bet viņš uz tām sacīja: “Neizbīstaties! Jūs meklējat Jēzu no Nacaretes, kas bija krustā sists; Tas ir augšām cēlies un nav šeitan. Redziet še to vietu, kur Viņu nolika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Bet noejat un sakāt to Viņa mācekļiem un Pēterim, ka Viņš jūsu priekšā noies uz Galileju; tur jūs Viņu redzēsiet, kā Viņš jums ir sacījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Un tās steigšus izgāja ārā un bēga no tā kapa, jo drebēšana un bailība tām bija uzgājusi, un nesacīja nevienam nenieka, jo tās bijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Bet kad Viņš bija uzcēlies pirmajā nedēļas dienā it agri, tad Viņš parādījās papriekš Marijai Madaļai, no kuras Viņš septiņus velnus bija izdzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Šī gāja un pasludināja tiem mācekļiem, kas bija noskumuši un raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Un šie dzirdēdami, ka Viņš esot dzīvs un no tās redzēts, neticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Bet pēc tam, kad divi no tiem staigāja, Jēzus tiem uz lauku ejot parādījās citā ģīmī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Un tie arīdzan nogājuši to tiem citiem pasludināja, un tie arī viņiem neticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Visupēc Viņš parādījās tiem vienpadsmit pie galda sēžot un norāja viņu neticību un sirds cietību, ka tie nebija ticējuši tiem, kas pēc Viņa augšām celšanās Viņu jau bija redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Un Viņš uz tiem sacīja: “Ejat pa visu pasauli un pasludinājiet evaņģēliju visai radībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kas tic un top kristīts, tas taps svēts, bet kas netic, tas taps pazudināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Bet šīs zīmes tiem ticīgiem ies līdz: Manā Vārdā tie velnus izdzīs, jaunām mēlēm runās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Čūskas aizdzīs; un kad tie kādas nāvīgas zāles dzers, tad tas tiem nekaitēs. Uz neveseliem tie rokas uzliks, un tad viņi kļūs veseli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Un Tas Kungs, kad Tas ar tiem bija runājis, ir uzņemts debesīs un sēž pie Dieva labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Un tie izgāja un mācīja visās malās, un Tas Kungs tiem palīdzēja strādāt un to vārdu apstiprināja caur līdzejošām zīmēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Kad nu daudzi uzņēmušies sarakstīt stāstus par tām lietām, kas mūsu starpā tik tiešām notikušas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Tā kā tie mums ziņu devuši, kas no iesākuma paši tās redzējuši un Dieva vārda kalpi bijuši:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Tad arī man likās labi esam, ka es visas šīs lietas no pirmā gala it smalki izmeklējis, pēc kārtas tev sarakstu, mans mīļais Teofil,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Ka tu vari atzīt to īsteno mācības patiesību, kas tev mācīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Hērodus, Jūdejas ķēniņa, laikā bija viens priesteris, vārdā Zaharija, no Abijas kārtas, un viņa sieva no Ārona meitām, un viņai vārds bija Elizabete.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Un tie abi bija taisni Dieva priekšā, nenoziedzīgi staigādami iekš visiem Tā Kunga baušļiem un likumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Un tiem nebija neviena bērna; jo Elizabete bija neauglīga, un tie abi jau bija piedzīvojuši labu vecumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Bet notikās, viņam svēto priestera darbu Dieva priekšā darot savā pienākamā kārtā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Tad pēc priesteru ieraduma viņam pienācās ieiet Tā Kunga namā un kvēpināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Un viss ļaužu pulks ārā lūdza Dievu tai kvēpināšanas stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Bet viņam Tā Kunga eņģelis parādījās, stāvēdams pie kvēpināšanas altāra labās puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Un Zaharija to redzēdams izbijās, un bailes tam uznāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Bet tas eņģelis uz to sacīja: “Nebīsties, Zaharija, jo tava lūgšana ir paklausīta, un tava sieva Elizabete dzemdēs dēlu, un tu viņa vārdu sauksi: Jānis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Un tev būs prieks un līksmība, un daudzi par viņa piedzimšanu priecāsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Jo viņš būs liels Tā Kunga priekšā, vīnu un stipru dzērienu viņš nedzers un vēl savas mātes miesās viņš taps piepildīts ar Svētu Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Un viņš daudz no Israēla bērniem atgriezīs pie Tā Kunga, sava Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Un viņš ies Viņa priekšā Elijas garā un spēkā, atgriezdams tēvu sirdis pie bērniem un neklausīgos pie taisno gudrības, Tam Kungam sataisīt gatavus ļaudis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Un Zaharija sacīja uz to eņģeli: “Kā es to zināšu? Jo es esmu vecs, un mana sieva jau ir vecīga.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Un tas eņģelis atbildēja un uz to sacīja: “Es esmu Gabriēls, kas stāv Dieva priekšā, un esmu sūtīts ar tevi runāt un tev pasludināt šo prieka vēsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Un redzi, tu tapsi mēms un nevarēsi runāt līdz tai dienai, kad šās lietas notiks, tāpēc ka tu neesi ticējis maniem vārdiem, kas notiks savā laikā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Un tie ļaudis gaidīja uz Zahariju un brīnījās par viņa kavēšanos Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Un ārā iznācis tas nevarēja uz tiem runāt, un tie nomanīja, ka viņš Dieva namā bija redzējis kādu parādīšanu, un viņš tiem meta ar roku un palika mēms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Un notikās, kad viņa kalpošanas dienas bija pabeigtas, tad viņš nogāja uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Un pēc šīm dienām Elizabete, viņa sieva, tapa grūta un paslēpās piecus mēnešus sacīdama:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '“Tā Tas Kungs man ir darījis tanīs dienās, kad Viņš mani uzlūkojis, no manis atņemt manu kaunu starp cilvēkiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Un sestā mēnesī eņģelis Gabriēls no Dieva tapa sūtīts uz Galilejas pilsētu ar vārdu Nacarete');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Pie jumpravas, kas bija saderēta vīram, kam vārds Jāzeps, no Dāvida cilts, un tās jumpravas vārds bija Marija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Un pie tās ienācis tas eņģelis sacīja: “Esi sveicināta, tu apžēlotā, Tas Kungs ar tevi, tu augsti teicama starp sievām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Bet viņa to redzēdama iztrūkās par viņa valodu un domāja pie sevis, kas tā par sveicināšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Un tas eņģelis uz to sacīja: “Nebīsties, Marija, jo tu žēlastību esi atradusi pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Un redzi, tu tapsi grūta savās miesās un dzemdēsi Dēlu un sauksi Viņa vārdu: Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Tas būs liels un taps nosaukts Tā Visuaugstākā Dēls, un Dievs Tas Kungs Tam dos Viņa tēva Dāvida krēslu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Un Viņš valdīs pār Jēkaba namu mūžīgi, un Viņa valstībai nebūs gals.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Bet Marija sacīja uz to eņģeli: “Kā lai tas notiek? Jo es no vīra nezinos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Un tas eņģelis atbildēja un uz to sacīja: “Tas Svētais Gars nāks pār tevi un Tā Visuaugstākā spēks tevi apēnos, tāpēc arī Tas Svētais, kas no tevis dzims, taps nosaukts Dieva Dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Un redzi, Elizabete, tava radiniece, savā vecumā arīdzan ir grūta ar dēlu un iet tagad sestā mēnesī, kurai tāda slava, ka esot neauglīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Jo Dievam nekāda lieta nav neiespējama.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Bet Marija sacīja: “Redzi, es esmu Tā Kunga kalpone, lai man notiek pēc tava vārda.” Un tas eņģelis no tās aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Un Marija cēlās tanīs dienās un steidzās iet pār tiem kalniem uz vienu pilsētu iekš Jūda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Un iegāja Zaharijas namā un sveicināja Elizabeti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Un notikās, kad Elizabete Marijas sveicināšanu dzirdēja, tad tas bērniņš uzlēca viņas miesās, un Elizabete tapa Svēta Gara pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Un viņa stiprā balsī sauca un sacīja: “Tu esi augsti teicama starp sievām un augsti teicams ir tavas miesas auglis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Un kā tas man notiek, ka mana Kunga māte nāk pie manis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Jo redzi, tikko tavas sveicināšanas balss manās ausīs atskanēja, tad tas bērniņš manās miesās ar līksmību uzlēca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Un svētīga tu, kas esi ticējusi, jo tas taps piepildīts, kas tev no Tā Kunga sacīts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Un Marija sacīja: “Mana dvēsele teic augsti To Kungu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Un mans gars priecājās par Dievu, manu Pestītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Jo Viņš ir uzlūkojis savas kalpones zemību; redzi, no šī laika visi bērnu bērni mani teiks svētīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Jo Tas Spēcīgais lielas lietas pie manis darījis; un svēts ir Viņa Vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Un Viņa žēlastība paliek uz radu radiem pie tiem, kas Viņu bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Viņš darījis varenus darbus ar Savu elkoni un izkaisījis, kas ir lieli savā sirds prātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Viņš varenos nogrūdis no augstiem krēsliem, un pacēlis pazemīgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Izsalkušos Viņš pildījis ar labumiem, un bagātos Viņš atstājis tukšus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Viņš uzņēmis Savu kalpu Israēli un pieminējis Savu žēlastību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Kā Viņš runājis mūsu tēviem, Ābrahāmam un viņa bērniem mūžīgi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Un Marija palika pie tās kādus trīs mēnešus, pēc tam viņa atgriezās atpakaļ uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Un Elizabetes laiks nāca, ka tai bija dzemdēt, un viņa dzemdēja dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Un viņas kaimiņi un radi dzirdēja, ka Tas Kungs lielu žēlastību pie tās bija darījis, un tie priecājās līdz ar viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Un notikās astotā dienā, tad tie nāca, to bērniņu apgraizīt, un pēc viņa tēva vārda to sauca Zahariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Un viņa māte atbildēja un sacīja: “Nē, bet to būs nosaukt Jānis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Un tie viņai sacīja: “Neviena nav tavos rados, kam tāds vārds.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Un tie prasīja zīmes no viņa tēva, kā viņš gribētu, lai to sauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Un tas galdiņu prasījis rakstīja tā: viņa vārds ir Jānis. Par to visi brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Un tūdaļ viņa mute atdarījās, un viņa mēle tapa atraisīta, un tas runāja, Dievu slavēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Un izbailes uznāca visiem kaimiņiem, un visa šī lieta tapa zināma pa visiem Jūdu zemes kalniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Un visi, kas to dzirdēja, to ņēma pie sirds un sacīja: “Kas būs ar šo bērniņu? Jo Tā Kunga roka bija ar viņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Un viņa tēvs Zaharija tapa Svēta Gara pilns, sludināja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '“Slavēts ir Tas Kungs, Israēla Dievs, jo tas Savus ļaudis piemeklējis un pestījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Un mums uzcēlis pestīšanas ragu Sava kalpa Dāvida namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Kā Tas pirmajos laikos runājis caur Savu svēto praviešu muti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Ka Viņš mūs pestītu no mūsu ienaidniekiem un no visu to rokas, kas mūs ienīst;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Un parādītu žēlastību mūsu tēviem un pieminētu Savu svēto derību');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Un to stipro solīšanu, ko Viņš mūsu tēvam Ābrahāmam ir zvērējis, mums dot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Ka mēs, no savu ienaidnieku rokām pestīti, Viņam bez bailības kalpojam');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'Iekš svētības un taisnības Viņa priekšā visu savu mūžu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Un tu, bērniņ, tapsi nosaukts tā Visuaugstākā pravietis; un tu Tam Kungam iesi priekšā, Viņa ceļus sataisīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Un Viņa ļaudīm dot pestīšanas atzīšanu uz grēku piedošanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Mūsu Dieva sirsnīgas žēlastības dēļ caur ko tas auseklis no augstības mūs apraudzījis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Ka tas tiem atspīdētu, kas sēž tumsībā un nāves ēnā, un mūsu kājas atgrieztu uz miera ceļu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Un tas bērniņš auga un garā stiprinājās, un bija tuksnesī līdz tai dienai, kad tas parādījās priekš Israēla ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Un notika tanī laikā, ka grāmatas no ķeizara Augusta tapa izsūtītas, ka visa pasaule taptu uzrakstīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Un šī pirmā uzrakstīšana notika to brīdi, kad Kirenijus Sīrijā valdīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Un visi nogāja, ka liktos pierakstīties, ikviens savā cilts pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Tad arī Jāzeps no Galilejas, no Nacaretes pilsētas, nogāja uz Jūdu zemi, uz Dāvida pilsētu, vārdā Bētlemi, tāpēc ka tas bija no Dāvida rada un cilts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Ka liktos pierakstīties ar Mariju, savu saderēto sievu, kas bija grūta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Un notikās, tiem turpat esot, tas laiks atnāca, ka tai bija dzemdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Un viņai piedzima pirmdzimtais Dēls, un tā To ietina autiņos un To lika silē, jo tiem citur nebija rūmes tai mājas vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Un gani bija ap to pašu vietu laukā pie laidariem, tie nomodā būdami naktī savus lopus sargāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Un redzi, Tā Kunga eņģelis pie tiem piestājās, un Tā Kunga spožums tos apspīdēja, un tie bijās ļoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Un tas eņģelis uz tiem sacīja: “Nebīstaties, jo redzi, es jums pasludinu lielu prieku, kas visiem ļaudīm notiks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Jo jums šodien Tas Pestītājs dzimis, kas ir Kristus, Tas Kungs, Dāvida pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Un to ņematies par zīmi: jūs atradīsiet bērnu autos ietītu un silē gulošu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Un tūdaļ tur pie tā eņģeļa bija tas debesu draudzības pulks; tie Dievu slavēja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '“Gods Dievam augstībā un miers virs zemes un cilvēkiem labs prāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Un notikās, kad tie eņģeļi no tiem uz debesīm bija aizgājuši, tad tie gani runāja savā starpā: ejam tad nu uz Bētlemi, raudzīt, kas tur noticis, kā Tas Kungs mums licis ziņu dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Un tie steigdamies nāca un atrada gan Mariju, gan Jāzepu un To bērniņu, silē gulošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Bet kad tie to bija redzējuši, tad tie izpauda to vārdu, kas tiem par To bērnu bija sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Un visi, kas to dzirdēja, izbrīnījās par to valodu, ko tie gani tiem bija sacījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Bet Marija visus tos vārdus paturēja, tos savā sirdī apdomādama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Un tie gani griezās uz mājām, godāja un teica Dievu par visu, ko tie bija dzirdējuši un redzējuši, kā uz tiem bija sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Un kad astoņas dienas bija pagājušas, ka tas bērns taptu apgraizīts, tad Viņa vārdu nosauca Jēzu, kā no tā eņģeļa bija sacīts, pirms Viņš bija ieņemts mātes miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Un kad viņu šķīstīšanas dienas nāca pēc Mozus bauslības, tad tie Viņu nesa uz Jeruzālemi, ka To stādītu Tā Kunga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(Kā Tā Kunga bauslībā stāv rakstīts: ikviena pirmdzimtība no vīriešu kārtas lai top nosaukta Tam Kungam svēta);');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'Ka tie arī to upuri dotu, kā Tā Kunga bauslībā ir sacīts: vienu pāri ūbeļu baložu vai divus jaunus baložus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Un redzi, viens cilvēks bija Jeruzālemē, vārdā Sīmeans; šis cilvēks bija taisns un dievbijīgs, gaidīdams uz Israēla iepriecināšanu, un Tas Svētais Gars bija iekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Tam no Svētā Gara bija pasludināts, ka nāvi neredzēšot, iekams Tā Kunga Svaidīto nebūšot redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Tas nāca Dieva namā no Svētā Gara skubināts; un kad tie vecāki To Jēzus bērnu ienesa, ka ar To darītu pēc bauslības ieraduma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Tad To uz savām rokām ņēmis, viņš Dievu teica un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '“Kungs, lai nu Tavs kalps aiziet mierā, kā Tu esi sacījis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Jo manas acis Tavu pestīšanu redzējušas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Ko Tu esi sataisījis priekš visiem ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Gaismu, apgaismot pagānus, un par slavu Taviem Israēla ļaudīm.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Un Jāzeps un viņa māte brīnījās par to, ko viņš runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Un Sīmeans tos svētīja un sacīja uz Mariju, Viņa māti: “Redzi, Šis ir likts par krišanu un augšāmcelšanos daudz ļaudīm iekš Israēla, un par zīmi, kam top pretī runāts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'Un tev pašai caur dvēseli zobens spiedīsies, ka daudz siržu domas taps zināmas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Un tur bija viena praviete, Anna, Fānuēļa meita, no Ašera cilts, tā bija ļoti veca, un pēc savas jumpravības bija dzīvojusi septiņus gadus ar savu vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'Un tā bija atraitne pie astoņdesmit četriem gadiem; tā neatstājās no Dieva nama, ar gavēšanu un lūgšanu Dievam kalpodama dienās, naktīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Tā arīdzan tai pašā stundā piegāja un teica To Kungu, par To runādama uz visiem, kas uz pestīšanu Jeruzālemē gaidīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Un visu pabeiguši pēc Tā Kunga bauslības, tie atkal griezās uz Galileju, uz savu pilsētu Nacareti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Bet Tas Bērns auga un palika stiprs garā, pilns gudrības, un Dieva žēlastība bija pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Un Viņa vecāki gāja ik gadus uz Jeruzālemi Lieldienas svētkos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Un kad Viņš bija divpadsmit gadus vecs, tad tie pēc svētku ieraduma gāja uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Un kad tās svētās dienas bija pagalam, tad tiem atkal uz mājām ejot Tas Bērns Jēzus palika Jeruzālemē, un Jāzeps un Viņa māte to nezināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Bet tie domāja, ka Tas esot pie tiem ceļa biedriem; un vienas dienas gājumu nākuši, tie To meklēja pie radiem un pazīstamiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Un kad tie To neatrada, tad tie gāja atpakaļ uz Jeruzālemi, To meklēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Un notikās, pēc trim dienām tie Viņu atrada baznīcā sēžam starp tiem mācītājiem, tos dzirdot un tos jautājot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Un visi, kas Viņu dzirdēja, iztrūkušies brīnījās par Viņa saprašanu un Viņa atbildēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Un Viņu ieraudzījuši, tie pārbijās; un Viņa māte uz To sacīja: mans dēls, kāpēc Tu mums tā esi darījis? Redzi, Tavs tēvs un es, mēs Tevi ar sāpēm esam meklējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Un Viņš uz tiem sacīja: “Kam jūs Mani esat meklējuši? Vai nezinājāt, ka Man iekš Mana Tēva lietām jādarbojas?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Bet tie to vārdu neizprata, ko Viņš uz tiem sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Un Viņš nogāja tiem līdz un nāca uz Nacareti un bija tiem paklausīgs. Bet Viņa māte visus šos vārdus paturēja savā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Un Jēzus pieņēmās gudrībā, augumā un piemīlībā pie Dieva un cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Piecpadsmitā ķeizara Tiberijus valdīšanas gadā, kad Poncius Pilatus bija zemes valdītājs Jūdejā un Hērodus valdnieks Galilejā un Filips, viņa brālis, valdnieks Iturejā un Trakonites tiesā un Lizanijus valdnieks Abilenē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Apakš tiem augstiem priesteriem Annasa un Kajafasa, Dieva vārds notika uz Jāni, Zaharijas dēlu, tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Un viņš gāja pa visu Jardānes apgabalu, sludinādams kristību uz atgriešanos no grēkiem par grēku piedošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Itin kā rakstīts pravieša Jesajas grāmatā, kas saka: “Saucēja balss tuksnesī: “Sataisiet Tā Kunga ceļu, dariet līdzenas Viņa tekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Visas ielejas lai top pildītas, un visi kalni un pakalni lai top zemoti, un kas nelīdzens, lai top līdzens, un kas celmains, par staigājamu ceļu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Un visa miesa redzēs Tā Kunga pestīšanu.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Tāpēc viņš sacīja uz tiem ļaudīm, kas izgāja, ka no viņa tiktu kristīti: “Jūs odžu dzimums, kas jums ir rādījis izbēgt no nākamās dusmības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Tāpēc nesiet pienākamus atgriešanās augļus; un nesākat savā prātā sacīt: “Mums ir Ābrahāms par tēvu.” Jo Es jums saku, ka Dievs no šiem akmeņiem Ābrahāmam spēj bērnus radīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Jau arī cirvis kokiem pie saknes pielikts; tāpēc ikkatrs koks, kas nenes labus augļus, top nocirsts un ugunī iemests.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Un tie ļaudis tam jautāja un sacīja: “Ko tad mums būs darīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Viņš atbildēja un uz tiem sacīja: “Kam divi svārki, tas lai dod tam, kam nav; un kam ir barība, lai dara tāpat.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Bet arī muitnieki nāca, ka liktos kristīties, un uz to sacīja: “Mācītāj, ko mums būs darīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Un viņš uz tiem sacīja: “Neņemiet vairāk, nekā jums ir nospriests.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Bet arī karavīri tam jautāja un sacīja: “Ko tad mums būs darīt?” Un viņš uz tiem sacīja: “Nedariet nevienam pāri, neapmelojiet nevienu un esat mierā ar savu algu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Bet tiem ļaudīm gaidot un visiem savā prātā par Jāni domājot, vai tas neesot Kristus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Jānis visiem atbildēja sacīdams: “Es jūs gan kristīju ar ūdeni, bet Viens nāks, spēcīgāks, nekā es, Tam es neesmu cienīgs atraisīt Viņa kurpju siksnas. Tas jūs kristīs ar Svētu Garu un uguni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Tam vēteklis rokā, un Viņš tīrīs Savu klonu caur caurim un sakrās kviešus Savā klētī, bet pelavas sadedzinās ar neizdzēšamu uguni.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Arī vēl daudz citu ko mācīdams, viņš pasludināja tiem ļaudīm prieka vēsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Bet Hērodus, viens no tiem četriem valdniekiem, no viņa pārmācīts Hērodeijas, Filipa, sava brāļa, sievas dēļ, un visa ļauna dēļ, ko Hērodus bija darījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Pie visa tā arī šo vēl darīja, ka Jāni ieslēdza cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Un notikās, kad visi ļaudis tapa kristīti, un arī Jēzus bija kristīts un Dievu pielūdza, tad debesis atvērās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'Un Svētais Gars nolaidās uz Viņu redzamā ģīmī kā balodis; un balss atskanēja no debesīm sacīdama: “Tu esi Mans mīļais Dēls, pie Tevis Man ir labs prāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Un Viņš pats, Jēzus, bija trīsdesmitā gadā un bija pēc ļaužu domām Jāzepa dēls, tas bija Elus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Tas Matata, tas Levja, tas Melkus, tas Janna, tas Jāzepa dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Tas Matatijas, tas Amosa, tas Naūma, tas Eslus, tas Nagaja dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Tas Maāta, tas Matatijas, tas Zemeja, tas Jāzepa, tas Jūdas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Tas Jāņa, tas Rezas, tas Corobabeļa, tas Zalatiēļa, tas Nerus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Tas Melķus, tas Addas, tas Kozama, tas Elmodama, tas Era dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Tas Jāzepa, tas Eliēcera, tas Jorema, tas Matata, tas Levja dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Tas Sīmeana, tas Jūdas, tas Jāzepa, tas Jonana, tas Eliaķima dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Tas Meleas, tas Menas, tas Matatas, tas Natana, tas Dāvida dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Tas Isajus, tas Obeda, tas Boasa, tas Zalmana, tas Nahšona dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Tas Aminadaba, tas Arama, tas Hecrona, tas Vāreca, tas Jūdas dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Tas Jēkaba, tas Īzaka, tas Ābrahāma, tas Tārus, tas Nahora dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Tas Serugs, tas Regus, tas Pelegs, tas Ēbera, tas Šalus dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Tas Kainana, tas Arvaksada, tas Zema, tas Noas, tas Lāmeha dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Tas Matuzalas, tas Enoha, tas Jareda, tas Mahalaleēla, tas Kainana dēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Tas Enosa, tas Seta, tas Ādama dēls, tas Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Bet Jēzus, Svēta Gara pilns, nāca atpakaļ no Jardānes un no Tā Gara tapa vests tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Tur Viņš četrdesmit dienas no velna tapa kārdināts; un tanīs dienās nebaudīja nenieka, un kad tās bija pagājušas, tad pēc Viņam gribējās ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Un velns uz Viņu sacīja: “Ja Tu esi Dieva Dēls, tad saki šim akmenim, lai tas top par maizi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Bet Jēzus tam atbildēja un sacīja: “Stāv rakstīts: cilvēks nedzīvo no maizes vien, bet no ikviena Dieva vārda.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Un velns Viņu veda uz ļoti augstu kalnu un Tam rādīja visas pasaules valstis vienā acumirklī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Un velns uz Viņu sacīja: “Es Tev došu visu šo varu un šo godību, jo tā man ir nodota, un kam es gribu, tam es to dodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Kad Tu nu mani pielūgsi, tad viss tas būs Tavs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Un Jēzus tam atbildēja sacīdams: “Atkāpies no Manis; jo stāv rakstīts: tev būs pielūgt To Kungu, savu Dievu, un Viņam vien kalpot.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Un tas Viņu veda uz Jeruzālemi, un Viņu cēla Dieva nama jumta galā un sacīja uz Viņu: “Ja Tu esi Dieva Dēls, tad nolaidies no šejienes zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Jo stāv rakstīts: Viņš Saviem eņģeļiem par Tevi pavēlēs, Tevi pasargāt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'Un tie Tevi uz rokām nesīs, ka Tu savu kāju pie akmens nepiedauzīsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Un Jēzus atbildēja un uz to sacīja: “Ir sacīts: tev To Kungu, savu Dievu, nebūs kārdināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Un velns visu savu kārdināšanu beidzis, no Viņa atstājās līdz savam laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Un Jēzus Gara spēkā griezās atpakaļ uz Galileju, un Viņa slava izpaudās pa visu apkārtēju zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Un Viņš mācīja viņu baznīcās un tapa slavēts no visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Un Viņš nāca uz Nacareti, kur bija audzināts, un pēc Sava ieraduma svētdienā iegāja baznīcā, un Viņš pacēlās lasīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Un Viņam deva pravieša Jesajas grāmatu, un to grāmatu atvēris, Viņš atrada to vietu, kur bija rakstīts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '“Tā Kunga gars ir uz Manis, tāpēc Viņš Mani svaidījis, nabagiem sludināt prieka vēsti, tos, kam sagrauztas sirdis, dziedināt, cietuma ļaudīm sludināt atsvabināšanu, un akliem gaismu, salauztos palaist vaļā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Pasludināt Tā Kunga žēlastības gadu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Un to grāmatu aiztaisījis, Viņš to deva tam sulainim un apsēdās. Un visi, kas tur bija baznīcā, savas acis meta uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Un Viņš iesāka uz tiem sacīt: “Šodien šis raksts ir piepildīts jūsu ausīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Un visi Viņam deva liecību un brīnījās par tādiem žēlastības vārdiem, kas no Viņa mutes izgāja, un sacīja: “Vai šis nav Jāzepa dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Un Viņš uz tiem sacīja: “Jūs laikam gan uz Mani sacīsiet šo sakāmu vārdu: ārsts, dziedini pats sevi! Visu, ko esam dzirdējuši, kā noticis Kapernaūmā, to dari arī še Savā tēva pilsētā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Un Viņš sacīja: “Patiesi, Es jums saku: neviens pravietis nav pieņēmīgs savā tēva pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Bet tiešām, Es jums saku: Daudz atraitņu bija Elijas laikā iekš Israēla, kad debess bija aizslēgta trīs gadus un sešus mēnešus, ka liels bads uzgāja visai tai zemei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Un Elija nekļuva sūtīts pie nevienas no tām, kā vien pie vienas atraitnes uz Sareptu Sidonijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Un daudz spitālīgu bija pravieša Elišas laikā iekš Israēla, un neviens no tiem netapa šķīstīts, kā vien Naēmans no Sīrijas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Un to dzirdēdami, visi baznīcā tapa dusmu pilni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Un cēlušies To izstūma no pilsētas ārā un veda uz kalna malu, kur viņu pilsēta stāvēja, ka To nogāztu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Un caur viņu vidu iedams Viņš aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Un Viņš nogāja uz Kapernaūmu, Galilejas pilsētu, un tos mācīja svētdienās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Un tie ļoti brīnījās par Viņa mācību, jo Viņa vārdi bija vareni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Un tur baznīcā bija viens cilvēks, tam bija nešķīsta velna gars, un tas brēca stiprā balsī');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Sacīdams: “Vai! kas mums ar Tevi, Jēzu no Nacaretes? Vai Tu esi nācis, mūs nomaitāt? Es Tevi pazīstu, kas Tu esi, Tas Dieva Svētais.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Un Jēzus to apdraudēja sacīdams: “Paliec klusu un izej no tā.” Un velns to raustīja viņu vidū un izgāja no tā, tam neko ļauna nepadarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Un izbailes uznāca visiem un tie runāja savā starpā sacīdami: “Kas tas par vārdu? Jo Viņš ar varu un spēku pavēl nešķīstiem gariem, un tie atstājās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Un Viņa slava izgāja pa visu apkārtēju zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Un cēlies no tās baznīcas, Viņš nonāca Sīmaņa namā. Bet Sīmaņa sievas māte gulēja ar grūtu drudzi, un tie viņas dēļ To lūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Un Viņš galvgalā pie tās piestājies apdraudēja to drudzi un tas no tās atstājās; un tā tūdaļ cēlās un viņiem kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Un kad saule bija nogājusi, tad visi, kam bija neveseli ar dažādām sērgām, tos noveda pie Viņa; un Viņš ikkatram no tiem rokas uzlika un tos dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Un tur arī velni no daudziem atstājās, brēkdami un sacīdami: “Tu esi Kristus, Dieva Dēls!” Un Viņš tos apdraudēja un tiem neļāva teikt, ka tie zināja, Viņu esam Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Un gaismai austot Viņš iziedams gāja uz tuksnesi. Un tie ļaudis Viņu meklēja un pie Viņa nogāja un Viņu turēja, lai no tiem neaizietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Un Viņš uz tiem sacīja: “Arī tām citām pilsētām Man pienākas sludināt Dieva valstības priecas mācību, jo tāpēc Es esmu sūtīts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Un Viņš sludināja Galilejas baznīcās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Bet notikās, kad tie ļaudis pie Viņa spiedās, Dieva vārdu dzirdēt, un Viņš stāvēja pie Ģenecaretes ezera,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Tad Viņš redzēja divas laivas pie ezera stāvam, bet tie zvejnieki bija izkāpuši un mazgāja savus tīklus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Bet Viņš kāpa vienā laivā, kas Sīmanim piederēja, un tam lūdza, maķenīt no malas nocelt, un Viņš nosēdās un mācīja tos ļaudis no tās laivas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Un beidzis runāt Viņš uz Sīmani sacīja: “Dodies uz augšu, un izmetiet savus tīklus, ka jūs lomu velkat.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Un Sīmanis atbildēja un uz Viņu sacīja: “Kungs, mēs cauru nakti strādājuši un nenieka neesam dabūjuši; bet uz Tavu vārdu es to tīklu gribu izmest.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Un kad tie to darīja, tad tie saņēma lielu pulku zivju, tā ka viņu tīkls saplīsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Un tie meta ar roku saviem biedriem, kas bija otrā laivā, lai nāktu palīgā vilkt. Un tie nāca un piepildīja abas laivas pilnas, tā ka tās tik negrima.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Kad Sīmanis Pēteris to redzēja, tad viņš krita Jēzum pie kājām un sacīja: “Kungs, izej no manis, jo es esmu grēcīgs cilvēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Jo tam izbailes bija uzgājušas un visiem, kas pie viņa bija, par šo lomu, ko tie bija vilkuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Tā arī Jēkabam un Jānim, Cebedeja dēliem, Sīmaņa biedriem. Un Jēzus sacīja uz Sīmani: “Nebīsties, jo no šī laika tev būs cilvēkus zvejot.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Un tie vilka savas laivas pie malas un, visas lietas atstājuši, gāja Viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Un notikās, kad Viņš tur bija vienā pilsētā, redzi, tad viens cilvēks, spitālības pilns, Jēzu redzēdams nometās uz savu vaigu, Viņu pielūdza un sacīja: “Kungs, ja Tu gribi, tad Tu mani vari šķīstīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Un roku izstiepis, Viņš to aizskāra sacīdams: “Es gribu, topi šķīstīts.” Un tūdaļ spitālība no tā nozuda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Un Viņš tam pavēlēja, nevienam to nesacīt: “Bet noej un rādies priesterim un upurē par savu šķīstīšanu, ko Mozus ir pavēlējis tiem par liecību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Un Viņa slava jo vairāk izpaudās, un daudz ļaudis sapulcējās, Viņu dzirdēt un tapt dziedināti no savām slimībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Bet Viņš nogāja tuksnesī un pielūdza Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Un notikās kādā dienā Viņam mācot, tad tur farizeji sēdēja un bauslības mācītāji, kas bija nākuši no visiem Galilejas un Jūdejas un Jeruzālemes miestiem. Un Tā Kunga spēks parādījās Viņam dziedinājot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Un redzi, vīri nesa uz gultas vienu cilvēku, tas bija melmeņu sērdzīgs; un tie meklēja, to ienest un nolikt Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Un neatrazdami, kur viņu ienest, to ļaužu dēļ, tie uzkāpa jumtā un to nolaida caur griestiem ar gultu pašā vidū Jēzum priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Un Tas viņu ticību redzēdams uz to sacīja: “Cilvēks, tavi grēki tev ir piedoti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Un tie rakstu mācītāji un farizeji iesāka domāt pie sevis un sacīt: “Kas Tas tāds, ka Tas runā Dieva zaimošanas? Kas var grēkus piedot kā vien Tas Vienīgais Dievs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Bet nomanīdams viņu domas, Jēzus atbildēja un uz tiem sacīja: “Ko jūs domājat savās sirdīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Kas ir vieglāki sacīt: tavi grēki tev ir piedoti, vai sacīt: celies un staigā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Bet lai jūs zināt, ka Tam Cilvēka Dēlam ir vara virs zemes, grēkus piedot, (tad Viņš uz to melmeņu sērdzīgo sacīja:) Es tev saku: celies un ņem savu gultu un ej uz savām mājām!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Un tas tūdaļ viņiem redzot pacēlās, paņēma to, uz ko tas bija gulējis, un aizgāja uz savām mājām Dievu slavēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Un brīnīšanās visiem uzgāja, un tie slavēja Dievu: un tie bijāšanas pilni sacīja: “Mēs šodien brīnuma lietas esam redzējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Un pēc tam Viņš izgāja un ieraudzīja vienu muitnieku, vārdā Levi, pie muitas sēžam un uz to sacīja: “Nāc Man pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Un visu atstājis tas cēlās un gāja Viņam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Un Levi Viņam taisīja lielu mielastu savā namā, un tur bija liels pulks muitnieku un citu, kas līdz ar tiem apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Un tie rakstu mācītāji un farizeji kurnēja pret Viņa mācekļiem un sacīja: “Kāpēc jūs ēdat un dzerat ar muitniekiem un grēciniekiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Un Jēzus atbildēja un uz tiem sacīja: “Veseliem ārstus nevajag, bet vājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Es neesmu nācis, taisnus aicināt pie atgriešanās no grēkiem, bet grēcinekus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Bet tie uz Viņu sacīja: “Kāpēc Jāņa mācekļi tik daudz gavē un Dievu lūdz, tā kā arī tie farizeju mācekļi, bet tavi ēd un dzer?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Bet Viņš uz tiem sacīja: “Kāzu ļaudīm jūs nevarat likt gavēt, kamēr brūtgāns pie viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Bet nāks dienas, kad brūtgāns tiem būs atņemts, tanīs dienās tad tie gavēs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Un Viņš sacīja uz tiem arī līdzību: “Neviens neliek ielāpu no jaunām drēbēm uz vecām; citādi viņš tik saplēsīs tās jaunās, un tas ielāps no tām jaunām nederēs uz tām vecām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Un neviens nelej jaunu vīnu vecos ādas traukos; citādi tas jaunais vīns tos traukus pārplēsīs un izgāzīsies, un tie trauki ies bojā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Bet jaunu vīnu būs liet jaunos traukos, tad abi kopā paliek veseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Un nevienam, kas to veco dzēris, tūdaļ neiegribās tā jaunā, jo tas saka: tas vecais ir labāks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Un notikās vienā svētdienā Viņam caur labību ejot, ka Viņa mācekļi vārpas plūca un ēda, ar rokām tās izberzdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Bet kādi no farizejiem uz tiem sacīja: “Kam jūs dariet, ko svētdienās darīt nav brīv?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Un Jēzus atbildēja un uz tiem sacīja: “Vai jūs neesat lasījuši, ko Dāvids ir darījis, kad tas bija izsalcis līdz ar tiem, kas pie viņa bija?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Ka tas ir iegājis Dieva namā un tās Dievam noliktās maizes ņēmis un ēdis un devis arī tiem, kas pie viņa bija, kādas ēst nevienam nav brīv kā vien priesteriem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Un Viņš uz tiem sacīja: “Tas Cilvēka Dēls ir kungs arī par svētdienu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Bet atkal citā svētdienā Viņam baznīcā ejot un mācot notikās, ka tur bija cilvēks, kam labā roka bija nokaltusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Bet tie rakstu mācītāji un farizeji uz Viņu glūnēja, vai Viņš svētdienā nedziedinās, ka atrastu vainas pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Bet tas Viņu domas nomanīja un sacīja uz to cilvēku, kam tā nokaltusi roka bija: “Celies un stājies šeit vidū!” Un tas cēlās un nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Tad Jēzus uz tiem sacīja: “Es jums ko vaicāšu: vai ir brīv svētdienā labu darīt, vai ļaunu darīt, dzīvību glābt vai maitāt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Un tos visapkārt uzlūkojis, Viņš uz to cilvēku sacīja: “Izstiep savu roku!” Un tas tā darīja; un viņa roka tam atkal tapa vesela, itin kā tā otra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Un tie tapa trakuma pilni un sarunājās savā starpā, ko Jēzum darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Bet notikās tanīs dienās, ka Viņš izgāja uz to kalnu Dievu lūgt; un Viņš palika cauru nakti Dieva lūgšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Un kad gaisma ausa, tad Viņš sasauca Savus mācekļus un izredzēja no tiem divpadsmit, kurus Viņš arī nosauca par apustuļiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Sīmani, ko Viņš arī nosauca Pēteri, un Andreju, viņa brāli, Jēkabu un Jāni, Filipu un Bērtuli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mateju un Tomu, Jēkabu, Alfeja dēlu, un Sīmani, kas ir nosaukts Zelotes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Jūdu, Jēkaba dēlu, un Jūdasu Iskariotu, kas palika par nodevēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Un ar tiem zemē nokāpis Viņš stāvēja klajā vietā, un Viņa mācekļu draudze un liels pulks ļaužu no visas Jūdu zemes un Jeruzālemes un no Tirus un Sidonas jūrmalas bija nākuši, Viņu dzirdēt un tapt dziedināti no savām sērgām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Arī tie, kas tapa mocīti no nešķīstiem gariem, - un tie tapa darīti veseli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Un visi tie ļaudis meklēja Viņu aizskart, jo spēks izgāja no Viņa un Viņš visus dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Un Savas acis uz Saviem mācekļiem pacēlis, Viņš sacīja: “Svētīgi esat jūs nabagi, jo jums pieder Dieva valstība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Svētīgi esat, kas tagad izsalkuši, jo jūs tapsiet paēdināti. Svētīgi esat, kas tagad raudāt, jo jūs smiesities.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Svētīgi esat, kad cilvēki jūs ienīd, un kad tie jūs izslēgs un lamās un jūsu vārdu kā ļaunu atmetīs Tā Cilvēka Dēla dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Priecājaties tanī dienā un dejiet, jo redzi jūsu alga ir liela debesīs; jo tāpat viņu tēvi darījuši tiem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Bet ak vai jums, bagātiem, jo jums jau sava alga!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ak vai jums, kas esat piebarojušies, jo jūs izsalksiet! Ak vai jums, kas tagad smejaties, jo jūs noskumsities un raudāsiet!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Ak vai jums, kad visi cilvēki labu par jums runā, jo tāpat viņu tēvi darījuši tiem viltīgiem praviešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Bet Es saku jums, kas to dzirdiet: mīlējiet savus ienaidniekus; dariet labu tiem, kas jūs ienīd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Svētījiet tos, kas jūs nolād; lūdziet par tiem, kas jūs apkaitina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Tam, kas tev vaigā sit vienā pusē, tam sniedz arī otru; un tam, kas tavu mēteli ņem, tam arī neliedz svārkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Bet dod ikkatram, kas tevi lūdz; un neatprasi no tā, kas ņem, kas tev pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Un itin kā gribat, lai citi ļaudis jums dara, tāpat dariet arī jūs viņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Un kad mīlējāt tos, kas jūs mīl, kāda pateicība jums nākas? Jo grēcinieki arīdzan mīl tos, kas viņus mīl.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Un kad labu dariet tiem, kas jums labu dara, kāda pateicība jums nākas? Jo grēcinieki to dara tāpat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Un kad aizdodat tiem, no kā cerējat atdabūt, kāda pateicība jums nākas? Jo arī grēcinieki grēciniekiem aizdod, lai to pašu atdabū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Bet mīlējiet savus ienaidniekus un dariet labu un aizdodiet, nekā atkal par to negaidīdami, un tad jūsu alga būs liela, un jūs būsiet Tā Visuaugstākā bērni; jo Viņš ir laipnīgs pret nepateicīgiem un ļauniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Tāpēc esiet žēlīgi, kā arī jūsu Tēvs ir žēlīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Netiesājiet, tad jūs netapsiet tiesāti; nepazudinājiet, tad jūs netapsiet pazudināti; piedodiet, tad jums taps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dodiet, tad jums taps dots: pilns, saspaidīts, sakratīts un pār pārim ejams mērs jums taps iedots jūsu klēpī; jo ar to mēru, ar ko jūs mērojiet, jums taps atmērots.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Viņš tiem arī sacīja vienu līdzību: “Vai akls aklam ceļu var rādīt? Vai tie abi nekritīs bedrē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Māceklis nav augstāks pār savu mācītāju: kad māceklis ir kā viņa mācītājs, tad viņš ir pilnīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Bet ko tu redzi skabargu sava brāļa acī, bet baļķi savā paša acī tu nenomani?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Jeb, kā tu vari sacīt uz savu brāli: laid brāli, es to skabargu no tavas acs gribu izvilkt, un to baļķi savā paša acī tu neredzi? Tu liekuli, velc papriekš to baļķi no savas acs, un tad pielūko, ka tu to skabargu no sava brāļa acs vari izvilkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Jo tas nav labs koks, kas nes nelāga augļus, nedz nelāga koks, kas nes labus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Ikkatrs koks top pazīts pie saviem augļiem. Jo no ērkšķiem nevar lasīt vīģes, nedz vīnogas no dadžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Labs cilvēks no savas labas sirds mantas izdod labu, un ļauns cilvēks no savas ļaunas sirds mantas izdod ļaunu. Jo no sirds pilnības mute runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Bet ko jūs Mani saucat: Kungs, Dievs! un nedarāt, ko Es saku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Ikviens, kas pie Manis nāk un Manus vārdus dzird un dara, - Es jums rādīšu, kam viņš līdzināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Tas ir līdzināms cilvēkam, kas ēku taisīdams dziļi raka un pamatu lika uz klints. Kad nu plūdi gadījās, tad tā straume lauzās uz to ēku, bet viņu nespēja kustināt, jo tā bija uzlikta uz klints.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Bet kas dzird un nedara, tas ir līdzināms cilvēkam, kas ēku uztaisīja uz zemes bez pamata; un tā straume lauzās un tā ēka tūdaļ sagruva, un šīs ēkas gāšanās bija liela.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Kad nu Viņš tiem ļaudīm dzirdot visus Savus vārdus bija pabeidzis, tad Viņš iegāja Kapernaūmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Bet viena virsnieka kalps, ko tas turēja mīļu, gulēja slims uz miršanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Bet kad tas par Jēzu dzirdēja, tad tas nosūtīja pie Viņa Jūdu vecajus, un Viņu lūdza, lai nāktu, viņa kalpam palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Un pie Jēzus nogājuši, tie Viņu mīļi lūdza sacīdami: “Viņš ir vērts, ka Tu viņu paklausi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Jo viņš mīļo mūsu tautu un mums ir uztaisījis šo baznīcu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Un Jēzus gāja tiem līdz; bet kad Viņš vairs nebija tālu no tā nama, tad tas virsnieks draugus pie Viņa sūtīja, Tam sacīdams: “Kungs, nepūlējies, jo es neesmu cienīgs, ka Tu nāci apakš mana jumta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Tāpēc arī pats sevi neesmu turējis cienīgu pie Tevis nākt; bet saki tik vienu vārdu, tad mans kalps taps vesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Jo arī es esmu cilvēks, apakš valdīšanas stāvēdams, un apakš manis ir karavīri, un es saku šim: ej, tad viņš iet; un otram: nāc, tad viņš nāk; un savam kalpam: dari to, tad viņš dara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Bet Jēzus to dzirdējis, par viņu brīnījās un atgriezdamies sacīja uz tiem ļaudīm, kas Viņam gāja pakaļ: “Es jums saku: tādu ticību ne pat iekš Israēla neesmu atradis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Un tie, kas bija sūtīti, atgriezušies uz māju atrada to vājo kalpu veselu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Un pēc tam notikās, ka Viņš gāja uz vienu pilsētu ar vārdu Naīne, un daudz no Viņa mācekļiem gāja līdz un daudz ļaužu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Bet kad Viņš tuvu pie pilsētas vārtiem bija nācis, lūk, tad iznesa vienu mironi, kas bija savas mātes vienīgais dēls, un tā bija atraitne, un liels pulks pilsētnieku tai gāja līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Un to redzējis Tas Kungs par to iežēlojās un uz to sacīja: “Neraudi!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Un piegājis aizskāra zārku, un tie nesēji apstājās, un Viņš sacīja: “Jaunekli, Es tev saku, celies augšām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Un tas mironis cēlās sēdus un iesāka runāt, un Viņš to atdeva viņa mātei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Un bailība uzgāja visiem, un tie teica Dievu sacīdami: “Liels pravietis mūsu starpā ir cēlies, un Dievs Savus ļaudis uzlūkojis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Un šī slava no Viņa izpaudās pa visu Jūdu zemi un visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Un Jānim viņa mācekļi pasludināja par visām šīm lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Un Jānis ataicināja divus no saviem mācekļiem un tos sūtīja pie Jēzus sacīdams: “Vai Tu esi Tas, kam būs nākt, jeb vai mums būs citu gaidīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Bet tie vīri pie Viņa nogājuši sacīja: “Jānis, tas Kristītājs, mūs pie Tevis sūtījis sacīdams: vai Tu esi Tas, kam būs nākt, jeb vai mums būs citu gaidīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Bet tanī pašā stundā Viņš daudz darīja veselus no sērgām un sāpēm un ļauniem gariem, un daudz akliem Viņš dāvināja gaismu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Un Jēzus atbildēja un uz tiem sacīja: “Ejat un atsakāt Jānim, ko esat redzējuši un dzirdējuši, ka akli redz, tizli iet, spitālīgi top šķīsti, kurli dzird, miroņi top uzmodināti, nabagiem prieka vārds top sludināts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Un svētīgs ir, kas pie Manis neapgrēcinājās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Un Jāņa vēstnešiem aizejot, Viņš iesāka runāt uz tiem ļaudīm par Jāni: “Ko esat izgājuši tuksnesī skatīties? Vai niedri, ko vējš šauba?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Jeb ko esat izgājuši redzēt? Vai cilvēku, mīkstās drēbēs apģērbtu? Redzi, tie, kas dārgās drānās un kārībā dzīvo, ir ķēniņu namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Jeb ko esat izgājuši redzēt? Vai pravieti? Tiešām, Es jums saku, tas arī augstāks nekā pravietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Šis ir, par ko rakstīts: redzi, Es sūtu Savu eņģeli Tavā priekšā, kas Tavu ceļu sataisīs Tavā priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Jo Es jums saku: no visiem, kas dzimuši no sievām, neviens pravietis nav lielāks pār Jāni, to Kristītāju; bet tas mazākais Dieva valstībā ir lielāks pār viņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Un visi ļaudis, kas Viņu dzirdēja, un tie muitnieki apliecināja, ka Dievs taisns, likdamies kristīties ar Jāņa kristību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Bet tie farizeji un bauslības mācītāji Dieva padomu par sev pašiem ir iznīcinājuši, nelikdamies no viņa kristīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Bet Tas Kungs sacīja: “Kam šās cilts ļaudis līdzināšu, un kam tie ir līdzinājami?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Tie ir līdzinājami bērniem, kas sēž uz tirgus, un viens otram uzsauc un saka: mēs jums esam stabulējuši, un jūs neesat dejojuši; mēs jums dziedājuši raudu dziesmas, un jūs neesat raudājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Jo Jānis tas Kristītājs, ir nācis, nedz maizi ēzdams nedz vīnu dzerdams, un jūs sakāt: viņam ir velns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Tas Cilvēka Dēls ir nācis, ēd un dzer, un jūs sakāt: redzi, šis cilvēks ir rijējs un vīna dzērājs, muitnieku un grēcinieku draugs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Un gudrība top taisnota no visiem saviem bērniem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Bet kāds no farizejiem Viņu lūdza, ka Viņš pie tā ēstu, un Viņš tā farizeja namā iegājis apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Un redzi, tanī pilsētā viena sieva, kas bija grēciniece, dzirdējusi, ka Viņš tā farizeja namā pie galda sēžot, atnesa akmens trauciņu ar dārgām zālēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'Un stāvēja aiz Viņa pie Viņa kājām, raudāja un iesāka slapināt Viņa kājas ar savām asarām, un ar saviem galvas matiem nožāvēja un skūpstīja Viņa kājas un tās svaidīja ar tām zālēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Bet tas farizejs, kas Viņu bija aicinājis, to redzēdams sacīja pats pie sevis: “Kad Šis būtu pravietis, tad Viņš zinātu, kas šī tāda sieva, kas Viņu aizskar, jo tā ir grēciniece.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Un Jēzus atbildēdams uz to sacīja: “Sīmani, Man tev kas jāsaka;” viņš atbildēja: “Mācītāj, saki.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Jēzus sacīja: “Vienam naudas aizdevējam bija divi parādnieki; viens tam bija parādā piecsimt grašus, un otrs piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Kad nu tie nespēja atdot, tad viņš abiem diviem atlaida. Kurš tad no tiem, saki jel, to vairāk mīlēs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Bet Sīmanis atbildēdams sacīja: “Man šķiet tas, kam viņš vairāk atlaidis.” Bet Viņš uz to sacīja: “Tu pareizi esi spriedis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Un griezies pie tās sievas Viņš uz Sīmani sacīja: “Vai tu šo sievu redzi? Es esmu nācis tavā namā, tu Man ūdeni neesi devis priekš Manām kājām, bet šī ar savām asarām Manas kājas slapinājusi un ar saviem galvas matiem nožāvējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu Mani neesi skūpstījis, bet šī, kamēr tā ir iekšā nākusi, nav mitējusies Manas kājas skūpstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Ar eļļu tu neesi svaidījis Manu galvu, bet šī ar zālēm ir svaidījusi Manas kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Tādēļ Es tev saku: viņas grēki, kuru bija daudz, ir piedoti, jo tā daudz ir mīlējusi; bet kam maz top piedots, tas mīl maz.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Un Viņš uz to sacīja: “Tev tavi grēki piedoti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Un tie, kas līdz pie galda sēdēja, iesāka pie sev pašiem sacīt: “Kas Tas tāds, kas arī grēkus piedod?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Bet Viņš uz to sievu sacīja: “Tava ticība tev palīdzējusi. Ej ar mieru.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Un pēc tam notikās, ka Viņš staigāja pa pilsētām un miestiem, mācīdams un sludinādams par Dieva valstību, un tie divpadsmit bija pie Viņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Un kādas sievas, kas bija dziedinātas no ļauniem gariem un vājībām, Marija, saucama Madaļa, no kuras septiņi velni bija izgājuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Un Joanna, Hērodus nama uzrauga, Kūzas, sieva, un Zuzanna un daudz citas sievas, kas no sava padoma Viņam kalpoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Bet kad daudz ļaudis bija sanākuši un no visām pilsētām pie Viņa gāja, tad Viņš sacīja caur līdzību:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '“Sējējs izgāja, savu sēklu sēt; un sējot cita krita ceļmalā un tapa samīta, un tie putni apakš debess to apēda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Un cita krita uz akmeni, un uzdīgusi tā sakalta, tāpēc ka tai nebija slapjuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Un cita krita starp ērkšķiem, un tie ērkšķi uzauga līdz un to apmāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Un cita krita uz labu zemi, tā uzdīga un nesa simtkārtīgus augļus.” To sacījis Viņš sauca: “Kam ausis dzirdēt, tas lai dzird.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Bet Viņa mācekļi Viņam vaicāja, kas šī līdzība esot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Bet Viņš sacīja: “Jums ir dots zināt Dieva valstības noslēpumus, bet tiem citiem caur līdzību, ka tie redzēdami neredz un dzirdēdami nesaprot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Bet šī ir tā līdzība: tā sēkla ir Dieva vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Bet kas ceļmalā, ir tie, kas to dzird; pēc velns nāk un ņem to vārdu no viņu sirdīm, lai netic un netop svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Bet kas uz akmens, ir tie: kad tie to vārdu dzird, tad tie to uzņem ar prieku, bet tiem nav saknes; mazu brīdi tie tic un kārdināšanas laikā tie atkāpjās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Bet kas starp ērkšķiem krita, ir tie, kas to dzird, bet tomēr noiet un dodas uz zūdīšanos un bagātību un pasaules kārību, un noslāpst un nenes nekādus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Bet kas labā zemē, ir tie, kas to vārdu dzird un to patur labā un godīgā sirdī, augļus nesdami iekš paciešanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Un sveci iededzinājis, neviens to neapklāj ar trauku nedz to liek apakš galda, bet to liek uz lukturi, lai tie, kas nāk iekšā, to gaišumu redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Jo nekas nav paslēpts, kas netaps redzams, nedz apslēpts, kas netaps zināms un nenāks gaismā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Tāpēc pielūkojiet, kā jūs dzirdat! Jo kam ir, tam taps dots, un kam nav, no tā arī tas taps atņemts, ko tura par savu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Bet Viņa māte un brāļi atnāca pie Viņa, un nevarēja Viņam klāt tikt to ļaužu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Un Viņam ziņu deva un sacīja: “Tava māte un Tavi brāļi stāv ārā un grib Tevi redzēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Bet Viņš atbildēdams uz tiem sacīja: “Mana māte un Mani brāļi ir šie, kas Dieva vārdu dzird un dara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Un notikās kādā dienā, ka Viņš ar Saviem mācekļiem kāpa laivā, un uz tiem sacīja: “Ejam pāri uz otru ezera malu,” un tie stūma no malas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Un kad tie gāja ar laivu, tad Viņš aizmiga; un viesulis cēlās ezerā, un tie tapa apklāti ar viļņiem un bija lielās bēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Un pie Viņa piegājuši, tie Viņu modināja sacīdami: “Kungs, Dievs, mēs grimstam!” Bet Viņš pacēlās un apdraudēja vēju un ūdens viļņus. Un tie nostājās un palika it rāmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Bet Viņš uz tiem sacīja: “Kur ir jūsu ticība?” Bet tie bīdamies brīnījās savā starpā sacīdami: “Kas Tas tāds, ka Viņš arī vējiem un ūdeņiem pavēl, un tie Viņam paklausa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Un tie cēlās pāri uz to Gadariešu tiesu, kas ir Galilejai pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Un Viņam pie malas izejot viens vīrs no tās pilsētas sastapa, kas jau ilgi bija velnu apsēsts, un neapvilka drēbes, un nestāvēja mājā, bet kapos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Šis, Jēzu redzēdams, brēca un krita zemē Viņa priekšā un sacīja ar stipru balsi: “Kas man ar Tevi, Jēzu, Tu Dieva Tā Visuaugstākā Dēls? Es Tevi lūdzu, nemoki mani!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Jo Viņš tam nešķīstam garam pavēlēja, atstāties no tā cilvēka, jo tas viņu jau ilgu laiku bija plosījis, un viņš ar ķēdēm un saitēm tapa saistīts un tapa apsargāts, bet tās saites saraustījis, viņš no velna tapa dzīts uz tuksnesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Un Jēzus tam jautāja sacīdams: “Kā tev vārds?” Un viņš sacīja: “Leģions,” jo daudz velni iekš tā bija iegājuši');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Un tie Viņam lūdza, lai tiem nepavēlētu bezdibenī nokāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Bet tur bija liels cūku pulks ganos uz kalna, un tie Viņu lūdza, ka Viņš tiem atļautu ieiet tais cūkās. Un Viņš tiem atļāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Un tie velni no tā cilvēka atstājušies iegāja tais cūkās, un tas pulks no kraujas nogāzās ezerā un noslīka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Bet tie gani redzējuši, kas notika, aizbēga, un nogājuši to pasludināja pilsētā un ciemos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Bet tie izgāja, to notikumu redzēt, un nāca pie Jēzus un atrada to cilvēku, no kā tie velni bija atstājušies, apģērbtu un prātīgu pie Jēzus kājām sēžam, un tie bijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Un arī tie, kas to bija redzējuši, pasludināja viņiem, kā tas velna apsēstais tapis pestīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Un viss tas ļaužu pulks no tās Gadariešu tiesas Viņu lūdza, ka no tiem aizietu, jo tie no lielām bailēm bija pārņemti, un Viņš kāpa laivā un griezās atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Bet tas vīrs, no kā tie velni bija atstājušies, Viņu ļoti lūdza, ka pie Viņa varētu palikt, bet Jēzus to atlaida sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '“Griezies atpakaļ uz savām mājām un izteic, kādas lielas lietas Dievs tev ir darījis;” un tas nogāja pa visu to pilsētu, pasludinādams, kādas lielas lietas Jēzus tam bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Un notikās, kad Jēzus atpakaļ nāca, tad tie ļaudis Viņu uzņēma, jo tur bija daudz, kas uz Viņu gaidīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Un redzi, tur nāca viens vīrs, Jaīrus vārdā, un tas bija baznīcas priekšnieks, un tas Jēzum pie kājām krizdams lūdza, ka nāktu viņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Jo tam bija viena vienīga meita ap divpadsmit gadiem, un tā bija nomirusi. Un Viņam ejot tie ļaudis spiedās virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Un viena sieva, pie divpadsmit gadiem asins sērgā sirgusi, kas visu savu padomu bija izdevusi ārstiem un nevarējusi tapt dziedināta no neviena,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Piegājusi no aizmugures aizskāra Viņa drēbes vīli, un tūdaļ viņas asins skriešana nostājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Un Jēzus sacīja: “Kas Mani aizskāris?” Un kad visi liedzās, tad Pēteris un tie, kas pie Viņa bija, sacīja: “Kungs, tie ļaudis Tev laužas virsū un Tevi spiež, un Tu saki: kas Mani aizskāris?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Bet Jēzus sacīja: “Mani kāds ir aizskāris; jo Es esmu manījis, ka spēks no Manis izgājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Bet tā sieva, redzēdama, ka to nevarēja slēpt, nāca drebēdama un metās ceļos priekš Viņa un Viņam izteica priekš visiem ļaudīm, kādas vainas dēļ tā Viņu bija aizskārusi, un ka tā tūdaļ bija palikusi vesela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Bet Viņš uz to sacīja: “Turi drošu prātu, Mana meita, tava ticība tev palīdzējusi; ej ar mieru!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Un Viņam vēl tā runājot, viens no tā baznīcas priekšnieka saimes nāca, uz šo sacīdams: “Tava meita ir nomirusi, neapgrūtini to Mācītāju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Bet Jēzus to dzirdējis tam atbildēja sacīdams: “Nebīsties, tici tikai, un viņa taps glābta.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Un namā iegājis, Viņš nevienu nelaida iekšā, kā vien Pēteri un Jēkabu un Jāni un tās meitas tēvu un māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Bet visi raudāja un to nožēloja; bet Viņš sacīja: “Neraudiet, tā nav mirusi, bet tikai guļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Un tie Viņu apsmēja, zinādami, ka tā bija nomirusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Bet visus izdzinis, Viņš satvēra viņas roku, sauca un sacīja: “Meitiņa, celies augšām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Un viņas dvēsele atgriezās, un tā tūdaļ uzcēlās; un Viņš pavēlēja, tai dot ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Un viņas vecāki iztrūcinājās. Bet Viņš tiem pavēlēja, nevienam to nesacīt, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Un Savus divpadsmit mācekļus sasaucis, Viņš tiem deva varu un spēku pār visiem velniem, un sērgas dziedināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Un Viņš tos sūtīja, Dieva valstību sludināt un vājus darīt veselus:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Un Viņš uz tiem sacīja: “Neņemat neko līdz uz ceļu, nedz zizli, nedz kulīti, nedz maizi, nedz naudu, un lai nevienam no jums nav divi svārki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Un kurā mājā jūs ieiesiet, tur paliekat, un no turienes ejat tālāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Un kas jūs neuzņems, - tad iziedami no tās pilsētas nokratāt arī pīšļus no savām kājām par liecību pret tiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Bet tie izgājuši pārstaigāja visus tos miestus visur to priecas vārdu sludinādami un dziedinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Bet Hērodus, kas to ceturto zemes tiesu valdīja, dzirdēja visas lietas, kas caur Viņu notika, un nezināja, ko domāt, tāpēc ka citi runāja, ka Jānis no miroņiem esot augšām cēlies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Bet citi, ka Elija esot parādījies; bet citi, ka viens no tiem pirmajiem praviešiem esot augšām cēlies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Un Hērodus sacīja: “Es Jānim galvu esmu nocirtis, bet kas šis tāds, par ko es tādas lietas dzirdu?” Un tas meklēja, Viņu redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Un tie apustuļi atgriezušies Viņam teica, kādas lietas tie bija darījuši; un Viņš tos ņēma līdz un aizgāja savrup uz kādu tukšu vietu pie vienas pilsētas, vārdā Betsaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Bet tie ļaudis, to nomanīdami, gāja Viņam pakaļ, un Viņš tos pieņēmis runāja ar tiem par Dieva valstību; un kam dziedināšanas vajadzēja, tos Viņš darīja veselus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Bet vakars jau metās, un tie divpadsmit piegājuši uz Viņu sacīja: “Atlaidi tos ļaudis, ka tie nogājuši tais apkārtējos miestos un ciemos mājas vietu dabū un maizi atrod; jo mēs šeit esam tukšā vietā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Bet Viņš uz tiem sacīja: “Dodiet jūs viņiem ēst.” Bet tie sacīja: “Mums vairāk nav kā piecas maizes un divas zivis vien, ja mēs citur nogājuši barību nepirksim priekš visiem šiem ļaudīm.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Jo tur bija kādi piectūkstoš vīri. Bet Viņš uz Saviem mācekļiem sacīja: “Liekat viņiem apsēsties pa kārtām, pa piecdesmitiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Un tie tā darīja un lika visiem apsēsties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Bet, tās piecas maizes un tās divas zivis ņēmis, Viņš skatījās uz debesi, tās svētīja un pārlauza, un deva tiem mācekļiem, lai tiem ļaudīm ceļ priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Un tie visi ēda un paēda; un salasīja tās druskas, kas tiem bija atlikušas, divpadsmit kurvjus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Un notikās, kad Viņš viens pats Dievu lūdza, tad tie mācekļi pie Viņa piegāja; un Viņš tiem vaicāja sacīdams: “Ko tie ļaudis saka, Mani esam?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Bet tie atbildēdami sacīja: “Jānis, tas Kristītājs; un citi, ka viens no tiem veciem praviešiem esot augšām cēlies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Bet Viņš uz tiem sacīja: “Bet jūs, ko jūs sakāt, Mani esam?” Bet Pēteris atbildēdams sacīja: “Tu esi Tas Dieva Kristus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Bet viņš tiem stipri aizliedza, lai nevienam nesaka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Sacīdams: “Tam Cilvēka Dēlam būs daudz ciest un tapt atmestam no tiem vecajiem un augstiem priesteriem un rakstu mācītājiem, un tapt nokautam un trešā dienā uzmodinātam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Un Viņš uz visiem sacīja: “Ja kas grib nākt Man pakaļ, tas lai aizliedz sevi pašu un uzņem savu krustu ikdienas un staigā Man pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Jo kas savu dzīvību grib izglābt, tam tā zudīs; un kam sava dzīvība Manis dēļ zūd, tas to izglābs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Jo ko tas cilvēkam līdz, ka viņš samanto visu pasauli, bet pats pazūd jeb iet bojā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Jo kas Manis un Manu vārdu dēļ kaunas, tā paša dēļ Tas Cilvēka Dēls kaunēsies, kad Viņš nāks Savā un Sava Tēva un to svēto eņģeļu godībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Bet Es jums tiešām saku: ir kādi no tiem, kas še stāv, kas nāvi nebaudīs, kamēr Dieva valstību redzēs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Un notikās kādas astoņas dienas pēc šiem vārdiem, tad Viņš ņēma līdz Pēteri un Jāni un Jēkabu, un uzkāpa uz to kalnu, Dievu lūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Un Viņam lūdzot, Viņa vaigs palika citāds un Viņa drēbes spoži baltas kā zibens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Un redzi, divi vīri ar Viņu runāja, tie bija Mozus un Elija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Tie parādījās iekš godības un runāja par Viņa galu, ko Viņam bija piepildīt Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Bet Pēteris un viņa biedri bija miega pilni, bet uzmodušies tie redzēja Viņa spožumu un tos divus vīrus pie Viņa stāvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Un notikās, kad tie no Viņa šķīrās, tad Pēteris sacīja uz Jēzu: “Kungs, šeit mums labi, lai taisām trīs būdas, vienu Tev, vienu Mozum un vienu Elijam;” - un viņš nezināja, ko viņš runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Un tam šo runājot, padebesis nāca un viņus apēnoja, bet tie bijās, kad tas padebesis viņus apklāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Un balss nāca no tā padebeša sacīdama: “Šis ir Mans mīļais Dēls, To jums būs klausīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Un kad tā balss atskanēja, tad Jēzus atradās viens pats. Un tie cieta klusu un nesacīja nevienam tanīs dienās nekā no tā, ko bija redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Un notikās otrā dienā, kad tie no kalna nāca zemē, tad Viņu sastapa daudz ļaužu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Un redzi, viens vīrs no tiem ļaudīm brēca sacīdams: “Mācītāj, es Tev lūdzu, skaties uz manu dēlu, jo tas ir mans vienpiedzimušais,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Un redzi, viens gars to grābj, un tas piepeši brēc, un viņš to plosa līdz putām un tikai grūti no tā šķirās, to novārdzinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Un es Taviem mācekļiem esmu lūdzis, ka tie to izdzītu, bet tie nespēja.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Un Jēzus atbildēdams sacīja: “Ak tu neticīgā un netiklā cilts, cik ilgi Es pie jums būšu un jūs panesīšu? Atved savu dēlu šurp.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Un tam atnākot velns to plosīja un raustīja: bet Jēzus to nešķīsto garu apdraudēja un darīja to bērnu veselu un atdeva viņa tēvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Bet visi iztrūcinājās par to augsto Dieva godību. Un kad visi brīnījās par visu, ko Jēzus bija darījis, tad Viņš sacīja uz Saviem mācekļiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Liekat jūs šos vārdus savās ausīs, jo Tas Cilvēka Dēls taps nodots cilvēku rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Bet tie šo vārdu nesaprata, un tas tiem bija apslēpts, ka tie to nesamanīja, un tie bijās Viņu vaicāt par šo vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Un viņu starpā tādas domas cēlās, kurš no viņiem esot tas lielākais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Bet Jēzus viņu sirds domas redzēdams, ņēma vienu bērnu un to nostādīja Savā priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'Un uz tiem sacīja: “Ja kas šo bērnu uzņem Manā Vārdā, tas Mani uzņem; un ja kas Mani uzņem, tas uzņem To, kas Mani sūtījis. Jo kurš jūsu starpā ir tas mazākais, tas būs liels.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Bet Jānis atbildēdams sacīja: “Kungs, mēs vienu redzējām Tavā Vārdā velnus izdzenam, un tam esam lieguši, jo tas neiet ar mums Tev pakaļ. “');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Un Jēzus uz to sacīja: “Neliedziet, jo kas nav pret mums, tas ir ar mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Un notikās, kad Viņa paaugstināšanas laiks bija klāt, tad Viņš Savu vaigu grieza, iet uz Jeruzālemi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Un Viņš nosūtīja vēstnešus Savā priekšā un tie gāja un nāca uz vienu Samarijas miestu, sataisīt mājas vietu priekš Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Un tie Viņu neuzņēma, jo Viņš bija apņēmies, iet uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Un Viņa mācekļi, Jēkabs un Jānis, to redzēdami sacīja: “Kungs, vai Tu gribi, tad mēs sacīsim, lai uguns krīt no debess un tos sadedzina, itin kā arī Elija darījis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Bet Viņš atgriezdamies tos aprāja un sacīja: “Vai jūs nezināt, kādam garam jūs piederat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Jo Tas Cilvēka Dēls nav nācis, cilvēku dvēseles nomaitāt, bet pestīt.” Un tie gāja uz citu miestu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Un notikās tiem noejot, viens uz ceļa uz viņu sacīja: “Kungs, es Tev iešu pakaļ, kurp Tu iesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Un Jēzus uz to sacīja: “Lapsām ir alas un putniem apakš debess ligzdas, bet Tam Cilvēka Dēlam nav, kur Tas Savu galvu lai noliek.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Un Viņš uz citu sacīja: “Nāc Man pakaļ!” Bet tas sacīja: “Kungs, atļauj man papriekš noiet, savu tēvu aprakt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Bet Jēzus uz to sacīja: “Lai miroņi aprok savus miroņus, bet tu ej un pasludini Dieva valstību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Un cits sacīja: “Kungs, es Tev iešu pakaļ, bet atļauj man papriekš no tiem atvadīties, kas ir manā namā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Bet Jēzus uz to sacīja: “Neviens neder Dieva valstībā, kas savu roku pieliek pie arkla un skatās atpakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Un pēc tam Tas Kungs vēl septiņdesmit citus iecēla un tos sūtīja pa diviem savā priekšā uz ikkatru pilsētu un vietu, kur Viņš gribēja iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Un Viņš uz tiem sacīja: “Pļaujamā ir daudz, bet strādnieku maz; tāpēc lūdziet tā pļaujamā Kungu, lai Tas strādniekus sūta Savā pļaujamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Ejiet! Lūk, Es jūs sūtu kā jērus vilku starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Nenesiet maku, nedz kulīti, nedz kurpes, un nesveicinājiet nevienu uz ceļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Un kurā namā jūs ieiesiet, sakāt papriekš: miers lai ir ar šo namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Un ja tur būs kāds miera bērns, tad jūsu miers uz tā dusēs; bet ja ne, tad tas pie jums atgriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Tanī pašā namā paliekat, un ēdat un dzerat, kas tiem pie rokas, jo strādniekam sava alga pienākas; neejat no viena nama uz otru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Un kurā pilsētā jūs ieiesiet, un tie jūs uzņem, tur ēdat, ko jums ceļ priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Un dariet tur veselus tos vājos un sakāt uz tiem: Dieva valstība tuvu pie jums ir nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Bet kurā pilsētā jūs ieejat, un tie jūs neuzņem, tad izgājuši uz viņu ielām sakiet:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Arī tos pīšļus, kas mums no šīs pilsētas pielīp, mēs nokratām uz jums; tomēr to ziniet, ka Dieva valstība tuvu ir nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Bet Es jums saku, ka Sodomas ļaudīm viņā dienā vieglāki būs, nekā tādai pilsētai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Vai tev, Horacin! vai tev, Betsaida! jo kad iekš Tirus un Sidonas tie brīnumi būtu notikuši, kas pie jums notikuši, tad tie jau sen no grēkiem būtu atgriezušies maisos un pelnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Tomēr Tirum un Sidonai vieglāki būs tiesas dienā nekā jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Un tu, Kapernaūma, kas līdz debesīm esi paaugstināta, tu līdz ellei tapsi nogrūsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kas jūs dzird, tas Mani dzird, un kas jūs nicina, tas Mani nicina; bet kas Mani nicina, tas nicina To, kas Mani sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Un tie septiņdesmit pārnāca ar prieku sacīdami: “Kungs, arī tie velni mums padodas Tavā Vārdā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Un Viņš uz tiem sacīja: “Es sātanu redzēju itin kā zibeni no debess krītam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Redzi, Es jums esmu devis spēku, staigāt uz čūskām un skorpioniem, un pār visu ienaidnieka varu, un nekas jums nekaitēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Tomēr nepriecājaties par to, ka tie gari jums padodas, bet priecājaties, kā jūsu vārdi ir rakstīti debesīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Un tanī stundā Jēzus priecājās garā un sacīja: “Es Tev pateicos, Tēvs, debess un zemes Kungs, ka Tu šās lietas esi paslēpis gudriem un prātīgiem, un no tām ziņu devis bērniņiem. Tiešām, Tēvs, jo tā tas ir bijis Tavs labais prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Visas lietas Man ir nodotas no Mana Tēva. Un neviens neatzīst, kas ir Tas Dēls, kā vien Tas Tēvs, un kas ir Tas Tēvs, kā vien Tas Dēls, un kam Tas Dēls to grib darīt zināmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Un Viņš griezies pie tiem mācekļiem sacīja sevišķi: “Svētīgas ir tās acis, kas redz, ko jūs redzat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Jo Es jums saku: daudz pravieši un ķēniņi gribēja redzēt, ko jūs redzat, un nav redzējuši, un dzirdēt, ko jūs dzirdat, un nav dzirdējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Un redzi, viens rakstu mācītājs cēlās, Viņu kārdinādams, un sacīja: “Mācītāj, ko man būs darīt, ka es iemantoju mūžīgu dzīvošanu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Bet Viņš uz to sacīja: “Kā stāv bauslībā rakstīts? Kā tu lasi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Un tas atbildēja un sacīja: “Tev būs Dievu, savu Kungu, mīlēt no visas savas sirds un no visas savas dvēseles un no visa sava spēka un no visa sava prāta, un savu tuvāku kā sevi pašu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Tad Viņš tam sacīja: “Tu pareizi esi atbildējis; ej, dari to, tad tu dzīvosi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Bet tas gribēdams pats taisnoties sacīja uz Jēzu: “Kas tad ir mans tuvākais?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Tad Jēzus atbildēja un sacīja: “Viens cilvēks gāja no Jeruzālemes uz Jēriku un krita slepkavu rokās, tie tam noplēsa drēbes, un to sasituši, aizgāja un to pameta pusmirušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Bet no nejauši viens priesteris staigāja pa to pašu ceļu; kad tas to redzēja, tad viņš aizgāja garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Tāpat arī viens levits; tas pie tās vietas nācis to redzēja un aizgāja garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Bet viens Samarietis, savu ceļu iedams, nāca pie viņa, un viņu redzot sirds tam iežēlojās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Un piegājis sasēja viņa vātis, tanīs eļļu un vīnu ieliedams; pēc viņš to cēla uz savu lopu un to noveda mājas vietā un to apkopa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Un otrā dienā aiziedams viņš izvilka divus sudraba grašus un deva tos tam saimniekam un uz to sacīja: “Kopi šo, un ja tu vēl ko izdosi, atpakaļ nākdams es tev to atdošu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kurš no šiem trim tev šķiet tas tuvākais bijis tam, kas bija kritis slepkavu rokās?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Bet tas sacīja: “Tas, kas žēlastību pie viņa darījis.” Tad Jēzus uz to sacīja: “Tad ej nu un dari tu tāpat arīdzan.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Un notikās, Viņam Savu ceļu staigājot, Viņš nāca vienā pilsētiņā; un viena sieva, Marta vārdā, Viņu uzņēma savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Un tai bija māsa, vārdā Marija; tā nosēdās pie Jēzus kājām un klausījās Viņa vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Bet Marta daudz nodarbojās kalpodama un piegāja sacīdama: “Kungs, vai Tev nekas par to, ka mana māsa mani ir atstājusi vienu pašu kalpojam? Saki jel viņai, lai tā man palīdz”.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Bet Jēzus atbildēja un uz to sacīja: “Marta, Marta, tu gan daudz rūpējies un pūlējies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Bet vienas lietas vajag; Marija to labo daļu sev ir izredzējusi, tā no tās netaps atņemta.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Un notikās, kad Viņš kādā vietā Dievu lūdza, un kad bija pabeidzis, tad viens no Viņa mācekļiem uz Viņu sacīja: “Kungs, māci mums Dievu lūgt, itin kā arī Jānis savus mācekļus ir mācījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Un Viņš uz tiem sacīja: “Kad jūs lūdzat, sakāt: Mūsu Tēvs debesīs! Svētīts lai top Tavs Vārds; lai nāk Tava valstība; Tavs prāts lai notiek, kā debesīs, tā arī virs zemes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Mūsu dienišķu maizi dod mums ikdienas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Un piedod mums mūsu grēkus, jo mēs paši arīdzan piedodam ikvienam, kas mums parādā; un neieved mūs kārdināšanā; bet atpestī mūs no tā ļauna.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Un Viņš uz tiem sacīja: “Kuram jūsu starpā ir draugs, kad viņš pie tā noietu nakts vidū un uz to sacītu: “Lūdzams, aizdod man trīs maizes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Jo draugs pie manis no ceļa ir atnācis, un man nav, ko tam celt priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Un tas iekšā atbildēdams sacītu: “Neapgrūtini mani, durvis jau aizslēgtas, un mani bērni pie manis jau ir gultā. Es nevaru celties un tev dot;” -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Es jums saku: “Jebšu viņš arī neceltos un tam nedotu tāpēc, ka tas ir viņa draugs, tad tomēr viņa nekaunīgās uzstāšanās dēļ tas celsies un viņam dos, cik tam vajag.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Un Es jums saku: “Lūdziet, tad jums taps dots, meklējiet, tad jūs atradīsiet, klaudzinājiet, tad jums taps atvērts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Jo ikviens lūgdams dabū un meklēdams atrod, un kas klaudzina, tam top atvērts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Ja kādam tēvam jūsu starpā dēls lūdz maizi, vai tas viņam dos akmeni? Jeb arī ja zivi, vai tas viņam zivs vietā dos čūsku?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Jeb arī ja lūdz olu, vai tas viņam dos skarpiju?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Ja tad jūs, kas esat ļauni, mākat dot saviem bērniem labas dāvanas, cik vairāk jūsu Debesu Tēvs dos To Svēto Garu tiem, kas Viņu lūdzās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Un Viņš izdzina vienu velnu, un tas bija mēms. Bet notikās, kad velns bija izbēdzis, tad tas mēmais runāja, un tie ļaudis brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Bet citi no tiem sacīja: “Šis velnus izdzen caur Belcebulu, velnu virsnieku.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Bet citi kārdinādami meklēja no Viņa zīmi no debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Bet Viņš, viņu domas nomanījis, uz tiem sacīja: “Ikviena valsts, kas savā starpā top ienaidā, tā aiziet postā, un nams grūst uz namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Ja tad arī sātans savā starpā ienaidā, kā viņa valsts var pastāvēt? Jo jūs sakāt, ka Es velnus izdzenu caur Belcebulu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Bet ja Es velnus izdzenu caur Belcebulu, caur ko tad jūsu bērni tos izdzen? Tāpēc tie būs jūsu tiesātāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Bet ja Es velnus izdzenu caur Dieva pirkstu, tad jau Dieva valstība pie jums atnākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Kad tas stiprais apbruņojies savu pili apsargā, tad viņa lietas paliek mierā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Bet kad viens stiprāks viņam uziet, kas viņu uzvar, tad tas paņem viņa bruņas, uz ko viņš paļāvās, un izdala viņa laupījumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kas nav ar Mani, tas ir pret Mani; un kas ar Mani nesakrāj, tas izkaisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Kad tas nešķīstais gars izgājis no cilvēka, tad viņš pārstaigā sausas vietas un meklē dusēt. Bet to neatradis viņš saka: es gribu atpakaļ griezties uz savu namu, no kurienes esmu izgājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Un kad viņš nāk, tad viņš to atrod ar slotām mēztu un izpušķotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Tad viņš noiet un ņem pie sevis septiņus citus garus, kas niknāki nekā viņš pats; un tur iekšā nākuši tie tur dzīvo, un top pēc ar to cilvēku niknāki, nekā bijis papriekš.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Un notikās, kad Viņš tā runāja, tad viena sieva tanī pulkā savu balsi pacēla un uz Viņu sacīja: “Svētīgas ir tās miesas, kas Tevi nesušas, un tās krūtis, ko Tu esi zīdis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Bet Viņš sacīja: “Tiešām, svētīgi tie, kas Dieva vārdu dzird un pasargā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Un kad tie ļaudis sapulcinājās, tad Viņš iesāka sacīt: “Šī cilts ir nikna, tā meklē zīmi, un zīme tai netaps dota kā vien pravieša Jonas zīme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Jo itin kā Jona bija par zīmi Niniviešiem, tāpat arī Tas Cilvēka Dēls būs šai ciltij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Tā ķēniņiene no dienvidu puses celsies soda dienā pret šīs cilts ļaudīm un tos pazudinās; jo tā no pasaules gala ir nākusi, Salamana gudrību dzirdēt, un redzi, šeit ir vairāk nekā Salamans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Ninivieši celsies soda dienā pret šo cilti un to pazudinās; jo tie ir atgriezušies no grēkiem uz Jonas sludināšanu: un redzi, šeit ir vairāk nekā Jona.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Bet sveci iededzinājis, neviens to neliek kaktā, nedz apakš pūra, bet uz lukturi, lai tie, kas nāk iekšā, to gaišumu redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Miesas svece ir acs; tāpēc ja tava acs ir laba, tad arī visa tava miesa ir gaiša; bet ja tā ir kaitīga, tad arī tava miesa ir tumša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Tāpēc pieraugi, ka tas gaišums, kas ir iekš tevis, nav tumsība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Ja tad nu visa tava miesa ir gaiša, tā ka tai nemaz nav tumsības, tad tā būs visai gaiša, itin kā kad svece tevi apgaismo ar savu spīdumu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Bet kamēr Viņš vēl tā runāja, viens farizejs Viņu lūdza, ka Viņš azaidu pie tā ēstu. Un Viņš iegājis apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Un tas farizejs brīnījās redzēdams, ka Viņš nemazgājās priekš azaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Bet Tas Kungs uz to sacīja: “Tagad jūs farizeji šķīstat biķera un bļodas ārapusi, bet jūsu iekšpuse ir piepildīta ar laupījumu un blēdību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Jūs bezprātīgie, vai tas, kas āra pusi darījis, nav arī darījis iekšpusi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Bet dodiet to, kas tur iekšā, nabagiem, un redzi, viss jums ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Bet ak vai, jums, farizejiem! jo jūs dodat desmito tiesu no mētrām, dillēm un visādiem dārza augiem, un pārkāpiet tiesu un Dieva mīlestību. Šo vajadzēja darīt, un to nevajadzēja pamest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Ak vai, jums, farizejiem! jums tīk jo augstos krēslos baznīcās sēdēt un tirgos tapt sveicinātiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Ak vai, jums, rakstu mācītājiem un farizejiem! jūs liekuļi! jo jūs esat tā kā paslēpti kapi, un tie cilvēki, kas virsū staigā, to nezina.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Bet viens no tiem bauslības mācītājiem atbildēdams uz Viņu sacīja: “Mācītāj, Tu to runādams arī mūs nievā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Bet Viņš sacīja: “Ak vai, arī jums, rakstu mācītājiem! Jo jūs cilvēkus apkraujat ar grūti nesamām nastām, un paši tās nastas neaizskarat ne ar vienu pirkstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Ak vai, jums, jo jūs uztaisiet praviešu kapus, un jūsu tēvi tos ir nokāvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Tad nu jūs dodat liecību, ka jums jūsu tēvu darbi patīk; tie gan viņus ir nokāvuši, bet jūs uztaisiet viņu kapus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Tāpēc arī Dieva gudrība saka: Es sūtīšu pie tiem praviešus un apustuļus, un tie citus no tiem nokaus un citus izdzīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Ka pie šās cilts visu praviešu asinis taptu meklētas, kas ir izlietas no pasaules iesākuma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'No Abela asinīm līdz Zaharijas asinīm, kas ir nokauts starp altāri un Dieva namu. Patiesi, Es jums saku: tās taps meklētas pie šās tautas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Ak vai, jums, rakstu mācītājiem, jo jūs to atzīšanas atslēgu esat noņēmuši. Jūs paši neieejat, un tos, kas gribēja ieiet, jūs esat atturējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Un kad Viņš tā uz tiem sacīja, tad tie rakstu mācītāji un farizeji iesāka gauži viņam lauzties virsū un par daudz lietām Viņam tos vārdus izvilt no mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Un tie uz Viņu glūnēja un meklēja kaut ko saķert no Viņa mutes, ka Viņu varētu apsūdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Un kad daudz tūkstošu ļaužu sapulcējās, tā ka tie viens otru gandrīz samina, tad Jēzus iesāka sacīt uz Saviem mācekļiem: “Visvairāk sargājaties no farizeju rauga, kas ir liekulība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Bet nekas nav apslēpts, kas nenāks gaismā, nedz slepens, kas nekļūs zināms.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Tāpēc, ko jūs esat sacījuši tumsībā, to dzirdēs gaismā, un ko esat ausī runājuši kambaros, to sludinās uz jumtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Bet Es jums, Saviem draugiem, saku: nebīstaties no tiem, kas miesu nokauj un pēc vairāk neko nespēj darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Bet Es jums rādīšu, no kā jums jābīstas: bīstaties no tā, kam ir vara nokaut un tad iemest ellē: tiešām, Es jums saku, no tā bīstaties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Vai piecus zvirbuļus nepērk par divām artavām? Un neviens no tiem nav aizmirsts pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Bet arī visi jūsu galvas mati ir skaitīti, tāpēc nebīstaties; jūs esat labāki nekā daudz zvirbuļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Bet Es jums saku: ikvienu, kas Mani apliecinās cilvēku priekšā, to arī Tas Cilvēka Dēls apliecinās Dieva eņģeļu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Un kas Mani aizliegs cilvēku priekšā, tas taps aizliegts Dieva eņģeļu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Un ikvienam, kas ko runās pret To Cilvēka Dēlu, taps piedots; bet kas To Svēto Garu zaimojis, tam netaps piedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Bet kad jūs vedīs baznīcas tiesu un valdnieku un vareno priekšā, tad nebēdājaties, kā un ar ko aizbildināsities, jeb ko runāsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Jo Tas Svētais Gars jums mācīs tanī pašā stundā, ko būs runāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Bet viens no tiem ļaudīm uz Viņu sacīja: “Mācītāj, saki manam brālim, lai tas tēva mantu ar mani dala.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Bet Viņš uz to sacīja: “Cilvēks, kas Mani pār jums iecēlis par tiesnesi vai izšķīrēju?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Bet Viņš uz tiem sacīja: “Pieraugāt un sargājaties no mantas kārības! Jo neviens nedzīvo no tā, ka viņam pārlieku daudz mantas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Un Viņš tiem stāstīja līdzību sacīdams: “Kāda bagāta cilvēka tīrums bija nesis papilnam augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Un tas domāja savā prātā sacīdams: ko darīšu? Jo man nav, kur savus augļus likt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Un tas sacīja: to darīšu: es savus šķūņus gribu noplēst un lielākus uztaisīt un tur likšu visus savus augļus un savu labību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Un sacīšu uz savu dvēseli: dvēsele, tev ir liels mantas krājums uz daudz gadiem: dusi, ēd un dzer un līksmojies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Bet Dievs uz to sacīja: tu bezprātīgais! šinī naktī tavu dvēseli no tevis atprasīs, un kam tas būs ko tu esi sakrājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Tāds pat ir, kas sev mantas krāj un nav bagāts iekš Dieva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Un Viņš uz Saviem mācekļiem sacīja: “Tāpēc Es jums saku: nezūdaties savas dzīvības pēc, ko jūs ēdīsiet, nedz miesas pēc, ar ko jūs ģērbsities.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Dzīvība ir labāka nekā barība, un miesa labāka nekā drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Ņemiet vērā kraukļus, kas nedz sēj, nedz pļauj, kam ne klēts, nedz šķūņa; un jūsu Dievs tos uztur. Cik daudz labāki jūs esat nekā putni!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Un kurš jūsu starpā savam mūžam spēj pielikt vienu olekti, lai gan tādēļ raizējās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Ja nu jūs ne to vismazāko neiespējat, ko tad raizējaties par tām citām lietām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Ņemiet vērā puķes, kā tās aug: ne tās strādā, ne tas vērpj; bet Es jums saku, ka pat Salamans visa savā godībā tā nav bijis apģērbts, kā viena no tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Ja tad Dievs zāli laukā tā apģērbj, kas šodien stāv un rītu top iemesta krāsnī, cik vairāk jūs? Ak jūs mazticīgie!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Tā arīdzan nebēdājaties, ko ēdīsiet un ko dzersiet, nedz šaubāties šurpu turpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Jo visas šīs lietas pagāni pasaulē meklē, bet jūsu Tēvs zina, ka jums šo lietu vajag.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Bet meklējiet Dieva valstību, un tad jums visas šīs lietas taps piemestas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Nebīsties, tu mazais ganāmais pulciņ, jo jūsu Tēva žēlīgais prāts ir, jums dot to valstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Pārdodiet, kas jums ir, un dodiet nabagiem, gādājiet sev makus, kas nenovecojas, neiznīcīgu mantu debesīs, kur zaģļi netiek klāt, un kodes nesamaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Jo kur jūsu manta, tur arī būs jūsu sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Lai jūsu gurni ir apjozti un tās sveces spīdošas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Un esiet līdzīgi cilvēkiem, kas savu kungu gaida, kad tas celsies no kāzām, ka tie viņam nākot un klaudzinājot tūdaļ var atdarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Svētīgi tie kalpi, ko Tas Kungs pārnācis atradīs nomodā. Patiesi, Es jums saku, ka viņš apjozīsies, un tiem liks apsēsties un apkārt iedams tiem kalpos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Un kad viņš nāks nakts vidū, vai pirmajos gaiļos un tā atradīs, svētīgi tie kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Bet to ziniet, kad tas nama kungs zinātu, kurā stundā zaglis nāk, tad viņš būtu nomodā un neļautu savā namā ielauzties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Un jūs arīdzan esat gatavi: jo tanī stundā, kurā nedomājat, Tas Cilvēka Dēls nāks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Un Pēteris uz To sacīja: “Kungs, vai Tu šo līdzību saki uz mums, vai arī uz visiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Bet Tas Kungs sacīja: “Kas gan ir tas uzticīgais un gudrais nama turētājs, ko kungs ieceļ pār savu saimi, tiem piederīgo barību dot īstenā laikā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Svētīgs tas kalps, ko kungs, pārnācis atradīs tā darām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Es jums tiešām saku, ka viņš to iecels pār visu savu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Bet ja tas kalps sacīs savā prātā: mans kungs kavējās nākt; un iesāks kalpus un kalpones sist, un ēst un dzert un piedzerties:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Tad šī kalpa kungs nāks tanī dienā, kurā tas viņu negaida, un tanī stundā, ko tas nezina, un to šķels pušu un tam savu algu dos ar tiem neticīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Bet tas kalps, kas sava kunga prātu zinādams nav sataisījies, nedz darījis pēc viņa prāta, tas dabūs daudz sitienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Bet kas nezinādams darījis, ar ko viņš sitienus pelnījis, dabūs maz sitienu; bet no ikviena, kam daudz ir dots, daudz meklēs, un kam daudz ir uzticēts, no tā vairāk prasīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Es esmu nācis, uguni mest uz zemi, un kā Es gribētu, ka (tā) jau degtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Bet Man būs tapt kristītam ar vienu kristību, un kā Man ir bail, kamēr tā būs pabeigta!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Vai jums šķiet, ka esmu nācis mieru dot virs zemes? Es jums saku: nebūt ne, bet ienaidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Jo no šī laika vienā namā pieci savā starpā būs ienaidā, trīs pret diviem un divi pret trim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Tēvs cels ienaidu pret dēlu, un dēls pret tēvu, māte pret meitu, un meita pret māti, un vīra māte pret savu vedeklu, un vedekla pret savu vīra māti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Un viņš arī uz tiem ļaudīm sacīja: “Kad redzat kādu padebesi uzkāpjam no vakara puses, tad jūs tūdaļ sakāt: lietus nāk; un tā notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Un kad vējš pūš no dienvidiem, tad jūs sakāt: būs karsts laiks; un tā notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Jūs liekuļi, debess un zemes ģīmi jūs varat noprast, bet kā šo laiku neizprotat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Un kāpēc jūs arī no sevis pašiem nespriežat, kas taisnība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Jo kad tu ar savu pretinieku ej pie valdnieka, tad lūko uz ceļa ar viņu salīgt, ka tas tevi neved pie soģa, un soģis tevi nenodod bendēm, un bende tevi nemet cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Es tev saku, tu neiziesi no turienes, kamēr nenomaksāsi pēdējo artavu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Bet tanī pašā brīdī tur kādi gadījās, kas viņam pasludināja par tiem Galilejiem, kuru asinis Pilatus bija sajaucis ar viņu upuriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Un Jēzus atbildēja un uz tiem sacīja: “Vai jums šķiet, ka šie Galileji ir bijuši grēcinieki pār visiem Galilejiem, tāpēc ka tie to cietuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Es jums saku: nebūt ne; bet ja jūs neatgriezīsities no grēkiem, tad arī jūs visi tāpat tapsiet nomaitāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Jeb vai jums šķiet, ka tie astoņpadsmit, uz kuriem tas tornis iekš Siloāmas krita un ko tas nosita, vainīgi ir bijuši pār visiem cilvēkiem, kas Jeruzālemē dzīvo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Es jums saku: nebūt ne; bet ja jūs no grēkiem neatgriezīsities, tad jūs visi tāpat tapsiet nomaitāti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Un Viņš sacīja šo līdzību: “Vienam cilvēkam vīģes koks bija stādīts savā vīna kalnā, un tas nāca, augļus no tā meklēt un neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Tad viņš uz to vīna dārznieku sacīja: redzi, es jau nāku trīs gadus, augļus meklēt uz šī vīģes koka un neatrodu; nocērt to, kam tas velti stāv tai zemē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Bet tas atbildēja un uz viņu sacīja: kungs, lai tas vēl stāv šo gadu, tiekams to aproku un apmēsloju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Vai jel tas augļus nenesīs; ja ne, tad tu pēc to vari nocirst.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Un Viņš mācīja vienā no tām baznīcām svētdienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Un redzi, vienai sievai bija neveselības gars astoņpadsmit gadus, un tā bija savilkta un nemaz nevarēja taisni atliekties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Bet Jēzus, viņu redzēdams, to pieaicināja un uz to sacīja: “Sieva, topi vaļā no savas neveselības!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Un uzlika tai rokas, un tā tūdaļ pacēlās taisna un slavēja Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Bet tas baznīcas priekšnieks apskaities, tāpēc ka Jēzus svētdienā bija dziedinājis, atbildēja un uz tiem ļaudīm sacīja: “Sešas dienas ir, kur jāstrādā, tad nu tanīs nāciet un liekaties dziedināties, un ne svētdienā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Tad Tas Kungs tam atbildēja un sacīja: “Tu liekuli, vai ikviens jūsu starpā savu vērsi vai ēzeli neatraisa no siles svētdienā un to nenoved dzirdīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Bet šī Ābrahāma meita, ko sātans, redzi, astoņpadsmit gadus ir saistījis, vai tā nebija svētdienā atraisāma no šīs saites?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Un Viņam to sakot visi Viņa pretinieki kaunējās un visi ļaudis priecājās par visiem šiem brīnuma darbiem, kas caur Viņu notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Un Viņš sacīja: “Kam Dieva valstība līdzinājās, un kam to līdzināšu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Tā ir līdzinājama sinepju graudiņam, ko cilvēks ņēmis iemeta savā dārzā; un tas uzauga un palika par lielu koku, un tie putni apakš debess taisīja ligzdas viņa zaros.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Un atkal Viņš sacīja: “Kam Dieva valstību līdzināšu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Tā ir līdzinājama raugam, ko sieva ņēmusi iejauca iekš trīs mēru miltu, tiekams viss sarūga.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Un Viņš tās pilsētas un pilsētiņas pārstaigāja mācīdams un iedams uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Bet viens uz Viņu sacīja: “Kungs! Vai to ir maz, kas nāks Debesu valstībā?” Bet Viņš uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '“Cīnieties ieiet caur tiem šauriem vārtiem, jo, Es jums saku, daudz meklēs ieiet un nevarēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Kad tas nama Kungs celsies un durvis aizslēgs, un jūs iesāksiet ārā stāvēt un pie durvīm klaudzināt sacīdami: Kungs, Dievs, atdari mums; tad Viņš atbildēdams jums sacīs: Es jūs nepazīstu, no kurienes jūs esat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tad jūs iesāksiet sacīt: mēs Tavā priekšā esam ēduši un dzēruši, un Tu esi mācījis mūsu ielās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Un Viņš sacīs: Es jums saku, Es jūs nepazīstu, no kurienes jūs esat; atkāpjaties no Manis, visi jūs ļauna darītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tur būs raudāšana un zobu trīcēšana, kad jūs redzēsiet Ābrahāmu un Īzaku un Jēkabu un visus praviešus Dieva valstībā, bet sevi pašus izmestus ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Un tad nāks no rīta un vakara puses, no ziemeļa un dienvidu puses, un sēdēs Dieva valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Un redzi, ir pēdējie, kas būs pirmie, un ir pirmie, kas būs pēdējie.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Tanī dienā kādi farizeji atnāca un uz Viņu sacīja: “Izej un ej projām no šejienes; jo Hērodus grib Tevi nokaut.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Un Viņš uz tiem sacīja: “Ejat un sakāt šai lapsai: redzi, Es velnus izdzenu un slimus daru veselus šodien un rīt, bet trešajā dienā Es būšu galā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Tomēr Man vēl šodien un rīt un parīt jāstaigā; jo tas neklājās, ka pravietis citur galu dabū, kā Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzāleme, Jeruzāleme, tu, kas nokauj praviešus un ar akmeņiem nomētā tos, kas pie tevis sūtīti. - cik reiz Es esmu gribējis tavus bērnus sakrāt, itin kā vista savus cālīšus apakš spārniem; un jūs neesat gribējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Redzi, jūsu nams jums top atstāts postā. Bet patiesi, Es jums saku, ka jūs Mani neredzēsiet, līdz kamēr tas laiks nāk, kad jūs sacīsiet: slavēts, kas nāk Tā Kunga Vārdā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Un gadījās, ka Jēzus viena farizeju virsnieka namā nāca svētdienā uz mielastu, un tie uz Viņu glūnēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Un lūk, viens ūdens sērdzīgs cilvēks tur bija Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Un Jēzus iesāka runāt uz tiem bauslības mācītājiem un farizejiem un sacīja: “Vai brīv svētdienā dziedināt?” Bet tie cieta klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Un, to ņēmis, Viņš to dziedināja un sūtīja projām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Pēc Viņš atbildēja un uz tiem sacīja: “Kurš ir jūsu starpā, kam savs ēzelis vai vērsis iekrīt akā, un viņš to tūdaļ neizvilks svētā dienā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Un tie tam nenieka uz to nevarēja atbildēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Viņš arī tiem viesiem teica kādu līdzību, nomanīdams, ka tie izraudzījās sēdēt jo augstā vietā, un uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '“Kad tu no kāda topi kāzās lūgts, tad nesēdies augstākajā vietā, ka negadās jo cienīgs nekā tu, kas arī no viņa lūgts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Un ka tas, kas tevi un viņu lūdzis, nenāk uz tevi sacīt: dod šim vietas, un tad tev ar kaunu būs jāsēž zemākajā vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Bet kad tu esi lūgts, tad ej un sēdies jo zemā vietā, ka tas, kas tevi lūdzis, nāk uz tevi sacīt: draugs, virzies augšām: tad tev būs gods priekš tiem, kas līdz ar tevi sēž pie galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Jo kas pats paaugstinājās, taps pazemots, un kas pats pazemojās, taps paaugstināts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Un Viņš sacīja arī uz to, kas Viņu bija aicinājis: “Kad tu azaidu vai vakariņu taisi, tad nelūdzi savus draugus, nedz savus brāļus, nedz savus radus, nedz bagātus kaimiņus, ka tie tevi atkal nelūdz, un tu savu atmaksu dabū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Bet kad tu viesības dari, aicini nabagus, kropļus, tizlus, aklus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Tad tu būsi svētīgs, jo tiem nav, ko tev atmaksāt; un tev taps atdots, kad tie taisnie augšām celsies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Bet viens no tiem, kas pie galda sēdēja, to dzirdējis, uz Viņu sacīja: “Svētīgs, kas maizi ēd Dieva valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Bet Viņš uz to sacīja: “Viens cilvēks lielu vakariņu sataisīja un lūdza daudzus pie tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Un viņš savu kalpu sūtīja ap to vakariņa stundu, tiem aicinātiem sacīt: nāciet, jo visas lietas sataisītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Bet tie visi cits pēc cita iesāka aizbildināties. Pirmais uz to sacīja: es tīrumu esmu pircis, un man jānoiet, to apraudzīt; lūdzos, aizbildini mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Un otrs sacīja: es pieci jūgus vēršu esmu pircis un noeju, tos apraudzīt; lūdzos, aizbildini mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Un cits sacīja: es sievu esmu apņēmis, tāpēc nevaru nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Un tas kalps nāca un savam kungam to atsacīja; tad tas nama kungs tapa dusmīgs un sacīja uz savu kalpu: ej steigšus uz gatvēm un pilsētas ielām, un ieved tos nabagus un kropļus un tizlus un aklus šeit iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Un tas kalps sacīja: kungs, tas ir padarīts, ko tu esi pavēlējis, bet vēl ir rūmes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Un Tas Kungs sacīja uz to kalpu: Izej uz lielceļiem un pie sētmalām un spiedi tos nākt iekšā, lai mans nams top pilns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Jo es jums saku, ka neviens no tiem vīriem, kas bija aicināti, manu vakariņu nebaudīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Bet daudz ļaužu gāja Viņam līdz, un Viņš atgriezdamies uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '“Ja kas nāk pie Manis un neienīst savu tēvu un māti un sievu un bērnus un brāļus un māsas un arī turklāt savu paša dzīvību, tas nevar būt Mans māceklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Un kas savu krustu nenes un nestaigā Man pakaļ tas nevar būt Mans māceklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Jo kurš ir jūsu starpā, kas torni grib uztaisīt un papriekš neapsēžās un nepārdomā, cik tas maksā, vai viņam būs padoma līdz pat galam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Lai, kad pamatu licis un nespēj pabeigt, visi, kas to redz, nesāk viņu apsmiet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Sacīdami: Šis cilvēks ir iesācis celt, bet nav spējis pabeigt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Jeb kurš ķēniņš, karā iedams kauties ar citu ķēniņu, papriekš neapsēžās un neapdomājās, vai būs spēcīgs, iet pretī ar desmit tūkstošiem tam, kas viņam uziet ar divdesmit tūkstošiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Bet kad nav, tad viņš sūta vēsti, kamēr vēl ir tālu, un lūdz mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Tad nu tāpat ikkatrs no jums, kas visai savai rocībai neatsaka, tas nevar būt Mans māceklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Sāls ir laba, bet ja sāls paliek nelietīga, ar ko tad to darīs derīgu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Tā neder ne zemei, ne sūdos. To izmet ārā. Kam ausis dzirdēt, tas lai dzird.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Un visādi muitnieki un grēcinieki steidzās pie Viņa, gribēdami Viņu dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Un tie farizeji un rakstu mācītāji kurnēja un sacīja: “Šis uzņem grēciniekus un ēd ar tiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Bet Viņš tiem šo līdzību stāstīja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '“Ja kādam cilvēkam jūsu starpā ir simts avis, un tam viena no tām pazūd, vai tas neatstāj tās deviņdesmit deviņas tuksnesī un nenoiet pēc tās pazudušās, tiekams to atrod?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Un to atradis, viņš līksmodamies to ceļ uz saviem pleciem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Un mājās pārnācis viņš sasauc savus draugus un kaimiņus, uz tiem sacīdams: priecājaties ar mani, es savu avi esmu atradis, kas bija pazudusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Es jums saku: tā arī debesīs būs vairāk līksmības par vienu pašu grēcinieku, kas atgriežas no grēkiem, nekā par deviņdesmit deviņiem taisniem, kam atgriešanās no grēkiem nevajag.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Jeb ja kādai sievai ir desmit graši un viens tai nozūd, vai tā neiededzina sveci un nemēž namu, rūpīgi meklēdama, kamēr to atrod?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Un to atradusi, tā sasauc savas draudzenes un kaimiņienes sacīdama: priecājaties ar mani, jo es savu grasi atkal esmu atradusi, kas man bija nozudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Tā, Es jums saku, būs arī līksmība pie Dieva eņģeļiem par vienu pašu grēcinieku, kas atgriežas no grēkiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Un Viņš sacīja: “Vienam cilvēkam bija divi dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Un tas jaunākais no tiem sacīja uz tēvu: tēvs, dod man manu tiesu no tās mantas, kas man nākas; un viņš tiem to mantu dalīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Un pēc necik ilga laika tas jaunākais, visu saņēmis kopā, aizgāja uz tālu zemi un tur savu mantu izšķērdēja, negodīgi dzīvodams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Kad nu tas visu savu mantu bija iztērējis, tad liels bads nāca tanī zemē, un tam iesāka pietrūkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Tad viņš gāja un pieķērās turpat pie viena namnieka; tas to sūtīja uz savu tīrumu, cūkas ganīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Un viņš gribēja savu vēderu pildīt ar sēnalām, ko cūkas ēda, bet neviens ne tās tam nedeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Tad viņš pie atzīšanas nācis sacīja: cik algādžu manam tēvam, kam maizes papilnam, un es mirstu badu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Es celšos un iešu pie sava tēva un sacīšu uz viņu: tēvs, es esmu grēkojis pret debesīm un pret tevi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Un vairs neesmu cienīgs, ka mani sauc par tavu dēlu; dari mani par vienu no taviem algādžiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Un viņš cēlās un gāja pie sava tēva. Bet kad tas vēl bija tālu, tad viņa tēvs to redzēja, un viņš iežēlojās par to un skrēja un krita tam ap kaklu un to skūpstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Un dēls sacīja uz viņu: tēvs, es esmu grēkojis pret debesi un pret tevi un neesmu vairs cienīgs, ka mani sauc par tavu dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Bet tēvs sacīja uz saviem kalpiem: atnesiet tās viskrāšņākās drēbes un ģērbiet to un dodiet tam gredzenu rokā un kurpes kājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Un atnesat treknu teļu un nokaujiet to, lai ēdam un līksmojamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Jo šis mans dēls bija nomiris un atkal tapis dzīvs; viņš bija pazudis un ir atrasts. Un tie sāka līksmoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Bet vecākais dēls bija uz lauka, un pārnākdams tuvu pie mājām viņš dzirdēja to dziedāšanu un diešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Un vienu no tiem kalpiem pasaucis, viņš jautāja, kas tas esot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Un šis sacīja uz viņu: tavs brālis ir pārnācis, un tavs tēvs ir nokāvis treknu teļu, tāpēc ka viņš to veselu atdabūjis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Tad viņš apskaitās un negribēja ieiet. Bet viņa tēvs gāja ārā un to lūdza iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Bet viņš atbildēja un sacīja uz tēvu: redzi, tik daudz gadus es tev kalpoju un nekad vēl neesmu pārkāpis tavu bausli, un tomēr man tu vēl nekad ne kazlēnu neesi devis, ka es būtu līksmojies ar saviem draugiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Bet kad nu šis tavs dēls ir atnācis, kas tavu mantu aprijis ar maukām, tad tu viņam esi nokāvis barotu teļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Un viņš sacīja uz to: dēls, tu pie manis esi vienmēr un viss, kas mans, tas ir arī tavs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Bet tev bija būt līksmam un priecīgam, jo šis tavs brālis bija nomiris un ir atkal tapis dzīvs, viņš bija pazudis un ir atrasts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Un Viņš sacīja arī uz Saviem mācekļiem: “Kādam bagātam vīram bija nama turētājs, un tas viņa priekšā tapa apsūdzēts, ka viņa mantu esot izšķērdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Un to aicinājis, viņš uz to sacīja: kā es to dzirdu par tevi? Atbildi par savu nama turēšanu; jo tu joprojām nevari būt nama valdītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Bet tas nama turētājs runāja pats pie sevis: ko nu darīšu? Mans kungs man atņem nama valdīšanu. Rakt nespēju, diedelēt kaunos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Es zinu, ko darīšu, kad no amata topu nocelts, lai tie mani uzņem savos namos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Un saaicinājis visus sava kunga parādniekus, viņš sacīja uz to pirmo: cik tu manam kungam esi parādā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Un tas sacīja: simts mucu eļļas. Un viņš uz to sacīja: ņem savu grāmatu, sēdies un raksti tūdaļ piecdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Tad viņš uz to otru sacīja: bet tu, cik tu esi parādā? Un tas sacīja: simts mēru kviešu. Un viņš uz to sacīja: ņem savu grāmatu un raksti astoņdesmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Un Tas Kungs uzteica to netaisno nama turētāju, ka tas gudri bija darījis; jo šīs pasaules bērni ir gudrāki savā kārtā nekā tie gaismas bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Un Es jums saku: dariet sev draugus no tās netaisnās mantas, ka tie, kad jums nu pietrūkst, jūs uzņem tais mūžīgos dzīvokļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kas vismazākā lietā ir uzticīgs, tas arīdzan lielākā ir uzticīgs; bet kas vismazākā ir netaisns, tas arī lielākā ir netaisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Ja tad jūs pie netaisnās mantas neesat uzticīgi, kas jums uzticēs patieso?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Un kad jūs iekš svešas lietas neesat uzticīgi, kas jums dos jūsu pašu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Neviens kalps nevar kalpot diviem kungiem; jo tas vienu ienīdēs un otru mīlēs, jeb vienam pieķersies un otru atmetīs. Jūs nevarat kalpot Dievam un mantai.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Bet šo visu arī tie farizeji dzirdēja, kas mantu mīlēja, un tie Viņu apsmēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Un Viņš uz tiem sacīja: “Jūs esat tie, kas paši taisnojās cilvēku priekšā, bet Dievs pazīst jūsu sirdis; jo kas cilvēku starpā ir augsts, tas ir negantība Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Bauslība un pravieši ir līdz Jānim; no tā laika Dieva valstības evaņģēlijs top sludināts, un ikkatrs ar varu laužās tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Vieglāki ir, ka debess un zeme zūd, nekā no bauslības viena rakstu zīmīte zustu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Ikviens, kas no savas sievas šķirās un precē citu, tas pārkāpj laulību, un ikviens, kas vienu no vīra atšķirtu precē, tas pārkāpj laulību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Kāds bagāts vīrs bija, tas ģērbās ar purpuru un dārgu audekli, un dzīvoja ikdienas kārumā un līksmībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Bet arī kāds nabags bija, vārdā Lāzarus, tas gulēja priekš viņa durvīm, pilns ar vātīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Un gribēja paēst no tām druskām, kas krita no tā bagātā galda. Bet tikai suņi nāca un laizīja viņa vātis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Bet gadījās, ka tas nabags nomira un no eņģeļiem tapa aiznests Ābrahāma klēpī, un tas bagātais arīdzan nomira un tapa aprakts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Kad tas nu bija ellē un mokās, tad tas pacēla savas acis un redzēja Ābrahāmu no tālienes un Lāzaru viņa klēpī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Un sauca un sacīja: tēvs Ābrahām, apžēlojies par mani un sūti Lāzaru, lai tas savu pirksta galu iemērc ūdenī un dzisina manu mēli, jo es ciešu lielas mokas šinīs uguns liesmās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Bet Ābrahāms atbildēja: piemini, dēls, ka tu savu labumu esi dabūjis savā dzīvības laikā, un Lāzarus turpretī ļaunumu, bet tagad šis top iepriecināts, bet tu topi mocīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Un turklāt starp jums un mums ir liela starpa, ka tie, kas no šejienes gribētu noiet pie jums, nevar; nedz arī no turienes pārnākt pie mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Un viņš sacīja: tad es tevi lūdzu, tēvs, sūti viņu uz mana tēva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Jo man vēl pieci brāļi; lai viņš tos pamāca, ka tie arīdzan nenāk šinī moku vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Ābrāms uz to sacīja: tiem ir Mozus un pravieši, lai tie tos klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Bet tas sacīja: Nē, tēvs Ābrahām, bet kad viens no mirušiem pie tiem ietu, tad tie atgrieztos no grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Tad viņš uz to sacīja: kad tie neklausa Mozu un praviešus, tad tie arī neticēs, kaut ir kāds no miroņiem augšāmceltos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Un Viņš uz tiem mācekļiem sacīja: “Bez tā tas nebūs, ka apgrēcības nenāk, bet vai tam, caur ko tās nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Tam būtu labāki, ka tam dzirnu akmeni piekārtu pie kakla, un to iemestu jūrā, nekā tas vienu no šiem mazajiem apgrēcinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Sargājaties paši! Bet ja tavs brālis grēko pret tevi, tad pamāci to; un ja tas atgriežas, tad piedod tam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Un ja tas ikdienas septiņ reiz grēko pret tevi un ikdienas septiņ reiz griezīsies pie tevis sacīdams: tas man ir žēl; tad tev būs viņam piedot.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Un tie apustuļi uz To Kungu sacīja: “Vairo mums ticību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Bet Tas Kungs sacīja: “Ja jums ticība būtu kā sinepju graudiņš, tad jūs varētu sacīt uz šo vīģes koku: izraujies ar saknēm un dēsties jūrā; un tas jums paklausītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Un ja kādam jūsu starpā ir kalps, kas viņam ar un gana, vai viņš tam, kad tas no lauka nāk, sacīs: nāc tūdaļ un apsēdies?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Vai viņš tam nesacīs tā: sataisi man, ko es šo vakaru ēdīšu, apjozies un kalpo man, kamēr es ēdu un dzeru, un pēc tam arī tu ēdīsi un dzersi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Vai viņš tam kalpam pateiksies, ka tas ir darījis, kas tam bija pavēlēts? Nedomāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Tā arī jūs, kad jūs visu esat darījuši, kas jums pavēlēts, tad sakāt: mēs esam nelietīgi kalpi, jo kas mums pienācās darīt, to esam darījuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Un notikās, ka iedams uz Jeruzālemi Viņš staigāja vidū caur Samariju un Galileju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Un kad Viņš kādā pilsētiņā nāca, tad Viņam desmit spitālīgi vīri sastapās, tie stāvēja no tālienes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Paceldami savu balsi, un sacīja: “Jēzu, mīļais Kungs, apžēlojies par mums!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Un tos redzējis, Viņš uz tiem sacīja: “Ejat un rādieties tiem priesteriem.” Un notikās, ka tie aizejot tapa šķīsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Bet viens no tiem, redzēdams, ka viņš tapis šķīsts, griezās atpakaļ un teica Dievu ar skaņu balsi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Un krita uz savu vaigu pie Viņa kājām un Viņam pateicās; un tas bija viens Samarietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Un Jēzus atbildēja un sacīja: “Vai desmit nav tapuši šķīsti? Bet kur tad tie deviņi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Vai tad cits neviens nav atradies, kas atpakaļ būtu griezies un Dievam godu devis, kā vien šis svešinieks?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Un Viņš uz to sacīja: “Celies un ej, tava ticība tev ir palīdzējusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Un vaicāts no tiem farizejiem, kad Dieva valstība nāks, Viņš tiem atbildēja un sacīja: “Dieva valstība nenāk ārīgi nomanama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Un arī nesacīs: redzi, še, vai: redzi, tur; jo redzi, Dieva valstība ir iekš jums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Un Viņš sacīja uz tiem mācekļiem: “Nāks dienas, kad jūs vēlēsities vienu no Tā Cilvēka Dēla dienām redzēt, un neredzēsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Un tie uz jums sacīs: redzi, še! Vai redzi, tur! Bet nenoejat, nedz dzenaties tam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Jo itin kā zibens, kas zibinādams spīd no viena debess gala līdz otram debess galam, tā arīdzan būs Tas Cilvēka Dēls Savā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Bet papriekš Viņam būs daudz ciest un tapt atmestam no šīs cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Un itin kā bija Noas dienās, tā arīdzan būs Tā Cilvēka Dēla dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Tie ēda, dzēra, precēja un tapa precēti līdz tai dienai, kur Noā šķirstā iegāja, un grēku plūdi nāca un visus noslīcināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Un tā kā notikās Lata dienās: tie ēda, dzēra, pirka, pārdeva, dēstīja, uztaisīja ēkas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Bet tai dienā, kad Lats izgāja no Sodomas, tad uguns un sērs lija no debess un visus nomaitāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'It tāpat būs tai dienā, kur Tas Cilvēka Dēls parādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Tanī dienā, kas būs uz jumta un viņa rīki namā, tas lai nekāpj zemē, tos paņemt; un tāpat, kas ir uz lauka, lai negriežās atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Pieminiet Lata sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Ja kas meklēs savu dzīvību paturēt, tas to zaudēs, un ja kas to zaudēs, tas to paturēs dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Es jums saku: tanī naktī divi būs vienā gultā, viens taps pieņemts un otrs atstāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Divas kopā mals, - viena taps pieņemta un otra atstāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Divi būs laukā, viens taps pieņemts un otrs atstāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Un tie atbildēja un uz Viņu sacīja: “Kurā vietā, Kungs?” Bet Viņš uz tiem sacīja: “Kur ir maita, tur sakrāsies ērgļi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Un Viņš tiem arī vienu līdzību sacīja, ka pienākas allažiņ Dievu lūgt un nepiekust,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Un sacīja: “Bija soģis kādā pilsētā, tas no Dieva nebijās un no neviena cilvēka nekaunējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Un viena atraitne bija tanī pilsētā; un tā nāca pie viņa sacīdama: izdod man tiesu pret manu pretinieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Un viņš ilgu laiku negribēja. Bet pēc viņš sacīja pie sevis: jebšu es Dievu nebīstos un no neviena cilvēka nekaunos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Tomēr, kad šī atraitne man gauži spiežas virsū, tad es tai gribu tiesu izdot, ka tā bezgala nākdama mani nenomāc.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Un Tas Kungs sacīja: “Klausāties, ko tas netaisnais soģis saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Vai tad Dievs neizdos tiesu Saviem izredzētiem, kas dienām naktīm uz Viņu brēc, lai gan Viņš tiem liek gaidīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Es jums saku: Viņš tiem tiesu izdos īsā laikā. Bet, kad Tas Cilvēka Dēls atnāks, vai Tas gan ticību atradīs virs zemes?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Bet Viņš arī sacīja uz kādiem, kas uz sev pašiem paļāvās, ka esot taisni, un citus nicināja, šo līdzību:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '“Divi cilvēki gāja Dieva namā Dievu lūgt, viens farizejs, otrs muitnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Tas farizejs nostājies lūdza, pats pie sevis šos vārdus sacīdams: es tev pateicos Dievs, ka es neesmu kā citi cilvēki, laupītāji, netaisni, laulības pārkāpēji, vai arī kā šis muitnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Es gavēju divreiz nedēļā un dodu desmito tiesu no visa sava padoma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Bet tas muitnieks no tālienes stāvēdams negribēja nedz savas acis pacelt uz debesīm, bet sita pie savām krūtīm un sacīja: Dievs, esi man grēciniekam žēlīgs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Es jums saku: šis nogāja savā namā taisnots pār to otru; jo kas pats paaugstinājās, tas taps pazemots, un kas pats pazemojās, tas taps paaugstināts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Un tie arī bērniņus atnesa pie Viņa, ka Viņš tos aizskartu, bet to redzēdami tie mācekļi tos aprāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Bet Jēzus tos pieaicināja un sacīja: “Laidiet tos bērniņus pie Manis un neliedziet tiem; jo tādiem Dieva valstība pieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Patiesi, Es jums saku: ja kas Dieva valstību nedabū kā bērniņš, tas nenāks tur iekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Un viens virsnieks Tam jautāja un sacīja: “Labais Mācītāj, ko man būs darīt, lai es iemantoju mūžīgu dzīvošanu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Un Jēzus uz to sacīja: “Ko tu Mani sauci par labu? neviens nav labs kā vien Tas Vienīgais Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu tos baušļus zini: tev nebūs laulību pārkāpt; tev nebūs nokaut; tev nebūs zagt; tev nebūs nepatiesu liecību dot; godā savu tēvu un savu māti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Bet tas sacīja: “Visu to esmu turējis no pašas jaunības.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Bet Jēzus to dzirdēdams uz to sacīja: “Vienas lietas tev vēl trūkst; pārdod visu, kas tev ir un izdali nabagiem; tad tev manta būs debesīs, un nāc un staigā Man pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Bet, šos vārdus dzirdot, tas ļoti noskuma, jo viņš bija ļoti bagāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Un Jēzus redzēdams, ka tas bija noskumis, sacīja: “Cik grūti bagātie ieies Dieva valstībā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Jo vieglāki ir, kamielim iet caur adatas aci, nekā bagātam ieiet Dieva valstībā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Tad tie, kas to dzirdēja, sacīja: “Kas tad var kļūt Dieva valstībā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Bet Viņš sacīja: “Kas cilvēkiem neiespējams, tas Dievam iespējams.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Un Pēteris sacīja: “Redzi, mēs visu esam atstājuši un Tev pakaļ gājuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Un Viņš uz tiem sacīja: “Patiesi, Es jums saku: neviens nav, kas atstājis mājas vai vecākus vai brāļus vai sievu vai bērnus Dieva valstības dēļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Kas to daudzkārtīgi neatdabūs šinī laikā, un nākošā laikā mūžīgu dzīvošanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Un tos divpadsmit pie Sevis ņēmis, Viņš uz tiem sacīja: “Redzi, mēs noejam uz Jeruzālemi, un viss taps piepildīts, ko pravieši rakstījuši par To Cilvēka Dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Jo Viņš taps nodots pagāniem un taps apmēdīts un lamāts un apspļaudīts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Un tie To šaustīs un nokaus, un trešā dienā Viņš atkal augšām celsies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Bet viņi nesaprata no tā nenieka, un šī valoda viņiem bija apslēpta, un nesaprata to, kas bija sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Bet gadījās, Viņam tuvu klāt nākot pie Jērikus, viens akls sēdēja ceļmalā un nabagoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Bet kad tas tos ļaudis dzirdēja garām ejam, tad tas jautāja, kas tur esot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Un viņi tam atbildēja: “Jēzus no Nacaretes iet garām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Tad tas brēca un sacīja: “Jēzu, Dāvida dēls, apžēlojies par mani!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Bet tie, kas priekšā gāja, to apsauca, lai būtu klusu. Bet viņš vēl vairāk brēca: “Tu Dāvida dēls, apžēlojies par mani!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Bet Jēzus apstājās un pavēlēja, to atvest pie Sevis; bet kad tie to pie Viņa bija atveduši, tad Viņš to jautāja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Sacīdams: “Ko tu gribi, lai Es tev daru?” Viņš atbildēja: “Kungs, ka varu redzēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Un Jēzus uz to sacīja: “Esi redzīgs, tava ticība tev palīdzējusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Un tūdaļ viņš tapa redzīgs un Tam staigāja pakaļ, Dievu teikdams. Un visi ļaudis, kas to redzēja, slavēja Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Un Jēzus nonācis gāja caur Jēriku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Un redzi, tur bija viens cilvēks vārdā Zakhejs, un tas bija muitnieku virsnieks, bagāts vīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Tas labprāt gribēja Jēzu redzēt, kāds Viņš esot, un nevarēja to ļaužu dēļ, mazs būdams no auguma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Un tas tecēja papriekš un kāpa uz meža vīģes koku, ka Viņu redzētu; jo šepat Viņam bija jāiet garām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Un tai vietā nonācis Jēzus skatījās uz augšu un to ieraudzījis, Viņš uz to sacīja: “Zakhej, kāp steigšus zemē, jo Man šodien pie tevis mājas vieta jaņem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Un viņš steigšus nokāpa un Jēzu uzņēma ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Un to redzēdami, visi kurnēja un sacīja: “Viņš iegājis, mājot pie grēcinieka.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Bet Zakhejs piegājis sacīja uz To Kungu: “Redzi, Kungs, pusi no savas mantas es došu nabagiem; un ja es kam ko novīlis, to es četrkārtīgi atdošu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Bet Jēzus uz to sacīja: “Šodien šim namam žēlastība notikusi; jo šis arīdzan ir Ābrahāma dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Jo Tas Cilvēka Dēls ir nācis, meklēt un svētu darīt to, kas pazudis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Un kad tie to klausījās, tad Viņš sacīja vēl vienu līdzību, tāpēc ka Viņš tuvu bija pie Jeruzālemes, un tiem šķita, ka Dieva valstība drīz parādīšoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Tāpēc Viņš sacīja: “Viens cilvēks no augstas cilts gāja uz tālu zemi, valstību uzņemt un atkal pārnākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Un aicinājis savus desmit kalpus, viņš tiem deva desmit podus un uz tiem sacīja: pelnaties ar tiem, līdz kamēr es pārnāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Un viņa pilsētas ļaudis to ienīdēja un tam vēstnešus sūtīja pakaļ, sacīdami: mēs negribam, ka šis pār mums valda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Un notikās viņam atpakaļ nākot, kad viņš valstību bija uzņēmis, - tad viņš lika aicināt savā priekšā tos kalpus, kam viņš to naudu bija devis, ka zinātu, ko ikkatrs bija sapelnījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Un tas pirmais atnāca un sacīja: kungs, tavs pods desmit podus ir piepelnījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Un viņš uz to sacīja: labi, tu godīgais kalps, tāpēc ka tu tai mazākā lietā esi bijis uzticīgs, esi valdnieks pār desmit pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Un tas otrais nāca un sacīja: kungs, tavs pods piecus podus ir pelnījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Un viņš arī uz šo sacīja: un tu būsi valdnieks pār piecām pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Un vēl cits nāca sacīdams: kungs, redzi, še tavs pods, ko turēju noliktu sviedru autā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Jo es tevi bijos, tāpēc ka tu esi bargs cilvēks; tu ņēmi, ko neesi licis, un pļauj, ko neesi sējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Bet viņš uz to sacīja: no tavas mutes es tevi tiesāšu, tu blēdīgais kalps: tu esi zinājis, mani esam bargu cilvēku un ņemam, ko neesmu licis, un pļaujam, ko neesmu sējis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Kādēļ tad tu manu sudrabu neesi devis naudas mijējiem? Tad es pārnācis to būtu atprasījis ar augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Un viņš sacīja uz tiem, kas klāt stāvēja: ņemiet viņam to podu nost un dodiet tam, kam ir desmit podi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Un tie uz viņu sacīja: kungs, tam jau ir desmit podi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Es jums saku: ikvienam, kam ir, tam taps dots: un no tā, kam nav, taps arī atņemts, kas tam ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Tomēr šos manus ienaidniekus, kas negribēja, ka es pār tiem valdu, atvediet šurp un nokaujiet tos manā priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Un to sacījis, Viņš aizgāja projām uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Un notikās, kad Viņš tuvu nāca pie Betfagas un Betanijas, pie tā kalna, kas top saukts Eļļas kalns, tad Viņš sūtīja divus no Saviem mācekļiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Un sacīja: “Ejat uz to miestu, kas jūsu priekšā, un tur nākuši jūs atradīsiet kumeļu piesietu, uz kā vēl neviens nav sēdējis, to atraisiet un atvediet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Un ja kas jums vaicās, kādēļ jūs to atraisiet, tad sakāt viņam: Tam Kungam tā vajag.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Un tie izsūtītie nogāja un atrada, kā Viņš tiem bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Un kad tie to kumeļu atraisīja, tad tie, kam tas piederēja, uz tiem sacīja: “Kam jūs to kumeļu atraisiet?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Bet tie sacīja: “Tam Kungam to vajag.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Un tie to atveda pie Jēzus un, savas drēbes tam kumeļam uzlikuši, tie sēdināja Jēzu virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Un Viņam jājot tie savas drēbes paklāja uz ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Un kad Viņš jau tuvu bija nācis, kur sāk kāpt zemē no Eļļas kalna, tad viss mācekļu pulks iesāka Dievu priecīgi teikt ar skaņu balsi par visiem tiem brīnumiem, ko tie bija redzējuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Sacīdami: “Slavēts ir Tas Ķēniņš, kas nāk Tā Kunga Vārdā, miers debesīs un gods augstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Un kādi farizeji no tā pulka sacīja uz Viņu: “Mācītāj, apsauc Savus mācekļus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Un Viņš atbildēja un uz tiem sacīja: “Es jums saku, ja šie cietīs klusu, tad akmeņi brēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Un kad Viņš tuvu klāt nāca, tad Viņš uzlūkoja to pilsētu un raudāja par to');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Sacīdams: “Kaut jel tu arī zinātu un šinī pašā un savā laikā, ko pie tava miera vajag! Bet nu tas ir apslēpts priekš tavām acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Jo tas laiks nāks pār tevi, ka tavi ienaidnieki apkārt ap tevi apmetīs ratu lēģeri, tevi apsēdēs un visās malās spaidīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Un tevi gluži izpostīs līdz ar taviem bērniem tavā vidū un akmeni uz akmens neatstās, tāpēc ka tu savas piemeklēšanas laiku neesi atzinusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Un Viņš gāja Dieva namā un sāka izdzīt, kas tur iekšā pirka un pārdeva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Uz tiem sacīdams: tā ir rakstīts: “Mans nams ir lūgšanas nams, bet jūs to esat darījuši par slepkavu bedri.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Un Viņš mācīja ikdienas Dieva namā. Bet tie augstie priesteri un rakstu mācītāji ar tiem ļaužu virsniekiem meklēja Viņu nokaut,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Un neatrada, kā to darīt, jo visi ļaudis Viņam piekrita un To klausīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Un notikās tanīs dienās, kad Viņš Dieva namā tos ļaudis mācīja un evaņģēliju sludināja, tad tie augstie priesteri un rakstu mācītāji ar tiem vecajiem piestājās');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'Un runāja uz Viņu sacīdami: “Saki mums, kādā varā Tu to dari, un kas tas ir, kas Tev šo varu devis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Un Viņš atbildēja un uz tiem sacīja: “Es arī jums vienu vārdu vaicāšu, sakāt Man arīdzan:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Jāņa kristība, vai tā bija no debesīm, vai no cilvēkiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Bet tie apdomājās savā starpā sacīdami: “Ja mēs sakām, no debesīm, tad Viņš sacīs: kādēļ tad jūs viņam neesat ticējuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Un ja mēs sakām: no cilvēkiem, tad visi ļaudis mūs akmeņiem nomētās, jo tie tic, ka Jānis esot pravietis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Un tie atbildēja, ka nezinot, no kurienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Un Jēzus uz tiem sacīja: “Tad Es arīdzan jums nesaku, kādā varā Es šās lietas daru.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Bet Viņš iesāka šo līdzību sacīt uz tiem ļaudīm: “Viens cilvēks dēstīja vīna kalnu un to izdeva dārzniekiem un nebija labu laiku mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Un kad bija laiks, tad viņš sūtīja kalpu pie tiem dārzniekiem, ka tie viņam dotu no vīna kalna augļiem, bet tie dārznieki to sita un to aizsūtīja tukšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Un viņš vēl otru kalpu sūtīja; un tie arī šo sita un apsmēja un aizsūtīja tukšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Un viņš vēl trešo sūtīja; bet tie arī šo sakāva un izmeta ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Un tā vīna kalna kungs sacīja: ko es darīšu? Es sūtīšu savu mīļo dēlu, varbūt tie šo redzēdami bīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Bet viņu redzēdami, tie dārznieki sarunājās savā starpā un sacīja: šis tas mantinieks; nāciet, nokausim to, ka tā mantība mums tiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Un tie viņu izmeta ārā no tā vīna kalna un nokāva. Ko tad nu tā vīna kalna kungs tiem darīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Viņš nāks un nomaitās šos dārzniekus un to vīna kalnu dos citiem.” Tie to dzirdējuši sacīja: “Lai tas nenotiek.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Bet Viņš tos uzlūkoja un sacīja: “Kas tad tas, kas ir rakstīts: tas akmens, ko tie nama taisītāji atmetuši, tas ir tapis par stūra akmeni?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Ikkatrs, kas uz šo akmeni kritīs, sadauzīsies; bet uz ko tas kritīs, to tas satrieks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Un tie augstie priesteri un rakstu mācītāji meklēja rokas pielikt pie Viņa tanī pašā stundā un bijās no tiem ļaudīm; jo tie noprata, ka Tas šo līdzību par viņiem bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Un tie uz Viņu glūnēja un izsūtīja, kurus bija izmācījuši, lai izliktos taisni, ka Viņu varētu savaldzināt kādā vārdā un nodot valdībai un zemes soģa varai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Un tie Viņam vaicāja sacīdami: “Mācītāj, mēs zinām, ka Tu pareizi runā un māci un neuzlūko cilvēka vaigu, bet māci Dieva ceļu pēc patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Vai ir brīv, ķeizaram meslus dot, vai ne?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Bet Tas viņu viltību nomanīja un uz tiem sacīja: “Kam jūs Mani kārdinājāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Rādiet Man šurp to nomas naudu; kā ir šī zīme un tas virsraksts?” Un tie atbildēdami sacīja: “Ķeizara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Un Viņš uz tiem sacīja: “Tad dodiet ķeizaram, kas ķeizaram pieder, un Dievam, kas Dievam pieder.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Un tie Viņu nevienā vārdā nevarēja ķert ļaužu priekšā, un brīnījās par Viņa atbildi un palika klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Bet tad kādi no tiem saducejiem (kas pretī runādami saka, augšāmcelšanos neesam) nāca un Viņu vaicāja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Sacīdami: “Mācītāj, Mozus mums ir rakstījis, kad kādam brālis mirst, kam sieva ir, un tas bez bērniem miris, ka viņa brālim to sievu būs apņemt un savam brālim celt dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Tad nu septiņi brāļi bija, un tas pirmais sievu apņēmis nomira bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Un tas otrais apņēma to sievu; šis arīdzan nomira bez bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Un tas trešais viņu apņēma. Un tāpat arī visi septiņi; un tiem nepalika bērnu pakaļ un tie nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Pēdīgi pēc visiem arī tā sieva nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Kuram no šiem tā sieva būs augšāmcelšanās laikā? Jo visiem septiņiem tā bijusi par sievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Un Jēzus atbildēdams uz tiem sacīja: “Šīs pasaules bērni precē un top precēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Bet tie, kas būs cienīgi tikt pie mūžīgas dzīvošanas un pie tās augšāmcelšanās no miroņiem, tie nedz precē, nedz top precēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Jo tie vairs nevar mirt, un ir eņģeļiem līdzīgi un Dieva bērni, būdami augšāmcelšanās bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Bet, ka miroņi top uzmodināti, to arī Mozus ir parādījis pie tā ērkšķu krūma, kad viņš To Kungu sauc par Ābrahāma Dievu un Īzaka Dievu un Jēkaba Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Bet Dievs nav mirušu, bet dzīvu Dievs, jo visi Viņam dzīvo.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Bet kādi no tiem rakstu mācītājiem atbildēja un sacīja: “Mācītāj, Tu pareizi esi sacījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Un viņi vairs neuzdrīkstējās Viņam nekā vaicāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Un Viņš uz tiem sacīja: “Kā tad saka, Kristu esam Dāvida dēlu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Un tas pats Dāvids saka dziesmu grāmatā: Tas Kungs sacīja uz manu Kungu: sēdies pa Manu labo roku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Tiekams es Tavus ienaidniekus lieku par pameslu Tavām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Tad nu Dāvids Viņu sauc par Kungu, - kā tad Tas ir viņa dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Un visiem ļaudīm dzirdot Viņš sacīja uz Saviem mācekļiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '“Sargājaties no tiem rakstu mācītājiem, kam tīk staigāt garos svārkos un mīl sveicinātiem tapt tirgos un sēdēt jo augstos krēslos baznīcās un jo augstās vietās viesībās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Kas atraitņu namus aprij un taisnojās ar savām garām lūgšanām; tie dabūs jo grūtu sodību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Un Savas acis pacēlis, Viņš redzēja bagātos savas dāvanas metam Dieva šķirstā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Un Viņš arī redzēja, ka viena nabaga atraitne divas artavas iemeta tur iekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Un sacīja: “Es jums tiešām saku, ka šī nabaga atraitne vairāk ir iemetusi, nekā visi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Jo šie visi no savas bagātības ir iemetuši pie tām Dieva dāvanām, bet šī no savas nabadzības ir iemetusi visu savu padomu, cik viņai bija.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Un kādiem par Dieva namu runājot, ka tas esot izgreznots ar dārgiem akmeņiem un jaukām uzkārtām dāvanām, Viņš sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '“Laiks nāks, kad no tā, ko jūs redzat, ne akmens uz akmens netaps pamests, ko nenolauzīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Un tie Viņam vaicāja sacīdami: “Mācītāj, kad tad tas būs? Un kāda tā zīme, kad šīs lietas notiks?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Bet Viņš sacīja: “Pielūkojiet, ka jūs netopat pievilti. Jo daudzi nāks Manā Vārdā sacīdami: es tas esmu, un tas laiks ir tuvu klāt nācis. Tad nu neejat viņiem pakaļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Bet kad jūs dzirdēsiet karus un dumpjus, tad neiztrūcinājaties, jo šim visam būs papriekš notikt, bet tūdaļ vēl nav tas gals.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Tad Viņš uz tiem sacīja: “Tauta celsies pret tautu un valsts pret valsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Un lielas zemes trīcēšanas būs dažās vietās un bada laiki un mēri arī bailīgas lietas un lielas zīmes no debesīm notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Bet pirms viss tas notiks, tie savas rokas jums pieliks un jūs vajās un nodos baznīcās un cietumos, un jūs vedīs priekš ķēniņiem un valdniekiem Mana Vārda dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Bet tas notiks jums par liecību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Tad nu apņematies savās sirdīs, nerūpēties iepriekš, kā jūs aizbildināsities.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Jo Es jums došu muti un gudrību, kam nevarēs pretī runāt nedz pretī stāvēt neviens no tiem, kas pret jums ceļas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Bet jūs tapsiet nodoti arī no vecākiem un brāļiem un radiem un draugiem. Un tie citus no jums nonāvēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Un jūs būsiet ienīdēti no visiem Mana Vārda dēļ');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Un tomēr ne matam no jūsu galvas nebūs zust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Caur savu pacietību izglābsiet savas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Bet kad jūs redzēsiet Jeruzālemi visapkārt apstātu no karaspēka, tad zināt, ka viņas izpostīšana ir tuvu klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Tad lai bēg kalnos, kas ir Jūdu zemē, un lai steidzās projām, kas ir viņas vidū; un tie, kas uz laukiem, lai neiet tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Jo šīs ir tās atriebšanas dienas, lai viss top piepildīts, kas ir rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Bet, ak vai, tām grūtām un zīdītājām tanīs dienās, jo tur būs lielas bēdas virs zemes un dusmas par šo tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Un tie kritīs caur zobena asmeni un gūstīti taps novesti pie visām tautām, un Jeruzāleme taps samīdīta no pagāniem, tiekams pagānu laiki būs piepildīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Un zīmes notiks pie saules, pie mēneša un pie zvaigznēm, un virs zemes tiem ļaudīm būs bail, un tie būs pārbijušies, un jūra un ūdens viļņi kauks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Un cilvēki nīcin iznīks no bailības, gaidīdami tās lietas, kas nāks virs zemes, jo debess stiprumi kustināsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Un tad tie redzēs To Cilvēka Dēlu padebesī nākam ar lielu spēku un godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Bet kad tas iesāks notikt, tad savas galvas paceldami skatāties uz augšu, tāpēc ka jūsu pestīšana jo tuvu nāk.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Un Viņš tiem sacīja vienu līdzību: “Uzlūkojiet vīģes koku un visus kokus!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Tūdaļ kad tie izplaukst, tad jūs to redzēdami paši nomaniet, ka vasara jau tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Tā tad arī, redzēdami šo visu notiekam, ziniet, ka Dieva valstība tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Patiesi, Es jums saku: šī cilts nezudīs, tiekams viss tas būs noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Debess un zeme zudīs, bet Mani vārdi nezudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Bet sargājaties, ka jūsu sirdis nekļūst apgrūtinātas ar lieku ēšanu un ar zūdīšanos pēc uztura, un ka šī diena piepeši jums neuzbrūk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Jo viņa nāks, kā kāds slazda valgs pār visiem, kas dzīvo pa visu zemes virsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Tāpēc esiet modrīgi allažiņ un lūdziet, lai varat šim visam izbēgt, kas notiks, un pastāvēt Tā Cilvēka Dēla priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Un Viņš pa tām dienām bija Dieva namā mācīdams; un pa tām naktīm Viņš izgāja un palika tai kalnā, kas top saukts Eļļas kalns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Un visi ļaudis nāca agri no rīta pie Viņa Dieva namā, Viņu klausīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Un tās neraudzētās maizes svētki, ko sauc Lieldienu, bija tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Un tie augstie priesteri un rakstu mācītāji meklēja, kā Viņu nokaut; jo tie bijās no tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Bet sātans iegāja iekš Jūdasa, kas tapa saukts Iskariots un bija viens no tiem divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Un tas nogāja un runāja ar tiem augstiem priesteriem un kara virsniekiem, kā tas Viņu tiem nodotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Un tie tapa līksmi un norunāja, viņam naudu dot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Un tas apsolīja un meklēja izdevīgu laiku, Viņu tiem nodot bez dumpja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Bet tās neraudzētās maizes diena nāca, kur Lieldienas jērs bija jākauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Un Viņš Pēteri un Jāni sūtīja sacīdams: “Ejat un sataisāt mums Lieldienas jēru, ka ēdam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Bet tie uz Viņu sacīja: “Kur Tu gribi, lai mēs to sataisām?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Un Viņš uz tiem sacīja: “Lūk, pilsētā ieejot jūs viens cilvēks sastaps, ūdens krūzi nesdams; ejat tam pakaļ tanī namā, kur tas ieiet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Un sakāt uz to nama kungu: Mācītājs tev saka: kur ir tā vieta, kur lai Es ar Saviem mācekļiem ēdu Lieldienas jēru?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Un viņš jums rādīs vienu lielu, ar deķiem izklātu istabu, turpat to sataisiet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Tie nogājuši atrada, kā Viņš tiem bija sacījis, un Lieldienas jēru sataisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Un kad tā stunda nāca, tad Viņš apsēdās un tie divpadsmit apustuļi līdz ar Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Un Viņš uz tiem sacīja: “Es sirsnīgi esmu vēlējies šo Lieldienas jēru ar jums ēst, pirms Es ciešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Jo Es jums saku, ka Es vairs no tā neēdīšu, tiekams tas taps piepildīts Dieva valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Un to biķeri ņēmis, Viņš pateicās un sacīja: “Ņemiet to un daliet to savā starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Jo Es jums saku, Es nedzeršu no vīna koka augļiem, tiekams Dieva valstība būs nākusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Un maizi ņēmis, Viņš pateicās un pārlauza un tiem to deva sacīdams: “Tā ir Mana miesa, kas par jums top dota. To dariet, Mani pieminēdami.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Tāpat arī to biķeri pēc tā vakarēdiena sacīdams: “Šis biķeris ir tā jaunā iestādīšana iekš Manām asinīm, kas par jums top izlietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Bet redzi, Mana nodevēja roka ir ar Mani pie galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Un Tas Cilvēka Dēls gan tā aiziet, kā tas ir nolikts, tomēr vai tam cilvēkam, kas Viņu nodod.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Un tie iesāka apjautāties savā starpā, kurš jel viņu starpā tas esot, kurš to grasās darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Un tur arī bāršanās cēlās viņu starpā, kurš no viņiem esot tas lielākais?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Bet Viņš uz tiem sacīja: “Pasaules ķēniņi valda, un tie varenie top saukti cienīgi kungi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Bet jūs tā ne. Bet tam lielākajam jūsu starpā būs būt kā tam mazākajam, un tam augstākajam kā tam kalpotājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Jo kurš tas lielākais, vai tas, kas sēž pie galda, vai tas, kas kalpo? Vai ne tas, kas sēž pie galda? Bet Es esmu jūsu starpā kā tāds, kas kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Bet jūs esat tie, kas pastāvējuši pie Manis iekš Manām kārdināšanām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Un tāpēc Es jums esmu novēlējis to valstību, kā Mans Tēvs Man to novēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Ka jums būs ēst un dzert pie Mana galda Manā valstībā un sēdēt uz krēsliem, tiesāt tās divpadsmit Israēla ciltis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Un Tas Kungs sacīja: “Sīmani, Sīmani, redzi, sātanam ir ļoti iegribējies jūs sijāt kā kviešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Bet Es esmu lūdzis par tevi, ka tava ticība nemitētos. Un kad tu vienreiz atgriezīsies, tad stiprini savus brāļus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Bet tas uz Viņu sacīja: “Kungs, es esmu gatavs ar Tevi iet cietumā un nāvē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Bet Viņš sacīja: “Es tev saku, Pēteri, gailis šodien nedziedās, pirms tu trīs reiz nebūsi liedzies, ka tu Mani pazīsti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Un Viņš uz tiem sacīja: “Kad Es jūs esmu sūtījis bez maka un kulītes un kurpēm, vai jums kas trūcis?” Un tie sacīja: “Nekas!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Tad Viņš uz tiem sacīja: “Bet tagad, kam maks ir, tas lai to ņem, tāpat arī kulīti. Un kam nav, tas lai savas drēbes pārdod un pērk zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Jo Es jums saku, ka vēl pie Manis būs piepildītam tapt, kas ir rakstīts: Viņš tiem netaisniem ir līdzināts. Jo kas ir rakstīts par Mani, tas piepildās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Bet tie sacīja: “Kungs, redzi, še ir divi zobeni.” Un Viņš tiem sacīja: “Ir diezgan.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Un izgājis Viņš staigāja pēc sava ieraduma uz Eļļas kalnu, un Viņa mācekļi Viņam gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Un tai vietā nācis Viņš uz tiem sacīja: “Lūdziet, ka jūs neiekrītat kārdināšanā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Un Viņš novērsās no tiem akmens metiena tālumā un ceļos nometies lūdzās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Un sacīja: “Tēvs, ja Tu gribi, tad ņem šo biķeri no Manis; tomēr ne Mans, bet Tavs prāts lai notiek.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Bet Viņam viens eņģelis no debesīm parādījās un Viņu stiprināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Un kad Viņš nāves bailēs cīnījās, tad Viņš Dievu pielūdza jo karsti; bet Viņa sviedri kā asins lāses pilēja uz zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Un no tās pielūgšanas cēlies Viņš nāca pie Saviem mācekļiem, un tos atrada aizmigušus aiz noskumšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Un uz tiem sacīja: “Ko jūs guļat? Ceļaties un lūdziet Dievu, ka neiekrītat kārdināšanā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Un Viņam vēl runājot, redzi, pulks ļaužu un viens no tiem divpadsmit, Jūdas vārdā, gāja tiem priekšā un nāca tuvu pie Jēzus, Viņu skūpstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Bet Jēzus uz to sacīja: “Jūdas, vai tu skūpstīdams nodod To Cilvēka Dēlu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Un tie, kas pie Viņa bija, redzēdami, kas tur gribēja notikt, uz Viņu sacīja: “Kungs, vai mums būs cirst ar zobenu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Un viens no tiem cirta augstā priestera kalpam, un tam nocirta labo ausi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Bet Jēzus atbildēja un sacīja: “Ļaujat pat to.” un Viņš tam to ausi aizskāra un to dziedināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Un Jēzus sacīja uz tiem augstiem priesteriem un tiem kara virsniekiem pie Dieva nama un tiem vecajiem, kas Viņam bija nākuši virsū: “Jūs esat izgājuši tā kā pret slepkavu ar zobeniem un šķēpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Es esmu bijis ikdienas pie jums Dieva namā, un jūs savas rokas Man neesat pielikuši; bet šī ir jūsu stunda un tas tumsības spēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Un tie Viņu saņēma, veda un noveda augstā priestera namā. Bet Pēteris gāja no tālienes pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Un kad tie uguni bija sakūruši nama vidū un kopā nosēdušies, Pēteris apsēdās viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Un viena kalpone, to redzēdama sēžam pie uguns, uzlūkoja to un sacīja: “Šis arīdzan bija pie Viņa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Bet tas Viņu aizliedza sacīdams: “Sieva, es Viņu nepazīstu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Un par mazu brīdi vēl cits to redzēdams sacīja: “Tu arīdzan esi no tiem.” Bet Pēteris sacīja: “Cilvēks, es neesmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Un par vienu stundu cits to apstiprināja sacīdams: “Patiesi, šis arīdzan ir bijis pie Viņa, jo tas arīdzan ir Galilejs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Bet Pēteris sacīja: “Cilvēks, es nezinu, ko tu runā.” Un tūdaļ kad tas vēl runāja, gailis dziedāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Un Tas Kungs atgriezās un uzlūkoja Pēteri. Tad Pēteris pieminēja Tā Kunga vārdu, ka Tas uz viņu bija sacījis: “Pirms nekā gailis dziedās, tu Mani trīs reiz aizliegsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Un ārā izgājis Pēteris raudāja gauži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Bet tie vīri, kas Jēzu turēja, Viņu apmēdīja un sita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Un tie Viņu aizklāja un sita Viņam vaigā un Viņam vaicāja sacīdami: “Uzmini, pravietis būdams, kurš Tevi sitis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Arī daudz citus vārdus tie uz Viņu sacīja, zaimodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Un kad gaisma ausa, tad sapulcējās tie ļaužu vecaji un augstie priesteri un rakstu mācītāji, un tie To veda augšā priekš savas tiesas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Un sacīja: “Ja Tu esi Kristus, tad saki mums.” Bet Viņš uz tiem sacīja: “Ja Es jums saku, tad jūs neticat;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'Bet ja Es vaicāšu, tad jūs Man neatbildēsiet un Mani nelaidīsiet vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Bet no šī laika Tas Cilvēka Dēls sēdēs pie Tā Visspēcīgā Dieva labās rokas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Tad visi sacīja: “Vai tad Tu esi Dieva Dēls?” Un Viņš uz tiem sacīja: “Jūs to sakāt, un Es tas esmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Un tie sacīja: “Kādas liecības mums vēl vajag? Mēs paši to esam dzirdējuši no Viņa mutes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Un viss viņu pulks cēlās un noveda Viņu pie Pilatus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Un iesāka Viņu apsūdzēt sacīdami: “Šo mēs atrodam, ka Viņš mūsu tautu sajauc un aizliedz ķeizaram metekli(nodokli) dot sacīdams: Viņš esot Kristus, viens Ķēniņš.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Un Pilatus Viņam vaicāja sacīdams: “Vai Tu esi Jūdu ķēniņš?” Un Viņš atbildēdams uz to sacīja: “Tu to saki.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Bet Pilatus sacīja uz tiem augstiem priesteriem un tiem ļaudīm: “Es nekādas vainas neatrodu pie šā cilvēka.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Bet tie tam stāvēja virsū un sacīja: “Viņš tos ļaudis skubina uz dumpi, mācīdams pa visu Jūdu zemi, iesākdams no Galilejas līdz šejienei.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Bet kad Pilatus Galileju dzirdēja, tad tas vaicāja, vai Viņš esot no Galilejas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Un dabūjis zināt, ka Viņš piederot apakš Hērodus tiesas, tas Viņu nosūtīja pie Hērodus, kas tanīs dienās arīdzan bija Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Bet kad Hērodus Jēzu redzēja, tad tas tapa ļoti līksms. Jo tas jau sen labprāt Viņu gribēja redzēt, tādēļ ka tas daudz par Viņu bija dzirdējis un cerēja kādu zīmi no Viņa redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Un tas dažādas lietas vaicāja no Viņa. Bet Viņš tam neatbildēja nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Un tie augstie priesteri un rakstu mācītāji stāvēja un Viņu apsūdzēja gauži.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Bet Hērodus ar savu pils saimi Viņu nicināja un apmēdīja, un tam baltu drēbi apvilka un to sūtīja atpakaļ pie Pilatus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Tanī dienā Pilatus un Hērodus palika par draugiem, jo papriekš tie savā starpā bija ienaidā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Un Pilatus, saaicinājis tos augstos priesterus un virsniekus un tos ļaudis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Uz tiem sacīja: “Jūs šo cilvēku pie manis esat atveduši, ka Viņš tos ļaudis novēršot, un redziet, es Viņu esmu jūsu priekšā izklausinājis un pie tā cilvēka neesmu atradis it nekādas vainas, par ko jūs Viņu apsūdzat;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Un Hērodus arī ne; jo tas Viņu pie mums atpakaļ sūtījis, un redzi, Viņš nekā nav darījis, ar ko nāvi būtu pelnījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Tāpēc es Viņu gribu pārmācīt un atlaist.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Un uz svētkiem tam vajadzēja viņiem vienu cietumnieku atlaist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Bet viss tas pulks brēca un sacīja: “Nost ar šo un atlaidi mums Barabu!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Tas kāda dumpja dēļ, kas pilsētā bija noticis, un slepkavības dēļ bija iemests cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Tad Pilatus atkal viņus uzrunāja un gribēja Jēzu atlaist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Bet tie sauca un sacīja: “Sit Viņu krustā, sit Viņu krustā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Bet viņš trešu reiz uz tiem sacīja: “Ko tad Šis ļauna darījis? Es pie Viņa nekādas nāves vainas neatrodu; tāpēc es Viņu gribu pārmācīt un atlaist.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Bet tie tam mācās virsū ar lielu brēkšanu lūgdami, ka Viņš taptu krustā sists, un viņu brēkšana pārspēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Tad Pilatus nosprieda, lai viņu lūgšanas notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Un viņš tiem atlaida to, kas dumpja un slepkavības dēļ cietumā bija iemests, ko tie bija izlūgušies, bet Jēzu tas nodeva viņu prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Un kad Viņu aizveda, tad tie saņēma vienu no Kirenes, vārdā Sīmani, kas nāca no lauka, un uzlika tam to krustu, ka tas to Jēzum pakaļ nestu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Bet liels ļaužu un sievu pulks Viņam gāja pakaļ, tās Viņu žēloja un apraudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Bet Jēzus uz tām atgriezās un sacīja: “Jūs Jeruzālemes meitas, neraudāt par Mani, bet raudāt pašas par sevi un par saviem bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Jo redziet, nāks dienas, kad sacīs: svētīgas ir tās neauglīgās un tās miesas, kas nav bērnus nesušas, un tās krūtis, kas nav zīdījušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Tad tie iesāks sacīt uz tiem kalniem: krītiet uz mums! un uz tiem pakalniem: apklājiet mūs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Jo kad to dara pie zaļa koka, kas tad vēl notiks pie sakaltuša?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Bet divi citi ļauna darītāji arīdzan tapa novesti, ka taptu nomaitāti līdz ar Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Un kad tie nāca uz to vietu, ko sauc par pieres vietu, tad tie tur sita krustā Viņu un tos ļauna darītājus, vienu pa labo un otru pa kreiso roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Bet Jēzus sacīja: “Tēvs, piedod tiem, jo tie nezina, ko tie dara.” Un tie, Viņa drēbes dalīdami, kauliņus par tām meta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Un tie ļaudis stāvēja skatīdamies. Bet tie virsnieki savā starpā Viņu apsmēja sacīdami: “Viņš citiem palīdzējis, lai palīdzās pats Sev, ja šis ir Kristus, tas Dieva izredzētais.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Un arī tie karavīri Viņu apmēdīja, piegāja un Viņam etiķi atnesa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'Un sacīja: “Ja Tu esi tas Jūdu ķēniņš, tad palīdzies pats Sev.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Un virsraksts pār Viņu bija rakstīts ar Grieķu, Romiešu un Ebreju rakstiem: šis ir tas Jūdu ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Bet viens no tiem pakārtiem ļauna darītājiem Viņu zaimoja, sacīdams: “Ja Tu esi Kristus, tad palīdzi Sev pašam un mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Bet tas otrais to aprāja un sacīja: “Un tu arīdzan nebīsties no Dieva, kas esi tanī pašā sodībā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Un tomēr mums gan pareizi notiek. Jo mēs dabūjam, ko esam nopelnījuši ar saviem darbiem, bet šis nekā ļauna nav darījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Un viņš uz Jēzu sacīja: “Kungs, piemini mani, kad Tu nāksi Savā valstībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Un Jēzus uz to sacīja: “Patiesi, Es tev saku: šodien tu būsi ar Mani paradīzē!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Un tas bija ap sesto stundu, tad tapa tumšs pār visu to zemi līdz devītajai stundai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Un saule tapa aptumšota, un tas priekškaramais auts Dieva namā pārplīsa vidū pušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Un Jēzus sauca ar skaņu balsi un sacīja: “Tēvs, Es Savu garu nododu Tavās rokās.” Un to sacījis Viņš dvēseli izlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Un tas kapteinis redzēdams, kas notika, Dievu teica un sacīja: “Patiesi, šis ir bijis taisns cilvēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Un visi, kas tur klātu bija un redzēja, kas tur notika, tie sita pie krūtīm un griezās atpakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Bet visi Viņa mīļie stāvēja no tālienes un tās sievas, kas ar Viņu bija nākušas no Galilejas un šās lietas redzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Un redzi, viens vīrs, Jāzeps vārdā, kas bija runas kungs, labs un taisns vīrs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(Šis nebija piemeties viņu padomam un darīšanai,) no Arimatijas, Jūdu pilsētas, kas arī pats gaidīja uz Dieva valstību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Šis piegājis pie Pilatus lūdza Jēzus miesas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Un tās noņēma, ietina smalkā audeklī un ielika kapā, kas bija izcirsts klintī, kur vēl neviens nebija glabāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Un tā bija tā sataisāmā diena, un svētdiena jau iesākās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Un tās sievas, kas ar Viņu bija nākušas no Galilejas, arīdzan gāja pakaļ un skatījās uz to kapu, un kā Viņa miesas tapa noliktas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Un atpakaļ griezušās tās sataisīja smaržīgas svaidāmas zāles, un to svēto dienu tās bija klusu pēc bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Bet pirmajā nedēļas dienā it agri, gaismai austot, tās sievas nāca pie kapa un nesa tās svaidāmās zāles, ko tās bija sataisījušas. Un vēl kādas citas bija līdz ar tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Un tās atrada to akmeni no kapa noveltu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Un gāja iekšā un Tā Kunga Jēzus miesas neatrada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Un notikās, kad tās nezināja, ko darīt, redzi, tad pie tām divi vīri piestājās, kam drēbes spīdēja tā kā zibens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Un kad tās pārbijušās galvu nokāra, viņi uz tām sacīja: “Ko jūs meklējat to dzīvo pie mirušiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Viņš nav šeitan, bet ir uzcēlies. Pieminiet, ko Viņš jums runājis, vēl būdams iekš Galilejas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Sacīdams: Tam Cilvēka Dēlam būs tapt nodotam grēcinieku rokās un tapt krustā sistam un trešā dienā augšām celties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Un tās pieminēja Viņa vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Un atpakaļ griezušās no kapa tās to visu pasludināja tiem vienpadsmit un visiem citiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Un tur bija Marija Madaļa un Joanna un Marija, Jēkaba māte, un tās citas ar tām, tās tiem apustuļiem to sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Un viņu vārdi tiem likās kā pasakas, un tie viņām neticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Un Pēteris cēlās, tecēja pie tā kapa un locīdamies paskatījās un redzēja tos autus pie malas liktus, un aizgāja, pats pie sevis brīnīdamies par to, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Un redzi, divi no tiem gāja tanī pašā dienā uz kādu pilsētiņu, kas bija no Jeruzālemes labu jūdzi (zemes) tālu, ar vārdu Emmaūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Un tie runāja savā starpā par visām tām lietām, kas bija notikušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Un gadījās, kad tie tā runāja savā starpā, arī pats Jēzus pie tiem piegāja un līdz ar tiem staigāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Bet viņu acis tapa turētas, ka tie Viņu nepazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Un Viņš uz tiem sacīja: “Kādas tās runas, ko jūs runājat savā starpā uz ceļa un esat tik noskumuši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Tad viens ar vārdu Kleopas atbildēja un uz Viņu sacīja: “Vai tad tu viens esi tāds svešinieks Jeruzālemē, kas nezina, kas šinīs dienās tur noticis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Un Viņš uz tiem sacīja: “Kas tad?” Un tie uz Viņu sacīja: “Tas ar Jēzu no Nacaretes, kas bija pravietis, varens darbos un vārdos priekš Dieva un visiem ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Kā to mūsu augstie priesteri un virsnieki ir nodevuši pie pazudināšanas uz nāvi un Viņu situši krustā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Bet mēs cerējām, ka Viņam bija Israēli atpestīt; un pār visu to šodien ir tā trešā diena, ka šīs lietas ir notikušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Tad arī kādas no mūsu sievām mūs izbiedējušas; tās agri bijušas pie kapa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'Un Viņa miesas neatradušas, nāk un saka, ka esot eņģeļu parādīšanu redzējušas, kas saka, Viņš esot dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Un kādi no mums nogāja pie kapa un atrada tā, kā tās sievas sacīja, bet Viņu pašu tie neredzēja.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Tad Viņš uz tiem sacīja: “Ak jūs nesaprašas un sirds kūtrie, ka jūs negribat ticēt visu to, ko tie pravieši sludinājuši!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Vai Kristum tā nebija jācieš un jāieiet Savā godībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Pēc iesākdams no Mozus un no visiem praviešiem Viņš tiem izstāstīja visus rakstus, kas par Viņu bija rakstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Un tie nāca klāt pie tās pilsētiņas, kurp tie gāja, bet Viņš likās ejot tālāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Un tie to gauži lūdza un sacīja: “Palieci pie mums, jo vakars jau metās, un tā diena ir pagalam;” un Viņš iegāja pie tiem palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Un notikās, ka Viņš ar tiem sēdēdams pie galda to maizi ņēma, pateicās, pārlauza un tiem to deva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Tad viņu acis tapa atvērtas, un tie Viņu pazina; bet Viņš no tiem nozuda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Un tie sacīja savā starpā: “Vai mūsu sirds iekš mums nedega, kad Viņš ar mums runāja uz ceļa, mums tos rakstus izstāstīdams?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Un tanī pašā stundā tie cēlās, griezās atpakaļ uz Jeruzālemi un atrada tos vienpadsmit sapulcētus un tos, kas pie tiem bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Tie sacīja: “Tas Kungs patiesi ir augšām cēlies un Sīmanim parādījies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Un viņi šiem stāstīja, kas bija noticis uz ceļa, un kā Tas no viņiem pazīts, to maizi lauzdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Un kad tie runāja par šīm lietām, tad Jēzus stāvēja pats vidū starp tiem un uz tiem sacīja: “Miers ar jums!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Bet tie ļoti izbijās un tiem šķita, ka garu redzot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Un Viņš uz tiem sacīja: “Kam jūs esat tā izbijušies? Un kāpēc tādas domas ceļas jūsu sirdīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Redziet Manas rokas un Manas kājas; Es pats tas esmu. Aptaustiet Mani un apskatiet; jo garam nav miesas un kaulu, kā jūs redzat Man esam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Un to sacījis Viņš tiem rādīja Savas rokas un kājas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Bet kad tie to aiz prieka vēl neticēja un brīnījās, tad Viņš uz tiem sacīja: “Vai jums še kas ir, ko ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Un tie Tam cēla priekšā ceptas zivs gabalu un tīru medu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Un Viņš ņēma un to ēda viņiem redzot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Pēc Viņš uz tiem sacīja: “Šie ir tie vārdi, ko Es jums esmu sacījis, pie jums vēl būdams, ka visam būs notikt, kas par Mani rakstīts Mozus bauslībā, praviešos un dziesmās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Tad Viņš tiem saprašanu atdarīja, ka tie tos rakstus saprata,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Un uz tiem sacīja: “Tā tas stāv rakstīts, ka Kristum bija jācieš un augšām jāceļas no miroņiem trešā dienā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'Un ka Viņa Vārdā jāsludina atgriešanās un grēku piedošana visām tautām, iesākot no Jeruzālemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Un jūs esat liecinieki par šo visu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Un redzi, Es uz jums sūtu Sava Tēva apsolīšanu. Bet paliekat jūs Jeruzālemes pilsētā, līdz kamēr tiksiet apģērbti ar spēku no augšienes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Un viņš tos izveda līdz Betānijai un Savas rokas pacēlis tos svētīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Un notikās, kad Viņš tos svētīja, tad Viņš no tiem šķīrās un tapa uzcelts uz debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Bet tie Viņu pielūdza un griezās atpakaļ uz Jeruzālemi ar lielu prieku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Un bija allažiņ Dieva namā, teica un slavēja Dievu. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Iesākumā bija Vārds, un Vārds bija pie Dieva, un Dievs bija Vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Tas bija iesākumā pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Visas lietas ir darītas caur Viņu, un bez Viņa nekas nav darīts, kas ir darīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Iekš Viņa bija dzīvība, un tā dzīvība bija cilvēku gaišums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Un tas gaišums spīd tumsībā, un tumsība to nesaņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Viens cilvēks bija no Dieva sūtīts, Jānis vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Tas nāca liecības dēļ, ka dotu liecību par To Gaišumu, lai visi caur to ticētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Viņš pats nebija tas gaišums, bet ka tas liecību dotu par To Gaišumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Tam patiesam Gaišumam, kas ikvienu cilvēku apgaismo, bija nākt pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Viņš bija pasaulē, un pasaule ir caur Viņu darīta; bet pasaule Viņu nepazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Viņš nāca pie tiem savējiem, un šie Viņu neuzņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Bet cik Viņu uzņēma, tiem Viņš deva vaļu, palikt par Dieva bērniem, tiem, kas tic uz Viņa Vārdu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Kas ne no asinīm, nedz no miesas gribēšanas, nedz pēc kāda vīra prāta, bet kas no Dieva dzimuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Un tas Vārds tapa miesa un dzīvoja mūsu starpā, pilns žēlastības un patiesības, un mēs redzējām Viņa godību, tādu godību, kā Tā vienpiedzimušā Dēla no Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jānis dod liecību par Viņu un sauc sacīdams: “Šis bija Tas, par ko es sacīju: kas nāk pēc manis, Tas ir bijis priekš manis. Viņš bija pirmāk nekā es.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Un no Viņa pilnuma mēs visi esam dabūjuši žēlastību uz žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Jo bauslība ir dota caur Mozu, žēlastība un patiesība ir notikusi caur Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Dievu neviens nekad nav redzējis: tas vienpiedzimušais Dēls, Tēva klēpī būdams, Tas mums to ir stāstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Un šī ir Jāņa liecība, kad tie Jūdi no Jeruzālemes priesterus un levitus sūtīja, lai tam jautā: “Kas tu esi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Un viņš apliecināja un neliedzās, un apliecināja: “Es neesmu Kristus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Un tie tam jautāja: “Kas tad? Vai tu esi Elija?” Un viņš saka: “Neesmu.” “Vai tu esi tas Pravietis?” Un viņš atbildēja: “Nē”.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Tad tie uz viņu sacīja: “Kas tu esi? lai atbildam tiem, kas mūs sūtījuši; ko tu saki par sevi pašu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Viņš sacīja: “Es esmu saucēja balss tuksnesī: sataisiet Tā Kunga ceļu, kā pravietis Jesaja sacījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Un tie izsūtītie bija no tiem farizejiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Un tie viņam jautāja un uz viņu sacīja: “Kāpēc tad tu kristi, kad tu neesi Tas Kristus, nedz Elija, nedz tas Pravietis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Jānis tiem atbildēja un sacīja: “Es kristīju ar ūdeni; bet Tas jūsu vidū iestājies, ko jūs nepazīstat;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Tas nāk pēc manis, un ir bijis priekš manis, Tam es neesmu cienīgs kurpju siksnas atraisīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Tas notika Betanijā viņpus Jardānes upes, kur Jānis kristīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Otrā dienā Jānis Jēzu ierauga nākam un saka: “Redzi, Tas Dieva Jērs, kas nes pasaules grēkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Šis ir Tas, par ko es esmu sacījis: pēc manis nāk vīrs, kas bijis priekš manis: jo Viņš bija pirmāk nekā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Un es Viņu nepazinu: bet lai Viņš Israēlim taptu zināms, tāpēc es esmu nācis, kristīdams ar ūdeni.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Un Jānis deva liecību sacīdams: “Es redzēju to Garu nolaižamies no debess kā balodi un paliekam uz Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Un es Viņu nepazinu, bet kas mani sūtījis kristīt ar ūdeni, Tas uz mani sacīja: uz ko tu redzēsi to Garu nolaižamies un paliekam, šis ir Tas, kas kristī ar Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Un es esmu redzējis un liecību devis, ka šis ir Tas Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Otrā dienā Jānis atkal stāvēja un divi no viņa mācekļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Un ieraudzījis Jēzu staigājam, viņš saka: “Redzi, Tas Dieva Jērs!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Un tie divi mācekļi viņu dzirdēja runājam un Jēzum gāja pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Un Jēzus atgriezdamies un tos redzējis pakaļ nākam, uz tiem saka: “Ko jūs meklējat?” Un tie uz Viņu sacīja: “Rabbi, (tas ir tulkots: mācītājs,) kur Tu mājo?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Viņš uz tiem saka: “Nāciet un redziet.” Tie nāca un redzēja, kur Viņš mājoja, un palika to dienu pie Viņa, un tas bija ap desmito stundu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Andrejs, Sīmaņa Pētera brālis, bija viens no tiem diviem, kas to no Jāņa bija dzirdējuši un Viņam gājuši pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Šis pirmais atrod savu brāli Sīmani un uz to saka: “Mēs to Mesiju esam atraduši (tas ir tulkots: Kristus).”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Un viņš to veda pie Jēzus. Un Jēzus to uzlūkoja un sacīja: “Tu esi Sīmanis, Jonas dēls, tu tapsi saukts Kefas, tas ir tulkots: Pēteris (akmens).”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Otrā dienā Jēzus gribēja iziet uz Galileju un atrod Filipu un uz to saka: “Nāc Man pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Un Filips bija no Betsaidas, Andreja un Pētera pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filips atrod Natanaēli un uz to saka: “Par ko Mozus bauslībā rakstījis un tie pravieši, To mēs esam atraduši, Jēzu no Nacaretes, Jāzepa dēlu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Un Natanaēls uz to sacīja: “Vai no Nacaretes var būt kāds labums?” Filips uz to saka: “Nāc un redzi!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jēzus redzēja Natanaēli nākam, un par to saka: “Redzi, patiesi viens Israēlietis, iekš kā viltības nav.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanaēls uz Viņu saka: “Kā Tu mani pazīsti?” Jēzus atbildēja un uz to sacīja: “Es tevi redzēju, pirms Filips tevi aicināja, kad tu biji apakš tā vīģes koka.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanaēls atbildēja un uz Viņu saka: “Rabbi, Tu esi Dieva Dēls, Tu esi Israēla Ķēniņš.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jēzus atbildēja un uz to sacīja: “Tādēļ tu tici, ka Es tev esmu sacījis: Es tevi redzēju apakš tā vīģes koka. Tu redzēsi lielākas lietas nekā tās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Un Viņš uz to saka: “Patiesi, patiesi, Es jums saku: no šī laika jūs redzēsiet debesis atvērtas un Dieva eņģeļus uzkāpjam un nokāpjam uz To Cilvēka Dēlu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Un trešajā dienā kāzas bija Kānā iekš Galilejas, un Jēzus māte bija tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Bet arī Jēzus un Viņa mācekļi tapa aicināti uz tām kāzām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Un kad vīna pietrūka, Jēzus māte saka uz Viņu: “Tiem nav vīna.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jēzus uz to saka: “Sieva, kas Man ar tevi? Mana stunda vēl nav nākusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Viņa māte uz tiem sulaiņiem saka: “Ko Viņš jums teiks, to dariet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Un tur seši akmeņu ūdens trauki bija likti pēc Jūdu šķīstīšanas, un ikkatrā sagāja divi līdz trīs mēri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jēzus uz tiem saka: “Pildiet šos traukus ar ūdeni!” Un tie tos pildīja līdz malai pilnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Un Viņš uz tiem saka: “Smeļat nu un nesat barības sargam;” un tie to nesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Kad nu barības sargs to ūdeni baudīja, kas bija palicis par vīnu (un nezināja, no kurienes tas bija, bet tie sulaiņi to zināja, kas to ūdeni bija smēluši), tad barības sargs aicina brūtgānu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Un uz to saka: “Ikkatrs cilvēks papriekš ceļ priekšā labo vīnu, un kad tie iedzērušies, plānāko; tu labo vīnu līdz šim esi pataupījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Šī tā pirmā brīnuma zīme, ko Jēzus darīja Kānā iekš Galilejas, un parādīja Savu godību, un Viņa mācekļi ticēja uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Pēc tam Viņš nogāja uz Kapernaūmu, pats un Viņa māte un Viņa brāļi un Viņa mācekļi, un viņi tur palika kādas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Un Jūdu Lieldiena bija tuvu klāt, un Jēzus aizgāja uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Un Viņš atrada Dieva namā tos, kas pārdeva vēršus un avis un baložus, un tos naudas mijējus tur sēžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Un pātagu taisījis no auklām, Viņš izdzina visus no Dieva nama ārā un arī tās avis un tos vēršus un izkaisīja tiem mijējiem to naudu un apgāza tos galdus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Un sacīja tiem baložu pārdevējiem: “Nesiet to projām! Nedariet Mana Tēva namu par tirgus namu!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Bet Viņa mācekļi pieminēja, ka ir rakstīts: “Karstums Tava nama dēļ Mani aprij.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Tad tie Jūdi atbildēja un uz Viņu sacīja: “Kādu zīmi Tu mums rādi, ka Tu šās lietas dari?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jēzus atbildēja un uz tiem sacīja: “Noplēsiet šo Dieva namu, tad Es to atkal uzcelšu trejās dienās?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Tad tie Jūdi sacīja: “Šis Dieva nams četrdesmit un sešos gados ir uztaisīts, un Tu to uzcelsi trejās dienās?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Bet Viņš runāja par Savas miesas Dieva namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Kad Viņš nu bija augšām cēlies no miroņiem, tad Viņa mācekļi atminējās, ka Viņš to uz tiem bija sacījis, un ticēja tam rakstam un tam vārdam, ko Jēzus bija sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Un kad Viņš pa tiem svētkiem bija Jeruzālemē, tad daudzi ticēja uz Viņa Vārdu, redzēdami tās brīnuma zīmes, ko Viņš darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Bet Jēzus pats viņiem neuzticējās, tāpēc ka Viņš visus pazina,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'Un ka Viņam nevajadzēja, lai kas Viņam liecību dotu par cilvēku; jo Viņš pats zināja, kas bija iekš cilvēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Un tur viens cilvēks bija no tiem farizejiem, vārdā Nikademus, Jūdu virsnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Tas nāca pie Jēzus naktī un uz Viņu sacīja: “Rabbi, mēs zinām, ka Tu esi Mācītājs, no Dieva nācis; jo neviens nevar darīt tās brīnuma zīmes, ko Tu dari, ja Dievs nav ar to.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jēzus atbildēja un uz to sacīja: “Patiesi, Es tev saku, ja kas nav piedzimis no augšienes, tad tas Debesu valstību nevar redzēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikademus uz Viņu saka: “Kā cilvēks var piedzimt, vecs būdams? Vai viņš atkal var ieiet savas mātes miesās un piedzimt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Un Jēzus atbildēja: “Patiesi, patiesi, Es tev saku: ja kas nepiedzimst caur ūdeni un Garu, tad tas nevar ieiet Dieva valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Kas piedzimis no miesas, tas ir miesa, un kas piedzimis no Gara, tas ir gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Nebrīnies, ka Es tev esmu sacījis: Jums būs piedzimt no augšienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Vējš pūš, kur gribēdams, un tu gan dzirdi viņa pūšanu, bet tu nezini, no kurienes viņš nāk un kurp viņš iet. Tā ir ar ikvienu, kas piedzimis no Gara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikademus atbildēja un uz Viņu sacīja: “Kā tas var notikt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jēzus atbildēja un uz to sacīja: “Tu esi mācītājs iekš Israēla un to tu nezini?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Patiesi, patiesi, Es tev saku. Mēs runājam, ko zinām, un liecinājām, ko esam redzējuši, un jūs mūsu liecību nepieņemat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Ja jūs neticat, kad Es jums saku par zemes lietām; kā jūs tad ticēsiet, kad Es jums sacīšu par debesu lietām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Jo neviens nav braucis uz debesīm kā vien Tas, kas ir nācis no debesīm, Tas Cilvēka Dēls, kas ir debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Un kā Mozus tuksnesī čūsku ir paaugstinājis, tāpat Tam Cilvēka Dēlam būs tapt paaugstinātam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Lai ikviens, kas tic uz Viņu, dabū mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Jo tik ļoti Dievs pasauli mīlējis, ka Viņš Savu vienpiedzimušo Dēlu devis, ka visiem tiem, kas tic uz Viņu, nebūs pazust, bet dabūt mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Jo Dievs Savu Dēlu nav sūtījis pasaulē, ka Tas pasauli sodītu, bet ka pasaule caur Viņu taptu pestīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kas tic uz Viņu, tas netop sodīts, bet kas netic, tas jau ir sodīts, tāpēc ka tas nav ticējis uz tā vienpiedzimušā Dieva Dēla Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Bet šī ir tā sodība, ka gaišums nācis pasaulē un cilvēki vairāk mīlēja tumsību nekā gaišumu, tāpēc ka viņu darbi bija ļauni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Jo ikviens, kas dara ļaunu, tas ienīst gaismu un nenāk priekš gaismas, lai viņa darbi netop norāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Bet kas dara patiesību, tas nāk priekš gaismas, lai viņa darbus var redzēt, jo tie darīti iekš Dieva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Pēc tam Jēzus un Viņa mācekļi nāca uz Jūdu zemi, un Viņš tur ar tiem palika un kristīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Un Jānis arīdzan kristīja Enonā, tuvu pie Zalimes, jo tur bija daudz ūdens. Un tie (ļaudis) nogāja un tapa kristīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Jo Jānis vēl nebija likts cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Tad viena apjautāšanās cēlās starp Jāņa mācekļiem un tiem Jūdiem par šķīstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Un tie nāca pie Jāņa un uz to sacīja: “Rabbi, Tas, kas bija pie tevis viņpus Jardānes, kam tu liecību devi, redzi, Tas kristī, un visi nāk pie Viņa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jānis atbildēja un sacīja: “Cilvēks nekā nevar ņemties, ja tas viņam nav dots no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Jūs paši esat mani liecinieki, ka es esmu sacījis: Es neesmu Tas Kristus, bet sūtīts Viņa priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kam tā brūte, tas ir brūtgāns, bet tā brūtgāna draugs, kas stāv un viņu dzird, priecājās ļoti par tā brūtgāna balsi. Tad nu šis mans prieks ir piepildīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Viņam būs iet lielumā, bet man mazumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kas nāk no augšienes, tas ir pār visiem; kas ir no zemes, tas ir no zemes: kas nāk no debesīm, tas ir pār visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Un ko Tas ir redzējis un dzirdējis, to Tas apliecina; un Viņa liecību neviens nepieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kas Viņa liecību pieņēmis, tas ir apzieģelējis, Dievu esam patiesīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Jo ko Dievs ir sūtījis, tas runā Dieva vārdus, jo Dievs nedod To Garu ar mēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Tas Tēvs mīļo To Dēlu un visas lietas ir devis Viņa rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kas tic uz To Dēlu, tam ir mūžīga dzīvība; bet kas Tam Dēlam neklausa, tas dzīvību neredzēs, bet Dieva dusmība uz tā paliek.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Un kad Tas Kungs nomanīja, ka tie farizeji bija dzirdējuši, ka Jēzus vairāk mācekļu dabūjot un vairāk kristījot nekā Jānis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Jebšu Jēzus pats nekristīja, bet Viņa mācekļi,)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Tad Viņš atstāja Jūdeju un atkal nogāja uz Galileju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Un Viņam bija jāiet caur Samariju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Tad Viņš nonāk vienā Samarijas pilsētā, ko sauc Sīharu, tuvu pie tā tīruma, ko Jēkabs deva savam dēlam Jāzepam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Un tur bija Jēkaba aka. Kad nu Jēzus, no ceļa piekusis, pie tās akas apsēdās, - un tas bija ap sesto stundu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Tad viena sieva no Samarijas nāk ārā, ūdeni smelt. Uz to Jēzus saka: “Dodi Man dzert.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(Jo viņa mācekļi bija nogājuši pilsētā, maizi pirkt.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Tad tā Samariešu sieva uz Viņu saka: “Kā Tu, Jūds būdams, prasi dzert no manis, vienas Samariešu sievas?” Jo Jūdi netur nekādu draudzību ar Samariešiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jēzus atbildēja un uz to sacīja: “Ja tu to Dieva dāvanu zinātu un kas Tas tāds ir, kas uz tevi saka: dod Man dzert; tad tu Viņu būtu lūgusi, un Viņš tev būtu devis dzīvu ūdeni.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Tā sieva uz Viņu saka: “Kungs, Tev nav smeļama trauka, un tā aka ir dziļa, - no kurienes tad Tev ir tas dzīvais ūdens?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Vai Tu esi lielāks nekā mūsu tēvs Jēkabs, kas mums šo aku devis un pats no tās dzēris un viņa dēli un viņa lopi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jēzus atbildēja un uz to sacīja: “Ikvienam, kas dzer no šī ūdens, atkal slāpst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Bet ja kas dzers no tā ūdens, ko Es tam došu, tam neslāps ne mūžam; bet tas ūdens, ko Es tam došu, iekš viņa taps par ūdens avotu, kas verd uz mūžīgu dzīvošanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Tā sieva uz Viņu saka: “Kungs, dod man to - tādu ūdeni, ka man neslāpst un man vairs nav jānāk šurpu smelt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jēzus uz to saka: “Ej, sauc savu vīru un nāc šurp.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Tā sieva atbildēja un sacīja: “Man vīra nav.” Jēzus uz to saka: “Tu pareizi esi sacījusi: man vīra nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Jo pieci vīri tev bijuši, un kas tev tagad ir, tas nav tavs vīrs; to tu pēc taisnības esi sacījusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Tā sieva uz Viņu saka: “Kungs, es redzu, ka Tu esi pravietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Mūsu tēvi ir pielūguši šinī kalnā, un jūs sakāt, Jeruzālemē to vietu esam, kur pienākas pielūgt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jēzus uz to saka: “Sieva, tici Man, tā stunda nāk, ka jūs nedz šai kalnā, nedz Jeruzālemē To Tēvu pielūgsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Jūs pielūdzat, ko jūs nezināt, mēs pielūdzam, ko mēs zinām; jo pestīšana ir no tiem Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Bet tā stunda nāk un jau tagad ir, ka tie īstenie pielūdzēji To Tēvu pielūgs garā un patiesībā; jo Tas Tēvs tādus arī meklē, kas To tā pielūdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dievs ir Gars, un kas To pielūdz, tiem To būs pielūgt garā un patiesībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Tā sieva uz Viņu saka: “Es zinu, ka tas Mesija nāk, kas saukts Kristus; kad Tas nāks, Tas mums visu pasludinās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jēzus uz to saka: “Es Tas esmu, kas ar tevi runā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Un tai brīdī Viņa mācekļi nāca un brīnījās, ka Viņš ar to sievu runāja. Tomēr neviens nesacīja: Ko Tu vaicā? Jeb, ko Tu runā ar viņu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Tad tā sieva pameta savu ūdens trauku un nogāja pilsētā un sacīja uz tiem ļaudīm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '“Nāciet, redziet vienu cilvēku, kas man visu ir sacījis, ko es esmu darījusi. Vai Šis nav Tas Kristus?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Tad tie izgāja no pilsētas un nāca pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Un pa to starpu tie mācekļi Viņu lūdza sacīdami: “Rabbi, ēd.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Bet Viņš uz tiem sacīja: “Man barība jāēd, ko jūs nezināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Tad tie mācekļi savā starpā sacīja: “Vai kas Viņam ko atnesis ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jēzus uz tiem saka: “Mana barība ir, ka Es daru Tā prātu, kas Mani sūtījis, un padaru Viņa darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Vai jūs nesakāt: Vēl ir četri mēneši, tad nāk pļaujamais laiks? Redzi, Es jums saku: Paceliet savas acis un skatiet tās druvas, jo tās jau ir baltas uz pļaušanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Un kas pļauj, tas dabū algu un sakrāj augļus uz mūžīgu dzīvošanu, ka abi var priecāties kopā, sējējs un pļāvējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Jo še tas vārds ir tiesa: Cits ir tas sējējs un cits tas pļāvējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Es jūs esmu sūtījis pļaut, kur jūs neesat strādājuši; citi tur strādājuši, un jūs esat nākuši viņu darbā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Bet no tās pašas pilsētas daudz Samariešu ticēja uz Viņu tās sievas vārdu dēļ, kas liecību deva: “Viņš man visu ir sacījis, ko es esmu darījusi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Kad nu tie Samarieši pie Viņa nāca, tad tie Viņu lūdza, ka Viņš pie tiem paliktu; un Viņš tur palika divas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Un daudz vairāk no tiem ticēja Viņa paša vārdu dēļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Un sacīja uz to sievu: “Mēs neticam vairs tavas valodas dēļ, jo mēs paši esam dzirdējuši un zinām, ka Šis tiešām ir Tas pasaules Pestītājs, Tas Kristus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Un pēc divām dienām Viņš izgāja no turienes un nogāja uz Galileju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Jo pats Jēzus apliecināja, ka pravietis savā tēvijā netop turēts godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Kad Viņš nu nāca uz Galileju, tad tie Galileji Viņu uzņēma, jo tie visu bija redzējuši, ko Viņš svētkos Jeruzālemē bija darījis; jo tie arīdzan bija nākuši uz svētkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Tad Jēzus atkal nāca uz Kānu iekš Galilejas, kur Viņš ūdeni bija darījis par vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Un tur viens ķēniņa sulainis bija, kam dēls gulēja nevesels Kapernaūmā. Šis dzirdējis, ka Jēzus bija nācis no Jūdejas uz Galileju, nogāja pie Viņa un To lūdza, lai noietu un viņa dēlam palīdzētu, jo tas guļot uz miršanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Tad Jēzus uz viņu sacīja: “Ja jūs zīmes un brīnumus neredzat, tad jūs neticat.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Tas ķēniņa sulainis uz Viņu saka: “Kungs, nāc, pirms nekā mans dēls mirst.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jēzus uz viņu saka: “Ej, tavs dēls dzīvs.” Un tas cilvēks ticēja tam vārdam, ko Jēzus uz viņu bija sacījis, un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Un noejot viņa kalpi to sastapa un tam pasludināja un sacīja: “Tavs dēls dzīvs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Tad tas no viņiem izvaicāja to stundu, kur ar viņu bija palicis labāk. Un tie uz viņu sacīja: “Vakar ap septīto stundu drudzis viņu atstāja.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Tad tas tēvs nomanīja ap to stundu esam, kad Jēzus viņam bija sacījis: “Tavs dēls dzīvs.” Un viņš ticēja ar visu savu saimi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Šī tā otrā brīnuma zīme, ko Jēzus darīja, nākdams no Jūdejas uz Galileju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Pēc tam bija Jūdu svētki, un Jēzus gāja uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Bet Jeruzālemē pie avju vārtiem ir dīķis, ar vārdu ebrejiski Betezda, tur bija piecas istabas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Tanīs gulēja liels pulks neveselu, aklu, tizlu, nokaltušu, (kas gaidīja uz ūdens kustēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Jo savā laikā viens eņģelis nolaidās tai dīķī un to ūdeni pakustināja. Kurš tad iekāpa pirmais pēc ūdens kustināšanas, tas tapa vesels, lai gulēja kādā sērgā gulēdams.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Un tur viens cilvēks trīsdesmit un astoņus gadus bija gulējis nevesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Šo Jēzus redzēja guļam, un zinādams, ka tas ilgu laiku tur bija gulējis, Viņš uz to saka: “Vai gribi tapt vesels?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Tas neveselais Tam atbildēja: “Kungs, man nav cilvēka, kas mani iemet tai dīķī, kad tas ūdens top kustināts; un tiekams es nāku, cits jau nokāpj manā priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jēzus uz to saka: “Celies, ņem savu gultu un ej.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Un tūdaļ tas cilvēks tapa vesels un ņēma savu gultu un aizgāja. Bet tā diena bija svētdiena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Tad tie Jūdi sacīja uz to, kas bija dziedināts: “Svētdiena ir, tev nav brīv savu gultu nest.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Viņš tiem atbildēja: “Kas mani darīja veselu, Tas uz mani sacīja: ņem savu gultu un ej.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Tad tie viņam vaicāja: “Kas ir Tas tāds cilvēks, kas tev sacījis: ņem savu gultu un ej?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Bet tas, kas bija vesels palicis, nezināja, kas Tas tāds esot; jo Jēzus bija atkāpies tai ļaužu pulkā, kas tai vietā bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Pēc tam Jēzus to atrod Dieva namā un uz to saka: “Raugi, tu esi tapis vesels, neapgrēkojies vairs, ka tev nenotiek jo grūti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Tas cilvēks nogāja un tiem Jūdiem pasludināja, ka Jēzus Tas esot, kas viņu darījis veselu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Un tāpēc tie Jūdi Jēzu ienīdēja un Viņu meklēja nokaut, ka Viņš to bija darījis svētdienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Bet Jēzus tiem atbildēja: “Mans Tēvs strādā līdz šim, un Es arīdzan strādāju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Tādēļ tie Jūdi jo vairāk Viņu meklēja nokaut, ka Viņš ne vien svētdienu nesvētīja, bet arī sacīja, ka Dievs esot Viņa paša Tēvs, Sevi līdzinādams Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Tad Jēzus atbildēja un uz tiem sacīja: “Patiesi, patiesi, Es jums saku: Tas Dēls neko nevar darīt no Sevis paša, ja Tas neredz To Tēvu tā darām, jo, ko Šis dara, to arī Tas Dēls dara tāpat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Jo Tas Tēvs mīļo To Dēlu, un Tam rāda visu, ko pats dara un Tam rādīs lielākas lietas nekā šās, ka jums jābrīnās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Jo itin kā Tas Tēvs miroņus uzmodina un dara dzīvus, tāpat arī Tas Dēls dara dzīvus, kurus gribēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Jo Tas Tēvs nevienu netiesā, bet visu tiesu ir devis Tam Dēlam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Ka visiem būs To Dēlu godāt, itin kā tie To Tēvu godā; kas To Dēlu negodā, tas negodā To Tēvu, kas Viņu sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Patiesi, patiesi, Es jums saku: kas Manu vārdu dzird un Tam tic, kas Mani sūtījis, tam ir mūžīga dzīvība, un tas nenāk sodībā, bet no nāves ir iegājis dzīvībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Patiesi, patiesi, Es jums saku: tā stunda nāk un jau tagad ir, ka tie mirušie dzirdēs Dieva Dēla balsi, un kas to dzird, tie dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Jo itin kā Tam Tēvam ir dzīvība iekš Sevis paša, tāpat Viņš arī Tam Dēlam ir devis, ka Tam dzīvība ir iekš Sevis paša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Un Viņš Tam varu devis, arī tiesu turēt, tādēļ ka Tas ir Tas Cilvēka Dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Nebrīnāties par to, jo tā stunda nāk, kurā visi, kas ir kapos, Viņa balsi dzirdēs');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'Un izies ārā, tie, kas labu darījuši, pie augšāmcelšanās uz dzīvību, bet kas ļaunu darījuši, pie augšāmcelšanās uz sodību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Es neko nevaru darīt no Sevis paša; tā kā Es dzirdu, tā Es tiesāju, un Mana tiesa ir taisna; jo Es nemeklēju Savu prātu, bet Tā Tēva prātu, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Ja Es pats liecību dodu par Sevi, tad Mana liecība nav patiesīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Cits ir, kas liecību dod par Mani, un Es zinu, to liecību esam patiesīgu, ko Viņš apliecina par Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Jūs esat sūtījuši pie Jāņa, un tas patiesībai liecību devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Tomēr Es liecību neņemu no cilvēka, bet Es to saku, lai jūs topat pestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Viņš bija degoša un spīdoša svece, bet jūs mazu brīdi gribējāt līksmoties viņa gaišumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Bet Man ir lielāka liecība nekā no Jāņa. Jo tie darbi, ko Tas Tēvs Man devis darīt, šie darbi, ko Es daru, liecību dod par Mani, ka Tas Tēvs Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Un Tas Tēvs, kas Mani sūtījis, pats liecību devis par Mani; jūs Viņa balsi nekad neesat dzirdējuši, nedz Viņa ģīmi redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Un Viņa vārds nav paliekams pie jums, jo jūs Tam neticat, ko Viņš sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Meklējat rakstos, jo jums šķiet, ka tur iekšā jums ir mūžīga dzīvība, un tie ir, kas liecību dod par Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Bet jūs negribat nākt pie Manis, lai jums būtu dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Godu no cilvēkiem Es neņemu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Bet Es jūs pazīstu, ka Dieva mīlestība nav iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Es esmu nācis Sava Tēva vārdā, un jūs Mani neuzņemat; kad cits nāks sava paša vārdā, to jūs uzņemsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Kā jūs varat ticēt, cits no cita godu ņemdami? Un to godu, kas ir no tā vienīgā Dieva, to jūs nemeklējat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Nedomājiet, ka Es jūs apsūdzēšu pie Tā Tēva; tur ir viens, kas jūs apsūdz, Mozus, uz ko jūs esat cerējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Jo ja jūs Mozum ticētu, tad jūs Man arīdzan ticētu; jo viņš ir rakstījis par Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Bet ja jūs viņa rakstiem neticat, kā tad jūs Maniem vārdiem ticēsiet?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Pēc tam Jēzus aizbrauca pār Galilejas jūru pie Tiberijas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Un liels pulks ļaužu Tam gāja pakaļ, tāpēc ka tie redzēja tās brīnuma zīmes, ko Viņš darīja pie neveseliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Bet Jēzus kāpa uz to kalnu un apsēdās ar Saviem mācekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Bet Jūdu Lieldienas svētki bija tuvu klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Tad Jēzus pacēla acis un redzēja, ka daudz ļaužu pie Viņa nāca, un saka uz Filipu: “Kur pirksim maizes, ka šiem ir ko ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, '(Bet to Tas sacīja, viņu pārbaudīdams; jo pats gan zināja, ko gribēja darīt.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filips tam atbildēja: “Par divsimt sudraba grašiem maizes tiem nepietiek, ka ikviens no tiem maķenīt ņemtos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Tad viens no Viņa mācekļiem, Andrejs, Sīmaņa Pētera brālis, uz Viņu saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '“Še ir viens jauneklis, tam ir piecas miežu maizes un divas zivis; bet kas tas ir priekš tik daudz ļaudīm?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Un Jēzus sacīja: “Dariet, ka tie ļaudis apsēžas;” un tur daudz zāles bija tanī vietā. Tad apsēdās kādi piectūkstoš vīri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Un Jēzus ņēma tās maizes, pateicās un deva tiem mācekļiem, un tie mācekļi tiem, kas bija apsēdušies. Tāpat arī no tām zivīm, cik gribēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Bet kad tie bija paēduši, tad Viņš saka uz Saviem mācekļiem: “Sakrājiet atlikušās druskas, ka nekas nepazūd.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Tad tie salasīja un pildīja divpadsmit kurvjus ar druskām no tām piecām miežu maizēm, kas tiem atlika, kas bija ēduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Kad nu tie cilvēki to brīnuma zīmi redzēja, ko Jēzus bija darījis, tad tie sacīja: “Šis ir patiesi tas pravietis kam bija nākt pasaulē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Kad nu Jēzus manīja, ka tie gribēja nākt, Viņu tvert, lai par ķēniņu celtu, tad Viņš devās viens pats atkal uz to kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Un kad vakars metās, Viņa mācekļi nogāja pie jūras,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Un laivā kāpuši tie brauca pāri pār jūru uz Kapernaūmu: un jau bija palicis tumšs, un Jēzus pie tiem nebija atnācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Un jūra cēlās, stipram vējam pūšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Un vairāk nekā pusjūdzi aizirušies, tie redzēja Jēzu pa jūru staigājam un tuvu pie laivas esam. Un tie bijās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Bet Viņš uz tiem saka: “Es tas esmu, nebīstaties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Tad tie gribēja Viņu ņemt laivā, un tūdaļ tā laiva nāca tanī malā, uz ko tie dzinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Otrā dienā tie ļaudis viņpus jūras stāvēdami redzēja, ka citas laivas tur nebija, kā vien tā, kurā viņa mācekļi bija iekāpuši un ka Jēzus nebija līdz gājis ar saviem mācekļiem laivā, bet ka viņa mācekļi vieni paši bija nocēlušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Un kad nu tur citas laiviņas no Tiberijas pienāca tuvu pie tās vietas, kur tie to maizi bija ēduši, ko Tas Kungs bija svētījis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Un kad tie ļaudis redzēja, ka Jēzus tur vairs nebija, nedz Viņa mācekļi, tad tie arīdzan iekāpa laivās un nāca Kapernaūmā, Jēzu meklēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Un otrā jūras malā Viņu atraduši, tie uz Viņu sacīja: “Rabbi, kad Tu esi atnācis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jēzus tiem atbildēja un sacīja: “Patiesi, patiesi, Es jums saku: jūs Mani nemeklējat tāpēc, ka jūs brīnuma zīmes esat redzējuši, bet ka jūs esat ēduši un paēduši no tām maizēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Dzenaties ne pēc tās barības, kas zūd, bet pēc tās barības, kas paliek līdz mūžīgai dzīvošanai, ko Tas Cilvēka Dēls jums dos, jo šo Dievs Tas Tēvs ir apzieģelējis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Tad tie uz Viņu sacīja: “Ko darīsim, lai strādājam Dieva darbus?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jēzus atbildēja un uz tiem sacīja: “Šis ir tas Dieva darbs, ka jums būs ticēt uz To, ko Viņš sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Tad tie uz Viņu sacīja: “Kādu zīmi tad Tu dari, ka mēs to redzam un Tev ticam? Ko Tu dari?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Mūsu tēvi to manna ir ēduši tuksnesī, kā ir rakstīts: Viņš tiem ir devis ēst maizi no debesīm.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Tad Jēzus uz tiem sacīja: patiesi, patiesi, Es jums saku: “Mozus jums to maizi no debesīm nav devis, bet Mans Tēvs jums dod to īsteno maizi no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Jo tā ir Tā Dieva maize, kas nāk no debesīm un dod pasaulei dzīvību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Tad tie uz Viņu sacīja: “Kungs, dod mums allažiņ tādu maizi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Un Jēzus uz tiem sacīja: “Es esmu tā dzīvības maize. Kas pie Manis nāk, tas neizsalks: un kas tic uz Mani, tam neslāps nemūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Bet Es jums esmu sacījis, ka jūs Mani gan esat redzējuši, tomēr jūs neticat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Ikviens, ko Tas Tēvs Man dod, tas nāk pie Manis, un kas nāk pie Manis, to Es neizmetīšu ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Jo Es esmu no debesīm nācis, ne lai Es daru Savu prātu, bet Tā prātu, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Bet šis ir Tā Tēva prāts, kas Mani sūtījis, ka no visa tā, ko Viņš Man devis, Man neko nebūs pazaudēt, bet to uzmodināt pastara dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Un šis ir Tā prāts, kas Mani sūtījis, ka ikvienam, kas To Dēlu redz un uz Viņu tic, ir mūžīga dzīvība, un Es viņu uzmodināšu pastara dienā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Tad tie Jūdi pret Viņu kurnēja, ka Viņš bija sacījis: Es esmu tā maize, kas ir nākusi no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Un tie sacīja: “Vai Šis nav Jēzus, Jāzepa dēls, kura tēvu un māti mēs pazīstam? Kā tad Tas saka: Es esmu no debesīm nācis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Tad Jēzus atbildēja un uz tiem sacīja: “Nekurniet savā starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Neviens pie Manis nevar nākt, ja Tas Tēvs, kas Mani sūtījis, viņu nevelk, un Es viņu uzmodināšu pastara dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Praviešu rakstos ir sacīts: un tie visi būs mācīti no Dieva. Tad nu ikkatrs, kas no Tā Tēva ir dzirdējis un mācījies, tas nāk pie Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ne tā, ka jebkāds To Tēvu būtu redzējis, kā vien Tas, kas ir no Dieva; Tas To Tēvu ir redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Patiesi, patiesi, Es jums saku: kas tic uz Mani, tam ir mūžīga dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Es esmu tā dzīvības maize.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Jūsu tēvi to manna ir ēduši tuksnesī un ir nomiruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Šī ir tā maize, kas nāk no debesīm, lai, kas ēd no tās, nemirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Es esmu tā dzīvā maize, kas nākusi no debesīm; ja kas ēd no šīs maizes, tas dzīvos mūžīgi. Un tā maize, ko Es došu, ir Mana miesa, ko Es došu par pasaules dzīvību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Tad tie Jūdi savā starpā strīdējās sacīdami: “Kā Šis mums Savu miesu var dot ēst?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Tad Jēzus uz tiem sacīja: “Patiesi, patiesi, Es jums saku: ja jūs Tā Cilvēka Dēla miesu neēdat un Viņa asinis nedzerat, tad dzīvības nav iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kas Manu miesu ēd un Manas asinis dzer, tam ir mūžīga dzīvība, un Es viņu uzmodināšu pastara dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Jo Mana miesa ir patiess ēdiens un Manas asinis ir patiess dzēriens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kas Manu miesu ēd un Manas asinis dzer, tas paliek iekš Manis un Es iekš tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Itin kā Mani tas dzīvais Tēvs ir sūtījis, un Es dzīvoju caur To Tēvu: tāpat, kas Mani ēd, tas arīdzan dzīvos caur Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Šī ir tā maize, kas nākusi no debesīm, ne tā, kā mūsu tēvi to manna ir ēduši un nomiruši; kas šo maizi ēd, tas dzīvos mūžīgi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'To Viņš sacīja baznīcā, mācīdams Kapernaūmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Tad no Viņa mācekļiem daudzi, to dzirdēdami, sacīja: “Šī valoda ir grūta, kas to var ieklausīties?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Tad Jēzus pie Sevis zinādams, ka Viņa mācekļi par to kurnēja, uz tiem sacīja: “Vai tas jums ir par piedauzīšanu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Bet kad nu jūs redzētu To Cilvēka Dēlu uzkāpjam, kur Viņš papriekš bijis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Tas Gars ir, kas dara dzīvu, tā miesa neder nenieka. Tie vārdi, ko Es jums runāju, ir gars un ir dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Bet citi ir jūsu starpā, kas netic.” Jo Jēzus no iesākuma zināja, kuri tie, kas neticēja, un kurš tas, kas Viņu nodos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Un Viņš sacīja: “Tādēļ Es jums esmu sacījis, ka neviens pie Manis nevar nākt, ja tas viņam nav dots no Mana Tēva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'No tā brīža daudzi no Viņa mācekļiem atkāpās un vairs nestaigāja ar Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Tad Jēzus sacīja uz tiem divpadsmit: “Vai jūs arīdzan gribat aiziet?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Sīmanis Pēteris Viņam atbildēja: “Kungs, pie ka mēs iesim? Tev ir mūžīgas dzīvības vārdi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Un mēs esam ticējuši un atzinuši, ka Tu esi Kristus, tā dzīvā Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Tad Jēzus tiem atbildēja: “Vai Es jūs neesmu izredzējis divpadsmit? Un viens no jums ir velns.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Bet Viņš to sacīja par Jūdasu, Sīmaņa dēlu, Iskariotu. Jo pēc tas Viņu nodeva, būdams viens no tiem divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Un pēc tam Jēzus staigāja pa Galileju; jo Viņš negribēja staigāt pa Jūdeju, tāpēc ka tie Jūdi Viņu meklēja nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Un Jūdu lieveņu svētki bija tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Tad Viņa brāļi uz To sacīja: “Ej jel projām no šejienes, un noej uz Jūdu zemi, lai arī Tavi mācekļi redz Tavus darbus, ko Tu dari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Jo neviens neko nedara slepenībā, kas grib kļūt zināms. Ja Tu tādas lietas dari, tad rādies pasaulei.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Jo pat Viņa brāļi neticēja uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Tad Jēzus uz tiem saka: “Mans laiks vēl nav klāt; bet jūsu laiks ir vienmēr klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Pasaule jūs nevar ienīdēt, bet Mani viņa ienīst, jo Es liecību dodu par to, ka viņas darbi ļauni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Ejat jūs uz šiem svētkiem, Es vēl neeju uz šiem svētkiem; jo Mans laiks vēl nav nācis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Un to uz tiem sacījis, Viņš palika Galilejā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Bet kad Viņa brāļi bija aizgājuši, tad Viņš arīdzan gāja uz svētkiem, ne ļaudīm redzot, bet kā paslepeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Tad tie Jūdi Viņu meklēja svētkos un sacīja: “Kur Viņš ir?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Un tur Viņa dēļ daudz valodas bija pie tiem ļaudīm, jo citi sacīja: “Viņš ir labs;” un citi sacīja: “Nē, bet Viņš tos ļaudis pieviļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Tomēr neviens droši par Viņu nerunāja, jo tie bijās no tiem Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Bet svētku vidū Jēzus gāja Dieva namā un mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Un tie Jūdi brīnījās sacīdami: “Kā šis tos rakstus zin un tomēr tos nav mācījies?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jēzus tiem atbildēja un sacīja: “Mana mācība nav Mana, bet Tā, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Ja kas grib Viņa prātu darīt, tas atzīs, vai šī mācība ir no Dieva, jeb vai Es pats no Sevis runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kas no sevis runā, tas meklē savu paša godu; bet kas meklē Tā godu, kas Viņu sūtījis, tas ir patiesīgs, un iekš Tā nav netaisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Vai Mozus jums nav bauslību devis, un neviens no jums nedara pēc bauslības? Kam jūs meklējat Mani nokaut?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Tie ļaudis atbildēja un sacīja: “Tev ir velns. Kas Tevi meklē nokaut?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jēzus atbildēja un uz tiem sacīja: “Vienu darbu Es esmu darījis, un jūs visi brīnāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Mozus jums apgraizīšanu ir devis, (ne tā kā tā būtu no Mozus, bet no tiem tēviem,) un jūs cilvēku apgraizāt svētdienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Ja cilvēks apgraizīšanu dabū svētdienā, lai Mozus bauslība netop pārkāpta, ko jūs tad par Mani apskaistaties, ka Es svētdienā visu to cilvēku esmu darījis veselu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Nespriežat pēc tā, kas priekš acīm, bet spriežat taisnu tiesu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Tad kādi no Jeruzālemes ļaudīm sacīja: “Vai šis nav Tas, ko tie meklē nokaut?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Un redzi, Viņš droši runā, un tie uz Viņu nesaka nenieka. Vai mūsu virsnieki tagad tiešām atzinuši, ka Šis patiesi ir Tas Kristus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Bet mēs Viņu zinām, no kurienes Viņš ir; bet kad Tas Kristus nāks, tad neviens nezinās, no kurienes Tas ir.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Tad Jēzus Dieva namā mācīdams sauca un sacīja: “Jūs Mani pazīstat un zināt, no kurienes Es esmu? Bet Es neesmu nācis pats no Sevis, bet kas Mani sūtījis, Tas ir patiesīgs; To jūs nepazīstat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Bet Es To pazīstu, jo Es esmu no Viņa, un Viņš Mani sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Tad tie Viņu meklēja gūstīt; tomēr neviens rokas pie Viņa nepielika, jo Viņa stunda vēl nebija nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Bet daudz no tiem ļaudīm ticēja uz Viņu un sacīja: “Kad Kristus nāks, vai tas vairāk brīnuma zīmes darīs, nekā tās, ko Šis ir darījis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Tie farizeji dzirdēja, ka tiem ļaudīm tādas valodas bija par Viņu. Un tie farizeji un augstie priesteri sūtīja sulaiņus, lai tie Viņu gūstītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Tad Jēzus uz tiem sacīja: “Vēl mazu brīdi Es esmu pie jums un noeju pie Tā, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Jūs Mani meklēsiet un neatradīsiet, un kur Es esmu, turp jūs nevarat nonākt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Tad tie Jūdi sacīja savā starpā: “Kur Šis noies, ka mēs Viņu neatradīsim? Vai Viņš noies pie tiem, kas ir izklīduši starp Grieķiem, un Grieķus mācīs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Kas tie par vārdiem, ko Šis runā: jūs Mani meklēsiet un neatradīsiet? Un: kur Es esmu, turp jūs nevarat nonākt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Un beidzamā, tai lielā svētku dienā, Jēzus stāvēja un sauca sacīdams: “Ja kam slāpst, tas lai nāk pie Manis un dzer!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kas tic uz Mani, kā tie raksti saka, no tā miesas dzīvā ūdens straumes tecēs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Un Viņš to sacīja par to Garu, ko tiem bija dabūt, kas tic uz Viņu; jo Tas Svētais Gars vēl nebija, tāpēc ka Jēzus vēl nebija apskaidrots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Tad daudz no tiem ļaudīm šo vārdu dzirdēdami sacīja: “Šis patiesi ir tas pravietis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Citi sacīja: “Viņš ir Tas Kristus;” bet citi sacīja: “Vai Kristus nāks no Galilejas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Vai tas raksts nav sacījis, ka no Dāvida cilts un no Bētlemes pilsētiņas, kur Dāvids bija, Kristus nāks?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Tad šķelšanās cēlās starp tiem ļaudīm Viņa dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Bet kādi no tiem gribēja Viņu gūstīt, tomēr neviens rokas pie Viņa nepielika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Tad tie sulaiņi nāca pie tiem augstiem priesteriem un farizejiem, un šie uz viņiem sacīja: “Kāpēc Viņu neesat atveduši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Tie sulaiņi atbildēja: “Nemūžam cilvēks tā vēl nav runājis kā šis Cilvēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Tad tie farizeji tiem atbildēja: “Vai jūs arīdzan esat pievilti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Vai gan kāds no tiem virsniekiem jeb no tiem farizejiem uz Viņu ticējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Bet šie ļaudis, kas bauslību neprot, ir nolādēti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nikademus, kas naktī bija nācis pie Viņa, viens no tiem būdams, uz tiem sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '“Vai mūsu bauslība notiesā kādu cilvēku, ja tā papriekš par viņu nav izklausinājusi un nav dabūjusi zināt, ko viņš dara?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Tie atbildēja un uz to sacīja: “Vai tu arīdzan esi no Galilejas? Pārmeklē un raugi, ka no Galilejas neviens pravietis nav cēlies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '(Un ikviens nogāja savā namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Un Jēzus gāja uz Eļļas kalnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Un no rīta agri Viņš atkal nāca Dieva namā un visi ļaudis pie Viņa nāca, un Viņš apsēdās un tos mācīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Un tie rakstu mācītāji un farizeji pie Viņa atveda vienu sievu, kas laulības pārkāpšanā bija pieķerta; un to nostādīja tur vidū,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Un sacīja uz Viņu: “Mācītāj, šī sieva ir pieķerta pašā laulības pārkāpšanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Un mums ir pavēlēts Mozus bauslībā, tādas nomētāt ar akmeņiem. Ko tad Tu saki?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Bet to tie sacīja Viņu kārdinādami, ka dabūtu vainu, Viņu apsūdzēt. Bet Jēzus pie zemes locīdamies rakstīja ar pirkstu smiltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Un kad tie jautādami Viņam uzstāja, tad Viņš uzcēlās un uz tiem sacīja: “Kurš no jums bez grēka, tas lai met to pirmo akmeni uz viņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Un Viņš atkal locīdamies rakstīja smiltīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Bet tie, to dzirdējuši un no savas sirds apziņas pārliecināti, izgāja cits pakaļ citam, no tiem vecajiem līdz tiem pēdējiem. Un Jēzus tur palika viens pats ar to sievu, kas vidū stāvēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Un Jēzus atkal pacēlās un nevienu neredzēdams kā vien to sievu uz to sacīja: “Sieva, kur ir tavi apsūdzētāji? Vai neviens tevi nav pazudinājis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Un tā sacīja: “Neviens, Kungs!” Un Jēzus uz to sacīja: “Tad arī Es tevi nepazudinu: ej un negrēko vairs.”)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Tad Jēzus atkal uz tiem runāja sacīdams: “Es esmu tas pasaules gaišums. Kas Man iet pakaļ, tas nestaigās tumsībā, bet tam būs tas dzīvības gaišums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Tad tie farizeji uz Viņu sacīja: “Tu liecību dod par Sevi pašu, Tava liecība nav patiesīga.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jēzus atbildēja un uz tiem sacīja: “Jebšu Es liecību dodu par Sevi, tomēr Mana liecība ir patiesīga. Jo Es zinu, no kurienes Es esmu nācis un uz kurieni Es eju. Bet jūs nezināt, no kurienes nāku un uz kurieni eju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Jūs tiesājiet pēc miesas; Es netiesāju neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Un ja Es arī tiesāju, tad Mana tiesa ir taisna; jo Es neesmu viens, bet Es un Tas Tēvs, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Un arī jūsu bauslībā ir rakstīts, ka divēju cilvēku liecība ir patiesīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Es dodu liecību par Sevi, un Tas Tēvs, kas Mani sūtījis, dod liecību par Mani.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Tad tie uz Viņu sacīja: “Kur ir Tavs Tēvs?” Jēzus atbildēja: “Jūs nepazīstat nedz Mani nedz Manu Tēvu. Ja jūs Mani būtu pazinuši, tad jūs arī Manu Tēvu būtu pazinuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Šos vārdus Jēzus runāja pie Dieva šķirsta, mācīdams Dieva namā. Un neviens Viņu negūstīja, jo Viņa stunda vēl nebija nākusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Tad Jēzus atkal uz tiem sacīja: “Es noeju, un jūs Mani meklēsiet un mirsiet savos grēkos. Uz kurieni Es eju, turp jūs nevarat nākt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Tad tie Jūdi sacīja: “Vai Tas Sev pats galu darīs, ka Tas saka: uz kurieni Es eju, turp jūs nevarat nākt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Un Viņš uz tiem sacīja: “Jūs esat no tā, kas ir zemē, Es no tā, kas ir augšā; jūs esat no šīs pasaules, Es neesmu no šīs pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Tādēļ Es jums esmu sacījis ka jūs mirsiet savos grēkos. Jo ja jūs neticat, ka Es Tas esmu, tad jūs mirsiet savos grēkos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Tad tie uz Viņu sacīja: “Kas Tu tāds esi?” Un Jēzus uz tiem sacīja: “Visupirms Tas, ko arī uz jums runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Man daudz par jums jārunā un jātiesā bet kas Mani sūtījis, Tas ir patiesīgs, un ko Es no Viņa esmu dzirdējis, to Es runāju uz pasauli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Un tie nesaprata, ka Viņš uz tiem runāja par To Tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Tad Jēzus uz tiem sacīja: “Kad jūs To Cilvēka Dēlu paaugstināsiet, tad jūs sapratīsiet, ka Es tas esmu, un ka Es neko nedaru no Sevis, bet itin to runāju, ko Mans Tēvs Man ir mācījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Un kas Mani sūtījis, Tas ir ar Mani. Tas Tēvs Mani nav atstājis vienu, jo kas Viņam patīk, to Es allaž daru.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Kad Viņš to runāja, tad daudzi ticēja uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Tad Jēzus sacīja uz tiem Jūdiem, kas Viņam bija ticējuši: “Ja jūs paliekat Manā Vārdā, tad jūs patiesi esat Mani mācekļi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Un atzīsiet patiesību, un patiesība jūs atsvabinās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Tie Viņam atbildēja: “Mēs esam Ābrahāma dzimums un ne mūžam nevienam neesam kalpojuši; kā tad Tu saki: jūs tapsiet svabadi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jēzus tiem atbildēja: “Patiesi, patiesi, Es jums saku: ikviens, kas grēku dara, tas ir grēka kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Bet kalps mūžam namā nepaliek; dēls paliek mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Ja nu Tas Dēls jūs atsvabinās, tad jūs tiešām būsiet svabadi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Es zinu, ka jūs esat Ābrahāma dzimums, bet jūs Mani meklējat nokaut, jo Manam vārdam nav vietas pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Es runāju, ko Es esmu redzējis pie Sava Tēva; un jūs arīdzan darāt, ko jūs esat redzējuši pie sava tēva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Tie atbildēja un sacīja: “Mūsu tēvs ir Ābrahāms.” Jēzus uz tiem saka: “Ja jūs būtu Ābrahāma bērni, tad jūs arī darītu Ābrahāma darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Bet nu jūs Mani meklējat nokaut, cilvēku, kas jums patiesību esmu runājis, ko esmu dzirdējis no Dieva. To Ābrahāms nav darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Jūs darāt sava tēva darbus!” Tad tie uz Viņu sacīja: “Mēs maucībā neesam dzimuši. Mums ir viens vienīgs Tēvs, Dievs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Tad Jēzus uz tiem sacīja: “Ja Dievs būtu jūsu tēvs, tad jūs Mani mīlētu; jo Es esmu izgājis un nāku no Dieva; jo Es neesmu nācis no Sevis, bet Viņš Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Kādēļ tad jūs Manu valodu nesaprotat? Tādēļ ka jūs Manu mācību nevarat ieklausīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Jūs esat no tā tēva, tā velna, un sava tēva prātu jūs gribat darīt. Tas no iesākuma ir bijis slepkava un nav pastāvējis iekš patiesības; jo iekš tā nav patiesības. Kad viņš melus runā, tad viņš runā no sevis paša; jo viņš ir melkulis un melu tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Bet kad Es patiesību saku, tad jūs Man neticat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kas jūsu starpā Man jebkādu grēku var pierādīt? Bet kad Es jums patiesību saku, kam jūs Man neticat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kas ir no Dieva, tas Dieva vārdus klausa; tāpēc jūs neklausiet, ka jūs neesat no Dieva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Tad tie Jūdi atbildēja un uz Viņu sacīja: “Vai mēs pareizi nesakām, ka Tu esi Samarietis, un Tev ir velns?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jēzus atbildēja: “Man velna nav, bet Es Savu Tēvu godāju, un jūs Mani turat negodā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Es Savu godu nemeklēju, bet Viens ir, kas to meklē un tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Patiesi, patiesi, Es jums saku, kas Manu vārdu turēs, tas nāvi neredzēs ne mūžam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Tad tie Jūdi uz To sacīja: “Tagad mēs nomanām, ka Tev ir velns. Ābrahāms nomiris un tie pravieši, un Tu saki: kas Manu vārdu turēs, tas nāvi nebaudīs ne mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Vai Tu esi lielāks nekā mūsu tēvs Ābrahāms, kas nomiris? Un tie pravieši ir nomiruši. Par kādu Tu pats Sevi dari?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jēzus atbildēja: “Ja Es pats Sevi godāju, tad Mans gods nav nekas; bet Mans Tēvs Mani godā, par ko jūs sakāt, ka Tas jūsu Tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Tomēr jūs Viņu nepazīstat, bet Es Viņu pazīstu. Un kad Es sacītu, ka Es Viņu nepazīstu, tad Es būtu tāds pat melkulis, kā jūs; bet Es Viņu pazīstu, un Viņa vārdu turu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Ābrahāms, jūsu tēvs, tapa līksms, ka Manu dienu redzēšot, un viņš to redzēja un priecājās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Tad tie Jūdi uz To sacīja: “Tu vēl neesi piecdesmit gadus vecs, un Ābrahāmu esi redzējis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jēzus uz tiem sacīja: “Patiesi, patiesi, Es jums saku: pirms nekā Ābrahāms bija, Es esmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Tad tie pacēla akmeņus, mest uz Viņu. Bet Jēzus paslēpās un izgāja no Dieva nama ārā, iedams caur viņu vidu. Un tā Viņš aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Un aiziedams Viņš ieraudzīja cilvēku, kas bija neredzīgs no dzimuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Un Viņa mācekļi Viņam vaicāja sacīdami: “Rabbi, kurš ir grēkojis: vai šis, vai viņa vecāki, ka tas ir neredzīgs piedzimis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jēzus atbildēja: “Nedz šis grēkojis, nedz viņa vecāki; bet ka Dieva darbi pie viņa parādītos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Man nākas strādāt Tā darbus, kas Mani sūtījis, kamēr vēl ir diena; nāk nakts, kad neviens nevar strādāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Kamēr Es esmu pasaulē, Es esmu pasaules gaišums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'To sacījis Viņš spļāva zemē un taisīja svaidāmo no tām siekalām un svaidīja tā neredzīgā acis ar to svaidāmo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Un sacīja uz to: “Ej, mazgājies Siloāmas dīķī” (Siloāma, tas ir tulkots: sūtīts). Tad tas nogāja un mazgājās un pārnāca redzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Tad tie kaimiņi un kas viņu papriekš bija redzējuši, ka viņš bija neredzīgs, sacīja: “Vai šis nav tas, kas tur sēdēja un nabagoja?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Citi sacīja: “Viņš tas pats;” un citi: “Viņš tam līdzīgs!” Bet viņš sacīja: “Es tas esmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Tad tie uz viņu sacīja: “Kā tavas acis tapa atdarītas?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Viņš atbildēja un sacīja: “Viens cilvēks, kas top saukts Jēzus, taisīja svaidāmo un ar to svaidīja manas acis un sacīja uz mani: Ej uz Siloāmas dīķi un mazgājies. Tad es nogājis mazgājos un tapu redzīgs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Tad viņi uz to sacīja: “Kur Tas ir?” Tas saka: “Es nezinu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Tad tie to citkārt neredzīgo noveda pie tiem farizejiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Un tā bija svētdiena, kad Jēzus to svaidāmo bija taisījis un tam acis atdarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Un tad atkal tie farizeji viņam vaicāja: “Kā tas tapis redzīgs?” Un viņš uz tiem sacīja: “Viņš svaidāmas zāles uzlika uz manām acīm, un es mazgājos un redzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Tad citi no tiem farizejiem sacīja: “Šis cilvēks nav no Dieva, jo Viņš svētdienu nesvētī;” citi sacīja: “Kā gan grēcīgs cilvēks tādas brīnuma zīmes var darīt?” Un šķelšanās bija viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Un tie atkal uz to neredzīgo saka: “Ko tu par Viņu saki, ka Viņš tavas acis ir atvēris?” Un tas sacīja: “Viņš ir pravietis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Bet tie Jūdi neticēja no viņa, ka viņš bijis neredzīgs un tapis redzīgs, tiekams tie sauca tā vecākus, kas bija tapis redzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Un viņi tiem vaicāja sacīdami: “Vai šis ir jūsu dēls, par ko jūs sakāt, ka viņš neredzīgs piedzimis? Kā tad tas tagad redz?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Viņa vecāki tiem atbildēja un sacīja: “Mēs zinām, ka šis ir mūsu dēls, un ka tas neredzīgs piedzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Bet kā tas tagad redz, to nezinām, vai kas viņa acis atdarījis, to mēs nezinām. Viņš ir diezgan vecs, vaicājiet viņam, viņš pats par sevi runās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'To viņa vecāki sacīja, jo tie bijās no tiem Jūdiem; jo tie Jūdi jau bija sarunājušies, izslēgt no draudzes to, kas apliecinātu, Viņu esam Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Tādēļ viņa vecāki sacīja: “Viņš ir diezgan vecs, vaicājiet viņam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Kad tie otru reiz to cilvēku sauca, kas bijis neredzīgs, un uz to sacīja: “Dod Dievam godu, mēs zinām, ka Šis cilvēks ir grēcinieks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Tad tas atbildēja un sacīja: “Vai Viņš ir grēcinieks, to nezinu; to vien zinu, ka es biju neredzīgs un tagad redzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Un tie atkal uz viņu sacīja: “Ko Viņš tev darījis? Kā Viņš tavas acis atvēris?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Viņš tiem atbildēja: “Es jums jau esmu sacījis, un jūs neesat klausījuši. Kam jūs to atkal gribat dzirdēt? Vai arī jūs gribat palikt par Viņa mācekļiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Tad tie viņu lamāja un sacīja: “Tu esi Viņa māceklis, bet mēs esam Mozus mācekļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Mēs zinām, ka Dievs uz Mozu ir runājis; bet par šo mēs nezinām, no kurienes Viņš ir.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Tas cilvēks atbildēja un uz tiem sacīja: “Tā ir brīnišķa lieta, ka jūs nezināt, no kurienes Tas ir, un tomēr Tas manas acis atdarījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Mēs jau zinām, ka Dievs grēciniekus neklausa, bet kas ir dievbijīgs un Viņa prātu dara, to tādu Viņš klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Tas ne mūžam vēl nav dzirdēts, ka kāds ir atdarījis tāda acis, kas neredzīgs piedzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Ja Tas nebūtu no Dieva, tad Tas neko nespētu darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Tie atbildēja un uz viņu sacīja: “Tu viscaur grēkos esi piedzimis un tu mūs gribi mācīt?” Un tie viņu izdzina ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jēzus dzirdēja, ka tie to bija izdzinuši, un to atradis Viņš uz to sacīja: “Vai tu tici uz Dieva Dēlu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Tas atbildēja un sacīja: “Kungs, kurš Tas ir, lai es ticu uz Viņu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Un Jēzus uz to sacīja: “Tu Viņu esi redzējis, un kas ar tevi runā, ir Tas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Un viņš sacīja: “Kungs, es ticu,” - un Viņu pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Un Jēzus sacīja: “Uz tiesu Es esmu nācis šinī pasaulē, lai tie neredzīgie redz un tie redzīgie top akli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Un kādi no tiem farizejiem, kas pie Viņa bija, to dzirdēja un uz Viņu sacīja: “Vai tad mēs arīdzan esam akli?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jēzus uz tiem sacīja: “Kad jūs būtu akli, tad jums nebūtu grēka. Bet tagad jūs sakāt: mēs redzam; tāpēc jūsu grēks paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Patiesi, patiesi, Es jums saku: kas neieiet pa durvīm avju kūtī, bet kāpj citur kur iekšā, tas ir zaglis un slepkava.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Bet kas ieiet pa durvīm, tas ir tas avju gans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Tam tas durvju sargs atver, un tās avis klausa viņa balsi, un viņš savas avis sauc pie vārda un tās izved.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Un kad viņš savas avis izlaidis, tad tas iet viņu priekšā; un tās avis tam iet pakaļ, jo tās viņa balsi pazīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Bet svešam tās neiet pakaļ, bet bēg no tā, jo tās tā svešā balsi nepazīst.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Šo līdzību Jēzus uz tiem sacīja; bet tie nesaprata, kas tas bija, ko Viņš uz tiem runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Tad Jēzus atkal uz tiem sacīja: “Patiesi, patiesi, Es jums saku: Es esmu tās durvis pie tām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Visi, kas priekš Manis nākuši, tie bijuši zagļi un slepkavas, bet tās avis tiem nav klausījušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Es esmu tās durvis; ja kas caur Mani ieiet, tas taps svēts, un tas ieies un izies un atradīs ganības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Zaglis nenāk kā vien gribēdams zagt, žņaugt un nokaut; Es esmu nācis, ka tiem būtu dzīvība un viss papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Es esmu tas labais gans: labais gans dod Savu dvēseli par tām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Bet derēts gans, kas nav īstais gans, kam tās avis nepieder, redz vilku nākam un tās avis atstāj un bēg, un vilks tās sakampj un izklīdina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Bet tas derētais gans bēg, tāpēc ka viņš derēts, un nebēdā par tām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Es esmu tas labais gans un pazīstu Savas avis, un tās Mani pazīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Itin kā Mani Tas Tēvs pazīst, tāpat arī Es To Tēvu pazīstu; un Es dodu Savu dzīvību par tām avīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Man arī vēl citas avis, tās nav no šīs kūts. Arī tās Man būs atvest; un tās dzirdēs Manu balsi, un būs viens pats ganāmpulks, viens pats gans.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Tāpēc Tas Tēvs Mani mīl, kā Es Savu dzīvību dodu, lai Es to atkal ņemu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Neviens to neņem no Manis, bet Es to dodu no Sevis. Man ir vara, to dot, un Man ir vara, to atkal ņemt. Šo likumu Es esmu dabūjis no Sava Tēva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Tad atkal šķelšanās cēlās starp tiem Jūdiem šo vārdu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Jo daudz no tiem sacīja: “Viņam ir velns un Viņš ir traks; ko jūs Viņu klausāt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Citi sacīja: “Šie vārdi nav velna apsēsta vārdi; vai velns akliem acis var atdarīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Un Jeruzālemē bija Dieva nama iesvētīšanas svētki, un bija ziema.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Un Jēzus staigāja Dieva namā, Salamana priekšnamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Tad tie Jūdi Viņu apstāja un uz Viņu sacīja: “Cik ilgi Tu mūsu dvēseles kavē? Ja Tu esi Kristus, tad saki mums to skaidri.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jēzus tiem atbildēja: “Es jums to esmu sacījis, un jūs neticat. Tie darbi, ko Es daru Sava Tēva vārdā, šie dod liecību par Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Bet jūs neticat, jo jūs neesat no Manām avīm, kā Es jums esmu sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Manas avis Manu balsi klausa, un Es tās pazīstu, un tās Man iet pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Un Es tām dodu mūžīgu dzīvību, un tās ne mūžam neies bojā, un neviens tās neizraus no Manas rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mans Tēvs, kas Man tās devis, ir lielāks pār visiem, un neviens tās nevar izraut no Mana Tēva rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Es un Tas Tēvs, mēs esam viens.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Tad tie Jūdi atkal pacēla akmeņus, Viņu nomētāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jēzus tiem atbildēja: “Daudz labus darbus Es jums esmu rādījis no Sava Tēva; kura darba dēļ jūs Mani mētājiet ar akmeņiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Tie Jūdi Viņam atbildēja un sacīja: “Laba darba dēļ mēs Tevi nemētājam, bet zaimošanas dēļ un ka Tu cilvēks būdams pats Sevi dari par Dievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jēzus tiem atbildēja: “Vai jūsu bauslībā nav rakstīts: Es esmu sacījis, jūs esat dievi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Kad tā nu tos sauca par dieviem, uz kuriem Dieva vārds ir noticis, un to rakstu nevar atmest,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Ko tad jūs sakāt uz Mani, ko Tas Tēvs svētījis un pasaulē sūtījis: Tu Dievu zaimo; tāpēc ka Es esmu sacījis: Es esmu Dieva Dēls?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Ja Es Sava Tēva darbus nedaru, tad neticiet Man.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Bet ja Es tos daru, tad, ja nu neticat Man, tad ticat jel tiem darbiem, lai jūs atzīstat un ticat, ka Tas Tēvs ir iekš Manis, un Es iekš Viņa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Tad tie atkal Viņu meklēja gūstīt, bet Viņš izgāja no viņu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Un Viņš atkal cēlās pāri Jardānai uz to vietu, kur Jānis iesākumā kristīja, un palika tur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Un daudz pie Viņa nāca un sacīja: “Jebšu Jānis nav darījis nevienas brīnuma zīmes, tomēr viss, ko Jānis par Šo sacījis, tas ir tiesa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Un daudzi tur ticēja uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Un tur viens gulēja nevesels, Lāzarus vārdā, Betanijā, Marijas un viņas māsas Martas miestā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(Bet šī bija tā Marija, kas To Kungu ar zālēm bija svaidījusi un Viņa kājas ar saviem matiem nožāvējusi; tai brālis Lāzarus gulēja nevesels.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Tad tās māsas sūtīja pie Viņa un sacīja: “Kungs, redzi, ko Tu mīļo, tas guļ nevesels.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Un Jēzus to dzirdējis sacīja: “Šī neveselība nav uz miršanu, bet Dievam par godu, lai Dieva Dēls caur to top pagodināts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Bet Jēzus mīlēja to Martu un viņas māsu un to Lāzaru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Kad nu Viņš bija dzirdējis, to esam neveselu, tad Viņš vēl divas dienas palika tai vietā, kur Viņš bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Pēc tam Viņš saka uz Saviem mācekļiem: “Ejam atkal uz Jūdeju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Tie mācekļi uz Viņu saka: “Rabbi, tie Jūdi nesen Tevi meklēja ar akmeņiem nomētāt, un Tu atkal noej uz turieni?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jēzus atbildēja: “Vai dienai nav divpadsmit stundas? Ja kas staigā dienā, tas nepiedauzās; jo tas redz šīs pasaules gaismu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Bet ja kas staigā naktī, tas piedauzās; jo iekš tā gaismas nav.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'To Viņš sacīja, un pēc tam Viņš uz tiem saka: “Lāzarus, mūsu draugs, ir aizmidzis, bet Es eju, viņu uzmodināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Tad Viņa mācekļi sacīja: “Kungs, kad viņš aizmidzis, tad viņš taps vesels.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Bet Jēzus bija runājis par viņa nāvi; un tiem šķita, ka viņš runājot par aizmigšanu miegā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tad Jēzus uz tiem skaidri sacīja: “Lāzarus ir nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Un Es priecājos jūsu dēļ, ka Es tur neesmu bijis (ka jūs varat ticēt); bet ejam pie viņa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tad Toms, saucams dvīnis, uz tiem citiem mācekļiem sacīja: “Ejam mēs arīdzan, ka līdz ar Viņu mirstam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Tad Jēzus nogājis to atrada jau četras dienas kapā gulošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, '(Bet Betanija bija tuvu pie Jeruzālemes, kādu pusjūdzi.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Un daudz Jūdu bija nākuši pie Martas un Marijas, ka tās iepriecinātu par viņu brāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Tad Marta dzirdējusi, ka Jēzus nākot, gāja Viņam pretī, bet Marija palika mājās sēžot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Tad Marta sacīja uz Jēzu: “Kungs, ja Tu šeitan būtu bijis, tad mans brālis nebūtu miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Bet arī tagad es zinu, ka visu, ko Tu no Dieva lūgsi, Dievs Tev dos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jēzus uz to saka: “Tavs brālis celsies augšām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta uz Viņu saka: “Es zinu, ka viņš augšāmcelsies tanī augšāmcelšanā pastara dienā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jēzus uz to sacīja: “Es esmu tā augšāmcelšanās un tā dzīvība; kas tic uz Mani, jebšu tas būtu miris, tas dzīvos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Un ikviens, kas dzīvo un tic uz Mani, tas nemirs ne mūžam. Vai tu to tici?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Tā uz Viņu saka: “Tiešām, Kungs, es ticu, ka Tu esi Kristus, Dieva Dēls, kam bija nākt pasaulē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Un to sacījusi viņa nogāja un sauca Mariju, savu māsu, slepeni, sacīdama: “Mācītājs ir šeitan un tevi aicina.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Un to dzirdējusi, tā tūdaļ cēlās un nāca pie Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '(Bet Jēzus tai miestā vēl nebija ienācis, bet bija tai vietā, kur Marta Viņu sastapa.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Tad tie Jūdi, kas namā pie viņas bija un viņu iepriecināja, redzēdami, ka Marija tūdaļ cēlās un izgāja, viņai gāja pakaļ sacīdami: “Viņa iet uz kapu, tur raudāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Tad Marija, kad tā nāca, kur Jēzus bija, un Viņu redzēja, metās Viņam pie kājām un uz Viņu sacīja: “Kungs, ja Tu šeitan būtu bijis, tad mans brālis nebūtu miris.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Tad Jēzus, kad tas viņu redzēja raudam, arī tos Jūdus raudam, kas līdz ar viņu bija nākuši, garā aizgrābts, noskuma pie Sevis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'Un sacīja: “Kur jūs viņu esat nolikuši?” Tie uz Viņu saka: “Kungs, nāc un redzi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jēzus raudāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Tad tie Jūdi sacīja: “Redzi, kā tas Viņu ir mīlējis!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Bet citi no tiem sacīja: “Vai Tas, kas tā neredzīgā acis atvēris, nevarēja darīt, ka arī šis nebūtu nomiris?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Tad Jēzus atkal sirdī aizgrābts nāk pie kapa; bet tas bija alā, un akmens gulēja priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jēzus saka: “Noceļat to akmeni.” Marta, tā nomirušā māsa, uz Viņu saka: “Kungs, viņam jau smaka; viņš jau četras dienas ir gulējis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jēzus uz to saka: “Vai Es tev neesmu sacījis: ja tu ticēsi, tad tu redzēsi Dieva godību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Tad tie to akmeni cēla, kur tas mironis bija nolikts, un Jēzus pacēla acis uz augšu un sacīja: “Tēvs, Es Tev pateicos, ka Tu Mani esi paklausījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Bet Es zinu, ka Tu allažiņ Mani klausi; bet to ļaužu dēļ, kas apkārt stāv, Es to saku, lai tie tic, ka Tu Mani esi sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Un to sacījis Viņš stiprā balsī sauca: “Lāzaru, nāc ārā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Tad tas mirušais izgāja, pie kājām un rokām saistīts ar autiem, un viņa vaigs bija aptīts ar sviedru autu. Un Jēzus uz tiem saka: “Atraisiet viņu, un lai viņš staigā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Tad daudzi no tiem Jūdiem, kas pie Marijas bija nākuši un redzējuši, ko Jēzus darījis, ticēja uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Bet citi no tiem nogāja pie tiem farizejiem un tiem sacīja, ko Jēzus bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Tad tie augstie priesteri un farizeji sapulcināja to augsto tiesu un sacīja: ko darīsim? Jo Šis cilvēks dara daudz brīnuma zīmes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Ja Viņu tā palaidīsim, tad visi uz Viņu ticēs, un tad Romieši nāks un mums atņems gan zemi, gan ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Un viens no tiem, Kajafas, tanī gadā augstais priesteris būdams, uz tiem sacīja: “Jūs nezināt neko,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Un jūs neapdomājat, ka mums ir labāki, ka viens cilvēks mirst par tiem ļaudīm, nekā visa tauta pazūd.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Bet viņš to nesacīja no sevis paša, bet tanī gadā augstais priesteris būdams, viņš ka pravietis runāja, ka Jēzum bija mirt par to tautu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'Un ne par to tautu vien, bet lai Viņš tos izklīdušos Dieva bērnus kopā sapulcinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'No tās dienas tie sarunājās, Viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Tad Jēzus droši vairs nestaigāja starp tiem Jūdiem, bet no turienes aizgāja uz to vidu tuvu pie tuksneša, uz to pilsētu vārdā Efraīm, un tur Viņš palika ar Saviem mācekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Bet Jūdu Lieldiena bija tuvu un daudzi no tā vidus nogāja priekš Lieldienas uz Jeruzālemi, ka tie šķīstītos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Tad tie Jēzu meklēja un Dieva namā stāvēdami savā starpā runāja: “Kā jums šķiet? Vai Viņš gan uz svētkiem nenāks?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Bet tie augstie priesteri un farizeji bija devuši pavēli, ja kas zinātu, kur Viņš esot, lai tas dotu ziņu, ka tie Viņu tvertu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jēzus nu sešas dienas priekš Lieldienas nāca uz Betaniju, kur Lāzarus bija, kas bija miris, un ko Viņš uzmodinājis no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Tad tie Viņam tur mielastu sataisīja, un Marta kalpoja; un Lāzarus bija viens no tiem, kas ar Viņu pie galda sēdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Bet Marija, vienu mārciņu ļoti dārgas un it tīras nardu eļļu ņēmusi, svaidīja Jēzus kājas un žāvēja Viņa kājas ar saviem matiem. Un tas nams tapa pilns no tās zāļu smaržas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Tad viens no Viņa mācekļiem, Jūdas Sīmaņa dēls Iskariots, kas pēc tam Viņu nodeva, saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '“Kādēļ šī nardu eļļa nav pārdota par trīs simt grašiem, un tas nav dots nabagiem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Bet to viņš nesacīja, tāpēc ka viņam par nabagiem rūpēja, bet tāpēc ka viņš bija zaglis un to maku turēja, un nesa, kas tapa dots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Tad Jēzus sacīja: “Laid viņu mierā, viņa to uz Manu bēru dienu ir pataupījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Jo nabagi ir vienmēr pie jums, bet Es neesmu vienmēr pie jums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Tad liels pulks Jūdu ļaužu nomanīja Viņu tur esam, un nāca ne vien Jēzus dēļ, bet ka tie arī redzētu Lāzaru, ko Viņš bija uzmodinājis no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Un tie augstie priesteri sarunājās, arī Lāzaru nokaut;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Jo viņa dēļ daudz Jūdu nogāja un ticēja uz Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Otrā dienā liels ļaužu pulks uz svētkiem nācis, dzirdēdams, ka Jēzus nākot uz Jeruzālemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Ņēma zarus no palmu kokiem un izgāja Viņam pretī un kliedza: “Ozianna, slavēts, kas nāk Tā Kunga Vārdā, tas Israēla Ķēniņš.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Un jaunu ēzeli atradis, Jēzus sēdās virsū, tā kā rakstīts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '“Nebīsties, tu Ciānas meita, redzi, tavs Ķēniņš nāk, sēdēdams uz ēzeļa kumeļa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Bet to Viņa mācekļi no iesākuma nesaprata. Bet kad Jēzus bija pagodināts, tad tie atgādinājās, ka tas par Viņu bija rakstīts, un ka tie Viņam to bija darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Jo tie ļaudis, kas pie Viņa bija, apliecināja, ka Viņš Lāzaru bija izsaucis no kapa un to uzmodinājis no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Tādēļ arīdzan tie ļaudis Viņam pretī gāja, kad tie bija dzirdējuši, ka Viņš šo brīnuma zīmi bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Tad tie farizeji savā starpā sacīja:”Jūs redzat, ka jūs neko nespējat! Redzi, visa pasaule Viņam iet pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Un tur bija kādi Grieķi no tiem, kas uz svētkiem bija nākuši, Dievu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Šie gāja pie Filipa, kas bija no Betsaidas iekš Galilejas, un viņu lūdza sacīdami: “Kungs, mēs gribam Jēzu redzēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filips nāk un to saka Andrejam, un Andrejs un Filips to saka Jēzum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Bet Jēzus tiem atbildēja sacīdams: “Tā stunda ir nākusi, ka Tas Cilvēka Dēls top pagodināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Patiesi, patiesi, Es jums saku: ja tas kviešu grauds neiekrīt zemē un nenomirst, tad tas paliek viens pats; bet ja viņš nomirst, tad tas nes daudz augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kas savu dzīvību tur mīļu, tas to pazaudēs; un kas savu dzīvību šinī pasaulē ienīst, tas to paturēs uz mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Ja kas Man grib kalpot, tas lai staigā Man pakaļ; un kur Es būšu, tur arī Mans kalps būs; un ja kas Man kalpos, to Mans Tēvs cienīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Tagad Mana dvēsele ir satriekta. Un ko lai es saku? Tēvs, izpestī Mani no šās stundas! Bet tāpēc Es uz šo stundu esmu nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Tēvs, pagodini Savu vārdu.” Tad balss no debesīm nāca: “Es To esmu pagodinājis un To atkal pagodināšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Tad tie ļaudis, kas tur stāvēja, to dzirdējuši, sacīja: “Pērkons rūca!” Citi sacīja: “Eņģelis ar Viņu runājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jēzus atbildēja un sacīja: “Šī balss ne Manis, bet jūsu dēļ ir notikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Tagad ir šīs pasaules tiesa; tagad šīs pasaules virsnieks taps izmests ārā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Un Es, kad Es no zemes būšu paaugstināts, Es visus vilkšu pie Sevis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Bet to Viņš sacīja zīmēdams, kādā nāvē Viņam bija mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Tad tie ļaudis Viņam atbildēja: “Mēs no bauslības esam dzirdējuši, ka Kristum būs palikt mūžīgi, un kā Tu saki, ka Tam Cilvēka Dēlam būs tapt paaugstinātam? Kurš ir šis Cilvēka dēls?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Tad Jēzus uz tiem sacīja: “Gaišums vēl mazu brīdi pie jums ir. Staigājiet, kamēr jums vēl ir gaišums, ka tumsība jūs neaizņem. Un kas tumsībā staigā, tas nezina, uz kurieni tas iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Ticait uz to gaišumu, kamēr jums vēl ir tas gaišums, ka jūs paliekat par gaismas bērniem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'To Jēzus runāja un aizgāja un no tiem paslēpās. Un jebšu Viņš tik daudz brīnuma zīmes viņu priekšā bija darījis, tomēr tie neticēja uz Viņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Ka pravieša Jesajas vārds piepildītos, ko viņš ir sacījis: “Kungs, kas mūsu sludināšanai ticējis, un kam Tā Kunga elkonis parādīts?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Tāpēc tie nevarēja ticēt, ka Jesaja atkal ir sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '“Viņš viņu acis ir aptumšojis un viņu sirdis apcietinājis, ka tie ar acīm neredz un sirdī nesaprot un neatgriežas, ka Es tos dziedinātu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'To Jesaja sacīja, kad tas Viņa godību redzēja un par Viņu runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Tomēr arī daudz no tiem virsniekiem ticēja uz Viņu, bet to farizeju dēļ viņi to neizteica, ka netaptu izslēgti no draudzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Jo tie godu pie cilvēkiem vairāk mīlēja nekā godu pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Un Jēzus sauca un sacīja: “Kas tic uz Mani, tas netic uz Mani, bet uz To, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Un kas Mani redz, tas redz To, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Es, tas gaišums, esmu nācis pasaulē, lai ikkatrs, kas tic uz Mani, nepaliek tumsībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Un ja kas Manus vārdus dzird un netic, tad Es to netiesāju, jo Es neesmu nācis, pasauli tiesāt, bet pasauli atpestīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kas Mani nicina un Manus vārdus nepieņem, tam ir, kas viņu tiesā: tas vārds, ko Es esmu runājis, tas viņu tiesās pastara dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Jo Es no Sevis neesmu runājis, bet Tas Tēvs, kas Mani sūtījis, tas Man pavēlējis, ko lai Es saku, un ko lai Es runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Un Es zinu, ka Viņa pavēle ir mūžīga dzīvošana. Tāpēc, ko Es runāju, to Es tā runāju, kā Man Tas Tēvs ir sacījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Un priekš Lieldienas svētkiem Jēzus zinādams, ka Viņa laiks bija nācis, no šīs pasaules iet pie Tā Tēva, tā kā Viņš mīlējis tos savējos, kas bija pasaulē, tā Viņš tos mīlēja līdz galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Un vakariņu ēdot, (kad jau velns Jūdasam Iskariotam, Sīmaņa dēlam, sirdī bija iedevis, Viņu nodot),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jēzus, zinādams, ka Tas Tēvs Viņam visas lietas bija devis rokās, un ka Viņš nācis no Dieva un aizies pie Dieva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Cēlās no vakariņa, novilka savus svārkus un priekšautu ņēmis ar to apsējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Pēc Viņš ūdeni lej traukā un iesāka tiem mācekļiem kājas mazgāt un tās žāvēt ar to priekšautu, ar ko Viņš bija apsējies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Tad Viņš nāk pie Sīmaņa Pētera. Tas uz Viņu saka: “Kungs, vai Tu man kājas mazgāsi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jēzus atbildēja un uz to sacīja: “Ko Es daru, to tu tagad nezini, bet pēc tu to sapratīsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Tad Pēteris uz Viņu saka: “Nemūžam Tev nebūs manas kājas mazgāt.” Jēzus tam atbildēja: “Ja Es tevi nemazgāšu, tad tev nebūs daļas ar Mani.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Sīmanis Pēteris uz Viņu saka: “Kungs, nevien manas kājas, bet arī rokas un galvu!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jēzus uz to saka: “Kas ir mazgāts, tam nevajag kā vien kājas mazgāt, bet viņš ir viscaur šķīsts. Jūs arī esat šķīsti, bet ne visi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Jo Viņš Savu nodevēju gan zināja; tāpēc Viņš sacīja: “Jūs neesat visi šķīsti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Kad Tas nu viņu kājas bija mazgājis, tad Viņš ņēma savus svārkus un atkal nosēdās un uz tiem sacīja: “Vai jūs zināt, ko Es jums esmu darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Jūs Mani saucat par Mācītāju un par Kungu, un tas pareizi runāts, jo Es tas esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Ja tad Es, jūsu Kungs un Mācītājs, jūsu kājas esmu mazgājis, tad arī jums būs cits citam kājas mazgāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Jo Es jums priekšzīmi esmu devis, lai jūs darāt, kā Es jums esmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Patiesi, patiesi, Es jums saku: kalps nav lielāks par savu kungu, nedz, kas sūtīts, lielāks par to, kas viņu sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Ja jūs tā zināt, svētīgi jūs esat, kad jūs to darāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Es nerunāju par jums visiem; Es zinu, kurus Es esmu izredzējis; bet lai tas raksts piepildās: kas ar Mani maizi ēd, tas Mani min ar kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Tagad Es jums to saku, pirms tas notiek, lai, kad tas notiek, jūs ticat, ka Es Tas esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Patiesi, patiesi, Es jums saku: kas uzņem, ja Es kādu sūtīšu, tas Mani uzņem; un kas Mani uzņem, tas uzņem To, kas Mani sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'To sacījis, Jēzus garā aizgrābts liecināja un sacīja: “Patiesi, Es jums saku, viens no jums Mani nodos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Tad tie mācekļi cits uz citu skatījās, nezinādami, par kuru Tas runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Un viens no viņa mācekļiem sēdēja pie Jēzus krūtīm, to Jēzus mīlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Tad Sīmanis Pēteris šim met ar acīm, lai vaicā, kurš tas esot, par ko Viņš runā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Un tas pielocīdamies pie Jēzus krūtīm uz Viņu saka: “Kungs, kurš tas ir?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jēzus atbild: “Tas ir tas, kam Es to kumosu iemērktu došu;” tad Viņš iemērca to kumosu un dod to Jūdasam, Sīmaņa dēlam, Iskariotam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Un pēc tā kumosa tad sātans iegāja iekš tā. Tad Jēzus uz to saka: “Ko tu dari, to dari drīz.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Bet neviens no tiem, kas tur klāt sēdēja, nesaprata, kāpēc Viņš tam to sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Jo kādiem šķita, tāpēc ka Jūdasam tas maks bija, ka Jēzus uz viņu saka: pērc, ko mums uz svētkiem vajag; vai lai viņš nabagiem ko dotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Tad nu, to kumosu ņēmis, viņš izgāja tūdaļ ārā, un nakts bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Kad viņš nu bija izgājis, tad Jēzus saka: “Tagad Tas Cilvēka Dēls ir pagodināts, un Dievs ir pagodināts iekš Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Ja Dievs ir pagodināts iekš Viņa, tad arī Dievs Viņu pagodinās iekš Sevis paša un Viņu drīz pagodinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Bērniņi, Es vēl mazu brīdi esmu pie jums. Jūs Mani meklēsiet, un kā Es tiem Jūdiem esmu sacījis: uz kurieni Es eju, tur jūs nevarat nākt; tā Es jums tagad saku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Jaunu bausli Es jums dodu, ka jūs cits citu mīlējāt, itin kā Es jūs esmu mīlējis, ka arī jūs cits citu mīlējiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Pie tam visi nomanīs, ka jūs esat Mani mācekļi, ja jums ir mīlestība savā starpā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Sīmanis Pēteris uz Viņu saka: “Kungs, kurp Tu ej?” Jēzus tam atbildēja: “Kur Es eju, tur tu tagad Man nevari nākt pakaļ, bet pēcgalā tu Man nāksi pakaļ.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pēteris uz Viņu saka: “Kungs, kāpēc es tagad Tev nevaru iet pakaļ? Savu dzīvību es par Tevi nodošu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jēzus tam atbildēja: “Vai tu par Mani savu dzīvību nodosi? Patiesi, patiesi, Es tev saku: gailis nedziedās, pirms tu trīskārt Mani neaizliegsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Jūsu sirds lai neizbīstas! Ticat uz Dievu un ticat uz Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Mana Tēva namā ir daudz dzīvokļu. Kad tas tā nebūtu, tad Es jums to būtu sacījis. Es noeju, jums vietu sataisīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Un kad Es būšu nogājis un jums vietu sataisījis, tad Es gribu atkal atnākt un jūs ņemt pie Sevis, lai jūs esat, kur Es esmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Un kurp Es noeju, to jūs zināt, un to ceļu jūs arī zināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Toms uz to saka: “Kungs, mēs nezinām, kurp Tu ej; kā tad mēs to ceļu varam zināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jēzus uz to saka: “Es esmu tas ceļš un tā patiesība un tā dzīvība; neviens nenāk pie Tā Tēva, kā vien caur Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Kad jūs Mani būtu pazinuši, tad jūs arī būtu pazinuši Manu Tēvu, un no šī laika jūs Viņu pazīstat un Viņu esat redzējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filips uz Viņu saka: “Kungs, rādi mums To Tēvu, tad mums pietiek.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jēzus uz to saka: “Tik ilgi Es pie jums esmu, un tu Mani nepazīsti? Filip, kas Mani redz, tas redz To Tēvu. Kā tad tu saki: rādi mums To Tēvu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Vai tu netici, ka Es esmu iekš Tā Tēva, un Tas Tēvs ir iekš Manis? Tos vārdus, ko Es uz jums runāju, tos Es nerunāju no Sevis; bet Tas Tēvs, kas ir iekš Manis, Tas dara tos darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Ticiet Man, ka Es esmu iekš Tā Tēva un Tas Tēvs iekš Manis; ja ne, tad jel ticiet Man to darbu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Patiesi, patiesi, Es jums saku: kas tic uz Mani, tas arīdzan tos darbus darīs, ko Es daru, un darīs lielākus nekā šos; jo Es eju pie Sava Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Un ko jūs lūgsiet Manā Vārdā, to Es gribu darīt, lai Tas Tēvs top godāts iekš Tā Dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Kad jūs ko lūgsiet Manā Vārdā, to Es darīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Ja jūs Mani mīlat, tad turiet Manus baušļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Un Es To Tēvu lūgšu, un Tas jums dos citu iepriecinātāju, lai Tas pie jums paliek mūžīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'To patiesības Garu, ko pasaule nevar dabūt, jo tā Viņu neredz, nedz Viņu pazīst; bet jūs Viņu pazīstat, jo Tas paliek pie jums un būs iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Es jūs nepametīšu bāriņus, Es atkal nāku pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Vēl mazs brīdis, tad pasaule Mani vairs neredzēs, bet jūs Mani redzēsiet, jo Es dzīvoju un jums būs dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Tajā dienā jūs atzīsiet, ka Es esmu iekš Sava Tēva, un jūs iekš Manis un Es iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kam Mani baušļi ir, un kas tos tur, tas Mani mīl, un kas Mani mīl, tas taps mīlēts no Mana Tēva; un Es to mīlēšu un tam parādīšos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Jūda (ne tas Iskariots) uz Viņu saka: “Kungs, kas tas ir, ka Tu mums parādīsies un ne pasaulei?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jēzus atbildēja un uz to sacīja: “Ja kas Mani mīl, tas Manu vārdu turēs, un Mans Tēvs to mīlēs, un Mēs pie tā nāksim un mājas vietu pie tā darīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kas Mani nemīl, tas Manus vārdus netur, un tas vārds, ko jūs dzirdat, nav Mans, bet Tā Tēva, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'To Es jums esmu sacījis, vēl pie jums būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Bet tas iepriecinātājs, Tas Svētais Gars, ko Tas Tēvs sūtīs Manā Vārdā, tas jums mācīs visas lietas un jums atgādinās visu to, ko Es jums esmu sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Mieru Es jums atstāju; Savu mieru Es jums dodu, - ne tā, kā pasaule dod, Es jums dodu. Jūsu sirds lai neiztrūcinājās un lai neizbīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Jūs esat dzirdējuši, ka Es jums esmu sacījis: Es noeju un atkal atnāku pie jums, kad jūs Mani mīlētu, tad jūs priecātos, ka Es esmu sacījis: Es noeju pie Tā Tēva. Jo Tas Tēvs ir lielāks nekā Es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Un tagad Es jums esmu sacījis, pirms tas notiek, lai jūs ticat, kad tas notiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Es joprojām daudz vairs nerunāšu ar jums, jo šīs pasaules virsnieks nāk un nenieka nespēj pār Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Bet lai pasaule atzīst, ka Es To Tēvu mīlēju un daru tā, kā Man Tas Tēvs pavēlējis: ceļamies un ejam no šejienes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Es esmu tas īstenais vīna koks, un Mans Tēvs ir tas vīna dārznieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Ikvienu zaru pie Manis, kas augļus nenes, to Viņš noņem, un ikvienu, kas augļus nes, to Viņš šķīsta, lai tas jo vairāk augļus nes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Jūs tagad esat šķīsti tā vārda dēļ, ko Es uz jums esmu runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Paliekat iekš Manis, un Es iekš jums. Itin kā zars nevar augļus nest no sevis, ja tas nepaliek iekš vīna koka; tā arī jūs ne, ja jūs nepaliekat iekš Manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Es esmu tas vīna koks, jūs tie zari; kas paliek iekš Manis un Es iekš viņa, tas nes daudz augļus; jo bez Manis jūs nenieka nespējat darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Ja kas nepaliek iekš Manis, tas ir izmests, tā kā kāds zars, un ir sakaltis; un tie top sakrāti un ugunī iemesti un sadedzināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Ja jūs paliekat iekš Manis, un Mani vārdi paliek iekš jums, tad jūs lūgsiet, ko gribēdami, un tas jums notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Iekš tā Mans Tēvs ir pagodināts, ka jūs nesat daudz augļus un topat Mani mācekļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Itin kā Tas Tēvs Mani mīlējis, tā Es arīdzan jūs esmu mīlējis; paliekat iekš Manas mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Ja jūs Manus baušļus turēsiet, tad jūs paliksiet iekš Manas mīlestības, itin kā Es Sava Tēva baušļus esmu turējis un palieku iekš Viņa mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'To Es jums esmu runājis, lai Mans prieks paliek iekš jums, un jūsu prieks top pilnīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Šis ir Mans bauslis, ka jūs viens otru mīlējāt, itin kā Es jūs esmu mīlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Nevienam nav lielāka mīlestība nekā šī, kad kāds savu dzīvību nodod par saviem draugiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Jūs esat Mani draugi, ja jūs darāt, ko Es jums pavēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Es jūs vairs nesaucu par kalpiem, jo kalps nezina, ko viņa kungs dara; bet Es jūs esmu saucis par draugiem, jo visu, ko esmu dzirdējis no Sava Tēva, to Es jums esmu darījis zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Jūs Mani neesat izredzējuši, bet Es jūs esmu izredzējis un jūs iecēlis, ka jums būs noiet un augļus nest un ka jūsu augļiem būs palikt, ka Es jums to dodu, ko jūs lūgsiet no Tā Tēva Manā Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'To Es jums pavēlu, ka jūs mīlētu cits citu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Ja pasaule jūs ienīst, tad ziniet, ka tā Mani papriekš ienīdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Ja jūs būtu no pasaules, tad pasaule mīlētu, kas viņai pieder; bet kad jūs neesat no pasaules, bet Es jūs esmu izredzējis no pasaules, tāpēc pasaule jūs ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Pieminiet Manu vārdu, ko Es jums esmu sacījis: kalps nav lielāks nekā viņa kungs. Ja tie Mani vajājuši, tad tie arī jūs vajās. Ja tie Manu vārdu turējuši, tad tie arī jūsu vārdu turēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Bet tie jums to visu darīs Mana Vārda dēļ, tāpēc ka tie To nepazīst, kas Mani sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Kad Es nebūtu nācis, nedz uz tiem runājis, tad tiem nebūtu grēka, bet nu tiem nav aizbildināšanās par savu grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kas Mani ienīst, tas ienīst arī Manu Tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Kad Es tos darbus viņu priekšā nebūtu darījis, ko cits neviens nav darījis, tad tiem nebūtu grēka. Bet tagad tie tos ir redzējuši un ir ienīdējuši gan Mani, gan Manu Tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Bet lai tas vārds piepildās, kas rakstīts viņu bauslībā: tie Mani velti ienīdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Bet kad tas Iepriecinātājs nāks, ko Es jums sūtīšu no Tā Tēva, (tas patiesības Gars, kas iziet no Tā Tēva), Tas liecību dos par Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Un jūs arī liecību dosiet, jo jūs esat pie Manis no iesākuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'To Es jums esmu sacījis, lai jūs neņemat apgrēcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Tie jūs izslēgs no draudzes; un nāk laiks, ka tas, kas jūs nokaus, domās, ar to Dievam kalpojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Un to tie darīs, tāpēc ka tie nav atzinuši nedz Manu Tēvu nedz Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Bet to Es jums esmu sacījis tāpēc, lai, kad tas laiks būs nācis, jūs pieminat, ka Es jums to esmu sacījis. Bet to Es no iesākuma jums neesmu sacījis, tāpēc ka Es biju pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Bet nu Es noeju pie Tā, kas Mani sūtījis, un neviens no jums Mani nejautā: kurp Tu ej?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Bet kad Es to uz jums esmu runājis, tad jūsu sirds ir palikusi pilna noskumšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Bet Es jums saku patiesību: tas jums par labu, ka Es noeju; jo, kad Es nenoeju, tad tas Iepriecinātājs nenāks pie jums; bet kad Es noiešu, tad Es To pie jums sūtīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Un kad Tas būs nācis, Tas pārliecinās pasauli par grēku, par taisnību un par sodu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Par grēku, ka tie netic uz Mani;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Par taisnību, ka Es eju pie Tā Tēva, un jūs Mani vairs neredzēsiet;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Par sodu, ka šīs pasaules kungs ir notiesāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Man vēl daudz jums jāsaka, bet tagad jūs to nevarat panest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Bet kad Viņš, Tas Patiesības Gars, nāks, Tas jūs vadīs uz visu patiesību; jo Viņš no Sevis paša nerunās, bet ko Tas dzirdēs, to Tas runās un nākošas lietas jums pasludinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Tas Mani pagodinās, jo no Manis Viņš ņems un jums to pasludinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Viss, kas Tam Tēvam ir, tas ir Mans, tāpēc Es esmu sacījis: Viņš ņems no Manis un jums pasludinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Par mazu brīdi, tad jūs Mani vairs neredzēsiet, un atkal par mazu brīdi, tad jūs Mani redzēsiet,” - jo Es eju pie Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Tad kādi no Viņa mācekļiem sacīja savā starpā: “Kas tas ir, ko Viņš saka: par mazu brīdi, tad jūs Mani neredzēsiet, un atkal par mazu brīdi, tad jūs Mani redzēsiet;” un: “Es eju pie Tā Tēva?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Un tie sacīja: “Kas tas ir, ko Viņš saka: par mazu brīdi? Mēs nezinām, ko Viņš saka!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Tad Jēzus nomanīja, ka tie Tam gribēja jautāt, un uz tiem sacīja: “Par to jūs apjautājaties savā starpā, ka Es esmu sacījis: par mazu brīdi jūs Mani neredzēsiet, un atkal par mazu brīdi jūs Mani redzēsiet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Patiesi, patiesi, Es jums saku: jūs raudāsiet un vaidēsiet, un pasaule priecāsies; bet jūs noskumsiet; - tomēr jūsu noskumšana paliks par prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Kad sieva dzemdē, tad tā noskumusi, jo viņas stunda nākusi; bet kad tai tas bērns dzimis, tad viņa tās sāpes vairs nepiemin tās līksmības dēļ, ka cilvēks dzimis pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Tā arī jūs tagad esat noskumuši, bet Es jūs atkal redzēšu, un jūsu sirds līksmosies, un jūsu prieku neviens no jums neatņems. Un tanī dienā jūs Man nenieka nejautāsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Patiesi, patiesi, Es jums saku: ko vien jūs Tam Tēvam lūgsiet Manā Vārdā, to Viņš jums dos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Līdz šim jūs neko neesat lūguši Manā Vārdā; lūdziet, tad jūs ņemsiet, lai jūsu līksmība ir pilnīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'To Es uz jums esmu runājis caur līdzībām, bet laiks nāk, kad Es ar jums vairs nerunāšu caur līdzībām, bet jums skaidri pasludināšu par To Tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Tajā dienā jūs lūgsiet Manā Vārdā; un Es jums nesaku, ka Es To Tēvu lūgšu jūsu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Jo pats Tas Tēvs jūs mīl, tāpēc ka jūs Mani mīlējuši un ticējuši, ka Es esmu izgājis no Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Es esmu izgājis no Tā Tēva un nācis šinī pasaulē; atkal Es atstāju šo pasauli un eju pie Tā Tēva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Tad Viņa mācekļi uz To sacīja: “Redzi, tagad Tu runā skaidri un nesaki nekādu līdzību');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Tagad mēs zinām, ka Tu visu zini, un nevienam nevajag Tevi jautāt; tāpēc mēs ticam, ka Tu esi izgājis no Dieva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Tad Jēzus tiem atbildēja: “Tagad jūs ticat?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Redzi, tas laiks nāk un jau ir nācis, ka jūs izklīdīsiet, ikviens uz savu vietu, un Mani pametīsiet vienu pašu. Un Es neesmu viens, jo Tas Tēvs ir ar Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'To Es uz jums esmu runājis, lai jums miers būtu iekš Manis. Pasaulē jums būs bēdas; bet turat drošu prātu, Es pasauli esmu uzvarējis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'To Jēzus runāja un pacēla Savas acis uz debesīm un sacīja: “Tēvs, tā stunda ir nākusi; pagodini Savu Dēlu, lai arī Tavs Dēls Tevi pagodina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Itin kā Tu Viņam esi devis varu pār visu miesu, lai Viņš visiem tiem, ko Tu Viņam esi devis, dotu mūžīgu dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Bet šī ir tā mūžīgā dzīvība, ka viņi Tevi atzīst, to vienīgo patieso Dievu, un To, ko Tu esi sūtījis, Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Es Tevi esmu pagodinājis virs zemes, Es esmu padarījis to darbu, ko Tu Man esi devis, lai Es to daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Un tagad pagodini Mani, Tu Tēvs, pie Sevis paša ar to godību, kas Man bija pie Tevis, pirms nekā pasaule bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Es Tavu Vārdu esmu darījis zināmu tiem cilvēkiem, ko Tu Man no pasaules esi devis. Tie bija Tavi, un Tu Man tos esi devis, un tie Tavu vārdu ir turējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Un tagad tie ir atzinuši, ka viss, ko Tu Man esi devis, ir no Tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Jo tos vārdus, ko Tu Man esi devis, Es tiem esmu devis; un tie tos ir pieņēmuši un patiesi atzinuši, ka Es esmu izgājis no Tevis, un ir ticējuši, ka Tu Mani esi sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Es lūdzu par tiem; Es nelūdzu par pasauli, bet par tiem, ko Tu Man esi devis, jo tie ir Tavi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Viss, kas Man pieder, tas Tev pieder; un kas Tev pieder, tas Man pieder; un Es esmu pagodināts iekš tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Un Es vairs neesmu pasaulē, bet šie ir pasaulē; un Es nāku pie Tevis. Svētais Tēvs, uzturi iekš Tava Vārda tos, ko Tu Man esi devis, lai tie ir viens, itin kā Mēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Kad Es biju pie tiem pasaulē, Es tos uzturēju Tavā Vārdā. Es esmu pasargājis tos, ko Tu Man esi devis, un neviens no tiem nav pazudis, kā tik tas pazušanas dēls, ka tas raksts taptu piepildīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Bet tagad Es nāku pie Tevis un to runāju iekš pasaules, lai Mans prieks ir pilnīgs iekš tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Es tiem Tavu Vārdu esmu devis, un pasaule tos ir ienīdējusi, tāpēc ka tie nav no pasaules, itin kā Es neesmu no pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Es nelūdzu, ka Tu tos atņemtu no pasaules, bet ka Tu tos pasargātu no tā ļaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Tie nav no pasaules, tā kā Es neesmu no pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Svētī tos iekš Tavas patiesības, Tavs Vārds ir patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Itin kā Tu Mani esi sūtījis pasaulē, tā Es arīdzan tos esmu sūtījis pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Un Es pats svētījos par viņiem, ka arī viņi būtu svētīti iekš patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Bet Es nelūdzu par šiem vien, bet arī par tiem, kas caur viņu vārdiem uz Mani ticēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Lai visi ir viens, itin kā Tu Tēvs iekš Manis un Es iekš Tevis, lai arī tie ir viens iekš Mums, lai pasaule tic, ka Tu Mani esi sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Un Es to godību, ko Tu Man esi devis, tiem esmu devis, lai tie ir viens, itin kā Mēs esam viens,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Es iekš tiem un Tu iekš Manis, ka tie ir pilnīgi viens, lai pasaule atzīst, ka Tu Mani esi sūtījis un tos mīlējis, itin kā Tu Mani esi mīlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Tēvs, Es gribu, ka, kur Es esmu, arī tie ir pie Manis, ko Tu Man esi devis, lai tie redz Manu godību, ko Tu Man esi devis, jo Tu Mani esi mīlējis priekš pasaules iesākuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Taisnais Tēvs, pasaule Tevi nav atzinusi, bet Es Tevi esmu atzinis, un šie ir atzinuši, ka Tu Mani esi sūtījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Un Es tiem Tavu Vārdu esmu darījis zināmu un darīšu zināmu, lai tā mīlestība, ar ko Tu Mani esi mīlējis, ir iekš tiem, un Es iekš tiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'To sacījis Jēzus izgāja ar Saviem mācekļiem pār Kidronas upi; tur bija dārzs, kurā Viņš un Viņa mācekļi iegāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Bet arī Jūdas, kas Viņu nodeva, zināja to vietu; jo Jēzus dažu reiz tur bija sapulcējies ar Saviem mācekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Tad Jūdas, karavīru pulku ņēmis pie sevis un sulaiņus no tiem augstiem priesteriem un farizejiem, tur nonāk ar lāpām, eļļas svecēm un kara ieročiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jēzus nu visu zinādams, kas Viņam notikšot, gāja tiem pretim un uz tiem saka: “Ko jūs meklējat?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Tie Viņam atbildēja: “Jēzu no Nacaretes.” Jēzus uz tiem saka: “Es tas esmu.” Un pie tiem stāvēja arī Jūdas, kas Viņu nodeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Kad nu Jēzus uz tiem sacīja: “Es tas esmu;” tad tie atkāpās atpakaļ un krita pie zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Tad viņš tiem atkal vaicāja: “Ko jūs meklējat?” Un tie sacīja: “Jēzu no Nacaretes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jēzus atbildēja: “Es jums esmu sacījis, ka Es tas esmu; ja tad jūs Mani meklējat, tad lieciet šos mierā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Ka tas vārds taptu piepildīts, ko Viņš bija sacījis: “Es nevienu neesmu pazaudējis no tiem, ko Tu Man esi devis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Bet Sīmanis Pēteris, kam zobens bija, to izvilcis cirta tam augstā priestera kalpam un tam nocirta labo ausi, un tā kalpa vārds bija Malkus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Tad Jēzus uz Pēteri sacīja: “Bāz savu zobenu makstīs; vai Man nebūs to biķeri dzert, ko Mans Tēvs Man ir devis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Tad tas pulks un tas virsnieks un tie Jūdu sulaiņi Jēzu saņēma un sēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Un Viņu veda papriekš pie Annasa, tas bija sievas tēvs Kajafasam, kas bija tā gada augstais priesteris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Bet Kajafas bija tas, kas tiem Jūdiem padomu bija devis, labi esot, ka viens cilvēks mirtu par to tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Un Sīmanis Pēteris un vēl otrs māceklis Jēzum gāja pakaļ, un šis māceklis tam augstam priesterim bija pazīstams un iegāja līdz ar Jēzu tā augstā priestera pilī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Bet Pēteris stāvēja ārā pie durvīm. Tad tas otrs māceklis, kas tam augstam priesterim bija pazīstams, izgāja un runāja ar to durvju sargātāju un ieveda Pēteri iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Tad tā kalpone, kas bija durvju sargātāja, saka uz Pēteri: “Vai tu arīdzan neesi viens no šī cilvēka mācekļiem?” Tas saka: “Es neesmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Un tie kalpi un sulaiņi stāvēja un uguni bija sakūruši no oglēm, jo bija auksts, un tie sildījās. Bet arī Pēteris pie tiem stāvēja un sildījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Tad tas augstais priesteris Jēzum vaicāja par Viņa mācekļiem un par Viņa mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jēzus tam atbildēja: “Es droši un skaidri esmu runājis uz pasauli, Es allaž esmu mācījis baznīcā un Dieva namā, kur visi tie Jūdi saiet, un neko neesmu runājis kaktā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Ko tu Man jautā? Jautā tiem, kas dzirdējuši, ko Es uz tiem esmu runājis; redzi, tie zin, ko Es esmu sacījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Bet Jēzum to runājot viens no tiem sulaiņiem, kas klāt stāvēja, Viņam sita vaigā un sacīja: “Vai Tu tā atbildi augstam priesterim?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jēzus tam atbildēja: “Kad Es esmu nepareizi runājis, tad pierādi, ka tas ir nepareizi; bet kad esmu pareizi runājis, kam tad tu Mani siti?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Tad Annas Viņu sūtīja saistītu pie Kajafasa, tā augstā priestera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Bet Sīmanis Pēteris stāvēja un sildījās. Tad tie uz viņu sacīja: “Vai tu arīdzan neesi viens no Viņa mācekļiem?” Tas liedzās un sacīja: “Es neesmu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Tad viens no tā augstā priestera kalpiem, radinieks tam, kam Pēteris labo ausi bija nocirtis, saka: “Vai es tevi neredzēju dārzā pie Viņa?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Tad Pēteris atkal liedzās; un tūdaļ gailis dziedāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Tad tie Jēzu veda no Kajafasa uz tiesas namu, un vēl bija agrs (rīts). Un paši neiegāja tiesas namā, ka netaptu nešķīsti, bet ka varētu ēst Lieldienas jēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Tad Pilatus pie tiem izgāja ārā un sacīja: “Ko jūs sūdzat par šo cilvēku?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Tie atbildēja un uz viņu sacīja: “Ja Šis nebūtu ļauna darītājs, tad mēs To tev nebūtu nodevuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Tad Pilatus uz tiem sacīja: “Tad ņemiet jūs Viņu un tiesājiet Viņu pēc savas bauslības.” Tad tie Jūdi uz viņu sacīja: “Mums nav brīv nevienu nonāvēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Ka Jēzus vārds taptu piepildīts, ko Viņš sacīja norādīdams, ar kādu nāvi Viņam būs mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Tad Pilatus atkal iegāja tiesas namā un Jēzu aicināja un uz To sacīja: “Vai Tu esi tas Jūdu Ķēniņš?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jēzus tam atbildēja: “Vai tu to runā pats no sevis? Jeb vai citi tev to par Mani sacījuši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus atbildēja: “Vai es esmu Jūds? Tava tauta un tie augstie priesteri Tevi man nodevuši; ko Tu esi darījis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jēzus atbildēja: “Mana valstība nav no šīs pasaules; ja Mana valstība būtu no šīs pasaules, tad Mani kalpi par to kautos, ka Es tiem Jūdiem netaptu nodots. Bet nu Mana valstība nav no tejienes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Tad Pilatus uz Viņu sacīja: “Tad Tu tomēr esi Ķēniņš?” Jēzus atbildēja: “Tu to saki, Es esmu Ķēniņš. Es tāpēc esmu dzimis un tāpēc pasaulē nācis, ka Man būs patiesību apliecināt. Ikviens, kas ir no patiesības, dzird Manu balsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilatus uz Viņu saka: “Kas ir patiesība?” Un to sacījis viņš atkal izgāja ārā pie tiem Jūdiem un uz tiem saka: “Es pie Tā nekādas vainas neatrodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Bet jums ir ieradums, ka es jums vienu atlaižu uz Lieldienu. Vai jūs nu gribat, lai es jums atlaižu to Jūdu Ķēniņu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Tad visi atkal brēca sacīdami: “Ne to, bet Barabu.” Bet Baraba bija slepkava.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tad Pilatus Jēzu ņēma un Viņu šauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Un tie karavīri nopina ērkšķu kroni un to uzlika uz Viņa galvu un Tam apvilka purpura mēteli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Un sacīja: “Esi sveicināts, Tu Jūdu Ķēniņ!” un Viņam sita vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Tad Pilatus atkal izgāja ārā un uz tiem saka: “Redziet, es jums To vedu ārā, lai jūs zināt, ka es nekādas vainas pie Tā neatrodu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Tad Jēzus izgāja ārā, to ērkšķu kroni un to purpura drēbi nesdams, un Pilatus uz tiem saka: “Redziet, kāds cilvēks!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Kad nu tie augstie priesteri un sulaiņi Viņu redzēja, tad tie brēca un sacīja: “Sit Viņu krustā!” Pilatus uz tiem saka: “Ņemiet jūs Viņu un sitiet Viņu krustā; jo es nekādas vainas pie Viņa neatrodu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Tad tie Jūdi viņam atbildēja: “Mums ir bauslība, un pēc mūsu bauslības Viņam būs mirt; jo Viņš pats Sevi par Dieva Dēlu darījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Kad nu Pilatus šo vārdu dzirdēja, tad viņš vēl vairāk bijās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Un atkal iegāja tiesas namā un saka uz Jēzu: “No kurienes Tu esi?” Un Jēzus viņam nekā neatbildēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Tad Pilatus uz Viņu saka: “Vai Tu ar mani nerunā? Vai Tu nezini, ka man ir vara, Tevi krustā sist un vara, Tevi palaist?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jēzus atbildēja: “Tev nebūtu nekādas varas pār Mani, ja tā tev nebūtu dota no augšienes. Tāpēc tam, kas Mani tev nodevis, ir tas lielākais grēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'No tā brīža Pilatus meklēja viņu palaist. Bet tie Jūdi brēca un sacīja: “Ja tu Šo laidīsi vaļā, tad tu neesi ķeizara draugs. Jo kas pats ceļas par ķēniņu, tas ķeizaram pretinieks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Kad nu Pilatus šo vārdu dzirdēja, tad viņš Jēzu izveda ārā un nosēdās uz soģa krēslu tai vietā, ko sauc par akmeņu bruģi, ebrejiski gabbatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Bet tā bija tā sataisāmā diena uz Lieldienu, ap sesto stundu. Un viņš uz tiem Jūdiem saka: “Redziet, jūsu Ķēniņš!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Bet tie brēca: “Nost! nost! sit To krustā.” Pilatus uz tiem saka: “Vai man jūsu Ķēniņu būs sist krustā?” Tie augstie priesteri atbildēja: “Mums nav ķēniņa, tik vien ķeizars.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tad viņš tiem To nodeva, ka To sistu krustā; un tie Jēzu ņēma un To aizveda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Un Viņš izgāja un nesa Savu krustu uz to vietu, ko sauc pieres vietu, ebrejiski Golgatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Tur tie Viņu sita krustā un līdz ar Viņu divus citus vienā un otrā pusē un Jēzu vidū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Un Pilatus rakstīja virsrakstu un to lika krusta galā, un tur bija rakstīts: Jēzus no Nacaretes, tas Jūdu Ķēniņš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Šo virsrakstu daudz Jūdu lasīja, jo tā vieta, kur Jēzus tapa krustā sists bija tuvu pie pilsētas. Un tas bija rakstīts ebrejiski, grieķiski un latiniski.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Tad tie Jūdu augstie priesteri uz Pilatu sacīja: “Neraksti: tas Jūdu Ķēniņš, bet ka Viņš sacījis: Es esmu Jūdu Ķēniņš.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus atbildēja: “Ko esmu rakstījis, to esmu rakstījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Kad nu tie karavīri Jēzu bija krustā situši, tad tie ņēma Viņa drēbes un lika četrās daļās, ikvienam karavīram vienu daļu, un arī tos svārkus. Bet tie svārki bija nešūti, no augšienes caur caurim austi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Tad tie savā starpā sacīja: “Tos nedalīsim, bet metīsim kauliņus par tiem, kam tie piederēs;” - ka tie raksti taptu piepildīti, kas saka: “Tie Manas drēbes ir izdalījuši savā starpā un kauliņus metuši par Maniem svārkiem.” Un to tie karavīri darīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Bet tur pie tā krusta stāvēja Jēzus māte un Viņa mātes māsa, Marija, Kleopas sieva, un Marija Maddaļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Kad nu Jēzus Savu māti redzēja un to mācekli, ko Viņš mīlēja, klāt stāvam, tad Viņš saka uz Savu māti: “Sieva, redzi, tavs dēls!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Pēc tam Viņš saka uz to mācekli: “Redzi, tava māte!” Un tai pašā stundā tas māceklis to ņēma pie sevis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Pēc tam Jēzus zinādams, ka jau viss bija pabeigts, lai tie raksti taptu piepildīti, saka: “Man slāpst.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Bet tur stāvēja trauks, pilns etiķa. Un tie sūkli pildīja ar etiķi un to uzdūra īzapa stiebram un Viņam sniedza pie mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Kad nu Jēzus to etiķi bija ņēmis, tad Viņš sacīja: “Tas ir piepildīts.” Un, galvu nokāris, Viņš izlaida garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Tad tie Jūdi, lai svētā dienā tās miesas nepaliktu pie krusta, tāpēc ka tā bija sataisāma diena (jo tā pati svētku diena bija īpaši liela) Pilatu lūdza, ka viņu lieli taptu salauzīti un tie taptu noņemti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Tad tie karavīri nāca un tam pirmajam salauza lielus un tam otram, kas līdz ar To bija krustā sists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Bet kad tie nāca pie Jēzus un redzēja, ka Viņš jau bija nomiris, tad tie Viņam lielus nelauza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Bet viens no tiem karavīriem Viņam sānos iedūra ar šķēpu, un tūdaļ iztecēja asinis un ūdens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Un kas to redzējis, tas to apliecinājis, un viņa liecība ir patiesīga, un viņš zin, ka viņš runā taisnību, lai arī jūs ticat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Jo tas noticis, ka tas raksts taptu piepildīts: Nevienu no Viņa kauliem nebūs salauzt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Un atkal cits raksts saka: tie redzēs To, iekš kā tie dūruši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Pēc tam Jāzeps no Arimatijas, kas bija Jēzus māceklis, bet slepeni, no tiem Jūdiem bīdamies, lūdza Pilatu, ka viņš Jēzus miesas varētu noņemt, un Pilatus to ļāva; un tas nāca un noņēma Jēzus miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Bet arī Nikademus nāca, kas citu reiz naktī bija nācis pie Jēzus, un atnesa dārgas svaidāmas zāles, mirres un alvejas sajauktas kādas simts mārciņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Tad tie Jēzus miesas ņēma, un tās ar tām zālēm ietina linu autos, kā tie Jūdi mēdz glabāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Un tanī vietā, kur Viņš bija krustā sists, bija dārzs un tanī dārzā jauns kaps, kur vēl neviens nebija ielikts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Tur tie Jēzu ielika Jūdu sataisāmas dienas dēļ, jo tas kaps bija tuvu klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Pirmā nedēļas dienā rīta agrumā, kad vēl bija tumšs, Marija Maddaļa nāk pie kapa un redz to akmeni no kapa noveltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Tad tā tek un nāk pie Sīmaņa Pētera un pie tā otra mācekļa, ko Jēzus mīlēja, un uz tiem saka: “Tie To Kungu ir izņēmuši no kapa, un mēs nezinām, kur tie Viņu nolikuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Tad Pēteris un tas otrs māceklis izgāja un nāca pie kapa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Un tie divi tecēja kopā, un tas otrs tecēja priekša, čaklāki nekā Pēteris, un nāca papriekš pie kapa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Un pieliekdamies viņš redzēja tos linu autus tur noliktus, tomēr negāja iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Tad arī Sīmanis Pēteris, tam pakaļ iedams, nāk un ieiet kapā un redz tos linu autus tur noliktus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'Un tas sviedru auts, kas ap Viņa galvu bija, nebija likts pie tiem linu autiem, bet savrup citā malā satīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Tad arī tas otrs māceklis gāja iekšā, kas papriekš bija nācis pie kapa, un redzēja un ticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Jo tie vēl nezināja tos rakstus, ka Viņam bija augšāmcelties no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Tad tie mācekļi atkal aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Un Marija stāvēja ārā kapa priekšā raudādama. Kad nu viņa raudāja, tad viņa paliecās pie kapa');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'Un redz divus eņģeļus baltās drēbēs sēžam, vienu galvgalā, otru kājgalā, kur Jēzus miesas bija gulējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Un tie uz viņu saka: “Sieva, ko tu raudi?” tā uz tiem saka: “Tie manu Kungu paņēmuši, un es nezinu, kur tie Viņu likuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Un to sacījusi viņa apgriezās un redz Jēzu stāvam, un nezināja, to esam Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jēzus uz to saka: “Sieva, ko tu raudi? Ko tu meklē?” Viņa šķizdama, ka viņš tas dārznieks, uz To saka: “Kungs, ja tu Viņu esi aiznesis, tad saki man, kur tu Viņu noliki, ka es Viņu varu dabūt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jēzus uz to saka: “Marija!” tā apgriezusies uz Viņu saka: “Rabbuni!” (Tas ir: Mācītājs.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jēzus uz to saka: “Neaizskar Mani; jo Es vēl neesmu uzbraucis pie Sava Tēva, bet noej pie Maniem brāļiem un saki tiem: Es uzbraucu pie Sava Tēva un pie jūsu Tēva, pie Sava Dieva un pie jūsu Dieva.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marija Maddaļa nāk un pasludina tiem mācekļiem, ka viņa To Kungu redzējusi, un ko Tas viņai sacījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Šai pirmā nedēļas dienā, kad vakars bija meties, kad tie mācekļi aiz aizslēgtām durvīm bija sapulcējušies, bīdamies no tiem Jūdiem, tad Jēzus nāca un iestājās viņu vidū un uz tiem saka: “Miers ar jums!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Un to sacījis, Viņš tiem rādīja Savas rokas un Savus sānus; tad tie mācekļi tapa līksmi, To Kungu redzēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Tad Jēzus atkal uz tiem sacīja: “Miers ar jums! Kā Mani Tas Tēvs ir sūtījis, tā arī Es jūs sūtu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Un to teicis, Viņš pūta uz tiem un saka: “Ņemiet To Svēto Garu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Kam jūs grēkus piedosiet, tiem tie piedoti, un kam jūs grēkus paturēsiet, tiem tie paturēti.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Bet Toms, viens no tiem divpadsmit, dvīnis saukts, nebija pie tiem, kad Jēzus nāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Tad tie citi mācekļi uz to sacīja: “Mēs To Kungu esam redzējuši.” Un viņš uz tiem sacīja: “Ja es neredzu tās naglu zīmes Viņa rokās un nelieku savu pirkstu tanīs naglu zīmēs un nelieku savu roku Viņa sānos, tad es neticēšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Un pēc astoņām dienām Viņa mācekļi atkal tur bija iekšā un Toms pie viņiem. Jēzus nāk, kad tās durvis bija aizslēgtas, un iestājās vidū starp tiem un sacīja: “Miers ar jums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Pēc tam Viņš saka uz Tomu: “Stiep šurp savu pirkstu un aplūko Manas rokas, un sniedz šurp savu roku un liec to Manos sānos, un neesi neticīgs, bet ticīgs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Toms atbildēja un uz Viņu sacīja: “Mans Kungs un mans Dievs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jēzus uz to saka: “Tāpēc ka tu Mani esi redzējis, Tom, tu tici. Svētīgi tie, kas neredz un tomēr tic.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Arī vēl daudz citas zīmes Jēzus darījis Savu mācekļu priekšā, kas nav rakstītas šinī grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Bet šīs ir rakstītas, lai jūs ticat, ka Jēzus ir Tas Kristus, Dieva Dēls, un lai jums, kad jūs ticat, dzīvība ir iekš Viņa Vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Pēc tam Jēzus tiem mācekļiem atkal parādījās pie Tiberijas jūras, un Viņš tā parādījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Tur bija kopā Sīmanis Pēteris un Toms, dvīnis saukts, un Natanaēls no Kānas iekš Galilejas un tie Cebedeja dēli un divi citi no Viņa mācekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Sīmanis Pēteris uz tiem saka: “Es iešu zvejot.” Tad tie uz viņu saka: “Mēs arī iesim tev līdz!” Tad tie izgāja un tūdaļ iekāpa laivā un nekā nedabūja tajā naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Bet kad gaisma jau bija aususi, Jēzus stāvēja malā, un tie mācekļi nezināja, to esam Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Tad Jēzus uz tiem saka: “Bērni, vai jums nav ko ēst?” Tie Viņam atbildēja: “Nav nekā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Bet Viņš uz tiem sacīja: “Metiet tīklu pa laivas labo pusi, tad jūs atradīsiet.” Tad tie izmeta tīklu un vairs nespēja to vilkt tā pulka zivju dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Tad tas māceklis, ko Jēzus mīlēja, uz Pēteri saka: “Tas ir Tas Kungs!” Tad Pēteris dzirdēdams, ka Tas esot Tas Kungs, drēbi apvilka (jo viņš bija noģērbies) un iemetās jūrā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Bet tie citi mācekļi nāca ar laivu, jo tie nebija tālu no malas, bet pie divsimt olekšu nost, un vilka to tīklu ar tām zivīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Kad tie nu izkāpa pie malas, tad tie redzēja ogles liktas un zivis uz tām un maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jēzus uz tiem saka: “Atnesiet šurp no tām zivīm, ko jūs tagad esat dabūjuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Sīmanis Pēteris iekāpa un to tīklu izvilka malā pilnu ar lielām zivīm, pusotru simts un trīs. Un jebšu to tik daudz bija, tomēr tas tīkls nesaplīsa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jēzus uz tiem saka: “Nāciet un turiet azaidu.” Bet neviens no tiem mācekļiem nedrīkstēja Viņam jautāt, kas Tu esi? Jo tie gan zināja, ka Viņš bija Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Tad Jēzus nāk un to maizi ņem un tiem to dod, tā arī no tām zivīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Šī nu trešā reize, ka Jēzus Saviem mācekļiem parādījies pēc Savas augšām celšanās no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Kad tie nu to azaidu bija noturējuši, tad Jēzus uz Sīmani Pēteri saka: “Sīmani, Jonas dēls, vai tu Mani vairāk mīli nekā šie?” Tas uz Viņu saka: “Tiešām, Kungs, Tu zini, ka es Tevi mīlēju.” Viņš uz to saka: “Gani Manus jērus!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Atkal otru reiz Viņš uz to saka: “Sīmani, Jonas dēls, vai tu Mani mīli?” Tas uz Viņu saka: “Tiešām, Kungs, Tu zini, ka es Tevi mīlēju.” Viņš uz to saka: “Gani Manas avis!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Trešo reiz Viņš uz to saka: “Sīmani, Jonas dēls, vai tu Mani mīli?” Pēteris noskuma, ka Viņš trešo lāgu uz to sacīja: “Vai tu Mani mīli?” Un sacīja uz Viņu: “Kungs Tu visas lietas zini; Tu zini, ka es Tevi mīlēju.” Jēzus uz to saka: “Gani Manas avis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Patiesi, patiesi, Es tev saku: tu, jaunāks būdams, pats esi jozies un esi gājis, kur gribēdams; bet, vecs tapis, tu savas rokas izstiepsi, un cits tevi jozīs un tevi vedīs, kur tu negribi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Bet to Viņš sacīja, gribēdams rādīt, ar kādu nāvi tam bija Dievu godāt. Un to runājis Viņš uz to saka: “Nāc Man pakaļ!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Un Pēteris apgriezies redz to mācekli, ko Jēzus mīlēja, pakaļ nākam, kas arī pie tā vakariņa pie Viņa krūtīm bija gulējis un sacījis: Kungs, kurš ir tas, kas Tevi nodos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Kad Pēteris to redzēja, tad viņš saka uz Jēzu: “Kungs, kas tad būs ar šo?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jēzus uz to saka: “Ja Es gribu, ka šis paliek, kamēr Es nāku, kas tev par to? Nāc tu Man pakaļ!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Tad šī valoda cēlās starp tiem brāļiem: “Šis māceklis nemirs.” Bet Jēzus viņam nebija sacījis, ka viņš nemirs, bet: “Ja Es gribu, ka viņš paliek, kamēr Es nāku, kas tev par to?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Šis ir tas māceklis, kas liecību dod par šīm lietām un tās ir sarakstījis; un mēs zinām, ka viņa liecība uzticama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, '(Un vēl daudz citas lietas Jēzus ir darījis, un ja visas tās pēc kārtas uzrakstītu, tad man šķiet, ka arī visa pasaule tās sarakstītas grāmatas nevarētu saņemt. Āmen.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Tos pirmos stāstus es gan esmu stāstījis par visu, mans Teofil, ko Jēzus ir iesācis darīt un mācīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Līdz tai dienai, kad Viņš tapa uzņemts un tiem apustuļiem, ko Viņš izredzējis, pavēles bija devis caur Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Tiem Viņš arīdzan pēc Savas ciešanas caur daudz skaidrām zīmēm Pats dzīvs bija parādījies, no tiem četrdesmit dienas redzēts un uz tiem runādams par Dieva valstības lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Un kad Viņš tos bija sapulcinājis, tad Viņš tiem pavēlēja, neatstāties no Jeruzālemes, bet gaidīt uz Tā Tēva apsolīšanu, ko jūs no manis esat dzirdējuši (tā Viņš sacīja);');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Jo Jānis gan ir kristījis ar ūdeni, bet jūs tapsiet kristīti ar Svēto Garu ne ilgi pēc šīm dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Tad nu tie, kas bija kopā nākuši, Viņam vaicāja sacīdami: “Kungs, vai Tu šinī laikā atkal uzcelsi Israēla valstību?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Bet Viņš uz tiem sacīja: “Jums nepieklājās zināt tos laikus jeb brīžus, ko Tas Tēvs Savā paša varā nolicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Bet jūs dabūsiet spēku, kad Tas Svētais Gars pār jums būs nācis, un būsiet Mani liecinieki tā Jeruzālemē, kā arī visā Jūdu zemē un Samarijā un līdz pat pasaules galam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Un to sacījis, Viņš tiem redzot tapa uzcelts, un viens padebesis To uzņēma no viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Un kad tie skatījās uz debesīm, Viņam uzkāpjot, redzi, tad divi vīri pie tiem stāvēja baltās drēbēs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Un sacīja: “Jūs Galileju vīri, ko jūs stāvat skatīdamies uz debesīm! Šis Jēzus, kas ir uzņemts no jums uz debesīm, tāpat nāks, kā jūs viņu esat redzējuši debesīs uzkāpjam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Tad tie griezās atpakaļ uz Jeruzālemi no tā kalna, kas top saukts Eļļas kalns, kas ir tuvu pie Jeruzālemes vienu svētdienas gājumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Un tur nonākuši tie uzkāpa augšistabā; tur bija sapulcēti Pēteris un Jēkabs, un Jānis un Andrejs, Filips un Toms, Bērtulis un Matejs, Jēkabs, Alfeja dēls, un Sīmanis Zelotes un Jūda, Jēkaba brālis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Šie visi vienprātīgi pastāvēja iekš lūgšanas un pielūgšanas līdz ar tām sievām un ar Viņa brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Un tanīs dienās Pēteris cēlās starp tiem mācekļiem un sacīja, (un tur bija kopā līdz simts divdesmit dvēselēm):');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '“Vīri, brāļi, tiem rakstiem bija tapt piepildītiem, ko Tas Svētais Gars ir papriekš sacījis caur Dāvida muti par Jūdasu, kas bija ceļa vadonis tiem, kas Jēzu saņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Jo tas bija pieskaitīts pie mums un līdz ar mums dabūjis šo pašu kalpošanas amatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Tad nu šis tīrumu ir mantojis no tās netaisnās algas, un uz vaigu nokritis, tas vidū uz pusēm sprādzis un visas viņa iekšas ir izgāzušās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Un tas visiem, kas Jeruzālemē dzīvo, ir tapis zināms, kā arī tas tīrums viņu valodā ir nosaukts: Aķeldama, tas ir asins tīrums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Jo Dāvida dziesmu grāmatā ir rakstīts: viņu māja lai paliek par postažu, un lai neviens tur nedzīvo, un lai cits dabū viņa uzrauga amatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Tāpēc nu pieklājās, ka no tiem vīriem, kas ar mums kopā bijuši pa visu to laiku, kad Tas Kungs Jēzus pie mums ir iegājis un izgājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Iesākot no Jāņa kristības līdz tai dienai, kad Viņš no mums ir uzņemts debesīs, ka viens no šiem top par Viņa augšāmcelšanās liecinieku līdz ar mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Un tie stādīja divus priekšā, Jāzepu, kas top saukts Barsaba, ar pavārdu Justs, un Mattīsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Un Dievu pielūguši tie sacīja: “Kungs, Tu visu siržu manītājs, rādi no šiem diviem vienu, ko Tu izredzējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Kas var dalību dabūt pie šās kalpošanas un pie šī apustuļu amata, no kā Jūdas ir atstājies, noiedams savā vietā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Un tie meslojās, un mesli krita uz Mattīsu, un tas tiem vienpadsmit tapa pieskaitīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Un kad vasaras svētku diena atnāca, tad visi vienprātīgi bija kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Un tur piepeši no debess rūkšana notika, tā kā no varena vēja pūšanas, un piepildīja visu to namu, kur tie sēdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Un dalītas mēles tiem parādījās tā kā uguns un nolaidās uz ikvienu no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Un visi tapa piepildīti ar Svētu Garu un iesāka runāt ar citām mēlēm, kā tiem Tas Gars deva izrunāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Bet tur bija Jūdu ļaudis, kas Jeruzālemē dzīvoja, dievbijīgi vīri no visādām tautām apakš debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Kad nu šī balss notika, tad tas pulks nāca kopā un iztrūcinājās; jo ikviens tos dzirdēja savā valodā runājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Un tie visi sabijušies brīnījās, un cits uz citu sacīja: “Redzi, vai šie visi, kas runā, nav Galileji?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Kā tad mēs tos dzirdam ikviens savā valodā, kurā mēs dzimuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Partieši un Mēdieši un Elamieši, un kas dzīvojam iekš Mezopotamijas, Jūdejas un Kapadoķijas, Pontus un Āzijas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Friģijas un Pamfilijas, Ēģiptes un Libijas robežās pret Kireni, un piedzīvotāji no Romas, Jūdi un Jūdu ticības biedri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Krieti un Arābi, - mēs dzirdam, tos ar mūsu pašu mēlēm Dieva lielos darbus runājam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Un visi sabijušies nezināja, ko darīt, un cits uz citu sacīja: “Kas tas būs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Bet citi mēdīdami sacīja: “Tie salda vīna pilni.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Bet Pēteris nostājies ar tiem vienpadsmit, pacēla savu balsi un uz tiem runāja: “Jūs Jūdu vīri, un visi, kas Jeruzālemē dzīvojat, lai tas jums ir zināms, un saņemat manus vārdus savās ausīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Jo šie nav piedzēruši, kā jums šķiet; jo šī ir dienas trešā stunda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Bet tas ir, ko pravietis Joēls sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Un Dievs saka: “Notiks pēdīgās dienās, ka Es izliešu no Sava Gara uz visu miesu; un jūsu dēli un jūsu meitas sludinās nākamas lietas, un jūsu jaunekļi redzēs parādīšanas, un jūsu vecaji sapņos sapņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Un arī uz Saviem kalpiem un uz Savām kalponēm Es tanīs dienās izliešu no Sava Gara, un tie sludinās praviešu mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Un Es došu brīnumus augšā pie debess un zīmes apakšā virs zemes, asinis un uguni un dūmu tvaiku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Saule taps pārvērsta par tumsību, un mēnesis par asinīm, pirms nekā nāks Tā Kunga lielā un spožā diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Un notiks, ka ikviens, kas Tā Kunga vārdu piesauks, taps izglābts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Jūs Israēla vīri, klausiet šos vārdus: Jēzu no Nacaretes, vīru no Dieva skaidri ierādītu jūsu starpā caur spēcīgiem darbiem un brīnumiem un zīmēm, ko Dievs darījis caur Viņu jūsu starpā, kā jūs paši to zināt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Šo, pēc Dieva nolemta padoma un papriekš zināšanas nodotu, jūs esat ņēmuši, caur netaisnu rokām pie krusta piekaluši un nokāvuši -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'To Dievs ir uzmodinājis, nāves sāpes atraisīdams, jo nevarēja būt, ka Viņš no tās taptu turēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Jo Dāvids par Viņu saka: es To Kungu vienmēr esmu turējis priekš acīm; jo Viņš man ir pa labo roku, ka es nešaubos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Tāpēc mana sirds priecājās un mana mēle līksmojās un arī mana miesa dusēs uz cerību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Jo Tu manu dvēseli nepametīsi kapā, nedz Savam Svētam liksi redzēt satrūdēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu man esi zināmus darījis dzīvības ceļus; Tu mani piepildīsi ar līksmību Tava vaiga priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Vīri, brāļi, lai ar drošību uz jums runājam par vectēvu Dāvidu: tas ir nomiris un aprakts, un viņa kaps pie mums ir līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Tad nu viņš pravietis būdams un zinādams, ka Dievs zvērēdams viņam bija solījis, ka tas Kristu gribot celt no viņa gurnu augļiem pēc miesas un to sēdināt uz viņa krēslu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'To tas paredzēdams ir runājis par Kristus augšāmcelšanos, ka Viņa dvēsele nav pamesta kapā nedz Viņa miesa redzējusi satrūdēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Šo Jēzu Dievs ir uzmodinājis, tam mēs visi esam liecinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Tad nu caur Dieva labo roku paaugstināts un no Tā Tēva dabūjis Tā Svētā Gara apsolīšanu, Viņš ir izlējis to, ko jūs tagad redzat un dzirdat,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Jo Dāvids nav uzkāpis debesīs; bet viņš saka: Tas Kungs ir sacījis uz manu Kungu: “Sēdies pie Manas labās rokas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Tiekams Es Tavus ienaidniekus lieku par pameslu Tavām kājām.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Tad nu visam Israēla namam būs tiešām zināt, ka Dievs Viņu ir darījis par Kungu un Kristu, šo pašu Jēzu, ko jūs esat situši krustā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Un kad tie to dzirdēja, tad sirds tiem pārtrūka, un tie sacīja uz Pēteri un tiem citiem apustuļiem: “Vīri, brāļi, ko mums būs darīt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Bet Pēteris uz tiem sacīja: “Atgriežaties no grēkiem un liekaties ikviens kristīties Jēzus Kristus vārdā uz grēku piedošanu, tad jūs dabūsiet Tā Svētā Gara dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Jo jums šī apsolīšana pieder un jūsu bērniem un visiem, kas ir tālu, cik Tas Kungs, mūsu Dievs, pieaicinās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Un ar daudz citiem vārdiem tas liecību deva un tos pamācīja sacīdams: “Izglābjaties no šās netiklas cilts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Kas nu viņa vārdu labprāt uzņēma, tie tapa kristīti; un tanī dienā tapa pieliktas kādas trīs tūkstošas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Un tie pastāvēja iekš apustuļu mācības un iekš draudzības un iekš maizes laušanas un iekš Dieva lūgšanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Un visām dvēselēm bailība uzgāja, un daudz brīnumi un zīmes notika caur tiem apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Bet visi, kas bija ticīgi, palika kopā un visas lietas tiem bija kopā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Un tie pārdeva visu savu mantu un sagādu, un to izdalīja visiem, kā kuram vajadzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Un tie ikdienas vienprātīgi turējās kopā Dieva namā, un šurp un turp namos maizi lauza un barību ņēma ar prieku un sirds vientiesību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Dievu teikdami, un bija visiem ļaudīm piemīlīgi; un Tas Kungs pielika ikdienas pie tās draudzes, kas tapa svētīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Bet Pēteris un Jānis gāja kopā uz Dieva namu ap lūgšanas stundu, tā ir tā devītā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Un viens vīrs, no mātes miesām tizls būdams, tapa nests; to tie ikdienas nolika priekš Dieva nama durvīm, kas top sauktas tās krāšņās, ka tas dāvanas lūgtos no tiem, kas gāja Dieva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Šis, redzēdams Pēteri un Jāni, ka tie gribēja ieiet Dieva namā, lūdzās kādu dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Bet Pēteris ar Jāni uz to skatījās un sacīja: “Skaties uz mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Un tas skatījās uz tiem gaidīdams, ko laba no viņiem dabūt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Bet Pēteris sacīja: “Sudraba un zelta man nav, bet kas man ir, to es tev dodu: Jēzus Kristus no Nacaretes vārdā: celies un staigā!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Un viņš to satvēra pie labās rokas un to pacēla, un tūdaļ viņa lieli un krimšļi tapa stingri,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Un uzlēcis viņš stāvēja un staigāja un gāja ar tiem Dieva namā, staigādams un lēkdams un Dievu teikdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Un visi ļaudis to redzēja staigājam un Dievu teicam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Un to arī pazina, ka viņš tas bija, kas dāvanu dēļ pie tām Dieva nama krāšņām durvīm bija sēdējis; un tie brīnījās, iztrūcinādamies par to, kas viņam bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Kad nu šis tizlais, kas bija vesels tapis, pie Pētera un Jāņa turējās, tad visi ļaudis pārbijušies pie tiem satecēja tai saucamā Salamana priekšnamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Bet Pēteris, to redzēdams, tiem ļaudīm atbildēja: “Jūs Israēla vīri, ko jūs brīnāties par to, jeb ko jūs lūkojieties uz mums, tā kā mēs caur savu pašu spēku un savu dievbijāšanu to būtu padarījuši, ka šis staigā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Ābrahāma un Īzaka un Jēkaba Dievs, mūsu tēvu Dievs, ir pagodinājis Savu Dēlu Jēzu, ko jūs esat nodevuši un aizlieguši priekš Pilatus, kad tas sprieda, Viņu laist vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Bet jūs To Svēto un Taisno esat aizlieguši un lūguši, ka jums tas slepkava taptu dots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Bet To dzīvības lielkungu jūs esat nokāvuši, ko Dievs ir uzmodinājis no miroņiem; tam mēs esam liecinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Un caur to ticību uz Viņa Vārdu, Viņš pie šā, ko jūs redzat un pazīstat, Savu Vārdu ir apstiprinājis, un tā ticība, kas ir caur Viņu, šim devusi pilnīgu veselību jūsu visu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Un nu brāļi, es zinu, ka nezinādami to esat darījuši, jūs kā arī jūsu virsnieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Bet ko Dievs caur visu Savu praviešu muti papriekš sludinājis, ka Kristum bija ciest, to Viņš tā ir piepildījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Tāpēc atjaunojaties savā prātā un atgriežaties, ka jūsu grēki top izdeldēti, lai atspirgšanas laiki nāk no Tā Kunga vaiga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Un lai Viņš Jēzu Kristu sūta, kas jums papriekš ir sludināts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Ko debesīm būs uzņemt līdz tam laikam, kad viss būs atjaunots, par ko Dievs jau sen ir runājis caur visu Savu svēto praviešu muti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Jo Mozus uz tiem tēviem ir sacījis: Tas Kungs jūsu Dievs jums cels vienu pravieti no jūsu brāļiem tā kā mani; To jums būs klausīt visās lietās, ko Tas uz jums runās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Un notiks, ka ikkatra dvēsele, kas neklausīs šim Pravietim, taps izdeldēta no tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Un visi pravieši no Samuēla sākot, un visi, kas pēc ir runājuši, tie arī šās dienas ir pasludinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Jūs esat to praviešu un tās derības bērni, (tās derības), ko Dievs darījis ar mūsu tēviem sacīdams uz Ābrahāmu: caur tavu sēklu visas ciltis virs zemes taps svētītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Dievs, Savu bērnu Jēzu uzmodinājis, To papriekš pie jums ir sūtījis, lai Tas jūs svētītu, ka ikviens atgrieztos no sava ļaunuma.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Bet šiem uz tiem ļaudīm runājot piegāja tie priesteri un tas Dieva nama virsnieks un tie saduceji,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Apskaitušies, ka viņi tos ļaudis mācīja un ka pasludināja iekš Jēzus augšāmcelšanos no miroņiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Un rokas tiem pielika un tos iemeta cietumā līdz rītam; jo vakars jau bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Bet daudzi, kas to vārdu dzirdēja, ticēja; un tur tapa skaitīti pie piectūkstošiem vīriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Bet notikās otrā dienā, ka viņu virsnieki un vecaji un rakstu mācītāji Jeruzālemē sapulcējās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Un Annas, tas augstais priesteris, un Kajafas un Jānis un Aleksanders, un cik no augstā priestera cilts bija;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Un viņus savā priekšā noveduši, tie jautāja: “Kurā spēkā jeb kurā vārdā jūs to esat darījuši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tad Pēteris, Svēta Gara pilns, uz tiem sacīja: “Jūs ļaužu virsnieki un jūs Israēla vecaji,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Ja mēs šodien topam tiesāti laba darba dēļ pie šā neveselā cilvēka, caur ko šis ir dziedināts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Tad jums visiem un visiem Israēla ļaudīm būs zināt, ka šis jūsu priekšā stāv vesels tik vien caur Jēzus Kristus no Nacaretes vārdu, ko jūs esat krustā situši, un ko Dievs no miroņiem uzmodinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Šis ir tas akmens, no jums nama taisītājiem atmests, kas palicis par stūra akmeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Un tā pestīšana nav caur citu nevienu, jo arīdzan cits vārds apakš debess cilvēkiem nav dots, caur ko mums būs mūžīgi dzīvot.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Kad tie nu Pētera un Jāņa sirds drošību redzēja un noprata, ka tie bija nemācīti un zemas kārtas cilvēki, tad tie brīnījās, un tos pazina, ka viņi bijuši ar Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Un kad tie to cilvēku, kas bija vesels tapis, redzēja pie viņiem stāvam, tad tiem nebija ko pretim runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Un tie lika viņiem iziet no tiesas nama un sarunājās savā starpā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Sacīdami: “Ko lai darām ar šiem cilvēkiem? Jo ka skaidrs brīnums caur tiem noticis, tas ir zināms visiem, kas Jeruzālemē dzīvo, un mēs to nevaram noliegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Bet lai tas starp tiem ļaudīm tālāki neizpaužas, mēs tiem gribam stipri piekodināt, ka tiem vairs uz nevienu cilvēku nebūs runāt iekš šī vārda.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Un viņus aicinājuši, tie viņiem pavēlēja, it nemaz nerunāt, nedz mācīt iekš Jēzus vārda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Bet Pēteris un Jānis atbildēdami uz tiem sacīja: “Spriežat paši, vai Dieva priekšā ir taisni, jums vairāk klausīt nekā Dievam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Jo mēs nevaram palikt nerunājuši par to, ko esam redzējuši un dzirdējuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Bet tie vēl vairāk viņus apdraudēja un palaida un neatrada, kā tos sodīt, to ļaužu dēļ, jo visi Dievu teica par to, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Jo tas cilvēks bija vairāk nekā četrdesmit gadus vecs, pie kā šī dziedināšanas zīme bija notikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Un vaļā atlaisti tie nāca pie tiem savējiem un pasludināja, ko tie augstie priesteri un vecaji uz tiem bija sacījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Un to dzirdējuši, tie vienprātīgi savu balsi pacēla uz Dievu un sacīja: “Kungs, Tu esi Tas Dievs, kas ir darījis debesi un zemi un jūru un visas lietas, kas tur iekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Kas caur Sava kalpa Dāvida muti esi sacījis: Kāpēc pagāni trako, un ļaudis domā uz nelietību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Ķēniņi virs zemes ir sacēlušies, un valdnieki sapulcējušies pret To Kungu un pret Viņa Svaidīto.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Jo patiesi, tie ir sapulcējušies pret Tavu svēto bērnu Jēzu, ko Tu esi svaidījis, arī Hērodus un Poncius Pilatus līdz ar pagāniem un Israēla ļaudīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'To darīdami, ko Tava roka un Tavs padoms papriekš ir nolēmis, ka tam bija notikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Tad nu, Kungs, skaties Tu uz viņu biedināšanu un dodi Saviem kalpiem Tavu Vārdu runāt ar visu drošību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Savu roku izstiepdams, ka dziedināšanas notiek un zīmes un brīnumi caur Tava svētā bērna Jēzus Vārdu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Un pēc lūgšanas tā vieta pakustinājās, kur tie bija sapulcējušies; un tie visi tapa Svētā Gara pilni un runāja Dieva vārdu ar drošību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Un tā draudze, kas ticēja, bija viena sirds un viena dvēsele, un neviens neko no savas mantas nesauca par savu, bet tās mantas bija visiem kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Un ar lielu spēku tie apustuļi deva liecību par Tā Kunga Jēzus augšāmcelšanos, un liela žēlastība bija pār tiem visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Un viņu starpā arī nebija neviena, kam kas pietrūka, jo kuriem tīrumi vai nami bija, tie tos pārdeva un atnesa to maksu no tā, kas bija pārdots,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'Un nolika tiem apustuļiem pie kājām, un ikkatram tapa izdalīts, kā kuram vajadzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Un Jāzeps, no tiem apustuļiem ar pavārdu saukts Barnaba (tas ir tulkots: iepriecināšanas bērns), viens Levits, dzimis Kipriets,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Kam bija tīrums, pārdeva to un atnesa to naudu un nolika pie apustuļu kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Un viens vīrs, ar vārdu Ananija, ar savu sievu Sapfiru pārdeva savu mantību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Un atrāva ko no tās maksas ar sievas ziņu; un kādu daļu atnesis, to nolika pie apustuļu kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Bet Pēteris sacīja: “Ananija, kāpēc sātans tavu sirdi ir piepildījis, tam Svētam Garam melot un no tā tīruma maksas ko atraut?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Vai tas tavs būdams nevarēja tavs palikt? Arī pārdots tas bija tavā vaļā; kāpēc tad tu tādu lietu savā sirdī esi iedomājies? Tu neesi cilvēkiem melojis, bet Dievam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Un šos vārdus dzirdējis, Ananija krita pie zemes un nomira; un lielas bailes uzgāja visiem, kas to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Un tie jaunekļi cēlušies to apkopa un iznesa un apraka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Un notikās pēc kādām trim stundām, tad viņa sieva arīdzan iegāja, nezinādama, kas bija noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Bet Pēteris tai atbildēja: “Saki man, vai jūs to tīrumu tik dārgi esat pārdevuši?” Un tā sacīja: “Tiešām, tik dārgi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Un Pēteris uz to sacīja: “Kāpēc tad jūs savā starpā esat norunājuši Tā Kunga Garu kārdināt? Redzi, to kājas, kas tavu vīru aprakuši, ir priekš durvīm un tevi iznesīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Un tūdaļ tā nokrita pie viņa kājām un nomira. Un tie jaunekļi iekšā nākuši to atrada mirušu un to iznesa un apraka pie viņas vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Un lielas bailes uzgāja visai draudzei un visiem, kas to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Un caur apustuļu rokām daudz zīmes un brīnumi notika starp tiem ļaudīm, un visi bija vienprātīgi Salamana priekšnamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Bet no tiem citiem neviens nedrīkstēja viņiem pieķerties, bet tie ļaudis tos augsti cienīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Un vēl vairāk tapa pielikti, kas Tam Kungam ticēja, pulks vīru un sievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Tā ka arī tie neveselie tapa izvesti uz ielām un gultās un nestuvēm likti, lai, Pēterim nākot, jel viņa ēna kādus no tiem apēnotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Un arī no apkārtējām pilsētām pulks ļaužu nāca uz Jeruzālemi, nesdami neveselus un nešķīstu garu apsēstus, kas visi tapa dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Bet tas augstais priesteris cēlās un visi, kas pie tā bija (tā saduceju biedrība), un tapa bardzības pilni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'Un pielika tiem apustuļiem rokas un tos iemeta pilsētas cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Bet Tā Kunga eņģelis naktī atvēra cietuma durvis un tos izveda un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '“Ejat, un Dieva namā stāvēdami, runājiet uz tiem ļaudīm visus šās dzīvības vārdus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Bet to dzirdējuši, tie iegāja it agri Dieva namā un mācīja. Bet tas augstais priesteris un tie, kas līdz ar viņu, nāca un sasauca to augsto tiesu un visus Israēla bērnu vecajus un sūtīja uz cietumu, tos atvest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Bet tie sulaiņi tur nogājuši tos neatrada cietumā un atnākuši to pasludināja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Sacīdami: “Mēs to cietumu gan atradām it cieti aizslēgtu un tos sargus ārā stāvošus priekš durvīm, bet atvēruši mēs iekšā neatradām neviena.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Kad nu tas priesteris un tas Dieva nama virsnieks un tie augstie priesteri šos vārdus dzirdēja, tad tie par to iztrūcinājās, kas tas esot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Un tur viens nāca un tiem pasludināja sacīdams: “Redzi, tie vīri, ko jūs esat likuši cietumā, stāv Dieva namā un māca tos ļaudis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Tad tas virsnieks ar tiem sulaiņiem nogāja un tos atveda, bet ne ar varu, (jo tie bijās no tiem ļaudīm, ka ar akmeņiem netaptu nomētāti).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Un tos atveduši, tie tos stādīja augstās tiesas priekšā, un tas augstais priesteris tiem vaicāja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Sacīdams: “Vai mēs pavēlēdami jums neesam pavēlējuši, nemācīt iekš šī Vārda? Un redzi, jūs ar savu mācību esat piepildījuši Jeruzālemi un gribat pār mums vest šī Cilvēka asinis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Bet Pēteris un tie apustuļi atbildēja un sacīja: “Dievam būs vairāk klausīt nekā cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Mūsu tēvu Dievs ir uzmodinājis Jēzu, ko jūs esat nokāvuši, To piekārdami pie koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Šo Dievs caur Savu labo roku ir paaugstinājis par Lielkungu un Pestītāju, Israēlim dot atgriešanos un grēku piedošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Un mēs esam Viņa liecinieki šinīs lietās, un arī Tas Svētais Gars, ko Dievs tiem devis, kas Viņam paklausa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Bet kad viņi to dzirdēja, tad tas tiem iedūra sirdī, un tie viņus meklēja nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Bet viens no tās augstās tiesas, farizejs, ar vārdu Gamaliēls, bauslības mācītājs, no visiem ļaudīm godā turēts, pacēlās un pavēlēja, tos apustuļus maķenīt izvest,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Un sacīja uz viņiem: “Jūs Israēla vīri, apdomājaties labi par šiem cilvēkiem, ko jūs gribat darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Jo priekš šīm dienām Teudas cēlās sacīdams, ka viņš kas esot; tam cilvēku pulks pie četrsimt pieķērās. Tas ir nokauts, un visi, kas tam paklausīja, ir izklīdināti un iznīcināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Pēc šā cēlās Jūda, tas Galilejs, tai rakstīšanas laikā un novērsa daudz ļaužu sev pakaļ; šis arīdzan ir nomaitāts, un visi, cik viņam paklausīja, izklīdināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Tādēļ es jums tagad saku: atstājaties no šiem cilvēkiem un liekat tos mierā. Jo ja šis padoms jeb šis darbs ir no cilvēkiem, tad tas iznīks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Bet ja tas ir no Dieva, tad jūs to nevarēsiet iznīcināt; un ka vēl jūs netopat atrasti karotāji pret Dievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Un viņi tam paklausīja un tos apustuļus iesauca, tos šauta un tiem pavēlēja, nerunāt iekš Jēzus Vārda, un tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Tad nu tie līksmodamies aizgāja no tās augstās tiesas, ka tie bija cienīgi turēti, Viņa Vārda dēļ kaunu ciest;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Un nemitējās ikdienas Dieva namā un mājās mācīt un Jēzu Kristu priecīgi pasludināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Un tanīs dienās, kad tie mācekļi vairojās, kurnēšana cēlās pie tiem Grieķiem pret tiem Ebrejiem, ka viņu atraitnes iekš dienišķas apkopšanas paliekot neievērotas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Un tie divpadsmit saaicināja to mācekļu draudzi un sacīja: “Tas nepieklājās, ka mēs Dieva vārdu atstājam un kalpojam pie galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Tāpēc, brāļi, izredziet savā starpā septiņus vīrus, kam ir laba slava, Svēta Gara un gudrības pilnus, ko mēs šīs vajadzības pēc varētu iecelt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Bet mēs gribam pastāvīgi turēties pie Dieva lūgšanas un pie tā vārda amata.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Un šie vārdi patika visai draudzei; un tie izredzēja Stefanu, ticības un Svēta Gara pilnu vīru, un Filipu un Prokoru un Nikanoru un Timonu un Parmenu un Nikolaju, vienu Jūdu ticības biedri no Antioķijas');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Šos tie veda apustuļu priekšā; un Dievu pielūguši tie viņiem rokas uzlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Un Dieva vārds auga augumā, un mācekļu skaits Jeruzālemē ļoti vairojās, un liels priesteru pulks palika paklausīgs ticībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Un Stefans, ticības un spēka pilns, darīja brīnumus un lielas zīmes starp tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Un kādi no tās saucamās Libertiņu un Kireniešu un Aleksandriešu skolas un no tiem, kas bija no Ķiliķijas un Āzijas, cēlās un ar Stefanu stipri apjautājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Un tie nespēja pretī stāvēt tai gudrībai un Tam Garam, ar ko viņš runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Tad tie izmācīja vīrus, lai saka: “Mēs viņu esam dzirdējuši zaimošanas runājam pret Mozu un pret Dievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Un tie saskubināja tos ļaudis un tos vecajus un tos rakstu mācītājus. Un viņam uzmākušies, tie viņu sagrāba un veda tiesas priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Un atveda viltīgus lieciniekus, kas sacīja: “Šis cilvēks nemitās zaimošanas runāt pret šo svēto vietu un bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Jo mēs viņu esam dzirdējuši sakām: šis Jēzus no Nacaretes nopostīs šo vietu un pārvērtīs tās ierašas, ko mums Mozus devis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Un visi, kas augstā tiesā sēdēja, skatījās uz viņu un redzēja viņa vaigu kā kāda eņģeļa vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Un tas augstais priesteris sacīja: “Vai tas tā ir?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Bet viņš sacīja: “Vīri, brāļi un tēvi, klausāties! Tas godības Dievs parādījās mūsu tēvam Ābrahāmam, kad viņš bija Mezopotamijā, pirms Hāranā mājoja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Un sacīja uz viņu: izej no savas zemes un no saviem radiem un ej uz to zemi, ko Es tev rādīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Tad viņš no Kaldeju zemes izgājis mājoja Hāranā; un pēc, kad viņa tēvs bija nomiris, Dievs viņu no turienes pārveda uz šo zemi, kur jūs tagad dzīvojiet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Un viņam nedeva nekādu iemantojamu tiesu iekš tās, ir ne pēdas platumā; un tomēr viņam to solīja par mantu dot un viņa dzimumam pēc viņa, kad viņam bērnu vēl nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Bet Dievs tā runāja: tavs dzimums būs piedzīvotājs svešā zemē un piespiests pie kalpošanas un grūti vārdzināts četrsimt gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Un to tautu, kam tie kalpos, Es gribu sodīt, Dievs sacīja; un pēc tam tie izies un Man kalpos šinī vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Un Viņš tam deva to apgraizīšanas derību. Un tā viņš dzemdināja to Īzaku un to apgraizīja astotā dienā, un Īzaks to Jēkabu, un Jēkabs tos divpadsmit vectēvus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Un tie vectēvi apskauda un pārdeva Jāzepu uz Ēģiptes zemi; un Dievs bija ar viņu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Un to izglāba no visām viņa bēdām un tam deva žēlastību un gudrību Faraona, Ēģiptes ķēniņa, priekšā, un tas viņu iecēla par valdītāju pār Ēģiptes zemi un visu savu namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Bet bads nāca un lielas bēdas pār visu Ēģiptes un Kanaāna zemi; un mūsu tēvi neatrada barības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Un Jēkabs dzirdējis, labību esam Ēģiptes zemē, izsūtīja mūsu tēvus pirmo reiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Un otru reiz Jāzeps no saviem brāļiem tapa pazīts, un Jāzepa radi Faraonam kļuva zināmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Un Jāzeps sūtīja un ataicināja savu tēvu Jēkabu un visus savus radus, septiņdesmit un piecas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Un Jēkabs nogāja uz Ēģiptes zemi un nomira, viņš un mūsu tēvi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Un tapa pārvesti uz Šehemi un tai kapā ielikti, ko Ābrahāms ar sudraba maksu bija pircis no Hamora bērniem Šehemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Bet kad tas apsolīšanas laiks tuvu klāt nāca, ko Dievs Ābrahāmam bija zvērējis, tad tie ļaudis auga un vairojās Ēģiptes zemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Tiekams cits ķēniņš cēlās, kas Jāzepu nepazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Šis mūsu tautai ar viltu uzmācās un mūsu tēviem ļaunu darīja, tā ka viņiem savi mazie bērniņi bija jāizmet laukā, lai tie nepaliktu pie dzīvības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Tai laikā Mozus piedzima un bija Dievam patīkams un tapa audzināts trīs mēnešus sava tēva namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Un kad tas bija izlikts laukā, tad Faraona meita to uzņēma un to uzaudzināja sev pašai par dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Un Mozus tapa mācīts visā ēģiptiešu gudrībā un bija spēcīgs vārdos un darbos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Kad nu viņš bija četrdesmit gadus vecs, tad tas savā sirdī apņēmās, apmeklēt savus brāļus, Israēla bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Un redzēdams, ka viens netaisnību cieta, viņš pārstāvēja un atrieba to, kam pāri darīja, un nosita to Ēģiptieti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Un viņš domāja, ka viņa brāļi nomanīšot, ka Dievs caur viņa roku tiem dodot pestīšanu. Bet tie to nesaprata.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Un otrā dienā viņš tiem piestājās, kad tie bārās un tos skubināja uz mieru sacīdams: vīri, jūs esat brāļi, kāpēc jūs viens otram pāri darāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Bet tas, kas savam tuvākam pāri darīja, viņu atgrūda sacīdams: kas tevi cēlis par virsnieku un tiesas kungu pār mums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Vai tu mani arīdzan gribi nokaut, kā tu vakar to Ēģiptieti esi nokāvis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Un Mozus šī vārda dēļ bēga un piemita Midijana zemē, kur viņš divus dēlus dzemdināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Un kad četrdesmit gadi bija pagājuši, tad Tā Kunga eņģelis Sinaī kalna tuksnesī viņam parādījās degošā ērkšķu krūmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Un Mozus to redzēdams, brīnījās par to parādīšanu, un kad tas piegāja to aplūkot, tad Tā Kunga balss uz viņu notika:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '“Es esmu tavu tēvu Dievs, Ābrahāma Dievs un Īzaka Dievs un Jēkaba Dievs.” Un Mozus sāka drebēt un nedrīkstēja tur skatīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Bet Tas Kungs uz to sacīja: “Noauni kurpes no savām kājām, jo tā vieta, kur tu stāvi, ir svēta zeme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Es redzēdams esmu redzējis Savu ļaužu grūtumu Ēģiptes zemē, un dzirdējis viņu nopūšanos un nolaidies tos izglābt; un nu nāc, Es tevi sūtīšu uz Ēģiptes zemi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Šo Mozu, ko tie bija aizlieguši sacīdami: kas tevi cēlis par virsnieku un tiesas kungu? šo Dievs sūtījis par virsnieku un pestītāju caur tā eņģeļa roku, kas tam bija parādījies ērkšķu krūmā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Šis viņus ir izvedis, darīdams brīnumus un zīmes Ēģiptes zemē un sarkanā jūrā un tuksnesī četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Šis ir tas Mozus, kas uz Israēla bērniem sacīja: “Tas Kungs, jūsu Dievs, jums no jūsu brāļiem cels vienu pravieti tā kā mani; To jums būs klausīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Šis pie tās draudzes tuksnesī bija ar to eņģeli, kas uz viņu runāja Sinaī kalnā, un bija ar mūsu tēviem; un saņēma dzīvus vārdus, mums tos dot;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Tam mūsu tēvi negribēja paklausīt, bet viņu atmeta un savās sirdis atgriezās uz Ēģiptes zemi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Sacīdami uz Āronu: taisi mums dievus, kas mūsu priekšā ies; jo mēs nezinām, kas ir noticis šim Mozum, kas mūs izvedis no Ēģiptes zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Un tie taisīja tanīs dienās vienu teļu un pienesa tam elkadievam upurus un priecājās par savu roku darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Bet Dievs novērsās un tos nodeva kalpot tam debess spēkam, itin kā ir rakstīts praviešu grāmatā: vai tu Israēla nams šinīs četrdesmit gados tuksnesī Man esi atnesis kaujamus un citus upurus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Un jūs esat pieņēmuši to Moloka dzīvokli un sava Dieva, Remvana, zvaigzni, tās bildes, ko esat taisījuši, tās pielūgt; un Es jūs pārcelšu viņpus Bābeles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Tā liecības telts bija pie mūsu tēviem tuksnesī, itin kā tas, kas ar Mozu runājis, bija pavēlējis, to taisīt pēc tās priekšzīmes, ko viņš bija redzējis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'To dabūjuši, mūsu tēvi ar Jozua to arī ieveda tai zemē, kas tiem pagāniem bija, kurus Dievs ir izdzinis mūsu tēvu priekšā līdz Dāvida dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Šis žēlastību atrada Dieva priekšā un ilgojās tam Jēkaba Dievam dzīvokli atrast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Un Salamans Viņam namu uztaisīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Bet tas Visuaugstākais nedzīvo namos, kas rokām taisīti, itin kā tas pravietis saka:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '“Debess ir Mans goda krēsls un zeme Manu kāju pamesls; kādu namu jūs Man uztaisīsiet, tā saka Tas Kungs, jeb kura ir Mana dusas vieta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Vai Mana roka nav šo visu taisījusi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Jūs stūrgalvīgie un sirdīs un ausīs neapgraizītie, jūs allažiņ tam Svētam Garam pretī stāvat, tā kā jūsu tēvi, tā arī jūs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Kuru no tiem praviešiem jūsu tēvi nav vajājuši? Viņi nokāvuši tos, kas par Tā Taisnā atnākšanu papriekš sludināja; Šim jūs tagad esat palikuši par nodevējiem un slepkavām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Jūs, kas bauslību caur eņģeļu rokām esat dabūjuši un neesat sargājuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Kad tie to dzirdēja, tad tas tiem iedūra sirdī un tie sakoda zobus pret viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Bet viņš, Svēta Gara pilns būdams, skatījās uz debesīm un redzēja Dieva godību un Jēzu stāvam pie Dieva labās rokas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Un sacīja: redzi, es debesis redzu atvērtas un To Cilvēka Dēlu stāvam pie Dieva labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Bet tie ar skaņu balsi brēkdami aizturēja savas ausis un visi kopā viņam uzmācās virsū,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Un to izmeta no pilsētas ārā un nomētāja ar akmeņiem; un tie liecinieki savas drēbes nolika pie viena jaunekļa kājām, kam vārds bija Sauls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Un tie ar akmeņiem nomētāja Stefanu, kas sauca un sacīja: Kungs Jēzu, pieņem manu garu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Un ceļos mezdamies tas sauca ar skaņu balsi: Kungs, nepielīdzini tiem šo grēku! Un to sacījis viņš aizmiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Bet Saulam viņa nāve bija ļoti pa prātam; un tanī dienā liela vajāšana cēlās pret to draudzi, kas bija Jeruzālemē. Un visi izklīda pa Jūdu zemes un Samarijas tiesām, tik ne tie apustuļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Un dievbijīgi vīri Stefanu paglabāja un viņu gauži nožēloja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Bet Sauls to draudzi postīja un gāja pa namiem, satverdams gan vīrus, gan sievas, un tos nodeva cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Tad nu tie izklīdinātie apkārt staigāja, to vārdu pasludinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Un Filips uz vienu Samarijas pilsētu nogājis, tiem Kristu pasludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Un tie ļaudis vienprātīgi klausījās uz to, ko Filips runāja, dzirdēdami un redzēdami tās zīmes, ko viņš darīja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Jo no daudziem, kam bija nešķīsti gari, tie izgāja, ar stipru balsi brēkdami, un daudzi melmeņu sērdzīgi(paralizēti) un tizli tapa dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Un liela līksmība cēlās tai pilsētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Un kāds vīrs, ar vārdu Sīmanis, tai pilsētā līdz tam bija darbojies ar buršanu un Samarijas ļaudis iztrūcinājis sacīdams, ka esot liels vīrs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Tam visi klausīja, tā mazi kā lieli sacīdami: “Šis ir tas lielais Dieva spēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Bet tie tāpēc tam klausīja, ka tas jau sen ar burvību tos bija apstulbojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Kad tie nu Filipam ticēja, kas tiem pasludināja to evaņģēliju par Dieva valstību un Jēzus Kristus vārdu, tad tie tapa kristīti, tā vīri kā sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Un Sīmanis pats arīdzan ticēja, un kristīts pastāvīgi turējās pie Filipa, un redzēdams zīmes un lielus brīnumus notiekam, viņš iztrūkās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Bet tie apustuļi Jeruzālemē dzirdēdami, ka Samarija Dieva vārdu bija pieņēmusi, sūtīja pie tiem Pēteri un Jāni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Šie nonākuši par tiem lūdza Dievu, ka tie dabūtu Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Jo tas vēl uz nevienu no tiem nebija nācis, bet tie bija tikai kristīti uz Tā Kunga Jēzus vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Tad viņi rokas tiem uzlika, un tie dabūja Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Bet Sīmanis redzēdams, ka caur apustuļu roku uzlikšanu Svētais Gars top dots, tiem dāvāja naudu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Sacīdams: “Dodiet man arīdzan to spēku, ka tas, kam es rokas uzlieku, dabū Svēto Garu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Bet Pēteris uz to sacīja: “Ka tu pazustu ar savu sudrabu, tāpēc ka tu domā Dieva dāvanu par naudu pirkt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Tev nav daļas nedz mantošanas pie šā vārda, jo tava sirds nav taisna Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Tāpēc atgriezies no šā sava ļaunuma un lūdz Dievu, vai šis tavas sirds nodoms tev varētu tapt piedots;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Jo es tevi redzu rūgtas žults pilnu un netaisnībā saistītu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Bet Sīmanis atbildēja un sacīja: “Lūdziet jūs par mani To Kungu, lai uz mani nenāk, ko jūs esat runājuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Tad nu Tā Kunga vārdu apliecinājuši un runājuši, tie griezās atpakaļ uz Jeruzālemi un pasludināja evanģēliju daudz Samarijas miestos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Un Tā Kunga eņģelis uz Filipu runāja sacīdams: “Celies un ej uz dienvidu pusi uz to ceļu, kas no Jeruzālemes iet uz Gazu, kur daudz nestaigā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Un cēlies viņš nogāja. Un redzi, viens Moru vīrs, Kandaces, Moru zemes ķēniņienes, kambarjunkurs un lielskungs, kas bija pār visām viņas mantām, tas bija nācis uz Jeruzālemi, Dievu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Un atpakaļ uz ceļu devies viņš sēdēja savos ratos un lasīja pravieti Jesaju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Un Tas Gars uz Filipu sacīja: “Ej klāt un turies pie šiem ratiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Un piesteidzies Filips dzirdēja viņu lasām pravieti Jesaju un sacīja: “Vai tu arī saproti, ko tu lasi?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Bet tas sacīja: “Kā lai to varu, kad neviens mani nemāca?” Un viņš lūdza Filipu, lai tas uzkāptu un pie tā piesēstos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Un tas rakstu gabals, ko tas lasīja, bija šis: “Viņš ir tā kā avs pie kaušanas vests un itin kā jērs apklusis sava cirpēja priekšā, tāpat Viņš savu muti neatdara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Iekš Viņa pazemošanās Viņa sodība ir atņemta; kas izteiks Viņa dzimumu? Jo Viņa dzīvība top aizrauta no zemes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Un tas kambarjunkurs atbildēja un uz Filipu sacīja: “Es tevi lūdzu, par ko tas pravietis to saka? Vai par sevi pašu, jeb vai par citu kādu?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Un Filips savu muti atdarīja un no šī raksta iesākdams viņam pasludināja to evaņģēliju no Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Un to ceļu braukdami tie nāca pie kāda ūdens, un tas kambarjunkurs sacīja: “Redz, še ūdens! Kas stāv pretī, ka topu kristīts?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Bet Filips sacīja: “Ja tu no visas sirds tici, tad to var.” Un viņš atbildēja un sacīja: “Es ticu, ka Jēzus Kristus ir Dieva Dēls.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Un viņš pavēlēja, tos ratus pieturēt, un abi divi nokāpa ūdenī, tā Filips kā tas kambarjunkurs, un viņš to kristīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Un kad tie no ūdens bija izkāpuši, Dieva Gars Filipu aizrāva, un tas kambarjunkurs viņu vairs neredzēja; bet viņš līksms brauca savu ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Bet Filips atradās Ašdodā; un visas pilsētas pārstaigādams, viņš evaņģēliju sludināja, kamēr nāca uz Cezareju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Bet Sauls vēl draudus un nāvi šņākdams pret Tā Kunga mācekļiem, gāja pie tā augstā priestera');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Un lūdza no tā grāmatas uz Damasku pie tām Jūdu draudzēm, ja viņš kādus no šīs ticības atrastu, vai vīrus vai sievas, ka viņš tos saistītus vestu uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Un viņam ejot notikās, ka viņš tuvu pie Damaskus nāca, un tur gaišums no debess viņu piepeši apspīdēja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Un viņš krita pie zemes un dzirdēja balsi uz viņu tā sakām: “Saul, Saul, ko tu Mani vajā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Un viņš sacīja: “Kungs, kas Tu esi?” Tas Kungs sacīja: “Es esmu Jēzus, ko tu vajā. Tev grūti nāksies pret dzenuli spārdīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Un tas sacīja trīcēdams un iztrūcies: “Kungs, ko Tu gribi, lai daru?” Tas Kungs uz to sacīja: “Celies un ej pilsētā, un tev sacīs, ko tev būs darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Bet tie vīri, kas bija viņa ceļa biedri, stāvēja iztrūkušies, to balsi gan dzirdēdami, bet neviena neredzēdami');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Bet Sauls cēlās no zemes un savas acis paceldams neredzēja neviena. Un tie to pie rokas vezdami ieveda Damaskū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Un trīs dienas tas nevarēja redzēt un ne ēda, ne dzēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Bet viens māceklis bija iekš Damaskus, ar vārdu Ananija, un Tas Kungs caur parādīšanu uz to sacīja: “Ananija!” Un tas sacīja: “Redzi, še es esmu, Kungs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Un Tas Kungs uz to sacīja: “Celies un ej uz to ielu, kas top saukta tā Taisnā, un meklē Jūdas namā to Tarsieti, kam vārds Sauls; jo, redzi, tas Dievu lūdz;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Un tas caur parādīšanu ir redzējis vīru, ar vārdu Ananija, ieejam un tam roku uzliekam, lai tas atkal top redzīgs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Bet Ananija atbildēja: “Kungs, es no daudziem esmu dzirdējis par šo vīru, cik ļaunuma tas darījis Taviem svētiem Jeruzālemē;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Un šeitan tam ir vara no tiem augstiem priesteriem, visus saistīt, kas Tavu Vārdu piesauc.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Bet Tas Kungs uz to sacīja: “Ej, jo šis Man ir izredzēts ierocis, Manu Vārdu nest pagānu un ķēniņu un Israēla bērnu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Jo Es tam rādīšu, cik daudz tam Mana Vārda dēļ jācieš.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Un Ananija nogāja un nāca tanī namā un tam rokas uzlika sacīdams: “Saul, brāli, Tas Kungs mani sūtījis, (Jēzus, kas tev uz tā ceļa, kur tu esi nācis, ir parādījies), lai tu atkal topi redzīgs un piepildīts ar Svēto Garu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Un tūdaļ no viņa acīm nokrita kā zvīņas, un viņš tapa tūdaļ redzīgs, un uzcēlies tapa kristīts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Un barību ņēmis viņš atspirga. Un Sauls bija kādas dienas pie tiem mācekļiem iekš Damaskus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Un tūdaļ tas sludināja baznīcās par Jēzu, ka Viņš Tas Dieva Dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Bet visi, kas to dzirdēja, iztrūkās un sacīja: “Vai šis nav tos postījis, kas Jeruzālemē šo Vārdu piesauca? Vai tas nav tāpēc šurp nācis, ka viņus vestu saistītus pie tiem augstiem priesteriem?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Bet Sauls palika jo dienas jo spēcīgs un iztrūcināja tos Jūdu ļaudis, kas Damaskū dzīvoja, un pierādīja, ka Šis Tas Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Un kad jau kāds laiks bija pagājis, tad tie Jūdu ļaudis sarunājās viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Bet viņu nodoms Saulam tapa zināms; un tie vārtus sargāja caurām dienām un naktīm, ka viņu varētu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Bet tie mācekļi viņu ņēma naktī un kurvī pār mūri nolaida zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Un uz Jeruzālemi nācis Sauls raudzīja tiem mācekļiem piebiedroties; bet visi no tā bijās, neticēdami, viņu esam mācekli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Bet Barnaba viņu ņēma un veda pie tiem apustuļiem un tiem teica, kā viņš uz ceļa To Kungu redzējis, un ka Tas ar viņu runājis, un kā viņš Damaskū ar drošību runājis Jēzus vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Un viņš pie tiem bija Jeruzālemē, ieiedams un iziedams un droši sludinādams Tā Kunga Jēzus vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Un viņš arī runāja un apjautājās ar tiem Grieķiem; bet tie glūnēja viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Bet tie brāļi, to nomanīdami, viņu pavadīja uz Cezareju un viņu sūtīja uz Tarsu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Tad nu tai draudzei pa visu Jūdeju un Galileju un Samariju bija miers, un tā auga un staigāja iekš Tā Kunga bijāšanas un vairojās caur Tā Svētā Gara iepriecināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Un notikās, ka Pēteris visur pārstaigājot arī nonāca pie tiem svētiem, kas Liddā dzīvoja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Un tur tas atrada vienu cilvēku, ar vārdu Eneas, astoņus gadus uz gultas gulošu, - šis bija melmeņu sērdzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Un Pēteris uz to sacīja: “Enea, lai Jēzus, Tas Kristus, tevi dara veselu; celies un taisi pats sev gultu!” Un tas tūdaļ cēlās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Un to visi redzēja, kas Liddā un Šaronā dzīvoja, un tie atgriezās pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Un Joppē bija kāda mācekle, ar vārdu Tabita, tas ir tulkots: stirna; šī bija labu darbu darītāja un nabagu apdāvinātāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Un notikās tanīs dienās, ka viņa palika slima un nomira, un tie to mazgājuši nolika augšistabā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Bet kad nu Lidda tuvu pie Joppes ir, tad tie mācekļi dzirdēdami, Pēteri tur esam, sūtīja divus vīrus pie tā, lūgdami, ka tas nekavētos, pie tiem noiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Un Pēteris cēlās un gāja tiem līdz. Un kad viņš bija atnācis, tad viņu uzveda tai augšistabā; un pie tās stāvēja visas atraitnes, raudādamas un rādīdamas tos svārkus un tās drēbes, ko tā Stirna, pie tiem būdama, bija taisījusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Un Pēteris, visus izdzinis, metās ceļos un Dievu lūdza, un pie tās mirušās atgriezdamies sacīja: “Tabita, celies augšām.” Un tā savas acis atvēra un Pēteri redzējusi cēlās sēdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Un viņš tai roku deva un to pacēla, un, tos svētos un tās atraitnes aicinājis, viņu dzīvu tiem veda priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Un tas tapa zināms pa visu Joppi un daudzi ticēja uz To Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Un notikās, ka viņš daudz dienas Joppē palika pie viena ādmiņa, ar vārdu Sīmanis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Un viens vīrs bija Cezarejā, Karniels vārdā, viens kapteinis, no tā saucamā Itālijas karoga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Dieva cienītājs un dievbijīgs ar visu savu namu, kas tos ļaudis daudz apdāvināja un allažiņ Dievu lūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Šis ap devīto dienas stundu parādīšanā skaidri redzēja Dieva eņģeli ienākam pie viņa un uz viņu sakām: “Karniel!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Un to redzēdams viņš pārbijās un sacīja: “Kas ir, Kungs?” Bet tas uz viņu sacīja: “Tavas lūgšanas ir uzkāpušas un pieminētas Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Un tagad nosūti vīrus uz Joppi un ataicini Sīmani, ar pavārdu Pēteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Šis piemājo pie kāda ādmiņa Sīmaņa, kam nams ir jūrmalā; šis tev sacīs, ko tev būs darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Un kad tas eņģelis, kas ar Karnieli runāja, bija aizgājis, tad šis aicināja divus no saviem nama kalpiem un vienu dievbijīgu karavīru no tiem, kas pastāvīgi pie viņa bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Un visas lietas stāstījis viņš tos sūtīja uz Joppi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Un otrā dienā, kad tie uz ceļa bija un tai pilsētai tuvu klāt nāca, Pēteris uzkāpa uz jumtu, Dievu lūgt, ap sesto stundu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Un viņš izsalcis būdams gribēja ko baudīt, un kamēr tie ēdienu sataisīja, viņš garā tapa aizgrābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Un viņš redz debesi atvērtu un kādu trauku nonākam, tā kā lielu palagu pie četriem stūriem nolaistu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Tanī bija visādi četrkājīgi lopi un zvēri un tārpi no zemes virsas un putni, kas apakš debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Un balss notika uz to: “Celies, Pēteri, kauj un ēd.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Bet Pēteris sacīja: “Ne mūžam, Kungs! Jo es nekad neesmu ko ēdis, kas ir aizliegts, vai nešķīsts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Un atkal otru reiz balss uz viņu notika: “Ko Dievs ir šķīstījis, to tev nebūs turēt par aizliegtu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Un tas notika trīs reizes un tas trauks atkal tapa uzcelts debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Un kad Pēteris savā prātā nezināja, ko šī parādīšana apzīmējot, ko viņš bija redzējis, redzi, tad tie no Karnieļa sūtītie vīri, Sīmaņa namu izvaicājuši, stāvēja pie vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Un tie sauca un vaicāja, vai Sīmanis, ar pavārdu Pēteris, tur mājojot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Un kad Pēteris to parādīšanu pārdomāja, tad Tas Gars uz to sacīja: “Redzi, trīs vīri tevi meklē;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Bet celies, nokāp un ej tiem līdz nešaubīdamies, jo Es tos esmu sūtījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Un Pēteris nokāpa pie tiem vīriem, kas no Karnieļa pie tā bija sūtīti, un sacīja: “Redzi, es esmu tas, ko jūs meklējiet, kādas lietas dēļ jūs še esat?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Un tie sacīja: “Karniels, viens kapteinis, taisns un dievbijīgs vīrs, kam pie visas Jūdu cilts laba slava, tas no viena svēta eņģeļa ir pamācīts, tevi uz savu namu aicināt un vārdus dzirdēt no tevis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Tad nu viņš tos aicināja iekšā un uzņēma savā namā. Un otrā dienā viņš cēlās un gāja tiem līdz, un kādi brāļi, kas bija no Joppes, viņu pavadīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Un otrā dienā tie nonāca Cezarejā, un Karniels, savus radiniekus un labākos draugus saaicinājis, viņus gaidīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Un notikās, Pēterim ieejot, ka Karniels tam gāja pretī un paklanījās, mezdamies pie viņa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Bet Pēteris to pacēla un sacīja: “Celies, arī es esmu cilvēks.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Un ar to sarunādamies viņš gāja iekšā un atrada daudz kopā sanākušus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Un uz tiem sacīja: “Jūs zināt, ka Jūdu vīram nepieklājās piebiedroties jeb nākt pie svešas tautas cilvēka; bet man Dievs ir rādījis, ka nevienu cilvēku nebūs saukt par negantu jeb nešķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Tāpēc es ataicināts arī esmu nācis bez pretī runāšanas; tad nu vaicāju: kādēļ jūs mani esat aicinājuši?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Un Karniels sacīja: “Priekš četrām dienām līdz šai stundai es biju gavējis, un devītā stundā man savā namā Dievu lūdzot, redzi, viens vīrs ar spožām drēbēm stāvēja manā priekšā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Un sacīja: Karniel, tavas lūgšanas ir paklausītas un tavas nabagu dāvanas ir pieminētas Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Tāpēc sūti uz Joppi un ataicini Sīmani, ar pavārdu Pēteri; šis mājo Sīmaņa, tā ādmiņa, namā pie jūras; šis nāks un ar tevi runās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Tāpēc es tūdaļ pie tevis esmu sūtījis, un tu esi labi darījis, ka esi nācis. Tad nu tagad mēs visi stāvam Dieva priekšā, visu to dzirdēt, kas tev no Dieva pavēlēts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Bet Pēteris savu muti atdarījis sacīja: “Nu es tiešām atzīstu, ka Dievs cilvēka vaigu neuzlūko;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Bet no visām tautām, kas Viņu bīstas un taisnību dara, tas Viņam pieņēmīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Tas ir tas vārds, ko Viņš Israēla bērniem ir sūtījis, pasludinādams prieku un mieru caur Jēzu Kristu: Šis ir Kungs pār visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Jūs zināt, kas noticis pa visu Jūdu zemi, iesākot no Galilejas, pēc tās kristības, ko Jānis pasludinājis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Kā Dievs ar Svētu Garu un spēku ir svaidījis to Jēzu no Nacaretes, kas ir apkārt gājis, labu darīdams un dziedinādams visus no velna uzvarētos; jo Dievs bija ar Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Un mēs esam liecinieki par visu, ko Viņš darījis Jūdu zemē un arī Jeruzālemē; Šo tie nokāvuši piekārdami pie koka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Šo Dievs ir uzmodinājis trešā dienā un Viņam licis parādīties');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Ne visiem ļaudīm, bet tiem papriekš no Dieva ieceltiem lieciniekiem, mums, kas ar Viņu esam ēduši un dzēruši pēc Viņa augšām celšanās no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Un Viņš mums ir pavēlējis, tiem ļaudīm pasludināt un apliecināt, Viņu esam to no Dieva iestādīto soģi pār dzīviem un mirušiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Šim visi pravieši dod liecību, ka caur Viņa vārdu ikviens, kas tic uz Viņu, dabū grēku piedošanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Un Pēterim šos vārdus vēl runājot, Svētais Gars krita uz visiem, kas to vārdu dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Un tie ticīgie no tās apgraizīšanas, cik Pēterim bija līdz nākuši, iztrūkās, ka arī uz pagāniem Svētā Gara dāvana bija izlieta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Jo tie tos dzirdēja valodām runājam un Dievu teicam. Tad Pēteris atbildēja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '“Vai arī kas laban ūdeni var liegt, ka šie netaptu kristīti, kas To Svēto Garu ir dabūjuši itin kā mēs?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Un viņš pavēlēja, tos kristīt iekš Tā Kunga vārda. Tad tie viņu lūdza, lai viņš kādas dienas pie tiem paliktu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Un tie apustuļi un brāļi Jūdu zemē dzirdēja, ka arī pagāni Dieva vārdu bija pieņēmuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Un kad Pēteris uz Jeruzālemi nāca, tad tie apgraizītie ar to strīdējās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Sacīdami: “Tu pie vīriem, kam ir priekšāda, esi iegājis un ar tiem ēdis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Bet Pēteris iesāka tiem pēc kārtas stāstīt sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '“Es Joppes pilsētā Dievu lūdzu, un garā aizgrābts redzēju vienu parādīšanu: kādu trauku nonākam tā kā lielu palagu pie četriem stūriem nolaistu no debesīm, un tas nonāca pie manis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'To skatīdams es ņēmu vērā un redzēju četrkājīgus lopus un zvērus un tārpus no zemes virsas un putnus, kas apakš debess.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Un es dzirdēju balsi uz mani sakām: “Celies, Pēteri, kauj un ēd.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Bet es sacīju: “Ak Kungs, ne mūžam! Jo nekas, kas ir negants un nešķīsts, nekad nav nācis manā mutē.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Un balss no debess man atbildēja otrā kārtā: “Ko Dievs ir šķīstījis, to tev nebūs turēt par negantu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Un tas notikās trim reizēm, un viss atkal tapa uzvilkts debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Un redzi, tūdaļ trīs vīri, no Cezarejas pie manis sūtīti, stāvēja priekš tā nama, kur es biju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Un Tas Gars uz mani sacīja, lai es tiem ejot līdz bez šaubīšanās, un arī šie seši brāļi man gāja līdz, un mēs iegājām tā vīra namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Un tas mums stāstīja, kā tas vienu eņģeli bija redzējis savā namā stāvam un uz viņu sakām: “Sūti vīrus uz Joppi un ataicini Sīmani, ar pavārdu Pēteri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Šis tev vārdus sacīs, caur ko tu ar visu savu namu tapsi izglābts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Un kad es sāku runāt, tad Svētais gars uz tiem krita, tāpat kā arī iesākumā uz mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Un es pieminēju Tā Kunga vārdu, ka Viņš ir sacījis: “Jānis gan ar ūdeni kristījis, bet jūs tapsiet kristīti ar Svēto Garu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Ja nu Dievs tiem tādu pat dāvanu devis kā arī mums, kas esam ticējuši uz To Kungu Jēzu Kristu, kas tad es biju, ka es būtu spējis Dievam to aizliegt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Un tie to dzirdējuši bija ar mieru un teica Dievu sacīdami: “Tad nu Dievs arī pagāniem ir devis atgriešanos no grēkiem uz dzīvību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Bet nu tie, kas bija izklīduši tai vajāšanā, kas Stefana dēļ bija cēlusies, izgāja līdz Feniķijai, Kiprai un Antioķijai, nevienam to vārdu nesludinādami kā vien Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Un viņu starpā bija kādi Kiprieši un Kirenieši, kas nākuši uz Antioķiju arī uz Grieķiem runāja, to evaņģēliju no Tā Kunga Jēzus mācīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Un Tā Kunga roka bija ar tiem, un liels pulks ticēja un atgriezās pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Bet slava par tiem nāca ausīs tai Jeruzālemes draudzei; un tā sūtīja Barnabu, lai noietu līdz Antioķijai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Šis nonācis un to Dieva žēlastību redzējis, priecājās un visus pamācīja, lai tie no sirds dibena apņemtos pie Tā Kunga palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Jo viņš bija labs vīrs un Svētā Gara un ticības pilns. Un labs ļaužu pulks Tam Kungam tapa pievests,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Un Barnaba izgāja uz Tarsu, Saulu meklēt, un to atradis, viņš to noveda uz Antioķiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Un notikās, ka tie veselu gadu kopā bija tai draudzē un mācīja labu pulku, un ka Antioķijā tos mācekļus sāka saukt par kristīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Un tanīs dienās pravieši nāca no Jeruzālemes uz Antioķiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Un viens no tiem, ar vārdu Agabs, cēlās un pasludināja caur To Garu, ka liels bada laiks nākšot pār visu pasauli: tas arī noticis apakš Ķeizara Klaudius.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Un tie mācekļi apņēmās, kā kurš spēja, ko labu par palīgu sūtīt tiem brāļiem, kas dzīvoja Jūdu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'To tie arī darīja, un tiem vecajiem to sūtīja caur Barnabas un Saula roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Un ap to pašu laiku ķēniņš Hērodus kādiem no tās draudzes pielika rokas, tiem ļaunu darīdams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Un nokāva ar zobenu Jēkabu, Jāņa brāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Un redzēdams, ka tas tiem Jūdu ļaudīm patika, viņš turklāt arī vēl Pēteri sagrāba, (bet bija tās neraudzētās maizes dienas)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Un sagrābis to lika cietumā, un to nodeva sešpadsmit karavīriem, kas pa četriem to sargāja, gribēdams viņu pēc Lieldienas tiem ļaudīm vest priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Tad nu Pēteris cietumā tapa sargāts; bet tā draudze bez mitēšanās lūdza Dievu par viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Un kad Hērodus viņu gribēja priekšā vest, tanī pašā naktī Pēteris gulēja starp diviem karavīriem, ar divām ķēdēm saistīts, un tie sargi priekš durvīm sargāja to cietumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Un redzi, Tā Kunga eņģelis piestājās, un gaišums spīdēja tanī ēkā; un viņš piesita Pēterim pie sāniem un to uzmodināja sacīdams: “Celies drīz!” Un ķēdes nokrita no viņa rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Un tas eņģelis uz to sacīja: “Apjozies un apauni kājas!” Un tas tā darīja. Un viņš uz to sacīja: “Apmet savu mēteli un nāc man līdz.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Un tas iznācis viņam gāja līdz un nezināja to tiešām caur eņģeli notiekam; bet tam likās, ka redzot kādu parādīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Un caur pirmo un otru vakti gājuši, tie nāca pie tiem dzelzs vārtiem, kas iet uz pilsētu; tie paši no sevis tiem atdarījās; un izgājuši tie vienu ielu nostaigāja un tūdaļ tas eņģelis no tā atstājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Un Pēteris atjēdzies sacīja: “Tagad es tiešām zinu, ka Tas Kungs Savu eņģeli ir sūtījis un mani izpestījis no Hērodus rokas un no visas Jūdu ļaužu gaidīšanas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Un to nopratis viņš nāca pie Marijas nama, kas bija māte Jānim, kam pavārds Marks; tur daudz bija sapulcējušies Dievu lūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Un Pēterim pie vārtu durvīm klaudzinot, viena kalpone, ar vārdu Rode, nāca klausīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Un Pētera balsi pazīdama, tā aiz prieka tos vārtus neatdarīja, bet ietecēja un pasludināja, ka Pēteris stāvot priekš vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Bet tie uz viņu sacīja: “Vai tu traka?” Bet viņa uz to pastāvēja, tā esot. Bet tie sacīja: “Tas ir viņa eņģelis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Bet Pēteris joprojām klaudzināja; un atdarījuši tie viņu redzēja un iztrūkās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Bet viņš meta ar roku, lai būtu klusu, un tiem stāstīja, kā Tas Kungs viņu bija izvedis no cietuma. Un viņš sacīja: “Pasakiet to Jēkabam un tiem brāļiem;” un viņš izgājis devās uz citu vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Un kad gaisma ausa, tad tie karavīri gauži iztrūkās, kas gan ar Pēteri esot noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Bet kad Hērodus viņu bija meklējis un nebija atradis, tad viņš tos sargus priekš tiesas izvaicājis pavēlēja, tos novest (pie nāves); un viņš nogāja no Jūdu zemes uz Cezareju un tur mita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Un Hērodus apņēmās karot pret Tirus un Sidonas ļaudīm; bet tie nāca vienprātīgi pie viņa, un pārrunājuši Blastu, kas bija uzraugs pār tā ķēniņa guļamo kambari, tie lūdza mieru, tāpēc ka viņu zeme savu uzturu ņēma no ķēniņa zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Un kādā noliktā dienā Hērodus aptērpās ar ķēniņa drēbēm un sēdēja uz goda krēsla un uz tiem runāja ļaužu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Un tie ļaudis uzkliedza: “Tā ir dieva un ne cilvēka balss.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Un tūdaļ Tā Kunga eņģelis viņu sita, tāpēc ka viņš Dievam to godu nedeva. Un viņš no tārpiem tapa ēsts un nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Bet Dieva vārds auga un vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Bet Barnaba un Sauls, kad tie to palīdzību bija nonesuši, griezās atpakaļ no Jeruzālemes un ņēma līdz arī Jāni, ar pavārdu Marks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Un pie tās draudzes, kas bija Antioķijā, bija pravieši un mācītāji: Barnaba un Sīmeans, kas dēvēts Nigers, un Lucijus no Kirenes un Mannaēns, kas ar Hērodu, to lielkungu, bija uzaudzināts, un Sauls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Un kad tie Tam Kungam kalpoja un gavēja, tad Svētais Gars sacīja: “Nošķiriet man Barnabu un Saulu uz to darbu, pie kā Es tos esmu aicinājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Tad tie gavēja un Dievu lūdza un tiem rokas uzlikuši tos atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Tad nu šie no Svētā Gara izsūtītie nogāja uz Seleukiju, un no tejienes pārcēlās uz Kipru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Un nākuši Salaminā tie pasludināja Dieva vārdu Jūdu baznīcās, un tiem arī Jānis bija klāt par palīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Un to salu pārstaigājuši līdz Pafai, tie atrada kādu burvi, viltīgu pravieti, Jūdu cilvēku, kam vārds bija Barjesus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Tas bija pie tā zemes soģa Sergijus Paula, kas bija gudrs vīrs. Šis, Barnabu un Saulu ataicinājis, ļoti vēlējās Dieva vārdu dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Bet tiem Elimas, tas burvis, (jo tā viņa vārds top tulkots), stāvēja pretī, meklēdams zemes soģi novērst no ticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Bet Sauls, (arī Pāvils saukts), Svēta Gara pilns viņu uzskatīja');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Un sacīja: “Ak tu velna bērns, visas viltības un visas blēdības pilns, tu visas taisnības ienaidnieks, vai tu nestāsies pārvērst Tā Kunga taisnos ceļus?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Un nu redzi, Tā Kunga roka ir pret tevi, un tu būsi akls un uz kādu laiku sauli neredzēsi.” Un tūdaļ krēsla un tumsa krita uz viņu, un viņš gāja apkārt, meklēdams vadoņus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Tad tas zemes soģis redzēdams, kas bija noticis, ticēja, izbrīnīdamies par Tā Kunga mācību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Un Pāvils līdz ar tiem biedriem, no Pafas cēlušies, nāca uz Pergu Pamfilijā; bet Jānis no tiem šķīrās un griezās atpakaļ uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Un tie pārstaigādami, no Pergas nāca uz Antioķiju Pisidijā un vienā svētdienā iegājuši baznīcā apsēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Un pēc bauslības un praviešu lasīšanas tie baznīcas virsnieki sūtīja pie tiem sacīdami: “Vīri, brāļi, ja jums kādi pamācīšanas vārdi uz tiem ļaudīm, tad runājiet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Un Pāvils cēlies un ar roku metis sacīja: “Jūs Israēla vīri un jūs dievbijīgie, klausāties:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Šīs Israēla tautas Dievs mūsu tēvus ir izredzējis un to tautu augsti cēlis, kad tie piemita Ēģiptes zemē, un no turienes ar paceltu roku Viņš tos ir izvedis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Un tuksnesī Viņš tos uzturējis pie četrdesmit gadiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Un izdeldējis septiņas tautas Kanaāna zemē un tiem izdalījis viņu zemi par mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Un pēc tam pie četrsimt un piecdesmit gadiem Viņš tiem deva soģus līdz pravietim Samuēlim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Un tad tie lūdzās ķēniņu; un Dievs tiem deva Saulu, Ķisa dēlu, vīru no Benjamina cilts, četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Un to atmetis, Viņš tiem iecēla Dāvidu par ķēniņu; tam Viņš arī deva liecību sacīdams: “Es esmu atradis Dāvidu, Isajus dēlu, vīru pēc Manas sirds, kas darīs visu Manu prātu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'No šā dzimuma Dievs Israēlim pēc tās apsolīšanas ir iecēlis To Pestītāju Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Priekš Viņa atnākšanas Jānis visiem Israēla ļaudīm bija pasludinājis to kristību uz atgriešanos no grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Un Jānis savu ceļu pabeidzis sacīja: “Ko jūs domājat, kas es esmu? Es tas neesmu; bet redzi, Viens nāk pēc manis, kam es neesmu cienīgs kurpju siksnas atraisīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Vīri, brāļi, jūs bērni no Ābrahāma dzimuma, un cik jūsu starpā ir dievbijīgi, jums šis pestīšanas vārds ir sūtīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Jo tie, kas Jeruzālemē dzīvo, un viņu virsnieki Šo neatzīdami nedz tos praviešu vārdus, kas ik svētdienas top lasīti, tos ir piepildījuši, Viņu tiesādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Un nekādu nāves vainu neatrazdami, tie Pilatu ir lūguši, Viņu nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Un kad tie visu bija padarījuši, kas rakstīts par Viņu, tad Viņu ir noņēmuši no koka un ielikuši kapā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Bet Dievs Viņu ir uzmodinājis no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Un daudz dienas Viņš ir parādījies tiem, kas līdz ar Viņu bija nākuši uz Jeruzālemi un kas tagad ir Viņa liecinieki pie tiem ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Un mēs arīdzan jums pasludinājām to evaņģēliju par to apsolīšanu, kas tiem tēviem notikusi, ka Dievs mums, viņu bērniem, to ir piepildījis, Jēzu uzmodinādams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Kā arī otrā Dāvida dziesmā ir rakstīts: “Tu esi Mans Dēls, šodien Es Tevi esmu dzemdinājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Bet ka Viņš To no miroņiem ir uzmodinājis, ka Tam vairs nebija satrūdēt, Viņš tā ir sacījis: “Es jums došu to Dāvidam solīto pastāvīgo žēlastību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Tāpēc viņš arī citā vietā saka: “Tu Savam Svētam nedosi redzēt satrūdēšanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Jo Dāvids, savā laikā Dieva prātam kalpojis, ir aizmidzis un pie saviem tēviem noguldīts un satrūdēšanu redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Bet Tas, ko Dievs ir uzmodinājis, Tas satrūdēšanu nav redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Tad nu lai jums ir zināms, vīri, brāļi, ka caur Viņu jums grēku piedošana top pasludināta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'Un no visa tā, no kā jūs caur Mozus bauslību nevarējāt taisnoti tapt, ikviens, kas tic, caur Šo top taisnots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Tāpēc pielūkojiet, ka pār jums nenāk, kas ir sacīts iekš tiem praviešiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '“Raugāt, jūs pulgotāji, un brīnāties un iznīkstiet, jo Es kādu darbu padaru jūsu dienās, tādu darbu, ko jūs neticēsiet, ja kāds jums to stāsta.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Un kad tie Jūdi bija izgājuši no baznīcas, tad tie pagāni lūdza, nākošā svētdienā viņiem šos vārdus runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Un kad tā draudze tapa atlaista, tad daudz Jūdi un dievbijīgi Jūdu ticības biedri Pāvilam un Barnabam gāja pakaļ; šie tos pamācīja un paskubināja palikt Dieva žēlastībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Un nākošā svētdienā tik ne visa tā pilsēta sapulcējās, Dieva vārdu dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Bet tie Jūdi, to ļaužu pulku redzēdami, tapa naida pilni un runāja tam pretī, ko Pāvils sacīja; pretī runādami un zaimodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Bet Pāvils un Barnaba ar drošību sacīja: tas Dieva vārds papriekš uz jums bija jārunā, bet kad jūs to atmetat un sev pašus necienīgus turat mantot mūžīgu dzīvošanu, redzi, tad mēs griežamies pie tiem pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Jo tā Tas Kungs mums ir pavēlējis: “Es tevi esmu iecēlis pagāniem par gaišumu, ka tu būtu tā pestīšana līdz pasaules galam.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Kad nu tie pagāni to dzirdēja, tad tie priecājās un slavēja Tā Kunga vārdu, un ticēja, cik uz mūžīgu dzīvošanu bija izredzēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Un Tā Kunga vārds izpaudās pa visu to tiesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Bet tie Jūdi skubināja dievbijīgas sievas no augstas kārtas un tās pilsētas virsniekus un cēla vajāšanu pret Pāvilu un Barnabu un tos izdzina no savām robežām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Bet tie tos pīšļus nokratīja no savām kājām pret tiem un nāca uz Ikoniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Un tie mācekļi tapa piepildīti ar prieku un ar Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Un notikās Ikonijā, ka tie kopā iegāja Jūdu baznīcā un tā runāja, ka no tiem Jūdiem un Grieķiem liels pulks ticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Bet tie neticīgie Jūdi paskubināja un iekaitināja pagāniem sirdis pret tiem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Tad nu tie labu laiku tur palika un droši runāja, paļaudamies uz To Kungu, kas Savam žēlastības vārdam liecību deva un lika zīmēm un brīnumiem notikt caur viņu rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Un tās pilsētas ļaudis šķīrās: citi bija ar tiem Jūdiem un citi ar tiem apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Bet kad tur dumpis cēlās no pagāniem un Jūdiem līdz ar viņu virsniekiem, ka tie viņiem varu darītu un tos akmeņiem nomētātu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Tad viņi to nomanīdami bēga uz Likaonijas pilsētām, Listru un Derbi, un uz tām apkārtējām vietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Un tur viņi evaņģēliju sludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Un kāds vīrs Listrā sēdēja ar nespēcīgām kājām, tizls no mātes miesām, kas vēl nekad nebija staigājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Tas dzirdēja Pāvilu runājam. Un šis viņu uzlūkodams nomanīja, ka viņš ticēja un ka viņu var glābt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Sacīja ar stipru balsi: “Celies stāvu uz savām kājām!” Un viņš uzlēca un staigāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Un kad tie ļaudis redzēja, ko Pāvils bija darījis, tad tie pacēla savu balsi un sacīja Likaoniski: “Dievi palikuši cilvēkiem līdzīgi un pie mums zemē nonākuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Un tie sauca Barnabu par Jupiteru un Pāvilu par Merkuriju: tāpēc ka viņš bija tas runātājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Un Jupitera priesteris, kas bija ārpus pilsētas, atveda vēršus un vainagus pie vārtiem un gribēja ar tiem ļaudīm upurēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Bet tie apustuļi Pāvils un Barnaba to dzirdēdami, saplēsa savas drēbes un ieskrēja ļaužu vidū saukdami');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Un sacīdami: “Vīri, kāpēc jūs tā darāt? Mēs arīdzan esam tādi pat mirstami cilvēki kā jūs, kas jums to evaņģēliju sludinām, ka jums no šiem nelietīgiem būs atgriezties pie Tā dzīvā Dieva, kas ir radījis debesi un zemi un jūru un visu, kas tur iekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Kas pagājušos laikos visiem pagāniem ļāvis staigāt pa saviem ceļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Jebšu Viņš Sevi nav pametis neapliecinātu, labu darīdams, no debesīm mums lietu un auglīgus laikus dodams, mūsu sirdis ar barību un ar prieku pildīdams.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Un to runādami, tie ar mokām nomierināja tos ļaudis, ka tie viņiem neupurēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Bet no Antioķijas un Ikonijas Jūdi pienāca un tos ļaudis pārrunāja un Pāvilu akmeņiem mētāja, un to no pilsētas vilka ārā, domādami, viņu esam nomirušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Bet kad tie mācekļi ap viņu bija sanākuši, tad viņš uzcēlās un iegāja pilsētā; un otrā dienā viņš izgāja ar Barnabu uz Derbi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Un tai pilsētā evaņģēliju pasludinājuši un labu pulku par mācekļiem darījuši, tie griezās atpakaļ uz Listru un Ikoniju un Antioķiju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Stiprinādami mācekļu dvēseles un pamācīdami, lai paliek iekš ticības, un ka caur daudz bēdām mums būs ieiet Dieva valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Un tie viņiem ikvienā draudzē iecēla vecajus un ar gavēšanu Dievu lūguši tos pavēlēja Tam Kungam, uz ko tie bija ticējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Un pārstaigājuši Pisidiju, tie nāca uz Pamfiliju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Un Pergā to vārdu runājuši, tie nonāca uz Attaliju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Un no turienes tie nocēlās uz Antioķiju, no kurienes tie Dieva žēlastībai bija pavēlēti uz to darbu, ko bija pabeiguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Un tur nonākuši un to draudzi sapulcējuši, tie stāstīja, kādas lietas Dievs pie tiem bija darījis, un ka Viņš pagāniem ticības durvis bija atvēris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Un tie tur palika labu laiku pie tiem mācekļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Un kādi no Jūdu zemes nākuši mācīja tos brāļus: ja jūs netopat apgraizīti pēc Mozus bauslības, tad jūs nevarat tapt pestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Kad nu Pāvilam un Barnabam liela šķelšanās un apjautāšanās ar viņiem cēlās, tad nosprieda, lai Pāvils un Barnaba un vēl citi kādi no tiem ietu pie tiem apustuļiem un vecajiem uz Jeruzālemi šās jautāšanas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Tad nu no tās draudzes pavadīti tie gāja caur Feniķiju un Samariju; un par pagānu atgriešanos stāstīdami, tie visiem brāļiem darīja lielu prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Un uz Jeruzālemi nākuši, tie tapa uzņemti no tās draudzes un tiem apustuļiem un tiem vecajiem, un pasludināja, kādas lietas Dievs ar tiem bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Bet no tās farizeju šķiras kādi cēlās, kas bija tapuši ticīgi, sacīdami: “Tos būs apgraizīt un tiem būs pavēlēt, Mozus bauslību turēt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Un tie apustuļi un vecaji sapulcējās, spriest par šo vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Bet kad daudz apjautāšanās notika, tad Pēteris cēlās un uz tiem sacīja: “Vīri, brāļi, jūs zināt, ka Dievs pagājušos laikos mūsu starpā ir izvēlējis, ka caur manu muti pagāni evaņģēliju dzirdētu un ticētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Un Dievs, tas siržu manītājs, tiem liecību ir devis, tā Svēto Garu tiem dodams, tā kā mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Un nekādu starpību nav darījis starp mums un viņiem, viņu sirdis šķīstīdams caur ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Tad nu ko jūs Dievu kārdināt, uz mācekļu kaklu likdami jūgu, ko nedz mūsu tēvi, nedz mēs nespējam panest?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Bet caur Tā Kunga Jēzus Kristus žēlastību mēs ticam tapt izglābti, tā kā arī viņi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Un viss tas pulks cieta klusu un klausījās, kā Barnaba un Pāvils stāstīja, kādas zīmes un brīnumus Dievs caur viņiem bija darījis pie pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Un kad šie beidza runāt, tad Jēkabs atbildēja sacīdams: “Vīri, brāļi, klausiet mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Sīmanis ir stāstījis, kā Dievam pirmoreiz paticis no pagāniem ļaudis pieņemt pie Sava vārda;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Un ar to praviešu vārdi saskan, kā ir rakstīts:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '“Pēc tam Es atgriezīšos un atkal uzcelšu Dāvida sagruvušo dzīvokli, un kas pie tā izlauzts, to Es atkal uztaisīšu un uzcelšu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Lai tie atlikušie cilvēki To Kungu meklē, arī visi pagāni, pār kuriem Mans vārds ir piesaukts, - tā saka Tas Kungs, kas to visu dara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Dievam visi Savi darbi ir zināmi no mūžības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Tāpēc es spriežu, ka tos nebūs apgrūtināt, kas no pagāniem pie Dieva atgriežas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Bet ka tiem būs rakstīt, lai sargās, ka neapgānās ar elka dieviem un maucību un nožņaugto un asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Jo Mozum ir no veciem laikiem pa visām pilsētām savi sludinātāji, un viņš ik svētdienas top lasīts baznīcās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Tad tiem apustuļiem un vecajiem un visai draudzei patika, no viņiem izvēlētus vīrus ar Pāvilu un Barnabu uz Antioķiju sūtīt: Jūdu, ar pavārdu Barsaba, un Sīlāsu, vīrus, kas bija augstā godā pie tiem brāļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Un caur viņu rokām tā rakstīt: “Tie apustuļi un tie vecaji un tie brāļi prieku vēlē tiem brāļiem, kas pagāni bijuši un ir Antioķijā un Sīrijā un Ķiliķijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Kad mēs esam dzirdējuši, ka kādi no mums izgājuši, jūs ar vārdiem sajaukt un jūsu dvēseles darīt šaubīgas, sacīdami, ka jums būs likties apgraizīties un bauslību turēt, kuriem mēs to neesam pavēlējuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Tad mēs vienis prātis palikuši nospriedām, izvēlētus vīrus pie jums sūtīt ar Barnabu un Pāvilu, mūsu mīļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Kas savas dvēseles ir nodevuši par mūsu Kunga Jēzus Kristus vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Tad mēs Jūdu un Sīlasu esam sūtījuši, kas to pašu arī ar vārdiem pasacīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Jo tam Svētam Garam un mums ir paticis, jums nekādu nastu vairāk neuzlikt, kā vien šīs vajadzīgas lietas:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Ka jums būs sargāties no elkadievu upuriem un no asinīm un no nožņaugtā un no maucības; kad jūs no šīm lietām sargāsities, tad jūs labi darīsiet. Dzīvojiet veseli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Tad nu tie tapa atlaisti un nāca uz Antioķiju, un to draudzi sapulcējuši, iedeva to grāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Un to lasījuši šie priecājās par to iepriecināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Bet Jūda un Sīlas, kas paši arīdzan bija pravieši, tos brāļus pamācīja ar daudz vārdiem un tos stiprināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Un kādu laiku tur palikuši, tie no tiem brāļiem ar mieru tapa atlaisti pie tiem apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '(Un Sīlasam patika tur palikt.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Bet Pāvils un Barnaba palika Antioķijā, ar daudz citiem mācīdami un Tā Kunga vārdu sludinādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Un pēc kādām dienām Pāvils sacīja uz Barnabu: “Iesim atkal un pa visām pilsētām, kur Tā Kunga vārdu esam sludinājuši, apraudzīsim savus brāļus, kā tiem klājas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Un Barnaba deva to padomu, Jāni, kas top saukts Marks, ņemt līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Bet Pāvils negribēja tādu līdz ņemt, kas no viņiem bija atkāpies Pamfilijā un ar viņiem nebija līdz gājis pie darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Par to notika sariebšanās, tā ka tie viens no otra šķīrās, un ka Barnaba ņēma līdz Marku un pārcēlās uz Kipru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Bet Pāvils Sīlasu izvēlējies izgāja, Dieva žēlastībai no tiem brāļiem pavēlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Un viņš pārstaigāja Sīriju un Ķiliķiju, tās draudzes stiprinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Un viņš nāca uz Derbi un Listru. Un redzi, tur bija viens māceklis, vārdā Timotejs, ticīgas Jūdu sievas dēls, bet no Grieķu tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Šim laba liecība tika dota no tiem brāļiem Listrā un Ikonijā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Pāvils gribēja, ka šis viņam ietu līdz; un viņš to ņēma un apgraizīja to Jūdu dēļ kas tanīs vietās bija, jo visi zināja, ka viņa tēvs bijis Grieķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Un kad tie pārstaigāja tās pilsētas, tad tie viņiem pavēlēja, tos likumus sargāt, ko tie apustuļi un vecaji Jeruzālemē bija nosprieduši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Tad nu tās draudzes tapa stiprinātas iekš ticības, un viņu pulks jo dienas vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Un tiem caur Friģiju un Galatiju ejot tapa aizliegts no Tā Svētā Gara, to vārdu iekš Āzijas runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Mizijā nākuši tie raudzīja uz Bitiniju iet, bet Tas Gars tiem neļāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Un gar Miziju gājuši tie nonāca uz Troādu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Un Pāvils naktī redzēja parādīšanu: viens Maķedoniets stāvēja, viņu lūgdams un sacīdams: “Nāc uz Maķedoniju un palīdzi mums.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Un kad viņš to parādīšanu bija redzējis, tad mēs meklējām tūdaļ iziet uz Maķedoniju, nomanīdami, ka Tas Kungs mūs bija aicinājis, tiem evaņģēliju sludināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Tad mēs nocēlušies no Troādas gājām tiešām uz Samotrāķiju un otrā dienā uz Neapoli;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Un no turienes uz Filipiem, kas ir tā lielākā pilsēta kādā Maķedonijas tiesā, kur ienācēji bija apmetušies. Un tanī pilsētā mēs palikām kādas dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Un tai svētā dienā mēs izgājām no pilsētas ārā gar upes malu, kur tie bija ieraduši Dievu lūgt. Un apsēdušies mēs runājām uz tām sanākušām sievām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Un viena sieva, ar vārdu Lidija, purpura pārdevēja no Tiatiras pilsētas, dievbijīga sieva, klausījās. Tai Tas Kungs sirdi atdarīja, ņemt vērā, ko Pāvils runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Un kad tā ar savu namu bija kristīta, tad tā lūdza sacīdama: “Ja jums šķiet, ka esmu ticīga uz To Kungu, tad nāciet manā namā un paliekat tur.” Un tā mūs piespieda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Bet notikās, mums ejot Dievu lūgt, viena meita mūs sastapa; tai bija zīlētāja gars, un ar zīlēšanu tā saviem kungiem daudz peļnas pienesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Šī Pāvilam un mums gāja pakaļ un brēca sacīdama: “Šie cilvēki ir Dieva, Tā Visu Augstākā, kalpi, kas jums pestīšanas ceļu sludina.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Un to viņa darīja daudz dienas. Bet Pāvilam tas bija pretī un atgriezdamies tas uz to garu sacīja: “Jēzus Kristus vārdā es tev pavēlu iziet no tās.” Un viņš no tās izgāja tanī pašā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Bet viņas kungi redzēdami, ka viņu peļņas cerība bija zudusi, ņēma Pāvilu un Sīlasu un tos vilka uz tirgu pie tiem virsniekiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Un tos pieveduši pie tiem valdītājiem, viņi sacīja: “Šie cilvēki mūsu pilsētu sajauc, Jūdi būdami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Un sludina ierašas, ko mums, kas esam Romieši, neklājās nedz pieņemt, nedz darīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Un tas ļaužu pulks cēlās pret tiem, un tie virsnieki tiem noplēsa drēbes un pavēlēja, tos ar rīkstēm šaust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Un daudz sitienus tiem devuši, viņi tos iemeta cietumā, un cietuma sargam pavēlēja, tos cieti sargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Šis tādu pavēli dabūjis, tos iemeta tai dziļākā cietumā un viņu kājas apcietināja siekstā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Un ap nakts vidu Pāvils un Sīlas Dievu lūdza un slavas dziesmas dziedāja, un tie, kas bija cietumā, uz viņiem klausījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Tad piepeši liela zemes trīcēšana notika, tā ka cietuma pamati kustēja, un tūdaļ visas durvis atvērās, un visiem saites tapa vaļā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Un tas cietuma sargs uzmodies un cietuma durvis redzējis atvērtas, izvilka zobenu un gribēja sevi pašu nonāvēt, domādams, tos cietumniekus esam izbēgušus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Bet Pāvils ar stipru balsi brēca sacīdams: “Nedari sev ļauna, jo mēs visi esam šeitan.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Un viņš sveci prasījis, ieskrēja un drebēdams metās zemē priekš Pāvila un Sīlasa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Un tos izveda ārā un sacīja: “Kungi, ko man būs darīt, lai es mūžīgi dzīvoju?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Un tie sacīja: “Tici uz To Kungu Jēzu Kristu, tad tu un viss tavs nams mūžīgi dzīvos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Un tie runāja Tā Kunga vārdu uz viņu un uz visiem, kas bija tanī namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Un viņš tos uzņēma tanī pašā nakts stundā un tiem brūces nomazgāja; un tūdaļ viņš tapa kristīts, pats un visi viņa piederīgie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Un viņš tos veda savā namā, tos sēdināja pie galda un priecājās, ka viņš ar visu savu namu bija nācis pie ticības uz Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Kad nu gaisma bija aususi, tad tie virsnieki sūtīja sulaiņus, un lika sacīt: “Palaid šos cilvēkus.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Un tas cietuma sargs Pāvilam pasludināja šos vārdus: “Tie virsnieki sūtījuši, lai jūs atlaiž. Tad nu izejiet un staigājiet ar mieru.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Bet Pāvils uz tiem sacīja: “Tie mūs, Romiešu cilvēkus, netiesātus visiem redzot ir šautuši un cietumā iemetuši, un tagad tie mūs slepeni izmet? Tā ne; bet lai viņi paši nāk un mūs izved.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Un tie sulaiņi atsacīja šos vārdus tiem virsniekiem: un tie bijās, dzirdēdami, tos esam Romiešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Un nākuši viņi tos pārrunāja un tos izveda un lūdza, iziet no tās pilsētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Un tie no cietuma izgājuši, nogāja pie tās Lidijas; un tos brāļus redzējuši, tie tos pamācīja un aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Un caur Amfipoli un Apoloniju gājuši tie nāca uz Tesaloniku: tur bija viena Jūdu baznīca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Un Pāvils pēc sava ieraduma pie tiem iegāja un trijās svētās dienās ar tiem sarunājās par tiem rakstiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Tos izstāstīdams un viņiem priekšā likdams, ka Kristum bija ciest un augšām celties no miroņiem, un sacija: “Šis ir Tas Kristus Jēzus, ko es jums pasludināju.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Un kādi no tiem tapa pārliecināti un piebiedrojās Pāvilam un Sīlasam, un no tiem dievbijīgiem Grieķiem liels pulks un laba tiesa sievu no augstas kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Bet tie neticīgie Jūdi, skaudības pilni, ņēma pie sevis kādus saskrējušus neliešus un sapulcinājās un cēla troksni tai pilsētā; un Jazona namu apstājuši, meklēja tos vest priekš tā ļaužu pulka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Bet tos neatraduši, tie Jazonu un citus brāļus vilka pie pilsētas virsniekiem brēkdami: “Tie, kas visu pasauli ar dumpi pilda, tie arī šurp ir nākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Tos Jazons ir uzņēmis; un šie visi dara pret ķeizara pavēlēm sacīdami: citu esam ķēniņu - Jēzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Un tie iztrūcināja tos ļaudis un tos pilsētas virsniekus, kas to dzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Bet šie, aizbildināšanu no Jazona un tiem dabūjuši, tos palaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Bet tie brāļi tūdaļ naktī Pāvilu un Sīlasu izvadīja uz Bereju; tie tur nonākuši iegāja Jūdu baznīcā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Un šie bija labvēlīgāki pār tiem Tesalonikas Jūdiem un to vārdu uzņēma ar visu labu prātu, meklēdami ikdienas rakstos, vai šās lietas tā esot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Tad nu daudzi no tiem ticēja, arī no Grieķu augstas kārtas sievām un vīriem laba tiesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Un kad tie Tesalonikas Jūdi dabūja zināt, ka arī Berejā Dieva vārds no Pāvila tapa sludināts, tad tie nāca arī uz turieni un tos ļaudis skubināja uz dumpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Bet tie brāļi tūdaļ Pāvilu izsūtīja, ka tas noietu uz jūru, bet Sīlas un Timotejs tur palika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Bet tie, kas Pāvilu pavadīja, to veda līdz Atēnai, un pavēli priekš Sīlasa un Timoteja dabūjuši, lai šie arīdzan pie viņa nāktu, tie aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Un kamēr Pāvils viņus gaidīja Atēnā, viņa gars iekš viņa iedegās, kad viņš redzēja to pilsētu tik elkadievīgu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Tad nu viņš baznīcā sarunājās ar tiem Jūdiem un tiem dievbijīgiem, un tirgū ikdienas ar tiem, kas piegadījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Un kādi no Epikureju un Stoīku gudriem ar viņu sarunājās; un kādi sacīja: “Ko šis pļāpa grib runāt?” Un citi: “Šis izliekās kā svešu dievu sludinātājs;” tāpēc ka viņš tiem Jēzu un to augšāmcelšanos sludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Un tie viņu ņēma un veda uz tās augstās tiesas vietu, sacīdami: “Vai nevaram dabūt zināt, kāda tā jaunā mācība, ko tu sludini?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Jo tu dažas svešas lietas runā priekš mūsu ausīm, tāpēc mēs gribam zināt, kas tas ir?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Bet visi Atēnieši un tie svešinieki, kas tur piemājoja, ar citu neko to laiku nekavēja, kā vien ko jaunu runāt un dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Un Pāvils stāvēja tās augstās tiesas plača vidū un sacīja: “Jūs Atēniešu vīri, pēc visa es jūs redzu jo dievbijīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Jo staigādams un jūsu svētekļus apraudzīdams, es atradu arī vienu altāri, kam bija virsū rakstīts: nepazīstamam Dievam. Tad nu, ko jūs nepāzīdami godājiet, To es jums pasludināju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Tas Dievs, kas ir radījis pasauli un visu, kas tur iekšā, šis, debess un zemes Kungs būdams, nemājo rokām taisītās baznīcās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Un Viņam arī nenotiek no cilvēku rokām kalpošana, tā kā Viņam ko vajadzētu; bet Viņš pats dod visiem dzīvību un dvašu un visas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Un Viņš ir darījis, ka no vienām asinīm visas cilvēku tautas dzīvo pa visu zemes virsu, un ir nolicis papriekš nospriestus laikus un robežas, kur tiem būs dzīvot,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Ka tie To Kungu meklētu, lai tie Viņu varētu just un atrast, - jebšu Viņš nav tālu no neviena no mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Jo iekš Viņa mēs dzīvojam un kustam un esam; tā kā arī kādi no jūsu dziesminiekiem sacījuši: mēs arī esam Viņa rada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Tad nu mums, kas Dieva rada esam, nebūs domāt, dievību esam līdzīgu zeltam vai sudrabam vai akmenim, kādam caur cilvēka gudrību un izdomāšanu iztaisītam tēlam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Tad nu Dievs tos nezināšanas laikus panesis, tagad pavēl visiem cilvēkiem visās malās no grēkiem atgriezties;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Tāpēc ka Viņš vienu dienu ir nolicis, kur Viņš pasauli tiesās iekš taisnības caur vienu Vīru, ko Viņš uz to izredzējis, visiem ticību pasniegdams, kad Viņš to no miroņiem ir uzmodinājis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Bet kad tie dzirdēja miroņu augšāmcelšanos, tad citi to ņēma smieklā, bet citi sacīja: “Par to mēs tevi vēl kādu citu reiz dzirdēsim.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, '(Tukšs)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Bet kādi vīri tam pieķērās un ticēja. Starp tiem bija Dionisijs, tās augstās tiesas loceklis, un viena sieva, ar vārdu Damare, un vēl citi līdz ar tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Un pēc tam Pāvils aizgāja no Atēnas un nāca uz Korintu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Un atrada kādu Jūdu, ar vārdu Aķilu, pēc dzimtenes no Pontus, kas nesen ar Prisķilu, savu sievu, no Itālijas bija atnācis, (tāpēc ka ķeizars Klaudijs bija pavēlējis, visiem Jūdiem iziet no Romas), un iegāja pie tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Un ar to vienādā amatā būdams viņš pie tiem palika un strādāja; jo tie savā amatā bija telšu taisītāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Un viņš ik svētdienas mācīja baznīcā un pārliecināja gan Jūdus, gan Ģrieķus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Un kad Sīlas un Timotejs no Maķedonijas bija atnākuši, tad Pāvils garā tapa piespiests, tiem Jūdiem apliecināt, ka Jēzus esot Tas Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Bet kad tie turējās pretī un zaimoja, tad viņš drēbes izkratījis uz tiem sacīja: jūsu asinis uz jūsu galvu! Es esmu skaidrs, no šā laika es iešu pie tiem pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Un no turienes aizgājis tas nāca kāda cilvēka namā, kam bija vārds Justs, un tas Dievu bijās, un viņa nams pie baznīcas bija tuvu klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Bet Krispus, tas baznīcas virsnieks, ticēja uz To Kungu ar visu savu namu, un daudz no Korintiešiem, viņu dzirdēdami, ticēja un tapa kristīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Un Tas Kungs naktī caur vienu parādīšanu uz Pāvilu sacīja: “Nebīsties, bet runā un neciet klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Jo Es esmu ar tevi, un neviens necelsies pret tevi, ļaunu tev darīt; jo Man ir daudz ļaužu šinī pilsētā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Un viņš tur sabija gadu un sešus mēnešus, Dieva vārdu pie viņiem mācīdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Un kad Gallions Akajā bija zemes soģis, tad tie Jūdi vienā prātā cēlās pret Pāvilu, un to veda priekš soģa krēsla,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Sacīdami: ‘Šis tos ļaudis pārrunā Dievam kalpot pret bauslību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Bet kad Pāvils muti gribēja atvērt, Gallions uz tiem Jūdiem sacīja: “Ja tur būtu kāds netaisns darbs jeb blēņu lieta, jūs Jūdi, tad es jūs labprāt klausītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Bet kad nu jautāšana ir par mācību un vārdiem un bauslību, kas jums ir, tad lūkojiet jūs paši, jo es par to negribu būt tiesātājs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Un viņš tos dzina nost no soģa krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Bet visi Grieķi ņēma Sostenu, to baznīcas virsnieku, un to kūla priekš soģa krēsla, un Gallions par to neko nebēdāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Un Pāvils vēl daudz dienas tur palicis, no tiem brāļiem atvadījās, un cēlās pāri uz Sīriju, un līdz ar viņu Prisķila un Aķila, kas Kenhrejā savu galvu bija apcirpis: jo to bija solījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Un viņš nonāca uz Efesu un tos tur atstāja, bet pats iegāja baznīcā un sarunājās ar tiem Jūdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Un kad tie viņu lūdza, ilgāki pie tiem palikt, tad viņš negribēja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Bet šķīrās no tiem sacīdams: “Nākamie svētki man visādā vīzē jāsvētī Jeruzālemē, bet es atkal atgriezīšos pie jums, ja Dievs grib;” un viņš aizcēlās no Efesus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Un uz Cezareju nācis viņš nogāja un apsveicināja to draudzi un devās uz Antioķiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Un tur kādu laiku palicis, viņš izgāja un pēc kārtas pārstaigāja Galatijas un Friģijas tiesu un stiprināja visus mācekļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Bet viens Jūdu vīrs, ar vārdu Apollus, dzimis Aleksandriets, vīrs, varens vārdos, nonāca uz Efesu; tas bija spēcīgs rakstos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Šis bija mācīts Tā Kunga ceļā, un karstā garā tas runāja un mācīja skaidri visu no Tā Kunga, jebšu viņš Jāņa kristību vien pazina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Un tas iesāka droši runāt baznīcā. Un viņu dzirdējuši, Aķila un Prisķila viņu ņēma pie sevis un viņam vēl skaidrāki Tā Kunga ceļu izstāstīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Un kad viņš gribēja noiet uz Akaju, tad tie brāļi tos mācekļus lūdza caur rakstiem, lai viņu uzņem; šis tur nonācis, daudz ir palīdzējis tiem, kas caur žēlastību ticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Jo viņš tos Jūdus stipri pārliecināja, visu ļaužu priekšā no tiem rakstiem pierādīdams, ka Jēzus ir Tas Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Un kamēr Apollus Korintū bija, notikās, ka Pāvils, tās augšzemes vietas pārstaigājis, nāca uz Efesu, un kādus mācekļus atradis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Viņš uz tiem sacīja: “Vai jūs Svēto Garu esat dabūjuši, kad jūs tapāt ticīgi?” Bet tie uz viņu sacīja: “Mēs neesam ne dzirdējuši, ka Svēts Gars ir.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Un viņš uz tiem sacīja: “Uz ko tad jūs esat kristīti?” Un tie sacīja: “Uz Jāņa kristību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Bet Pāvils sacīja: “Jānis ir kristījis ar to kristību uz atgriešanos no grēkiem, tiem ļaudīm sacīdams, lai tic uz To, kas nākšot pēc viņa, tas ir, uz Kristu Jēzu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Un to dzirdējuši tie tapa kristīti uz Tā Kunga Jēzus vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Un kad Pāvils tiem rokas uzlika, tad Svētais Gars uz tiem nāca, un tie runāja valodām un sludināja praviešu mācības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Un visi tie vīri bija kādi divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Bet viņš baznīcā iegājis, droši mācīja kādus trīs mēnešus, sarunādamies un tos pārliecinādams par Dieva valstības lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Un kad citi bija apcietināti un nepaklausīgi un par šo ceļu ļaužu priekšā nelabi runāja, tad viņš no tiem atstājās un atšķīra tos mācekļus, ikdienas sarunādamies kādā Tiranna skolā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Un tā tas gāja divus gadus, tā ka visi, kas Āzijā dzīvoja, Tā Kunga Jēzus vārdu dzirdēja, gan Jūdi, gan Grieķi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Un Dievs lielus darbus darīja caur Pāvila rokām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Tā ka arī sviedru auti un citi auti no viņa miesām tapa nesti pie neveseliem; un slimības tos atstāja, un ļaunie gari no tiem izgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Un kādi no tiem Jūdiem, kas bija velnu izdzinēji un apkārt vazājās, uzdrīkstējās Tā Kunga Jēzus vārdu saukt pār tiem, kam bija ļauni gari, sacīdami: mēs jūs apdraudam no tā Jēzus puses, ko Pāvils sludina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Tie nu, kas šo darīja, bija Sķevasa, Jūdu augstā priestera, septiņi dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Un tas ļaunais gars atbildēja un sacīja: “To Jēzu es pazīstu un to Pāvilu es zinu; bet jūs, kas jūs tādi esat?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Un tas cilvēks, kam tas ļaunais gars bija, tiem uzlēca un tos pievarēdams tā darīja, ka tiem bija kailiem un ievainotiem jāizbēg no tā nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Un tas tapa zināms visiem Jūdiem un Grieķiem, kas Efesū dzīvoja; un visiem bailes uzgāja, un Tā Kunga Jēzus vārds tapa augsti teikts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Un daudzi no tiem, kas bija palikuši ticīgi, nāca un izteica un izsūdzēja savus nedarbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Un daudzi no tiem, kas māņu darbus bija darījuši, tās grāmatas kopā sanesa un sadedzināja visiem redzot; un viņu vērtību aprēķināja un saskaitīja piecdesmit tūkstošus sudraba grašus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tik varen auga un uzvarēja Tā Kunga vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Un pēc šiem notikumiem Pāvils garā apņēmās pārstaigāt Maķedoniju un Akaju un iet uz Jeruzālemi, sacīdams: “Pēc tam, kad tur būšu bijis, man arī Roma jāredz.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Un uz Maķedoniju divus sūtījis, kas viņam kalpoja, Timoteju un Erastu, viņš pats kādu brīdi palika iekš Āzijas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Bet ap to laiku liels troksnis cēlās šīs mācības dēļ');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Jo viens, ar vārdu Demeteris, sudraba kalējs, no sudraba taisīja Dianas namiņus un gādāja tiem amata meistariem lielu peļņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Šos, un šī amata strādniekus sapulcējis, viņš sacīja: “Vīri, jūs zināt: ka no šā darba mums ir sava pārtikšana;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Un jūs redzat un dzirdat, ka šis Pāvils ne vien Efesū, bet tik ne pa visu Āziju lielu pulku pārrunādams ir novērsis, sacīdams, ka tie nav dievi, kas rokām taisīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Un tas ne vien mums tā var padarīt, ka šī mūsu peļņa ies mazumā, bet arī ka tās augstās dieves Dianas nams taps nievāts, un arī viņas augstība iznīks, kam taču visa Āzija un pasaule kalpo.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Bet to dzirdēdami, tie tapa dusmības pilni un sauca, sacīdami: “Augsta ir Efesiešu Diana.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Un visa tā pilsēta tapa trokšņa pilna, un tie skrēja vienprātīgi uz teātri, līdz raudami tos Maķedoniešus Gaju un Aristarku, Pāvila ceļa biedrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Un kad Pāvils gribēja iet pie tiem ļaudīm, tad tie mācekļi viņam to neļāva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Bet arī kādi no Āzijas virsniekiem, viņa draugi būdami, pie tā sūtīja lūgdami, ka tas nedotos uz teātri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Tad nu citi sauca šā, citi tā, jo tā draudze bija sajukusi, un tas lielais pulks nezināja, kādēļ kopā bija sanākuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Un Aleksandru no tā pulka izvilka, kad tie Jūdi viņu uz priekšu stūma; un Aleksandrs meta ar roku, gribēdams priekš tiem ļaudīm aizbildināties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Bet kad tie nomanīja, viņu esam Jūdu, tad visi vienā balsī sauca ap divām stundām: “Augsta ir Efesiešu Diana.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Un kad tās pilsētas rakstuvedējs to pulku bija klusinājis, tad viņš sacīja: “Jūs Efesus vīri, kurš cilvēks nezina, Efesus pilsētu esam tās augstās dieves Dianas un tā no debess kritušā tēla kopēju?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Kad nu šīm lietām neviens nevar pretī runāt, tad jums pienākas ar mieru būt un nenieka aplam nedarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Jo jūs šos vīrus esat atveduši, kas nav nedz tās svētās vietas laupītāji nedz jūsu dievietes zaimotāji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Ja tad nu Demeterim un tiem amata vīriem kāda lieta ir pret kādu, tad tiesas dienas top turētas un zemes soģi ir, lai viņi tur savā starpā sūdzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Bet ja jūs citu kādu lietu meklējiet, tad lai sapulcējās pēc likuma un lai iztiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Jo mēs esam tai likstā, ka par to, kas šodien noticis, varam tikt apsūdzēti dumpja dēļ, un tomēr nekādas vainas nav, ar ko šo dumpi varētu aizbildināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Un to sacījis, viņš tos ļaudis atlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Un pēc, kad troksnis bija klusināts, Pāvils tos mācekļus saaicināja un tos sveicinājis izgāja un devās uz Maķedoniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Un pārstaigājis to vidu un ar daudz vārdiem tos pamācījis, viņš nāca Grieķu zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Un tur kādus trīs mēnešus palicis viņš gribēja pārcelties uz Sīriju; bet kad tie Jūdi uz viņu glūnēja, tad viņš apņēmās, atpakaļ griezties caur Maķedoniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Un viņu pavadīja līdz Āzijai Sopaters no Berejas, bet no Tesaloniķiešiem Aristarks un Sekunds, un Gajus no Derbes, un Timotejs, no Āzijas Tihiks un Trofims.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Šie papriekš gājuši mūs gaidīja Troadā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Bet mēs nocēlāmies pēc tām neraudzētas maizes dienām no Filipiem, un nonācām piecās dienās pie tiem uz Troadu, kur mēs septiņas dienas palikām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Bet pirmā nedēļas dienā, kad tie mācekļi bija sanākuši to maizi lauzt, Pāvils ar tiem sarunājās, gribēdams otrā dienā aiziet; un viņš to vārdu mācīja līdz pusnaktij.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Un tur daudz eļļas lukturi bija tanī augšistabā, kur tie bija sapulcējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Un viens jauneklis, ar vārdu Eutiks, sēdēja uz loga un tika no dziļa miega pārņemts, tāpēc ka Pāvils tik ilgi runāja, un no miega pārvarēts tas nokrita no trešā stāva un tapa uzcelts nedzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Bet Pāvils nokāpis uzmetās uz viņu un to apkampa sacīdams: “Nedariet troksni, jo tā dvēsele ir iekš viņa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Un viņš uzkāpa un to maizi lauzis un baudījis vēl labu laiku līdz gaismai sludināja Dieva vārdu un viņš aizgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Un tie to jaunekli atveda dzīvu un tapa ļoti iepriecināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Bet mēs laivā gājuši papriekš nocēlāmies uz Assonu, gribēdami tur Pāvilu uzņemt; jo tā viņš bija pavēlējis, gribēdams pats kājām iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Un kad viņš Assonā ar mums satikās, tad mēs viņu uzņēmām un nācām uz Mitileni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Un no turienes nocēlušies mēs nācām otrā dienā pret Hiju, un dienu vēlāk mēs piestājām Samus malā, un tad palikām Troģillā un nācām otrā dienā uz Mileti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Jo Pāvils bija apņēmies Efesum garām celties, ka viņš laiku nekavētu iekš Āzijas, jo viņš steidzās, ja to paspētu, uz vasaras svētkiem tikt Jeruzālemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Bet viņš sūtīja no Miletes uz Efesu un ataicināja tās draudzes vecajus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Un kad tie pie viņa nāca, viņš uz tiem sacīja: “Jūs zināt no tās pirmās dienas, kur es uz Āziju nācis, kāds es pa visu to laiku pie jums esmu bijis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Tam Kungam kalpodams ar visu pazemību un ar daudz asarām un kārdināšanām, kas man notikušas caur Jūdu viltībām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Ka es nenieka neesmu paslēpis no visa tā, kas jums par labu, ka jums to nebūtu pasludinājis un mācījis, tā draudzē, kā pa mājām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Apliecinādams tik pat Jūdiem kā arī Grieķiem atgriešanos pie Dieva un ticību uz mūsu Kungu Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Un nu redzi, es garā saistīts eju uz Jeruzālemi, nezinādams, kas man tur notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Tomēr Svētais Gars ikvienā pilsētā liecību dod sacīdams, ka saites un bēdas mani gaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Bet es neko par to nebēdāju, un mana dzīvība man pašam nav dārga, ka nepabeigtu ar prieku savu amatu, ko es esmu dabūjis no Tā Kunga Jēzus, apliecināt to evaņģēliju no Dieva žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Un nu redzi, es zinu, ka jūs manu vaigu vairs neredzēsiet, jūs visi, pie kuriem es esmu staigājis, Dieva valstību sludinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Tāpēc es jūsu priekšā apliecināju šinī pašā dienā, ka es skaidrs esmu no visu asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Jo es neesmu atrāvies, ka jums nebūtu pasludinājis visu Dieva padomu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Tāpēc sargājat sevi pašus un visu to ganāmo pulku, pār ko Svētais Gars jūs iecēlis par bīskapiem, Dieva draudzi ganīt, ko Viņš ar Savām paša asinīm atpircis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Jo es to zinu, ka pēc manas aiziešanas plēsīgi vilki pie jums ielauzīsies, kas to ganāmo pulku nesaudzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Un no jums pašiem vīri celsies, negantas lietas runādami, ka tie tos mācekļus novērstu sev pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Tāpēc esiet modrīgi, pieminēdami, ka es trīs gadus naktīm dienām neesmu mitējies ar asarām ikvienu pamācīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Un nu, brāļi, es jūs nododu Dievam un Viņa žēlastības vārdam, kas ir spēcīgs, jūs uztaisīt un jums mantību dot ar visiem svētītiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Sudrabu vai zeltu vai drēbes es no neviena neesmu kārojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Bet jūs paši zināt, ka šās rokas manai vajadzībai un tiem, kas pie manis bija, ir kalpojušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Es jums visas lietas esmu rādījis, ka tā strādājot piederas vājos uzņemt un pieminēt Tā Kunga Jēzus vārdu, jo Viņš ir sacījis: “Svētīgāk ir dot, nekā ņemt.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Un šo sacījis, viņš ceļos metās un līdz ar visiem tiem Dievu pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Bet tur visi gauži raudāja; un tie metās ap Pāvila kaklu un viņu skūpstīja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Visvairāk no sirds sāpēm pārņemti tā vārda dēļ, ko viņš bija sacījis, ka tiem vairs nebūšot viņa vaigu redzēt. Un tie viņu pavadīja uz laivu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Un kad notikās, ka mēs no tiem atšķīrušies, tad mēs braucām taisnā ceļā un nācām uz Kosu un otrā dienā uz Rodu un no turienes uz Pataru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Un laivu atraduši, kas uz Feniķiju pārcēlās, mēs iekāpām un aizcēlāmies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Un kad mēs Kipru ieraudzījām un pa kreiso roku pametām, tad cēlāmies uz Sīriju, un Tīrū mēs laidām pie malas, jo tur tai laivai prece bija jāizkrauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Un mācekļus atraduši, mēs tur palikām septiņas dienas; tie Pāvilam caur to Garu sacīja, lai tas neietu uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Un notikās pēc šīm dienām, tad mēs izgājām un devāmies projām, un tur visi ar sievām un bērniem mūs izvadīja no pilsētas ārā; un mēs pie jūrmalas ceļos metušies Dievu lūdzām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Un kad savā starpā bijām atvadījušies, iekāpām laivā. Bet viņi griezās atpakaļ uz savām mājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Bet mēs joprojām no Tīrus pārcēlušies laidām pie Ptolemajidas malā; un tos brāļus apsveicinājuši, mēs pie tiem palikām vienu dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Bet otrā dienā mēs, kas ap Pāvilu bijām, izgājuši nācām uz Cezareju; un iegājuši evanģelista Filipa namā, (kas bija viens no tiem septiņiem), mēs pie tā palikām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Bet šim bija četras meitas, jumpravas, kas nākošas lietas sludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Un kad mēs kādas dienas tur bijām palikuši, viens pravietis atnāca no Jūdu zemes, ar vārdu Agabs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Un tas nāca pie mums un ņēma Pāvila jostu un saistīja pats sev rokas un kājas sacīdams: “Tā Svētais Gars saka: to vīru, kam šī josta pieder, tāpat tie Jūdi saistīs Jeruzālemē un viņu nodos pagānu rokās.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Un kad mēs to dzirdējām, tad ne vien mēs lūdzām, bet arī tie, kas tai vietā dzīvoja, lai viņš neietu uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Bet Pāvils atbildēja: “Ko jūs darāt, ka raudāt un laužat manu sirdi? Jo es esmu gatavs par Tā Kunga Jēzus vārdu ne vien likties saistīties Jeruzālemē, bet arī mirt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Un kad viņš neļāvās pārrunāties, tad mēs palikām klusu, sacīdami: “Tā Kunga prāts lai notiek.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Pēc šīm dienām mēs sataisījamies un gājām uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Un tur arī kādi mācekļi no Cezarejas mums nāca līdz un mūs veda pie viena veca mācekļa, Mnasona no Kipras, lai pie tā mājotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Un kad nācām uz Jeruzālemi, tad tie brāļi mūs ar mīļu prātu uzņēma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Un otrā dienā Pāvils ar mums nogāja pie Jēkaba; un visi vecaji tur arīdzan sanāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Un viņš tos sveicinājis, pa kārtām stāstīja visu, ko Dievs pie pagāniem caur viņa kalpošanu bija darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Un to dzirdējuši, tie To Kungu teica un uz viņu sacīja: “Brāli, tu redzi, cik tūkstoši Jūdu ir, kas palikuši ticīgi, un visi gauži dzenās pēc bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Un tie par tevi dabūjuši zināt, ka tu visus Jūdus, kas starp pagāniem, mācot atstāties no Mozus, sacīdams, ka tiem nebūs savus bērnus apgraizīt, nedz pēc tām ierašām dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Tādēļ ko tad nu? Tiešām, gan ļaužu pulks sanāks; jo tie dzirdēs tevi esam atnākušu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Tāpēc dari to, ko mēs tev sakām: mums ir četri vīri, tie Dievam ir solījušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Tos ņem pie sevis un šķīsties ar tiem, un izdod par tiem to maksu, ka tie galvu apcērp, un lai visi zin, ka tie nieki, ko tie par tevi dzirdējuši, bet ka arī tu pats bauslību turēdams staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Bet par tiem pagāniem, kas palikuši ticīgi, mēs esam rakstījuši un sprieduši, ka tiem nebūs neko no tādām lietām turēt, kā vien, ka tiem būs sargāties no elkadievu upuriem un no asinīm un no nožņaugtā un no maucības.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tad Pāvils tos vīrus pie sevis ņēmis otrā dienā ar tiem šķīstījās un iegāja Dieva namā, un darīja zināmu, ka šķīstīšanas laiku tur palikšot, tiekams par ikvienu no tiem upura dāvana būšot pienesta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Bet kad tās septiņas dienas jau drīz bija beigtas, tad tie Jūdi no Āzijas, viņu ieraudzīdami Dieva namā, paskubināja visu to pulku un rokas pie viņa pielika,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Saukdami: “Jūs Israēla vīri, nāciet palīgā! Šis ir tas cilvēks, kas visus visās malās māca pret tautu un pret bauslību un pret šo vietu, un turklāt viņš Grieķus ir ievedis Dieva namā un šo svēto vietu apgānījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, '(Jo tie priekš tam Trofimu no Efesus pie viņa bija redzējuši pilsētā un domāja, ka Pāvils to esot ievedis Dieva namā.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Un visa tā pilsēta tapa trokšņa pilna, un tie ļaudis satecēja kopā; un tie grāba un rāva Pāvilu no Dieva nama ārā, un tūdaļ durvis tapa aizslēgtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Un kad tie meklēja viņu nokaut, tad tā ziņa nāca pie tā karapulka virsnieka, ka visa Jeruzāleme esot sajaukta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Šis tūdaļ karavīrus un kapteiņus paņēmis, pie tiem noskrēja, un kad tie to virsnieku un tos karavīrus redzēja, tad tie mitējās Pāvilu sist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tad tas virsnieks piegājis viņu saņēma un pavēlēja, viņu ar divām ķēdēm saistīt, un vaicāja, kas viņš esot un ko esot darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Bet tai pulkā citi sauca šā, citi tā. Kad tas nu tā trokšņa dēļ to lietu skaidri nevarēja saprast, tad tas pavēlēja, viņu vest lēģerī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Un kad viņš pie tām trepēm nāca, tad viņš no tiem karavīriem nešus bija jānes to ļaužu uzmākšanās dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Jo tas ļaužu pulks gāja pakaļ saukdams: “Nost ar viņu!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Un Pāvils, pirms lēģerī tapa ievests, uz to virsnieku saka: “Vai man brīv tev ko sacīt?” Un tas sacīja: “Vai tu proti grieķiski?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Vai tu neesi tas Ēģiptiets, kas priekš šīm dienām dumpi cēlis un tos četrtūkstošus slepkavas uz tuksnesi izvedis?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Bet Pāvils sacīja: “Es esmu Jūdu cilvēks no Tarsus, zināmas Ķiliķijas pilsētas loceklis, es tevi lūdzu, vēli man uz tiem ļaudīm runāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Un kad tas bija atvēlējis, tad Pāvils uz tām trepēm stāvēdams meta tiem ļaudīm ar roku; un kad nu pavisam palika klusu, tad viņš Ebreju valodā tos uzrunāja un sacīja:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '“Vīri, brāļi un tēvi, klausiet tagad manu aizbildināšanos jūsu priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, '(Bet kad tie dzirdēja, viņu Ebreju valodā tos uzrunājam, tad tie palika vēl klusāki. Un viņš sacīja:)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Es esmu Jūdu vīrs, Tarsū, Ķiliķijas zemē, piedzimis, bet šinī pilsētā pie Gamaliēla kājām audzināts, tēvu bauslībā krietni izmācīts, karsts Dieva bauslības aizstāvētājs, tā kā jūs visi šodien esat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Un šim ceļam es esmu pretī turējies līdz nāvei, saistīdams un cietumā nododams vīrus un sievas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Tā kā arī tas augstais priesteris un viss tas vecaju pulks man liecību dod, no kuriem es arī grāmatas uz tiem brāļiem ņēmis, esmu gājis uz Damasku, arī tos, kas tur, saistītus vest uz Jeruzālemi, ka tie taptu mocīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Un notikās, kad es biju uz ceļa un tuvu nācu pie Damaskus ap pusdienas laiku, tad piepeši liels gaišums no debess mani apspīdēja visapkārt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Un es kritu pie zemes un dzirdēju balsi uz mani sakām: “Saul, Saul, ko tu Mani vajā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Bet es atbildēju: “Kas Tu esi, Kungs?” Un Viņš uz mani sacīja: “Es esmu Jēzus no Nacaretes, ko tu vajā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Bet tie, kas man bija līdz, gan redzēja to gaišumu un pārbijās, bet to balsi, kas ar mani runāja, to tie nedzirdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Un es sacīju: “Ko man būs darīt, Kungs?” Un Tas Kungs uz mani sacīja: “Celies un ej uz Damasku, un tur tev sacīs visu, kas tev jādara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Un kad nevarēju redzēt tā spožā gaišuma dēļ tad es no saviem ceļabiedriem pie rokas vests nācu uz Damasku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Bet Ananija, dievbijīgs vīrs pēc bauslības, kam laba slava bija no visiem apkārtējiem Jūdiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Tas pie manis nācis un piestājies sacīja uz mani: “Saul, brāli, skaties uz augšu.” Un es tanī pašā stundā uz viņu skatījos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Un viņš sacīja: “Mūsu tēvu Dievs tevi izvēlējis, Viņa prātu atzīt un To Taisno redzēt un balsi no Viņa mutes dzirdēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Jo tu Viņam būsi par liecinieku pie visiem cilvēkiem par to, ko tu esi redzējis un dzirdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Un nu, ko tu gaidi? Celies un liecies kristīties un liec nomazgāt savus grēkus, Tā Kunga vārdu piesaukdams.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Un notikās, kad es uz Jeruzālemi biju atpakaļ griezies un Dieva namā Dievu pielūdzu, tad garā tapu aizgrābts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Un es Viņu redzēju, un Tas man sacīja: “Steidzies un izej čakli no Jeruzālemes, jo tie nepieņems tavu liecību par Mani.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Un es sacīju: “Kungs, tie zina, ka es Tavus ticīgos cietumā iemetu un pa baznīcām šaustu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Un kad Stefana, Tava liecinieka asinis tapa izlietas, ka es tur arī stāvēju klāt, un tas man patika, un es tās drēbes tiem glabāju, kas viņu nonāvēja.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Un Viņš uz mani sacīja: “Ej! Jo Es tevi izsūtīšu tālu pie pagāniem.””');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Un tie viņu klausījās līdz šiem vārdiem un savas balsis pacēla, sacīdami: “Nost no zemes virsas ar šo tādu, jo tam nebūs dzīvot.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Un kad tie brēca un savas drēbes nosvieda un pīšļus gaisā meta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Tad tas virsnieks pavēlēja, viņu novest uz lēģeri, un sacīja, lai viņu ar sitieniem izvaicā, ka dabūtu zināt, kādēļ tie tā par viņu brēca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Un kad viņu ar siksnām piesēja, tad Pāvils sacīja uz to kapteini, kas tur stāvēja: “Vai jums brīv, vienu Romieti un vēl bez tiesas šaust?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Un tas kapteinis to dzirdējis gāja un tam virsniekam to teica sacīdams: “Ko tu gribi darīt? Jo šis cilvēks ir Romietis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Tad tas virsnieks piegāja un uz viņu sacīja: “Saki man, vai tu esi Romietis?” Un tas sacīja: “Esmu gan.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Un tas virsnieks atbildēja: “Es par lielu maksu šo pilsētnieka tiesu esmu iedabūjis.” Bet Pāvils sacīja: “Bet es tāds jau esmu piedzimis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Un tūdaļ tie no viņa atkāpās, kas viņu gribēja izvaicāt. Un tas virsnieks bijās, ka dabūjis zināt, viņu esam Romieti, un ka viņu bija sējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Bet kad otrā dienā to gribēja skaidri zināt, kādēļ viņš no tiem Jūdiem apsūdzēts, tad viņš to atraisīja un pavēlēja, ka tie augstie priesteri un visa viņu augstā tiesa nāktu kopā, un Pāvilu novedis, viņš tiem to stādīja priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Un Pāvils, acis uz to tiesu metis, sacīja: “Vīri, brāļi, es ar visai labu zināmu sirdi Dieva priekšā esmu dzīvojis līdz šai pašai dienai.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Bet tas augstais priesteris Ananija pavēlēja tiem, kas pie viņa stāvēja, viņam par muti sist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Tad Pāvils uz to sacīja: “Dievs tevi sitīs, tu nobaltēta siena! Tu še sēdi, mani tiesāt pēc bauslības, un tu pavēli, mani sist pret bauslību!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Un tie, kas tur klāt stāvēja, sacīja: “Vai tu to augsto Dieva priesteri lamā?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Un Pāvils sacīja: “Es nezināju, brāļi, viņu esam augsto priesteri, jo ir rakstīts: pret savu ļaužu virsnieku tev nebūs ļaunu runāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Bet Pāvils zinādams, ka citi bija no saducejiem, citi no farizejiem, sauca augstās tiesas priekšā: “Vīri, brāļi, es esmu farizeja dēls, es topu tiesāts par to cerību, ka miroņi augšām celsies.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Kad viņš to bija runājis, tad troksnis cēlās starp tiem farizejiem un saducejiem, un tas pulks šķīrās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Jo tie saduceji saka: augšāmcelšanās neesot, un neesot nedz eņģeļa, nedz gara; bet tie farizeji visu to apliecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Un tur liela brēkšana sākās, un tie rakstu mācītāji no tās farizeju puses cēlās un tiepās sacīdami: “Mēs pie šā cilvēka nekā ļauna neatrodam; un ja kāds gars ar viņu ir runājis, vai kāds eņģelis, tad lai nekarojam pret Dievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Bet kad tas troksnis vairojās, tad tam virsniekam rūpēja, ka Pāvils no tiem netaptu saplēsts, un viņš tiem karavīriem pavēlēja noiet, to no viņu vidus izraut un novest uz lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Un nākošā naktī Tas Kungs viņam piestājās sacīdams: “Turi drošu prātu, Pāvil; jo itin tā, kā tu par Mani liecību esi devis Jeruzālemē, tāpat tev būs arī Romā liecināt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Un kad gaisma bija aususi, tad tie Jūdi sapulcējās un sazvērējās kopā sacīdami: “Mēs negribam ne ēst ne dzert, tiekams Pāvilu būsim nokāvuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Un to bija vairāk nekā četrdesmit, kas tā bija sazvērējušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Šie nāca pie tiem augstiem priesteriem un vecajiem un sacīja: “Mēs svēti esam nodievojušies, nekā nebaudīt, kamēr Pāvilu būsim nokāvuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Tad nu dodiet ziņu tam virsniekam un tai augstai tiesai, lai to rītā pie jums atved, tā kā jūs viņa lietu gribētu labāki izklausināt; bet mēs esam gatavi to nokaut, pirms tas atnāk.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Bet Pāvila māsas dēls šo viltu dzirdējis, atnāca un iegāja lēģerī un Pāvilam to pasludināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Un Pāvils vienu no tiem kapteiņiem pasauca un sacīja: “Noved šo jaunekli pie virsnieka, jo viņam ir priekš tā kāda ziņa.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Tad nu šis to ņēma un noveda pie tā virsnieka un sacīja: “Tas saistītais Pāvils mani sauca un lūdza, šo jaunekli pie tevis atvest, jo viņam ar tevi kas jārunā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Un tas virsnieks to pie rokas ņēma un savrup aizgājis vaicāja: “Kas tev ir, ko man teikt?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Un tas sacīja: “Tie Jūdi saderējušies tevi lūgt, ka tu rītā Pāvilu liktu vest priekš augstās tiesas, tā kā tie gribētu viņu jo skaidri izklausināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Tad nu tu neļaujies no tiem pārrunāties; jo vairāk nekā četrdesmit vīri no tiem uz viņu glūn un paši nodievojušies, nekā ne ēst ne dzert, kamēr viņu būšot nokāvuši, un nu tie ir gatavi, gaidīdami no tevis to solīšanu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tad tas virsnieks to jaunekli atlaida pavēlēdams: “Nesaki to nevienam, ka tu to man esi zināmu darījis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Un tas, divus no tiem kapteiņiem ataicinājis, sacīja: “Sataisiet divsimt karavīrus, ka tie iet uz Cezareju, un septiņdesmit jātniekus un divsimt strēlniekus ap to trešo stundu naktī.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Viņš arī lika jājamus lopus parīkot, ka Pāvilu virsū sēdinātu un veselu novestu pie tā valdītāja Felika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Un viņš grāmatu rakstīja ar šiem vārdiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '“Klaudijs Lizijs tam viscienīgam valdītājam Felikam prieku!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Šo vīru, kas no tiem Jūdiem sagrābts un no tiem tik nenokauts, es, ar tiem karavīriem pienācis, esmu izrāvis, dzirdēdams, ka viņš Romietis');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Un gribēdams to vainu zināt, kādēļ tie viņu apsūdzēja, es viņu esmu vedis priekš viņu augstās tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Un es viņu atradu apsūdzētu par viņu bauslības jautāšanām, bet viņš par neko netapa apsūdzēts, ar ko nāvi vai saites būtu pelnījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Un kad man tas padoms tapa zināms, kas tiem Jūdiem bija pret šo vīru, tad es tūdaļ viņu pie tevis esmu sūtījis un tiem sūdzētājiem pavēlējis, tavā priekšā izteikt, kas tiem ir pret viņu. Dzīvo vesels!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Tad nu tie karavīri, tā kā tiem bija pavēlēts, Pāvilu ņēma un pa nakti noveda uz Antipatridu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Un otrā dienā tie viņu atstāja tiem jātniekiem, ar viņu tālāk iet, un paši griezās atpakaļ uz lēģeri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Viņi nu uz Cezareju nākuši un to grāmatu tam zemes valdītājam atdevuši, arī Pāvilu viņam nodeva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Un tas zemes valdītājs to grāmatu lasījis vaicāja, no kuras zemes tiesas viņš esot? Un dzirdējis, ka viņš no Ķiliķijas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Tas sacīja: “Es tevi izklausināšu, kad arī tavi sūdzētāji atnāks,” un pavēlēja, viņu Hērodus pilī apsargāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Un pēc piecām dienām tas augstais priesteris Ananija nonāca ar tiem vecajiem un ar kādu runātāju Tertullu; šie pie tā zemes valdītāja savu sūdzību pret Pāvilu pienesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Un kad viņš tapa saukts, Tertullus iesāka viņu apsūdzēt sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '“Ka mēs caur tevi lielu mieru esam dabūjuši, un ka caur tavu uzraudzību daudz teicamas lietas šai tautai notiek, to mēs, viscienīgais Feliks, visādi un visās malās ar visu pateikšanu saņemam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Bet lai es tevi pārāk ilgi nekavēju, lūdzos, ka tu pēc tavas laipnības kādus īsus vārdus no mums klausītos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Jo mēs esam atraduši, ka šis vīrs ir mēris un trokšņa cēlējs starp visiem Jūdiem visā pasaulē un ka viņš ir tās Nacareju draudzes priekšnieks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Kas arī apņēmies, Dieva namu apgānīt; to mēs tad arī esam grābuši un pēc savas bauslības gribējuši tiesāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Bet Lizijs, tas virsnieks, pienācis klāt, viņu ar lielu varu no mūsu rokām ir aizvedis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Un viņa sūdzētājiem pavēlējis, pie tevis nākt; no tā tu pats visas lietas izklausinādams vari noprast, par ko mēs viņu apsūdzam.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Bet tie Jūdi arīdzan runāja līdz, sacīdami, ka tas tā esot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Bet Pāvils, kad tas zemes valdītājs viņam ar roku bija metis, lai runā, atbildēja: “Tāpēc ka es zinu, tevi jau daudz gadus esam ieceltu par soģi pār šo tautu, tad es jo droši savu lietu aizbildināšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Tu vari dabūt zināt, ka nav vairāk nekā divpadsmit dienas, kamēr es uz Jeruzālemi esmu nācis, Dievu lūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Un tie mani nav atraduši nedz Dieva namā uz kādu runājam, nedz baznīcās, nedz pilsētā troksni ceļam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Tie arī nevar pierādīt, par ko tie tagad mani apsūdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Bet to es tev droši saku, ka es savu tēvu Dievam kalpoju pēc tā ceļa, ko tie sauc par atkāpēju ticību, ticēdams visu, kas bauslībā un praviešos rakstīts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Un man ir uz Dievu tā cerība, uz ko šie arīdzan gaida, ka miroņi augšāmcelsies, gan taisniem, gan netaisniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Un tāpēc es pats dzenos, vienmēr paturēt bezvainīgu zināmu sirdi Dieva un cilvēku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Bet pēc kādiem gadiem es esmu nācis, mīlestības dāvanas savai tautai dot un upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Pie tam, kad es Dieva namā šķīstījos, kādi Jūdi no Āzijas mani atrada, bez drūzmas un bez trokšņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Tiem būtu pienācies tavā priekšā būt un sūdzēt, ja tiem kas būtu pret mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Jeb lai šie paši saka, kādu netaisnību tie pie manis ir atraduši, kad es stāvēju augstās tiesas priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Ja ne šā vienīga vārda dēļ, ka es priekš tiem stāvēdams saucu: miroņu augšāmcelšanās dēļ es šodien no jums topu tiesāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Un kad Feliks to dzirdēja, tad viņš to spriedumu pavilcināja, šo mācību jo labi zinādams, un sacīja: “Kad Lizijs, tas virsnieks, atnāks, tad es jūsu lietu izklausināšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Un viņš tam kapteinim pavēlēja, Pāvilu sargāt un viņam atvieglošanu vēlēt un nevienam no viņa piederīgiem neliegt, viņam kalpot un pie viņa nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Un pēc kādām dienām Feliks atnāca ar Druzillu, savu sievu, kas bija no Jūdu cilts, un sūtīja pēc Pāvila un klausījās viņa mācību par ticību uz Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Un kad viņš runāja par taisnību un šķīstību un nākamo sodību, tad Feliks pārbijās un atbildēja: “Šo reiz tu vari iet; kad man atkal būs vaļas, tad es tevi aicināšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Bet tas turklāt arī cerēja, ka tam nauda no Pāvila taps dota, lai viņu atlaistu. Tādēļ tas arī dažreiz pēc viņa sūtīja un ar viņu runāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Un kad divi gadi bija pagājuši, tad Porcius Festus nāca Felika vietā, un Feliks gribēdams tiem Jūdiem ko pa prātam darīt, Pāvilu pameta cietumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Tad nu Festus, to zemes valdību uzņēmis, gāja pēc trim dienām no Cezarejas uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Un tur viņam tas augstais priesteris un tie augstākie no tiem Jūdiem sūdzēja pret Pāvilu un viņu lūdza,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Želastības prasīdami pret viņu, ka tas viņu uz Jeruzālemi sūtītu, glūnēdami, ka viņu uz ceļa nokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Tad Festus atbildēja, ka Pāvils topot sargāts Cezarejā, un ka viņš pats gribot drīz turp aiziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Kas nu jūsu starpā to var (tā viņš sacīja), tie lai līdz noiet un to apsūdz, ja kāda vaina ir pie šā vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Un kad viņš pie tiem vairāk kā desmit dienas bija palicis, tad viņš nāca uz Cezareju un otrā dienā, uz soģa krēsla sēdēdams, viņš pavēlēja, Pāvilu atvest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Un kad tas bija atnācis, tad tie no Jeruzālemes nākušie Jūdi apkārt stāvēja, daudz un grūtas vainas pret Pāvilu nesdami, ko tie nevarēja pierādīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Jo tas tā aizbildinājās: “Es neko neesmu grēkojis, ne pret Jūdu bauslību, ne pret Dieva namu, ne pret ķeizaru.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Bet Festus gribēdams tiem Jūdiem pa prātam darīt, atbildēja un uz Pāvilu sacīja: “Vai tu gribi uz Jeruzālemi iet, lai es tevi tur tiesāju par šīm lietām?”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Bet Pāvils sacīja: “Es stāvu priekš ķeizara soģa krēsla, tur man pienākas tapt tiesātam, tiem Jūdiem es nekādu netaisnību neesmu darījis, kā arī tu jo labi zini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Bet ja es netaisnību esmu darījis un nāvi kaut kā pelnījis, tad es neliedzos mirt; bet ja tas nav nekas, par ko tie mani apsūdz, tad neviens pēc viņu patikšanas mani viņiem nevar nodot. Es ķeizaru piesaucu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Tad Festus ar tiem runas kungiem sarunājies atbildēja: “Ķeizaru tu esi piesaucis, pie ķeizara tev būs noiet.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Bet kad kādas dienas bija pagājušās, tad ķēniņš Agrippa un Berniķe nāca uz Cezareju, Festu apsveicināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Un kad tie kādas dienas tur bija pakavējušies, Festus ķēniņam stāstīja Pāvila lietas sacīdams: “Še ir viens vīrs no Felika atstāts cietumā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Par to, kad es biju Jeruzālemē, tie augstie priesteri un Jūdu vecaji pienesa sūdzību un lūdza spriedumu pret viņu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Tiem es atbildēju: Romiešiem nav ieradums, kādu cilvēku nodot uz nomaitāšanu, pirms tas, kas apsūdzēts, tos sūdzētājus nav redzējis savā priekšā un nav vaļu dabūjis par to sūdzību aizbildināties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Kad nu tie šeitan bija sanākuši, tad es bez nekādas kavēšanās otrā dienā uz soģa krēsla sēdēdams pavēlēju, to vīru atvest;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Pret to tie sūdzētāji stāvēdami nekādu lietu nav pienesuši, ko es par ļaunu būtu uzskatījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Bet tiem bija kādas apjautāšanas pret viņu par savu pašu māņu ticību un par kādu Jēzu, kas esot nomiris, par ko Pāvils sacīja, Viņu esam dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Un šo strīdus lietu labi nesaprazdams, es sacīju: vai tas gribot uz Jeruzālemi iet un tur par šīm lietām likties tiesāties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Bet kad Pāvils prasīja, lai uz paša ķeizara spriedumu taptu sargāts; tad es pavēlēju to sargāt, tiekams es viņu pie ķeizara sūtīšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Un Agrippa sacīja uz Festu: “Es pats arīdzan šo cilvēku gribētu dzirdēt;” un viņš sacīja: “Rīt tu to dzirdēsi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Tad nu otrā dienā, kad Agrippa un Berniķe ar lielu greznību nāca un ar tiem virsniekiem un tās pilsētas augstiem vīriem iegāja tiesas namā, Pāvils pēc Festus pavēles tapa atvests.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Un Festus sacīja: “Agrippa ķēniņ un visi jūs vīri, kas klāt esat, jūs šo redzat, par ko visa Jūdu draudze tā Jeruzālemē kā arī šeitan mani ir piesaukusi un brēc, ka tam nebūs vairs dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Bet es esmu atradis, ka tas neko nav darījis, ar ko nāvi būtu pelnījis; un tādēļ, ka tas pats ķeizaru ir piesaucis, tad es esmu spriedis, viņu sūtīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Bet man par šo nav nekādas skaidrības, ko Tam Kungam lai rakstu. Tādēļ es jums to esmu priekšā vedis un visvairāk tev, ķēniņ Agrippa, lai es pēc notikušas izklausīšanas zinu, kas jāraksta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Jo man šķiet, aplamu lietu esam, vienu saistītu sūtīt un tās vainas pret to neuzrādīt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa sacīja uz Pāvilu: “Tev ir vēlēts priekš sevis paša runāt.” Tad Pāvils roku izstiepis aizbildinājās:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '“Es to sev turu par lielu laimi, ķēniņ Agrippa, ka man šodien ir vēlēts tavā priekšā aizbildināties par visu to, par ko es no tiem Jūdiem topu apsūdzēts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Visvairāk, kad es zinu, tevi esam mācītu visās Jūdu ierašās un jautāšanās. Tāpēc es tevi lūdzu, lēnprātīgi mani klausīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Manu dzīvošanu no mazām dienām, kāda tā no iesākuma bijusi manas tautas starpā iekš Jeruzālemes, to nu visi Jūdi zina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Tie mani sen jau pazina, (ja tie gribētu liecību dot), ka es esmu dzīvojis pēc mūsu Dieva kalpošanas viscietākiem likumiem, farizejs būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Un nu es stāvu un topu tiesāts par to cerību uz to no Dieva mūsu tēviem doto apsolīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Pie tās cer nākt mūsu divpadsmit ciltis, bez mitēšanās naktīm un dienām Dievam kalpodamas. Par šo cerību, ķēniņ Agrippa, es no tiem Jūdiem topu apsūdzēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Kā? Vai tā jums šķiet neticama lieta, ka Dievs miroņus uzmodina?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Man pašam gan šķita, ka man vajagot Jēzus, tā Nacarieša, vārdam daudz pretī darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'To es arī esmu darījis Jeruzālemē, un es daudz svētus esmu ieslēdzis cietumā, to varu no tiem augstiem priesteriem dabūjis; un kad viņi tapa nokauti, tad man tas bija pa prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Un pa visām baznīcām es tos daudzkārt esmu mocījis un tos spiedis zaimot, un pārlieku pret tiem trakodams es tos esmu vajājis arī līdz svešām pilsētām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Kad es tādēļ arī uz Damasku gāju ar spēku un varu no tiem augstiem priesteriem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Tad, ak ķēniņ, es dienas vidū uz ceļa gaišumu no debesīm, skaidrāku nekā sauli, redzēju, kas mani un manus ceļa biedrus apspīdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Un kad mēs visi pie zemes pakritām, tad es dzirdēju balsi uz mani runājam un Ebreju valodā sakām: “Saul, Saul, ko tu Mani vajā? Tev grūti nāksies pret dzenuli spārdīt!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Bet es sacīju: “Kas Tu esi, Kungs?” Bet Tas sacīja: “Es esmu Jēzus, ko tu vajā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Bet celies un stāvi uz savām kājām. Jo tāpēc Es tev esmu parādījies, ka Es tevi ieceltu par kalpu un liecinieku tanīs lietās, ko tu esi redzējis un kādās Es tev parādīšos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Tevi izraudams no šiem ļaudīm un no tiem pagāniem, pie kuriem Es tevi tagad sūtu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Viņu acis atdarīt, ka tie atgriežas no tumsības pie gaismas un no velna varas pie Dieva, ka tie dabū grēku piedošanu un daļu starp tiem svētītiem caur ticību uz Mani.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Tāpēc, ak ķēniņ Agrippa, es šai parādīšanai no debesīm neesmu bijis nepaklausīgs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Bet es papriekš tiem, kas Damaskū un Jeruzālemē un visā Jūdu zemē, un tiem pagāniem esmu pasludinājis, lai no grēkiem atstājās un pie Dieva atgriežas un dara atjaunota prāta pienākamus darbus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Tādēļ tie Jūdi, Dieva namā mani sagrābuši, apņēmās mani nokaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Bet palīgu no Dieva dabūjis es stāvu līdz šai dienai, un apliecināju tik pat mazam kā lielam, cita nekā nesacīdams kā vien, ko pravieši un Mozus runājuši, kas notiks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Ka Kristum bija jācieš, un ka Viņš, tas pirmais, kas no miroņiem augšāmcēlies, gaismu pasludinās Saviem ļaudīm un tiem pagāniem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Un kad viņš tā aizbildinājās, tad Festus sacīja ar skaņu balsi: “Pāvil, tu esi traks, tā lielā rakstu zināšana tevi padara traku.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Bet tas sacīja: “Es neesmu vis traks, viscienīgais Festu, bet es runāju patiesīgus un prātīgus vārdus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Jo par šīm lietām ķēniņš zina, uz ko es arī droši runāju. Jo es neticu, ka kāda no šīm lietām viņam ir paslēpta; jo tas nav kaktā noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Vai tu, ķēniņ Agrippa, tiem praviešiem tici? Es zinu, ka tu tici!”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Bet Agrippa sacīja uz Pāvilu: “Daudz netrūkst, tu mani pārrunā, ka es palieku par Kristus mācekli.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Bet Pāvils sacīja: “Es no Dieva vēlētos, lai trūkst maz vai daudz, ka ne vien tu, bet arī visi, kas mani šodien dzird, tādi top, kāds es esmu, bez šīm saitēm vien.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Un kad viņš to runāja, tad ķēniņš cēlās un zemes valdītājs un Berniķe un kas pie tiem sēdēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Un aizgājuši tie runāja savā starpā sacīdami: “Šis cilvēks neko nedara, ar ko viņš nāvi vai saites pelna.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Un Agrippa sacīja uz Festu: “Šo cilvēku varētu palaist, kad tas ķeizaru nebūtu piesaucis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Un kad tas bija nospriests, ka mums bija pārcelties uz Itāliju, tad tie Pāvilu un kādus citus cietumniekus nodeva vienam karakapteinim, ar vārdu Julijus, no ķeizara karoga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Un vienā Adramitijas laivā kāpuši, mēs gribējām Āzijas pilsētām iet garām, un aizcēlāmies, un Aristarks, tas Maķedonietis no Tesalonikas, bija mums līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Un otrā dienā mēs laidām malā pie Sidonas. Un Julijus laipnīgi pret Pāvilu turēdamies atļāva pie tiem draugiem iet, ka tas no tiem dabūtu apgādāšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Un mēs no turienes aizcēlušies braucām apakš Kipras, jo vēji mums bija pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Un gar Ķiliķiju un Pamfiliju pār jūru pārcēlušies mēs nācām uz Miru Liķijas zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Un tur tas kapteinis atrada vienu laivu no Aleksandrijas, kas gāja uz Itāliju, un lika mums tanī iekāpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Un mēs kādas dienas lēni braukdami un ar mokām pret Knidu nākuši, tāpēc ka vējš mūs nelaida, braucām gar Krietu pret Salmoni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Un ar mokām tur garām braukuši mēs nācām kādā vietā, ko sauc par krāšņu ostu, kur Laseas pilsēta bija tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Kad nu labs laiks bija pagājis un braukšana jau bija bailīga, tāpēc ka arī gavēņu laiks jau bija pāri, tad Pāvils tos pamācīja,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Uz tiem sacīdams: “Vīri, es redzu, ka tā braukšana notiks ar grūtumu un lielu postu, ne vien pie preces un laivas, bet arī pie mūsu dzīvības.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Bet tas kapteinis vairāk ticēja stūrmanim un kuģiniekam, nekā tam, ko Pāvils sacīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Un kad tā mala nederēja, tur par ziemu mist, tad tā lielā puse padomu deva, no turienes aizcelties, vai nevarētu pie Feniķes kļūt, un tur par ziemu palikt; tā ir osta iekš Krietas un stāv pret dienvidu vēju un vakara vēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Un kad dienvidu vējš lēni pūta, tad viņiem šķita, ka savu nodomu panākuši, un enkurus uzvilkuši, tie laida jo tuvu gar Krietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Bet neilgi pēc tam viesuļa vējš, kas top saukts idus, pacēlās pret to salu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Un kad laiva tapa līdz aizrauta un nespēja pret vēju turēties, tad mēs to padevām un tapām nesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Un kad mēs pie vienas salas nācām, kas Klauda top saukta, tad mēs tikko varējām mazo laiviņu saturēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'To tie uzvilkuši, ar virvēm to laivu nostiprināja, un bīdamies, ka uz seklumu neuzklīstu, zēģeli nolaida zemē un mētājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Un kad vētrā ļoti tapām mētāti, tad otrā dienā sāka lādiņu izmest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Un trešā dienā mēs ar savām pašu rokām laivas rīkus izmetām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Un kad kādas dienas ne saule, ne zvaigznes nespīdēja un liela auka mūs spieda, tad visa glābšanas cerība mums izzuda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Un kad tie ilgi nebija ēduši, Pāvils cēlās viņu vidū sacīdams: “Jums, ak vīri, būtu pienācies man paklausīt un neaizbraukt no Krietas un izsargāties no tāda grūtuma un skādes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Un tagad es jūs pamācu turēt drošu prātu, jo nevienam no jums dzīvība nezudīs, bet vien tā laiva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Jo šinī naktī man piestājās viens eņģelis no Tā Dieva, kam es piederu un kam es arī kalpoju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Sacīdams: “Nebīsties, Pāvil, tev būs nākt ķeizara priekšā, un redzi Dievs tev visus ir dāvinājis, kas līdz ar tevi ir laivā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Tāpēc turat drošu prātu, jūs vīri: jo es Dievam ticu, ka tas tā notiks, kā man sacīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Bet mēs tapsim izmesti pie kādas salas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Kad nu tā četrpadsmitā nakts bija nākusi, un mēs Adrijas jūrā tapām mētāti ap nakts vidu, tad tie laivinieki bijās, ka neuzdurtos uz kādu malu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Un tie lodi izmeta un atrada divdesmit asis, un maķenīt tālāk atkal lodi izmetuši, atrada piecpadsmit asis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Un bīdamies, ka uz akmeņiem neuzklīstu, tie meta no laivas pakaļgala četrus enkurus un vēlējās, ka gaisma austu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Bet kad tie laivinieki meklēja no laivas bēgt un mazo laiviņu nolaida jūrā, melodami, ka no priekšgala enkurus gribot nolaist,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Tad Pāvils uz to kapteini un tiem karavīriem sacīja: “Ja šie nepaliek laivā, tad jūs nevarat izglābties.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Tad tie karavīri tās laiviņas virves nocirta un lika tai nokrist.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Un kamēr gaisma ausa, Pāvils visus lūdza, lai barības pabauda, sacīdams: “Šodien ir tā četrpadsmitā diena, ka jūs gaidīdami paliekat neēduši un nekā neesat baudījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Tādēļ es jūs pamācu, barību ņemt; jo tas jums pašiem būs par labu; jo nevienam no jums ne mats no galvas nekritīs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Un to sacījis un maizi ņēmis, viņš Dievam pateicās visu priekšā un to pārlauzis iesāka ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Un visi iedrošināti ņēma arī barību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Un mēs tanī laivā pavisam bijām divsimt un septiņdesmit un sešas dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Un paēduši tie laivu atviegloja, labību jūrā izmezdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Un kad gaisma ausa, tie to zemi nepazina, bet ieraudzīja vienu jūras līci, kura malā tie laivu gribēja pielaist, ja tik varētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Un tie enkurus nocirtuši palaida jūrā un turklāt stūra saites atraisījuši un zēģeli pa vējam pacēluši dzinās pie malas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Bet tie noklīda tādā vietā, kur uz abējām pusēm bija jūra, un laiva dauzījās, un priekšgals uzgāja uz sēkli un palika nekustināms, un pakaļgals tapa sadauzīts no viļņu varas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Tad to karavīru padoms bija, tos saistītos nokaut, lai neviens izpeldēdams neizbēgtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Bet tas kapteinis, gribēdams Pāvilu izglābt, viņu padomam turējās pretī un pavēlēja tiem, kas varēja peldēt, papriekš ūdenī ielaisties un malā iet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Un tiem citiem, vai uz galdiem, vai uz kādiem laivas gabaliem; un tā notika, ka visi izglābās un tika malā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Un kad tie bija izglābti, tad tie dabūja zināt, ka tā sala tapa saukta Melite.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Un tie salas ļaudis mums parādīja lielu laipnību; jo tie uguni uzkūruši mūs visus uzņēma, tā lietus dēļ kas bija sācis līt, un tā aukstuma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Un kad Pāvils kādu žagaru nastiņu bija salasījis un pie uguns pielicis, tad viena odze no tā karstuma izlīda un ap viņa roku aptinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Un kad tie salas ļaudis to tārpu redzēja pie viņa rokas karājamies, tad tie sacīja savā starpā: šis cilvēks tiešām ir slepkava, kam no jūras izglābtam atriebšana neļauj dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Bet viņš to tārpu nokratīja ugunī un neko ļauna necieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Un tie gaidīja, ka tas uztūktu, vai piepeši nomiris pakristu; bet kad tie ilgi bija gaidījuši un redzēja, ka nekāds ļaunums viņam nenotika, tad tiem citas domas nāca, un tie sacīja, viņu esam dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Un ap to pašu vietu tam salas virsniekam, ar vārdu Publijus, bija muiža; tas mūs uzņēma un trīs dienas laipni kopa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Un notikās, ka Publijus tēvs ar drudzi un ar asins sērgu sirga; pie tā Pāvils iegāja un Dievu pielūdzis rokas tam uzlika un to darīja veselu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Kad nu tas bija noticis, tad arī tie citi atnāca, kam tanī salā bija sērgas, un tapa dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Tie arīdzan mūs ar lielu godu pagodināja, un kad mēs aizcēlāmies, tie deva, ko mums vajadzēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Un pēc trim mēnešiem aizcēlāmies ar laivu, kas bija no Aleksandrijas un tanī salā pa ziemu bija mitusi, un kam par zīmi bija dvīņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Un uz Sirakuzu nākuši, mēs tur palikām trīs dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'No turienes atkal aizcēlušies, mēs nācām uz Reģiu; un kad pēc vienas dienas dienasvidus vējš cēlās, tad nācām otrā dienā uz Puteoliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Tur mēs atradām brāļus un no tiem tapām lūgti, septiņas dienas pie tiem palikt, un tā mēs nācām uz Romu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Un no turienes tie brāļi, par mums dzirdējuši, izgāja mums pretī līdz Appijus tirgum un TriTabernām; tos redzēdams, Pāvils Dievam pateicās un ņēmās drošu prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Un kad mēs nācām uz Romu, tad tas kapteinis tos saistītos nodeva tam karavaldniekam, bet Pāvilam vaļa tapa dota, savrup palikt ar kādu karavīru, kas viņu sargāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Un notikās pēc trim dienām, ka Pāvils Jūdu priekšniekus saaicināja. Un kad tie bija kopā sanākuši, viņš uz tiem sacīja: ‘Vīri, brāļi, es neko neesmu darījis ne pret šiem ļaudīm, ne pret tēvu ieradumiem un tomēr saistīts no Jeruzālemes esmu nodots Romiešu rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Tie izjautājuši gribēja mani atlaist, tādēļ ka nekādas nāves vainas pie manis nebija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Bet kad tie Jūdi pretī runāja, tad tapu spiests, ķeizaru piesaukt, tomēr ne tā, ka man būtu ko sūdzēt pret savu tautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Tad nu šās lietas dēļ es jūs esmu lūdzis, ka dabūtu jūs redzēt un ar jums runāt. Jo Israēla cerības dēļ es ar šīm ķēdēm esmu saistīts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Bet tie uz viņu sacīja: “Mēs neesam nedz grāmatas par tevi no Jūdu zemes dabūjuši, nedz arī kāds no tiem atnākušiem brāļiem par tevi ko ļauna ir sludinājis jeb runājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Tomēr mēs gribam no tevis dzirdēt, ko tu domā; jo no šās draudzes mums ir zināms, ka tai visās malās top pretī runāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Un kad tie viņam vienu dienu bija nolikuši, tad daudzi nāca pie viņa mājas vietā; tiem viņš Dieva valstību apliecināja un izstāstīja, tos pārliecinādams par Jēzu no rīta agri līdz vakaram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Un citi gan tapa pārliecināti caur to, ko viņš sacīja, bet citi neticēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Un nebūdami savā starpā vienprātīgi, tie aizgāja, kad Pāvils to vienu vārdu bija sacījis: “Tas Svētais Gars gan labi caur pravieti Jesaju ir runājis uz mūsu tēviem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Sacīdams: “Noej pie šiem ļaudīm un saki: ar ausīm jūs dzirdēsiet un nesapratīsiet, un redzēdami jūs redzēsiet un nenomanīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Jo šo ļaužu sirds ir tapusi cieta, un ar ausīm tie grūti dzird un snauž ar savām acīm, ka tie ar acīm neredz un ar sirdi nesaprot un neatgriežas, ka Es tos dziedinātu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Tad nu jums būs zināt, ka pagāniem Dieva pestīšana ir sūtīta, un tie to dzirdēs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Un kad viņš to bija sacījis, tad tie Jūdi aizgāja, savā starpā daudz apjautādamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Un Pāvils palika divus gadus savā īpaši īrētā mājas vietā, un visus pieņēma, kas pie viņa nāca,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Dieva valstību sludinādams un par To Kungu Jēzu Kristu mācīdams ar visu drošību bez aizliegšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Pāvils, Jēzus Kristus kalps, aicināts par apustuli, izvēlēts, sludināt Dieva evaņģēliju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Ko Viņš papriekš caur Saviem praviešiem svētos rakstos apsolījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Par Savu Dēlu, (kas pēc miesas ir cēlies no Dāvida sēklas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Un pēc tā svētīšanas Gara caur augšāmcelšanos no miroņiem spēkā ir parādīts Dieva dēls), par Jēzu Kristu, mūsu Kungu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Caur ko mēs esam dabūjuši žēlastību un apustuļa amatu, lai ticībai paklausa Viņa Vārda labad visi pagāni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Kuru starpā arī jūs esat Jēzus Kristus aicinātie, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Visiem Dieva mīļiem, tiem aicinātiem svētiem Romā: žēlastība jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Papriekš es savam Dievam pateicos caur Jēzu Kristu par jums visiem, ka jūsu ticība top teikta visā pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Jo Dievs, kam es savā garā kalpoju, Viņa Dēla evaņģēliju sludinādams, ir mans liecinieks, ka es bez mitēšanās jūs pieminu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Allažiņ savās lūgšanās lūgdams, lai jel kādu reiz ceļš man izdotos pēc Dieva prāta pie jums nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Jo es ilgojos jūs redzēt, lai jums iedotu kādu garīgu dāvanu, ka jūs topat stiprināti:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Tas ir, ka es līdz ar jums taptu iepriecināts caur mūsu abēju, tā jūsu kā manu ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Bet es jums, brāļi, negribu slēpt, ka daudzreiz esmu apņēmies pie jums nākt (un līdz šim esmu aizkavēts), lai es arī pie jums kādu augli dabūtu, kā pie tiem citiem pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Jo es esmu parādnieks Grieķiem un barbariem, gudriem un negudriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Tādēļ no savas puses esmu gatavs, arī jums, kas esat Romā, evaņģēliju sludināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Jo es nekaunos Kristus evaņģēlija dēļ; jo tas ir Dieva spēks par pestīšanu ikvienam, kas tic, papriekš Jūdam un arī Grieķim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Jo Dieva taisnība iekš tā parādās no ticības uz ticību. Itin kā ir rakstīts: taisnais dzīvos no ticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Jo Dieva dusmība no debesīm parādās pār ikvienu bezdievību un netaisnību pie cilvēkiem, kas patiesību netaisnībā aiztur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Jo Tā Dieva atzīšana tiem ir zināma, jo Dievs tiem to ir zināmu darījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Jo Viņa neredzamā būšana no pasaules radīšanas pie tiem darbiem top nomanīta un ieraudzīta, gan Viņa mūžīgais spēks, gan Viņa dievība, tā ka tie nevar aizbildināties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Tāpēc ka tie Dievu atzīdami, to kā Dievu nav godājuši nedz Viņam pateikušies, bet savās domās nelieši tapuši un viņu neprātīgā sirds ir aptumšota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Teikdamies gudri esoši, tie palikuši par ģeķiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Un ir apmainījuši tā neiznīcīgā Dieva godību par ģīmi, kas līdzīgs nīcīgam cilvēkam un putniem un četrkājīgiem lopiem un tārpiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Tāpēc Dievs tos arī nodevis viņu siržu kārībās uz nešķīstību, savas miesas sagānīt savā starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Dieva patiesību tie ir pārvērtuši melos un radītas lietas lielākā godā turējuši un tām vairāk kalpojuši nekā tam Radītājam, kas ir augsti teicams mūžīgi! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Tāpēc Dievs tos ir nodevis negodīgās kārībās; jo viņu sievieši to sadzīvi, kas pēc dabas, ir pārvērtuši par tādu, kas ir pret dabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Tāpat arīdzan tie vīrieši ir atstājuši to sadzīvi ar sievieti, kas pēc dabas, un savā kārībā cits uz citu iekarsušies, un vīrieši ar vīriešiem bezkaunību dzinuši un savas nomaldīšanās pienākamo algu pie sev pašiem dabūjuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Un kā tie nav cienījuši Dievu turēt atzīšanā, tā Dievs tos ir nodevis pārvērstam prātam, to darīt, kas neklājās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Piepildītus ar visādu netaisnību, maucību, blēdību, mantas kārību, niknumu, pilnus skaudības, slepkavības, ķildu, viltības, netiklības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Mēlnešus, apmelotājus, Dievam negantus, varas darītājus, lepnus, lielīgus, ļaunuma izgudrotājus, vecākiem nepaklausīgus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Neprātīgus, derības pārkāpējus, cietsirdīgus, nesaderīgus, nežēlīgus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Kas zinādami to Dieva likumu, ka tie, kas tādas lietas dara, nāvi pelna, nevien tādas lietas dara, bet arī labu prātu tur pie tiem, kas tā dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Tāpēc tu, ak cilvēks, esi neaizbildinājams, ikviens, kas tiesā; jo kurā lietā tu otru tiesā, tu pats sevi notiesā, jo tu tās pašas lietas dari, tu tiesātājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Bet mēs zinām, ka Dieva sodība tiem tiešām uzies, kas tādas lietas dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Bet vai tu, ak cilvēks, gan domā, ka tu izbēgsi Dieva sodībai, tos tiesādams, kas tādas lietas dara, un pats tās darīdams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Jeb vai tu nicini Viņa laipnības un pacietības un lēnprātības bagātību, nezinādams, ka Dieva laipnība tevi vada uz atgriešanos no grēkiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Bet tu pēc savas cietas un neatgriezīgas sirds sev pašam krājies par mantu dusmību uz dusmības dienu, kad Dievs parādīs taisnu spriedumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Kas ikvienam atmaksās pēc viņa darbiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Tiem, kas pastāvīgi labā darbā godu un slavu un neiznīcību meklē - mūžīgu dzīvošanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Bet tiem, kas ir rējēji un nepaklausa patiesībai, bet paklausa netaisnībai - dusmību un bardzību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Bēdas un izbailes ikkatrai cilvēka dvēselei, kas ļaunu dara, papriekš Jūdam un arī Grieķim;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Bet gods un slava un miers ikkatram, kas labu dara, papriekš Jūdam un arī Grieķim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Jo Dievs neuzlūko cilvēka vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Jo kas bez bauslības grēkojuši, tie arī bez bauslības pazudīs; un kas apakš bauslības grēkojuši, tie pēc bauslības taps tiesāti -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Jo ne bauslības klausītāji Dieva priekšā taisni, bet bauslības darītāji taps taisnoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Jo ja tie pagāni, kam bauslības nav, no savas dabas dara pēc bauslības, tad šie, kam bauslības nav, paši sev ir par bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Tie tad parāda, bauslības darbu esam ierakstītu viņu sirdīs caur to, ka viņu zināma sirds tiem liecību dod, un tās domas savā starpā vai apsūdzēs, vai arī aizbildinās,) -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Tanī dienā, kad Dievs cilvēku noslēpumus tiesās pēc mana evaņģēlija caur Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Raugi, tu saucies Jūds un paļaujies uz bauslību un lielies ar Dievu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Un zini Viņa prātu, un bauslībā mācīts izšķīri, kas labs un kas ļauns;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Un tu ņemies akliem būt vadonis un gaišums tiem, kas ir tumsībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Neprātīgiem pamācītājs un nejēgām mācītājs, kam ir atzīšanas un patiesības raksts bauslībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Tad nu citu mācīdams pats sevi nemāci. Tu sludini, ka nebūs zagt, pats zodz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Tu saki, ka nebūs laulību pārkāpt, pats laulību pārkāpi. Tu elkadievus turi negantus, pats esi svētuma laupītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Tu lielies ar bauslību, pats Dievu pulgo caur bauslības pārkāpšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Jo Dieva vārds jūsu dēļ top zaimots pagānu starpā, itin kā ir rakstīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Jo apgraizīšana gan ir derīga, ja tu bauslību dari; bet ja esi bauslības pārkāpējs, tad tavs apgraizījums ir tapis par priekšādu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Ja nu priekšāda bauslības likumus tur, vai tad viņu priekšāda netaps turēta par apgraizījumu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Un tad tā priekšāda, kas no dabas tāda ir un bauslību tur, tiesās tevi, kas pie raksta un apgraizīšanas esi bauslības pārkāpējs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Jo tas nav Jūds, kas no ārienes tāds ir; nedz tā ir apgraizīšana, kas no ārienes pie miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Bet tas ir Jūds, kas no iekšienes tāds, un tā ir sirds apgraizīšana, kas garā un ne rakstā; tam ir teikšana ne no cilvēkiem, bet no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Kas tad nu Jūdam ir pārāki, jeb kāds ir tas apgraizīšanas labums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Visādi liels! Jo pirmā kārtā Dieva vārdi tiem ir uzticēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Jo kas par to, ja kādi nav ticējuši? Vai viņu neticība Dieva uzticību iznīcinās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nemaz ne! Bet lai tā paliek, ka Dievs ir taisns un ikkatrs cilvēks melkulis, itin kā ir rakstīts: “Ka Tu palieci taisns Savos vārdos un uzvari, kad Tu topi tiesāts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Kad nu mūsu netaisnība Dieva taisnību apstiprina, ko lai sakām? Vai tad Dievs nav netaisns, kad Viņš soda? To runāju, kā cilvēki mēdz runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nemaz ne! Jo kā tad Dievs pasauli tiesās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Jo ja Dieva patiesība caur maniem meliem ir vairojusies Viņam par godu, ko tad es vēl kā grēcinieks topu tiesāts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Un kam mēs nesakām, itin kā topam zaimoti, un itin kā daži teic, mūs sakām: darīsim ļaunu, lai nāk labums? Tādiem sods pēc taisnības notiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Ko tad nu? Vai mēs esam labāki? Nemaz ne. Jo mēs jau pirmāk esam rādījuši, gan Jūdus, gan Grieķus, visus esam apakš grēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Itin kā stāv rakstīts: nav neviena taisna, it neviena,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Nav neviena prātīga, nav neviena, kas Dievu meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Visi ir atkāpušies un kopā tapuši nelieši, nav neviena, kas labu dara, it neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Viņu rīkle ir atvērts kaps; ar savām mēlēm tie viltību dara: odžu dzelonis ir apakš viņu lūpām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Viņu mute ir lāstu un rūgtuma pilna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Viņu kājas ir čaklas izliet asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Posts un sirdēsti ir pa viņu ceļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Un miera ceļu tie nezin.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Dieva bijāšanas nav priekš viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Bet mēs zinām, ka bauslība visu, ko tā saka, to tā runā uz tiem, kas ir apakš bauslības, lai ikviena mute top aizbāzta, un visa pasaule ir noziedzīga Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Tādēļ no bauslības darbiem neviena miesa netaps taisnota Viņa priekšā; jo caur bauslību nāk grēku atzīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Bet Dieva taisnība, kas no bauslības un no praviešiem ir apliecināta, tagad ir tapusi zināma bez bauslības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Tā Dieva taisnība caur ticību uz Jēzu Kristu priekš visiem un pie visiem, kas tic; jo tur nav nekādas starpības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Jo visi ir grēkojuši, un tiem trūkst teikšanas Dieva priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Un top taisnoti bez nopelna no Viņa žēlastības caur to atpirkšanu, kas notikusi caur Kristu Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'To Dievs ir nolicis par salīdzināšanu, caur ticību iekš Viņa asinīm, ka tas Savu taisnību parādītu, pamezdams tos priekšlaikā darītos grēkus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Iekš dievišķas paciešanas, ka Tas Savu taisnību parādītu šinī laikā: Sevi esam taisnu, un taisnu darām to, kas ir no Jēzus ticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kur nu ir tā lielīšanās? Tā ir zudusi. Caur kuru bauslību? Vai caur darbu bauslību? Nē! Bet caur ticības bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Tad nu mēs turam, ka cilvēks top taisnots caur ticību bez bauslības darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Jeb vai Dievs tikai Jūdu Dievs? Vai nav arī pagānu Dievs? Tiešām arī pagānu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Jo viens Dievs ir, kas taisno apgraizījumu no ticības un priekšādu caur ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Vai tad nu mēs bauslību iznīcinām caur ticību? Nemaz! Bet mēs bauslību apstiprinām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Ko nu lai sakām, ka mūsu vectēvs Ābrahāms ir dabūjis pēc miesas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Jo ja Ābrahāms caur darbiem ir taisnots, tad tam ir gan slava, bet ne pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Jo ko tas raksts saka? Ābrahāms Dievam ir ticējis un tas viņam ir pielīdzināts par taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Bet tam darba darītājam alga netop pielīdzināta pēc žēlastības, bet pēc parāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Bet tam, kas nav darba darītājs, bet tic uz To, kas bezdievīgo taisno, tam ticība top pielīdzināta par taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Tā kā arī Dāvids saka, to cilvēku esam svētīgu, kam Dievs taisnību pielīdzina bez darbiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Svētīgi tie, kam pārkāpumi piedoti un grēki apklāti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Svētīgs tas vīrs, kam Tas Kungs grēku nepielīdzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Vai nu šis labums atlec apgraizījumam vien, vai arī priekšādai? Jo mēs sakām, ka Ābrahāmam ticība ir pielīdzināta par taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Kā tad tā viņam ir pielīdzināta? Vai iekš apgraizījuma, vai iekš priekšādas? Ne iekš apgraizījuma, bet iekš priekšādas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Bet to apgraizīšanas zīmi viņš dabūja par taisnības zieģeli tai ticībai, ko viņš vēl priekšādā būdams turēja; ka tas būtu par tēvu visiem, kas priekšādā būdami tic, lai ticība tiem arīdzan taptu pielīdzināta par taisnību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Un par apgraizīšanas tēvu tiem, kas ne vien apgraizīti, bet arī staigā tās ticības pēdās, kas mūsu tēvam Ābrahāmam bija priekšādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Jo tā apsolīšana, ka viņš būšot pasaules mantinieks, Ābrahāmam jeb viņa sēklai nav notikusi caur bauslību, bet caur ticības taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Jo ja tie bauslības ļaudis - mantinieki, tad ticība ir veltīga un tā apsolīšana iznīkusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Jo bauslība padara dusmību; jo kur bauslības nav, tur arī nav pārkāpšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Tāpēc no ticības, lai ir pēc žēlastības; lai tā apsolīšana ir pastāvīga visam dzimumam, ne vien tam, kas no bauslības, bet arī tam, kas no Ābrahāma ticības. Tas mums visiem ir tēvs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(Kā ir rakstīts: daudz tautām Es tevi esmu cēlis par tēvu,) Tā Dieva priekšā, kam viņš ir ticējis, kas miroņus dara dzīvus un sauc to, kas vēl nav, tā kā tas jau būtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Pret cerību viņš ir ticējis uz cerību, lai paliktu par tēvu daudz tautām, pēc tā vārda: Tādam būs būt tavam dzimumam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Un viņš nepalika vājš iekš ticības, nedz lūkoja uz savām izdēdējušām miesām, tik ne simts gadus vecs būdams, nedz uz Sāras izdēdējušām miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Bet pie tās Dieva apsolīšanas viņa prāts neticībā nešaubījās, bet kļuva spēcīgs iekš ticības un Dievam deva godu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Pilnā ticībā zinādams, ka Dievs to, ko Viņš apsolījis, arī spēj darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Tāpēc tas viņam arī pielīdzināts par taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Bet tas ne vien viņa dēļ ir rakstīts, ka tas viņam ir pielīdzināts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Bet arī mūsu dēļ, kam tas tiks pielīdzināts, kad ticam uz to, kas no miroņiem ir uzmodinājis mūsu Kungu Jēzu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Kas ir nodots mūsu grēku dēļ un uzmodināts mūsu taisnošanas labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Tad nu mums no ticības taisnotiem miers ir pie Dieva caur mūsu Kungu Jēzu Kristu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Caur ko mēs ticībā esam dabūjuši arī pieiešanu pie tās pašas žēlastības, kurā mēs stāvam, un lielāmies ar to cerību uz Dieva godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Bet ne vien ar to, bet mēs lielāmies arī ar bēdām, zinādami, ka bēdas dara pacietību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Un pacietība pastāvību, un pastāvība cerību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Un cerība nepamet kaunā; jo Dieva mīlestība ir izlieta mūsu sirdīs caur To Svēto Garu, kas mums ir dots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Jo Kristus, kad mēs vēl bijām vāji, par bezdievīgiem savā laikā ir nomiris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Jo neviens lēti nemirst par kādu taisnu; par to, kas labs, gandrīz kāds varētu apņemties mirt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Bet Dievs Savu mīlestību uz mums parāda, ka Kristus par mums ir nomiris, kad mēs vēl bijām grēcinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Tad nu mēs tagad caur Viņa asinīm taisnoti jo vairāk caur Viņu tapsim glābti no tās dusmības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Jo ja mēs ienaidnieki būdami, ar Dievu esam salīdzināti caur Viņa Dēla nāvi, tad nu salīdzināti, mēs jo vairāk tapsim glābti caur Viņa dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Un ne vien tā, bet mēs arī lielāmies ar Dievu caur mūsu Kungu Jēzu Kristu, caur ko mēs tagad salīdzināšanu esam dabūjuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Tādēļ itin kā caur vienu cilvēku grēks ir ienācis pasaulē un caur grēku nāve, un tā nāve pie visiem cilvēkiem ir caurspiedusies, tāpēc ka visi ir grēkojuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Jo līdz bauslībai grēks gan bija pasaulē; bet grēks netop pielīdzināts, kad bauslības nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Tomēr nāve ir valdījusi no Ādama līdz Mozum arī pār tiem, kas nebija grēkojuši tādā pārkāpšanā kā Ādams, kas ir tā nākamā (Ādama) priekšzīme.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Bet ne tāda, kāda tā apgrēkošanās, arī tā žēlastība. Jo ja caur tā viena apgrēkošanos daudzi ir miruši, tad daudz vairāk Dieva žēlastība un dāvana caur Tā viena Cilvēka, Jēzus Kristus, žēlastību pārpilnam ir nākusi pār daudziem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Un ar to žēlastības dāvanu tas nav tā, kā ar tā viena (cilvēka) grēku. Jo tas spriedums ir gan no viena uz pazudināšanu; bet tā apžēlošana ir uz taisnošanu no daudz grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Jo ja caur tā viena apgrēkošanos nāve ir valdījusi caur to vienu, tad daudz vairāk tie, kas to žēlastības pilnību un to taisnības dāvanu dabū, valdīs iekš dzīvības caur To vienu Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Tad nu itin kā caur viena apgrēkošanos pazudināšana ir nākusi pār visiem cilvēkiem, tāpat arī caur viena taisnību dzīvības taisnošana nāk pār visiem cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Jo itin kā caur tā viena cilvēka nepaklausību daudzi ir darīti par grēciniekiem, tāpat arīdzan caur tā viena paklausību daudzi taps darīti par taisniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Bet bauslība pienākusi klāt, lai apgrēkošanās vairotos; bet kur grēks ir vairojies, tur žēlastība vēl vairāk ir vairojusies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Lai, kā grēks ir valdījis ar nāvi, tāpat arī žēlastība valda caur taisnību uz mūžīgu dzīvošanu caur Jēzu Kristu, mūsu Kungu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Ko nu lai sakām? Vai mums grēkā būs palikt, lai žēlastība vairojās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nemaz ne! Kā mēs, kas grēkam esam miruši, iekš tā vēl gribētu dzīvot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Jeb vai jūs nezināt, ka, cik no mums ir kristīti uz Kristu Jēzu, tie uz Viņa nāvi ir kristīti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Tad nu mēs līdz ar Viņu caur kristību esam aprakti nāvē, lai, kā Kristus ir uzmodināts no miroņiem caur Tā Tēva godību, tāpat arī mēs staigājam atjaunotā dzīvībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Jo ja mēs esam dēstīti līdzīgā nāvē ar Viņu, tad arī augšāmcelšanā Viņam būsim līdzīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'To zinādami, ka mūsu vecais cilvēks līdz ir krustā sists, lai grēcīgā miesa iznīkst, ka mēs grēkam vairs nekalpojam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Jo, kas nomiris, tas ir taisnots no grēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Bet ja mēs ar Kristu esam miruši, tad ticam, ka ar Viņu arī dzīvosim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Zinādami, ka Kristus no miroņiem uzmodināts vairs nemirst; nāve pār Viņu vairs nevalda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Jo ko Viņš miris, to Viņš grēkam nomiris vienreiz; bet ko Viņš dzīvo, to Viņš dzīvo Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tāpat turaties arī jūs, ka grēkam esat nomiruši, bet dzīvojiet Dievam iekš Kristus Jēzus, mūsu Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Tad nu lai grēks nevalda jūsu mirstamā miesā, paklausīt viņas kārībām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Nedz padodiet savus locekļus grēkam par netaisnības ieročiem; bet padodiet sevi pašus Dievam, tā kā no miroņiem dzīvus, un savus locekļus Dievam par taisnības ieročiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Jo grēks pār jums nevaldīs; jo jūs neesat apakš bauslības, bet apakš žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Ko nu? Vai mums būs grēkot, tāpēc ka neesam apakš bauslības, bet apakš žēlastības? Ne mūžam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Vai nezināt, ka jūs tam esat kalpi, kam padodaties par kalpiem uz paklausību, paklausīdami, vai grēkam uz nāvi, vai paklausībai uz taisnību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Bet gods Dievam, ka jūs, kas bijuši grēka kalpi, no sirds dziļuma esat palikuši paklausīgi tai mācības priekšzīmei, uz ko esat nodoti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Un atsvabināti no grēka esat palikuši par kalpiem taisnībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Es runāju cilvēcīgi jūsu miesas vājības dēļ; jo tā kā jūs savus locekļus bijāt padevuši kalpot nešķīstībai un netaisnībai uz netaisniem darbiem, tāpat padodiet tagad savus locekļus, kalpot taisnībai uz svētiem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Jo kad jūs bijāt grēka kalpi, tad jūs bijāt svabadi no taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Kāds auglis tad jums to brīdi bija? Tāds, par ko jūs tagad kaunaties; jo viņa gals ir nāve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Bet tagad, kad jūs no grēka esat atsvabināti un Dievam kalpojat, tad jums ir savs auglis, ka paliekat svēti; bet tas gals ir mūžīga dzīvošana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Jo grēka nopelns ir nāve; bet Dieva dāvana ir mūžīga dzīvība iekš Kristus Jēzus, mūsu Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Jeb vai jūs nezināt, brāļi (jo es runāju ar tiem, kas bauslību zin), ka bauslība valda pār cilvēku, kamēr tas dzīvo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Jo laulāta sieva caur bauslību ir piesieta pie vīra, kamēr tas dzīvs; bet kad vīrs miris, tad viņa ir atsvabināta no tā vīra bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Tad nu viņa taps saukta laulības pārkāpēja, kad viņa, kamēr vīrs dzīvs, pie cita vīra turas; bet ja vīrs miris, tad viņa ir svabada no tās bauslības, tā ka viņa nav vis laulības pārkāpēja, kad viņa iet pie cita vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Tā, mani brāļi, arī jūs bauslībai esat nonāvēti caur Kristus miesu, ka jums būs turēties pie cita, pie Tā, kas no miroņiem ir uzmodināts, lai Dievam augļus nesam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Jo kad mēs miesā bijām, tad grēku kārības caur bauslību mūsu locekļos bija spēcīgas, nāvei augļus nest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Bet tagad mēs no tās bauslības, kur tapām turēti, esam atsvabināti un tai nomiruši, tā ka mēs kalpojam atjaunotā garā un ne vecā raksta būšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Ko nu lai sakām? Vai bauslība ir grēks? Nemaz ne! Bet grēku es nepazinu kā vien caur bauslību. Jo iekārošanu es nezinātu, ja bauslība nesacītu: tev nebūs iekāroties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Bet grēks, caur bausli pamodināts, cēla iekš manis visādu iekārošanu. Jo bez bauslības grēks ir nedzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Un es citkārt dzīvoju bez bauslības, bet kad bauslis nāca, tad grēks palika dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Bet es nomiru, un atradās, ka tas bauslis man uz nāvi izdevās, kas man bija dots uz dzīvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Jo grēks caur bausli pamodināts mani ir pievīlis un caur to pašu nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Tad jau bauslība gan ir svēta, un bauslis gan ir svēts un taisns un labs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Vai tad tas, kas ir labs, man palicis par nāvi? Nemaz ne! Bet grēks, - lai tas parādītos kā grēks, kas caur to, kas labs, man padara nāvi, lai grēks paliktu pārlieku grēcīgs caur bausli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Jo mēs zinām, ka bauslība ir garīga; bet es esmu miesīgs, pārdots apakš grēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Jo es nezinu, ko es daru; jo to es nedaru, ko gribu; bet ko es ienīstu, to es daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Bet ja es daru, ko negribu, tad es apliecināju, bauslību esam labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Bet tagad es vairs to nedaru, bet tas grēks, kas iekš manis mīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Jo es zinu, ka iekš manis (tas ir manā miesā) labums nemīt; jo gribēt gan gribu labu darīt, bet spēt nespēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Jo to labu, ko gribu, es nedaru; bet to ļaunu, ko negribu, to es daru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Bet ja es to daru, ko negribu, tad es to vairs nedaru, bet tas grēks, kas iekš manis mīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Tad nu šo likumu atrodu, ka man gribot to labu darīt ļaunums pielīp.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Jo man ir labs prāts pie Dieva bauslības pēc tā iekšējā cilvēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Bet es redzu citu bauslību savos locekļos pret mana prāta bauslību karojam un mani gūstītu novedam apakš grēka bauslības, kas ir manos locekļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Es nabaga cilvēks, kas mani izraus no šīs nāves miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Es Dievam pateicos caur Jēzu Kristu, mūsu Kungu. Tad nu es pats ar savu prātu kalpoju Dieva bauslībai, bet ar savu miesu grēka bauslībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Tad nu nav nekādas pazudināšanas tiem, kas ir iekš Kristus Jēzus, kas nestaigā pēc miesas, bet pēc Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Jo tā dzīvības Gara bauslība iekš Kristus Jēzus mani ir atsvabinājusi no grēka un nāves bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Jo kad tas bauslībai nebija iespējams, tāpēc ka tā caur miesu bija nespēcīga, tad Dievs ir sūtījis Savu paša Dēlu grēcīgas miesas līdzībā un grēka dēļ un grēku pazudinājis iekš miesas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Ka bauslības taisnība taptu piepildīta iekš mums, kas nestaigājam pēc miesas, bet pēc Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Jo tie, kas ir pēc miesas, tie domā uz to, kas patīk miesai; bet tie, kas pēc Gara, uz to, kas patīk Garam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Jo miesas prāts ir nāve; un Gara prāts ir dzīvība un miers.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Tāpēc ka miesas prāts ir naids pret Dievu; jo tas Dieva bauslībai nepaklausa un arī nespēj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Bet tie, kas pēc miesas dzīvo, nevar Dievam patikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Bet jūs nedzīvojiet pēc miesas, bet pēc Gara, ja tikai Dieva Gars iekš jums mīt; bet ja kam Kristus Gara nav, tas Viņam nepieder.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Bet ja Kristus ir iekš jums, tad miesa gan ir nedzīva grēka dēļ, bet Tas Gars ir dzīvība taisnības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Bet ja Tā Gars, kas Jēzu ir uzmodinājis no miroņiem, iekš jums mīt, tad Tas, kas Kristu ir uzmodinājis no miroņiem, arī jūsu mirstamas miesas darīs dzīvas caur Savu Garu, kas iekš jums mīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Tad nu mēs, brāļi, esam parādnieki ne miesai, ka pēc miesas būtu jādzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Ja jūs pēc miesas dzīvojiet, tad jūs mirsiet, bet ja jūs caur To Garu miesas darbošanās nonāvējat, tad jūs dzīvosiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Jo cik no Dieva Gara top vadīti, tie ir Dieva bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Jo jūs neesat dabūjuši kalpošanas garu, ka jums atkal jābīstas, bet jūs esat dabūjuši dievbērnības Garu, caur ko mēs saucam: Abba, Tēvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Tas Gars pats apliecina līdz ar mūsu garu, ka esam Dieva bērni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Bet ja bērni, tad arī mantinieki, proti Dieva mantinieki un Kristus līdzmantinieki, ja tikai līdz ciešam, ka arī līdz topam pagodināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Jo es turu, ka šī laika ciešanas neatsver to godību, kas mums taps parādīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Jo tie radījumi ilgodamies gaida uz Dieva bērnu parādīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Jo tie radījumi ir padoti nīcībai, ne pēc savas gribēšanas, bet Tā dēļ, kas tos tai ir padevis uz cerību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Jo arī tie radījumi paši taps atsvabināti no iznīcības kalpošanas uz Dieva bērnu godības svabadību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Jo mēs zinām, ka visi radījumi kopā nopūšās un kopā mokās līdz šim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Un ne vien tie, bet arī mēs paši, kam Tā Gara pirmība ir, mēs paši arīdzan nopūšamies pie sevis, gaidīdami uz to bērnību, uz mūsu miesas atpestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Jo cerībā mēs esam pestīti. Bet cerība, kas ir redzama, nav cerība; jo ko kas redz, kā tas to var cerēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Bet ja mēs ceram, ko neredzam, tad mēs uz to gaidām ar paciešanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Tāpat arī Tas Gars mūsu vājībai nāk palīgā; jo mēs nezinām, ko mums būs lūgt, kā piederas, bet Tas Gars pats mūs aizstāv ar neizrunājamām nopūtām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Un Tas, kas sirdis pārmeklē, zin, kas ir Tā Gara prāts, jo Tas pēc Dieva prāta tos svētos aizstāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Un mēs zinām, ka tiem, kas Dievu mīl, visas lietas nāk par labu, tiem, kas pēc Viņa nodoma ir aicināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Jo kurus Viņš papriekš paredzējis, tos Viņš arī papriekš ir nolicis, lai Viņa Dēla ģīmim būtu līdzīgi, ka Tas būtu tas pirmdzimtais starp daudz brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Bet kurus Viņš papriekš nolicis, tos Viņš arī aicinājis; un kurus Viņš aicinājis, tos Viņš arī taisnojis; un kurus Viņš taisnojis, tos Viņš arī pagodinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Ko lai nu par to sakām? Ja Dievs par mums, kas būs pret mums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Jo Viņš arī Savu paša Dēlu nav taupījis, bet To par mums visiem nodevis, kā Viņš mums ar To nedāvinās visas lietas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kas apsūdzēs Dieva izredzētos? Dievs ir, kas taisno.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kas pazudinās? Kristus ir nomiris, bet vēl vairāk, Viņš arī uzmodināts; Viņš ir pie Dieva labās rokas, Viņš mūs arī aizstāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kas mūs šķirs no Kristus mīlestības? Vai bēdas, vai bailība, vai vajāšana, vai bads, vai plikums, vai liksta, vai zobens?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Tā kā ir rakstīts: “Tevis dēļ mēs topam nāvēti augu dienu; mēs esam turēti līdzi kaujamām avīm.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Bet visās šinīs lietās mēs pārpārim uzvaram caur to, kas mūs ir mīlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Jo es zinu tiešām, ka ne nāve, ne dzīvība, ne eņģeļi, ne valdības, ne spēki, ne klātbūdamas, ne nākamas lietas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'Ne augstums, ne dziļums, nedz cita kāda radīta lieta mūs nevarēs šķirt no Dieva mīlestības, kas ir iekš Kristus Jēzus, mūsu Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Es patiesību saku iekš Kristus, es nemeloju, jo mana sirdsapziņa man liecību dod iekš Svēta Gara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Ka man ir lielas skumjas un nemitīgas sāpes manā sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Jo es būtu vēlējies pats būt nolādēts no Kristus par maniem brāļiem, kas ir mani radi pēc miesas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Tie ir Israēlieši, tiem pieder tā bērnība un tā godība un tās derības un tā bauslība un Tā Dieva kalpošana un tās apsolīšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Tiem tie tēvi, no kuriem arī Kristus pēc miesas; tas ir Dievs pār visiem, augsti teicams mūžīgi. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Tomēr ne tā, tā kā Dieva vārds būtu pakritis; jo ne visi, kas no Israēla, ir Israēls,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Nedz tie visi tādēļ bērni, ka tie ir Ābrahāma dzimums, bet: “Iekš Īzaka tev dzimums taps dēvēts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Tas ir: ne tie miesas bērni ir Dieva bērni, bet tie apsolīšanas bērni top turēti par dzimumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Jo tas apsolīšanas vārds ir šis: ap šo pašu laiku Es nākšu, tad Sārai būs dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Un ne vien šī, bet arī Rebeka, kad bija grūta no viena, no Īzaka, mūsu tēva -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Jo kad tie bērni vēl nebija dzimuši, nedz darījuši ne laba ne ļauna, lai Dieva nodoms, kā Viņš izredzējis, pastāvētu, ne pēc darbiem, bet pēc Tā aicinātāja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Tad viņai kļuva sacīts: lielākais kalpos mazākajam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Tā kā ir rakstīts: Es Jēkabu esmu mīlējis un Ēsavu ienīdējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Ko nu lai sakām? Vai netaisnība ir pie Dieva? Nebūt ne!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Jo uz Mozu Viņš saka: Es žēlošu, ko žēloju, un apžēlošos, par ko apžēlojos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Tad nu tas nav ne no cilvēka gribēšanas, ne no cilvēka skriešanas, bet no Dieva apžēlošanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Jo tas raksts saka uz Faraonu: itin tāpēc Es tevi esmu cēlis, ka Es pie tevis parādītu Savu spēku, un ka Mans Vārds taptu pasludināts visā pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Tad nu Viņš apžēlojās, par ko Tas grib, un apcietina, ko Tas grib.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Tu nu gan uz mani sacīsi: ko tad Viņš vēl rāj? Jo kas Viņa prātam var pretī turēties?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Bet, ak cilvēciņ! Kas tu tāds esi, ka tu gribi ar Dievu tiesāties? Vai kāds darbs uz savu meistaru saka: kam tu mani tādu esi taisījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Vai tad podniekam nav vara pār mālu, no tās pašas pītes taisīt citu trauku godam un citu negodam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Bet nu Dievs, gribēdams dusmību parādīt un Savu spēku zināmu darīt, ar lielu lēnprātību ir panesis tos dusmības traukus, sataisītus uz pazušanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'Un ka Tas Savas godības bagātību parādītu pie tiem žēlastības traukiem, ko Viņš iepriekš ir sataisījis uz godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Tādus Viņš arī mūs ir aicinājis, ne vien no Jūdiem, bet arī no pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Tā kā Viņš arī pie Hozejas saka: Es tos saukšu par Saviem ļaudīm, kas Mani ļaudis nebija, un par Savu mīļo, kas Man mīļa nebija;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Un notiks tanī vietā, kur uz tiem tika sacīts: Jūs neesat Mani ļaudis! Tur tie taps saukti Tā dzīvā Dieva bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Un Jesaja izsauc pār Israēli: ja Israēla bērnu skaits būtu kā jūras smiltis, tomēr tikai atlikums taps izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Jo Viņš to vārdu piepilda un pasteidz iekš taisnības; jo drīz Tas Kungs to vārdu izdarīs virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Un itin kā Jesaja ir papriekš sacījis: ja Tas Kungs Cebaot mums nebūtu atlicinājis kādu sēklu, tad mēs būtu palikuši tā kā Sodoma un līdzīgi Gomorai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Ko nu lai sakām? Ka pagāni, kas pēc taisnības nedzinās, taisnību dabūjuši, proti to taisnību no ticības;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Bet Israēls, pēc taisnības bauslības dzīdamies, to taisnības bauslību nav panācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Kādēļ? Tādēļ ka ne no ticības bet tā kā no bauslības darbiem (to meklēja); jo tie ir piedauzījušies pie tā piedauzīšanas akmens,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Itin kā ir rakstīts: redzi, Es lieku Ciānā piedauzīšanas akmeni un apgrēcības klinti, un kas uz Viņu tic nepaliks kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Brāļi, mana sirds vēlēšanās un Dieva lūgšana par Israēla bērniem ir, ka tie tiek pestīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Jo es tiem liecību dodu, ka tie karsti dzenās pēc Dieva, bet bez saprašanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Jo nepazīdami Dieva taisnību un meklēdami uzcelt savu pašu taisnību, tie Dieva taisnībai nav paklausījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Jo bauslības gals ir Kristus, par taisnību ikvienam, kas tic.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Jo Mozus raksta par to taisnību, kas nāk no bauslības: kurš cilvēks to dara, tas caur to dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Bet tā taisnība, kas no ticības, saka tā: nesaki savā sirdī, kas uzkāps debesīs? Proti Kristu novest zemē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Jeb: kas nokāps bezdibenī? Proti Kristu no miroņiem atvest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Bet ko tā saka? Tuvu pie tevis ir tas vārds, tavā mutē un tavā sirdī: proti tas ticības vārds, ko mēs pasludinājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Jo ja tu ar savu muti Jēzu apliecināsi par Kungu un savā sirdī ticēsi, ka Dievs Viņu no miroņiem ir uzmodinājis, tad tu mūžīgi dzīvosi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Jo ar sirdi tic uz taisnību un ar muti apliecina uz mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Jo tas raksts saka: neviens, kas uz Viņu tic, nepaliks kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Jo še nav starpības starp Jūdiem un Grieķiem, jo Tas pats ir Kungs pār visiem, bagāts priekš visiem, kas Viņu piesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Jo ikviens, kas Tā Kunga vārdu piesauks, taps izglābts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Kā lai nu To piesauc, uz ko nav ticējuši? Bet kā lai tic, par ko nav dzirdējuši? Bet kā lai dzird bez sludinātāja?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Bet kā lai sludina, ja netop sūtīti? Itin kā ir rakstīts: cik jaukas ir to prieka vēstnešu kājas, kas sludina mieru, kas sludina labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Bet ne visi tam evaņģēlijam bijuši paklausīgi; jo Jesaja saka: Kungs, kas tic mūsu sludināšanai?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Tad nu ticība ir no sludināšanas, un sludināšana caur Dieva vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Bet es saku: vai tie nav dzirdējuši? Tiešām, viņu skaņa ir izgājusi pa visu zemi, un viņu vārdi līdz pasaules galam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Bet es saku: vai Israēls to nav sapratis? Jau Mozus saka: “Es jūs kaitināt kaitināšu caur tautu, kas nav Mana, caur ģeķīgu tautu Es jūs tirināt tirināšu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Bet Jesaja drīkst sacīt: “Es esmu atrasts no tiem, kas Mani nav meklējuši, un esmu tiem parādījies, kas pēc Manis nav vaicājuši.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Bet uz Israēli viņš saka: “Augu dienu Savas rokas esmu izstiepis pār ļaudīm, kas neklausa, bet runā pretī.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Tad nu es saku: vai Dievs Savus ļaudis ir atmetis? Nemaz ne! Jo es arīdzan esmu Israēlietis, no Ābrahāma dzimuma, no Benjamina cilts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Dievs nav vis atmetis Savu tautu, ko Viņš papriekš ir izredzējis. Jeb vai jūs nezināt, ko tas raksts saka par Eliju, kā tas pie Dieva sūdz pret Israēli sacīdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '“Kungs, tie Tavus praviešus ir nokāvuši un Tavus altārus apgāzuši, un es viens esmu atlicis, un tie meklē manu dzīvību.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Bet ko Dievs tam atbildēdams saka? “Es Sev esmu atlicinājis septiņtūkstošus vīrus, kas ceļus nav locījuši Baāla priekšā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Tad nu arīdzan tāpat šinī laikā viens atlikums pēc žēlīgas izredzēšanas ir atlicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Bet ja tas ir caur žēlastību, tad tas vairs nav darbu nopelns; citādi žēlastība nav vairs žēlastība. Bet ja tas ir no darbiem, tad tā nav žēlastība; citādi nopelns nav vairs nopelns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Ko tad nu? Ko Israēls meklē, to viņš nav dabūjis; tie izredzētie gan to ir dabūjuši, bet tie citi ir apcietinājušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Itin kā ir rakstīts: Dievs tiem ir devis grūta miega garu, acis, ka tie neredz, un ausis, ka tie nedzird, līdz šai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Un Dāvids saka: lai viņu galds viņiem paliek par valgu, par slazdu un par piedauzīšanu un par atmaksu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Viņu acis lai top aptumšotas, ka neredz, un loki viņu muguru vienmēr!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Tad nu es saku: vai viņi tāpēc piedauzījušies, lai kristu? Nebūt ne! Bet caur viņu kritumu pagāniem pestīšana notikusi, viņiem par paskubināšanu, šiem dzīties pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Bet, ja viņu kritums pasaulei ir bagātība un viņu trūkums pagāniem bagātība, cik vairāk viņu pilnums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Jo es uz jums pagāniem runāju: pagānu apustulis būdams, es savu amatu gribu godāt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Vai es jel tos, kas ir mana miesa, varētu paskubināt un kādus no tiem izglābt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Jo ja viņu atmešana ir pasaules salīdzināšana, kas tad būs viņu pieņemšana, ja ne dzīvība no miroņiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Un ja tie (mīklas) pirmaji ir svēti, tad arī (visa) tā mīkla, un ja tā sakne svēta, tad arī tie zari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Ja nu kādi no tiem zariem ir nolauzti, un tu, meža eļļas koks būdams, tiem esi uzpotēts un pie tā eļļas koka saknes un taukuma daļu esi dabūjis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Tad nelielies pret tiem zariem; bet ja tu pret tiem lielīsies, tad zini: tu nenesi to sakni, bet tā sakne nes tevi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu nu sacīsi: tie zari ir nolauzti ka es taptu iepotēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Gan labi; tie ir nolauzti neticības dēļ, un tu stāvi caur ticību: nelielies, bet bīsties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Jo ja Dievs tos īstos zarus nav saudzējis, tad Viņš tevi gan arī nesaudzēs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Tad redzi nu Dieva laipnību un bardzību! To bardzību pie tiem, kas ir krituši, bet to laipnību pie tevis, ja tu iekš tās laipnības paliksi; citādi tu arīdzan tapsi izcirsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Un viņi, ja tie neticībā nepaliks, arī taps iepotēti. Jo Dievs ir spēcīgs, viņus atkal iepotēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Jo ja tu no tā eļļas koka, kas pēc savas dabas mežā audzis, esi izcirsts un pret savu dabu esi iepotēts labā eļļas kokā, cik vairāk tie, kas jau pēc savas dabas tādi, savā paša eļļas kokā taps iepotēti!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Jo es negribu, brāļi, jums slēpt šo noslēpumu, (lai jūs neliekaties paši gudri esoši), ka Israēlim pa daļai apcietināšana ir notikusi, tiekams tas pagānu pilnums būs iegājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Un tā viss Israēls taps izglābts, itin kā ir rakstīts: Pestītājs nāks no Ciānas un nogriezīs bezdievīgo būšanu no Jēkaba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Un šī ir Mana derība ar tiem, kad Es viņu grēkus atņemšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Tad pēc evaņģēlija tie gan ir ienaidnieki jūsu dēļ; bet pēc tās izredzēšanas tie ir mīļi to tēvu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Jo Dievam nav žēl Savu žēlastības dāvanu un Savas aicināšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Jo itin kā jūs arīdzan citkārt Dievam bijāt neklausīgi, bet tagad caur viņu neklausīšanu esat apžēloti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Tāpat arī šie tagad bijuši neklausīgi, lai caur to apžēlošanu, kas jums ir notikusi, arī viņi top apžēloti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Jo Dievs visus ir saslēdzis nepaklausībā, ka lai Viņš par visiem apžēlotos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ak Dieva bagātības un gudrības un atzīšanas dziļums! Cik neizmanāmas ir Viņa tiesas un neizdibinājami Viņa ceļi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Jo kas ir atzinis Tā Kunga prātu? Jeb kas ir bijis Viņam padoma devējs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Jeb kas Viņam papriekš devis, ka tam taptu atmaksāts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Jo no Viņa un caur Viņu un uz Viņu ir visas lietas. Viņam lai ir gods mūžīgi! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Tāpēc, brāļi, es jūs lūdzu caur Dieva apžēlošanām, ka jūs savas miesas nodotu par dzīvu, svētu un Dievam patīkamu upuri; tā lai ir jūsu prātīgā Dieva kalpošana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Un nepaliekat šai pasaulei līdzīgi, bet pārvēršaties, savā prātā atjaunodamies, ka jūs varat pārbaudīt, kas ir tas labais un patīkamais un pilnīgais Dieva prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Jo caur to žēlastību, kas man ir dota, es ikvienam jūsu starpā saku, ka nevienam nebūs pārgudram būt vairāk, nekā tam pieklājās gudram būt; bet ka tam būs prātīgi gudram būt, kā kuram Dievs ir izdalījis ticības mēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Jo itin kā mums vienā miesā ir daudz locekļu, bet visiem tiem locekļiem nav vienāds darbs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Tāpat mēs daudzi esam viena miesa iekš Kristus, bet savā starpā mēs esam cits cita locekļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Un mums ir dažādas dāvanas pēc tās žēlastības, kas mums dota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Ja kam ir praviešu mācība, lai tā saietās ar ticību; ja kam kāds amats, tas lai paliek tai amatā; ja kas māca, tas lai paliek tai mācīšanā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Ja kas pamāca, tas lai paliek tai pamācīšanā; kas ko dod, lai to dara iekš vientiesības; kas valda, lai to dara rūpīgi; kas apžēlojās, lai to dara ar prieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Mīlestība lai ir bezviltīga; ienīstat ļaunu, pieķeraties labam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Lai brāļu mīlestība jūsu starpā ir sirsnīga, un godu dodot nākat viens otram pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Neesiet kūtri iekš tā, kas jums jādara; esiet dedzīgi garā, kalpojiet Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Esiet priecīgi cerībā, pacietīgi bēdās, pastāvīgi lūgšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Nāciet palīgā tiem svētiem viņu vajadzībās; dodiet labprāt mājas vietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Svētījiet tos, kas jūs vajā, svētījiet un nelādiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Līksmojaties ar līksmiem un raudiet ar tiem, kas raud.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Esiet savā starpā vienprātīgi, nedzīdamies pēc augstām lietām, bet turēdamies pazemīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Neliekaties paši gudri esoši; neatmaksājiet nevienam ļaunu ar ļaunu, turaties pa godam visu cilvēku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Ja tas var būt, no savas puses turat mieru ar visiem cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Neatriebjaties paši, mīļie, bet dodiet vietu Dieva dusmībai. Jo ir rakstīts: “Man pieder atriebšana! Es atmaksāšu,” saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Tad nu, ja tavs ienaidnieks ir izsalcis, tad ēdini to; ja tas izslāpis, tad dzirdini to. Jo to darīdams tu kvēlainas ogles sakrāsi uz viņa galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ļaunums lai tevi neuzvar, bet uzvari tu ļaunumu ar labumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Ikviens lai ir paklausīgs tām valdīšanām, kam tā vara; jo nekādas valdīšanas nav kā vien no Dieva, un kur valdīšanas ir, tur tās no Dieva ir ieceltas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Tad nu, kas valdīšanai turas pretī, tas turas pretī Dieva likumam. Bet kas pretī turas, tie dabūs savu sodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Jo valdnieki nav bijājami labiem darbiem, bet ļauniem; ja tu negribi no valdīšanas bīties, tad dari labu, tad tev būs teikšana no viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Jo tā ir Dieva kalpone tev par labu; bet ja tu ļaunu dari, tad bīsties, jo tā zobenu nenes velti, jo tā ir Dieva kalpone, atriebēja ļaundarītājam par sodību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Tāpēc vajag paklausīt ne vien sodības dēļ bet arī zināmas sirds dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Tāpēc dodat arī meslus. Jo tie ir Dieva sulaiņi, šo savu amatu kopdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Tad nu dodiet ikvienam, kas tam nākas: meslus, kam mesli nākas; muitu, kam muita nākas; bijāšanu, kam bijāšana nākas; godu, kam gods nākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Neesiet nevienam neko parādā, kā vien, ka jūs cits citu mīlat; jo kas otru mīl, tas bauslību ir piepildījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Jo tas bauslis: tev nebūs laulību pārkāpt, tev nebūs nokaut, tev nebūs zagt, tev nebūs nepatiesu liecību dot, tev nebūs iekārot, un ja vēl ir cits bauslis, tas šinī vārdā top saņemts, proti tanī: tev būs savu tuvāko mīlēt kā sevi pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Mīlestība tuvākam ļauna nedara; tad nu mīlestība ir bauslības piepildīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Un to dariet, zinādami to laiku, ka tagad mums ir tā stunda celties no miega; jo tagad mūsu pestīšana ir tuvāka, nekā kad mēs palikām ticīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Nakts ir pagājusi un diena tuvu nākusi, tad lai noliekam tumsības darbus un lai apvelkam gaismas ieročus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Lai tā kā dienā godīgi staigājam, ne rīšanā un plītēšanā, ne izvirtībā un nešķīstībā, ne bāršanā un ienaidībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Bet apvelciet To Kungu Jēzu Kristu un nekopiet miesu uz kārībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Pieņemiet to, kas ir vājš ticībā, viņa prātu nesajaukdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Jo cits tic, ka visu var ēst, bet kas ir vājš, tas ēd dārza augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Kas ēd, tas lai nenicina to, kas neēd; un kas neēd, tas lai netiesā to, kas ēd; jo Dievs viņu ir pieņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Kas tu tāds esi, ka tu cita kalpu tiesā? Viņš stāv, vai krīt savam paša Kungam; bet viņš taps pacelts, jo Dievs ir spēcīgs, viņu pacelt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Dažs cienī vienu dienu vairāk nekā otru, bet dažs visas dienas cienī vienādi; ikviens par to lai pats savā prātā zinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kas kādu dienu cienī, tas to cienī Tam Kungam; un kas to dienu necienī, tas to necienī Tam Kungam. Kas ēd, tas ēd Tam Kungam, jo viņš pateicās Dievam; un kas neēd, tas neēd Tam Kungam, un pateicās Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Jo neviens mūsu starpā nedzīvo sev pašam, un neviens nemirst sev pašam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Jo kad dzīvojam, tad dzīvojam Tam Kungam; kad mirstam, tad mirstam Tam Kungam. Tāpēc vai dzīvojam, vai mirstam, mēs piederam Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Jo tādēļ Kristus arī miris un augšāmcēlies un atkal dzīvs tapis, ka tas būtu Kungs pār mirušiem un dzīviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Bet tu, ko tu tiesā savu brāli? Jeb arī tu, ko tu nicini savu brāli? Jo mums visiem būs jāstājas priekš Kristus');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Jo ir rakstīts: “Es dzīvoju, saka Tas Kungs, Manā priekšā visi ceļi locīsies, un ikviena mēle teiks Dievu.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Tad nu ikviens no mums pats par sevi dos atbildēšanu Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Tāpēc lai mēs cits citu vairs netiesājam, bet to tiesājiet jo vairāk, ka neviens savam brālim neliek piedauzīties, nedz tam dod apgrēcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Es zinu un atzīstu tiešām iekš Tā Kunga Jēzus, ka neviena lieta no sevis nav nešķīsta; bet tam vien, kas to par nešķīstu tura, tam tā ir nešķīsta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Bet ja tavs brālis ēdiena dēļ noskumst, tad tu vairs nestaigā pēc mīlestības. Nesamaitā ar savu ēdienu to, par ko Kristus ir miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Tad nu lai jūsu labums netop zaimots,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Jo Dieva valstība nav ēdiens un dzēriens, bet taisnība un miers un prieks iekš Svētā Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Jo kas šinīs lietās Kristum kalpo, tas ir Dievam patīkams un cilvēkiem pieņēmīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Tādēļ lai pēc tā dzenamies, kas der mieram un uztaisīšanai jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Neposti Dieva darbu ēdiena dēļ. Visas lietas gan ir šķīstas, bet tās ir nelabas tam cilvēkam, kas ēd un piedauzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Labāki ir, gaļas neēst un vīna nedzert, nekā to darīt, pie kā tavs brālis piedauzās, jeb apgrēcinājās, jeb (ticībā) top vājš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Ja tev ir ticība, tad lai tā ir tev pašam Dieva priekšā. Svētīgs ir tas, kas sevi pašu netiesā iekš tā, ko viņš tura par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Bet kam ēdot prāts šaubās, tas ir pazudināts, jo tas nenāk no ticības; bet viss, kas nav no ticības, tas ir grēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Bet mums, kas esam stipri, pienākas panest nestipro vājības un nevis sev pašiem būt pa prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Jo ikviens no mums lai savam tuvākam ir pa prātam uz labu un par uztaisīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Jo arī Kristus nav Sev pašam bijis pa prātam, bet kā stāv rakstīts: “Tavu nievātāju nievāšanas Man ir uzkritušas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Jo viss, kas ir papriekš rakstīts, tas mums papriekš rakstīts par mācību, lai mums cerība būtu caur paciešanu un Dieva rakstu iepriecināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Bet lai tas paciešanas un iepriecināšanas Dievs jums dod vienādu prātu jūsu starpā pēc Kristus Jēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Ka jūs vienprātīgi vienā mutē varat pagodināt Dievu un mūsu Kunga Jēzus Kristus Tēvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Tāpēc uzņematies cits citu, itin kā arī Kristus jūs ir uzņēmis Dievam par godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Un es saku, ka Jēzus Kristus ir palicis par apgraizīšanas kalpu Dieva patiesības labad, ka Viņš apstiprinātu to tēvu apsolīšanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Un ka pagāni Dievu slavētu par to žēlastību, tā kā ir rakstīts: “Tāpēc es Tevi gribu teikt starp pagāniem un Tavam vārdam dziedāt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Un atkal tas saka: “Priecājaties, jūs pagāni, līdz ar Viņa ļaudīm.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Un atkal: “Slavējat To Kungu, visi pagāni, un teiciet Viņu, visas tautas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Un atkal Jesaja saka: “Tur būs Isajus sakne, un (Viņš) kas celsies valdīt pār pagāniem; uz To pagāni cerēs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Bet Tas cerības Dievs lai jūs piepilda ar visu prieku un mieru iekš ticības, ka varat būt bagāti iekš cerības caur Svētā Gara spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Tomēr, mani brāļi, es pats arīdzan no jums gan zinu, ka arī jūs paši esat pilni labprātības, piepildīti ar visu atzīšanu, ka jūs varat cits citu paskubināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Bet vietām jums, mani brāļi, drošāki esmu rakstījis, jums atgādinādams caur to žēlastību, kas man ir dota no Dieva,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Lai es esmu Jēzus Kristus kalps pie pagāniem, strādādams to svēto Dieva evaņģēlija darbu, lai pagāni paliek par patīkamu upuri, kas svētīts caur Svēto Garu');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Tad nu man Dievam kalpojot ir ko teikties iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Jo es neiedrošināšos ko runāt, ko Kristus pagānu paklausības labad caur mani nav strādājis ar vārdiem un darbiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Caur zīmju un brīnumu spēku, caur Dieva Gara spēku, tā ka es Kristus evaņģēliju esmu izpaudis no Jeruzālemes visapkārt līdz Illirijai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Un tā no sirds darbojies, evaņģēliju pasludināt, kur Kristus vārds vēl netapa piesaukts, ka es to namu neuzceltu uz cita pamatu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Bet itin kā ir rakstīts: kam no tā nav sludināts, tie redzēs; un kas nav dzirdējuši, tie dabūs zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Tāpēc es arī daudzreiz esmu aizkavēts pie jums nākt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Bet kad tagad šinīs zemēs man vairs nav vietas, un man jau no daudz gadiem gribās pie jums nākt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Tad es uz Spāniju iedams pie jums nākšu; jo es ceru, ka pārstaigādams jūs redzēšu, un no jums uz turieni tapšu pavadīts, kad es papriekš maķenīt ar jums būšu papriecājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Bet tagad es eju uz Jeruzālemi, tiem svētiem palīdzību nesdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Jo Maķedonijai un Akajai ir paticis, kādas dāvanas samest priekš tiem nabagiem, kas ir starp tiem svētiem Jeruzālemē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Jo tiem tā ir paticis; tie ir arīdzan viņu parādnieki. Jo ja pagāni pie viņu garīgām dāvanām daļu ir dabūjuši, tad arī šiem pienākas ar tām laicīgām viņiem kalpot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Tad to pabeidzis un šo augli tiem apzieģelējis es noiešu caur jums uz Spāniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Un es zinu, ka es pie jums nākdams ar pilnu Kristus evaņģēlija svētību nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Bet es jūs lūdzu, brāļi, caur mūsu Kungu Jēzu Kristu un caur Tā Gara mīlestību, ka jūs līdz ar mani cīnāties, par mani Dievu lūgdami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Lai es topu izglābts no tiem neticīgiem Jūdejā, un lai šī mana kalpošana, kas Jeruzālemes labad notiek, tiem svētiem būtu patīkama,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Ka es pēc Dieva prāta ar prieku varu nākt pie jums un līdz ar jums atspirdzinājos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Un tas miera Dievs lai ir ar jums visiem. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Vēl es jums pavēlu Foibu, mūsu māsu, kas ir draudzes kalpone Kenhrejā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Ka jūs to uzņemat iekš Tā Kunga, kā tiem svētiem pieklājās, un tai palīdzat, kurā lietā tai ko no jums vajadzēs: jo tā arīdzan palīdzīga bijusi daudziem, arī man pašam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Sveicinājiet Prisķilu un Aķilu, manus darba biedrus iekš Kristus Jēzus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Tie par manu dzīvību ir nolikuši savu pašu kaklu, - tiem ne vien es pateicos, bet arīdzan visas draudzes no pagāniem; Nehem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Arī to draudzi viņu namā. Sveicinājiet Epenetu, manu mīļo, kas no Āzijas tas pirmais pie Kristus ir griezies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Sveicinājiet Mariju, kas par mums daudz ir pūlējusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Sveicinājiet Androniku un Jūniju, manus radus un cietuma biedrus, kas pie tiem apustuļiem ir cienīti, un jau priekš manis ir bijuši iekš Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Sveicinājiet Ampliju, manu mīļo iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Sveicinājiet Urbanu, mūsu darba biedru iekš Kristus un Staķiju, manu mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Sveicinājiet Apellu, kas uzticīgs iekš Kristus; sveicinājiet tos, kas ir no Aristobula saimes;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Sveicinājiet Herodionu, manu radinieku. Sveicinājiet tos, kas no Narkisa saimes ir iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Sveicinājiet Trivenu un Trivozu, kas strādā iekš Tā Kunga. Sveicinājiet Perzidu, to mīļo, kas daudz ir strādājusi iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Sveicinājiet Rufu, to izredzēto iekš Tā Kunga, un viņa un manu māti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Sveicinājiet Azinkritu un Flegontu, Ermani, Patrobu, Ermeni un tos brāļus, kas pie tiem ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Sveicinājiet Filologu un Jūliju, Nereu un viņa māsu un Olimpu un visus svētos, kas pie tiem ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Sveicinājiet cits citu ar svētu skūpstīšanu. Visas Kristus draudzes jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Bet es jūs pamācu, brāļi, sargājaties no tiem, kas šķelšanos un apgrēcības ceļ pret to mācību, ko jūs esat mācījušies, un atkāpjaties no tiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Jo tie tādi nekalpo mūsu Kungam Jēzum Kristum, bet savam pašu vēderam, un caur laipnīgām runām un saldiem vārdiem tie pieviļ vientiesīgas sirdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Jo jūsu paklausība ir izpaudusies pie visiem, tāpēc es par jums priecājos; bet es gribu, ka jūs esat gudri uz labu, bet nejēgas uz ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Bet tas miera Dievs samīs sātanu apakš jūsu kājām īsā laikā. Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jums. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timotejs, mans darba biedrs, un Lucijus un Jazons un Zozipaters, mani radi, jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Es, Tercijus, kas šo grāmatu esmu rakstījis, jūs sveicinu iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gajus, mans un visas draudzes nama tēvs, jūs sveicina; Erasts, pilsētas mantas valdnieks, un Kvartus, tas brālis, jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jums visiem. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Bet Tam, kas jūs spēj stiprināt pēc mana evaņģēlija un Jēzus Kristus sludināšanas, pēc tā noslēpuma parādīšanas, kas no mūžīgiem laikiem nav bijis dzirdēts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Bet tagad zināms darīts un caur praviešu rakstiem pēc tā mūžīgā Dieva pavēlēšanas ir sludināts visiem pagāniem, lai šie ticībai paklausa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Tam vienam gudram Dievam lai ir gods mūžīgi caur Jēzu Kristu. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Pāvils, caur Dieva prātu aicināts par Jēzus Kristus apustuli, un Sostens, tas brālis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Tai Dieva draudzei, kas ir Korintū, tiem iekš Kristus Jēzus svētītiem, tiem aicinātiem svētiem, un visiem, kas mūsu Kunga Jēzus Kristus vārdu piesauc kaut kurā vietā, tā pie viņiem, kā pie mums:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Es savam Dievam arvien pateicos par jums Dieva žēlastības dēļ kas jums ir dota iekš Kristus Jēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Ka jūs iekš Viņa bagāti esat darīti visās lietās, ikvienā mācībā un ikvienā atzīšanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Tā kā Kristus liecība ir apstiprināta jūsu starpā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Un ka nekādas dāvanas jums netrūkst, kas gaidāt uz mūsu Kunga Jēzus Kristus parādīšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Tas jūs arī apstiprinās līdz galam, ka esat bezvainīgi mūsu Kunga Jēzus Kristus dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Dievs ir uzticīgs, caur ko jūs esat aicināti pie Viņa Dēla Jēzus Kristus, mūsu Kunga, biedrības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Bet es jūs pamācu, brāļi, caur mūsu Kunga Jēzus Kristus vārdu, lai jums visiem ir vienāda valoda, un lai nav jūsu starpā nekādas šķelšanās, bet lai jūs esat pilnīgi vienādā prātā un vienādā padomā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Jo caur tiem, kas ir Kloēs namā, man ir stāstīts par jums, mani brāļi, ka jūsu starpā esot strīdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Bet es runāju par to, ka ikviens no jums saka: es esmu Pāvila, bet es Apollus, bet es Kefasa, bet es Kristus māceklis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Vai tad Kristus ir dalīts? Vai Pāvils par jums krustā sists? Jeb vai jūs esat kristīti uz Pāvila vārdu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Es Dievam pateicos, ka es nevienu no jums neesmu kristījis, kā tikai Krispu un Gaju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Lai jel neviens nesaka, ka esmu kristījis uz savu vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Bet arī Stefana namu es esmu kristījis. Bez tiem nezinu, vai citu kādu esmu kristījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Jo Kristus mani nav sūtījis kristīt, bet evaņģēliju sludināt, ne ar gudriem vārdiem, lai Kristus krusts netop iznīcināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Jo tas vārds no tā krusta ir ģeķība tiem, kas pazūd, bet mums, kas topam izglābti, tas ir Dieva spēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Jo ir rakstīts: “Es samaitāšu gudrību gudriem un iznīcināšu prātu prātīgiem.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kur tie gudrie? Kur tie rakstu mācītāji? Kur tie šī laika zinātnieki? Vai šīs pasaules gudrību Dievs nav darījis par ģeķību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Jo kad pasaule caur savu gudrību Dievu neatzina Dieva gudrībā, tad Dievam ir paticis, caur ģeķīgu sludināšanu ticīgos darīt svētus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Jo Jūdi prasa zīmes un Grieķi meklē gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Bet mēs sludinājam Kristu, To krustā sisto, kas Jūdiem apgrēcība un Grieķiem ģeķība;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Bet tiem aicinātiem, tā Jūdiem kā Grieķiem, mēs sludinājam Kristu kā Dieva spēku un Dieva gudrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Jo Dieva ģeķība ir gudrāka nekā cilvēki, un Dieva nespēcība spēcīgāka nekā cilvēki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Jo raugāt, brāļi, savu aicināšanu, ka nav daudz gudru pēc miesas, ne daudz spēcīgu, ne daudz no augstas dzimtas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Bet kas ģeķīgs pasaulei, to Dievs ir izredzējis, ka Viņš tos gudros liktu kaunā, un kas nespēcīgs pasaulei, to Dievs ir izredzējis, ka Viņš tos spēcīgos liktu kaunā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Un kas necienīgs pasaulei un pulgots, un kas nav nekas, to Dievs ir izredzējis, ka Viņš iznīcinātu to, kas ir kas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Lai neviena miesa Viņa priekšā nelielās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Bet no Viņa jūs esat iekš Kristus Jēzus, kas mums no Dieva ir dots par gudrību un taisnību un svētu darīšanu un pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Tā kā ir rakstīts: kas lielās, lai lielās iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Un pie jums nākdams, brāļi, es nenācu ar augstu valodu vai gudrību, jums Dieva liecību pasludinādams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Jo nedomāju, ka es jūsu starpā ko zinot, kā vien Jēzu Kristu un To pašu krustā sistu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Un es biju pie jums vājībā un bijāšanā un lielā drebēšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Un mana valoda un mana sludināšana nebija iekš mīkstiem cilvēku gudrības vārdiem, bet iekš Gara un spēka parādīšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Lai jūsu ticība nebūtu iekš cilvēku gudrības, bet iekš Dieva spēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Bet mēs sludinājam, kas gan gudrība pie tiem pilnīgiem, bet kas nav gudrība pie šīs pasaules, nedz pie šīs pasaules valdniekiem, kas iznīkst;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Bet mēs sludinājam Dieva gudrību noslēpumā, to apslēpto, ko Dievs priekš pasaules laikiem ir nolēmis mums par godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'To neviens no šīs pasaules virsniekiem nav atzinis; jo, ja tie To būtu atzinuši, tad tie To godības Kungu nebūtu krustā situši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Bet itin kā ir rakstīts: Ko acs nav redzējusi, un auss nav dzirdējusi, un kas neviena cilvēka sirdī nav nācis, to Dievs ir sataisījis tiem, kas Viņu mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Bet mums Dievs to ir parādījis caur Savu Garu; jo Tas Gars izmana visas lietas, arī Dieva dziļumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Jo kurš cilvēks zin, kas ir iekš cilvēka, kā vien cilvēka gars, kas iekš tā ir? Tāpat arīdzan neviens nezin, kas ir iekš Dieva, kā vien Dieva Gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Bet mēs neesam dabūjuši pasaules garu, bet to Garu, kas ir no Dieva, lai zinām, ko Dievs mums ir dāvinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'To mēs arī nerunājam ar vārdiem, ko cilvēku gudrība māca, bet ar vārdiem, ko Svētais Gars māca, garīgas lietas garīgi apspriezdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Bet miesīgs cilvēks nesaņem, kas ir no Dieva Gara, jo tas viņam ir ģeķība, un viņš to nevar saprast, jo tas ir garīgi apspriežams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Bet tas garīgais cilvēks visas lietas prot apspriest, bet par viņu neviens neprot spriest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Jo kas ir atzinis Tā Kunga prātu, ka tas Viņu pamācītu? Bet mums ir Kristus prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Un, brāļi, es nevarēju ar jums runāt kā ar garīgiem, bet kā ar miesīgiem, kā ar nejēgām iekš Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Es jūs esmu dzirdinājis ar pienu un ne ar barību, jo jūs vēl nespējāt; bet arī tagad jūs vēl nespējiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Jo jūs vēl esat miesīgi: jo kamēr jūsu starpā ir ienaids un strīdus un šķelšanās, vai jūs neesat miesīgi un vai nestaigājat pēc cilvēku kārtas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Jo kad cits saka: es turos pie Pāvila, un cits: es pie Apollus, vai jūs neesat miesīgi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kas tad ir Pāvils, un kas ir Apollus? Tie ir kalpi vien, caur kuriem jūs esat palikuši ticīgi, un tā, kā Tas Kungs ikvienam ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Es esmu dēstījis, Apollus ir slacinājis; bet Dievs ir audzinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Tad nu nedz tas dēstītājs ir kas, nedz tas slacinātājs, bet Dievs, kas audzina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Un tas dēstītājs un tas slacinātājs ir vis viens; bet ikkatrs dabūs savu īpašu algu, pēc sava īpaša darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Jo mēs esam Dieva darba biedri, jūs esat Dieva aramais tīrums, Dieva ēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Pēc tās Dieva žēlastības, kas man ir dota, es kā gudrs nama taisītājs esmu licis pamatu, un cits uz tā uztaisa ēku; - bet ikvienam būs pielūkot, kā viņš to ēku uztaisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Jo citu pamatu neviens nevar likt pār to, kas ir likts, proti Jēzus, Tas Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Bet, ja kas uz šo pamatu uzceļ zeltu, sudrabu, dārgus akmeņus, kokus, sienu, salmus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Tad ikviena darbs taps redzams, jo tā diena to atklās, - tāpēc, ka šī ugunī parādīsies; un kāds ikkatra darbs ir, to uguns pārbaudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Ja kāda darbs paliek, ko tas tur virsū uzcēlis, tas dabūs algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Ja kāda darbs sadegs, tam būs jācieš, bet viņš pats taps izglābts, tomēr kā caur uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Vai nezināt, ka jūs esat Dieva nams, un ka Dieva Gars iekš jums mājo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Ja kas Dieva namu samaitā, to Dievs samaitās; jo Dieva nams ir svēts, un jūs tas esat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Lai neviens nepieviļas. Ja kam jūsu starpā šķiet, ka viņš gudrs šinī pasaulē, tas lai top ģeķis, lai kļūst gudrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Jo šīs pasaules gudrība ir ģeķība pie Dieva, jo ir rakstīts: “Viņš satver gudros viņu viltībā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Un atkal: Tas Kungs pazīst gudro domas, ka tās nelietīgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Tad nu neviens lai nelielās ar cilvēkiem. Jo viss jums pieder,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Lai Pāvils, lai Apollus, lai Kefas, lai pasaule, lai dzīvība, lai nāve, lai klātesošas lietas, lai nākamas - viss jums pieder;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Bet jūs Kristum, bet Kristus Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Par tādiem lai ikviens cilvēks mūs tura: par Kristus kalpiem un par Dieva noslēpumu nama turētājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Visnotaļ nu pie nama turētājiem meklē, ka tie top atrasti uzticīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Bet tā man maza lieta, ka es no jums, jeb no cilvēku tiesas kļūstu tiesāts, un es arī pats sevi netiesāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Es gan nenieka neapzinos, bet tādēļ vēl neesmu taisnots; bet kas mani tiesā, ir Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Tad nu netiesājiet neko priekšlaikus, kamēr Tas Kungs nāks, Tas arī vedīs gaismā, kas apslēpts tumsībā, un darīs zināmus siržu padomus; un tad ikvienam sava teikšana būs no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Bet to es esmu zīmējis, brāļi, uz sevi un uz Apollu jūsu labad, lai jūs mācaties pie mums, nebūt gudrāki pār to, kas ir rakstīts, lai jūs neviena dēļ neuzpūšaties cits pret citu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Jo kas tevi cēlis pār citiem? Un kas tev ir, ko neesi dabūjis? Bet ja tu arī esi dabūjis, ko tu lielies, tā kā nebūtu dabūjis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Jūs jau esat pieēduši, jau esat palikuši bagāti, bez mums jūs esat sākuši valdīt, un ak! Kaut jūs valdītu, ka arī mēs varētu valdīt līdz ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Jo man šķiet, ka Dievs mūs apustuļus ir nolicis par pēdīgiem tā kā nāvei nodotus; jo mēs esam palikuši kā par ērmiem pasaulei, tā eņģeļiem, kā cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Mēs esam ģeķi Kristus dēļ bet jūs prātīgi iekš Kristus; mēs vāji, bet jūs spēcīgi; jūs cienīgi, bet mēs nicināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Mēs līdz šai pašai stundai esam izsalkuši un noslāpuši un esam pliki un topam sisti un dzenāti');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Un darbojamies strādādami ar savām rokām; mēs topam lamāti, un svētījam; mēs topam vajāti, un paciešamies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Mēs topam zaimoti un lūdzam; mēs esam tapuši tā kā mēsli pasaulē un visiem par noslauku līdz šim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'To nerakstu, jūs apkaunodams, bet es jūs pamācu kā savus mīļos bērnus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Jo jebšu jums būtu desmit tūkstoš pamācītāju iekš Kristus, tad tomēr jums nav daudz tēvu; jo es jūs esmu dzemdinājis iekš Kristus Jēzus caur evaņģēliju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Tāpēc jūs pamācu: dzenaties man pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Tādēļ jums esmu sūtījis Timoteju, kas ir mans mīļais un uzticīgais bērns iekš Tā Kunga; tas jums atgādinās manus ceļus iekš Kristus, kā es visur visās draudzēs mācu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Bet citi uzpūzdamies saka, ka es pie jums nenākšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Bet es drīz pie jums nākšu, ja Tas Kungs gribēs, un redzēšu - ne to vārdus, kas uzpūtušies, bet viņu spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Jo Dieva valstība nestāv vārdos, bet spēkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Ko jūs gribat? Vai man pie jums būs nākt ar rīksti, vai ar mīlestību un ar lēnu garu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Visnotaļ dzird, ka maucība pie jums, un vēl tāda maucība, kādas nav ne pie pagāniem, ka kāds dzīvo ar sava tēva sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Un jūs esat uzpūtušies un ne jo vairāk noskumuši, tā ka no jūsu vidus tas taptu izmests, kas tādu nedarbu darījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Jo pēc miesas gan klāt nebūdams, bet garā klāt būdams, es jau tā kā klāt būdams esmu spriedis par to, kas šo nedarbu tā darījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Ka mūsu Kunga Jēzus Kristus vārdā sanākam, jūs un mans gars ar mūsu Kunga Jēzus Kristus spēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Un to tādu nododam sātanam uz miesas samaitāšanu, lai gars top izglābts Tā Kunga Jēzus dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Jūsu slava nav laba. Vai nezināt, ka maz rauga saraudzē visu mīklu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Tāpēc izmetat ārā to veco raugu, ka esat jauna mīkla, itin kā jūs esat neraudzēti; jo arī par mums mūsu Lieldienas jērs ir upurēts, tas ir Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Tad lai svētkus turam ne ar veco raugu, nevis ar blēdības un ļaundarības raugu, bet ar skaidrības un patiesības neraudzētām maizēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Es jums esmu rakstījis savā grāmatā, lai nebiedrojaties ar mauciniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Tomēr es to nesaku pavisam no tiem mauciniekiem šinī pasaulē, vai no plēsējiem vai laupītājiem vai elka dievīgiem; citādi jums no pasaules būtu jāiziet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Bet nu es jums esmu rakstījis, lai jūs ar tiem nepinaties, ja kāds, kas saucās par brāli, ir maucinieks vai plēsējs(alkatīgs) vai elkadievīgs vai zaimotājs vai dzērājs vai laupītājs, ka jums ar tādu nebūs ne ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Jo ko man būs sodīt tos, kas ir ārā, un jūs nesodat tos, kas ir iekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Bet tos, kas ir ārā, Dievs sodīs. Izmetiet ārā to ļauno no sava pašu vidus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Ja kam no jums kāda sūdzība ir pret citu kādu, kā tas gan drīkst tiesāties priekš tiem netaisniem un ne priekš tiem svētiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Vai jūs nezināt, ka tie svētie pasauli tiesās; un ja caur jums pasaule kļūst tiesāta, vai tad jūs esat necienīgi, tās mazākās lietas tiesāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Vai nezināt, ka mēs tiesāsim eņģeļus? Kā ne jo vairāk laicīgas lietas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Kad nu jums par laicīgām lietām jātiesājas; kas draudzē necienīti, tādus jūs ieceļat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Es to saku jums par kaunu. Vai tad jūsu starpā nav neviena gudra, neviena, kas varētu tiesu spriest starp saviem brāļiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Bet brālis iet ar brāli tiesāties, un tad vēl pie neticīgiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Jo tā jau ir vaina pie jums, ka jūs pavisam(vispār) savā starpā tiesājaties; kādēļ jūs labāk neciešat netaisnību? Kādēļ jūs labāk neciešat pārestību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Bet jūs dariet netaisnību un dariet pāri, un to vēl brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Vai nezināt, ka netaisnie Dieva valstību neiemantos? Nepieviļaties! Ne maucinieki, ne elkadievīgie, ne laulības pārkāpēji, ne malaki*, ne tie, kas pie vīriem guļ,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ne zagļi, ne plēsēji, ne dzērāji, ne zaimotāji, ne laupītāji Dieva valstību neiemantos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Un kādi no jums bija tādi; bet jūs esat nomazgāti, bet jūs esat svēti darīti, bet jūs esat taisnoti iekš Tā Kunga Jēzus vārda un iekš mūsu Dieva Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Viss man ir brīv, bet ne viss der. Viss man ir brīv, bet nekam es nepadošos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Barība vēderam, un vēders barībai, bet Dievs iznīcinās gan šo, gan to; bet miesa nav maucībai, bet Tam Kungam, un Tas Kungs miesai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Bet Dievs ir To Kungu uzmodinājis un arī mūs uzmodinās caur Savu spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Vai nezināt, ka jūsu miesas ir Kristus locekļi? Vai tad es ņemtu Kristus locekļus un darītu par maukas locekļiem? Nemūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Jeb vai nezināt, ka tas, kas maukai pieķeras, ir viena miesa ar to? Jo viņš saka: tie divi būs viena miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Bet kas Tam Kungam pieķeras, tas ir viens gars ar To.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Bēgat no maucības! Visi grēki, ko cilvēks dara, ir ārpus miesas; bet kas maucību dara, tas grēko pie savas paša miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Jeb vai nezināt, ka jūsu miesa ir Tā Svētā Gara dzīvoklis, kas ir iekš jums, ko jūs no Dieva esat dabūjuši, un jūs nepiederat sev pašiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Jo jūs esat dārgi atpirkti. Tad nu godiniet Dievu savā miesā un savā garā, kas pieder Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Bet par to, ko jūs man esat rakstījuši, saku: cilvēkam ir labi, sievas neaizskart;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Bet lai maucība nenotiek, tad lai ikkatram ir sava sieva, un lai ikkatrai ir savs vīrs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Vīrs sievai lai parāda pienākamu mīlestību; tā arīdzan sieva vīram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Sievai nav vaļas par savu miesu, bet vīram; tā arī vīram nav vaļas par savu miesu, bet sievai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Neatraujaties viens otram, kā tikai vienā prātā uz kādu laiku, lai jums vaļa ir Dievu lūgt; un nāciet atkal kopā, lai sātans jūs nekārdina, kad nevarat valdīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'To saku, atvēlēdams un ne pavēlēdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Jo es gribētu, ka visi cilvēki tādi būtu, kā es; bet ikkatram ir sava dāvana no Dieva, vienam šāda, otram tāda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Bet es saku nelaulātiem un atraitnēm: labi tiem, ja tie paliek itin kā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Bet ja tie nevar valdīties, tad lai iedodas laulībā: jo labāki ir iedoties laulībā, nekā degt kārībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Bet laulātiem pavēlu ne es, bet Tas Kungs, lai sieva neatšķiras no vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Un ja tā arī būtu atšķīrusies, tad tai būs palikt bez laulības, vai salīgt ar vīru; un lai vīrs neatstumj sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Bet tiem citiem saku es, ne Tas Kungs: ja kādam brālim ir neticīga sieva un tai ir pa prātam, dzīvot ar viņu, lai viņš to neatstumj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Un ja sievai ir neticīgs vīrs, un tam ir pa prātam, dzīvot ar viņu, tā lai viņu neatstumj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Jo neticīgais vīrs ir svētīts caur sievu, un neticīgā sieva ir svētīta caur vīru, jo citādi jūsu bērni būtu nešķīsti, bet tagad tie ir svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Bet ja tas neticīgais atšķiras, tad lai tas atšķiras; tas brālis vai tā māsa šinīs lietās nav saistīti. Dievs mūs ir aicinājis uz mieru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Jo ko tu, sieva, zini, vai tu vīru izglābsi? Jeb ko tu, vīrs, zini, vai tu sievu izglābsi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Tomēr kā kuram Dievs ir piešķīris, kā kuru Tas Kungs ir aicinājis, tā lai tas staigā, un tāpat es pavēlu visās draudzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Jo kas ir aicināts apgraizīts, tas lai neuzvelk priekšādu; ja kas ir aicināts iekš priekšādas, tas lai netop apgraizīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Apgraizīšana nav nekas, un priekšāda nav nekas, bet Dieva baušļu turēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Kā kurš ir aicināts, tā lai viņš paliek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Ja tu kalps būdams esi aicināts, nebēdā par to; bet ja tu vari tapt svabads, tad to jo labāki pieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Ja kas iekš Tā Kunga ir aicināts, kalps būdams, tas ir Tā Kunga svabadnieks; tāpat arīdzan, kas svabadnieks būdams, ir aicināts, tas ir Kristus kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Jūs esat dārgi atpirkti; netopiet cilvēku kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Ikkatram, brāļi, kā tas ir aicināts, tā tam būs palikt pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Bet par tām meitām man nav Tā Kunga pavēles; bet padomu dodu, kā no Tā Kunga žēlastību dabūjis, ka esmu uzticīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Tad nu man šķiet, tā esam labi tagadēja bēdu laika dēļ, ka cilvēkam labi, tāpat palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Ja esi saderēts ar sievu, tad nemeklē atlaišanu; ja esi vaļā no sievas, tad nemeklē sievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Bet ja arī būsi laulībā iedevies, tad neesi grēkojis, un ja meita būs laulībā iedevusies, tad tā nav grēkojusi; bet tādiem pie miesas būs bēdas, bet es jūs gribētu saudzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Bet to es saku, brāļi, tas laiks ir īss; tāpēc nu tie, kam sievas, lai ir, tā kā kad tiem nebūtu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Un tie, kas raud, lai ir kā kas neraud; un kas priecājās, kā kas nepriecājās, un kas pērk, kā kas to nepatur:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'Un kas šo pasauli lieto, kā kas to nelieto; jo šīs pasaules būšana paiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Bet es gribu, ka jūs esat bez zūdīšanās. Kas nelaulāts, tas rūpējās par Tā Kunga lietām, kā tas Tam Kungam var patikt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Bet kas laulāts, tas rūpējās par pasaules lietām, kā tas sievai var patikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Tāda pat starpība ir starp sievu un meitu: tā nelaulātā rūpējās par Tā Kunga lietām, ka tā svēta būtu miesā un garā; bet tā laulātā rūpējās par pasaules lietām, kā tā vīram var patikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Un to es saku jums pašiem par labu: ne, ka gribētu jums apmest valgu, bet ka jūs godīgi dzīvojiet un pie Tā Kunga turaties bez mitēšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Bet ja kam šķiet, ka viņa meitai, kas pāri par gadiem, tas nepieklājoties, un ja tam tā vajag notikt, tad lai dara, ko gribēdams; viņš negrēko: lai tā laulībā iedodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Bet kas ir pastāvīgs savā sirdī, un kam vajadzības nav, bet ir vaļa, pēc sava paša prāta darīt, un to savā sirdī ir apņēmies, savu meitu paturēt nelaulātu, - tas dara labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Tad nu, kas laulībā izdod, tas dara labi, un kas laulībā neizdod, tas dara labāki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Sieva caur bauslību ir sieta, kamēr viņas vīrs dzīvs; bet kad viņas vīrs ir miris, tad tai ir vaļa precēt kuru grib, tikai iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Bet viņa ir jo svētīga, ja viņa tāpat paliek, pēc mana padoma; bet man šķiet, ka man arīdzan ir Dieva Gars.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Bet par elkadievu upuriem zinām, ka mums visiem ir atzīšana. Atzīšana uzpūš, bet mīlestība uztaisa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Bet ja kam šķiet, ka ko zinot, tas vēl nezin nenieka tā, kā piederās zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Bet ja kas Dievu mīl, tas no Viņa ir atzīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Tad nu par elku upuru ēšanu zinām, ka neviena elka nav pasaulē un ka cita Dieva nav kā vien Tas Vienīgais,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Un jebšu ir tā saucami dievi, tā debesīs, kā virs zemes - tā kā ir daudz dievu un daudz kungu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Tomēr mums ir viens Dievs, Tas Tēvs, no kā visas lietas, un mēs uz Viņu, un viens Kungs Jēzus Kristus, caur ko visas lietas, un mēs caur Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Tomēr tā atzīšana nav iekš visiem; bet kādi, kas līdz šim apzinās, elkus esam, ēd tā kā no elku upuriem, un viņu zināma sirds, vāja būdama, top apgānīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Bet barība nedara mūs Dievam pieņēmīgus; jo ēzdami mēs neesam labāki, un neēzdami mēs neesam sliktāki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Bet pielūkojiet, ka šī jūsu vaļa vājiem nekļūst par piedauzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Jo, ja kas redzētu tevi, kam tā atzīšana, elka namā pie galda sēžam, vai tā vājā brāļa zināma sirds netaps skubināta, elku upurus ēst?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Un caur tavu atzīšanu pazudīs tavs vājais brālis, kā labad Kristus ir miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Bet pret brāļiem tā grēkodami un viņu vājo zināmu sirdi ievainodami, jūs grēkojat pret Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Tādēļ, ja manam brālim barība par piedauzīšanu, tad es nemūžam gaļu neēdīšu, lai savu brāli neapgrēcināju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Vai es neesmu svabads? Vai es neesmu apustulis? Vai es Kristu, mūsu Kungu, neesmu redzējis? Vai jūs neesat mans darbs iekš Tā Kunga?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Ja es citiem neesmu apustulis, tomēr jums es esmu; jo mana apustuļa amata zieģelis jūs esat iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Mana atbildēšana tiem, kas mani tiesā, ir šī:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Vai mums nav brīv, ēst un dzert?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Vai mums nav brīv kādu māsu vest līdz par sievu, tā kā arī tie citi apustuļi un Tā Kunga brāļi un Kefas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Jeb vai man un Barnabam vien nav brīv, nestrādāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kas jel iet karā ar savu maizi? Kas vīna kalnu dēsta un neēd no viņa augļiem? Jeb kas lopus gana un neēd no tā piena?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Vai es to runāju pēc cilvēku prāta? Jeb vai to nesaka arī pati bauslība?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Jo Mozus bauslībā ir rakstīts: Tev nebūs vērsim, kas labību min, purnu apsiet: vai tad Dievam rūp par vēršiem?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Jeb vai viņš to visu nesaka mūsu labad? Jo mūsu labad ir rakstīts, ka arājam vajag art uz cerību un kūlējam kult uz cerību, ka viņam būs sava daļa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Ja mēs jums to garīgo mantu esam sējuši, vai tad tā liela lieta, ja jūsu miesīgo pļaujam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Ja tad citiem tāda vaļa ir par jums, kāpēc ne jo vairāk mums? Bet mēs šo vaļu neesam lietojuši, bet visu panesam, lai Kristus evaņģēliju neaizkavējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Vai nezināt, ka tie, kas pie svētuma kalpo, no tā svētuma ēd? Un ka tiem, kam darbs ir pie altāra, daļa ir no tā altāra?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tāpat arī Tas Kungs ir iestādījis, ka tie, kas evaņģēliju sludina, no evaņģēlija pārtiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Bet no tā es nekā neesmu lietojis. Un es to neesmu rakstījis, lai pie manis tā notiek; jo man būtu labāki mirt, nekā ja kāds manu slavu nīcinātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Jo kad es evaņģēliju sludināju, tad man nav ko lielīties; jo tas man jādara; un vai man, ja es evaņģēliju nesludināju!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Jo ja es to labprāt daru, tad man ir alga; ja ne labprāt, tad tomēr nama turēšana man ir uzticēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Kāda alga tad nu man ir? Ka evaņģēliju sludinādams Kristus evaņģēliju mācu bez maksas, lai neizlietoju savu vaļu pie evaņģēlija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Jo no visiem svabads būdams es sevi pašu esmu darījis visiem par kalpu, ka jo vairāk dvēseļu mantotu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Un Jūdiem es esmu tapis par Jūdu, ka Jūdus mantotu; tiem, kas apakš bauslības es esmu tapis kā apakš bauslības, (pats nebūdams apakš bauslības,) ka mantotu tos, kas apakš bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Tiem, kas bez bauslības, esmu tapis tā kā bez bauslības, (pats nebūdams bez bauslības Dieva priekšā, bet stāvēdams iekš bauslības caur Kristu), ka es tos mantotu, kas bez bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Vājiem es esmu tapis tā kā vājš, ka mantotu vājos; visiem esmu palicis viss, ka visādi kādus glābtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Un to es daru evaņģēlija dēļ, ka man arī kāda daļa pie tā būtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Vai nezināt, ka tie, kas iet skrieties, gan visi skrien, bet viens dabū to goda maksu? Skrieniet tā, ka jūs to dabūjiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Bet ikviens, kas cīkstas, savaldās visās lietās, - viņi tāpēc, ka dabūtu iznīcīgu kroni, bet mēs neiznīcīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Es tad skrienu, ne tā kā uz ko nezināmu, - es cīnos, ne tā kā gaisu sizdams;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Bet es savu miesu mērdēju un viņu kalpināju, lai citiem sludinādams pats nekļūstu atmetams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Bet es gribu, brāļi, lai jūs liekat vērā, ka mūsu tēvi visi bijuši apakš tā padebeša, un visi gājuši caur to jūru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'Un visi uz Mozu ir kristīti padebesī un jūrā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'Un visi baudījuši to pašu garīgo barību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Un visi dzēruši to pašu garīgo dzērienu; jo tie dzēra no tā garīgā akmens, kas gāja līdz; bet tas akmens bija Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Bet pie tā lielā pulka no tiem Dievam nebija labs prāts; jo tie ir nobeigti tuksnesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Un tas noticis mums par priekšzīmi, ka mēs nebūtu ļauna iekārotāji tā kā tie iekārojušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Un arī netopat elku kalpi, kā citi no tiem, - kā ir rakstīts: tie ļaudis apsēdās ēst un dzert un cēlās līksmoties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Lai arī maucībai nedodamies, tā kā citi no tiem ir maukojuši un krituši vienā dienā divdesmit un trīs tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Lai arī Kristu nekārdinājiet, tā kā arī citi no tiem viņu kārdinājuši un ir nomaitāti caur čūskām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Un arī nekurniet, tā kā citi no tiem kurnējuši un ir nomaitāti caur to maitātāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Un viss tas viņiem noticis kā priekšzīme, un ir uzrakstīts par mācību mums, uz kuriem pasaules gals ir nācis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Tāpēc, kas šķietās stāvot, tas lai pielūko, ka nekrīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Jums vēl nekāda kārdināšana nav uzgājusi kā tikai cilvēcīga; bet Dievs ir uzticīgs; tas neļaus jūs vairāk kārdināt nekā spējat, bet kārdināšanai arī tādu galu darīs, ka varat panest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Tādēļ, mani mīļie, bēgat no elku kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Kā uz prātīgiem es saku; apspriežat paši, ko es saku:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Tas pateicības biķeris, ko ar pateikšanu svētījam, vai tas nav savienošana ar Kristus asinīm? Tā maize, ko laužam, vai tā nav savienošana ar Kristus miesu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Jo kā viena maize, tā mēs daudzi esam viena miesa; jo mums visiem ir daļa pie vienas maizes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Uzskatat to Israēli pēc miesas: Vai tiem, kas upurus ēd, nav biedrība ar altāri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Ko tad nu es saku? Vai, ka elkadievs kas esot? Jeb ka elka upuris kas esot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Bet ko pagāni upurē, to tie upurē velniem un ne Dievam; bet es negribu, ka jums biedrība būtu ar velniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Jūs nevarat dzert Tā Kunga biķeri un velnu biķeri. Jums nevar daļa būt pie Tā Kunga galda un pie velnu galda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Jeb vai gribam To Kungu kaitināt? Vai mēs esam jo spēcīgāki nekā Viņš?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Viss man ir brīv, bet ne viss der. Viss man ir brīv, bet ne viss der uztaisīšanai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Nevienam nebūs to meklēt, kas pašam, bet kas citam par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Visu, ko skārņos pārdod, ēdiet, neko neizmeklēdami zināmas sirds dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Jo Tam Kungam pieder zeme un viņas pilnums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Un ja kāds no tiem neticīgiem jūs aicina, un jūs gribat iet, tad ēdiet visu, ko jums ceļ priekšā, ne ko neizmeklēdami zināmas sirds dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Bet ja kas uz jums saka: šis ir elka upuris, tad neēdat, viņa dēļ, kas jums to ir teicis, un zināmas sirds dēļ; (jo Tam Kungam pieder zeme un viņas pilnums.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Bet es saku: ne tavas, bet tā tuvāka zināmas sirds dēļ. Jo kāpēc mana svabadība lai top tiesāta no cita zināmas sirds?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Ja es ar pateicību to saņemu, ko tad topu zaimots, par ko es pateicos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Tāpēc, vai ēdat vai dzerat un ko vien darāt, visu to darāt Dievam par godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Nepaliekat par piedauzīšanu ne Jūdiem ne Grieķiem ne Dieva draudzei,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Itin kā arī es visiem visās lietās esmu pa prātam, nemeklēdams, kas man, bet kas daudziem par labu, lai tie top izglābti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Dzenaties man pakaļ, tā kā es Kristum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Un es jūs slavēju, brāļi, ka jūs visās lietās mani pieminat un turat tās mācības, kā jums tās esmu mācījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Bet es gribu, ka jūs zināt, ka ikkatra vīra galva ir Kristus, bet sievas galva ir vīrs, bet Kristus galva ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Ikviens vīrs, kas Dievu lūgdams vai mācīdams apsegu tur uz galvas, apkauno savu galvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Bet ikviena sieva ar neapsegtu galvu Dievu lūgdama vai mācīdama, apkauno savu galvu. Jo tas tikpat, tā kā tā būtu apcirpta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Jo ja sieva neapsedzās, tad lai tā arī top apcirpta. Bet kad nu tas sievai par kaunu, ka tā ir apcirpta jeb plikgalve, tad lai tā apsedzās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Bet vīram nebūs galvu apsegt, jo viņš ir Dieva ģīmis un gods; bet sieva ir vīra gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Jo vīrs nav no sievas, bet sieva no vīra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Un vīrs arī nav radīts sievas dēļ, bet sieva vīra dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Tāpēc sievai būs valdnieka zīmi galvā turēt eņģeļu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Tomēr nedz vīrs ir bez sievas, nedz sieva bez vīra iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Jo tā kā sieva ir no vīra, tāpat arī vīrs ir caur sievu; bet viss tas ir no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Spriežat paši, vai pieklājās, ka sieva Dievu lūdz neapsegta?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Jeb vai pati daba jums nemāca, ka tas vīram par negodu, kad tam gari mati,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Bet ja sievai gari mati: tad tas viņai par godu; jo mati viņai doti par apsegu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Bet ja kāds grib par to tiepties: mums tāda ieraduma nav, nedz Dieva draudzēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Es jūs pamācu un to nevaru uzteikt, ka jūs sanākat ne par svētību, bet par nesvētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Jo pirmā kārtā, kad jūs sanākat draudzē, es dzirdu, ka šķelšanās ir jūsu starpā, un pa daļai to gan ticu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Jo šķelšanām gan vajag būt jūsu starpā, lai tie pastāvīgie jūsu starpā top zināmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Kad nu jūs sanākat kopā, tad tā nenotiek, kā pieklājās baudīt Tā Kunga mielastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Jo pie mielasta ikviens steidzās paņemt savu paša ēdienu un cits paliek neēdis un cits ir pilns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Jo vai tad jums nav māju, kur varat ēst un dzert? Jeb vai jūs Dieva draudzi nicinājiet un tos apkaunojiet, kam nav nekā? Ko lai jums saku? Vai lai jūs teicu? Šinī lietā es jūs neteicu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Jo no Tā Kunga es to esmu dabūjis, ko atkal jums esmu mācījis, ka Tas Kungs Jēzus tanī naktī, kad Tas kļuva nodots, to maizi ņēma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'Un pateicies pārlauza un sacīja: ņemiet, ēdiet, tā ir Mana miesa, kas par jums top lauzta; to dariet Mani pieminēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Tāpat arī to biķeri, pēc tā vakarēdiena, sacīdams: Šis biķeris ir tā jaunā derība iekš Manām asinīm. To dariet, cikkārt jūs to dzeriet, Mani pieminēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Jo cikkārt jūs no šīs maizes ēdat un no šī biķera dzerat, tad pasludinājiet Tā Kunga nāvi, tiekams Tas nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Tad nu, kas necienīgi ēd šo maizi, vai dzer Tā Kunga biķeri, tas būs noziedzīgs pie Tā Kunga miesas un asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Bet lai cilvēks pats izmeklējās, un tā lai viņš ēd no šīs maizes un dzer no šī biķera.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Jo kas necienīgi ēd un dzer, tas ēd un dzer sev pašam sodu, neizšķirdams Tā Kunga miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Tādēļ jūsu starpā daudz ir vāji un neveseli, un daudz ir aizmiguši (garīgi, iekš draudzes).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Jo ja mēs paši sevi tiesātu, tad netaptu tiesāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Bet kad mēs topam tiesāti, tad no Tā Kunga topam pārmācīti, lai ar pasauli netopam pazudināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Tad nu, mani brāļi, kad jūs sanākat pie mielasta, tad gaidiet cits uz citu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Bet ja kas ir izsalcis, tas lai ēd mājās, lai jūs nesanākat par sodu. To citu es mācīšu, kad es nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Bet par tām garīgām dāvanām, brāļi, es negribu jums slēpt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Jūs zināt, ka bijāt pagāni, noklīduši pie mēmiem elkadieviem, ka tapāt vadīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Tāpēc jums daru zināmu, ka neviens, kas caur Dieva Garu runā, Jēzu nenolād un neviens nevar Jēzu saukt par Kungu kā vien caur Svēto Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Bet ir dažādas dāvanas, tomēr viens pats Gars;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Un ir dažādas kalpošanas, tomēr viens pats Kungs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Un ir dažādi spēki, bet tomēr viens pats Dievs, kas ir spēcīgs visās lietu lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Bet ikvienam tiek dots, lai to Garu parāda, tuvākam par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Jo caur to Garu citam top dots runāt no gudrības, citam runāt no atzīšanas - pēc tā paša Gara;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Un citam ticība iekš tā paša Gara, un citam dāvanas dziedināt iekš tā paša Gara;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Un citam spēki, brīnumus darīt, un citam Dieva vārda mācīšana, un citam garu pārbaudīšana, un citam dažādas valodas, un citam valodu iztulkošana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Bet visu to padara tas pats viens Gars un izdala ikvienam sevišķi tā, kā Tas grib.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Jo tā kā miesa ir viena un tai daudz locekļu, bet visi locekļi pie tās vienas miesas, daudzi būdami, ir viena miesa; tāpat arī Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Jo mēs arīdzan visi esam kristīti caur vienu Garu par vienu miesu, lai esam Jūdi vai Grieķi, lai kalpi vai svabadnieki; un visi mēs esam dzirdināti ar vienu Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Jo arī miesa nav viens loceklis, bet daudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Ja kāja sacītu: ka es neesmu roka, tāpēc neesmu no miesas; vai tāpēc viņa nav no miesas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Un ja auss sacītu: ka es neesmu acs, tāpēc neesmu no miesas; vai tāpēc viņa nav no miesas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Ja visa miesa būtu acs, kur paliktu dzirdēšana? Ja visa miesa būtu dzirdēšana, kur paliktu ošana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Bet tagad Dievs tos locekļus ir licis, ikvienu no tiem pie miesas, tā kā Viņš gribējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Bet ja tie visi būtu viens loceklis, kur paliktu miesa?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Bet tagad gan ir daudz locekļu, bet viena miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Un acs nevar sacīt uz roku: man tevis nevajag; jeb atkal galva uz kājām: man jūsu nevajag.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Bet daudz vairāk tie miesas locekļi, kas liekās būtu tie vājākie, ir tie jo vajadzīgie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Un kas mums liekās pie miesas būt jo negodīgi, tos jo vairāk godājam, un mūsu jo neglītie locekļi dabū jo lielu glītumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Bet mūsu glītiem locekļiem to nevajag; bet Dievs miesu ir salicis, tam maz godātam loceklim augstāku godu dodams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Lai šķelšanās nebūtu iekš miesas, bet lai tie locekļi cits par citu vienlīdzīgi gādātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Un kad viens loceklis cieš, tad visi locekļi cieš līdz, jeb kad viens loceklis top godāts, tad visi locekļi priecājās līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Bet jūs esat Kristus miesa un locekļi, ikviens pēc savas kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Un citus Dievs ir iecēlis draudzē pirmā kārtā par apustuļiem, otrā kārtā par praviešiem, trešā kārtā par mācītājiem, tad brīnumu darītājus, pēc tam, kam dāvanas dziedināt, palīgus, valdītājus, dažādas valodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Vai visi ir apustuļi? Vai visi ir pravieši? Vai visi ir mācītāji? Vai visi ir brīnumu darītāji?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Vai visiem ir dāvanas dziedināt? Vai visi runā valodām? Vai visi var tulkot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Bet dzenaties pēc tām vislabākām dāvanām, un es jums rādīšu vēl jo labāku ceļu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Ja es runātu ar cilvēku un eņģeļu mēlēm, un man nebūtu mīlestības, tad es būtu skanīgs varš jeb šķindošs zvārgulis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Un ja man būtu praviešu mācība, un ja es zinātu visus noslēpumus un visu atzīšanu, un ja man būtu visa ticība, tā ka es varētu kalnus pārcelt, un man nebūtu mīlestības, tad es neesmu nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Un ja es visu savu mantu dotu nabagiem, un ja es savu miesu nodotu, ka taptu sadedzināts, un man nebūtu mīlestības, tad tas man nepalīdzētu nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Mīlestība ir lēnprātīga, tā ir laipnīga, mīlestība neskauž, mīlestība nelielās, tā neuzpūšās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Tā neturas netikli, tā nemeklē savu labumu, tā neapskaistās, tā nedomā uz ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Tā nepriecājās par netaisnību, bet tā priecājās par patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Tā apklāj visu, tā tic visu, tā cerē visu, tā panes visu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Mīlestība nekad nebeidzās, jebšu gan praviešu mācības mitēsies, un jebšu valodas beigsies, un jebšu atzīšana mitēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Jo tas ir mazums, ko zinām, un tas ir mazums, ko mācam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Bet kad pilnība nāks, tad tas, kas ir mazums, zudīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Kad biju bērns, tad runāju kā bērns, man bija bērna prāts un bērna domas; bet kad paliku par vīru, tad atmetu bērna dabu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Jo tagad redzam kā caur spieģeli iekš mīklas, bet tad vaigu vaigā; tagad es atzīstu pa daļai, bet tad es atzīšu, itin kā es esmu atzīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Bet nu paliek ticība, cerība, mīlestība, šās trīs: bet tā lielākā no tām ir mīlestība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Dzenaties pēc mīlestības, rūpējaties par tām garīgām dāvanām, bet visvairāk, ka varat mācīt (praviešu garā).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Jo kas valodām runā, tas nerunā cilvēkiem, bet Dievam; jo neviens nedzird, bet garā viņš runā noslēpumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Bet kas māca, tas runā cilvēkiem par uztaisīšanu un paskubināšanu un iepriecināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kas valodām runā, tas uztaisa sevi pašu; bet kas māca, tas uztaisa draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Es gribētu, ka jūs visi valodām runātu, bet jo vairāk, ka jūs mācītu; jo kas māca, tas ir pārāks par to, kas valodām runā, proti ja šis netulko, kā lai draudze top uztaisīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Un nu, brāļi, kad es pie jums nāktu, valodām runādams, ko es jums līdzētu, ja es uz jums nerunātu, vai parādīšanu, vai atzīšanu, vai praviešu mācību, vai rakstu izstāstīšanu pasniegdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Tāpat ir ar tām nedzīvām lietām, kas skan, lai ir stabule, lai kokle; ja viņu skaņas nevar izšķirt, kā var noprast, kas ir stabulēts vai koklēts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Un atkal, ja bazūne neskan skaidri, kas taisīsies uz karu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tāpat arī jūs, ja valodām runājiet nesaprotamus vārdus, kā zinās, kas top runāts? Jo jūs runāsiet vējā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Daudz un dažādas balsis ir pasaulē, un neviena no tām nav nesaprotama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Tad nu, ja es balsi nesaprotu, būšu svešs tam, kas runā, un tas kas runā, būs man svešs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tāpat arī jūs, kad pēc tām garīgām dāvanām dzenaties, tad meklējat, ka jo pilnīgi paliekat draudzei par uztaisīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Tāpēc, kas valodām runā, tas lai Dievu lūdz, ka varētu tulkot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Jo kad es Dievu lūdzu valodām, tad mans gars gan lūdz, bet mans prāts augļus nenes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Kas tad nu ir? Es pielūgšu garā, bet es pielūgšu arī, ka var saprast; es dziedāšu garā, bet es dziedāšu arī, ka var saprast.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Citādi, ja tu Dievu slavēsi garā, kā gan tas, kas nesaprot, uz tavu pateikšanu var sacīt: Āmen? Jo viņš nezin, ko tu runā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Jo tu gan labi pateici Dievam, bet otrs netop uztaisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Es pateicos savam Dievam, ka es vairāk nekā jūs visi valodām runāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Bet iekš draudzes es labāki gribu runāt piecus vārdus saprotamus, lai pamācu arī citus, nekā desmit tūkstošus valodām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Brāļi, netopat bērni iekš saprašanas, bet topat nejēgas iekš ļaunuma, bet saprašanā topat pilnīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Bauslībā ir rakstīts: Caur ļaudīm, kam sveša valoda un ar svešām lūpām Es runāšu uz šiem ļaudīm un arī tā tie Man neklausīs, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Tad nu tās valodas ir par zīmi ne ticīgiem, bet neticīgiem, un praviešu mācība ne neticīgiem, bet ticīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Tad nu, kad visa draudze sanāktu kopā, un visi runātu valodām, un ienāktu, kas to nesaprot, vai neticīgi: vai tie nesacītu, ka jūs esat traki?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Bet ja visi mācītu, un kāds neticīgs vai, kas nesaprot, nāktu iekšā, tas taptu no visiem pārliecināts un no visiem tiesāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Un viņa apslēptās sirds domas tā taptu zināmas, un tā viņš uz savu vaigu mezdamies Dievu pielūgtu un pasludinātu, Dievu tiešām esam mūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Kā tad nu ir, brāļi? Kad jūs sanākat, kā kuram ir vai dziesma, vai mācība, vai valoda, vai parādīšana, vai tulkošana, lai viss notiek par uztaisīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Un ja valodām runā, tad, vai pa diviem, vai ja daudz trīs, un cits pēc cita, - un viens lai iztulko.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Bet ja tulka nav, tad lai tas klusu cieš draudzē un lai runā sev pašam un Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Bet pravieši lai runā divi vai trīs, un tie citi lai pārspriež.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Bet ja citam, kas tur sēž, kāda parādīšana notiek, tad lai tas pirmais paliek klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Jo jūs pa vienam visi varat mācīt, lai visi mācās un visi top iepriecināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Un praviešu gari praviešiem ir paklausīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Jo Dievs nav nekārtības, bet miera Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Tā kā visās svēto draudzēs, lai jūsu sievas draudzes sapulcēs nerunā; jo tām nepieklājās runāt, bet būt paklausīgām, tā kā arī bauslība saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Un ja tās grib ko mācīties, lai tās mājās vaicā saviem vīriem; jo sievām ir par kaunu, draudzes sapulcē runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Vai tad no jums Dieva vārds ir izgājis? Jeb vai pie jums vien tas ir nācis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Ja kam šķiet, ka esot pravietis jeb garīgs, tam būs atzīt, ka tas, ko jums rakstu, ir Tā Kunga bauslis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Bet ja kas neprot, tas lai neprot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Tad nu, brāļi, dzenaties, ka mācat praviešu garā un neliedzat valodām runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Lai viss notiek, kā piederas un pa kārtām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Bet es jums daru zināmu, brāļi, to evaņģēliju, ko jums esmu pasludinājis, ko jūs arī esat pieņēmuši, kurā jūs arī stāvat,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Caur ko jūs arī mūžīgi dzīvosiet, ja to paturat tādā prātā, kādā es jums to esmu pasludinājis; - ja tikai neesat velti ticējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Jo mācīdams visu papriekš esmu devis, ko es arī esmu dabūjis, ka Kristus par mūsu grēkiem ir nomiris pēc tiem rakstiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Un ka Tas ir aprakts, un ka Tas trešā dienā uzmodināts pēc tiem rakstiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'Un ka Tas ir redzēts no Kefasa, pēc no tiem divpadsmit.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Un pēc Tas ir redzēts no vairāk nekā piecsimt brāļiem vienā reizē, no kuriem vēl daudz dzīvi un citi arī aizmiguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Pēc Tas ir redzēts no Jēkaba, pēc no visiem apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Pēc visiem šiem Tas arī redzēts no manis, kā no kāda nelaikā dzimuša bērna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Jo es esmu tas vismazākais no tiem apustuļiem un neesmu cienīgs, ka mani sauc par apustuli, tāpēc ka es Dieva draudzi esmu vajājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Bet no Dieva žēlastības esmu, kas es esmu, un Viņa žēlastība pie manis nav bijusi veltīga, bet es esmu vairāk strādājis nekā tie visi, tomēr ne es, bet Dieva žēlastība, kas ir ar mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Tad nu lai būtu vai es, vai viņi, tā mēs sludinājam, un tā jūs esat ticējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Ja nu Kristus top sludināts, ka Tas no miroņiem ir uzmodināts, kā tad citi jūsu starpā saka, ka miroņu augšāmcelšanās neesot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Bet ja miroņu augšāmcelšanās nav, tad arī Kristus nav augšāmcēlies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Un ja Kristus nav augšāmcēlies, tad mūsu sludināšana ir veltīga, un jūsu ticība arīdzan veltīga;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Un mēs arī topam atrasti nepatiesīgi Dieva liecinieki; jo mēs esam liecinājuši pret Dievu, ka Viņš Kristu ir uzmodinājis, ko Viņš nav uzmodinājis, ja miroņi netop uzmodināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Jo ja miroņi netop uzmodināti, tad arī Kristus nav uzmodināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Un ja Kristus nav uzmodināts, tad jūsu ticība ir veltīga; tad jūs vēl esat iekš saviem grēkiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Tad arīdzan tie ir pazuduši, kas iekš Kristus aizmiguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Ja vien šinī dzīvībā cerējam uz Kristu, tad esam jo nožēlojami pār visiem cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Bet nu Kristus ir uzmodināts no miroņiem, Viņš tas pirmais ir tapis no tiem, kas ir aizmiguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Jo kad caur vienu cilvēku nāve, tad arī caur vienu cilvēku miroņu augšāmcelšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Jo tā kā iekš Ādama visi mirst, tāpat arī iekš Kristus visi taps dzīvi darīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Bet ikviens savā kārtā: tas pirmais ir Kristus, pēc tie, kas Kristum pieder pie Viņa atnākšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Pēc tam tas gals, kad Viņš nodos to valstību Dievam Tam Tēvam, kad Viņš iznīcinās visu valdību un visu varu un spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Jo Viņam pienākas valdīt, tiekams Viņš visus ienaidniekus būs licis Sev apakš kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Tas pēdīgais ienaidnieks, kas taps izdeldēts, ir nāve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Jo Tas Viņam visu ir licis apakš kājām, tomēr kad saka, ka viss Viņam padots, tad protams, ka bez Tā, kas Viņam visu padevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Bet kad Viņam viss būs padots, tad arī pats Tas Dēls taps padots Tam, kas Viņam visu ir padevis, lai Dievs ir viss iekš visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Jo ko tie darīs, kas par miroņiem top kristīti, ja miroņi nemaz netop uzmodināti? Kādēļ tad tie par miroņiem top kristīti?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Kādēļ arī mēs ikstundas esam briesmās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Es mirstu ikdienas, - tik tiešām, ka jūs, brāļi, esat mans gods iekš Kristus Jēzus, mūsu Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Ja es pēc cilvēku prāta Efesū esmu kāvies ar zvēriem, kas man no tā atlec, ja miroņi netop uzmodināti? Ēdīsim un dzersim, jo rītu mēs mirsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Nepieviļaties! Ļaunas sabiedrības samaitā labus tikumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Uzmostaties it no tiesas un negrēkojiet; jo citiem nav Dieva atzīšanas, to es saku jums par kaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Bet ja kāds saka: kā tad miroņi top uzmodināti? Un kādā miesā tie nāk?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Tu nesapraša, ko tu sēji, tas nepaliek atkal dzīvs, ja tas nemirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Un ko tu sēji, nav tā miesa, kas celsies, bet tikai grauds, vai nu kviešu, vai cits kāds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Bet Dievs tam dod tādu miesu, kādu Viņš grib, un ikkatrai sēklai savu īpašu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ne ikkatra miesa ir vienāda miesa; bet savāda ir cilvēku miesa un savāda lopu un savāda zivju un savāda putnu miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Un ir gan debesu lietas un ir gan zemes lietas; bet savāda godība ir debesu lietām un savāda zemes lietām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Cits spožums ir saulei, un cits spožums mēnesim, un cits spožums zvaigznēm; jo viena zvaigzne ir spožāka pār otru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Tāpat arī būs miroņu augšāmcelšanās. Sēts top iekš satrūdēšanas un top uzmodināts iekš nesatrūdēšanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Sēts top iekš negodības un top uzmodināts iekš godības; sēts top iekš vājības un top uzmodināts iekš spēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Sēta top dabīga miesa, uzmodināta garīga miesa. Jo kā ir dabīga miesa, ir arī garīga miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Tāpat arīdzan ir rakstīts: tas pirmais cilvēks, Ādams, ir palicis par dzīvu dvēseli, tas pēdīgais Ādams par garu, kas dzīvu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Bet tā garīgā miesa nav tā pirmā, bet tā dabīgā, pēc tam tā garīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Tas pirmais cilvēks ir no zemes, no pīšļiem, tas otrais cilvēks ir Tas Kungs no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Kāds tas, kas no pīšļiem, tādi pat arīdzan tie no pīšļiem, un kāds Tas debešķīgais, tādi pat arī tie debešķīgie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Un tā kā esam nesuši tā ģīmi, kas no pīšļiem, tā arī nesīsim Tā ģīmi, kas no debesīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Bet to es saku, brāļi, ka miesa un asinis Dieva valstību nevar iemantot, nedz iznīcība iemantos neiznīcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Redzi, es jums saku noslēpumu: mēs gan visi neaizmigsim, bet visi tapsim pārvērsti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'It piepeši, acumirklī, pie pēdīgās bazūnes skaņas. Jo tā bazūne skanēs un miroņi taps uzmodināti nesatrūdami un mēs tapsim pārvērsti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Jo šim, kas ir satrūdams, būs apvilkt nesatrūdēšanu, un šim mirstamam būs apvilkt nemirstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Un kad tas, kas iznīcīgs, apvilks neiznīcību, un tas, kas mirstams, apvilks nemirstību, tad tas vārds notiks, kas ir rakstīts: nāve ir aprīta uzvarēšanā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Nāve, kur ir tavs dzelonis? Elle, kur ir tava uzvarēšana?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Bet nāves dzelonis ir grēks, un grēka spēks ir bauslība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Bet pateicība Dievam, kas mums to uzvarēšanu devis caur mūsu Kungu Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Tad nu, mani mīļie brāļi, esiet pastāvīgi, nešaubīgi, pilnīgi iekš Tā Kunga darba vienmēr, zinādami, ka jūsu darbs nav veltīgs iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Bet par tām sametamām dāvanām priekš tiem svētiem, kā es to esmu iecēlis Galatijas draudzēs, tāpat dariet jūs arīdzan.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Ikkatrā pirmā nedēļas dienā lai ikviens no jums pie sevis paša ko laba noliek un sakrāj, cik viņš paspēj, lai tās dāvanas nav jāsalasa tad tik, kad es nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Un kad es nonākšu, tad tos, ko būsiet ieskatījuši par derīgiem, ar grāmatām sūtīšu, jūsu dāvanas nonest uz Jeruzālemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Bet ja arīdzan būtu vērts, ka arī es tur noeju, tad tie man var nākt līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Bet pie jums es nākšu, kad Maķedoniju būšu izstaigājis, jo es gribu iet caur Maķedoniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Un var būt, ka es pie jums kādu brīdi palikšu, vai arī mitīšu par ziemu, ka jūs mani pavadiet, kurp es noiešu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Jo tagad es jūs negribu redzēt tikai garām iedams, bet ceru kādu laiku pie jums palikt, ja Tas Kungs to vēlēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Bet Efesū es palikšu līdz vasaras svētkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Jo man lielas un plašas durvis ir atvērtas, un pretinieku ir daudz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Un kad Timotejs nāk, tad pielūkojiet, ka tas pie jums ir bez bailēm; jo viņš strādā Tā Kunga darbu, tāpat kā es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Tāpēc lai neviens viņu nenicina; bet pavadiet viņu ar mieru, lai tas nāk pie manis, jo es viņu gaidu ar tiem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Bet brāli Apollu es dažkārt esmu skubinājis, lai ar tiem brāļiem pie jums noiet, bet viņam prāts pavisam nebija tagad iet, bet tomēr tas ies, kad tam būs izdevīgs laiks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Esiet modrīgi, stāviet ticībā, turaties kā vīri, esiet stipri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Viss pie jums lai notiek iekš mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Un es jūs lūdzu, brāļi: jūs zināt Stefana namu, ka tie ir tie pirmie no Akajas, un ka tie ir nodevušies tiem svētiem uz kalpošanu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Ka arī jūs tiem tādiem paklausiet un ikkatram, kas līdzi strādā un pūlējās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Bet es priecājos par Stefana un Fortunata un Akaīka atnākšanu, jo kad jūs pie manis neesat, tad šie ir pie manis jūsu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Jo tie atspirdzinājuši manu un jūsu garu; tāpēc atzīstiet tos par tādiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Āzijas draudzes jūs sveicina: Aķila un Prisķila ar to draudzi, kas viņu namā, jūs daudz sveicina iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Visi brāļi jūs sveicina. Sveicināties savā starpā ar svētu skūpstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Es Pāvils, jūs sveicināju, es ar savu pašu roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Ja kas nemīl To Kungu Jēzu Kristu, tas lai ir nolādēts; Maran ata (Tas Kungs nāk)!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Tā Kunga Jēzus Kristus žēlastība lai ir ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Mana mīlestība ir ar jums visiem iekš Jēzus Kristus. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Pāvils, caur Dieva prātu Jēzus Kristus apustulis, un Timotejs tas brālis, Dieva draudzei, kas ir Korintū, un visiem svētiem pa visu Akaju:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Slavēts lai ir Dievs un mūsu Kunga Jēzus Kristus Tēvs, Tas apžēlošanas Tēvs un visas iepriecināšanas Dievs, kas mūs iepriecina visās mūsu bēdās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Ka mēs tos, kas ir visādās bēdās, varam iepriecināt ar to iepriecināšanu, ar ko mēs paši no Dieva topam iepriecināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Jo, ka Kristus ciešanas pie mums vairojās, tāpat arī mūsu iepriecināšana caur Kristu vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Bet kad mēs topam apbēdināti, taču tas jums ir par iepriecināšanu un pestīšanu, kas spēcīga rādās to pašu bēdu paciešanā, ko arī mēs ciešam. Vai, kad mēs topam iepriecināti, tad tas jums ir par iepriecināšanu un pestīšanu. Un mūsu cerība par jums ir stipra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'To zinām, ka itin kā jums ir daļa pie ciešanas, tāpat arī pie iepriecināšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Jo negribam jums slēpt, brāļi, savas bēdas, kas mums notikušas Āzijā, ka mēs pārlieku bijām apgrūtināti, vairāk nekā mēs spējām, tā ka jau vairs necerējām dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Bet mēs paši pie sevis nopratām, ka mums bija jāmirst, lai nepaļaujamies uz sevi pašiem, bet uz Dievu, kas miroņus uzmodina;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Tas mūs no tādas nāves ir izrāvis un izrauj; uz Viņu ceram, ka Tas mūs arī vēl izraus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Arī caur jūsu piepalīdzību ar lūgšanām par mums, lai par to mums notikušo žēlastību arī notiek no daudz ļaudīm daudz pateikšanas par mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Jo šī ir mūsu slava, mūsu zināmas sirds liecība, ka mēs iekš vientiesības un Dieva skaidrības, ne iekš miesīgas gudrības, bet iekš Dieva žēlastības esam turējušies pasaulē un visvairāk pret jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Jo mēs cita nekā jums nerakstām, kā vien, ko jūs lasāt, jeb arī saprotat; un es ceru, ka jūs arī pavisam sapratīsiet:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Tā kā jūs kaut cik mūs jau esat sapratuši, ka mēs esam jūsu gods, itin kā arī jūs esat mūsu gods Tā Kunga Jēzus dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Un tādā uzticībā es jau papriekš gribēju pie jums nākt, ka jūs atkal dabūtu kādu žēlastību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Un caur jums iet uz Maķedoniju un atkal no Maķedonijas nākt pie jums, un no jums pavadīts tapt uz Jūdu zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Vai tad nu to apņemdamies neapdomīgi esmu darījis? Jeb vai pēc miesas prāta to apņemos, ko apņemos, ka pie manis būtu „jā jā“arī „nē nē“?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Bet Dievs ir uzticīgs, ka mūsu vārdi uz jums nav bijuši jā un nē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Jo Dieva Dēls, Jēzus Kristus, kas jūsu starpā caur mums ir sludināts, caur mani un Silvanu un Timoteju, nebija jā un nē, bet jā ir bijis iekš Viņa;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Jo cik ir Dieva apsolīšanu, tās ir iekš Viņa jā un iekš Viņa Āmen, Dievam par godu caur mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Bet Tas, kas mūs un jūs stiprina iekš Kristus, un kas mūs ir svaidījis, Tas ir Dievs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Tas mūs arī ir apzieģelējis un devis Tā Gara ķīlu mūsu sirdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Bet es Dievu piesaucu par liecinieku savai dvēselei, ka es tādēļ vien vēl neesmu nācis uz Korintu, ka es jūs saudzētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Ne tā kā mēs valdām par jūsu ticību, bet mēs esam jūsu prieka palīgi; jo jūs stāvat ticībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Bet es pie sevis esmu apņēmies nenākt atkal pie jums ar skumdināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Jo ja es jūs noskumdināju, kas tad ir, kas mani iepriecina, ja ne tas, kas no manis bija noskumdināts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Un to jums esmu rakstījis, lai man nākot nebūtu jānoskumst par tiem, par kuriem man bija priecāties, un es stipri ceru no jums visiem, ka mans prieks arī jums visiem prieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Jo iekš daudz bēdām un sirds bailēm ar daudz asarām jums esmu rakstījis; ne, lai jūs noskumstat, bet lai nomaniet to ļoti lielo mīlestību, ko es uz jums turu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Bet ja kas skumdinājis, tad tas nav mani skumdinājis, bet lai pāri nedaru, kaut cik jūs visus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Šim tādam jau pietiek šī pārmācīšana, kas tam no daudziem ir notikusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tā, ka jums turpretī jo vairāk pienākas piedot un iepriecināt, ka tas nenonīkst no pārlieku lielas noskumšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Tāpēc jums lūdzu, ka jūs gribētu viņam parādīt mīlestību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Jo tāpēc arī esmu rakstījis, lai es nomanītu jūsu prātu, vai jūs visās lietās esat paklausīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Kam jūs piedodat, tam es arīdzan piedodu; jo ja es arī kādam ko esmu piedevis, tad tam jūsu dēļ esmu piedevis priekš Kristus vaiga, lai no sātana netopam pievilti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Jo viņa domas mums nav nezināmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Bet kad es nācu Troadā Kristus evaņģēliju sludināt, un durvis man bija atvērtas iekš Tā Kunga, tad savā garā nevarēju apmierināties, tāpēc ka neatradu Titu, savu brāli,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Bet no tiem atvadījies aizgāju uz Maķedoniju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Un pateicība Dievam, kas mums allaž dod uzvarēt iekš Kristus un Savas atzīšanas labo smaržu caur mums izlaiž visās malās!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Jo mēs esam Kristus saldā smarža Dievam pie tiem, kas top izglābti, un pie tiem, kas pazūd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Šiem gan nāves smarža uz nāvi, bet viņiem dzīvības smarža uz dzīvību. Un kas ir derīgs uz to?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Jo mēs neesam kā daudzi, kas ar Dieva vārdu kā ar preci pieviļ, bet mēs runājam itin kā no skaidrības, kā no Dieva puses Dieva priekšā iekš Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Vai tad mēs atkal iesākam paši sevi ieteikt? Jeb vai mums arīdzan tā kā citiem vajag ieteikšanas grāmatas uz jums, vai teikšanas grāmatas no jums?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Jūs esat mūsu grāmata, rakstīta mūsu sirdīs, zināma un lasāma visiem cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Jo jūs esat zināmi, ka esat Kristus grāmata, sataisīta caur mūsu amatu, rakstīta ne ar tinti, bet ar tā dzīvā Dieva Garu, ne uz akmeņu galdiem, bet uz sirds miesīgiem galdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Un tāda uzticība mums ir caur Kristu uz Dievu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Ne ka mēs no sevis pašiem esam derīgi, ko laba domāt tā kā no sevis pašiem; bet ka esam derīgi, tas ir no Dieva;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Tas mūs arī ir darījis derīgus, kalpot jaunai derībai, ne raksta zīmei, bet Garam; jo raksta zīme nokauj, bet Gars dara dzīvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Un ja tam nāves amatam, kas iezīmēts raksta zīmēs un akmeņos, bijis spožums, tā ka Israēla bērni nevarēja uzskatīt Mozus vaigu viņa vaiga spožuma dēļ kam bija jāzūd:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Kā lai nebūtu jo vairāk spožuma tam Gara amatam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Jo ja tam pazudināšanas amatam bijis spožums, tad jo vairāk spožuma ir tam taisnošanas amatam pārpārim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Šo uzlūkojot ir tā kā bez spožuma tas, kam spožums bijis, tā jo pārlieku lielā spožuma dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Jo ja tam, kam bija zust, bijis spožums, tad jo vairāk spožuma ir tam, kas pastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Tāpēc ka mums ir tāda cerība, tad runājam ar lielu drošību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Un ne tā, kā Mozus, kas apsegu lika uz savu vaigu, lai Israēla bērni nemanītu, uz ko zīmējās tas (spožums,) kam bija zust.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Bet viņu sirdis ir apcietinātas; jo līdz šai dienai viņiem veco derību lasot tas pats apsegs paliek un netop atsegts, jo tas zūd caur Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Bet līdz šai dienai, kad Mozus top lasīts, apsegs karājās priekš viņu sirdīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Tomēr kad viņi atgriežas pie Tā Kunga, tad tas apsegs top noņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Bet Tas Kungs ir Tas Gars. Kur nu Tā Kunga Gars, tur ir svabadība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Bet nu mēs visi atsegtā vaigā skatīdami Tā Kunga spožumu kā spieģelī, topam pārvērsti tai pašā ģīmī no spožuma uz spožumu, tā kā no Tā Kunga Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Tādēļ, ka mums šis amats ir pēc tās mums dotās žēlastības, mēs nepiekūstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Bet mēs atsakām slepenai bezkaunībai, nestaigādami iekš viltības, nedz Dieva vārdu pārgrozīdami, bet ar patiesības parādīšanu darīdami sev pašus pieņēmīgus ikkatra cilvēka zināmai sirdij Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Bet ja mūsu evaņģēlijs ir apsegts, tad tas ir apsegts iekš tiem, kas pazūd;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Iekš tiem šās pasaules dievs ir apstulbojis neticīgās sirdis, lai tiem nespīd tā godības pilna evaņģēlija spožums no Kristus, kas ir Dieva ģīmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Jo mēs nesludinām paši sevi, bet Kristu Jēzu, To Kungu; bet sevi, ka esam jūsu kalpi Jēzus dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Jo Dievs, kas sacījis, lai gaisma aust no tumsības, tas ir atspīdējis mūsu sirdīs, apgaismošanu dot, ka atzīstam Dieva godību iekš Jēzus Kristus vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Bet mēs šo mantu turam mālu traukos, lai tas lielu lielais spēks būtu no Dieva, un ne no mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Mēs visur topam spaidīti, bet tomēr nenospaidīti; mēs esam neziņā, bet tomēr neesam izmisuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Mēs topam vajāti, tomēr neesam atstāti; mēs topam pie zemes mesti, tomēr neejam bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Mēs arvien Tā Kunga Jēzus miršanu visur līdz nesam savās miesās, lai arī Jēzus dzīvība mūsu miesās parādās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Jo kamēr dzīvojam, allažiņ topam nodoti nāvē Jēzus dēļ, lai arī Jēzus dzīvība parādās mūsu mirstamās miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Tad nu nāve ir spēcīga iekš mums, bet dzīvība iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Bet kad mums ir tas pats ticības gars, tā kā stāv rakstīts: es esmu ticējis, tāpēc es esmu runājis; tad mēs ticam, tāpēc arī runājam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Zinādami, ka Tas, kas To Kungu Jēzu ir uzmodinājis, arī mūs caur Jēzu uzmodinās un līdz ar jums stādīs priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Jo viss tas notiek jūsu dēļ, ka žēlastība vairodamies pie daudziem vairotu pateikšanu Dievam par godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Tāpēc nepiekūstam, bet jebšu mūsu ārīgais cilvēks nīcin nīkst, tomēr tas iekšķīgais jo dienas jo vairāk atjaunojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Jo mūsu bēdas, kas ir īsas un vieglas, mums padara neizsakot lielu, mūžīgu un pastāvīgu godību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Mums, kas neņemam vērā to, kas redzams, bet to, kas nav redzams. Jo kas redzams, tas ir laicīgs; bet kas nav redzams, tas ir mūžīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Jo mēs zinām, kad mūsu laicīgais mājoklis, šī būda būs salauzta, tad mums ir ēka no Dieva, mājoklis ne rokām taisīts, kas ir mūžīgs debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Jo šinī būdā mēs nopūšamies un ilgojamies, ka taptu pārģērbti ar savu dzīvokli, kas ir no debesīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Proti, ja pavisam tiksim atrasti apģērbti, ne pliki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Jo šinī būdā būdami mēs arī nopūšamies un esam apgrūtināti; tādēļ ka negribam tapt noģērbti, bet pārģērbti, lai tas, kas mirstams, top aprīts no dzīvības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Bet kas mūs uz šo pašu sataisa, ir Dievs, kas mums arī devis Tā Gara ķīlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Tāpēc mēs arvienu turam drošu prātu un zinām: kamēr mājojam miesās, tikmēr esam svešumā un vēl ne pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Jo mēs staigājam ticība, ne skatīšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Bet mēs turam drošu prātu un gribam labāki būt ārā no miesām un būt pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Tāpēc arī, vai pie Tā Kunga mājās būdami, vai te vēl svešumā, dzenamies uz to, ka Viņam labi patīkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Jo mums visiem būs parādīties priekš Kristus soģa krēsla, lai ikviens dabū, ko miesās būdams darījis, vai labu, vai ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Tad nu zinādami, ka To Kungu būs bīties, mēs pārliecinājām cilvēkus, bet Dievam esam zināmi; bet es ceru, ka mēs arī esam zināmi jūsu zināmās sirdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Jo mēs jums atkal neuzteicamies paši, bet jums ko dodam par mums lielīties; lai jums kas ir pret tiem, kas lielās ar to, kas priekš acīm, un ne ar to, kas sirdī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Jo ja mēs par daudz teikuši, tad tas ir Dievam par godu; jeb ja mēreni, tad jums par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Jo Kristus mīlestība mūs spiež (atzīt),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Kad spriežam tā: ka, ja viens par visiem ir miris, tad visi miruši. Un Viņš tādēļ par visiem ir miris, lai tie, kas dzīvo, vairs nedzīvo sev pašiem, bet Tam, kas par viņiem miris un uzmodināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Tad nu uz priekšu mēs nepazīstam nevienu pēc miesas; un jebšu mēs Kristu arī esam pazinuši pēc miesas, tomēr tagad Viņu vairs nepazīstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Tad nu, ja kas ir iekš Kristus, tas ir jauns radījums. Kas bijis, ir pagājis, redzi, viss ir palicis jauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Bet viss tas ir no Dieva, kas mūs ir salīdzinājis ar Sevi pašu caur Jēzu Kristu un mums devis to salīdzināšanas amatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Jo Dievs bija iekš Kristus, salīdzinādams pasauli ar Sevi pašu, tiem viņu grēkus nepielīdzinādams, un mūsu starpā ir iecēlis to salīdzināšanas vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Tad nu no Kristus puses mēs esam sūtīti, tā kā Dievs caur mums lūgtu, mēs lūdzam no Kristus puses: ļaujaties salīdzināties ar Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Jo To, kas nekāda grēka nav zinājis, Viņš priekš mums ir darījis par grēku, ka mēs iekš Tā kļūtu Dieva taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Bet mēs arīdzan kā palīgi lūdzam, ka jūs Dieva žēlastību velti nedabūjat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Jo Viņš saka: “Pieņēmīgā laikā Es tevi esmu paklausījis un pestīšanas dienā tev par palīgu nācis.” Redzi, tagad ir tas labais pieņēmīgais laiks; redzi, tagad ir tā pestīšanas diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Mēs nevienā lietā nedodam nekādu apgrēcību, lai amats netop lamāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Bet ikkatrā lietā mēs sevi pašus darām pieņēmīgus, tā kā Dieva kalpi: iekš daudz paciešanām, iekš bēdām, iekš spaidīšanām, iekš bailībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Iekš sitieniem, iekš cietumiem, iekš trokšņiem, iekš darbiem, iekš nomodām, iekš gavēšanām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Iekš šķīstības, iekš atzīšanas, iekš lēnprātības, iekš laipnības, iekš Svētā Gara, iekš neviltotas mīlestības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Iekš patiesības vārda, iekš Dieva spēka, caur taisnības bruņām pa labo un kreiso pusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Caur godu un negodu, caur slavu un neslavu, kā viltnieki, un tomēr patiesīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Tā kā nepazīstami un tomēr pazīstami, tā kā mirdami, un redzi, mēs dzīvojam, tā kā pārmācīti un ne nonāvēti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Tā kā noskumuši, bet vienmēr priecīgi, tā kā nabagi, bet darīdami daudz bagātus, tā kā tādi, kam nav nenieka un kam tomēr ir visas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Mūsu mute ir atvērusies uz jums, ak Korintieši, mūsu sirds ir atdarījusies!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Neslēpjat mums savas bēdas! Bet jūs tās gan slēpjat savā sirds dziļumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Bet par atmaksu prasu no jums kā no saviem bērniem, lai jūsu sirds arīdzan atdarās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Nevelciet svešu jūgu ar neticīgiem, jo kāda daļa ir taisnībai ar netaisnību? Kāda biedrība ir gaismai ar tumsību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Kā saskan Kristus ar Belialu? Jeb kāda daļa ir ticīgam ar neticīgu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Un kāda līdzība ir Dieva namam ar elkadieviem? Jo jūs esat Tā dzīvā Dieva nams; tā kā Dievs sacījis: “Es iekš tiem gribu mājot un viņu starpā staigāt, un gribu būt viņu Dievs, un viņi būs Mani ļaudis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Tas Kungs saka: “Tāpēc izejiet no viņu vidus un atšķiraties un neaiztiekat neko, kas ir nešķīsts; tad Es jūs gribu pieņemt.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, '“Un Es būšu jums par Tēvu, un jūs būsiet Man par dēliem un meitām, to Tas Kungs saka, Tas Visuvaldītājs.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Kad nu mums ir tādas apsolīšanas, tad, mīļie, lai paši šķīstamies no visas apgānīšanas pie miesas un pie gara un lai topam pilnīgi svēti iekš Dieva bijāšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Klausiet mūs: mēs nevienam neesam pāri darījuši, nevienu postījuši, nevienu piekrāpuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Es to nesaku, jūs notiesādams. Jo es jau esmu sacījis: jūs esat mūsu sirdīs, ka kopā mirstam un kopā dzīvojam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Man ir liela drošība uz jums, man ir daudz ko slavēt par jums; es esmu ļoti iepriecināts, es esmu pārpārim prieka pilns visās mūsu bēdās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Jo kad mēs nonācām Maķedonijā, tad mūsu miesai nebija nekādas atvieglošanas, bet mēs bijām visai apbēdināti: no ārienes ķildas, no iekšienes bailes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Bet Dievs, kas pazemīgos iepriecina, mūs ir iepriecinājis caur Titus atnākšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Un nevien caur viņa atnākšanu, bet arī caur to iepriecināšanu, ar ko viņš par jums bija iepriecināts, ka tas mums teica jūsu ilgošanos, jūsu raudāšanu, jūsu sirds karstumu par mani, tā ka es jo vairāk priecājos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Jo jebšu es jūs esmu noskumdinājis caur to grāmatu, taču tas man nav žēl; kad man arī bija žēl, (jo es redzu, ka šī pati grāmata jūs ir noskumdinājusi, lai arī tikai uz mazu brīdi,)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Tad es tagad priecājos, ne par to, ka jūs tapāt noskumdināti, bet par to, ka jūs noskumdināti uz atgriešanos; jo jūs dievišķi tapāt skumdināti, lai jums nekas no mums nenāktu par ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Jo dievišķā noskumšana padara atgriešanos uz svētību, kas nevienam nav žēl, bet pasaules noskumšana padara nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Jo redzi, šī pati lieta, ka jūs dievišķi tapāt noskumdināti, kādu lielu čaklību tā pie jums ir padarījusi, kādu aizbildināšanos, kādu apskaišanos, kādu bijāšanos, kādu ilgošanos, kādu karstumu, kādu sodīšanu! Visnotaļ jūs esat parādījušies šķīsti šinī lietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Jebšu es jums esmu rakstījis, taču tas nav tā dēļ, kas netaisnību darījis, nedz tā dēļ, kam netaisnība darīta, bet tādēļ, lai jūsu čaklība par mums parādītos pie jums Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Tāpēc mēs esam iepriecināti; bet pie šīs mūsu iepriecināšanas vēl ļoti daudz vairāk esam priecājušies par Titus prieku, tāpēc ka viņa gars no jums visiem ir atspirdzināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Jo kad es kaut kā jūs esmu viņam slavējis, tad es neesmu palicis kaunā; bet tā kā es visas lietas jums esmu runājis ar patiesību, tāpat arīdzan mūsu slavēšana Titus priekšā bija patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Un viņa sirds prāts gauži uz jums stāv, kad tas piemin visu jūsu paklausību, kā jūs viņu esat uzņēmuši ar bijāšanu un drebēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Tad nu es priecājos, ka visās lietās jums varu uzticēties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Bet jums, brāļi, darām zināmu to Dieva žēlastību, kas parādījusies Maķedonijas draudzēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Jo lai gan bēdās daudz pārbaudīti, tomēr viņiem ļoti liels prieks bijis, un jebšu tie bija ļoti nabagi, taču tie bagāti devuši pēc savas sirds labprātības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Jo tie pēc sava spēka, to es apliecināju, un vēl pāri par savu spēku bijuši labprātīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Mūs lūgtin lūgdami, lai saņemam to dāvanu un piepalīdzību tiem svētiem par labu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Un tie ne vien deva, kā cerējām, bet viņi arī paši nodevās papriekš Tam Kungam un arī mums caur Dieva prātu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Tā ka Titu paskubinājām, lai viņš, kā bija iesācis, tāpat jūsu starpā arī pabeigtu šīs dāvanas saņemt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Bet tā, kā jūs visās lietās esat pieņēmušies, ticībā, mācībā un atzīšanā un visā čaklībā un savā mīlestībā uz mums, tā pieņematies arī šinī labdarīšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Es to nesaku pavēlēdams, bet caur to labprātību, ko citi parādījuši, pārbaudu arī jūsu mīlestību, vai tā ir īstena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Jo jūs zināt mūsu Kunga Jēzus Kristus žēlastību, ka Tas, bagāts būdams, jūsu dēļ ir tapis nabags, lai jūs caur Viņa nabadzību kļūtu bagāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Un šinī lietā dodu padomu, jo tas par labu jums, kas jau pērn esat iesākuši nevien to darīt, bet arī labu prātu rādīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Bet tagad pabeidziet to darbu, lai tas labais prāts, kas jums ir bijis, to gribēt, tāpat arī jums būtu, to pabeigt, cik spējiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Jo ja kam ir labs prāts, tas ir pieņēmīgs pēc tā, kas viņam ir, ne pēc tā, kas viņam nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Jo ne tā, lai citiem būtu atvieglošana un jums grūtums, bet izlīdzināšanas pēc, lai šinī laikā jūsu pilnība atvieglo viņu trūkumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Tā lai arī viņu pilnība atvieglo jūsu trūkumu, ka izlīdzināšana rodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Tā kā ir rakstīts: kas daudz bija sakrājis, tam neatlika; un kas maz bija sakrājis, tam nepietrūka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Bet pateicība Dievam, kas to pašu uzcītību par jums devis Titus sirdī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Ka viņš to paskubināšanu ir pieņēmis, un jo uzcītīgs būdams pats no sevis pie jums ir nogājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Un mēs viņam esam līdz sūtījuši to brāli, kam pa visām draudzēm laba slava ir pie evaņģēlija;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, '(Un ne vien tāpēc, bet arī ka tas no tām draudzēm mums ir iecelts par ceļabiedri pie šīs apdāvināšanas, ko mēs sagādājam, pašam Tam Kungam par godu un pēc sava labā prāta;)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'No tā sargādamies, ka neviens mums neceļ neslavu šī bagātā krājuma dēļ, ko esam sagādājuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Jo mēs dzenamies pēc tā, kas ir labs, ne vien Tā Kunga, bet arī cilvēku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Un tiem līdz esam sūtījuši savu brāli, ko mēs daudz lietās dažkārt esam pārbaudījuši, ka viņš ir uzcītīgs un tagad jo uzcītīgs, tās lielās uzticības dēļ, kas tam ir uz jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Kad jūs vaicājiet par Titu, viņš ir mans biedrs un palīgs pie jums; kad vaicājiet par tiem brāļiem, tie ir draudžu sūtītie un Kristus gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Tad parādiet tiem savu mīlestību, un ko no jums esam slavējuši, lai tās draudzes to redz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Jo par to palīdzību priekš tiem svētiem man jums vairs nav jāraksta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Jo es zinu jūsu labprātību, par ko jūs slavēju pie Maķedoniešiem, ka Akaja jau pērn bijusi gatava un jūsu karstums ir paskubinājis daudzus citus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Bet tos brāļus es esmu sūtījis, lai šinī lietā mūsu slavēšana par jums nepaliktu tukša, lai jūs būtu gatavi, kā esmu sacījis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Lai, ja Maķedonieši man nāktu līdz, un jūs neatrastu gatavus, mēs (lai nesakām: jūs) netiktu kaunā ar šo savu drošo slavēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Tad nu man šķita, ka vajagot paskubināt tos brāļus, lai tie papriekš ietu pie jums un sataisītu jūsu apsolīto svētību, ka tā būtu gatava, tā kā svētība un nekā sīkstība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Bet to es saku: kas sīksti sēj, tas arī sīksti pļaus; un kas bagātīgi sēj, tas arī bagātīgi pļaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Ikviens, kā tas savā sirdī apņemas, ne noskumis nedz piespiests; jo priecīgu devēju Dievs mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Un Dievs ir spēcīgs, jums dot papilnam visādu žēlastību, ka no visām lietām jums būtu arvien itin diezgan un papilnam priekš visādiem labiem darbiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Tā kā ir rakstīts: “Viņš ir kaisījis un nabagiem devis, Viņa taisnība paliek mūžīgi.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Bet, kas sējējam sniedz sēklu, Tas arī maizi sniegs ēšanai un vairos jūsu sēju un liks pieaugt jūsu taisnības augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Un tā visās lietās jūs tapsiet bagāti uz visādu sirds labprātību, un tā caur mums notiks, ka Dievam dod pateicību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Jo šīs palīdzības sagādāšana ne vien atvieglina trūkumu tiem svētiem, bet ir arīdzan bagāta caur to, ka daudzi pateicās Dievam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Šīs jūsu īstenās palīdzības dēļ Dievu pagodinādami par jūsu paklausīgo Kristus evaņģēlija apliecināšanu un par to vientiesīgo labdarīšanu priekš viņiem un priekš visiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Un caur to, ka viņi par jums lūdz, no sirds pēc jums ilgodamies dēļ tās bagātās Dieva žēlastības pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Bet pateicība Dievam par Viņa neizteicamo dāvanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Bet es, Pāvils, pats jūs lūdzu caur Kristus lēnprātību un laipnību, es, kas klāt būdams jūsu starpā gan esmu pazemīgs, bet no tālienes drošs pret jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Es lūdzos, ka man pie jums nākot nevajadzētu būt bargam ar to drošību, ar ko es domāju pret citiem turēties, kam šķiet, ka mēs tā kā pēc miesas dzīvojam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Jo mēs miesā staigādami, tomēr pēc miesas necīnāmies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Jo mūsu karošanas ieroči nav miesīgi, bet spēcīgi Dieva priekšā, nopostīt tos stiprumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Mēs izpostām tos padomus un visu, kas augsti ceļas pret Dieva atzīšanu, un savaldām visas domas, lai Kristum paklausa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Un esam gatavi, atriebt ikvienu neklausību, kad jūsu paklausība būs tapusi pilnīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Vai jūs raugiet uz to, kas priekš acīm? Ja kāds no sevis paša tic, ka Kristum piederot, lai tas atkal pie sevis paša tā domā, ka, tā kā viņš pieder Kristum, tāpat arī mēs piederam Kristum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Jo lai es arī vēl vairāk lielītos ar mūsu varu, ko Tas Kungs mums devis jums par uztaisīšanu un ne par postīšanu, taču es nepalikšu kaunā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Lai mani netur par tādu, kas jūs gribētu baidīt caur grāmatām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Jo tie saka, ka tās grāmatas gan ir svarīgas un stipras, bet tas cilvēks pats klāt būdams nespēcīgs un viņa valoda nievājama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Tas tāds lai zin, kādi mēs no tālienes esam ar vārdiem grāmatās, tādi pat mēs arī klāt būdami ar darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Jo nedrīkstam pieskaitīties jeb sevi līdzināt tādiem, kas paši sevi uzteic; bet viņi paši pie sevis mērodamies un paši sevi ar sevi līdzinādami ir neprātīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Bet mēs nelielīsimies pārlieku, bet pēc tā robežu mēra, ko Dievs mums ir nolicis, ka arī līdz pat jums esam nonākuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Jo mēs neizstiepjamies pārlieku, tā kā līdz jums nebūtu nonākuši, jo mēs arī līdz pat jums esam tikuši ar Kristus evaņģēliju;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Ne pārlieku lielīdamies ar cita darbiem, bet cerēdami, ka jūsu ticībai augot mēs pie jums savās robežās jo vairāk augsim lielumā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Tā ka mēs evaņģēliju varam pasludināt tiem, kas aiz jūsu robežām, un nelielīsimies ar to, kas svešā daļā jau pastrādāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Bet kas lielās, lai lielās iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Jo ne tas, kas pats sevi uzteic, ir derīgs, bet ko Tas Kungs uzteic.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Ak, kad jūs mani kaut cik panestu manā nesaprašanā! Bet jūs mani gan panesat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Jo es esmu iekarsis par jums ar dievišķu karstumu, jo es jūs esmu saderējis, kā šķīstu jumpravu, pievedamu vienam vīram, tas ir Kristum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Bet es bīstos, ka tāpat, kā tā čūska ar savu viltību Ievu pievīlusi, arī jūsu domas netop samaitātas un nenoklīst no tās vientiesības, kas ir iekš Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Jo, ja kas nāk un citu Jēzu sludina, ko mēs neesam sludinājuši, jeb ja jūs dabūjat citu garu, ko jūs neesat dabūjuši, jeb citu evaņģēliju, ko neesat pieņēmuši, tad jūs to gan labi panesat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Jo ceru, ka nebūt neesmu mazāks par tiem tādiem jo augstiem apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Un ja arī runā man trūkst, tad tomēr ne atzīšanā; bet mēs jau vienmēr un visādi jums esam pazīstami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Vai grēku esmu darījis, ka pats pazemojos, lai jūs taptu paaugstināti, ka es jums Dieva evaņģēliju bez maksas esmu sludinājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Citas draudzes esmu aplaupījis, no tām ņemdams algu par to kalpošanu pie jums; un kad es biju pie jums un man kas trūka, tad tomēr nevienu neesmu apgrūtinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Jo manu trūkumu ir atvieglinājuši tie brāļi, kas no Maķedonijas nākuši; un visās lietās es esmu tā turējies, ka es jūs neapgrūtinātu, un tā vēl turēšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Kristus patiesība ir iekš manis, ka šī slava Akajas zemē man neapklusīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Kādēļ? Ka es jūs nebūtu mīlējis? To Dievs zina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Bet ko es daru, to es arī vēl darīšu, lai es iemeslu atņemu tiem, kas iemeslu meklē, lai tie, ar ko lielās, tiek atrasti tādi, kā arī mēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Jo tie tādi viltus apustuļi un viltīgi strādnieki izliekās kā Kristus apustuļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Un tas nav brīnums: jo pats sātans izliekas kā gaišības eņģelis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Tad nav liela lieta, ja arī viņa kalpi izliekas kā taisnības kalpi - tiem būs gals pēc viņu darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Es saku atkal, lai neviens nedomā, ka es esmu nesapraša; bet ja ne, tad pieņemiet mani kā nesaprašu, lai es arī kaut cik varu lielīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Ko es runāju, to nerunāju pēc Tā Kunga, bet tā kā iekš nesaprašanas, kad nu tā ņemos lielīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Kad daudzi lielās pēc miesas, tad es arīdzan gribu lielīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Jo jūs labprāt panesat tos nesaprašas, prātīgi būdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Jo jūs panesat, ja kāds jūs dara par kalpiem, ja kāds jūs plēš, ja kāds no jums ņem, ja kāds paaugstinājās, ja kāds jums cērt vaigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Par negodu saku: - to mēs nespējām; tomēr kurā lietā kāds drošs, (es runāju neprātīgi), tanī es arīdzan esmu drošs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Vai tie ir Ebreji? Es arīdzan. Vai tie ir Israēlieši? Es arīdzan. Vai tie ir Ābrahāma dzimums? Arī es.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Vai tie ir Kristus kalpi? (es neprātīgi runāju) es jo vairāk: iekš darbiem vairāk, iekš sitieniem pārlieku vairāk, iekš cietumiem vairāk, iekš nāves bailēm daudzreiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'No Jūdiem piecreiz esmu dabūjis četrdesmit sitienus bez viena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Trīs reiz esmu šaustīts, vienreiz akmeņiem mētāts, trīs reiz ar laivu esmu cietis ūdens briesmas, nakti un dienu jūras dziļumā esmu sabijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Daudzreiz esmu ceļā bijis: briesmās ūdeņos, briesmās starp slepkavām, briesmās starp savas cilts ļaudīm, briesmās starp pagāniem, briesmās pilsētā, briesmās tuksnesī, briesmās jūrā, briesmās starp viltīgiem brāļiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Iekš darba un pūliņa, daudz nomodā, iekš izsalkšanas un iztvīkšanas, daudz reiz iekš gavēšanām, iekš salšanas un plikuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Bez tam, kas vēl citādi notiek: tās rūpes par visām draudzēm ikdienas laužas man virsū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kas nogurst, un es nenogurstu? Kas tiek kaitināts(apgrēcināts), un es neiedegos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Ja tad būs lielīties, tad lielīšos ar savu nespēcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Mūsu Kunga Jēzus Kristus Dievs un Tēvs, kas ir augsti teicams mūžīgi mūžam, Tas zin, ka es nemeloju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Damaskū ķēniņa Areta ļaužu valdnieks apsargāja Damaskus pilsētu, gribēdams mani gūstīt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Un kurvī pa logu es tapu nolaists pār mūri un izbēgu no viņa rokām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Lielīties man gan nekā nepalīdz, - tomēr es nu gribu runāt par to, ko Tas Kungs man devis redzēt un parādījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Es pazīstu vienu cilvēku iekš Kristus; priekš četrpadsmit gadiem (vai tas miesā bijis, nezinu, jeb vai tas ārā no miesas bijis, nezinu, Dievs to zina) tas ir tapis aizrauts trešā debesī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Un es pazīstu to tādu cilvēku (vai tas miesā bijis, jeb vai tas ārā no miesas bijis, es nezinu, Dievs to zina),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Ka tas ir aizrauts paradīzē un ir dzirdējis neizsakāmus vārdus, ko runāt cilvēkam nav brīv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Par to tādu es gribu lielīties, bet par sevi pašu nelielīšos kā vien ar savu nespēcību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Jo ja es gribētu lielīties, tad tomēr es nebūtu neprātīgs, jo es sacītu patiesību; bet es atturos no tā, lai neviens no manis nedomā vairāk pār to, ko tas pie manis redz, jeb ko tas no manis dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Un lai es to augsto parādīšanu dēļ nepaaugstinājos, tad man miets ir dots miesās, proti sātana eņģelis, kam mani būs sist ar dūrēm, lai es augsti neturos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Tādēļ es To Kungu trīs reiz esmu lūdzis, lai tas no manis atstātos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Un Viņš uz mani ir sacījis: “Tev pietiek Mana žēlastība; jo Mans spēks iekš nespēcīgiem varens parādās.” Tad nu jo labāki lielīšos ar savu nespēcību, lai Kristus spēks pie manis mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Tāpēc man ir labs prāts iekš vājībām, iekš nievāšanām, iekš bēdām, iekš vajāšanām, iekš bailēm - Kristus dēļ. Jo kad esmu nespēcīgs, tad esmu spēcīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Lielīdamies esmu palicis par nesaprašu: jūs mani esat spieduši. Jo man nācās, no jums tapt teiktam, jo es nebūt neesmu bijis mazāks nekā tie jo augstie apustuļi, lai gan es neesmu nekas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Apustuļa zīmes jūsu starpā ir padarītas visā pacietība, ar zīmēm un brīnumiem un spēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Jo kādā lietā jūs esat bijuši mazāki par citām draudzēm, bez vien, ka es priekš sevis jūs neesmu apgrūtinājis? Piedodiet man, ka es jums tā esmu pāri darījis!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Redzi, es esmu gatavs trešo reizi nākt pie jums, un jūs neapgrūtināšu; jo es nemeklēju to, kas jums pieder, bet jūs pašus. Jo bērniem nebūs mantas krāt priekš vecākiem, bet vecākiem priekš bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Un es labprāt pats maksāšu un par maksu pats gribu doties par jūsu dvēselēm; jebšu es jūs pārlieku mīlēdams gan maz topu mīlēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Lai nu ir, ka es jums neesmu bijis par grūtību; bet gan gudrinieks būdams jūs ar viltu esmu ķēris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Vai caur kādu no tiem, ko pie jums esmu sūtījis, es jums mantu esmu izkrāpis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Es Titu esmu lūdzis un to brāli līdz sūtījis; vai Titus jums ko izkrāpis? Vai neesam staigājuši tanī pašā garā? Vai ne tanīs pašās pēdās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Vai jūs atkal domājiet, ka mēs pie jums aizbildinājāmies? Mēs runājam Dieva priekšā iekš Kristus; bet, mani mīļie, viss tas notiek jums par uztaisīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Jo es bīstos, ka es nākdams jūs neatradīšu tādus, kā es gribu, un ka es netapšu atrasts tāds, kā jūs gribat: ka tik nav jūsu starpā bāršanās, nīdēšanās, dusmības, ienaids, aprunāšanas, apmelošanas, uzpūšanās, trokšņi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Ka mans Dievs mani nepazemo, kad atkal pie jums nākšu, un man nav jāraud par daudziem, kas papriekš ir grēkojuši un nav atgriezušies no nešķīstības un maucības un visas nešķīstas būšanas, ko tie darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Nu trešoreiz nāku pie jums. Ikkatru lietu apstiprinās divu vai trīs liecinieku mute.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Jau esmu papriekš sacījis un saku vēl, kā otrreiz pie jums būdams, tāpat arī tagad klāt nebūdams, tiem, kas ir apgrēkojušies, un visiem tiem citiem, ka es, kad atkal nākšu, netaupīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Jo jūs meklējat liecību, vai iekš manis runā Kristus, kas pie jums nav nespēcīgs, bet kas ir varens jūsu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Jo jebšu Viņš ir krustā sists iekš nespēcības, tomēr Viņš ir dzīvs caur Dieva spēku; jo mēs arīdzan esam nespēcīgi iekš Viņa, bet mēs dzīvosim līdz ar Viņu caur Dieva spēku pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Pārbaudaties paši, vai esat ticībā, pārmeklējaties paši! Jeb vai neatzīstaties, ka Jēzus Kristus iekš jums ir? - Ja tikai neesat nederīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Bet es ceru, ka jūs samanīsiet, ka mēs neesam nederīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Bet es Dievu lūdzu, ka jūs nekā ļauna nedariet, ne tādēļ, lai mēs parādītos derīgi, bet lai jūs to labu darītu, un mēs būtu kā nederīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Jo mēs neko nespējam pret patiesību, bet tik par patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Jo mēs priecājamies, kad mēs esam nespēcīgi un jūs spēcīgi, un to mēs arī vēlam, ka jūs topat pilnīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Tāpēc pie jums nebūdams es to rakstu, lai man klāt esot nevajag bargam būt pēc tās varas, ko Tas Kungs man ir devis uz uztaisīšanu un ne uz postīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Beidzot, brāļi, esiet līksmi, topiet pilnīgi, iepriecinājaties savā starpā, esat vienprātīgi, turat mieru; tad Tas mīlestības un miera Dievs būs ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Sveiciniet cits citu ar svētu skūpstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Visi svētie jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Tā Kunga Jēzus Kristus žēlastība un Dieva mīlestība un Svētā Gara sadraudzība lai ir ar jums visiem. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Pāvils, apustulis ne no cilvēkiem, nedz caur kādu cilvēku, bet caur Jēzu Kristu un Dievu To Tēvu, kas To uzmodinājis no miroņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Un visi brāļi, kas pie manis ir, Galatijas draudzēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Žēlastība lai ir jums un miers no Dieva, Tā Tēva, un mūsu Kunga Jēzus Kristus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Kas pats ir nodevies par mūsu grēkiem, ka mūs izrautu no šās tagadējas niknās pasaules pēc mūsu Dieva un Tēva prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Viņam lai ir gods mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Es brīnos, ka jūs tik drīz no tā, kas jūs ir aicinājis caur Kristus žēlastību, topat nogriezti uz citu evaņģēliju;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Un tomēr cita nav, bet tikai kādi rodas, kas jūs sajauc un Kristus evaņģēliju grib pārgrozīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Bet ja arī mēs, vai eņģelis no debesīm jums pasludinātu citu evaņģēliju pār to, ko esam pasludinājuši, tas lai ir nolādēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Itin kā jau esam sacījuši, tā es nu vēl reiz saku: ja kas jums pasludina citu evaņģēliju pār to, ko jūs esat dabūjuši, tas lai ir nolādēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Jo vai es tagad cilvēkiem runāju pa prātam vai Dievam? Jeb vai es meklēju cilvēkiem patikt? Jo ja es cilvēkiem patiktu, tad es nebūtu Kristus kalps.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Bet es jums daru zināmu, brāļi, ka tas evaņģēlijs, ko esmu pasludinājis, nav pēc cilvēku prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Jo es to arī neesmu dabūjis nedz mācījies no cilvēka, bet caur Jēzus Kristus parādīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Jo jūs jau sen esat dzirdējuši par manu dzīvošanu Jūdu ticībā, ka Dieva draudzi pārlieku esmu vajājis un postījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Un biju pārāks Jūdu ticībā pār daudz citiem, kas manā ciltī bija manos gados, un biju tēvišķu iestādījumu pārlieku dedzīgs pārstāvētājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Bet kad Dievam, kas mani no mātes miesām izredzējis un caur Savu žēlastību aicinājis, patika,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Savu Dēlu parādīt iekš manis, ka es Viņa evaņģēliju sludinātu starp pagāniem, tad es padoma neņēmos no miesām un asinīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Nedz gāju atpakaļ uz Jeruzālemi pie tiem, kas priekš manis bija apustuļi, bet tūdaļ nogāju uz Arābiju un atkal atgriezos atpakaļ uz Damasku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Pēc tam, pēc trīs gadiem es nogāju uz Jeruzālemi, iepazīties ar Pēteri, un paliku pie tā piecpadsmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Bet citu nevienu no apustuļiem neredzēju, kā vien Jēkabu, Tā Kunga brāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Bet ko jums rakstu, redzi, to apliecināju Dieva priekša, ka es nemeloju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Pēc tam nācu uz Sīrijas un uz Ķiliķijas zemēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Bet no vaiga nebiju pazīstams Jūdu zemes draudzēm, kas ir iekš Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Bet tie to vien bija dzirdējuši, ka tas, kas citkārt mūs vajāja, tagad sludina to ticību, ko tas citkārt postīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Un tie par mani pagodināja Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Pēc tam, pēc četrpadsmit gadiem, es atkal nogāju uz Jeruzālemi ar Barnabu, arī Titu paņemdams līdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Bet es turp nogāju caur kādu parādīšanu un tiem to evaņģēliju, ko es sludināju starp pagāniem, liku priekšā un sevišķi tiem jo cienīgiem, lai es velti neteku vai nebūtu skrējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Bet arī Titus, kas bija ar mani, Grieķis būdams, netapa spiests apgraizīties;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Bet to ielīdušo viltīgo brāļu dēļ, kas bija iezagušies, izlūkot mūsu brīvību, kas mums ir iekš Kristus Jēzus, ka tie mūs darītu par kalpiem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Tiem mēs ne acumirkli neesam ceļu griezuši nedz paklausījuši, lai evaņģēlija patiesība pie jums paliktu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Bet no tiem, kas bija jo cienīgi (kādi tie jebkad bijuši, tas man vienalga, Dievs neuzlūko cilvēka vaigu), šie jo cienīgie man neko nav uzlikuši klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Bet turpretī, kad tie redzēja, ka evaņģēlijs man ir uzticēts pie tiem, kam ir priekšāda, tā kā Pēterim pie tiem, kas ir apgraizīti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Jo Tas, kas ar Pēteri bijis spēcīgs apustuļu amatā pie apgraizītiem, Tas arī bijis spēcīgs ar mani pie pagāniem) -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Un kad Jēkabs, Kefas un Jānis, ko turēja par pīlāriem, atzina to žēlastību, kas man bija dota; tad tie man un Barnabam roku deva uz biedrību, lai mēs mācītu pagānus un viņi (mācītu) apgraizītos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Tikai lai mēs nabagus pieminētu, - un es arī esmu rūpējies to izdarīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Un kad Pēteris bija nācis uz Antioķiju, tad es tam acīs stājos pretī, jo viņš bija apsūdzams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Jo, pirms nekā no Jēkaba kādi bija atnākuši, viņš ēda kopā ar pagāniem; bet kad tie bija atnākuši, tad viņš atrāvās un nošķīrās, bīdamies tos no apgraizīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Un līdz ar viņu arī tie citi Jūdi apgrēkojās ar liekulību, tā ka arī Barnaba līdz tapa nogriezts caur viņu liekulību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Bet kad es redzēju, ka tie nestaigā pareizi pēc evaņģēlija patiesības, tad es Pēterim sacīju visiem dzirdot: Ja tu Jūds būdams dzīvo ka pagāns un nekā Jūds, ko tu spiedi pagānus, lai tie dzīvo kā Jūdi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Mēs no dzimuma esam Jūdi un ne grēcinieki no pagāniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Bet zinādami, ka cilvēks netop taisnots caur bauslības darbiem, bet caur Jēzus Kristus ticību, arī mēs esam ticējuši uz Kristu Jēzu, lai topam taisnoti caur Kristus ticību un ne caur bauslības darbiem: tāpēc ka caur bauslības darbiem neviena miesa netaps taisnota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Bet ja mēs, kas meklējam tapt taisnoti iekš Kristus, arī paši topam atrasti grēcinieki, - vai tad Kristus ir grēka kalps? Nemaz ne!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Jo ja es to, ko esmu nolauzis, atkal uztaisu, tad pats kļūstu par pārkāpēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Jo es caur bauslību bauslībai esmu miris, lai dzīvotu Dievam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Es ar Kristu esmu krustā sists, bet es dzīvoju, tomēr vairs ne es, bet iekš manis dzīvo Kristus, un ko es tagad dzīvoju miesā, to dzīvoju ticībā uz To Dieva Dēlu, kas mani mīlējis un Pats par mani nodevies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Es nenicināju Dieva žēlastību; jo ja taisnība ir caur bauslību, tad Kristus velti miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ak jūs neprātīgie Galatieši, kas jūs ir apmānījis, patiesībai nepaklausīt, jūs, kam priekš acīm rakstīts Jēzus Kristus, Tas krustā sistais?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'To vien gribu no jums zināt, vai jūs to Garu esat dabūjuši no bauslības darbiem, vai no ticības mācības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Vai jūs esat tik neprātīgi, ka garā iesākuši, tagad miesā pabeidziet?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Vai jūs tik daudz velti esat cietuši? Ja tikai velti vien!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Tad nu (Viņš), kas jums to Garu sniedz un iekš jums modina brīnuma spēkus, vai Viņš to dara no bauslības darbiem vai no ticības mācības?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Tā kā Ābrahāms Dievam ticējis, un tas viņam ir pielīdzināts par taisnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Tad saprotat, ka, kuri ir no ticības, tie ir Ābrahāma bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Un tas raksts paredzēdams, ka Dievs caur ticību pagānus taisno, Ābrahāmam papriekš sludinājis to prieka vārdu: “Iekš tevis visas tautas taps svētītas.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Tad nu kas ir no ticības, tie līdz ar to ticīgo Ābrahāmu top svētīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Jo cik ir no bauslības darbiem, tie ir apakš lāsta, jo ir rakstīts: “Ikviens ir nolādēts, kas nepaliek iekš visa, kas ir rakstīts bauslības grāmatā, ka viņš to dara.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Un ka neviens caur bauslību netop taisnots pie Dieva, tas ir zināms: jo taisnais dzīvos no ticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Bet bauslība nav no ticības; bet kurš cilvēks to darīs, tas caur to dzīvos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristus mūs ir atpircis no bauslības lāsta, priekš mums par lāstu palicis, (jo ir rakstīts: “Nolādēts ikviens, kas kārts pie koka”),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Ka Ābrahāma svētība nāktu uz pagāniem iekš Kristus Jēzus, un ka mēs Tā Gara apsolīšanu dabūtu caur ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Brāļi, es runāju cilvēcīgi: neviens jau nenicina apstiprinātu cilvēka iestādījumu (testamentu) nedz pieliek ko klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Tad nu Ābrahāmam un viņa sēklai tās apsolīšanas notikušas. Viņš nesaka: “Un tavām sēklām”, tā kā no daudziem, bet tā kā no vienas: “Un tavai Sēklai”, Tas ir Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Un to es saku: tas iestādījums, kas papriekš no Dieva ir apstiprināts uz Kristu, netop nocelts caur bauslību, kas pēc četrsimt un trīsdesmit gadiem notikusi, ka tā to apsolīšanu būtu iznīcinājusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Jo ja tā iemantošana ir no bauslības, tad tā vairs nav no apsolīšanas: bet Dievs to Ābrahāmam ir dāvinājis caur apsolīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Par ko tad nu bauslība? Tā to pārkāpumu dēļ ir pielikta klāt, tiekams tā Sēkla nāktu, kam tā apsolīšana notikusi, un bauslība ir iestādīta caur eņģeļiem, caur vidutāja roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Bet vidutājs nav viena paša vidutājs; bet Dievs ir vienīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Vai tad nu bauslība ir pretī Dieva apsolīšanām? Nemaz. Jo ja kāda bauslība būtu dota, kas spētu dot dzīvību, tad patiesi taisnība nāktu no bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Bet tas raksts visu ir saslēdzis apakš grēka, ka tā apsolīšana tiem ticīgiem taptu dota no ticības uz Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Bet pirms ticība nāca, mēs tapām turēti saslēgti apakš bauslības uz tās nākamās ticības atspīdēšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Tad nu bauslība ir bijusi mūsu pamācītājs uz Kristu, ka mēs taptu taisnoti caur ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Bet kad ticība ir nākusi, tad mēs vairs neesam apakš tā pamācītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Jo jūs visnotaļ esat Dieva bērni caur to ticību iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Jo jūs visi, kas esat kristīti uz Kristu, jūs Kristu esat apvilkuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Tur nav ne Jūds, ne Grieķis, tur nav ne kalps, ne svabadnieks, tur nav ne vīrs, ne sieva, - jo jūs visi esat viens iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Un ja jūs Kristum piederat, tad jūs esat Ābrahāma dzimums un pēc apsolīšanas mantinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Bet Es jums saku: kamēr mantinieks vēl ir bērns, tad starp viņu un kalpu nav nekādas starpības, jebšu viņš kungs ir pār visu mantu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Bet viņš ir apakš pārstāvētājiem un sargiem līdz tam no tēva nospriestam laikam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Tāpat arī mēs, kad bijām bērni, bijām kalpu kārtā apakš pasaules likumu sākumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Bet kad tā laika piepildīšana nāca, tad Dievs sūtīja Savu Dēlu, dzimušu no sievas un noliktu apakš bauslības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Ka Viņš tos, kas bija apakš bauslības, atpirktu, ka mēs to bērnu tiesu dabūtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Un kad nu jūs esat bērni, tad Dievs Sava Dēla Garu ir sūtījis jūsu sirdīs, tas sauc: Abba, Tēvs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Tad nu vairs neesi kalps, bet bērns; bet ja bērns, tad arī Dieva mantinieks caur Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Bet to brīdi, kad jūs Dievu neatzināt, jūs esat kalpojuši tiem, kas pēc būšanas nav dievi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Un tagad, kad jūs Dievu atzīstat, bet jo vairāk, kad no Dieva esat atzīti, - kā jūs atkal griežaties pie tiem vājiem un tukšiem sākumiem un tiem atkal no jauna gribat kalpot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Jūs cienījat dienas un mēnešus un laikus un gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Man bail jūsu dēļ, ka tik nebūšu velti pie jums strādājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Topiet tādi, kā es; jo arī es esmu tapis tāds, kā jūs, brāļi, es jūs lūdzu. - Jūs man neko neesat pāri darījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Bet jūs zināt, ka es pirmoreiz miesas vājības dēļ jums evaņģēliju esmu sludinājis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Un tā pārbaudīšana, kas jums caur manu miesu notikusi, jums nav bijusi nicināma nedz nepanesama, bet jūs mani esat uzņēmuši tā kā Dieva eņģeli, tā kā Kristu Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Tad nu, kāda līksmība jums to brīdi bija? Jo es jums dodu liecību, ka jūs, ja tas būtu varējis būt, savas acis būtu izrāvuši un man devuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Vai tad es nu jūsu ienaidnieks esmu tapis, jums patiesību sacīdams?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Tie iekarst jūsu dēļ, kā nav labi, bet tie jūs grib novērst, lai jūs atkal iekarstu viņu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Bet labi ir vienmēr iekarst laba dēļ un ne tad vien, kad es esmu klāt pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mani bērniņi, ko es atkal dzemdēju ar sāpēm, tiekams Kristus iekš jums nāk redzams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Es gan vēlētos, tagad pie jums būt un citādā balsī runāt; jo man jūsu dēļ padoma pietrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Sakiet man, jūs, kas apakš bauslības gribat būt, vai jūs bauslību neesat dzirdējuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Jo ir rakstīts, ka Ābrahāmam bijuši divi dēli, viens no tās kalpones un otrs no tās svabadās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Bet kas no tās kalpones bija, tas ir piedzimis pēc miesas; un kas no tās svabadās, tas caur to apsolīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Šie vārdi pēc līdzības saprotami. Šīs ir tās divas derības; viena no Sina kalna, kas uz kalpošanu dzemdē, tā ir tā Hāgare.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Jo Hāgare ir tas Sina kalns Arābijā - un līdzinājās tai tagadējai Jeruzālemei, kas kalpo ar saviem bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Bet tā Jeruzāleme, kas ir augšā, ir tā svabadā, tā ir mūsu visu māte.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Jo ir rakstīts: priecājies, neauglīgā, tu, kas neesi dzemdējusi, izsaucies un gavilē tu, kas bērnu sāpes necieti; jo tai tukšai ir daudz bērnu, vairāk nekā tai, kas ir apprecēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Bet mēs, brāļi, esam apsolīšanas bērni, tā kā Īzaks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Bet itin kā to brīdi tas, kas bija piedzimis pēc miesas, vajāja to, kas bija piedzimis pēc Gara, tāpat arī tagad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Bet ko tas raksts saka? Izmet to kalponi un viņas dēlu; jo tam kalpones dēlam nebūs mantot ar tās svabadās dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Tāpēc, brāļi, mēs neesam tās kalpones bērni, bet tās svabadās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Tad nu pastāviet tai svabadībā, uz ko Kristus mūs ir atsvabinājis, un neliekaties atkal gūstīties kalpošanas jūgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Redzi, es Pāvils jums saku: ja jūs topat apgraizīti, tad Kristus jums nederēs nenieka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Un atkal es apliecināju ikvienam cilvēkam, kas top apgraizīts, ka tam visa bauslība jātur.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Jūs esat atkāpušies no Kristus, jūs, kas caur bauslību gribat tapt taisnoti; jūs žēlastību esat pazaudējuši:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Jo no ticības mēs garā gaidām taisnības cerību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Jo iekš Kristus Jēzus nedz apgraizīšana ko spēj, nedz priekšāda, bet ticība, kas caur mīlestību spēcīga parādās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Jūs gan labi tecējāt; kas jūs ir aizkavējis, ka jūs patiesībai nepaklausāt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Tā pierunāšana nav no Tā, kas jūs aicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Maz rauga saraudzē visu mīklu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Es droši uz jums paļaujos iekš Tā Kunga, ka jūs citu prātu neturēsiet; bet kas jūs sajauc, tas nesīs to sodu, lai būtu, kas būdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Bet, brāļi, ja es vēl apgraizīšanu sludināju, kam tad vēl topu vajāts? Tad tā piedauzīšanās pie krusta jau būtu mitējusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Kaut jel arī tie taptu graizīti, kas jūs musina!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Jo, brāļi, jūs uz svabadību esat aicināti; tikai ne uz tādu svabadību, ka miesai ir vaļa; bet kalpojiet cits citam mīlestībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Jo visa bauslība vienā vārdā top piepildīta, proti šinī; Tev būs savu tuvāko mīlēt kā sevi pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Bet ja jūs savā starpā kožaties un ēdaties, tad pielūkojiet, ka jūs cits no cita netiekat aprīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Bet es saku: staigājiet garā, tad jūs miesas kārību nepadarīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Jo miesai gribās pret garu un garam pret miesu, un tie stāv viens otram pretī, ka jūs nedarāt, ko gribat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Bet ja jūs no Gara topat vadīti, tad jūs neesat apakš bauslības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Bet miesas darbi ir zināmi, ka laulības pārkāpšana, maucība, nešķīstība, bezkaunība,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Elkadievība, burvība, ienaids, bāršanās, nīdēšanās, dusmības, ķildas, šķelšanās, viltīgas mācības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Skaudības, slepkavības, plītēšanas, rīšanas, un kas šiem līdzīgi; no tiem es jums papriekš saku, tā kā jau esmu sacījis, ka tie, kas tādas lietas dara, Dieva valstību neiemantos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Bet Tā Gara auglis ir: mīlestība, līksmība, miers, pacietība, laipnība, labprātība, ticība, lēnprātība, sātība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Pret tādiem nav bauslība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Bet tie, kas Kristum pieder, savu miesu ir krustā situši ar tām kārībām un iekārošanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Ja mēs garā dzīvojam, tad lai arī garā staigājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Lai nedzenamies pēc nīcīga goda, cits citu kaitinādami, cits citu skauzdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Brāļi, ja kāds cilvēks taptu pieķerts kāda noziegumā, tad jūs, kas esat garīgi, atgriežat tādu ar lēnprātīgu garu, lūkojot uz sevi pašu, ka arī tu netopi kārdināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Nesiet cits cita nastas, un tā jūs piepildīsiet Kristus bauslību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Jo kam šķiet, ka viņš kas esot, un nav nekas, tas pieviļās savā prātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Bet ikviens lai pārbauda savu paša darbu, tad tam būs teikšana pie sevis paša vien un ne pie cita.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Jo ikkatrs nesīs savu paša nastu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Lai tas, kas top mācīts tai vārdā, visādu labumu izdala tam, kas viņu māca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Nepieviļaties! Dievs neļaujas apsmieties. Jo ko cilvēks sēj, to tas arī pļaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Ja kas sēj uz savu miesu, tas no tās miesas pļaus samaitāšanu; bet kas sēj uz To Garu, tas pļaus no Tā Gara mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Tad nu labu darīdami lai nepiekūstam; jo savā laikā arī pļausim, ja nepiekūstam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Tāpēc nu, kamēr mums laiks, lai labu darām visiem, bet visvairāk ticības biedriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Raugāt, kādu garu grāmatu es jums esmu rakstījis ar savu paša roku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Visi tie, kas grib spīdēt pēc miesas, tie jūs spiež apgraizīties, tāpēc vien, ka tie Kristus krusta dēļ netaptu vajāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Jo tie, kas ir apgraizīti, paši netur bauslību, bet grib, lai jūs topat apgraizīti, ka tie ar jūsu miesu varētu lielīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Bet tas lai man nenotiek, ka lielos, kā vien ar mūsu Kunga Jēzus Kristus krustu, caur ko man pasaule ir krustā sista un es pasaulei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Jo iekš Kristus Jēzus nedz apgraizīšana kas ir, nedz priekšāda, bet jauns radījums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Un cik pēc šā priekšraksta staigās, pār tiem lai ir miers un žēlastība un pār to Dieva Israēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Uz priekšu lai neviens man vairs nedara rūpes, jo es savā miesā nesu Tā Kunga Jēzus rētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jūsu garu, brāļi. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Pāvils, caur Dieva prātu Jēzus Kristus apustulis, tiem svētiem, kas ir Efesū un ir ticīgi iekš Kristus Jēzus:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Slavēts lai ir mūsu Kunga Jēzus Kristus Dievs un Tēvs, kas mūs ir svētījis ar visādu garīgu svētību iekš debešķīgām dāvanām caur Kristu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Tā kā Viņš mūs iekš Tā izredzējis priekš pasaules radīšanas, ka mēs būtu svēti un bezvainīgi Viņa priekšā iekš mīlestības;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Tas mums papriekš ir nodomājis to bērnu tiesu caur Jēzu Kristu pie Sevis paša pēc Sava prāta labpatikšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Par slavu Savai godājamai žēlastībai, caur ko Viņš mūs ir darījis patīkamus iekš Tā Mīļotā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Iekš Tā mums ir atpestīšana caur Viņa asinīm, grēku piedošana, pēc Viņa bagātās žēlastības');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Ko Viņš mums papilnam parādījis iekš visas gudrības un saprašanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Un pēc Savas labpatikšanas Viņš mums ir darījis zināmu Sava prāta noslēpumu, ko Viņš apņēmies Pats pie Sevis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Visu valdīt uz laiku piepildīšanu, ka visas lietas iekš Kristus kā apakš vienas galvas taptu savienotas, gan tās debesīs, gan tās virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Iekš Viņa, caur ko mēs arīdzan tapuši mantinieki, izredzēti pēc Viņa apņemšanās, kas visas lietas spēcīgi padara pēc Sava prāta padoma;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Ka Viņa godībai būtu par slavu mēs, kas papriekš uz Kristu cerējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Caur To arī jūs esat dzirdējuši to patiesības vārdu, savas pestīšanas evaņģēliju, iekš Viņa arī jūs pie ticības nākuši, esat apzieģelēti ar to apsolīšanas Svēto Garu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Kas ir mūsu mantošanas ķīla, ka Viņš pestīs Savus ļaudis Savai godībai par slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Tādēļ arīdzan, kad dzirdēju par jūsu ticību iekš Tā Kunga Jēzus un par to mīlestību uz visiem svētiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Tad es nemitējos par jums pateikties, jūs pieminēdams savās lūgšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Ka mūsu Kunga Jēzus Kristus Dievs, Tas godības Tēvs, jums dotu gudrības un parādīšanas Garu iekš Viņa atzīšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Apgaismotas prāta acis, ka jūs varat atzīt, kāda ir Viņa aicināšanas cerība, un cik bagāta Viņa mantojama godība pie tiem svētiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Un kāds Viņa spēka pārlieku augstais lielums pie mums, kas ticam, pēc Viņa varenā un spēcīgā darba,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Ko tas padarījis iekš Kristus, Viņu uzmodinādams no miroņiem, un Viņu sēdinādams pie Savas labās rokas debesīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Pāri par ikkatru virsniecību un valdību un spēku un kundzību un ikkatru vārdu, kas top dēvēts ne vien šinī laikā bet arī nākamā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Un Tas ir padevis visas lietas apakš Viņa kājām, un Viņu visās lietās devis par galvu tai draudzei,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Kas ir Viņa miesa un Tā pilnums, kas visur visu piepilda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Un arī jūs, kas bijāt nomiruši iekš pārkāpšanām un grēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Iekš kuriem jūs citkārt staigājuši pēc šās pasaules ieraduma un pēc tā virsnieka, kas valda gaisā, gara, kas tagad spēcīgi darbojās iekš neticības bērniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Starp tiem arī mēs visi citkārt dzīvojām savas miesas kārībās, darīdami miesas un sirds prātu, un no dabas bijām dusmības bērni, tā kā arī tie citi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Bet Dievs, bagāts būdams apžēlošanā, mūs ir mīlējis Savas lielās mīlestības pēc,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Un mūs, kas bijām nomiruši grēkos, ar Kristu ir darījis dzīvus (caur žēlastību jūs esat izglābti),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Un līdz uzmodinājis un līdz sēdinājis debesīs iekš Kristus Jēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Ka Tas nākamos laikos parādītu Savas žēlastības pārliekam lielo bagātību caur to laipnību pār mums iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Jo no žēlastības jūs esat pestīti caur ticību, un tas ne no jums: tā ir Dieva dāvana;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Ne no darbiem, lai neviens nelielās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Jo mēs esam Viņa darbs, radīti iekš Kristus Jēzus uz labiem darbiem, uz kuriem Dievs mūs papriekš ir sataisījis, ka mums iekš tiem būs staigāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Tāpēc pieminiet, ka jūs, kas citkārt bijāt pagāni pēc miesas un tapāt par priekšādu saukti no tiem, kas top saukti tā apgraizīšana, kas pie miesas ar rokām darīta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Ka jūs tanī laikā bijāt bez Kristus, šķirti no Israēla draudzes un svešinieki tām apsolīšanas derībām, bez cerības un bez Dieva pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Bet tagad iekš Kristus Jēzus jūs, kas citkārt bijuši tālu, esat tuvu nākuši caur Kristus asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Jo Viņš ir mūsu miers, kas no abiem ir darījis vienu un to sienu, kas bija starpā, ir noārdījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'To ienaidību noceldams caur Savu miesu, to baušļu bauslību, kas stāv likumos, ka Viņš tos divus iekš Sevis paša radītu par vienu jaunu cilvēku, mieru darīdams,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Un ka Viņš abus vienā miesā Dievam salīdzinātu caur to krustu, to ienaidību pie tā nokāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Un nākdams Viņš mieru pasludinājis caur evaņģēliju jums, kas bijāt tālu, un tiem, kas ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Jo caur Viņu mums abiem ir pieiešana iekš viena Gara pie Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Tad nu jūs vairs neesat svešinieki un piedzīvotāji, bet līdzpavalstnieki ar tiem svētiem un Dieva saime,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Uztaisīti uz apustuļu un praviešu pamata, kur Pats Jēzus Kristus ir tas stūra akmens,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Uz kā viss tas nams taisīts aug par svētu Dieva namu iekš Tā Kunga;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Uz kā arī jūs topat līdz uztaisīti par Dieva mājas vietu iekš Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Tādēļ es, Pāvils, esmu Tā Kunga Jēzus Kristus saistīts par jums pagāniem,-');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Ja jūs tikai esat dzirdējuši, kādā vīzē Dieva žēlastība man priekš jums ir dota,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, '(Proti) ka Viņš man caur parādīšanu ir zināmu darījis to noslēpumu, - tā kā es īsiem vārdiem to jau esmu rakstījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Pie tam jūs, to lasīdami, varat nomanīt, kā es saprotu Kristus noslēpumu, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Par ko citos laikos cilvēku bērniem ziņa nebija dota, tā kā tā tagad caur To Garu ir parādīta Viņa svētiem apustuļiem un praviešiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Ka pagāni ir līdzmantinieki un vienā miesā savienoti, un ka tiem arīdzan ir dalība pie Viņa apsolīšanas iekš Kristus caur evaņģēliju;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Tam es esmu palicis par kalpu pēc tās žēlastības dāvanas, ko Dievs man devis pēc Sava spēka varas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Man, tam vismazākajam no visiem svētiem, šī žēlastība ir dota, Kristus neizdibinājamo bagātību caur evaņģēliju pasludināt starp pagāniem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Un visus apgaismot, lai saprot, kā ir gājis ar to noslēpumu, kas no iesākuma bija apslēpts iekš Dieva, tā visu radītāja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Ka Dieva daudzkārtīgā gudrība tagad caur to draudzi taptu zināma tām varām un spēkiem debesīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Pēc tā mūžīgā nodoma, ko Viņš ir izdarījis iekš Kristus Jēzus, mūsu Kunga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Iekš kā mums ir drošība un pieiešana ar uzticību caur to ticību uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Tādēļ es jūs lūdzu, ka jūs nepiekūstat iekš manām bēdām par jums, kas ir jūsu gods.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Šās lietas labad es loku savus ceļus mūsu Kunga Jēzus Kristus Tēva priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'No kā viss top dēvēts, kam ir bērna vārds debesīs un virs zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Lai Viņš jums dod pēc Savas bagātās godības, ar spēku tapt stiprinātiem caur Viņa Garu pie tā iekšējā cilvēka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Ka Kristus caur ticību mājo jūsu sirdīs, un jūs mīlestībā iesakņojaties un nostiprinājaties,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Ka spējat saņemt līdz ar visiem svētiem, kāds tas platums un garums un dziļums un augstums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Un atzīt Kristus mīlestību, kas ir daudz augstāka nekā visa saprašana, ka topat piepildīti ar visu Dieva pilnību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Bet Tam, kas ir spēcīgs pārlieku vairāk darīt pār visu, ko mēs lūdzam vai domājam, pēc tā spēka, kas iekš mums spēcīgs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Tam lai ir gods iekš tās draudzes un iekš Kristus Jēzus uz radu radiem mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Tad nu jūs lūdzu, es, saistīts iekš Tā Kunga, ka jūs cienīgi staigājiet pēc tās aicināšanas, ar ko esat aicināti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Ar visu pazemību un laipnību un lēnprātību, cits citu panesdami iekš mīlestības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Un čakli būdami, sargāt gara vienprātību caur miera saiti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Viena miesa un viens gars, tā kā jūs arī esat aicināti savā aicināšanā uz vienu cerību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Viens Kungs, viena ticība, viena kristība;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Viens visu Dievs un Tēvs, kas ir pār visiem un caur visiem un iekš visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Bet ikvienam no jums žēlastība ir dota pēc Kristus dāvanas mēra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Tāpēc Tas saka: “Viņš ir uzkāpis augstībā, cietumu pārvarējis un cilvēkiem dāvanas devis.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '(Bet tas vārds: Viņš ir uzkāpis, ko citu tas saka nekā: Viņš arī papriekš ir nokāpis tais jo zemās zemes vietās?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Kas ir nokāpis, tas ir Tas Pats, kas arī uz augšu kāpis, tālu pār visām debesīm, ka Tas visu piepildītu.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Un Viņš citus ir devis par apustuļiem un citus par praviešiem un citus par evaņģēlistiem un citus par ganiem un mācītājiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Ka tie svētie top sataisīti uz kalpošanas darbu, Kristus miesai par uztaisīšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Kamēr mēs visi tiekam pie Dieva Dēla vienādas ticības un atzīšanas un uzaugam par pilnīgu vīru, pilnīgi Kristum līdzīgi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Lai vairs neesam bērni, kas top šaubīti un mētāti no ikkatra mācības vēja caur cilvēku blēdību un viltību, ar ko tie meklē mūs pievilt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Bet patiesīgi būdami iekš mīlestības lai augam visās lietās iekš Tā, kas ir tā galva, proti Kristus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'No kā visa miesa top salaista un sastiprināta caur visādām palīdzības saitēm pēc tā spēka, kas ikkatram loceklim ir, ka tā miesa uzaug pati uztaisīdamies iekš mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'To nu es saku un apliecināju iekš Tā Kunga, ka jums nebūs vairs staigāt, kā tie citi pagāni staigā iekš prāta nelietības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Saprašanā aptumšoti, sveši būdami tai Dieva dzīvībai caur nezināšanu, kas iekš tiem ir, caur viņu sirds cietību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Kas par nebēdniekiem palikuši, ir nodevušies bezkaunībai uz visādas nešķīstības darbiem iekš mantas kārības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Bet tā jūs Kristu neesat mācījušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Ja tikai par Viņu esat dzirdējuši un iekš Viņa esat mācīti, tā kā iekš Jēzus ir patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Tad nu jums pēc tās iepriekšējās dzīvošanas būs nolikt to veco cilvēku, kas samaitāts caur viltīgām kārībām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Un jums būs atjaunoties savā sirds prātā un garā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Un apvilkt to jauno cilvēku, kas pēc Dieva radīts iekš patiesas taisnības un svētības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Tādēļ noliekat melus un runājiet patiesību, ikviens ar savu tuvāko, jo mēs esam locekļi savā starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Dusmojiet un negrēkojiet; lai saule nenoiet pār jūsu dusmību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Nedodiet vietu velnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Kas zadzis, tam vairs nebūs zagt, bet jo vairāk strādāt un ar rokām ko labu sagādāt, lai būtu ko dot tam, kam trūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Nekādai nelietīgai valodai nebūs iziet no jūsu mutes; bet tādai, kas ir laba un derīga priekš uztaisīšanas, lai dod svētību tiem, kas to dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Un neapbēdinājiet to Svēto Dieva Garu, caur ko jūs esat apzieģelēti uz to atpestīšanas dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Ikviens rūgtums un dusmība un bardzība un brēkšana un zaimošana līdz ar visu ļaunumu lai ir tālu nost no jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Bet esiet cits pret citu laipnīgi, sirds žēlīgi, cits par citu apžēlodamies, tā kā arī Dievs iekš Kristus ir apžēlojies par jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Tad nu Dievam dzenaties pakaļ kā mīļi bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Un staigājiet iekš mīlestības, kā arī Kristus mūs ir mīlējis un Pats par mums nodevies par dāvanu un upuri Dievam par saldu smaržu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Bet maucība un visa nešķīstība vai mantas kārība lai jūsu starpā netop ne minēta, kā tiem svētiem pieklājās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Arī bezkaunīga būšana un ģeķīga tērzēšana vai smiekli, kas neklājās, bet jo vairāk pateicība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Jo to jūs zināt, ka neviens maucinieks nedz nešķīsts, nedz negausis, kas ir elkadieva kalps, nedabū mantību Kristus un Dieva valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Lai neviens jūs nepieviļ ar tukšiem vārdiem, jo caur to Dieva dusmība nāk pār tiem neticības bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Tāpēc neesiet viņu biedri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Jo jūs citkārt bijāt tumsība, bet tagad jūs esat gaisma iekš Tā Kunga. Staigājiet kā gaismas bērni,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(Jo gaismas auglis ir visāda labprātība un taisnība un patiesība),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Un pārbaudiet, kas Tam Kungam labi patīk,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Un neņemiet daļas pie tiem neauglīgiem tumsības darbiem, bet jo vairāk tos arī norājiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Jo ko tie slepeni dara, to izsacīt jau ir kauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Bet visas lietas, kad tās no gaismas top norātas nāk gaismā: jo kas nāk gaismā, ir gaisma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Tāpēc Viņš saka: “Uzmosties tu, kas guli, un celies augšā no miroņiem, tad Kristus tevi apgaismos.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Tad nu pielūkojiet, ka jūs apdomīgi staigājiet, nekā neprātnieki, bet kā prāta ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Ņemiet vērā to laiku, jo tās dienas ir ļaunas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Tādēļ neesat neprātīgi, bet saprotiet, kas ir Tā Kunga prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Un nepiedzeraties ar vīnu, tas ir posts; bet topiet piepildīti ar Garu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Runādami savā starpā slavas dziesmās un pateicības dziesmās un garīgās dziesmās, dziedādami un slavu dodami Tam Kungam savās sirdīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Pateicieties vienmēr par visu Dievam un Tam Tēvam iekš mūsu Kunga Jēzus Kristus vārda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Cits citam padodamies iekš Dieva bijāšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Jūs sievas, esat paklausīgas saviem vīriem kā Tam Kungam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Jo vīrs ir sievas galva, kā arī Kristus draudzes galva; Viņš ir Savas miesas Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Bet kā draudze Kristum ir paklausīga, tāpat arī sievas saviem vīriem visās lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Jūs vīri, mīlējiet savas sievas, tā kā arī Kristus to draudzi mīlējis un Pats par to ir nodevies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Ka Viņš to svētītu, ko ir šķīstījis caur ūdens mazgāšanu iekš vārda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Ka Viņš to draudzi stādītu Savā priekšā pagodinātu, kurai nebūtu nekāds traips, nedz grumba, nedz cita kāda vaina, bet ka tā būtu svēta un bezvainīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Tāpat pienākas vīriem savas sievas mīlēt kā savu miesu; jo kas savu sievu mīl, tas mīl sevi pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Jo neviens vēl nav ienīdējis savu paša miesu, bet tas to kopj un glabā, tā kā arī Kristus to draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Jo mēs esam Viņa miesas locekļi, no Viņa miesām un no Viņa kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Tāpēc cilvēks atstās savu tēvu un māti un pieķersies pie savas sievas, un tie divi būs viena miesa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Šis noslēpums ir liels; bet es runāju par Kristu un par to draudzi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Tāpat arī jums ikvienam būs savu sievu mīlēt kā sevi pašu; bet sieva lai bīstas vīru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Jūs bērni, paklausiet saviem vecākiem iekš Tā Kunga, jo tas pieklājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Godā savu tēvu un māti - (šis ir tas pirmais bauslis, kam ir apsolīšana) -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Lai tev labi klājās un tu ilgi dzīvo virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Un jūs tēvi, nekaitinājiet savus bērnus; bet uzaudzinājiet tos Tā Kunga pārmācīšanā un pamācīšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Jūs kalpi, paklausiet tiem, kas pēc miesas jūsu kungi, ar bijāšanu un drebēšanu, iekš sirds vientiesības, tā kā Kristum,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Nekalpodami tik priekš acīm, tā kā gribēdami patikt cilvēkiem, bet kā Kristus kalpi, darīdami Dieva prātu no visas dvēseles,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Ar labu prātu, kā Tam Kungam kalpodami un nekā cilvēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Zinādami, ja kas ko labu darīs, ka tas to atdabūs no Tā Kunga, lai ir kalps, lai svabadnieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Un jūs kungi, dariet to pašu viņiem; atmetiet draudus, zinādami, ka arī jums Kungs ir debesīs, un Tas neuzlūko cilvēka vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Beidzot, mani brāļi, topiet spēcīgi iekš Tā Kunga un iekš Viņa spēka varas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Apvelkat visas Dieva bruņas, lai varat pretī stāvēt velna viltīgām uzmākšanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Jo mums nav cīnīšanās pret miesu un asinīm, bet pret tām valdībām un varām, pret tiem pasaules valdītājiem šīs pasaules tumsībā, pret tiem ļauniem gariem gaisā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Tādēļ sagrābiet visus tos Dieva ieročus, ka jūs varat pretī stāvēt ļaunā dienā un visu uzvarējuši, pastāvēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Tad nu stāviet, savus gurnus apjozuši ar patiesību un apvilkuši taisnības bruņas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Un kājas apāvuši ar gatavu prātu pakaļ dzīties tam miera evaņģēlijam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Pār visām lietām sagrābuši ticības priekšturamās bruņas, ar ko jūs tā blēdnieka ugunīgās bultas visas varēsiet izdzēst;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Un ņemiet pestīšanas bruņucepuri un Tā Gara zobenu, tas ir Dieva vārdu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Ar ikvienu lūgšanu un pielūgšanu lūgdami allažiņ iekš Gara, un uz to nomodā būdami iekš visādas pastāvēšanas un aizlūgšanas par visiem svētiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Un par mani, ka man tas vārds taptu dots, kad es savu muti atdaru, ar drošību zināmu darīt evaņģēlija noslēpumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Par ko es vēstnesis esmu ķēdēs, lai to droši sludināju, kā man pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Bet lai arī jūs zināt, kā man klājās, un ko es daru, tad visu jums stāstīs Tihikus, tas mīļais brālis un uzticīgais kalps iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'To es īpaši tādēļ pie jums esmu sūtījis, lai jūs varat zināt, kā mums klājās, un lai viņš jūsu sirdis iepriecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Miers lai ir tiem brāļiem un mīlestība ar ticību no Dieva, Tā Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Žēlastība lai ir ar visiem, kas bez mitēšanās mīļo mūsu Kungu Jēzu Kristu. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Pāvils un Timotejs, Jēzus Kristus kalpi, visiem tiem svētiem iekš Kristus Jēzus, kas ir Filipos, un arī tiem bīskapiem un palīgiem:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Es pateicos savam Dievam, cikkārt jūs pieminu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Arvienu ikkatrā lūgšanā par jums visiem ar līksmību lūgdamies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Jūsu biedrības dēļ pie evaņģēlija no pirmās dienas līdz šim laikam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'To īpaši cerēdams, ka Tas, kas to labo darbu iekš jums iesācis, to pabeigs līdz Jēzus Kristus dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Tā man piederas par jums visiem domāt, tādēļ ka es jūs turu savā sirdī, gan iekš savām saitēm, gan iekš savas aizbildināšanās un evaņģēlija apstiprināšanas, jūs visus, kam līdz ar mani ir daļa pie tās žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Jo Dievs ir mans liecinieks, cik ļoti es pēc jums visiem ilgojos ar Jēzus Kristus sirds mīlestību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Un par to es Dievu lūdzu, ka jūsu mīlestība jo dienas vairotos iekš atzīšanas un visas samanīšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Ka jūs varat pārbaudīt to, kas labs un kas ļauns, lai jūs esat skaidri un nepiedauzīgi uz Kristus dienu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Piepildīti ar taisnības augļiem, kas ir caur Jēzu Kristu, Dievam par godu un slavu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Bet es gribu, ka jūs zināt, brāļi, ka tas, kas man ir noticis, jo vairāk ir izdevies evaņģēlijam par pieaugšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Tā, ka manas saites ir tapušas zināmas iekš Kristus visā tiesas namā un visiem tiem citiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Un ka daudz no tiem brāļiem iekš Tā Kunga, caur manām saitēm iedrošināti, jo vairāk uzdrīkstas to vārdu runāt bez bailības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Citi gan sludina Kristu arī ar skaudību un strīdu, bet citi arī ar labu prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Kas to dara ar strīdu, tie Kristu sludina ne no skaidras sirds, un domā manām saitēm bēdas pielikt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Bet kas to dara no mīlestības, tie to dara zinādami, ka es esmu likts par evaņģēlija aizstāvētāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Kas par to? Taču Kristus top sludināts visādā vīzē, lai nu ar neskaidru, lai ar patiesīgu sirdi; par to es priecājos un priecāšos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Jo es zinu, ka tas man par svētību izdosies caur jūsu lūgšanu un caur Jēzus Kristus Gara palīdzību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Pēc manas sirsnīgas gaidīšanas un cerības, ka es nekādā lietā nepalikšu kaunā, bet ka ar visu drošību, tā kā arvien, tā arī tagad, Kristus taps paaugstināts pie manām miesām, vai caur dzīvību vai caur nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Jo mana dzīvība ir Kristus, un miršana man nes augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Bet ja miesā dzīvot manam darbam ir par labu, tad, ko man būs vēlēties, to nezinu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Jo es topu spiests abējādi, man gribās tapt atraisītam un būt pie Kristus, - jo tas ir ļoti daudz labāki;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Bet miesā palikt ir vēl jo vajadzīgi jūsu dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Un to ticēdams es zinu, ka es palikšu un pie jums visiem palikšu jums par pieaugšanu un ticības līksmību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Ka jūsu slavēšana iekš Kristus Jēzus par mani vairojās caur to, ka es atkal pie jums nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Tikai turaties cienīgi pēc Kristus evaņģēlija, ka es, vai nākdams un jūs redzēdams, vai pie jums nebūdams, varu dzirdēt, ka jūs stāvat vienā garā, vienā prātā kopā cīnīdamies par evaņģēlija ticību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Un ka jūs nekādā lietā netopat iztrūcināti no tiem pretiniekiem; jo tas tiem ir par zīmi, ka pazudīs, bet jums, ka tapsiet izglābti, un tas ir no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Jo jums tā žēlastība ir dota Kristus dēļ, ne vien uz Viņu ticēt, bet arīdzan par Viņu ciest, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'To pašu cīnīšanos cīnīdamies, ko pie manis esat redzējuši un tagad no manis dzirdat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Ja tad nu ir kāda pamācīšana iekš Kristus, ja tad ir mīlestības iepriecināšana, ja tad ir Tā Gara biedrība, ja tad ir sirds žēlastība un apžēlošana,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Tad darāt manu prieku pilnīgu, ka jums ir viens prāts, viena mīlestība, viena sirds un dvēsele;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Un nedariet nenieka strīdēdamies vai lieku godu meklēdami, bet pazemīgi turēdami cits citu augstāku par sevi pašu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Nevienam nebūs raudzīt uz to, kas pašam der, bet ikviens lai rauga arī uz to, kas der citiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Tāds prāts lai jums ir, kāds arī Kristum Jēzum bijis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Kas Dieva ģīmī būdams neturēja par laupījumu, Dievam līdzi būt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Bet Pats Sevi ir iztukšojis un kalpa ģīmi pieņēmis un tā kā cits cilvēks tapis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Un cilvēka kārtā atrasts Pats Sevi pazemoja, paklausīgs palicis līdz nāvei, līdz pat krusta nāvei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Tāpēc arī Dievs Viņu varen ir paaugstinājis un Viņam dāvinājis vārdu, kas iet pār visiem vārdiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Ka Jēzus vārdā būs ceļus locīt visiem tiem, kas ir debesīs un virs zemes un apakš zemes,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Un ikkatrai mēlei būs apliecināt, ka Jēzus Kristus ir Tas Kungs par godu Dievam, Tam Tēvam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Tad nu, mani mīļie, tā kā jūs allažiņ esat paklausīgi bijuši, ne tikai man klāt esot, bet nu daudz vairāk man klāt neesot, dzenaties ar bijāšanu un drebēšanu uz to, ka topat svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Jo Dievs ir, kas iekš jums padara gan gribēšanu, gan padarīšanu pēc Sava labā prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Dariet visu bez kurnēšanas un šaubīšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Ka esat bezvainīgi un skaidri, nenoziedzīgi Dieva bērni niknas un netiklas tautas vidū, kur jūs spīdat tā kā spīdekļi pasaulē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Pasargādami to dzīvības vārdu man par slavu uz Kristus dienu, ka es neesmu velti tecējis, nedz velti darbojies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Bet jebšu es topu upurēts klāt pie jūsu ticības upura un Dieva kalpošanas, taču es priecājos un līdz ar jums visiem priecājos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Un par to pašu priecājaties jūs arīdzan un priecājaties līdz ar mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Bet es ceru iekš Tā Kunga Jēzus, Timoteju drīz pie jums sūtīt, lai es arīdzan topu atspirdzināts, kad dabūšu zināt, kā jums klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Jo man nav neviena, kam būtu tik vienāds prāts ar mani, kas tik sirsnīgi par jums gādātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Jo tie visi meklē, kas pašiem, ne, kas Jēzum Kristum der.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Bet viņa pārbaudītu uzticību jūs zināt, ka viņš, tā kā tēvam dēls, līdz ar mani ir kalpojis pie evaņģēlija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Tad nu es ceru tūdaļ šo sūtīt, tiklīdz redzēšu, kā ar mani būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Bet to es tiešām ceru iekš Tā Kunga, ka es pats arīdzan drīz nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Bet es turēju par vajadzīgu pie jums sūtīt Epafroditu, to brāli un mana darba un cīnīšanās biedri, jūsu apustuli, kas manai vajadzībai kalpojis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Tādēļ ka viņš pēc jums visiem ilgojās un viņam rūpēja, ka jūs dzirdējuši, viņš esot nevesels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Un viņš arī gulēja uz miršanu, bet Dievs par viņu ir apžēlojies, tomēr nevien par viņu, bet arī par mani, ka man nenāktu noskumšana uz noskumšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Tad nu es viņu jo drīz esmu sūtījis, lai jūs to atkal redzēdami varat priecāties, un mana noskumšana top mazāka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Tad nu uzņemat viņu iekš Tā Kunga ar visu prieku, un tos tādus turat godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Jo Kristus darba dēļ viņš ir nācis tuvu pie nāves, nebēdādams par savu dzīvību, lai viņš man kalpotu jūsu vietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Un vēl, mani brāļi, priecājaties iekš Tā Kunga. To pašu jums vienmēr rakstīt, man nav par apnikšanu, bet jums par stiprināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Redziet tos suņus, redziet tos ļaunos strādniekus, redziet to sagraizīšanu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Jo mēs esam tā apgraizīšana, mēs, kas Dievam kalpojam garā un iekš Kristus Jēzus lielāmies un nepaļaujamies uz miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Jebšu man varētu būt arī paļaušanās uz miesu; ja citam kam šķiet, ka tas var paļauties uz miesu, es vairāk:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Es esmu apgraizīts astotā dienā, no Israēla tautas, no Benjamina cilts, Ebrejs no Ebrejiem, pēc bauslības farizejs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Pēc karstuma draudzes vajātājs, pēc tās taisnības, kas ir iekš bauslības, bezvainīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Bet kas man bija par mantu, to es Kristus dēļ esmu turējis par skādi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Jo patiesi es arī visu turu par skādi pret Kristus Jēzus, mana Kunga, atzīšanas augsto mantu; tādēļ es visu esmu pametis, un to turu par sūdu, lai es Kristu mantoju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Un iekš Viņa topu atrasts, ka man nav sava taisnība, tā, kas ir no bauslības, bet tā, kas ir caur Kristus ticību, proti tā taisnība, kas ir no Dieva caur ticību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Lai es atzīstu Viņu un Viņa augšāmcelšanās spēku un to līdz ciešanu ar Viņu un Viņam līdzīgs topu nāvē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Vai jel varētu nākt pie tās augšāmcelšanās no miroņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ne tā kā es to jau būtu dabūjis, vai jau būtu pilnīgs; bet es tam dzenos pakaļ, vai es to arī gan varētu satvert, tā kā arī es esmu satverts no Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Brāļi, man nešķiet, ka to jau esmu satvēris;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Bet to vien saku: aizmirsdams to, kas aiz manis, es stiepjos uz to, kas priekšā, es dzenos uz to mērķi, pēc tās goda maksas, uz ko Dievs debesīs aicina iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Visi nu, kas esam pilnīgi, lai šādu prātu turam; un ja jūs vēl par kaut ko citādi domājiet, tad Dievs arī to jums parādīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Bet tikai, pie kā esam tikuši, tai pašā ceļā lai staigājam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Dzenaties man pakaļ, brāļi, un lūkojiet uz tiem, kas tā staigā, ka mēs jums esam par priekšzīmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Jo daudzi staigā, par kuriem jums daudzkārt esmu sacījis, bet tagad saku arī raudādams, ka tie ir Kristus krusta ienaidnieki;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Viņu gals ir pazušana, viņu Dievs ir vēders, un viņu gods stāv viņu kaunā, viņu prāts nesās uz pasaules lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Bet mūsu dzīvošana ir debesīs, no kurienes mēs arī gaidām To Pestītāju, To Kungu Jēzu Kristu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Kas mūsu niecīgo miesu pārvērtīs, ka tā top līdzīga Viņa godības miesai, pēc tās spēcības, ar ko Viņš arī visas lietas var nolikt apakš Savām kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Tad nu, mani mīļie brāļi, manas sirds ilgošanās, mans prieks un mans kronis, - tā stāviet iekš Tā Kunga, jūs mīļie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Es lūdzu Evodiju un lūdzu Sintihu, lai ir vienis prātis iekš Tā Kunga;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Un tevi arīdzan lūdzu, tu mans īstais darba biedri: gādā par šīm sievām, kas līdz ar mani ir cīnījušās iekš evaņģēlija, tā kā arī Klements, un mani citi darba biedri, kuru vārdi ir dzīvības grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Priecājaties iekš Tā Kunga vienmēr; es saku atkal: priecājaties!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Lai jūsu lēnība top zināma visiem cilvēkiem; Tas Kungs ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Nebēdājaties par neko; bet jūsu lūgšanas visās lietās lai pie Dieva top zināmas caur piesaukšanu un pielūgšanu ar pateikšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Un tas Dieva miers, kas augstāks nekā visa saprašana, tas pasargās jūsu sirdis un jūsu domas iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Un vēl, brāļi, visu, kas patiesīgs, visu, kas godīgs, visu, kas taisns, visu, kas šķīsts, visu, kas mīlīgs, visu, kam laba slava, ja ir kāds labs tikums, un ja ko var teikt, - to liekat vērā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Ko jūs arī esat mācījušies un dabūjuši un dzirdējuši un redzējuši pie manis, to dariet; tad tas miera Dievs būs ar jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Bet es ļoti esmu priecājies iekš Tā Kunga, ka jūs nu atkal reiz esat uzsākuši gādāt par mani: par ko jūs arī esat gādājuši, bet tas laiks jums nav izdevies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Es to nesaku nekāda trūkuma dēļ; jo es esmu mācījies iztikt ar to, kas man ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Un es zinu zems būt, un es zinu augsts būt; visādi un visās lietās esmu mācījies, gan paēdis būt, gan izsalcis, pilnībā dzīvot un trūkumu ciest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Es spēju visas lietas iekš Tā, kas mani dara spēcīgu, proti iekš Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Tomēr jūs esat labi darījuši, ka jūs manas bēdas līdz ar mani esat nesuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Un arī jūs, Filipieši, zināt, ka no evaņģēlija sākuma laikiem, kad es no Maķedonijas esmu izgājis, neviena draudze nav ar mani biedrībā stāvējusi iekš došanas un ņemšanas, kā tikai jūs vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Jo arī, kad es biju Tesalonikā, jūs vienu un otru reizi man esat sūtījuši priekš manas vajadzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ne tā kā es to dāvanu meklēju, bet es meklēju to augli, kas no tās bagātīgi atlec priekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Bet es visu esmu dabūjis un man ir pār pārim; es esmu papilnam apgādāts ar to, ko jūs caur Epafroditu man sūtījuši, kā saldu smaržu, kā pieņēmīgu un Dievam patīkamu upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Bet mans Dievs piepildīs visu jūsu vajadzību pēc Savas bagātības iekš godības caur Kristu Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Bet mūsu Dievam un Tēvam lai ir gods mūžīgi mūžam. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Sveicinājiet ikvienu svētu iekš Kristus Jēzus; tie brāļi, kas pie manis, jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Visi tie svētie jūs sveicina un visvairāk tie no ķeizara nama.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jums visiem. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Pāvils, caur Dieva prātu Jēzus Kristus apustulis, un Timotejs, tas brālis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Tiem svētiem un ticīgiem brāļiem iekš Kristus Kolosās: žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Mēs pateicamies mūsu Kunga Jēzus Kristus Dievam un Tēvam vienmēr par jums lūgdami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Kad esam dzirdējuši par jūsu ticību iekš Kristus Jēzus un par to mīlestību uz visiem svētiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Tās cerības dēļ, kas jums ir nolikta debesīs, par ko jūs papriekš esat dzirdējuši caur to patiesības, proti evaņģēlija, vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Tas pie jums ir nācis, tā kā arī visā pasaulē, un nes augļus un aug, tā kā arī jūsu starpā no tās dienas, kad esat dzirdējuši un atzinuši Dieva žēlastību iekš patiesības;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Tā jūs arī esat mācījušies no Epafras, mūsu mīļā darba biedra, kas ir uzticīgs Kristus kalps priekš jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Kas mums arī stāstījis jūsu mīlestību Garā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Tāpēc arī mēs no tās dienas, kad to esam dzirdējuši, nemitējamies par jums Dievu lūgt un piesaukt, lai jūs topat piepildīti ar Viņa prāta atzīšanu iekš visas gudrības un garīgas saprašanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Lai jūs cienīgi staigājiet, Tam Kungam par patikšanu, iekš visa laba darba augļus nesdami un pieaugdami iekš Dieva atzīšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Ar visādu spēku spēcīgi būdami pēc Viņa godības varas iekš visas pacietības un lēnprātības ar līksmību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Pateikdamies Tam Tēvam, kas mūs ir darījis derīgus, līdz ar tiem svētiem mantību dabūt iekš gaismas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Tas mūs ir izrāvis no tumsības varas un pārstādījis Sava mīļā Dēla valstībā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Iekš kā mums ir tā pestīšana caur Viņa asinīm, tā grēku piedošana;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Tas ir Tā neredzamā Dieva ģīmis, visu radījumu pirmdzimtais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Jo iekš Viņa visas lietas ir radītas, kas debesīs un virs zemes, redzamās un neredzamās, lai gan troņi, lai gan kundzības, lai gan virsniecības, lai gan valdības, visas lietas ir radītas caur Viņu un uz Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Un Viņš ir priekš visām lietām, un visas lietas pastāv iekš Viņa;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Un Viņš ir tai miesai tā galva, proti tai draudzei; Viņš ir tas iesākums, tas pirmdzimtais no tiem mirušiem, ka Viņš starp visiem būtu tas pirmais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Jo Tam Tēvam ir paticis, ka iekš Viņa mājotu visa pilnība,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Un ka caur Viņu un uz Viņu visu salīdzinātu, gan to, kas virs zemes, gan to, kas debesīs, mieru darīdams caur Viņu, caur Viņa krusta asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Un jūs, kas citkārt bijāt sveši un savā prātā ienaidnieki iekš ļauniem darbiem, Tas tagad ir salīdzinājis');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Iekš Viņa cilvēcīgas miesas caur nāvi, ka Tas jūs nostādītu svētus un bezvainīgus un nenoziedzīgus Savā priekšā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Ja tik jūs paliekat ticībā stipri un pastāvīgi un nenovēršami no tā evaņģēlija cerības, ko jūs esat dzirdējuši, kas ir pasludināts visai radībai apakš debess. Šim es, Pāvils, esmu palicis par kalpu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Es nu priecājos savās ciešanās par jums, un piepildu atkal, kas vēl trūkst no Kristus bēdām, iekš savas miesas par Viņa miesu, kas ir tā draudze;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Tai es esmu palicis par kalpu, kā Dievs man to priekš jums ir novēlējis, lai Dieva vārdu pilnīgi pasludināju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'To noslēpumu, kas ir bijis paslēpts no mūžīgiem laikiem un no dzimumu dzimumiem, bet tagad skaidri ir parādīts Viņa svētiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Tiem Dievs ir gribējis darīt zināmu, kāda šim noslēpumam bagāta godība starp tautām; tas ir Kristus iekš jums, tā godības cerība,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'To mēs pasludinājam, paskubinādami ikvienu cilvēku un mācīdami ikvienu cilvēku iekš visas gudrības, lai mēs ikvienu cilvēku varam nostādīt pilnīgu iekš Kristus Jēzus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Par to es arī darbojos, cīnīdamies pēc Viņa spēcības, kas iekš manis stipri strādā ar spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Jo es gribu, ka jūs ziniet, cik liela cīnīšanās man ir par jums un par tiem, kas ir Laodiķeā, un par visiem, kas manu miesīgu vaigu nav redzējuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Lai viņu sirdis taptu iepriecinātas, un viņi taptu savienoti iekš mīlestības un bagātīgi piepildīti ar saprašanu, atzīt Dieva, Tā Tēva, un Kristus noslēpumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Iekš Tā ir apslēpta visa gudrības un atzīšanas bagātība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Bet to es saku, lai neviens jūs nepieviļ ar gudriem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Jo jebšu es neesmu klāt ar miesu, tomēr es jums esmu klāt ar garu, priecādamies un redzēdams jūsu kārtīgu dzīvošanu un jūsu stipru ticību uz Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Tad nu tā, kā jūs Kristu Jēzu, To Kungu, esat pieņēmuši, tā staigājiet iekš Viņa,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Iesakņoti un uztaisīti iekš Viņa un apstiprināti iekš ticības, tā kā jūs esat mācīti, augdami iekš tās ar pateicību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Pielūkojiet, ka neviens jūs neaplaupa caur pasaules gudrību un tukšu viltību pēc cilvēku stāstīšanām, pēc pasaules likumu sākumiem un ne pēc Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Jo iekš Viņa mājo visa dievības pilnība cilvēka miesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Un jūs esat pilnīgi iekš Viņa, kas ir visas varas un valdības galva;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'Iekš Viņa jūs arī esat apgraizīti ar apgraizīšanu ne rokām darītu, caur grēcīgā miesas prāta nolikšanu, caur Kristus apgraizīšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Līdz ar Viņu aprakti kristībā, iekš kā jūs arī esat uzmodināti caur to ticību, ko Dievs rada, kas Viņu no miroņiem ir uzmodinājis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Tas arī jūs, kad bijāt miruši noziegumos un savas miesas priekšādā, ir darījis līdz ar Viņu dzīvus, žēlīgi jums piedodams visus noziegumus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Un ir izdeldējis to parādu grāmatu, to likumu rakstu, kas mums bija pretī, un to ņēmis nost un piesitis pie krusta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Un ir nopostījis tās valdības un varas un tās klaji smieklā licis un Savas uzvarēšanas godu pār tām parādījis caur Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Tad nu lai neviens jūs netiesā par ēdienu, vai par dzērienu, vai par svētkiem vai jauniem mēnešiem, vai svētdienām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Tā bija to nākošo lietu ēna; bet tā īstā būšana ir Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Lai no tās goda maksas neviens jūs nenogriež, kas liekā pazemībā un eņģeļu kalpošanā pats sev patīk un uz to dzenās, ko viņš nav redzējis, un ir velti uzpūsts savā miesas prātā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Un neturās pie tās galvas, no kā visa miesa caur locekļiem un dzīslām palīdzību dabū un ir salaista un uzaug dievišķā augumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Ja nu jūs līdz ar Kristu tiem pasaules likumiem esat nomiruši, ko tad jūs, tā kā vēl pasaulē dzīvotu, topat apgrūtināti ar pavēlēm:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Neaizskar! Nebaudi! Neaiztiec!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '(Tam visam jāzūd, kad to lieto) - pēc cilvēku pavēlēm un mācībām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Tas gan liekās gudri dēļ tās pašu uzņemtās Dieva kalpošanas un pazemošanās un miesas netaupīšanas, tomēr nevienam nav par godu, bet tik par miesas prāta piepildīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Ja tad nu jūs ar Kristu esat augšāmcēlušies, tad meklējiet to, kas ir augšā, kur Kristus ir, sēdēdams pie Dieva labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Domājiet uz to, kas ir augšā, ne uz to, kas virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Jo jūs esat nomiruši, un jūsu dzīvība ir apslēpta ar Kristu iekš Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Kad nu Kristus, jūsu dzīvība, atspīdēs, tad arī jūs ar Viņu atspīdēsiet iekš godības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Tāpēc nonāvējiet savus locekļus, kas pasaulei pieder, maucību, nešķīstību, bezkaunību, ļaunu iekārošanu un mantas kārību, kas ir elku kalpošana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'To dēļ Dieva dusmība nāk pār tiem neticības bērniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Šajos grēkos arī jūs citkārt esat staigājuši, kad iekš tiem dzīvojāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Bet tagad arī jūs visu to noliekat: dusmību, bardzību, ļaunumu, Dieva zaimošanu, bezkaunīgus vārdus no savas mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Nemelojiet cits pret citu un novelkat to veco cilvēku ar viņa darbiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Un apvelkat to jauno, kas top atjaunots uz atzīšanu pēc sava radītāja ģīmja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Tur nav nedz Grieķis, nedz Jūds, nedz apgraizīšana, nedz priekšāda, nedz barbars, nedz Skitietis, nedz kalps, nedz svabadnieks: bet Kristus ir viss un iekš visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Tad nu apvelciet kā Dieva izredzētie, svētie un mīļotie, sirds žēlastību, laipnību, pazemību, lēnību, lēnprātību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Cits citu panesdami un cits citam piedodami, ja vienam ir ko sūdzēt pret otru, tā kā arī Kristus jums ir piedevis, tāpat arī jūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Un pār visu šo apvelciet mīlestību, kas ir pilnības saite.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Un Dieva miers lai valda jūsu sirdīs, uz ko jūs arī esat aicināti vienā miesā, un esat pateicīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Kristus vārds lai mīt bagātīgi jūsu starpā iekš visas gudrības, ka jūs paši mācaties un paskubinājaties ar svētām dziesmām un pateicības dziesmām un garīgām dziesmām, Tam Kungam mīlīgi dziedādami savās sirdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Un visu, ko jūs dariet ar vārdiem vai ar darbiem, to visu dariet Tā Kunga Jēzus vārdā, pateikdamies Dievam Tam Tēvam caur Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Jūs sievas, esiet paklausīgas saviem vīriem, tā kā pieklājās iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Jūs vīri, mīļojiet savas sievas un neesat bargi pret tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Jūs bērni, esiet paklausīgi tiem vecākiem visās lietās, jo tas Tam Kungam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Jūs tēvi, nekaitinājiet savus bērnus, ka tie nepaliek bailīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Jūs kalpi, paklausiet visās lietās tiem, kas pēc miesas jūsu kungi, ne priekš acīm kalpodami, tā kā gribēdami cilvēkiem patikt, bet sirds vientiesībā Dievu bīdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Un visu, ko jūs dariet, to dariet no sirds, tā kā Tam Kungam un ne cilvēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Zinādami, ka jūs no Tā Kunga dabūsiet par atmaksu to iemantošanu, jo jūs kalpojat Tam Kungam Kristum.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Bet kas nepareizi dara, tas dabūs, ko tas nepareizi ir darījis, un (tur) cilvēka vaigs netiek uzlūkots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Jūs kungi, kas ir pareizi un pēc tiesas, to dariet tiem kalpiem, zinādami, ka jums arīdzan Kungs ir debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Esiet pastāvīgi iekš lūgšanas un esiet nomodā iekš tās ar pateicību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Lūgdami turklāt arī par mums, ka Dievs mums gribētu atvērt tā vārda durvis, runāt Kristus noslēpumu, kā dēļ es arī esmu saistīts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Lai es to varu darīt zināmu, tā kā man pienākas runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Staigājiet iekš gudrības priekš tiem, kas ir ārā, laiku vērā ņemdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Jūsu valoda lai ir arvien mīlīga un ar sāli sālīta, ka jūs zināt ikvienam atbildēt, kā pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Kā man klājās, par to Tihikus jums ziņu dos, tas mīļais brālis un uzticīgais palīgs un amata biedrs iekš Tā Kunga,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Ko es tāpēc esmu sūtījis pie jums, lai es ziņu dabūtu, kā jums klājās, un lai tas jūsu sirdis iepriecinātu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Ar Onezimu, to uzticīgo un mīļo brāli, kas no jūsu draudzes; tie jums visu stāstīs, kā te iet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarks, mans cietuma biedrs, jūs sveicina, un Marks, Barnabas brāļa dēls, par ko jūs pavēles esat dabūjuši (kad tas pie jums nāks, tad to uzņemiet),');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Un Jēzus, ar pavārdu Justs, kas ir no apgraizīšanas. Šie vien ir mani darba biedri pie Dieva valstības, kas man bijuši par iepriecināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Epafra, kas ir no jūsu draudzes, Kristus kalps, jūs sveicina, vienmēr par jums cīnīdamies iekš lūgšanām, ka jūs pilnīgi un stipri pastāviet visā Dieva prātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Jo es tam dodu liecību, ka viņš karsti darbojās par jums un par tiem Laodiķeā un par tiem Hierapolē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Lūkas, tas ārsts, tas mīļais, un Demas jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Sveicinājiet tos brāļus Laodiķeā, un Nimfu un to Dieva draudzi viņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Un kad tā grāmata no jums ir lasīta, tad gādājiet, ka tā arī Laodiķeas draudzē top lasīta, un ka jūs arīdzan to grāmatu no Laodiķeas lasāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Un sakāt Arhipam: kopi to amatu, ko tu esi dabūjis iekš Tā Kunga, ka tu to pilnīgi izdari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Tā sveicināšana ar manu, Pāvila, roku. Pieminiet manas saites! Žēlastība lai ir ar jums! Āmen!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Pāvils un Silvans un Timotejs Tesaloniķiešu draudzei iekš Dieva Tā Tēva un Tā Kunga Jēzus Kristus: žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Mēs Dievam pateicamies vienmēr par jums visiem, jūs pieminēdami savās lūgšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Bez mitēšanās pieminēdami jūsu ticības darbu un jūsu mīlestības pūliņu un jūsu pastāvību iekš cerības uz mūsu Kungu Jēzu Kristu, mūsu Dieva un Tēva priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Zinādami, ka jūs, no Dieva mīļotie brāļi, esat izredzēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Jo mūsu evaņģēlijs ir bijis pie jums ne vien vārdos, bet arī spēkā un Svētā Garā un pilnā patiesībā: tā kā jūs zināt, kādi mēs esam bijuši pie jums jūsu labad.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Un jūs esat pakaļdzinušies mums un Tam Kungam un to vārdu uzņēmuši iekš daudz bēdām ar Svētā Gara prieku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Tā ka jūs esat palikuši par priekšzīmi visiem ticīgiem Maķedonijā un Akajā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Jo no jums Tā Kunga vārds ir izpaudies ne vien Maķedonijā un Akajā, bet arī visās malās jūsu ticība uz Dievu ir izgājusi, tā ka mums par to nevajag neko runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Jo tie paši sludina par mums, kādu ieiešanu mēs pie jums esam atraduši un kā jūs esat atgriezušies pie Dieva no tiem elkudieviem, kalpot Tam dzīvam un patiesam Dievam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Un gaidīt no debesīm Viņa Dēlu, ko Viņš uzmodinājis no miroņiem, Jēzu, kas mūs izpestījis no tās nākamās dusmības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Jo jūs paši zināt, brāļi, mūsu ieiešanu pie jums, ka tā nav bijusi veltīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Bet jebšu papriekš bijām cietuši un bijām nievāti Filipos, tā kā jūs zināt, tomēr esam bijuši droši iekš sava Dieva, runāt uz jums Dieva evaņģēliju iekš lielas cīnīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Jo mūsu pamācīšana nav no alošanās, nedz no neskaidrības, nedz no viltības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Bet tā, kā Dievs mūs ir cienīgus turējis, mums to evaņģēliju uzticēt, tā runājam, nekā lai cilvēkiem patīkam, bet Dievam, kas mūsu sirdis pārbauda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Jo mīksta mēle mums nekad nav bijusi, tā kā jūs zināt, nedz kaut ko esam darījuši mantas dēļ, - Dievs par to liecinieks;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Nedz godu meklēdami no cilvēkiem, nedz no jums, nedz no citiem, jebšu varējām savu svarīgo spēku rādīt kā Kristus apustuļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Bet esam bijuši lēnīgi jūsu vidū, tā kā zīdītāja savus bērnus glabā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Tāpat mēs pēc jums ilgodamies gribējām jums pasniegt ne vien Dieva evaņģēliju, bet arī savas dvēseles, tādēļ ka jūs mums esat palikuši mīļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Jo pieminiet, brāļi, mūsu darbu un pūliņu; jo dienām naktīm strādādami, lai nevienam no jums nebūtu par grūtumu, mēs jums esam sludinājuši Dieva evaņģēliju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Jūs esat liecinieki un Dievs, kā mēs pie jums, kas ticat, esam bijuši svēti un taisni un nenoziedzīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Tāpat jūs zināt, ka mēs ikvienu no jums tā kā tēvs savus bērnus, paskubinājām');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Un apliecinājām, ka jums cienīgi būs staigāt Dievam, kas jūs aicina pie Savas valstības un godības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Tāpēc arī Dievam bez mitēšanās pateicamies, ka jūs Dieva vārda mācību no mums dzirdēdami, to neesat pieņēmuši kā cilvēku vārdu, bet (tā kā tas patiesīgi ir) kā Dieva vārdu, kas arī spēcīgi strādā iekš jums, kas ticat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Jo jūs, brāļi, esat pakaļdzinušies tām Dieva draudzēm, kas ir Jūdu zemē iekš Kristus Jēzus, tāpēc ka jūs arīdzan to pašu esat cietuši no saviem cilts biedriem, kā arī viņi no tiem Jūdiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Tie arī To Kungu Jēzu ir nokāvuši un savus praviešus un mūs ir vajājuši un tie Dievam nepatīk un ir visiem cilvēkiem pretī;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Un tie mūs kavē uz pagāniem runāt, ka šie top izglābti, un tā viņi arvien savus grēkus piepilda. Bet tā dusmība jau pār viņiem nākusi viņus nobeigt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Bet mēs, brāļi, kādu brīdi no jums šķirti pēc vaiga, ne pēc sirds, jo vairāk esam steigušies ar gaužu ilgošanos redzēt, jūsu vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Tādēļ mēs pie jums esam gribējuši nākt (es Pāvils) vienu un otru reizi; bet sātans mūs aizkavējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Jo kas ir mūsu cerība vai prieks vai goda kronis? Vai arī ne jūs mūsu Kunga Jēzus Kristus priekšā pie Viņa atnākšanas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Jo jūs esat mūsu gods un prieks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Tādēļ to ilgāk nepanesdami, esam apņēmušies, vieni paši palikt Atēnā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Un esam sūtījuši Timoteju, savu brāli un Dieva kalpu, savu darba biedru iekš Kristus evaņģēlija, jūs apstiprināt un paskubināt iekš jūsu ticības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Ka neviens nešaubās šinīs bēdās; jo jūs paši zināt, ka tās mums ir noliktas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Jo kad pie jums bijām, mēs jums papriekš sacījām, ka bēdas mums būs jācieš, tā kā tas arī noticis un kā jūs to zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Tādēļ arīdzan es to ilgāk nepanesdams, viņu esmu sūtījis, lai es no jūsu ticības dabūtu zināt, vai gan tas kārdinātājs jūs nav kārdinājis un mūsu darbs nav palicis veltīgs?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Bet tagad, kad Timotejs no jums ir nācis pie mums un mums labas vēstis nesis par jūsu ticību un mīlestību, un ka jūs arvienu mūs labā piemiņā turat, kārodami mūs redzēt, itin kā arī mēs jūs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Tādēļ, brāļi, mēs esam iepriecināti par jums iekš visām savām bēdām un raizēm caur jūsu ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Jo tagad mēs atdzīvojamies, kad jūs pastāvat iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Jo kādu pateicību mēs Dievam par jums varam atdot par visu šo prieku, ar ko priecājamies jūsu dēļ mūsu Dieva priekšā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Naktīm dienām ļoti gauži lūgdamies, lai varētu jūsu vaigu redzēt un jūsu ticības trūkumu piepildīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Bet pats mūsu Dievs un Tēvs un mūsu Kungs Jēzus Kristus lai pašķir mūsu ceļu pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Bet jums lai Tas Kungs dod augt un lai jūs dara pār pārim pilnīgus iekš mīlestības savā starpā un uz visiem, tā kā arī mēs esam uz jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Ka Viņš jūsu sirdis stiprinātu, būt nenoziedzīgiem un svētiem mūsu Dieva un Tēva priekšā, kad mūsu Kungs Jēzus Kristus atnāks ar visiem Saviem svētiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Tad nu vēl, brāļi, jūs lūdzam un paskubinājam iekš Tā Kunga Jēzus, kā jūs no mums jau esat dzirdējuši, kā jums būs staigāt Dievam par patikšanu, lai jūs jo dienas jo vairāk pieņematies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Jo jūs zināt, kādas pavēles mēs jums esam devuši caur To Kungu Jēzu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Jo šis ir Dieva prāts, ka jūs topat svēti, ka jums būs atrauties no maucības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Ka ikvienam būs zināt, sev draugu mantot iekš svētīšanas un goda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Ne kārības sērgā, kā arī tie pagāni, kas Dievu nepazīst;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Ka neviens savam brālim pāri nedara, nedz mantas dēļ to piekrāpj kādā darīšanā, jo Tas Kungs ir atriebējs par visu to, tā kā mēs jums arī jau esam sacījuši un apliecinājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Jo Dievs mūs nav aicinājis uz nešķīstību, bet ka topam svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Tad nu, kas ir nicinātājs, tas nenicina kādu cilvēku, bet Dievu, kas arī Savu Svēto Garu jums ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Bet jums nevajag, ka es par to brāļu mīlestību rakstu; jo jūs paši esat Dieva mācīti, cits citu mīlēt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Un jūs to arī darāt visiem brāļiem, kas ir pa visu Maķedoniju; bet mēs jūs paskubinājam, brāļi, jo dienas jo vairāk pieņemties');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Un turēt par godu, klusi dzīvot un savus darbus darīt un savām rokām strādāt, tā kā mēs jums esam pavēlējuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Ka jūs godīgi staigājat priekš tiem, kas ir ārā, un ka jums cita nevajag.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Bet, brāļi, es jums negribu slēpt par tiem, kas ir aizmiguši, ka jūs nenoskumstat tā kā tie citi, kam nav cerības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Jo ja mēs ticam, ka Jēzus ir miris un augšāmcēlies, tāpat arī Dievs tos aizmigušos caur Jēzu atvedīs līdz ar Viņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Jo to mēs jums sakām caur Tā Kunga vārdu, ka mēs, kas dzīvojam un atliekam uz Tā Kunga atnākšanu, tiem aizmigušiem nenāksim priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Jo pats Tas Kungs nāks zemē no debesīm ar kliegšanu, ar liela eņģeļa balsi un ar Dieva bazūni, un tie iekš Kristus mirušie uzcelsies papriekš,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Pēc tam mēs, kas dzīvojam un esam atlikuši, tapsim aizrauti līdz ar tiem iekš padebešiem Tam Kungam pretī gaisā; un tā mēs būsim arvien pie Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Tad nu iepriecinājaties savā starpā ar šiem vārdiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Bet par tiem laikiem un brīžiem, brāļi, nevajag jums rakstīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Jo jūs paši it labi zināt, ka Tā Kunga diena nāks tāpat kā zaglis naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Jo kad tie sacīs: miers ir un drošība, tad tā samaitāšana piepeši nāks pār tiem, kā bērnu sāpes pār grūtu sievu, un tie neizbēgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Bet jūs, brāļi, neesiet iekš tumsības, ka šī diena kā zaglis jūs sagrābj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Jūs visi esat gaismas bērni un dienas bērni; mēs neesam ne nakts ne tumsības bērni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Tad nu lai mēs neguļam, tā kā tie citi, bet lai esam nomodā un skaidrā prātā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Jo tie, kas guļ, guļ naktī; un kas piedzeras, tie piedzeras naktī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Bet mums, kas esam dienas bērni, būs skaidrā prātā būt un apvilkt ticības un mīlestības bruņas un par bruņu cepuri pestīšanas cerību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Jo Dievs mūs nav nolicis uz dusmību, bet uz mūžīgas dzīvības panākšanu caur mūsu Kungu Jēzu Kristu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Kas par mums ir miris, ka mums, vai esam nomodā, vai aizmiguši, līdz ar Viņu būs dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Tāpēc pamācāties savā starpā un uztaisiet cits citu, tā kā arī jau darāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Bet mēs jūs lūdzam, brāļi, ka jūs tos atzīstat, kas jūsu starpā strādā, un savus priekšniekus iekš Tā Kunga, un kas jūs pamāca.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Un turat tos jo vairāk mīļus viņu darba dēļ; turat mieru savā starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Bet mēs jūs lūdzam, brāļi, pamāciet netiklos, ieprieciniet bailīgos, panesiet vājos, esiet lēnprātīgi pret visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Pielūkojiet, ka neviens nevienam neatmaksā ļaunu ar ļaunu, bet arvien dzenaties uz labu, tā savā starpā, kā pret visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Priecājaties vienmēr.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Lūdziet Dievu bez mitēšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Pateicieties Dievam visās lietās: jo tas ir Dieva prāts iekš Kristus Jēzus pie jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Nenoslāpējiet to Garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Nenicinājiet praviešu mācības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Pārbaudiet visu; to, kas labs, paturiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Atraujaties no visa, kas liekās ļauns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Bet pats tas miera Dievs lai jūs svētī caur caurim, un viss jūsu gars un dvēsele un miesa lai bezvainīgi top pasargāti uz mūsu Kunga Jēzus Kristus atnākšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Uzticīgs ir Tas, kas jūs aicina, - Tas to arī darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Brāļi, lūdziet par mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Sveicinājiet visus brāļus ar svētu skūpstīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Es jums piekodināju no Dieva puses, lai šī grāmata top lasīta priekš visiem svētiem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jums. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pāvils un Silvans un Timotejs Tesaloniķiešu draudzei iekš Dieva, mūsu Tēva, un iekš Tā Kunga Jēzus Kristus:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Mums pienākas Dievam vienmēr pateikties par jums, brāļi, tā kā tas ir pareizi, tādēļ ka jūsu ticība augumā aug un ka mīlestība jūsu starpā vairojās pie ikviena no jums;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Tā ka mēs paši jūsu dēļ teicamies Dieva draudzēs par jūsu pastāvību un ticību iekš visām jūsu vajāšanām un iekš tām bēdām, ko jūs panesat, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Kas zīmējās uz Dieva taisno tiesu, ka jūs paliekat cienīgi, Dieva valstību mantot, par ko jūs arī ciešat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Tā ka tas ir pēc Dieva taisnības, jūsu bēdinātājiem atmaksāt ar bēdām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Un jums, kas topat apbēdināti, dot atvieglošanu līdz ar mums, kad Tas Kungs Jēzus parādīsies no debesīm ar Sava spēka eņģeļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Ar uguns liesmām sodīt tos, kas Dievu nepazīst un kas ir nepaklausīgi mūsu Kunga Jēzus Kristus evaņģēlijam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Tie par sodību cietīs mūžīgu samaitāšanu no Tā Kunga vaiga un no Viņa spēka godības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Kad Viņš nāks viņā dienā, lai taptu pagodināts iekš Saviem svētiem un apbrīnots iekš visiem tiem, kas ticējuši, (jo mūsu liecībai pie jums tapa ticēts.)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Tādēļ mēs arī vienmēr lūdzam par jums, lai mūsu Dievs jūs dara cienīgus, ka dabūjat, uz ko esat aicināti, un lai Viņš jūs dara pilnīgus visā labā prātā un ticības darbā ar spēku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Lai mūsu Kunga Jēzus Kristus vārds top pagodināts iekš jums, un jūs iekš Viņa, pēc mūsu Dieva un Tā Kunga Jēzus Kristus žēlastības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Bet dēļ mūsu Kunga Jēzus Kristus atnākšanas un dēļ mūsu sapulcināšanas pie Viņa mēs, brāļi, jūs lūdzam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Ka jūs netopat drīz prātā šaubīti nedz iztrūcināti, ne caur garu, ne caur vārdu, ne caur grāmatu, tā kā no mums būtu rakstīts, ka Tā Kunga diena esot klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Lai neviens jūs nekādā vīzē nepieviļ; jo tā nenāks, pirms tā atkāpšanās nebūs nākusi un tas grēka cilvēks, tas pazušanas dēls, nebūs parādījies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Kas turas pretī un paaugstinājās pār visu to, kas Dievs saucams, un kas ir Dieva kalpošana, tā ka viņš Dieva namā sēž kā Dievs, izrādīdamies, ka viņš esot Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Vai jūs vairs nepieminiet, ka es vēl pie jums būdams to jums esmu sacījis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Un nu jūs zināt, kas aizkavē, tiekams viņš parādās savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Jo tas netaisnības noslēpums jau ir spēkā, tikai ka tam, kas viņu līdz šim aizkavē, vēl būs tapt atņemtam nost.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Un tad parādīsies tas netaisnais, ko Tas Kungs nomaitās ar savas mutes garu un izdeldēs, kad atspīdēs viņa atnākšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Šā (tā netaisnā) atnākšana notiek pēc sātana spēka ar visādu viltības varu un viltības zīmēm un brīnumiem');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'Un ar visādu pievilšanu uz netaisnību pie tiem, kas pazūd; tādēļ ka tie patiesības mīlestību nav pieņēmuši, ka taptu svēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Un tādēļ Dievs tiem sūtīs spēcīgu maldīšanās garu, ka tie tic meliem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Lai top sodīti visi, kas patiesībai nav ticējuši, bet kam bijusi patikšana pie netaisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Bet mums pienākas vienmēr Dievam pateikties par jums, no Tā Kunga mīļotie brāļi, ka Dievs no iesākuma jūs izredzējis uz pestīšanu, lai caur to Garu tiekat svēti un ticat patiesībai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Uz to Viņš jūs ir aicinājis caur mūsu evaņģēliju, lai panākat mūsu Kunga Jēzus Kristus godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Tad nu, brāļi, pastāviet un turiet tās mācības, ko esat mācījušies tā caur mūsu vārdu, kā caur mūsu grāmatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Bet pats mūsu Kungs Jēzus Kristus un mūsu Dievs un Tēvs, kas mūs ir mīlējis un devis mūžīgu iepriecināšanu un labu cerību iekš žēlastības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Tas lai jūsu sirdis iepriecina un lai jūs stiprina iekš visāda laba vārda un darba.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Beidzot, brāļi, lūdziet par mums, lai Tā Kunga vārds turpina savu gaitu un top godāts, tā kā arī pie jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Un lai mēs topam atpestīti no tiem netikliem un ļauniem cilvēkiem; jo ticība netīk visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Bet uzticīgs ir Tas Kungs, kas jūs stiprinās un pasargās no tā ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Un mēs ceram no jums iekš Tā Kunga, ka jūs, ko mēs jums pavēlam, gan dariet, gan darīsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Bet Tas Kungs lai sataisa jūsu sirdis uz Dieva mīlestību un uz Kristus pacietību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Mēs jums pavēlam, brāļi, mūsu Kunga Jēzus Kristus vārdā, atstāties no ikviena brāļa, kas staigā netikli un ne pēc tās mācības, ko tas no mums ir dabūjis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Jo jūs paši zināt, kā piederās mums pakaļ dzīties; jo mēs jūsu starpā neesam netikli turējušies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Nedz esam maizi ēduši pie kāda bez maksas, bet iekš darbošanās un pūlēšanās naktīm dienām strādādami, ka nevienu no jums neapgrūtinātu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Ne ka mums nebūtu brīv, bet lai paši sevi jums dotu par priekšzīmi mums pakaļdzīties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Jo kad bijām pie jums, to jums esam pavēlējuši, ka, ja kas negrib strādāt, tam arī nebūs ēst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Jo mēs dzirdam, ka citi jūsu starpā netikli staigā neko nestrādādami, bet nedarbus darīdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Bet tiem tādiem mēs pavēlam un tos paskubinājam caur mūsu Kungu Jēzu Kristu, lai tie klusā garā strādā un ēd savu pašu maizi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Bet jūs, brāļi, nepiekūstiet labu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Bet ja kas mūsu vārdiem šinī grāmatā nepaklausa, to iezīmējat, un nejaucaties ar to, lai tas top apkaunots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Un neturiet to kā ienaidnieku, bet pamāciet to kā brāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Bet pats tas miera Kungs lai jums dod mieru vienmēr un visādi. Tas Kungs lai ir ar jums visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Tā sveicināšana ar manu paša, Pāvila, roku; šī ir tā zīme iekš ikkatras grāmatas. Tā es rakstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jums visiem. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Pāvils, Jēzus Kristus apustulis, pēc Dieva, mūsu Pestītāja un Tā Kunga Kristus Jēzus, mūsu cerības, pavēles');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timotejam, savam īstam dēlam iekš ticības: žēlastība, apžēlošana, miers no Dieva, mūsu Tēva, un no Jēzus Kristus, mūsu Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Itin kā es tevi esmu lūdzis Efesū palikt, kad es gāju uz Maķedoniju, lai tu kādus paskubinātu, nemācīt nekādu citu mācību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Nedz cienīt pasakas un bezgalīgus cilts rakstus, kas vairāk ceļ jautāšanas nekā Dieva draudzi kopj ticībā, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Bet tās mācības gala mērķis ir mīlestība no šķīstas sirds un labas apziņas un bezviltīgas ticības;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'No tā kādi ir noklīduši un griezušies uz tukšām valodām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Gribēdami būt bauslības mācītāji, tie neprot, nedz ko saka, nedz ko droši liecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Bet mēs zinām, ka bauslība ir laba, ja kas pēc tās pareizi turas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'To zinādams, ka bauslība nav iecelta taisnam, bet netaisniem un pārgalvīgiem, bezdievīgiem un grēciniekiem, nesvētiem un negantiem, tēva un mātes kāvējiem, slepkavām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Mauciniekiem, tiem, kas pie vīriešiem guļ, cilvēku zagļiem, melkuļiem, tiem, kas nepatiesi zvēr, un ja vēl kas tai veselīgai Dieva mācībai ir pretim,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Pēc tā svētā Dieva godības pilnā evaņģēlija, kas man ir uzticēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Un es pateicos Tam, kas mani darījis spēcīgu, mūsu Kungam Kristum Jēzum, ka Tas mani turējis par uzticīgu un iecēlis šinī amatā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Kaut gan iepriekš biju zaimotājs un vajātājs un varas darītājs, bet man žēlastība ir notikusi, jo es nezinādams to esmu darījis iekš neticības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Tomēr mūsu Kunga žēlastība jo pilnīga ir bijusi pie manis ar ticību un mīlestību, kas ir iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Tas ir patiesīgs un augsti pieņemams vārds, ka Kristus Jēzus ir nācis pasaulē grēciniekus izglābt, starp kuriem es esmu tas lielākais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Bet tādēļ man žēlastība ir notikusi, lai it īpaši pie manis Jēzus Kristus parādītu visu lēnprātību tiem par priekšzīmi, kas iekš Viņa ticēs uz mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Bet Tam mūžīgam, neiznīcīgam Ķēniņam, Tam neredzamam vienīgam gudram Dievam lai ir gods un slava mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Šo pavēli es tev lieku pie sirds, mans dēls Timotej, pēc tiem praviešu vārdiem, kas par tevi iepriekš ir sacīti, lai tu pēc tiem karo to labo karošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Turēdams ticību un labu zināmu sirdi, ko citi atmetuši un ticības lietās kā sadragāta laiva postā gājuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Starp tiem ir Imenejs un Aleksandrs, ko esmu nodevis sātanam, lai tie kļūst pārmācīti, ka Dievu vairs nezaimo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Tad nu es pamācu pār visām lietām, lai notiek lūgšanas, piesaukšanas, aizlūgšanas, pateikšanas par visiem cilvēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Par ķēniņiem un visiem, kas ir augstā kārtā, lai mēs mierīgi un klusi dzīvojam visā dievbijāšanā un godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Jo tas ir labi un patīkami Dieva, mūsu Pestītāja, priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Kas grib, ka visi cilvēki top izglābti un nāk pie patiesības atzīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Jo viens Dievs ir un viens vidutājs starp Dievu un cilvēkiem, tas cilvēks Kristus Jēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Kas Sevi pašu ir nodevis par atpirkšanas maksu priekš visiem par liecību savā laikā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Uz ko es esmu iecelts par pasludinātāju un apustuli, (es saku patiesību iekš Kristus un nemeloju), par mācītāju pagāniem ticībā un patiesībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Tad nu es gribu, lai vīri Dievu pielūdz visās vietās, paceldami svētas rokas bez dusmības un šaubīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Tāpat lai arī sievas pieklājīgās drēbēs kaunīgi un godīgi ģērbjas, ne ar sapītām bizēm nedz ar zeltu nedz ar pērlēm nedz ar dārgām drēbēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Bet ar labiem darbiem, (kā tas sievām klājās, kas pie Dieva kalpošanas turas).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Sieva klusībā lai mācās ar visu paklausīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Bet sievai es nepieļauju mācīt nedz pār vīru valdīt, bet viņai būs turēties klusu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Jo Ādams papriekš ir radīts, pēc tam Ieva;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Un Ādams nav pievilts, bet sieva ir pievilta un kritusi pārkāpšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Bet tā taps izglābta caur bērnu dzemdēšanu, ja viņa paliek ticībā un mīlestībā un dzenās pēc svētas dzīvošanas ar godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Tas ir patiesīgs vārds: ja kas iekāro bīskapa amatu, tas iekāro teicamu darbu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Tad nu bīskapam pienākas būt nenoziedzīgam, vienas sievas vīram, sātīgam, prātīgam, godīgam, kas labprāt dod mājas vietu, un kas māk mācīt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Kas nav dzērājs, ne rējējs, nedz negodīgas peļņas dzinējs, bet lēnīgs, ne strīdīgs, ne naudas kārīgs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Kas savu namu labi valda, kam bērni, kas paklausa ar visu godu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(Bet ja kas savu paša namu nezin valdīt, kā tas gādās par Dieva draudzēm?)');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Ne tāds, kas kristīgu ticību tikko uzņēmis, lai neuzpūšas un neiekrīt zaimotāja tiesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Bet viņam vajag arī labas liecības no tiem, kas ārā, ka neiekrīt nievāšanā un zaimotāja valgos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Tāpat arī draudzes kopējiem būs būt godīgiem, kam nav divējādas mēles, ne vīna plītniekiem, nedz negodīgas peļņas dzinējiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Kas ticības noslēpumu tur iekš šķīstas zināmas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Un šiem arīdzan būs papriekš tapt pārbaudītiem, pēc lai tie kalpo, ja tie ir bezvainīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Tāpat arī sievām būs būt godīgām, ne mēlnesēm, bet sātīgām, uzticīgām visās lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Draudzes kopējiem būs būt vienas sievas vīriem, kas savus bērnus un savu namu labi valda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Jo kas labi kalpojuši, tie pelnās labu pakāpi un daudz drošības iekš ticības, kas ir iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'To es tev rakstu, cerēdams it drīz nākt pie tevis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Bet ja es aizkavētos, lai tu zini, kā pienākas turēties Dieva namā, kas ir tā dzīvā Dieva draudze, tās patiesības pīlārs un pamats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Un teicami liels ir tas dievbijāšanas noslēpums: Dievs ir parādīts miesā, taisnots garā, skatīts no eņģeļiem, sludināts tautām, ticēts pasaulē, uzņemts godībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Bet Tas Gars skaidri saka, ka nākamos laikos citi atkāpsies no ticības, klausīdami viltīgus garus un velnu mācības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Kas viltīgi melus runā, kam pašu zināma sirds kā ar dedzekli iezīmēta,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Kas aizliedz laulībā iedoties, pavēl noturēties no barībām, ko Dievs radījis, lai tie ticīgie un tie kas patiesību atzinuši, tās saņem ar pateicību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Jo ikkatra Dieva radīta lieta ir laba, un nekas nav atmetams, kas ar pateicību top ņemts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Jo tas top svētīts caur Dieva vārdu un lūgšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Kad tu šās lietas tiem brāļiem liksi priekšā, tad tu būsi labs Jēzus Kristus kalps, uzaudzināts iekš ticības un labas mācības vārdiem, uz ko tu esi dzinies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Bet tās nesvētās un nelietīgās pasakas atmeti un darbojies pats iekš dievbijāšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Jo tā miesīgā darbošanās maz ko der; bet dievbijāšana der pie visām lietām; un tai ir šās tagadējās un tās nākošās dzīvošanas apsolīšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Tas ir patiesīgs un augsti pieņemams vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Jo par to mēs arī strādājam un topam nievāti, ka esam cerējuši uz to dzīvo Dievu, kas ir visu cilvēku, visvairāk ticīgo Pestītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Šās lietas pavēli un māci.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Lai neviens nenicina tavu jaunību, bet topi tiem ticīgiem par priekšzīmi iekš mācības, iekš dzīvošanas, iekš mīlestības, iekš ticības, iekš šķīstības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Pastāvi iekš lasīšanas, paskubināšanas, mācīšanas, tiekams es nāku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Kopi to dāvanu, kas ir iekš tevis, kas tev caur praviešu vārdiem ir dota, kad tie vecaji tev rokas uzlika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Par to gādā, pie tā palieci, ka tava pieaugšana top redzama visās lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Ņem vērā sevi pašu un to mācību, pastāvi šinīs lietās; jo to darīdams gan sevi pašu izglābsi, gan tos, kas tevi klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Vecu nerāj, bet pamāci kā tēvu, jaunākus kā brāļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Vecākas sievas kā mātes, jaunākas kā māsas, iekš visas šķīstības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Godā tās atraitnes, kas ir īsteni atraitnes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Bet ja kādai atraitnei ir bērni jeb bērnu bērni, tādas lai papriekš mācās savā pašu namā dievbijīgi dzīvot un atlīdzināt, ko no tiem vecākiem dabūjušas; jo tas ir labi un patīkami Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Bet kura ir īsta atraitne un itin viena palikusi, tā savu cerību likusi uz Dievu un paliek lūgšanās un Dieva piesaukšanās naktīm dienām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Bet kura uz kārību dzenās, tā dzīva būdama ir nomirusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Un to pavēli, lai tās turas bezvainīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Bet ja kas savus piederīgos un visvairāk savu saimi neapgādā, tas ticību ir aizliedzis un ir sliktāks par neticīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Atraitne lai top izvēlēta ne jaunāka kā sešdesmit gadus, kas bijusi viena vīra sieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Kurai labu darbu liecība top dota, ja tā bērnus uzaudzinājusi, ja tā labprāt svešiniekus uzņēmusi, ja tā svētiem kājas mazgājusi, ja tā apbēdinātiem palīgā nākusi, ja tā pēc ikviena laba darba dzinusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Bet jaunākas atraitnes atmet; jo kad tās vēlīgas(pārgalvīgas) tapušas - Kristum pretī, tad tās grib iet pie vīra,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Un tām ir vaina, ka tās to pirmo ticību pārlauzušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Turklāt arīdzan tās ir slinkas, mācās apkārt iet pa mājām; un ne vien slinkas, bet arīdzan plukšķes, nedarbus darīdamas, runādamas, kas neklājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Tad nu es gribu, ka tās jaunās iet pie vīra, bērnus dzemdē, namu valda un pretiniekam nedod nekāda iemesla uz nievāšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Jo citas jau ir griezušās sātanam pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Ja kādam ticīgam jeb kādai ticīgai ir atraitnes, tad lai tie tām nāk palīgā, un lai draudze netop apgrūtināta, ka tā tām īstenām atraitnēm var nākt palīgā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Tos vecajus, kas labi valda, turi divkārtīgā godā, visvairāk tos, kas strādā iekš vārda un mācīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Jo tas raksts saka: vērsim, kas labību izmin, tev nebūs aizsiet purnu, un: strādniekam sava alga pienākas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Pret vecaju neuzņem sūdzības bez diviem vai trim lieciniekiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Tos, kas apgrēkojās, pārmāci visu priekšā, lai arī tie citi bīstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Es piekodināju Dieva un Tā Kunga Jēzus Kristus un to izredzēto eņģeļu priekšā, lai tu šās lietas turi, neko nedarīdams ne pēc ienaida, ne pēc draudzības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Rokas nevienam neuzliec ātri, un nepinies ar svešiem grēkiem; sevi pašu glabā šķīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Un nedzer vairs ūdeni vien, bet ņem maķenīt vīna, tavas pasirds(kuņģa) labad un tavas dažādas vājības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Citu cilvēku grēki jau zināmi, pirms tie vēl priekš tiesas nāk; bet citu ļaužu grēki pēc top zināmi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Tāpat arī tie labie darbi jau ir zināmi; un kas vēl nav, tie nevar palikt apslēpti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Visiem, kas ir kalpi apakš jūga, tiem būs savus kungus visā godā turēt, lai Dieva vārdu un mācību nezaimo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Bet tiem, kam ir ticīgi kungi, nebūs viņus nicināt, tāpēc ka šie ir brāļi, bet jo vairāk kalpot, tāpēc ka šie, kas šo labumu dabū, ir ticīgi un mīlēti; to māci un pavēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ja kas citu mācību māca un nenāk pie mūsu Kunga Jēzus Kristus veselīgiem vārdiem un pie dievbijāšanas mācības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Tas ir uzpūsts un nezin nenieka, bet vārgst iekš jautāšanām un vārdu ķildām, no kā ceļas skaudība, bāršanās, zaimošanas, ļaunas domas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Nelietīgas apjautāšanas tādiem, kam prāti sajaukti, kam patiesība zudusi, kam šķiet, dievbijāšanu esam mantas pelnīšanu: - atkāpies no tādiem!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Bet tā ir liela mantošana, ja kas ir dievbijīgs un pieticīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Jo mēs nenieka neesam ienesuši pasaulē, tad ir zināms, ka mēs arī nenieka nevaram iznest.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Bet kad mums sava barība un apģērbs, tad lai mums pietiek.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Bet kas grib bagāts tapt, tie krīt kārdināšanā un valgā un daudz bezprātīgās un nelabās kārībās, kas cilvēkus gāž samaitāšanā un pazušanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Jo naudas kārība ir visa ļaunuma sakne; pēc tās dzīdamies daži ir nomaldījušies no ticības un paši ar daudz sāpēm sadūrušies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Bet tu, Dieva cilvēks, bēdz no šīm lietām; dzenies pēc taisnības, dievbijāšanas, ticības, mīlestības, pacietības, laipnības;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Cīnies to labo ticības cīnīšanos, sagrāb to mūžīgo dzīvību, uz ko tu arīdzan esi aicināts un esi apliecinājis labu liecību daudz liecinieku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Es tev pavēlu Dieva priekšā, kas visu dara dzīvu, un Jēzus Kristus priekšā, kas apakš Poncius Pilatus apliecinājis to labo liecību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Šo bausli turēt neaptraipītu, nenicinātu līdz mūsu Kunga Jēzus Kristus atspīdēšanai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Ko savā laikā parādīs tas svētais un vienīgi varenais, tas visu ķēniņu Ķēniņš un visu kungu Kungs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Kam vien ir nemirstība, kas dzīvo nepieejamā gaišumā, ko neviens cilvēks nav redzējis, nedz var redzēt. Tam lai ir gods un mūžīga vara! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Tiem bagātiem šinī pasaulē pavēli, lai tie augsti neturas, nedz cerē uz to nepastāvīgo bagātību, bet uz To dzīvo Dievu, kas mums visas lietas bagātīgi pasniedz par atspirgšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Lai tie labu dara, bagāti top iekš labiem darbiem, labprāt izdala, ir devīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Lai sev mantas krāj par labu pamatu uz nākamo laiku, ka tie dabū mūžīgo dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Ak Timotej, glabā to uzticēto mantu, atraudamies no tām nesvētām valodām un tukšām strīdu runām, kas ceļas no tās gudrības, ko par nepatiesu tā sauc;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Pie kuras turēdamies daži nomaldījušies no ticības. Žēlastība lai ir ar tevi! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pāvils, caur Dieva prātu Jēzus Kristus apustulis, aicināts sludināt to dzīvību iekš Kristus Jēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timotejam, tam mīļam dēlam: žēlastība, apžēlošana, miers no Dieva, Tā Tēva, un no Kristus Jēzus, mūsu Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Es pateicos Dievam, kam kalpoju no tēvu tēviem ar skaidru zināmu sirdi, tā kā es bez mitēšanās tevi savās lūgšanās pieminu naktīm dienām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Ilgodamies tevi redzēt, pieminēdams tavas asaras, lai es topu piepildīts ar prieku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Kad pieminu tavu bezviltīgo ticību, kas jau papriekš ir mājojusi iekš tavas mātes mātes Loidas un iekš tavas mātes Eunikas, un es stipri ceru, ka arī iekš tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Tāpēc es tev atgādināju, atkal pamodināt to Dieva žēlastības dāvanu, kas ir iekš tevis caur manu roku uzlikšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Jo Dievs mums nav devis bailības garu, bet spēka un mīlestības un savaldības garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Tad nu nekaunies par mūsu Kunga liecību, nedz par mani, Viņa saistīto; bet ciet līdz to grūtumu par evaņģēliju pēc Dieva spēka,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Kas mūs izglābis un aicinājis ar svētu aicināšanu ne pēc mūsu darbiem, bet pēc Savas īpašas apņemšanās un žēlastības, kas mums dota iekš Kristus Jēzus no mūžīgiem laikiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Un tagad ir parādīta caur mūsu Pestītāja Jēzus Kristus atspīdēšanu, kas nāvi izdeldējis un dzīvību un neiznīcību gaismā vedis caur evaņģēliju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Uz ko es esmu iecelts par sludinātāju un apustuli un mācītāju pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Tādēļ es arī to ciešu, bet es nekaunos; jo es zinu, kam esmu ticējis, un stipri ceru, ka Viņš ir spēcīgs, to man novēlēto mantu pasargāt līdz viņai dienai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Paturi tās veselīgās mācības priekšzīmi, ko tu esi dzirdējis no manis, iekš ticības un mīlestības, kas ir iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Šo labo mantu glabā caur To Svēto Garu, kas iekš mums mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'To tu zini, ka visi, kas ir iekš Āzijas, no manis ir nogriezušies; starp tiem ir Fiģels un Hermoģens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Lai Tas Kungs dod žēlastību Onesifora namam; jo tas mani daudzkārtīgi atspirdzinājis un nav kaunējies par manām ķēdēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Bet Romā nācis tas mani rūpīgi ir meklējis un atradis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Lai Tas Kungs tam dod, žēlastību atrast pie Tā Kunga viņā dienā; un cik tas man Efesū kalpojis, to tu jo labi zini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Tad nu, mans dēls, topi spēcīgs iekš tās žēlastības, kas ir iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Un ko tu no manis esi dzirdējis caur daudz lieciniekiem, to māci uzticīgiem cilvēkiem, kas būs derīgi arī citus mācīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Tad tu nu ciet līdz to ļaunumu kā labs Jēzus Kristus karavīrs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Neviens karavīrs netinās ar citiem dzīves darbiem, lai var patikt tam, kas viņu uz karu derējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Un jebšu kas cīnās tas nedabūs kroni, ja nebūs pareizi cīnījies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Zemniekam, kas zemi strādā, būs pirmajam dabūt no tiem augļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Ņem vērā, ko es saku, lai Tas Kungs tev dod saprašanu visās lietās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Turi piemiņā Jēzu Kristu, kas no miroņiem uzmodināts, no Dāvida dzimuma pēc mana evaņģēlija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Viņa dēļ es ļaunumu ciešu līdz pat saitēm kā ļaundarītājs; bet Dieva vārds nav saistīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Tāpēc es visu panesu to izredzēto dēļ, lai arī tie debess prieku dabū iekš Kristus Jēzus ar mūžīgu godību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Tas ir patiesīgs vārds; jo ja mēs līdz mirstam, tad arī līdz dzīvosim;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Ja panesam, tad arī līdz valdīsim; ja mēs aizliedzam, tad Viņš arīdzan mūs aizliegs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Ja mēs esam neuzticami, Viņš paliek uzticams, Viņš Sevi pašu nevar aizliegt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'To piemini, apliecinādams Tā Kunga priekšā, lai tie nestrīdas vārdu dēļ; jo tas neder nekam, kā vien klausītājus sajaukt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Centies, sevi pašu Dievam derīgu priekšā stādīt, kā strādnieku, kam nav jākaunas, un kas tos patiesības vārdus pareizi izdala.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Bet no tām nesvētām tukšām valodām atraujies; jo tie bezdievību vairot vairos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Un viņu vārdi izplešas plašumā tā kā sērga; starp tiem ir Imenejs un Filēts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Kas no patiesības ir nomaldījušies, sacīdami, augšāmcelšanos jau esam notikušu, un pārgroza dažiem ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Bet tas stiprais Dieva pamats pastāv; tam ir šis zieģelis: Tas Kungs tos savējos pazīst, - un: lai atstājās no netaisnības ikviens, kas Tā Kunga vārdu piesauc.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Bet lielā namā ne vien ir zelta un sudraba trauki, bet arī koka un māla trauki, un citi godam, bet citi negodam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Ja tad nu kāds ir šķīstījies no šiem, tad tas būs trauks par godu, svētīts un Tam Kungam derīgs, uz ikvienu labu darbu sataisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Bēdz no tām jaunības kārībām, dzenies pēc taisnības, ticības, mīlestības, pēc miera ar tiem, kas To Kungu piesauc no šķīstas sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Bet tās jautāšanas, kas ir ģeķīgas un bez pamācīšanas, tās atmet, zinādams, ka tās tikai strīdu dzemdina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Bet Tā Kunga kalpam nepienākas strīdēties, bet lēnīgam būt pret visiem, un tādam, kas māk mācīt un ļaunu panest;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Kas ar laipnību tos pretiniekus māca, vai Dievs jel kad tiem nedotu atgriezties pie patiesības atzīšanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Un vai jel tie neuzmostos no velna valga, no kā tie savaldzināti uz viņa prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Bet to tev būs zināt, ka pēdīgās dienās briesmīgi laiki nāks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Jo cilvēki būs pašu mīļotāji, naudas kārīgi, lielīgi, lepni, zaimotāji, vecākiem nepaklausīgi, nepateicīgi, nesvēti,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Bez mīlestības, nesaderīgi, apmelotāji, kas nesavaldās, kas briesmīgi, kas labu nemīl,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Nodevēji, nebēdnieki, uzpūsti, kas vairāk mīļo kārības nekā Dievu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Kas liekās dievbijāšanu cienījuši, bet viņas spēku aizliedz, - un no tādiem atkāpies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'No tādiem ir tie, kas namos ielavās un gūsta tās sieviņas, kas ar grēkiem apkrautas un no dažādām iekārošanām top valdītas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Kas arvienu mācās un nekad nevar nākt pie patiesības atzīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Bet kā Jannes un Jambres Mozum stāvēja pretī, tāpat arī šie stāv pretī patiesībai, cilvēki, kas savā prātā samaitāti, nederīgi pie ticības lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Bet šie tālu netiks; jo šo trakums taps visiem zināms, tā kā arī pie viņiem notika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Bet tu esi dzinies pakaļ manai mācībai, vadīšanai, nodomam, ticībai, lēnprātībai, mīlestībai, pacietībai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Tām vajāšanām, ciešanām, kas man ir notikušas Antioķijā, Ikonijā, Listrā; tādas vajāšanas es esmu panesis, un Tas Kungs mani no visām ir izrāvis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Un visi, kas dievbijīgi grib dzīvot iekš Kristus Jēzus, tie taps vajāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Bet tie ļaunie cilvēki un viltnieki pieaugs ļaunumā, pievildami un pievilti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Bet tu paliec iekš tā, ko tu esi mācījies, un kas tev ir uzticēts, zinādams, no kā tu to esi mācījies,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Un ka tu no mazām dienām svētos rakstus zini, kas tevi var darīt gudru uz debes\' prieku caur to ticību, kas ir iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Viss raksts no Dieva iedots ir arī derīgs pie mācīšanas, pie pārliecināšanas, pie norāšanas, pie pamācīšanas iekš taisnības,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Lai tas Dieva cilvēks ir pilnīgs, uz ikvienu labu darbu pilnīgi sataisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Es piekodināju Dieva un Tā Kunga Jēzus Kristus priekšā, kas nāks tiesāt dzīvus un mirušus, Viņa atspīdēšanu un Viņa valstību minēdams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Pasludini to vārdu, dari to laikā, nelaikā, pārliecini, apdraudi, paskubini iekš visas lēnprātības un mācības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Jo nāks laiki, ka tie to veselīgo mācību nepanesīs, bet pēc savām pašu iekārošanām sev mācītājus uzkraus, kā tiem ausis niez,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Un novērsīs ausis no patiesības un griezīsies pie pasakām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Bet tu esi nomodā iekš visām lietām, panes ļaunumu, dari evaņģelista darbu, izdari savu amatu pilnīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Jo es jau topu upurēts, un manas atraisīšanas laiks ir tuvu klāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'To labo cīnīšanos esmu cīnījies, to tecēšanu esmu pabeidzis, ticību esmu turējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Joprojām man ir nolikts tas taisnības kronis, ko man Tas Kungs, Tas taisnais Soģis, dos viņā dienā, un nevien man, bet arī visiem, kas Viņa atspīdēšanu ir mīlējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Steidzies ātri nākt pie manis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Jo Demas mani atstājis, mīlēdams šo pasauli, un ir nogājis uz Tesaloniku, Krescents uz Galatiju, Titus uz Dalmatiju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lūkas vien ir pie manis; ņem Marku un atved to līdz, jo tas man ļoti derīgs pie kalpošanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tihiku es esmu sūtījis uz Efesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'To mēteli, ko es Troadā pie Karpa esmu atstājis, atnes nākdams līdz un tās grāmatas, visvairāk tās rakstāmās ādas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Aleksandrs, tas kalējs, man daudz ļauna ir darījis; Tas Kungs tam atmaksās pēc viņa darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'No tā tu arīdzan sargies, jo tas mūsu vārdiem pārlieku pretī stāvējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Pie manas pirmās aizbildināšanās neviens pie manis nav bijis, bet visi ir atstājušies no manis, (lai tas tiem netop pielīdzināts).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Bet Tas Kungs man ir klāt bijis un mani stiprinājis, ka caur mani tā mācība pilnīgi taptu zināma un visi pagāni to dzirdētu; un es esmu izrauts no lauvas rīkles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Un Tas Kungs mani izraus no ikviena ļauna darba un izglābs uz Savu Debesu valstību; Tam ir gods mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Sveicini Prisku un Aķilu un Onesifora namu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erasts ir palicis Korintū, un Trofimu es esmu atstājis neveselu Miletū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Steidzies nākt priekš ziemas. Tevi sveicina Eubuls un Pudents un Linus un Klaudija un visi brāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Lai Tas Kungs Jēzus Kristus ir ar tavu garu. Žēlastība lai ir ar jums! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pāvils, Dieva kalps un Jēzus Kristus apustulis, pēc Dieva izredzēto ticības un pēc patiesības atzīšanas uz dievbijāšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Mūžīgas dzīvošanas cerībā, ko Dievs, kas nevar melot, no mūžīgiem laikiem ir apsolījis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Bet savā laikā Savu vārdu ir darījis zināmu caur to sludināšanu, kas man ir uzticēta pēc Dieva, mūsu Pestītāja, pavēles:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titum, savam īstam dēlam pēc tās ticības, kas mums abiem kopā: žēlastība un miers no Dieva, Tā Tēva, un no Tā Kunga Jēzus Kristus, mūsu Pestītāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Tādēļ tevi esmu atstājis Krietā, ka tu izdarītu, kas vēl trūka, un pa pilsētām vecajus ieceltu, kā es tev esmu pavēlējis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Ja kam ir laba slava, kas ir vienas sievas vīrs, kam ir ticīgi bērni, nedz palaidņi, nedz neklausīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Jo bīskapam kā Dieva nama turētājam jābūt vīram, kam laba slava, ne iedomīgam, ne dusmīgam, ne dzērājam, ne rējējam, ne negodīgas peļņas dzinējam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Kas labprāt mājas vietu dod, labu mīl, kas prātīgs, taisns, svēts, šķīsts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Kas pastāvīgi turas pēc tā uzticamā vārda mācības, ka viņš ir spēcīgs, arī pamācīt caur to veselīgo mācību, un pārmācīt tos, kas pretī runā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Jo ir daudz nebēdnieki, kas niekus runā un viltnieki, visvairāk tie no apgraizīšanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Tiem vajag muti aizbāzt, jo tie veselus namus pārgroza negodīgas peļņas dēļ mācīdami, kas neklājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Kāds no tiem, viņu pašu pravietis, ir sacījis: Krieti vienmēr melkuļi, nikni zvēri, slinki vēderi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Šī liecība ir patiesīga; tāpēc pārmāci tos stingri, lai tie paliek veseli ticībā');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Un nedodas uz Jūdu pasakām un uz tādu cilvēku baušļiem, kas nogriežas no patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Visas lietas ir šķīstas šķīstiem; bet apgānītiem un neticīgiem nekas nav šķīsts; bet gan viņu prāts ir apgānīts, gan viņu zināma sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Tie saka, ka Dievu pazīstot, bet ar darbiem tie Viņu aizliedz, neganti būdami un neklausīgi un pie ikviena laba darba nederīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Bet tu runā, kā pēc tās veselīgās mācības pienākas:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Ka tiem veciem vīriem būs būt modrīgiem, godīgiem, prātīgiem, veseliem ticībā, mīlestībā, pacietībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Tāpat tām vecām sievām, ka tām būs turēties, kā svētām pieklājās, ka nebūs citus apmelot nedz padoties dzeršanai, bet dot labu mācību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Ka tās pamāca tās jaunās sievas, vīru mīlēt, bērnus mīlēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Prātīgām būt, šķīstām, nama kopējām, krietnām, saviem vīriem paklausīgām, lai Dieva vārds netop zaimots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Tos jaunos vīrus pamāci tāpat, ka tiem būs būt prātīgiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Parādies pats visās lietās kā priekšzīme iekš labiem darbiem, savā mācībā skaidrs un cienīgs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Ar veselīgiem nevainojamiem vārdiem, lai tas pretinieks top kaunā, un lai tas nevar, ko ļaunu uz mums runāt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Tos kalpus pamāci, saviem kungiem paklausīt un visās lietās pa prātam būt un nerunāt pretī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Neko slepeni nepaņemt, bet visur labu uzticību parādīt, ka tie Dieva, mūsu Pestītāja, mācībai visās lietās par godu turas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Jo Dieva žēlastība, kas visiem cilvēkiem pestīšanu atnes, ir atspīdējusi');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Un mūs pamāca, lai mēs bezdievību un pasaulīgas kārības aizliegdami, šķīsti un taisni un dievbijīgi dzīvojam šinī pasaulē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Gaidīdami to mūžīgo cerības labumu un tā lielā Dieva un mūsu Pestītāja Jēzus Kristus godības atspīdēšanu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Tas Pats par mums ir nodevies, ka mūs atpirktu no visas netaisnības un šķīstītu Sev pašam īpašus ļaudis, kas čakli dzītos uz labiem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'To runā un pamāci un pārmāci, stipri pavēlēdams; neviens lai tevi nenicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Atgādini tiem, lai tie tām valdībām un varām padodas, ir paklausīgi un uz ikvienu labu darbu gatavi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Lai nevienu nezaimo un nestrīdas, bet lai ir lēnīgi, lai visu laipnību parāda visiem cilvēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Jo arī mēs citkārt bijām neprātīgi, nepaklausīgi, alodami, iekārošanām un dažādām kārībām kalpodami, blēdībā un skaudībā dzīvodami, naidīgi, cits citu ienīdēdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Bet kad Dieva, mūsu Pestītāja, laipnība un cilvēku mīlestība ir atspīdējusi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Tad Viņš, ne no tiem taisnības darbiem, ko mēs būtu darījuši, bet pēc Savas apžēlošanas mūs ir izglābis caur to mazgāšanu, kas atdzemdina un atjauno iekš Tā Svētā Gara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Ko Viņš bagātīgi pār mums izlējis caur Jēzu Kristu, mūsu Pestītāju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Lai, caur Viņa žēlastību taisnoti, paliekam par mūžīgas dzīvības mantiniekiem pēc tās cerības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Tas ir patiesīgs vārds. Un to es gribu, ka tu to stipri māci, lai tie, kas Dievam tic, pastāvīgi darbojās iekš labiem darbiem. Tas cilvēkiem ir labi un derīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Bet no ģeķīgām jautāšanām un cilts rakstiem un riešanām un strīdiem par bauslību atraujies, jo tie ir nederīgi un nelietīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'No cilvēka, kas turas pie viltīgas mācības, atkāpies pēc vienas un otras pamācīšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Zinādams, ka tāds ir nelietis un grēko un tīšā prātā pats pazudinājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Kad es Artemu pie tevis sūtīšu vai Tihiku, tad steidzies nākt pie manis uz Nikopoli, jo es jau esmu apņēmies, tur palikt par ziemu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenasu, to bauslības mācītāju, un Apollu izvadi krietni, tā ka tiem nekā netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Un lai arī tie mūsējie mācās labos darbos pastāvīgi darboties priekš visa tā, kas vajadzīgs, lai tie nav neauglīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Tevi sveicina visi, kas pie manis; sveicini tos, kas mūs mīl iekš ticības. Žēlastība lai ir ar jums visiem! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pāvils, Tā Kunga Kristus Jēzus saistīts, un Timotejs, tas brālis, Filemonam, tam mīļotam un mūsu darba biedram,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Un Apijai, tai mīļotai, un Arhipam, mūsu cīnīšanās biedram, un tai Dieva draudzei tavā namā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Žēlastība lai ir jums un miers no Dieva, mūsu Tēva, un no Tā Kunga Jēzus Kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Es savam Dievam pateicos allažiņ, tevi pieminēdams savās lūgšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Dzirdēdams par tavu mīlestību un ticību, kas tev ir uz To Kungu Jēzu un uz visiem svētiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Ka tā ticība, kas tev ir līdz ar mums, top spēcīga un tu atzīsti visu to labumu, kas mums ir iekš Kristus Jēzus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Jo mums ir liels prieks un iepriecināšana caur tavu mīlestību; jo caur tevi, brāli, tiem svētiem sirdis ir atspirdzinātas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Tāpēc, jebšu man liela drošība ir iekš Kristus tev pavēlēt to, kas pieklājās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Tad es tomēr labāki lūdzu no mīlestības, es tas vecais Pāvils, un tagad arī Jēzus Kristus saistīts, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Es tevi lūdzu par savu dēlu Onezimu, ko esmu dzemdinājis iekš savām saitēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'To, kas tev citkārt nebija derīgs, bet tagad tev un man ir labi derīgs, to es sūtu atpakaļ;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Bet tu viņu, tas ir manu sirdi, pieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Es viņu pats pie sevis gribēju paturēt, lai tas tavā vietā man kalpotu iekš evaņģēlija saitēm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Bet bez tavas ziņas es neko negribēju darīt, lai tava labdarīšana nebūtu kā piespiesta, bet no laba prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Jo varbūt, ka viņš tāpēc mazu brīdi bijis atšķirts no tevis, lai tu viņu atdabūtu uz mūžību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Ne vairs kā kalpu, bet vairāk nekā kalpu, kā mīļu brāli, īpaši man, bet cik vairāk tev gan pēc miesas, gan iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Tad nu, ja tu mani turi par (ticības)biedru, tad pieņem viņu tā kā mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Bet ja viņš tev netaisnību darījis, vai ir parādā, tad man to pielīdzini.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Es, Pāvils, to rakstu ar savu roku: es maksāšu; lai tev neteiktu, ka tu arī pats sevi man esi parādā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Tiešām, brāli, lai es no tevis ko mantoju iekš Tā Kunga, atspirdzini manu sirdi iekš Tā Kunga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Cerēdams, ka tu paklausīsi, es tev rakstu, un zinu, ka tu arī darīsi vairāk nekā es saku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Turklāt sataisi man arī mājas vietu, jo es ceru, ka caur jūsu lūgšanām es jums tapšu atdots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Tevi sveicina, Epafra, mans cietuma biedrs iekš Kristus Jēzus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marks, Aristarks, Demas, Lūkas, mani darba biedri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jūsu garu! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Dievs dažu reizi un dažādi vecos laikos uz tiem tēviem runājis caur tiem praviešiem, šinīs pēdīgās dienās uz mums ir runājis caur To Dēlu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'To Viņš ir iecēlis par mantinieku pār visu; caur To Viņš arī pasauli radījis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Tas ir tas godības atspīdums un Viņa būšanas ģīmis un nes visas lietas caur Savu spēcīgo vārdu, un, šķīstīšanu no grēkiem darījis caur Sevi pašu, un sēdies pie labās rokas tai godībai augstībā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Un Viņš ir tapis tik daudz augstāks pār eņģeļiem, cik Viņš augstāku vārdu pār tiem ir mantojis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Jo kuram eņģelim Viņš jebkad ir sacījis: Tu esi Mans Dēls, šodien Es Tevi esmu dzemdinājis? Un atkal: Es Viņam būšu par Tēvu, un Viņš Man būs par Dēlu?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Un kad Viņš atkal to pirmdzimušo ieved pasaulē, Viņš saka: un visiem Dieva eņģeļiem būs Viņu pielūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Un par tiem eņģeļiem Viņš gan saka: kas Savus eņģeļus dara par vējiem, un Savus sulaiņus par uguns liesmām;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Bet par To Dēlu: Tavs goda krēsls, ak Dievs, paliek mūžīgi mūžam; Tavas valdīšanas scepteris ir taisns scepteris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Tu esi mīlējis taisnību un ienīdējis netaisnību; tāpēc Dievs, Tavs Dievs, Tevi svaidījis ar prieka eļļu, pāri par Taviem biedriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Un: Tu, Kungs, iesākumā zemi esi dibinājis, un debesis ir Tavu roku darbs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Tās zudīs, bet Tu palieci vienmēr, tās sadils visas kā drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Un tā kā uzvalku Tu tās satīsi, un tās taps pārvērstas: bet Tu esi tas pats, un Tavi gadi nebeigsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Un uz kuru eņģeli Viņš jebkad ir sacījis: sēdies pie Manas labās rokas, tiekams Es Tavus ienaidniekus lieku par pameslu Tavām kājām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Vai visi tie nav gari, kas kalpo un top izsūtīti uz kalpošanu to dēļ, kas to debesprieku iemantos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Tāpēc mums būs jo vairāk vērā ņemt to vārdu, ko esam dzirdējuši, ka jel netopam aizrauti pazušanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Jo ja tas vārds, kas caur eņģeļiem runāts, ir bijis stiprs, un ikkatra pārkāpšana un neklausīšana ir dabūjusi savu taisno atmaksu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Kā tad mēs izbēgsim par tādu pestīšanu nebēdādami? Tā papriekš ir sludināta caur To Kungu un mums apstiprināta no tiem, kas to dzirdējuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Tai Dievs ir liecību devis ar zīmēm un brīnumiem un dažādiem spēkiem un ar Tā Svētā Gara izdalīšanām pēc Sava prāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Jo ne eņģeļiem Viņš ir padevis to nākamo pasauli, par ko mēs runājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Bet viens kādā vietā ir apliecinājis sacīdams: kas ir cilvēks, ka Tu viņu piemini? Jeb cilvēka dēls, ka Tu viņu piemeklē?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Īsu laiku Tu viņu esi darījis mazāku nekā eņģeļus, ar godu un slavu Tu viņu esi kronējis un viņu iecēlis pār Savu roku darbiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Visas lietas Tu esi licis apakš viņa kājām. Jo kad Tas viņam visas lietas padevis, tad Tas neko nav atstājis, kas viņam nebūtu padots; bet tagad mēs vēl neredzam, ka viņam visas lietas padotas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Bet mēs redzam Jēzu nāves ciešanas dēļ ar godu un slavu kronētu, kas īsu laiku mazāks tapis nekā eņģeļi, lai Viņš caur Dieva žēlastību par visiem nāvi baudītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Jo Tam, kā dēļ visas lietas ir un caur ko visas lietas ir, kas daudz bērnus uz godību vada, Tam pienācās Viņu, pestīšanas vadoni, caur ciešanām pilnīgu darīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Jo tāpat tas, kas svētī, kā tie, kas top svētīti, visi ir no viena; tādēļ Viņš nekaunas, tos saukt par brāļiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Sacīdams: Es Tavu vārdu sludināšu Saviem brāļiem, draudzes vidū Es Tev pateicības dziesmas dziedāšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Un atkal: Es Savu cerību likšu uz Viņu. Un atkal: redzi, Es un tie bērni, ko Dievs Man ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Kad nu tie bērni miesas un asinis dabūjuši, tad arī Viņš to pašu it līdzīgi ir dabūjis, ka Viņš caur nāvi iznīcinātu to, kam bija nāves vara, tas ir velnu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Un atsvabinātu visus tos, kas caur nāves bailēm cauru mūžu bija padoti kalpošanai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Jo Viņš taču nepieņem eņģeļus, bet Ābrahāma dzimumu Viņš pieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Tāpēc Viņam vajadzēja visās lietās tiem brāļiem palikt līdzīgam, lai sirds žēlīgs taptu un uzticīgs augsts priesteris Dieva priekšā, to ļaužu grēkus salīdzināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Jo caur to, ka Pats ir cietis un kārdināts, Viņš tiem, kas top kārdināti, var palīdzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Tādēļ, svētie brāļi, kam ir daļa pie tās debešķīgas aicināšanas, ņemiet vērā to apustuli un augsto priesteri, ko mēs apliecinājam, Kristu Jēzu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Kas ir uzticīgs Tam, kas Viņu iecēlis, tā kā arī Mozus visā Viņa namā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Jo Šis ir lielāka goda cienīgs nekā Mozus, tā kā tam, kas namu uztaisījis, ir lielāks gods nekā tam namam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Jo ikkatrs nams no kāda top uztaisīts, bet kas šo visu ir uztaisījis, tas ir Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Un Mozus gan ir bijis uzticīgs visā Viņa namā kā kalps, par liecību tam vārdam, kas bija runājams;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Bet Kristus kā Dēls pār Viņa namu; tā nams mēs esam, ja tikai to drošību un to cerību, ar ko lielāmies, līdz galam paturam stipru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Tādēļ, tā kā Svētais Gars saka: šodien, kad jūs Viņa balsi dzirdēsiet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Neapcietinājiet savas sirdis, tā kā pie tās sariebšanas tai kārdināšanas dienā tuksnesī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Kur jūsu tēvi Mani kārdinājuši, Mani pārbaudījuši un redzējuši Manus darbus četrdesmit gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Tāpēc Es apskaitos par šo tautu un sacīju: vienmēr tie alojās savā sirdī, bet Manus ceļus tie nezināja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Tad Es arī esmu zvērējis Savā dusmībā: tiem nebūs ieiet Manā dusēšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Pielūkojat, brāļi, ka jel nevienam no jums nav ļauna neticīga sirds, ka jūs atkāpjaties no tā dzīvā Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Bet pamācāties paši ikdienas kamēr vēl top sacīts: šodien; ka neviens no jums netop apcietināts caur grēka pievilšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Jo mēs daļu esam dabūjuši pie Kristus, ja tikai to iesākto būšanu līdz galam paturam stipru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Kad top sacīts: šodien, kad jūs Viņa balsi dzirdēsiet, neapcietinājiet savas sirdis, kā tai sariebšanas laikā!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Kas tad, to dzirdējuši, Viņu ir nicinājuši? Vai ne visi, kas caur Mozu ir izgājuši no Ēģiptes?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Par kuriem Viņš tad ir apskaities četrdesmit gadus? Vai ne par tiem, kas ir apgrēkojušies, kuru miesas pakrita tuksnesī?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Kuriem tad Viņš ir zvērējis, ka tiem nebūs ieiet Viņa dusēšanā, ja ne tiem, kas bijuši nepaklausīgi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Un mēs redzam, ka tie nav varējuši ieiet neticības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Tad nu lai bīstamies, ka jel tā apsolīšana, Viņa dusēšanā ieiet, netop aizkavēta un neviens no jums netop ieraudzīts tāds, kas būtu palicis to nesasniedzis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Jo arī mums tas evaņģēlijs ir pasludināts, tā kā viņiem; bet tas sludināšanas vārds tiem nekā nepalīdzēja, tāpēc ka tas nebija savienots ar ticību iekš tiem, kas to bija dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Jo mēs, kas esam ticējuši, ieejam tai dusēšanā, tā kā Viņš ir sacījis: Es zvērēju Savā dusmībā, tiem nebūs ieiet Manā dusēšanā; lai gan tie darbi no pasaules radīšanas bija padarīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Jo Viņš kādā vietā par to septīto dienu tā ir runājis: un Dievs septītā dienā ir dusējis no visiem Saviem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Un šinī vietā atkal: tiem nebūs ieiet Manā dusēšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Kad nu tā paliek, ka citiem būs ieiet tai dusēšanā, un ka tie, kam papriekš tas evaņģēlijs ir sludināts, nav iegājuši neticības dēļ;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Tad Viņš atkal kādu dienu noliek: šodien, caur Dāvidu sacīdams pēc tāda ilga laika, tā kā ir sacīts: šodien, kad jūs Viņa balsi dzirdēsiet, neapcietinājiet savas sirdis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Ja jau Jozua tos ir ievedis dusēšanā, tad Viņš pēc tam nebūtu runājis par citu dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Tad nu vēl atliek svēta dusēšana Dieva ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Jo kas Viņa dusēšanā ir iegājis, tas dus arī no saviem darbiem, tā kā Dievs no Saviem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Tad nu lai dzenamies ieiet tanī dusēšanā, ka neviens neiekrīt tai pašā neticības priekšzīmē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Jo Dieva vārds ir dzīvs un spēcīgs un asāks, nekā kāds abējās pusēs griezīgs zobens, un spiežās cauri, līdz kamēr pāršķir dvēseli un garu, locekļus un smadzenes, un ir soģis pār sirds domām un sirds prātu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Un Viņa priekšā neviena radīta lieta nav neredzama, bet visas lietas ir atsegtas un redzamas priekš Tā acīm, par ko mēs runājam(dosim norēķinu).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Kad nu mums ir liels augsts priesteris, kas caur debesīm gājis, Jēzus, Dieva Dēls, tad lai mēs pie šīs apliecināšanas stipri turamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Jo mums nav augsts priesteris, kas nevarētu iežēloties par mūsu vājībām, bet kas visās lietās ir kārdināts tā kā mēs, tomēr bez grēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Tad nu lai ar drošību pieejam pie tā žēlastības krēsla, lai apžēlošanu dabūjam un žēlastību atrodam par palīdzību savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Jo ikviens augsts priesteris, kas no cilvēkiem ņemts, top iecelts pār cilvēkiem tanīs lietās, kas priekš Dieva jādara, lai tas upurē dāvanas un upurus par grēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Un var iežēloties par tiem, kas nezin un alojās, tāpēc ka viņš pats arīdzan ar vājību apņemts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Un šās vājības dēļ viņam jāupurē par grēkiem, tā kā priekš tiem ļaudīm, tāpat arī priekš sevis paša.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Un neviens neņem pats sev to godu, bet kā kurš no Dieva top aicināts, tā kā arī Ārons.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tāpat arī Kristus nav pats Sevi pagodinājis, ka taptu par augstu priesteri, bet Tas, kas uz Viņu ir runājis: Tu esi Mans Dēls, šodien Es Tevi esmu dzemdinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Tā kā Viņš arī citā vietā saka: Tu esi priesteris mūžīgi pēc Melhizedeka kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Šis (Kristus) Savās miesas dienās, lūgšanas un aizlūgšanas ar stipru brēkšanu un asarām ir upurējis Tam, kas Viņu no nāves varēja izglābt, un ir paklausīts, tāpēc ka Viņš Dievu turēja godā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Un jebšu Dēls būdams, tomēr Viņš paklausību ir mācījies caur to, ko ir cietis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Un pilnīgs tapis, Viņš ir palicis visiem, kas Viņam paklausa, par mūžīgas dzīvošanas gādātāju;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Un no Dieva ir nosaukts par augstu priesteri pēc Melhizedeka kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Par to mums būtu daudz ko runāt, to izstāstīt ir grūti, tāpēc ka jūs kūtri palikuši pie uzklausīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Jo jums, kam sen laikiem pienākas būt mācītājiem, atkal vajag, ka topat mācīti, kādas ir tās pirmās Dieva vārdu sākuma mācības; un esat palikuši par tādiem, kam piena vajag un ne cietas barības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Jo ikviens, kas tikai pienu bauda, tas vēl ir nesapraša iekš tā taisnības vārda, jo tas ir bērns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Bet pieaugušiem vajag stipra ēdiena, tiem, kam prāts radināts un izmācīts, izšķirt labu un ļaunu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Tāpēc nerunāsim par tām kristīgām sākuma mācībām, bet dosimies uz to pilnību, ne atkal pamatu likdami ar atgriešanos no nedzīviem darbiem un ar ticību uz Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Ar mācību par kristību, par roku uzlikšanu, par miroņu augšāmcelšanos, par mūžīgu sodību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Arī to mēs darīsim, ja tikai Dievs to ļauj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Jo tas nevar būt, ka tie, kas vienreiz bijuši apgaismoti un baudījuši tās debesu dāvanas un daļu dabūjuši pie Tā Svētā Gara,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Un baudījuši to labo Dieva vārdu un tās nākamās pasaules spēkus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Un atkāpjas, ka tie atkal varētu tapt atjaunoti uz atgriešanos no grēkiem, jo tie Dieva Dēlu sev atkal krustā sit un liek smieklā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Jo tā zeme, kas iedzer to daudzkārt līstošo lietu un nes derīgu zāli tiem, kuru dēļ tā arī tiek apstrādāta, tā dabū svētību no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Bet kas ērkšķus un dadžus nes, tā ir nederīga, un tai lāsts ir tuvu, un gals degšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Bet no jums, mīļie, mēs ceram ko labāku, un ka dzīsities pēc pestīšanas, jebšu tā runājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Jo Dievs nav netaisns, ka Viņš aizmirstu jūsu darbu un to mīlestību, ko esat parādījuši pie Viņa vārda, kad jūs tiem svētiem kalpojāt un vēl kalpojiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Bet mēs gribam, ka ikviens no jums parāda to pašu uzcītību uz cerības pilnību līdz galam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Lai jūs netopat kūtri, bet tiem dzenaties pakaļ, kas caur ticību un pacietīgu gaidīšanu iemanto tās apsolīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Jo kad Dievs Ābrahāmam to apsolīšanu deva, un kad Viņš nevarēja pie nekāda lielāka zvērēt, tad Viņš zvērēja pie Sevis paša,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Sacīdams: patiesi, Es svētīdams tevi svētīšu un vairodams tevi vairošu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Un tā Ābrahāms pacietīgi gaidīdams to dabūja, kas bija apsolīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Jo cilvēki zvēr pie kāda lielāka nekā viņi paši, un zvērēšana viņiem nobeidz visu strīdu un ir par apstiprināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Tad nu Dievs, gribēdams tiem apsolīšanas mantiniekiem Savu nepārvēršamo padomu jo skaidri parādīt, zvērēdams vidū nācis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Ka mēs caur divām nepārvēršamām lietām - jo nevar būt, ka Dievs melotu - dabūtu stipru iepriecināšanu, mēs, kas steidzamies to solīto cerību saņemt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Tā mums ir tā kā uzticīgs un stiprs dvēseles enkurs, kas ieķerās priekškaramā auta iekšpusē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Kur Jēzus kā priekštecētājs par mums ir iegājis, pēc Melhizedeka kārtas par augstu priesteri palicis uz mūžību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Jo šis Melhizedeks bija Salemes ķēniņš, Dieva tā visu augstākā priesteris, kas Ābrahāmam, kad tas pārnāca no tās ķēniņu kaušanas, gāja pretī un viņu svētīja;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Tam Ābrahāms arī deva to desmito tiesu no visa. Tas pirmā kārtā top tulkots: taisnības ķēniņš, - bet tad arīdzan: Salemes ķēniņš, tas ir, miera ķēniņš;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Bez tēva, bez mātes, bez radu raksta; kam nav nedz dienu iesākuma, nedz dzīvības gala, bet Dieva Dēlam līdzināts viņš paliek priesteris mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Bet lūkojiet, cik liels šis ir, ka pats Ābrahāms, tas vectēvs, viņam desmito tiesu no tā laupījuma devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Un tiem Levja bērniem, kas to svēto amatu dabū, ir gan viens likums, desmito tiesu ņemt no tiem ļaudīm pēc bauslības, tas ir, no saviem brāļiem, jebšu tie cēlušies no Ābrahāma gurniem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Bet viņš, kas nebija cēlies no viņu cilts, to desmito tiesu ir ņēmis no Ābrahāma un svētījis to, kam tās apsolīšanas bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Bet nu bez nekādas pretī runāšanas tas mazākais top svētīts no tā lielākā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Un še mirstīgi cilvēki ņem to desmito tiesu, bet tur tas, par ko liecība top dota, ka tas dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Un (tā sakot): arī Levi, kas to desmito tiesu ņem, to desmito tiesu ir devis caur Ābrahāmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Jo viņš vēl bija tēva gurnos, kad Melhizedeks šim gāja pretī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Ja tad nu tā pilnība būtu caur to priestera amatu no Levja cilts, (jo līdz ar to tie ļaudis bauslību ir dabūjuši), kam tad vēl vajadzēja citam priesterim celties pēc Melhizedeka kārtas, un netikt sauktam pēc Ārona kārtas?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Jo kad priesteru amats tiek pārcelts, tad arīdzan bauslībai jātiek pārceltai.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Jo Tas, par ko tas sacīts, piederēja pie citas cilts, no kuras neviens nebija kalpojis pie altāra.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Jo tas ir zināms, ka mūsu Kungs cēlies no Jūda cilts un uz šo cilti Mozus neko nav runājis par priesteru amatu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Un tas vēl jo skaidri ir zināms, ja pēc Melhizedeka līdzības cits priesteris ceļas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Kas tāds tapis ne pēc miesīga likuma bauslības, bet pēc neiznīcīgas dzīvības spēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Jo Viņš apliecina: Tu esi priesteris mūžīgi pēc Melhizedeka kārtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Jo iepriekšēja baušļa atcelšana notiek tāpēc, ka tas nespēcīgs un nederīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Jo bauslība neko nav darījusi pilnīgu, bet tā labākas cerības ievešana, caur ko mēs tuvu nākam pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Un kad tas nav noticis bez zvērēšanas, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(Jo viņi bez zvērēšanas palikuši par priesteriem, bet Šis ar zvērēšanu, caur To, kas uz Viņu saka: Tas Kungs ir zvērējis - un tas Tam nebūs žēl - Tu esi priesteris mūžīgi pēc Melhizedeka kārtas) -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Tad Jēzus par vienas daudz labākas derības galvinieku ir palicis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Un viņi gan daudzi ir tapuši par priesteriem, tāpēc ka nāve tiem neļāva palikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Bet Šim caur to, ka Viņš mūžīgi paliek, ir neiznīcīgs priestera amats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Tādēļ Viņš arī pilnīgi var izglābt tos, kas caur Viņu pie Dieva nāk, vienmēr dzīvodams, ka Viņš tos aizstāvētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Jo tāds augsts priesteris mums arī pienācās, kas ir svēts, nenoziedzīgs, neapgānīts, atšķirts no grēciniekiem un augstāks pār debesīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Kam nevajag, tā kā tiem augstiem priesteriem, ikdienas upurus nest papriekš par saviem pašu grēkiem un pēc par tiem ļaužu grēkiem; jo to Viņš ir darījis vien\' reiz, kad Viņš pats Sevi upurējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Jo bauslība ieceļ par augstiem priesteriem cilvēkus, kam ir vājība, bet tas zvērēšanas vārds, kas nāca pēc bauslības, tas To Dēlu ieceļ mūžīgi pilnīgu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Bet visu, kas sacīts, saņemot vienā vārdā: mums ir tāds augsts priesteris, kas sēž pa labo roku tam augstības goda krēslam debesīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'To svētumu kopējs un tās patiesās Dieva telts, ko Tas Kungs ir uzcēlis un ne cilvēks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Jo ikviens augsts priesteris top iecelts, nest dāvanas un upurus; tādēļ vajadzēja, ka arī Šim kas būtu, ko Tas upurētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Jo ja Viņš virs zemes būtu, tad Viņš nebūtu priesteris, tāpēc, ka (te) priesteri ir, kas pēc bauslības dāvanas upurē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Un kas tai debesu lietu līdzībai un ēnai kalpo, tā kā Mozus caur Dievu bija pamācīts, kā tam Dieva telti bija uzcelt; jo Viņš sacīja: raugi, ka tu visu to dari pēc tās priekšzīmes, kas tev kalnā ir rādīta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Bet nu Kristus jo labu amatu dabūjis, jo labākas derības vidutājs Viņš ir, kas ar labākām apsolīšanām ir apstiprināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Jo ja viņa, tā pirmā, būtu bijusi bez trūkuma, tad otra vieta nebūtu meklēta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Jo tos rādams, Viņš saka: redzi, dienas nāk, saka Tas Kungs, un Es celšu jaunu derību ar Israēla namu un ar Jūda namu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Ne tādu derību, kādu Es ar viņu tēviem esmu cēlis tanī dienā, kad Es tos pie rokas satvēru, tos no Ēģiptes izvest: jo tie Manā derībā nav palikuši; - tad Es arīdzan par tiem neesmu bēdājis, saka Tas Kungs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Jo šī ir tā derība, ko Es celšu ar Israēla namu pēc šīm dienām, saka Tas Kungs: Es došu Savus baušļus viņu prātā, un Es tos rakstīšu viņu sirdīs, un Es tiem būšu par Dievu, un tie Man būs par ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Un tie nemācīs neviens savu tuvāko un neviens savu brāli, sacīdams: atzīsti To Kungu: Jo tie visi Mani pazīs, no tā mazākā viņu starpā līdz tam lielākajam viņu starpā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Jo Es apžēlošos par viņu netaisnībām, un nepieminēšu vairs viņu grēkus un viņu noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Kad Viņš saka: jaunu (derību), tad Viņš to pirmo ir darījis par vecu. Kas nu ir darīts par vecu un vecs paliek, tas iznīkšanai ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Tad nu gan arī tai pirmai derībai bija Dieva kalpošanas likumi un laicīgs svētums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Jo Dieva telts bija uzcelta: tai priekšējā bija tas lukturis un tas galds un tās Dieva priekšā noliktas maizes; tā top saukta tā svētā vieta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Bet aiz tā otra priekškaramā auta tas dzīvoklis, kas top saukts tā vissvētākā vieta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Tam bija tas kvēpināmais zelta altāris un tas derības šķirsts, vispāri pārvilkts ar zeltu, kurā tas zelta trauciņš ar to debess maizi un Ārona zizlis, kas bija zaļojis, un tie derības galdiņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Un virsū pār to tie godības ķerubi, kas to derības šķirsta vāku apēnoja: par to tagad nav jārunā īpaši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Kad nu šās lietas tā sataisītas, tad tie priesteri gan allažiņ ieiet tai dzīvokļa priekšējā daļā, Dieva kalpošanas darbus darīdami,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Bet tai otrā tas augstais priesteris vien vienreiz par gadu, ne bez asinīm, ko viņš upurē par sava paša un to ļaužu noziegumiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Caur to Svētais Gars rāda, ka ceļš uz to svēto vietu vēl nav parādīts, kamēr tā dzīvokļa priekšēja daļa pastāv;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Tā ir to tagadēju laiku līdzība, pēc kuras upurē dāvanas un upurus, kas to, kas kalpo, nevar pilnīgu darīt pēc zināmas sirds,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Bet tie tikai līdz ar ēdieniem un dzērieniem un daudzkārtīgām mazgāšanām kā ārīgi miesas likumi uzlikti līdz tam laikam, kad viss labāki tiks pārtaisīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Bet Kristus, to nākamo labumu augstais priesteris, ir nācis un caur jo lielu un jo pilnīgu dzīvokli, ne rokām taisītu - tas ir, ne no šīs radības, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Nedz ar āžu un teļu asinīm, bet ar Savām paša asinīm Viņš vienreiz ir iegājis tai svētā vietā un sagādājis mūžīgu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Jo ja vēršu un āžu asinis un pelni no jaunas govs nešķīstos apslacinājot šķīsta uz miesas šķīstību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Cik vairāk Kristus asinis, kas caur to mūžīgo Garu Sevi pašu bezvainīgu Dievam ir upurējis, šķīstīs jūsu zināmu sirdi no nedzīviem darbiem, kalpot Tam dzīvam Dievam?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Un tādēļ Viņš ir tās jaunās derības (testamenta) vidutājs, lai, kad nāve bija notikusi par atpestīšanu no tām pārkāpšanām, kas bija apakš tās pirmās derības, tie, kas ir aicināti, dabū to apsolīto mūžīgo mantību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Jo kur ir iestādījums(testaments), tur tam iestādītajam vajag būt mirušam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Jo iestādījums (testaments) ir stiprs, kad tas iestādītājs miris; jo tas nekad nav spēkā, kamēr viņš vēl dzīvs, kas to cēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Tāpēc arī tā pirmā derība nav iecelta bez asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Jo kad Mozus visus likumus pēc bauslības bija runājis uz visiem ļaudīm, tad tas ņēma teļu un āžu asinis ar ūdeni un purpura vilnu un īzapu un apslacināja pašu to grāmatu kā arī visus ļaudis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Sacīdams: šīs ir tās derības asinis, ko Dievs jums ir pavēlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Tā līdzīgi viņš arī Dieva telti un visus Dieva kalpošanas rīkus apslacināja ar asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Un gandrīz viss ar asinīm top šķīstīts pēc bauslības, un bez asins izliešanas nenotiek piedošana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Tad nu tām debes\' lietu līdzībām tā vajag tapt šķīstītām, bet tām debes\' lietām pašām caur labākiem upuriem, nekā šie ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Jo Kristus nav iegājis tai rokām taisītā svētā vietā, caur ko tā patiesā top zīmēta, bet pašās debesīs, ka tas tagad parādītos priekš Dieva vaiga par mums;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Nedz ka Viņš Sevi pašu daudzreiz upurētu, tā kā tas augstais priesteris ik gadus svētā vietā ieiet ar svešām asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Citādi Viņam būtu pienācies daudzreiz ciest no pasaules iesākuma; bet tagad Viņš vienreiz laiku galā ir parādījies, grēku iznīcināt caur Savu paša upuri.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Un tā, kā cilvēkiem ir nolikts vienreiz mirt un pēc tam tā tiesa:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Tāpat arī Kristus, vienreiz upurēts, daudz ļaužu grēkus atņemt, taps redzēts otru reizi bez grēka no tiem, kas Viņu gaida, uz mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Jo bauslībai ir nākamo labumu ēna, ne to lietu ģīmis pats, un ar tiem upuriem, kas ik gadus tie paši, un ko bez mitēšanās upurē, upurētājus nekad nevar darīt pilnīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Citādi tie būtu mitējušies upurēt, ja tiem ar upuriem kalpojot vairs nebūtu bijusi nekāda apzināšanās par grēkiem, kad tie vienreiz šķīstīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Bet nu ik gadus caur tiem (upuriem) notiek grēku pieminēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Jo tas nevar būt, ka vēršu vai āžu asinis grēkus atņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Tāpēc pasaulē nākdams Viņš saka: upurus un dāvanas Tu neesi gribējis, bet to miesu Tu Man esi sataisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Dedzināmi upuri un grēku upuri Tev nav patikuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Tad Es sacīju: redzi, Es nāku, (grāmatā par Mani ir rakstīts) Tavu prātu darīt, ak Dievs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Kad Viņš papriekš bija sacījis: upurus un dāvanas un dedzināmos upurus un grēku upurus Tu neesi gribējis, nedz tie Tev bija pa prātam, (kas pēc bauslības top upurēti);');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Tad Viņš sacīja: redzi, Es nāku, ak Dievs, Tavu prātu darīt. Viņš tad noceļ to pirmo, ka Viņš to otru ieceltu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Pēc šī prāta mēs esam svētīti caur Jēzus Kristus miesas upuri vienreiz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Un ikkatrs priesteris gan ikdienas stāv kalpodams un tos pašus upurus daudzkārt upurēdams, kas grēkus mūžam nevar atņemt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Bet Šis, vienu upuri par grēkiem upurējis, uz mūžību nosēdies pie Dieva labās rokas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Joprojām gaidīdams, tiekams Viņa ienaidnieki top likti par pameslu Viņa kājām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Jo ar vienu upuri Viņš ir mūžīgi pilnīgus darījis tos, kas top svētīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Un Svētais Gars mums to arīdzan apliecina; jo kad Viņš papriekš bija sacījis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Šī ir tā derība, ko Es ar viņiem celšu pēc šīm dienām, saka Tas Kungs: Savus baušļus Es došu viņu sirdīs un tos rakstīšu viņu prātā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Un Es vairs nepieminēšu viņu grēkus un viņu netaisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Kur nu ir grēku piedošana, tur vairs nav upura par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Kad nu, brāļi, mums ir drošība, ieiet tai svētā vietā caur Jēzus asinīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Ko Viņš mums ir sataisījis par jaunu un dzīvu ceļu caur to priekškaramo autu, tas ir, caur Savu miesu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Un kad nu mums ir augsts priesteris pār Dieva namu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Lai pieejam ar patiesīgu sirdi iekš pilnīgas ticības, apslacināti savās sirdīs, vaļā no ļaunas apzināšanās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Un pie miesas nomazgāti ar šķīstu ūdeni, lai mēs to cerības apliecināšanu paturam nešaubīgu, (jo Tas ir uzticīgs, kas to apsolījis).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Un lai mēs cits citu vērā ņemamies ar skubināšanu pie mīlestības un labiem darbiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Un lai neatstājam savu sapulcināšanos, kā daži mēdz, bet cits citu lai pamācam; un to jo vairāk, jo jūs redzat, ka tā diena nāk tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Jo ja mēs tīši grēkojam pēc tam, kad esam dabūjuši patiesības atzīšanu, tad vairs neatliekās nekāds upuris par grēkiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Bet briesmīga sodības gaidīšana un uguns karstums, kas pretiniekus aprīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Ja kāds Mozus bauslību nicinājis, tam bez apžēlošanas caur diviem vai trim lieciniekiem jāmirst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Cik gan, domājiet, grūtāku sodību būs pelnījis tas, kas Dieva Dēlu min ar kājām un tās derības asinis, caur ko viņš svētīts, tur par nesvētām, un kas to žēlastības Garu ir nievājis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Jo mēs pazīstam To, kas ir sacījis: Man pieder atriebšana, Es atmaksāšu, saka Tas Kungs. Un atkal: Tas Kungs tiesās Savus ļaudis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Briesmīga lieta ir, iekrist Tā dzīvā Dieva rokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Bet pieminiet tās iepriekšējās dienas, kurās, apgaismoti, jūs pastāvīgi esat cīnījušies lielās bēdu cīnīšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Gan caur mēdīšanām un bēdām tapuši par ērmiem, gan palikuši par biedriem tiem, kam tā klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Jo jūs esat cietuši līdz ar manām saitēm un ar prieku panesuši savas mantas laupīšanu, zinādami, ka jums iekš sev pašiem ir labāka un paliekama manta debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Tāpēc neatmetiet savu sirds drošību, jo tai ir liela alga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Bet paciešanās jums vajag, lai jūs Dieva prātu darījuši iemantojiet to apsolīto svētību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Jo vēl ir mazs brīdis, un Tas, kam jānāk, nāks un nekavēsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Bet taisnais no ticības dzīvos; un ja kas atkāpjas, pie tā manai dvēselei nav labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Bet mēs neesam no tiem, kas atkāpjas uz pazušanu, bet kas tic uz dvēseles izglābšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Bet ticība ir paļaušanās uz lietām, kas cerējamas, un pārliecināšanās par lietām, kas neredzamas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Jo caur to tie vecaji liecību ir dabūjuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Caur ticību mēs noprotam, ka pasaule ir radīta caur Dieva vārdu, tā ka tās redzamās lietas nav cēlušās no redzamām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Caur ticību Ābels Dievam lielāku upuri ir pienesis nekā Kains: caur to viņš liecību ir dabūjis, ka viņš taisns, kad Dievs par viņa dāvanām liecināja; un caur to viņš vēl runā, jebšu miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Caur ticību Enohs ir aizņemts, tā ka nāvi neredzēja; un viņš netapa atrasts, tāpēc ka Dievs viņu bija aizņēmis; jo pirms viņš tapa aizņemts, viņš liecību ir dabūjis, ka viņš Dievam paticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Bet bez ticības nevar Dievam patikt; jo kas pie Dieva nāk, tam būs ticēt, ka Viņš ir un ka būs atmaksātājs tiem, kas Viņu meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Caur ticību Noa, no Dieva par to pamācīts, kas nebija redzams, Dievu bīdamies to šķirstu ir uzcirtis savam namam par izglābšanu; caur to viņš pasauli ir notiesājis un iemantojis to taisnību, kas nāk caur ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Caur ticību Ābrahāms aicināts ir paklausījis un izgājis uz to vietu, ko tam bija mantot, un viņš ir izgājis, nezinādams, kur nonākšot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Caur ticību viņš mājojis tai apsolītā zemē tā kā svešā, un teltīs dzīvojis ar Īzaku un Jēkabu, kas bija tās pašas apsolīšanas līdzmantinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Jo viņš gaidīja to pilsētu, kam stipri pamati un kam cēlējs un uztaisītājs pats Dievs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Caur ticību arī tā pati Sāra spēku dabūjusi, grūta tapt, un dzemdējusi pāri par laiku savā vecumā, jo viņa To turēja par uzticīgu, kas to bija apsolījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Tādēļ arī no viena, un no tā paša izdēdējušā, ir dzimuši tik daudz kā debess zvaigznes un kā smiltis jūrmalā, kas neskaitāmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Šie visi ir miruši iekš ticības un to, kas bija apsolīts, nav panākuši, bet no tālienes redzējuši un ar mieru bijuši un apliecinājuši, ka viņi esot virs zemes viesi un svešinieki.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Jo tie, kas tādas lietas runā, rāda, ka tie tēva zemi meklē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Un ja tie būtu prātā turējuši to, no kuras bija izgājuši, tad tiem būtu bijis laiks, atpakaļ griezties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Bet nu tie ilgojās pēc vienas labākas, proti debešķīgas; tāpēc Dievs viņu dēļ nekaunas saukties viņu Dievs, jo Viņš tiem pilsētu ir sataisījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Caur ticību Ābrahāms, kad tapa pārbaudīts, ir upurējis to Īzaku un atnesis to vienpiedzimušo, lai gan tas tās apsolīšanas bija dabūjis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Un uz to bija sacīts: iekš Īzaka tev dzimums taps dēvēts;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Jo viņš domāja, ka Dievs spēcīgs arī no miroņiem uzmodināt; tādēļ viņš to arī kā priekšzīmi atdabūja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Caur ticību Īzaks Jēkabu un Ēsavu ir svētījis par nākamām lietām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Caur ticību Jēkabs mirdams katru no Jāzepa dēliem ir svētījis, un ir Dievu pielūdzis, noliecies pār sava zižļa galu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Caur ticību Jāzeps mirdams ir sludinājis par Israēla bērnu iziešanu un ir devis pavēli par saviem kauliem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Caur ticību Mozus, kad bija piedzimis, tapa apslēpts trīs mēnešus no saviem vecākiem, tādēļ ka tie redzēja, viņu esam krāšņu bērniņu. Un tie nebijās par ķēniņa pavēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Caur ticību Mozus, kad bija liels palicis, liedzās saukties par Faraona meitas dēlu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Un labāki gribēja ļaunu ciest ar Dieva ļaudīm, nekā uz īsu laiku baudīt grēka laimi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Un turēja Kristus negodu par lielāku bagātību nekā visas Ēģiptes mantas; jo viņš skatījās uz to algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Caur ticību viņš atstāja Ēģipti, nebīdamies no ķēniņa dusmības; jo viņš pastāvīgi turējās pie tā, kas nebija redzams, tā kā viņš to redzētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Caur ticību viņš turēja to Pasa un to aplaistīšanu ar asinīm, ka tas pirmdzimušo maitātājs tos neaiztiktu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Caur ticību tie gāja caur sarkano jūru tā kā pa sausumu, ko ēģiptieši arī raudzījuši un noslīkuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Caur ticību Jērikus mūri ir sagruvuši, kad tie septiņas dienas bija apstāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Caur ticību tā mauka Rahaba nav pazudusi līdz ar tiem neticīgiem, kad viņa tos izlūkus ar mieru bija uzņēmusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Un ko lai vēl vairāk saku? Man pietrūktu laika, kad es stāstītu par Gideonu un Baraku un Simsonu un Jeftu un Dāvidu un Samuēli un tiem praviešiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Kas caur ticību ķēniņu valstis ir uzvarējuši, taisnību darījuši, apsolīšanas panākuši, lauvu rīkles aizbāzuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Uguns spēku izdzēsuši, zobena asmenim izbēguši, atspirgušies no vājības, karā vareni tapuši, svešu kara spēku uz bēgšanu spieduši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Sievas savus mirušos caur augšāmcelšanos ir atdabūjušas, un citi grūti ir mocīti un to izglābšanu nav pieņēmuši, lai labāku augšāmcelšanos dabūtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Un citi mēdīšanas un pātagas ir cietuši un arī saites un cietumu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Ar akmeņiem ir nomētāti, ar zāģiem sagriezti, sadedzināti, caur zobenu nomaitāti, avju un kazu ādās viņi apkārt gājuši, atstāti, mocīti, bēdināti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(Kuru pasaule nebija vērta) tuksnešos maldījušies un kalnos un alās un zemes bedrēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Un šiem visiem caur ticību liecība ir bijusi, un tie nav panākuši, kas tiem bija solīts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Tādēļ ka Dievs priekš mums ko labāku papriekš bija izredzējis, ka tie netaptu pilnīgi bez mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Tad nu arī mēs, kad tāds liels pulks liecinieku ir visapkārt ap mums, lai noliekam ikvienu nastu un to grēku, kas mūs visai apstāj, un ar pacietību lai tekam iekš tās mums noliktās cīnīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Un lai skatāmies uz Jēzu, ticības iesācēju un pabeidzēju, kas, jebšu varējis priekā būt, krustu ir panesis un par kaunu nav bēdājis un ir sēdies pa labo roku Dieva goda krēslam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Ņemiet vērā Šo, kas tādu pretī runāšanu panesis no grēciniekiem, lai jūs nepiekūstat, savās dvēselēs pagurdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Jūs vēl neesat pretī stāvējuši līdz asinīm, cīnīdamies pret grēku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Un esat aizmirsuši to pamācīšanu, kas uz jums kā uz bērniem saka: mans dēls, neturi Tā Kunga pārmācīšanu par mazu lietu un nepagursti, kad tu no Viņa kļūsti pārmācīts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Jo ko Tas Kungs mīl, to Viņš pārmāca, un šausta ikvienu dēlu, ko Viņš uzņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Ja jūs to pārmācīšanu paciešat, tad Dievs turas pret jums kā pret bērniem; jo kur ir dēls, ko tēvs nepārmāca?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Bet ja esat bez pārmācīšanas, pie kuras visiem ir daļa bijusi, tad jūs esat maukas bērni un ne dēli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Un ja mums mūsu miesīgie tēvi ir bijuši par pārmācītājiem un mēs tos esam bijušies, - vai ne daudz vairāk Tam garu Tēvam būsim paklausīgi un dzīvosim?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Jo viņi gan mazu brīdi, kā paši zinādami, mūs ir pārmācījuši, bet Šis mūs pārmāca par labu, ka mums būtu daļa pie Viņa svētās būšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Bet ikviena pārmācīšana, klāt būdama, mums nešķiet līksmība esot, bet noskumšana; bet visu pēc tā dod taisnības un miera augļus tiem, kas caur to izmācīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Tādēļ paceļat atkal gurdenās rokas un slābanos ceļus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Un staigājat taisnus ceļus ar savām kājām, ka tas, kas tizls, nepaklūp, bet turpretī top dziedināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Dzenaties pēc miera ar visiem un pēc tās svētās dzīvošanas, bez kā neviens To Kungu neredzēs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Pielūkodami, ka neviens nezaudē Dieva žēlastību, ka nekāda rūgta sakne, augsti uzaugusi, jūs nesajauc, un ka daudzi caur to netop apgānīti;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Ka neviens nav maucinieks, nedz nesvēts, kā Ēsavs, kas savu pirmdzimtības tiesu ir pārdevis par vienu ēdienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Jo jūs zināt, ka tas arī pēc tam, lai gan gribēdams to svētību iemantot, tapa atmests; jo viņš neatrada žēlošanas vietu, jebšu to ar asarām meklēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Jo jūs neesat nākuši pie kalna, kas bija aiztiekams, un pie degoša uguns un krēslības un tumsības un vētras,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Un pie bazūnes skaņas un vārdu balss, par ko tie, kas to dzirdēja, ir lūgušies, ka uz tiem vairs netaptu runāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Jo tie nevarēja panest šo pavēli: ja arī kāds lops to kalnu aiztiktu, tad to būs ar akmeņiem nomētāt vai ar bultu nošaut.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Un tā parādīšana bija tik briesmīga, ka Mozus sacīja: es esmu pārbijies un drebu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Bet jūs esat nākuši pie Ciānas kalna, un pie Tā dzīvā Dieva pilsētas, pie debess Jeruzālemes un pie daudz tūkstošiem eņģeļu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Un pie pirmdzimušo sapulces un draudzes, kas debesīs pierakstīti, un pie Dieva, tā soģa pār visiem, un pie pilnīgi taisno gariem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Un pie Jēzus, jaunas derības vidutāja, un pie apslacināšanas asinīm, kas labāki runā nekā Ābels.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Pielūkojiet, ka jūs to, kas tur runā, neatmetiet. Jo kad tie nav izbēguši, kas to atmeta, kas virs zemes Dieva mācību runāja, tad mēs ne tik neizbēgsim, ja no tā novēršamies, kas ir no debesīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Viņa balss tai laikā zemi pakustināja; bet tagad Viņš ir pasludinājis sacīdams: vēl vienreiz Es kustināšu ne vien zemi, bet arī debesi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Un tas vārds „vēl vienreiz“parāda, ka tam, kas ir kustinājams, būs tapt pārceltam, jo tas ir darīts, lai paliek tas, kas nav kustinājams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Tādēļ nu, ka dabūjam nekustinājamu valstību, lai esam pateicīgi un tā lai Dievam kalpojam, kā Viņam labi patīk, ar baiļošanos un bijāšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Jo mūsu Dievs ir rijoša uguns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Brāļu mīlestība lai pastāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Neaizmirstiet labprāt dot mājas vietu; jo caur to daži nezinot eņģeļus ir uzņēmuši savās mājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Pieminiet tos saistītos, tā kā līdzsaistīti; un tos, kas ļaunumu cieš, kā tādi, kas paši arī vēl esiet miesā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Laulība lai ir godīga pie visiem un laulības gulta neapgānīta; bet mauciniekus un laulības pārkāpējus Dievs sodīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Jūsu dzīvošana lai ir bez mantas kārības; esiet mierā ar to, kas pie rokas, jo Viņš ir sacījis: Es tevi neatstāšu, nedz tevi pametīšu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Tā ka droši varam sacīt: Tas Kungs ir mans palīgs, un es nebīšos, ko man darīs cilvēks?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Pieminiet savus vadītājus, kas jums to Dieva vārdu runājuši. Uzlūkojiet viņu dzīvošanas galu un dzenaties viņu ticībai pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jēzus Kristus tas pats vakar un šodien un mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Neļaujaties šaubīties caur dažādām un svešām mācībām; jo tas ir labi, ka sirds top stiprināta caur žēlastību un ne caur ēdieniem, caur ko nekāds labums nav ticis tiem, kas tā staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Mums ir altāris, no kā ēst nevienam nav brīv, kas tai teltī Dievam kalpo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Jo kuru lopu asinis caur augsto priesteri par grēku top ienestas tai svētā vietā, to pašu miesas top sadedzinātas ārā, lēģera priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Tāpēc arī Jēzus, lai caur Savām paša asinīm ļaudis svētītu, ir cietis ārā priekš vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Tad nu lai izejam pie Viņa ārā, lēģera priekšā, nest Viņa negodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Jo šeitan mums nav paliekama pilsēta, bet to nākamo meklējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Tad nu lai caur Viņu Dievam allažiņ pienesam slavas upuri, tas ir, savu lūpu augļus, kas Viņa vārdu apliecina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Neaizmirstiet labu darīt un izdalīt, jo tādi upuri Dievam labi patīk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Paklausāt saviem vadītājiem un esat viņiem padevīgi; jo tie ir nomodā par jūsu dvēselēm, kā tādi, kam būs atbildēšanu dot, lai tie to dara ar prieku un ne nopūzdamies, jo tas jums nebūtu labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Lūdziet par mums, jo mēs apzināmies, ka mums, kas visās lietās gribam godīgi staigāt, ir laba zināma sirds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Un jo vairāk lūdzu to darīt, lai jo ātri jums topu atdots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Bet Tas miera Dievs, kas no miroņiem atkal atvedis To lielo avju ganu caur mūžīgas derības asinīm, mūsu Kungu Jēzu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Tas lai jūs dara pilnīgus iekš ikviena laba darba, ka jūs Viņa prātu dariet, un lai rada iekš jums, kas Viņam labi patīk, caur Jēzu Kristu, Viņam lai ir gods mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Bet es jūs lūdzu, brāļi, panesiet šo pamācīšanu, jo es jums īsiem vārdiem esmu rakstījis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Zināt, ka brālis Timotejs ir atlaists; ar to, (ja tas drīz nāk) es jūs redzēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Sveicinājiet visus savus vadītājus un visus svētos. Tie brāļi no Itālijas jūs sveicina.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Žēlastība lai ir ar jums visiem! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jēkabs, Dieva un Tā Kunga Jēzus Kristus kalps, sveicina tās divpadsmit ciltis, kas dzīvo svešumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Mani brāļi, turat to par tīru prieku, kad jūs iekrītat dažādās kārdināšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Zinādami, ka jūsu ticības pārbaudīšana rada pastāvību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Bet pastāvībai lai ir pilnīgs darbs, ka jūs esat pilnīgi un veseli, un ka jums nekā netrūkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Un ja kādam no jums gudrības trūkst, tas lai lūdzās no Dieva, kas visiem labprāt dod un nevienam nepārmet, - tad tā viņam taps dota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Bet lai lūdz ticībā, ne šaubīdamies; jo kas šaubās, tas ir līdzīgs jūras vilnim, ko vējš kustina un mētā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Jo tāds cilvēks lai nedomā, ka tas no Tā Kunga ko dabūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Divprātīgs cilvēks ir nepastāvīgs visos savos ceļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Bet zemas kārtas brālis lai lielās ar savu augstumu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Un kas ir bagāts, ar savu zemumu; jo viņš paiet kā zāles puķe.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Jo saule ir uzlēkusi ar karstumu un zāli izkaltējusi, un viņas puķe ir nokritusi un viņas vaiga jaukums nozudis; - tāpat arīdzan bagātais savītīs uz saviem ceļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Svētīgs ir tas vīrs, kas kārdināšanā pastāv, jo pārbaudīts viņš dabūs to dzīvības kroni, ko Tas Kungs ir solījis tiem, kas Viņu mīļo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Neviens, kas top kārdināts, lai nesaka, ka tas no Dieva top kārdināts; jo Dievs nevar tapt kārdināts uz ļaunu, un arī Pats nekārdina neviena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Bet ikviens top kārdināts, kad tas no savas paša kārības top skubināts un labināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Pēc tam, kad iekārošana ir ieņēmusies, tad tā dzemdē grēku, un kad grēks ir padarīts, tad tas dzemdē nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Nepieviļaties, mani mīļie brāļi!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Ikviena laba dāvana un ikviens pilnīgs dāvinājums nāk zemē no augšienes, no tā gaismas Tēva, pie kā nekādas pārmīšanās nedz pārvēršanās ēnas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Pēc Sava prāta Viņš mūs ir dzemdinājis caur to patiesības vārdu, ka mēs būtu Viņa radījumu pirmaji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Tad nu, mani mīļie brāļi, lai ikviens cilvēks ir čakls dzirdēt, bet lēns runāt un lēns dusmot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Jo cilvēka dusmība nedara, kas ir taisni Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Tāpēc noliekat visu nešķīstību un blēdību un pieņemat ar lēnprātību to iekš jums iedēstīto vārdu, kas jūsu dvēseles var darīt svētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Bet esiet tā vārda darītāji un ne tikai klausītāji, paši sevi pievildami;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Jo, ja kas ir tā vārda klausītājs, bet ne darītājs, tas ir līdzināms vīram, kas savu miesīgo vaigu aplūko spieģelī;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Jo viņš sevi aplūkojis un nogājis un tūdaļ aizmirsis, kādā vaigā viņš bijis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Bet kas locīdamies ieskatās pilnīgā svabadības bauslībā un paliek pie tās, un nav aizmirsīgs klausītājs, bet tā darba darītājs, tas būs svētīgs savā darīšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Ja kam šķiet, ka tas Dievam kalpojot, un nesavalda savu mēli, bet savu sirdi pieviļ, Tā Dieva kalpošana ir nelietīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Šķīsta un neapgānīta kalpošana Dieva un Tā Tēva priekšā ir šī, bāriņus un atraitnes viņu bēdās apmeklēt un sevi pašu pasargāt neapgānītu no pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mani brāļi, ticību uz Jēzu Kristu, mūsu godājamo Kungu, turēdami neuzlūkojiet cilvēka vaigu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Jo ja kāds vīrs nāktu jūsu baznīcā ar zelta gredzenu pirkstā un ar krāšņām drēbēm, un tur arīdzan nāktu kāds nabags ar rupjām drēbēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Un jūs uzlūkotu to, kam krāšņas drēbes, un uz to sacītu: sēdies tu še labā vietā; un sacītu uz to nabagu: stāvi tu tur, vai sēdies apakš manu kāju pamesla, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Vai tad jūs pie sev pašiem neesat starpību darījuši un neesat tapuši tiesneši pēc ļaunām domām spriezdami?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Klausiet, mani mīļie brāļi: vai Dievs nav izredzējis tos šās pasaules nabagus, kas ticībā ir bagāti un tās valstības mantinieki, ko Viņš ir apsolījis tiem, kas Viņu mīļo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Bet jūs tiem nabagiem negodu esat darījuši. Vai tie bagātie nav tie, kas jūs apspiež un jūs velk pie tiesām?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Vai tie nezaimo to labo vārdu, kas pār jums ir saukts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Ja tad jūs to ķēniņa bauslību piepildāt pēc tā raksta: tev būs savu tuvāko mīlēt kā sevi pašu, - tad jūs darāt labi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Bet ja jūs cilvēka vaigu uzlūkojiet, tad jūs grēku darāt un topat no bauslības pārliecināti kā pārkāpēji.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Jo kas visus baušļus tur un vienā klūp, tas ir noziedzies pie visiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Jo kas ir sacījis: tev nebūs laulību pārkāpt, - Tas arī sacījis: tev nebūs nokaut. Ja tu nu laulību nepārkāpi, bet nokauji, tad tu esi palicis par bauslības pārkāpēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Runājiet tā un dariet tā, kā tādi, kas caur svabadības bauslību taps tiesāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Jo tam, kas apžēlošanu nav parādījis, uzies sodība bez apžēlošanas, bet apžēlošana lielās pret sodību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Ko tas palīdz, mani brāļi, ja kas saka, ka viņam ir ticība, bet darbu nav? Vai tā ticība viņu var izglābt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Ja kāds brālis vai māsa pliki būtu un tiem trūktu dienišķas pārtikšanas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Un ja kāds no jums uz tiem sacītu: ejiet ar mieru, sildieties un paēdiet; bet jūs tiem nedotu kas miesai vajadzīgs, - ko tas palīdz?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Tāpat arīdzan ticība, ja tai darbu nav, pati par sevi tā nedzīva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Bet kāds varētu sacīt: tev ir ticība, un man ir darbi! Rādi man tavu ticību bez darbiem un es tev rādīšu no maniem darbiem ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu tici, ka ir viens vienīgs Dievs, un dari labi. Velni arīdzan tic un dreb.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Bet vai tu gribi zināt, tu nelietīgais cilvēks, ka ticība bez darbiem ir nedzīva?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Vai mūsu tēvs Ābrahāms nav taisnots no darbiem, savu dēlu Īzaku par upuri atnesdams uz altāri?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Tad tu redzi, ka ticība ar savu spēku ir bijusi pie viņa darbiem, un ticība ir tapusi pilnīga caur darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Un tas raksts ir piepildīts, kas saka: Ābrahāms Dievam ir ticējis un tas viņam ir pielīdzināts par taisnību, un viņš nosaukts Dieva draugs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Tad nu jūs redzat, ka cilvēks top taisnots no darbiem un ne no ticības vien.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Vai arī tā mauka Rahaba nav tāpat taisnota no darbiem, kad tā tos sūtītos ir uzņēmusi un pa citu ceļu izlaidusi?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Jo tā kā miesa bez gara ir nedzīva, tāpat arīdzan ticība bez darbiem ir nedzīva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Netopiet daudzi par mācītājiem, mani brāļi, zinādami, ka mēs grūtāku spriedumu dabūsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Jo mēs visi klūpam daudz; ja kas ne vārdā neklūp, tas ir pilnīgs vīrs, spēcīgs, arī savaldīt visu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Redzi, zirgiem liekam iemauktus mutē, lai tie mums paklausa, un valdām visu viņu miesu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Redzi, arī tādas lielas un no stipriem vējiem mētātas laivas top valdītas no mazas stūres, uz kurieni stūrmaņa prāts nesās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tāpat arī mēle ir mazs loceklis un daudz ko padara; redzi, maza uguns, kādu lielu mežu tā iededzina!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Mēle arīdzan ir uguns, pasaule pilna netaisnības; tāpat mēle starp mūsu locekļiem ir tas, kas visu miesu apgāna un iededzina visapkārt mūsu dzīvības ceļu, pati iededzināta no elles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Jo ikkatra daba, tā zvēru, kā putnu, tā tārpu, kā jūras zvēru, top valdīta un ir tapusi valdīta no cilvēcīgas dabas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Bet mēli neviens cilvēks nespēj savaldīt, to nepārvaramo ļaunumu ar nāves dzeloni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Ar to mēs slavējam To Kungu un Tēvu, un ar to mēs nolādam cilvēkus, kas pēc Dieva ģīmja radīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'No tās pašas mutes iziet svētīšana un lādēšana. Tam nebūs tā notikt, mani brāļi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Vai arī no tā paša akas avota izverd salds un rūgts?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Mani brāļi, vai vīģes koks var nest eļļas koka augļus, vai vīna koks vīģes? Tāpat aka nevar dot sāļu un saldu ūdeni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kurš ir gudrs un prātīgs starp jums? Tas lai rāda caur savu labo dzīvošanu savus darbus iekš lēnīgas gudrības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Bet ja jūs rūgtu bardzību un ienaidību turat savā sirdī, tad nelielāties un nemelojiet pret patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Šī nav tā gudrība, kas nāk no augšienes zemē, bet tā ir pasaules, dabas un velna gudrība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Jo kur bardzība un ienaids, tur ir sajukšana un visāds ļaunums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Bet tā gudrība, kas ir no augšienes, papriekš ir šķīsta, pēc tam mierīga, lēna, paklausīga, pilna apžēlošanas un labu augļu, taisna un bez liekulības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Bet taisnības auglis top sēts iekš miera tiem, kas mieru dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'No kurienes kari un kaušanās jūsu starpā? Vai ne no turienes, no jūsu kārībām, kas karo jūsu locekļos?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Jūs iekārojiet, un jums nav nenieka; jūs ienīstiet un skaužat un nevarat iedabūt; jūs kaujat un karojat, tomēr jums nav nenieka, tādēļ ka jūs nelūdziet,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Jūs lūdziet un nedabūjiet, tāpēc ka nepareizi lūdziet, lai to savās kārībās varētu aprīt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Jūs laulības pārkāpēji un laulības pārkāpējas, vai jūs nezināt, ka šīs pasaules draudzība ir Dieva nīšana? Kas tad grib būt pasaules draugs, tas paliek Dievam par ienaidnieku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Jeb vai jums šķiet, ka tas Raksts velti saka: Tam Garam, kas iekš mums mājo, gribās(ilgojās) pret To (ar) skaudību?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Bet Viņš dod lielāku žēlastību; tādēļ (tas raksts) saka: Dievs lepniem turas pretī, bet pazemīgiem Viņš dod žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Tad nu padodaties Dievam, stāviet velnam pretī, tad viņš bēgs no jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Nāciet tuvu pie Dieva, tad Viņš nāks tuvu pie jums. Šķīstiet rokas, jūs grēcinieki, un dariet sirdis šķīstas, jūs divprātīgie!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Esiet bēdīgi un noskumuši un raudāt; jūsu smiekli lai pārvēršas par vaidiem, un jūsu līksmība par skumību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Pazemojaties Tā Kunga priekšā, tad Viņš jūs paaugstinās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Neaprunājiet cits citu, brāļi; kas brāli aprunā un savu brāli tiesā, tas aprunā bauslību un tiesā bauslību; bet ja tu bauslību tiesā, tad tu neesi bauslības darītājs, bet tiesātājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Viens vienīgs ir Tas bauslības devējs un tiesātājs; Tas var pestīt un nomaitāt. Kas tu tāds esi, ka tu citu tiesā?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nu tad jūs, kas sakāt: šodien vai rītu mēs iesim uz šo vai to pilsētu un tur padzīvosim vienu gadu un pirksim un pārdosim un pelnīsimies;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Un nezināt, kas rītu notiks, - jo kāda ir jūsu dzīvība? Tā ir tvaiks, kas mazu brīdi rādās un pēc iznīkst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Tai vietā jums būtu jāsaka: Ja Tas Kungs gribēs un mēs dzīvosim, tad mēs šo vai to darīsim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Bet nu jūs lielāties savā lepnībā; visa tāda lielīšanās ir ļauna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Tad nu, kas zina labu darīt un nedara, tam tas ir par grēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Tad nu jūs bagātie, raudāt un kaucat par tām bēdām, kas pār jums nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Jūsu bagātība ir sapuvusi, un jūsu drēbes no kodēm saēstas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Jūsu zelts un sudrabs ir sarūsējis, un viņu rūsa jums būs par liecību un aprīs jūsu miesas tā kā uguns, jūs esat mantas krājušies pēdīgās dienās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Redzi, strādnieku, jūsu tīrumu pļāvēju alga, ko jūs atrāvuši, brēc, un to pļāvēju brēkšana ir nākusi priekš Tā Kunga Cebaot ausīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Jūs esat kāri dzīvojuši virs zemes un kārību dzinuši, jūs savas sirdis esat barojuši, tā kā uz kaujamu dienu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Jūs esat nosodījuši, jūs esat nokāvuši taisno, viņš jums pretī neturas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Tad nu esiet pacietīgi, brāļi, līdz Tā Kunga atnākšanai. Redzi, arājs gaida tos dārgos zemes augļus, pacietīgi uz tiem cerēdams, tiekams dabū to agro un to vēlo lietu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Esiet arī jūs pacietīgi, stiprinājiet savas sirdis, jo Tā Kunga atnākšana ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Nenopūšaties cits pret citu, brāļi, lai netopat tiesāti. Redzi soģis stāv priekš durvīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Mani brāļi, ņematies par ciešanas un pacietības priekšzīmi tos praviešus, kas ir runājuši Tā Kunga Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Redzi, mēs tos teicam svētīgus, kas bijuši pacietīgi; jūs Ījaba paciešanu esat dzirdējuši un Tā Kunga galu redzējuši, ka Tas Kungs ir sirdsžēlīgs un apžēlotājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Bet pār visām lietām, mani brāļi, nezvērējiet, nedz pie debess, nedz pie zemes, nedz kādu citu zvērestu; bet jūsu jā! lai ir jā! un jūsu nē! lai ir nē! lai jūs neiekrītat sodībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Ja kas jūsu starpā cieš, tas lai Dievu lūdz; ja kas ir līksmā prātā, tas lai dzied slavas dziesmas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ja kas jūsu starpā nevesels, tas lai aicina draudzes vecajus: lai tie par viņu lūdz, viņu svaidīdami ar eļļu Tā Kunga Vārdā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Un tā ticības lūgšana izglābs neveselo, un Tas Kungs viņu pacels, un ja viņš grēkus būtu darījis, tad tie viņam taps piedoti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Izsūdziet cits citam noziegumus un lūdziet cits par citu, ka topat veseli. Taisna cilvēka sirsnīga lūgšana daudz ko iespēj.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elija bija cilvēks, mums līdzīgs, un lūgdams lūdza Dievu, ka lietus nelītu; un lietus nelija virs zemes trīs gadus un sešus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Un viņš atkal lūdza, un debess deva lietu, un zeme nesa savus augļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Brāļi, ja kas jūsu starpā ir nomaldījies no patiesības, un ja kāds to atgriež,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Tam būs zināt: kas grēcinieku atgriež no viņa maldīšanās ceļa, tas viņa dvēseli izglābs no nāves un apklās grēku pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pēteris, Tā Kunga Jēzus Kristus apustulis, tiem izredzētiem svešiniekiem, kas mīt pa Pontu, Galatiju, Kapadoķiju, Āziju un Bitiniju,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Kas izredzēti pēc Dieva, Tā Tēva, paredzēšanas, iekš Tā Gara svētu darīšanas, uz paklausīšanu un uz apslacīšanu ar Jēzus Kristus asinīm: žēlastība un miers lai pie jums vairojās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Slavēts lai ir mūsu Kunga Jēzus Kristus Dievs un Tēvs, kas pēc Savas lielās apžēlošanas mūs atdzemdinājis uz dzīvu cerību caur Jēzus Kristus augšāmcelšanos no miroņiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Uz neiznīcīgu un neapgānītu un nesavīstamu mantību, kas top paturēta debesīs priekš jums,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Kas iekš Dieva spēka topat glabāti caur ticību uz pestīšanu, kas ir gatava parādīties pēdīgā laikā:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Par to jūs priecājaties, mazu brīdi tagad, ja vajag, noskumdināti dažādās kārdināšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Lai jūsu pārbaudītā ticība top atrasta dārgāka nekā zelts, kas iznīkst un ugunī kļūst pārbaudīts, - par slavu un godu un teikšanu, kad Jēzus Kristus taps redzams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'To neredzējuši jūs mīlat un, jebšu tagad Viņu neredzat, tomēr ticēdami uz Viņu, priecājaties ar neizsakāmu un godības pilnu prieku,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Panākdami savas ticības gala mērķi, dvēseļu pestīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Pēc šīs pestīšanas rūpīgi vaicājuši un meklējuši tie pravieši, kas par to jums novēlēto žēlastību papriekš sludinājuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Izmeklēdami, kuru un kādu laiku Kristus Gars, kas iekš tiem bija, zīmēja, papriekš apliecinādams Kristus ciešanas un to godību pēc tām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Tiem ir parādīts, ka tie nav kalpojuši sev pašiem, bet jums ar to, ko jums tagad pasludinājuši tie prieka sludinātāji iekš Svētā Gara, kas no debesīm sūtīts; tādas lietas skatīties arī eņģeļiem ļoti gribās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Tāpēc apjoziet savas sirds gurnus un skaidrā prātā ceriet pilnīgi uz to žēlastību, kas jums taps atnesta, kad Jēzus Kristus parādīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Kā paklausīgi bērni neturaties pēc tām iekārošanām, kurām jūs līdz šim savā nezināšanā klausījāt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Bet, kā jūsu Aicinātājs ir svēts, tāpat arī jūs topat svēti visā dzīvošanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Jo ir rakstīts: esiet svēti, jo Es esmu svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Un ja jūs to kā Tēvu piesauciet, kas cilvēka vaigu neuzlūkodams tiesā pēc ikviena darba, tad dzīvojiet iekš bijāšanas šinī laikā, kamēr šeitan mītat;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Zinādami, ka jūs neesat atpirkti ar iznīcīgu mantu, ar sudrabu vai zeltu no savas nelietīgās dzīvošanas pēc tēvu ieraduma,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Bet ar Kristus, tā nenoziedzīga un neapgānīta jēra, dārgām asinīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Tas papriekš paredzēts priekš pasaules radīšanas, un redzams tapis šinīs pēdīgos laikos jūsu labad,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Kas caur Viņu ticat uz Dievu, kas To ir uzmodinājis no miroņiem un Tam godību devis, tā ka jūsu ticība arī ir cerība uz Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Un savas dvēseles šķīstījuši, tai patiesībai paklausot caur To Garu uz neviltīgu brāļu mīlestību, mīliet savā starpā no šķīstas sirds un bez mitēšanās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Jūs, kas esat atdzimuši ne no iznīcīgas sēklas, bet no neiznīcīgas caur to dzīvo un mūžīgi paliekamo Dieva vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Jo visa miesa ir kā zāle un visa cilvēka godība kā zāles puķe; zāle ir savītusi un viņas puķe nokritusi;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Bet Tā Kunga vārds paliek mūžīgi. Bet šis ir tas vārds, kas jūsu starpā ir pasludināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Bet nu atstājiet visu ļaunumu un visu viltību un liekulību un skaudību un visas aprunāšanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Tā kā jaunpiedzimuši bērniņi iekārojaties to garīgo bezviltīgo pienu, ka jūs caur to uzaugat,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Ja jūs esat baudījuši, ka Tas Kungs ir laipnīgs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Pie Tā jūs esat nākuši kā pie dzīva akmens, gan atmests no cilvēkiem, bet izredzēts un dārgs pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Un jūs paši arīdzan kā dzīvi akmeņi topat uztaisīti par garīgu namu un svētu priesterību, garīgus upurus upurēt, kas Dievam ir pieņēmīgi caur Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Jo rakstos stāv(rakstīts): redzi, Es lieku Ciānā izredzētu, it dārgu stūra akmeni; un kas tic uz Viņu, tas nepaliks kaunā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Tad nu jums, kas ticat, Viņš ir dārgs; bet tiem neklausīgiem tas akmens, ko tie nama taisītāji atmetuši, kas ir palicis par stūra akmeni, ir arī klupšanas akmens un piedauzīšanās klints,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Tiem, kas neklausīgi būdami pie tā vārda piedauzās, uz ko tie arīdzan ir nolikti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Bet jūs esat izredzēta tauta, ķēniņu priesterība, svēta cilts, Dieva īpaši ļaudis; ka jums būs pasludināt Tā tikumus, kas jūs aicinājis no tumsības pie Savas brīnišķās gaismas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Jūs, kas citkārt nebijāt Dieva ļaudis, bet tagad esat Dieva ļaudis, kas citkārt nebijāt apžēloti, bet tagad esat apžēloti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Mīļie, es jūs pamācu kā piemājotājus un svešiniekus, ka jums būs noturēties no miesīgām kārībām, kas pret dvēseli karo,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Un ka jūs dzīvojiet godīgi starp tiem pagāniem, lai kurās lietās tie jūs aprunā kā ļaundarītājus, tie to labo darbu dēļ, ko tie pie jums redz, Dievu pagodina tai piemeklēšanas dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Tad esiet ikvienai cilvēku kārtībai paklausīgi Tā Kunga dēļ: gan ķēniņam, kā tādam, kas pār visiem ir iecelts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Gan valdniekiem, kā tādiem, kas no viņa ir sūtīti par atriebšanu ļaundarītājiem, bet par slavu laba darītājiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Jo tāds ir Dieva prāts, ka jūs labu darīdami, muti aizbāžat neprātīgu cilvēku nezināšanai,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Kā svabadnieki, un ne tā kā jums svabadība būtu par ļaunuma apsegu, bet tā kā Dieva kalpi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Turiet visus godā; mīlējiet brāļu draudzību; bīstaties Dievu, godājiet ķēniņu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Jūs kalpi, esiet paklausīgi tiem kungiem iekš visas bijāšanas, ne vien tiem labiem un lēniem, bet arī tiem bargiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Jo tā ir žēlastība, ja, kas Dievu apzinādamies, grūtumu panes netaisnību ciezdams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Jo kāda slava ir šī, ja jūs apgrēkodamies topat pliķēti un panesat? Bet ja jūs labu darīdami ciešat un panesat, tā ir žēlastība pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Jo uz to jūs esat aicināti, kā arī Kristus priekš jums ir cietis un jums priekšzīmi pametis, ka jums būs pakaļ iet Viņa pēdām:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Tas grēkus nav darījis, nedz viltība ir atrasta Viņa mutē,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Tas lamāts neatlamāja un ciezdams neļaunojās, bet nodeva to Tam, kas taisni tiesā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Tas mūsu grēkus Pats ir nesis Savā miesā pie tā koka, ka mēs, no grēkiem vaļā tikuši, taisnībai dzīvotu; caur Viņa brūcēm jūs esat dziedināti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Jo jūs bijāt tā kā avis, kas maldās, bet tagad jūs esat atgriezti pie savu dvēseļu gana un bīskapa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Tāpat jūs sievas, esiet paklausīgas saviem vīriem, lai arī, ja kādi tam vārdam neklausa, tie caur to sievu dzīvošanu top pielabināti bez vārda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Ievērodami jūsu šķīsto dzīvošanu iekš bijāšanas;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Jūsu jaukums lai nav no ārienes matu pīšanā un zelta aplikšanā, vai drēbju apvilkšanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Bet tas apslēptais sirds cilvēks, kam neiznīcīgs jaukums lēnā, klusā garā, - tas ir dārgs priekš Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Jo tāpat arī citkārt tās svētās sievas izgreznojās, kas cerēja uz Dievu un bija paklausīgas saviem vīriem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Tā kā Sāra Ābrahāmam bijusi paklausīga, viņu par kungu saukdama; tai jūs esat tapušas meitas, kad jūs labu dariet un par nekādu biedināšanu neizbīstaties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Tāpat jūs vīri, dzīvojat prātīgi ar to sievišķi, kā ar to vājāko rīku un dodat tām godu, kā žēlastības un dzīvības līdzmantiniecēm, lai jūsu lūgšanas netop aizkavētas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Un beidzot esiet visi vienprātīgi, līdzcietīgi, brālīgi, sirds žēlīgi, laipnīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Neatmaksādami ļaunu ar ļaunu, nedz lamāšanu ar lamāšanu; bet turpretī svētījiet, zinādami, ka jūs uz to esat aicināti, ka jums svētību būs iemantot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Jo kas grib dzīvību mīlēt un labas dienas redzēt, tas lai savu mēli klusina no ļauna un savas lūpas, ka tās viltību nerunā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Lai tas novēršas no ļauna un dara labu; lai tas meklē mieru, un tam dzenās pakaļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Jo Tā Kunga acis ir pār taisniem un viņa ausis uz viņu lūgšanām, bet Tā Kunga vaigs ir pretī tiem, kas ļaunu dara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Un kas jums ļaunu darīs, ja jūs tam labam dzenaties pakaļ?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Bet ja jums arī jācieš taisnības dēļ, tad jūs esat svētīgi; un nebīstaties par viņu biedināšanu, nedz iztrūcinājaties.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Bet svētījiet Dievu To Kungu savās sirdīs. Un esat arvien gatavi ar lēnību un bijāšanu atbildēt ikkatram, kas atbildēšanu prasa par to cerību, kas ir iekš jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Un lai jums ir laba zināma sirds, ka, kurās lietās jūs aprunā kā ļaundarītājus, tie top kaunā, kas jūsu labo dzīvošanu iekš Kristus zaimo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Jo tas ir labāki, ka jūs labu darīdami, ja Dieva prātam patīk, ciešat, nekā ļaunu darīdami');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Jo arī Kristus vienreiz par grēkiem ir cietis, taisnais par netaisniem, ka Viņš mūs Dievam pievestu, miesā gan nonāvēts, bet dzīvs darīts garā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Kurā Viņš ir nogājis un arī tiem gariem, kas cietumā, sludinājis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Kas citkārt bija neklausīgi, kad Dieva lēnība vienreiz gaidīja Noas dienās, kad tas šķirsts tapa taisīts, kurā maz (tas ir astoņas) dvēseles tapa izglābtas caur ūdeni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Un tā tur zīmēta kristība arī mūs tagad izglābj, - ne miesas sārņu nolikšana, bet labas zināmas sirds derība ar Dievu - caur Jēzus Kristus augšāmcelšanos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Tas ir pie Dieva labās rokas uzkāpis debesīs, un Tam ir paklausīgi eņģeļi un valdības un vara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Kad nu Kristus par mums ir cietis miesā, tad apbruņojaties ar to pašu prātu, - jo kas cieš miesā, tas mitās no grēkiem, -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Ka miesā būdami to vēl atliekamo laiku vairs nedzīvojat cilvēku kārībām, bet Dieva prātam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Jo tas ir gan, ka to pagājušo dzīvības laiku pēc pagānu prāta esam pavadījuši un staigājuši iekš bezkaunīgām kārībām, vīna plītešanām, rīšanām, dzeršanām un negantām elkadievībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Tā tiem ir sveša lieta, ka jūs ar tiem līdz nestaigājiet tai pašā palaidnības postā, un tādēļ tie zaimo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Šie atbildēšanu dos Tam, kas ir gatavs tiesāt dzīvus un mirušus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Jo tāpēc arī mirušiem evaņģēlijs ir sludināts, ka tie kā cilvēki gan top sodīti miesā, bet Dievam dzīvo garā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Visu lietu gals ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Tad nu esiet prātīgi un modrīgi uz Dieva lūgšanām. Pār visām lietām turiet sirsnīgu mīlestību savā starpā, jo mīlestība apsedz grēku pulku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Dodiet mājas vietu cits citam labprāt bez kurnēšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Lai viens otram kalpo, ikviens ar to dāvanu, kā tas ir dabūjis, kā labi nama turētāji par tām dažādām Dieva dāvanām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Ja kas runā, tas lai runā tā kā Dieva vārdus; ja kam kāds amats, lai tas to izdara itin pēc tā spēka, ko Dievs pasniedz, ka visās lietās Dievs top godināts caur Jēzu Kristu, kam pieder gods un vara mūžīgi mūžam. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Mīļie, nebrīnaties par to bēdu karstumu jūsu starpā, kas jums notiek par pārbaudīšanu, tā kā jums uzietu sveša lieta;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Bet itin kā jums ir daļa pie Kristus ciešanām, tā priecājaties, ka jūs arī Viņa godības parādīšanā varētu priecāties un gavilēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Ja topat nievāti Kristus vārda dēļ, svētīgi esiet! Jo tas godības un Dieva Gars dus uz jums; caur viņiem Tas top zaimots, bet caur jums Tas top pagodināts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Jo neviens no jums lai necieš kā slepkava vai zaglis vai ļaundarītājs vai kā tāds, kas jaucās svešā amatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Bet ja kas cieš kā kristīgs cilvēks, tad lai tas nekaunas, bet Dievu pagodina šinī lietā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Jo laiks ir klāt, ka sodība iesākās pie Dieva nama; bet ja tā papriekš pie mums iesākās, kāds būs gals tiem, kas Dieva evaņģēlijam nav paklausījuši;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Un ja taisnais tik ar mokām top izglābts, kur paliks bezdievīgais un grēcinieks?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Tad nu arī tiem, kas pēc Dieva prāta cieš, iekš laba darīšanas, būs pavēlēt savas dvēseles Viņam, kā Tam uzticīgam Radītājam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Tos vecajus jūsu starpā pamācu, es tas līdzvecākais un liecinieks par Kristus ciešanām un tās godības biedrs, kas taps redzams:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Ganiet Dieva ganāmo pulku, kas pie jums, un uzraugiet, ne piespiesti, bet ar labu prātu, ne negodīgas peļņas dēļ bet no sirds,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Nedz kā valdīdami par Tā Kunga daļu, bet (par) priekšzīmi būdami tam ganāmam pulkam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Un kad Tas Augstais Gans atspīdēs, tad jūs dabūsiet to nesavīstamo godības kroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Tāpat, jūs jaunākie, esiet tiem vecajiem paklausīgi; bet visi, cits citam padodamies, esiet izpušķoti ar pazemību, jo Dievs lepniem turas pretī, bet pazemīgiem Viņš dod žēlastību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Tad nu pazemojaties apakš Dieva varenās rokas, lai Viņš jūs paaugstina savā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Visu savu zūdīšanos metiet uz Viņu, jo Viņš gādā par jums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Esiet skaidrā prātā, esiet nomodā, jo jūsu pretinieks, velns, staigā apkārt kā rūcošs lauva, un meklē, kuru tas aprītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Tam stāviet pretim, stipri ticībā, zinādami, ka tās pašas ciešanas papilnam uziet jūsu brāļiem pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Bet Tas visu žēlīgais Dievs, kas mūs aicinājis uz Savu mūžīgo godību iekš Kristus Jēzus, Tas jūs, kas mazu brīdi ciešat, Pats sataisīs, spēcinās, stiprinās, pastāvīgus darīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Tam lai ir gods un vara mūžīgi mūžam. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Caur Silvanu, to uzticīgo brāli, es jums, kā man šķiet īsiem vārdiem esmu rakstījis, pamācīdams un apliecinādams, ka tā ir tā patiesā Dieva žēlastība, kurā jūs stāvat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Jūs sveicina tā līdz izvēlētā Bābeles draudze un mans dēls Marks.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Sveicinājaties savā starpā ar mīlestības skūpstu. Miers jums visiem, kas iekš Kristus Jēzus. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Sīmanis Pēteris, Jēzus Kristus kalps un apustulis, tiem, kas to pašu dārgo ticību līdz ar mums ir dabūjuši, iekš mūsu Dieva un mūsu Pestītāja Jēzus Kristus taisnības:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Žēlastība lai ir jums un miers daudzkārtīgi caur Dieva un mūsu Kunga Jēzus atzīšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Tā kā Viņa dievišķais spēks mums visu, kas der pie dzīvošanas un dievbijības, ir dāvinājis caur Tā atzīšanu, kas mūs aicinājis caur Savu godību un spēku;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Caur ko mums tās visu lielās un dārgās apsolīšanas ir dāvinātas, lai jūs caur tām dalību dabūjiet pie dievišķas dabas, bēgdami no tā posta, kas ir pasaulē caur iekārošanu:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Tad nu visā spēkā uz to (apsolījumu) dzīdamies pasniedziet iekš savas ticības tikumu, un iekš tikuma atzīšanu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Un iekš atzīšanās sātību, un iekš sātības pacietību, un iekš pacietības dievbijību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Un iekš dievbijības brāļu mīlestību, un iekš brāļu mīlestības mīlestību (uz visiem).');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Jo ja viss tas pie jums ir un bagātīgi rodas, tad jūs nepaliksiet kūtri nedz neauglīgi iekš mūsu Kunga Jēzus Kristus atzīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Un ja kam tā nav, tas ir akls un stulbs, un tas ir aizmirsis, ka viņš šķīstīts no saviem veciem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Tādēļ, brāļi, darbojaties, lai jūsu aicināšana un izredzēšana jo stipra paliek, jo to darīdami jūs nekad nepaklupsiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Jo tā jums bagātīgi taps atvēlēta tā ieiešana mūsu Kunga un Pestītāja Jēzus Kristus mūžīgā valstībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Tādēļ es nemitēšos jums to allažiņ atgādināt, jebšu jūs to zināt un esat stiprināti tai patiesībā, kas jums tagad ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Jo man šķiet, ka ir pareizi, jūs modināt caur pamācīšanu, kamēr esmu šinī dzīvoklī,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Zinādams, ka mans dzīvoklis drīz būs jānoliek, tā kā arī mūsu Kungs Jēzus Kristus man darījis zināmu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Bet es gādāšu, ka arī pēc manas aiziešanas jūs arvien to varētu pieminēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Jo mēs neesam dzinušies pakaļ izgudrotām pasakām, kad mēs jums esam sludinājuši mūsu Kunga Jēzus Kristus spēku un atnākšanu, bet mēs paši Viņa augsto godību ar acīm esam redzējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Jo no Dieva, Tā Tēva, Viņš dabūjis slavu un godību, kad tāda balss uz Viņu notika no tās augsti teicamās godības: Šis ir Mans mīļais Dēls, pie kā Man ir labs prāts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Un šo balsi mēs esam dzirdējuši no debess nākam, kad mēs ar Viņu bijām uz tā svētā kalna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Un mums ir jo stiprs praviešu vārds, un jūs darāt labi, to vērā ņemdami tā kā sveci, kas spīd tumšā vietā, tiekams diena aust un rīta zvaigzne uzlec jūsu sirdīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'To pār visām lietām atzīdami, ka neviena praviešu mācība rakstos nav izstāstāma pēc cilvēku domām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Jo praviešu mācība nekad nav notikusi caur cilvēka gribēšanu, bet tie svētie Dieva cilvēki ir runājuši, dzīti no Svētā Gara.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Bet arī viltīgi pravieši bijuši starp tiem ļaudīm, kā arī jūsu starpā būs viltīgi mācītāji, kas paslepen ievedīs svešas posta mācības un To Kungu, kas tos atpircis, aizliegdami pelnīsies ātru pazušanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Un daudzi dzīsies pakaļ viņu palaidnībām; un caur viņiem tas patiesības ceļš taps zaimots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Un mantas kārības pēc viņi ar viltīgi izdomātiem vārdiem pie jums ielabināsies; par tiem tā sodība jau sen nekavējās un viņu posts nesnauž.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Jo ja Dievs nav saudzējis tos eņģeļus, kas apgrēkojušies, bet tos nogāzis ellē un nodevis tumsības saitēm, ka tie taptu paturēti uz sodību;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Un ja nav saudzējis to veco pasauli, bet Nou, to taisnības sludinātāju, līdz ar septiņiem citiem ir pasargājis, kad plūdus uzveda tai bezdievīgai pasaulei,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Un tās pilsētas Sodomu un Gomoru pelnos likdams caur izdeldēšanu nosodījis un iecēlis par priekšzīmi tiem, kas bezdievīgi dzīvos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Un ir izrāvis to taisno Latu, kas caur šo neganto cilvēku nešķīsto dzīvošanu bija grūtumu cietis,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(Jo šis taisnais cilvēks viņu starpā mājodams savā taisnā dvēselē ir mocījies dienu no dienas, redzēdams un dzirdēdams viņu negantos darbus):');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Tā Tas Kungs dievbijīgos zin izraut no kārdināšanas, bet netaisnos mocīšanai paturēt uz soda dienu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Bet visvairāk tos, kas staigā pēc miesas iekš nešķīstām kārībām un valdību nicina, kas ir droši, patgalvīgi, un kam nav bail, zaimot tos godā celtos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Lai gan eņģeļi, spēkā un varā lielāki būdami, nenes Tā Kunga priekšā tiesu pret tiem, zaimodami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Bet šie, tā kā neprātīgi zvēri, kas pēc savas dabas dzimuši, ka top gūstīti un nokauti, zaimodami, ko tie neprot, savā pazušanā arī pazudīs,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Dabūdami netaisnības algu. Tiem šķiet, saldumu esam, ikdienas kārībā dzīvot; tie ir traipekļu pilni un gānekļi un kārīgi savās viltībās, kad tie ir līdz ar jums mielastos;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Tiem ir acis pilnas ar laulības pārkāpšanu, un tie neatstājās no grēkiem, krāpdami nestiprinātas dvēseles, tiem sirds radināta uz negausību, lāstu bērni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Tie no tā īstenā ceļa atstādamies ir maldījušies un dzenās pakaļ Bileāma, Beora dēla, ceļam, kas netaisnības algu mīlēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Bet viņš tapa pārmācīts par savu pārkāpšanu, kad tas mēmais nastu nesējs lops ar cilvēka balsi runādams aizkavēja tā pravieša bezprātību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Tie ir akas bez ūdens, padebeši no viesuļa mētāti, kam visdziļākā tumsība top paturēta mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Jo lepnus un tukšus vārdus runādami, tie krāpj caur miesas kārībām un bezkaunībām tos, kas patiesi jau bija izbēguši no tiem, kas dzīvo iekš alošanās;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Apsola tiem svabadību, un paši ir pazušanas kalpi: jo no kura kāds ir pārvarēts, tā kalps viņš ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Jo ja tie caur Tā Kunga un Pestītāja Jēzus Kristus atzīšanu gan izbēguši no pasaules apgānīšanām, bet iekš tām atkal iepinušies top uzvarēti, tad pēc ar viņiem paliek niknāki nekā papriekš.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Jo tiem būtu bijis labāki, kad tie taisnības ceļu nebūtu atzinuši, nekā, kad to bija atzinuši, nogriezties no tā svētā baušļa, kas tiem bija iedots.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Bet tiem ir noticis pēc tā patiesīgā sakāmā vārda: suns atkal ierij savu vēmekli, un peldināta cūka atkal vārtās dubļos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Mīļie, jau šo otru grāmatu es jums rakstu, kur caur atgādināšanu jūs pamodināju uz sirds skaidrību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Ka jums būs pieminēt tos no tiem svētiem praviešiem papriekš sludinātos vārdus un Tā Kunga un Pestītāja pavēlēšanu no mums, tiem apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Papriekš to ziniet, ka pēdīgās dienās nāks smējēji, staigādami pēc savām pašu kārībām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Un sacīdami: kur ir Viņa atnākšanas apsolīšana? Jo no tā laika, kad tie tēvi ir aizmiguši, visas lietas paliek kā no radīšanas iesākuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Jo tīši tie negrib zināt, ka vecos laikos debesis bijušas un zeme, no ūdens un iekš ūdens pastāvēdama caur Dieva vārdu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Caur ko tā laika pasaule tapa maitāta ūdens plūdos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Bet tās debesis, kas tagad ir un tā zeme caur Viņa vārdu ir glabātas un top ugunij paturētas uz to bezdievīgo cilvēku sodības un nomaitāšanas dienu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Bet to jums būs zināt, mīļie, ka viena diena pie Tā Kunga ir kā tūkstoši gadi un tūkstoši gadi kā viena diena.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Tas Kungs nevilcina to apsolīšanu, kā kādiem šķiet, to esam vilcināšanu, bet Viņš ir lēnprātīgs pret mums, negribēdams, ka kāds pazūd, bet ka visi dodās uz atgriešanos no grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Bet Tā Kunga diena nāks kā zaglis naktī; tad debesis ar rūkšanu zudīs un tie pirmie pasaules sākumi no karstuma izkusīs, un zeme un tie darbi iekš tās sadegs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Tad nu, ja viss tas izkūst, cik ļoti tad jums pienākas staigāt svētā dzīvošanā un dievbijāšanā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Gaidot un steidzoties uz tās Dieva dienas atnākšanu, kur debesis degdamas zudīs un tie pirmie pasaules sākumi no karstuma izkusīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Bet mēs gaidām pēc Viņa apsolīšanas jaunas debesis un jaunu zemi, kur taisnība mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Tādēļ, mīļie, kad jūs šās lietas gaidāt, darbojaties, ka neapgānīti un bezvainīgi no Viņa topat atrasti iekš miera;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Un turiet mūsu Kunga lēnprātību par glābšanu, tā kā arī mūsu mīļais brālis Pāvils jums ir rakstījis pēc tās gudrības, kas tam dota,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Kā arī visās grāmatās, kur viņš par šīm lietām runā, no kurām citas grūti saprotamas, ko tie neizmācītie un nestiprinātie pārgroza, tā kā arī tos citus rakstus, sev pašiem par pazušanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Tad nu jūs, mīļie, to papriekš zinādami, sargājaties, ka jūs caur to neganto cilvēku pievilšanu līdz novesti neizkrītat no sava stipruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Bet pieaugat mūsu Kunga un Pestītāja Jēzus Kristus žēlastībā un atzīšanā. Tam lai ir gods gan tagad gan mūžīgos laikos! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Kas bija no iesākuma, ko esam dzirdējuši, ko ar savām acīm esam redzējuši, ko esam skatījuši, un ko mūsu rokas aptaustījušas, no tā dzīvības vārda,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(Ja dzīvība ir parādīta, un mēs to esam redzējuši, un apliecinām un pasludinām jums to mūžīgo dzīvību, kas bija pie Tā Tēva un mums ir parādīta,) -');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Ko esam redzējuši un dzirdējuši, - to mēs jums pasludinām, lai arī jums ir sadraudzība ar mums, un šī mūsu sadraudzība ir ar To Tēvu un ar Viņa Dēlu Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Un to mēs jums rakstam, lai jūsu prieks ir pilnīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Un šī ir tā sludināšana, ko no Viņa esam dzirdējuši un jums sludinājām: ka Dievs ir gaišums un iekš Viņa nav nekādas tumsības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Ja mēs sakām, ka mums ir sadraudzība ar Viņu, un ja tumsībā staigājam, tad melojam un nedarām patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Bet ja staigājam gaišumā, tā kā Viņš ir gaišumā, tad mums ir sadraudzība savā starpā, un Jēzus Kristus, Viņa Dēla, asinis mūs šķīsta no visiem grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ja mēs sakām, ka mums grēka nav, tad mēs paši pieviļamies, un patiesības nav iekš mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Ja mēs savus grēkus izsūdzam, tad Viņš ir uzticīgs un taisns, ka Viņš mums grēkus piedod un mūs šķīsta no visas netaisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Ja mēs sakām, ka neesam grēkojuši, tad mēs Viņu darām par melkuli, un Viņa vārds nav iekš mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mani bērniņi, to es jums rakstu, lai jūs negrēkojiet; un ja kas grēko, tad mums ir aizbildinātājs pie Tā Tēva, Jēzus Kristus, tas taisnais.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Un Viņš ir tā salīdzināšana par mūsu grēkiem, un ne vien par mūsu, bet arī par visas pasaules grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Un pie tam mēs nomanam, ka Viņu esam atzinuši, ja Viņa baušļus turam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kas saka: es Viņu pazīstu, un netur Viņa baušļus, tas ir melkulis, un patiesības nav iekš tā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Bet ja kas Viņa vārdu tur, iekš tā patiesi Dieva mīlestība ir pilnīga; pie tam mēs atzīstam, ka esam iekš Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kas teicās iekš Viņa paliekot, tam pienākas pašam arīdzan tāpat staigāt, kā Viņš ir staigājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Brāļi, es jums nerakstu jaunu bausli, bet vecu bausli, kas jums ir bijis no iesākuma. Šis vecais bauslis ir tas vārds, ko jūs no iesākuma esat dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Atkal jaunu bausli es jums rakstu, kas ir patiesība iekš Viņa un iekš jums: jo tumsība paiet un patiesā gaisma tagad spīd.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kas teicās esot gaismā un ienīst savu brāli, tas vēl ir tumsībā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kas savu brāli mīl, tas paliek gaismā, un iekš tā nav piedauzīšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Kas savu brāli ienīst, tas ir tumsībā un staigā tumsībā un nezina, kurp tas iet, jo tumsība viņa acis ir aptumšojusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Es jums rakstu, bērniņi, jo grēki jums top piedoti Viņa Vārda dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Es jums rakstu, tēvi, jo jūs To esat atzinuši, kas ir no iesākuma. Es jums rakstu, jaunekļi, jo jūs to ļauno esat uzvarējuši. Es jums esmu rakstījis, bērni, jo jūs To Tēvu esat atzinuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Es jums esmu rakstījis, tēvi, jo jūs To esat atzinuši, kas ir no iesākuma. Es jums esmu rakstījis, jaunekļi, jo jūs esat spēcīgi, un Dieva vārds paliek iekš jums, un jūs to ļauno esat uzvarējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Nemīlējiet pasauli nedz to, kas ir pasaulē; jo kas pasauli mīl, iekš tā nav Tā Tēva mīlestība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Jo viss, kas ir pasaulē: miesas kārība, acu kārība un dzīves lepnība - tas nav no Tā Tēva, bet no pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Un pasaule paiet un viņas kārība; bet kas Dieva prātu dara, tas paliek mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Bērniņi, nu ir tā pēdīgā stunda; un tā, kā jūs esat dzirdējuši, ka tas pretī-kristus nāk, tā arī tagad daudz pretī-kristi cēlušies, no tā mēs zinām pēdējo stundu esam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Tie no mums ir izgājuši, bet tie nebija no mums; jo ja tie būtu bijuši no mums, tad tie būtu palikuši pie mums, bet tiem bija parādīties, ka tie nav visi no mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Tomēr jums ir tā svaidīšana no Tā Svētā, un jūs visu zināt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Es jums neesmu rakstījis, tā kā jūs nezinātu patiesību, bet ka jūs to jau zināt, un ka no patiesības nenāk nekādi meli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kas ir tas melkulis, ja ne tas, kas liedz, ka Jēzus ir Tas Kristus? Tas ir tas pretī-kristus, kas liedz To Tēvu un To Dēlu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Ikvienam, kas To Dēlu liedz, tam arī nav Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Tad nu, ko jūs esat dzirdējuši no iesākuma, tas lai paliek iekš jums; ja iekš jums paliek, ko no iesākuma esat dzirdējuši, tad arī jūs paliksiet iekš Tā Dēla un Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Un šī ir tā apsolīšana, ko Viņš mums ir apsolījis, (proti) to mūžīgo dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'To es jums esmu rakstījis par tiem, kas jūs pieviļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Un tā svaidīšana, ko jūs no Viņa esat dabūjuši, paliek iekš jums, un jums nevajag, ka kāds jūs māca; bet tā kā šī pati svaidīšana jūs māca visās lietās, tā viņa arīdzan ir patiesīga un nav meli. Un, kā tā jūs ir mācījusi, tā paliekat iekš Viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Un nu, bērniņi, paliekat iekš Viņa; lai, kad Viņš parādīsies, mums ir drošība un mēs no Viņa netopam kaunā likti Viņa atnākšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Ja jūs zināt, ka Viņš ir taisns, tad zināt, ka ikviens, kas taisnību dara, no Viņa ir piedzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Redziet, kādu lielu mīlestību Tas Tēvs mums ir parādījis, ka mēs topam saukti Dieva bērni. Tāpēc pasaule mūs nepazīst, ka tā Viņu nepazīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Mīļie, tagad mēs esam Dieva bērni, un vēl nav atspīdējis, kas mēs būsim; bet mēs zinām, ka, kad Tas atspīdēs, mēs Viņam būsim līdzīgi, jo mēs Viņu redzēsim, kāds Viņš ir.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Un ikviens, kam šī cerība uz Viņu, šķīsta sevi pašu, tā kā Viņš ir šķīsts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Ikviens, kas grēku dara, tas dara arī netaisnību, un grēks ir netaisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Un jūs zināt, ka Viņš ir parādījies, lai Viņš mūsu grēkus atņemtu, un iekš Viņa nav grēka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Ikviens, kas iekš Viņa paliek, tas negrēko; ikviens, kas grēko, Viņu nav redzējis, nedz Viņu atzinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Bērniņi, lai neviens jūs nepieviļ: kas taisnību dara, tas ir taisns, tā kā Viņš ir taisns.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kas grēku dara, tas ir no velna, jo velns grēko no iesākuma. Tādēļ Dieva Dēls ir atspīdējis, ka Viņš velna darbus izārdītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Ikviens, kas no Dieva piedzimis, tas nedara grēku, jo Viņa sēkla paliek iekš tā un tas nevar grēkot, jo tas no Dieva ir piedzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Pie tam top zināmi Dieva bērni un velna bērni. Ikkatrs, kas taisnību nedara, tas nav no Dieva, un kas nemīl savu brāli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Jo šī ir tā sludināšana, ko jūs no iesākuma esat dzirdējuši, lai mēs cits citu mīlējam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ne tā kā Kains, kas bija no tā ļaunā un savu brāli nokāva. Un kādēļ viņš to nokāva? Tāpēc ka viņa darbi bija ļauni, bet viņa brāļa darbi taisni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Nebrīnāties, mani brāļi, ja pasaule jūs ienīst.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Mēs zinām, ka esam pārcelti no nāves uz dzīvību, tāpēc ka mēs tos brāļus mīlējam; kas nemīl, tas paliek nāvē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Ikviens, kas savu brāli ienīst, tas ir slepkava, un jūs zināt, ka nevienam slepkavam mūžīga dzīvība nav paliekama iekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Pie tam mēs esam atzinuši mīlestību, ka Viņš Savu dzīvību par mums ir nodevis, un mums arīdzan pienākas dzīvību nodot par tiem brāļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Bet ja kādam ir šās pasaules manta, un tas redz savu brāli trūkumu ciešam un aizslēdz savu sirdi priekš viņa, kā Dieva mīlestība paliek iekš tāda?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Mani bērniņi, lai mēs nemīlējam ar vārdiem, nedz ar mēli, bet ar darbiem un ar patiesību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Un pie tam mēs atzīstam, ka esam no patiesības, un savas sirdis Viņa priekšā varam klusināt,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Ka, ja mūsu sirds mūs pazudina, Dievs ir lielāks nekā mūsu sirds un zin visas lietas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mīļie, ja mūsu sirds mūs nepazudina, tad mums ir drošība pie Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Un ko vien mēs lūdzam, to no Viņa dabūjam, jo mēs turam Viņa baušļus un darām, kas Viņa priekšā ir patīkams.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Un šis ir Viņa bauslis, lai mēs ticam Viņa Dēla Jēzus Kristus Vārdam un lai cits citu mīlējam, tā kā Viņš mums bausli ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Un kas Viņa baušļus tur, tas paliek iekš Viņa un Viņš iekš tā. Un pie tam atzīstam, ka Viņš iekš mums paliek, no Tā Gara, ko Viņš mums devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mīļie, neticat ikkatram garam, bet pārbaudiet tos garus, vai tie no Dieva? Jo daudz viltīgi pravieši ir izgājuši pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Pie tam jūs atzīstat Dieva Garu: ikkatrs gars, kas apliecina, ka Jēzus Kristus nācis miesā, tas ir no Dieva:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Un ikkatrs gars, kas neapliecina, ka Jēzus Kristus nācis miesā, tas nav no Dieva. Un tas ir tā pretī-kristus gars, par ko jūs esat dzirdējuši, ka tas nāk, un tagad jau ir pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Bērniņi, jūs esat no Dieva un viņus esat uzvarējuši; jo kas iekš jums, Tas ir lielāks pār to, kas iekš pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Tie ir no pasaules, tāpēc tie runā no pasaules, un pasaule tos klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Mēs esam no Dieva: kas Dievu atzīst, tas mūs klausa; kas nav no Dieva, tas mūs neklausa. Pie tam mēs atzīstam to patiesības Garu un to alošanas garu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Mīļie, lai mēs cits citu mīlējam, jo mīlestība ir no Dieva, un ikviens, kas mīl, tas no Dieva ir dzimis un atzīst Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kas nemīl, tas Dievu neatzīst; jo Dievs ir mīlestība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Iekš Tā Dieva mīlestība pie mums ir parādījusies, ka Dievs Savu vienpiedzimušo Dēlu sūtījis pasaulē, ka mums caur Viņu būs dzīvot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Iekš tā stāv mīlestība, ne ka mēs esam mīlējuši Dievu, bet ka Viņš mūs ir mīlējis un Savu Dēlu sūtījis par salīdzināšanu par mūsu grēkiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Mīļie, ja Dievs mūs tā ir mīlējis, tad arī pienākas, ka mēs cits citu mīlējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Dievu nemūžam neviens nav redzējis. Ja mēs cits citu mīlējam, tad Dievs paliek iekš mums, un Viņa mīlestība ir pilnīga iekš mums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Pie tam mēs zinām, ka paliekam iekš Viņa, un Viņš iekš mums, ka Viņš no Sava Gara mums ir devis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Un mēs esam redzējuši un apliecinājam, ka Tas Tēvs To Dēlu ir sūtījis par pasaules Pestītāju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Ja kas apliecinās, ka Jēzus ir Dieva Dēls, tad Dievs paliek iekš viņa, un viņš paliek iekš Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Un mēs esam atzinuši un ticējuši (uz) to mīlestību, kas Dievam ir uz mums. Dievs ir mīlestība; un kas iekš mīlestības paliek, tas paliek iekš Dieva un Dievs iekš viņa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Iekš to mīlestība pie mums ir pilnīga, ka mums ir drošība tai tiesas dienā; jo kā Viņš ir, tāpat arī mēs esam šinī pasaulē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Bailības nav iekš mīlestības, bet pilnīga mīlestība bailību izmet ārā; jo bailībai ir mocība, un kas baiļojās, tas nav pilnīgs iekš mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Lai mēs Viņu mīlam, jo Viņš mūs papriekš ir mīlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Ja kas saka: es mīlu Dievu un ienīst savu brāli, tas ir melkulis: jo kas savu brāli nemīl, ko tas redz, kā tas Dievu var mīlēt, ko tas nav redzējis?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Un šis bauslis mums ir no Viņa, ka tam, kas mīl Dievu, arī savu brāli būs mīlēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Ikviens, kas tic, ka Jēzus ir Tas Kristus, tas no Dieva ir dzimis, un ikviens, kas To mīl, kas Viņu dzemdinājis, tas mīl arī to, kas no Viņa ir dzimis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Pie tam mēs atzīstam, ka Dieva bērnus mīlam, kad Dievu mīlam un Viņa baušļus turam;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Jo šī ir Tā Dieva mīlestība, ka mēs Viņa baušļus turam, un Viņa baušļi nav grūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Jo ikviens, kas no Dieva dzimis, uzvar pasauli; un šī pati ir tā uzvarēšana, kas pasauli uzvar, (proti) mūsu ticība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kas ir, kas pasauli uzvar, kā vien kas tic, ka Jēzus ir Dieva Dēls?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Šis ir tas, kas nācis caur ūdeni un asinīm, Jēzus Kristus, ne ar ūdeni vien, bet ar ūdeni un asinīm; un Tas Gars ir tas liecības devējs, jo Tas Gars ir tā patiesība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Jo trīs ir, kas liecību dod, (debesīs, Tas Tēvs, Tas Vārds un Tas Svētais Gars: un šie trīs ir viens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Un trīs ir, kas liecību dod virs zemes,) Tas Gars un tas ūdens un tās asinis: un šie trīs ir kopā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Ja mēs cilvēku liecību pieņemam, tad Dieva liecība ir jo liela; šī ir Tā Dieva liecība, ko Viņš par Savu Dēlu liecinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kas tic uz to Dieva Dēlu, tam ir tā liecība iekš sevis paša. Kas Dievam netic, tas Viņu ir darījis par melkuli, jo tas tai liecībai nav ticējis, ko Dievs par Savu Dēlu ir liecinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Un šī ir tā liecība, ka Dievs mums mūžīgu dzīvību ir devis, un šī dzīvība ir iekš Viņa Dēla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kam Tas Dēls ir, tam ir tā dzīvība. Kam Tas Dieva Dēls nav, tam nav tā dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'To es esmu rakstījis jums, kas ticiet uz Dieva Dēla vārdu, lai jūs zināt, ka jums ir mūžīga dzīvība, un ka jūs ticat uz Dieva Dēla vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Un šī ir tā drošība, kas mums ir uz Viņu, ka, ja mēs ko lūdzam pēc Viņa prāta, tad Viņš mūs klausa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Un ja mēs zinām, ka Viņš mūs klausa, kad ko lūdzam, tad zinām, ka tajās lūgšanās dabūjam (to), ko no Viņa esam lūguši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Ja kas savu brāli redz, ka tas apgrēkojās ar kādu grēku ne uz nāvi, tam būs Dievu lūgt, un Tas viņam dos dzīvību, (proti) tiem, kas apgrēkojās ne uz nāvi. Ir grēks uz nāvi; par to nesaku, ka būs lūgt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Ikviena netaisnība ir grēks; un ir grēks, kas nav uz nāvi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Mēs zinām, ka ikviens, kas no Dieva dzimis, negrēko; bet kas no Dieva dzimis, tas sargā sevi pašu, un tas ļaunais viņu neaizskar.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Mēs zinām, ka esam no Dieva, un visa pasaule ir nogrimusi ļaunumā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Bet mēs zinām, ka Dieva Dēls ir nācis un mums tādu prātu devis, ka atzīstam To patiesīgo un esam iekš Tā Patiesīgā, iekš Viņa Dēla Jēzus Kristus; šis ir Tas patiesīgais Dievs un tā mūžīgā dzīvība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Bērniņi, sargājaties no elkadieviem! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Tas vecākais tai izredzētai mātei un viņas bērniem, ko es patiesi mīlēju, un ne vien es, bet arī visi, kas patiesību atzinuši,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Tās patiesības dēļ, kas iekš mums paliek un ar mums būs mūžīgi:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Žēlastība, apžēlošana, miers lai ir ar jums no Dieva Tā Tēva un no Tā Kunga Jēzus Kristus, Tā Tēva Dēla, iekš patiesības un mīlestības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Es ļoti esmu priecājies, ka tavu bērnu starpā esmu atradis, kas staigā iekš patiesības, tā kā mēs bausli esam dabūjuši no Tā Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Un nu es tevi lūdzu, māte, ne tā kā jaunu bausli tev rakstīdams, bet kas mums no iesākuma bijis: lai mēs cits citu mīlējam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Un šī ir tā mīlestība, ka staigājam pēc Viņa baušļiem; šis ir tas bauslis, ka iekš tā staigājiet, kā no iesākuma esat dzirdējuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Jo daudz viltnieki ir nākuši pasaulē, kas neapliecina Jēzu Kristu esam nākušu miesā. Šis ir tas viltnieks un tas pretī-kristus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Lūkojiet uz sevi pašiem, ka nezaudējam, ko esam strādājuši, bet ka dabūjam pilnu algu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Nevienam, kas ir pārkāpējs un nepaliek iekš Kristus mācības, nav Dieva: kas iekš Kristus mācības paliek, tam ir Tas Tēvs un Tas Dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Ja kas nāk pie jums un šo mācību nenes, to neuzņemiet mājās un nesveicinājiet.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Jo kas viņu sveicina, tam ir daļa pie viņa ļauniem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Man vēl ir daudz ko jums rakstīt; bet es negribēju uz papīra un ar tinti; bet es ceru pie jums nākt un muti pret muti runāt, lai mūsu prieks ir pilnīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Tavas māsas, tās izredzētās, bērni tevi sveicina. Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Tas vecākais Gajum, tam mīļotam, ko es patiesībā mīlēju.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Mīļais, pār visām lietām es vēlēju, lai tev labi klājās, un tu esi vesels, tā kā tavai dvēselei labi klājās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Jo es ļoti esmu priecājies, kad tie brāļi nāca un apliecināja tavu patiesību, tā kā tu iekš patiesības staigā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Man lielāka prieka nav, nekā kad dzirdu savus bērnus staigājam iekš patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Mīļais, tu dari pēc ticības, ko tu dari pie tiem brāļiem, un vēl tiem no svešuma atnākušiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Kas ir devuši liecību par tavu mīlestību draudzes priekšā; un tu labi darīsi, kad tu tos izvadīsi, tā kā pieklājās Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Jo tie Viņa vārda dēļ ir izgājuši, neko no pagāniem neņemdami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Tad nu mums pienākas tos tādus uzņemt, ka mēs paliekam par darba biedriem pie patiesības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Es tai draudzei esmu rakstījis; bet Diotrefs, kas grib būt starp tiem tas augstākais, mūs nepieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Tādēļ, kad es nākšu, tad es viņa darbus pieminēšu, ko viņš dara, ar ļauniem vārdiem pret mums aprunādams; un ar to nebūdams mierā viņš pats tos brāļus neuzņem un aizliedz arī tiem, kas to grib darīt, un tos izmet no draudzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Mīļais, nedzenies tam ļaunam pakaļ, bet tam labam; kas labu dara, tas ir no Dieva, bet kas ļaunu dara, tas Dievu nav redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demeterim liecība top dota no visiem un no pašas patiesības, un mēs arīdzan liecību dodam, un jūs zināt, ka mūsu liecība ir patiesīga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Man daudz būtu ko rakstīt, bet es negribu tev rakstīt ar tinti un spalvu;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Bet es ceru drīz tevi redzēt, tad mēs muti pret muti runāsim. Miers lai ir ar tevi. Tie draugi tevi sveicina. Sveicini tos draugus pa vārdam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Jūda, Jēzus Kristus kalps un Jēkaba brālis, tiem aicinātiem, kas iekš Dieva Tā Tēva svētīti un iekš Jēzus Kristus pasargāti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Žēlastība lai ir jums un miers un mīlestība papilnam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Mīļie, no visas sirds rūpējoties jums rakstīt par to pestīšanu, kas mums visiem ir kopā, man vajadzēja jums rakstīt un lūgt, lai jūs cīnāties par to ticību, kas vienreiz tiem svētiem ir dota.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Jo kādi cilvēki ielavījušies, kas rakstos sen papriekš nozīmēti uz šo sodību, bezdievīgi, kas mūsu Dieva žēlastību pārvērš bezkaunībā un aizliedz to vienīgo valdītāju Dievu un mūsu Kungu Jēzu Kristu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Bet es jums, kas visu jau zināt, gribu atgādināt, ka Tas Kungs tos ļaudis no Ēģiptes zemes vienreiz pestījis, pēc tos neticīgos ir nomaitājis;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Un tos eņģeļus, kas savu augsto kārtu nav sargājuši, bet savu dzīvokli atstājuši, Viņš ar mūžīgām saitēm ir paturējis apakš tumsības uz tās lielās dienas sodu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Tā kā Sodoma un Gomora un tās apkārtējās pilsētas, kas tāpat kā viņas maucībai bija padevušās un citai miesai gājušas pakaļ, ir noliktas par mūžīgu uguns priekšzīmi, sodību ciezdamas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Tāpat arī šie sapņotāji apgāna miesu un nicina virsības un zaimo augstības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Bet Miķelis, tas lielais eņģelis, kad tas cīnījās ar velnu, un tam pretī runāja par Mozus miesām, neuzdrīkstējās zaimošanas tiesu pret to spriest, bet sacīja: lai Tas Kungs tevi soda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Bet šie zaimo, ko tie neprot; bet ko tie pēc dabas prot, tā kā bezprātīgie zvēri, iekš tā tie iet postā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ak vai, tiem, jo tie ir gājuši uz Kaina ceļu, un peļņas dēļ iegāzušies Bileāma alošanā un ir nomaitāti Koraha pretī runāšanā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Šie ir tie gānekļi pie jūsu mīlestības mielastiem, kopā plītēdami un bez bijāšanas barodamies, padebeši bez ūdens, vēju mētāti, kaili, neauglīgi, divkārt nomiruši, izsakņoti koki,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Bargi jūras viļņi, kas savu pašu kaunu putās izgāž; nomaldījušās zvaigznes, kam tā visdziļākā tumsība top uzglabāta mūžīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Bet par šiem arīdzan Enohs, tas septītais no Ādama, sludinājis sacīdams: redzi, Tas Kungs nāks ar Saviem daudz tūkstošiem svētiem,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Tiesu turēt par visiem, visus bezdievīgos starp tiem pārmācīt par visiem viņu bezdievīgiem darbiem, ko tie bezdievīgie darījuši, un par visiem negantiem vārdiem, ko tie bezdievīgie grēcinieki pret Viņu runājuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Šie ir kurnētāji un skundētāji, staigādami pēc savām kārībām un viņu mute runā lepnus vārdus, un tie apbrīno cilvēku augstību pelņas dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Bet jūs, mīļie, pieminiet tos vārdus, kas jums ir papriekš sacīti no mūsu Kunga Jēzus Kristus apustuļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Ka tie jums ir sacījuši, ka pēdējos laikos būs smējēji, pēc savām bezdievīgām kārībām staigādami.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Šie ir tie, kas ceļ šķiras, miesīgi cilvēki, kam gara nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Bet jūs, mīļie, uztaisāties savā vissvētākā ticībā, iekš Tā Svētā Gara lūgdamies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Turaties iekš Dieva mīlestības, gaidīdami mūsu Kunga Jēzus Kristus apžēlošanu uz mūžīgu dzīvošanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Un citus pārmāciet, kas ir šaubīgi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Un citus izglābiet, tos no uguns izraudami, un par citiem apžēlojaties ar bijāšanu, ienīdēdami arīdzan tās no miesas apgānītās drēbes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Bet Tam, kas ir spēcīgs jūs pasargāt, ka neklūpat, un Savas godības priekšā bezvainīgus stādīt ar līksmību,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Tam vienam gudram Dievam, mūsu Pestītājam, lai ir gods un augsta slava, spēks un vara, tagad un mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Jēzus Kristus parādīšana, ko Dievs Viņam ir devis, rādīt Saviem kalpiem to, kam būs notikt drīzumā, un ko Viņš ir zināmu darījis caur Savu eņģeli sūtīdams Savam kalpam Jānim.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Tas ir apliecinājis Dieva vārdu un Jēzus Kristus liecību un visu, ko viņš redzējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Svētīgs ir tas, kas to lasa, un tie, kas dzird šās praviešu mācības vārdus un patur, kas te ir rakstīts; - jo tas laiks ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jānis tām septiņām Dieva draudzēm, kas ir Āzijā: žēlastība lai ir jums un miers no Tā, kas ir un kas bijis un kas nāk; un no tiem septiņiem gariem, kas ir Viņa goda krēsla priekšā;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Un no Jēzus Kristus, kas ir Tas uzticīgais liecinieks, Tas pirmdzimtais no tiem mirušiem un Tas valdītājs pār tiem ķēniņiem virs zemes; kas mūs ir mīlējis un mūs mazgājis no mūsu grēkiem ar Savām asinīm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Un mūs darījis par ķēniņiem un priesteriem Savam Dievam un Tēvam: Viņam lai ir gods un vara mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Redzi, Viņš nāk ar padebešiem, un visas acis Viņu redzēs un tie, kas Viņu ir dūruši, un visas pasaules ciltis kauks Viņa priekšā. Tiešām, Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Es esmu Tas A(Alfa) un Tas O(Omega), Tas Iesākums un Tas Gals, saka Tas Kungs Dievs, kas ir un kas bijis un kas nāk, Tas Visuvaldītājs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Es Jānis, jūsu brālis un biedrs iekš Jēzus Kristus bēdām, valstības un pacietības, es biju tai salā, ko sauc Patmos, Dieva vārda dēļ un Jēzus Kristus liecības dēļ.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Es biju garā Tā Kunga dienā un dzirdēju aiz manis stipru balsi kā bazūni;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Tā sacīja: Es esmu Tas A(Alfa) un Tas O(Omega), Tas Pirmais un Tas Pēdīgais; un ko tu redzi, to raksti grāmatā un sūti tām draudzēm, kas ir Āzijā, uz Efesu un uz Smirnu un uz Pergamu un uz Tiatiru un uz Sardu un uz Filadelfiju un uz Laodiķeu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Un es apgriezos, to balsi skatīties, kas ar mani runāja, un apgriezies es redzēju septiņus zelta lukturus,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Un vidū starp tiem septiņiem lukturiem vienu, līdzīgu Cilvēka Dēlam, apģērbtu ar gariem svārkiem un apjoztu ap krūtīm ar zelta jostu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Un Viņa galva un mati bija balti, tā kā balta vilna, tā kā sniegs, un Viņa acis bija tā kā uguns liesma;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Un Viņa kājas bija varam līdzīgas, itin kā ceplī degošas, un Viņa balss tā kā lielu ūdeņu balss.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Un Viņam bija labā rokā septiņas zvaigznes, un no Viņa mutes izgāja ass, abējās pusēs griezīgs zobens, un Viņa vaigs spīdēja, kā saule spīd savā spēkā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Un kad es Viņu redzēju, tad es nokritu pie Viņa kājām tā kā miris; un Viņš man uzlika Savu labo roku sacīdams: nebīsties! Es esmu Tas Pirmais un Tas Pēdējais');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Un Tas Dzīvais. Es biju nomiris un redzi, Es esmu dzīvs mūžīgi mūžam. Un Man ir elles un nāves atslēgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Raksti, ko tu esi redzējis, to, kas nu ir, un to, kas pēc šim notiks,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'To noslēpumu par tām septiņām zvaigznēm, ko tu esi redzējis Manā labā rokā, un tos septiņus zelta lukturus. Tās septiņas zvaigznes ir to septiņu draudžu eņģeļi, un tie septiņi lukturi, ko tu esi redzējis, ir septiņas draudzes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Efesus draudzes eņģelim raksti: tā saka Tas, kas tās septiņas zvaigznes tur Savā labā rokā, kas staigā vidū starp tiem septiņiem zelta lukturiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Es zinu tavus darbus un tavu pūliņu un tavu pacietību un ka tu ļaunus nevari ieredzēt; un tu esi pārbaudījis tos, kas teicās apustuļi esoši un nav, un tos esi atradis melkuļus;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Un esi panesis, un tev ir pacietība un esi pūlējies Mana Vārda dēļ un neesi piekusis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Bet tas Man ir pret tevi, ka tu no savas pirmās mīlestības esi atstājies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Tad nu piemini, no kurienes tu esi atkritis, un atgriezies un dari tos pirmos darbus; bet ja ne, tad Es pie tevis nākšu drīz un nostumšu tavu lukturi no viņa vietas, ja tu neatgriezīsies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Bet tas tev ir, ka tu tos Nikolaītu darbus ienīsti, ko Es arīdzan ienīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kam ir ausis, tas lai dzird, ko Tas Gars tām draudzēm saka: tam, kas uzvar, Es došu ēst no tā dzīvības koka, kas ir Dieva paradīzē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Un Smirnas draudzes eņģelim raksti: tā saka Tas Pirmais un Tas Pēdīgais, kas bija miris un ir dzīvs tapis:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Es zinu tavus darbus un tavas bēdas un tavu nabadzību (tomēr tu esi bagāts), un to zaimošanu no tiem, kas teicās Jūdi esoši un nav, bet ir sātana draudze.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Nebīsties nekā par to, ka tev jācieš; redzi, sātans kādus no jums metīs cietumā, lai jūs topat kārdināti, un jums būs bēdas desmit dienas. Esi uzticīgs līdz nāvei, tad Es tev došu to dzīvības kroni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kam ir auss, tas lai dzird, ko Tas Gars tām draudzēm saka: tam, kas uzvar, nekāda vaina nenotiks no tās otrās nāves.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Un Pergamus draudzes eņģelim raksti: tā saka Tas, kam tas asais, abējās pusēs griezīgais zobens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Es zinu tavus darbus, un ka tu piemājo, kur sātana krēsls, un ka tu Manu Vārdu turi un Manu ticību neesi aizliedzis, arī ne tanīs dienās, kad Antipas, Mans uzticīgais liecinieks, ir nokauts pie jums, kur sātans mājo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Bet tas vien Man ir pret tevi, ka tavā vidū ir, kas Bileāma mācību cienī, kas Balaku mācīja, apgrēcību celt Israēla bērnu priekšā, elku upurus ēst un maukot.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Tāpat tev arīdzan ir, kas to Nikolaītu mācību cienī, ko Es ienīstu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Atgriezies no grēkiem! Bet ja ne, tad Es pie tevis nākšu drīz un karošu pret tiem ar Savas mutes zobenu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kam ir ausis, tas lai dzird, ko Tas Gars tām draudzēm saka; tam, kas uzvar, Es došu ēst no tā apslēptā manna, un Es viņam došu labas liecības zīmi un uz tās liecības zīmes vienu jaunu vārdu rakstītu, ko neviens nezin, kā vien tas, kas to dabū.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Un Tiatiras draudzes eņģelim raksti: tā saka Tas Dieva Dēls, kam acis ir tā kā uguns liesma, un kam kājas ir varam līdzīgas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Es zinu tavus darbus un tavu mīlestību un tavu kalpošanu un tavu ticību un tavu pacietību un tavus darbus, un ka to pēdējo darbu ir vairāk nekā to pirmo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Bet tas vien Man ir pret tevi, ka tu tai sievai, tai Jezebelei, kas praviete teicās, vaļu dod, mācīt un pievilt Manus kalpus, ka mauko un ēd elku upurus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Un Es viņai laiku esmu devis, lai viņa atgrieztos no savas maucības, un tā nav atgriezusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Redzi, Es viņu metīšu uz gultu, un tos, kas ar viņu maukojuši, lielās bēdās, ja tie neatgriezīsies no saviem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Un viņas bērnus Es nonāvēdams nonāvēšu, un visām draudzēm būs atzīt, ka Es tas esmu, kas īkstis un sirdis pārbauda. Un Es došu ikvienam no jums pēc viņa darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Bet jums Es saku, tiem citiem, kas ir Tiatirā, kam šīs mācības nav, un kas (kā tie saka) sātana dziļumus nav atzinuši: Es nekādu citu nastu uz jums nemetīšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Tomēr, kas jums ir, to turat, kamēr Es nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Un tam, kas uzvar un Manus darbus tur līdz galam, Es došu varu pār tiem pagāniem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Un viņš tos ganīs ar dzelzs rīksti, tā kā māla trauki top sadauzīti, kā arī Es to esmu dabūjis no Sava Tēva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Un Es viņam došu to rīta zvaigzni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kam ir ausis, tas lai dzird, ko Tas Gars tām draudzēm saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Un Sardus draudzes eņģelim raksti: tā saka Tas, kam tie septiņi Dieva gari un tās septiņas zvaigznes. Es zinu tavus darbus, ka tev tas vārds ir, ka tu dzīvo, un tu esi miris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Uzmosties un stiprini to citu, kas grib mirt; jo Es tavus darbus neesmu atradis pilnīgus Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Tad nu piemini, kā tu esi dabūjis un dzirdējis, un turi to un atgriezies: ja tu nu nebūsi nomodā, tad Es nākšu pār tevi tā kā zaglis, un tu nezināsi, kurā stundā Es pār tevi nākšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Bet tev vēl ir maz vārdu iekš Sardus, kas savas drēbes nav apgānījuši, un tie staigās baltās drēbēs ar Mani, jo tie to ir vērts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kas uzvar, tas ar baltām drēbēm taps apģērbts; un Es viņa vārdu neizdeldēšu no tās dzīvības grāmatas un viņa vārdu apliecināšu priekš Sava Tēva un Viņa eņģeļiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kam ir ausis, tas lai dzird, ko Tas Gars tām draudzēm saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Un Filadelfias draudzes eņģelim raksti: tā saka Tas Svētais, Tas Patiesīgais, kam ir tā Dāvida atslēga, kas atver, un neviens neaizslēdz, un aizslēdz, un neviens neatver.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Es zinu tavus darbus. Redzi, Es tavā priekšā esmu devis atvērtas durvis, un neviens tās nevar aizslēgt; jo tev ir maz spēka, un tu Manu mācību esi turējis un neesi aizliedzis Manu Vārdu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Redzi, Es dodu no sātana draudzes, kas teicās Jūdi esoši un nav, bet melo, - redzi, Es darīšu, ka tie nāks un pie tavām kājām pielūgs un atzīs, ka Es tevi esmu mīlējis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Tāpēc ka tu Manas paciešanas mācību esi turējis, tad Es arī tevi pasargāšu no tās kārdināšanas stundas, kas nāks pār visu pasauli, tos kārdināt, kas dzīvo virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Redzi, Es nāku drīz. Turi, kas tev ir, ka neviens tavu kroni neatņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Kas uzvar, to Es darīšu par pīlāru Sava Dieva namā, un tas vairs neizies ārā; un Es uz viņu rakstīšu Sava Dieva Vārdu, un Sava Dieva pilsētas vārdu, tās jaunās Jeruzālemes, kas nonāk no debesīm no Mana Dieva, un Manu Vārdu, to jauno.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kam ir ausis, tas lai dzird, ko Tas Gars tām draudzēm saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Un Laodiķeas draudzes eņģelim raksti: tā saka Tas Āmen, Tas uzticīgais un patiesīgais liecinieks, Tas Dieva radījumu iesākums.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Es zinu tavus darbus, ka tu neesi ne auksts, ne karsts. Kaut jel tu būtu vai auksts, vai karsts!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Kad tu nu esi remdens un ne auksts, ne karsts, tad Es tevi izspļaušu no Savas mutes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Jo tu saki: es esmu bagāts un pār pāri bagāts, un man nekā nevajag; un tu nezini, ka tu esi nelaimīgs un nožēlojams un nabags un akls un kails.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Es tev dodu padomu, ka tev no Manis būs pirkt zeltu, kas ugunī ir izdedzināts, lai tu topi bagāts, - un baltas drēbes, lai tu topi apģērbts, un tavas kailības kauns nenāk redzams; un svaidi savas acis ar acu zālēm, lai tu vari redzēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ko Es mīlēju, tos Es pārmācu un pamācu: tad nu iekarsies un atgriezies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Redzi, Es stāvu priekš durvīm un klaudzināju: ja kas Manu balsi klausīs un durvis atvērs, pie tā Es ieiešu un vakarēdienu turēšu ar viņu un viņš ar Mani.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Kas uzvar, tam Es došu sēdēt ar Mani uz Mana goda krēsla, tā kā Es esmu uzvarējis un sēdies ar Savu Tēvu uz Viņa goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kam ir ausis, tas lai dzird, ko Tas Gars tām draudzēm saka.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Pēc tam es redzēju, un raugi, durvis bija atvērtas debesīs, un tā pirmā balss, ko es dzirdēju tā kā bazūni ar mani runājam, sacīja: uzkāp šurp, Es tev rādīšu, kam pēc būs notikt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Un tūdaļ es biju garā, un redzi, tur goda krēsls bija celts debesīs, un tur Viens sēdēja uz tā goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Un ģīmis Tam, kas tur sēdēja, bija līdzīgs jaspis un sardis akmenim; un visapkārt tam goda krēslam bija varavīksne, kas izskatījās tā kā smaragds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Un visapkārt ap to goda krēslu bija divdesmit četri krēsli, un uz tiem krēsliem es redzēju divdesmit četrus vecajus sēžam, apģērbtus baltām drēbēm, un tiem bija zelta kroņi uz galvām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Un no tā goda krēsla iziet zibeņi, pērkoni un balsis; un tur bija septiņi degoši eļļas lukturi, kas tā goda krēsla priekšā deg; tie ir tie septiņi Dieva gari.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Un tā goda krēsla priekšā bija tā kā glāzes jūra, kristālam līdzīga, un tā goda krēsla vidū un visapkārt ap to goda krēslu četri dzīvi radījumi, pilni ar acīm priekšā un aizmugurē.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Un tas pirmais no tiem dzīviem bija lauvam līdzīgs, un tas otrais vērsim līdzīgs, un tam trešam bija tā kā cilvēka vaigs, un tas ceturtais bija skrejošam ērglim līdzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Un tiem četriem dzīviem bija ikvienam seši spārni, un tie bija visapkārt un iekšpusē pilni ar acīm, un tie bez atpūšanās dienām naktīm sauc: svēts, svēts, svēts ir Tas Kungs Dievs, Tas Visuvaldītājs, kas bijis un kas ir un kas nāk.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Un kad tie dzīvie godu un slavu un pateikšanu dod Tam, kas sēž uz tā goda krēsla, kas dzīvo mūžīgi mūžam,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Tad tie divdesmit četri vecaji nometās zemē priekš Tā, kas sēž uz tā goda krēsla, un pielūdz To, kas dzīvo mūžīgi mūžam, un met savus kroņus tā goda krēsla priekšā sacīdami:');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Kungs, Tu esi cienīgs ņemt godu un slavu un spēku, jo Tu visas lietas esi radījis un caur Tavu prātu tās ir un ir radītas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Un es redzēju labā rokā Tam, kas sēdēja uz tā goda krēsla, grāmatu no iekšas un ārpuses aprakstītu un ar septiņiem zieģeļiem aizzieģelētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Un es redzēju spēcīgu eņģeli saucam ar stipru balsi: kas ir cienīgs to grāmatu attaisīt un viņas zieģeļus atdarīt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Un neviens nedz debesīs, nedz virs zemes, nedz apakš zemes to grāmatu nevarēja atdarīt, nedz tur ieskatīties iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Un es gauži raudāju, ka neviens netapa atrasts cienīgs, atdarīt un lasīt to grāmatu, nedz tur ieskatīties iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Un viens no tiem vecajiem uz mani saka: neraudi! Redzi, tas lauva no Jūda cilts, tā Dāvida sakne, ir uzvarējis, attaisīt to grāmatu un atdarīt viņas septiņus zieģeļus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Un es redzēju, un raugi, tā goda krēsla un to četru dzīvo vidū un to vecaju vidū stāvēja Jērs kā nokauts, tam bija septiņi ragi un septiņas acis, tie ir tie septiņi Dieva gari, izsūtīti pa visu pasauli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Un Tas nāca un ņēma to grāmatu no labās rokas Tam, kas sēdēja uz tā goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Un kad Tas to grāmatu bija ņēmis, tad tie četri dzīvie un tie divdesmit četri vecaji metās zemē priekš Tā Jēra, turēdami ikviens kokles un zelta kausus, pilnus ar kvēpināmām zālēm; tās ir to svēto lūgšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Un tie dziedāja jaunu dziesmu sacīdami: Tu esi cienīgs, ņemt to grāmatu un atdarīt viņas zieģeļus; jo Tu biji nokauts un Dievam Tu mūs esi atpircis ar Savām asinīm no visām ciltīm un valodām un ļaudīm un tautām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Un mūs esi darījis par ķēniņiem un priesteriem mūsu Dievam, un mēs valdīsim virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Un es redzēju un dzirdēju daudz eņģeļu balsis visapkārt ap to goda krēslu un ap tiem dzīviem un vecajiem; un viņu pulks bija desmit tūkstoš reiz desmit tūkstoši un tūkstoš reiz tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Tie sacīja ar stipru balsi: Tas Jērs, kas tapa nokauts, ir cienīgs, ņemt spēku un bagātību un gudrību un stiprumu un slavu un godu un pateicību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Un visus radījumus, kas ir debesīs un virs zemes un zemes apakšā, un kas ir jūrā, un visus, kas tur ir iekšā, es dzirdēju sakām: Tam, kas sēž uz tā goda krēsla, un Tam Jēram lai ir pateicība un slava un gods un vara mūžīgi mūžam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Un tie četri dzīvie sacīja: Āmen! Un tie divdesmit četri vecaji metās zemē un pielūdza To, kas dzīvo mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Un es redzēju, ka Tas Jērs vienu no tiem zieģeļiem atdarīja, un dzirdēju vienu no tiem četriem dzīviem sakām kā ar pērkona balsi: nāc un lūko!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Un es redzēju, un raugi, tur bija balts zirgs, un kas uz tā sēdēja, tam bija stops; un tam kronis tapa dots, un viņš izgāja uzvarēdams, un lai uzvarētu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Un kad Viņš to otru zieģeli atdarīja, tad es dzirdēju to otru dzīvo sakām: nāc un lūko!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Un tur izgāja otrs, sarkans zirgs, un tam, kas uz tā sēdēja, tapa dots, mieru atņemt no zemes, un ka tie cits citu nokautu savā starpā, un tam tapa dots liels zobens.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Un kad Viņš to trešo zieģeli atdarīja, tad es dzirdēju to trešo dzīvo sakām: nāc un lūko! Un es redzēju, un raugi, melns zirgs, un tam, kas uz tā sēdēja, bija svari rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Un es dzirdēju balsi to četru dzīvo vidū sakām: viens mērs kviešu par sudraba gabalu un trīs mēri miežu par sudraba gabalu un eļļu un vīnu nesamaitā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Un kad Viņš to ceturto zieģeli atdarīja, tad es dzirdēju tā ceturtā dzīvā balsi sakām: nāc un lūko!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Un es redzēju un raugi, pelēks zirgs, un kas uz tā sēdēja, tam bija vārds: nāve; un elle tai gāja pakaļ; un tiem vara tapa dota, ceturto pasaules tiesu nokaut ar zobenu un ar badu un ar mēri un caur zemes zvēriem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Un kad Tas to piekto zieģeli atdarīja, tad es redzēju apakš tā kvēpināmā altāra to dvēseles, kas bija nokauti Dieva vārda dēļ un tās liecības dēļ, kas tiem bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Un tie sauca ar stipru balsi sacīdami: cik ilgi, ak svētais un patiesīgais Valdītājs, Tu nesodi un neatriebi mūsu asinis pie tiem, kas virs zemes dzīvo?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Un garas baltas drēbes ikvienam tapa dotas, un tiem tapa sacīts, lai tie vēl mazu laiku dus, tiekams viņu darba biedru un viņu brāļu skaits būs pilns, kas taps nokauti, tā kā viņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Un es redzēju, kad Viņš to sesto zieģeli atdarīja, tad cēlās liela zemes trīcēšana, un saule tapa tumša kā rupjš maiss, un mēnesis tapa kā asinis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Un debess zvaigznes krita uz zemi, kā vīģes koks savas neienākušās vīģes nomet, kratīts no liela vēja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Un debess aizgāja kā satīta grāmata, un visi kalni un salas tapa kustinātas no savām vietām,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Un tie ķēniņi virs zemes un tie lielie kungi un tie bagātie un tie virsnieki un tie varenie un visi kalpi un visi svabadie paslēpās alās un kalnu dobumos,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Un sacīja uz tiem kalniem un tām klintīm: krītiet pār mums un apslēpiet mūs no Tā vaiga, kas sēž uz tā goda krēsla, un no Tā Jēra dusmības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Jo Viņa dusmības lielā diena ir atnākusi, - un kas var pastāvēt?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Un pēc tam es redzēju četrus eņģeļus stāvam uz tiem četriem zemes stūriem, kas tos četrus zemes vējus turēja, lai vējš nepūstu ne pa zemi, ne pa jūru, ne pa kādu koku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Un es redzēju citu eņģeli uzkāpjam no rīta puses, tam bija tā dzīvā Dieva zieģelis, un tas sauca ar stipru balsi uz tiem četriem eņģeļiem, kam vara bija dota, samaitāt zemi un jūru,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Sacīdams: nesamaitājiet ne zemi, ne jūru, ne kokus, tiekams mēs apzieģelēsim sava Dieva kalpus pie viņu pierēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Un es dzirdēju, cik to apzieģelēto: simts četrdesmit un četri tūkstoši bija apzieģelēti no visām Israēla bērnu ciltīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'No Jūda cilts: divpadsmit tūkstoši apzieģelēti. No Rūbena cilts: divpadsmit tūkstoši. No Gada cilts: divpadsmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'No Ašera cilts: divpadsmit tūkstoši. No Naftalus cilts: divpadsmit tūkstoši. No Manasus cilts: divpadsmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'No Sīmeana cilts: divpadsmit tūkstoši. No Levja cilts: divpadsmit tūkstoši. No Īsašara cilts: divpadsmit tūkstoši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'No Zebulona cilts: divpadsmit tūkstoši. No Jāzepa cilts: divpadsmit tūkstoši. No Benjamina cilts: divpadsmit tūkstoši apzieģelēti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Pēc tam es redzēju, un raugi, liels pulks, ko neviens nevarēja izskaitīt, no visādām tautām un ciltīm un ļaudīm un valodām stāvēja priekš tā goda krēsla un priekš Tā Jēra, apģērbti baltām garām drēbēm un palmu zari viņu rokās,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Un sauca ar stipru balsi un sacīja: pestīšana pieder mūsu Dievam, kas sēž uz tā goda krēsla, un Tam Jēram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Un visi eņģeļi stāvēja visapkārt ap to goda krēslu un ap tiem vecajiem un tiem četriem dzīviem un metās priekš tā goda krēsla zemē uz savu vaigu un pielūdza Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Sacīdami: Āmen! Teikšana un gods un gudrība un pateicība un slava un vara un spēks pieder mūsu Dievam mūžīgi mūžam! Āmen.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Un viens no tiem vecajiem atbildēja, uz mani sacīdams: šie, kas apģērbti baltām garām drēbēm, kas tie tādi, un no kurienes tie nākuši?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Un es uz viņu sacīju: Kungs, tu to zini! Un viņš uz mani sacīja: šie ir tie, kas ir nākuši no tām lielām bēdām un ir mazgājuši savas drēbes un tās balinājuši iekš Tā Jēra asinīm;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Tādēļ tie ir Dieva goda krēsla priekšā un Viņam kalpo dienām un naktīm Viņa namā, un kas sēž uz tā goda krēsla, Tas tos apēnos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Ne tie vairs izsalks, ne tiem vairs slāps; nedz saule, nedz kāds karstums tos vairs nespiedīs;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Jo Tas Jērs, kas ir vidū priekš tā goda krēsla, tos ganīs un tos vadīs pie dzīviem ūdens avotiem, un Dievs nožāvēs visas asaras no viņu acīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Un kad Viņš to septīto zieģeli atdarīja, palika kluss debesīs kādu pusstundu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Un es redzēju tos septiņus eņģeļus, kas stāvēja Dieva priekšā, un tiem tapa dotas septiņas bazūnes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Un cits eņģelis nāca un stāvēja pie tā altāra, turēdams zelta kvēpināmu trauku; un tam tapa dotas daudz kvēpināmas zāles, ka viņš tās ar visu svēto lūgšanām liktu uz to zelta altāri, kas ir tā goda krēsla priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Un šo kvēpināmo zāļu dūmi uzkāpa ar svēto lūgšanām no tā eņģeļa rokas Dieva priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Un tas eņģelis ņēma to kvēpināmo trauku un to pildīja ar uguni no tā altāra un to meta uz zemi. Tad notika balsis un pērkoni un zibeņi un zemes trīcēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Un tie septiņi eņģeļi, kam tās septiņas bazūnes bija, taisījās bazūnēt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Un tas pirmais bazūnēja. Un krusa cēlās un uguns ar asinīm sajaukts un krita uz zemi, un koku trešā tiesa izdega un visa zaļā zāle izdega.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Un tas otrais eņģelis bazūnēja. Un tā kā liels kalns, ugunī degošs, tapa mests jūrā, un jūras trešā tiesa tapa par asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Un radījumu trešā tiesa, kas jūrā, kam ir dzīvība, nomira, un laivu trešā tiesa tapa sadragāta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Un tas trešais eņģelis bazūnēja. Un liela zvaigzne tā kā degoša lāpa nokrita no debesīm un krita uz upju trešo tiesu un uz ūdeņu avotiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Un tās zvaigznes vārds top saukts: Vērmeles, un ūdeņu trešā tiesa tapa par vērmelēm, un daudz ļaužu nomira no tiem ūdeņiem, jo tie bija rūgti palikuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Un tas ceturtais eņģelis bazūnēja. Un saules trešā tiesa tapa samaitāta un mēneša trešā tiesa un zvaigžņu trešā tiesa, ka viņu trešā tiesa taptu aptumšota un dienas trešā tiesa nespīdētu, un nakts tāpat.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Un es redzēju un dzirdēju ērgli pa debess vidu skrejam un ar stipru balsi sakām: vai, vai, Ak vai, tiem, kas virs zemes dzīvo, to citu bazūņu balsu dēļ no tiem trim eņģeļiem, kas vēl bazūnēs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Un tas piektais eņģelis bazūnēja. Un es redzēju zvaigzni, kritušu no debess uz zemi, un tam tapa dota bezdibeņa akas atslēga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Un tas atvēra bezdibeņa aku. Un dūmi uzkāpa no tās akas, kā liela cepļa dūmi. Un saule tapa aptumšota un gaiss no tās akas dūmiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Un no tiem dūmiem siseņi nāca uz zemi, un tiem vara tapa dota, tā kā skorpioniem vara ir virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Un tiem tapa sacīts, lai tie nemaitātu zemes zāli nedz zaļumu, nedz kādu koku, bet vien tos cilvēkus, kam tas Dieva zieģelis nav pie viņu pierēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Un viņiem tapa dots, ka tie tos nenokautu, bet mocītu piecus mēnešus; un viņu mocīšana bija tā kā skarpija mocīšana, kad tas cilvēkam ir iedzēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Un tanīs dienās cilvēki nāvi meklēs un to neatradīs, un tie kāros mirt, bet nāve no viņiem bēgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Un tie siseņi bija līdzīgi zirgiem, kas ir sataisīti uz karu, un uz viņu galvām bija kā kroņi, zeltam līdzīgi, un viņu vaigi kā cilvēku vaigi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Un tiem bija mati kā sievu mati, un viņu zobi bija kā lauvu zobi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Un tiem bija bruņas kā dzelzs bruņas, un viņu spārnu troksnis tā kā ratu troksnis, kad daudz zirgi skrien karā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Un tiem bija astes skorpioniem līdzīgas, un viņu astēs bija dzeloņi, un viņiem bija vara, cilvēkus maitāt piecus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Un pār tiem bija ķēniņš, tas bezdibeņa eņģelis, viņa vārds bija ebrejiski: Abadon, un Grieķu valodā: Apolion.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Tas viens “vai” ir pagājis; redzi, vēl nāk divi “vai” pēc tam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Un tas sestais eņģelis bazūnēja, un es dzirdēju vienu balsi no tā zelta altāra četriem stūriem, kas bija Dieva priekšā,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Sakām uz to sesto eņģeli, kam tā bazūne bija: atraisi tos četrus eņģeļus, kas ir saistīti pie tās lielās Eifrates upes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Un tie četri eņģeļi tapa atraisīti, kas bija gatavi uz to stundu un dienu un mēnesi un gadu, ka tie cilvēku trešo tiesu nokautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Un tas kara jātnieku skaits bija divdesmit tūkstoši reiz desmit tūkstoši. Un es dzirdēju viņu skaitu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Un tā es redzēju tos zirgus tanī parādīšanā un tos, kas uz tiem sēdēja: tiem bija ugunīgas un tumši zilas un sēram līdzīgas bruņas; un to zirgu galvas bija kā lauvu galvas, un no viņu mutēm izgāja uguns un dūmi un sērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Caur šiem trim cilvēku trešā tiesa tapa nokauta, caur to uguni un caur tiem dūmiem un caur to sēru, kas no viņu mutēm izgāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Jo viņu vara stāvēja viņu mutē un viņu astēs; jo viņu astes bija čūskām līdzīgas; tām bija galvas, un ar tām tie maitāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Un tie atlikušie cilvēki, kas nav nokauti caur šīm mocībām, tomēr nav atgriezušies no savu roku darbiem, ka tie nebūtu (vairs) pielūguši tos velnus un tos zelta un sudraba un vara un akmens un koka elkus, kas nevar redzēt, nedz dzirdēt, nedz staigāt;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Un tie nav atgriezušies no savām slepkavībām, nedz no savām burvestībām, nedz no savas maucības, nedz no savām zādzībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Un es redzēju citu spēcīgu eņģeli no debesīm nokāpjam, tas bija apģērbts ar mākoni, un varavīksne bija uz viņa galvas, un viņa vaigs bija tā kā saule un viņa kājas tā kā uguns stabi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Un tam atvērta grāmatiņa bija rokā, un tas lika savu labo kāju uz jūru un kreiso uz zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Un tas sauca ar stipru balsi, kā lauva rūc; un kad tas bija saucis, tad tie septiņi pērkoni runāja savās balsīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Un kad tie septiņi pērkoni savās balsīs bija runājuši, tad es tās gribēju rakstīt, un es dzirdēju balsi no debesīm uz mani sakām: apzieģelē, ko tie septiņi pērkoni ir runājuši, un neraksti to.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Un tas eņģelis, ko es redzēju stāvām uz jūras un uz zemes, pacēla savu roku uz debesīm');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'Un zvērēja pie Tā, kas dzīvo mūžīgi mūžam, kas ir radījis debesis un, kas tur iekšā, un zemi un, kas tur iekšā, un jūru un, kas tur iekšā, ka laiks vairs nebūs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Bet iekš tā septītā eņģeļa balss dienām, kad tas bazūnēs, tad Dieva noslēpums taps piepildīts, kā Viņš Saviem kalpiem, tiem praviešiem, ir pasludinājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Un tā balss, ko es biju dzirdējis no debesīm, atkal ar mani runāja un sacīja: ej, ņem to grāmatiņu, kas ir atvērta tā eņģeļa rokā, kas uz jūras un uz zemes stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Un es nogāju pie tā eņģeļa un uz to sacīju: dod man to grāmatiņu; un tas uz mani sacīja: ņem un apēd to, un tā būs rūgta tavā vēderā, bet tavā mutē tā būs salda kā medus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Un es to grāmatiņu ņēmu no tā eņģeļa rokas un to apēdu, un tā bija manā mutē salda kā medus, un kad es to biju apēdis, tā bija rūgta manā vēderā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Un viņš uz mani sacīja: tev būs atkal pasludināt nākošas lietas par daudz ļaudīm un tautām un valodām un ķēniņiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Un niedre man tapa dota mēra kokam līdzīga, un tas eņģelis stāvēja sacīdams: celies un mēro to Dieva namu un to altāri un tos, kas tur iekšā pielūdz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Bet to pagalmu, kas ir Dieva nama ārpusē, pamet ārā, un nemēro to, jo tas ir dots pagāniem; un tie to svēto pilsētu samīs četrdesmit divus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Un Es vaļu došu Saviem diviem lieciniekiem, un tie kā pravieši mācīs tūkstoš divsimt un sešdesmit dienas, ar maisiem apģērbti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Šie ir tie divi eļļas koki un tie divi lukturi, kas pasaules valdītāja priekšā stāv.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Un ja kas tiem grib vainu darīt, tad uguns iziet no viņu mutes un aprij viņu ienaidniekus; un ja kas tos grib apvainot, tam tāpat būs nokautam tapt.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Šiem ir vara, debesi aizslēgt, ka lietus nelīst viņu sludināšanas dienās, un tiem ir vara pār tiem ūdeņiem, tos pārvērst par asinīm un zemi sist ar visādām mokām, cikkārt viņiem gribās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Un kad tie savu liecību būs pabeiguši, tad tas zvērs, kas izkāpj no bezdibeņa, ar tiem karos un tos uzvarēs un tos nokaus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Un viņu miesas gulēs uz tās lielās pilsētas ielas, kas garīgi top saukta Sodoma un Ēģipte, kur arī mūsu Kungs ir krustā sists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Un no tiem ļaudīm un tām ciltīm un valodām un tautām būs, kas redzēs viņu miesas pusceturtas dienas un neļaus viņu miesas ielikt kapos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Un tie, kas dzīvo virs zemes, priecāsies par tiem un būs līksmi, un cits citam dāvanas sūtīs, jo šie divi pravieši bija mocījuši tos, kas virs zemes dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Un pēc pusceturtas dienas iegāja iekš tiem dzīvības gars no Dieva, un tie stājās uz savām kājām, un lielas izbailes uzkrita tiem, kas tos ieraudzīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Un tie dzirdēja stipru balsi no debess uz tiem sakām: nāciet šurp augšām. Un tie uzkāpa iekš mākoņa uz debesīm, un viņu ienaidnieki uz tiem skatījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Un tanī stundā liela zemes trīcēšana notika, un tās pilsētas desmitā tiesa sagruva, un tai zemes trīcēšanā septiņtūkstoš cilvēku vārdi tika nokauti, un tie atlikušie pārbijās un deva godu Tam Dievam debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Tas otrais “vai” ir pagājis, un redzi, tas trešais “vai” nāk drīz.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Un tas septītais eņģelis bazūnēja, un stipras balsis cēlās debesīs sacīdamas: pasaules valstis ir kļuvušas mūsu Kungam un Viņa Kristum, un Tas valdīs mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Un tie divdesmit četri vecaji, kas sēž Dieva priekšā uz saviem goda krēsliem, krita uz savu vaigu un pielūdza Dievu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Sacīdami: mēs Tev pateicamies, Kungs Dievs, Visuvaldītājs, kas ir un kas bijis un kas nāk, ka Tu Savu lielo spēku esi ņēmis un Savu valdību uzcēlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Un tās tautas ir iedusmojušās, un Tava dusmība ir nākusi un tas mirušo laiks, ka tie top sodīti, un ka tā alga top dota Taviem kalpiem, tiem praviešiem, un tiem svētiem un tiem, kas Tavu Vārdu bīstas, tiem maziem un lieliem; un ka tie top samaitāti, kas zemi maitāja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Un tas Dieva nams debesīs tapa atvērts, un Viņa derības šķirsts tapa redzams Viņa namā, un zibeņi notika un balsis un pērkoni un zemes trīcēšana un liela krusa.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Un liela zīme parādījās debesīs: sieva ar sauli apģērbta, un mēnesis apakš viņas kājām, un viņas galvā kronis no divpadsmit zvaigznēm,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Un grūta būdama tā brēca bērnu sāpēs un dzemdēšanas mokās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Un cita zīme parādījās debesīs, un redzi, liels pūķis, sarkans kā uguns, ar septiņām galvām un desmit ragiem, un uz viņa galvām septiņi ķēniņa kroņi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Un viņa aste vilka debess zvaigžņu trešo tiesu un tās nometa uz zemi. Un tas pūķis stājās tās sievas priekšā, kurai bija jādzemdē, ka viņš, kad tā dzemdētu, viņas bērnu aprītu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Un viņa dzemdēja bērnu, dēlu, kam visus pagānus būs ganīt ar dzelzs rīksti, un viņas bērns tapa aizrauts pie Dieva un pie Viņa goda krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Un tā sieva bēga uz tuksnesi, kur viņai bija no Dieva sataisīta vieta, lai viņa tur taptu uzturēta tūkstoš divsimt un sešdesmit dienas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Un karš cēlās debesīs. Miķelis un viņa eņģeļi karoja pret to pūķi; un tas pūķis karoja un viņa eņģeļi,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Un nespēja nenieka, un viņu vieta vairs netika atrasta debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Un tas lielais pūķis tika izmests, tā vecā čūska, ko dēvē par velnu un sātanu, kas visu pasauli pieviļ; tas tika nomests uz zemi, un viņa eņģeļi līdz ar viņu tur tika nomesti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Un es dzirdēju stipru balsi debesīs sakām: tagad pestīšana un spēks un valstība mūsu Dievam, un vara Viņa Kristum ir kļuvusi; jo mūsu brāļu apsūdzētājs ir nomests, kas tos apsūdzēja priekš mūsu Dieva dienām naktīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Un tie viņu ir uzvarējuši caur Tā Jēra asinīm un caur savas liecības vārdu, un tie savu dzīvību nav mīlējuši līdz nāvei.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Tāpēc priecājaties, jūs debesis, un kas tur dzīvo! Ak vai, tiem, kas zemes un jūras virsū dzīvo; jo velns pie jums ir nonācis ar lielām dusmām, zinādams, ka tam ir maz laika.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Un kad tas pūķis redzēja, ka viņš bija nomests uz zemi, tad viņš vajāja to sievu, kas to dēlu bija dzemdējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Un tai sievai divi liela ērgļa spārni tapa doti, ka tā uz tuksnesi skrietu savā vietā, kur viņa top uzturēta laiku un laikus un puslaiku, nost no tās čūskas vaiga.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Un tā čūska no savas mutes izlaida ūdeni tā kā upi tai sievai pakaļ, lai viņu caur to upi aizrautu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Un zeme nāca tai sievai palīgā, un zeme atvēra savu muti un aprija to upi, ko tas pūķis no savas mutes izlaida.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Un tas pūķis iedusmojās pret to sievu un nogāja karot ar tiem, kas atlikušies no viņas dzimuma, kas Dieva baušļus tur, un kam ir Jēzus Kristus liecība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Un es stāvēju uz jūras smiltīm. Un es redzēju zvēru izkāpjam no jūras, tam bija septiņas galvas un desmit ragi, un uz viņa ragiem desmit ķēniņa kroņi, un uz viņa galvām bija zaimošanas vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Un tas zvērs, ko es redzēju, bija pardelim līdzīgs, un viņa kājas kā lāča kājas, un viņa mute kā lauvas mute; un tas pūķis tam deva savu spēku un savu goda krēslu un lielu varu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Un es redzēju vienu no viņa galvām kā līdz nāvei ievainotu, un viņa nāves vaina tapa dziedināta, un visa zeme tam zvēram pakaļ brīnījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Un viņi pielūdza to pūķi, kas tam zvēram varu bija devis, un pielūdza to zvēru sacīdami: kas ir tam zvēram līdzīgs? Kas var ar to karot?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Un tam tapa dota mute, runāt lielas lietas un Dieva zaimošanas, un vara tam tapa dota, karot četrdesmit divus mēnešus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Un tas atdarīja savu muti un runāja zaimošanu pret Dievu, zaimodams Viņa vārdu un Viņa dzīvokli un tos, kas dzīvo debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Un tam tapa dots, karot ar tiem svētiem un tos uzvarēt, un tam vara tapa dota pār visām ciltīm un valodām un tautām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Un to pielūgs visi, kas dzīvo virs zemes, kam vārdi nav rakstīti Tā Jēra dzīvības grāmatā, kas ir nokauts no pasaules radīšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Ja kam ir ausis, tas lai dzird.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Ja kas ved cietumā, tas ies cietumā; ja kas ar zobenu nokauj, tam ar zobenu būs tapt nokautam. Še to svēto pacietība un ticība!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Un es redzēju citu zvēru izkāpjam no zemes, un tam bija divi ragi, jēra ragiem līdzīgi, un tas runāja kā pūķis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Un visu tā pirmā zvēra varu tas dara viņa priekšā, un dara, ka zeme un tie, kas uz tās dzīvo, pielūdz to pirmo zvēru, kam tā nāves vaina bija dziedināta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Un tas dara lielas zīmes, ka tas arī ugunij liek nokrist no debess uz zemi cilvēku priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Un tas pieviļ tos, kas dzīvo virs zemes caur tām zīmēm, ko darīt tā zvēra priekšā viņam ir dots, un saka uz tiem, kas virs zemes dzīvo, lai tie bildi taisa tam zvēram, kam tā vaina no zobena bija, un kas bija palicis dzīvs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Un tam tapa dots, tai zvēra bildei garu dot, ka tā zvēra bilde ir runātu, ir darītu, ka tie taptu nokauti, kas tā zvēra bildi nepielūgtu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Un tas dara, ka visiem, maziem un lieliem, bagātiem un nabagiem, svabadiem un kalpiem, zīme top dota pie viņu labās rokas vai pie viņu pieres;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'Un ka neviens nevar ne pirkt, ne pārdot, kā vien tas, kam tā zīme ir, tas zvēra vārds jeb viņa vārda skaitlis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Še tā gudrība! Kam ir saprašana, tas lai pārskaita tā zvēra skaitli; jo tas ir cilvēka skaitlis, un viņa skaitlis ir sešsimt sešdesmit un seši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Un es redzēju, un raugi, Tas Jērs stāvēja uz Ciānas kalna un līdz ar Viņu simt četrdesmit četri tūkstoši, kam Viņa Tēva vārds bija rakstīts pie viņu pierēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Un es dzirdēju balsi no debesīm kā daudz ūdeņu balsi un kā liela pērkona balsi, un tā balss, ko es dzirdēju, bija tā kā koklētāji koklē uz savām koklēm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Un tie dziedāja kā jaunu dziesmu tā goda krēsla priekšā un to četru dzīvo un to vecaju priekšā, un neviens nevarēja to dziesmu mācīties, kā vien tie simt četrdesmit četri tūkstoši, kas bija atpirkti no pasaules.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Šie ir, kas ar sievām nav apgānījušies; jo tie ir šķīsti; šie ir, kas Tam Jēram staigā pakaļ, uz kurieni Tas iet. Šie ir atpirkti no cilvēkiem par pirmajiem Dievam un Tam Jēram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Un viņu mutē viltība nav atrasta, jo tie ir bezvainīgi Dieva goda krēsla priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Un es redzēju citu eņģeli debes\' vidū skrienam; tam bija mūžīgs evaņģēlijs, tiem sludināt, kas virs zemes dzīvo, un visām tautām un ciltīm un valodām un ļaudīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Šis ar stipru balsi sacīja: bīstaties Dievu un dodiet Viņam godu, jo Viņa sodības stunda ir nākusi, un pielūdziet To, kas ir radījis debesi un zemi un jūru un ūdeņu avotus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Un cits eņģelis, otrs, nāca pakaļ sacīdams: kritusi, kritusi Bābele, tā lielā pilsēta, tāpēc ka tā visas tautas dzirdinājusi ar savas maucības dusmu vīnu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Un cits eņģelis, tas trešais, tiem nāca pakaļ sacīdams ar stipru balsi: ja kas to zvēru pielūdz un viņa bildi un pieņem to zīmi pie savas pieres un pie savas rokas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Tas arīdzan dzers no Dieva dusmības vīna, kas stiprs Viņa bardzības biķerī ir ieliets, un tas taps mocīts ar uguni un sēru to svēto eņģeļu un Tā Jēra priekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Un tie dūmi no viņu mocības uzkāpj mūžīgi mūžam, un dusēšanas nav nedz dienu nedz nakti tiem, kas to zvēru un viņa bildi pielūdz, un ja kas viņa vārda zīmi pieņem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Še ir to svēto pacietība. Še ir tie, kas tur Dieva baušļus un Jēzus ticību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Un es dzirdēju balsi no debesīm uz mani sakām: raksti! Svētīgi ir tie mirušie, kas iekš Tā Kunga mirst no šī brīža. Tiešām, Tas Gars saka, ka tie dus no savām darbošanām un viņu darbi tos pavada.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Un es redzēju un raugi, spožs padebesis un uz tā padebeša viens sēdēja, kas Cilvēka Dēlam līdzīgs, ar zelta kroni galvā un ar asu cirpi rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Un cits eņģelis nāca no Dieva nama, saukdams ar stipru balsi uz To, kas uz tā padebeša sēdēja: cērt ar Savu cirpi un pļauj; jo tā pļaušanas stunda Tev ir nākusi, tāpēc ka tas pļaujamais virs zemes ir ienācies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Un Tas, kas uz tā padebeša sēdēja, ar Savu cirpi cirta uz zemi, un zeme tapa pļauta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Un cits eņģelis nāca no Tā Dieva nama, kas ir debesīs, un tam bija arīdzan asa cirpe.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Un cits eņģelis nāca no tā altāra, tam bija vara pār uguni, un tas sauca ar lielu saukšanu uz to, kam tā asā cirpe bija, sacīdams: cērt ar savu aso cirpi un nogriez vīna ķekarus no zemes vīna koka, jo viņa ogas ir ienākušās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Un tas eņģelis cirta ar savu cirpi uz zemi un nogrieza ogas no zemes vīna koka un meta tās tai lielā Dieva dusmības vīna spaidā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Un tas vīna spaids tapa mīts ārpus pilsētas, un no tā vīna spaida nāca asinis līdz zirgu iemauktiem pie tūkstoš un sešsimt birzumiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Un es redzēju citu lielu un brīnišķu zīmi debesīs: septiņus eņģeļus, kas turēja tās septiņas pēdīgās mocības, jo iekš tām Dieva dusmība piepildījās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Un es redzēju kā glāzes jūru ar uguni jauktu; un tos, kas uzvarēja to zvēru un viņa bildi un viņa zīmi un viņa vārda skaitli, ka tie stāvēja pie tās glāzes jūras, turēdami Dieva kokles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Un tie dziedāja Mozus, Tā Dieva kalpa, dziesmu un Tā Jēra dziesmu sacīdami: lieli un brīnišķi ir Tavi darbi, Kungs Dievs, visu Valdītājs; taisni un patiesīgi ir Tavi ceļi, Tu Ķēniņ pār tām tautām!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kas Tevi nebītos, Kungs, un nedotu Tavam vārdam godu? Jo Tu vien esi svēts; jo visas tautas nāks un pielūgs Tavā priekšā, jo Tavas tiesas ir atspīdējušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Un pēc tam es redzēju, un raugi, Dieva nams, tas liecības dzīvoklis, tapa atvērts debesīs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Un tie septiņi eņģeļi, kam tās septiņas mocības bija, nāca ārā no Dieva nama, apģērbti ar šķīstu un spožu audekli un apjozti ap krūtīm ar zelta jostām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Un viens no tiem četriem dzīviem deva tiem septiņiem eņģeļiem septiņus zelta kausus, pildītus ar Tā Dieva dusmību, kas mūžīgi mūžam dzīvo.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Un Dieva nams tapa pilns dūmu no Dieva godības un no Viņa spēka, un neviens nevarēja Dieva namā ieiet, kamēr to septiņu eņģeļu septiņas mocības nebija pabeigtas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Un es dzirdēju stipru balsi no Dieva nama sakām uz tiem septiņiem eņģeļiem: ejat un izlejat Dieva dusmības kausus uz zemi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Un tas pirmais nogāja un izlēja savu kausu uz zemi, un tur ļauns un nikns augonis piemetās tiem cilvēkiem, kam tā zvēra zīme bija, un kas viņa bildi pielūdza.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Un tas otrais eņģelis savu kausu izlēja jūrā, un tā palika par asinīm, kā no miruša, un ikviena dzīva dvaša jūrā nomira.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Un tas trešais eņģelis izlēja savu kausu upēs un ūdeņu avotos, un tie palika par asinīm.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Un es dzirdēju to ūdeņu eņģeli sakām: Kungs, kas ir un kas bijis, Tu esi taisns un svēts, ka Tu tā esi tiesājis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Jo tie to svēto un to praviešu asinis ir izlējuši; tāpēc Tu tiem arīdzan asinis esi devis dzert, jo tie to pelnījuši.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Un es dzirdēju citu no tā altāra sakām: tiešām, Kungs Dievs, visu Valdītājs, patiesīgas un taisnas ir Tavas tiesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Un tas ceturtais eņģelis izlēja savu kausu uz sauli, un viņam tapa dots, cilvēkus dedzināt ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Un cilvēki tapa dedzināti ar lielu karstumu un zaimoja Tā Dieva vārdu, kam vara ir pār šīm mocībām. Bet tie neatgriezās no grēkiem, Viņam dot godu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Un tas piektais eņģelis savu kausu izlēja uz tā zvēra goda krēslu, un viņa valsts tapa aptumšota, un tie no sāpēm sakoda savas mēles,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Un zaimoja To Dievu debesīs savu sāpju dēļ un savu augoņu dēļ, un neatgriezās no saviem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Un tas sestais eņģelis savu kausu izlēja uz to lielo Eifrates upi, un viņas ūdens izsīka, ka taptu sataisīts ceļš tiem ķēniņiem no saules lēkšanas puses.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Un es redzēju no tā pūķa mutes un no tā zvēra mutes un no tā viltīgā pravieša mutes nākam trīs nešķīstus garus, vardēm līdzīgus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Jo tie ir velnu gari, kas dara zīmes un iziet pie visas pasaules ķēniņiem, tos sapulcināt uz karu, Dieva, tā Visuvarenā, lielā dienā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '“Redzi, Es nāku kā zaglis: svētīgs, kas nomodā un savas drēbes sarga, ka tas nestaigā pliks un viņa kauns netop redzēts.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Un viņš tos sapulcināja uz to vietu, kas ebrejiski top saukta Armaģedon.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Un tas septītais eņģelis savu kausu izlēja gaisā, un stipra balss nāca no tā debes\' nama, no tā goda krēsla, sacīdama: ir noticis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Un balsis un pērkoni un zibeņi cēlās. Un tad notika liela zemes trīcēšana, kāda vēl nav notikusi, kamēr cilvēki virs zemes bijuši, tāda un tik liela zemes trīcēšana.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Un tā lielā pilsēta dalījās trijās daļās, un pagānu pilsētas sagruva, un Bābele, tā lielā, tapa pieminēta Dieva priekšā, ka tai taptu dots viņa dusmības un bardzības vīna biķeris.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Un visas salas bēga, un kalni netapa atrasti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Un liela krusa, triju podu smaga, krita no debesīm uz cilvēkiem, un cilvēki zaimoja Dievu tās mocības dēļ caur to krusu; jo viņas mocība ir varen liela.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Un viens no tiem septiņiem eņģeļiem, kam tie septiņi kausi bija, nāca un ar mani runāja, uz mani sacīdams: nāc šurp, es tev rādīšu tās lielās maukas sodību, kas sēž pie tiem lieliem ūdeņiem;');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Ar to ir maukojuši tie ķēniņi virs zemes un tie, kas virs zemes dzīvo, ir piedzērušies no viņas maucības vīna.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Un viņš mani garā aizveda uz tuksnesi. Un es redzēju sievu sēžam uz sarkana zvēra, kas bija pilns ar zaimošanas vārdiem, kam bija septiņas galvas un desmit ragi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Un tā sieva bija apģērbta ar purpuru un dārgu sarkanumu un izpušķota ar zeltu un dārgiem akmeņiem un pērlēm, savā rokā turēdama zelta biķeri, pilnu ar savas maucības negantību un nešķīstību.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Un pie viņas pieres bija rakstīts vārds: “Noslēpums, Bābele, tā lielā, tā mauka un negantības māte virs zemes.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Un es redzēju to sievu piedzērušu no to svēto asinīm un no Jēzus liecinieku asinīm; to redzēdams es brīnījos ar lielu brīnīšanos.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Un tas eņģelis uz mani sacīja: kādēļ tu brīnies? Es tev sacīšu to noslēpumu par to sievu un to zvēru, kas viņu nes, un kam ir tās septiņas galvas un tie desmit ragi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Tas zvērs, ko tu esi redzējis, bija un nav un izkāps no bezdibeņa un ies bojā; un tie, kas virs zemes dzīvo, (kam vārdi nav rakstīti tai dzīvības grāmatā no pasaules radīšanas,) tie brīnīsies, redzēdami to zvēru, ka tas bija un nav un būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Še prāts ar gudrību! Tās septiņas galvas ir septiņi kalni, uz kuriem tā sieva sēž,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Un ir septiņi ķēniņi. Pieci ir krituši, un viens ir, un tas otrais vēl nav nācis, un kad tas nāks, tad tam būs palikt mazu brīdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Un tas zvērs, kas bija un nav, pats ir tas astotais, un ir no tiem septiņiem un iet bojā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Un tie desmit ragi, ko tu esi redzējis, ir desmit ķēniņi, kas valstību vēl nav dabūjuši; bet tā kā ķēniņi tie varu dabū uz vienu stundu ar to zvēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Šiem ir vienāds prāts, un tie savu spēku un varu nodos tam zvēram.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Šie karos ar To Jēru, un Tas Jērs tos uzvarēs, jo Tas ir to kungu Kungs un to ķēniņu Ķēniņš, - un tie, kas līdz ar Viņu, tie aicinātie un izredzētie un ticīgie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Un viņš uz mani saka: tie ūdeņi, ko tu esi redzējis, kur tā mauka sēž, ir ļaudis un ļaužu pulki un tautas un valodas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Un tie desmit ragi, ko tu esi redzējis uz tā zvēra, šie to mauku nīdēs un viņu darīs tukšu un kailu un viņas miesu ēdīs un viņu sadedzinās ar uguni.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Jo Dievs tiem sirdī devis, darīt Viņa prātu un darīt vienādā prātā un savu valstību dot tam zvēram, tiekams Dieva vārdi taps piepildīti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Un tā sieva, ko tu esi redzējis, ir tā lielā pilsēta, kam ir tā valdība pār tiem ķēniņiem virs zemes.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Un pēc tam es redzēju citu eņģeli nokāpjam no debesīm, tam bija liela vara, un zeme tapa apgaismota no viņa spožuma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Un tas sauca spēcīgi ar stipru balsi sacīdams: kritusi, kritusi Bābele, tā lielā, un palikusi velniem par mājas vietu un visiem nešķīstiem gariem par cietumu un visiem nešķīstiem un negantiem putniem par cietumu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Jo no viņas maucības dusmu vīna visas tautas ir dzērušas, un tie ķēniņi virs zemes ar viņu ir maukojuši, un tie tirgotāji virs zemes ir bagāti tapuši no viņas varenā kāruma.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Un es dzirdēju citu balsi no debesīm sakām: izejat no viņas, Mani ļaudis, ka jūs viņai nepaliekat par biedriem pie viņas grēkiem un ka jūs nedabūjiet no viņas mocībām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Jo viņas grēki ir līdz debesīm kāpuši, un Dievs ir pieminējis viņas noziegumus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Atmaksājiet viņai, kā viņa jums ir atmaksājusi, un dariet viņai divkārtīgi pēc viņas darbiem, ielejat viņai divkārtīgi tai biķerī, kur viņa ielējusi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Cik viņa pati sevi ir pagodinājusi un kārumā dzīvojusi, tik lielu mocību un bēdas padariet viņai, jo viņa saka savā sirdī: es sēžu tā kā ķēniņiene, un neesmu atraitne, un bēdas es neredzēšu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Tādēļ viņas mocības nāks vienā dienā, nāve un bēdas un bads, un viņa taps sadedzināta ugunī, jo spēcīgs ir Tas Kungs Dievs, kas viņu soda.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Un viņu apraudās un nožēlos tie ķēniņi virs zemes, kas ar viņu maucībā un kārumā dzīvojuši, kad tie redzēs tos dūmus no viņas degšanas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Tie stāvēs no tālienes aiz bailēm no viņas mokām un sacīs: vai, vai! Tā lielā pilsēta Bābele! Tā stiprā pilsēta! Jo tava sodība ir nākusi vienā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Un tie tirgotāji virs zemes raud un žēlojās par viņu, tāpēc ka viņu preci neviens vairs nepērk,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Zelta un sudraba preci un dārgus akmeņus un pērles un dārgu audekli un purpuru un zīdu un dārgu sarkanumu un visādus saldi smaržīgus kokus un visādus traukus no ziloņkauliem un visādus traukus no dārga koka un vara un dzelzs un marmora akmens,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'Un kanēli un kvēpināmās zāles un saldas smaržzāles un vīraku un vīnu un eļļu un kviešu miltus un kviešus un lopus un avis un zirgus un karietes un cilvēku miesas un dvēseles.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Un tie dārza augļi, ko tava dvēsele kāroja, ir nost no tevis, un viss, kas bija gards un spožs, tas ir nost no tevis, un to tu vairs neatradīsi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Šo lietu tirgotāji, kas no viņas bija bagāti tapuši, stāvēs no tālienes, aiz bailēm no viņas mokām, raudādami un žēlodamies');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Un sacīs: Vai! vai! tā lielā pilsēta, kas bija apģērbta ar dārgu audekli un purpuru un sarkanu dārgu vadmalu, un kas bija izgreznota ar zeltu un dārgiem akmeņiem un pērlēm! Jo tāda bagātība ir postīta vienā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Un visi stūrmaņi un visi, kas brauc uz laivām, un laivinieki un, cik uz jūras darbojās, stāvēja no tālienes');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'Un brēca, skatīdami tos dūmus no viņas degšanas, un sacīja: kura šai lielai pilsētai līdzīga?');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Un tie meta pīšļus uz savām galvām un brēca raudādami un žēlodamies un sacīja: Vai! Vai! tā lielā pilsēta, kur visi, kam laivas bija jūrā, bagāti tapuši no viņas greznuma, tā ir postīta vienā stundā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Līksmojaties par viņu, debesis, un jūs svētie apustuļi un jūs pravieši, jo Dievs jūsu tiesu ir iztiesājis pie viņas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Un viens spēcīgs eņģelis pacēla akmeni, tā kā lielu dzirnu akmeni, un to iemeta jūrā sacīdams: tāpat tā lielā pilsēta Bābele ar mešanu taps mesta un vairs netaps atrasta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Un koklētāju un dziedātāju un stabulnieku un bazūnētāju balss vairs netaps dzirdēta iekš tevis un nekāda amata amatnieks vairs netaps atrasts iekš tevis. Un dzirnavu balss vairs netaps dzirdēta iekš tevis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Un sveces gaišums vairs nespīdēs iekš tevis, un brūtgāna un brūtes balss vairs netaps dzirdēta iekš tevis. Jo tavi tirgotāji bija lieli kungi virs zemes, jo caur tavu apmānīšanu visas tautas tika pieviltas,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Un iekš tās ir atrastas to praviešu asinis un to svēto un visu to, kas virs zemes ir nokauti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Un pēc tam es dzirdēju, kā lielu ļaužu pulku, stipru balsi debesīs sakām: Alleluja! Pestīšana un gods un slava un spēks Tam Kungam, mūsu Dievam!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Jo Viņa tiesas ir patiesīgas un taisnas, tāpēc ka Viņš to lielo mauku ir notiesājis, kas zemi ir samaitājusi ar savu maucību, un Viņš savu kalpu asinis pie tās ir atriebis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Un tie sacīja otrā kārtā: Alleluja! Un viņas dūmi uzkāpj mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Un tie divdesmit četri vecaji un tie četri dzīvie nometās un pielūdza Dievu, kas uz tā goda krēsla sēdēja, sacīdami: Āmen, Alleluja!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Un balss izgāja no tā goda krēsla sacīdama: teiciet mūsu Dievu, visi Viņa kalpi, un kas Viņu bīstas, mazie un lielie.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Un es dzirdēju kā balsi no daudz ļaudīm un kā balsi no daudz ūdeņiem un kā balsi no stipriem pērkoniem sakām: Alleluja! Jo Tas Kungs, tas visu Valdītājs Dievs, ir valdību uzņēmis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Lai priecājamies un gavilējam un Viņam godu dodam, jo Tā Jēra kāzas ir nākušas, un Viņa sieva ir sataisījusies.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Un viņai ir dots, ka top apģērbta ar šķīstu un spožu dārgu audeklu; jo tas dārgais audekls ir to svēto taisnība.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Un viņš uz mani saka: raksti! Svētīgi ir tie, kas ir aicināti uz Tā Jēra kāzu mielastu! Un viņš uz mani saka: šie ir tie patiesīgie Dieva vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Un es kritu pie viņa kājām, viņu pielūgt, un viņš uz mani saka: “Raugi, nedari tā! Es esmu darba biedrs tev un taviem brāļiem, kam ir Jēzus liecība. Pielūdz Dievu! Jo Jēzus liecība ir tas praviešu mācības gars.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Un es redzēju debesis atvērtas, un raugi, balts zirgs, un kas uz tā sēdēja, tapa saukts Uzticīgs un Patiesīgs, un Tas tiesā un karo iekš taisnības.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Un Viņa acis ir kā uguns liesma, un uz Viņa galvas ir daudz ķēniņu kroņi, un vārds Viņam bija rakstīts, ko neviens nezināja, kā vien Viņš pats.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Un Viņš bija apģērbts ar drēbēm, kas bija asinīs mērktas, un Viņa vārds tapa saukts Dieva vārds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Un Tam gāja pakaļ tie debes\' karaspēki uz baltiem zirgiem, apģērbti ar baltu un šķīstu dārgu audekli.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Un no Viņa mutes iziet ass zobens, ar to sist pagānus; un Viņš tos ganīs ar dzelzs rīksti, un Viņš min Dieva, Tā Visuvarenā, bargās dusmības vīna spaidu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Un uz drēbēm un uz sāniem viņam ir tas vārds rakstīts: ķēniņu Ķēniņš un kungu Kungs!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Un es redzēju vienu eņģeli saulē stāvam, un tas sauca ar stipru balsi sacīdams uz visiem putniem, kas debess vidū skrien: nāciet un sapulcinājaties uz to lielo Dieva mielastu,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Ka jūs ēdat ķēniņu miesas, virsnieku miesas un vareno miesas un zirgu miesas un jājēju, kas uz tiem sēž, un visu svabadu un kalpu un mazu un lielu miesas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Un es redzēju to zvēru un tos ķēniņus virs zemes, un viņu sapulcinātos karaspēkus karojam pret To, kas uz tā zirga sēdēja, un pret Viņa kara spēku.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Un tas zvērs tapa sagrābts, un līdz ar to tas viltīgais pravietis, kas viņa priekšā tās zīmes bija darījis, caur ko viņš bija pievīlis tos, kas bija pieņēmuši tā zvēra zīmi, un tos, kas pielūdza viņa bildi: tie divi tapa dzīvi iemesti uguns zaņķī, kas deg ar sēru.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Un tie atlikušie tapa nokauti caur to zobenu, kas izgāja no mutes Tam, kas sēdēja uz tā zirga, un visi putni pieēdās no viņu miesām.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Un es redzēju eņģeli nokāpjam no debesīm, tam bija bezdibeņa atslēgas un lielas ķēdes savā rokā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Un viņš sagrāba to pūķi, to veco čūsku, tas ir velns un sātans, un to saistīja tūkstoš gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Un viņš to iemeta bezdibenī un aizslēdza un uzlika zieģeli virsū, ka tas tos ļaudis vairs nepieviltu, tiekams tūkstoš gadi būtu pabeigti, un pēc tiem viņam būs vaļā tapt mazu brīdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Un es redzēju goda krēslus, un uz tiem apsēdās, un šiem tapa dots tiesu spriest, un es redzēju to dvēseles, kam Jēzus liecības un Dieva vārda dēļ galva bija nocirsta un kas nebija pielūguši nedz to zvēru nedz viņa bildi un nebija pieņēmuši to zīmi pie savas pieres un pie savas rokas; un tie dzīvoja un valdīja līdz ar Kristu tūkstoš gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Bet tie citi mirušie netapa atkal dzīvi, tiekams tūkstoš gadi bija pabeigti; šī ir tā pirmā augšāmcelšanās.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Svētīgs un svēts, kam ir daļa pie tās pirmās augšāmcelšanās! Par šiem tai otrai nāvei varas nav, bet tie būs Dieva un Kristus priesteri un valdīs līdz ar Viņu tūkstoš gadus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Un kad tie tūkstoš gadi būs pabeigti, tad sātans no sava cietuma taps atraisīts,');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Un izies vilt tās tautas, kas tanīs četros zemes stūros, to Gogu un Magogu, tos sapulcināt karā; šo pulks ir kā jūras smiltis.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Un tie nāca uz zemes klajumu un visapkārt apstāja to svēto lēģeri un to mīļo pilsētu, un uguns krita no Dieva no debess un tos aprija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Un velns, kas tos pievīla, tapa iemests tai uguns un sēra zaņķī, kur tas zvērs ir un tas viltīgais pravietis, un tie taps mocīti dienām naktīm mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Un es redzēju lielu baltu godības krēslu un To, kas uz tā sēdēja, no Viņa vaiga zeme un debess bēga, un vieta tiem netapa atrasta.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Un es redzēju tos mirušos, mazos un lielos stāvam Dieva priekšā, un tās grāmatas tapa atvērtas; un cita grāmata tapa atvērta, kas ir tā dzīvības grāmata. Un tie mirušie tapa tiesāti pēc tiem rakstiem tais grāmatās, pēc viņu darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Un jūra deva tos mirušos, kas iekš tās bija, un nāve un elle deva tos mirušos, kas iekš tām bija, un ikviens tapa tiesāts pēc saviem darbiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Un nāve un elle tapa iemestas uguns zaņķī: šī ir tā otrā nāve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Un ja kas netapa atrasts tai dzīvības grāmatā rakstīts, tas tapa iemests uguns zaņķī.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Un es redzēju jaunu debesi un jaunu zemi; jo tā pirmā debess un tā pirmā zeme bija zudušas, un jūra vairs nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Un es, Jānis, redzēju to svēto pilsētu, to jauno Jeruzālemi, no Dieva nokāpjam no debesīm, sataisītu kā savam vīram izgreznotu brūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Un es dzirdēju lielu balsi no debesīm sakām: redzi, tas Dieva dzīvoklis pie cilvēkiem, un Viņš mājos pie tiem un tie būs Viņa ļaudis, un Dievs pats būs pie tiem, viņiem par Dievu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Un Dievs nožāvēs visas asaras no viņu acīm un nāve vairs nebūs, nedz bēdas, nedz brēkšana, nedz raizes vairs nebūs; jo tās pirmās lietas ir pagājušas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Un kas uz tā godības krēsla sēdēja, sacīja: redzi, visu es daru jaunu. Un Viņš uz mani saka: raksti! Jo šie vārdi ir uzticami un patiesīgi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Un Viņš uz mani sacīja: tas ir noticis. Es esmu Tas A(Alfa) un Tas O(Omega), Tas Iesākums un Tas Gals. Es tam iztvīkušam došu no dzīvības ūdens avota bez maksas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kas uzvar, tam būs iemantot visas lietas, un Es būšu viņa Dievs, un viņš būs Mans dēls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Bet tiem bailīgiem un neticīgiem un negantiem un slepkavām un mauciniekiem un burvjiem un elku kalpiem un visiem melkuļiem būs sava daļa tai zaņķī, kas deg ar uguni un sēru; tā ir tā otrā nāve.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Un pie manis nāca viens no tiem septiņiem eņģeļiem, kam tie septiņi kausi bija, pildīti ar tām septiņām pēdīgām mocībām, un runāja ar mani sacīdams: nāc šurp! Es tev rādīšu to sievu, Tā Jēra brūti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Un viņš mani garā noveda uz lielu un augstu kalnu un man rādīja to lielo pilsētu, to svēto Jeruzālemi, kas no debesīm nokāpa no Dieva.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Un tai bija Dieva godība. Un viņas spožums bija tam visdārgākam akmenim līdzīgs, tā kā jaspisa akmens, kas spīd kā kristāls.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Un tai bija liels un augsts mūris ar divpadsmit vārtiem, un uz tiem vārtiem bija divpadsmit eņģeļi, un vārdi bija virsū rakstīti, kas ir tie divpadsmit Israēla bērnu cilšu vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'No austruma trīs vārti, no ziemeļa puses trīs vārti, no dienasvidus puses trīs vārti, no vakara puses trīs vārti.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Un pilsētas mūrim bija divpadsmit pamati un uz tiem Tā Jēra divpadsmit apustuļu vārdi.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Un kas ar mani runāja, tam bija zelta kārts, ka tas to pilsētu mērotu un viņas vārtus un viņas mūrus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Un tā pilsēta bija četrstūrīga un bija tik gara, cik plata. Un viņš to pilsētu mēroja ar to kārti pie divpadsmit tūkstošiem birzumiem; viņas garums un platums un augstums bija it vienāds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Un viņš mēroja viņas mūri pie simts četrdesmit un četrām olektīm pēc cilvēka mēra, kas tam eņģelim bija.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Un viņas mūris bija uztaisīts no jaspisa; un tā pilsēta bija no skaidra zelta, kas skaidrai glāzei bija līdzīgs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Un pilsētas mūra pamati bija izrotāti ar visādiem dārgiem akmeņiem; pirmais pamats bija jaspis, otrais safīrs, trešais kalķedons, ceturtais smaragds.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Piektais sardoniks, sestais sardis, septītais krizolits, astotais berils, devītais topāzis, desmitais krizoprazs, vienpadsmitais hiacints, divpadsmitais ametists.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Un tie divpadsmit vārti bija divpadsmit pērles, un ikvieni vārti bija no vienas pērles, un pilsētas ielas bija skaidrs zelts tā kā skaidra glāze.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Un es neredzēju nevienu Dieva namu iekš tās, jo Tas Kungs, tas visu valdītājs Dievs, ir viņas nams un Tas Jērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Un tai pilsētai saules nevajag nedz mēneša, ka tie tur spīdētu, jo Dieva godība to apgaismo, un viņas gaišums ir Tas Jērs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Un tautas staigās viņas gaišumā, un ķēniņi virs zemes savu godu un slavu nesīs tur iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Un viņas vārti netaps aizslēgti dienā, jo nakts tur nav.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Un tautu godu un slavu tur nesīs iekšā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Un tur neieies neviens, kas ir apgānīts un negantību dara un melus, bet tie vien, kas ir rakstīti Tā Jēra dzīvības grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Un viņš man rādīja dzīvības ūdens upi, skaidru kā kristālu, iztekam no Dieva un Tā Jēra godības krēsla.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Viņas ielas vidū un pa abējām upes pusēm bija tas dzīvības koks, kas nesa divpadsmit reiz augļus, ikvienā mēnesī savu augli, un tā koka lapas ir tautām par dziedināšanu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Un nekāda nolādēta vairs nebūs, un Dieva un Tā Jēra godības krēsls būs tur iekšā, un Viņa kalpi Viņam kalpos');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Un redzēs Viņa vaigu, un Viņa Vārds būs pie viņu pieres.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Un tur nakts nebūs, un tiem nevajadzēs nedz uguns nedz saules gaišuma; jo Tas Kungs Dievs tos apgaismo. Un tie valdīs mūžīgi mūžam.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Un viņš uz mani sacīja: šie vārdi ir uzticami un patiesīgi. Un Tas Kungs, to svēto praviešu Dievs, Savu eņģeli ir sūtījis Saviem kalpiem to rādīt, kam būs notikt īsā laikā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '“Redzi, Es nāku drīz. Svētīgs ir tas, kas tur tos praviešu vārdus, kas šinī grāmatā.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Un es, Jānis, tas esmu, kas šīs lietas redzējis un dzirdējis. Un kad es biju redzējis un dzirdējis, tad es metos zemē pielūgt priekš tā eņģeļa kājām, kas man šīs lietas rādīja.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Un viņš uz mani saka: raugi, nedari to! Jo es esmu tavs un tavu brāļu, to praviešu, darba biedrs, un to, kas šīs grāmatas vārdus tur. Pielūdz Dievu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Un viņš uz mani saka: neaizzieģelē tos praviešu vārdus, kas šinī grāmatā, jo tas laiks ir tuvu.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kas netaisnību dara, tas lai joprojām netaisnību dara, un kas ir apgānīts, tas lai joprojām ir apgānīts, un kas ir taisns, tas lai joprojām ir taisns, un kas ir svēts, tas lai joprojām ir svēts.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '“Un redzi, Es nāku drīz, un Mana alga līdz ar Mani, ikvienam atmaksāt, kā viņa darbs būs.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Es esmu Tas A(Alfa) un Tas O(Omega), Tas Pirmais un Tas Pēdīgais, Tas Iesākums un Tas Gals.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Svētīgi ir tie, kas Viņa baušļus dara, lai viņiem vara(tiesības) ir pie tā dzīvības koka, un lai viņi ieiet pa tiem pilsētas vārtiem.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Bet ārā ir tie suņi un tie burvji un tie maucinieki un tie slepkavas un tie elku kalpi un ikviens, kas mīl un dara melus.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, '“Es, Jēzus, Savu eņģeli esmu sūtījis, jums šo apliecināt priekš tām Dieva draudzēm. Es esmu Dāvida sakne un dzimums, tā spožā Rīta Zvaigzne.”');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Un Tas Gars un tā brūte saka: nāc! Un kas to dzird, tas lai saka: nāc! Un kam slāpst, tas lai nāk, un kam gribās, tas lai ņem to dzīvības ūdeni bez maksas.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Jo es apliecināju visiem, kas dzird tos praviešu vārdus, kas šinī grāmatā: ja kas pie šiem ko pieliek, tad Dievs pieliks viņam tās mocības, kas ir rakstītas šinī grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Un ja kas ko atņem no tiem praviešu vārdiem, kas šinī grāmatā, tad Dievs atņems viņa daļu no tās dzīvības grāmatas un no tās svētās pilsētas un no tā, kas ir rakstīts šinī grāmatā.');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Kas to apliecina, Tas saka: Tiešām, Es nāku drīz! Āmen. Tiešām, nāc, Kungs Jēzu!');
INSERT INTO `LvGluck8_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Mūsu Kunga Jēzus Kristus žēlastība lai ir ar jums visiem! Āmen.');
